CREATE PROCEDURE CD_DB_Tables_Size
AS 

DECLARE objects_cursor CURSOR LOCAL FAST_FORWARD READ_ONLY for
      SELECT s.name + '.' + o.name from sys.schemas s
      INNER JOIN sys.objects o
      ON o.schema_id = s.schema_id
      WHERE
            o.type = 'S' or --Tablas de sistema
            o.type = 'U' or --Tablas de usuario
            o.type = 'V' or --Vistas (solo las indexadas devuelven tama±o)
            o.type = 'SQ' or --Cola de servicio
            o.type = 'IT' -- Tablas internas usadas p.e. por el Service Broker o los indices XML--Tabla temporal para albergar los resultados

CREATE TABLE #results
      (name SYSNAME, rows CHAR(11),
      reserved VARCHAR(18), data VARCHAR(18),
      index_size VARCHAR(18),Unused VARCHAR(18))


DECLARE @object_name AS SYSNAME
OPEN objects_cursor
FETCH NEXT FROM objects_cursor INTO @object_name;
WHILE @@FETCH_STATUS = 0
BEGIN
      INSERT INTO #results EXEC sp_spaceused @object_name
      FETCH NEXT FROM objects_cursor INTO @object_name;    
END;
CLOSE objects_cursor;
DEALLOCATE objects_cursor;


UPDATE
  #results
SET
  reserved = LEFT(reserved,LEN(reserved)-3),
  data = LEFT(data,LEN(data)-3),
  index_size = LEFT(index_size,LEN(index_size)-3),
  Unused = LEFT(Unused,LEN(Unused)-3)


SELECT
  Name,
  reserved AS [Tama±o en Disco (KB)],
  data AS [Datos (KB)],
  index_size AS [Indices (KB)],
  Unused AS [No usado (KB)],
  Rows AS Filas FROM #results
ORDER BY
  CONVERT(bigint, reserved) DESC


DROP TABLE #results
GO



CREATE   VIEW CD_Personas AS
SELECT CAST(C.Id_Cliente AS CHAR(20)) AS Id_Persona
,CAST(C.Id_Cliente AS CHAR(20)) AS Id_Usuario1
,CAST('' AS CHAR(20)) AS Id_Usuario2
,C.Razon_Social AS Persona
,CAST('' AS CHAR(20)) AS Legajo
,C.Doc_Nro AS Doc_Nro
,C.Sexo AS Sexo
,CAST(C.Foto AS VARCHAR(254))AS Foto
,C.Fecha_Ven_Trib AS Fecha_Taf
,O.Fecha_Desde AS Desde
,O.Fecha_Hasta AS Hasta
FROM Clientes C, Contratos O
WHERE O.Id_Cliente = C.Id_Cliente
AND C.Activo = 1
AND O.Activo = 1
GO


CREATE FUNCTION dbo.CFJ_Cbtes_Items_Calcular(@pJson VARCHAR(8000)) 
RETURNS VARCHAR(8000)
AS
BEGIN
DECLARE @rtaJson VARCHAR(8000)

/*Variables recibidas por parámetro a traves del JSON*/
DECLARE @pId_Cliente				INT
DECLARE @pId_Lista_Precio			SMALLINT
DECLARE @pId_Producto				VARCHAR(14)
DECLARE @Cantidad					DECIMAL(15,5)
DECLARE @Fecha_QA					DATETIME
DECLARE @Fecha_Venc					DATETIME
DECLARE @Id_Moneda					CHAR(3)

SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Lista_Precio			= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Lista_Precio')), 0)
SET @pId_Producto				= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), '')
SET @Cantidad					= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Cantidad')), 0)
SET @Fecha_QA					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_QA')), 0)
SET @Fecha_Venc					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Venc')), 0)
SET @Id_Moneda					= ISNULL(CONVERT(CHAR(3),  dbo.CF_JSON_VALUE(@pJson,'Id_Moneda')), 'PES')
/*FIN Variables recibidas por parámetro a traves del JSON*/

/*Variables Locales*/
DECLARE @Precio					DECIMAL(15,5)
DECLARE @Bonif					DECIMAL(5,2)
DECLARE @Precio_Grav			DECIMAL(15,5)
DECLARE @Precio_Exen			DECIMAL(15,5)
DECLARE @Cantidad_Equiv			DECIMAL(15,5)
DECLARE @Imp_Gravado			DECIMAL(12,2)
DECLARE @Imp_Exento				DECIMAL(12,2)
DECLARE @Imp_Final				DECIMAL(15,5)
DECLARE @Imp_Iva				DECIMAL(12,2)
DECLARE @Porc_Iva				DECIMAL(5,2)
DECLARE @Id_Iva					CHAR(3)
/*FIN Variables Locales*/

SET @Precio = 0
SET @Bonif	= 0

IF(@pId_Producto = '')
BEGIN
	SET @Precio = 0
END
ELSE
BEGIN
	/*Precio en Lista Precios*/
	IF(@pId_Lista_Precio <> 0)
	BEGIN

		SELECT 
		@Precio		= ISNULL(Precio, 0),
		@Bonif		= ISNULL(Bonificacion, 0)
		FROM Prod_Listas_Precios_Items 
		WHERE 
		Id_Producto = @pId_Producto 
		AND Id_Lista_Precio = @pId_Lista_Precio

		IF(@Bonif <> 0)
		BEGIN
			SET @Precio = @Precio * ((100 - @Bonif) / 100)
		END
		
	END

	IF(@Precio = 0)
	BEGIN
		/*Precio en Producto*/
		SET @Precio			= ISNULL((SELECT ISNULL(Precio_Final, 0) FROM Productos WHERE Id_Producto = @pId_Producto), 0)
	END
END

/*=====================================================================================================================*/

/*Tasa de IVA*/
SET @Precio_Grav = @Precio

SELECT
@Id_Iva		= ISNULL(PR.Id_Iva, ''), 
@Porc_Iva	= ISNULL(Porc1, 0)
FROM Productos PR, Productos_TasaIva PRI
WHERE
PR.Id_Producto = @pId_Producto
AND ISNULL(PR.Id_Iva, '') = PRI.Id_Iva

IF(@Porc_Iva <> 0)
BEGIN
	SET @Precio_Grav = @Precio * (1 + (@Porc_Iva/100))
END

/*=====================================================================================================================*/

SET @rtaJson		=	'{' +
						dbo.CF_Json_ParsearVariable('Precio', @Precio, 'DECIMAL') + ',' +
						dbo.CF_Json_ParsearVariable('Bonif', @Bonif, 'DECIMAL') + ',' +
						dbo.CF_Json_ParsearVariable('Porc_Iva', @Porc_Iva, 'DECIMAL') + ',' +
						dbo.CF_Json_ParsearVariable('Precio_Grav', @Precio_Grav, 'DECIMAL') + 						
						'}'

   RETURN ISNULL(@rtaJson, 0)
END
GO


