CREATE FUNCTION dbo.CFJ_Contratos_Periodo_Validar(@pJsonRecibido VARCHAR(8000))
RETURNS INT
AS
BEGIN
DECLARE @Id_Contrato_En_Periodo		INT

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pId_Usuario			SMALLINT
DECLARE @pId_Cliente			INT
DECLARE @pId_Producto			VARCHAR(14)
DECLARE @pId_Contrato_A_Excluir INT
DECLARE @pFecha_Desde			DATETIME
DECLARE @pFecha_Hasta			DATETIME

SET @pId_Usuario				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Usuario')), 0)
SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')), 0)
SET @pId_Producto				= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Producto')), '')
SET @pId_Contrato_A_Excluir		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Contrato')), 0)


DECLARE @sFecha_Desde			VARCHAR(20)

DECLARE @sFecha_Hasta			VARCHAR(20)



SET @sFecha_Desde = NULLIF(LTRIM(RTRIM(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Desde')))), '')

SET @sFecha_Hasta = NULLIF(LTRIM(RTRIM(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Hasta')))), '')



SET @pFecha_Desde = CASE 

                        WHEN @sFecha_Desde IS NULL THEN GETDATE()

                        WHEN ISDATE(@sFecha_Desde) = 1 THEN CONVERT(DATETIME, @sFecha_Desde)

                        ELSE GETDATE()

                    END



SET @pFecha_Hasta = CASE 

                        WHEN @sFecha_Hasta IS NULL THEN GETDATE()

                        WHEN ISDATE(@sFecha_Hasta) = 1 THEN CONVERT(DATETIME, @sFecha_Hasta)

                        ELSE GETDATE()

                    END


/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable Locales*/

/*FIN Variable Locales*/


SET @Id_Contrato_En_Periodo = ISNULL((SELECT MIN(CT.Id_Contrato) 
										FROM Contratos CT JOIN Contratos_Prod CP ON CT.Id_Contrato = CP.Id_Contrato
										WHERE CT.Activo =1
										AND CT.Id_Contrato <> @pId_Contrato_A_Excluir
										AND CT.Id_Cliente = @pId_Cliente
										AND CP.Id_Producto = @pId_Producto
										AND @pFecha_Desde <= ISNULL(CT.Fecha_Hasta,@pFecha_Desde)
										AND @pFecha_Hasta >= CT.Fecha_Desde
										)
									, 0)


RETURN ISNULL(@Id_Contrato_En_Periodo, 0)
END


/*

SELECT dbo.CFJ_Contratos_Periodo_Validar('{"Id_Cliente":"89115","Id_Producto":"P0273","Fecha_Desde":"20190101","Fecha_Hasta":"20190124"')	

*/
GO


CREATE FUNCTION [dbo].[CFJ_Credencial_QR](@pJson VARCHAR(8000))
RETURNS VARCHAR(2048)
AS
BEGIN
DECLARE @Json_Respuesta		VARCHAR(2048)

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFormato			VARCHAR(20)
DECLARE @pId_Cliente		INT

SET @pFormato		= UPPER(LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Formato')), ''))))
SET @pId_Cliente	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables locales*/
DECLARE @Formato				VARCHAR(20)
DECLARE @Valor					VARCHAR(2048)
DECLARE @pJson_QR_Dinamico		VARCHAR(8000)
DECLARE @Json_QR_Dinamico		VARCHAR(8000)
/*FIN Variables locales*/

--===========================================================================================

-- Formato: el recibido por par├ímetro, o si no vino, el configurado en los seteos del cliente (club). Default: DNI
SET @Formato = @pFormato

IF(@Formato NOT IN ('DNI', 'NRO_SOCIO', 'QR_DINAMICO'))
BEGIN
	SET @Formato = UPPER(LTRIM(RTRIM(ISNULL(dbo.CF_xParam('Credencial_QR_Format'), ''))))
END

IF(@Formato NOT IN ('DNI', 'NRO_SOCIO', 'QR_DINAMICO'))
BEGIN
	SET @Formato = 'DNI'
END

--===========================================================================================

IF(@Formato = 'DNI')
BEGIN
	SELECT @Valor = LTRIM(RTRIM(ISNULL(Doc_Nro, ''))) FROM Clientes WHERE Id_Cliente = @pId_Cliente
END

IF(@Formato = 'NRO_SOCIO')
BEGIN
	SELECT @Valor = LTRIM(RTRIM(ISNULL(Id_Cliente_Externo, ''))) FROM Clientes WHERE Id_Cliente = @pId_Cliente
END

IF(@Formato = 'QR_DINAMICO')
BEGIN
	SET @pJson_QR_Dinamico =	'{' +
								dbo.CF_Json_ParsearVariable('Id_Cliente', @pId_Cliente, 'INT') + ',' +
								dbo.CF_Json_ParsearVariable('Formato', 'N', 'VARCHAR(1)') +
								'}'

	SET @Json_QR_Dinamico = dbo.CFJ_SCA_QR_Dinamico_Generar(@pJson_QR_Dinamico)

	SET @Valor = dbo.CF_JSON_VALUE(@Json_QR_Dinamico, 'url')
END

--===========================================================================================

SET @Json_Respuesta =	'{' +
						dbo.CF_Json_ParsearVariable('Formato', @Formato, 'VARCHAR(20)') + ',' +
						dbo.CF_Json_ParsearVariable('Valor', @Valor, 'VARCHAR(2048)') +
						'}'

RETURN ISNULL(@Json_Respuesta, '')
END
GO


CREATE FUNCTION [dbo].[CFJ_Menu_Favorito](@pJson VARCHAR(8000))
RETURNS SMALLINT
AS
BEGIN

DECLARE @pUsuario INT
DECLARE @pMenu INT
DECLARE @pModulo INT
DECLARE @Favorito INT

SET @pUsuario = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), 0)
SET @pMenu = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Menu')), 0)
SET @pModulo = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Modulo')), 0)

SET @Favorito = (SELECT 
	Id_Favorito 
	FROM Seg_User_Fav 
	WHERE Id_Usuario = @pUsuario AND Id_Menu = @pMenu AND Id_Modulo = @pModulo
)


RETURN ISNULL(@Favorito, 0)
END



