CREATE FUNCTION [dbo].[CFJ_Producto_Facturado] (@pJson VARCHAR(8000))
RETURNS TINYINT
AS
BEGIN
	/*Variables recibidas por parámetro a traves del JSON*/
	DECLARE @pId_Cliente			INT
	DECLARE @pId_Producto			VARCHAR(14)
	DECLARE @pId_Tiempo				CHAR(3)
	DECLARE @pFecha					DATETIME
	DECLARE @pRefacturar			TINYINT
	DECLARE @pFlag_Tabla_Temp       TINYINT

	SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
	SET @pId_Producto				= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), '')
	SET @pId_Tiempo					= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Tiempo')), '')
	SET @pFecha						= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')),GETDATE())
	SET @pRefacturar				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Refacturar')), 0)
	SET @pFlag_Tabla_Temp		    = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Tabla_Temp')), 0)

	/*FIN Variables recibidas por parámetro a traves del JSON*/

	IF ISNULL(@pRefacturar,0) <> 0 RETURN 0    --se refacturo no controlo nada

	DECLARE @Cantidad		INT
	DECLARE @Tipo			CHAR(1)
	DECLARE @CantCiclos		INT
	DECLARE @Flag_Mes		TINYINT
	DECLARE @Flag_Periodo	TINYINT
	DECLARE @ReturnValue	INT

	SET @ReturnValue = 0

	IF @pFlag_Tabla_Temp = 1 AND OBJECT_ID (N'Z_CONTRATOS_FACTURADOS', N'U') IS NOT NULL 
	BEGIN
        SET @ReturnValue = (select count(*) from Z_CONTRATOS_FACTURADOS WHERE id_Cliente  = @pId_Cliente AND Id_Producto = @pId_Producto)
    END

	IF(ISNULL(@ReturnValue,0) = 0)
	BEGIN
    	IF ISNULL(@pId_Tiempo,'') <> ''   --por defecto se toma mensual
		BEGIN

			SELECT @Cantidad = Cantidad , @Tipo = Tipo FROM Tab_Uni_Tiempo WHERE Id_Tiempo = @pId_Tiempo
			IF ISNULL(@Cantidad,0) = 0 SET @Cantidad = 1

			IF @Tipo = 'A'
				SELECT @CantCiclos = ISNULL(  DATEDIFF(yy,MAX(i.Fecha_QA),@pFecha) ,9999999) 
						FROM Cbtes_Items i, Cbtes c , Cbtes_Tipos T 
						WHERE c.id_trans = i.id_trans 
								AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
								--AND ((c.Comprobante_Nro = 0 AND c.Id_Estado_Cbte = 3) OR c.Id_Estado_Cbte NOT IN (0,3))
								AND c.Id_Estado_Cbte NOT IN (0,3)
								AND (T.Compromete_Factura = 1 OR T.Compromete_Remitos = 1)
								AND I.Id_Cliente = @pId_Cliente
								AND i.Id_Producto = @pId_Producto
			ELSE IF @Tipo = 'D'
				SELECT @CantCiclos = ISNULL(  DATEDIFF(dd,MAX(i.Fecha_QA),@pFecha) ,9999999) 
						FROM Cbtes_Items i, Cbtes c , Cbtes_Tipos T 
						WHERE c.id_trans = i.id_trans 
								AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
								--AND ((c.Comprobante_Nro = 0 AND c.Id_Estado_Cbte = 3) OR c.Id_Estado_Cbte NOT IN (0,3))
								AND c.Id_Estado_Cbte NOT IN (0,3)
								AND (T.Compromete_Factura = 1 OR T.Compromete_Remitos = 1)
								AND I.Id_Cliente = @pId_Cliente
								AND i.Id_Producto = @pId_Producto	
			ELSE		
				SELECT @CantCiclos = ISNULL(  DATEDIFF(mm,MAX(i.Fecha_QA),@pFecha) ,9999999) 
						FROM Cbtes_Items i, Cbtes c , Cbtes_Tipos T 
						WHERE c.id_trans = i.id_trans 
								AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
								--AND ((c.Comprobante_Nro = 0 AND c.Id_Estado_Cbte = 3) OR c.Id_Estado_Cbte NOT IN (0,3))
								AND c.Id_Estado_Cbte NOT IN (0,3)
								AND (T.Compromete_Factura = 1 OR T.Compromete_Remitos = 1)
								AND I.Id_Cliente = @pId_Cliente
								AND i.Id_Producto = @pId_Producto	

			IF @CantCiclos < @Cantidad SET @ReturnValue = 1
		END
		ELSE   --IF ISNULL(@pId_Tiempo,'') <> ''   -
		BEGIN
			SELECT @Flag_Mes = Flag_Mes, @Flag_Periodo = Flag_Periodo FROM Productos WHERE Id_Producto = @pId_Producto

			IF @Flag_Mes = 1 OR @Flag_Periodo = 1
					SELECT  @ReturnValue = COUNT(*) FROM Cbtes_Items i, Cbtes c , Cbtes_Tipos T 
							WHERE c.id_trans = i.id_trans 
										AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
										--AND ((c.Comprobante_Nro = 0 AND c.Id_Estado_Cbte = 3) OR c.Id_Estado_Cbte NOT IN (0,3))
										AND c.Id_Estado_Cbte NOT IN (0,3)
										AND (T.Compromete_Factura = 1 OR T.Compromete_Remitos = 1)
										AND ISNULL(I.Id_Cliente,C.ID_CLIENTE) = @pId_Cliente
										AND i.Id_Producto = @pId_Producto
										AND DATEPART(yy,i.Fecha_QA) = DATEPART(yy,@pFecha) 
										AND DATEPART(mm,i.Fecha_QA) = DATEPART(mm,@pFecha) 
	
		END
    END

	RETURN ISNULL(@ReturnValue,0)
END
GO

CREATE FUNCTION [dbo].[CFJ_Producto_Fechas](@pJson VARCHAR(2048))
RETURNS VARCHAR(2048)
AS
BEGIN


/*Variables recibidas por par├ímetro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Producto			VARCHAR(14)
DECLARE @pFecha					DATETIME

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Producto				= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), '')
SET @pFecha						= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')), '19000101')
/*FIN Variables recibidas por par├ímetro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
declare @JSON varchar(2000)
DECLARE @Retorno VARCHAR(2048)
/*FIN Variable de Retorono del Stored*/

/*Variables Locales*/
DECLARE @Flag_Mes				INT 
DECLARE @Flag_Periodo			INT 
DECLARE @Flag_Periodo_Tipo		CHAR(1) 
DECLARE @Flag_Periodo_Hasta		DATETIME
DECLARE @Flag_Periodo_Desde		DATETIME
DECLARE @Flag_Periodo_Cant		SMALLINT

DECLARE @Fecha_Desde			DATE
DECLARE @Fecha_Hasta			DATE
/*FIN Variables Locales*/

/*=================================================================================*/
	/*
	 * PRIORIDADES:
	 * 
	 * 1) Flag Mes
	 * 2) Flag Periodo
	*/


	SELECT	@Flag_Mes			= Flag_Mes,
			@Flag_Periodo		= Flag_Periodo ,
			@Flag_Periodo_Tipo	= Flag_Periodo_Tipo,
			@Flag_Periodo_Hasta	= Flag_Periodo_Hasta,
			@Flag_Periodo_Desde = Flag_Periodo_Desde,
			@Flag_Periodo_Cant	= Flag_Periodo_Cant
	FROM Productos 
	WHERE Id_Producto=@pId_Producto

	/*=================================================================================*/
		SET @Fecha_Desde = CONVERT(DATE,GETDATE())
		SET @Fecha_Hasta = '19000101'

	IF (@Flag_Mes=1)
	BEGIN
		SET @Fecha_Hasta = DATEADD(month, 1, @Fecha_Desde)
	END 

	IF (@Flag_Periodo=1)
	BEGIN
		IF (@Flag_Periodo_Cant>=1)
		BEGIN
			IF(@Flag_Periodo_Tipo='D')
			BEGIN
				SET @Fecha_Hasta = DATEADD(day, @Flag_Periodo_Cant, @Fecha_Desde)
			END 

			IF(@Flag_Periodo_Tipo='M')
			BEGIN
				SET @Fecha_Hasta = DATEADD(MONTH, @Flag_Periodo_Cant, @Fecha_Desde)
			END 

			IF(@Flag_Periodo_Tipo='A')
			BEGIN
				SET @Fecha_Hasta = DATEADD(YEAR, @Flag_Periodo_Cant, @Fecha_Desde)
			END 

			IF(@Flag_Periodo_Tipo='F')
			BEGIN
				SET @Fecha_Desde = @Flag_Periodo_Desde
				SET @Fecha_Hasta = @Flag_Periodo_Hasta
			END 

		END 
	END 



	/*=================================================================================*/

SET @Retorno 		=	'{' +
								dbo.CF_Json_ParsearVariable('Id_Producto', @pId_Producto, 'VARCHAR(14)') + ',' + 
								dbo.CF_Json_ParsearVariable('Fecha_Desde', @Fecha_Desde, 'DATE') + ',' + 
								dbo.CF_Json_ParsearVariable('Fecha_Hasta', @Fecha_Hasta, 'DATE') + 
								'}'

RETURN @Retorno


END
GO


CREATE FUNCTION [dbo].[CFJ_Producto_Valida_Stock] (@pJson VARCHAR(8000))
RETURNS SMALLINT
AS
BEGIN
/*
 * LOG VERSIONES:
 * 07/12/2023: Se agrego Log de Versiones
 * Retorno: -1 = Producto sin stock | 0 = Producto NO valida Stock | >= 1 = Producto valida Stock (Cantidad) 
*/

/*Declaracion Variables Json*/
DECLARE @pId_Producto			VARCHAR(14)

SET @pId_Producto				= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), '')
/*Fin Declaracion Variables Json*/

/*Declaracion Variables Locales*/
DECLARE @ReturnValue	INT
DECLARE @Valida			SMALLINT
DECLARE @Cantidad		INT
/*Fin de Declaraciones Variables Locales*/

	SET @ReturnValue = 0

	SET @Valida = ISNULL((SELECT 1 FROM Productos 
							WHERE Estiba_Max > 0
							AND Maneja_Stock = 1
							AND Fraciona_Stk = 1
							AND Id_Producto = @pId_Producto), 0)

IF (@Valida >= 1 AND dbo.CF_xParam('Validar_Stk_Factura') = 1)
BEGIN

	SET @Cantidad =  ISNULL((SELECT SUM(isnull(I.Cantidad,0) * T.Compromete_Stock)
							 FROM Cbtes_Items I, Cbtes C, Cbtes_Tipos T 
							 WHERE I.Id_Trans = C.Id_Trans 
							 AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
							 AND C.Id_Estado_Cbte not in (0,3) 
							 AND I.Id_Estado_Cbte <> DBO.CF_xParam('EST_INIC_ITEMS_VMAT')
							 AND I.Flag_QA <> 'X'
							 AND T.Compromete_Stock in (1,-1) 
							 AND (I.Fecha_QA < dateadd(day,1,Fecha) OR I.Fecha_QA IS NULL )
							 AND I.Id_Producto = @pId_Producto), 0)

	IF (@Cantidad <= 0)
	BEGIN
		SET @ReturnValue = -1
	END
	ELSE
	BEGIN
		SET @ReturnValue = @Cantidad
	END
END


RETURN ISNULL(@ReturnValue, 0)
END
GO



CREATE FUNCTION [dbo].[CFJ_SCA_GenerarQR](@pJson VARCHAR(8000)) 
RETURNS VARCHAR(50)
AS
BEGIN
/*Variable Retorno*/
DECLARE @QR						VARCHAR(50)
/*FIN Variable Retorno*/

/*Variables recibidas por par├ímetro a traves del JSON*/
DECLARE @pId_Trans				INT
DECLARE @pItem					SMALLINT
DECLARE @pFormato				VARCHAR(10)

SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pItem						= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Item')), 0)
SET @pFormato					= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Formato')), '')
/*FIN Variables recibidas por par├ímetro a traves del JSON*/

/*Variables Locales*/
DECLARE @Evento_QR_Formato		VARCHAR(40)
DECLARE @Id_Lista_Precio		SMALLINT	
DECLARE @Id_Acceso				SMALLINT
DECLARE @Prox_Nro_Secuencial	INT
DECLARE @Cbtes_Id_Cliente		INT
DECLARE @Cbtes_Items_Id_Cliente	INT
DECLARE @Id_Producto			VARCHAR(14)
DECLARE @Doc_Nro				BIGINT
DECLARE @Nro_Ubic				VARCHAR(10)
DECLARE @Lote					VARCHAR(20)
/*FIN Variables Locales*/

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@pId_Trans = 0 OR @pItem = 0)
BEGIN
	SET @QR = ''
	RETURN @QR
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@pFormato <> '')
BEGIN
	SET @Evento_QR_Formato = @pFormato
END
ELSE
BEGIN
	SET @Evento_QR_Formato = dbo.CF_xParam('Evento_QR_Formato')
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

SELECT 
@Id_Lista_Precio			= ISNULL(Id_Lista, 0),
@Cbtes_Id_Cliente			= ISNULL(Id_Cliente, 0)
FROM Cbtes
WHERE
Id_Trans = @pId_Trans

SELECT
@Cbtes_Items_Id_Cliente		= ISNULL(Id_Cliente, 0),
@Id_Producto				= ISNULL(Id_Producto, ''),
@Lote						= ISNULL(Lote, '')
FROM Cbtes_Items
WHERE
Id_Trans = @pId_Trans
AND Item = @pItem

SELECT
@Doc_Nro					= ISNULL(Doc_Nro, 0)
FROM Clientes
WHERE
Id_Cliente = @Cbtes_Items_Id_Cliente

SELECT
@Nro_Ubic					= ISNULL(Nro_Ubic, '')
FROM Productos
WHERE
Id_Producto	= @Id_Producto

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@Evento_QR_Formato = 'DNI')
BEGIN
	SET @QR = CONVERT(VARCHAR(20), @Doc_Nro)

	RETURN @QR
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@Evento_QR_Formato = '14')
BEGIN
	SET @QR =	RIGHT('0000' + CAST(@Id_Lista_Precio AS VARCHAR), 4) + 
				RIGHT('000' + CAST(CAST(@Nro_Ubic AS INT) AS VARCHAR), 3) +
				RIGHT('0000000' + CAST(CAST(@Lote AS VARCHAR) AS VARCHAR), 7)

	RETURN @QR
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@Evento_QR_Formato = '43')
BEGIN
	SET @QR =	RIGHT('0000000000' + CAST(CAST(@Lote AS VARCHAR) AS VARCHAR), 10) +
				RIGHT('00000' + CAST(@Id_Lista_Precio AS VARCHAR), 5) + 
				RIGHT('000' + CAST(CAST(@Nro_Ubic AS INT) AS VARCHAR), 3) +
				RIGHT('0000000000' + CAST(@Cbtes_Items_Id_Cliente AS VARCHAR), 10) + 
				RIGHT('0000000000' + CAST(@pId_Trans AS VARCHAR), 10) + 
				RIGHT('00000' + CAST(@pItem AS VARCHAR), 5)

	RETURN @QR
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

RETURN ISNULL(@QR, '')
END

--SELECT DBO.CFJ_SCA_GenerarQR ('{"Id_trans":"5251414","Item":"1","Formato":"DNI"}')
GO


CREATE FUNCTION [dbo].[CFJ_SCA_QR_Dinamico_Generar](@pJson VARCHAR(8000))
RETURNS VARCHAR(2048)
AS
BEGIN
DECLARE @Json_Respuesta		VARCHAR(8000)

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pId_Cliente		INT
DECLARE @pId_Producto		VARCHAR(14)
DECLARE @pFecha_Desde		DATETIME
DECLARE @pFecha_Hasta		DATETIME
DECLARE @pId_Lista_Precio	SMALLINT
DECLARE @pToken				VARCHAR(256)
DECLARE @pApp				VARCHAR(256) --App:CleverSCA
DECLARE @pFormato			VARCHAR(1)

SET @pId_Cliente		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Producto		= UPPER(LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), ''))))
SET @pFecha_Desde		= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde')), '19000101')
SET @pFecha_Hasta		= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta')), '19000101')
SET @pId_Lista_Precio	= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Lista_Precio')), 0)
SET @pToken				= LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(256), dbo.CF_JSON_VALUE(@pJson,'Token')), '')))
SET @pFormato			= ISNULL(CONVERT(VARCHAR(1), dbo.CF_JSON_VALUE(@pJson,'Formato')), 'A')
/*FIN Variables recibidas por parametro a traves del JSON*/


/*Variables locales*/
DECLARE @Respuesta				VARCHAR(8000) 
DECLARE @Token					VARCHAR(256)
DECLARE @Flag_Existe_Token		TINYINT
DECLARE @url					VARCHAR(2048)
DECLARE @cant_usos_permitidos	INT
DECLARE @fecha_desde			DATETIME
DECLARE @fecha_hasta			DATETIME
/*FIN Variables locales*/

--===========================================================================================

IF(dbo.CF_xParam('QR_Dinamico') = 1)
BEGIN

	IF EXISTS ( SELECT * FROM sysobjects WHERE id = object_id(N'dbo.CFJ_SCA_QR_Dinamico_Generar_') AND type = 'FN')
	BEGIN
		SET @Respuesta = (dbo.CFJ_SCA_QR_Dinamico_Generar_(@pJson))
		RETURN ISNULL(@Respuesta, '')
	END


--===========================================================================================

-------------------------------------------------------------------------------------------------------------------------------------
/*
VERSIONES:
02/08/2022 Se agrega parametro @pFormato
*/
-------------------------------------------------------------------------------------------------------------------------------------

IF(@pFormato = 'A')
BEGIN
	SET @url = (dbo.CF_xParam('API_Url'))

	SET @url = @url + 'index.php'

	SET @url = @url + '?acs_qr=1'

	IF(@pToken = '')
	BEGIN		
		--SET @Token = (dbo.CF_Token(32))
		SET @Token = (dbo.CF_Clientes_Links_Token('A',32))	
	END
	ELSE
	BEGIN
		SET @Token = @pToken
	END

	SET @url = @url + '&token=' + @Token

	IF(@pId_Producto <> '')
	BEGIN
		SET @url = @url + '&id_producto=' + @pId_Producto
	END

	IF(@pId_Lista_Precio > 0)
	BEGIN
		SET @url = @url + '&id_lista_precio=' + @pId_Lista_Precio
	END
END

IF(@pFormato = 'N')
BEGIN
	SET @Token = dbo.CF_Clientes_Links_Token(@pFormato, 10)
	
	SET @url	= @Token
END

-------------------------------------------------------------------------------------------------------------------

IF(@pFecha_Desde > '19000101' AND @pFecha_Hasta > '19000101')
BEGIN
	SET @fecha_desde = @pFecha_Desde
	SET @fecha_hasta = @pFecha_Hasta
END
ELSE
BEGIN
	SET @fecha_desde = GETDATE()
	SET @fecha_hasta = DATEADD(MINUTE, 3, GETDATE())
END

-------------------------------------------------------------------------------------------------------------------

SET @cant_usos_permitidos = 1

-------------------------------------------------------------------------------------------------------------------

	SET @Json_Respuesta =	'{' +
							dbo.CF_Json_ParsearVariable('url', @url, 'VARCHAR(2048)') + ',' +
							dbo.CF_Json_ParsearVariable('token', @token, 'VARCHAR(256)') + ',' + 
							dbo.CF_Json_ParsearVariable('cant_usos_permitidos', @cant_usos_permitidos, 'INT') + ',' + 
							dbo.CF_Json_ParsearVariable('fecha_desde', @fecha_desde, 'DATETIME') + ',' + 
							dbo.CF_Json_ParsearVariable('fecha_hasta', @fecha_hasta, 'DATETIME') + 
							'}'
END
	RETURN ISNULL(@Json_Respuesta, '')
END

