CREATE FUNCTION [dbo].[z_CFUJ_Contrato_Cli_Hab](@pJson VARCHAR(8000))
RETURNS VARCHAR(8000)
AS
BEGIN

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pId_Cliente		INT
DECLARE @pId_Familia		INT
DECLARE @pId_Producto		VARCHAR(14)
DECLARE @pObservacion		TINYINT


SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Familia			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Familia')), 0)
SET @pId_Producto			= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), '')
SET @pObservacion			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Observacion')), 0)

/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Respuesta			VARCHAR(8000)
DECLARE @Observacion		VARCHAR(8000) = ''

DECLARE @Inscripto			TINYINT
DECLARE @Existe_Contrato    TINYINT
/*FIN Variables Locales*/


--==========================================================================================
/*IMPLEMENTAR*/
--==========================================================================================

-- Ticket #011090
-- Si el socio esta inscripto en el torneo de futbol (contrato cod. 12), si está inscripto paga el producto 2500, sino paga el 2503
SET @pId_Familia = ISNULL((SELECT TOP 1 Id_Familia FROM Productos WHERE Id_Producto = @pId_Producto),0)

IF (@pId_Familia = 48 /*CFF CENTRO DE FORMACION DE FUTBOL*/)
BEGIN
    SET @Inscripto = ISNULL((SELECT TOP 1 1 
                             FROM Contratos 
                             WHERE Activo = 1 
                               AND Fecha_Hasta >= GETDATE() 
                               AND Id_Tipo_Con = 12 
                               AND Id_Cliente = @pId_Cliente), 0)

    IF (@Inscripto = 0 AND @pId_Producto = '2500')
    BEGIN
        SET @Respuesta = '0'
	END
	
    IF (@Inscripto = 1 AND @pId_Producto = '2503') 
    BEGIN
        SET @Respuesta = '0'
    END
END

---------------------------------------------------------------------------------------
/*
/*INSTITUTO*/
declare @Id_Tipo_Cli int
--SET @pId_Familia = ISNULL((SELECT TOP 1 Id_Familia FROM Productos WHERE Id_Producto = @pId_Producto),0)
SET @Id_Tipo_Cli = ISNULL((SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @pId_Cliente),0)

IF(@Id_Tipo_Cli = 1127)
BEGIN

		SET @Existe_Contrato = ISNULL((SELECT TOP 1 1 
								 FROM Contratos 
								 WHERE Activo = 1 
								   AND ISNULL(Fecha_Hasta,GETDATE()+1) >= GETDATE() 
								   AND Id_Tipo_Con = 1 
								   AND Id_Cliente = @pId_Cliente), 0)
		IF (@Existe_Contrato = 1)
		BEGIN
			IF(@pId_Familia = 62)
			BEGIN
				SET @Respuesta = 0
				RETURN @Respuesta
			END

		END

		IF(@pId_Familia = 4)
			BEGIN
				SET @Respuesta = 0
				RETURN @Respuesta
			END
END

*/

/*INSTITUTO validaciones de Matricula 1195 se agrega esta validacion por pedido tk# 013736 23/03/2026*/

/*no permitir duplicar pago de matricula tk#013736 */
IF (@pId_Cliente > 0 AND @pId_Producto = '1196')
BEGIN
    IF EXISTS (
        SELECT 1
        FROM Cbtes C
        INNER JOIN Cbtes_items I ON C.id_trans = I.id_trans
        INNER JOIN Cbtes_tipos CT ON C.id_tipo_cbte = CT.id_tipo_cbte
        WHERE I.id_producto = '1196'
          AND I.id_cliente = @pId_Cliente
          AND C.id_estado_cbte = 2
          AND CT.compromete_factura = 1
          AND DATEPART(YY, I.Fecha_QA) = 2026
    )
    BEGIN
        IF (@pObservacion = 1)
        BEGIN
            SET @Observacion = 'La matrícula ya se encuentra paga'
        END

          SET @Respuesta = 0;
            RETURN ISNULL(@Observacion, @Respuesta)
    END
END

IF (@pId_Cliente > 0 
    AND @pId_Producto IN (
        '1185','1186','1187','1188','1189','1190','1191','1192',
        '1193','1194'/*,'1195',*/
    ))
BEGIN
	DECLARE @TieneMatriculaPagada INT = 0;

    -- Validar matrícula paga (producto 1195 SIN deuda)
    SELECT @TieneMatriculaPagada = COUNT(*)
    FROM Cbtes C
    INNER JOIN Cbtes_items I ON C.id_trans = I.id_trans
    INNER JOIN Cbtes_tipos CT ON C.id_tipo_cbte = CT.id_tipo_cbte
    WHERE I.id_producto IN ('1195','1196')
      AND I.id_cliente = @pId_Cliente
      AND C.id_estado_cbte =2       -- NO impago → está paga
      AND CT.compromete_factura = 1
	  AND DATEPART(YY,I.Fecha_QA)='2026'

    -- Si NO tiene matrícula paga → cortar
    IF (@TieneMatriculaPagada = 0)
    BEGIN
        IF(@pObservacion = 1)
        BEGIN
            SET @Observacion = 'Debe abonar la Matrícula antes de continuar'
        END

        SET @Respuesta = 0;
    END
	ELSE
	BEGIN
		SET @Respuesta = 1; -- OK Con Matricula Paga

		SELECT @Respuesta = COUNT(*)
		FROM Cbtes C
		INNER JOIN Cbtes_items I ON C.id_trans = I.id_trans
		INNER JOIN Productos P ON I.id_producto = P.id_producto
		INNER JOIN Cbtes_tipos CT ON C.id_tipo_cbte = CT.id_tipo_cbte
		WHERE P.id_familia = 4            -- productos del instituto
		  AND C.id_estado_cbte = 1        -- impago
		  AND CT.compromete_factura = 1   -- genera deuda
		  AND I.id_cliente = @pId_Cliente;

		IF @Respuesta >= 1
		BEGIN
			IF(@pObservacion = 1)
			BEGIN
				SET @Observacion = 'Posee Deuda de Instituto'
			END
			SET @Respuesta = 0;
		END
		ELSE
		BEGIN
			SET @Respuesta = 1; -- OK sin deuda
		END
	END
END



IF(@pObservacion = 1)
BEGIN
    RETURN ISNULL(@Observacion, '')
END

-----------------------------------------------------------------------------------------
RETURN ISNULL(@Respuesta,'1')
END

---------------------------------------------------------------------------------------------
GO


CREATE FUNCTION [dbo].[CFUJ_Contrato_Cli_Hab](@pJson VARCHAR(8000))
RETURNS VARCHAR(8000)
AS
BEGIN

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pId_Cliente		INT
DECLARE @pId_Familia		INT
DECLARE @pId_Producto		VARCHAR(14)
DECLARE @pObservacion		TINYINT


SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Familia			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Familia')), 0)
SET @pId_Producto			= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), '')
SET @pObservacion			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Observacion')), 0)

/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Respuesta			VARCHAR(8000)
DECLARE @Observacion		VARCHAR(8000) = ''

DECLARE @Inscripto			TINYINT
DECLARE @Existe_Contrato    TINYINT
/*FIN Variables Locales*/


--==========================================================================================
/*IMPLEMENTAR*/
--==========================================================================================

-- Ticket #011090
-- Si el socio esta inscripto en el torneo de futbol (contrato cod. 12), si está inscripto paga el producto 2500, sino paga el 2503
SET @pId_Familia = ISNULL((SELECT TOP 1 Id_Familia FROM Productos WHERE Id_Producto = @pId_Producto),0)

IF (@pId_Familia = 48 /*CFF CENTRO DE FORMACION DE FUTBOL*/)
BEGIN
    SET @Inscripto = ISNULL((SELECT TOP 1 1 
                             FROM Contratos 
                             WHERE Activo = 1 
                               AND Fecha_Hasta >= GETDATE() 
                               AND Id_Tipo_Con = 12 
                               AND Id_Cliente = @pId_Cliente), 0)

    IF (@Inscripto = 0 AND @pId_Producto = '2500')
    BEGIN
        SET @Respuesta = '0'
	END
	
    IF (@Inscripto = 1 AND @pId_Producto = '2503') 
    BEGIN
        SET @Respuesta = '0'
    END
END

---------------------------------------------------------------------------------------
/*
/*INSTITUTO*/
declare @Id_Tipo_Cli int
--SET @pId_Familia = ISNULL((SELECT TOP 1 Id_Familia FROM Productos WHERE Id_Producto = @pId_Producto),0)
SET @Id_Tipo_Cli = ISNULL((SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @pId_Cliente),0)

IF(@Id_Tipo_Cli = 1127)
BEGIN

		SET @Existe_Contrato = ISNULL((SELECT TOP 1 1 
								 FROM Contratos 
								 WHERE Activo = 1 
								   AND ISNULL(Fecha_Hasta,GETDATE()+1) >= GETDATE() 
								   AND Id_Tipo_Con = 1 
								   AND Id_Cliente = @pId_Cliente), 0)
		IF (@Existe_Contrato = 1)
		BEGIN
			IF(@pId_Familia = 62)
			BEGIN
				SET @Respuesta = 0
				RETURN @Respuesta
			END

		END

		IF(@pId_Familia = 4)
			BEGIN
				SET @Respuesta = 0
				RETURN @Respuesta
			END
END

*/

/*INSTITUTO validaciones de Matricula 1195 se agrega esta validacion por pedido tk# 013736 23/03/2026*/

/*no permitir duplicar pago de matricula tk#013736 */
IF (@pId_Cliente > 0 AND @pId_Producto = '1196')
BEGIN
    IF EXISTS (
        SELECT 1
        FROM Cbtes C
        INNER JOIN Cbtes_items I ON C.id_trans = I.id_trans
        INNER JOIN Cbtes_tipos CT ON C.id_tipo_cbte = CT.id_tipo_cbte
        WHERE I.id_producto = '1196'
          AND I.id_cliente = @pId_Cliente
          AND C.id_estado_cbte = 2
          AND CT.compromete_factura = 1
          AND DATEPART(YY, I.Fecha_QA) = 2026
    )
    BEGIN
        IF (@pObservacion = 1)
        BEGIN
            SET @Observacion = 'La matrícula ya se encuentra paga'
        END

          SET @Respuesta = 0;
            RETURN ISNULL(@Observacion, @Respuesta)
    END
END

IF (@pId_Cliente > 0 
    AND @pId_Producto IN (
        '1185','1186','1187','1188','1189','1190','1191','1192',
        '1193','1194'/*,'1195',*/
    ))
BEGIN
	DECLARE @TieneMatriculaPagada INT = 0;

    -- Validar matrícula paga (producto 1195 SIN deuda)
    SELECT @TieneMatriculaPagada = COUNT(*)
    FROM Cbtes C
    INNER JOIN Cbtes_items I ON C.id_trans = I.id_trans
    INNER JOIN Cbtes_tipos CT ON C.id_tipo_cbte = CT.id_tipo_cbte
    WHERE I.id_producto IN ('1195','1196')
      AND I.id_cliente = @pId_Cliente
      AND C.id_estado_cbte =2       -- NO impago → está paga
      AND CT.compromete_factura = 1
	  AND DATEPART(YY,I.Fecha_QA)='2026'

    -- Si NO tiene matrícula paga → cortar
    IF (@TieneMatriculaPagada = 0)
    BEGIN
        IF(@pObservacion = 1)
        BEGIN
            SET @Observacion = 'Debe abonar la Matrícula antes de continuar'
        END

        SET @Respuesta = 0;
    END
	ELSE
	BEGIN
		SET @Respuesta = 1; -- OK Con Matricula Paga

		SELECT @Respuesta = COUNT(*)
		FROM Cbtes C
		INNER JOIN Cbtes_items I ON C.id_trans = I.id_trans
		INNER JOIN Productos P ON I.id_producto = P.id_producto
		INNER JOIN Cbtes_tipos CT ON C.id_tipo_cbte = CT.id_tipo_cbte
		WHERE P.id_familia = 4            -- productos del instituto
		  AND C.id_estado_cbte = 1        -- impago
		  AND CT.compromete_factura = 1   -- genera deuda
		  AND I.id_cliente = @pId_Cliente;

		IF @Respuesta >= 1
		BEGIN
			IF(@pObservacion = 1)
			BEGIN
				SET @Observacion = 'Posee Deuda de Instituto'
			END
			SET @Respuesta = 0;
		END
		ELSE
		BEGIN
			SET @Respuesta = 1; -- OK sin deuda
		END
	END
END



IF(@pObservacion = 1)
BEGIN
    RETURN ISNULL(@Observacion, '')
END

-----------------------------------------------------------------------------------------
RETURN ISNULL(@Respuesta,'1')
END

---------------------------------------------------------------------------------------------
GO

