EJ IMPLEMENTACION:

DECLARE @Id_Cliente_Externo			VARCHAR(14)
DECLARE @Razon_Social				VARCHAR(100)
DECLARE @Apellido					VARCHAR(100)
DECLARE @Nombre						VARCHAR(100)
