DECLARE @Lote_Abono								TINYINT			--Perrtenecen a abonos anteriores (Lote Abono)
/*FIN Variables Locales*/

-----------------------------------------------------------------------------------------------------------------------------------------------

SELECT
@Activo								= ISNULL(Activo, 0),
