WHERE
Id_Cliente = @pId_Cliente

-----------------------------------------------------------------------------------------------------------------------------------------------

/*SE HABILITA POR BACKDOOR*/
SELECT
@Flag_Root = ISNULL(Valor_Integer, 0)
