	RETURN @Flag_Validacion_OK
END


IF(CONVERT(DATE, @pFecha) <> CONVERT(DATE, GETDATE()))
BEGIN
	SET @Hoy				= CONVERT(DATE, @pFecha)
END
ELSE
BEGIN
	SET @Hoy				= CONVERT(DATE, GETDATE())
