CREATE FUNCTION [dbo].[CFUJ_Venta_Abono_Lista_Renovacion](@pJson VARCHAR(8000))
RETURNS SMALLINT
AS
BEGIN


/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug							TINYINT
DECLARE @pId_Cliente						INT
DECLARE @pId_Lista_Precio_Abono_Origen		SMALLINT
DECLARE @pFecha								DATETIME

SET @pModoDebug							= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), '')
SET @pId_Cliente						= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Lista_Precio_Abono_Origen		= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Lista_Precio_Abono_Origen')), 0)
SET @pFecha								= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')), GETDATE())
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Id_Lista_Precio_Abono_Destino			SMALLINT
/*FIN Variables Locales*/

-----------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------

--IMPLEMENTACIONES
--17/05/2022: Se crea la funcion

-----------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------

/*
EJEMPLO Se utiliza para Kiosk, al momento de renovaciones de abonos se recibe por parametro el id_Lista_PRecio del abono vencido(origen) y lo convierte a la lista de precios nueva (renovacion nueva): 
IF (@pId_Lista_Precio_Abono_Origen IN (	521, /*ABONO  1░ SEMESTRE 2022 (hasta 22-1)*/
										522, /*ABONO  1░ SEMESTRE 2022 */
										523, /*RENOVAR ABONO 1░ SEMEST 2022(Precio Hasta 22)*/
										524) /*RENOVAR ABONO 1░ SEMEST 2022*/
										) /* Listas del Primer semestre 2022*/
BEGIN
	IF @pFecha < '20220527'
	BEGIN
		SET @Id_Lista_Precio_Abono_Destino = 547 /*Lista Renovaci¾n del 2║ Semestre*/
	END
	ELSE 
	BEGIN
		SET @Id_Lista_Precio_Abono_Destino = 548 /*Lista Renovaci¾n 2║ Semestre 2022 - Sin descuento del 27/5 al 3/6*/
	END
END
*/
-----------------------------------------------------------------------------------------------------------------------------------------------

RETURN ISNULL(@Id_Lista_Precio_Abono_Destino, @pId_Lista_Precio_Abono_Origen)
END
GO

CREATE FUNCTION [dbo].[CFUJ_Venta_Abono_Renov_Condiciones_Validar](@pJson VARCHAR(8000))
RETURNS TINYINT
AS
BEGIN
/*Variable Retorno*/
DECLARE @Flag_Validacion_OK		TINYINT
/*FIN Variable Retorno*/

	/***************************************************************************************************

	Procedimiento:      dbo.CFUJ_Venta_Abono_Renov_Condiciones_Validar
	Fecha de Creacion:  2024-01-09
	Creado por:         Adriana Laverde
	Descripcion:        Funcion encargada para la validacion de listas de abonos habilitadas en una Renovacion, por defecto habilita
	Llamado por:        kiosk/plateas_renovacion_listas.php (Kiosk)
	Tablas afectadas:   []
	Usado en:           Renovacion de Abonos
	Parametro(s):       ModoDebug, Id_Cliente, Id_Evento, Fecha, Id_Evento_Abono_Origen
	Forma de uso:       SELECT dbo.CFUJ_Venta_Abono_Renov_Condiciones_Validar ('{"ModoDebug":"0","Id_Cliente":"25483","Id_Evento":"2021","Fecha":"2024-01-09T10:12:51","Id_Evento_Abono_Origen":"2020"}')
	Notas adicionales:  

	- Para utilizar esta función se deben verificar las particularidades que pida el cliente para la renovacion de abonos

	- Se crean secciones para implementar particularidades del cliente (pueden cambiar de orden dependiendo de la necesidad)

	****************************************************************************************************

	SUMARIO DE CAMBIOS
	FECHA(yyyy-mm-dd)    Autor              Comentarios
	------------------- ------------------- ------------------------------------------------------------

              
	***************************************************************************************************/


/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug							TINYINT
DECLARE @pId_Cliente						INT
DECLARE @pId_Evento							SMALLINT
DECLARE @pFecha								DATETIME
DECLARE @pId_Evento_Abono_Origen			SMALLINT

SET @pModoDebug							= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), '')
SET @pId_Cliente						= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Evento							= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Evento')), 0)
SET @pFecha								= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')), GETDATE())
SET @pId_Evento_Abono_Origen			= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Evento_Abono_Origen')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Cliente_Activo									TINYINT
DECLARE @Cliente_Fecha_Alta								DATETIME
DECLARE @Cliente_Fecha_Baja								DATETIME
DECLARE @Cliente_Id_Cliente_Ref									INT
DECLARE @Cliente_Id_Cliente_Externo						VARCHAR(14)
DECLARE @Cliente_Razon_Social							VARCHAR(100)
DECLARE @Cliente_Fecha_Nac								DATETIME
DECLARE @Cliente_Edad									INT
DECLARE @Cliente_Id_Tipo_Cli							SMALLINT
DECLARE @Cliente_Doc_Nro								BIGINT
DECLARE @Cliente_Credencial_Nro							VARCHAR(30)
DECLARE @Cliente_Tipo_Persona							CHAR(1)
DECLARE @Cliente_Ult_Cuota_Paga							DATETIME
/*FIN Variables Locales*/

-----------------------------------------------------------------------------------------------------------------------------------------------

SELECT
@Cliente_Activo								= ISNULL(Activo, 0),
@Cliente_Fecha_Alta							= ISNULL(Fecha_Alta, '19000101'),
@Cliente_Fecha_Baja							= ISNULL(Fecha_Baja, '19000101'),
@Cliente_Id_Cliente_Ref						= ISNULL(Id_Cliente_Ref, 0),
@Cliente_Id_Cliente_Externo					= LTRIM(RTRIM(ISNULL(Id_Cliente_Externo, ''))),
@Cliente_Razon_Social						= LTRIM(RTRIM(ISNULL(Razon_Social, ''))),
@Cliente_Fecha_Nac							= ISNULL(Fecha_Nac, '19000101'),
@Cliente_Edad								= dbo.CF_Edad_Persona_A_UnaFecha(ISNULL(Fecha_Nac, '19000101'), @pFecha),
@Cliente_Id_Tipo_Cli						= ISNULL(Id_Tipo_Cli, 0),
@Cliente_Doc_Nro							= ISNULL(Doc_Nro, 0),
@Cliente_Credencial_Nro						= LTRIM(RTRIM(ISNULL(Credencial_Nro, ''))),
@Cliente_Tipo_Persona						= ISNULL(Tipo_Persona, 'F'), 
@Cliente_Ult_Cuota_Paga						= ISNULL(Ult_Cuota_Paga, '19000101')
FROM Clientes
WHERE
Id_Cliente = @pId_Cliente

-----------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------

-----------------------------------------------------------------------------------------------------------------------------------------------
IF (@Cliente_Activo <> 1)
BEGIN
	SET @Flag_Validacion_OK = 0
	RETURN @Flag_Validacion_OK
END

-----------------------------------------------------------------------------------------------------------------------------------------------

IF (@Cliente_Tipo_Persona <> 'F')
BEGIN
	SET @Flag_Validacion_OK = 0
	RETURN @Flag_Validacion_OK
END
--------------------------------------------------------------------------------------------------------------------------------------

-----------------------------------------------------------------------------------------------------------------------------------------------

--INICIALIZACION
SET @Flag_Validacion_OK = 1

-----------------------------------------------------------------------------------------------------------------------------------------------

IF(1 = 0)
BEGIN
	SET @Flag_Validacion_OK = 0
END

----------------------------------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------------------------------

-- IMPLEMETAR VALIDACIONES PARTICULARES PARA CADA LISTA DE RENOVACION

----------------------------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------------------------
RETURN ISNULL(@Flag_Validacion_OK, 0)
END
GO


CREATE FUNCTION [dbo].[CFUJ_Venta_Abonos_Condiciones_Validar](@pJson VARCHAR(8000))
RETURNS TINYINT
AS
BEGIN
/*Variable Retorno*/
DECLARE @Flag_Validacion_OK		TINYINT
/*FIN Variable Retorno*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug			TINYINT
DECLARE @pId_Cliente		INT
DECLARE @pId_Evento			SMALLINT
DECLARE @pFecha				DATETIME

SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), '')
SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Evento				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Evento')), 0)
SET @pFecha					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')), GETDATE())
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Cliente_Activo									TINYINT
DECLARE @Cliente_Fecha_Alta								DATETIME
DECLARE @Cliente_Fecha_Baja								DATETIME
DECLARE @Cliente_Id_Cliente_Ref									INT
DECLARE @Cliente_Id_Cliente_Externo						VARCHAR(14)
DECLARE @Cliente_Razon_Social							VARCHAR(100)
DECLARE @Cliente_Fecha_Nac								DATETIME
DECLARE @Cliente_Edad									INT
DECLARE @Cliente_Id_Tipo_Cli							SMALLINT
DECLARE @Cliente_Doc_Nro								BIGINT
DECLARE @Cliente_Credencial_Nro							VARCHAR(30)
DECLARE @Cliente_Tipo_Persona							CHAR(1)
DECLARE @Cliente_Ult_Cuota_Paga							DATETIME

DECLARE @Evento_Activo									TINYINT
DECLARE @Evento_Descripcion								VARCHAR(45)
DECLARE @Evento_Fecha_Desde								DATETIME
DECLARE @Evento_Fecha_Hasta								DATETIME
DECLARE @Evento_Evento_Desde							DATETIME
DECLARE @Evento_Evento_Hasta							DATETIME
DECLARE @Evento_Fecha_Vta_Web_Desde						DATETIME
DECLARE @Evento_Fecha_Vta_Web_Hasta						DATETIME
DECLARE @Evento_Flag_Localidades						TINYINT
DECLARE @Evento_Flag_Web								TINYINT
DECLARE @Evento_Evento_Cant_Dias_Limite					INT
DECLARE @Evento_Evento_Fecha_Reserva_Limite				DATETIME
DECLARE @Evento_Id_Sede									SMALLINT

DECLARE @Dia_De_La_Semana								VARCHAR(50)
DECLARE @Hoy											DATE
DECLARE @Flag_Root										TINYINT
/*FIN Variables Locales*/

-----------------------------------------------------------------------------------------------------------------------------------------------

SELECT
@Cliente_Activo								= ISNULL(Activo, 0),
@Cliente_Fecha_Alta							= ISNULL(Fecha_Alta, '19000101'),
@Cliente_Fecha_Baja							= ISNULL(Fecha_Baja, '19000101'),
@Cliente_Id_Cliente_Ref						= ISNULL(Id_Cliente_Ref, 0),
@Cliente_Id_Cliente_Externo					= LTRIM(RTRIM(ISNULL(Id_Cliente_Externo, ''))),
@Cliente_Razon_Social						= LTRIM(RTRIM(ISNULL(Razon_Social, ''))),
@Cliente_Fecha_Nac							= ISNULL(Fecha_Nac, '19000101'),
@Cliente_Edad								= dbo.CF_Edad_Persona_A_UnaFecha(ISNULL(Fecha_Nac, '19000101'), @pFecha),
@Cliente_Id_Tipo_Cli						= ISNULL(Id_Tipo_Cli, 0),
@Cliente_Doc_Nro							= ISNULL(Doc_Nro, 0),
@Cliente_Credencial_Nro						= LTRIM(RTRIM(ISNULL(Credencial_Nro, ''))),
@Cliente_Tipo_Persona						= ISNULL(Tipo_Persona, 'F'), 
@Cliente_Ult_Cuota_Paga						= ISNULL(Ult_Cuota_Paga, '19000101')
FROM Clientes
WHERE
Id_Cliente = @pId_Cliente

-----------------------------------------------------------------------------------------------------------------------------------------------

/*SE HABILITA POR BACKDOOR*/
SELECT
@Flag_Root = ISNULL(Valor_Integer, 0)
FROM Clientes_XCampos
WHERE
Id_Campo = 103 /*ROOT*/
AND Id_Cliente = @pId_Cliente

IF(@Flag_Root=1)
BEGIN
	SET @Flag_Validacion_OK = 1
	RETURN @Flag_Validacion_OK
END

-----------------------------------------------------------------------------------------------------------------------------------------------

SELECT
@Evento_Activo							= ISNULL(Activo, 0),
@Evento_Descripcion						= LTRIM(RTRIM(ISNULL(Descripcion, ''))),
@Evento_Fecha_Desde						= ISNULL(Fecha_Desde, '19000101'),
@Evento_Fecha_Hasta						= ISNULL(Fecha_Hasta, '19000101'),
@Evento_Evento_Desde					= ISNULL(Evento_Desde, '19000101'),
@Evento_Evento_Hasta					= ISNULL(Evento_Hasta, '19000101'),
@Evento_Fecha_Vta_Web_Desde				= ISNULL(Fecha_Vta_Web_Desde, '19000101'),
@Evento_Fecha_Vta_Web_Hasta				= ISNULL(Fecha_Vta_Web_Hasta, '19000101'),
@Evento_Flag_Localidades				= ISNULL(Flag_Localidades, 0),
@Evento_Flag_Web						= ISNULL(Flag_Web, 0),
@Evento_Evento_Cant_Dias_Limite			= ISNULL(Evento_Cant_Dias_Limite, 0),
@Evento_Evento_Fecha_Reserva_Limite		= ISNULL(Evento_Fecha_Reserva_Limite, '19000101'),
@Evento_Id_Sede							= ISNULL(Id_Sede, 0)
FROM Prod_Listas_Precios
WHERE
Id_Lista_Precio = @pId_Evento

IF(CONVERT(DATE, @pFecha) <> CONVERT(DATE, GETDATE()))
BEGIN
	SET @Hoy				= CONVERT(DATE, @pFecha)
END
ELSE
BEGIN
	SET @Hoy				= CONVERT(DATE, GETDATE())
END

-----------------------------------------------------------------------------------------------------------------------------------------------

SET @Dia_De_La_Semana	= LTRIM(RTRIM(UPPER(DATENAME(WEEKDAY, @Hoy))))	/*LUNES, MARTES, MIERCOLES, JUEVES,....*/

-----------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------

--ULTIMA IMPLEMENTACION DD/MM/AAAA

-----------------------------------------------------------------------------------------------------------------------------------------------

IF(@Evento_Activo <> 1)
BEGIN
	SET @Flag_Validacion_OK = 0
	RETURN @Flag_Validacion_OK
END


IF(@Evento_Flag_Localidades <> 1 /*Evento en un periodo de tiempo*/)
BEGIN
	SET @Flag_Validacion_OK = 0
	RETURN @Flag_Validacion_OK
END

IF(@Evento_Flag_Web <> 1)
BEGIN
	SET @Flag_Validacion_OK = 0
	RETURN @Flag_Validacion_OK
END

IF(	CONVERT(DATE, @Evento_Fecha_Vta_Web_Desde) >= @Hoy
	AND CONVERT(DATE, @Evento_Fecha_Vta_Web_Hasta) <= @Hoy)
BEGIN
	SET @Flag_Validacion_OK = 0
	RETURN @Flag_Validacion_OK
END

-----------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------

IF(@Cliente_Activo <> 1)
BEGIN
	SET @Flag_Validacion_OK = 0
	RETURN @Flag_Validacion_OK
END

-----------------------------------------------------------------------------------------------------------------------------------------------

IF(@Cliente_Tipo_Persona <> 'F')
BEGIN
	SET @Flag_Validacion_OK = 0
	RETURN @Flag_Validacion_OK
END

-----------------------------------------------------------------------------------------------------------------------------------------------



-----------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------
-----------------------------------------------------------------------------------------------------------------------------------------------

-----------------------------------------------------------------------------------------------------------------------------------------------

--INICIALIZACION
SET @Flag_Validacion_OK = 1

-----------------------------------------------------------------------------------------------------------------------------------------------

IF(1 = 0)
BEGIN
	SET @Flag_Validacion_OK = 0
END

----------------------------------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------------------------------
----------------------------------------------------------------------------------------------------------------------------------

--------------------------------------------------------------------------------------------------------------------------------
RETURN ISNULL(@Flag_Validacion_OK, 0)
END
--SELECT dbo.CFUJ_Venta_Abonos_Condiciones_Validar ('{"ModoDebug":"0","Id_Cliente":"37819","Id_Evento":"511","Fecha":"20220112"}')
GO

CREATE FUNCTION [dbo].[CFUJ_Venta_Tickets_Condiciones_Validar](@pJson VARCHAR(8000))
RETURNS TINYINT
AS
BEGIN
/*Variable Retorno*/
DECLARE @Flag_Validacion_OK		TINYINT
/*FIN Variable Retorno*/

/***************************************************************************************************

	Procedimiento:      dbo.CFUJ_Venta_Tickets_Condiciones_Validar
	Fecha de Creacion:  2023-08-07
	Creado por:         Adriana Laverde
	Descripcion:        Funcion encargada para la validacion de clientes en una Venta de Entradas
	Llamado por:        kiosk/tickets.php (Kiosk), sys/modules/services/localidades_vta_ficha.php (ERP-WEB), sales/invoice_receipt_add.php y tables/client_select.php (Api)
	Tablas afectadas:   []
	Usado en:           Venta de Entradas
	Parametro(s):       ModoDebug, Id_Cliente, Id_Evento, Fecha
	Forma de uso:       SELECT dbo.CFUJ_Venta_Tickets_Condiciones_Validar ('{"ModoDebug":"0","Id_Cliente":"25483","Id_Evento":"2021","Fecha":"20220217"}')
	Notas adicionales:  

	- Para utilizar esta función se deben verificar las particularidades que pida el cliente para la venta de sus entradas 

	- Se crean secciones para implementar particularidades del cliente (pueden cambiar de orden dependiendo de la necesidad)

	****************************************************************************************************

	SUMARIO DE CAMBIOS
	FECHA(yyyy-mm-dd)    Autor              Comentarios
	------------------- ------------------- ------------------------------------------------------------

              
	***************************************************************************************************/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug			TINYINT
DECLARE @pId_Cliente		INT
DECLARE @pId_Evento			SMALLINT
DECLARE @pFecha				DATETIME

SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), '')
SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Evento				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Evento')), 0)
SET @pFecha					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')), GETDATE())
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Cliente_Activo							TINYINT
DECLARE @Cliente_Fecha_Alta						DATETIME
DECLARE @Cliente_Fecha_Baja						DATETIME
DECLARE @Id_Cliente_Ref							INT
DECLARE @Cliente_Id_Cliente_Externo				VARCHAR(14)
DECLARE @Cliente_Razon_Social					VARCHAR(100)
DECLARE @Cliente_Fecha_Nac						DATETIME
DECLARE @Cliente_Edad							INT
DECLARE @Cliente_Id_Tipo_Cli					SMALLINT
DECLARE @Cliente_Doc_Nro						BIGINT
DECLARE @Cliente_Credencial_Nro					VARCHAR(30)
DECLARE @Cliente_Tipo_Persona					CHAR(1)
DECLARE @Cliente_Ult_Cuota_Paga					DATETIME
DECLARE @Cliente_Tipo_Categoria					CHAR(1)

DECLARE @Evento_Activo							TINYINT
DECLARE @Evento_Descripcion						VARCHAR(45)
DECLARE @Evento_Fecha_Desde						DATETIME
DECLARE @Evento_Fecha_Hasta						DATETIME
DECLARE @Evento_Evento_Desde					DATETIME
DECLARE @Evento_Evento_Hasta					DATETIME
DECLARE @Evento_Fecha_Vta_Web_Desde				DATETIME
DECLARE @Evento_Fecha_Vta_Web_Hasta				DATETIME
DECLARE @Evento_Flag_Localidades				TINYINT
DECLARE @Evento_Flag_Web						TINYINT
DECLARE @Evento_Evento_Cant_Dias_Limite			INT
DECLARE @Evento_Evento_Fecha_Reserva_Limite		DATETIME
DECLARE @Evento_Id_Sede							SMALLINT

DECLARE	@Id_Contrato_Licencia_Activo			INT
DECLARE @Flag_Entrada_Ya_Adquirida				TINYINT
DECLARE	@Cliente_Flag_Root						INT

DECLARE @Dia_De_La_Semana						VARCHAR(50)
DECLARE @Hoy									DATE
DECLARE @Flag_Debito_Auto						SMALLINT

DECLARE @Evento_Id_Evento_Grupo					INT
DECLARE @Evento_UCP_Min_Validar					DATETIME
DECLARE @CliTipo_Existe							SMALLINT
DECLARE @CliTipo_Cant_Entrada					INT
DECLARE @CliTipo_Fecha_Vta_Desde				DATETIME
DECLARE @CliTipo_Fecha_Vta_Hasta				DATETIME
DECLARE @CliTipo_Flag_UCP_Validar				SMALLINT
/*FIN Variables Locales*/

---------------------------------------------------------------- SETEOS GENERALES -----------------------------------------------------------------

SELECT
@Cliente_Activo								= ISNULL(C.Activo, 0),
@Cliente_Fecha_Alta							= ISNULL(C.Fecha_Alta, '19000101'),
@Cliente_Fecha_Baja							= ISNULL(C.Fecha_Baja, '19000101'),
@Id_Cliente_Ref								= ISNULL(C.Id_Cliente_Ref, 0),
@Cliente_Id_Cliente_Externo					= LTRIM(RTRIM(ISNULL(C.Id_Cliente_Externo, ''))),
@Cliente_Razon_Social						= LTRIM(RTRIM(ISNULL(C.Razon_Social, ''))),
@Cliente_Fecha_Nac							= ISNULL(C.Fecha_Nac, '19000101'),
@Cliente_Edad								= dbo.CF_Edad_Persona_A_UnaFecha(ISNULL(C.Fecha_Nac, '19000101'), @pFecha),
@Cliente_Id_Tipo_Cli						= ISNULL(C.Id_Tipo_Cli, 0),
@Cliente_Doc_Nro							= ISNULL(C.Doc_Nro, 0),
@Cliente_Credencial_Nro						= LTRIM(RTRIM(ISNULL(C.Credencial_Nro, ''))),
@Cliente_Tipo_Persona						= ISNULL(C.Tipo_Persona, 'F'), 
@Cliente_Ult_Cuota_Paga						= ISNULL(C.Ult_Cuota_Paga, '19000101'),
@Cliente_Tipo_Categoria						= ISNULL(T.Flag_Tipo,'')
FROM Clientes C, Clientes_Tipos T
WHERE
Id_Cliente = @pId_Cliente
AND C.Id_tipo_Cli = T.Id_Tipo_Cli

-----------------------------------------------------------------------------------------------------------------------------------------------

/*SE HABILITA POR BACKDOOR*/
SELECT
@Cliente_Flag_Root = ISNULL(Valor_Integer, 0)
FROM Clientes_XCampos
WHERE
Id_Campo = 0 /*ROOT (PARTICULAR)*/
AND Id_Cliente = @pId_Cliente
		

IF(@Cliente_Flag_Root=1)
BEGIN
	SET @Flag_Validacion_OK = 1
	RETURN @Flag_Validacion_OK
END

-----------------------------------------------------------------------------------------------------------------------------------------------

SELECT
@Evento_Activo							= ISNULL(Activo, 0),
@Evento_Descripcion						= LTRIM(RTRIM(ISNULL(Descripcion, ''))),
@Evento_Fecha_Desde						= ISNULL(Fecha_Desde, '19000101'),
@Evento_Fecha_Hasta						= ISNULL(Fecha_Hasta, '19000101'),
@Evento_Evento_Desde					= ISNULL(Evento_Desde, '19000101'),
@Evento_Evento_Hasta					= ISNULL(Evento_Hasta, '19000101'),
@Evento_Fecha_Vta_Web_Desde				= ISNULL(Fecha_Vta_Web_Desde, '19000101'),
@Evento_Fecha_Vta_Web_Hasta				= ISNULL(Fecha_Vta_Web_Hasta, '19000101'),
@Evento_Flag_Localidades				= ISNULL(Flag_Localidades, 0),
@Evento_Flag_Web						= ISNULL(Flag_Web, 0),
@Evento_Evento_Cant_Dias_Limite			= ISNULL(Evento_Cant_Dias_Limite, 0),
@Evento_Evento_Fecha_Reserva_Limite		= ISNULL(Evento_Fecha_Reserva_Limite, '19000101'),
@Evento_Id_Sede							= ISNULL(Id_Sede, 0),
@Evento_Id_Evento_Grupo					= ISNULL(Id_Evento_Grupo, 0),
@Evento_UCP_Min_Validar					= ISNULL(UCP_Min_Validar, '19000101')
FROM Prod_Listas_Precios
WHERE
Id_Lista_Precio = @pId_Evento

-----------------------------------------------------------------------------------------------------------------------------------------------

SELECT
@CliTipo_Existe						= 1,
@CliTipo_Cant_Entrada				= ISNULL(Cant_Entradas, 1),
@CliTipo_Fecha_Vta_Desde			= ISNULL(Fecha_Vta_Desde, @Evento_Fecha_Vta_Web_Desde),
@CliTipo_Fecha_Vta_Hasta			= ISNULL(Fecha_Vta_Hasta, @Evento_Fecha_Vta_Web_Hasta),
@CliTipo_Flag_UCP_Validar			= ISNULL(Flag_UCP_Validar, 0)
FROM Prod_Listas_Precios_Cli_Tipos
WHERE
Id_Lista_Precio = @pId_Evento
AND Id_Tipo_Cli = @Cliente_Id_Tipo_Cli

-------------------------------------------------------- FIN SETEOS GENERALES -----------------------------------------------------------------

----------------------------------------------------- SETEOS PARTICULARES ----------------------------------------------------------------------

-- IMPLEMENTAR AQUI CUALQUIER SETEO PARTICULAR DEL CLIENTE

----------------------------------------------------- FIN SETEOS PARTICULARES ---------------------------------------------------------------------

---------------------------------------------------------  VALIDACIONES GENERALES --------------------------------------------------------------
						
IF(CONVERT(DATE, @pFecha) <> CONVERT(DATE, GETDATE()))
BEGIN
	SET @Hoy				= CONVERT(DATE, @pFecha)
END
ELSE
BEGIN
	SET @Hoy				= CONVERT(DATE, GETDATE())
END

SET @Dia_De_La_Semana	= LTRIM(RTRIM(UPPER(DATENAME(WEEKDAY, @Hoy))))	/*LUNES, MARTES, MIERCOLES, JUEVES,....*/

-----------------------------------------------------------------------------------------------------------------------------------------------

IF(@Cliente_Activo <> 1)
BEGIN
	SET @Flag_Validacion_OK = 0
	RETURN @Flag_Validacion_OK
END

-----------------------------------------------------------------------------------------------------------------------------------------------

IF(@Cliente_Tipo_Persona <> 'F')
BEGIN
	SET @Flag_Validacion_OK = 0
	RETURN @Flag_Validacion_OK
END

-----------------------------------------------------------------------------------------------------------------------------------------------

--INICIALIZACION
SET @Flag_Validacion_OK = 0

---------------------------------------------------------  VALIDACIONES PARTICULARES ----------------------------------------------------------

-- IMPLEMENTAR AQUI CUALQUIER VALIDACION PARTICULAR DEL CLIENTE

---------------------------------------------------------  FIN VALIDACIONES PARTICULARES ------------------------------------------------------

-----------------------------------------------------------------------------------------------------------------------------------------------
/*se modifica para validar que un socio pueda comprar hasta 4 entradas 27/102023 */
SET @Flag_Entrada_Ya_Adquirida = ISNULL((SELECT COUNT(C.Id_Trans)
											FROM Cbtes_Items CI LEFT JOIN Cbtes C	ON CI.Id_Trans = C.Id_Trans
																LEFT JOIN Productos P	ON CI.Id_Producto = P.Id_Producto
																LEFT JOIN Cbtes_Tipos CT	ON C.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
																LEFT JOIN Prod_Listas_Precios PL	ON C.Id_Lista = PL.Id_Lista_Precio
											WHERE 
											CI.Id_Cliente = @pId_Cliente
											AND P.Tipo='L'
											AND PL.Activo = 1
											AND CI.Fecha_Venc >= GETDATE()
											AND PL.Id_Evento_Grupo in (@Evento_Id_Evento_Grupo)
											and (CT.Compromete_Factura = 1 OR CT.Compromete_Pedido = 1)
											AND C.Id_Estado_Cbte NOT IN (3)),0)

IF(@Flag_Entrada_Ya_Adquirida > 5)
BEGIN
	SET @Flag_Validacion_OK = 0
	RETURN @Flag_Validacion_OK
END

------------------------------------------------------------------------------------------------------------------------------------------------

IF(@pFecha >= @CliTipo_Fecha_Vta_Desde AND @pFecha <= @CliTipo_Fecha_Vta_Hasta AND @CliTipo_Existe = 1)
BEGIN

	IF(@CliTipo_Flag_UCP_Validar > 0)
	BEGIN
		IF(CONVERT(DATE, dbo.CF_FOMONTH(@Cliente_Ult_Cuota_Paga)) >= CONVERT(DATE, @Evento_UCP_Min_Validar))
		BEGIN
			SET @Flag_Validacion_OK = 1
			RETURN @Flag_Validacion_OK	
		END
		ELSE
		BEGIN
			SET @Flag_Validacion_OK = 0
			RETURN @Flag_Validacion_OK	
		END
	END
	ELSE
	BEGIN
		SET @Flag_Validacion_OK = 1
		RETURN @Flag_Validacion_OK
	END
END

---------------------------------------------------------  FIN VALIDACIONES GENERALES ------------------------------------------------------------

RETURN ISNULL(@Flag_Validacion_OK, 0)
END

----------------------------------------------------------------------------------------------------------------------------------------------
GO

CREATE FUNCTION [dbo].CFU_BancoBBVA_Proveedores_OP_Provincias(@pId_Provincia VARCHAR(3))
RETURNS CHAR(2)
AS
BEGIN
DECLARE @Retorno		CHAR(2)

/*
TABLA DE BBVA

01	CAPITAL FEDERAL
02	BUENOS AIRES
03	CATAMARCA
04	CORDOBA
05	CORRIENTES
06	CHACO
07	CHUBUT
