	SET @Retorno = '12' /*LA RIOJA*/
END 

IF(@pId_Provincia = 'M')
BEGIN
	SET @Retorno = '13' /*MENDOZA*/
END 

IF(@pId_Provincia = 'N')
BEGIN
	SET @Retorno = '14' /*MISIONES*/
END 

IF(@pId_Provincia = 'Q')
BEGIN
	SET @Retorno = '15' /*NEUQUEN*/
END 

IF(@pId_Provincia = 'R')
BEGIN
	SET @Retorno = '16' /*RIO NEGRO*/
END 

IF(@pId_Provincia = 'A')
BEGIN
	SET @Retorno = '17' /*SALTA*/
END 

IF(@pId_Provincia = 'J')
BEGIN
	SET @Retorno = '18' /*SAN JUAN*/
END 

IF(@pId_Provincia = 'D')
BEGIN
	SET @Retorno = '19' /*SAN LUIS*/
