CREATE FUNCTION [dbo].[CFU_Cbte_Pago_Habilitado](@pId_Trans INT)
RETURNS CHAR(2)
AS
BEGIN

DECLARE @Id_Tarjeta				VARCHAR(10);
DECLARE @Retorno				VARCHAR(3000);
DECLARE @Dias_Bloqueo_CobMan	INT;
DECLARE @Fecha_Presentacion		DATETIME;
DECLARE @Id_Tar_Lote			INT;

SET @Retorno= '';

SELECT TOP 1 @Dias_Bloqueo_CobMan = t.Dias_Bloqueo_CobMan 
		, @Fecha_Presentacion=l.Fecha_Presentacion

					FROM Val_Tarjetas_Lotes_Items i, Val_Tarjetas_Lotes l, Valores_Tarjetas_Cred t
					WHERE i.Id_Trans=@pId_Trans 
						and i.Estado = 'P' 
						and t.Id_Tarjeta = l.Id_Tarjeta
						and l.Id_Tar_Lote=i.Id_Tar_Lote
					ORDER BY l.Fecha_Presentacion DESC

SET @Id_Tarjeta= (SELECT Id_Tarjeta FROM Val_Tarjetas_Lotes Where Id_Tar_Lote=@Id_Tar_Lote)

IF @Dias_Bloqueo_CobMan != 0
BEGIN 
	IF (DATEADD(day,@Dias_Bloqueo_CobMan,@Fecha_Presentacion)) >= CONVERT(DATE, GETDATE()) 
		SET @Retorno = 'Este comprobante fue enviado al débito automático. No esta habilitado el pago por este medio.'
END

--Si devuelve vacio el pago es habilitado, sino devolver el mensaje a mostrar.



RETURN @Retorno
END
GO

