CREATE FUNCTION [dbo].[CFU_Prod_Lista_Precio](@pId_Lista_Precio SMALLINT, @pId_Producto VARCHAR(14), @pId_Cliente INT, @Fecha DATETIME)
RETURNS DECIMAL(12,2)
AS
BEGIN
DECLARE @Precio									DECIMAL(12,2)
DECLARE @Flag_Existe_Lista_Precio				TINYINT
DECLARE @Flag_Existe_Producto					TINYINT
DECLARE @Flag_Existe_Cliente					TINYINT
DECLARE @Flag_Existe_Producto_En_Lista_Precios	TINYINT

DECLARE @Id_Lista_Precio_Nuevo_Socio			SMALLINT

DECLARE @Id_Tipo_Cli							INT
DECLARE @Id_Familia								INT
DECLARE @Fecha_Nac								VARCHAR(4)
DECLARE @Sexo									CHAR(1)
DECLARE @Edad									INT
/*=================================================================================*/

SET @Flag_Existe_Lista_Precio = ISNULL((SELECT 1 FROM Prod_Listas_Precios WHERE Id_Lista_Precio = @pId_Lista_Precio), 0)
IF(@pId_Lista_Precio = 0 OR @Flag_Existe_Lista_Precio = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

SET @Flag_Existe_Producto = ISNULL((SELECT 1 FROM Productos WHERE Id_Producto = @pId_Producto), 0)
IF(@pId_Producto = '' OR @Flag_Existe_Producto = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

SET @Flag_Existe_Cliente = ISNULL((SELECT 1 FROM Clientes WHERE Id_Cliente = @pId_Cliente), 0)
IF(@pId_Cliente = 0 OR @Flag_Existe_Cliente = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

SET @Flag_Existe_Producto_En_Lista_Precios = ISNULL((SELECT 1 FROM Prod_Listas_Precios_Items WHERE Id_Lista_Precio = @pId_Lista_Precio AND Id_Producto = @pId_Producto), 0)
IF(@Flag_Existe_Producto_En_Lista_Precios = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

/*=================================================================================*/
SET @Id_Lista_Precio_Nuevo_Socio = ISNULL((SELECT ID_LISTA_PRECIO FROM CLIENTES WHERE ID_CLIENTE=@pId_Cliente),0)

IF (@Id_Lista_Precio_Nuevo_Socio=222 and @pId_Lista_Precio not in (224,230)) --222 Lista Nuevos socios / 224 Lista para inscripciones
BEGIN
	SELECT
	@Precio = Precio
	FROM Prod_Listas_Precios_Items 
	WHERE 
	Id_Lista_Precio = 223 
	AND Id_Producto = @pId_Producto
	RETURN @Precio
END 

SELECT
@Precio = Precio
FROM Prod_Listas_Precios_Items 
WHERE 
Id_Lista_Precio = @pId_Lista_Precio 
AND Id_Producto = @pId_Producto

/*=================================================================================*/

/*PARA CUALQUIER OTRA PARTICULARIDAD IMPLEMENTAR A PARTIR DE AQUI LA MODIFICACION DE LA VARIABLE @Precio*/

/*=================================================================================*/


-- 20240222 Ticket #7946
IF (@pId_Lista_Precio = 224 /*INSCRIPCIONES WEB*/)
BEGIN
	
	SET @Id_Familia		= ISNULL((SELECT Id_Familia FROM Productos WHERE Id_Producto = @pId_Producto),0)
	
	IF (@Id_Familia = 23 /*FUTBOL*/)
	BEGIN
	
		SELECT	@Id_Tipo_Cli	= Id_Tipo_Cli,
				@Fecha_Nac		= YEAR(Fecha_Nac),
				@Sexo			= Sexo,
				@Edad= YEAR(@Fecha) - YEAR(Fecha_Nac) -- se agrega para no harcodear año 27/02/2026
		FROM Clientes 
		WHERE Id_Cliente = @pId_Cliente 
		AND Activo = 1
		
/*
		1.  Las mujeres pagan el 50% del valor del producto que le corresponde por su categoría de socia
			Si Es mujer y corresponde categoría infantil (6ta y 5ta) el porcentaje de descuento es el que 
			le corresponde por la categoría (30% y 70%).
			A partir de la categoría Cadete si es Mujer le corresponde el 50%
			
		2.  Los infantiles hay categorías 5° y 6° que abonan el 70% y el 30% respectivamente del valor del 
			producto futbol - infantil, las edades para las categoría 5° son nacidos en el 2015 y 2016
			y la categoria 6° nacidos en 2017 y 2018.
			(Validar por categoría de socio da infantil y por fecha de nacimiento el año para encuadrarlo 
			dentro de la 5° o 6° categoría)
*/
		
		IF (@Id_Tipo_Cli = 1000 /*INFANTIL*/) /*sexo indefinido*/
		BEGIN
			/*IF(@Fecha_Nac >= '2015' AND @Fecha_Nac <= '2016') -- 5°
			BEGIN
				SET @Precio = (@Precio-(@Precio * 0.30))
				RETURN ISNULL(@Precio, 0)
			END
			IF(@Fecha_Nac >= '2017' AND @Fecha_Nac <= '2018') -- 6°
			BEGIN
				SET @Precio = (@Precio-(@Precio * 0.70))
				RETURN ISNULL(@Precio, 0)
			END*/
			
			--IF(@Fecha_Nac >= '2017' AND @Fecha_Nac <= '2018') -- 5°  //Ticket #011107 -- se actualiza el año 27/2/2026
			--BEGIN
			--	SET @Precio = (@Precio-(@Precio * 0.30))
			--	RETURN ISNULL(@Precio, 0)
			--END
			--IF(@Fecha_Nac >= '2019' AND @Fecha_Nac <= '2020') -- 6°
			--BEGIN
			--	SET @Precio = (@Precio-(@Precio * 0.70))
			--	RETURN ISNULL(@Precio, 0)
			--END
			IF(@Edad >= '8' AND @Edad <= '9') -- 5°  //-- se actualiza el año 27/2/2026
			BEGIN
				SET @Precio = (@Precio-(@Precio * 0.30))
				RETURN ISNULL(@Precio, 0)
			END
			IF(@Edad >= '6' AND @Edad <= '7') -- 6°
			BEGIN
				SET @Precio = (@Precio-(@Precio * 0.70))
				RETURN ISNULL(@Precio, 0)
			END
		END

		IF(@Sexo = 'F')
		BEGIN
			SET @Precio = (@Precio-(@Precio * 0.50))
			RETURN ISNULL(@Precio, 0) 
		END

	END
	
END

----------------------------------------------------------------------------
--- 20251029 Ticket #012785

SET @Id_Tipo_Cli = (SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente=@pId_Cliente)

IF (@pId_Producto IN (  '1658' /*AJEDREZ - ANUAL*/,
						'1657'/*AJEDREZ - MENSUAL*/,
						'1030'/*CERAMICA - MENSUALIDAD*/,
						'2552'/*COMEDIA MUSICAL - MENSUALIDAD.*/,
						'1156'/*FOLKLORE - MENSUALIDAD*/,
						'2383'/*SALSA - BACHATA (UNA VEZ POR SEMANA)*/,
						'2553'/*TALLER LITERARIO Y POESIA - MENSUALIDAD.*/,
						'1310'/*TANGO - MENSUALIDAD*/,
						'1312'/*TEATRO - MENSUALIDAD*/,
						'1236'/*DIBUJO / PLASTICA / PINTURA - MENSUALIDAD*/
						)
		AND  (@Id_Tipo_Cli = 1000 /*INFANTIL*/))
		BEGIN
		SET @Precio = (@Precio-(@Precio * 0.50))
			RETURN ISNULL(@Precio, 0) 
		END


-----------------------

/*=================================================================================*/

RETURN ISNULL(@Precio, 0)
END
GO

CREATE FUNCTION [dbo].[CFU_Prod_Lista_Precio_Ofertas](@pId_Lista_Precio SMALLINT, @pId_Producto VARCHAR(14), @Fecha DATETIME,  @Id_Usuario INT)
RETURNS DECIMAL(12,2)
AS
BEGIN
DECLARE @Precio									DECIMAL(12,2)
DECLARE @Flag_Existe_Lista_Precio				TINYINT
DECLARE @Flag_Existe_Producto					TINYINT
DECLARE @Flag_Existe_Producto_En_Lista_Precios	TINYINT   
Declare @Prioridad                              TINYINT
DECLARE @Id_lista_Precio_Padre				    INT
DECLARE @Coeficiente         					DECIMAL(12,5)
DECLARE @Id_Sucursal          			        INT
Declare @Filtro_Sucursal                        SMALLINT
/*=================================================================================*/

SET @Id_Sucursal = 0

If @Id_Usuario <> 0
   SET @Id_Sucursal = ISNULL((SELECT ISNULL(Id_Sucursal,0) from Seg_User S Where S.No = @Id_Usuario),0)


SET @Flag_Existe_Lista_Precio = ISNULL((SELECT 1 FROM Prod_Listas_Precios WHERE Id_Lista_Precio = @pId_Lista_Precio), 0)
IF(@pId_Lista_Precio = 0 OR @Flag_Existe_Lista_Precio = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

SET @Flag_Existe_Producto = ISNULL((SELECT 1 FROM Productos WHERE Id_Producto = @pId_Producto), 0)
IF(@pId_Producto = '' OR @Flag_Existe_Producto = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END



SET @Flag_Existe_Producto_En_Lista_Precios = ISNULL((SELECT 1 FROM Prod_Listas_Precios_Items 
    WHERE Id_Lista_Precio = @pId_Lista_Precio AND Id_Producto = @pId_Producto), 0)
IF(@Flag_Existe_Producto_En_Lista_Precios = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

SET @Id_lista_Precio_Padre = ISNULL((SELECT Id_lista_Precio_Padre FROM Prod_Listas_Precios WHERE Id_lista_Precio = @pId_Lista_Precio),@pId_Lista_Precio)

IF @Id_lista_Precio_Padre = 0
   SET @Id_lista_Precio_Padre = @pId_Lista_Precio

SET @Filtro_Sucursal =  ISNULL((SELECT COUNT(*) 
                    FROM Prod_Listas_Precios_Suc S, Prod_Listas_Precios_Asoc A, Prod_Listas_Precios L, Prod_Listas_Precios_Items I
                    WHERE A.Id_Lista_Precio_Padre = @Id_lista_Precio_Padre
					      AND A.Id_Lista_Precio = S.Id_Lista_Precio
						  AND S.Id_Lista_Precio = L.Id_Lista_Precio
						  AND I.Id_Lista_Precio = L.Id_Lista_Precio
						  and I.Id_Producto = @pId_Producto
						  and L.Fecha_Desde <= @Fecha and dateadd(dd,1,L.Fecha_Hasta) >= @Fecha ),0)


SET @Coeficiente = ISNULL((SELECT Coeficiente FROM Prod_Listas_Precios WHERE Id_lista_Precio = @pId_Lista_Precio),1)

IF @Coeficiente = 0
   SET @Coeficiente = 1

/*=================================================================================*/
--select Top 1 lp.id_lista_precio,I.id_Producto,pl.coeficiente,i.Precio, CAST(ROUND((i.Precio*pl.coeficiente) * (1+(T.Porc1/100)),0) AS DECIMAL(14,2)) as Precio_Lista
set @Precio = 0
IF @Filtro_Sucursal <> 0 AND @Id_Sucursal <> 0
   BEGIN
		select Top 1 @Precio = ISNULL(CAST(ROUND((i.Precio*@Coeficiente),0) AS DECIMAL(14,2)),0) 
				 from Prod_Listas_Precios PL, 
					  Prod_Listas_Precios_Asoc A,
					  Prod_Listas_Precios_Suc S,
					  Prod_Listas_Precios LP,
 					  Prod_Listas_Precios_Items I,
					  Productos p
				where PL.Id_lista_Precio = @pId_Lista_Precio
				and I.Id_Producto = @pId_Producto
				AND A.Id_lista_Precio_Padre = @Id_lista_Precio_Padre
			--	and PL.Id_lista_Precio_Padre = @Id_lista_Precio_Padre
				and A.Id_lista_Precio = LP.Id_lista_Precio
				and I.Id_lista_precio = LP.Id_lista_Precio
				and Lp.Fecha_Desde <= @Fecha and dateadd(dd,1,Lp.Fecha_Hasta) >= @Fecha 
				AND S.Id_Lista_Precio = A.Id_Lista_Precio
				AND S.Id_Sucursal = @Id_Sucursal
				and P.Id_Producto = I.Id_Producto
				order by A.Orden desc
    END
   ELSE
    BEGIN
		select Top 1 @Precio = ISNULL(CAST(ROUND((i.Precio*@Coeficiente),0) AS DECIMAL(14,2)),0) 
				 from Prod_Listas_Precios PL, 
					  Prod_Listas_Precios_Asoc A,
					  Prod_Listas_Precios LP,
 					  Prod_Listas_Precios_Items I,
					  Productos p
				where PL.Id_lista_Precio = @pId_Lista_Precio
				and I.Id_Producto = @pId_Producto
				AND A.Id_lista_Precio_Padre = @Id_lista_Precio_Padre
			--	and PL.Id_lista_Precio_Padre = @Id_lista_Precio_Padre
				and A.Id_lista_Precio = LP.Id_lista_Precio
				and I.Id_lista_precio = LP.Id_lista_Precio
				and Lp.Fecha_Desde <= @Fecha and dateadd(dd,1,Lp.Fecha_Hasta) >= @Fecha 
				and P.Id_Producto = I.Id_Producto
				order by A.Orden desc
	END

/*=================================================================================*/
IF @Precio = 0
	SELECT
	@Precio = Precio
	FROM Prod_Listas_Precios_Items 
	WHERE 
	Id_Lista_Precio = @pId_Lista_Precio 
	AND Id_Producto = @pId_Producto

/*=================================================================================*/

/*PARA CUALQUIER OTRA PARTICULARIDAD IMPLEMENTAR A PARTIR DE AQUI LA MODIFICACION DE LA VARIABLE @Precio*/

/*=================================================================================*/

RETURN ISNULL(@Precio, 0)
END

