/*================================================================================================================================*/

/*Variables de Calculo intermedio*/
DECLARE @Id_Proveedor				INT
DECLARE @Cuit_Proveedor				VARCHAR(11)
DECLARE @Razon_Social_Proveedor		VARCHAR(100)
DECLARE @CBU_Proveedor				VARCHAR(22)
DECLARE @Ingresos_Brutos_Proveedor	VARCHAR(20)
DECLARE @Direccion_Proveedor		VARCHAR(100)
DECLARE @Cp_Proveedor				VARCHAR(10)
DECLARE @Id_Localidad_Proveedor		INT
DECLARE @Id_Provincia_Proveedor		CHAR(3)
DECLARE @email_Proveedor			VARCHAR(8000)
/*FIN Variables de Calculo intermedio*/


/*Asignacion de variables*/
SELECT
@Id_Proveedor	= ISNULL(Id_Proveedor, 0)
FROM Cbtes
WHERE
Id_Trans = @pId_Trans

SELECT
@Cuit_Proveedor				= SUBSTRING(LTRIM(RTRIM(ISNULL(Cuit, ''))), 1, 11),
@Razon_Social_Proveedor		= ISNULL(Razon_Social, ''),
@CBU_Proveedor				= ISNULL(CBU, ''),
@Ingresos_Brutos_Proveedor	= ISNULL(LTRIM(RTRIM(REPLACE(ingresos_brutos, 'CM', ''))), ''),
@Direccion_Proveedor		= ISNULL(Direccion, ''),
@Id_Localidad_Proveedor		= ISNULL(Id_Localidad, 0),
@Cp_Proveedor				= ISNULL(Cp, ''),
@Id_Provincia_Proveedor		= ISNULL(Id_Provincia, ''),
@email_Proveedor			= SUBSTRING(CONVERT(VARCHAR(8000), ISNULL(email, '')), 1, 40)
FROM Proveedores
WHERE
Id_Proveedor = @Id_Proveedor
/*FIN Asignacion de variables*/

/*================================================================================================================================*/

SET @aIDENT_REGISTRO		= '0306'
SET @aTIPO_REG				= '090'
SET @aTIPO_DOC_EMPRE		= 'CUIT'
SET @aNRO_CUIT_EMPRE		= (SELECT RIGHT('0000000000000' + CAST(@pCuitEmpresa AS VARCHAR), 13))
SET @aSECUENCIA				= (SELECT RIGHT('000000' + CAST(@pNroSecuencia AS VARCHAR), 6))
SET @aPRO_NRO_ORD			= 'PUBL_MP        '
SET @aPRO_NRO_BENEF			= (SELECT RIGHT('000000000000000' + CAST(@Id_Proveedor AS VARCHAR), 15))
SET @aPRO_EST_BENEF			= '1' --??
SET @aPRO_DOCTO_TIP			= 'CUI' /*CUIT*/
SET @aPRO_DOCTO_NRO			= (SELECT RIGHT('00000000000' + CAST(@Cuit_Proveedor AS VARCHAR), 11))
SET @aPRO_DENOMINA			= @Razon_Social_Proveedor
SET @aPRO_CATEGO			= '  '
SET @aPRO_PERMIT_FINAN		= ' '
SET @aPRO_CUS_TIP			= '00'
SET @aPRO_CUS_SUC			= '000'
SET @aPRO_CUS_NRO			= '0000000000'
SET @aPRO_CBU_NRO			= @CBU_Proveedor
SET @aPRO_INGBRTS			= (SELECT RIGHT('00000000000' + CAST(CONVERT(BIGINT, REPLACE (@Ingresos_Brutos_Proveedor, '-', '')) AS VARCHAR), 11))
SET @aPRO_CALLE				= @Direccion_Proveedor
SET @aPRO_NUMERO			= '00000'	/*No tenemos el numero separado*/
SET @aPRO_DEPTO				= '   '		/*No tenemos el depto separado*/
SET @aPRO_PISO				= '00'		/*No tenemos el Nro Piso sepadao*/
SET @aPRO_LOCALID			= ISNULL((SELECT ISNULL(Descripcion, '') FROM Tab_Localidades WHERE Id_Localidad = @Id_Localidad_Proveedor), '')
SET @aPRO_CPOSTAL			= @Cp_Proveedor
SET @aPRO_CODPROV			= (dbo.CFU_BancoBBVA_Proveedores_OP_Provincias(@Id_Provincia_Proveedor))
SET @aPRO_CODPAIS			= '080'
SET @aPRO_EMAIL				= @email_Proveedor
SET @aPRO_CALLE_ENTREGA		= '                        '
SET @aPRO_NUMERO_ENTREGA	= '     '
SET @aPRO_DEPTO_ENTREGA		= '   '
SET @aPRO_PISO_ENTREGA		= '  '
SET @aPRO_LOCALID_ENTREGA	= '                            '
SET @aPRO_CPOSTAL_ENTREGA	= '     '
SET @aPRO_CODPROV_ENTREGA	= '  '
SET @aPRO_CODPAIS_ENTREGA	= '   '
SET @aPRO_TELEF_TIP			= '00' /*Sin informacion*/
SET @aPRO_TELEF_PRE			= '    '
SET @aPRO_TELEF_CAR			= '    '
SET @aPRO_TELEF_NRO			= '     '
SET @aPRO_TELEF_INT			= '                  '
SET @aPRO_TELEF_ALTER_TIP	= '00' /*Sin informacion*/
SET @aPRO_TELEF_ALTER_PRE	= '    '
SET @aPRO_TELEF_ALTER_CAR	= '    '
SET @aPRO_TELEF_ALTER_NRO	= '     '
SET @aPRO_TELEF_ALTER_INT	= '                  '
SET @aPRO_AUTORIZA_NOM1		= '                         '
SET @aPRO_AUTORIZA_TIP1		= '   '
SET @aPRO_AUTORIZA_DOC1		= '00000000'
SET @aPRO_AUTORIZA_NOM2		= '                         '
SET @aPRO_AUTORIZA_TIP2		= '   '
SET @aPRO_AUTORIZA_DOC2		= '00000000'
SET @aPRO_AUTORIZA_NOM3		= '                         '
SET @aPRO_AUTORIZA_TIP3		= '   '
SET @aPRO_AUTORIZA_DOC3		= '00000000'
SET @aPRO_DATOS				= '                                                                                                    '
SET @aPRO_MINUTA			= (SELECT RIGHT('00000000' + CAST(@pId_Trans AS VARCHAR), 8))
SET @aFILLER				= '                                                                                                                                                                                                                          '

/*================================================================================================================================*/

SET @Retorno =	@aIDENT_REGISTRO + 
				@aTIPO_REG + 
				@aTIPO_DOC_EMPRE + 
				@aNRO_CUIT_EMPRE + 
				@aSECUENCIA + 
				@aPRO_NRO_ORD + 
				@aPRO_NRO_BENEF   + 
				@aPRO_EST_BENEF   + 
				@aPRO_DOCTO_TIP   + 
				@aPRO_DOCTO_NRO   + 
				@aPRO_DENOMINA    + 
				@aPRO_CATEGO      + 
				@aPRO_PERMIT_FINAN   + 
				@aPRO_CUS_TIP  + 
				@aPRO_CUS_SUC  + 
				@aPRO_CUS_NRO  + 
				@aPRO_CBU_NRO   + 
				@aPRO_INGBRTS   + 
				@aPRO_CALLE + 
				@aPRO_NUMERO   + 
				@aPRO_DEPTO + 
				@aPRO_PISO  + 
				@aPRO_LOCALID  + 
				@aPRO_CPOSTAL  + 
				@aPRO_CODPROV  + 
				@aPRO_CODPAIS  + 
				@aPRO_EMAIL + 
				@aPRO_CALLE_ENTREGA   + 
				@aPRO_NUMERO_ENTREGA  + 
				@aPRO_DEPTO_ENTREGA   + 
				@aPRO_PISO_ENTREGA + 
				@aPRO_LOCALID_ENTREGA + 
				@aPRO_CPOSTAL_ENTREGA + 
				@aPRO_CODPROV_ENTREGA + 
				@aPRO_CODPAIS_ENTREGA + 
				@aPRO_TELEF_TIP + 
				@aPRO_TELEF_PRE + 
				@aPRO_TELEF_CAR + 
				@aPRO_TELEF_NRO + 
				@aPRO_TELEF_INT + 
				@aPRO_TELEF_ALTER_TIP + 
				@aPRO_TELEF_ALTER_PRE + 
				@aPRO_TELEF_ALTER_CAR + 
				@aPRO_TELEF_ALTER_NRO + 
				@aPRO_TELEF_ALTER_INT + 
				@aPRO_AUTORIZA_NOM1  + 
				@aPRO_AUTORIZA_TIP1  + 
				@aPRO_AUTORIZA_DOC1  + 
				@aPRO_AUTORIZA_NOM2  + 
				@aPRO_AUTORIZA_TIP2  + 
				@aPRO_AUTORIZA_DOC2  + 
				@aPRO_AUTORIZA_NOM3  + 
				@aPRO_AUTORIZA_TIP3  + 
				@aPRO_AUTORIZA_DOC3  + 
				@aPRO_DATOS + 
				@aPRO_MINUTA + 
				@aFILLER
				
/*================================================================================================================================*/
					
RETURN @Retorno
END
GO


CREATE FUNCTION [dbo].[CF_BancoCabal_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT) 
RETURNS CHAR(240)
AS
BEGIN

/*Variable de Retorno*/
DECLARE @Retorno			CHAR(240)
/*FIN Variable de Retorno*/

/*Variables del Archivo*/
DECLARE @aId_Trans		CHAR(9)/*DESCRIPCIÔö£├┤N: Descripcion del Archivo para esta campo: IdentificaciÔö£Ôöén del socio, PERO EN CLEVER NECESITAMOS EL ID_TRANS PARA PODER IDENTIFICAR LA TRANSACCIÔö£├┤N EN EL ARCHIVO DE RESPUESTA. POS: 001-009. LONG: 9. FORMATO: NumÔö£┬«rico. OBS: NÔö£Ôòæmero con el que la Empresa identifica a su cliente/socio.*/
DECLARE @aTar_Nro		CHAR(16)/*DESCRIPCIÔö£├┤N: NÔö£Ôòæmero de Tarjeta Cabal. POS: 010-025. LONG: 16. FORMATO: NumÔö£┬«rico. OBS: IMPORTANTE: actualizar el dato con lo informado en el archivo de respuesta.*/
DECLARE @aImporte		CHAR(11)/*DESCRIPCIÔö£├┤N: Importe del DÔö£┬«bito. POS: 026-036. LONG: 11. FORMATO: NumÔö£┬«rico. OBS: Formato: 9 enteros con 2 decimales, sin usar separador decimal.*/
DECLARE @aLibreA		CHAR(82)/*DESCRIPCIÔö£├┤N: Libre. POS: 037-118. LONG: 82. FORMATO: AlfanumÔö£┬«rico. OBS: Completar con espacios.*/
DECLARE @aDescripcion	CHAR(25)/*DESCRIPCIÔö£├┤N: Leyenda que se imprime en el resumen del usuario. CompaÔö£ÔûÆÔö£┬ías de Seguro: Nombre de la Aseguradora Rama '/' (informar barra) NÔö£Ôòæmero de PÔö£Ôöéliza '/' (informar barra) Endoso '/' (informar barra) NÔö£Ôòæmero de Cuota. POS: 119-143. LONG: 25 (7,2,1,8,1,3,1,2). FORMATO: AlfanumÔö£┬«rico. OBS: Si no se informa, se toma el Nombre del Comercio.*/
DECLARE @aFechaPresent	CHAR(6)/*DESCRIPCIÔö£├┤N: Fecha de la PresentaciÔö£Ôöén. POS: 144-149. LONG: 6. FORMATO: NumÔö£┬«rico. OBS: Formato: DDMMAA.*/
DECLARE @aLibreB		CHAR(27)/*DESCRIPCIÔö£├┤N: Libre. POS: 150-176. LONG: 27. FORMATO: AlfanumÔö£┬«rico. OBS: Completar con espacios.*/
DECLARE @aNroComercio	CHAR(11)/*DESCRIPCIÔö£├┤N: NÔö£Ôòæmero de Comercio Cabal. POS: 177-187. LONG: 11. FORMATO: NumÔö£┬«rico. OBS: */
DECLARE @aId_Moneda		CHAR(1)/*DESCRIPCIÔö£├┤N: CÔö£Ôöédigo de Moneda. POS: 188-188. LONG: 1. FORMATO: AlfanumÔö£┬«rico. OBS: Informar: 'P'*/
DECLARE @aLibreC		CHAR(21)/*DESCRIPCIÔö£├┤N: Libre. POS: 189-209. LONG: 21. FORMATO: AlfanumÔö£┬«rico. OBS: Completar con espacios.*/
DECLARE @aNroTicket		CHAR(4)/*DESCRIPCIÔö£├┤N: NÔö£Ôòæmero de Ticket. POS: 210-213. LONG: 4. FORMATO: NumÔö£┬«rico. OBS: No debe repetirse dentro de la misma presentaciÔö£Ôöén.*/
DECLARE @aLibreD		CHAR(10)/*DESCRIPCIÔö£├┤N: Libre. POS: 214-223. LONG: 10. FORMATO: AlfanumÔö£┬«rico. OBS: Completar con espacios.*/
DECLARE @aCodOperacion	CHAR(2)/*DESCRIPCIÔö£├┤N: CÔö£Ôöédigo de OperaciÔö£Ôöén. POS: 224-225. LONG: 2. FORMATO: NumÔö£┬«rico. OBS: '01': DÔö£┬«bito al Usuario / '51': CrÔö£┬«dito al Usuario*/
DECLARE @aLibreE		CHAR(15)/*DESCRIPCIÔö£├┤N: Libre. POS: 226-240. LONG: 15. FORMATO: AlfanumÔö£┬«rico. OBS: Completar con espacios.*/
/*FIN Variables del Archivo*/

/*Variables Intermedias*/
DECLARE @Tar_Nro				VARCHAR(22)
DECLARE @Fecha_Cbte				DATETIME
DECLARE @Anio_Periodo			VARCHAR(4)
DECLARE @Mes_Periodo			VARCHAR(2)
DECLARE @Fecha_Presentacion		DATETIME
DECLARE @Id_Tarjeta				VARCHAR(10)
DECLARE @Comercio_Nro			VARCHAR(50)
DECLARE @Item					INT
/*FIN Variables Intermedias*/

/*Calculos intermerdios*/
SELECT	@Fecha_Presentacion = ISNULL(Fecha_Presentacion, '19000101'),
		@Id_Tarjeta			= ISNULL(Id_Tarjeta, '')
FROM Val_Tarjetas_Lotes
WHERE
Id_Tar_Lote = @pId_Tar_Lote


SELECT	@Tar_Nro		= ISNULL(DBO.CF_Cotiza(Nro), ''),
		@Item			= ISNULL(Item, 0)
FROM Val_Tarjetas_Lotes_Items 
WHERE
Id_Tar_Lote = @pId_Tar_Lote
AND Id_Trans = @pId_Trans


SELECT  @Fecha_Cbte		= ISNULL(Fecha, '19000101')
FROM Cbtes
WHERE 
Id_Trans = @pId_Trans

SET @Anio_Periodo = CAST(DATEPART(YY,@Fecha_Cbte) AS CHAR(4))
SET @Mes_Periodo = RIGHT('00' + CAST(MONTH(@Fecha_Cbte) AS VARCHAR),2)

SELECT @Comercio_Nro = ISNULL(Comercio_Nro, '')
FROM Valores_Tarjetas_Cred
WHERE
Id_Tarjeta = @Id_Tarjeta
/*FIN Calculos intermerdios*/

/*=============================================================================*/

/*Grabacion de los campos de la fila*/
SET @aId_Trans		= RIGHT('000000000' + CAST(@pId_Trans AS VARCHAR), 9)
SET @aTar_Nro		= RIGHT('0000000000000000000000' + @Tar_Nro, 16)
SET @aImporte		= RIGHT('00000000000' + CAST(CAST(@pImporte * 100 AS INT) AS VARCHAR), 11)
SET @aLibreA		= '                                                                                  '
SET @aDescripcion	= 'CUOTA MES: ' + @Anio_Periodo + '/' + @Mes_Periodo
SET @aFechaPresent	= RIGHT('00' + CAST(DAY(@Fecha_Presentacion) AS VARCHAR),2) + RIGHT('00' + CAST(MONTH(@Fecha_Presentacion) AS VARCHAR),2) + SUBSTRING(CAST(DATEPART(YY, @Fecha_Presentacion) AS CHAR(4)),3,2)
SET @aLibreB		= '                           '
SET @aNroComercio	= RIGHT('00000000000' + CAST(@Comercio_Nro AS VARCHAR), 11)
SET @aId_Moneda		= 'P'
SET @aLibreC		= '                     '
SET @aNroTicket		= RIGHT('0000' + CAST(@Item AS VARCHAR), 4)
SET @aLibreD		= '          '
SET @aCodOperacion	= '01' /*01 dÔö£┬«bito al usuario. 51 es para credito*/
SET @aLibreE		= '               '
/*FIN Grabacion de los campos de la fila*/

/*=============================================================================*/

/*GrabaciÔö£Ôöén de la Fila Completa*/
SET @Retorno			=	@aId_Trans		+
							@aTar_Nro		+
							@aImporte		+
							@aLibreA		+
							@aDescripcion	+
							@aFechaPresent	+
							@aLibreB		+
							@aNroComercio	+
							@aId_Moneda		+
							@aLibreC		+
							@aNroTicket		+
							@aLibreD		+
							@aCodOperacion	+
							@aLibreE
/*FIN GrabaciÔö£Ôöén de la Fila Completa*/

RETURN ISNULL(@Retorno, '')
END
GO



CREATE FUNCTION [dbo].[CF_BancoGalicia_Proveedores_OP_OPG_TX](@pId_Trans INT, @pId_Valor INT, @pNroSecuencia INT) 
RETURNS CHAR(271)
AS
BEGIN

/*================================================================================================================================*/

/*Variables del Archivo*/
DECLARE @Retorno						CHAR(58)

/*--------------------------------------------------------------------------------------------------------------------------------*/

DECLARE @aCBU					CHAR(22)	-- NRO: 01. NOMBRE: CBU/CVU/ALIAS/NRO CUENTA.	TIPO: A. TAM: 022. POS. INI: 001. POS_FIN: 022. OBSERVACION: CBU/CVU/ALIAS/NRO CUENTA
DECLARE @aIMP_PAGO				CHAR(14)	-- NRO: 02. NOMBRE: IMP_PAGO.					TIPO: D. TAM: 014. POS. INI: 023. POS_FIN: 037. OBSERVACION: Importe del Pago.
DECLARE @aMotivo				CHAR(10)	-- NRO: 03. NOMBRE: MOTIVO.						TIPO: A. TAM: 010. POS. INI: 038. POS_FIN: 048. OBSERVACION: Motivo obligatorio.
DECLARE @aDescripcion			CHAR(12)	-- NRO: 04. NOMBRE: DESCRIPCION.				TIPO: A. TAM: 012. POS. INI: 049. POS_FIN: 061. OBSERVACION: Descripcion del Pago.

/*FIN Variables del Archivo*/

/*================================================================================================================================*/

/*Variables de Calculo intermedio*/
DECLARE @Importe					DECIMAL(12,2)
DECLARE @Id_Proveedor				INT
DECLARE @Cuit						VARCHAR(19)
DECLARE @Cbu						VARCHAR(22)
DECLARE @Descrip_Cbte				VARCHAR(12)
/*FIN Variables de Calculo intermedio*/


/*Asignacion de variables*/
SELECT
@Importe			= ISNULL(Importe, 0)
FROM Valores
WHERE
Id_Trans = @pId_Trans
AND Id_Valor = @pId_Valor

SELECT
@Id_Proveedor	= ISNULL(Id_Proveedor, 0),
@Descrip_Cbte   = RTRIM(LTRIM(ISNULL(Id_Tipo_Cbte, ''))) + ' ' +  CONVERT(VARCHAR(8),RTRIM(LTRIM(ISNULL(Comprobante_Nro, ''))))
FROM Cbtes
WHERE
Id_Trans = @pId_Trans

SELECT
@Cuit			= LTRIM(RTRIM(ISNULL(Cuit, ''))),
@Cbu			= LTRIM(RTRIM(ISNULL(CBU, '')))
FROM Proveedores
WHERE
Id_Proveedor = @Id_Proveedor
/*FIN Asignacion de variables*/

/*================================================================================================================================*/

SET @aCBU			=	@Cbu

SET @aIMP_PAGO		=	CAST(CAST(ISNULL(@Importe, 0) AS DECIMAL(12, 2)) AS VARCHAR)

/*
Motivos:
varios, alquiler, cuota, expensas
*/

SET @aMotivo		= 'varios'	

SET @aDescripcion	= @Descrip_Cbte

/*================================================================================================================================*/

SET @Retorno =	@aCBU						+ ';' +
				@aIMP_PAGO					+ ';' +
				@aMotivo					+ ';' +
				@aDescripcion				

/*================================================================================================================================*/
					
RETURN @Retorno
END
GO


CREATE FUNCTION [dbo].[CF_BancoICBC_Proveedores_TX](@pId_Trans INT) 
RETURNS CHAR(280)
AS
BEGIN

DECLARE @Retorno			CHAR(280)
DECLARE @CUIT_Proveedor		VARCHAR(19)		
DECLARE @CBU				VARCHAR(22)
DECLARE @Contacto_Proveedor	VARCHAR(4)
DECLARE @Monto_OP			DECIMAL(20,2)
DECLARE @Mails				VARCHAR(150)

/*Seteo Variables Locales*/
SELECT	@CUIT_Proveedor			= ISNULL(P.Cuit, '19000101'),
		@CBU					= ISNULL(P.CBU,''),
		@Contacto_Proveedor		= 'ICBC',
		@Monto_OP				= C.Imp_Total,
		@Mails					= REPLACE(ISNULL(CONVERT(VARCHAR(150),P.Email),''),';',' ') 
FROM Cbtes C
	LEFT JOIN Proveedores P ON C.Id_Proveedor = P.Id_Proveedor
	LEFT JOIN Cbtes_Tipos CT ON C.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
WHERE Id_Trans = @pId_Trans
	AND CT.Compromete_Pagos = 1
	AND C.Imp_Total > 0
	AND P.Cuit IS NOT NULL AND P.Cuit <> ''
	AND P.CBU IS NOT NULL AND P.CBU <> ''
     
SET @Retorno =	@CUIT_Proveedor + ';' + @CBU + ';' + @Contacto_Proveedor + ';' + CONVERT(VARCHAR(50),@Monto_OP) + ';' + ''+ ';' + RTRIM(LTRIM(@Mails))

RETURN ISNULL(RTRIM(LTRIM(@Retorno)), '')
END
GO


CREATE FUNCTION [dbo].[CF_BancoICBC_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT) 
RETURNS CHAR(240)
AS
BEGIN

/*Variable de Retorno*/
DECLARE @Retorno			CHAR(240)
/*FIN Variable de Retorno*/

/*Variables del Archivo*/
DECLARE @aTipo_Reg		CHAR(1)  /*DESCRIPCION: Tipo de registro Valor="2". POS:01-01 - Longitud(1)*/
DECLARE @aTransaccion	CHAR(4)  /*DESCRIPCION: C├│digo de Transacci├│n de la entidad por defecto: Orden de d├®bito el valor="3700". POS:02-05 - Longitud(4)*/	
DECLARE @aCBU				CHAR(8)  /*DESCRIPCION: Bloque 1 de CBU. POS:06-13 - Longitud(8) */
DECLARE @aCBU_2			CHAR(14) /*DESCRIPCION: Bloque 2 de CBU. POS:14-27 - Longitud(24)*/
DECLARE @aId_Cliente		CHAR(22) /*DESCRIPCION: Identificador del cliente pasamos Id_cliente. POS:28-49 - Longitud(22) */
DECLARE @aImporte			CHAR(10) /*DESCRIPCION: Importe del D├®bito. POS:50-59 - Longitud(10). OBS: Formato: 8 enteros con 2 decimales, sin usar separador decimal. */
DECLARE @aId_Trans			CHAR(15) /*DESCRIPCION: Referencia ├║nivoca del Debito.Id_Trans. POS:60-74 - Longitud(15)*/
DECLARE @aFechaVenc		CHAR(8)   /*DESCRIPCION: Fecha de Vencimiento.Se completa con cero si no viene expl├¡cita. POS:75-82 - Longitud(8)*/
DECLARE @aFiller				CHAR(18) /*DESCRIPCION: Libre. POS: 83-100. Longitud(18). FORMATO: Alfanum├®rico. OBS: Completar con espacios.*/

/*FIN Variables del Archivo*/

/*Variables Intermedias*/
DECLARE @Tar_Nro					VARCHAR(22)
DECLARE @Fecha_Cbte					DATETIME
DECLARE @Fecha_Venc					DATETIME
DECLARE @Anio_Periodo				VARCHAR(4)
DECLARE @Mes_Periodo				VARCHAR(2)
DECLARE @Id_Tarjeta					VARCHAR(10)
DECLARE @Item						INT
DECLARE @Id_Cliente					INT
/*FIN Variables Intermedias*/

/*Calculos intermerdios*/

SELECT	@Tar_Nro	= ISNULL(DBO.CF_Cotiza(Nro), ''),
		@Item		= ISNULL(Item, 0),
		@Id_Cliente	= ISNULL(Id_Cliente,0)
FROM Val_Tarjetas_Lotes_Items 
WHERE
Id_Tar_Lote = @pId_Tar_Lote
AND Id_Trans = @pId_Trans


SELECT  @Fecha_Cbte		= ISNULL(Fecha, '19000101'),
		@Fecha_Venc		= ISNULL(Fecha_Venc, '19000101') 
FROM Cbtes
WHERE 
Id_Trans = @pId_Trans

SET @Anio_Periodo = CAST(DATEPART(YY,@Fecha_Cbte) AS CHAR(4))
SET @Mes_Periodo = RIGHT('00' + CAST(MONTH(@Fecha_Cbte) AS VARCHAR),2)

/*FIN Calculos intermerdios*/

/*=============================================================================*/

/*Grabacion de los campos de la fila*/

SET @aTipo_Reg		= '2'
SET @aTransaccion	=	'3700'
SET @aCBU				= RIGHT('00000000' + SUBSTRING(@Tar_Nro ,1,8),8) 
SET @aCBU_2			= RIGHT('00000000000000' + SUBSTRING(@Tar_Nro,10,22),14)
SET @aId_Cliente		= RIGHT('0000000000000000000000' + CAST(@Id_Cliente  AS VARCHAR), 22)
SET @aImporte		    = RIGHT('0000000000' + CAST(CAST(@pImporte * 100 AS INT) AS VARCHAR), 10)
SET @aId_Trans		= RIGHT('000000000000000' + CAST(@pId_Trans AS VARCHAR), 15)
SET @aFechaVenc		= CAST(DATEPART(YY, @Fecha_Venc) AS CHAR(4))  +  RIGHT('00' + CAST(MONTH(@Fecha_Venc) AS VARCHAR),2) + RIGHT('00' + CAST(DAY(@Fecha_Venc) AS VARCHAR),2)
SET @aFiller				=  '                  ' 

/*FIN Grabacion de los campos de la fila*/

/*=============================================================================*/

/*Grabaci├│n de la Fila Completa*/
SET @Retorno			=	@aTipo_Reg	+
									@aTransaccion	+
									@aCBU	+
									@aCBU_2	+
									@aId_Cliente	 +
									@aImporte +
									@aId_Trans	+
									@aFechaVenc +
									@aFiller				
									
/*FIN Grabaci├│n de la Fila Completa*/

RETURN ISNULL(@Retorno, '')
END
GO


CREATE FUNCTION dbo.CF_BancoMacroOtros_TX(@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT, @pModoDebug TINYINT) 
RETURNS CHAR(220)
AS
BEGIN

/*Variable de Retorno*/
DECLARE @Retorno			varCHAR(220)
/*FIN Variable de Retorno*/

/*Variables del Archivo*/
DECLARE @FillerInicio		CHAR(1) /*Relleno.  informar '0' cero*/
DECLARE @NroConvenio		CHAR(5) /*Numero de convenio en COBIS. obligatorio*/
DECLARE @NroServicio		CHAR(10)/*Numero de servicio en COBIS. obligatorio. De no existir informar blancos*/
DECLARE @NroEmpresaSueldos	CHAR(5) /*Numero de convenio AS en COBIS. obligatorio. De no existir informar ceros*/
DECLARE @CodBancoAdherente	CHAR(3) /*Codigo de Banco asignado por BCRA. obligatorio*/
DECLARE @CodSucursalCuenta	CHAR(4) /*Codigo de sucursal. Para Banco Macro  informar el numero de sucursal. Para otros bancos, informar las posiciones 4 a 7 del bloque 1 De la CBU*/
DECLARE @TipoCuenta			CHAR(1) /*Para cuentas de otros bancos no informar: se deja un espacio*/
DECLARE @CtaBancariaAdhere	CHAR(15)/*Cuenta COBIS del adherente. Para Bco Macro informar el numero de cuenta. Para otros bancos, informar el bloque 2 De la CBU y rellenar con un cero a izquierda.*/
DECLARE @IdActualAdhere		CHAR(22)/*Identif. Del cliente con la empresa. obligatorio*/
DECLARE @IdDebito			CHAR(15)/*Numero de factura  / recibo identif. obligatorio Identificacion del Comprobante*/
DECLARE @FuncionUsoMovim	CHAR(2) /*identifica la transaccion a efectuar. informar blancos*/
DECLARE @CodMovimRechazo	CHAR(4) /*obligatorio para rechazos. informar blancos*/
DECLARE @FechaVencimiento	CHAR(8) /*Fecha aplicacion / ABM. Obligatoria*/
DECLARE @MonedaDebito		CHAR(3) /*Moneda a debitar / debitada. 002 Dolares 080 Pesos*/
DECLARE @ImporteDebitar		CHAR(13)/*importe de la transaccion. No Informar punto decimal*/
DECLARE @FechaReintentoTope CHAR(8) /*Informar Ceros*/
DECLARE @ImporteDebitado	CHAR(13)/*Informar Ceros*/
DECLARE @NuevaSucBancaria	CHAR(4) /*Codigo de sucursal nueva. Informar Ceros*/
DECLARE @TipoCuentaB		CHAR(1) /*Tipo de cuenta COBIS. Informar Ceros*/
DECLARE @NuevaCuentaBanc	CHAR(15)/*Nueva cuenta COBIS del adherente. Informar Ceros*/
DECLARE @NuevaIdAdherente	CHAR(22)/*Nueva Identificacion Del cliente. Infromar Blancos*/
DECLARE @DatosRetorno		CHAR(40)/*Informar Blancos*/
DECLARE @SinUso				CHAR(5) /*Informar Blancos*/
DECLARE @FillerFin			CHAR(1) /*Relleno. Inforar '0' Cero*/
/*FIN Variables del Archivo*/

/*Variables Intermedias*/
DECLARE @Tar_Nro					VARCHAR(22)
DECLARE @Item						INT
DECLARE @Id_Banco_Macro				VARCHAR(10)
DECLARE @Id_Cliente					INT
DECLARE @CBU_PrimerBloque_IdBanco	CHAR(3)
DECLARE @CBU_PrimerBloque_IdSuc		CHAR(4)
DECLARE @CBU_SegundBloque_Cuenta	CHAR(15)
DECLARE @Separador					CHAR(1)
DECLARE @FormatoExportacion			TINYINT

/*FIN Variables Intermedias*/

/*TEST:*/

/* Modo de exportacion del archivo */
SET @FormatoExportacion = ISNULL((dbo.CF_xParam('Id_Ban_Macro_Ver')),0)

SELECT	@Tar_Nro = ISNULL(DBO.CF_Cotiza(Nro), ''), @Item = ISNULL(Item, 0) FROM Val_Tarjetas_Lotes_Items WHERE Id_Tar_Lote	= @pId_Tar_Lote AND Id_Trans = @pId_Trans
SET @CBU_PrimerBloque_IdBanco		= (SELECT CAST(SUBSTRING(@Tar_Nro,1,3) AS CHAR(3)))

IF(@CBU_PrimerBloque_IdBanco <> '285')
BEGIN

	SET @FillerInicio					= '0'
	SET @NroConvenio					= (SELECT LEFT(CAST(Comercio_Nro AS VARCHAR) + '00000', 5) FROM Valores_Tarjetas_Cred WHERE Id_Tarjeta = dbo.CF_xParam('Id_BancoMacro_333'))
	SET @NroServicio					= ISNULL((SELECT Valor_String FROM xParametros WHERE IdParametro = 'BcoMacro_Servicio'),'          ')
	SET @NroEmpresaSueldos				= (SELECT ISNULL(CONVERT(CHAR(5),Valor_Integer),'00000') FROM xParametros WHERE IdParametro = 'BcoMacro_Servicio')
	SET @CodBancoAdherente				= @CBU_PrimerBloque_IdBanco

	IF(@FormatoExportacion = 1)
	BEGIN
		SET @CodSucursalCuenta				= (SELECT RIGHT ('0' + CAST(SUBSTRING(@Tar_Nro,4,4) AS VARCHAR), 4))
		SET @CBU_SegundBloque_Cuenta		= (SELECT CAST(SUBSTRING(@Tar_Nro,9,15) AS CHAR(15)))
		SET @CtaBancariaAdhere				= '0' + @CBU_SegundBloque_Cuenta
	END
	ELSE
	BEGIN
		SET @CodSucursalCuenta				= (SELECT RIGHT ('0' + CAST(SUBSTRING(@Tar_Nro,4,4) AS VARCHAR), 4))
		SET @CBU_SegundBloque_Cuenta		= (SELECT CAST(SUBSTRING(@Tar_Nro,9,15) AS CHAR(15)))
		SET @CtaBancariaAdhere				= '0' + @CBU_SegundBloque_Cuenta
	END

	SET @TipoCuenta	= ' '/* No se informa al ser CBUs de otros Bancos */
	SET @IdActualAdhere					= (SELECT LEFT(CAST(Id_Cliente AS VARCHAR) + '0000000000000000000000', 22) FROM Cbtes WHERE Id_Trans = @pId_Trans)
	SET @IdDebito						= (SELECT LEFT(CAST(Id_Trans AS VARCHAR) + '               ', 15) FROM Cbtes WHERE Id_Trans = @pId_Trans)
	SET @FuncionUsoMovim				= '  '
	SET @CodMovimRechazo				= '    '
	SET @FechaVencimiento				= (SELECT CAST(DATEPART(YY,Fecha_Presentacion) AS CHAR(4)) + RIGHT('00' + CAST(DATEPART(mm,Fecha_Presentacion) AS VARCHAR),2) + RIGHT('00' + CAST(DATEPART(dd,Fecha_Presentacion) AS VARCHAR),2) FROM Val_Tarjetas_Lotes WHERE Id_Tar_Lote = @pId_Tar_Lote)
	SET @MonedaDebito		= '080'
	SET @ImporteDebitar		=	RIGHT( '0000000000000' + CAST(CAST(@pImporte * 100 AS INT) AS VARCHAR), 13) 
	SET @FechaReintentoTope = '00000000'
	SET @ImporteDebitado	= '0000000000000'	
	SET @NuevaSucBancaria	= '0000'	
	SET @TipoCuentaB		= '0'	
	SET @NuevaCuentaBanc	= '000000000000000'
	SET @NuevaIdAdherente	= '                      '
	SET @DatosRetorno		= '                                        '
	SET @SinUso				= '    '
	SET @FillerFin			= '0'

	SET @Retorno			=	  @FillerInicio
								+ @NroConvenio
								+ @NroServicio
								+ @NroEmpresaSueldos
								+ @CodBancoAdherente
								+ @CodSucursalCuenta
								+ @TipoCuenta
								+ @CtaBancariaAdhere
								+ @IdActualAdhere
								+ @IdDebito
								+ @FuncionUsoMovim
								+ @CodMovimRechazo
								+ @FechaVencimiento
								+ @MonedaDebito
								+ @ImporteDebitar
								+ @FechaReintentoTope
								+ @ImporteDebitado
								+ @NuevaSucBancaria
								+ @TipoCuentaB
								+ @NuevaCuentaBanc
								+ @NuevaIdAdherente
								+ @DatosRetorno
								+ @SinUso
								+ @FillerFin

END

IF(@pModoDebug = 1)
BEGIN
	SET @Retorno = (SELECT '@FillerInicio: '			+ @FillerInicio			+ ' ' +
							'@NroConvenio: '			+ @NroConvenio			+ ' ' +
							'@NroServicio: '			+ @NroServicio			+ ' ' +
							'@NroEmpresaSueldos: '		+ @NroEmpresaSueldos	+ ' ' +
							'@CodBancoAdherente: '		+ @CodBancoAdherente	+ ' ' +
							'@CodSucursalCuenta: '		+ @CodSucursalCuenta	+ ' ' +
							'@TipoCuenta: '				+ @TipoCuenta			+ ' ' +
							'@CtaBancariaAdhere: '		+ @CtaBancariaAdhere	+ ' ' +
							'@IdActualAdhere: '			+ @IdActualAdhere		+ ' ' +
							'@IdDebito: '				+ @IdDebito				+ ' ' +
							'@FuncionUsoMovim: '		+ @FuncionUsoMovim		+ ' ' +
							'@CodMovimRechazo: '		+ @CodMovimRechazo		+ ' ' +
							'@FechaVencimiento: '		+ @FechaVencimiento		+ ' ' +
							'@MonedaDebito: '			+ @MonedaDebito			+ ' ' +
							'@ImporteDebitar: '			+ @ImporteDebitar		+ ' ' +
							'@FechaReintentoTope: '		+ @FechaReintentoTope	+ ' ' +
							'@ImporteDebitado: '		+ @ImporteDebitado		+ ' ' +
							'@NuevaSucBancaria: '		+ @NuevaSucBancaria		+ ' ' +
							'@TipoCuentaB: '			+ @TipoCuentaB			+ ' ' +
							'@NuevaCuentaBanc: '		+ @NuevaCuentaBanc		+ ' ' +
							'@NuevaIdAdherente: '		+ @NuevaIdAdherente		+ ' ' +
							'@DatosRetorno: '			+ @DatosRetorno			+ ' ' +
							'@SinUso: '					+ @SinUso				+ ' ' +
							'@FillerFin: '				+ @FillerFin)
END

RETURN @Retorno
END
GO


CREATE FUNCTION dbo.CF_BancoMacro_Proveedores_OP_OPG_TX(@pId_Trans INT, @pId_Valor INT, @pNroSecuencia INT) 
RETURNS CHAR(285)
AS
BEGIN

/*================================================================================================================================*/

/*Variables del Archivo*/
DECLARE @Retorno						CHAR(285)

/*--------------------------------------------------------------------------------------------------------------------------------*/

DECLARE @aTTD_BNF_ID			CHAR(2)		-- NRO: 01. NOMBRE: TTD_BNF_ID.				TIPO: N. TAM: 002. POS. INI: 001. POS_FIN: 002. OBSERVACION: Tipo de documento del beneficiario
DECLARE @aBNF_NUMDOC			CHAR(11)	-- NRO: 02. NOMBRE: BNF_NUMDOC.				TIPO: N. TAM: 011. POS. INI: 003. POS_FIN: 013. OBSERVACION: Numero de Documento del Beneficiario (sin guiones ni puntos)
DECLARE @aSUC_ENTREGA			CHAR(3)		-- NRO: 03. NOMBRE: SUC_ENTREGA.			TIPO: N. TAM: 003. POS. INI: 014. POS_FIN: 016. OBSERVACION: Sucursal de Entrega del cheque. (Unicamente para las modalidades 1 y 9. Para el resto va la Sucursal de radicacion de la cuenta de pago)
DECLARE @aOPG_IDOPGCLI			CHAR(30)	-- NRO: 04. NOMBRE: OPG_IDOPGCLI.			TIPO: A. TAM: 030. POS. INI: 017. POS_FIN: 046. OBSERVACION: Clave Identificatoria de la Orden de Pago segun el cliente. (Id. de pago no puede repetirse nunca. Debe ser un dato univoco)
DECLARE @aOPG_ORDENALT			CHAR(120)	-- NRO: 05. NOMBRE: OPG_ORDENALT.			TIPO: A. TAM: 120. POS. INI: 047. POS_FIN: 166. OBSERVACION: Orden del pago o Razon social o denominacion del beneficiario.
DECLARE @aOPG_IMP_PAGO			CHAR(15)	-- NRO: 06. NOMBRE: OPG_IMP_PAGO.			TIPO: D. TAM: 015. POS. INI: 167. POS_FIN: 181. OBSERVACION: Importe del Pago.
DECLARE @aCTA_CUENTADEBITO		CHAR(15)	-- NRO: 07. NOMBRE: CTA_CUENTADEBITO.		TIPO: N. TAM: 015. POS. INI: 182. POS_FIN: 196. OBSERVACION: Cuenta de debito (de la empresa que paga)
DECLARE @aOPG_CUENTAPAGO		CHAR(22)	-- NRO: 08. NOMBRE: OPG_CUENTAPAGO.			TIPO: N. TAM: 022. POS. INI: 197. POS_FIN: 218. OBSERVACION: Para modalidad de pago 2 o 4 va la cuenta del beneficiario (CBU). Para modalidad de pago 1, 6, 8 y 9 va el Numero de Cheque de la chequera entregada.
DECLARE @aMPG_ID				CHAR(2)		-- NRO: 09. NOMBRE: MPG_ID.					TIPO: N. TAM: 002. POS. INI: 219. POS_FIN: 220. OBSERVACION: Modalidad de Pago
DECLARE @aOPG_MAR_REGCHQ		CHAR(1)		-- NRO: 10. NOMBRE: OPG_MAR_REGCHQ.			TIPO: N. TAM: 001. POS. INI: 221. POS_FIN: 221. OBSERVACION: Marca de Registracion de Cheque. (1=Con la leyenda No a la Orden, 2=Sin la leyenda No a la Orden). (Para otras modalidades de pago (no cheques), completar con 0)
DECLARE @aOPG_FEC_PAGO			CHAR(10)	-- NRO: 11. NOMBRE: OPG_FEC_PAGO.			TIPO: D. TAM: 010. POS. INI: 222. POS_FIN: 231. OBSERVACION: Fecha de Emision del pago en el cheque.
DECLARE @aOPG_FEC_PAGODIFERIDO	CHAR(10)	-- NRO: 12. NOMBRE: OPG_FEC_PAGODIFERIDO.	TIPO: D. TAM: 010. POS. INI: 232. POS_FIN: 241. OBSERVACION: Fecha de Pago Diferido (Requerido solo para modalidad de pago "cheque de pago diferido")
DECLARE @aUSR_FIRMANTE1			CHAR(10)	-- NRO: 13. NOMBRE: USR_FIRMANTE1.			TIPO: A. TAM: 010. POS. INI: 242. POS_FIN: 251. OBSERVACION: Dejar en blanco
DECLARE @aUSR_FIRMANTE2			CHAR(10)	-- NRO: 14. NOMBRE: USR_FIRMANTE2.			TIPO: A. TAM: 010. POS. INI: 252. POS_FIN: 261. OBSERVACION: Dejar en blanco
DECLARE @aUSR_FIRMANTE3			CHAR(10)	-- NRO: 15. NOMBRE: USR_FIRMANTE3.			TIPO: A. TAM: 010. POS. INI: 262. POS_FIN: 271. OBSERVACION: Dejar en blanco
/*FIN Variables del Archivo*/

/*================================================================================================================================*/

/*Variables de Calculo intermedio*/
DECLARE @Importe					DECIMAL(12,2)
DECLARE @Fecha_Cbte					DATETIME
DECLARE @Id_Tipo_Val				CHAR(3)
DECLARE @Fecha_Emision				DATETIME
DECLARE @Fecha_Acreditacion			DATETIME
DECLARE @Transferible				TINYINT
DECLARE @Id_Proveedor				INT
DECLARE @Cuit						VARCHAR(19)
DECLARE @Valor_Nro					INT
DECLARE @Separador					CHAR(1)
/*FIN Variables de Calculo intermedio*/


/*Asignacion de variables*/

SET @Separador = CHAR(9)

SELECT
@Importe			= ISNULL(Importe, 0),
@Id_Tipo_Val		= ISNULL(Id_Tipo_Val, '   '),
@Fecha_Emision		= CONVERT(DATE, ISNULL(Fecha_Emision, '19000101')),
@Fecha_Acreditacion	= CONVERT(DATE, ISNULL(Fecha_Acreditacion, '19000101')),
@Transferible		= ISNULL(Transferible, 0),
@Valor_Nro			= ISNULL(Valor_Nro, 0)
FROM Valores
WHERE
Id_Trans = @pId_Trans
AND Id_Valor = @pId_Valor

SELECT
@Fecha_Cbte		= ISNULL(Fecha, '19000101'),
@Id_Proveedor	= ISNULL(Id_Proveedor, 0)
FROM Cbtes
WHERE
Id_Trans = @pId_Trans

SELECT
@Cuit			= LTRIM(RTRIM(ISNULL(Cuit, '')))
FROM Proveedores
WHERE
Id_Proveedor = @Id_Proveedor
/*FIN Asignacion de variables*/

/*================================================================================================================================*/

/*
Tipos de Documento:

3 = D.N.I.
10 = C.U.I.T “ Clave Unica de identificacion tributaria
11 = Cod. de identidad de paises limetrofes
13 = C.U.I.L. - Clave Unica de Ident. Laboral
14 = C.D.I. - Clave de Identificacion
*/
SET @aTTD_BNF_ID			= '10'

SET @aBNF_NUMDOC			= SUBSTRING(@Cuit, 1, 11)

SET @aOPG_IDOPGCLI			= (SELECT RIGHT('000000000000000000000000000000' + CAST(@pId_Trans AS VARCHAR), 30))

SET @aOPG_ORDENALT			= dbo.CF_Cbte_Descrip(@pId_Trans)

SET @aOPG_IMP_PAGO			= (SELECT RIGHT('000000000000000' + CAST(CAST((ISNULL(@Importe, 0)) * 100 AS INT) AS VARCHAR), 15))

SET @aCTA_CUENTADEBITO		= (SELECT RIGHT('000000000000000' + dbo.CF_xParam('BcoMacro_NroCtaDeb'), 15))



/*
Modalidades de Pago:

1 = Cheque Comn
2 = Acreditacion en Cuenta
4 = Acreditacion en Cuenta Otros Bancos
5 = Efectivo
9 = Cheque de Pago Diferido
6 = ECHEQ Comn
8 = ECHEQ de Pago Diferido
*/
IF(@Id_Tipo_Val IN ('CH3', 'CHP'))
BEGIN
	SET @aMPG_ID				= '1'
END
ELSE
BEGIN
	SET @aMPG_ID				= '2'
END	

IF(@aMPG_ID IN ('1','9'))
BEGIN
	SET @aSUC_ENTREGA			= (SELECT RIGHT('000' + dbo.CF_xParam('BcoMacro_SucEntrega'), 3))
END
ELSE
BEGIN
	SET @aSUC_ENTREGA			= (SELECT RIGHT('000' + dbo.CF_xParam('BcoMacro_SucEntrega'), 3))
END

IF(@aMPG_ID IN ('2','4'))
BEGIN
	SET @aOPG_CUENTAPAGO		= (SELECT RIGHT('0000000000000000000000' + CAST(@Valor_Nro AS VARCHAR), 22))
END
ELSE
BEGIN
	SET @aOPG_CUENTAPAGO		= (SELECT RIGHT('0000000000000000000000' + CAST(@Valor_Nro AS VARCHAR), 22))
END

/*
Marca de Registracion de los Cheques

1 = Cheque cruzado con leyenda "No a la Orden"
2 = Cheque cruzado sin leyenda "No a la Orden"
*/
IF(@Fecha_Emision = @Fecha_Acreditacion)
BEGIN
	/*Cheque al dia*/
	IF(@Transferible = 1)
	BEGIN
		/*No a la orden*/
		SET @aOPG_MAR_REGCHQ	= 1
	END
	ELSE
	BEGIN
		/*Sin leyenda no a la orden*/
		SET @aOPG_MAR_REGCHQ	= 2
	END
END
ELSE
BEGIN
	/*Cheque Pago Diferido (CPD)*/
	IF(@Transferible = 1)
	BEGIN
		/*No a la orden*/
		SET @aOPG_MAR_REGCHQ	= 1
	END
	ELSE
	BEGIN
		/*Sin leyenda no a la orden*/
		SET @aOPG_MAR_REGCHQ	= 2
	END
END	



SET @aOPG_FEC_PAGO			= (/*DD*/RIGHT('00' + CAST(DATEPART(dd, @Fecha_Cbte) AS VARCHAR),2) + '/' + /*MM*/RIGHT('00' + CAST(DATEPART(mm, @Fecha_Cbte) AS VARCHAR),2) + '/' + /*AAAA*/CAST(DATEPART(YY, @Fecha_Cbte) AS CHAR(4)))

SET @aOPG_FEC_PAGODIFERIDO	= (/*DD*/RIGHT('00' + CAST(DATEPART(dd, @Fecha_Cbte) AS VARCHAR),2) + '/' + /*MM*/RIGHT('00' + CAST(DATEPART(mm, @Fecha_Cbte) AS VARCHAR),2) + '/' + /*AAAA*/CAST(DATEPART(YY, @Fecha_Cbte) AS CHAR(4)))

SET @aUSR_FIRMANTE1			= '          '

SET @aUSR_FIRMANTE2			= '          '

SET @aUSR_FIRMANTE3			= '          '

/*================================================================================================================================*/

SET @Retorno =	@aTTD_BNF_ID				+ @Separador +
				@aBNF_NUMDOC				+ @Separador +
				@aSUC_ENTREGA				+ @Separador +
				@aOPG_IDOPGCLI				+ @Separador +
				@aOPG_ORDENALT				+ @Separador +
				@aOPG_IMP_PAGO				+ @Separador +
				@aCTA_CUENTADEBITO			+ @Separador +
				@aOPG_CUENTAPAGO			+ @Separador +
				@aMPG_ID					+ @Separador +
				@aOPG_MAR_REGCHQ			+ @Separador +
				@aOPG_FEC_PAGO				+ @Separador +
				@aOPG_FEC_PAGODIFERIDO		+ @Separador +
				@aUSR_FIRMANTE1				+ @Separador +
				@aUSR_FIRMANTE2				+ @Separador +
				@aUSR_FIRMANTE3

/*================================================================================================================================*/
					
RETURN @Retorno
END
GO


CREATE FUNCTION dbo.CF_BancoMacro_TX(@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT) 
RETURNS CHAR(220)
AS
BEGIN

/*Variable de Retorno*/
DECLARE @Retorno			CHAR(220)
/*FIN Variable de Retorno*/

/*Variables del Archivo*/
DECLARE @FillerInicio		CHAR(1) /*Relleno.  informar '0' cero*/
DECLARE @NroConvenio		CHAR(5) /*Numero de convenio en COBIS. obligatorio*/
DECLARE @NroServicio		CHAR(10)/*Numero de servicio en COBIS. obligatorio. De no existir informar blancos*/
DECLARE @NroEmpresaSueldos	CHAR(5) /*Numero de convenio AS en COBIS. obligatorio. De no existir informar ceros*/
DECLARE @CodBancoAdherente	CHAR(3) /*Codigo de Banco asignado por BCRA. obligatorio*/
DECLARE @CodSucursalCuenta	CHAR(4) /*Codigo de sucursal. Para Banco Macro  informar el numero de sucursal. Para otros bancos, informar las posiciones 4 a 7 del bloque 1 De la CBU*/
DECLARE @TipoCuenta			CHAR(1) /*Tipo de cuenta COBIS. 3 - Cta Cte ,  4 - Caja de Ahorros para cuentas de Banco Macro - Bansud. Para cuentas de otros bancos no informar*/
DECLARE @CtaBancariaAdhere	CHAR(15)/*Cuenta COBIS del adherente. Para Bco Macro informar el numero de cuenta. Para otros bancos, informar el bloque 2 De la CBU y rellenar con un cero a izquierda.*/
DECLARE @IdActualAdhere		CHAR(22)/*Identif. Del cliente con la empresa. obligatorio*/
DECLARE @IdDebito			CHAR(15)/*Numero de factura  / recibo identif. obligatorio Identificacion del Comprobante*/
DECLARE @FuncionUsoMovim	CHAR(2) /*identifica la transaccion a efectuar. informar blancos*/
DECLARE @CodMovimRechazo	CHAR(4) /*obligatorio para rechazos. informar blancos*/
DECLARE @FechaVencimiento	CHAR(8) /*Fecha aplicaci├ö├Â┬ú├ö├Â├®n / ABM. Obligatoria*/
DECLARE @MonedaDebito		CHAR(3) /*Moneda a debitar / debitada. 002 Dolares 080 Pesos*/
DECLARE @ImporteDebitar		CHAR(13)/*importe de la transaccion. No Informar punto decimal*/
DECLARE @FechaReintentoTope CHAR(8) /*Informar Ceros*/
DECLARE @ImporteDebitado	CHAR(13)/*Informar Ceros*/
DECLARE @NuevaSucBancaria	CHAR(4) /*Codigo de sucursal nueva. Informar Ceros*/
DECLARE @TipoCuentaB		CHAR(1) /*Tipo de cuenta COBIS. Informar Ceros*/
DECLARE @NuevaCuentaBanc	CHAR(15)/*Nueva cuenta COBIS del adherente. Informar Ceros*/
DECLARE @NuevaIdAdherente	CHAR(22)/*Nueva Identificacion Del cliente. Infromar Blancos*/
DECLARE @DatosRetorno		CHAR(40)/*Informar Blancos*/
DECLARE @SinUso				CHAR(5) /*Informar Blancos*/
DECLARE @FillerFin			CHAR(1) /*Relleno. Inforar '0' Cero*/

/*FIN Variables del Archivo*/

/*Variables Intermedias*/
DECLARE @Tar_Nro					VARCHAR(22)
DECLARE @Item						INT
DECLARE @Id_Banco_Macro				VARCHAR(10)
DECLARE @Id_Cliente					INT
DECLARE @CBU_PrimerBloque_IdBanco	CHAR(3)
DECLARE @CBU_PrimerBloque_IdSuc		CHAR(4)
DECLARE @CBU_SegundBloque_Cuenta	CHAR(13)
DECLARE @CBU_SegundBloque_DigVerifC CHAR(1)
DECLARE @Separador					CHAR(1)
DECLARE @FormatoExportacion			TINYINT

/*FIN Variables Intermedias*/

/* Modo de exportacion del archivo */

SET @FormatoExportacion = ISNULL((SELECT Valor_Integer FROM xParametros WHERE IdParametro = 'Id_Ban_Macro_Ver'),0)

/*Calculos intermerdios*/

SELECT	@Tar_Nro		= ISNULL(DBO.CF_Cotiza(Nro), ''),
		@Item			= ISNULL(Item, 0) 
		FROM Val_Tarjetas_Lotes_Items 
		WHERE Id_Tar_Lote = @pId_Tar_Lote 
		AND Id_Trans = @pId_Trans

SET @Id_Banco_Macro				= ISNULL((SELECT Valor_String FROM xParametros WHERE IdParametro = 'Id_BancoMacro'),'')
SET @Id_Cliente					= (SELECT Id_Cliente FROM Cbtes WHERE Id_Trans = @pId_Trans)

IF(@FormatoExportacion = 1)
BEGIN
	SET @CBU_PrimerBloque_IdSuc		= (SELECT RIGHT ('0' + CAST(SUBSTRING(@Tar_Nro,5,3) AS VARCHAR), 4))
END
ELSE
BEGIN
	SET @CBU_PrimerBloque_IdSuc		= (SELECT RIGHT ('0' + CAST(SUBSTRING(@Tar_Nro,5,4) AS VARCHAR), 4))
END

SET @CBU_PrimerBloque_IdBanco	= (SELECT CAST(SUBSTRING(@Tar_Nro,1,3) AS CHAR(3)))

IF(@FormatoExportacion = 1)
BEGIN
	SET @CBU_SegundBloque_Cuenta	= (SELECT CAST(SUBSTRING(@Tar_Nro,11,11) AS CHAR(11))) -- SE MODIFICA POR TICKET #000400 EL 11/01/2022
END
ELSE
BEGIN
	SET @CBU_SegundBloque_Cuenta	= (SELECT CAST(SUBSTRING(@Tar_Nro,9,13) AS CHAR(13)))
END

SET @CBU_SegundBloque_DigVerifC	= (SELECT CAST(SUBSTRING(@Tar_Nro,22,1) AS CHAR(1)))
SET @TipoCuenta					= (SELECT CAST(SUBSTRING(@Tar_Nro,9,10) AS CHAR(1)))

/* FIN Calculos intermerdios*/

/*Grabacion de los campos de la fila*/
SET @FillerInicio		= '0'
SET @NroConvenio		= (SELECT LEFT(CAST(Comercio_Nro AS VARCHAR) + '00000', 5) FROM Valores_Tarjetas_Cred WHERE  Id_Tarjeta = @Id_Banco_Macro)	
SET @NroServicio		= ISNULL((SELECT Valor_String FROM xParametros WHERE IdParametro = 'BcoMacro_Servicio'),'          ')
SET @NroEmpresaSueldos	= (SELECT ISNULL(CONVERT(CHAR(5),Valor_Integer),'00000') FROM xParametros WHERE IdParametro = 'BcoMacro_Servicio')
SET @CodBancoAdherente	= @CBU_PrimerBloque_IdBanco
SET @CodSucursalCuenta	= @CBU_PrimerBloque_IdSuc

----------------------------------------------Se agrega tipo de cuenta pedido ticket 24126-----------------------------------------------------------------------
IF (@CBU_PrimerBloque_IdBanco = '285') /*285 = C├ö├Â┬ú├ö├Â├®d. Banco Macro*/
BEGIN
	IF (@TipoCuenta = 3 OR @TipoCuenta = 4) /*3 - Cta. Cte. ,  4 - Caja de Ahorros*/
	BEGIN
		SET @TipoCuenta	= @TipoCuenta
	END 
END
ELSE
	BEGIN
		SET @TipoCuenta	= ' '/*No se informa*/
	END
------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@FormatoExportacion = 1)
BEGIN
	SET @CtaBancariaAdhere	= @TipoCuenta + (SELECT RIGHT (CAST(SUBSTRING(@Tar_Nro,5,3) AS VARCHAR), 4)) + @CBU_SegundBloque_Cuenta -- SE MODIFICA POR TICKET #000400 EL 11/01/2022
END
ELSE
BEGIN
	SET @CtaBancariaAdhere	= '0' + @CBU_SegundBloque_Cuenta + @CBU_SegundBloque_DigVerifC
END

SET @IdActualAdhere		= (SELECT LEFT(CAST(Id_Cliente AS VARCHAR) + '                      ', 22) FROM Cbtes WHERE Id_Trans = @pId_Trans)
SET @IdDebito			= (SELECT LEFT(CAST(Id_Trans AS VARCHAR) + '               ', 15) FROM Cbtes WHERE Id_Trans = @pId_Trans)
SET @FuncionUsoMovim	= '  '
SET @CodMovimRechazo	= '    '
--SET @FechaVencimiento	= (SELECT CAST(DATEPART(YY,Fecha_Venc) AS CHAR(4)) + 
--						   RIGHT('00' + CAST(DATEPART(mm,Fecha_Venc) AS VARCHAR),2) + 
--						   RIGHT('00' + CAST(DATEPART(dd,Fecha_Venc) AS VARCHAR),2) 
--						   FROM Cbtes WHERE Id_Trans = @pId_Trans)
------------------------------------------------------------------------------------------------------------------------------------------------------------------
SET @FechaVencimiento	= (SELECT CAST(DATEPART(YY,Fecha_Presentacion) AS CHAR(4)) +					 /*Se modifica la fecha venc para que tome la de Val_Tarjetas_Lotes_Items*/
						   RIGHT('00' + CAST(DATEPART(mm,Fecha_Presentacion) AS VARCHAR),2) + 
						   RIGHT('00' + CAST(DATEPART(dd,Fecha_Presentacion) AS VARCHAR),2)  
						   FROM Val_Tarjetas_Lotes WHERE Id_Tar_Lote = @pId_Tar_Lote)

------------------------------------------------------------------------------------------------------------------------------------------------------------------

SET @MonedaDebito		= '080' /*Siempre Pesos*/
SET @ImporteDebitar		=	RIGHT( '0000000000000' + CAST(CAST(@pImporte * 100 AS INT) AS VARCHAR), 13) 
SET @FechaReintentoTope = '00000000'
SET @ImporteDebitado	= '0000000000000'
SET @NuevaSucBancaria	= '0000'
SET @TipoCuentaB		= '0'
SET @NuevaCuentaBanc	= '000000000000000'
SET @NuevaIdAdherente	= '                      '
SET @DatosRetorno		= '                                        '
SET @SinUso				= '     '
SET @FillerFin			= '0'

/*FIN Grabacion de los campos de la fila*/

SET @Retorno			=			@FillerInicio
							+ @NroConvenio
							+ @NroServicio
							+ @NroEmpresaSueldos
							+ @CodBancoAdherente
							+ @CodSucursalCuenta
							+ @TipoCuenta
							+ @CtaBancariaAdhere
							+ @IdActualAdhere
							+ @IdDebito
							+ @FuncionUsoMovim
							+ @CodMovimRechazo
							+ @FechaVencimiento
							+ @MonedaDebito
							+ @ImporteDebitar
							+ @FechaReintentoTope
							+ @ImporteDebitado
							+ @NuevaSucBancaria
							+ @TipoCuentaB
							+ @NuevaCuentaBanc
							+ @NuevaIdAdherente
							+ @DatosRetorno
							+ @SinUso
							+ @FillerFin



RETURN @Retorno
END
GO


CREATE FUNCTION [dbo].[CF_BancoPagoTIC_API_AR_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT, @pPeriodo DATETIME) 
RETURNS VARCHAR(8000)
AS
BEGIN

/*Variable de Retorno*/
DECLARE @Retorno				VARCHAR(8000)
/*FIN Variable de Retorno*/

/*Variables Locales*/
DECLARE @body_Json				VARCHAR(8000)
DECLARE @detalle_json			VARCHAR(8000)
DECLARE @Url_WebService			VARCHAR(255)
DECLARE @IPN_Pagos				VARCHAR(255)
DECLARE @Url_Envio				VARCHAR(255)
DECLARE @Tar_Nro				VARCHAR(50)
DECLARE @Id_Moneda				VARCHAR(10)
DECLARE @Fecha_Vence			DATETIME
DECLARE @Fecha_Vence_VC			VARCHAR(25)
DECLARE @Fecha_Ult_Pago_VC		VARCHAR(25)
DECLARE @Id_Concepto			VARCHAR(10)
DECLARE @Concepto_Descrip		VARCHAR(100)
DECLARE @Lote_Trans				VARCHAR(16)
/*FIN Variables Locales*/

/*--------------------------------------------------------------------------------------------------------------------------------*/

SELECT 
@Url_WebService		= ISNULL(Url_WebService, ''),
@IPN_Pagos			= ISNULL(IPN_Pagos, '')
FROM AR_PAGOTIC_WS_Configuracion
WHERE
Id_Configuracion = 0

SELECT 
@Tar_Nro		= ISNULL(DBO.SF_COTIZA(Nro), '')
FROM Val_Tarjetas_Lotes_Items VTLI
WHERE
Id_Tar_Lote = @pId_Tar_Lote
AND Id_Trans = @pId_Trans

--SET @Url_Envio = @Url_WebService + 'suscripciones/adhesion/' + @Tar_Nro + '/pago'

SET @Lote_Trans = RIGHT('00000' + CAST(@pId_Tar_Lote AS VARCHAR), 5) + '-' + RIGHT('0000000000' + CAST(@pId_Trans AS VARCHAR), 10)

SET @Id_Moneda = 'ARS'

---SET @Fecha_Vence = dbo.CF_EOMONTH(@pPeriodo) 

SET @Fecha_Vence = dbo.CFU_PMONTH(@pPeriodo) /*2023-01-04   Se Agrega para que siempre mande el 10 del mes*/

----SET @Fecha_Vence='20221222'

SET @Fecha_Vence_VC =	CAST(YEAR(@Fecha_Vence) AS VARCHAR)
						+ '-' 
						+ RIGHT('00' + CAST(MONTH(@Fecha_Vence) AS VARCHAR), 2) 
						+ '-' 
						+ RIGHT('00' + CAST(DAY(@Fecha_Vence) AS VARCHAR), 2)
						+ 'T'
						+ '23:59:00-0300'


SET @Fecha_Ult_Pago_VC = dbo.CF_EOMONTH(@pPeriodo) 

SET @Fecha_Ult_Pago_VC =	CAST(YEAR(@Fecha_Ult_Pago_VC) AS VARCHAR)
						+ '-' 
						+ RIGHT('00' + CAST(MONTH(@Fecha_Ult_Pago_VC) AS VARCHAR), 2) 
						+ '-' 
						+ RIGHT('00' + CAST(DAY(@Fecha_Ult_Pago_VC) AS VARCHAR), 2)
						+ 'T'
						+ '23:59:00-0300'



-----SET @Fecha_Ult_Pago_VC =@Fecha_Vence_VC
-----SET @Fecha_Ult_Pago_VC ='2022-12-31T23:59:59-0300'

SELECT 
TOP 1
@Id_Concepto			= LTRIM(RTRIM(CI.Id_Producto)),
@Concepto_Descrip		= LTRIM(RTRIM(PR.Descripcion_Resumida))
FROM Cbtes_Items CI, Productos PR
WHERE
CI.Id_Producto = PR.Id_Producto
AND Id_Trans = @pId_Trans

/*--------------------------------------------------------------------------------------------------------------------------------*/

SET @detalle_json = '{' +
					dbo.CF_Json_ParsearVariable('external_reference', @pId_Trans, 'VARCHAR(10)') + ',' +
					dbo.CF_Json_ParsearVariable('concept_id', @Id_Concepto, 'VARCHAR(10)') + ',' +
					dbo.CF_Json_ParsearVariable('concept_description', @Concepto_Descrip, 'VARCHAR(100)') + ',' +
					dbo.CF_Json_ParsearVariable('amount', @pImporte, 'VARCHAR(10)') +
					'}'


SET @body_Json = '{' +
					dbo.CF_Json_ParsearVariable('currency_id', @Id_Moneda, 'VARCHAR(15)') + ',' +
					dbo.CF_Json_ParsearVariable('external_transaction_id', @Lote_Trans, 'VARCHAR(16)') + ',' +
					dbo.CF_Json_ParsearVariable('due_date', @Fecha_Vence_VC, 'VARCHAR(25)') + ',' +
					dbo.CF_Json_ParsearVariable('last_due_date', @Fecha_Ult_Pago_VC, 'VARCHAR(25)') + ',' +
					dbo.CF_Json_ParsearVariable('notification_url', @IPN_Pagos, 'VARCHAR(255)') + ',' +
					'"details":[' + @detalle_json + ']' + 
					'}'

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*
SET @Retorno =	@Url_Envio 
				+ ';'
				+ @body_Json
*/

SET @Retorno =  @body_Json

RETURN @Retorno
END

--SELECT dbo.CF_BancoPagoTIC_API_AR_TX(Id_Trans, Importe, Id_Tar_Lote, '20220501') FROM Val_Tarjetas_Lotes_Items WHERE Id_Tar_Lote = 3

/*
RTA EJ:
{
	"currency_id":"ARS",
	"external_transaction_id":"00003-0000330824",
	"due_date":"2022-05-31T23:59:59-0300",
	"last_due_date":"2022-05-31T23:59:59-0300",
	"notification_url":"https://clubtesting.miclub.info/utils/pagotic_ipn_pagos.php",
	"details":[
					{
						"external_reference":"330824",
						"concept_id":"CS",
						"concept_description":"CUOTA SOCIAL",
						"amount":"1100.00"
					}
				]
}
*/
GO



CREATE FUNCTION [dbo].[CF_BancoPatagonia_TX](@pId_Trans INT, @pTarNro VARCHAR(22), @pFecha_Venc DATETIME, @pImporte DECIMAL(12,2)) 
RETURNS CHAR(200)
AS
BEGIN

/*Variable de Retorno*/
DECLARE @Retorno			CHAR(200)
/*FIN Variable de Retorno*/

/*Variables del Archivo*/
/*Para todos los tipos de novedad*/
DECLARE @aTipoNovedad				CHAR(1)		/*Tipo de Novedad / D - Debitos*/
DECLARE @aCUIT						CHAR(11)	/*CUIT/L DNI del Cliente*/
/*Bloque 1 de la CBU*/
DECLARE @aEntidad					CHAR(3)		/*Entidad*/
DECLARE @aSucursal					CHAR(4)		/*Sucursal*/
DECLARE @aDigVerifBloq1				CHAR(1)		/*Digito Verificador Bloque 1*/
/*Bloque 2 de la CBU*/
DECLARE @aTipoCuenta				CHAR(2)		/*Tipo de Cuenta*/
DECLARE @aNroCuenta					CHAR(11)	/*Nro. de Cuenta*/
DECLARE @aDigVerifBloq2				CHAR(1)		/*Digito Verificador Bloque 2*/
/*Segun tabla COELSA - ACH*/
DECLARE @aIdentClientePag			CHAR(22)	/*Identificador Cliente Pagador*/
DECLARE @aFechaVenc					CHAR(8)		/*Fecha de Vencimiento*/
DECLARE @aProdPrestacion			CHAR(10)	/*Producto/Prestacion*/
/*Para Adhesiones*/
DECLARE @aADHTipoDoc				CHAR(4)		/*Tipo de Documento*/
DECLARE @aADHNroDoc					CHAR(11)	/*Nro. de Documento*/
/*Para D├Übitos, Reversiones*/
DECLARE @aDEBRefDeb					CHAR(15)	/*Referencia del d├Übito*/
DECLARE @aDEBImporte				CHAR(10)	/*Importe (8 enteros y 2 decimales)*/
DECLARE @aDEBTipoMon				CHAR(1)		/*Tipo de Moneda./ P:Pesos o D:Dolares*/
/*Para notificaciones de Cambio en Empresa Originante*/
DECLARE @aNOTEMPORIIdentCliPag		CHAR(22)	/*Identificador de Cliente Nuevo*/
/*Para Notificaciones de Cambio en Entidad Receptoras*/
/*Bloque 2 de la CBU*/
DECLARE @aNOTENTRECEPTipoCuenta		CHAR(2)		/*Tipo de Cuenta*/
DECLARE @aNOTENTRECEPNroCuenta		CHAR(11)	/*Nro de Cuenta*/
DECLARE @aNOTENTRECEPDigVerifBloq2	CHAR(1)		/*Digito Verificador - Bloque 2*/
/*Para Rechazos en la rendicion, en las presentaciones dajar en blanco*/
DECLARE @aRECHCodRechazo			CHAR(3)		/*Codigo de Rechazo. Ej R02, R03,...*/
DECLARE @aOBLIGReserv				CHAR(35)	/*Reserva. (Blancos)*/
DECLARE @aOBLIGNroCuitEmp			CHAR(11)	/*Nro. Cuit Empresa.*/
/*FIN Variables del Archivo*/

/*Variables Intermedias*/
DECLARE @Importe						VARCHAR(10)
DECLARE @FechaVencimiento				DATETIME
DECLARE @Id_Cliente						INT
DECLARE @CBU							VARCHAR(25)
DECLARE @CBU_PrimerBloque_IdBanco		CHAR(3)
DECLARE @CBU_PrimerBloque_IdSuc			CHAR(4)
DECLARE @CBU_PrimerBloque_DigVerifPriBlo CHAR(1)
DECLARE @CBU_SegundBloque_TipoCuenta	CHAR(2)
DECLARE @CBU_SegundBloque_NroCuenta		CHAR(11)
DECLARE @CBU_SegundBloque_DigVerifC		CHAR(1)
/*FIN Variables Intermedias*/

/*Calculo CBU*/

SET @CBU = (SELECT RTRIM(LTRIM(ISNULL(DBO.CF_Cotiza(@pTarNro), ''))))

SET @CBU_PrimerBloque_IdBanco			= (SELECT CAST(SUBSTRING(@CBU,1,3) AS CHAR(3)))
SET @CBU_PrimerBloque_IdSuc				= (SELECT CAST(SUBSTRING(@CBU,4,4) AS CHAR(4)))
SET @CBU_PrimerBloque_DigVerifPriBlo	= (SELECT CAST(SUBSTRING(@CBU,8,1) AS CHAR(1)))

SET @CBU_SegundBloque_TipoCuenta		= (SELECT CAST(SUBSTRING(@CBU,9,2) AS CHAR(2)))
SET @CBU_SegundBloque_NroCuenta			= (SELECT CAST(SUBSTRING(@CBU,11,11) AS CHAR(11)))
SET @CBU_SegundBloque_DigVerifC			= (SELECT CAST(SUBSTRING(@CBU,22,1) AS CHAR(1)))
/*FIN Calculo CBU*/

SET @Id_Cliente			= (SELECT ISNULL(Id_Cliente,0)			FROM Cbtes WHERE Id_Trans = @pId_Trans)
--5/12/2018 Se toma fecha del Lote en vez del Cbte por Ticket 15.404
SET @FechaVencimiento	= ISNULL(@pFecha_Venc, DATEADD(dd, 10, GETDATE()))
SET @Importe			= (SELECT RIGHT('0000000000' +  CAST(CAST((@pImporte * 100) AS INT) AS VARCHAR), 10))

/*Grabacion de los campos de la fila*/
SET @aTipoNovedad				= 'D'
SET @aCUIT						= '00000000000'
SET @aEntidad					= @CBU_PrimerBloque_IdBanco
SET @aSucursal					= @CBU_PrimerBloque_IdSuc
SET @aDigVerifBloq1				= @CBU_PrimerBloque_DigVerifPriBlo
SET @aTipoCuenta				= @CBU_SegundBloque_TipoCuenta
SET @aNroCuenta					= @CBU_SegundBloque_NroCuenta
SET @aDigVerifBloq2				= @CBU_SegundBloque_DigVerifC
SET @aIdentClientePag			= ISNULL(LEFT(CAST(RIGHT('000000' + CONVERT(VARCHAR(10), @Id_Cliente), 6) AS VARCHAR) + '                      ', 22), '                      ')
SET @aFechaVenc					= /*DD*/RIGHT('00' + CAST(DATEPART(dd, @FechaVencimiento) AS VARCHAR),2) + /*MM*/RIGHT('00' + CAST(DATEPART(mm, @FechaVencimiento) AS VARCHAR),2) + /*AAAA*/CAST(DATEPART(YY, @FechaVencimiento) AS CHAR(4))
SET @aProdPrestacion			= 'CUOTAS    '
SET @aADHTipoDoc				= '    '
SET @aADHNroDoc					= '00000000000'
SET @aDEBRefDeb					= ISNULL(LEFT(CAST(@pId_Trans AS VARCHAR) + '               ', 15), '               ')
SET @aDEBImporte				= @Importe
SET @aDEBTipoMon				= 'P'
SET @aNOTEMPORIIdentCliPag		= '                      '
SET @aNOTENTRECEPTipoCuenta		= '00'
SET @aNOTENTRECEPNroCuenta		= '00000000000'
SET @aNOTENTRECEPDigVerifBloq2	= '0'
SET @aRECHCodRechazo			= '   '
SET @aOBLIGReserv				= '                                   '
SET @aOBLIGNroCuitEmp			= (dbo.CF_XParam('RECE_Cuit'))

/*FIN Grabacion de los campos de la fila*/

/*Grabacio┬¥n de la Fila Completa*/
SET @Retorno			=	@aTipoNovedad				+ @aCUIT						+ @aEntidad +
							@aSucursal					+ @aDigVerifBloq1				+ @aTipoCuenta +
							@aNroCuenta					+ @aDigVerifBloq2				+ @aIdentClientePag +
							@aFechaVenc					+ @aProdPrestacion				+ @aADHTipoDoc +
							@aADHNroDoc					+ @aDEBRefDeb					+ @aDEBImporte + 
							@aDEBTipoMon				+ @aNOTEMPORIIdentCliPag		+ @aNOTENTRECEPTipoCuenta +
							@aNOTENTRECEPNroCuenta		+ @aNOTENTRECEPDigVerifBloq2	+ @aRECHCodRechazo +
							@aOBLIGReserv				+ @aOBLIGNroCuitEmp
/*FIN Grabacio┬¥n de la Fila Completa*/

RETURN @retorno
END
GO


CREATE FUNCTION [dbo].[CF_BancoPayPerTIC_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT) 
RETURNS VARCHAR(500)
AS
BEGIN

/*Variable de Retorno*/
DECLARE @Retorno			VARCHAR(500)
/*FIN Variable de Retorno*/

/*Variables del Archivo*/
DECLARE @aSeparador				CHAR(1)
DECLARE @aId_Trans				VARCHAR(10)		/*Identificador interno de transacci¾n para la entidad recaudadora*/
DECLARE @aId_Cliente			VARCHAR(10)		/*Identificador unÝvoco del pagador*/
DECLARE @aRazon_Social			VARCHAR(100)	/*Nombre del pagador*/
DECLARE @aTelefono				VARCHAR(900)	/*TelÚfono del pagador (SOLO numeros)*/
DECLARE @aEmail					VARCHAR(8000)	/*E-mail del pagador*/
DECLARE @aId_Producto			VARCHAR(14)		/*Identificador del concepto a cobrar*/
DECLARE @aDescripcion_Prod		VARCHAR(100)	/*Descripci¾n del concepto a cobrar*/
DECLARE @aImp_Total				VARCHAR(10)		/*Monto a cobrar (Solo numeros con punto decimal)*/
DECLARE @aRecurrenciaCobro		VARCHAR(2)		/*Recurrencia del cobro. *Modalidad Debito Automatico: Valor '0': El cobro se repetirß cada mes, todos los meses. Valor !=0: El cobro se repetirß tantas veces como este valor indique.   *Modalidad e-Commerce: El valor indica la cantidad de cuotas a realizar.*/
DECLARE @aURLCambios			VARCHAR(255)	/*URL a la cual se enviaran las notificaciones con el cambio de estado de los pagos.*/
DECLARE @aFechaVencimiento		VARCHAR(19)		/*Fecha de vencimiento.  Es la fecha del dÝa por defecto.  No es tomado en cuenta para pagos online (dd/mm/aaaa hh:mm:ss)*/
DECLARE @aUltFechaPago			VARCHAR(19)		/* ┌ltima fecha para aceptar el pago, durante este perÝodo se aplica el rate y el charge. Por defecto es el dÝa 24 del mes en curso. No es tomado en cuenta para pagos online (dd/mm/aaaa hh:mm:ss)*/
DECLARE @aTNAACobrar			VARCHAR(3)		/*TNA tasa de interÚs anual a cobrar entre los vencimientos. Por defecto es 0. No es tomado en cuenta para pagos online*/
DECLARE @aImpFijoDiferimiento	VARCHAR(10)		/*Importe fijo a aplicar en el diferimiento*/
DECLARE @aImpMinAAplicarVenc	VARCHAR(10)		/*Importe M═NIMO  a aplicar en el vencimiento*/
DECLARE @aTipoMedioPago			VARCHAR(5)		/*Tipo de medio de pago*/
DECLARE @aNroMedioPago			VARCHAR(22)		/*N·mero de medio de pago. CBU: 22 dÝgitos VISA: 16 dÝgitos MASTER: 16 dÝgitos AMEX: 15 dÝgitos No es tomado en cuenta para pagos online.*/
DECLARE @aNroPromo				VARCHAR(10)		/* Numero de promoci¾n el cual se obtiene del servicio de promociones. Nota: Este campo solo es valido para transacciones online y depende de la entidad con la cual se procese*/
DECLARE @aPriDatoAdicCli		VARCHAR(100)	/*Primer dato adicional del cliente*/
DECLARE @aSegDatoAdicCli		VARCHAR(100)	/*Segundo dato adicional del cliente*/
DECLARE @aId_Moneda				VARCHAR(3)		/*Identficador de la moneda de la transacci¾n (ARS, USD, etc)*/
DECLARE @aURLFinalizarPagoOnline VARCHAR(255)	/*URL a la cual se redireccionarß luego de finalizar la transacci¾n - s¾lo para pago online*/
DECLARE @aURLFinalizarPago 		VARCHAR(255)	/*URL a la cual podra regresar el pagador luego de la transacci¾n*/
DECLARE @aURLNotificacionesPago	VARCHAR(255)	/*URL a la cual se enviaran las notificaciones con el cambio de estado de los pagos*/
DECLARE @SesionGenerada			VARCHAR(500)	/*Sesi¾n generada por el servicio de autentificaci¾n. Este campo solo se requiere si en la configuraci¾n del comercio lo especifica.*/
DECLARE @PermControlIntegMsg	VARCHAR(500)	/*Permite controlar la integridad del mensaje enviado por el cliente.*/
DECLARE @Formato				CHAR(1)			/*A: API v1 / B: API v2*/
DECLARE @aPais_Expide_Identificacion	CHAR(3)/*Pais que expide la identificacion (String)*/
DECLARE @aTipoIdentificacion_Socio		CHAR(7)/*Tipo de identificaci¾n (String)*/
DECLARE @aNumeroIdentificacion_Socio	CHAR(14)/*N·mero de identificaci¾n (String)*/
/*FIN Variables del Archivo*/

/*Variables Intermedias*/
DECLARE @Id_Cliente				INT
DECLARE @Id_Cliente_Externo		VARCHAR(14)
DECLARE @Razon_Social			VARCHAR(100)
DECLARE @Telefono				VARCHAR(900)
DECLARE @Email					VARCHAR(8000)
DECLARE @Id_Producto			VARCHAR(14)
DECLARE @Descripcion_Prod		VARCHAR(100)
DECLARE @Fecha_QA				DATETIME
DECLARE @Fecha_Presentacion		DATETIME
DECLARE @Fecha_Venc				DATETIME
DECLARE @Fecha_Venc_VC			VARCHAR(20)
DECLARE @Fecha_Ult_Pago			DATETIME
DECLARE @Fecha_Ult_Pago_VC		VARCHAR(20)
DECLARE @Doc_Nro				BIGINT
/*FIN Variables Intermedias*/

/*Calculos intermerdios*/
SET @Formato			= (dbo.CF_xParam('PayPerTic_Formato'))

SET @Fecha_Presentacion	= (SELECT ISNULL(Fecha, GETDATE()) FROM Val_Tarjetas_Lotes WHERE Id_Tar_Lote = @pId_Tar_Lote)
SET @Fecha_Presentacion	= CONVERT(DATE, @Fecha_Presentacion)

SELECT  @Id_Cliente		= ISNULL(Id_Cliente, 0),
		@Fecha_Venc		= ISNULL(Fecha_Venc, DATEADD(dd, 10, Fecha))
FROM Cbtes
WHERE 
Id_Trans = @pId_Trans

SET @Fecha_Venc		= DATEADD(dd, 10, @Fecha_Presentacion)	--Los clubes mandan a PayPerTic la deuda Historica, por lo tanto la fecha de Venc no sirve, ya que el webService espera de la fecha actual 10 dias mas.

SET @Fecha_Venc_VC =	RIGHT('00' + CAST(DAY(@Fecha_Venc) AS VARCHAR),2) +
						'/' +
						RIGHT('00' + CAST(MONTH(@Fecha_Venc) AS VARCHAR),2) + 
						'/' +
						CAST(DATEPART(YY, @Fecha_Venc) AS CHAR(4)) + 
						' ' +
						RIGHT('00' + CAST(DATEPART(HH, @Fecha_Venc) AS VARCHAR),2) +
						':' +
						RIGHT('00' + CAST(DATEPART(MINUTE, @Fecha_Venc) AS VARCHAR),2) +
						':' +
						RIGHT('00' + CAST(DATEPART(SECOND, @Fecha_Venc) AS VARCHAR),2)

SET @Fecha_Ult_Pago = DATEADD(dd, 10, @Fecha_Venc)

SET @Fecha_Ult_Pago_VC = RIGHT('00' + CAST(DAY(@Fecha_Ult_Pago) AS VARCHAR),2) +
						'/' +
						RIGHT('00' + CAST(MONTH(@Fecha_Ult_Pago) AS VARCHAR),2) + 
						'/' +
						CAST(DATEPART(YY, @Fecha_Ult_Pago) AS CHAR(4)) + 
						' ' +
						RIGHT('00' + CAST(DATEPART(HH, @Fecha_Ult_Pago) AS VARCHAR),2) +
						':' +
						RIGHT('00' + CAST(DATEPART(MINUTE, @Fecha_Ult_Pago) AS VARCHAR),2) +
						':' +
						RIGHT('00' + CAST(DATEPART(SECOND, @Fecha_Ult_Pago) AS VARCHAR),2)

/*=============================================================================*/

SELECT  @Id_Cliente_Externo = ISNULL(LTRIM(RTRIM(Id_Cliente_Externo)), CONVERT(VARCHAR(14), Id_Cliente)),
		@Razon_Social		= ISNULL(LTRIM(RTRIM(Razon_Social)), LTRIM(RTRIM(Apellido)) + ' ' + LTRIM(RTRIM(Nombre))),
		@Telefono			= ISNULL(LTRIM(RTRIM(Telefono)), ''),
		@Email				= ISNULL(LTRIM(RTRIM(CONVERT(VARCHAR(8000), Email))), ''),
		@Doc_Nro			= ISNULL(Doc_Nro, 0)
FROM Clientes
WHERE 
Id_Cliente = @Id_Cliente

SET @Razon_Social = REPLACE(@Razon_Social, ',', '') --Hay que sacar las comas porque sino lo toma como separador de campo

SET @Telefono = REPLACE(@Telefono, '-', '')
SET @Telefono = REPLACE(@Telefono, '(', '')
SET @Telefono = REPLACE(@Telefono, ')', '')

IF(ISNUMERIC(@Telefono) = 0)
BEGIN
	SET @Telefono = ''
END

/*=============================================================================*/

SELECT	TOP 1 
		@Id_Producto		= LTRIM(RTRIM(Id_Producto)),  
		@Descripcion_Prod	= LTRIM(RTRIM(Descripcion_producto)), 
		@Fecha_QA			= Fecha_QA
FROM Cbtes_Items 
WHERE 
Id_Trans = @pId_Trans 
ORDER BY Imp_Final DESC
/*FIN Calculos intermerdios*/

/*Grabacion de los campos de la fila*/
SET @aSeparador				= ','

SET @aId_Trans				= @pId_Trans
SET @aId_Cliente			= @Id_Cliente_Externo --Seg·n conversaci¾n via Skype 18/07/2018 con Kevin Forgalan (kevpf_1) ejecutivo de Cuenta de PayPerTic este Numero es con el que los socios van a pagar
SET @aRazon_Social			= @Razon_Social
SET @aTelefono				= '' --@Telefono Seg·n conversaci¾n via Skype 18/07/2018 con Kevin Forgalan (kevpf_1) ejecutivo de Cuenta de PayPerTic si este dato no esta perfectamente parseado como telefono es mejo enviarlo vacio
SET @aEmail					= @Email
SET @aId_Producto			= @Id_Producto
SET @aDescripcion_Prod		= CAST(DATEPART(YY, @Fecha_QA) AS CHAR(4)) + '/' + RIGHT('00' + CAST(MONTH(@Fecha_QA) AS VARCHAR),2) + ' ' + @Descripcion_Prod
SET @aImp_Total				= CONVERT(VARCHAR(10), @pImporte)
/*Para futuras implementaciones*/
SET @aRecurrenciaCobro		= ''
SET @aURLCambios			= '' --Este campo cuando se tenga una API se pueden recibir novedades
SET @aFechaVencimiento		= @Fecha_Venc_VC
SET @aUltFechaPago			= @Fecha_Ult_Pago_VC
SET @aTNAACobrar			= ''
SET @aImpFijoDiferimiento	= ''
SET @aImpMinAAplicarVenc	= ''
SET @aTipoMedioPago			= ''
SET @aNroMedioPago			= ''
SET @aNroPromo				= ''
SET @aPriDatoAdicCli		= ''
SET @aSegDatoAdicCli		= ''
SET @aId_Moneda				= 'ARS' /*Pesos Argentinos*/
SET @aURLFinalizarPagoOnline= ''
SET @aURLFinalizarPago		= ''
SET @aURLNotificacionesPago = ''
SET @SesionGenerada			= ''
SET @PermControlIntegMsg	= ''
SET @aPais_Expide_Identificacion= 'ARG'
SET @aTipoIdentificacion_Socio	= 'DNI_ARG'
SET @aNumeroIdentificacion_Socio= CONVERT(VARCHAR(20), @Doc_Nro)
/*FIN Grabacion de los campos de la fila*/

/*Grabaci¾n de la Fila Completa*/

IF(@Formato = 'A') /*API version 1*/
BEGIN
	SET @Retorno			=	@aId_Trans				+ @aSeparador +
								@aId_Cliente			+ @aSeparador +
								@aRazon_Social			+ @aSeparador +
								@aTelefono				+ @aSeparador +
								@aEmail					+ @aSeparador +
								@aId_Producto			+ @aSeparador +
								@aDescripcion_Prod		+ @aSeparador +
								@aImp_Total				+ @aSeparador +
								@aRecurrenciaCobro		+ @aSeparador +
								@aURLCambios			+ @aSeparador +
								@aFechaVencimiento		+ @aSeparador +
								@aUltFechaPago			/*+ @aSeparador +
								@aTNAACobrar			+ @aSeparador +
								@aImpFijoDiferimiento	+ @aSeparador +
								@aImpMinAAplicarVenc	+ @aSeparador +
								@aTipoMedioPago			+ @aSeparador +
								@aNroMedioPago			+ @aSeparador +
								@aNroPromo				+ @aSeparador +
								@aPriDatoAdicCli		+ @aSeparador +
								@aSegDatoAdicCli		+ @aSeparador +
								@SesionGenerada			+ @aSeparador +
								@PermControlIntegMsg*/
END

IF(@Formato = 'B') /*API version 2*/
BEGIN
	/*
	--Hasta el 06/10/2020. Modificada por Reuni¾n con Buchardo y responsable de PayPerTic Martin
	SET @Retorno			=	@aId_Trans				+ @aSeparador +
								@aId_Trans				+ @aSeparador +
								@aId_Producto			+ @aSeparador +
								@aDescripcion_Prod		+ @aSeparador +
								@aId_Moneda				+ @aSeparador +
								@aImp_Total				+ @aSeparador +
								@aFechaVencimiento		+ @aSeparador +
								@aUltFechaPago			+ @aSeparador +
								@aURLFinalizarPagoOnline+ @aSeparador +
								@aURLFinalizarPago		+ @aSeparador +
								@aURLNotificacionesPago + @aSeparador +
								@aTNAACobrar			+ @aSeparador +
								@aImpFijoDiferimiento	+ @aSeparador +
								@aNroMedioPago			+ @aSeparador +
								@aNroPromo				+ @aSeparador +
								@aPriDatoAdicCli		+ @aSeparador +							
								@aId_Cliente			+ @aSeparador +
								@aRazon_Social												
	*/
	SET @Retorno			=	@aId_Trans						+ @aSeparador +					/*Identificador UNICO para cada transaccion informada (String)*/
								@aId_Trans						+ @aSeparador +					/*Identificador interno de transacci¾n para la entidad recaudadora (String)*/
								@aId_Producto					+ @aSeparador +					/*Identificador del concepto a cobrar (String)*/
								@aDescripcion_Prod				+ @aSeparador +					/*Descripci¾n del concepto a cobrar (String)*/
								@aId_Moneda						+ @aSeparador +					/*Identficador de la moneda de la transacci¾n (ARS, USD, etc)*/
								@aImp_Total						+ @aSeparador +					/*Monto a cobrar (Double - Solo numeros con punto decimal)*/
								@aFechaVencimiento				+ @aSeparador +					/*Fecha de vencimiento. Es la fecha del dÝa por defecto. No es tomado en cuenta para pagos online (dd/mm/aaaa hh:mm:ss)*/
								@aUltFechaPago					+ @aSeparador +					/*┌ltima fecha para aceptar el pago, durante este perÝodo se aplica el rate y el charge. Por defecto es el dÝa 24 del mes en curso. No es tomado en cuenta para pagos online (dd/mm/aaaa hh:mm:ss)*/
								@aURLFinalizarPagoOnline		+ @aSeparador +					/*URL a la cual se redireccionarß luego de finalizar la transacci¾n - s¾lo para pago online. (String)*/
								@aURLFinalizarPago				+ @aSeparador +					/*URL a la cual podra regresar el pagador luego de la transacci¾n. (String)*/
								@aURLNotificacionesPago			+ @aSeparador +					/*URL a la cual se enviaran las notificaciones con el cambio de estado de los pagos. (String)*/
								@aTNAACobrar					+ @aSeparador +					/*TNA tasa de interÚs anual a cobrar entre los vencimientos. Por defecto es 0.*/
								@aImpFijoDiferimiento			+ @aSeparador +					/*Importe fijo a aplicar en el diferimiento (Double)*/
								@aNroMedioPago					+ @aSeparador +					/*N·mero de medio de pago. CBU: 22 dÝgitos VISA: 16 dÝgitos MASTER: 16 dÝgitos AMEX: 15 dÝgitos No es tomado en cuenta para pagos online.*/
								@aNroPromo						+ @aSeparador +					/*Numero de promoci¾n el cual se obtiene del servicio de promociones. Nota: Este campo solo es valido para transacciones online y depende de la entidad con la cual se procese (String)*/
								@aPriDatoAdicCli				+ @aSeparador +					/*Cualquier tipo de informacion adicional*/
								@aId_Cliente					+ @aSeparador +					/*Identificador del pagador*/
								@aRazon_Social					+ @aSeparador +					/*Nombre del pagador (String)*/
								@aEmail							+ @aSeparador +					/*Email del pagador (String)*/
								@aTelefono						+ @aSeparador +					/*Telefono del pagador (String)*/
								@aPais_Expide_Identificacion	+ @aSeparador +					/*Pais que expide la identificacion (String)*/
								@aTipoIdentificacion_Socio		+ @aSeparador +					/*Tipo de identificaci¾n (String)*/
								@aNumeroIdentificacion_Socio									/*N·mero de identificaci¾n (String)*/											
END
/*FIN Grabacion de la Fila Completa*/

RETURN @retorno
END
GO

CREATE FUNCTION [dbo].[CF_Banco_OCA_UY_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT, @pPeriodo DATETIME) 
RETURNS CHAR(106)
AS
BEGIN

/*Variables Archivo*/
DECLARE @Retorno					CHAR(106)
DECLARE @aNro_Socio_Institucion		CHAR(50)		/*Formato: Alfanumerico (50).	Desde: 001. Hasta: 050. Nota: Nro de Socio de la Institucion.*/
DECLARE @aDoc_Nro_Titular			CHAR(7)			/*Formato: Alfanumerico (7).	Desde: 051. Hasta: 057. Nota: Cedula del Tarjeta Habiente*/
DECLARE @aMoneda					CHAR(3)			/*Formato: Numerico (3).		Desde: 058. Hasta: 060. Nota: Moneda $: 858, U$S: 840.*/
DECLARE @aImporte					CHAR(7)			/*Formato: Numerico (5,2).		Desde: 061. Hasta: 067. Nota: Monto correspondiente al valor del débito automático cobrado o del cupón crédito devuelto por el Establecimiento al usuario, se encuentra formado por una parte entera y otra decimal. El monto no incluye punto ni coma decimal, como tampoco signo; simplemente deberá informarse alineado a la derecha, con ceros a la izquierda.*/
DECLARE @aAplicaDevolucionIVA		CHAR(1)			/*Formato: Numerico (1).		Desde: 068.	Hasta: 068	Nota: No aplica=0, Aplica Dev. Iva Ley 19210=6*/
DECLARE @aNumeroFactura				CHAR(20)		/*Formato: Alfanumerico(20)		Desde: 069.	Hasta: 088	Nota: Numero de Factura*/
DECLARE @ImporteGravado				CHAR(9)			/*Formato: Numerico (7,2).		Desde: 089. Hasta: 097. Nota: Importe Gravado Sin IVA, se encuentra formado por una parte entera y otra decimal. El monto no incluye punto ni coma decimal, como tampoco signo; simplemente deberá informarse alineado a la derecha, con ceros a la izquierda.*/
DECLARE @ImporteRetenido			CHAR(9)			/*Formato: Numerico (7,2).		Desde: 098. Hasta: 106. Nota: Importe Retenido, se encuentra formado por una parte entera y otra decimal. El monto no incluye punto ni coma decimal, como tampoco signo; simplemente deberá informarse alineado a la derecha, con ceros a la izquierda.*/
/*FIN Variables Archivo*/

/*Variable Locales*/
DECLARE @Id_Tarjeta				VARCHAR(10)
DECLARE @Fecha_Presentacion		DATETIME
DECLARE @Comercio_Nro			VARCHAR(50)
DECLARE @Tar_Nro				VARCHAR(22)
DECLARE @Id_Contrato			INT
DECLARE @Tar_Fecha_Vence		DATETIME
DECLARE @Fecha_Cbte				DATETIME
DECLARE @Mes_Periodo			SMALLINT
DECLARE @Mes_Periodo_VC			VARCHAR(3)
DECLARE @Id_Cliente				INT
DECLARE @Id_Cliente_Externo		INT
DECLARE @Comprobante_Nro		INT
DECLARE @Id_Cliente_Ref			INT
DECLARE @Doc_Nro				BIGINT
DECLARE @Doc_Nro_Titular		BIGINT
/*FIN Variable Locales*/

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

/*Seteo Variables Locales*/
SELECT	
@Id_Tarjeta				= ISNULL(Id_Tarjeta, ''),
@Fecha_Presentacion		= ISNULL(Fecha_Presentacion, '19000101')
FROM Val_Tarjetas_Lotes
WHERE
Id_Tar_Lote = @pId_Tar_Lote

SELECT
@Comercio_Nro			= ISNULL(Comercio_Nro, '')
FROM Valores_Tarjetas_Cred
WHERE
ISNULL(Id_Tarjeta, '') = @Id_Tarjeta

SELECT	
@Tar_Nro				= ISNULL(DBO.SF_Cotiza(Nro), '')
FROM Val_Tarjetas_Lotes_Items 
WHERE
Id_Tar_Lote = @pId_Tar_Lote
AND Id_Trans = @pId_Trans


SELECT	
@Id_Cliente				= ISNULL(Id_Cliente, 0),
@Fecha_Cbte				= ISNULL(Fecha, '19000101'),
@Id_Contrato			= ISNULL(Id_Contrato, 0),
@Comprobante_Nro		= ISNULL(Comprobante_Nro, 0)
FROM Cbtes 
WHERE
Id_Trans = @pId_Trans

SELECT 
@Id_Cliente_Externo		= ISNULL(Id_Cliente_Externo, Id_Cliente),
@Id_Cliente_Ref			= ISNULL(Id_Cliente_Ref, 0),
@Doc_Nro				= ISNULL(Doc_Nro, 0)
FROM Clientes
WHERE
Id_Cliente = @Id_Cliente

SELECT
@Doc_Nro_Titular		= ISNULL(Doc_Nro, 0)
FROM Clientes
WHERE
Id_Cliente = @Id_Cliente_Ref

SELECT
@Tar_Fecha_Vence		= ISNULL(Tar_Fecha_Vence, DATEADD(YEAR, 1, GETDATE()))
FROM Contratos
WHERE
Id_Contrato = @Id_Contrato

SET @Mes_Periodo = DATEPART(MONTH, @pPeriodo)

SELECT
@Mes_Periodo_VC =	CASE @Mes_Periodo
						WHEN 1	THEN 'ENE'
						WHEN 2	THEN 'FEB'
						WHEN 3	THEN 'MAR'
						WHEN 4	THEN 'ABR'
						WHEN 5	THEN 'MAY'
						WHEN 6	THEN 'JUN'
						WHEN 7	THEN 'JUL'
						WHEN 8	THEN 'AGO'
						WHEN 9	THEN 'SEP'
						WHEN 10 THEN 'OCT'
						WHEN 11 THEN 'NOV'
						WHEN 12 THEN 'DIC'
					END


/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

SET @aNro_Socio_Institucion		= (RIGHT('                                                  ' + CAST(@Id_Cliente_Externo AS VARCHAR), 50))

SET @aDoc_Nro_Titular			= (RIGHT('0000000' + @Tar_Nro, 7))

SET @aMoneda					= '858' /*Pesos Uruguayos*/

SET @aImporte					= RIGHT('0000000' + CAST(CAST(@pImporte * 100 AS INT) AS VARCHAR), 7)

SET @aAplicaDevolucionIVA		= '0'

SET @aNumeroFactura				= (RIGHT('                    ' + CAST(@pId_Trans AS VARCHAR), 20))

SET @ImporteGravado				= '000000000'

SET @ImporteRetenido			= '000000000'

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

SET @Retorno =	@aNro_Socio_Institucion +
				@aDoc_Nro_Titular +
				@aMoneda +
				@aImporte +
				@aAplicaDevolucionIVA +
				@aNumeroFactura + 
				@ImporteGravado +
				@ImporteRetenido

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

RETURN ISNULL(@Retorno, '                                                                    ')
END
GO


CREATE FUNCTION [dbo].[CF_Banco_Roela_AR_CB](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT, @pPeriodo DATETIME) 
RETURNS CHAR(56)
AS
BEGIN
/*Variable de Retorno*/
DECLARE @Retorno				CHAR(56)
/*FIN Variable de Retorno*/

IF EXISTS ( SELECT * FROM sysobjects WHERE id = object_id(N'dbo.CF_Banco_Roela_AR_CB_') AND type = 'FN')
BEGIN
    SET @Retorno = dbo.CF_Banco_Roela_AR_CB_(@pId_Trans, @pImporte, @pId_Tar_Lote, @pPeriodo)
	RETURN @Retorno
END

/*Variables del Archivo*/
DECLARE @aEmpresaServicio		CHAR(4)		/*Empresa de Servicio.			Tipo: Numerico. Long: 04. Desde: 001. Hasta: 004. Descripcion: Fijo: 0447*/
DECLARE @aId_Concepto			CHAR(1)		/*Identificador de Concepto.	Tipo: Numerico. Long: 01. Desde: 005. Hasta: 005. Descripcion: Digito a su disposicion y puede referirse a distintos conceptos que factura el ente. Ej: 1: Alquileres, 2: expensas, 3: Cuota, 4: seguro de vida, 5: cliente VIP, etc*/
DECLARE @aId_Usuario			CHAR(8)		/*Identificador de Usuario.		Tipo: Numerico. Long: 08. Desde: 006. Hasta: 013. Descripcion: Codigo para identificar a clientes que van a abonar. Ej: DNI, Legajo, Unidad Funcional, factura, etc*/
DECLARE @aFch_1Venc				CHAR(6)		/*Fecha 1er Vto.				Tipo: Numerico. Long: 06. Desde: 014. Hasta: 019. Descripcion: Formato AAAAMMDD.*/
DECLARE @aImporte_1Venc			CHAR(7)		/*Importe 1er Vto.				Tipo: Numerico. Long: 07. Desde: 020. Hasta: 026. Descripcion: Monto a Cobrar (5 enteros, 2 decimales). */
DECLARE @aDias2Venc				CHAR(2)		/*Dias hasta 2do Vto.			Tipo: Numerico. Long: 02. Desde: 027. Hasta: 028. Descripcion: Cantidad de dias corridos entre el 1er y 2do vencimiento. Si no usa segundo vencimiento, completar con 0 (cero)*/
DECLARE @aImporte_2Venc			CHAR(7)		/*Importe 2do Vto.				Tipo: Numerico. Long: 07. Desde: 029. Hasta: 035. Descripcion: Monto a Cobrar (5 enteros, 2 decimales).  Si no usa segundo vencimiento, completar con 0 (cero)*/
DECLARE @aDias3Venc				CHAR(2)		/*Dias hasta 3er Vto.			Tipo: Numerico. Long: 02. Desde: 036. Hasta: 037. Descripcion: Cantidad de dias corridos entre el 2do y 3er vencimiento. Si no usa segundo vencimiento, completar con 0 (cero)*/
DECLARE @aImporte_3Venc			CHAR(7)		/*Importe 3er Vto.				Tipo: Numerico. Long: 07. Desde: 038. Hasta: 044. Descripcion: Monto a Cobrar (5 enteros, 2 decimales).  Si no usa segundo vencimiento, completar con 0 (cero)*/
DECLARE @aId_Cuenta				CHAR(10)	/*Identificado de Cuenta		Tipo: Numerico. Long: 10. Desde: 045. Hasta: 054. Descripcion: Otorgado por Banco Roela*/
DECLARE @aDigito_Verif_1		CHAR(1)		/*Digito Verificador 1.			Tipo: Numerico. Long: 01. Desde: 055. Hasta: 055. Descripcion: Ver Anexo*/
DECLARE @aDigito_Verif_2		CHAR(1)		/*Digito Verificador 2.			Tipo: Numerico. Long: 01. Desde: 056. Hasta: 056. Descripcion: Ver Anexo*/
/*FIN Variables del Archivo*/

/*Variables Locales*/
DECLARE @Cadena_A_Verificar				CHAR(54)
DECLARE	@i								TINYINT
DECLARE @Mult_Paso2						INT
DECLARE @Suma_Paso3						INT
DECLARE @Division_Paso4					DECIMAL(12,2)
DECLARE @Modulo_Paso5					DECIMAL(12,2)
DECLARE @Cadena_A_Verificar2			CHAR(55)

DECLARE @Id_Tarjeta						VARCHAR(10)

DECLARE @1_Vto_Porc_Recargo				DECIMAL(12,5)
DECLARE @1_Vto_Plazo_Desde				INT
DECLARE @1_Vto_Plazo_Hasta				INT
DECLARE @2_Vto_Porc_Recargo				DECIMAL(12,5)
DECLARE @2_Vto_Plazo_Desde				INT
DECLARE @2_Vto_Plazo_Hasta				INT
DECLARE @3_Vto_Porc_Recargo				DECIMAL(12,5)
DECLARE @3_Vto_Plazo_Desde				INT
DECLARE @3_Vto_Plazo_Hasta				INT

DECLARE @Comercio_Nro					VARCHAR(50)
DECLARE @Id_Cliente						INT
DECLARE @Id_Contrato					INT
DECLARE @Comprobante_Nro				INT
DECLARE @Importe_Cbte					DECIMAL(12,2)
DECLARE @Fecha_Cbte						DATETIME
DECLARE @Id_Cliente_Externo				VARCHAR(14)
DECLARE @Id_Cliente_Ref					INT
DECLARE @Doc_Nro						BIGINT
DECLARE @Tipo_Persona					CHAR(1)
DECLARE @Id_Tipo_Cbte					VARCHAR(4)
DECLARE @Id_Cliente_Externo_Tit			VARCHAR(14)
DECLARE @Id_Cond_Pago					SMALLINT
/*FIN Variables Locales*/

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

/*Seteo Variables Locales*/

SET @Id_Tarjeta			= dbo.CF_xParam('Id_Banco_Roela_AR')

SELECT
@Comercio_Nro			= LTRIM(RTRIM(ISNULL(Comercio_Nro, '')))
FROM Valores_Tarjetas_Cred
WHERE
ISNULL(Id_Tarjeta, '') = @Id_Tarjeta

SELECT	
@Id_Cliente				= ISNULL(Id_Cliente, 0),
@Fecha_Cbte				= ISNULL(Fecha, '19000101'),
@Id_Contrato			= ISNULL(Id_Contrato, 0),
@Comprobante_Nro		= ISNULL(Comprobante_Nro, 0),
@Id_Tipo_Cbte			= ISNULL(Id_Tipo_Cbte, ''),
@Importe_Cbte			= ISNULL(Imp_Total, 0)
FROM Cbtes 
WHERE
Id_Trans = @pId_Trans

SELECT
@Id_Cond_Pago			= ISNULL(Id_Cond_Pago, 0)
FROM Productos
WHERE
Id_Producto = dbo.CF_xParam('Prod_Cuota_Social')

SELECT 
@Id_Cliente_Externo		= ISNULL(Id_Cliente_Externo, Id_Cliente),
@Id_Cliente_Ref			= ISNULL(Id_Cliente_Ref, 0),
@Doc_Nro				= ISNULL(Doc_Nro, 0),
@Tipo_Persona			= ISNULL(Tipo_Persona, 'F')
FROM Clientes 
WHERE 
Id_Cliente = @Id_Cliente

SELECT 
@Id_Cliente_Externo_Tit		= ISNULL(Id_Cliente_Externo, Id_Cliente)
FROM Clientes 
WHERE 
Id_Cliente = @Id_Cliente_Ref

SELECT 
@1_Vto_Porc_Recargo		= ISNULL(Porc_Bonif, 0),
@1_Vto_Plazo_Desde		= ISNULL(Plazo_Desde, 0),
@1_Vto_Plazo_Hasta		= ISNULL(Plazo_Bonif, 0)
FROM Cbtes_Cond_Pago_Items 
WHERE 
Id_Cond_Pago = @Id_Cond_Pago 
AND Tipo = 'P'
AND Id_Cond_Pago_Item = 1

IF(@1_Vto_Porc_Recargo = CONVERT(DECIMAL(12,5), 0))
BEGIN
	SET @1_Vto_Porc_Recargo = CONVERT(DECIMAL(12,5), 1)
END
ELSE
BEGIN
	SET @1_Vto_Porc_Recargo = (@1_Vto_Porc_Recargo / 100) + 1
END

SELECT 
@2_Vto_Porc_Recargo		= ISNULL(Porc_Bonif, 0),
@2_Vto_Plazo_Desde		= ISNULL(Plazo_Desde, 0),
@2_Vto_Plazo_Hasta		= ISNULL(Plazo_Bonif, 0)
FROM Cbtes_Cond_Pago_Items 
WHERE 
Id_Cond_Pago = @Id_Cond_Pago 
AND Tipo = 'P'
AND Id_Cond_Pago_Item = 2

IF(@2_Vto_Porc_Recargo = CONVERT(DECIMAL(12,5), 0))
BEGIN
	SET @2_Vto_Porc_Recargo = CONVERT(DECIMAL(12,5), 1)
END
ELSE
BEGIN
	SET @2_Vto_Porc_Recargo = (@2_Vto_Porc_Recargo / 100) + 1
END

SELECT 
@3_Vto_Porc_Recargo		= ISNULL(Porc_Bonif, 0),
@3_Vto_Plazo_Desde		= ISNULL(Plazo_Desde, 0),
@3_Vto_Plazo_Hasta		= ISNULL(Plazo_Bonif, 0)
FROM Cbtes_Cond_Pago_Items 
WHERE 
Id_Cond_Pago = @Id_Cond_Pago 
AND Tipo = 'P'
AND Id_Cond_Pago_Item = 3

IF(@3_Vto_Porc_Recargo = CONVERT(DECIMAL(12,5), 0))
BEGIN
	SET @3_Vto_Porc_Recargo = CONVERT(DECIMAL(12,5), 1)
END
ELSE
BEGIN
	SET @3_Vto_Porc_Recargo = (@3_Vto_Porc_Recargo / 100) + 1
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@Tipo_Persona = 'I'/*Inmueble*/)
BEGIN
	IF(dbo.CF_IsNumeric(@Id_Cliente_Externo_Tit) = 1)
	BEGIN
		SET @Id_Cliente_Externo = CONVERT(VARCHAR(14), @Id_Cliente_Ref)
	END
	ELSE
	BEGIN
		SET @Id_Cliente_Externo = @Id_Cliente_Externo_Tit
	END
END
ELSE
BEGIN
	IF(dbo.CF_IsNumeric(@Id_Cliente_Externo) = 1)
	BEGIN
		SET @Id_Cliente_Externo = @Id_Cliente_Externo
	END
	ELSE
	BEGIN
		SET @Id_Cliente_Externo = CONVERT(VARCHAR(14), @Id_Cliente)
	END
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

/*Seteo variables del Archivo*/

SET @aEmpresaServicio	= '0447'

SET @aId_Concepto		= '1'

SET @aId_Usuario		= RIGHT('00000000' + CAST(@pId_Trans AS VARCHAR), 8)

SET @aFch_1Venc			= SUBSTRING(RIGHT('0000' + CAST(DATEPART(YEAR, @Fecha_Cbte) AS VARCHAR), 4), 3, 2) + RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_Cbte) AS VARCHAR), 2) + RIGHT('00' + CAST(@1_Vto_Plazo_Hasta AS VARCHAR), 2)

SET @aImporte_1Venc		= (SELECT RIGHT('0000000' + CAST(CAST(@pImporte * @1_Vto_Porc_Recargo * 100 AS INT) AS VARCHAR), 7))

SET @aDias2Venc			= RIGHT('00' + CAST((@2_Vto_Plazo_Hasta - @1_Vto_Plazo_Hasta) AS VARCHAR), 2)

SET @aImporte_2Venc		= (SELECT RIGHT('0000000' + CAST(CAST(@pImporte * @2_Vto_Porc_Recargo * 100 AS INT) AS VARCHAR), 7))

SET @aDias3Venc			= RIGHT('00' + CAST((@3_Vto_Plazo_Hasta - @2_Vto_Plazo_Hasta) AS VARCHAR), 2)

SET @aImporte_3Venc		= (SELECT RIGHT('0000000' + CAST(CAST(@pImporte * @3_Vto_Porc_Recargo * 100 AS INT) AS VARCHAR), 7))

SET @aId_Cuenta			= RIGHT('0000000000' + @Comercio_Nro, 10)

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

--Digito verificador 1

SET @Cadena_A_Verificar =	@aEmpresaServicio +
							@aId_Concepto +
							@aId_Usuario +
							@aFch_1Venc +
							@aImporte_1Venc +
							@aDias2Venc +
							@aImporte_2Venc +
							@aDias3Venc +
							@aImporte_3Venc +
							@aId_Cuenta

SET @Suma_Paso3	= 0 
SET @i			= 1

WHILE (@i <= 54)
BEGIN

	IF(@i IN (1))
	BEGIN
		SET @Mult_Paso2 = SUBSTRING(@Cadena_A_Verificar, @i, 1) * 1
	END

	IF(@i IN (2,6,10,14,18,22,26,30,34,38,42,46,50,54))
	BEGIN
		SET @Mult_Paso2 = SUBSTRING(@Cadena_A_Verificar, @i, 1) * 3
	END

	IF(@i IN (3,7,11,15,19,23,27,31,35,39,43,47,51))
	BEGIN
		SET @Mult_Paso2 = SUBSTRING(@Cadena_A_Verificar, @i, 1) * 5
	END

	IF(@i IN (4,8,12,16,20,24,28,32,36,40,44,48,52))
	BEGIN
		SET @Mult_Paso2 = SUBSTRING(@Cadena_A_Verificar, @i, 1) * 7
	END

	IF(@i IN (5,9,13,17,21,25,29,33,37,41,45,49,53))
	BEGIN
		SET @Mult_Paso2 = SUBSTRING(@Cadena_A_Verificar, @i, 1) * 9
	END

	SET @Suma_Paso3 = @Suma_Paso3 + @Mult_Paso2

	SET @i = @i + 1
END

SET @Division_Paso4		= CONVERT(DECIMAL(12, 2), (@Suma_Paso3 / 2))

SET @Modulo_Paso5		= ROUND(@Division_Paso4, 0, 1) % 10

SET @aDigito_Verif_1	= CONVERT(VARCHAR(1), ROUND(CONVERT(INT, @Modulo_Paso5), 0, 1))

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

--Digito verificador 2

SET @Cadena_A_Verificar2 =	@Cadena_A_Verificar +  
							@aDigito_Verif_1

SET @Suma_Paso3	= 0 
SET @i			= 1

WHILE (@i <= 55)
BEGIN	
	IF(@i IN (1))
	BEGIN
		SET @Mult_Paso2 = SUBSTRING(@Cadena_A_Verificar2, @i, 1) * 1
	END

	IF(@i IN (2,6,10,14,18,22,26,30,34,38,42,46,50,54))
	BEGIN
		SET @Mult_Paso2 = SUBSTRING(@Cadena_A_Verificar2, @i, 1) * 3
	END

	IF(@i IN (3,7,11,15,19,23,27,31,35,39,43,47,51,55))
	BEGIN
		SET @Mult_Paso2 = SUBSTRING(@Cadena_A_Verificar2, @i, 1) * 5
	END

	IF(@i IN (4,8,12,16,20,24,28,32,36,40,44,48,52))
	BEGIN
		SET @Mult_Paso2 = SUBSTRING(@Cadena_A_Verificar2, @i, 1) * 7
	END

	IF(@i IN (5,9,13,17,21,25,29,33,37,41,45,49,53))
	BEGIN
		SET @Mult_Paso2 = SUBSTRING(@Cadena_A_Verificar2, @i, 1) * 9
	END

	SET @Suma_Paso3 = @Suma_Paso3 + @Mult_Paso2

	SET @i = @i + 1
END

SET @Division_Paso4		= CONVERT(DECIMAL(12, 2), (@Suma_Paso3 / 2))

SET @Modulo_Paso5		= ROUND(@Division_Paso4, 0, 1) % 10

SET @aDigito_Verif_2	= CONVERT(VARCHAR(1), ROUND(CONVERT(INT, @Modulo_Paso5), 0, 1))

-------------------------------------------------------------------------------------------------------------------------------------------------------------------
                    
SET @Retorno =	@aEmpresaServicio		+
				@aId_Concepto			+
				@aId_Usuario			+
				@aFch_1Venc				+
				@aImporte_1Venc			+
				@aDias2Venc				+
				@aImporte_2Venc			+
				@aDias3Venc				+
				@aImporte_3Venc			+
				@aId_Cuenta				+
				@aDigito_Verif_1		+
				@aDigito_Verif_2	

-------------------------------------------------------------------------------------------------------------------------------------------------------------------
                                                        
RETURN ISNULL(@Retorno, '                                                        ')
END
GO


CREATE  FUNCTION [dbo].[CF_Banco_Roela_AR_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT, @pPeriodo DATETIME) 
RETURNS CHAR(280)
AS
BEGIN
/*Variable de Retorno*/
DECLARE @Retorno			CHAR(280)
/*FIN Variable de Retorno*/

IF EXISTS ( SELECT * FROM sysobjects WHERE id = object_id(N'dbo.CF_Banco_Roela_AR_TX_') AND type = 'FN')
BEGIN
    SET @Retorno = dbo.CF_Banco_Roela_AR_TX_(@pId_Trans, @pImporte, @pId_Tar_Lote, @pPeriodo)
	RETURN @Retorno
END

/*Variables del Archivo*/
DECLARE @aCod_Registro			CHAR(1)		/*Codigo de Registro. Valor fijo: 5. Indica que este renglon forma parte del detalle.*/
DECLARE @aNroReferencia			CHAR(19)	/*Los 19 digitos se forman de la siguiente manera: 1)Los primeros nueve digitos son para identificar a los titulares de las obligaciones. Si utiliza el codigo debarras de SIRO, se completa la primera posicion con cero y las 8 restantes con el "identificador de usuario" del diseÔö£ÔûÆo de registro de codigo de barra SIRO). No puede utilizarse aqui un numero de comprobante. 2) Las ultimas 10 posiciones son el "identificador de cuenta" otorgado por Banco Roela (presente en el diseÔö£ÔûÆo de registro del Codigo de Barras SIRO)*/
DECLARE @aId_Factura			CHAR(20)	/*Debe completarse de la siguiente manera: 1) Las primeras 15 posiciones se completan con datos de la factura 2) La posicion 16 para identificar el concepto a facturar (si no se va a utilizar, completar con cero) 3) Los cuatro digitos restantes para identificar el mes y el aÔö£ÔûÆo de facturacion con el formato MMAA. Por ejemplo si el Concepto 1 es "deuda" y el 2 es "intereses", si se quiere informar la deuda de agosto de 2014 este campo se completa con: XXXXXXXXXXXXXXX10814; y si se quiere informar el interes de ese mismo periodo, se completa con XXXXXXXXXXXXXXX20814. En caso que el ente trabaja con un solo concepto y no necesita discriminarlos, informara: XXXXXXXXXXXXXXX00814*/
DECLARE @aId_Moneda				CHAR(1)		/*Codigo de moneda de los importes informados. Valor fijo: 0 (Pesos).*/
DECLARE @aFecha_PriVenc			CHAR(8)		/*Fecha del 1er vencimiento de la factura Formato: AAAAMMDD*/
DECLARE @aImporte_PriVenc		CHAR(11)	/*Importe de la factura para el 1er vencimiento. Formato: 9 enteros, 2 decimales, sin separadores*/
DECLARE @aFecha_SegVenc			CHAR(8)		/*Fecha del 2do vencimiento de la factura Formato: AAAAMMDD*/
DECLARE @aImporte_SegVenc		CHAR(11)	/*Importe de la factura para el 2do vencimiento. Formato: 9 enteros, 2 decimales, sin separadores*/
DECLARE @aFecha_TerVenc			CHAR(8)		/*Fecha del 3er vencimiento de la factura Formato: AAAAMMDD*/
DECLARE @aImporte_TerVenc		CHAR(11)	/*Importe de la factura para el 3er vencimiento. Formato: 9 enteros, 2 decimales, sin separadores*/
DECLARE @aFiller1				CHAR(19)	/*Campo para uso futuro. Valor fijo: ceros.*/
DECLARE @aNro_Referencia_Ant	CHAR(19)	/*Repetir el valor informado en el campo "Nro. Referencia"*/
DECLARE @aMensajeTicket			CHAR(40)	/*Datos a informar en el ticket de pago. Utilizar de la siguiente manera: 1) Utilizar las primeras 15 posiciones para informar el Ente al cual se esta efectuando el pago, abreviando el nombre de modo que el pagador pueda identificar inequivocamente el Ente. 2) Utilizar las 25 posiciones restantes para informacion secundaria, como el concepto que se esta pagando y/o el periodo. Completar solo con letras mayusculas (sin acentos, ni "Ôö£ÔûÆ") y numeros. No admite caracteres especiales (puntos, comas, parentesis, etc.).*/
DECLARE @aMensajePantalla		CHAR(15)	/*Datos a informar en la pantalla de seleccion de la factura a pagar. Utilizar las primeras 15 posiciones del campo "Mensaje en Ticket" para informar el Ente al cual se esta efectuando el pago, abreviando el nombre de modo que el pagador pueda identificar inequivocamente el Ente. Completar solo con letras mayusculas (sin acentos, ni "Ôö£ÔûÆ") y numeros. No admite caracteres especiales (puntos, comas, parentesis, etc.).*/
DECLARE @aCodBarra				CHAR(60)	/*Completar con espacios.*/
DECLARE @aFiller2				CHAR(29)	/*Completar con ceros.*/
/*FIN Variables del Archivo*/

/*Variables Locales*/
DECLARE @Id_Tarjeta						VARCHAR(10)
DECLARE @Fecha_Presentacion				DATETIME
DECLARE @Fecha_1_Vto					DATETIME
DECLARE @Fecha_2_Vto					DATETIME
DECLARE @Fecha_3_Vto					DATETIME
DECLARE @Porc_Recargo_1_Vto				DECIMAL(12,5)
DECLARE @Porc_Recargo_2_Vto				DECIMAL(12,5)
DECLARE @Porc_Recargo_3_Vto				DECIMAL(12,5)
DECLARE @Comercio_Nro					VARCHAR(50)
DECLARE @Id_Cliente						INT
DECLARE @Id_Contrato					INT
DECLARE @Comprobante_Nro				INT
DECLARE @Fecha_Cbte						DATETIME
DECLARE @Id_Cliente_Externo				VARCHAR(14)
DECLARE @Id_Cliente_Ref					INT
DECLARE @Doc_Nro						BIGINT
DECLARE @Tipo_Persona					CHAR(1)
DECLARE @Porc_Recargo					DECIMAL(12,5)	
DECLARE @Id_Tipo_Cbte					VARCHAR(4)
DECLARE @Descripcion_Corta				VARCHAR(11)
DECLARE @Descripcion_Larga				VARCHAR(36)
DECLARE @Id_Cliente_Externo_Tit			VARCHAR(14)
DECLARE @Item_1							SMALLINT
DECLARE @Id_Cond_Pago_Item				SMALLINT
/*FIN Variables Locales*/

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

/*Seteo Variables Locales*/
SELECT	
@Id_Tarjeta				= ISNULL(Id_Tarjeta, ''),
@Fecha_Presentacion		= ISNULL(Fecha_Presentacion, '19000101'),
@Fecha_1_Vto			= ISNULL(Fecha_1_Vto, '19000101'),
@Fecha_2_Vto			= ISNULL(Fecha_2_Vto, '19000101'),
@Fecha_3_Vto			= ISNULL(Fecha_3_Vto, '19000101')
FROM Val_Tarjetas_Lotes
WHERE
Id_Tar_Lote = @pId_Tar_Lote

SELECT
@Comercio_Nro			= LTRIM(RTRIM(ISNULL(Comercio_Nro, '')))
FROM Valores_Tarjetas_Cred
WHERE
ISNULL(Id_Tarjeta, '') = @Id_Tarjeta

SELECT	
@Id_Cliente		= ISNULL(Id_Cliente, 0),
@Fecha_Cbte		= ISNULL(Fecha, '19000101'),
@Id_Contrato	= ISNULL(Id_Contrato, 0),
@Comprobante_Nro= ISNULL(Comprobante_Nro, 0),
@Id_Tipo_Cbte	= ISNULL(Id_Tipo_Cbte, '')
FROM Cbtes 
WHERE
Id_Trans = @pId_Trans

SELECT
@Item_1			= MIN(Item)
FROM Cbtes_Items
WHERE
Id_Trans = @pId_Trans

SELECT
@Id_Cond_Pago_Item = ISNULL(Id_Cond_Pago, 0)
FROM Cbtes_Items
WHERE
Id_Trans = @pId_Trans
AND Item = @Item_1

SET @Porc_Recargo_1_Vto = ISNULL(	(SELECT 
									ISNULL(Porc_Bonif, 0)
									FROM Cbtes_Cond_Pago_Items 
									WHERE 
									Id_Cond_Pago = @Id_Cond_Pago_Item 
									AND Plazo_Desde <= DATEPART(DAY, @Fecha_1_Vto)
									AND Plazo_Bonif >= DATEPART(DAY, @Fecha_1_Vto))
								, 0)

SET @Porc_Recargo_1_Vto = (@Porc_Recargo_1_Vto / 100) + 1

SET @Porc_Recargo_2_Vto = ISNULL(	(SELECT 
									ISNULL(Porc_Bonif, 0)
									FROM Cbtes_Cond_Pago_Items 
									WHERE 
									Id_Cond_Pago = @Id_Cond_Pago_Item 
									AND Plazo_Desde <= DATEPART(DAY, @Fecha_2_Vto)
									AND Plazo_Bonif >= DATEPART(DAY, @Fecha_2_Vto))
								, 0)

SET @Porc_Recargo_2_Vto = (@Porc_Recargo_2_Vto / 100) + 1

SET @Porc_Recargo_3_Vto = ISNULL(	(SELECT 
									ISNULL(Porc_Bonif, 0)
									FROM Cbtes_Cond_Pago_Items 
									WHERE 
									Id_Cond_Pago = @Id_Cond_Pago_Item 
									AND Plazo_Desde <= DATEPART(DAY, @Fecha_3_Vto)
									AND Plazo_Bonif >= DATEPART(DAY, @Fecha_3_Vto))
								, 0)

SET @Porc_Recargo_3_Vto = (@Porc_Recargo_3_Vto / 100) + 1

SELECT 
@Id_Cliente_Externo		= ISNULL(Id_Cliente_Externo, Id_Cliente),
@Id_Cliente_Ref			= ISNULL(Id_Cliente_Ref, 0),
@Doc_Nro				= ISNULL(Doc_Nro, 0),
@Tipo_Persona			= ISNULL(Tipo_Persona, 'F')
FROM Clientes 
WHERE 
Id_Cliente = @Id_Cliente

SELECT 
@Id_Cliente_Externo_Tit		= ISNULL(Id_Cliente_Externo, Id_Cliente)
FROM Clientes 
WHERE 
Id_Cliente = @Id_Cliente_Ref

IF(@Porc_Recargo = 0)
BEGIN
	SET @Porc_Recargo = 1
END
ELSE
BEGIN
	SET @Porc_Recargo = (@Porc_Recargo / 100) + 1
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@Tipo_Persona = 'I'/*Inmueble*/)
BEGIN
	IF(dbo.CF_IsNumeric(@Id_Cliente_Externo_Tit) = 1)
	BEGIN
		SET @Id_Cliente_Externo = CONVERT(VARCHAR(14), @Id_Cliente_Ref)
	END
	ELSE
	BEGIN
		SET @Id_Cliente_Externo = @Id_Cliente_Externo_Tit
	END
END
ELSE
BEGIN
	IF(dbo.CF_IsNumeric(@Id_Cliente_Externo) = 1)
	BEGIN
		SET @Id_Cliente_Externo = @Id_Cliente_Externo
	END
	ELSE
	BEGIN
		SET @Id_Cliente_Externo = CONVERT(VARCHAR(14), @Id_Cliente)
	END
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@Tipo_Persona = 'I'/*Inmueble*/)
BEGIN
	SET @Descripcion_Corta = 'EXP '
	SET @Descripcion_Larga = 'EXPENSAS '
END
ELSE
BEGIN
	IF(@Id_Tipo_Cbte = 'CUP')
	BEGIN
		SET @Descripcion_Corta = 'C SOC '
		SET @Descripcion_Larga = 'CUOTA SOCIAL '
	END
	ELSE
	BEGIN
		SET @Descripcion_Corta = 'ACT C SOC '
		SET @Descripcion_Larga = 'CUOTA SOCIAL ACTIVIDADES '
	END
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------



-------------------------------------------------------------------------------------------------------------------------------------------------------------------

/*Seteo variables del Archivo*/
SET @aCod_Registro		= '5'

SET @aNroReferencia		= '0' + RIGHT('00000000' + @Id_Cliente_Externo, 8) + RIGHT('0000000000' + @Comercio_Nro, 10)

SET @aId_Factura		= RIGHT('000000000000000' + CAST(@pId_Trans AS VARCHAR), 15) + '4' + RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_Cbte) AS VARCHAR), 2) + SUBSTRING(RIGHT('0000' + CAST(DATEPART(YEAR, @Fecha_Cbte) AS VARCHAR), 4), 3, 2)
                 
SET @aId_Moneda			= '0'

SET @aFecha_PriVenc		= RIGHT('0000' + CAST(DATEPART(YEAR, @Fecha_1_Vto) AS VARCHAR), 4) + RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_1_Vto) AS VARCHAR), 2) + RIGHT('00' + CAST(DATEPART(DAY, @Fecha_1_Vto) AS VARCHAR), 2)

SET @aImporte_PriVenc	= (SELECT RIGHT('00000000000' + CAST(CAST(@pImporte * @Porc_Recargo_1_Vto * 100 AS INT) AS VARCHAR), 11))

SET @aFecha_SegVenc		= RIGHT('0000' + CAST(DATEPART(YEAR, @Fecha_2_Vto) AS VARCHAR), 4) + RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_2_Vto) AS VARCHAR), 2) + RIGHT('00' + CAST(DATEPART(DAY, @Fecha_2_Vto) AS VARCHAR), 2)

SET @aImporte_SegVenc	= (SELECT RIGHT('00000000000' + CAST(CAST(@pImporte * @Porc_Recargo_2_Vto * 100 AS INT) AS VARCHAR), 11))

SET @aFecha_TerVenc		= RIGHT('0000' + CAST(DATEPART(YEAR, @Fecha_3_Vto) AS VARCHAR), 4) + RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_3_Vto) AS VARCHAR), 2) + RIGHT('00' + CAST(DATEPART(DAY, @Fecha_3_Vto) AS VARCHAR), 2)

SET @aImporte_TerVenc	= (SELECT RIGHT('00000000000' + CAST(CAST(@pImporte * @Porc_Recargo_3_Vto * 100 AS INT) AS VARCHAR), 11))

SET @aFiller1			= '0000000000000000000'

SET @aNro_Referencia_Ant = @aNroReferencia

		 
SET @aMensajeTicket		= @Descripcion_Larga + RIGHT('00' + CAST(DATEPART(MONTH, @pPeriodo) AS VARCHAR), 2) + SUBSTRING(RIGHT('0000' + CAST(DATEPART(YEAR, @pPeriodo) AS VARCHAR), 4), 3, 2)

SET @aMensajePantalla	= @Descripcion_Corta + RIGHT('00' + CAST(DATEPART(MONTH, @pPeriodo) AS VARCHAR), 2) + SUBSTRING(RIGHT('0000' + CAST(DATEPART(YEAR, @pPeriodo) AS VARCHAR), 4), 3, 2)
                
SET @aCodBarra			= '                                                            '

SET @aFiller2			= '00000000000000000000000000000'

-------------------------------------------------------------------------------------------------------------------------------------------------------------------
                    
SET @Retorno =	@aCod_Registro		+ 
				@aNroReferencia		+ 
				@aId_Factura		+ 
				@aId_Moneda			+
				@aFecha_PriVenc		+
				@aImporte_PriVenc	+
				@aFecha_SegVenc		+
				@aImporte_SegVenc	+
				@aFecha_TerVenc		+
				@aImporte_TerVenc	+
				@aFiller1			+
				@aNro_Referencia_Ant +
				@aMensajeTicket		+
				@aMensajePantalla	+
				@aCodBarra			+
				@aFiller2

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

RETURN ISNULL(@Retorno, '                                                                                                                                                                                                                                                                                        ')
END
GO


CREATE FUNCTION [dbo].[CF_Banco_Scotiabank_UY_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT, @pPeriodo DATETIME) 
RETURNS CHAR(121)
AS
BEGIN

/*Variables Archivo*/
DECLARE @Retorno						CHAR(121)

DECLARE @aNro_Documento					CHAR(18)	/*Formato: Alfanumerico (18).	Desde: 001. Hasta: 018. Nota: Nro RUC o BPS Empresa.*/
DECLARE @aCod_Documento					CHAR(2)		/*Formato: Alfanumerico (2).	Desde: 019. Hasta: 020. Nota: En Blanco.*/
DECLARE @aCat_Cliente					CHAR(1)		/*Formato: Alfanumerico (1).	Desde: 021. Hasta: 021. Nota: Siempre J.*/
DECLARE @aOperativa						CHAR(2)		/*Formato: Alfanumerico (2).	Desde: 022. Hasta: 023. Nota: 03 para debitos.*/
DECLARE @aFecha							CHAR(8)		/*Formato: Alfanumerico (8).	Desde: 024. Hasta: 031. Nota: DDMMAAAA.*/
DECLARE @aServicio						CHAR(21)	/*Formato: Alfanumerico (21).	Desde: 032. Hasta: 052. Nota: Nro de Identificador Afiliado.*/
DECLARE @aImporte						CHAR(15)	/*Formato: Numerico (15).		Desde: 053. Hasta: 067. Nota: 13 Enteros y 2 Decimales.*/
DECLARE @aSigno							CHAR(1)		/*Formato: Alfanumerico (1).	Desde: 068. Hasta: 068. Nota: -.*/
DECLARE @aMoneda						CHAR(2)		/*Formato: Alfanumerico (2).	Desde: 069. Hasta: 070. Nota: 00: Pesos Uruguayos, 01: Dolares Estadounidenses*/
DECLARE @aId_Factura					CHAR(12)	/*Formato: Alfanumerico (12).	Desde: 071. Hasta: 082. Nota: Es obligatorio si es Consumidor Final.*/
DECLARE @aIndicador_Consumidor_Final	CHAR(1)		/*Formato: Numerico (1).		Desde: 083. Hasta: 083. Nota: 0: No Conusmidor Final, 1: Consumidor Final.*/
DECLARE @aImporte_Grav_Iva_Basico		CHAR(15)	/*Formato: Numerico (15).		Desde: 084. Hasta: 097. Nota: 13 Enteros y 2 Decimales.*/
DECLARE @aImporte_Grav_Iva_Minimo		CHAR(15)	/*Formato: Numerico (15).		Desde: 098. Hasta: 112. Nota: 13 Enteros y 2 Decimales.*/
DECLARE @aFecha_Facturacion				CHAR(8)		/*Formato: Alfanumerico (8).	Desde: 113. Hasta: 120. Nota: DDMMAAAA.*/
/*FIN Variables Archivo*/

/*Variable Locales*/
DECLARE @Id_Tarjeta				VARCHAR(10)
DECLARE @Fecha_Presentacion		DATETIME
DECLARE @Comercio_Nro			VARCHAR(50)
DECLARE @Tar_Nro				VARCHAR(22)
DECLARE @Id_Contrato			INT
DECLARE @Tar_Fecha_Vence		DATETIME
DECLARE @Fecha_Cbte				DATETIME
DECLARE @Mes_Periodo			SMALLINT
DECLARE @Mes_Periodo_VC			VARCHAR(3)
DECLARE @Id_Cliente				INT
DECLARE @Id_Cliente_Externo		INT
DECLARE @Comprobante_Nro		INT
DECLARE @Id_Cliente_Ref			INT
DECLARE @Doc_Nro				BIGINT
DECLARE @Doc_Nro_Titular		BIGINT
DECLARE @Param_Rece_Cuit		VARCHAR(40)
/*FIN Variable Locales*/

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

/*Seteo Variables Locales*/
SELECT	
@Id_Tarjeta				= ISNULL(Id_Tarjeta, ''),
@Fecha_Presentacion		= ISNULL(Fecha_Presentacion, '19000101')
FROM Val_Tarjetas_Lotes
WHERE
Id_Tar_Lote = @pId_Tar_Lote

SELECT
@Comercio_Nro			= LTRIM(RTRIM(ISNULL(Comercio_Nro, '')))
FROM Valores_Tarjetas_Cred
WHERE
ISNULL(Id_Tarjeta, '') = @Id_Tarjeta

SELECT	
@Tar_Nro		= ISNULL(DBO.SF_COTIZA(Nro), '') 
FROM Val_Tarjetas_Lotes_Items 
WHERE
Id_Tar_Lote = @pId_Tar_Lote
AND Id_Trans = @pId_Trans

SELECT	
@Id_Cliente				= ISNULL(Id_Cliente, 0),
@Fecha_Cbte				= ISNULL(Fecha, '19000101'),
@Id_Contrato			= ISNULL(Id_Contrato, 0),
@Comprobante_Nro		= ISNULL(Comprobante_Nro, 0)
FROM Cbtes 
WHERE
Id_Trans = @pId_Trans

SELECT 
@Id_Cliente_Externo		= ISNULL(Id_Cliente_Externo, Id_Cliente),
@Id_Cliente_Ref			= ISNULL(Id_Cliente_Ref, 0),
@Doc_Nro				= ISNULL(Doc_Nro, 0)
FROM Clientes
WHERE
Id_Cliente = @Id_Cliente

SELECT
@Doc_Nro_Titular		= ISNULL(Doc_Nro, 0)
FROM Clientes
WHERE
Id_Cliente = @Id_Cliente_Ref

SELECT
@Tar_Fecha_Vence		= ISNULL(Tar_Fecha_Vence, DATEADD(YEAR, 1, GETDATE()))
FROM Contratos
WHERE
Id_Contrato = @Id_Contrato

SET @Mes_Periodo = DATEPART(MONTH, @pPeriodo)

SELECT
@Mes_Periodo_VC =	CASE @Mes_Periodo
						WHEN 1	THEN 'ENE'
						WHEN 2	THEN 'FEB'
						WHEN 3	THEN 'MAR'
						WHEN 4	THEN 'ABR'
						WHEN 5	THEN 'MAY'
						WHEN 6	THEN 'JUN'
						WHEN 7	THEN 'JUL'
						WHEN 8	THEN 'AGO'
						WHEN 9	THEN 'SEP'
						WHEN 10 THEN 'OCT'
						WHEN 11 THEN 'NOV'
						WHEN 12 THEN 'DIC'
					END

SET @Param_Rece_Cuit = LTRIM(RTRIM(dbo.CF_xParam('RECE_CUIT')))

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

SET @aNro_Documento					= '   ' + @Comercio_Nro + '   '

SET @aCod_Documento					= '  '

SET @aCat_Cliente					= 'J'

SET @aOperativa						= '03' /*Debito Automatico*/

SET @aFecha							= RIGHT('00' + CAST(DATEPART(DAY, @Fecha_Presentacion) AS VARCHAR), 2) + 
									  RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_Presentacion) AS VARCHAR), 2)  + 
									  RIGHT('0000' + CAST(DATEPART(YEAR, @Fecha_Presentacion) AS VARCHAR), 4)
															
SET @aServicio						= @Id_Cliente_Externo

SET @aImporte						= RIGHT('000000000000000' + CAST(CAST(@pImporte * 100 AS INT) AS VARCHAR), 15)

SET @aSigno							= '-'

SET @aMoneda						= '00'	/*Pesos Uruguayos*/

SET @aId_Factura					= (RIGHT('000000000000' + CAST(@pId_Trans AS VARCHAR), 12))

SET @aIndicador_Consumidor_Final	= '1'	/*Consumidor Final*/

SET @aImporte_Grav_Iva_Basico		= '               '

SET @aImporte_Grav_Iva_Minimo		= '               '

SET @aFecha_Facturacion				= RIGHT('00' + CAST(DATEPART(DAY, @Fecha_Cbte) AS VARCHAR), 2) + 
									  RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_Cbte) AS VARCHAR), 2)  + 
									  RIGHT('0000' + CAST(DATEPART(YEAR, @Fecha_Cbte) AS VARCHAR), 4)

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

SET @Retorno =	@aNro_Documento					+
				@aCod_Documento					+
				@aCat_Cliente					+
				@aOperativa						+
				@aFecha							+
				@aServicio						+
				@aImporte						+
				@aSigno							+
				@aMoneda						+
				@aId_Factura					+
				@aIndicador_Consumidor_Final	+
				@aImporte_Grav_Iva_Basico		+
				@aImporte_Grav_Iva_Minimo		+
				@aFecha_Facturacion 

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

RETURN ISNULL(@Retorno, '                                                                                                                         ')
END
GO


CREATE FUNCTION [dbo].[CF_Banelco_CB_TX](@pId_Trans INT, @pImporte DECIMAL(12,2)) 
RETURNS CHAR(56)
AS
BEGIN

DECLARE @Retorno				CHAR(56)
DECLARE @aCuit					CHAR(11)
DECLARE @aId_Cliente			CHAR(10)	/*Identificación del cliente en la empresa.  Se refiere a la identificación que deberá ingresar el cliente para poder pagar, que le sirve a la empresa para saber quien le está pagando. Son los números que componen el “concepto utilizado como ID del cliente” que la empresa completó en el formulario de adhesión.*/
DECLARE @aId_Trans				CHAR(15)	/*Identificación de la factura. Se refiere a la identificación particular de la factura que está pagando el cliente. No tiene que ser obligatoriamente el “Nro. de Factura”, sino que puede ser cualquier número que utilice la empresa para individualizar el pago (puede que para un mismo Nro. Referencia, haya varios Id. Factura, si un cliente tiene varias facturas a pagar).*/
DECLARE @aImporte				CHAR(12)	/*Importe de la factura para el 1er vencimiento. Formato: 10 enteros, 2 decimales, sin separadores*/
DECLARE @aFecha					CHAR(8)		/*Fecha del 1er vencimiento de la factura Formato: AAAAMMDD*/
DECLARE @aId_Cliente_Externo	CHAR(10)
DECLARE @TipoIdentPrim			INT	
DECLARE @Id_Cliente				INT

/*Seteo Variables Locales*/
SELECT	@Id_Cliente = Id_Cliente
		
FROM Cbtes 
WHERE
Id_Trans = @pId_Trans

SET @TipoIdentPrim = dbo.CF_xParam('Banelco_IdentPrim')

SET @aId_Cliente_Externo = ISNULL((SELECT ISNULL(Id_cliente_Externo,'') from Clientes WHERE Id_Cliente = @Id_Cliente),0)

/*Se arma el Codigo de Barra*/

SET @aCuit			= '99999999999'

IF (@TipoIdentPrim = 0)		/*Utiliza Id_Cliente como Nro de referencia de Cliente*/
BEGIN
	SET @aId_Cliente	= (SELECT RIGHT('0000000000' + CAST(Id_Cliente AS VARCHAR), 10) FROM Cbtes WHERE Id_Trans = @pId_Trans)
END
ELSE IF (@TipoIdentPrim = 1) /*Utiliza Id_Cliente_Externo como Nro de referencia de Cliente*/
BEGIN
	SET @aId_Cliente	= (RIGHT('0000000000' + CAST(@aId_Cliente_Externo AS VARCHAR), 10))
END


SET @aId_Trans		= (SELECT RIGHT('000000000000000' + CAST(@pId_Trans AS VARCHAR), 15))

SET @aImporte		= (SELECT RIGHT('000000000000' + CAST(CAST(@pImporte * 100 AS INT) AS VARCHAR), 12))

SET @aFecha			= (	SELECT
						CAST(DATEPART(YY,Fecha_Venc) as CHAR(4)) + 
						RIGHT( '00' + CAST(DATEPART(mm,Fecha_Venc) AS VARCHAR),2) + 
						RIGHT( '00' + CAST(DATEPART(dd,Fecha_Venc) AS VARCHAR),2) 
						FROM Cbtes 
						WHERE 
						Id_Trans = @pId_Trans)

SET @Retorno =	@aCuit			+ 
				@aId_Cliente	+ 
				@aId_Trans		+ 
				@aImporte		+ 
				@aFecha 

RETURN ISNULL(@Retorno, '                                                        ')
END
GO


CREATE FUNCTION [dbo].[CF_Banelco_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT) 
RETURNS CHAR(280)
AS
BEGIN

DECLARE @Retorno			CHAR(280)
DECLARE @aCod_Registro		CHAR(1)		/*C¥digo de Registro. Valor fijo: 5. Indica que este rengl¥n forma parte del detalle.*/
DECLARE @aId_Cliente		CHAR(19)	/*Identificaci¥n del cliente en la empresa.  Se refiere a la identificaci¥n que deber▀ ingresar el cliente para poder pagar, que le sirve a la empresa para saber quien le est▀ pagando. Son los nÀmeros que componen el ¶concepto utilizado como ID del cliente÷ que la empresa complet¥ en el formulario de adhesi¥n.*/
DECLARE @aId_Trans			CHAR(20)	/*Identificaci¥n de la factura. Se refiere a la identificaci¥n particular de la factura que est▀ pagando el cliente. No tiene que ser obligatoriamente el ¶Nro. de Factura÷, sino que puede ser cualquier nÀmero que utilice la empresa para individualizar el pago (puede que para un mismo Nro. Referencia, haya varios Id. Factura, si un cliente tiene varias facturas a pagar).*/
DECLARE @aId_Moneda			CHAR(1)		/*C¥digo de moneda de los importes informados. Valor fijo: 0 (Pesos).*/
DECLARE @aFecha_PriVenc		CHAR(8)		/*Fecha del 1er vencimiento de la factura Formato: AAAAMMDD*/
DECLARE @aImporte_PriVenc	CHAR(11)	/*Importe de la factura para el 1er vencimiento. Formato: 9 enteros, 2 decimales, sin separadores*/
DECLARE @aFecha_SegVenc		CHAR(8)		/*Fecha del 2do vencimiento de la factura Formato: AAAAMMDD*/
DECLARE @aImporte_SegVenc	CHAR(11)	/*Importe de la factura para el 2do vencimiento. Formato: 9 enteros, 2 decimales, sin separadores*/
DECLARE @aFecha_TerVenc		CHAR(8)		/*Fecha del 3er vencimiento de la factura Formato: AAAAMMDD*/
DECLARE @aImporte_TerVenc	CHAR(11)	/*Importe de la factura para el 3er vencimiento. Formato: 9 enteros, 2 decimales, sin separadores*/
DECLARE @aFiller1			CHAR(19)	/*Campo para uso futuro. Valor fijo: ceros.*/
DECLARE @aId_Cliente_Externo CHAR(19)	/*Se debe repetir la informaci¥n del campo ¶Nro. Referencia÷. En caso que se modifique la identificaci¥n del cliente, se deber▀ informar la identificaci¥n anterior por Ànica vez, luego se deber▀ repetir la informaci¥n del campo Nro. Referencia.*/
DECLARE @aMensajeTicket		CHAR(40)	/*Datos a informar en el ticket de pago. Es el mensaje  que se imprimir▀ en el comprobante de pago que se refiere al concepto abonado por el cliente. Ej: Cuota Noviembre.*/
DECLARE @aMensajePantalla	CHAR(15)	/*Datos a informar en la pantalla de selecci¥n de la factura a pagar. Es el mensaje que ver▀ el cliente en pantalla antes de confirmar el pago. Se refiere al mismo concepto que el campo ¶Mensaje Ticket÷, pero con menos caracteres.*/
DECLARE @aCodBarra			CHAR(60)	/*C¥digo de barras. Son los nÀmeros que componen el c¥digo de barras de la empresa. Si no posee uno, se debe completar el campo con espacios.*/
DECLARE @aFiller2			CHAR(29)	/*Campo para uso futuro. Valor fijo: ceros.*/
DECLARE @Id_Cliente			INT
DECLARE @Id_Cliente_Externo	INT
DECLARE @Fecha				DATETIME
DECLARE @CantCerosCompletarId_Cliente INT
DECLARE @Fecha_Presentacion		DATETIME
DECLARE @Id_Cond_Pago		SMALLINT
DECLARE @Cant_Dias_Desde_Cbtes_Hasta_Presentacion INT
DECLARE @Porc_Recargo		DECIMAL(12,5)	
DECLARE @Fecha_PriVenc		DATETIME
DECLARE @Fecha_SegVenc		DATETIME
DECLARE @Fecha_TerVenc		DATETIME
DECLARE @TipoIdentPrim		INT
DECLARE @Id_Primario		CHAR(10)
DECLARE @contieneLetras		INT


/*Seteo Variables Locales*/
SELECT	@Fecha_Presentacion = ISNULL(Fecha_Presentacion, '19000101')
FROM Val_Tarjetas_Lotes
WHERE
Id_Tar_Lote = @pId_Tar_Lote


SELECT	@Id_Cliente		= Id_Cliente,
		@Fecha			= Fecha,
		@Id_Cond_Pago	= Id_Cond_Pago
FROM Cbtes 
WHERE
Id_Trans = @pId_Trans


SET @Porc_Recargo = ISNULL((SELECT Porc_Bonif FROM Cbtes_Cond_Pago_Items WHERE Id_Cond_Pago = @Id_Cond_Pago AND Plazo_Desde <= @Cant_Dias_Desde_Cbtes_Hasta_Presentacion AND Plazo_Bonif >= @Cant_Dias_Desde_Cbtes_Hasta_Presentacion),0)

IF(@Porc_Recargo = 0)
BEGIN
	SET @Porc_Recargo = 1
END
ELSE
BEGIN
	SET @Porc_Recargo = (@Porc_Recargo / 100) + 1
END

SET @CantCerosCompletarId_Cliente = dbo.CF_xParam('Banelco_CantDigCli')

SET @TipoIdentPrim = dbo.CF_xParam('Banelco_IdentPrim')

SET @contieneLetras = (SELECT ISNUMERIC(id_cliente_externo) FROM clientes WHERE id_cliente= @Id_Cliente)

IF(@contieneLetras=0)
BEGIN
	SET @Id_Cliente_Externo = ISNULL((SELECT Id_Cliente from Clientes WHERE Id_Cliente = @Id_Cliente),0)
END
ELSE
BEGIN
	SET @Id_Cliente_Externo = ISNULL((SELECT ISNULL(Id_cliente_Externo,'') from Clientes WHERE Id_Cliente = @Id_Cliente),0)
END

/*Seteo variables del Archivo*/
SET @aCod_Registro		= '5'

IF (@TipoIdentPrim = 0)		/*Utiliza Id_Cliente como Nro de referencia de Cliente*/
BEGIN
	
	SET @Id_Primario = (CAST(@Id_Cliente AS VARCHAR))

END 
ELSE IF (@TipoIdentPrim = 1) /*Utiliza Id_Cliente_Externo como Nro de referencia de Cliente*/
BEGIN

	SET @Id_Primario = (CAST(@Id_Cliente_Externo AS VARCHAR))

END

IF(@CantCerosCompletarId_Cliente = 0)
BEGIN
	SET @aId_Cliente		= (CAST(@Id_Primario AS VARCHAR))
END

IF(@CantCerosCompletarId_Cliente = 8)
BEGIN
	SET @aId_Cliente		= (RIGHT('00000000' + CAST(CAST(@Id_Primario AS INT) AS VARCHAR), 8))
END

SET @aId_Trans			= (SELECT RIGHT( '000000000000000' + CAST(@pId_Trans AS VARCHAR), 15))
                 
SET @aId_Moneda			= '0'

SET @Fecha_PriVenc		=  dbo.CF_FOMONTH(@Fecha_Presentacion)
SET @Fecha_PriVenc		= DATEADD(dd, 14, @Fecha_PriVenc)

SET @aFecha_PriVenc = (	SELECT 
							CAST(DATEPART(YY, @Fecha_PriVenc) AS CHAR(4)) + 
							RIGHT('00' + CAST(DATEPART(mm, @Fecha_PriVenc) AS VARCHAR),2) + 
							RIGHT('00' + CAST(DATEPART(dd, @Fecha_PriVenc) AS VARCHAR),2))

/*Calculo Porcentaje segun cond Pago*/
SET @Cant_Dias_Desde_Cbtes_Hasta_Presentacion = DATEDIFF(dd, @Fecha, @Fecha_PriVenc) + 1
SET @Porc_Recargo = ISNULL((SELECT Porc_Bonif FROM Cbtes_Cond_Pago_Items WHERE Id_Cond_Pago = @Id_Cond_Pago AND Plazo_Desde <= @Cant_Dias_Desde_Cbtes_Hasta_Presentacion AND Plazo_Bonif >= @Cant_Dias_Desde_Cbtes_Hasta_Presentacion),0)

IF(@Porc_Recargo = 0)
BEGIN
	SET @Porc_Recargo = 1
END
ELSE
BEGIN
	SET @Porc_Recargo = (@Porc_Recargo / 100) + 1
END
/*FIN Calculo Porcentaje segun cond Pago*/

SET @aImporte_PriVenc	= (SELECT RIGHT('00000000000' + CAST(CAST(@pImporte * @Porc_Recargo * 100 AS INT) AS VARCHAR), 11))


SET @Fecha_SegVenc		= DATEADD(dd, 1, @Fecha_PriVenc)

SET @aFecha_SegVenc		= (	SELECT 
							CAST(DATEPART(YY, @Fecha_SegVenc) AS CHAR(4)) + 
							RIGHT('00' + CAST(DATEPART(mm, @Fecha_SegVenc) AS VARCHAR),2) + 
							RIGHT('00' + CAST(DATEPART(dd, @Fecha_SegVenc) AS VARCHAR),2))

/*Calculo Porcentaje segun cond Pago*/
SET @Cant_Dias_Desde_Cbtes_Hasta_Presentacion = DATEDIFF(dd, @Fecha, @Fecha_SegVenc) + 1
SET @Porc_Recargo = ISNULL((SELECT Porc_Bonif FROM Cbtes_Cond_Pago_Items WHERE Id_Cond_Pago = @Id_Cond_Pago AND Plazo_Desde <= @Cant_Dias_Desde_Cbtes_Hasta_Presentacion AND Plazo_Bonif >= @Cant_Dias_Desde_Cbtes_Hasta_Presentacion),0)

IF(@Porc_Recargo = 0)
BEGIN
	SET @Porc_Recargo = 1
END
ELSE
BEGIN
	SET @Porc_Recargo = (@Porc_Recargo / 100) + 1
END
/*FIN Calculo Porcentaje segun cond Pago*/

SET @aImporte_SegVenc	= (SELECT RIGHT('00000000000' + CAST(CAST(@pImporte * @Porc_Recargo * 100 AS INT) AS VARCHAR), 11))

SET @aFecha_TerVenc		= '00000000'

SET @aImporte_TerVenc	= '00000000000'

SET @aFiller1			= '0000000000000000000'

/*20/05/2019. Se Cambia el Campo Id_Cliente_Externo por Id_Cliente por el ticket 16.648 ya que se indica que el Identificador de Cliente (Campo 2) debe ser igual al Campo 12*/
--SET @aId_Cliente_Externo = (SELECT CAST(ISNULL(Id_Cliente_Externo, '') AS VARCHAR) FROM Clientes WHERE Id_Cliente = @Id_Cliente)
/*IF(@CantCerosCompletarId_Cliente = 0)
BEGIN
	SET @aId_Cliente_Externo = (CAST(@Id_Cliente AS VARCHAR))
END

IF(@CantCerosCompletarId_Cliente = 8)
BEGIN
	SET @aId_Cliente_Externo = (RIGHT('00000000' + CAST(@Id_Cliente AS VARCHAR), 8))
END*/

SET @aId_Cliente_Externo = @aId_Cliente
		 
SET @aMensajeTicket		= 'MES' + RIGHT('00' + CAST(MONTH(@Fecha) AS VARCHAR), 2) + '/' + CAST(YEAR(@Fecha) AS CHAR(4)) + '                              '
SET @aMensajePantalla	= 'MES' + RIGHT('00' + CAST(MONTH(@Fecha) AS VARCHAR), 2) + '/' + CAST(YEAR(@Fecha) AS CHAR(4)) + '     '
                
SET @aCodBarra = (dbo.CF_Banelco_CB_TX(@pId_Trans, @pImporte)) 

SET @aFiller2			= '00000000000000000000000000000'
                    
SET @Retorno =	@aCod_Registro		+ 
				@aId_Cliente		+ 
				@aId_Trans			+ 
				@aId_Moneda			+
				@aFecha_PriVenc		+
				@aImporte_PriVenc	+
				@aFecha_SegVenc		+
				@aImporte_SegVenc	+
				@aFecha_TerVenc		+
				@aImporte_TerVenc	+
				@aFiller1			+
				@aId_Cliente_Externo +
				@aMensajeTicket		+
				@aMensajePantalla	+
				@aCodBarra			+
				@aFiller2
   
RETURN ISNULL(@Retorno, '                                                                                                                                                                                                                                                                                        ')
END
GO


CREATE FUNCTION dbo.CF_Caja_Transf_Alias_Cont   (@Id_Periodo_Caja INT, @Id_Tipo_Val CHAR(3),@Id_Moneda CHAR(3))
RETURNS INT	
AS
BEGIN

DECLARE @Retorno 	SMALLINT
	,@Id_Caja INT
	,@Id_Concepto INT
	
SET @Id_Caja = ISNULL(
				(SELECT Id_Caja  FROM Cajas_Periodos WHERE Id_Periodo_Caja = @Id_Periodo_Caja)
				,0)
/* Tabla de cuentas de la caja*/
SET @Retorno = ISNULL(
				(SELECT Id_Alias_Cta_Cont FROM Cajas_Ctas_Cont 
				    WHERE Id_Caja = @Id_Caja 
					  AND Id_Tipo_Val = @Id_Tipo_Val
					  AND Id_Moneda = @Id_Moneda )
				,0)

/* Cuenta de la caja*/
IF @Retorno = 0 AND @Id_Tipo_Val = 'EFE'
BEGIN
	SET @Retorno = ISNULL(
					(SELECT Id_Cta_Contable FROM Cajas 
						WHERE Id_Caja = @Id_Caja)
					,0)
END

/* Cuenta de los valores*/
IF @Retorno = 0
BEGIN
	SET @Retorno = ISNULL(
					(SELECT Id_Alias_Cta_Cont  FROM Valores_Tipos
						WHERE Id_Tipo_Val = @Id_Tipo_Val)
					,0)

END

/* Cuenta de los valores*/
IF @Retorno = 0
BEGIN
	SET @Id_Concepto = ISNULL(
					dbo.CF_xParam('Trans_Concepto')
					,0)
	SET @Retorno = ISNULL(
					(SELECT Id_Cta_Contable FROM Conceptos
						WHERE Id_Concepto = @Id_Concepto)
					,0)

END

RETURN ISNULL(@Retorno,0);

END
GO


CREATE FUNCTION dbo.CF_Cbte_Cob_Permitir   (@Id_Trans INT, @Fecha DATETIME)
RETURNS INT	
AS
BEGIN

/*
Descripci¾n:Valida si el cbte. se puede cob
Fecha de creaci¾n: 4/12/2018
Auto: GC
Retorno: Retorna cero cuando es habilitada la cobranza
*/


DECLARE @Retorno 	SMALLINT;

/* Valido Cant_Meses_Cobro_Atrasado */

SET @Retorno = ISNULL((Select COUNT(*) from cbtes_items i, Productos P, Prod_Familias F 
                 where I.id_trans = @Id_Trans
                  And P.id_producto = I.Id_Producto 
                  And P.Id_Familia = F.Id_Familia 
                  And ISNULL(F.Cant_Meses_Cobro_Atrasado,0) <> 0 
                  And (I.FECHA_QA + F.Cant_Meses_Cobro_Atrasado) < @Fecha),0)


/* Agregar resto de validaciones aca */


RETURN ISNULL(@Retorno,0);

END
GO


CREATE FUNCTION [dbo].[CF_Cbte_Descrip](@pId_Trans INT)
RETURNS VARCHAR(100)	
AS

BEGIN

DECLARE @Descripcion			VARCHAR(100)
DECLARE @Id_Tipo_Cbte			CHAR(4)
DECLARE @Id_Sucursal			SMALLINT
DECLARE @Id_Sucursal_Compra 	SMALLINT
DECLARE @Compromete_Compras		SMALLINT
DECLARE @Compromete_Remitos		SMALLINT
DECLARE @Letra					VARCHAR(3)
DECLARE @Descrip_Corta			CHAR(4)
DECLARE @Cant_Dig_Cbtes			INT
DECLARE @Sucursal_Char			VARCHAR(5)
DECLARE @Comprobante_Nro		INT
DECLARE @Comprobante_Nro_Char	VARCHAR(9)



SELECT @Id_Tipo_Cbte		= ISNULL(CB.Id_Tipo_Cbte, '')
     , @Descrip_Corta		= ISNULL(RTRIM(LTRIM(CT.Descrip_Corta)), '')
	 , @Letra				= ISNULL(RTRIM(LTRIM(CT.Letra)), '')
	 , @Id_Sucursal			= ISNULL(CT.Id_Sucursal, 0)
	 , @Id_Sucursal_Compra	= ISNULL(CB.Id_Sucursal, 0)
	 , @Compromete_Compras	= ISNULL(CT.Compromete_Compras, 0)
	 , @Compromete_Remitos	= ISNULL(CT.Compromete_Remitos, 0)
FROM Cbtes CB, Cbtes_Tipos CT
WHERE 
CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
AND CB.Id_Trans = @pId_Trans

/*============================================================================*/

IF(@Compromete_Remitos IN (1, -1))
BEGIN
	SET @Cant_Dig_Cbtes = (dbo.CF_xParam('Cant_Dig_Rem'))
END
ELSE
BEGIN
	SET @Cant_Dig_Cbtes = (dbo.CF_xParam('Cant_Dig_Cbtes'))
END

IF(@Cant_Dig_Cbtes = 0)
BEGIN
	SET @Cant_Dig_Cbtes = 8
END

/*============================================================================*/

IF (@Compromete_Compras IN (1, -1))
BEGIN
   SET @Id_Sucursal	= @Id_Sucursal_Compra
END
ELSE
BEGIN
   SET @Id_Sucursal	= ISNULL((SELECT ISNULL(Sucursal_Nro, 0) FROM Empresas_Suc WHERE Id_Sucursal = @Id_Sucursal),0)
END

/*============================================================================*/
   
SET @Sucursal_Char			= (SELECT RIGHT('00000' + CAST(@Id_Sucursal AS VARCHAR(5)), 5))
SET @Comprobante_Nro		= ISNULL((SELECT ISNULL(Comprobante_Nro, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans),0)

/*=====================================================================================================*/

IF(@Cant_Dig_Cbtes <= 4)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('00000'+CAST(@Comprobante_Nro AS VARCHAR(4)), 4))
END

IF(@Cant_Dig_Cbtes = 5)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('00000'+CAST(@Comprobante_Nro AS VARCHAR(5)), 5))
END

IF(@Cant_Dig_Cbtes = 6)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('000000'+CAST(@Comprobante_Nro AS VARCHAR(6)), 6))
END

IF(@Cant_Dig_Cbtes = 7)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('0000000'+CAST(@Comprobante_Nro AS VARCHAR(7)), 7))
END

IF(@Cant_Dig_Cbtes = 8)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('00000000'+CAST(@Comprobante_Nro AS VARCHAR(8)), 8))
END

IF(@Cant_Dig_Cbtes >= 9)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('000000000'+CAST(@Comprobante_Nro AS VARCHAR(9)), 9))
END

/*=====================================================================================================*/

SET @Descripcion = (@Descrip_Corta + ' ' + @Letra + ' ' + @Sucursal_Char + '-' + @Comprobante_Nro_Char);

RETURN ISNULL(@Descripcion, '')

END
GO


CREATE FUNCTION dbo.CF_Cbte_Nombre_PDF(@pId_Trans INT, @pNroCopia TINYINT) 
RETURNS VARCHAR(255)
AS
BEGIN
DECLARE @Nombre_PDF VARCHAR(255)

--===========================================================================================

IF EXISTS ( SELECT * FROM sysobjects 
			WHERE 
			id = object_id(N'dbo.CF_Cbte_Nombre_PDF_') 
			AND type = 'FN')
BEGIN
	/*Si existe la función personalizada CF_Cbte_Nombre_PDF_ utiliza esa*/
    SET @Nombre_PDF = (dbo.CF_Cbte_Nombre_PDF_(@pId_Trans, @pNroCopia))

    RETURN ISNULL(@Nombre_PDF, '')
END

--===========================================================================================

SET @Nombre_PDF = CONVERT(VARCHAR(10), @pId_Trans) + '-' + LTRIM(RTRIM(dbo.CF_Cbte_Descrip(@pId_Trans)))

IF(@pNroCopia > 0)
BEGIN
	SET @Nombre_PDF = LTRIM(RTRIM(@Nombre_PDF)) + ' (' + CONVERT(VARCHAR(3), @pNroCopia) + ')'
END

SET @Nombre_PDF = LTRIM(RTRIM(@Nombre_PDF)) + '.pdf'

RETURN ISNULL(@Nombre_PDF,'')
END
GO

CREATE FUNCTION CF_Cbte_Numerar (@Id_Tipo_Cbte CHAR(4))
RETURNS INT
AS
BEGIN
DECLARE @Tipo_Numeracion	CHAR(3)
DECLARE @Prox_Nro			INT
DECLARE @Id_Tipo_Cbte_Dest  CHAR(3)
DECLARE @Mensaje			VARCHAR(100)

SELECT @Tipo_Numeracion = UPPER(Tipo_Numeracion)
       ,@Prox_Nro = Prox_Nro
	   ,@Id_Tipo_Cbte_Dest = Id_Tipo_Cbte_Dest 
	   FROM Cbtes_Tipos WHERE Id_Tipo_Cbte =  dbo.CF_Cbte_Traer_Tipo_Dest(@Id_Tipo_Cbte)

IF @Tipo_Numeracion = 'MAN'
	RETURN 0

IF ISNULL(@Prox_Nro,0) = 0
	SET @Prox_Nro = 1


RETURN ISNULL(@Prox_Nro,0)
END
GO


CREATE FUNCTION dbo.CF_Cbte_Rec_Total_Pago (@pId_Trans  INT)
RETURNS DECIMAL(16,2)
AS
BEGIN
DECLARE @Pagado DECIMAL(16,2)

SELECT @Pagado =SUM(V.Importe) 
	FROM Valores_Mov M, Valores V  
	WHERE V.Id_Valor = M.Id_Valor
	AND M.Renglon_Nro = 1
	AND M.id_trans = @pId_Trans



RETURN @Pagado
END
GO


CREATE FUNCTION [dbo].[CF_Cbte_Saldo](@trans INT,@fecha datetime) 
RETURNS DECIMAL(16,2)
AS
BEGIN
DECLARE @Retorno DECIMAL(17,5)
		,@FechaCbte datetime
		,@Compromete_Factura SMALLINT
		,@Compromete_Recibos SMALLINT


SELECT @fechacbte = C.fecha , @Compromete_Factura = T.Compromete_Factura ,@Compromete_Recibos = T.Compromete_Recibos
					FROM Cbtes C, Cbtes_Tipos T 
					WHERE C.Id_Trans = @trans 
						AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte

if @fecha < @fechacbte 
   RETURN 0

set @Retorno = 0

IF @Compromete_Factura = 1
BEGIN
	SET @Retorno = isnull(
							(
								SELECT SUM(ISNULL(A.importe,0)) 
									FROM Cbtes_Aplica A, Cbtes D , Cbtes_tipos T
									WHERE A.Id_Trans = @trans AND A.id_trans_D = D.Id_trans
										AND d.id_estado_cbte in (1,2,4)
										AND D.Id_Tipo_Cbte = t.Id_Tipo_Cbte
										AND (T.Compromete_Recibos in (1,-1) OR T.compromete_factura = -1)
										AND D.Fecha < @Fecha + 1
							)
					   ,0)
END     
ELSE 
BEGIN
	IF @Compromete_Factura = -1
	BEGIN
		SET @Retorno = isnull(
								(
									SELECT SUM(ISNULL(A.importe,0)) 
										FROM Cbtes_Aplica A, Cbtes O , Cbtes_tipos T
										WHERE A.Id_Trans_D = @trans AND A.id_trans = O.Id_trans
											AND o.id_estado_cbte in (1,2,4)
											AND o.Id_Tipo_Cbte = t.Id_Tipo_Cbte
											AND o.fecha < @fecha + 1
											AND T.Compromete_Factura in (1,-1)
								)
						   ,0)

		SET @Retorno = @Retorno + isnull(
								(
									SELECT SUM(ISNULL(A.importe,0)) 
										FROM Cbtes_Aplica A, Cbtes D , Cbtes_tipos T
										where A.Id_Trans = @trans AND A.id_trans_D = D.Id_trans
											and D.id_estado_cbte in (1,2,4)
											and D.Id_Tipo_Cbte = t.Id_Tipo_Cbte
											and T.Compromete_Recibos in (1,-1) 
											AND D.Fecha < @Fecha + 1
								) * -1
						   ,0)
                  
	END
END

IF @Compromete_Recibos IN (1,-1)
BEGIN
	SET @Retorno = isnull(
							(
									SELECT SUM(ISNULL(A.importe,0)) 
										FROM Cbtes_Aplica A, Cbtes O , Cbtes_tipos T
										WHERE A.Id_Trans_D = @trans AND A.id_trans = O.Id_trans
											AND o.id_estado_cbte in (1,2,4)
											AND o.Id_Tipo_Cbte = t.Id_Tipo_Cbte
											AND o.fecha < @fecha + 1
											AND T.Compromete_Factura in (1,-1)
							)
					   ,0)
END


set @Retorno =  (SELECT Imp_Total FROM Cbtes WHERE Id_Trans = @trans )- @Retorno
     
RETURN @Retorno
END
GO

CREATE FUNCTION CF_Cbte_Traer_Tipo_Dest (@Id_Tipo_Cbte CHAR(4))
RETURNS CHAR(4)
AS
BEGIN

DECLARE @Tipo_Numeracion	CHAR(3)
DECLARE @Id_Tipo_Cbte_Dest  CHAR(3)

SELECT @Tipo_Numeracion = UPPER(Id_Tipo_Cbte)
	   ,@Id_Tipo_Cbte_Dest = Id_Tipo_Cbte_Dest 
	   FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte

IF @Tipo_Numeracion = 'DEP' AND ISNULL(@Id_Tipo_Cbte_Dest,'') <> ''
BEGIN
	RETURN @Id_Tipo_Cbte_Dest
END


RETURN @Id_Tipo_Cbte
END
GO


CREATE FUNCTION [dbo].[CF_Cbte_xCampo](@pId_Trans INT, @pId_Campo INT) 
RETURNS VARCHAR(5000)
AS
BEGIN
DECLARE @Retorno VARCHAR(5000)


SELECT @Retorno = CASE UPPER(LTRIM(RTRIM(TipoDato)))
					WHEN 'STRING'	THEN Valor_String 
					WHEN 'INTEGER'	THEN CAST(Valor_Integer AS VARCHAR(50))
					WHEN 'DECIMAL'	THEN CAST(Valor_Decimal AS VARCHAR(100))
					WHEN 'MEMO'		THEN Valor_Memo 
					WHEN 'DATE'		THEN CONVERT(VARCHAR(8),Valor_DT ,112)
					WHEN 'TIME'		THEN CONVERT(VARCHAR(8),Valor_DT ,114)
					WHEN 'LINK'		THEN Valor_Memo 
					END
					FROM Cbtes_XCampos CX, xCampos X
					WHERE CX.Id_Campo = @pId_Campo
					AND CX.Id_Trans = @pId_Trans
					AND X.Id_Campo = CX.Id_Campo

RETURN ISNULL(@Retorno, '')
END
GO

CREATE FUNCTION [dbo].[CF_Cbtes_Descrip_SinTrans](   @pComprobante_Ult_Nro	INT,
													@pDescrip_Corta			CHAR(4),
													@pLetra					VARCHAR(3),
													@pId_Sucursal			SMALLINT,
													@pCant_Dig_Cbtes		INT,
													@pCompromete_Remitos	SMALLINT,
													@pCant_Dig_Rem			INT,
													@pId_Sucursal_Compra	SMALLINT,
													@pCompromete_Compras	SMALLINT)
RETURNS VARCHAR(100)	
AS
BEGIN

DECLARE @Descripcion			VARCHAR(100)
DECLARE @Comprobante_Nro_Char	VARCHAR(9)
DECLARE @Sucursal_Char			VARCHAR(5)

IF(@pCant_Dig_Rem <> 0 AND @pCompromete_Remitos IN (1,-1))
BEGIN
	SET @pCant_Dig_Cbtes = @pCant_Dig_Rem
END

IF(@pCompromete_Compras IN (1, -1))
BEGIN
   SET @pId_Sucursal	= @pId_Sucursal_Compra
END

SET @Sucursal_Char			= (SELECT REPLICATE('0',5-LEN(RTRIM(@pId_Sucursal))) + RTRIM(@pId_Sucursal))

/*=====================================================================================================*/

IF(@pCant_Dig_Cbtes > 4)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT REPLICATE('0',@pCant_Dig_Cbtes-LEN(RTRIM(@pComprobante_Ult_Nro))) + RTRIM(@pComprobante_Ult_Nro))
	
END
ELSE
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT REPLICATE('0',4-LEN(RTRIM(@pComprobante_Ult_Nro))) + RTRIM(@pComprobante_Ult_Nro))
END

/*=====================================================================================================*/

SET @Descripcion = (@pDescrip_Corta + ' ' + @pLetra + ' ' + @Sucursal_Char + '-' + @Comprobante_Nro_Char);

RETURN ISNULL(@Descripcion, '')
END
GO



CREATE FUNCTION [dbo].[CF_Cbtes_Id_Tarjeta](@pId_Trans INT)
RETURNS VARCHAR(10)
AS
BEGIN

DECLARE @Id_Tarjeta				VARCHAR(10)
DECLARE @Id_Cond_Pago_Debito	SMALLINT
DECLARE @Id_Cond_Pago			SMALLINT
DECLARE @Id_Contrato			INT
DECLARE @Id_Tarjeta_Cbte		VARCHAR(10)
DECLARE @Id_Tarjeta_Contrato	VARCHAR(10)
DECLARE @Id_Cliente				INT
DECLARE @Id_Tarjeta_Cliente		VARCHAR(10)


SET @Id_Cond_Pago_Debito	= CONVERT(SMALLINT, dbo.CF_xParam('Cond_Pag_Debito'))
SET @Id_Cond_Pago			= ISNULL( (SELECT Id_Cond_Pago FROM Cbtes WHERE Id_Trans = @pId_Trans) ,0)

IF(@Id_Cond_Pago_Debito = @Id_Cond_Pago AND @Id_Cond_Pago != 0 )
BEGIN
	/*Busca directamente en los datos del Cbte*/
	SET @Id_Tarjeta_Cbte = (SELECT ISNULL(Id_Tarjeta, '') FROM Cbtes WHERE Id_Trans = @pId_Trans)
	
	IF(@Id_Tarjeta_Cbte <> '')
	BEGIN
		SET @Id_Tarjeta = @Id_Tarjeta_Cbte
	END
END
ELSE
BEGIN
	/*Tiene que buscar si tiene una tarjeta cargada en el Contrato*/
	SET @Id_Contrato = (SELECT ISNULL(Id_Contrato, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans)

	SET @Id_Tarjeta_Contrato = (SELECT ISNULL(Id_Tarjeta, '') FROM Contratos WHERE Id_Contrato = @Id_Contrato)

	IF(@Id_Tarjeta_Contrato <> '')
	BEGIN
		/*El Contrato tiene un Tipo de Tarjeta cargado*/
		SET @Id_Tarjeta = @Id_Tarjeta_Contrato
	END
	ELSE
	BEGIN
		/*El Contrato NO tiene un Tipo de Tarjeta cargado, tiene que revisar en la ficha del Socio de la cabecera del Cbte*/
		SET @Id_Cliente			= (SELECT ISNULL(Id_Cliente, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans)
		
		IF(@Id_Cliente NOT IN (0, 1))
		BEGIN
			SET @Id_Tarjeta_Cliente = (SELECT ISNULL(Id_Tarjeta, '') FROM Clientes WHERE Id_Cliente = @Id_Cliente)
	
			IF(@Id_Tarjeta_Cliente <> '')
			BEGIN
				SET @Id_Tarjeta = @Id_Tarjeta_Cliente
			END
		END
	END
END

RETURN ISNULL(@Id_Tarjeta, '')
END
GO



CREATE FUNCTION dbo.CF_Cbtes_Por_Debito(@pId_Trans INT,@Veirf_Dias_Bloqueo_CobMan TINYINT)
RETURNS TINYINT
AS
BEGIN

DECLARE @Id_Tarjeta				VARCHAR(10)
		,@Tar_Nro				VARCHAR(25)
		,@Retorno				TINYINT
		,@Dias_Bloqueo_CobMan	SMALLINT


SET @Retorno = 0
SET @Id_Tarjeta = dbo.CF_Cbtes_Id_Tarjeta(@pId_Trans)

IF @Id_Tarjeta != ''
BEGIN
	SET @Tar_Nro = dbo.CF_Cbtes_Tar_Nro(@pId_Trans)
	IF @Tar_Nro != ''
	BEGIN
	    SET @Retorno = 1
		IF ISNULL(@Veirf_Dias_Bloqueo_CobMan,0) != 0
		BEGIN
		    SELECT @Dias_Bloqueo_CobMan = Dias_Bloqueo_CobMan FROM Valores_Tarjetas_Cred WHERE Id_Tarjeta = @Id_Tarjeta
			IF ISNULL(@Dias_Bloqueo_CobMan,0) != 0
			BEGIN
			   SELECT @Retorno = 0 FROM Cbtes WHERE Id_Trans = @pId_Trans AND Fecha + @Dias_Bloqueo_CobMan < GETDATE()
			END 
		END
	END
END

RETURN @Retorno
END
GO



CREATE FUNCTION [dbo].[CF_Cbtes_Tar_Nro](@pId_Trans INT)
RETURNS VARCHAR(50)
AS
BEGIN

DECLARE @Tar_Nro				VARCHAR(50)
DECLARE @Id_Cond_Pago_Debito	SMALLINT
DECLARE @Id_Cond_Pago			SMALLINT
DECLARE @Id_Contrato			INT
DECLARE @Tar_Nro_Cbte			VARCHAR(50)
DECLARE @Tar_Nro_Contrato		VARCHAR(50)
