CREATE FUNCTION dbo.CF_Cliente_Cob_Tipo_Mes(@Id_Cliente INT,@Id_Tipo_Val  CHAR(3),@Flag_Grupo TINYINT,@Fecha DATETIME)
RETURNS DECIMAL(16,2)
AS
BEGIN

IF @Id_Cliente IN(0,1) RETURN 0

DECLARE @Retorno DECIMAL(16,2),
		@titular INT


IF ISNULL(@Flag_Grupo,0) <> 0
BEGIN
   SELECT @titular = ISNULL(Id_Cliente_Ref,0) FROM Clientes WHERE Id_Cliente  = @Id_Cliente
   IF @titular =  0  SET @titular = @Id_Cliente

	SELECT @Retorno = SUM(V.Importe) FROM Valores V, Valores_Mov VM ,Cbtes C, Cbtes_Tipos T 
	WHERE  C.id_Tipo_Cbte = T.Id_Tipo_Cbte
	AND T.Compromete_Recibos = 1
	AND C.Id_Estado_Cbte IN (1,2,4)
	AND ( C.id_Cliente IN (SELECT Id_Cliente FROM Clientes WHERE Id_Cliente_Ref = @titular)
	      OR  C.id_Cliente = @titular )
	AND C.Fecha >= dbo.CF_FOMONTH(@Fecha)
	AND C.Fecha <  dbo.CF_EOMONTH(@Fecha + 1)
	AND V.Id_Valor = VM.Id_Valor
	AND V.Id_Tipo_Val = @Id_Tipo_Val
	AND VM.Id_Trans = C.id_Trans
	AND VM.Renglon_Nro = (SELECT MAX(VM2.Renglon_Nro) FROM Valores_Mov VM2
							WHERE VM2.Id_Valor = VM.Id_Valor
								AND VM2.Id_Trans = C.Id_Trans)
END
ELSE
BEGIN
	SET @titular = @Id_Cliente


	SELECT @Retorno = SUM(V.Importe) FROM Valores V, Valores_Mov VM ,Cbtes C, Cbtes_Tipos T 
	WHERE  C.id_Tipo_Cbte = T.Id_Tipo_Cbte
	AND T.Compromete_Recibos = 1
	AND C.Id_Estado_Cbte IN (1,2,4)
	AND C.id_Cliente = @titular
	AND C.Fecha >= dbo.CF_FOMONTH(@Fecha)
	AND C.Fecha <  dbo.CF_EOMONTH(@Fecha + 1)
	AND V.Id_Valor = VM.Id_Valor
	AND V.Id_Tipo_Val = @Id_Tipo_Val
	AND VM.Id_Trans = C.id_Trans
	AND VM.Renglon_Nro = (SELECT MAX(VM2.Renglon_Nro) FROM Valores_Mov VM2
							WHERE VM2.Id_Valor = VM.Id_Valor
								AND VM2.Id_Trans = C.Id_Trans)

END


RETURN ISNULL(@Retorno,0)


END
GO


CREATE FUNCTION [dbo].[CF_Cliente_Grupo_Descrip](@Id_Cliente INT)
RETURNS VARCHAR(100)
AS
BEGIN
/*

0: Muestra condicion del iva  
1: Muestra Titular + Individual + Cant. Total referenciados  y contactos 
2: Muestra Titular + Individual + Cant. Total referenciados

*/
IF @Id_Cliente IN(0,1) RETURN ''


DECLARE @Cli_Adm_Grupo INT
DECLARE @Id_Tit INT
DECLARE @Iva VARCHAR(100)
DECLARE @Integrantes INT
DECLARE @Adherentes INT
DECLARE @Cant INT

SET @Cli_Adm_Grupo = ISNULL(CONVERT(INT,dbo.CF_xParam('Cli_Adm_Grupo')),0)

SELECT @Id_Tit = Id_Cliente_Ref , @Iva = I.Descripcion 
			FROM Clientes C 
				LEFT JOIN Iva I ON I.Id_Iva = C.Id_Iva 
			WHERE Id_Cliente = @Id_Cliente

IF @Cli_Adm_Grupo = 0 RETURN ISNULL(@Iva,'')

SET @Id_Tit = ISNULL(@Id_Tit,0)

IF @Id_Tit = 0 SET @Id_Tit = @Id_Cliente

SELECT @Integrantes = COUNT(*) FROM Clientes WHERE Id_Cliente_Ref = @Id_Tit 
									AND Activo = 1
									AND Fecha_Alta <= GETDATE()
									AND (Fecha_Baja >= GETDATE() OR Fecha_Baja IS NULL)
SET @Integrantes = ISNULL(@Integrantes,0)

IF @Cli_Adm_Grupo = 1
BEGIN
   SELECT @Adherentes = COUNT(*) FROM Clientes_Adherentes WHERE Id_Cliente = @Id_Tit
									AND Activo = 1
									AND Fecha_Alta <= GETDATE()
									AND (Fecha_Baja >= GETDATE() OR Fecha_Baja IS NULL)		

   SET @Adherentes = ISNULL(@Adherentes,0)

END
IF @Id_Tit = @Id_Cliente 
BEGIN    
	IF @Integrantes + @Adherentes = 0   
		RETURN 'INDIVIDUAL'
	ELSE	
		RETURN 'TITULAR (' + CONVERT(VARCHAR(10),@Integrantes + @Adherentes + 1 ) + ')'
END
ELSE		 
   		RETURN 'INTEGRANTE (' + CONVERT(VARCHAR(10),@Integrantes + @Adherentes + 1 ) + ')'

RETURN ''

END
GO


CREATE FUNCTION [dbo].[CF_Cliente_xCampo](@pId_Cliente INT, @pId_Campo INT) 
RETURNS VARCHAR(5000)
AS
BEGIN
DECLARE @Retorno VARCHAR(5000)


SELECT @Retorno = CASE UPPER(LTRIM(RTRIM(TipoDato)))
					WHEN 'STRING'	THEN Valor_String 
					WHEN 'INTEGER'	THEN CAST(Valor_Integer AS VARCHAR(50))
					WHEN 'DECIMAL'	THEN CAST(Valor_Decimal AS VARCHAR(100))
					WHEN 'MEMO'		THEN Valor_Memo 
					WHEN 'DATE'		THEN CONVERT(VARCHAR(8),Valor_DT ,112)
					WHEN 'TIME'		THEN CONVERT(VARCHAR(8),Valor_DT ,114)
					WHEN 'LINK'		THEN Valor_Memo 
					END
					FROM Clientes_XCampos C, xCampos X
					WHERE C.Id_Campo = @pId_Campo
					AND C.Id_Cliente = @pId_Cliente
					AND X.Id_Campo = C.Id_Campo

RETURN ISNULL(@Retorno,'')

END
GO


CREATE FUNCTION dbo.CF_Clientes_Links_Token(
											@pFormato			VARCHAR(1),		/*A: Alfanumerico. N: Numerico*/
											@pCant_Carac_Dig	SMALLINT		/*Cantidad de Caracteres/Digitos al retornar en el Token*/
											)
RETURNS VARCHAR(50)
AS
BEGIN

DECLARE @Token				VARCHAR(50)
DECLARE	@Letras				CHAR(62)
DECLARE	@Numeros			CHAR(10)
DECLARE @Posicion			SMALLINT
DECLARE @Valor_Random		FLOAT
DECLARE @Valor_Random_INT	INT
DECLARE @Cada_Caracter		CHAR(1)
DECLARE @Flag_Existe_Token	TINYINT

-------------------------------------------------------------------------------------------------------------------------------------
/*
VERSIONES:
02/08/2022 Creaci¾n de funci¾n.
*/
-------------------------------------------------------------------------------------------------------------------------------------

IF(@pFormato NOT IN ('A', 'N'))
BEGIN
	SET @pFormato = 'A'
END

IF(@pCant_Carac_Dig < 1)
BEGIN
	SET @pCant_Carac_Dig = 1
END

-------------------------------------------------------------------------------------------------------------------------------------

SET @Token		= ''
SET @Letras		= '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'
SET @Numeros	= '0123456789'

-------------------------------------------------------------------------------------------------------------------------------------

IF(@pFormato = 'A')
BEGIN
	SET @Posicion = 1

	WHILE (@Posicion < @pCant_Carac_Dig + 1)
	BEGIN
		SELECT @Valor_Random = rndResult FROM rndView
	
		SET @Cada_Caracter = SUBSTRING(@Letras, CAST(ROUND(@Valor_Random * 62,0) AS INT), 1)

		SET @Token = LTRIM(RTRIM(@Token)) + @Cada_Caracter
	
		SET @Posicion = @Posicion + 1
	END
END

-------------------------------------------------------------------------------------------------------------------------------------

IF(@pFormato = 'N')
BEGIN
	SET @Posicion = 1

	WHILE (@Posicion < @pCant_Carac_Dig + 1)
	BEGIN
		SELECT @Valor_Random = rndResult FROM rndView

		SET @Valor_Random_INT = CAST(ROUND(@Valor_Random * 10,0) AS INT)
		
		IF(@Valor_Random_INT = 0)
		BEGIN
			SET @Valor_Random_INT = 1
		END
	
		SET @Cada_Caracter = SUBSTRING(@Numeros, @Valor_Random_INT, 1)

		SET @Token = LTRIM(RTRIM(@Token)) + @Cada_Caracter
	
		SET @Posicion = @Posicion + 1
	END

	IF(@pCant_Carac_Dig = 10)	--Por Lectores intelektron que lo maximo que leen es: 4.294.967.295 (2^32)
	BEGIN
		SET @Token = STUFF(@Token, 1, 1, '3')
	END
END

-------------------------------------------------------------------------------------------------------------------------------------

SET @Flag_Existe_Token = ISNULL((SELECT 
								TOP 1 1
								FROM Clientes_Links
								WHERE
								Token = @Token)
								, 0)

IF(@Flag_Existe_Token = 1)
BEGIN
	SET @Token = (dbo.CF_Clientes_Links_Token(@pFormato, @pCant_Carac_Dig))
END
-------------------------------------------------------------------------------------------------------------------------------------

RETURN @Token
END

--SELECT dbo.CF_Clientes_Links_Token('A', 32)
--SELECT dbo.CF_Clientes_Links_Token('N', 10)
GO

CREATE FUNCTION [dbo].[CF_Clientes_Tipos_PFam_Validar] (@pId_Tipo_Cli INT, @pId_Familia  INT)
RETURNS SMALLINT
AS
BEGIN
    DECLARE @Existe_Categoria   INT
    DECLARE @Cantidad           INT
    DECLARE @FlagPermitirFam    SMALLINT
    DECLARE @Resultado          SMALLINT

    SELECT 
        @Existe_Categoria = COUNT(1),
        @FlagPermitirFam  = ISNULL(MAX(Flag_Permitir_Fam), 0)
    FROM Clientes_Tipos
    WHERE Id_Tipo_Cli = @pId_Tipo_Cli

    IF (@Existe_Categoria = 0)
        RETURN 0

    SELECT 
        @Cantidad = ISNULL(COUNT(1), 0)
    FROM Clientes_Tipos_PFam
    WHERE Id_Tipo_Cli = @pId_Tipo_Cli

    IF (@Cantidad = 0)
        RETURN 1

    -- Hay filas en Clientes_Tipos_PFam, aplicamos la lista blanca/negra

    IF (@FlagPermitirFam = 1)
    BEGIN
        -- LISTA BLANCA:
        -- Solo las familias que esten configuradas son validas
        IF EXISTS (
            SELECT 1 
            FROM Clientes_Tipos_PFam
            WHERE Id_Tipo_Cli = @pId_Tipo_Cli
              AND Id_Familia  = @pId_Familia
        )
            SET @Resultado = 1
        ELSE
            SET @Resultado = 0
    END
    ELSE
    BEGIN
        -- LISTA NEGRA (Flag_Permitir_Fam = 0 o NULL)
        -- Las familias configuradas se EXCLUYEN
        IF EXISTS (
            SELECT 1 
            FROM Clientes_Tipos_PFam
            WHERE Id_Tipo_Cli = @pId_Tipo_Cli
              AND Id_Familia  = @pId_Familia
        )
            SET @Resultado = 0
        ELSE
            SET @Resultado = 1
    END

    RETURN @Resultado
END
GO


CREATE FUNCTION [dbo].[CF_Clientes_UCP_xCbteEsp](@pId_Cliente INT)
RETURNS DATETIME
AS
BEGIN
DECLARE @UCP_Especial DATETIME
DECLARE @FmaCuto INT
DECLARE @CbteEsp  CHAR(4)


SET @FmaCuto =  CAST ( (DBO.CF_xParam('Fam_CuotasSoc')) AS INT)
SET @CbteEsp = (DBO.CF_xParam('TipoCbteModifUCP'))

/*Se agrega un tipo de Cbte capaz de modificar la última cuota paga en caso de encontrase en estado Pendiente*/

SET @UCP_Especial = (SELECT ISNULL(MIN(CI.Fecha_QA), '19000101')
								FROM Cbtes_Items CI, Cbtes CB, Productos PR, Cbtes_Tipos CT
								WHERE
								CB.Id_Trans = CI.Id_Trans
								AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
								AND CI.Id_Producto = PR.Id_Producto
								AND CT.Compromete_Factura IN (1)
								AND CB.Id_Estado_Cbte IN (1/*Pendiente*/)
								AND PR.Id_Familia = @FmaCuto
								AND CI.Id_Cliente = @pId_Cliente
								AND CB.Id_Tipo_Cbte = @CbteEsp)
								 
RETURN ISNULL(@UCP_Especial, '19000101')
END
GO


CREATE FUNCTION [dbo].[CF_Contrato_Cli_Edad](@pFecha_Nac DATETIME, @pFlag_Valida_Edad_Escolar SMALLINT, @Edad_Min SMALLINT, @Edad_Max SMALLINT)
RETURNS SMALLINT 
AS

BEGIN
DECLARE @Edad					SMALLINT
DECLARE @Respuesta				SMALLINT
DECLARE @Mes					SMALLINT
DECLARE @Dia					SMALLINT

SET @Edad = (SELECT (CAST(DATEDIFF(dd, @pFecha_Nac, (GETDATE() + 1)) / 365.25 AS SMALLINT)))
SET @Mes = 	(SELECT MONTH(@pFecha_Nac))

IF (@pFlag_Valida_Edad_Escolar = 1)
BEGIN
	IF (@Mes > 6)  
	BEGIN
		SET @Respuesta = @Edad
		RETURN @Respuesta
	END

	IF (@Edad = @Edad_Max AND @Mes < 7)  
	BEGIN
		SET @Respuesta = @Edad + 1
		RETURN @Respuesta
	END

	IF (@Edad + 1 = @Edad_Min AND @Mes < 7)  
	BEGIN
		SET @Respuesta = @Edad + 1
		RETURN @Respuesta
	END

	SET @Respuesta = @Edad
END
ELSE
	SET @Respuesta = @Edad


RETURN ISNULL(@Respuesta, 0)
END

