											,@Flag_SoloAsientos
											)
		FETCH NEXT FROM Cur_CF_Cta_Cont_Saldo_CC INTO @Id_Centro_Costo
	END
	CLOSE Cur_CF_Cta_Cont_Saldo_CC
	DEALLOCATE Cur_CF_Cta_Cont_Saldo_CC
END
/*find e recurisivida centro de costo*/










RETURN @Importe
END
GO

/*--------------------------------------------------------------------------------------------*/

CREATE FUNCTION [dbo].[CF_CtrlPresup_MesPesup] (	@mes INT
													,@Anio INT
													,@Id_Centro_Costo char(10)
													,@Alias INT
													,@Flag_Recur TINYINT)
RETURNS DECIMAL(16,2)
AS
BEGIN

IF @Anio = 0	
	RETURN 0;

IF @Alias = 0	
	RETURN 0;



DECLARE @IMPORTE DECIMAL(16,2)
		,@Mes_D  SMALLINT
		,@Mes_H  SMALLINT

IF @mes = 0
BEGIN
	SET	@Mes_D  = 1
	SET @Mes_H  = 12
END
ELSE
BEGIN
	SET	@Mes_D  = @mes
	SET @Mes_H  = @mes
END


SET @IMPORTE = 0

IF ISNULL(@Id_Centro_Costo,'') = ''
BEGIN
	SET @IMPORTE  = (ISNULL((SELECT SUM(ISNULL(O.Debe,0)) - SUM(ISNULL(O.Haber,0)) as importe
								  FROM Cbtes_Ctas_Contables O, Cbtes C, Cbtes_Tipos T
								  WHERE O.Id_Trans = C.Id_Trans 
								  AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
								  AND T.Compromete_CtrlPresup IN (1,-1)
								  AND DATEPART(mm,C.Fecha) BETWEEN @Mes_D AND @Mes_H  
								  AND DATEPART(YYYY,C.Fecha) = @Anio
								  and c.Id_Estado_Cbte  in (2,4)
								  AND O.Alias = @Alias),0)) 
END
ELSE
BEGIN
	SET @IMPORTE  = (ISNULL((SELECT SUM(ISNULL(O.Debe,0)) - SUM(ISNULL(O.Haber,0)) as importe
								  FROM Cbtes_Ctas_Contables O, Cbtes C, Cbtes_Tipos T
								  WHERE O.Id_Trans = C.Id_Trans 
								  AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
								  AND T.Compromete_CtrlPresup IN (1,-1)
								  AND DATEPART(mm,C.Fecha) BETWEEN @Mes_D AND @Mes_H  
								  AND DATEPART(YYYY,C.Fecha) = @Anio
								  AND ISNULL(C.Id_Centro_Costo,'') = ISNULL(@Id_Centro_Costo,'')
								  and c.Id_Estado_Cbte  in (2,4)
								  AND O.Alias = @Alias),0)) 

	/*Recursividad*/

	IF ISNULL(@Flag_Recur,0) <> 0
	BEGIN
		DECLARE Cur_CF_CtrlPresup_MesPesup CURSOR FOR SELECT Id_Centro_Costo FROM Centro_Costos WHERE Id_Centro_Costo_Padre = @Id_Centro_Costo
		OPEN Cur_CF_CtrlPresup_MesPesup
		FETCH NEXT FROM Cur_CF_CtrlPresup_MesPesup INTO @Id_Centro_Costo
		WHILE @@FETCH_STATUS=0
		BEGIN
			SET @IMPORTE = @IMPORTE + dbo.CF_CtrlPresup_MesPesup(@mes, @Anio, @Id_Centro_Costo ,@Alias ,@Flag_Recur)
			FETCH NEXT FROM Cur_CF_CtrlPresup_MesPesup INTO @Id_Centro_Costo
		END
		CLOSE Cur_CF_CtrlPresup_MesPesup
		DEALLOCATE Cur_CF_CtrlPresup_MesPesup
	END
	/*fin recursivad*/
END

RETURN @IMPORTE

END
GO


CREATE FUNCTION dbo.CF_DB_Version()
RETURNS DECIMAL(5,2)
AS
BEGIN

DECLARE @Ver				DECIMAL(5,2)
		,@ProductVersion	VARCHAR(128)

SET @ProductVersion = CONVERT(VARCHAR(18),SERVERPROPERTY('ProductVersion'))

IF @ProductVersion LIKE('8.%')
   SET @Ver = 8

IF @ProductVersion LIKE('9.%')
   SET @Ver = 9

IF @ProductVersion LIKE('10.%')
   SET @Ver = 10

IF @ProductVersion LIKE('10.25%')
   SET @Ver = 10.25

IF @ProductVersion LIKE('10.50%')
   SET @Ver = 10.50

IF @ProductVersion LIKE('11.%')
   SET @Ver = 11

IF @ProductVersion LIKE('12.%')
   SET @Ver = 12

IF @ProductVersion LIKE('13.%')
   SET @Ver = 13

IF @ProductVersion LIKE('14.%')
   SET @Ver = 14

IF @ProductVersion LIKE('15.%')
   SET @Ver = 15

IF @ProductVersion LIKE('16.%')
   SET @Ver = 16

IF @ProductVersion LIKE('17.%')
   SET @Ver = 17

IF @ProductVersion LIKE('18.%')
   SET @Ver = 18

IF @ProductVersion LIKE('19.%')
   SET @Ver = 19

IF @ProductVersion LIKE('20.%')
   SET @Ver = 20


RETURN ISNULL(@Ver, 0)
END
GO


CREATE FUNCTION [dbo].[CF_Descrip_Cbte](@pId_Trans INT)
RETURNS VARCHAR(100)	
AS

BEGIN

DECLARE @Descripcion			VARCHAR(100)
DECLARE @Id_Tipo_Cbte			CHAR(4)
DECLARE @Id_Sucursal			SMALLINT
DECLARE @Id_Sucursal_Compra 	SMALLINT
DECLARE @Compromete_Compras		SMALLINT
DECLARE @Compromete_Remitos		SMALLINT
DECLARE @Letra					VARCHAR(3)
DECLARE @Descrip_Corta			CHAR(4)
DECLARE @Cant_Dig_Cbtes			INT
DECLARE @Sucursal_Char			VARCHAR(5)
DECLARE @Comprobante_Nro		INT
DECLARE @Comprobante_Nro_Char	VARCHAR(9)



SELECT @Id_Tipo_Cbte		= ISNULL(CB.Id_Tipo_Cbte, '')
     , @Descrip_Corta		= ISNULL(RTRIM(LTRIM(CT.Descrip_Corta)), '')
	 , @Letra				= ISNULL(RTRIM(LTRIM(CT.Letra)), '')
	 , @Id_Sucursal			= ISNULL(CT.Id_Sucursal, 0)
	 , @Id_Sucursal_Compra	= ISNULL(CB.Id_Sucursal, 0)
	 , @Compromete_Compras	= ISNULL(CT.Compromete_Compras, 0)
	 , @Compromete_Remitos	= ISNULL(CT.Compromete_Remitos, 0)
FROM Cbtes CB, Cbtes_Tipos CT
WHERE 
CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
AND CB.Id_Trans = @pId_Trans

/*============================================================================*/

IF(@Compromete_Remitos IN (1, -1))
BEGIN
	SET @Cant_Dig_Cbtes = (dbo.CF_xParam('Cant_Dig_Rem'))
END
ELSE
BEGIN
	SET @Cant_Dig_Cbtes = (dbo.CF_xParam('Cant_Dig_Cbtes'))
END

IF(@Cant_Dig_Cbtes = 0)
BEGIN
	SET @Cant_Dig_Cbtes = 8
END

/*============================================================================*/

IF (@Compromete_Compras IN (1, -1))
BEGIN
   SET @Id_Sucursal	= @Id_Sucursal_Compra
END
ELSE
BEGIN
   SET @Id_Sucursal	= ISNULL((SELECT ISNULL(Sucursal_Nro, 0) FROM Empresas_Suc WHERE Id_Sucursal = @Id_Sucursal),0)
END

/*============================================================================*/
   
SET @Sucursal_Char			= (SELECT RIGHT('00000' + CAST(@Id_Sucursal AS VARCHAR(5)), 5))
SET @Comprobante_Nro		= ISNULL((SELECT ISNULL(Comprobante_Nro, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans),0)

/*=====================================================================================================*/

IF(@Cant_Dig_Cbtes <= 4)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('00000'+CAST(@Comprobante_Nro AS VARCHAR(4)), 4))
END

IF(@Cant_Dig_Cbtes = 5)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('00000'+CAST(@Comprobante_Nro AS VARCHAR(5)), 5))
END

IF(@Cant_Dig_Cbtes = 6)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('000000'+CAST(@Comprobante_Nro AS VARCHAR(6)), 6))
END

IF(@Cant_Dig_Cbtes = 7)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('0000000'+CAST(@Comprobante_Nro AS VARCHAR(7)), 7))
END

IF(@Cant_Dig_Cbtes = 8)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('00000000'+CAST(@Comprobante_Nro AS VARCHAR(8)), 8))
END

IF(@Cant_Dig_Cbtes >= 9)
BEGIN
	SET @Comprobante_Nro_Char	= (SELECT RIGHT('000000000'+CAST(@Comprobante_Nro AS VARCHAR(9)), 9))
END

/*=====================================================================================================*/

SET @Descripcion = (@Descrip_Corta + ' ' + @Letra + ' ' + @Sucursal_Char + '-' + @Comprobante_Nro_Char);

RETURN ISNULL(@Descripcion, '')

END
GO


CREATE FUNCTION dbo.CF_Descrip_Cbte_Producto(@pId_Trans INT) 
RETURNS VARCHAR(8000)
AS
BEGIN

DECLARE @Descripcion	VARCHAR(8000)

DECLARE @Descrip_Prod	VARCHAR(100)

SET @Descripcion='' 
DECLARE curNombre CURSOR FOR
SELECT Descripcion_Detallada FROM Productos P, Cbtes_Items CI
WHERE
CI.Id_Producto=P.Id_Producto
AND CI.Id_Trans=@pId_Trans

OPEN curNombre
FETCH NEXT FROM curNombre INTO @Descrip_Prod
WHILE @@FETCH_STATUS = 0
BEGIN

IF(@Descripcion='')
BEGIN
	set @Descripcion = @Descrip_Prod 
END 
ELSE
BEGIN
	set @Descripcion = @Descripcion + ', ' +@Descrip_Prod
END

FETCH NEXT FROM curNombre INTO @Descrip_Prod
END
CLOSE curNombre
DEALLOCATE curNombre


RETURN ISNULL(@Descripcion, '')

END
GO


CREATE FUNCTION dbo.CF_Doc_Nro_UY_Validar(@pDoc_Nro BIGINT)
RETURNS BIGINT
AS
BEGIN
DECLARE @Doc_Nro_Validado		BIGINT
DECLARE @Doc_Nro_Validado_VC	VARCHAR(20)
DECLARE @Doc_Nro_VC				VARCHAR(20)
DECLARE @Suma					INT
DECLARE @Media					INT
DECLARE @Digito_Verificador		TINYINT

SET @Doc_Nro_VC = CONVERT(VARCHAR(20), @pDoc_Nro)

--Si el Doc_Nro no tiene al menos 7 u 8 digitos ya no se puede calcular
IF(LEN(@Doc_Nro_VC) NOT IN (7,8))
BEGIN	
	SET @Doc_Nro_Validado = 0
	RETURN @Doc_Nro_Validado
END

SET @Suma = (CONVERT(TINYINT, SUBSTRING(@Doc_Nro_VC, 1, 1)) * 2) +
			(CONVERT(TINYINT, SUBSTRING(@Doc_Nro_VC, 2, 1)) * 9) +
			(CONVERT(TINYINT, SUBSTRING(@Doc_Nro_VC, 3, 1)) * 8) +
			(CONVERT(TINYINT, SUBSTRING(@Doc_Nro_VC, 4, 1)) * 7) +
			(CONVERT(TINYINT, SUBSTRING(@Doc_Nro_VC, 5, 1)) * 6) + 
			(CONVERT(TINYINT, SUBSTRING(@Doc_Nro_VC, 6, 1)) * 3) +
			(CONVERT(TINYINT, SUBSTRING(@Doc_Nro_VC, 7, 1)) * 4)

SET @Media = (@Suma % 10)

SET @Digito_Verificador =  ((10 - @Media) % 10)

SET @Doc_Nro_Validado_VC = SUBSTRING(@Doc_Nro_VC, 1, 7) + CONVERT(VARCHAR(1), @Digito_Verificador)

SET @Doc_Nro_Validado = CONVERT(BIGINT, @Doc_Nro_Validado_VC)

RETURN ISNULL(@Doc_Nro_Validado, 0)
END

--SELECT dbo.CF_Doc_Nro_UY_Validar(19359017)
GO



CREATE FUNCTION [dbo].[CF_EOMONTH](@Fecha DATETIME) 
RETURNS DATETIME
AS
