CREATE FUNCTION dbo.CF_FileName_Sanitize (@Texto      NVARCHAR(4000) )
RETURNS NVARCHAR(4000)
AS
BEGIN
    DECLARE @i int = 1,
            @len int,
            @c nchar(1),
            @res NVARCHAR(4000) = N'',
            @prevSpace bit = 0,
			@MaxLen INT = 240,
			@ColapsarEspacios BIT = 1;

    IF @Texto IS NULL RETURN N'_';

    -- trim inicial
    SET @Texto = LTRIM(RTRIM(@Texto));
    SET @len = LEN(@Texto);

    WHILE @i <= @len AND LEN(@res) < @MaxLen
    BEGIN
        SET @c = SUBSTRING(@Texto, @i, 1);

        -- descarta controles (incluye TAB/CR/LF) y caracteres inv├ílidos Windows
        IF NOT (UNICODE(@c) < 32
           OR @c IN (N'\',N'/',N':',N'*',N'?',N'"',N'<',N'>',N'|'))
        BEGIN
            -- opcional: colapsar espacios m├║ltiples
            IF @ColapsarEspacios = 1 AND @c = N' '
            BEGIN
                IF @prevSpace = 0
                BEGIN
                    SET @res = @res + @c;
                    SET @prevSpace = 1;
                END
            END
            ELSE
            BEGIN
                SET @res = @res + @c;
                SET @prevSpace = 0;
            END
        END

        SET @i += 1;
    END

    -- trim final
    SET @res = LTRIM(RTRIM(@res));

    -- Windows: no permite terminar en espacio o punto
    WHILE LEN(@res) > 0 AND (RIGHT(@res,1) = N' ' OR RIGHT(@res,1) = N'.')
        SET @res = LEFT(@res, LEN(@res)-1);

    -- si qued├│ vac├¡o, devolver "_"
    IF LEN(@res) = 0
        RETURN N'_';

    -- Evitar nombres reservados (insensible a may├║sc/min├║sc)
    DECLARE @base NVARCHAR(4000) = UPPER(@res);

    -- si tiene extensi├│n, validar solo el "nombre" antes del primer punto
    DECLARE @firstDot int = CHARINDEX(N'.', @base);
    DECLARE @nameOnly NVARCHAR(4000) =
        CASE WHEN @firstDot > 0 THEN LEFT(@base, @firstDot-1) ELSE @base END;

    IF @nameOnly IN (N'CON',N'PRN',N'AUX',N'NUL',
                     N'COM1',N'COM2',N'COM3',N'COM4',N'COM5',N'COM6',N'COM7',N'COM8',N'COM9',
                     N'LPT1',N'LPT2',N'LPT3',N'LPT4',N'LPT5',N'LPT6',N'LPT7',N'LPT8',N'LPT9')
    BEGIN
        SET @res = @res + N'_';
    END

    -- por si al agregar "_" qued├│ con punto/espacio final
    WHILE LEN(@res) > 0 AND (RIGHT(@res,1) = N' ' OR RIGHT(@res,1) = N'.')
        SET @res = LEFT(@res, LEN(@res)-1);

    IF LEN(@res) = 0
        RETURN N'_';

    RETURN @res;
END
GO

CREATE FUNCTION CF_Finan_TemTea (@TEM FLOAT)
RETURNS FLOAT
AS
BEGIN

DECLARE @Mes FLOAT
DECLARE @TEA FLOAT
SET @TEM = @TEM / 100

SET @Mes = 365/30
SET @TEA = ((POWER( (1 + @TEM) , @Mes) ) - 1) * 100

RETURN @TEA
END
