SELECT dbo.CF_Horas_Lab_Dif('20220629 18:00','20220630 18:15',8,17)

*/
GO


CREATE FUNCTION [dbo].[CF_IdentifDNI](@pDato VARCHAR(100))
RETURNS INT
AS
BEGIN

DECLARE @Id_Cliente					INT
DECLARE @Flag_Tipo_DNI				TINYINT
DECLARE @Flag_Formato_Valido_Doc	INT=0
DECLARE @Doc_Escaneado				VARCHAR(20)
DECLARE @Doc_Nro					BIGINT
DECLARE @Long_Dato					INT
DECLARE @Flag_Es_Numerico			TINYINT

SET @Long_Dato			= LEN(@pDato)
SET @Flag_Es_Numerico	= dbo.CF_IsNumeric(@pDato)

IF(ISNULL(@pDato, '') = '')
BEGIN
	SET @Id_Cliente = 0
	RETURN @Id_Cliente
END

IF(@Long_Dato > 50)
BEGIN
	IF(ISNULL(dbo.SF_CortarCadena(@pDato, '"', 4), '') IN ('F', 'M') 
			OR ISNULL(dbo.SF_CortarCadena(@pDato, '"', 9), '') 	IN ('F', 'M') 
			OR ISNULL(dbo.SF_CortarCadena(@pDato, '@', 4), '') 	IN ('F', 'M') 
			OR ISNULL(dbo.SF_CortarCadena(@pDato, '@', 9), '') IN ('F', 'M'))
	BEGIN
		IF(ISNULL(dbo.SF_CortarCadena(@pDato, '"', 4), '') IN ('F', 'M') 
			OR ISNULL(dbo.SF_CortarCadena(@pDato, '@', 4), '') IN ('F', 'M'))
		BEGIN
			SET @Flag_Tipo_DNI = 1 /*Formato Nuevo*/
		END
		ELSE
		BEGIN
			SET @Flag_Tipo_DNI = 2 /*Formato Viejo*/
		END
	END
	ELSE
	BEGIN
		/*Formato NO valido*/
		SET @Flag_Tipo_DNI = 0
	END

	/*Formato Nuevo*/
	IF(@Flag_Tipo_DNI = 1) 
	BEGIN
		SET @Doc_Escaneado				= (SELECT ISNULL(dbo.SF_CortarCadena(@pDato, '"', 5),''))
		
		IF(@Doc_Escaneado = '')
		BEGIN
			SET @Doc_Escaneado			= (SELECT ISNULL(dbo.SF_CortarCadena(@pDato, '@', 5),''))
		END
		
		SET @Doc_Escaneado				= REPLACE(@Doc_Escaneado, 'M', '')
		SET @Doc_Escaneado				= REPLACE(@Doc_Escaneado, 'F', '')
		SET @Flag_Formato_Valido_Doc	= (SELECT ISNUMERIC(@Doc_Escaneado))
	END

	/*Formato Viejo*/
	IF(@Flag_Tipo_DNI = 2) 
	BEGIN
		SET @Doc_Escaneado				= (SELECT dbo.SF_CortarCadena(@pDato, '"', 2))
		SET @Doc_Escaneado				= REPLACE(@Doc_Escaneado, 'M', '')
		SET @Doc_Escaneado				= REPLACE(@Doc_Escaneado, 'F', '')
		SET @Flag_Formato_Valido_Doc	= (SELECT ISNUMERIC(@Doc_Escaneado))
	END


	IF(@Flag_Formato_Valido_Doc = 1)
	BEGIN
		SET @Doc_Nro					= @Doc_Escaneado
		SET @Id_Cliente					= (SELECT TOP 1 ISNULL(Id_Cliente, 0) 
												FROM Clientes C
													JOIN Clientes_Tipos T ON C.Id_Tipo_Cli = T.Id_Tipo_Cli
												WHERE Doc_Nro = @Doc_Nro 
												ORDER BY 
														 C.Activo DESC,
													  CASE T.Flag_Tipo
														WHEN 'P' THEN 1
														WHEN 'S' THEN 2
														WHEN ''  THEN 3
														WHEN 'N' THEN 4
														ELSE 5
													  END,
														 C.Ult_Cuota_Paga DESC
											)
	END
	ELSE
	BEGIN
		SET @Id_Cliente = 0
	END



	/*Formato NO valido*/
	IF(@Flag_Tipo_DNI = 0) 
	BEGIN
		SET @Id_Cliente = 0
	END
	
END


RETURN @Id_Cliente

END
GO


CREATE FUNCTION [dbo].[CF_IsNumeric](@pDato VARCHAR(MAX))
RETURNS TINYINT
AS 
BEGIN
DECLARE @Flag_Es_Numerico	TINYINT
DECLARE @longitud			INT
DECLARE @posicion			INT

SET @Flag_Es_Numerico = 1

SET @longitud = LEN(@pDato)

SET @posicion = 0

WHILE @posicion < @longitud
BEGIN
	SET @posicion = @posicion + 1
	
	IF(ISNUMERIC(SUBSTRING(@pDato, @posicion, 1)) = 0)
	BEGIN
		SET @Flag_Es_Numerico = 0
	END
END
  
RETURN @Flag_Es_Numerico
END
GO



CREATE FUNCTION [dbo].[CF_Itau_UY_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT) 
RETURNS CHAR(200)
AS
BEGIN

/*Variables Archivo*/
DECLARE @Retorno					CHAR(200)
DECLARE @aCuenta_A_Debitar			VARCHAR(22)	/*Formato: Num├®rico (22) 		Nro. de Tarjeta del socio*/
DECLARE @aImporte					VARCHAR(11)	/*Formato: Num├®rico (9,2).		Monto correspondiente que se recibe por par├ímetro*/
DECLARE @aRef_Debito				VARCHAR(10)	/*Formato: Num├®rico (10).		Id_Cliente_externo del socio*/
DECLARE @aRef_Credito 				VARCHAR(1)		/*Formato: Num├®rico (1).		Se deber├í completar siempre en blanco.*/
DECLARE @aConsumidor_Final 			VARCHAR(1)		/*Formato: Alfanum├®rico (1).	Se deber├í completar siempre con la letra "S".*/
DECLARE @aMonto_Gravado 			VARCHAR(1)		/*Formato: Num├®rico (1).		Se deber├í completar siempre en Cero.*/
DECLARE @aImporte_Ret_Iva 			VARCHAR(1)		/*Formato: Num├®rico (1).		Se deber├í completar siempre en Cero.*/
DECLARE @aNumero_Factura			VARCHAR(1)		/*Formato: Alfanum├®rico (1).	Se deber├í completar siempre en blanco.*/
/*FIN Variables Archivo*/

/*Variable Locales*/
DECLARE @Tar_Nro				VARCHAR(22)
DECLARE @Id_Cliente				INT
DECLARE @Id_Cliente_Externo		INT
/*FIN Variable Locales*/

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

/*Seteo Variables Locales*/

SELECT	
@Tar_Nro		= ISNULL(DBO.SF_COTIZA(Nro), '') 
FROM Val_Tarjetas_Lotes_Items 
WHERE
Id_Tar_Lote = @pId_Tar_Lote
AND Id_Trans = @pId_Trans


SELECT	
@Id_Cliente				= ISNULL(Id_Cliente, 0)
FROM Cbtes 
WHERE
Id_Trans = @pId_Trans


SELECT 
@Id_Cliente_Externo		= ISNULL(Id_Cliente_Externo, Id_Cliente)
FROM Clientes
WHERE
Id_Cliente = @Id_Cliente

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

SET @aCuenta_A_Debitar			=	@Tar_Nro

SET @aImporte					=	@pImporte

SET @aRef_Debito				=	@Id_Cliente_Externo

SET @aRef_Credito				=	''

SET @aConsumidor_Final			=	'S'

SET @aMonto_Gravado				=	'0'

SET @aImporte_Ret_Iva			=	'0'

SET @aNumero_Factura			=	''

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

SET @Retorno =	@aCuenta_A_Debitar	 + ';' +
				@aImporte 		   	 + ';' +
				@aRef_Debito 		 + ';' +
				@aRef_Credito  		 + ';' +
				@aConsumidor_Final 	 + ';' +
				@aMonto_Gravado		 + ';' +
				@aImporte_Ret_Iva 	 + ';' +
				@aNumero_Factura

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

RETURN ISNULL(@Retorno, '                                                                                                                                                                                                        ')
END
GO


CREATE FUNCTION [dbo].[CF_Item_Paid](@pId_Cliente INT, @pId_Producto VARCHAR(14), @pFecha DATETIME)
RETURNS TINYINT
AS
BEGIN
DECLARE @Flag_Item_Pagado TINYINT

DECLARE @Flag_Mes				TINYINT
DECLARE @Flag_Periodo			TINYINT
DECLARE @Flag_Existe_Producto	TINYINT
DECLARE @Flag_Existe_Cliente	TINYINT
DECLARE @Flag_PermiteProdPorPed	INT

---------------------------------------------------------------------------------------------------------------

SET @Flag_Existe_Producto = ISNULL((SELECT 1 FROM Productos WHERE Id_Producto = @pId_Producto), 0)

IF(@Flag_Existe_Producto = 0)
BEGIN
	SET @Flag_Item_Pagado = 0
	RETURN @Flag_Item_Pagado
END

---------------------------------------------------------------------------------------------------------------

SET @Flag_Existe_Cliente = ISNULL((SELECT 1 FROM Clientes WHERE Id_Cliente = @pId_Cliente), 0)

IF(@Flag_Existe_Cliente = 0)
BEGIN
	SET @Flag_Item_Pagado = 0
	RETURN @Flag_Item_Pagado
END

---------------------------------------------------------------------------------------------------------------

SELECT  
@Flag_Mes		= ISNULL(Flag_Mes, 0),
@Flag_Periodo	= ISNULL(Flag_Periodo, 0)
FROM Productos
WHERE
Id_Producto = @pId_Producto

---------------------------------------------------------------------------------------------------------------

IF (@Flag_Mes = 0 AND @Flag_Periodo = 0) --No controla ni mes ni periodo, con que alguna vez lo haya pagado esta ok
BEGIN	
	SET @Flag_Item_Pagado = (SELECT MAX(1)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND ISNULL(CB.Id_Tipo_Cbte, '') = CT.Id_Tipo_Cbte
							AND ISNULL(CT.Compromete_Factura, 0) IN (1)
							AND ISNULL(CI.Id_Cliente, 0) = @pId_Cliente
							AND LTRIM(RTRIM(ISNULL(CI.Id_Producto, ''))) = LTRIM(RTRIM(@pId_Producto))
							AND ((ISNULL(CB.Id_Estado_Cbte, 0) = 2) OR (ISNULL(CB.Id_Estado_Cbte, 0) IN (1, 4) AND ISNULL(CI.Imp_Final, 0) = 0))
							)
	RETURN ISNULL(@Flag_Item_Pagado, 0)
END

---------------------------------------------------------------------------------------------------------------

IF (@Flag_Mes = 1) --Controla mes tiene prioridad por sobre Periodo
BEGIN	
	SET @Flag_Item_Pagado = (SELECT MAX(1)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND ISNULL(CB.Id_Tipo_Cbte, '') = CT.Id_Tipo_Cbte
							AND ISNULL(CT.Compromete_Factura, 0) IN (1)
							AND ISNULL(CI.Id_Cliente, 0) = @pId_Cliente
							AND LTRIM(RTRIM(ISNULL(CI.Id_Producto, ''))) = LTRIM(RTRIM(@pId_Producto))
							AND ((ISNULL(CB.Id_Estado_Cbte, 0) = 2) OR (ISNULL(CB.Id_Estado_Cbte, 0) IN (1, 4) AND ISNULL(CI.Imp_Final, 0) = 0))
							AND dbo.CF_FOMONTH(CONVERT(DATE, ISNULL(CI.Fecha_QA, '19000101'))) = dbo.CF_FOMONTH(CONVERT(DATE, @pFecha))
							)

	RETURN ISNULL(@Flag_Item_Pagado, 0)
END

---------------------------------------------------------------------------------------------------------------

IF (@Flag_Periodo = 1)
BEGIN	
	SET @Flag_Item_Pagado = (SELECT MAX(1)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND ISNULL(CB.Id_Tipo_Cbte, '') = CT.Id_Tipo_Cbte
							AND ISNULL(CT.Compromete_Factura, 0) IN (1)
							AND ISNULL(CI.Id_Cliente, 0) = @pId_Cliente
							AND LTRIM(RTRIM(ISNULL(CI.Id_Producto, ''))) = LTRIM(RTRIM(@pId_Producto))
							AND ((ISNULL(CB.Id_Estado_Cbte, 0) = 2) OR (ISNULL(CB.Id_Estado_Cbte, 0) IN (1, 4) AND ISNULL(CI.Imp_Final, 0) = 0))
							AND CONVERT(DATE, ISNULL(CI.Fecha_QA, '19000101')) <= CONVERT(DATE, @pFecha)
							AND CONVERT(DATE, ISNULL(CI.Fecha_Venc, '19000101')) >= CONVERT(DATE, @pFecha)
							)

	RETURN ISNULL(@Flag_Item_Pagado, 0)
END

---------------------------------------------------------------------------------------------------------------

RETURN ISNULL(@Flag_Item_Pagado, 0)
END
GO


CREATE FUNCTION [dbo].[CF_JSON_VALUE](@pJson VARCHAR(8000), @pVar VARCHAR(4000))
RETURNS VARCHAR(4000)
AS
BEGIN

DECLARE @Retorno VARCHAR(4000)
DECLARE @PosVar  SMALLINT
DECLARE @PosDatoInicio  SMALLINT
DECLARE @PosDatoFin  SMALLINT


SET @PosVar =  CHARINDEX('"' + UPPER(@pVar) + '"',UPPER(@pJson),1) 
IF @PosVar <> 0
BEGIN
     IF SUBSTRING(@pJson,@PosVar + LEN(@pVar) + 3,1) = '['
	 BEGIN
	    SET @PosDatoInicio = @PosVar + LEN(@pVar) + 4
	    SET @PosDatoFin = CHARINDEX(']',UPPER(@pJson),@PosDatoInicio) - 1
		SET @Retorno    = SUBSTRING(@pJson,@PosDatoInicio,@PosDatoFin - @PosDatoInicio + 1)
	 END

     IF SUBSTRING(@pJson,@PosVar + LEN(@pVar) + 3,1) = '{'
	 BEGIN
	    SET @PosDatoInicio = @PosVar + LEN(@pVar) + 4
	    SET @PosDatoFin = CHARINDEX('}',UPPER(@pJson),@PosDatoInicio) - 1
		SET @Retorno    = SUBSTRING(@pJson,@PosDatoInicio,@PosDatoFin - @PosDatoInicio + 1)
	 END


     IF SUBSTRING(@pJson,@PosVar + LEN(@pVar) + 3,1) = '"'
	 BEGIN
	    SET @PosDatoInicio = @PosVar + LEN(@pVar) + 4
	    SET @PosDatoFin = CHARINDEX('"',UPPER(@pJson),@PosDatoInicio) - 1
		SET @Retorno    = SUBSTRING(@pJson,@PosDatoInicio,@PosDatoFin - @PosDatoInicio + 1)
	 END
	 
	 IF SUBSTRING(@pJson,@PosVar + LEN(@pVar) + 3,1) NOT IN ('"','{','[')
	 BEGIN
	    SET @PosDatoInicio = @PosVar + LEN(@pVar) + 3
	    SET @PosDatoFin = CHARINDEX(',',UPPER(@pJson),@PosDatoInicio) - 1
		IF  @PosDatoFin = -1 
			SET @PosDatoFin = CHARINDEX('}',UPPER(@pJson),@PosDatoInicio) - 1
	    SET @Retorno    = SUBSTRING(@pJson,@PosDatoInicio,@PosDatoFin - @PosDatoInicio + 1)
	 END
END

RETURN @Retorno

END
GO



CREATE  FUNCTION dbo.CF_Json_ParsearVariable(@pVariable VARCHAR(4000), @pValor VARCHAR(4000), @pTipoDato VARCHAR(20))
RETURNS VARCHAR(8000)
AS
BEGIN
DECLARE @Json		VARCHAR(8000)
DECLARE @Fecha		DATETIME
DECLARE @FechaVC	VARCHAR(30)

/*--------------------------------------------22/9/2021       si le pasamos un nulo devuele el valor que corresponde ------------------------------------------------*/
IF (ISNULL(@pValor,'0') = '0' OR LTRIM(RTRIM(@pValor)) = '') AND RTRIM(LTRIM(UPPER(@pTipoDato))) IN ('BIGINT','NUMERIC','BIT','SMALLINT','DECIMAL','SMALLMONEY','INT','TINYINT','MONEY','FLOAT','REAL')
BEGIN
	SET @Json = '"' + LTRIM(RTRIM(@pVariable)) + '"' + ':' + '"0"'
	RETURN @Json
END


IF ISNULL(@pValor,'19000101') = '19000101' AND RTRIM(LTRIM(UPPER(@pTipoDato))) IN ('DATE','DATETIMEOFFSET','DATETIME2','SMALLDATETIME','DATETIME','TIME')
BEGIN
	SET @Json = '"' + LTRIM(RTRIM(@pVariable)) + '"' + ':' + '"1900-01-01T00:00:00"'
	RETURN @Json
END


IF ISNULL(@pValor,'') = ''
BEGIN
	SET @Json = '"' + LTRIM(RTRIM(@pVariable)) + '"' + ':' + '""'
	RETURN @Json
END
/*--------------------------------------------------fin de validacion de nulos -------------------------------------------------*/



IF(@pTipoDato = 'DATETIME')
BEGIN
	SET @Fecha = CONVERT(DATETIME, @pValor)
	SET @FechaVC = REPLACE(CONVERT(VARCHAR, @Fecha, 111), '/', '-') + 'T' + CONVERT(VARCHAR, @Fecha, 8)
	
	SET @Json = '"' + LTRIM(RTRIM(@pVariable)) + '"' + ':' + '"' + @FechaVC + '"'
	
	RETURN @Json
END


IF(@pTipoDato = 'DATE')
BEGIN
	SET @Fecha = CONVERT(DATETIME, @pValor)
	SET @FechaVC = REPLACE(CONVERT(VARCHAR, @Fecha, 111), '/', '-') + 'T00:00:00'
	
	SET @Json = '"' + LTRIM(RTRIM(@pVariable)) + '"' + ':' + '"' + @FechaVC + '"'
	
	RETURN @Json
END

ELSE
BEGIN
	SET @Json = '"' + LTRIM(RTRIM(@pVariable)) + '"' + ':' + '"' + @pValor + '"'
	
	RETURN @Json
END

RETURN ISNULL(@Json, '"":""')
END

/*

SELECT dbo.CF_Json_ParsearVariable('Saludo', 'Hola', 'VARCHAR')
SELECT dbo.CF_Json_ParsearVariable('Numero', '0', 'INT')
SELECT dbo.CF_Json_ParsearVariable('Fecha', '20210701', 'DATETIME')
SELECT dbo.CF_Json_ParsearVariable('Saludo', null, 'VARCHAR')
SELECT dbo.CF_Json_ParsearVariable('Numero', null, 'INT')
SELECT dbo.CF_Json_ParsearVariable('Fecha', null, 'DATETIME')


*/
GO


CREATE FUNCTION dbo.CF_Localidades_Disponibles(@pId_Sector SMALLINT, @pFecha DATETIME, @pId_Lista_Precio_Evento SMALLINT)
RETURNS INT
AS
BEGIN
DECLARE @Cantidad_Localidades_Disponibles	INT
DECLARE @Localidades_Totales				INT
DECLARE @Localidades_Reservadas				INT
DECLARE @Localidades_Ocupadas				INT

-------------------------------------------------------------------------------------------------------------------------------------

SET @Localidades_Totales = (dbo.CF_Localidades_Totales(@pId_Sector))

SET @Localidades_Reservadas = (dbo.CF_Localidades_Reservadas(@pId_Sector,@pFecha,@pId_Lista_Precio_Evento))

SET @Localidades_Ocupadas = (dbo.CF_Localidades_Ocupadas(@pId_Sector,@pFecha,@pId_Lista_Precio_Evento))

-------------------------------------------------------------------------------------------------------------------------------------

SET @Cantidad_Localidades_Disponibles = @Localidades_Totales - @Localidades_Reservadas - @Localidades_Ocupadas

-------------------------------------------------------------------------------------------------------------------------------------

RETURN ISNULL(@Cantidad_Localidades_Disponibles, 0)
END
GO


CREATE FUNCTION [dbo].[CF_Localidades_Ocupadas]
(
    @pId_Sector SMALLINT,
    @pFecha DATETIME,
    @pId_Lista_Precio_Evento SMALLINT
)
RETURNS INT
AS
BEGIN

    DECLARE @Cantidad_Localidades_Ocupadas INT
    DECLARE @Id_Evento_Grupo INT
    DECLARE @Hoy DATETIME

    SET @Cantidad_Localidades_Ocupadas = 0
    SET @Id_Evento_Grupo = 0
    SET @Hoy = DATEADD(DAY, DATEDIFF(DAY, 0, GETDATE()), 0) -- hoy 00:00:00

    IF (@pId_Lista_Precio_Evento > 0)
    BEGIN
        -- Obtengo grupo desde la lista
        SELECT @Id_Evento_Grupo = ISNULL(Id_Evento_Grupo, 0)
        FROM Prod_Listas_Precios
        WHERE Id_Lista_Precio = @pId_Lista_Precio_Evento

        IF (@Id_Evento_Grupo = 0)
        BEGIN
            -- Lista puntual
            SELECT
                @Cantidad_Localidades_Ocupadas = COUNT(*)
            FROM Cbtes_Items A WITH (INDEX(IX_CBTI_Flag_QA))
            JOIN Cbtes B WITH (INDEX(IX_CBT_Lista_Estado))
                ON B.Id_Trans = A.Id_Trans
            JOIN Cbtes_Tipos C
                ON C.Id_Tipo_Cbte = B.Id_Tipo_Cbte
            JOIN Productos P
                ON P.Id_Producto = A.Id_Producto
            WHERE
                A.Flag_QA IN ('A','B')
                AND B.Id_Estado_Cbte IN (1,2,4)
                AND (C.Compromete_Factura = 1 OR C.Compromete_Remitos = 1 OR C.Compromete_Pedido = 1)
                AND B.Id_Lista = @pId_Lista_Precio_Evento
                AND P.Tipo = 'L'
                AND P.Vendible = 1
                AND P.Id_Sector = @pId_Sector
        END
        ELSE
        BEGIN
            -- Grupo: grupo base + grupos (Eventos_Grupos.Inc_Abonos_Grup_Eve)
            ;WITH Grupos AS
            (
                -- Siempre incluyo el grupo base
                SELECT @Id_Evento_Grupo AS Id_Evento_Grupo

                UNION

                -- + los grupos del string "15,14,..." si existen
                SELECT CONVERT(INT, LTRIM(RTRIM(n.i.value('.', 'varchar(20)')))) AS Id_Evento_Grupo
                FROM Eventos_Grupos eg
                CROSS APPLY (
                    SELECT CAST(
                        '<i>' + REPLACE(ISNULL(eg.Inc_Abonos_Grup_Eve,''), ',', '</i><i>') + '</i>'
                        AS XML
                    ) AS x
                ) t
                CROSS APPLY t.x.nodes('/i') n(i)
                WHERE eg.Id_Evento_Grupo = @Id_Evento_Grupo
                  AND LTRIM(RTRIM(n.i.value('.', 'varchar(20)'))) <> ''
                  AND LTRIM(RTRIM(n.i.value('.', 'varchar(20)'))) NOT LIKE '%[^0-9]%' -- solo numeros
            ),
            Listas AS
            (
                -- Abonos
                SELECT plp.Id_Lista_Precio
                FROM Prod_Listas_Precios plp
                JOIN Grupos g ON g.Id_Evento_Grupo = plp.Id_Evento_Grupo
                WHERE plp.Flag_Localidades = 1
				AND plp.Evento_Hasta >= @Hoy

                UNION ALL

                -- Partidos futuros
                SELECT plp.Id_Lista_Precio
                FROM Prod_Listas_Precios plp
                JOIN Grupos g ON g.Id_Evento_Grupo = plp.Id_Evento_Grupo
                WHERE plp.Flag_Localidades = 2
                  AND plp.Fecha_Evento >= @Hoy
            )
            SELECT
                @Cantidad_Localidades_Ocupadas = COUNT(*)
            FROM Cbtes B WITH (INDEX(IX_CBT_Lista_Estado))
            JOIN Listas L
                ON L.Id_Lista_Precio = B.Id_Lista
            JOIN Cbtes_Items A WITH (INDEX(IX_CBTI_Flag_QA))
                ON A.Id_Trans = B.Id_Trans
               AND A.Flag_QA IN ('A','B')
            JOIN Productos P
                ON P.Id_Producto = A.Id_Producto
            JOIN Cbtes_Tipos C
                ON C.Id_Tipo_Cbte = B.Id_Tipo_Cbte
            WHERE
                B.Id_Estado_Cbte IN (1,2,4)
                AND (C.Compromete_Factura = 1 OR C.Compromete_Remitos = 1 OR C.Compromete_Pedido = 1)
                AND P.Tipo = 'L'
                AND P.Id_Sector = @pId_Sector
        END
    END
    ELSE
    BEGIN
        -- Caso sin lista: por rango de fechas
        DECLARE @Desde DATETIME
        DECLARE @Hasta DATETIME

        SET @Desde = DATEADD(DAY, DATEDIFF(DAY, 0, @pFecha), 0)
        SET @Hasta = DATEADD(DAY, 1, @Desde)

        SELECT
            @Cantidad_Localidades_Ocupadas = COUNT(*)
        FROM Cbtes_Items A WITH (INDEX(IX_CBTI_Flag_QA))
        JOIN Cbtes B WITH (INDEX(IX_CBT_Lista_Estado))
            ON B.Id_Trans = A.Id_Trans
        JOIN Cbtes_Tipos C
            ON C.Id_Tipo_Cbte = B.Id_Tipo_Cbte
        JOIN Productos P
            ON P.Id_Producto = A.Id_Producto
        WHERE
            A.Flag_QA IN ('A','B')
            AND B.Id_Estado_Cbte IN (1,2,4)
            AND (C.Compromete_Factura = 1 OR C.Compromete_Remitos = 1 OR C.Compromete_Pedido = 1)
            AND A.Fecha_QA < @Hasta
            AND A.Fecha_Venc >= @Desde
            AND P.Tipo = 'L'
            AND P.Id_Sector = @pId_Sector
    END

    RETURN ISNULL(@Cantidad_Localidades_Ocupadas, 0)
END
GO


CREATE FUNCTION [dbo].[CF_Localidades_Reservadas](@pId_Sector SMALLINT, @pFecha DATETIME, @pId_Lista_Precio_Evento SMALLINT)
RETURNS INT
AS
BEGIN
DECLARE @Cantidad_Localidades_Reservadas					INT
DECLARE @Hoy												DATE
DECLARE @Param_Loca_Cbte_Loca_Ent							VARCHAR(4)
DECLARE @Fecha_Reserva_Limite								DATE
DECLARE @Cant_Dias_Limite									INT
DECLARE @Flag_Ubic_Fija										TINYINT
DECLARE @Flag_Localidades									TINYINT
-------------------------------------------------------------------------------------------------------------------------------------

SET @Cantidad_Localidades_Reservadas = 0

-------------------------------------------------------------------------------------------------------------------------------------

SET @Hoy						= CONVERT(DATE, GETDATE())

SET @Param_Loca_Cbte_Loca_Ent	= SUBSTRING(LTRIM(RTRIM(dbo.CF_xParam('Loca_Cbte_Loca_Ent'))), 1, 4)

SELECT	
@Fecha_Reserva_Limite	= ISNULL(Evento_Fecha_Reserva_Limite, '19000101'),
@Cant_Dias_Limite		= ISNULL(Evento_Cant_Dias_Limite, 0),
@Flag_Localidades		= ISNULL(Flag_Localidades, 0)
FROM Prod_Listas_Precios 
WHERE 
Id_Lista_Precio = @pId_Lista_Precio_Evento

SELECT
@Flag_Ubic_Fija = Flag_Ubic_Fija
FROM Empresas_Sedes_Sectores
Where Id_Sector = @pId_Sector

--Si es un partido y no es localidad fija no debe buscar reserva 
IF (@Flag_Localidades = 2 AND @Flag_Ubic_Fija = 0)
BEGIN
	RETURN 0
END

IF(@Fecha_Reserva_Limite = '19000101')
BEGIN
	--Si Evento_Fecha_Reserva_Limite no esta grabado en el Evento (Prod_Listas_Precios) lo saca del parametro
	SET @Fecha_Reserva_Limite = CONVERT(DATE, dbo.CF_xParam('Loca_Fecha_Lim'))
END

IF(@Cant_Dias_Limite = 0)
BEGIN
	--Si Evento_Cant_Dias_Limite no esta grabado en el Evento (Prod_Listas_Precios) lo saca del parametro
	SET @Cant_Dias_Limite = CONVERT(INT, dbo.CF_xParam('Loca_Fecha_Lim_Dias'))
END

IF (@Fecha_Reserva_Limite < CONVERT(DATE, GETDATE()))
BEGIN
	SET @Cantidad_Localidades_Reservadas = 0
END
ELSE
BEGIN
	SET @Cantidad_Localidades_Reservadas = ISNULL(	(SELECT COUNT(*)
													FROM Cbtes_Items A, Cbtes B, Cbtes_Tipos C, Productos P
													WHERE
													A.Id_Trans = B.Id_Trans
													AND B.Id_Tipo_Cbte = C.Id_Tipo_Cbte
													AND A.Id_Producto = P.Id_Producto 
													AND A.Flag_QA = 'A' 
													AND B.Id_Estado_Cbte <> 3 
													AND B.Id_Estado_Cbte <> 0
													AND (C.Compromete_Factura = 1 OR C.Compromete_Remitos = 1 OR C.Compromete_Pedido = 1)
													AND A.Fecha_Venc < @Hoy
													AND DATEADD(DAY, @Cant_Dias_Limite, A.Fecha_Venc) >= @Hoy
													AND P.Tipo = 'L'
													AND B.Id_Tipo_Cbte <> @Param_Loca_Cbte_Loca_Ent
													AND P.Id_Sector = @pId_Sector
													AND NOT EXISTS(	SELECT 1 
																	FROM Cbtes_Items A2, Cbtes B2 ,Cbtes_Tipos C2
																	WHERE 
																	A2.Id_Trans = B2.Id_Trans
																	AND B2.Id_Tipo_Cbte = C2.Id_Tipo_Cbte
																	AND A2.Id_Producto = A.Id_Producto
																	AND A2.Flag_QA = 'A' 
																	AND B2.Id_Estado_Cbte <> 3 
																	AND B2.Id_Estado_Cbte <> 0
																	AND (C2.Compromete_Factura = 1 OR C2.Compromete_Remitos = 1 OR C2.Compromete_Pedido = 1)
																	AND A2.Fecha_QA < DATEADD(DAY, 1, CONVERT(DATE, @pFecha))
																	AND A2.Fecha_Venc >= CONVERT(DATE, @pFecha))
													)
													, 0)
END

-------------------------------------------------------------------------------------------------------------------------------------

RETURN ISNULL(@Cantidad_Localidades_Reservadas, 0)
END
GO



CREATE FUNCTION [dbo].[CF_Localidades_Totales](@pId_Sector SMALLINT)
RETURNS INT
AS
BEGIN
DECLARE @Cantidad_Localidades_Totales		INT
DECLARE @Cantidad_Productos_Del_Sector		INT
DECLARE @Flag_Ubic_Fija						TINYINT

-------------------------------------------------------------------------------------------------------------------------------------

SELECT 
TOP 1
@Flag_Ubic_Fija = ISNULL(Flag_Ubic_Fija, 0)
FROM Empresas_Sedes_Sectores
WHERE 
Id_Sector = @pId_Sector

IF(@Flag_Ubic_Fija = 1)
BEGIN
	--Son todos los productos (Asientos) que pertenecen al Id_Sector
	SET @Cantidad_Localidades_Totales = ISNULL((SELECT COUNT(*) FROM Productos WHERE Tipo = 'L' AND Activo = 1 AND Id_Sector = @pId_Sector), 0)
END
ELSE
BEGIN
	--Es la minima de cantidad de los productos del sector (Hablado con Gabriel 19/04/2022) (Ej. Popular sin numerar)
	--Es la cantidad de localidades de Empresa Sectores (Hablado con Gabriel 21/03/2023) (Ej. Platea Su Baja)
	SET @Cantidad_Localidades_Totales = ISNULL((SELECT ISNULL(Cant_Localidades, 0) FROM Empresas_Sedes_Sectores WHERE  Id_Sector = @pId_Sector), 0)
END

-------------------------------------------------------------------------------------------------------------------------------------

/* Antes del 19/04/2022
SET @Cantidad_Productos_Del_Sector = ISNULL((SELECT COUNT(*) FROM Productos WHERE Tipo = 'L' AND Activo = 1 AND Id_Sector = @pId_Sector), 0)

IF (@Cantidad_Productos_Del_Sector = 1)
BEGIN
	--Es un solo producto (Ej. Popular sin numerar) que tiene la cantidad maxima de ocupacion
	SET @Cantidad_Localidades_Totales = ISNULL((SELECT ISNULL(Estiba_Max, 0) FROM Productos WHERE Tipo = 'L' AND Activo = 1 AND Id_Sector = @pId_Sector), 0)
END
ELSE
BEGIN
	--Son todos los productos (Asientos) que pertenecen al Id_Sector
	SET @Cantidad_Localidades_Totales = ISNULL((SELECT COUNT(*) FROM Productos WHERE Tipo = 'L' AND Activo = 1 AND Id_Sector = @pId_Sector), 0)
END
*/

-------------------------------------------------------------------------------------------------------------------------------------

RETURN ISNULL(@Cantidad_Localidades_Totales, 0)
END
GO


CREATE FUNCTION [dbo].[CF_Login_Sistema](@pUsuario VARCHAR(41), @pPassword VARCHAR(20))
RETURNS INT
AS
BEGIN

DECLARE @Flag_Login_Exitoso			INT
DECLARE @Password_Encriptada		VARCHAR(50)
DECLARE @Flag_Usuario_Tiene_Espacio BIGINT

SET @pUsuario = UPPER(LTRIM(RTRIM(@pUsuario)))
SET @pPassword = UPPER(@pPassword)
SET @Flag_Usuario_Tiene_Espacio = CHARINDEX(' ' , @pUsuario)

SET @Password_Encriptada = (dbo.SF_EncriptPassword(@pPassword))

IF(@Flag_Usuario_Tiene_Espacio = 0)
BEGIN
	SET @Flag_Login_Exitoso =  ISNULL(	(SELECT ISNULL(No, 0)
	  									FROM Seg_User
	  									WHERE 
	  									UPPER(LTRIM(RTRIM(LastName))) = @pUsuario
	  									AND UPPER(LTRIM(RTRIM(Password)))	= @Password_Encriptada)
	  								, 0)
END
ELSE
BEGIN
	SET @Flag_Login_Exitoso =  ISNULL(	(SELECT ISNULL(No, 0)
	  									FROM Seg_User
	  									WHERE 
	  									UPPER(LTRIM(RTRIM(FirstName))) + ' ' + UPPER(LTRIM(RTRIM(LastName))) = @pUsuario
	  									AND UPPER(LTRIM(RTRIM(Password)))	= @Password_Encriptada)
	  								, 0)
END

RETURN ISNULL(@Flag_Login_Exitoso, 0)
END
GO


CREATE FUNCTION [dbo].[CF_MasterCard_UY_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT, @pPeriodo DATETIME) 
RETURNS CHAR(200)
AS
BEGIN

/*Variables Archivo*/
DECLARE @Retorno					CHAR(200)
DECLARE @aNro_Comercio				CHAR(8)		/*Formato: Numérico (8).		Desde: 001. Hasta: 008. Nota: Informar el número de comercio.*/
DECLARE @aTipo_Registro				CHAR(1)		/*Formato: Numérico (1).		Desde: 009. Hasta: 009. Nota: 2 = registro detalle de débito automático, 3 = registro detalle de cupón crédito*/
DECLARE @aNro_Tarjeta				CHAR(16)	/*Formato: Numérico (16).		Desde: 010. Hasta: 025. Nota: Se indicará el número de tarjeta del socio.*/
DECLARE @aNro_Refencia				CHAR(12)	/*Formato: Numérico (12).		Desde: 026. Hasta: 037. Nota: Corresponde al número mediante el cual el socio es identificado por el Establecimiento; puede ser el número de abonado, socio, afiliado, etc. Deberá indicarse alineado a la derecha, con ceros a izquierda. */
DECLARE @aCuotas					CHAR(3)		/*Formato: Numérico (3).		Desde: 038. Hasta: 040. Nota: Adhesiones nuevas: indica la cuota a partir de la cual comienza el débito automático de las mismas. El dato a informar deberá ser igual a 1 (uno) o mayor (sólo cuando se desee cobrar más de una cuota en el mismo período) y menor que la cantidad informada en cuotas plan. Adhesiones existentes: indica la cantidad de cuotas que se cancelan. En caso de informarse ceros se cobrará el importe indicado en la novedad pero no se cancelarán cuotas. */
DECLARE @aCuotas_Plan				CHAR(3)		/*Formato: Numérico (3).		Desde: 041. Hasta: 043. Nota: Es la cantidad de cuotas del plan al que pertenece la adhesión. Si se trata de un plan ilimitado de cuotas deberá informarse “999”. */
DECLARE @aFrecuencia_DB				CHAR(2)		/*Formato: Numérico (2).		Desde: 044. Hasta: 045. Nota: Indica la periodicidad de debitación de las cuotas. Valor: 01. */
DECLARE @aImporte					CHAR(11)	/*Formato: Numérico (9,2).		Desde: 046. Hasta: 056. Nota: Monto correspondiente al valor del débito automático cobrado o del cupón crédito devuelto por el Establecimiento al usuario, se encuentra formado por una parte entera y otra decimal. El monto no incluye punto ni coma decimal, como tampoco signo; simplemente deberá informarse alineado a la derecha, con ceros a la izquierda.*/
DECLARE @aPeriodo					CHAR(5)		/*Formato: Alfanumérico (5).	Desde: 057. Hasta: 061. Nota: En este campo deberá indicarse el período al que corresponde la cuota del débito.  Si la novedad corresponde a un cupón crédito, este campo deberá informar “CRED “. */
DECLARE @aFiller1					CHAR(1)		/*Formato: Alfanumérico (1).	Desde: 062. Hasta: 062. Nota: Se deberá completar con espacios en blanco.*/
DECLARE @aFecha_Vto_Pago			CHAR(6)		/*Formato: Alfanumérico (6).	Desde: 063. Hasta: 068. Nota: Indicar fecha de vencimiento de la obligación de pago del débito automático que se está informando. Formato DDMMAA */
DECLARE @aDatos_Auxiliares			CHAR(40)	/*Formato: Alfanumérico (40).	Desde: 069. Hasta: 108. Nota: Se informarán los datos auxiliares enviados por el comercio para la novedad.*/
DECLARE @aMarcaAplicaDevolucionIVA	CHAR(1)		/*Formato: Numérico (1).		Desde: 109. Hasta: 109. Nota: Indicador de devolución de IVA, Ley 19.210. Valores: 0 – no aplica, 1 – aplica */
DECLARE @aImporte_Gravado			CHAR(11)	/*Formato: Numérico (9,2).		Desde: 110. Hasta: 120. Nota: Importe del débito sin IVA.*/
DECLARE @aNumero_Factura			CHAR(20)	/*Formato: Alfanumérico (20).	Desde: 121. Hasta: 140. Nota: Identificación de la factura.*/
DECLARE @aFiller2					CHAR(60)	/*Formato: Alfanumérico (60).	Desde: 141. Hasta: 200. Nota: Se deberá completar con espacios en blanco.*/

/*FIN Variables Archivo*/

/*Variable Locales*/
DECLARE @Id_Tarjeta				VARCHAR(10)
DECLARE @Fecha_Presentacion		DATETIME
DECLARE @Comercio_Nro			VARCHAR(50)
DECLARE @Tar_Nro				VARCHAR(22)
DECLARE @Id_Contrato			INT
DECLARE @Tar_Fecha_Vence		DATETIME
DECLARE @Fecha_Cbte				DATETIME
DECLARE @Mes_Periodo			SMALLINT
DECLARE @Mes_Periodo_VC			VARCHAR(3)
DECLARE @Id_Cliente				INT
DECLARE @Id_Cliente_Externo		INT
DECLARE @Comprobante_Nro		INT
/*FIN Variable Locales*/

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

/*Seteo Variables Locales*/
SELECT	
@Id_Tarjeta				= ISNULL(Id_Tarjeta, ''),
@Fecha_Presentacion		= ISNULL(Fecha_Presentacion, '19000101')
FROM Val_Tarjetas_Lotes
WHERE
Id_Tar_Lote = @pId_Tar_Lote

SELECT
@Comercio_Nro			= ISNULL(Comercio_Nro, '')
FROM Valores_Tarjetas_Cred
WHERE
ISNULL(Id_Tarjeta, '') = @Id_Tarjeta

SELECT	
@Tar_Nro				= LTRIM(RTRIM(ISNULL(DBO.SF_COTIZA(Nro), '')))
FROM Val_Tarjetas_Lotes_Items 
WHERE
Id_Tar_Lote = @pId_Tar_Lote
AND Id_Trans = @pId_Trans


SELECT	
@Id_Cliente				= ISNULL(Id_Cliente, 0),
@Fecha_Cbte				= ISNULL(Fecha, '19000101'),
@Id_Contrato			= ISNULL(Id_Contrato, 0),
@Comprobante_Nro		= ISNULL(Comprobante_Nro, 0)
FROM Cbtes 
WHERE
Id_Trans = @pId_Trans

SELECT 
@Id_Cliente_Externo		= ISNULL(Id_Cliente_Externo, Id_Cliente)
FROM Clientes
WHERE
Id_Cliente = @Id_Cliente

SELECT
@Tar_Fecha_Vence		= ISNULL(Tar_Fecha_Vence, DATEADD(YEAR, 1, GETDATE()))
FROM Contratos
WHERE
Id_Contrato = @Id_Contrato

SET @Mes_Periodo = DATEPART(MONTH, @pPeriodo)

SELECT
@Mes_Periodo_VC =	CASE @Mes_Periodo
						WHEN 1	THEN 'ENE'
						WHEN 2	THEN 'FEB'
						WHEN 3	THEN 'MAR'
						WHEN 4	THEN 'ABR'
						WHEN 5	THEN 'MAY'
						WHEN 6	THEN 'JUN'
						WHEN 7	THEN 'JUL'
						WHEN 8	THEN 'AGO'
						WHEN 9	THEN 'SEP'
						WHEN 10 THEN 'OCT'
						WHEN 11 THEN 'NOV'
						WHEN 12 THEN 'DIC'
					END


/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

SET @aNro_Comercio				=	(RIGHT('00000000' + @Comercio_Nro, 8))

SET @aTipo_Registro				=	'2' /*Debito Automatico*/

SET @aNro_Tarjeta				=	(RIGHT('0000000000000000' + @Tar_Nro, 16))

SET @aNro_Refencia				=	(RIGHT('000000000000' + CAST(@pId_Trans AS VARCHAR), 12))

SET @aCuotas					=	'001'

SET @aCuotas_Plan				=	'999'

SET @aFrecuencia_DB				=	'01'

SET @aImporte					=	RIGHT('00000000000' + CAST(CAST(@pImporte * 100 AS INT) AS VARCHAR), 11)

SET @aPeriodo					=	RIGHT('00' + CAST(DATEPART(MONTH, @pPeriodo) AS VARCHAR), 2)  + 
									'/' +
									SUBSTRING(RIGHT('0000' + CAST(DATEPART(YEAR, @pPeriodo) AS VARCHAR), 4), 3, 2)

SET @aFiller1					=	' '

SET @aFecha_Vto_Pago			=	RIGHT('00' + CAST(DATEPART(DAY, @Fecha_Cbte) AS VARCHAR), 2) +
									RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_Cbte) AS VARCHAR), 2)  + 
									SUBSTRING(RIGHT('0000' + CAST(DATEPART(YEAR, @Fecha_Cbte) AS VARCHAR), 4), 3, 2)
									

SET @aDatos_Auxiliares			= '                                        '

SET @aMarcaAplicaDevolucionIVA	= '0' /*No Aplica*/

SET @aImporte_Gravado			= '00000000000'

SET @aNumero_Factura			= (RIGHT('00000000000000000000' + CAST(@Comprobante_Nro AS VARCHAR), 20)) 

SET @aFiller2					= '                                                            '

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

SET @Retorno =	@aNro_Comercio +
				@aTipo_Registro +
				@aNro_Tarjeta +
				@aNro_Refencia +
				@aCuotas +
				@aCuotas_Plan +
				@aFrecuencia_DB +
				@aImporte +
				@aPeriodo +
				@aFiller1 +
				@aFecha_Vto_Pago +
				@aDatos_Auxiliares +
				@aMarcaAplicaDevolucionIVA +
				@aImporte_Gravado +
				@aNumero_Factura +
				@aFiller2


/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

RETURN ISNULL(@Retorno, '                                                                                                                                                                                                        ')
END
GO



