/*FIN Variable de Retorno*/

/*Variables Intermedias*/
/*FIN Variables Intermedias*/

/*SET @Id_Trans_NC = ISNULL((SELECT MAX(NC.Id_Trans)
							FROM Cbtes F
							JOIN Cbtes_Tipos TF ON F.Id_Tipo_Cbte = TF.Id_Tipo_Cbte AND TF.Compromete_Factura = 1
							JOIN Cbtes_Aplica A ON F.Id_Trans = A.Id_Trans
