CREATE FUNCTION [dbo].[CF_NumeroALetras]( @Numero numeric(18,2),@Moneda VARCHAR(20))
		 RETURNS Varchar(300)
AS
BEGIN
    DECLARE @ImpLetra Varchar(300)
        DECLARE @lnEntero INT,
                        @lcRetorno VARCHAR(512),
                        @lnTerna INT,
                        @lcMiles VARCHAR(512),
                        @lcCadena VARCHAR(512),
                        @lnUnidades INT,
                        @lnDecenas INT,
                        @lnCentenas INT,
                        @lnFraccion INT
        SELECT  @lnEntero = CAST(@Numero AS INT),
                        @lnFraccion = (@Numero - @lnEntero) * 100,
                        @lcRetorno = '',
                        @lnTerna = 1
  WHILE @lnEntero > 0
  BEGIN /* WHILE */
            -- Recorro terna por terna
            SELECT @lcCadena = ''
            SELECT @lnUnidades = @lnEntero % 10
            SELECT @lnEntero = CAST(@lnEntero/10 AS INT)
            SELECT @lnDecenas = @lnEntero % 10
            SELECT @lnEntero = CAST(@lnEntero/10 AS INT)
            SELECT @lnCentenas = @lnEntero % 10
            SELECT @lnEntero = CAST(@lnEntero/10 AS INT)
            -- Analizo las unidades
            SELECT @lcCadena =
            CASE /* UNIDADES */
              WHEN @lnUnidades = 1 THEN 'UN ' + @lcCadena
              WHEN @lnUnidades = 2 THEN 'DOS ' + @lcCadena
              WHEN @lnUnidades = 3 THEN 'TRES ' + @lcCadena
              WHEN @lnUnidades = 4 THEN 'CUATRO ' + @lcCadena
              WHEN @lnUnidades = 5 THEN 'CINCO ' + @lcCadena
              WHEN @lnUnidades = 6 THEN 'SEIS ' + @lcCadena
              WHEN @lnUnidades = 7 THEN 'SIETE ' + @lcCadena
              WHEN @lnUnidades = 8 THEN 'OCHO ' + @lcCadena
              WHEN @lnUnidades = 9 THEN 'NUEVE ' + @lcCadena
              ELSE @lcCadena
            END /* UNIDADES */
            -- Analizo las decenas
            SELECT @lcCadena =
            CASE /* DECENAS */
              WHEN @lnDecenas = 1 THEN
                CASE @lnUnidades
                  WHEN 0 THEN 'DIEZ '
                  WHEN 1 THEN 'ONCE '
                  WHEN 2 THEN 'DOCE '
                  WHEN 3 THEN 'TRECE '
                  WHEN 4 THEN 'CATORCE '
                  WHEN 5 THEN 'QUINCE '
                  WHEN 6 THEN 'DIEZ Y SEIS '
                  WHEN 7 THEN 'DIEZ Y SIETE '
                  WHEN 8 THEN 'DIEZ Y OCHO '
                  WHEN 9 THEN 'DIEZ Y NUEVE '
                END
              WHEN @lnDecenas = 2 THEN
              CASE @lnUnidades
                WHEN 0 THEN 'VEINTE '
                ELSE 'VEINTI' + @lcCadena
              END
              WHEN @lnDecenas = 3 THEN
              CASE @lnUnidades
                WHEN 0 THEN 'TREINTA '
                ELSE 'TREINTA Y ' + @lcCadena
              END
              WHEN @lnDecenas = 4 THEN
                CASE @lnUnidades
                    WHEN 0 THEN 'CUARENTA'
                    ELSE 'CUARENTA Y ' + @lcCadena
                END
              WHEN @lnDecenas = 5 THEN
                CASE @lnUnidades
                    WHEN 0 THEN 'CINCUENTA '
                    ELSE 'CINCUENTA Y ' + @lcCadena
                END
              WHEN @lnDecenas = 6 THEN
                CASE @lnUnidades
                    WHEN 0 THEN 'SESENTA '
                    ELSE 'SESENTA Y ' + @lcCadena
                END
              WHEN @lnDecenas = 7 THEN
                 CASE @lnUnidades
                    WHEN 0 THEN 'SETENTA '
                    ELSE 'SETENTA Y ' + @lcCadena
                 END
              WHEN @lnDecenas = 8 THEN
                CASE @lnUnidades
                    WHEN 0 THEN 'OCHENTA '
                    ELSE  'OCHENTA Y ' + @lcCadena
                END
              WHEN @lnDecenas = 9 THEN
                CASE @lnUnidades
                    WHEN 0 THEN 'NOVENTA '
                    ELSE 'NOVENTA Y ' + @lcCadena
                END
              ELSE @lcCadena
            END /* DECENAS */
            -- Analizo las centenas
            SELECT @lcCadena =
            CASE /* CENTENAS */
              WHEN @lnCentenas = 1 THEN 'CIENTO ' + @lcCadena
              WHEN @lnCentenas = 2 THEN 'DOSCIENTOS ' + @lcCadena
              WHEN @lnCentenas = 3 THEN 'TRESCIENTOS ' + @lcCadena
              WHEN @lnCentenas = 4 THEN 'CUATROCIENTOS ' + @lcCadena
              WHEN @lnCentenas = 5 THEN 'QUINIENTOS ' + @lcCadena
              WHEN @lnCentenas = 6 THEN 'SEISCIENTOS ' + @lcCadena
              WHEN @lnCentenas = 7 THEN 'SETECIENTOS ' + @lcCadena
              WHEN @lnCentenas = 8 THEN 'OCHOCIENTOS ' + @lcCadena
              WHEN @lnCentenas = 9 THEN 'NOVECIENTOS ' + @lcCadena
              ELSE @lcCadena
            END /* CENTENAS */
            -- Analizo la terna
            SELECT @lcCadena =
            CASE /* TERNA */
              WHEN @lnTerna = 1 THEN @lcCadena
              WHEN @lnTerna = 2 THEN @lcCadena + 'MIL '
              WHEN @lnTerna = 3 THEN @lcCadena + 'MILLONES '
              WHEN @lnTerna = 4 THEN @lcCadena + 'MIL '
              ELSE ''
            END /* TERNA */
            -- Armo el retorno terna a terna
            SELECT @lcRetorno = @lcCadena  + @lcRetorno
            SELECT @lnTerna = @lnTerna + 1
   END /* WHILE */
   IF @lnTerna = 1
       SELECT @lcRetorno = 'CERO'
   
   IF @lnFraccion <> 0
   BEGIN
		DECLARE @sFraccion VARCHAR(15)
		SET @sFraccion = '00' + LTRIM(CAST(@lnFraccion AS varchar))
		SET @lcRetorno = RTRIM(@lcRetorno) + ' CON ' + SUBSTRING(@sFraccion,LEN(@sFraccion)-1,2) + '/100'
   END
   IF RTRIM(LTRIM(@Moneda)) <> '' 
       SELECT @ImpLetra = 'SON '+ @Moneda +' '+ RTRIM(@lcRetorno) 
   ELSE 
       SELECT @ImpLetra = RTRIM(@lcRetorno) 

   RETURN @ImpLetra
END


		/*
		SELECT dbo.CF_NumeroALetras (1,' ')
		SELECT dbo.CF_NumeroALetras (34,' ')
		SELECT dbo.CF_NumeroALetras (345214.89,'DOLARES ')
		SELECT dbo.CF_NumeroALetras (456,'PESOS ')
		SELECT dbo.CF_NumeroALetras (1234567200.58,'PESOS ')
		SELECT dbo.CF_NumeroALetras (5522,'PESOS ')
		SELECT dbo.CF_NumeroALetras (12,'PESOS ')
		SELECT dbo.CF_NumeroALetras (988,'PESOS ')
		SELECT dbo.CF_NumeroALetras (1540,'PESOS ')
		SELECT dbo.CF_NumeroALetras (10009,'PESOS ')



		*/
GO


CREATE FUNCTION [dbo].[CF_PagoFacil_CB_FactElec_TX](@Trans INT) 
RETURNS CHAR(42)
AS
BEGIN


declare @trans_char char(8)

declare @id_pagoPyme char(4) --es fija 1434
DECLARE @Importe1 CHAR(8)
DECLARE @Fecha1 CHAR(5)
declare @cliente CHAR(5)
DECLARE @Retorno CHAR(42)
DECLARE @Mult CHAR(50)
DECLARE @Importe2 CHAR(6)
DECLARE @Fecha2 CHAR(5)
declare @tipoGeneracion char(1) --es fija 9
declare @nroOperacion char(6)-- es el id_trans
declare @moneda char(1) --es fija 0 (pesos)
DECLARE @pos smallint
DECLARE @Suma DECIMAL(12,2)
DECLARE @dv  CHAR(1)
declare @subtotal int


set @id_pagoPyme = '1434'
set @moneda = '0'
SET @Importe1  = (SELECT RIGHT ( '000000' + CAST(cast((ISNULL(Imp_Total,0) + ISNULL(Saldo_Anterior,0)) * Cotizacion * 100 AS int) AS VARCHAR), 8) 
                 FROM Cbtes WHERE Id_Trans = @trans)
SET @Fecha1    = (select substring(cast(DATEPART(YY,Fecha_Venc) as CHAR(4)),3,2) + 
                 SUBSTRING(CAST(DATEPART(dy,Fecha_Venc) + 1000 AS CHAR(4)),2,3)
                 FROM Cbtes WHERE Id_Trans = @trans)
--print @Fecha1
SET @Importe2  = '000000'
                 
SET @Fecha2    = '00'
                 
SET @cliente = (select RIGHT( '00000' + cast (substring(i.Id_Cliente_Externo,1,7)as varchar),5)
                 FROM Cbtes C , Clientes i WHERE c.id_Cliente = i.id_Cliente and Id_Trans = @trans)
                 
set @tipoGeneracion = '9'
--print @trans
set @trans_char = right( '00000000' + cast(@trans as varchar),8)
                 
set @retorno = '000000000000000000000000000000000000000000'                 
                 
--IF substring(@cliente,1,1) <> 'E'
--BEGIN
   set @retorno = @id_pagoPyme + @Importe1 + @Fecha1 + '00273' + @tipoGeneracion + @trans_char +
                  @moneda + @Importe2 + @Fecha2
  -- print @retorno
  -- print '123456789012345678901234567890123456789012345678901234567890'
   SET @Mult = '13579357935793579357935793579357935793579357935793579357935793579'
   SET @pos = 1
   SET @Suma = 0
   WHILE @pos <= 40
   BEGIN
        set @subtotal = CAST(SUBSTRING(@Retorno,@pos,1) AS INT) * CAST(SUBSTRING(@Mult,@pos,1) AS INT)
--       print cast (@pos as char(2)) +'   ' + cast (@subtotal as char(3))
		SET @Suma = @Suma + @subtotal
        SET @pos = @pos + 1
   END
  -- print @Suma
   SET @Suma = @Suma / 2
   SET @dv = CAST(CAST(@Suma AS INT) % 10 AS CHAR(1))
   SET @retorno = SUBSTRING(@retorno,1,40) + @dv

   SET @pos = 1
   SET @Suma = 0
   WHILE @pos <= 41
   BEGIN
		SET @Suma = @Suma + CAST(SUBSTRING(@Retorno,@pos,1) AS INT) * CAST(SUBSTRING(@Mult,@pos,1) AS INT)
        SET @pos = @pos + 1
   END
   SET @Suma = @Suma / 2
 --  print @Suma
   SET @dv = CAST(CAST(@Suma AS INT) % 10 AS CHAR(1))
   SET @retorno = SUBSTRING(@retorno,1,41) + @dv


return @retorno
END
GO


CREATE FUNCTION [dbo].[CF_PagoFacil_CB_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT) 
RETURNS CHAR(55)
AS
BEGIN

DECLARE @Retorno	CHAR(55)

DECLARE @EmpresaServicio	CHAR(4)
DECLARE @ImportePriVenc		CHAR(8)
DECLARE @Fecha_Venc			DATETIME
DECLARE @FechaPriVenc		CHAR(5)
DECLARE @Id_Cliente			INT
DECLARE @IdentCliente		CHAR(14)
DECLARE @Moneda				CHAR(1)
DECLARE @RecargoSegVenc		CHAR(6)
DECLARE @FechaSegVenc		CHAR(2)
DECLARE @DatosSinDigVer		CHAR(40)
DECLARE @DatosConDigVerifA	CHAR(41)
DECLARE @SecuenciaA			CHAR(5)
DECLARE @SecuenciaB			CHAR(4)
DECLARE @SecuenciaC			CHAR(3)
DECLARE @MultiplicadorA		CHAR(40)
DECLARE @MultiplicadorB		CHAR(41)
DECLARE @pos				SMALLINT
DECLARE @Suma				DECIMAL(12,2)
DECLARE @DigVerificadorA	CHAR(1)
DECLARE @DigVerificadorB	CHAR(1)
DECLARE @DigVerificador		CHAR(2)
DECLARE	@Fecha_Venc_P		INT

/*===========================================================================================*/

SET @EmpresaServicio	= (SELECT SUBSTRING(Valor_String,5,4) FROM xParametros WHERE IdParametro='Id_PagoFacil_Uti')

SET @ImportePriVenc		= (SELECT RIGHT('00000000' + CAST(CAST(ISNULL(@pImporte, 0) * 100 AS INT) AS VARCHAR), 8))


SET @Fecha_Venc_P = ISNULL(dbo.CF_xParam('PagoFacil_Fecha'), 0)

IF (@Fecha_Venc_P =0) --La fecha de vencimiento es del comprobante
BEGIN
SET @Fecha_Venc			= (SELECT Fecha_Venc FROM Cbtes WHERE Id_Trans = @pId_Trans)
END 

IF (@Fecha_Venc_P =1) --La fecha de vencimiento del lote de la tarjeta (Fecha Presentacion)
BEGIN 
SET @Fecha_Venc			= (SELECT ISNULL(Fecha_Presentacion, '19000101')
						FROM Val_Tarjetas_Lotes WHERE Id_Tar_Lote = @pId_Tar_Lote)
END

IF (@Fecha_Venc_P = 2) --16/06/2020. La fecha de hoy mas 1 mes (Como esta en CF_PagoFacil_TX)
BEGIN 
	SET @Fecha_Venc			= DATEADD(mm,1,GETDATE())
END

SET @FechaPriVenc		=(SUBSTRING(CAST(DATEPART(YY,@Fecha_Venc) AS CHAR(4)),3,2) + 
							SUBSTRING(CAST(DATEPART(dy,@Fecha_Venc) + 1000 AS CHAR(4)),2,3))

SET @Id_Cliente			= ISNULL((SELECT ISNULL(Id_Cliente, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans),0)
SET @IdentCliente		= (SELECT RIGHT('00000000000000' + CAST(@Id_Cliente AS VARCHAR),14))
		
SET @Moneda				= '0'
SET @RecargoSegVenc		= '000000'
SET @FechaSegVenc		= '00'

/*===========================================================================================*/

SET @DatosSinDigVer =	@EmpresaServicio +
						@ImportePriVenc +
						@FechaPriVenc +
						@IdentCliente +
						@Moneda +
						@RecargoSegVenc +
						@FechaSegVenc

SET @SecuenciaA = '13579'
SET @SecuenciaB = '3579'
SET @SecuenciaC = '357'
SET @MultiplicadorA = @SecuenciaA + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaC

SET @pos = 1
SET @Suma = 0
   
WHILE (@pos < 41)
BEGIN
	SET @Suma = @Suma + CAST(SUBSTRING(@DatosSinDigVer,@pos,1) AS INT) * CAST(SUBSTRING(@MultiplicadorA,@pos,1) AS INT)
    SET @pos = @pos + 1
END
   
SET @Suma = @Suma / 2
   
SET @DigVerificadorA = CAST(CAST(@Suma AS INT) % 10 AS CHAR(1))

SET @DatosConDigVerifA = @DatosSinDigVer + @DigVerificadorA

/*===========================================================================================*/

SET @MultiplicadorB = @SecuenciaA + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaB + @SecuenciaB

SET @pos = 1
SET @Suma = 0
   
WHILE (@pos < 42)
BEGIN
	SET @Suma = @Suma + CAST(SUBSTRING(@DatosConDigVerifA,@pos,1) AS INT) * CAST(SUBSTRING(@MultiplicadorB,@pos,1) AS INT)
    SET @pos = @pos + 1
END
   
SET @Suma = @Suma / 2
   
SET @DigVerificadorB = CAST(CAST(@Suma AS INT) % 10 AS CHAR(1))

/*===========================================================================================*/
SET @DigVerificador = @DatosConDigVerifA + @DigVerificadorB
/*===========================================================================================*/

SET @Retorno = @EmpresaServicio + /*04 caracteres. Empresa de Servicio.*/
				@ImportePriVenc +  /*08 caracteres. Formato: 6 enteros 2 decimales.*/
				@FechaPriVenc +    /*05 caracteres. Formato: AADDD. Ej. 05/07/2003 = 03186*/
				@IdentCliente +	   /*14 caracteres. Identificacion del Cliente.*/
				@Moneda	+		   /*01 caracteres. Valor "0" (Pesos).*/
				@RecargoSegVenc	+  /*06 caracteres. Formato: 4 enteros 2 decimales.*/
				@FechaSegVenc +	   /*02 caracteres. Formato DD.*/
				@DigVerificador	   /*02 caracteres. Doble Verificacion.*/
				
RETURN ISNULL(@Retorno, '                                                       ')

END
GO

CREATE  FUNCTION [dbo].[CF_PagoFacil_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT)  -- Le agregue el numero de lote
RETURNS CHAR(200)
AS
BEGIN

/*Variable de Retorno*/
DECLARE @Retorno			CHAR(200)
/*FIN Variable de Retorno*/

/*Variables del Archivo*/
DECLARE @aTipoRegistro		CHAR(2)	/*LONG: 02. Detalle de Registro. Valor "02"*/
DECLARE @aIdentPrimario		CHAR(21)/*LONG: 21. Clave Primaria para b·squeda*/
DECLARE @aIdentSecundario	CHAR(30)/*LONG: 30. Clave Secundaria para b·squeda*/
DECLARE @aNroSecuencia		CHAR(6)	/*LONG: 06. */
DECLARE @aMensaje			CHAR(20)/*LONG: 20. Mensaje a mostrar para el registro.*/
DECLARE @aNombreCliente		CHAR(40)/*LONG: 40. */
DECLARE @aCodBarra			CHAR(55)/*LONG: 55. */
DECLARE @aFechaVigencia		CHAR(8)	/*LONG: 08. Formato: AAAAMMDD*/
DECLARE @aFechaVencimiento	CHAR(8)	/*LONG: 08. Formato: AAAAMMDD*/
DECLARE @aTipoPago			CHAR(1)	/*LONG: 01. Valores Posibles: "T": Pago Total | "P": Pago Parcial | "A": Monto Abierto*/
DECLARE @aFiller			CHAR(9)	/*LONG: 09. */
/*FIN Variables del Archivo*/


/*Variables Intermedias*/
DECLARE @TipoIdentPrim	INT
DECLARE @Id_Cliente		INT
DECLARE @Id_Cliente_Externo VARCHAR(14)
DECLARE @Doc_Nro		BIGINT
DECLARE @Anio_Periodo	CHAR(4)
DECLARE @Mes_Periodo	CHAR(2)
DECLARE @Fecha_Cbte		DATETIME
DECLARE @Fecha_Hoy		DATETIME
DECLARE @Fecha_Hoy_MasUnMes	DATETIME
DECLARE @Anio_Hoy		CHAR(4)
DECLARE @Mes_Hoy		CHAR(2)
DECLARE @Dia_Hoy		CHAR(2)
DECLARE @Fecha_Venc		DATETIME
DECLARE @Anio_Venc		CHAR(4)
DECLARE @Mes_Venc		CHAR(2)
DECLARE @Dia_Venc		CHAR(2)
/*FIN Variables Intermedias*/

/*=================================================================================*/

SET @aTipoRegistro	= '02'

SET @Id_Cliente		= ISNULL((SELECT ISNULL(Id_Cliente, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans),0)
SET @Doc_Nro		= ISNULL((SELECT ISNULL(Doc_Nro, 0) FROM Clientes WHERE Id_Cliente = @Id_Cliente), 0)
SET @Id_Cliente_Externo = ISNULL((SELECT RTRIM(LTRIM(ISNULL(Id_Cliente_Externo, ''))) FROM Clientes WHERE Id_Cliente = @Id_Cliente), '')

SET @TipoIdentPrim = ISNULL(dbo.CF_xParam('PagoFacil_IdentPrim'), 0)

IF(@TipoIdentPrim = 0) /*Doc_Nro*/
BEGIN
	SET @aIdentPrimario = (RIGHT( '000000000000000000000' + CAST(@Doc_Nro AS VARCHAR), 21))
END

IF(@TipoIdentPrim = 1) /*Id_Cliente_Externo*/
BEGIN
	SET @aIdentPrimario = (RIGHT( '000000000000000000000' + CAST(@Id_Cliente_Externo AS VARCHAR), 21))
END

IF(@TipoIdentPrim = 2) /*Id_Cliente*/
BEGIN
	SET @aIdentPrimario = (RIGHT( '000000000000000000000' + CAST(@Id_Cliente AS VARCHAR), 21))
END



SET @aIdentSecundario = (CONVERT(CHAR(30), CAST(@pId_Trans AS VARCHAR)))

/*N·mero de Secuencia*/
SET @Fecha_Cbte		= (SELECT ISNULL(Fecha, '19000101') FROM Cbtes WHERE Id_Trans = @pId_Trans)
SET @Anio_Periodo	= CAST(DATEPART(YY,@Fecha_Cbte) AS CHAR(4))
SET @Mes_Periodo	= RIGHT('00' + CAST(MONTH(@Fecha_Cbte) AS VARCHAR),2)

SET @aNroSecuencia = @Anio_Periodo + @Mes_Periodo
/*FIN N·mero de Secuencia*/

SET @aMensaje = 'DEUDA AL ' + @Mes_Periodo + '/' + @Anio_Periodo

SET @aNombreCliente	= (SELECT SUBSTRING(ISNULL(Razon_Social, ''),0,20) FROM Clientes WHERE Id_Cliente = @Id_Cliente)


SET @aCodBarra = ISNULL((SELECT dbo.CF_PagoFacil_CB_TX(@pId_Trans, @pImporte, @pId_Tar_Lote)), '                                                       ')

/*Fecha Vigencia, se pidi¾ en el ticket 9315. 19/04/2017 que Fecha de Vigencia sea el dÝa actual*/
SET @Fecha_Hoy	= GETDATE()

SET @Anio_Hoy	= CAST(DATEPART(YY,@Fecha_Hoy) AS CHAR(4))
SET @Mes_Hoy	= RIGHT('00' + CAST(MONTH(@Fecha_Hoy) AS VARCHAR),2)
SET @Dia_Hoy	= RIGHT('00' + CAST(DAY(@Fecha_Hoy) AS VARCHAR),2)

SET @aFechaVigencia = @Anio_Hoy + @Mes_Hoy + @Dia_Hoy
/*FIN Fecha Vigencia*/

/*Fecha Vencimiento, se pidi¾ en el ticket 9315. 19/04/2017 que Fecha Vencimiento sea un mes mas de la fecha Actual*/
SET @Fecha_Hoy_MasUnMes = DATEADD(mm,1,GETDATE())

SET @Anio_Venc	= CAST(DATEPART(YY,@Fecha_Hoy_MasUnMes) AS CHAR(4))
SET @Mes_Venc	= RIGHT('00' + CAST(MONTH(@Fecha_Hoy_MasUnMes) AS VARCHAR),2)
SET @Dia_Venc	= RIGHT('00' + CAST(DAY(@Fecha_Hoy_MasUnMes) AS VARCHAR),2)

SET @aFechaVencimiento = @Anio_Venc + @Mes_Venc + @Dia_Venc
/*FIN Fecha Vencimiento*/

SET @aTipoPago = 'T'

SET @aFiller = '         '

/*=================================================================================*/

SET @retorno =	@aTipoRegistro		+
				@aIdentPrimario		+
				@aIdentSecundario	+
				@aNroSecuencia		+	
				@aMensaje			+	
				@aNombreCliente		+	
				@aCodBarra			+	
				@aFechaVigencia		+
				@aFechaVencimiento	+
				@aTipoPago			+
				@aFiller		

RETURN @retorno
END
GO

CREATE FUNCTION [dbo].[CF_Percep_IIBB_Entrerios_TX](@pId_Trans INT, @pId_Tipo_Reten VARCHAR(10), @pNroRenglon INT) 
RETURNS CHAR(140)
AS
BEGIN

DECLARE @Retorno			CHAR(140)
/*Formato segun ticket 004984*/
DECLARE @aNroRenglon		CHAR(5)		/*Formato: 99999 Creciente */
DECLARE @aFecha				CHAR(10)	/*Formato: ddmmaaaa*/
DECLARE @aTipoCbte			CHAR(3)		/*Formato: Ver lista abajo*/
DECLARE @aSucursal			CHAR(4)		/*Punto de Venta*/
DECLARE @aNroCbte			CHAR(8)		/*Formato: Ceros a la izquierda */
DECLARE @aNombre			CHAR(60)	/*Formato: Blancos a la derecha*/
DECLARE @aCUIT				CHAR(11)	/*Formato: 99999999999*/
DECLARE @aMonto				CHAR(10)	/*Formato: -999999999999.99 (no se aclara para este campo pero se supone que puede ser negativo sino no seria 16*/
DECLARE @aAlicuota			CHAR(4)		/*Formato: 99.99*/
DECLARE @aImporte			CHAR(10)	/*Formato: -999999999999.99 (Signo negativo a la izq en caso de indicar un Comprobante tipo Nota de Credito*/
DECLARE @aCodCM				CHAR(3)		/*Formato: 908 Codigo Convenio multilateral DDJJ */		
DECLARE @aTipoPercepcion    CHAR(3)		/* Regin de Percepcion segun la juridiccion 011*/
DECLARE @aSeparador			CHAR(1)     /*delimitador de campos*/


DECLARE @Id_Tipo_Cbte		CHAR(4)
DECLARE @Fecha				DATETIME
DECLARE @Id_Sucursal		SMALLINT
DECLARE @Comprobante_Nro	INT
DECLARE @Destinatario		VARCHAR(100)
DECLARE @Compromete_Factura	SMALLINT
DECLARE @Letra				CHAR(1)
DECLARE @Id_Triburario		VARCHAR(4)
DECLARE @Cuit				VARCHAR(11)
DECLARE @Imp_Total			DECIMAL(12,2)
DECLARE @Importe			DECIMAL(12,2)
DECLARE @Porc				DECIMAL(7,4)
DECLARE @Id_Cliente			INT
DECLARE @compromete_Recibo	SMALLINT
DECLARE @Imp_Base_Imponible	DECIMAL(12,2)
DECLARE @Fecha_Perc			DATETIME
/*Tipos de Comprobantes*/
/*
 * 1: Factura A
 * 2: Nota de Debito
 * 3: Recibo NO tiene Codigo Tributario
 * 4: Nota de Venta de Contado codigo 10
 * 5: Factura de Exportaci├│n codigo 19
 * 6: Nota de Debito para operacion c/exterior codigo 20
 * 7: Liquidacion codigos 27,28,29
 * 20: Otros Comprobantes de Debito 
 * 102: Nota de Credito 3
 * 106: Nota de Cr├®dito para operaciones c/exterior
 *120: Otros comprobantes de Credito codigo 21	
*/

SELECT	@Id_Tipo_Cbte		= ISNULL(Id_Tipo_Cbte, ''),
		@Fecha				= Fecha,
		@Id_Sucursal		= ISNULL(Id_Sucursal,0),
		@Comprobante_Nro	= ISNULL(Comprobante_Nro, 0),
		@Destinatario		= ISNULL(Destinatario, ''),
		@Id_Cliente			= ISNULL(Id_Cliente, 0),
		@Imp_Total			= ISNULL(Imp_Total, 0)
FROM Cbtes
WHERE
Id_Trans = @pId_Trans
AND Id_Estado_Cbte <> 3

SELECT	@Compromete_Factura = ISNULL(Compromete_Factura, 0),
		@compromete_Recibo	= ISNULL(@compromete_Recibo,0),
		@Letra				= ISNULL(Letra, ''),
		@Id_Triburario		= ISNULL(Id_Tributario, '')
FROM Cbtes_Tipos
WHERE
Id_Tipo_Cbte = @Id_Tipo_Cbte

SET @Cuit = (SELECT ISNULL(Cuit, '') FROM Clientes WHERE Id_Cliente = @Id_Cliente)

SELECT	@Importe			= ISNULL(CR.Importe, 0),
		@Porc				= ISNULL(CR.Porc, 0),
		@Imp_Base_Imponible = ISNULL(CR.Imp_Base_Imponible, 0),
		@Fecha_Perc			= Fecha
FROM Cbtes_Reten CR, Cbtes_Reten_Tipos CRT
WHERE
CR.Id_Tipo_Reten = CRT.Id_Tipo_Reten
AND CR.Id_Trans = @pId_Trans
AND ISNULL(CRT.Tipo, '') = 'P'
AND ISNULL(CRT.Tipo_Imp, '') = 'B'
AND ISNULL(CR.Importe, 0) <> 0
AND CR.Id_Tipo_Reten = @pId_Tipo_Reten


IF(@Id_Tipo_Cbte = '' OR @Id_Triburario = '' OR @Importe = 0)
BEGIN
	SET @Retorno = '                                                                                                                                            '
	RETURN @Retorno
END

/*Tipo Cbte*/
IF(@Id_Triburario IN ('01','06','11','201','206','211')) --1: Factura A
	SET @aTipoCbte = '001'

IF(@Id_Triburario IN ('2','02','07','12','202','207','212')) --Nota de Debito
	SET @aTipoCbte = '002'

/*Si es recibo No tiene Codigo Tributario X*/	
IF(@compromete_Recibo = 1)
	SET @aTipoCbte = '003'

IF(@Id_Triburario IN ('3','03','08','13','203','208','213')) --Nota de Credito
	SET @aTipoCbte = '102'

IF(@Id_Triburario = '10') --Nota de Venta de Contado
	SET @aTipoCbte = '004'
	
IF(@Id_Triburario = '19') --Factura de Exportaci├│n
	SET @aTipoCbte = '005'

IF(@Id_Triburario = '20') --Nota de Debito para operacion c/exterior
	SET @aTipoCbte = '006'
	
IF(@Id_Triburario IN ('27','28','29')) --Liquidaci├│n codigos 27,28,29
	SET @aTipoCbte = '007'

/*FIN Tipo Cbte*/	

SET @aSeparador		= ','
SET @aNroRenglon 	= RIGHT('00000' + CAST(@pNroRenglon as VARCHAR),5) 
--SET @aFecha			= RIGHT('00' + CAST(DAY(@Fecha) AS VARCHAR),2) + RIGHT('00' + CAST(MONTH(@Fecha) AS VARCHAR),2) + CAST(DATEPART(YY, @Fecha) AS CHAR(4))
SET @aFecha			= RIGHT('00' + CAST(DAY(@Fecha_Perc) AS VARCHAR),2) +
						'/' +
						RIGHT('00' + CAST(MONTH(@Fecha_Perc) AS VARCHAR),2) + 
						'/' +
						CAST(DATEPART(YY, @Fecha_Perc) AS CHAR(4))
SET @aSucursal		= RIGHT('0000' + CAST(@Id_Sucursal AS VARCHAR),4)
SET @aNroCbte		= RIGHT('00000000' + CAST(@Comprobante_Nro AS VARCHAR), 8)
SET @aNombre		= @Destinatario
SET @aCUIT			= @Cuit
SET @aCodCM			= '908'
SET @aTipoPercepcion = '001' /*Consultar el tipo de regimen para la juridiccion*/

IF(@aTipoCbte IN ('102', '106'))
BEGIN
	SET @aMonto		= '-' + RIGHT('0000000000' + CONVERT(VARCHAR(10), @Imp_Base_Imponible),10) 
	SET @aImporte	= '-' + RIGHT('0000000000' + CONVERT(VARCHAR(10), @Importe),10) 
END
ELSE
BEGIN
	SET @aMonto		= RIGHT('0000000000' + CONVERT(VARCHAR(10), @Imp_Base_Imponible),10) 
	SET @aImporte	= RIGHT('0000000000' + CONVERT(VARCHAR(10), @Importe),10) 
END

IF(@Porc >= 0.01)
BEGIN
	SET @aAlicuota = CAST(CONVERT(DECIMAL(7,2), @Porc) AS VARCHAR)
END
ELSE
BEGIN
	SET @aAlicuota = '0.01'
END

SET @Retorno	=	@aNroRenglon		+ @aSeparador +
					@aTipoCbte			+ @aSeparador +	
					@Letra				+ @aSeparador +
					@aSucursal			+
					@aNroCbte			+ @aSeparador +
					@aCUIT				+ @aSeparador +
					@aFecha				+ @aSeparador +
					@aMonto				+ @aSeparador +
					@aAlicuota			+ @aSeparador +
					@aImporte			+ @aSeparador +
					@aTipoPercepcion	+ @aSeparador +
					@aCodCM
					
				
RETURN ISNULL(@Retorno, '                                                                                                                                           ')
END
/*

SELECT dbo.CF_Percep_IIBB_Entrerios_TX(180314,'PERC.I.BRE', 17) 
00017,102,A,000000005091,30541519218,30/03/2023,-82555.33 ,0.50,-339.73   ,001,908                                                          
*/
GO


CREATE FUNCTION [dbo].[CF_Percep_IIBB_Salta_TX](@pId_Trans INT, @pId_Tipo_Reten VARCHAR(10) ) 
RETURNS CHAR(140)
AS
BEGIN

DECLARE @Retorno			CHAR(140)
/*Formato segun ticket 17499*/
DECLARE @aFecha				CHAR(8)		/*Formato: ddmmaaaa*/
DECLARE @aTipoCbte			CHAR(4)		/*Formato: Ver lista abajo*/
DECLARE @aNroCbte			CHAR(20)	/*Formato: Ceros a la izquierda*/
DECLARE @aNombre			CHAR(60)	/*Formato: Blancos a la derecha*/
DECLARE @aCUIT				CHAR(11)	/*Formato: 99999999999*/
DECLARE @aMonto				CHAR(16)	/*Formato: -999999999999.99 (no se aclara para este campo pero se supone que puede ser negativo sino no seria 16*/
DECLARE @aAlicuota			CHAR(5)		/*Formato: 99.99*/
DECLARE @aImporte			CHAR(16)	/*Formato: -999999999999.99 (Signo negativo a la izq en caso de indicar un Comprobante tipo Nota de Credito*/

DECLARE @Id_Tipo_Cbte		CHAR(4)
DECLARE @Fecha				DATETIME
DECLARE @Comprobante_Nro	INT
DECLARE @Destinatario		VARCHAR(100)
DECLARE @Compromete_Factura	SMALLINT
DECLARE @Letra				CHAR(1)
DECLARE @Id_Triburario		VARCHAR(4)
DECLARE @Cuit				VARCHAR(19)
DECLARE @Imp_Total			DECIMAL(12,2)
DECLARE @Importe			DECIMAL(13,2)
DECLARE @Porc				DECIMAL(7,4)
DECLARE @Id_Cliente			INT

/*Tipos de Comprobantes*/
/*
 * FA_A: Factura A
 * FA_B: Factura B
 * FA_C: Factura C
 * FA_P: Factura Publica
 * NC_A: Nota de Credito A
 * NC_B: Nota de Credito B
 * NC_C: Nota de Credito C
 * NC_P: Nota de Credito Publica
 * ND_A: Nota de Debito A
 * ND_B: Nota de Debito B
 * ND_C: Nota de Debito C
 * ND_P: Nota de Debito Publica
*/

SELECT	@Id_Tipo_Cbte		= ISNULL(Id_Tipo_Cbte, ''),
		@Fecha				= Fecha,
		@Comprobante_Nro	= ISNULL(Comprobante_Nro, 0),
		@Destinatario		= ISNULL(Destinatario, ''),
		@Id_Cliente			= ISNULL(Id_Cliente, 0),
		@Imp_Total			= ISNULL(Imp_Total, 0)
FROM Cbtes
WHERE
Id_Trans = @pId_Trans
AND Id_Estado_Cbte <> 3

SELECT	@Compromete_Factura = ISNULL(Compromete_Factura, 0),
		@Letra				= ISNULL(Letra, ''),
		@Id_Triburario		= ISNULL(Id_Tributario, '')
FROM Cbtes_Tipos
WHERE
Id_Tipo_Cbte = @Id_Tipo_Cbte

SET @Cuit = (SELECT ISNULL(Cuit, '') FROM Clientes WHERE Id_Cliente = @Id_Cliente)

SELECT	@Importe = ISNULL(CR.Importe, 0),
		@Porc = ISNULL(CR.Porc, 0)
FROM Cbtes_Reten CR, Cbtes_Reten_Tipos CRT
WHERE
CR.Id_Tipo_Reten = CRT.Id_Tipo_Reten
AND CR.Id_Trans = @pId_Trans
AND ISNULL(CRT.Tipo, '') = 'P'
AND ISNULL(CRT.Tipo_Imp, '') = 'B'
AND ISNULL(CR.Importe, 0) <> 0
AND CR.Id_Tipo_Reten = @pId_Tipo_Reten


IF(@Id_Tipo_Cbte = '' OR @Id_Triburario = '' OR @Importe = 0)
BEGIN
	SET @Retorno = '                                                                                                                                            '
	RETURN @Retorno
END

/*Tipo Cbte*/
IF(@Id_Triburario = '01')
	SET @aTipoCbte = 'FA_A'

IF(@Id_Triburario = '06')
	SET @aTipoCbte = 'FA_B'
	
IF(@Id_Triburario = '11')
	SET @aTipoCbte = 'FA_C'

IF(@Id_Triburario = '03')
	SET @aTipoCbte = 'NC_A'

IF(@Id_Triburario = '08')
	SET @aTipoCbte = 'NC_B'
	
IF(@Id_Triburario = '13')
	SET @aTipoCbte = 'NC_C'
	
IF(@Id_Triburario = '02')
	SET @aTipoCbte = 'ND_A'

IF(@Id_Triburario = '07')
	SET @aTipoCbte = 'ND_B'
	
IF(@Id_Triburario = '12')
	SET @aTipoCbte = 'ND_C'

--------------SE AGREGAN NUEVOS TIPOS DE CBTES--------------

IF(@Id_Triburario = '201')
	SET @aTipoCbte = 'FA_A'
		
IF(@Id_Triburario = '206')
	SET @aTipoCbte = 'FA_B'
	
IF(@Id_Triburario = '211')
	SET @aTipoCbte = 'FA_C'
	
IF(@Id_Triburario = '203')
	SET @aTipoCbte = 'NC_A'
	
IF(@Id_Triburario = '208')
	SET @aTipoCbte = 'NC_B'
	
IF(@Id_Triburario = '213')
	SET @aTipoCbte = 'NC_C'
	
IF(@Id_Triburario = '202')
	SET @aTipoCbte = 'ND_A'
	
IF(@Id_Triburario = '207')
	SET @aTipoCbte = 'ND_B'
	
IF(@Id_Triburario = '212')
	SET @aTipoCbte = 'ND_C'

/*FIN Tipo Cbte*/	

SET @aFecha = RIGHT('00' + CAST(DAY(@Fecha) AS VARCHAR),2) + RIGHT('00' + CAST(MONTH(@Fecha) AS VARCHAR),2) + CAST(DATEPART(YY, @Fecha) AS CHAR(4))

SET @aNroCbte	= RIGHT('00000000000000000000' + CAST(@Comprobante_Nro AS VARCHAR), 20)
SET @aNombre	= @Destinatario
SET @aCUIT		= @Cuit

IF(@aTipoCbte IN ('NC_A', 'NC_B', 'NC_C'))
BEGIN
	SET @aMonto		= '-' + RIGHT('000000000000000' + CAST(@Imp_Total AS VARCHAR), 15)
	SET @aImporte	= '-' + RIGHT('000000000000000' + CAST(@Importe AS VARCHAR), 15)
END
ELSE
BEGIN
	SET @aMonto		= RIGHT('0000000000000000' + CAST(@Imp_Total AS VARCHAR), 16)
	SET @aImporte	= RIGHT('0000000000000000' + CAST(@Importe AS VARCHAR), 16)
END

IF(@Porc >= 0.01)
BEGIN
	SET @aAlicuota = RIGHT('00000' + CAST(CONVERT(DECIMAL(7,2), @Porc) AS VARCHAR), 5)
END
ELSE
BEGIN
	SET @aAlicuota = '00.01'
END

SET @Retorno	=	@aFecha +
					@aTipoCbte +
					@aNroCbte +
					@aNombre +
					@aCUIT +
					@aMonto +
					@aAlicuota +
					@aImporte
					
RETURN ISNULL(@Retorno, '                                                                                                                                            ')
END
GO

CREATE FUNCTION CF_Preset_Valor (@Id_Usuario SMALLINT, @Id_Ventana VARCHAR(100) ,@Nombre VARCHAR(100), @Modo CHAR(1) )
RETURNS VARCHAR(8000)
AS
BEGIN

DECLARE @Retorno VARCHAR(8000)

IF ISNULL(@Id_Usuario,0) != 0
BEGIN 
	IF @Modo IN ('A','T')
	BEGIN
		SET @Retorno = (SELECT Valor 
						FROM xVentanas_Items_Users
						WHERE Id_Ventana = @Id_Ventana
						AND Nombre = @Nombre
						AND Id_Usuario = @Id_Usuario
						AND ISNULL(Flag_Modif,0) = 1
						AND (ISNULL(Flag_Todas,0) = 1 
							OR ISNULL(Flag_Agregar,0) = 1))
		IF @Retorno IS NOT NULL
			RETURN @Retorno
	END

	IF @Modo IN ('C','T')
	BEGIN
		SET @Retorno = (SELECT Valor 
						FROM xVentanas_Items_Users
						WHERE Id_Ventana = @Id_Ventana
						AND Nombre = @Nombre
						AND Id_Usuario = @Id_Usuario
						AND ISNULL(Flag_Modif,0) = 1
						AND (ISNULL(Flag_Todas,0) = 1 
							OR ISNULL(Flag_Cambiar,0) = 1))

		IF @Retorno IS NOT NULL
			RETURN @Retorno
	END

	IF @Modo IN ('B','T')
	BEGIN
		SET @Retorno = (SELECT Valor 
						FROM xVentanas_Items_Users
						WHERE Id_Ventana = @Id_Ventana
						AND Nombre = @Nombre
						AND Id_Usuario = @Id_Usuario
						AND ISNULL(Flag_Modif,0) = 1
						AND (ISNULL(Flag_Todas,0) = 1 
							OR ISNULL(Flag_Borrar,0) = 1))

		IF @Retorno IS NOT NULL
			RETURN @Retorno
	END
END

IF @Modo IN ('A','T')
BEGIN
	SET @Retorno = (SELECT Valor 
					FROM xVentanas_Items
					WHERE Id_Ventana = @Id_Ventana
					AND Nombre = @Nombre
					AND ISNULL(Flag_Modif,0) = 1
					AND (ISNULL(Flag_Todas,0) = 1 
						OR ISNULL(Flag_Agregar,0) = 1))

END

IF @Modo IN ('C','T')
BEGIN
	SET @Retorno = (SELECT Valor 
					FROM xVentanas_Items
					WHERE Id_Ventana = @Id_Ventana
					AND Nombre = @Nombre
					AND ISNULL(Flag_Modif,0) = 1
					AND (ISNULL(Flag_Todas,0) = 1 
						OR ISNULL(Flag_Cambiar,0) = 1))

END

IF @Modo IN ('B','T')
BEGIN
	SET @Retorno = (SELECT Valor 
					FROM xVentanas_Items
					WHERE Id_Ventana = @Id_Ventana
					AND Nombre = @Nombre
					AND ISNULL(Flag_Modif,0) = 1
					AND (ISNULL(Flag_Todas,0) = 1 
						OR ISNULL(Flag_Borrar,0) = 1))

END



RETURN @Retorno

END
GO


CREATE FUNCTION [dbo].[CF_Prisma_MasterCard_Cred_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT)
RETURNS CHAR(100)
AS
BEGIN

/*Variable de Retorno*/
DECLARE @Retorno			CHAR(100)
/*FIN Variable de Retorno*/


IF EXISTS ( SELECT * FROM sysobjects 
			WHERE 
			id = object_id(N'dbo.CF_Prisma_MasterCard_Cred_TX_') 
			AND type = 'FN')
BEGIN
	/*Si existe la funci¾n personalizada CF_Turno_Validar_ utiliza esa*/
    SET @Retorno = (dbo.CF_Prisma_MasterCard_Cred_TX_(@pId_Trans , @pImporte , @pId_Tar_Lote ))
    RETURN ISNULL(@Retorno, '')
END




/*Variables del Archivo*/
DECLARE @aTipoRegistro		CHAR(1)	/*LONG: 01. INI: 01. FIN: 01. Tipo de Registro. Fijo "1"*/
DECLARE @aNumeroTarjeta		CHAR(16)/*LONG: 16. INI: 02. FIN: 17. Numero de Tarjeta*/
DECLARE @aReservado01		CHAR(3)	/*LONG: 03. INI: 18. FIN: 20. Reservado. Constante espacios*/
DECLARE @aNroReferencia		CHAR(8)	/*LONG: 08. INI: 21. FIN: 28. Referencia o numero de comprobante o Nro. Secuencial ascendente unico por archivo.*/
DECLARE @aFechaOrigenVencDeb CHAR(8)/*LONG: 08. INI: 29. FIN: 36. Fecha de origen o vencimiento del debito. Formato AAAAMMDD*/
DECLARE @aCodigoTransaccion	CHAR(4)	/*LONG: 04. INI: 37. FIN: 40. Codigo de Transaccion. Fijo "0005"*/
DECLARE @aImporte			CHAR(15)/*LONG: 15. INI: 41. FIN: 55. Importe*/
DECLARE @aIdentificadorDeb	CHAR(15)/*LONG: 15. INI: 56. FIN: 70. Identificador del Debito*/
DECLARE @aCodigoAltaIdent	CHAR(1)	/*LONG: 01. INI: 71. FIN: 71. Codigo de alta del Identificador. Constante E si es el primer debito informado, sino espacios*/
DECLARE @aEstadoRegistro	CHAR(2)	/*LONG: 02. INI: 72. FIN: 73. Estado del registro - Fijo: " "*/
DECLARE @aReservado02		CHAR(26)/*LONG: 26. INI: 74. FIN: 99. Reservado. Constante espacios*/
DECLARE @aMarcaFin			CHAR(1)	/*LONG: 01. INI: 100. FIN: 100. Marca de fin de registro. Fijo "*"*/
/*FIN Variables del Archivo*/


/*Variables Intermedias*/
DECLARE @Tar_Nro				VARCHAR(22)
DECLARE @Fecha_Venc				DATETIME
DECLARE @Id_Cliente				INT
/*FIN Variables Intermedias*/

/*=================================================================================*/

SELECT	@Tar_Nro		= LTRIM(RTRIM(ISNULL(DBO.SF_COTIZA(Nro), '')))
FROM Val_Tarjetas_Lotes_Items 
WHERE
Id_Tar_Lote = @pId_Tar_Lote
AND Id_Trans = @pId_Trans

SELECT	@Fecha_Venc		= ISNULL(Fecha_Venc, '19000101'),
		@Id_Cliente		= ISNULL(Id_Cliente, 0)
FROM Cbtes 
WHERE
Id_Trans = @pId_Trans


/*=================================================================================*/

SET @aTipoRegistro		= '1'

SET @aNumeroTarjeta		= (RIGHT('0000000000000000' + CAST(@Tar_Nro AS VARCHAR), 16))

SET @aReservado01		= '   '

SET @aNroReferencia		= (RIGHT('00000000' + CAST(@pId_Trans AS VARCHAR), 8))

SET @aFechaOrigenVencDeb = CAST(DATEPART(YY, @Fecha_Venc) AS CHAR(4)) + RIGHT('00' + CAST(MONTH(@Fecha_Venc) AS VARCHAR),2) + RIGHT('00' + CAST(DAY(@Fecha_Venc) AS VARCHAR),2)

SET @aCodigoTransaccion = '0005'

SET @aImporte			= RIGHT('000000000000000' + CAST(CAST(@pImporte * 100 AS INT) AS VARCHAR), 15)

SET @aIdentificadorDeb	= RIGHT('000000000000000' + CAST(@Id_Cliente AS VARCHAR), 15)

SET @aCodigoAltaIdent	= 'E'

SET @aEstadoRegistro	= '  '

SET @aReservado02		= '                          '

SET @aMarcaFin			= '*'

/*=================================================================================*/

SET @retorno =	@aTipoRegistro		+
				@aNumeroTarjeta		+
				@aReservado01		+
				@aNroReferencia		+
				@aFechaOrigenVencDeb +
				@aCodigoTransaccion	+
				@aImporte			+
				@aIdentificadorDeb	+
				@aCodigoAltaIdent	+
				@aEstadoRegistro	+
				@aReservado02		+
				@aMarcaFin			

RETURN @retorno
END

/* 31/5/23 ahora paso el year de la fecha en digitos*/
GO

CREATE FUNCTION [dbo].CF_ProdFamilia_Facturado(@pId_Cliente INT, @pId_Producto VARCHAR(14), @pFechaDesde DATETIME, @pFechaHasta DATETIME) 
RETURNS INT
AS
BEGIN
DECLARE @Retorno INT
		,@FLAG_MES TINYINT
		,@FLAG_PERIODO TINYINT
		,@Estado_Proc_RECE INT
		,@ID_Familia INT




SELECT @FLAG_MES = ISNULL(FLAG_MES,0), @FLAG_PERIODO = ISNULL(FLAG_PERIODO,0), @ID_Familia = ISNULL(ID_FAMILIA,0) FROM Productos WHERE Id_Producto = @pId_Producto
SET @Estado_Proc_RECE = CAST(dbo.CF_xParam('Estado_Proc_RECE') AS INT)

IF @FLAG_MES <> 0
BEGIN
	SELECT @Retorno = (SELECT TOP 1 I.Id_trans FROM Cbtes_Items I, Cbtes C,Cbtes_Tipos T, Productos P
							WHERE I.Id_Trans = C.Id_Trans
							AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
							AND T.Compromete_Factura = 1
							AND ISNULL(I.Id_cliente,C.Id_Cliente) = @pId_Cliente
							AND I.Id_Producto = P.Id_Producto
							AND P.ID_FAMILIA = @ID_Familia
							AND C.Id_Estado_Cbte IN (1,2,4,@Estado_Proc_RECE)
							AND DATEPART(mm,I.Fecha_QA) = DATEPART(mm,@pFechaDesde)
							AND DATEPART(yy,I.Fecha_QA) = DATEPART(yy,@pFechaDesde)
					)
END
ELSE
BEGIN
	IF @FLAG_PERIODO <> 0
	BEGIN
		SELECT @Retorno = (SELECT TOP 1 I.Id_trans FROM Cbtes_Items I, Cbtes C,Cbtes_Tipos T, Productos P
								WHERE I.Id_Trans = C.Id_Trans
								AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
								AND T.Compromete_Factura = 1
								AND ISNULL(I.Id_cliente,C.Id_Cliente) = @pId_Cliente
							    AND I.Id_Producto = P.Id_Producto
							    AND P.ID_FAMILIA = @ID_Familia
								AND C.Id_Estado_Cbte IN (1,2,4,@Estado_Proc_RECE)
								AND @pFechaDesde <= I.Fecha_Venc
								AND @pFechaHasta >= I.Fecha_QA
						)
	END
END
RETURN ISNULL(@Retorno,0)

END
GO


CREATE FUNCTION [dbo].[CF_Prod_Familias_Cupo] 
(		@pId_Familia				INT
		,@pId_Prod_Familia_Sala		INT
		,@pId_Prod_Familia_Horario	INT
		,@pId_Producto				CHAR(14)
)		
RETURNS INT
AS
BEGIN
	DECLARE @Flag_Valida_Cupo	TINYINT
			,@Cupo INT

	SELECT @Flag_Valida_Cupo = Flag_Valida_Cupo FROM Prod_Familias WHERE Id_Familia = @pId_Familia

	IF @Flag_Valida_Cupo = 0
	   RETURN 0

	IF @Flag_Valida_Cupo = 1  --Por Sala
	BEGIN
		SELECT @Cupo = S.Cupo FROM Prod_Familias_Salas S WHERE S.Id_Prod_Familia_Sala = @pId_Prod_Familia_Sala
		RETURN ISNULL(@Cupo,0)
	END

	IF @Flag_Valida_Cupo = 2  --Por Sala Y Horario
	BEGIN
		SELECT @Cupo = S.Cupo FROM Prod_Familias_Horarios_Salas S WHERE S.Id_Prod_Familia_Sala = @pId_Prod_Familia_Sala AND S.Id_Prod_Familia_Horario = @pId_Prod_Familia_Horario
		RETURN ISNULL(@Cupo,0)
	END

	IF @Flag_Valida_Cupo = 3  --Por Sala Y Producto
	BEGIN
		SELECT @Cupo = S.Cupo FROM Prod_Salas S WHERE S.Id_Prod_Familia_Sala = @pId_Prod_Familia_Sala AND S.Id_Producto = @pId_Producto
		RETURN ISNULL(@Cupo,0)
	END

	IF @Flag_Valida_Cupo = 4  --Por Sala , Producto y Horario
	BEGIN
		--falta la tabla
		RETURN ISNULL(@Cupo,0)
	END

	IF @Flag_Valida_Cupo = 5  --Por Producto y Horario
	BEGIN
		SELECT @Cupo = S.Cupo FROM Prod_Horarios S WHERE S.Id_Prod_Familia_Horario = @pId_Prod_Familia_Horario AND S.Id_Producto = @pId_Producto
		RETURN ISNULL(@Cupo,0)
	END

	IF @Flag_Valida_Cupo = 6  --Por Horario
	BEGIN
		SELECT @Cupo = S.Cupo FROM Prod_Familias_Horarios S WHERE S.Id_Prod_Familia_Horario = @pId_Prod_Familia_Horario
		RETURN ISNULL(@Cupo,0)
	END
	
	IF @Flag_Valida_Cupo = 7  --Por Horario
	BEGIN
		SELECT @Cupo = S.Cupo FROM Prod_Familias S WHERE S.Id_Familia = @pId_Familia
		RETURN ISNULL(@Cupo,0)
	END

	IF @Flag_Valida_Cupo = 8  --Por Producto 20220816
	BEGIN
		SELECT @Cupo = S.Cupo FROM Productos S WHERE S.Id_Producto = @pId_Producto
		RETURN ISNULL(@Cupo,0)
	END

	RETURN ISNULL(@Cupo,0)
END
GO

CREATE FUNCTION CF_Prod_Listas_Precios_Validar_U (@Id_Lista_Precio SMALLINT, @Id_Usuario SMALLINT)
RETURNS TINYINT 
AS
BEGIN
IF (@Id_Usuario = -1)
	RETURN 1

IF ISNULL((SELECT COUNT(*) FROM Prod_Listas_precios_Usuarios WHERE Id_Lista_Precio = @Id_Lista_Precio),0) = 0
	RETURN 1

IF EXISTS (SELECT 1 FROM Prod_Listas_precios_Usuarios WHERE Id_Lista_Precio = @Id_Lista_Precio AND Id_Usuario = @Id_Usuario)
	RETURN 1


RETURN 0
END
GO


CREATE FUNCTION dbo.CF_Produc_Buscar_Cod_ITVF (@Id varchar(200))
RETURNS TABLE
AS
RETURN
(
    WITH Clean AS
    (
        SELECT
            IdClean = LTRIM(RTRIM(REPLACE(@Id, '''', ''))),
            Id30    = LEFT(LTRIM(RTRIM(REPLACE(@Id, '''', ''))), 30)
    )
    SELECT
        MatchType   = COALESCE(p1.MatchType, p2.MatchType, p3.MatchType, p4.MatchType, p5.MatchType, p6.MatchType),
        Id_Producto = COALESCE(p1.Id_Producto, p2.Id_Producto, p3.Id_Producto, p4.Id_Producto, p5.Id_Producto, p6.Id_Producto),
        Factor_Conv = COALESCE(p1.Factor_Conv, p2.Factor_Conv, p3.Factor_Conv, p4.Factor_Conv, p5.Factor_Conv, p6.Factor_Conv),
        Analisis    = COALESCE(p1.Analisis,    p2.Analisis,    p3.Analisis,    p4.Analisis,    p5.Analisis,    p6.Analisis),
        Lote        = COALESCE(p1.Lote,        p2.Lote,        p3.Lote,        p4.Lote,        p5.Lote,        p6.Lote),
        Despacho    = COALESCE(p1.Despacho,    p2.Despacho,    p3.Despacho,    p4.Despacho,    p5.Despacho,    p6.Despacho),
        Fecha_Venc  = COALESCE(p1.Fecha_Venc,  p2.Fecha_Venc,  p3.Fecha_Venc,  p4.Fecha_Venc,  p5.Fecha_Venc,  p6.Fecha_Venc),

        -- NUEVOS CAMPOS (del maestro Productos)
        Descripcion_Detallada  = COALESCE(p1.Descripcion_Detallada,  p2.Descripcion_Detallada,  p3.Descripcion_Detallada,  p4.Descripcion_Detallada,  p5.Descripcion_Detallada,  p6.Descripcion_Detallada),
        Descripcion_Resumida   = COALESCE(p1.Descripcion_Resumida,   p2.Descripcion_Resumida,   p3.Descripcion_Resumida,   p4.Descripcion_Resumida,   p5.Descripcion_Resumida,   p6.Descripcion_Resumida),
        Id_Iva                 = COALESCE(p1.Id_Iva,                 p2.Id_Iva,                 p3.Id_Iva,                 p4.Id_Iva,                 p5.Id_Iva,                 p6.Id_Iva),
        Precio_Gravado         = COALESCE(p1.Precio_Gravado,         p2.Precio_Gravado,         p3.Precio_Gravado,         p4.Precio_Gravado,         p5.Precio_Gravado,         p6.Precio_Gravado),
        Precio_Exento          = COALESCE(p1.Precio_Exento,          p2.Precio_Exento,          p3.Precio_Exento,          p4.Precio_Exento,          p5.Precio_Exento,          p6.Precio_Exento),
        Precio_Final           = COALESCE(p1.Precio_Final,           p2.Precio_Final,           p3.Precio_Final,           p4.Precio_Final,           p5.Precio_Final,           p6.Precio_Final),
        Precio_Formula         = COALESCE(p1.Precio_Formula,         p2.Precio_Formula,         p3.Precio_Formula,         p4.Precio_Formula,         p5.Precio_Formula,         p6.Precio_Formula),
        Precio_Formula_SQL     = COALESCE(p1.Precio_Formula_SQL,     p2.Precio_Formula_SQL,     p3.Precio_Formula_SQL,     p4.Precio_Formula_SQL,     p5.Precio_Formula_SQL,     p6.Precio_Formula_SQL)

    FROM Clean c

    -- 1) Productos.Id_Producto
    OUTER APPLY
    (
        SELECT TOP (1)
            MatchType   = CAST('ID_PRODUCTO' AS varchar(30)),
            Id_Producto = p.Id_Producto,
            Factor_Conv = CAST(NULL AS decimal(18,6)),
            Analisis    = CAST(NULL AS varchar(200)),
            Lote        = CAST(NULL AS varchar(200)),
            Despacho    = CAST(NULL AS varchar(200)),
            Fecha_Venc  = CAST(NULL AS date),

            Descripcion_Detallada = p.Descripcion_Detallada,
            Descripcion_Resumida  = p.Descripcion_Resumida,
            Id_Iva                = p.Id_Iva,
            Precio_Gravado        = p.Precio_Gravado,
            Precio_Exento         = p.Precio_Exento,
            Precio_Final          = p.Precio_Final,
            Precio_Formula        = p.Precio_Formula,
            Precio_Formula_SQL    = p.Precio_Formula_SQL
        FROM dbo.Productos p
        WHERE p.Id_Producto = c.IdClean
    ) p1

    -- 2) Productos.Id_Producto_Externo
    OUTER APPLY
    (
        SELECT TOP (1)
            MatchType   = CAST('ID_PRODUCTO_EXTERNO' AS varchar(30)),
            Id_Producto = p.Id_Producto,
            Factor_Conv = CAST(NULL AS decimal(18,6)),
            Analisis    = CAST(NULL AS varchar(200)),
            Lote        = CAST(NULL AS varchar(200)),
            Despacho    = CAST(NULL AS varchar(200)),
            Fecha_Venc  = CAST(NULL AS date),

            Descripcion_Detallada = p.Descripcion_Detallada,
            Descripcion_Resumida  = p.Descripcion_Resumida,
            Id_Iva                = p.Id_Iva,
            Precio_Gravado        = p.Precio_Gravado,
            Precio_Exento         = p.Precio_Exento,
            Precio_Final          = p.Precio_Final,
            Precio_Formula        = p.Precio_Formula,
            Precio_Formula_SQL    = p.Precio_Formula_SQL
        FROM dbo.Productos p
        WHERE p1.Id_Producto IS NULL
          AND p.Id_Producto_Externo = c.IdClean
    ) p2

    -- 3) Productos_CBarras.Cod_Barra (trae datos de Productos)
    OUTER APPLY
    (
        SELECT TOP (1)
            MatchType   = CAST('COD_BARRA' AS varchar(30)),
            Id_Producto = b.Id_Producto,
            Factor_Conv = b.Factor_Conv,
            Analisis    = CAST(NULL AS varchar(200)),
            Lote        = CAST(NULL AS varchar(200)),
            Despacho    = CAST(NULL AS varchar(200)),
            Fecha_Venc  = CAST(NULL AS date),

            Descripcion_Detallada = p.Descripcion_Detallada,
            Descripcion_Resumida  = p.Descripcion_Resumida,
            Id_Iva                = p.Id_Iva,
            Precio_Gravado        = p.Precio_Gravado,
            Precio_Exento         = p.Precio_Exento,
            Precio_Final          = p.Precio_Final,
            Precio_Formula        = p.Precio_Formula,
            Precio_Formula_SQL    = p.Precio_Formula_SQL
        FROM dbo.Productos_CBarras b
        JOIN dbo.Productos p ON p.Id_Producto = b.Id_Producto
        WHERE p1.Id_Producto IS NULL
          AND p2.Id_Producto IS NULL
          AND b.Cod_Barra = c.IdClean
    ) p3

    -- 4) Productos.Nro_Anmat
    OUTER APPLY
    (
        SELECT TOP (1)
            MatchType   = CAST('NRO_ANMAT' AS varchar(30)),
            Id_Producto = p.Id_Producto,
            Factor_Conv = CAST(NULL AS decimal(18,6)),
            Analisis    = CAST(NULL AS varchar(200)),
            Lote        = CAST(NULL AS varchar(200)),
            Despacho    = CAST(NULL AS varchar(200)),
            Fecha_Venc  = CAST(NULL AS date),

            Descripcion_Detallada = p.Descripcion_Detallada,
            Descripcion_Resumida  = p.Descripcion_Resumida,
            Id_Iva                = p.Id_Iva,
            Precio_Gravado        = p.Precio_Gravado,
            Precio_Exento         = p.Precio_Exento,
            Precio_Final          = p.Precio_Final,
            Precio_Formula        = p.Precio_Formula,
            Precio_Formula_SQL    = p.Precio_Formula_SQL
        FROM dbo.Productos p
        WHERE p1.Id_Producto IS NULL
          AND p2.Id_Producto IS NULL
          AND p3.Id_Producto IS NULL
          AND p.Nro_Anmat = c.IdClean
    ) p4

    -- 5) Items por Analisis (30) + vencimiento futuro (trae datos de Productos)
    OUTER APPLY
    (
        SELECT TOP (1)
            MatchType   = CAST('ITEM_ANALISIS' AS varchar(30)),
            Id_Producto = i.Id_Producto,
            Factor_Conv = CAST(NULL AS decimal(18,6)),
            Analisis    = i.Analisis,
            Lote        = i.Lote,
            Despacho    = i.Despacho,
            Fecha_Venc  = CONVERT(date, i.Fecha_Venc),

            Descripcion_Detallada = p.Descripcion_Detallada,
            Descripcion_Resumida  = p.Descripcion_Resumida,
            Id_Iva                = p.Id_Iva,
            Precio_Gravado        = p.Precio_Gravado,
            Precio_Exento         = p.Precio_Exento,
            Precio_Final          = p.Precio_Final,
            Precio_Formula        = p.Precio_Formula,
            Precio_Formula_SQL    = p.Precio_Formula_SQL
        FROM dbo.Cbtes_Items i
        JOIN dbo.Productos p ON p.Id_Producto = i.Id_Producto
        WHERE p1.Id_Producto IS NULL
          AND p2.Id_Producto IS NULL
          AND p3.Id_Producto IS NULL
          AND p4.Id_Producto IS NULL
          AND LEFT(i.Analisis, 30) = c.Id30
          AND i.Fecha_Venc > GETDATE()
        ORDER BY i.Fecha_QA DESC
    ) p5

    -- 6) Items por Lote (trae datos de Productos)
    OUTER APPLY
    (
        SELECT TOP (1)
            MatchType   = CAST('ITEM_LOTE' AS varchar(30)),
            Id_Producto = i.Id_Producto,
            Factor_Conv = CAST(NULL AS decimal(18,6)),
            Analisis    = i.Analisis,
            Lote        = i.Lote,
            Despacho    = i.Despacho,
            Fecha_Venc  = CONVERT(date, i.Fecha_Venc),

            Descripcion_Detallada = p.Descripcion_Detallada,
            Descripcion_Resumida  = p.Descripcion_Resumida,
            Id_Iva                = p.Id_Iva,
            Precio_Gravado        = p.Precio_Gravado,
            Precio_Exento         = p.Precio_Exento,
            Precio_Final          = p.Precio_Final,
            Precio_Formula        = p.Precio_Formula,
            Precio_Formula_SQL    = p.Precio_Formula_SQL
        FROM dbo.Cbtes_Items i
        JOIN dbo.Productos p ON p.Id_Producto = i.Id_Producto
        WHERE p1.Id_Producto IS NULL
          AND p2.Id_Producto IS NULL
          AND p3.Id_Producto IS NULL
          AND p4.Id_Producto IS NULL
          AND p5.Id_Producto IS NULL
          AND i.Lote = c.IdClean
    ) p6
);
GO

CREATE FUNCTION CF_Produc_Ocup_Cbte(@Id_Producto VARCHAR(14),@Fecha DATETIME) 
RETURNS INT
AS
BEGIN

DECLARE @Id_Trans INT

SET @Id_Trans = (SELECT TOP 1 A.Id_Trans FROM Cbtes_Items A, Cbtes B ,Cbtes_Tipos C 
                          WHERE A.Id_Trans = B.Id_Trans 
                          AND B.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
                          AND A.Flag_QA = 'A' AND B.Id_Estado_Cbte NOT IN (0,3)
                          AND (C.Compromete_Factura = 1 OR C.Compromete_Remitos = 1 OR C.Compromete_Pedido = 1) 
                          AND A.Fecha_QA <= @Fecha + 1 AND ISNULL(A.Fecha_Venc,@Fecha +1) >= @Fecha - 1
                          AND A.Id_Producto = @Id_Producto 
						  ORDER BY A.Id_Trans DESC )
RETURN ISNULL(@Id_Trans,0)
END
GO

CREATE FUNCTION CF_Produc_Ocup_Cont(@Id_Producto VARCHAR(14),@Fecha DATETIME) 
RETURNS INT
AS
BEGIN

DECLARE @Id_Contrato INT

SET @Id_Contrato = (SELECT TOP 1 A.Id_Contrato FROM Contratos_Prod A, Contratos B 
                          WHERE A.Id_Contrato = B.Id_Contrato 
                          AND B.Fecha_Desde <= @Fecha + 1 AND ISNULL(B.Fecha_Hasta,@Fecha +1) >= @Fecha - 1
                          AND A.Id_Producto = @Id_Producto 
						  AND B.Activo = 1
						  ORDER BY B.Id_Contrato)
RETURN ISNULL(@Id_Contrato,0)
END
GO



CREATE FUNCTION [dbo].[CF_Produc_Precio](@pId_Producto VARCHAR(14), @pId_Cliente INT, @pFecha DATETIME, @pId_Contrato INT, @pPorcBonif DECIMAL(9,4), @pTipoRespuesta CHAR(1))
RETURNS DECIMAL(16,4)
AS 
BEGIN

/*
Referencias de parametros de entrada:

@pPorcBonif //Porcentaje de Descuento con prioridad sobre cualquier otro descuento. Ej: 10 = 10% de descuento

@pTipoRespuesta = '' o 'B' //Retorna el Precio con Bonificacion aplicada
@pTipoRespuesta = 'S' //Retorna el Precio sin Bonificacion aplicada
@pTipoRespuesta = 'P' //Retorna el Porcentaje Bonificacion aplicada
*/

/*Variable de Retorno de la Funcion*/
DECLARE @Retorno						DECIMAL(16,4)
/*FIN Variable de Retorono de la Funcion*/


/*Variables Locales*/
DECLARE @JsonEnviar						VARCHAR(8000)
DECLARE @Precio							DECIMAL(12,4)
DECLARE @Precio_Grav					DECIMAL(12,4)
DECLARE @Precio_Exen					DECIMAL(12,4)
DECLARE @Prioridad_Calculo				TINYINT
DECLARE @Id_Lista_Precio_Cliente		SMALLINT
DECLARE @Id_Lista_Precio_Espec_Cliente	INT
DECLARE @Id_Lista_Precio_Contrato		SMALLINT
DECLARE @Precio_Contrato				DECIMAL(12,4)
DECLARE @Precio_Producto				DECIMAL(12,4)
DECLARE @Flag_Precio_For				TINYINT
DECLARE @Flag_Existe_Prod_Cli_Precios	TINYINT
DECLARE @Id_IVA							CHAR(3)
DECLARE @Porc_IVA						DECIMAL(7,4)
DECLARE @Porc_Bonif_Contrato			DECIMAL(5,2)
DECLARE @Porc_Bonif_Prod_Cli_Precios	DECIMAL(5,2)
DECLARE @Porc_Bonif_Lista_Precios_Items	DECIMAL(12,4)
DECLARE @Porc_Bonif_Prod_Listas_Precios_Items_Especial DECIMAL(12,2)
DECLARE @Porc_Bonif_Prod_Listas_Precios_Items_Comun DECIMAL(12,2)
DECLARE @Porc_A_Aplicar					DECIMAL(9,4)
/*FIN Variables Locales*/


/*=================================================================================*/
/*
 * PRIORIDADES DE CALCULO:
 * 
 * 1) Digitado en Contrato
 * 2) Formulado
 * 3) Prod_Cli_Precios
 * 4) Lista de Precios Contrato
 * 5) Lista de Precios Especial Cliente
 * 6) Lista de Precios "Comun" Cliente
 * 7) Producto
*/
SET @Prioridad_Calculo = 0

/*=================================================================================*/

IF(@pId_Producto = '')
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

/*=================================================================================*/

SELECT
		@Flag_Precio_For		= ISNULL(Flag_Precio_For, 0),
		@Precio_Producto		= ISNULL(Precio_Gravado, 0),
		@Id_IVA					= ISNULL(Id_IVA, '')
		FROM Productos
		WHERE
		Id_Producto = @pId_Producto


SELECT
		@Id_Lista_Precio_Cliente		= ISNULL(Id_Lista_Precio, 0),
		@Id_Lista_Precio_Espec_Cliente	= ISNULL(Id_Precio_Especial, 0)
		FROM Clientes
		WHERE
		Id_Cliente = @pId_Cliente


SELECT
		@Id_Lista_Precio_Contrato		= ISNULL(Id_Lista_Precio, 0),
		@Porc_Bonif_Contrato			= ISNULL(Porc_Bonif, 0)
		FROM Contratos
		WHERE
		Id_Contrato = @pId_Contrato

SELECT
		@Porc_IVA						= ISNULL(Porc1, 0)
		FROM Productos_TasaIVA
		WHERE
		Id_IVA = @Id_IVA

SET @Porc_A_Aplicar = 1 --Para multiplicar por defecto por 1

/*=================================================================================*/

IF(@pTipoRespuesta = 'P' AND @pPorcBonif > 0) --Porcentaje Bonificacion aplicada y llega por parametro retorna lo mismo
BEGIN
	RETURN ISNULL(@pPorcBonif, 0)
END

/*=================================================================================*/

/*1) Precio Digitado en Contrato*/

IF(@Prioridad_Calculo = 0 AND @pId_Contrato > 0)
BEGIN
	SELECT
	@Precio_Contrato = ISNULL(Precio, 0)
	FROM Contratos_Prod
	WHERE
	Id_Contrato = @pId_Contrato
	AND Id_Producto = @pId_Producto		

	IF(@Precio_Contrato <> 0)
	BEGIN
		/*Solo se considera que el precio de un contrato prima sobre el resto si es mayor que cero*/
		SET @Prioridad_Calculo = 1
		
		SET @Precio = @Precio_Contrato
		
		IF(@pTipoRespuesta = 'S') --Precio sin Bonificar
		BEGIN
			RETURN ISNULL(@Precio, 0)
		END
		
		IF(@pTipoRespuesta = 'P') --Porcentaje Bonificacion aplicada y el contrato tienen un porcentaje
		BEGIN
			RETURN ISNULL(@Porc_Bonif_Contrato, 0)
		END
		
		IF(@pTipoRespuesta = '' OR @pTipoRespuesta = 'B') --Precio Bonificado
		BEGIN
			IF(@pPorcBonif > 0) --Bonificacion Por parametro
			BEGIN
				SET @Precio = @Precio * ((100 - @pPorcBonif)/100)
			END
			ELSE
			BEGIN
				IF(@Porc_Bonif_Contrato > 0) -- Bonificacion del contrato
				BEGIN
					SET @Precio = @Precio * ((100 - @Porc_Bonif_Contrato)/100)
				END
			END
			
			RETURN ISNULL(@Precio, 0)
		END				
	END
END

/*=================================================================================*/

/*2) Precio Formulado*/

IF(@Prioridad_Calculo = 0 AND @Flag_Precio_For = 1)
BEGIN
	/*Si es formulado aunque el precio sea cero el retorno se devuelve ese*/
	SET @Prioridad_Calculo = 2
		
	SET @JsonEnviar =	'{' +
						dbo.CF_Json_ParsearVariable('Id_Producto', @pId_Producto, 'VARCHAR(14)') + ',' +
						dbo.CF_Json_ParsearVariable('Id_Cliente', @pId_Cliente, 'INT') + ',' +
						dbo.CF_Json_ParsearVariable('Fecha', @pFecha, 'DATETIME') + ',' +
						dbo.CF_Json_ParsearVariable('Id_Contrato', @pId_Contrato, 'INT') + 
						'}'
    SET @Precio = (dbo.CFUJ_Produc_Precio(@JsonEnviar))
    
	IF(@pTipoRespuesta = 'S') --Precio sin Bonificar
	BEGIN
		RETURN ISNULL(@Precio, 0)
	END
    
	IF(@pTipoRespuesta = 'P') --Porcentaje Bonificacion aplicada en caso de Precios formulados no se puede calcular la bonificacion ya que esta embebida en la formula
	BEGIN
		RETURN 0
	END
	
	IF(@pTipoRespuesta = '' OR @pTipoRespuesta = 'B') --Precio Bonificado
	BEGIN
		IF(@pPorcBonif > 0) --Bonificacion Por parametro
		BEGIN
			SET @Precio = @Precio * ((100 - @pPorcBonif)/100)
		END
		
		RETURN ISNULL(@Precio, 0)
	END
END

/*=================================================================================*/

/*3) Precio Prod_Cli_Precios*/

IF(@Prioridad_Calculo = 0 AND @pId_Cliente <> 0)
BEGIN
	SET @Flag_Existe_Prod_Cli_Precios = ISNULL((SELECT MAX(1) FROM Prod_Cli_Precios WHERE Id_Producto = @pId_Producto AND Id_Cliente = @pId_Cliente), 0)

	IF(@Flag_Existe_Prod_Cli_Precios = 1)
	BEGIN
		SET @Prioridad_Calculo = 3
		
		SELECT 
		@Precio							= ISNULL(Precio, 0),
		@Porc_Bonif_Prod_Cli_Precios	= ISNULL(Bonif, 0)
		FROM Prod_Cli_Precios
		WHERE
		Id_Producto = @pId_Producto
		AND Id_Cliente = @pId_Cliente

		IF(@pTipoRespuesta = 'S') --Precio sin Bonificar
		BEGIN
			RETURN ISNULL(@Precio, 0)
		END
	    
		IF(@pTipoRespuesta = 'P') --Porcentaje Bonificacion aplicada
		BEGIN
			RETURN ISNULL(@Porc_Bonif_Prod_Cli_Precios, 0)
		END
		
		IF(@pTipoRespuesta = '' OR @pTipoRespuesta = 'B') --Precio Bonificado
		BEGIN
			IF(@pPorcBonif > 0) --Bonificacion Por parametro
			BEGIN
				SET @Precio = @Precio * ((100 - @pPorcBonif)/100)
			END
			ELSE
			BEGIN
				IF(@Porc_Bonif_Contrato > 0) -- Bonificacion de Prod_Cli_Precios
				BEGIN
					SET @Precio = @Precio * ((100 - @Porc_Bonif_Prod_Cli_Precios)/100)
				END
			END
			
			RETURN ISNULL(@Precio, 0)
		END
	END
END

/*=================================================================================*/

/*4) Precio Lista de Precios Contrato*/

IF(@Prioridad_Calculo = 0 AND @Id_Lista_Precio_Contrato <> 0)
BEGIN
	SET @Flag_Existe_Prod_Cli_Precios = ISNULL((SELECT MAX(1) FROM Prod_Listas_Precios_Items WHERE Id_Producto = @pId_Producto AND Id_Lista_Precio = @Id_Lista_Precio_Contrato), 0)

	IF(@Flag_Existe_Prod_Cli_Precios = 1)
	BEGIN
		SET @Prioridad_Calculo = 4
		
		SELECT 
		@Precio	=
		CASE
			WHEN ISNULL(Precio_Nuevo, 0)<> 0.00 AND p.Fecha_Desde_Nueva <= @pFecha THEN ISNULL(Precio_Nuevo, 0)
			ELSE ISNULL(Precio, 0)
		END,
		@Porc_Bonif_Prod_Cli_Precios =ISNULL(Bonificacion, 0)
		FROM Prod_Listas_Precios_Items i, Prod_Listas_Precios p
		WHERE I.Id_Lista_Precio=p.Id_Lista_Precio
		AND i.Id_Producto = @pId_Producto
		AND i.Id_Lista_Precio = @Id_Lista_Precio_Contrato
		
		IF(@pTipoRespuesta = 'S') --Precio sin Bonificar
		BEGIN
			RETURN ISNULL(@Precio, 0)
		END
	    
		IF(@pTipoRespuesta = 'P') --Porcentaje Bonificacion aplicada
		BEGIN
			RETURN ISNULL(@Porc_Bonif_Lista_Precios_Items, 0)
		END
		
		IF(@pTipoRespuesta = '' OR @pTipoRespuesta = 'B') --Precio Bonificado
		BEGIN
			IF(@pPorcBonif > 0) --Bonificacion Por parametro
			BEGIN
				SET @Precio = @Precio * ((100 - @pPorcBonif)/100)
			END
			ELSE
			BEGIN
				IF(@Porc_Bonif_Contrato > 0) -- Bonificacion de Prod_Listas_Precios_Items
				BEGIN
					SET @Precio = @Precio * ((100 - @Porc_Bonif_Lista_Precios_Items)/100)
				END
			END
			
			RETURN ISNULL(@Precio, 0)
		END
	END
END

/*=================================================================================*/

/*5) Precio Lista de Precios Especial Cliente*/

IF(@Prioridad_Calculo = 0 AND @Id_Lista_Precio_Espec_Cliente <> 0)
BEGIN
	SET @Flag_Existe_Prod_Cli_Precios = ISNULL((SELECT MAX(1) FROM Prod_Listas_Precios_Items WHERE Id_Producto = @pId_Producto AND Id_Lista_Precio = @Id_Lista_Precio_Espec_Cliente), 0)

	IF(@Flag_Existe_Prod_Cli_Precios = 1)
	BEGIN
		SET @Prioridad_Calculo = 5
		--Agrego si existe Precio_Nuevo en Prod_Listas_Precios_Items y fecha_D
		SELECT 
		@Precio = 
		CASE
			WHEN ISNULL(Precio_Nuevo, 0)<> 0.00 AND p.Fecha_Desde_Nueva <= @pFecha THEN ISNULL(Precio_Nuevo, 0)
			ELSE ISNULL(Precio, 0)
		END,
		@Porc_Bonif_Prod_Listas_Precios_Items_Especial = ISNULL(Bonificacion, 0)
		FROM Prod_Listas_Precios_Items i, Prod_Listas_Precios p
		WHERE i.Id_Lista_Precio=p.Id_Lista_Precio
		AND	Id_Producto = @pId_Producto
		AND i.Id_Lista_Precio = @Id_Lista_Precio_Espec_Cliente
		
		IF(@pTipoRespuesta = 'S') --Precio sin Bonificar
		BEGIN
			RETURN ISNULL(@Precio, 0)
		END
	    
		IF(@pTipoRespuesta = 'P') --Porcentaje Bonificacion aplicada
		BEGIN
			RETURN ISNULL(@Porc_Bonif_Prod_Listas_Precios_Items_Especial, 0)
		END
		
		IF(@pTipoRespuesta = '' OR @pTipoRespuesta = 'B') --Precio Bonificado
		BEGIN
			IF(@pPorcBonif > 0) --Bonificacion Por parametro
			BEGIN
				SET @Precio = @Precio * ((100 - @pPorcBonif)/100)
			END
			ELSE
			BEGIN
				IF(@Porc_Bonif_Contrato > 0) -- Bonificacion de Prod_Listas_Precios_Items
				BEGIN
					SET @Precio = @Precio * ((100 - @Porc_Bonif_Prod_Listas_Precios_Items_Especial)/100)
				END
			END
			
			RETURN ISNULL(@Precio, 0)
		END
	END
END

/*=================================================================================*/

/*6) Precio Lista de Precios "Comun" Cliente*/

IF(@Prioridad_Calculo = 0 AND @Id_Lista_Precio_Cliente <> 0)
BEGIN
	SET @Flag_Existe_Prod_Cli_Precios = ISNULL((SELECT MAX(1) FROM Prod_Listas_Precios_Items WHERE Id_Producto = @pId_Producto AND Id_Lista_Precio = @Id_Lista_Precio_Cliente), 0)

	IF(@Flag_Existe_Prod_Cli_Precios = 1)
	BEGIN
		SET @Prioridad_Calculo = 6
		
		SELECT 
		@Precio = 
		CASE
			WHEN ISNULL(Precio_Nuevo, 0)<> 0.00 AND p.Fecha_Desde_Nueva <= @pFecha THEN ISNULL(Precio_Nuevo, 0)
			ELSE ISNULL(Precio, 0)
		END,
		@Porc_Bonif_Prod_Listas_Precios_Items_Comun = ISNULL(Bonificacion, 0)
		FROM Prod_Listas_Precios_Items i, Prod_Listas_Precios p
		WHERE i.Id_Lista_Precio=p.Id_Lista_Precio
		AND	i.Id_Producto = @pId_Producto
		AND i.Id_Lista_Precio = @Id_Lista_Precio_Cliente
		
		IF(@pTipoRespuesta = 'S') --Precio sin Bonificar
		BEGIN
			RETURN ISNULL(@Precio, 0)
		END
	    
		IF(@pTipoRespuesta = 'P') --Porcentaje Bonificacion aplicada
		BEGIN
			RETURN ISNULL(@Porc_Bonif_Prod_Listas_Precios_Items_Comun, 0)
		END
		
		IF(@pTipoRespuesta = '' OR @pTipoRespuesta = 'B') --Precio Bonificado
		BEGIN
			IF(@pPorcBonif > 0) --Bonificacion Por parametro
			BEGIN
				SET @Precio = @Precio * ((100 - @pPorcBonif)/100)
			END
			ELSE
			BEGIN
				IF(@Porc_Bonif_Contrato > 0) -- Bonificacion de Prod_Listas_Precios_Items
				BEGIN
					SET @Precio = @Precio * ((100 - @Porc_Bonif_Prod_Listas_Precios_Items_Comun)/100)
				END
			END
			
			RETURN ISNULL(@Precio, 0)
		END		
	END
END

/*=================================================================================*/

/*7) Precio Producto*/
IF(@Prioridad_Calculo = 0)
BEGIN
	SET @Prioridad_Calculo = 7
	
	SET @Precio = @Precio_Producto	
	
	IF(@pTipoRespuesta = 'S') --Precio sin Bonificar
	BEGIN
		RETURN ISNULL(@Precio, 0)
	END
    
	IF(@pTipoRespuesta = 'P') --Porcentaje Bonificacion aplicada en caso de Productos no existe
	BEGIN
		RETURN 0
	END
	
	IF(@pTipoRespuesta = '' OR @pTipoRespuesta = 'B') --Precio Bonificado
	BEGIN
		IF(@pPorcBonif > 0) --Bonificacion Por parametro
		BEGIN
			SET @Precio = @Precio * ((100 - @pPorcBonif)/100)
		END
		
		RETURN ISNULL(@Precio, 0)
	END
END

/*=================================================================================*/


RETURN 0 /*Tiene que haber salido por un RETURN anterior*/
END
GO

 
CREATE FUNCTION [dbo].[CF_Produc_Precio_Lista](@pId_Lista_Precio SMALLINT, @pId_Producto VARCHAR(14), @Fecha DATETIME,  @Id_Usuario INT)
RETURNS DECIMAL(12,2)
AS
BEGIN
DECLARE @Precio									DECIMAL(12,2)
DECLARE @Flag_Existe_Lista_Precio				TINYINT
DECLARE @Flag_Existe_Producto					TINYINT
DECLARE @Flag_Existe_Producto_En_Lista_Precios	TINYINT   
Declare @Prioridad                              TINYINT
DECLARE @Id_lista_Precio_Padre				    INT
DECLARE @Coeficiente         					DECIMAL(12,5)
DECLARE @Id_Sucursal          			        INT
Declare @Filtro_Sucursal                        SMALLINT
/*=================================================================================*/

SET @Id_Sucursal = 0

If @Id_Usuario <> 0
   SET @Id_Sucursal = ISNULL((SELECT ISNULL(Id_Sucursal,0) from Seg_User S Where S.No = @Id_Usuario),0)


SET @Flag_Existe_Lista_Precio = ISNULL((SELECT 1 FROM Prod_Listas_Precios WHERE Id_Lista_Precio = @pId_Lista_Precio), 0)
IF(@pId_Lista_Precio = 0 OR @Flag_Existe_Lista_Precio = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

SET @Flag_Existe_Producto = ISNULL((SELECT 1 FROM Productos WHERE Id_Producto = @pId_Producto), 0)
IF(@pId_Producto = '' OR @Flag_Existe_Producto = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END



SET @Flag_Existe_Producto_En_Lista_Precios = ISNULL((SELECT 1 FROM Prod_Listas_Precios_Items 
    WHERE Id_Lista_Precio = @pId_Lista_Precio AND Id_Producto = @pId_Producto), 0)
IF(@Flag_Existe_Producto_En_Lista_Precios = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

SET @Id_lista_Precio_Padre = ISNULL((SELECT Id_lista_Precio_Padre FROM Prod_Listas_Precios WHERE Id_lista_Precio = @pId_Lista_Precio),@pId_Lista_Precio)

IF @Id_lista_Precio_Padre = 0
   SET @Id_lista_Precio_Padre = @pId_Lista_Precio

SET @Filtro_Sucursal =  ISNULL((SELECT COUNT(*) 
                    FROM Prod_Listas_Precios_Suc S, Prod_Listas_Precios_Asoc A, Prod_Listas_Precios L, Prod_Listas_Precios_Items I
                    WHERE A.Id_Lista_Precio_Padre = @Id_lista_Precio_Padre
					      AND A.Id_Lista_Precio = S.Id_Lista_Precio
						  AND S.Id_Lista_Precio = L.Id_Lista_Precio
						  AND I.Id_Lista_Precio = L.Id_Lista_Precio
						  and I.Id_Producto = @pId_Producto
						  and L.Fecha_Desde <= @Fecha and dateadd(dd,1,L.Fecha_Hasta) >= @Fecha ),0)


SET @Coeficiente = ISNULL((SELECT Coeficiente FROM Prod_Listas_Precios WHERE Id_lista_Precio = @pId_Lista_Precio),1)

IF @Coeficiente = 0
   SET @Coeficiente = 1

/*=================================================================================*/
--select Top 1 lp.id_lista_precio,I.id_Producto,pl.coeficiente,i.Precio, CAST(ROUND((i.Precio*pl.coeficiente) * (1+(T.Porc1/100)),0) AS DECIMAL(14,2)) as Precio_Lista
set @Precio = 0
IF @Filtro_Sucursal <> 0 AND @Id_Sucursal <> 0
   BEGIN
		select Top 1 @Precio = ISNULL(CAST(ROUND((i.Precio*@Coeficiente),0) AS DECIMAL(14,2)),0) 
				 from Prod_Listas_Precios PL, 
					  Prod_Listas_Precios_Asoc A,
					  Prod_Listas_Precios_Suc S,
					  Prod_Listas_Precios LP,
 					  Prod_Listas_Precios_Items I,
					  Productos p
				where PL.Id_lista_Precio = @pId_Lista_Precio
				and I.Id_Producto = @pId_Producto
				AND A.Id_lista_Precio_Padre = @Id_lista_Precio_Padre
			--	and PL.Id_lista_Precio_Padre = @Id_lista_Precio_Padre
				and A.Id_lista_Precio = LP.Id_lista_Precio
				and I.Id_lista_precio = LP.Id_lista_Precio
				and Lp.Fecha_Desde <= @Fecha and dateadd(dd,1,Lp.Fecha_Hasta) >= @Fecha 
				AND S.Id_Lista_Precio = A.Id_Lista_Precio
				AND S.Id_Sucursal = @Id_Sucursal
				and P.Id_Producto = I.Id_Producto
				order by A.Orden desc
    END
   ELSE
    BEGIN
		select Top 1 @Precio = ISNULL(CAST(ROUND((i.Precio*@Coeficiente),0) AS DECIMAL(14,2)),0) 
				 from Prod_Listas_Precios PL, 
					  Prod_Listas_Precios_Asoc A,
					  Prod_Listas_Precios LP,
 					  Prod_Listas_Precios_Items I,
					  Productos p
				where PL.Id_lista_Precio = @pId_Lista_Precio
				and I.Id_Producto = @pId_Producto
				AND A.Id_lista_Precio_Padre = @Id_lista_Precio_Padre
			--	and PL.Id_lista_Precio_Padre = @Id_lista_Precio_Padre
				and A.Id_lista_Precio = LP.Id_lista_Precio
				and I.Id_lista_precio = LP.Id_lista_Precio
				and Lp.Fecha_Desde <= @Fecha and dateadd(dd,1,Lp.Fecha_Hasta) >= @Fecha 
				and P.Id_Producto = I.Id_Producto
				order by A.Orden desc
	END

/*=================================================================================*/
IF @Precio = 0
	SELECT
	@Precio = Precio
	FROM Prod_Listas_Precios_Items 
	WHERE 
	Id_Lista_Precio = @pId_Lista_Precio 
	AND Id_Producto = @pId_Producto

/*=================================================================================*/

/*PARA CUALQUIER OTRA PARTICULARIDAD IMPLEMENTAR A PARTIR DE AQUI LA MODIFICACION DE LA VARIABLE @Precio*/

/*=================================================================================*/

RETURN ISNULL(@Precio, 0)
END

