CREATE FUNCTION [dbo].[CF_Produc_Trans](@Id_Trans INT)
RETURNS VARCHAR(400)
AS
BEGIN

DECLARE @Descripcion_Producto	VARCHAR(150) 
DECLARE @Descripcion_Total		VARCHAR(400) 
	
DECLARE Contratos_Productos CURSOR FOR
		SELECT P.Descripcion_Resumida FROM Productos P, Cbtes_items CI
				WHERE	P.Id_Producto = CI.Id_Producto
				AND		Ci.Id_Trans=@Id_Trans

OPEN Contratos_Productos
FETCH NEXT FROM Contratos_Productos	INTO @Descripcion_Producto

WHILE @@FETCH_STATUS = 0
BEGIN
	IF  ISNULL(@Descripcion_Total,'')=''
		SET @Descripcion_Total = LTRIM(RTRIM(@Descripcion_Producto))
	ELSE
		SET @Descripcion_Total = LTRIM(RTRIM(ISNULL(@Descripcion_Total, ''))) + ' - ' + ISNULL(@Descripcion_Producto,'')
										
	FETCH NEXT FROM Contratos_Productos	INTO @Descripcion_Producto 
END
CLOSE Contratos_Productos
DEALLOCATE Contratos_Productos;

------------------------------------------------------------------------uctos;
						 
						  
RETURN ISNULL(@Descripcion_Total,'')
END
GO


CREATE FUNCTION dbo.CF_Producto_Facturado(@pId_Cliente INT, @pId_Producto VARCHAR(14), @pFechaDesde DATETIME, @pFechaHasta DATETIME) 
RETURNS INT
AS
BEGIN
DECLARE @Retorno INT
		,@FLAG_MES TINYINT
		,@FLAG_PERIODO TINYINT
		,@Estado_Proc_RECE INT




SELECT @FLAG_MES = ISNULL(FLAG_MES,0), @FLAG_PERIODO = ISNULL(FLAG_PERIODO,0) FROM Productos WHERE Id_Producto = @pId_Producto
SET @Estado_Proc_RECE = CAST(dbo.CF_xParam('Estado_Proc_RECE') AS INT)

IF @FLAG_MES <> 0
BEGIN
	SELECT @Retorno = (SELECT TOP 1 I.Id_trans FROM Cbtes_Items I, Cbtes C,Cbtes_Tipos T
							WHERE I.Id_Trans = C.Id_Trans
							AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
							AND T.Compromete_Factura = 1
							AND ISNULL(I.Id_cliente,C.Id_Cliente) = @pId_Cliente
							AND I.Id_Producto = @pId_Producto
							AND C.Id_Estado_Cbte IN (1,2,4,@Estado_Proc_RECE)
							AND DATEPART(mm,I.Fecha_QA) = DATEPART(mm,@pFechaDesde)
							AND DATEPART(yy,I.Fecha_QA) = DATEPART(yy,@pFechaDesde)
					)
END
ELSE
BEGIN
	IF @FLAG_PERIODO <> 0
	BEGIN
		SELECT @Retorno = (SELECT TOP 1 I.Id_trans FROM Cbtes_Items I, Cbtes C,Cbtes_Tipos T
								WHERE I.Id_Trans = C.Id_Trans
								AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
								AND T.Compromete_Factura = 1
								AND ISNULL(I.Id_cliente,C.Id_Cliente) = @pId_Cliente
								AND I.Id_Producto = @pId_Producto
								AND C.Id_Estado_Cbte IN (1,2,4,@Estado_Proc_RECE)
								AND @pFechaDesde <= ISNULL(I.Fecha_Venc,I.Fecha_QA)
								AND @pFechaHasta >= I.Fecha_QA
						)
	END
END
RETURN ISNULL(@Retorno,0)

END
GO


CREATE FUNCTION [dbo].[CF_Producto_Validar](@pId_Cliente INT, @pId_Producto VARCHAR(50))
RETURNS INT
AS
BEGIN

DECLARE @Respuesta				INT
DECLARE @Fecha_Venc             DATETIME
--===========================================================================================

IF EXISTS ( SELECT * FROM sysobjects 
			WHERE 
			id = object_id(N'dbo.CF_Producto_Validar_') 
			AND type = 'FN')
BEGIN
	/*Si existe la funci├│n personalizada CF_Turno_Validar_ utiliza esa*/
    SET @Respuesta = (dbo.CF_Producto_Validar_(@pId_Cliente, @pId_Cliente))
    RETURN @Respuesta
END

--===========================================================================================

	DECLARE cur_Valida_Turno CURSOR FOR
		select @pId_Cliente,@pId_Producto

		OPEN cur_Valida_Turno
		FETCH NEXT FROM cur_Valida_Turno INTO @pId_Cliente,@pId_Producto
		WHILE @@FETCH_STATUS = 0
		BEGIN

		SET @Fecha_Venc=( SELECT ISNULL(DATEADD(DAY,PCV.Cant_Dias_Gracia,CV.Fecha),'19900101') FROM  
						Clientes_Venc CV,	Prod_Cli_Venc PCV
						WHERE 
						 CV.Id_Tipo_Venc= PCV.Id_Tipo_Venc
						AND Id_Producto=@pId_Producto AND id_cliente=@pId_Cliente)

			IF (@Fecha_Venc< GETDATE())
			BEGIN
			SET @Respuesta = 0
			BREAK
			END
			ELSE
			BEGIN
			SET @Respuesta = 1
			END

		FETCH NEXT FROM cur_Valida_Turno INTO   @pId_Cliente,@pId_Producto
		END
		CLOSE cur_Valida_Turno
		DEALLOCATE cur_Valida_Turno
	
RETURN @Respuesta
END
GO



CREATE FUNCTION [dbo].[CF_Reportes_User_Validar](@pId_Reporte VARCHAR(50), @pId_Usuario INT)
RETURNS TINYINT
AS
BEGIN

DECLARE @Cant INT

SET @Cant = (SELECT COUNT(*) FROM TAB_REPORTES_USERS WHERE ID_REPORTE = @pId_Reporte)

IF ISNULL(@Cant,0) = 0 RETURN 1

SET @Cant = (SELECT COUNT(*) FROM TAB_REPORTES_USERS WHERE ID_REPORTE = @pId_Reporte AND ID_USUARIO = @pId_Usuario)

IF ISNULL(@Cant,0) > 0 RETURN 1


SET @Cant = (SELECT COUNT(*) FROM TAB_REPORTES_USERS  WHERE ID_REPORTE = @pId_Reporte
             AND ID_USUARIO in (select UGrpNo from Seg_UserInGroup where UserNo = @pId_Usuario))
 
IF ISNULL(@Cant,0) > 0 RETURN 1


RETURN 0
END
GO


CREATE FUNCTION [dbo].[CF_Rpt_CD_ES_Clientes_Cantidades](@pId_Controlador SMALLINT, @pResultado CHAR(1), @pTipo CHAR(1), @pFecha_Desde DATETIME, @pFecha_Hasta DATETIME, @pFlag_Persona_Identificadas TINYINT) 
RETURNS INT
AS
BEGIN

DECLARE @Cant INT

IF(@pFlag_Persona_Identificadas = 1)
BEGIN
	SET @Cant = ISNULL((SELECT COUNT(DISTINCT Id_Cliente)
						FROM CD_ES
						WHERE
						Id_Cliente > 0
						AND Id_Controlador = @pId_Controlador
						AND Resultado = @pResultado
						AND Tipo = @pTipo
						AND Fecha >= @pFecha_Desde
						AND Fecha <= @pFecha_Hasta)
						, 0)
END
ELSE
BEGIN
	SET @Cant = ISNULL((SELECT COUNT(*)
						FROM CD_ES
						WHERE
						Id_Cliente = 0
						AND Id_Controlador = @pId_Controlador
						AND Resultado = @pResultado
						AND Tipo = @pTipo
						AND Fecha >= @pFecha_Desde
						AND Fecha <= @pFecha_Hasta)
						, 0)
END

RETURN ISNULL(@Cant, 0)
END
GO



CREATE FUNCTION [dbo].[CF_SCA_Antipassback](@pId_Cliente INT, @pId_Acceso SMALLINT, @pFecha DATETIME, @pTipoAcceso CHAR(1), @pFechaEvento DATETIME)
RETURNS CHAR(1)
AS
BEGIN
DECLARE @Flag_Estado_Acceso			CHAR(1)
DECLARE @Cant_Horas_Antipassback	TINYINT
DECLARE @Flag_Evento				TINYINT
DECLARE @UltTipoAcceso				CHAR(1)
DECLARE @Tiempo_Antirebote			INT
DECLARE @UltPasadaExistosa			DATETIME
DECLARE @LimiteAntirrebote			DATETIME
DECLARE @CD_Controlador_Tipo		CHAR(1)
DECLARE @Id_Cliente_Master			INT

-------------------------------------------------------------------------------------------------------------------------------------

SET @Id_Cliente_Master = ISNULL((SELECT Id_Cliente FROM CD_Cli_Master WHERE Id_Cliente = @pId_Cliente), 0)

IF(@Id_Cliente_Master <> 0)
BEGIN
	SET @Flag_Estado_Acceso = 'O'
	RETURN @Flag_Estado_Acceso
END

-------------------------------------------------------------------------------------------------------------------------------------

-------------------------------------------------------------------------------------------------------------------------------------

SELECT 
@Cant_Horas_Antipassback	= ISNULL(Flag_Antipassback, 0), 
@Flag_Evento				= ISNULL(Flag_Evento, 0),
@Tiempo_Antirebote			= ISNULL(Tiempo_Antirebote, 0)		/*@Tiempo_Antirebote en centesimas de segundo*/
FROM CD_Accesos 
WHERE 
Id_Acceso = @pId_Acceso

-------------------------------------------------------------------------------------------------------------------------------------

--02/07/2021 Agregado
SELECT 
TOP 1
@CD_Controlador_Tipo = ISNULL(Tipo, 'E')
FROM CD_Controladores 
WHERE 
Id_Acceso = @pId_Acceso
ORDER BY Id_Controlador

-------------------------------------------------------------------------------------------------------------------------------------

IF(@Cant_Horas_Antipassback = 0)
BEGIN
	--SET @Cant_Horas_Antipassback = 16 --Horas
	SET @Flag_Estado_Acceso = 'O'
	RETURN @Flag_Estado_Acceso
END


IF(@Flag_Evento <> 0)
BEGIN
	-- Modo Evento (Ej. Partido)
	
	SET @UltPasadaExistosa =ISNULL((SELECT MAX(CE.Fecha)
								FROM CD_ES CE
								WHERE 
								CE.Id_Cliente = @pId_Cliente
								AND CE.Id_ES =	(SELECT MAX(CE2.Id_ES) FROM CD_ES CE2 WHERE CE2.Id_Cliente = @pId_Cliente AND CE2.Resultado = 'S' AND CE2.Id_Acceso IN (SELECT Id_Acceso FROM CD_Accesos WHERE Flag_Evento = 1 ))
								AND CE.Fecha >= @pFechaEvento),'19000101')
	
	IF(@UltPasadaExistosa <> '19000101')
	BEGIN
		/*Ya paso una vez por Molinete durante el evento*/
		SET @LimiteAntirrebote = DATEADD(SS, (@Tiempo_Antirebote/100), @UltPasadaExistosa)		
		
		SET @UltTipoAcceso =	(SELECT ISNULL(MAX(CE.Tipo), 'S')
								FROM CD_ES CE
								WHERE 
								CE.Id_Cliente = @pId_Cliente
								AND CE.Id_ES =	(SELECT MAX(CE2.Id_ES) FROM CD_ES CE2 WHERE CE2.Id_Cliente = @pId_Cliente AND CE2.Resultado = 'S' AND CE2.Id_Acceso IN (SELECT Id_Acceso FROM CD_Accesos WHERE Flag_Evento = 1 ))
								AND CE.Fecha >= @pFechaEvento
								AND @pFecha >= @LimiteAntirrebote)

		IF(@UltTipoAcceso = @pTipoAcceso)
		BEGIN
			IF(@pTipoAcceso = 'E')
			BEGIN
				--Ya Ingresado
				SET @Flag_Estado_Acceso = 'Y'
				RETURN @Flag_Estado_Acceso
			END
			
			IF(@pTipoAcceso = 'S')
			BEGIN
				--No Registro Entrada
				SET @Flag_Estado_Acceso = 'S'
				RETURN @Flag_Estado_Acceso
			END
		END
	END
	ELSE
	BEGIN
		/*Nunca Paso*/
		SET @Flag_Estado_Acceso = 'O'
		RETURN @Flag_Estado_Acceso
	END
END
ELSE
BEGIN

	-- Modo "Normal"
	SET @UltTipoAcceso = (SELECT ISNULL(MAX(CE.Tipo), 'S')
		FROM CD_ES CE
		WHERE CE.Id_Cliente = @pId_Cliente
		  AND CE.Resultado = 'S'
		  AND CE.Fecha <= DATEADD(SECOND, (-@Tiempo_Antirebote / 100), @pFecha)
		  AND CE.Fecha >= DATEADD(HOUR, (-@Cant_Horas_Antipassback), @pFecha)
	)

	IF(@UltTipoAcceso = @pTipoAcceso)
	BEGIN
		IF(@pTipoAcceso = 'E')
		BEGIN
			IF(@CD_Controlador_Tipo = 'A')
			BEGIN
				--No Registro Salida
				SET @Flag_Estado_Acceso = 'E'
			END
			ELSE
			BEGIN
				--Ya ingresado. Antipassback
				SET @Flag_Estado_Acceso = 'Y'				
			END

			RETURN @Flag_Estado_Acceso
			/*
			02/07/2021 Se modifico
			--No Registro Salida
			SET @Flag_Estado_Acceso = 'E'
			RETURN @Flag_Estado_Acceso
			*/
		END
		
		IF(@pTipoAcceso = 'S')
		BEGIN
			--No Registro Entrada
			SET @Flag_Estado_Acceso = 'S'
			RETURN @Flag_Estado_Acceso
		END
	END						

END

RETURN ISNULL(@Flag_Estado_Acceso, 'O')

END
GO


CREATE FUNCTION [dbo].[CF_SCA_Cliente_ApeNom](@pId_Cliente INT)
RETURNS VARCHAR(100)
AS
BEGIN
DECLARE @Ape_Nom		VARCHAR(100)
DECLARE @Apellido		VARCHAR(100)
DECLARE @Nombre			VARCHAR(100)
DECLARE @Razon_Social	VARCHAR(100)

SELECT  @Apellido		= ISNULL(Apellido, ''),
		@Nombre			= ISNULL(Nombre, ''),
		@Razon_Social	= ISNULL(Razon_Social, '')
FROM Clientes
WHERE 
Id_Cliente = @pId_Cliente

SET @Apellido = REPLACE(@Apellido, ',', '')
SET @Nombre = REPLACE(@Nombre, ',', '')
SET @Razon_Social = REPLACE(@Razon_Social, ',', '')

IF(@Apellido <> '')
BEGIN
	SET @Ape_Nom = @Apellido + ' ' + @Nombre
END
ELSE
BEGIN
	SET @Ape_Nom = @Razon_Social
END

RETURN ISNULL(@Ape_Nom, '')

END
GO


CREATE FUNCTION [dbo].[CF_SCA_DatosAdicionales](@pId_Cliente	INT, @pId_Evento SMALLINT, @pFecha DATETIME)
RETURNS VARCHAR(MAX)
AS
BEGIN

DECLARE @Datos_Adicionales		VARCHAR(MAX)
DECLARE @Razon_Social			VARCHAR(100)
DECLARE @Razon_Social_Titu		VARCHAR(100)
DECLARE @Categoria				VARCHAR(100)
DECLARE @Id_Cliente_Ref			INT
DECLARE @Doc_Nro				BIGINT
DECLARE @Fecha_Nac				DATETIME
DECLARE @Ult_Cuota_Paga			DATETIME
DECLARE @Cant_Visitas			INT
DECLARE @Id_Tipo_Cli			SMALLINT
DECLARE @Abono_Estacionamiento	INT

SELECT 
	@Razon_Social	= ISNULL(CL.Razon_Social, ''),
	@Categoria		= ISNULL(CT.Descripcion, ''),
	@Id_Cliente_Ref = ISNULL(CL.Id_Cliente_Ref, 0),
	@Doc_Nro		= ISNULL(CL.Doc_Nro, 0),
	@Fecha_Nac		= ISNULL(CL.Fecha_Nac, '19000101'),
	@Ult_Cuota_Paga = ISNULL(CL.Ult_Cuota_Paga, '19000101'),
	@Id_Tipo_Cli	= ISNULL(CL.Id_Tipo_Cli, 0)
FROM Clientes CL
	LEFT JOIN Clientes_Tipos CT ON ISNULL(CL.Id_Tipo_Cli, 0) = CT.Id_Tipo_Cli
WHERE Id_Cliente = @pId_Cliente

SET @Razon_Social = REPLACE(@Razon_Social, ',', ' ')

IF(@Id_Cliente_Ref <> 0)
BEGIN
	SET @Razon_Social_Titu = (SELECT ISNULL(Razon_Social, '') FROM Clientes WHERE Id_Cliente = @pId_Cliente)
	SET @Razon_Social_Titu = REPLACE(@Razon_Social_Titu, ',', ' ')
END

SET @Datos_Adicionales = 'Categoria  : '	+ LTRIM(RTRIM(@Categoria)) + '$' +
						-- 'Nro. Doc.  : '	+ LTRIM(RTRIM(CONVERT(VARCHAR(20), @Doc_Nro))) + '$' +
						-- 'Fecha Nac.: '	+ LTRIM(RTRIM(CONVERT(VARCHAR(10), @Fecha_Nac, 101))) + ' (' + LTRIM(RTRIM(CONVERT(VARCHAR(3), dbo.CF_Edad_Persona_A_UnaFecha(@Fecha_Nac, @pFecha)))) + ' años)' + '$' +
						 'U.C.P.: '		+ LTRIM(RTRIM(CONVERT(VARCHAR(10), @Ult_Cuota_Paga, 103))) + '$'

IF(@Id_Cliente_Ref <> 0)
BEGIN
	SET @Datos_Adicionales = @Datos_Adicionales + 'Titular: ' + LTRIM(RTRIM(@Razon_Social_Titu))  + '$'
END

IF @Id_Tipo_Cli IN(1018, 1103, 1113) /*Visitas*/
BEGIN
	SET @Cant_Visitas= ISNULL((SELECT COUNT(*) 
										FROM CD_ES
										WHERE
										Id_Cliente = @pId_Cliente
										AND Fecha >= DATEADD(month, -6, GETDATE()) /* últimos 6 meses */)
									,0)
	SET @Datos_Adicionales = @Datos_Adicionales + 'CANTIDAD INGRESOS: ' + LTRIM(RTRIM(@Cant_Visitas))  + '$'
END

SET @Abono_Estacionamiento =	(SELECT  SUM(I.Cantidad_Saldo)
								FROM Productos P
									JOIN Cbtes_Items I ON I.Id_Producto = P.Id_Producto
									JOIN Cbtes C ON I.Id_Trans = C.Id_Trans 
									JOIN Clientes L ON I.Id_Cliente = L.Id_Cliente
									JOIN Cbtes_Tipos CT ON C.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
								WHERE P.Flag_Entregas = 1
									AND (L.Id_Cliente = @pId_Cliente OR L.Id_Cliente_Ref = @pId_Cliente)
									AND C.Id_Estado_Cbte IN (2,4)
									AND CT.Compromete_Factura = 1
									AND CONVERT(VARCHAR(10),I.Fecha_QA,103) <= CONVERT(VARCHAR(10),@pFecha,103)
									AND CONVERT(VARCHAR(10),I.Fecha_Venc,103) >= CONVERT(VARCHAR(10),@pFecha, 103))

IF @Abono_Estacionamiento > 0
BEGIN
	SET @Datos_Adicionales = @Datos_Adicionales + 'Posee ' + CONVERT(VARCHAR(10),@Abono_Estacionamiento)  + ' Estadias para Estacionamiento $'
END

RETURN ISNULL(@Datos_Adicionales, '')
END
GO


CREATE FUNCTION [dbo].[CF_SCA_FormatoIP](@pDireccionIP VARCHAR(15))
RETURNS VARCHAR(15)
AS
BEGIN
DECLARE @DireccionIPFormateada	VARCHAR(15)
DECLARE @Posicion	INT
DECLARE @IP_Part	VARCHAR(3)

IF(LEN(@pDireccionIP) < 15)
BEGIN

	IF((SELECT MAX(Id) FROM dbo.SF_DivisionCadena(@pDireccionIP, '.')) = 4)
	BEGIN
		DECLARE curIPFormateada CURSOR FOR 
		SELECT Id, corte FROM dbo.SF_DivisionCadena(@pDireccionIP, '.')
		ORDER BY Id

		OPEN curIPFormateada
		FETCH NEXT FROM curIPFormateada INTO @Posicion, @IP_Part
		WHILE @@FETCH_STATUS = 0
		BEGIN
			
			IF(@Posicion = 1)
			BEGIN
				SET @DireccionIPFormateada = RIGHT('000' + LTRIM(RTRIM(@IP_Part)), 3)
			END
			ELSE
			BEGIN
				SET @DireccionIPFormateada = @DireccionIPFormateada + '.' + RIGHT('000' + LTRIM(RTRIM(@IP_Part)), 3)
			END
			FETCH NEXT FROM curIPFormateada INTO @Posicion, @IP_Part
		END 
		CLOSE curIPFormateada
		DEALLOCATE curIPFormateada
	END
END
ELSE
BEGIN
	SET @DireccionIPFormateada = @pDireccionIP
END

RETURN ISNULL(@DireccionIPFormateada, '255.255.255.255')

END
GO


CREATE FUNCTION [dbo].[CF_SCA_GenerarQR](@pId_Trans INT, @pItem SMALLINT) 
RETURNS VARCHAR(50)
AS
BEGIN
/*Variable de Retorno*/
DECLARE @QR				VARCHAR(50)
/*FIN Variable de Retorno*/

/*Variables Locales*/
DECLARE @Evento_QR_Formato		VARCHAR(40)
DECLARE @Id_Lista_Precio		SMALLINT	
DECLARE @Id_Acceso				SMALLINT
DECLARE @Prox_Nro_Secuencial	INT
DECLARE @Cbtes_Id_Cliente		INT
DECLARE @Cbtes_Items_Id_Cliente	INT
DECLARE @Id_Producto			VARCHAR(14)
DECLARE @Doc_Nro				BIGINT
DECLARE @Nro_Ubic				VARCHAR(10)
DECLARE @Lote					VARCHAR(20)
/*FIN Variables Locales*/

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@pId_Trans = 0 OR @pItem = 0)
BEGIN
	SET @QR = ''
	RETURN @QR
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

SET @Evento_QR_Formato = dbo.CF_xParam('Evento_QR_Formato')

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

SELECT 
@Id_Lista_Precio			= ISNULL(Id_Lista, 0),
@Cbtes_Id_Cliente			= ISNULL(Id_Cliente, 0)
FROM Cbtes
WHERE
Id_Trans = @pId_Trans

SELECT
@Cbtes_Items_Id_Cliente		= ISNULL(Id_Cliente, 0),
@Id_Producto				= ISNULL(Id_Producto, ''),
@Lote						= ISNULL(Lote, '')
FROM Cbtes_Items
WHERE
Id_Trans = @pId_Trans
AND Item = @pItem

SELECT
@Doc_Nro					= ISNULL(Doc_Nro, 0)
FROM Clientes
WHERE
Id_Cliente = @Cbtes_Items_Id_Cliente

SELECT
@Nro_Ubic					= ISNULL(Nro_Ubic, '')
FROM Productos
WHERE
Id_Producto	= @Id_Producto

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@Evento_QR_Formato = 'DNI')
BEGIN
	SET @QR = CONVERT(VARCHAR(20), @Doc_Nro)

	RETURN @QR
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@Evento_QR_Formato = '14')
BEGIN
	SET @QR =	RIGHT('0000' + CAST(@Id_Lista_Precio AS VARCHAR), 4) + 
				RIGHT('000' + CAST(CAST(@Nro_Ubic AS INT) AS VARCHAR), 3) +
				RIGHT('0000000' + CAST(CAST(@Lote AS VARCHAR) AS VARCHAR), 7)

	RETURN @QR
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@Evento_QR_Formato = '43')
BEGIN
	SET @QR =	RIGHT('0000000000' + CAST(CAST(@Lote AS VARCHAR) AS VARCHAR), 10) +
				RIGHT('00000' + CAST(@Id_Lista_Precio AS VARCHAR), 5) + 
				RIGHT('000' + CAST(CAST(@Nro_Ubic AS INT) AS VARCHAR), 3) +
				RIGHT('0000000000' + CAST(@Cbtes_Items_Id_Cliente AS VARCHAR), 10) + 
				RIGHT('0000000000' + CAST(@pId_Trans AS VARCHAR), 10) + 
				RIGHT('00000' + CAST(@pItem AS VARCHAR), 5)

	RETURN @QR
END

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

RETURN ISNULL(@QR, '')
END
GO


CREATE FUNCTION [dbo].[CF_SCA_IdAcceso](@pId_Controlador	SMALLINT)
RETURNS SMALLINT
AS
BEGIN
DECLARE @Id_Acceso		SMALLINT

SET @Id_Acceso = (SELECT ISNULL(Id_Acceso, 0) FROM Cd_Controladores WHERE Id_Controlador = @pId_Controlador)

RETURN ISNULL(@Id_Acceso, 0)

END
GO


CREATE FUNCTION [dbo].[CF_SCA_IdControlador](@pNro_Serie VARCHAR(30), @pIPServidor VARCHAR(15))
RETURNS SMALLINT
AS
BEGIN
DECLARE @Id_Controlador		SMALLINT
DECLARE @IPServerFormateada	VARCHAR(15)

SET @IPServerFormateada = (dbo.CF_SCA_FormatoIP(@pIPServidor))

SET @Id_Controlador =	(SELECT MAX(ISNULL(CC.Id_Controlador, 0)) 
						FROM Cd_Controladores CC, CD_Accesos CA, CD_Servers CS
						WHERE 
						CC.Id_Acceso = CA.Id_Acceso
						AND CA.Pc_Server = CS.Pc_Server
						AND dbo.CF_SCA_FormatoIP(CS.Ip) = @IPServerFormateada
						AND CC.Nro_Serie = @pNro_Serie)					

RETURN ISNULL(@Id_Controlador, 0)

END
GO


CREATE FUNCTION [dbo].[CF_SCA_Id_Cliente]		(@pTipo_Validacion	CHAR(1),
											@pTag				VARCHAR(30),	/*Credencial MiFare / Wiegand*/
											@pDoc				BIGINT,			/*Documento*/
											@pHue				VARCHAR(5000),	/*Huella Dactilar*/
											@pCba				VARCHAR(20),	/*Codigo de Barra*/
											@pDma				VARCHAR(5000)	/*Data Matrix*/)
RETURNS INT
AS
BEGIN
DECLARE @Id_Cliente	INT

DECLARE @Evento VARCHAR(5)
DECLARE @Ticket VARCHAR(8)

IF(@pTipo_Validacion = 'T')
BEGIN
	SET @Id_Cliente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Credencial_Nro = @pTag), 0)	
	RETURN @Id_Cliente
END

IF(@pTipo_Validacion = 'D')
BEGIN
	SET @Id_Cliente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Doc_Nro = @pDoc), 0)	
	RETURN @Id_Cliente
END

IF(@pTipo_Validacion = 'H')
BEGIN
	SET @Id_Cliente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes_HD WHERE Huella = CONVERT(VARBINARY(2000), @pHue)), 0)	
	RETURN @Id_Cliente
END

IF(@pTipo_Validacion = 'B')
BEGIN

	SET @Evento = SUBSTRING(@pCba, 1, 4)
	SET @Ticket = SUBSTRING(@pCba, 8, 7)

	SET @Id_Cliente = ISNULL(	(SELECT CI.Id_Cliente 
								FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT
								WHERE
								CB.Id_Trans = CI.Id_Trans
								AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
								AND CT.Compromete_Pedido = 1
								AND CB.Id_Lista = @Evento
								AND CI.Lote = @Ticket)
							, 0)
	RETURN @Id_Cliente
END

IF(@pTipo_Validacion = 'M')
BEGIN
	SET @Id_Cliente = 0 /*No implementado*/	
	RETURN @Id_Cliente
END

RETURN ISNULL(@Id_Cliente, 0)

END
GO


CREATE FUNCTION [dbo].[CF_SCA_IdentifIdCliente](@pDato VARCHAR(100))
RETURNS INT
AS
BEGIN
DECLARE @Id_Cliente					INT
DECLARE @Flag_Tipo_DNI				TINYINT
DECLARE @Flag_Formato_Valido_Doc	INT
DECLARE @Doc_Escaneado				VARCHAR(20)
DECLARE @Doc_Nro					BIGINT
DECLARE @Long_Dato					INT
DECLARE @Flag_Es_Numerico			TINYINT
DECLARE @DatoOriginal				VARCHAR(100)

IF EXISTS ( SELECT * FROM sysobjects WHERE id = object_id(N'dbo.CF_SCA_IdentifIdCliente_') AND type = 'FN')
BEGIN
	SET @Id_Cliente = (dbo.CF_SCA_IdentifIdCliente_(@pDato))
	RETURN ISNULL(@Id_Cliente, 0)
END

IF(ISNULL(@pDato, '') = '')
BEGIN
	SET @Id_Cliente = 0
	RETURN @Id_Cliente
END

SET @Long_Dato			= LEN(@pDato)
SET @Flag_Es_Numerico	= dbo.CF_IsNumeric(@pDato)
SET @DatoOriginal		= @pDato

IF(@Long_Dato > 60)
BEGIN
	/*
	08-08-2022: Se deja los mayores de 60 digitos que se consideren como DNI Leidos ya que los QR ahora son de 10 caracteres numericos
	
	/*QR*/
	SET @Id_Cliente = ISNULL((SELECT ISNULL(Id_Cliente, 0) FROM Clientes_Links WHERE LOWER(LTRIM(RTRIM(URL)))= LOWER(LTRIM(RTRIM(@pDato)))), 0)
	RETURN @Id_Cliente
	*/
	IF(dbo.CF_xParam('QR_Dinamico') = 1)
	BEGIN
		SET @pDato = (SELECT SUBSTRING(@pDato,1,10))
		SET @Id_Cliente = ISNULL((SELECT ISNULL(Id_Cliente, 0) FROM Clientes_Links 
									WHERE Token = LOWER(LTRIM(RTRIM(@pDato))) AND FECHA_GEN > DATEADD(MINUTE, -3, GETDATE())),0)
		IF(@Id_Cliente = 0)
		BEGIN
			SET @Id_Cliente = ISNULL((SELECT dbo.CF_IdentifDNI(@DatoOriginal)),0)
			IF(@Id_Cliente = 0)
			BEGIN
				SET @Id_Cliente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Credencial_Nro = UPPER(LTRIM(RTRIM(@DatoOriginal)))), 0)
			END
		END		
	END
	ELSE
	BEGIN
		SET @Id_Cliente = ISNULL((SELECT dbo.CF_IdentifDNI(@pDato)),0)
		IF(@Id_Cliente = 0)
		BEGIN
			SET @Id_Cliente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Credencial_Nro = UPPER(LTRIM(RTRIM(@pDato)))), 0)
		END
	END
	
	RETURN @Id_Cliente
END

IF(@Flag_Es_Numerico = 0)
BEGIN
	/*Credencial MiFare*/
	SET @Id_Cliente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Credencial_Nro = UPPER(LTRIM(RTRIM(@pDato)))), 0)
	IF(@Id_Cliente = 0)
	BEGIN
		IF(dbo.CF_xParam('QR_Dinamico') = 1)
		BEGIN
			SET @pDato = (SELECT SUBSTRING(@pDato,1,10))
			SET @Id_Cliente = ISNULL((SELECT ISNULL(Id_Cliente, 0) FROM Clientes_Links 
										WHERE Token = LOWER(LTRIM(RTRIM(@pDato))) AND FECHA_GEN > DATEADD(MINUTE, -3, GETDATE())),0)
		END
		ELSE
		BEGIN
			SET @Id_Cliente = ISNULL((SELECT dbo.CF_IdentifDNI(@pDato)),0)
			IF(@Id_Cliente = 0)
			BEGIN
				SET @Id_Cliente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Credencial_Nro = UPPER(LTRIM(RTRIM(@pDato)))), 0)
			END
		END
	END
	RETURN @Id_Cliente
END

IF(@Flag_Es_Numerico = 1)
BEGIN
	/*DNI*/
	IF(CONVERT(BIGINT, @pDato) < 3000000000)
	BEGIN
		SET @Id_Cliente = ISNULL((SELECT TOP 1 ISNULL(Id_Cliente, 0) 
												FROM Clientes C
													JOIN Clientes_Tipos T ON C.Id_Tipo_Cli = T.Id_Tipo_Cli
												WHERE Doc_Nro = CONVERT(BIGINT, @pDato)  
												ORDER BY 
														 C.Activo DESC,
													  CASE T.Flag_Tipo
														WHEN 'P' THEN 1
														WHEN 'S' THEN 2
														WHEN ''  THEN 3
														WHEN 'N' THEN 4
														ELSE 5
													  END,
														 C.Ult_Cuota_Paga DESC), 0)
		IF(@Id_Cliente = 0)
		BEGIN
			SET @Id_Cliente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Credencial_Nro = UPPER(LTRIM(RTRIM(@pDato)))), 0)
		END

		RETURN @Id_Cliente
	END
	ELSE
	BEGIN
		/*QR Intelektron Numerico de 10 caracteres que empieza con 9*/
		IF(dbo.CF_xParam('QR_Dinamico') = 1)
		BEGIN
			SET @pDato = (SELECT SUBSTRING(@pDato,1,10))
			SET @Id_Cliente = ISNULL((SELECT ISNULL(Id_Cliente, 0) FROM Clientes_Links 
										WHERE Token = LOWER(LTRIM(RTRIM(@pDato))) AND FECHA_GEN > DATEADD(MINUTE, -3, GETDATE())),0)
			IF(@Id_Cliente = 0)
			BEGIN
				SET @Id_Cliente = ISNULL((SELECT dbo.CF_IdentifDNI(@DatoOriginal)),0)
				IF(@Id_Cliente = 0)
				BEGIN
					SET @Id_Cliente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Credencial_Nro = UPPER(LTRIM(RTRIM(@DatoOriginal)))), 0)
				END
			END				
		END
		ELSE
		BEGIN
			SET @Id_Cliente = ISNULL((SELECT ISNULL(Id_Cliente, 0) FROM Clientes_Links WHERE Token = LOWER(LTRIM(RTRIM(@pDato)))), 0)
		END

		RETURN @Id_Cliente
	END
END

RETURN ISNULL(@Id_Cliente, 0)
END

--POR NRO DOC			SELECT dbo.CF_SCA_IdentifIdCliente('33554240')				RTA: 879212
--POR QR				SELECT dbo.CF_SCA_IdentifIdCliente('3475627707')			RTA: 879212
--POR DNI NUEVO			SELECT dbo.CF_SCA_IdentifIdCliente('00586082921"PAZ WERNER"FEDERICO"M"33554240"B"05-03-1988"11-03-2019"202')		RTA: 879212
--POR DNI VIEJO			SELECT dbo.CF_SCA_IdentifIdCliente('"33554240    "A"1"PAZ WERNER"FEDERICO"ARGENTINA"05-03-1988"M"18-06-2010"00013006433"7000 "18-06-2025"323"0"ILR╬ô├Â┬úÔö£┬¬01.2 C╬ô├Â┬úÔö£┬¬100614.02"UNIDAD ╬ô├Â┬╝Ôö£├ç05 ╬ô├Â┬úÔö£┬║╬ô├Â┬úÔö£┬║ S-N╬ô├Â┬úÔö£┬¬ 0040:2008::0005')   RTA: 879212
GO

