CREATE FUNCTION [dbo].[CF_SCA_TipoValidacion]	(@pTag		VARCHAR(30),	/*Credencial MiFare / Wiegand*/
											@pDoc		BIGINT,			/*Documento*/
											@pHue		VARCHAR(5000),	/*Huella Dactilar*/
											@pCba		VARCHAR(20),	/*Codigo de Barra*/
											@pDma		VARCHAR(5000)	/*Data Matrix*/)
RETURNS CHAR(1)
AS
BEGIN
DECLARE @Tipo_Validacion	CHAR(1)

IF(@pTag <> '')
BEGIN
	SET @Tipo_Validacion = 'T' /*Tag (Credencial MiFare / Wiegand)*/
	RETURN @Tipo_Validacion
END

IF(@pDoc <> 0)
BEGIN
	SET @Tipo_Validacion = 'D' /*Documento*/
	RETURN @Tipo_Validacion
END

IF(@pHue <> '')
BEGIN
	SET @Tipo_Validacion = 'H' /*Huella Dactilar*/
	RETURN @Tipo_Validacion
END

IF(@pCba <> '')
BEGIN
	SET @Tipo_Validacion = 'B' /*Codigo de Barra*/
	RETURN @Tipo_Validacion
END

IF(@pDma <> '')
BEGIN
	SET @Tipo_Validacion = 'M' /*Data Matrix*/
	RETURN @Tipo_Validacion
END

RETURN ISNULL(@Tipo_Validacion, 'N')

END
GO


CREATE FUNCTION [dbo].[CF_SCA_ValidarCategHorario](@pId_Cliente INT, @pId_Acceso SMALLINT, @pFecha DATETIME)
RETURNS SMALLINT
AS
BEGIN
DECLARE @Retorno				SMALLINT
DECLARE @DiaActual				TINYINT
DECLARE @Id_Tipo_Cli			SMALLINT

--[CD_ACCESOS_HORARIOS].[Dia] = 0 -> Domingo ,1->Lunes ....


SET @DiaActual = DATEPART(DW,@pFecha)

IF (@@DATEFIRST= 7)
   SET @DiaActual = @DiaActual - 1


IF (@DiaActual=7) 
	SET @DiaActual = 0

SET @Id_Tipo_Cli = (SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @pId_Cliente)


-------------------------------------Verifica cuando el PRODUCTO está VACIO, CATEGORIA está CARGADA
SET @Retorno = ISNULL((SELECT Id_Tipo_Cli FROM CD_ACCESOS_HORARIOS WHERE Id_Acceso = @pId_Acceso
               AND ISNULL(Id_Producto,'') = ''
               AND Id_Tipo_Cli = @Id_Tipo_Cli
               AND Dia = @DiaActual
               AND ( (Hora_Desde IS NULL AND Hora_Hasta IS NULL) OR (CAST(@pFecha AS TIME) BETWEEN CAST(Hora_Desde AS TIME) AND CAST(Hora_Hasta AS TIME)))),0)



RETURN ISNULL(@Retorno, 0)

END
GO


CREATE FUNCTION [dbo].[CF_SCA_ValidarContratosTipos](@pId_Cliente INT, @pId_Acceso SMALLINT, @pFecha DATETIME)
RETURNS INT
AS
BEGIN
DECLARE @ContratoHabilitado INT

SET @ContratoHabilitado = 0

SET @ContratoHabilitado = ISNULL((SELECT MAX(CO.Id_Contrato)
								FROM Contratos CO, CD_Accesos_Cont_Tipos CACT
								WHERE 
								CO.Id_Cliente = @pId_Cliente
								AND CO.Id_Tipo_Con = CACT.Id_Tipo_Con
								--AND CO.Activo = 1 --22/01/2019 se comenta porque se controla solo por las fechas desde y hasta
								AND CO.Id_Tipo_Con IN (SELECT Id_Tipo_Con FROM CD_Accesos_Cont_Tipos WHERE Id_Acceso = @pId_Acceso)
								AND ISNULL(CACT.Flag_Habilitado, 'H') = 'H'
								AND CO.Fecha_Desde < (@pFecha + 1)
								AND (CO.Fecha_Hasta IS NULL OR CO.Fecha_Hasta >= @pFecha))
								,0)


RETURN ISNULL(@ContratoHabilitado, 0)

END
GO


CREATE FUNCTION [dbo].[CF_SCA_ValidarContratosTiposRechazos](@pId_Cliente INT, @pId_Acceso SMALLINT, @pFecha DATETIME)
RETURNS INT
AS
BEGIN
DECLARE @ContratoRechazado	INT

SET @ContratoRechazado = 0

SET @ContratoRechazado = ISNULL((SELECT MAX(CO.Id_Contrato)
								FROM Contratos CO, CD_Accesos_Cont_Tipos CACT
								WHERE 
								CO.Id_Cliente = @pId_Cliente
								AND CO.Id_Tipo_Con = CACT.Id_Tipo_Con
								AND CO.Activo = 1 
								AND CO.Id_Tipo_Con IN (SELECT Id_Tipo_Con FROM CD_Accesos_Cont_Tipos WHERE Id_Acceso = @pId_Acceso)
								AND ISNULL(CACT.Flag_Habilitado, 'H') = 'R'
								AND CO.Fecha_Desde < (@pFecha + 1)
								AND (CO.Fecha_Hasta IS NULL OR CO.Fecha_Hasta >= @pFecha))
								,0)

RETURN ISNULL(@ContratoRechazado, 0)

END
GO


CREATE FUNCTION [dbo].[CF_SCA_ValidarEvento](@pId_Cliente INT, @pId_Acceso SMALLINT, @pFecha DATETIME)
RETURNS SMALLINT
AS
BEGIN
DECLARE @Id_Lista_Precio		SMALLINT

SET @Id_Lista_Precio = 0

SET @Id_Lista_Precio =	ISNULL((SELECT CB.Id_Lista
								FROM Cbtes_Items CI, Cbtes CB, Cbtes_Tipos CT, Clientes CL
								WHERE 
								CI.Id_Trans = CB.Id_Trans
								AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte
								AND (ISNULL(CT.Compromete_Factura, 0) = 1 OR ISNULL(CT.Compromete_Remitos, 0) = 1 OR ISNULL(CT.Compromete_Pedido, 0) = 1) --21/10/2021 Se agrego compromete Pedido
								AND CB.Id_Estado_Cbte IN (4, 2)
								AND CI.Id_Cliente = CL.Id_Cliente 
								AND CB.Id_Lista IN (SELECT Id_Lista_Precio FROM CD_Accesos_Eventos WHERE Id_Acceso = @pId_Acceso)
								AND CI.Fecha_QA <= @pFecha			--06/10/2021 Se reemplazo el < por <=
								AND CI.Fecha_Venc >= @pFecha
								AND CL.Id_Cliente = @pId_Cliente)
								, 0)

RETURN ISNULL(@Id_Lista_Precio, 0)
END
