CREATE FUNCTION [dbo].[CF_SCA_ValidarUltCuotaPaga](@pId_Cliente INT, @pId_Acceso SMALLINT, @pFecha DATETIME)
RETURNS TINYINT
AS
BEGIN
DECLARE @Flag_UCP				TINYINT
DECLARE @Ult_Cuota_Paga			DATETIME
DECLARE @Flag_Ult_Cuota_Paga	TINYINT
DECLARE @Dias_Gracia			INT
DECLARE @Meses_Gracia			SMALLINT

SET @Flag_UCP				= 0
SET @Flag_Ult_Cuota_Paga	= (SELECT ISNULL(Flag_Ult_Cuota_Paga, 0) FROM CD_Accesos WHERE Id_Acceso = @pId_Acceso)
SET @Dias_Gracia			= (SELECT ISNULL(Dias_Gracia, 0) FROM CD_Accesos WHERE Id_Acceso = @pId_Acceso)
SET @Meses_Gracia           = (SELECT ISNULL(Meses_Gracia, 0) FROM CD_Accesos WHERE Id_Acceso = @pId_Acceso)

IF (@Flag_Ult_Cuota_Paga <> 0)
BEGIN
    SET @Ult_Cuota_Paga = (SELECT ISNULL(Ult_Cuota_Paga, '19000101') FROM Clientes WHERE Id_Cliente = @pId_Cliente)

    -- 1) sumar meses
    DECLARE @fecha_mas_meses date = DATEADD(MONTH, @Meses_Gracia, CONVERT(date, @Ult_Cuota_Paga))

    -- 2) llevar al primer dia de ese mes
    DECLARE @primer_dia_mes date = DATEADD(DAY, 1, EOMONTH(@fecha_mas_meses, -1))
    -- (equivalente: DATEFROMPARTS(YEAR(@fecha_mas_meses), MONTH(@fecha_mas_meses), 1))

    -- 3) sumar dias de gracia
    DECLARE @fecha_limite date = DATEADD(DAY, @Dias_Gracia, @primer_dia_mes)

    -- 4) comparar contra @pFecha
    SET @Flag_UCP = CASE WHEN @fecha_limite < CONVERT(date, @pFecha) THEN 0 ELSE 1 END

    RETURN @Flag_UCP
END
ELSE
BEGIN
    SET @Flag_UCP = 0 
    RETURN @Flag_UCP
END

    RETURN ISNULL(@Flag_UCP, 0)
END

-- SELECT dbo.CF_SCA_ValidarUltCuotaPaga (872811, 22, GETDATE())

/*
--ULT_CUOTA_PAGA			Id_Cliente	Razon_Social
--2025-09-01 00:00:00.000	872811		VAZ CLAUDIO    --> al dia 9/10/25 esta habilitado
--2025-08-01 00:00:00.000	916661	    PRUEBA PRUEBA  --> al dia 9/10/25 NO esta habilitado
--2025-08-31 00:00:00.000	916661	    PRUEBA PRUEBA  --> al dia 9/10/25 NO esta habilitado
--2025-09-01 00:00:00.000	916661	    PRUEBA PRUEBA  --> al dia 10/10/25 esta habilitado
--2025-09-01 00:00:00.000	916661	    PRUEBA PRUEBA  --> al dia 11/10/25 esta habilitado
--2025-09-01 00:00:00.000	916661	    PRUEBA PRUEBA  --> al dia 12/10/25 NO esta habilitado

/*
Con UCP = 01/09/2025, Meses_Gracia = 1 y Dias_Gracia = 10:

UCP + 1 mes -> 01/10/2025

Primer dia de ese mes -> 01/10/2025

10 días -> 11/10/2025

La funcion habilita hasta e incluyendo el 11/10/2025.
El 12/10/2025 ya es posterior a la fecha limite, por eso NO habilita
*/

SELECT dbo.CF_SCA_ValidarUltCuotaPaga (916661, 22/*ACCESO CS BIOESTAR*/, '20251012')

*/
GO


CREATE FUNCTION [dbo].[CF_SCA_ValidarVencimientosPersona](@pId_Cliente INT, @pId_Acceso SMALLINT, @pFecha DATETIME)
RETURNS VARCHAR(10)
AS
BEGIN
DECLARE @Id_Tipo_Venc_Vencido				VARCHAR(10)
DECLARE @Id_Tipo_Venc_No_Existe				VARCHAR(10)

SET @Id_Tipo_Venc_Vencido = ''


SET @Id_Tipo_Venc_No_Existe = ISNULL((SELECT MAX(Id_Tipo_Venc) FROM CD_Accesos_Venc WHERE Id_Acceso = @pId_Acceso AND Id_Tipo_Venc NOT IN (SELECT DISTINCT Id_Tipo_Venc FROM Clientes_Venc WHERE Id_Cliente = @pId_Cliente)), '')

IF(@Id_Tipo_Venc_No_Existe <> '')
BEGIN
	SET @Id_Tipo_Venc_Vencido = @Id_Tipo_Venc_No_Existe
	RETURN @Id_Tipo_Venc_Vencido
END


SET @Id_Tipo_Venc_Vencido = ISNULL((SELECT MAX(CV.Id_Tipo_Venc)
									FROM Clientes_Venc CV, CD_Accesos_Venc CAV
									WHERE 
									CV.Id_Tipo_Venc = CAV.Id_Tipo_Venc
									AND CAV.Id_Acceso = @pId_Acceso
									AND CV.Id_Cliente = @pId_Cliente
									AND CONVERT(DATE, ISNULL(CV.Fecha, '19000101')) < CONVERT(DATE, @pFecha))
								,'')

RETURN ISNULL(@Id_Tipo_Venc_Vencido, '')

END
GO


