CREATE FUNCTION [dbo].[CF_Seg_User_Validar] (@Id_Usuario SMALLINT,@Equate VARCHAR(30) )
RETURNS TINYINT
AS

BEGIN
DECLARE @Retorno TINYINT
		,@DoorNo  SMALLINT
		,@DenyFlag TINYINT

IF (@Id_Usuario = -1)   --Si existe NO tiene permismo
	RETURN 1

SET @DoorNo = ISNULL((SELECT TOP 1 [No] FROM Seg_Door WHERE Equate = @Equate),'')

IF (@DoorNo = '')
	RETURN 0

--busco negacion individual
SET @DenyFlag = (SELECT TOP 1DenyFlag FROM Seg_Access WHERE DenyFlag = 1 AND DoorNo = @DoorNo AND UserNo = @Id_Usuario)
IF (@DenyFlag = 1)   --Si existe NO tiene permismo
	RETURN 0

--busco aprobacion individual
SET @DenyFlag = (SELECT TOP 1 DenyFlag FROM Seg_Access WHERE DenyFlag = 0 AND DoorNo = @DoorNo AND UserNo = @Id_Usuario)
IF (@DenyFlag = 0)   --Si existe tiene permismo
	RETURN 1

--busco negacion por grupo
SET @DenyFlag = (SELECT TOP 1 DenyFlag FROM Seg_Access WHERE DenyFlag = 1 AND DoorNo = @DoorNo 
						AND UserNo IN (SELECT UGrpNo FROM Seg_UserInGroup WHERE UserNo = @Id_Usuario)
				)
IF (@DenyFlag = 1)   --Si existe NO tiene permismo
	RETURN 0

--busco aprobacion por grupo
SET @DenyFlag = (SELECT TOP 1 DenyFlag FROM Seg_Access WHERE DenyFlag = 0 AND DoorNo = @DoorNo 
						AND UserNo IN (SELECT UGrpNo FROM Seg_UserInGroup WHERE UserNo = @Id_Usuario)
				)
IF (@DenyFlag = 0)   --Si existe NO tiene permismo
	RETURN 1


RETURN 0

END
GO


CREATE FUNCTION dbo.CF_Seg_User_Validar_Ip (@Id_Usuario SMALLINT,@Ip VARCHAR(20) )
RETURNS TINYINT
AS

BEGIN
DECLARE @Retorno TINYINT
		,@Cant  INT
		,@Flag_IP_NoFiltrar  TINYINT

IF (@Id_Usuario = -1)   --Admin entra directo
	RETURN 1

		
IF COL_LENGTH('Empresas_IP', 'IP') IS NULL 
	RETURN 1

SET @Cant = ISNULL( (SELECT COUNT(*) FROM Empresas_IP) ,0 )

IF @Cant = 0
	RETURN 1

SET @Flag_IP_NoFiltrar = ISNULL((SELECT Flag_IP_NoFiltrar FROM Seg_User S WHERE S.NO = @Id_Usuario) , 0)
IF @Flag_IP_NoFiltrar = 1
	RETURN 1

IF (SELECT 1 FROM Empresas_IP I WHERE I.Ip = @Ip) = 1
	RETURN 1


RETURN 0

END
GO



CREATE FUNCTION [dbo].[CF_Split] (@String VARCHAR(MAX), @separator VARCHAR(10))


RETURNS @rtnTable TABLE
  (
  Id INT IDENTITY(1,1),
  ColumnA VARCHAR(MAX)
  )
 AS
BEGIN
    DECLARE @position INT = 0;
    DECLARE @endAt INT = 0;
    DECLARE @tempString VARCHAR(MAX);
    
    set @String = ltrim(rtrim(@String));

    WHILE @position<=LEN(@String)
    BEGIN       
        SET @endAt = CHARINDEX(@separator,@String,@position);
        IF (@endAt=0)
        BEGIN
            INSERT INTO @rtnTable(ColumnA) SELECT SUBSTRING(@String,@position,LEN(@String)-@position + 1);
            BREAK;
        END;
        SET @tempString = SUBSTRING(LTRIM(RTRIM(@String)),@position,@endAt-@position);

        INSERT INTO @rtnTable(ColumnA) SELECT @tempString;
        SET @position=@endAt+1;
    END;
    RETURN;
END;


