CREATE  FUNCTION [dbo].[CF_TarjNevada_TX](@trans INT) 
RETURNS CHAR(69)
AS
BEGIN

DECLARE @Retorno			CHAR(69)
DECLARE @Id_Tarjeta_Nevada	VARCHAR(10)
DECLARE @Tar_Nro			VARCHAR(25)
DECLARE @Fecha_Alta			DATETIME
DECLARE @Id_Cliente			INT
DECLARE @SERPlastico		CHAR(16) /*Nro. de Tarjeta. Aig Por Tarj. Nevada*/
DECLARE @SERMonto			CHAR(12) /*Monto a Debitar. 10 Ent. 2 Dec*/
DECLARE @SERFecAlta			CHAR(6)	 /*Fec. Ingre. al Servicio. AA-MM-DD*/
DECLARE @SERLeyenda			CHAR(35) /*Descripcion Servicio. Alfanumericos*/

SET @Id_Tarjeta_Nevada = ISNULL((SELECT Valor_String FROM xParametros WHERE IdParametro = 'Id_Nevada'),'')

IF (@Id_Tarjeta_Nevada <> '')
BEGIN
	SET @Id_Cliente = (SELECT Id_Cliente FROM Cbtes WHERE Id_Trans = @trans)
	SET @Tar_Nro	= (SELECT DBO.CF_Cotiza(Tar_Nro) FROM Contratos WHERE Id_Cliente = @Id_Cliente AND Id_Tarjeta = @Id_Tarjeta_Nevada AND Activo=1)
	SET @Fecha_Alta = (SELECT Fecha_Alta FROM Contratos WHERE Id_Cliente = @Id_Cliente AND Id_Tarjeta = @Id_Tarjeta_Nevada AND Activo=1)
	
	SET @SERPlastico	=	@Tar_Nro
	SET @SERMonto		=	(SELECT RIGHT( '000000000000' + CAST(CAST((ISNULL(Imp_Total,0) + ISNULL(Saldo_Anterior,0)) * Cotizacion * 100 AS INT) AS VARCHAR), 12) 
							FROM Cbtes WHERE Id_Trans = @trans)
	SET @SERFecAlta		=	(SELECT RIGHT('00' + CAST(DATEPART(YY,@Fecha_Alta) AS VARCHAR),2) + 
							RIGHT('00' + CAST(DATEPART(mm,@Fecha_Alta) AS VARCHAR),2) + 
							RIGHT('00' + CAST(DATEPART(dd,@Fecha_Alta) AS VARCHAR),2))							
	SET @SERLeyenda		= '                                   '

	SET @Retorno		=	@SERPlastico		+ @SERMonto			+ @SERFecAlta +
							@SERLeyenda
END

RETURN ISNULL(@retorno,'')
END
GO


CREATE FUNCTION [dbo].[CF_Tarjeta_Validar] (@Id_Tarjeta VARCHAR(10),@Tar_Nro VARCHAR(50) )
RETURNS VARCHAR(100)	
AS


BEGIN


DECLARE @Descripcion		VARCHAR(100);
DECLARE @Flag_Valida_Long	TINYINT;
DECLARE @Valida_PimerDig	CHAR(9);
DECLARE @Flag_Valida_DV		TINYINT;

IF ISNUMERIC(@Tar_Nro) = 0
	SET @Tar_Nro = (Select dbo.CF_Cotiza(@Tar_Nro))


SET @Descripcion = '';

IF ISNULL(@Id_Tarjeta,'') = '' 
	RETURN @Descripcion;

SELECT @Flag_Valida_Long = Flag_Valida_Long , @Valida_PimerDig = Valida_PimerDig , @Flag_Valida_DV = Flag_Valida_DV 
	FROM Valores_Tarjetas_Cred WHERE Id_Tarjeta = @Id_Tarjeta


IF ISNULL(@Flag_Valida_Long,0) != 0
BEGIN
	IF LEN(RTRIM(LTRIM(@Tar_Nro))) <> @Flag_Valida_Long
	BEGIN
		SET @Descripcion = 'Cantidad de Digitos Invalido';
		RETURN @Descripcion;
	END
END


IF ISNULL(@Valida_PimerDig,'') != ''
BEGIN
	IF SUBSTRING(RTRIM(LTRIM(@Tar_Nro)),1,LEN(RTRIM(LTRIM(@Valida_PimerDig))))  <> SUBSTRING(RTRIM(LTRIM(@Valida_PimerDig)),1, LEN(RTRIM(LTRIM(@Valida_PimerDig))))
	BEGIN
		SET @Descripcion = 'El Nro. No Corresponde a la Tarjeta/CBU Selecionado.';
		RETURN @Descripcion;
	END
END



IF ISNULL(@Flag_Valida_DV,0) != 0
BEGIN
	IF @Flag_Valida_DV = 1
	BEGIN 
		IF ISNULL(  (SELECT dbo.SF_Tar_Validar(@Tar_Nro)) ,0 ) = 0
		BEGIN
			SET @Descripcion = 'Nro. de tarjeta invalido.';
			RETURN @Descripcion;
		END 
	END
	IF @Flag_Valida_DV = 2
	BEGIN 
		IF ISNULL(  (SELECT dbo.SF_Cbu_Validar(@Tar_Nro)) ,0 ) = 0
		BEGIN
			SET @Descripcion = 'Nro. de CBU invalido.';
			RETURN @Descripcion;
		END 
	END
END
	

RETURN @Descripcion;

END
GO




CREATE FUNCTION dbo.CF_Token(@tam SMALLINT)
RETURNS VARCHAR(1024)
AS
BEGIN

DECLARE @pos SMALLINT
	,@SourceString CHAR(62)
	,@Retorno VARCHAR(1024)
	,@Car CHAR(1)
	,@rndValue FLOAT


SET @SourceString = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'
SET @Retorno = ''

SET @pos = 1
WHILE (@pos < @tam + 1)
BEGIN
	SELECT @rndValue = rndResult FROM rndView
	SET @Car = SUBSTRING(@SourceString,CAST( ROUND(@rndValue * 62,0) AS INT),1)
	SET @Retorno = LTRIM(RTRIM(@Retorno)) + @Car
	SET @pos = @pos + 1
END

RETURN @Retorno


END
GO


CREATE FUNCTION [dbo].[CF_Traducir](@pFrase VARCHAR(4000), @pIdioma SMALLINT)
RETURNS VARCHAR(4000)
AS
BEGIN

IF ISNULL(@pIdioma,0) = 0 RETURN @pFrase 


DECLARE @Frase		VARCHAR(4000)
DECLARE @Separador	CHAR(1)
DECLARE @Palabras	TABLE	(Id INT IDENTITY(1,1),
							Data NVARCHAR(4000)) 
DECLARE @Contador		INT

SET @Frase =ISNULL((SELECT Traduccion FROM Tab_Idiomas_Trad WHERE Frase=@pFrase AND Id_Idioma=@pIdioma), '');

IF(@Frase <> '') RETURN @Frase 

IF(@Frase = '')
BEGIN
	SET @pFrase		= @pFrase
	SET @Separador	= ' '

	SET @Contador = 1
	WHILE (CHARINDEX(@Separador, @pFrase) > 0)
	BEGIN
		DECLARE @Palabra VARCHAR(4000)
		SET @Palabra = LTRIM(RTRIM(SUBSTRING(@pFrase, 1, CHARINDEX(@Separador, @pFrase) - 1)))
    
		-- Traducir cada palabra antes de insertarla
		SET @Palabra = ISNULL((
			SELECT Traduccion FROM Tab_Idiomas_Trad 
			WHERE Frase = @Palabra AND Id_Idioma = @pIdioma
		), @Palabra)

		INSERT INTO @Palabras (Data) SELECT @Palabra

		SET @pFrase   = SUBSTRING(@pFrase, CHARINDEX(@Separador, @pFrase) + 1, LEN(@pFrase))
		SET @Contador = @Contador + 1
	END

	SET @pFrase = ISNULL((SELECT Traduccion FROM Tab_Idiomas_Trad WHERE Frase=@pFrase AND Id_Idioma=@pIdioma), @pFrase);


	INSERT INTO @Palabras (data)
	SELECT Data = LTRIM(RTRIM(@pFrase))


	SELECT @frase = COALESCE(@frase + ' ', '') + data  FROM @Palabras
END



RETURN LTRIM(RTRIM(@frase))
END
/*
select dbo.SF_Traduccion('administrador de socios')
*/
GO


CREATE FUNCTION [dbo].[CF_Turno_Asistencia_Validar](@pId_Cliente INT, @pId_Turno BIGINT, @pId_Sector INT)
RETURNS VARCHAR(5000)
AS
BEGIN

DECLARE @Respuesta				VARCHAR(5000) 
DECLARE @Fecha					DATETIME
DECLARE @Id_Recurso				INT 
DECLARE @Id_Sector				SMALLINT
DECLARE @Id_Sector_Deseado		SMALLINT
DECLARE @Id_Sede_deseada        SMALLINT
DECLARE @Flag_Asistencia		TINYINT
DECLARE @Horas_Asistencia		INT

DECLARE @Socio					VARCHAR(500)
DECLARE @Entrada				INT 
DECLARE @Descripcion_Sede		VARCHAR(50)
--===========================================================================================
SELECT	@Id_Recurso = ISNULL(Id_Recurso, 0),
		@Fecha		= Fecha
FROM CRM_Turnos 
WHERE 
Id_Turno = @pId_Turno

--===========================================================================================

SELECT @Id_Sector_Deseado = ISNULL(Id_Sector, 0),
	   @Flag_Asistencia   = ISNULL(Flag_Asistencia,0),
	   @Horas_Asistencia  = ISNULL(Horas_Asistencia,0)
FROM Empresas_Sedes_Sec_Recursos
WHERE
Id_Recurso = @Id_Recurso

--===========================================================================================

SELECT @Id_Sede_deseada   = ISNULL(Id_Sede, 0),
	   @Descripcion_Sede  = Descripcion
FROM Empresas_Sedes_Sectores
WHERE
Id_sector = @Id_Sector_Deseado

--===========================================================================================

SELECT @Socio = Razon_Social FROM Clientes WHERE Id_Cliente = @pId_Cliente

--===========================================================================================

IF (@Flag_Asistencia = 1 AND @Horas_Asistencia > 0)
BEGIN

	SET @Entrada = (SELECT COUNT(*) FROM CD_ES
					WHERE FECHA BETWEEN (SELECT DATEADD(HOUR,-@Horas_Asistencia,GETDATE()))
					and GETDATE()
					AND Tipo='E'
					AND Id_Cliente=@pId_Cliente)

		IF @Entrada = 0
		BEGIN
			SET @Respuesta = @Socio 
			RETURN @Respuesta
		END	

END
RETURN ISNULL(@Respuesta, '')
END
GO


CREATE FUNCTION [dbo].[CF_Turno_Destinatario] (@Id_Turno INT)
RETURNS VARCHAR(1000)
AS 
BEGIN

DECLARE @Razon_Social VARCHAR(100)
DECLARE @Razon_Sociales VARCHAR(1000)
DECLARE @Id_Cliente INT

SELECT @Razon_Social = C.Razon_Social, @Id_Cliente = T.Id_Cliente FROM CRM_Turnos T, Clientes C
WHERE C.Id_Cliente = ISNULL(T.Id_Cliente,0)
AND T.Id_Turno = @Id_Turno

IF @Id_Cliente = 0	RETURN ''



DECLARE curNombre CURSOR FOR
	SELECT ISNULL(LTRIM(RTRIM(C.Razon_Social)), '') AS Razon_Social
	FROM CRM_Turnos_Clientes TC , Clientes C 
	WHERE TC.Id_Cliente = C.Id_Cliente
	AND TC.Id_Turno = @Id_Turno 
	AND ISNULL(TC.Id_Cliente,0) <> 0

SET @Razon_Sociales=@Razon_Social

OPEN curNombre
FETCH NEXT FROM curNombre INTO @Razon_Social
WHILE @@FETCH_STATUS = 0
BEGIN
	SET @Razon_Sociales= @Razon_Sociales + ' / ' + @Razon_Social
	FETCH NEXT FROM curNombre INTO @Razon_Social
END
CLOSE curNombre
DEALLOCATE curNombre

RETURN @Razon_Sociales
END
GO



CREATE FUNCTION [dbo].[CF_Turno_Item_Paid](@pId_Cliente INT, @pId_Producto VARCHAR(14), @pFecha DATETIME, @pDias INT)
RETURNS TINYINT
AS
BEGIN
DECLARE @Flag_Item_Pagado TINYINT

DECLARE @Flag_Mes				TINYINT
DECLARE @Flag_Periodo			TINYINT
DECLARE @Flag_Existe_Producto	TINYINT
DECLARE @Flag_Existe_Cliente	TINYINT
DECLARE @Flag_PermiteProdPorPed	INT

---------------------------------------------------------------------------------------------------------------

SET @Flag_Existe_Producto = ISNULL((SELECT 1 FROM Productos WHERE Id_Producto = @pId_Producto), 0)

IF(@Flag_Existe_Producto = 0)
BEGIN
	SET @Flag_Item_Pagado = 0
	RETURN @Flag_Item_Pagado
END

---------------------------------------------------------------------------------------------------------------

SET @Flag_Existe_Cliente = ISNULL((SELECT 1 FROM Clientes WHERE Id_Cliente = @pId_Cliente), 0)

IF(@Flag_Existe_Cliente = 0)
BEGIN
	SET @Flag_Item_Pagado = 0
	RETURN @Flag_Item_Pagado
END

---------------------------------------------------------------------------------------------------------------

SELECT  
@Flag_Mes		= ISNULL(Flag_Mes, 0),
@Flag_Periodo	= ISNULL(Flag_Periodo, 0)
FROM Productos
WHERE
Id_Producto = @pId_Producto

---------------------------------------------------------------------------------------------------------------

IF (@Flag_Mes = 0 AND @Flag_Periodo = 0) --No controla ni mes ni periodo, con que alguna vez lo haya pagado esta ok
BEGIN	
	SET @Flag_Item_Pagado = (SELECT MAX(1)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND ISNULL(CB.Id_Tipo_Cbte, '') = CT.Id_Tipo_Cbte
							AND ISNULL(CT.Compromete_Factura, 0) IN (1)
							AND ISNULL(CI.Id_Cliente, 0) = @pId_Cliente
							AND LTRIM(RTRIM(ISNULL(CI.Id_Producto, ''))) = LTRIM(RTRIM(@pId_Producto))
							AND ((ISNULL(CB.Id_Estado_Cbte, 0) = 2) OR (ISNULL(CB.Id_Estado_Cbte, 0) IN (1, 4) AND ISNULL(CI.Imp_Final, 0) = 0))
							)
	RETURN ISNULL(@Flag_Item_Pagado, 0)
END

---------------------------------------------------------------------------------------------------------------

IF (@Flag_Mes = 1) --Controla mes tiene prioridad por sobre Periodo
BEGIN	
	SET @Flag_Item_Pagado = (SELECT MAX(1)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND ISNULL(CB.Id_Tipo_Cbte, '') = CT.Id_Tipo_Cbte
							AND ISNULL(CT.Compromete_Factura, 0) IN (1)
							AND ISNULL(CI.Id_Cliente, 0) = @pId_Cliente
							AND LTRIM(RTRIM(ISNULL(CI.Id_Producto, ''))) = LTRIM(RTRIM(@pId_Producto))
							AND ((ISNULL(CB.Id_Estado_Cbte, 0) = 2) OR (ISNULL(CB.Id_Estado_Cbte, 0) IN (1, 4) AND ISNULL(CI.Imp_Final, 0) = 0))
							AND CONVERT(DATE,dbo.CF_EOMONTH(CI.Fecha_QA)+@pDias)>= CONVERT(DATE, @pFecha)
							)

	RETURN ISNULL(@Flag_Item_Pagado, 0)
END

---------------------------------------------------------------------------------------------------------------

IF (@Flag_Periodo = 1)
BEGIN	
	SET @Flag_Item_Pagado = (SELECT MAX(1)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND ISNULL(CB.Id_Tipo_Cbte, '') = CT.Id_Tipo_Cbte
							AND ISNULL(CT.Compromete_Factura, 0) IN (1)
							AND ISNULL(CI.Id_Cliente, 0) = @pId_Cliente
							AND LTRIM(RTRIM(ISNULL(CI.Id_Producto, ''))) = LTRIM(RTRIM(@pId_Producto))
							AND ((ISNULL(CB.Id_Estado_Cbte, 0) = 2) OR (ISNULL(CB.Id_Estado_Cbte, 0) IN (1, 4) AND ISNULL(CI.Imp_Final, 0) = 0))
							AND CONVERT(DATE, ISNULL(CI.Fecha_QA, '19000101'))  <= CONVERT(DATE, @pFecha)
							AND DATEADD(DAY,@pDias,CONVERT(DATE, ISNULL(CI.Fecha_Venc, '19000101'))) >= CONVERT(DATE, @pFecha)
							)

	RETURN ISNULL(@Flag_Item_Pagado, 0)
END

---------------------------------------------------------------------------------------------------------------

RETURN ISNULL(@Flag_Item_Pagado, 0)
END
GO


CREATE FUNCTION [dbo].[CF_Turno_Producto_Cobrar](@pId_Recurso_Horario INT, @pId_Sector_Turno INT, @pId_Recurso INT)
RETURNS VARCHAR(14) 
AS
BEGIN

DECLARE @Respuesta  VARCHAR(14)

SET @Respuesta =''

IF (@pId_Sector_Turno<>0)
BEGIN
	SET @Respuesta = (SELECT top 1 Id_Producto FROM Empresas_Sedes_Sec_Turnos WHERE Id_Sector_Turno=@pId_Sector_Turno)
END

IF (ISNULL(@Respuesta,'')='')
BEGIN
	SET @Respuesta = (SELECT top 1 Id_Producto FROM Empresas_Sedes_Sec_Recuros_Horarios WHERE Id_Recurso=@pId_Recurso) 
END

IF (ISNULL(@Respuesta,'')='')
BEGIN
	SET @Respuesta = (SELECT top 1 Id_Producto FROM Empresas_Sedes_Sectores_Prod WHERE Id_Sector=@pId_Sector_Turno) 
END

IF (ISNULL(@Respuesta,'')='')
BEGIN
	SET @Respuesta = (SELECT TOP 1 Id_Producto FROM Empresas_Sedes_Sec_Recuros_Horarios WHERE Id_Recurso_Horario=@pId_Recurso_Horario) 
END





--SET @Respuesta=''
RETURN ISNULL(@Respuesta, '')
END
