CREATE  FUNCTION [dbo].[CF_Turno_Validar](@pId_Cliente INT, @pId_Turno BIGINT, @pId_Sector INT, @pCategoria CHAR(1) )
RETURNS VARCHAR(5000)
AS
BEGIN


DECLARE @Respuesta				VARCHAR(5000) 
DECLARE @Fecha					DATETIME
DECLARE @Id_Recurso				INT 
DECLARE @Duracion_Turno			SMALLINT
DECLARE @Horas_Anticipacion		DECIMAL(8,2)
DECLARE @Cupo_Min_Indiv			INT
DECLARE @Cupo_Max_Compartido	INT
DECLARE @Cupo_Max_Indiv			INT
DECLARE @Turno_previo			BIGINT
DECLARE @Minutos_Ant_Oport		INT
DECLARE @Minutos_Post_Oport		INT
DECLARE @Id_Sector				SMALLINT
DECLARE @Fecha_Reserva_Previa	DATETIME
DECLARE @Dia_De_La_Semana		VARCHAR(50)
DECLARE @Hora_Turno				DATETIME
DECLARE @Id_Sector_Deseado		SMALLINT
DECLARE @Turno_previo_acomp     SMALLINT
DECLARE @Flag_Asistencia		TINYINT
DECLARE @Horas_Asistencia		INT
DECLARE @Entrada				INT
DECLARE @Socio					VARCHAR(500)
--===========================================================================================

IF EXISTS ( SELECT * FROM sysobjects 
			WHERE 
			id = object_id(N'dbo.CF_Turno_Validar_') 
			AND type = 'FN')
BEGIN
	/*Si existe la funci├│n personalizada CF_Turno_Validar_ utiliza esa*/
    SET @Respuesta = (dbo.CF_Turno_Validar_(@pId_Cliente, @pId_Turno,@pId_Sector,@pCategoria))
    RETURN ISNULL(@Respuesta, '')
END

--===========================================================================================

SELECT	@Id_Recurso = ISNULL(Id_Recurso, 0),
		@Fecha		= Fecha
FROM CRM_Turnos 
WHERE 
Id_Turno = @pId_Turno

SET @Dia_De_La_Semana	= DATENAME(WEEKDAY, @Fecha) --Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday o Lunes, Martes, Miercoles, Jueves, Viernes, Sabado, Domingo
SET @Hora_Turno			= CONVERT(DATETIME, CONVERT(VARCHAR(10), @Fecha, 108))

--===========================================================================================

SELECT @Id_Sector_Deseado = ISNULL(Id_Sector, 0),
	   @Flag_Asistencia   = ISNULL(Flag_Asistencia,0),
	   @Horas_Asistencia  = ISNULL(Horas_Asistencia,0)
FROM Empresas_Sedes_Sec_Recursos
WHERE
Id_Recurso = @Id_Recurso

--===========================================================================================

SELECT @Socio = Razon_Social FROM Clientes WHERE Id_Cliente = @pId_Cliente

--===========================================================================================

IF(@Id_Recurso > 0)
BEGIN

	--===========================================================================================
	
	SELECT	@Duracion_Turno			= ISNULL(Frecuencia, 0),
			@Horas_Anticipacion		= ISNULL(Horas_Anticipacion, 0),
			@Cupo_Min_Indiv			= ISNULL(Cupo_Min_Indiv, 0),
			@Cupo_Max_Compartido	= ISNULL(Cupo_Max_Compartido, 0),
			@Cupo_Max_Indiv			= ISNULL(Cupo_Max_Indiv, 0),
			@Minutos_Ant_Oport		= ISNULL(Minutos_Ant_Oport, 0),
			@Minutos_Post_Oport		= ISNULL(Minutos_Post_Oport, 0)
	FROM Empresas_Sedes_Sec_Recuros_Horarios 
	WHERE 
	Activo = 1
	AND Id_Recurso = @Id_Recurso
	AND (	(ISNULL(Lunes, 0) = 1  AND (@Dia_De_La_Semana = 'Monday'  OR  @Dia_De_La_Semana = 'Lunes'))  OR
			(ISNULL(Martes, 0) = 1 AND (@Dia_De_La_Semana = 'Tuesday' OR  @Dia_De_La_Semana = 'Martes')) OR
			(ISNULL(Miercoles, 0) = 1 AND (@Dia_De_La_Semana = 'Wednesday' OR @Dia_De_La_Semana = 'Miercoles')) OR
			(ISNULL(Jueves, 0) = 1  AND (@Dia_De_La_Semana = 'Thursday' OR  @Dia_De_La_Semana = 'Jueves')) OR
			(ISNULL(Viernes, 0) = 1 AND (@Dia_De_La_Semana = 'Friday' OR @Dia_De_La_Semana = 'Viernes')) OR
			(ISNULL(Sabado, 0) = 1  AND (@Dia_De_La_Semana = 'Saturday'  OR @Dia_De_La_Semana = 'Sabado')) OR
			(ISNULL(Domingo, 0) = 1 AND (@Dia_De_La_Semana = 'Sunday' OR @Dia_De_La_Semana = 'Domingo'))
		)
	AND Hora_Inicio <= @Hora_Turno
	AND Hora_Fin >= @Hora_Turno
	
	--===========================================================================================
	
	/*Revisa si tiene un turno reservado para el mismo sector a la misma hora que solicita el nuevo */
	SET @Turno_previo = (SELECT MIN(T.Id_Turno)
						FROM CRM_Turnos T 
						WHERE 
						T.Id_Cliente = @pId_Cliente 
						AND Fecha = @Fecha
						)
						
	IF(@Turno_previo > 0)
	BEGIN
		SET @Respuesta = 'Ya posee una reserva para el mismo dia y horario.'
		RETURN @Respuesta
	END
						
	--===========================================================================================
						
	IF (@Minutos_Ant_Oport <> 0 OR @Minutos_Post_Oport <> 0) 
		AND GETDATE() >= DATEADD(MINUTE, @Minutos_Ant_Oport*-1, @Fecha) 
		AND GETDATE() <= DATEADD(MINUTE, @Minutos_Post_Oport, @Fecha)
	BEGIN
		SET @Respuesta = ''
		RETURN @Respuesta
	END

	--===========================================================================================
	
	IF DATEADD(hh, @Horas_Anticipacion, GETDATE()) > @Fecha 
	BEGIN
		SET @Respuesta = 'No es posible tomar la reserva con esta anticipaci├│n'
		RETURN @Respuesta
	END
	
	--===========================================================================================
	
	--busqueda de turnos previos en misma SEDE.
	SET @Turno_previo = (SELECT MIN(T.Id_Turno) --COUNT(*) 
						FROM CRM_Turnos T 
						WHERE 
						T.Id_Cliente = @pId_Cliente 
						AND GETDATE() <= DATEADD(MINUTE, @Duracion_Turno, @Fecha)
						AND Id_Recurso IN (SELECT Id_Recurso FROM Empresas_Sedes_Sec_Recursos WHERE Id_Sector = @Id_Sector_Deseado))

	IF (@Turno_previo = 0)
	BEGIN
		SET @Turno_previo = (SELECT MIN(T.Id_Turno) --COUNT(*) 
							FROM CRM_Turnos T, CRM_Turnos_Clientes TC 
							WHERE 
							TC.Id_Turno = T.Id_Turno
							AND TC.Id_Cliente = @pId_Cliente 
							AND GETDATE() <= DATEADD(MINUTE, @Duracion_Turno, @Fecha)
							AND Id_Recurso IN (SELECT Id_Recurso FROM Empresas_Sedes_Sec_Recursos WHERE Id_Sector = @Id_Sector_Deseado))
	END

	IF (@Turno_previo = 0)
	BEGIN
		SET @Respuesta = ''
	END
	ELSE
	BEGIN
		SELECT
		@Fecha_Reserva_Previa = Fecha
		FROM CRM_Turnos
		WHERE
		Id_Turno = @Turno_previo
		
		SET @Respuesta = 'Ya posee una reserva previa el: '+  CONVERT(VARCHAR(10), @Fecha_Reserva_Previa, 103) + ' ' + CONVERT(VARCHAR(5), @Fecha_Reserva_Previa, 114) 
	END


END
RETURN ISNULL(@Respuesta, '')
END
GO

CREATE FUNCTION [dbo].[CF_Turno_Validar_](@pId_Cliente INT, @pId_Turno BIGINT, @pId_Sector INT, @pCategoria CHAR(1))
RETURNS VARCHAR(5000)
AS
BEGIN

DECLARE @Respuesta				VARCHAR(5000) 
DECLARE @Fecha					DATETIME
DECLARE @Id_Recurso				INT 
DECLARE @Duracion_Turno			SMALLINT
DECLARE @Horas_Anticipacion		DECIMAL(8,2)
DECLARE @Cupo_Min_Indiv			INT
DECLARE @Cupo_Max_Compartido	INT
DECLARE @Cupo_Max_Indiv			INT
DECLARE @Turno_previo			BIGINT
DECLARE @Minutos_Ant_Oport		INT
DECLARE @Minutos_Post_Oport		INT
DECLARE @Id_Sector				SMALLINT
DECLARE @Fecha_Reserva_Previa	DATETIME
DECLARE @Dia_De_La_Semana		VARCHAR(50)
DECLARE @Hora_Turno				DATETIME
DECLARE @Id_Sector_Deseado		SMALLINT
DECLARE @Id_Sede_deseada        SMALLINT
DECLARE @Turno_previo_acomp     SMALLINT
DECLARE @Vencimiento			INT
DECLARE @Id_Producto			VARCHAR(50)
DECLARE @Habilitado				INT
DECLARE @Fecha_Venc             DATETIME
DECLARE @Id_Tipo_Venc			VARCHAR (10)
DECLARE @Flag_Producto_Valida	TINYINT
	
--===========================================================================================

SELECT	@Id_Recurso = ISNULL(Id_Recurso, 0),
		@Fecha		= Fecha
FROM CRM_Turnos 
WHERE 
Id_Turno = @pId_Turno

SET @Dia_De_La_Semana	= DATENAME(WEEKDAY, @Fecha) --Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday o Lunes, Martes, Miercoles, Jueves, Viernes, Sabado, Domingo
SET @Hora_Turno			= CONVERT(DATETIME, CONVERT(VARCHAR(10), @Fecha, 108))

--===========================================================================================

SELECT @Id_Sector_Deseado = ISNULL(Id_Sector, 0)
FROM Empresas_Sedes_Sec_Recursos
WHERE
Id_Recurso = @Id_Recurso

--===========================================================================================
SELECT @Id_Sede_deseada   = ISNULL(Id_Sede, 0)
FROM Empresas_Sedes_Sectores
WHERE
Id_sector = @Id_Sector_Deseado


--===========================================================================================

---====================================== Apto médico =======================================
	SELECT @Id_Tipo_Venc= ISNULL(Id_Tipo_Venc, '') 
	FROM Empresas_Sedes_Sectores_Venc
	WHERE
	Id_Sector =  @Id_Sector_Deseado
	
	SET @Fecha_Venc= (SELECT ISNULL(Fecha,'19900101') FROM clientes_venc 
						WHERE id_tipo_venc=@Id_Tipo_Venc AND id_cliente=@pId_Cliente)
	IF (@Fecha_Venc< GETDATE())
	BEGIN
	SET @Respuesta = 'Posee Certificado Aptitud Física Vencido'
	RETURN @Respuesta
	END
	 
	--===========================================================================================
IF(@Id_Recurso > 0)
BEGIN

	--===========================================================================================
	
	SELECT	@Duracion_Turno			= ISNULL(Frecuencia, 0),
			@Horas_Anticipacion		= ISNULL(Horas_Anticipacion, 0),
			@Cupo_Min_Indiv			= ISNULL(Cupo_Min_Indiv, 0),
			@Cupo_Max_Compartido	= ISNULL(Cupo_Max_Compartido, 0),
			@Cupo_Max_Indiv			= ISNULL(Cupo_Max_Indiv, 0),
			@Minutos_Ant_Oport		= ISNULL(Minutos_Ant_Oport, 0),
			@Minutos_Post_Oport		= ISNULL(Minutos_Post_Oport, 0)
	FROM Empresas_Sedes_Sec_Recuros_Horarios 
	WHERE 
	Activo = 1
	AND Id_Recurso = @Id_Recurso
	AND (	(ISNULL(Lunes, 0) = 1  AND (@Dia_De_La_Semana = 'Monday'  OR  @Dia_De_La_Semana = 'Lunes'))  OR
			(ISNULL(Martes, 0) = 1 AND (@Dia_De_La_Semana = 'Tuesday' OR  @Dia_De_La_Semana = 'Martes')) OR
			(ISNULL(Miercoles, 0) = 1 AND (@Dia_De_La_Semana = 'Wednesday' OR @Dia_De_La_Semana = 'Miercoles' OR @Dia_De_La_Semana = 'Mi'+ CHAR(233) +'rcoles')) OR
			(ISNULL(Jueves, 0) = 1  AND (@Dia_De_La_Semana = 'Thursday' OR  @Dia_De_La_Semana = 'Jueves')) OR
			(ISNULL(Viernes, 0) = 1 AND (@Dia_De_La_Semana = 'Friday' OR @Dia_De_La_Semana = 'Viernes')) OR
			(ISNULL(Sabado, 0) = 1  AND (@Dia_De_La_Semana = 'Saturday'  OR @Dia_De_La_Semana = 'Sabado' OR  @Dia_De_La_Semana = 'S'+ CHAR(225) +'bado')) OR
			(ISNULL(Domingo, 0) = 1 AND (@Dia_De_La_Semana = 'Sunday' OR @Dia_De_La_Semana = 'Domingo'))
		)
	AND Hora_Inicio <= @Hora_Turno
	AND Hora_Fin >= @Hora_Turno
	
	--===========================================================================================
		/*Revisa si tiene un turno reservado para el mismo dia y hora que solicita el nuevo */
	SET @Turno_previo = (SELECT MIN(T.Id_Turno)
						FROM CRM_Turnos T 
						WHERE 
						T.Id_Cliente = @pId_Cliente 
						AND convert(varchar,fecha,103)  = convert(varchar,@Fecha,103)
						AND T.Id_Recurso=@Id_Recurso
						)
						
	IF(@Turno_previo > 0)
	BEGIN
		SET @Respuesta = 'Ya posee una reserva para el mismo dia y horario de la misma actividad.'
		RETURN @Respuesta
	END
	

			
	--===========================================================================================

						
	IF (@Minutos_Ant_Oport <> 0 OR @Minutos_Post_Oport <> 0) 
		AND GETDATE() >= DATEADD(MINUTE, @Minutos_Ant_Oport*-1, @Fecha) 
		AND GETDATE() <= DATEADD(MINUTE, @Minutos_Post_Oport, @Fecha)
	BEGIN
		SET @Respuesta = ''
		RETURN @Respuesta
	END

	--===========================================================================================
	
	IF DATEADD(hh, @Horas_Anticipacion, GETDATE()) > @Fecha 
	BEGIN
		SET @Respuesta = 'No es posible tomar la reserva con esta anticipación.' + ' - ' + CONVERT (VARCHAR(50),  DATEADD(hh, @Horas_Anticipacion, GETDATE())) + ' - ' + CONVERT (VARCHAR(50), @Fecha)
		RETURN @Respuesta
	END
	
	--===========================================================================================

/*Revisa si tiene un turno reservado para el mismo dia en la misma SEDE */
	SET @Turno_previo = (SELECT MIN(T.Id_Turno)
						FROM CRM_Turnos T 
						WHERE 
						T.Id_Cliente = @pId_Cliente 
						AND CONVERT (DATE, Fecha)= CONVERT (DATE, @Fecha)
						AND Id_Recurso =@Id_Recurso )
						
	IF(@Turno_previo > 0)
	BEGIN
		SET @Respuesta = 'Ya posee una reserva para el mismo dia y sector.'
		RETURN @Respuesta
	END
	
		--===========================================================================================					
	--busqueda de turnos previos en misma SEDE.

	SET @Turno_previo = 0
	SET @Turno_previo = (SELECT COUNT(*) 
						FROM CRM_Turnos T 
						WHERE 
						T.Id_Cliente = @pId_Cliente 
						AND GETDATE() <= DATEADD(MINUTE, @Duracion_Turno, @Fecha)
						AND t.fecha >  GETDATE()
						AND Id_Recurso in (SELECT id_recurso FROM Empresas_Sedes_Sec_Recursos WHERE id_sector in
						                                     (SELECT id_Sector FROM Empresas_Sedes_Sectores WHERE id_sede=@Id_Sede_deseada))
															 )

		SET @Turno_previo_acomp = (SELECT COUNT(*) 
							FROM CRM_Turnos T, CRM_Turnos_Clientes TC 
							WHERE 
							TC.Id_Turno = T.Id_Turno
							AND TC.Id_Cliente = @pId_Cliente 
							AND GETDATE() <= DATEADD(MINUTE, @Duracion_Turno, @Fecha)
							AND T.fecha >  GETDATE()
								AND Id_Recurso in (SELECT id_recurso FROM Empresas_Sedes_Sec_Recursos WHERE id_sector in
						                                     (SELECT id_Sector FROM Empresas_Sedes_Sectores WHERE id_sede=@Id_Sede_deseada))
							)
	/*Acumula turnos del socio tanto como titular y si tiene turno como acompañante*/
	SET @Turno_previo = (@Turno_previo +@Turno_previo_acomp)
    
	 IF (@Turno_previo < 2)
	BEGIN
		SET @Respuesta = ''
	END
	ELSE
	BEGIN
		/*SELECT
		@Fecha_Reserva_Previa = Fecha
		FROM CRM_Turnos
		WHERE
		Id_Turno = @Turno_previo*/
		
		SET @Respuesta = 'Ya posee ' + CONVERT (VARCHAR(10), @turno_previo) +  ' reserva/s previa/s.'
	END

	
END

--=================================Arancel de la actividad paga =============================
 SET @Flag_Producto_Valida = ISNULL((SELECT  MAX(1) FROM Empresas_Sedes_Sectores_Prod WHERE Id_Sector=@Id_Sector_Deseado),0)
	IF(@Flag_Producto_Valida=1)
	BEGIN

		SET @Respuesta='Para poder confirmar el turno debés tener el arancel de la actividad al día. Realizá el pago en la sede virtual o comunicate con la Oficina de Socios al Whatsapp 11-2266-1000'
		DECLARE cur_Valida_Turno CURSOR FOR
		SELECT ISNULL(Id_producto, '')
		FROM Empresas_Sedes_Sectores_Prod
		WHERE
		Id_Sector = @Id_Sector_Deseado


		OPEN cur_Valida_Turno
		FETCH NEXT FROM cur_Valida_Turno INTO @Id_Producto
		WHILE @@FETCH_STATUS = 0
		BEGIN

		SET @Habilitado= dbo.CF_Item_Paid(@pId_Cliente, @Id_Producto, @Fecha) 

			IF(@Habilitado=1)
			BEGIN
			set  @Respuesta = '' 
		
			BREAK
			END

		FETCH NEXT FROM cur_Valida_Turno INTO @Id_Producto
		END
		CLOSE cur_Valida_Turno
		DEALLOCATE cur_Valida_Turno

	RETURN @Respuesta
	END 
	 
--===========================================================================================


RETURN ISNULL(@Respuesta, '')
END
GO



CREATE FUNCTION [dbo].[CF_Turno_Validar_Producto](@pId_Cliente INT, @pId_Turno BIGINT, @pId_Sector_Turno INT )
RETURNS VARCHAR(14)
AS
BEGIN


DECLARE @Respuesta				VARCHAR(14) 
DECLARE @Fecha					DATETIME
DECLARE @Id_Recurso				INT 
DECLARE @Id_Recurso_Horario		INT 
DECLARE @Flag_Producto_Valida	INT
DECLARE @Habilitado				INT
DECLARE @Id_Sector				SMALLINT
DECLARE @Id_Producto			VARCHAR(50)
DECLARE @Id_Sector_Deseado		SMALLINT

DECLARE @Dias_Gracia			INT

--===========================================================================================
IF EXISTS ( SELECT * FROM sysobjects 
			WHERE 
			id = object_id(N'dbo.CF_Turno_Validar_Producto_') 
			AND type = 'FN')
BEGIN
	/*Si existe la funcion personalizada CF_Turno_Validar_ utiliza esa*/
    SET @Respuesta = (dbo.CF_Turno_Validar_Producto_(@pId_Cliente, @pId_Turno,@pId_Sector_Turno))
    RETURN ISNULL(@Respuesta, '')
END

--===========================================================================================
SELECT	@Id_Recurso = ISNULL(Id_Recurso, 0),
		@Fecha		= Fecha,
		@Id_Recurso_Horario = ISNULL(Id_Recurso_Horario, 0)
FROM CRM_Turnos 
WHERE 
Id_Turno = @pId_Turno

--===========================================================================================
SELECT @Id_Sector_Deseado = ISNULL(Id_Sector, 0)
FROM Empresas_Sedes_Sec_Recursos
WHERE
Id_Recurso = @Id_Recurso

--===========================================================================================
SET @Habilitado=0
IF(@Id_Sector_Deseado > 0) 
BEGIN

	/*VALIDO EL PRODUCTO DEL SECTOR TURNO Empresas_Sedes_Sec_Turnos */
	SET @Flag_Producto_Valida = ISNULL((SELECT  MAX(1) FROM Empresas_Sedes_Sec_Turnos WHERE Id_Sector=@pId_Sector_Turno),0)
	IF(@Flag_Producto_Valida=1)
	BEGIN

		
		DECLARE cur_Valida_Turno CURSOR FOR
		SELECT ISNULL(Id_producto, '')
		FROM  Empresas_Sedes_Sec_Turnos
		WHERE
		Id_Sector = @pId_Sector_Turno


		OPEN cur_Valida_Turno
		FETCH NEXT FROM cur_Valida_Turno INTO @Id_Producto
		WHILE @@FETCH_STATUS = 0
		BEGIN

		SET @Habilitado= dbo.CF_Item_Paid(@pId_Cliente, @Id_Producto, @Fecha) 

			IF(@Habilitado=1)
			BEGIN
				SET  @Respuesta = '' 
				BREAK
			END

		FETCH NEXT FROM cur_Valida_Turno INTO @Id_Producto
		END
		CLOSE cur_Valida_Turno
		DEALLOCATE cur_Valida_Turno


	END 



	/*VALIDAMOS EL PRODUCTO DEL RECURSO HORARIO*/
	
	SET @Flag_Producto_Valida = ISNULL((SELECT  MAX(1) FROM Empresas_Sedes_Sec_Recuros_Horarios WHERE Id_Recurso=@Id_Recurso),0)
	IF(@Flag_Producto_Valida=1)
	BEGIN

		
		DECLARE cur_Valida_Turno CURSOR FOR
		SELECT ISNULL(Id_producto, '')
		FROM  Empresas_Sedes_Sec_Recuros_Horarios
		WHERE
		Id_Recurso = @Id_Recurso


		OPEN cur_Valida_Turno
		FETCH NEXT FROM cur_Valida_Turno INTO @Id_Producto
		WHILE @@FETCH_STATUS = 0
		BEGIN

		SET @Habilitado= dbo.CF_Item_Paid(@pId_Cliente, @Id_Producto, @Fecha) 

			IF(@Habilitado=1)
			BEGIN
				SET  @Respuesta = '' 
				RETURN @Respuesta
			END

		FETCH NEXT FROM cur_Valida_Turno INTO @Id_Producto
		END
		CLOSE cur_Valida_Turno
		DEALLOCATE cur_Valida_Turno


	END 
	

	
		/*VALIDO EL PRODUCTO DEL SECTOR PRODUCTO Empresas_Sedes_Sectores_Prod */
	SET @Flag_Producto_Valida = ISNULL((SELECT  MAX(1) FROM Empresas_Sedes_Sectores_Prod WHERE Id_Sector=@Id_Sector_Deseado),0)
	IF(@Flag_Producto_Valida=1)
	BEGIN
		
		DECLARE cur_Valida_Turno CURSOR FOR
		SELECT ISNULL(Id_producto, '')
		FROM  Empresas_Sedes_Sectores_Prod
		WHERE
		Id_Sector = @Id_Sector_Deseado


		OPEN cur_Valida_Turno
		FETCH NEXT FROM cur_Valida_Turno INTO @Id_Producto
		WHILE @@FETCH_STATUS = 0
		BEGIN

		SET @Dias_Gracia= ISNULL((SELECT ISNULL(Dias_Gracia,0) FROM Empresas_Sedes_Sectores_Prod 
							WHERE Id_Sector=@Id_Sector_Deseado AND Id_Producto=@Id_Producto),0)

		SET @Habilitado= dbo.CF_Turno_Item_Paid(@pId_Cliente, @Id_Producto, @Fecha,@Dias_Gracia) 

			IF(@Habilitado=1)
			BEGIN
				SET  @Respuesta = '' 
				BREAK
			END

		FETCH NEXT FROM cur_Valida_Turno INTO @Id_Producto
		END
		CLOSE cur_Valida_Turno
		DEALLOCATE cur_Valida_Turno


	END 


END

	IF(@Habilitado=0)
	BEGIN
		IF (@pId_Sector_Turno!=0)	
			BEGIN
				SET @Id_Producto= dbo.CF_Turno_Producto_Cobrar(@Id_Recurso_Horario,@pId_Sector_Turno,@Id_Recurso)
			END 
			
		IF (@Id_Producto ='' AND @Id_Sector_Deseado!=0 )	
			BEGIN
				SET @Id_Producto= dbo.CF_Turno_Producto_Cobrar(@Id_Recurso_Horario,@Id_Sector_Deseado,@Id_Recurso)
			END
			
		SET @Respuesta= ISNULL(@Id_Producto,'')
	END

RETURN ISNULL(@Respuesta, '')
END
GO


CREATE FUNCTION [dbo].[CF_UCP_xCbteEspecial](@pId_Cliente INT)
RETURNS DATETIME
AS
BEGIN
DECLARE @UCP_Especial DATETIME

SET @UCP_Especial = (SELECT ISNULL(MIN(CI.Fecha_QA), '19000101')
								FROM Cbtes_Items CI, Cbtes CB, Productos PR, Cbtes_Tipos CT
								WHERE
								CB.Id_Trans = CI.Id_Trans
								AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
								AND CI.Id_Producto = PR.Id_Producto
								AND CT.Compromete_Factura IN (1)
								AND CB.Id_Estado_Cbte IN (1/*Pendiente*/)
								AND PR.Id_Familia = (DBO.CF_xParam('Fam_CuotasSoc'))
								AND CI.Id_Cliente = @pId_Cliente
								AND CB.Id_Tipo_Cbte = (DBO.CF_xParam('TipoCbteModifUCP')))
								 
RETURN ISNULL(@UCP_Especial, '19000101')
END
GO


CREATE FUNCTION dbo.CF_Ult_Cuota_Paga(@pId_Cliente INT, @pFecha DATETIME) 
RETURNS DATE
AS
BEGIN
DECLARE @Fecha_UCP					DATE
DECLARE @Tipo_Calculo				CHAR(1)		/*'V': "Mas Vieja Pagada", 'R': "Mas Reciente Pagada" */
DECLARE @Ult_Cuota_Paga				DATETIME
DECLARE @Ult_Cuota_Impaga			DATETIME
DECLARE @Fecha_Alta					DATETIME
DECLARE @Dia_Inicio_Sistema_Clever	DATE
DECLARE @Fam_CuotasSoc				INT

------------------------------------------------------------------------------------------------------------------------------------------------
/*
Tipo de Calculo cuando hay cuotas pagas y cuotas impagas:

EJ:
2/2020 Impago
3/2020 Pago

SI @Tipo_Calculo = 'V'
-----UCP: 1/2020

SI @Tipo_Calculo = 'R'
-----UCP: 3/2020
*/
SET @Tipo_Calculo = 'V' /*Mas Vieja Pagada*/

------------------------------------------------------------------------------------------------------------------------------------------------

SET @Dia_Inicio_Sistema_Clever = '20201001' /*Para importaciones de solo Deuda se considera la primer Cuota Paga el dia de puesta en Marcha de CleverSoft*/
SET @Fam_CuotasSoc = (dbo.CF_xParam('Fam_CuotasSoc'))
------------------------------------------------------------------------------------------------------------------------------------------------

SET @Ult_Cuota_Paga =(SELECT MAX(CI.Fecha_QA)
					FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
					WHERE
					CB.Id_Trans = CI.Id_Trans
					AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
					AND CI.Id_Producto = PR.Id_Producto
					AND CT.Compromete_Factura = 1
					AND (CB.Id_Estado_Cbte = 2  OR (CB.Id_Estado_Cbte = 1 AND CI.Imp_Final = 0))
					AND PR.Id_Familia = @Fam_CuotasSoc
					AND PR.Vendible = 1
					AND CI.Id_Cliente = @pId_Cliente) 

------------------------------------------------------------------------------------------------------------------------------------------------

SET @Ult_Cuota_Impaga = (SELECT MIN(CI.Fecha_QA)
						FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
						WHERE 
						CB.Id_Trans = CI.Id_Trans 						
						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte
						AND CI.Id_Producto = PR.Id_Producto
						AND CT.Compromete_Factura = 1
						AND (CB.Id_Estado_Cbte in (1,4) AND CB.Saldo <> 0) /*Se agrega saldo diferente a cero para que tome la max por los contratos que facturan en cero*/
						AND PR.Id_Familia = @Fam_CuotasSoc
						AND PR.Vendible = 1
						AND CI.Id_Cliente = @pId_Cliente)	

------------------------------------------------------------------------------------------------------------------------------------------------

/*CASO 1*/
IF(	
	(@Ult_Cuota_Paga IS NULL)				/*No tiene ninguna Factura en estado completo o pendiente con importe cero*/
	AND 
	(@Ult_Cuota_Impaga IS NULL)				/*No tiene ninguna Factura adeudada*/
)
BEGIN
	/*La fecha de ultima cuota paga se considera el dia que inicio el sistema de CleverSoft*/
	SET @Fecha_UCP = @Dia_Inicio_Sistema_Clever
	RETURN @Fecha_UCP
END

------------------------------------------------------------------------------------------------------------------------------------------------

/*CASO 2*/
IF(
	(@Ult_Cuota_Paga IS NULL)			/*No tiene ninguna Factura en estado completo o pendiente con importe cero*/
	AND 
	(@Ult_Cuota_Impaga IS NOT NULL)		/*Tiene al menos una Factura adeudada*/
)
BEGIN
	/*La fecha de ultima cuota paga se considera el mes anterior a la impaga*/
	SET @Fecha_UCP = DATEADD(MM, -1, @Ult_Cuota_Impaga)
	RETURN @Fecha_UCP
END

------------------------------------------------------------------------------------------------------------------------------------------------
	
/*CASO 3*/
IF(
	(@Ult_Cuota_Paga IS NOT NULL)		/*Tiene al menos una factura en estado completo o pendiente con importe cero*/
	AND 
	(@Ult_Cuota_Impaga IS NULL)			/*No tiene ninguna Factura adeudada*/
)
BEGIN
	/*La fecha de ultima cuota paga se considera la Fecha_QA mas reciente*/
	SET @Fecha_UCP = @Ult_Cuota_Paga
	RETURN @Fecha_UCP
END

------------------------------------------------------------------------------------------------------------------------------------------------

	
/*CASO 4*/
IF(
	(@Ult_Cuota_Paga IS NOT NULL) /*Tiene al menos una factura en estado completo o pendiente con importe cero*/
	AND 
	(@Ult_Cuota_Impaga IS NOT NULL)/*Tiene al menos una Factura adeudada*/
)
BEGIN

	IF (@Ult_Cuota_Impaga >= @Ult_Cuota_Paga) 
	BEGIN
		/*
		Caso Ejemplo:
		2/2020 Pago
		3/2020 Impago
		*/
		/*Cuota Impaga es mas reciente que la Cuota Paga*/
		/*La fecha de ultima cuota paga se considera el mes anterior a la impaga*/
		SET @Fecha_UCP = @Ult_Cuota_Paga
		RETURN @Fecha_UCP
	END
	ELSE
	BEGIN
		/*
		Caso Ejemplo:
		2/2020 Impago
		3/2020 Pago
		*/
		/*Cuota Impaga es anterior a la Cuota Paga*/		
		IF(@Tipo_Calculo = 'V' /*Mas Vieja Pagada*/)
		BEGIN
			/*La fecha de ultima cuota paga se considera la Fecha_QA mas reciente*/
			/*En Ejemplo: 1/2020*/
			SET @Fecha_UCP = DATEADD(MM, -1, @Ult_Cuota_Impaga)
			RETURN @Fecha_UCP
		END

		IF(@Tipo_Calculo = 'R' /*Mas Reciente Pagada*/)
		BEGIN
			/*La fecha de ultima cuota paga se considera la Fecha_QA mas reciente*/
			/*En Ejemplo: 3/2020*/
			SET @Fecha_UCP = @Ult_Cuota_Paga
			RETURN @Fecha_UCP
		END
	END
END

------------------------------------------------------------------------------------------------------------------------------------------------

RETURN ISNULL(@Fecha_UCP, @Dia_Inicio_Sistema_Clever)
END
GO


CREATE FUNCTION [dbo].[CF_Valida_Edad_Inscripciones](@pFecha_Nac DATETIME, @pFlag_Valida_Edad_Escolar SMALLINT, @Edad_Min SMALLINT, @Edad_Max SMALLINT)
RETURNS SMALLINT 
AS

BEGIN
DECLARE @Edad					SMALLINT
DECLARE @Respuesta				SMALLINT
DECLARE @Mes					SMALLINT
DECLARE @Dia					SMALLINT
DECLARE @Hoy					SMALLINT

SET @Edad = (DATEDIFF(yy, @pFecha_Nac,GETDATE()))
SET @Mes  = (SELECT MONTH(@pFecha_Nac))
SET @Dia  = (SELECT DAY(@pFecha_Nac))
SET @Hoy  = (SELECT MONTH(GETDATE()))

IF (@pFlag_Valida_Edad_Escolar = 1)
BEGIN
	IF (@Mes = 7 AND @Dia = 1)  
	BEGIN
		SET @Respuesta = @Edad - 1
		RETURN @Respuesta
	END

	IF (@Mes > 6)  
	BEGIN
		IF DATEPART(mm,@pFecha_Nac) <= DATEPART(mm,GETDATE()) AND DATEPART(dd,@pFecha_Nac) > DATEPART(dd,GETDATE())
		BEGIN
			SET @Respuesta = @Edad - 1
			RETURN @Respuesta 
		END	ELSE
		IF(@pFecha_Nac < GETDATE())
		BEGIN
			SET @Respuesta = @Edad   - 1 
			RETURN @Respuesta
		END
		ELSE
		BEGIN
			SET @Respuesta = @Edad
			RETURN @Respuesta
		END
	END

	IF (@Mes <= 7 /*AND  @Dia <> 1*/ /*SE COMENTA EL 12/11/2025 NO ENTRABAN LOS QUE CUMPLEN EL PRIMERO DE CADA MES ANTES DE JULIO*/) 
	BEGIN
		SET @Respuesta = @Edad
		RETURN @Respuesta
	END
END
ELSE
	SET @Respuesta = @Edad -1 --Revisar demas casos cuando no valida edad escolar que de bien la categoria 18/03/2026 Maca


RETURN ISNULL(@Respuesta, 0)
END

--SELECT DBO.CF_Valida_Edad_Inscripciones ('20170101',0,4,5)
--SELECT DBO.CF_Valida_Edad_Inscripciones ('20151126',1,6,7)
GO


CREATE FUNCTION [dbo].[CF_ValidarCUIT](@pCuit VARCHAR(19))
RETURNS TINYINT
AS

BEGIN
DECLARE @FlagDigitoVerifCorrecto	TINYINT
DECLARE @DigVerificadorOrig			CHAR(1)
DECLARE @DigVerificadorCalculado	CHAR(1)
DECLARE @SumaDigitos				INT
DECLARE @Posicion					TINYINT
DECLARE @Multiplicador				TINYINT
DECLARE @ModuloSuma					INT

/*El CUIT/CUIL consta de 11 números. 
Los 10 primeros (2 + 8) constituyen el código de identificación y el último, el 
dígito de verificación. 
Para obtener esta verificación se procede de la siguiente forma: 
A cada dígito del código, se lo multiplica por los siguientes 
números (respectivamente) 5, 4, 3, 2, 7, 6, 5, 4, 3, 2 y cada valor obtenido, 
se suma para obtener una expresión (que llamaremos "valor 1". 
A este "valor 1", se le saca el resto de la división entera a 11. 
Se obtiene de esta forma un número (del 0 al 10) (que llamamos "valor 2. Sacamos 
la diferencia entre 11 y el "valor 2", y obtenemos un valor comprendido 
entre 1 y 11 (llamémosle "valor 3&quot. Si "valor 3"=11, el código verificador es cero. 
Si "valor 3"=10, el código verificador es 9. En cualquier otro caso, 
el código verificador es "valor 3". 
Ejemplo numérico con un número de CUIT, que es 20-17254359-7. 
2 0 1 7 2 5 4 3 5 9 
x 
5 4 3 2 7 6 5 4 3 2 
------------------------------------------------ 
10 + 00 + 03 + 14 + 14 + 30 + 20 + 12 + 15 + 18 = 136 
v1 = 136 
136 mod 11 = 4 
v2 = 4 
11 - 4 = 7 
v3 = 7 => Código de verificación es siete. 
*/

SET @pCuit = REPLACE(@pCuit,'-','')

IF((LEN(@pCuit)<11) OR (LEN(@pCuit)>=12))
BEGIN
	SET @FlagDigitoVerifCorrecto = 0
	RETURN @FlagDigitoVerifCorrecto
END

SET @DigVerificadorOrig = SUBSTRING(@pCuit,11,1)

SET @SumaDigitos = 0
SET @Posicion = 0
SET @Multiplicador = 6

WHILE(@Posicion<10)
BEGIN
	SET @Posicion = @Posicion + 1
	SET @Multiplicador = @Multiplicador - 1
	
	IF(@Multiplicador = 1)
	BEGIN
		SET @Multiplicador = 7
	END
	
	SET @SumaDigitos = 	@SumaDigitos + (CONVERT(INT, SUBSTRING(@pCuit, @Posicion, 1)) * @Multiplicador)		
END

SET @ModuloSuma = @SumaDigitos % 11


SET @DigVerificadorCalculado = CONVERT(CHAR(1), (11 - @ModuloSuma))

IF(@DigVerificadorOrig = @DigVerificadorCalculado)
BEGIN
	SET @FlagDigitoVerifCorrecto = 1
END
ELSE
BEGIN
	SET @FlagDigitoVerifCorrecto = 0
END
 
RETURN @FlagDigitoVerifCorrecto

END
GO

CREATE FUNCTION CF_Valor_Descrip (
	@Id_Valor				INT,
	@Id_Moneda				CHAR(3),
	@Id_Tipo_Val			CHAR(3),
	@Descripcion			VARCHAR(100),
	@Valor_Nro				INT,
	@Id_Banco				SMALLINT,
	@Fecha_Acreditacion		DATETIME,
	@Cuit					VARCHAR(13),
	@Id_Tarjeta				VARCHAR(10),
	@Tarjeta_Lote			SMALLINT,
	@Tarjeta_Nro			VARCHAR(25),
	@Tarjeta_Vence			DATETIME,
	@Tarjeta_Cant_Cuotas	TINYINT,
	@Id_Cta_Banco			SMALLINT
	)
RETURNS VARCHAR(500)
AS
BEGIN

IF (ISNULL(@Id_Valor,0) != 0)
	SELECT 	@Id_Moneda = Id_Moneda,	
			@Id_Tipo_Val = Id_Tipo_Val,
			@Descripcion = Descripcion,			
			@Valor_Nro = Valor_Nro,
			@Id_Banco = Id_Banco,
			@Fecha_Acreditacion	= Fecha_Acreditacion,
			@Cuit = Cuit,
			@Id_Tarjeta	= Id_Tarjeta,
			@Tarjeta_Lote = Tarjeta_Lote,
			@Tarjeta_Nro = Tarjeta_Nro,
			@Tarjeta_Vence = Tarjeta_Vence,
			@Tarjeta_Cant_Cuotas = Tarjeta_Cant_Cuotas,
			@Id_Cta_Banco = Id_Cta_Banco
			FROM Valores WHERE Id_Valor = @Id_Valor



DECLARE @Retorno VARCHAR(100)
DECLARE @Descripcion_Bco VARCHAR(50)
DECLARE @Descripcion_Tar VARCHAR(50)
DECLARE @Descripcion_BcoCta VARCHAR(100)
DECLARE @Cuenta_Nro VARCHAR(50)
DECLARE @Signo CHAR(3)

SET @Descripcion_Tar = ISNULL((SELECT Descripcion FROM Valores_Tarjetas_Cred WHERE Id_Tarjeta = @Id_Tarjeta),'')
SET @Signo = ISNULL((SELECT Signo FROM Valores_Monedas WHERE Id_Moneda = @Id_Moneda),'')
SET @Descripcion_Bco = ISNULL((SELECT Descripcion FROM Bancos WHERE Id_Banco = @Id_Banco),'')
SET @Descripcion_Tar = ISNULL((SELECT Descripcion FROM Valores_Tarjetas_Cred WHERE Id_Tarjeta = @Id_Tarjeta),'')
SET @Descripcion_BcoCta = ISNULL((SELECT Descripcion FROM Bancos_Ctas WHERE Id_Cta_Banco = @Id_Cta_Banco),'')
SET @Cuenta_Nro = ISNULL((SELECT Cuenta_Nro FROM Bancos_Ctas WHERE Id_Cta_Banco = @Id_Cta_Banco),'')
	


SET @Retorno = ISNULL( LTRIM( RTRIM( (SELECT Descripcion FROM Valores_Tipos WHERE Id_Tipo_Val = @Id_Tipo_Val) )),'*')


/*e_Efectivo*/
IF @Id_Tipo_Val = 'EFE'
	SET @Retorno = LTRIM( RTRIM( @Descripcion ) )

/*e_Dif_Cam*/
IF @Id_Tipo_Val = 'DIC'
	SET @Retorno = LTRIM( RTRIM( @Retorno ))

/*e_Fac_Cre*/
IF @Id_Tipo_Val = 'FAC'
	SET @Retorno = LTRIM( RTRIM( @Retorno )) 
			+ ' Nro.:'
			+ CAST(@Valor_Nro AS VARCHAR(20)) 
			+' ' + LTRIM( RTRIM( @Descripcion ) )

/*e_Ajuste*/
IF @Id_Tipo_Val = 'AJU'
	SET @Retorno = LTRIM( RTRIM( @Descripcion ) )

/*e_Tickets*/
IF @Id_Tipo_Val = 'TIC'
	SET @Retorno = LTRIM( RTRIM( @Retorno ))+ ' ' + LTRIM( RTRIM( @Descripcion ) )

/*e_Cheque3*/
IF @Id_Tipo_Val = 'CH3'
	SET @Retorno = LTRIM( RTRIM( @Retorno ))
					+ ' ' 
					+ LTRIM( RTRIM( @Signo ) )
					+ ' ' 
					+ ' Nro.:'
					+ CAST(@Valor_Nro AS VARCHAR(20)) 
					+ ' ' 
					+ CONVERT(VARCHAR(10),@Fecha_Acreditacion,3)   --dd-mm-aa
					+ ' ' 
					+ LTRIM( RTRIM( @Descripcion_Bco ) )
					+ ' ' 
					+ LTRIM( RTRIM( @Cuit ) )
					+ ' ' 
					+ LTRIM( RTRIM( @Descripcion ) )

/*e_Tarjeta*/
IF @Id_Tipo_Val = 'TAR'
BEGIN
	SET @Retorno = LTRIM( RTRIM( @Descripcion_Tar ))
					+ ' ' 
					+ LTRIM( RTRIM( RIGHT(@Tarjeta_Nro,4) ) )	
	IF  LTRIM( RTRIM( @Tarjeta_Lote ) )	!= ''
		SET @Retorno = LTRIM( RTRIM( @Retorno ))
					+ ' ' 
					+ LTRIM( RTRIM( @Tarjeta_Lote ) )	

	IF (@Tarjeta_Vence IS NOT NULL)
		SET @Retorno = LTRIM( RTRIM( @Retorno ))+ ' ' 
					+ ' ' 
					+ CONVERT(VARCHAR(10),@Tarjeta_Vence,3)   --dd-mm-aa

	SET @Retorno = LTRIM( RTRIM( @Retorno )) 
					+ ' ' 
					+ LTRIM( RTRIM( @Descripcion ) )
END

/*e_Finan*/
IF @Id_Tipo_Val = 'FIN'
BEGIN
	SET @Retorno = LTRIM( RTRIM( @Descripcion_Tar ))
					+ ' Cant.Cuotas:' 
					+ CAST( @Tarjeta_Cant_Cuotas AS VARCHAR(10))

	IF (@Tarjeta_Vence IS NOT NULL)
		SET @Retorno = LTRIM( RTRIM( @Retorno ))+ ' ' 
					+ '   1er Vto: ' 
					+ CONVERT(VARCHAR(10),@Tarjeta_Vence,3)   --dd-mm-aa

	SET @Retorno = LTRIM( RTRIM( @Retorno )) 
					+ ' ' 
					+ LTRIM( RTRIM( @Descripcion ) )
	
	SET @Retorno = LTRIM( RTRIM( @Retorno ))+ ' ' + LTRIM( RTRIM( @Descripcion ) )
END

/*e_Cupon*/
IF @Id_Tipo_Val = 'CUP'
BEGIN
	SET @Retorno = LTRIM( RTRIM( @Descripcion_Tar ))
					+ ' ' 
					+ LTRIM( RTRIM(@Tarjeta_Nro ) )	

	IF  LTRIM( RTRIM( @Tarjeta_Lote ) )	!= ''
		SET @Retorno = LTRIM( RTRIM( @Retorno ))
					+ ' Lote: ' 
					+ LTRIM( RTRIM( @Tarjeta_Lote ) )	

	IF (@Tarjeta_Vence IS NOT NULL)
		SET @Retorno = LTRIM( RTRIM( @Retorno ))+ ' ' 
					+ ' ' 
					+ CONVERT(VARCHAR(10),@Tarjeta_Vence,3)   --dd-mm-aa

	SET @Retorno = LTRIM( RTRIM( @Retorno )) 
					+ ' ' 
					+ LTRIM( RTRIM( @Descripcion ) )
END

/*e_ChequeProp*/
IF @Id_Tipo_Val = 'CHP'
	SET @Retorno = LTRIM( RTRIM( @Signo ) )
					+ ' ' 
					+ LTRIM( RTRIM( @Retorno ))
					+ ' ' 
					+ ' Nro.:'
					+ CAST(@Valor_Nro AS VARCHAR(20)) 
					+ ' ' 
					+ CONVERT(VARCHAR(10),@Fecha_Acreditacion,3)   --dd-mm-aa
					+ ' ' 
					+ LTRIM( RTRIM( @Descripcion_Bco ) )
					+ ' ' 
					+ LTRIM( RTRIM( @Descripcion ) )

/*e_Depositos*/
IF @Id_Tipo_Val = 'DB'
	SET @Retorno = LTRIM( RTRIM( @Signo ) )
					+ ' ' 
					+ LTRIM( RTRIM( @Retorno ))
					+ ' ' 
					+ ' Cuenta:'
					+ CAST(@Cuenta_Nro AS VARCHAR(20)) 
					+ ' Fecha: ' 
					+ CONVERT(VARCHAR(10),@Fecha_Acreditacion,3)   --dd-mm-aa
					+ ' ' 
					+ LTRIM( RTRIM( @Descripcion_Bco ) )
					+ ' ' 
					+ LTRIM( RTRIM( @Descripcion ) )


/*e_Cta_Personal*/
IF @Id_Tipo_Val = 'CTA'
	SET @Retorno = LTRIM( RTRIM( @Signo ) )
					+ ' ' 
					+ LTRIM( RTRIM( @Retorno ))
					+ ' ' 
					+ ' Cuenta:'
					+ CAST(@Cuenta_Nro AS VARCHAR(20)) 
					+ ' Fecha' 
					+ CONVERT(VARCHAR(10),@Fecha_Acreditacion,3)   --dd-mm-aa
					+ ' ' 
					+ LTRIM( RTRIM( @Descripcion_Bco ) )
					+ ' ' 
					+ LTRIM( RTRIM( @Descripcion ) )


RETURN RTRIM(LTRIM(SUBSTRING(@Retorno,1,100)))
END
GO


CREATE FUNCTION [dbo].[CF_VisaNet_UY_TX](@pId_Trans INT, @pImporte DECIMAL(12,2), @pId_Tar_Lote INT, @pPeriodo DATETIME) 
RETURNS CHAR(200)
AS
BEGIN

/*Variables Archivo*/
DECLARE @Retorno				CHAR(200)
DECLARE @aTipo_Registro			CHAR(1)		/*Tipo: ALFANUMERICO.	Largo: 001.			Formato:							Observacion: Siempre 1*/
DECLARE @aNro_de_Cabezal		CHAR(7)		/*Tipo: NUMERICO.		Largo: 007.			Formato:							Observacion: */
DECLARE @aNro_Transaccion		CHAR(7)		/*Tipo: NUMERICO.		Largo: 007.			Formato:							Observacion: */
DECLARE @aNro_Comercio			CHAR(8)		/*Tipo: NUMERICO.		Largo: 008.			Formato:							Observacion: */
DECLARE @aSucursal_Comercio		CHAR(3)		/*Tipo: NUMERICO.		Largo: 003.			Formato:							Observacion: */
DECLARE @aFecha_Lote			CHAR(8)		/*Tipo: NUMERICO.		Largo: 008.			Formato: AAAAMMDD					Observacion: */
DECLARE @aMoneda				CHAR(4)		/*Tipo: NUMERICO.		Largo: 004.			Formato:							Observacion: $: 0858, U$S: 0840*/
DECLARE @aCant_Cuotas			CHAR(2)		/*Tipo: NUMERICO.		Largo: 002.			Formato:							Observacion: Contado=01, 2 Cuotas = 0, 3 Cuotas = 03,...*/
DECLARE @aPlan_de_Venta			CHAR(4)		/*Tipo: NUMERICO.		Largo: 004.			Formato:							Observacion: Vta Combustible=0100, Debitos Automaticos=0090, Transacciones Contado=0001, Transacciones en Cuotas=(Cant. Cuotas)*/
DECLARE @aTipo_Transaccion		CHAR(2)		/*Tipo: NUMERICO.		Largo: 002.			Formato:							Observacion: Compra=05, Devolucion=06, Anulacion Compra=25, Anulacion devolucion=26*/
DECLARE @aNro_Tarjeta			CHAR(19)	/*Tipo: ALFANUMERICO.	Largo: 019.			Formato:							Observacion: */
DECLARE @aVencimiento_Tarjeta	CHAR(4)		/*Tipo: NUMERICO.		Largo: 004.			Formato: AAMM						Observacion: */
DECLARE @aFecha_Transaccion		CHAR(8)		/*Tipo: NUMERICO.		Largo: 008.			Formato: AAAAMMDD					Observacion: Si es anulacion debe ser fecha de la transaccion original*/
DECLARE @aImporte				CHAR(15)	/*Tipo: NUMERICO.		Largo: 015.			Formato: 13 enteros, 2 decimales	Observacion: */
DECLARE @aNumero_Autorizacion	CHAR(6)		/*Tipo: ALFANUMERICO.	Largo: 006.			Formato:							Observacion: */
DECLARE @aPeriodo				CHAR(6)		/*Tipo: ALFANUMERICO.	Largo: 006.			Formato:							Observacion: Si Plan de Venta=90 (debitos automaticos) mes/aa:"ENE/97". Si plan de venta no es 90 '     '*/
DECLARE @aSocio					CHAR(10)	/*Tipo: ALFANUMERICO.	Largo: 010.			Formato:							Observacion: */
DECLARE @aAplicaDevolucionIVA	CHAR(1)		/*Tipo: NUMERICO.		Largo: 001.			Formato:							Observacion: No aplica=0, Aplica Dev. Iva Ley 19210=6*/
DECLARE @aSerie_Comprobante		CHAR(2)		/*Tipo: ALFANUMERICO.	Largo: 002.			Formato:							Observacion: */
DECLARE @aNumero_Comprobante	CHAR(7)		/*Tipo: NUMERICO.		Largo: 007.			Formato:							Observacion: */
DECLARE @aImporte_Gravado		CHAR(15)	/*Tipo: NUMERICO.		Largo: 015.			Formato: 13 enteros, 2 decimales	Observacion: */
DECLARE @aFiller				CHAR(61)	/*Tipo: ALFANUMERICO.	Largo: 061.			Formato:							Observacion: */
/*FIN Variables Archivo*/

/*Variable Locales*/
DECLARE @Id_Tarjeta				VARCHAR(10)
DECLARE @Fecha_Presentacion		DATETIME
DECLARE @Comercio_Nro			VARCHAR(50)
DECLARE @Tar_Nro				VARCHAR(22)
DECLARE @Id_Contrato			INT
DECLARE @Tar_Fecha_Vence		DATETIME
DECLARE @Fecha_Cbte				DATETIME
DECLARE @Mes_Periodo			SMALLINT
DECLARE @Mes_Periodo_VC			VARCHAR(3)
DECLARE @Id_Cliente				INT
DECLARE @Id_Cliente_Externo		INT
DECLARE @Comprobante_Nro		INT
/*FIN Variable Locales*/

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

/*Seteo Variables Locales*/
SELECT	
@Id_Tarjeta				= ISNULL(Id_Tarjeta, ''),
@Fecha_Presentacion		= ISNULL(Fecha_Presentacion,@pPeriodo)
FROM Val_Tarjetas_Lotes
WHERE
Id_Tar_Lote = @pId_Tar_Lote

SELECT
@Comercio_Nro			= ISNULL(Comercio_Nro, '')
FROM Valores_Tarjetas_Cred
WHERE
ISNULL(Id_Tarjeta, '') = @Id_Tarjeta

SELECT	
@Tar_Nro				= LTRIM(RTRIM(ISNULL(DBO.SF_COTIZA(Nro), '')))
FROM Val_Tarjetas_Lotes_Items 
WHERE
Id_Tar_Lote = @pId_Tar_Lote
AND Id_Trans = @pId_Trans


SELECT	
@Id_Cliente				= ISNULL(Id_Cliente, 0),
@Fecha_Cbte				= @Fecha_Presentacion,
@Id_Contrato			= ISNULL(Id_Contrato, 0),
@Comprobante_Nro		= ISNULL(Comprobante_Nro, 0)
FROM Cbtes 
WHERE
Id_Trans = @pId_Trans

SELECT 
@Id_Cliente_Externo		= ISNULL(Id_Cliente_Externo, Id_Cliente)
FROM Clientes
WHERE
Id_Cliente = @Id_Cliente

SELECT
@Tar_Fecha_Vence		= ISNULL(Tar_Fecha_Vence, DATEADD(YEAR, 1, GETDATE()))
FROM Contratos
WHERE
Id_Contrato = @Id_Contrato

SET @Mes_Periodo = DATEPART(MONTH, @pPeriodo)

SELECT
@Mes_Periodo_VC =	CASE @Mes_Periodo
						WHEN 1	THEN 'ENE'
						WHEN 2	THEN 'FEB'
						WHEN 3	THEN 'MAR'
						WHEN 4	THEN 'ABR'
						WHEN 5	THEN 'MAY'
						WHEN 6	THEN 'JUN'
						WHEN 7	THEN 'JUL'
						WHEN 8	THEN 'AGO'
						WHEN 9	THEN 'SEP'
						WHEN 10 THEN 'OCT'
						WHEN 11 THEN 'NOV'
						WHEN 12 THEN 'DIC'
					END


/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

SET @aTipo_Registro			=	'1'

SET @aNro_de_Cabezal		=	'0000001'

SET @aNro_Transaccion		=	(RIGHT('0000000' + CAST(@pId_Trans AS VARCHAR), 7))

SET @aNro_Comercio			=	(RIGHT('00000000' + @Comercio_Nro, 8))

SET @aSucursal_Comercio		=	(RIGHT('000' + dbo.CF_xParam('Id_Visa_Suc'), 3))

SET @aFecha_Lote			=	RIGHT('0000' + CAST(DATEPART(YEAR, @Fecha_Presentacion) AS VARCHAR), 4) + 
								RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_Presentacion) AS VARCHAR), 2)  + 
								RIGHT('00' + CAST(DATEPART(DAY, @Fecha_Presentacion) AS VARCHAR), 2)

SET @aMoneda				=	'0858' /*PESOS URUGUAYOS*/

SET @aCant_Cuotas			=	'01' /*CONTADO*/

SET @aPlan_de_Venta			=	'0090' /*DEBITO AUTOMATICO*/

SET @aTipo_Transaccion		=	'05' /*COMPRA*/

---SET @aNro_Tarjeta			=	(RIGHT('0000000000000000000' + @Tar_Nro, 19))

SET @aNro_Tarjeta			=	(RIGHT('0000000000000000000' + @Tar_Nro, 19))

SET @aVencimiento_Tarjeta	=	SUBSTRING(RIGHT('0000' + CAST(DATEPART(YEAR, @Tar_Fecha_Vence) AS VARCHAR), 4), 3, 2) + 
								RIGHT('00' + CAST(DATEPART(MONTH, @Tar_Fecha_Vence) AS VARCHAR), 2)

SET @aFecha_Transaccion		=	RIGHT('0000' + CAST(DATEPART(YEAR, @Fecha_Cbte) AS VARCHAR), 4) + 
								RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_Cbte) AS VARCHAR), 2)  + 
								RIGHT('00' + CAST(DATEPART(DAY, @Fecha_Cbte) AS VARCHAR), 2)

SET @aImporte				=	RIGHT('000000000000000' + CAST(CAST(@pImporte * 100 AS INT) AS VARCHAR), 15)

SET @aNumero_Autorizacion	=	'000000'

SET @aPeriodo				=	@Mes_Periodo_VC +
								'/' +
								SUBSTRING(RIGHT('0000' + CAST(DATEPART(YEAR, @pPeriodo) AS VARCHAR), 4), 3, 2)

SET @aSocio					= (RIGHT('0000000000' + CAST(@Id_Cliente_Externo AS VARCHAR), 10))

SET @aAplicaDevolucionIVA	= '0' /*NO APLICA*/

SET @aSerie_Comprobante		= 'SC'

SET @aNumero_Comprobante	= (RIGHT('0000000' + CAST(@Comprobante_Nro AS VARCHAR), 7)) 

SET @aImporte_Gravado		= '000000000000000'

SET @aFiller				= '                                                             '

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

SET @Retorno =	@aTipo_Registro			+
				@aNro_de_Cabezal		+
				@aNro_Transaccion		+
				@aNro_Comercio			+
				@aSucursal_Comercio		+
				@aFecha_Lote			+
				@aMoneda				+
				@aCant_Cuotas			+
				@aPlan_de_Venta			+
				@aTipo_Transaccion		+
				@aNro_Tarjeta			+
				@aVencimiento_Tarjeta	+
				@aFecha_Transaccion		+
				@aImporte				+
				@aNumero_Autorizacion	+
				@aPeriodo				+
				@aSocio					+
				@aAplicaDevolucionIVA	+
				@aSerie_Comprobante		+
				@aNumero_Comprobante	+
				@aImporte_Gravado		+
				@aFiller

/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/

RETURN ISNULL(@Retorno, '                                                                                                                                                                                                        ')
END
GO


CREATE FUNCTION [dbo].[CF_Vta_TCli_Prod_Validar](@pId_Cliente INT, @pId_Producto VARCHAR(14))
RETURNS TINYINT
AS
BEGIN

RETURN ISNULL(0,0) 	

DECLARE @Flag_Cliente_Valido					TINYINT -- Valor a retornar: 1 para inhabilitado, 0 para habilitado.
DECLARE @Flag_Prod_Valida_Cat					TINYINT -- Flag que chequea si el producto se valida por categor├¡as.
DECLARE @Flag_Existe_Producto_Cat				TINYINT -- Flag que chequea si el producto esta disponible para la categor├¡a del cliente.
DECLARE @Id_Tipo_Cli							INT		-- La categor├¡a del cliente.

/*=================================================================================*/


SET @Id_Tipo_Cli = (SELECT DBO.SF_Categ(@pId_Cliente,GETDATE()))
SET @Flag_Cliente_Valido = 0

SET @Flag_Prod_Valida_Cat = ISNULL((SELECT TOP 1 1 FROM Clientes_Tipos_Prod tp, Clientes c 
											 WHERE tp.Id_Tipo_Cli=c.Id_Tipo_Cli 
											 AND tp.Id_Producto=@pId_Producto)
									         ,0)
IF(@Flag_Prod_Valida_Cat <> 0)
BEGIN
	SET @Flag_Existe_Producto_Cat = ISNULL((SELECT 1 FROM Clientes_Tipos_Prod tp, Clientes c 
													 WHERE tp.Id_Tipo_Cli=c.Id_Tipo_Cli 
													 AND tp.Id_Producto=@pId_Producto 
													 AND c.Id_Cliente=@pId_Cliente
													 AND tp.Id_Tipo_Cli = @Id_Tipo_Cli)
													 ,0)

	IF(@Flag_Existe_Producto_Cat <> 0)
	BEGIN
		SET @Flag_Cliente_Valido = 1
		RETURN ISNULL(@Flag_Cliente_Valido,0)
	END
END		

RETURN ISNULL(0,0) 	
END
GO


CREATE FUNCTION [dbo].[CF_WSOCA_OR_XML_Datos](@pId_Trans INT, @pItem SMALLINT) 
RETURNS VARCHAR(8000)
AS
BEGIN
/*Variable de Retorno*/
DECLARE @OR_XML_Datos						VARCHAR(8000)
/*FIN Variable de Retorno*/

/*Variables Locales*/
DECLARE @Version							VARCHAR(3)
DECLARE @Nro_Cuenta							VARCHAR(10)

DECLARE @Origen_Calle						VARCHAR(30)
DECLARE @Origen_Calle_Nro					VARCHAR(5)
DECLARE @Origen_Piso_Nro					VARCHAR(2)
DECLARE @Origen_Depto_Nro					VARCHAR(4)
DECLARE @Origen_Cp							VARCHAR(4)
DECLARE @Origen_Localidad_Descrip			VARCHAR(30)
DECLARE @Origen_Provincia_Descrip			VARCHAR(30)
DECLARE @Origen_Contacto					VARCHAR(30)
DECLARE @Origen_email						VARCHAR(100)
DECLARE @Origen_Solicitante					VARCHAR(30)
DECLARE @Origen_Observaciones				VARCHAR(100)
DECLARE @Origen_CentroCosto					VARCHAR(10)
DECLARE @Origen_Id_Franja_Horaria			VARCHAR(1)
DECLARE @Origen_Id_Centro_Imposicion		VARCHAR(3)
DECLARE @Origen_Fecha						VARCHAR(10)

DECLARE @Envio_Id_Operativa					VARCHAR(6)
DECLARE @Envio_NroRemito					VARCHAR(30)

DECLARE @Destino_Apellido					VARCHAR(30)
DECLARE @Destino_Nombre						VARCHAR(30)
DECLARE @Destino_Calle						VARCHAR(30)
DECLARE @Destino_Calle_Nro					VARCHAR(5)
DECLARE @Destino_Piso_Nro					VARCHAR(6)
DECLARE @Destino_Depto_Nro					VARCHAR(4)
DECLARE @Destino_Localidad_Descrip			VARCHAR(30)
DECLARE @Destino_Provincia_Descrip			VARCHAR(30)
DECLARE @Destino_Cp							VARCHAR(4)
DECLARE @Destino_Telefono					VARCHAR(30)
DECLARE @Destino_Email						VARCHAR(100)
DECLARE @Destino_Id_CI						VARCHAR(3)
DECLARE @Destino_Celular					VARCHAR(15)
DECLARE @Destino_Observaciones				VARCHAR(100)

DECLARE @Paquete_Alto						VARCHAR(11)
DECLARE @Paquete_Ancho						VARCHAR(11)
DECLARE @Paquete_Largo						VARCHAR(11)
DECLARE @Paquete_Peso						VARCHAR(11)
DECLARE @Paquete_Valor						VARCHAR(11)
DECLARE @Paquete_Cantidad					VARCHAR(10)

DECLARE @Id_Sucursal						SMALLINT
DECLARE @Sucursal_Domicilio					VARCHAR(30)
DECLARE @Sucursal_Domicilio_Nro				SMALLINT
DECLARE @Sucursal_Cod_Postal				VARCHAR(20)
DECLARE @Sucursal_Id_Localidad				INT
DECLARE @Sucursal_Localidad					VARCHAR(80)
DECLARE @Sucursal_Id_Provincia				CHAR(3)
DECLARE @Sucursal_Provincia					VARCHAR(50)
DECLARE @Sucursal_Mail						VARCHAR(255)

DECLARE @Id_Cliente							INT
DECLARE @Clientes_Apellido					VARCHAR(100)
DECLARE @Clientes_Nombre					VARCHAR(100)
DECLARE @Clientes_Email						VARCHAR(8000)
DECLARE @Clientes_Tel_Movil					VARCHAR(20)

DECLARE @Clientes_Suc_Direccion				VARCHAR(100)
DECLARE @Clientes_Suc_Dir_Entrega_Numero	INT
DECLARE @Clientes_Suc_Dir_Entrega_Piso		VARCHAR(50)
DECLARE @Clientes_Suc_Dir_Entrega_Dto		VARCHAR(50)
DECLARE @Clientes_Suc_Dir_Entrega_Localidad	VARCHAR(50)
DECLARE @Clientes_Suc_Provincia_Descrip		VARCHAR(200)
DECLARE @Clientes_Suc_Dir_Entrega_CP		VARCHAR(8)
DECLARE @Clientes_Suc_Telefono				VARCHAR(300)
DECLARE @Clientes_Suc_Contacto				VARCHAR(100)

DECLARE @Cbtes_Items_Id_Producto			VARCHAR(14)
DECLARE @Cbtes_Items_Cantidad				DECIMAL(15,5)
DECLARE @Cbtes_Items_Precio_Grav			DECIMAL(15,5)

DECLARE @Productos_Alto						DECIMAL(7,2)
DECLARE @Productos_Ancho					DECIMAL(7,2)
DECLARE @Productos_Largo					DECIMAL(7,2)
DECLARE @Productos_Id_Familia				INT
DECLARE @Productos_Peso						DECIMAL(7,2)

DECLARE @Productos_x_Cantidad_Peso			DECIMAL(9,2)
DECLARE @Productos_x_Cantidad_Cotizacion	DECIMAL(9,2)

DECLARE @Id_Producto_OCA					VARCHAR(14)
DECLARE @Id_Operativa_Cotizada				VARCHAR(6)
/*FIN Variables Locales*/

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

/*
EJ:

<?xml version="1.0" encoding="iso-8859-1" standalone="yes"?>
<ROWS>
	<cabecera ver="2.0" nrocuenta="111757/001" />
	<origenes>
		<origen calle="La Rioja" nro="300" piso="" depto="" cp="1215" localidad="CAPITAL FEDERAL" provincia="CAPITAL FEDERAL" contacto="" email="test@oca.com.ar" solicitante="" observaciones="" centrocosto="" idfranjahoraria="1" idcentroimposicionorigen="3" fecha="20211110">
			<envios>
				<envio idoperativa="94584" nroremito="Envio1">
					<destinatario apellido="Fernandez" nombre="Martin" calle="BALCARCE" nro="50" piso="" depto="" localidad="CAPITAL FEDERAL" provincia="CAPITAL FEDERAL" cp="1214" telefono="49569622" email="test@oca.com.ar" idci="0" celular="1121877788" observaciones="Prueba" />
					<paquetes>
						<paquete alto="10" ancho="10" largo="10" peso="1" valor="10" cant="3" />
					</paquetes>
				</envio>
			</envios>
		</origen>
	</origenes>
</ROWS>
*/

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

SELECT
@Id_Sucursal						= ISNULL(Id_Sucursal, 0),
@Id_Cliente							= ISNULL(Id_Cliente, 0)
FROM Cbtes
WHERE
Id_Trans = @pId_Trans

SELECT
@Cbtes_Items_Id_Producto			= ISNULL(Id_Producto, ''),
@Cbtes_Items_Cantidad				= ISNULL(Cantidad, 0),
@Cbtes_Items_Precio_Grav			= ISNULL(Precio_Grav, 0)
FROM Cbtes_Items
WHERE 
Id_Trans = @pId_Trans
AND Item = @pItem

---------------------------------------------------------------------------------------------------------------------

SET @Id_Operativa_Cotizada = ''

SET @Id_Producto_OCA = ISNULL((SELECT MIN(PR.Id_Producto)
								FROM Cbtes_Items CI, Productos PR 
								WHERE
								PR.Id_Producto = ISNULL(CI.Id_Producto, '')
								AND PR.Id_Familia = 1000  /*FLETES*/
								AND CI.Id_Trans = @pId_Trans)
								, '')

IF(@Id_Producto_OCA = dbo.CF_xParam('OCAWS_Id_Prod_PaP'))
BEGIN
	SET @Id_Operativa_Cotizada = LTRIM(RTRIM(dbo.CF_xParam('OCAWS_Operativa')))
END

IF(@Id_Producto_OCA = dbo.CF_xParam('OCAWS_Id_Prod_PaS'))
BEGIN
	SET @Id_Operativa_Cotizada = LTRIM(RTRIM(dbo.CF_xParam('OCAWS_Operativa_PaS')))
END

---------------------------------------------------------------------------------------------------------------------

SELECT
@Productos_Alto						= ISNULL(Alto, 0),
@Productos_Ancho					= ISNULL(Ancho, 0),
@Productos_Largo					= ISNULL(Largo, 0),
@Productos_Id_Familia				= ISNULL(Id_Familia, 0),
@Productos_Peso						= ISNULL(Peso, 0)
FROM Productos
WHERE
Id_Producto = @Cbtes_Items_Id_Producto

IF(@Productos_Id_Familia IN (1000/*FLETES*/, 1020/*ADICIONALES LOGISTICA / ENTREGAS*/))
BEGIN
	SET @OR_XML_Datos = ''
	RETURN @OR_XML_Datos
END

SET @Productos_x_Cantidad_Peso		= CAST(SUM(@Productos_Peso * @Cbtes_Items_Cantidad) AS DECIMAL(9, 2))
SET @Productos_x_Cantidad_Cotizacion = CAST(SUM(@Cbtes_Items_Precio_Grav * @Cbtes_Items_Cantidad) AS DECIMAL(9, 2))

SELECT
@Sucursal_Domicilio			= UPPER(LTRIM(RTRIM(ISNULL(Domicilio, '')))),
@Sucursal_Domicilio_Nro		= ISNULL(Domicilio_Nro, 0),
@Sucursal_Cod_Postal		= UPPER(LTRIM(RTRIM(ISNULL(Cod_Postal, '')))),
@Sucursal_Id_Localidad		= ISNULL(Id_Localidad, 0),
@Sucursal_Mail				= LOWER(LTRIM(RTRIM(ISNULL(Mail, ''))))
FROM Empresas_Suc
WHERE
Id_Sucursal = @Id_Sucursal

SELECT
@Sucursal_Localidad			= UPPER(LTRIM(RTRIM(ISNULL(TL.Descripcion, '')))),
@Sucursal_Id_Provincia		= ISNULL(TP.Id_Provincia, ''),
@Sucursal_Provincia			= UPPER(LTRIM(RTRIM(ISNULL(TP.Descripcion, ''))))
FROM Tab_Localidades TL, Tab_Provincias TP
WHERE
ISNULL(TL.Id_Provincia, '') = TP.Id_Provincia
AND TL.Id_Localidad = @Sucursal_Id_Localidad

SELECT
@Clientes_Apellido				= UPPER(LTRIM(RTRIM(ISNULL(Apellido, '')))),
@Clientes_Nombre				= UPPER(LTRIM(RTRIM(ISNULL(Nombre, '')))),
@Clientes_Email					= LOWER(LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(8000), email), '')))),
@Clientes_Tel_Movil				= LTRIM(RTRIM(ISNULL(Tel_Movil, '')))
FROM Clientes 
WHERE
Id_Cliente = @Id_Cliente

IF(@Clientes_Email NOT LIKE '%@%')
BEGIN
	SET @Clientes_Email = ''
END

SELECT
@Clientes_Suc_Direccion				= UPPER(LTRIM(RTRIM(ISNULL(Direccion, '')))),
@Clientes_Suc_Dir_Entrega_Numero	= ISNULL(Dir_Entrega_Numero, 0),
@Clientes_Suc_Dir_Entrega_Piso		= UPPER(LTRIM(RTRIM(ISNULL(Dir_Entrega_Piso, '')))),
@Clientes_Suc_Dir_Entrega_Dto		= UPPER(LTRIM(RTRIM(ISNULL(Dir_Entrega_Dto, '')))),
@Clientes_Suc_Dir_Entrega_Localidad	= UPPER(LTRIM(RTRIM(ISNULL(Dir_Entrega_Localidad, '')))),
@Clientes_Suc_Provincia_Descrip		= UPPER(LTRIM(RTRIM(ISNULL(Provincia_Descrip, '')))),
@Clientes_Suc_Dir_Entrega_CP		= UPPER(LTRIM(RTRIM(ISNULL(Dir_Entrega_CP, '')))),
@Clientes_Suc_Telefono				= UPPER(LTRIM(RTRIM(ISNULL(Telefono, '')))),
@Clientes_Suc_Contacto				= UPPER(LTRIM(RTRIM(ISNULL(Contacto, ''))))
FROM Clientes_Suc
WHERE
Id_Cliente = @Id_Cliente
AND Nro = 1


--SELECT Alto FROM Productos

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

SET @Version						= '2.0'
SET @Nro_Cuenta						= LTRIM(RTRIM(dbo.CF_xParam('OCAWS_NroCuenta')))

SET @Origen_Calle					= SUBSTRING(@Sucursal_Domicilio, 1, 30)
SET @Origen_Calle_Nro				= CONVERT(VARCHAR(5), @Sucursal_Domicilio_Nro)
SET @Origen_Piso_Nro				= ''
SET @Origen_Depto_Nro				= ''
SET @Origen_Cp						= SUBSTRING(@Sucursal_Cod_Postal, 1, 5)
SET @Origen_Localidad_Descrip		= SUBSTRING(@Sucursal_Localidad, 1, 30)
SET @Origen_Provincia_Descrip		= SUBSTRING(@Sucursal_Provincia, 1, 30)
SET @Origen_Contacto				= ''
SET @Origen_email					= SUBSTRING(@Sucursal_Mail, 1, 100)
SET @Origen_Solicitante				= ''
SET @Origen_Observaciones			= ''
SET @Origen_CentroCosto				= ''	/*Mail 30/11/2021 10:32Hs Daniel Martin Fernandez <mfernandez@oca.com.ar> indico que se puede enviar siempre cero*/
SET @Origen_Id_Franja_Horaria		= LTRIM(RTRIM(dbo.CF_xParam('OCAWS_FranjaHoraria')))
SET @Origen_Id_Centro_Imposicion	= LTRIM(RTRIM(dbo.CF_xParam('OCAWS_CImposic_Orig')))
SET @Origen_Fecha					= RIGHT('0000' + CAST(DATEPART(YEAR, GETDATE()) AS VARCHAR), 4) + RIGHT('00' + CAST(DATEPART(MONTH, GETDATE()) AS VARCHAR), 2) + RIGHT('00' + CAST(DATEPART(DAY, GETDATE()) AS VARCHAR), 2)

SET @Envio_Id_Operativa				= @Id_Operativa_Cotizada
SET @Envio_NroRemito				= LTRIM(RTRIM(dbo.CF_Cbte_Descrip(@pId_Trans)))

SET @Destino_Apellido				= SUBSTRING(@Clientes_Apellido, 1, 30)
SET @Destino_Nombre					= SUBSTRING(@Clientes_Nombre, 1, 30)
SET @Destino_Calle					= SUBSTRING(@Clientes_Suc_Direccion, 1, 30)
SET @Destino_Calle_Nro				= CONVERT(VARCHAR(5), @Clientes_Suc_Dir_Entrega_Numero)
SET @Destino_Piso_Nro				= SUBSTRING(@Clientes_Suc_Dir_Entrega_Piso, 1, 6)
