SET @Paquete_Cantidad				= '1'																		--REPLACE(CONVERT(VARCHAR(10), @Cbtes_Items_Cantidad), '.00000', '')

-------------------------------------------------------------------------------------------------------------------------------------------------------------------

SET @OR_XML_Datos = ''
