CREATE FUNCTION [dbo].[CF_xParam](@pId_Parametro VARCHAR(20))
RETURNS VARCHAR(8000)
AS
BEGIN

DECLARE @Valor_Parametro VARCHAR(8000)
DECLARE @TipoDato VARCHAR(10)

SET @TipoDato = (SELECT MAX(ISNULL(TipoDato,'')) FROM xParametros WHERE IdParametro = @pId_Parametro)

IF (@TipoDato = '')
BEGIN
	RETURN ''
END

IF(@TipoDato = 'DECIMAL')
BEGIN
	SET @Valor_Parametro = ISNULL((SELECT CONVERT(VARCHAR(8000), Valor_Decimal) FROM xParametros WHERE IdParametro = @pId_Parametro), '0')
END

IF(@TipoDato = 'TIME')
BEGIN
	SET @Valor_Parametro = ISNULL((SELECT CONVERT(VARCHAR(8000), Valor_Time, 121) FROM xParametros WHERE IdParametro = @pId_Parametro), '1900-01-01 00:00:00.000')
END

IF(@TipoDato = 'MEMO')
BEGIN
	SET @Valor_Parametro = ISNULL((SELECT CONVERT(VARCHAR(8000), Valor_Memo) FROM xParametros WHERE IdParametro = @pId_Parametro), '')
END

IF(@TipoDato = 'DATE')
BEGIN
	SET @Valor_Parametro = ISNULL((SELECT CONVERT(VARCHAR(8000), Valor_Date, 121) FROM xParametros WHERE IdParametro = @pId_Parametro), '1900-01-01 00:00:00.000')
END

IF(@TipoDato = 'STRING')
BEGIN
	SET @Valor_Parametro = ISNULL((SELECT CONVERT(VARCHAR(8000), Valor_String) FROM xParametros WHERE IdParametro = @pId_Parametro), '')
END

IF(@TipoDato = 'INTEGER')
BEGIN
	SET @Valor_Parametro = ISNULL((SELECT CONVERT(VARCHAR(8000), Valor_Integer) FROM xParametros WHERE IdParametro = @pId_Parametro), '0')
END

IF(@TipoDato = 'FOLDER')
BEGIN
	SET @Valor_Parametro = ''
END

RETURN ISNULL(@Valor_Parametro,'')
END
GO


CREATE PROCEDURE [dbo].[CPJU_Cbtes_Pos_V2]  @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON


DECLARE 	@pLote				VARCHAR(50),
			@pModoDebug			TINYINT,
			@pOmitir_Result_OK	TINYINT

SET @pLote				= ISNULL(CONVERT(VARCHAR(50), dbo.CF_JSON_VALUE(@pJsonRecibido,'Lote')), '')
SET @pModoDebug			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)
SET @pOmitir_Result_OK	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Omitir_Result_OK')), 1)

DECLARE @Id_Trans INT


/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
DECLARE @Result_Stored_Invocado				INT
DECLARE @Result_Tabla_Stored_Invocado TABLE (ErrorNumber	INT,
											ErrorSeverity	INT,
											ErrorState		INT,
											ErrorProcedure  VARCHAR(1000),
											ErrorLine		INT,
											ErrorMessage	VARCHAR(4000))
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
DECLARE @rta_JSON_Stored_Invocado			VARCHAR(8000)


BEGIN TRY
	
	DECLARE LotCur CURSOR FOR 
					WITH Tot_Items AS (SELECT I.Id_Trans,SUM(Imp_Final) AS Tot
							FROM Cbtes_Items I 
								JOIN Cbtes C ON C.Id_Trans = I.Id_Trans
								JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
								WHERE C.Id_Estado_Cbte IN (1,2,4)
									AND T.Compromete_Factura IN (1,-1)
									AND C.Lote = @pLote
								GROUP BY I.Id_Trans
								
					)
					SELECT C.Id_Trans 
					FROM Cbtes C JOIN Tot_Items I ON I.Id_Trans = C.Id_Trans
					WHERE C.Lote = @pLote
					AND C.Imp_Total <> I.Tot
	
	
	OPEN LotCur

	FETCH NEXT FROM LotCur INTO @Id_Trans
	WHILE @@FETCH_STATUS = 0 
	BEGIN 

			SET @JSON_Parametros_Stored_Invocado =	'{' +
													dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('Id_Trans', @Id_Trans, 'INT') + 
													dbo.CF_Json_ParsearVariable('Omitir_Result_OK', 1, 'TINYINT') + 
													'}'
		INSERT INTO @Result_Tabla_Stored_Invocado			
			EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Fac_Fin @JSON_Parametros_Stored_Invocado
		IF ISNULL(@Result_Stored_Invocado, 0) <> 0 RAISERROR ('Error when calling CPJ_Cbtes_Fac_Fin', 16,  1 ) 
		
		FETCH NEXT FROM LotCur INTO @Id_Trans
	END 

	CLOSE LotCur
	DEALLOCATE LotCur

	SET @rtaMsjStored		=	'CPJU_Cbtes_Pos_V2 ejecutado correctamente'
    IF @pOmitir_Result_OK = 0
	BEGIN
		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage
	END
END TRY  


BEGIN CATCH  
 

	IF EXISTS (SELECT 1 FROM @Result_Tabla_Stored_Invocado) 
		SELECT * FROM @Result_Tabla_Stored_Invocado
    ELSE
    EXECUTE usp_GetErrorInfo

	RETURN 9999
END CATCH

RETURN 0

/*
EXEC dbo.CPJU_Cbtes_Pos_V2 '{"ModoDebug":"0","Lote":"CSOC_2026-03_"}'


*/
GO

CREATE PROCEDURE CPJU_Fact_Lote_Recalcular_Precios @pJsonRecibido VARCHAR(8000)
AS

DECLARE	@pFecha_Desde datetime,
	    @pFecha_Hasta datetime,
	    @pId_Tipo_cbte VARCHAR(4),
		@pLote VARCHAR(50),
        @pId_Lote_Tipo INT		

        SET @pFecha_Desde			= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Desde')),GETDATE())
        SET @pFecha_Hasta			= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Hasta')),GETDATE())
        SET @pId_Tipo_Cbte			= ISNULL(CONVERT(VARCHAR(4), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Tipo_Cbte')),'CUP')
        SET @pLote			        = ISNULL(CONVERT(VARCHAR(50), dbo.CF_JSON_VALUE(@pJsonRecibido,'Lote')), '')
  	    SET @pId_Lote_Tipo	        = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Lote_Tipo')), 1)

	/*Variable de Retorno del Stored*/

	DECLARE @rtaErrorStored						INT
	DECLARE @rtaMsjStored						VARCHAR(4000)
	DECLARE @Result_Stored_Invocado				INT
	DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)

	DECLARE @Result_Tabla_Stored_Invocado TABLE (ErrorNumber	INT,
										       	 ErrorSeverity	INT,
											     ErrorState		INT,
											     ErrorProcedure VARCHAR(1000),
											     ErrorLine		INT,
											     ErrorMessage	VARCHAR(4000))

BEGIN TRY 

BEGIN TRAN
/*   Atenci├│n esto recalcula el importe de comprobantes, solo sirve para las empresas que no tiene contabilidad

	Y que no tiene facturas electr├│nicas.
	El proceso de aumento para el resto de la empresas es generar el cbte. por la diferenica.

*/

/*
   Select Lote Into #Cbtes_lotes from Cbtes_Lotes where Id_Lote_Tipo = @pId_Lote_Tipo or Lote = '' or Lote is null


   PRINT @pLote

   If @pLote <> ''
      Delete  #Cbtes_lotes where Lote <> @pLote


   PRINT @pId_Tipo_cbte
   PRINT @pId_Lote_Tipo

   select c.id_cliente,c.id_trans,i.id_producto,i.cantidad,i.precio_grav
                ,dbo.SF_Categ_Precio(k.id_tipo_cli,k.id_lista_precio,k.id_cliente,getdate()) as precio_calculado
                Into #Diferencias
                from cbtes c, cbtes_items i, clientes k, #Cbtes_lotes L
                where c.id_trans = i.id_trans 
				      and c.id_tipo_cbte = @pId_Tipo_cbte
                      and c.saldo <> 0 
					  and c.id_estado_cbte = 1
					  and c.Lote = L.Lote
                      and c.id_cliente = k.id_cliente
	                  AND C.FECHA >= @pFecha_Desde 
	                  AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)

                      

	select id_trans,sum(cantidad*precio_calculado) as imp_total 
		   into #Trans_a_Procesar from #Diferencias group by Id_Trans


    set @rtaErrorStored = isnull((select count(*) from #Trans_a_Procesar),0)
	
	PRINT @rtaErrorStored


	update cbtes_items SET precio_grav = d.precio_calculado,
						  imp_gravado = d.precio_calculado,
						  precio = d.precio_calculado,
						  imp_final = d.precio_calculado
					 from cbtes_items i, #Trans_a_Procesar p, #Diferencias D
						  where p.id_trans = i.id_trans 
							and p.id_trans = d.id_trans 
							and I.id_Producto = d.id_Producto
							and I.id_cliente = D.id_cliente

	update cbtes  set imp_exento = i.imp_total, imp_total = i.imp_total, saldo = i.imp_total
						  from cbtes  c, #Trans_a_Procesar I
						  where c.id_trans = i.id_trans 

	update clientes_ctacte  set importe = k.imp_total, saldo = k.imp_total
						  from clientes_ctacte c, #Trans_a_Procesar K
						  where  c.id_trans = k.id_trans
                   
	update cbtes_ctas_contables_DIFE  set debe = c.imp_total 
						  from #Trans_a_Procesar c, cbtes_ctas_contables k
						  where  c.id_trans = k.id_trans
						  and k.debe <> 0

	update cbtes_ctas_contables_DIFE  set haber = c.imp_total 
						  from #Trans_a_Procesar c, cbtes_ctas_contables k
						  where c.id_trans = k.id_trans
						  and k.haber <> 0

   DROP TABLE #Diferencias
   DROP TABLE #Trans_a_Procesar
   DROP TABLE #Cbtes_lotes
*/
   COMMIT TRAN

   SELECT	 0				 AS ErrorNumber 
			,0				 AS ErrorSeverity  
			,0				 AS ErrorState 
			,0			     AS ErrorProcedure  
			,0               AS ErrorLine		
			,@rtaErrorStored AS ErrorMessage

 			
END TRY 

BEGIN CATCH  
    EXECUTE usp_GetErrorInfo
	ROLLBACK
	RETURN 9999
END CATCH
RETURN 0 
 



 /*
  
  EXEC dbo.CPJU_FACT_LOTE_RECALCULAR_PRECIOS '{
			"Fecha_Desde":"20220801",
			"Fecha_Hasta":"20220905",
			"Id_Tipo_Cbte":"ND"}'

EXEC CPJU_Fact_Lote_Recalcular_Precios '{"Fecha_Desde":"20220801","Fecha_Hasta":"20220831","Lote":"LOTE_2022-08_","Id_Lote_Tipo":"1","Id_Tipo_Cbte":"ND" }'
  
EXEC CPJU_Fact_Lote_Recalcular_Precios '{"Fecha_Desde":"20220801","Fecha_Hasta":"20220831","Lote":"","Id_Lote_Tipo":"1","Id_Tipo_Cbte":"ND" }'

SELECT * FROM CBTES WHERE LOTE = 'LOTE_2022-08_'

update CBTES set saldo = 10000 WHERE LOTE = 'LOTE_2022-08_'
*/
GO

CREATE PROCEDURE [dbo].[CPJU_Lista_Blanca_Suprema_Socios] @pJson VARCHAR(8000)
AS 

/*
 * LOG VERSIONES:
 * 16/07/2025 TC: Se crea el Stored
 * 22/07/2025 TC: 
 *		Se agrega que busque por todos los faciales en vez de tenerlo seteado
 *		Se agrega la posibilicad de rehacer solamente la de un controlador si es necesario
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Cliente			INT
DECLARE @pId_Controlador		INT

SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Controlador			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Controlador')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Id_Controlador			INT
DECLARE @Id_Controlador_Suprema INT
DECLARE @Id_Cliente				INT
DECLARE @Credencial_Nro			VARCHAR(50)
DECLARE @Doc_Nro				VARCHAR(20)
DECLARE @Mensaje				VARCHAR(5000)
DECLARE @Respuesta				INT

DECLARE @Result_Tabla_Stored_Invocado TABLE (
	Flag_Habilitado				TINYINT,
	Mensaje						VARCHAR(5000),
	Info						VARCHAR(101),
	Foto						VARCHAR(256),
	Foto_Bin					IMAGE,
	Id_Cliente					INT,
	Id_Cliente_Ref				INT,
	Tiempo_Mensaje				SMALLINT
)

DECLARE @Fecha_Actual			DATETIME = GETDATE()
DECLARE @Sql					NVARCHAR(MAX)
DECLARE @Sql_Delete				NVARCHAR(MAX)
/*FIN Variables Locales*/

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a Stored Procedure: CPJU_Lista_Blanca_Suprema_Socios'
	PRINT 'Parametros:' + @pJson
END

-- Creo tabla temporal
CREATE TABLE #Lista_Blanca (
	Id_Cliente INT,
	Doc_Nro BIGINT, 
	Credencial_Nro VARCHAR(30),
	Id_Controlador INT,
	Suprema_Grupo_Id INT,
	Mensaje VARCHAR(5000),
	Habilitado TINYINT
)

-- Creo indice para tabla temporal
CREATE INDEX IXXXX_Lista_Blanca ON #Lista_Blanca (Id_Cliente)

SET @Sql_Delete = 'DELETE FROM CD_Lista_Blanca_Suprema WHERE 1=1'

SET @Sql = 'INSERT INTO #Lista_Blanca
			SELECT C.Id_Cliente, C.Doc_Nro, C.Credencial_Nro, CON.Id_Controlador, CON.Suprema_Grupo_Id, '''' AS Mensaje, 1 AS Habilitado
				FROM Clientes C, Clientes_Fotos F, CD_Controladores CON
					WHERE C.Id_Cliente = F.Id_Cliente
					AND F.Foto IS NOT NULL
					AND F.Nro = 1
					AND C.Activo = 1
					AND C.Doc_Nro > 1000000
					AND C.Tipo_Persona = ''F''
					AND CON.Activo = 1
					AND CON.Suprema_Grupo_Id <> 0'

IF(@pId_Cliente <> 0)
BEGIN
	SET @Sql_Delete += ' AND Id_Cliente = ' + CAST(@pId_Cliente AS VARCHAR)

	SET @Sql += ' AND C.Id_Cliente = ' + CAST(@pId_Cliente AS VARCHAR)
END

IF(@pId_Controlador <> 0)
BEGIN

	SET @Id_Controlador_Suprema = (SELECT Suprema_Grupo_id FROM CD_Controladores WHERE Id_Controlador = @pId_Controlador)

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Id_Controlador_Suprema: ' + CAST(@Id_Controlador_Suprema AS VARCHAR)
	END

	-- Compruebo que el id de suprema exista
	IF(@Id_Controlador_Suprema IS NULL OR @Id_Controlador_Suprema = 0)
	BEGIN
		RETURN
	END

	SET @Sql_Delete += ' AND Id_Grupo_Suprema = ' + CAST(@Id_Controlador_Suprema AS VARCHAR)

	SET @Sql += ' AND CON.Id_Controlador = ' + CAST(@pId_Controlador AS VARCHAR)
END

IF(@pModoDebug = 1)
BEGIN
	PRINT '--------------- QUERY LIMPIEZA LISTA BLANCA ---------------'
	PRINT @Sql_Delete
END

-- Limpio la tabla de CD_Lista_Blanca_Suprema
EXEC(@Sql_Delete)

IF(@pModoDebug = 1)
BEGIN
	PRINT '--------------- QUERY CREACION DE TABLA TEMPORAL ---------------'
	PRINT @Sql
END

-- Cargo la tabla temporal
EXEC(@Sql)

IF(@pModoDebug = 1)
BEGIN
	PRINT '--------------- INICIO DE CURSOR ---------------'
END

-- Cursor para consultar por socio y controlador si esta habilitado
DECLARE CPJU_Lista_Blanca_Suprema_Socios CURSOR FOR
SELECT Id_Cliente, Doc_Nro, Credencial_Nro, Id_Controlador, Suprema_Grupo_Id FROM #Lista_Blanca WHERE Habilitado = 1

OPEN CPJU_Lista_Blanca_Suprema_Socios
FETCH NEXT FROM CPJU_Lista_Blanca_Suprema_Socios INTO @Id_Cliente, @Doc_Nro, @Credencial_Nro, @Id_Controlador, @Id_Controlador_Suprema
WHILE @@FETCH_STATUS = 0
BEGIN

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Id_Cliente AQUI: ' + CAST(@Id_Cliente AS VARCHAR)
		PRINT 'Credencial AQUI: ' + CAST(@Credencial_Nro AS VARCHAR)
		PRINT 'Id_Controlador AQUI: ' + CAST(@Id_Controlador AS VARCHAR)
		PRINT 'Fecha_Actual AQUI: ' + CAST(@Fecha_Actual AS VARCHAR)
	END

	DELETE @Result_Tabla_Stored_Invocado

	-- Si no tiene credencial uso el nro de documento
	IF(ISNULL(@Credencial_Nro, '') = '')
	BEGIN
		SET @Credencial_Nro = CAST(@Doc_Nro AS varchar(30))
	END

	-- Consulta si esta habilitado para pasar
	INSERT INTO @Result_Tabla_Stored_Invocado EXEC dbo.CP_SCA_RegistrarAcceso @Id_Controlador,
									'E',
									@Fecha_Actual,
									'19000101',
									@Credencial_Nro,
									0,
									'',
									'',
									'',
									0,
									0,
									0

	SELECT TOP 1 @Respuesta = Flag_Habilitado, @Mensaje = Mensaje 
	FROM @Result_Tabla_Stored_Invocado

	PRINT 'RESPUESTA: ' + CAST(@Respuesta AS VARCHAR)
	PRINT '@Id_Cliente: ' + CAST(@Id_Cliente AS VARCHAR)

	-- Si esta habilitado y no esta en la lista blanca lo agrego
	IF @Respuesta = 1
	BEGIN
		UPDATE #Lista_Blanca SET Mensaje = @Mensaje  WHERE Id_Cliente = @Id_Cliente AND Id_Controlador = @Id_Controlador AND Suprema_Grupo_Id = @Id_Controlador_Suprema
		PRINT 'INSERTO EN LISTA BLANCA 0'
		IF NOT EXISTS (
			SELECT 1 
			FROM CD_Lista_Blanca_Suprema 
			WHERE Id_Cliente = @Id_Cliente
		)
		BEGIN
			PRINT 'INSERTO EN LISTA BLANCA'
			INSERT INTO CD_Lista_Blanca_Suprema (Id_Grupo_Suprema, Fecha_Proceso, Id_Cliente, Mensaje)
			VALUES (@Id_Controlador_Suprema, GETDATE(), @Id_Cliente, @Mensaje)
		END
		ELSE
		BEGIN
			PRINT 'NO INSERTO EN LISTA BLANCA'
		END
	END
	ELSE
	-- Si no fue habilitado no lo agrego a la lista blanca
	BEGIN
		PRINT 'UPDATE EN #LISTA BLANCA'
		UPDATE #Lista_Blanca SET Habilitado = 0, Mensaje = @Mensaje WHERE Id_Cliente = @Id_Cliente AND Id_Controlador = @Id_Controlador AND Suprema_Grupo_Id = @Id_Controlador_Suprema
	END

	FETCH NEXT FROM CPJU_Lista_Blanca_Suprema_Socios INTO @Id_Cliente, @Doc_Nro, @Credencial_Nro, @Id_Controlador, @Id_Controlador_Suprema
END
CLOSE CPJU_Lista_Blanca_Suprema_Socios
DEALLOCATE CPJU_Lista_Blanca_Suprema_Socios

IF(@pModoDebug = 1)
BEGIN
	PRINT '--------------- FIN DE CURSOR ---------------'
END

