CREATE PROCEDURE [dbo].CPJ_AR_Fact_Apocrifas_Import @pJson VARCHAR(8000)
AS

/*Parametros */
DECLARE @Archivo VARCHAR(1000)

DECLARE @Mensaje			VARCHAR(100)
		,@sql				NVARCHAR(4000)
		,@cant				INT
		,@Fecha				VARCHAR(10)
		,@Fecha_Pub			VARCHAR(10)
		,@Cuit				VARCHAR(19)
		,@Descripcion		VARCHAR(500)
		,@xParametro		TINYINT
		
/*Fin de Parametros*/

SET @Archivo	 = ISNULL(CONVERT(VARCHAR(1000)	, dbo.CF_JSON_VALUE(@pJson,'Archivo')), '')
SET @xParametro	 = (SELECT dbo.CF_xParam('Afip_Fact_Apocri'))

IF (@Archivo = '')
BEGIN	
	SET @cant		= 0;
	SET @Mensaje	= 'Archivo Vaacio';

	SELECT	 0					AS ErrorNumber 
		,0					AS ErrorSeverity  
		,0					AS ErrorState 
		,0					AS ErrorProcedure  
		,@cant 				AS ErrorLine		
		,@Mensaje			AS ErrorMessage

	RETURN;
END 

IF (@xParametro = 0)
BEGIN
	SET @cant = 0;
	SET @Mensaje	= 'Funci├│n Deshabilitada por xParametro: Afip_Fact_Apocri';

	SELECT	 0					AS ErrorNumber 
		,0					AS ErrorSeverity  
		,0					AS ErrorState 
		,0					AS ErrorProcedure  
		,@cant 				AS ErrorLine		
		,@Mensaje			AS ErrorMessage

	RETURN;
END


BEGIN TRY
BEGIN TRAN

SET @cant = 0
 
CREATE TABLE #AR_AFIP_Fact_Apocrifas_Import (Linea VARCHAR(500) )
 
SET @sql = 'BULK INSERT #AR_AFIP_Fact_Apocrifas_Import
		FROM '''+ @Archivo + '''
		WITH ( DATAFILETYPE =''char'' ,FIELDTERMINATOR= ''|'', ROWTERMINATOR = ''0x0a'' );'

EXEC (@sql)


DELETE AR_AFIP_Fact_Apocrifas


DECLARE curTabCarga CURSOR FOR
SELECT  CAST(SUBSTRING(Linea,0,12)   AS VARCHAR(19)) AS 'Cuit'
					,CAST(SUBSTRING(Linea,13,10)  AS VARCHAR(10)) AS 'Fecha'
					,CAST(SUBSTRING(Linea,24,10)  AS VARCHAR(10)) AS 'Fecha_Pub'
					,CAST(SUBSTRING(Linea,36,500) AS varchar(500)) AS 'Descripcion'
FROM #AR_AFIP_Fact_Apocrifas_Import 
WHERE Linea NOT LIKE '%#%'

OPEN curTabCarga
FETCH NEXT FROM curTabCarga INTO  @Cuit, @Fecha, @Fecha_Pub, @Descripcion
WHILE @@FETCH_STATUS = 0
BEGIN
	

		PRINT 'CUIT: ' + @Cuit

		SET @Fecha =		(SELECT dbo.SF_CortarCadena (@Fecha, '/',3)		+  dbo.SF_CortarCadena (@Fecha, '/',2)		+  dbo.SF_CortarCadena (@Fecha, '/',1))
		PRINT 'FECHA: ' + @Fecha

		SET @Fecha_Pub =	(SELECT dbo.SF_CortarCadena (@Fecha_Pub, '/',3) +  dbo.SF_CortarCadena (@Fecha_Pub, '/',2)	+  dbo.SF_CortarCadena (@Fecha_Pub, '/',1))
		PRINT '@Fecha_Pub: ' + @Fecha_Pub

		INSERT INTO AR_AFIP_Fact_Apocrifas (Cuit,	Fecha,					Fecha_Pub,					Descripcion)
									VALUES  (@Cuit, CONVERT(DATE,@Fecha),	CONVERT(DATE,@Fecha_Pub),	@Descripcion)

	SET @cant += 1


FETCH NEXT FROM curTabCarga INTO @Cuit, @Fecha, @Fecha_Pub, @Descripcion
END
CLOSE curTabCarga
DEALLOCATE curTabCarga;


SET @Mensaje = CONVERT(VARCHAR(10),@cant) + ' Registros Importados'
DROP TABLE #AR_AFIP_Fact_Apocrifas_Import


COMMIT
SELECT	 0					AS ErrorNumber 
		,0					AS ErrorSeverity  
		,0					AS ErrorState 
		,0					AS ErrorProcedure  
		,@cant 				AS ErrorLine		
		,@Mensaje			AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;   

/*
EXEC DBO.CPJ_AR_Fact_Apocrifas_Import '{"Archivo":"C:\Users\soporte\Downloads\FacturasApocrifas.txt"}'
*/
GO



CREATE  PROCEDURE [dbo].[CPJ_AR_Padron_IIBB_Import] @pJson VARCHAR(8000)
AS

/*Parametros */

DECLARE  @Id_Tipo_Reten VARCHAR(10)
		,@Id_Tipo_Percep VARCHAR(10)
		,@Archivo VARCHAR(1000)
		,@Provincia INT
		
/*
0	Ciudad AutÔö£Ôöénoma de Buenos Aires
1	Buenos Aires
2	Catamara
3	CÔö£Ôöérdoba
4	Corrientes
5	Entre RÔö£┬íos
6	Jujuy
7	Mendoza
8	La Rioja
9	Salta
10	San Juan
11	San Luis
12	Santa Fe
13	Santiago del Estero
14	TucumÔö£├¡n
16	Chaco
17	Chubut
18	Formosa
19	Misiones
20	NeuquÔö£┬«n
21	La Pampa
22	RÔö£┬ío Negro
23	Santa Cruz
24	Tierra del Fuego
*/

SET @Id_Tipo_Reten		= ISNULL(CONVERT(VARCHAR(10)	, dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Reten')),'')
SET @Id_Tipo_Percep		= ISNULL(CONVERT(VARCHAR(10)	, dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Percep')),'')
SET @Archivo			= ISNULL(CONVERT(VARCHAR(1000)	, dbo.CF_JSON_VALUE(@pJson,'Archivo')), '')
SET @Provincia			= ISNULL(CONVERT(INT			, dbo.CF_JSON_VALUE(@pJson,'Provincia')), 0)

IF @Id_Tipo_Reten = '' AND @Id_Tipo_Percep = '' RETURN
IF @Archivo = ''								RETURN
/*************************** Fin de Parametros *****************************/

DECLARE @Mensaje			VARCHAR(100)
		,@sql NVARCHAR(4000)
		,@cant INT


BEGIN TRY
BEGIN TRAN

SET @cant = 0
 
CREATE TABLE #AR_Padron_IIBB_Temp (Linea VARCHAR(500) )
 
SET @sql = 'BULK INSERT #AR_Padron_IIBB_Temp
		FROM '''+ @Archivo + '''
		WITH ( DATAFILETYPE =''char'' ,FIELDTERMINATOR= ''|'', ROWTERMINATOR = ''0x0a'' );'

EXEC (@sql)



IF @Provincia = 0  --CABA
BEGIN
	IF ISNULL(@Id_Tipo_Percep,'') <> ''
	BEGIN
	    DELETE AR_Padron_IIBB WHERE Id_Tipo_Reten = @Id_Tipo_Percep
		INSERT INTO AR_Padron_IIBB
			SELECT CAST(SUBSTRING(Linea,28,11) AS VARCHAR(19))
				,@Id_Tipo_Percep,GETDATE()
				,0
				,CAST(SUBSTRING(Linea,46,1) +'.' + SUBSTRING(Linea,48,2) AS DECIMAL(7,2))     
				FROM #AR_Padron_IIBB_Temp
	END

	IF ISNULL(@Id_Tipo_Reten,'') <> ''
	BEGIN
	    DELETE AR_Padron_IIBB WHERE Id_Tipo_Reten = @Id_Tipo_Reten
		INSERT INTO AR_Padron_IIBB
			SELECT CAST(SUBSTRING(Linea,28,11) AS VARCHAR(19))
				,@Id_Tipo_Reten,GETDATE()
				,0
				,CAST(SUBSTRING(Linea,51,1) +'.' + SUBSTRING(Linea,53,2) AS DECIMAL(7,2))
				FROM #AR_Padron_IIBB_Temp
	END

END




IF @Provincia = 1  --Buenos Aires
BEGIN
	IF ISNULL(@Id_Tipo_Reten,'') <> ''
	BEGIN
	    DELETE AR_Padron_IIBB WHERE Id_Tipo_Reten = @Id_Tipo_Reten
		INSERT INTO AR_Padron_IIBB
			SELECT CAST(SUBSTRING(Linea,30,11) AS VARCHAR(19))
				,@Id_Tipo_Reten,GETDATE()
				,0
				,CAST(SUBSTRING(Linea,48,1) +'.' + SUBSTRING(Linea,50,2) AS DECIMAL(7,2))
				FROM #AR_Padron_IIBB_Temp
	END

	IF ISNULL(@Id_Tipo_Percep,'') <> ''
	BEGIN
	    DELETE AR_Padron_IIBB WHERE Id_Tipo_Reten = @Id_Tipo_Percep
		INSERT INTO AR_Padron_IIBB
			SELECT CAST(SUBSTRING(Linea,30,11) AS VARCHAR(19))
				,@Id_Tipo_Percep,GETDATE()
				,0
				,CAST(SUBSTRING(Linea,48,1) +'.' + SUBSTRING(Linea,50,2) AS DECIMAL(7,2))
				FROM #AR_Padron_IIBB_Temp
	END
END



IF ISNULL(@Id_Tipo_Percep,'') <> ''
BEGIN
	DELETE FROM Clientes_Reten WHERE Id_Tipo_Reten = @Id_Tipo_Percep
	INSERT INTO Clientes_Reten
		SELECT B.Id_Cliente , @Id_Tipo_Percep,A.Porc,A.Coef 
				FROM [dbo].[AR_Padron_IIBB] A, Clientes B 
				WHERE A.Cuit = B.Cuit AND A.Id_Tipo_Reten = @Id_Tipo_Percep
   SELECT @cant = COUNT(*) FROM Clientes_Reten WHERE Id_Tipo_Reten = @Id_Tipo_Percep

END 

IF ISNULL(@Id_Tipo_Reten,'') <> ''
BEGIN
	DELETE FROM Proveedores_Reten where Id_Tipo_Reten = @Id_Tipo_Reten
	INSERT INTO Proveedores_Reten
		SELECT B.Id_Proveedor , @Id_Tipo_Reten,A.Porc,A.Coef , NULL, NULL
				FROM [dbo].[AR_Padron_IIBB] A, Proveedores B 
				WHERE A.Cuit = B.Cuit AND A.Id_Tipo_Reten = @Id_Tipo_Reten
	SELECT @cant += COUNT(*) FROM Proveedores_Reten WHERE Id_Tipo_Reten = @Id_Tipo_Reten

END 

SET @Mensaje = CONVERT(VARCHAR(10),@cant) + ' Registros Importados'
DROP TABLE #AR_Padron_IIBB_Temp

COMMIT
SELECT	 0					AS ErrorNumber 
		,0					AS ErrorSeverity  
		,0					AS ErrorState 
		,0					AS ErrorProcedure  
		,@cant 				AS ErrorLine		
		,@Mensaje			AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;   

/*

