DECLARE @Param VARCHAR(5000)

SET @Param = '{' +
			'"Fecha_Desde":"",' +
			'"Fecha_Hasta":"",' +
			'"Id_Plan_Cta":"10",' +
			'"ModoDebug":"1"' +
			'}'

EXEC CPJ_Asientos_Numerar @Param

*/
GO

CREATE PROCEDURE [dbo].[CPJ_Asientos_Renumerar] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON

DECLARE @pFecha_Desde		DATETIME
			 ,@pFecha_Hasta		DATETIME	
			,@pId_Plan_Cta			INT
			,@pModoDebug			TINYINT
			,@pId_Usuario			SMALLINT
-------------------------------------------------------------------------------

DECLARE 	@pId_Asiento				INT
				,@Metodo					INT
				,@Sql						NVARCHAR(MAX)
				,@Cantidad				INT
				,@ProxNro					INT
				,@Mensaje				VARCHAR(100)
				,@UltError					INT
				--,@pId_Plan_Cta			INT


SET @pFecha_Desde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Desde')),GETDATE())
SET @pFecha_Hasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Hasta')),GETDATE())
SET @pId_Usuario					= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Usuario')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)
SET @pId_Plan_Cta				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Plan_Cta')), 0)


--------------------------------------------------------------------------
BEGIN TRY
BEGIN TRAN

IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Asientos_Renumerar'
		PRINT 'Parametros: '+ @pJsonRecibido  
		PRINT '@pId_Plan_Cta: ' + CONVERT(VARCHAR(4),@pId_Plan_Cta)
	END

SET @Cantidad = 0
SET @Metodo = 	dbo.CF_xParam('Tipo_Numero_Asiento')

CREATE TABLE #Asiento (Id_Asiento INT)

SET @Sql = 'INSERT INTO #Asiento
					SELECT A.ID_ASIENTO FROM ASIENTOS A, ASIENTOS_TIPOS T WHERE A.Id_Plan_Cta =' + CONVERT(VARCHAR(10), @pId_Plan_Cta) +
                                             'AND A.Id_Tipo_Asi =  T.Id_Tipo_Asi' 
                                                                               
 
IF @Metodo =2
BEGIN                                             
		SET @Sql =	RTRIM(LTRIM(@Sql)) + CHAR(13) + 
					'AND A.Fecha >= ''' + CONVERT(VARCHAR(10), @pFecha_Desde, 112) + ''' '
					
		SET @Sql =	RTRIM(LTRIM(@Sql)) + CHAR(13) + 
					'AND A.Fecha < ''' + CONVERT(VARCHAR(10), DATEADD(DAY, 1, @pFecha_Hasta), 112) + ''' ' 
END	

SET @Sql = RTRIM(LTRIM(@Sql)) + CHAR(13) + 'ORDER BY A.Fecha,A.Id_Tipo_Asi,A.Id_Asiento'			

	                                            

IF @pModoDebug = 1 PRINT @Sql
			

EXEC sp_executesql @Sql

ALTER TABLE #Asiento ADD Numero INT IDENTITY(1,1)

-- SELECT * FROM #Asiento

/*------------------------------------------------------------------------------------------------------------------------------------------------*/

IF @Metodo =1
BEGIN 
	UPDATE Asientos SET Nro = Numero FROM #Asiento z, Asientos a WHERE a.Id_asiento=z.ID_ASIENTO 
END
ELSE
BEGIN
		
		SET @ProxNro = (SELECT ISNULL(MAX(Nro),0) + 1 as Nro 
								   FROM Asientos
									WHERE Id_Plan_Cta = @pId_Plan_Cta 
		   	    					AND DATEPART(mm,@pFecha_Desde) = DATEPART(mm,Fecha)
								    AND DATEPART(yy,@pFecha_Hasta) = DATEPART(yy,Fecha))
		SET @Cantidad = (SELECT COUNT(*) FROM  #Asiento)						    
		PRINT '@Cantidad ' + CONVERT(VARCHAR(2),@Cantidad)
		PRINT '@ProxNro ' + CONVERT(VARCHAR(2),@ProxNro)
		WHILE 	@Cantidad > 0
		BEGIN 
				UPDATE #Asiento SET Numero = @ProxNro 
				SET @ProxNro = @ProxNro +1
				SET @Cantidad -= 1
				PRINT '@Cantidad ' + CONVERT(VARCHAR(2),@Cantidad)
		END	
		UPDATE Asientos SET Nro=@ProxNro FROM Asientos a, #Asiento z WHERE a.Id_asiento=z.Id_asiento	     
END

DROP TABLE #Asiento

COMMIT
SELECT	 0						AS ErrorNumber 
			,0						AS ErrorSeverity  
			,0						AS ErrorState 
			,0						AS ErrorProcedure  
			,@Cantidad 		AS ErrorLine		
			,@Mensaje		AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;   





/*

DECLARE @Param VARCHAR(5000)

SET @Param = '{' +
			'"Fecha_Desde":"20220101",' +
			'"Fecha_Hasta":"20221231",' +
			'"Id_Plan_Cta":"143",' +
			'"ModoDebug":"1"' +
			'}'

EXEC CPJ_Asientos_Renumerar @Param

*/
GO

 

create PROCEDURE [dbo].[CPJ_BalanceCC_Pagos_Rpt]	@pJson VARCHAR(8000)
AS
SET NOCOUNT ON

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug			    	TINYINT
DECLARE @pId_Usuario			    SMALLINT
DECLARE @pFecha_Desde			    DATETIME
DECLARE @pFecha_Hasta			    DATETIME
DECLARE @pId_Centro_Costo			CHAR(10)
DECLARE @pId_Alias_Cta_Cont			SMALLINT
DECLARE @pId_Plan_Cta			    INT
DECLARE @pId_Unid_Negocio			CHAR(10)
DECLARE @pSoloResultado	    		TINYINT			--10/05/2021
DECLARE @pFlag_FiltrarId_CC			TINYINT			--10/05/2021
DECLARE @pTipo_Reporte				VARCHAR(10)		--13/05/2021

SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Usuario				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), 0)
SET @pFecha_Desde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde')), '19000101')
SET @pFecha_Hasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta')), '19000101')
SET @pId_Centro_Costo			= ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Centro_Costo')), '')
SET @pId_Alias_Cta_Cont			= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Alias_Cta_Cont')), 0)
SET @pId_Plan_Cta				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Plan_Cta')), 0)
SET @pId_Unid_Negocio			= ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Unid_Negocio')), '')
SET @pSoloResultado				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'SoloResultado')), 0)
SET @pFlag_FiltrarId_CC			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_FiltrarId_CC')), 0)
SET @pTipo_Reporte				= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Tipo_Reporte')), 'AGRUP')
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @SqlStr						NVARCHAR(MAX)
DECLARE @Id_Trans					INT
DECLARE @Alias						DECIMAL(12,0)
DECLARE @Nro_Cta_Contable			VARCHAR(20)
DECLARE @Debe						DECIMAL(12,2)
DECLARE @Haber						DECIMAL(12,2)
DECLARE @Fecha						DATETIME
DECLARE @Descripcion				VARCHAR(80)
DECLARE @Centro_Costo				VARCHAR(200)
DECLARE @Centro_Costo_Padre1		VARCHAR(200)
DECLARE @Centro_Costo_Padre2		VARCHAR(200)
DECLARE @Destinatario				VARCHAR(100)
DECLARE @Observacion_Orig			VARCHAR(8000)
DECLARE @Observacion_Dest			VARCHAR(8000)
DECLARE @Importe					DECIMAL(12,2)
DECLARE @Imp_Total_Fac				DECIMAL(12,2)
DECLARE @Imp_Aplicado				DECIMAL(12,2)
DECLARE @Imp_Fac					DECIMAL(12,2)
DECLARE @Coef_Aplic					DECIMAL(12,2)
DECLARE @Id_Trans_CCC				INT
DECLARE @Id_Centro_Costo_Padre1		CHAR(10)
DECLARE @Id_Centro_Costo_Padre2		CHAR(10)
DECLARE @Mes_Desde					DATETIME
DECLARE @Mes_Hasta					DATETIME
DECLARE @Mes_Nro					TINYINT
DECLARE @Suma_Debe					DECIMAL(16,2)
DECLARE @Suma_Haber					DECIMAL(16,2)
DECLARE @Suma_Saldo					DECIMAL(16,2)
DECLARE @Id_Centro_Costo			CHAR(10)
DECLARE @Id_Centro_Costo_Cur		CHAR(10)
DECLARE @Id_Ejercicio				INT
DECLARE @Ejercicio_Fecha_Inicio		DATETIME
DECLARE @Ejercicio_Fecha_Cierre		DATETIME
DECLARE @Fecha_Saldo_Anterior		DATETIME
DECLARE @Mes_Saldo_Anterior			TINYINT
/*FIN Variables Locales*/

BEGIN TRY
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_BalanceCC_Rpt'
		PRINT 'Parametros: '
		PRINT '@pTipo_Reporte: ' + @pTipo_Reporte
		PRINT '@pId_Usuario: ' + CONVERT(VARCHAR(10), @pId_Usuario) + '. @pFecha_Desde: ' + CONVERT(VARCHAR(10), @pFecha_Desde, 112) + '. @pFecha_Hasta: ' + CONVERT(VARCHAR(10), @pFecha_Hasta, 112) + '. @pId_Centro_Costo: ' + CONVERT(VARCHAR(10), @pId_Centro_Costo)
		PRINT '@pId_Unid_Negocio: ' + @pId_Unid_Negocio + '. @pSoloResultado: ' + CONVERT(VARCHAR(10), @pSoloResultado) + '. @pFlag_FiltrarId_CC: ' + CONVERT(VARCHAR(10), @pFlag_FiltrarId_CC)
	END

	/*=============================================================================================================================*/
	/*=============================================================================================================================*/

	IF(@pId_Usuario = 0)
	BEGIN
		SET @pId_Usuario = -1
	END
	
	IF(@pTipo_Reporte = '')										RAISERROR ('Tipo_Reporte can not be blank.', 16,  1)
	IF(@pFecha_Desde = '19000101')								RAISERROR ('Fecha_Desde can not be blank.', 16,  1)
	IF(@pFecha_Hasta = '19000101')								RAISERROR ('Fecha_Hasta can not be blank.', 16,  1) 
	IF(@pFecha_Desde >= @pFecha_Hasta)							RAISERROR ('Fecha_Desde can not be bigger or equal than Fecha_Hasta.', 16,  1)
	IF(DATEDIFF(YEAR, @pFecha_Desde, @pFecha_Hasta) > 0)		RAISERROR ('Diference between Fecha_Desde and Fecha_Hasta can not be bigger than a year.', 16,  1) 
	
	IF(@pFlag_FiltrarId_CC <> 0)
	BEGIN
		IF(@pId_Centro_Costo = '')									RAISERROR ('Id_Centro_Costo can not be blank.', 16,  1)
	END

	IF(@pTipo_Reporte = 'EXPLO')
	BEGIN
		IF(@pId_Alias_Cta_Cont = 0)										RAISERROR ('Id_Alias_Cta_Cont can not be zero for this type of report.', 16,  1)
		IF(@pId_Centro_Costo = '')										RAISERROR ('Id_Centro_Costo can not be blank for this type of report.', 16,  1)
		IF(@pFlag_FiltrarId_CC = 0)										RAISERROR ('Flag_FiltrarId_CC can not be zero for this type of report.', 16,  1)		
	END

	--18/08/2021 Gabriel nos dijo que si viene una cuenta contable no tiene que tomar solo los de resultado tildes o no tildes en el erp web (modules/accounting/balanceccfinan.php)
	IF(@pId_Alias_Cta_Cont <> 0)
	BEGIN
		SET @pSoloResultado = 0
	END
	
	/*=============================================================================================================================*/

	IF(@pFlag_FiltrarId_CC <> 0)
	BEGIN
		SET @Id_Centro_Costo = @pId_Centro_Costo

		SELECT
		@Centro_Costo = ISNULL(Descripcion, ''),
		@Id_Centro_Costo_Padre1 = ISNULL(Id_Centro_Costo_Padre, '')
		FROM Centro_Costos
		WHERE
		Id_Centro_Costo = @pId_Centro_Costo

		SELECT
		@Centro_Costo_Padre1 = ISNULL(Descripcion, ''),
		@Id_Centro_Costo_Padre2 = ISNULL(Id_Centro_Costo_Padre, '')
		FROM Centro_Costos
		WHERE
		Id_Centro_Costo = @Id_Centro_Costo_Padre1

		SELECT
		@Centro_Costo_Padre2 = ISNULL(Descripcion, '')
		FROM Centro_Costos
		WHERE
		Id_Centro_Costo = @Id_Centro_Costo_Padre2
	END

	/*=============================================================================================================================*/

	SELECT
	@Id_Ejercicio			= ISNULL(Id_Ejercicio, 0)
	FROM Plan_Ctas
	WHERE
	Id_Plan_Cta = @pId_Plan_Cta

	SELECT 
	@Ejercicio_Fecha_Inicio = ISNULL(Fecha_Inicio, '19000101'),
	@Ejercicio_Fecha_Cierre	= ISNULL(Fecha_Cierre, '19000101')
	FROM Plan_Ctas_Ejercicios
	WHERE
	Id_Ejercicio = @Id_Ejercicio

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Id_Ejercicio: ' + CONVERT(VARCHAR(10), @Id_Ejercicio) + '. @Ejercicio_Fecha_Inicio: ' + CONVERT(VARCHAR(10), @Ejercicio_Fecha_Inicio, 102) + '. @Ejercicio_Fecha_Cierre: ' + CONVERT(VARCHAR(10), @Ejercicio_Fecha_Cierre, 102)
	END

	/*=============================================================================================================================*/
	
	CREATE TABLE #Rpt_BalanceCC
	(
	Id_Trans_O						INT,
	Id_Trans_D						INT,
	Alias							DECIMAL(12,0),
	Nro_Cta_Contable				VARCHAR(20),
	Debe							DECIMAL(12,2),
	Haber							DECIMAL(12,2),
	Saldo							DECIMAL(12,2),
	Fecha							DATETIME,
	Cta_Contable					VARCHAR(80),
	Id_Centro_Costo					VARCHAR(10),
	Centro_Costo					VARCHAR(200),
	Centro_Costo2					VARCHAR(200),
	Centro_Costo3					VARCHAR(200),
	Destinatario					VARCHAR(100),
	Observacion_Orig				VARCHAR(8000),
	Observacion_Dest				VARCHAR(8000)
	)

	/*=============================================================================================================================*/

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Recibos OP Varias'
	END

	CREATE TABLE #Rpt_BalanceCC_OP_Varias
	(
	Id_Trans						INT,
	Alias							DECIMAL(12,0),
	Nro_Cta_Contable				VARCHAR(20),
	Debe							DECIMAL(12,2),
	Haber							DECIMAL(12,2),
	Fecha							DATETIME,
	Descripcion						VARCHAR(80),
	Destinatario					VARCHAR(100),
	Observacion_Orig				VARCHAR(8000),
	Observacion_Dest				VARCHAR(8000),
	Id_Centro_Costo					VARCHAR(10)
	)
	
	/*=============================================================================================================================*/

	SET @SqlStr =	'INSERT INTO #Rpt_BalanceCC_OP_Varias (Id_Trans, Alias, Nro_Cta_Contable, Debe, Haber, Fecha, Descripcion, Destinatario, Observacion_Orig, Observacion_Dest, Id_Centro_Costo) '

	SET @SqlStr =	RTRIM(LTRIM(@SqlStr))										+ CHAR(13) + 
					'SELECT '													+ CHAR(13) + 
					'C.Id_Trans, '												+ CHAR(13) + 
					'O.Alias, '													+ CHAR(13) + 
					'O.Nro_Cta_Contable, '										+ CHAR(13) + 
					'C.Debe, '													+ CHAR(13) + 
					'C.Haber, '													+ CHAR(13) + 
					'E.Fecha, '													+ CHAR(13) + 
					'O.Descripcion AS Cta_Contable, '							+ CHAR(13) + 
					'ISNULL(E.Destinatario, '''') AS Destinatario, '			+ CHAR(13) + 
					'ISNULL(CONVERT(VARCHAR(8000), E.Observacion), '''') AS Observacion_Orig, '+ CHAR(13) + 
					'ISNULL(CONVERT(VARCHAR(8000), E.Observacion), '''') AS Observacion_Dest, '+ CHAR(13) +
					'ISNULL(C.Id_Centro_Costo, '''') AS Id_Centro_Costo '		+ CHAR(13) +
					'FROM Cbtes_Ctas_Contables C, Cbtes E,Cbtes_Tipos T,Pla_Ctas_Cuentas_Contables O ' + CHAR(13) + 
					'WHERE '													+ CHAR(13) + 
					'C.Id_Trans = E.Id_Trans '									+ CHAR(13) + 
					'AND E.Id_Tipo_Cbte = T.Id_Tipo_Cbte '						+ CHAR(13) + 	
					'AND O.Id_Cta_Contable = C.Id_Cta_Contable '				+ CHAR(13) +
					'AND ISNULL(E.Id_Proveedor, 0) = 0 '						+ CHAR(13) + 					
					'AND E.Id_Estado_Cbte NOT IN (0,3) '
					
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND E.Fecha >= ''' + CONVERT(VARCHAR(10), @Ejercicio_Fecha_Inicio, 112) + ''' '
--					'AND E.Fecha >= ''' + CONVERT(VARCHAR(10), @pFecha_Desde, 112) + ''' '
					
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND E.Fecha < ''' + CONVERT(VARCHAR(10), DATEADD(DAY, 1, @pFecha_Hasta), 112) + ''' '

	IF(@pFlag_FiltrarId_CC <> 0)
	BEGIN		
		SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
						'AND C.Id_Centro_Costo = ''' + @pId_Centro_Costo + ''' '
	END
	
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND T.Compromete_Pagos IN (1,-1)'

	IF(@pSoloResultado = 1)
	BEGIN
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) +
					'AND ISNULL(O.Tipo, '''') IN (''+'',''-'') '
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT ''
		PRINT '@SqlStr (Orden Pagos Varias): '
		PRINT @SqlStr
		PRINT ''
	END

	EXECUTE sp_executesql @SqlStr

	/*=============================================================================================================================*/

	DECLARE cur_BalanceCC_OP_Varias CURSOR FOR
	SELECT 
	Id_Trans,
	Alias,
	Nro_Cta_Contable, 
	Debe, 
	Haber, 
	Fecha, 
	Descripcion,
	Destinatario,
	Observacion_Orig,
	Observacion_Dest,
	Id_Centro_Costo
	FROM #Rpt_BalanceCC_OP_Varias

	OPEN cur_BalanceCC_OP_Varias
	FETCH NEXT FROM cur_BalanceCC_OP_Varias INTO @Id_Trans, @Alias, @Nro_Cta_Contable, @Debe, @Haber, @Fecha, @Descripcion, @Destinatario, @Observacion_Orig, @Observacion_Dest, @Id_Centro_Costo_Cur
	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF(@pFlag_FiltrarId_CC = 0)
		BEGIN
			SET @Id_Centro_Costo = @Id_Centro_Costo_Cur

			SELECT
			@Centro_Costo = ISNULL(Descripcion, ''),
			@Id_Centro_Costo_Padre1 = ISNULL(Id_Centro_Costo_Padre, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo

			SELECT
			@Centro_Costo_Padre1 = ISNULL(Descripcion, ''),
			@Id_Centro_Costo_Padre2 = ISNULL(Id_Centro_Costo_Padre, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo_Padre1

			SELECT
			@Centro_Costo_Padre2 = ISNULL(Descripcion, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo_Padre2
		END

		INSERT INTO #Rpt_BalanceCC
		(Id_Trans_O,
		Id_Trans_D,
		Alias,
		Nro_Cta_Contable,
		Debe,
		Haber,
		Saldo,
		Fecha,
		Cta_Contable,
		Id_Centro_Costo,
		Centro_Costo,
		Centro_Costo2,
		Centro_Costo3,
		Destinatario,
		Observacion_Orig,
		Observacion_Dest)
		VALUES
		(@Id_Trans,
		0,
		@Alias,
		@Nro_Cta_Contable,
		@Debe,
		@Haber,
		0,
		@Fecha,
		@Descripcion,
		@Id_Centro_Costo,
		@Centro_Costo,
		@Centro_Costo_Padre1,
		@Centro_Costo_Padre2,
		@Destinatario,
		@Observacion_Orig,
		@Observacion_Dest)		

		FETCH NEXT FROM cur_BalanceCC_OP_Varias INTO @Id_Trans, @Alias, @Nro_Cta_Contable, @Debe, @Haber, @Fecha, @Descripcion, @Destinatario, @Observacion_Orig, @Observacion_Dest, @Id_Centro_Costo_Cur
	END
	CLOSE cur_BalanceCC_OP_Varias
	DEALLOCATE cur_BalanceCC_OP_Varias

	/*=============================================================================================================================*/
	/*=============================================================================================================================*/

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'OP Proveedores'
	END

	CREATE TABLE #Rpt_BalanceCC_OP_Proveedores
	(
	Id_Trans_Aplica					INT,
	Importe							DECIMAL(12,2),
	Imp_Total_Fac					DECIMAL(12,2),
	Id_Trans_CCC					INT,
	Alias							DECIMAL(12,0),
	Nro_Cta_Contable				VARCHAR(20),
	Debe							DECIMAL(12,2),
	Haber							DECIMAL(12,2),
	Fecha_OP						DATETIME,
	Descripcion						VARCHAR(80),
	Destinatario					VARCHAR(100),
	Observacion_Orig				VARCHAR(8000),
	Observacion_Dest				VARCHAR(8000),
	Id_Centro_Costo					VARCHAR(10)
	)
	
	/*=============================================================================================================================*/

	SET @SqlStr =	'INSERT INTO #Rpt_BalanceCC_OP_Proveedores (Id_Trans_Aplica, Importe, Imp_Total_Fac, Id_Trans_CCC, Alias, Nro_Cta_Contable, Debe, Haber, Fecha_OP, Descripcion, Destinatario, Observacion_Orig, Observacion_Dest, Id_Centro_Costo) '
	
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr))											+ CHAR(13) + 
					'SELECT '														+ CHAR(13) + 
					'A.Id_Trans, '													+ CHAR(13) + 
					'A.Importe, '													+ CHAR(13) + 
					'Fac.Imp_Total, '												+ CHAR(13) + 
					'OP.Id_Trans, '													+ CHAR(13) + 
					'O.Alias, '														+ CHAR(13) +
					'O.Nro_Cta_Contable, '											+ CHAR(13) + 
					'C.Debe, '														+ CHAR(13) + 
					'C.Haber, '														+ CHAR(13) + 
					'OP.Fecha, '													+ CHAR(13) + 
					'O.Descripcion, '												+ CHAR(13) + 
					'ISNULL(Fac.Destinatario, '''') AS Destinatario, '				+ CHAR(13) + 
					'ISNULL(CONVERT(VARCHAR(8000), Fac.Observacion), '''') AS Observacion_Orig, '+ CHAR(13) + 
					'ISNULL(CONVERT(VARCHAR(8000), OP.Observacion), '''') AS Observacion_Dest, '+ CHAR(13) +
					'ISNULL(C.Id_Centro_Costo, '''') AS Id_Centro_Costo '			+ CHAR(13) +
					'FROM Cbtes_Aplica A,Cbtes_Ctas_Contables C, Cbtes OP,Cbtes Fac,Cbtes_Tipos T,Pla_Ctas_Cuentas_Contables O ' + CHAR(13) + 
					'WHERE '														+ CHAR(13) + 
					'C.id_trans = A.id_trans '										+ CHAR(13) + 
					'AND A.id_trans_D = OP.id_trans '								+ CHAR(13) + 
					'AND Fac.id_trans = C.id_trans '								+ CHAR(13) + 
					'AND OP.id_Tipo_Cbte = T.Id_Tipo_Cbte '							+ CHAR(13) + 
					'AND O.Id_Cta_Contable = C.Id_Cta_Contable '					+ CHAR(13) + 
					'AND OP.Id_Proveedor > 0 '										+ CHAR(13) + 
					'AND OP.Id_Estado_Cbte NOT IN (0,3) '							+ CHAR(13) + 
					'AND Fac.Id_Estado_Cbte NOT IN (0,3) ' 


	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND OP.Fecha >= ''' + CONVERT(VARCHAR(10), @Ejercicio_Fecha_Inicio, 112) + ''' '
--					'AND OP.Fecha >= ''' + CONVERT(VARCHAR(10), @pFecha_Desde, 112) + ''' '
					
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND OP.Fecha < ''' + CONVERT(VARCHAR(10), DATEADD(DAY, 1, @pFecha_Hasta), 112) + ''' '

	IF(@pFlag_FiltrarId_CC <> 0)
	BEGIN
		SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
						'AND C.Id_Centro_Costo = ''' + @pId_Centro_Costo + ''' '
	END

	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND T.Compromete_Pagos IN (1,-1)'

	IF(@pSoloResultado = 1)
	BEGIN
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) +
					'AND ISNULL(O.Tipo, '''') IN (''+'',''-'') '
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT ''
		PRINT '@SqlStr (OP Proveedores): '
		PRINT @SqlStr
		PRINT ''
	END

	EXECUTE sp_executesql @SqlStr

	/*=============================================================================================================================*/

	DECLARE cur_BalanceCC_OP_Proveedores CURSOR FOR
	SELECT 
	Id_Trans_Aplica,
	Id_Trans_CCC,
	Importe,
	Imp_Total_Fac,
	Alias,
	Nro_Cta_Contable, 
	Debe, 
	Haber, 
	Fecha_OP, 
	Descripcion,
	Destinatario,
	Observacion_Orig,
	Observacion_Dest,
	Id_Centro_Costo
	FROM #Rpt_BalanceCC_OP_Proveedores

	OPEN cur_BalanceCC_OP_Proveedores
	FETCH NEXT FROM cur_BalanceCC_OP_Proveedores INTO @Id_Trans, @Id_Trans_CCC, @Importe, @Imp_Total_Fac, @Alias, @Nro_Cta_Contable, @Debe, @Haber, @Fecha, @Descripcion, @Destinatario, @Observacion_Orig, @Observacion_Dest, @Id_Centro_Costo_Cur
	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF(@pFlag_FiltrarId_CC = 0)
		BEGIN
			SET @Id_Centro_Costo = @Id_Centro_Costo_Cur

			SELECT
			@Centro_Costo = ISNULL(Descripcion, ''),
			@Id_Centro_Costo_Padre1 = ISNULL(Id_Centro_Costo_Padre, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo

			SELECT
			@Centro_Costo_Padre1 = ISNULL(Descripcion, ''),
			@Id_Centro_Costo_Padre2 = ISNULL(Id_Centro_Costo_Padre, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo_Padre1

			SELECT
			@Centro_Costo_Padre2 = ISNULL(Descripcion, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo_Padre2
		END

		SET @Imp_Aplicado	= @Importe
		SET @Imp_Fac		= @Imp_Total_Fac
		SET @Coef_Aplic		= @Imp_Aplicado / @Imp_Fac

		INSERT INTO #Rpt_BalanceCC
		(Id_Trans_O,
		Id_Trans_D,
		Alias,
		Nro_Cta_Contable,
		Debe,
		Haber,
		Saldo,
		Fecha,
		Cta_Contable,
		Id_Centro_Costo,
		Centro_Costo,
		Centro_Costo2,
		Centro_Costo3,
		Destinatario,
		Observacion_Orig,
		Observacion_Dest)
		VALUES
		(@Id_Trans_CCC,
		@Id_Trans,
		@Alias,
		@Nro_Cta_Contable,
		@Debe * @Coef_Aplic,
		@Haber * @Coef_Aplic,
		0,
		@Fecha,
		@Descripcion,
		@Id_Centro_Costo,
		@Centro_Costo,
		@Centro_Costo_Padre1,
		@Centro_Costo_Padre2,
		@Destinatario,
		@Observacion_Orig,
		@Observacion_Dest)

		FETCH NEXT FROM cur_BalanceCC_OP_Proveedores INTO @Id_Trans, @Id_Trans_CCC, @Importe, @Imp_Total_Fac, @Alias, @Nro_Cta_Contable, @Debe, @Haber, @Fecha, @Descripcion, @Destinatario, @Observacion_Orig, @Observacion_Dest, @Id_Centro_Costo_Cur
	END
	CLOSE cur_BalanceCC_OP_Proveedores
	DEALLOCATE cur_BalanceCC_OP_Proveedores

	/*=============================================================================================================================*/
	/*=============================================================================================================================*/

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Asientos Manuales'
	END

	CREATE TABLE #Rpt_BalanceCC_AS_Manuales
	(
	Alias							DECIMAL(12,0),
	Nro_Cta_Contable				VARCHAR(20),
	Descripcion						VARCHAR(80),
	Fecha							DATETIME,	
	Destinatario					VARCHAR(100),
	Debe							DECIMAL(12,2),
	Haber							DECIMAL(12,2),
	Observacion						VARCHAR(8000),
	Id_Centro_Costo					VARCHAR(10)
	)

	/*=============================================================================================================================*/

	SET @SqlStr =	'INSERT INTO #Rpt_BalanceCC_AS_Manuales (Alias, Nro_Cta_Contable, Descripcion, Fecha, Destinatario, Debe, Haber, Observacion, Id_Centro_Costo) '
	
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr))											+ CHAR(13) + 
					'SELECT '														+ CHAR(13) + 
					'PCCC.Alias AS Alias, '											+ CHAR(13) + 
					'PCCC.Nro_Cta_Contable AS Nro_Cta, '							+ CHAR(13) + 
					'PCCC.Descripcion AS Cta, '										+ CHAR(13) + 
					'A.Fecha AS Fecha, '											+ CHAR(13) + 
					'A.Descripcion AS Destinatario, '								+ CHAR(13) + 
					'AI.Debe, '														+ CHAR(13) + 
					'AI.Haber, '													+ CHAR(13) + 
					'AI.Nota, '														+ CHAR(13) + 
					'ISNULL(AI.Id_Centro_Costo, '''') AS Id_Centro_Costo '			+ CHAR(13) +
					'FROM Asientos A, Asientos_Items AI, Pla_Ctas_Cuentas_Contables PCCC ' + CHAR(13) + 
					'WHERE '														+ CHAR(13) + 
					'A.Id_Asiento = AI.Id_Asiento '									+ CHAR(13) + 
					'AND AI.Id_Cta_Contable = PCCC.Id_Cta_Contable '				+ CHAR(13) + 
					'AND ISNULL(A.Resumido, 0) = 0 '

	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND A.Fecha >= ''' + CONVERT(VARCHAR(10), @Ejercicio_Fecha_Inicio, 112) + ''' '
--					'AND A.Fecha >= ''' + CONVERT(VARCHAR(10), @pFecha_Desde, 112) + ''' '
					
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND A.Fecha < ''' + CONVERT(VARCHAR(10), DATEADD(DAY, 1, @pFecha_Hasta), 112) + ''' '

	IF(@pFlag_FiltrarId_CC <> 0)
	BEGIN
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND AI.Id_Centro_Costo = ''' + @pId_Centro_Costo + ''' '
	END
	
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND AI.Id_Alias_Cta_Cont = ' + CONVERT(VARCHAR(10), @pId_Alias_Cta_Cont)

	IF(@pSoloResultado = 1)
	BEGIN
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) +
					'AND ISNULL(PCCC.Tipo, '''') IN (''+'',''-'') '
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT ''
		PRINT '@SqlStr (AS Manuales): '
		PRINT @SqlStr
		PRINT ''
	END

	EXECUTE sp_executesql @SqlStr

	/*=============================================================================================================================*/
--
	DECLARE cur_BalanceCC_AS_Manuales CURSOR FOR
	SELECT 
	Alias,
	Nro_Cta_Contable,
	Descripcion,
	Fecha,
	Destinatario,
	Debe,
	Haber,
	Observacion,
	Id_Centro_Costo
	FROM #Rpt_BalanceCC_AS_Manuales

	OPEN cur_BalanceCC_AS_Manuales
	FETCH NEXT FROM cur_BalanceCC_AS_Manuales INTO @Alias, @Nro_Cta_Contable, @Descripcion, @Fecha, @Destinatario, @Debe, @Haber, @Observacion_Orig, @Id_Centro_Costo_Cur
	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF(@pFlag_FiltrarId_CC = 0)
		BEGIN
			SET @Id_Centro_Costo = @Id_Centro_Costo_Cur

			SELECT
			@Centro_Costo = ISNULL(Descripcion, ''),
			@Id_Centro_Costo_Padre1 = ISNULL(Id_Centro_Costo_Padre, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo

			SELECT
			@Centro_Costo_Padre1 = ISNULL(Descripcion, ''),
			@Id_Centro_Costo_Padre2 = ISNULL(Id_Centro_Costo_Padre, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo_Padre1

			SELECT
			@Centro_Costo_Padre2 = ISNULL(Descripcion, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo_Padre2
		END

		SET @Imp_Aplicado	= 0
		SET @Imp_Fac		= 0
		SET @Coef_Aplic		= 0

		INSERT INTO #Rpt_BalanceCC
		(Id_Trans_O,
		Id_Trans_D,
		Alias,
		Nro_Cta_Contable,
		Debe,
		Haber,
		Saldo,
		Fecha,
		Cta_Contable,
		Id_Centro_Costo,
		Centro_Costo,
		Centro_Costo2,
		Centro_Costo3,
		Destinatario,
		Observacion_Orig,
		Observacion_Dest)
		VALUES
		(0,
		0,
		@Alias,
		@Nro_Cta_Contable,
		0/*@Debe Ahora va sobre Saldo_AntMan*/,
		0/*@Haber Ahora va sobre Saldo_AntMan*/,
		0,
		@Fecha,
		@Descripcion,
		@Id_Centro_Costo,
		@Centro_Costo,
		@Centro_Costo_Padre1,
		@Centro_Costo_Padre2,
		@Destinatario,
		@Observacion_Orig,
		'')

		FETCH NEXT FROM cur_BalanceCC_AS_Manuales INTO @Alias, @Nro_Cta_Contable, @Descripcion, @Fecha, @Destinatario, @Debe, @Haber, @Observacion_Orig, @Id_Centro_Costo_Cur
	END
	CLOSE cur_BalanceCC_AS_Manuales
	DEALLOCATE cur_BalanceCC_AS_Manuales
--	
	
	/*=============================================================================================================================*/
	
	CREATE TABLE #Rpt_Balance_Financiero_Saldo_x_Mes_Asientos_Manuales
	(Alias				DECIMAL(12,0),
	Nro_Cta				VARCHAR(20),
	Saldo				DECIMAL(16,2),
	Id_Centro_Costo		CHAR(10))

	INSERT INTO #Rpt_Balance_Financiero_Saldo_x_Mes_Asientos_Manuales
	SELECT
	PCCC.Alias AS Alias,
	PCCC.Nro_Cta_Contable AS Nro_Cta,
	(AI.Debe - AI.Haber) AS Saldo,
	ISNULL(AI.Id_Centro_Costo, '') AS Id_Centro_Costo
	FROM Asientos A, Asientos_Items AI, Pla_Ctas_Cuentas_Contables PCCC
	WHERE
	A.Id_Asiento = AI.Id_Asiento
	AND AI.Id_Cta_Contable = PCCC.Id_Cta_Contable
	AND ISNULL(A.Resumido, 0) = 0
	AND CONVERT(DATE, A.Fecha) >=  CONVERT(DATE, @Ejercicio_Fecha_Inicio, 112)
	AND CONVERT(DATE, A.Fecha) <  CONVERT(DATE, DATEADD(DAY, 1, @Ejercicio_Fecha_Cierre), 112)
	AND AI.Id_Alias_Cta_Cont =  CONVERT(VARCHAR(10), @pId_Alias_Cta_Cont)

	/*=============================================================================================================================*/
	
	IF(@pTipo_Reporte = 'EXPLO')
	BEGIN
		--Explosion por Cbtes

		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Explosion por Comprobantes'
			PRINT '@pId_Alias_Cta_Cont: ' + CONVERT(VARCHAR(10), @pId_Alias_Cta_Cont) + '. @pId_Centro_Costo:' + @pId_Centro_Costo + '. @pFecha_Desde: ' + CONVERT(VARCHAR(10), @pFecha_Desde, 102) + '. @pFecha_Hasta: ' + CONVERT(VARCHAR(10), @pFecha_Hasta, 102)
		END

		SELECT
		Centro_Costo AS CC1, 
		Centro_Costo2 AS CC2,
		Centro_Costo3 AS CC3,
		Nro_Cta_Contable AS Nro_Cta, 
		Cta_Contable AS Cta,
		Id_Trans_O AS Trans_Origen,
		CONVERT(DATE, Fecha) AS Fecha,
		dbo.CF_Cbte_Descrip(Id_Trans_O) AS Cbte,
		Destinatario AS Destinatario,
		Observacion_Orig AS Obs,
		Id_Trans_D AS Trans_Destino,
		'' AS Fecha_Destino,
		dbo.CF_Cbte_Descrip(Id_Trans_D) AS Cbte_Destino,
		Observacion_Dest AS Obs_Destino,
		Debe,
		Haber,
		Saldo
		FROM #Rpt_BalanceCC
		WHERE
		Alias = @pId_Alias_Cta_Cont
		AND Id_Centro_Costo = @pId_Centro_Costo
		AND Fecha >= @pFecha_Desde
		AND Fecha < DATEADD(DAY, 1, @pFecha_Hasta)
		ORDER BY Nro_Cta_Contable, Fecha
	END
	
	IF(@pTipo_Reporte = 'AGRUP')
	BEGIN
		/*=============================================================================================================================*/
		/*=============================================================================================================================*/

		--Agrupacion por Cuentas Mensual
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Agrupacion por Cuentas Mensual'
		END

		/*=============================================================================================================================*/
	
		CREATE TABLE #Rpt_Balance_Financiero_Saldo_x_Mes_CC_Meses
		(Mes			TINYINT,
		Desde			DATETIME,
		Hasta			DATETIME)

		--SET @Mes_Nro = 1
		SET @Mes_Nro = DATEPART(MONTH, @pFecha_Desde)
		SET @Mes_Desde = dbo.CF_FOMONTH(@pFecha_Desde)
		SET @Mes_Hasta = dbo.CF_EOMONTH(@pFecha_Desde)

		WHILE @Mes_Hasta <= @pFecha_Hasta
		BEGIN
			IF(@pModoDebug = 1)
			BEGIN
				PRINT '@Mes_Nro: ' + CONVERT(VARCHAR(10), @Mes_Nro) + '. @Mes_Desde: ' + CONVERT(VARCHAR(10), @Mes_Desde, 112) + '. @Mes_Hasta: ' + CONVERT(VARCHAR(10), @Mes_Hasta, 112)
			END

			INSERT INTO #Rpt_Balance_Financiero_Saldo_x_Mes_CC_Meses
			(Mes,	Desde,	Hasta)
			VALUES
			(@Mes_Nro, @Mes_Desde, @Mes_Hasta)

			SET @Mes_Nro = @Mes_Nro + 1
			SET @Mes_Desde = DATEADD(MONTH, 1, @Mes_Desde)
			SET @Mes_Hasta = dbo.CF_EOMONTH(@Mes_Desde)	
		END

		/*=============================================================================================================================*/
	
		CREATE TABLE #Rpt_Balance_Financiero_Saldo_x_Mes_CC
		(Nro_Cta_Contable				VARCHAR(20),
		Alias							DECIMAL(12,0),
		Cta_Contable					VARCHAR(80),
		Id_Centro_Costo					CHAR(10),
		Centro_Costo					VARCHAR(200),
		Saldo_AntMan					DECIMAL(16,2),
		Saldo_Ant						DECIMAL(16,2),
		Mes_01							DECIMAL(16,2),
		Mes_02							DECIMAL(16,2),
		Mes_03							DECIMAL(16,2),
		Mes_04							DECIMAL(16,2),
		Mes_05							DECIMAL(16,2),
		Mes_06							DECIMAL(16,2),
		Mes_07							DECIMAL(16,2),
		Mes_08							DECIMAL(16,2),
		Mes_09							DECIMAL(16,2),
		Mes_10							DECIMAL(16,2),
		Mes_11							DECIMAL(16,2),
		Mes_12							DECIMAL(16,2),
		Total							DECIMAL(16,2),
		Ingresos                        DECIMAL(16,2),
		Egresos                         DECIMAL(16,2))
	
		/*=============================================================================================================================*/

		SET @SqlStr =	'INSERT INTO #Rpt_Balance_Financiero_Saldo_x_Mes_CC (Alias, Nro_Cta_Contable, Cta_Contable, Id_Centro_Costo, Centro_Costo) '
	
		SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
						'SELECT DISTINCT ' + CHAR(13) + 
						'Alias, ' + CHAR(13) + 
						'ISNULL(Nro_Cta_Contable, ''''), ' + CHAR(13) + 
						'ISNULL(Cta_Contable, ''''), ' + CHAR(13) + 
						'ISNULL(Id_Centro_Costo, ''''), ' + CHAR(13) + 
						'ISNULL(Centro_Costo, '''') '

		SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) +
						'FROM #Rpt_BalanceCC '

		IF(@pModoDebug = 1)
		BEGIN
			PRINT ''
			PRINT '@SqlStr: '
			PRINT @SqlStr
			PRINT ''
		END

		EXECUTE sp_executesql @SqlStr
	
		/*=============================================================================================================================*/

		UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC 
		SET 
		Mes_01 = 0,
		Mes_02 = 0,
		Mes_03 = 0,
		Mes_04 = 0,
		Mes_05 = 0,
		Mes_06 = 0,
		Mes_07 = 0,
		Mes_08 = 0,
		Mes_09 = 0,
		Mes_10 = 0,
		Mes_11 = 0,
		Mes_12 = 0,
		Total = 0,
		Saldo_Ant = 0,
		Saldo_AntMan = 0,
		Ingresos = 0,
		Egresos = 0
	
		/*=============================================================================================================================*/

		DECLARE curCPJ_BalanceSaldoMesCentro_Rpt CURSOR FOR
		SELECT 
		Alias, 
		Id_Centro_Costo 
		FROM #Rpt_Balance_Financiero_Saldo_x_Mes_CC

		OPEN curCPJ_BalanceSaldoMesCentro_Rpt
		FETCH NEXT FROM curCPJ_BalanceSaldoMesCentro_Rpt INTO @Alias, @Id_Centro_Costo
		WHILE @@FETCH_STATUS = 0
		BEGIN

			--Recorro todos los meses
			DECLARE curCPJ_BalanceSaldoMesCentro_Rpt_Meses CURSOR FOR
			SELECT Mes, Desde, Hasta 
			FROM #Rpt_Balance_Financiero_Saldo_x_Mes_CC_Meses
			ORDER BY Mes

			OPEN curCPJ_BalanceSaldoMesCentro_Rpt_Meses
			FETCH NEXT FROM curCPJ_BalanceSaldoMesCentro_Rpt_Meses INTO @Mes_Nro, @Mes_Desde, @Mes_Hasta
			WHILE @@FETCH_STATUS = 0
			BEGIN
				SET @Suma_Debe =	ISNULL((SELECT SUM(Debe) 
												FROM #Rpt_BalanceCC 
												WHERE 
												Alias = @Alias
												AND ISNULL(Id_Centro_Costo, '') = @Id_Centro_Costo
												AND CONVERT(DATE, Fecha) >= CONVERT(DATE, @Mes_Desde)
												AND CONVERT(DATE, Fecha) < DATEADD(DAY, 1, CONVERT(DATE, @Mes_Hasta)))
												, 0)

				SET @Suma_Haber =	ISNULL((SELECT SUM(Haber) 
												FROM #Rpt_BalanceCC 
												WHERE 
												Alias = @Alias
												AND ISNULL(Id_Centro_Costo, '') = @Id_Centro_Costo
												AND CONVERT(DATE, Fecha) >= CONVERT(DATE, @Mes_Desde)
												AND CONVERT(DATE, Fecha) < DATEADD(DAY, 1, CONVERT(DATE, @Mes_Hasta)))
												, 0)

				SET @Suma_Saldo = @Suma_Debe - @Suma_Haber

				IF(@pModoDebug = 1)
				BEGIN
					PRINT '@Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. @Centro_Costo: ' + LTRIM(RTRIM(CONVERT(VARCHAR(10), @Id_Centro_Costo))) + '. @pId_Plan_Cta: ' + CONVERT(VARCHAR(10), @pId_Plan_Cta) + '. @pId_Unid_Negocio: ' + LTRIM(RTRIM(CONVERT(VARCHAR(10), @pId_Unid_Negocio))) + '. @Mes_Nro: ' + CONVERT(VARCHAR(10), @Mes_Nro) + ' (@Mes_Desde: ' + CONVERT(VARCHAR(10), @Mes_Desde, 112) + ' - @Mes_Hasta: ' + CONVERT(VARCHAR(10), @Mes_Hasta, 112) + '). @Suma_Debe: ' + CONVERT(VARCHAR(20), @Suma_Debe) + '. @Suma_Haber: ' + CONVERT(VARCHAR(20), @Suma_Haber) + '. @Suma_Saldo: ' + CONVERT(VARCHAR(20), @Suma_Saldo)
				END

				IF(@Mes_Nro = 1)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_01 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo				
				END

				IF(@Mes_Nro = 2)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_02 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo
				END

				IF(@Mes_Nro = 3)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_03 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo
				END

				IF(@Mes_Nro = 4)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_04 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo
				END

				IF(@Mes_Nro = 5)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_05 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo
				END

				IF(@Mes_Nro = 6)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_06 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo
				END

				IF(@Mes_Nro = 7)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_07 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo
				END

				IF(@Mes_Nro = 8)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_08 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo
				END

				IF(@Mes_Nro = 9)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_09 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo
				END

				IF(@Mes_Nro = 10)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_10 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo
				END

				IF(@Mes_Nro = 11)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_11 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo
				END

				IF(@Mes_Nro = 12)
				BEGIN
					UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC SET Mes_12 = @Suma_Saldo WHERE Alias = @Alias AND Id_Centro_Costo = @Id_Centro_Costo
				END

				FETCH NEXT FROM curCPJ_BalanceSaldoMesCentro_Rpt_Meses INTO @Mes_Nro, @Mes_Desde, @Mes_Hasta
			END
			CLOSE curCPJ_BalanceSaldoMesCentro_Rpt_Meses
			DEALLOCATE curCPJ_BalanceSaldoMesCentro_Rpt_Meses	

			FETCH NEXT FROM curCPJ_BalanceSaldoMesCentro_Rpt INTO @Alias, @Id_Centro_Costo
		END
		CLOSE curCPJ_BalanceSaldoMesCentro_Rpt
		DEALLOCATE curCPJ_BalanceSaldoMesCentro_Rpt

	/*=============================================================================================================================*/

		UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC
		SET
		Saldo_AntMan = z.Saldo
		FROM #Rpt_Balance_Financiero_Saldo_x_Mes_Asientos_Manuales z
		WHERE
		#Rpt_Balance_Financiero_Saldo_x_Mes_CC.Alias = z.Alias
		AND #Rpt_Balance_Financiero_Saldo_x_Mes_CC.Nro_Cta_Contable = z.Nro_Cta
		AND #Rpt_Balance_Financiero_Saldo_x_Mes_CC.Id_Centro_Costo = z.Id_Centro_Costo

		/*=============================================================================================================================*/

		IF(@pModoDebug = 1)
		BEGIN
			PRINT '@Ejercicio_Fecha_Inicio: ' + CONVERT(VARCHAR(10), @Ejercicio_Fecha_Inicio, 102) + '. @pFecha_Desde: ' + CONVERT(VARCHAR(10), @pFecha_Desde, 102)
		END

		IF(@pFecha_Desde <> @Ejercicio_Fecha_Inicio)
		BEGIN
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Calculo de Saldo Anterior'
			END

			DECLARE CPJ_BalanceCC_Rpt_SaldoAnt CURSOR FOR
			SELECT Alias, Id_Centro_Costo
			FROM #Rpt_Balance_Financiero_Saldo_x_Mes_CC

			OPEN CPJ_BalanceCC_Rpt_SaldoAnt
			FETCH NEXT FROM CPJ_BalanceCC_Rpt_SaldoAnt INTO @Alias, @Id_Centro_Costo
			WHILE @@FETCH_STATUS = 0
			BEGIN

				SET @Suma_Debe =	ISNULL((SELECT SUM(Debe) 
												FROM #Rpt_BalanceCC 
												WHERE 
												Alias = @Alias
												AND ISNULL(Id_Centro_Costo, '') = @Id_Centro_Costo
												AND CONVERT(DATE, Fecha) >= CONVERT(DATE, @Ejercicio_Fecha_Inicio)
												AND CONVERT(DATE, Fecha) < CONVERT(DATE, @pFecha_Desde)
												)
												, 0)

				SET @Suma_Haber =	ISNULL((SELECT SUM(Haber) 
												FROM #Rpt_BalanceCC 
												WHERE 
												Alias = @Alias
												AND ISNULL(Id_Centro_Costo, '') = @Id_Centro_Costo
												AND CONVERT(DATE, Fecha) >= CONVERT(DATE, @Ejercicio_Fecha_Inicio)
												AND CONVERT(DATE, Fecha) < CONVERT(DATE, @pFecha_Desde)
												)
												, 0)

				SET @Suma_Saldo = @Suma_Debe - @Suma_Haber

				IF(@pModoDebug = 1)
				BEGIN
					PRINT '@Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. @Id_Centro_Costo: ' + @Id_Centro_Costo
					PRINT '@Suma_Saldo: ' + CONVERT(VARCHAR(20), @Suma_Saldo) + '. @Suma_Debe: ' + CONVERT(VARCHAR(20), @Suma_Debe) + '. @Suma_Haber: ' + CONVERT(VARCHAR(20), @Suma_Haber)
				END

				UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC
				SET
				Saldo_Ant = Saldo_Ant + @Suma_Saldo
				WHERE
				Alias = @Alias
				AND Id_Centro_Costo = @Id_Centro_Costo

				FETCH NEXT FROM CPJ_BalanceCC_Rpt_SaldoAnt INTO @Alias, @Id_Centro_Costo
			END
			CLOSE CPJ_BalanceCC_Rpt_SaldoAnt
			DEALLOCATE CPJ_BalanceCC_Rpt_SaldoAnt
		END
		

		/*=============================================================================================================================*/

		UPDATE #Rpt_Balance_Financiero_Saldo_x_Mes_CC 
		SET 		
		Total   = Mes_01 + Mes_02 + Mes_03 + Mes_04 + Mes_05 + Mes_06 + Mes_07 + Mes_08 + Mes_09 + Mes_10 + Mes_11 + Mes_12 + Saldo_AntMan,
		Egresos = Mes_01 + Mes_02 + Mes_03 + Mes_04 + Mes_05 + Mes_06 + Mes_07 + Mes_08 + Mes_09 + Mes_10 + Mes_11 + Mes_12 + Saldo_AntMan
		

		/*=============================================================================================================================*/

  	SELECT * into Z_Reporte FROM #Rpt_Balance_Financiero_Saldo_x_Mes_CC  ORDER BY Nro_Cta_Contable, Id_Centro_Costo	
	
    declare @JSON_Parametros_Stored_Invocado varchar(4000)

	SET @JSON_Parametros_Stored_Invocado =	'{' +
	                                        dbo.CF_Json_ParsearVariable('Id_Usuario', -1, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('Equate', 90, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('FechaDesde', @pFecha_Desde, 'DATETIME') + ',' +
											dbo.CF_Json_ParsearVariable('FechaHasta', @pFecha_Desde, 'DATETIME') + ',' +
											dbo.CF_Json_ParsearVariable('Flag_Liquidacion', 0, 'TINYINT') + 
											dbo.CF_Json_ParsearVariable('Id_Periodo_Caja', 0, 'TINYINT') + 
											dbo.CF_Json_ParsearVariable('Flag_FPago', 0, 'TINYINT') + 
											dbo.CF_Json_ParsearVariable('Tipo_Cob','', 'TINYINT') + 
											dbo.CF_Json_ParsearVariable('Formato', 'CC', 'CHAR(3)') +
											dbo.CF_Json_ParsearVariable('Generar', 1, 'TINYINT') +  
											'}'
						
	EXEC dbo.CPJ_Productos_Cobros @JSON_Parametros_Stored_Invocado
	IF @pId_Centro_Costo = ''
	    BEGIN
			SELECT Nro_Cta_Contable,Alias,Cta_Contable,Id_Centro_Costo,Centro_Costo,Ingresos,Egresos
				from Z_Reporte 
				where Ingresos+egresos <> 0
  				ORDER BY Nro_Cta_Contable, Id_Centro_Costo	
        END
	  ELSE
	    BEGIN
		 	SELECT Nro_Cta_Contable,Alias,Cta_Contable,Id_Centro_Costo,Centro_Costo,Ingresos,Egresos
				from Z_Reporte 
				where Ingresos+egresos <> 0
				AND Id_Centro_Costo = @pId_Centro_Costo
  				ORDER BY Nro_Cta_Contable, Id_Centro_Costo	
        END
	   drop table Z_Reporte

		/*=============================================================================================================================*/
	END

	/*=============================================================================================================================*/

	/*=============================================================================================================================*/

	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Rpt_Balance_Financiero_Saldo_x_Mes_CC') 
		DROP TABLE #Rpt_Balance_Financiero_Saldo_x_Mes_CC

	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Rpt_BalanceCC_Recibos_Varios') 
		DROP TABLE #Rpt_BalanceCC_Recibos_Varios

	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Rpt_BalanceCC_Recibos_Clientes') 
		DROP TABLE #Rpt_BalanceCC_Recibos_Clientes

	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Rpt_BalanceCC_OP_Varias') 
		DROP TABLE #Rpt_BalanceCC_OP_Varias

	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Rpt_BalanceCC_OP_Proveedores') 
		DROP TABLE #Rpt_BalanceCC_OP_Proveedores

	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Rpt_BalanceCC') 
		DROP TABLE #Rpt_BalanceCC

	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Rpt_BalanceCC_AS_Manuales') 
		DROP TABLE #Rpt_BalanceCC_AS_Manuales

	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Rpt_Balance_Financiero_Saldo_x_Mes_CC_Meses') 
		DROP TABLE #Rpt_Balance_Financiero_Saldo_x_Mes_CC_Meses

	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Rpt_Balance_Financiero_Saldo_x_Mes_CC') 
		DROP TABLE #Rpt_Balance_Financiero_Saldo_x_Mes_CC
	
	/*=============================================================================================================================*/
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_BalanceCC_Rpt'
	END
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	RETURN 9999
END CATCH

RETURN 0

