	DECLARE cur_BalanceCC_Recibos_Clientes CURSOR FOR
	SELECT 
	Id_Trans_Aplica,
	Id_Trans_CCC,
	Importe,
	Imp_Total_Fac,
	Alias,
	Nro_Cta_Contable, 
	Debe, 
	Haber, 
	Fecha_Rec, 
	Descripcion,
	Destinatario,
	Observacion_Orig,
	Observacion_Dest,
	Id_Centro_Costo
	FROM #Rpt_BalanceCC_Recibos_Clientes

	OPEN cur_BalanceCC_Recibos_Clientes
	FETCH NEXT FROM cur_BalanceCC_Recibos_Clientes INTO @Id_Trans, @Id_Trans_CCC, @Importe, @Imp_Total_Fac, @Alias, @Nro_Cta_Contable, @Debe, @Haber, @Fecha, @Descripcion, @Destinatario, @Observacion_Orig, @Observacion_Dest, @Id_Centro_Costo_Cur
	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF(@pFlag_FiltrarId_CC = 0)
		BEGIN
			SET @Id_Centro_Costo = @Id_Centro_Costo_Cur

			SELECT
			@Centro_Costo = ISNULL(Descripcion, ''),
			@Id_Centro_Costo_Padre1 = ISNULL(Id_Centro_Costo_Padre, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo

			SELECT
			@Centro_Costo_Padre1 = ISNULL(Descripcion, ''),
			@Id_Centro_Costo_Padre2 = ISNULL(Id_Centro_Costo_Padre, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo_Padre1

			SELECT
			@Centro_Costo_Padre2 = ISNULL(Descripcion, '')
			FROM Centro_Costos
			WHERE
			Id_Centro_Costo = @Id_Centro_Costo_Padre2
		END

		SET @Imp_Aplicado	= @Importe
		SET @Imp_Fac		= @Imp_Total_Fac
		SET @Coef_Aplic		= @Imp_Aplicado / @Imp_Fac

		INSERT INTO #Rpt_BalanceCC
		(Id_Trans_O,
		Id_Trans_D,
		Alias,
		Nro_Cta_Contable,
		Debe,
		Haber,
		Saldo,
		Fecha,
		Cta_Contable,
		Id_Centro_Costo,
		Centro_Costo,
		Centro_Costo2,
		Centro_Costo3,
		Destinatario,
		Observacion_Orig,
		Observacion_Dest)
		VALUES
		(@Id_Trans_CCC,
		@Id_Trans,
		@Alias,
		@Nro_Cta_Contable,
		@Debe * @Coef_Aplic,
		@Haber * @Coef_Aplic,
		0,
		@Fecha,
		@Descripcion,
		@Id_Centro_Costo,
		@Centro_Costo,
		@Centro_Costo_Padre1,
		@Centro_Costo_Padre2,
		@Destinatario,
		@Observacion_Orig,
		@Observacion_Dest)

		FETCH NEXT FROM cur_BalanceCC_Recibos_Clientes INTO @Id_Trans, @Id_Trans_CCC, @Importe, @Imp_Total_Fac, @Alias, @Nro_Cta_Contable, @Debe, @Haber, @Fecha, @Descripcion, @Destinatario, @Observacion_Orig, @Observacion_Dest, @Id_Centro_Costo_Cur
	END
	CLOSE cur_BalanceCC_Recibos_Clientes
	DEALLOCATE cur_BalanceCC_Recibos_Clientes

