										"ModoDebug":"1",
										"Id_Usuario":"-1",
										"Fecha_Desde":"20210101",
										"Fecha_Hasta":"20211231",
										"Flag_incluirSoloAsientos":"0",
										"Flag_FiltrarId_CC":"0",
										"Id_Centro_Costo":"0",
										"Id_Plan_Cta":"9",
										"Id_Unid_Negocio":"",
										"Flag_Desglozar_CC":"0",
										"Flag_Solo_con_Saldo":"1",
										"Flag_Excluir_Asientos_Cierre":"1"
										}'


*/
