--------------SALDO ANTERIOR CBTES

	SET @SqlStr = 'INSERT INTO #Cbtes_Sumas_Saldos_ANTERIOR (Id_Cta_Contable, Id_Centro_Costo, Saldo_Ant,Debe_Suma,Haber_Suma) '

	SET @SqlStr =	RTRIM(LTRIM(@SqlStr))												+ CHAR(13) + 
