--		select * from #Cbtes_Sumas_Saldos_ANTERIOR

--------

   INSERT INTO  #Asientos_Sumas_Saldos  
        SELECT * FROM  #Cbtes_Sumas_Saldos

   INSERT INTO  #Asientos_Sumas_Saldos_ANTERIOR  
        SELECT * FROM  #Cbtes_Sumas_Saldos_ANTERIOR 
		
 

   SELECT ID_CTA_CONTABLE,ID_CENTRO_COSTO,SUM(SALDO_ANT) AS ANTERIOR ,SUM(Debe_Suma) AS Debe_Suma ,SUM(Haber_Suma) AS Haber_Suma
			INTO #Sumas_Saldos
			FROM #Asientos_Sumas_Saldos
			GROUP BY ID_CTA_CONTABLE,ID_CENTRO_COSTO
   --select count(*) from #Sumas_Saldos

   SELECT ID_CTA_CONTABLE,ID_CENTRO_COSTO,SUM(SALDO_ANT) AS ANTERIOR ,SUM(Debe_Suma) AS Debe_Suma ,SUM(Haber_Suma) AS Haber_Suma
			INTO #Sumas_Saldos_Anteriores
			FROM #Asientos_Sumas_Saldos_ANTERIOR
			GROUP BY ID_CTA_CONTABLE,ID_CENTRO_COSTO

   --select count(*) from #Sumas_Saldos_Anteriores
  
    SELECT Q.ID_CTA_CONTABLE,Q.ID_CENTRO_COSTO
		,SUM(Q.ANTERIOR) AS ANTERIOR
		,SUM(Q.Debe_Suma) AS Debe_Suma
		,SUM(Q.Haber_Suma) AS Haber_Suma
		into #Resultado
	FROM
			(
			SELECT a.ID_CTA_CONTABLE,a.ID_CENTRO_COSTO,a.ANTERIOR,a.Debe_Suma,a.Haber_Suma
			FROM #Sumas_Saldos_Anteriores A
			union 
			SELECT S.ID_CTA_CONTABLE,s.ID_CENTRO_COSTO,s.ANTERIOR,s.Debe_Suma,s.Haber_Suma
			FROM #Sumas_Saldos s
			) Q
	GROUP BY Q.ID_CTA_CONTABLE,Q.ID_CENTRO_COSTO
	ORDER BY Q.ID_CTA_CONTABLE,Q.ID_CENTRO_COSTO
	
	

	SELECT P.Nro_Cta_Contable,P.Alias,P.Descripcion as Cta_Contable, A.Id_Centro_Costo, C.Descripcion as Centro_Costo, P.Columna as Columna_Bal,P.Id_Cuenta_Padre as Alias_Cta_Padre,P.Id_Cta_Contable
	       into #Rpt_Balance_Sumas_Saldos 
		   from Pla_Ctas_Cuentas_Contables P, #Resultado A, Centro_Costos C
		   where P.Id_Plan_Cta = @pId_Plan_Cta
		   AND A.Id_Centro_Costo = C.Id_Centro_Costo
		   AND P.Id_Cta_Contable = A.ID_CTA_CONTABLE
		   AND A.Id_Cta_Contable IS NOT NULL
		   AND P.Id_Cta_Contable IS NOT NULL
		   
 
 
	SELECT P.Nro_Cta_Contable,P.Alias,P.Descripcion as Cta_Contable,SUM(P.columna) as columna_bal
	       into #CtaPadre 
		   from Pla_Ctas_Cuentas_Contables P, #Rpt_Balance_Sumas_Saldos A 
		   where P.Id_Plan_Cta = @pId_Plan_Cta
		   AND P.ALIAS = A.Alias_Cta_Padre
		   AND A.Alias_Cta_Padre <> 0
		   AND A.Id_Cta_Contable IS NOT NULL
		   AND P.Id_Cta_Contable IS NOT NULL	
		   GROUP BY P.Nro_Cta_Contable,P.Alias,P.Descripcion
		   
    
		   
	INSERT INTO	 #Rpt_Balance_Sumas_Saldos (Nro_Cta_Contable,Alias,Cta_Contable,Columna_Bal,Alias_Cta_Padre,Id_Cta_Contable,Id_Centro_Costo,Centro_Costo) 
	 SELECT Nro_Cta_Contable,Alias,Cta_Contable,0,0,0,'','' FROM #CtaPadre WHERE Cta_Contable NOT IN (SELECT Cta_Contable FROM #Rpt_Balance_Sumas_Saldos)
		   	
	ALTER TABLE #Rpt_Balance_Sumas_Saldos ADD
		Anterior						DECIMAL(30,2),
		Debe							DECIMAL(30,2),
		Haber							DECIMAL(30,2),
		Diferencia						DECIMAL(30,2),
		Deudor							DECIMAL(30,2),
		Acreedor						DECIMAL(30,2)

    UPDATE #Rpt_Balance_Sumas_Saldos 
			SET Anterior	    = 0,
				Debe			= 0,
				Haber			= 0,
				Diferencia		= 0,
				Deudor	        = 0,
				Acreedor        = 0 

	UPDATE #Rpt_Balance_Sumas_Saldos 
		SET Anterior    = a.ANTERIOR,
		Debe			= A.Debe_Suma,
		Haber			= A.Haber_Suma,
		Diferencia		= (A.Debe_Suma - A.Haber_Suma) 
        from #Rpt_Balance_Sumas_Saldos B, #Resultado A
	    where B.Id_Cta_Contable = A.Id_Cta_Contable
	          And B.Id_Centro_Costo = A.Id_Centro_Costo

    UPDATE #Rpt_Balance_Sumas_Saldos SET Deudor = abs(Diferencia+Anterior) where Diferencia+Anterior > 0

	UPDATE #Rpt_Balance_Sumas_Saldos SET Acreedor = abs(Diferencia+Anterior) where Diferencia+Anterior <= 0

	/*=============================================================================================================================*/
	IF(@pFlag_Ctas_Result = 0)
		SELECT * FROM #Rpt_Balance_Sumas_Saldos	
				WHERE 
				ISNULL(Debe, 0) <> 0 
				OR ISNULL(Haber, 0) <> 0
				OR ISNULL(Anterior, 0) <> 0
				OR COLUMNA_BAL = 0
				ORDER BY Nro_Cta_Contable,Centro_Costo
     ELSE
		SELECT R.* FROM #Rpt_Balance_Sumas_Saldos	 R
				JOIN Pla_Ctas_Cuentas_Contables C ON R.Id_Cta_Contable = C.Id_Cta_Contable
				WHERE 
					(
						ISNULL(R.Debe, 0) <> 0 
						OR ISNULL(R.Haber, 0) <> 0
						OR ISNULL(R.Anterior, 0) <> 0
						OR COLUMNA_BAL = 0
					)
					AND
						C.Tipo IN ('+','-')
				ORDER BY Nro_Cta_Contable,Centro_Costo	
	/*=============================================================================================================================*/
	DROP TABLE #Asientos_Sumas_Saldos	
	DROP TABLE #Sumas_Saldos_Anteriores
	DROP TABLE #Cbtes_Sumas_Saldos
	DROP TABLE #Sumas_Saldos
  	DROP TABLE #Resultado
	DROP TABLE #Rpt_Balance_Sumas_Saldos
	DROP TABLE #Cbtes_Sumas_Saldos_ANTERIOR
	DROP TABLE #Asientos_Sumas_Saldos_ANTERIOR
	DROP TABLE #CtaPadre
	/*=============================================================================================================================*/
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Balance_Sumas_Saldos_Rpt'
	END
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	RETURN 9999
END CATCH

RETURN 0

/*

EXEC dbo.CPJ_Balance_Sumas_Saldos_Rpt '{
										"ModoDebug":"1",
										"Id_Usuario":"-1",
										"Fecha_Desde":"20240701",
										"Fecha_Hasta":"20250630",
										"Flag_incluirSoloAsientos":"1",
										"Flag_FiltrarId_CC":"0",
										"Id_Centro_Costo":"0",
										"Id_Plan_Cta":"5",
										"Id_Unid_Negocio":"",
										"Flag_Desglozar_CC":"1",
										"Flag_Excluir_Asientos_Cierre":"0",
										"Flag_Ctas_Result":"1"
										"Id_Alias_Cta_Contable":""
										}'
										
										
*/
GO


CREATE PROCEDURE dbo.CPJ_BancoRoela_BaseDeuda_Full @pJson VARCHAR(8000)
AS
BEGIN
SET NOCOUNT ON


	/***************************************************************************************************

	Procedimiento:      CPJ_BancoRoela_BaseDeuda_Full
	Fecha de Creacion:  2026-02-11
	Creado por:         Adriana Laverde
	Descripcion:        Stored creado para generar el archivo a presentar por api a SIRO / BANCO ROELA
	Llamado por:        banco_roela_debt_upload_process.php (API2)
	Tablas afectadas:   []
	Usado en:           
	Parametro(s):       Id_Tar_Lote 
	Forma de uso:       EXEC dbo.CPJ_BancoRoela_BaseDeuda_Full '{"Id_Tar_Lote":179}'
	Notas adicionales:  

	****************************************************************************************************

	SUMARIO DE CAMBIOS
	FECHA(yyyy-mm-dd)    Autor              Comentarios
	------------------- ------------------- ------------------------------------------------------------

	***************************************************************************************************/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pId_Tar_Lote		INT

SET @pId_Tar_Lote			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Tar_Lote')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Declaracion Variables Locales*/
DECLARE @id_convenio		CHAR(10),
        @fecha_pres			DATETIME,
        @yyyymmdd			CHAR(8),
		@Id_Tarjeta			VARCHAR(10),
		@pAplicarRecargos	TINYINT,
        @pClientePers		VARCHAR(15)
/*FIN Declaracion Variables Locales*/

    SELECT  @fecha_pres = ISNULL(Fecha_Presentacion, GETDATE()),
			@Id_Tarjeta	= ISNULL(Id_Tarjeta, '')
    FROM Val_Tarjetas_Lotes
    WHERE Id_Tar_Lote = @pId_Tar_Lote

	SELECT
	@id_convenio			=  RIGHT(REPLICATE('0',10) + ISNULL(CONVERT(VARCHAR(20), Comercio_Nro), ''), 10)
	FROM Valores_Tarjetas_Cred
	WHERE
	ISNULL(Id_Tarjeta, '') = @Id_Tarjeta

    SET @yyyymmdd = CONVERT(CHAR(8), @fecha_pres, 112)

	-- Flag recargos desde param (0/1)
	SET @pAplicarRecargos = ISNULL(CONVERT(BIT, dbo.CF_xParam('ROELA_RecargosCP')), 0)

	-- Cliente personalizado desde param (15)
	SET @pClientePers = LEFT(UPPER(ISNULL(CONVERT(VARCHAR(40), dbo.CF_xParam('ROELA_ClientPerso')), '')) + REPLICATE(' ',15), 15)

    DECLARE @Header CHAR(280) =
        '0' + '400' + '0000' + @yyyymmdd + '1' + REPLICATE('0', 263)

	-- Base: junta el item del lote (Val_Tarjetas_Lotes_Items) con su comprobante (Cbtes), cliente (Clientes) y fechas de vencimiento del lote (Val_Tarjetas_Lotes).
    ;WITH Base AS
    (
        SELECT
            VTLI.Item,
            VTLI.Id_Trans,
            VTLI.Importe,
            C.Id_Cliente,
            C.Fecha AS Fecha_Cbte,
            ISNULL(C.Id_Tipo_Cbte,'') AS Id_Tipo_Cbte,

            CL.Id_Cliente_Ref,
            ISNULL(CL.Tipo_Persona,'F') AS Tipo_Persona,
            ISNULL(CL.Id_Cliente_Externo, CONVERT(VARCHAR(14), CL.Id_Cliente)) AS Id_Cliente_Externo_Raw,
            ISNULL(CLT.Id_Cliente_Externo, CONVERT(VARCHAR(14), CL.Id_Cliente_Ref)) AS Id_Cliente_Externo_Tit_Raw,

            VTL.Fecha_1_Vto,
            VTL.Fecha_2_Vto,
            VTL.Fecha_3_Vto
        FROM Val_Tarjetas_Lotes_Items VTLI
        JOIN Val_Tarjetas_Lotes VTL ON VTL.Id_Tar_Lote = VTLI.Id_Tar_Lote
        JOIN Cbtes C ON C.Id_Trans = VTLI.Id_Trans
        JOIN Clientes CL ON CL.Id_Cliente = C.Id_Cliente
        LEFT JOIN Clientes CLT ON CLT.Id_Cliente = CL.Id_Cliente_Ref
        WHERE
            VTLI.Id_Tar_Lote = @pId_Tar_Lote
            AND VTLI.Estado = 'P'
    ),
	--Pagador: aplica la logica para determinar Id_Cliente_Externo_Final (segun Tipo_Persona y titular) y define descripciones + Concepto_Base + Periodo_MMAA desde Cbtes.Fecha
    Pagador AS
    (
        SELECT
            B.*,
            Id_Cliente_Externo_Final =
                CASE
                    WHEN B.Tipo_Persona = 'I' THEN
                        CASE
                            WHEN dbo.CF_IsNumeric(B.Id_Cliente_Externo_Tit_Raw) = 1
                                THEN CONVERT(VARCHAR(14), ISNULL(B.Id_Cliente_Ref, 0))
                            ELSE B.Id_Cliente_Externo_Tit_Raw
                        END
                    ELSE
                        CASE
                            WHEN dbo.CF_IsNumeric(B.Id_Cliente_Externo_Raw) = 1
                                THEN B.Id_Cliente_Externo_Raw
                            ELSE CONVERT(VARCHAR(14), B.Id_Cliente)
                        END
                END,

            Descripcion_Corta =
                CASE
                    WHEN B.Tipo_Persona = 'I' THEN 'EXP '
                    WHEN B.Id_Tipo_Cbte = 'CUP' THEN 'C SOC '
                    ELSE 'ACT C SOC '
                END,
            Descripcion_Larga =
                CASE
                    WHEN B.Tipo_Persona = 'I' THEN 'EXPENSAS '
                    WHEN B.Id_Tipo_Cbte = 'CUP' THEN 'CUOTA SOCIAL '
                    ELSE 'CUOTA SOCIAL ACTIVIDADES '
                END,

            -- tipo de concepto
            Concepto_Base =
                CASE
                    WHEN B.Tipo_Persona = 'I' THEN '3'
                    WHEN B.Id_Tipo_Cbte = 'CUP' THEN '1'
                    ELSE '2'
                END,

            -- periodo (MMAA) desde FECHA DEL CBTE
            Periodo_MMAA =
                RIGHT('00' + CONVERT(VARCHAR(2), DATEPART(MONTH, B.Fecha_Cbte)), 2) +
                SUBSTRING(RIGHT('0000' + CONVERT(VARCHAR(4), DATEPART(YEAR, B.Fecha_Cbte)), 4), 3, 2)
        FROM Base B
    ),
	--CondPago: busca la condicion de pago del comprobante (toma el MIN(Item) de Cbtes_Items y de ahi su Id_Cond_Pago)
    CondPago AS
    (
        SELECT
            P.*,
            Item_1 = M.Item_1,
            Id_Cond_Pago_Item = ISNULL(CPI.Id_Cond_Pago, 0)
        FROM Pagador P
        OUTER APPLY (
            SELECT Item_1 = MIN(CI.Item)
            FROM Cbtes_Items CI
            WHERE CI.Id_Trans = P.Id_Trans
        ) M
        OUTER APPLY (
            SELECT TOP 1 Id_Cond_Pago = CI.Id_Cond_Pago
            FROM Cbtes_Items CI
            WHERE CI.Id_Trans = P.Id_Trans AND CI.Item = M.Item_1
        ) CPI
    ),
	--Factores: calcula los recargos dependiendo de la condicion de pago para cada vencimiento usando Cbtes_Cond_Pago_Items y el dia del mes de cada fecha de vto
	Factores AS
	(
		SELECT
			CP.*,

			Factor1 =
				CASE
					WHEN @pAplicarRecargos = 0 THEN 1.0
					ELSE COALESCE((
						SELECT TOP 1 (ISNULL(X.Porc_Bonif,0) / 100.0) + 1
						FROM Cbtes_Cond_Pago_Items X
						WHERE X.Id_Cond_Pago = CP.Id_Cond_Pago_Item
						  AND X.Plazo_Desde <= DATEPART(DAY, CP.Fecha_1_Vto)
						  AND X.Plazo_Bonif >= DATEPART(DAY, CP.Fecha_1_Vto)
					), 1.0)
				END,

			Factor2 =
				CASE
					WHEN @pAplicarRecargos = 0 THEN 1.0
					ELSE COALESCE((
						SELECT TOP 1 (ISNULL(X.Porc_Bonif,0) / 100.0) + 1
						FROM Cbtes_Cond_Pago_Items X
						WHERE X.Id_Cond_Pago = CP.Id_Cond_Pago_Item
						  AND X.Plazo_Desde <= DATEPART(DAY, CP.Fecha_2_Vto)
						  AND X.Plazo_Bonif >= DATEPART(DAY, CP.Fecha_2_Vto)
					), 1.0)
				END,

			Factor3 =
				CASE
					WHEN @pAplicarRecargos = 0 THEN 1.0
					ELSE COALESCE((
						SELECT TOP 1 (ISNULL(X.Porc_Bonif,0) / 100.0) + 1
						FROM Cbtes_Cond_Pago_Items X
						WHERE X.Id_Cond_Pago = CP.Id_Cond_Pago_Item
						  AND X.Plazo_Desde <= DATEPART(DAY, CP.Fecha_3_Vto)
						  AND X.Plazo_Bonif >= DATEPART(DAY, CP.Fecha_3_Vto)
					), 1.0)
				END

		FROM CondPago CP
	),
	--D: arma la estructura del archivo por item (nro referencia 19, fechas AAAAMMDD, importes 11 con recargo, mensajes) y calcula rn_dup para detectar duplicados por (nro_referencia_19, Periodo_MMAA, Concepto_Base)
    D AS
    (
        SELECT
            F.*,
            nro_referencia_19 =
                '0' +
                RIGHT('00000000' + CONVERT(VARCHAR(14), F.Id_Cliente_Externo_Final), 8) +
                @id_convenio,

            f1 = CONVERT(CHAR(8), F.Fecha_1_Vto, 112),
            f2 = CONVERT(CHAR(8), CASE WHEN F.Fecha_2_Vto IS NULL OR F.Fecha_2_Vto < F.Fecha_1_Vto THEN F.Fecha_1_Vto ELSE F.Fecha_2_Vto END, 112),
            f3 = CONVERT(CHAR(8), CASE WHEN F.Fecha_3_Vto IS NULL OR F.Fecha_3_Vto < ISNULL(F.Fecha_2_Vto, F.Fecha_1_Vto) THEN ISNULL(F.Fecha_2_Vto, F.Fecha_1_Vto) ELSE F.Fecha_3_Vto END, 112),

            imp1_centavos = CONVERT(BIGINT, CAST(ROUND(F.Importe * F.Factor1 * 100.0, 0) AS BIGINT)),

            imp1_11 = RIGHT(REPLICATE('0',11) + CONVERT(VARCHAR(30), CONVERT(BIGINT, CAST(ROUND(F.Importe * F.Factor1 * 100.0, 0) AS BIGINT))), 11),
            imp2_11 = RIGHT(REPLICATE('0',11) + CONVERT(VARCHAR(30), CONVERT(BIGINT, CAST(ROUND(F.Importe * F.Factor2 * 100.0, 0) AS BIGINT))), 11),
            imp3_11 = RIGHT(REPLICATE('0',11) + CONVERT(VARCHAR(30), CONVERT(BIGINT, CAST(ROUND(F.Importe * F.Factor3 * 100.0, 0) AS BIGINT))), 11),

            mensaje_ticket_40	= LEFT(@pClientePers + UPPER(F.Descripcion_Larga) + F.Periodo_MMAA + REPLICATE(' ',40), 40),
            mensaje_pantalla_15 = LEFT(UPPER(F.Descripcion_Corta) + F.Periodo_MMAA + REPLICATE(' ',15), 15),

            rn_dup = ROW_NUMBER() OVER (
                PARTITION BY
                    ('0' + RIGHT('00000000' + CONVERT(VARCHAR(14), F.Id_Cliente_Externo_Final), 8) + @id_convenio),
                    F.Periodo_MMAA,
                    F.Concepto_Base
                ORDER BY F.Item
            )
        FROM Factores F
    ),
	--D2: resuelve el duplicado final: fija Concepto_Final (si repite, cambia el digito 16) y arma id_factura_20 (15 Id_Trans + concepto + MMAA) ya definitivo
    D2 AS
    (
        SELECT
            D.Item,
            D.nro_referencia_19,
            D.f1, D.f2, D.f3,
            D.imp1_11, D.imp2_11, D.imp3_11,
            D.imp1_centavos,
            D.mensaje_ticket_40,
            D.mensaje_pantalla_15,

            Concepto_Final =
                CASE
                    WHEN D.rn_dup = 1 THEN D.Concepto_Base
                    ELSE SUBSTRING('4567890123', ((D.rn_dup - 2) % 10) + 1, 1)
                END,

            id_factura_20 =
                RIGHT(REPLICATE('0',15) + CONVERT(VARCHAR(30), D.Id_Trans), 15) +
                CASE
                    WHEN D.rn_dup = 1 THEN D.Concepto_Base
                    ELSE SUBSTRING('4567890123', ((D.rn_dup - 2) % 10) + 1, 1)
                END +
                D.Periodo_MMAA
        FROM D
    ),
	--TrailerCalc: calcula los totales del trailer (cantidad de detalles y suma de imp1_centavos).
    TrailerCalc AS
    (
        SELECT
            cant = COUNT(*),
            total_cent = ISNULL(SUM(imp1_centavos), 0)
        FROM D2
    )
    SELECT *
    FROM
    (
        SELECT
            orden = 0,
            item  = 0,
            Linea      = @Header
        UNION ALL
        SELECT
            orden = 1,
            item  = D2.Item,
            Linea =
                '5' +
                D2.nro_referencia_19 +
                D2.id_factura_20 +
                '0' +
                D2.f1 +
                D2.imp1_11 +
                D2.f2 +
                D2.imp2_11 +
                D2.f3 +
                D2.imp3_11 +
                REPLICATE('0',19) +
                D2.nro_referencia_19 +
                D2.mensaje_ticket_40 +
                D2.mensaje_pantalla_15 +
                REPLICATE(' ',60) +
                REPLICATE('0',29)
        FROM D2
        UNION ALL
        SELECT
            orden = 2,
            item  = 0,
            Linea =
                '9' +
                '400' +
                '0000' +
                @yyyymmdd +
                RIGHT(REPLICATE('0',7) + CONVERT(VARCHAR(20), T.cant), 7) +
                REPLICATE('0',7) +
                RIGHT(REPLICATE('0',16) + CONVERT(VARCHAR(30), T.total_cent), 16) +
                REPLICATE('0',234)
        FROM TrailerCalc T
    ) X
    ORDER BY X.orden, X.item

END
GO



CREATE PROCEDURE [dbo].[CPJ_Browse_CD_ES_Log] @pJson VARCHAR(8000)
AS
BEGIN

/*=============================================================================================================================================================*/

/* Variables por Parametro */
DECLARE @pModoDebug			TINYINT
DECLARE @pFecha_Desde		DATETIME
DECLARE @pFecha_Hasta		DATETIME
DECLARE @pId_Cliente		INT
DECLARE @pTipo				CHAR(2)
DECLARE @pResultado			CHAR(1)
DECLARE @pTipo_Filtro		CHAR(1)
DECLARE @pId_Accesos		VARCHAR(100)
DECLARE @pId_Controladores  VARCHAR(100)
DECLARE @pId_Tipo_Cli  		INT 
/* FIN Variables por Parametro */


/*Variables Locales*/
DECLARE @posicion						INT
DECLARE @longitud						INT
DECLARE @Id_Controlador_Filtro			SMALLINT
DECLARE @Id_Acceso_Filtro				SMALLINT
DECLARE @SqlStr							NVARCHAR(MAX) -- Arma el SQL a ejecutar
/*FIN Variables Locales*/

/*=============================================================================================================================================================*/

SET @pModoDebug			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pFecha_Desde		= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde')), '19000101') 
SET @pFecha_Hasta		= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta')), '20501231') 
SET @pId_Cliente		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0) 
SET @pTipo				= ISNULL(CONVERT(CHAR(2), dbo.CF_JSON_VALUE(@pJson,'Tipo')), 'ES') 
SET @pResultado			= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJson,'Resultado')), '') 
SET @pTipo_Filtro		= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJson,'Tipo_Filtro')), '') 
SET @pId_Accesos		= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJson,'Id_Accesos')), '') 
SET @pId_Controladores  = ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJson,'Id_Controladores')), '')
SET @pId_Tipo_Cli		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Cli')), 0) 


IF(@pTipo = '') SET @pTipo = 'ES' 
IF(RIGHT(@pId_Accesos, 1) = ',') SET @pId_Accesos = SUBSTRING(@pId_Accesos, 1, LEN(@pId_Accesos) - 1) 
IF(RIGHT(@pId_Controladores, 1) = ',') SET @pId_Controladores = SUBSTRING(@pId_Controladores, 1, LEN(@pId_Controladores) - 1) 

/*=============================================================================================================================================================*/


CREATE TABLE #BrowseCDES	(Codigo			INT,
							Tipo			VARCHAR(8),
							Origen			VARCHAR(11),
							Credencial		VARCHAR(100),
							Pers_Cod		INT,
							Pers_Nro_Socio	VARCHAR(14),
							Pers_Nombre		VARCHAR(100), 
							Pers_Categ		VARCHAR(50),
							Fecha			DATE,
							Hora			VARCHAR(8),
							Resultado		VARCHAR(6),
							Observacion		VARCHAR(200),
							Id_Acceso		SMALLINT,
							Acceso			VARCHAR(20),
							Id_Controlador	SMALLINT,
							Controlador		VARCHAR(100))

/*=============================================================================================================================================================*/

SET @SqlStr =	''

SET @SqlStr +=	'INSERT INTO #BrowseCDES '
SET @SqlStr +=	' SELECT'
SET @SqlStr +=	' CE.Id_ES AS Codigo,'
SET @SqlStr +=	' CASE CE.Tipo '
SET @SqlStr +=	' 	WHEN ''E'' THEN ''Entrada'''
SET @SqlStr +=	' 	WHEN ''S'' THEN ''Salida'''
SET @SqlStr +=	' END'
SET @SqlStr +=	' AS Tipo,'
SET @SqlStr +=	' CASE CE.Origen'
SET @SqlStr +=	' 	WHEN ''A'' THEN ''Automatico'''
SET @SqlStr +=	' 	WHEN ''M'' THEN ''Manual'''
SET @SqlStr +=	' END'
SET @SqlStr +=	' AS Origen,'
SET @SqlStr +=	' CE.Id_Tarjeta	AS Credencial,'
SET @SqlStr +=	' CL.Id_Cliente	AS Pers_Cod,'
SET @SqlStr +=	' ISNULL(CL.Id_Cliente_Externo,  '''')	AS Pers_Nro_Socio,'
SET @SqlStr +=	' CL.Razon_Social AS Pers_Nombre,'
SET @SqlStr +=	' CT.Descripcion AS Pers_Categ,'
SET @SqlStr +=	' CONVERT(DATE, CE.Fecha) AS Fecha,'
SET @SqlStr +=	' CONVERT(VARCHAR(8), CE.Fecha, 8) AS Hora,'
SET @SqlStr +=	' CASE CE.Resultado'
SET @SqlStr +=	' 	WHEN ''S'' THEN ''Satisf'''
SET @SqlStr +=	' 	WHEN ''E'' THEN ''Error'''
SET @SqlStr +=	' END'
SET @SqlStr +=	' AS Resultado,'
SET @SqlStr +=	' CONVERT(VARCHAR(100), CE.Observacion)	AS Observacion,'
SET @SqlStr +=	' CA.Id_Acceso AS Id_Acceso,'
SET @SqlStr +=	' CA.Descripcion AS Acceso,'
SET @SqlStr +=	' CC.Id_Controlador	AS Id_Controlador,'
SET @SqlStr +=	' CC.Descripcion AS Controlador'
SET @SqlStr +=	' FROM CD_ES CE, Clientes CL, Clientes_Tipos CT, CD_Accesos CA, CD_Controladores CC'
SET @SqlStr +=	' WHERE'
SET @SqlStr +=	' CE.Id_Cliente = CL.Id_Cliente'
SET @SqlStr +=	' AND ISNULL(CL.Id_Tipo_Cli, 0) = CT.Id_Tipo_Cli'
SET @SqlStr +=	' AND CE.Id_Acceso = CA.Id_Acceso'
SET @SqlStr +=	' AND CE.Id_Controlador = CC.Id_Controlador'
SET @SqlStr +=	' AND CE.Fecha >= ''' + CONVERT(VARCHAR(10), @pFecha_Desde, 112) +''''
SET @SqlStr +=	' AND CE.Fecha < ''' + CONVERT(VARCHAR(10), DATEADD(dd, 1, @pFecha_Hasta), 112) +'''' 

IF(@pId_Cliente > 0)
BEGIN
	SET @SqlStr +=	' AND CE.Id_Cliente = ' + CONVERT(VARCHAR(10), @pId_Cliente)
END		
		
IF(@pTipo <> 'ES')
BEGIN
	SET @SqlStr +=	' AND CE.Tipo = ''' + @pTipo + ''''
END

IF(@pResultado <> '')
BEGIN
	SET @SqlStr +=	' AND CE.Resultado = '''  + @pResultado + ''''
END

IF(@pTipo_Filtro = 'A')
BEGIN
	--Filtro por Acceso
	SET @SqlStr +=	' AND CE.Id_Acceso IN (' + @pId_Accesos + ')'
END

IF(@pTipo_Filtro = 'C')
BEGIN
	--Filtro por Controlador
	SET @SqlStr +=	' AND CE.Id_Controlador IN (' + @pId_Controladores + ')'
END

-- Filtro por Tipo Cliente
IF(@pId_Tipo_Cli <> 0) SET @SqlStr +=	' AND CT.Id_Tipo_Cli = ' + CONVERT(VARCHAR(100), @pId_Tipo_Cli)

/*=============================================================================================================================================================*/

IF(@pModoDebug = 1) PRINT @SqlStr


EXECUTE sp_executesql @SqlStr

SELECT * FROM #BrowseCDES
DROP TABLE #BrowseCDES

/*=============================================================================================================================================================*/

END

-- EXEC [dbo].[CPJ_Browse_CD_ES_Log] '{"Fecha_Desde":"20250927","Fecha_Hasta":"20250928","Id_Cliente":"","Tipo":"","Resultado":"","Tipo_Filtro":"C","Id_Accesos":"","Id_Controladores":"","Id_Tipo_Cli":0}'
GO


CREATE PROCEDURE dbo.CPJ_CD_ES_Registrar_RF @pJson VARCHAR(8000)
AS 

/*
 * LOG VERSIONES:
 * 23/08/2022: Se crea el Stored
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug				TINYINT

SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @pJson_A_Enviar		VARCHAR(8000)
DECLARE @Fecha_Desde		DATETIME
DECLARE @Fecha_Desde_VC		VARCHAR(20)
/*FIN Variables Locales*/

SET @Fecha_Desde = DATEADD(MINUTE, -1, GETDATE())

SET @Fecha_Desde_VC	 =	RIGHT('0000' + CAST(DATEPART(YEAR, @Fecha_Desde) AS VARCHAR), 4) + 
						'-' +
						RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_Desde) AS VARCHAR), 2)  + 
						'-' +
						RIGHT('00' + CAST(DATEPART(DAY, @Fecha_Desde) AS VARCHAR), 2) +
						'T' +
						RIGHT('00' + CAST(DATEPART(HOUR, @Fecha_Desde) AS VARCHAR), 2) + 
						':' +
						RIGHT('00' + CAST(DATEPART(MINUTE, @Fecha_Desde) AS VARCHAR), 2) + 
						':' +
						'00'

SET @pJson_A_Enviar =	'{' + 
						dbo.CF_Json_ParsearVariable('ModoDebug', '1', 'INTEGER') + ',' + 
						dbo.CF_Json_ParsearVariable('API_Metodo', 'suprema_rf_events', 'INTEGER') + ',' + 
						'"API_Data":{"fecha_desde":"' + @Fecha_Desde_VC + '"}' +
						'}'

EXEC dbo.CPJ_CleverAPI_Ejecutar @pJson_A_Enviar

--EXEC dbo.CPJ_CD_ES_Registrar_RF '{"ModoDebug":"1"}'
GO



CREATE PROCEDURE [dbo].[CPJ_Caja_Transf_Masiva] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*Variables recibidas por par├ímetro a traves del JSON*/
DECLARE	@pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Periodo_Caja_Ori	INT
DECLARE @pId_Periodo_Caja_Dest	INT
DECLARE @pFecha_Desde			DATETIME
DECLARE @pFecha_Hasta			DATETIME
DECLARE @pId_trans			    VARCHAR(MAX)

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Periodo_Caja_Ori		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Periodo_Caja_Ori')), 0)
SET @pId_Periodo_Caja_Dest		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Periodo_Caja_Dest')), 0)
SET @pFecha_Desde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde')), 0)
SET @pFecha_Hasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta')), 0)
SET @pId_trans				    = ISNULL(CONVERT(VARCHAR(1000), dbo.CF_JSON_VALUE(@pJson,'Id_trans')), '')

/*FIN Variables recibidas por par├ímetro a traves del JSON*/
 

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)

/*FIN Variable de Retorono del Stored*/


/*Declaraci├│n de Variables*/
DECLARE @Id_Periodo_Caja_Nuevo		INT
DECLARE @CP_Id_Caja					INT
DECLARE @Mensaje					VARCHAR(100)
DECLARE @Sql						NVARCHAR(1000) 
/*FIN Declaraci├│n de Variables*/

BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Caja_Transf_Masiva'
		PRINT 'Par├ímetros:'
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) +  'Id_Periodo_Caja_Origen: ' + CONVERT(VARCHAR(10), @pId_Periodo_Caja_Ori) + 'Id_Periodo_Caja_Destino:' + CONVERT(VARCHAR(10),@pId_Periodo_Caja_Dest) + 'Fecha_Desde:' + CONVERT(VARCHAR(10),@pFecha_Desde,103) + 'Fecha_Hasta:' + CONVERT(VARCHAR(10),@pFecha_Hasta,103)
	END

	/*===================================================================*/

	IF(@pId_Periodo_Caja_Ori = 0 AND @pId_Periodo_Caja_Dest = 0 AND @pFecha_Desde = 0 AND @pFecha_Hasta = 0)
	BEGIN
		SET @rtaErrorStored = 70001 /*los per├¡odos no pueden ser ceros y las fechas no pueden ser null*/
		SET @rtaMsjStored	= 'Los periodos no pueden ser ceros y/o las fechas no pueden ser null'
		
		SELECT	 @rtaErrorStored	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,@rtaMsjStored		AS ErrorMessage
			
		IF @pFlagUsarTrans <> 0 
		BEGIN
			ROLLBACK
		END
		
		RETURN 9999
	END
	
	/*===================================================================*/	
	SELECT Id_Trans INTO #Caja_mov_Atransferir FROM Cajas_Mov WHERE 1=0
	IF @pId_trans = ''
   	    INSERT INTO #Caja_mov_Atransferir 
	       SELECT Id_Trans  FROM Cajas_Mov WHERE Fecha BETWEEN @pFecha_Desde AND @pFecha_Hasta
		          AND Id_Periodo_Caja=@pId_Periodo_Caja_Ori 
	  ELSE
	    BEGIN
	      SET @Sql = 'INSERT INTO #Caja_mov_Atransferir 
	                  SELECT Id_Trans  FROM Cajas_Mov WHERE ID_TRANS IN (' + @pId_trans + ')'
		  --EXEC @SQL
		  EXEC(@Sql)

		END

	
	/*=============Actualizo Tablas=======================================*/	
    
    UPDATE Cajas_Mov SET Id_Periodo_Caja = @pId_Periodo_Caja_Dest 
			  WHERE Id_Trans IN (SELECT Id_Trans FROM #Caja_mov_Atransferir )
			  AND Id_Periodo_Caja = @pId_Periodo_Caja_Ori
			  
	UPDATE Valores_Mov SET Id_Periodo_Caja = @pId_Periodo_Caja_Dest 
			  WHERE Id_Trans IN (SELECT Id_Trans FROM #Caja_mov_Atransferir )
			  AND Id_Periodo_Caja = @pId_Periodo_Caja_Ori		  

    UPDATE Valores SET Id_Periodo_Caja = @pId_Periodo_Caja_Dest 
			  WHERE Id_Trans IN (SELECT Id_Trans FROM #Caja_mov_Atransferir )
			  AND Id_Periodo_Caja = @pId_Periodo_Caja_Ori



	/*===================FIN Actualizo Tablas============================*/	
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END
	
	/*===================================================================*/	

	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('Id_Periodo_Caja_Ori', @pId_Periodo_Caja_Ori, 'INT') +
								dbo.CF_Json_ParsearVariable('Id_Periodo_Caja_Dest', @pId_Periodo_Caja_dest, 'INT') +
								dbo.CF_Json_ParsearVariable('Fecha_Desde', @pFecha_Desde, 'DATETIME') +
								dbo.CF_Json_ParsearVariable('Fecha_Hasta', @pFecha_Hasta, 'DATETIME') +
								'}'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Caja_Transf_Masiva'
	END

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo
	
	IF ISNULL(@pFlagUsarTrans,0) <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO



