CREATE PROCEDURE [dbo].[CPJ_Cbtes_Calc_Intereses] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Trans				INT
DECLARE @pImp_Total				DECIMAL(12,2)
DECLARE @pImp_Abonado			DECIMAL(12,2)
DECLARE @pFecha_Pago			DATETIME


SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pImp_Total					= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_Total')), 0)
SET @pImp_Abonado				= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_Abonado')), 0)
SET @pFecha_Pago				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Pago')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
DECLARE @Result_Stored_Invocado				INT
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Producto			VARCHAR(14)
DECLARE @Descripcion			VARCHAR(150)
DECLARE @Importe				DECIMAL(16,2)
DECLARE @Periodo				DATETIME
DECLARE @Porcentaje				DECIMAL(12,5)
DECLARE @Porc_Bonif				DECIMAL(12,5)
DECLARE @Coef_Imp_Pagado		DECIMAL(15,5)
DECLARE @Fecha_Factura			DATETIME
DECLARE @Id_Cond_Pago_Cbte		SMALLINT
DECLARE @Id_Cond_Pago_Cbte_Item	SMALLINT
DECLARE @Item					SMALLINT
DECLARE @Plazo					INT
DECLARE @Porc_Bonif_Rec			DECIMAL(12,5)
DECLARE @Fecha_Rec				DATETIME
DECLARE @Dif_Dias				INT
DECLARE @Flag_Encontro			TINYINT
DECLARE @Plazo_Desde			INT
DECLARE @Porc_Bonif_Cbtes_Cond_Pago_Item DECIMAL(12,5)
DECLARE @Plazo_Bonif			BIGINT
DECLARE @Id_Cond_Pago_Item		INT
DECLARE @Tipo					CHAR(1)
DECLARE @Plazo_Sin_Recargo		INT
DECLARE @Imp_Final				DECIMAL(15,5)
DECLARE @Flag_Mes				TINYINT
DECLARE @Fecha_QA				DATETIME
DECLARE @Param_Prod_Recargos	VARCHAR(14)
/*Fin de Declaraciones Variables Locales */

/*Tabla de Respuesta*/
DECLARE @tRespuesta TABLE (
	Id_Producto VARCHAR(14),
	Descripcion VARCHAR(150),
	Importe		DECIMAL(16,2),
	Periodo		DATETIME,
	Porcentaje	DECIMAL(12,5),
	Id_Trans	INT
	)


BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Calc_Intereses'
		PRINT 'Parametros:'
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + '. Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans) + '. Imp_Total: ' + CONVERT(VARCHAR(10), @pImp_Total) + '. Imp_Abonado: ' + CONVERT(VARCHAR(10), @pImp_Abonado) + '. Fecha_Pago: ' + CONVERT(VARCHAR(10), @pFecha_Pago, 102)
	END
	
	/*===================================================================*/

	IF(@pId_Trans = 0)
	BEGIN
		SET @rtaErrorStored = 70001 /*Transaccion no abierta*/
		
		SELECT	 @rtaErrorStored	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,''					AS ErrorMessage
			
		IF @pFlagUsarTrans <> 0 
		BEGIN
			ROLLBACK
		END
		
		RETURN 9999
	END
	
	/*===================================================================*/	

	SET @Id_Producto			= ''
	SET @Descripcion			= ''
	SET @Importe				= 0
	SET @Periodo				= '19000101'
	SET @Porc_Bonif				= 0
	SET @Param_Prod_Recargos	= dbo.CF_xParam('PROD_RECARGOS')
	
	/*===================================================================*/	

	SET @Coef_Imp_Pagado = (@pImp_Abonado / @pImp_Total)

	SELECT	@Fecha_Factura		= ISNULL(Fecha, '19000101'),
			@Id_Cond_Pago_Cbte	= ISNULL(Id_Cond_Pago, 0)
		FROM	Cbtes
		WHERE	Id_Trans = @pId_Trans

	/*===================================================================*/	

	

	DECLARE curCPJ_Cbtes_Calc_Intereses_Cbtes_Items CURSOR FOR
		SELECT	Item,					ISNULL(Id_Producto, ''),		ISNULL(Id_Cond_Pago, 0),
				ISNULL(Imp_Final, 0),	ISNULL(Fecha_QA, '19000101')
				FROM	Cbtes_Items
				WHERE	
				Id_Trans = @pId_Trans
				AND Id_Cond_Pago IN (SELECT DISTINCT Id_Cond_Pago FROM Cbtes_Cond_Pago_Items WHERE Id_Cond_Pago <> 0)
				
	OPEN curCPJ_Cbtes_Calc_Intereses_Cbtes_Items
	FETCH NEXT FROM curCPJ_Cbtes_Calc_Intereses_Cbtes_Items INTO @Item, @Id_Producto, @Id_Cond_Pago_Cbte_Item, @Imp_Final, @Fecha_QA
	WHILE @@FETCH_STATUS = 0
	BEGIN		

		IF(@Id_Cond_Pago_Cbte_Item <> 0)
		BEGIN
			SET @Plazo = 0
			SET @Porc_Bonif_Rec = 0
            SET @Fecha_Rec = @pFecha_Pago

            SET @Dif_Dias = DATEDIFF(dd, @Fecha_Factura, @Fecha_Rec)

			SET @Flag_Encontro = 0
			
			DECLARE curCPJ_Cbtes_Calc_Intereses_Cbtes_Items_Cond_Pago CURSOR FOR
				SELECT	ISNULL(Plazo_Desde, 0),
						ISNULL(Porc_Bonif, 0),
						ISNULL(Plazo_Bonif, 0),
						UPPER(ISNULL(Tipo, '')),
						ISNULL(Plazo_Sin_Recargo, 0)
					FROM	Cbtes_Cond_Pago_Items
					WHERE	Id_Cond_Pago = @Id_Cond_Pago_Cbte_Item


			OPEN curCPJ_Cbtes_Calc_Intereses_Cbtes_Items_Cond_Pago
			WHILE @@FETCH_STATUS = 0 AND @Flag_Encontro = 0
			BEGIN

				--Se rota la sentencia del Cursor para que corte cuando @Flag_Encontro = 1
				FETCH NEXT FROM curCPJ_Cbtes_Calc_Intereses_Cbtes_Items_Cond_Pago INTO @Plazo_Desde, @Porc_Bonif_Cbtes_Cond_Pago_Item, @Plazo_Bonif, @Tipo, @Plazo_Sin_Recargo

				IF(@Dif_Dias < 0 AND @Plazo_Desde = 0)
				BEGIN
					SET @Flag_Encontro = 1
					SET @Porc_Bonif_Rec = @Porc_Bonif_Cbtes_Cond_Pago_Item
					BREAK
				END

				IF(@Dif_Dias >= @Plazo_Desde AND @Dif_Dias <= @Plazo_Bonif)
				BEGIN
					SET @Flag_Encontro = 1
					SET @Porc_Bonif_Rec = @Porc_Bonif_Cbtes_Cond_Pago_Item
					BREAK
				END				
			END
			CLOSE curCPJ_Cbtes_Calc_Intereses_Cbtes_Items_Cond_Pago
			DEALLOCATE curCPJ_Cbtes_Calc_Intereses_Cbtes_Items_Cond_Pago

			IF(@pModoDebug = 1)
			BEGIN
				PRINT '@Flag_Encontro: ' + CONVERT(VARCHAR(10), @Flag_Encontro) 
					+ '. @Id_Cond_Pago_Cbte_Item: ' + CONVERT(VARCHAR(10), @Id_Cond_Pago_Cbte_Item) 
					+ '. @Id_Cond_Pago_Item: ' + CONVERT(VARCHAR(10), ISNULL(@Id_Cond_Pago_Item,0))
					+ '. @Porc_Bonif_Rec: ' + CONVERT(VARCHAR(10), @Porc_Bonif_Rec) 
					+ '. @Plazo_Bonif: ' + CONVERT(VARCHAR(10), @Plazo_Bonif) 
					+ '. @Fecha_Factura: ' + CONVERT(VARCHAR(10), @Fecha_Factura , 102) 
					+ ' @Fecha_Rec: ' + CONVERT(VARCHAR(10), @Fecha_Rec, 102) 
			END

			SELECT
				@Descripcion	= ISNULL(Descripcion_Detallada, ''),
				@Flag_Mes		= ISNULL(Flag_Mes, 0)
				FROM Productos
				WHERE
				Id_Producto = @Id_Producto

			IF(@Tipo = 'D'/*Descuento*/ AND @Porc_Bonif_Rec > 0 AND @Dif_Dias > @Plazo_Sin_Recargo)
			BEGIN
				SET @Importe = @Imp_Final * (@Porc_Bonif_Rec * (@Dif_Dias - @Plazo_Sin_Recargo) / 100)
			END
			ELSE
			BEGIN
				SET @Importe = @Imp_Final * (@Porc_Bonif_Rec / 100)
			END

			IF(@pModoDebug = 1)
			BEGIN
				PRINT '@Importe: ' + CONVERT(VARCHAR(10), @Importe) + '. Coef_Imp_Pagado: ' + CONVERT(VARCHAR(10), @Coef_Imp_Pagado)
			END

			IF @Coef_Imp_Pagado=0
			BEGIN
				SET @Coef_Imp_Pagado=1
			END

			SET @Importe =  @Importe * @Coef_Imp_Pagado
			SET @Porcentaje = ABS(@Porc_Bonif_Rec)

			IF(@pModoDebug = 1)
			BEGIN
				PRINT '@Porcentaje: ' + CONVERT(VARCHAR(10), @Porcentaje)
			END

			IF(@Flag_Mes = 1)
			BEGIN
				SET @Periodo = dbo.CF_FOMONTH(@Fecha_QA)
			END
			ELSE
			BEGIN
				SET @Periodo = '19000101'
			END
		END

		IF @Flag_Encontro = 1
		BEGIN
			IF(@Param_Prod_Recargos <> '')
			BEGIN
				SET @Id_Producto = @Param_Prod_Recargos
			END

			INSERT INTO @tRespuesta VALUES(@Id_Producto,@Descripcion,@Importe,@Periodo,@Porcentaje,@pId_Trans)
		END

		FETCH NEXT FROM curCPJ_Cbtes_Calc_Intereses_Cbtes_Items INTO @Item, @Id_Producto, @Id_Cond_Pago_Cbte_Item, @Imp_Final, @Fecha_QA
	END
	CLOSE curCPJ_Cbtes_Calc_Intereses_Cbtes_Items
	DEALLOCATE curCPJ_Cbtes_Calc_Intereses_Cbtes_Items

	/*===================================================================*/	
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	
	
	SELECT * FROM @tRespuesta

/*
	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('Id_Producto', @Id_Producto, 'VARCHAR(14)') + ',' +
								dbo.CF_Json_ParsearVariable('Descripcion', @Descripcion, 'VARCHAR(150)') + ',' +
								dbo.CF_Json_ParsearVariable('Importe', @Importe, 'DECIMAL(12,2)') + ',' +
								dbo.CF_Json_ParsearVariable('Periodo', @Periodo, 'DATETIME') + ',' +
								dbo.CF_Json_ParsearVariable('Porcentaje', @Porcentaje, 'DECIMAL(12,5)') + ',' +
								dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'INT') +
								'}'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage
*/
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Calc_Intereses'
	END

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Cli_Aplica_Auto]  @pJson VARCHAR(8000)	 
AS

/***************************************************************************************************

	Procedimiento:      CPJ_Cbtes_Cli_Aplica_Auto
	Fecha de Creacion:  2026-02-28
	Creado por:         Gabriel Centenari
	Descripcion:        Aplica por importe iguales orden por Fecha una cta. cte. de cliente todos los cbtes en estado 1 (Pendiente)


						Flujo general:
						1) Carga lasa Facturas e @Facturas con nro de registro
						2) Carga los recibos y NC en @Recibos con nro registro
						3) Genera @Cbtes_Aplica
						4) Depende el modo muestra resultados o lo genera deFinitivamente

	Llamado por:        Boton en Clientes Cta. Cte.

	Tablas aFectadas:   Cbtes,Cbtes_Aplica, Clientes_CtaCte

	Usado en:           ERP

	Parametro(s):       Id_Cliente,ModoDebug,Modo       
						Se reciben en JSON.

	Forma de uso:       EXEC CPJ_Cbtes_Cli_Aplica_Auto '{"Id_Cliente":"57691","ModoDebug":"0","Modo":"CBTES_APLICA"}'

	Notas adicionales:  Modo:
                        APLICAR  ->  Generar la aplicaci¾n

                        Modo de Control que no genera nada
                        FACTURAS ->  Muestra las Facturas a aplciar

***************************************************************************************************

SUMARIO DE CAMBIOS
FECHA(yyyy-mm-dd)    Autor              Comentarios
------------------- ------------------- ------------------------------------------------------------

***************************************************************************************************/



/*Variables recibidas por parametro a traves del JSON*/

DECLARE @pId_Cliente    INT
        ,@pModoDebug    TINYINT
        ,@pModo         VARCHAR(20)  --APLICAR - Aplicar           

SET @pId_Cliente       = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pModoDebug        = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pModo             = UPPER(ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Modo')), ''))


/*FIN Variables recibidas por parametro a traves del JSON*/

SET NOCOUNT ON

/*Declaracion Variables Locales*/

DECLARE @ErrorMessage			VARCHAR(100)
		,@Id_Trans_Fac			INT
		,@Id_Trans_Rec			INT
		,@Importe				DECIMAL(18,2)
		,@Fecha_Rec				DATETIME
		,@Fecha_Fac				DATETIME
		,@Cli_ReF_CtaCte_Agrup	TINYINT
		,@Id_Moneda				CHAR(3)
		,@Id_Unid_Negocio		CHAR(10)
		,@Nro					INT
		,@Nro_Nuevo				INT
		,@Nro_Hasta				INT


DECLARE @Ordenado_Nro TABLE
	(
		Fecha			DATETIME,
		Id_Trans_Fac	INT,
		Id_Trans_Rec	INT,
		Imp_Total		DECIMAL(18,2),
		Saldo			DECIMAL(18,2),
		Id_Moneda		CHAR(3),
		Id_Unid_Negocio CHAR(10),
		Nro				INT IDENTITY(1,1),
		Id_Trans_Aplic  INT,

		INDEX IX_OrdXXX (Fecha, Id_Trans_Fac, Id_Trans_Rec)
	);

DECLARE @Facturas TABLE (
	Id_Trans INT PRIMARY KEY
	,Fecha DATETIME
	,Imp_Total DECIMAL(18,2)
	,Id_Moneda CHAR(3)
	,Id_Unid_Negocio CHAR(10)
)

DECLARE @Recibos TABLE (
	Id_Trans INT PRIMARY KEY
	,Fecha DATETIME
	,Imp_Total DECIMAL(18,2)
	,Id_Moneda CHAR(3)
	,Id_Unid_Negocio CHAR(10)
)

DECLARE @Ordenado TABLE
	(
		Fecha DATETIME,
		Id_Trans_Fac INT,
		Id_Trans_Rec INT,
		Imp_Total DECIMAL(18,2),
		Saldo DECIMAL(18,2),
		Id_Moneda CHAR(3),
		Id_Unid_Negocio CHAR(10),

		INDEX IX_OrdXXX (Fecha, Id_Trans_Fac, Id_Trans_Rec)
	);
DECLARE @Unid_Negocio TABLE (Id_Unid_Negocio CHAR(10))
DECLARE @Monedas TABLE (Id_Moneda CHAR(3))


DECLARE @Rec_Ceros TABLE
	(
		Fecha			DATETIME,
		Id_Trans_Fac	INT,
		Id_Trans_Rec	INT,
		Imp_Total		DECIMAL(18,2),
		Saldo			DECIMAL(18,2),
		Id_Moneda		CHAR(3),
		Id_Unid_Negocio CHAR(10),
		Nro				INT,
		Id_Trans_Aplic  INT,

		INDEX IX_rECXXX (Fecha, Id_Trans_Fac, Id_Trans_Rec)
	);


/*FIN Declaracion Variables Locales*/

IF NOT @pModo IN ('FACTURAS','RECIBOS','CBTES_APLICA','CBTES_APLICA_CERO','FACTURAS_CTRL','RECIBOS_CTRL','APLICAR','APLICAR_CERO') 
BEGIN
	SET @ErrorMessage = 'PARAMETRO INVALIDO'
	SELECT 1 AS ErrorNumber,0 AS ErrorSeverity,0 AS ErrorState,0 AS ErrorProcedure,0 AS ErrorLine,@ErrorMessage AS ErrorMessage
	RETURN 9998
END


SET @Cli_ReF_CtaCte_Agrup = CONVERT(TINYINT,dbo.CF_xParam('Cli_ReF_CtaCte_Agrup'))


BEGIN TRY
INSERT INTO @Facturas
SELECT F.Id_Trans,F.Fecha,F.Imp_Total,F.Id_Moneda,T.Id_Unid_Negocio 
    FROM Cbtes F
	    JOIN Cbtes_Tipos t ON F.Id_Tipo_Cbte = t.Id_Tipo_Cbte AND t.Compromete_Factura = 1
	    WHERE F.Id_Estado_Cbte = 1 AND F.Id_Cond_Pago != 1
	    AND F.Id_Cliente = @pId_Cliente

IF @Cli_ReF_CtaCte_Agrup = 1
	INSERT INTO @Facturas
		SELECT Id_Trans,Fecha,Imp_Total,F.Id_Moneda,T.Id_Unid_Negocio  
			FROM Cbtes F
				JOIN Cbtes_Tipos t ON F.Id_Tipo_Cbte = t.Id_Tipo_Cbte AND t.Compromete_Factura = 1
				JOIN Clientes C ON C.Id_Cliente = F.Id_Cliente
				WHERE F.Id_Estado_Cbte = 1 AND F.Id_Cond_Pago != 1
				AND C.Id_Cliente_ReF =  @pId_Cliente

INSERT INTO @Recibos
SELECT R.Id_Trans,DATEADD(HOUR,23,R.Fecha) AS Fecha,R.Imp_Total,R.Id_Moneda,T.Id_Unid_Negocio
    FROM Cbtes R
	    JOIN Cbtes_Tipos t ON r.Id_Tipo_Cbte = t.Id_Tipo_Cbte 
		JOIN Clientes C ON C.Id_Cliente = r.Id_Cliente
	    WHERE r.Id_Estado_Cbte = 1
		AND ((t.Compromete_Factura = -1 AND r.Id_Cond_Pago != 1) OR t.Compromete_Recibos = 1)
	    AND r.Id_Cliente = @pId_Cliente

IF @Cli_ReF_CtaCte_Agrup = 1
	INSERT INTO @Recibos
		SELECT r.Id_Trans,DATEADD(HOUR,23,R.Fecha),r.Imp_Total,R.Id_Moneda,T.Id_Unid_Negocio 
			FROM Cbtes r
				JOIN Cbtes_Tipos t ON r.Id_Tipo_Cbte = t.Id_Tipo_Cbte 
				JOIN Clientes C ON C.Id_Cliente = r.Id_Cliente
				WHERE r.Id_Estado_Cbte = 1
				AND ((t.Compromete_Factura = -1 AND r.Id_Cond_Pago != 1) OR t.Compromete_Recibos = 1)
				AND C.Id_Cliente_ReF =  @pId_Cliente


DECLARE @Cbtes_Aplica TABLE (Id_Trans_Fac INT, Id_Trans_Rec INT, Importe DECIMAL(18,2), Fecha_Rec DATETIME)


IF @pModo = 'FACTURAS'      
BEGIN 
	SELECT * FROM @Facturas ORDER BY Id_Trans
	RETURN 0
END

IF @pModo = 'RECIBOS'       
BEGIN
	SELECT * FROM @Recibos ORDER BY Id_Trans
	RETURN 0
END


IF @pModo IN ('CBTES_APLICA','APLICAR') 
BEGIN
	DECLARE Aplic CURSOR FOR SELECT Id_Trans,Fecha,Imp_Total,Id_Moneda,Id_Unid_Negocio FROM @Facturas

	OPEN Aplic
	FETCH NEXT FROM Aplic INTO @Id_Trans_Fac,@Fecha_Fac , @Importe , @Id_Moneda , @Id_Unid_Negocio
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Id_Trans_Rec = 0
		SELECT TOP 1 @Id_Trans_Rec = R.Id_Trans , @Fecha_Rec = R.Fecha FROM @Recibos R 
						WHERE R.Imp_Total = @Importe 
							AND R.Id_Moneda = @Id_Moneda
							AND R.Id_Unid_Negocio = @Id_Unid_Negocio
							AND NOT EXISTS (SELECT 1 FROM @Cbtes_Aplica A WHERE R.Id_Trans = A.Id_Trans_Rec)

						ORDER BY Fecha,Id_Trans
		IF ISNULL(@Id_Trans_Rec,0) != 0
		BEGIN
			IF @Fecha_Rec < @Fecha_Fac SET @Fecha_Rec = @Fecha_Fac
			INSERT INTO @Cbtes_Aplica (Id_Trans_Fac, Id_Trans_Rec, Importe, Fecha_Rec)
				VALUES (@Id_Trans_Fac,@Id_Trans_Rec,@Importe,@Fecha_Rec)
		END

		FETCH NEXT FROM Aplic INTO @Id_Trans_Fac,@Fecha_Fac , @Importe , @Id_Moneda , @Id_Unid_Negocio
	END
	CLOSE Aplic
	DEALLOCATE ApliC
END

IF @pModo IN ('CBTES_APLICA_CERO','APLICAR_CERO') 
BEGIN
	INSERT INTO @Ordenado SELECT Fecha,Id_Trans,0,Imp_Total,0,Id_Moneda,Id_Unid_Negocio FROM @Facturas
	INSERT INTO @Ordenado SELECT Fecha,0,Id_Trans,Imp_Total,0,Id_Moneda,Id_Unid_Negocio FROM @Recibos

	UPDATE @Ordenado SET Id_Moneda = CONVERT(CHAR(3),dbo.CF_xParam('Moneda_Nacional')) WHERE Id_Moneda IS NULL
	UPDATE @Ordenado SET Id_Unid_Negocio = '' WHERE Id_Unid_Negocio IS NULL

	
	INSERT INTO @Unid_Negocio SELECT DISTINCT Id_Unid_Negocio FROM  @Ordenado 
	INSERT INTO @Monedas SELECT DISTINCT Id_Moneda FROM  @Ordenado 


	DECLARE Cur_UN CURSOR FOR SELECT Id_Unid_Negocio FROM @Unid_Negocio
	OPEN Cur_UN
	FETCH NEXT FROM Cur_UN INTO @Id_Unid_Negocio
	WHILE @@FETCH_STATUS = 0
	BEGIN 
		DECLARE Cur_Monedas CURSOR FOR SELECT Id_Moneda FROM @Monedas
		OPEN Cur_Monedas
		FETCH NEXT FROM Cur_Monedas INTO @Id_Moneda
		WHILE @@FETCH_STATUS = 0
		BEGIN 
			DELETE FROM @Ordenado_Nro
			DELETE FROM @Rec_Ceros

			/*Calculo el campo Saldo **********************************************************************************************************************/
			;WITH Movs AS
				(
					SELECT o.*, Mov = CASE
								WHEN o.Id_Trans_Fac <> 0 THEN  o.Imp_Total   -- Factura suma
								WHEN o.Id_Trans_Rec <> 0 THEN -o.Imp_Total   -- Recibo resta
								ELSE 0
								END
					FROM @Ordenado o WHERE o.Id_Unid_Negocio = @Id_Unid_Negocio AND o.Id_Moneda = @Id_Moneda
				),
				Calc AS
				(
					SELECT 	m.*, SaldoCalc =
							SUM(m.Mov) OVER
							(
								ORDER BY
									m.Fecha,
									CASE WHEN m.Id_Trans_Fac <> 0 THEN 0 ELSE 1 END, -- mismo dÝa: primero facturas, luego recibos
									m.Id_Trans_Fac,
									m.Id_Trans_Rec
								ROWS UNBOUNDED PRECEDING
							)
					FROM Movs m
				)
			UPDATE o SET o.Saldo = c.SaldoCalc FROM @Ordenado o 
				JOIN Calc c
					ON c.Fecha = o.Fecha
					AND c.Id_Trans_Fac = o.Id_Trans_Fac
					AND c.Id_Trans_Rec = o.Id_Trans_Rec
					AND c.Imp_Total    = o.Imp_Total
				WHERE o.Id_Unid_Negocio = @Id_Unid_Negocio AND o.Id_Moneda = @Id_Moneda;

			/*Fin Calculo el campo Saldo **********************************************************************************************************************/

			
			INSERT INTO @Ordenado_Nro (Fecha			
									   ,Id_Trans_Fac	
									   ,Id_Trans_Rec	
									   ,Imp_Total		
									   ,Saldo			
									   ,Id_Moneda		
									   ,Id_Unid_Negocio)

			SELECT Fecha			
				   ,Id_Trans_Fac	
				   ,Id_Trans_Rec	
				   ,Imp_Total		
				   ,Saldo			
				   ,Id_Moneda		
				   ,Id_Unid_Negocio
				FROM @Ordenado ORDER BY Fecha,Id_Trans_Fac,Id_Trans_Rec

			--select * from @Ordenado_Nro

			IF NOT EXISTS(SELECT 1 FROM @Ordenado_Nro WHERE Saldo = 0)
				DELETE FROM @Ordenado_Nro

			DELETE @Ordenado_Nro WHERE Nro > (SELECT TOP 1 Nro FROM @Ordenado_Nro WHERE Saldo = 0 ORDER BY Nro DESC)
			
			--SELECT * FROM @Ordenado_Nro	

            INSERT INTO @Rec_Ceros
				SELECT * FROM @Ordenado_Nro WHERE Id_Trans_Rec != 0 AND Saldo = 0 ORDER BY Nro  

			IF @pModo IN ('CBTES_APLICA','CBTES_APLICA_CERO')
               SELECT * FROM @Rec_Ceros
			

			DECLARE Cur_Aplic_Cero CURSOR FOR SELECT Id_Trans_Fac,Id_Trans_Rec,Nro,Fecha FROM @Rec_Ceros
			OPEN Cur_Aplic_Cero
			FETCH NEXT FROM Cur_Aplic_Cero INTO @Id_Trans_Fac,@Id_Trans_Rec,@Nro,@Fecha_Rec
			WHILE @@FETCH_STATUS = 0
			BEGIN
				--SELECT * FROM @Ordenado_Nro WHERE Nro < @Nro AND Id_Trans_Aplic IS NULL 
				UPDATE @Ordenado_Nro SET Id_Trans_Aplic = @Id_Trans_Rec ,Fecha = @Fecha_Rec 
									WHERE Nro <= @Nro AND Id_Trans_Aplic IS NULL 
									
				FETCH NEXT FROM Cur_Aplic_Cero INTO @Id_Trans_Fac,@Id_Trans_Rec,@Nro,@Fecha_Rec
			END
			CLOSE Cur_Aplic_Cero
			DEALLOCATE Cur_Aplic_Cero

			
			
			IF @pModo IN ('CBTES_APLICA','CBTES_APLICA_CERO')
			   SELECT * FROM @Ordenado_Nro

            DELETE @Ordenado_Nro WHERE Id_Trans_Rec = Id_Trans_Aplic AND Id_Trans_Aplic IS NOT NULL  

			

			INSERT INTO @Cbtes_Aplica
				SELECT Id_Trans_Fac,Id_Trans_Aplic,Imp_Total,Fecha FROM @Ordenado_Nro 
					WHERE Id_Trans_Fac <> 0 AND Id_Trans_Aplic IS NOT NULL ORDER BY Nro

			INSERT INTO @Cbtes_Aplica
				SELECT Id_Trans_Rec,Id_Trans_Aplic,Imp_Total * -1,Fecha FROM @Ordenado_Nro 
					WHERE Id_Trans_Rec <> 0 AND Id_Trans_Aplic IS NOT NULL ORDER BY Nro
            --SELECT * FROM @Cbtes_Aplica
            --RETURN  

			FETCH NEXT FROM Cur_Monedas INTO @Id_Moneda
		END
		CLOSE Cur_Monedas
		DEALLOCATE Cur_Monedas
	    
		FETCH NEXT FROM Cur_UN INTO @Id_Unid_Negocio
	END
	CLOSE Cur_UN
	DEALLOCATE Cur_UN
END

IF @pModo IN ('CBTES_APLICA','CBTES_APLICA_CERO')
BEGIN
    SELECT * FROM @Cbtes_Aplica a
	    LEFT JOIN @Facturas F ON F.Id_Trans = a.Id_Trans_Fac 
	    LEFT JOIN @Recibos R ON R.Id_Trans = a.Id_Trans_Rec
        RETURN 0
END

IF @pModo = 'FACTURAS_CTRL'
BEGIN
    SELECT Id_Trans_Fac,COUNT(*) FROM @Cbtes_Aplica GROUP BY Id_Trans_Fac ORDER BY 2 DESC,1
        RETURN 0
END

IF @pModo = 'RECIBOS_CTRL'
BEGIN
    SELECT Id_Trans_Rec,COUNT(*) FROM @Cbtes_Aplica GROUP BY Id_Trans_Rec ORDER BY 2 DESC,1
        RETURN 0
END

IF @pModo = 'APLICAR'
BEGIN
	IF  EXISTS (SELECT 1 FROM @Cbtes_Aplica)
	BEGIN
		BEGIN TRAN
		INSERT INTO Cbtes_Aplica SELECT Id_Trans_Fac,1,Id_Trans_Rec,1,0,Importe,CONVERT(DATE,Fecha_Rec) FROM @Cbtes_Aplica

		UPDATE Cbtes           SET Id_Estado_Cbte = 2,Saldo = 0 FROM Cbtes c           JOIN @Cbtes_Aplica a ON c.Id_Trans = a.Id_Trans_Fac
		UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 2,Saldo = 0 FROM Clientes_CtaCte c JOIN @Cbtes_Aplica a ON c.Id_Trans = a.Id_Trans_Fac

		UPDATE Cbtes           SET Id_Estado_Cbte = 2,Saldo = 0 FROM Cbtes r           JOIN @Cbtes_Aplica a ON r.Id_Trans = a.Id_Trans_Rec
		UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 2,Saldo = 0 FROM Clientes_CtaCte r JOIN @Cbtes_Aplica a ON r.Id_Trans = a.Id_Trans_Rec
		COMMIT
    END
    SELECT @ErrorMessage = CONVERT(VARCHAR,COUNT(*)) + ' Cbtes. Aplicados ' FROM @Cbtes_Aplica
    SELECT 0 AS ErrorNumber,0 AS ErrorSeverity,0 AS ErrorState,0 AS ErrorProcedure,0 AS ErrorLine,@ErrorMessage AS ErrorMessage
    RETURN 0
END

IF @pModo = 'APLICAR_CERO'
BEGIN
	IF  EXISTS (SELECT 1 FROM @Cbtes_Aplica)
	BEGIN
		BEGIN TRAN
		INSERT INTO Cbtes_Aplica 
			SELECT Id_Trans_Fac,1,Id_Trans_Rec,1,0,Importe,Fecha_Rec FROM @Cbtes_Aplica

		UPDATE Cbtes           SET Id_Estado_Cbte = 2,Saldo = 0 FROM Cbtes c           JOIN @Cbtes_Aplica a ON c.Id_Trans = a.Id_Trans_Fac
		UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 2,Saldo = 0 FROM Clientes_CtaCte c JOIN @Cbtes_Aplica a ON c.Id_Trans = a.Id_Trans_Fac

		UPDATE Cbtes           SET Id_Estado_Cbte = 2,Saldo = 0 FROM Cbtes r           JOIN @Cbtes_Aplica a ON r.Id_Trans = a.Id_Trans_Rec
		UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 2,Saldo = 0 FROM Clientes_CtaCte r JOIN @Cbtes_Aplica a ON r.Id_Trans = a.Id_Trans_Rec
		COMMIT
    END
    SELECT @ErrorMessage = CONVERT(VARCHAR,COUNT(*)) + ' Cbtes. Aplicados ' FROM @Cbtes_Aplica
    SELECT 0 AS ErrorNumber,0 AS ErrorSeverity,0 AS ErrorState,0 AS ErrorProcedure,0 AS ErrorLine,@ErrorMessage AS ErrorMessage
    RETURN 0
END

RETURN 0

END TRY
BEGIN CATCH
    EXECUTE usp_GetErrorInFo
	IF @@TRANCOUNT > 0 ROLLBACK
    RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Cli_DesAplicar]  @pJson VARCHAR(8000)	 
AS

/***************************************************************************************************

	Procedimiento:      CPJ_Cbtes_Cli_DesAplicar
	Fecha de Creacion:  2026-03-08
	Creado por:         Gabriel Centenari
	Descripcion:        Desaclica toda la cta.cte. y deja todo en pendiente , regenerando cta.cte.


	Llamado por:        Boton en Clientes Cta. Cte.

	Tablas aFectadas:   Cbtes,Cbtes_Aplica, Clientes_CtaCte

	Usado en:           ERP

	Parametro(s):       Id_Cliente,ModoDebug      
						Se reciben en JSON.

	Forma de uso:       EXEC CPJ_Cbtes_Cli_DesAplicar '{"Id_Cliente":"63858","ModoDebug":"0"}'


***************************************************************************************************

SUMARIO DE CAMBIOS
FECHA(yyyy-mm-dd)    Autor              Comentarios
------------------- ------------------- ------------------------------------------------------------

***************************************************************************************************/



/*Variables recibidas por parametro a traves del JSON*/

DECLARE @pId_Cliente    INT
        ,@pModoDebug    TINYINT
     

SET @pId_Cliente       = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pModoDebug        = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)

/*FIN Variables recibidas por parametro a traves del JSON*/

SET NOCOUNT ON
SET XACT_ABORT ON

/*Declaracion Variables Locales*/

DECLARE @ErrorMessage			VARCHAR(100)
		,@Cli_ReF_CtaCte_Agrup	TINYINT


/*FIN Declaracion Variables Locales*/

IF @pId_Cliente < 2		
	RETURN 0


SET @Cli_ReF_CtaCte_Agrup = CONVERT(TINYINT,dbo.CF_xParam('Cli_ReF_CtaCte_Agrup'))

DECLARE @CliAfectados TABLE
(
    Id_Cliente INT NOT NULL PRIMARY KEY
);

BEGIN TRY
	BEGIN TRAN 
 
    INSERT INTO @CliAfectados 
	SELECT Id_Cliente FROM Clientes WHERE Id_Cliente = @pId_Cliente
	
	IF @Cli_ReF_CtaCte_Agrup = 1
		INSERT INTO @CliAfectados 
		SELECT C.Id_cliente FROM Clientes C 
			WHERE C.Id_cliente_ref = @pId_Cliente
				AND NOT EXISTS  ( SELECT 1
					  FROM @CliAfectados T
					  WHERE T.Id_Cliente = C.Id_Cliente
					)


	DELETE Cbtes_Aplica 
		FROM Cbtes C 
			JOIN Cbtes_Aplica A ON C.Id_trans = A.Id_Trans
		WHERE A.Id_Trans <> 0 
			AND C.Id_cliente IN (SELECT Id_Cliente FROM @CliAfectados)


	DELETE Clientes_CtaCte 
		FROM Cbtes C
			JOIN Clientes_CtaCte A ON C.Id_trans = A.Id_Trans 
			JOIN Cbtes_Tipos T ON C.Id_tipo_cbte = T.Id_tipo_cbte 
		WHERE (T.Compromete_Recibos in (1,-1) OR T.Compromete_Factura IN (1,-1)) 
			AND C.Id_cliente IN (SELECT Id_Cliente FROM @CliAfectados)

	UPDATE Cbtes SET Saldo = C.Imp_Total, Id_Estado_Cbte = 1 
		FROM Cbtes C
			JOIN Cbtes_Tipos T ON  t.Id_Tipo_Cbte = C.Id_Tipo_Cbte
		WHERE ((t.Compromete_Factura in (1,-1) AND C.id_cond_pago <> 1) Or t.Compromete_Recibos IN (1,-1))
			AND C.Id_Estado_Cbte <> 3
			AND C.Id_cliente IN (SELECT Id_Cliente FROM @CliAfectados)

	INSERT INTO Clientes_CtaCte (Id_Trans,Nro_Cuota,Id_Cliente,Fecha,Fecha_Vence,Descripcion,Importe,Saldo,Id_Estado_Cbte,Id_Moneda)
	SELECT C.Id_Trans,1,@pId_Cliente,C.Fecha,C.Fecha_Venc,dbo.CF_Cbte_Descrip(C.Id_Trans),C.Imp_Total,C.Saldo,1,C.Id_Moneda 
		FROM Cbtes C
			JOIN Cbtes_Tipos T ON t.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
		WHERE ((t.Compromete_Factura = 1 AND C.id_cond_pago <> 1) Or t.Compromete_Recibos = -1)
			AND C.imp_total <> 0
			AND C.Id_Estado_Cbte = 1
			AND C.Id_cliente IN (SELECT Id_Cliente FROM @CliAfectados)

	INSERT INTO Clientes_CtaCte (Id_Trans,Nro_Cuota,Id_Cliente,Fecha,Fecha_Vence,Descripcion,Importe,Saldo,Id_Estado_Cbte,Id_Moneda)
	SELECT C.Id_Trans,1,@pId_Cliente,C.Fecha,C.Fecha_Venc,dbo.CF_Cbte_Descrip(C.Id_Trans),C.Imp_Total * -1,C.Saldo * -1,1,C.Id_Moneda  
		FROM Cbtes C
			JOIN Cbtes_Tipos T ON t.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
		WHERE ((t.Compromete_Factura = -1 AND C.id_cond_pago <> 1) Or t.Compromete_Recibos = 1)
			AND C.imp_total <> 0
			AND C.Id_Estado_Cbte <> 3 
			AND C.Id_cliente IN (SELECT Id_Cliente FROM @CliAfectados)

	COMMIT
    SELECT @ErrorMessage = CONVERT(VARCHAR,COUNT(*)) + ' Cbtes. Procesados ' 
				FROM Clientes_CtaCte 
				WHERE Id_Cliente IN (SELECT Id_Cliente FROM @CliAfectados)
					AND Importe <> 0 AND Id_Estado_Cbte = 1
    SELECT 0 AS ErrorNumber,0 AS ErrorSeverity,0 AS ErrorState,0 AS ErrorProcedure,0 AS ErrorLine,@ErrorMessage AS ErrorMessage
    RETURN 0

END TRY
BEGIN CATCH
    
	IF @@TRANCOUNT > 0 ROLLBACK
	EXECUTE usp_GetErrorInFo
    RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Compra_Fin] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*Variables recibidas por parßmetro a traves del JSON*/
DECLARE @pFlagUsarTrans		     	TINYINT
DECLARE @pModoDebug			    	TINYINT
DECLARE @pId_Trans				    INT
DECLARE @pFlag_Tabla_Temp           TINYINT


SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pFlag_Tabla_Temp           = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pFlag_Tabla_Temp,'Flag_Tabla_Temp')), 0)

/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
DECLARE @Result_Stored_Invocado				INT
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Cta_Contable					INT
DECLARE @Fecha								DATETIME
DECLARE @Observacion						VARCHAR(100)
DECLARE @Item								SMALLINT

DECLARE @Descripcion_Cbte					VARCHAR(80)
DECLARE @Imp_Gravado_Sum_It					DECIMAL(12,2)
DECLARE @Porc_Bonificacion_Cb				DECIMAL(5,2)
DECLARE @Imp_Gravado						DECIMAL(12,2)
DECLARE @Imp_Iva_Sum_It						DECIMAL(12,2)
DECLARE @Imp_Iva							DECIMAL(12,2)
DECLARE @Imp_Exento							DECIMAL(12,2)
DECLARE @Imp_Total							DECIMAL(12,2)
DECLARE @Saldo								DECIMAL(12,2)
DECLARE @Imp_Bonificacion					DECIMAL(12,2)
DECLARE @Cantidad							DECIMAL(12,4)
DECLARE @Id_Tipo_Cbte						CHAR(4)
DECLARE @Compromete_Stock					SMALLINT
/*Fin de Declaraciones Variables Locales */


BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Compra_Fin'
		PRINT 'Parametros:'
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + ' Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans)
	END
	
	/*===================================================================*/

	IF(@pId_Trans = 0)
	BEGIN
		SET @rtaErrorStored = 70001 /*Transaccion no abierta*/
		
		SELECT	 @rtaErrorStored	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,''					AS ErrorMessage
			
		IF @pFlagUsarTrans <> 0 
		BEGIN
			ROLLBACK
		END
		
		RETURN 9999
	END


	/*===================================================================*/
	
	SELECT  
	@Id_Tipo_Cbte	= ISNULL(Id_Tipo_Cbte, '')
	FROM Cbtes
	WHERE 
	Id_Trans = @pId_Trans
	
	/*===================================================================*/

	SELECT  
	@Compromete_Stock	= ISNULL(Compromete_Stock, 0)
	FROM Cbtes_Tipos 
	WHERE 
	Id_Tipo_Cbte = @Id_Tipo_Cbte
	
	/*===================================================================*/
	
	SET @Descripcion_Cbte = (dbo.CF_Cbte_Descrip(@pId_Trans))
	
	/*===================================================================*/	
	
	UPDATE Transacciones SET Descripcion = @Descripcion_Cbte WHERE Id_Trans = @pId_Trans
	
	/*===================================================================*/	
	
	UPDATE Cbtes_Items 	SET Id_Estado_Cbte = 1	WHERE Id_Trans = @pId_Trans
	
	/*===================================================================*/
		
	SET @Porc_Bonificacion_Cb	= ISNULL((SELECT ISNULL(Porc_Bonificacion, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans), 0)
	
	IF @pFlag_Tabla_Temp = 0
	   BEGIN
        	SET @Imp_Gravado_Sum_It		= ISNULL((SELECT SUM((ISNULL(Imp_Gravado, 0) * ISNULL(Cantidad_Saldo, 0))) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)
        	SET @Imp_Iva_Sum_It			= ISNULL((SELECT SUM(ISNULL(Imp_Iva, 0)) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)
 	        SET @Imp_Exento				= ISNULL((SELECT SUM((ISNULL(Imp_Exento, 0) * ISNULL(Cantidad_Saldo, 0))) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)
        	SET @Cantidad				= ISNULL((SELECT COUNT(*) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)  
       END
      ELSE
	   BEGIN
        	SET @Imp_Gravado_Sum_It		= ISNULL((SELECT SUM((ISNULL(Imp_Gravado, 0) * ISNULL(Cantidad_Saldo, 0))) FROM #ITEMS_CBTE), 0)
        	SET @Imp_Iva_Sum_It			= ISNULL((SELECT SUM(ISNULL(Imp_Iva, 0)) FROM #ITEMS_CBTE), 0)
 	        SET @Imp_Exento				= ISNULL((SELECT SUM((ISNULL(Imp_Exento, 0) * ISNULL(Cantidad_Saldo, 0))) FROM #ITEMS_CBTE), 0)
        	SET @Cantidad				= ISNULL((SELECT COUNT(*) FROM #ITEMS_CBTE), 0)  
       END        	
        	    	
	IF(@Porc_Bonificacion_Cb = 0)
		SET @Imp_Gravado		= @Imp_Gravado_Sum_It
	  ELSE
		SET @Imp_Gravado		= (@Imp_Gravado_Sum_It * ((100 - @Porc_Bonificacion_Cb) / 100))


	SET @Imp_Iva				= @Imp_Iva_Sum_It
	SET @Imp_Total				= @Imp_Gravado + @Imp_Iva + @Imp_Exento
	SET @Saldo					= @Imp_Total
	SET @Imp_Bonificacion		= (@Imp_Gravado_Sum_It - @Imp_Gravado)		
	
	/*===================================================================*/	
	
	IF @Imp_Iva = 0
	BEGIN
		SET @Imp_Exento = @Imp_Exento+@Imp_Gravado
		SET @Imp_Gravado = 0
	END
	
	/*===================================================================*/	
	
	IF(@Compromete_Stock = 0)
	BEGIN
		UPDATE Cbtes 
		SET 
		Id_Estado_Cbte = 1 /*Pendiente*/
		WHERE
		Id_Trans = @pId_Trans
		
		UPDATE Proveedores_CtaCte 
		SET 
		Id_Estado_Cbte = 1 /*Pendiente*/
		WHERE
		Id_Trans = @pId_Trans	
	END
	ELSE
	BEGIN
		UPDATE Cbtes 
		SET 
		Cantidad			= @Cantidad,
		Imp_Gravado			= @Imp_Gravado, 
		Imp_Exento			= @Imp_Exento,
		Saldo				= @Saldo, 
		Imp_Iva				= @Imp_Iva,
		Imp_Bonificacion	= @Imp_Bonificacion,
		Imp_Total			= @Imp_Total
		WHERE 
		Id_Trans = @pId_Trans

		/*===================================================================*/	
			
		UPDATE Proveedores_CtaCte
		SET
		Descripcion		= @Descripcion_Cbte,
		Importe			= @Imp_Total,
		Saldo			= @Saldo
		WHERE
		Id_Trans = @pId_Trans		
	END
	
	/*===================================================================*/	
	
	SET @JSON_Parametros_Stored_Invocado =	'{' +
											dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('FlagRegenerar', 1, 'TINYINT') + 
											'}'
						
	EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Ctas_Contables_Generar @JSON_Parametros_Stored_Invocado
	IF ISNULL(@Result_Stored_Invocado,0) <> 0 
	BEGIN
		/*El CPJ_Cbtes_Ctas_Contables_Generar deberÝa devolver el SELECT con el error*/
		RETURN 9999
	END		

	--17/11/2020 Se agrega que si el saldo es 0 en cta cte tiene que poner el estado en completo
	IF(@Compromete_Stock <> 0 AND @Saldo = 0)
	BEGIN
		UPDATE Proveedores_CtaCte
		SET
		Id_Estado_Cbte = 2 --Completo
		WHERE
		Id_Trans = @pId_Trans
	END

	/*===================================================================*/	
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	

	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT') + ',' +
								dbo.CF_Json_ParsearVariable('descrip_Cbte', @Descripcion_Cbte, 'VARCHAR') +
								'}'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Compra_Fin'
	END

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0 


/*
EXEC dbo.CPJ_Cbtes_Compra_Fin '{"FlagUsarTrans":"0",
									"ModoDebug":"1",
									"Id_Trans":"2496949"
									}'
*/
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Compra_Generar] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans		TINYINT
DECLARE @pModoDebug			TINYINT
DECLARE @pId_Usuario		SMALLINT
DECLARE @pId_Trans			INT
