SET @pCotizacion			= ISNULL(CONVERT(DECIMAL(12,4), dbo.CF_JSON_VALUE(@pJson,'Cotiz')), 0)
SET @pEfe_Cotiz		     	= ISNULL(CONVERT(DECIMAL(12,4), dbo.CF_JSON_VALUE(@pJson,'Efe_Cotiz')), 1)
SET @pValores				= ISNULL(CONVERT(VARCHAR(MAX), dbo.CF_JSON_VALUE(@pJson,'Valores')), '')
SET @pObservacion			= ISNULL(CONVERT(VARCHAR(MAX), dbo.CF_JSON_VALUE(@pJson,'Observacion')), '')
SET @pOmitir_Resultado_Ok	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Resultado_OK')), 0)
SET @pCambiar_Acredita	    = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_F_Acred')), 0)
/*Fin Declaracion Variables Json*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
