					,0				AS ErrorState 
					,0				AS ErrorProcedure  
					,0				AS ErrorLine		
					,@Mensaje		AS ErrorMessage
					,@Id_Trans		AS Id_Trans
		END

		IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0   ROLLBACK
		RETURN 2004
	END

	SET @Flag_Existe_Moneda = ISNULL((SELECT 1 FROM Valores_Monedas WHERE Id_Moneda = @pId_Moneda), 0)
	IF (@Flag_Existe_Moneda = 0)
	BEGIN
