	SET	@Destinatario   = '' 
	SET	@Id_Pais		= ''   
	SET	@Id_Provincia	= ''
	SET	@Id_Localidad	= ''
	SET	@Id_Lista		= 0
	SET	@Cuit			= ''
	SET	@Id_Iva			= ''
	SET	@Id_Concepto	= @pId_Concepto

	SET @Email			=  ''


	SET @Comprobante_Nro		= 0		
	SET @Plazo_Venc				= 0
	SET @Fecha_Venc				= @pFecha --Siempre es la misma en Recibos, no se basa en Cond_Pago Dias_Venc	
	SET @Periodo_Iva			= @pFecha
	SET @Periodo				= @pFecha
	SET @Imp_Total				= @pTotal
	SET @Saldo					= @pTotal
	SET @Imp_Gravado			= @pTotal
	SET @Cbte_Nro_Externo		= ''
	
	/*TO-DO: De aca para abajo por ahora por Default*/
	SET @Id_Cond_Vta			= ''
