	SET @Remito_Nro				= ''
	SET @Pedido_Nro				= ''
	SET @Id_Tarjeta				= ''
	SET @Tarjeta_Nro			= ''
	SET @Cantidad_Saldo			= 0
	SET @Saldo_Anterior			= 0
	SET @NRO_DJAI				= ''
	SET @Cantidad_Equiv			= 0
	SET @Id_Trans_Origen		= 0
	SET @Id_Sede_Origen			= 0
	--SET @Patente_Transporte NULL
	--SET @Patente_Transporte_Acoplado NULL	

	/*FIN de Seteo de variables *******************************************************/
	
	INSERT INTO dbo.Cbtes
	(Id_Trans,			Id_Empresa,			Id_Sucursal,
	Id_Tipo_Cbte,		Cbte_Grupo,			Comprobante_Nro,
	Id_Cliente,			Id_Taller,			Id_Proceso,
	Id_Proveedor,		Signo,				Id_Estado_Cbte,
	Fecha,				Id_Dep_Fisico,		Id_Dep_Logico,
	Porc_DescEspecial,	Porc_DescFin,		Porc_Bonificacion,
	Porc_Iva,			Porc_Iva2,			Imp_Neto,
	Imp_DescEspecial,	Imp_DescFin,		Imp_Bonificacion,
	Imp_Gravado,		Imp_Exento,			Imp_IVA,
	Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
	Imp_Total,			Bultos,				NroImpresion,
	Exportado,			Id_Usuario,			Fecha_Estimada,
	Dir_Entrega,		Id_Pais,			Id_Provincia,
	Id_Localidad,		Persona_Recibe,		Porc_Iva3,
	Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
	Imp_IVA3,			Imp_Percep,			Saldo,
	Periodo_Iva,		Periodo,			Fecha_Venc,
	Observacion,		Id_Cond_Pago_Item,	Id_Cond_Pago,
	Id_Tipo_Reten,		Cant_Cuotas,		Id_Producto,
	Id_Formula,			Cantidad,			Id_Vendedor,
	Id_Transportista,	Id_Lista,			Id_Moneda,
	Cotizacion,			Destinatario,		Cuit,
	Id_Iva,				Cant_Batch,			Nro_Perm_Embarque,
	Fecha_Perm_Embar,	Saldo_Iva_Recup,	Lote,
	Suc_Destina,		Id_Puerto,			Id_Cond_Vta,
	Cbte_Nro_Externo,	Nota_Part1,			Nota_Part2,
	Id_Asiento,			Id_Centro_Costo,	Id_Valor,
	Cai,				Cai_Vence,			Des_Anio,
	Des_Aduana,			Des_Destina,		Des_Nro,
	Des_Verif,			Id_Contrato,		Id_Cobrador,
	Nro_Auto_Trib,		Id_Camp,			Remito_Nro,
	Pedido_Nro,			Id_Tarjeta,			Tarjeta_Nro,
	Cantidad_Saldo,		Saldo_Anterior,		NRO_DJAI,
	Cantidad_Equiv,		Id_Trans_Origen,	Id_Sede_Origen,
	Email,				Patente_Transporte,	Patente_Transporte_Acoplado,
	Flag_Lote)
	VALUES
	(@Id_Trans,			@Id_Empresa,		@Id_Sucursal,
	SUBSTRING(@pId_Tipo_Cbte,1,4),	@Cbte_Grupo,		@Comprobante_Nro,
	0,		@Id_Taller,			@Id_Proceso,
	@Id_Proveedor,		@Signo,				@Id_Estado_Cbte,
	@pFecha,			@Id_Dep_Fisico,		@Id_Dep_Logico,
	@Porc_DescEspecial,	@Porc_DescFin,		@Porc_Bonificacion,
	@Porc_Iva,			@Porc_Iva2,			@Imp_Neto,
	@Imp_DescEspecial,	@Imp_DescFin,		@Imp_Bonificacion,
	@Imp_Gravado,		@Imp_Exento,		@Imp_IVA,
	@Imp_IVA2,			@Imp_Percepcion_IB,	@Imp_Percepcion_Iva,
	@Imp_Total,			@Bultos,			@NroImpresion,
	@Exportado,			@pId_Usuario,		@Fecha_Estimada,
	@Dir_Entrega,		@Id_Pais,			@Id_Provincia,
	@Id_Localidad,		@Persona_Recibe,	@Porc_Iva3,
	@Imp_Gravado2,		@Imp_Gravado3,		@Imp_NoGravado,
	@Imp_IVA3,			@Imp_Percep,		@Saldo,
	@Periodo_Iva,		@Periodo,			@Fecha_Venc,
	@pObservacion,		@Id_Cond_Pago_Item,	@Id_Cond_Pago,
	@Id_Tipo_Reten,		@Cant_Cuotas,		@Id_Producto,
	@Id_Formula,		@Cantidad,			@Id_Vendedor,
	@Id_Transportista,	@Id_Lista,			@pId_Moneda,
	@pCotizacion,		@Destinatario,		@Cuit,
	@Id_Iva,			@Cant_Batch,		@Nro_Perm_Embarque,
	@Fecha_Perm_Embar,	@Saldo_Iva_Recup,	'',
	@Suc_Destina,		@Id_Puerto,			@Id_Cond_Vta,
	@Cbte_Nro_Externo,	@Nota_Part1,		@Nota_Part2,
	@Id_Asiento,		@Id_Centro_Costo,	@Id_Valor,
	@Cai,				@Cai_Vence,			@Des_Anio,
	@Des_Aduana,		@Des_Destina,		@Des_Nro,
	@Des_Verif,			0,		@Id_Cobrador,
	@Nro_Auto_Trib,		@Id_Camp,			@Remito_Nro,
	@Pedido_Nro,		@Id_Tarjeta,		@Tarjeta_Nro,
	@Cantidad_Saldo,	@Saldo_Anterior,	@Nro_DJAI,
	@Cantidad_Equiv,	@Id_Trans_Origen,	@Id_Sede_Origen,
	@Email,				@Patente_Transporte,@Patente_Transporte_Acoplado,
	@Flag_Lote)

	/*****************************************************************************/

	SET @Renglon_Nro = 1
	SET @Id_Estado_Mov_Caja = 2  
	SET @Descripcion = ISNULL((dbo.CF_Cbte_Descrip(@Id_Trans)), '')
	SET @Id_Tipo_Mov_Caja = 3 --DEPOSITO
	
	IF @pFecha = CONVERT(DATE,GETDATE())
		BEGIN
			SET @pFecha = GETDATE()
		END
	ELSE
		BEGIN
			SET @pFecha = DATEADD(hh,23,@pFecha)
			SET @pFecha = DATEADD(mi,59,@pFecha)
			/* cuando la fecha difiere del dia actual, set graba con ese al asl 23:59*/
		END	

	INSERT INTO dbo.Cajas_Mov
			(Id_Trans,			Renglon_Nro,	Id_Estado_Mov_Caja,
			Importe,			Descripcion,	Id_Periodo_Caja,
			Id_Tipo_Mov_Caja,	Fecha)
			VALUES
			(@Id_Trans,			@Renglon_Nro,	@Id_Estado_Mov_Caja,
			@pTotal,			@Descripcion,	@pId_Periodo_Caja,
			@Id_Tipo_Mov_Caja,	@pFecha)

	/*****************************************************************************/

	--SELECT * FROM CAJAS_MOV_TIPOS

	SET @Item = 1
	SET @Id_Estado_Concepto = 0
	
	INSERT INTO dbo.Cajas_Mov_Conceptos
			(Id_Trans,						Id_Concepto,			Item,
			Id_Estado_Concepto,		Importe,				Id_Periodo_Caja)
			VALUES
			(@Id_Trans,				@pId_Concepto,		@Item,
			@Id_Estado_Concepto,	@pTotal  ,	@pId_Periodo_Caja)

	/*****************************************************************************/
	
	UPDATE Transacciones SET Descripcion = LTRIM(RTRIM(@Descripcion)) WHERE Id_Trans = @Id_Trans

	/*****************************************************************************/
	--genero valores_mov y actualizo valores

	DECLARE @TempItems TABLE  (
 			Id_Valor   INT 
		)

	DECLARE @Item_Array VARCHAR(MAX)
	DECLARE @Pos INT


		SET @pValores = REPLACE(@pValores, '\', '')
		WHILE CHARINDEX('{', @pValores) > 0
		BEGIN

			-- Extraemos el contenido del primer objeto { ... }
			IF(@pModoDebug = 1)
				PRINT @pValores

			SET @Item_Array = SUBSTRING(@pValores, CHARINDEX('{', @pValores), CHARINDEX('}', @pValores) - CHARINDEX('{', @pValores) + 1)

			IF(@pModoDebug = 1)
				PRINT @Item_Array
    
			-- Insertamos en la tabla temporal usando tu funci├│n CF_JSON_VALUE para cada campo
			INSERT INTO @TempItems 	VALUES (
				CAST(dbo.CF_JSON_VALUE(@Item_Array, 'Val') AS  INT))
	 

			-- Borramos el objeto procesado de la cadena para pasar al siguiente
			SET @Pos = CHARINDEX('},', @pValores)
			IF @Pos > 0
				SET @pValores = SUBSTRING(@pValores, @Pos + 2, LEN(@pValores))
			ELSE
				SET @pValores = '' -- No hay m├ís elementos
		END


    DECLARE cur_Valores CURSOR FOR	SELECT Id_Valor from @TempItems
			
	OPEN cur_Valores
	FETCH NEXT FROM cur_Valores INTO @Id_Valor
	WHILE @@FETCH_STATUS = 0
	BEGIN	
				IF(@pModoDebug = 1)
				BEGIN
					PRINT '-------------------'
					PRINT 'Variables cursor: '
					PRINT @Id_Valor
					PRINT '-------------------'
				END 
				--actualizo valores

				Select Top 1 * into #Val_Mov From Valores_Mov where id_valor = @Id_Valor Order by Id_trans Desc
				
		        SET @Renglon_Nro = ISNULL((Select MAX(Renglon_Nro) From Valores_Mov where id_valor = @Id_Valor ),0)+1

                SET @Destinatario = ISNULL((Select ID_TARJETA From Valores  where id_valor = @Id_Valor ),'') 

				Update #Val_Mov Set Id_Trans = @Id_Trans
				               ,Renglon_nro = @Renglon_Nro
				               ,Id_Estado_Valor = 2
							   ,Id_Periodo_Caja = @pId_Periodo_Caja
							   ,Fecha_Acreditacion = @pFecha_Acreditacion
							  From #Val_Mov V

			    Insert Into Valores_Mov 
			           Select * from #Val_Mov

                Update Valores Set Id_Trans = @Id_Trans,  Id_Estado_Valor = 2 where Id_valor = @Id_Valor

			    Drop Table #Val_Mov

                -- genero mvtos banco

				SELECT @Nro_Valor = Valor_Nro, @Descripcion_Valor = Descripcion, @Fecha_Acreditacion = ISNULL(Fecha_Acreditacion,GETDATE()), @Importe_Valor = Importe
				       FROM VALORES WHERE ID_VALOR = @Id_Valor

                IF @pCambiar_Acredita = 1
				   Set @Fecha_Acreditacion = @pFecha_Acreditacion


				SET @Id_Mov_Cta_Banco = ISNULL((SELECT MAX(Id_Mov_Cta_Banco) FROM Bancos_Ctas_Mov),0)+1
  

				INSERT Into Bancos_Ctas_Mov (Id_Mov_Cta_Banco
					  ,Id_Trans
					  ,Id_Cta_Banco
					  ,Id_Tipo_Mov_Cta_Banco
					  ,Importe
					  ,Id_Est_Mov_Cta_Banco
					  ,Comprobante_Nro
					  ,Conciliado
					  ,Fecha_Acreditacion
					  ,Descripcion
					  ,Fecha_Mov)
                VALUES (@Id_Mov_Cta_Banco,@Id_Trans,@pId_Cta_Banco,1,@Importe_Valor,1,@Nro_Valor,0,@Fecha_Acreditacion,@Descripcion_Valor,@pFecha ) 

				FETCH NEXT FROM cur_Valores INTO @Id_Valor
               
    END

	CLOSE cur_Valores
	DEALLOCATE cur_Valores

-----INSERTO EN DEPOSITOS
    INSERT INTO Depositos ([Id_Trans]
		  ,[Fecha_Mov]
		  ,[Fecha_Acreditacion]
		  ,[Id_Cta_Banco]
		  ,[Importe]
		  ,[Id_Estado_Deposito]
		  ,[Boleta_Nro])
     VALUES
	      (@Id_Trans,@pFecha,@pFecha_Acreditacion,@pId_Cta_Banco,@pTotal,3,'')

-----EGREGO VALORES SI SE DEPOSITO EFECTIVO

    IF @pImporte_Efe <> 0
	   BEGIN 

				Select Top 1 * into #Val  From Valores  where Id_Tipo_Val = 'EFE' and Flag_Electronico = 0  Order by Id_trans Desc
				SET @Id_Valor_Nuevo = ISNULL((SELECT MAX(Id_Valor) FROM Valores),0)+1
	
				Update #Val Set Id_Trans = @Id_Trans
				               ,Id_Valor = @Id_Valor_Nuevo
							   ,Id_Periodo_Caja = @pId_Periodo_Caja
							   ,Id_Estado_Valor = 2
							   ,Fecha_Val = @pFecha 
							   ,Fecha_Emision = @pFecha 
							   ,Fecha_Acreditacion = @pFecha_Acreditacion
							   ,Importe = @pImporte_Efe 
							   ,Valor_Nro = 0
							   ,Descripcion = 'EFECTIVO'
							   ,Id_Banco  = 0
							   ,Id_Cta_Banco  = 0
							   ,Id_Tarjeta = ''
							   ,Tarjeta_Nro = ''
							   ,Id_Moneda = @pEfe_Moneda
							   ,Cotizacion = @pEfe_Cotiz
							   From #Val 

                Insert Into Valores 
			           Select * from #Val 


				Select Top 1 * into #Val_Mov_Efe From Valores_Mov Where Descripcion like '%efectivo%' order by id_trans desc
 			    SET @Renglon_Nro = ISNULL((Select MAX(Renglon_Nro) From Valores_Mov where id_valor = @Id_Valor_Nuevo ),0)+1

				Update #Val_Mov_Efe Set Id_Trans = @Id_Trans
				               ,Id_Valor = @Id_Valor_Nuevo
				               ,Renglon_nro = @Renglon_Nro
				               ,Id_Estado_Valor = 2
							   ,Id_Periodo_Caja = @pId_Periodo_Caja
							   ,Fecha_Acreditacion = @pFecha_Acreditacion
							   ,Fecha  = @pFecha 
							  From #Val_Mov_Efe V

			    Insert Into Valores_Mov 
			           Select * from #Val_Mov_Efe


                Drop Table #Val 
			    Drop Table #Val_Mov_Efe
        END


    /******** Llamar a Cbtes_Fin *****************/

		SET @JSON_Parametros_Stored_Invocado =	'{' +
													dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('Id_Trans', @Id_Trans, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'INT') + ',' +
													dbo.CF_Json_ParsearVariable('Omitir_Resultado_OK', @pOmitir_Resultado_OK, 'TINYINT') + 
												'}'		
        INSERT INTO @Result_Tabla_Stored_Invocado
		EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Grabar_Numero @JSON_Parametros_Stored_Invocado
		IF ISNULL(@Result_Stored_Invocado,0) <> 0 
		BEGIN
		    IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0   ROLLBACK
			RETURN 9999
		END

		SET @Descripcion_Cbte = (dbo.CF_Cbte_Descrip(@Id_Trans))
		UPDATE Transacciones SET Descripcion = @Descripcion_Cbte WHERE Id_Trans = @Id_Trans
		UPDATE CBTES SET Destinatario = @Destinatario WHERE Id_Trans = @Id_Trans
		UPDATE Cajas_Mov SET Descripcion = @Descripcion_Cbte WHERE Id_Trans = @Id_Trans

		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Genero asientos del cbte'
		END

		SET @JSON_Parametros_Stored_Invocado =	'{' +
														dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'TINYINT') + ',' +
														dbo.CF_Json_ParsearVariable('Id_Trans', @Id_Trans, 'TINYINT') + ',' +
														dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'INT') + ',' +
														dbo.CF_Json_ParsearVariable('RtaMsjStored', @pOmitir_Resultado_OK, 'TINYINT') + ',' +
														dbo.CF_Json_ParsearVariable('FlagRegenerar', 1, 'TINYINT') + 
												'}'				

		INSERT INTO @Result_Tabla_Stored_Invocado											
		EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Ctas_Contables_Generar @JSON_Parametros_Stored_Invocado
		IF ISNULL(@Result_Stored_Invocado,0) <> 0 
		BEGIN
		    IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0   ROLLBACK
			RETURN 9998
		END
	/****************************************************************************/
	
	IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0   COMMIT


	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @Id_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_tipo_cbte', @pId_Tipo_Cbte, 'VARCHAR') +
									'}'
									
		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,@Id_Trans		AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: [CPJ_Cbtes_Depositos_Generar]'
	END	
	IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0   COMMIT
	
END TRY 

BEGIN CATCH  

    EXECUTE usp_GetErrorInfo; 
	IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0   ROLLBACK
	RETURN 9999

END CATCH


RETURN 0

 /*

CPJ_Cbtes_Depositos_Generar '{"ModoDebug":"1","FlagUsarTrans":"1","Id_Peri":"1","T_Cbte":"BDEC","Cta_Banco":"2","Mone":"PES","Cotiz":1,"Fecha":"2026-06-02 14:05:00","F_Acred":"2026-06-02","Observa":"observacion del comprobante","Concep":"467","Valores":[{"Val":"23538"},{"Val":"23502"},{"Val":"23501"}],"Efe":"1500","Total":"653755.59","Flag_F_Acred":"1"}'

 
 
*/
GO


CREATE PROCEDURE CPJ_Cbtes_Fac_Fin @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*
 * LOG VERSIONES:
 * 13/09/2021: Se agrego Log de Versiones
 * 11/06/2026: Se reemplaza la variable @pOmitir_Result_OK por @pOmitir_Resultado_OK
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans		     	TINYINT
DECLARE @pModoDebug			    	TINYINT
DECLARE @pId_Trans				    INT
DECLARE @pObservacion_Incluye_Integ VARCHAR(8000)
DECLARE @pFlag_Tabla_Temp           TINYINT
DECLARE @pFlag_Renumerar			TINYINT
DECLARE @id_Estado_cbte 			TINYINT
DECLARE @pOmitir_Resultado_OK		TINYINT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pObservacion_Incluye_Integ = ISNULL(CONVERT(VARCHAR(8000), dbo.CF_JSON_VALUE(@pJson,'Observacion_Incluye_Integ')), '')
SET @pFlag_Tabla_Temp           = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Tabla_Temp')), 0)
SET @pFlag_Renumerar			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Renumerar')), 1)
SET @pOmitir_Resultado_OK		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Result_OK')), 1)

/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
DECLARE @Result_Stored_Invocado				INT
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Cta_Contable					INT
DECLARE @Fecha								DATETIME
DECLARE @Observacion						VARCHAR(100)
DECLARE @Item								SMALLINT

DECLARE @Descripcion_Cbte					VARCHAR(80)
DECLARE @Porc_Bonificacion_Cb				DECIMAL(5,2)
DECLARE @Imp_Gravado_1						DECIMAL(12,2)
DECLARE @Imp_Gravado_2						DECIMAL(12,2)
DECLARE @Imp_Gravado_3						DECIMAL(12,2)
DECLARE @Imp_Iva_1							DECIMAL(12,2)
DECLARE @Imp_Iva_2							DECIMAL(12,2)
DECLARE @Imp_Iva_3							DECIMAL(12,2)
DECLARE @Imp_Exento							DECIMAL(12,2)
DECLARE @Imp_Total							DECIMAL(12,2)
DECLARE @Saldo								DECIMAL(12,2)
DECLARE @Imp_Bonificacion					DECIMAL(12,2)
DECLARE @Cantidad							DECIMAL(12,4)
DECLARE @Imp_Percep							DECIMAL(12,2)
DECLARE @Compromete_Factura					SMALLINT
DECLARE @Id_Tipo_Cbte						VARCHAR(4)
DECLARE @It_Sum_Iva_1						DECIMAL(12,2)
DECLARE @It_Sum_Iva_2						DECIMAL(12,2)
DECLARE @It_Sum_Iva_3						DECIMAL(12,2)
DECLARE @It_Sum_Iva_Total					DECIMAL(12,2)
DECLARE @It_Sum_Imp_Gravado_1				DECIMAL(12,2)
DECLARE @It_Sum_Imp_Gravado_2				DECIMAL(12,2)
DECLARE @It_Sum_Imp_Gravado_3				DECIMAL(12,2)
DECLARE @It_Sum_Gravado_Total				DECIMAL(12,2)
DECLARE @Tasa_Iva_1							DECIMAL(12,2)
DECLARE @Tasa_Iva_2							DECIMAL(12,2)
DECLARE @Tasa_Iva_3							DECIMAL(12,2)
DECLARE @Cant_Cuotas						SMALLINT
DECLARE @CtaCte_Importe						DECIMAL(12,2)
DECLARE @CtaCte_Saldo						DECIMAL(12,2)
DECLARE @CtaCte_Imp_Total					DECIMAL(12,2)
DECLARE @CtaCte_Suma						DECIMAL(12,2)
DECLARE @CtaCte_Diferencia					DECIMAL(12,2)
DECLARE @Iva_Suma							TINYINT
DECLARE @Id_Cond_Pago						SMALLINT
DECLARE @Id_Moneda                          CHAR(3)    
DECLARE @Id_Cliente                         INT
DECLARE @FechaVence                         DATETIME
DECLARE @Cotizacion                         DECIMAL(12,4)

DECLARE @Result_Tabla_Stored_Invocado TABLE (ErrorNumber	INT,
											ErrorSeverity	INT,
											ErrorState		INT,
											ErrorProcedure  VARCHAR(1000),
											ErrorLine		INT,
											ErrorMessage	VARCHAR(4000))

/*Fin de Declaraciones Variables Locales */

BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Fac_Fin'
		PRINT 'Parametros:'
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + ' Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans)
	END
	
	/*===================================================================*/

	IF(@pId_Trans = 0)
	BEGIN
		SET @rtaErrorStored = 70001 /*Transaccion no abierta*/
		
		SELECT	 @rtaErrorStored	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,''					AS ErrorMessage
			
		IF @pFlagUsarTrans <> 0 
		BEGIN
			ROLLBACK
		END
		
		RETURN 9999
	END
	
	/*===================================================================*/	
		
	SET @JSON_Parametros_Stored_Invocado =	'{' +
											dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'INT') +
											'}'
											
	
	/*===================================================================*/

	SELECT 	@Id_Tipo_Cbte = ISNULL(C.Id_Tipo_Cbte, ''),
			@Cant_Cuotas  = ISNULL(C.Cant_Cuotas, 0),
			@Compromete_Factura = ISNULL(Compromete_Factura, 0),
			@Id_Estado_cbte = ISNULL(T.Id_Estado_cbte,0),
			@Iva_Suma = ISNULL(V.Iva_Suma,0),
			@Id_Cond_Pago = c.Id_cond_Pago,
		    @Id_Moneda  = ISNULL(C.Id_Moneda ,'PES'),
			@Id_Cliente = ISNULL(C.Id_Cliente, 0), 
			@FechaVence = ISNULL(C.Fecha_Venc, C.Fecha) ,
			@Cotizacion = ISNULL(C.Cotizacion, 1) 
			FROM Cbtes C 
						LEFT JOIN Cbtes_Tipos T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
						LEFT JOIN Iva V ON C.Id_Iva = V.Id_Iva
			WHERE c.Id_Trans = @pId_Trans

	IF(@Id_Moneda = '')
	BEGIN
		SET @Id_Moneda = dbo.CF_xParam('Moneda_Nacional')
	END

	IF(@Cotizacion = 0)
	BEGIN
		SET @Cotizacion = 1
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Id_Tipo_Cbte: ' + @Id_Tipo_Cbte + ' @Compromete_Factura: ' + CONVERT(VARCHAR(10), @Compromete_Factura)
	END
	
	-----------------------------------------------------------------------------------------------------------------------------------------

	SET @Descripcion_Cbte = (dbo.CF_Cbte_Descrip(@pId_Trans))
	
	-----------------------------------------------------------------------------------------------------------------------------------------
	
	UPDATE Transacciones SET Descripcion = @Descripcion_Cbte WHERE Id_Trans = @pId_Trans
	
	-----------------------------------------------------------------------------------------------------------------------------------------
	
	UPDATE Cbtes_Items 	SET Id_Estado_Cbte = 1	WHERE Id_Trans = @pId_Trans
	
	-----------------------------------------------------------------------------------------------------------------------------------------

	SET @Tasa_Iva_1	= CONVERT(DECIMAL(12,2), dbo.CF_xParam('Tasa_Iva_1'))
	SET @Tasa_Iva_2	= CONVERT(DECIMAL(12,2), dbo.CF_xParam('Tasa_Iva_2'))
	SET @Tasa_Iva_3	= CONVERT(DECIMAL(12,2), dbo.CF_xParam('Tasa_Iva_3'))

	-----------------------------------------------------------------------------------------------------------------------------------------

	SET @Porc_Bonificacion_Cb	= ISNULL((SELECT ISNULL(Porc_Bonificacion, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans), 0)
	
	-----------------------------------------------------------------------------------------------------------------------------------------
	
	SET @It_Sum_Imp_Gravado_1	= 0
	SET @It_Sum_Imp_Gravado_2	= 0
	SET @It_Sum_Imp_Gravado_3	= 0
	SET @It_Sum_Gravado_Total	= 0

	SET @Imp_Gravado_1			= 0
	SET @Imp_Gravado_2			= 0
	SET @Imp_Gravado_3			= 0

	-----------------------------------------------------------------------------------------------------------------------------------------
	
	SET @It_Sum_Iva_1			= 0
	SET @It_Sum_Iva_2			= 0
	SET @It_Sum_Iva_3			= 0
	SET @It_Sum_Iva_Total		= 0
	
	SET @Imp_Iva_1				= 0
	SET @Imp_Iva_2				= 0
	SET @Imp_Iva_3				= 0

	-----------------------------------------------------------------------------------------------------------------------------------------



	--06/07/2021 Se comenta en @Imp_Gravado_Sum_It la multiplicacion de * ISNULL(Cantidad_Saldo, 0)
	
	IF @pFlag_Tabla_Temp = 0
	BEGIN

		SELECT Porc_Iva,SUM(ISNULL(Imp_Gravado, 0)) AS Imp_Gravado,SUM(ISNULL(Imp_Iva, 0)) AS Imp_Iva,SUM(ISNULL(Imp_Exento,0)) AS Imp_Exento 
			INTO #Porc
			FROM Cbtes_Items WHERE Id_Trans = @pId_Trans GROUP BY Porc_Iva

        SET @Cantidad				= ISNULL((SELECT COUNT(*) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)  
        SET @Imp_Percep				= ISNULL((SELECT SUM(ISNULL(Importe, 0)) FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans), 0)	--21/04/2021 Se agrega

		IF @Iva_Suma = 0   --05/06/2024 SE agregue IF @Iva_Suma = 0 
		BEGIN
			SET @It_Sum_Imp_Gravado_1	= 0
			SET @It_Sum_Imp_Gravado_2	= 0
			SET @It_Sum_Imp_Gravado_3	= 0
			SET @It_Sum_Gravado_Total	= 0

			SET @It_Sum_Iva_1			= 0
			SET @It_Sum_Iva_2			= 0
			SET @It_Sum_Iva_3			= 0
			SET @It_Sum_Iva_Total		= 0

			SET @Imp_Exento	= ISNULL((SELECT SUM((ISNULL(Imp_Gravado, 0) + ISNULL(Imp_Exento, 0))) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans),0)
		END
		ELSE
		BEGIN
			SET @It_Sum_Imp_Gravado_1	= ISNULL((SELECT Imp_Gravado FROM #Porc WHERE Porc_Iva = @Tasa_Iva_1), 0)
			SET @It_Sum_Imp_Gravado_2	= ISNULL((SELECT Imp_Gravado FROM #Porc WHERE Porc_Iva = @Tasa_Iva_2), 0)
			SET @It_Sum_Imp_Gravado_3	= ISNULL((SELECT Imp_Gravado FROM #Porc WHERE Porc_Iva = @Tasa_Iva_3), 0)
			SET @It_Sum_Gravado_Total	= @It_Sum_Imp_Gravado_1 + @It_Sum_Imp_Gravado_2 + @It_Sum_Imp_Gravado_3

			SET @It_Sum_Iva_1			= ISNULL((SELECT Imp_Iva FROM #Porc WHERE Porc_Iva = @Tasa_Iva_1), 0)
			SET @It_Sum_Iva_2			= ISNULL((SELECT Imp_Iva FROM #Porc WHERE Porc_Iva = @Tasa_Iva_2), 0)
			SET @It_Sum_Iva_3			= ISNULL((SELECT Imp_Iva FROM #Porc WHERE Porc_Iva = @Tasa_Iva_3), 0)
			SET @It_Sum_Iva_Total		= @It_Sum_Iva_1 + @It_Sum_Iva_2 + @It_Sum_Iva_3

 			SET @Imp_Exento				= ISNULL((SELECT  SUM(Imp_Exento)	FROM #Porc ), 0)
			SET @Imp_Exento				+= ISNULL((SELECT Imp_Gravado 	FROM #Porc WHERE Porc_Iva = 0), 0)	
		END
	END
    ELSE
	BEGIN

		SELECT Porc_Iva,SUM(ISNULL(Imp_Gravado, 0)) AS Imp_Gravado,SUM(ISNULL(Imp_Iva, 0)) AS Imp_Iva,SUM(ISNULL(Imp_Exento,0)) AS Imp_Exento 
			INTO #Porc2
			FROM #ITEMS_CBTE GROUP BY Porc_Iva

		SET @Cantidad				= ISNULL((SELECT COUNT(*) FROM #ITEMS_CBTE), 0)  
		SET @Imp_Percep				= ISNULL((SELECT SUM(ISNULL(Importe, 0)) FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans), 0)	--21/04/2021 Se agrega

		IF @Iva_Suma = 0   --05/06/2024 SE agregue IF @Iva_Suma = 0 
		BEGIN
			SET @It_Sum_Imp_Gravado_1	= 0
			SET @It_Sum_Imp_Gravado_2	= 0
			SET @It_Sum_Imp_Gravado_3	= 0
			SET @It_Sum_Gravado_Total	= 0

			SET @It_Sum_Iva_1			= 0
			SET @It_Sum_Iva_2			= 0
			SET @It_Sum_Iva_3			= 0
			SET @It_Sum_Iva_Total		= 0

			SET @Imp_Exento				= ISNULL( (SELECT SUM(ISNULL(Imp_Exento, 0) + ISNULL(Imp_Gravado, 0)) FROM #ITEMS_CBTE), 0)
		END
		ELSE
		BEGIN

			SET @It_Sum_Imp_Gravado_1	= ISNULL((SELECT Imp_Gravado FROM #Porc2 WHERE Porc_Iva = @Tasa_Iva_1), 0)
			SET @It_Sum_Imp_Gravado_2	= ISNULL((SELECT Imp_Gravado FROM #Porc2 WHERE Porc_Iva = @Tasa_Iva_2), 0)
			SET @It_Sum_Imp_Gravado_3	= ISNULL((SELECT Imp_Gravado FROM #Porc2 WHERE Porc_Iva = @Tasa_Iva_3), 0)
			SET @It_Sum_Gravado_Total	= @It_Sum_Imp_Gravado_1 + @It_Sum_Imp_Gravado_2 + @It_Sum_Imp_Gravado_3

			SET @It_Sum_Iva_1			= ISNULL((SELECT Imp_Iva FROM #Porc2 WHERE Porc_Iva = @Tasa_Iva_1), 0)
			SET @It_Sum_Iva_2			= ISNULL((SELECT Imp_Iva FROM #Porc2 WHERE Porc_Iva = @Tasa_Iva_2), 0)
			SET @It_Sum_Iva_3			= ISNULL((SELECT Imp_Iva FROM #Porc2 WHERE Porc_Iva = @Tasa_Iva_3), 0)
			SET @It_Sum_Iva_Total		= @It_Sum_Iva_1 + @It_Sum_Iva_2 + @It_Sum_Iva_3

 			SET @Imp_Exento				= ISNULL((SELECT  SUM(Imp_Exento)	FROM #Porc2 ), 0)
			SET @Imp_Exento				+= ISNULL((SELECT Imp_Gravado 	FROM #Porc2 WHERE Porc_Iva = 0), 0)	
		END
	END        	
	
	-----------------------------------------------------------------------------------------------------------------------------------------
	
	IF(@Porc_Bonificacion_Cb = 0)
	BEGIN
		SET @Imp_Gravado_1		= @It_Sum_Imp_Gravado_1
		SET @Imp_Gravado_2		= @It_Sum_Imp_Gravado_2
		SET @Imp_Gravado_3		= @It_Sum_Imp_Gravado_3
	END
	ELSE
	BEGIN
		SET @Imp_Gravado_1		= (@It_Sum_Imp_Gravado_1 * ((100 - @Porc_Bonificacion_Cb) / 100))
		SET @Imp_Gravado_2		= (@It_Sum_Imp_Gravado_2 * ((100 - @Porc_Bonificacion_Cb) / 100))
		SET @Imp_Gravado_3		= (@It_Sum_Imp_Gravado_3 * ((100 - @Porc_Bonificacion_Cb) / 100))
	END

	-----------------------------------------------------------------------------------------------------------------------------------------

	SET @Imp_Iva_1				= @It_Sum_Iva_1
	SET @Imp_Iva_2				= @It_Sum_Iva_2
	SET @Imp_Iva_3				= @It_Sum_Iva_3

	-----------------------------------------------------------------------------------------------------------------------------------------

	SET @Imp_Total				=	(@Imp_Gravado_1 + @Imp_Gravado_2 + @Imp_Gravado_3) + 
									(@Imp_Iva_1 + @Imp_Iva_2 + @Imp_Iva_3) + 
									@Imp_Exento + 
									@Imp_Percep
	
	-----------------------------------------------------------------------------------------------------------------------------------------

	SET @Saldo					= @Imp_Total
	SET @Imp_Bonificacion		= ((@It_Sum_Imp_Gravado_1 + @It_Sum_Imp_Gravado_2 + @It_Sum_Imp_Gravado_3) - (@Imp_Gravado_1 + @Imp_Gravado_2 + @Imp_Gravado_3))		
	
	-----------------------------------------------------------------------------------------------------------------------------------------
	
	IF (@It_Sum_Iva_Total = 0)
	BEGIN
		SET @Imp_Exento = @Imp_Exento + @Imp_Gravado_1 + @Imp_Gravado_2 + @Imp_Gravado_3
		SET @Imp_Gravado_1 = 0
		SET @Imp_Gravado_2 = 0
		SET @Imp_Gravado_3 = 0
	END
	
	-----------------------------------------------------------------------------------------------------------------------------------------
	
	UPDATE Cbtes 
		SET 
		Cantidad			= @Cantidad,
		Imp_Gravado			= @Imp_Gravado_1, 
		Imp_Gravado2		= @Imp_Gravado_2,
		Imp_Gravado3		= @Imp_Gravado_3, 
		Imp_Exento			= @Imp_Exento,
		Saldo				= @Saldo, 
		Imp_Iva				= @Imp_Iva_1,
		Imp_Iva2			= @Imp_Iva_2,
		Imp_Iva3			= @Imp_Iva_3,
		Imp_Bonificacion	= @Imp_Bonificacion,
		Imp_Total			= @Imp_Total,
		Observacion         = @pObservacion_Incluye_Integ,
		Imp_Percep			= @Imp_Percep,
		Id_Estado_Cbte      = @Id_Estado_cbte,
		Id_Moneda           = @Id_Moneda,
		Cotizacion          = @Cotizacion
		WHERE 
		Id_Trans = @pId_Trans

	-----------------------------------------------------------------------------------------------------------------------------------------
	IF @Id_Cond_Pago NOT IN (0, 1)
	BEGIN
	   -- SI TIENE CUOTAS SE DIVIDE POR LA CANTIDAD DE CUOTAS
		IF(@Cant_Cuotas > 0)
		BEGIN
			SET @CtaCte_Importe	= (@Imp_Total * @Compromete_Factura) / @Cant_Cuotas
			SET @CtaCte_Saldo	= (@Saldo * @Compromete_Factura) / @Cant_Cuotas
		END	
		ELSE
		BEGIN
			SET @CtaCte_Importe	= (@Imp_Total * @Compromete_Factura)
			SET @CtaCte_Importe	= (@Saldo * @Compromete_Factura)
		END
		SET @Descripcion_Cbte = dbo.CF_Descrip_Cbte(@pId_Trans)

		IF (Select COUNT(*) from Clientes_CtaCte where Id_Trans = @pId_Trans) = 0
		   BEGIN
				INSERT INTO Clientes_CtaCte 
				(Id_Trans,		Nro_Cuota,		Id_Empresa,
				Id_Cliente,		Fecha,			Fecha_Vence,
				Descripcion,	Importe,		Id_Estado_Cbte,
				Observacion,	Id_Trans_Origen,Nro_Cuota_Origen,
				Id_Moneda,		Saldo,			Nro_FacCre)
				VALUES
				(@pId_Trans,	1,					NULL,
				@Id_Cliente,	@Fecha,			@FechaVence,
				@Descripcion_Cbte,	@CtaCte_Importe, @Id_Estado_Cbte,
				'',				0,					0,
				@Id_Moneda,	@CtaCte_Importe,	0)
	       END
	
	-- SI TIENE CUOTAS SE DIVIDE POR LA CANTIDAD DE CUOTAS

	
		UPDATE Clientes_CtaCte
			SET
				Descripcion		= @Descripcion_Cbte,
				Importe			= @CtaCte_Importe,
				Saldo			= @CtaCte_Saldo
			WHERE
			Id_Trans = @pId_Trans

	-- SI LA SUMA DE TODAS LAS CUOTAS ES DIFERENTE AL TOTAL DEL CBTE SE LE RESTA LA DIFERENCIA A LA PRIMERA CUOTA
		SET @CtaCte_Suma	  = (SELECT SUM(Importe) FROM Clientes_CtaCte WHERE Id_Trans = @pId_Trans)
		SET @CtaCte_Imp_Total = @Imp_Total * @Compromete_Factura

		IF (@CtaCte_Imp_Total <> @CtaCte_Suma)
		BEGIN
			SET @CtaCte_Diferencia = @CtaCte_Suma - @CtaCte_Imp_Total
			UPDATE Clientes_CtaCte 
			SET 
			Importe = (Importe - @CtaCte_Diferencia),
			Saldo = (Saldo - @CtaCte_Diferencia) 
			WHERE Id_Trans = @pId_Trans 
			AND Nro_Cuota = 1
		END
    END
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'SE PROCESO Clientes_CtaCte'
	END	
	-----------------------------------------------------------------------------------------------------------------------------------------
	If dbo.CF_xParam('Lote:Asi_Generar') = 1
	   BEGIN
			SET @JSON_Parametros_Stored_Invocado =	'{' +
													dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'INT') + ',' +
													dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'INT') + ',' +
													dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'INT') + ',' +
													dbo.CF_Json_ParsearVariable('Omitir_Resultado_OK', @pOmitir_Resultado_OK, 'INT') + ',' +
													dbo.CF_Json_ParsearVariable('FlagRegenerar', 1, 'TINYINT') + 
													'}'		
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'ejecuto dbo.CPJ_Cbtes_Ctas_Contables_Generar'
				PRINT @JSON_Parametros_Stored_Invocado
			END	
						
			EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Ctas_Contables_Generar @JSON_Parametros_Stored_Invocado
			IF ISNULL(@Result_Stored_Invocado,0) <> 0 
			BEGIN

				IF(@pModoDebug = 1)
				BEGIN
					PRINT 'Error: CPJ_Cbtes_Ctas_Contables_Generar: ' + CONVERT(VARCHAR(100),@Result_Stored_Invocado)
				END

				RETURN 99991
			END		
        END

	-----------------------------------------------------------------------------------------------------------------------------------------

	IF(@pFlag_Renumerar = 1)
	BEGIN

		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'ejecuto dbo.CPJ_Cbtes_Grabar_Numero'
			PRINT @JSON_Parametros_Stored_Invocado
		END	
						
		EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Grabar_Numero @JSON_Parametros_Stored_Invocado
		IF ISNULL(@Result_Stored_Invocado,0) <> 0 
		BEGIN

			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Error: CPJ_Cbtes_Grabar_Numero: ' + CONVERT(VARCHAR(100),@Result_Stored_Invocado)
			END

			RETURN 99992
		END	

		SET @Descripcion_Cbte = (dbo.CF_Cbte_Descrip(@pId_Trans))
		UPDATE Transacciones SET Descripcion = @Descripcion_Cbte WHERE Id_Trans = @pId_Trans
		UPDATE Clientes_CtaCte SET Descripcion = @Descripcion_Cbte WHERE Id_Trans = @pId_Trans
	END

	-----------------------------------------------------------------------------------------------------------------------------------------

	-- 17/11/2020 Se agrega que si el saldo es 0 en cta cte tiene que poner el estado en completo
	-- 26/11/2025 Si la condici├│n de pago es contado marco la factura como completa
	IF(@Saldo = 0 OR @Id_Cond_Pago = 1)
	BEGIN
		UPDATE Clientes_CtaCte
		SET
		Id_Estado_Cbte = 2 --Completo
		WHERE
		Id_Trans = @pId_Trans
	END

	-----------------------------------------------------------------------------------------------------------------------------------------
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	-----------------------------------------------------------------------------------------------------------------------------------------

	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT') + ',' +
								dbo.CF_Json_ParsearVariable('descrip_Cbte', @Descripcion_Cbte, 'VARCHAR') +
								'}'
    IF @pOmitir_Resultado_OK = 0
	BEGIN
		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Fac_Fin'
	END

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 99993
END CATCH

RETURN 0 

--EXEC dbo.CPJ_Cbtes_Fac_Fin '{"FlagUsarTrans":"0","ModoDebug":"1","Id_Trans":"11101150","Flag_Renumerar":"1"}'
GO

CREATE PROCEDURE [dbo].[CPJ_Cbtes_Fac_Generar] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON

/*
 * LOG VERSIONES:
 * 13/09/2021: Se agrego Log de Versiones
 * 13/04/2022: Se agrego parametro Flag_LoteUnico
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans		TINYINT
DECLARE @pModoDebug			TINYINT
DECLARE @pId_Usuario		SMALLINT
DECLARE @pId_Trans			INT
DECLARE @pLote				VARCHAR(25)
DECLARE @pFecha				DATETIME
DECLARE @pFechaVence		DATETIME
DECLARE @pId_Cliente		INT
DECLARE @pId_Tipo_Cbte		CHAR(4)
DECLARE @pId_Cond_Pago		SMALLINT
DECLARE @pId_Moneda			CHAR(3)
DECLARE @pCotizacion		DECIMAL(12,4)
DECLARE @pId_Contrato		INT
DECLARE @pNro_Auto_Trib		VARCHAR(14)
DECLARE @pCai_Vence			DATETIME
DECLARE @Bonif_Contrato     DECIMAL(5,2)
DECLARE @pId_Periodo_Caja	INT							--03/02/2021 Agregado
DECLARE @pImporte			DECIMAL(16,2)				--03/02/2021 Agregado
DECLARE @pId_Cobrador		VARCHAR(10)					--04/02/2021 Agregado
DECLARE @pCbte_Nro_Externo	VARCHAR(25)					--30/06/2021 Agregado
DECLARE @pPedido_Nro		VARCHAR(25)					--07/07/2021 Agregado
DECLARE @pId_Lista_Precio	SMALLINT					--06/08/2021 Agregado
DECLARE @pFlag_LoteUnico	TINYINT						--12/04/2022 Agregado
DECLARE @pOmitir_Resultado_OK   TINYINT
DECLARE @pId_Tarjeta		VARCHAR(10)
DECLARE @pTar_Nro			VARCHAR(50)


SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Usuario			= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), -1)
SET @pId_Trans				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pLote					= ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Lote')), '')
SET @pFecha					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')),'19000101')
SET @pFechaVence			= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'FechaVence'))
SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Tipo_Cbte			= ISNULL(CONVERT(CHAR(4), dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Cbte')), '')
SET @pId_Cond_Pago			= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Cond_Pago')), '')
SET @pId_Moneda				= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Id_Moneda')), 'PES')
SET @pCotizacion			= ISNULL(CONVERT(DECIMAL(12,4), dbo.CF_JSON_VALUE(@pJson,'Cotizacion')), 1)
SET @Bonif_Contrato			= ISNULL(CONVERT(DECIMAL(5,2), dbo.CF_JSON_VALUE(@pJson,'Bonif_Contrato')), 0)
SET @pId_Contrato			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Contrato')), 0)
SET @pNro_Auto_Trib			= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Nro_Auto_Trib')), '')
SET @pCai_Vence				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Cai_Vence')), '19000101')
SET @pId_Periodo_Caja		= ISNULL(CONVERT(INT,dbo.CF_JSON_VALUE(@pJson,'Id_Periodo_Caja')),0)
SET @pImporte				= ISNULL(CONVERT(DECIMAL(15,2), dbo.CF_JSON_VALUE(@pJson,'Importe')), 0)
SET @pId_Cobrador			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Cobrador')), '')
SET @pCbte_Nro_Externo		= ISNULL(CONVERT(VARCHAR(25), dbo.CF_JSON_VALUE(@pJson,'Cbte_Nro_Externo')), '')
SET @pPedido_Nro			= ISNULL(CONVERT(VARCHAR(25), dbo.CF_JSON_VALUE(@pJson,'Pedido_Nro')), '')
SET @pId_Lista_Precio		= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Lista_Precio')), 0)
SET @pFlag_LoteUnico		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_LoteUnico')), 0)
SET @pOmitir_Resultado_Ok	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Resultado_OK')), 0)
SET @pId_Tarjeta			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Tarjeta')), '')
SET @pTar_Nro				= ISNULL(CONVERT(VARCHAR(50), dbo.CF_JSON_VALUE(@pJson,'Tar_Nro')), '')
/*FIN Variables recibidas por parametro a traves del JSON*/


/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Empresa			SMALLINT
DECLARE @Id_Sucursal		SMALLINT
DECLARE @Cbte_Grupo			INT
DECLARE @Comprobante_Nro	INT
DECLARE @Id_Taller			VARCHAR(10)
DECLARE @Id_Proceso			VARCHAR(10)
DECLARE @Id_Proveedor		INT
DECLARE @Signo				SMALLINT
DECLARE @Id_Estado_Cbte		SMALLINT
DECLARE @Id_Dep_Fisico		CHAR(3)
DECLARE @Id_Dep_Logico		CHAR(3)
DECLARE @Porc_DescEspecial	DECIMAL(5, 2)
DECLARE @Porc_DescFin		DECIMAL(5, 2)
DECLARE @Porc_Iva			DECIMAL(5, 2)
DECLARE @Porc_Iva2			DECIMAL(5, 2)
DECLARE @Imp_Neto			DECIMAL(12, 2)
DECLARE @Imp_DescEspecial	DECIMAL(12, 2)
DECLARE @Imp_DescFin		DECIMAL(12, 2)
DECLARE @Imp_Bonificacion	DECIMAL(12, 2)
DECLARE @Imp_Gravado		DECIMAL(12, 2)
DECLARE @Imp_Exento			DECIMAL(12, 2)
DECLARE @Imp_IVA			DECIMAL(12, 2)
DECLARE @Imp_IVA2			DECIMAL(12, 2)
DECLARE @Imp_Percepcion_IB	DECIMAL(12, 2)
DECLARE @Imp_Percepcion_Iva DECIMAL(12, 2)
DECLARE @Imp_Total			DECIMAL(12, 2)
DECLARE @Bultos				SMALLINT
DECLARE @NroImpresion		INT
DECLARE @Exportado			TINYINT
DECLARE @Dir_Entrega		VARCHAR(255)
DECLARE @Id_Pais			CHAR(3)
DECLARE @Id_Provincia		CHAR(3)
DECLARE @Id_Localidad		INT
DECLARE @Porc_Iva3			DECIMAL(5, 2)
DECLARE @Imp_Gravado2		DECIMAL(12, 2)
DECLARE @Imp_Gravado3		DECIMAL(12, 2)
DECLARE @Imp_NoGravado		DECIMAL(12, 2)
DECLARE @Imp_IVA3			DECIMAL(12, 2)
DECLARE @Imp_Percep			DECIMAL(12, 2)
DECLARE @Saldo				DECIMAL(12, 2)
DECLARE @Periodo_Iva		DATETIME
DECLARE @Periodo			DATETIME
DECLARE @Id_Cond_Pago_Item	TINYINT
DECLARE @Id_Tipo_Reten		VARCHAR(10)
DECLARE @Cant_Cuotas		SMALLINT
DECLARE @Id_Producto		VARCHAR(14)
DECLARE @Id_Formula			VARCHAR(15)
DECLARE @Cantidad			DECIMAL(12, 4)
DECLARE @Id_Transportista	INT
DECLARE @Destinatario		VARCHAR(100)
DECLARE @Cuit				VARCHAR(19)
DECLARE @Doc_Nro			BIGINT
DECLARE @Id_Iva				CHAR(3)
DECLARE @Cant_Batch			SMALLINT
DECLARE @Fecha_Perm_Embar	DATETIME
DECLARE @Saldo_Iva_Recup	DECIMAL(12, 2)
DECLARE @Suc_Destina		SMALLINT
DECLARE @Id_Asiento			INT
DECLARE @Id_Valor			INT
DECLARE @Cai				DECIMAL(14, 0)
DECLARE @Des_Anio			TINYINT
DECLARE @Des_Aduana			CHAR(3)
DECLARE @Des_Destina		CHAR(4)
DECLARE @Des_Nro			INT
DECLARE @Des_Verif			CHAR(1)
DECLARE @Id_Cobrador		VARCHAR(10)
DECLARE @Remito_Nro			VARCHAR(25)
DECLARE @Pedido_Nro			VARCHAR(25)
DECLARE @Cantidad_Saldo		DECIMAL(12, 4)
DECLARE @Saldo_Anterior		DECIMAL(12, 2)
DECLARE @NRO_DJAI			VARCHAR(30)
DECLARE @Cantidad_Equiv		DECIMAL(12, 4)
DECLARE @Id_Trans_Origen	INT
DECLARE @Id_Sede_Origen		SMALLINT
DECLARE @Email				VARCHAR(8000)
DECLARE @Patente_Transporte VARCHAR(7)
DECLARE @Patente_Transporte_Acoplado VARCHAR(7)
DECLARE @Plazo_Venc			SMALLINT
DECLARE @Porc_Bonificacion	DECIMAL(5,2)
DECLARE @Fecha_Estimada		DATETIME
DECLARE @Persona_Recibe		VARCHAR(100)
DECLARE @Observacion		VARCHAR(8000)
DECLARE @Id_Lista			SMALLINT
DECLARE @Id_Lista_Contrato	SMALLINT
DECLARE @Id_Vendedor		VARCHAR(10)
DECLARE @Nro_Perm_Embarque	VARCHAR(20)
DECLARE @Id_Puerto			CHAR(3)
DECLARE @Id_Cond_Vta		CHAR(10)
DECLARE @Cbte_Nro_Externo	VARCHAR(25)
DECLARE @Nota_Part1			VARCHAR(100)
DECLARE @Nota_Part2			VARCHAR(100)
DECLARE @Id_Centro_Costo	CHAR(10)
DECLARE @Id_Camp			SMALLINT
DECLARE @Flag_Lote			TINYINT
DECLARE @Compromete_Factura SMALLINT
DECLARE @Descrip_Cbte		VARCHAR(100)
DECLARE @Importe			DECIMAL(12, 2)
DECLARE @Importe_Con_Signo	DECIMAL(12, 2)
DECLARE @Id_Cliente_Ref		INT
DECLARE @Renglon_Nro		SMALLINT
DECLARE @Id_Estado_Mov_Caja	INT
DECLARE @Descripcion		VARCHAR(100)
DECLARE @Id_Tipo_Mov_Caja	SMALLINT
DECLARE @Id_Concepto		INT
DECLARE @Item				SMALLINT
DECLARE @Id_Estado_Concepto	SMALLINT
DECLARE @Flag_Existe_Cbte_Lote TINYINT
/*Fin de Declaraciones Variables Locales */



BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Fac_Generar'
		PRINT 'Parametros:'
		PRINT 'pFlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans)  + '. pId_Usuario: ' + CONVERT(VARCHAR(10), @pId_Usuario) + '. pLote: ' + @pLote + '. pFecha: ' + CONVERT(VARCHAR(10), @pFecha, 103) + '. pFechaVence: ' + CONVERT(VARCHAR(10), @pFechaVence, 103) +  '. pId_Cliente: ' + CONVERT(VARCHAR(10), @pId_Cliente) + '. pId_Tipo_Cbte: ' + @pId_Tipo_Cbte + '. pId_Cond_Pago: ' + CONVERT(VARCHAR(10), @pId_Cond_Pago) + '. pId_Moneda: ' + @pId_Moneda + '. pCotizacion: ' + CONVERT(VARCHAR(10), @pCotizacion)
		PRINT 'pId_Contrato: ' + CONVERT(VARCHAR(10), @pId_Contrato)  + '. pNro_Auto_Trib: ' + @pNro_Auto_Trib + '. @pCai_Vence: ' + CONVERT(VARCHAR(10), @pCai_Vence, 103) + '. pId_Periodo_Caja: ' + CONVERT(VARCHAR(10), @pId_Periodo_Caja) + '. pImporte: ' + CONVERT(VARCHAR(10), @pImporte)
	END
	
	/*===================================================================================================================================================================*/

	--13/04/2022 Se agrega la utilizacion del parametro @pFlag_LoteUnico para poder validar que si ya se ingreso un pago WEB (Lote tipo P00XXXXXX) sea unico
	IF(@pFlag_LoteUnico = 1)
	BEGIN
		SET @Flag_Existe_Cbte_Lote = ISNULL((SELECT TOP 1 1
											FROM Cbtes CB, Cbtes_Tipos CT
											WHERE
											CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
											AND CT.Compromete_Factura IN (1, -1)
											AND CB.Lote = @pLote)
											, 0) 
		IF(@pModoDebug = 1)
		BEGIN
			PRINT '@Flag_Existe_Cbte_Lote: ' + CONVERT(VARCHAR(10), @Flag_Existe_Cbte_Lote)
		END

		IF(@Flag_Existe_Cbte_Lote = 1)
		BEGIN
			SET @pId_Trans		= 0

				IF @pOmitir_Resultado_Ok = 0
				BEGIN
					SET @rtaMsjStored	=	'{' +
											dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
											dbo.CF_Json_ParsearVariable('id_cliente', 0, 'INT')  + ',' +
											dbo.CF_Json_ParsearVariable('id_tipo_cbte', '', 'VARCHAR') +
											'}'
										
					SELECT	 0				AS ErrorNumber 
							,0				AS ErrorSeverity  
							,0				AS ErrorState 
							,0				AS ErrorProcedure  
							,@pId_Trans		AS ErrorLine		
							,@rtaMsjStored	AS ErrorMessage
				END
		END
	END

	/*===================================================================================================================================================================*/


	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Inserta en Transacciones.'
	END
	
	IF(@pId_Trans = 0)
	BEGIN
		SET @pId_Trans		= ISNULL((SELECT MAX(Id_Trans) FROM Transacciones), 0) + 1
		INSERT INTO Transacciones 
		(Id_Trans,		Descripcion,						Fecha_Mov,
		Id_Usuario) 
		VALUES
		(@pId_Trans,	'Apertura CPJ_Transacciones_Abrir', GETDATE(), 
		@pId_Usuario)
	END


	/*===================================================================*/


	IF(@pId_Cliente = 0)  RAISERROR ('Id_Cliente can not be zero.', 16,  1 ) 
	IF(@pId_Tipo_Cbte = '') RAISERROR ('Id_Tipo_Cbte can not be blank.', 16,  1 ) 

		
	/*===================================================================*/
	
	IF(@pId_Usuario = 0)
	BEGIN
		SET @pId_Usuario = -1
	END
	
	IF(@pId_Moneda = '')
	BEGIN
		SET @pId_Moneda = dbo.CF_xParam('Moneda_Nacional')
	END

	IF(@pCotizacion = 0)
	BEGIN
		SET @pCotizacion = 1
	END
	
	IF(@pLote <> '')
	BEGIN
		SET @Flag_Lote	= 1
	END
	ELSE
	BEGIN
		SET @Flag_Lote	= 0
	END
	
	/*===================================================================*/

	SET @pFecha				= (SELECT CONVERT(DATE, @pFecha))
    SET @Id_Estado_Cbte		= 0  --siempre comienza en carga

	/*===================================================================*/

	SELECT  @Id_Sucursal		= ISNULL(Id_Sucursal, 0),
			@Cbte_Grupo			= ISNULL(Cbte_Grupo, 0),
			@Compromete_Factura = ISNULL(Compromete_Factura, 0)
	FROM Cbtes_Tipos 
	WHERE 
	Id_Tipo_Cbte = @pId_Tipo_Cbte
	
	/*===================================================================*/

	SELECT 	@Destinatario	= ISNULL(Razon_Social, Apellido + ', ' + Nombre),
			@Id_Pais		= ISNULL(Id_Pais_Cob, ''),
			@Id_Provincia	= ISNULL(Id_Provincia_Cob, ''),
			@Id_Localidad	= ISNULL(Id_Localidad_Cob, 0),
			@Cuit			= ISNULL(Cuit, ''),
			@Doc_Nro		= ISNULL(Doc_Nro, 0),
			@Id_Iva			= ISNULL(Id_Iva, ''),
			@Id_Dep_Fisico	= ISNULL(Id_Dep_Fisico, ''),
			@Id_Dep_Logico	= ISNULL(Id_Dep_Logico, ''),
			@Email			= ISNULL(Email, ''),
			@Id_Lista		= ISNULL(Id_Lista_Precio, 0),
			@Porc_Bonificacion = ISNULL(Bonif, 0),
			@Id_Cliente_Ref	= ISNULL(Id_Cliente_Ref, 0),
			@Id_Concepto	= ISNULL(Id_Concepto, 0)
	FROM Clientes
	WHERE
	Id_Cliente = @pId_Cliente

	--25/01/2021 Agregado 
	IF(@Id_Localidad = 0)
	BEGIN
		SET @Id_Provincia = ''
		SET @Id_Pais = ''
	END
	--FIN 25/01/2021 Agregado 
	
	--04/05/2021	Agregado
	IF ((@Cuit = '' OR @Cuit = '0') AND @Doc_Nro > 0)
	BEGIN
		SET @Cuit = CONVERT(VARCHAR(19), @Doc_Nro)
	END
	--FIN 04/05/2021	Agregado

	/*===================================================================*/
	
	IF @pId_Contrato <> 0
	BEGIN
		SELECT 
		@Id_Lista_Contrato = ISNULL(Id_Lista_Precio, 0) 
		FROM Contratos 
		WHERE 
		Id_Contrato = @pId_Contrato

		IF @Id_Lista_Contrato <> 0
		BEGIN
			SET @Id_Lista = @Id_Lista_Contrato
		END
	END

	IF @Bonif_Contrato <> 0
	BEGIN
	   SET @Porc_Bonificacion = @Bonif_Contrato
	END

	/*===================================================================*/
	--06/08/2021 Se agrega que si recibe una lista de precios por parametro tenga prioridad por sobre todo
	
	IF (@pId_Lista_Precio <> 0)
	BEGIN
		SET @Id_Lista = @pId_Lista_Precio
	END
	
	/*===================================================================*/
	SET @Comprobante_Nro	= 0 /*En Carga*/
	SET @Importe			= 0 /*En Carga*/
	SET @Importe_Con_Signo	= @Importe * @Compromete_Factura
	SET @Plazo_Venc			= ISNULL((SELECT ISNULL(Plazo_Venc, 0) FROM Cbtes_Cond_Pago WHERE Id_Cond_Pago = @pId_Cond_Pago), 0)
	SET @Periodo_Iva		= @pFecha
	SET @Periodo			= @pFecha
	SET @Imp_Total			= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Saldo				= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Gravado		= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Neto			= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Exento			= 0 /*Hay que actualizarlo luego de grabar los items*/
		
	/*TO-DO: De aca para abajo por ahora por Default*/
	SET @Id_Taller			= ''
	SET @Id_Proceso			= ''
	SET @Id_Proveedor		= 0
	SET @Signo				= 0
	SET	@Porc_DescFin		= 0
	SET @Porc_DescEspecial	= 0
	SET @Porc_Iva			= dbo.CF_xParam('Tasa_Iva_1')
	SET @Porc_Iva2			= dbo.CF_xParam('Tasa_Iva_2')
	SET @Imp_DescEspecial	= 0
	SET @Imp_DescFin		= 0
	SET @Imp_Bonificacion	= 0
	SET @Imp_Iva			= 0
	SET @Imp_Iva2			= 0
	SET @Imp_Percepcion_IB	= 0
	SET @Imp_Percepcion_Iva = 0
	SET @Bultos				= 0
	SET @NroImpresion		= 0
	SET @Exportado			= 0
	SET @Dir_Entrega		= ''
	SET @Porc_Iva3			= dbo.CF_xParam('Tasa_Iva_3')
	SET @Imp_Gravado2		= 0
	SET @Imp_Gravado3		= 0
	SET @Imp_NoGravado		= 0
	SET @Imp_IVA3			= 0
	SET @Imp_Percep			= 0
	SET @Id_Cond_Pago_Item	= 0
	SET @Id_Tipo_Reten		= ''
	SET @Cant_Cuotas		= 1
	SET @Id_Producto		= NULL
	SET @Id_Formula			= NULL
	SET @Cantidad			= 0
	SET @Id_Transportista	= 0
	SET @Cant_Batch			= 0
	SET @Fecha_Perm_Embar	= NULL
	SET @Saldo_Iva_Recup	= 0
	SET @Suc_Destina		= 0
	SET @Id_Asiento			= 0
	SET @Id_Valor			= 0
	SET @Cai				= 0	
	SET @Des_Anio			= 0
	SET @Des_Aduana			= ''
	SET @Des_Destina		= ''
	SET @Des_Nro			= 0
	SET @Des_Verif			= ''
	
	IF(@pId_Cobrador <> '')
	BEGIN
		SET @Id_Cobrador		= @pId_Cobrador
	END
	ELSE
	BEGIN
		SET @Id_Cobrador		= (SELECT ISNULL(Id_Cobrador, '') FROM Clientes WHERE Id_Cliente = @pId_Cliente)
	END

	SET @Remito_Nro			= ''
	SET @Pedido_Nro			= @pPedido_Nro
	SET @Cantidad_Saldo		= 0
	SET @Saldo_Anterior		= 0
	SET @NRO_DJAI			= ''
	SET @Cantidad_Equiv		= 0
	SET @Id_Trans_Origen	= 0
	SET @Id_Sede_Origen		= 0
	SET @Patente_Transporte = ''
	SET @Patente_Transporte_Acoplado = ''
	SET @Porc_Bonificacion	= 0
	SET @Fecha_Estimada		= NULL
	SET @Persona_Recibe		= ''
	SET @Observacion		= ''
	SET @Id_Vendedor		= ''
	SET @Nro_Perm_Embarque	= ''
	SET @Id_Puerto			= ''
	SET @Id_Cond_Vta		= ''
	SET @Cbte_Nro_Externo	= @pCbte_Nro_Externo
	SET @Nota_Part1			= ''
	SET @Nota_Part2			= ''
	SET @Id_Centro_Costo	= ''
	SET @Id_Camp			= 0

	
	INSERT INTO Cbtes
	(Id_Trans,			Id_Empresa,			Id_Sucursal,
	Id_Tipo_Cbte,		Cbte_Grupo,			Comprobante_Nro,
	Id_Cliente,			Id_Taller,			Id_Proceso,
	Id_Proveedor,		Signo,				Id_Estado_Cbte,
	Fecha,				Id_Dep_Fisico,		Id_Dep_Logico,
	Porc_DescEspecial,	Porc_DescFin,		Porc_Bonificacion,
	Porc_Iva,			Porc_Iva2,			Imp_Neto,
	Imp_DescEspecial,	Imp_DescFin,		Imp_Bonificacion,
	Imp_Gravado,		Imp_Exento,			Imp_IVA,
	Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
	Imp_Total,			Bultos,				NroImpresion,
	Exportado,			Id_Usuario,			Fecha_Estimada,
	Dir_Entrega,		Id_Pais,			Id_Provincia,
	Id_Localidad,		Persona_Recibe,		Porc_Iva3,
	Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
	Imp_IVA3,			Imp_Percep,			Saldo,
	Periodo_Iva,		Periodo,			Fecha_Venc,
	Observacion,		Id_Cond_Pago_Item,	Id_Cond_Pago,
	Id_Tipo_Reten,		Cant_Cuotas,		Id_Producto,
	Id_Formula,			Cantidad,			Id_Vendedor,
	Id_Transportista,	Id_Lista,			Id_Moneda,
	Cotizacion,			Destinatario,		Cuit,
	Id_Iva,				Cant_Batch,			Nro_Perm_Embarque,
	Fecha_Perm_Embar,	Saldo_Iva_Recup,	Lote,
	Suc_Destina,		Id_Puerto,			Id_Cond_Vta,
	Cbte_Nro_Externo,	Nota_Part1,			Nota_Part2,
	Id_Asiento,			Id_Centro_Costo,	Id_Valor,
	Cai,				Cai_Vence,			Des_Anio,
	Des_Aduana,			Des_Destina,		Des_Nro,
	Des_Verif,			Id_Contrato,		Id_Cobrador,
	Nro_Auto_Trib,		Id_Camp,			Remito_Nro,
	Pedido_Nro,			Id_Tarjeta,			Tarjeta_Nro,
	Cantidad_Saldo,		Saldo_Anterior,		NRO_DJAI,
	Cantidad_Equiv,		Id_Trans_Origen,	Id_Sede_Origen,
	Email,				Patente_Transporte,	Patente_Transporte_Acoplado,
	Flag_Lote,			Id_Cliente_Ref)
	VALUES
	(@pId_Trans,		@Id_Empresa,		@Id_Sucursal,
	@pId_Tipo_Cbte,		@Cbte_Grupo,		@Comprobante_Nro,
	@pId_Cliente,		@Id_Taller,			@Id_Proceso,
	@Id_Proveedor,		@Signo,				@Id_Estado_Cbte,
	@pFecha,			@Id_Dep_Fisico,		@Id_Dep_Logico,
	@Porc_DescEspecial,	@Porc_DescFin,		@Porc_Bonificacion,
	@Porc_Iva,			@Porc_Iva2,			@Imp_Neto,
	@Imp_DescEspecial,	@Imp_DescFin,		@Imp_Bonificacion,
	@Imp_Gravado,		@Imp_Exento,		@Imp_IVA,
	@Imp_IVA2,			@Imp_Percepcion_IB,	@Imp_Percepcion_Iva,
	@Imp_Total,			@Bultos,			@NroImpresion,
	@Exportado,			@pId_Usuario,		@Fecha_Estimada,
	@Dir_Entrega,		@Id_Pais,			@Id_Provincia,
	@Id_Localidad,		@Persona_Recibe,	@Porc_Iva3,
	@Imp_Gravado2,		@Imp_Gravado3,		@Imp_NoGravado,
	@Imp_IVA3,			@Imp_Percep,		@Saldo,
	@Periodo_Iva,		@Periodo,			@pFechaVence,
	@Observacion,		@Id_Cond_Pago_Item,	@pId_Cond_Pago,
	@Id_Tipo_Reten,		@Cant_Cuotas,		@Id_Producto,
	@Id_Formula,		@Cantidad,			@Id_Vendedor,
	@Id_Transportista,	@Id_Lista,			@pId_Moneda,
	@pCotizacion,		@Destinatario,		@Cuit,
	@Id_Iva,			@Cant_Batch,		@Nro_Perm_Embarque,
	@Fecha_Perm_Embar,	@Saldo_Iva_Recup,	@pLote,
	@Suc_Destina,		@Id_Puerto,			@Id_Cond_Vta,
	@Cbte_Nro_Externo,	@Nota_Part1,		@Nota_Part2,
	@Id_Asiento,		@Id_Centro_Costo,	@Id_Valor,
	@Cai,				@pCai_Vence,		@Des_Anio,
	@Des_Aduana,		@Des_Destina,		@Des_Nro,
	@Des_Verif,			@pId_Contrato,		@Id_Cobrador,
	@pNro_Auto_Trib,	@Id_Camp,			@Remito_Nro,
	@Pedido_Nro,		@pId_Tarjeta,		@pTar_Nro,
	@Cantidad_Saldo,	@Saldo_Anterior,	@Nro_DJAI,
	@Cantidad_Equiv,	@Id_Trans_Origen,	@Id_Sede_Origen,
	@Email,				@Patente_Transporte,@Patente_Transporte_Acoplado,
	@Flag_Lote,			@Id_Cliente_Ref)

	/*===================================================================*/
	
	IF @pId_Cond_Pago NOT IN (0, 1)
	BEGIN
		SET @Descrip_Cbte = dbo.CF_Descrip_Cbte(@pId_Trans)
		
		INSERT INTO Clientes_CtaCte 
		(Id_Trans,		Nro_Cuota,		Id_Empresa,
		Id_Cliente,		Fecha,			Fecha_Vence,
		Descripcion,	Importe,		Id_Estado_Cbte,
		Observacion,	Id_Trans_Origen,Nro_Cuota_Origen,
		Id_Moneda,		Saldo,			Nro_FacCre)
		VALUES
		(@pId_Trans,	1,					NULL,
		@pId_Cliente,	@pFecha,			@pFechaVence,
		@Descrip_Cbte,	@Importe_Con_Signo, @Id_Estado_Cbte,
		'',				0,					0,
		@pId_Moneda,	@Importe_Con_Signo,	0)
	END 
	
	/*===================================================================*/

	IF(@pId_Cond_Pago = 1/*Contado*/)
	BEGIN
		SET @Renglon_Nro = 1
		SET @Id_Estado_Mov_Caja = 0 --EN CARGA
		SET @Descripcion = ISNULL((dbo.CF_Cbte_Descrip(@pId_Trans)), '')
		SET @Id_Tipo_Mov_Caja = 1 --e_Ing_Varios

		INSERT INTO dbo.Cajas_Mov
		(Id_Trans,			Renglon_Nro,	Id_Estado_Mov_Caja,
		Importe,			Descripcion,	Id_Periodo_Caja,
		Id_Tipo_Mov_Caja,	Fecha)
		VALUES
		(@pId_Trans,		@Renglon_Nro,	@Id_Estado_Mov_Caja,
		@pImporte,			@Descripcion,	@pId_Periodo_Caja,
		@Id_Tipo_Mov_Caja,	GETDATE()/*Es con hora*/)
	END

	/*****************************************************************************/

	IF(@pId_Cond_Pago = 1/*Contado*/)
	BEGIN
		SET @Item = 1
		SET @Id_Estado_Concepto = 0
	
		INSERT INTO dbo.Cajas_Mov_Conceptos
		(Id_Trans,				Id_Concepto,			Item,
		Id_Estado_Concepto,		Importe,				Id_Periodo_Caja)
		VALUES
		(@pId_Trans,			@Id_Concepto,			@Item,
		@Id_Estado_Concepto,	@pImporte * (-1),		@pId_Periodo_Caja)
	END	

	/*===================================================================*/
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	
	
	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_cliente', @pId_Cliente, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_tipo_cbte', @pId_Tipo_Cbte, 'VARCHAR') +
									'}'
										
		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,@pId_Trans		AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Fac_Generar'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO

CREATE PROCEDURE [dbo].[CPJ_Cbtes_Fac_Generar_Item]		@pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

 
/*
 * LOG VERSIONES:
 * 13/09/2021: Se agrego Log de Versiones
 * 10/06/2022: Se cambia que Costo_MO siempre lo tome de la tabla de Productos y omita @pCosto_MO por pedido de Victor
 * 04/04/2024: se agrego la validacion de item facturado, cuando se factura directo desde clarion por fact.contratos
 * 04/03/2026: se agrego el parametro de observacion para pisar el que carga por defecto
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans								TINYINT
DECLARE @pModoDebug									TINYINT
DECLARE @pId_Trans									INT
DECLARE @pId_Producto								VARCHAR(14)
DECLARE @pCantidad									DECIMAL(15,5)
DECLARE @pFecha_QA									DATETIME
DECLARE @pFecha_Venc								DATETIME
DECLARE @pId_Cliente								INT
DECLARE @pId_Contrato								INT
DECLARE @pBonif										DECIMAL(5,2)
DECLARE @pPrecio_Grav								DECIMAL(15,5)
DECLARE @pPrecio_Exen								DECIMAL(15,5)
DECLARE @pId_Tiempo									CHAR(3)
DECLARE @pRefacturar								TINYINT
DECLARE @pFlag_Tabla_Temp							TINYINT
DECLARE @pLote										VARCHAR(20)
DECLARE @pFecha_Entrega								DATETIME
DECLARE @pCosto_GF									DECIMAL(15,5)
DECLARE @pCosto_MO									DECIMAL(15,5)
DECLARE @pRedondeo_Imp_Final						TINYINT
DECLARE @pCantidad_Equiv							DECIMAL(15,5)
DECLARE @pOmitir_Resultado_OK						TINYINT	
DECLARE @pFlag_Verif_Prod_Fact_x_Contrato			TINYINT	 -- 31/8
DECLARE @pObservacion								VARCHAR(255) -- 20260304s. Se agregó para pisar el que se carga

SET @pFlag_Tabla_Temp								= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Tabla_Temp')), 0)
SET @pFlagUsarTrans									= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug										= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Producto									= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), 0)
SET @pCantidad										= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Cantidad')), 0)
SET @pFecha_QA										= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_QA'))
SET @pFecha_Venc									= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Venc'))
SET @pId_Cliente									= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Contrato									= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Contrato')), 0)
SET @pBonif											= ISNULL(CONVERT(DECIMAL(5,2), dbo.CF_JSON_VALUE(@pJson,'Bonif')), 0)
SET @pPrecio_Grav 									= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Precio_Grav')), 0)
SET @pPrecio_Exen									= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Precio_Exen')), 0)
SET @pId_Tiempo	            						= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Id_Tiempo')), '')
SET @pRefacturar									= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Refacturar')), 0)
SET @pId_Trans										= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pLote											= ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Lote')), '')
SET @pFecha_Entrega									= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Entrega')), '19000101')
SET @pCosto_GF										= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Costo_GF')), 0)
SET @pCosto_MO										= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Costo_MO')), 0)
SET @pRedondeo_Imp_Final							= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Redondeo_Imp_Final')), 0)
SET @pCantidad_Equiv     							= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Cantidad_Equiv')), 0)
SET @pOmitir_Resultado_OK							= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Resultado_OK')), 0)
SET @pFlag_Verif_Prod_Fact_x_Contrato				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Verif_Prod_Fact_x_Contrato')), 0)
SET @pObservacion									= ISNULL(CONVERT(VARCHAR(255), dbo.CF_JSON_VALUE(@pJson,'Observacion')), '')
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Item 					SMALLINT
DECLARE @Id_Estado_Cbte 		SMALLINT
DECLARE @Calle 					CHAR(5)
DECLARE @Columna 				CHAR(5)
DECLARE @Fila 					CHAR(5)
DECLARE @Bultos 				DECIMAL(15, 5)
DECLARE @Despacho 				VARCHAR(100)
DECLARE @Serie 					VARCHAR(100)
DECLARE @Millas 				INT
DECLARE @Cantidad_Saldo 		DECIMAL(15, 5)
DECLARE @Imp_Gravado 			DECIMAL(12, 2)
DECLARE @Imp_Exento 			DECIMAL(12, 2)
DECLARE @Analisis 				VARCHAR(30)
DECLARE @Flag_QA 				CHAR(1)
DECLARE @Descripcion_producto 	VARCHAR(100)
DECLARE @Id_Unidad_Medida 		CHAR(4)
DECLARE @Imp_Final				DECIMAL(15,5)
DECLARE @Costo 					DECIMAL(15, 5)
DECLARE @Imp_Iva 				DECIMAL(12, 2)
DECLARE @Id_Costo 				INT
DECLARE @Id_Tarea 				SMALLINT
DECLARE @Fecha_Caducidad 		DATETIME
DECLARE @Id_Pais 				CHAR(3)
DECLARE @Id_Usuario 			SMALLINT
DECLARE @Cantidad_Equiv 		DECIMAL(15, 5)
DECLARE @Costo_MO 				DECIMAL(15, 5)
DECLARE @Costo_GF 				DECIMAL(15, 5)
DECLARE @Id_Cond_Pago 			SMALLINT
DECLARE @Fecha_Proceso 			DATETIME
DECLARE @Id_Balanza 			CHAR(10)
DECLARE @Orden 					SMALLINT
DECLARE @Flag_NoImp_Factura 	TINYINT
DECLARE @Nro_Tag 				VARCHAR(30)
DECLARE @Fecha_Elaboracion 		DATETIME
DECLARE @Costo_Comparativo 		DECIMAL(13, 4)
DECLARE @Porc_Imp_Int 			DECIMAL(5, 2)
DECLARE @Id_Cta_Banco 			SMALLINT
DECLARE @Flag_Existe_Trans		TINYINT
DECLARE @Flag_Existe_Cliente	TINYINT
DECLARE @Flag_Existe_Producto	TINYINT
DECLARE @Observacion			VARCHAR(8000)
DECLARE @Id_Lista_Precio		SMALLINT
DECLARE @Precio_Gravado_Producto DECIMAL(13, 4)
DECLARE @Precio					DECIMAL(15,5)
DECLARE @Item_Facturado         SMALLINT
DECLARE @Id_Iva					CHAR(3)
DECLARE @Porc1					DECIMAL(7,4)
DECLARE @Tasa_Iva_1				DECIMAL(12,2)
DECLARE @Tasa_Iva_2				DECIMAL(12,2)
DECLARE @Tasa_Iva_3				DECIMAL(12,2)
DECLARE @Porc_Iva				DECIMAL(5,2)		
DECLARE @Precio_Exen			DECIMAL(15,5)
DECLARE @Precio_Grav			DECIMAL(15,5)
DECLARE @Costo_Rentabilidad		DECIMAL(13,4)			--09/09/2021 Agregado
DECLARE @Cantidad		INT
DECLARE @Tipo			CHAR(1)
DECLARE @CantCiclos		INT
DECLARE @Flag_Mes		TINYINT
DECLARE @Flag_Periodo	TINYINT
/*FIN Declaracion Variables Locales*/

IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0 
	SET @pFlagUsarTrans = 0

BEGIN TRY
 
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Fac_Generar_Item'
		PRINT 'Parametros:'
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + ' Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans) + ' Id_Contrato: ' + CONVERT(VARCHAR(10), @pId_Contrato) + ' Id_Producto: ' + @pId_Producto + ' Cantidad: ' + CONVERT(VARCHAR(10), @pCantidad) + ' Fecha_QA: ' + CONVERT(VARCHAR(10), @pFecha_QA, 103) + ' Fecha_Venc: ' + CONVERT(VARCHAR(10), @pFecha_Venc, 103) + ' Id_Cliente: ' + CONVERT(VARCHAR(10), @pId_Cliente) + ' Bonif: ' + CONVERT(VARCHAR(10), @pBonif) + ' Precio_Grav: ' + CONVERT(VARCHAR(25), @pPrecio_Grav) + ' Precio_Exent: ' + CONVERT(VARCHAR(25), @pPrecio_Exen) 
	END

	/*===================================================================*/


    IF @pFlag_Tabla_Temp = 1
	BEGIN
		SET @pId_Trans	= 0
	END


	IF(@pId_Cliente = 0)	RAISERROR ('Id_Cliente can not be zero.', 16,  1 )
	IF(@pId_Producto = '')	RAISERROR ('Id_Producto can not be blank.', 16,  1 ) 
	
	SELECT @Flag_Mes = Flag_Mes, @Flag_Periodo = Flag_Periodo 
	       FROM Productos WHERE Id_Producto = @pId_Producto
    
	SET @Item_Facturado = 0

	IF @pRefacturar = 0 
	BEGIN

		IF @pFlag_Tabla_Temp = 1 AND OBJECT_ID (N'Z_CONTRATOS_FACTURADOS', N'U') IS NOT NULL 
		BEGIN
			SET @Item_Facturado = ISNULL((select 1 from Z_CONTRATOS_FACTURADOS WHERE id_Cliente  = @pId_Cliente AND Id_Producto = @pId_Producto),0)
		END
		IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Refacturar = 0'
 				PRINT 'Item Facturado1: ' + CONVERT(VARCHAR(10),@Item_Facturado) 
			End

	   	IF(@Item_Facturado = 0 AND @pFlag_Verif_Prod_Fact_x_Contrato = 0) -- 31/8
		BEGIN
    		IF @pId_Tiempo <> '' AND @Flag_Mes <> 1   --por defecto se toma mensual
			BEGIN

				SELECT @Cantidad = ISNULL(Cantidad,0), @Tipo = ISNULL(Tipo,0) FROM Tab_Uni_Tiempo WHERE Id_Tiempo = @pId_Tiempo
				IF @Cantidad = 0 SET @Cantidad = 1

				IF @Tipo = 'A'
					SELECT @CantCiclos = ISNULL(  DATEDIFF(yy,MAX(i.Fecha_QA),@pFecha_QA) ,9999999) 
							FROM Cbtes_Items i, Cbtes c , Cbtes_Tipos T 
							WHERE c.id_trans = i.id_trans 
									AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
									AND ((c.Comprobante_Nro = 0 AND c.Id_Estado_Cbte = 3) OR c.Id_Estado_Cbte NOT IN (0,3))
									AND (T.Compromete_Factura = 1 OR T.Compromete_Remitos = 1)
									AND I.Id_Cliente = @pId_Cliente
									AND i.Id_Producto = @pId_Producto
				ELSE IF @Tipo = 'D'
					SELECT @CantCiclos = ISNULL(  DATEDIFF(dd,MAX(i.Fecha_QA),@pFecha_QA) ,9999999) 
							FROM Cbtes_Items i, Cbtes c , Cbtes_Tipos T 
							WHERE c.id_trans = i.id_trans 
									AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
									AND ((c.Comprobante_Nro = 0 AND c.Id_Estado_Cbte = 3) OR c.Id_Estado_Cbte NOT IN (0,3))
									AND (T.Compromete_Factura = 1 OR T.Compromete_Remitos = 1)
									AND I.Id_Cliente = @pId_Cliente
									AND i.Id_Producto = @pId_Producto	
				ELSE		
					SELECT @CantCiclos = ISNULL(  DATEDIFF(mm,MAX(i.Fecha_QA),@pFecha_QA) ,9999999) 
							FROM Cbtes_Items i, Cbtes c , Cbtes_Tipos T 
							WHERE c.id_trans = i.id_trans 
									AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
									AND ((c.Comprobante_Nro = 0 AND c.Id_Estado_Cbte = 3) OR c.Id_Estado_Cbte NOT IN (0,3))
									AND (T.Compromete_Factura = 1 OR T.Compromete_Remitos = 1)
									AND I.Id_Cliente = @pId_Cliente
									AND i.Id_Producto = @pId_Producto	

				IF @CantCiclos < @Cantidad SET @Item_Facturado = 1
			END
		 ELSE   --IF ISNULL(@pId_Tiempo,'') <> ''   -
			BEGIN
				IF @Flag_Mes = 1 OR @Flag_Periodo = 1
				BEGIN
					IF @pFlag_Tabla_Temp = 1 AND OBJECT_ID (N'Z_Productos_Facturados', N'U') IS NOT NULL 
					BEGIN
						IF(@pModoDebug = 1)
							BEGIN
								PRINT 'Refacturar = 0'
 								PRINT 'Item Facturado3: ' + CONVERT(VARCHAR(10),@Item_Facturado) 
							End
						SELECT  @Item_Facturado = 1 FROM Z_Productos_Facturados WHERE Id_Producto = @pId_Producto AND Id_Cliente = @pId_Cliente
					END
				END
				ELSE
				BEGIN
						SELECT  @Item_Facturado = 1 FROM Cbtes_Items i, Cbtes c , Cbtes_Tipos T 
									WHERE c.id_trans = i.id_trans 
												AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
												AND ((c.Comprobante_Nro = 0 AND c.Id_Estado_Cbte = 3) 
												OR c.Id_Estado_Cbte NOT IN (0,3))
												AND (T.Compromete_Factura = 1 OR T.Compromete_Remitos = 1)
												AND ISNULL(I.Id_Cliente,C.ID_CLIENTE) = @pId_Cliente
												AND i.Id_Producto = @pId_Producto
												AND DATEPART(yy,i.Fecha_QA) = DATEPART(yy,@pFecha_QA) 
												AND DATEPART(mm,i.Fecha_QA) = DATEPART(mm,@pFecha_QA) 

				END
			END
		END
	END

    IF (@pRefacturar = 0 AND @Item_Facturado <> 0)
	BEGIN
		IF @pFlagUsarTrans <> 0 COMMIT

		/*************************************************************************************************/
		IF @pOmitir_Resultado_OK = 0
		BEGIN
			SET @rtaMsjStored		=	'{' +
										dbo.CF_Json_ParsearVariable('id_trans', ISNULL(@pId_Trans,0), 'INT')  + ',' +
										dbo.CF_Json_ParsearVariable('item', ISNULL(@Item,0), 'SMALLINT')  + ',' +
										dbo.CF_Json_ParsearVariable('id_producto', ISNULL(@pId_Producto,''), 'VARCHAR')  + ',' +
										dbo.CF_Json_ParsearVariable('imp_final', ISNULL(@Imp_Final,0), 'DECIMAL') +
										'}'

			SELECT	 0				AS ErrorNumber 
					,0				AS ErrorSeverity  
					,0				AS ErrorState 
					,0				AS ErrorProcedure  
					,0				AS ErrorLine		
					,@rtaMsjStored	AS ErrorMessage
		END
		RETURN 0
	END


	/*************************************************************************************************/

	SET @Tasa_Iva_1	= CONVERT(DECIMAL(12,2), dbo.CF_xParam('Tasa_Iva_1'))
	SET @Tasa_Iva_2	= CONVERT(DECIMAL(12,2), dbo.CF_xParam('Tasa_Iva_2'))
	SET @Tasa_Iva_3	= CONVERT(DECIMAL(12,2), dbo.CF_xParam('Tasa_Iva_3'))

	/*************************************************************************************************/

	SELECT  
	@Id_Estado_Cbte	= ISNULL(Id_Estado_Cbte, 0),
	@pLote			= ISNULL(Lote, ''),
	@Id_Usuario		= ISNULL(Id_Usuario, '-1')
	FROM Cbtes
	WHERE 
	Id_Trans = @pId_Trans

	/*************************************************************************************************/

	SELECT  
	@Calle					= ISNULL(Calle, ''),
	@Columna				= ISNULL(Columna, ''),
	@Fila					= ISNULL(Fila, ''),
	@Despacho				= ISNULL(Despacho, ''),
	@Descripcion_producto	= ISNULL(Descripcion_Resumida, ''),
	@Id_Unidad_Medida		= ISNULL(Id_Unidad_Medida, ''),
	@Costo					= ISNULL(Costo, 0),
	@Id_Cond_Pago			= ISNULL(Id_Cond_Pago, 0),
	@Id_Cta_Banco			= ISNULL(Id_Cta_Banco, 0),
	@Precio_Gravado_Producto = ISNULL(Precio_Gravado, 0),
	@Id_Iva					= ISNULL(Id_Iva, ''),
	@Costo_Rentabilidad		= ISNULL(Costo_Rentabilidad, 0),
	@Costo_mo		        = ISNULL(Costo_Rentabilidad, 0)
	FROM Productos
	WHERE 
	Id_Producto = @pId_Producto	
	

	/*************************************************************************************************/

	SELECT
	@Porc1	= ISNULL(Porc1, 0)
	FROM Productos_TasaIva
	WHERE
	Id_Iva = @Id_Iva
	
	SET @Porc_Iva = @Porc1


	/*************************************************************************************************/
		
	--EXENTO
	IF(@pBonif > 0)
	BEGIN
		SET @Precio_Exen			= @pPrecio_Exen * (1 - (@pBonif / 100))
	END
	ELSE
	BEGIN
		SET @Precio_Exen			= @pPrecio_Exen
	END

	SET @Imp_Exento				= @Precio_Exen * @pCantidad	

	-------------------------------------------------------------------------------------

	--GRAVADO
	IF(@pBonif > 0)
	BEGIN
		SET @Precio_Grav			= @pPrecio_Grav * (1 - (@pBonif / 100))
	END
	ELSE
	BEGIN
		SET @Precio_Grav			= @pPrecio_Grav
	END

	SET @Imp_Gravado			= @Precio_Grav * @pCantidad
	SET @Imp_Iva 				= @Imp_Gravado * (@Porc_Iva/100)

	-------------------------------------------------------------------------------------

	SET @Precio		= @Precio_Exen + @Precio_Grav 

	SET @Imp_Final	= @Imp_Exento + @Imp_Gravado + @Imp_Iva

	IF(@pRedondeo_Imp_Final > 0)
	BEGIN
		SET @Imp_Final				= ROUND(@Imp_Final, @pRedondeo_Imp_Final)
	END

	/*************************************************************************************************/

	IF @pFlag_Tabla_Temp = 1
	BEGIN
    	SET @Item 					= (ISNULL((SELECT MAX(ISNULL(Item, 0)) FROM #ITEMS_CBTE WHERE Id_Trans = @pId_Trans), 0)) + 1
	END
	ELSE
	BEGIN
     	SET @Item 					= (ISNULL((SELECT MAX(ISNULL(Item, 0)) FROM CBTES_ITEMS WHERE Id_Trans = @pId_Trans), 0)) + 1
	END


	SET @Bultos 				= 0
	SET @Serie 					= ''
	SET @Millas 				= 0
	SET @Cantidad_Saldo 		= @pCantidad
	SET @Analisis 				= ''
	SET @Flag_QA 				= 'A'
	SET @Id_Costo 				= 0
	SET @Id_Tarea 				= 0
	SET @Fecha_Caducidad 		= NULL
	SET @Id_Pais 				= ''
	SET @Cantidad_Equiv 		= @pCantidad_Equiv

    SET @Costo_GF 				= @pCosto_GF
	SET @Fecha_Proceso 			= NULL
	SET @Id_Balanza 			= ''
	SET @Orden 					= 0
	SET @Flag_NoImp_Factura 	= 0
	SET @Nro_Tag 				= ''
	SET @Fecha_Elaboracion 		= NULL
	SET @Costo_Comparativo 		= 0
	SET @Porc_Imp_Int 			= 0
	SET @Observacion			= (ISNULL((SELECT Observa_Factura FROM Productos WHERE Id_Producto = @pId_Producto), ''))

	-- 20260304s. Agrego para pisar el valor de arriba
	IF(@pObservacion <> '') SET @Observacion = @pObservacion

	/*************************************************************************************************/

	IF((@pFecha_Entrega <> '19000101') AND (CONVERT(DATE, @pFecha_Entrega) <> CONVERT(DATE, GETDATE())))
	BEGIN
		UPDATE Cbtes 
		SET
		Fecha_Estimada = @pFecha_Entrega
		WHERE
		Id_Trans = @pId_Trans
	END

	/*************************************************************************************************/

	IF @pFlag_Tabla_Temp = 1
	BEGIN
		INSERT INTO #ITEMS_CBTE
		(Id_Trans,		Item,					Id_Producto, 
		Id_Estado_Cbte, Cantidad,				Calle, 
		Columna,		Fila,					Bultos, 
		Despacho,		Serie,					Fecha_Venc,
		Observacion,	Millas,					Cantidad_Saldo, 
		Precio_Grav,	Precio_Exen,			Imp_Gravado, 
		Imp_Exento,		Analisis,				Lote, 
		Flag_QA,		Fecha_QA,				Porc_Iva, 
		Bonif,			Descripcion_producto,	Id_Unidad_Medida, 
		Imp_Final,		Costo,					Imp_Iva, 
		Precio,			Id_Costo,				Id_Cliente,
		Id_Tarea,		Fecha_Caducidad,		Id_Pais, 
		Id_Usuario,		Cantidad_Equiv,			Costo_MO, 
		Costo_GF,		Id_Cond_Pago,			Fecha_Proceso, 
		Id_Balanza,		Orden,					Flag_NoImp_Factura, 
		Nro_Tag,		Fecha_Elaboracion,		Costo_Comparativo, 
		Porc_Imp_Int,	Id_Cta_Banco)
		VALUES
		(@pId_Trans,		@Item,					@pId_Producto, 
		@Id_Estado_Cbte,	@pCantidad,				@Calle, 
		@Columna,			@Fila,					@Bultos, 
		@Despacho,			@Serie,					@pFecha_Venc,
		@Observacion,		@Millas,				@Cantidad_Saldo, 
		@Precio_Grav,		@Precio_Exen,			@Imp_Gravado, 
		@Imp_Exento,		@Analisis,				@pLote, 
		@Flag_QA,			@pFecha_QA,				@Porc_Iva, 
		@pBonif,			@Descripcion_producto,	@Id_Unidad_Medida, 
		@Imp_Final,			@Costo,					@Imp_Iva, 
		@Precio,			@Id_Costo,				@pId_Cliente,
		@Id_Tarea,			@Fecha_Caducidad,		@Id_Pais, 
		@Id_Usuario,		@Cantidad_Equiv,		@Costo_MO, 
		@Costo_GF,			@Id_Cond_Pago,			@Fecha_Proceso, 
		@Id_Balanza,		@Orden,					@Flag_NoImp_Factura, 
		@Nro_Tag,			@Fecha_Elaboracion,		@Costo_Comparativo, 
		@Porc_Imp_Int,		@Id_Cta_Banco)
	END
	ELSE
	BEGIN    
		INSERT INTO CBTES_ITEMS
		(Id_Trans,		Item,					Id_Producto, 
		Id_Estado_Cbte, Cantidad,				Calle, 
		Columna,		Fila,					Bultos, 
		Despacho,		Serie,					Fecha_Venc,
		Observacion,	Millas,					Cantidad_Saldo, 
		Precio_Grav,	Precio_Exen,			Imp_Gravado, 
		Imp_Exento,		Analisis,				Lote, 
		Flag_QA,		Fecha_QA,				Porc_Iva, 
		Bonif,			Descripcion_producto,	Id_Unidad_Medida, 
		Imp_Final,		Costo,					Imp_Iva, 
		Precio,			Id_Costo,				Id_Cliente,
		Id_Tarea,		Fecha_Caducidad,		Id_Pais, 
		Id_Usuario,		Cantidad_Equiv,			Costo_MO, 
		Costo_GF,		Id_Cond_Pago,			Fecha_Proceso, 
		Id_Balanza,		Orden,					Flag_NoImp_Factura, 
		Nro_Tag,		Fecha_Elaboracion,		Costo_Comparativo, 
		Porc_Imp_Int,	Id_Cta_Banco)
	    VALUES
		(@pId_Trans,		@Item,					@pId_Producto, 
		@Id_Estado_Cbte,	@pCantidad,				@Calle, 
		@Columna,			@Fila,					@Bultos, 
		@Despacho,			@Serie,					@pFecha_Venc,
		@Observacion,		@Millas,				@Cantidad_Saldo, 
		@Precio_Grav,		@Precio_Exen,			@Imp_Gravado, 
		@Imp_Exento,		@Analisis,				@pLote, 
		@Flag_QA,			@pFecha_QA,				@Porc_Iva, 
		@pBonif,			@Descripcion_producto,	@Id_Unidad_Medida, 
		@Imp_Final,			@Costo,					@Imp_Iva, 
		@Precio,			@Id_Costo,				@pId_Cliente,
		@Id_Tarea,			@Fecha_Caducidad,		@Id_Pais, 
		@Id_Usuario,		@Cantidad_Equiv,		@Costo_MO, 
		@Costo_GF,			@Id_Cond_Pago,			@Fecha_Proceso, 
		@Id_Balanza,		@Orden,					@Flag_NoImp_Factura, 
		@Nro_Tag,			@Fecha_Elaboracion,		@Costo_Comparativo, 
		@Porc_Imp_Int,		@Id_Cta_Banco)
	END

	/*===================================================================*/

	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	
 
	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('item',@Item, 'SMALLINT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_producto', @pId_Producto, 'VARCHAR')  + ',' +
									dbo.CF_Json_ParsearVariable('imp_final',@Imp_Final, 'DECIMAL') +
									'}'

		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Fac_Generar_Item'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO



CREATE PROCEDURE [dbo].[CPJ_Cbtes_Grabar_Numero] @pJson VARCHAR(8000)
AS
SET NOCOUNT ON
 
/*Variables recibidas por parámetro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Trans				INT
DECLARE @pOmitir_Resultado_OK	TINYINT
 
 
SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pOmitir_Resultado_OK		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Resultado_OK')), 0)
/*FIN Variables recibidas por parámetro a traves del JSON*/
 
/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
DECLARE @Result_Stored_Invocado				INT
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
/*FIN Variable de Retorono del Stored*/
 
/*Declaracion Variables Locales*/
DECLARE @Mensaje							VARCHAR(100)
DECLARE @Id_Tipo_Cbte						CHAR(4)
DECLARE @Fecha_Cai							DATETIME
DECLARE @Nro_Cai							VARCHAR(14)
DECLARE @Flag_Val_Correla					TINYINT
DECLARE @Compromete_Factura					SMALLINT
DECLARE @Fecha								DATETIME
DECLARE @Fecha_Cbte							DATETIME
DECLARE @Comprobante_Nro					INT
DECLARE @Id_Estado_Cbte						SMALLINT
DECLARE @Id_Cond_Pago						SMALLINT
DECLARE @Compromete_Recibos					SMALLINT
DECLARE @Compromete_Pagos					SMALLINT
/*Fin de Declaraciones Variables Locales */
BEGIN TRY
 
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Grabar_Numero'
		PRINT 'Parámetros:'
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + ' Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans)
	END
 
	/*===================================================================*/
 
	IF(@pId_Trans = 0)
	BEGIN
		SET @rtaErrorStored = 70001 /*Transaccion no abierta*/
		SELECT	 @rtaErrorStored	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,''					AS ErrorMessage
		IF @pFlagUsarTrans <> 0 
		BEGIN
			ROLLBACK
		END
		RETURN 9999
	END
	/*===================================================================*/	
 
	SELECT	@Id_Tipo_Cbte = ISNULL(T.Id_Tipo_Cbte,''),
			@Fecha_Cai = ISNULL(T.Fecha_Cai, '19000101'),
			@Nro_Cai = ISNULL(T.Nro_Cai, 0),
			@Flag_Val_Correla = ISNULL(T.Flag_Val_Correla,0),
			@Compromete_Factura = ISNULL(T.Compromete_Factura,0),
			@Id_Estado_Cbte = ISNULL(T.Id_Estado_Cbte,0),
			@Id_Cond_Pago = ISNULL(C.Id_Cond_Pago,0),
			@Compromete_Recibos = ISNULL(Compromete_Recibos,0),
			@Compromete_Pagos	= ISNULL(Compromete_Pagos,0),
			@Fecha_Cbte = C.Fecha,
			@Comprobante_Nro = ISNULL(T.Prox_Nro,1)
	FROM Cbtes_Tipos T, Cbtes C
	WHERE 
	T.Id_Tipo_Cbte = dbo.CF_Cbte_Traer_Tipo_Dest(C.Id_Tipo_Cbte)
	AND C.Id_Trans = @pId_Trans
 
    IF @Flag_Val_Correla = 1 OR (@Compromete_Factura <> 0 AND CAST( dbo.CF_xParam('Fact_Cont_FN') AS INT ) <> 0 )
	BEGIN
	    /*
		SELECT	@Fecha = MAX(Fecha),
				@Comprobante_Nro = ISNULL(MAX(Comprobante_Nro),0) + 1 FROM Cbtes 
		WHERE 
		(Id_Tipo_Cbte = @Id_Tipo_Cbte OR Id_Tipo_Cbte  IN (	SELECT Id_Tipo_Cbte 
															FROM Cbtes_Tipos 
															WHERE Id_Tipo_Cbte_Dest = @Id_Tipo_Cbte)) --para destino y todos los cbtes que dependen del destino
		AND NOT (Id_Estado_Cbte = 3 AND Comprobante_Nro = 0)
		*/
 
		SELECT  
			@Fecha = MAX(Fecha),
			@Comprobante_Nro = ISNULL(MAX(Comprobante_Nro), 0) + 1
		FROM Cbtes
		WHERE 
			Id_Tipo_Cbte IN (
				SELECT Id_Tipo_Cbte 
				FROM Cbtes_Tipos 
				WHERE Id_Tipo_Cbte_Dest = @Id_Tipo_Cbte
				UNION
				SELECT @Id_Tipo_Cbte
			)
			AND NOT (Id_Estado_Cbte = 3 AND Comprobante_Nro = 0);
 
 
	   SET @Fecha = ISNULL(@Fecha,GETDATE())
	   SET @Comprobante_Nro = ISNULL(@Comprobante_Nro, 1)
 
	   IF @Fecha > @Fecha_Cbte
	   BEGIN
			SET @Fecha_Cbte = @Fecha
		END
	END
 
	IF @Id_Estado_Cbte = 0  --si no tenia valor por defecto
	BEGIN
		SET @Id_Estado_Cbte = 1  --Pendiente
 
		IF (@Compromete_Factura <> 0 AND @Id_Cond_Pago = 1 ) OR @Compromete_Recibos <> 0 OR @Compromete_Pagos <> 0
		BEGIN
			SET @Id_Estado_Cbte = 2	 --Completo
		END
	END
 
 
	
	UPDATE Cbtes_Items 		SET Id_Estado_Cbte	= @Id_Estado_Cbte	WHERE	Id_Trans = @pId_Trans
 
 
	UPDATE Cbtes 
		SET 
		Comprobante_Nro = @Comprobante_Nro,
		Fecha = @Fecha_Cbte,
		Id_Estado_Cbte = @Id_Estado_Cbte,
		Cai_Vence  = @Fecha_Cai,
		Cai = @Nro_Cai
		WHERE 
		Id_Trans = @pId_Trans
 
	UPDATE Clientes_CtaCte
		SET	
		Id_Estado_Cbte	= @Id_Estado_Cbte,
		Descripcion		= dbo.CF_Cbte_Descrip(@pId_Trans) --19/11/2020 Agregado
		WHERE	
		Id_Trans = @pId_Trans
 
 
	/*
 
	UPDATE Cbtes_Tipos 
		SET 
		Fecha_Ult = @Fecha_Cbte, 
		Prox_Nro = @Comprobante_Nro + 1
		WHERE 
		Id_Tipo_Cbte = @Id_Tipo_Cbte 
		OR Id_Tipo_Cbte IN (SELECT Id_Tipo_Cbte 
							FROM Cbtes_Tipos 
							WHERE Id_Tipo_Cbte_Dest = @Id_Tipo_Cbte) --para destino y todos los cbtes que dependen del destino
    */
 
 
	DECLARE @TiposAActualizar TABLE (Id_Tipo_Cbte CHAR(4));
 
	INSERT INTO @TiposAActualizar (Id_Tipo_Cbte)
	SELECT Id_Tipo_Cbte
	FROM Cbtes_Tipos
	WHERE Id_Tipo_Cbte_Dest = @Id_Tipo_Cbte
	UNION
	SELECT @Id_Tipo_Cbte;
 
	UPDATE CT
	SET 
		Fecha_Ult = @Fecha_Cbte, 
		Prox_Nro = @Comprobante_Nro + 1
	FROM Cbtes_Tipos CT
	JOIN @TiposAActualizar T ON T.Id_Tipo_Cbte = CT.Id_Tipo_Cbte;
 
	/*===================================================================*/	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END
	/*===================================================================*/	
 
	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_Trans', @pId_Trans, 'INT') + ',' +
									dbo.CF_Json_ParsearVariable('comprobante_Nro', @Comprobante_Nro, 'INT') +
									'}'
 
		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage
	END
 
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Grabar_Numero'
	END
END TRY  
 
 
BEGIN CATCH  
    EXECUTE usp_GetErrorInfo
 
	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END
 
	RETURN 9999
END CATCH;   
 
RETURN 0
GO



CREATE PROCEDURE [dbo].[CPJ_Cbtes_Interes_Calc] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON

DECLARE @pId_Cliente INT
       ,@pId_Unid_Negocio VARCHAR(10)
	   ,@pCriterio VARCHAR(1)
	   ,@pId_Trans INT

SET @pId_Cliente		= ISNULL(CONVERT(INT,dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')), 0)
SET @pId_Unid_Negocio	= ISNULL(CONVERT(VARCHAR(10),dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')), 0)
SET @pCriterio	    	= ISNULL(CONVERT(VARCHAR(1),dbo.CF_JSON_VALUE(@pJsonRecibido,'Criterio')), 'D')
SET @pId_Trans		    = ISNULL(CONVERT(INT,dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Trans')), 0)

DECLARE @Imp_Recargo DECIMAL(12,2)								  

SELECT Id_Unid_Negocio INTO #UN FROM Empresas_Unid_Negocios
IF @pId_Unid_Negocio <> ''
    DELETE #UN WHERE Id_Unid_Negocio <> @pId_Unid_Negocio

SELECT I.Id_Trans,I.ID_PRODUCTO,I.descripcion_producto,I.Imp_Final,C.Imp_Total,C.Saldo
                ,(C.Saldo/C.Imp_Total) as Coef
				, dbo.CF_FOMONTH(C.Fecha) as Fecha_Desde
				,DATEDIFF(dd,dbo.CF_FOMONTH(C.Fecha),GETDATE()) AS Dif_dias
				,I.Id_Cond_Pago
				,(Select CP.Porc_Bonif from Cbtes_Cond_Pago_Items Cp 
						where cp.Id_Cond_Pago = I.Id_Cond_Pago
						and DATEDIFF(dd,dbo.CF_FOMONTH(C.Fecha),GETDATE()) >= CP.Plazo_Desde
						and DATEDIFF(dd,dbo.CF_FOMONTH(C.Fecha),GETDATE()) <= CP.Plazo_Bonif 
						) As Porc_Recargo
				,(Select CP.Plazo_Sin_Recargo from Cbtes_Cond_Pago_Items Cp 
						where cp.Id_Cond_Pago = I.Id_Cond_Pago
						and DATEDIFF(dd,dbo.CF_FOMONTH(C.Fecha),GETDATE()) >= CP.Plazo_Desde
						and DATEDIFF(dd,dbo.CF_FOMONTH(C.Fecha),GETDATE()) <= CP.Plazo_Bonif 
						) As Plazo_Sin_Recargo
				,(Select CP.Tipo from Cbtes_Cond_Pago_Items Cp 
						where cp.Id_Cond_Pago = I.Id_Cond_Pago
						and DATEdiff(dd,dbo.CF_FOMONTH(C.Fecha),GETDATE()) >= CP.Plazo_Desde
						and DATEdiff(dd,dbo.CF_FOMONTH(C.Fecha),GETDATE()) <= CP.Plazo_Bonif 
						) As Tipo
				,Cast(0 as Decimal(12,2)) as Importe_Recargo
				,C.Destinatario as razon_Social
		 INTO #RECARGOS
		 FROM Clientes_CtaCte k, Cbtes C, Cbtes_Tipos T, Cbtes_Items I,#UN U, Productos P
			  WHERE k.ID_CLIENTE = @pId_Cliente 
			  and k.Id_Estado_Cbte in (1,4)
			  and C.Id_Trans = I.Id_Trans
			  And C.Id_Trans = K.Id_Trans
			  And C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
			  And T.Id_Unid_Negocio = U.Id_Unid_Negocio
			  And T.Compromete_Factura IN (1,-1)
			  And T.Letra <> 'L'
			  And P.Id_Producto = I.Id_Producto
			  AND I.Imp_Final <> 0
			  AND I.Id_Cond_Pago IS NOT NULL AND I.Id_Cond_Pago <> 0
		--	  And P.Flag_Mes = 1
			  AND I.Fecha_QA IS NOT NULL
			  ORDER BY k.Fecha_Vence,k.Id_Trans

UPDATE #RECARGOS SET Importe_Recargo =  Imp_Final * (Porc_Recargo / 100)

UPDATE #RECARGOS SET Importe_Recargo =  Imp_Final * (Porc_Recargo * (Dif_Dias - Plazo_Sin_Recargo) / 100)
	          WHERE UPPER(Tipo) = 'D' AND Porc_Recargo > 0 AND Dif_Dias > Plazo_Sin_Recargo

UPDATE #RECARGOS SET Importe_Recargo =  Importe_Recargo * Coef

UPDATE #RECARGOS SET Id_Producto =  (SELECT dbo.CF_xParam('PROD_RECARGOS'))

SET @Imp_Recargo = (SELECT TOP 1 ISNULL(Importe_Recargo,0) FROM #RECARGOS WHERE Id_Trans = @pId_Trans)

IF (@Imp_Recargo > 0)
BEGIN
	UPDATE #RECARGOS SET descripcion_producto += ' ' + '(Recargo)'  
END
ELSE
BEGIN
	UPDATE #RECARGOS SET descripcion_producto += ' ' + '(Descuento)'  
END

SELECT DISTINCT(ID_TRANS) INTO #TRANS FROM #RECARGOS

IF @pId_Trans <> 0
	     DELETE #TRANS WHERE ID_TRANS <> @pId_Trans

If @pCriterio = 'R' 
         Select Id_Producto,Sum(Importe_Recargo) Recargo from #RECARGOS R , #TRANS T
		        WHERE R.ID_TRANS = T.ID_TRANS group by Id_Producto

If @pCriterio = 'D'
		 Select * from #RECARGOS R , #TRANS T
               WHERE R.ID_TRANS = T.ID_TRANS  

If @pCriterio = 'T' 
         Select R.Id_TRANS,Sum(Importe_Recargo) Recargo from #RECARGOS R , #TRANS T
		        WHERE R.ID_TRANS = T.ID_TRANS group by R.Id_TRANS

DROP TABLE #RECARGOS
DROP TABLE #UN
DROP TABLE #TRANS

 /*
 EXEC dbo.CPJ_Cbtes_Interes_Calc.   '{
			"Id_Cliente":"19887",
			"Id_Unid_Negocio":"",
			"Criterio":"T",
			"Id_Trans":"493364",
		}'

 EXEC dbo.CPJ_Cbtes_Interes_Calc.   '{
			"Id_Cliente":"19887",
			"Id_Unid_Negocio":"",
			"Criterio":"T",
			"Id_Trans":"",
		}'

*/
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Lotes_Asientos_Generar] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON

DECLARE 	@pLote				VARCHAR(20),
			@pFecha_Desde		DATETIME,
			@pFecha_Hasta		DATETIME,
			@pTipo				CHAR(3),
			@pCriterio			CHAR(3),
			@pFlagUsarTrans		TINYINT,
			@pModoDebug			TINYINT

SET @pLote				= ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJsonRecibido,'Lote')), '')
SET @pFecha_Desde		= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Desde')),GETDATE())
SET @pFecha_Hasta		= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Hasta')),GETDATE())
SET @pTipo				= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Tipo')), '')
SET @pCriterio			= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Criterio')), '')
SET @pFlagUsarTrans		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FlagUsarTrans')), 0)
SET @pModoDebug			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)

/* DECLARACION DE VARIABLES LOCALES */

DECLARE @JSON_Parametros_Stored_Invocado				VARCHAR(8000)
DECLARE @Result_Stored_Invocado							INT
DECLARE @Mensaje										VARCHAR(100)
DECLARE @UltError										INT
DECLARE @Segundos										INT
DECLARE @Cta_No_Definida								INT

DECLARE @Result_Tabla_Stored_Invocado TABLE (
											  ErrorNumber		INT,
											  ErrorSeverity		INT,
											  ErrorState		INT,
											  ErrorProcedure	VARCHAR(1000),
											  ErrorLine			INT,
											  ErrorMessage		VARCHAR(1000)
											)

CREATE TABLE #TRANS_TIPO ( Id_Trans INT )
CREATE TABLE #TRANS_CRITERIO ( Id_Trans INT )

/* FIN DECLARACION DE VARIABLES LOCALES */

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Lotes_Asientos_Generar'
	PRINT 'Parametros:'
	PRINT '@pLote: ' + @pLote
	PRINT '@pFecha_Desde: ' + CONVERT(VARCHAR(30), @pFecha_Desde, 112)
	PRINT '@pFecha_Hasta: ' + CONVERT(VARCHAR(30), @pFecha_Hasta, 112)
	PRINT '@pTipo: ' + CONVERT(VARCHAR(5), @pTipo)
	PRINT '@pCriterio: ' + CONVERT(VARCHAR(5), @pCriterio)
	PRINT '@pFlagUsarTrans: ' + CONVERT(VARCHAR(5), @pFlagUsarTrans)
END

BEGIN TRY

	IF(ISNULL(dbo.CF_xParam('CtaNoDefinida'),0) = 0)
		RAISERROR ('Debe definir el parametro CtaNoDefinida', 16, 1)

	/* ---------------------------------------------------- POR PARAMETRO @pTipo ---------------------------------------------------- */
	IF(@pLote <> '')
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Genera por parametro @pLote'
		END

		INSERT INTO #TRANS_TIPO SELECT Id_Trans FROM Cbtes WHERE Lote = @pLote
	END
	ELSE IF(@pTipo <> '')
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Genera por parametro @pTipo - Filtra por Tipo de Cbte y Rango de Fechas'
		END

		INSERT INTO #TRANS_TIPO SELECT C.Id_Trans 
								  FROM Cbtes C
								  LEFT JOIN Cbtes_Tipos CT ON CT.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
								  WHERE Fecha >= CONVERT(varchar(30),@pFecha_Desde,112)
										AND Fecha < CONVERT(varchar(30),DATEADD(DAY,1,@pFecha_Hasta),112)
										AND 1 = ABS(CASE 
							  						WHEN @pTipo = 'V' THEN CT.Compromete_Factura
							  						WHEN @pTipo = 'C' THEN CT.Compromete_Compras
							  						WHEN @pTipo = 'P' THEN CT.Compromete_Pagos
							  						WHEN @pTipo = 'R' THEN CT.Compromete_Recibos
							  						WHEN @pTipo = 'T' THEN CT.Compromete_Trans_Fondos
							  					END)

		END
	/* ---------------------------------------------------- FIN POR PARAMETRO @pTipo ---------------------------------------------------- */

	/* ---------------------------------------------------- POR PARAMETRO @pCriterio ---------------------------------------------------- */

	IF(@pCriterio = 'G' OR @pCriterio = 'E')
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Genera por @pCriterio General o Error'
		END

		/* AGREGO TRANSACCIONES SIN ASIENTOS */
		INSERT INTO #TRANS_CRITERIO SELECT Id_Trans FROM #TRANS_TIPO TT WHERE NOT EXISTS (SELECT ID_TRANS FROM Cbtes_Ctas_Contables CCC WHERE CCC.ID_TRANS = TT.Id_Trans)

		IF(@pCriterio = 'E')
		BEGIN
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Filtra por @pCriterio Error'
			END

			/* AGREGO TRANSACCIONES CON CUENTA 'A IMPUTAR' */
			SET @Cta_No_Definida = dbo.CF_xParam('CtaNoDefinida')

			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Agrega Trans con Cuenta a Imputar (ALIAS: ' + CONVERT(VARCHAR(10),@Cta_No_Definida) + ')'
			END

			INSERT INTO #TRANS_CRITERIO SELECT Id_Trans FROM #TRANS_TIPO TT WHERE EXISTS (SELECT ID_TRANS FROM Cbtes_Ctas_Contables CCC WHERE CCC.ID_TRANS = TT.Id_Trans AND ALIAS = @Cta_No_Definida)

			/* AGREGO TRANSACCIONES CON ASIENTOS NO BALANCEADOS */
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Agrega Trans no balanceadas'
			END

			INSERT INTO #TRANS_CRITERIO SELECT TT.Id_Trans FROM #TRANS_TIPO TT LEFT JOIN Cbtes_Ctas_Contables CCC ON TT.Id_Trans = CCC.ID_TRANS
															    GROUP BY TT.ID_TRANS
															    HAVING (SUM(CCC.HABER) - SUM(CCC.DEBE)) <> 0

		END
	END
	ELSE IF(@pCriterio = 'R')
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Genera por @pCriterio Regenera'
		END
		INSERT INTO #TRANS_CRITERIO SELECT Id_Trans FROM #TRANS_TIPO
		DELETE FROM Cbtes_Ctas_Contables WHERE ID_TRANS IN (SELECT Id_Trans FROM #TRANS_TIPO)
	END
	/* ---------------------------------------------------- FIN POR PARAMETRO @pCriterio ---------------------------------------------------- */

	/* ------------------------------------------------------ CORRECCION DE ASIENTOS ------------------------------------------------------ */

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Realiza la correccion de asientos'
	END

	DECLARE @Id_Trans INT
	DECLARE curCPJAsientos CURSOR FOR
	SELECT Id_Trans FROM #TRANS_CRITERIO

	OPEN curCPJAsientos
	FETCH NEXT FROM curCPJAsientos INTO @Id_Trans
	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Id_Trans: ' + CONVERT(VARCHAR(20),@Id_Trans)
		END

		SET @JSON_Parametros_Stored_Invocado =	'{' +
												dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'TINYINT') + ',' +
												dbo.CF_Json_ParsearVariable('Id_Trans', @Id_Trans, 'INT') + ',' +
												dbo.CF_Json_ParsearVariable('ModoDebug', 0, 'TINYINT') + ',' +
												dbo.CF_Json_ParsearVariable('FlagRegenerar', 1, 'TINYINT') + 
												'}'
				
		
		INSERT INTO @Result_Tabla_Stored_Invocado					
		EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Ctas_Contables_Generar @JSON_Parametros_Stored_Invocado

		IF ISNULL(@Result_Stored_Invocado,0) <> 0 
		BEGIN
			INSERT INTO Cbtes_Lotes_Errores (Lote,Item,Id_Trans,Id_Cliente,Cod_Barra,Descripcion,Importe)
									VALUES (@pLote,1,@Id_Trans,0,'','Error desde CPJ_Cbtes_Lotes_Asientos_Generar',0)
			RETURN 9999
		END

	FETCH NEXT FROM curCPJAsientos INTO @Id_Trans
	END
	CLOSE curCPJAsientos
	DEALLOCATE curCPJAsientos

	/* ------------------------------------------------------ FIN CORRECCION DE ASIENTOS ------------------------------------------------------ */

	DROP TABLE #TRANS_TIPO
	DROP TABLE #TRANS_CRITERIO

END TRY  
BEGIN CATCH  
	IF EXISTS(SELECT * FROM @Result_Tabla_Stored_Invocado)
	BEGIN
		SELECT * FROM @Result_Tabla_Stored_Invocado
		EXECUTE usp_GetErrorInfo
		RETURN 9999
	END
END CATCH

RETURN 0

/*
MODO DE USO:

DECLARE @Param VARCHAR(5000) -- 10 seg x 4088 (calculo de casi 80000 transacciones -> 13 minutos)

SET @Param = '{' +
			'"Lote":"",' +
			'"Fecha_Desde":"20230701",' +
			'"Fecha_Hasta":"20230731",' +
			'"Tipo":"R",' +
			'"Criterio":"E",' +
			'"FlagUsarTrans":"0",' +
			'"ModoDebug":"1"' +
			'}'

EXEC CPJ_Cbtes_Lotes_Asientos_Generar @Param
*/
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Lotes_Cobranza] @pJson VARCHAR(8000)

AS
SET NOCOUNT ON

Declare	@pLote				VARCHAR(29),
		@pFecha				DATETIME,
		@pDescripcion		VARCHAR(50),
		@pId_Lote_Tipo		SMALLINT,
		@pId_Periodo_Caja	INT,
		@pFecha_Rec			DATETIME,
		@pId_Tipo_Cbte		CHAR(4),
		@pId_Moneda			CHAR(3),
		@pCotizacion		DECIMAL(9,4),
		@pId_Tipo_Val		CHAR(3),
		@pImporte			DECIMAL(16,2),
		@pUsuario			INT,
    	@pId_Tarjeta        VARCHAR(10),
    	@pId_Cta_banco      INT,
	    @pId_Cobrador		VARCHAR(10) /*21/05/2020 Agregado x Ticket 19.849*/

SET @pLote				= ISNULL(CONVERT(VARCHAR(29), dbo.CF_JSON_VALUE(@pJson,'Lote')), '')
SET @pFecha				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')), GETDATE())
SET @pDescripcion		= ISNULL(CONVERT(VARCHAR(50), dbo.CF_JSON_VALUE(@pJson,'Descripcion')), '')
SET @pId_Lote_Tipo      = ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Lote_Tipo')), 0)
SET @pId_Periodo_Caja   = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Periodo_Caja')), 0)
SET @pFecha_Rec			= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Rec')), GETDATE())
SET @pId_Tipo_Cbte		= ISNULL(CONVERT(CHAR(4), dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Cbte')),'')
SET @pId_Moneda			= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Id_Moneda')), '')
SET @pCotizacion        = ISNULL(CONVERT(DECIMAL(9,4), dbo.CF_JSON_VALUE(@pJson,'Cotizacion')), 1)
SET @pId_Tipo_Val		= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Val')), '')
SET @pImporte			= ISNULL(CONVERT(DECIMAL(16,2), dbo.CF_JSON_VALUE(@pJson,'Importe')), 0)
SET @pUsuario           = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), 0)
SET @pId_Tarjeta        = ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Tarjeta')), '')
SET @pId_Cta_banco      = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cta_banco')), 0)
SET @pId_Cobrador       = ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Cobrador')), '')

/*Declaracion Variables Locales*/



DECLARE @Usar_Trans			TINYINT
--SET @Usar_Trans = ISNULL((SELECT 1 WHERE SERVERPROPERTY('ProductVersion') > '10.50.4000.0'),0)
----IF @@TRANCOUNT > 0 SET @Usar_Trans = 0
SET @Usar_Trans = 0

/*Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@Id_Cliente		INT
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Trans_Rec		INT
		,@CursorOpen        INT
		,@Flag_Cbte_Tipo	SMALLINT
		,@Sql               VARCHAR(5000)
		,@Imp_SP            VARCHAR(1000) 


  DECLARE @Respuesta Table (
				ErrorNumber		INT,
				ErrorSeverity	INT,
				ErrorState		INT,
				ErrorProcedure  VARCHAR(1000),
				ErrorLine		INT,
				ErrorMessage	VARCHAR(1000)
				)

BEGIN TRY
	IF @Usar_Trans = 1 BEGIN TRAN

	/*Agregar Lote con fecha de inicio y Flag_enProceso en 1 */

	INSERT INTO Cbtes_Lotes (Lote,Fecha,Descripcion,Id_Lote_Tipo,Flag_enProceso,Fecha_Inicio)
		VALUES (@pLote,@pFecha,@pDescripcion,@pId_Lote_Tipo,1,GETDATE())



	/*Recorrer los tagueados */

	DECLARE TagCbtesCursor CURSOR FOR
		SELECT T.Ptr AS Id_Trans, C.Id_Cliente,T.Importe , C.Email_Cob
				FROM TagFile_ T , Clientes C
				WHERE Tbl = 300 AND Usr = @pUsuario
				AND C.Id_Cliente = CAST(T.Val AS INT)

	OPEN TagCbtesCursor

	FETCH NEXT FROM TagCbtesCursor INTO @Id_Trans,@Id_Cliente,@Importe,@Email_Cob
	SET @CursorOpen = 0	
	SET @UltError = 0
	WHILE @@FETCH_STATUS=0 AND @UltError  = 0
	BEGIN
	        SET @CursorOpen = 1	

		    SET @Id_Trans_Rec = 0

			DELETE @Respuesta
			INSERT INTO @Respuesta
			EXEC @UltError = CP_Cbtes_Rec_Generar @pUsuario, @Id_Cliente,@Email_Cob,@pId_Periodo_Caja,@pFecha_Rec,@Importe,@pId_Tipo_Cbte,@pId_Moneda,@pCotizacion,@pLote, @pId_Cobrador
			IF @UltError <> 0
				BEGIN
					IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 ROLLBACK
					SELECT * FROM @Respuesta	
					RETURN 4567
				END
			ELSE	
				SELECT TOP 1 @Id_Trans_Rec = ErrorLine FROM @Respuesta

            IF @Id_Trans_Rec = 0
			BEGIN
				IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 ROLLBACK
				SELECT	 4568			AS ErrorNumber 
						,0				AS ErrorSeverity  
						,0				AS ErrorState 
						,0				AS ErrorProcedure  
						,0				AS ErrorLine		
						,'No se genero el numero de trans recibo'		AS ErrorMessage
				RETURN 4568
			END


			DELETE @Respuesta
			INSERT INTO @Respuesta
			EXEC @UltError = CP_Cbtes_Rec_Generar_Item @Id_Trans_Rec,1,'',1,@Id_Trans,@Importe
			IF @UltError <> 0
			BEGIN
				IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 ROLLBACK
				SELECT * FROM @Respuesta	
				RETURN 4569
			END


			DELETE @Respuesta
			INSERT INTO @Respuesta
			EXEC @UltError = CP_Cbtes_Rec_Generar_Pago @Id_Trans_Rec,@pId_Tipo_Val,0,@pFecha_Rec,@pFecha_Rec,@pFecha_Rec,@pFecha_Rec,@Importe,@pId_Tarjeta,'',NULL,'','',0,@pId_Cta_banco
			IF @UltError <> 0
			BEGIN
				IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 ROLLBACK
				SELECT * FROM @Respuesta	
				RETURN 4570
			END

			
			
			DELETE @Respuesta
			INSERT INTO @Respuesta
			EXEC @UltError = CP_Cbtes_Rec_Fin @Id_Trans_Rec
			
			IF @UltError <> 0
			BEGIN
				IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 ROLLBACK
				SELECT * FROM @Respuesta	
				RETURN 4571
			END
			
				
   			FETCH NEXT FROM TagCbtesCursor INTO @Id_Trans,@Id_Cliente,@Importe,@Email_Cob	

	END
	CLOSE TagCbtesCursor
	DEALLOCATE TagCbtesCursor
	SET @CursorOpen = 0	

	/*Actualizar Lote con fecha de fin y Flag_enProceso en 0 y totales */
	UPDATE Cbtes_Lotes SET	Cantidad = (SELECT COUNT(*) FROM Cbtes WHERE Lote = @pLote) ,
							Importe =  (SELECT SUM(Imp_Total) FROM Cbtes WHERE Lote = @pLote),
							Fecha_Finalizacion = GETDATE(),
							Flag_enProceso = 0
			WHERE Lote = @pLote
			
	/*CURSOR DE LOS CBTES DEL LOTE */
	/*  Ahora lo hace CP_Cbtes_Rec_Fin         9/9/2020 Gaby

    SELECT @Imp_SP = ISNULL(Imp_Sp,'') FROM CBTES_TIPOS WHERE ID_TIPO_CBTE = @pId_Tipo_Cbte
	
	IF @Imp_SP <> ''
	BEGIN	

		DECLARE Cursor_Fact_Pro CURSOR FOR
		SELECT c.Id_Trans
		FROM cbtes c
		WHERE c.lote = @pLote
		
		
		OPEN Cursor_Fact_Pro
		FETCH NEXT FROM Cursor_Fact_Pro INTO  @Id_trans
		WHILE @@FETCH_STATUS = 0
		BEGIN	

		    SET @sql = 'EXEC '+ LTRIM(RTRIM(@Imp_SP)) +' '+ CAST(@Id_Trans AS VARCHAR(10))

			EXEC(@sql)
			
		FETCH NEXT FROM Cursor_Fact_Pro INTO @Id_Trans
		END
		CLOSE Cursor_Fact_Pro
		DEALLOCATE Cursor_Fact_Pro
	END
	*/
	/*FIN */
		
	/******************************fin del proceso***********************************************/


	/*******************    En caso de error deberia grabar en la tablla cbtes_errores ***********************/

	
	IF @Usar_Trans = 1 AND @@TRANCOUNT > 0  COMMIT

	SET @Mensaje = (SELECT DATEDIFF(s,Fecha_Inicio,Fecha_Finalizacion) FROM CBTES_LOTES WHERE LOTE = @pLote)

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage
END TRY  


BEGIN CATCH  
    
    EXECUTE usp_GetErrorInfo
	IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 ROLLBACK
	
	UPDATE Cbtes_Lotes SET	Cantidad = (SELECT COUNT(*) FROM Cbtes WHERE Lote = @pLote) ,
							Importe =  (SELECT SUM(Imp_Total) FROM Cbtes WHERE Lote = @pLote),
							Fecha_Finalizacion = GETDATE(),
							Flag_enProceso = 0
			WHERE Lote = @pLote

      IF @CursorOpen = 1
	     BEGIN 
		 	CLOSE TagCbtesCursor
	        DEALLOCATE TagCbtesCursor
         END
		 	
	RETURN 9999
END CATCH

RETURN 0
GO



CREATE PROCEDURE [dbo].[CPJ_Cbtes_Lotes_Facturar] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON

/*
  VERSION  03/12/2021 
*/

DECLARE 	@pLote				VARCHAR(29),
			@pFecha				DATETIME,
			@pDescripcion		VARCHAR(50),
			@pId_Lote_Tipo		SMALLINT,
			@pFecha_Desde		DATETIME,
			@pFecha_Hasta		DATETIME,
			@pFecha_Rem_Desde	DATETIME,
			@pFecha_Rem_Hasta	DATETIME,
			@pFecha_QA       	DATETIME,
			@pFecha_Venc     	DATETIME,
			@pId_Tipo_Cont      INT,
			@pId_Usuario		INT,
			@pFiltrarTarjeta    Tinyint,
			@pFiltrarCliente    Tinyint,
			@pFiltrarCondPago   Tinyint,
			@pFiltrarTipoCbte   Tinyint,
			@pFiltrarCantCont   INT,
			@pRefacturar        TINYINT,
			@pIncl_Cbtes_Cero   Tinyint,
			@pFlagUsarTrans		TINYINT,
			@pModoDebug			TINYINT

SET @pLote				= ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJsonRecibido,'Lote')), '')
SET @pFecha				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha')),GETDATE())
SET @pDescripcion		= ISNULL(CONVERT(VARCHAR(50), dbo.CF_JSON_VALUE(@pJsonRecibido,'Descripcion')), '')
SET @pId_Lote_Tipo		= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Lote_Tipo')), 0)
SET @pFecha_Desde		= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Desde')),GETDATE())
SET @pFecha_Hasta		= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Hasta')),GETDATE())
SET @pFecha_Rem_Desde	= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Rem_Desde')),GETDATE())
SET @pFecha_Rem_Hasta	= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Rem_Hasta')),GETDATE())
SET @pFecha_QA			= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_QA')),@pFecha_Desde)
SET @pFecha_Venc		= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Venc')),@pFecha_Hasta)
SET @pId_Tipo_Cont		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Tipo_Cont')), 0)
SET @pId_Usuario		= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Usuario')), 0)
SET @pFiltrarTarjeta	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FiltrarTarjeta')), 0)
SET @pFiltrarCliente	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FiltrarCliente')), 0)
SET @pFiltrarCondPago	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FiltrarCondPago')), 0)
SET @pFiltrarTipoCbte	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FiltrarTipoCbte')), 0)
SET @pFiltrarCantCont	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FiltrarCantCont')), 0)
SET @pRefacturar		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Refacturar')), 0)
SET @pIncl_Cbtes_Cero   = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Incl_Cbtes_Cero')), 0)
SET @pFlagUsarTrans		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FlagUsarTrans')), 0)
SET @pModoDebug			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)


/*Declaracion Variables Locales*/



DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Segundos			INT



DECLARE @Sql		VARCHAR(MAX)
DECLARE @SqlSaldo	VARCHAR(MAX)
DECLARE @SqlSelect	VARCHAR(MAX)
DECLARE @SqlFrom	VARCHAR(MAX)
DECLARE @SqlWhere	VARCHAR(MAX)
DECLARE @SqlGroup	VARCHAR(MAX)

DECLARE @Id_Contrato INT
DECLARE @Id_Tiempo CHAR(3)
DECLARE @Flag_Agru_Cli_Ref TINYINT
DECLARE @Lote_en_proceso SMALLINT

DECLARE @pJson		VARCHAR(8000)

BEGIN TRY
      
      SET @Lote_en_proceso = ISNULL((SELECT COUNT(*) FROM Cbtes_Lotes WHERE Flag_enProceso = 1),0)
      IF(@Lote_en_proceso <>  0)  RAISERROR ('Existe actualmente otro Lote en proceso', 16,  1 ) 
      
	  DECLARE @Respuesta Table (
					ErrorNumber		INT,
					ErrorSeverity	INT,
					ErrorState		INT,
					ErrorProcedure  VARCHAR(1000),
					ErrorLine		INT,
					ErrorMessage	VARCHAR(1000)
					)

					
			    SET @pJson =	'{' +
							dbo.CF_Json_ParsearVariable('Id_Tipo_Lote', 1, 'INT') +  
							'}'
				INSERT INTO @Respuesta			
			    EXEC @UltError = CPJU_Tri_Parar @pJson

				SET @Mensaje = 'Error when calling CPJU_Tri_Parar ' + @pJson
	            IF @UltError <> 0 RAISERROR (@Mensaje, 16,  1 ) 					
					
		

	  SELECT @Flag_Agru_Cli_Ref = Flag_Agru_Cli_Ref FROM Contratos_Tipos WHERE Id_Tipo_Con = @pId_Tipo_Cont

	  CREATE TABLE #CONTRATOS_PROCESAR  (
				ID_CONTRATO INT,
				ID_TIEMPO CHAR(3) )
				

				
		SET @SqlSelect = 'SELECT O.ID_CONTRATO,ISNULL(O.ID_TIEMPO,'''')'

		IF @pFiltrarCantCont > 0 
		   SET @SqlSelect = 'SELECT TOP ' + CAST(@pFiltrarCantCont AS VARCHAR(10)) + '  O.ID_CONTRATO,ISNULL(O.ID_TIEMPO,'''')'

		SET @SqlFrom = 'FROM Contratos O,Clientes C'

		SET @SqlWhere = '  WHERE O.Id_Tipo_Con = ' + CAST(@pId_Tipo_Cont AS VARCHAR(10)) + '
							 AND O.Id_Cliente = C.Id_Cliente 
							 AND C.Activo = 1  AND O.Activo = 1
							 AND ( O.Fecha_Hasta >= '''+ CONVERT(VARCHAR(8),@pFecha_Desde+1,112) +'''
								 OR O.Fecha_Hasta IS NULL)
 							 AND O.Fecha_Desde < '''+ CONVERT(VARCHAR(8),@pFecha_Hasta+1,112) +'''
							 AND (O.Fecha_Cob_Hasta < '''+ CONVERT(VARCHAR(8),@pFecha_Hasta+1,112) +'''
								 OR O.Fecha_Cob_Hasta IS NULL)
							 AND (EXISTS (SELECT P.Id_Contrato FROM Contratos_Prod P WHERE P.Id_Contrato = O.Id_Contrato 
											   AND ISNULL(P.Flag_Facturable,0) <> 0 )
							     OR (EXISTS (SELECT 1 FROM Contratos_Tipos_Prod CT WHERE CT.Id_Tipo_Con = O.Id_Tipo_Con ))) '
											    		   

		 IF	@Flag_Agru_Cli_Ref <> 0 
    		SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND ISNULL(C.Id_Cliente_Ref,0) = 0'

		 IF	@pFiltrarCondPago <> 0 
    		SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND C.Id_Cond_Pago IN (SELECT CP.PTR FROM TagFile_ CP WHERE CP.USR = ' + CAST(@pId_Usuario AS VARCHAR(10)) + ' AND CP.TBL = 150)'
 
		 IF	@pFiltrarTipoCbte <> 0 
			SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND O.Id_tipo_cbte IN (SELECT CT.POS FROM TagFilePos_ CT WHERE CT.USR = ' + CAST(@pId_Usuario AS VARCHAR(10)) + ' AND CT.TBL = 120)'

		 IF	@pFiltrarCliente <> 0 
			SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND C.ID_CLIENTE IN (SELECT CP.PTR FROM TagFile_ CP WHERE CP.USR = ' + CAST(@pId_Usuario AS VARCHAR(10)) + ' AND CP.TBL = 400)'

		 IF	@pFiltrarTarjeta <> 0 
	 		SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND ( ISNULL(O.Id_Tarjeta,'') IN (SELECT TAR.POS FROM TagFilePos_ TAR WHERE TAR.USR = ' + CAST(@pId_Usuario AS VARCHAR(10)) + ' AND TAR.TBL = 210)
															OR ISNULL(C.Id_Tarjeta,'') IN (SELECT TAR.POS FROM TagFilePos_ TAR WHERE TAR.USR = ' + CAST(@pId_Usuario AS VARCHAR(10)) + ' AND TAR.TBL = 210) )'

		 IF @pRefacturar  <> 1 													
		    SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND O.ID_Contrato NOT IN (SELECT ID_Contrato  FROM Z_CONTRATOS_FACTURADOS P WHERE P.ID_Contrato = O.ID_Contrato)'
   

		SET  @SqlGroup	= 'ORDER BY O.ID_CLIENTE'

		SET @Sql = @SqlSelect +' '+ @SqlFrom + ' ' + @SqlWhere + ' ' + @SqlGroup
		IF @pModoDebug<> 0 PRINT @Sql

	
		INSERT INTO Cbtes_Lotes (Lote,Fecha,Descripcion,Id_Lote_Tipo,Flag_enProceso,Fecha_Inicio,Fecha_Desde,Fecha_Hasta,Observacion,Id_Tipo_Con)
			VALUES (@pLote,@pFecha,@pDescripcion,@pId_Lote_Tipo,1,GETDATE(),@pFecha_Desde,@pFecha_Hasta,@Sql,@pId_Tipo_Cont)
			

	    IF OBJECT_ID (N'Z_CONTRATOS_FACTURADOS', N'U') IS NOT NULL 
		BEGIN
			DROP TABLE Z_CONTRATOS_FACTURADOS
		END

 	    SELECT ISNULL(I.Id_Cliente,C.ID_CLIENTE) As Id_Cliente, i.Id_Producto, Isnull(c.Id_Contrato,0) As Id_Contrato, count(*) As Cantidad
 	            Into Z_CONTRATOS_FACTURADOS
				FROM Cbtes_Items i, Cbtes c , Cbtes_Tipos T, Contratos O
						WHERE c.id_trans = i.id_trans 
                                 AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
								 AND C.Id_Contrato = O.Id_Contrato
                                 AND ((c.Comprobante_Nro = 0 AND c.Id_Estado_Cbte = 3) 
							      or  (c.Id_Estado_Cbte <> 0 and c.Id_Estado_Cbte <> 3))
                                 AND (T.Compromete_Factura = 1
 								 OR T.Compromete_Remitos = 1)
                                 AND DATEPART(yy,i.Fecha_QA) = DATEPART(yy,@pFecha_QA) 
                                 AND DATEPART(mm,i.Fecha_QA) = DATEPART(mm,@pFecha_QA) 
								 AND O.Id_Tipo_Con = @pId_Tipo_Cont
								 group by ISNULL(I.Id_Cliente,C.ID_CLIENTE) , i.Id_Producto	, c.Id_Contrato 


        CREATE NONCLUSTERED INDEX [IX_CONT_FACT_Cli]
                ON [dbo].Z_CONTRATOS_FACTURADOS (Id_Cliente,Id_producto)
                 
        CREATE NONCLUSTERED INDEX [IX_CONT_FACT_Cont]
                ON [dbo].Z_CONTRATOS_FACTURADOS (Id_Contrato) 

		IF OBJECT_ID (N'Z_Productos_Facturados', N'U') IS NOT NULL 
		BEGIN
			DROP TABLE Z_Productos_Facturados
		END

		SELECT L.Id_Cliente, I.Id_Producto
				INTO Z_Productos_Facturados
				FROM
				Clientes L, Cbtes_Items I, Cbtes C, Cbtes_Tipos CT
				WHERE L.Id_Cliente = I.Id_Cliente
				AND I.Id_Trans = C.Id_Trans 
				AND C.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
				AND C.Id_Estado_Cbte NOT IN (0,3)
				AND CT.Compromete_Factura = 1
				AND DATEPART(yy,I.Fecha_QA) = DATEPART(yy,@pFecha_QA) 
                AND DATEPART(mm,I.Fecha_QA) = DATEPART(mm,@pFecha_QA) 
				GROUP BY L.Id_Cliente, I.Id_Producto

		 CREATE NONCLUSTERED INDEX [IX_FACT_Prod_Cli]
                ON Z_Productos_Facturados (Id_Cliente,Id_producto)

		INSERT INTO #CONTRATOS_PROCESAR
		   EXEC(@sql)

		DECLARE Cur_Facturar_Contratos CURSOR FOR
				   SELECT Id_Contrato,Id_Tiempo FROM #CONTRATOS_PROCESAR 

		OPEN Cur_Facturar_Contratos 
		FETCH NEXT FROM Cur_Facturar_Contratos INTO @Id_Contrato,@Id_Tiempo
		WHILE @@FETCH_STATUS=0
		BEGIN

			SET @pJson =	'{' +
							dbo.CF_Json_ParsearVariable('FlagUsarTrans', @pFlagUsarTrans, 'TINYINT') + ',' +
							dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'TINYINT') + ',' +
							dbo.CF_Json_ParsearVariable('Omitir_Resultado_OK', 1, 'TINYINT') + ',' +		
							dbo.CF_Json_ParsearVariable('Refacturar', @pRefacturar, 'TINYINT') + ',' +
							dbo.CF_Json_ParsearVariable('Incl_Cbtes_Cero', @pIncl_Cbtes_Cero, 'TINYINT') + ',' +
						    dbo.CF_Json_ParsearVariable('Id_Tiempo', @Id_Tiempo, 'CHAR(3)') + ',' +
							dbo.CF_Json_ParsearVariable('Id_Contrato', @Id_Contrato, 'INT') + ',' +
							dbo.CF_Json_ParsearVariable('Id_Usuario', @pId_Usuario, 'SMALLINT') + ',' +
							dbo.CF_Json_ParsearVariable('Fecha', @pFecha, 'DATETIME') + ',' +
							dbo.CF_Json_ParsearVariable('Lote', @pLote, 'VARCHAR(20)') + ',' +
							dbo.CF_Json_ParsearVariable('Flag_Tabla_Temp', 1, 'SMALLINT') + ',' +
							dbo.CF_Json_ParsearVariable('Fecha_QA', @pFecha_QA, 'DATETIME') + ',' +
							dbo.CF_Json_ParsearVariable('Fecha_Venc', @pFecha_Venc, 'DATETIME') + ',' +
				   			dbo.CF_Json_ParsearVariable('Fecha_Rem_Desde', @pFecha_Rem_Desde, 'DATETIME') + ',' +
						    dbo.CF_Json_ParsearVariable('Fecha_Rem_Hasta', @pFecha_Rem_Hasta, 'DATETIME') +
							'}'

				
			    EXEC @UltError = CPJ_Contrato_Facturar @pJson

				SET @Mensaje = 'Error when calling CPJ_Contrato_Facturar ' + @pJson
	            IF @UltError <> 0 RAISERROR (@Mensaje, 16,  1 ) 

 			    FETCH NEXT FROM Cur_Facturar_Contratos INTO @Id_Contrato,@Id_Tiempo
				IF @pModoDebug <> 0 
				   BEGIN
						PRINT '@@FETCH_STATUS: ' + CONVERT(VARCHAR(20),@@FETCH_STATUS)
						PRINT '@Id_Contrato: ' + CONVERT(VARCHAR(20),@Id_Contrato)
						PRINT '@UltError: ' + CONVERT(VARCHAR(20),@UltError)
						PRINT 'CPJ_Contrato_Facturar ' + CONVERT(VARCHAR(4000), @pJson )
				   END
		END
		CLOSE Cur_Facturar_Contratos
		DEALLOCATE Cur_Facturar_Contratos

		DROP TABLE #CONTRATOS_PROCESAR

	 	DROP TABLE Z_CONTRATOS_FACTURADOS
	 	DROP TABLE Z_Productos_Facturados

		UPDATE Cbtes_Lotes SET	Cantidad = (SELECT COUNT(*) FROM Cbtes WHERE Lote = @pLote) ,
								Importe =  (SELECT SUM(Imp_Total) FROM Cbtes WHERE Lote = @pLote),
								Fecha_Finalizacion = GETDATE(),
								Flag_enProceso = 0
				WHERE Lote = @pLote
				
		SET @pJson =	'{' +
							dbo.CF_Json_ParsearVariable('Id_Tipo_Lote', 1, 'INT') +  
							'}'
							
		EXEC @UltError = CPJU_Tri_Prender @pJson

		SET @Mensaje = 'Error when calling CPJU_Tri_Prender ' + @pJson
		IF @UltError <> 0 RAISERROR (@Mensaje, 16,  1 ) 					

		SET @Segundos = (SELECT DATEDIFF(s,Fecha_Inicio,Fecha_Finalizacion) FROM CBTES_LOTES WHERE LOTE = @pLote) 
		SET @Mensaje = 'Minutos Transcurridos: ' + CONVERT(VARCHAR(10),(@Segundos / 60 )  ) + ' ( ' + CONVERT(VARCHAR(10),(@Segundos)) +' segundos).'
 
		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage

END TRY  


BEGIN CATCH  
    IF EXISTS(SELECT * FROM @RESPUESTA)
	   SELECT * FROM @RESPUESTA
	    
    EXECUTE usp_GetErrorInfo
	
	UPDATE Cbtes_Lotes SET	Cantidad = (SELECT COUNT(*) FROM Cbtes WHERE Lote = @pLote) ,
							Importe =  (SELECT SUM(Imp_Total) FROM Cbtes WHERE Lote = @pLote),
							Fecha_Finalizacion = GETDATE(),
							Flag_enProceso = 0
			WHERE Lote = @pLote

			IF (SELECT CURSOR_STATUS('global','Cur_Facturar_Contratos') ) = -1
			   DEALLOCATE curContratoGenerarCbtes_ItemsXRemitosPropiosTr		 

			IF (SELECT CURSOR_STATUS('global','Cur_Facturar_Contratos') ) = 1
			BEGIN
			   CLOSE Cur_Facturar_Contratos
			   DEALLOCATE Cur_Facturar_Contratos		 
			END


	RETURN 9999
END CATCH

RETURN 0



