SET @Param = '{' +
			'"Lote":"viac4",' +
			'"Fecha":"20231001",' +
			'"Descripcion":"viac4",' +
			'"Id_Lote_Tipo":"1",' + 
			'"Fecha_Desde":"20231001",' +
			'"Fecha_Hasta":"20231031"' +
