BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Ped_Generar'
		PRINT 'Parametros:'
		PRINT 'pFlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans)  + '. pId_Usuario: ' + CONVERT(VARCHAR(10), @pId_Usuario) + '. pLote: ' + @pLote + '. pFecha: ' + CONVERT(VARCHAR(10), @pFecha, 103) + '. pFechaVence: ' + CONVERT(VARCHAR(10), @pFechaVence, 103) +  '. pId_Cliente: ' + CONVERT(VARCHAR(10), @pId_Cliente) + '. pId_Tipo_Cbte: ' + @pId_Tipo_Cbte + '. pId_Cond_Pago: ' + CONVERT(VARCHAR(10), @pId_Cond_Pago) + '. pId_Moneda: ' + @pId_Moneda + '. pCotizacion: ' + CONVERT(VARCHAR(10), @pCotizacion)
		PRINT 'pId_Contrato: ' + CONVERT(VARCHAR(10), @pId_Contrato)  + '. pNro_Auto_Trib: ' + @pNro_Auto_Trib + '. @pCai_Vence: ' + CONVERT(VARCHAR(10), @pCai_Vence, 103) + '. pId_Periodo_Caja: ' + CONVERT(VARCHAR(10), @pId_Periodo_Caja) + '. pImporte: ' + CONVERT(VARCHAR(10), @pImporte)
	END
	
	/*===================================================================*/


	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Inserta en Transacciones.'
	END
	
	IF(@pId_Trans = 0)
	BEGIN
		SET @pId_Trans		= ISNULL((SELECT MAX(Id_Trans) FROM Transacciones), 0) + 1
		INSERT INTO Transacciones 
		(Id_Trans,		Descripcion,						Fecha_Mov,
		Id_Usuario) 
		VALUES
		(@pId_Trans,	'Apertura CPJ_Transacciones_Abrir', GETDATE(), 
		@pId_Usuario)
	END


	/*===================================================================*/


	IF(@pId_Cliente = 0)  RAISERROR ('Id_Cliente can not be zero.', 16,  1 ) 
	IF(@pId_Tipo_Cbte = '') RAISERROR ('Id_Tipo_Cbte can not be blank.', 16,  1 ) 

		
	/*===================================================================*/
	
	IF(@pId_Usuario = 0)
	BEGIN
		SET @pId_Usuario = -1
	END
	
	IF(@pId_Moneda = '')
	BEGIN
		SET @pId_Moneda = dbo.CF_xParam('Moneda_Nacional')
	END

	IF(@pCotizacion = 0)
	BEGIN
		SET @pCotizacion = 1
	END
	
	IF(@pLote <> '')
	BEGIN
		SET @Flag_Lote	= 1
	END
	ELSE
	BEGIN
		SET @Flag_Lote	= 0
	END
	
	/*===================================================================*/

	SET @pFecha				= (SELECT CONVERT(DATE, @pFecha))
    SET @Id_Estado_Cbte		= 0  --siempre comienza en carga

	/*===================================================================*/

	SELECT  @Id_Sucursal		= ISNULL(Id_Sucursal, 0),
			@Cbte_Grupo			= ISNULL(Cbte_Grupo, 0),
			@Compromete_Factura = ISNULL(Compromete_Factura, 0),
			@Comprobante_Nro	= ISNULL(Prox_Nro, 0)
	FROM Cbtes_Tipos 
	WHERE 
	Id_Tipo_Cbte = @pId_Tipo_Cbte
	
	IF (@pNumerar_Cbte=1)
	BEGIN
		UPDATE Cbtes_Tipos SET Prox_Nro=@Comprobante_Nro+1 WHERE 	Id_Tipo_Cbte = @pId_Tipo_Cbte
	END
	ELSE
	BEGIN
		SET @Comprobante_Nro	= 0 /*En Carga*/
	END
	/*===================================================================*/

	SELECT 	@Destinatario	= ISNULL(Razon_Social, Apellido + ', ' + Nombre),
			@Id_Pais		= ISNULL(Id_Pais_Cob, ''),
			@Id_Provincia	= ISNULL(Id_Provincia_Cob, ''),
			@Id_Localidad	= ISNULL(Id_Localidad_Cob, 0),
			@Cuit			= ISNULL(Cuit, ''),
			@Doc_Nro		= ISNULL(Doc_Nro, 0),
			@Id_Iva			= ISNULL(Id_Iva, ''),
			@Email			= ISNULL(Email, ''),
			@Id_Lista		= ISNULL(Id_Lista_Precio, 0),
			@Porc_Bonificacion = ISNULL(Bonif, 0),
			@Id_Cliente_Ref	= ISNULL(Id_Cliente_Ref, 0),
			@Id_Concepto	= ISNULL(Id_Concepto, 0)
	FROM Clientes
	WHERE
	Id_Cliente = @pId_Cliente

	--13/07/2021 Agregado
	SELECT
	@Id_Imp_Fiscal = ISNULL(Id_Imp_Fiscal, '')
	FROM Iva
	WHERE
	Id_Iva = @Id_Iva
	--FIN 13/07/2021 Agregado


	--25/01/2021 Agregado 
	IF(@Id_Localidad = 0)
	BEGIN
		SET @Id_Provincia = ''
		SET @Id_Pais = ''
	END
	--FIN 25/01/2021 Agregado 

	--13/07/2021 Modificado - 04/05/2021	Agregado	
	IF(@Id_Imp_Fiscal = 'F' /*Consumidor Final*/)
	BEGIN
		SET @Cuit = 0
	END
	ELSE
	BEGIN
		IF ((@Cuit = '' OR @Cuit = '0') AND @Doc_Nro > 0)
		BEGIN
			SET @Cuit = CONVERT(VARCHAR(19), @Doc_Nro)
		END
	END
	--FIN 13/07/2021 Modificado - 04/05/2021	Agregado

	/*===================================================================*/
	IF @pId_Contrato <> 0
	BEGIN
		SELECT @Id_Lista_Contrato = Id_Lista_Precio FROM Contratos WHERE Id_Contrato = @pId_Contrato
		IF ISNULL(@Id_Lista_Contrato,0) <> 0 SET @Id_Lista = @Id_Lista_Contrato
	END
	IF @Bonif_Contrato <> 0
	   SET @Porc_Bonificacion = @Bonif_Contrato
	   
	/*===================================================================*/

	--Valido el deposito fisico y logico --20211007

	-- Valido si me pasan depositos
	IF(@pId_Dep_Fisico <> '')
	BEGIN
		SET @Id_Dep_Fisico = @pId_Dep_Fisico
	END

	--10/06/2021 Agregado
	IF(@pId_Dep_Logico <> '')
	BEGIN
		SET @Id_Dep_Logico = @pId_Dep_Logico
	END

	IF(@Id_Dep_Logico='' OR @Id_Dep_Fisico='')
	BEGIN
		/*Valido el deposito de cbtes_tipos */
		SELECT  
		@Id_Dep_Fisico	= ISNULL(Id_Deposito_Fisico, ''),
		@Id_Dep_Logico	= ISNULL(Id_Deposito_Log, '')
		FROM Cbtes_Tipos 
		WHERE 
		Id_Tipo_Cbte = @pId_Tipo_Cbte

	END

	IF(@Id_Dep_Logico='')
	BEGIN
		/*Valido el deposito de empresas_suc */
		SELECT
		@Id_Dep_Fisico	= ISNULL(Id_Deposito_Fisico, ''),
		@Id_Dep_Logico	= ISNULL(Id_Deposito_Log, '')
		FROM Empresas_Suc WHERE Id_Sucursal in (SELECT Id_Sucursal
		FROM Cbtes_Tipos 
		WHERE 
		Id_Tipo_Cbte = @pId_Tipo_Cbte)
	END

	
	IF(@Id_Dep_Logico='')
	BEGIN
		/*Valido el deposito de clientes */
		SELECT
		@Id_Dep_Fisico	= ISNULL(Id_Dep_Fisico, ''),
		@Id_Dep_Logico	= ISNULL(Id_Dep_Logico, '')
		FROM Clientes
		WHERE
		Id_Cliente = @pId_Cliente
	END
	


	/*===================================================================*/

	IF(@pId_Lista_Precio!='') SET @Id_Lista=@pId_Lista_Precio

	--SET @Comprobante_Nro	= 0 /*En Carga*/
	SET @Importe			= 0 /*En Carga*/
	SET @Importe_Con_Signo	= @Importe * @Compromete_Factura
	SET @Plazo_Venc			= ISNULL((SELECT ISNULL(Plazo_Venc, 0) FROM Cbtes_Cond_Pago WHERE Id_Cond_Pago = @pId_Cond_Pago), 0)
	SET @Periodo_Iva		= @pFecha
	SET @Periodo			= @pFecha
	SET @Imp_Total			= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Saldo				= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Gravado		= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Neto			= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Exento			= 0 /*Hay que actualizarlo luego de grabar los items*/
		
	/*TO-DO: De aca para abajo por ahora por Default*/
	SET @Id_Taller			= ''
	SET @Id_Proceso			= ''
	SET @Id_Proveedor		= 0
	SET @Signo				= 0
	SET	@Porc_DescFin		= 0
	SET @Porc_DescEspecial	= 0
	SET @Porc_Iva			= dbo.CF_xParam('Tasa_Iva_1')
	SET @Porc_Iva2			= dbo.CF_xParam('Tasa_Iva_2')
	SET @Imp_DescEspecial	= 0
	SET @Imp_DescFin		= 0
	SET @Imp_Bonificacion	= 0
	SET @Imp_Iva			= 0
	SET @Imp_Iva2			= 0
	SET @Imp_Percepcion_IB	= 0
	SET @Imp_Percepcion_Iva = 0
	SET @Bultos				= 0
	SET @NroImpresion		= 0
	SET @Exportado			= 0
	SET @Dir_Entrega		= ''
	SET @Porc_Iva3			= dbo.CF_xParam('Tasa_Iva_3')
	SET @Imp_Gravado2		= 0
	SET @Imp_Gravado3		= 0
	SET @Imp_NoGravado		= 0
	SET @Imp_IVA3			= 0
	SET @Imp_Percep			= 0
	SET @Id_Cond_Pago_Item	= 0
	SET @Id_Tipo_Reten		= ''
	SET @Cant_Cuotas		= 1
	SET @Id_Producto		= NULL
	SET @Id_Formula			= NULL
	SET @Cantidad			= 0
	SET @Id_Transportista	= 0
	SET @Cant_Batch			= 0
	SET @Fecha_Perm_Embar	= NULL
	SET @Saldo_Iva_Recup	= 0
	SET @Suc_Destina		= 0
	SET @Id_Asiento			= 0
	SET @Id_Valor			= 0
	SET @Cai				= 0	
	SET @Des_Anio			= 0
	SET @Des_Aduana			= ''
	SET @Des_Destina		= ''
	SET @Des_Nro			= 0
	SET @Des_Verif			= ''
	
	IF(@pId_Cobrador <> '')
	BEGIN
		SET @Id_Cobrador		= @pId_Cobrador
	END
	ELSE
	BEGIN
		SET @Id_Cobrador		= (SELECT ISNULL(Id_Cobrador, '') FROM Clientes WHERE Id_Cliente = @pId_Cliente)
	END

	SET @Remito_Nro			= ''
	SET @Pedido_Nro			= ''
	SET @Id_Tarjeta			= ''
	SET @Tarjeta_Nro		= ''
	SET @Cantidad_Saldo		= 0
	SET @Saldo_Anterior		= 0
	SET @NRO_DJAI			= ''
	SET @Cantidad_Equiv		= 0
	SET @Id_Trans_Origen	= @pId_Trans_Origen
	SET @Id_Sede_Origen		= 0
	SET @Patente_Transporte = ''
	SET @Patente_Transporte_Acoplado = ''
	SET @Porc_Bonificacion	= 0
	SET @Fecha_Estimada		= NULL
	SET @Persona_Recibe		= ''
	SET @Id_Vendedor		= ''
	SET @Nro_Perm_Embarque	= ''
	SET @Id_Puerto			= ''
	SET @Id_Cond_Vta		= ''
	SET @Cbte_Nro_Externo	= @pCbte_Nro_Externo
	SET @Nota_Part1			= ''
	SET @Nota_Part2			= ''
	SET @Id_Centro_Costo	= ''
	SET @Id_Camp			= 0
	SET @Id_Estado_Proceso	= @pId_Estado_Proceso

	
	INSERT INTO Cbtes
	(Id_Trans,			Id_Empresa,			Id_Sucursal,
	Id_Tipo_Cbte,		Cbte_Grupo,			Comprobante_Nro,
	Id_Cliente,			Id_Taller,			Id_Proceso,
	Id_Proveedor,		Signo,				Id_Estado_Cbte,
	Fecha,				Id_Dep_Fisico,		Id_Dep_Logico,
	Porc_DescEspecial,	Porc_DescFin,		Porc_Bonificacion,
	Porc_Iva,			Porc_Iva2,			Imp_Neto,
	Imp_DescEspecial,	Imp_DescFin,		Imp_Bonificacion,
	Imp_Gravado,		Imp_Exento,			Imp_IVA,
	Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
	Imp_Total,			Bultos,				NroImpresion,
	Exportado,			Id_Usuario,			Fecha_Estimada,
	Dir_Entrega,		Id_Pais,			Id_Provincia,
	Id_Localidad,		Persona_Recibe,		Porc_Iva3,
	Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
	Imp_IVA3,			Imp_Percep,			Saldo,
	Periodo_Iva,		Periodo,			Fecha_Venc,
	Observacion,		Id_Cond_Pago_Item,	Id_Cond_Pago,
	Id_Tipo_Reten,		Cant_Cuotas,		Id_Producto,
	Id_Formula,			Cantidad,			Id_Vendedor,
	Id_Transportista,	Id_Lista,			Id_Moneda,
	Cotizacion,			Destinatario,		Cuit,
	Id_Iva,				Cant_Batch,			Nro_Perm_Embarque,
	Fecha_Perm_Embar,	Saldo_Iva_Recup,	Lote,
	Suc_Destina,		Id_Puerto,			Id_Cond_Vta,
	Cbte_Nro_Externo,	Nota_Part1,			Nota_Part2,
	Id_Asiento,			Id_Centro_Costo,	Id_Valor,
	Cai,				Cai_Vence,			Des_Anio,
	Des_Aduana,			Des_Destina,		Des_Nro,
	Des_Verif,			Id_Contrato,		Id_Cobrador,
	Nro_Auto_Trib,		Id_Camp,			Remito_Nro,
	Pedido_Nro,			Id_Tarjeta,			Tarjeta_Nro,
	Cantidad_Saldo,		Saldo_Anterior,		NRO_DJAI,
	Cantidad_Equiv,		Id_Trans_Origen,	Id_Sede_Origen,
	Email,				Patente_Transporte,	Patente_Transporte_Acoplado,
	Flag_Lote,			Id_Cliente_Ref,		Id_Estado_Proceso)
	VALUES
	(@pId_Trans,		@Id_Empresa,		@Id_Sucursal,
	@pId_Tipo_Cbte,		@Cbte_Grupo,		@Comprobante_Nro,
	@pId_Cliente,		@Id_Taller,			@Id_Proceso,
	@Id_Proveedor,		@Signo,				@Id_Estado_Cbte,
	@pFecha,			@Id_Dep_Fisico,		@Id_Dep_Logico,
	@Porc_DescEspecial,	@Porc_DescFin,		@Porc_Bonificacion,
	@Porc_Iva,			@Porc_Iva2,			@Imp_Neto,
	@Imp_DescEspecial,	@Imp_DescFin,		@Imp_Bonificacion,
	@Imp_Gravado,		@Imp_Exento,		@Imp_IVA,
	@Imp_IVA2,			@Imp_Percepcion_IB,	@Imp_Percepcion_Iva,
	@Imp_Total,			@Bultos,			@NroImpresion,
	@Exportado,			@pId_Usuario,		@Fecha_Estimada,
	@Dir_Entrega,		@Id_Pais,			@Id_Provincia,
	@Id_Localidad,		@Persona_Recibe,	@Porc_Iva3,
	@Imp_Gravado2,		@Imp_Gravado3,		@Imp_NoGravado,
	@Imp_IVA3,			@Imp_Percep,		@Saldo,
	@Periodo_Iva,		@Periodo,			@pFechaVence,
	@pObservacion,		@Id_Cond_Pago_Item,	@pId_Cond_Pago,
	@Id_Tipo_Reten,		@Cant_Cuotas,		@Id_Producto,
	@Id_Formula,		@Cantidad,			@Id_Vendedor,
	@Id_Transportista,	@Id_Lista,			@pId_Moneda,
	@pCotizacion,		@Destinatario,		@Cuit,
	@Id_Iva,			@Cant_Batch,		@Nro_Perm_Embarque,
	@Fecha_Perm_Embar,	@Saldo_Iva_Recup,	@pLote,
	@Suc_Destina,		@Id_Puerto,			@Id_Cond_Vta,
	@Cbte_Nro_Externo,	@Nota_Part1,		@Nota_Part2,
	@Id_Asiento,		@Id_Centro_Costo,	@Id_Valor,
	@Cai,				@pCai_Vence,		@Des_Anio,
	@Des_Aduana,		@Des_Destina,		@Des_Nro,
	@Des_Verif,			@pId_Contrato,		@Id_Cobrador,
	@pNro_Auto_Trib,	@Id_Camp,			@Remito_Nro,
	@Pedido_Nro,		@Id_Tarjeta,		@Tarjeta_Nro,
	@Cantidad_Saldo,	@Saldo_Anterior,	@Nro_DJAI,
	@Cantidad_Equiv,	@Id_Trans_Origen,	@Id_Sede_Origen,
	@Email,				@Patente_Transporte,@Patente_Transporte_Acoplado,
	@Flag_Lote,			@Id_Cliente_Ref,	@Id_Estado_Proceso)

	/*===================================================================*/
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	
	
	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
								dbo.CF_Json_ParsearVariable('id_cliente', @pId_Cliente, 'INT')  + ',' +
								dbo.CF_Json_ParsearVariable('id_tipo_cbte', @pId_Tipo_Cbte, 'VARCHAR') +
								'}'
								
	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,@pId_Trans		AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Ped_Generar'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE dbo.CPJ_Cbtes_Ped_Generar_Item		@pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*
VERSIONES:
12/07/2022: Por pedido de Victor Cantidad_Equiv (que antes era cero) sea = cantidad
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Trans				INT
DECLARE @pId_Producto			VARCHAR(14)
DECLARE @pCantidad				DECIMAL(15,5)
DECLARE @pFecha_QA				DATETIME
DECLARE @pFecha_Venc			DATETIME
DECLARE @pId_Cliente			INT
DECLARE @pBonif					DECIMAL(5,2)
DECLARE @pPorc_Iva				DECIMAL(5,2)
DECLARE @pPrecio_Grav			DECIMAL(15,5)
DECLARE @pPrecio_Exen			DECIMAL(15,5)
DECLARE @pId_Tiempo             CHAR(3)
DECLARE @pRefacturar            TINYINT
DECLARE @pFlag_Tabla_Temp       TINYINT
DECLARE @pLote					VARCHAR(20)
DECLARE @pFecha_Entrega			DATETIME
DECLARE @pCosto_GF				DECIMAL(15,5)
DECLARE @pCosto_MO				DECIMAL(15,5)
DECLARE @pRedondeo_Imp_Final	TINYINT

SET @pFlag_Tabla_Temp		    = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Tabla_Temp')), 0)
SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Producto				= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), 0)
SET @pCantidad					= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Cantidad')), 0)
SET @pFecha_QA					= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_QA'))
SET @pFecha_Venc				= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Venc'))
SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pBonif						= ISNULL(CONVERT(DECIMAL(5,2), dbo.CF_JSON_VALUE(@pJson,'Bonif')), 0)
SET @pPorc_Iva					= ISNULL(CONVERT(DECIMAL(5,2), dbo.CF_JSON_VALUE(@pJson,'Porc_Iva')), 0)
SET @pPrecio_Grav 				= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Precio_Grav')), 0)
SET @pPrecio_Exen				= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Precio_Exen')), 0)
SET @pId_Tiempo	            	= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Id_Tiempo')), '')
SET @pRefacturar		        = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Refacturar')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pLote						= ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Lote')), '')
SET @pFecha_Entrega				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Entrega')), '19000101')
SET @pCosto_GF					= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Costo_GF')), 0)
SET @pCosto_MO					= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Costo_MO')), 0)
SET @pRedondeo_Imp_Final		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Redondeo_Imp_Final')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Item 					SMALLINT
DECLARE @Id_Estado_Cbte 		SMALLINT
DECLARE @Calle 					CHAR(5)
DECLARE @Columna 				CHAR(5)
DECLARE @Fila 					CHAR(5)
DECLARE @Bultos 				DECIMAL(15, 5)
DECLARE @Despacho 				VARCHAR(100)
DECLARE @Serie 					VARCHAR(100)
DECLARE @Millas 				INT
DECLARE @Cantidad_Saldo 		DECIMAL(15, 5)
DECLARE @Imp_Gravado 			DECIMAL(12, 2)
DECLARE @Imp_Exento 			DECIMAL(12, 2)
DECLARE @Analisis 				VARCHAR(30)
DECLARE @Flag_QA 				CHAR(1)
DECLARE @Descripcion_producto 	VARCHAR(100)
DECLARE @Id_Unidad_Medida 		CHAR(4)
DECLARE @Imp_Final				DECIMAL(15,5)
DECLARE @Costo 					DECIMAL(15, 5)
DECLARE @Imp_Iva 				DECIMAL(12, 2)
DECLARE @Id_Costo 				INT
DECLARE @Id_Tarea 				SMALLINT
DECLARE @Fecha_Caducidad 		DATETIME
DECLARE @Id_Pais 				CHAR(3)
DECLARE @Id_Usuario 			SMALLINT
DECLARE @Cantidad_Equiv 		DECIMAL(15, 5)
DECLARE @Costo_MO 				DECIMAL(15, 5)
DECLARE @Costo_GF 				DECIMAL(15, 5)
DECLARE @Id_Cond_Pago 			SMALLINT
DECLARE @Fecha_Proceso 			DATETIME
DECLARE @Id_Balanza 			CHAR(10)
DECLARE @Orden 					SMALLINT
DECLARE @Flag_NoImp_Factura 	TINYINT
DECLARE @Nro_Tag 				VARCHAR(30)
DECLARE @Fecha_Elaboracion 		DATETIME
DECLARE @Costo_Comparativo 		DECIMAL(13, 4)
DECLARE @Porc_Imp_Int 			DECIMAL(5, 2)
DECLARE @Id_Cta_Banco 			SMALLINT
DECLARE @Flag_Existe_Trans		TINYINT
DECLARE @Flag_Existe_Cliente	TINYINT
DECLARE @Flag_Existe_Producto	TINYINT
DECLARE @Observacion			VARCHAR(8000)
DECLARE @Id_Lista_Precio		SMALLINT
DECLARE @Precio_Gravado_Producto DECIMAL(13, 4)
DECLARE @Precio					DECIMAL(15,5)
DECLARE @Item_Facturado         SMALLINT
DECLARE @Costo_Rentabilidad		DECIMAL(14,4)
/*FIN Declaracion Variables Locales*/


BEGIN TRY
 
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Ped_Generar_Item'
		PRINT 'Parametros:'
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + ' Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans) + ' Id_Producto: ' + @pId_Producto + ' Cantidad: ' + CONVERT(VARCHAR(10), @pCantidad) + ' Fecha_QA: ' + CONVERT(VARCHAR(10), @pFecha_QA, 103) + ' Fecha_Venc: ' + CONVERT(VARCHAR(10), @pFecha_Venc, 103) + ' Id_Cliente: ' + CONVERT(VARCHAR(10), @pId_Cliente) + ' Bonif: ' + CONVERT(VARCHAR(10), @pBonif) + ' Porc_Iva: ' + CONVERT(VARCHAR(10), @pPorc_Iva) + ' Precio_Grav: ' + CONVERT(VARCHAR(25), @pPrecio_Grav) + ' Precio_Exent: ' + CONVERT(VARCHAR(25), @pPrecio_Exen) 
	END

	/*===================================================================*/
    IF @pFlag_Tabla_Temp = 1  
	    SET @pId_Trans	= 0
	  ELSE
    	IF(@pId_Trans = 0)		RAISERROR ('Id_Trans can not be zero.', 16,  1 ) 

	IF(@pId_Cliente = 0)	RAISERROR ('Id_Cliente can not be zero.', 16,  1 ) 
	IF(@pId_Producto = '')	RAISERROR ('Id_Producto can not be blank.', 16,  1 ) 
    Set @Item_Facturado = 0
	IF @pRefacturar = 0 
	   	SET @Item_Facturado =  ( SELECT dbo.CFJ_Producto_Facturado  ('{ "Id_Cliente":"' + CONVERT(VARCHAR(15), @pId_Cliente) + '",' 
	                                                              + ' "id_producto":"' + CONVERT(VARCHAR(15), @pId_Producto) + '",'
																  + ' "Id_Tiempo":"' + CONVERT(VARCHAR(15), @pId_Tiempo) + '",'
																  + ' "Fecha":"' + CONVERT(VARCHAR(15), @pFecha_QA , 112 ) + '",'
																  + ' "Flag_Tabla_Temp":"' + CONVERT(VARCHAR(1), @pFlag_Tabla_Temp ) + '",'
															      + ' "Refacturar":"' + CONVERT(VARCHAR(5), @pRefacturar) + '"}'))

    IF (@pRefacturar = 0 AND @Item_Facturado <> 0)
	    BEGIN
		     IF @pFlagUsarTrans <> 0 COMMIT


				/*===================================================================*/	

				SET @rtaMsjStored		=	'{' +
											dbo.CF_Json_ParsearVariable('id_trans', ISNULL(@pId_Trans,0), 'INT')  + ',' +
											dbo.CF_Json_ParsearVariable('item', ISNULL(@Item,0), 'SMALLINT')  + ',' +
											dbo.CF_Json_ParsearVariable('id_producto', ISNULL(@pId_Producto,''), 'VARCHAR')  + ',' +
											dbo.CF_Json_ParsearVariable('imp_final', ISNULL(@Imp_Final,0), 'DECIMAL') +
											'}'

				SELECT	 0				AS ErrorNumber 
						,0				AS ErrorSeverity  
						,0				AS ErrorState 
						,0				AS ErrorProcedure  
						,0				AS ErrorLine		
						,@rtaMsjStored	AS ErrorMessage

			   RETURN 0
	    END


	/*************************************************************************************************/

	SELECT  @Id_Estado_Cbte	= ISNULL(Id_Estado_Cbte, 0),
			@pLote			= ISNULL(Lote, ''),
			@Id_Usuario		= ISNULL(Id_Usuario, '-1')
	FROM Cbtes
	WHERE 
	Id_Trans = @pId_Trans

	/*************************************************************************************************/

	SELECT  @Calle					= ISNULL(Calle, ''),
			@Columna				= ISNULL(Columna, ''),
			@Fila					= ISNULL(Fila, ''),
			@Despacho				= ISNULL(Despacho, ''),
			@Descripcion_producto	= ISNULL(Descripcion_Resumida, ''),
			@Id_Unidad_Medida		= ISNULL(Id_Unidad_Medida, ''),
			@Costo					= ISNULL(Costo, 0),
			@Costo_MO				= ISNULL(Costo_Rentabilidad, 0),
			@Id_Cond_Pago			= ISNULL(Id_Cond_Pago, 0),
			@Id_Cta_Banco			= ISNULL(Id_Cta_Banco, 0),
			@Precio_Gravado_Producto = ISNULL(Precio_Gravado, 0),
			@Costo_Rentabilidad		= ISNULL(Costo_Rentabilidad, 0)
	FROM Productos
	WHERE 
	Id_Producto = @pId_Producto	
	

	/*************************************************************************************************/
    IF @pFlag_Tabla_Temp = 1  
    	SET @Item 					= (ISNULL((SELECT MAX(ISNULL(Item, 0)) FROM #ITEMS_CBTE WHERE Id_Trans = @pId_Trans), 0)) + 1
	  ELSE
     	SET @Item 					= (ISNULL((SELECT MAX(ISNULL(Item, 0)) FROM CBTES_ITEMS WHERE Id_Trans = @pId_Trans), 0)) + 1
	    
	SET @Precio					= @pPrecio_Grav + @pPrecio_Exen
	SET @pPrecio_Grav			= @Precio * (1 - (@pBonif / 100) )
	SET @pPrecio_Exen			= 0

	SET @Bultos 				= 0
	SET @Serie 					= ''
	SET @Millas 				= 0
	SET @Cantidad_Saldo 		= @pCantidad
	SET @Imp_Gravado 			= @pPrecio_Grav * @pCantidad
	SET @Imp_Exento 			= 0
	SET @Analisis 				= ''
	SET @Flag_QA 				= 'A'
	SET @Imp_Iva 				= ((@pPrecio_Grav * @pPorc_Iva) / 100)

	SET @Imp_Final				= (@Imp_Gravado + @Imp_Iva + @Imp_Exento)

	IF(@pRedondeo_Imp_Final > 0)
	BEGIN
		SET @Imp_Final				= ROUND(@Imp_Final, @pRedondeo_Imp_Final)
		SET @Imp_Iva				= @Imp_Final - @Imp_Gravado - @Imp_Exento
	END

	SET @Id_Costo 				= 0
	SET @Id_Tarea 				= 0
	SET @Fecha_Caducidad 		= NULL
	SET @Id_Pais 				= ''
	
	--SET @Cantidad_Equiv 		= 0
	SET @Cantidad_Equiv 		= @pCantidad		--12/07/2022 por pedido de Victor
	
	IF (@pCosto_MO > 0)
	BEGIN
		SET @Costo_MO 				= @pCosto_MO
	END
	ELSE
	BEGIN
		SET @Costo_MO 				= @Costo_Rentabilidad				--21/05/2021 Pedido por Victor
	END
	SET @Costo_GF 				= @pCosto_GF
	SET @Fecha_Proceso 			= NULL
	SET @Id_Balanza 			= ''
	SET @Orden 					= 0
	SET @Flag_NoImp_Factura 	= 0
	SET @Nro_Tag 				= ''
	SET @Fecha_Elaboracion 		= NULL
	SET @Costo_Comparativo 		= 0
	SET @Porc_Imp_Int 			= 0
	SET @Observacion			= ''	

	/*************************************************************************************************/

	IF (@pFecha_Entrega <> '19000101') 
	BEGIN
		UPDATE Cbtes 
		SET
		Fecha_Estimada = @pFecha_Entrega
		WHERE
		Id_Trans = @pId_Trans
	END

	/*************************************************************************************************/
    IF @pFlag_Tabla_Temp = 1 
		INSERT INTO #ITEMS_CBTE
		(Id_Trans,		Item,					Id_Producto, 
		Id_Estado_Cbte, Cantidad,				Calle, 
		Columna,		Fila,					Bultos, 
		Despacho,		Serie,					Fecha_Venc,
		Observacion,	Millas,					Cantidad_Saldo, 
		Precio_Grav,	Precio_Exen,			Imp_Gravado, 
		Imp_Exento,		Analisis,				Lote, 
		Flag_QA,		Fecha_QA,				Porc_Iva, 
		Bonif,			Descripcion_producto,	Id_Unidad_Medida, 
		Imp_Final,		Costo,					Imp_Iva, 
		Precio,			Id_Costo,				Id_Cliente,
		Id_Tarea,		Fecha_Caducidad,		Id_Pais, 
		Id_Usuario,		Cantidad_Equiv,			Costo_MO, 
		Costo_GF,		Id_Cond_Pago,			Fecha_Proceso, 
		Id_Balanza,		Orden,					Flag_NoImp_Factura, 
		Nro_Tag,		Fecha_Elaboracion,		Costo_Comparativo, 
		Porc_Imp_Int,	Id_Cta_Banco)
		VALUES
		(@pId_Trans,		@Item,					@pId_Producto, 
		@Id_Estado_Cbte,	@pCantidad,				@Calle, 
		@Columna,			@Fila,					@Bultos, 
		@Despacho,			@Serie,					@pFecha_Venc,
		@Observacion,		@Millas,				@Cantidad_Saldo, 
		@pPrecio_Grav,		@pPrecio_Exen,			@Imp_Gravado, 
		@Imp_Exento,		@Analisis,				@pLote, 
		@Flag_QA,			@pFecha_QA,				@pPorc_Iva, 
		@pBonif,			@Descripcion_producto,	@Id_Unidad_Medida, 
		@Imp_Final,			@Costo,					@Imp_Iva, 
		@Precio,			@Id_Costo,				@pId_Cliente,
		@Id_Tarea,			@Fecha_Caducidad,		@Id_Pais, 
		@Id_Usuario,		@Cantidad_Equiv,		@Costo_MO, 
		@Costo_GF,			@Id_Cond_Pago,			@Fecha_Proceso, 
		@Id_Balanza,		@Orden,					@Flag_NoImp_Factura, 
		@Nro_Tag,			@Fecha_Elaboracion,		@Costo_Comparativo, 
		@Porc_Imp_Int,		@Id_Cta_Banco)
       
      ELSE
	    
		INSERT INTO CBTES_ITEMS
		(Id_Trans,		Item,					Id_Producto, 
		Id_Estado_Cbte, Cantidad,				Calle, 
		Columna,		Fila,					Bultos, 
		Despacho,		Serie,					Fecha_Venc,
		Observacion,	Millas,					Cantidad_Saldo, 
		Precio_Grav,	Precio_Exen,			Imp_Gravado, 
		Imp_Exento,		Analisis,				Lote, 
		Flag_QA,		Fecha_QA,				Porc_Iva, 
		Bonif,			Descripcion_producto,	Id_Unidad_Medida, 
		Imp_Final,		Costo,					Imp_Iva, 
		Precio,			Id_Costo,				Id_Cliente,
		Id_Tarea,		Fecha_Caducidad,		Id_Pais, 
		Id_Usuario,		Cantidad_Equiv,			Costo_MO, 
		Costo_GF,		Id_Cond_Pago,			Fecha_Proceso, 
		Id_Balanza,		Orden,					Flag_NoImp_Factura, 
		Nro_Tag,		Fecha_Elaboracion,		Costo_Comparativo, 
		Porc_Imp_Int,	Id_Cta_Banco)
	    VALUES
		(@pId_Trans,		@Item,					@pId_Producto, 
		@Id_Estado_Cbte,	@pCantidad,				@Calle, 
		@Columna,			@Fila,					@Bultos, 
		@Despacho,			@Serie,					@pFecha_Venc,
		@Observacion,		@Millas,				@Cantidad_Saldo, 
		@pPrecio_Grav,		@pPrecio_Exen,			@Imp_Gravado, 
		@Imp_Exento,		@Analisis,				@pLote, 
		@Flag_QA,			@pFecha_QA,				@pPorc_Iva, 
		@pBonif,			@Descripcion_producto,	@Id_Unidad_Medida, 
		@Imp_Final,			@Costo,					@Imp_Iva, 
		@Precio,			@Id_Costo,				@pId_Cliente,
		@Id_Tarea,			@Fecha_Caducidad,		@Id_Pais, 
		@Id_Usuario,		@Cantidad_Equiv,		@Costo_MO, 
		@Costo_GF,			@Id_Cond_Pago,			@Fecha_Proceso, 
		@Id_Balanza,		@Orden,					@Flag_NoImp_Factura, 
		@Nro_Tag,			@Fecha_Elaboracion,		@Costo_Comparativo, 
		@Porc_Imp_Int,		@Id_Cta_Banco)

	/*===================================================================*/
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	

	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
								dbo.CF_Json_ParsearVariable('item',@Item, 'SMALLINT')  + ',' +
								dbo.CF_Json_ParsearVariable('id_producto', @pId_Producto, 'VARCHAR')  + ',' +
								dbo.CF_Json_ParsearVariable('imp_final',@Imp_Final, 'DECIMAL') +
								'}'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Ped_Generar_Item'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Pres_Generar] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON

DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Trans				INT
DECLARE @pId_Tipo_Cbte			CHAR(4)
DECLARE @pFecha					DATETIME
DECLARE @pFecha_Venc			DATETIME
DECLARE @pId_Cliente			INT
DECLARE @pId_Vendedor			VARCHAR(20)	
DECLARE @pId_Cond_Pago			SMALLINT
DECLARE @pId_Centro_Costos		CHAR(10)
DECLARE @pCotizacion			DECIMAL(12,2)
DECLARE @pImporte				DECIMAL(20,2)
DECLARE @pId_Sucursal			VARCHAR(25)	
DECLARE @pComprobante_Nro		SMALLINT
DECLARE @pId_Lista_Precio		INT	
DECLARE @pOmitir_Resultado_OK	TINYINT		

SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pId_Tipo_Cbte			= ISNULL(CONVERT(CHAR(4), dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Cbte')), '')
SET @pFecha					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')),'19000101')
SET @pFecha_Venc			= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Venc'))
SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Cond_Pago			= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Cond_Pago')), '')
SET @pId_Centro_Costos		= ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Centro_Costo')), '')
SET @pCotizacion			= ISNULL(CONVERT(DECIMAL(12,4), dbo.CF_JSON_VALUE(@pJson,'Cotizacion')), 1)
SET @pId_Sucursal			= ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Id_Sucursal')), 0)
SET @pId_Vendedor			= ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Id_Vendedor')), 0)
SET @pImporte				= ISNULL(CONVERT(DECIMAL(20,2), dbo.CF_JSON_VALUE(@pJson,'Importe')), 0)
SET @pId_Lista_Precio		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Lista_Precio')), 0)
SET @pOmitir_Resultado_OK	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Resultado_OK')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/


/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored					INT
DECLARE @rtaMsjStored					VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Empresa						SMALLINT
DECLARE @Id_Sucursal					SMALLINT
DECLARE @Cbte_Grupo						INT
DECLARE @Comprobante_Nro				INT
DECLARE @Id_Taller						VARCHAR(10)
DECLARE @Id_Proceso						VARCHAR(10)
DECLARE @Id_Proveedor					INT
DECLARE @Signo							SMALLINT
DECLARE @Id_Estado_Cbte					SMALLINT
DECLARE @Id_Dep_Fisico					CHAR(3)
DECLARE @Id_Dep_Logico					CHAR(3)
DECLARE @Porc_DescEspecial				DECIMAL(5, 2)
DECLARE @Porc_DescFin					DECIMAL(5, 2)
DECLARE @Porc_Iva						DECIMAL(5, 2)
DECLARE @Porc_Iva2						DECIMAL(5, 2)
DECLARE @Imp_Neto						DECIMAL(12, 2)
DECLARE @Imp_DescEspecial				DECIMAL(12, 2)
DECLARE @Imp_DescFin					DECIMAL(12, 2)
DECLARE @Imp_Bonificacion				DECIMAL(12, 2)
DECLARE @Imp_Gravado					DECIMAL(12, 2)
DECLARE @Imp_Exento						DECIMAL(12, 2)
DECLARE @Imp_IVA						DECIMAL(12, 2)
DECLARE @Imp_IVA2						DECIMAL(12, 2)
DECLARE @Imp_Percepcion_IB				DECIMAL(12, 2)
DECLARE @Imp_Percepcion_Iva				DECIMAL(12, 2)
DECLARE @Imp_Total						DECIMAL(12, 2)
DECLARE @Bultos							SMALLINT
DECLARE @NroImpresion					INT
DECLARE @Exportado						TINYINT
DECLARE @Dir_Entrega					VARCHAR(255)
DECLARE @Id_Pais						CHAR(3)
DECLARE @Id_Provincia					CHAR(3)
DECLARE @Id_Localidad					INT
DECLARE @Porc_Iva3						DECIMAL(5, 2)
DECLARE @Imp_Gravado2					DECIMAL(12, 2)
DECLARE @Imp_Gravado3					DECIMAL(12, 2)
DECLARE @Imp_NoGravado					DECIMAL(12, 2)
DECLARE @Imp_IVA3						DECIMAL(12, 2)
DECLARE @Imp_Percep						DECIMAL(12, 2)
DECLARE @Saldo							DECIMAL(12, 2)
DECLARE @Periodo_Iva					DATETIME
DECLARE @Periodo						DATETIME
DECLARE @Id_Cond_Pago_Item				TINYINT
DECLARE @Id_Tipo_Reten					VARCHAR(10)
DECLARE @Cant_Cuotas					SMALLINT
DECLARE @Id_Producto					VARCHAR(14)
DECLARE @Id_Formula						VARCHAR(15)
DECLARE @Cantidad						DECIMAL(12, 4)
DECLARE @Id_Transportista				INT
DECLARE @Destinatario					VARCHAR(100)
DECLARE @Cuit							VARCHAR(19)
DECLARE @Doc_Nro						BIGINT
DECLARE @Id_Iva							CHAR(3)
DECLARE @Cant_Batch						SMALLINT
DECLARE @Fecha_Perm_Embar				DATETIME
DECLARE @Saldo_Iva_Recup				DECIMAL(12, 2)
DECLARE @Suc_Destina					SMALLINT
DECLARE @Id_Asiento						INT
DECLARE @Id_Valor						INT
DECLARE @Cai							DECIMAL(14, 0)
DECLARE @Des_Anio						TINYINT
DECLARE @Des_Aduana						CHAR(3)
DECLARE @Des_Destina					CHAR(4)
DECLARE @Des_Nro						INT
DECLARE @Des_Verif						CHAR(1)
DECLARE @Id_Cobrador					VARCHAR(10)
DECLARE @Remito_Nro						VARCHAR(25)
DECLARE @Pedido_Nro						VARCHAR(25)
DECLARE @Id_Tarjeta						VARCHAR(11)
DECLARE @Tarjeta_Nro					VARCHAR(25)
DECLARE @Cantidad_Saldo					DECIMAL(12, 4)
DECLARE @Saldo_Anterior					DECIMAL(12, 2)
DECLARE @NRO_DJAI						VARCHAR(30)
DECLARE @Cantidad_Equiv					DECIMAL(12, 4)
DECLARE @Id_Trans_Origen				INT
DECLARE @Id_Sede_Origen					SMALLINT
DECLARE @Email							VARCHAR(8000)
DECLARE @Patente_Transporte				VARCHAR(7)
DECLARE @Patente_Transporte_Acoplado	VARCHAR(7)
DECLARE @Plazo_Venc						SMALLINT
DECLARE @Porc_Bonificacion				DECIMAL(5,2)
DECLARE @Fecha_Estimada					DATETIME
DECLARE @Persona_Recibe					VARCHAR(100)
DECLARE @Observacion					VARCHAR(8000)
DECLARE @Id_Lista						SMALLINT
DECLARE @Nro_Perm_Embarque				VARCHAR(20)
DECLARE @Id_Puerto						CHAR(3)
DECLARE @Id_Cond_Vta					CHAR(10)
DECLARE @Cbte_Nro_Externo				VARCHAR(25)
DECLARE @Nota_Part1						VARCHAR(100)
DECLARE @Nota_Part2						VARCHAR(100)
DECLARE @Id_Camp						SMALLINT
DECLARE @Flag_Lote						TINYINT
DECLARE @Compromete_Presupuesto			SMALLINT
DECLARE @Descrip_Cbte					VARCHAR(100)
DECLARE @Importe						DECIMAL(12, 2)
DECLARE @Importe_Con_Signo				DECIMAL(12, 2)
DECLARE @Id_Cliente_Ref					INT
DECLARE @Renglon_Nro					SMALLINT
DECLARE @Id_Estado_Mov_Caja				INT
DECLARE @Descripcion					VARCHAR(100)
DECLARE @Id_Tipo_Mov_Caja				SMALLINT
DECLARE @Id_Concepto					INT
DECLARE @Item							SMALLINT
DECLARE @Id_Estado_Concepto				SMALLINT
DECLARE @Flag_Existe_Cbte_Lote			TINYINT

/*Fin de Declaraciones Variables Locales */



BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	/*===================================================================================================================================================================*/

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Inserta en Transacciones.'
	END
	
	IF(@pId_Trans = 0)
	BEGIN
		SET @pId_Trans = ISNULL((SELECT MAX(Id_Trans) FROM Transacciones), 0) + 1

		INSERT INTO Transacciones (Id_Trans, Descripcion, Fecha_Mov, Id_Usuario) 
						   VALUES (@pId_Trans,	'CPJ_Transacciones_Abrir', GETDATE(), -1)
	END

	IF(@pId_Cliente = 0)  RAISERROR ('El codigo de cliente no puede ser cero', 16,  1 ) 
	IF(@pId_Tipo_Cbte = '') RAISERROR ('El tipo de comprobante no puede estar vacio.', 16,  1 )


	/*===================================================================*/

	IF(@pCotizacion = 0)
	BEGIN
		SET @pCotizacion = 1
	END
	
	SET @Flag_Lote	= 0
	SET @pFecha				= (SELECT CONVERT(DATE, @pFecha))
    SET @Id_Estado_Cbte		= 0

	/*===================================================================*/

	SELECT  @Id_Sucursal			= ISNULL(Id_Sucursal, 0),
			@Cbte_Grupo				= ISNULL(Cbte_Grupo, 0),
			@Compromete_Presupuesto = ISNULL(Compromete_Presup, 0),
			@Id_Estado_Cbte			= ISNULL(Id_Estado_Cbte,0),
			@Comprobante_Nro		= ISNULL(Prox_Nro,1)
	FROM Cbtes_Tipos 
	WHERE Id_Tipo_Cbte = @pId_Tipo_Cbte

	IF(@Compromete_Presupuesto NOT IN (1,-1)) RAISERROR ('El tipo de comprobante no corresponde a presupuestos.', 16, 1) 
	
	/*===================================================================*/

	SELECT 	@Destinatario	= ISNULL(Razon_Social, Apellido + ', ' + Nombre),
			@Id_Pais		= ISNULL(Id_Pais_Cob, ''),
			@Id_Provincia	= ISNULL(Id_Provincia_Cob, ''),
			@Id_Localidad	= ISNULL(Id_Localidad_Cob, 0),
			@Cuit			= ISNULL(Cuit, ''),
			@Doc_Nro		= ISNULL(Doc_Nro, 0),
			@Id_Iva			= ISNULL(Id_Iva, ''),
			@Id_Dep_Fisico	= ISNULL(Id_Dep_Fisico, ''),
			@Id_Dep_Logico	= ISNULL(Id_Dep_Logico, ''),
			@Email			= ISNULL(Email, ''),
			@Id_Lista		= ISNULL(Id_Lista_Precio, 0),
			@Porc_Bonificacion = ISNULL(Bonif, 0),
			@Id_Cliente_Ref	= ISNULL(Id_Cliente_Ref, 0),
			@Id_Concepto	= ISNULL(Id_Concepto, 0),
			@Id_Cobrador	= ISNULL(Id_Cobrador,0)
	FROM Clientes
	WHERE Id_Cliente = @pId_Cliente

	IF(@pId_Lista_Precio <> 0)
	BEGIN
		SET @Id_Lista = @pId_Lista_Precio
	END

	IF(@Id_Localidad = 0)
	BEGIN
		SET @Id_Provincia = ''
		SET @Id_Pais = ''
	END
	
	IF ((@Cuit = '' OR @Cuit = '0') AND @Doc_Nro > 0)
	BEGIN
		SET @Cuit = CONVERT(VARCHAR(19), @Doc_Nro)
	END

	SET @Importe			= 0 /*En Carga*/
	SET @Importe_Con_Signo	= @Importe * @Compromete_Presupuesto
	SET @Plazo_Venc			= ISNULL((SELECT ISNULL(Plazo_Venc, 0) FROM Cbtes_Cond_Pago WHERE Id_Cond_Pago = @pId_Cond_Pago), 0)
	SET @Periodo_Iva		= @pFecha
	SET @Periodo			= @pFecha
	SET @Imp_Total			= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Saldo				= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Gravado		= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Neto			= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Exento			= 0 /*Hay que actualizarlo luego de grabar los items*/
		
	/*TO-DO: De aca para abajo por ahora por Default*/
	SET @Id_Taller			= ''
	SET @Id_Proceso			= ''
	SET @Id_Proveedor		= 0
	SET @Signo				= 0
	SET	@Porc_DescFin		= 0
	SET @Porc_DescEspecial	= 0
	SET @Porc_Iva			= dbo.CF_xParam('Tasa_Iva_1')
	SET @Porc_Iva2			= dbo.CF_xParam('Tasa_Iva_2')
	SET @Imp_DescEspecial	= 0
	SET @Imp_DescFin		= 0
	SET @Imp_Bonificacion	= 0
	SET @Imp_Iva			= 0
	SET @Imp_Iva2			= 0
	SET @Imp_Percepcion_IB	= 0
	SET @Imp_Percepcion_Iva = 0
	SET @Bultos				= 0
	SET @NroImpresion		= 0
	SET @Exportado			= 0
	SET @Dir_Entrega		= ''
	SET @Porc_Iva3			= dbo.CF_xParam('Tasa_Iva_3')
	SET @Imp_Gravado2		= 0
	SET @Imp_Gravado3		= 0
	SET @Imp_NoGravado		= 0
	SET @Imp_IVA3			= 0
	SET @Imp_Percep			= 0
	SET @Id_Cond_Pago_Item	= 0
	SET @Id_Tipo_Reten		= ''
	SET @Cant_Cuotas		= 1
	SET @Id_Producto		= NULL
	SET @Id_Formula			= NULL
	SET @Cantidad			= 0
	SET @Id_Transportista	= 0
	SET @Cant_Batch			= 0
	SET @Fecha_Perm_Embar	= NULL
	SET @Saldo_Iva_Recup	= 0
	SET @Suc_Destina		= 0
	SET @Id_Asiento			= 0
	SET @Id_Valor			= 0
	SET @Cai				= 0	
	SET @Des_Anio			= 0
	SET @Des_Aduana			= ''
	SET @Des_Destina		= ''
	SET @Des_Nro			= 0
	SET @Des_Verif			= ''
	SET @Remito_Nro			= ''
	SET @Id_Tarjeta			= ''
	SET @Tarjeta_Nro		= ''
	SET @Cantidad_Saldo		= 0
	SET @Saldo_Anterior		= 0
	SET @NRO_DJAI			= ''
	SET @Cantidad_Equiv		= 0
	SET @Id_Trans_Origen	= 0
	SET @Id_Sede_Origen		= 0
	SET @Patente_Transporte = ''
	SET @Patente_Transporte_Acoplado = ''
	SET @Porc_Bonificacion	= 0
	SET @Fecha_Estimada		= NULL
	SET @Persona_Recibe		= ''
	SET @Observacion		= ''
	SET @Nro_Perm_Embarque	= ''
	SET @Id_Puerto			= ''
	SET @Id_Cond_Vta		= ''
	SET @Nota_Part1			= ''
	SET @Nota_Part2			= ''
	SET @Id_Camp			= 0

	
	INSERT INTO Cbtes
	(Id_Trans,			Id_Empresa,			Id_Sucursal,
	Id_Tipo_Cbte,		Cbte_Grupo,			Comprobante_Nro,
	Id_Cliente,			Id_Taller,			Id_Proceso,
	Id_Proveedor,		Signo,				Id_Estado_Cbte,
	Fecha,				Id_Dep_Fisico,		Id_Dep_Logico,
	Porc_DescEspecial,	Porc_DescFin,		Porc_Bonificacion,
	Porc_Iva,			Porc_Iva2,			Imp_Neto,
	Imp_DescEspecial,	Imp_DescFin,		Imp_Bonificacion,
	Imp_Gravado,		Imp_Exento,			Imp_IVA,
	Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
	Imp_Total,			Bultos,				NroImpresion,
	Exportado,			Id_Usuario,			Fecha_Estimada,
	Dir_Entrega,		Id_Pais,			Id_Provincia,
	Id_Localidad,		Persona_Recibe,		Porc_Iva3,
	Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
	Imp_IVA3,			Imp_Percep,			Saldo,
	Periodo_Iva,		Periodo,			Fecha_Venc,
	Observacion,		Id_Cond_Pago_Item,	Id_Cond_Pago,
	Id_Tipo_Reten,		Cant_Cuotas,		Id_Producto,
	Id_Formula,			Cantidad,			Id_Vendedor,
	Id_Transportista,	Id_Lista,			Id_Moneda,
	Cotizacion,			Destinatario,		Cuit,
	Id_Iva,				Cant_Batch,			Nro_Perm_Embarque,
	Fecha_Perm_Embar,	Saldo_Iva_Recup,	Lote,
	Suc_Destina,		Id_Puerto,			Id_Cond_Vta,
	Cbte_Nro_Externo,	Nota_Part1,			Nota_Part2,
	Id_Asiento,			Id_Centro_Costo,	Id_Valor,
	Cai,				Cai_Vence,			Des_Anio,
	Des_Aduana,			Des_Destina,		Des_Nro,
	Des_Verif,			Id_Contrato,		Id_Cobrador,
	Nro_Auto_Trib,		Id_Camp,			Remito_Nro,
	Pedido_Nro,			Id_Tarjeta,			Tarjeta_Nro,
	Cantidad_Saldo,		Saldo_Anterior,		NRO_DJAI,
	Cantidad_Equiv,		Id_Trans_Origen,	Id_Sede_Origen,
	Email,				Patente_Transporte,	Patente_Transporte_Acoplado,
	Flag_Lote,			Id_Cliente_Ref)
	VALUES
	(@pId_Trans,		@Id_Empresa,		@Id_Sucursal,
	@pId_Tipo_Cbte,		@Cbte_Grupo,		@Comprobante_Nro,
	@pId_Cliente,		@Id_Taller,			@Id_Proceso,
	@Id_Proveedor,		@Signo,				@Id_Estado_Cbte,
	@pFecha,			@Id_Dep_Fisico,		@Id_Dep_Logico,
	@Porc_DescEspecial,	@Porc_DescFin,		@Porc_Bonificacion,
	@Porc_Iva,			@Porc_Iva2,			@Imp_Neto,
	@Imp_DescEspecial,	@Imp_DescFin,		@Imp_Bonificacion,
	@Imp_Gravado,		@Imp_Exento,		@Imp_IVA,
	@Imp_IVA2,			@Imp_Percepcion_IB,	@Imp_Percepcion_Iva,
	@Imp_Total,			@Bultos,			@NroImpresion,
	@Exportado,			-1,		@Fecha_Estimada,
	@Dir_Entrega,		@Id_Pais,			@Id_Provincia,
	@Id_Localidad,		@Persona_Recibe,	@Porc_Iva3,
	@Imp_Gravado2,		@Imp_Gravado3,		@Imp_NoGravado,
	@Imp_IVA3,			@Imp_Percep,		@Saldo,
	@Periodo_Iva,		@Periodo,			@pFecha_Venc,
	@Observacion,		@Id_Cond_Pago_Item,	@pId_Cond_Pago,
	@Id_Tipo_Reten,		@Cant_Cuotas,		@Id_Producto,
	@Id_Formula,		@Cantidad,			@pId_Vendedor,
	@Id_Transportista,	@Id_Lista,			'PES',
	@pCotizacion,		@Destinatario,		@Cuit,
	@Id_Iva,			@Cant_Batch,		@Nro_Perm_Embarque,
	@Fecha_Perm_Embar,	@Saldo_Iva_Recup,	'',
	@Suc_Destina,		@Id_Puerto,			@Id_Cond_Vta,
	@Cbte_Nro_Externo,	@Nota_Part1,		@Nota_Part2,
	@Id_Asiento,		@pId_Centro_Costos,	@Id_Valor,
	@Cai,				'19000101',		@Des_Anio,
	@Des_Aduana,		@Des_Destina,		@Des_Nro,
	@Des_Verif,			0,		@Id_Cobrador,
	'',	@Id_Camp,			@Remito_Nro,
	@Pedido_Nro,		@Id_Tarjeta,		@Tarjeta_Nro,
	@Cantidad_Saldo,	@Saldo_Anterior,	@Nro_DJAI,
	@Cantidad_Equiv,	@Id_Trans_Origen,	@Id_Sede_Origen,
	@Email,				@Patente_Transporte,@Patente_Transporte_Acoplado,
	@Flag_Lote,			@Id_Cliente_Ref)

	/*===================================================================*/
	
	IF @pId_Cond_Pago NOT IN (0, 1)
	BEGIN
		SET @Descrip_Cbte = dbo.CF_Descrip_Cbte(@pId_Trans)
		
		INSERT INTO Clientes_CtaCte 
		(Id_Trans,		Nro_Cuota,		Id_Empresa,
		Id_Cliente,		Fecha,			Fecha_Vence,
		Descripcion,	Importe,		Id_Estado_Cbte,
		Observacion,	Id_Trans_Origen,Nro_Cuota_Origen,
		Id_Moneda,		Saldo,			Nro_FacCre)
		VALUES
		(@pId_Trans,	1,					NULL,
		@pId_Cliente,	@pFecha,			@pFecha_Venc,
		@Descrip_Cbte,	@Importe_Con_Signo, @Id_Estado_Cbte,
		'',				0,					0,
		'pes',	@Importe_Con_Signo,	0)
	END 
	
	/*===================================================================*/

	IF(@pId_Cond_Pago = 1/*Contado*/)
	BEGIN
		SET @Renglon_Nro = 1
		SET @Id_Estado_Mov_Caja = 0 --EN CARGA
		SET @Descripcion = ISNULL((dbo.CF_Cbte_Descrip(@pId_Trans)), '')
		SET @Id_Tipo_Mov_Caja = 1 --e_Ing_Varios

		INSERT INTO dbo.Cajas_Mov
		(Id_Trans,			Renglon_Nro,	Id_Estado_Mov_Caja,
		Importe,			Descripcion,	Id_Periodo_Caja,
		Id_Tipo_Mov_Caja,	Fecha)
		VALUES
		(@pId_Trans,		@Renglon_Nro,	@Id_Estado_Mov_Caja,
		@pImporte,			@Descripcion,	0,
		@Id_Tipo_Mov_Caja,	GETDATE()/*Es con hora*/)
	END

	/*****************************************************************************/

	IF(@pId_Cond_Pago = 1/*Contado*/)
	BEGIN
		SET @Item = 1
		SET @Id_Estado_Concepto = 0
	
		INSERT INTO dbo.Cajas_Mov_Conceptos
		(Id_Trans,				Id_Concepto,			Item,
		Id_Estado_Concepto,		Importe,				Id_Periodo_Caja)
		VALUES
		(@pId_Trans,			@Id_Concepto,			@Item,
		@Id_Estado_Concepto,	@pImporte * (-1),		0)
	END	

	/*===================================================================*/
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	
	
	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_cliente', @pId_Cliente, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_tipo_cbte', @pId_Tipo_Cbte, 'VARCHAR') +
									'}'
									
		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,@pId_Trans		AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Fac_Generar'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Pres_a_Ped] @pJson VARCHAR(8000)
AS
SET NOCOUNT ON

/*Variables recibidas por par├ímetro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Usuario			SMALLINT
DECLARE @pId_Trans_Pres			INT
DECLARE @pId_Tipo_Cbte_Ped		VARCHAR(4)

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Usuario				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), -1)
SET @pId_Trans_Pres				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans_Pres')), 0)
SET @pId_Tipo_Cbte_Ped			= ISNULL(CONVERT(VARCHAR(4), dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Cbte_Ped')), 0)
/*FIN Variables recibidas por par├ímetro a traves del JSON*/

/*Declaraci├│n de Variables Locales*/
DECLARE @Id_Trans_Ped						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
DECLARE @Descripcion_Cbte					VARCHAR(80)
DECLARE @Result_Stored_Invocado				INT
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
DECLARE @Pres_Id_Estado_Cbte				SMALLINT
DECLARE @Ped_Id_Estado_Cbte					SMALLINT
DECLARE @Pres_Imp_Total						DECIMAL(20,5)
DECLARE @Id_Cliente							INT		
DECLARE @Id_Iva								CHAR(5)
DECLARE @Id_Vendedor						VARCHAR(10)
DECLARE @Observacion						VARCHAR(8000)
DECLARE @Id_Cond_Pago						SMALLINT
DECLARE @Cbte_Nro_Externo					VARCHAR(15)
DECLARE @Id_Cond_Vta						VARCHAR(10)
DECLARE @Id_Moneda							CHAR(3)
DECLARE @Cotizacion							INT
DECLARE @Id_Centro_Costo					INT
DECLARE @Email								VARCHAR(8000)	
DECLARE @Id_Puerto							CHAR(5)
/*FIN Declaraci├│n de Variables Locales*/

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a CPJ_Cbtes_Pres_a_Ped'
	PRINT 'Parametros: FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + '. ModoDebug: ' + CONVERT(VARCHAR(10), @pModoDebug)
	PRINT '@pId_Usuario: ' + CONVERT(VARCHAR(10), @pId_Usuario)
	PRINT '@pId_Trans_Pres: ' + CONVERT(VARCHAR(10), @pId_Trans_Pres) +'. @pId_Tipo_Cbte_Ped: ' + @pId_Tipo_Cbte_Ped
END

BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pId_Trans_Pres = 0)  RAISERROR ('@pId_Trans_Pres no puede ser cero.', 16,  1 ) 

	IF(@pId_Tipo_Cbte_Ped = '')  RAISERROR ('@pId_Tipo_Cbte_Ped no puede ser vacio.', 16,  1 ) 

	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	----Recupero Datos del Presupuesto
	SELECT
	--@Id_Cliente			= ISNULL(Id_Cliente, 0),
	--@Id_Iva				= ISNULL(Id_Iva, ''),
	--@Id_Vendedor		= ISNULL(Id_Vendedor,''),
	--@Observacion		= ISNULL(Observacion,''),
	@Id_Cond_Pago		= ISNULL(Id_Cond_Pago,10)
	--@Cbte_Nro_Externo	= ISNULL(Cbte_Nro_Externo,''),
	--@Id_Cond_Vta		= ISNULL(Id_Cond_Vta,''),
	--@Id_Moneda			= ISNULL(Id_Moneda,'PES'),
	--@Cotizacion			= ISNULL(Cotizacion,1),
	--@Id_Centro_Costo	= ISNULL(Id_Centro_Costo,''),
	--@Email				= ISNULL(Email,''),
	--@Id_Puerto			= ISNULL(Id_Puerto,'')
	FROM Cbtes
	WHERE
	Id_Trans = @pId_Trans_Pres

	SELECT 
	@Ped_Id_Estado_Cbte = ISNULL(Id_Estado_Cbte,1) 
	FROM Cbtes_Tipos 
	WHERE Id_Tipo_Cbte = @pId_Tipo_Cbte_Ped

	/*Ingreso en Transacciones*/
	SET @Id_Trans_Ped = (SELECT MAX(Id_Trans) + 1 FROM Transacciones)
	
	INSERT INTO Transacciones (Id_Trans, Fecha_Mov,	Descripcion, Id_Usuario) 
	VALUES (@Id_Trans_Ped, GETDATE(), 'Creada por CPJ_Cbtes_Pres_a_Ped', @pId_Usuario)

	/*Inserto en Cbtes*/
	SELECT * INTO #Cbte_Ped FROM Cbtes WHERE Id_Trans = @pId_Trans_Pres

	UPDATE #Cbte_Ped 
	SET 
	Id_Trans = @Id_Trans_Ped, 
	Id_Tipo_Cbte = @pId_Tipo_Cbte_Ped,
	Id_Estado_Cbte = @Ped_Id_Estado_Cbte, 
	Comprobante_Nro = (SELECT ISNULL(MAX(Comprobante_Nro),1) FROM Cbtes WHERE Id_Tipo_Cbte = @pId_Tipo_Cbte_Ped),
	Id_Trans_Origen = @pId_Trans_Pres,
	Fecha = CONVERT(DATE, GETDATE()),
	Fecha_Venc = (SELECT CONVERT(DATE, DATEADD(DAY,ISNULL(Plazo_Venc,0),GETDATE())) FROM Cbtes_Cond_Pago WHERE Id_Cond_Pago = @Id_Cond_Pago)
	
	INSERT INTO Cbtes SELECT * FROM #Cbte_Ped

	/*Inserto en Cbtes_Items*/
	SELECT * INTO #Cbtes_Items_Ped FROM Cbtes_Items WHERE Id_Trans = @pId_Trans_Pres 
	
	UPDATE #Cbtes_Items_Ped 
	SET 
	Id_Trans = @Id_Trans_Ped, 
	Flag_QA = 'A'

	INSERT INTO Cbtes_Items SELECT * FROM #Cbtes_Items_Ped

	/*Inserto en Cbtes_Items_xCampos*/
	SELECT * INTO #Cbtes_Items_xCampos_Ped FROM Cbtes_Items_xCampos WHERE Id_Trans = @pId_Trans_Pres

	UPDATE #Cbtes_Items_xCampos_Ped 
	SET 
	Id_Trans = @Id_Trans_Ped

	INSERT INTO Cbtes_Items_xCampos SELECT * FROM #Cbtes_Items_xCampos_Ped

	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	
	SET @JSON_Parametros_Stored_Invocado =	'{' +
											dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('Id_Trans', @Id_Trans_Ped, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('FlagRegenerar', 1, 'TINYINT') + 
											'}'
						
	EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Ped_Fin @JSON_Parametros_Stored_Invocado
	IF ISNULL(@Result_Stored_Invocado,0) <> 0 
	BEGIN
		RETURN 9999
	END		

	UPDATE Cbtes 
	SET
	Id_Estado_Cbte = @Ped_Id_Estado_Cbte
	WHERE Id_Trans = @Id_Trans_Ped
	AND Id_Estado_Cbte <> @Ped_Id_Estado_Cbte

	UPDATE Cbtes
	SET
	Id_Estado_Cbte = 2
	WHERE Id_Trans = @pId_Trans_Pres

	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('id_trans', @Id_Trans_Ped, 'INT') + ',' +
								dbo.CF_Json_ParsearVariable('descrip_Cbte', dbo.CF_Cbte_Descrip(@Id_Trans_Ped), 'VARCHAR') +
								'}'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage

	-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'FIN Procedimiento: CPJ_Cbtes_Pres_a_Ped'
	END

	------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  ROLLBACK

	RETURN 9999
END CATCH

RETURN 0 

--EXEC dbo.CPJ_Cbtes_Pres_a_Ped '{"FlagUsarTrans":"0","ModoDebug":"1","Id_Trans_Pres":"9063528", "Id_Tipo_Cbte_Ped":"PEDT"}'
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Prov_Aplica_Auto]  @pJson VARCHAR(8000)	 
AS

/***************************************************************************************************

	Procedimiento:      CPJ_Cbtes_Prov_Aplica_Auto
	Fecha de Creacion:  2026-03-13
	Creado por:         Gabriel Centenari
	Descripcion:        Aplica por importe iguales orden por Fecha una cta. cte. de prov. todos los cbtes en estado 1 (Pendiente)


						Flujo general:
						1) Carga lasa Facturas e @Facturas con nro de registro
						2) Carga los recibos y NC en @Pagos con nro registro
						3) Genera @Cbtes_Aplica
						4) Depende el modo muestra resultados o lo genera deFinitivamente

	Llamado por:        Boton en Proveedores Cta. Cte.

	Tablas aFectadas:   Cbtes,Cbtes_Aplica, Proveedores_CtaCte

	Usado en:           ERP

	Parametro(s):       Id_Proveedor,ModoDebug,Modo       
						Se reciben en JSON.

	Forma de uso:       EXEC CPJ_Cbtes_Prov_Aplica_Auto '{"Id_Proveedor":"71","ModoDebug":"0","Modo":"CBTES_APLICA_CERO"}'
						EXEC CPJ_Cbtes_Prov_Aplica_Auto '{"Id_Proveedor":"71","ModoDebug":"0","Modo":"APLICAR_CERO"}'

	Notas adicionales:  Modo:
                        APLICAR  ->  Generar la aplicaci¾n

                        Modo de Control que no genera nada
                        FACTURAS ->  Muestra las Facturas a aplciar

***************************************************************************************************

SUMARIO DE CAMBIOS
FECHA(yyyy-mm-dd)    Autor              Comentarios
------------------- ------------------- ------------------------------------------------------------

***************************************************************************************************/



/*Variables recibidas por parametro a traves del JSON*/

DECLARE @pId_Proveedor    INT
        ,@pModoDebug    TINYINT
        ,@pModo         VARCHAR(20)  --APLICAR - Aplicar           

SET @pId_Proveedor     = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Proveedor')), 0)
SET @pModoDebug        = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pModo             = UPPER(ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Modo')), ''))


/*FIN Variables recibidas por parametro a traves del JSON*/

SET NOCOUNT ON

/*Declaracion Variables Locales*/

DECLARE @ErrorMessage			VARCHAR(100)
		,@Id_Trans_Fac			INT
		,@Id_Trans_OP			INT
		,@Importe				DECIMAL(18,2)
		,@Fecha_OP				DATETIME
		,@Fecha_Fac				DATETIME
		,@Cli_ReF_CtaCte_Agrup	TINYINT
		,@Id_Moneda				CHAR(3)
		,@Id_Unid_Negocio		CHAR(10)
		,@Nro					INT
		,@Nro_Nuevo				INT
		,@Nro_Hasta				INT


DECLARE @Ordenado_Nro TABLE
	(
		Fecha			DATETIME,
		Id_Trans_Fac	INT,
		Id_Trans_OP	INT,
		Imp_Total		DECIMAL(18,2),
		Saldo			DECIMAL(18,2),
		Id_Moneda		CHAR(3),
		Id_Unid_Negocio CHAR(10),
		Nro				INT IDENTITY(1,1),
		Id_Trans_Aplic  INT,

		INDEX IX_OrdXXX (Fecha, Id_Trans_Fac, Id_Trans_OP)
	);

DECLARE @Facturas TABLE (
	Id_Trans INT PRIMARY KEY
	,Fecha DATETIME
	,Imp_Total DECIMAL(18,2)
	,Id_Moneda CHAR(3)
	,Id_Unid_Negocio CHAR(10)
)

DECLARE @Pagos TABLE (
	Id_Trans INT PRIMARY KEY
	,Fecha DATETIME
	,Imp_Total DECIMAL(18,2)
	,Id_Moneda CHAR(3)
	,Id_Unid_Negocio CHAR(10)
)

DECLARE @Ordenado TABLE
	(
		Fecha DATETIME,
		Id_Trans_Fac INT,
		Id_Trans_OP INT,
		Imp_Total DECIMAL(18,2),
		Saldo DECIMAL(18,2),
		Id_Moneda CHAR(3),
		Id_Unid_Negocio CHAR(10),

		INDEX IX_OrdXXX (Fecha, Id_Trans_Fac, Id_Trans_OP)
	);
DECLARE @Unid_Negocio TABLE (Id_Unid_Negocio CHAR(10))
DECLARE @Monedas TABLE (Id_Moneda CHAR(3))


DECLARE @Rec_Ceros TABLE
	(
		Fecha			DATETIME,
		Id_Trans_Fac	INT,
		Id_Trans_OP		INT,
		Imp_Total		DECIMAL(18,2),
		Saldo			DECIMAL(18,2),
		Id_Moneda		CHAR(3),
		Id_Unid_Negocio CHAR(10),
		Nro				INT,
		Id_Trans_Aplic  INT,

		INDEX IX_rECXXX (Fecha, Id_Trans_Fac, Id_Trans_OP)
	);


/*FIN Declaracion Variables Locales*/

IF NOT @pModo IN ('FACTURAS','PAGOS','CBTES_APLICA','CBTES_APLICA_CERO','FACTURAS_CTRL','PAGOS_CTRL','APLICAR','APLICAR_CERO') 
BEGIN
	SET @ErrorMessage = 'PARAMETRO INVALIDO'
	SELECT 1 AS ErrorNumber,0 AS ErrorSeverity,0 AS ErrorState,0 AS ErrorProcedure,0 AS ErrorLine,@ErrorMessage AS ErrorMessage
	RETURN 9998
END


BEGIN TRY
INSERT INTO @Facturas
SELECT F.Id_Trans,F.Fecha,F.Imp_Total,F.Id_Moneda,T.Id_Unid_Negocio 
    FROM Cbtes F
	    JOIN Cbtes_Tipos t ON F.Id_Tipo_Cbte = t.Id_Tipo_Cbte AND (t.Compromete_Compras = 1 OR t.Compromete_Pagos = -1)
	    WHERE F.Id_Estado_Cbte = 1 
	    AND F.Id_Proveedor = @pId_Proveedor


INSERT INTO @Pagos
SELECT R.Id_Trans,DATEADD(HOUR,23,R.Fecha) AS Fecha,R.Imp_Total,R.Id_Moneda,T.Id_Unid_Negocio
    FROM Cbtes R
	    JOIN Cbtes_Tipos t ON r.Id_Tipo_Cbte = t.Id_Tipo_Cbte 
		JOIN Proveedores C ON C.Id_Proveedor = r.Id_Proveedor
	    WHERE r.Id_Estado_Cbte = 1
		AND (t.Compromete_Compras = -1 OR t.Compromete_Pagos = 1)
	    AND r.Id_Proveedor = @pId_Proveedor



DECLARE @Cbtes_Aplica TABLE (Id_Trans_Fac INT, Id_Trans_OP INT, Importe DECIMAL(18,2), Fecha_Rec DATETIME)


IF @pModo = 'FACTURAS'      
BEGIN 
	SELECT * FROM @Facturas ORDER BY Id_Trans
	RETURN 0
END

IF @pModo = 'PAGOS'       
BEGIN
	SELECT * FROM @Pagos ORDER BY Id_Trans
	RETURN 0
END


IF @pModo IN ('CBTES_APLICA','APLICAR') 
BEGIN
	DECLARE Aplic CURSOR FOR SELECT Id_Trans,Fecha,Imp_Total,Id_Moneda,Id_Unid_Negocio FROM @Facturas

	OPEN Aplic
	FETCH NEXT FROM Aplic INTO @Id_Trans_Fac,@Fecha_Fac , @Importe , @Id_Moneda , @Id_Unid_Negocio
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Id_Trans_OP = 0
		SELECT TOP 1 @Id_Trans_OP = R.Id_Trans , @Fecha_OP = R.Fecha FROM @Pagos R 
						WHERE R.Imp_Total = @Importe 
							AND R.Id_Moneda = @Id_Moneda
							AND R.Id_Unid_Negocio = @Id_Unid_Negocio
							AND NOT EXISTS (SELECT 1 FROM @Cbtes_Aplica A WHERE R.Id_Trans = A.Id_Trans_OP)

						ORDER BY Fecha,Id_Trans
		IF ISNULL(@Id_Trans_OP,0) != 0
		BEGIN
			IF @Fecha_OP < @Fecha_Fac SET @Fecha_OP = @Fecha_Fac
			INSERT INTO @Cbtes_Aplica (Id_Trans_Fac, Id_Trans_OP, Importe, Fecha_Rec)
				VALUES (@Id_Trans_Fac,@Id_Trans_OP,@Importe,@Fecha_OP)
		END

		FETCH NEXT FROM Aplic INTO @Id_Trans_Fac,@Fecha_Fac , @Importe , @Id_Moneda , @Id_Unid_Negocio
	END
	CLOSE Aplic
	DEALLOCATE ApliC
END

IF @pModo IN ('CBTES_APLICA_CERO','APLICAR_CERO') 
BEGIN
	INSERT INTO @Ordenado SELECT Fecha,Id_Trans,0,Imp_Total,0,Id_Moneda,Id_Unid_Negocio FROM @Facturas
	INSERT INTO @Ordenado SELECT Fecha,0,Id_Trans,Imp_Total,0,Id_Moneda,Id_Unid_Negocio FROM @Pagos

	UPDATE @Ordenado SET Id_Moneda = CONVERT(CHAR(3),dbo.CF_xParam('Moneda_Nacional')) WHERE Id_Moneda IS NULL
	UPDATE @Ordenado SET Id_Unid_Negocio = '' WHERE Id_Unid_Negocio IS NULL

	
	INSERT INTO @Unid_Negocio SELECT DISTINCT Id_Unid_Negocio FROM  @Ordenado 
	INSERT INTO @Monedas SELECT DISTINCT Id_Moneda FROM  @Ordenado 


	DECLARE Cur_UN CURSOR FOR SELECT Id_Unid_Negocio FROM @Unid_Negocio
	OPEN Cur_UN
	FETCH NEXT FROM Cur_UN INTO @Id_Unid_Negocio
	WHILE @@FETCH_STATUS = 0
	BEGIN 
		DECLARE Cur_Monedas CURSOR FOR SELECT Id_Moneda FROM @Monedas
		OPEN Cur_Monedas
		FETCH NEXT FROM Cur_Monedas INTO @Id_Moneda
		WHILE @@FETCH_STATUS = 0
		BEGIN 
			DELETE FROM @Ordenado_Nro
			DELETE FROM @Rec_Ceros

			/*Calculo el campo Saldo **********************************************************************************************************************/
			;WITH Movs AS
				(
					SELECT o.*, Mov = CASE
								WHEN o.Id_Trans_Fac <> 0 THEN  o.Imp_Total   -- Factura suma
								WHEN o.Id_Trans_OP <> 0 THEN -o.Imp_Total   -- Recibo resta
								ELSE 0
								END
					FROM @Ordenado o WHERE o.Id_Unid_Negocio = @Id_Unid_Negocio AND o.Id_Moneda = @Id_Moneda
				),
				Calc AS
				(
					SELECT 	m.*, SaldoCalc =
							SUM(m.Mov) OVER
							(
								ORDER BY
									m.Fecha,
									CASE WHEN m.Id_Trans_Fac <> 0 THEN 0 ELSE 1 END, -- mismo dÝa: primero facturas, luego recibos
									m.Id_Trans_Fac,
									m.Id_Trans_OP
								ROWS UNBOUNDED PRECEDING
							)
					FROM Movs m
				)
			UPDATE o SET o.Saldo = c.SaldoCalc FROM @Ordenado o 
				JOIN Calc c
					ON c.Fecha = o.Fecha
					AND c.Id_Trans_Fac = o.Id_Trans_Fac
					AND c.Id_Trans_OP = o.Id_Trans_OP
					AND c.Imp_Total    = o.Imp_Total
				WHERE o.Id_Unid_Negocio = @Id_Unid_Negocio AND o.Id_Moneda = @Id_Moneda;

			/*Fin Calculo el campo Saldo **********************************************************************************************************************/

			
			INSERT INTO @Ordenado_Nro (Fecha			
									   ,Id_Trans_Fac	
									   ,Id_Trans_OP	
									   ,Imp_Total		
									   ,Saldo			
									   ,Id_Moneda		
									   ,Id_Unid_Negocio)

			SELECT Fecha			
				   ,Id_Trans_Fac	
				   ,Id_Trans_OP	
				   ,Imp_Total		
				   ,Saldo			
				   ,Id_Moneda		
				   ,Id_Unid_Negocio
				FROM @Ordenado ORDER BY Fecha,Id_Trans_Fac,Id_Trans_OP

			--select * from @Ordenado_Nro

			IF NOT EXISTS(SELECT 1 FROM @Ordenado_Nro WHERE Saldo = 0)
				DELETE FROM @Ordenado_Nro

			DELETE @Ordenado_Nro WHERE Nro > (SELECT TOP 1 Nro FROM @Ordenado_Nro WHERE Saldo = 0 ORDER BY Nro DESC)
			
			--SELECT * FROM @Ordenado_Nro	

            INSERT INTO @Rec_Ceros
				SELECT * FROM @Ordenado_Nro WHERE Id_Trans_OP != 0 AND Saldo = 0 ORDER BY Nro  

			IF @pModo IN ('CBTES_APLICA','CBTES_APLICA_CERO')
               SELECT * FROM @Rec_Ceros
			

			DECLARE Cur_Aplic_Cero CURSOR FOR SELECT Id_Trans_Fac,Id_Trans_OP,Nro,Fecha FROM @Rec_Ceros
			OPEN Cur_Aplic_Cero
			FETCH NEXT FROM Cur_Aplic_Cero INTO @Id_Trans_Fac,@Id_Trans_OP,@Nro,@Fecha_OP
			WHILE @@FETCH_STATUS = 0
			BEGIN
				--SELECT * FROM @Ordenado_Nro WHERE Nro < @Nro AND Id_Trans_Aplic IS NULL 
				UPDATE @Ordenado_Nro SET Id_Trans_Aplic = @Id_Trans_OP ,Fecha = @Fecha_OP 
									WHERE Nro <= @Nro AND Id_Trans_Aplic IS NULL 
									
				FETCH NEXT FROM Cur_Aplic_Cero INTO @Id_Trans_Fac,@Id_Trans_OP,@Nro,@Fecha_OP
			END
			CLOSE Cur_Aplic_Cero
			DEALLOCATE Cur_Aplic_Cero

			
			
			IF @pModo IN ('CBTES_APLICA','CBTES_APLICA_CERO')
			   SELECT * FROM @Ordenado_Nro

            DELETE @Ordenado_Nro WHERE Id_Trans_OP = Id_Trans_Aplic AND Id_Trans_Aplic IS NOT NULL  

			

			INSERT INTO @Cbtes_Aplica
				SELECT Id_Trans_Fac,Id_Trans_Aplic,Imp_Total,Fecha FROM @Ordenado_Nro 
					WHERE Id_Trans_Fac <> 0 AND Id_Trans_Aplic IS NOT NULL ORDER BY Nro

			INSERT INTO @Cbtes_Aplica
				SELECT Id_Trans_OP,Id_Trans_Aplic,Imp_Total * -1,Fecha FROM @Ordenado_Nro 
					WHERE Id_Trans_OP <> 0 AND Id_Trans_Aplic IS NOT NULL ORDER BY Nro
            --SELECT * FROM @Cbtes_Aplica
            --RETURN  

			FETCH NEXT FROM Cur_Monedas INTO @Id_Moneda
		END
		CLOSE Cur_Monedas
		DEALLOCATE Cur_Monedas
	    
		FETCH NEXT FROM Cur_UN INTO @Id_Unid_Negocio
	END
	CLOSE Cur_UN
	DEALLOCATE Cur_UN
END

IF @pModo IN ('CBTES_APLICA','CBTES_APLICA_CERO')
BEGIN
    SELECT * FROM @Cbtes_Aplica a
	    LEFT JOIN @Facturas F ON F.Id_Trans = a.Id_Trans_Fac 
	    LEFT JOIN @Pagos R ON R.Id_Trans = a.Id_Trans_OP
        RETURN 0
END

IF @pModo = 'FACTURAS_CTRL'
BEGIN
    SELECT Id_Trans_Fac,COUNT(*) FROM @Cbtes_Aplica GROUP BY Id_Trans_Fac ORDER BY 2 DESC,1
        RETURN 0
END

IF @pModo = 'PAGOS_CTRL'
BEGIN
    SELECT Id_Trans_OP,COUNT(*) FROM @Cbtes_Aplica GROUP BY Id_Trans_OP ORDER BY 2 DESC,1
        RETURN 0
END

IF @pModo = 'APLICAR'
BEGIN
	IF  EXISTS (SELECT 1 FROM @Cbtes_Aplica)
	BEGIN
		BEGIN TRAN
		INSERT INTO Cbtes_Aplica SELECT Id_Trans_Fac,1,Id_Trans_OP,1,0,Importe,CONVERT(DATE,Fecha_Rec) FROM @Cbtes_Aplica

		UPDATE Cbtes           SET Id_Estado_Cbte = 2,Saldo = 0 FROM Cbtes c           JOIN @Cbtes_Aplica a ON c.Id_Trans = a.Id_Trans_Fac
		UPDATE Proveedores_CtaCte SET Id_Estado_Cbte = 2,Saldo = 0 FROM Proveedores_CtaCte c JOIN @Cbtes_Aplica a ON c.Id_Trans = a.Id_Trans_Fac

		UPDATE Cbtes           SET Id_Estado_Cbte = 2,Saldo = 0 FROM Cbtes r           JOIN @Cbtes_Aplica a ON r.Id_Trans = a.Id_Trans_OP
		UPDATE Proveedores_CtaCte SET Id_Estado_Cbte = 2,Saldo = 0 FROM Proveedores_CtaCte r JOIN @Cbtes_Aplica a ON r.Id_Trans = a.Id_Trans_OP
		COMMIT
    END
    SELECT @ErrorMessage = CONVERT(VARCHAR,COUNT(*)) + ' Cbtes. Aplicados ' FROM @Cbtes_Aplica
    SELECT 0 AS ErrorNumber,0 AS ErrorSeverity,0 AS ErrorState,0 AS ErrorProcedure,0 AS ErrorLine,@ErrorMessage AS ErrorMessage
    RETURN 0
END

IF @pModo = 'APLICAR_CERO'
BEGIN
	IF  EXISTS (SELECT 1 FROM @Cbtes_Aplica)
	BEGIN
		BEGIN TRAN
		INSERT INTO Cbtes_Aplica 
			SELECT Id_Trans_Fac,1,Id_Trans_OP,1,0,Importe,Fecha_Rec FROM @Cbtes_Aplica

		UPDATE Cbtes           SET Id_Estado_Cbte = 2,Saldo = 0 FROM Cbtes c           JOIN @Cbtes_Aplica a ON c.Id_Trans = a.Id_Trans_Fac
		UPDATE Proveedores_CtaCte SET Id_Estado_Cbte = 2,Saldo = 0 FROM Proveedores_CtaCte c JOIN @Cbtes_Aplica a ON c.Id_Trans = a.Id_Trans_Fac

		UPDATE Cbtes           SET Id_Estado_Cbte = 2,Saldo = 0 FROM Cbtes r           JOIN @Cbtes_Aplica a ON r.Id_Trans = a.Id_Trans_OP
		UPDATE Proveedores_CtaCte SET Id_Estado_Cbte = 2,Saldo = 0 FROM Proveedores_CtaCte r JOIN @Cbtes_Aplica a ON r.Id_Trans = a.Id_Trans_OP
		COMMIT
    END
    SELECT @ErrorMessage = CONVERT(VARCHAR,COUNT(*)) + ' Cbtes. Aplicados ' FROM @Cbtes_Aplica
    SELECT 0 AS ErrorNumber,0 AS ErrorSeverity,0 AS ErrorState,0 AS ErrorProcedure,0 AS ErrorLine,@ErrorMessage AS ErrorMessage
    RETURN 0
END

RETURN 0

END TRY
BEGIN CATCH
    EXECUTE usp_GetErrorInFo
	IF @@TRANCOUNT > 0 ROLLBACK
    RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Prov_DesAplicar]  @pJson VARCHAR(8000)	 
AS

/***************************************************************************************************

	Procedimiento:      CPJ_Cbtes_Prov_DesAplicar
	Fecha de Creacion:  2026-03-13
	Creado por:         Gabriel Centenari
	Descripcion:        Desaclica toda la cta.cte. y deja todo en pendiente , regenerando cta.cte.


	Llamado por:        Boton en Clientes Cta. Cte.

	Tablas aFectadas:   Cbtes, Cbtes_Aplica, Proveedores_CtaCte

	Usado en:           ERP

	Parametro(s):       Id_Proveedor,ModoDebug      
						Se reciben en JSON.

	Forma de uso:       EXEC CPJ_Cbtes_Prov_DesAplicar '{"Id_Proveedor":"71","ModoDebug":"0"}'


***************************************************************************************************

SUMARIO DE CAMBIOS
FECHA(yyyy-mm-dd)    Autor              Comentarios
------------------- ------------------- ------------------------------------------------------------

***************************************************************************************************/



/*Variables recibidas por parametro a traves del JSON*/

DECLARE @pId_Proveedor    INT
        ,@pModoDebug    TINYINT
     

SET @pId_Proveedor       = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Proveedor')), 0)
SET @pModoDebug        = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)

/*FIN Variables recibidas por parametro a traves del JSON*/

SET NOCOUNT ON
SET XACT_ABORT ON

/*Declaracion Variables Locales*/

DECLARE @ErrorMessage			VARCHAR(100)


/*FIN Declaracion Variables Locales*/

IF @pId_Proveedor < 2		
	RETURN 0


BEGIN TRY
	BEGIN TRAN 
 
	DELETE Cbtes_Aplica 
		FROM Cbtes C 
			JOIN Cbtes_Aplica A ON C.Id_trans = A.Id_Trans
		WHERE A.Id_Trans <> 0 
			AND C.Id_Proveedor = @pId_Proveedor


	DELETE Proveedores_CtaCte 
		FROM Cbtes C
			JOIN Proveedores_CtaCte A ON C.Id_trans = A.Id_Trans 
			JOIN Cbtes_Tipos T ON C.Id_tipo_cbte = T.Id_tipo_cbte 
		WHERE (T.Compromete_Pagos in (1,-1) OR T.Compromete_Compras IN (1,-1)) 
			AND C.Id_Estado_Cbte IN (1,2,3,4)
			AND C.Id_Proveedor = @pId_Proveedor

    UPDATE Cbtes SET Cotizacion = 1 FROM Cbtes C
			JOIN Cbtes_Tipos T ON  t.Id_Tipo_Cbte = C.Id_Tipo_Cbte
		WHERE (t.Compromete_Compras in (1,-1) AND t.Compromete_Pagos IN (1,-1))
			AND C.Id_Estado_Cbte IN (1,2,3,4)
			AND (C.Cotizacion IS NULL OR C.Cotizacion = 0)
			AND C.Id_Proveedor = @pId_Proveedor
	UPDATE Cbtes SET Saldo = C.Imp_Total, Id_Estado_Cbte = 1
		FROM Cbtes C
			JOIN Cbtes_Tipos T ON  t.Id_Tipo_Cbte = C.Id_Tipo_Cbte
		WHERE (t.Compromete_Compras in (1,-1) OR t.Compromete_Pagos IN (1,-1))
			AND C.Id_Estado_Cbte IN (1,2,3,4)
			AND C.Id_Proveedor = @pId_Proveedor

	INSERT INTO Proveedores_CtaCte (Id_Trans,Nro_Cuota,Id_Proveedor,Fecha,Fecha_Vence,Descripcion,Importe,Saldo,Id_Estado_Cbte,Id_Moneda)
	SELECT C.Id_Trans,1,@pId_Proveedor,C.Fecha,C.Fecha_Venc,dbo.CF_Cbte_Descrip(C.Id_Trans),C.Imp_Total,C.Saldo,1,C.Id_Moneda 
		FROM Cbtes C
			JOIN Cbtes_Tipos T ON t.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
		WHERE (t.Compromete_Compras = 1  Or t.Compromete_Pagos = -1)
			AND C.imp_total <> 0
			AND C.Id_Estado_Cbte = 1
			AND C.Id_Proveedor = @pId_Proveedor

	INSERT INTO Proveedores_CtaCte (Id_Trans,Nro_Cuota,Id_Proveedor,Fecha,Fecha_Vence,Descripcion,Importe,Saldo,Id_Estado_Cbte,Id_Moneda)
	SELECT C.Id_Trans,1,@pId_Proveedor,C.Fecha,C.Fecha_Venc,dbo.CF_Cbte_Descrip(C.Id_Trans),C.Imp_Total * -1,C.Saldo * -1,1,C.Id_Moneda  
		FROM Cbtes C
			JOIN Cbtes_Tipos T ON t.Id_Tipo_Cbte = C.Id_Tipo_Cbte 
		WHERE (t.Compromete_Compras = -1 Or t.Compromete_Pagos = 1)
			AND C.imp_total <> 0
			AND C.Id_Estado_Cbte = 1
			AND C.Id_Proveedor = @pId_Proveedor

	COMMIT
    SELECT @ErrorMessage = CONVERT(VARCHAR,COUNT(*)) + ' Cbtes. Procesados ' 
				FROM Proveedores_CtaCte 
				WHERE Id_Proveedor = @pId_Proveedor
					AND Importe <> 0 AND Id_Estado_Cbte = 1
    SELECT 0 AS ErrorNumber,0 AS ErrorSeverity,0 AS ErrorState,0 AS ErrorProcedure,0 AS ErrorLine,@ErrorMessage AS ErrorMessage
    RETURN 0

END TRY
BEGIN CATCH
    
	IF @@TRANCOUNT > 0 ROLLBACK
	EXECUTE usp_GetErrorInFo
    RETURN 9999
END CATCH

RETURN 0
GO


