	Id_Proveedor,		Signo,				Id_Estado_Cbte,
	Fecha,				Id_Dep_Fisico,		Id_Dep_Logico,
	Porc_DescEspecial,	Porc_DescFin,		Porc_Bonificacion,
	Porc_Iva,			Porc_Iva2,			Imp_Neto,
	Imp_DescEspecial,	Imp_DescFin,		Imp_Bonificacion,
	Imp_Gravado,		Imp_Exento,			Imp_IVA,
	Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
	Imp_Total,			Bultos,				NroImpresion,
	Exportado,			Id_Usuario,			Fecha_Estimada,
	Dir_Entrega,		Id_Pais,			Id_Provincia,
	Id_Localidad,		Persona_Recibe,		Porc_Iva3,
	Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
	Imp_IVA3,			Imp_Percep,			Saldo,
	Periodo_Iva,		Periodo,			Fecha_Venc,
	Observacion,		Id_Cond_Pago_Item,	Id_Cond_Pago,
	Id_Tipo_Reten,		Cant_Cuotas,		Id_Producto,
	Id_Formula,			Cantidad,			Id_Vendedor,
	Id_Transportista,	Id_Lista,			Id_Moneda,
	Cotizacion,			Destinatario,		Cuit,
	Id_Iva,				Cant_Batch,			Nro_Perm_Embarque,
	Fecha_Perm_Embar,	Saldo_Iva_Recup,	Lote,
	Suc_Destina,		Id_Puerto,			Id_Cond_Vta,
	Cbte_Nro_Externo,	Nota_Part1,			Nota_Part2,
	Id_Asiento,			Id_Centro_Costo,	Id_Valor,
	Cai,				Cai_Vence,			Des_Anio,
	Des_Aduana,			Des_Destina,		Des_Nro,
	Des_Verif,			Id_Contrato,		Id_Cobrador,
	Nro_Auto_Trib,		Id_Camp,			Remito_Nro,
	Pedido_Nro,			Id_Tarjeta,			Tarjeta_Nro,
	Cantidad_Saldo,		Saldo_Anterior,		NRO_DJAI,
	Cantidad_Equiv,		Id_Trans_Origen,	Id_Sede_Origen,
	Email,				Patente_Transporte,	Patente_Transporte_Acoplado,
	Flag_Lote)
	VALUES
	(@Id_Trans,			@Id_Empresa,		@Id_Sucursal,
	SUBSTRING(@pId_Tipo_Cbte,1,4),	@Cbte_Grupo,		@Comprobante_Nro,
	0,		@Id_Taller,			@Id_Proceso,
	@Id_Proveedor,		@Signo,				@Id_Estado_Cbte,
	@pFecha,			@Id_Dep_Fisico,		@Id_Dep_Logico,
	@Porc_DescEspecial,	@Porc_DescFin,		@Porc_Bonificacion,
	@Porc_Iva,			@Porc_Iva2,			@Imp_Neto,
	@Imp_DescEspecial,	@Imp_DescFin,		@Imp_Bonificacion,
	@Imp_Gravado,		@Imp_Exento,		@Imp_IVA,
	@Imp_IVA2,			@Imp_Percepcion_IB,	@Imp_Percepcion_Iva,
	@Imp_Total,			@Bultos,			@NroImpresion,
	@Exportado,			@pId_Usuario,		@Fecha_Estimada,
	@Dir_Entrega,		@Id_Pais,			@Id_Provincia,
	@Id_Localidad,		@Persona_Recibe,	@Porc_Iva3,
	@Imp_Gravado2,		@Imp_Gravado3,		@Imp_NoGravado,
	@Imp_IVA3,			@Imp_Percep,		@Saldo,
	@Periodo_Iva,		@Periodo,			@Fecha_Venc,
	@Observacion,		@Id_Cond_Pago_Item,	@Id_Cond_Pago,
	@Id_Tipo_Reten,		@Cant_Cuotas,		@Id_Producto,
	@Id_Formula,		@Cantidad,			@Id_Vendedor,
	@Id_Transportista,	@Id_Lista,			@pId_Moneda,
	@pCotizacion,		@Destinatario,		@Cuit,
	@Id_Iva,			@Cant_Batch,		@Nro_Perm_Embarque,
	@Fecha_Perm_Embar,	@Saldo_Iva_Recup,	@pLote,
	@Suc_Destina,		@Id_Puerto,			@Id_Cond_Vta,
	@Cbte_Nro_Externo,	@Nota_Part1,		@Nota_Part2,
	@Id_Asiento,		@Id_Centro_Costo,	@Id_Valor,
	@Cai,				@Cai_Vence,			@Des_Anio,
	@Des_Aduana,		@Des_Destina,		@Des_Nro,
	@Des_Verif,			0,		@Id_Cobrador,
	@Nro_Auto_Trib,		@Id_Camp,			@Remito_Nro,
	@Pedido_Nro,		@Id_Tarjeta,		@Tarjeta_Nro,
	@Cantidad_Saldo,	@Saldo_Anterior,	@Nro_DJAI,
	@Cantidad_Equiv,	@Id_Trans_Origen,	@Id_Sede_Origen,
	@Email,				@Patente_Transporte,@Patente_Transporte_Acoplado,
	@Flag_Lote)

	/*****************************************************************************/

	SET @Renglon_Nro = 1
	SET @Id_Estado_Mov_Caja = 0 --EN CARGA
	SET @Descripcion = ISNULL((dbo.CF_Cbte_Descrip(@Id_Trans)), '')
	SET @Id_Tipo_Mov_Caja = 1 --ingresos varios
	
	IF @pFecha = CONVERT(DATE,GETDATE())
		BEGIN
			SET @pFecha = GETDATE()
		END
	ELSE
		BEGIN
			SET @pFecha = DATEADD(hh,23,@pFecha)
			SET @pFecha = DATEADD(mi,59,@pFecha)
			/* cuando la fecha difiere del dia actual, set graba con ese al asl 23:59*/
		END	
	

	INSERT INTO dbo.Cajas_Mov
			(Id_Trans,			Renglon_Nro,	Id_Estado_Mov_Caja,
			Importe,			Descripcion,	Id_Periodo_Caja,
			Id_Tipo_Mov_Caja,	Fecha)
			VALUES
			(@Id_Trans,			@Renglon_Nro,	@Id_Estado_Mov_Caja,
			@pImporte,			@Descripcion,	@pId_Periodo_Caja,
			@Id_Tipo_Mov_Caja,	@pFecha)

	/*****************************************************************************/

	--SELECT * FROM CAJAS_MOV_TIPOS

	SET @Item = 1
	SET @Id_Estado_Concepto = 0
	
	
	
	INSERT INTO dbo.Cajas_Mov_Conceptos
			(Id_Trans,						Id_Concepto,			Item,
			Id_Estado_Concepto,		Importe,				Id_Periodo_Caja)
			VALUES
			(@Id_Trans,				@Id_Concepto,		@Item,
			@Id_Estado_Concepto,	@pImporte *-1 ,	@pId_Periodo_Caja)

	/*****************************************************************************/
	
	UPDATE Transacciones SET Descripcion = LTRIM(RTRIM(@Descripcion)) WHERE Id_Trans = @Id_Trans

	/*****************************************************************************/
	
	IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0
	BEGIN
		COMMIT
	END

	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @Id_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_tipo_cbte', @pId_Tipo_Cbte, 'VARCHAR') +
									'}'
									
		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,@Id_Trans		AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_OP_Varias_Generar'
	END	
	
END TRY  
BEGIN CATCH  

    EXECUTE usp_GetErrorInfo; 
	ROLLBACK
	RETURN 9999
END CATCH


RETURN 0

 /*
CPJ_Cbtes_OP_Varias_Generar '{"Id_Trans":"11270335","Numerar_Cbte":1,"Id_Tipo_Cbte":"OP15","Id_Lista_Precio":null,"Fecha":"2026-04-20 13:13:03","Ignorar_Cliente":1,"Id_Periodo_Caja":"899","FlagUsarTrans":1}'



select * from cbtes_iva
*/
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Rec_Anular] @pJson VARCHAR(8000)

AS
SET NOCOUNT ON
/*
 * LOG VERSIONES:
 * 04/12/2023: Se agrego Log de Versiones
*/

/*Declaracion Variables Json*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Trans				INT
DECLARE @pMotivoAnulacion		VARCHAR(1000)
DECLARE @pId_Usuario			SMALLINT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pMotivoAnulacion			= ISNULL(CONVERT(VARCHAR(1000), dbo.CF_JSON_VALUE(@pJson,'MotivoAnulacion')), '')
SET @pId_Usuario				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), 0)
/*Fin Declaracion Variables Json*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Flag_Existe_Usuario	TINYINT
DECLARE @Mensaje				VARCHAR(100)
/*Fin de Declaraciones Variables Locales */

BEGIN TRY
	
	IF (@pFlagUsarTrans <> 0 )
	BEGIN
		BEGIN TRAN
	END

	/*===================================================================================================================================================================*/	

	IF (@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Rec_Anular'
		PRINT 'Parametros:'	
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + ' Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans)
	END
	
	/*===================================================================================================================================================================*/

	IF(@pId_Trans = 0)
	BEGIN
		SET @rtaErrorStored = 70001 /*Transaccion no abierta*/
		
		SELECT	 @rtaErrorStored	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,''					AS ErrorMessage
			
		IF (@pFlagUsarTrans <> 0)
		BEGIN
			ROLLBACK
		END
		
		RETURN 9999
	END

	/*===================================================================================================================================================================*/

	SET @Flag_Existe_Usuario = ISNULL((SELECT 1 FROM Seg_User WHERE No = @pId_Usuario), 0)
	IF (@Flag_Existe_Usuario = 0)
	BEGIN

		SET @Mensaje = 'No existe el usuario '

		SELECT		1001			AS ErrorNumber 
					,0				AS ErrorSeverity  
					,0				AS ErrorState 
					,0				AS ErrorProcedure  
					,0				AS ErrorLine		
					,@Mensaje		AS ErrorMessage
					,0				AS Id_Trans

		IF (@pFlagUsarTrans <> 0)
		BEGIN
			ROLLBACK
		END

		RETURN 1001
	END

	/*===================================================================================================================================================================*/

	SELECT Id_Trans INTO #Trans FROM Cbtes C, Cbtes_Tipos T
		WHERE C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
		AND T.Compromete_Recibos IN (1,-1)
		AND C.Id_Trans = @pId_Trans

	UPDATE Valores SET Id_Estado_Valor = 1
		FROM Valores V, #Trans T
		WHERE T.Id_Trans  = V.Id_Trans

	UPDATE Valores_Mov SET Id_Estado_Valor = 1
		FROM Valores_Mov V, #Trans T
		WHERE T.Id_Trans  = V.Id_Trans

	UPDATE Cajas_Mov SET Id_Estado_Mov_Caja = 1
		FROM Cajas_Mov C, #Trans T
		WHERE T.Id_Trans  = C.Id_Trans
	
	UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 3 
		FROM Clientes_CtaCte C, #Trans T
		WHERE T.Id_Trans  = C.Id_Trans

	UPDATE Cbtes_Items SET Id_Estado_Cbte = 3 
		FROM Cbtes_Items C, #Trans T
		WHERE T.Id_Trans  = C.Id_Trans

	UPDATE Cbtes SET Id_Estado_Cbte = 3
					,Imp_Neto = 0
					,Imp_DescEspecial  = 0
					,Imp_DescFin  = 0
					,Imp_Bonificacion  = 0
					,Imp_Gravado  = 0
					,Imp_Exento  = 0
					,Imp_IVA  = 0
					,Imp_IVA2  = 0
					,Imp_Percepcion_IB  = 0
					,Imp_Percepcion_Iva  = 0
					,Imp_Total  = 0
					,Imp_Gravado2  = 0
					,Imp_Gravado3  = 0
					,Imp_NoGravado  = 0
					,Imp_IVA3  = 0
					,Imp_Percep  = 0
					,Saldo  = 0
					,Saldo_Iva_Recup  = 0
					,Observacion = LTRIM(RTRIM(@pMotivoAnulacion)) + 
					              CHAR(13) + CHAR(10) +
								  'Anulado por '+  CONVERT(VARCHAR(10),@pId_Usuario) +
					              CHAR(13) + CHAR(10) +
								  '---'+ 
								  CHAR(13) + CHAR(10) + 
								  LTRIM(RTRIM(CONVERT(VARCHAR(MAX),C.Observacion)))
		FROM Cbtes C, #Trans T
		WHERE T.Id_Trans  = C.Id_Trans


	IF (@pFlagUsarTrans <> 0)
	BEGIN
		COMMIT
	END

		SET @rtaMsjStored	=	'{' +
								dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT') +
								'}'

		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Rec_Anular'
	END

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF (@pFlagUsarTrans <> 0 )
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Rec_Fin] @pJson VARCHAR(8000)
AS
SET NOCOUNT ON
/*
 * LOG VERSIONES:
 * 26/06/2025: sz. Se agrego el Flag de ingresos varios
 * 25/09/2025: Por defecto el pFlag_Renumerar en 1
*/

/*Variables recibidas por parametros a traves del JSON*/
DECLARE @pFlagUsarTrans					TINYINT
DECLARE @pModoDebug						TINYINT
DECLARE @pId_Trans						INT
DECLARE @pOmitir_Resultado_OK			TINYINT
DECLARE @pFlag_Renumerar				TINYINT
DECLARE @pFlag_Ingresos_Varios			TINYINT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')),0)
SET @pOmitir_Resultado_OK		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Resultado_OK')),0)
SET @pFlag_Renumerar			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Renumerar')), 1)
SET @pFlag_Ingresos_Varios		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Ingresos_Varios')), 0)
/*FIN Variables recibidas por parametros a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
DECLARE @Result_Stored_Invocado				INT
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Cta_Contable		INT
DECLARE @Fecha					DATETIME
DECLARE @Debe					DECIMAL(12,2)
DECLARE @Haber					DECIMAL(12,2)
DECLARE @Observacion			VARCHAR(100)
DECLARE @Alias					SMALLINT
DECLARE @Id_Asiento				INT
DECLARE @Id_Centro_Costo		CHAR(10)
DECLARE @Item					SMALLINT
DECLARE @Resultado				INT
DECLARE @Descripcion_Cbte		VARCHAR(80)
DECLARE @Importe_Aplicado		DECIMAL(16,2)
DECLARE @Importe_Pago_A_Cta		DECIMAL(16,2)
DECLARE @Importe_Rec			DECIMAL(16,2)
DECLARE @Mensaje				VARCHAR(100)
/*Fin de Declaraciones Variables Locales */

BEGIN TRY
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Rec_Fin'
		PRINT 'parametros: '
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + '. Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans) 
	END
	
	IF(@pId_Trans = 0)
	BEGIN
		IF @pOmitir_Resultado_OK = 0
		BEGIN
			SET @rtaErrorStored = 70001 /*Transaccion no abierta*/
			
			SELECT	 @rtaErrorStored	AS ErrorNumber 
					,0					AS ErrorSeverity  
					,0					AS ErrorState 
					,0					AS ErrorProcedure  
					,0					AS ErrorLine		
					,''					AS ErrorMessage
		END
		
		IF @pFlagUsarTrans <> 0 
		BEGIN
			ROLLBACK
		END
		
		RETURN 9999
	END

	SET @Importe_Rec				= ISNULL((SELECT Imp_Total FROM Cbtes WHERE Id_Trans = @pId_Trans),0)
	SET @Importe_Aplicado			= ISNULL((SELECT SUM(Importe) FROM Cbtes_Aplica WHERE Id_Trans_D = @pId_Trans AND Id_Trans <> 0), 0) 
	SET @Importe_Pago_A_Cta			= ISNULL((SELECT SUM(Importe) FROM Cbtes_Aplica WHERE Id_Trans_D = @pId_Trans AND Id_Trans = 0), 0)
	SET @Descripcion_Cbte			= (dbo.CF_Cbte_Descrip(@pId_Trans))

	UPDATE Transacciones SET Descripcion = SUBSTRING((Descripcion + ' ' + @Descripcion_Cbte), 1, 50) WHERE Id_Trans = @pId_Trans
	
	--------------------------------- ACTUALIZO NUMERACION EN CBTE ---------------------------------

	IF(@pFlag_Renumerar = 1)
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Renumero Cbte'
		END

		SET @JSON_Parametros_Stored_Invocado =	'{' +
													dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'INT') + ',' +
													dbo.CF_Json_ParsearVariable('Omitir_Resultado_OK', @pOmitir_Resultado_OK, 'TINYINT') + 
												'}'		

		EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Grabar_Numero @JSON_Parametros_Stored_Invocado
		IF ISNULL(@Result_Stored_Invocado,0) <> 0 
		BEGIN
			RETURN 9999
		END

		SET @Descripcion_Cbte = (dbo.CF_Cbte_Descrip(@pId_Trans))
		UPDATE Transacciones SET Descripcion = @Descripcion_Cbte WHERE Id_Trans = @pId_Trans
		UPDATE Clientes_CtaCte SET Descripcion = @Descripcion_Cbte WHERE Id_Trans = @pId_Trans
	END

	--------------------------------- FIN ACTUALIZO NUMERACION EN CBTE ---------------------------------
	--agrego conceptos
	/* no implemtar por el monento
		  DELETE Cbtes_Conceptos WHERE Id_Trans = @pId_Trans

	      INSERT INTO Cbtes_Conceptos (ID_CONCEPTO,ID_TRANS,ITEM,IMPORTE,OBSERVACION)
	               SELECT ID_CONCEPTO,Id_Trans,ITEM,abs(IMPORTE),@Descripcion_Cbte AS OBSERVACION 
				   FROM CAJAS_MOV_CONCEPTOS WHERE Id_Trans = @pId_Trans
   */
	--------------------------------- ACTUALIZO ESTADOS EN TABLAS DE CBTE ---------------------------------

	UPDATE Cajas_Mov SET Id_Estado_Mov_Caja = 2, Descripcion = @Descripcion_Cbte WHERE Id_Trans = @pId_Trans
    UPDATE Cajas_Mov SET Importe = -1 * Importe WHERE Id_Trans = @pId_Trans AND Importe < 0
	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Importe_Rec: ' + CONVERT(VARCHAR(10), @Importe_Rec) + '. @Importe_Aplicado: ' + CONVERT(VARCHAR(10), @Importe_Aplicado) + '. @Importe_Pago_A_Cta: ' + CONVERT(VARCHAR(10), @Importe_Pago_A_Cta)
	END

	IF(@pFlag_Ingresos_Varios = 1)
	BEGIN 
		DECLARE @Importe_Valores DECIMAL(16,2)
		SET @Importe_Valores = ISNULL((SELECT SUM(Importe) FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans), 0)
		
		IF(@pModoDebug = 1) PRINT 'Importe recibo: ' + CONVERT(VARCHAR(20), @Importe_Rec) + ' - Importe_Valores: ' + CONVERT(VARCHAR(20), @Importe_Valores)

		IF(@Importe_Rec > 0 AND @Importe_Rec = @Importe_Valores)
		BEGIN
			UPDATE Cbtes SET Id_Estado_Cbte = 2, Saldo = 0 WHERE Id_Trans = @pId_Trans
			-- Cambio todos los valores a negativo
			UPDATE Cajas_Mov_Conceptos SET Importe = -1 * Importe WHERE Id_Trans = @pId_Trans AND Importe < 0
		END 
		ELSE 
		BEGIN 
			-- Pendiente
			UPDATE Cbtes SET Id_Estado_Cbte = 1 WHERE Id_Trans = @pId_Trans 
		END 
	END 
	ELSE 
	BEGIN
		IF(@Importe_Aplicado =  @Importe_Rec)
		BEGIN	
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Actualiza Estado a COMPLETO'
			END

			UPDATE Cbtes SET Id_Estado_Cbte = 2, Saldo = 0 WHERE Id_Trans = @pId_Trans
			UPDATE Cbtes_Items SET Id_Estado_Cbte = 2 WHERE Id_Trans = @pId_Trans
			UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 2, Descripcion = @Descripcion_Cbte, Saldo = 0 WHERE Id_Trans = @pId_Trans
		END
		ELSE
		BEGIN
			IF(@Importe_Pago_A_Cta = @Importe_Rec)
			BEGIN
				IF(@pModoDebug = 1)
				BEGIN
					PRINT 'Actualiza Estado a PENDIENTE'
				END

				UPDATE Cbtes SET Id_Estado_Cbte = 1 WHERE Id_Trans = @pId_Trans
				UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 1, Descripcion = @Descripcion_Cbte WHERE Id_Trans = @pId_Trans
			END
			ELSE
			BEGIN
				IF(@pModoDebug = 1)
				BEGIN
					PRINT 'Actualiza Estado a PARCIAL'
				END

				UPDATE Cbtes SET Id_Estado_Cbte = 4 WHERE Id_Trans = @pId_Trans
				UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 4, Descripcion = @Descripcion_Cbte WHERE Id_Trans = @pId_Trans
			END
		END
	END 

	--------------------------------- FIN ACTUALIZO ESTADOS EN TABLAS DE CBTE ---------------------------------

	--------------------------------- GENERACION DE CUENTAS CONTABLES EN CBTE ---------------------------------

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Genero asientos del cbte'
	END

	SET @JSON_Parametros_Stored_Invocado =	'{' +
													dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'INT') + ',' +
													dbo.CF_Json_ParsearVariable('RtaMsjStored', @pOmitir_Resultado_OK, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('FlagRegenerar', 1, 'TINYINT') + 
											'}'				

	EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Ctas_Contables_Generar @JSON_Parametros_Stored_Invocado
	IF ISNULL(@Result_Stored_Invocado,0) <> 0 
	BEGIN
		RETURN 9999
	END

	--------------------------------- FIN GENERACION DE CUENTAS CONTABLES EN CBTE ---------------------------------


	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('descrip_Cbte', @Descripcion_Cbte, 'VARCHAR') +
									'}'

		SELECT		0						AS ErrorNumber 
					,0						AS ErrorSeverity  
					,0						AS ErrorState 
					,0						AS ErrorProcedure  
					,0						AS ErrorLine		
					,@rtaMsjStored	AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Rec_Fin'
	END
END TRY 
BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Rec_Generar] @pJson VARCHAR(8000)

AS
SET NOCOUNT ON
/*
 * LOG VERSIONES:
 * 13/09/2021: Se agrego Log de Versiones
 * 13/04/2022: Se agrego parametro Flag_LoteUnico
*/

/*Declaracion Variables Json*/

DECLARE @pFlagUsarTrans				TINYINT
DECLARE @pModoDebug					TINYINT
DECLARE @pId_Usuario				SMALLINT
DECLARE @pId_Cliente				INT
DECLARE @pEmail						VARCHAR(50)
DECLARE @pId_Periodo_Caja			INT
DECLARE @pFecha						DATETIME
DECLARE @pImporte					DECIMAL(12,2)
DECLARE @pId_Tipo_Cbte				CHAR(4)
DECLARE @pId_Moneda					CHAR(3)
DECLARE @pCotizacion				DECIMAL(9, 4)
DECLARE @pId_Cobrador				VARCHAR(10)
DECLARE @pLote						VARCHAR(20)
DECLARE @pCbte_Nro_Externo			VARCHAR(25)
DECLARE @pFlag_LoteUnico			TINYINT		--12/04/2022 Agregado
DECLARE @pOmitir_Resultado_OK		TINYINT
DECLARE @pId_Contrato		INT

SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Usuario			= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), 0)
SET @pId_Cliente			= ISNULL(CONVERT(INT,dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')),0)
SET @pEmail					= ISNULL(CONVERT(VARCHAR(50), dbo.CF_JSON_VALUE(@pJson,'Email')), '')
SET @pId_Periodo_Caja		= ISNULL(CONVERT(INT,dbo.CF_JSON_VALUE(@pJson,'Id_Periodo_Caja')),0)
SET @pFecha					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')),'19000101')
SET @pImporte				= ISNULL(CONVERT(DECIMAL(15,2), dbo.CF_JSON_VALUE(@pJson,'Importe')), 0)
SET @pId_Tipo_Cbte			= ISNULL(CONVERT(CHAR(4), dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Cbte')), '')
SET @pId_Moneda				= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Id_Moneda')), '')
SET @pCotizacion			= ISNULL(CONVERT(DECIMAL(12,4), dbo.CF_JSON_VALUE(@pJson,'Cotizacion')), 0)
SET @pId_Cobrador			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Cobrador')), '')
SET @pLote					= ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Lote')), '')
SET @pCbte_Nro_Externo		= ISNULL(CONVERT(VARCHAR(25), dbo.CF_JSON_VALUE(@pJson,'Cbte_Nro_Externo')), '')
SET @pFlag_LoteUnico		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_LoteUnico')), 0)
SET @pOmitir_Resultado_Ok		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Resultado_OK')), 0)
SET @pId_Contrato			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Contrato')), 0)
/*Fin Declaracion Variables Json*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Trans					INT
DECLARE @Id_Empresa					SMALLINT
DECLARE @Id_Sucursal				SMALLINT
DECLARE @Cbte_Grupo					INT
DECLARE @Comprobante_Nro			INT
DECLARE @Id_Taller					VARCHAR(10)
DECLARE @Id_Proceso					VARCHAR(10)
DECLARE @Id_Proveedor				INT
DECLARE @Signo						SMALLINT
DECLARE @Id_Estado_Cbte				SMALLINT
DECLARE @Id_Dep_Fisico				CHAR(3)
DECLARE @Id_Dep_Logico				CHAR(3)
DECLARE @Porc_DescEspecial			DECIMAL(5, 2)
DECLARE @Porc_DescFin				DECIMAL(5, 2)
DECLARE @Porc_Bonificacion			DECIMAL(5, 2)
DECLARE @Porc_Iva					DECIMAL(5, 2)
DECLARE @Porc_Iva2					DECIMAL(5, 2)
DECLARE @Imp_Neto					DECIMAL(12, 2)
DECLARE @Imp_DescEspecial			DECIMAL(12, 2)
DECLARE @Imp_DescFin				DECIMAL(12, 2)
DECLARE @Imp_Bonificacion			DECIMAL(12, 2)
DECLARE @Imp_Gravado				DECIMAL(12, 2)
DECLARE @Imp_Exento					DECIMAL(12, 2)
DECLARE @Imp_IVA					DECIMAL(12, 2)
DECLARE @Imp_IVA2					DECIMAL(12, 2)
DECLARE @Imp_Percepcion_IB			DECIMAL(12, 2)
DECLARE @Imp_Percepcion_Iva			DECIMAL(12, 2)
DECLARE @Imp_Total					DECIMAL(12, 2)
DECLARE @Bultos						SMALLINT
DECLARE @NroImpresion				INT
DECLARE @Exportado					TINYINT
DECLARE @Fecha_Estimada				DATETIME
DECLARE @Dir_Entrega				VARCHAR(255)
DECLARE @Id_Pais						CHAR(3)
DECLARE @Id_Provincia				CHAR(3)
DECLARE @Id_Localidad				INT
DECLARE @Persona_Recibe				VARCHAR(100)
DECLARE @Porc_Iva3					DECIMAL(5, 2)
DECLARE @Imp_Gravado2				DECIMAL(12, 2)
DECLARE @Imp_Gravado3				DECIMAL(12, 2)
DECLARE @Imp_NoGravado				DECIMAL(12, 2)
DECLARE @Imp_IVA3					DECIMAL(12, 2)
DECLARE @Imp_Percep					DECIMAL(12, 2)
DECLARE @Saldo						DECIMAL(12, 2)
DECLARE @Periodo_Iva				DATETIME
DECLARE @Periodo					DATETIME
DECLARE @Fecha_Venc					DATETIME
DECLARE @Observacion				VARCHAR(8000)
DECLARE @Id_Cond_Pago_Item			TINYINT
DECLARE @Id_Cond_Pago				SMALLINT
DECLARE @Id_Tipo_Reten				VARCHAR(10)
DECLARE @Cant_Cuotas				SMALLINT
DECLARE @Id_Producto				VARCHAR(14)
DECLARE @Id_Formula					VARCHAR(15)
DECLARE @Cantidad					DECIMAL(12, 4)
DECLARE @Id_Vendedor				VARCHAR(10)
DECLARE @Id_Transportista			INT
DECLARE @Id_Lista					SMALLINT
DECLARE @Destinatario				VARCHAR(100)
DECLARE @Cuit						VARCHAR(19)
DECLARE @Id_Iva						CHAR(3)
DECLARE @Cant_Batch					SMALLINT
DECLARE @Nro_Perm_Embarque			VARCHAR(20)
DECLARE @Fecha_Perm_Embar			DATETIME
DECLARE @Saldo_Iva_Recup			DECIMAL(12, 2)
DECLARE @Suc_Destina				SMALLINT
DECLARE @Id_Puerto					CHAR(3)
DECLARE @Id_Cond_Vta				CHAR(10)
DECLARE @Cbte_Nro_Externo			VARCHAR(25)
DECLARE @Nota_Part1					VARCHAR(100)
DECLARE @Nota_Part2					VARCHAR(100)
DECLARE @Id_Asiento					INT
DECLARE @Id_Centro_Costo			CHAR(10)
DECLARE @Id_Valor					INT
DECLARE @Cai						DECIMAL(14, 0)
DECLARE @Cai_Vence					DATETIME
DECLARE @Des_Anio					TINYINT
DECLARE @Des_Aduana					CHAR(3)
DECLARE @Des_Destina				CHAR(4)
DECLARE @Des_Nro					INT
DECLARE @Des_Verif					CHAR(1)
DECLARE @Id_Cobrador				VARCHAR(10)
DECLARE @Nro_Auto_Trib				VARCHAR(14)
DECLARE @Id_Camp					SMALLINT
DECLARE @Remito_Nro					VARCHAR(25)
DECLARE @Pedido_Nro					VARCHAR(25)
DECLARE @Id_Tarjeta					VARCHAR(11)
DECLARE @Tarjeta_Nro				VARCHAR(25)
DECLARE @Cantidad_Saldo				DECIMAL(12, 4)
DECLARE @Saldo_Anterior				DECIMAL(12, 2)
DECLARE @NRO_DJAI					VARCHAR(30)
DECLARE @Cantidad_Equiv				DECIMAL(12, 4)
DECLARE @Id_Trans_Origen			INT
DECLARE @Id_Sede_Origen				SMALLINT
DECLARE @Email						VARCHAR(8000)
DECLARE @Patente_Transporte			VARCHAR(7)
DECLARE @Patente_Transporte_Acoplado VARCHAR(7)

DECLARE @Flag_Existe_Cliente		TINYINT
DECLARE @Flag_Existe_Periodo_Caja	TINYINT
DECLARE @Flag_Existe_Cbte_Tipo		TINYINT
DECLARE @Flag_Existe_Moneda			TINYINT
DECLARE @Flag_Existe_Usuario		TINYINT
DECLARE @Flag_Lote					TINYINT

DECLARE @Plazo_Venc					SMALLINT
DECLARE @Renglon_Nro				SMALLINT
DECLARE @Id_Estado_Mov_Caja			INT
DECLARE @Descripcion				VARCHAR(100)
DECLARE @Id_Tipo_Mov_Caja			SMALLINT
DECLARE @Id_Concepto				INT
DECLARE @Item						SMALLINT
DECLARE @Id_Estado_Concepto			SMALLINT
DECLARE @Mensaje					VARCHAR(100)
DECLARE @Resultado					INT
DECLARE @Flag_Existe_Cbte_Lote		TINYINT
/*Fin de Declaraciones Variables Locales */

/*BLOQUE BEGIN TRY *************************************************************************************/
BEGIN TRY
	BEGIN TRAN

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Rec_Generar'
		PRINT 'Parametros:'	
		PRINT '.@pId_Cliente: ' + CONVERT(VARCHAR(10), @pId_Cliente)+ '.pEmail: ' + CONVERT(VARCHAR(MAX), @pEmail) + ' pFecha: ' + CONVERT(VARCHAR(10), @pFecha, 103) +'pImporte:  ' +CONVERT(VARCHAR(50),@pImporte) + 'pId_Tipo_Cbte: ' + @pId_Tipo_Cbte +  ' pId_Moneda: ' + @pId_Moneda + ' pCotizacion: ' + CONVERT(VARCHAR(20), @pCotizacion) + '. pLote: ' + @pLote + 'pCbte_Nro_Externo: ' + @pCbte_Nro_Externo
	END
	
	/*===================================================================================================================================================================*/

	SET @Flag_Existe_Usuario = ISNULL((SELECT 1 FROM Seg_User WHERE No = @pId_Usuario), 0)
	IF (@Flag_Existe_Usuario = 0)
	BEGIN
		IF @pOmitir_Resultado_Ok = 0
		BEGIN
			SET @Mensaje = 'No existe el usuario '

			SELECT	1001			AS ErrorNumber 
					,0				AS ErrorSeverity  
					,0				AS ErrorState 
					,0				AS ErrorProcedure  
					,0				AS ErrorLine		
					,@Mensaje		AS ErrorMessage
					,0				AS Id_Trans
		END

		ROLLBACK
		RETURN 1001
	END

	SET @Flag_Existe_Cliente = ISNULL((SELECT 1 FROM Clientes WHERE Id_Cliente = @pId_Cliente), 0)
	IF (@Flag_Existe_Cliente = 0)
	BEGIN
		IF @pOmitir_Resultado_Ok = 0
		BEGIN
			SET @Mensaje = 'No existe el Cliente '

			SELECT	2001			AS ErrorNumber 
					,0				AS ErrorSeverity  
					,0				AS ErrorState 
					,0				AS ErrorProcedure  
					,0				AS ErrorLine		
					,@Mensaje		AS ErrorMessage
					,@Id_Trans		AS Id_Trans
		END

		ROLLBACK
		RETURN
	END

	SET @Flag_Existe_Periodo_Caja = ISNULL((SELECT 1 FROM Cajas_Periodos WHERE Id_Periodo_Caja = @pId_Periodo_Caja AND Id_Estado_Caja = 1/*Abierta*/), 0)
	IF (@Flag_Existe_Periodo_Caja = 0)
	BEGIN
		IF @pOmitir_Resultado_Ok = 0
		BEGIN
			SET @Mensaje = 'No existe el Periodo de Caja Abierto'

			SELECT	2003			AS ErrorNumber 
					,0				AS ErrorSeverity  
					,0				AS ErrorState 
					,0				AS ErrorProcedure  
					,0				AS ErrorLine		
					,@Mensaje		AS ErrorMessage
					,@Id_Trans		AS Id_Trans
		END

		ROLLBACK
		RETURN 2003
	END

	SET @Flag_Existe_Cbte_Tipo = ISNULL((SELECT 1 FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @pId_Tipo_Cbte AND ISNULL(Activo, 0) = 1), 0)
	IF (@Flag_Existe_Cbte_Tipo = 0)
	BEGIN
		IF @pOmitir_Resultado_Ok = 0
		BEGIN
			SET @Mensaje = 'No existe el Tipo de Cbte o esta inactivo'

			SELECT	2004			AS ErrorNumber 
					,0				AS ErrorSeverity  
					,0				AS ErrorState 
					,0				AS ErrorProcedure  
					,0				AS ErrorLine		
					,@Mensaje		AS ErrorMessage
					,@Id_Trans		AS Id_Trans
		END

		ROLLBACK
		RETURN 2004
	END

	SET @Flag_Existe_Moneda = ISNULL((SELECT 1 FROM Valores_Monedas WHERE Id_Moneda = @pId_Moneda), 0)
	IF (@Flag_Existe_Moneda = 0)
	BEGIN
		IF @pOmitir_Resultado_Ok = 0
		BEGIN
			SET @Mensaje = 'No existe el Tipo de Moneda'

			SELECT	2005			AS ErrorNumber 
					,0				AS ErrorSeverity  
					,0				AS ErrorState 
					,0				AS ErrorProcedure  
					,0				AS ErrorLine		
					,@Mensaje		AS ErrorMessage
					,@Id_Trans		AS Id_Trans
		END

		ROLLBACK
		RETURN 2006
	END

	/*Cargo en transacciones *************************************************************************/
	
	SET @Id_Trans		= ISNULL((SELECT MAX(Id_Trans) + 1 FROM Transacciones), 0)
	INSERT INTO dbo.Transacciones 	(Id_Trans,	Descripcion,				Fecha_Mov, 	Id_Usuario)
							VALUES	(@Id_Trans,	'Apertura CPJ_Transacciones_Abrir',	GETDATE(), 	@pId_Usuario)


    /*Fin Cargo en transacciones ******************************************************************/

	--13/04/2022 Se agrega la utilizacion del parametro @pFlag_LoteUnico para poder validar que si ya se ingreso un pago WEB (Lote tipo P00XXXXXX) sea unico
	IF(@pFlag_LoteUnico = 1)
	BEGIN
		SET @Flag_Existe_Cbte_Lote = ISNULL((SELECT TOP 1 1
											FROM Cbtes CB, Cbtes_Tipos CT
											WHERE
											CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
											AND CT.Compromete_Recibos IN (1, -1)
											AND CB.Lote = @pLote)
											, 0) 
		IF(@pModoDebug = 1)
		BEGIN
			PRINT '@Flag_Existe_Cbte_Lote: ' + CONVERT(VARCHAR(10), @Flag_Existe_Cbte_Lote)
		END

		IF(@Flag_Existe_Cbte_Lote = 1)
		BEGIN
			SET @Id_Trans		= 0

			IF @pOmitir_Resultado_OK = 0
			BEGIN
				SET @rtaMsjStored	=	'{' +
										dbo.CF_Json_ParsearVariable('id_trans', @Id_Trans, 'INT')  + ',' +
										dbo.CF_Json_ParsearVariable('id_cliente', 0, 'INT')  + ',' +
										dbo.CF_Json_ParsearVariable('id_tipo_cbte', '', 'VARCHAR') +
										'}'
									
				SELECT	 0				AS ErrorNumber 
						,0				AS ErrorSeverity  
						,0				AS ErrorState 
						,0				AS ErrorProcedure  
						,@Id_Trans		AS ErrorLine		
						,@rtaMsjStored	AS ErrorMessage
			END
		END
	END

	/******************VALIDACIONES *************************************************************************/
	
	IF(@pId_Moneda = '')
	BEGIN
		SET @pId_Moneda = dbo.CF_xParam('Moneda_Nacional')
	END

	IF(@pCotizacion = 0)
	BEGIN
		SET @pCotizacion = 1
	END
	
	IF(@pLote <> '')
	BEGIN
		SET @Flag_Lote	= 1
	END
	ELSE
	BEGIN
		SET @Flag_Lote	= 0
	END
	/*FIN VALIDACIONES ****************************************************************************/	


    
	/*Comienzo con seteo de variables *************************************************************/
	
	SET @pFecha				= (SELECT CONVERT(DATE, @pFecha))

	SELECT  @Id_Sucursal	= ISNULL(Id_Sucursal, 0),
			@Cbte_Grupo		= ISNULL(Cbte_Grupo, 0),
			@Id_Cond_Pago	= ISNULL(Id_Cond_Pago, ''),
			@Id_Estado_Cbte	= ISNULL(Id_Estado_Cbte, 0)
			FROM Cbtes_Tipos 
			WHERE Id_Tipo_Cbte = @pId_Tipo_Cbte

	SELECT 	@Destinatario	= ISNULL(Razon_Social, Apellido + ', ' + Nombre),
			@Id_Pais		= ISNULL(Id_Pais_Cob, ''),
			@Id_Provincia	= ISNULL(Id_Provincia_Cob, ''),
			@Id_Localidad	= ISNULL(Id_Localidad_Cob, 0),
			@Id_Lista		= ISNULL(Id_Lista_Precio, 0),
			@Cuit			= ISNULL(Cuit, ''),
			@Id_Iva			= ISNULL(Id_Iva, ''),
			@Id_Concepto	= ISNULL(Id_Concepto, 0)
			FROM Clientes
			WHERE Id_Cliente = @pId_Cliente

	IF(ISNULL(@pEmail, '') = '')
	BEGIN
		SET @Email				= (SELECT ISNULL(Email_Cob, '') FROM Clientes WHERE Id_Cliente = @pId_Cliente)
	END

	SET @Comprobante_Nro		= 0		
	SET @Plazo_Venc				= (SELECT ISNULL(Plazo_Venc, 0) FROM Cbtes_Cond_Pago WHERE Id_Cond_Pago = @Id_Cond_Pago)
	SET @Fecha_Venc				= @pFecha --Siempre es la misma en Recibos, no se basa en Cond_Pago Dias_Venc	
	SET @Periodo_Iva			= @pFecha
	SET @Periodo				= @pFecha
	SET @Imp_Total				= @pImporte
	SET @Saldo					= @pImporte
	SET @Imp_Gravado			= @pImporte
	SET @Cbte_Nro_Externo		= @pCbte_Nro_Externo
	
	/*TO-DO: De aca para abajo por ahora por Default*/
	SET @Id_Cond_Vta			= ''
	SET @Id_Taller				= ''
	SET @Id_Proceso				= ''
	SET @Id_Proveedor			= 0
	SET @Signo					= 0
	SET	@Porc_DescFin			= 0
	SET @Id_Dep_Fisico			= ''
	SET @Id_Dep_Logico			= ''
	SET @Porc_DescEspecial		= 0
	SET @Porc_Bonificacion		= 0
	SET @Porc_Iva				= 0
	SET @Porc_Iva2				= 0
	SET @Imp_Neto				= 0
	SET @Imp_DescEspecial		= 0
	SET @Imp_DescFin			= 0
	SET @Imp_Bonificacion		= 0
	SET @Imp_Exento				= 0
	SET @Imp_Iva				= 0
	SET @Imp_Iva2				= 0
	SET @Imp_Percepcion_IB		= 0
	SET @Imp_Percepcion_Iva		= 0
	SET @Bultos					= 0
	SET @NroImpresion			= 0
	SET @Exportado				= 0
	--SET @Fecha_Estimada NULL
	SET @Dir_Entrega			= ''
	SET @Persona_Recibe			= ''
	SET @Porc_Iva3				= 0
	SET @Imp_Gravado2			= 0
	SET @Imp_Gravado3			= 0
	SET @Imp_NoGravado			= 0
	SET @Imp_IVA3				= 0
	SET @Imp_Percep				= 0
	SET @Observacion			= ''
	--SET @Id_Cond_Pago_Item	NULL
	SET @Id_Tipo_Reten			= ''
	SET @Cant_Cuotas			= 0
	--SET @Id_Producto			NULL
	--SET @Id_Formula			NULL
	SET @Cantidad				= 0
	SET @Id_Vendedor			= ''
	SET @Id_Transportista		= 0
	SET @Cant_Batch				= 0
	SET @Nro_Perm_Embarque		= ''
	--SET @Fecha_Perm_Embar
	SET @Saldo_Iva_Recup		= 0
	SET @Suc_Destina			= 0
	SET @Id_Puerto				= ''
	--SET @Cbte_Nro_Externo	= ''
	SET @Nota_Part1				= ''
	SET @Nota_Part2				= ''
	SET @Id_Asiento				= 0
	SET @Id_Centro_Costo		= ''
	SET @Id_Valor				= 0
	SET @Cai					= 0
	--SET @Cai_Vence NULL
	SET @Des_Anio				= 0
	SET @Des_Aduana				= ''
	SET @Des_Destina			= ''
	SET @Des_Nro				= 0
	SET @Des_Verif				= ''


	IF(@pId_Cobrador <> '')
	BEGIN
		SET @Id_Cobrador		= @pId_Cobrador
	END
	ELSE
	BEGIN
		SET @Id_Cobrador		= (SELECT ISNULL(Id_Cobrador, '') FROM Clientes WHERE Id_Cliente = @pId_Cliente)
	END

	SET @Nro_Auto_Trib			= ''
	SET @Id_Camp				= 0
	SET @Remito_Nro				= ''
	SET @Pedido_Nro				= ''
	SET @Id_Tarjeta				= ''
	SET @Tarjeta_Nro			= ''
	SET @Cantidad_Saldo			= 0
	SET @Saldo_Anterior			= 0
	SET @NRO_DJAI				= ''
	SET @Cantidad_Equiv			= 0
	SET @Id_Trans_Origen		= 0
	SET @Id_Sede_Origen			= 0
	--SET @Patente_Transporte NULL
	--SET @Patente_Transporte_Acoplado NULL	

	/*FIN de Seteo de variables *******************************************************/
	
	INSERT INTO dbo.Cbtes
	(Id_Trans,			Id_Empresa,			Id_Sucursal,
	Id_Tipo_Cbte,		Cbte_Grupo,			Comprobante_Nro,
	Id_Cliente,			Id_Taller,			Id_Proceso,
	Id_Proveedor,		Signo,				Id_Estado_Cbte,
	Fecha,				Id_Dep_Fisico,		Id_Dep_Logico,
	Porc_DescEspecial,	Porc_DescFin,		Porc_Bonificacion,
	Porc_Iva,			Porc_Iva2,			Imp_Neto,
	Imp_DescEspecial,	Imp_DescFin,		Imp_Bonificacion,
	Imp_Gravado,		Imp_Exento,			Imp_IVA,
	Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
	Imp_Total,			Bultos,				NroImpresion,
	Exportado,			Id_Usuario,			Fecha_Estimada,
	Dir_Entrega,		Id_Pais,			Id_Provincia,
	Id_Localidad,		Persona_Recibe,		Porc_Iva3,
	Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
	Imp_IVA3,			Imp_Percep,			Saldo,
	Periodo_Iva,		Periodo,			Fecha_Venc,
	Observacion,		Id_Cond_Pago_Item,	Id_Cond_Pago,
	Id_Tipo_Reten,		Cant_Cuotas,		Id_Producto,
	Id_Formula,			Cantidad,			Id_Vendedor,
	Id_Transportista,	Id_Lista,			Id_Moneda,
	Cotizacion,			Destinatario,		Cuit,
	Id_Iva,				Cant_Batch,			Nro_Perm_Embarque,
	Fecha_Perm_Embar,	Saldo_Iva_Recup,	Lote,
	Suc_Destina,		Id_Puerto,			Id_Cond_Vta,
	Cbte_Nro_Externo,	Nota_Part1,			Nota_Part2,
	Id_Asiento,			Id_Centro_Costo,	Id_Valor,
	Cai,				Cai_Vence,			Des_Anio,
	Des_Aduana,			Des_Destina,		Des_Nro,
	Des_Verif,			Id_Contrato,		Id_Cobrador,
	Nro_Auto_Trib,		Id_Camp,			Remito_Nro,
	Pedido_Nro,			Id_Tarjeta,			Tarjeta_Nro,
	Cantidad_Saldo,		Saldo_Anterior,		NRO_DJAI,
	Cantidad_Equiv,		Id_Trans_Origen,	Id_Sede_Origen,
	Email,				Patente_Transporte,	Patente_Transporte_Acoplado,
	Flag_Lote)
	VALUES
	(@Id_Trans,			@Id_Empresa,		@Id_Sucursal,
	SUBSTRING(@pId_Tipo_Cbte,1,4),	@Cbte_Grupo,		@Comprobante_Nro,
	@pId_Cliente,		@Id_Taller,			@Id_Proceso,
	@Id_Proveedor,		@Signo,				@Id_Estado_Cbte,
	@pFecha,			@Id_Dep_Fisico,		@Id_Dep_Logico,
	@Porc_DescEspecial,	@Porc_DescFin,		@Porc_Bonificacion,
	@Porc_Iva,			@Porc_Iva2,			@Imp_Neto,
	@Imp_DescEspecial,	@Imp_DescFin,		@Imp_Bonificacion,
	@Imp_Gravado,		@Imp_Exento,		@Imp_IVA,
	@Imp_IVA2,			@Imp_Percepcion_IB,	@Imp_Percepcion_Iva,
	@Imp_Total,			@Bultos,			@NroImpresion,
	@Exportado,			@pId_Usuario,		@Fecha_Estimada,
	@Dir_Entrega,		@Id_Pais,			@Id_Provincia,
	@Id_Localidad,		@Persona_Recibe,	@Porc_Iva3,
	@Imp_Gravado2,		@Imp_Gravado3,		@Imp_NoGravado,
	@Imp_IVA3,			@Imp_Percep,		@Saldo,
	@Periodo_Iva,		@Periodo,			@Fecha_Venc,
	@Observacion,		@Id_Cond_Pago_Item,	@Id_Cond_Pago,
	@Id_Tipo_Reten,		@Cant_Cuotas,		@Id_Producto,
	@Id_Formula,		@Cantidad,			@Id_Vendedor,
	@Id_Transportista,	@Id_Lista,			@pId_Moneda,
	@pCotizacion,		@Destinatario,		@Cuit,
	@Id_Iva,			@Cant_Batch,		@Nro_Perm_Embarque,
	@Fecha_Perm_Embar,	@Saldo_Iva_Recup,	@pLote,
	@Suc_Destina,		@Id_Puerto,			@Id_Cond_Vta,
	@Cbte_Nro_Externo,	@Nota_Part1,		@Nota_Part2,
	@Id_Asiento,		@Id_Centro_Costo,	@Id_Valor,
	@Cai,				@Cai_Vence,			@Des_Anio,
	@Des_Aduana,		@Des_Destina,		@Des_Nro,
	@Des_Verif,			@pId_Contrato,		@Id_Cobrador,
	@Nro_Auto_Trib,		@Id_Camp,			@Remito_Nro,
	@Pedido_Nro,		@Id_Tarjeta,		@Tarjeta_Nro,
	@Cantidad_Saldo,	@Saldo_Anterior,	@Nro_DJAI,
	@Cantidad_Equiv,	@Id_Trans_Origen,	@Id_Sede_Origen,
	@Email,				@Patente_Transporte,@Patente_Transporte_Acoplado,
	@Flag_Lote)

	/*****************************************************************************/

	SET @Renglon_Nro = 1
	SET @Id_Estado_Mov_Caja = 0 --EN CARGA
	SET @Descripcion = ISNULL((dbo.CF_Cbte_Descrip(@Id_Trans)), '')
	SET @Id_Tipo_Mov_Caja = 7 --RECIBO DE COBRANZA

	INSERT INTO dbo.Cajas_Mov
			(Id_Trans,			Renglon_Nro,	Id_Estado_Mov_Caja,
			Importe,			Descripcion,	Id_Periodo_Caja,
			Id_Tipo_Mov_Caja,	Fecha)
			VALUES
			(@Id_Trans,			@Renglon_Nro,	@Id_Estado_Mov_Caja,
			@pImporte,			@Descripcion,	@pId_Periodo_Caja,
			@Id_Tipo_Mov_Caja,	GETDATE()/*Es con hora*/)

	/*****************************************************************************/

	SET @Item = 1
	SET @Id_Estado_Concepto = 0
	
	INSERT INTO dbo.Cajas_Mov_Conceptos
			(Id_Trans,						Id_Concepto,			Item,
			Id_Estado_Concepto,		Importe,				Id_Periodo_Caja)
			VALUES
			(@Id_Trans,					@Id_Concepto,		@Item,
			@Id_Estado_Concepto,	@pImporte * (-1),	@pId_Periodo_Caja)

	/*****************************************************************************/
	
	UPDATE Transacciones SET Descripcion = LTRIM(RTRIM(@Descripcion)) WHERE Id_Trans = @Id_Trans

	/*****************************************************************************/
	
	IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0
	BEGIN
		COMMIT
	END

	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @Id_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_cliente', @pId_Cliente, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_tipo_cbte', @pId_Tipo_Cbte, 'VARCHAR') +
									'}'
									
		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,@Id_Trans		AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Rec_Generar'
	END	
	
END TRY  
BEGIN CATCH  

    EXECUTE usp_GetErrorInfo; 
	ROLLBACK
	RETURN 9999
END CATCH


RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Rec_Generar_Item] @pJson VARCHAR(8000)
AS
SET NOCOUNT ON

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans				TINYINT
DECLARE @pModoDebug					TINYINT
DECLARE @pId_Trans					INT
DECLARE @pItem						SMALLINT
DECLARE @pId_Producto				VARCHAR(14)
DECLARE @pCantidad					DECIMAL(15,5)
DECLARE @pId_Trans_A_Cancelar		INT
DECLARE @pImporte_A_Cancelar		DECIMAL(16,2)
DECLARE @pOmitir_Resultado_OK       TINYINT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')),0)
SET @pItem						= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Item')),0)
SET @pId_Producto				= ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')),'')
SET @pCantidad					= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Cantidad')),0)
SET @pId_Trans_A_Cancelar		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans_A_Cancelar')),0)
SET @pImporte_A_Cancelar		= ISNULL(CONVERT(DECIMAL(16,2), dbo.CF_JSON_VALUE(@pJson,'Importe_A_Cancelar')),0)
SET @pOmitir_Resultado_OK		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Resultado_OK')),0)
/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/
	
/*Declaracion Variables Locales*/
DECLARE @Id_Estado_Cbte			SMALLINT
DECLARE @Calle					CHAR(3)
DECLARE @Columna				CHAR(3)
DECLARE @Fila					CHAR(3)
DECLARE @Bultos					DECIMAL(15,5)
DECLARE @Despacho				VARCHAR(100)
DECLARE @Serie					VARCHAR(100)
DECLARE @Fecha_Venc				DATETIME
DECLARE @Observacion			VARCHAR(8000)
DECLARE @Millas					INT
DECLARE @Cantidad_Saldo			DECIMAL(15,5)
DECLARE @Precio_Grav			DECIMAL(15,5)
DECLARE @Precio_Exen			DECIMAL(15,5)
DECLARE @Imp_Gravado			DECIMAL(12,2)
DECLARE @Imp_Exento				DECIMAL(12,2)
DECLARE @Analisis				VARCHAR(30)
DECLARE @Lote					VARCHAR(20)
DECLARE @Flag_QA				CHAR(1)
DECLARE @Fecha_QA				DATETIME
DECLARE @Porc_Iva				DECIMAL(5,2)
DECLARE @Bonif					DECIMAL(5,2)
DECLARE @Descripcion_producto	VARCHAR(100)
DECLARE @Id_Unidad_Medida		CHAR(4)
DECLARE @Imp_Final				DECIMAL(15,5)
DECLARE @Costo					DECIMAL(15,5)
DECLARE @Imp_Iva				DECIMAL(12,2)
DECLARE @Precio					DECIMAL(15,5)
DECLARE @Id_Costo				INT
DECLARE @Id_Cliente				INT
DECLARE @Id_Tarea				SMALLINT
DECLARE @Fecha_Caducidad		DATETIME
DECLARE @Id_Pais				CHAR(3)
DECLARE @Id_Usuario				SMALLINT
DECLARE @CANTIDAD_EQUIV			DECIMAL(15,5)
DECLARE @Costo_MO				DECIMAL(15,5)
DECLARE @Costo_GF				DECIMAL(15,5)
DECLARE @Id_Cond_Pago			SMALLINT
DECLARE @Fecha_Proceso			DATETIME
DECLARE @Id_Balanza				CHAR(10)
DECLARE @Orden					SMALLINT
DECLARE @Flag_NoImp_Factura		TINYINT
DECLARE @Nro_Tag				VARCHAR(30)
DECLARE @Fecha_Elaboracion		DATETIME
DECLARE @Costo_Comparativo		DECIMAL(13,4)
DECLARE @Id_Cta_Banco			SMALLINT
DECLARE @Porc_Imp_INT			DECIMAL(5,2)

DECLARE @Nro_Cuota				SMALLINT
DECLARE @Id_Empresa				SMALLINT
DECLARE @Id_Cliente_Cab			INT
DECLARE @Fecha_Vence			DATETIME
DECLARE @Descripcion			VARCHAR(100)
DECLARE @Importe				DECIMAL(12,2)
DECLARE @Nro_Cuota_Origen		SMALLINT
DECLARE @Id_Moneda				CHAR(3)
DECLARE @Saldo					DECIMAL(12,2)
DECLARE @Nro_FacCre				INT

DECLARE @Flag_Existe_Producto	TINYINT
DECLARE @Id_Tipo_Cbte			CHAR(4)
DECLARE @Fecha					DATETIME
DECLARE @Item					SMALLINT
DECLARE @Item_D					SMALLINT
DECLARE @Cantidad				DECIMAL(14, 2)
DECLARE @Fecha_Aplic			DATETIME

DECLARE @Id_Estado_Cbte_Id_Trans_Origen	SMALLINT
DECLARE @Id_Trans_Origen		INT
DECLARE @Id_Trans_CA			INT
DECLARE @Saldo_Cbte				DECIMAL(16,2)

DECLARE @Mensaje				VARCHAR(100)
/*Fin de Declaraciones Variables Locales */


BEGIN TRY
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Rec_Generar_Item'
		PRINT 'Parametros:'
		PRINT  'Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans) + ' Id_Producto: ' + @pId_Producto + ' Cantidad: ' + CONVERT(VARCHAR(20), @pCantidad) + ' Id_Trans_A_Cancelar: ' + CONVERT(VARCHAR(10), @pId_Trans_A_Cancelar) + ' Importe_A_Cancelar: ' + CONVERT(VARCHAR(20), @pImporte_A_Cancelar)
	END

	/*Validaciones******************************************************************/
	
	IF(@pId_Trans		 = 0) RAISERROR ('Id_Trans can not be zero.', 16,  1 ) 

	/*Fin Validaciones **************************************************************/
	
	/*Seteo Respuesta del Stored *********************************************/

	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('item', @Item, 'SMALLINT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_producto', @pId_Producto, 'VARCHAR')  + ',' +
									dbo.CF_Json_ParsearVariable('Importe_A_Cancelar', @pImporte_A_Cancelar, 'DECIMAL') +
									'}'

		SELECT	 0						AS ErrorNumber 
				,0						AS ErrorSeverity  
				,0						AS ErrorState 
				,0						AS ErrorProcedure  
				,0						AS ErrorLine		
				,@rtaMsjStored			AS ErrorMessage
	END

	/*Asignaci├│n de Variables *********************************************************/
	
	SELECT  @Id_Tipo_Cbte	= ISNULL(Id_Tipo_Cbte, ''),
			@Fecha			= ISNULL(Fecha, '19000101'),
			@Id_Cliente_Cab = ISNULL(Id_Cliente, 0),
			@Id_Moneda		= Id_Moneda
	FROM Cbtes
	WHERE 
	Id_Trans = @pId_Trans

	/*************************************************************************************************/

	SELECT  @Id_Estado_Cbte	= ISNULL(Id_Estado_Cbte_Item, 0) FROM Cbtes_Tipos  WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte

	/*************************************************************************************************/

	IF(@pId_Producto <> '')
	BEGIN
		SELECT  @Calle	= ISNULL(Calle, ''),
			@Columna	= ISNULL(Columna, ''),
			@Fila		= ISNULL(Fila, ''),
			@Despacho	= ISNULL(Despacho, '')
		FROM Productos
		WHERE 
		Id_Producto = @pId_Producto
	END
	ELSE
	BEGIN
		SET @Calle		=  ''
		SET @Columna	= ''
		SET @Fila		=  ''
		SET @Despacho	=  ''
	END

	/*************************************************************************************************/

	IF(@pId_Trans_A_Cancelar <> 0)
	BEGIN
		SELECT @Id_Estado_Cbte_Id_Trans_Origen = ISNULL(Id_Estado_Cbte, 0), @Saldo_Cbte = Saldo FROM Cbtes 	WHERE Id_Trans = @pId_Trans_A_Cancelar
	END
	ELSE
	BEGIN
		SET @Id_Estado_Cbte_Id_Trans_Origen = 0 
		SET @Saldo_Cbte = 0 
	END

	/*************************************************************************************************/

	IF(@pId_Trans_A_Cancelar <> 0)
	BEGIN
		SET @Observacion			= (dbo.CF_Cbte_Descrip(@pId_Trans_A_Cancelar))
		SET @Descripcion_producto	= (dbo.CF_Cbte_Descrip(@pId_Trans_A_Cancelar))
	END
	ELSE
	BEGIN
		SET @Observacion			= ''
		SET @Descripcion_producto	= ''
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Observacion: ' + @Observacion + '. @Descripcion_producto' + @Descripcion_producto
	END

	/*************************************************************************************************/

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Id_Estado_Cbte_Id_Trans_Origen: ' + CONVERT(VARCHAR(10), @Id_Estado_Cbte_Id_Trans_Origen)
	END

	IF(@Id_Estado_Cbte_Id_Trans_Origen IN (1,4) /*Pendiente*/)
	BEGIN
		SET @Fecha_Venc		= @Fecha		
		SET @Imp_Gravado	= @pImporte_A_Cancelar
		SET @Item 			= @pItem 
		SET @Imp_Final		= @Imp_Gravado
		/*TO-DO: De aca para abajo por ahora por Default*/
		SET @Bultos			= 0
		SET @Serie			= ''
		SET @Millas			= 0
		SET @Cantidad_Saldo = 0
		SET @Precio_Grav	= 0
		SET @Precio_Exen	= 0	
		SET @Imp_Exento		= 0
		SET @Analisis		= ''
		SET @Lote			= ''
		SET @Flag_QA		= ''
		--SET @Fecha_QA = NULL
		SET @Porc_Iva		= 0
		SET @Bonif			= 0
		SET @Id_Unidad_Medida = ''
		--SET @Imp_Final = 0
		SET @Costo			= 0
		SET @Imp_Iva		= 0
		SET @Precio			= 0
		SET @Id_Costo		= 0
		SET @Id_Cliente		= 0
		SET @Id_Tarea		= 0
		--SET @Fecha_Caducidad = NULL
		SET @Id_Pais		= ''
		SET @Id_Usuario		= 0
		SET @Cantidad_Equiv = 0
		SET @Costo_MO		= 0
		SET @Costo_GF		= 0
		SET @Id_Cond_Pago	= 0
		--SET @Fecha_Proceso NULL
		SET @Id_Balanza		= ''
		SET @Orden			= 0
		SET @Flag_NoImp_Factura = 0
		SET @Nro_Tag		= ''
		--SET @Fecha_Elaboracion = NULL
		SET @Costo_Comparativo = 0
		SET @Id_Cta_Banco	= 0
		SET @Porc_Imp_Int	= 0
		
		IF(@pId_Trans_A_Cancelar <> 0)
		BEGIN
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Inserta Cbtes_Items'
			END

			INSERT INTO dbo.Cbtes_Items
			(Id_Trans,		Item,				Id_Producto,
			Id_Estado_Cbte,	Cantidad,			Calle,
			Columna,		Fila,				Bultos,
			Despacho,		Serie,				Fecha_Venc,
			Observacion,	Millas,				Cantidad_Saldo,
			Precio_Grav,	Precio_Exen,		Imp_Gravado,
			Imp_Exento,		Analisis,			Lote,
			Flag_QA,		Fecha_QA,			Porc_Iva,
			Bonif,			Descripcion_producto,Id_Unidad_Medida,
			Imp_Final,		Costo,				Imp_Iva,
			Precio,			Id_Costo,			Id_Cliente,
			Id_Tarea,		Fecha_Caducidad,	Id_Pais,
			Id_Usuario,		Cantidad_Equiv,		Costo_MO,
			Costo_GF,		Id_Cond_Pago,		Fecha_Proceso,
			Id_Balanza,		Orden,				Flag_NoImp_Factura,
			Nro_Tag,		Fecha_Elaboracion,	Costo_Comparativo,
			Id_Cta_Banco,	Porc_Imp_Int)
			VALUES
			(@pId_Trans,	@pItem,				@pId_Producto,
			@Id_Estado_Cbte,@pCantidad,			@Calle,
			@Columna,		@Fila,				@Bultos,
			@Despacho,		@Serie,				@Fecha_Venc,
			@Observacion,	@Millas,			@Cantidad_Saldo,
			@Precio_Grav,	@Precio_Exen,		@Imp_Gravado,
			@Imp_Exento,	@Analisis,			@Lote,
			@Flag_QA,		@Fecha_QA,			@Porc_Iva,
			@Bonif,			@Descripcion_producto,@Id_Unidad_Medida,
			@Imp_Final,		@Costo,				@Imp_Iva,
			@Precio,		@Id_Costo,			@Id_Cliente,
			@Id_Tarea,		@Fecha_Caducidad,	@Id_Pais,
			@Id_Usuario,	@Cantidad_Equiv,	@Costo_MO,
			@Costo_GF,		@Id_Cond_Pago,		@Fecha_Proceso,
			@Id_Balanza,	@Orden,				@Flag_NoImp_Factura,
			@Nro_Tag,		@Fecha_Elaboracion,	@Costo_Comparativo,
			@Id_Cta_Banco,	@Porc_Imp_Int)
		END
	END	

	/*****************************************************************************/

	IF(@pId_Trans_A_Cancelar <> 0)
	BEGIN
		SET @Descripcion		= dbo.CF_Cbte_Descrip(@pId_Trans)
	END
	ELSE
	BEGIN
		SET @Descripcion		= ''
	END

	SET @Nro_Cuota			= @pItem
	SET @Fecha_Vence		= @Fecha	
	SET @Importe			= (@pImporte_A_Cancelar * (-1))
	SET @Id_Estado_Cbte		= 0 --En Carga
	SET @Observacion		= ''
	SET @Saldo				= @Importe
	SET @Nro_FacCre			= 0
	
	IF(@Id_Estado_Cbte_Id_Trans_Origen IN (1,4)/*Pendiente*/)
	BEGIN
		SET @Id_Trans_Origen = @pId_Trans_A_Cancelar
		SET @Nro_Cuota_Origen = 1
	END
	ELSE
	BEGIN
		SET @Id_Trans_Origen = 0
		SET @Nro_Cuota_Origen = 0
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Inserta Clientes_CtaCte'
	END

	INSERT INTO dbo.Clientes_CtaCte
	(Id_Trans,			Nro_Cuota,				Id_Empresa,
	Id_Cliente,			Fecha,					Fecha_Vence,
	Descripcion,		Importe,				Id_Estado_Cbte,
	Observacion,		Id_Trans_Origen,		Nro_Cuota_Origen,
	Id_Moneda,			Saldo,					Nro_FacCre)
	VALUES
	(@pId_Trans,		@Nro_Cuota,				@Id_Empresa,
	@Id_Cliente_Cab,	@Fecha,					@Fecha_Vence,
	@Descripcion,		@Importe,				@Id_Estado_Cbte,
	@Observacion,		@Id_Trans_Origen,		@Nro_Cuota_Origen,
	@Id_Moneda,			@Saldo,					@Nro_FacCre)

	/*****************************************************************************/
	
	SET @Item_D	= 1
	SET @Cantidad = 0
	
	IF(@Id_Estado_Cbte_Id_Trans_Origen IN (1,4) /*Pendiente*/)
	BEGIN
		SET @Id_Trans_CA	= @pId_Trans_A_Cancelar
		SET @Item			= 1
	END
	ELSE
	BEGIN
		SET @Id_Trans_CA	= 0
		SET @Item			= 0
	END

	IF NOT EXISTS (	SELECT 1 
					FROM Cbtes_Aplica 
					WHERE 
					Id_Trans = @Id_Trans_CA
					AND	Item = @Item
					AND	Id_Trans_D = @pId_Trans
					AND	Item_D = @Item_D)
    BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Inserta Cbtes_Aplica'
		END

		INSERT INTO dbo.Cbtes_Aplica
		(Id_Trans,			Item,				Id_Trans_D,
		Item_D,				Cantidad,			Importe,
		Fecha_Aplic)
		VALUES
		(@Id_Trans_CA,		@Item,				@pId_Trans,
		@Item_D,			@Cantidad,			@pImporte_A_Cancelar,
		@Fecha_Aplic)
    END
	ELSE
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Actualiza Cbtes_Aplica'
		END

		UPDATE Cbtes_Aplica
		SET 
		Importe = Importe + @pImporte_A_Cancelar
		WHERE 
		Id_Trans = @Id_Trans_CA
		AND	Item = @Item
		AND	Id_Trans_D = @pId_Trans
		AND	Item_D = @Item_D
	END
	/*****************************************************************************/
	
	IF ((@pId_Trans_A_Cancelar <> 0) AND (@Id_Estado_Cbte_Id_Trans_Origen IN (1,4)/*Pendiente*/))
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Actualiza Id_Trans_A_Cancelar: ' +  CONVERT(VARCHAR(10), @pId_Trans_A_Cancelar)
		END

	    IF @Saldo_Cbte - ABS(@pImporte_A_Cancelar) <= 0
		BEGIN
			UPDATE Cbtes SET Id_Estado_Cbte = 2, Saldo = 0 WHERE Id_Trans = @pId_Trans_A_Cancelar
			UPDATE Cbtes_Items SET Id_Estado_Cbte = 2 WHERE Id_Trans = @pId_Trans_A_Cancelar
			UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 2, Saldo = 0 WHERE Id_Trans = @pId_Trans_A_Cancelar
        END
		ELSE
		BEGIN
			UPDATE Cbtes SET Id_Estado_Cbte = 4, Saldo = Saldo - ABS(@pImporte_A_Cancelar) WHERE Id_Trans = @pId_Trans_A_Cancelar
			UPDATE Cbtes_Items SET Id_Estado_Cbte = 4 WHERE Id_Trans = @pId_Trans_A_Cancelar
			UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 4, Saldo = Saldo - @pImporte_A_Cancelar WHERE Id_Trans = @pId_Trans_A_Cancelar

		END
	END

	/*****************************************************************************/

	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	
	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('item', @Item, 'SMALLINT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_producto', @pId_Producto, 'VARCHAR')  + ',' +
									dbo.CF_Json_ParsearVariable('id_estado_cbte', @Id_estado_Cbte, 'INT')  + ','  +
									dbo.CF_Json_ParsearVariable('Importe', @Imp_Final, 'DECIMAL') + ',' +
									dbo.CF_Json_ParsearVariable('Importe_A_Cancelar', @pImporte_A_Cancelar, 'DECIMAL') +
									'}'

		SELECT		0						AS ErrorNumber 
					,0						AS ErrorSeverity  
					,0						AS ErrorState 
					,0						AS ErrorProcedure  
					,0						AS ErrorLine		
					,@rtaMsjStored			AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Rec_Generar_Item'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	
	RETURN 9999
END CATCH

RETURN 0
GO




CREATE PROCEDURE [dbo].[CPJ_Cbtes_Rec_Generar_Pago] @pJson VARCHAR(8000)
AS
SET NOCOUNT ON


/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Trans				INT
DECLARE @pId_Tipo_Val			CHAR(3)
DECLARE @pValor_Nro				INT
DECLARE @pFecha_Val				DATETIME
DECLARE @pFecha_Emision			DATETIME
DECLARE @pFecha_Acreditacion	DATETIME
DECLARE @pFecha_Vence			DATETIME
DECLARE @pImporte				DECIMAL(12,2)
DECLARE @pId_Tarjeta			VARCHAR(10)
DECLARE @pTarjeta_Nro			VARCHAR(25)
DECLARE @pTarjeta_Vence			DATETIME
DECLARE @pTarjeta_Lote			SMALLINT
DECLARE @pId_Cta_banco			SMALLINT
DECLARE @pRtaMsjStored			TINYINT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')),0)
SET @pId_Tipo_Val				= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Val')),'')
SET @pValor_Nro					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Valor_Nro')),0)
SET @pFecha_Val					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Val')),GETDATE())
SET @pFecha_Emision				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Emision')),GETDATE())
SET @pFecha_Acreditacion		= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Acreditacion')),GETDATE())
SET @pFecha_Vence				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Vence')),GETDATE())
SET @pImporte					= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Importe')),0)
SET @pId_Tarjeta				= ISNULL(CONVERT(VARCHAR(25), dbo.CF_JSON_VALUE(@pJson,'Id_Tarjeta')),'')
SET @pTarjeta_Nro				= ISNULL(CONVERT(VARCHAR(25), dbo.CF_JSON_VALUE(@pJson,'Tarjeta_Nro')),'') 
SET @pTarjeta_Vence				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Tarjeta_Vence')),GETDATE())
SET @pTarjeta_Lote				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Tarjeta_Lote')),0)
SET @pId_Cta_banco				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cta_banco')),0)
SET @pRtaMsjStored				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'RtaMsjStored')), 0)

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Valor				INT
DECLARE @Id_Valor_Origen		INT
DECLARE @Id_Estado_Valor		SMALLINT
DECLARE @Descripcion			VARCHAR(50)
DECLARE @Id_Cliente				INT
DECLARE @Id_Proveedor			INT
DECLARE @Id_Banco				SMALLINT
DECLARE @Id_Cta_Banco			SMALLINT
DECLARE @Id_Mov_Caja			INT
DECLARE @Id_Moneda				CHAR(3)
DECLARE @Cotizacion				DECIMAL(9,4)
DECLARE @Id_Periodo_Caja		INT
DECLARE @Propio					TINYINT
DECLARE @Transferible			TINYINT
DECLARE @Cuit					VARCHAR(13)
DECLARE @Id_Chequera			INT
DECLARE @Renglon_Nro_Caja		SMALLINT
DECLARE @Flag_Conciliado		TINYINT
DECLARE @Fecha_Conci			DATETIME
DECLARE @Tarjeta_Cant_Cuotas	TINYINT
DECLARE @Tarjeta_Imp_Cuota		DECIMAL(12,2)
DECLARE @Tarjeta_Crit_Cuota		CHAR(1)

DECLARE @pTarjeta_Cod_Seguridad	INT	
DECLARE @pTarjeta_Cod_Autoriz	INT

DECLARE @Flag_Existe_Tipo_Valor	TINYINT

DECLARE @Renglon_Nro			SMALLINT
DECLARE @Id_Motivo_Estado		SMALLINT
DECLARE @Fecha					DATETIME

DECLARE @Id_Estado_Mov_Caja		INT
DECLARE @Id_Tipo_Mov_Caja		SMALLINT
DECLARE @Lote					VARCHAR(20)

DECLARE @Id_Mov_Cta_Banco		INT


DECLARE @Mensaje				VARCHAR(100)
/*Fin de Declaraciones Variables Locales */

BEGIN TRY
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Rec_Generar_Pago'
		PRINT 'Parametros: '
		PRINT 'Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans) + ' Id_Tipo_Val: ' + @pId_Tipo_Val + ' Valor_Nro: ' + CONVERT(VARCHAR(20), @pValor_Nro) + ' Fecha_Val: ' + CONVERT(VARCHAR(10), @pFecha_Val,103) + ' Fecha_Emision: ' + CONVERT(VARCHAR(10), @pFecha_Emision,103)
		PRINT 'Fecha_Acreditacion: ' + CONVERT(VARCHAR(10),@pFecha_Acreditacion,103) + 'Fecha_Vence: ' + CONVERT(VARCHAR(10),@pFecha_Vence,103) + 'Importe: ' + CONVERT(VARCHAR(50),@pImporte) + 'Id_Tarjeta: ' + @pId_Tarjeta + 'Tarjeta_Nro: ' + @pTarjeta_Nro + 'Tarjeta_Vence: ' + CONVERT(VARCHAR(10),@pTarjeta_Vence,103)
 		PRINT 'Tarjeta_Lote: ' + CONVERT(VARCHAR(10),@pTarjeta_Lote) + '@pId_Cta_banco: ' + CONVERT(VARCHAR(10),@pId_Cta_banco)
 	END
	
	/*Validaciones****************************************************************************/

	SET @Flag_Existe_Tipo_Valor = ISNULL((SELECT 1 FROM Valores_Tipos WHERE Id_Tipo_Val = @pId_Tipo_Val), 0)
	IF (@Flag_Existe_Tipo_Valor = 0)  RAISERROR ('Flag_Existe_Tipo_Valor can not be zero.', 16,  1 ) 
	IF(@pId_Trans = 0) RAISERROR ('Id_Trans can not be zero.', 16,  1 ) 

	/*************************************************************************************************/
		SET @rtaMsjStored		=	'{' +
										dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
										dbo.CF_Json_ParsearVariable('Id_Tipo_Val', @pId_Tipo_Val, 'CHAR(3)')  + ',' +
										dbo.CF_Json_ParsearVariable('Val_Nro', @pValor_Nro, 'INT')  + ',' +
										dbo.CF_Json_ParsearVariable('Id_Tarjeta',@pId_Tarjeta,'VARCHAR(25)')+ ',' +
										dbo.CF_Json_ParsearVariable('Importe', @pImporte, 'DECIMAL') +
									'}'
			
		IF (@pRtaMsjStored = 0)
		BEGIN
			SELECT	 0					AS ErrorNumber 
					,0					AS ErrorSeverity  
					,0					AS ErrorState 
					,0					AS ErrorProcedure  
					,0					AS ErrorLine		
					,@rtaMsjStored		AS ErrorMessage
		END
	/**************************************************************************************************/					

	SELECT  @Id_Cliente		= ISNULL(Id_Cliente, 0),
			@Id_Moneda		= ISNULL(Id_Moneda, 'PES'),
			@Cotizacion		= ISNULL(Cotizacion, 1),
			@Cuit			= ISNULL(Cuit, ''),
			@Fecha			= Fecha
	FROM Cbtes
	WHERE 
	Id_Trans = @pId_Trans

	/*****************************************************************************/
	
	SELECT  @Id_Periodo_Caja = ISNULL(Id_Periodo_Caja, 0)
	FROM Cajas_Mov
	WHERE 
	Id_Trans = @pId_Trans

	/*****************************************************************************/
    SET @Id_Estado_Valor	= 4  /*'COMPLETO'*/

	IF @pId_Tipo_Val IN ('TAR','CH3','CHP','CUP')    /*TK 07749 7/5/24 VICTOR  EN CARTERA */ 
		SET @Id_Estado_Valor	= 3

	IF @pId_Tipo_Val IN ('DB','CTA')    /*TK 07749 7/5/24 VICTOR  DEPOSITADO */ 
		   SET @Id_Estado_Valor	= 2	    

	IF @pId_Tipo_Val IN ('FIN')         /* 24/4/25 VICTOR  DEPOSITADO */ 
	  BEGIN
		   SET @Id_Estado_Valor	= 2
		   SET @pId_Cta_Banco   = (SELECT ISNULL(Id_Cta_Banco,0) FROM Valores_Tarjetas_Cred WHERE Id_Tarjeta = @pId_Tarjeta)
      END

	SET @Id_Valor				= (SELECT MAX(ISNULL(Id_Valor,0)) + 1 FROM Valores)
	SET @Id_Valor_Origen		= 0
	
	SET @Descripcion			= (SELECT ISNULL(Descripcion, '') FROM Valores_Tipos WHERE Id_Tipo_Val = @pId_Tipo_Val)
	SET @Id_Proveedor			= 0
	SET @Id_Banco				= (SELECT ISNULL(ID_Banco,0) FROM Bancos_Ctas WHERE Id_Cta_Banco = @pId_Cta_Banco)
	SET @Id_Cta_Banco			= @pId_Cta_Banco
	SET @Id_Mov_Caja			= 0
	SET @Propio					= 0
	SET @Transferible			= 0
	SET @Id_Chequera			= 0
	SET @Renglon_Nro_Caja		= 1
	SET @Flag_Conciliado		= 0
	--SET @Fecha_Conci NULL
	SET @Tarjeta_Cant_Cuotas	= 0
	SET @Tarjeta_Imp_Cuota		= 0
	SET @Tarjeta_Crit_Cuota		= ''

	IF @pFecha_Val = '19000101'
	   SET @pFecha_Val = @pFecha_Vence
	IF @pFecha_Emision = '19000101'
	   SET @pFecha_Emision = @pFecha_Vence
	IF @pFecha_Acreditacion = '19000101'
	   SET @pFecha_Acreditacion = @pFecha_Vence	 

	INSERT INTO dbo.Valores
	(Id_Valor,						Id_Valor_Origen,			Id_Trans,
	Id_Estado_Valor,				Id_Tipo_Val,				Valor_Nro,
	Descripcion,					Fecha_Val,					Fecha_Emision,
	Fecha_Acreditacion,				Fecha_Vence,				Id_Cliente,
	Id_Proveedor,					Id_Banco,					Id_Cta_Banco,
	Id_Mov_Caja,					Id_Moneda,					Importe,
	Id_Tarjeta,						Tarjeta_Nro,				Tarjeta_Vence,
	Tarjeta_Cod_Seguridad,			Tarjeta_Cod_Autoriz,		Cotizacion,
	Id_Periodo_Caja,				Propio,						Transferible,
	Cuit,							Tarjeta_Lote,				Id_Chequera,
	Renglon_Nro_Caja,				Flag_Conciliado,			Fecha_Conci,
	Tarjeta_Cant_Cuotas,			Tarjeta_Imp_Cuota,			Tarjeta_Crit_Cuota)
	VALUES
	(@Id_Valor,						@Id_Valor_Origen,			@pId_Trans,
	@Id_Estado_Valor,				@pId_Tipo_Val,				@pValor_Nro,
	@Descripcion,					@pFecha_Val,				@pFecha_Emision,
	@pFecha_Acreditacion,			@pFecha_Vence,				@Id_Cliente,
	@Id_Proveedor,					@Id_Banco,					@Id_Cta_Banco,
	@Id_Mov_Caja,					@Id_Moneda,					@pImporte,
	@pId_Tarjeta,					@pTarjeta_Nro,				@pTarjeta_Vence,
	@pTarjeta_Cod_Seguridad,		@pTarjeta_Cod_Autoriz,		@Cotizacion,
	@Id_Periodo_Caja,				@Propio,					@Transferible,
	@Cuit,							@pTarjeta_Lote,				@Id_Chequera,
	@Renglon_Nro_Caja,				@Flag_Conciliado,			@Fecha_Conci,
	@Tarjeta_Cant_Cuotas,			@Tarjeta_Imp_Cuota,			@Tarjeta_Crit_Cuota)

	/*****************************************************************************/
	
	SET @Renglon_Nro = 1
	SET @Id_Motivo_Estado = 0
	SET @Descripcion = ''

	INSERT INTO dbo.Valores_Mov
	(Id_Valor,					Renglon_Nro,				Id_Trans,
	Id_Motivo_Estado,			Id_Estado_Valor,			Id_Periodo_Caja,
    Descripcion,				Fecha_Acreditacion,			Fecha,
    Renglon_Nro_Caja)
	VALUES
	(@Id_Valor,					@Renglon_Nro,				@pId_Trans,
	@Id_Motivo_Estado,			@Id_Estado_Valor,			@Id_Periodo_Caja,
    @Descripcion,				@pFecha_Acreditacion,		@Fecha,
    @Renglon_Nro_Caja)
	
	/*****************************************************************************/
	
	IF (@pId_Tipo_Val = 'DB' or @pId_Tipo_Val = 'FIN') and @pId_Cta_banco <> 0
	BEGIN
		SET @Id_Mov_Cta_Banco = (SELECT MAX(ISNULL(Id_Mov_Cta_Banco,0)) + 1 FROM bancos_ctas_mov)
		SET @Lote = (SELECT ISNULL(lote,'') FROM Cbtes where id_Trans = @pId_Trans)
		
		INSERT INTO bancos_ctas_mov 
			(Id_Mov_Cta_Banco,			Id_Trans,					Id_Cta_Banco,			Id_Tipo_Mov_Cta_Banco,	
			Importe,					Id_Est_Mov_Cta_Banco, 		Comprobante_Nro,		Conciliado, 
			Fecha_Acreditacion,			Descripcion,				Fecha_Mov)
		VALUES (@Id_Mov_Cta_Banco,		@pId_Trans,					@pId_Cta_banco,			9/*Deposito*/,	
			@pImporte,					1,							@Lote,					0,
			@pFecha_Acreditacion,		@Lote,						@pFecha_Emision)
	END
	
	/*****************************************************************************/

	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	

	SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('Id_Tipo_Val', @pId_Tipo_Val, 'CHAR(3)')  + ',' +
									dbo.CF_Json_ParsearVariable('Val_Nro', @pValor_Nro, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('Id_Tarjeta',@pId_Tarjeta,'VARCHAR(25)')+ ',' +
									dbo.CF_Json_ParsearVariable('Importe', @pImporte, 'DECIMAL') +
								'}'
	IF (@pRtaMsjStored = 0)
	BEGIN
	SELECT	 0						AS ErrorNumber 
			,0						AS ErrorSeverity  
			,0						AS ErrorState 
			,0						AS ErrorProcedure  
			,0						AS ErrorLine		
			,@rtaMsjStored			AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Rec_Generar_Pago'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	
	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Rec_Web_Completar] @pJson VARCHAR(8000)

AS
SET NOCOUNT ON
/*
 * LOG VERSIONES:
 * 12/12/2023: Se agrego Log de Versiones
 * Uso: Solo completa (No genera) recibos web donde exista el nro Operacion en WebProcesos
 * Casos de uso:
 *			1. Items faltantes
 *			2. Medios de Pagos Faltantes
 *			3. Cbte en carga y sin numero de comprobante
 *
 * Modo de uso: EXEC CPJ_Cbtes_Rec_Web_Completar '{"ModoDebug":"1" ,"Id_Trans":"1316787"}'
 * Retorno: 	ErrorNumber	ErrorSeverity	ErrorState	ErrorProcedure	ErrorLine	ErrorMessage
 *			S:	0			0				0			0				0			Recibo Completado | Nro. Operacion no abierta | Las transacciones asociadas estan aplicadas a otro comprobante, quedando la operación en estado parcial o pago a cuenta
 *			E:	70001		0				0			0				0			Transaccion no abierta									
*/

/*Declaracion Variables Json*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Trans				INT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
/*Fin Declaracion Variables Json*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Json								VARCHAR(4000)
DECLARE @Transacciones						VARCHAR(4000)
DECLARE @Id_Cliente							INT
DECLARE @Lote								VARCHAR(100)
DECLARE @Index								INT = 1
DECLARE @Id_Trans_Fac						INT
DECLARE @Saldo_Fac							DECIMAL (20,2)
DECLARE @Items_Trans						SMALLINT
DECLARE @Items_Rec							SMALLINT
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
DECLARE @Result_Stored_Invocado				INT
DECLARE @Aplicado							SMALLINT
DECLARE	@Existe_Valores						SMALLINT
DECLARE @Importe							DECIMAL(20,2)
DECLARE @Id_Tipo_Val						CHAR(3)
DECLARE @Id_Tarjeta							VARCHAR(10)
DECLARE @Tar_Cod_Autorizar					VARCHAR(10)
DECLARE @Tar_Lote							SMALLINT
DECLARE @Tipo_Valor_Recibo_VW				CHAR(3)
DECLARE @Id_Cta_Banco_CWeb					INT
DECLARE @Fecha								DATETIME
DECLARE @Resultado							VARCHAR(200)
DECLARE @Trans_Aplicadas					SMALLINT
DECLARE @Cbtes_Saldo						SMALLINT
DECLARE @Tipo_Operacion						VARCHAR(1)
/*Fin de Declaraciones Variables Locales */

BEGIN TRY
	
	IF (@pFlagUsarTrans <> 0 )
	BEGIN
		BEGIN TRAN
	END

	/*===================================================================================================================================================================*/	

	IF (@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Rec_Web_Completar'
		PRINT 'Parametros:'	
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + ' Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans)
	END
	
	/*===================================================================================================================================================================*/

	IF(@pId_Trans = 0)
	BEGIN
		SET @rtaErrorStored = 70001 /*Transaccion no abierta*/
		
		SELECT	 @rtaErrorStored	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,''					AS ErrorMessage
			
		IF (@pFlagUsarTrans <> 0)
		BEGIN
			ROLLBACK
		END
		
		RETURN 9999
	END

	/*===================================================================================================================================================================*/

	IF OBJECT_ID('tempdb..#Transacciones') IS NOT NULL
	BEGIN
		DROP TABLE #Transacciones
	END

	CREATE TABLE #Transacciones (Id_Trans	INT
								, Saldo		DECIMAL(20,2)
								, Aplicado	SMALLINT)

	IF OBJECT_ID('tempdb..#Valores') IS NOT NULL
	BEGIN
		DROP TABLE #Valores
	END

	CREATE TABLE #Valores (Id_Tipo_Val					CHAR(3)
						  , Id_Tarjeta					VARCHAR(10)
						  , Tar_Cod_Autorizar			VARCHAR(10)
						  , Tar_Lote					SMALLINT
						  , Importe_Total				DECIMAL(20,2)
						  , Importe_Total_Con_Recargo	DECIMAL(20,2))
						  
	IF OBJECT_ID('tempdb..#Json_Trans') IS NOT NULL
	BEGIN
		DROP TABLE #Json_Trans
	END

	CREATE TABLE #Json_Trans (Id						INT
							 ,ColumnA					VARCHAR(4000))

	/*===================================================================================================================================================================*/

	-- (1) Datos de la Operacion (WebProcesos)
	SET @Lote = ISNULL((SELECT Lote FROM Cbtes WHERE Id_Trans = @pId_Trans),'')
	SET @Json = ISNULL((SELECT Json FROM WebProcesos WHERE Nro_Operacion = @Lote),'')
	SET @Transacciones = ISNULL(CONVERT(VARCHAR(4000), dbo.CF_JSON_VALUE(@Json,'transacciones')), '')


	IF(@Json <> '')
	BEGIN
		
		SET @Resultado = ''

		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Datos | Json: ' + CONVERT(VARCHAR(4000), @Json) + ' Transacciones: '  + CONVERT(VARCHAR(4000), @Transacciones)
		END

		SET @Items_Trans = (LEN(@Transacciones) - LEN(REPLACE(@Transacciones, '"id_trans"', ''))) / LEN('"id_trans"')

		WHILE @Index <= @Items_Trans
		BEGIN
			
			INSERT INTO #Json_Trans (Id, ColumnA)
			SELECT Id,
				   ColumnA
			FROM dbo.CF_Split(@Transacciones, '},{') 
			WHERE Id = @Index

			UPDATE #Json_Trans
			SET ColumnA = STUFF(ColumnA, 1, 1, '')
			WHERE (CHARINDEX('{', ColumnA) = 1
				   OR CHARINDEX('}', ColumnA) = 1
				   OR CHARINDEX(',{', ColumnA) = 1)

			SELECT @Id_Trans_Fac = CONVERT(INT, dbo.CF_JSON_VALUE(ColumnA,'Id_Trans'))
				  ,@Saldo_Fac = CONVERT(DECIMAL(20,2), dbo.CF_JSON_VALUE(ColumnA,'Saldo'))
			FROM #Json_Trans WHERE Id = @Index

			/*--Version simplificada-- (JSON_VALUE funciona a partir de versiones 2016 de sql)
			SET @Id_Trans_Fac = CONVERT(INT, JSON_VALUE(@Json, '$.transacciones[' + CAST(@Index AS NVARCHAR(MAX)) + '].id_trans'))
			SET @Saldo_Fac = CONVERT(DECIMAL(20,2), JSON_VALUE(@Json, '$.transacciones[' + CAST(@Index AS NVARCHAR(MAX)) + '].saldo'))
			*/

			INSERT INTO #Transacciones (Id_Trans, Saldo) VALUES (@Id_Trans_Fac, @Saldo_Fac)

			SET @Index = @Index + 1
		END


		INSERT INTO #Valores (Id_Tipo_Val, Id_Tarjeta, Tar_Cod_Autorizar, Tar_Lote, Importe_Total, Importe_Total_Con_Recargo)
					VALUES	 (ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@Json,'Id_Tipo_Val')), '')
							 ,ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@Json,'id_tarjeta')), '')
							 ,ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@Json,'tar_cod_autorizar')), '')
							 ,ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@Json,'tar_lote')), 0)
							 ,ISNULL(CONVERT(DECIMAL(20,2), dbo.CF_JSON_VALUE(@Json,'importe_total')), 0)
							 ,ISNULL(CONVERT(DECIMAL(20,2), dbo.CF_JSON_VALUE(@Json,'importe_total_con_recargo')), 0))


		-- (2) Verificar Items del Recibo
		SET @Items_Rec = (SELECT COUNT(*) AS Items FROM Cbtes_Items WHERE Id_Trans = @pId_Trans)

			-- Si no corresponden la cantidad de items abonados al recibo generado, eliminar registros incompletos y volver a generar
		IF (@Items_Trans <> @Items_Rec)
		BEGIN

			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Se generan los items del cbte'
			END

			DELETE FROM Cbtes_Items 	WHERE Id_Trans = @pId_Trans
			DELETE FROM Clientes_CtaCte WHERE Id_Trans = @pId_Trans
			DELETE FROM Cbtes_Aplica	WHERE Id_Trans_D = @pId_Trans AND Id_Trans = 0

			SET @Index = 1
			DECLARE @Id_Trans_A_Aplicar INT
			DECLARE @Saldo				DECIMAL(20,2)
			DECLARE curFacInicializar_Agregar CURSOR FOR
			SELECT Id_Trans, Saldo FROM #Transacciones

			OPEN curFacInicializar_Agregar
			FETCH NEXT FROM curFacInicializar_Agregar INTO @Id_Trans_A_Aplicar, @Saldo
			WHILE @@FETCH_STATUS = 0
			BEGIN
				
				IF(@pModoDebug = 1)
				BEGIN
					PRINT 'Id_Trans_A_Aplicar: ' + CONVERT(VARCHAR(20),@Id_Trans_A_Aplicar)
				END
				
				-- Verifico si las transacciones ya no estan aplicadas a otro cbte, de ser asi no se pasan por el fac_fin 
				SET @Cbtes_Saldo = ISNULL((SELECT 1 FROM Cbtes 
													WHERE Id_Trans = @Id_Trans_A_Aplicar 
													AND (EXISTS (SELECT Id_Trans FROM Cbtes_Aplica 
																				WHERE Id_Trans_D = @pId_Trans 
																				AND Id_Trans = @Id_Trans_A_Aplicar)
													OR Saldo > 0)
											), 0)
											
				DELETE FROM Cbtes_Aplica WHERE Id_Trans_D = @pId_Trans AND Id_Trans = @Id_Trans_A_Aplicar
				
				IF (@Cbtes_Saldo = 1)
				BEGIN
					SET @JSON_Parametros_Stored_Invocado =	
					'{' + dbo.CF_Json_ParsearVariable('Flag_Renumerar', 0, 'TINYINT') + ',' +
						  dbo.CF_Json_ParsearVariable('Id_Trans', @Id_Trans_A_Aplicar, 'TINYINT') +
					'}'				

					EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Fac_Fin @JSON_Parametros_Stored_Invocado
				END
				
				SET @JSON_Parametros_Stored_Invocado =	
						'{' + dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'TINYINT') + ',' +
							  --dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'TINYINT') + ',' +
							  dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'TINYINT') + ',' +
							  dbo.CF_Json_ParsearVariable('Item', @Index, 'SMALLINT') + ',' +
							  dbo.CF_Json_ParsearVariable('Id_Producto', '', 'VARCHAR(20)') + ',' +
							  dbo.CF_Json_ParsearVariable('Cantidad', 1, 'DECIMAL(15,5)') + ',' +
							  dbo.CF_Json_ParsearVariable('Id_Trans_A_Cancelar', @Id_Trans_A_Aplicar, 'INT') + ',' +
							  dbo.CF_Json_ParsearVariable('Importe_A_Cancelar', @Saldo, 'DECIMAL(16,2)') + ',' +
							  dbo.CF_Json_ParsearVariable('Omitir_Resultado_OK', 1, 'TINYINT') + 
						'}'	

				EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Rec_Generar_Item @JSON_Parametros_Stored_Invocado

				SET @Index = @Index + 1

				SET @Aplicado =  ISNULL((SELECT 1 FROM Cbtes_Aplica WHERE Id_Trans = @Id_Trans_A_Aplicar AND Id_Trans_D = @pId_Trans),0)
				UPDATE #Transacciones SET Aplicado = @Aplicado WHERE Id_Trans = @Id_Trans_A_Aplicar

			FETCH NEXT FROM curFacInicializar_Agregar INTO @Id_Trans_A_Aplicar, @Saldo
			END
			CLOSE curFacInicializar_Agregar
			DEALLOCATE curFacInicializar_Agregar

			SET @Trans_Aplicadas = ISNULL((SELECT SUM(Aplicado) FROM #Transacciones), 0)

			IF(@Trans_Aplicadas < @Items_Trans)
			BEGIN
				SET @Resultado = 'Las transacciones asociadas estan aplicadas a otro comprobante, quedando la operación en estado parcial o pago a cuenta.'
			END

		END


		-- (3) Verificar Valores del Recibo
		SET @Existe_Valores = ISNULL((SELECT 1 FROM Cbtes C, Valores V  WHERE C.Id_Trans = V.Id_Trans AND C.Id_Trans = @pId_Trans),0) 

		IF (@Existe_Valores = 0)
		BEGIN

			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Se genera los valores del cbte'
			END

			SET @Tipo_Valor_Recibo_VW = DBO.CF_xParam('Tipo_Valor_Recibo_VW')
			SET @Id_Cta_Banco_CWeb	  = DBO.CF_xParam('Id_Cta_Baco_CWeb')

			SELECT  @Id_Tipo_Val = 
					CASE 
						WHEN ISNULL(@Id_Tarjeta, '') <> '' THEN
							'TAR'
						WHEN ISNULL((SELECT Id_Tipo_Val), '') = '' THEN
							@Tipo_Valor_Recibo_VW
						ELSE
							ISNULL((SELECT Id_Tipo_Val), '')
					END,
					@Id_Tarjeta = ISNULL((SELECT Id_Tipo_Val), ''),
					@Tar_Cod_Autorizar = ISNULL((SELECT Id_Tipo_Val), ''),
					@Tar_Lote = ISNULL((SELECT Id_Tipo_Val), 0),
					@Importe = 
					CASE 
						WHEN ISNULL((SELECT Importe_Total_Con_Recargo), 0) = 0 THEN
							ISNULL((SELECT Importe_Total FROM #Valores), 0)
						ELSE
							ISNULL((SELECT Importe_Total_Con_Recargo), 0)
					END,
					@Fecha = CONVERT(DATE, GETDATE())
			FROM #Valores

			SET @JSON_Parametros_Stored_Invocado =	
				'{' + dbo.CF_Json_ParsearVariable('Flag_Renumerar', 0, 'TINYINT') + ',' +
					  --dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'TINYINT') + ',' +
					  dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'TINYINT') + ',' +
					  dbo.CF_Json_ParsearVariable('Id_Tipo_Val', @Id_Tipo_Val, 'CHAR(3)') + ',' +
					  dbo.CF_Json_ParsearVariable('Valor_Nro', 1, 'INT') + ',' +
					  dbo.CF_Json_ParsearVariable('Fecha_Val', @Fecha, 'DATETIME') + ',' +
					  dbo.CF_Json_ParsearVariable('Fecha_Emision', @Fecha, 'DATETIME') + ',' +
					  dbo.CF_Json_ParsearVariable('Fecha_Acreditacion', @Fecha, 'DATETIME') + ',' +
					  dbo.CF_Json_ParsearVariable('Fecha_Vence', @Fecha, 'DATETIME') + ',' +
					  dbo.CF_Json_ParsearVariable('Importe', @Importe, 'DECIMAL(20,2)') + ',' +
					  dbo.CF_Json_ParsearVariable('Id_Tarjeta', @Id_Tarjeta, 'VARCHAR(25)') + ',' +
					  dbo.CF_Json_ParsearVariable('Tarjeta_Nro', '', 'VARCHAR(25)') + ',' +
					  dbo.CF_Json_ParsearVariable('Tarjeta_Vence', @Fecha, 'DATETIME') + ',' +
					  dbo.CF_Json_ParsearVariable('Tarjeta_Lote', @Tar_Lote, 'SMALLINT') + ',' +
					  dbo.CF_Json_ParsearVariable('Id_Cta_banco', @Id_Cta_Banco_CWeb, 'INT') + ',' +
					  dbo.CF_Json_ParsearVariable('RtaMsjStored', 1, 'TINYINT') + 
				'}'				

			EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Rec_Generar_Pago @JSON_Parametros_Stored_Invocado

		END


		-- (4) Completar Recibo
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Se ejecuta el Rec Fin'
		END

		SET @JSON_Parametros_Stored_Invocado =	
				'{' + dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'INT') + ',' +
					  dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'TINYINT') + ',' +
					  dbo.CF_Json_ParsearVariable('Flag_Renumerar', 1, 'TINYINT') + ',' + 
					  dbo.CF_Json_ParsearVariable('Omitir_Resultado_OK', 1, 'TINYINT') + 
				'}'

		EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Rec_Fin @JSON_Parametros_Stored_Invocado


		-- (5) Respuesta
		IF(@Resultado = '')
		BEGIN
			SET @Resultado = 'Recibo Completado.'
		END

	END
	ELSE
	BEGIN
		SET @Tipo_Operacion = (ISNULL((SELECT LEFT(Lote, 1) FROM Cbtes WHERE Id_Trans = @pId_Trans), ''))
		IF(@Tipo_Operacion = 'N')
		BEGIN

			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Operacion de Nuevo Socio.'
			END

			SET @JSON_Parametros_Stored_Invocado =	
					'{' + dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'INT') + ',' +
					      dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'TINYINT') + ',' +
						  dbo.CF_Json_ParsearVariable('Flag_Renumerar', 1, 'TINYINT') + ',' + 
						  dbo.CF_Json_ParsearVariable('Omitir_Resultado_OK', 1, 'TINYINT') + 
					'}'

			EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Rec_Fin @JSON_Parametros_Stored_Invocado

			SET @Resultado = 'Recibo Completado.'
			
		END
		ELSE
		BEGIN
			SET @Resultado = 'Nro. Operacion no abierta.'
		END
	END
	/*===================================================================================================================================================================*/
	
		IF OBJECT_ID('tempdb..#Transacciones') IS NOT NULL
		BEGIN
			DROP TABLE #Transacciones
		END

		IF OBJECT_ID('tempdb..#Valores') IS NOT NULL
		BEGIN
			DROP TABLE #Valores
		END
		
		IF OBJECT_ID('tempdb..#Json_Trans') IS NOT NULL
		BEGIN
			DROP TABLE #Json_Trans
		END

	/*===================================================================================================================================================================*/

	IF (@pFlagUsarTrans <> 0)
	BEGIN
		COMMIT
	END

		SET @rtaMsjStored	=	@Resultado + ' Trans: ' + CONVERT(VARCHAR(20), @pId_Trans)

		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Rec_Web_Completar'
	END

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF (@pFlagUsarTrans <> 0 )
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO

 

CREATE PROCEDURE [dbo].[CPJ_Cbtes_Rem_Compra_Fin] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans		     	TINYINT
DECLARE @pModoDebug			    	TINYINT
DECLARE @pId_Trans				    INT
DECLARE @pObservacion_Incluye_Integ VARCHAR(8000)
DECLARE @pFlag_Tabla_Temp           TINYINT
DECLARE @pRtaMsjStored				TINYINT					--01/12/2022 Agregado	


SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pObservacion_Incluye_Integ = ISNULL(CONVERT(varchar(8000), dbo.CF_JSON_VALUE(@pObservacion_Incluye_Integ,'Observacion_Incluye_Integ')), '')
SET @pFlag_Tabla_Temp           = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pFlag_Tabla_Temp,'Flag_Tabla_Temp')), 0)
SET @pRtaMsjStored				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'RtaMsjStored')), 0)

/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
DECLARE @Result_Stored_Invocado				INT
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Cta_Contable					INT
DECLARE @Fecha								DATETIME
DECLARE @Observacion						VARCHAR(100)
DECLARE @Item								SMALLINT
DECLARE @Id_Estado_Cbte						SMALLINT

DECLARE @Descripcion_Cbte					VARCHAR(80)
DECLARE @Imp_Gravado_Sum_It					DECIMAL(12,2)
DECLARE @Porc_Bonificacion_Cb				DECIMAL(5,2)
DECLARE @Imp_Gravado						DECIMAL(12,2)
DECLARE @Imp_Iva_Sum_It						DECIMAL(12,2)
DECLARE @Imp_Iva							DECIMAL(12,2)
DECLARE @Imp_Exento							DECIMAL(12,2)
DECLARE @Imp_Total							DECIMAL(12,2)
DECLARE @Saldo								DECIMAL(12,2)
DECLARE @Imp_Bonificacion					DECIMAL(12,2)
DECLARE @Cantidad							DECIMAL(12,4)
/*Fin de Declaraciones Variables Locales */


BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Rem_Compra_Fin'
		PRINT 'Parametros:'
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + ' Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans)
	END
	
	/*===================================================================*/

	IF(@pId_Trans = 0)
	BEGIN
		SET @rtaErrorStored = 70001 /*Transaccion no abierta*/
		
		SELECT	 @rtaErrorStored	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,''					AS ErrorMessage
			
		IF @pFlagUsarTrans <> 0 
		BEGIN
			ROLLBACK
		END
		
		RETURN 9999
	END
	
	/*===================================================================*/	
		
											
	SET @JSON_Parametros_Stored_Invocado =	'{' +
											dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('RtaMsjStored', @pRtaMsjStored, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('FlagRegenerar', 1, 'TINYINT') + 
											'}'
						


	EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Grabar_Numero @JSON_Parametros_Stored_Invocado
	IF ISNULL(@Result_Stored_Invocado,0) <> 0 
	BEGIN
		/*El CPJ_Cbtes_Grabar_Numero deberia devolver el SELECT con el error*/
		RETURN 9999
	END	
	/*===================================================================*/
	
	SET @Descripcion_Cbte = (dbo.CF_Cbte_Descrip(@pId_Trans))
	
	/*===================================================================*/	
	
	UPDATE Transacciones SET Descripcion = @Descripcion_Cbte WHERE Id_Trans = @pId_Trans
	
	/*===================================================================*/	
	
	UPDATE Cbtes_Items 	SET Id_Estado_Cbte = 2	WHERE Id_Trans = @pId_Trans
	
	-- Actualizo el estado del comprobante segun el que tiene configurado en el tipo de cbte
	SELECT @Id_Estado_Cbte = ISNULL(T.Id_Estado_Cbte, 2) FROM Cbtes C
	JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
	WHERE C.Id_Trans = @pId_Trans
	
	UPDATE Cbtes  SET Id_Estado_Cbte = @Id_Estado_Cbte	WHERE Id_Trans = @pId_Trans
	
	/*===================================================================*/
		
	SET @Porc_Bonificacion_Cb	= ISNULL((SELECT ISNULL(Porc_Bonificacion, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans), 0)
	
	IF @pFlag_Tabla_Temp = 0
	   BEGIN
        	SET @Imp_Gravado_Sum_It		= ISNULL((SELECT SUM((ISNULL(Imp_Gravado, 0) * ISNULL(Cantidad_Saldo, 0))) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)
        	SET @Imp_Iva_Sum_It			= ISNULL((SELECT SUM(ISNULL(Imp_Iva, 0)) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)
 	        SET @Imp_Exento				= ISNULL((SELECT SUM((ISNULL(Imp_Exento, 0) * ISNULL(Cantidad_Saldo, 0))) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)
        	SET @Cantidad				= ISNULL((SELECT COUNT(*) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)  
       END
      ELSE
	   BEGIN
        	SET @Imp_Gravado_Sum_It		= ISNULL((SELECT SUM((ISNULL(Imp_Gravado, 0) * ISNULL(Cantidad_Saldo, 0))) FROM #ITEMS_CBTE), 0)
        	SET @Imp_Iva_Sum_It			= ISNULL((SELECT SUM(ISNULL(Imp_Iva, 0)) FROM #ITEMS_CBTE), 0)
 	        SET @Imp_Exento				= ISNULL((SELECT SUM((ISNULL(Imp_Exento, 0) * ISNULL(Cantidad_Saldo, 0))) FROM #ITEMS_CBTE), 0)
        	SET @Cantidad				= ISNULL((SELECT COUNT(*) FROM #ITEMS_CBTE), 0)  
       END        	
        	    	
	IF(@Porc_Bonificacion_Cb = 0)
		SET @Imp_Gravado		= @Imp_Gravado_Sum_It
	  ELSE
		SET @Imp_Gravado		= (@Imp_Gravado_Sum_It * ((100 - @Porc_Bonificacion_Cb) / 100))


	SET @Imp_Iva				= @Imp_Iva_Sum_It
	SET @Imp_Total				= @Imp_Gravado + @Imp_Iva + @Imp_Exento
	SET @Saldo					= @Imp_Total
	SET @Imp_Bonificacion		= (@Imp_Gravado_Sum_It - @Imp_Gravado)		


	
	/*===================================================================*/	
	IF @Imp_Iva = 0
	   BEGIN
	     SET @Imp_Exento = @Imp_Exento+@Imp_Gravado
		 SET @Imp_Gravado = 0
       END
	
	UPDATE Cbtes 
	SET 
	Cantidad			= @Cantidad,
	Imp_Gravado			= @Imp_Gravado, 
	Imp_Exento			= @Imp_Exento,
	Saldo				= @Saldo, 
	Imp_Iva				= @Imp_Iva,
	Imp_Bonificacion	= @Imp_Bonificacion,
	Imp_Total			= @Imp_Total,
	Observacion         = @pObservacion_Incluye_Integ 
	WHERE 
	Id_Trans = @pId_Trans

	/*===================================================================*/	
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	

	IF (@pRtaMsjStored = 0)
	BEGIN

		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT') + ',' +
									dbo.CF_Json_ParsearVariable('descrip_Cbte', @Descripcion_Cbte, 'VARCHAR') +
									'}'

		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage

	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Rem_Compra_Fin'
	END

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO



CREATE PROCEDURE [dbo].[CPJ_Cbtes_Rem_Compra_Generar] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans		TINYINT
DECLARE @pModoDebug			TINYINT
DECLARE @pId_Usuario		SMALLINT
DECLARE @pId_Trans			INT
DECLARE @pLote				VARCHAR(20)
DECLARE @pFecha				DATETIME
DECLARE @pFechaVence		DATETIME
DECLARE @pId_Proveedor		INT
DECLARE @pId_Tipo_Cbte		CHAR(4)
DECLARE @pId_Cond_Pago		SMALLINT
DECLARE @pId_Moneda			CHAR(3)
DECLARE @pCotizacion		DECIMAL(12,4)
DECLARE @pId_Contrato		INT
DECLARE @pNro_Auto_Trib		VARCHAR(14)
DECLARE @pCai_Vence			DATETIME
DECLARE @Bonif_Contrato     DECIMAL(5,2)
DECLARE @pId_Periodo_Caja	INT							--03/02/2021 Agregado
DECLARE @pId_Cobrador		VARCHAR(10)					--04/02/2021 Agregado
DECLARE @pId_Sucursal		SMALLINT
DECLARE @pComprobante_Nro	INT
DECLARE @pId_Centro_Costo	CHAR(10)
DECLARE @pImp_Exento		DECIMAL(12,2)
DECLARE @pImp_NoGravado		DECIMAL(12,2)
DECLARE @pImp_Gravado		DECIMAL(12,2)
DECLARE @pImp_Gravado2		DECIMAL(12,2)
DECLARE @pImp_Gravado3		DECIMAL(12,2)
DECLARE @pFlag_Req_Comp		INT
DECLARE @pRemito_Nro        INT
DECLARE @pOmitir_Resultado_Ok SMALLINT

SET @pOmitir_Resultado_Ok	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Resultado_OK')), 0)
SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Usuario			= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), -1)
SET @pId_Trans				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pLote					= ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Lote')), '')
SET @pFecha					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')),'19000101')
SET @pFechaVence			= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'FechaVence'))
SET @pId_Proveedor			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Proveedor')), 0)
SET @pId_Tipo_Cbte			= ISNULL(CONVERT(CHAR(4), dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Cbte')), '')
SET @pId_Cond_Pago			= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Cond_Pago')), '')
SET @pId_Moneda				= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Id_Moneda')), '')
SET @pCotizacion			= ISNULL(CONVERT(DECIMAL(12,4), dbo.CF_JSON_VALUE(@pJson,'Cotizacion')), 0)
SET @Bonif_Contrato			= ISNULL(CONVERT(DECIMAL(5,2), dbo.CF_JSON_VALUE(@pJson,'Bonif_Contrato')), 0)
SET @pId_Contrato			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Contrato')), 0)
SET @pNro_Auto_Trib			= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Nro_Auto_Trib')), '')
SET @pCai_Vence				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Cai_Vence')), '19000101')
SET @pId_Periodo_Caja		= ISNULL(CONVERT(INT,dbo.CF_JSON_VALUE(@pJson,'Id_Periodo_Caja')),0)
SET @pId_Cobrador			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Cobrador')), '')
SET @pId_Sucursal			= ISNULL(CONVERT(SMALLINT,dbo.CF_JSON_VALUE(@pJson,'Id_Sucursal')),0)
SET @pComprobante_Nro		= ISNULL(CONVERT(INT,dbo.CF_JSON_VALUE(@pJson,'Comprobante_Nro')),0)
SET @pRemito_Nro        	= ISNULL(CONVERT(INT,dbo.CF_JSON_VALUE(@pJson,'Remito_Nro')),0)
SET @pId_Centro_Costo		= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Centro_Costo')), '')
SET @pImp_Exento			= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_Exento')), 0)
SET @pImp_NoGravado			= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_NoGravado')), 0)
SET @pImp_Gravado			= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_Gravado')), 0)
SET @pImp_Gravado2			= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_Gravado2')), 0)
SET @pImp_Gravado3			= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_Gravado3')), 0)
SET @pFlag_Req_Comp			= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Flag_Req_Comp')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/


/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
