DECLARE @Id_Estado_Concepto	SMALLINT
DECLARE @Compromete_Stock	SMALLINT
DECLARE @Compromete_Remitos_Com TINYINT
 

/*Fin de Declaraciones Variables Locales */



BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Rem_Compra'
		PRINT 'Parametros:'
		PRINT 'pFlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans)  + '. pId_Usuario: ' + CONVERT(VARCHAR(10), @pId_Usuario) + '. pLote: ' + @pLote + ' pFecha: ' + CONVERT(VARCHAR(10), @pFecha, 103) + ' pFechaVence: ' + CONVERT(VARCHAR(10), @pFechaVence, 103) +  ' pId_Proveedor: ' + CONVERT(VARCHAR(10), @pId_Proveedor) + ' pId_Tipo_Cbte: ' + @pId_Tipo_Cbte + ' pId_Cond_Pago: ' + CONVERT(VARCHAR(10), @pId_Cond_Pago) + ' pId_Moneda: ' + @pId_Moneda + ' pCotizacion: ' + CONVERT(VARCHAR(10), @pCotizacion)
		PRINT 'pId_Contrato: ' + CONVERT(VARCHAR(10), @pId_Contrato) + '. pNro_Auto_Trib: ' + @pNro_Auto_Trib + '. @pCai_Vence: ' + CONVERT(VARCHAR(10), @pCai_Vence, 103) + '. pId_Periodo_Caja: ' + CONVERT(VARCHAR(10), @pId_Periodo_Caja)
		PRINT '@pImp_Exento: ' + CONVERT(VARCHAR(10), @pImp_Exento) + '. @pImp_NoGravado: ' + CONVERT(VARCHAR(10), @pImp_NoGravado) + '. @pImp_Gravado: ' + CONVERT(VARCHAR(10), @pImp_Gravado) + '. @pImp_Gravado2: ' + CONVERT(VARCHAR(10), @pImp_Gravado2) + '. @pImp_Gravado3: ' + CONVERT(VARCHAR(10), @pImp_Gravado3)					
		PRINT '@pId_Sucursal: ' + CONVERT(VARCHAR(10), @pId_Sucursal) + '@pComprobante_Nro: ' + CONVERT(VARCHAR(10), @pComprobante_Nro) + '@pId_Centro_Costo: ' + @pId_Centro_Costo
	END
	
	/*===================================================================*/


	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Inserta en Transacciones.'
	END
	
	IF(@pId_Trans = 0)
	BEGIN
		SET @pId_Trans		= ISNULL((SELECT MAX(Id_Trans) FROM Transacciones), 0) + 1
		INSERT INTO Transacciones 
		(Id_Trans,		Descripcion,						Fecha_Mov,
		Id_Usuario) 
		VALUES
		(@pId_Trans,	'Apertura CPJ_Transacciones_Abrir', GETDATE(), 
		@pId_Usuario)
	END


	/*===================================================================*/

	IF(@pId_Proveedor = 0)  RAISERROR ('Id_Proveedor can not be zero.', 16,  1 ) 
	IF NOT EXISTS(SELECT Id_Proveedor FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)  RAISERROR ('Id_Proveedor debe existir en la base.', 16,  1 ) 

	IF(@pId_Tipo_Cbte = '') RAISERROR ('Id_Tipo_Cbte can not be blank.', 16,  1 )
	IF(@pId_Sucursal = 0)  RAISERROR ('Id_Sucursal can not be zero.', 16,  1 ) 
		
	/*===================================================================*/
	
	IF(@pId_Usuario = 0)
	BEGIN
		SET @pId_Usuario = -1
	END
	
	IF(@pId_Moneda = '')
	BEGIN
		SET @pId_Moneda = dbo.CF_xParam('Moneda_Nacional')
	END

	IF(@pCotizacion = 0)
	BEGIN
		SET @pCotizacion = 1
	END
	
	IF(@pLote <> '')
	BEGIN
		SET @Flag_Lote	= 1
	END
	ELSE
	BEGIN
		SET @Flag_Lote	= 0
	END
	
	/*===================================================================*/

	SET @pFecha				= (SELECT CONVERT(DATE, @pFecha))
    SET @Id_Estado_Cbte		= 0  --siempre comienza en carga

	/*===================================================================*/

	SELECT  @Cbte_Grupo			= ISNULL(Cbte_Grupo, 0),
			@Compromete_Remitos_Com = ISNULL(Compromete_Remitos_Com, 0),
			@Compromete_Stock	= ISNULL(Compromete_Stock, 0),
			@Id_Dep_Fisico		= ISNULL(Id_Deposito_Fisico, ''),
            @Id_Dep_Logico		= ISNULL(Id_Deposito_Log, '')
	FROM Cbtes_Tipos 
	WHERE 
	Id_Tipo_Cbte = @pId_Tipo_Cbte
	
	/*===================================================================*/

	SELECT 	@Destinatario	= ISNULL(Razon_Social, Apellido),
			@Id_Pais		= ISNULL(Id_Pais, ''),
			@Id_Provincia	= ISNULL(Id_Provincia, ''),
			@Id_Localidad	= ISNULL(Id_Localidad, 0),
			@Cuit			= ISNULL(Cuit, ''),
			@Id_Iva			= ISNULL(Id_Iva, ''),
			@Email			= ISNULL(Email, '')
	FROM Proveedores
	WHERE
	Id_Proveedor = @pId_Proveedor
	
	IF (@Id_Pais = '' OR @Id_Provincia = '' OR @Id_Localidad = 0)
	BEGIN
		SET @Id_Pais = ''
		SET @Id_Provincia = ''
		SET @Id_Localidad = 0
	END	

	/*===================================================================*/

	SET @Plazo_Venc			= ISNULL((SELECT ISNULL(Plazo_Venc, 0) FROM Cbtes_Cond_Pago WHERE Id_Cond_Pago = @pId_Cond_Pago), 0)
	SET @Periodo_Iva		= @pFecha
	SET @Periodo			= @pFecha	
	
	IF(@Compromete_Stock = 0)
	BEGIN
		SET @Importe			= @pImp_Exento + @pImp_NoGravado + @pImp_Gravado + @pImp_Gravado2 + @pImp_Gravado3
	END
	ELSE
	BEGIN
		SET @Importe			= 0 /*Hay que actualizarlo luego de grabar los items*/
		SET @Saldo				= 0 /*Hay que actualizarlo luego de grabar los items*/
	END	
	
	SET @Importe_Con_Signo	= @Importe 
	SET @Imp_Total			= @Importe
	SET @Saldo				= @Importe
		
	SET @Imp_Neto			= 0 /*Hay que actualizarlo luego de grabar los items*/	
		
	/*TO-DO: De aca para abajo por ahora por Default*/
	
	SET @Id_Lista			= 0
	SET @Id_Cliente_Ref		= 0
	SET @Id_Taller			= ''
	SET @Id_Proceso			= ''
	SET @Id_Cliente			= 0
	SET @Signo				= 0
	SET	@Porc_DescFin		= 0
	SET @Porc_DescEspecial	= 0
	SET @Porc_Iva			= dbo.CF_xParam('Tasa_Iva_1')
	SET @Porc_Iva2			= dbo.CF_xParam('Tasa_Iva_2')
	SET @Imp_DescEspecial	= 0
	SET @Imp_DescFin		= 0
	SET @Imp_Bonificacion	= 0
	SET @Imp_Iva			= 0
	SET @Imp_Iva2			= 0
	SET @Imp_Percepcion_IB	= 0
	SET @Imp_Percepcion_Iva = 0
	SET @Bultos				= 0
	SET @NroImpresion		= 0
	SET @Exportado			= 0
	SET @Dir_Entrega		= ''
	SET @Porc_Iva3			= dbo.CF_xParam('Tasa_Iva_3')
	SET @Imp_IVA3			= 0
	SET @Imp_Percep			= 0
	SET @Id_Cond_Pago_Item	= 0
	SET @Id_Tipo_Reten		= ''
	SET @Cant_Cuotas		= 1
	SET @Id_Producto		= NULL
	SET @Id_Formula			= NULL
	SET @Cantidad			= 0
	SET @Id_Transportista	= 0
	SET @Cant_Batch			= 0
	SET @Fecha_Perm_Embar	= NULL
	SET @Saldo_Iva_Recup	= 0
	SET @Suc_Destina		= 0
	SET @Id_Asiento			= 0
	SET @Id_Valor			= 0
	SET @Cai				= 0	
	SET @Des_Anio			= 0
	SET @Des_Aduana			= ''
	SET @Des_Destina		= ''
	SET @Des_Nro			= 0
	SET @Des_Verif			= ''	
	SET @Id_Cobrador		= ''
	SET @Remito_Nro         = CONVERT( varchar(25), @pRemito_Nro)
	SET @Pedido_Nro			= ''
	SET @Id_Tarjeta			= ''
	SET @Tarjeta_Nro		= ''
	SET @Cantidad_Saldo		= 0
	SET @Saldo_Anterior		= 0
	SET @NRO_DJAI			= ''
	SET @Cantidad_Equiv		= 0
	SET @Id_Trans_Origen	= 0
	SET @Id_Sede_Origen		= 0
	SET @Patente_Transporte = ''
	SET @Patente_Transporte_Acoplado = ''
	SET @Porc_Bonificacion	= 0
	SET @Fecha_Estimada		= NULL
	SET @Persona_Recibe		= ''
	SET @Observacion		= ''
	SET @Id_Vendedor		= ''
	SET @Nro_Perm_Embarque	= ''
	SET @Id_Puerto			= ''
	SET @Id_Cond_Vta		= ''
	SET @Cbte_Nro_Externo	= CONVERT( varchar(25), @pRemito_Nro)
	SET @Nota_Part1			= ''
	SET @Nota_Part2			= ''
	SET @Id_Camp			= 0

	
	INSERT INTO Cbtes
	(Id_Trans,			Id_Empresa,			Id_Sucursal,
	Id_Tipo_Cbte,		Cbte_Grupo,			Comprobante_Nro,
	Id_Cliente,			Id_Taller,			Id_Proceso,
	Id_Proveedor,		Signo,				Id_Estado_Cbte,
	Fecha,				Id_Dep_Fisico,		Id_Dep_Logico,
	Porc_DescEspecial,	Porc_DescFin,		Porc_Bonificacion,
	Porc_Iva,			Porc_Iva2,			Imp_Neto,
	Imp_DescEspecial,	Imp_DescFin,		Imp_Bonificacion,
	Imp_Gravado,		Imp_Exento,			Imp_IVA,
	Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
	Imp_Total,			Bultos,				NroImpresion,
	Exportado,			Id_Usuario,			Fecha_Estimada,
	Dir_Entrega,		Id_Pais,			Id_Provincia,
	Id_Localidad,		Persona_Recibe,		Porc_Iva3,
	Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
	Imp_IVA3,			Imp_Percep,			Saldo,
	Periodo_Iva,		Periodo,			Fecha_Venc,
	Observacion,		Id_Cond_Pago_Item,	Id_Cond_Pago,
	Id_Tipo_Reten,		Cant_Cuotas,		Id_Producto,
	Id_Formula,			Cantidad,			Id_Vendedor,
	Id_Transportista,	Id_Lista,			Id_Moneda,
	Cotizacion,			Destinatario,		Cuit,
	Id_Iva,				Cant_Batch,			Nro_Perm_Embarque,
	Fecha_Perm_Embar,	Saldo_Iva_Recup,	Lote,
	Suc_Destina,		Id_Puerto,			Id_Cond_Vta,
	Cbte_Nro_Externo,	Nota_Part1,			Nota_Part2,
	Id_Asiento,			Id_Centro_Costo,	Id_Valor,
	Cai,				Cai_Vence,			Des_Anio,
	Des_Aduana,			Des_Destina,		Des_Nro,
	Des_Verif,			Id_Contrato,		Id_Cobrador,
	Nro_Auto_Trib,		Id_Camp,			Remito_Nro,
	Pedido_Nro,			Id_Tarjeta,			Tarjeta_Nro,
	Cantidad_Saldo,		Saldo_Anterior,		NRO_DJAI,
	Cantidad_Equiv,		Id_Trans_Origen,	Id_Sede_Origen,
	Email,				Patente_Transporte,	Patente_Transporte_Acoplado,
	Flag_Lote,			Id_Cliente_Ref)
	VALUES
	(@pId_Trans,		@Id_Empresa,		@pId_Sucursal,
	@pId_Tipo_Cbte,		@Cbte_Grupo,		@pComprobante_Nro,
	@Id_Cliente,		@Id_Taller,			@Id_Proceso,
	@pId_Proveedor,		@Signo,				@Id_Estado_Cbte,
	@pFecha,			@Id_Dep_Fisico,		@Id_Dep_Logico,
	@Porc_DescEspecial,	@Porc_DescFin,		@Porc_Bonificacion,
	@Porc_Iva,			@Porc_Iva2,			@Imp_Neto,
	@Imp_DescEspecial,	@Imp_DescFin,		@Imp_Bonificacion,
	@pImp_Gravado,		@pImp_Exento,		@Imp_IVA,
	@Imp_IVA2,			@Imp_Percepcion_IB,	@Imp_Percepcion_Iva,
	@Imp_Total,			@Bultos,			@NroImpresion,
	@Exportado,			@pId_Usuario,		@Fecha_Estimada,
	@Dir_Entrega,		@Id_Pais,			@Id_Provincia,
	@Id_Localidad,		@Persona_Recibe,	@Porc_Iva3,
	@pImp_Gravado2,		@pImp_Gravado3,		@pImp_NoGravado,
	@Imp_IVA3,			@Imp_Percep,		@Saldo,
	@Periodo_Iva,		@Periodo,			@pFechaVence,
	@Observacion,		@Id_Cond_Pago_Item,	@pId_Cond_Pago,
	@Id_Tipo_Reten,		@Cant_Cuotas,		@Id_Producto,
	@Id_Formula,		@Cantidad,			@Id_Vendedor,
	@Id_Transportista,	@Id_Lista,			@pId_Moneda,
	@pCotizacion,		@Destinatario,		@Cuit,
	@Id_Iva,			@Cant_Batch,		@Nro_Perm_Embarque,
	@Fecha_Perm_Embar,	@Saldo_Iva_Recup,	@pLote,
	@Suc_Destina,		@Id_Puerto,			@Id_Cond_Vta,
	@Cbte_Nro_Externo,	@Nota_Part1,		@Nota_Part2,
	@Id_Asiento,		@pId_Centro_Costo,	@Id_Valor,
	@Cai,				@pCai_Vence,		@Des_Anio,
	@Des_Aduana,		@Des_Destina,		@Des_Nro,
	@Des_Verif,			@pId_Contrato,		@Id_Cobrador,
	@pNro_Auto_Trib,	@Id_Camp,			@Remito_Nro,
	@Pedido_Nro,		@Id_Tarjeta,		@Tarjeta_Nro,
	@Cantidad_Saldo,	@Saldo_Anterior,	@Nro_DJAI,
	@Cantidad_Equiv,	@Id_Trans_Origen,	@Id_Sede_Origen,
	@Email,				@Patente_Transporte,@Patente_Transporte_Acoplado,
	@Flag_Lote,			@Id_Cliente_Ref)

	/*****************************************************************************/


	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	

	-- Incremento el proximo numero 
	IF  ISNULL((SELECT CASE WHEN Tipo_Numeracion = 'AUT' THEN 1 ELSE 0 END FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @pId_Tipo_Cbte), 0) = 1
	BEGIN
		UPDATE Cbtes_Tipos SET Prox_Nro = Prox_Nro + 1 WHERE Id_Tipo_Cbte = @pId_Tipo_Cbte
	END

	/*===================================================================*/
	
	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
								dbo.CF_Json_ParsearVariable('id_proveedor', @pId_Proveedor, 'INT')  + ',' +
								dbo.CF_Json_ParsearVariable('id_tipo_cbte', @pId_Tipo_Cbte, 'VARCHAR') +
								'}'
								
	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,@pId_Trans		AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Rem_Compra_Generar'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0


