DECLARE @pFecha_Estimada	DATETIME					--19/07/2022 Agregado
DECLARE @pId_Vendedor	 	VARCHAR(10)					--19/07/2022 Agregado
DECLARE @pId_Cond_Vta	 	CHAR(10)					--19/07/2022 Agregado
DECLARE @pId_Centro_Costo	CHAR(10)					--19/07/2022 Agregado
DECLARE @pId_Lista	 		SMALLINT					--19/07/2022 Agregado
DECLARE @pEmail	 			VARCHAR(8000)				--19/07/2022 Agregado
DECLARE @pId_Puerto	 		CHAR(3)						--19/07/2022 Agregado
DECLARE @pNota_Part1	 	VARCHAR(100)				--19/07/2022 Agregado
DECLARE @pNota_Part2	 	VARCHAR(100)				--19/07/2022 Agregado
DECLARE @pObservacion	 	VARCHAR(8000)				--19/07/2022 Agregado
DECLARE @pNro_Perm_Embarque	VARCHAR(20)					--19/07/2022 Agregado
DECLARE @pPersona_Recibe	VARCHAR(100)				--19/07/2022 Agregado
DECLARE @pPedido_Nro	 	VARCHAR(25)					--19/07/2022 Agregado
