DECLARE @Porc_Bonificacion	DECIMAL(5,2)
DECLARE @Id_Lista			SMALLINT
DECLARE @Id_Lista_Contrato	SMALLINT
DECLARE @Cbte_Nro_Externo	VARCHAR(25)
DECLARE @Id_Camp			SMALLINT
DECLARE @Flag_Lote			TINYINT
DECLARE @Compromete_Factura SMALLINT
DECLARE @Descrip_Cbte		VARCHAR(100)
DECLARE @Importe			DECIMAL(12, 2)
DECLARE @Importe_Con_Signo	DECIMAL(12, 2)
DECLARE @Id_Cliente_Ref		INT
DECLARE @Renglon_Nro		SMALLINT
DECLARE @Id_Estado_Mov_Caja	INT
DECLARE @Descripcion		VARCHAR(100)
DECLARE @Id_Tipo_Mov_Caja	SMALLINT
DECLARE @Id_Concepto		INT
DECLARE @Item				SMALLINT
DECLARE @Id_Estado_Concepto	SMALLINT
DECLARE @Email				VARCHAR(8000)
DECLARE @Email_Cob			VARCHAR(254)
DECLARE @Email_Web			VARCHAR(300)
/*Fin de Declaraciones Variables Locales */



BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Rem_Generar'
		PRINT 'Parametros:'
		PRINT 'pFlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans)  + '. pId_Usuario: ' + CONVERT(VARCHAR(10), @pId_Usuario) + '. pLote: ' + @pLote + '. pFecha: ' + CONVERT(VARCHAR(10), @pFecha, 103) + '. pFechaVence: ' + CONVERT(VARCHAR(10), @pFechaVence, 103) +  '. pId_Cliente: ' + CONVERT(VARCHAR(10), @pId_Cliente) + '. pId_Tipo_Cbte: ' + @pId_Tipo_Cbte + '. pId_Cond_Pago: ' + CONVERT(VARCHAR(10), @pId_Cond_Pago) + '. pId_Moneda: ' + @pId_Moneda + '. pCotizacion: ' + CONVERT(VARCHAR(10), @pCotizacion)
		PRINT 'pId_Contrato: ' + CONVERT(VARCHAR(10), @pId_Contrato)  + '. pNro_Auto_Trib: ' + @pNro_Auto_Trib + '. @pCai_Vence: ' + CONVERT(VARCHAR(10), @pCai_Vence, 103) + '. pId_Periodo_Caja: ' + CONVERT(VARCHAR(10), @pId_Periodo_Caja) + '. pImporte: ' + CONVERT(VARCHAR(10), @pImporte)
	END
	
	/*===================================================================*/


	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Inserta en Transacciones.'
	END
	
	IF(@pId_Trans = 0)
	BEGIN
		SET @pId_Trans		= ISNULL((SELECT MAX(Id_Trans) FROM Transacciones), 0) + 1
		INSERT INTO Transacciones 
		(Id_Trans,		Descripcion,						Fecha_Mov,
		Id_Usuario) 
		VALUES
		(@pId_Trans,	'Apertura CPJ_Transacciones_Abrir', GETDATE(), 
		@pId_Usuario)
	END


	/*===================================================================*/


	IF(@pId_Cliente = 0)  RAISERROR ('Id_Cliente can not be zero.', 16,  1 ) 
	IF(@pId_Tipo_Cbte = '') RAISERROR ('Id_Tipo_Cbte can not be blank.', 16,  1 ) 

		
	/*===================================================================*/
	
	IF(@pId_Usuario = 0)
	BEGIN
		SET @pId_Usuario = -1
	END
	
	IF(@pId_Moneda = '')
	BEGIN
		SET @pId_Moneda = dbo.CF_xParam('Moneda_Nacional')
	END

	IF(@pCotizacion = 0)
	BEGIN
		SET @pCotizacion = 1
	END
	
	IF(@pLote <> '')
	BEGIN
		SET @Flag_Lote	= 1
	END
	ELSE
	BEGIN
		SET @Flag_Lote	= 0
	END
	
	/*===================================================================*/

	SET @pFecha				= (SELECT CONVERT(DATE, @pFecha))
    SET @Id_Estado_Cbte		= 0  --siempre comienza en carga

	/*===================================================================*/

	SELECT  @Id_Sucursal		= ISNULL(Id_Sucursal, 0),
			@Cbte_Grupo			= ISNULL(Cbte_Grupo, 0),
			@Compromete_Factura = ISNULL(Compromete_Factura, 0)
	FROM Cbtes_Tipos 
	WHERE 
	Id_Tipo_Cbte = @pId_Tipo_Cbte
	
	/*===================================================================*/

	SELECT 	@Destinatario	= ISNULL(Razon_Social, Apellido + ', ' + Nombre),
			@Id_Pais		= ISNULL(Id_Pais_Cob, ''),
			@Id_Provincia	= ISNULL(Id_Provincia_Cob, ''),
			@Id_Localidad	= ISNULL(Id_Localidad_Cob, 0),
			@Cuit			= ISNULL(Cuit, ''),
			@Id_Iva			= ISNULL(Id_Iva, ''),
			@Id_Dep_Fisico	= ISNULL(Id_Dep_Fisico, ''),
			@Id_Dep_Logico	= ISNULL(Id_Dep_Logico, ''),
			@Email			= ISNULL(CONVERT(VARCHAR(8000), Email), ''),
			@Email_Cob		= ISNULL(Email_Cob, ''),
			@Email_Web		= ISNULL(Email_Web, ''),
			@Id_Lista		= ISNULL(Id_Lista_Precio, 0),
			@Porc_Bonificacion = ISNULL(Bonif, 0),
			@Id_Cliente_Ref	= ISNULL(Id_Cliente_Ref, 0),
			@Id_Concepto	= ISNULL(Id_Concepto, 0)
	FROM Clientes
	WHERE
	Id_Cliente = @pId_Cliente

	--06/04/2022 Se agrega, antes solo usaba el email, prioridades email, email_web, email_cob
	IF(@Email = '' AND @Email_Web <> '')
	BEGIN
		SET @Email = @Email_Web
	END

	IF(@Email = '' AND @Email_Cob <> '')
	BEGIN
		SET @Email = @Email_Cob
	END

	IF(@pEmail <> '')
	BEGIN
		SET @Email = @pEmail
	END

	--25/01/2021 Agregado 
	IF(@Id_Localidad = 0)
	BEGIN
		SET @Id_Provincia = ''
		SET @Id_Pais = ''
	END
	--FIN 25/01/2021 Agregado 

	/*===================================================================*/

	IF @pId_Contrato <> 0
	BEGIN
		SELECT 
		@Id_Lista_Contrato = Id_Lista_Precio 
		FROM Contratos 
		WHERE 
		Id_Contrato = @pId_Contrato

		IF ISNULL(@Id_Lista_Contrato,0) <> 0
		BEGIN
			SET @Id_Lista = @Id_Lista_Contrato
		END
	END

	IF(@pId_Lista <> 0)
	BEGIN
		SET @Id_Lista = @pId_Lista
	END


	IF @Bonif_Contrato <> 0
	BEGIN
		SET @Porc_Bonificacion = @Bonif_Contrato
	END

	/*===================================================================*/

	SET @Comprobante_Nro	= 0 /*En Carga*/
	SET @Importe			= 0 /*En Carga*/
	SET @Importe_Con_Signo	= @Importe * @Compromete_Factura
	SET @Plazo_Venc			= ISNULL((SELECT ISNULL(Plazo_Venc, 0) FROM Cbtes_Cond_Pago WHERE Id_Cond_Pago = @pId_Cond_Pago), 0)
	SET @Periodo_Iva		= @pFecha
	SET @Periodo			= @pFecha
	SET @Imp_Total			= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Saldo				= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Gravado		= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Neto			= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Exento			= 0 /*Hay que actualizarlo luego de grabar los items*/
		
	/*TO-DO: De aca para abajo por ahora por Default*/
	SET @Id_Taller			= ''
	SET @Id_Proceso			= ''
	SET @Id_Proveedor		= 0
	SET @Signo				= 0
	SET	@Porc_DescFin		= 0
	SET @Porc_DescEspecial	= 0
	SET @Porc_Iva			= dbo.CF_xParam('Tasa_Iva_1')
	SET @Porc_Iva2			= dbo.CF_xParam('Tasa_Iva_2')
	SET @Imp_DescEspecial	= 0
	SET @Imp_DescFin		= 0
	SET @Imp_Bonificacion	= 0
	SET @Imp_Iva			= 0
	SET @Imp_Iva2			= 0
	SET @Imp_Percepcion_IB	= 0
	SET @Imp_Percepcion_Iva = 0
	SET @Bultos				= 0
	SET @NroImpresion		= 0
	SET @Exportado			= 0
	SET @Porc_Iva3			= dbo.CF_xParam('Tasa_Iva_3')
	SET @Imp_Gravado2		= 0
	SET @Imp_Gravado3		= 0
	SET @Imp_NoGravado		= 0
	SET @Imp_IVA3			= 0
	SET @Imp_Percep			= 0
	SET @Id_Cond_Pago_Item	= 0
	SET @Id_Tipo_Reten		= ''
	SET @Cant_Cuotas		= 1
	SET @Id_Producto		= NULL
	SET @Id_Formula			= NULL
	SET @Cantidad			= 0
	SET @Cant_Batch			= 0
	SET @Fecha_Perm_Embar	= NULL
	SET @Saldo_Iva_Recup	= 0
	SET @Suc_Destina		= 0
	SET @Id_Asiento			= 0
	SET @Id_Valor			= 0
	SET @Cai				= 0	
	SET @Des_Anio			= 0
	SET @Des_Aduana			= ''
	SET @Des_Destina		= ''
	SET @Des_Nro			= 0
	SET @Des_Verif			= ''
	
	IF(@pId_Cobrador <> '')
	BEGIN
		SET @Id_Cobrador		= @pId_Cobrador
	END
	ELSE
	BEGIN
		SET @Id_Cobrador		= (SELECT ISNULL(Id_Cobrador, '') FROM Clientes WHERE Id_Cliente = @pId_Cliente)
	END

	IF(@pFecha_Estimada = '19000101')
	BEGIN
		SET @pFecha_Estimada = NULL
	END

	SET @Remito_Nro			= ''
	SET @Id_Tarjeta			= ''
	SET @Tarjeta_Nro		= ''
	SET @Cantidad_Saldo		= 0
	SET @Saldo_Anterior		= 0
	SET @NRO_DJAI			= ''
	SET @Cantidad_Equiv		= 0
	SET @Id_Trans_Origen	= 0
	SET @Id_Sede_Origen		= 0
	SET @Patente_Transporte = ''
	SET @Patente_Transporte_Acoplado = ''
	SET @Porc_Bonificacion	= 0
	SET @Cbte_Nro_Externo	= @pCbte_Nro_Externo
	SET @Id_Camp			= 0

	
	INSERT INTO Cbtes
	(Id_Trans,			Id_Empresa,			Id_Sucursal,
	Id_Tipo_Cbte,		Cbte_Grupo,			Comprobante_Nro,
	Id_Cliente,			Id_Taller,			Id_Proceso,
	Id_Proveedor,		Signo,				Id_Estado_Cbte,
	Fecha,				Id_Dep_Fisico,		Id_Dep_Logico,
	Porc_DescEspecial,	Porc_DescFin,		Porc_Bonificacion,
	Porc_Iva,			Porc_Iva2,			Imp_Neto,
	Imp_DescEspecial,	Imp_DescFin,		Imp_Bonificacion,
	Imp_Gravado,		Imp_Exento,			Imp_IVA,
	Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
	Imp_Total,			Bultos,				NroImpresion,
	Exportado,			Id_Usuario,			Fecha_Estimada,
	Dir_Entrega,		Id_Pais,			Id_Provincia,
	Id_Localidad,		Persona_Recibe,		Porc_Iva3,
	Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
	Imp_IVA3,			Imp_Percep,			Saldo,
	Periodo_Iva,		Periodo,			Fecha_Venc,
	Observacion,		Id_Cond_Pago_Item,	Id_Cond_Pago,
	Id_Tipo_Reten,		Cant_Cuotas,		Id_Producto,
	Id_Formula,			Cantidad,			Id_Vendedor,
	Id_Transportista,	Id_Lista,			Id_Moneda,
	Cotizacion,			Destinatario,		Cuit,
	Id_Iva,				Cant_Batch,			Nro_Perm_Embarque,
	Fecha_Perm_Embar,	Saldo_Iva_Recup,	Lote,
	Suc_Destina,		Id_Puerto,			Id_Cond_Vta,
	Cbte_Nro_Externo,	Nota_Part1,			Nota_Part2,
	Id_Asiento,			Id_Centro_Costo,	Id_Valor,
	Cai,				Cai_Vence,			Des_Anio,
	Des_Aduana,			Des_Destina,		Des_Nro,
	Des_Verif,			Id_Contrato,		Id_Cobrador,
	Nro_Auto_Trib,		Id_Camp,			Remito_Nro,
	Pedido_Nro,			Id_Tarjeta,			Tarjeta_Nro,
	Cantidad_Saldo,		Saldo_Anterior,		NRO_DJAI,
	Cantidad_Equiv,		Id_Trans_Origen,	Id_Sede_Origen,
	Email,				Patente_Transporte,	Patente_Transporte_Acoplado,
	Flag_Lote,			Id_Cliente_Ref)
	VALUES
	(@pId_Trans,		@Id_Empresa,		@Id_Sucursal,
	@pId_Tipo_Cbte,		@Cbte_Grupo,		@Comprobante_Nro,
	@pId_Cliente,		@Id_Taller,			@Id_Proceso,
	@Id_Proveedor,		@Signo,				@Id_Estado_Cbte,
	@pFecha,			@Id_Dep_Fisico,		@Id_Dep_Logico,
	@Porc_DescEspecial,	@Porc_DescFin,		@Porc_Bonificacion,
	@Porc_Iva,			@Porc_Iva2,			@Imp_Neto,
	@Imp_DescEspecial,	@Imp_DescFin,		@Imp_Bonificacion,
	@Imp_Gravado,		@Imp_Exento,		@Imp_IVA,
	@Imp_IVA2,			@Imp_Percepcion_IB,	@Imp_Percepcion_Iva,
	@Imp_Total,			@Bultos,			@NroImpresion,
	@Exportado,			@pId_Usuario,		@pFecha_Estimada,
	@pDir_Entrega,		@Id_Pais,			@Id_Provincia,
	@Id_Localidad,		@pPersona_Recibe,	@Porc_Iva3,
	@Imp_Gravado2,		@Imp_Gravado3,		@Imp_NoGravado,
	@Imp_IVA3,			@Imp_Percep,		@Saldo,
	@Periodo_Iva,		@Periodo,			@pFechaVence,
	@pObservacion,		@Id_Cond_Pago_Item,	@pId_Cond_Pago,
	@Id_Tipo_Reten,		@Cant_Cuotas,		@Id_Producto,
	@Id_Formula,		@Cantidad,			@pId_Vendedor,
	@pId_Transportista,	@Id_Lista,			@pId_Moneda,
	@pCotizacion,		@Destinatario,		@Cuit,
	@Id_Iva,			@Cant_Batch,		@pNro_Perm_Embarque,
	@Fecha_Perm_Embar,	@Saldo_Iva_Recup,	@pLote,
	@Suc_Destina,		@pId_Puerto,		@pId_Cond_Vta,
	@Cbte_Nro_Externo,	@pNota_Part1,		@pNota_Part2,
	@Id_Asiento,		@pId_Centro_Costo,	@Id_Valor,
	@Cai,				@pCai_Vence,		@Des_Anio,
	@Des_Aduana,		@Des_Destina,		@Des_Nro,
	@Des_Verif,			@pId_Contrato,		@Id_Cobrador,
	@pNro_Auto_Trib,	@Id_Camp,			@Remito_Nro,
	@pPedido_Nro,		@Id_Tarjeta,		@Tarjeta_Nro,
	@Cantidad_Saldo,	@Saldo_Anterior,	@Nro_DJAI,
	@Cantidad_Equiv,	@Id_Trans_Origen,	@Id_Sede_Origen,
	@Email,				@Patente_Transporte,@Patente_Transporte_Acoplado,
	@Flag_Lote,			@Id_Cliente_Ref)

	/*===================================================================*/
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	

	IF (@pOmitir_Resultado_Ok = 0)
	BEGIN
	
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_cliente', @pId_Cliente, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_tipo_cbte', @pId_Tipo_Cbte, 'VARCHAR') +
									'}'
								
		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,@pId_Trans		AS ErrorLine		
				,@rtaMsjStored	AS ErrorMeaage

	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Rem_Generar'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_Rem_Generar_Item]		@pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*
VERSIONES:
--19/07/2022: Se agregan parametros de entrada: @pObservacion
--15/11/2023: Se agregan parametros de entrada: @pId_Trans_A_Aplicar
			  Se hacen validaciones necesarias para @pId_Trans_A_Aplicar
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Trans				INT
DECLARE @pId_Trans_A_Aplicar	INT
DECLARE @pId_Producto			VARCHAR(14)
DECLARE @pCantidad				DECIMAL(15,5)
DECLARE @pFecha_QA				DATETIME
DECLARE @pFecha_Venc			DATETIME
DECLARE @pId_Cliente			INT
DECLARE @pBonif					DECIMAL(5,2)
DECLARE @pPorc_Iva				DECIMAL(5,2)
DECLARE @pPrecio_Grav			DECIMAL(15,5)
DECLARE @pPrecio_Exen			DECIMAL(15,5)
DECLARE @pId_Tiempo             CHAR(3)
DECLARE @pRefacturar            TINYINT
DECLARE @pFlag_Tabla_Temp       TINYINT
DECLARE @pLote					VARCHAR(20)
DECLARE @pObservacion	 		VARCHAR(8000)				--19/07/2022 Agregado
DECLARE @pRtaMsjStored			TINYINT						--01/12/2022 Agregado
DECLARE @pOmitir_Resultado_OK	TINYINT

SET @pFlag_Tabla_Temp		    = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Tabla_Temp')), 0)
SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Producto				= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), 0)
SET @pCantidad					= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Cantidad')), 0)
SET @pFecha_QA					= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_QA'))
SET @pFecha_Venc				= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Venc'))
SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pBonif						= ISNULL(CONVERT(DECIMAL(5,2), dbo.CF_JSON_VALUE(@pJson,'Bonif')), 0)
SET @pPorc_Iva					= ISNULL(CONVERT(DECIMAL(5,2), dbo.CF_JSON_VALUE(@pJson,'Porc_Iva')), 0)
SET @pPrecio_Grav 				= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Precio_Grav')), 0)
SET @pPrecio_Exen				= ISNULL(CONVERT(DECIMAL(15,5), dbo.CF_JSON_VALUE(@pJson,'Precio_Exen')), 0)
SET @pId_Tiempo	            	= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Id_Tiempo')), '')
SET @pRefacturar		        = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Refacturar')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pId_Trans_A_Aplicar		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans_A_Aplicar')), 0)
SET @pLote						= ISNULL(CONVERT(VARCHAR(20), dbo.CF_JSON_VALUE(@pJson,'Lote')), '')
SET @pObservacion				= ISNULL(CONVERT(VARCHAR(8000), dbo.CF_JSON_VALUE(@pJson,'Observacion')), '')
SET @pRtaMsjStored				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'RtaMsjStored')), 0)
SET @pOmitir_Resultado_OK		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Resultado_OK')), 1)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Item 							SMALLINT
DECLARE @Id_Estado_Cbte 				SMALLINT
DECLARE @Calle 							CHAR(5)
DECLARE @Columna 						CHAR(5)
DECLARE @Fila 							CHAR(5)
DECLARE @Bultos 						DECIMAL(15, 5)
DECLARE @Despacho 						VARCHAR(100)
DECLARE @Serie 							VARCHAR(100)
DECLARE @Millas 						INT
DECLARE @Cantidad_Saldo 				DECIMAL(15, 5)
DECLARE @Imp_Gravado 					DECIMAL(12, 2)
DECLARE @Imp_Exento 					DECIMAL(12, 2)
DECLARE @Analisis 						VARCHAR(30)
DECLARE @Flag_QA 						CHAR(1)
DECLARE @Descripcion_producto 			VARCHAR(100)
DECLARE @Id_Unidad_Medida 				CHAR(4)
DECLARE @Imp_Final						DECIMAL(15,5)
DECLARE @Costo 							DECIMAL(15, 5)
DECLARE @Imp_Iva 						DECIMAL(12, 2)
DECLARE @Id_Costo 						INT
DECLARE @Id_Tarea 						SMALLINT
DECLARE @Fecha_Caducidad 				DATETIME
DECLARE @Id_Pais 						CHAR(3)
DECLARE @Id_Usuario 					SMALLINT
DECLARE @Cantidad_Equiv 				DECIMAL(15, 5)
DECLARE @Costo_MO 						DECIMAL(15, 5)
DECLARE @Costo_GF 						DECIMAL(15, 5)
DECLARE @Id_Cond_Pago 					SMALLINT
DECLARE @Fecha_Proceso 					DATETIME
DECLARE @Id_Balanza 					CHAR(10)
DECLARE @Orden 							SMALLINT
DECLARE @Flag_NoImp_Factura 			TINYINT
DECLARE @Nro_Tag 						VARCHAR(30)
DECLARE @Fecha_Elaboracion 				DATETIME
DECLARE @Costo_Comparativo 				DECIMAL(13, 4)
DECLARE @Porc_Imp_Int 					DECIMAL(5, 2)
DECLARE @Id_Cta_Banco 					SMALLINT
DECLARE @Flag_Existe_Trans				TINYINT
DECLARE @Flag_Existe_Cliente			TINYINT
DECLARE @Flag_Existe_Producto			TINYINT
DECLARE @Id_Lista_Precio				SMALLINT
DECLARE @Precio_Gravado_Producto		DECIMAL(13, 4)
DECLARE @Precio							DECIMAL(15,5)
DECLARE @Item_Facturado					SMALLINT

DECLARE @Id_Estado_Cbte_Id_Trans_Origen	SMALLINT
DECLARE @Cantidad						DECIMAL(14, 2)
DECLARE @Cantidad_Saldo_Total			DECIMAL(14, 2)
DECLARE @Id_Trans_CA					INT
DECLARE @Fecha_Aplic					DATETIME
DECLARE @Item_D							SMALLINT

/*FIN Declaracion Variables Locales*/


BEGIN TRY
 
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Rem_Generar_Item'
		PRINT 'Parametros:'
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + ' Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans) + ' Id_Producto: ' + @pId_Producto + ' Cantidad: ' + CONVERT(VARCHAR(10), @pCantidad) + ' Fecha_QA: ' + CONVERT(VARCHAR(10), @pFecha_QA, 103) + ' Fecha_Venc: ' + CONVERT(VARCHAR(10), @pFecha_Venc, 103) + ' Id_Cliente: ' + CONVERT(VARCHAR(10), @pId_Cliente) + ' Bonif: ' + CONVERT(VARCHAR(10), @pBonif) + ' Porc_Iva: ' + CONVERT(VARCHAR(10), @pPorc_Iva) + ' Precio_Grav: ' + CONVERT(VARCHAR(25), @pPrecio_Grav) + ' Precio_Exent: ' + CONVERT(VARCHAR(25), @pPrecio_Exen) 
	END

	/*===================================================================*/
    IF @pFlag_Tabla_Temp = 1  
	    SET @pId_Trans	= 0
	  ELSE
    	IF(@pId_Trans = 0)		RAISERROR ('Id_Trans can not be zero.', 16,  1 ) 

	IF(@pId_Cliente = 0)	RAISERROR ('Id_Cliente can not be zero.', 16,  1 ) 
	IF(@pId_Producto = '')	RAISERROR ('Id_Producto can not be blank.', 16,  1 ) 
    Set @Item_Facturado = 0
	IF @pRefacturar = 0 
	   	SET @Item_Facturado =  ( SELECT dbo.CFJ_Producto_Facturado  ('{ "Id_Cliente":"' + CONVERT(VARCHAR(15), @pId_Cliente) + '",' 
	                                                              + ' "id_producto":"' + CONVERT(VARCHAR(15), @pId_Producto) + '",'
																  + ' "Id_Tiempo":"' + CONVERT(VARCHAR(15), @pId_Tiempo) + '",'
																  + ' "Fecha":"' + CONVERT(VARCHAR(15), @pFecha_QA , 112 ) + '",'
																  + ' "Flag_Tabla_Temp":"' + CONVERT(VARCHAR(1), @pFlag_Tabla_Temp ) + '",'
															      + ' "Refacturar":"' + CONVERT(VARCHAR(5), @pRefacturar) + '"}'))

    IF (@pRefacturar = 0 AND @Item_Facturado <> 0)
	    BEGIN
		     IF @pFlagUsarTrans <> 0 COMMIT


				/*===================================================================*/	

			IF (@pOmitir_Resultado_OK = 0)
			BEGIN

				SET @rtaMsjStored		=	'{' +
											dbo.CF_Json_ParsearVariable('id_trans', ISNULL(@pId_Trans,0), 'INT')  + ',' +
											dbo.CF_Json_ParsearVariable('item', ISNULL(@Item,0), 'SMALLINT')  + ',' +
											dbo.CF_Json_ParsearVariable('id_producto', ISNULL(@pId_Producto,''), 'VARCHAR')  + ',' +
											dbo.CF_Json_ParsearVariable('imp_final', ISNULL(@Imp_Final,0), 'DECIMAL') +
											'}'

				SELECT	 0				AS ErrorNumber 
						,0				AS ErrorSeverity  
						,0				AS ErrorState 
						,0				AS ErrorProcedure  
						,0				AS ErrorLine		
						,@rtaMsjStored	AS ErrorMessage
			END

			   RETURN 0
	    END


	/*************************************************************************************************/

	SELECT  @Id_Estado_Cbte	= ISNULL(Id_Estado_Cbte, 0),
			@pLote			= ISNULL(Lote, ''),
			@Id_Usuario		= ISNULL(Id_Usuario, '-1')
	FROM Cbtes
	WHERE 
	Id_Trans = @pId_Trans

	/*************************************************************************************************/

	SELECT  @Calle					= ISNULL(Calle, ''),
			@Columna				= ISNULL(Columna, ''),
			@Fila					= ISNULL(Fila, ''),
			@Despacho				= ISNULL(Despacho, ''),
			@Descripcion_producto	= ISNULL(Descripcion_Resumida, ''),
			@Id_Unidad_Medida		= ISNULL(Id_Unidad_Medida, ''),
			@Costo					= ISNULL(Costo, 0),
			@Id_Cond_Pago			= ISNULL(Id_Cond_Pago, 0),
			@Id_Cta_Banco			= ISNULL(Id_Cta_Banco, 0),
			@Precio_Gravado_Producto = ISNULL(Precio_Gravado, 0)
	FROM Productos
	WHERE 
	Id_Producto = @pId_Producto	

	/*************************************************************************************************/

	IF(@pId_Trans_A_Aplicar <> 0)
	BEGIN
		SELECT @Id_Estado_Cbte_Id_Trans_Origen = ISNULL(Id_Estado_Cbte, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans_A_Aplicar
	END
	ELSE
	BEGIN
		SET @Id_Estado_Cbte_Id_Trans_Origen = 0
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Id_Estado_Cbte_Id_Trans_Origen: ' + CONVERT(VARCHAR(10), @Id_Estado_Cbte_Id_Trans_Origen)
	END

	/*************************************************************************************************/
	IF (@pCantidad = 0)
		SET @pCantidad = 1

	IF (@pFecha_QA <  GETDATE() - 10)
		SET @pFecha_QA = GETDATE()

    IF @pFlag_Tabla_Temp = 1  
    	SET @Item 					= (ISNULL((SELECT MAX(ISNULL(Item, 0)) FROM #ITEMS_CBTE WHERE Id_Trans = @pId_Trans), 0)) + 1
	  ELSE
     	SET @Item 					= (ISNULL((SELECT MAX(ISNULL(Item, 0)) FROM CBTES_ITEMS WHERE Id_Trans = @pId_Trans), 0)) + 1
	    
	SET @Precio					= @pPrecio_Grav + @pPrecio_Exen
	SET @pPrecio_Grav			= @Precio * (1 - (@pBonif / 100) )
	SET @pPrecio_Exen			= 0

	SET @Bultos 				= 0
	SET @Serie 					= ''
	SET @Millas 				= 0
	SET @Cantidad_Saldo 		= @pCantidad
	SET @Imp_Gravado 			= @pPrecio_Grav * @pCantidad
	SET @Imp_Exento 			= 0
	SET @Analisis 				= ''
	SET @Flag_QA 				= 'A'
	SET @Imp_Iva 				= ((@pPrecio_Grav * @pPorc_Iva) / 100)
	SET @Imp_Final				= (@Imp_Gravado + @Imp_Iva + @Imp_Exento)
	SET @Id_Costo 				= 0
	SET @Id_Tarea 				= 0
	SET @Fecha_Caducidad 		= NULL
	SET @Id_Pais 				= ''
	SET @Cantidad_Equiv 		= 0
	SET @Costo_MO 				= 0
	SET @Costo_GF 				= 0
	SET @Fecha_Proceso 			= NULL
	SET @Id_Balanza 			= ''
	SET @Orden 					= 0
	SET @Flag_NoImp_Factura 	= 0
	SET @Nro_Tag 				= ''
	SET @Fecha_Elaboracion 		= NULL
	SET @Costo_Comparativo 		= 0
	SET @Porc_Imp_Int 			= 0


	/*************************************************************************************************/
    IF @pFlag_Tabla_Temp = 1 
		INSERT INTO #ITEMS_CBTE
		(Id_Trans,		Item,					Id_Producto, 
		Id_Estado_Cbte, Cantidad,				Calle, 
		Columna,		Fila,					Bultos, 
		Despacho,		Serie,					Fecha_Venc,
		Observacion,	Millas,					Cantidad_Saldo, 
		Precio_Grav,	Precio_Exen,			Imp_Gravado, 
		Imp_Exento,		Analisis,				Lote, 
		Flag_QA,		Fecha_QA,				Porc_Iva, 
		Bonif,			Descripcion_producto,	Id_Unidad_Medida, 
		Imp_Final,		Costo,					Imp_Iva, 
		Precio,			Id_Costo,				Id_Cliente,
		Id_Tarea,		Fecha_Caducidad,		Id_Pais, 
		Id_Usuario,		Cantidad_Equiv,			Costo_MO, 
		Costo_GF,		Id_Cond_Pago,			Fecha_Proceso, 
		Id_Balanza,		Orden,					Flag_NoImp_Factura, 
		Nro_Tag,		Fecha_Elaboracion,		Costo_Comparativo, 
		Porc_Imp_Int,	Id_Cta_Banco)
		VALUES
		(@pId_Trans,		@Item,					@pId_Producto, 
		@Id_Estado_Cbte,	@pCantidad,				@Calle, 
		@Columna,			@Fila,					@Bultos, 
		@Despacho,			@Serie,					@pFecha_Venc,
		@pObservacion,		@Millas,				@Cantidad_Saldo, 
		@pPrecio_Grav,		@pPrecio_Exen,			@Imp_Gravado, 
		@Imp_Exento,		@Analisis,				@pLote, 
		@Flag_QA,			@pFecha_QA,				@pPorc_Iva, 
		@pBonif,			@Descripcion_producto,	@Id_Unidad_Medida, 
		@Imp_Final,			@Costo,					@Imp_Iva, 
		@Precio,			@Id_Costo,				@pId_Cliente,
		@Id_Tarea,			@Fecha_Caducidad,		@Id_Pais, 
		@Id_Usuario,		@Cantidad_Equiv,		@Costo_MO, 
		@Costo_GF,			@Id_Cond_Pago,			@Fecha_Proceso, 
		@Id_Balanza,		@Orden,					@Flag_NoImp_Factura, 
		@Nro_Tag,			@Fecha_Elaboracion,		@Costo_Comparativo, 
		@Porc_Imp_Int,		@Id_Cta_Banco)
       
      ELSE
	    
		INSERT INTO CBTES_ITEMS
		(Id_Trans,		Item,					Id_Producto, 
		Id_Estado_Cbte, Cantidad,				Calle, 
		Columna,		Fila,					Bultos, 
		Despacho,		Serie,					Fecha_Venc,
		Observacion,	Millas,					Cantidad_Saldo, 
		Precio_Grav,	Precio_Exen,			Imp_Gravado, 
		Imp_Exento,		Analisis,				Lote, 
		Flag_QA,		Fecha_QA,				Porc_Iva, 
		Bonif,			Descripcion_producto,	Id_Unidad_Medida, 
		Imp_Final,		Costo,					Imp_Iva, 
		Precio,			Id_Costo,				Id_Cliente,
		Id_Tarea,		Fecha_Caducidad,		Id_Pais, 
		Id_Usuario,		Cantidad_Equiv,			Costo_MO, 
		Costo_GF,		Id_Cond_Pago,			Fecha_Proceso, 
		Id_Balanza,		Orden,					Flag_NoImp_Factura, 
		Nro_Tag,		Fecha_Elaboracion,		Costo_Comparativo, 
		Porc_Imp_Int,	Id_Cta_Banco)
	    VALUES
		(@pId_Trans,		@Item,					@pId_Producto, 
		@Id_Estado_Cbte,	@pCantidad,				@Calle, 
		@Columna,			@Fila,					@Bultos, 
		@Despacho,			@Serie,					@pFecha_Venc,
		@pObservacion,		@Millas,				@Cantidad_Saldo, 
		@pPrecio_Grav,		@pPrecio_Exen,			@Imp_Gravado, 
		@Imp_Exento,		@Analisis,				@pLote, 
		@Flag_QA,			@pFecha_QA,				@pPorc_Iva, 
		@pBonif,			@Descripcion_producto,	@Id_Unidad_Medida, 
		@Imp_Final,			@Costo,					@Imp_Iva, 
		@Precio,			@Id_Costo,				@pId_Cliente,
		@Id_Tarea,			@Fecha_Caducidad,		@Id_Pais, 
		@Id_Usuario,		@Cantidad_Equiv,		@Costo_MO, 
		@Costo_GF,			@Id_Cond_Pago,			@Fecha_Proceso, 
		@Id_Balanza,		@Orden,					@Flag_NoImp_Factura, 
		@Nro_Tag,			@Fecha_Elaboracion,		@Costo_Comparativo, 
		@Porc_Imp_Int,		@Id_Cta_Banco)

	
	/*===================================================================*/
	
	SET @Id_Trans_CA	= @pId_Trans_A_Aplicar

	SET @Item_D			= 1
	SET @Item			= 1

	IF NOT EXISTS (	SELECT 1 
					FROM Cbtes_Aplica 
					WHERE 
					Id_Trans = @Id_Trans_CA
					AND	Item = @Item
					AND	Id_Trans_D = @pId_Trans
					AND	Item_D = @Item_D)
    BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Inserta Cbtes_Aplica'
		END

		INSERT INTO dbo.Cbtes_Aplica
		(Id_Trans,			Item,				Id_Trans_D,
		Item_D,				Cantidad,			Importe,
		Fecha_Aplic)
		VALUES
		(@pId_Trans,		@Item,				@Id_Trans_CA,
		@Item_D,			@pCantidad,			@pPrecio_Grav,
		@Fecha_Aplic)
    END
	ELSE
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Actualiza Cbtes_Aplica'
		END

		UPDATE Cbtes_Aplica
		SET 
		Importe = Importe + @pPrecio_Grav
		WHERE 
		Id_Trans = @Id_Trans_CA
		AND	Item = @Item
		AND	Id_Trans_D = @pId_Trans
		AND	Item_D = @Item_D
	END

	/*===================================================================*/
	
	IF (@pId_Trans_A_Aplicar <> 0)
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Actualiza Id_Trans_A_Aplicar: ' +  CONVERT(VARCHAR(10), @pId_Trans_A_Aplicar)
		END

		UPDATE Cbtes_Items SET Cantidad_Saldo -= @pCantidad WHERE Id_Trans = @pId_Trans_A_Aplicar AND Id_Producto = @pId_Producto

		SET @Cantidad_Saldo			= ISNULL((SELECT Cantidad_Saldo FROM Cbtes_Items WHERE Id_Trans = @pId_Trans_A_Aplicar AND Id_Producto = @pId_Producto),0)
		SET @Cantidad	 			= ISNULL((SELECT Cantidad FROM Cbtes_Items WHERE Id_Trans = @pId_Trans_A_Aplicar AND Id_Producto = @pId_Producto),0)
		SET @Cantidad_Saldo_Total	= ISNULL((SELECT SUM(Cantidad_Saldo) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans_A_Aplicar),0)

		IF(@Id_Estado_Cbte_Id_Trans_Origen IN (1,4))
		BEGIN
			IF(@Cantidad_Saldo = 0)
			BEGIN
				UPDATE Cbtes_Items SET Id_Estado_Cbte = 2 WHERE Id_Trans = @pId_Trans_A_Aplicar AND Id_Producto = @pId_Producto
			END
			ELSE
			BEGIN
				UPDATE Cbtes		SET Id_Estado_Cbte = 4  WHERE Id_Trans = @pId_Trans_A_Aplicar
				UPDATE Cbtes_Items	 SET Id_Estado_Cbte = 4 WHERE Id_Trans = @pId_Trans_A_Aplicar AND Id_Producto = @pId_Producto
			END

			IF(@Cantidad_Saldo_Total = 0)
			BEGIN
				UPDATE Cbtes SET Id_Estado_Cbte = 2 WHERE Id_Trans = @pId_Trans_A_Aplicar
			END
		END
	END

	/*===================================================================*/
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	

	IF (@pOmitir_Resultado_OK = 0)
	BEGIN

		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
									dbo.CF_Json_ParsearVariable('item',@Item, 'SMALLINT')  + ',' +
									dbo.CF_Json_ParsearVariable('id_producto', @pId_Producto, 'VARCHAR')  + ',' +
									dbo.CF_Json_ParsearVariable('imp_final',@Imp_Final, 'DECIMAL') +
									'}'

		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage

	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Rem_Generar_Item'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Cbtes_ReqCompra_GenerarOrdenDeCompra] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/* Variables */
DECLARE @pId_Trans							INT
DECLARE @pModoDebug							TINYINT
DECLARE @pId_Usuario						INT
DECLARE @Last_Id_Trans						INT
DECLARE @Req_Compra_Comprobante_Nro			INT 
DECLARE @Req_Compra_Fecha					DATE
DECLARE @Req_Compra_Id_Tipo_Cbte			VARCHAR(15)
DECLARE @Cbte_Tipo_Prox_Comprobante_Nro		INT
DECLARE @Cbte_Tipo_Id_Estado_Cbte			INT

SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Usuario			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), 0)
SET @pId_Trans				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)

BEGIN TRY
	BEGIN TRANSACTION

	-- Lanzo error
	IF (dbo.CF_xParam('T_Cbte_Ord_Comp') = '') RAISERROR ('Sin cÔö£Ôöédigo asignado a la orden de compra', 16,  1 ) 


	-- Creo la transacciÔö£Ôöén
	SET @Last_Id_Trans = ISNULL((SELECT MAX(Id_Trans) FROM Transacciones), 0) + 1
	INSERT INTO Transacciones (Id_Trans, Fecha_mov, Id_Usuario) VALUES	(@Last_Id_Trans, GETDATE(), @pId_Usuario)

	-- Copio la info del Requerimiento de Compra (Comprobante)
	SELECT * INTO #Cbtes FROM Cbtes WHERE Id_Trans = @pId_Trans
	SELECT @Req_Compra_Comprobante_Nro = Comprobante_Nro, @Req_Compra_Fecha = Fecha, @Req_Compra_Id_Tipo_Cbte = Id_Tipo_Cbte 
	FROM Cbtes WHERE Id_Trans = @pId_Trans
	-- Copio la info del tipo de Comprobante original
	SELECT * INTO #Cbtes_Tipos FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Req_Compra_Id_Tipo_Cbte
	-- Actualizo el prÔö£Ôöéximo nÔö£Ôòæmero de comprobante
	UPDATE Cbtes_Tipos SET Prox_Nro = Prox_Nro + 1 WHERE Id_Tipo_Cbte = @Req_Compra_Id_Tipo_Cbte

	SELECT @Cbte_Tipo_Prox_Comprobante_Nro = Prox_Nro, @Cbte_Tipo_Id_Estado_Cbte = Id_Estado_Cbte FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = dbo.CF_xParam('T_Cbte_Ord_Comp')
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Last_Id_Trans: ' + CONVERT(VARCHAR(10), @Last_Id_Trans)
		PRINT '@Req_Compra_Comprobante_Nro: ' + CONVERT(VARCHAR(20), @Req_Compra_Comprobante_Nro)
		PRINT '@Req_Compra_Fecha: ' + CONVERT(VARCHAR(20), @Req_Compra_Fecha) 
		PRINT '@Req_Compra_Id_Tipo_Cbte: ' + CONVERT(VARCHAR(15), @Req_Compra_Id_Tipo_Cbte)
		PRINT '@Cbte_Tipo_Prox_Comprobante_Nro: ' + CONVERT(VARCHAR(20), @Cbte_Tipo_Prox_Comprobante_Nro)
		PRINT '@Cbte_Tipo_Id_Estado_Cbte: ' + CONVERT(VARCHAR(15), @Cbte_Tipo_Id_Estado_Cbte)
	END

	UPDATE 
		#Cbtes 
	SET 
		Id_Trans = @Last_Id_Trans, 
		Id_Tipo_Cbte = dbo.CF_xParam('T_Cbte_Ord_Comp'), 
		Cbte_Nro_Externo = @Req_Compra_Comprobante_Nro, 
		Periodo_Iva = @Req_Compra_Fecha, 
		Periodo = @Req_Compra_Fecha,
		Comprobante_Nro = @Cbte_Tipo_Prox_Comprobante_Nro,
		Id_Estado_Cbte = 1, 
		Id_Trans_Origen = @pId_Trans
	WHERE 
		Id_Trans = @pId_Trans
		
	
	-- Seteo el estado de la Orden de compra
	UPDATE #Cbtes SET Id_Estado_Cbte = dbo.CF_xParam('Est_OC_Req_Aprob') WHERE Id_Trans = @Last_Id_Trans

	IF (@pModoDebug = 1 ) 
	BEGIN 
		PRINT 'Imprimi tabla temporal cbtes antes del insert'
		SELECT * FROM #Cbtes
	END 

	-- Creo la Orden de compra
	INSERT INTO Cbtes SELECT * FROM #Cbtes


	DECLARE @cursor_item INT
	DECLARE @cursor_Porcentaje1 FLOAT
	DECLARE @cursor_Id_Producto VARCHAR(14)
	DECLARE @cursor_Cantidad FLOAT
	DECLARE @cursor_Imp_Final FLOAT

	-- Itero por los items del comprobante original para agregarlos al comprobante creado
	DECLARE cursorCbtesItems CURSOR LOCAL FOR SELECT Item, Id_Producto, Cantidad, Imp_Final FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Item <> 0
	OPEN cursorCbtesItems
	FETCH NEXT FROM cursorCbtesItems INTO @cursor_item, @cursor_Id_Producto, @cursor_Cantidad, @cursor_Imp_Final
	WHILE @@FETCH_STATUS = 0
	BEGIN
		-- copio el item en una tabla temporal
		SELECT * INTO #Cbtes_Items FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Item = @cursor_item

		-- Busco el porcentaje
		SET @cursor_Porcentaje1 = ISNULL((SELECT pti.Porc1 FROM Productos p LEFT JOIN Productos_TasaIva pti ON p.Id_Iva = pti.Id_Iva WHERE p.Id_Producto = @cursor_Id_Producto), 0)

		-- Piso las variables del item
		UPDATE #Cbtes_Items SET Id_Trans = @Last_Id_Trans, Id_Estado_Cbte = dbo.CF_xParam('Est_OC_Req_Aprob') WHERE Item = @cursor_item 
		-- Hago el insert del item en la DB
		INSERT INTO Cbtes_Items SELECT * FROM #Cbtes_Items

		-- Inserto en Cbtes_Aplica
		INSERT INTO Cbtes_aplica (Id_Trans, Item, Id_Trans_d, Item_D, Cantidad, Importe, Fecha_Aplic) VALUES (@pId_Trans, @cursor_item, @Last_Id_Trans, @cursor_item, @cursor_Cantidad, @cursor_Imp_Final, GETDATE())

		-- Limpio la tabla para el prÔö£Ôöéximo registro
		DROP TABLE #Cbtes_Items
	FETCH NEXT FROM cursorCbtesItems INTO @cursor_item, @cursor_Id_Producto, @cursor_Cantidad, @cursor_Imp_Final
	END
	CLOSE cursorCbtesItems


	-- Incremento el proximo numero del tipo de comprobante si es autoincremental
	IF  ISNULL((SELECT CASE WHEN Tipo_Numeracion = 'AUT' THEN 1 ELSE 0 END FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = dbo.CF_xParam('T_Cbte_Ord_Comp')), 0) = 1
	BEGIN
		UPDATE Cbtes_Tipos SET Prox_Nro = Prox_Nro + 1 WHERE Id_Tipo_Cbte = dbo.CF_xParam('T_Cbte_Ord_Comp')
	END

	-- Cambio el estado del Requerimiento de compra a completo
	UPDATE cbtes SET Id_Estado_Cbte = dbo.CF_xParam('Est_REQC_Aprob') WHERE Id_Trans = @pId_Trans

	COMMIT TRANSACTION

	IF (@pModoDebug = 1 ) PRINT 'Procedimiento ejecutado correctamente. (commit)'
	
	DECLARE @rtaMsjStored			VARCHAR(4000)
	SET @rtaMsjStored =	'{' + dbo.CF_Json_ParsearVariable('Id_Trans', @Last_Id_Trans, 'INT') + '}'

	IF OBJECT_ID('tempdb..#Cbtes') IS NOT NULL DROP TABLE #Cbtes
	IF OBJECT_ID('tempdb..#Cbtes_Items') IS NOT NULL DROP TABLE #Cbtes_Items
	IF OBJECT_ID('tempdb..#Cbtes_Tipos') IS NOT NULL DROP TABLE #Cbtes_Tipos

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage
	RETURN 0

END TRY  
BEGIN CATCH  

	IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

	IF OBJECT_ID('tempdb..#Cbtes') IS NOT NULL DROP TABLE #Cbtes
	IF OBJECT_ID('tempdb..#Cbtes_Items') IS NOT NULL DROP TABLE #Cbtes_Items
	IF OBJECT_ID('tempdb..#Cbtes_Tipos') IS NOT NULL DROP TABLE #Cbtes_Tipos

	EXECUTE usp_GetErrorInfo

	RETURN 9999
END CATCH
GO


CREATE PROCEDURE dbo.CPJ_Cbtes_Reten_Agregar	@pJson VARCHAR(8000)
AS
SET NOCOUNT ON

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans		     	TINYINT
DECLARE @pModoDebug			    	TINYINT
DECLARE @pId_Usuario			    SMALLINT
DECLARE @pId_Trans					INT
DECLARE @pNro						DECIMAL(16,0)
DECLARE @pId_Tipo_Reten				VARCHAR(10)
DECLARE @pImporte					DECIMAL(13,2)
DECLARE @pObservaciones				VARCHAR(8000)
DECLARE @pImp_Pago_Acum				DECIMAL(12,2)
DECLARE @pImp_No_Imponible			DECIMAL(12,2)
DECLARE @pImp_Base_Imponible		DECIMAL(12,2)
DECLARE @pPorc						DECIMAL(7,4)
DECLARE @pImp_Determinado			DECIMAL(12,2)
DECLARE @pImp_Reten_Ant				DECIMAL(12,2)
DECLARE @pFecha						DATETIME

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Usuario				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pNro						= ISNULL(CONVERT(DECIMAL(16,0), dbo.CF_JSON_VALUE(@pJson,'Nro')), 0)
SET @pId_Tipo_Reten				= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Reten')), '')
SET @pImporte					= ISNULL(CONVERT(DECIMAL(13,2), dbo.CF_JSON_VALUE(@pJson,'Importe')), 0)
SET @pObservaciones				= ISNULL(CONVERT(VARCHAR(8000), dbo.CF_JSON_VALUE(@pJson,'Observaciones')), '')
SET @pImp_Pago_Acum				= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_Pago_Acum')), 0)
SET @pImp_No_Imponible			= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_No_Imponible')), 0)
SET @pImp_Base_Imponible		= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_Base_Imponible')), 0)
SET @pPorc						= ISNULL(CONVERT(DECIMAL(7,4), dbo.CF_JSON_VALUE(@pJson,'Porc')), 0)
SET @pImp_Determinado			= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_Determinado')), 0)
SET @pImp_Reten_Ant				= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Imp_Reten_Ant')), 0)
SET @pFecha						= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')), '19000101')
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/

/*FIN Variables Locales*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

BEGIN TRY
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Reten_Agregar'
		PRINT 'Parametros: '
		PRINT '@pJson: ' + @pJson
	END

	/*=============================================================================================================================*/

	IF(@pId_Usuario = 0)
	BEGIN
		SET @pId_Usuario = -1
	END

	IF(@pId_Trans = 0)											RAISERROR ('Id_Trans can not be zero.', 16,  1) 
	IF(@pNro = 0)												RAISERROR ('Nro can not be zero.', 16,  1) 
	IF(@pId_Tipo_Reten = '')									RAISERROR ('Id_Tipo_Reten can not be zero.', 16,  1) 
	IF(@pFecha = '19000101')									RAISERROR ('Fecha can not be blank.', 16,  1)
	
	/*=============================================================================================================================*/
	
	INSERT INTO Cbtes_Reten
	(Id_Trans,				Nro,					Id_Tipo_Reten,
	Importe,				Observaciones,			Imp_Pago_Acum,
	Imp_No_Imponible,		Imp_Base_Imponible,		Porc,
	Imp_Determinado,		Imp_Reten_Ant,			Fecha)
	VALUES
	(@pId_Trans,			@pNro,					@pId_Tipo_Reten,
	@pImporte,				@pObservaciones,		@pImp_Pago_Acum,
	@pImp_No_Imponible,		@pImp_Base_Imponible,	@pPorc,
	@pImp_Determinado,		@pImp_Reten_Ant,		@pFecha)
	
	/*===================================================================*/
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END

	/*===================================================================*/	

	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT')  + ',' +
								dbo.CF_Json_ParsearVariable('nro',@pNro, 'DECIMAL(16,0)')  + ',' +
								dbo.CF_Json_ParsearVariable('id_tipo_reten', @pId_Tipo_Reten, 'VARCHAR(10)') + 
								'}'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Reten_Agregar'
	END
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	RETURN 9999
END CATCH

RETURN 0

/*
EXEC dbo.CPJ_Cbtes_Reten_Agregar		'{"FlagUsarTrans":"0",
										"ModoDebug":"0",
										"Id_Usuario":"-1",
										"Id_Trans":"1203931",
										"Nro":"1",
										"Id_Tipo_Reten":"PERIBRU",
										"Importe":"1421.28",
										"Observaciones":"",
										"Imp_Pago_Acum":"0",
										"Imp_No_Imponible":"0",
										"Porc":"0",
										"Imp_Determinado":"0",
										"Imp_Reten_Ant":"0",
										"Fecha":"2021-04-20T00:00:00"
										}'
*/
GO


CREATE  PROCEDURE [dbo].[CPJ_Cbtes_Trans_Caja_Generar] @pJson VARCHAR(8000)

AS
SET NOCOUNT ON
/*
 * LOG VERSIONES:
 * 13/09/2021: Se agrego Log de Versiones
 * 13/04/2022: Se agrego parametro Flag_LoteUnico
*/

/*Declaracion Variables Json*/

DECLARE @pFlagUsarTrans				TINYINT
DECLARE @pModoDebug					TINYINT
DECLARE @pId_Usuario				SMALLINT
DECLARE @pId_Periodo_Caja_Ori       INT
DECLARE @pId_Periodo_Caja_Dest      INT
DECLARE @pFecha						DATETIME
DECLARE @pImporte					DECIMAL(12,2)
DECLARE @pId_Tipo_Cbte				CHAR(4)
DECLARE @Id_Tipo_Val				CHAR(4)
DECLARE @pId_Concepto	    	    INT
DECLARE @pId_Moneda					CHAR(3)
DECLARE @pCotizacion				DECIMAL(9, 4)
DECLARE @pFecha_Val DATE
DECLARE @pFecha_Vence DATE
DECLARE @pFecha_Acreditacion DATE
DECLARE @pFecha_Emision DATE

DECLARE @pValor_Nro CHAR(12) ,@pId_Tarjeta CHAR(12),@pTarjeta_Nro CHAR(20),
	        @pTarjeta_Lote CHAR(20), @pTarjeta_Vence DATETIME, @pId_Cta_Banco CHAR(12)

DECLARE @pOmitir_Resultado_OK		TINYINT
DECLARE @pId_Tipo_Val               CHAR(3)

SET @pValor_Nro = '' 
SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Usuario			= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), 0)
