CREATE PROCEDURE [dbo].[CPJ_Centro_Costos_Saldos_Generar] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON

/*Variables Recibidas por Parametros*/
DECLARE	@pId_Usuario			INT
DECLARE	@pFlagUsarTrans			TINYINT
DECLARE	@pModoDebug				TINYINT

DECLARE	@pId_Centro_Costo		VARCHAR(10)
DECLARE	@pId_Unid_Negocio		CHAR(10)
DECLARE	@pFecha					DATETIME

SET @pId_Usuario				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Usuario')), 0)
SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)

SET @pId_Centro_Costo	        = ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Centro_Costo')), '')
SET @pId_Unid_Negocio	        = ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')), '')
SET @pFecha						= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha')),GETDATE())
/*FIN Variables Recibidas por Parametros*/

/*Variables Locales*/
DECLARE @Id_Centro_Costo_Saldo_Existente					INT
DECLARE @Id_Centro_Costo_Saldo_Existente_Periodo_Anterior	INT
DECLARE @Json_Parametro										VARCHAR(8000)
DECLARE @Fecha_Desde										DATETIME
DECLARE @Fecha_Hasta										DATETIME
DECLARE @rta_CPJ_Productos_Cobros			TABLE (	Id_Centro_Costo		VARCHAR(10),
													Centro_Costo		VARCHAR(200),
													Imp_Prod_CIva		DECIMAL(15,2),
													Participacion		DECIMAL(12,2))

DECLARE @rta_CPJ_Pagos_CC					TABLE (	Id_Centro_Costo		VARCHAR(10),
													Centro_Costo		VARCHAR(200),
													Debe				DECIMAL(15,2),
													Haber				DECIMAL(15,2),
													Saldo				DECIMAL(15,2))

DECLARE @Id_Centro_Costo								CHAR(10)
DECLARE @Id_Unid_Negocio								CHAR(10)
DECLARE @Periodo										DATE
DECLARE @SA												DECIMAL(16,2)
DECLARE @Ingresos										DECIMAL(16,2)
DECLARE @Egresos										DECIMAL(16,2)
DECLARE @Saldo											DECIMAL(16,2)
DECLARE @Nota											VARCHAR(8000)
/*FIN Variables Locales*/

-------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a CPJ_Centro_Costos_Saldos_Generar'
END

-------------------------------------------------------------------------------------------------------------------------------------------------------

SET @Fecha_Desde = dbo.CF_FOMONTH(@pFecha)
SET @Fecha_Hasta = dbo.CF_EOMONTH(@pFecha)

-------------------------------------------------------------------------------------------------------------------------------------------------------

SET @Id_Centro_Costo					= @pId_Centro_Costo
SET @Id_Unid_Negocio					= @pId_Unid_Negocio
SET @Periodo							= @Fecha_Desde
SET @Nota								= 'Actualizado el ' + CONVERT(VARCHAR(20), GETDATE(), 120)

-------------------------------------------------------------------------------------------------------------------------------------------------------

SET @Ingresos = 0

SET @Json_Parametro =	'''{' +
						dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'SMALLINT') + ',' +
						dbo.CF_Json_ParsearVariable('Id_Usuario', @pId_Usuario, 'SMALLINT') + ',' +
						dbo.CF_Json_ParsearVariable('Id_Centro_Costo', @pId_Centro_Costo, 'VARCHAR(10)') + ',' +
						dbo.CF_Json_ParsearVariable('FechaDesde', @Fecha_Desde, 'DATETIME') + ',' +
						dbo.CF_Json_ParsearVariable('FechaHasta', @Fecha_Hasta, 'DATETIME') + ',' +
						dbo.CF_Json_ParsearVariable('Id_Unid_Negocio', @pId_Unid_Negocio, 'VARCHAR(10)') + ',' +
						dbo.CF_Json_ParsearVariable('SoloResultado', 0, 'TINYINT') + ',' +
						dbo.CF_Json_ParsearVariable('Formato', 'CC', 'VARCHAR(3)') + ',' +
						dbo.CF_Json_ParsearVariable('Flag_Filtrar_CC', 1, 'TINYINT') +
						'}'''

IF(@pModoDebug = 1)
BEGIN
	PRINT 'CPJ_Productos_Cobros: ' + @Json_Parametro
END

INSERT INTO @rta_CPJ_Productos_Cobros
EXEC CPJ_Productos_Cobros @Json_Parametro

SET @Ingresos = ISNULL((SELECT SUM(Imp_Prod_CIva) FROM @rta_CPJ_Productos_Cobros), 0)

-----------------------------------------------------------------------------------------------------------------------------------------------------

SET @Egresos = 0

SET @Json_Parametro =	'''{' +
						dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'SMALLINT') + ',' +
						dbo.CF_Json_ParsearVariable('Id_Usuario', @pId_Usuario, 'SMALLINT') + ',' +
						dbo.CF_Json_ParsearVariable('Id_Centro_Costo', @pId_Centro_Costo, 'VARCHAR(10)') + ',' +
						dbo.CF_Json_ParsearVariable('Fecha_Desde', @Fecha_Desde, 'DATETIME') + ',' +
						dbo.CF_Json_ParsearVariable('Fecha_Hasta', @Fecha_Hasta, 'DATETIME') + ',' +
						dbo.CF_Json_ParsearVariable('Id_Alias_Cta_Cont', 0 , 'SMALLINT') + ',' +
						dbo.CF_Json_ParsearVariable('Id_Unid_Negocio', @pId_Unid_Negocio, 'VARCHAR(10)') + ',' +
						dbo.CF_Json_ParsearVariable('SoloResultado', 0, 'TINYINT') + ',' +
						dbo.CF_Json_ParsearVariable('Tipo_Reporte', 'CC', 'VARCHAR(3)') + ',' +
						dbo.CF_Json_ParsearVariable('Flag_Filtrar_CC', 1, 'TINYINT') +
						'}'''

IF(@pModoDebug = 1)
BEGIN
	PRINT 'CPJ_Pagos_CC: ' + @Json_Parametro
END

INSERT INTO @rta_CPJ_Pagos_CC
EXEC CPJ_Pagos_CC @Json_Parametro

SET @Egresos = ISNULL((SELECT SUM(Debe) FROM @rta_CPJ_Pagos_CC), 0)

-------------------------------------------------------------------------------------------------------------------------------------------------------

SET @Id_Centro_Costo_Saldo_Existente_Periodo_Anterior = ISNULL(	(SELECT MAX(Id_Centro_Costo_Saldo)
																FROM Centro_Costos_Saldos
																WHERE
																Id_Centro_Costo = @pId_Centro_Costo
																AND Id_Unid_Negocio = @pId_Unid_Negocio
																AND Periodo = DATEADD(MONTH, -1, @Fecha_Desde))
																, 0)

IF(@Id_Centro_Costo_Saldo_Existente_Periodo_Anterior <> 0)
BEGIN
	SELECT
	@SA		= ISNULL(Saldo, 0)
	FROM Centro_Costos_Saldos
	WHERE
	Id_Centro_Costo_Saldo = @Id_Centro_Costo_Saldo_Existente_Periodo_Anterior
END
ELSE
BEGIN
	SET @SA = 0
END

-------------------------------------------------------------------------------------------------------------------------------------------------------

SET @Saldo = @SA + @Ingresos - @Egresos

-------------------------------------------------------------------------------------------------------------------------------------------------------

SET @Id_Centro_Costo_Saldo_Existente = ISNULL(	(SELECT MAX(Id_Centro_Costo_Saldo)
												FROM Centro_Costos_Saldos
												WHERE
												Id_Centro_Costo = @pId_Centro_Costo
												AND Id_Unid_Negocio = @pId_Unid_Negocio
												AND Periodo = @Fecha_Desde)
												, 0)

IF(@Id_Centro_Costo_Saldo_Existente = 0)
BEGIN
	INSERT INTO Centro_Costos_Saldos
	(Id_Centro_Costo,
	Id_Unid_Negocio,
	Periodo,
	SA,
	Ingresos,
	Egresos,
	Saldo,
	Nota)
	VALUES
	(@Id_Centro_Costo,
	@Id_Unid_Negocio,
	@Periodo,
	@SA,
	@Ingresos,
	@Egresos,
	@Saldo,
	@Nota)

	
	SET @Id_Centro_Costo_Saldo_Existente = ISNULL(	(SELECT MAX(Id_Centro_Costo_Saldo)
												FROM Centro_Costos_Saldos
												WHERE
												Id_Centro_Costo = @pId_Centro_Costo
												AND Id_Unid_Negocio = @pId_Unid_Negocio
												AND Periodo = @Fecha_Desde)
												, 0)
END
ELSE
BEGIN
	UPDATE Centro_Costos_Saldos
	SET
	SA = @SA,
	Ingresos = @Ingresos,
	Egresos = @Egresos,
	Saldo = @Saldo,
	Nota = @Nota
	WHERE
	Id_Centro_Costo_Saldo = @Id_Centro_Costo_Saldo_Existente
END

-------------------------------------------------------------------------------------------------------------------------------------------------------

SELECT 
Id_Centro_Costo_Saldo,
Id_Centro_Costo,
Id_Unid_Negocio,
Periodo,
SA,
Ingresos,
Egresos,
Saldo,
Nota
FROM Centro_Costos_Saldos
WHERE
Id_Centro_Costo_Saldo = @Id_Centro_Costo_Saldo_Existente

-------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@pModoDebug = 1)
BEGIN
	PRINT 'FIN CPJ_Centro_Costos_Saldos_Generar'
END

/*
EXEC dbo.CPJ_Centro_Costos_Saldos_Generar   '{
												"Id_Usuario":"-1",
												"FlagUsarTrans":"0",
												"ModoDebug":"1",
												"Id_Centro_Costo":"7",
												"Id_Unid_Negocio":"",
												"Fecha":"20210401"
											  }'

EXEC dbo.CPJ_Centro_Costos_Saldos_Generar   '{
												"Id_Usuario":"-1",
												"FlagUsarTrans":"0",
												"ModoDebug":"1",
												"Id_Centro_Costo":"7",
												"Id_Unid_Negocio":"",
												"Fecha":"20210501"
											  }'
*/
GO



CREATE PROCEDURE dbo.CPJ_Centro_Costos_Saldos_Resumen_Anual @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON

/*Variables Recibidas por Parametros*/
DECLARE	@pId_Usuario			INT
DECLARE	@pFlagUsarTrans			TINYINT
DECLARE	@pModoDebug				TINYINT

DECLARE	@pAnio					SMALLINT

SET @pId_Usuario				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Usuario')), 0)
SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)

SET @pAnio				        = ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Anio')), 0)
/*FIN Variables Recibidas por Parametros*/

/*Variables Locales*/
DECLARE @Id_Centro_Costo						VARCHAR(10)
DECLARE @CC_Descripcion							VARCHAR(200)
DECLARE @Id_Centro_Costo_Saldo_Mas_Reciente		INT
DECLARE @Periodo_Mas_Reciente					DATE
DECLARE @Saldo_Mas_Reciente						DECIMAL(16,2)

DECLARE @rta_CPJ_Centro_Costos_Saldos_Resumen		TABLE (	Id_Centro_Costo			VARCHAR(10),
															Centro_Costo			VARCHAR(200),
															Ult_Periodo_Generado	DATE,
															Saldo					DECIMAL(16,2))
/*FIN Variables Locales*/

-------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a CPJ_Centro_Costos_Saldos_Resumen_Anual'
END

DECLARE curCentro_Costos_Saldos CURSOR FOR
SELECT DISTINCT CC.Id_Centro_Costo, ISNULL(CC.Descripcion, '') AS CC_Descripcion
FROM Centro_Costos CC, Centro_Costos_Saldos CCS
WHERE
CC.Id_Centro_Costo = CCS.Id_Centro_Costo
AND DATEPART(YEAR, CCS.Periodo) = @pAnio

OPEN curCentro_Costos_Saldos
FETCH NEXT FROM curCentro_Costos_Saldos INTO @Id_Centro_Costo, @CC_Descripcion
WHILE @@FETCH_STATUS = 0
BEGIN

	SET @Id_Centro_Costo_Saldo_Mas_Reciente = ISNULL((SELECT TOP 1 Id_Centro_Costo_Saldo
													FROM Centro_Costos_Saldos
													WHERE
													Id_Centro_Costo = @Id_Centro_Costo
													AND DATEPART(YEAR, Periodo) = @pAnio
													ORDER BY Periodo DESC)
													, 0)

	SELECT
	@Periodo_Mas_Reciente	= ISNULL(Periodo, '19000101'),
	@Saldo_Mas_Reciente		= ISNULL(Saldo, 0)
	FROM Centro_Costos_Saldos
	WHERE
	Id_Centro_Costo_Saldo = @Id_Centro_Costo_Saldo_Mas_Reciente

	INSERT INTO @rta_CPJ_Centro_Costos_Saldos_Resumen
	(Id_Centro_Costo, Centro_Costo, Ult_Periodo_Generado, Saldo)
	VALUES
	(@Id_Centro_Costo, @CC_Descripcion, @Periodo_Mas_Reciente, @Saldo_Mas_Reciente)

	FETCH NEXT FROM curCentro_Costos_Saldos INTO @Id_Centro_Costo, @CC_Descripcion
END
CLOSE curCentro_Costos_Saldos
DEALLOCATE curCentro_Costos_Saldos

SELECT * FROM @rta_CPJ_Centro_Costos_Saldos_Resumen

-------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@pModoDebug = 1)
BEGIN
	PRINT 'FIN CPJ_Centro_Costos_Saldos_Resumen_Anual'
END

/*
EXEC dbo.CPJ_Centro_Costos_Saldos_Resumen_Anual   '{
												"Id_Usuario":"-1",
												"FlagUsarTrans":"0",
												"ModoDebug":"1",
												"Anio":"2021"
												}'
*/
GO



CREATE PROCEDURE dbo.CPJ_Centro_Costos_Saldos_Resumen_Anual_Detallado @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON

/*Variables Recibidas por Parametros*/
DECLARE	@pId_Usuario			INT
DECLARE	@pFlagUsarTrans			TINYINT
DECLARE	@pModoDebug				TINYINT

DECLARE	@pAnio					SMALLINT
DECLARE @pId_Centro_Costo		VARCHAR(10)

SET @pId_Usuario				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Usuario')), 0)
SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)

SET @pAnio				        = ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Anio')), 0)
SET @pId_Centro_Costo	        = ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Centro_Costo')), '')
/*FIN Variables Recibidas por Parametros*/

/*Variables Locales*/
DECLARE @Id_Centro_Costo						VARCHAR(10)
DECLARE @CC_Descripcion							VARCHAR(200)
DECLARE @Id_Centro_Costo_Saldo_Mas_Reciente		INT
DECLARE @Periodo_Mas_Reciente					DATE
DECLARE @Saldo_Mas_Reciente						DECIMAL(16,2)

DECLARE @rta_CPJ_Centro_Costos_Saldos_Resumen_Anual_Detallado		TABLE (	Mes				TINYINT,
																			Periodo			DATE,
																			SA				DECIMAL(16,2),
																			Ingresos		DECIMAL(16,2),
																			Egresos			DECIMAL(16,2),
																			Saldo			DECIMAL(16,2),
																			Nota			TEXT,
																			Flag_Generado	TINYINT)
DECLARE @Mes									TINYINT
DECLARE @Id_Centro_Costo_Saldo_Mes_Seleccionado	INT
DECLARE @Periodo								DATE
/*FIN Variables Locales*/

-------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a CPJ_Centro_Costos_Saldos_Resumen_Anual_Detallado'
END


-------------------------------------------------------------------------------------------------------------------------------------------------------

SET @Mes = 0

WHILE @Mes < 12
BEGIN
	SET @Mes = @Mes + 1
	SET @Periodo = CONVERT(DATE, (CONVERT(VARCHAR(10), @pAnio) + CONVERT(VARCHAR(2), RIGHT('00' + CAST(@Mes AS VARCHAR), 2)) + '01'))

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Mes: ' + CONVERT(VARCHAR(2), RIGHT('00' + CAST(@Mes AS VARCHAR), 2)) + '. Periodo: ' + CONVERT(VARCHAR(10), @Periodo, 102)
	END

	SET @Id_Centro_Costo_Saldo_Mes_Seleccionado = ISNULL((SELECT MAX(Id_Centro_Costo_Saldo)
														FROM Centro_Costos_Saldos CCS
														WHERE
														CCS.Id_Centro_Costo = @pId_Centro_Costo
														AND CCS.Periodo = @Periodo)
														, 0)
	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Id_Centro_Costo_Saldo_Mes_Seleccionado: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo_Saldo_Mes_Seleccionado) 
	END

	IF(@Id_Centro_Costo_Saldo_Mes_Seleccionado > 0)
	BEGIN
		INSERT INTO @rta_CPJ_Centro_Costos_Saldos_Resumen_Anual_Detallado 
		(Mes,	Periodo,	SA,		Ingresos,	Egresos,	Saldo,	Nota,	Flag_Generado) 
		SELECT 
		@Mes,	Periodo,	SA,		Ingresos,	Egresos,	Saldo,	Nota,	1
		FROM Centro_Costos_Saldos
		WHERE
		Id_Centro_Costo_Saldo = @Id_Centro_Costo_Saldo_Mes_Seleccionado
	END
	ELSE
	BEGIN
		INSERT INTO @rta_CPJ_Centro_Costos_Saldos_Resumen_Anual_Detallado (Mes, Flag_Generado) VALUES (@Mes, 0)
	END
END

-------------------------------------------------------------------------------------------------------------------------------------------------------

SELECT * FROM @rta_CPJ_Centro_Costos_Saldos_Resumen_Anual_Detallado

-------------------------------------------------------------------------------------------------------------------------------------------------------

IF(@pModoDebug = 1)
BEGIN
	PRINT 'FIN CPJ_Centro_Costos_Saldos_Resumen_Anual_Detallado'
END

/*
EXEC dbo.CPJ_Centro_Costos_Saldos_Resumen_Anual_Detallado   '{
															"Id_Usuario":"-1",
															"FlagUsarTrans":"0",
															"ModoDebug":"1",
															"Anio":"2021",
															"Id_Centro_Costo":"7"
															}'
*/
GO


CREATE PROCEDURE [dbo].[CPJ_CleverAPI_Ejecutar] @pJson VARCHAR(8000)
AS 

/*
 * LOG VERSIONES:
 * 22/08/2022: Se crea el Stored
*/

/*-------------------------------------------------------------------------------------------------------------------------------------*/

/*
NOTA IMPORTANTE:

Para utilizar este Stored primero se debe haber configurado el motor de SQL a traves del Stored: CP_ConfigurarMSSQL
*/

/*-------------------------------------------------------------------------------------------------------------------------------------*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug				TINYINT
DECLARE @pAPI_URL				VARCHAR(255)
DECLARE @pAPI_Metodo			VARCHAR(255)
DECLARE @pAPI_Data				VARCHAR(8000)
DECLARE @pAPI_Token				VARCHAR(50)
DECLARE @pAPI_Base_Datos		VARCHAR(100)

SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pAPI_URL					= ISNULL(CONVERT(VARCHAR(255), dbo.CF_JSON_VALUE(@pJson,'API_URL')),'')
SET @pAPI_Metodo				= ISNULL(CONVERT(VARCHAR(255), dbo.CF_JSON_VALUE(@pJson,'API_Metodo')),'')
SET @pAPI_Data					= ISNULL(CONVERT(VARCHAR(8000), dbo.CF_JSON_VALUE(@pJson,'API_Data')),'')
SET @pAPI_Token					= ISNULL(CONVERT(VARCHAR(50), dbo.CF_JSON_VALUE(@pJson,'API_Token')),'')
SET @pAPI_Base_Datos			= ISNULL(CONVERT(VARCHAR(255), dbo.CF_JSON_VALUE(@pJson,'API_Base_Datos')),'')
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Obj_Token 		INT
DECLARE @Respuesta		VARCHAR(8000)
DECLARE @Body			VARCHAR(8000)
DECLARE @Estado_Html	INT
/*FIN Variables Locales*/

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a Stored Procedure: CPJ_CleverAPI_Ejecutar'
	PRINT 'Parametros:'
	PRINT 'pAPI_URL: ' + @pAPI_URL  + '. pAPI_Token: ' + @pAPI_Token
	PRINT 'pAPI_Metodo: ' + @pAPI_Metodo 
	PRINT 'pAPI_Data: ' + @pAPI_Data 
	PRINT 'pAPI_Base_Datos: ' + @pAPI_Base_Datos
	PRINT ''
END

/*-------------------------------------------------------------------------------------------------------------------------------------*/

IF(@pAPI_Metodo = '')	RAISERROR ('El parametro: API_Metodo no puede estar vacio.', 16,  1 )

IF(@pAPI_Data = '')		RAISERROR ('El parametro: API_Data no puede estar vacio.', 16,  1 )

IF(@pAPI_URL = '')
BEGIN
	SET @pAPI_URL = dbo.CF_xParam('API_Url')
END

IF(@pAPI_Token = '')
BEGIN
	SET @pAPI_Token = dbo.CF_xParam('Api_Token')
END

IF(@pAPI_Base_Datos = '')
BEGIN
	SET @pAPI_Base_Datos = DB_NAME()
END

/*-------------------------------------------------------------------------------------------------------------------------------------*/

SET @Body = @pAPI_Metodo + '=1'
SET @Body = @Body + '&' + 'data=' + '{' + @pAPI_Data + '}'
SET @Body = @Body + '&' + 'token=' + @pAPI_Token
SET @Body = @Body + '&' + 'db=' + @pAPI_Base_Datos

IF(@pModoDebug = 1)
BEGIN
	PRINT '@Body: ' + @Body
END

/*-------------------------------------------------------------------------------------------------------------------------------------*/
/*
EXEC SP_OACreate 'WinHttp.WinHttpRequest.5.1', @Obj_Token OUT;
IF @Obj_Token <> 0 RAISERROR('ERROR CPJ_CleverAPI_Ejecutar: No pudo conectarse al servidor.', 10, 1);

EXEC SP_OAMethod @Obj_Token, 'open', NULL, 'POST', @pAPI_URL, 'false'
IF @Obj_Token <> 0 RAISERROR('ERROR CPJ_CleverAPI_Ejecutar: No se pudo abrir la conexion.', 10, 1);

EXEC SP_OAMethod @Obj_Token, 'setRequestHeader', null, 'Content-Type', 'application/x-www-form-urlencoded'

EXEC SP_OAMethod @Obj_Token, 'send', NULL, @Body

EXEC SP_OAGetProperty @Obj_Token, 'status', @Estado_Html OUTPUT
EXEC SP_OAGetProperty  @Obj_Token, 'responseText', @Respuesta OUTPUT

EXEC SP_OADestroy @Obj_Token
*/

EXEC SP_OACreate 'WinHttp.WinHttpRequest.5.1', @Obj_Token OUT;
IF @Obj_Token = 0 RAISERROR('ERROR CPJ_CleverAPI_Ejecutar: No pudo conectarse al servidor.', 10, 1);

-- Modo Debug (Opcional)
IF (@pModoDebug = 1)
BEGIN
    PRINT '@Obj_Token: ' + CONVERT(VARCHAR(8000), @Obj_Token)
END

-- Abrir la conexión
EXEC SP_OAMethod @Obj_Token, 'open', NULL, 'POST', @pAPI_URL, 'false';

-- Establecer el encabezado
EXEC SP_OAMethod @Obj_Token, 'setRequestHeader', null, 'Content-Type', 'application/x-www-form-urlencoded';

-- Enviar la solicitud
EXEC SP_OAMethod @Obj_Token, 'send', NULL, @Body;

-- Obtener el código de estado HTTP
EXEC SP_OAGetProperty @Obj_Token, 'status', @Estado_Html OUTPUT;

-- Verificar el código de estado HTTP
IF @Estado_Html <> 200
BEGIN
    RAISERROR('ERROR CPJ_CleverAPI_Ejecutar: La solicitud HTTP falló con el código de estado: %d.', 16, 1, @Estado_Html);
END

-- Obtener la respuesta HTTP
EXEC SP_OAGetProperty @Obj_Token, 'responseText', @Respuesta OUTPUT;

-- Destruir el objeto COM
EXEC SP_OADestroy @Obj_Token;


/*-------------------------------------------------------------------------------------------------------------------------------------*/

SELECT 
@Respuesta			AS Respuesta,
@Estado_Html		AS Rta_Estado 

