CREATE PROCEDURE [dbo].[CPJ_Cli_Catcte_Control]  @pJsonRecibido VARCHAR(8000)	 

AS
SET NOCOUNT ON 
DECLARE 	@pId_Cliente			INT,
			@pReparar				CHAR(1),
			@pDebug					INT,
			@pOmitirResult			CHAR(1),
			@Cli_Ref_CtaCte_Agrup	INT,
			@Id_Cliente_Tit			INT,
			@Sql					VARCHAR(MAX)


SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')),0)
SET @pReparar					= UPPER(ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Reparar')),''))
SET @pDebug						= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Debug')),0)
SET @pOmitirResult				= UPPER(ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'OmitirResult')),'N'))

SET @Cli_Ref_CtaCte_Agrup = ISNULL(CONVERT(INT,dbo.CF_xParam('Cli_Ref_CtaCte_Agrup')),0)

CREATE TABLE  #Respuesta (Id_Error INT, Error_Msg VARCHAR(1000),Accion VARCHAR(5000))
DECLARE @Trans TABLE (Id_Trans INT)

IF @Cli_Ref_CtaCte_Agrup <> 0	
	SET @Id_Cliente_Tit = dbo.CF_Cli_Id_Cliente_Ref(@pId_Cliente)
ELSE
	SET @Id_Cliente_Tit = @pId_Cliente

/**************** CReo la tabla Clientes  **************************/

SELECT Id_Cliente INTO #Cli FROM Clientes WHERE 1 = 0
IF @Cli_Ref_CtaCte_Agrup <> 0
	SET @Sql = 'INSERT INTO #Cli 
							SELECT Id_Cliente FROM Clientes C
							WHERE (C.Id_Cliente = ' + CONVERT(VARCHAR(16),@Id_Cliente_Tit) +' 
								OR C.Id_Cliente IN (SELECT C2.Id_Cliente  FROM Clientes C2 WHERE C2.Id_Cliente_Ref = ' + CONVERT(VARCHAR(16),@Id_Cliente_Tit) +') 
								)'
ELSE
	SET @Sql = 'INSERT INTO #Cli 
							SELECT Id_Cliente FROM Clientes C 
							WHERE C.Id_Cliente = ' + CONVERT(VARCHAR(16),@Id_Cliente_Tit)
EXEC (@Sql)

/**************** CReo la tabla Cbtes  **************************/
SELECT C.Id_Trans,C.Id_Cliente,C.Fecha,C.Imp_Total,C.Saldo,C.Id_Estado_Cbte,T.Compromete_Factura,T.Compromete_Recibos,C.Id_Tipo_Cbte
	INTO #Cbtes
	FROM Cbtes C 
		JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
		JOIN #Cli L ON L.Id_Cliente = C.Id_Cliente 
	WHERE (T.Compromete_Factura IN (1,-1) OR T.Compromete_Recibos IN (1,-1) )
			AND C.Id_Estado_Cbte IN (1,2,4)
			AND (C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
CREATE INDEX IX_zCbtes_xxx ON #Cbtes (Id_Trans)



/**************** Tipo de cbte mal configurado.  **************************/

SET @Sql = 'INSERT INTO #Respuesta
			SELECT 7999,''Tipo de Cbte. mal configurado, '' + T.Id_Tipo_Cbte  + '' (no puede ser recibo y factura) '','''' 
				 FROM  Cbtes_Tipos T
				 WHERE T.Compromete_Factura IN (1,-1) AND T.Compromete_Recibos IN (1,-1) '
				
IF @pDebug = 1 PRINT @Sql
EXEC(@sql)


/**************** Cbtes con importe negativo.  **************************/
IF @pReparar = 'S'
BEGIN
	SET @Sql = 'UPDATE Cbtes SET Imp_Total = ABS(C.Imp_Total)
						,Saldo = ABS(C.Saldo)
						,Imp_Gravado = ABS(C.Imp_Gravado)		
				FROM Cbtes C 
					JOIN #Cbtes B ON B.Id_Trans = C.Id_Trans 
				WHERE C.Imp_Total < 0
				 '
    IF @pDebug = 1 PRINT @Sql
	EXEC(@sql)
END

SET @Sql = 'INSERT INTO #Respuesta
			SELECT 9000,''Cbtes con importe negativo en cbtes, '' + C.Id_Tipo_Cbte + '' Transacción: '' 
					+ CONVERT(VARCHAR(16),C.Id_Trans) + '' '' + CONVERT(VARCHAR,C.Fecha,112)  + '' '' + CONVERT(VARCHAR,C.Fecha,112)  + '' '' + CONVERT(VARCHAR,C.Fecha,112) 
					+ '' Cliente: '' + CONVERT(VARCHAR(16),C.Id_Cliente)  ,''REPARACIÓN AUTOMÁTICA POSIBLE'' 
				FROM Cbtes C 
					JOIN #Cbtes B ON B.Id_Trans = C.Id_Trans 
				WHERE C.Imp_Total < 0
					
					 '
IF @pDebug = 1 PRINT @Sql
EXEC(@sql)



/****************Id_cliente difeente en ctat.cte.  **************************/
IF @pReparar = 'S'
BEGIN
	SET @Sql = 'UPDATE Clientes_CtaCte SET Id_Cliente = B.Id_Cliente
				FROM Clientes_CtaCte K
					JOIN #Cbtes B ON B.Id_Trans = K.Id_Trans
				 WHERE B.Id_Cliente <> K.Id_Cliente'
	IF @pDebug = 1 PRINT @Sql
	EXEC(@sql)
END

SET @Sql = 'INSERT INTO #Respuesta
			SELECT 9010,''Codigo de Cliente diferente en cta.cte., '' + B.Id_Tipo_Cbte + '' Transacción: '' + CONVERT(VARCHAR,K.Id_Trans) + '' Cliente: '' + CONVERT(VARCHAR(16),K.Id_Cliente)  ,''REPARACIÓN AUTOMÁTICA POSIBLE'' 
				 FROM Clientes_CtaCte K
					JOIN #Cbtes B ON B.Id_Trans = K.Id_Trans 
				 WHERE B.Id_Cliente <> K.Id_Cliente'
IF @pDebug = 1 PRINT @Sql
EXEC(@sql)

/**************** diferente en fechas  **************************/

IF @pReparar = 'S'
BEGIN
	SET @Sql = 'UPDATE Clientes_CtaCte SET Fecha = B.Fecha
				FROM Clientes_CtaCte K
					JOIN #Cbtes B ON B.Id_Trans = K.Id_Trans
				 WHERE B.Fecha <> K.Fecha'
	IF @pDebug = 1 PRINT @Sql
	EXEC(@sql)
END

SET @Sql = 'INSERT INTO #Respuesta
			SELECT 9015,''Fecha ctat.cte. , '' + B.Id_Tipo_Cbte + '' Transacción: '' + CONVERT(VARCHAR,K.Id_Trans) + '' Cliente: '' + CONVERT(VARCHAR(16),K.Id_Cliente)  ,''REPARACIÓN AUTOMÁTICA POSIBLE'' 
				 FROM Clientes_CtaCte K
					JOIN #Cbtes B ON B.Id_Trans = K.Id_Trans 
				 WHERE B.Fecha <> K.Fecha'
IF @pDebug = 1 PRINT @Sql
EXEC(@sql)



	
/*************** Aplicaciones fuera del grupo familiar erroenas de id_Cliente ctat.cte.  **************************/





SET @Sql = 'INSERT INTO #Respuesta
			SELECT 9030,''Aplicación no corresponde al grupo  '' + C2.Id_Tipo_Cbte + '' Transacción: '' + CONVERT(VARCHAR(16),C2.Id_Trans) + '' Cliente: '' + CONVERT(VARCHAR(16),C2.Id_Cliente) ,''REPARACIÓN MANUAL DESAPLICANDO TODA LA CTA.CTE.'' 
				 FROM Cbtes_Aplica A
						JOIN #Cbtes B	ON B.Id_Trans = A.Id_Trans_D
						JOIN Cbtes C2	ON A.Id_Trans = C2.Id_Trans
						JOIN Cbtes_Tipos T2 ON T2.Id_tipo_Cbte = C2.Id_Tipo_Cbte
					 WHERE (T2.Compromete_Factura = -1 OR T2.Compromete_Recibos IN (1,-1))
					 AND A.Id_trans_d != 0 AND A.Id_Trans != 0
					 AND C2.Id_Estado_Cbte IN (1,2,4) 
					 AND C2.Id_Cliente NOT IN (SELECT Id_Cliente  FROM #Cli )
					 '

IF @pDebug = 1 PRINT @Sql
EXEC(@sql)



IF @pReparar = 'S'
BEGIN
----------------------------por si falta un id_cliente mantengo el orginal -------------------
UPDATE Cbtes_Items SET Id_Cliente = C2.Id_Trans
      FROM Cbtes_Items I
						JOIN Cbtes_Aplica A ON I.Id_Trans = A.Id_Trans
						JOIN #Cbtes B	ON B.Id_Trans = A.Id_Trans_D
						JOIN Cbtes C2	ON A.Id_Trans = C2.Id_Trans
						JOIN Cbtes_Tipos T2 ON T2.Id_tipo_Cbte = C2.Id_Tipo_Cbte
					 WHERE (T2.Compromete_Factura =1 )
					 AND A.Id_trans_d != 0 AND A.Id_Trans != 0
					 AND C2.Id_Estado_Cbte IN (1,2,4) 
					 AND C2.Id_Cliente NOT IN (SELECT Id_Cliente  FROM #Cli )
					 AND ISNULL(I.Id_Cliente,0) = 0

----------------------------Pongo el nuevo titular -------------------
UPDATE Clientes_CtaCte SET Id_Cliente = @Id_Cliente_Tit
      FROM Clientes_CtaCte Cta
						JOIN Cbtes C2 ON C2.Id_Trans = Cta.Id_Trans
						JOIN Cbtes_Aplica A ON C2.Id_Trans = A.Id_Trans
						JOIN #Cbtes B	ON B.Id_Trans = A.Id_Trans_D
						JOIN Cbtes_Tipos T2 ON T2.Id_tipo_Cbte = C2.Id_Tipo_Cbte
					 WHERE (T2.Compromete_Factura = 1 )
					 AND A.Id_trans_d != 0 AND A.Id_Trans != 0
					 AND C2.Id_Estado_Cbte IN (1,2,4) 
					 AND C2.Id_Cliente NOT IN (SELECT Id_Cliente  FROM #Cli )

UPDATE Cbtes SET Id_Cliente = @Id_Cliente_Tit
      FROM Cbtes C2
						JOIN Cbtes_Aplica A ON C2.Id_Trans = A.Id_Trans
						JOIN #Cbtes B	ON B.Id_Trans = A.Id_Trans_D
						JOIN Cbtes_Tipos T2 ON T2.Id_tipo_Cbte = C2.Id_Tipo_Cbte
					 WHERE (T2.Compromete_Factura = 1 )
					 AND A.Id_trans_d != 0 AND A.Id_Trans != 0
					 AND C2.Id_Estado_Cbte IN (1,2,4) 
					 AND C2.Id_Cliente NOT IN (SELECT Id_Cliente  FROM #Cli )
END

SET @Sql = 'INSERT INTO #Respuesta
			SELECT 9030,''Aplicación no corresponde al grupo '' + C2.Id_Tipo_Cbte + '' (FC) Transacción: '' + CONVERT(VARCHAR(16),C2.Id_Trans) + '' Cliente: '' + CONVERT(VARCHAR(16),C2.Id_Cliente) ,''REPARACIÓN AUTOMÁTICA POSIBLE''  
				 FROM Cbtes_Aplica A
						JOIN #Cbtes B	ON B.Id_Trans = A.Id_Trans_D
						JOIN Cbtes C2	ON A.Id_Trans = C2.Id_Trans
						JOIN Cbtes_Tipos T2 ON T2.Id_tipo_Cbte = C2.Id_Tipo_Cbte
					 WHERE (T2.Compromete_Factura = 1 )
					 AND A.Id_trans_d != 0 AND A.Id_Trans != 0
					 AND C2.Id_Estado_Cbte IN (1,2,4) 
					 AND C2.Id_Cliente NOT IN (SELECT Id_Cliente  FROM #Cli )
					 '

IF @pDebug = 1 PRINT @Sql
EXEC(@sql)

/*************** Saldo cbte. de factura difiere del importe aplicado  **************************/
SELECT A.Id_Trans,SUM(A.Importe) AS Importe
	INTO #Aplica
		FROM Cbtes_Aplica A
			JOIN #Cbtes C ON C.Id_Trans = A.Id_Trans 
			JOIN #Cbtes X ON X.Id_Trans = A.Id_trans_d 
		WHERE A.Id_trans_d <> 0
		GROUP BY A.Id_Trans

SELECT A.Id_Trans_D,SUM(A.Importe) AS Importe
	INTO #Aplica_D
		FROM Cbtes_Aplica A
			 JOIN #Cbtes C ON C.Id_Trans = A.Id_Trans 
			 JOIN #Cbtes X ON X.Id_Trans = A.Id_trans_d 
		WHERE A.Id_trans <> 0
		GROUP BY A.Id_Trans_D


IF @pReparar = 'S'
BEGIN
	SET @Sql = 'UPDATE Cbtes SET Saldo = C.Imp_Total - A.Importe 
								,Id_Estado_Cbte =	CASE (C.Imp_Total - A.Importe )
														WHEN C.Imp_Total THEN 1
														WHEN 0 THEN 2
														ELSE 4
													END
				FROM Cbtes C
					  JOIN #Cbtes B ON B.Id_Trans = C.Id_Trans
					  JOIN #Aplica A ON A.Id_Trans = C.Id_Trans 
				WHERE B.Compromete_Factura = 1  
					AND C.Imp_Total - A.Importe <> C.SAldo'
	IF @pDebug = 1 PRINT @Sql
	EXEC(@sql)
END
SET @Sql = 'INSERT INTO #Respuesta
			SELECT 9040,''Saldo cbte. de factura difiere del importe aplicado '' + C.Id_Tipo_Cbte + '' Transacción: '' + CONVERT(VARCHAR(16),C.Id_Trans) + '' '' + CONVERT(VARCHAR,C.Fecha,112)  + '' Cliente: '' + CONVERT(VARCHAR(16),C.Id_Cliente) ,''REPARACIÓN AUTOMÁTICA POSIBLE''  
				 FROM Cbtes C
					  JOIN #Cbtes B ON B.Id_Trans = C.Id_Trans
					  JOIN #Aplica A ON A.Id_Trans = C.Id_Trans 
				WHERE B.Compromete_Factura = 1  
					AND C.Imp_Total - A.Importe <> C.SAldo'
IF @pDebug = 1 PRINT @Sql
EXEC(@sql)




