/*************** *Estado diferente en ctat.cte.  **************************/
-- PARCHE: el chequeo original comparaba CADA cuota de Clientes_CtaCte contra
-- el estado del comprobante y marcaba/reparaba cualquier cuota que no
-- coincidiera. Eso genera falsos positivos (y una reparacion automatica
-- destructiva) cuando el comprobante tiene varias cuotas y alguna quedo con
-- un estado distinto de forma legitima (ej: recibo aplicado parcial). Ahora
-- solo se considera inconsistencia real cuando NINGUNA cuota del comprobante
-- coincide con Cbtes. Si hay una unica cuota se repara automatico (caso
-- simple, sin ambiguedad); si hay varias cuotas y ninguna coincide, se deja
-- para revision manual porque no hay forma de saber cual corregir.
IF @pReparar = 'S'
BEGIN
	SET @Sql = 'UPDATE Clientes_CtaCte SET Id_Estado_Cbte =  C.Id_Estado_Cbte
					 FROM Clientes_CtaCte K
						JOIN #Cbtes C ON C.Id_Trans = K.Id_Trans 
					 WHERE C.Id_Estado_Cbte <> K.Id_Estado_Cbte
					 AND (SELECT COUNT(*) FROM Clientes_CtaCte K2 WHERE K2.Id_Trans = K.Id_Trans) = 1'
	IF @pDebug = 1 PRINT @Sql
	EXEC(@sql)
END

SET @Sql = 'INSERT INTO #Respuesta
			SELECT 9050,''Estado diferente en ctacte., '' + C.Id_Tipo_Cbte + '' Transacción: '' + CONVERT(VARCHAR(16),C.Id_Trans) + '' '' + CONVERT(VARCHAR,C.Fecha,112)  + '' Cliente: '' + CONVERT(VARCHAR(16),C.Id_Cliente) ,''REPARACIÓN AUTOMÁTICA POSIBLE'' 
				 FROM #Cbtes C
				 WHERE NOT EXISTS (SELECT 1 FROM Clientes_CtaCte K WHERE K.Id_Trans = C.Id_Trans AND K.Id_Estado_Cbte = C.Id_Estado_Cbte)
				 AND (SELECT COUNT(*) FROM Clientes_CtaCte K3 WHERE K3.Id_Trans = C.Id_Trans) = 1'
IF @pDebug = 1 PRINT @Sql
EXEC(@sql)

SET @Sql = 'INSERT INTO #Respuesta
			SELECT 9050,''Estado diferente en ctacte. (varias cuotas, ninguna coincide), '' + C.Id_Tipo_Cbte + '' Transacción: '' + CONVERT(VARCHAR(16),C.Id_Trans) + '' '' + CONVERT(VARCHAR,C.Fecha,112)  + '' Cliente: '' + CONVERT(VARCHAR(16),C.Id_Cliente) ,''REPARACIÓN MANUAL DESAPLICANDO TODA LA CTA.CTE.'' 
				 FROM #Cbtes C
				 WHERE NOT EXISTS (SELECT 1 FROM Clientes_CtaCte K WHERE K.Id_Trans = C.Id_Trans AND K.Id_Estado_Cbte = C.Id_Estado_Cbte)
				 AND (SELECT COUNT(*) FROM Clientes_CtaCte K3 WHERE K3.Id_Trans = C.Id_Trans) > 1'
IF @pDebug = 1 PRINT @Sql
EXEC(@sql)




IF @pReparar = 'S'
BEGIN
	SET @Sql = 'UPDATE Clientes_CtaCte SET Id_Estado_Cbte =  3
				 FROM Clientes_CtaCte K
						JOIN Cbtes C ON C.Id_Trans = K.Id_Trans 
						JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
						JOIN #Cli L ON L.Id_Cliente = C.Id_Cliente
				 WHERE C.Id_Estado_Cbte = 3
				 AND (T.Compromete_Factura IN (1,-1) OR T.Compromete_Recibos IN (1,-1) )
				 AND C.Id_Estado_Cbte <> K.Id_Estado_Cbte'
	IF @pDebug = 1 PRINT @Sql
	EXEC(@sql)
END

SET @Sql = 'INSERT INTO #Respuesta
