CREATE  PROCEDURE CPJ_Cli_Catcte_Control_Global  @pJsonRecibido VARCHAR(8000)	 

AS
SET NOCOUNT ON 
/* Parametros */
DECLARE 	@pDesde					DATE,
			@pHasta					DATE,
			@pLimit					INT,
			@pDebug					INT,
			@pFormato				CHAR(1),
			@pOrden					CHAR(1),
			@pFlag_Todos			TINYINT,
			@pFlag_Estados			TINYINT,
			@pFlag_Importe			TINYINT,
			@pFlag_Saldo			TINYINT,
			@pFlag_Aplicado			TINYINT,
			@pFlag_Codigo			TINYINT,
			@pFlag_Signo			TINYINT,
			@pFlag_Fechas			TINYINT,
			@pFlag_Contado			TINYINT,
			@pFlag_Grupo			TINYINT,
			@pReparar				CHAR(1)


/* Variables */
DECLARE 	@Sql					VARCHAR(MAX)


SET @pDesde						= ISNULL(CONVERT(DATE, dbo.CF_JSON_VALUE(@pJsonRecibido,'Desde')),'19000101')
SET @pHasta						= ISNULL(CONVERT(DATE, dbo.CF_JSON_VALUE(@pJsonRecibido,'Hasta')),DATEADD(YEAR,50,GETDATE()))
SET @pLimit						= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Limit')),0)
SET @pDebug						= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Debug')),0)
SET @pFormato					= UPPER(ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Formato')),'D')) --D=Detallado C=Resumen Cuentas  E=Estadistico
SET @pOrden						= UPPER(ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Orden')),'T')) --T=Titular,Id_Trans   O=Observacion,Id_Trans
SET @pFlag_Todos				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Todos')),0)
SET @pFlag_Estados				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Estados')),0)
SET @pFlag_Importe				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Importe')),0)
SET @pFlag_Saldo				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Saldo')),0)
SET @pFlag_Aplicado				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Aplicado')),0)
SET @pFlag_Codigo				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Codigo')),0)
SET @pFlag_Signo				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Signo')),0)
SET @pFlag_Fechas				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Fechas')),0)
SET @pFlag_Contado				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Contado')),0)
SET @pFlag_Grupo				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Grupo')),0)
SET @pReparar					= UPPER(ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Reparar')),''))

IF (@pFlag_Estados + @pFlag_Importe + @pFlag_Saldo + @pFlag_Aplicado + @pFlag_Codigo + @pFlag_Signo + @pFlag_Fechas + @pFlag_Contado + @pFlag_Grupo) = 0
   SET @pFlag_Todos = 1

IF @pFlag_Todos	= 1
BEGIN
	SET @pFlag_Estados	 = 1
	SET @pFlag_Importe	 = 1
	SET @pFlag_Saldo	 = 1
	SET @pFlag_Aplicado	 = 1
	SET @pFlag_Codigo	 = 1
	SET @pFlag_Signo	 = 1
	SET @pFlag_Fechas	 = 1
	SET @pFlag_Contado	 = 1
	SET @pFlag_Grupo	 = 1
END


UPDATE Clientes SET Id_Cliente_Ref = 0 WHERE Id_Cliente_Ref IS NULL

------------------------------------------------------------------------
SELECT
		C.Id_Cliente AS Codigo          ,
		I.Id_Cliente AS Codigo_Tit      ,
        I.Razon_Social                  ,
        C.Id_Trans                      ,
        C.Fecha                         ,
		C.Id_Tipo_Cbte					,
        T.Descripcion                   ,
        C.Id_Estado_Cbte AS Estado      ,
        C.Imp_Total						,
		C.Saldo							,
        E.Id_Cliente AS Codigo_CC		,
        E.Id_Estado_Cbte AS Estado_CC   ,
        E.Importe  AS Importe_CC        ,
		E.Saldo    AS Saldo_CC	,
		CONVERT(VARCHAR(1000),C.Observacion) AS Observacion
INTO	#Respuesta
FROM
        Clientes_CtaCte E
		JOIN Cbtes C ON E.Id_Trans = C.Id_Trans
		JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
		JOIN Clientes I ON I.Id_Cliente = E.Id_Cliente
WHERE 1 = 0

CREATE INDEX IX_Resp_Aplic_C ON #Respuesta (Codigo_Tit,Id_Trans)
CREATE INDEX IX_Resp_Aplic_O ON #Respuesta (Observacion)

---------------------------Es titular e integrante---------------------------------------------
INSERT INTO #Respuesta
   SELECT T.Id_Cliente,T.Id_Cliente_Ref,T.Razon_Social
			, 0,NULL,'','',0,0,0,0,0,0,0
			, 'Es titular e integrante'  FROM Clientes I
		JOIN Clientes T ON T.Id_Cliente = I.Id_Cliente_Ref
	WHERE I.Id_Cliente > 0
		AND I.Id_Cliente <> 0
		AND T.Id_Cliente_Ref <> 0


--Diferencias en Clientes
IF @pFlag_Codigo = 1
BEGIN
	IF @pLimit = 0
		SET @Sql = 'INSERT INTO #Respuesta SELECT '
	ELSE
		SET @Sql += 'INSERT INTO #Respuesta SELECT TOP '+ CONVERT(VARCHAR,@pLimit) 

	SET @Sql += '
			C.Id_Cliente AS Codigo          ,
			I.Id_Cliente AS Codigo_Tit      ,
			I.Razon_Social                  ,
			C.Id_Trans                      ,
			C.Fecha                         ,
			C.Id_Tipo_Cbte					,
			T.Descripcion                   ,
			C.Id_Estado_Cbte AS Estado      ,
			C.Imp_Total						,
			C.Saldo							,
			E.Id_Cliente AS Codigo_CC		,
			E.Id_Estado_Cbte AS Estado_CC   ,
			E.Importe  AS Importe_CC        ,
			E.Saldo    AS Saldo_CC	,
			''Diferencias en Codigo Clientes''
	FROM
			Clientes_CtaCte E
			JOIN Cbtes C ON E.Id_Trans = C.Id_Trans
			JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
			JOIN Clientes I ON I.Id_Cliente = C.Id_Cliente
	WHERE
			E.Id_Cliente <> C.Id_Cliente
			AND		C.Id_Estado_Cbte IN (1,2,4)
			AND     (
							E.Importe      != 0
							OR C.Imp_Total != 0)
			AND     C.Id_Cliente NOT IN (1,0)
			AND		(C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
			AND     (T.Compromete_Factura IN (1,-1) OR T.Compromete_Recibos IN (1,-1) )
			AND		C.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
			AND		C.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +''''


	IF @pDebug = 1 PRINT @Sql
	EXEC(@Sql)
END



/* Signo erroneo en ctat.cte. */
IF @pFlag_Signo = 1 
BEGIN
	IF @pLimit = 0
		SET @Sql = 'WITH Importes AS ( SELECT '
	ELSE
		SET @Sql = 'WITH Importes AS ( SELECT TOP '+ CONVERT(VARCHAR,@pLimit) 

	SET @Sql += ' 
									E.Id_Trans,
									SUM(E.Importe) as Importe
							FROM
									Clientes_CtaCte E
							WHERE
									E.Id_Estado_Cbte IN (1,2,4)
									AND		E.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
									AND		E.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +'''
							GROUP BY
									E.Id_Trans 
						)
	INSERT INTO #Respuesta 
	SELECT 
			C.Id_Cliente AS Codigo          ,
			I.Id_Cliente AS Codigo_Tit      ,
			I.Razon_Social                  ,
			C.Id_Trans                      ,
			C.Fecha                         ,
			C.Id_Tipo_Cbte					,
			T.Descripcion                   ,
			C.Id_Estado_Cbte AS Estado      ,
			C.Imp_Total						,
			C.Saldo							,
			0 AS Codigo_CC					,
			0 AS Estado_CC					,
			E.Importe  AS Importe_CC        ,
			0    AS Saldo_CC				,
			''Signo erroneo en ctat.cte.''
	FROM
			Importes E
			JOIN Cbtes C ON E.Id_Trans = C.Id_Trans
			JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
			JOIN Clientes I ON I.Id_Cliente = C.Id_Cliente
	WHERE
			C.Id_Estado_Cbte IN (1,2,4)
			AND	(	
					(E.Importe < 0 AND (T.Compromete_Factura = 1 OR T.Compromete_Recibos = -1) )
					OR 
					(E.Importe > 0 AND (T.Compromete_Factura = -1 OR T.Compromete_Recibos = 1) )
				)
			AND     C.Id_Cliente NOT IN (1,0)
			AND		(C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
			AND		C.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
			AND		C.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +''''

	IF @pDebug = 1 PRINT @Sql
	EXEC(@Sql)
END


--Diferencias en estados
IF @pFlag_Estados = 1
BEGIN
	IF @pLimit = 0
		SET @Sql = 'INSERT INTO #Respuesta SELECT '
	ELSE
		SET @Sql = 'INSERT INTO #Respuesta SELECT TOP '+ CONVERT(VARCHAR,@pLimit) 

	SET @Sql += '
			C.Id_Cliente AS Codigo          ,
			I.Id_Cliente AS Codigo_Tit      ,
			I.Razon_Social                  ,
			C.Id_Trans                      ,
			C.Fecha                         ,
			C.Id_Tipo_Cbte					,
			T.Descripcion                   ,
			C.Id_Estado_Cbte AS Estado      ,
			C.Imp_Total						,
			C.Saldo							,
			E.Id_Cliente AS Codigo_CC		,
			E.Id_Estado_Cbte AS Estado_CC   ,
			E.Importe  AS Importe_CC        ,
			E.Saldo    AS Saldo_CC	,
			''Diferencias en Estados''
	FROM
			Clientes_CtaCte E
			JOIN Cbtes C ON E.Id_Trans = C.Id_Trans
			JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
			JOIN Clientes I ON I.Id_Cliente = C.Id_Cliente
	WHERE
			C.Id_Estado_Cbte IN (1,2,3,4)
			AND ( 
					(C.Id_Estado_Cbte = 2 AND E.Id_Estado_Cbte != 2)
					OR 
					(C.Id_Estado_Cbte = 3 AND E.Id_Estado_Cbte != 3)
					OR 
					(C.Id_Estado_Cbte IN (1,4) AND ABS(C.Imp_Total) = ABS(E.Importe) AND E.Id_Estado_Cbte NOT IN (1,4 ) ) -- solo evaluo cuando es en una cuota
					OR 
					(C.Id_Estado_Cbte IN (1,4) AND ABS(C.Imp_Total) != ABS(E.Importe) AND E.Id_Estado_Cbte NOT IN (1,2,4) ) --son cuotas
				)
			AND     C.Id_Cliente NOT IN (1,0)
			AND		(C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
			AND		(C.Imp_Total != 0 AND E.Importe != 0)
			AND     (T.Compromete_Factura IN (1,-1) OR T.Compromete_Recibos IN (1,-1) )
			AND		C.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
			AND		C.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +''''

	IF @pDebug = 1 PRINT @Sql
	EXEC(@Sql)
END

