/*diferencias en importes */
IF @pFlag_Importe = 1
BEGIN
	IF @pLimit = 0
		SET @Sql = 'WITH Importes AS ( SELECT '
	ELSE
		SET @Sql = 'WITH Importes AS ( SELECT TOP '+ CONVERT(VARCHAR,@pLimit) 

	SET @Sql += ' 
									E.Id_Trans,
									SUM(E.Importe) as Importe
							FROM
									Clientes_CtaCte E
							WHERE
									E.Id_Estado_Cbte IN (1,2,4)
									AND		E.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
									AND		E.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +'''
							GROUP BY
									E.Id_Trans 
						)
	INSERT INTO #Respuesta 
	SELECT
			C.Id_Cliente AS Codigo          ,
			I.Id_Cliente AS Codigo_Tit      ,
			I.Razon_Social                  ,
			C.Id_Trans                      ,
			C.Fecha                         ,
			C.Id_Tipo_Cbte					,
			T.Descripcion                   ,
			C.Id_Estado_Cbte AS Estado      ,
			C.Imp_Total						,
			C.Saldo							,
			0 AS Codigo_CC		,
			0 AS Estado_CC   ,
			S.Importe  AS Importe_CC        ,
			0    AS Saldo_CC	,
			''Importe Total Diferente en CC.''
	FROM
			Cbtes C		
			JOIN Cbtes_Tipos T	ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
			JOIN Clientes I		ON I.Id_Cliente = C.Id_Cliente
			JOIN Importes S		ON S.Id_Trans     = C.Id_Trans
	WHERE
			C.Id_Estado_Cbte IN (1,2,4)
			AND		C.Imp_Total    <> S.Importe
			AND     C.Id_Cliente NOT IN (1,0)
			AND		(C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
			AND		C.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
			AND		C.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +'''
			AND     (
					T.Compromete_Factura    = 1
					OR T.Compromete_Recibos = -1)

	UNION ALL
	SELECT
			C.Id_Cliente AS Codigo          ,
			I.Id_Cliente AS Codigo_Tit      ,
			I.Razon_Social                  ,
			C.Id_Trans                      ,
			C.Fecha                         ,
			C.Id_Tipo_Cbte					,
			T.Descripcion                   ,
			C.Id_Estado_Cbte AS Estado      ,
			C.Imp_Total	* -1				,
			C.Saldo	* -1					,
			0 AS Codigo_CC		,
			0 AS Estado_CC   ,
			S.Importe  AS Importe_CC        ,
			0    AS Saldo_CC	,
			''Importe Total Diferente en CC.''
	FROM
			Cbtes C		
			JOIN Cbtes_Tipos T	ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
			JOIN Clientes I		ON I.Id_Cliente = C.Id_Cliente
			JOIN Importes S		ON S.Id_Trans     = C.Id_Trans
	WHERE
			C.Id_Estado_Cbte IN (1,2,4)
			AND		C.Imp_Total * -1  != S.Importe
			AND     C.Id_Cliente NOT IN (1,0)
			AND		(C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
			AND		C.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
			AND		C.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +'''
			AND     (
					T.Compromete_Factura    = -1
					OR T.Compromete_Recibos = 1)

			'

	IF @pDebug = 1 PRINT @Sql
	EXEC(@Sql)
END

