--Aplicaciones fuera del grupo familiar
IF @pFlag_Grupo = 1 AND ISNULL(CONVERT(INT,dbo.CF_xParam('Cli_Ref_CtaCte_Agrup')),0) = 1
BEGIN
	IF @pLimit = 0
		SET @Sql = 'INSERT INTO #Respuesta SELECT '
	ELSE
		SET @Sql = 'INSERT INTO #Respuesta SELECT TOP '+ CONVERT(VARCHAR,@pLimit) 

	SET @Sql += '
			C.Id_Cliente AS Codigo          ,
			I.Id_Cliente AS Codigo_Tit      ,
			I.Razon_Social                  ,
			C.Id_Trans                      ,
			C.Fecha                         ,
			C.Id_Tipo_Cbte					,
			T.Descripcion                   ,
			C.Id_Estado_Cbte AS Estado      ,
			C.Imp_Total						,
			C.Saldo							,
			0 AS Codigo_CC		,
			0 AS Estado_CC   ,
			0 AS Importe_CC        ,
			0 AS Saldo_CC	,
			''Aplicaciones fuera de grupo''
	FROM	Cbtes_Aplica A
			JOIN Cbtes C ON C.Id_Trans = A.Id_Trans						AND C.Id_Estado_Cbte IN (1,2,4) 
																		AND C.Id_Cliente NOT IN (1,0)
																		AND	(C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
			JOIN Clientes I ON I.Id_Cliente = C.Id_Cliente			
			JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte		AND (T.Compromete_Factura IN (1,-1) OR T.Compromete_Recibos IN (1,-1) )

			JOIN Cbtes C2 ON C2.Id_Trans = A.Id_Trans_D					AND  C2.Id_Estado_Cbte IN (1,2,4)
			JOIN Cbtes_Tipos T2 ON T2.Id_Tipo_Cbte = C2.Id_Tipo_Cbte	AND (T2.Compromete_Factura IN (1,-1) OR T2.Compromete_Recibos IN (1,-1) )
			JOIN Clientes I2 ON I2.Id_Cliente = C2.Id_Cliente
	WHERE
					A.Id_Trans_D != 0
			AND		A.Id_Trans != 0
			AND 	CASE I.Id_Cliente_Ref WHEN 0 THEN I.Id_Cliente ELSE I.Id_Cliente_Ref END 
					!= 
					CASE I2.Id_Cliente_Ref WHEN 0 THEN I2.Id_Cliente ELSE I2.Id_Cliente_Ref END 
			AND		C.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
			AND		C.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +''''


	IF @pDebug = 1 PRINT @Sql
	EXEC(@Sql)
END


/* Total Aplicado Fac y NC */
IF @pFlag_Aplicado = 1
BEGIN
	IF @pLimit = 0
		SET @Sql = 'WITH Aplicado AS ( SELECT '
	ELSE
		SET @Sql = 'WITH Aplicado AS ( SELECT TOP '+ CONVERT(VARCHAR,@pLimit) 

	SET @Sql += ' 
									A.Id_Trans,
									SUM(A.Importe) as Importe_Aplicado
							FROM
									Cbtes_Aplica A
									JOIN Cbtes C ON C.Id_Trans = A.Id_Trans
									JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
									JOIN Cbtes C2 ON C2.Id_Trans = A.Id_Trans_D
									JOIN Cbtes_Tipos T2 ON T2.Id_Tipo_Cbte = C2.Id_Tipo_Cbte
							WHERE
									A.Id_Trans != 0 
									AND		A.Id_Trans_D != 0
									AND		C.Id_Estado_Cbte IN (1,2,4)
									AND		C2.Id_Estado_Cbte IN (1,2,4)
									AND     T.Compromete_Factura IN (1,-1) 
									AND     (T2.Compromete_Factura = -1 OR T2.Compromete_Recibos = 1 )
									AND		C.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
									AND		C.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +'''
							GROUP BY
									A.Id_Trans 
						)
	INSERT INTO #Respuesta 
	SELECT
			C.Id_Cliente AS Codigo          ,
			I.Id_Cliente AS Codigo_Tit      ,
			I.Razon_Social                  ,
			C.Id_Trans                      ,
			C.Fecha                         ,
			C.Id_Tipo_Cbte					,
			T.Descripcion                   ,
			C.Id_Estado_Cbte AS Estado      ,
			C.Imp_Total						,
			C.Saldo							,
			0 AS Codigo_CC		,
			0 AS Estado_CC   ,
			A.Importe_Aplicado AS Importe_CC        ,
			0 AS Saldo_CC	,
			''Total aplicado de FC o NC difiere del saldo.''
	FROM
			Cbtes C		
			JOIN Aplicado A		ON A.Id_Trans = C.Id_Trans
			JOIN Cbtes_Tipos T	ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
			JOIN Clientes I		ON I.Id_Cliente	= C.Id_Cliente
	WHERE
			C.Imp_ToTal - A.Importe_Aplicado    != C.Saldo
			AND     C.Id_Cliente NOT IN (1,0)
			AND     (T.Compromete_Factura = 1 OR T.Compromete_Recibos = -1 )
			AND		(C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
			AND		C.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
			AND		C.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +'''
			'

	IF @pDebug = 1 PRINT @Sql
	EXEC(@Sql)
END

/* Total Aplicado de Recibos */
IF @pFlag_Aplicado = 1
BEGIN
	IF @pLimit = 0
		SET @Sql = 'WITH Aplicado AS ( SELECT '
	ELSE
		SET @Sql = 'WITH Aplicado AS ( SELECT TOP '+ CONVERT(VARCHAR,@pLimit) 

	SET @Sql += ' 
									A.Id_Trans_D AS Id_Trans,
									SUM(A.Importe) as Importe_Aplicado
							FROM
									Cbtes_Aplica A
									JOIN Cbtes C ON C.Id_Trans = A.Id_Trans_D
									JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
									JOIN Cbtes C2 ON C2.Id_Trans = A.Id_Trans
									JOIN Cbtes_Tipos T2 ON T2.Id_Tipo_Cbte = C2.Id_Tipo_Cbte
							WHERE
									C.Id_Estado_Cbte IN (1,2,4)
									AND     (T.Compromete_Factura = -1 OR T.Compromete_Recibos = 1) 
									AND		C2.Id_Estado_Cbte IN (1,2,4)
									AND     ( 
													((T2.Compromete_Factura IN (1,-1) OR T2.Compromete_Recibos IN (1,-1)) AND A.Id_Trans != 0)
													OR
													A.Id_Trans = 0
											)
									AND		C.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
									AND		C.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +'''
							GROUP BY
									A.Id_Trans_D 
						)
	INSERT INTO #Respuesta 
	SELECT
			C.Id_Cliente AS Codigo          ,
			I.Id_Cliente AS Codigo_Tit      ,
			I.Razon_Social                  ,
			C.Id_Trans                      ,
			C.Fecha                         ,
			C.Id_Tipo_Cbte					,
			T.Descripcion                   ,
			C.Id_Estado_Cbte AS Estado      ,
			C.Imp_Total						,
			C.Saldo							,
			0 AS Codigo_CC		,
			0 AS Estado_CC   ,
			A.Importe_Aplicado AS Importe_CC        ,
			0 AS Saldo_CC	,
			''Total aplicado de RC difiere del saldo.''
	FROM
			Cbtes C		
			JOIN Aplicado A		ON A.Id_Trans = C.Id_Trans
			JOIN Cbtes_Tipos T	ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
			JOIN Clientes I		ON I.Id_Cliente	= C.Id_Cliente
	WHERE
			C.Imp_ToTal - A.Importe_Aplicado    != C.Saldo
			AND     C.Id_Cliente NOT IN (1,0)
			AND     (T.Compromete_Factura = -1 OR T.Compromete_Recibos = 1 )
			AND		(C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
			AND		C.Fecha >= '''+ CONVERT(VARCHAR,@pDesde,112) +'''
			AND		C.Fecha < '''+ CONVERT(VARCHAR, DATEADD(DAY,1,@pHasta),112) +'''
			'

	IF @pDebug = 1 PRINT @Sql
	EXEC(@Sql)
END




------------------------------------------------------------------------------------------------
UPDATE #Respuesta SET Codigo_Tit = Codigo WHERE Codigo_Tit = 0

IF @pReparar != 'S'
BEGIN 
	--D=Detallado C=Resumen Cuentas  E=Estadistico
	IF UPPER(@pFormato) = 'C'
		SELECT Id_Cliente,Razon_Social,Id_Cliente_Externo FROM Clientes WHERE Id_Cliente IN (SELECT DISTINCT(Codigo_Tit) FROM #Respuesta)
		ORDER BY Razon_Social
	ELSE IF UPPER(@pFormato) = 'B'
		SELECT C.Id_Trans,C.Id_Tipo_Cbte,T.Descripcion,C.Fecha, C.Id_Cliente,E.Razon_Social,C.Id_Estado_Cbte,C.Imp_Total
				FROM Cbtes C 
					JOIN Clientes E ON E.Id_Cliente = C.Id_Cliente
					JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
				WHERE EXISTS (SELECT 1 FROM #Respuesta R WHERE R.Id_Trans = C.Id_Trans)
				ORDER BY Id_Trans
	ELSE IF UPPER(@pFormato) = 'E'
		BEGIN
		DECLARE @Cant_Cbtes DECIMAL(18,5)
				,@Cant_Clientes DECIMAL(18,5)
				,@Cant_Cbtes_Err DECIMAL(18,5)
				,@Cant_Clientes_Err DECIMAL(18,5)
				,@Porc_Cbtes_Err DECIMAL(6,2)
				,@Porc_Clientes_Err DECIMAL(6,2)

		SELECT @Cant_Cbtes			= COUNT(*) FROM Cbtes C JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte WHERE T.Compromete_Factura IN (1,-1) OR T.Compromete_Recibos IN (1,-1)
		SELECT @Cant_Clientes		= COUNT(*) FROM Clientes
		SELECT @Cant_Cbtes_Err		= COUNT(DISTINCT Id_Trans) FROM #Respuesta;
		SELECT @Cant_Clientes_Err	= COUNT(DISTINCT Codigo_Tit) FROM #Respuesta;

		SET @Porc_Cbtes_Err		= 100 * @Cant_Cbtes_Err / @Cant_Cbtes 
		SET @Porc_Clientes_Err	= 100 * @Cant_Clientes_Err / @Cant_Clientes

		SELECT 	@Cant_Clientes_Err AS 'Cuentas Afectadas'
				,@Cant_Clientes AS 'Total Cuentas'
				,@Porc_Clientes_Err AS '% Cuentas Afectadas'
				,@Cant_Cbtes_Err AS 'Cbtes Afectados'
				,@Cant_Cbtes AS 'Total Cbtes'
				,@Porc_Cbtes_Err AS '% Cbtes Afectadas'
		END
	ELSE
	BEGIN
		IF UPPER(@pOrden) = 'O'
			SELECT * FROM #Respuesta ORDER BY Observacion
		ELSE
			SELECT * FROM #Respuesta ORDER BY Codigo_Tit,Id_Trans
	END
	DROP TABLE #Respuesta

END
ELSE
BEGIN
   DECLARE Rep_Cur CURSOR FOR SELECT DISTINCT(Codigo_Tit) FROM #Respuesta
   DECLARE @Id_Cliente INT 

   OPEN Rep_Cur
   FETCH NEXT FROM Rep_Cur INTO @Id_Cliente
   WHILE (@@FETCH_STATUS = 0)
   BEGIN
		SET @Sql = 'EXEC CPJ_Cli_Catcte_Control ''{"id_Cliente":"' + CONVERT(VARCHAR,@Id_Cliente) + '","Reparar":"S","OmitirResult":"S"}'''
		PRINT @Sql
		EXEC(@Sql)
		FETCH NEXT FROM Rep_Cur INTO @Id_Cliente
   END
   CLOSE Rep_Cur
   DEALLOCATE Rep_Cur
   DROP TABLE #Respuesta

   SET @Sql = 'EXEC CPJ_Cli_Catcte_Control_Global  ''{"Reparar":"N"'
   SET @Sql += '"Desde":"'+ CONVERT(VARCHAR,@pDesde					) + '"'
   SET @Sql += '"Hasta":"'+ CONVERT(VARCHAR,@pHasta					) + '"'
   SET @Sql += '"Limit":"'+ CONVERT(VARCHAR,@pLimit					) + '"'
   SET @Sql += '"Debug":"'+ CONVERT(VARCHAR,@pDebug					) + '"'
   SET @Sql += '"Formato":"'+ CONVERT(VARCHAR,@pFormato				) + '"'
   SET @Sql += '"Orden":"'+ CONVERT(VARCHAR,@pOrden					) + '"'
   SET @Sql += '"Flag_Todos":"'+ CONVERT(VARCHAR,@pFlag_Todos		) + '"'
   SET @Sql += '"Flag_Estados":"'+ CONVERT(VARCHAR,@pFlag_Estados	) + '"'
   SET @Sql += '"Flag_Importe":"'+ CONVERT(VARCHAR,@pFlag_Importe	) + '"'
   SET @Sql += '"Flag_Saldo":"'+ CONVERT(VARCHAR,@pFlag_Saldo		) + '"'
   SET @Sql += '"Flag_Aplicado":"'+ CONVERT(VARCHAR,@pFlag_Aplicado	) + '"'
   SET @Sql += '"Flag_Codigo":"'+ CONVERT(VARCHAR,@pFlag_Codigo		) + '"'
   SET @Sql += '"Flag_Signo":"'+ CONVERT(VARCHAR,@pFlag_Signo		) + '"'
   SET @Sql += '"Flag_Fechas":"'+ CONVERT(VARCHAR,@pFlag_Fechas		) + '"'
   SET @Sql += '"Flag_Contado":"'+ CONVERT(VARCHAR,@pFlag_Contado	) + '"'
   SET @Sql += '"Flag_Grupo":"'+ CONVERT(VARCHAR,@pFlag_Grupo		) + '"'
   SET @Sql += '}'''
   PRINT @Sql
   EXEC(@Sql)
END

