CREATE PROCEDURE CPJ_Cli_Prod_Vend_Hist	@pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON

/*Parametros*/
DECLARE @pId_Cliente			INT
		,@pId_Unid_Negocio		CHAR(10)
		,@pModoDebug			TINYINT


/*Fin de Parametros*/

	
/*Seteo Parametros*/
SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')),0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)

CREATE TABLE #Unid_Negocios  (Id_Unid_Negocio CHAR(10))
DECLARE @Sql VARCHAR(5000)
		,@Id_Unid_Negocio_Inc VARCHAR(500)


IF LTRIM(RTRIM(@pId_Unid_Negocio)) = ''
	INSERT INTO #Unid_Negocios SELECT Id_Unid_Negocio FROM Empresas_Unid_Negocios
ELSE
BEGIN	
	
	SET @Sql = 'INSERT INTO #Unid_Negocios SELECT DISTINCT Id_Unid_Negocio FROM Empresas_Unid_Negocios WHERE Id_Unid_Negocio = '''+ @pId_Unid_Negocio +''''

	SELECT @Id_Unid_Negocio_Inc = Id_Unid_Negocio_Inc FROM Empresas_Unid_Negocios WHERE Id_Unid_Negocio = @pId_Unid_Negocio
	IF RTRIM(LTRIM(ISNULL(@Id_Unid_Negocio_Inc,''))) != ''
		SET @Sql += ' OR Id_Unid_Negocio IN(' + @Id_Unid_Negocio_Inc +')'
	IF @pModoDebug = 1 PRINT @Sql
	EXEC(@Sql)
END


SELECT DISTINCT
    z.Id_Producto,
    z.Descripcion_Detallada
FROM
(
    /* 1) Productos por comprobantes del cliente */
    SELECT
        i.Id_Producto,
        p.Descripcion_Detallada
    FROM Cbtes_Items i
    JOIN Cbtes c
        ON c.Id_Trans = i.Id_Trans
    JOIN Cbtes_Tipos t
        ON t.Id_Tipo_Cbte = c.Id_Tipo_Cbte
    JOIN Productos p
        ON p.Id_Producto = i.Id_Producto
	JOIN #Unid_Negocios U
		ON T.Id_Unid_Negocio COLLATE DATABASE_DEFAULT  = U.Id_Unid_Negocio COLLATE DATABASE_DEFAULT 
    WHERE
        p.Activo = 1
        AND p.Vendible = 1
        AND (t.Compromete_Factura IN (1, -1) OR t.Compromete_Remitos IN (1, -1))
        AND c.Id_Estado_Cbte IN (1, 2, 4)
        AND i.Id_Cliente = @pId_Cliente
    UNION ALL

    /* 2) Productos por comprobantes de clientes referidos al cliente */
    SELECT
        i.Id_Producto,
        p.Descripcion_Detallada
    FROM Cbtes_Items i
    JOIN Cbtes c
        ON c.Id_Trans = i.Id_Trans
    JOIN Cbtes_Tipos t
        ON t.Id_Tipo_Cbte = c.Id_Tipo_Cbte
    JOIN Productos p
        ON p.Id_Producto = i.Id_Producto
    JOIN Clientes cl
        ON cl.Id_Cliente = i.Id_Cliente
	JOIN #Unid_Negocios U
		ON T.Id_Unid_Negocio COLLATE DATABASE_DEFAULT  = U.Id_Unid_Negocio COLLATE DATABASE_DEFAULT 
    WHERE
        p.Activo = 1
        AND p.Vendible = 1
        AND (t.Compromete_Factura IN (1, -1) OR t.Compromete_Remitos IN (1, -1))
        AND c.Id_Estado_Cbte IN (1, 2, 4)
        AND cl.Id_Cliente_Ref = @pId_Cliente
        AND cl.Activo = 1

    UNION ALL

    /* 3) Productos por contratos vigentes del cliente */
    SELECT
        cp.Id_Producto,
        p.Descripcion_Detallada
    FROM Contratos c
    JOIN Contratos_Prod cp
        ON cp.Id_Contrato = c.Id_Contrato
    JOIN Productos p
        ON p.Id_Producto = cp.Id_Producto
    WHERE
        c.Activo = 1
        AND p.Activo = 1
        AND p.Vendible = 1
        AND c.Id_Cliente = @pId_Cliente
        AND c.Fecha_Desde < GETDATE()
        AND (c.Fecha_Hasta IS NULL OR c.Fecha_Hasta > GETDATE())
) z
ORDER BY 2;


/*

EXEC CPJ_Cli_Prod_Vend_Hist '{"id_cliente":"309681","Id_Unid_Negocio":"CLU"}'

*/
GO


CREATE PROCEDURE dbo.CPJ_Cliente_Deuda_Notif @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*Variables recibidas por parámetro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Cliente			INT


SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
/*FIN Variables recibidas por parámetro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
DECLARE @Result_Stored_Invocado				INT
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Producto			VARCHAR(14)
DECLARE @Descripcion			VARCHAR(150)
DECLARE @Importe				DECIMAL(16,2)
DECLARE @Periodo				DATETIME
DECLARE @Porcentaje				DECIMAL(12,5)
DECLARE @Porc_Bonif				DECIMAL(12,5)
DECLARE @Coef_Imp_Pagado		DECIMAL(15,5)
DECLARE @Fecha_Factura			DATETIME
DECLARE @Id_Cond_Pago_Cbte		SMALLINT
DECLARE @Id_Cond_Pago_Cbte_Item	SMALLINT
DECLARE @Item					SMALLINT
DECLARE @Plazo					INT
DECLARE @Porc_Bonif_Rec			DECIMAL(12,5)
DECLARE @Fecha_Rec				DATETIME
DECLARE @Dif_Dias				INT
DECLARE @Flag_Encontro			TINYINT
DECLARE @Plazo_Desde			INT
DECLARE @Porc_Bonif_Cbtes_Cond_Pago_Item DECIMAL(12,5)
DECLARE @Plazo_Bonif			BIGINT
DECLARE @Id_Cond_Pago_Item		INT
DECLARE @Tipo					CHAR(1)
DECLARE @Plazo_Sin_Recargo		INT
DECLARE @Imp_Final				DECIMAL(15,5)
DECLARE @Flag_Mes				TINYINT

DECLARE @Id_trans_Deuda  		INT
DECLARE @Fecha_Referencia   	DATETIME
DECLARE @Imp_Deuda    			DECIMAL(16,2)
DECLARE @Tipo_Contacto      	SMALLINT
DECLARE @Id_Contacto            INT
DECLARE	@Motivo                 SMALLINT
DECLARE	@SubMotivo              SMALLINT
DECLARE	@Objeto                 SMALLINT

/*Fin de Declaraciones Variables Locales */


BEGIN TRY

    
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cliente_Deuda_Notif'
		PRINT 'Parámetros:'
		PRINT 'Cliente: ' + CONVERT(VARCHAR(10), @pId_Cliente)  
	END
	
	/*===================================================================*/

	IF(@pId_Cliente = 0)
	BEGIN
		SET @rtaErrorStored = 70001 /*Transaccion no abierta*/
		
		SELECT	 @rtaErrorStored	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,''					AS ErrorMessage
			
		IF @pFlagUsarTrans <> 0 
		BEGIN
			ROLLBACK
		END
		
		RETURN 9999
	END
	
	/*===================================================================*/	
	SET @Plazo_Desde =  (SELECT ISNULL(Valor_Integer,0) FROM xParametros where SETDatos= 1 AND idParametro ='AviMora_Dias_Mora')
	
	SET @Fecha_Referencia =  (SELECT GETDATE() - @Plazo_Desde)

    SET @Imp_Deuda = (SELECT ISNULL(SUM(CC.SALDO),0) FROM CLIENTES_CTACTE CC, CBTES C, CLIENTES K  WHERE C.ID_TRANS = CC.ID_TRANS AND C.ID_ESTADO_CBTE <> 3 AND CC.SALDO <> 0
	                  AND CC.Fecha_Vence <= @Fecha_Referencia AND C.ID_CLIENTE = K.ID_CLIENTE AND (K.ID_CLIENTE =  @pId_Cliente OR K.Id_Cliente_Ref = @pId_Cliente))

    SET @Id_trans_Deuda = (SELECT TOP 1 CC.ID_TRANS FROM CLIENTES_CTACTE CC, CBTES C, CLIENTES K  WHERE C.ID_TRANS = CC.ID_TRANS AND C.ID_ESTADO_CBTE <> 3 AND CC.SALDO > 0 
	                       AND CC.Fecha_Vence <= @Fecha_Referencia AND C.ID_CLIENTE = K.ID_CLIENTE AND (K.ID_CLIENTE =  @pId_Cliente OR K.Id_Cliente_Ref = @pId_Cliente))

	/*===================================================================*/	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Fecha_Referencia ' + CONVERT(VARCHAR(12), @Fecha_Referencia)
		PRINT '@Imp_Deuda ' + CONVERT(VARCHAR(10), @Imp_Deuda)  
	END
	IF @Imp_Deuda <> 0 
	   BEGIN 
	     set @Descripcion = 'Deuda registrada de $'+ CONVERT(VARCHAR(10),@Imp_Deuda)

		 IF(@pModoDebug = 1)
			BEGIN
				PRINT '@Descripcion ' + @Descripcion
			END

	     INSERT INTO Cbtes_Procesos (Id_Trans,Fecha,Tipo,Estado,Fecha_Proc,Id_Usuario,Nota,Observaciones)
		 Values (@Id_trans_Deuda,getdate(),'M','P',null,0,'AVISO_MORA',@Descripcion)

		 
         SET @Tipo_Contacto  = (SELECT ISNULL(Valor_Integer,0) FROM xParametros where SETDatos= 1 AND idParametro ='AviMora_CRM_T_Cont')  
		 SET @Motivo  = (SELECT ISNULL(Valor_Integer,0) FROM xParametros where SETDatos= 1 AND idParametro ='AviMora_CRM_Motivo')  
		 SET @SubMotivo  = (SELECT ISNULL(Valor_Integer,0) FROM xParametros where SETDatos= 1 AND idParametro ='AviMora_CRM_SubMoti')  
		 SET @Objeto  = (SELECT ISNULL(Valor_Integer,0) FROM xParametros where SETDatos= 1 AND idParametro ='AviMora_CRM_Objeto') 

		 IF @Tipo_Contacto <> 0
		    BEGIN 

			SET @Id_Contacto = (SELECT MAX(ID_CONTACTO)+1 FROM CRM_Contactos)

			INSERT INTO CRM_Contactos
				    (Id_Contacto,
					Fecha,
					Id_Tipo_Contacto,
					Id_Motivo_Contacto,
					Modo,
					Id_Cliente,
					Id_Proveedor,
					Descripcion,
					Flag_Aviso_Auto,
					Id_Estado,
					Resolucion,
					Fecha_Reso,
					Fecha_Aviso,
					Id_SubMotivo_Contacto,
					Id_Objeto_Contacto,
					Id_Trans,
					Id_Vendedor,
					Id_Usuario,
					Id_Camp)
				VALUES
				    (@Id_Contacto,
					GETDATE(),
					@Tipo_Contacto,
					@Motivo,
					'S',
					@pId_Cliente,
					0,
                    @Descripcion,
					0,
					1,
					'',
					Getdate(),
					Getdate(),
					@SubMotivo,
					@Objeto,
					@Id_trans_Deuda,
					'',
					0,
					0)	

     --- agrego la deuda en [dbo].[CRM_Contactos_Cbtes]
		   IF(@pModoDebug = 1)
		        BEGIN
			    PRINT 'Agrego CRM_Contactos_Cbtes'
				END
	       DECLARE CUR_GENERAR CURSOR FOR

	       SELECT DISTINCT(CC.ID_TRANS),CC.DESCRIPCION FROM CLIENTES_CTACTE CC, CBTES C, CLIENTES K  WHERE C.ID_TRANS = CC.ID_TRANS AND C.ID_ESTADO_CBTE <> 3 AND CC.SALDO > 0
	                  AND CC.Fecha_Vence <= @Fecha_Referencia AND C.ID_CLIENTE = K.ID_CLIENTE AND (K.ID_CLIENTE =  @pId_Cliente OR K.Id_Cliente_Ref = @pId_Cliente) 

	       OPEN CUR_GENERAR
	       FETCH NEXT FROM CUR_GENERAR INTO  @Id_trans_Deuda,@Descripcion
	       WHILE @@FETCH_STATUS = 0
	         BEGIN
			     IF(@pModoDebug = 1)
			          BEGIN

			    	  PRINT 'Id_Trans:' + CONVERT(VARCHAR(10), @Id_trans_Deuda)   + '  Descripcion ' + @Descripcion
		         END
			     INSERT INTO CRM_Contactos_Cbtes (Id_Contacto,Id_Trans,Descripcion)  
				        VALUES (@Id_Contacto,@Id_trans_Deuda,@Descripcion)

 		    	 FETCH NEXT FROM CUR_GENERAR INTO   @Id_trans_Deuda,@Descripcion

	         END -- si genere crm_contactos_cbtes
	       CLOSE CUR_GENERAR
	       DEALLOCATE CUR_GENERAR 
		
		   IF(@pModoDebug = 1)
		    	BEGIN
				PRINT 'fin generacion cbtes_procesos ' 
				END
		 END  -- si genro crm
       END --si tiene deuda envio mail
	/*===================================================================*/	

	

	/*===================================================================*/	
	
	IF @pFlagUsarTrans <> 0 
 	BEGIN
		COMMIT
	END

	/*===================================================================*/	

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cliente_Deuda_Notif'
	END

END TRY  

BEGIN CATCH  
	EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0

--------------------------------------------------------------------------- PARA PROBAR

-- EXEC CPJ_Cliente_Deuda_Notif '{"id_cliente":"39518","ModoDebug":"1","FlagUsarTrans":"0"}'
--  select * from cbtes_Procesos where id_proceso > 24929
--  select * from crm_contactos where id_contacto  > 733
GO


CREATE PROCEDURE CPJ_Cliente_Login @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*Variables recibidas por parámetro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pEmail					VARCHAR(1000)
DECLARE @pClave					VARCHAR(1000)
		,@pIp			VARCHAR(50)
		,@pSession_Id	VARCHAR(32)
		,@pOrigen		VARCHAR(3)
		,@pVersion		VARCHAR(32)

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pEmail						= ISNULL(CONVERT(VARCHAR(1000), dbo.CF_JSON_VALUE(@pJson,'Email')),'')
SET @pClave						= ISNULL(CONVERT(VARCHAR(1000), dbo.CF_JSON_VALUE(@pJson,'Clave')), '')
SET @pIp						= ISNULL(CONVERT(VARCHAR(50), dbo.CF_JSON_VALUE(@pJson,'Ip')),'')
SET @pSession_Id				= ISNULL(CONVERT(VARCHAR(32), dbo.CF_JSON_VALUE(@pJson,'Session_Id')), '')
SET @pOrigen					= ISNULL(CONVERT(VARCHAR(3), dbo.CF_JSON_VALUE(@pJson,'Origen')), '')
SET @pVersion					= ISNULL(CONVERT(VARCHAR(32), dbo.CF_JSON_VALUE(@pJson,'Version')), '')

/*FIN Variables recibidas por parámetro a traves del JSON*/

DECLARE @Cant		INT	
		,@Id_Cliente	INT


IF @pModoDebug = 1
BEGIN
	PRINT @pEmail	
	PRINT @pClave
END


IF UPPER(SUBSTRING(@pEmail,1,3)) = 'ID:' AND @pClave = LTRIM(RTRIM(dbo.CF_xParam('Kiosk_Backdoor')))
BEGIN
	IF @pModoDebug = 1
	BEGIN
		PRINT 'Ingresa por ID'	
	END
	IF ISNUMERIC( SUBSTRING(@pEmail,4, LEN(@pEmail) - 3 ) ) = 1
	BEGIN 
		SELECT		C.Id_Cliente, C.Id_Cliente_Ref, C.Apellido, C.Nombre, C.Razon_Social, C.Email_Web, C.Ult_Cuota_Paga, C.Id_Cliente_Externo, C.Id_Tipo_Cli
					,T.Descripcion AS 'Descripcion_Tipo_Cli',C.Fecha_Web_Ult_Ingreso
			INTO	#Resp
			FROM	Clientes C LEFT OUTER JOIN Clientes_Tipos T ON T.Id_Tipo_Cli = C.Id_Tipo_Cli
			WHERE	C.id_Cliente = CAST( SUBSTRING(@pEmail,4, LEN(@pEmail) - 3 ) AS INT)
					AND C.Activo=1
	    SELECT @Id_Cliente = Id_Cliente FROM #Resp
		SELECT * FROM #Resp
		DROP TABLE #Resp
        IF OBJECT_ID('Clientes_Logins') IS NOT NULL
		BEGIN
			INSERT INTO Clientes_Logins (Fecha_Login,Id_Cliente,[Ip],Session_Id,Origen,[Version])
					VALUES (GETDATE(),@Id_Cliente,@pIp,@pSession_Id,@pOrigen,@pVersion)
		END
		UPDATE Clientes SET Fecha_Web_Ult_Ingreso = GETDATE() WHERE Id_Cliente = @Id_Cliente
	END
END
ELSE
BEGIN
	IF @pModoDebug = 1
	BEGIN
		PRINT 'Ingresa por email'	
	END	
	IF  LEN(RTRIM(LTRIM(@pEmail))) <> 0
	BEGIN 

		SET @Cant = (	SELECT	COUNT(*)
							FROM	Clientes C WITH (NOLOCK)
									LEFT OUTER JOIN Clientes_Tipos T  WITH (NOLOCK) ON T.Id_Tipo_Cli = C.Id_Tipo_Cli
							WHERE	C.Email_Web = LTRIM(RTRIM(@pEmail))
								AND C.Clave_Web = LTRIM(RTRIM(@pClave))
								AND C.Activo=1)
		IF @pModoDebug = 1
		BEGIN
			PRINT 'Se repite el user y clave, cantidad:'+ CAST(@Cant AS VARCHAR(10))	
		END	
		IF 	@Cant = 1
		BEGIN					
			SELECT		C.Id_Cliente, C.Id_Cliente_Ref, C.Apellido, C.Nombre, C.Razon_Social, C.Email_Web
						, C.Ult_Cuota_Paga, C.Id_Cliente_Externo, C.Id_Tipo_Cli, T.Descripcion AS 'Descripcion_Tipo_Cli',C.Fecha_Web_Ult_Ingreso
				INTO #Resp2
				FROM	Clientes C LEFT OUTER JOIN Clientes_Tipos T ON T.Id_Tipo_Cli = C.Id_Tipo_Cli
				WHERE	C.Email_Web = LTRIM(RTRIM(@pEmail))
					AND C.Clave_Web = LTRIM(RTRIM(@pClave))
					AND C.Activo=1

			SELECT @Id_Cliente = Id_Cliente FROM #Resp2
			SELECT * FROM #Resp2
			DROP TABLE #Resp2
			IF OBJECT_ID('Clientes_Logins') IS NOT NULL
			BEGIN
				INSERT INTO Clientes_Logins (Fecha_Login,Id_Cliente,[Ip],Session_Id,Origen,[Version])
						VALUES (GETDATE(),@Id_Cliente,@pIp,@pSession_Id,@pOrigen,@pVersion)
			END
			UPDATE Clientes SET Fecha_Web_Ult_Ingreso = GETDATE() WHERE Id_Cliente = @Id_Cliente
		END			

	END
END
GO



CREATE  PROCEDURE [dbo].[CPJ_Clientes_CtaCte] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON

/*Declaracion Variables Locales*/

DECLARE @pFecha_Desde DATETIME
		,@pFecha_Hasta DATETIME
		,@pId_Cliente INT
		


SET @pFecha_Desde					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde')), '19000101')
SET @pFecha_Hasta					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta')), GETDATE())
SET @pId_Cliente					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)



DECLARE @Cli_Ref_CtaCte_Agrup	INT
					


SET @Cli_Ref_CtaCte_Agrup = CAST(dbo.CF_xParam('Cli_Ref_CtaCte_Agrup') AS INT)


IF ISNULL(@Cli_Ref_CtaCte_Agrup,0) = 0
BEGIN
	 SELECT cc.fecha_vence,cc.fecha,cc.descripcion,cc.nro_cuota,cc.id_moneda,cc.importe,cc.saldo,c.id_cliente,c.destinatario,c.id_trans, 
	 cc.Id_Moneda, ISNULL(c.Cotizacion, 1) as Cotizacion, t.Id_Unid_Negocio, t.Letra, c.Id_Contrato, cc.Observacion 
		FROM clientes_ctacte CC, cbtes c, cbtes_tipos T, clientes K
		WHERE c.id_trans = cc.id_trans and c.id_tipo_cbte = t.id_tipo_cbte
		and c.id_cliente = k.id_cliente 
		and c.id_cliente = @pid_Cliente 
		and c.id_estado_cbte NOT IN (0,3)
		and cc.saldo <> 0 ORDER BY cc.Fecha_Vence
END 
ELSE 
BEGIN 
	 SELECT cc.fecha_vence,cc.fecha,cc.descripcion,cc.nro_cuota,cc.id_moneda,cc.importe,cc.saldo,c.id_cliente,c.destinatario,c.id_trans, 
	 cc.Id_Moneda, ISNULL(c.Cotizacion, 1) as Cotizacion, t.Id_Unid_Negocio, t.Letra, c.Id_Contrato, cc.Observacion 
		FROM clientes_ctacte CC, cbtes c, cbtes_tipos T, clientes K
		WHERE c.id_trans = cc.id_trans and c.id_tipo_cbte = t.id_tipo_cbte
		and c.id_cliente = k.id_cliente 
		and ((k.id_cliente = @pid_Cliente and isnull(k.id_cliente_ref ,0) = 0) 
			OR (isnull(k.id_cliente ,0) != 0  AND k.Id_cliente_ref = @pid_Cliente))
		and c.id_estado_cbte NOT IN (0,3)
		and cc.saldo <> 0 ORDER BY cc.Fecha_Vence
END
 


 /*
 EXEC CPJ_Clientes_CtaCte '{"Id_Cliente":"989005","Fecha_Desde":"","Fecha_Hasta":""}'
 SELECT * FROM Cbtes WHERE Id_Trans = 1264751
 SELECT dbo.CF_xParam('Cant_D_Val_Pres_Tar')
 */
GO

CREATE PROCEDURE [dbo].[CPJ_Clientes_Deuda] @pJsonRecibido VARCHAR(8000)
AS
SET NOCOUNT ON

/*Parametros*/

DECLARE 	@pFechaHasta			DATETIME,
			@pId_Unid_Negocio       VARCHAR(10),
			@pFiltrar_con_saldo     TINYINT,
			@pClientes_activos      TINYINT,
			@pFiltroFecha           TINYINT,
			@pCriterio              VARCHAR(2),
			@pId_Cliente            INT,
			@pInc_UCP_a_Fecha		TINYINT,
			@pLimite				INT,
            @pModoDebug				TINYINT,
			@pTipoDeuda			    CHAR(1),
			@pCotizacion            Decimal(20,4),
			@pId_Moneda             CHAR(3),
			@pOrden  			    CHAR(2)   --"RZ"=>"Razon Social","ID"=>"importe desc"
			 
SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())
SET @pFiltrar_con_saldo			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Filtrar_con_saldo')),0)
SET @pClientes_activos			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Clientes_activos')),0)
SET @pFiltroFecha		    	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FiltroFecha')),0)
SET @pCriterio			        = ISNULL(CONVERT(VARCHAR(2), dbo.CF_JSON_VALUE(@pJsonRecibido,'Criterio')),'D')
SET @pId_Cliente  		    	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')),0)
SET @pInc_UCP_a_Fecha  		   	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Inc_UCP_a_Fecha')),0)
SET @pLimite		  		   	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Limite')),0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)
SET @pTipoDeuda 				= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Tipo')), 'H')
SET @pOrden 			    	= ISNULL(CONVERT(CHAR(2), dbo.CF_JSON_VALUE(@pJsonRecibido,'Orden')), 'RZ')
SET @pId_Moneda			    	= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Moneda')), '')
SET @pCotizacion			   	= ISNULL(CONVERT(Decimal(20,4), dbo.CF_JSON_VALUE(@pJsonRecibido,'Cotizacion')), 1)

-- @pDeudaActual: H = Historica , C = Cbte  , F = Vencimiento

/*

@pCriterio
CS  Control Saldos de cbtes con debe/haber
T	Saldo por cliente 
D	Detallado x cbte
TD  Total Debe / Haber

P	Cliente / Producto
TP  Total x Producto
CI  Control de total de items de facturas
CC  Control_Producto
*/

 
DECLARE @pFecha DATETIME,
		@Now DATETIME,
		@Sql VARCHAR(MAX),
		@TOTAL_PRINT DECIMAL(20,2),
		@Agrupar_GF TinyInt,
		@Deuda_Total DECIMAL(20,2)

 	
SET @pFecha = DATEADD(DAY, 1, CONVERT(DATE, @pFechaHasta));

SET @Now = GETDATE()

SET @Agrupar_GF = ISNULL(CONVERT(TINYINT, dbo.CF_xParam('Cli_Ref_CtaCte_Agrup')), 0);

UPDATE Clientes SET Id_Cliente_Ref = 0 WHERE Id_Cliente_Ref IS NULL
UPDATE Cbtes_Tipos SET Compromete_Recibos = 0  WHERE Compromete_Recibos IS NULL
UPDATE Cbtes_Tipos SET Compromete_Factura = 0 WHERE Compromete_Factura IS NULL


IF(@pModoDebug = 1)
BEGIN
	PRINT CONVERT(VARCHAR,GETDATE(),13) +' - Fin de Correcciones Iniciales'
END


CREATE TABLE #Deuda_Clientes_A_Fecha (
    Id_Cliente INT,
    ID_TIPO_CBTE char(4),
    COMPROBANTE_NRO int,
    FECHA DATETIME,
    IMP_TOTAL DECIMAL(18,2),
    Imp_Aplicado DECIMAL(18,2),
    Imp_Aplicado2 DECIMAL(18,2),
    SALDO DECIMAL(18,2),
    ID_TRANS INT,
    SIGNO SMALLINT,
    Fecha_Generacion DATETIME,
    COEFICIENTE DECIMAL(30,28),
	COTIZACION  DECIMAL(18,4),
	ID_MONEDA CHAR(3)
)

CREATE INDEX IX_DEUDA_IdCliente_IdTrans 
    ON #Deuda_Clientes_A_Fecha (Id_Cliente, ID_TRANS)
CREATE NONCLUSTERED INDEX IX_DEUDA_IdTrans 
    ON #Deuda_Clientes_A_Fecha (ID_TRANS) 
    INCLUDE (Id_Cliente, Fecha, IMP_TOTAL, Imp_Aplicado, Imp_Aplicado2, Signo)


SELECT Id_unid_Negocio INTO #Unid_Negocios FROM Empresas_Unid_Negocios
IF @pId_Unid_Negocio <> ''
   DELETE #Unid_Negocios WHERE Id_unid_Negocio <> @pId_Unid_Negocio

SELECT Id_Moneda INTO #Val_Monedas FROM Valores_Monedas
IF @pId_Moneda <> ''
   DELETE #Val_Monedas WHERE Id_Moneda <> @pId_Moneda

--- Empiezo copiando todo los cbtes de ventas/cobranzas
CREATE TABLE #Cbtes
(
    Id_Trans             INT NOT NULL,
    Id_Cliente           INT NOT NULL,
    Fecha                DATETIME NOT NULL,
    Imp_Total            DECIMAL(18,2) NOT NULL DEFAULT 0,
    Imputado             DECIMAL(18,2) NOT NULL DEFAULT 0,
    Imputado_D           DECIMAL(18,2) NOT NULL DEFAULT 0,
    A_Cuenta             DECIMAL(18,2) NOT NULL DEFAULT 0,
    Saldo                DECIMAL(18,2) NOT NULL DEFAULT 0,
    Id_Estado_Cbte       TINYINT NULL,
    Compromete_Factura   SMALLINT NOT NULL DEFAULT 0,
    Compromete_Recibos   SMALLINT NOT NULL DEFAULT 0,
    Id_Tipo_Cbte         CHAR(4) NOT NULL,
    Comprobante_Nro      INT NULL,
    Signo                SMALLINT NOT NULL DEFAULT 1,
    Id_Cliente_Ref       INT NOT NULL DEFAULT 0,
	Cotizacion           DECIMAL(18,4),
	Id_Moneda            CHAR(3)
);
IF @pTipoDeuda <> 'H'
   BEGIN
     IF @pTipoDeuda <> 'V'   
 			INSERT INTO #Cbtes
				SELECT 
					C.Id_Trans,
					CASE 
						WHEN @Agrupar_GF = 1 AND L.Id_Cliente_Ref <> 0 THEN L.Id_Cliente_Ref 
						ELSE C.Id_Cliente 
					END AS Id_Cliente,
					C.Fecha,
					C.IMP_TOTAL,
					CAST(0 AS DECIMAL(18,2)) AS Imputado,
					CAST(0 AS DECIMAL(18,2)) AS Imputado_D,
					CAST(0 AS DECIMAL(18,2)) AS A_cuenta,
					C.SALDO AS Saldo,
					C.Id_Estado_Cbte,
					T.Compromete_Factura AS Compromete_Factura,
					T.Compromete_Recibos AS Compromete_Recibos,
					C.Id_Tipo_Cbte,
					C.Comprobante_Nro,
					T.Compromete_Factura AS Signo,
					L.Id_Cliente_Ref AS Id_Cliente_Ref,
					C.Cotizacion,
					C.Id_Moneda
				FROM Cbtes C
				JOIN Cbtes_Tipos T 
					ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
				JOIN Clientes L 
					ON L.Id_Cliente = C.Id_Cliente
				JOIN #Unid_Negocios U 
					ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
				JOIN #Val_Monedas M 
					ON M.Id_Moneda = C.Id_Moneda
				WHERE 
					( T.Compromete_Factura IN (1, -1) OR T.Compromete_Recibos IN (1, -1) )
					AND C.Id_Estado_Cbte IN (1, 4)
					AND (C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
					AND C.Fecha  < @pFecha
					AND C.Id_Cliente > 1
					AND (@pId_Cliente = 0 OR C.Id_Cliente = @pId_Cliente OR L.Id_Cliente_Ref = @pId_Cliente)
					AND (@pClientes_activos = 0 OR L.Activo = 1);
		ELSE 
 			INSERT INTO #Cbtes
				SELECT 
					C.Id_Trans,
					CASE 
						WHEN @Agrupar_GF = 1 AND L.Id_Cliente_Ref <> 0 THEN L.Id_Cliente_Ref 
						ELSE C.Id_Cliente 
					END AS Id_Cliente,
					C.Fecha_Venc,
					C.IMP_TOTAL*C.Cotizacion AS IMP_TOTAL,
					CAST(0 AS DECIMAL(18,2)) AS Imputado,
					CAST(0 AS DECIMAL(18,2)) AS Imputado_D,
					CAST(0 AS DECIMAL(18,2)) AS A_cuenta,
					C.SALDO*C.Cotizacion AS Saldo,
					C.Id_Estado_Cbte,
					T.Compromete_Factura AS Compromete_Factura,
					T.Compromete_Recibos AS Compromete_Recibos,
					C.Id_Tipo_Cbte,
					C.Comprobante_Nro,
					T.Compromete_Factura AS Signo,
					L.Id_Cliente_Ref AS Id_Cliente_Ref,
					C.Cotizacion,
					C.Id_Moneda
				FROM Cbtes C
				JOIN Cbtes_Tipos T 
					ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
				JOIN Clientes L 
					ON L.Id_Cliente = C.Id_Cliente
				JOIN #Unid_Negocios U 
					ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
				JOIN #Val_Monedas M 
					ON M.Id_Moneda = C.Id_Moneda
				WHERE 
					( T.Compromete_Factura IN (1, -1) OR T.Compromete_Recibos IN (1, -1) )
					AND C.Id_Estado_Cbte IN (1, 4)
					AND (C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
					AND C.Fecha_Venc < @pFecha
					AND C.Id_Cliente > 1
					AND (@pId_Cliente = 0 OR C.Id_Cliente = @pId_Cliente OR L.Id_Cliente_Ref = @pId_Cliente)
					AND (@pClientes_activos = 0 OR L.Activo = 1);
        


		CREATE CLUSTERED INDEX IX_zCbtes_IdTrans2 ON #Cbtes(Id_Trans);

		CREATE NONCLUSTERED INDEX IX_zCbtes_IdCliente2 ON #Cbtes(Id_Cliente)
			INCLUDE (Saldo, Imp_Total, Imputado, Imputado_D, Signo, Fecha);

		CREATE NONCLUSTERED INDEX IX_zCbtes_IdClienteRef2 ON #Cbtes(Id_Cliente_Ref);

		UPDATE #Cbtes SET SIGNO = -1 WHERE Compromete_Factura = -1 OR  Compromete_Recibos IN (1,-1)
		UPDATE #Cbtes SET IMP_TOTAL = IMP_TOTAL * SIGNO, SALDO = SALDO * SIGNO

		INSERT INTO #Deuda_Clientes_A_Fecha
		SELECT C.Id_Cliente
				,C.ID_TIPO_CBTE
				,C.COMPROBANTE_NRO
				,C.FECHA
				,C.IMP_TOTAL
				,ISNULL(C.imputado,  0) AS Imp_Aplicado
				,ISNULL(C.imputado_d,0) AS Imp_Aplicado2
				,C.SALDO
				,C.ID_TRANS
				,C.SIGNO
				,@Now
				,CASE 
					WHEN ISNULL(C.IMP_TOTAL, 0) = 0 THEN 0
					ELSE ABS(C.SALDO) / ABS(C.IMP_TOTAL)
				END AS COEFICIENTE,
				C.Cotizacion,
				C.Id_Moneda
		FROM #CBTES C
  END
 ELSE
  BEGIN
	INSERT INTO #Cbtes
		SELECT 
			C.Id_Trans,
			CASE 
				WHEN @Agrupar_GF = 1 AND L.Id_Cliente_Ref <> 0 THEN L.Id_Cliente_Ref 
				ELSE C.Id_Cliente 
			END AS Id_Cliente,
			C.Fecha,
			C.IMP_TOTAL  * C.Cotizacion as IMP_TOTAL,
			CAST(0 AS DECIMAL(18,2)) AS Imputado,
			CAST(0 AS DECIMAL(18,2)) AS Imputado_D,
			CAST(0 AS DECIMAL(18,2)) AS A_cuenta,
			C.IMP_TOTAL * C.Cotizacion AS Saldo,
			C.Id_Estado_Cbte,
			T.Compromete_Factura AS Compromete_Factura,
			T.Compromete_Recibos AS Compromete_Recibos,
			C.Id_Tipo_Cbte,
			C.Comprobante_Nro,
			T.Compromete_Factura AS Signo,
			L.Id_Cliente_Ref AS Id_Cliente_Ref,
			C.Cotizacion,
			C.Id_Moneda
		FROM Cbtes C
		JOIN Cbtes_Tipos T 
			ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
		JOIN Clientes L 
			ON L.Id_Cliente = C.Id_Cliente
		JOIN #Unid_Negocios U 
			ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
		JOIN #Val_Monedas M 
			ON M.Id_Moneda = C.Id_Moneda
		WHERE 
			( T.Compromete_Factura IN (1, -1) OR T.Compromete_Recibos IN (1, -1) )
			AND C.Id_Estado_Cbte IN (1, 2, 4)
			AND (C.Id_Cond_Pago != 1 OR C.Id_Cond_Pago IS NULL)
			AND C.Fecha < @pFecha
			AND C.Id_Cliente > 1
			AND (@pId_Cliente = 0 OR C.Id_Cliente = @pId_Cliente OR L.Id_Cliente_Ref = @pId_Cliente);

 

	CREATE CLUSTERED INDEX IX_zCbtes_IdTrans ON #Cbtes(Id_Trans);

	CREATE NONCLUSTERED INDEX IX_zCbtes_IdCliente ON #Cbtes(Id_Cliente)
		INCLUDE (Saldo, Imp_Total, Imputado, Imputado_D, Signo, Fecha);

	CREATE NONCLUSTERED INDEX IX_zCbtes_IdClienteRef ON #Cbtes(Id_Cliente_Ref);

	IF(@pModoDebug = 1)
	BEGIN
		PRINT CONVERT(VARCHAR,GETDATE(),13) +' - Fin de creacion de tabla de cbtes'
	END


	-------------------------------------------------------- Calculo el saldo por cliente

	SELECT 	C.Id_Cliente,
			SUM(CASE WHEN C.Compromete_Factura = 1 OR C.Compromete_Recibos = -1 THEN C.IMP_TOTAL ELSE 0 END) AS Debe,
			SUM(CASE WHEN C.Compromete_Factura = -1 OR C.Compromete_Recibos = 1 THEN C.IMP_TOTAL ELSE 0 END) AS Haber,
			SUM(
				CASE WHEN C.Compromete_Factura = 1 OR C.Compromete_Recibos = -1 THEN C.IMP_TOTAL 
					 WHEN C.Compromete_Factura = -1 OR C.Compromete_Recibos = 1 THEN -C.IMP_TOTAL 
					 ELSE 0 
				END
			) AS Saldo
		INTO #Saldos
		FROM #Cbtes C
		GROUP BY C.Id_Cliente;

	IF(@pModoDebug = 2)
	BEGIN
		IF OBJECT_ID('dbo.z_Saldos') IS NOT NULL
			DROP TABLE dbo.z_Saldos
		SELECT * INTO z_Saldos FROM #Saldos  
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT CONVERT(VARCHAR,GETDATE(),13) +' - Fin de Creacion de tablas iniciales'
	END
	IF @pCriterio = 'TD' --Control Saldos
	BEGIN
		SELECT * FROM #Saldos

		IF(@pModoDebug = 1)
		BEGIN
			SET @TOTAL_PRINT = (SELECT SUM(SALDO) FROM #Saldos)
			PRINT 'TOTAL = ' + CONVERT(VARCHAR(100), @TOTAL_PRINT)  
		END

		RETURN 
	END
	--------------------------------------------------------------------------------------------------------


		--total aplicado por cbte con un recibo o NC
		SELECT A.ID_TRANS,SUM(ISNULL(A.Importe*C.Cotizacion,0))  AS Imp_Aplicado
		INTO #Aplicado
					FROM cbtes_aplica a
						JOIN #Cbtes p ON p.Id_Trans = A.ID_TRANS_D AND A.ID_TRANS <> 0
						JOIN #Cbtes C ON C.Id_Trans = A.ID_TRANS 
					WHERE 					
						(p.Compromete_Recibos in (1,-1) OR p.Compromete_Factura in (-1))
						GROUP BY A.ID_TRANS 
	--select * from #Aplicado where Id_Trans  in( 294802,294803,294804)
 
	-- Total aplicado destino contra un cbte
		SELECT A.ID_TRANS_D,SUM(ISNULL(A.Importe*P.Cotizacion,0))  AS Imp_Aplicado
		INTO #Aplicado_D
					FROM cbtes_aplica a
						JOIN #cbtes p ON p.Id_Trans = A.ID_TRANS_D
						JOIN #Cbtes K ON K.Id_Trans = A.ID_TRANS 
					WHERE A.Id_Trans != 0 and P.Id_Trans = A.ID_TRANS_D
						GROUP BY  A.ID_TRANS_D 

	--select * from #Aplicado_d where Id_Trans_d  in( 294802,294803,294804)

	update #cbtes set Imputado = a.Imp_Aplicado FROM #Aplicado a, #CBTES C WHERE C.ID_TRANS = A.ID_TRANS 

	update #cbtes set Imputado_D = a.Imp_Aplicado FROM #Aplicado_D a, #CBTES C WHERE C.ID_TRANS = A.ID_TRANS_D 
	----------------------------------------------------------------------

	---Actualizo los saldos en cbtes

	UPDATE C
	SET 
		Saldo =
			CASE 
				WHEN C.Compromete_Factura = 1 THEN
					CASE 
						WHEN C.Imputado + C.Imputado_D >= C.Imp_Total THEN 0
						ELSE C.Imp_Total - (C.Imputado + C.Imputado_D)
					END

				WHEN C.Compromete_Factura = -1 THEN
					CASE 
						WHEN ABS(C.Imputado) + C.Imputado_D >= C.Imp_Total THEN 0
						ELSE C.Imp_Total - (ABS(C.Imputado) + C.Imputado_D)
					END

				WHEN C.Compromete_Recibos = 1 THEN
					CASE 
						WHEN ABS(C.Imputado) + C.Imputado_D >= C.Imp_Total THEN 0
						ELSE C.Imp_Total - (ABS(C.Imputado) + C.Imputado_D)
					END

				ELSE C.Saldo
			END,
		Signo =
			CASE 
				WHEN C.Compromete_Recibos = 1 THEN -1
				ELSE C.Signo
			END
	FROM #Cbtes C;


	DELETE FROM #Cbtes WHERE Saldo = 0;
	UPDATE #Cbtes SET Saldo = Saldo * Signo;

	UPDATE Cbtes_Items SET Imp_Final = Imp_Gravado  
		FROM Cbtes_Items I JOIN #cbtes C ON C.Id_Trans = I.Id_Trans 
		WHERE C.Compromete_Recibos IN (1,-1) AND I.Imp_Gravado <> I.Imp_Final
	 

	INSERT INTO #Deuda_Clientes_A_Fecha
	SELECT C.Id_Cliente
			,C.ID_TIPO_CBTE
			,C.COMPROBANTE_NRO
			,C.FECHA
			,C.IMP_TOTAL
			,ISNULL(C.imputado,  0) AS Imp_Aplicado
			,ISNULL(C.imputado_d,0) AS Imp_Aplicado2
			,C.SALDO
			,C.ID_TRANS
			,C.SIGNO
			,@Now
			,CASE 
					WHEN ISNULL(C.IMP_TOTAL, 0) = 0 THEN 0
					WHEN ABS(ISNULL(C.SALDO,0)) / ABS(C.IMP_TOTAL) > 1 THEN 1
					ELSE ABS(ISNULL(C.SALDO,0)) / ABS(C.IMP_TOTAL)
				END AS COEFICIENTE,
			C.Cotizacion,
			C.Id_Moneda
	FROM #CBTES C

END

