CREATE TABLE #UCP (Id_Cliente INT, UCP_A_Fecha DATE)
CREATE INDEX Ix_ucp ON #UCP (Id_Cliente)

IF @pInc_UCP_a_Fecha = 1
BEGIN
	DECLARE @Fam_CuotasSoc INT
	SET @Fam_CuotasSoc = ISNULL(CONVERT(INT,dbo.CF_xParam('Fam_CuotasSoc')),0)

	INSERT INTO #UCP
		SELECT I.Id_Cliente,CONVERT(DATE, MAX(I.Fecha_qa)) AS UCP_A_Fecha
		FROM Cbtes_Items I
		JOIN Productos P	ON P.Id_Producto = I.Id_Producto	AND P.Id_Familia = @Fam_CuotasSoc
		JOIN Cbtes C		ON C.Id_Trans = I.Id_Trans			AND C.Id_Estado_Cbte IN (1,2,4)
		LEFT JOIN Cbtes_Aplica A ON A.Id_Trans = C.Id_Trans
		LEFT JOIN Cbtes R ON R.Id_Trans = A.Id_Trans_D AND ( R.Id_Estado_Cbte IN (1,2,4) )
		LEFT JOIN Cbtes_Tipos TR ON TR.Id_Tipo_Cbte = R.Id_Tipo_Cbte AND ( TR.Compromete_Recibos  = 1 OR TR.Compromete_Factura = -1)
		JOIN Cbtes_Tipos T	ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte	AND T.Compromete_Factura = 1
		JOIN (SELECT DISTINCT Id_Cliente FROM #Deuda_Clientes_A_Fecha) D ON D.Id_Cliente = I.Id_Cliente
		WHERE C.Fecha < @pFecha AND R.Fecha < @pFecha
		GROUP BY I.Id_Cliente;
END

IF @pCriterio = 'D' OR  @pCriterio = 'CI'   
BEGIN
    SELECT I.Id_Trans,SUM(ISNULL(i.imp_final,0)) AS Imp_Total, 
		Detalle = 
		CASE @pId_Cliente WHEN 0 THEN ''
		ELSE
			STUFF(
				(
					SELECT ', ' + LTRIM(RTRIM(ISNULL(I2.Descripcion_producto,''))) +	
						CASE P.Flag_Mes 
							WHEN 1 THEN ' ' + RIGHT(CONVERT(VARCHAR,I2.fecha_QA,3),5) +' '+ CONVERT(VARCHAR,I2.Imp_Final)
							ELSE 
								CASE P.Flag_Periodo WHEN 1 THEN ' ' + CONVERT(VARCHAR,I2.fecha_QA,3) +'-' + CONVERT(VARCHAR,I2.Fecha_Venc,3) +' '+ CONVERT(VARCHAR,I2.Imp_Final)
								ELSE ''
								END 
						END
					FROM Cbtes_items I2
						 JOIN Productos P ON P.Id_Producto = I2.Id_Producto
					WHERE I2.Id_Producto <> '' and I2.Id_Trans = I.Id_TRans
					FOR XML PATH(''), TYPE
				).value('.', 'varchar(max)')
			,1,2,'') 
        END
		INTO #DetItem 
		FROM Cbtes_Items i
			JOIN #CBTES C ON C.Id_Trans =  I.Id_Trans 
		GROUP BY I.Id_Trans
    CREATE INDEX IX_zCbtes_Item_xxx ON #DetItem (Id_Trans)
END 


IF @pCriterio = 'D'
BEGIN
	IF (@pLimite > 0)
	BEGIN
		SELECT TOP (@pLimite) D.Id_Cliente,K.Razon_Social,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,K.Fecha_Alta,K.Fecha_Baja
					,D.Fecha,C.Fecha_Venc,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion
					,c.Id_Moneda AS Moneda, D.Saldo AS IMP_TOTAL,D.Id_Trans 
				   ,ISNULL(I.Imp_Total,0) - ABS(D.IMP_TOTAL) as Items
				   ,K.Ult_Cuota_Paga
				   ,ISNULL(U.UCP_A_Fecha,'19000101') as UCP_A_Fecha, ISNULL(I.Detalle,'') AS Detalle
		   FROM #Deuda_Clientes_A_Fecha D 
				LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente
				JOIN Clientes K ON K.Id_Cliente = D.Id_Cliente AND (@pClientes_activos = 0 OR K.Activo = 1)
				JOIN Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
				JOIN Cbtes C ON C.Id_trans = D.Id_Trans AND D.Saldo <> 0
				LEFT JOIN #DetItem I  ON I.Id_trans = D.Id_Trans  
			  ORDER BY K.Razon_Social,D.Fecha
	END
	ELSE
	BEGIN
		SELECT D.Id_Cliente,K.Razon_Social,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,K.Fecha_Alta,K.Fecha_Baja,D.Fecha,C.Fecha_Venc,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion,c.Id_Moneda AS Moneda, D.Saldo AS IMP_TOTAL,D.Id_Trans 
		   ,ISNULL(I.Imp_Total,0) - ABS(D.IMP_TOTAL) as Items
		   ,K.Ult_Cuota_Paga 
		   ,ISNULL(U.UCP_A_Fecha,'19000101') as UCP_A_Fecha, ISNULL(I.Detalle,'') AS Detalle
		   FROM #Deuda_Clientes_A_Fecha D 
				LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente
				JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente AND (@pClientes_activos = 0 OR K.Activo = 1)
				JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
				JOIN Cbtes C ON C.Id_trans = D.Id_Trans AND D.Saldo <> 0
				LEFT JOIN #DetItem I  ON I.Id_trans = D.Id_Trans  
			  ORDER BY K.Razon_Social,D.Fecha
	END
END

IF @pCriterio = 'CI'
BEGIN
	IF (@pLimite > 0)
	BEGIN
		SELECT TOP (@pLimite) D.Id_Cliente,K.Razon_Social,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,K.Fecha_Alta,K.Fecha_Baja,D.Fecha,C.Fecha_Venc
			,D.ID_TIPO_CBTE
			,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion
			,c.Id_Moneda AS Moneda
			, D.Saldo 
			,D.Id_Trans 
			,I.Imp_Total AS Total_Items
		   ,ISNULL(I.Imp_Total,0) - ABS(D.IMP_TOTAL) as Dif_Items
		   ,K.Ult_Cuota_Paga
		   ,ISNULL(U.UCP_A_Fecha,'19000101') as UCP_A_Fecha
		   FROM #Deuda_Clientes_A_Fecha D 
				LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente
				JOIN Clientes K ON K.Id_Cliente = D.Id_Cliente AND (@pClientes_activos = 0 OR K.Activo = 1)
				JOIN Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
				JOIN Cbtes C ON C.Id_trans = D.Id_Trans AND D.Saldo <> 0
				LEFT JOIN #DetItem I  ON I.Id_trans = D.Id_Trans 
		   WHERE ISNULL(I.Imp_Total,0) <> ABS(D.IMP_TOTAL)	
		   ORDER BY K.Razon_Social,D.Fecha
	END
	ELSE
	BEGIN
		SELECT D.Id_Cliente,K.Razon_Social,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,K.Fecha_Alta,K.Fecha_Baja,D.Fecha,C.Fecha_Venc
			,D.ID_TIPO_CBTE
			--,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion
			,c.Id_Moneda AS Moneda
			, D.Saldo 
			,D.Id_Trans 
			,I.Imp_Total AS Total_Items
		   ,ISNULL(I.Imp_Total,0) - ABS(D.IMP_TOTAL) as Dif_Items
		   ,K.Ult_Cuota_Paga
		   ,ISNULL(U.UCP_A_Fecha,'19000101') as UCP_A_Fecha
		   FROM #Deuda_Clientes_A_Fecha D 
				LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente
				JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente AND (@pClientes_activos = 0 OR K.Activo = 1)
				JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
				JOIN Cbtes C ON C.Id_trans = D.Id_Trans AND D.Saldo <> 0
				LEFT JOIN #DetItem I  ON I.Id_trans = D.Id_Trans  
           WHERE ISNULL(I.Imp_Total,0) <> ABS(D.IMP_TOTAL)	
		   ORDER BY K.Razon_Social,D.Fecha
	END
END
