CREATE PROCEDURE [dbo].[CPJ_Clientes_Deuda_a_Fecha_T1] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON
/*Parametros*/

DECLARE 	@pFechaHasta			DATETIME,
			@pId_Unid_Negocio       VARCHAR(10),
			@pFiltrar_con_saldo     TINYINT,
			@pClientes_activos      TINYINT,
			@pFiltroFecha           TINYINT,
			@pCriterio              VARCHAR(2),
			@pId_Cliente            INT,
			@pInc_UCP_a_Fecha		TINYINT,
			@pLimite				INT,
            @pRegenerar             TINYINT
			 
SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())
SET @pFiltrar_con_saldo			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Filtrar_con_saldo')),0)
SET @pClientes_activos			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Clientes_activos')),0)
SET @pFiltroFecha		    	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FiltroFecha')),0)
SET @pCriterio			        = ISNULL(CONVERT(VARCHAR(2), dbo.CF_JSON_VALUE(@pJsonRecibido,'Criterio')),'R')
SET @pId_Cliente  		    	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')),0)
SET @pInc_UCP_a_Fecha  		   	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Inc_UCP_a_Fecha')),0)
SET @pLimite		  		   	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Limite')),0)
SET @pRegenerar  		   	    = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Regenerar')),0)

-- Seteo el nombre de la nueva tabla
DECLARE @suffix char(8) = CONVERT(char(8), @pFechaHasta, 112); -- yyyymmdd
DECLARE @tblName sysname = N'dbo.Z_DEUDA_CLIENTES_FECHA_' + @suffix;
DECLARE @tblQuoted nvarchar(300) = QUOTENAME('dbo') + N'.' + QUOTENAME('Z_DEUDA_CLIENTES_FECHA_' + @suffix);
 
DECLARE @pFecha DATETIME
SET @pFecha  = DATEADD(day, 1, @pFechaHasta);

DECLARE @Agrupar_GF TinyInt
SET @Agrupar_GF =  dbo.CF_xParam('Cli_Ref_CtaCte_Agrup')

IF(@pRegenerar = 1)
BEGIN
	SET @pId_Cliente = 0
END

Select Id_Cliente_Ref
    	into #Clientes from Clientes where 1=0

Create Index Ix_Clientes on #Clientes (Id_Cliente_Ref)

IF @Agrupar_GF <> 1
   BEGIN
		If @pId_Cliente <> 0
           INSERT INTO #Clientes SELECT Id_Cliente as Id_Cliente_Ref 
										from Clientes where Id_Cliente = @pId_Cliente
		  Else
		   If @pClientes_activos = 1
              INSERT INTO #Clientes SELECT Id_Cliente as Id_Cliente_Ref 
										from Clientes where Activo = 1 and Id_cliente > 1
			Else
              INSERT INTO #Clientes SELECT Id_Cliente as Id_Cliente_Ref 
										from Clientes where Activo = 1 and Id_cliente > 1
   END
  ELSE
   BEGIN
		Select Id_cliente,Id_Cliente_Ref,Razon_Social
    			into #Clientes_Temp from Clientes where 1=0

		Create Index Ix_Clientes_Temp on #Clientes_Temp (Id_cliente,Id_Cliente_Ref)

		If @pId_Cliente <> 0
			 Insert Into #Clientes_Temp select Id_cliente, case ISNULL(Id_Cliente_Ref,0) 
										WHEN 0 THEN Id_Cliente
										ELSE Id_Cliente_Ref
										END AS Id_Cliente_Ref,Razon_Social
										from Clientes where Id_Cliente = @pId_Cliente
		  Else
		   If @pClientes_activos = 1
			  Insert Into #Clientes_Temp Select Id_cliente, case ISNULL(Id_Cliente_Ref,0) 
										WHEN 0 THEN Id_Cliente
										ELSE Id_Cliente_Ref
										END AS Id_Cliente_Ref,Razon_Social
										from Clientes where Activo = 1 and Id_cliente > 1
			Else
			  Insert Into #Clientes_Temp select Id_cliente, case ISNULL(Id_Cliente_Ref,0) 
										WHEN 0 THEN Id_Cliente
										ELSE Id_Cliente_Ref
										END AS Id_Cliente_Ref,Razon_Social
										from Clientes where  Id_cliente > 1

 
			 INSERT INTO #Clientes SELECT DISTINCT(Id_Cliente_Ref) FROM #Clientes_Temp
		END


Select Id_unid_Negocio into #Unid_Negocios from Empresas_Unid_Negocios
If @pId_Unid_Negocio <> ''
   Delete #Unid_Negocios where Id_unid_Negocio <> @pId_Unid_Negocio

-- Marca para regenerar si NO existe la tabla versionada por fecha o si está vacía
IF OBJECT_ID(@tblName, 'U') IS NULL
BEGIN
    SET @pRegenerar = 1;
END
ELSE 
BEGIN
    DECLARE @cnt int, @sqlCnt nvarchar(max);
    SET @sqlCnt = N'SELECT @cnt = COUNT(*) FROM ' + @tblQuoted + N';'
    EXEC sp_executesql @sqlCnt, N'@cnt int OUTPUT', @cnt = @cnt OUTPUT

    IF @cnt = 0
        SET @pRegenerar = 1;
END

IF(@pRegenerar = 1)
BEGIN
	--paso 1 FC
    SELECT K.Id_Cliente_Ref AS Id_Cliente
                ,C.ID_TIPO_CBTE,C.COMPROBANTE_NRO,C.FECHA,(C.Imp_Total * T.Compromete_Factura) AS IMP_TOTAL
                ,Isnull((SELECT SUM(ISNULL(A.Importe,0)) 
                    FROM cbtes_aplica a, cbtes p, Cbtes_Tipos tp 
                    WHERE p.Id_Trans = A.ID_TRANS_D  AND A.ID_TRANS = C.Id_Trans and p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte 
                        and  ( tp.Compromete_Recibos in (1,-1) OR tp.Compromete_Factura in (-1))
                        AND P.FECHA < @pFecha AND p.id_estado_cbte not in (0,3)),0) AS Imp_Aplicado 
                ,CAST(0 AS DECIMAL(12,2)) AS Imp_Aplicado2
                ,(C.SALDO * T.Compromete_Factura) AS SALDO,C.ID_TRANS,1 AS SIGNO
        INTO #DEUDA
        FROM CBTES C
        JOIN CBTES_TIPOS T ON  C.Id_Tipo_Cbte = T.ID_TIPO_CBTE AND T.Compromete_Factura IN (1)
        JOIN #Unid_Negocios U ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
        JOIN Clientes O ON  C.Id_Cliente = O.ID_Cliente
        , #Clientes k
        WHERE  CASE ISNULL(O.Id_Cliente_Ref,0) 
                                    WHEN 0 THEN O.Id_Cliente
                                    ELSE O.Id_Cliente_Ref
                                    END = K.Id_Cliente_Ref
            AND C.Id_Estado_Cbte NOT IN (0,3)
            AND C.Id_Cond_Pago <> 1
            AND C.Id_Cliente > 1
            AND C.FECHA < @pFecha
            AND ( NOT EXISTS  (SELECT A.ID_TRANS FROM CBTES_APLICA A WHERE C.ID_TRANS = A.ID_TRANS) OR C.SALDO <> 0
            OR (SELECT MAX(p.fecha)
                        FROM cbtes_aplica a
                        JOIN cbtes p ON p.Id_Trans = A.ID_TRANS_D AND p.id_estado_cbte not in (0,3)
                        JOIN Cbtes_Tipos tp ON p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte and (tp.Compromete_Recibos in (1,-1) 
                            OR ( tp.Compromete_Factura in (-1)   AND P.Id_Cond_Pago <> 1)
                            )
                        WHERE  A.ID_TRANS = C.Id_Trans ) >= @pFecha )

    -- paso 2 NC

    UNION ALL

    SELECT K.Id_Cliente_Ref AS Id_Cliente
                ,C.ID_TIPO_CBTE,C.COMPROBANTE_NRO,C.FECHA,(C.IMP_TOTAL* T.Compromete_Factura) AS IMP_TOTAL
                ,(SELECT isnull(SUM(A.Importe),0)
                        FROM cbtes_aplica a
                        JOIN cbtes p ON p.Id_Trans = A.ID_TRANS AND P.Id_Cond_Pago <> 1 AND P.FECHA < @pFecha AND p.id_estado_cbte not in (0,3)
                        JOIN Cbtes_Tipos tp ON p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte   and  ( tp.Compromete_Recibos in (1,-1) OR tp.Compromete_Factura in (1))
                        WHERE A.ID_TRANS_D = C.Id_Trans ) AS Imp_Aplicado 
                ,CAST(0 AS DECIMAL(12,2)) AS Imp_Aplicado2
                ,(C.SALDO* T.Compromete_Factura) AS SALDO,C.ID_TRANS,-1 AS SIGNO
        FROM CBTES C
        JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.ID_TIPO_CBTE AND T.Compromete_Factura IN (-1)
        JOIN #Unid_Negocios U ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
        JOIN Clientes O ON C.Id_Cliente = O.ID_Cliente
        , #Clientes k
        WHERE  CASE ISNULL(O.Id_Cliente_Ref,0) 
                                    WHEN 0 THEN O.Id_Cliente
                                    ELSE O.Id_Cliente_Ref
                                    END = K.Id_Cliente_Ref
            AND C.Id_Cond_Pago <> 1
            AND C.Id_Estado_Cbte NOT IN (0,3)
            AND C.Id_Cliente > 1
            AND C.FECHA < @pFecha
            AND ( NOT EXISTS  (SELECT A.ID_TRANS FROM CBTES_APLICA A WHERE C.ID_TRANS = A.ID_TRANS)
            OR 	(SELECT MAX(p.fecha)
                        FROM cbtes_aplica a
                        JOIN cbtes p ON p.Id_Trans = A.ID_TRANS_D AND p.id_estado_cbte not in (0,3)
                        JOIN Cbtes_Tipos tp ON p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte and (tp.Compromete_Recibos in (1,-1) 
                            OR ( tp.Compromete_Factura in (-1)   AND P.Id_Cond_Pago <> 1)
                            )
                        WHERE  A.ID_TRANS = C.Id_Trans ) >= @pFecha )
            
            
    --paso 3 OP

    UNION ALL

    SELECT  K.Id_Cliente_Ref AS Id_Cliente
            ,C.ID_TIPO_CBTE,C.COMPROBANTE_NRO,C.FECHA,(C.IMP_TOTAL* -1) as IMP_TOTAL
            ,(SELECT ISNULL(SUM(A.IMPORTE),0) FROM CBTES_APLICA A, CBTES K1 WHERE C.ID_TRANS = A.ID_TRANS_D AND K1.FECHA < @pFecha
                AND A.ID_TRANS = K1.ID_TRANS AND K1.ID_ESTADO_CBTE NOT IN (0,3)  and a.id_trans <> 0
                AND ISNULL((SELECT COUNT(*) FROM CBTES_APLICA CA WHERE C.ID_TRANS = CA.ID_TRANS_D),0) > = 1 
                )  as Imp_Aplicado
            ,(SELECT ISNULL(SUM(A.IMPORTE),0) FROM CBTES_APLICA A, CBTES K WHERE C.ID_TRANS = A.ID_TRANS AND K.FECHA < @pFecha
                AND A.ID_TRANS_D = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3) )  as Imp_Aplicado2,
                C.SALDO,C.ID_TRANS,-1 AS SIGNO
        FROM CBTES C
        JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.ID_TIPO_CBTE AND T.Compromete_Recibos IN (1,-1)
        JOIN #Unid_Negocios U ON  U.Id_Unid_Negocio = T.Id_Unid_Negocio
        JOIN Clientes O ON C.Id_Cliente = O.ID_Cliente
        , #Clientes k
        WHERE  CASE ISNULL(O.Id_Cliente_Ref,0) 
                                    WHEN 0 THEN O.Id_Cliente
                                    ELSE O.Id_Cliente_Ref
                                    END = K.Id_Cliente_Ref
            AND C.Id_Estado_Cbte NOT IN (0,3)
            AND C.Id_Cliente > 1
            AND C.FECHA < @pFecha
            AND (((SELECT ISNULL(MAX(A.ID_TRANS),0) FROM CBTES_APLICA A , CBTES K WHERE C.ID_TRANS = A.Id_Trans_D
                AND A.ID_TRANS = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3)
                AND K.FECHA < @pFecha
                ) = 0)
            OR (SELECT ISNULL(SUM(A.IMPORTE),0) FROM CBTES_APLICA A, CBTES K WHERE C.ID_TRANS = A.Id_Trans_D
                AND A.ID_TRANS = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3)	AND A.ID_TRANS <> 0
                AND K.FECHA < @pFecha
                ) <> ABS(C.IMP_TOTAL) )
            AND (SELECT ISNULL(ABS(SUM(A.IMPORTE)),0)  FROM CBTES_APLICA A, CBTES K WHERE C.Id_Trans = A.Id_Trans
                AND A.ID_TRANS_D = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3)
                AND K.FECHA < @pFecha
                ) <> ABS(C.IMP_TOTAL) 


    UPDATE #DEUDA SET Imp_Aplicado = abs(IMP_TOTAL), Saldo = 0  FROM #DEUDA WHERE  ABS(Imp_Aplicado) > abs(IMP_TOTAL)
    
    /* ====== Crear/limpiar tabla por fecha y copiar #DEUDA ====== */
    DECLARE @sql nvarchar(max)

    -- Crear si no existe
    IF OBJECT_ID(@tblName, 'U') IS NULL
    BEGIN
        SET @sql = N'
        CREATE TABLE ' + @tblQuoted + N'(
            Id_Cliente INT,
            ID_TIPO_CBTE char(4),
            COMPROBANTE_NRO int,
            FECHA DATETIME,
            IMP_TOTAL DECIMAL(18,2),
            Imp_Aplicado DECIMAL(18,2),
            Imp_Aplicado2 DECIMAL(18,2),
            SALDO DECIMAL(18,2),
            ID_TRANS INT,
            SIGNO SMALLINT
        );
        CREATE INDEX IX_DEUDA_IdCliente_IdTrans ON ' + @tblQuoted + N'(Id_Cliente, ID_TRANS);'
        EXEC sp_executesql @sql
    END
    ELSE
    BEGIN
        SET @sql = N'DELETE FROM ' + @tblQuoted + N';'
        EXEC sp_executesql @sql
    END

    -- Insertar los datos de #DEUDA en la tabla por fecha
    SET @sql = N'INSERT INTO ' + @tblQuoted + N'
                (Id_Cliente, ID_TIPO_CBTE, COMPROBANTE_NRO, FECHA, IMP_TOTAL,
                 Imp_Aplicado, Imp_Aplicado2, SALDO, ID_TRANS, SIGNO)
                SELECT Id_Cliente, ID_TIPO_CBTE, COMPROBANTE_NRO, FECHA, IMP_TOTAL,
                       Imp_Aplicado, Imp_Aplicado2, SALDO, ID_TRANS, SIGNO
                FROM #DEUDA;'
    EXEC sp_executesql @sql

END

-- 1) Crear SIEMPRE la #temp con el layout esperado
IF OBJECT_ID('tempdb..#Z_DEUDA_CLIENTES_FECHA') IS NOT NULL DROP TABLE #Z_DEUDA_CLIENTES_FECHA;

CREATE TABLE #Z_DEUDA_CLIENTES_FECHA (
    Id_Cliente      INT,
    ID_TIPO_CBTE    CHAR(4),
    COMPROBANTE_NRO INT,
    FECHA           DATETIME,
    IMP_TOTAL       DECIMAL(18,2),
    Imp_Aplicado    DECIMAL(18,2),
    Imp_Aplicado2   DECIMAL(18,2),
    SALDO           DECIMAL(18,2),
    ID_TRANS        INT,
    SIGNO           SMALLINT
);

-- 2) Si existe la tabla por fecha, cargarla en la #temp; si no, queda vacía
IF OBJECT_ID(@tblName, 'U') IS NOT NULL
BEGIN
    DECLARE @sqlTemp NVARCHAR(MAX) =
        N'INSERT INTO #Z_DEUDA_CLIENTES_FECHA
          (Id_Cliente,ID_TIPO_CBTE,COMPROBANTE_NRO,FECHA,IMP_TOTAL,
           Imp_Aplicado,Imp_Aplicado2,SALDO,ID_TRANS,SIGNO)
          SELECT Id_Cliente,ID_TIPO_CBTE,COMPROBANTE_NRO,FECHA,IMP_TOTAL,
                 Imp_Aplicado,Imp_Aplicado2,SALDO,ID_TRANS,SIGNO
          FROM ' + @tblQuoted + N';';
    EXEC sp_executesql @sqlTemp;
END


CREATE TABLE #UCP (Id_Cliente INT, UCP_A_Fecha DATE)
Create Index Ix_ucp on #UCP (Id_Cliente)

IF @pInc_UCP_a_Fecha = 1
BEGIN
	DECLARE @Fam_CuotasSoc INT
	SET @Fam_CuotasSoc = CONVERT(INT,dbo.CF_xParam('Fam_CuotasSoc'))

	INSERT INTO #UCP
	SELECT I.Id_Cliente,CONVERT(DATE,MAX(I.Fecha_qa) ) AS UCP_A_Fecha
		FROM Cbtes_Items I
		    JOIN  Productos P ON P.Id_Producto = I.Id_Producto AND P.Id_Familia = @Fam_CuotasSoc
			JOIN  Cbtes C ON C.Id_Trans = I.Id_Trans AND C.Id_Estado_Cbte IN (1,2,4)
				LEFT JOIN Cbtes_Aplica A ON A.Id_Trans = C.Id_Trans
					LEFT JOIN Cbtes R ON R.Id_Trans = A.Id_Trans_D AND ( R.Id_Estado_Cbte IN (1,2,4) )
					LEFT JOIN Cbtes_Tipos TR ON TR.Id_Tipo_Cbte = R.Id_Tipo_Cbte AND ( TR.Compromete_Recibos  = 1 OR TR.Compromete_Factura = -1)
			JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte AND T.Compromete_Factura = 1
			, #Z_DEUDA_CLIENTES_FECHA D
		WHERE I.Id_Cliente = D.Id_Cliente
		AND C.Fecha < @pFecha
		AND R.Fecha < @pFecha
		GROUP BY I.Id_Cliente
		
	
END


if @pCriterio = 'D'
IF (@pLimite > 0)
BEGIN
	SELECT TOP (@pLimite) D.Id_Cliente,K.Razon_Social,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,K.Fecha_Alta,K.Fecha_Baja,D.Fecha,C.Fecha_Venc,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion,c.Id_Moneda AS Moneda, ISNULL(D.imp_total,0) - ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2) ,0) * D.Signo  AS IMP_TOTAL,D.Id_Trans 
	   ,(select sum(isnull(i.imp_final,0)) from cbtes_items i where i.id_trans = d.id_trans)-abs(D.imp_total) as items
	   ,K.Ult_Cuota_Paga
	   ,ISNULL(U.UCP_A_Fecha,'19000101') as UCP_A_Fecha
	   FROM #Z_DEUDA_CLIENTES_FECHA D 
			LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente
			JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente 
			JOIN #Clientes KT ON KT.Id_Cliente_Ref = COALESCE(NULLIF(K.Id_Cliente_Ref, 0), K.Id_Cliente)
			JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
			, CBTES C 
	   WHERE C.Id_trans = D.Id_Trans AND ISNULL(D.imp_total,0)- ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2),0)*D.SIGNO  <> 0
		  ORDER BY K.Razon_Social,D.Fecha
END
ELSE
BEGIN
	SELECT D.Id_Cliente,K.Razon_Social,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,K.Fecha_Alta,K.Fecha_Baja,D.Fecha,C.Fecha_Venc,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion,c.Id_Moneda AS Moneda, ISNULL(D.imp_total,0) - ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2) ,0) * D.Signo  AS IMP_TOTAL,D.Id_Trans 
	   ,(select sum(isnull(i.imp_final,0)) from cbtes_items i where i.id_trans = d.id_trans)-abs(D.imp_total) as items
	   ,K.Ult_Cuota_Paga
	   ,ISNULL(U.UCP_A_Fecha,'19000101') as UCP_A_Fecha
	   FROM #Z_DEUDA_CLIENTES_FECHA D 
			LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente
			JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente 
			JOIN #Clientes KT ON KT.Id_Cliente_Ref = COALESCE(NULLIF(K.Id_Cliente_Ref, 0), K.Id_Cliente)
			JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
			, CBTES C 
	   WHERE C.Id_trans = D.Id_Trans AND ISNULL(D.imp_total,0)- ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2),0)*D.SIGNO  <> 0
		  ORDER BY K.Razon_Social,D.Fecha
END
 
 
if @pCriterio = 'T'
    IF @pFiltrar_con_saldo = 1
	   BEGIN
		SELECT D.Id_Cliente,K.Razon_Social,SUM(ISNULL(Imp_total,0) - ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2),0) * Signo) as Saldo 
			,K.Ult_Cuota_Paga
			,U.UCP_A_Fecha,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,K.Fecha_Alta,K.Fecha_Baja
		   FROM #Z_DEUDA_CLIENTES_FECHA D 
			LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente		
			JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente
			JOIN #Clientes KT ON KT.Id_Cliente_Ref = COALESCE(NULLIF(K.Id_Cliente_Ref, 0), K.Id_Cliente)
			JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
		   GROUP BY D.Id_Cliente,Razon_Social,K.Ult_Cuota_Paga,U.UCP_A_Fecha ,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion,K.Telefono,K.Fecha_Alta,K.Fecha_Baja
		   HAVING SUM(ISNULL(Imp_total,0) - ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2),0) * Signo) <> 0
			ORDER BY Razon_Social 
	   END
      ELSE
		SELECT D.Id_Cliente,K.Razon_Social,SUM((ISNULL(imp_total,0)) - Abs(ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2),0))*SIGNO) as Saldo 
			,K.Ult_Cuota_Paga
			,U.UCP_A_Fecha,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,K.Fecha_Alta,K.Fecha_Baja
				   FROM #Z_DEUDA_CLIENTES_FECHA D 
						LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente			
						JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente
						JOIN #Clientes KT ON KT.Id_Cliente_Ref = COALESCE(NULLIF(K.Id_Cliente_Ref, 0), K.Id_Cliente)
						JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli 
		   GROUP BY D.Id_Cliente,K.Razon_Social ,K.Ult_Cuota_Paga,U.UCP_A_Fecha ,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion,K.Telefono,K.Fecha_Alta,K.Fecha_Baja
		ORDER BY Razon_Social 

if @pCriterio = 'P' OR @pCriterio = 'TP'
    BEGIN
		SELECT C.Id_Cliente,K.Razon_Social,D.Fecha,C.Fecha_Venc,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion
				,c.Id_Moneda AS Moneda
				,I.Id_Trans
				,I.Id_Producto
				,I.Descripcion_Producto
				,I.IMP_FINAL*D.SIGNO AS Imp_Prod
				,ISNULL(D.imp_totaL,0)* D.Signo AS Imp_Fac 
				,ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2) ,0) * D.Signo  AS Imp_Apli
				,ABS((ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO )/D.imp_total) AS Coef
				,(I.IMP_FINAL*D.SIGNO) * (ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO )/D.imp_total AS Saldo,I.Id_Cliente AS Id_Cliente_Item ,H.Razon_Social AS Razon_Social_Item
				,K.Ult_Cuota_Paga
		INTO #DET
		FROM #Z_DEUDA_CLIENTES_FECHA D JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente
			JOIN #Clientes KT ON KT.Id_Cliente_Ref = COALESCE(NULLIF(K.Id_Cliente_Ref, 0), K.Id_Cliente)
			, CBTES C  JOIN  CBTES_ITEMS I ON C.ID_TRANS = I.ID_TRANS
				 LEFT JOIN Clientes H ON I.Id_Cliente = H.Id_Cliente
				 JOIN Cbtes_Tipos T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
		WHERE   D.ID_TRANS = C.ID_TRANS AND ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO  <> 0 
				AND T.Compromete_Factura IN (1,-1)
				AND D.imp_total <> 0


		INSERT INTO #DET
			SELECT C.Id_Cliente,K.Razon_Social,D.Fecha,C.Fecha_Venc,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion,c.Id_Moneda AS Moneda,C.ID_TRANS, 'ACUENTA' AS ID_PRODUCTO,'PAGOS A CUENTA' AS Descripcion_Producto, 0 AS IMP_PROD, ISNULL(D.imp_totaL,0)* D.Signo AS IMP_FAC ,  ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2) ,0) * D.Signo  AS IMP_APLI
				 , ABS((ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO )/D.imp_total) AS COEF
				 ,0 AS SALDO ,0 AS Id_Cliente_Item ,'' AS Razon_Social_Item
				 ,K.Ult_Cuota_Paga
			FROM #Z_DEUDA_CLIENTES_FECHA D JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente
			    JOIN #Clientes KT ON KT.Id_Cliente_Ref = COALESCE(NULLIF(K.Id_Cliente_Ref, 0), K.Id_Cliente)
				, CBTES C JOIN Cbtes_Tipos T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
			   WHERE   D.ID_TRANS = C.ID_TRANS AND ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO  <> 0 
			   AND T.Compromete_Recibos IN (1,-1)
			   AND D.imp_total <> 0

		UPDATE  #DET SET IMP_PROD = (IMP_FAC*COEF)*-1, SALDO  = (IMP_FAC*COEF)*-1 
				 WHERE IMP_PROD = 0    AND IMP_FAC >= ABS(IMP_APLI)  AND ID_PRODUCTO ='ACUENTA'

		UPDATE  #DET SET IMP_PROD = (IMP_FAC*COEF), SALDO  = (IMP_FAC*COEF) 
				 WHERE IMP_PROD = 0  AND IMP_FAC < ABS(IMP_APLI)  AND ID_PRODUCTO ='ACUENTA'

        IF @pCriterio = 'P'
		     SELECT D.*, U.UCP_A_Fecha
				FROM #DET D 
							LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente				
				ORDER BY Razon_Social ,Razon_Social_Item,Descripcion_Producto ,Fecha
		ELSE
			 SELECT Id_Producto,Descripcion_Producto,Sum(Saldo) As Saldo 
			   	 FROM #DET
				 Group by Id_Producto,Descripcion_Producto 
				 ORDER BY Descripcion_Producto 

		 DROP TABLE #DET
	 END

DROP TABLE #UCP
DROP TABLE #Clientes
DROP TABLE #Unid_Negocios
DROP TABLE #Z_DEUDA_CLIENTES_FECHA

IF(@pRegenerar = 1)
BEGIN
	DROP TABLE #DEUDA
END 


