--- criterio total se utiliza tambien en deuda actual

IF @pCriterio = 'T'
BEGIN
    IF @pFiltrar_con_saldo = 1 -- Solo deudores
    BEGIN
		SET @Deuda_Total = (SELECT SUM(Saldo) 
            FROM #Cbtes_TotCli D 
                LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente	
                JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente AND (@pClientes_activos = 0 OR K.Activo = 1)
                JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
            WHERE D.Saldo > 0)

   SET @Sql = 'SELECT K.Id_Cliente,K.Razon_Social,D.Saldo,K.Ult_Cuota_Paga
            ,U.UCP_A_Fecha,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono
			,K.Fecha_Alta,K.Fecha_Baja,' + CAST(@Deuda_Total AS char(20)) + ' As Deuda_Total
            FROM #Cbtes_TotCli D 
                LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente	
                JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente AND (@pClientes_activos = 0 OR K.Activo = 1)
                JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
            WHERE D.Saldo > 0'
			
    --        ORDER BY Razon_Social 
    END
    ELSE IF @pFiltrar_con_saldo = 2 -- Solo acreedores
    BEGIN
	     SET @Deuda_Total = (SELECT SUM(Saldo) 
            FROM #Cbtes_TotCli D 
                LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente	
                JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente 
                JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
            WHERE D.Saldo < 0)

       SET @Sql = ' SELECT K.Id_Cliente,K.Razon_Social,D.Saldo,K.Ult_Cuota_Paga
            ,U.UCP_A_Fecha,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono
			,K.Fecha_Alta,K.Fecha_Baja,' + CAST(@Deuda_Total AS char(20)) + ' As Deuda_Total
            FROM #Cbtes_TotCli D 
                LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente	
                JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente AND (@pClientes_activos = 0 OR K.Activo = 1) 
                JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
            WHERE D.Saldo < 0'
         --   ORDER BY Razon_Social
    END
    ELSE
    BEGIN -- TOTAL
	    SET @Deuda_Total = (SELECT SUM(Saldo) 
            FROM #Cbtes_TotCli D
                LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente			
                JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente  AND (@pClientes_activos = 0 OR K.Activo = 1)
                JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli )

        SET @Sql = 'SELECT K.Id_Cliente,K.Razon_Social,D.Saldo,K.Ult_Cuota_Paga
            ,U.UCP_A_Fecha,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo
			,K.Telefono,K.Fecha_Alta,K.Fecha_Baja,' + CAST(@Deuda_Total AS char(20)) + ' As Deuda_Total
            FROM #Cbtes_TotCli D
                LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente			
                JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente  AND (@pClientes_activos = 0 OR K.Activo = 1)
                JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli'
          --  ORDER BY Razon_Social 
    END
	IF @pOrden = 'ID'
	   SET @SQL = @SQL + ' ORDER BY D.Saldo DESC '
	ELSE
	   SET @SQL = @SQL + ' ORDER BY Razon_Social ' 

    PRINT @SQL

    EXEC(@SQL)

	IF(@pModoDebug = 1)
	BEGIN
		SET @TOTAL_PRINT = (SELECT SUM(SALDO) FROM #Cbtes_TotCli)
		PRINT 'TOTAL = ' +CONVERT(VARCHAR(100), @TOTAL_PRINT)  
	END
END

----------------------------------------------------------------------------------------
IF @pCriterio = 'P' OR @pCriterio = 'TP' OR @pCriterio = 'CC' OR @pCriterio = 'CX'
BEGIN

    -- 1. Descuentos por comprobante (solo afectan items, nunca IVA ni percepciones)
    SELECT C.Id_Trans,
           ISNULL(C.Imp_Bonificacion, 0) 
         + ISNULL(C.Imp_DescEspecial, 0) 
         + ISNULL(C.Imp_DescFin, 0)       AS Total_Descuentos
    INTO #Desc_Cbte
    FROM Cbtes C
    JOIN #Deuda_Clientes_A_Fecha D ON D.Id_Trans = C.Id_Trans

    CREATE INDEX IX_Desc_IdTrans ON #Desc_Cbte (Id_Trans)


    -- 2. Base imponible por comprobante
    SELECT I.Id_Trans,
           SUM(ISNULL(Imp_Gravado, 0)) AS Base_Gravada
    INTO #Base_Cbte
    FROM Cbtes_Items I
	JOIN #Deuda_Clientes_A_Fecha D ON D.Id_Trans = I.Id_Trans
    GROUP BY I.Id_Trans

    CREATE INDEX IX_Base_IdTrans ON #Base_Cbte (Id_Trans)

    -- 3. IVA por comprobante
    SELECT I.Id_Trans, SUM(ISNULL(I.Imp_Gravado, 0) * ISNULL(I.Porc_Iva, 0) / 100.0) AS Total_IVA
    INTO #IVA_Cbte
    FROM Cbtes_Items I
	JOIN #Deuda_Clientes_A_Fecha D ON D.Id_Trans = I.Id_Trans
    GROUP BY I.Id_Trans

    CREATE INDEX IX_IVA_IdTrans ON #IVA_Cbte (Id_Trans)


    -- 4. Percepciones por comprobante
    SELECT R.Id_Trans,
           SUM(ISNULL(R.Importe, 0)) AS Total_Percepcion
    INTO #Percep_Cbte
    FROM Cbtes_Reten R
    JOIN Cbtes_Reten_Tipos RT ON RT.Id_Tipo_Reten = R.Id_Tipo_Reten
                              AND RT.Tipo = 'P'
	JOIN #Deuda_Clientes_A_Fecha D ON D.Id_Trans = R.Id_Trans
    GROUP BY R.Id_Trans

    CREATE INDEX IX_Percep_IdTrans ON #Percep_Cbte (Id_Trans)


    -- 5. CUBO de informacion
    CREATE TABLE #DET (
        Id_Cliente           INT,
        Razon_Social         VARCHAR(200),
        Fecha                DATETIME,
        Fecha_Venc           DATETIME,
        Descripcion          VARCHAR(500),
        Moneda               VARCHAR(20),
        Id_Trans             INT,
        Id_Producto          VARCHAR(20),
        Descripcion_Producto VARCHAR(200),
        SIGNO                SMALLINT,
        Imp_Gravado_Bruto    DECIMAL(18,2),
        Desc_Ratio           DECIMAL(18,6),
        Imp_Item_Neto        DECIMAL(18,2),
        Coef_Pendiente       DECIMAL(18,6),
        Saldo_Item           DECIMAL(18,2),
        Imp_Fac              DECIMAL(18,2),
        Imp_Apli             DECIMAL(18,2),
        Ult_Cuota_Paga       DATETIME,
        Tipo_Linea           VARCHAR(20)
    )

    INSERT INTO #DET
    SELECT
        D.Id_Cliente,
        K.Razon_Social,
        D.Fecha,
        C.Fecha_Venc,
        DBO.CF_Cbte_Descrip(D.Id_Trans)				AS Descripcion,
        C.Id_Moneda									AS Moneda,
        I.Id_Trans,
        I.Id_Producto,
        I.Descripcion_Producto,
        D.SIGNO,
        I.Imp_Gravado								AS Imp_Gravado_Bruto,
        CASE 
            WHEN ISNULL(B.Base_Gravada, 0) = 0 THEN 0
            ELSE ISNULL(DC.Total_Descuentos, 0) / B.Base_Gravada
        END											AS Desc_Ratio,
        I.Imp_Gravado 
				* (1.0 - CASE 
							WHEN ISNULL(B.Base_Gravada, 0) = 0 THEN 0
							ELSE ISNULL(DC.Total_Descuentos, 0) / B.Base_Gravada
						 END)								AS Imp_Item_Neto,
        D.COEFICIENTE,
				--CASE 
				--	WHEN ISNULL(D.IMP_TOTAL, 0) = 0 THEN 1
				--	ELSE ABS(ISNULL(D.IMP_TOTAL, 0) 
				--			 - ISNULL(D.Imp_Aplicado, 0) 
				--			 - ABS(ISNULL(D.Imp_Aplicado2, 0))) 
				--		 / ABS(D.IMP_TOTAL)
				--END											AS Coef_Pendiente,
        I.Imp_Gravado 
				* (1.0 - CASE 
							WHEN ISNULL(B.Base_Gravada, 0) = 0 THEN 0
							ELSE ISNULL(DC.Total_Descuentos, 0) / B.Base_Gravada
						 END)
                * D.COEFICIENTE
				--* CASE 
				--	WHEN ISNULL(D.IMP_TOTAL, 0) = 0 THEN 1
				--	ELSE ABS(ISNULL(D.IMP_TOTAL, 0) 
				--			 - ISNULL(D.Imp_Aplicado, 0) 
				--			 - ABS(ISNULL(D.Imp_Aplicado2, 0))) 
				--		 / ABS(D.IMP_TOTAL)
				--  END
				* D.SIGNO									AS Saldo_Item,
        ISNULL(D.IMP_TOTAL, 0) * D.SIGNO			AS Imp_Fac,
        ISNULL(D.Imp_Aplicado 
             + ABS(D.Imp_Aplicado2), 0) 
        * D.SIGNO									AS Imp_Apli,
        K.Ult_Cuota_Paga,
        'ITEM'										AS Tipo_Linea
    FROM #Deuda_Clientes_A_Fecha D
    JOIN Clientes K            ON K.Id_Cliente  = D.Id_Cliente AND (@pClientes_activos = 0 OR K.Activo = 1)
    JOIN Cbtes C               ON C.Id_Trans    = D.Id_Trans
    JOIN Cbtes_Tipos T         ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
    JOIN Cbtes_Items I         ON I.Id_Trans    = D.Id_Trans
    LEFT JOIN #Base_Cbte B     ON B.Id_Trans    = D.Id_Trans
    LEFT JOIN #Desc_Cbte DC    ON DC.Id_Trans   = D.Id_Trans
    WHERE ISNULL(D.IMP_TOTAL, 0) - ISNULL(D.Imp_Aplicado + ABS(D.Imp_Aplicado2), 0) * D.SIGNO <> 0
      AND T.Compromete_Factura IN (1, -1)
	  AND T.Compromete_Recibos NOT IN (1, -1)
      AND D.IMP_TOTAL <> 0


    -- 6. IVA como linea  (no recibe descuento, si recibe coef)
    INSERT INTO #DET
    SELECT
        D.Id_Cliente,
        K.Razon_Social,
        D.Fecha,
        C.Fecha_Venc,
        DBO.CF_Cbte_Descrip(D.Id_Trans)     AS Descripcion,
        C.Id_Moneda,
        D.Id_Trans,
        'IVA'                                AS Id_Producto,
        'IVA'                                AS Descripcion_Producto,
        D.SIGNO,
        IV.Total_IVA                         AS Imp_Gravado_Bruto,
        0                                    AS Desc_Ratio,
        IV.Total_IVA                         AS Imp_Item_Neto,
        CASE 
            WHEN ISNULL(D.IMP_TOTAL, 0) = 0 THEN 1
            ELSE ABS(ISNULL(D.IMP_TOTAL, 0) 
                     - ISNULL(D.Imp_Aplicado, 0) 
                     - ABS(ISNULL(D.Imp_Aplicado2, 0))) 
                 / ABS(D.IMP_TOTAL)
        END                                  AS Coef_Pendiente,
        IV.Total_IVA
        * CASE 
            WHEN ISNULL(D.IMP_TOTAL, 0) = 0 THEN 1
            ELSE ABS(ISNULL(D.IMP_TOTAL, 0) 
                     - ISNULL(D.Imp_Aplicado, 0) 
                     - ABS(ISNULL(D.Imp_Aplicado2, 0))) 
                 / ABS(D.IMP_TOTAL)
          END
        * D.SIGNO                            AS Saldo_Item,
        ISNULL(D.IMP_TOTAL, 0) * D.SIGNO    AS Imp_Fac,
        ISNULL(D.Imp_Aplicado 
             + ABS(D.Imp_Aplicado2), 0) 
        * D.SIGNO                            AS Imp_Apli,
        K.Ult_Cuota_Paga,
        'IVA'                                AS Tipo_Linea
    FROM #Deuda_Clientes_A_Fecha D
    JOIN Clientes K            ON K.Id_Cliente  = D.Id_Cliente AND (@pClientes_activos = 0 OR K.Activo = 1)
    JOIN Cbtes C               ON C.Id_Trans    = D.Id_Trans
    JOIN Cbtes_Tipos T         ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
    JOIN #IVA_Cbte IV          ON IV.Id_Trans   = D.Id_Trans
    WHERE ISNULL(D.IMP_TOTAL, 0) - ISNULL(D.Imp_Aplicado + ABS(D.Imp_Aplicado2), 0) * D.SIGNO <> 0
      AND T.Compromete_Factura IN (1, -1)
	  AND T.Compromete_Recibos NOT IN (1, -1)
      AND D.IMP_TOTAL <> 0
      AND IV.Total_IVA <> 0


    -- 7. Percepciones como linea 
    INSERT INTO #DET
    SELECT
        D.Id_Cliente,
        K.Razon_Social,
        D.Fecha,
        C.Fecha_Venc,
        DBO.CF_Cbte_Descrip(D.Id_Trans)     AS Descripcion,
        C.Id_Moneda,
        D.Id_Trans,
        'PERCEPCION'                         AS Id_Producto,
        'PERCEPCION'                         AS Descripcion_Producto,
        D.SIGNO,
        P.Total_Percepcion                   AS Imp_Gravado_Bruto,
        0                                    AS Desc_Ratio,
        P.Total_Percepcion                   AS Imp_Item_Neto,
        CASE 
            WHEN ISNULL(D.IMP_TOTAL, 0) = 0 THEN 1
            ELSE ABS(ISNULL(D.IMP_TOTAL, 0) 
                     - ISNULL(D.Imp_Aplicado, 0) 
                     - ABS(ISNULL(D.Imp_Aplicado2, 0))) 
                 / ABS(D.IMP_TOTAL)
        END                                  AS Coef_Pendiente,
        P.Total_Percepcion
        * CASE 
            WHEN ISNULL(D.IMP_TOTAL, 0) = 0 THEN 1
            ELSE ABS(ISNULL(D.IMP_TOTAL, 0) 
                     - ISNULL(D.Imp_Aplicado, 0) 
                     - ABS(ISNULL(D.Imp_Aplicado2, 0))) 
                 / ABS(D.IMP_TOTAL)
          END
        * D.SIGNO                            AS Saldo_Item,
        ISNULL(D.IMP_TOTAL, 0) * D.SIGNO    AS Imp_Fac,
        ISNULL(D.Imp_Aplicado 
             + ABS(D.Imp_Aplicado2), 0) 
        * D.SIGNO                            AS Imp_Apli,
        K.Ult_Cuota_Paga,
        'PERCEPCION'                         AS Tipo_Linea
    FROM #Deuda_Clientes_A_Fecha D
    JOIN Clientes K            ON K.Id_Cliente  = D.Id_Cliente AND (@pClientes_activos = 0 OR K.Activo = 1)
    JOIN Cbtes C               ON C.Id_Trans    = D.Id_Trans
    JOIN Cbtes_Tipos T         ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
    JOIN #Percep_Cbte P        ON P.Id_Trans    = D.Id_Trans
    WHERE ISNULL(D.IMP_TOTAL, 0) - ISNULL(D.Imp_Aplicado + ABS(D.Imp_Aplicado2), 0) * D.SIGNO <> 0
      AND T.Compromete_Factura IN (1, -1)
	  AND T.Compromete_Recibos NOT IN (1, -1)
      AND D.IMP_TOTAL <> 0
      AND P.Total_Percepcion <> 0



INSERT INTO #DET
    SELECT
        D.Id_Cliente,
        K.Razon_Social,
        D.Fecha,
        C.Fecha_Venc,
        DBO.CF_Cbte_Descrip(D.Id_Trans)     AS Descripcion,
        C.Id_Moneda,
        C.Id_Trans,
        'ACUENTA'                            AS Id_Producto,
        'PAGOS A CUENTA'                     AS Descripcion_Producto,
        D.SIGNO,
        0                                    AS Imp_Gravado_Bruto,
        0                                    AS Desc_Ratio,
        0                                    AS Imp_Item_Neto,
        0   AS Coef_Pendiente,
		D.SALDO	 AS Saldo_Item,
        D.IMP_TOTAL * D.SIGNO     AS Imp_Fac,
        0    AS Imp_Apli,
        K.Ult_Cuota_Paga,
        'ACUENTA'                            AS Tipo_Linea
    FROM #Deuda_Clientes_A_Fecha D
    JOIN Clientes K            ON K.Id_Cliente  = D.Id_Cliente AND (@pClientes_activos = 0 OR K.Activo = 1)
    JOIN Cbtes C               ON C.Id_Trans    = D.Id_Trans
    JOIN Cbtes_Tipos T         ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
    WHERE D.SALDO <> 0
      AND T.Compromete_Recibos IN (1, -1)

    UPDATE #DET SET Coef_Pendiente = 1 WHERE Coef_Pendiente > 1

IF(@pModoDebug = 2)
BEGIN
	IF OBJECT_ID('dbo.Z_Detalle') IS NOT NULL
		DROP TABLE dbo.Z_Detalle
	SELECT * INTO Z_Detalle FROM  #DET 
END




    IF @pCriterio = 'P'
        SELECT D.*, U.UCP_A_Fecha
        FROM #DET D
            LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente
        ORDER BY Razon_Social, Tipo_Linea, Descripcion_Producto, Fecha

    IF @pCriterio = 'TP'
        SELECT 
            Id_Producto,
            Descripcion_Producto,
            Tipo_Linea,
            SUM(Saldo_Item) AS Saldo
        FROM #DET
        GROUP BY Id_Producto, Descripcion_Producto, Tipo_Linea
        ORDER BY Tipo_Linea, Descripcion_Producto

    IF @pCriterio = 'CC'
        SELECT D.*, U.UCP_A_Fecha
        FROM #DET D
            LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente
        WHERE Coef_Pendiente > 1
        ORDER BY Razon_Social, Descripcion_Producto, Fecha

    IF @pCriterio = 'CX'
    BEGIN
        SELECT F.*, DC.Saldo
        FROM #Deuda_Clientes_A_Fecha F
        JOIN #Cbtes_TotCli DC ON DC.Id_Cliente = F.Id_Cliente
        WHERE F.SALDO <> DC.Saldo
    END

    DROP TABLE #DET
    DROP TABLE #Desc_Cbte
    DROP TABLE #Base_Cbte
    DROP TABLE #IVA_Cbte
    DROP TABLE #Percep_Cbte

END

DROP TABLE #UCP
DROP TABLE #Unid_Negocios
 

