/*Variables Locales*/
DECLARE @Id_Cliente		INT
/*FIN Variables Locales*/

BEGIN TRY
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Clientes_Insertar'
		PRINT 'Parametros: '+ @pJson  
	END

	/*===================================================================*/

	IF(@pDoc_Nro = 0 AND @pCuit = '')
	BEGIN
		RAISERROR ('Parameters "Doc_Nro" or "Cuit" mandatory', 16,  1)
	END

	/*===================================================================*/
	
	IF(@pCuit <> '')
	BEGIN
		SET @Id_Cliente = ISNULL((SELECT TOP 1 ISNULL(Id_Cliente, 0) FROM Clientes WHERE LTRIM(RTRIM(Cuit)) = LTRIM(RTRIM(@pCuit)) ORDER BY Activo DESC, Id_Cliente DESC), 0)
	END

	IF(@Id_Cliente = 0 AND @pDoc_Nro <> 0)
	BEGIN
		SET @Id_Cliente = ISNULL((SELECT TOP 1 ISNULL(Id_Cliente, 0) FROM Clientes WHERE Doc_Nro = @pDoc_Nro ORDER BY Activo DESC, Id_Cliente DESC), 0)
	END

	/*===================================================================*/

	IF(@Id_Cliente = 0)
	BEGIN
		SET @Id_Cliente = ISNULL((SELECT MAX(Id_Cliente) + 1 FROM Clientes), 1)

		INSERT INTO Clientes
		(Id_Cliente,				Razon_Social,				Apellido,
		Nombre,						Sexo,						Fecha_Nac,
		Id_Tipo_Doc,				Doc_Nro,					Ingresos_Brutos,
		Direccion,					Cp,							Id_Pais,
		Id_Provincia,				Provincia_Descrip,			Id_Localidad,
		Localidad_Descrip,			Fax,						Cuit,
		Email,Activo,				Id_Estado_Cliente,			Id_Grupo_Afinidad,
		Porc_DescEspecial,			Id_Lista_Precio,			Id_Vendedor,
		Id_Transportista,			Bonif,						Id_Cond_Pago,
		Cred_CtaCte,				Cred_ChePro,Cred_CheTer,	Id_Iva,
		CTE,						Id_Concepto,				Id_Cta_Banco,
		Id_Zona,					Observacion,				Id_Cliente_Externo,
		Id_Transporte,				Id_Alias_Cta_Cont_Venta,	Mercado,
		Observa_Fact,				Entre_Calle_1,				Entre_Calle_2,
		Plano_Nro,					Plano_Matriz,				Id_Cobrador,
		Id_Motivo_Est,				Id_Tipo_Cli,				Id_Dep_Fisico,
		Id_Dep_Logico,				Id_Tarjeta,					Id_Banco,
		Tar_Nro,					Tar_Fecha_Vence,			Tar_Titular,
		Direccion_Cob,				Cp_Cob,						Id_Pais_Cob,
		Id_Provincia_Cob,			Provincia_Descrip_Cob,		Id_Localidad_Cob,
		Localidad_Descrip_Cob,		Entre_Calle_1_Cob,			Entre_Calle_2_Cob,
		Plano_Nro_Cob,				Plano_Matriz_Cob,			Fecha_Ven_Trib,
		Web,						Id_Cliente_Ref,				Fecha_Alta,
		Fecha_Baja,					Id_Centro_Costo,			Id_Promotor,
		Nombre_Fantasia,			Id_Cond_Vta,				Id_Puerto,
		Id_Calle,					Nro,						Depto,
		Fecha_Modif,				Foto,						Latitud,
		Longitud,					Id_Calle_Cob,				Nro_Cob,
		Depto_Cob,					Latitud_Cob,				Longitud_Cob,
		Id_Precio_Especial,			Cod_Autoriz_Trib,			Id_Alias_Cta_Cont_Venta_Dol,
		Estado_Civil,				Id_Nacionalidad,			Id_Cli_Relac,
		Tipo_Persona,				telefono,					Calle_Descrip,
		Calle_Cob_Descrip,			Imp_Aporte,					Fecha_Aporte,
		Credencial_Nro,				Credencial_Banda1,			Credencial_Banda2,
		Credencial_Imp,				Ult_Cuota_Paga,				Legajo,
		Credencial_Entrega,			Id_Unid_Negocio,			Clave_Web,
		Flag_Anmat,					Nro_Anmat,					Tar_Cuit,
		Id_Anmat,					Coef_Comi_Vta,				Coef_Comi_Cobros,
		Email_Cob,					Recorrido_Cob,				Tar_Fecha_Alta,
		Tar_Fecha_Baja,				Imp_Fac_Max_Mes,			Email_Web,
		Tel_Movil,					Flag_Tel_Movil_Verif,		Flag_Comunic_Sms,
		Flag_Comunic_Email,			Carpeta,					Id_Emp_Area,
		Id_AR_ARBA_COT_Tipo_Dom_Nro,Dir_Entrega_Numero,			Dir_Entrega_Piso,
		Dir_Entrega_Dto,			Dir_Entrega_Barrio,			Dir_Entrega_CP,
		Dir_Entrega_Localidad,		Id_Usuario_Alta)
		VALUES
		(@Id_Cliente,					@pRazon_Social,				@pApellido,
		@pNombre,						@pSexo,						@pFecha_Nac,
		@pId_Tipo_Doc,					@pDoc_Nro,					@pIngresos_Brutos,
		@pDireccion,					@pCp,						@pId_Pais,
		@pId_Provincia,					@pProvincia_Descrip,		@pId_Localidad,
		@pLocalidad_Descrip,			@pFax,						@pCuit,
		@pEmail,@pActivo,				@pId_Estado_Cliente,		@pId_Grupo_Afinidad,
		@pPorc_DescEspecial,			@pId_Lista_Precio,			@pId_Vendedor,
		@pId_Transportista,				@pBonif,					@pId_Cond_Pago,
		@pCred_CtaCte,					@pCred_ChePro,@pCred_CheTer,@pId_Iva,
		@pCTE,							@pId_Concepto,				@pId_Cta_Banco,
		@pId_Zona,						@pObservacion,				@pId_Cliente_Externo,
		@pId_Transporte,				@pId_Alias_Cta_Cont_Venta,	@pMercado,
		@pObserva_Fact,					@pEntre_Calle_1,			@pEntre_Calle_2,
		@pPlano_Nro,					@pPlano_Matriz,				@pId_Cobrador,
		@pId_Motivo_Est,				@pId_Tipo_Cli,				@pId_Dep_Fisico,
		@pId_Dep_Logico,				@pId_Tarjeta,				@pId_Banco,
		@pTar_Nro,						@pTar_Fecha_Vence,			@pTar_Titular,
		@pDireccion_Cob,				@pCp_Cob,					@pId_Pais_Cob,
		@pId_Provincia_Cob,				@pProvincia_Descrip_Cob,	@pId_Localidad_Cob,
		@pLocalidad_Descrip_Cob,		@pEntre_Calle_1_Cob,		@pEntre_Calle_2_Cob,
		@pPlano_Nro_Cob,				@pPlano_Matriz_Cob,			@pFecha_Ven_Trib,
		@pWeb,							@pId_Cliente_Ref,			@pFecha_Alta,
		@pFecha_Baja,					@pId_Centro_Costo,			@pId_Promotor,
		@pNombre_Fantasia,				@pId_Cond_Vta,				@pId_Puerto,
		@pId_Calle,						@pNro,						@pDepto,
		@pFecha_Modif,					@pFoto,						@pLatitud,
		@pLongitud,						@pId_Calle_Cob,				@pNro_Cob,
		@pDepto_Cob,					@pLatitud_Cob,				@pLongitud_Cob,
		@pId_Precio_Especial,			@pCod_Autoriz_Trib,			@pId_Alias_Cta_Cont_Venta_Dol,
		@pEstado_Civil,					@pId_Nacionalidad,			@pId_Cli_Relac,
		@pTipo_Persona,					@ptelefono,					@pCalle_Descrip,
		@pCalle_Cob_Descrip,			@pImp_Aporte,				@pFecha_Aporte,
		@pCredencial_Nro,				@pCredencial_Banda1,		@pCredencial_Banda2,
		@pCredencial_Imp,				@pUlt_Cuota_Paga,			@pLegajo,
		@pCredencial_Entrega,			@pId_Unid_Negocio,			@pClave_Web,
		@pFlag_Anmat,					@pNro_Anmat,				@pTar_Cuit,
		@pId_Anmat,						@pCoef_Comi_Vta,			@pCoef_Comi_Cobros,
		@pEmail_Cob,					@pRecorrido_Cob,			@pTar_Fecha_Alta,
		@pTar_Fecha_Baja,				@pImp_Fac_Max_Mes,			@pEmail_Web,
		@pTel_Movil,					@pFlag_Tel_Movil_Verif,		@pFlag_Comunic_Sms,
		@pFlag_Comunic_Email,			@pCarpeta,					@pId_Emp_Area,
		@pId_AR_ARBA_COT_Tipo_Dom_Nro,	@pDir_Entrega_Numero,		@pDir_Entrega_Piso,
		@pDir_Entrega_Dto,				@pDir_Entrega_Barrio,		@pDir_Entrega_CP,
		@pDir_Entrega_Localidad,		@pId_Usuario_Alta)
	END
	ELSE
	BEGIN
		IF(@pDireccion <> '')
		BEGIN
			UPDATE Clientes
			SET
			Direccion = @pDireccion,
			Cp = @pCp,
			Localidad_Descrip = @pLocalidad_Descrip,
			Provincia_Descrip = @pProvincia_Descrip
			WHERE
			Id_Cliente = @Id_Cliente
		END
	END
	/*===================================================================*/

	IF @pFlagUsarTrans <> 0 COMMIT

	SELECT	 0							AS ErrorNumber 
			,0							AS ErrorSeverity  
			,0							AS ErrorState 
			,0							AS ErrorProcedure  
			,@Id_Cliente				AS ErrorLine		
			,''							AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Clientes_Insertar'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  ROLLBACK

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Clientes_Localidad] (@pJson VARCHAR(8000)) 
AS 
SET NOCOUNT ON 

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Pais				CHAR (3)
/*FIN Variables recibidas por parametro a traves del JSON*/

	SET @pId_Pais			= ISNULL(CONVERT(CHAR, dbo.CF_JSON_VALUE(@pJson,'Id_Pais')), '')
	SET @pFlagUsarTrans		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
	SET @pModoDebug			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)


DECLARE @Descripcion_Pais	VARCHAR (30)
DECLARE @Id_Provincia		CHAR (3)
DECLARE @Id_Localidad		INT
DECLARE @Json_Rta			NVARCHAR(MAX)

	SET @Descripcion_Pais	= ISNULL((SELECT Descripcion FROM Tab_Paises WHERE Id_Pais = @pId_Pais),'')
	SET @Id_Provincia		= ISNULL((SELECT MAX(Id_Provincia) FROM Tab_Provincias WHERE Id_Pais = @pId_Pais),'')-- alfanumerica
	SET @Id_Localidad		= ISNULL((SELECT MAX(Id_Localidad) FROM Tab_Localidades WHERE Id_Pais = @pId_Pais AND Id_Provincia=@Id_Provincia),0)--numerica


	IF (@Id_Provincia='')
	BEGIN
		SET @Id_Provincia		= ISNULL((SELECT Id_Pais FROM Tab_Paises WHERE Id_Pais = @pId_Pais),'')-- alfanumerica
		PRINT 'Provincia Vacia'

		INSERT INTO Tab_Provincias (Id_Provincia,	Descripcion,		Id_Pais)
							VALUES (@pId_Pais,		@Descripcion_Pais,  @pId_Pais)
		PRINT 'Se inserta en Tab_Provincias'
	END

	IF (@Id_Localidad=0)
	BEGIN

		SET @Id_Localidad		= ISNULL((SELECT MAX(Id_Localidad) FROM Tab_Localidades WHERE Id_Pais = @pId_Pais),0)--numerica
	
			IF (@Id_Localidad = 0) 
			BEGIN
			
				SET @Id_Localidad		= (SELECT MAX(Id_Localidad) FROM Tab_Localidades) 
				SET @Id_Localidad		= @Id_Localidad +1
				PRINT 'Localidad Vacia'
				INSERT INTO Tab_Localidades (Id_Localidad, Id_Pais,		Descripcion,		Id_Provincia)
									 VALUES (@Id_Localidad, @pId_Pais,	@Descripcion_Pais,	@Id_Provincia)
				PRINT 'Se inserta en Tab_Localidades'
				
			END	
	END

	SET @Json_Rta='{'
	SET @Json_Rta = @Json_Rta +	dbo.CF_Json_ParsearVariable('Id_Localidad', @Id_Localidad, 'INT') + ','
	SET @Json_Rta = @Json_Rta +	dbo.CF_Json_ParsearVariable('Id_Provincia', @Id_Provincia, 'CHAR (3)') 
	SET @Json_Rta = @Json_Rta + '}'

	SELECT  @Json_Rta as 'Respuesta'
GO


CREATE PROCEDURE [dbo].[CPJ_Clientes_Mov] @pJsonRecibido VARCHAR(8000)	 
AS

DECLARE 	@pFechaDesde			DATETIME,
			@pFechaHasta			DATETIME,
			@pFormato				VARCHAR(10),
			@pId_Tipo_Cli			INT
			 
			
			
SET @pFechaDesde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaDesde')),GETDATE())
SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())			
SET @pFormato					= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Formato')),'D')			
SET @pId_Tipo_Cli				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Tipo_Cli')),0)		


/*Activos anteriores a Fecha Desde*/

SELECT C.Id_Cliente,MAX(Item) Item INTO #Hist_Max_Ant 
	FROM Clientes C, Clientes_Hist H
	WHERE H.Fecha < @pFechaDesde
	AND C.Id_Cliente = H.Id_Cliente
	AND C.Fecha_Alta < @pFechaDesde
	AND ISNULL(C.Fecha_Baja,@pFechaDesde + 1) > @pFechaDesde
	AND ISNULL(H.Id_Tipo_Cli,0) <> 0
	AND ISNULL(Id_Contrato,0) = 0 
	AND C.Id_Cliente NOT IN (0,1)
	GROUP BY C.Id_Cliente

SELECT C.Id_Cliente,MAX(Item) Item INTO #Hist_Max_Rango_Ant 
	FROM Clientes C, Clientes_Hist H
	WHERE H.Fecha < @pFechaHasta
	AND C.Id_Cliente = H.Id_Cliente
	AND C.Fecha_Alta < @pFechaDesde
	AND ISNULL(C.Fecha_Baja,@pFechaHasta + 1) > @pFechaHasta
	AND ISNULL(H.Id_Tipo_Cli,0) <> 0
	AND ISNULL(Id_Contrato,0) = 0 
	AND C.Id_Cliente NOT IN (0,1)
	GROUP BY C.Id_Cliente



SELECT 'Anterior' AS Tipo,C.Id_Cliente,C.Id_Cliente_Externo, C.Fecha_Alta, C.Fecha_Baja, C.Razon_Social,C.Fecha_Nac
       ,Dbo.CF_Edad_Persona_A_UnaFecha(C.Fecha_Nac,@pFechaDesde -1) AS Edad_Inicio
       ,ISNULL( H.Id_Tipo_Cli,C.Id_Tipo_Cli) AS Id_Tipo_Cli ,ISNULL(T.Descripcion,CCTT.Descripcion) AS Categoria_ini,H.Fecha AS Fecha_Mov
       ,HR.Id_Tipo_Cli AS Id_Tipo_Cli_Fin ,TR.Descripcion AS Categoria_Fin,HR.Fecha AS Fecha_Mov_Fin
       ,C.Id_Motivo_Est , E.Descripcion AS Estado, '' AS Motivo_Baja
    INTO #Resultado   
    FROM Clientes C
        LEFT JOIN #Hist_Max_Ant M ON C.Id_Cliente = M.Id_Cliente
        LEFT JOIN Clientes_Hist H ON C.Id_Cliente = H.Id_Cliente AND M.Item = H.Item
        LEFT JOIN Clientes_Tipos T ON H.Id_Tipo_Cli = T.Id_Tipo_Cli
        LEFT JOIN #Hist_Max_Rango_Ant MR ON C.Id_Cliente = MR.Id_Cliente
        LEFT JOIN Clientes_Hist HR ON C.Id_Cliente = HR.Id_Cliente AND MR.Item = HR.Item
        LEFT JOIN Clientes_Tipos TR ON HR.Id_Tipo_Cli = TR.Id_Tipo_Cli
        LEFT JOIN Tab_Motivos_Est E ON E.Id_Motivo_Est = C.Id_Motivo_Est
		, Clientes_Tipos CCTT
    WHERE C.Fecha_Alta < @pFechaDesde
	AND CCTT.Id_Tipo_Cli = C.Id_Tipo_Cli
    AND (C.Fecha_Baja > @pFechaDesde OR C.Fecha_Baja IS NULL)
	AND C.Id_Cliente NOT IN (0,1)

--nuevos socios entre ese rango



SELECT C.Id_Cliente,MIN(Item) Item INTO #Hist_Min_Nuevos
	FROM Clientes C, Clientes_Hist H
	WHERE H.Fecha < @pFechaHasta
	AND C.Id_Cliente = H.Id_Cliente
    AND C.Fecha_Alta >= @pFechaDesde AND C.Fecha_Alta < @pFechaHasta
    AND H.Fecha >= @pFechaDesde AND H.Fecha < @pFechaHasta
    AND (C.Fecha_Baja > @pFechaHasta OR C.Fecha_Baja IS NULL)
	AND ISNULL(H.Id_Tipo_Cli,0) <> 0
	AND ISNULL(Id_Contrato,0) = 0 
	AND C.Id_Cliente NOT IN (0,1)
	GROUP BY C.Id_Cliente


SELECT C.Id_Cliente,MAX(Item) Item INTO #Hist_Max_Nuevos
	FROM Clientes C, Clientes_Hist H
	WHERE H.Fecha < @pFechaHasta
	AND C.Id_Cliente = H.Id_Cliente
    AND C.Fecha_Alta >= @pFechaDesde AND C.Fecha_Alta < @pFechaHasta
    AND H.Fecha >= @pFechaDesde AND H.Fecha < @pFechaHasta
    AND (C.Fecha_Baja > @pFechaHasta OR C.Fecha_Baja IS NULL)
	AND ISNULL(H.Id_Tipo_Cli,0) <> 0
	AND ISNULL(Id_Contrato,0) = 0 
	AND C.Id_Cliente NOT IN (0,1)
	GROUP BY C.Id_Cliente

INSERT INTO #Resultado
SELECT 'Nuevo' AS Tipo,C.Id_Cliente,C.Id_Cliente_Externo, C.Fecha_Alta, C.Fecha_Baja, C.Razon_Social,C.Fecha_Nac
       ,Dbo.CF_Edad_Persona_A_UnaFecha(C.Fecha_Nac,@pFechaDesde -1) AS Edad_Inicio
       ,ISNULL( H.Id_Tipo_Cli,C.Id_Tipo_Cli) AS Id_Tipo_Cli ,ISNULL(T.Descripcion,CCTT.Descripcion) AS Categoria_ini,H.Fecha AS Fecha_Mov
       ,HR.Id_Tipo_Cli AS Id_Tipo_Cli_Fin ,TR.Descripcion AS Categoria_Fin,HR.Fecha AS Fecha_Mov_Fin
       ,C.Id_Motivo_Est , E.Descripcion AS Estado, '' AS Motivo_Baja 
    FROM Clientes C
				LEFT JOIN #Hist_Min_Nuevos M ON C.Id_Cliente = M.Id_Cliente
				LEFT JOIN Clientes_Hist H ON C.Id_Cliente = H.Id_Cliente AND M.Item = H.Item
				LEFT JOIN Clientes_Tipos T ON H.Id_Tipo_Cli = T.Id_Tipo_Cli
				LEFT JOIN #Hist_Max_Nuevos MR ON C.Id_Cliente = MR.Id_Cliente
				LEFT JOIN Clientes_Hist HR ON C.Id_Cliente = HR.Id_Cliente AND MR.Item = HR.Item
				LEFT JOIN Clientes_Tipos TR ON HR.Id_Tipo_Cli = TR.Id_Tipo_Cli
				LEFT JOIN Tab_Motivos_Est E ON E.Id_Motivo_Est = C.Id_Motivo_Est
		, Clientes_Tipos CCTT
    WHERE C.Fecha_Alta >= @pFechaDesde AND C.Fecha_Alta < @pFechaHasta
	AND CCTT.Id_Tipo_Cli = C.Id_Tipo_Cli
    AND (C.Fecha_Baja > @pFechaHasta OR C.Fecha_Baja IS NULL)
	AND C.Id_Cliente NOT IN (0,1)



	
			

UPDATE #Resultado SET Id_Tipo_Cli_Fin = Id_Tipo_Cli, Categoria_Fin = Categoria_ini WHERE Id_Tipo_Cli_Fin IS NULL

UPDATE #Resultado SET Fecha_Baja = NULL WHERE Fecha_Baja > @pFechaHasta


IF @pId_Tipo_Cli <> 0
	DELETE #Resultado WHERE Id_Tipo_Cli <> @pId_Tipo_Cli

IF UPPER(@pFormato) = 'C'
BEGIN
	CREATE TABLE #categ  (
			Id_Tipo_Cli INT,
			Categoria VARCHAR(100) , 
			SA DECIMAL(16,4) DEFAULT(0),
			Altas INT DEFAULT(0), 
			Bajas INT DEFAULT(0), 
			Altas_Pasaje INT DEFAULT(0), 
			Bajas_Pasaje INT DEFAULT(0), 
			SF DECIMAL(16,4) DEFAULT(0),
			Porc DECIMAL(12,2) DEFAULT(0)
			)
	
	INSERT INTO #categ (Id_Tipo_Cli,Categoria)
    SELECT Id_Tipo_Cli,Categoria_ini AS Categoria FROM #Resultado GROUP BY Id_Tipo_Cli,Categoria_ini
    UNION 
    SELECT Id_Tipo_Cli_Fin AS Id_Tipo_Cli,Categoria_Fin AS Categoria FROM #Resultado GROUP BY Id_Tipo_Cli_Fin,Categoria_Fin
    
    SELECT Id_Tipo_Cli,Categoria_ini,COUNT(*) AS Cant INTO #Categ_G FROM #Resultado WHERE Tipo = 'Anterior' GROUP BY Id_Tipo_Cli,Categoria_ini
    
    UPDATE #categ SET SA = Cant
       FROM #categ c ,#Categ_G r
       WHERE c.Categoria COLLATE Modern_Spanish_CI_AS = r.Categoria_ini COLLATE Modern_Spanish_CI_AS

    SELECT Id_Tipo_Cli,Categoria_ini,COUNT(*) AS Cant INTO #Categ_N FROM #Resultado WHERE Tipo = 'Nuevo' GROUP BY Id_Tipo_Cli,Categoria_ini

    UPDATE #categ SET Altas = Cant
       FROM #categ c ,#Categ_N R
       WHERE c.Categoria COLLATE Modern_Spanish_CI_AS = r.Categoria_ini COLLATE Modern_Spanish_CI_AS

    SELECT Id_Tipo_Cli,Categoria_ini,COUNT(*) AS Cant INTO #Categ_B FROM #Resultado WHERE Fecha_Baja IS NOT NULL GROUP BY Id_Tipo_Cli,Categoria_ini

    UPDATE #categ SET Bajas = Cant
       FROM #categ c ,#Categ_B R
       WHERE c.Categoria COLLATE Modern_Spanish_CI_AS = r.Categoria_ini COLLATE Modern_Spanish_CI_AS

    SELECT Categoria_Fin,COUNT(*) AS Cant INTO #Categ_AP FROM #Resultado 
			WHERE Fecha_Baja IS NULL AND Categoria_ini COLLATE Modern_Spanish_CI_AS <> Categoria_Fin COLLATE Modern_Spanish_CI_AS 
			GROUP BY Categoria_Fin

    UPDATE #categ SET Altas_Pasaje = Cant
       FROM #categ c ,#Categ_AP R
       WHERE c.Categoria COLLATE Modern_Spanish_CI_AS = r.Categoria_Fin COLLATE Modern_Spanish_CI_AS


    SELECT Categoria_ini,COUNT(*) AS Cant INTO #Categ_BP FROM #Resultado 
			WHERE Fecha_Baja IS NULL AND Categoria_ini COLLATE Modern_Spanish_CI_AS <> Categoria_Fin COLLATE Modern_Spanish_CI_AS 
			GROUP BY Categoria_ini
     --SELECT * FROM #Categ_BP			

    UPDATE #categ SET Bajas_Pasaje = Cant
       FROM #categ c ,#Categ_BP R
       WHERE c.Categoria COLLATE Modern_Spanish_CI_AS = r.Categoria_Ini COLLATE Modern_Spanish_CI_AS

    UPDATE #Categ SET SF = SA + Altas - Bajas + Altas_Pasaje - Bajas_Pasaje
    UPDATE #categ SET Porc = ((SF / SA) - 1) * 100 WHERE SA <> 0

    SELECT Id_Tipo_Cli,Categoria ,
			CONVERT(INT,SA) AS Saldo_Ant,
			Altas ,
			Bajas ,
			Altas_Pasaje ,
			Bajas_Pasaje ,
			CONVERT(INT,SF) Saldo_Final,
			Porc 
		 FROM #Categ   
    WHERE Categoria IS NOT NULL
    ORDER BY Categoria 
       
	
END
ELSE IF  UPPER(@pFormato) = 'CM'
BEGIN
    SELECT Categoria_ini AS Categoria,Estado, COUNT(*) AS Cantidad FROM #Resultado 
			WHERE Fecha_Baja IS NOT NULL 
			GROUP BY Categoria_Ini,Estado
			ORDER BY Categoria_Ini,Estado


END -- Se agrega formatos faltantes: 04/05/2026 por Maca R
ELSE IF UPPER(@pFormato) = 'DA'
BEGIN
    SELECT 
        Tipo,
        Id_Cliente,
        Id_Cliente_Externo,
        Fecha_Alta,
        Razon_Social,
        Fecha_Baja,
        Fecha_Nac,
        Edad_Inicio,
        Categoria_ini,
        Categoria_Fin,
        CASE 
            WHEN Tipo = 'Nuevo' THEN 'ALTA'
            WHEN Fecha_Baja IS NOT NULL THEN 'BAJA'
            WHEN Categoria_ini <> Categoria_Fin THEN 'CAMBIO DE CATEGORIA'
        END AS  Estado
    FROM #Resultado
    WHERE Tipo = 'Nuevo'
    ORDER BY Fecha_Alta
END
ELSE IF UPPER(@pFormato) = 'DB'
BEGIN
    SELECT 
        Tipo,
        Id_Cliente,
        Id_Cliente_Externo,
        Fecha_Alta,
        Razon_Social,
        Fecha_Baja,
        Fecha_Nac,
        Edad_Inicio,
        Categoria_ini,
        Categoria_Fin,
        CASE 
            WHEN Tipo = 'Nuevo' THEN ''
            WHEN Fecha_Baja IS NOT NULL THEN Estado
            WHEN Categoria_ini <> Categoria_Fin THEN ''
        END AS  Motivo_Baja,
        CASE 
            WHEN Tipo = 'Nuevo' THEN 'ALTA'
            WHEN Fecha_Baja IS NOT NULL THEN 'BAJA'
            WHEN Categoria_ini <> Categoria_Fin THEN 'CAMBIO DE CATEGORIA'
        END AS  Estado
    FROM #Resultado
    WHERE Fecha_Baja IS NOT NULL
    ORDER BY Fecha_Baja
END
ELSE
BEGIN
	--SELECT * FROM #Resultado 
	--	ORDER BY Fecha_Alta
	SELECT 
        Tipo,
        Id_Cliente,
        Id_Cliente_Externo,
        Fecha_Alta,
        Razon_Social,
        Fecha_Baja,
        Fecha_Nac,
        Edad_Inicio,
        Categoria_ini,
        Categoria_Fin,
        CASE 
            WHEN Tipo = 'Nuevo' THEN ''
            WHEN Fecha_Baja IS NOT NULL THEN Estado
            WHEN Categoria_ini <> Categoria_Fin THEN ''
        END AS Motivo_Baja,
        CASE 
            WHEN Tipo = 'Nuevo' THEN 'ALTA'
            WHEN Fecha_Baja IS NOT NULL THEN 'BAJA'
            WHEN Categoria_ini <> Categoria_Fin THEN 'CAMBIO DE CATEGORIA'
        END AS  Estado
    FROM #Resultado
    WHERE 
        Tipo = 'Nuevo'
        OR Fecha_Baja IS NOT NULL
        OR Categoria_ini <> Categoria_Fin
    ORDER BY Categoria_ini, Fecha_Mov_Fin
END



/*

EXEC CPJ_Clientes_Mov '{"FechaDesde":"20260401","FechaHasta":"20260430","Formato":"DT"}'
EXEC CPJ_Clientes_Mov '{"FechaDesde":"20260401","FechaHasta":"20260430","Formato":"DA"}'
EXEC CPJ_Clientes_Mov '{"FechaDesde":"20260401","FechaHasta":"20260430","Formato":"DB"}'

EXEC CPJ_Clientes_Mov '{"FechaDesde":"20210701","FechaHasta":"20220630","Formato":"CM"}'
EXEC CPJ_Clientes_Mov '{"Id_Usuario":"-1","FechaDesde":"20220401","FechaHasta":"20220502","Formato":"D","Id_Tipo_Cli":"42"}' 
EXEC CPJ_Clientes_Mov '{"Id_Usuario":"-1","FechaDesde":"20220601","FechaHasta":"20220801","Formato":"C","id_tipo_cli":"1"}' 

*/
