GO


CREATE PROCEDURE [dbo].[CPJ_Clientes_ResumenCta_Detalle] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON
/*Parametros*/

DECLARE 	@pFechaDesde			DATETIME,
			@pFechaHasta			DATETIME,
			@pId_Unid_Negocio       VARCHAR(10),
			@pFiltrar_con_saldo     TINYINT,
			@pClientes_activos      TINYINT,
            @pId_Cliente            INT

SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
SET @pFechaDesde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaDesde')),GETDATE())
SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())
SET @pFiltrar_con_saldo			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Filtrar_con_saldo')),0)
SET @pClientes_activos			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Clientes_activos')),0)
SET @pId_Cliente		    	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')),0)

/*Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Trans_Rec		INT
		,@CursorOpen        INT
		,@Flag_Cbte_Tipo	SMALLINT
		,@Periodo           DATE 
		,@Id_sucursal	    SMALLINT
		,@Venta_Total       DECIMAL(16,2)

					
BEGIN 

    SELECT ID_UNID_NEGOCIO INTO #UN FROM Empresas_Unid_Negocios

    IF CAST(@pId_Unid_Negocio as int) <> 0
       DELETE #UN WHERE ID_UNID_NEGOCIO <> @pId_Unid_Negocio 


	CREATE TABLE #ACTIVO (ACTIVO TINYINT)
    INSERT INTO #ACTIVO (ACTIVO) VALUES (1)

	IF @pClientes_activos <> 1
	  INSERT INTO #ACTIVO (ACTIVO) VALUES (0)


		Select F.Fecha,K.Descripcion,F.Fecha_Venc,F.Id_Trans,F.Id_Moneda,F.Cotizacion,F.IMP_TOTAL*f.cotizacion AS Debe,F.IMP_TOTAL AS Haber,F.IMP_TOTAL AS Saldo
		Into #Resumen_Cta
		 from Cbtes_Tipos T, Clientes c, Cbtes F, #UN U, CLIENTES_CTACTE K
		 where C.id_cliente = f.id_cliente
		 AND K.ID_TRANS = F.ID_TRANS
		 AND C.ID_CLIENTE = @pId_Cliente
		 AND T.Id_Unid_Negocio = U.Id_Unid_Negocio
		 and f.id_tipo_cbte = t.id_tipo_cbte
		 and f.Id_Cond_Pago <> 1 and t.Compromete_Factura in (1) 
		 and f.id_estado_cbte not in (0,3)
		 AND F.FECHA >= @pFechaDesde 
	  	 AND F.FECHA < dateadd(dd,1,@pFechaHasta)

 
        UPDATE #Resumen_Cta SET HABER = 0,SALDO = 0

		Select F.FECHA,K.Descripcion,F.Fecha_Venc,F.ID_TRANS,F.ID_MONEDA,F.COTIZACION,0 AS DEBE,F.IMP_TOTAL*f.cotizacion AS HABER,0 AS SALDO
		Into #Resumen_nc
		 from Cbtes_Tipos T, Clientes c, Cbtes F, #UN U, CLIENTES_CTACTE K
		 where C.id_cliente = f.id_cliente
		 AND K.ID_TRANS = F.ID_TRANS
		 AND C.ID_CLIENTE = @pId_Cliente
		 AND T.Id_Unid_Negocio = U.Id_Unid_Negocio
		 and f.id_tipo_cbte = t.id_tipo_cbte
		 and f.Id_Cond_Pago <> 1 and t.Compromete_Factura in (-1) 
		 and f.id_estado_cbte not in (0,3)
		 AND F.FECHA >= @pFechaDesde 
	     AND F.FECHA < dateadd(dd,1,@pFechaHasta)

		Select F.FECHA,K.Descripcion,F.Fecha_Venc,F.ID_TRANS,F.ID_MONEDA,F.COTIZACION,0 AS DEBE,F.IMP_TOTAL*f.cotizacion AS HABER,0 AS SALDO
		Into #Resumen_REC
		 from Cbtes_Tipos T, Clientes c, Cbtes F, #UN U, CLIENTES_CTACTE K
		 where C.id_cliente = f.id_cliente
		 AND K.ID_TRANS = F.ID_TRANS
		 AND C.ID_CLIENTE = @pId_Cliente
		 AND T.Id_Unid_Negocio = U.Id_Unid_Negocio
		 and f.id_tipo_cbte = t.id_tipo_cbte
		 and t.Compromete_Recibos in (1,-1) 
		 and f.id_estado_cbte not in (0,3)
		 AND K.Nro_Cuota = 1
		 AND F.FECHA >= @pFechaDesde 
		 AND F.FECHA < dateadd(dd,1,@pFechaHasta)

        INSERT INTO #Resumen_Cta SELECT * FROM #Resumen_nc
	    INSERT INTO #Resumen_Cta SELECT * FROM #Resumen_Rec
 
		 

		DECLARE @Debe DECIMAL(16,2)
		DECLARE @Haber DECIMAL(16,2)
		DECLARE @Saldo DECIMAL(16,2)

		SET @Saldo = 0
		DECLARE Cur_Saldo CURSOR FOR
			 SELECT Id_Trans,Debe,Haber FROM #Resumen_Cta order by FECHA,ID_TRANS

		OPEN Cur_Saldo 
		FETCH NEXT FROM Cur_Saldo INTO @Id_trans,@debe,@haber
		WHILE @@FETCH_STATUS=0
		BEGIN
			SET @Saldo = @Saldo + @debe - @haber
			UPDATE #Resumen_Cta SET Saldo = @Saldo WHERE Id_trans = @Id_trans
			FETCH NEXT FROM Cur_Saldo INTO @Id_trans,@debe,@haber
		END
		CLOSE Cur_Saldo
		DEALLOCATE Cur_Saldo

		SELECT * FROM #Resumen_Cta ORDER BY FECHA,ID_TRANS


		DROP TABLE #Resumen_Cta
        DROP TABLE #UN
		DROP TABLE #Resumen_nc
		DROP TABLE #ACTIVO
		DROP TABLE #Resumen_Rec
 END

/*

EXEC dbo.CPJ_Clientes_ResumenCta_Detalle   '{
			"FechaDesde":"20210101",
			"FechaHasta":"20210930",
		    "Filtrar_con_saldo":"1",
			"Clientes_activos":"1",
			"Id_Cliente":"52",
			"Id_Unid_Negocio":""
		}'

*/
GO



CREATE PROCEDURE [dbo].[CPJ_Clientes_Visitas] @pJsonRecibido VARCHAR(MAX)
AS
SET NOCOUNT ON

	IF EXISTS ( SELECT * 
            FROM   sysobjects 
            WHERE  id = object_id(N'dbo.CPJ_Clientes_Visitas_') 
                   and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
	BEGIN 
		EXEC CPJ_Clientes_Visitas_ @pJsonRecibido
		RETURN
	END	

	/***************************************************************************************************

	Procedimiento:      CPJ_Clientes_Visitas
	Fecha de Creacion:  2024-10-22
	Creado por:         Adriana Laverde
	Descripcion:        Stored creado para generar invitaciones al club
	Llamado por:        invitados.php (KIOSK, APP)
	Tablas afectadas:   []
	Usado en:           
	Parametro(s):       FlagUsarTrans, ModoDebug, 
	Forma de uso:       EXEC
	Notas adicionales:  Usar CPJ_Clientes_Visitas_ para validaciones particulares

	****************************************************************************************************

	SUMARIO DE CAMBIOS
	FECHA(yyyy-mm-dd)    Autor              Comentarios
	------------------- ------------------- ------------------------------------------------------------
	2025-09-26 se guarda la fecha_hasta de la invitacion en invitaciones individuales
	2026-02-05			Sa├║l				Agrego @pId_Producto @pNo_Operacion @pIgnorar_Invit_Max_Anuales 
											@pSolo_Validar_Invitacion para implementar las invitaciones con costos

              
	***************************************************************************************************/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE	@pFlagUsarTrans				TINYINT,
		@pModoDebug					TINYINT,
		@pApellido					VARCHAR(100),
		@pNombre					VARCHAR(100),
		@pDocumento					VARCHAR(100),
		@pFecha_Invitacion			DATETIME,
		@pCantidad					INT,
        @pEmail						VARCHAR(100),
		@pObservacion				VARCHAR(2000),
		@pId_Invitante				INT,
		@pTipo						TINYINT,
		@pId_Link					INT,
		@pId_Producto				VARCHAR(15), 
		@pNo_Operacion				VARCHAR(100),
		@pIgnorar_Invit_Max_Anuales TINYINT,
		@pIgnorar_Validaciones		TINYINT,
		@pSolo_Validar_Invitacion	TINYINT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)
SET @pApellido					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Apellido')), '')
SET @pNombre					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Nombre')), '')
SET @pDocumento					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Documento')),'')
SET @pFecha_Invitacion			= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Invitacion')),'')
SET @pCantidad					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Cantidad')),'')
SET @pEmail						= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Email')),'')
SET @pObservacion				= ISNULL(CONVERT(VARCHAR(2000), dbo.CF_JSON_VALUE(@pJsonRecibido,'Observacion')),'')
SET @pId_Invitante				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Invitante')),0)
SET @pTipo						= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Tipo')),0)
SET @pId_Link					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Link')),0) -- Para los registros de invitados por link
SET @pId_Producto				= ISNULL(CONVERT(VARCHAR(15), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Producto')),'')
SET @pNo_Operacion				= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Nro_Operacion')),'')

SET @pIgnorar_Invit_Max_Anuales	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido, 'Ignorar_Invit_Max_Anuales')), 0)
SET @pIgnorar_Validaciones		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido, 'Ignorar_Validaciones')), 0)
SET @pSolo_Validar_Invitacion	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido, 'Solo_Validar_Invitacion')), 0)

/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Variables Locales*/
DECLARE @Invitacion_Previa			DATETIME
DECLARE @Existe						INT = 0
DECLARE @Cant_Invitaciones			INT
DECLARE @Categoria					INT
DECLARE @Categoria_Invitado			INT
DECLARE @Cant_Visitas_En_Mes		INT
DECLARE @Primer_Dia_Mes				DATETIME
DECLARE @Primer_Dia_Prox_Mes		DATETIME
DECLARE @Fecha_Libre				DATETIME = 0 --Libre de validaciones 
DECLARE	@URL						VARCHAR(2000)
DECLARE @Token						VARCHAR(250)
DECLARE @Id_Pais					CHAR(3) -- 14/08/2025 Maca Se agrega por las particularidades de los clientes 200, ARG
/*FINVariables Locales*/

BEGIN TRY
	IF (@pFlagUsarTrans <> 0)
	BEGIN
		BEGIN TRAN
	END

	IF (@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Clientes_Visitas'
		PRINT 'Parametros: '+ @pJsonRecibido  
		PRINT ' ---------------------- '
	END

	IF(@pId_Link > 0)
	BEGIN
		SET @pId_Invitante = ISNULL((SELECT Id_Cliente FROM Clientes_Links WHERE Id_Link = @pId_Link),0)
		SET @pFecha_Invitacion = ISNULL((SELECT Fecha_Desde FROM Clientes_Links WHERE Id_Link = @pId_Link),'')
		SET @pId_Producto = ISNULL((SELECT Id_Producto FROM Clientes_Links WHERE Id_Link = @pId_Link), '')
	END
	ELSE
	BEGIN
	 SET @pId_Link = NULL
	END

	IF(@pTipo = 1)
	BEGIN
		-----------------------------------------------------------------------------------------------
		SET	@Existe				= ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Doc_Nro = CAST(@pDocumento AS BIGINT) AND Activo = 1),0)
		SET	@Categoria			= ISNULL((SELECT TOP 1 Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @Existe AND Activo = 1),0)

		SET @Categoria_Invitado = dbo.CF_xParam('Categ_Invitados')
		----------------------------------------------------

		SET @Primer_Dia_Mes = (dbo.CF_FOMONTH(@pFecha_Invitacion))
		SET @Primer_Dia_Prox_Mes = DATEADD(MONTH, 1, @Primer_Dia_Mes) 
		SET @Cant_Visitas_En_Mes = ISNULL((SELECT COUNT(*) 
												FROM CD_ES
												WHERE
												Id_Cliente = @Existe
												AND Fecha >= @Primer_Dia_Mes
												AND Fecha < @Primer_Dia_Prox_Mes)
											,0)
		----------------------------------------------------

		SET @Invitacion_Previa = (SELECT ISNULL((SELECT MAX(Fecha)
			FROM Clientes_Invitados_Mov 
			WHERE Id_Cliente_D = @Existe	
			AND FECHA >= DATEADD(yy, DATEDIFF(yy, 0, GETDATE()), 0)
			AND FECHA <=  DATEADD(yy, DATEDIFF(yy, 0, GETDATE()) + 1, -1)),'19000101'))
		----------------------------------------------------

		SELECT @Cant_Invitaciones = COUNT(*)
			FROM Clientes_Invitados_Mov 
			WHERE Id_Cliente_D = @Existe 
			AND FECHA >= DATEADD(yy, DATEDIFF(yy, 0, GETDATE()), 0)
			AND FECHA <=  DATEADD(yy, DATEDIFF(yy, 0, GETDATE()) + 1, -1)
		----------------------------------------------------
	END

	IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES 
			   WHERE TABLE_NAME = 'Usr_Invit_Fechas_Libres' 
			   AND TABLE_SCHEMA = 'dbo')
	BEGIN
		SET @Fecha_Libre = (SELECT ISNULL((SELECT 1
										   FROM Usr_Invit_Fechas_Libres 
										   WHERE Fecha_Desde <= @pFecha_Invitacion
										   AND Fecha_Hasta >= @pFecha_Invitacion), 0))
	END

	----------------------------------------------------

	IF (ISNULL(@Existe,0 ) <> 0)
	BEGIN
	
		IF(@Categoria NOT IN (@Categoria_Invitado))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n a un Socio.' AS ErrorMessage
			RETURN 9999
			END

		IF(@pIgnorar_Validaciones = 0 AND @Fecha_Libre = 0) --(0: VALIDA ; 1: NO VALIDA (LIBRE))
		BEGIN

			IF(@pIgnorar_Invit_Max_Anuales = 0 AND @Cant_Invitaciones >= dbo.CF_xParam('Invit_Max_Anuales'))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n. La persona posee el mÔö£├¡ximo de invitaciones en el a├▒o.' AS ErrorMessage
			RETURN 9999
			END

			IF(@pFecha_Invitacion < @Invitacion_Previa)
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n. La persona posee una invitaci├│n' AS ErrorMessage
			RETURN 9999
			END

			IF(@Cant_Visitas_En_Mes >= 1  OR (MONTH(@Invitacion_Previa) = MONTH(@pFecha_Invitacion)) AND CONVERT(DATE, @Invitacion_Previa) <> '1900-01-01')
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n. La persona ya fue invitada este mes.' AS ErrorMessage
			RETURN 9999
			END

			IF(@Invitacion_Previa <= @pFecha_Invitacion AND GETDATE() < @Invitacion_Previa AND CONVERT(DATE, @Invitacion_Previa) <> '1900-01-01')
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n. La persona posee una invitaci├│n previa' AS ErrorMessage
			RETURN 9999
			END

			IF(@pFecha_Invitacion < CONVERT(VARCHAR(8),GETDATE(),112))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaciÔö£Ôöén.' AS ErrorMessage
			RETURN 9999
			END
		END

		-- Hago los insert
		IF(@pSolo_Validar_Invitacion = 0)
		BEGIN
			IF (@pTipo = 1 /*INVITACION INDIVIDUAL*/)
			BEGIN
				INSERT INTO Clientes_Invitados_Mov (Id_Cliente,	Id_Cliente_D,	Fecha_Mov, Fecha, Id_Link, Id_Producto, Nro_Operacion)
				VALUES   (@pId_Invitante, @Existe, GETDATE(), @pFecha_Invitacion, @pId_Link, @pId_Producto, @pNo_Operacion)
			
				IF(@pId_Link <> 0)
				BEGIN
					UPDATE Clientes_Links SET Cant_Usos_Realizados = Cant_Usos_Realizados + 1 WHERE Id_Link = @pId_Link
				END
			END

			IF (@pTipo = 2 /*GENERAR LINK (INVITACIONES MASIVAS)*/)
			BEGIN
			
				SET @Token = dbo.CF_Clientes_Links_Token('A',32)
				SET @URL = '/' + CONVERT(VARCHAR(20), 'invitados_link.php') + '/' + 'invitados_link.php?id=' + CONVERT(VARCHAR(250), @Token)


				INSERT INTO Clientes_Links (Url, Id_Cliente ,Fecha_Gen, Fecha_Ult_Uso, Cant_Usos_Permitidos,
											Cant_Usos_Realizados, Mail, Token, Nota, Fecha_Desde, Fecha_Hasta, Id_Producto)
				VALUES					   (@URL, @pId_Invitante, GETDATE(), GETDATE(), @pCantidad, 
											0, '', @Token, @pObservacion, @pFecha_Invitacion, @pFecha_Invitacion, @pId_Producto)

				IF(@pId_Link <> 0)
				BEGIN
					UPDATE Clientes_Links SET Cant_Usos_Realizados = Cant_Usos_Realizados + 1 WHERE Id_Link = @pId_Link
				END
			END
		END

		-- Si todo fue okey
		SELECT  0 AS ErrorNumber
				,0 AS ErrorSeverity
				,0 AS ErrorState
				,0 AS ErrorProcedure
				,0 AS ErrorLine
				,CAST(@Existe AS VARCHAR(4000)) AS ErrorMessage

	END
	ELSE
	BEGIN
			
		IF (@pTipo = 1 /*INVITACION INDIVIDUAL*/)
		BEGIN
				-- Hago los insert
				IF(@pSolo_Validar_Invitacion = 0)
				BEGIN

					SET @Existe  = (SELECT MAX(Id_Cliente) FROM Clientes ) + 1
					SET @Id_Pais = dbo.CF_xParam('Web_Id_Pais')

					INSERT INTO Clientes (Razon_Social,	  Apellido,			Nombre,			Id_Tipo_Doc,	Doc_Nro,
											Email,			  Email_Cob,		Email_Web,		Activo,			Id_Iva,
											Id_Tipo_Cli,	  Fecha_Alta,		Tipo_Persona,	Id_Cliente,		ID_NACIONALIDAD,
											ID_LISTA_PRECIO, Id_Cliente_Ref,	Observacion)

					VALUES (LTRIM(RTRIM(UPPER(@pApellido))) +' '+ LTRIM(RTRIM(UPPER(@pNombre))),UPPER(@pApellido),UPPER(@pNombre),'',@pDocumento,
							@pEmail,			@pEmail,			@pEmail,			1,				'CF',
							@Categoria_Invitado,				GETDATE(),			'F',			@Existe,		'ARG',
							0,					0,				@pObservacion )


					INSERT INTO Clientes_Invitados_Mov (Id_Cliente,	Id_Cliente_D,	Fecha_Mov, Fecha, Fecha_Hasta, Id_Link, Id_Producto, Nro_Operacion)
					VALUES   (@pId_Invitante, @Existe, GETDATE(), @pFecha_Invitacion, @pFecha_Invitacion,  @pId_Link, @pId_Producto, @pNo_Operacion)

					IF(@pId_Link <> 0)
					BEGIN
						UPDATE Clientes_Links SET Cant_Usos_Realizados = Cant_Usos_Realizados + 1 WHERE Id_Link = @pId_Link
					END
				END

				
				SELECT  0 AS ErrorNumber
					,0 AS ErrorSeverity
					,0 AS ErrorState
					,0 AS ErrorProcedure
					,0 AS ErrorLine
					,CAST(@Existe AS VARCHAR(4000)) AS ErrorMessage
			
		END

		IF (@pTipo = 2 /*GENERAR LINK (INVITACIONES MASIVAS)*/)
		BEGIN
			
			-- Hago los insert
			IF(@pSolo_Validar_Invitacion = 0)
			BEGIN
				SET @Token = dbo.CF_Clientes_Links_Token('A',32)
				SET @URL = '/' + CONVERT(VARCHAR(25),'invitados_link.php?id=') + CONVERT(VARCHAR(250),@Token)

				INSERT INTO Clientes_Links (Url, Id_Cliente ,Fecha_Gen, Fecha_Ult_Uso, Cant_Usos_Permitidos,
											Cant_Usos_Realizados, Mail, Token, Nota, Fecha_Desde, Fecha_Hasta, Id_Producto)
				VALUES					   (@URL, @pId_Invitante, GETDATE(), GETDATE(), @pCantidad, 
											0, '', @Token, @pObservacion, @pFecha_Invitacion, @pFecha_Invitacion, @pId_Producto)

			
				SELECT  0 AS ErrorNumber
						,0 AS ErrorSeverity
						,0 AS ErrorState
						,0 AS ErrorProcedure
						,0 AS ErrorLine
						,CAST(@URL AS VARCHAR(4000)) AS ErrorMessage
			END
		END

	END

	/*====================================================================================================================================================*/

	IF @pFlagUsarTrans <> 0 COMMIT
	
	/*====================================================================================================================================================*/

	IF (@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Clientes_Visitas'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  ROLLBACK

	RETURN 9999
END CATCH

RETURN 0
GO

CREATE PROCEDURE [dbo].[CPJ_Clientes_Visitas_] @pJsonRecibido VARCHAR(MAX)
AS
SET NOCOUNT ON


	/***************************************************************************************************

	Procedimiento:      CPJ_Clientes_Visitas
	Fecha de Creacion:  2024-10-22
	Creado por:         Adriana Laverde
	Descripcion:        Stored creado para generar invitaciones al club
	Llamado por:        invitados.php (KIOSK, APP)
	Tablas afectadas:   []
	Usado en:           
	Parametro(s):       FlagUsarTrans, ModoDebug, 
	Forma de uso:       EXEC
	Notas adicionales:  Usar CPJ_Clientes_Visitas_ para validaciones particulares

	****************************************************************************************************

	SUMARIO DE CAMBIOS
	FECHA(yyyy-mm-dd)    Autor              Comentarios
	------------------- ------------------- ------------------------------------------------------------
	2025-09-26 se guarda la fecha_hasta de la invitacion en invitaciones individuales
	2026-02-05			Saúl				- Agrego Ignorar_Invit_Max_Anuales para ignorar la variable de xParametros 
											- Agrego Ignorar_Validaciones para ignorar todas las validaciones 
											- Agrego Solo_Validar_Invitacion para que no haga los inserts. 
											  Hace que el store sirva solo para validar.

              
	***************************************************************************************************/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE	@pFlagUsarTrans				TINYINT,
		@pModoDebug					TINYINT,
		@pApellido					VARCHAR(100),
		@pNombre					VARCHAR(100),
		@pDocumento					VARCHAR(100),
		@pFecha_Invitacion			DATETIME,
		@pCantidad					INT,
        @pEmail						VARCHAR(100),
		@pObservacion				VARCHAR(2000),
		@pId_Invitante				INT,
		@pTipo						TINYINT,
		@pId_Link					INT,
		@pId_Producto				VARCHAR(15), 
		@pNo_Operacion				VARCHAR(100),
		@pIgnorar_Invit_Max_Anuales TINYINT,
		@pIgnorar_Validaciones		TINYINT,
		@pSolo_Validar_Invitacion	TINYINT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)
SET @pApellido					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Apellido')), '')
SET @pNombre					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Nombre')), '')
SET @pDocumento					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Documento')),'')
SET @pFecha_Invitacion			= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Invitacion')),'')
SET @pCantidad					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Cantidad')),'')
SET @pEmail						= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Email')),'')
SET @pObservacion				= ISNULL(CONVERT(VARCHAR(2000), dbo.CF_JSON_VALUE(@pJsonRecibido,'Observacion')),'')
SET @pId_Invitante				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Invitante')),0)
SET @pTipo						= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Tipo')),0)
SET @pId_Link					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Link')),0) -- Para los registros de invitados por link
SET @pId_Producto				= ISNULL(CONVERT(VARCHAR(15), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Producto')),'')
SET @pNo_Operacion				= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Nro_Operacion')),'')

SET @pIgnorar_Invit_Max_Anuales	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido, 'Ignorar_Invit_Max_Anuales')), 0)
SET @pIgnorar_Validaciones		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido, 'Ignorar_Validaciones')), 0)
SET @pSolo_Validar_Invitacion	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido, 'Solo_Validar_Invitacion')), 0)

/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Variables Locales*/
DECLARE @Invitacion_Previa			DATETIME
DECLARE @Existe						INT = 0
DECLARE @Cant_Invitaciones			INT
DECLARE @Categoria					INT
DECLARE @Categoria_Invitado			INT
DECLARE @Cant_Visitas_En_Mes		INT
DECLARE @Primer_Dia_Mes				DATETIME
DECLARE @Primer_Dia_Prox_Mes		DATETIME
DECLARE @Fecha_Libre				DATETIME = 0 --Libre de validaciones 
DECLARE	@URL						VARCHAR(2000)
DECLARE @Token						VARCHAR(250)
DECLARE @Id_Pais					CHAR(3) -- 14/08/2025 Maca Se agrega por las particularidades de los clientes 200, ARG
DECLARE @Valida_Visitas_Mes 		INT    ---27/10/2025   Andre - Solicitado por GEBA TK 012676
/*FINVariables Locales*/

BEGIN TRY
	IF (@pFlagUsarTrans <> 0)
	BEGIN
		BEGIN TRAN
	END

	IF (@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Clientes_Visitas'
		PRINT 'Parametros: '+ @pJsonRecibido  
		PRINT ' ---------------------- '
	END

	IF(@pId_Producto = '0')
	BEGIN 
		SET @pId_Producto = ''
	END 

	IF(@pId_Link > 0)
	BEGIN
		SET @pId_Invitante = ISNULL((SELECT Id_Cliente FROM Clientes_Links WHERE Id_Link = @pId_Link),0)
		SET @pFecha_Invitacion = ISNULL((SELECT Fecha_Desde FROM Clientes_Links WHERE Id_Link = @pId_Link),'')
		SET @pId_Producto = ISNULL((SELECT Id_Producto FROM Clientes_Links WHERE Id_Link = @pId_Link), '')
	END
	ELSE
	BEGIN
	 SET @pId_Link = NULL
	END

	IF(@pTipo = 1)
	BEGIN
		-----------------------------------------------------------------------------------------------
		SET	@Existe				= ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Doc_Nro = CAST(@pDocumento AS BIGINT) AND Activo = 1),0)
		SET	@Categoria			= ISNULL((SELECT TOP 1 Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @Existe AND Activo = 1),0)

		SET @Categoria_Invitado = dbo.CF_xParam('Categ_Invitados')
		SET @Valida_Visitas_Mes =  dbo.CF_xParam('Valida_Invitado_Mes')
		----------------------------------------------------

		SET @Primer_Dia_Mes = (dbo.CF_FOMONTH(@pFecha_Invitacion))
		SET @Primer_Dia_Prox_Mes = DATEADD(MONTH, 1, @Primer_Dia_Mes) 
		
		IF @Valida_Visitas_Mes =1
		BEGIN
		SET @Cant_Visitas_En_Mes = ISNULL((SELECT COUNT(*) 
												FROM CD_ES
												WHERE
												Id_Cliente = @Existe
												AND Fecha >= @Primer_Dia_Mes
												AND Fecha < @Primer_Dia_Prox_Mes)
											,0)
		END	
		----------------------------------------------------

		SET @Invitacion_Previa = (SELECT ISNULL((SELECT MAX(Fecha)
			FROM Clientes_Invitados_Mov 
			WHERE Id_Cliente_D = @Existe	
			AND FECHA >= DATEADD(yy, DATEDIFF(yy, 0, GETDATE()), 0)
			AND FECHA <=  DATEADD(yy, DATEDIFF(yy, 0, GETDATE()) + 1, -1)),'19000101'))
		----------------------------------------------------

		SELECT @Cant_Invitaciones = COUNT(*)
			FROM Clientes_Invitados_Mov 
			WHERE Id_Cliente_D = @Existe 
			AND FECHA >= DATEADD(yy, DATEDIFF(yy, 0, GETDATE()), 0)
			AND FECHA <=  DATEADD(yy, DATEDIFF(yy, 0, GETDATE()) + 1, -1)
		----------------------------------------------------
	END

	IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES 
			   WHERE TABLE_NAME = 'zInvit_Fechas_Libres' 
			   AND TABLE_SCHEMA = 'dbo')
	BEGIN
		SET @Fecha_Libre = (SELECT ISNULL((SELECT 1
										   FROM zInvit_Fechas_Libres 
										   WHERE Fecha_Desde <= @pFecha_Invitacion
										   AND Fecha_Hasta >= @pFecha_Invitacion), 0))
	END

	----------------------------------------------------

	IF (ISNULL(@Existe,0 ) <> 0)
	BEGIN
	
		IF(@Categoria NOT IN (@Categoria_Invitado))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitación a un Socio.' AS ErrorMessage
			RETURN 9999
			END

		IF(@pIgnorar_Validaciones = 0 AND @Fecha_Libre = 0) --(0: VALIDA ; 1: NO VALIDA (LIBRE))
		BEGIN

			IF(@pIgnorar_Invit_Max_Anuales = 0 AND @Cant_Invitaciones >= dbo.CF_xParam('Invit_Max_Anuales'))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitación. La persona posee el máximo de invitaciones en el año.' AS ErrorMessage
			RETURN 9999
			END

			IF(@pFecha_Invitacion < @Invitacion_Previa)
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitación. La persona posee una invitación' AS ErrorMessage
			RETURN 9999
			END

			IF @Valida_Visitas_Mes = 1
			BEGIN
				IF(@Cant_Visitas_En_Mes > 1  OR (MONTH(@Invitacion_Previa) = MONTH(@pFecha_Invitacion)) AND CONVERT(DATE, @Invitacion_Previa) <> '1900-01-01')
				BEGIN
					SELECT  5001 AS ErrorNumber
						,1 AS ErrorSeverity
						,1 AS ErrorState
						,1 AS ErrorProcedure
						,1 AS ErrorLine
						,'No es posible realizar la invitación. La persona ya fue invitada este mes.' AS ErrorMessage
				RETURN 9999
				END
			END
			
			/* agrego*/
			IF(@Invitacion_Previa = @pFecha_Invitacion )
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitación. La persona posee una invitación previa para el mismo dia.' AS ErrorMessage
			RETURN 9999
			END

			IF(@Invitacion_Previa <= @pFecha_Invitacion AND GETDATE() < @Invitacion_Previa AND CONVERT(DATE, @Invitacion_Previa) <> '1900-01-01' AND @Valida_Visitas_Mes = 1)
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitación. La persona posee una invitación previa' AS ErrorMessage
			RETURN 9999
			END
			

			IF(@pFecha_Invitacion < CONVERT(VARCHAR(8),GETDATE(),112))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitación.' AS ErrorMessage
			RETURN 9999
			END
		END

		-- Hago los insert
		IF(@pSolo_Validar_Invitacion = 0)
		BEGIN
			IF (@pTipo = 1 /*INVITACION INDIVIDUAL*/)
			BEGIN
				INSERT INTO Clientes_Invitados_Mov (Id_Cliente,	Id_Cliente_D,	Fecha_Mov, Fecha, Id_Link, Id_Producto, Nro_Operacion)
				VALUES   (@pId_Invitante, @Existe, GETDATE(), @pFecha_Invitacion, @pId_Link, @pId_Producto, @pNo_Operacion)

				IF(@pId_Link <> 0)
				BEGIN
					UPDATE Clientes_Links SET Cant_Usos_Realizados = Cant_Usos_Realizados + 1 WHERE Id_Link = @pId_Link
				END
			END

			IF (@pTipo = 2 /*GENERAR LINK (INVITACIONES MASIVAS)*/)
			BEGIN
			
				SET @Token = dbo.CF_Clientes_Links_Token('A',32)
				SET @URL = '/' + CONVERT(VARCHAR(20), 'invitados_link.php') + '/' + 'invitados_link.php?id=' + CONVERT(VARCHAR(250), @Token)


				INSERT INTO Clientes_Links (Url, Id_Cliente ,Fecha_Gen, Fecha_Ult_Uso, Cant_Usos_Permitidos,
											Cant_Usos_Realizados, Mail, Token, Nota, Fecha_Desde, Fecha_Hasta, Id_Producto)
				VALUES					   (@URL, @pId_Invitante, GETDATE(), GETDATE(), @pCantidad, 
											0, '', @Token, @pObservacion, @pFecha_Invitacion, @pFecha_Invitacion, @pId_Producto)

				IF(@pId_Link <> 0)
				BEGIN
					UPDATE Clientes_Links SET Cant_Usos_Realizados = Cant_Usos_Realizados + 1 WHERE Id_Link = @pId_Link
				END
			END
		END

		-- Si todo fue okey
		SELECT  0 AS ErrorNumber
				,0 AS ErrorSeverity
				,0 AS ErrorState
				,0 AS ErrorProcedure
				,0 AS ErrorLine
				,CAST(@Existe AS VARCHAR(4000)) AS ErrorMessage

	END
	ELSE
	BEGIN
			
		IF (@pTipo = 1 /*INVITACION INDIVIDUAL*/)
		BEGIN
				-- Hago los insert
				IF(@pSolo_Validar_Invitacion = 0)
				BEGIN

					SET @Existe  = (SELECT MAX(Id_Cliente) FROM Clientes ) + 1
					SET @Id_Pais = dbo.CF_xParam('Web_Id_Pais')

					INSERT INTO Clientes (Razon_Social,	  Apellido,			Nombre,			Id_Tipo_Doc,	Doc_Nro,
											Email,			  Email_Cob,		Email_Web,		Activo,			Id_Iva,
											Id_Tipo_Cli,	  Fecha_Alta,		Tipo_Persona,	Id_Cliente,		ID_NACIONALIDAD,
											ID_LISTA_PRECIO, Id_Cliente_Ref,	Observacion)

					VALUES (LTRIM(RTRIM(UPPER(@pApellido))) +' '+ LTRIM(RTRIM(UPPER(@pNombre))),UPPER(@pApellido),UPPER(@pNombre),'',@pDocumento,
							@pEmail,			@pEmail,			@pEmail,			1,				'CF',
							@Categoria_Invitado,				GETDATE(),			'F',			@Existe,		'ARG',
							0,					0,				@pObservacion )


					INSERT INTO Clientes_Invitados_Mov (Id_Cliente,	Id_Cliente_D,	Fecha_Mov, Fecha, Fecha_Hasta, Id_Link, Id_Producto, Nro_Operacion)
					VALUES   (@pId_Invitante, @Existe, GETDATE(), @pFecha_Invitacion, @pFecha_Invitacion,  @pId_Link, @pId_Producto, @pNo_Operacion)

					IF(@pId_Link <> 0)
					BEGIN
						UPDATE Clientes_Links SET Cant_Usos_Realizados = Cant_Usos_Realizados + 1 WHERE Id_Link = @pId_Link
					END
				END

				
				SELECT  0 AS ErrorNumber
					,0 AS ErrorSeverity
					,0 AS ErrorState
					,0 AS ErrorProcedure
					,0 AS ErrorLine
					,CAST(@Existe AS VARCHAR(4000)) AS ErrorMessage
			
		END

		IF (@pTipo = 2 /*GENERAR LINK (INVITACIONES MASIVAS)*/)
		BEGIN
			
			-- Hago los insert
			IF(@pSolo_Validar_Invitacion = 0)
			BEGIN
				SET @Token = dbo.CF_Clientes_Links_Token('A',32)
				SET @URL = '/' + CONVERT(VARCHAR(25),'invitados_link.php?id=') + CONVERT(VARCHAR(250),@Token)

				INSERT INTO Clientes_Links (Url, Id_Cliente ,Fecha_Gen, Fecha_Ult_Uso, Cant_Usos_Permitidos,
											Cant_Usos_Realizados, Mail, Token, Nota, Fecha_Desde, Fecha_Hasta, Id_Producto)
				VALUES					   (@URL, @pId_Invitante, GETDATE(), GETDATE(), @pCantidad, 
											0, '', @Token, @pObservacion, @pFecha_Invitacion, @pFecha_Invitacion, @pId_Producto)

			
				SELECT  0 AS ErrorNumber
						,0 AS ErrorSeverity
						,0 AS ErrorState
						,0 AS ErrorProcedure
						,0 AS ErrorLine
						,CAST(@URL AS VARCHAR(4000)) AS ErrorMessage
			END
		END

	END

	/*====================================================================================================================================================*/

	IF @pFlagUsarTrans <> 0 COMMIT
	
	/*====================================================================================================================================================*/

	IF (@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Clientes_Visitas'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  ROLLBACK

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Clientes_Visitas_bkp_09_02_2026] @pJsonRecibido VARCHAR(MAX)
AS
SET NOCOUNT ON

	IF EXISTS ( SELECT * 
            FROM   sysobjects 
            WHERE  id = object_id(N'dbo.CPJ_Clientes_Visitas_') 
                   and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
	BEGIN 
		EXEC CPJ_Clientes_Visitas_ @pJsonRecibido
		RETURN
	END	

	/***************************************************************************************************

	Procedimiento:      CPJ_Clientes_Visitas
	Fecha de Creacion:  2024-10-22
	Creado por:         Adriana Laverde
	Descripcion:        Stored creado para generar invitaciones al club
	Llamado por:        invitados.php (KIOSK, APP)
	Tablas afectadas:   []
	Usado en:           
	Parametro(s):       FlagUsarTrans, ModoDebug, 
	Forma de uso:       EXEC
	Notas adicionales:  Usar CPJ_Clientes_Visitas_ para validaciones particulares

	****************************************************************************************************

	SUMARIO DE CAMBIOS
	FECHA(yyyy-mm-dd)    Autor              Comentarios
	------------------- ------------------- ------------------------------------------------------------
	2025-09-26 se guarda la fecha_hasta de la invitacion en invitaciones individuales
              
	***************************************************************************************************/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE	@pFlagUsarTrans			TINYINT,
		@pModoDebug				TINYINT,
		@pApellido				VARCHAR(100),
		@pNombre				VARCHAR(100),
		@pDocumento				VARCHAR(100),
		@pFecha_Invitacion		DATETIME,
		@pCantidad				INT,
        @pEmail					VARCHAR(100),
		@pObservacion			VARCHAR(2000),
		@pId_Invitante			INT,
		@pTipo					TINYINT,
		@pId_Link				INT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)
SET @pApellido					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Apellido')), '')
SET @pNombre					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Nombre')), '')
SET @pDocumento					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Documento')),'')
SET @pFecha_Invitacion			= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Invitacion')),'')
SET @pCantidad					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Cantidad')),'')
SET @pEmail						= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Email')),'')
SET @pObservacion				= ISNULL(CONVERT(VARCHAR(2000), dbo.CF_JSON_VALUE(@pJsonRecibido,'Observacion')),'')
SET @pId_Invitante				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Invitante')),0)
SET @pTipo						= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Tipo')),0)
SET @pId_Link					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Link')),0) -- Para los registros de invitados por link
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Variables Locales*/
DECLARE @Invitacion_Previa			DATETIME
DECLARE @Existe						INT = 0
DECLARE @Cant_Invitaciones			INT
DECLARE @Categoria					INT
DECLARE @Categoria_Invitado			INT
DECLARE @Cant_Visitas_En_Mes		INT
DECLARE @Primer_Dia_Mes				DATETIME
DECLARE @Primer_Dia_Prox_Mes		DATETIME
DECLARE @Fecha_Libre				DATETIME = 0 --Libre de validaciones 
DECLARE	@URL						VARCHAR(2000)
DECLARE @Token						VARCHAR(250)
DECLARE @Id_Pais					CHAR(3) -- 14/08/2025 Maca Se agrega por las particularidades de los clientes 200, ARG
DECLARE @Valida_Visitas_Mes 		INT    ---27/10/2025   Andre - Solicitado por GEBA TK 012676
/*FINVariables Locales*/

BEGIN TRY
	IF (@pFlagUsarTrans <> 0)
	BEGIN
		BEGIN TRAN
	END

	IF (@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Clientes_Visitas'
		PRINT 'Parametros: '+ @pJsonRecibido  
		PRINT ' ---------------------- '
	END

	IF(@pId_Link > 0)
	BEGIN
		SET @pId_Invitante = ISNULL((SELECT Id_Cliente FROM Clientes_Links WHERE Id_Link = @pId_Link),0)
		SET @pFecha_Invitacion = ISNULL((SELECT Fecha_Desde FROM Clientes_Links WHERE Id_Link = @pId_Link),'')
	END
	ELSE
	BEGIN
	 SET @pId_Link = NULL
	END

	IF(@pTipo = 1)
	BEGIN
		-----------------------------------------------------------------------------------------------
		SET	@Existe				= ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Doc_Nro = CAST(@pDocumento AS BIGINT) AND Activo = 1),0)
		SET	@Categoria			= ISNULL((SELECT TOP 1 Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @Existe AND Activo = 1),0)

		SET @Categoria_Invitado =  dbo.CF_xParam('Categ_Invitados')
		SET @Valida_Visitas_Mes =  dbo.CF_xParam('Valida_Invitado_Mes')
		----------------------------------------------------

		SET @Primer_Dia_Mes = (dbo.CF_FOMONTH(@pFecha_Invitacion))
		SET @Primer_Dia_Prox_Mes = DATEADD(MONTH, 1, @Primer_Dia_Mes) 
		
		IF @Valida_Visitas_Mes =1
		BEGIN
		SET @Cant_Visitas_En_Mes = ISNULL((SELECT COUNT(*) 
												FROM CD_ES
												WHERE
												Id_Cliente = @Existe
												AND Fecha >= @Primer_Dia_Mes
												AND Fecha < @Primer_Dia_Prox_Mes)
											,0)
		END								
		----------------------------------------------------

		SET @Invitacion_Previa = (SELECT ISNULL((SELECT MAX(Fecha)
			FROM Clientes_Invitados_Mov 
			WHERE Id_Cliente_D = @Existe	
			AND FECHA >= DATEADD(yy, DATEDIFF(yy, 0, GETDATE()), 0)
			AND FECHA <=  DATEADD(yy, DATEDIFF(yy, 0, GETDATE()) + 1, -1)),'19000101'))
		
		
		----------------------------------------------------

		SELECT @Cant_Invitaciones = COUNT(*)
			FROM Clientes_Invitados_Mov 
			WHERE Id_Cliente_D = @Existe 
			AND FECHA >= DATEADD(yy, DATEDIFF(yy, 0, GETDATE()), 0)
			AND FECHA <=  DATEADD(yy, DATEDIFF(yy, 0, GETDATE()) + 1, -1)
		----------------------------------------------------
	END

	IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES 
			   WHERE TABLE_NAME = 'zInvit_Fechas_Libres' 
			   AND TABLE_SCHEMA = 'dbo')
	BEGIN
		SET @Fecha_Libre = (SELECT ISNULL((SELECT 1
										   FROM zInvit_Fechas_Libres 
										   WHERE Fecha_Desde <= @pFecha_Invitacion
										   AND Fecha_Hasta >= @pFecha_Invitacion), 0))
	END

	----------------------------------------------------

	IF (ISNULL(@Existe,0 ) <> 0)
	BEGIN
	
		IF(@Categoria NOT IN (@Categoria_Invitado))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n a un Socio.' AS ErrorMessage
			RETURN 9999
			END

		IF(@Fecha_Libre = 0) --(0: VALIDA ; 1: NO VALIDA (LIBRE))
		BEGIN

			IF(@Cant_Invitaciones >= dbo.CF_xParam('Invit_Max_Anuales'))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n. La persona posee el m├íximo de invitaciones en el a├▒o.' AS ErrorMessage
			RETURN 9999
			END

			IF(@pFecha_Invitacion < @Invitacion_Previa)
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitacion. La persona posee una invitacion' AS ErrorMessage
			RETURN 9999
			END

			IF @Valida_Visitas_Mes =1
			BEGIN
			IF(@Cant_Visitas_En_Mes > 1  OR (MONTH(@Invitacion_Previa) = MONTH(@pFecha_Invitacion)) AND CONVERT(DATE, @Invitacion_Previa) <> '1900-01-01')
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitacion. La persona ya fue invitada este mes.' AS ErrorMessage
			RETURN 9999
			END
			END
			
			/* agrego*/
			IF(@Invitacion_Previa = @pFecha_Invitacion )
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitación. La persona posee una invitación previa para el mismo dia.' AS ErrorMessage
			RETURN 9999
			END
			

			IF(@Invitacion_Previa <= @pFecha_Invitacion AND GETDATE() < @Invitacion_Previa AND CONVERT(DATE, @Invitacion_Previa) <> '1900-01-01' AND @Valida_Visitas_Mes =1)
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n. La persona posee una invitaci├│n previa' AS ErrorMessage
			RETURN 9999
			END

			IF(@pFecha_Invitacion < CONVERT(VARCHAR(8),GETDATE(),112))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n.' AS ErrorMessage
			RETURN 9999
			END
		END

		IF (@pTipo = 1 /*INVITACION INDIVIDUAL*/)
		BEGIN
			INSERT INTO Clientes_Invitados_Mov (Id_Cliente,	Id_Cliente_D,	Fecha_Mov, Fecha, Id_Link)
			VALUES   (@pId_Invitante, @Existe, GETDATE(), @pFecha_Invitacion, @pId_Link)
		END

		IF (@pTipo = 2 /*GENERAR LINK (INVITACIONES MASIVAS)*/)
		BEGIN
			
			SET @Token = dbo.CF_Clientes_Links_Token('A',32)
			SET @URL = '/' + CONVERT(VARCHAR(20), 'invitados_link.php') + '/' + 'invitados_link.php?id=' + CONVERT(VARCHAR(250), @Token)


			INSERT INTO Clientes_Links (Url, Id_Cliente ,Fecha_Gen, Fecha_Ult_Uso, Cant_Usos_Permitidos,
										Cant_Usos_Realizados, Mail, Token, Nota, Fecha_Desde, Fecha_Hasta)
			VALUES					   (@URL, @pId_Invitante, GETDATE(), GETDATE(), @pCantidad, 
										0, '', @Token, @pObservacion, @pFecha_Invitacion, @pFecha_Invitacion)

			IF(@pId_Link <> 0)
			BEGIN
				UPDATE Clientes_Links SET Cant_Usos_Realizados = Cant_Usos_Realizados + 1 WHERE Id_Link = @pId_Link
			END
		END
	END
	ELSE
	BEGIN
			
		IF (@pTipo = 1 /*INVITACION INDIVIDUAL*/)
		BEGIN
				SET @Existe  = (SELECT MAX(Id_Cliente) FROM Clientes ) + 1
				SET @Id_Pais = dbo.CF_xParam('Web_Id_Pais')

				INSERT INTO Clientes (Razon_Social,	  Apellido,			Nombre,			Id_Tipo_Doc,	Doc_Nro,
										Email,			  Email_Cob,		Email_Web,		Activo,			Id_Iva,
										Id_Tipo_Cli,	  Fecha_Alta,		Tipo_Persona,	Id_Cliente,		ID_NACIONALIDAD,
										ID_LISTA_PRECIO, Id_Cliente_Ref,	Observacion)

				VALUES (LTRIM(RTRIM(UPPER(@pApellido))) +' '+ LTRIM(RTRIM(UPPER(@pNombre))),UPPER(@pApellido),UPPER(@pNombre),'',@pDocumento,
						@pEmail,			@pEmail,			@pEmail,			1,				'CF',
						@Categoria_Invitado,				GETDATE(),			'F',			@Existe,		'ARG',
						0,					0,				@pObservacion )


				INSERT INTO Clientes_Invitados_Mov (Id_Cliente,	Id_Cliente_D,	Fecha_Mov, Fecha, Fecha_Hasta, Id_Link)
				VALUES   (@pId_Invitante, @Existe, GETDATE(), @pFecha_Invitacion, @pFecha_Invitacion,  @pId_Link)

				IF(@pId_Link <> 0)
				BEGIN
					UPDATE Clientes_Links SET Cant_Usos_Realizados = Cant_Usos_Realizados + 1 WHERE Id_Link = @pId_Link
				END

				
			SELECT  0 AS ErrorNumber
					,0 AS ErrorSeverity
					,0 AS ErrorState
					,0 AS ErrorProcedure
					,0 AS ErrorLine
					,CAST(@Existe AS VARCHAR(4000)) AS ErrorMessage
			
		END

		IF (@pTipo = 2 /*GENERAR LINK (INVITACIONES MASIVAS)*/)
		BEGIN

			SET @Token = dbo.CF_Clientes_Links_Token('A',32)
			SET @URL = '/' + CONVERT(VARCHAR(25),'invitados_link.php?id=') + CONVERT(VARCHAR(250),@Token)

			INSERT INTO Clientes_Links (Url, Id_Cliente ,Fecha_Gen, Fecha_Ult_Uso, Cant_Usos_Permitidos,
										Cant_Usos_Realizados, Mail, Token, Nota, Fecha_Desde, Fecha_Hasta)
			VALUES					   (@URL, @pId_Invitante, GETDATE(), GETDATE(), @pCantidad, 
										0, '', @Token, @pObservacion, @pFecha_Invitacion, @pFecha_Invitacion)

			
			SELECT  0 AS ErrorNumber
					,0 AS ErrorSeverity
					,0 AS ErrorState
					,0 AS ErrorProcedure
					,0 AS ErrorLine
					,CAST(@URL AS VARCHAR(4000)) AS ErrorMessage
		END

	END

	/*====================================================================================================================================================*/

	IF @pFlagUsarTrans <> 0 COMMIT
	
	/*====================================================================================================================================================*/

	IF (@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Clientes_Visitas'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  ROLLBACK

	RETURN 9999
END CATCH

RETURN 0
GO



CREATE PROCEDURE [dbo].[CPJ_Cobros_Pendientes] @pJson VARCHAR(8000)
AS 
BEGIN
SET NOCOUNT ON

DECLARE	@pFiltrar_Fecha		TINYINT 
	,@pFecha_Desde			DATETIME 
	,@pFecha_Hasta			DATETIME
	,@pId_cliente			INT
	,@pDoc_Nro				BIGINT
	,@pId_Cobrador			VARCHAR(10)
	,@pId_Cliente_Externo	VARCHAR(50)
	,@pDet_Producto			INT=0


SET @pFiltrar_Fecha			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Filtrar_Fecha')), 0)
SET @pFecha_Desde			= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde'))
SET @pFecha_Hasta			= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta'))
SET @pId_cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Cobrador			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Cobrador')), '')
SET @pDoc_Nro				= ISNULL(CONVERT(BIGINT, dbo.CF_JSON_VALUE(@pJson,'Doc_Nro')), 0)
SET @pId_Cliente_Externo	= ISNULL(CONVERT(VARCHAR(50), dbo.CF_JSON_VALUE(@pJson,'Id_Cliente_Externo')), '')
SET @pDet_Producto		    = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Det_Producto')), 0)


DECLARE @Sql		VARCHAR(MAX)
DECLARE @SqlSaldo	VARCHAR(MAX)
DECLARE @SqlSelect	VARCHAR(MAX)
DECLARE @SqlFrom	VARCHAR(MAX)
DECLARE @SqlWhere	VARCHAR(MAX)
DECLARE @SqlGroup	VARCHAR(MAX)

CREATE TABLE #Cobros_Pend  (
			 Fecha DATETIME
			,Fecha_Vence DATETIME
			,Descripcion VARCHAR(25)
			,Id_Trans INT
			,Nro_Cuota SMALLINT
			,Id_cliente INT
			,Razon_Social CHAR(100)
			,Importe DECIMAL(16,2)
			,Saldo 	DECIMAL(16,2)
			,Id_Tipo_Cbte Char(4)
			,Comprobante_Nro INT
			,Id_Estado_Cbte SMALLINT
			,Id_Cobrador Varchar(10)
			,Nombre_Cobrador CHAR(100)
			,Id_Interno INT IDENTITY(1,1)
			,Activo TINYINT
			,Descrip_Producto	VARCHAR(8000)
			,Doc_Nro	BIGINT
			,Id_Cliente_Externo VARCHAR(50)
		)

IF @pId_cliente = 0 AND @pDoc_Nro <> 0
	SELECT TOP 1 @pId_cliente = Id_cliente FROM Clientes WHERE Doc_Nro = @pDoc_Nro ORDER BY Activo  DESC

IF @pId_cliente = 0 AND @pDoc_Nro = 0 AND @pId_Cliente_Externo <> ''
	SELECT TOP 1 @pId_cliente = Id_cliente FROM Clientes WHERE Id_Cliente_Externo = @pId_Cliente_Externo ORDER BY Activo  DESC


IF  @pId_cliente = 0  AND (@pDoc_Nro <> 0 OR @pId_Cliente_Externo <> '')
BEGIN
	SELECT * FROM #Cobros_Pend
	DROP TABLE #Cobros_Pend 
	RETURN 0
END


SET @SqlSelect = 'SELECT TOP 50 k.FECHA as Fecha,
                         k.Fecha_vence as Fecha_Vence,
						 k.Descripcion as Descripcion,
						 k.Id_Trans as Id_Trans,
						 k.Nro_Cuota as Nro_Cuota,
						 k.Id_cliente as Id_Cliente,
						 UPPER(CL.Razon_Social) as Razon_Social,
						 K.Importe as Importe,
						 k.Saldo as Saldo,
						 C.Id_Tipo_Cbte as Id_Tipo_Cbte,
						 C.Comprobante_Nro as Comprobante_Nro,
						 k.Id_Estado_Cbte as Id_Estado_Cbte,
						 UPPER(CL.id_COBRADOR) as Id_Cobrador,
						 V.Descripcion as Nombre_Cobrador,
						 CL.Activo
						'
						 

IF (@pDet_Producto<>0)
BEGIN
	SET @SqlSelect =@SqlSelect+ ',dbo.CF_Descrip_Cbte_Producto(C.Id_Trans) AS Det_Producto'
END 
ELSE
BEGIN
	SET @SqlSelect =@SqlSelect+ ','''' AS Det_Producto'
END 
SET @SqlSelect =@SqlSelect+ ',CL.Doc_Nro
						 ,CL.Id_Cliente_Externo'

SET @SqlFrom = 'FROM  Cbtes C , Clientes_Ctacte K, Clientes CL,  Cbtes_Tipos T,  Vendedores V'
----------------------------------------------------------------------------------------------------------------------
SET @SqlWhere = ' WHERE c.id_trans = k.id_trans 
                        AND K.ID_CLIENTE = CL.ID_CLIENTE
						AND C.ID_TIPO_CBTE = T.ID_TIPO_CBTE
						AND CL.ID_COBRADOR = V.ID_VENDEDOR 
						AND K.ID_ESTADO_CBTE IN (1,4)
						AND T.COMPROMETE_FACTURA IN (1)
						AND K.SALDO <> 0'
						

					 
IF @pId_cliente <> 0
  BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND C.Id_cliente  = ' +  cast(@pId_cliente  as varchar(12))
  END


IF ISNULL(@pId_Cobrador,'') <> '' AND @pId_cliente = 0
	BEGIN
		SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND CL.Id_Cobrador = ''' + @pId_Cobrador + ''''
	END


IF ISNULL(@pFiltrar_Fecha,0) <> 0
BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND k.FECHA_VENCE >= '''+ CONVERT(VARCHAR(8),@pFecha_Desde,112) +''''

	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND k.FECHA_VENCE < '''+ CONVERT(VARCHAR(8),@pFecha_Hasta+1,112) +''''
END
----------------------------------------------------------------------------------------------------------------------
SET @SqlGroup = ' ORDER BY CL.Activo DESC,k.id_cliente,k.FECHA_VENCE '


SET @Sql = @SqlSelect +' '+ @SqlFrom + ' ' + @SqlWhere + ' ' + @SqlGroup 
PRINT @Sql
--EXECUTE (@Sql) 

CREATE INDEX IX_cobros_Pend____ ON  #Cobros_Pend (Id_Interno)

INSERT INTO #Cobros_Pend
EXEC(@sql)

SELECT * FROM #Cobros_Pend


DROP TABLE #Cobros_Pend 

END


/*


EXEC [CPJ_Cobros_Pendientes] '{"Filtrar_Fecha":"0"
					,"Fecha_Desde":""
					,"Fecha_Hasta":""
					,"Id_Cliente":"10533"
					,"Id_Cobrador":""
					,"Doc_Nro":""
					,"Det_Producto":""}'


*/
GO

CREATE PROCEDURE [dbo].[CPJ_Cobros_Realizados] @pJson VARCHAR(8000) 
AS 
BEGIN 
SET NOCOUNT ON

DECLARE @pFiltrar_Fecha TINYINT 
DECLARE @pFecha_Desde DateTime 
DECLARE @pFecha_Hasta DateTime
DECLARE @pId_cliente  INT
DECLARE @pId_Cobrador Varchar(10)
DECLARE @pId_Periodo_Caja INT

SET @pFiltrar_Fecha = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Filtrar_Fecha')), 0)
SET @pFecha_Desde = ISNULL(CONVERT(DateTime, dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde')), '19000101')
SET @pFecha_Hasta = ISNULL(CONVERT(DateTime, dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta')), '19000101')
SET @pId_cliente  = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_cliente')), 0)
SET @pId_Cobrador = ISNULL(CONVERT(Varchar(10), dbo.CF_JSON_VALUE(@pJson,'Id_Cobrador')), '')
SET @pId_Periodo_Caja = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Periodo_Caja')), 0)

DECLARE @Sql		VARCHAR(MAX)
DECLARE @SqlSaldo	VARCHAR(MAX)
DECLARE @SqlSelect	VARCHAR(MAX)
DECLARE @SqlFrom	VARCHAR(MAX)
DECLARE @SqlWhere	VARCHAR(MAX)
DECLARE @SqlGroup	VARCHAR(MAX)

CREATE TABLE #Cobros_Realizados  (
			 Fecha DATETIME
			,Descripcion VARCHAR(25)
			,Id_Trans INT
			,Nro_Cuota SMALLINT
			,Id_cliente INT
			,Razon_Social CHAR(100)
			,Importe DECIMAL(16,2)
			,Id_Tipo_Cbte Char(4)
			,Comprobante_Nro INT
			,Id_Periodo_Caja INT
			,Id_Cobrador Varchar(10)
			,Nombre_Cobrador CHAR(100)
			,Id_Interno INT IDENTITY(1,1)
		)

SET @SqlSelect = 'SELECT k.FECHA as Fecha,
						 k.Descripcion as Descripcion,
						 k.Id_Trans as Id_Trans,
						 k.Nro_Cuota as Nro_Cuota,
						 k.Id_cliente as Id_Cliente,
						 UPPER(CL.Razon_Social) as Razon_Social,
						 K.Importe * -1 as Importe,
						 C.Id_Tipo_Cbte as Id_Tipo_Cbte,
						 C.Comprobante_Nro as Comprobante_Nro,
						 M.Id_Periodo_Caja as Id_Periodo_Caja,
						 UPPER(CL.id_COBRADOR) as Id_Cobrador,
						 V.Descripcion as Nombre_Cobrador'


SET @SqlFrom = ' FROM  Cbtes C , Clientes_Ctacte K, Clientes CL,  Cbtes_Tipos T,  Vendedores V, Cajas_Mov M '
----------------------------------------------------------------------------------------------------------------------
SET @SqlWhere = ' WHERE c.id_trans = k.id_trans 
                        AND K.ID_CLIENTE = CL.ID_CLIENTE
						AND C.ID_TIPO_CBTE = T.ID_TIPO_CBTE
						AND CL.ID_COBRADOR = V.ID_VENDEDOR 
						AND K.ID_ESTADO_CBTE IN (2,4)
						AND T.COMPROMETE_RECIBOS IN (1,-1)
						AND K.ID_TRANS = M.ID_TRANS '
				
					 
IF @pId_cliente <> 0
  BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND C.Id_cliente  = ' +  cast(@pId_cliente  as varchar(12))
  END

IF ISNULL(@pId_Cobrador,'') <> ''
	BEGIN
		SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND CL.Id_Cobrador = ''' + @pId_Cobrador + ''''
	END

IF @pId_Periodo_Caja <> 0
  BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND M.Id_Periodo_Caja  = ' +  cast(@pId_Periodo_Caja  as varchar(12))
  END


IF ISNULL(@pFiltrar_Fecha,0) <> 0
BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND k.FECHA_VENCE >= '''+ CONVERT(VARCHAR(8),@pFecha_Desde,112) +''''

	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND k.FECHA_VENCE < '''+ CONVERT(VARCHAR(8),@pFecha_Hasta+1,112) +''''
END
----------------------------------------------------------------------------------------------------------------------
SET @SqlGroup = ' ORDER BY k.id_cliente,k.FECHA '


SET @Sql = @SqlSelect +' '+ @SqlFrom + ' ' + @SqlWhere + ' ' + @SqlGroup 
PRINT @Sql
--EXECUTE (@Sql) 

CREATE INDEX IX_Cobros_Realizados____ ON  #Cobros_Realizados (Id_Interno)

INSERT INTO #Cobros_Realizados
EXEC(@sql)

SELECT * FROM #Cobros_Realizados

DROP TABLE #Cobros_Realizados

END


-- EXEC CPJ_Cobros_Realizados '{"Filtrar_Fecha":"1","Fecha_Desde":"20220101","Fecha_Hasta":"20261130"}'
GO



CREATE PROCEDURE [dbo].[CPJ_Conceptos_Rpt_Anual] @pJson VARCHAR(8000)
AS 
DECLARE @pAnio INT
	,@pCircuito CHAR(1)
	,@pFlag_Apertura TINYINT
	,@pId_Periodo_Caja INT
	,@pNivel	CHAR(1)

SET NOCOUNT ON 
SET @pAnio				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Anio')), 0)
SET @pCircuito			= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJson,'Circuito')), 0)
SET @pFlag_Apertura		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Apertura')), 0)
SET @pId_Periodo_Caja	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Periodo_Caja')), 0)
SET @pNivel				= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJson,'Nivel')), 'C')

DECLARE @Mes SMALLINT
	,@Id_Concepto INT
	,@Rubro VARCHAR(100) 
	,@SubRubro VARCHAR(100) 
	,@Concepto VARCHAR(100) 
	,@Importe DECIMAL(16,2)
	,@Id_Dest INT 
	,@Destinatario VARCHAR(100)

CREATE TABLE #Reporte (
	Id_Concepto INT
	,Rubro VARCHAR(100) DEFAULT('')
	,SubRubro VARCHAR(100) DEFAULT('')
	,Concepto VARCHAR(100) DEFAULT('')
	,Id_Dest INT DEFAULT(0)
	,Destinatario VARCHAR(100) DEFAULT('')
	,Importe DECIMAL(16,2)  DEFAULT(0)
	,Mes1 DECIMAL(16,2) DEFAULT(0)
	,Mes2 DECIMAL(16,2) DEFAULT(0)
	,Mes3 DECIMAL(16,2) DEFAULT(0)
	,Mes4 DECIMAL(16,2) DEFAULT(0)
	,Mes5 DECIMAL(16,2) DEFAULT(0)
	,Mes6 DECIMAL(16,2) DEFAULT(0)
	,Mes7 DECIMAL(16,2) DEFAULT(0)
	,Mes8 DECIMAL(16,2) DEFAULT(0)
	,Mes9 DECIMAL(16,2) DEFAULT(0)
	,Mes10 DECIMAL(16,2) DEFAULT(0)
	,Mes11 DECIMAL(16,2) DEFAULT(0)
	,Mes12 DECIMAL(16,2) DEFAULT(0)
	,Total DECIMAL(16,2) DEFAULT(0)
)

SELECT Id_Periodo_Caja INTO #Cajas_Periodos FROM Cajas_Periodos WHERE 1=0

IF @pId_Periodo_Caja = 0
	INSERT INTO #Cajas_Periodos SELECT Id_Periodo_Caja FROM Cajas_Periodos 
ELSE
	INSERT INTO #Cajas_Periodos SELECT Id_Periodo_Caja FROM Cajas_Periodos WHERE Id_Periodo_Caja = @pId_Periodo_Caja 


SET @Mes = 1
WHILE @Mes <= 12
BEGIN

	IF @pCircuito IN ('','P')
	BEGIN
		IF @pFlag_Apertura = 0
		BEGIN

			DECLARE MiCurPagos CURSOR FOR 
				SELECT	O.Id_Concepto
						,O2.Descripcion	AS Rubro 
						,O1.Descripcion	AS SubRubro 
						,O.Descripcion	AS Concepto
						,0 AS Id_Dest
						,'' AS Destinatario
						,SUM(ISNULL(CO.Importe,0))
					FROM Cajas_Mov_Conceptos CO
						, Cbtes C
						LEFT JOIN Proveedores P ON C.Id_Proveedor = P.Id_Proveedor
						, Cbtes_Tipos T
						, Conceptos O LEFT JOIN Conceptos O1 ON O1.Id_Concepto = O.Id_Concepto_Padre
						LEFT JOIN Conceptos O2 ON O2.Id_Concepto = O1.Id_Concepto_Padre
				
					WHERE CO.Id_Trans = C.Id_Trans
					AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
					AND CO.Id_Concepto = O.Id_Concepto
					AND C.Id_Estado_Cbte IN (1,2,4)
					AND T.Compromete_Pagos IN (1,-1)
					AND DATEPART(YEAR,C.Fecha) = @pAnio
					AND DATEPART(MONTH,C.Fecha) = @Mes
					AND CO.Id_Periodo_Caja IN (SELECT Id_Periodo_Caja FROM #Cajas_Periodos )
					GROUP BY O.Id_Concepto,O2.Descripcion, O1.Descripcion, O.Descripcion
					ORDER BY O2.Descripcion, O1.Descripcion, O.Descripcion
		END
		ELSE
		BEGIN
			DECLARE MiCurPagos CURSOR FOR 
				SELECT	O.Id_Concepto
						,O2.Descripcion	AS Rubro 
						,O1.Descripcion	AS SubRubro 
						,O.Descripcion	AS Concepto
						,ISNULL(C.Id_Proveedor,0) AS Id_Dest
						,ISNULL(P.Razon_Social,'') AS Proveedor
						,SUM(ISNULL(CO.Importe,0))
					FROM Cajas_Mov_Conceptos CO
						, Cbtes C
						LEFT JOIN Proveedores P ON C.Id_Proveedor = P.Id_Proveedor
						, Cbtes_Tipos T
						, Conceptos O LEFT JOIN Conceptos O1 ON O1.Id_Concepto = O.Id_Concepto_Padre
						LEFT JOIN Conceptos O2 ON O2.Id_Concepto = O1.Id_Concepto_Padre
					WHERE CO.Id_Trans = C.Id_Trans
					AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
					AND CO.Id_Concepto = O.Id_Concepto
					AND C.Id_Estado_Cbte IN (1,2,4)
					AND T.Compromete_Pagos IN (1,-1)
					AND DATEPART(YEAR,C.Fecha) = @pAnio
					AND DATEPART(MONTH,C.Fecha) = @Mes
					AND CO.Id_Periodo_Caja IN (SELECT Id_Periodo_Caja FROM #Cajas_Periodos )
					GROUP BY O.Id_Concepto,O2.Descripcion, O1.Descripcion, O.Descripcion,C.Id_Proveedor,P.Razon_Social
					ORDER BY O2.Descripcion, O1.Descripcion, O.Descripcion,C.Id_Proveedor,P.Razon_Social
		END
	END --IF @pCircuito IN ('','P')


	IF @pCircuito = 'R'
	BEGIN
		IF @pFlag_Apertura = 0
		BEGIN

			DECLARE MiCurPagos CURSOR FOR 
				SELECT	O.Id_Concepto
						,O2.Descripcion	AS Rubro 
						,O1.Descripcion	AS SubRubro 
						,O.Descripcion	AS Concepto
						,0 AS Id_Dest
						,'' AS Destinatario
						,SUM(ISNULL(CO.Importe,0))
					FROM Cajas_Mov_Conceptos CO
						, Cbtes C
						LEFT JOIN Clientes Cli ON C.Id_Cliente = Cli.Id_Cliente
						, Cbtes_Tipos T
						, Conceptos O LEFT JOIN Conceptos O1 ON O1.Id_Concepto = O.Id_Concepto_Padre
						LEFT JOIN Conceptos O2 ON O2.Id_Concepto = O1.Id_Concepto_Padre
				
					WHERE CO.Id_Trans = C.Id_Trans
					AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
					AND CO.Id_Concepto = O.Id_Concepto
					AND C.Id_Estado_Cbte IN (1,2,4)
					AND T.Compromete_Recibos IN (1,-1)
					AND DATEPART(YEAR,C.Fecha) = @pAnio
					AND DATEPART(MONTH,C.Fecha) = @Mes
					AND CO.Id_Periodo_Caja IN (SELECT Id_Periodo_Caja FROM #Cajas_Periodos )
					GROUP BY O.Id_Concepto,O2.Descripcion, O1.Descripcion, O.Descripcion
					ORDER BY O2.Descripcion, O1.Descripcion, O.Descripcion
		END
		ELSE
		BEGIN
			DECLARE MiCurPagos CURSOR FOR 
				SELECT	O.Id_Concepto
						,O2.Descripcion	AS Rubro 
						,O1.Descripcion	AS SubRubro 
						,O.Descripcion	AS Concepto
						,ISNULL(C.Id_Cliente,0) AS Id_Dest
						,ISNULL(Cli.Razon_Social,'') AS Destinatario
						,SUM(ISNULL(CO.Importe,0))
					FROM Cajas_Mov_Conceptos CO
						, Cbtes C
						LEFT JOIN Clientes Cli ON C.Id_Cliente = Cli.Id_Cliente
						, Cbtes_Tipos T
						, Conceptos O LEFT JOIN Conceptos O1 ON O1.Id_Concepto = O.Id_Concepto_Padre
						LEFT JOIN Conceptos O2 ON O2.Id_Concepto = O1.Id_Concepto_Padre
					WHERE CO.Id_Trans = C.Id_Trans
					AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
					AND CO.Id_Concepto = O.Id_Concepto
					AND C.Id_Estado_Cbte IN (1,2,4)
					AND T.Compromete_Recibos IN (1,-1)
					AND DATEPART(YEAR,C.Fecha) = @pAnio
					AND DATEPART(MONTH,C.Fecha) = @Mes
					AND CO.Id_Periodo_Caja IN (SELECT Id_Periodo_Caja FROM #Cajas_Periodos )
					GROUP BY O.Id_Concepto,O2.Descripcion, O1.Descripcion, O.Descripcion,C.Id_Cliente,Cli.Razon_Social
					ORDER BY O2.Descripcion, O1.Descripcion, O.Descripcion,Cli.Razon_Social
		END
	END --IF @pCircuito ='R'


	IF @pCircuito = 'C'
	BEGIN
		IF @pFlag_Apertura = 0
		BEGIN

			DECLARE MiCurPagos CURSOR FOR 
				SELECT	O.Id_Concepto
						,O2.Descripcion	AS Rubro 
						,O1.Descripcion	AS SubRubro 
						,O.Descripcion	AS Concepto
						,0 AS Id_Dest
						,'' AS Destinatario
						,SUM(ISNULL(CO.Importe,0))
					FROM Cbtes_Conceptos CO
						, Cbtes C
						LEFT JOIN Proveedores P ON C.Id_Proveedor = P.Id_Proveedor
						, Cbtes_Tipos T
						, Conceptos O LEFT JOIN Conceptos O1 ON O1.Id_Concepto = O.Id_Concepto_Padre
						LEFT JOIN Conceptos O2 ON O2.Id_Concepto = O1.Id_Concepto_Padre
					WHERE CO.Id_Trans = C.Id_Trans
					AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
					AND CO.Id_Concepto = O.Id_Concepto
					AND C.Id_Estado_Cbte IN (1,2,4)
					AND T.Compromete_Compras IN (1,-1)
					AND DATEPART(YEAR,C.Fecha) = @pAnio
					AND DATEPART(MONTH,C.Fecha) = @Mes
					GROUP BY O.Id_Concepto,O2.Descripcion, O1.Descripcion, O.Descripcion
					ORDER BY O2.Descripcion, O1.Descripcion, O.Descripcion
		END
		ELSE
		BEGIN
			DECLARE MiCurPagos CURSOR FOR 
				SELECT	O.Id_Concepto
						,O2.Descripcion	AS Rubro 
						,O1.Descripcion	AS SubRubro 
						,O.Descripcion	AS Concepto
						,ISNULL(C.Id_Proveedor,0) AS Id_Dest
						,ISNULL(P.Razon_Social,'') AS Proveedor
						,SUM(ISNULL(CO.Importe,0))
					FROM Cbtes_Conceptos CO
						, Cbtes C
						LEFT JOIN Proveedores P ON C.Id_Proveedor = P.Id_Proveedor
						, Cbtes_Tipos T
						, Conceptos O LEFT JOIN Conceptos O1 ON O1.Id_Concepto = O.Id_Concepto_Padre
						LEFT JOIN Conceptos O2 ON O2.Id_Concepto = O1.Id_Concepto_Padre
					WHERE CO.Id_Trans = C.Id_Trans
					AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
					AND CO.Id_Concepto = O.Id_Concepto
					AND C.Id_Estado_Cbte IN (1,2,4)
					AND T.Compromete_Compras IN (1,-1)
					AND DATEPART(YEAR,C.Fecha) = @pAnio
					AND DATEPART(MONTH,C.Fecha) = @Mes
					GROUP BY O.Id_Concepto,O2.Descripcion, O1.Descripcion, O.Descripcion,C.Id_Proveedor,P.Razon_Social
					ORDER BY O2.Descripcion, O1.Descripcion, O.Descripcion,C.Id_Proveedor,P.Razon_Social
		END
	END --IF @pCircuito = 'C'



	IF @pCircuito = 'V'
	BEGIN
		IF @pFlag_Apertura = 0
		BEGIN

			DECLARE MiCurPagos CURSOR FOR 
				SELECT	1
						,'Ventas'	AS Rubro 
						,'Ventas'	AS SubRubro 
						,'Ventas'	AS Concepto
						,0 AS Id_Dest
						,'' AS Destinatario
						,SUM(ISNULL(C.Imp_Total *  T.Compromete_Factura,0))
					FROM Cbtes C
						LEFT JOIN Clientes Cli ON C.Id_Cliente = Cli.Id_Cliente
						, Cbtes_Tipos T
			
					WHERE C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
					AND C.Id_Estado_Cbte IN (1,2,4)
					AND T.Compromete_Factura IN (1,-1) 
					AND DATEPART(YEAR,C.Fecha) = @pAnio
					AND DATEPART(MONTH,C.Fecha) = @Mes
					--GROUP BY 1
					ORDER BY 1
		END
		ELSE
		BEGIN
			DECLARE MiCurPagos CURSOR FOR 
				SELECT	1
						,'Ventas'	AS Rubro 
						,'Ventas'	AS SubRubro 
						,'Ventas'	AS Concepto
						,ISNULL(C.Id_Cliente,0) AS Id_Dest
						,ISNULL(Cli.Razon_Social,'') AS Destinatario
						,SUM(ISNULL(C.Imp_Total * T.Compromete_Factura ,0))
					FROM Cbtes C
						LEFT JOIN Clientes Cli ON C.Id_Cliente = Cli.Id_Cliente
						, Cbtes_Tipos T
						
					WHERE C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
					AND C.Id_Estado_Cbte IN (1,2,4)
					AND T.Compromete_Factura IN (1,-1)
					AND DATEPART(YEAR,C.Fecha) = @pAnio
					AND DATEPART(MONTH,C.Fecha) = @Mes
					GROUP BY C.Id_Cliente,Cli.Razon_Social
					ORDER BY Cli.Razon_Social
		END
	END --IF @pCircuito ='V'

	IF @pCircuito IN ('','N')
	BEGIN
		IF @pFlag_Apertura = 0
		BEGIN

			DECLARE MiCurPagos CURSOR FOR 
				SELECT	O.Id_Concepto
						,O2.Descripcion	AS Rubro 
						,O1.Descripcion	AS SubRubro 
						,O.Descripcion	AS Concepto
						,0 AS Id_Dest
						,'' AS Destinatario
						,SUM(Convert(Decimal(20,2),Abs(ISNULL(CO.Importe,0)) * abs(ISNULL(V.Importe,0))/(ABS(ISNULL(C.Imp_total,0))+ABS(ISNULL(C.Imp_percep,0)))*-1)) AS Importe
				--		,SUM(ISNULL(V.Importe*-1,0)) AS Importe
					FROM Cajas_Mov_Conceptos CO
						, Cbtes C
						LEFT JOIN Proveedores P ON C.Id_Proveedor = P.Id_Proveedor
						, Cbtes_Tipos T
						, Valores V
						  LEFT JOIN Bancos_Ctas_Mov B  on V.ID_TRANS = B.ID_TRANS 
						                          AND CONVERT(VARCHAR(20),V.Valor_Nro) = CONVERT(VARCHAR(20),B.COMPROBANTE_NRO)
												  AND ABS(V.Importe) = ABS(B.Importe)
						, Valores_Mov M
						, Conceptos O LEFT JOIN Conceptos O1 ON O1.Id_Concepto = O.Id_Concepto_Padre
						LEFT JOIN Conceptos O2 ON O2.Id_Concepto = O1.Id_Concepto_Padre
					WHERE CO.Id_Trans = C.Id_Trans
					AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
					AND CO.Id_Concepto = O.Id_Concepto
					AND C.Id_Estado_Cbte IN (1,2,4)
					AND T.Compromete_Pagos IN (1,-1)
					AND M.Id_Trans = C.Id_Trans
					AND V.Id_Valor = M.ID_VALOR
					AND  V.Id_Tipo_Val Not In ('AJU','DES')
					AND ((V.Id_Tipo_Val In ('CHP','DB') AND B.CONCILIADO  = 1 AND B.CONCILIADO IS Not NULL)
					OR V.Id_Tipo_Val In ('EFE','TAR','FIN') )
					AND DATEPART(YEAR,isnull(B.Fecha_Acreditacion,ISNULL(V.Fecha_Acreditacion,C.fecha))) = @pAnio
					AND DATEPART(MONTH,isnull(B.Fecha_Acreditacion,ISNULL(V.Fecha_Acreditacion,C.fecha))) = @Mes
					AND CO.Id_Periodo_Caja IN (SELECT Id_Periodo_Caja FROM #Cajas_Periodos )
					GROUP BY O.Id_Concepto,O2.Descripcion, O1.Descripcion, O.Descripcion
					ORDER BY O2.Descripcion, O1.Descripcion, O.Descripcion
		END
		ELSE
		BEGIN
			DECLARE MiCurPagos CURSOR FOR 
				SELECT	O.Id_Concepto
						,O2.Descripcion	AS Rubro 
						,O1.Descripcion	AS SubRubro 
						,O.Descripcion	AS Concepto
						,ISNULL(C.Id_Proveedor,0) AS Id_Dest
						,ISNULL(P.Razon_Social,'') AS Proveedor
						,SUM(Abs(ISNULL(CO.Importe,0)) * abs(ISNULL(V.Importe,0))/(ABS(ISNULL(C.Imp_total,0))+ABS(ISNULL(C.Imp_percep,0)))*-1)  AS Importe

--						,SUM(ISNULL(V.Importe*-1,0)) AS Importe
					FROM Cajas_Mov_Conceptos CO
						, Cbtes C
						LEFT JOIN Proveedores P ON C.Id_Proveedor = P.Id_Proveedor
						, Cbtes_Tipos T
						, Valores V
						  LEFT JOIN Bancos_Ctas_Mov B  on V.ID_TRANS = B.ID_TRANS 
						                          AND CONVERT(VARCHAR(20),V.Valor_Nro) = CONVERT(VARCHAR(20),B.COMPROBANTE_NRO)
												  AND ABS(V.Importe) = ABS(B.Importe)
						, Valores_Mov M
						, Conceptos O LEFT JOIN Conceptos O1 ON O1.Id_Concepto = O.Id_Concepto_Padre
						LEFT JOIN Conceptos O2 ON O2.Id_Concepto = O1.Id_Concepto_Padre
					WHERE CO.Id_Trans = C.Id_Trans
					AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
					AND CO.Id_Concepto = O.Id_Concepto
					AND C.Id_Estado_Cbte IN (1,2,4)
					AND T.Compromete_Pagos IN (1,-1)
					AND M.Id_Trans = C.Id_Trans
					AND V.Id_Valor = M.ID_VALOR
					AND  V.Id_Tipo_Val Not In ('AJU','DES')
					AND ((V.Id_Tipo_Val In ('CHP','DB') AND B.CONCILIADO  = 1 AND B.CONCILIADO IS Not NULL)
					OR V.Id_Tipo_Val In ('EFE','TAR','FIN') )
					AND DATEPART(YEAR,isnull(B.Fecha_Acreditacion,ISNULL(V.Fecha_Acreditacion,C.fecha))) = @pAnio
					AND DATEPART(MONTH,isnull(B.Fecha_Acreditacion,ISNULL(V.Fecha_Acreditacion,C.fecha))) = @Mes
					AND CO.Id_Periodo_Caja IN (SELECT Id_Periodo_Caja FROM #Cajas_Periodos )
					GROUP BY O.Id_Concepto,O2.Descripcion, O1.Descripcion, O.Descripcion,C.Id_Proveedor,P.Razon_Social
					ORDER BY O2.Descripcion, O1.Descripcion, O.Descripcion,C.Id_Proveedor,P.Razon_Social
		END
	END --IF @pCircuito IN ('','P')


	OPEN MiCurPagos
	FETCH NEXT FROM MiCurPagos INTO @Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe
	WHILE (@@FETCH_STATUS=0)
	BEGIN
		IF @Mes = 1
		BEGIN
			
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes1)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes1	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END
		IF @Mes = 2
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes2)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes2	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END
		IF @Mes = 3
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes3)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes3	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END
		IF @Mes = 4
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes4)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes4	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END
		IF @Mes = 5
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes5)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes5	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END
		IF @Mes = 6
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes6)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes6	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END
		IF @Mes = 7
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes7)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes7	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END
		IF @Mes = 8
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes8)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes8	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END
		IF @Mes = 9
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes9)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes9	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END
		IF @Mes = 10
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes10)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes10	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END
		IF @Mes = 11
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes11)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes11	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END
		IF @Mes = 12
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM #Reporte WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest)
				INSERT INTO #Reporte  (Id_Concepto, Rubro, SubRubro, Concepto,Id_Dest,Destinatario,Mes12)
				VALUES (@Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe)
			ELSE
				UPDATE #Reporte SET Mes12	= @Importe WHERE Id_Concepto = @Id_Concepto AND Id_Dest = @Id_Dest
		END


		FETCH NEXT FROM MiCurPagos INTO @Id_Concepto,@Rubro,@SubRubro,@Concepto,@Id_Dest,@Destinatario,@Importe
	END
	CLOSE MiCurPagos
	DEALLOCATE MiCurPagos
	SET @Mes += 1
END

--ALTER TABLE #Reporte DROP COLUMN Importe
UPDATE #Reporte SET Total = Mes1 + Mes2 + Mes3 + Mes4 + Mes5 + Mes6 + Mes7 + Mes8 + Mes9 + Mes10 + Mes11 + Mes12
UPDATE #Reporte SET Concepto = '' WHERE Concepto IS NULL
UPDATE #Reporte SET SubRubro = Concepto WHERE SubRubro IS NULL OR SubRubro = ''
UPDATE #Reporte SET Rubro = SubRubro WHERE Rubro IS NULL OR Rubro = ''


IF @pNivel = 'R'
	SELECT Rubro,SUM(Importe)	AS Importe
				,SUM(Mes1 )		AS Mes1 
				,SUM(Mes2 )		AS Mes2 
				,SUM(Mes3 )		AS Mes3 
				,SUM(Mes4 )		AS Mes4 
				,SUM(Mes5 )		AS Mes5 
				,SUM(Mes6 )		AS Mes6 
				,SUM(Mes7 )		AS Mes7 
				,SUM(Mes8 )		AS Mes8 
				,SUM(Mes9 )		AS Mes9 
				,SUM(Mes10)		AS Mes10
				,SUM(Mes11)		AS Mes11
				,SUM(Mes12)		AS Mes12
				,SUM(Total)		AS Total
			FROM #Reporte GROUP BY Rubro ORDER BY Rubro
ELSE IF @pNivel = 'S'
	SELECT Rubro,SubRubro,SUM(Importe)	AS Importe
				,SUM(Mes1 )		AS Mes1 
				,SUM(Mes2 )		AS Mes2 
				,SUM(Mes3 )		AS Mes3 
				,SUM(Mes4 )		AS Mes4 
				,SUM(Mes5 )		AS Mes5 
				,SUM(Mes6 )		AS Mes6 
				,SUM(Mes7 )		AS Mes7 
				,SUM(Mes8 )		AS Mes8 
				,SUM(Mes9 )		AS Mes9 
				,SUM(Mes10)		AS Mes10
				,SUM(Mes11)		AS Mes11
				,SUM(Mes12)		AS Mes12
				,SUM(Total)		AS Total
			FROM #Reporte GROUP BY Rubro,SubRubro ORDER BY Rubro,SubRubro
ELSE
	SELECT * FROM #Reporte ORDER BY Rubro,SubRubro,Concepto,Destinatario
	

DROP TABLE #Reporte


