									C.Id_Tipo_Con = @Id_Tipo_Con
									AND C.Id_Tipo_Con <> 0
									AND C.Id_Producto <> ''
									AND C.Id_Producto = P.Id_Producto
									AND T.Id_Iva = P.Id_Iva)
	
    IF (@Contratos_Tipos_Prod_cant > 0)
	BEGIN
