				PRINT CONVERT(VARCHAR(23), GETDATE(), 121) + ': ' + '@Flag_Mes_Desglo: ' + CONVERT(VARCHAR(10), @Flag_Mes_Desglo) + '. @Cantidad: ' + CONVERT(VARCHAR(20), @Cantidad)
			END

