CREATE PROCEDURE [dbo].[CPJ_Contratos_Generar] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*Variables recibidas por par╗metro a traves del JSON*/
DECLARE @pFlagUsarTrans				TINYINT
DECLARE @pModoDebug					TINYINT
DECLARE @pId_Usuario				SMALLINT
DECLARE @pId_Tipo_Con				INT
DECLARE @pFecha_Desde				DATETIME
DECLARE @pFecha_Hasta				DATETIME
DECLARE @pId_Cliente				INT
DECLARE @pId_Grupo_Cont				CHAR(10)
DECLARE @pId_SubGrupo_Cont			CHAR(10)
DECLARE @pId_Lista_Precio			INT
DECLARE @pId_Tipo_Cbte				CHAR(5)
DECLARE @pObservacion				VARCHAR(5000)
DECLARE @descrip					VARCHAR(200)
DECLARE @pFlag_Sistema 				TINYINT 
DECLARE @pId_Tiempo					CHAR(3) 
DECLARE @pPorc_Bonif				DECIMAL(5,2)
DECLARE @pObservacion_Fact			VARCHAR(5000)
DECLARE @pFlag_Forma_Pago_Cliente	TINYINT 
DECLARE @pId_Tipo_Con_Forma_Pago	INT 

DECLARE @pFlag_Contratos_Productos				TINYINT 
DECLARE @pContratos_Productos_Id_Producto		VARCHAR(14) 
DECLARE @pFlag_Contratos_Productos_Facturable	TINYINT 


SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Tipo_Con				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Con')), 0)
SET @pId_Usuario				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), -1)
SET @pFecha_Desde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde')),'19000101')
SET @pFecha_Hasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta')),'')
SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Grupo_Cont				= ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Grupo_Cont')), '')
SET @pId_SubGrupo_Cont			= ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_SubGrupo_Cont')), '')
SET @pId_Lista_Precio			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Lista_Precio')), 0)
SET @pId_Tipo_Cbte				= ISNULL(CONVERT(CHAR(5), dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Cbte')), '')
SET @pObservacion				= ISNULL(CONVERT(VARCHAR(5000), dbo.CF_JSON_VALUE(@pJson,'Observacion')), '')
SET @pObservacion_Fact			= ISNULL(CONVERT(VARCHAR(5000), dbo.CF_JSON_VALUE(@pJson,'Observacion_Fact')), '')
SET @pId_Tiempo					= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Id_Tiempo')), '')
SET @pPorc_Bonif				= ISNULL(CONVERT(DECIMAL(5,2), dbo.CF_JSON_VALUE(@pJson,'Porc_Bonif')), 0)
SET @pFlag_Sistema				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Sistema')), 0)
SET @pFlag_Forma_Pago_Cliente	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Forma_Pago_Cliente')), 0)
SET @pId_Tipo_Con_Forma_Pago	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Tipo_Con_Forma_Pago')), 0)
SET @pFlag_Contratos_Productos				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Contratos_Productos')), 0)
SET @pContratos_Productos_Id_Producto		= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), '')
SET @pFlag_Contratos_Productos_Facturable	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Contratos_Productos_Facturable')), 0)

IF(@pModoDebug = 1) PRINT 'Guardó todas las variables del json'

SET @descrip				= (SELECT Descripcion FROM Contratos_Tipos WHERE Id_Tipo_Con = @pId_Tipo_Con)

/*FIN Variables recibidas por par╗metro a traves del JSON*/


/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Contrato			INT
DECLARE @Cliente_Id_Iva			CHAR(3)
DECLARE @Cliente_Id_Tarjeta		VARCHAR(10)
DECLARE @Cliente_Id_Banco		SMALLINT 
DECLARE @Cliente_Id_Cta_Banco	INT
DECLARE @Cliente_Tar_Nro		VARCHAR(50)
DECLARE @Id_Tarjeta				VARCHAR(10)
DECLARE @Id_Banco				SMALLINT 
DECLARE @Id_Cta_Banco			INT
DECLARE @Tar_Nro				VARCHAR(50)
DECLARE @Id_Cond_Pago			INT

SET @Id_Tarjeta		= NULL
SET @Id_Banco		= NULL
SET @Id_Cta_Banco	= NULL
SET @Tar_Nro		= NULL


SELECT 
	@Cliente_Id_Iva			= ISNULL(Id_Iva, ''), 
	@Cliente_Id_Tarjeta		= ISNULL(Id_Tarjeta, ''), 
	@Cliente_Id_Banco		= ISNULL(Id_Banco, 0), 
	@Cliente_Id_Cta_Banco	= ISNULL(Id_Cta_Banco, 0), 
	@Cliente_Tar_Nro		= ISNULL(Tar_Nro, '') ,
	@Id_Cond_Pago			= ISNULL(Id_Cond_Pago,0)
FROM Clientes WHERE Id_Cliente = @pId_Cliente 

/*Fin de Declaraciones Variables Locales */

IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0 
	SET @pFlagUsarTrans = 0

BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Contratos_Generar'
	END
	
	/*===================================================================*/

	
	IF(@pId_Cliente = 0)  RAISERROR ('Id_Cliente can not be zero.', 16,  1 )
	IF(@pId_Tipo_Con = 0)  RAISERROR ('Id_Tipo_Con can not be zero.', 16,  1 )

		
	/*===================================================================*/
	
	IF(@pId_Usuario = 0)
	BEGIN
		SET @pId_Usuario = -1
	END


	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Inserto en Contratos.'
	END

	IF (@pFecha_Hasta='')
	BEGIN
		SET	@pFecha_Hasta= NULL
		-- PRINT @pFecha_Hasta
	END

	IF (@pId_Lista_Precio=0) 
	BEGIN 
		SET @pId_Lista_Precio =(SELECT Id_Lista_Precio FROM Clientes WHERE Id_Cliente=@pId_Cliente) 
	END
	
	IF (@Cliente_Id_Iva = dbo.CF_xParam('Iva_RI')) 
	BEGIN  
		SET @pId_Tipo_Cbte = (SELECT ISNULL(Id_Tipo_Cbte_Ri,'') FROM Contratos_Tipos WHERE Id_Tipo_Con=@pId_Tipo_Con)
	END 
	ELSE 
	BEGIN 
		SET @pId_Tipo_Cbte = (SELECT ISNULL(Id_Tipo_Cbte,'') FROM Contratos_Tipos WHERE Id_Tipo_Con=@pId_Tipo_Con)
	END 


	IF (@pId_Tiempo = '')
	BEGIN
		SET	@pId_Tiempo = NULL
	END
	
	IF (@pFlag_Forma_Pago_Cliente = 1)
	BEGIN
		IF (@Cliente_Id_Tarjeta <> '' OR @Cliente_Id_Cta_Banco <> 0)
		BEGIN
			SET @Id_Tarjeta		= @Cliente_Id_Tarjeta				
			SET @Id_Banco		= @Cliente_Id_Banco		
			SET @Id_Cta_Banco	= @Cliente_Id_Cta_Banco	
			SET @Tar_Nro		= @Cliente_Tar_Nro		
		END 
		ELSE 
		BEGIN 
			IF(@pId_Tipo_Con_Forma_Pago <> 0)
			BEGIN 
				SELECT 
					TOP 1 
					@Id_Tarjeta		= ISNULL(Id_Tarjeta, ''), 
					@Id_Banco		= ISNULL(Id_Banco, 0), 
					@Id_Cta_Banco	= ISNULL(Id_Cta_Banco, 0), 
					@Tar_Nro		= ISNULL(Tar_Nro, '') 
				FROM Contratos 
				WHERE 
					Id_Tipo_Con = @pId_Tipo_Con_Forma_Pago AND 
					Activo = 1 AND Id_Cliente = @pId_Cliente
				ORDER BY Id_Contrato DESC
			END 
		END 
	END

	IF(@pId_Tipo_Con_Forma_Pago <> 0)
	BEGIN 
		SELECT 
			TOP 1 
			@Id_Tarjeta		= ISNULL(Id_Tarjeta, ''), 
			@Id_Banco		= ISNULL(Id_Banco, 0), 
			@Id_Cta_Banco	= ISNULL(Id_Cta_Banco, 0), 
			@Tar_Nro		= ISNULL(Tar_Nro, '') 
		FROM Contratos 
		WHERE 
			Id_Tipo_Con = @pId_Tipo_Con_Forma_Pago AND 
			Activo = 1 AND Id_Cliente = @pId_Cliente 
		ORDER BY Id_Contrato DESC 
	END 

	IF(@Id_Cond_Pago = 0)
	BEGIN
		SET @Id_Cond_Pago = dbo.CF_xParam('Cond_pago_Lotes_Cont')
	END

	SET @Id_Contrato = ISNULL((SELECT MAX(Id_Contrato) FROM Contratos), 0) + 1

	INSERT INTO Contratos (
		Id_Contrato, 
		Id_Tipo_Con,
		Id_Cond_Pago, 
		Id_Cliente, 
		Fecha_Alta, 
		Fecha_Desde, 
		Fecha_Hasta, 
		Id_Grupo_Cont, 
		Id_SubGrupo_Cont, 
		Id_Usuario_Alta, 
		Activo, 
		Id_Lista_Precio,
		Id_Tipo_Cbte,
		Observacion,
		Observa_Fact,
		Descripcion,
		Flag_Sistema,
		Id_Tiempo, 
		Porc_Bonif, 
		Id_Tarjeta,
		Id_Banco,
		Id_Cta_Banco,
		Tar_Nro 
	) VALUES (
		@Id_Contrato,
		@pId_Tipo_Con,
		@Id_Cond_Pago,
		@pId_Cliente, 
		GETDATE(),
		@pFecha_Desde,
		@pFecha_Hasta,
		@pId_Grupo_Cont,
		@pId_SubGrupo_Cont,
		@pId_Usuario,
		1,
		@pId_Lista_Precio,
		@pId_Tipo_Cbte,
		@pObservacion,
		@pObservacion_Fact, 
		@descrip,
		@pFlag_Sistema,
		@pId_Tiempo, 
		@pPorc_Bonif, 
		@Id_Tarjeta,
		@Id_Banco,
		@Id_Cta_Banco,
		@Tar_Nro
	)

	/*======================= CONTRATOS PRODUCTOS ===============================*/

	IF(@pFlag_Contratos_Productos = 1) 
	BEGIN 
		IF(@pContratos_Productos_Id_Producto = '')  SET @pContratos_Productos_Id_Producto = NULL 

		INSERT INTO Contratos_Prod (
			Id_Contrato, 
			Item, 
			Id_Producto, 
			Cantidad, 
			Precio, 
			Flag_Facturable 
		) VALUES (
			@Id_Contrato, 
			1, 
			@pContratos_Productos_Id_Producto, 
			1, 
			0,
			@pFlag_Contratos_Productos_Facturable
		)
	END 

	/*===================================================================*/	

	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END
	
	/*===================================================================*/	
	
	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('id_contrato', @Id_Contrato, 'INT')  + ',' +
								dbo.CF_Json_ParsearVariable('id_cliente', @pId_Cliente, 'INT')  + ',' +
								'}'
								
	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,@Id_Contrato		AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Contratos_Generar'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Contratos_Horarios_Generar] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 
/*Variables recibidas por par▀metro a traves del JSON*/
DECLARE @pFlagUsarTrans		TINYINT
DECLARE @pModoDebug			TINYINT
DECLARE @pId_Contrato		INT
DECLARE @pId_Prod_Familia_Horario	VARCHAR(14)
DECLARE @pItem				INT

/*				*/
SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Contrato			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Contrato')), 0)
SET @pItem					= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Item')), 1)
SET @pId_Prod_Familia_Horario= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), 0)
/*FIN Variables recibidas por par▀metro a traves del JSON*/


/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion Variables Locales*/
DECLARE @Id_Contrato_Prod_Horario INT
/*Fin de Declaraciones Variables Locales */



BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Contratos_Horarios_Generar'
	END
	
	/*===================================================================*/


	/*===================================================================*/

	
	IF(@pId_Contrato = 0)  RAISERROR ('Id_Contrato can not be zero.', 16,  1 )

		
	/*===================================================================*/
	
	

