CREATE PROCEDURE dbo.CPJ_Item_Paid_On_Date @pJSon	VARCHAR(8000)
AS
SET NOCOUNT ON 

/*Variables recibidas por parßmetro a traves del JSON*/
DECLARE	@pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Cliente			INT
DECLARE @pId_Productos			VARCHAR(7900)
DECLARE @pFecha					DATETIME

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Productos				= ISNULL(CONVERT(VARCHAR(7900), dbo.CF_JSON_VALUE(@pJson,'Id_Productos')), 0) /**/
SET @pFecha						= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')), 0)
/*FIN Variables recibidas por parßmetro a traves del JSON*/

/*Declaracion Variables Locales*/
DECLARE	@rtaMsjStored						VARCHAR(100)
DECLARE @SqlStr								NVARCHAR(MAX)
DECLARE @SqlStrNotNull						NVARCHAR(MAX)
DECLARE @Parametros							NVARCHAR(100)
DECLARE @Id_Producto						VARCHAR(14)
DECLARE @Flag_Item_Pagado					TINYINT
DECLARE @Fecha_DATE							DATE
DECLARE @Fecha_DATE_VARCHAR					VARCHAR(8)
DECLARE @posicion							INT
DECLARE @longitud							INT
DECLARE @Cada_Id_Producto					VARCHAR(14)
DECLARE @Lista_Id_Productos					VARCHAR(7900)
/*Fin de Declaraciones Variables Locales */


BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Item_Paid_On_Date'
		PRINT 'Parametros:'
		PRINT 'pJSon: ' + CONVERT(VARCHAR(8000), @pJSon)		
	END
	
	/*===================================================================*/
	
	SET @Fecha_DATE			=	CONVERT(DATE, @pFecha)
	
	SET @Fecha_DATE_VARCHAR =	CONVERT(VARCHAR(4), DATEPART(YEAR, @Fecha_DATE))	+ 
								RIGHT('00' + CAST(DATEPART(MONTH, @Fecha_DATE) AS VARCHAR), 2) +
								RIGHT('00' + CAST(DATEPART(DAY, @Fecha_DATE) AS VARCHAR), 2)
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fecha_DATE_VARCHAR: ' + @Fecha_DATE_VARCHAR
	END
	
	/*===================================================================*/
	
	SET @pId_Productos = LTRIM(RTRIM(@pId_Productos))
	
	IF(@pModoDebug = 1)
	BEGIN	
		PRINT 'pId_Productos: ' + @pId_Productos
	END
	
	IF(LEN(@pId_Productos) = 0)
	BEGIN
		/*No mandaron ningun Producto a validar, Sale del Stored*/
		SET @rtaMsjStored		=	'{' +
									dbo.CF_Json_ParsearVariable('Flag_Item_Pagado', 0, 'TINYINT') +
									'}'

		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage
				
		RETURN 0
	END
	
	IF (SUBSTRING(@pId_Productos, LEN(@pId_Productos)-1, 1) <> ',')
	BEGIN
		SET @pId_Productos = @pId_Productos + ','
	END
	
	SET @posicion = 0
	SET @longitud = 0
	SET @Lista_Id_Productos = ''
	
	WHILE CHARINDEX(',', @pId_Productos, @posicion + 1) > 0
	BEGIN
		SET @longitud			= CHARINDEX(',', @pId_Productos, @posicion + 1) - @posicion
		SET @Cada_Id_Producto	= SUBSTRING(@pId_Productos, @posicion, @longitud)
		
		
		IF(@Lista_Id_Productos = '')
		BEGIN
			SET @Lista_Id_Productos = '''' + @Cada_Id_Producto + ''''
		END
		ELSE
		BEGIN
			SET @Lista_Id_Productos = LTRIM(RTRIM(@Lista_Id_Productos)) + ',''' + @Cada_Id_Producto + ''''
		END
		
		SET @posicion = CHARINDEX(',', @pId_Productos, @posicion + @longitud) +1
	END
	
	IF (@pModoDebug = 1)
	BEGIN	
		PRINT 'Lista_Id_Productos: ' + @Lista_Id_Productos
	END
	
	/*===================================================================*/
	
	SET @Flag_Item_Pagado = 0
	
	/*===================================================================*/
	
	SET @Parametros = N'@Id_ProductoOUT VARCHAR(14) OUTPUT'; 
	
	/*===================================================================*/
	
	SET @SqlStr = 'SELECT @Id_ProductoOUT = ISNULL(MAX(CI.Id_Producto),'''')'
	
	/*===================================================================*/
	
	SET @SqlStr = RTRIM(LTRIM(@SqlStr))																+ CHAR(13) + 
				' FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR'
	
	/*===================================================================*/
	
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr))															+ CHAR(13) + 
					' WHERE'																		+ CHAR(13) + 
					' CB.Id_Trans = CI.Id_Trans'													+ CHAR(13) +
					' AND ISNULL(CB.Id_Tipo_Cbte, '''') = CT.Id_Tipo_Cbte'							+ CHAR(13) +
					' AND ISNULL(CI.Id_Producto, '''') = PR.Id_Producto'							+ CHAR(13) +
					' AND CI.Id_Cliente = '+ CAST(@pId_Cliente AS VARCHAR(10))						+ CHAR(13) +
					' AND LTRIM(RTRIM(ISNULL(CI.Id_Producto, ''''))) IN (' + @Lista_Id_Productos + ')'
	
	/*===================================================================*/
	
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr))															+ CHAR(13) + 
					' AND ISNULL(CT.Compromete_Factura, 0) IN (1)'									+ CHAR(13) + 
					' AND ((ISNULL(CB.Id_Estado_Cbte, 0) = 2) OR (ISNULL(CB.Id_Estado_Cbte, 0) IN (1, 4) AND ISNULL(CI.Imp_Final, 0) = 0))'

	/*===================================================================*/
	
	--No controla ni mes ni periodo, con que alguna vez lo haya pagado esta ok
	SET @SqlStrNotNull =	RTRIM(LTRIM(@SqlStr))													+ CHAR(13) + 
							' AND ISNULL(PR.Flag_Mes, 0) = 0'										+ CHAR(13) +  
							' AND ISNULL(PR.Flag_Periodo, 0) = 0'
	IF(@pModoDebug = 1)
	BEGIN
		PRINT ''
		PRINT 'No controla ni mes ni periodo, con que alguna vez lo haya pagado esta ok'
		PRINT @SqlStrNotNull
	END
	
	EXECUTE sp_executesql @SqlStrNotNull, @Parametros, @Id_ProductoOUT = @Id_Producto OUTPUT;
	IF (@Id_Producto <> '')
	BEGIN
		SET @Flag_Item_Pagado = 1
	END
	
	/*===================================================================*/

	IF (@Flag_Item_Pagado = 0) --Hasta ahora no encontr¾ ningun producto que cumpla alguna de las condiciones anteriores, cambia la condicion y vuelve a evaluar
	BEGIN
		--Controla mes
		SET @SqlStrNotNull =	RTRIM(LTRIM(@SqlStr))												+ CHAR(13) + 
							' AND ISNULL(PR.Flag_Mes, 0) = 1'										+ CHAR(13) +  
							--' AND ISNULL(PR.Flag_Periodo, 0) = 0' (Con que este tildado mes no importa periodo porque tiene prioridad por sobre periodo)
							' AND dbo.CF_FOMONTH(CONVERT(DATE, ISNULL(CI.Fecha_QA, ''19000101''))) = dbo.CF_FOMONTH(CONVERT(DATE, ''' + @Fecha_DATE_VARCHAR + '''))'
		IF(@pModoDebug = 1)
		BEGIN
			PRINT @SqlStrNotNull
		END
		
		EXECUTE sp_executesql @SqlStrNotNull, @Parametros, @Id_ProductoOUT = @Id_Producto OUTPUT;
		IF (@Id_Producto <> '')
		BEGIN
			PRINT ''
			PRINT 'Controla Mes'
			SET @Flag_Item_Pagado = 1			
		END
	END


	/*===================================================================*/	
	
	IF (@Flag_Item_Pagado = 0) --Hasta ahora no encontr¾ ningun producto que cumpla alguna de las condiciones anteriores, cambia la condicion y vuelve a evaluar
	BEGIN
		--Controla Periodo
		SET @SqlStrNotNull =	RTRIM(LTRIM(@SqlStr))												+ CHAR(13) + 
							' AND ISNULL(PR.Flag_Mes, 0) = 0'										+ CHAR(13) +  
							' AND ISNULL(PR.Flag_Periodo, 0) = 1'									+ CHAR(13) + 
							' AND CONVERT(DATE, ISNULL(CI.Fecha_QA, ''19000101'')) <= ''' +@Fecha_DATE_VARCHAR  + '''' + CHAR(13) + 
							' AND CONVERT(DATE, ISNULL(CI.Fecha_Venc, ''19000101'')) >= ''' + @Fecha_DATE_VARCHAR + '''' 
		IF(@pModoDebug = 1)
		BEGIN
			PRINT @SqlStrNotNull
		END
		
		EXECUTE sp_executesql @SqlStrNotNull, @Parametros, @Id_ProductoOUT = @Id_Producto OUTPUT;
		IF (@Id_Producto <> '')
		BEGIN
			PRINT ''
			PRINT 'Controla Periodo'
			SET @Flag_Item_Pagado = 1			
		END
	END
	
	/*===================================================================*/


	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('flag_paid', @Flag_Item_Pagado, 'TINYINT') +
								'}'


	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Item_Paid_On_Date'
	END

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0 

/*
Ej.
DECLARE @pJson VARCHAR(8000)
SET @pJson =	'{' +
				dbo.CF_Json_ParsearVariable('ModoDebug', 1, 'TINYINT') + ',' +
				dbo.CF_Json_ParsearVariable('Id_Cliente', 2490, 'INT') + ',' +
				dbo.CF_Json_ParsearVariable('Fecha', GETDATE(), 'DATETIME') + 
				dbo.CF_Json_ParsearVariable('Id_Productos', 'CS101,CS102', 'VARCHAR(7900)') + 
				'}'
EXEC dbo.CPJ_Item_Paid_On_Date @pJson
*/
GO


CREATE PROCEDURE [dbo].[CPJ_Localidades_Cliente]		@pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

--MODIFICACIONES:
--01/02/2022 10:40Hs Se agrega validacion con parametro cant_min_reserva
--17/02/2022 17:32Hs Se agrega validacion de Protocolos preasignados
--18/02/2022 08:18Hs Se agrega validacion de Id_Evento_Grupo

/*Variables recibidas por paremetro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Cliente			INT
DECLARE @pId_Lista_Precio		INT
DECLARE @pId_Sector				INT
DECLARE @pFlag_Interface		CHAR(1)

SET @pFlagUsarTrans		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Cliente		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Lista_Precio	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Lista_Precio')), 0)
SET @pId_Sector			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Sector')), 0)
SET @pFlag_Interface	= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJson,'Flag_Interface')), '')	--'G': Grafica Estadio Futbol | '' o 'E': Entradas adquiridas/renovables
/*FIN Variables recibidas por parametro a traves del JSON*/
--EXEC CPJ_Localidades_Cliente '{"ModoDebug":"1","Id_Cliente":"0","Id_Lista_Precio":"2001","Id_Sector":"6","Flag_Interface":"G"}'


/*Variables Locales*/
DECLARE @SqlStr					NVARCHAR(MAX)
DECLARE @SqlStrs				NVARCHAR(MAX)
DECLARE @Id_Cliente_Ref			INT
DECLARE @Cant_Minutos_Reserva	INT
DECLARE @Id_Evento_Grupo		INT
/*FIN Variables Locales*/

BEGIN TRY
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Localidades_Cliente'
		PRINT 'Parametros: '+ @pJson  
	END

	/*====================================================================================================================================================*/
	
	SET @Cant_Minutos_Reserva = (SELECT dbo.CF_xParam('cant_min_reserva'))

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Cant_Minutos_Reserva: '+ CONVERT(VARCHAR(10), @Cant_Minutos_Reserva)  
	END

	/*====================================================================================================================================================*/

	IF(@pId_Cliente > 0)
	BEGIN
		SELECT
		@Id_Cliente_Ref = ISNULL(Id_Cliente_Ref, 0)
		FROM Clientes 
		WHERE
		Id_Cliente = @pId_Cliente

		IF(@Id_Cliente_Ref = 0)
		BEGIN
			SET @Id_Cliente_Ref = @pId_Cliente
		END
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Id_Cliente_Ref: '+ CONVERT(VARCHAR(10), @Id_Cliente_Ref)  
	END

	/*====================================================================================================================================================*/

	--18/02/2022
	IF(@pId_Lista_Precio > 0)
	BEGIN
		SET @Id_Evento_Grupo = ISNULL((SELECT ISNULL(Id_Evento_Grupo, 0) FROM Prod_Listas_Precios WHERE Id_Lista_Precio = @pId_Lista_Precio), 0)
	END

	/*====================================================================================================================================================*/

	IF OBJECT_ID('tempdb..#Rta_CPJ_Localidades_Cliente') IS NOT NULL
	BEGIN
		DROP TABLE #Rta_CPJ_Localidades_Cliente
	END

	CREATE TABLE #Rta_CPJ_Localidades_Cliente (Id_Trans				INT
											, Id_Cliente			INT
											, Id_Lista				INT
											, Razon_Social			VARCHAR(100)
											, Fecha_QA				DATETIME
											, Fecha_Venc			DATETIME
											, Fecha_Desde			DATETIME
											, Fecha_Hasta			DATETIME
											, Descripcion			VARCHAR(100)
											, Id_Producto			VARCHAR(14)
											, Descripcion_Resumida	VARCHAR(100)
											, Estado				VARCHAR(10)
											, Serie					VARCHAR(100))

	/*====================================================================================================================================================*/

	SET @SqlStr =	''

	SET @SqlStr +=	'INSERT INTO #Rta_CPJ_Localidades_Cliente '
	SET @SqlStr +=	' SELECT'
	SET @SqlStr +=	' DISTINCT'
	SET @SqlStr +=	' CB.Id_Trans,'
	SET @SqlStr +=	' ISNULL(CI.Id_Cliente, 0) AS Id_Cliente,'
	SET @SqlStr +=	' ISNULL(CB.Id_Lista, 0) AS Id_Lista,'
	SET @SqlStr +=	' UPPER(LTRIM(RTRIM(ISNULL(CL.Razon_Social, '''')))) AS Razon_Social,'
	SET @SqlStr +=	' CI.Fecha_QA,'
	SET @SqlStr +=	' CI.Fecha_Venc,'
	SET @SqlStr +=	' PLP.Fecha_Desde,'
	SET @SqlStr +=	' PLP.Fecha_Hasta,'
	SET @SqlStr +=	' UPPER(LTRIM(RTRIM(ISNULL(PLP.Descripcion, '''')))) AS Descripcion,'
	SET @SqlStr +=	' UPPER(LTRIM(RTRIM(ISNULL(CI.Id_Producto, '''')))) AS Id_Producto,'
	SET @SqlStr +=	' UPPER(RTRIM(LTRIM(ISNULL(PR.Descripcion_Resumida, '''')))) AS Descripcion_Resumida,'
	SET @SqlStr +=	' CASE 
						WHEN	CONVERT(DATE, ISNULL(CI.Fecha_QA, ''19000101'')) <= CONVERT(DATE, GETDATE()) 
								AND (CONVERT(DATE, ISNULL(CI.Fecha_Venc, ''19000101'')) >= CONVERT(DATE, GETDATE()) OR CI.Fecha_Venc IS NULL) 
								THEN ''C''
						WHEN	ISNULL(PLP.Evento_Cant_Dias_Renov_Prev, 0) > 0 
								AND CONVERT(DATE, ISNULL(CI.Fecha_QA, ''19000101'')) <= CONVERT(DATE, GETDATE()) 
								AND CI.Fecha_Venc IS NOT NULL
								AND CONVERT(DATE, ISNULL(CI.Fecha_Venc, ''19000101'')) >= CONVERT(DATE, GETDATE())
								AND DATEADD(DAY, (-1) *  ISNULL(PLP.Evento_Cant_Dias_Renov_Prev, 0),  ISNULL(CI.Fecha_Venc, ''19000101'')) <= CONVERT(DATE, GETDATE()) 
								THEN ''CR''
						WHEN	ISNULL(PLP.Evento_Cant_Dias_Limite, 0) > 0
								AND CONVERT(DATE, ISNULL(CI.Fecha_QA, ''19000101'')) <= CONVERT(DATE, GETDATE())
								AND CI.Fecha_Venc IS NOT NULL
								AND DATEADD(DAY, ISNULL(PLP.Evento_Cant_Dias_Limite, 0), CONVERT(DATE, CI.Fecha_Venc)) >= CONVERT(DATE, GETDATE())
								THEN ''R''
						WHEN	(ISNULL(PR.Fecha_Reserva, ''19900101'') >= DATEADD(MINUTE,- ' + CONVERT(VARCHAR(5), @Cant_Minutos_Reserva) +  ',GETDATE()))
								THEN ''RP''
						ELSE ''V''
					END Estado,
					CI.Serie'
	SET @SqlStr +=	' FROM Cbtes CB, Cbtes_Items CI, Productos PR, Clientes CL, Prod_Listas_Precios PLP, Cbtes_Tipos CT'
	SET @SqlStr +=	' WHERE'
	SET @SqlStr +=	' CB.Id_Trans = CI.Id_Trans'
	SET @SqlStr +=	' AND CI.Id_Producto = PR.Id_Producto'
	SET @SqlStr +=	' AND CI.Id_Cliente = CL.Id_Cliente'
	SET @SqlStr +=	' AND CB.Id_Lista = PLP.Id_Lista_Precio'
	SET @SqlStr +=	' AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte'
	SET @SqlStr +=	' AND (CT.Compromete_Factura = 1 OR Compromete_Remitos = 1)'
	SET @SqlStr +=	' AND CB.Id_Estado_Cbte NOT IN (0,3,1)'
	
	IF(@pFlag_Interface IN ('', 'E'))
	BEGIN
		SET @SqlStr +=	' AND PLP.Flag_Localidades = 1'
	END

	IF(@pFlag_Interface = 'G')
	BEGIN
		SET @SqlStr +=	' AND PLP.Flag_Localidades IN (1,2)'
	END

	SET @SqlStr +=	' AND PR.Tipo = ''L'''
	SET @SqlStr +=	' AND CI.Flag_QA = ''A'''

	IF(@pId_Cliente <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND (CL.Id_Cliente = ' + CONVERT(VARCHAR(10), @Id_Cliente_Ref) +  ' OR ISNULL(CL.Id_Cliente_Ref, 0) = ' + CONVERT(VARCHAR(10), @Id_Cliente_Ref) + ')'
	END

	--18/02/2022 v2
	IF(@Id_Evento_Grupo <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PLP.Id_Lista_Precio IN (SELECT Id_Lista_Precio FROM Prod_Listas_Precios WHERE Id_Evento_Grupo = ' + CONVERT(VARCHAR(10), @Id_Evento_Grupo) + ')'
	END
	--FIN 18/02/2022 v2
	
	IF(@pId_Sector <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PR.Id_Sector = ' + CONVERT(VARCHAR(20),@pId_Sector) 
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@SqlStr: ' + @SqlStr
	END

	/*====================================================================================================================================================*/

	EXECUTE sp_executesql @SqlStr

	/*====================================================================================================================================================*/

	/*17/02/2022 Protocolos Ubicables*/
	IF(@pFlag_Interface = 'G')
	BEGIN
		SET @SqlStr =	'INSERT INTO #Rta_CPJ_Localidades_Cliente '
		SET @SqlStr +=	' SELECT'
		SET @SqlStr +=	' 0 AS Id_Trans,'
		SET @SqlStr +=	' 0 AS Id_Cliente,'
		SET @SqlStr +=	' 0 AS Id_Lista,'
		SET @SqlStr +=	' '''' AS Razon_Social,'
		SET @SqlStr +=	' '''' AS Fecha_QA,'
		SET @SqlStr +=	' '''' AS Fecha_Venc,'
		SET @SqlStr +=	' '''' AS Fecha_Desde,'
		SET @SqlStr +=	' '''' AS Fecha_Hasta,'
		SET @SqlStr +=	' '''' AS Descripcion,'
		SET @SqlStr +=	' I.Id_Producto AS Id_Producto,'
		SET @SqlStr +=	' '''' AS Descripcion_Resumida,'
		SET @SqlStr +=	' ''C'' AS Estado,'
		SET @SqlStr +=	' '''' AS Serie'
		SET @SqlStr +=	' FROM Tab_Ent_Protocolares_Items I, Tab_Ent_Protocolares E, Productos PR'
		SET @SqlStr +=	' WHERE'
		SET @SqlStr +=	' I.Id_Ent_Protocolo = E.Id_Ent_Protocolo'
		SET @SqlStr +=	' AND I.Id_Producto = PR.Id_Producto'
		SET @SqlStr +=	' AND I.Activo = 1'
		SET @SqlStr +=	' AND E.Activo = 1'

		IF(@pId_Sector <> 0)
		BEGIN
			SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PR.Id_Sector = ' + CONVERT(VARCHAR(20),@pId_Sector) 
		END

		IF(@pModoDebug = 1)
		BEGIN
			PRINT '@SqlStr: ' + @SqlStr
		END

		EXECUTE sp_executesql @SqlStr
	END
	/*FIN 17/02/2022 Protocolos Ubicables*/

	/*====================================================================================================================================================*/


	IF(@pFlag_Interface IN ('', 'E'))
	BEGIN
		SELECT * FROM #Rta_CPJ_Localidades_Cliente
	END

	IF(@pFlag_Interface = 'G')
	BEGIN
		SELECT * FROM #Rta_CPJ_Localidades_Cliente WHERE Estado <> 'V'
	END

	/*====================================================================================================================================================*/

	IF OBJECT_ID('tempdb..#Rta_CPJ_Localidades_Cliente') IS NOT NULL
	BEGIN
		DROP TABLE #Rta_CPJ_Localidades_Cliente
	END

	/*====================================================================================================================================================*/

	IF @pFlagUsarTrans <> 0 COMMIT
	
	/*====================================================================================================================================================*/

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Localidades_Cliente'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  ROLLBACK

	RETURN 9999
END CATCH

RETURN 0 


-- EXEC CPJ_Localidades_Cliente '{"ModoDebug":"1","Id_Cliente":"0","Id_Lista_Precio":"2001","Id_Sector":"6","Flag_Interface":"G"}'
GO


CREATE PROCEDURE [dbo].[CPJ_Localidades_Duplicadas] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON

	DECLARE @pFecha_Desde		DATE
	DECLARE @pFecha_Hasta		DATE
	DECLARE @Id_Evento_Grupo	INT
	DECLARE @sql				VARCHAR(MAX)
	DECLARE @Inc_Abonos_Grup_Eve VARCHAR(1000)

	SET @pFecha_Desde			= ISNULL(CONVERT(DATE, dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde')), CONVERT(DATE,GETDATE()))
	SET @pFecha_Hasta			= ISNULL(CONVERT(DATE, dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta')), CONVERT(DATE,GETDATE()))
	SET @Id_Evento_Grupo		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Evento_Grupo')), 0)

	SET @pFecha_Hasta = DATEADD(DAY,1,@pFecha_Hasta)

BEGIN TRY

	SELECT * INTO #LISTAS FROM Prod_Listas_Precios WHERE Id_Evento_Grupo = @Id_Evento_Grupo
	SELECT @Inc_Abonos_Grup_Eve = Inc_Abonos_Grup_Eve FROM Eventos_Grupos WHERE Id_Evento_Grupo = @Id_Evento_Grupo
	SET @sql = 'INSERT INTO #LISTAS
					SELECT *   
						FROM Prod_Listas_Precios P 
						WHERE Id_Evento_Grupo IN (' + @Inc_Abonos_Grup_Eve +')
						AND NOT EXISTS (SELECT 1 FROM #LISTAS L WHERE L.Id_Lista_Precio = P.Id_Lista_Precio)' 
    EXEC(@sql) 



	SELECT i.id_producto, COUNT(*) AS Cantidad
	INTO #zDuplicados_20220317_3
	FROM cbtes c, cbtes_items i, Clientes T, Productos P, Empresas_Sedes_Sectores Sec
	WHERE 
	c.id_trans=i.id_trans
	AND c.id_lista IN (SELECT Id_Lista_Precio FROM #LISTAS)
	AND c.Id_Estado_Cbte not in (0, 3)
	AND T.Id_Cliente = I.Id_Cliente
	AND T.Activo = 1
	AND CONVERT(DATE, i.fecha_qa) < @pFecha_Hasta
	AND CONVERT(DATE, i.fecha_venc) >= @pFecha_Desde
	AND Flag_QA IN ('A','B')
	AND P.Id_Producto = I.Id_Producto
	AND Sec.Id_Sector = P.Id_Sector
	AND Sec.Flag_Ubic_Fija = 1
	GROUP BY i.id_producto
	HAVING COUNT(*) > 1

	SELECT c.id_trans, dbo.CF_Cbte_Descrip(C.Id_Trans) AS Cbte, C.Lote, CONVERT(DATE, c.fecha) AS Fecha_Cbte, E.Descripcion, c.id_lista, PLP.Descripcion AS Lista,  CONVERT(DATE, i.fecha_qa) AS Fecha_Desde, CONVERT(DATE, i.fecha_venc) AS Fecha_Hasta, i.id_cliente, t.razon_social, i.id_producto, PR.Descripcion_Detallada AS Producto, PR.Calle AS Sector, PR.Fila, PR.Columna AS Asiento, PR.Id_Sector,
		CASE
			WHEN CONVERT(VARCHAR(250),t.Email_Web) IS NOT NULL AND CONVERT(VARCHAR(250),t.Email_Web) <> '' THEN t.Email_Web
			WHEN CONVERT(VARCHAR(250),t.Email) IS NOT NULL AND CONVERT(VARCHAR(250),t.Email) <> '' THEN t.Email
			ELSE 'Sin email'
		END AS Email,
	  CASE
			WHEN CONVERT(VARCHAR(250),t.telefono) IS NOT NULL AND CONVERT(VARCHAR(250),t.telefono) <> '' THEN t.telefono
			WHEN CONVERT(VARCHAR(250),t.Tel_Movil) IS NOT NULL AND CONVERT(VARCHAR(250),t.Tel_Movil) <> '' THEN t.Tel_Movil
			ELSE 'Sin tel├Üfono'
	  END AS Telefono
	INTO #zDupl_20220317_3
	FROM cbtes c, cbtes_items i, clientes t, Prod_Listas_Precios PLP, Productos PR, Cbtes_Estados E
	WHERE 
	c.id_trans=i.id_trans
	AND i.id_cliente=t.id_cliente
	AND C.Id_Estado_Cbte = E.Id_Estado_Cbte
	AND PR.Id_Producto = I.Id_Producto
	AND C.Id_Lista = PLP.Id_Lista_Precio
	AND Flag_QA = 'A'
	AND I.Id_Producto <> ''
	and i.Id_Producto in (SELECT id_producto FROM #zDuplicados_20220317_3)
	AND c.Id_Estado_Cbte not in (0, 3)
	AND c.id_lista IN (SELECT Id_Lista_Precio FROM Prod_Listas_Precios WHERE Id_Lista_Precio in (SELECT Id_Lista_Precio FROM #LISTAS))
	AND CONVERT(DATE, i.fecha_qa) < @pFecha_Hasta
	AND CONVERT(DATE, i.fecha_venc) >= @pFecha_Desde
	ORDER BY I.Id_Producto

	SELECT DISTINCT Id_Cliente, A.Cbte, A.Descripcion AS Estado_Cbte, Razon_Social, Id_Producto, Fecha_Cbte, Id_Lista, Lote, t.Id_Trans, a.Id_Sector, CONVERT(VARCHAR(250),a.Email) AS Email, CONVERT(VARCHAR(250),a.Telefono) as Telefono
	FROM #zDupl_20220317_3 a, transacciones t,Cbtes_Aplica ca
	where a.Id_Trans = t.Id_Trans
	and ca.Id_Trans=t.Id_Trans
	and a.Id_Trans=ca.Id_Trans
	ORDER BY Id_Producto, t.Id_Trans

	IF OBJECT_ID('tempdb..#Listas') IS NOT NULL
		DROP TABLE #Listas


END TRY  
BEGIN CATCH  

    EXECUTE usp_GetErrorInfo

	IF OBJECT_ID('tempdb..#Listas') IS NOT NULL
		DROP TABLE #Listas


	RETURN 9999

END CATCH

RETURN 0

/*
exec [CPJ_Localidades_Duplicadas] '{"Id_Evento_Grupo":14,"Fecha_Desde":"20260201","Fecha_Hasta":"20260201"}'
*/
GO


CREATE PROCEDURE [dbo].[CPJ_Localidades_Ocupadas]		@pJson VARCHAR(8000)
AS 
SET NOCOUNT ON

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
		,@pModoDebug			TINYINT
		,@pId_Lista_Precio		INT
		,@pId_Cliente			INT
		,@pId_Sector			INT
		,@pId_Producto			VARCHAR(14)
		,@pId_Trans				INT
		,@pInc_Abonos			TINYINT
		,@pInc_AbonosReserAnt	TINYINT
		,@pInc_AbonosReser		TINYINT
		,@pInc_Abonos_Grup_Eve	VARCHAR(500)
		,@pInc_TicketVend		TINYINT
		,@pInc_TicketCanj		TINYINT
		,@pInc_TicketImp		TINYINT
		,@pInc_ProtoFijos		TINYINT
		,@pInc_ProtoImp			TINYINT
		,@pInc_ProcesoVta		TINYINT
		,@pInc_Todos			TINYINT
		,@pInc_Libres			TINYINT
		,@pFormato				VARCHAR(10)



SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Lista_Precio		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Lista_Precio')), 0)
SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Sector				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Sector')), 0)
SET @pId_Producto			= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), '')
SET @pId_Trans				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pInc_Abonos			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Inc_Abonos')), 0)
SET @pInc_AbonosReserAnt	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Inc_AbonosReserAnt')), 0)
SET @pInc_AbonosReser		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Inc_AbonosReser')), 0)
SET @pInc_Abonos_Grup_Eve	= ISNULL(CONVERT(VARCHAR(500), dbo.CF_JSON_VALUE(@pJson,'Inc_Abonos_Grup_Eve')), '')
SET @pInc_TicketVend		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Inc_TicketVend')), 0)
SET @pInc_TicketCanj		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Inc_TicketCanj')), 0)
SET @pInc_TicketImp			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Inc_TicketImp')), 0)
SET @pInc_ProtoFijos		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Inc_ProtoFijos')), 0)
SET @pInc_ProtoImp			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Inc_ProtoImp')), 0)
SET @pInc_ProcesoVta		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Inc_ProcesoVta')), 0)
SET @pInc_Todos				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Inc_Todos')), 0)
SET @pInc_Libres			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Inc_Libres')), 0)
SET @pFormato				= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Formato')), '')


IF 	(@pInc_Abonos + @pInc_AbonosReserAnt + @pInc_AbonosReser	+ @pInc_TicketVend + @pInc_TicketCanj + @pInc_TicketImp	+ @pInc_ProtoFijos + @pInc_ProtoImp + @pInc_ProcesoVta = 0)
	AND @pInc_Todos = 0
BEGIN
	SET @pInc_Todos = 1
END
	

IF UPPER(@pFormato) IN ('TS','TT')        --TS Total x Sector     TT  Total por Tipo
BEGIN
	SET @pInc_Todos = 1
END

IF  (@pInc_Libres IN (1,2)) 
BEGIN
	SET @pInc_Todos = 1
	SET @pId_Producto = ''
	SET @pId_Cliente = 0
	SET @pId_Trans = 0
	IF @pId_Lista_Precio = 0
		RAISERROR ('Id_Lista_Precio can not be zero.', 16,  1 ) 
END



IF @pInc_Todos = 1
BEGIN
	SET @pInc_Abonos		    = 1
	SET @pInc_AbonosReserAnt    = 1
	SET @pInc_AbonosReser	    = 1
	SET @pInc_TicketVend	    = 1
	SET @pInc_TicketCanj	    = 1
	SET @pInc_TicketImp		    = 1
	SET @pInc_ProtoFijos	    = 1
	SET @pInc_ProtoImp		    = 1
	SET @pInc_ProcesoVta		= 1
END 


/*FIN Variables recibidas por parametro a traves del JSON*/

/*====================================================================================================================================================*/

--IF(@pId_Lista_Precio = 0)  RAISERROR ('Id_Lista_Precio can not be zero.', 16,  1 ) 

/*====================================================================================================================================================*/

/*Variables Locales*/
DECLARE @SqlStr						NVARCHAR(MAX)
DECLARE @Id_Cliente_Ref				INT
DECLARE @Id_Evento_Grupo			INT
DECLARE @Evento_Desde				DATE
DECLARE @Evento_Hasta				DATE
DECLARE @Flag_Localidades			TINYINT
DECLARE @Fecha_Evento				DATETIME
DECLARE @Id_Evento_Grupo_Reservas	INT
DECLARE @Evento_Fecha_Reserva_Limite DATETIME
DECLARE @cant_min_reserva			INT
DECLARE @version_SQL				VARCHAR(50)
DECLARE @Id_lista_Origen			INT
DECLARE @Id_Cbte_Ent_Prot           CHAR(4)
DECLARE @Loca_Cbte_Loca_Ent         CHAR(4)

SET @Id_Cbte_Ent_Prot = dbo.CF_xParam('Id_Cbte_Ent_Prot')
SET @Loca_Cbte_Loca_Ent = dbo.CF_xParam('Loca_Cbte_Loca_Ent')

 
/*FIN Variables Locales*/

BEGIN TRY
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Localidades_Ocupadas'
		PRINT 'Parametros: '+ @pJson  
	END

	/*====================================================================================================================================================*/

	SET @version_SQL = dbo.CF_DB_Version()

	/*====================================================================================================================================================*/

	IF(@pId_Cliente > 0)
	BEGIN
		SELECT 		
		@Id_Cliente_Ref = ISNULL(Id_Cliente_Ref, 0)
		FROM Clientes 
		WHERE
		Id_Cliente = @pId_Cliente

		IF(@Id_Cliente_Ref = 0)
		BEGIN
			SET @Id_Cliente_Ref = @pId_Cliente
		END
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@pId_Cliente: ' + CONVERT(VARCHAR(10), @pId_Cliente) + '. @Id_Cliente_Ref: '+ CONVERT(VARCHAR(10), @Id_Cliente_Ref)  
	END

	

----------------------------------------


	IF OBJECT_ID('tempdb..#Rta_CPJ_Localidades_Ocupadas') IS NOT NULL
	BEGIN
		DROP TABLE #Rta_CPJ_Localidades_Ocupadas
	END

	CREATE TABLE #Rta_CPJ_Localidades_Ocupadas	(Id_Trans					INT
												, Id_Cliente				INT
												, Id_Lista					INT
												, Razon_Social				VARCHAR(100)
												, Fecha_QA					DATETIME
												, Fecha_Venc				DATETIME
												, Fecha_Desde				DATETIME
												, Fecha_Hasta				DATETIME
												, Descripcion				VARCHAR(100)
												, Id_Producto				VARCHAR(14)
												, Descripcion_Resumida		VARCHAR(100)
												, Estado					VARCHAR(10)
												, Serie						VARCHAR(100)
												, Item						INT
												, Flag_QA					CHAR(1)
												, Fecha_Cbte				DATETIME
												, Cbte_Descrip				VARCHAR(50)
												, Id_Estado_Cbte			SMALLINT
												, Cantidad					INT
												, Lote						VARCHAR(100)
												, Id_Sector					SMALLINT
												, Sector_Codigo				VARCHAR(10)
												, Sector_Nombre				VARCHAR(50)
												, Columna					VARCHAR(5)
												, Fila						VARCHAR(5)
												, Fecha_Evento				DATETIME
												, Id_Lista_Renov			INT
												, Id_Evento_Grupo			INT
												, Id_Evento_Grupo_Reservas	INT
												)

	CREATE TABLE #ARA							(Id_Trans					INT
												, Id_Cliente				INT
												, Id_Lista					INT
												, Razon_Social				VARCHAR(100)
												, Fecha_QA					DATETIME
												, Fecha_Venc				DATETIME
												, Fecha_Desde				DATETIME
												, Fecha_Hasta				DATETIME
												, Descripcion				VARCHAR(100)
												, Id_Producto				VARCHAR(14)
												, Descripcion_Resumida		VARCHAR(100)
												, Estado					VARCHAR(10)
												, Serie						VARCHAR(100)
												, Item						INT
												, Flag_QA					CHAR(1)
												, Fecha_Cbte				DATETIME
												, Cbte_Descrip				VARCHAR(50)
												, Id_Estado_Cbte			SMALLINT
												, Cantidad					INT
												, Lote						VARCHAR(100)
												, Id_Sector					SMALLINT
												, Sector_Codigo				VARCHAR(10)
												, Sector_Nombre				VARCHAR(50)
												, Columna					VARCHAR(5)
												, Fila						VARCHAR(5)
												, Fecha_Evento				DATETIME
												, Id_Lista_Renov			INT
												, Id_Evento_Grupo			INT
												, Id_Evento_Grupo_Reservas	INT
												)

	CREATE TABLE #AR							(Id_Trans					INT
												, Id_Cliente				INT
												, Id_Lista					INT
												, Razon_Social				VARCHAR(100)
												, Fecha_QA					DATETIME
												, Fecha_Venc				DATETIME
												, Fecha_Desde				DATETIME
												, Fecha_Hasta				DATETIME
												, Descripcion				VARCHAR(100)
												, Id_Producto				VARCHAR(14)
												, Descripcion_Resumida		VARCHAR(100)
												, Estado					VARCHAR(10)
												, Serie						VARCHAR(100)
												, Item						INT
												, Flag_QA					CHAR(1)
												, Fecha_Cbte				DATETIME
												, Cbte_Descrip				VARCHAR(50)
												, Id_Estado_Cbte			SMALLINT
												, Cantidad					INT
												, Lote						VARCHAR(100)
												, Id_Sector					SMALLINT
												, Sector_Codigo				VARCHAR(10)
												, Sector_Nombre				VARCHAR(50)
												, Columna					VARCHAR(5)
												, Fila						VARCHAR(5)
												, Fecha_Evento				DATETIME
												, Id_Lista_Renov			INT
												, Id_Evento_Grupo			INT
												, Id_Evento_Grupo_Reservas	INT
												)							  

	CREATE INDEX #IX_Rta_CPJ_Loc_Ocup_Prod ON #Rta_CPJ_Localidades_Ocupadas (Id_Producto)

	CREATE INDEX #IX_Rta_CPJ_Loc_Ocup_ColFil ON #Rta_CPJ_Localidades_Ocupadas (Sector_Codigo,Id_Sector,Columna,Fila)

	
	CREATE INDEX #IX_ARA_Prod ON #ARA (Id_Producto)
	
	CREATE INDEX #IX_AR_Prod ON #AR (Id_Producto)
	CREATE INDEX #IX_AR_Trans ON #AR (Id_Trans)

	
------------------------------------------------------------------------

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@pId_Lista_Precio: '+ CONVERT(VARCHAR(10), @pId_Lista_Precio)  
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Actualiza Evento_Cant_Dias_Limite y Evento_Fecha_Reserva_Limite en caso de ser Abonos y no tenerlo configurado.'
	END

	IF(@pId_Lista_Precio > 0)
	BEGIN
		UPDATE Prod_Listas_Precios 
		SET 
		Evento_Cant_Dias_Limite = CONVERT(INT, dbo.CF_xParam('Loca_Fecha_Lim_Dias'))
		WHERE 
		Id_Lista_Precio = @pId_Lista_Precio  
		AND Evento_Cant_Dias_Limite = 0
		AND Flag_Localidades = 1

		UPDATE Prod_Listas_Precios 
				SET 
				Evento_Fecha_Reserva_Limite = CONVERT(DATE,dbo.CF_xParam('Loca_Fecha_Lim'))
				WHERE 
				Id_Lista_Precio = @pId_Lista_Precio 
				AND Evento_Fecha_Reserva_Limite IS NULL
				AND Flag_Localidades = 1

		SELECT	
				@Id_Evento_Grupo = ISNULL(Id_Evento_Grupo, 0), 
				@Evento_Desde = Fecha_Desde , 
				@Evento_Hasta = Fecha_Hasta , 
				@Flag_Localidades = Flag_Localidades,
				@Fecha_Evento = Fecha_Evento,
				@Evento_Fecha_Reserva_Limite = Evento_Fecha_Reserva_Limite		
				FROM Prod_Listas_Precios 
				WHERE 
				Id_Lista_Precio = @pId_Lista_Precio	

	   SELECT  TOP 1
			   @Id_Evento_Grupo_Reservas = ISNULL(Id_Evento_Grupo_Reservas,0)
			   FROM Eventos_Grupos 
			   WHERE Id_Evento_Grupo = @Id_Evento_Grupo 
			   

/* Si es partido, tomo la fecha del partido */


		IF @Flag_Localidades = 2
		BEGIN
			  SET @Evento_Desde = @Fecha_Evento 
			  SET @Evento_Hasta = @Fecha_Evento  
		END

		IF  @pInc_Abonos_Grup_Eve = ''
		BEGIN
			SELECT @pInc_Abonos_Grup_Eve = ISNULL(Inc_Abonos_Grup_Eve,'')  FROM Eventos_Grupos WHERE Id_Evento_Grupo = @Id_Evento_Grupo
		END



		IF(@pModoDebug = 1)
		BEGIN
			PRINT '@Id_Evento_Grupo: '+ CONVERT(VARCHAR(10), @Id_Evento_Grupo)  
			PRINT '@Evento_Desde: '+ CONVERT(VARCHAR(10), @Evento_Desde, 112)  
			PRINT '@Evento_Hasta: '+ CONVERT(VARCHAR(10), @Evento_Hasta, 112)  
			PRINT '@Flag_Localidades: '+ CONVERT(VARCHAR(10), @Flag_Localidades)  
			PRINT '@Fecha_Evento: '+ CONVERT(VARCHAR(20), @Fecha_Evento, 112)  
			PRINT '@Evento_Fecha_Reserva_Limite: '+ CONVERT(VARCHAR(10), @Evento_Fecha_Reserva_Limite, 112)  
			PRINT '@Id_Evento_Grupo_Reservas: '+ CONVERT(VARCHAR(10), ISNULL(@Id_Evento_Grupo_Reservas,0))  
			PRINT '@pInc_Abonos_Grup_Eve: '+ CONVERT(VARCHAR, ISNULL(@pInc_Abonos_Grup_Eve,''))  
		END
	END
	ELSE
	BEGIN
		SET @Evento_Desde = GETDATE() 
		SET @Evento_Hasta = GETDATE()
		
		SET @Evento_Fecha_Reserva_Limite = CONVERT(DATE, dbo.CF_xParam('Loca_Fecha_Lim'))		
	END

-------------------------------------------------------------------------------------------------------
	
SELECT PLG.Id_Lista_Precio,PLG.Id_Evento_Grupo INTO #Evento_Grupo_Abono
				FROM Prod_Listas_Precios PLG WHERE 1=0

SET @SqlStr = 'INSERT INTO #Evento_Grupo_Abono '
SET @SqlStr += CHAR(13) + ' SELECT PLG.Id_Lista_Precio,PLG.Id_Evento_Grupo '
SET @SqlStr += CHAR(13) + ' FROM Prod_Listas_Precios PLG'
SET @SqlStr += CHAR(13) + ' WHERE PLG.Id_Evento_Grupo IN ( '+ CONVERT(VARCHAR,@Id_Evento_Grupo)
IF @Id_Evento_Grupo_Reservas <> 0 
	SET @SqlStr += CHAR(13) + ',' + CONVERT(VARCHAR,@Id_Evento_Grupo_Reservas)
IF LTRIM(RTRIM(@pInc_Abonos_Grup_Eve)) <> ''	
	SET @SqlStr += CHAR(13) + ',' + LTRIM(RTRIM(@pInc_Abonos_Grup_Eve))
	
SET @SqlStr += CHAR(13) + ')'
SET @SqlStr += CHAR(13) + ' AND PLG.Id_Evento_Grupo <> 0 AND PLG.Flag_Localidades = 1'
SET @SqlStr += CHAR(13) + ' GROUP BY PLG.Id_Lista_Precio,PLG.Id_Evento_Grupo'

EXECUTE sp_executesql @SqlStr

IF(@pModoDebug = 1)
BEGIN
	PRINT CHAR(13) + '#Evento_Grupo_Abono: ' + @SqlStr 
END

-------------------------------------------------------------------------------------------------------
SELECT PLG.Id_Lista_Precio,PLG.Id_Evento_Grupo INTO #Evento_Grupo_Ticket
				FROM Prod_Listas_Precios PLG WHERE 1=0
				
SET @SqlStr = 'INSERT INTO #Evento_Grupo_Ticket '
SET @SqlStr += CHAR(13) + ' SELECT PLG.Id_Lista_Precio,PLG.Id_Evento_Grupo '
SET @SqlStr += CHAR(13) + ' FROM Prod_Listas_Precios PLG'
SET @SqlStr += CHAR(13) + ' WHERE PLG.Id_Evento_Grupo IN ( '+ CONVERT(VARCHAR,@Id_Evento_Grupo)
IF @Id_Evento_Grupo_Reservas <> 0 
	SET @SqlStr += CHAR(13) + ',' + CONVERT(VARCHAR,@Id_Evento_Grupo_Reservas)
IF LTRIM(RTRIM(@pInc_Abonos_Grup_Eve)) <> ''	
	SET @SqlStr += CHAR(13) + ',' + LTRIM(RTRIM(@pInc_Abonos_Grup_Eve))
	
SET @SqlStr += CHAR(13) + ')'
SET @SqlStr += CHAR(13) + ' AND PLG.Id_Evento_Grupo <> 0 AND PLG.Flag_Localidades = 2'
SET @SqlStr += CHAR(13) + ' GROUP BY PLG.Id_Lista_Precio,PLG.Id_Evento_Grupo'

EXECUTE sp_executesql @SqlStr

IF(@pModoDebug = 1)
BEGIN
	PRINT CHAR(13) + '#Evento_Grupo_Ticket: ' + @SqlStr 
END

/*======================================================================= VENTAS y REMITOS de ABONOS =============================================================================*/

IF  @pInc_Abonos = 1
BEGIN
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'VENTAS y REMITOS de ABONOS'
	END

	SET @SqlStr =	''

	SET @SqlStr +=	'INSERT INTO #Rta_CPJ_Localidades_Ocupadas '
	SET @SqlStr +=	' SELECT'
	SET @SqlStr +=	' DISTINCT'
	SET @SqlStr +=	' CB.Id_Trans,'
	SET @SqlStr +=	' ISNULL(CI.Id_Cliente, 0) AS Id_Cliente,'
	SET @SqlStr +=	' ISNULL(CB.Id_Lista, 0) AS Id_Lista,'
	SET @SqlStr +=	' UPPER(LTRIM(RTRIM(ISNULL(CL.Razon_Social, '''')))) AS Razon_Social,'
	SET @SqlStr +=	' CI.Fecha_QA,'
	SET @SqlStr +=	' CI.Fecha_Venc,'
	SET @SqlStr +=	' PLP.Fecha_Desde,'
	SET @SqlStr +=	' PLP.Fecha_Hasta,'
	SET @SqlStr +=	' UPPER(LTRIM(RTRIM(ISNULL(PLP.Descripcion, '''')))) AS Descripcion,'
	SET @SqlStr +=	' UPPER(LTRIM(RTRIM(ISNULL(CI.Id_Producto, '''')))) AS Id_Producto,'
	SET @SqlStr +=	' UPPER(RTRIM(LTRIM(ISNULL(PR.Descripcion_Resumida, '''')))) AS Descripcion_Resumida,'
	SET @SqlStr +=	'''A'' AS Estado,'
					/*
						A	-> Abono Comprado      
						ARA -> Abono Reserva Anticipada    
						AR	-> Abono Reservado     
						TV	-> Ticket Vendido
						TC	-> Ticket Canjeado
						TI	-> Ticket Impreso
						PI	-> Protocolos Impresos
						PU	-> Protocolo Fijo
						PV	-> En Proceso de Venta
					*/
	SET @SqlStr +=	' CI.Serie,'
	SET @SqlStr +=	' CI.Item,'
	SET @SqlStr +=	' CI.Flag_QA,'
	SET @SqlStr +=	' CB.Fecha,'
	SET @SqlStr +=	' dbo.CF_Cbte_Descrip(CB.Id_Trans) AS Cbte_Descrip,'
	SET @SqlStr +=	' CB.Id_Estado_Cbte,'
	SET @SqlStr +=	' CONVERT(INT, CI.Cantidad) AS Cantidad,'
	SET @SqlStr +=	' CB.Lote,'
	SET @SqlStr +=	' PR.Id_Sector,'
	SET @SqlStr +=	' S.Codigo AS Sector_Codigo,'
	SET @SqlStr +=	' S.Descripcion AS Sector_Nombre,'
	SET @SqlStr +=	' PR.Columna,'
	SET @SqlStr +=	' PR.Fila,'
	SET @SqlStr +=	' PLP.Fecha_Evento,'
	SET @SqlStr +=	' ISNULL(CB.Id_Lista, 0),'
	SET @SqlStr +=	' ISNULL(PLP.Id_Evento_Grupo, 0),'
	SET @SqlStr +=	' ISNULL(E.Id_Evento_Grupo_Reservas, 0)'
	SET @SqlStr +=	' FROM Cbtes CB, Cbtes_Items CI, Productos PR, Clientes CL, Prod_Listas_Precios PLP, Cbtes_Tipos CT, Empresas_Sedes_Sectores S, Eventos_Grupos E'
	SET @SqlStr +=	' WHERE'
	SET @SqlStr +=	' CB.Id_Trans = CI.Id_Trans'
	SET @SqlStr +=	' AND CI.Id_Producto = PR.Id_Producto'
	SET @SqlStr +=	' AND PR.Id_Sector = S.Id_Sector'
	SET @SqlStr +=	' AND CI.Id_Cliente = CL.Id_Cliente'
	SET @SqlStr +=	' AND CB.Id_Lista = PLP.Id_Lista_Precio'
	SET @SqlStr +=	' AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte'
	SET @SqlStr +=	' AND PLP.Id_Evento_Grupo = E.Id_Evento_Grupo'
	SET @SqlStr +=	' AND CL.Activo = 1 '
	SET @SqlStr +=	' AND (CT.Compromete_Factura = 1 OR Compromete_Remitos = 1) ' 
	SET @SqlStr +=	' AND CB.Id_Estado_Cbte IN (2,4,1) ' --25/04/2022 Se agrega estado 1
	SET @SqlStr +=	' AND PLP.Flag_Localidades = 1'
	SET @SqlStr +=	' AND PR.Tipo = ''L'''
	SET @SqlStr +=	' AND CI.Flag_QA IN (''A'',''B'')'
	SET @SqlStr +=  ' AND CI.Fecha_QA < ''' + CONVERT(VARCHAR(10), DATEADD(DAY, 1, @Evento_Hasta), 112) +'''
					  AND CI.Fecha_Venc >=  ''' + CONVERT(VARCHAR(10), @Evento_Desde, 112) +''''

	IF(@pId_Cliente <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND (CL.Id_Cliente = ' + CONVERT(VARCHAR(10), @Id_Cliente_Ref) +  ' OR CL.Id_Cliente_Ref = ' + CONVERT(VARCHAR(10), @Id_Cliente_Ref) + ')'
	END

	IF(@pId_Lista_Precio > 0)
	BEGIN
		IF(@Id_Evento_Grupo <> 0)
		BEGIN
				/*REVISAR: Porque filtramos por fecha hasta del evento? 
				no deberia ser suficiente por fecha_venc del item ?*/
			SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PLP.Id_Lista_Precio 
				IN (	SELECT PLG.Id_Lista_Precio 
						FROM Prod_Listas_Precios PLG, #Evento_Grupo_Abono EG
						WHERE PLG.Id_Lista_Precio = EG.Id_Lista_Precio
						AND PLG.Fecha_Hasta >= CONVERT(DATE,GETDATE()) )'
																						
		END
		ELSE
		BEGIN
			SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PLP.Id_Lista_Precio = '+ CONVERT(VARCHAR(10),@pId_Lista_Precio)
		END
	END

	
	IF(@pId_Sector <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PR.Id_Sector = ' + CONVERT(VARCHAR(20),@pId_Sector) 
	END

	IF(@pId_Producto <> '')
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PR.Id_Producto = ''' + @pId_Producto +''''
	END

	IF(@pId_Trans <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND CB.Id_Trans = ' + @pId_Trans 
	END


	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@SqlStr: ' + @SqlStr
	END

	EXECUTE sp_executesql @SqlStr

	IF(@pModoDebug = 1)
	BEGIN
		PRINT ''
	END
END

