	END 

	IF(@pModoDebug = 1)
	BEGIN
		PRINT ''
	END

	IF(@pId_Cliente = 0)
	BEGIN
		SELECT * INTO #rta FROM #Rta_CPJ_Localidades_Ocupadas WHERE ESTADO = 'A'
		DELETE FROM #Rta_CPJ_Localidades_Ocupadas WHERE ESTADO = 'A'

		DELETE FROM #rta WHERE Id_Trans IN (SELECT A.Id_Trans FROM #rta R, #ARA A 
					WHERE R.Id_Trans <> A.Id_Trans --diferennte trans ya renov
					AND R.Id_Producto = A.Id_Producto 
					AND R.Id_Cliente = A.Id_Cliente   --validamos mismo cliente
					AND R.Id_Evento_Grupo_Reservas = A.Id_Evento_Grupo)

		UPDATE #rta SET Estado = 'ARA' WHERE Id_Trans IN (SELECT Id_Trans FROM #ARA)

	    -- es lo mismo que abajo
		INSERT INTO #rta SELECT * FROM #ARA WHERE Id_Trans NOT IN (SELECT Id_Trans FROM #rta)
		INSERT INTO #Rta_CPJ_Localidades_Ocupadas SELECT * FROM #rta	
		/*
		IF ((SELECT COUNT(*) FROM #rta WHERE Estado = 'ARA') < (SELECT COUNT(*) FROM #ARA))
		BEGIN
			INSERT INTO #rta SELECT * FROM #ARA WHERE Id_Trans NOT IN (SELECT Id_Trans FROM #rta)
			INSERT INTO #Rta_CPJ_Localidades_Ocupadas SELECT * FROM #rta
		END
		ELSE
		BEGIN
			INSERT INTO #Rta_CPJ_Localidades_Ocupadas SELECT * FROM #rta
		END
		*/
	END
	ELSE
	BEGIN

		UPDATE #Rta_CPJ_Localidades_Ocupadas SET Estado = 'ARA' 
			WHERE Id_Trans IN  (SELECT Id_Trans FROM #ARA)
		
		DELETE FROM #Rta_CPJ_Localidades_Ocupadas
		WHERE Estado = 'ARA'
		AND EXISTS (
			SELECT 1
			FROM #Rta_CPJ_Localidades_Ocupadas AS sub
			WHERE sub.Id_Cliente = #Rta_CPJ_Localidades_Ocupadas.Id_Cliente
			AND sub.Id_Producto = #Rta_CPJ_Localidades_Ocupadas.Id_Producto
			AND sub.Estado = 'A'
		)

	END

		
END


