		SET @SqlStr +=	CHAR(13) + ' UPPER(LTRIM(RTRIM(ISNULL(CL.Razon_Social, '''')))) AS Razon_Social,'
		SET @SqlStr +=	CHAR(13) + ' CI.Fecha_QA,'
		SET @SqlStr +=	CHAR(13) + ' CI.Fecha_Venc,'
		SET @SqlStr +=	CHAR(13) + ' PLP.Fecha_Desde,'
		SET @SqlStr +=	CHAR(13) + ' PLP.Fecha_Hasta,'
		SET @SqlStr +=	CHAR(13) + ' UPPER(LTRIM(RTRIM(ISNULL(PLP.Descripcion, '''')))) AS Descripcion,'
		SET @SqlStr +=	CHAR(13) + ' UPPER(LTRIM(RTRIM(ISNULL(CI.Id_Producto, '''')))) AS Id_Producto,'
		SET @SqlStr +=	CHAR(13) + ' UPPER(RTRIM(LTRIM(ISNULL(PR.Descripcion_Resumida, '''')))) AS Descripcion_Resumida,'
		SET @SqlStr +=	CHAR(13) + ' ''AR'' AS Estado,'
					/*
						A	-> Abono Comprado       
						ARA -> Abono Reserva Anticipada    
						AR	-> Abono Resevado     
						TV	-> Ticket Vendido
						TC	-> Ticket Canjeado
						TI	-> Ticket Impreso
						PI	-> Protocolos Impresos
						PU	-> Protocolo Fijo
						PV	-> En Proceso de Venta
					*/
		SET @SqlStr +=	CHAR(13) + ' CI.Serie,'
		SET @SqlStr +=	CHAR(13) + ' CI.Item,'
		SET @SqlStr +=	CHAR(13) + ' CI.Flag_QA,'
		SET @SqlStr +=	CHAR(13) + ' CB.Fecha,'
		SET @SqlStr +=	CHAR(13) + ' dbo.CF_Cbte_Descrip(CB.Id_Trans) AS Cbte_Descrip,'
		SET @SqlStr +=	CHAR(13) + ' CB.Id_Estado_Cbte,'
		SET @SqlStr +=	CHAR(13) + ' CONVERT(INT, CI.Cantidad) AS Cantidad,'
		SET @SqlStr +=	CHAR(13) + ' CB.Lote,'
		SET @SqlStr +=	CHAR(13) + ' PR.Id_Sector,'
		SET @SqlStr +=	CHAR(13) + ' S.Codigo AS Sector_Codigo,'
		SET @SqlStr +=	CHAR(13) + ' S.Descripcion AS Sector_Nombre,'
		SET @SqlStr +=	CHAR(13) + ' PR.Columna,'
		SET @SqlStr +=	CHAR(13) + ' PR.Fila,'
		SET @SqlStr +=	CHAR(13) + ' PLP.Fecha_Evento,'
		SET @SqlStr +=	CHAR(13) + ' ISNULL(CB.Id_Lista, 0),'
		SET @SqlStr +=	CHAR(13) + ' ISNULL(PLP.Id_Evento_Grupo, 0),' /*Modificado 2024/07/01*/
		SET @SqlStr +=	CHAR(13) +' 0'

		IF CONVERT(DATE,@Evento_Fecha_Reserva_Limite) >= CONVERT(DATE,GETDATE()) 
		BEGIN
			IF(@pId_Lista_Precio > 0)
			BEGIN
				IF(@Id_Evento_Grupo <> 0)
				BEGIN
					SET @SqlStr +=	CHAR(13) +' FROM Cbtes CB, Cbtes_Items CI, Productos PR, Clientes CL, Prod_Listas_Precios PLP, Cbtes_Tipos CT, Empresas_Sedes_Sectores S, #Temp_Prod_Listas_Precios Z'
				END
				ELSE
				BEGIN
					SET @SqlStr +=	CHAR(13) +' FROM Cbtes CB, Cbtes_Items CI, Productos PR, Clientes CL, Prod_Listas_Precios PLP, Cbtes_Tipos CT, Empresas_Sedes_Sectores S'
				END
			END
			ELSE
			BEGIN
				SET @SqlStr +=	CHAR(13) +' FROM Cbtes CB, Cbtes_Items CI, Productos PR, Clientes CL, Prod_Listas_Precios PLP, Cbtes_Tipos CT, Empresas_Sedes_Sectores S'
			END
		END


		SET @SqlStr +=	CHAR(13) + ' WHERE'
		SET @SqlStr +=	CHAR(13) + ' CB.Id_Trans = CI.Id_Trans'
		SET @SqlStr +=	CHAR(13) + ' AND CI.Id_Producto = PR.Id_Producto'
		SET @SqlStr +=	CHAR(13) + ' AND PR.Id_Sector = S.Id_Sector'
		SET @SqlStr +=	CHAR(13) + ' AND CI.Id_Cliente = CL.Id_Cliente'
		SET @SqlStr +=	CHAR(13) + ' AND CB.Id_Lista = PLP.Id_Lista_Precio'
		SET @SqlStr +=	CHAR(13) + ' AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte'
		SET @SqlStr +=	CHAR(13) + ' AND CL.Activo = 1 '
		SET @SqlStr +=	CHAR(13) + ' AND (CT.Compromete_Factura = 1 OR Compromete_Remitos = 1) ' 
		SET @SqlStr +=	CHAR(13) + ' AND CB.Id_Estado_Cbte IN (2,4) '
		SET @SqlStr +=	CHAR(13) + ' AND PLP.Flag_Localidades = 1'
		SET @SqlStr +=	CHAR(13) + ' AND PR.Tipo = ''L'''
		SET @SqlStr +=	CHAR(13) + ' AND CI.Flag_QA IN (''A'',''B'')'
		SET @SqlStr +=	CHAR(13) + ' AND DATEADD(DAY, PLP.Evento_Cant_Dias_Limite, CONVERT(DATE, CI.Fecha_Venc)) >= CONVERT(DATE, GETDATE())
										AND CONVERT(DATE, CI.Fecha_Venc) <= CONVERT(DATE, GETDATE()) '
						  
		IF(@pId_Cliente <> 0)
