		BEGIN
			SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PR.Id_Producto = ''' + @pId_Producto +''''
		END

		IF(@pId_Trans <> 0)
		BEGIN
			SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND CB.Id_Trans = ' + @pId_Trans 
		END

		EXECUTE sp_executesql @SqlStr

		IF(@pModoDebug = 1)
		BEGIN
			PRINT '@SqlStr #AR: ' + @SqlStr
		END
		

		
		
		
		IF(@pId_Cliente = 0)
		BEGIN
			SELECT A.Id_Trans, A.Id_Cliente , A.Id_Producto
			INTO #ya_renovadas
			FROM #AR A
				JOIN #Rta_CPJ_Localidades_Ocupadas R ON A.Id_Cliente = R.Id_Cliente AND A.Id_Producto = R.Id_Producto AND A.Id_Lista <> R.Id_Lista
			WHERE R.Estado = 'A'

			CREATE INDEX #IX_renovadas_Trans ON #ya_renovadas (Id_Cliente,Id_Producto)

			INSERT INTO #Rta_CPJ_Localidades_Ocupadas 
				SELECT * FROM #AR AR
				WHERE NOT EXISTS  (SELECT Id_Trans FROM #ya_renovadas YR WHERE AR.Id_Cliente = YR.Id_Cliente AND AR.Id_Producto = YR.Id_Producto) 
		END
		ELSE
		BEGIN
			INSERT INTO #Rta_CPJ_Localidades_Ocupadas SELECT R.* FROM #AR R WHERE ID_PRODUCTO NOT IN (SELECT ID_PRODUCTO FROM #Rta_CPJ_Localidades_Ocupadas
																												WHERE Id_Producto = R.Id_Producto
																													  AND R.Id_Cliente = Id_Cliente)
		END
	END 

	IF(@pModoDebug = 1)
	BEGIN
		PRINT ''
	END
END
