	SET @SqlStr +=	' FROM Cbtes CB, Cbtes_Items CI 
							LEFT JOIN #Rta_CPJ_Localidades_Ocupadas LOT 
								ON LOT.ID_TRANS = CI.ID_TRANS 
								AND LOT.ITEM = CI.ITEM 
							LEFT JOIN #Rta_CPJ_Localidades_Ocupadas LOP 
								ON LOP.Id_Producto COLLATE SQL_Latin1_General_CP1_CI_AS = CI.Id_Producto COLLATE SQL_Latin1_General_CP1_CI_AS
						, Productos PR, Clientes CL, Prod_Listas_Precios PLP
						, Cbtes_Tipos CT, Empresas_Sedes_Sectores S '
	SET @SqlStr +=	' WHERE'
	SET @SqlStr +=	' CB.Id_Trans = CI.Id_Trans'
	SET @SqlStr +=	' AND CI.Id_Producto = PR.Id_Producto'
	SET @SqlStr +=	' AND PR.Id_Sector = S.Id_Sector'
	SET @SqlStr +=	' AND CI.Id_Cliente = CL.Id_Cliente'
	SET @SqlStr +=	' AND CB.Id_Lista = PLP.Id_Lista_Precio'
	SET @SqlStr +=	' AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte'
	SET @SqlStr +=	' AND CT.Compromete_Pedido = 1 ' 
	SET @SqlStr +=	' AND CB.Id_Tipo_Cbte = ''' + @Id_Cbte_Ent_Prot +'''' 
	SET @SqlStr +=	' AND CB.Id_Estado_Cbte IN (1,2,4) '
	SET @SqlStr +=	' AND PLP.Flag_Localidades = 2'
	SET @SqlStr +=	' AND PLP.Activo = 1'
	SET @SqlStr +=	' AND LOT.ID_TRANS IS NULL'
	SET @SqlStr +=	' AND LOP.Id_Producto IS NULL'
	SET @SqlStr +=	' AND CONVERT(DATE,PLP.Fecha_Hasta) >= CONVERT(DATE,GETDATE()) ' --25/04/2022 Se pone Fecha_Hasta (Periodo/Habilitar ingresos hasta), hasta ese momento la entrada va a figurar ocupada --06/05/2022 SE AGREGA CONVERT PARA NO VALIDAR LA HORA
	SET @SqlStr +=	' AND PR.Tipo = ''L'''
	SET @SqlStr +=	' AND CI.Flag_QA IN (''A'',''B'')'
	SET @SqlStr +=	' AND S.Flag_Ubic_Fija = 1'
	
	IF @Flag_Localidades = 2
	BEGIN
		SET @SqlStr +=	' AND CONVERT(VARCHAR(8),PLP.Fecha_Evento,112) = '''+ CONVERT(VARCHAR(8),@Fecha_Evento,112) +''''
    END

	IF(@pId_Cliente <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND (CL.Id_Cliente = ' + CONVERT(VARCHAR(10), @Id_Cliente_Ref) +  ' OR CL.Id_Cliente_Ref = ' + CONVERT(VARCHAR(10), @Id_Cliente_Ref) + ')'
	END

	IF(@pId_Lista_Precio > 0)
	BEGIN
		IF(@Id_Evento_Grupo <> 0)
		BEGIN
			SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PLP.Id_Lista_Precio IN (SELECT PLG.Id_Lista_Precio FROM #Evento_Grupo_Ticket PLG)'
		END
		ELSE
		BEGIN
			SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PLP.Id_Lista_Precio = '+ CONVERT(VARCHAR(10),@pId_Lista_Precio)
		END 
	END
	
	IF(@pId_Sector <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PR.Id_Sector = ' + CONVERT(VARCHAR(20),@pId_Sector) 
	END

	IF(@pId_Producto <> '')
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PR.Id_Producto = ''' + @pId_Producto +''''
	END

	IF(@pId_Trans <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND CB.Id_Trans = ' + @pId_Trans 
	END


	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@SqlStr: ' + @SqlStr
	END

	EXECUTE sp_executesql @SqlStr

	IF(@pModoDebug = 1)
	BEGIN
		PRINT ''
	END
END
/*======================================================================= PROTOCOLOS IMPRESOS para fechas o partidos con UBICACION NO FIJA=============================================================================*/
IF @pInc_ProtoImp = 1
BEGIN
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'PROTOCOLOS IMPRESOS para fechas o partidos con UBICACION NO FIJA'
	END

	SET @SqlStr =	''

	SET @SqlStr +=	'INSERT INTO #Rta_CPJ_Localidades_Ocupadas '
	SET @SqlStr +=	' SELECT'
	SET @SqlStr +=	' DISTINCT'
	SET @SqlStr +=	' CB.Id_Trans,'
	SET @SqlStr +=	' ISNULL(CI.Id_Cliente, 0) AS Id_Cliente,'
	SET @SqlStr +=	' ISNULL(CB.Id_Lista, 0) AS Id_Lista,'
	SET @SqlStr +=	' UPPER(LTRIM(RTRIM(ISNULL(CL.Razon_Social, '''')))) AS Razon_Social,'
	SET @SqlStr +=	' CI.Fecha_QA,'
	SET @SqlStr +=	' CI.Fecha_Venc,'
	SET @SqlStr +=	' PLP.Fecha_Desde,'
	SET @SqlStr +=	' PLP.Fecha_Hasta,'
	SET @SqlStr +=	' UPPER(LTRIM(RTRIM(ISNULL(PLP.Descripcion, '''')))) AS Descripcion,'
	SET @SqlStr +=	' UPPER(LTRIM(RTRIM(ISNULL(CI.Id_Producto, '''')))) AS Id_Producto,'
	SET @SqlStr +=	' UPPER(RTRIM(LTRIM(ISNULL(PR.Descripcion_Resumida, '''')))) AS Descripcion_Resumida,'
	SET @SqlStr +=	'''PI'' AS Estado,'
					/*
						A	-> Abono Comprado    
						ARA -> Abono Reserva Anticipada    
						AR	-> Abono Resevado     
						TV	-> Ticket Vendido
						TC	-> Ticket Canjeado
						TI	-> Ticket Impreso
						PI	-> Protocolos Impresos
						PU	-> Protocolo Fijo
						PV	-> En Proceso de Venta
					*/
	SET @SqlStr +=	' CI.Serie,'
	SET @SqlStr +=	' CI.Item,'
	SET @SqlStr +=	' CI.Flag_QA,'
	SET @SqlStr +=	' CB.Fecha,'
	SET @SqlStr +=	' dbo.CF_Cbte_Descrip(CB.Id_Trans) AS Cbte_Descrip,'
	SET @SqlStr +=	' CB.Id_Estado_Cbte,'
	SET @SqlStr +=	' CONVERT(INT, CI.Cantidad) AS Cantidad,'
	SET @SqlStr +=	' CB.Lote,'
	SET @SqlStr +=	' PR.Id_Sector,'
	SET @SqlStr +=	' S.Codigo AS Sector_Codigo,'
	SET @SqlStr +=	' S.Descripcion AS Sector_Nombre,'
	SET @SqlStr +=	' PR.Columna,'
	SET @SqlStr +=	' PR.Fila,'
	SET @SqlStr +=	' PLP.Fecha_Evento,'
	SET @SqlStr +=	' ISNULL(CB.Id_Lista, 0),'
	SET @SqlStr +=	' 0,'
	SET @SqlStr +=	' 0'
	SET @SqlStr +=	' FROM Cbtes CB, Cbtes_Items CI 
							LEFT JOIN #Rta_CPJ_Localidades_Ocupadas LOT 
								ON LOT.ID_TRANS = CI.ID_TRANS 
								AND LOT.ITEM = CI.ITEM 
						, Productos PR, Clientes CL, Prod_Listas_Precios PLP
						, Cbtes_Tipos CT, Empresas_Sedes_Sectores S '
	SET @SqlStr +=	' WHERE'
	SET @SqlStr +=	' CB.Id_Trans = CI.Id_Trans'
	SET @SqlStr +=	' AND CI.Id_Producto = PR.Id_Producto'
	SET @SqlStr +=	' AND PR.Id_Sector = S.Id_Sector'
	SET @SqlStr +=	' AND CI.Id_Cliente = CL.Id_Cliente'
	SET @SqlStr +=	' AND CB.Id_Lista = PLP.Id_Lista_Precio'
	SET @SqlStr +=	' AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte'
	SET @SqlStr +=	' AND CT.Compromete_Pedido = 1 ' 
	SET @SqlStr +=	' AND CB.Id_Tipo_Cbte = ''' + @Id_Cbte_Ent_Prot +'''' 
	SET @SqlStr +=	' AND CB.Id_Estado_Cbte IN (1,2,4) '
	SET @SqlStr +=	' AND PLP.Flag_Localidades = 2'
	SET @SqlStr +=	' AND PLP.Activo = 1'
	SET @SqlStr +=	' AND LOT.ID_TRANS IS NULL'
	SET @SqlStr +=	' AND CONVERT(DATE,PLP.Fecha_Hasta) >= CONVERT(DATE,GETDATE()) ' --25/04/2022 Se pone Fecha_Hasta (Periodo/Habilitar ingresos hasta), hasta ese momento la entrada va a figurar ocupada --06/05/2022 SE AGREGA CONVERT PARA NO VALIDAR LA HORA
	SET @SqlStr +=	' AND PR.Tipo = ''L'''
	SET @SqlStr +=	' AND CI.Flag_QA IN (''A'',''B'')'
	SET @SqlStr +=	' AND S.Flag_Ubic_Fija = 0'
	
	IF @Flag_Localidades = 2
	BEGIN
		SET @SqlStr +=	' AND CONVERT(VARCHAR(8),PLP.Fecha_Evento,112) = '''+ CONVERT(VARCHAR(8),@Fecha_Evento,112) +''''
    END

	IF(@pId_Cliente <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND (CL.Id_Cliente = ' + CONVERT(VARCHAR(10), @Id_Cliente_Ref) +  ' OR CL.Id_Cliente_Ref = ' + CONVERT(VARCHAR(10), @Id_Cliente_Ref) + ')'
	END

	IF(@pId_Lista_Precio > 0)
	BEGIN
		IF(@Id_Evento_Grupo <> 0)
		BEGIN
			SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PLP.Id_Lista_Precio IN (SELECT PLG.Id_Lista_Precio FROM #Evento_Grupo_Ticket PLG)'
		END
		ELSE
		BEGIN
			SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PLP.Id_Lista_Precio = '+ CONVERT(VARCHAR(10),@pId_Lista_Precio)
		END 
	END
	
	IF(@pId_Sector <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PR.Id_Sector = ' + CONVERT(VARCHAR(20),@pId_Sector) 
	END

	IF(@pId_Producto <> '')
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PR.Id_Producto = ''' + @pId_Producto +''''
	END

	IF(@pId_Trans <> 0)
	BEGIN
		SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND CB.Id_Trans = ' + @pId_Trans 
	END


	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@SqlStr: ' + @SqlStr
	END

	EXECUTE sp_executesql @SqlStr

	IF(@pModoDebug = 1)
	BEGIN
		PRINT ''
	END
END

	/*=======================================================================EN PROCESO DE VENTA=============================================================================*/
IF @pInc_ProcesoVta = 1
BEGIN
	IF(@pId_Cliente = 0)
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'EN PROCESO DE VENTA'
		END

		SET @cant_min_reserva = CONVERT(INT, dbo.CF_xParam('cant_min_reserva'))

		SET @SqlStr =	''

		SET @SqlStr +=	'INSERT INTO #Rta_CPJ_Localidades_Ocupadas '
		SET @SqlStr +=	' SELECT'
		SET @SqlStr +=	' 0 AS Id_Trans,'
		SET @SqlStr +=	' 0 AS Id_Cliente,'
		SET @SqlStr +=	' 0 AS Id_Lista,'
		SET @SqlStr +=	' '''' AS Razon_Social,'
		SET @SqlStr +=	' '''' AS Fecha_QA,'
		SET @SqlStr +=	' '''' AS Fecha_Venc,'
		SET @SqlStr +=	' '''' AS Fecha_Desde,'
		SET @SqlStr +=	' '''' AS Fecha_Hasta,'
		SET @SqlStr +=	' '''' AS Descripcion,'
		SET @SqlStr +=	' UPPER(LTRIM(RTRIM(ISNULL(PR.Id_Producto, '''')))) AS Id_Producto,'
		SET @SqlStr +=	' UPPER(RTRIM(LTRIM(ISNULL(PR.Descripcion_Resumida, '''')))) AS Descripcion_Resumida,'
		SET @SqlStr +=	'''PV'' AS Estado,'
					/*
						A	-> Abono Comprado     
						ARA -> Abono Reserva Anticipada    
						AR	-> Abono Resevado     
						TV	-> Ticket Vendido
						TC	-> Ticket Canjeado
						TI	-> Ticket Impreso
						PI	-> Protocolos Impresos
						PU	-> Protocolo Fijo
						PV	-> En Proceso de Venta
					*/
		SET @SqlStr +=	' '''' AS Serie,'
		SET @SqlStr +=	' 0 AS Item,'
		SET @SqlStr +=	' '''' AS Flag_QA,'
		SET @SqlStr +=	' '''' AS Fecha_Cbte,'
		SET @SqlStr +=	' '''' AS Cbte_Descrip,'
		SET @SqlStr +=	' 0 AS Id_Estado_Cbte,'
		SET @SqlStr +=	' 0 AS Cantidad,'
		SET @SqlStr +=	' '''' AS Lote,'
		SET @SqlStr +=	' PR.Id_Sector,'
		SET @SqlStr +=	' S.Codigo AS Sector_Codigo,'
		SET @SqlStr +=	' S.Descripcion AS Sector_Nombre,'
		SET @SqlStr +=	' PR.Columna,'
		SET @SqlStr +=	' PR.Fila,'
		SET @SqlStr +=	' '''' AS Fecha_Evento,'
		SET @SqlStr +=	' 0,'
		SET @SqlStr +=	' 0,'
		SET @SqlStr +=	' 0'
		SET @SqlStr +=	' FROM Productos PR, Empresas_Sedes_Sectores S'
		SET @SqlStr +=	' WHERE'
		SET @SqlStr +=	' PR.Fecha_Reserva >= DATEADD(MINUTE, (-1) * ' + CONVERT(VARCHAR(10), @cant_min_reserva) +', GETDATE())'
		SET @SqlStr +=	' AND PR.Id_Sector = S.Id_Sector'


		IF(@pId_Producto <> '')
		BEGIN
			SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PR.Id_Producto = ''' + @pId_Producto +''''
		END

		IF(@pId_Sector <> 0)
		BEGIN
			SET @SqlStr = RTRIM(LTRIM(@SqlStr)) + CHAR(13) +' AND PR.Id_Sector = ' + CONVERT(VARCHAR(20),@pId_Sector) 
		END

		IF(@pModoDebug = 1)
		BEGIN
			PRINT '@SqlStr: ' + @SqlStr
		END

		EXECUTE sp_executesql @SqlStr

		IF(@pModoDebug = 1)
		BEGIN
			PRINT ''
		END
	END
END
	/*====================================================================================================================================================*/

	IF @pInc_Libres IN (1 ,2)
	BEGIN
		SELECT Id_Sector,Codigo,Descripcion INTO #Sectores
		 FROM Empresas_Sedes_Sectores WHERE Flag_Ubic_Fija = 1 
		      OR (ISNULL(Flag_Ubic_Fija,0) = 0  AND Cant_Localidades > 0)

		IF(@pId_Sector <> 0)
		BEGIN
			DELETE #Sectores WHERE Id_Sector <>  @pId_Sector
		END


	    IF @pInc_Libres = 1
		BEGIN

			INSERT INTO #Rta_CPJ_Localidades_Ocupadas 
				SELECT 
						 0 AS Id_Trans,
						 0 AS Id_Cliente,
						 @pId_Lista_Precio AS Id_Lista,
						 '' AS Razon_Social,
						 '' AS Fecha_QA,
						 '' AS Fecha_Venc,
						 '' AS Fecha_Desde,
						 '' AS Fecha_Hasta,
						 '' AS Descripcion,
						 P.Id_Producto ,
						 P.Descripcion_Resumida,
						 'L' AS Estado,
						 '' AS Serie,
						 0 AS Item,
						 '' AS Flag_QA,
						 '' AS Fecha_Cbte,
						 '' AS Cbte_Descrip,
						 0 AS Id_Estado_Cbte,
						 0 AS Cantidad,
						 '' AS Lote,
						 P.Id_Sector,
						 S.Codigo AS Sector_Codigo,
						 S.Descripcion AS Sector_Nombre,
						 P.Columna,
						 P.Fila,
						 '' AS Fecha_Evento,
						 0,
						 0,
						 0
				FROM Productos P , Prod_Listas_Precios_Items I , #Sectores S
				WHERE P.Activo = 1 		 
						AND I.Id_Producto = P.Id_Producto
						AND I.Id_Lista_Precio = @pId_Lista_Precio
						AND P.Id_Sector = S.Id_Sector 
						AND NOT EXISTS (SELECT 1 FROM #Rta_CPJ_Localidades_Ocupadas R WHERE R.Id_Producto COLLATE Modern_Spanish_CI_AS = P.Id_Producto COLLATE Modern_Spanish_CI_AS)
			END
	    IF @pInc_Libres = 2
		BEGIN

			INSERT INTO #Rta_CPJ_Localidades_Ocupadas 
				SELECT 
						 0 AS Id_Trans,
						 0 AS Id_Cliente,
						 @pId_Lista_Precio AS Id_Lista,
						 '' AS Razon_Social,
						 '' AS Fecha_QA,
						 '' AS Fecha_Venc,
						 '' AS Fecha_Desde,
						 '' AS Fecha_Hasta,
						 '' AS Descripcion,
						 P.Id_Producto ,
						 P.Descripcion_Resumida,
						 'L' AS Estado,
						 '' AS Serie,
						 0 AS Item,
						 '' AS Flag_QA,
						 '' AS Fecha_Cbte,
						 '' AS Cbte_Descrip,
						 0 AS Id_Estado_Cbte,
						 0 AS Cantidad,
						 '' AS Lote,
						 P.Id_Sector,
						 S.Codigo AS Sector_Codigo,
						 S.Descripcion AS Sector_Nombre,
						 P.Columna,
						 P.Fila,
						 '' AS Fecha_Evento,
						 0,
						 0,
						 0
				FROM Productos P ,  #Sectores S
				WHERE P.Activo = 1 		
				        AND P.Vendible = 1 AND P.Tipo = 'L'
						AND P.Id_Sector = S.Id_Sector 
						AND NOT EXISTS (SELECT 1 FROM #Rta_CPJ_Localidades_Ocupadas R WHERE R.Id_Producto COLLATE Modern_Spanish_CI_AS = P.Id_Producto COLLATE Modern_Spanish_CI_AS)


			END
	END
	ELSE
	BEGIN
		SELECT Id_lista, 0 AS Id_Lista_Renov INTO #Renov FROM #Rta_CPJ_Localidades_Ocupadas WHERE 1=0
		IF(@pId_Cliente > 0)
		BEGIN

			DECLARE Cur_Renov CURSOR FOR 
			SELECT DISTINCT(Id_lista) FROM #Rta_CPJ_Localidades_Ocupadas

			OPEN Cur_Renov
			FETCH NEXT FROM Cur_Renov INTO @Id_lista_Origen
			WHILE @@FETCH_STATUS = 0
			BEGIN

				INSERT #Renov (Id_lista, Id_Lista_Renov)
				VALUES (@Id_lista_Origen, dbo.CFUJ_Venta_Abono_Lista_Renovacion ('{"ModoDebug":"0", 
																			   "Id_Cliente":"' + CONVERT(VARCHAR(15),@pId_Cliente) + '", 
																			   "Id_Lista_Precio_Abono_Origen":"'+ CONVERT(VARCHAR(10),@Id_lista_Origen)  +'", 
																			   "Fecha":"'+ CONVERT(VARCHAR(15),GETDATE(),112) +'"}'))

				FETCH NEXT FROM Cur_Renov INTO @Id_lista_Origen
			END
			CLOSE Cur_Renov
			DEALLOCATE Cur_Renov

			UPDATE #Rta_CPJ_Localidades_Ocupadas SET Id_Lista_Renov = CASE ISNULL(L.Id_Lista_Renov ,0)
																			WHEN 0 THEN R.Id_lista
																			ELSE L.Id_Lista_Renov
																			END 
					FROM #Rta_CPJ_Localidades_Ocupadas R LEFT OUTER JOIN #Renov L ON R.Id_lista = L.Id_lista
					
					

			--SELECT ARA.Id_Producto INTO #Rta_2 FROM #Rta_CPJ_Localidades_Ocupadas ARA, #Rta_CPJ_Localidades_Ocupadas A  
			--WHERE ARA.Id_Producto=A.Id_Producto AND ARA.Estado='ARA' AND ARA.Id_Lista_Renov = A.Id_Lista AND 

			SELECT I.Id_Producto INTO #Rta_2 
				FROM Cbtes_Items I, Cbtes C, Cbtes_Tipos T, Prod_Listas_Precios L ,#Rta_CPJ_Localidades_Ocupadas O
			    WHERE I.Id_Trans = C.Id_Trans
					AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte AND (T.Compromete_Factura = 1 OR T.Compromete_Remitos = 1 OR T.Compromete_Pedido = 1 ) 
					AND C.Id_Estado_Cbte IN(1,2,4)
					AND C.Id_Lista = L.Id_Lista_Precio 
					AND I.Id_Producto COLLATE SQL_Latin1_General_CP1_CI_AS = O.Id_Producto COLLATE SQL_Latin1_General_CP1_CI_AS
					AND C.Id_Lista IN (SELECT R.Id_Lista_Precio FROM Prod_Listas_Precios R , Eventos_Grupos E 
					        WHERE R.Id_Evento_Grupo = E.Id_Evento_Grupo AND E.Id_Evento_Grupo_Reservas = @Id_Evento_Grupo_Reservas)		        
			
			UPDATE #Rta_CPJ_Localidades_Ocupadas SET Estado='A' WHERE Id_Producto COLLATE SQL_Latin1_General_CP1_CI_AS  IN (SELECT Id_Producto COLLATE SQL_Latin1_General_CP1_CI_AS  FROM #Rta_2) AND Estado='ARA'

		END

	 
		IF OBJECT_ID('tempdb..#Renov') IS NOT NULL
		BEGIN
			DROP TABLE #Renov
		END

		IF OBJECT_ID('tempdb..#Rta_2') IS NOT NULL
		BEGIN
			DROP TABLE #Rta_2
		END
	 END
		
	IF UPPER(@pFormato) = 'TS' --Total por Sector
	BEGIN
		SELECT Sector_Codigo,Id_Sector,Sector_Nombre,COUNT(*) AS Total, 0 AS Ocupadas, 0 AS Libres, 0 AS Reservadas
			INTO #Tot_Sector FROM #Rta_CPJ_Localidades_Ocupadas GROUP BY Sector_Codigo,Id_Sector,Sector_Nombre



		SELECT Sector_Codigo,Id_Sector,Sector_Nombre,COUNT(*) AS Libres 
			INTO #Tot_Sector_L FROM #Rta_CPJ_Localidades_Ocupadas WHERE Estado = 'L' GROUP BY Sector_Codigo,Id_Sector,Sector_Nombre

		SELECT Sector_Codigo,Id_Sector,Sector_Nombre,COUNT(*) AS Ocupadas
			INTO #Tot_Sector_O FROM #Rta_CPJ_Localidades_Ocupadas WHERE Estado IN ('A','TV','TC','TI','PI','PU') GROUP BY Sector_Codigo,Id_Sector,Sector_Nombre
			
		SELECT Sector_Codigo,Id_Sector,Sector_Nombre,COUNT(*) AS Reservadas
			INTO #Tot_Sector_R FROM #Rta_CPJ_Localidades_Ocupadas WHERE Estado IN ('ARA','AR') GROUP BY Sector_Codigo,Id_Sector,Sector_Nombre

		UPDATE #Tot_Sector SET Libres = L.Libres	FROM #Tot_Sector T,  #Tot_Sector_L L WHERE T.Id_Sector = L.Id_Sector
		UPDATE #Tot_Sector SET Ocupadas = O.Ocupadas	FROM #Tot_Sector T,  #Tot_Sector_O O WHERE T.Id_Sector = O.Id_Sector
		UPDATE #Tot_Sector SET Reservadas = R.Reservadas	FROM #Tot_Sector T,  #Tot_Sector_R R WHERE T.Id_Sector = R.Id_Sector

		SELECT * FROM #Tot_Sector ORDER BY 3

	END
	ELSE IF UPPER(@pFormato) = 'TLP' --por lista
	BEGIN
		SELECT Id_Lista,Descripcion,Estado,COUNT(*) AS Cantidad FROM #Rta_CPJ_Localidades_Ocupadas  GROUP BY Id_Lista,Descripcion,Estado
	END	
	ELSE IF UPPER(@pFormato) = 'TT' --Total
	BEGIN
		SELECT Estado,COUNT(*) AS Total FROM #Rta_CPJ_Localidades_Ocupadas  GROUP BY Estado
	END
	ELSE IF UPPER(@pFormato) = 'TSP' --Total por Sector y Producto
	BEGIN
		SELECT Id_Sector, Sector_Nombre , Id_Producto, Descripcion_Resumida, Fila, Columna FROM #Rta_CPJ_Localidades_Ocupadas WHERE Estado = 'L'  AND Id_Sector = @pId_Sector
	END
	ELSE IF UPPER(@pFormato) = 'PE' --Prioridad por Estado
	BEGIN
		ALTER TABLE #Rta_CPJ_Localidades_Ocupadas ADD	Columna_Fisica SMALLINT
														,Fila_Fisica SMALLINT
		UPDATE #Rta_CPJ_Localidades_Ocupadas SET Columna_Fisica = P.Columna_Fisica , 
								Fila_Fisica = P.Fila_Fisica 
						FROM #Rta_CPJ_Localidades_Ocupadas R, Productos P
						WHERE P.Id_Producto COLLATE Modern_Spanish_CI_AS = R.Id_Producto COLLATE Modern_Spanish_CI_AS
		UPDATE #Rta_CPJ_Localidades_Ocupadas SET Columna_Fisica = Columna WHERE ISNULL(Columna_Fisica,0) = 0 AND ISNUMERIC(Columna) = 1
		UPDATE #Rta_CPJ_Localidades_Ocupadas SET Fila_Fisica = Fila WHERE ISNULL(Fila_Fisica,0) = 0 AND ISNUMERIC(Fila) = 1;


		-- Si hay mas de un resultado para el mismo id_producto tomaremos como prioridad el estado
		WITH RTA_LOC AS (
			SELECT 
				*,
				ROW_NUMBER() OVER (PARTITION BY Id_Producto ORDER BY
					CASE WHEN Estado = 'A'		THEN 1
						 WHEN Estado = 'ARA'	THEN 2
						 WHEN Estado = 'AR'		THEN 3
						 WHEN Estado = 'TV'		THEN 4
						 WHEN Estado = 'TC'		THEN 5
					  	 WHEN Estado = 'TI'		THEN 6
						 WHEN Estado = 'PI'		THEN 7
						 WHEN Estado = 'PU'		THEN 8
						 WHEN Estado = 'PV'		THEN 9
						 ELSE 10
					END) AS RowNum
			FROM 
				#Rta_CPJ_Localidades_Ocupadas
		)
		SELECT 
			*
		FROM 
			RTA_LOC
		WHERE 
			RowNum = 1
		ORDER BY 
			Sector_Codigo, Id_Sector, Columna_Fisica, Fila_Fisica, Fecha_Hasta DESC;
	END
	ELSE
	BEGIN
		ALTER TABLE #Rta_CPJ_Localidades_Ocupadas ADD	Columna_Fisica SMALLINT
														,Fila_Fisica SMALLINT
		UPDATE #Rta_CPJ_Localidades_Ocupadas SET Columna_Fisica = P.Columna_Fisica , 
								Fila_Fisica = P.Fila_Fisica 
						FROM #Rta_CPJ_Localidades_Ocupadas R, Productos P
						WHERE P.Id_Producto COLLATE Modern_Spanish_CI_AS = R.Id_Producto COLLATE Modern_Spanish_CI_AS
		UPDATE #Rta_CPJ_Localidades_Ocupadas SET Columna_Fisica = Columna WHERE ISNULL(Columna_Fisica,0) = 0 AND ISNUMERIC(Columna) = 1
		UPDATE #Rta_CPJ_Localidades_Ocupadas SET Fila_Fisica = Fila WHERE ISNULL(Fila_Fisica,0) = 0 AND ISNUMERIC(Fila) = 1

		SELECT * FROM #Rta_CPJ_Localidades_Ocupadas ORDER BY Sector_Codigo,Id_Sector,Columna_Fisica,Fila_Fisica, Fecha_Hasta desc

	END

	/*====================================================================================================================================================*/

	IF OBJECT_ID('tempdb..#Rta_CPJ_Localidades_Ocupadas') IS NOT NULL
	BEGIN
		DROP TABLE #Rta_CPJ_Localidades_Ocupadas
	END

	IF OBJECT_ID('tempdb..#Tot_Sector') IS NOT NULL
	BEGIN
		DROP TABLE #Tot_Sector
	END

	IF OBJECT_ID('tempdb..#Tot_Sector_L') IS NOT NULL
	BEGIN
		DROP TABLE #Tot_Sector_L
	END

	IF OBJECT_ID('tempdb..#Tot_Sector_O') IS NOT NULL
	BEGIN
		DROP TABLE #Tot_Sector_O
	END

	IF OBJECT_ID('tempdb..#ARA') IS NOT NULL
	BEGIN
		DROP TABLE #ARA
	END
	
	IF OBJECT_ID('tempdb..#AR') IS NOT NULL
	BEGIN
		DROP TABLE #AR
	END

	IF OBJECT_ID('tempdb..#rta') IS NOT NULL
	BEGIN
		DROP TABLE #rta
	END

	IF OBJECT_ID('tempdb..#rta2') IS NOT NULL
	BEGIN
		DROP TABLE #rta2
	END

	IF OBJECT_ID('tempdb..#ya_renovadas') IS NOT NULL
	BEGIN
		DROP TABLE #ya_renovadas
	END
	

	/*====================================================================================================================================================*/

	IF @pFlagUsarTrans <> 0 COMMIT
	
	/*====================================================================================================================================================*/

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: [CPJ_Localidades_Ocupadas]'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  ROLLBACK

	RETURN 9999
END CATCH

RETURN 0 



/*

EXEC [CPJ_Localidades_Ocupadas] '{"ModoDebug":"1","Id_Cliente":"0","Id_Lista_Precio":"2002","Id_Sector":"28","Inc_Libres":"1","Formato":"TS"}'

EXEC [CPJ_Localidades_Ocupadas] '{"ModoDebug":"1","Id_Cliente":"0","Id_Lista_Precio":"672","Inc_Libres":"2","Formato":"TS"}'
EXEC [CPJ_Localidades_Ocupadas] '{"ModoDebug":"1","Id_Cliente":"0","Id_Lista_Precio":"679","Inc_Libres":"2","Formato":"TS"}'
EXEC [CPJ_Localidades_Ocupadas] '{"ModoDebug":"1","Id_Cliente":"0","Id_Lista_Precio":"678","Inc_Libres":"1","Formato":"TS"}'
EXEC [CPJ_Localidades_Ocupadas] '{"ModoDebug":"0","id_sector":"26","Id_Lista_Precio":"678","Inc_Libres":"1"}'

EXEC [CPJ_Localidades_Ocupadas] '{"ModoDebug":"1","Id_Cliente":"0","Id_Lista_Precio":"2002","Inc_Libres":"1","Formato":"TT"}'

EXEC [CPJ_Localidades_Ocupadas] '{"ModoDebug":"0","Id_Cliente":"0","Id_Lista_Precio":"2154","Inc_Abonos_Grup_Eve":"","Inc_Libres":"1",}'
EXEC [CPJ_Localidades_Ocupadas] '{"ModoDebug":"0","id_sector":"26","Id_Lista_Precio":"618","Inc_Libres":"1"}'

EXEC [CPJ_Localidades_Ocupadas] '{"FlagUsarTrans":"0", "ModoDebug":"0", "Id_Sector":"", "Id_Cliente":"0", "Id_Lista_Precio":"1024", "Flag_Interface":"G" }'


