		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Fac_Fin (3)'
		PRINT 'Parametros:'
		PRINT '@JSON_Parametros_Stored_Invocado: ' + @JSON_Parametros_Stored_Invocado
	END	


	EXEC @UltError = dbo.CPJ_Cbtes_Fac_Fin @JSON_Parametros_Stored_Invocado

	IF(@UltError <> 0)
	BEGIN
		RAISERROR ('Error when calling CPJ_Cbtes_Fac_Fin (3)', 16, 1) 
	END
 
    ------------------- FIN ND MESES INCLUIDOS --------------------------------------------------------


	---- GENERO CUOTAS MORATORIA

    
	SET @Precio = (SELECT dbo.CFUJ_Moratoria_Deuda(@JSON_Parametros_Stored_Invocado)) / @Cant_Cuotas_Finan
	
	SET @Items = 2
	WHILE(@Items <= @Cant_Cuotas_Finan)
	BEGIN
	    SET @Fecha_Vto = DATEADD(MONTH,@Items-1,dbo.CF_FOMONTH(GETDATE()))

		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Genero ND POR Cantidad cuotas moratoria'
			PRINT 'Total de Items en ND: ' + CONVERT(VARCHAR(4),@Id_Grupo_Cont)
			PRINT 'Genero ND tipo: ' + @Tipo_ND
		END

		SET @JSON_Parametros_Stored_Invocado =	'{' +
														dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'TINYINT') + ',' +
														dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'TINYINT') + ',' +										
														dbo.CF_Json_ParsearVariable('Id_Usuario', -1, 'SMALLINT') + ',' +
														dbo.CF_Json_ParsearVariable('Omitir_Resultado_OK', 1, 'TINYINT') + ',' +
														dbo.CF_Json_ParsearVariable('Lote', '', 'VARCHAR(20)') + ',' +
														dbo.CF_Json_ParsearVariable('Fecha', GETDATE(), 'DATETIME') + ',' +
														dbo.CF_Json_ParsearVariable('FechaVence', @FECHA_VTO, 'DATETIME') + ',' +
														dbo.CF_Json_ParsearVariable('Id_Cliente', @pId_Cliente, 'INT') + ',' +
														dbo.CF_Json_ParsearVariable('Id_Tipo_Cbte', @Tipo_ND, 'CHAR(4)') + ',' +
														dbo.CF_Json_ParsearVariable('Id_Cond_Pago', @Cond_Pago, 'SMALLINT') + ',' +
                                                        dbo.CF_Json_ParsearVariable('Id_Tarjeta',@pId_Tarjeta,'VARCHAR(10)') + ',' +
                                                        dbo.CF_Json_ParsearVariable('Tar_Nro',@pTar_Nro,'VARCHAR(50)') + ',' +
														dbo.CF_Json_ParsearVariable('Id_Moneda', 'PES', 'CHAR(3)') + ',' +
														dbo.CF_Json_ParsearVariable('Id_Lista_Precio', @Id_Lista_Precio_Cbtes, 'SMALLINT') + ',' +
														dbo.CF_Json_ParsearVariable('Id_Contrato', @Id_Contrato, 'INT') +
														'}'

		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Fac_Generar'
			PRINT 'Parametros:'
			PRINT '@JSON_Parametros_Stored_Invocado: ' + @JSON_Parametros_Stored_Invocado
		END														
													
		EXEC @UltError = dbo.CPJ_Cbtes_Fac_Generar @JSON_Parametros_Stored_Invocado

		IF(@UltError <> 0)
		BEGIN
			RAISERROR ('Error when calling CPJ_Cbtes_Fac_Generar ND moratoria', 16, 1) 
		END

		SELECT @Id_Trans_ND = MAX(Id_Trans) FROM Cbtes WHERE Id_Contrato = @Id_Contrato AND Id_Tipo_Cbte = @Tipo_ND

		----GENERO LOS ITEMS
	
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Transaccion de ND generada: ' + CONVERT(VARCHAR(25),@Id_Trans_ND)
			PRINT 'Genero item de Moratoria para ND por el total de ' + CONVERT(VARCHAR(30),@Precio)
		END


		SET @JSON_Parametros_Stored_Invocado =	'{' +
													dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'TINYINT') + ',' +										
													dbo.CF_Json_ParsearVariable('Id_Trans', @Id_Trans_ND, 'INT') + ',' +
													dbo.CF_Json_ParsearVariable('Omitir_Resultado_OK', 1, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('Id_Producto', @Id_Producto_Item, 'VARCHAR(14)') + ',' +
													dbo.CF_Json_ParsearVariable('Cantidad', 1, 'DECIMAL(15,5)') + ',' +
													dbo.CF_Json_ParsearVariable('Fecha_QA', @FECHA_VTO, 'DATETIME') + ',' +
													dbo.CF_Json_ParsearVariable('Fecha_Venc', @FECHA_VTO, 'DATETIME') + ',' +
													dbo.CF_Json_ParsearVariable('Id_Cliente', @pId_Cliente, 'INT') + ',' +
													dbo.CF_Json_ParsearVariable('Lote', '', 'VARCHAR(20)') + ',' +
													dbo.CF_Json_ParsearVariable('Refacturar', 1, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('Bonif', 0, 'DECIMAL(5,2)') + ',' +
													dbo.CF_Json_ParsearVariable('Precio_Grav', @Valor_Cuota, 'DECIMAL(15,5)') + ',' +
													dbo.CF_Json_ParsearVariable('Cantidad_Equiv', 0, 'DECIMAL(15,5)') + ',' +
													dbo.CF_Json_ParsearVariable('Precio_Exen', 0, 'DECIMAL(15,5)') + 
												'}'

		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Fac_Generar_Item'
			PRINT 'Parametros:'
			PRINT '@JSON_Parametros_Stored_Invocado: ' + @JSON_Parametros_Stored_Invocado
		END			

		EXEC @UltError = dbo.CPJ_Cbtes_Fac_Generar_Item @JSON_Parametros_Stored_Invocado

		IF(@UltError <> 0)
		BEGIN
			RAISERROR ('Error when calling CPJ_Cbtes_Fac_Generar_Item', 16, 1) 
		END

		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Genero ND'
		END

		SET @JSON_Parametros_Stored_Invocado =	'{' +
													dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('ModoDebug', @pModoDebug, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('Omitir_Result_OK', 1, 'TINYINT') + ',' +
													dbo.CF_Json_ParsearVariable('Id_Trans', @Id_Trans_ND, 'INT') + 
												'}'
	
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Fac_Fin (3)'
			PRINT 'Parametros:'
			PRINT '@JSON_Parametros_Stored_Invocado: ' + @JSON_Parametros_Stored_Invocado
		END	

		EXEC @UltError = dbo.CPJ_Cbtes_Fac_Fin @JSON_Parametros_Stored_Invocado

		IF(@UltError <> 0)
		BEGIN
			RAISERROR ('Error when calling CPJ_Cbtes_Fac_Fin (3)', 16, 1) 
		END

		SET @Items += 1
	END

	SET @Id_Trans_Generada = (SELECT MIN(C.Id_Trans) FROM Cbtes C, Cbtes_Tipos T 
	       WHERE C.Id_Contrato = @Id_Contrato 
		   AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
		   AND T.Compromete_Factura = 1
		   AND C.Id_Estado_Cbte = 1
		   )
	
	--RAISERROR ('prueba trans', 16, 1) 

	IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0
	BEGIN
		COMMIT
	END

	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SET @rtaMsjStored	=	@Id_Trans_Generada

		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,@Id_Contrato	AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Moratoria_Generar'
	END
	
END TRY
BEGIN CATCH

	IF  (SELECT COUNT(*) FROM @Respuesta_ WHERE [ErrorNumber] > 0 ) > 0
	BEGIN
		SELECT * FROM @Respuesta_
	END
	ELSE
	BEGIN
		EXECUTE usp_GetErrorInfo
	END

	IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0
	BEGIN
		ROLLBACK
	END

	RETURN 9999

END CATCH
GO


CREATE  PROCEDURE [dbo].[CPJ_Pagos_CC] @pJson VARCHAR(8000)
AS


SET NOCOUNT ON

PRINT @pJson

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug			    	TINYINT
DECLARE @pId_Usuario			    SMALLINT
DECLARE @pFecha_Desde			    DATETIME
DECLARE @pFecha_Hasta			    DATETIME
DECLARE @pId_Centro_Costo			CHAR(10)
DECLARE @pId_Unid_Negocio			CHAR(10)
DECLARE @pSoloResultado	    		TINYINT			
DECLARE @pFlag_Filtrar_CC			TINYINT			
DECLARE @pFormato					VARCHAR(10)		

SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Usuario				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), 0)
SET @pFecha_Desde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde')), '19000101')
SET @pFecha_Hasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta')), '19000101')
SET @pId_Centro_Costo			= ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Centro_Costo')), '')
SET @pId_Unid_Negocio			= ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Unid_Negocio')), '')
SET @pSoloResultado				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'SoloResultado')), 0)
SET @pFlag_Filtrar_CC			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Filtrar_CC')), 0)
SET @pFormato				    = ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Tipo_Reporte')), 'CTA')
/*FIN Variables recibidas por parametro a traves del JSON*/


/*Variables Locales*/
DECLARE @SqlStr						NVARCHAR(MAX)
DECLARE @Id_Trans					INT
DECLARE @Alias						DECIMAL(12,0)
DECLARE @Nro_Cta_Contable			VARCHAR(20)
DECLARE @Debe						DECIMAL(12,2)
DECLARE @Haber						DECIMAL(12,2)
DECLARE @Fecha						DATETIME
DECLARE @Descripcion				VARCHAR(80)
DECLARE @Centro_Costo				VARCHAR(200)
DECLARE @Centro_Costo_Padre1		VARCHAR(200)
DECLARE @Centro_Costo_Padre2		VARCHAR(200)
DECLARE @Destinatario				VARCHAR(100)
DECLARE @Observacion_Orig			VARCHAR(8000)
DECLARE @Observacion_Dest			VARCHAR(8000)
DECLARE @Importe					DECIMAL(12,2)
DECLARE @Imp_Total_Fac				DECIMAL(12,2)
DECLARE @Imp_Aplicado				DECIMAL(12,2)
DECLARE @Imp_Fac					DECIMAL(12,2)
DECLARE @Coef_Aplic					DECIMAL(12,2)
DECLARE @Id_Trans_CCC				INT
DECLARE @Id_Centro_Costo_Padre1		CHAR(10)
DECLARE @Id_Centro_Costo_Padre2		CHAR(10)
DECLARE @Mes_Desde					DATETIME
DECLARE @Mes_Hasta					DATETIME
DECLARE @Mes_Nro					TINYINT
DECLARE @Suma_Debe					DECIMAL(16,2)
DECLARE @Suma_Haber					DECIMAL(16,2)
DECLARE @Suma_Saldo					DECIMAL(16,2)
DECLARE @Id_Centro_Costo			CHAR(10)
DECLARE @Id_Centro_Costo_Cur		CHAR(10)
/*FIN Variables Locales*/

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_BalanceCC_Rpt'
		PRINT 'Parametros: '
		PRINT '@pFormato: ' +  @pFormato
		PRINT '@pId_Usuario: ' + CONVERT(VARCHAR(10), @pId_Usuario) + '. @pFecha_Desde: ' + CONVERT(VARCHAR(10), @pFecha_Desde, 112) + '. @pFecha_Hasta: ' + CONVERT(VARCHAR(10), @pFecha_Hasta, 112) + '. @pId_Centro_Costo: ' + CONVERT(VARCHAR(10), @pId_Centro_Costo)
		PRINT '@pId_Unid_Negocio: ' + @pId_Unid_Negocio + '. @pSoloResultado: ' + CONVERT(VARCHAR(10), @pSoloResultado) + '. @pFlag_Filtrar_CC: ' + CONVERT(VARCHAR(10), @pFlag_Filtrar_CC)
	END

	/*=============================================================================================================================*/
	/*=============================================================================================================================*/

	IF(@pId_Usuario = 0)
	BEGIN
		SET @pId_Usuario = -1
	END
	
	IF(@pFormato = '')										RAISERROR ('Tipo_Reporte can not be blank.', 16,  1)
	IF(@pFecha_Desde = '19000101')								RAISERROR ('Fecha_Desde can not be blank.', 16,  1)
	IF(@pFecha_Hasta = '19000101')								RAISERROR ('Fecha_Hasta can not be blank.', 16,  1) 
	IF(@pFecha_Desde >= @pFecha_Hasta)							RAISERROR ('Fecha_Desde can not be bigger or equal than Fecha_Hasta.', 16,  1)
	IF(DATEDIFF(YEAR, @pFecha_Desde, @pFecha_Hasta) > 0)		RAISERROR ('Diference between Fecha_Desde and Fecha_Hasta can not be bigger than a year.', 16,  1) 
	

	/*=============================================================================================================================*/

	IF(@pFlag_Filtrar_CC <> 0)
	BEGIN
		SET @Id_Centro_Costo = @pId_Centro_Costo
	END

	/*=============================================================================================================================*/
	
	CREATE TABLE #Pagos_CC
	(
	Id_Trans_O						INT,
	Id_Trans_D						INT,
	Alias							DECIMAL(12,0),
	Nro_Cta_Contable				VARCHAR(20),
	Debe							DECIMAL(12,2),
	Haber							DECIMAL(12,2),
	Saldo							DECIMAL(12,2),
	Fecha							DATETIME,
	Cta_Contable					VARCHAR(80),
	Id_Centro_Costo					VARCHAR(10),
	Centro_Costo					VARCHAR(200),
	Centro_Costo2					VARCHAR(200),
	Centro_Costo3					VARCHAR(200),
	Destinatario					VARCHAR(100),
	Observacion_Orig				VARCHAR(8000),
	Observacion_Dest				VARCHAR(8000)
	)




	/*=============================================================================================================================*/

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'OP Varias'
	END

	CREATE TABLE #Pagos_CC_OP_Varias
				(
				Id_Trans						INT,
				Alias							DECIMAL(12,0),
				Nro_Cta_Contable				VARCHAR(20),
				Debe							DECIMAL(12,2),
				Haber							DECIMAL(12,2),
				Fecha							DATETIME,
				Descripcion						VARCHAR(80),
				Destinatario					VARCHAR(100),
				Observacion_Orig				VARCHAR(8000),
				Observacion_Dest				VARCHAR(8000),
				Id_Centro_Costo					VARCHAR(10)
				)
	
	/*=============================================================================================================================*/

	SET @SqlStr =	'INSERT INTO #Pagos_CC_OP_Varias (Id_Trans, Alias, Nro_Cta_Contable, Debe, Haber, Fecha, Descripcion, Destinatario, Observacion_Orig, Observacion_Dest, Id_Centro_Costo) '

	SET @SqlStr =	RTRIM(LTRIM(@SqlStr))										+ CHAR(13) + 
					'SELECT '													+ CHAR(13) + 
					'C.Id_Trans, '												+ CHAR(13) + 
					'O.Alias, '													+ CHAR(13) + 
					'O.Nro_Cta_Contable, '										+ CHAR(13) + 
					'C.Debe, '													+ CHAR(13) + 
					'C.Haber, '													+ CHAR(13) + 
					'E.Fecha, '													+ CHAR(13) + 
					'O.Descripcion AS Cta_Contable, '							+ CHAR(13) + 
					'ISNULL(E.Destinatario, '''') AS Destinatario, '			+ CHAR(13) + 
					'ISNULL(CONVERT(VARCHAR(8000), E.Observacion), '''') AS Observacion_Orig, '+ CHAR(13) + 
					'ISNULL(CONVERT(VARCHAR(8000), E.Observacion), '''') AS Observacion_Dest, '+ CHAR(13) +
					'ISNULL(C.Id_Centro_Costo, '''') AS Id_Centro_Costo '		+ CHAR(13) +
					'FROM Cbtes_Ctas_Contables C, Cbtes E,Cbtes_Tipos T,Pla_Ctas_Cuentas_Contables O ' + CHAR(13) + 
					'WHERE '													+ CHAR(13) + 
					'C.Id_Trans = E.Id_Trans '									+ CHAR(13) + 
					'AND E.Id_Tipo_Cbte = T.Id_Tipo_Cbte '						+ CHAR(13) + 	
					'AND O.Id_Cta_Contable = C.Id_Cta_Contable '				+ CHAR(13) +
					'AND ISNULL(E.Id_Proveedor, 0) = 0 '						+ CHAR(13) + 					
					'AND E.Id_Estado_Cbte NOT IN (0,3) '
					
					
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND E.Fecha >= ''' + CONVERT(VARCHAR(10), @pFecha_Desde, 112) + ''' ' + CHAR(13) +
					'AND E.Fecha < ''' + CONVERT(VARCHAR(10), DATEADD(DAY, 1, @pFecha_Hasta), 112) + ''' '

	IF(@pFlag_Filtrar_CC <> 0)
	BEGIN		
		SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
						'AND C.Id_Centro_Costo = ''' + @pId_Centro_Costo + ''' '
	END
	
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND T.Compromete_Pagos IN (1,-1)'

	IF(@pSoloResultado = 1)
	BEGIN
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) +
					'AND ISNULL(O.Tipo, '''') IN (''+'',''-'') '
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT ''
		PRINT '@SqlStr (Orden Pagos Varias): '
		PRINT @SqlStr
		PRINT ''
	END

	EXECUTE sp_executesql @SqlStr

	/*=============================================================================================================================*/

		INSERT INTO #Pagos_CC
								(Id_Trans_O,
								Id_Trans_D,
								Alias,
								Nro_Cta_Contable,
								Debe,
								Haber,
								Saldo,
								Fecha,
								Cta_Contable,
								Id_Centro_Costo,
								Centro_Costo,
								Centro_Costo2,
								Centro_Costo3,
								Destinatario,
								Observacion_Orig,
								Observacion_Dest)
		SELECT 
								P.Id_Trans,
								0,
								p.Alias,
								p.Nro_Cta_Contable, 
								ISNULL(p.Debe,0), 
								ISNULL(p.Haber,0), 
								ISNULL(p.Debe,0) - ISNULL(p.Haber,0),
								p.Fecha, 
								p.Descripcion,
								ISNULL(P.Id_Centro_Costo,''),
								CC.Descripcion,
								'',
								'',
								p.Destinatario,
								p.Observacion_Orig,
								p.Observacion_Dest
								FROM #Pagos_CC_OP_Varias P,  Centro_Costos CC
								WHERE ISNULL(P.Id_Centro_Costo,'') = CC.Id_Centro_Costo


	/*=============================================================================================================================*/
	/*=============================================================================================================================*/

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'OP Proveedores'
	END

	CREATE TABLE #Pagos_CC_OP_Proveedores
			(
			Id_Trans_Aplica					INT,
			Importe							DECIMAL(12,2),
			Imp_Total_Fac					DECIMAL(12,2),
			Id_Trans_CCC					INT,
			Alias							DECIMAL(12,0),
			Nro_Cta_Contable				VARCHAR(20),
			Debe							DECIMAL(12,2),
			Haber							DECIMAL(12,2),
			Fecha_OP						DATETIME,
			Descripcion						VARCHAR(80),
			Destinatario					VARCHAR(100),
			Observacion_Orig				VARCHAR(8000),
			Observacion_Dest				VARCHAR(8000),
			Id_Centro_Costo					VARCHAR(10)
			)
	
	/*=============================================================================================================================*/

	SET @SqlStr =	'INSERT INTO #Pagos_CC_OP_Proveedores (Id_Trans_Aplica, Importe, Imp_Total_Fac, Id_Trans_CCC, Alias, Nro_Cta_Contable, Debe, Haber, Fecha_OP, Descripcion, Destinatario, Observacion_Orig, Observacion_Dest, Id_Centro_Costo) '
	
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr))											+ CHAR(13) + 
					'SELECT '														+ CHAR(13) + 
					'A.Id_Trans, '													+ CHAR(13) + 
					'A.Importe, '													+ CHAR(13) + 
					'Fac.Imp_Total, '												+ CHAR(13) + 
					'OP.Id_Trans, '													+ CHAR(13) + 
					'O.Alias, '														+ CHAR(13) +
					'O.Nro_Cta_Contable, '											+ CHAR(13) + 
					'C.Debe, '														+ CHAR(13) + 
					'C.Haber, '														+ CHAR(13) + 
					'OP.Fecha, '													+ CHAR(13) + 
					'O.Descripcion, '												+ CHAR(13) + 
					'ISNULL(Fac.Destinatario, '''') AS Destinatario, '				+ CHAR(13) + 
					'ISNULL(CONVERT(VARCHAR(8000), Fac.Observacion), '''') + dbo.CF_Cbte_Descrip (OP.Id_Trans) AS Observacion_Orig, '+ CHAR(13) + 
					'ISNULL(CONVERT(VARCHAR(8000), OP.Observacion), '''') AS Observacion_Dest, '+ CHAR(13) +
					'ISNULL(C.Id_Centro_Costo, '''') AS Id_Centro_Costo '			+ CHAR(13) +
					'FROM Cbtes_Aplica A,Cbtes_Ctas_Contables C, Cbtes OP,Cbtes Fac,Cbtes_Tipos CTOP, Cbtes_Tipos CTFA,Pla_Ctas_Cuentas_Contables O ' + CHAR(13) + 
					'WHERE '														+ CHAR(13) + 
					'C.id_trans = A.id_trans '										+ CHAR(13) + 
					'AND A.id_trans_D = OP.id_trans '								+ CHAR(13) + 
					'AND Fac.id_trans = C.id_trans '								+ CHAR(13) + 
					'AND OP.id_Tipo_Cbte = CTOP.Id_Tipo_Cbte '						+ CHAR(13) +
					'AND Fac.id_tipo_cbte= CTFA.Id_Tipo_Cbte	' 	                + CHAR(13) +
					'AND O.Id_Cta_Contable = C.Id_Cta_Contable '					+ CHAR(13) + 
					'AND OP.Id_Proveedor > 0 '										+ CHAR(13) + 
					'AND OP.Id_Estado_Cbte NOT IN (0,3) '							+ CHAR(13) + 
					'AND Fac.Id_Estado_Cbte NOT IN (0,3) '                         

					
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND OP.Fecha >= ''' + CONVERT(VARCHAR(10), @pFecha_Desde, 112) + ''' ' + CHAR(13) +
					'AND OP.Fecha < ''' + CONVERT(VARCHAR(10), DATEADD(DAY, 1, @pFecha_Hasta), 112) + ''' '

	IF(@pFlag_Filtrar_CC <> 0)
	BEGIN
		SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
						'AND C.Id_Centro_Costo = ''' + @pId_Centro_Costo + ''' '
	END

	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
					'AND CTOP.Compromete_Pagos IN (1,-1)'

	IF(@pSoloResultado = 1)
	BEGIN
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) +
					'AND ISNULL(O.Tipo, '''') IN (''+'',''-'') '
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT ''
		PRINT '@SqlStr (OP Proveedores): '
		PRINT @SqlStr
		PRINT ''
	END

	EXECUTE sp_executesql @SqlStr

	/*=============================================================================================================================*/

		INSERT INTO #Pagos_CC
				(Id_Trans_O,
				Id_Trans_D,
				Alias,
				Nro_Cta_Contable,
				Debe,
				Haber,
				Saldo,
				Fecha,
				Cta_Contable,
				Id_Centro_Costo,
				Centro_Costo,
				Centro_Costo2,
				Centro_Costo3,
				Destinatario,
				Observacion_Orig,
				Observacion_Dest)
		SELECT 
			P.Id_Trans_Aplica,
			P.Id_Trans_CCC,
			P.Alias,
			P.Nro_Cta_Contable, 
			P.Debe * P.Importe / P.Imp_Total_Fac,   
			P.Haber * P.Importe / P.Imp_Total_Fac , 
			(P.Debe * P.Importe / P.Imp_Total_Fac ) - (  P.Haber * P.Importe / P.Imp_Total_Fac) , 
			P.Fecha_OP, 
			P.Descripcion,
			P.Id_Centro_Costo,
			CC.Descripcion,
			'',
			'',
			P.Destinatario,
			P.Observacion_Orig,
			P.Observacion_Dest
			FROM #Pagos_CC_OP_Proveedores P,	 Centro_Costos CC
			WHERE ISNULL(P.Id_Centro_Costo,'') = CC.Id_Centro_Costo


	/*=============================================================================================================================*/


	/*=============================================================================================================================*/
	
	IF(@pFormato = 'D')
	BEGIN
		--Explosion por Cbtes

		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Explosion por Comprobantes'
			PRINT '@pId_Centro_Costo:' + @pId_Centro_Costo + '. @pFecha_Desde: ' + CONVERT(VARCHAR(10), @pFecha_Desde, 102) + '. @pFecha_Hasta: ' + CONVERT(VARCHAR(10), @pFecha_Hasta, 102)
		END

		SELECT
		Id_Centro_Costo,
		Centro_Costo ,
		Nro_Cta_Contable AS Nro_Cta, 
		Cta_Contable AS Cta,
		Id_Trans_O AS Trans_Origen,
		CONVERT(DATE, Fecha) AS Fecha,
		dbo.CF_Cbte_Descrip(Id_Trans_O) AS Cbte,
		Destinatario AS Destinatario,
		Observacion_Orig AS Obs,
		Id_Trans_D AS Trans_Destino,
		'' AS Fecha_Destino,
		dbo.CF_Cbte_Descrip(Id_Trans_D) AS Cbte_Destino,
		Observacion_Dest AS Obs_Destino,
		Debe,
		Haber,
		Saldo
		FROM #Pagos_CC
		WHERE Fecha >= @pFecha_Desde
		AND Fecha < DATEADD(DAY, 1, @pFecha_Hasta)
		ORDER BY Nro_Cta_Contable, Fecha
	END
	
	IF(@pFormato = 'CTA')
	BEGIN
		/*=============================================================================================================================*/
		/*=============================================================================================================================*/

		--Agrupacion por Cuentas Mensual
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Agrupacion por Cuentas'
		END

		/*=============================================================================================================================*/
		SELECT
		Id_Centro_Costo,
		Centro_Costo ,
		Nro_Cta_Contable AS Nro_Cta, 
		Cta_Contable AS Cta,
		SUM(Debe) AS Debe,
		SUM(Haber) AS Haber,
		SUM(Saldo) AS Saldo
		FROM #Pagos_CC
		WHERE Fecha >= @pFecha_Desde
		AND Fecha < DATEADD(DAY, 1, @pFecha_Hasta)
		GROUP BY Id_Centro_Costo,Centro_Costo,Nro_Cta_Contable,Cta_Contable 
		ORDER BY 2
	

	END

	IF(@pFormato = 'CC')
	BEGIN
		/*=============================================================================================================================*/
		/*=============================================================================================================================*/

		--Agrupacion por Cuentas Mensual
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Agrupacion por CC'
		END

		/*=============================================================================================================================*/
		SELECT
		Id_Centro_Costo,
		Centro_Costo ,
		SUM(Debe) AS Debe,
		SUM(Haber) AS Haber,
		SUM(Saldo) AS Saldo
		FROM #Pagos_CC
		WHERE Fecha >= @pFecha_Desde
		AND Fecha < DATEADD(DAY, 1, @pFecha_Hasta)
		GROUP BY Id_Centro_Costo,Centro_Costo
		ORDER BY 2
	

	END



	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Pagos_CC_OP_Varias') 
		DROP TABLE #Pagos_CC_OP_Varias

	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Pagos_CC_OP_Proveedores') 
		DROP TABLE #Pagos_CC_OP_Proveedores

	IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Pagos_CC') 
		DROP TABLE #Pagos_CC

	
	/*=============================================================================================================================*/
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_BalanceCC_Rpt'
	END

/*
EXEC dbo.CPJ_Pagos_CC '{
							"ModoDebug":"1",
							"Id_Usuario":"-1",
							"Tipo_Reporte":"D",
							"Fecha_Desde":"20210101",
							"Fecha_Hasta":"20211231",
							"Id_Centro_Costo":"",
							"Id_Unid_Negocio":"",
							"SoloResultado":"0",
							"Flag_Filtrar_CC":"0"
							}'

EXEC CPJ_BalanceCC_Pagos_Rpt '{
							"ModoDebug":"1",
							"Id_Usuario":"-1",
							"Tipo_Reporte":"AGRUP",
							"Fecha_Desde":"20210101",
							"Fecha_Hasta":"20211231",
							"Id_Centro_Costo":"2",
							"Id_Alias_Cta_Cont":"0",
							"Id_Plan_Cta":"1",
							"Id_Unid_Negocio":"",
							"SoloResultado":"0",
							"Flag_Filtrar_CC":"0"
							}'


EXEC CPJ_BalanceCC_Pagos_Rpt '{
							"ModoDebug":"1",
							"Id_Usuario":"-1",
							"Tipo_Reporte":"AGRUP",
		                 	"Fecha_Desde":"20210401",
		                 	"Fecha_Hasta":"20210430",
							"Id_Centro_Costo":"ADM01",
							"Id_Alias_Cta_Cont":"0",
							"Id_Plan_Cta":"16",
							"Id_Unid_Negocio":"",
							"SoloResultado":"1",
							"Flag_Filtrar_CC":"1"
							}'


*/
GO



CREATE PROCEDURE [dbo].[CPJ_Produc_Cont_Generar]		@pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*Variables recibidas por par├ƒmetro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Usuario			INT
DECLARE @pId_Contrato			INT
DECLARE @pId_Trans				INT
DECLARE @pTipo					CHAR(3)
DECLARE @pValor					VARCHAR(8000)
DECLARE @pTar_Nro				VARCHAR(50)
DECLARE @pId_Tarjeta			VARCHAR(10)
DECLARE @pObservacion			VARCHAR(200)									

SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Usuario			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), 0)
SET @pId_Trans				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pTipo					= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Tipo')), '')
SET @pValor					= ISNULL(CONVERT(VARCHAR(8000), dbo.CF_JSON_VALUE(@pJson,'Valor')), '')
SET @pTar_Nro				= ISNULL(CONVERT(VARCHAR(50), dbo.CF_JSON_VALUE(@pJson,'Tar_Nro')), '')
SET @pId_Tarjeta			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Tarjeta')), '')
SET @pObservacion			= ISNULL(CONVERT(VARCHAR(200), dbo.CF_JSON_VALUE(@pJson,'Observacion')), '')																								

-- TC.20260313 - Encripta tarjeta
IF(ISNUMERIC(@pTar_Nro) = 1)
BEGIN
	SET @pTar_Nro = dbo.CF_Cotiza(@pTar_Nro)
END

--'' SOLO PRODUCTO   'PSH' - Producto sala horario 'PH'- Producto Horario
/*FIN Variables recibidas por par├ƒmetro a traves del JSON*/

/*Variables Locales*/
DECLARE @Id_Producto VARCHAR(14),
		@Fecha_QA DATETIME,
		@Fecha_Venc DATETIME,
		@Id_Cliente INT,
		@Existe_Cotrato INT,
		@Id_Tipo_Con_Web_Auto INT,
		@Descripcion_CT VARCHAR(200),
		@Id_Tipo_Cbte_Ri CHAR(4),
		@Id_Tipo_Cbte CHAR(4),
		@Id_Iva CHAR(3),
		@Id_Lista_Precio SMALLINT
						   

/*FIN Variables Locales*/

/*Variable de Retorno del Stored*/
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
DECLARE @Result_Stored_Invocado				INT
/*FIN Variable de Retorono del Stored*/

BEGIN TRY
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Produc_Cont_Generar'
		PRINT 'Par├ƒmetros: '+ @pJson  
	END
	
	/*===================================================================*/	
	
	IF @pId_Trans <> 0
	BEGIN
	--Recorro todos los productos		
	DECLARE cur_Produc_Cont_Generar CURSOR FOR 	
			SELECT ISNULL(I.Id_Cliente,C.Id_Cliente),I.Id_Producto,I.Fecha_QA,I.Fecha_Venc,P.Id_Tipo_Con_Web_Auto,CT.Descripcion,CT.Id_Tipo_Cbte_Ri,CT.Id_Tipo_Cbte,E.Id_Iva,PF.Id_Lista_Precio_Web
		FROM Cbtes_Items I, Cbtes C, Cbtes_Tipos T , Productos P ,Contratos_Tipos CT, Clientes E, Prod_Familias PF
		WHERE I.Id_trans = C.Id_Trans 
		AND C.Id_Trans = @pId_Trans 
		AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
		AND P.Id_Producto = I.Id_Producto
		AND P.Id_Familia=PF.Id_Familia						
		AND T.Compromete_Factura = 1
		AND C.Id_Estado_Cbte NOT IN (0,3)
		AND ISNULL(P.Id_Tipo_Con_Web_Auto,0) <> 0
		AND CT.Id_Tipo_Con = Id_Tipo_Con_Web_Auto
		AND E.Id_Cliente = ISNULL(I.Id_Cliente,C.Id_Cliente)

	OPEN cur_Produc_Cont_Generar
	FETCH NEXT FROM cur_Produc_Cont_Generar INTO @Id_Cliente,@Id_Producto,@Fecha_QA,@Fecha_Venc,@Id_Tipo_Con_Web_Auto,@Descripcion_CT,@Id_Tipo_Cbte_Ri,@Id_Tipo_Cbte,@Id_Iva,@Id_Lista_Precio
	WHILE @@FETCH_STATUS = 0
	BEGIN
	    SET @Existe_Cotrato = 0
		IF(@pModoDebug = 1)
		BEGIN
			PRINT '@Id_Producto: ' + CONVERT(VARCHAR(14), @Id_Producto) + ' @Id_Cliente: ' + CONVERT(VARCHAR(14), @Id_Cliente) +
			      '@Fecha_QA: ' + CONVERT(VARCHAR(14), @Fecha_QA,112) + '@Fecha_Venc: ' + CONVERT(VARCHAR(14), @Fecha_Venc,112) 
		END

		

		-----Verifico si existe el contrato --------------------------------------------------------------
		SET @Fecha_QA = ISNULL(@Fecha_QA,GETDATE())		
		SET @Fecha_Venc = ISNULL(@Fecha_Venc,GETDATE())
		
		IF @Fecha_Venc IS NULL
			SELECT TOP 1 @Existe_Cotrato = C.Id_Contrato FROM Contratos C , Contratos_Prod P
				WHERE C.Id_Contrato=P.Id_Contrato
					AND C.Id_Cliente = @Id_Cliente
					AND C.Activo = 1
					AND C.Id_Tipo_Con=30
					AND C.Fecha_Desde <= @Fecha_QA
					AND C.Fecha_Hasta IS NULL
					AND P.Id_Producto=@Id_Producto
        ELSE 
			SELECT TOP 1 @Existe_Cotrato = C.Id_Contrato FROM Contratos C , Contratos_Prod P
				WHERE C.Id_Contrato=P.Id_Contrato
					AND C.Id_Cliente = @Id_Cliente
					AND C.Activo = 1
					AND C.Id_Tipo_Con=30
					AND C.Fecha_Desde <= @Fecha_QA
					AND C.Fecha_Hasta >= @Fecha_Venc
					AND P.Id_Producto=@Id_Producto
        ---------------------------------------------------------------------------------------------------------

		IF ISNULL(@Existe_Cotrato,0) = 0	 						
		BEGIN
		   -------verifico la condici├│n del iva para ver que tipo de cbte tiene que tomar --------------------------
		   IF dbo.CF_xParam('Iva_RI') = @Id_Tipo_Cbte_RI
			  SET @Id_Tipo_Cbte = @Id_Tipo_Cbte_RI
		   ---------------------------------------------------------------------------------------------------------


		   SELECT @Existe_Cotrato = MAX(C.Id_Contrato) FROM Contratos C
		   SET @Existe_Cotrato = ISNULL(@Existe_Cotrato,0) + 1
		   
		   INSERT INTO Contratos 
			   (Id_Contrato,		Id_Cliente,	Id_Tipo_Con,			Fecha_Alta,	Fecha_Desde, Fecha_Hasta,	Activo,	Id_Tipo_Cbte,	Descripcion,
			   Porc_Bonif,	Id_Lista_Precio,Id_Sucursal,Imp_Bonif,	Id_Grupo_Cont,	Id_SubGrupo_Cont, Observacion, Id_Tarjeta, Tar_Nro)
			   VALUES
			   (@Existe_Cotrato,	@Id_Cliente,@Id_Tipo_Con_Web_Auto,	GETDATE(),	@Fecha_QA,	@Fecha_Venc,	1,		@Id_Tipo_Cbte,LTRIM(RTRIM(@Descripcion_CT)) + ' (AUTO. WEB)',		
			   0,			@Id_Lista_Precio,				0,			0,			'',				'', @pObservacion, @pId_Tarjeta, @pTar_Nro)

			   UPDATE CBTES SET Id_Contrato=@Existe_Cotrato WHERE Id_Trans=@pId_Trans

		 IF(@pTipo='PSH')
		 BEGIN

			EXEC @Result_Stored_Invocado = dbo.CP_Contratos_Prod_PSH_Agregar @Existe_Cotrato, @Id_Producto, @pValor
			IF ISNULL(@Result_Stored_Invocado,0) <> 0 
			BEGIN
				/*El CP_Contratos_Prod_PSH_Agregar deberia devolver el SELECT con el error*/
				RETURN 
			END
		 END
		 ELSE
		 BEGIN

			INSERT INTO Contratos_Prod 
			   (Id_Contrato,		Item,	Id_Producto,	Precio,	Precio_Formula,	Cant_Cuotas,	
			   Observa_Fact,	Flag_Facturable,	Cantidad,	Cant_Includ, Flag_No_Bonificable,	Id_Prod_Familia_Sala)
			   VALUES
			   (@Existe_Cotrato,	1,		@Id_Producto,	0,		'',				0,				
			   '',					1,				1,			0,			0,						0)
			END
		END

		FETCH NEXT FROM cur_Produc_Cont_Generar INTO @Id_Cliente,@Id_Producto,@Fecha_QA,@Fecha_Venc,@Id_Tipo_Con_Web_Auto,@Descripcion_CT,@Id_Tipo_Cbte_Ri,@Id_Tipo_Cbte,@Id_Iva,@Id_Lista_Precio
	END
	CLOSE cur_Produc_Cont_Generar
	DEALLOCATE cur_Produc_Cont_Generar
	--FIN Recorro todos los productos



	END --IF @pId_Trans <> 0

	/*===================================================================*/	

	IF @pFlagUsarTrans <> 0 COMMIT

	SELECT	 0							AS ErrorNumber 
			,0							AS ErrorSeverity  
			,0							AS ErrorState 
			,0							AS ErrorProcedure  
			,0							AS ErrorLine		
			,@Existe_Cotrato							AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Produc_Cont_Generar'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  
	BEGIN
		ROLLBACK
	END

END CATCH

RETURN 0 

--Ejemplo de uso
--EXEC CPJ_Produc_Cont_Generar '{"FlagUsarTrans":"0", "ModoDebug":"1", "Id_Trans":"2"}'
GO


CREATE PROCEDURE [dbo].[CPJ_Produc_Precio] @pJson VARCHAR(8000)
AS
SET NOCOUNT ON

/*Variables recibidas por parámetro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Producto			VARCHAR(14)
DECLARE @pId_Cliente			INT
DECLARE @pFecha					DATETIME
DECLARE @pId_Contrato			INT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Producto				= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), '')
SET @pId_Cliente				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pFecha						= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha')), '19000101')
SET @pId_Contrato				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Contrato')), 0)
/*FIN Variables recibidas por parámetro a traves del JSON*/


/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
declare @JSON varchar(2000)
/*FIN Variable de Retorono del Stored*/


/*Variables Locales*/
DECLARE @Precio							DECIMAL(12,4)
DECLARE @Precio_Grav					DECIMAL(12,4)
DECLARE @Precio_Exen					DECIMAL(12,4)
DECLARE @Prioridad_Calculo				TINYINT

DECLARE @Id_Lista_Precio_Cliente		SMALLINT
DECLARE @Id_Lista_Precio_Espec_Cliente	INT
DECLARE @Id_Lista_Precio_Contrato		SMALLINT
DECLARE @Precio_Contrato				DECIMAL(12,4)
DECLARE @Precio_Producto				DECIMAL(12,4)
DECLARE @Flag_Precio_For				TINYINT
DECLARE @Flag_Existe_Prod_Cli_Precios	TINYINT
DECLARE @Id_IVA							CHAR(3)
DECLARE @Porc_IVA						DECIMAL(7,4)
/*FIN Variables Locales*/

BEGIN TRY
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Produc_Precio'
		PRINT 'Parámetros:'
		PRINT 'ModoDebug: ' + CONVERT(VARCHAR(10), @pModoDebug) + '. Id_Producto: ' + @pId_Producto + '. Id_Cliente: ' + CONVERT(VARCHAR(10), @pId_Cliente) + '. Id_Contrato: ' + CONVERT(VARCHAR(10), @pId_Contrato) + ' Fecha: ' + CONVERT(VARCHAR(10), @pFecha, 112)
	END

	/*=================================================================================*/
	/*
	 * PRIORIDADES:
	 * 
	 * 1) Digitado en Contrato
	 * 2) Formulado
	 * 3) Prod_Cli_Precios
	 * 4) Lista de Precios Contrato
	 * 5) Lista de Precios Especial Cliente
	 * 6) Lista de Precios "Comun" Cliente
	 * 7) Producto
	*/
	SET @Prioridad_Calculo = 0

	/*=================================================================================*/

	IF(@pId_Producto = '')
	BEGIN
		SET @Precio = 0
		RETURN @Precio
	END

	/*=================================================================================*/
	
	SELECT
	@Flag_Precio_For		= ISNULL(Flag_Precio_For, 0),
	@Precio_Producto		= ISNULL(Precio_Gravado, 0),
	@Id_IVA					= ISNULL(Id_IVA, '')
	FROM Productos
	WHERE
	Id_Producto = @pId_Producto


	SELECT
	@Id_Lista_Precio_Cliente		= ISNULL(Id_Lista_Precio, 0),
	@Id_Lista_Precio_Espec_Cliente	= ISNULL(Id_Precio_Especial, 0)
	FROM Clientes
	WHERE
	Id_Cliente = @pId_Cliente


	SELECT
	@Id_Lista_Precio_Contrato		= ISNULL(Id_Lista_Precio, 0)
	FROM Contratos
	WHERE
	Id_Contrato = @pId_Contrato

	SELECT
	@Porc_IVA						= ISNULL(Porc1, 0)
	FROM Productos_TasaIVA
	WHERE
	Id_IVA = @Id_IVA

	/*=================================================================================*/

	/*1) Precio Digitado en Contrato*/

	IF(@Prioridad_Calculo = 0 AND @pId_Contrato > 0)
	BEGIN
		SELECT
		@Precio_Contrato = Precio
		FROM Contratos_Prod
		WHERE
		Id_Contrato = @pId_Contrato
		AND Id_Producto = @pId_Producto		

		IF(@Precio_Contrato > 0)
		BEGIN
			SET @Precio = @Precio_Contrato

			SET @Prioridad_Calculo = 1
		END
	END

	/*=================================================================================*/

	/*2) Precio Formulado*/

	IF(@Prioridad_Calculo = 0 AND @Flag_Precio_For = 1)
	BEGIN

			
		SET @JSON =	'{' +
					dbo.CF_Json_ParsearVariable('Id_Producto', @pId_Producto, 'VARCHAR(14)') + ',' +
					dbo.CF_Json_ParsearVariable('Id_Cliente', @pId_Cliente, 'INT') + ',' +
					dbo.CF_Json_ParsearVariable('Fecha', @pFecha, 'DATETIME') + ',' +
					dbo.CF_Json_ParsearVariable('Id_Contrato', @pId_Contrato, 'INT') + 
					'}'
	    SET @Precio = (dbo.CFUJ_Produc_Precio(@JSON))
 	    
		SET @Prioridad_Calculo = 2
	END

	/*=================================================================================*/

	/*3) Precio Prod_Cli_Precios*/

	IF(@Prioridad_Calculo = 0 AND @pId_Cliente <> 0)
	BEGIN
		SET @Flag_Existe_Prod_Cli_Precios = ISNULL((SELECT MAX(1) FROM Prod_Cli_Precios WHERE Id_Producto = @pId_Producto AND Id_Cliente = @pId_Cliente), 0)

		IF(@Flag_Existe_Prod_Cli_Precios = 1)
		BEGIN
			SELECT 
			@Precio = ISNULL(Precio, 0)
			FROM Prod_Cli_Precios
			WHERE
			Id_Producto = @pId_Producto
			AND Id_Cliente = @pId_Cliente

			SET @Prioridad_Calculo = 3
		END
	END

	/*=================================================================================*/

	/*4) Precio Lista de Precios Contrato*/

	IF(@Prioridad_Calculo = 0 AND @Id_Lista_Precio_Contrato <> 0)
	BEGIN
		SET @Flag_Existe_Prod_Cli_Precios = ISNULL((SELECT MAX(1) FROM Prod_Listas_Precios_Items WHERE Id_Producto = @pId_Producto AND Id_Lista_Precio = @Id_Lista_Precio_Contrato), 0)

		IF(@Flag_Existe_Prod_Cli_Precios = 1)
		BEGIN
			SELECT 
			@Precio = ISNULL(Precio, 0)
			FROM Prod_Listas_Precios_Items
			WHERE
			Id_Producto = @pId_Producto
			AND Id_Lista_Precio = @Id_Lista_Precio_Contrato

			SET @Prioridad_Calculo = 4
		END
	END

	/*=================================================================================*/

	/*5) Precio Lista de Precios Especial Cliente*/

	IF(@Prioridad_Calculo = 0 AND @Id_Lista_Precio_Espec_Cliente <> 0)
	BEGIN
		SET @Flag_Existe_Prod_Cli_Precios = ISNULL((SELECT MAX(1) FROM Prod_Listas_Precios_Items WHERE Id_Producto = @pId_Producto AND Id_Lista_Precio = @Id_Lista_Precio_Espec_Cliente), 0)

		IF(@Flag_Existe_Prod_Cli_Precios = 1)
		BEGIN
			SELECT 
			@Precio = ISNULL(Precio, 0)
			FROM Prod_Listas_Precios_Items
			WHERE
			Id_Producto = @pId_Producto
			AND Id_Lista_Precio = @Id_Lista_Precio_Espec_Cliente

			SET @Prioridad_Calculo = 5
		END
	END

	/*=================================================================================*/

	/*6) Precio Lista de Precios "Comun" Cliente*/

	IF(@Prioridad_Calculo = 0 AND @Id_Lista_Precio_Cliente <> 0)
	BEGIN
		SET @Flag_Existe_Prod_Cli_Precios = ISNULL((SELECT MAX(1) FROM Prod_Listas_Precios_Items WHERE Id_Producto = @pId_Producto AND Id_Lista_Precio = @Id_Lista_Precio_Cliente), 0)

		IF(@Flag_Existe_Prod_Cli_Precios = 1)
		BEGIN
			SELECT 
			@Precio = ISNULL(Precio, 0)
			FROM Prod_Listas_Precios_Items
			WHERE
			Id_Producto = @pId_Producto
			AND Id_Lista_Precio = @Id_Lista_Precio_Cliente

			SET @Prioridad_Calculo = 6
		END
	END

	/*=================================================================================*/

	/*7) Precio Producto*/
	IF(@Prioridad_Calculo = 0)
	BEGIN
		SET @Precio = @Precio_Producto
		SET @Prioridad_Calculo = 7
	END
	
	/*=================================================================================*/
	
	IF(@Porc_IVA = 0)
	BEGIN
		SET @Precio_Grav = 0
		SET @Precio_Exen = @Precio
	END
	ELSE
	BEGIN
		SET @Precio_Grav = @Precio * (1 + (@Porc_IVA / 100))
		SET @Precio_Exen = 0
	END

	/*=================================================================================*/
	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Precio_Grav: ' + CONVERT(VARCHAR(10), @Precio_Grav) + '. @Precio_Exen: '+ CONVERT(VARCHAR(10), @Precio_Exen) + '. @Prioridad_Calculo: ' + CONVERT(VARCHAR(10), @Prioridad_Calculo)
	END

	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('Precio_Grav', @Precio_Grav, 'DECIMAL(12,2)') + ',' + 
								dbo.CF_Json_ParsearVariable('Precio_Exen', @Precio_Exen, 'DECIMAL(12,2)') + ',' + 
								dbo.CF_Json_ParsearVariable('Prioridad_Calculo', @Prioridad_Calculo, 'TINYINT') + 
								'}'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity
			,0				AS ErrorState
			,0				AS ErrorProcedure
			,0				AS ErrorLine
			,@rtaMsjStored	AS ErrorMessage

	/*===================================================================*/

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Produc_Precio'
	END

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0 
	BEGIN
		ROLLBACK
	END

	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CPJ_Productos_Cobros] @pJsonRecibido VARCHAR(8000)

AS 
SET NOCOUNT ON

/*Parametros*/
DECLARE		@pId_Usuario			INT,
			@pFlagUsarTrans			TINYINT,
			@pModoDebug				TINYINT,
			@pFechaDesde			DATETIME,
			@pFechaHasta			DATETIME,
			@pPeriodoDesde			DATETIME,
			@pPeriodoHasta			DATETIME,
		    @pFlag_Liquidacion		TINYINT,
		    @pId_Periodo_Caja		INT,
		    @pFlag_FPago			TINYINT,
		    @pTipo_Cob				CHAR(1),		-- vacio = todos  M = Manual L=Lote
			@pFormato				VARCHAR(3),     --D  Detallado   F Resumen por Familia     CF  Resumen por Cobrador Familia  CFM  Resumen por Cob,Familia,Mes  P Producto  T Tipo/Categoria    CTA  Por cuenta y CC
			@pFlag_Filtrar_Fam		TINYINT,
			@pFlag_Inc_Fact_Periodo	TINYINT,		--Incluye lo facturado en el periodo y no este cobrado solo para formato  D
			@pFlag_Filtrar_Prod		TINYINT,
			@pFlag_No_Rec_Aplic		TINYINT,		-- Se agrega flag para validar si no se requiere Recibos de Aplicacion- 2021/08/12  0=Con Recibos de Aplica, 1= Sin Recibos de Aplica
			@pFlag_Filtrar_CC		TINYINT,
			@pId_Centro_Costo		VARCHAR(10),
            @pFlag_Filtrar_Caja		TINYINT,
			@pRegenerar_Archivo		CHAR(1),
			@pId_Familia            INT,
			@pId_Producto           VARCHAR(14),
			@pId_Cliente            INT,
			@pRegenarUltDias		INT

			


SET @pId_Usuario				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Usuario')), 0)
SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)

SET @pFechaDesde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaDesde')),GETDATE())
SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())

SET @pRegenarUltDias			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'RegenarUltDias')),0)
IF @pRegenarUltDias > 0 
BEGIN
	SET @pFechaDesde				= DATEADD(DAY, @pRegenarUltDias * -1 ,CONVERT(DATE,GETDATE()))
	SET @pFechaHasta				= GETDATE()
	PRINT @pFechaDesde
	PRINT @pFechaHasta
END



SET @pPeriodoDesde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'PeriodoDesde')),'')
SET @pPeriodoHasta				= CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'PeriodoHasta'))
 IF @pPeriodoHasta IS NULL
    SET @pPeriodoHasta = (SELECT MAX(FECHA_QA) FROM CBTES_ITEMS)

SET	@pFlag_Liquidacion			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Liquidacion')), 0)
SET	@pId_Periodo_Caja			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Periodo_Caja')), 0)
SET	@pFlag_FPago				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_FPago')), 0)
SET	@pTipo_Cob					= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Tipo_Cob')), '')
SET	@pFormato					= ISNULL(CONVERT(VARCHAR(3), dbo.CF_JSON_VALUE(@pJsonRecibido,'Formato')), 0)
SET	@pFlag_Filtrar_Fam			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Filtrar_Fam')), 0)
SET	@pFlag_Inc_Fact_Periodo		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Inc_Fact_Periodo')), 0)
SET	@pFlag_Filtrar_Prod			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Filtrar_Prod')), 0)
SET @pFlag_No_Rec_Aplic			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_No_Rec_Aplic')), 0)
SET @pFlag_Filtrar_CC			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Filtrar_CC')), 0)
SET @pId_Centro_Costo	        = ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Centro_Costo')), '')
SET @pFlag_Filtrar_Caja			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Filtrar_Caja')), 0)
SET @pRegenerar_Archivo			= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Regenerar_Archivo')),'S')
SET	@pId_Familia 		    	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Familia')), 0)
SET	@pId_Producto	            = ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Producto')), '')
SET	@pId_Cliente 		    	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')), 0)
            

  CREATE TABLE #Trans (Id_Trans INT)
  CREATE INDEX IX_Trans ON #Trans (Id_Trans)


  CREATE TABLE #Coef_Pagos (Id_Trans Int
	,Imp_Total_Rec [decimal](20, 2)
	,Imp_Valores [decimal](20, 2)
	,Imp_PAGOS_APLI [decimal](20, 2)
	,Imp_Efe [decimal](20, 2)
	,Imp_Tar [decimal](20, 2)
	,Imp_CH3 [decimal](20, 2) 
	,Imp_CHP [decimal](20, 2)
	,Imp_DB [decimal](20, 2)
	,Imp_Fin [decimal](20, 2)
	,Imp_Aju [decimal](20, 2)
	,Coef_PAGOS_APLI decimal(14,5)
	,Coef_Efe decimal(14,5)
	,Coef_Tar decimal(14,5)
	,Coef_CH3 decimal(14,5) 
	,Coef_CHP decimal(14,5)
	,Coef_DB decimal(14,5)
	,Coef_Fin decimal(14,5)
	,Coef_Aju decimal(14,5)
	)

  CREATE INDEX IX_Coef_Pagos ON #Coef_Pagos (Id_Trans)

  DECLARE @Id_Producto 				VARCHAR(14)
		  ,@Id_Proveedor 			INT
		  ,@Razon_Social		 	VARCHAR(100)
		  ,@Cuit 					VARCHAR(13)
		  ,@Id_Iva 					CHAR(3)
		  ,@Id_Alias_Cta_Cont 		INT
		  ,@Id_Cta_Contable_H 		INT
		  ,@Porc_Comision_Prov 		DECIMAL(7,2) 
		  ,@Importe 				[decimal](20, 2)
		  ,@Importe_Credito 		[decimal](20, 2)
		  ,@Id_Tipo_Cbte 			CHAR(4) 
		  ,@Fecha 					DATETIME
		  ,@Imp_Prod_SIva  			[decimal](20, 2)
		  ,@Id_Trans 				INT
		  ,@Id_Cliente_Externo 		VARCHAR(14)
		  ,@Id_Cta_Banco 			INT
		  ,@Id_Cliente 				INT
		  ,@Total     				DECIMAL(20,2)
		  ,@Existe_Tag_Prod 		INT
		  ,@Existe_Tag_Fam 			INT
		  ,@Existe_Tag_Caja  		INT
		  ,@e_Tag_Prod				SMALLINT
		  ,@e_Tag_Prod_Familias		SMALLINT
		  ,@e_Tag_Prod_Cajas		SMALLINT

   DECLARE @Id_Trans_Rec INT 
		  ,@Id_Tipo_Val CHAR(3) 
		  ,@IMPORTE_Val [decimal](20, 2)
		  ,@EXISTE SMALLINT
		  ,@Imp_Total_Rec [decimal](20, 2)
		  ,@Tipo_val char(3)
		  ,@coef DECIMAL(10,5)
		  ,@coef_Apl DECIMAL(10,5)
		  ,@coef_Val DECIMAL(10,5)
		  ,@UltError SMALLINT

  SET @Fecha = (SELECT CAST(GETDATE() AS DATE))

  DECLARE @Sql		    VARCHAR(MAX)
  DECLARE @SqlSaldo	    VARCHAR(MAX)
  DECLARE @SqlSelect	VARCHAR(MAX)
  DECLARE @SqlInto	    VARCHAR(MAX)
  DECLARE @SqlFrom	    VARCHAR(MAX)
  DECLARE @SqlWhere  	VARCHAR(MAX)
  DECLARE @SqlGroup	    VARCHAR(MAX)

  SET @e_Tag_Prod = 90
  SET @Existe_Tag_Prod = 0 
  
  SET @e_Tag_Prod_Familias = 80
  SET @Existe_Tag_Fam = 0 
 
  SET @e_Tag_Prod_Cajas = 250
  SET @Existe_Tag_Caja = 0

  If @pId_Cliente > 0
     Set @pFormato = 'D'

  IF @pRegenerar_Archivo = 'S'
     BEGIN
        DELETE RPT_Productos_Cob_Detalle where Fecha_Rec >= @pFechaDesde  and Fecha_Rec < dateadd(dd,1,@pFechaHasta)
        SELECT * INTO #REPORTE FROM RPT_Productos_Cob_Detalle where 0=1
		DELETE #REPORTE

		/************************************************************* Calculo el importe positivo de lo aplicado del recibo ***************************************************************************************/
		IF @pModoDebug > 0   --1
		BEGIN
			PRINT @pModoDebug
		END

		SELECT A.ID_TRANS_D,SUM(A.IMPORTE) AS IMPORTE_REC
		   INTO #Tot_Recibos
		   FROM  CBTES C
		    JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  AND T.Compromete_Recibos IN (1,-1)
			JOIN CBTES_APLICA A ON  A.ID_TRANS_D = C.ID_TRANS
		   WHERE C.ID_ESTADO_CBTE not in (0,3)
				 AND C.FECHA >= @pFechaDesde 
				 AND C.FECHA < dateadd(dd,1,@pFechaHasta)
				 AND A.IMPORTE > 0
				 GROUP BY A.ID_TRANS_D 

        CREATE INDEX IX_Tot_Recibos ON #Tot_Recibos (ID_TRANS_D)

		INSERT INTO #Tot_Recibos
			SELECT C.ID_TRANS,C.Imp_Total * T.Compromete_Factura
			   FROM  CBTES C
			     JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
				                    AND T.Compromete_Factura IN (1,-1) AND T.Flag_Items_Req <> 0
			   WHERE C.Id_Cond_Pago = 1
					 AND C.ID_ESTADO_CBTE not in (0,3)
					 AND C.FECHA >= @pFechaDesde 
					 AND C.FECHA < DATEADD(dd,1,@pFechaHasta)

		/************************************************************* Calculo el total de los valores del recibo ***************************************************************************************/

		IF @pModoDebug > 0   --2
		BEGIN
			SET @pModoDebug += 1
			PRINT @pModoDebug
		END

		SELECT C.ID_TRANS, C.FECHA, TR.IMPORTE_REC AS IMP_TOTAL,V.ID_TIPO_VAL,V.IMPORTE,CAST(V.Importe /TR.IMPORTE_REC AS DECIMAL(16,8)) AS COEF,V.Tarjeta_Cant_Cuotas
		   INTO #Valores_Rec
		   FROM CBTES C
		   JOIN CBTES_TIPOS T ON  C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  AND ((T.COMPROMETE_FACTURA  IN (1,-1) AND C.Id_Cond_Pago = 1) OR T.Compromete_Recibos IN (1,-1))
		   JOIN #Tot_Recibos TR ON C.ID_TRANS = TR.ID_TRANS_D
           JOIN VALORES_MOV M ON C.ID_TRANS = M.ID_TRANS AND M.Renglon_Nro = 1
 		   JOIN VALORES V ON  M.ID_VALOR = V.ID_VALOR
		   WHERE C.ID_ESTADO_CBTE NOT IN (0,3)
				 AND C.FECHA >= @pFechaDesde 
				 AND C.FECHA < dateadd(dd,1,@pFechaHasta)

        CREATE INDEX IX_Valores_Rec ON #Valores_Rec (ID_TRANS)

		UPDATE #Valores_Rec SET Importe = Importe * -1, Coef = Coef * -1 WHERE IMP_TOTAL < 0 


		/************************************************************* Calculo los pagos a cuenta ***************************************************************************************/
				 
		IF @pModoDebug > 0  --3
		BEGIN
			SET @pModoDebug += 1
			PRINT @pModoDebug
		END
		 
		SELECT C.ID_TRANS,C.FECHA,TR.IMPORTE_REC AS IMP_TOTAL,'ACUENTA' AS ID_PRODUCTO ,A.IMPORTE AS IMPORTE, CAST(A.IMPORTE/TR.IMPORTE_REC AS DECIMAL(16,8)) AS COEF,C.ID_CLIENTE 
		   INTO #ACuenta
		   FROM CBTES C
		   JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte AND T.Compromete_Recibos IN (1,-1)
		   JOIN CBTES_APLICA A ON A.ID_TRANS_D = C.ID_TRANS  AND A.Id_Trans = 0 AND A.IMPORTE <> 0
		   JOIN #Tot_Recibos TR ON C.ID_TRANS = TR.ID_TRANS_D
			 WHERE C.ID_ESTADO_CBTE NOT IN (0,3)
				 AND C.FECHA >= @pFechaDesde 
				 AND C.FECHA < dateadd(dd,1,@pFechaHasta)

        CREATE INDEX IX_ACuenta ON #ACuenta (ID_TRANS)

		DECLARE @Pagos_a_Cuenta [decimal](20, 2)
		SET @Pagos_a_Cuenta = ISNULL((select sum(IMPORTE) FROM #ACuenta WHERE IMPORTE > 0 ),0)


		/************************************************************* Calculo las aplicaciones  ***************************************************************************************/

		IF @pModoDebug > 0  --4
		BEGIN
			SET @pModoDebug += 1
			PRINT @pModoDebug
		END

		SELECT C.ID_TRANS,C.FECHA,TR.IMPORTE_REC AS IMP_TOTAL,'APL' AS ID_TIPO_VAL,SUM(A.IMPORTE)*-1 AS IMPORTE, CONVERT(DECIMAL(16,8),0) AS COEF, 0 AS 'Tarjeta_Cant_Cuotas'
		   INTO #Recibos_Aplic
		   FROM CBTES C
		    JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte AND T.Compromete_Recibos IN (1,-1)
			JOIN #Tot_Recibos TR ON C.ID_TRANS = TR.ID_TRANS_D
		    JOIN CBTES_APLICA A ON A.ID_TRANS_D = C.ID_TRANS AND A.IMPORTE <> 0
			JOIN CBTES REC ON REC.Id_Trans = A.ID_TRANS
		    JOIN CBTES_TIPOS TNC ON  REC.Id_Tipo_Cbte = TNC.Id_Tipo_Cbte AND TNC.COMPROMETE_RECIBOS = 1
		   WHERE C.ID_ESTADO_CBTE <> 3
				 AND C.FECHA >= @pFechaDesde 
				 AND C.FECHA < dateadd(dd,1,@pFechaHasta)
		   GROUP BY C.ID_TRANS,C.FECHA,TR.IMPORTE_REC

        CREATE INDEX IX_Recibos_Aplic ON #Recibos_Aplic (ID_TRANS)
		/************************************************************* Notas de Credito tomadas en los recibos  ***************************************************************************************/

 		IF @pModoDebug > 0  --5
		BEGIN
			SET @pModoDebug += 1
			PRINT @pModoDebug
		END

		SELECT C.ID_TRANS, C.FECHA,R.IMPORTE_REC AS IMP_TOTAL,'N/C' AS ID_TIPO_VAL,SUM(A.IMPORTE)*-1 AS IMPORTE, CAST(0 AS DECIMAL(16,8)) AS COEF, 0 AS 'Tarjeta_Cant_Cuotas' 
		   INTO #NCREDITO
		   FROM CBTES C
		     JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte AND T.Compromete_Recibos IN (1,-1)
		     JOIN CBTES_APLICA A ON A.ID_TRANS_D = C.ID_TRANS AND A.IMPORTE <> 0
			 JOIN #Tot_Recibos R ON A.ID_TRANS_D = R.ID_TRANS_D
		     JOIN CBTES NC ON  A.Id_Trans = NC.ID_TRANS
		     JOIN CBTES_TIPOS TNC ON NC.Id_Tipo_Cbte = TNC.Id_Tipo_Cbte  AND TNC.COMPROMETE_FACTURA = -1
		   WHERE C.ID_ESTADO_CBTE <> 3
				 AND C.FECHA >= @pFechaDesde 
				 AND C.FECHA < dateadd(dd,1,@pFechaHasta)
				 GROUP BY C.ID_TRANS, C.FECHA ,R.IMPORTE_REC



		/************************************************************* Calculo las retenciones  ***************************************************************************************/

		SELECT R.Id_Trans,SUM(R.IMPORTE) AS IMPORTE_RETEN
		   INTO #TOT_RETEN 
		   FROM  CBTES_RETEN R, #Tot_Recibos A
		   WHERE R.Id_Trans = A.Id_Trans_D
				 AND R.IMPORTE > 0
				 GROUP BY R.Id_Trans

        CREATE INDEX IX_TOT_RETEN ON #TOT_RETEN (ID_TRANS)

		SELECT C.ID_TRANS, C.FECHA, R.IMPORTE_REC AS IMP_TOTAL,'RET' AS ID_TIPO_VAL,T.IMPORTE_RETEN AS IMPORTE
		   , CAST(0 AS DECIMAL(16,8)) AS COEF 
		   , 0 AS 'Tarjeta_Cant_Cuotas'
		   INTO #RETEN
		   FROM CBTES C, #TOT_RETEN T, #Tot_Recibos R
		   WHERE C.ID_TRANS  = T.ID_TRANS
				 AND R.ID_TRANS_D = C.ID_TRANS 
				 AND T.IMPORTE_RETEN <> 0


		/*************************************************************  ***************************************************************************************/

  		IF @pModoDebug > 0  --6
		BEGIN
			SET @pModoDebug += 1
			PRINT @pModoDebug
		END
 
		INSERT INTO #Valores_Rec
				SELECT * FROM #NCREDITO
		INSERT INTO #Valores_Rec
				SELECT * FROM #Recibos_Aplic
		INSERT INTO #Valores_Rec
				SELECT * FROM #RETEN

		UPDATE #Valores_Rec SET COEF = IMPORTE/IMP_TOTAL  FROM #Valores_Rec  

		IF @pModoDebug > 0  --7
		BEGIN
			SET @pModoDebug += 1
			PRINT 'Canceladas'
			PRINT @pModoDebug 
		END

		/*************************************************************  Facturas Canceladas ***************************************************************************************/

		
		SELECT C.ID_TRANS
				,R.IMPORTE_REC AS IMP_TOTAL
				,F.ID_TRANS AS ID_TRANS_FAC
				,A.IMPORTE  
				,CONVERT(DECIMAL(16,8),((abs(A.IMPORTE)/R.IMPORTE_REC)) ) AS COEF
				,C.Porc_Bonificacion
				,F.Imp_Total AS Tot_Fac
				,CASE ISNULL( F.Imp_Total,0) WHEN 0 THEN 0 
					ELSE CONVERT(DECIMAL(20,8),A.Importe / F.Imp_Total) 
				 END
					AS Coef_Fac_Aplic
		 INTO #Facturas
			FROM CBTES C
			JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte AND T.Compromete_Recibos IN (1,-1)
			JOIN CBTES_APLICA A ON A.ID_TRANS_D = C.ID_TRANS AND A.IMPORTE <> 0
			JOIN #Tot_Recibos R ON A.ID_TRANS_D = R.ID_TRANS_D AND R.IMPORTE_REC <> 0
			JOIN CBTES F ON A.Id_Trans = F.ID_TRANS
			JOIN CBTES_TIPOS TF ON F.Id_Tipo_Cbte = TF.Id_Tipo_Cbte	AND TF.COMPROMETE_FACTURA = 1
			WHERE C.ID_ESTADO_CBTE <> 3
					AND C.FECHA >= @pFechaDesde 
					AND C.FECHA < DATEADD(dd,1,@pFechaHasta)

         CREATE INDEX IX_#Facturas ON #Facturas (ID_TRANS)

		--	     SELECT * FROM Cbtes_Aplica WHERE Id_Trans_D = 13407289
			IF @pModoDebug > 0  --8
			BEGIN
				SET @pModoDebug += 1
				PRINT @pModoDebug 
			END

		/************************************************************* Agrego las facturas de contado  ***************************************************************************************/

		INSERT INTO #Facturas
			SELECT C.ID_TRANS
					,C.IMP_TOTAL
					,C.ID_TRANS AS ID_TRANS_FAC
					,C.IMP_TOTAL AS IMPORTE  
					,CONVERT(DECIMAL(16,8), 1 ) AS COEF
					,C.Porc_Bonificacion
					,C.Imp_Total AS Tot_Fac
					,CONVERT(DECIMAL(20,8),1) AS Coef_Fac_Aplic
				FROM CBTES C
				    JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte AND T.Compromete_Factura IN (1,-1) AND T.Flag_Items_Req <> 0 
			      WHERE C.ID_COND_PAGO = 1
						AND C.ID_ESTADO_CBTE NOT IN (0,3)
						AND C.FECHA >= @pFechaDesde 
						AND C.FECHA < DATEADD(dd,1,@pFechaHasta)


		/************************************************************* Items de Facturas Canceladas  ***************************************************************************************/


		SELECT I.ID_TRANS as Id_TRans_Fac,I.ITEM,I.ID_CLIENTE,I.ID_PRODUCTO,Descripcion_producto,I.Cantidad,
					CONVERT(DECIMAL(20,2), (I.Imp_Final * (1-F.Porc_Bonificacion/100) ) ) * T.Compromete_Factura AS IMP_FINAL_PRODUCTO 
					,F.COEF AS COEF
					,CONVERT(DECIMAL(20,8), (((i.Imp_Final * f.Coef_Fac_Aplic) / f.Importe ) ) )AS  Coef_Items
					,CONVERT(DECIMAL(20,4), ((R.IMPORTE_REC* (1-F.Porc_Bonificacion/100) * CONVERT(DECIMAL(20,8),((i.Imp_Final * f.Coef_Fac_Aplic) /f.Importe )) * F.COEF ))) AS Imp_Cobrado
					,F.Id_Trans
					,F.Importe * T.Compromete_Factura AS iMPORTE
			INTO #items
				FROM CBTES_ITEMS I
				 JOIN #Facturas F ON I.ID_TRANS = F.ID_TRANS_FAC
				 JOIN #Tot_Recibos R ON F.ID_TRANS = R.ID_TRANS_d
				 JOIN Cbtes C ON F.ID_TRANS_FAC = C.Id_Trans
				 JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
				WHERE I.Imp_Final <> 0

       CREATE INDEX IX_#items ON #items (ID_TRANS)

       UPDATE #items SET Imp_Cobrado = IMP_FINAL_PRODUCTO WHERE ABS(IMP_FINAL_PRODUCTO - Imp_Cobrado) < 1 

    --   select * from #items where id_trans in (1552338,
				--1552344,
				--1552351)

	   /************************************************************* PAgos Cuenta ***************************************************************************************/


		INSERT INTO  #items SELECT 0,0,A.ID_CLIENTE,'ACUENTA','PAGO A CUENTA',0,A.IMPORTE,A.COEF,A.COEF,A.IMPORTE,A.ID_TRANS,A.IMPORTE
				 FROM #ACuenta A

		IF @pModoDebug > 0 --9
		BEGIN
			SET @pModoDebug += 1
			PRINT @pModoDebug
		END

		   SELECT I.ID_TRANS,I.ITEM,i.ID_CLIENTE,i.ID_PRODUCTO,i.Descripcion_producto,I.Cantidad AS Cantidad_Prod,i.IMP_FINAL_PRODUCTO ,
				cast(i.coef_Items * 100 as DECIMAL(20,5)) AS Porc_Cobr_Fact,
				i.Imp_Cobrado,
				R.Id_Tipo_Val,
				cast(R.coef * 100 as DECIMAL(20,5)) AS Porc_TVal,
				CAST(i.Imp_Cobrado*r.coef AS DECIMAL(20,2)) AS IMP_VALOR
				,I.Id_Trans_Fac
				,R.FECHA 
				,R.IMP_TOTAL
				,i.coef 
				,I.Importe
				,R.Tarjeta_Cant_Cuotas
				INTO #RESUMEN 
				FROM #items i, #Valores_Rec R
				WHERE I.ID_TRANS = r.ID_TRANS
				AND I.Imp_Cobrado <> 0
				ORDER BY I.ID_TRANS 

          CREATE INDEX IX_RESUMEN ON #RESUMEN (ID_TRANS)
		/*************************************************************  Detalle ***************************************************************************************/


		IF @pModoDebug > 0  --10
		BEGIN
			SET @pModoDebug += 1
			PRINT @pModoDebug
		END
		
		  INSERT INTO #REPORTE
				 SELECT  cast((i.Imp_Gravado * CF.Cotizacion) as [decimal](20, 2)) * TF.Compromete_Factura as Imp_Gravado_Item				--1
					,cast((i.Imp_Final * CF.Cotizacion) as [decimal](20, 2)) * TF.Compromete_Factura as Imp_Final_Item								--2
					,R.ID_TRANS_FAC as Id_Trans_Fac																		--3
					,cast((Cf.Imp_Gravado + CF.Imp_Gravado2 + Cf.Imp_Gravado3 + Cf.Imp_Exento) * CF.Cotizacion as [decimal](20, 2)) * TF.Compromete_Factura as Importe_Fac		--4
					,cast(Cf.Imp_total * CF.Cotizacion  as [decimal](20, 2)) * TF.Compromete_Factura as Imp_total_Fac							    --5
					,R.Id_trans as Id_Trans_Rec																			--6
					,cast(R.IMP_VALOR  as [decimal](20, 2))  as Importe_Aplicado											--7
					,i.Fecha_QA																							--8
					,i.Fecha_Venc																						--9
					,C.Id_cliente																						--10
					,C.Nombre_Fantasia																					--11
					,C.Id_Cliente_Externo																				--12
					,C.Razon_Social																						--13
					,C.Id_Tipo_Cli																						--14
					,dbo.CF_Cbte_Descrip(R.ID_TRANS_FAC) as Desc_Factura												--15
					,CR.Fecha																							--16
					,dbo.CF_Cbte_Descrip(R.ID_TRANS) as Desc_Recibo														--17
					,R.Fecha as Fecha_Rec																				--18
					,cast(R.IMP_TOTAL as [decimal](20, 2)) as Imp_Total_Rec												--19
					,CR.Id_Estado_Cbte																					--20
					,CR.Cotizacion as Cotizacion_Rec																	--21
					,CF.Cotizacion as Cotizacion_Fac																	--22
     				,CF.Porc_Bonificacion																				--23
					,CR.Id_Cobrador																						--24
					,R.Id_Producto																						--25
					,P.Descripcion_Detallada																			--26
					,CASE ISNULL(P.Id_Familia,0)	WHEN 0 THEN 65000 ELSE P.Id_Familia END																					--27
					,ISNULL(FP.Descripcion,'Pagos a Cuenta') as Descripcion_Familia										--28
 					,R.COEF * 100 as porc_aplicado																		--29
					,CAST(IMP_VALOR AS DECIMAL(20,2))  as Imp_Prod_CIva													--30
					,CAST(IMP_VALOR AS DECIMAL(20,2))  AS Imp_Prod_SIva												    --31
					,VE.DESCRIPCION AS Nombre_Cobrador																	--32
					,dbo.SF_Cli_Categ_Mes(i.Id_cliente, isnull(i.Fecha_QA,CR.Fecha)) as Id_Tipo_Cli_Ori					--33
					,CT.Descripcion AS Descripcion_Tipo_Cli																--34
					,isnull(c.id_cliente_ref,0) as id_cliente_ref														--35
					,cast(0 as [decimal](20, 2)) AS EFECTIVO																--36
					,cast(0 as [decimal](20, 2)) AS TARJETA																--37
					,cast(0 as [decimal](20, 2)) AS CHEQ_TER																--38
					,cast(0 as [decimal](20, 2)) AS CHEQ_PROP																--39
					,cast(0 as [decimal](20, 2)) AS DEBITO																	--40
					,cast(0 as [decimal](20, 2)) AS FINANC																	--41
					,cast(0 as [decimal](20, 2)) AS OTROS																	--42
					,cast(0 as [decimal](20, 2)) AS APLIC																	--43
					,CAST(IMP_VALOR AS DECIMAL(12,2)) AS Total_Pagos													--44
					,cast(0 as [decimal](20, 2)) AS Dif																	--45
					,i.Item as Item_Fac																					--46
 					,cast(R.coef as decimal(16,8)) AS Coef_Pago															--47 
					,ISNULL(CF.Id_Cond_Pago, 0) AS Id_Cond_Pago															--48  
					,ISNULL(CCP.Descripcion, '') AS Cond_Pago															--49  
					,cast(CF.Imp_Percep as [decimal](20, 2)) AS Imp_Total_Percep_Reten_Fac									--50  
					,cast(CR.Imp_Percep as [decimal](20, 2)) AS Imp_Total_Percep_Reten_Rec									--51  
					,CLFC.Nombre_Fantasia		AS FC_CL_Nombre_Fantasia												--52 
					,CLFC.Id_Cliente_Externo	AS FC_CL_Id_Cliente_Externo												--53 
					,CLFC.Razon_Social			AS FC_CL_Razon_Social													--54 
					,CLFC.Id_Tipo_Cli			AS FC_CL_Id_Tipo_Cli													--55 
					,CR.Id_Cobrador				AS CL_Id_Cobrador														--56 
					,CP.Id_Caja					AS Id_Caja																--57 
					,cast(I.Bonif as [decimal](20, 2)) AS Porc_Bonif_Item	                                            --58 
					,CASE I.Bonif WHEN 100 THEN 0
					         ELSE  												 
					             cast(((100 * I.Imp_Final) / (100-I.Bonif) * (R.Porc_Tval/100 )) as [decimal](20, 2)) * TF.Compromete_Factura 
					 END	AS Imp_Final_Item_Sin_Desc 	--59 
					,cast(((100 * I.Imp_Final) * (I.Bonif/100) * (R.Porc_Tval/100)) as [decimal](20, 2)) * TF.Compromete_Factura AS Imp_Bonif_Item				--60 
					,cast(R.Cantidad_Prod as [decimal](20, 2)) AS Cantidad_Prod															--61
					,P.Id_Alias_Cta_Cont AS Alias																		--62
					,P.Id_Centro_Costo   																		     	--63 
					,CONVERT(VARCHAR(20), TRR.Fecha_Mov, 120) AS Fac_Fecha_Mov											--64 
					,CONVERT(VARCHAR(20), TRF.Fecha_Mov, 120) AS Rec_Fecha_Mov                                          --65 
    				,cast(R.Importe as [decimal](20, 2)) As Importe                                                        --66 
 					,CM.Id_Periodo_Caja      AS Id_Periodo_Caja                                                         --67 
					,CR.id_tipo_Cbte         AS Id_Tipo_Cbte_Fac                                                        --68 
					,TF.Descripcion          AS Descripcion_Fac --69
					,I.Imp_Final * TF.Compromete_Factura --70
					,R.Porc_Cobr_Fact/100    AS COEF_ITEM      --71
					,R.Id_Tipo_Val  --72
					, (R.Porc_Tval/100) AS COEF_VAL  --73
					,cast(0 as [decimal](20, 2)) AS Ajustes	--74  												 
					,cast(0 as [decimal](20, 2)) AS Acuenta    --75
					,I.ITEM  --76
					,R.Tarjeta_Cant_Cuotas --77
			  FROM #RESUMEN R 
					LEFT JOIN Cbtes CR  ON R.ID_TRANS = CR.ID_TRANS                         ---ojjo
					LEFT JOIN Cbtes_Tipos TF ON CR.Id_Tipo_Cbte = TF.Id_Tipo_Cbte
					LEFT JOIN Transacciones TRF ON TRF.ID_TRANS = CR.ID_TRANS
					LEFT JOIN Clientes CLFC ON CR.Id_Cliente = CLFC.Id_Cliente
					LEFT JOIN Clientes_Tipos CT ON CLFC.Id_Tipo_Cli = CT.Id_Tipo_Cli
					LEFT JOIN Vendedores VE ON CR.Id_Cobrador = VE.Id_Vendedor
					LEFT JOIN CBTES_ITEMS I ON I.ID_TRANS = R.ID_TRANS_FAC AND I.ITEM = R.ITEM
					LEFT JOIN PRODUCTOS P ON R.ID_PRODUCTO  = P.ID_PRODUCTO
					LEFT JOIN PROD_FAMILIAS FP ON P.ID_FAMILIA  = FP.ID_FAMILIA
					LEFT JOIN CLIENTES C ON R.ID_CLIENTE  = C.ID_CLIENTE
					LEFT JOIN CBTES CF ON  CF.ID_TRANS  = R.ID_TRANS_FAC
					LEFT JOIN CBTES_COND_PAGO CCP ON CF.Id_Cond_Pago = CCP.Id_Cond_Pago
		  			LEFT JOIN Transacciones TRR ON TRR.ID_TRANS = R.ID_TRANS_FAC
					LEFT JOIN CAJAS_MOV CM ON CM.Id_Trans = R.Id_Trans
					LEFT JOIN CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = CM.Id_Periodo_Caja

		IF @pModoDebug > 0   --11
		BEGIN
			SET @pModoDebug += 1
			PRINT @pModoDebug
		END

		UPDATE #Reporte SET EFECTIVO = Imp_Prod_CIva FROM #Reporte WHERE Id_Tipo_Val = 'EFE' 
		UPDATE #Reporte SET TARJETA  = Imp_Prod_CIva FROM #Reporte WHERE Id_Tipo_Val = 'TAR'  
		UPDATE #Reporte SET CHEQ_TER = Imp_Prod_CIva FROM #Reporte WHERE Id_Tipo_Val = 'CH3'
		UPDATE #Reporte SET Cheq_Prop = Imp_Prod_CIva FROM #Reporte WHERE Id_Tipo_Val = 'CHP'  
		UPDATE #Reporte SET DEBITO = Imp_Prod_CIva FROM #Reporte WHERE Id_Tipo_Val = 'DB'  
		UPDATE #Reporte SET FINANC = Imp_Prod_CIva FROM #Reporte WHERE Id_Tipo_Val = 'FIN'
		UPDATE #Reporte SET APLIC = Imp_Prod_CIva FROM #Reporte WHERE Id_Tipo_Val IN ('APL','N/C')
		UPDATE #Reporte SET AJUSTES = isnull(Imp_Prod_CIva,0) FROM #Reporte WHERE Id_Tipo_Val = 'AJU' 
		UPDATE #Reporte SET ACUENTA = Imp_Prod_CIva FROM #Reporte WHERE Id_PRODUCTO = 'ACUENTA'
		UPDATE #Reporte SET OTROS = Imp_Prod_CIva FROM #Reporte WHERE Id_Tipo_Val = ('RET')
		UPDATE #Reporte SET Total_Pagos = (Efectivo+Tarjeta+Cheq_Ter+Cheq_Prop+Debito+Financ+Ajustes+APLIC+OTROS) from #REPORTE

	    UPDATE #Reporte SET Id_Centro_Costo = '' WHERE Id_Centro_Costo IS NULL 

		IF @pModoDebug > 0   --12
		BEGIN
			SET @pModoDebug += 1
			PRINT @pModoDebug
		END

      IF @pRegenerar_Archivo = 'S'
	     INSERT INTO RPT_Productos_Cob_Detalle 
		        SELECT * FROM #Reporte

 END

  /************************************************************* Resultado ***************************************************************************************/


  ----VALIDAR FILTROS
  SELECT * INTO #PRODUCTOS FROM PRODUCTOS where 1=0
  CREATE INDEX IX_PRODUCTOS ON #PRODUCTOS (Id_Producto)

  IF @pId_Producto = ''
     BEGIN
		  IF @pFlag_Filtrar_Prod = 1
			SET @Existe_Tag_Prod = ISNULL( (SELECT COUNT(*) FROM TagFilePos_ TAG WHERE TAG.TBL = @e_Tag_Prod AND TAG.USR = @pId_Usuario) ,0)

		  IF @Existe_Tag_Prod > 0 and @pFlag_Filtrar_Prod = 1
	    	  BEGIN
				INSERT INTO #PRODUCTOS 
				SELECT * FROM PRODUCTOS P WHERE P.ID_PRODUCTO IN (SELECT Tag.Pos FROM TagFilePos_ TAG WHERE  TAG.TBL = @e_Tag_Prod AND TAG.USR = @pId_Usuario )
              END
			ELSE
			  BEGIN
				INSERT INTO #PRODUCTOS  SELECT * FROM PRODUCTOS 
				IF NOT EXISTS (SELECT 1 FROM PRODUCTOS WHERE Id_Producto = 'ACUENTA')
					INSERT INTO #PRODUCTOS  (Id_Producto,Descripcion_Detallada) VALUES ('ACUENTA','Pago a Cuenta')
			  END
	 END
	ELSE
	 BEGIN
	    INSERT INTO #PRODUCTOS  SELECT * FROM PRODUCTOS WHERE ID_PRODUCTO = @pId_Producto
	 END


  SELECT * INTO #FAMILIAS FROM PROD_FAMILIAS where 1=0
  CREATE INDEX IX_FAMILIAS ON #FAMILIAS (Id_Familia)
  IF @pId_Familia = 0
     BEGIN
       IF @pFlag_Filtrar_Fam = 1
          SET @Existe_Tag_Fam = ISNULL( (SELECT COUNT(*) FROM TagFile_ TAG WHERE TAG.TBL = @e_Tag_Prod_Familias AND TAG.USR = @pId_Usuario) ,0)

       IF @Existe_Tag_Fam > 0 and @pFlag_Filtrar_Fam = 1
	      INSERT INTO #FAMILIAS
			SELECT * FROM PROD_FAMILIAS P WHERE P.Id_Familia IN (SELECT Tag.Val FROM TagFile_ TAG WHERE  TAG.TBL = @e_Tag_Prod_Familias AND TAG.USR = @pId_Usuario )
		ELSE
		BEGIN
		  INSERT INTO #FAMILIAS  SELECT * FROM PROD_FAMILIAS
		  IF NOT EXISTS (SELECT 1 FROM PROD_FAMILIAS WHERE Id_Familia = 65000)
			 INSERT INTO #FAMILIAS (Id_Familia,Descripcion) VALUES (65000,'Pagos a Cuenta')
		END
     END
  ELSE
	 BEGIN
	    INSERT INTO #FAMILIAS  SELECT * FROM PROD_FAMILIAS WHERE Id_Familia = @pId_Familia
	 END	
	 

  SELECT * INTO #CAJAS_PERIODOS FROM Cajas_Periodos
  CREATE INDEX IX_CAJAS_PERIODOS ON #CAJAS_PERIODOS (Id_Periodo_Caja)
   IF @pFlag_Filtrar_Caja = 1 
        DELETE #CAJAS_PERIODOS FROM #CAJAS_PERIODOS P WHERE P.Id_Periodo_Caja NOT IN (SELECT Tag.Val FROM TagFile_ TAG WHERE  TAG.TBL = @e_Tag_Prod_Cajas AND TAG.USR = @pId_Usuario )
 
---------------
  set @Total = (SELECT SUM(ISNULL(Imp_Prod_CIva,0)) FROM RPT_Productos_Cob_Detalle where FECHA_REC >= @pFechaDesde 
			          AND FECHA_REC < dateadd(dd,1,@pFechaHasta))
  
  IF UPPER(@pFormato) = 'D' OR @pFormato = ''
     IF @pId_Cliente > 0
		    SELECT R.*,P.Descripcion AS Cta, P.Nro_Cta_Contable, CC.Descripcion AS Centro_Costo,
			           REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(Telefono)), CHAR(9), ''), CHAR(13), ''), CHAR(10), ''), ' ', '/') AS Telefono,
					   C.Email, C.Doc_Nro, C.Fecha_Nac,J.Descripcion AS Descripcion_Caja, CP.Id_Cajero, E.Apellido_Nombre, U.LastName AS Operador
				FROM RPT_Productos_Cob_Detalle R 
				 LEFT JOIN Pla_Ctas_Cuentas_Contables P ON P.Id_Cta_Contable = dbo.CF_Cta_Cont(R.Alias,R.Fecha_Rec)
		    	 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				 JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja
				 JOIN Cajeros K ON K.Id_Cajero = CP.Id_Cajero
				 JOIN Empleados E ON E.Id_Empleado = K.Id_Empleado
				 JOIN Cajas J ON J.Id_Caja = CP.Id_Caja
				 JOIN CLIENTES C ON C.Id_Cliente = R.Id_cliente
				 JOIN Transacciones T ON T.Id_Trans = R.Id_Trans_Rec
				 JOIN Seg_User U ON T.Id_Usuario = U.No
				, Centro_Costos CC
				WHERE R.Id_Centro_Costo = CC.Id_Centro_Costo 
					  AND R.FECHA_REC >= @pFechaDesde 
			          AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
					  and R.Id_cliente = @pId_cliente
				ORDER BY  R.Fecha_Rec,R.Razon_Social,R.Id_Producto
		ELSE
		    SELECT R.*,P.Descripcion AS Cta, P.Nro_Cta_Contable, CC.Descripcion AS Centro_Costo,
			    REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(Telefono)), CHAR(9), ''), CHAR(13), ''), CHAR(10), ''), ' ', '/') AS Telefono,
				C.Email, C.Doc_Nro, C.Fecha_Nac,J.Descripcion AS Descripcion_Caja, CP.Id_Cajero, E.Apellido_Nombre, U.LastName AS Operador
				FROM RPT_Productos_Cob_Detalle R 
				 LEFT JOIN Pla_Ctas_Cuentas_Contables P ON P.Id_Cta_Contable = dbo.CF_Cta_Cont(R.Alias,R.Fecha_Rec)
		    	 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				 JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja
				 JOIN Cajeros K ON K.Id_Cajero = CP.Id_Cajero
				 JOIN Empleados E ON E.Id_Empleado = K.Id_Empleado
				 JOIN Cajas J ON J.Id_Caja = CP.Id_Caja
				 JOIN CLIENTES C ON C.Id_Cliente = R.Id_cliente
				 JOIN Transacciones T ON T.Id_Trans = R.Id_Trans_Rec
				 JOIN Seg_User U ON T.Id_Usuario = U.No
				, Centro_Costos CC
				WHERE R.Id_Centro_Costo = CC.Id_Centro_Costo 
					  AND R.FECHA_REC >= @pFechaDesde 
			          AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
				ORDER BY  R.Fecha_Rec,R.Razon_Social,R.Id_Producto			  

  IF UPPER(@pFormato) = 'P'
     SELECT R.Id_Producto,R.Descripcion_Detallada,Sum(ISNULL(R.Cantidad_Prod,0)) as Cantidad_Prod, SUM(r.Imp_Prod_CIva) AS Imp_Prod_CIva,
	        cast((SUM(R.Imp_Prod_CIva) / @Total * 100 ) as decimal(16,2)) AS Participacion 
			FROM RPT_Productos_Cob_Detalle R
				 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				 JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja
		    WHERE R.FECHA_REC >= @pFechaDesde 
				  AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
			GROUP BY R.Id_Producto, R.Descripcion_Detallada
			ORDER BY Participacion Desc,R.Descripcion_Detallada  

  IF UPPER(@pFormato) = 'F'
     SELECT R.Id_Familia, R.Descripcion_Familia,Sum(ISNULL(R.Cantidad_Prod,0)) as Cantidad_Prod, SUM(Imp_Prod_CIva) AS Imp_Prod_CIva,
	        CONVERT(DECIMAL(8,2),SUM(Imp_Prod_CIva) / @Total * 100) AS Participacion
			FROM RPT_Productos_Cob_Detalle R
				 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				 JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja
			Where R.Id_Familia > 0
				AND R.FECHA_REC >= @pFechaDesde 
				AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
			GROUP BY R.Id_Familia, R.Descripcion_Familia
			ORDER BY Participacion Desc
			
  IF UPPER(@pFormato) = 'R'
     SELECT R.Fecha_Rec, R.Desc_Recibo,R.Id_Trans_Rec,R.Id_Cliente,R.Id_Cliente_Externo, R.Razon_Social , SUM(Imp_Prod_CIva) AS Imp_Prod_CIva,
	        CONVERT(DECIMAL(8,2),SUM(Imp_Prod_CIva) / @Total * 100) AS Participacion
			FROM RPT_Productos_Cob_Detalle R
				 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				 JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja
			Where R.FECHA_REC >= @pFechaDesde 
				AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
			GROUP BY R.Fecha_Rec, R.Desc_Recibo,R.Id_Trans_Rec,R.Id_Cliente,R.Id_Cliente_Externo, R.Razon_Social 
			ORDER BY R.Fecha_Rec, R.Desc_Recibo

  IF UPPER(@pFormato) = 'CF'
	 SELECT R.Id_Familia, R.Descripcion_Familia,R.Id_Cobrador,R.Nombre_Cobrador , SUM(Imp_Prod_CIva) AS Imp_Prod_CIva, 
	        CONVERT(DECIMAL(8,2),SUM(Imp_Prod_CIva) / @Total * 100) AS Participacion
			FROM RPT_Productos_Cob_Detalle R 
				 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				 JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja
			Where R.Id_Familia > 0
				AND R.FECHA_REC >= @pFechaDesde 
				AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
			GROUP BY R.Id_Familia, R.Descripcion_Familia,R.Id_Cobrador,R.Nombre_Cobrador
			ORDER BY R.Nombre_Cobrador,Participacion Desc

  IF UPPER(@pFormato) = 'CFM'
	 SELECT R.Id_Familia, R.Descripcion_Familia,R.Id_Cobrador,R.Nombre_Cobrador , 
			DATEPART(mm,R.Fecha_QA) AS Mes,DATEPART(YY,R.Fecha_QA) AS Anio,
			SUM(Imp_Prod_CIva) AS Imp_Prod_CIva, 
	        CONVERT(DECIMAL(8,2),SUM(Imp_Prod_CIva) / @Total * 100) AS Participacion
			FROM RPT_Productos_Cob_Detalle R 
				 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				 JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja
			Where R.Id_Familia > 0
				AND R.FECHA_REC >= @pFechaDesde 
				AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
			GROUP BY R.Id_Familia, R.Descripcion_Familia,R.Id_Cobrador,R.Nombre_Cobrador,DATEPART(mm,R.Fecha_QA),DATEPART(YY,R.Fecha_QA)
			ORDER BY R.Nombre_Cobrador,R.Id_Cobrador,R.Descripcion_Familia,DATEPART(YY,R.Fecha_QA),DATEPART(mm,R.Fecha_QA)

  IF UPPER(@pFormato) = 'FPI'
	 SELECT R.Id_Familia, R.Descripcion_Familia,Sum(ISNULL(R.Cantidad_Prod,0)) as Cantidad_Prod,
			substring(convert(nvarchar(10),R.Fecha_QA,112),1,6)+'01' as Periodo,
			SUM(Imp_Prod_CIva) AS Imp_Prod_CIva, 
	        CONVERT(DECIMAL(8,2),SUM(Imp_Prod_CIva) / @Total * 100) AS Participacion
			FROM RPT_Productos_Cob_Detalle R 
				JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja
			Where R.Id_Familia > 0
				AND R.FECHA_REC >= @pFechaDesde 
				AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
	    	GROUP BY R.Id_Familia, R.Descripcion_Familia,substring(convert(nvarchar(10),R.Fecha_QA,112),1,6)+'01'
			ORDER BY R.Descripcion_Familia,substring(convert(nvarchar(10),R.Fecha_QA,112),1,6)+'01'


  IF UPPER(@pFormato) = 'T'
	 SELECT Id_Tipo_Cli_Ori, T.Descripcion  , SUM(Imp_Prod_CIva) AS Imp_Prod_CIva, 
	        CONVERT(DECIMAL(8,2),SUM(Imp_Prod_CIva) / @Total * 100) AS Participacion
			FROM RPT_Productos_Cob_Detalle R
				 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				 JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja, Clientes_Tipos t
			WHERE T.Id_Tipo_Cli = R.Id_Tipo_Cli_Ori
				AND R.FECHA_REC >= @pFechaDesde 
				AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
			GROUP BY Id_Tipo_Cli_Ori, T.Descripcion 
			ORDER BY Participacion Desc

  IF UPPER(@pFormato) = 'FP'
   
	 SELECT substring(convert(nvarchar(10),Fecha_Rec,112),1,6)+'01' as Fecha_Rec,sum(Efectivo) as Efectivo,sum(Tarjeta) as Tarjeta 
	        ,sum(Cheq_ter) as Cheq_ter,sum(CHEQ_PROP) as Cheq_Prop ,sum(DEBITO) as Debito 
			,sum(FINANC) as Financ ,sum(OTROS) as Otros,sum(AJUSTES) as Ajustes,sum(APLIC) as Aplic,sum(ACUENTA) as Acuenta, sum(Total_Pagos) as Total_Pagos
	 		FROM RPT_Productos_Cob_Detalle R
			   	 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				 JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja
				 WHERE R.FECHA_REC >= @pFechaDesde 
				 AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
			GROUP BY substring(convert(nvarchar(10),Fecha_Rec,112),1,6)+'01'

  IF UPPER(@pFormato) = 'S'
	 SELECT S.Id_Sector, ISNULL(S.Descripcion,'SIN SECTOR') AS Descripcion, COUNT(*) AS Cantidad, SUM(Imp_Prod_CIva) AS Imp_Prod_CIva, 
	        CONVERT(DECIMAL(8,2),SUM(Imp_Prod_CIva) / @Total * 100) AS Participacion
			FROM RPT_Productos_Cob_Detalle R
				 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
				 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
                 JOIN Empresas_Sedes_Sectores S ON S.ID_SECTOR  = PR.ID_SECTOR
			WHERE  R.FECHA_REC >= @pFechaDesde 
				   AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
			GROUP BY S.Id_Sector, S.Descripcion
			ORDER BY Participacion Desc

  IF UPPER(@pFormato) = 'CTA'
     BEGIN
		 SELECT R.Alias,C.Nro_Cta_Contable,C.Descripcion ,R.Id_Centro_Costo,CC.Descripcion AS Centro_Costo,SUM(Imp_Prod_CIva) AS Imp_Prod_CIva,
				 
				CONVERT(DECIMAL(8,2),SUM(Imp_Prod_CIva) / @Total * 100) AS Participacion 
				,SUM(APLIC) AS Aplicado
				,SUM(Imp_Prod_CIva) - SUM(APLIC) AS Tot_Sin_Aplic
				FROM RPT_Productos_Cob_Detalle R 
				 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				 JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja
				 , Pla_Ctas_Cuentas_Contables C, Centro_Costos CC
				WHERE  C.Id_Cta_Contable = dbo.CF_Cta_Cont(R.Alias,R.Fecha_Rec)
				AND R.Id_Centro_Costo = CC.Id_Centro_Costo
				AND R.FECHA_REC >= @pFechaDesde 
				AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
				GROUP BY R.Alias,C.Nro_Cta_Contable,C.Descripcion ,R.Id_Centro_Costo,CC.Descripcion
				ORDER BY C.Nro_Cta_Contable,R.Id_Centro_Costo
     END


  IF UPPER(@pFormato) = 'CC'
     BEGIN
		 SELECT R.Id_Centro_Costo,CC.Descripcion AS Centro_Costo,SUM(Imp_Prod_CIva) AS Imp_Prod_CIva, 
				CONVERT(DECIMAL(8,2),SUM(Imp_Prod_CIva) / @Total * 100) AS Participacion 
				FROM RPT_Productos_Cob_Detalle R 
				 JOIN #PRODUCTOS PR ON PR.ID_PRODUCTO  = R.ID_PRODUCTO
                 JOIN #FAMILIAS FP ON FP.ID_FAMILIA  = R.ID_FAMILIA
				 JOIN #CAJAS_PERIODOS CP ON CP.Id_Periodo_Caja = R.Id_Periodo_Caja
				, Pla_Ctas_Cuentas_Contables C, Centro_Costos CC
				WHERE  C.Id_Cta_Contable = dbo.CF_Cta_Cont(R.Alias,R.Fecha_Rec)
				AND R.Id_Centro_Costo = CC.Id_Centro_Costo
				AND R.FECHA_REC >= @pFechaDesde 
				AND R.FECHA_REC < dateadd(dd,1,@pFechaHasta)
				GROUP BY R.Id_Centro_Costo,CC.Descripcion
				ORDER BY CC.Descripcion
      END

 
  IF EXISTS(SELECT [name] FROM tempdb.sys.tables WHERE [name] = '#Reporte') 
		DROP TABLE #Reporte

  IF @pRegenerar_Archivo ='S'
     BEGIN
		  DROP TABLE #NCREDITO
		  DROP TABLE #Valores_Rec
		  DROP TABLE #Facturas
		  DROP TABLE #RESUMEN 
		  DROP TABLE #ITEMS
		  DROP TABLE #Recibos_Aplic
		  DROP TABLE #PRODUCTOS  
		  DROP TABLE #FAMILIAS 
		  DROP TABLE #CAJAS_PERIODOS  
		  DROP TABLE #RETEN 
		  DROP TABLE #TOT_RETEN 		
     END


