CREATE  PROCEDURE [dbo].[CPJ_Proveedores_CtaCte] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON

/*Declaracion Variables Locales*/

DECLARE @pFecha_Desde DATETIME
		,@pFecha_Hasta DATETIME
		,@pId_Proveedor INT
		
SET @pFecha_Desde					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde')), '19000101')
SET @pFecha_Hasta					= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta')), GETDATE())
SET @pId_Proveedor   		     	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Proveedor')), 0)


  
	 SELECT cc.fecha_vence,cc.fecha,cc.descripcion,cc.nro_cuota,cc.id_moneda,cc.importe,cc.saldo,c.id_proveedor,c.destinatario,c.id_trans 
		FROM proveedores_ctacte CC, cbtes c, cbtes_tipos T, Proveedores K
		WHERE c.id_trans = cc.id_trans 
		and c.id_tipo_cbte = t.id_tipo_cbte
		and c.Id_Proveedor = k.Id_Proveedor 
		and c.Id_Proveedor = @pId_Proveedor 
		and c.id_estado_cbte NOT IN (0,3)
		and c.fecha >= @pFecha_Desde
		and c.Fecha < Dateadd(d,1,@pFecha_Hasta)
		--and cc.saldo <> 0
		ORDER BY cc.Fecha 

 
 --  exec CPJ_Proveedores_CtaCte '{"Id_Proveedor":"1276","Fecha_Desde":"20220101","Fecha_Hasta":"20231231"}'
GO

 

CREATE PROCEDURE [dbo].[CPJ_Proveedores_Deuda_Actual]	@pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON

/*Parametros*/
DECLARE @pFechaDesde			DATETIME,
		@pFechaHasta			DATETIME,
		@pId_Unid_Negocio       VARCHAR(10),
		@pFiltrar_con_saldo     TINYINT,
		@pProveedores_activos   TINYINT,
        @pId_Proveedor          INT,
		@pFiltroFecha           TINYINT,
		@pEquate                SMALLINT,
		@pFormato			    CHAR(10),  /* T: Agrupado por proveedor       D: Detallado        */
		@pOrden                 CHAR(10),  /* IA: Importe Ascedente    ID: Importe Descendente       R: Razon Social        */
        @pUsuario               INT,
		@pTipo					CHAR(1),    /* C: Contable (deuda en negativo)      G: Gestion/Directivo (deuda en positovo)*/    
		@pTipoSaldo				CHAR(1),    /* T:Todos		A:Acreedor				D:Deudor     */    
		@pModoDebug				TINYINT


/*Fin de Parametros*/

	
		/*Seteo Parametros*/
		SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
		SET @pFechaDesde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaDesde')),GETDATE())
		SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())
		SET @pFiltrar_con_saldo			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Filtrar_con_saldo')),0)
		SET @pProveedores_activos		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Proveedores_activos')),0)
		SET @pFormato					= UPPER(ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Formato')),'T'))
		SET @pId_Proveedor				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Proveedor')),0)
		SET @pFiltroFecha		    	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FiltroFecha')),0)
		SET @pEquate		        	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Equate')),0)
		SET @pUsuario		        	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Usuario')),0)
		SET @pOrden				     	= UPPER(ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Orden')),''))
		SET @ptipo						= UPPER(ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Tipo')),'C'))
		SET @ptipoSaldo					= UPPER(ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'TipoSaldo')),'A'))
		SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)



		/*Declaro Variables Locales*/
		DECLARE  @Id_Proveedor					INT
				,@Razon_Social					VARCHAR(100)
				,@Cuit							VARCHAR(13)
				,@Id_Iva						CHAR(3)
				,@Id_Alias_Cta_Cont				INT
				,@Id_Cta_Contable_H				INT
				,@Porc_Comision_Prov			DECIMAL(7,2) 
				,@Importe						DECIMAL(12,2) 
				,@IMPORTE_CREDITO				DECIMAL(12,2) 
				,@ID_TIPO_CBTE					CHAR(4) 
				,@FECHA							DATETIME
				,@Imp_prod_siva					DECIMAL(12,2) 
				,@TRANS							INT
				,@Id_Cta_Banco					INT
				,@EXISTE_TAG					INT
			    ,@DEUDA_TOTAL  Decimal(14,2) 


		DECLARE @Sql		    VARCHAR(MAX)
		DECLARE @SqlSaldo	    VARCHAR(MAX)
		DECLARE @SqlSelect		VARCHAR(MAX)
		DECLARE @SqlSelectRec	VARCHAR(MAX)
		DECLARE @SqlFrom	    VARCHAR(MAX)
		DECLARE @SqlFromRec	    VARCHAR(MAX)
		DECLARE @SqlWhere		VARCHAR(MAX)
		DECLARE @SqlWhereFac	VARCHAR(MAX)
		DECLARE @SqlWhereRec	VARCHAR(MAX)
		DECLARE @SqlOrden   	VARCHAR(MAX)
		DECLARE @sqlgroup       VARCHAR(MAX)
		DECLARE @SqlHaving      VARCHAR(MAX)

		/*Fin Variables Locales*/

		SET @Sql	    = ''
		SET @SqlSaldo	= ''
		SET @SqlSelect	= ''
		SET @SqlSelectRec	= ''
		SET @SqlFrom	= ''
		SET @SqlFromRec	= ''
		SET @SqlWhere	= ''
		SET @SqlWhereFac	= ''
		SET @SqlWhereRec	= ''
		SET @SqlOrden	    = ''
		SET @sqlgroup       = ''
		SET @SqlHaving      = ''

		SET @FECHA		= (SELECT CAST(GETDATE() AS DATE))
		SET @EXISTE_TAG = 0

		SELECT ID_UNID_NEGOCIO 
			INTO #UN FROM Empresas_Unid_Negocios

		IF(CAST(@pId_Unid_Negocio AS INT)) <> 0
			DELETE #UN WHERE ID_UNID_NEGOCIO <> @pId_Unid_Negocio


		CREATE TABLE #ACTIVO (ACTIVO TINYINT)
			INSERT INTO #ACTIVO (ACTIVO) VALUES (1)

		IF(@pProveedores_activos) <> 1
			INSERT INTO #ACTIVO (ACTIVO) VALUES (0)



		/************************************************ SQL SELECT ************************************************/
		
		CREATE TABLE #Result (
		  	Id_Proveedor		INT
			,Razon_Social		VARCHAR(100)
			,Id_Trans			INT
			,Id_Tipo_Cbte		CHAR(4)
			,Fecha				DATETIME
			,Fecha_Venc			DATETIME
			,Cbte_Descrip		VARCHAR(100)
			,Nro_Cuota			INT
			,Saldo				DECIMAL(16,2)
			,Porc_Part			DECIMAL(6,2)
			,Cotizacion			DECIMAL(12,5)
			)

		CREATE TABLE #Result2 (
		  	Id_Proveedor		INT
			,Razon_Social		VARCHAR(100)
			,Id_Trans			INT
			,Id_Tipo_Cbte		CHAR(4)
			,Fecha				DATETIME
			,Fecha_Venc			DATETIME
			,Cbte_Descrip		VARCHAR(100)
			,Nro_Cuota			INT
			,Saldo				DECIMAL(16,2)
			,Porc_Part			DECIMAL(6,2)
			,Cotizacion			DECIMAL(12,5)
			)

		IF @pFormato IN ('T')
			SET @SqlSelect = 'INSERT INTO #Result (Id_Proveedor,Razon_Social,Saldo,Cotizacion) 
				SELECT C.Id_Proveedor, C.Razon_Social, (CC.Saldo  * F.Cotizacion  ) AS Saldo,F.Cotizacion'
        
		IF @pFormato IN ('D')
			SET @SqlSelect = 'INSERT INTO #Result (Id_Proveedor,Razon_Social,Id_Trans,Id_Tipo_Cbte,Fecha,Fecha_Venc,Nro_Cuota,Saldo,Cotizacion) 
				SELECT C.Id_Proveedor, C.Razon_Social,F.Id_Trans,F.Id_Tipo_Cbte,F.Fecha,F.Fecha_Venc,CC.Nro_Cuota, (CC.Saldo  * F.Cotizacion) AS Saldo, F.Cotizacion'
 

		/************************************************ SQL FROM ************************************************/

		SET @SqlFrom = ' FROM Proveedores_Ctacte CC
		                        JOIN Cbtes F ON CC.Id_Trans = F.Id_Trans
								JOIN Cbtes_Tipos TF ON F.Id_Tipo_Cbte = TF.Id_Tipo_Cbte
								JOIN #UN U ON TF.Id_Unid_Negocio = U.Id_Unid_Negocio
								JOIN Proveedores C ON CC.Id_Proveedor = C.Id_Proveedor
								JOIN #ACTIVO A ON C.Activo = A.Activo' 


		/************************************************ SQL WHERE ************************************************/

		SET @SqlWhere =	  ' WHERE F.Id_Proveedor <> 0
									AND F.Id_Estado_Cbte IN (1,4)
									AND F.Saldo <> 0 
									AND TF.Letra <> ''L''
									AND F.Imp_Total <> 0 
									AND CC.Importe <> 0 '


		SET @SqlWhereFac +=	  ' AND (TF.Compromete_Compras IN (1,-1) OR TF.Compromete_Pagos IN (1,-1))'
		SET @SqlWhereRec =	  ' AND TF.Compromete_Pagos IN (1,-1) ' 



    	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND CC.Fecha_Vence < ''' + CONVERT(VARCHAR(8),@pFechaHasta+1,112) +'''' 

		IF(@pId_Proveedor) <> 0
				SET @SqlWhere += ' AND CC.Id_Proveedor = ' + CONVERT(VARCHAR(8),@pId_Proveedor) 
        


		SET @Sql = @SqlSelect + ' ' + ' '+ @SqlFrom + ' ' + @SqlWhere +' '+ @SqlWhereFac 


		/**********************************************************************************************************/

  		IF @pModoDebug = 1 PRINT '1  '+ @Sql
		EXEC(@sql)

		IF @pTipo = 'C'
			UPDATE #result set saldo = saldo * -1 WHERE saldo IS NOT NULL  

		UPDATE #result set saldo = 0 WHERE saldo IS NULL   
		 
        IF @pFormato IN ('T') --Formato Agrupado
		BEGIN
			SET @sqlselect = 'INSERT INTO #Result2 (Id_Proveedor,Razon_Social,Porc_Part,Saldo) SELECT Id_Proveedor,Razon_Social, 0 as Porc_Part,SUM(Saldo) as Saldo FROM #Result '
			SET @sqlwhere = ' '
			SET @sqlgroup = ' GROUP BY Id_Proveedor,Razon_Social'

			If @pFiltrar_con_saldo = 1
			BEGIN
				IF  (@pTipoSaldo = 'A' AND  @pTipo = 'C') OR (@pTipoSaldo = 'D' AND  @pTipo = 'G')
					SET @sqlgroup += ' HAVING SUM(Saldo) < 0 '
				ELSE IF (@pTipoSaldo = 'D' AND  @pTipo = 'C') OR (@pTipoSaldo = 'A' AND  @pTipo = 'G')
					SET @sqlgroup += ' HAVING SUM(Saldo) > 0 '
				ELSE
					SET @sqlgroup += ' HAVING SUM(Saldo) != 0 ' /*No hay condicion para "Tipo":"C","TipoSaldo":"T" solo traera saldos positivos*/
			END

			IF @pOrden = 'ID'
				SET @SqlOrden  = ' ORDER BY 4 DESC '
			ELSE IF @pOrden = 'IA'
				SET @SqlOrden  = ' ORDER BY 4 ASC'
			ELSE
				SET @SqlOrden  = ' ORDER BY Razon_Social'
        END   
		ELSE -- 	IF @pFormato IN ( 'D')  --Formato Detallado Traera saldos positivos y negativos
		BEGIN
			SET @sqlselect = 'INSERT INTO #Result2 SELECT * FROM #Result '
			SET @sqlwhere = ' '
			SET @sqlgroup = ' '
			SET @SqlOrden  = ' ORDER BY Razon_Social,Fecha_Venc'
        END   
  
		IF @pOrden = 'ID'
			IF @pTipo = 'C'
				SET @SqlOrden  = ' ORDER BY 4 ASC '
			ELSE
				SET @SqlOrden  = ' ORDER BY 4 DESC'
		ELSE IF @pOrden = 'IA'
			IF @pTipo = 'C'
				SET @SqlOrden  = ' ORDER BY 4 DESC '
			ELSE
				SET @SqlOrden  = ' ORDER BY 4 ASC'
		ELSE
			SET @SqlOrden  = ' ORDER BY Razon_Social'

     
		SET @Sql = @SqlSelect + ' ' + @SqlWhere +' '+ @SqlGroup + ' '+ @SqlHaving  +' '+ @SqlOrden
		IF @pModoDebug = 1 PRINT '3 '+ @Sql
		EXEC(@sql)

		SET @DEUDA_TOTAL = (SELECT SUM(Saldo) FROM #result2 )
		UPDATE #Result2 SET Porc_Part = Saldo / @DEUDA_TOTAL * 100

		select * from #Result2
 
					 					 
  		DROP TABLE #UN
		DROP TABLE #ACTIVO
		DROP TABLE #Result

/*

EXEC CPJ_PROVEEDORES_Deuda_Actual '{"FechaHasta":"20261231","Id_Unid_Negocio":"","Filtrar_con_saldo":"1"
,"Proveedores_activos":"1","Id_Proveedor":"","Id_Familia":"","Orden":"ID","TipoSaldo":"D","Tipo":"G","Formato":"T"}'   

*/
GO



CREATE PROCEDURE [dbo].[CPJ_Proveedores_Deuda_a_Fecha] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON
/*Parametros*/

DECLARE 	@pFechaHasta			DATETIME,
			@pId_Unid_Negocio       VARCHAR(10),
			@pFiltrar_con_saldo     TINYINT,
			@pProveed_activos       TINYINT,
			@pFiltroFecha           TINYINT,
			@pCriterio              VARCHAR(2),
			@pId_Proveedor          INT,
            @pIncluir_Deuda         CHAR(1)

SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())
SET @pFiltrar_con_saldo			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Filtrar_con_saldo')),0)
SET @pProveed_activos			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Proveed_activos')),0)
SET @pFiltroFecha		    	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FiltroFecha')),0)
SET @pCriterio			        = ISNULL(CONVERT(VARCHAR(2), dbo.CF_JSON_VALUE(@pJsonRecibido,'Criterio')),'R')
SET @pId_Proveedor  			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Proveedor')),0)
SET @pIncluir_Deuda          	= ISNULL(CONVERT(char(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Incluir_Deuda')),'D')

 
DECLARE @pFecha DATETIME
SET @pFecha  = @pFechaHasta+1


Select * into #Proveedores from Proveedores where 1=0
If @pId_Proveedor <> 0
     Insert Into #Proveedores select * from Proveedores where Id_Proveedor = @pId_Proveedor
  Else
   If @pProveed_activos = 1
      Insert Into #Proveedores select * from Proveedores where Activo = 1 AND Id_Proveedor > 0  AND Id_Proveedor IS NOT NULL
	Else
	  Insert Into #Proveedores select * from Proveedores where Id_Proveedor > 0  AND Id_Proveedor IS NOT NULL
 
CREATE INDEX IX_#Proveedores_ ON #Proveedores (Id_Proveedor)

Select Id_unid_Negocio into #Unid_Negocios from Empresas_Unid_Negocios
If @pId_Unid_Negocio <> ''
   Delete #Unid_Negocios where Id_unid_Negocio <> @pId_Unid_Negocio

CREATE INDEX IX_#Unid_Negocios_ ON #Unid_Negocios (Id_unid_Negocio)
--paso 1 FC

SELECT A.Id_Trans,SUM(ISNULL(A.Importe,0)) AS Imp_Aplicado 
        INTO #APLICADO1
		FROM Cbtes_Aplica A
		  JOIN Cbtes p ON p.Id_Trans = A.ID_TRANS_D  AND p.id_estado_cbte  in (1,2,4)  
		  JOIN Cbtes_Tipos tp ON  p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte and (tp.Compromete_Pagos =1 )
		  JOIN #Proveedores K ON K.Id_Proveedor = P.Id_Proveedor
		WHERE P.FECHA < @pFecha  AND A.Id_trans <> 0
GROUP BY A.Id_Trans
CREATE INDEX ID_APLICADO1 ON #APLICADO1 (ID_TRANS)

SELECT A.Id_Trans,SUM(ISNULL(A.Importe,0)) AS Imp_Aplicado 
        INTO #APLICADO3
		FROM Cbtes_Aplica A
		  JOIN Cbtes p ON p.Id_Trans = A.ID_TRANS_D  AND p.id_estado_cbte  in (1,2,4)  
		  JOIN Cbtes_Tipos tp ON  p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte and (tp.Compromete_Compras =-1)
		  JOIN #Proveedores K ON K.Id_Proveedor = P.Id_Proveedor
		WHERE P.FECHA < @pFecha  AND A.Id_trans <> 0
GROUP BY A.Id_Trans
CREATE INDEX ID_APLICADO3 ON #APLICADO3 (ID_TRANS)

SELECT A.Id_Trans_D ,SUM(ISNULL(A.Importe,0)) AS Imp_Aplicado 
        INTO #APLICADO2
		FROM Cbtes_Aplica A
		  JOIN Cbtes p ON p.Id_Trans = A.ID_TRANS  AND p.id_estado_cbte  in (1,2,4)  
		  JOIN Cbtes_Tipos tp ON  p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte and ( tp.Compromete_Pagos = 1 OR tp.Compromete_Compras IN (1,-1))
		  JOIN #Proveedores K ON K.Id_Proveedor = P.Id_Proveedor
		WHERE P.FECHA < @pFecha  AND A.Id_trans <> 0
GROUP BY A.Id_Trans_D
CREATE INDEX ID_APLICADO2 ON #APLICADO2 (Id_Trans_D)


SELECT C.Id_Proveedor,P.Razon_Social,C.ID_TIPO_CBTE,C.COMPROBANTE_NRO,C.FECHA,(C.Imp_Total)*-1 AS IMP_TOTAL  
	,CAST(Isnull(A1.Imp_Aplicado,0) AS DECIMAL(16,2)) AS Imp_Aplicado 
	,CAST(Isnull(A2.Imp_Aplicado,0) AS DECIMAL(16,2)) AS Imp_Aplicado2
	,CAST(Isnull(A3.Imp_Aplicado,0) AS DECIMAL(16,2)) AS Imp_Aplicado3 
	,(C.SALDO)*-1 AS SALDO,C.ID_TRANS
INTO #DEUDA
FROM CBTES C
		 JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.ID_TIPO_CBTE  AND  T.COMPROMETE_COMPRAS IN (1)
		 JOIN #Proveedores P ON  P.Id_Proveedor = C.Id_Proveedor
		 JOIN #Unid_Negocios U ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
		 LEFT JOIN #APLICADO1 A1 ON  A1.ID_TRANS = C.Id_Trans
		 LEFT JOIN #APLICADO2 A2 ON  A2.ID_TRANS_D = C.Id_Trans
		 LEFT JOIN #APLICADO3 A3 ON  A3.ID_TRANS = C.Id_Trans
	WHERE  C.Id_Estado_Cbte IN (1,2,4)
		AND C.FECHA < @pFecha
		AND ( NOT EXISTS (SELECT A.ID_TRANS FROM CBTES_APLICA A WHERE C.ID_TRANS = A.ID_TRANS)
		OR  (ABS(C.Imp_Total) > ABS(Isnull(A1.Imp_Aplicado,0))+abs(isnull(A2.Imp_Aplicado,0))+abs(isnull(A3.Imp_Aplicado,0)))
		OR 	(SELECT MAX(p.fecha)
			 FROM cbtes_aplica a, cbtes p, Cbtes_Tipos tp 
			 WHERE p.Id_Trans = A.ID_TRANS_D  AND A.ID_TRANS = C.Id_Trans 
			 and p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte 
		     AND p.id_estado_cbte IN (1,2,4)
			 and (tp.Compromete_Pagos in (1,-1) OR tp.Compromete_Compras in (-1))
	 ) >= @pFecha )

-- paso 2 NC

UNION ALL

SELECT C.Id_Proveedor,P.Razon_Social,C.ID_TIPO_CBTE,C.COMPROBANTE_NRO,C.FECHA,C.IMP_TOTAL*-1 AS IMP_TOTAL 
,CAST(Isnull(A1.Imp_Aplicado,0) AS DECIMAL(12,2)) AS Imp_Aplicado 
,CAST(Isnull(A2.Imp_Aplicado,0) AS DECIMAL(16,2)) AS Imp_Aplicado2 
,CAST(Isnull(A3.Imp_Aplicado,0) AS DECIMAL(12,2)) AS Imp_Aplicado3
,C.SALDO*-1 AS SALDO,C.ID_TRANS
FROM CBTES C
		 JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.ID_TIPO_CBTE  AND  T.COMPROMETE_COMPRAS IN (-1)
		 JOIN #Proveedores P ON  P.Id_Proveedor = C.Id_Proveedor
		 JOIN #Unid_Negocios U ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
		 LEFT JOIN #APLICADO1 A1 ON  A1.ID_TRANS = C.Id_Trans
		 LEFT JOIN #APLICADO2 A2 ON  A2.ID_TRANS_D = C.Id_Trans
		 LEFT JOIN #APLICADO3 A3 ON  A3.ID_TRANS = C.Id_Trans
	WHERE  C.Id_Estado_Cbte IN (1,2,4)
		AND C.FECHA < @pFecha
		AND ( NOT EXISTS  (SELECT A.ID_TRANS FROM CBTES_APLICA A WHERE C.ID_TRANS = A.ID_TRANS)
			OR  (ABS(C.Imp_Total) > ABS(Isnull(A2.Imp_Aplicado,0)))
		    OR  (SELECT MAX(F.Fecha)
					 FROM Cbtes F 
					 JOIN Cbtes_Aplica A ON F.Id_Trans = A.ID_TRANS_D AND A.ID_TRANS = C.ID_TRANS 
					 JOIN Cbtes_Tipos TP ON F.Id_Tipo_Cbte = TP.Id_Tipo_Cbte  and (tp.Compromete_Pagos = 1 OR tp.Compromete_Compras in (1))
					 WHERE F.id_estado_cbte IN (1,2,4)	 
			 ) >= @pFecha )
 
--paso 3 OP
UNION ALL

SELECT  C.Id_Proveedor,P.Razon_Social,C.ID_TIPO_CBTE,C.COMPROBANTE_NRO,C.FECHA,C.IMP_TOTAL, 
  (SELECT ISNULL(SUM(A.IMPORTE),0) FROM CBTES_APLICA A, CBTES K WHERE C.ID_TRANS = A.ID_TRANS_D
  AND A.ID_TRANS = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3) AND C.ID_PROVEEDOR = K.ID_PROVEEDOR and a.id_trans <> 0
  AND ISNULL((SELECT COUNT(*) FROM CBTES_APLICA CA WHERE C.ID_TRANS = CA.ID_TRANS_D),0) >=1 
  )*-1  as Imp_Aplicado,
  (SELECT ISNULL(SUM(A.IMPORTE),0) FROM CBTES_APLICA A, CBTES K WHERE C.ID_TRANS = A.ID_TRANS
  AND A.ID_TRANS_D = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3) AND C.ID_PROVEEDOR = K.ID_PROVEEDOR )  as Imp_Aplicado2,
  CAST(0 AS DECIMAL(12,2)) AS Imp_Aplicado3,
  C.SALDO,C.ID_TRANS
FROM CBTES C, CBTES_TIPOS T, #Proveedores P , #Unid_Negocios U
WHERE C.Id_Tipo_Cbte = T.ID_TIPO_CBTE
AND P.Id_Proveedor = C.Id_Proveedor
AND T.Compromete_Pagos IN (1,-1)
AND U.Id_Unid_Negocio = T.Id_Unid_Negocio
AND C.Id_Estado_Cbte IN (1,2,4) 
AND C.FECHA < @pFecha
AND (((SELECT max(A.ID_TRANS) FROM CBTES_APLICA A , CBTES K WHERE C.ID_TRANS = A.Id_Trans_D
     AND A.ID_TRANS = K.ID_TRANS AND K.ID_ESTADO_CBTE IN (1,2,4)) = 0)
   OR (SELECT SUM(A.IMPORTE) FROM CBTES_APLICA A, CBTES K WHERE C.ID_TRANS = A.Id_Trans_D
      AND A.ID_TRANS = K.ID_TRANS AND K.ID_ESTADO_CBTE IN (1,2,4)	AND A.ID_TRANS <> 0) <> ABS(C.IMP_TOTAL) )
AND isnull((SELECT ABS(SUM(A.IMPORTE)) FROM CBTES_APLICA A, CBTES K WHERE C.Id_Trans = A.Id_Trans
      AND A.ID_TRANS_D = K.ID_TRANS AND K.ID_ESTADO_CBTE IN (1,2,4)),0) <> ABS(C.IMP_TOTAL) 


delete #DEUDA where ABS(imp_total) - (ABS(Imp_Aplicado) + ABS(Imp_Aplicado2) + ABS(Imp_Aplicado3)) = 0

--select * from #DEUDA

if @pCriterio = 'D'
   BEGIN
       IF @pIncluir_Deuda = 'T'
		   SELECT D.Id_Proveedor,D.Razon_Social,D.Fecha,C.Fecha_Venc,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion,c.Id_Moneda AS Signo,ISNULL(D.imp_total,0) + (ISNULL(Imp_Aplicado+Imp_Aplicado2,0))  AS IMP_TOTAL,D.Id_Trans 
		   FROM #DEUDA D, CBTES C where C.Id_trans = D.Id_Trans AND ISNULL(D.imp_total,0)- Abs(ISNULL(Imp_Aplicado+Imp_Aplicado2,0)) <> 0
			  ORDER BY Razon_Social,D.Fecha
       IF @pIncluir_Deuda = 'D'
		   SELECT D.Id_Proveedor,D.Razon_Social,D.Fecha,C.Fecha_Venc,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion,c.Id_Moneda AS Signo,ISNULL(D.imp_total,0) + (ISNULL(Imp_Aplicado+Imp_Aplicado2,0))  AS IMP_TOTAL,D.Id_Trans 
		   FROM #DEUDA D, CBTES C where C.Id_trans = D.Id_Trans AND ISNULL(D.imp_total,0)- Abs(ISNULL(Imp_Aplicado+Imp_Aplicado2,0)) > 0
			  ORDER BY Razon_Social,D.Fecha
       IF @pIncluir_Deuda = 'A'
		   SELECT D.Id_Proveedor,D.Razon_Social,D.Fecha,C.Fecha_Venc,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion,c.Id_Moneda AS Signo,ISNULL(D.imp_total,0) + (ISNULL(Imp_Aplicado+Imp_Aplicado2,0))  AS IMP_TOTAL,D.Id_Trans 
		   FROM #DEUDA D, CBTES C where C.Id_trans = D.Id_Trans AND ISNULL(D.imp_total,0)- Abs(ISNULL(Imp_Aplicado+Imp_Aplicado2,0))  < 0
			  ORDER BY Razon_Social,D.Fecha
   END
 else
    IF @pFiltrar_con_saldo = 1
	   BEGIN
		   IF @pIncluir_Deuda = 'T'
			   SELECT Id_Proveedor,Razon_Social,SUM(ISNULL(imp_total,0) + (ISNULL(Imp_Aplicado+Imp_Aplicado2,0))) as Saldo FROM #DEUDA 
				   GROUP BY Id_Proveedor,Razon_Social 	 HAVING SUM(ISNULL(imp_total,0) + Abs(ISNULL(Imp_Aplicado+Imp_Aplicado2,0))) <> 0
				ORDER BY Razon_Social 
		   IF @pIncluir_Deuda = 'D'
			   SELECT Id_Proveedor,Razon_Social,SUM(ISNULL(imp_total,0) + (ISNULL(Imp_Aplicado+Imp_Aplicado2,0))) as Saldo FROM #DEUDA 
				   GROUP BY Id_Proveedor,Razon_Social 	 HAVING SUM(ISNULL(imp_total,0) + Abs(ISNULL(Imp_Aplicado+Imp_Aplicado2,0))) > 0
				ORDER BY Razon_Social 
		   IF @pIncluir_Deuda = 'A'
			   SELECT Id_Proveedor,Razon_Social,SUM(ISNULL(imp_total,0) + (ISNULL(Imp_Aplicado+Imp_Aplicado2,0))) as Saldo FROM #DEUDA 
				   GROUP BY Id_Proveedor,Razon_Social 	 HAVING SUM(ISNULL(imp_total,0) + Abs(ISNULL(Imp_Aplicado+Imp_Aplicado2,0))) < 0
				ORDER BY Razon_Social 
       END
      ELSE
		SELECT Id_Proveedor,Razon_Social,SUM(ISNULL(imp_total,0) + (ISNULL(Imp_Aplicado+Imp_Aplicado2,0))) as Saldo FROM #DEUDA 
		   GROUP BY Id_Proveedor,Razon_Social
		ORDER BY Razon_Social 



DROP TABLE #DEUDA
DROP TABLE #Proveedores
DROP TABLE #Unid_Negocios
DROP TABLE #APLICADO1
DROP TABLE #APLICADO2
DROP TABLE #APLICADO3
