EXEC CPJ_Proveedores_Deuda_a_Fecha '{"FechaHasta":"20260304","Id_Unid_Negocio":"","Filtrar_con_saldo":"1","Proveed_activos":"0","Criterio":"T","Incluir_Deuda":"a","Id_proveedor":"294"}'

 
*/
