CREATE PROCEDURE [dbo].[CPJ_Proveedores_ResumenCta] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON
/*Parametros*/

DECLARE 	@pFechaDesde			DATETIME,
			@pFechaHasta			DATETIME,
			@pId_Unid_Negocio       VARCHAR(10),
			@pFiltrar_con_saldo     TINYINT,
			@pProveedores_activos   TINYINT, 
			@pId_Proveedor          INT,
            @pIncluir_Deuda         CHAR(1)


SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
SET @pFechaDesde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaDesde')),GETDATE())
SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())
SET @pFiltrar_con_saldo			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Filtrar_con_saldo')),0)
SET @pProveedores_activos		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Proveedores_activos')),0)
SET @pId_Proveedor			    = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Proveedor')),0)
SET @pIncluir_Deuda          	= ISNULL(CONVERT(char(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Incluir_Deuda')),'A')
/*Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@Id_Proveedor		INT
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Trans_Rec		INT
		,@CursorOpen        INT
		,@Flag_Cbte_Tipo	SMALLINT
		,@Periodo           DATE 
		,@Id_sucursal	    SMALLINT
		,@Venta_Total       DECIMAL(16,2)

					
BEGIN 


Select Id_Proveedor  Into #Proveedores from Proveedores where 1=0
	  If @pId_Proveedor = 0
	     Insert Into #Proveedores select Id_Proveedor From Proveedores  where  Id_Proveedor > 1
       ELSE
	     Insert Into #Proveedores select Id_Proveedor From Proveedores  where  Id_Proveedor = @pId_Proveedor
    CREATE INDEX IX_Proveedores ON  #Proveedores (ID_PROVEEDOR) 	

-- select * from #Clientes order by id_cliente_ref

    SELECT ID_UNID_NEGOCIO INTO #UN FROM Empresas_Unid_Negocios

    IF CAST(@pId_Unid_Negocio as int) <> 0
       DELETE #UN WHERE ID_UNID_NEGOCIO <> @pId_Unid_Negocio 

    CREATE INDEX IX_Unid_Negocio ON  #UN (Id_Unid_Negocio) 

	CREATE TABLE #ACTIVO (ACTIVO TINYINT)
    INSERT INTO #ACTIVO (ACTIVO) VALUES (1)

	IF @pProveedores_activos <> 1
	  INSERT INTO #ACTIVO (ACTIVO) VALUES (0)

print getdate()


	Select F.Id_Proveedor
			, CAST(sum(isnull(ABS(f.Imp_Total),0) * f.cotizacion * T.Compromete_Compras) - sum(isnull((f.Imp_Total),0) * f.cotizacion * T.Compromete_Pagos) AS DECIMAL(14,2)) AS Saldo
			, CAST(0 AS decimal(16,2)) AS Debe,  CAST(0 AS decimal(16,2)) AS Haber, CAST(0 AS decimal(16,2)) AS Sdo_Ant
		Into #Resumen_Cta
		 from Cbtes F
		      JOIN Cbtes_Tipos T ON F.id_tipo_cbte = T.id_tipo_cbte AND (t.Compromete_Compras in (1,-1) or t.Compromete_Pagos = 1)
			  JOIN #UN U ON  T.Id_Unid_Negocio = U.Id_Unid_Negocio
			  JOIN #Proveedores K ON K.Id_Proveedor = f.Id_Proveedor
		 where F.id_estado_cbte  in (1,2,4)
		      AND F.FECHA < dateadd(dd,1,@pFechaHasta)
		 group by F.Id_Proveedor 

       CREATE INDEX IX_Resumen_Cta ON  #Resumen_Cta (ID_PROVEEDOR) 	 
print getdate()
--return

--		IF @pFiltrar_con_saldo = 1
--		      DELETE #Resumen_Cta WHERE ABS(SALDO) = 0

	Select F.Id_Proveedor
			, CAST(sum(isnull(ABS(f.Imp_Total),0) * f.cotizacion * T.Compromete_Compras) - sum(isnull((f.Imp_Total),0) * f.cotizacion * T.Compromete_Pagos) AS DECIMAL(14,2)) AS Sdo_Ant
		Into #Resumen_Sdo_Ant
		 from Cbtes F
		      JOIN Cbtes_Tipos T ON F.id_tipo_cbte = T.id_tipo_cbte AND (t.Compromete_Compras in (1,-1) or t.Compromete_Pagos = 1)
			  JOIN #UN U ON  T.Id_Unid_Negocio = U.Id_Unid_Negocio
			  JOIN #Proveedores K ON K.Id_Proveedor = f.Id_Proveedor
		 where F.id_estado_cbte  in (1,2,4)
		      AND F.FECHA < @pFechaDesde
		 group by F.Id_Proveedor 

     CREATE INDEX IX_Resumen_SdoAnt ON  #Resumen_Sdo_Ant (ID_PROVEEDOR) 	 

print getdate()
--return
		select F.Id_Proveedor
				,sum(isnull(aBS(f.Imp_Total),0) * f.cotizacion) as Haber
	     into #Resumen_Haber
		 from Cbtes F
		      JOIN Cbtes_Tipos T ON F.id_tipo_cbte = T.id_tipo_cbte AND T.Compromete_Compras in (1)
			  JOIN #UN U ON  T.Id_Unid_Negocio = U.Id_Unid_Negocio
			  JOIN #Proveedores K ON K.Id_Proveedor = f.Id_Proveedor
		 where F.id_estado_cbte  in (1,2,4)
				AND F.FECHA >= @pFechaDesde 
				AND F.FECHA < dateadd(dd,1,@pFechaHasta)
		 group by F.Id_Proveedor 

     CREATE INDEX IX_Resumen_Haber ON  #Resumen_Haber (ID_PROVEEDOR) 	

		Select F.Id_Proveedor
		       ,(sum(isnull(ABS(f.Imp_Total),0) * f.cotizacion * T.Compromete_Compras))
			   + (sum(isnull(f.Imp_Total,0) * f.cotizacion*T.Compromete_Pagos)) as Debe 
		 Into #Resumen_Debe
		 From Cbtes F
		      JOIN Cbtes_Tipos T ON F.id_tipo_cbte = T.id_tipo_cbte AND (t.Compromete_Compras in (-1) OR t.Compromete_Pagos in (1)) 
			  JOIN #UN U ON  T.Id_Unid_Negocio = U.Id_Unid_Negocio
			  JOIN #Proveedores K ON K.Id_Proveedor = f.Id_Proveedor
		 Where F.id_estado_cbte  in (1,2,4)
				AND F.FECHA >= @pFechaDesde 
				AND F.FECHA < dateadd(dd,1,@pFechaHasta)
		 Group by F.Id_Proveedor 

    CREATE INDEX IX_Resumen_Debe ON  #Resumen_Debe (ID_PROVEEDOR) 	
print getdate()
--return
		UPDATE #Resumen_Cta set Debe = ISNULL(D.Debe,0), Haber = ISNULL(H.Haber,0), Sdo_Ant = ISNULL(A.Sdo_Ant,0) 
		  From #Resumen_Cta C
			 LEFT JOIN #Resumen_Debe D  ON  C.Id_Proveedor = D.Id_Proveedor  
			 LEFT JOIN #Resumen_Haber H ON  C.Id_Proveedor = H.Id_Proveedor  
			 LEFT JOIN #Resumen_Sdo_Ant A ON  C.Id_Proveedor = A.Id_Proveedor  
print getdate()
--return
     
	    IF @pFiltrar_con_saldo = 1
		    BEGIN
				 IF @pIncluir_Deuda = 'T'
					SELECT c.Razon_Social,R.Id_Proveedor ,(Saldo)*-1 As Saldo,(Sdo_Ant)*-1 As Sdo_Ant
					,(Debe) As Debe,(Haber) As Haber
					FROM #Resumen_Cta R, Proveedores C, #ACTIVO A
					Where R.Id_Proveedor = C.Id_Proveedor 
					 AND C.Activo = A.Activo
					 AND R.Saldo <> 0
					 order by C.Razon_Social
                 IF @pIncluir_Deuda = 'D'
					SELECT c.Razon_Social,R.Id_Proveedor ,(Saldo)*-1 As Saldo,(Sdo_Ant)*-1 As Sdo_Ant
					,(Debe) As Debe,(Haber) As Haber
					FROM #Resumen_Cta R, Proveedores C, #ACTIVO A
					Where R.Id_Proveedor = C.Id_Proveedor 
					 AND C.Activo = A.Activo
					 AND R.Saldo  < 0
					 order by C.Razon_Social
                 IF @pIncluir_Deuda = 'A'
					SELECT c.Razon_Social,R.Id_Proveedor ,(Saldo)*-1 As Saldo,(Sdo_Ant)*-1 As Sdo_Ant
					,(Debe) As Debe,(Haber) As Haber
					FROM #Resumen_Cta R, Proveedores C, #ACTIVO A
					Where R.Id_Proveedor = C.Id_Proveedor 
					 AND C.Activo = A.Activo
					 AND R.Saldo >  0
					 order by C.Razon_Social
					 
		     END
 		 ELSE

 			SELECT c.Razon_Social,r.Id_Proveedor,(Saldo)*-1 As Saldo,(Sdo_Ant)*-1 As Sdo_Ant
			,(Debe) As Debe,(Haber) As Haber
			FROM #Resumen_Cta R, Proveedores C, #ACTIVO A
			Where R.Id_Proveedor = C.Id_Proveedor 
			    AND C.Activo = A.Activo
			order by C.Razon_Social
			
--print getdate()
--return 

        DROP TABLE #Resumen_Sdo_Ant
		DROP TABLE #Resumen_Cta
		DROP TABLE #Resumen_DEBE
        DROP TABLE #Resumen_HABER
        DROP TABLE #UN
		DROP TABLE #ACTIVO
END

/*

EXEC dbo.CPJ_Proveedores_ResumenCta   '{
			"FechaDesde":"20250101",
			"FechaHasta":"20260309",
		    "Filtrar_con_saldo":"1",
			"Proveedores_activos":"1",
			"Incluir_Deuda":"A",
			"Id_Unid_Negocio":""
		}'

select imp_total,* from cbtes where id_proveedor = 52


select count(*) from transacciones

*/
GO

 

CREATE PROCEDURE [dbo].[CPJ_Proveedores_ResumenCta_Detalle] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON
/*Parametros*/

DECLARE 	@pFechaDesde			DATETIME,
			@pFechaHasta			DATETIME,
			@pId_Unid_Negocio       VARCHAR(10),
			@pFiltrar_con_saldo     TINYINT,
			@pProveedores_activos   TINYINT,
            @pId_Proveedor           INT

SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
SET @pFechaDesde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaDesde')),GETDATE())
SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())
SET @pFiltrar_con_saldo			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Filtrar_con_saldo')),0)
SET @pProveedores_activos	    = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Proveedores_activos')),0)
SET @pId_Proveedor		    	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Proveedor')),0)

/*Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Trans_Rec		INT
		,@CursorOpen        INT
		,@Flag_Cbte_Tipo	SMALLINT
		,@Periodo           DATE 
		,@Id_sucursal	    SMALLINT
		,@Venta_Total       DECIMAL(16,2)

					
BEGIN 

    SELECT ID_UNID_NEGOCIO INTO #UN FROM Empresas_Unid_Negocios

    IF CAST(@pId_Unid_Negocio as int) <> 0
       DELETE #UN WHERE ID_UNID_NEGOCIO <> @pId_Unid_Negocio 


	CREATE TABLE #ACTIVO (ACTIVO TINYINT)
    INSERT INTO #ACTIVO (ACTIVO) VALUES (1)

	IF @pProveedores_activos <> 1
	  INSERT INTO #ACTIVO (ACTIVO) VALUES (0)


		Select F.Fecha,dbo.CF_Descrip_Cbte(F.Id_Trans) as Descripcion ,F.Fecha_Venc,F.Id_Trans,F.Id_Moneda,F.Cotizacion,F.IMP_TOTAL*f.cotizacion AS Haber,Cast(0 as decimal(16,2)) AS Debe ,Cast(0 as decimal(16,2)) AS Saldo
		Into #Resumen_Cta
		 from Cbtes_Tipos T, Proveedores c, Cbtes F, #UN U
		 where C.Id_Proveedor = f.Id_Proveedor
		 AND C.Id_Proveedor = @pId_Proveedor
		 and f.id_tipo_cbte = t.id_tipo_cbte
		 AND T.Id_Unid_Negocio = U.Id_Unid_Negocio
		 and t.Compromete_Compras in (1) 
		 and f.id_estado_cbte  in (1,2,4)
		 AND F.FECHA >= @pFechaDesde 
	  	 AND F.FECHA < dateadd(dd,1,@pFechaHasta)

 
		Select F.FECHA,dbo.CF_Descrip_Cbte(F.Id_Trans) as Descripcion,F.Fecha_Venc,F.ID_TRANS,F.ID_MONEDA,F.COTIZACION,0 AS Haber,Abs(F.IMP_TOTAL*f.cotizacion) AS Debe,0 AS SALDO
		Into #Resumen_nc
		 from Cbtes_Tipos T, Proveedores c, Cbtes F, #UN U
		 where C.Id_Proveedor = f.Id_Proveedor
		 AND C.Id_Proveedor = @pId_Proveedor
		 AND T.Id_Unid_Negocio = U.Id_Unid_Negocio
		 and f.id_tipo_cbte = t.id_tipo_cbte
		 and t.Compromete_Compras in (-1) 
		 and f.id_estado_cbte  in (1,2,4)
		 AND F.FECHA >= @pFechaDesde 
	     AND F.FECHA < dateadd(dd,1,@pFechaHasta)

		Select F.FECHA,dbo.CF_Descrip_Cbte(F.Id_Trans) as Descripcion,F.Fecha_Venc,F.ID_TRANS,F.ID_MONEDA,F.COTIZACION,0 AS Haber,F.IMP_TOTAL*f.cotizacion AS Debe,0 AS SALDO
		Into #Resumen_REC
		 from Cbtes_Tipos T, Proveedores c, Cbtes F, #UN U 
		 where C.Id_Proveedor = f.Id_Proveedor
		 AND C.Id_Proveedor = @pId_Proveedor
		 AND T.Id_Unid_Negocio = U.Id_Unid_Negocio
		 and f.id_tipo_cbte = t.id_tipo_cbte
		 and t.Compromete_Pagos in (1,-1) 
		 and f.id_estado_cbte  in (1,2,4)
		 AND F.FECHA >= @pFechaDesde 
		 AND F.FECHA < dateadd(dd,1,@pFechaHasta)

        INSERT INTO #Resumen_Cta SELECT * FROM #Resumen_nc
	    INSERT INTO #Resumen_Cta SELECT * FROM #Resumen_Rec

		DECLARE @Debe DECIMAL(16,2)
		DECLARE @Haber DECIMAL(16,2)
		DECLARE @Saldo DECIMAL(16,2)

		SET @Saldo = 0
		DECLARE Cur_Saldo CURSOR FOR
			 SELECT Id_Trans,Debe,Haber FROM #Resumen_Cta order by FECHA,ID_TRANS

		OPEN Cur_Saldo 
		FETCH NEXT FROM Cur_Saldo INTO @Id_trans,@debe,@haber
		WHILE @@FETCH_STATUS=0
		BEGIN
			SET @Saldo = @Saldo + @debe - @haber
			UPDATE #Resumen_Cta SET Saldo = @Saldo WHERE Id_trans = @Id_trans
			FETCH NEXT FROM Cur_Saldo INTO @Id_trans,@debe,@haber
		END
		CLOSE Cur_Saldo
		DEALLOCATE Cur_Saldo

		SELECT * FROM #Resumen_Cta ORDER BY FECHA,ID_TRANS


		DROP TABLE #Resumen_Cta
        DROP TABLE #UN
		DROP TABLE #Resumen_nc
		DROP TABLE #ACTIVO
		DROP TABLE #Resumen_Rec
 END

/*

EXEC dbo.CPJ_Proveedores_ResumenCta_Detalle   '{
			"FechaDesde":"20210101",
			"FechaHasta":"20250930",
		    "Filtrar_con_saldo":"1",
			"Proveedores_activos":"1",
			"Id_Proveedor":"2048",
			"Id_Unid_Negocio":""
		}'

