CREATE PROCEDURE CPJ_Seg_Audit @pJsonRecibido VARCHAR(MAX)
AS 

SET NOCOUNT ON
DECLARE	@pId_Seg_User_Audit	BIGINT,
		@pProcedimiento		VARCHAR(50) ,
		@pNombre_Vent		VARCHAR(1000) ,
		@pId_Usuario		SMALLINT ,
		@pAccion			TINYINT ,
		@pId_Trans			INT ,
		@pId_Cliente		INT ,
		@pId_Producto		VARCHAR(14) ,
		@pId_Proveedor		INT ,
		@pId_Valor			INT ,
		@pId_Parametro		VARCHAR(20) ,
		@pAccion_Salida		TINYINT ,
		@pValor_Parametro	VARCHAR(1000) ,
		@pFlag_QA			CHAR(1) ,
		@pAnalisis			VARCHAR(30) ,
		@pId_Asiento		INT,
		@pFecha_Venc		DATETIME ,
		@pFecha_Caducidad	DATETIME ,
		@pLote				VARCHAR(20) 

DECLARE	@query				VARCHAR(8000),
		@Id_Seg_User_Audit_String VARCHAR(20)


SET @Id_Seg_User_Audit_String		= ISNULL(CONVERT(VARCHAR(20),		dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Seg_User_Audit')),'')
IF ISNUMERIC(@Id_Seg_User_Audit_String) = 1
	SET @pId_Seg_User_Audit		= ISNULL(CONVERT(BIGINT,@Id_Seg_User_Audit_String),0)
ELSE
	SET @pId_Seg_User_Audit		= 0
	
SET @pProcedimiento			= ISNULL(CONVERT(VARCHAR(100),	dbo.CF_JSON_VALUE(@pJsonRecibido,'Procedimiento')),'')
SET @pNombre_Vent			= ISNULL(CONVERT(VARCHAR(100),	dbo.CF_JSON_VALUE(@pJsonRecibido,'Nombre_Vent')),'')
SET @pId_Usuario			= ISNULL(CONVERT(SMALLINT,		dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Usuario')),0)
SET @pAccion				= ISNULL(CONVERT(TINYINT,		dbo.CF_JSON_VALUE(@pJsonRecibido,'Accion')),0)
SET @pId_Trans				= ISNULL(CONVERT(INT,			dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Trans')),0)
SET @pId_Cliente			= ISNULL(CONVERT(INT,			dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')),0)
SET @pId_Producto			= ISNULL(CONVERT(VARCHAR(14),	dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Producto')),'')
SET @pId_Proveedor			= ISNULL(CONVERT(INT,			dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Proveedor')),0)
SET @pId_Valor				= ISNULL(CONVERT(INT,			dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Valor')),0)
SET @pId_Parametro			= ISNULL(CONVERT(VARCHAR(20),	dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Parametro')),'')
SET @pAccion_Salida			= ISNULL(CONVERT(TINYINT,		dbo.CF_JSON_VALUE(@pJsonRecibido,'Accion_Salida')),0)
SET @pValor_Parametro		= ISNULL(CONVERT(VARCHAR(1000),	dbo.CF_JSON_VALUE(@pJsonRecibido,'Valor_Parametro')),'')
SET @pFlag_QA				= ISNULL(CONVERT(CHAR(1),		dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_QA')),'')
SET @pAnalisis				= ISNULL(CONVERT(VARCHAR(30),	dbo.CF_JSON_VALUE(@pJsonRecibido,'Analisis')),'')
SET @pId_Asiento			= ISNULL(CONVERT(VARCHAR(30),	dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Asiento')),'')
SET @pFecha_Venc			= CONVERT(DATETIME,				dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Venc'))
SET @pFecha_Caducidad		= CONVERT(DATETIME,				dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Caducidad'))
SET @pLote					= ISNULL(CONVERT(VARCHAR(20),	dbo.CF_JSON_VALUE(@pJsonRecibido,'Lote')),'')



IF @pId_Seg_User_Audit = 0
BEGIN
	INSERT INTO Seg_Usuarios_Audit (
			Fecha,Procedimiento,Nombre_Vent,Id_Usuario,Accion,Id_Trans,Id_Cliente,Id_Producto,Id_Proveedor,Id_Valor			
			,Id_Parametro,Accion_Salida,Valor_Parametro,Flag_QA,Analisis,Id_Asiento,Fecha_Venc,Fecha_Caducidad,Lote)
			VALUES (
			GETDATE(),@pProcedimiento,@pNombre_Vent,@pId_Usuario,@pAccion,@pId_Trans,@pId_Cliente,@pId_Producto,@pId_Proveedor,@pId_Valor			
			,@pId_Parametro,@pAccion_Salida,@pValor_Parametro,@pFlag_QA,@pAnalisis,@pId_Asiento,@pFecha_Venc,@pFecha_Caducidad,@pLote)
	SELECT @@IDENTITY
	RETURN 0
END
ELSE
BEGIN
	UPDATE Seg_Usuarios_Audit SET Fecha_Salida = GETDATE() , Accion_Salida = @pAccion_Salida 
		WHERE Id_Seg_User_Audit = @pId_Seg_User_Audit
	SELECT @pId_Seg_User_Audit
	RETURN 0
END



RETURN
	

	/*

EXEC CPJ_Seg_Audit '{	"Id_Seg_User_Audit":"",
						"Procedimiento":"Main",
						"Nombre_Vent":"",
						"Id_Usuario":"",
						"Accion":"",
						"Id_Trans":"",
						"Id_Cliente":"",
						"Id_Producto":"",
						"Id_Proveedor":"",
						"Id_Valor":"",
						"Id_Parametro":"",
						"Accion_Salida":"",
						"Valor_Parametro":"",
						"Flag_QA":"",
						"Analisis":"",
						"Id_Asiento":"0",
						"Fecha_Venc":"",
						"Fecha_Caducidad":"",
						"Lote":""}'



	*/
GO


CREATE PROCEDURE CPJ_Seg_User_Fav		@pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*Variables recibidas por parßmetro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT,
		@pModoDebug				TINYINT,
		@pAccion				CHAR(1),  --A=ADD    C=CHANGE     D=DELETE
		@pId_Usuario			SMALLINT,
		@pId_Modulo				SMALLINT,
		@pId_Menu				SMALLINT,
		@pOrden					SMALLINT,
		@pFlag_Grupo			TINYINT,
		@pDescripcion			VARCHAR(250),
		@pId_Favorito_Padre		INT,
		@pId_Favorito			INT


SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pAccion				= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJson,'Accion')), '')
SET @pId_Usuario			= CONVERT(SMALLINT,dbo.CF_JSON_VALUE(@pJson,'Id_Usuario'))
SET @pId_Modulo				= CONVERT(SMALLINT,dbo.CF_JSON_VALUE(@pJson,'Id_Modulo'))
SET @pId_Menu				= CONVERT(SMALLINT,dbo.CF_JSON_VALUE(@pJson,'Id_Menu'))
SET	@pOrden					= CONVERT(SMALLINT,dbo.CF_JSON_VALUE(@pJson,'Orden'))
SET	@pFlag_Grupo			= CONVERT(TINYINT,dbo.CF_JSON_VALUE(@pJson,'Flag_Grupo'))
SET	@pDescripcion			= CONVERT(VARCHAR(250),dbo.CF_JSON_VALUE(@pJson,'Descripcion'))
SET @pId_Favorito_Padre		= CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Favorito_Padre'))
SET @pId_Favorito			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Favorito')),0)


BEGIN TRY
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Seg_User_Fav'
		PRINT 'Parßmetros: '+ @pJson  
	END
	/*===================================================================*/	

	IF UPPER(@pAccion) NOT IN ('A','C','D') RAISERROR ('Parameter "Accion" must be A C D (ADD,CHANGE,DELETE)', 16,  1 )

	IF UPPER(@pAccion) = 'A'
	BEGIN
		INSERT INTO Seg_User_Fav (Id_Usuario,Id_Modulo,Id_Menu,Orden,Flag_Grupo,Descripcion,Id_Favorito_Padre)
			VALUES (@pId_Usuario,@pId_Modulo,@pId_Menu,@pOrden,@pFlag_Grupo,@pDescripcion,@pId_Favorito_Padre)
	END

	IF UPPER(@pAccion) = 'C'
	BEGIN
		IF @pId_Favorito = 0 RAISERROR ('Parameter "Id_Favorito" can not be 0', 16,  1 )
		UPDATE Seg_User_Fav SET Orden =  @pOrden , Flag_Grupo = @pFlag_Grupo , Descripcion = @pDescripcion, Id_Usuario = @pId_Usuario, Id_Modulo = @pId_Modulo, Id_Menu = @pId_Menu 
			WHERE  Id_Favorito = @pId_Favorito
			
	END

 	IF UPPER(@pAccion) = 'D'
	BEGIN
		IF @pId_Favorito = 0 RAISERROR ('Parameter "Id_Favorito" can not be 0', 16,  1 )
		DELETE Seg_User_Fav WHERE Id_Favorito = @pId_Favorito
	END




	/*===================================================================*/	

	IF @pFlagUsarTrans <> 0 COMMIT

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,''				AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Seg_User_Fav'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  ROLLBACK

	RETURN 9999
END CATCH

RETURN 0
GO


Create PROCEDURE [dbo].[CPJ_Socios_Mora_Temprana]	@pJsonRecibido VARCHAR(8000)
AS

SET NOCOUNT ON

DECLARE @pFechaDesde			DATETIME,
		@pFechaHasta			DATETIME,
		@pId_Unid_Negocio       VARCHAR(10),
		@pClientes_activos      TINYINT,
		@pUsuario               INT,
		@pId_Familia            INT,
		@pId_Tipo_Cli           INT,
		@pId_Producto           VARCHAR(14),
        @pOrden                 CHAR(10)

		DECLARE @Sql		    VARCHAR(MAX)
		DECLARE @SqlSelect		VARCHAR(MAX)
		DECLARE @SqlFrom	    VARCHAR(MAX)
		DECLARE @SqlWhere		VARCHAR(MAX)
		DECLARE @SqlOrden   	VARCHAR(MAX)
		DECLARE @sqlgroup       VARCHAR(MAX)
		DECLARE @SqlHaving      VARCHAR(MAX)

		/*Fin Variables Locales*/
		SET ANSI_NULLS ON;
        SET QUOTED_IDENTIFIER ON;   


		SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
		SET @pFechaDesde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaDesde')),GETDATE())
		SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())
		SET @pClientes_activos			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Clientes_activos')),0)
		SET @pUsuario		        	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Usuario')),0)
		SET @pOrden				     	= ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Orden')),'')
		SET @pId_Familia				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Familia')),0)
		SET @pId_Producto				= ISNULL(CONVERT(CHAR(14), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Producto')),'')
		SET @pId_Tipo_Cli				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Tipo_Cli')),0)
 

     Select * Into #Prod_Familias From Prod_Familias
	 If @pId_Familia <> 0
	     DELETE #Prod_Familias WHERE Id_Familia <>@pId_Familia 

     Select * Into #Clientes_Tipos From Clientes_Tipos
	 If @pId_Tipo_Cli <> 0
	     DELETE #Clientes_Tipos WHERE Id_Tipo_Cli <> @pId_Tipo_Cli 

 
 Select K.Activo,K.Id_cliente, K.Id_Cliente_Externo AS Nro_Socio, K.Razon_Social, K.Id_Tipo_Doc, K.Doc_Nro, K.Fecha_Nac
      , dbo.CF_Edad_Persona_A_UnaFecha(K.Fecha_Nac,GETDATE()) as Edad
      , K.Sexo 
	  , CASE ISNULL(K.Id_Cliente_Ref,0)
	         WHEN 0 THEN 'TITULAR'
	         ELSE 'INTEGRANTE'
	    END AS Grupo
	  , CASE ISNULL(K.Id_Cliente_Ref,0)
	         WHEN 0 THEN K.Razon_Social
	         ELSE TIT.Razon_Social
	    END AS Titular
	  , K.Id_Tipo_cli,CT.Descripcion as Categoria
	  , K.Ult_Cuota_Paga
	  , convert(varchar,K.Email) as Email
	  , convert(varchar,ISNULL(K.Tel_Movil,'')) AS Telefono
	  , K.Fecha_Alta,ISNULL(K.Fecha_Baja,'') AS Fecha_Baja
	  , K.Id_Motivo_Est
	  , M.Descripcion AS Motivo_Baja 
	  , isnull(F.Descripcion,'') as Actividad
	  , I.Fecha_QA 
 INTO #Reporte
 From Clientes K
		LEFT JOIN Cbtes_Items I ON I.Id_Cliente  = K.Id_Cliente AND I.Id_Cliente <> 0
		JOIN Cbtes C  ON C.Id_Trans = I.Id_Trans AND C.Id_Estado_Cbte Not In (0,3)
		JOIN Cbtes_tipos T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte And T.Compromete_Factura in (1,-1)
		JOIN Productos P   ON P.Id_Producto  = I.Id_Producto 
        JOIN #Prod_Familias F  ON F.Id_Familia = P.Id_Familia
		JOIN Clientes TIT  ON TIT.Id_Cliente = K.Id_Cliente_Ref
		JOIN #Clientes_Tipos CT ON CT.Id_Tipo_Cli = K.Id_Tipo_Cli
		JOIN Estados_Motivos M ON M.Id_Motivo_Estado = K.Id_Motivo_Est
    Where k.Ult_Cuota_Paga >= @pFechaDesde 
	      AND k.Ult_Cuota_Paga < dateadd(dd,1,@pFechaHasta)

	SET ANSI_NULLS ON;
    SET QUOTED_IDENTIFIER ON; 

	SELECT DISTINCT Activo, Id_Cliente, Nro_Socio, Razon_Social, Id_Tipo_Doc,
					Doc_Nro, Fecha_Nac, Edad, Sexo, Grupo,
					Titular, Id_Tipo_cli, Categoria, Ult_Cuota_Paga, Email,
					Telefono, Fecha_Alta, Fecha_Baja, Id_Motivo_Est, Motivo_Baja
					INTO #CTE_Claves
	FROM #Reporte

	SELECT  K.Activo,	K.Id_Cliente,    K.Nro_Socio,   K.Razon_Social,		K.Id_Tipo_Doc,
			K.Doc_Nro,  convert(date,K.Fecha_Nac) as Fecha_Nac,	 K.Edad,		K.Sexo,				K.Grupo,    
			K.Titular,	K.Id_Tipo_cli,   K.Categoria,   convert(date,K.Ult_Cuota_Paga) as Ult_Cuota_Paga,   K.Email,
			K.Telefono, convert(date,K.Fecha_Alta) as Fecha_Alta,    convert(date,K.Fecha_Baja) as Fecha_Baja,  K.Id_Motivo_Est,    K.Motivo_Baja, 
		STUFF((
			SELECT TOP 20 ', ' +   REPLACE(
									REPLACE(
										REPLACE(
											REPLACE(LTRIM(RTRIM(R.Actividad)), CHAR(10), ''),
										CHAR(13), ''),
									CHAR(9), ''),
								CHAR(160), '')  
			+ ' '+ LEFT(CONVERT(CHAR(8), R.Fecha_QA, 112), 6)
			FROM #Reporte AS R
			WHERE R.Id_Cliente = K.Id_Cliente ORDER BY Fecha_QA DESC
			FOR XML PATH(''), TYPE
		).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS Actividad
		INTO #Consulta
	FROM #CTE_Claves  K;


		SET @Sql	    = ''
		SET @SqlSelect	= ''
		SET @SqlFrom	= ''
		SET @SqlWhere	= ''
		SET @SqlOrden	= ''
		SET @sqlgroup   = ''
		SET @SqlHaving  = ''

      SET @SqlSelect	= 'SELECT * FROM #CONSULTA'
	  SET @SqlWhere	= 'WHERE 1=1 '

	  IF @pClientes_activos = 1
	     SET @SqlWhere	+= ' AND ACTIVO = 1 '
      
      IF @pOrden = 'N'
	     SET @SqlOrden	= 'ORDER BY Razon_Social'

      IF @pOrden = 'C'
	     SET @SqlOrden	= 'ORDER BY Nro_Socio'

	  SET @Sql = @SqlSelect + ' ' + @SqlWhere + ' ' + @SqlOrden

	  print @sql

	  EXEC(@sql) 

Drop Table #Reporte
Drop Table #Consulta
Drop Table #Prod_Familias


