CREATE PROCEDURE [dbo].[CPJ_Stock] @pJson VARCHAR(8000)
AS
SET NOCOUNT ON

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug						TINYINT
DECLARE @pId_Familia					INT
DECLARE @pId_Proveedor					INT
DECLARE @pDescripcion					CHAR(100)
DECLARE @pId_Producto					CHAR(14)
DECLARE @pCon_Stock						TINYINT
DECLARE @pCon_Precio					TINYINT
DECLARE @pFlag_Activo					TINYINT
DECLARE @pFlag_Vendible					TINYINT
DECLARE @pFlag_Critico					TINYINT
DECLARE @pFlag_Agrupa_Padre				TINYINT
DECLARE @pFecha_Desde					VARCHAR(10)
DECLARE @pFecha_Hasta					VARCHAR(10)

SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Familia				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Familia')),0)
SET @pId_Proveedor				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Proveedor')),0)
SET @pDescripcion				= ISNULL(CONVERT(CHAR(100), dbo.CF_JSON_VALUE(@pJson,'Descripcion')), '')
SET @pId_Producto				= ISNULL(CONVERT(CHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), '')
SET @pCon_Stock					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Con_Stock')),0)
SET @pCon_Precio				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Con_Precio')),0)
SET @pFlag_Activo				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Activo')),0)
SET @pFlag_Vendible				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Vendible')),0)
SET @pFlag_Critico				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Critico')),0)
SET @pFlag_Agrupa_Padre			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Agrupa_Padre')),0)
SET @pFecha_Desde				= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Fecha_Desde')),'')
SET @pFecha_Hasta				= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Fecha_Hasta')),'')
/*FIN Variables recibidas por parametro a traves del JSON*/


/*Declaracion Variables Locales*/
DECLARE @Sql					VARCHAR(MAX)
/*Fin de Declaraciones Variables Locales */




IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a Stored Procedure: CPJ_Stock'
	PRINT 'Parametros: '
	PRINT 'Id_Familia: ' + CONVERT(VARCHAR(10), @pId_Familia)
	PRINT 'Id_Proveedor: ' + CONVERT(VARCHAR(10), @pId_Proveedor)
	PRINT 'Descripcion: ' + @pDescripcion
	PRINT 'Id_Producto: ' + @pId_Producto
	PRINT 'Con_Stock: ' + CONVERT(VARCHAR(1), @pCon_Stock)
	PRINT 'Con_Precio: ' + CONVERT(VARCHAR(1), @pCon_Precio)
	PRINT 'Flag_Activo: ' + CONVERT(VARCHAR(1), @pFlag_Activo)
	PRINT 'Flag_Vendible: ' + CONVERT(VARCHAR(1), @pFlag_Vendible)
	PRINT 'Flag_Critico: ' + CONVERT(VARCHAR(1), @pFlag_Critico)
	PRINT 'Flag_Agrupa_Padre: ' + CONVERT(VARCHAR(1), @pFlag_Agrupa_Padre)
	PRINT 'Fecha_Desde: ' + CONVERT(VARCHAR(10), @pFecha_Desde)
	PRINT 'Fecha_Hasta: ' + CONVERT(VARCHAR(10), @pFecha_Hasta)
END


SELECT P.ID_PRODUCTO, P.ID_PRODUCTO_PADRE, B.COD_BARRA INTO #STOCK FROM PRODUCTOS P, Productos_CBarras B WHERE 1=0
		
ALTER Table #STOCK  ADD
			DESCRIPCION	   	VARCHAR(150),
			STK_ING			INT,
            STK_PED			INT,	
			TOTAL    	   	INT,
			SA				INT,
			STK_CRITICO		INT


SELECT Id_Producto, Cantidad INTO #Ingresos FROM Cbtes_Items WHERE 1 = 0
SELECT Id_Producto, Cantidad INTO #Saldo_Anterior FROM Cbtes_Items WHERE 1 = 0
SELECT Id_Producto, Cantidad INTO #Egresos FROM Cbtes_Items WHERE 1 = 0

BEGIN 

SELECT ID_PROVEEDOR INTO #PROVE FROM PROVEEDORES WHERE Activo = 1
SELECT ID_FAMILIA INTO #FAMILIAS FROM Prod_Familias 

IF @pId_Familia <> 0
BEGIN
	DELETE #FAMILIAS WHERE ID_FAMILIA <> @pId_Familia
END

IF @pId_Proveedor <> 0
BEGIN
	DELETE #PROVE WHERE ID_PROVEEDOR <> @pId_Proveedor
END 

SET @Sql = 'INSERT INTO #STOCK
			SELECT	P.ID_PRODUCTO AS ID_PRODUCTO,
					P.ID_PRODUCTO_PADRE AS ID_PRODUCTO_PADRE,
					ISNULL(B.COD_BARRA, '''') AS COD_BARRA,
					P.DESCRIPCION_DETALLADA AS DESCRIPCION,
					0 AS STK_ING,
					0 AS STK_PED,
					0 AS TOTAL,
					0 AS SA,
					ISNULL(P.Stock_Critico, 0) AS STK_CRITICO
				FROM Productos P
						JOIN #FAMILIAS F ON P.ID_FAMILIA = F.ID_FAMILIA
						JOIN #PROVE K ON P.Id_Proveedor = K.Id_Proveedor
						LEFT JOIN Productos_CBarras B ON B.Id_Producto = P.Id_Producto
						
				WHERE P.Maneja_Stock = 1
						AND NOT EXISTS (
								SELECT 1 
									FROM Productos P2
										WHERE P2.Id_Producto_Padre = P.Id_Producto
							)
					AND P.Tipo <> ''L''' 

IF(@pId_Producto <> '')
BEGIN
	SET @Sql += ' AND (P.Id_Producto = ''' + RTRIM(LTRIM(@pId_Producto)) + ''' OR P.Id_Producto_Padre = ''' + RTRIM(LTRIM(@pId_Producto)) + ''')'
END

IF(@pFlag_Activo = 1)
BEGIN
	SET @Sql += ' AND P.Activo = 1'
END

IF(@pFlag_Vendible = 1)
BEGIN
	SET @Sql += ' AND P.Vendible = 1'
END

IF(@pFlag_Critico = 1)
BEGIN
	SET @Sql += ' AND P.Stock_Critico IS NOT NULL AND P.Stock_Critico > 0'
END

IF(@pDescripcion <> '')
BEGIN
	SET @Sql += ' AND P.Descripcion_Detallada LIKE ''%' + RTRIM(LTRIM(@pDescripcion)) + '%'''
END

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Query #Stock: '
	PRINT @Sql
END

EXEC(@Sql)


-- Saldo Anterior
IF(@pFecha_Desde <> '')
BEGIN
	SET @Sql = 'INSERT INTO #Saldo_Anterior SELECT  I.ID_PRODUCTO,sum(i.Cantidad * t.compromete_Stock) AS SA
					FROM cbtes c, cbtes_tipos t, cbtes_items i, #STOCK S
						where c.id_tipo_cbte  = t.id_tipo_cbte
						and I.Id_Trans = c.Id_Trans
						And c.id_Estado_Cbte <> 3
						and I.id_Producto = S.Id_Producto 
						And t.compromete_Stock in (1,-1)
						AND T.Tipo <> ''T''
						AND I.FLAG_QA <> ''R''
						AND C.Fecha < ''' + @pFecha_Desde + '''
						GROUP BY I.ID_PRODUCTO '
		  
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Query #Saldo_Anterior: '
		PRINT @Sql
	END

	EXEC(@Sql)
END



-- Calcula los ingresos de los productos seleccionados
SET @Sql = 'INSERT INTO #Ingresos SELECT  I.ID_PRODUCTO,sum(i.Cantidad) AS CANTIDAD
				FROM cbtes c, cbtes_tipos t, cbtes_items i, #STOCK S
					where c.id_tipo_cbte  = t.id_tipo_cbte
					and I.Id_Trans = c.Id_Trans
					And c.id_Estado_Cbte <> 3
					and I.id_Producto = S.Id_Producto 
					And t.compromete_Stock in (1)
					AND T.Tipo <> ''T''
					AND I.FLAG_QA <> ''R'''

IF(@pFecha_Desde <> '')
BEGIN
	SET @Sql += ' AND C.Fecha >= ''' + @pFecha_Desde + ''''
END

IF(@pFecha_Hasta <> '')
BEGIN
	SET @Sql += ' AND C.Fecha < DATEADD(DD, 1, ''' + @pFecha_Hasta + ''')'
END

SET @Sql += ' GROUP BY I.ID_PRODUCTO '
		  
IF(@pModoDebug = 1)
BEGIN
	PRINT 'Query #Ingresos: '
	PRINT @Sql
END

EXEC(@Sql)

	
-- Calcula los egresos de los productos seleccionados
SET @Sql = 'INSERT into #Egresos 
			SELECT I.ID_PRODUCTO, SUM(i.Cantidad) AS CANTIDAD
				FROM cbtes c, cbtes_tipos t, cbtes_items i, #STOCK S
				   where c.id_tipo_cbte  = t.id_tipo_cbte
				   and I.Id_Trans = c.Id_Trans
				   And c.id_Estado_Cbte <> 3
				   and I.id_Producto = S.Id_Producto 
				   And t.Compromete_Stock in (-1)
				   AND T.Tipo <> ''T''
				   AND I.FLAG_QA <> ''R'''
	  

IF(@pFecha_Desde <> '')
BEGIN
	SET @Sql += ' AND C.Fecha >= ''' + @pFecha_Desde + ''''
END

IF(@pFecha_Hasta <> '')
BEGIN
	SET @Sql += ' AND C.Fecha < DATEADD(DD, 1, ''' + @pFecha_Hasta + ''')'
END
		
SET @Sql += ' GROUP BY I.ID_PRODUCTO '
		
IF(@pModoDebug = 1)
BEGIN
	PRINT 'Query #Egresoss: '
	PRINT @Sql
END

EXEC(@Sql)
        
IF(@pFecha_Desde <> '')
BEGIN
	UPDATE #STOCK SET SA 	= ISNULL(I.Cantidad,0) 	FROM #STOCK S, #Saldo_Anterior I 	WHERE S.ID_PRODUCTO =  I.ID_PRODUCTO
END
UPDATE #STOCK SET STK_ING 	= ISNULL(I.Cantidad,0)	FROM #STOCK S, #Ingresos I 			WHERE S.ID_PRODUCTO =  I.ID_PRODUCTO
UPDATE #STOCK SET STK_PED 	= ISNULL(C.Cantidad,0)	FROM #STOCK S, #Egresos C 			WHERE S.ID_PRODUCTO =  C.ID_PRODUCTO
UPDATE #STOCK SET TOTAL 	= STK_ING - STK_PED + SA

--		/*FIN */

END 

IF(@pCon_Stock = 1)
BEGIN
	DELETE FROM #STOCK WHERE TOTAL = 0 AND SA = 0 AND STK_ING = 0 AND STK_PED = 0 
END

IF(@pFlag_Critico = 1)
BEGIN
	DELETE FROM #STOCK WHERE SA + TOTAL > STK_CRITICO
END

IF(@pFlag_Agrupa_Padre = 1)
BEGIN

	-- Inserta a #STOCK los producuctos padre sumando los valores de los hijos
	INSERT INTO #STOCK
		SELECT PP.Id_Producto, NULL, ISNULL(B.Cod_Barra, ''), PP.Descripcion_Detallada, SUM(P.STK_ING) AS STK_ING, SUM(P.STK_PED) AS STK_PED, SUM(P.TOTAL) AS TOTAL, SUM(P.SA) AS SA, 0 AS STK_CRITICO
	FROM Productos PP
	JOIN #STOCK P ON P.Id_Producto_Padre = PP.Id_Producto AND P.Id_Producto_Padre IS NOT NULL
	LEFT JOIN Productos_CBarras B ON B.Id_Producto = PP.Id_Producto
	WHERE PP.Id_Producto <> ''
	GROUP BY PP.Id_Producto, PP.Descripcion_Detallada, B.Cod_Barra

END

SELECT * FROM #STOCK ORDER BY DESCRIPCION

 DROP TABLE #STOCK
 DROP TABLE #Ingresos
 DROP TABLE #Egresos
 DROP TABLE #Saldo_Anterior
 DROP TABLE #PROVE
 DROP TABLE #FAMILIAS

/* 
	EXEC CPJ_Stock '{"ModoDebug":1,"Flag_Activo":"1","Flag_Agrupa_Padre":"1"}'

	EXEC CPJ_Stock '{"ModoDebug":1}'
	EXEC CPJ_Stock '{"ModoDebug":1,"Id_Familia":"2"}'
	EXEC CPJ_Stock '{"ModoDebug":1,"Descripcion":"AJEDREZ"}'
	EXEC CPJ_Stock '{"ModoDebug":1,"Id_Producto":"IND_0001_01"}'
	EXEC CPJ_Stock '{"ModoDebug":1,"Con_Stock":"1"}'
	EXEC CPJ_Stock '{"ModoDebug":1,"Con_Precio":"1"}'
	EXEC CPJ_Stock '{"ModoDebug":1,"Flag_Activo":"1"}'
	EXEC CPJ_Stock '{"ModoDebug":1,"Flag_Vendible":"1"}'
	EXEC CPJ_Stock '{"ModoDebug":1,"Flag_Critico":"1"}'
	EXEC CPJ_Stock '{"ModoDebug":1,"Flag_Agrupa_Padre":"1"}'
	EXEC CPJ_Stock '{"ModoDebug":1,"Fecha_Desde":"20250107"}'
	EXEC CPJ_Stock '{"ModoDebug":1,"Fecha_Hasta":"20250123"}'
*/
GO


CREATE PROCEDURE [dbo].[CPJ_Tag] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON

DECLARE  @pTabla		VARCHAR(100)
		,@pId_Usuario	INT
		,@pId			VARCHAR(100)
		,@pMarcar		TINYINT
		,@pFlag_Todos	TINYINT


SET @pTabla				= UPPER(ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Tabla')), ''))
SET @pId_Usuario		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Usuario')), 0)
SET @pId				= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id')),'')
SET @pMarcar			= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Marcar')), 0)
SET @pFlag_Todos		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Flag_Todos')), 0)


IF RTRIM(LTRIM(@pTabla)) = '' RETURN 1
IF RTRIM(LTRIM(@pId)) = '' AND @pFlag_Todos = 0 RETURN 1
IF @pId_Usuario = 0 RETURN 1

DECLARE @equate INT


IF UPPER(@pTabla) = 'PROD_FAMILIAS'
BEGIN
	SET @equate = 80
	IF @pMarcar = 0
	BEGIN	
	    IF @pFlag_Todos = 1
			DELETE TagFile_ WHERE Usr = @pId_Usuario AND Tbl = @equate
		ELSE					
			DELETE TagFile_ WHERE Usr = @pId_Usuario AND Tbl = @equate AND Ptr = @pId
	END
    ELSE
	BEGIN
	    IF @pFlag_Todos = 1
		BEGIN
			DELETE TagFile_ WHERE Usr = @pId_Usuario AND Tbl = @equate
			INSERT INTO TagFile_ (Usr,Tbl,Ptr,Val) 
			SELECT @pId_Usuario,@equate,Id_Familia,CONVERT(CHAR(10),Id_Familia) FROM Prod_Familias
		END
		ELSE
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM TagFile_ TAG WHERE TAG.Usr = @pId_Usuario AND TAG.Tbl = @equate AND TAG.Ptr = @pId) 
				INSERT INTO TagFile_ (Usr,Tbl,Ptr,Val) VALUES (@pId_Usuario,@equate,CONVERT(INT,@pId),CONVERT(CHAR(10),@pId))
		END
		
	END

END 

IF UPPER(@pTabla) = 'CBTES'
BEGIN
	SET @equate = 300
	IF @pMarcar = 0
	BEGIN	
	    IF @pFlag_Todos = 1
			DELETE TagFile_ WHERE Usr = @pId_Usuario AND Tbl = @equate
		ELSE					
			DELETE TagFile_ WHERE Usr = @pId_Usuario AND Tbl = @equate AND Ptr = @pId
	END
    ELSE
	BEGIN
	    IF @pFlag_Todos = 1
		BEGIN
			DELETE TagFile_ WHERE Usr = @pId_Usuario AND Tbl = @equate
			INSERT INTO TagFile_ (Usr,Tbl,Ptr,Val) 
			SELECT @pId_Usuario,@equate,Id_Trans,CONVERT(CHAR(10),Id_Trans) FROM Cbtes
		END
		ELSE
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM TagFile_ TAG WHERE TAG.Usr = @pId_Usuario AND TAG.Tbl = @equate AND TAG.Ptr = @pId) 
				INSERT INTO TagFile_ (Usr,Tbl,Ptr,Val) VALUES (@pId_Usuario,@equate,CONVERT(INT,@pId),CONVERT(CHAR(10),@pId))
		END
		
	END

END 


IF UPPER(@pTabla) = 'PRODUCTOS'
BEGIN
	SET @equate = 90
	IF @pMarcar = 0
	BEGIN	
	
	    IF @pFlag_Todos = 1
			DELETE TagFilePos_ WHERE Usr = @pId_Usuario AND Tbl = @equate
		ELSE					
			DELETE TagFilePos_ WHERE Usr = @pId_Usuario AND Tbl = @equate AND Pos = @pId
	END
    ELSE
	BEGIN
	
	    IF @pFlag_Todos = 1
		BEGIN
		
			DELETE TagFilePos_ WHERE Usr = @pId_Usuario AND Tbl = @equate
			INSERT INTO TagFilePos_ (Usr,Tbl,Pos,Val) 
			SELECT @pId_Usuario,@equate,Id_Producto,CONVERT(VARCHAR(14),Id_Producto) FROM Productos
		END
		ELSE
		BEGIN

			IF NOT EXISTS (SELECT 1 FROM TagFilePos_ TAG WHERE TAG.Usr = @pId_Usuario AND TAG.Tbl = @equate AND TAG.Pos = @pId) 
				INSERT INTO TagFilePos_ (Usr,Tbl,Pos,Val) VALUES (@pId_Usuario,@equate,@pId,CONVERT(VARCHAR(20),@pId))

		END
		
		
	END

END 


IF UPPER(@pTabla) = 'CAJAS_PERIODOS'
BEGIN
	SET @equate = 250
	IF @pMarcar = 0
	BEGIN	
	    IF @pFlag_Todos = 1
			DELETE TagFile_ WHERE Usr = @pId_Usuario AND Tbl = @equate
		ELSE					
			DELETE TagFile_ WHERE Usr = @pId_Usuario AND Tbl = @equate AND Ptr = @pId
	END
    ELSE
	BEGIN
	    IF @pFlag_Todos = 1
		BEGIN
			DELETE TagFile_ WHERE Usr = @pId_Usuario AND Tbl = @equate
			INSERT INTO TagFile_ (Usr,Tbl,Ptr,Val) 
			SELECT @pId_Usuario,@equate,Id_Periodo_Caja,CONVERT(CHAR(10),Id_Periodo_Caja) FROM Cajas_Periodos
		END
		ELSE
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM TagFile_ TAG WHERE TAG.Usr = @pId_Usuario AND TAG.Tbl = @equate AND TAG.Ptr = @pId) 
				INSERT INTO TagFile_ (Usr,Tbl,Ptr,Val) VALUES (@pId_Usuario,@equate,CONVERT(INT,@pId),CONVERT(CHAR(10),@pId))
		END
		
	END

END 



RETURN 0



/*

EXEC dbo.CPJ_Tag   '{
			"Id_Usuario":"-1",
			"Tabla":"Prod_Familias",
			"Id":"3",
			"Marcar":"1"
		}'

SELECT * FROM TagFile_ TAG WHERE TAG.Usr = -1 AND TAG.Tbl = 80

EXEC dbo.CPJ_Tag   '{
			"Id_Usuario":"-1",
			"Tabla":"Prod_Familias",
			"Id":"3",
			"Marcar":"0"
		}'

SELECT * FROM TagFile_ TAG WHERE TAG.Usr = -1 AND TAG.Tbl = 80


*/
GO


CREATE PROCEDURE [dbo].[CPJ_Tarjetas_Cuotas_Opciones] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 
/*
 * LOG VERSIONES:
 * 25/09/2025: Devuelve los datos Id_Cta_Banco y Tipo
*/


/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug				TINYINT
DECLARE @pImporte				DECIMAL(12,2)
DECLARE @pFlag_Web				TINYINT
DECLARE @pProductos				VARCHAR(MAX)


SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pImporte					= ISNULL(CONVERT(DECIMAL(12,2), dbo.CF_JSON_VALUE(@pJson,'Importe')), 0)
SET @pFlag_Web					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Flag_Web')), 0)
SET @pProductos					= ISNULL(dbo.CF_JSON_VALUE(@pJson,'Productos'), '')

/*FIN Variables recibidas por parametro a traves del JSON*/

/*Tabla de Retorno*/
CREATE TABLE #Tarjetas_Cuotas
(
Id_Tarjeta				VARCHAR(10),
Descripcion				VARCHAR(50),
Descrip_Corta			VARCHAR(100),
Cant_Cuotas				TINYINT,
Importe_Cuota			DECIMAL(12,2),
Imp_Total_Orig			DECIMAL(12,2),
Imp_Total_Con_Recargo	DECIMAL(12,2),
Porc_Recargo			DECIMAL(12,5),
Bin_Autorizados			VARCHAR(8000),
Cuota_Gateway			TINYINT,
Flag_Promo				TINYINT,
Id_Cta_Banco			SMALLINT,
Tipo					CHAR(1)
)
/*FIN Tabla de Retorno*/

CREATE TABLE #Valores_Tarjetas_Cred_Filtrada
(Id_Tarjeta				VARCHAR(10),
Descripcion				VARCHAR(50),
Descrip_Corta			VARCHAR(100),
Flag_Promo				TINYINT,
Id_Cta_Banco			SMALLINT,
Tipo					CHAR(1)
)

/*Variables Locales*/
DECLARE @SqlQry					NVARCHAR(1000)
DECLARE @Id_Tarjeta				VARCHAR(10)
DECLARE @Descripcion			VARCHAR(50)
DECLARE @Descrip_Corta			VARCHAR(100)
DECLARE @Cant_Cuotas			TINYINT
DECLARE @Cuota_Gateway			TINYINT
DECLARE @Importe_Cuota			DECIMAL(12,2)
DECLARE @Imp_Total_Orig			DECIMAL(12,2)
DECLARE @Imp_Total_Con_Recargo	DECIMAL(12,2)
DECLARE @Porc_Recargo			DECIMAL(12,5)
DECLARE @Cant_Total_Cuotas		INT
DECLARE @Coef_Adel				DECIMAL(7,5)
DECLARE @Coef_Venc				DECIMAL(7,5)
DECLARE @Bin_Autorizados		VARCHAR(8000)
DECLARE @Bin					VARCHAR(6)
DECLARE @CantFP					INT
DECLARE @CantProd				INT
DECLARE @Flag_Promo				TINYINT
DECLARE @Id_Cta_Banco			SMALLINT
DECLARE @Tipo					CHAR(1)
/*FIN Variables Locales*/

SET @Imp_Total_Orig = @pImporte

IF @pModoDebug = 1
BEGIN
	PRINT 'Ingreso a Stored Procedure: CPJ_Tarjetas_Cuotas_Opciones'
	PRINT 'Parametros:'
	PRINT 'pImporte: ' + CONVERT(VARCHAR(20), @pImporte) + '. pFlag_Web: ' + CONVERT(VARCHAR(10), @pFlag_Web)
END

IF @pFlag_Web = 1
BEGIN
	SET @SqlQry =	'INSERT INTO #Valores_Tarjetas_Cred_Filtrada
					(Id_Tarjeta, Descripcion, Descrip_Corta, Flag_Promo, Id_Cta_Banco, Tipo)
					SELECT Id_Tarjeta, ISNULL(Descripcion, ''''), ISNULL(Descrip_Corta, Descripcion), ISNULL(Flag_Promo, 0), ISNULL(Id_Cta_Banco, 0), ISNULL(Tipo, '''') FROM Valores_Tarjetas_Cred
					WHERE
					ISNULL(Activo, 0) = 1
					AND Id_Tarjeta <> ''''
					AND ISNULL(Flag_Web, 0) = 1' 
END
ELSE
BEGIN
	SET @SqlQry =	'INSERT INTO #Valores_Tarjetas_Cred_Filtrada
					(Id_Tarjeta, Descripcion, Descrip_Corta, Flag_Promo, Id_Cta_Banco, Tipo)
					SELECT Id_Tarjeta, ISNULL(Descripcion, ''''), ISNULL(Descrip_Corta, Descripcion), ISNULL(Flag_Promo, 0), ISNULL(Id_Cta_Banco, 0), ISNULL(Tipo, '''') FROM Valores_Tarjetas_Cred
					WHERE
					ISNULL(Activo, 0) = 1
					AND Id_Tarjeta <> '''''
END

IF @pModoDebug = 1
BEGIN
	PRINT '@SqlQry: ' + @SqlQry
END

EXEC sp_executesql @SqlQry

DECLARE curTarjetas CURSOR FOR
SELECT Id_Tarjeta, Descripcion, Descrip_Corta, Flag_Promo, Id_Cta_Banco, Tipo FROM #Valores_Tarjetas_Cred_Filtrada

OPEN curTarjetas
FETCH NEXT FROM curTarjetas INTO @Id_Tarjeta, @Descripcion, @Descrip_Corta, @Flag_Promo, @Id_Cta_Banco, @Tipo
WHILE @@FETCH_STATUS = 0
BEGIN

	SET @Cant_Total_Cuotas	= ISNULL((SELECT ISNULL(COUNT(*), 0) FROM Valores_Tarjetas_Cuotas WHERE Id_Tarjeta = @Id_Tarjeta), 0)
	IF @pModoDebug = 1
	BEGIN
		PRINT '@Id_Tarjeta: ' + @Id_Tarjeta + '. @Cant_Total_Cuotas: ' + CONVERT(VARCHAR(10), @Cant_Total_Cuotas)
	END

	/*05/05/2020 Se agrega @Bin_Autorizados*/
	SET @Bin_Autorizados	= ''
	
	DECLARE curTarjetasBins CURSOR FOR
	SELECT LTRIM(RTRIM(ISNULL(Bin, ''))) FROM Valores_Tarjetas_Bin WHERE Id_Tarjeta = @Id_Tarjeta

	OPEN curTarjetasBins
	FETCH NEXT FROM curTarjetasBins INTO @Bin
	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF @pModoDebug = 1
		BEGIN
			PRINT '@Bin: ' + @Bin
		END
		
		IF(@Bin_Autorizados = '')
		BEGIN
			SET @Bin_Autorizados = @Bin
		END
		ELSE
		BEGIN
			SET @Bin_Autorizados = @Bin_Autorizados + ',' + @Bin
		END		
		
		FETCH NEXT FROM curTarjetasBins INTO @Bin
	END
	CLOSE curTarjetasBins
	DEALLOCATE curTarjetasBins
	/*FIN 05/05/2020 Se agrega @Bin_Autorizados*/
	
	IF(@Cant_Total_Cuotas = 0)
	BEGIN
		SET @Cant_Cuotas			= 1
		SET @Porc_Recargo			= 0
		SET @Importe_Cuota			= @Imp_Total_Orig
		SET @Imp_Total_Con_Recargo	= @Imp_Total_Orig
		
		INSERT INTO #Tarjetas_Cuotas
		(Id_Tarjeta,			Descripcion,			Descrip_Corta,
		Cant_Cuotas,			Importe_Cuota,			Imp_Total_Orig,
		Imp_Total_Con_Recargo,	Porc_Recargo,			Bin_Autorizados,
		Cuota_Gateway,			Flag_Promo,				Id_Cta_Banco, 
		Tipo)

		VALUES
		(@Id_Tarjeta,			@Descripcion,		@Descrip_Corta,
		@Cant_Cuotas,			@Importe_Cuota,		@Imp_Total_Orig,
		@Imp_Total_Con_Recargo,	@Porc_Recargo,		@Bin_Autorizados,
		0,						@Flag_Promo,		@Id_Cta_Banco,
		@Tipo)
	END
	ELSE
	BEGIN
		DECLARE curCuotas CURSOR FOR
		SELECT Cuota, ISNULL(Coef_Adel, 1), ISNULL(Coef_Venc, 1),ISNULL(Cuota_Gateway,0) FROM Valores_Tarjetas_Cuotas
		WHERE
		Id_Tarjeta = @Id_Tarjeta

		OPEN curCuotas
		FETCH NEXT FROM curCuotas INTO @Cant_Cuotas, @Coef_Adel, @Coef_Venc, @Cuota_Gateway
		WHILE @@FETCH_STATUS = 0
		BEGIN
			/*17/04/2020 Por ahora se multiplica siempre por @Coef_Venc porque en Clarion lo hace a traves de VALORES:Tarjeta_Crit_Cuota = 'V' y aca no lo recibe. Hablado Gabriel y Victor*/
			IF @pModoDebug = 1
			BEGIN
				PRINT '@Cant_Cuotas: ' + CONVERT(VARCHAR(10), @Cant_Cuotas) + '. @Coef_Adel: ' + CONVERT(VARCHAR(10), @Coef_Adel) + '. @Coef_Venc: ' + CONVERT(VARCHAR(10), @Coef_Venc) + '. @Cuota_Gateway: ' + CONVERT(VARCHAR(10), @Cuota_Gateway) + '. @Bin_Autorizados: ' + @Bin_Autorizados
			END


			IF @Coef_Venc = 0 SET @Coef_Venc = 1
			SET @Importe_Cuota			= ROUND(((@Imp_Total_Orig * @Coef_Venc) /  @Cant_Cuotas) , 2, 1)
			
			IF(@Coef_Venc in ( 1,0))
			BEGIN
				SET @Porc_Recargo		= 0
			END
			ELSE
			BEGIN
				SET @Porc_Recargo		= ((@Coef_Venc - 1) * 100)
			END
			
			SET @Imp_Total_Con_Recargo	= @Importe_Cuota * @Cant_Cuotas
			
			INSERT INTO #Tarjetas_Cuotas
			(Id_Tarjeta,			Descripcion,			Descrip_Corta,
			Cant_Cuotas,			Importe_Cuota,			Imp_Total_Orig,
			Imp_Total_Con_Recargo,	Porc_Recargo,			Bin_Autorizados,
			Cuota_Gateway,			Flag_Promo,				Id_Cta_Banco,
			Tipo)

			VALUES
			(@Id_Tarjeta,			@Descripcion,		@Descrip_Corta,
			@Cant_Cuotas,			@Importe_Cuota,		@Imp_Total_Orig,
			@Imp_Total_Con_Recargo,	@Porc_Recargo,		@Bin_Autorizados,
			@Cuota_Gateway,			@Flag_Promo,		@Id_Cta_Banco,
			@Tipo)

			FETCH NEXT FROM curCuotas INTO @Cant_Cuotas, @Coef_Adel, @Coef_Venc, @Cuota_Gateway
		END
		CLOSE curCuotas
		DEALLOCATE curCuotas
	END

	FETCH NEXT FROM curTarjetas INTO @Id_Tarjeta, @Descripcion, @Descrip_Corta, @Flag_Promo, @Id_Cta_Banco, @Tipo
END
CLOSE curTarjetas
DEALLOCATE curTarjetas

SET @pProductos = REPLACE(@pProductos,'"','''')

IF @pProductos <> ''
BEGIN
	SELECT * INTO #Productos_Forma_Pago FROM Productos_Forma_Pago WHERE 1=0
	SET @SqlQry = 'INSERT INTO #Productos_Forma_Pago SELECT * FROM Productos_Forma_Pago WHERE Id_Producto IN ('+ @pProductos + ');'
	EXEC sp_executesql @SqlQry
	SELECT @CantFP = COUNT(*) FROM #Productos_Forma_Pago
	UPDATE #Productos_Forma_Pago SET Cuota = 1 WHERE ISNULL(Cuota,0) = 0

	IF @CantFP > 0
	BEGIN
	   SET @CantProd = (SELECT COUNT(DISTINCT(Id_Producto)) FROM #Productos_Forma_Pago) --GROUP BY Id_Producto)
	   SELECT Id_Tarjeta,Cuota,COUNT(*)AS Cant 
					INTO #Productos_Forma_Pago_Filtrado 
					FROM #Productos_Forma_Pago 
					GROUP BY Id_Tarjeta,Cuota HAVING COUNT(*) = @CantProd

	   SELECT * FROM #Tarjetas_Cuotas T, #Productos_Forma_Pago_Filtrado P
			WHERE T.Id_Tarjeta COLLATE Modern_Spanish_CI_AI = P.Id_Tarjeta COLLATE Modern_Spanish_CI_AI
			AND T.Cant_Cuotas = P.Cuota
	   DROP TABLE #Productos_Forma_Pago_Filtrado

	END 
	ELSE
	BEGIN
		SELECT * FROM #Tarjetas_Cuotas
	END
	DROP TABLE #Productos_Forma_Pago
END
ELSE
BEGIN
	SELECT * FROM #Tarjetas_Cuotas
END


