CREATE PROCEDURE [dbo].[CPJ_Val_Tarjetas_Lotes_Items_Dividir_Items] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON

	/***************************************************************************************************

	Procedimiento:      dbo.CPJ_Val_Tarjetas_Lotes_Items_Dividir_Items
	Fecha de Creacion:  2023-08-09
	Creado por:         Florencia Gonzalez
	Descripcion:        Procedimiento encargado de dividir operaciones a informar a entidad 
						(lote de tarjetas de debito/credito)
	Llamado por:        Lotes:Tarjetas:Fac:Dividir (FSER.APP ERP Desktop)
	Tablas afectadas:   [Val_Tarjetas_Lotes],[Val_Tarjetas_Lotes_Items]
	Usado en:           Administrador de Lotes de Tarjetas de Cr├®ditos y Centros de Pago (men├║ Facturaci├│n y Cobranzas)
	Parametro(s):       FlagUsarTrans, ModoDebug, Id_Tar_Lote, Max_Importe, Omitir_Resultado_OK
	Forma de uso:       EXEC [dbo].[CPJ_Val_Tarjetas_Lotes_Items_Dividir_Items] '{"Id_Tar_Lote":"60","Max_Importe":"100000","FlagUsarTrans":"1","ModoDebug":"0","Omitir_Resultado_OK":"0"}'
	Notas adicionales:  

	****************************************************************************************************

	SUMARIO DE CAMBIOS
	FECHA(yyyy-mm-dd)    Autor              Comentarios
	------------------- ------------------- ------------------------------------------------------------
              
	***************************************************************************************************/

	-------------------------------------------- VARIABLES RECIBIDAS POR PARAM --------------------------------------------

	DECLARE @pFlagUsarTrans			TINYINT
	DECLARE @pModoDebug				TINYINT
	DECLARE @pId_Tar_Lote			SMALLINT
	DECLARE @pMax_Importe			INT
	DECLARE @pOmitir_Resultado_OK	TINYINT

	SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
	SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
	SET @pId_Tar_Lote				= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@pJson,'Id_Tar_Lote')), 0)
	SET @pMax_Importe				= ISNULL(CONVERT(DECIMAL(20,2), dbo.CF_JSON_VALUE(@pJson,'Max_Importe')), 0)
	SET @pOmitir_Resultado_OK		= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Omitir_Resultado_OK')), 0)

	-------------------------------------------- FIN VARIABLES RECIBIDAS POR PARAM --------------------------------------------

	-------------------------------------------- VARIABLES LOCALES --------------------------------------------

	DECLARE @Cant_Items_Divididos	INT
	DECLARE @Item_Dividir			INT
	DECLARE @Prox_Item				INT
	DECLARE @Importe				DECIMAL(12,2)
	DECLARE @Importe2				DECIMAL(12,2)
	DECLARE @Importe3				DECIMAL(12,2)

	DECLARE @Respuesta_ TABLE (
								ErrorNumber		INT,
								ErrorSeverity	INT,
								ErrorState		INT,
								ErrorProcedure  VARCHAR(1000),
								ErrorLine		INT,
								ErrorMessage	VARCHAR(1000)
							  )

	DECLARE @Items_Dividir TABLE (
									Id_Tar_Lote			INT,
									Item_Tar_Lote		INT,
									Id_Cliente			INT,
									Id_Trans			INT,
									Nro					VARCHAR(50),
									Descripcion			VARCHAR(50),
									Importe				DECIMAL(15,5),
									Estado				CHAR(1),
									Nota					VARCHAR(250),
									CUIT					VARCHAR(50),
									Fecha_Est				DATETIME,
									Importe_2Vto			DECIMAL(15,5),
									Importe_3Vto			DECIMAL(15,5),
									Item_Tabla			SMALLINT NOT NULL IDENTITY(1,1)
								  )

	-------------------------------------------- FIN VARIABLES LOCALES --------------------------------------------

BEGIN TRY
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Val_Tarjetas_Lotes_Items_Dividir_Items'
		PRINT 'Parametros:'
		PRINT 'pModoDebug: ' + CONVERT(VARCHAR(5), @pModoDebug) + '. pId_Tar_Lote: ' + CONVERT(VARCHAR(15),@pId_Tar_Lote) 
	END

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END
	
	IF ISNULL((SELECT Id_Tar_Lote FROM Val_Tarjetas_Lotes WHERE Id_Tar_Lote = @pId_Tar_Lote),0) = 0
	BEGIN
		INSERT INTO @Respuesta_ (ErrorNumber,ErrorMessage)
						VALUES(1,'El lote de tarjetas ' + CONVERT(VARCHAR(15),@pId_Tar_Lote) + ' no existe')
		RAISERROR ('Error al ejecutar CPJ_Val_Tarjetas_Lotes_Items_Dividir_Items', 16, 1)
	END

	IF (SELECT COUNT(*) FROM Val_Tarjetas_Lotes_Items WHERE Id_Tar_Lote = @pId_Tar_Lote) = 0
	BEGIN
		INSERT INTO @Respuesta_ (ErrorNumber,ErrorMessage)
						  VALUES(2,'El lote de tarjetas ' + CONVERT(VARCHAR(15),@pId_Tar_Lote) + ' no tiene items')
		RAISERROR ('Error al ejecutar CPJ_Val_Tarjetas_Lotes_Items_Dividir_Items', 16, 1)
	END

	IF (SELECT COUNT(*) FROM Val_Tarjetas_Lotes_Items WHERE Id_Tar_Lote = @pId_Tar_Lote AND Importe > @pMax_Importe) = 0
	BEGIN
		INSERT INTO @Respuesta_ (ErrorNumber,ErrorMessage)
						  VALUES(3,'No hay items en este lote de tarjetas que excedan el importe de ' +  CONVERT(VARCHAR(25),@pMax_Importe))
		RAISERROR ('Error al ejecutar CPJ_Val_Tarjetas_Lotes_Items_Dividir_Items', 16, 1)
	END
	
	--------------------------------------------- CALCULO ITEMS A SEPARAR --------------------------------------

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Genero tabla auxiliar con los items que exceden el maximo importe' 
	END


	INSERT INTO @Items_Dividir
		SELECT Id_Tar_Lote, Item, Id_Cliente, Id_Trans, Nro, Descripcion, Importe, Estado, Nota, Cuit, Fecha_Est, Importe_2Vto, Importe_3Vto 
			   FROM Val_Tarjetas_Lotes_Items
			   WHERE Id_Tar_Lote = @pId_Tar_Lote
			     AND Importe > @pMax_Importe

	-------------------------------------------- FIN CALCULO ITEMS A SEPARAR -----------------------------------


	--------------------------------------------- SEPARO LOS ITEMS  --------------------------------------------
	
	SET @Cant_Items_Divididos = 0

	WHILE(@Cant_Items_Divididos < (SELECT COUNT(*) FROM @Items_Dividir))
	BEGIN
		SET @Cant_Items_Divididos += 1

		-- MODIFICO ITEM PRINCIPAL A MAXIMO DE IMPORTE
		SET @Item_Dividir = (SELECT Item_Tar_Lote FROM @Items_Dividir WHERE Item_Tabla = @Cant_Items_Divididos)

		IF(@pModoDebug = 1)
		BEGIN
			PRINT '@Cant_Items_Divididos: ' + CONVERT(VARCHAR(25),@Cant_Items_Divididos)
			PRINT 'Actualizo el importe del item original en Val_Tarjetas_Lotes_Items al importe m├íximo por item: ' + CONVERT(VARCHAR(25),@pMax_Importe)
		END

		UPDATE Val_Tarjetas_Lotes_Items SET Importe = @pMax_Importe WHERE Id_Tar_Lote = @pId_Tar_Lote AND Item = @Item_Dividir AND Importe > 0
		UPDATE Val_Tarjetas_Lotes_Items SET Importe_2Vto = @pMax_Importe WHERE Id_Tar_Lote = @pId_Tar_Lote AND Item = @Item_Dividir AND Importe_2Vto > 0
		UPDATE Val_Tarjetas_Lotes_Items SET Importe_3Vto = @pMax_Importe WHERE Id_Tar_Lote = @pId_Tar_Lote AND Item = @Item_Dividir AND Importe_3Vto > 0

		WHILE((SELECT Importe FROM @Items_Dividir WHERE Item_Tabla = @Cant_Items_Divididos) > @pMax_Importe)
		BEGIN
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Mientras que el importe secundario siga siendo mayor que el m├íximo permitido por item, desgloso el item original'
			END

			SET @Prox_Item = (SELECT MAX(Item) + 1 FROM Val_Tarjetas_Lotes_Items WHERE Id_Tar_Lote = @pId_Tar_Lote)
			
			UPDATE @Items_Dividir SET Importe = (Importe - @pMax_Importe) WHERE Id_Tar_Lote = @pId_Tar_Lote AND Item_Tabla = @Cant_Items_Divididos AND Importe > 0
			UPDATE @Items_Dividir SET Importe_2Vto = (Importe_2Vto - @pMax_Importe) WHERE Id_Tar_Lote = @pId_Tar_Lote AND Item_Tabla = @Cant_Items_Divididos AND Importe_2Vto > 0
			UPDATE @Items_Dividir SET Importe_3Vto = (Importe_3Vto - @pMax_Importe) WHERE Id_Tar_Lote = @pId_Tar_Lote AND Item_Tabla = @Cant_Items_Divididos AND Importe_3Vto > 0

			SELECT @Importe = Importe,
				   @Importe2 = Importe_2Vto,
				   @Importe3 = Importe_3Vto
				   FROM @Items_Dividir
				   WHERE Item_Tabla = @Cant_Items_Divididos

			IF(@Importe > @pMax_Importe)
			BEGIN
				SET @Importe = @pMax_Importe
			END
			
			IF(@Importe2 > @pMax_Importe)
			BEGIN
				SET @Importe2 = @pMax_Importe
			END

			IF(@Importe3 > @pMax_Importe)
			BEGIN
				SET @Importe3 = @pMax_Importe
			END

			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Inserto en tabla Val_Tarjetas_Lotes_Items'
				PRINT '@Importe: ' + CONVERT(VARCHAR(25),@Importe) + '. @Importe2: ' + CONVERT(VARCHAR(25),@Importe2) + '. @Importe3: ' + CONVERT(VARCHAR(25),@Importe3)
				PRINT '@Prox_Item: ' + CONVERT(VARCHAR(25),@Prox_Item)
			END

			INSERT INTO Val_Tarjetas_Lotes_Items (Id_Tar_Lote, Item, Id_Cliente, Id_Trans, Nro, Descripcion, Importe, 
												  Estado, Nota, Cuit, Fecha_Est, Importe_2Vto, Importe_3Vto)

										   SELECT Id_Tar_Lote, @Prox_Item, Id_Cliente, Id_Trans, Nro, Descripcion, @Importe, 
												  Estado, Nota, Cuit, Fecha_Est, @Importe2, @Importe3 
													FROM @Items_Dividir
													WHERE Item_Tabla = @Cant_Items_Divididos
	    END
	END

	--------------------------------------------- FIN SEPARO LOS ITEMS  ----------------------------------------

	--------------------------------------------- REORDENO LOS ITEMS  ----------------------------------------

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Reordeno la columna Item en tabla Val_Tarjetas_Lotes_Items para el lote'
	END

	SELECT * INTO #Val_Tarjetas_Lotes_Items_AUX FROM Val_Tarjetas_Lotes_Items WHERE Id_Tar_Lote = @pId_Tar_Lote ORDER BY Id_Cliente, Id_Trans
	DELETE FROM Val_Tarjetas_Lotes_Items WHERE Id_Tar_Lote = @pId_Tar_Lote

	ALTER TABLE #Val_Tarjetas_Lotes_Items_AUX ADD Item_Ordenado INT IDENTITY(1,1)
	UPDATE #Val_Tarjetas_Lotes_Items_AUX SET Item = Item_Ordenado
	ALTER TABLE #Val_Tarjetas_Lotes_Items_AUX DROP COLUMN Item_Ordenado 

	INSERT INTO Val_Tarjetas_Lotes_Items SELECT * FROM #Val_Tarjetas_Lotes_Items_AUX

	--------------------------------------------- FIN REORDENO LOS ITEMS  ----------------------------------------

	--------------------------------------------- ACTUALIZO VALORES DEL LOTE  ----------------------------------------

	UPDATE Val_Tarjetas_Lotes SET Cantidad = (SELECT COUNT(*) FROM Val_Tarjetas_Lotes_Items WHERE Id_Tar_Lote = @pId_Tar_Lote) WHERE Id_Tar_Lote = @pId_Tar_Lote

	--------------------------------------------- FIN ACTUALIZO VALORES DEL LOTE  ----------------------------------------

	IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0
	BEGIN
		COMMIT
	END

	IF @pOmitir_Resultado_OK = 0
	BEGIN
		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,0				AS ErrorMessage
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Generacion_Moratoria'
	END
	
END TRY
BEGIN CATCH

	IF EXISTS (SELECT 1 FROM @Respuesta_)
	BEGIN
		SELECT * FROM @Respuesta_
	END
	ELSE
	BEGIN
		EXECUTE usp_GetErrorInfo
	END

	IF @pFlagUsarTrans <> 0 AND @@TRANCOUNT > 0
	BEGIN
		ROLLBACK
	END

	RETURN 9999

END CATCH
GO


CREATE  PROCEDURE CPJ_Verificacion_Saldos_Clientes  @pJsonRecibido VARCHAR(8000)	 

AS
/*
2026-02-21 Responsable: Gabriel  ; Para los casos que se agrupa y se filtra por activo, el filtro solo debe hacerce en resultado final, sino agrupa mal por los dados de baja.
*/


DECLARE 	@pFecha_Desde		DATETIME,
			@pFecha_Hasta		DATETIME,
			@pAgrupaCli         TINYINT,
			@pTipo				CHAR(1)


SET @pFecha_Desde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Desde')),GETDATE())
SET @pFecha_Hasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Hasta')),GETDATE())
SET @pAgrupaCli			     	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'AgrupaCli')),0)
SET @pTipo				     	= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJsonRecibido,'Tipo')),'')


--VERSION: 11/02/2022
IF UPPER(@pTipo) = 'D'
BEGIN
		SELECT t.Id_Trans,t.Id_Estado_Cbte,SUM(t.importe) AS Importe, SUM(T.Saldo) AS Saldo INTO #CtatCteSaldos FROM  clientes_ctacte t WHERE t.Id_Estado_Cbte NOT in (0,3) GROUP BY t.Id_Trans,t.Id_Estado_Cbte
	
		select * from #CtatCteSaldos where saldo <>0 and Id_Estado_Cbte=2
		
		select c.id_cliente,c.id_trans,C.Imp_Total,C.Saldo,t.Saldo as SaldoCtacte,C.Id_Estado_Cbte,t.Id_Estado_Cbte AS Id_Estado_CtaCte
		INTO #VerificacionFact
		from  Cbtes C LEFT JOIN #CtatCteSaldos t ON  c.id_trans = t.id_trans, Clientes K , Cbtes_Tipos e
		where c.id_trans = t.id_trans
		and c.id_cliente = K.id_cliente
		and t.Id_Estado_Cbte NOT in (0,3)
		and c.Id_Estado_Cbte NOT in (0,3)
		and c.id_tipo_cbte = e.Id_Tipo_Cbte
		and e.compromete_factura in (1,-1)
		and c.id_cliente > 1
		AND C.Imp_Total <> 0
		AND C.Saldo <> 0
		AND t.Saldo <> 0
		AND (c.Id_Estado_Cbte <> t.Id_Estado_Cbte
		OR ABS(C.Saldo)  <> ABS(t.Saldo)
		OR ABS(C.Imp_Total)  <> ABS(t.Importe) 
		)

	
		--select a.id_trans_D,importe,z.* from #VerificacionFact z, Cbtes_Aplica a where  z.Id_trans=a.Id_trans and id_Estado_Cbte=1

		select c.id_cliente,c.id_trans,C.Imp_Total,C.Saldo,t.Saldo as SaldoCtacte,C.Id_Estado_Cbte,t.Id_Estado_Cbte AS Id_Estado_CtaCte
		INTO #VerificacionRec
		from  Cbtes C LEFT JOIN #CtatCteSaldos t ON  c.id_trans = t.id_trans, Clientes K , Cbtes_Tipos e
		where c.id_trans = t.id_trans
		and c.id_cliente = K.id_cliente
		and t.Id_Estado_Cbte NOT in (0,3)
		and c.Id_Estado_Cbte NOT in (0,3)
		and c.id_tipo_cbte = e.Id_Tipo_Cbte
		and e.compromete_recibos in (1,-1)
		and c.id_cliente > 1
		AND C.Imp_Total <> 0
		AND C.Saldo <> 0
		AND (c.Id_Estado_Cbte <> t.Id_Estado_Cbte
		OR ABS(C.Saldo)  <> ABS(t.Saldo)
		OR ABS(C.Imp_Total)  <> ABS(t.Importe) 
		)

		SELECT * FROM #VerificacionFact
		SELECT * FROM  #VerificacionRec 

		DROP TABLE #CtatCteSaldos
		DROP TABLE #VerificacionFact
		DROP TABLE #VerificacionRec

END
ELSE
BEGIN
		select c.id_cliente,cast(sum(Isnull(t.Saldo,0)*Isnull(c.Cotizacion,1)) as decimal(14,2)) as DEUDA
		Into #Verificacion
		from  clientes_ctacte t, Cbtes C, Clientes K 
		where c.id_trans = t.id_trans
		and c.id_cliente = K.id_cliente
		and t.Id_Estado_Cbte  in (1,4)
		and c.Id_Estado_Cbte  in (1,4)
		and c.id_cliente > 1
		group by  c.id_cliente

	
		select C.id_cliente, sum(isnull(c.imp_total,0)*t.compromete_factura*Isnull(c.cotizacion,1))  as Rescta
		Into #Facturas
		from cbtes c, cbtes_tipos t
		where c.id_tipo_cbte = t.Id_Tipo_Cbte
		and compromete_factura in (1,-1)
		and c.Id_Estado_Cbte  in (1,2,4)
		and c.Id_Cond_Pago <> 1  
		and c.id_cliente > 1
		group by  c.id_cliente


		select c.id_cliente,sum(Isnull(c.imp_total,0)*Isnull(c.cotizacion,1)) as recibos
		into #Recibos
		from cbtes c, cbtes_tipos t, Clientes K 
		where c.id_tipo_cbte = t.Id_Tipo_Cbte
		and c.id_cliente = K.id_cliente
		and compromete_recibos in (1,-1)
		and c.Id_Estado_Cbte  in (1,2,4)
		and c.id_cliente > 1
		group by  c.id_cliente

		ALTER TABLE #Verificacion ADD Rescta Decimal(14,2),Diferencia Decimal(14,2), Cliente_Ref INT

		UPDATE #Verificacion SET Rescta = 0, DIFERENCIA = 0, Cliente_Ref = 0

        INSERT INTO #Verificacion 
		       select F.Id_Cliente,0,0,0,0 from #Facturas F  where NOT EXISTS 
			          (SELECT 1 FROM #Verificacion v WHERE V.ID_CLIENTE = F.ID_CLIENTE)

        INSERT INTO #Verificacion 
		       select F.Id_Cliente,0,0,0,0 from #Recibos F  where NOT EXISTS 
			          (SELECT 1 FROM #Verificacion v WHERE V.ID_CLIENTE = F.ID_CLIENTE)

		Update #Verificacion set Rescta = R.Rescta  from #Verificacion C, #Facturas R Where C.Id_Cliente = R.Id_Cliente

		Update #Verificacion set Rescta = C.Rescta - R.Recibos from #Verificacion C, #Recibos R Where C.Id_Cliente = R.Id_Cliente

		Update #Verificacion set Diferencia = Rescta - Deuda 
 
		UPDATE #Verificacion SET Cliente_Ref = isnull(C.ID_Cliente_Ref,0) FROM #Verificacion V, CLIENTES C
		WHERE V.Id_Cliente = C.Id_Cliente 

		Update #Verificacion SET Cliente_Ref = Id_Cliente where Cliente_Ref = 0
   

    IF @pAgrupaCli <> 1
		   BEGIN
			  SELECT v.id_cliente,c.razon_social,SUM(Rescta) as rescta,SUM(Deuda) as Deuda, SUM(Diferencia) as Diferencia FROM #Verificacion V,Clientes C 
			  where c.id_cliente = V.Id_cliente AND C.Activo = 1 GROUP BY v.id_cliente,c.razon_social having SUM(Diferencia) <> 0 order by C.Razon_Social
		   END
		ELSE
		   BEGIN
			  SELECT v.Cliente_Ref,c.razon_social,SUM(Rescta) as Rescta,SUM(Deuda) as Deuda ,SUM(Diferencia) as Diferencia FROM #Verificacion V,Clientes C 
			  where c.id_cliente = V.Cliente_Ref AND C.Activo = 1 GROUP BY v.Cliente_Ref,c.razon_social having SUM(Diferencia) <> 0 order by C.Razon_Social
		   END		  
 
		DROP TABLE #Verificacion
		DROP TABLE #Recibos
		DROP TABLE #Facturas
		
END

	--	CPJ_Verificacion_Saldos_Clientes '{"AgrupaCli":"1"}' 


-- SELECT * FROM CBTES C, Clientes_CtaCte K WHERE C.Id_Trans = k.Id_Trans and c.Id_Cliente <> k.Id_Cliente

-- SELECT Id_Cliente_Ref,* FROM CLIENTES K WHERE K.Id_Cliente_Ref = 0
GO


CREATE PROCEDURE [dbo].[CPJ_WebProcesos]		@pJson VARCHAR(8000)
AS 
SET NOCOUNT ON

IF NOT EXISTS (SELECT * FROM sysobjects WHERE Name='WebProcesos' AND xtype='U')
BEGIN 
	SELECT 1 as Nro_Operacion, 1 as Nro_Operacion_Externo
	RETURN 0
END

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pFlagUsarTrans				TINYINT
		,@pModoDebug				TINYINT
		,@pId_Cliente				INT
		,@pTipo_Operacion			CHAR(1)
		,@pNro_Operacion			VARCHAR(100)
		,@pNro_Operacion_Externo	VARCHAR(100)
		,@pJsonDatos				VARCHAR(8000)
		,@pJsonDatosSep				CHAR(1)
		,@pPrefijo					VARCHAR(10)
		,@pTamanio					INT
		,@pAccion					CHAR(1)



SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pTipo_Operacion		= ISNULL(CONVERT(CHAR(2), dbo.CF_JSON_VALUE(@pJson,'Tipo_Operacion')), '')
SET @pNro_Operacion			= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJson,'Nro_Operacion')), '')
SET @pNro_Operacion_Externo	= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJson,'Nro_Operacion_Externo')), '')
SET @pJsonDatos				= ISNULL(CONVERT(VARCHAR(8000), dbo.CF_JSON_VALUE(@pJson,'JsonDatos')), '')
SET @pJsonDatosSep			= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJson,'JsonDatosSep')), '')
SET @pPrefijo				= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Prefijo')), '')
SET @pTamanio				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Tamanio')), 12)
SET @pAccion				= ISNULL(CONVERT(CHAR(1), dbo.CF_JSON_VALUE(@pJson,'Accion')), 'A')  --A=Agregar


/*Variables Locales*/
/*FIN Variables Locales*/

BEGIN TRY
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_WebProcesos'
		PRINT 'Parametros: '+ @pJson  
	END

	/*====================================================================================================================================================*/
	
	SET @pJsonDatos = REPLACE(@pJsonDatos,@pJsonDatosSep,'"')
	
	INSERT INTO WebProcesos (Id_Cliente, Tipo_Operacion, Nro_Operacion, Nro_Operacion_Externo, 
					Fecha_Creacion, Id_Estado, [Json]) 
					VALUES (@pId_Cliente,@pTipo_Operacion,@pNro_Operacion,@pNro_Operacion_Externo,
								GETDATE(),0,@pJsonDatos)
    SET @pNro_Operacion_Externo = @@IDENTITY
	SET @pNro_Operacion = RTRIM(LTRIM(@pPrefijo)) + RIGHT('000000000000000000000000000000' + CONVERT(VARCHAR(50), @@IDENTITY), @pTamanio - LEN(@pPrefijo))

	UPDATE WebProcesos SET 	Nro_Operacion = @pNro_Operacion	, Nro_Operacion_Externo = @pNro_Operacion_Externo		
				WHERE Id_Web_Proceso = @@IDENTITY

	/*====================================================================================================================================================*/

	IF @pFlagUsarTrans <> 0 COMMIT

	SELECT @pNro_Operacion as Nro_Operacion, @pNro_Operacion_Externo as Nro_Operacion_Externo , @@IDENTITY AS Id_Web_Proceso

	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_WebProcesos'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  ROLLBACK

	RETURN 9999
END CATCH

RETURN 0 


/*
 
EXEC CPJ_WebProcesos '{"ModoDebug":"1","FlagUsarTrans":"1","Id_Cliente":"1","Tipo_Operacion":"P","JsonDatos":"","Prefijo":"P","Tamanio":"12","Accion":"A"}'
select TOP 1 * from webprocesos ORDER BY 1 DESC

*/
GO


Create PROCEDURE [dbo].[CPJ_ventas_socios_actividades]	@pJsonRecibido VARCHAR(8000)
AS

SET NOCOUNT ON

DECLARE @pFechaDesde			DATETIME,
		@pFechaHasta			DATETIME,
		@pId_Unid_Negocio       VARCHAR(10),
		@pClientes_activos      TINYINT,
		@pUsuario               INT,
		@pId_Familia            INT,
		@pId_Producto           VARCHAR(14),
        @pOrden                 CHAR(10)

		DECLARE @Sql		    VARCHAR(MAX)
		DECLARE @SqlSelect		VARCHAR(MAX)
		DECLARE @SqlFrom	    VARCHAR(MAX)
		DECLARE @SqlWhere		VARCHAR(MAX)
		DECLARE @SqlOrden   	VARCHAR(MAX)
		DECLARE @sqlgroup       VARCHAR(MAX)
		DECLARE @SqlHaving      VARCHAR(MAX)

		/*Fin Variables Locales*/


		SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
		SET @pFechaDesde				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaDesde')),GETDATE())
		SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())
		SET @pClientes_activos			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Clientes_activos')),0)
		SET @pUsuario		        	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Usuario')),0)
		SET @pOrden				     	= ISNULL(CONVERT(CHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Orden')),'')
		SET @pId_Familia				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Familia')),0)
		SET @pId_Producto				= ISNULL(CONVERT(CHAR(14), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Producto')),'')
 

     Select * Into #Prod_Familias From Prod_Familias
	 If @pId_Familia <> 0
	     DELETE #Prod_Familias WHERE Id_Familia <>@pId_Familia 


 
Select K.Activo,K.Id_cliente, K.Id_Cliente_Externo AS Nro_Socio, K.Razon_Social, K.Id_Tipo_Doc, K.Doc_Nro, K.Fecha_Nac
      , dbo.CF_Edad_Persona_A_UnaFecha(K.Fecha_Nac,GETDATE()) as Edad
      , K.Sexo 
	  , CASE ISNULL(K.Id_Cliente_Ref,0)
	         WHEN 0 THEN 'TITULAR'
	         ELSE 'INTEGRANTE'
	    END AS Grupo
	  , CASE ISNULL(K.Id_Cliente_Ref,0)
	         WHEN 0 THEN K.Razon_Social
	         ELSE TIT.Razon_Social
	    END AS Titular
	  , K.Id_Tipo_cli,CT.Descripcion as Categoria
	  , K.Ult_Cuota_Paga
	  , convert(varchar,K.Email) as Email
	  , convert(varchar,ISNULL(K.Tel_Movil,'')) AS Telefono
	  , K.Fecha_Alta,ISNULL(K.Fecha_Baja,'') AS Fecha_Baja
	  , K.Id_Motivo_Est
	  , M.Descripcion AS Motivo_Baja 
	  , F.Descripcion as Actividad
	  , I.Fecha_QA 
 INTO #Reporte
 From Clientes K
		LEFT JOIN Cbtes_Items I ON I.Id_Cliente  = K.Id_Cliente AND I.Id_Cliente <> 0
		JOIN Cbtes C  ON C.Id_Trans = I.Id_Trans AND C.Id_Estado_Cbte Not In (0,3)
		JOIN Cbtes_tipos T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte And T.Compromete_Factura in (1,-1)
		JOIN Productos P   ON P.Id_Producto  = I.Id_Producto 
        JOIN #Prod_Familias F  ON F.Id_Familia = P.Id_Familia
		JOIN Clientes TIT  ON TIT.Id_Cliente = K.Id_Cliente_Ref
		JOIN Clientes_Tipos CT ON CT.Id_Tipo_Cli = K.Id_Tipo_Cli
		JOIN Estados_Motivos M ON M.Id_Motivo_Estado = K.Id_Motivo_Est
    Where I.Fecha_QA >= @pFechaDesde 
	      AND i.Fecha_QA < dateadd(dd,1,@pFechaHasta)
	

-----------------------------------------------------------------------------------------------------------------------------------------------
--| MajorVersion | Producto                  | Notas                        |
--| ------------ | ------------------------- | ---------------------------- |
--| 8            | SQL Server 2000           |                              |
--| 9            | SQL Server 2005           |                              |
--| 10           | SQL Server 2008 / 2008 R2 | 10.0 ÔåÆ 2008; 10.50 ÔåÆ 2008 R2 |
--| 11           | SQL Server 2012           |                              |
--| 12           | SQL Server 2014           |                              |
--| 13           | SQL Server 2016           |                              |
--| 14           | SQL Server 2017           |                              |
--| 15           | SQL Server 2019           |                              |
--| 16           | SQL Server 2022           |                              |

-----------------------------------------------------------------------------------------------------------------------------------------------
 
 		Select K.Activo,K.Id_Cliente, Nro_Socio, K.Razon_Social, K.Id_Tipo_Doc, K.Doc_Nro, K.Fecha_Nac
			   , Edad
			   , K.Sexo 
			   , Grupo
			   , Titular
			   , K.Id_Tipo_cli, Categoria
			   , K.Ult_Cuota_Paga, K.Email, Telefono
			   , K.Fecha_Alta, Fecha_Baja
			   , K.Id_Motivo_Est, Motivo_Baja 
			INTO #Consulta
		  From #Reporte K
		  
	ALTER TABLE #Consulta ADD  Actividad VARCHAR(MAX)

	DECLARE @MajorVersion INT

	SELECT @MajorVersion = CAST(
								LEFT(
									CAST(SERVERPROPERTY('ProductVersion') AS VARCHAR(50)),
									CHARINDEX('.', CAST(SERVERPROPERTY('ProductVersion') AS VARCHAR(50))) - 1
								) 
							AS INT) 


	IF @MajorVersion >= 13  --2016
		SET @Sql = ' Insert INTO #Consulta
		Select K.Activo,K.Id_Cliente, Nro_Socio, K.Razon_Social, K.Id_Tipo_Doc, K.Doc_Nro, K.Fecha_Nac
			   , Edad
			   , K.Sexo 
			   , Grupo
			   , Titular
			   , K.Id_Tipo_cli, Categoria
			   , K.Ult_Cuota_Paga, K.Email, Telefono
			   , K.Fecha_Alta, Fecha_Baja
			   , K.Id_Motivo_Est, Motivo_Baja 
			   , STRING_AGG(Actividad + '' '' + left(Convert(char(8),Fecha_QA,112),6), '', '') as Actividad
		  From #Reporte K
		  GROUP BY 
		  K.Activo,K.Id_cliente, K.Nro_Socio , K.Razon_Social, K.Id_Tipo_Doc, K.Doc_Nro, K.Fecha_Nac
			   , Edad
			   , K.Sexo 
			   , Grupo
			   , Titular
			   , K.Id_Tipo_cli
			   , Categoria
			   , K.Ult_Cuota_Paga
			   , K.Email
			   , K.Telefono
			   , K.Fecha_Alta,K.Fecha_Baja
			   , K.Id_Motivo_Est
			   , K.Motivo_Baja' 
	
	ELSE
		SET @Sql = ';WITH CTE_Claves AS (
			SELECT DISTINCT         Activo,			Id_Cliente,			Nro_Socio,			Razon_Social,			Id_Tipo_Doc,
									Doc_Nro,        Fecha_Nac,			Edad,				Sexo,					Grupo,
									Titular,        Id_Tipo_cli,        Categoria,			Ult_Cuota_Paga,			Email,
									Telefono,       Fecha_Alta,			Fecha_Baja,			Id_Motivo_Est,			Motivo_Baja
			FROM #Reporte
		)
		INSERT INTO #Consulta
		SELECT  K.Activo,	K.Id_Cliente,    K.Nro_Socio,   K.Razon_Social,		K.Id_Tipo_Doc,
				K.Doc_Nro,  K.Fecha_Nac,	 K.Edad,		K.Sexo,				K.Grupo,    
				K.Titular,	K.Id_Tipo_cli,   K.Categoria,   K.Ult_Cuota_Paga,   K.Email,
				K.Telefono, K.Fecha_Alta,    K.Fecha_Baja,  K.Id_Motivo_Est,    K.Motivo_Baja,

			STUFF((
				SELECT
					'', '' + R.Actividad
						  + '' '' + LEFT(CONVERT(CHAR(8), R.Fecha_QA, 112), 6)
				FROM #Reporte AS R
				WHERE
					R.Id_Cliente    = K.Id_Cliente
				FOR XML PATH(''''), TYPE
			).value(''.'', ''NVARCHAR(MAX)'')
			, 1, 2, ''''  -- elimina la coma y espacio iniciales
			) AS Actividad
		FROM CTE_Claves AS K;'

	EXEC(@Sql)


----------------------------------------------------------------------------------------------------------------------


		SET @Sql	    = ''
		SET @SqlSelect	= ''
		SET @SqlFrom	= ''
		SET @SqlWhere	= ''
		SET @SqlOrden	= ''
		SET @sqlgroup   = ''
		SET @SqlHaving  = ''

      SET @SqlSelect	= 'SELECT * FROM #CONSULTA'
	  SET @SqlWhere	= 'WHERE 1=1 '

	  IF @pClientes_activos = 1
	     SET @SqlWhere	+= ' AND ACTIVO = 1 '
      
      IF @pOrden = 'N'
	     SET @SqlOrden	= 'ORDER BY Razon_Social'

      IF @pOrden = 'C'
	     SET @SqlOrden	= 'ORDER BY Nro_Socio'

	  SET @Sql = @SqlSelect + ' ' + @SqlWhere + ' ' + @SqlOrden
	  EXEC(@sql) 

Drop Table #Reporte
Drop Table #Consulta
Drop Table #Prod_Familias


