EXEC CPJ_ventas_socios_actividades '{"FechaDesde":"20220513","FechaHasta":"20230613","Id_Unid_Negocio":"","Filtrar_con_saldo":"1"
,"Clientes_activos":"1","Id_Producto":"","Id_Familia":"","Orden":"N","Formato":"PC"}'  

