CREATE PROCEDURE [dbo].[CP_AppEve_BusCred] (@pId_Evento SMALLINT, @pCredencial_Nro VARCHAR(30))
AS
BEGIN

SELECT I.Id_Trans,I.Item,isnull(k.Doc_Nro,0) as documento ,c.id_CLiente, K.nombre, K.apellido, c.Destinatario as nombre2, I.id_producto,
ISNULL(K.ID_CLIENTE_REF,0) as cod_empresa,E.Razon_Social as empresa,C.Observacion
, k.Credencial_Nro
FROM Cbtes_Items I, Cbtes C, Productos P, Clientes K, Clientes E,
Cbtes_Items I3, Cbtes C3, Productos P3,Cbtes_Tipos T3, Prod_Listas_Precios_Items LPI3, Productos P23
WHERE I.Id_Trans = C.Id_Trans
AND P.Id_Producto = I.Id_Producto
AND ISNULL(I.Id_cliente,0) = K.Id_cliente
AND ISNULL(K.ID_CLIENTE_REF,0) = E.ID_CLIENTE
AND ( P.vendible = 1 OR I.Id_Producto IN (dbo.CF_xParam('Acompa_A_Desig')))
AND P.ID_FAMILIA NOT IN (dbo.CF_xParam('Flias_Habitaciones'), dbo.CF_xParam('Flias_Mesas'))
AND C.Id_trans = c3.id_trans
And I3.Id_Trans = C3.Id_Trans AND P3.Id_Producto = I3.Id_Producto AND C3.Id_Tipo_Cbte = T3.Id_Tipo_Cbte
AND P3.ID_FAMILIA NOT IN (dbo.CF_xParam('Flias_Habitaciones'), dbo.CF_xParam('Flias_Mesas'))
AND T3.Compromete_Pedido IN(1,-1) AND C3.ID_ESTADO_CBTE IN (1,2,4)
AND I3.ID_PRODUCTO = LPI3.Id_Producto 
AND P23.Id_Producto = LPI3.Id_Producto
AND P23.Vendible = 1 AND P23.Tipo <> 'L'
AND LPI3.Id_Lista_Precio = @pId_Evento
And K.Credencial_Nro=@pCredencial_Nro

END
GO

CREATE PROCEDURE [dbo].[CP_AppEve_Busca] (@pId_Evento SMALLINT, @pDoc_Nro BIGINT, @pRazon_Social VARCHAR(100))
AS
BEGIN


SELECT I.Id_Trans,I.Item,
ISNULL(I.Id_Cliente,C.ID_CLIENTE),K.Razon_Social,c.id_CLiente, K.nombre, K.apellido, c.Destinatario as nombre2,I.id_producto,I.Descripcion_Producto,i.Cantidad,
ISNULL(K.ID_CLIENTE_REF,0),E.Razon_Social as empresa,Isnull(I.fecha_proceso,0),C.Observacion,Isnull(I.fecha_Caducidad,0),Isnull(I.fecha_QA,0),K.CREDENCIAL_NRO, isnull(k.Doc_Nro,0) as documento
FROM Cbtes_Items I, Cbtes C, Productos P, Clientes K, Clientes E,
Cbtes_Items I3, Cbtes C3, Productos P3,Cbtes_Tipos T3, Prod_Listas_Precios_Items LPI3, Productos P23
WHERE I.Id_Trans = C.Id_Trans
AND P.Id_Producto = I.Id_Producto
AND ISNULL(I.Id_cliente,0) = K.Id_cliente
AND ISNULL(K.ID_CLIENTE_REF,0) = E.ID_CLIENTE
AND ( P.vendible = 1 OR I.Id_Producto IN (dbo.CF_xParam('Acompa_A_Desig')))
AND P.ID_FAMILIA NOT IN (dbo.CF_xParam('Flias_Habitaciones'), dbo.CF_xParam('Flias_Mesas'))
AND C.Id_trans = c3.id_trans
And I3.Id_Trans = C3.Id_Trans AND P3.Id_Producto = I3.Id_Producto AND C3.Id_Tipo_Cbte = T3.Id_Tipo_Cbte
AND P3.ID_FAMILIA NOT IN (dbo.CF_xParam('Flias_Habitaciones'), dbo.CF_xParam('Flias_Mesas'))
AND T3.Compromete_Pedido IN(1,-1) AND C3.ID_ESTADO_CBTE IN (1,2,4)
AND I3.ID_PRODUCTO = LPI3.Id_Producto 
AND P23.Id_Producto = LPI3.Id_Producto
AND P23.Vendible = 1 AND P23.Tipo <> 'L'
AND T3.Id_Tipo_Cbte='INFO'
AND LPI3.Id_Lista_Precio = @pId_Evento
AND (
   ((K.Doc_Nro = @pDoc_Nro Or E.Doc_Nro = @pDoc_Nro) or (K.CUIT Like '%' + CONVERT(VARCHAR(13), @pDoc_Nro) + '%' Or E.CUIT Like '%' + CONVERT(VARCHAR(13), @pDoc_Nro) + '%'))
   or
   ((K.Razon_Social LIKE '%' + @pRazon_Social + '%' Or E.Razon_Social Like '%' + @pRazon_Social + '%') or (K.Nombre_Fantasia Like '%' + @pRazon_Social + '%' Or E.Nombre_Fantasia Like '%' + @pRazon_Social + '%'))
)
order by K.apellido

END
GO


CREATE PROCEDURE [dbo].[CP_AppEve_Cambiar_Mesa]	 @pId_Evento SMALLINT, @pId_Mesa1	VARCHAR(5), @pId_Mesa2	VARCHAR(5)
AS


UPDATE Cbtes_Items
SET 
Cbtes_Items.Calle	= @pId_Mesa2, 
Cbtes_Items.Fila	= '0', 
Cbtes_Items.Columna	= '0'
FROM Productos PR
WHERE 
Cbtes_Items.Id_Producto = PR.Id_Producto
AND ISNULL (Cbtes_Items.Calle, '')    = @pId_Mesa1
AND Cbtes_Items.Id_Trans IN (SELECT DISTINCT(CI2.Id_Trans)
							FROM 
							Cbtes_Items CI2 ,Productos P2, Prod_Listas_Precios_Items LPI
							WHERE 
							CI2.Id_Producto = P2.Id_Producto
							AND LPI.Id_Producto = CI2.Id_Producto
							AND P2.Id_Familia NOT IN (dbo.CF_xParam('Flias_Habitaciones'), dbo.CF_xParam('Flias_Mesas'))
							AND P2.Vendible = 1 							
							AND LPI.Id_Lista_Precio = @pId_Evento)
GO


CREATE PROCEDURE [dbo].[CP_AppEve_ClienteActivity] (
	@pId_Evento SMALLINT,
	@pId_Cliente INT,
	@pId_Trans INT,
	@pItem SMALLINT
)
AS
BEGIN

DECLARE @Credencial_Nro VARCHAR(30)
DECLARE @Fecha_Proceso DATETIME
DECLARE @Fecha_Caducidad DATETIME
DECLARE @Hotel VARCHAR(50)
DECLARE @Habitacion CHAR(5)
DECLARE @Mesa CHAR(5)
DECLARE @Datos_Adicionales VARCHAR(8000)
DECLARE @Color CHAR(7)
DECLARE @Acomp VARCHAR(100)

-- TAG
SELECT @Credencial_Nro = Credencial_Nro FROM Clientes WHERE Id_Cliente = @pId_Cliente


-- INGRESO
SELECT @Fecha_Proceso = Fecha_Proceso
	FROM CBTES_ITEMS I, PRODUCTOS P
	WHERE I.ID_PRODUCTO = P.ID_PRODUCTO AND P.VENDIBLE = 1 AND P.TIPO <> 'L'
	AND P.ID_FAMILIA NOT IN (dbo.CF_xParam('Flias_Habitaciones') , dbo.CF_xParam('Flias_Mesas'))
	AND I.ID_TRANS = @pId_Trans AND I.Item = @pItem


-- EGRESO
SELECT @Fecha_Caducidad = Fecha_Caducidad
	FROM CBTES_ITEMS I, PRODUCTOS P
	WHERE I.ID_PRODUCTO = P.ID_PRODUCTO AND P.VENDIBLE = 1 AND P.TIPO <> 'L'
	AND P.ID_FAMILIA NOT IN (dbo.CF_xParam('Flias_Habitaciones') , dbo.CF_xParam('Flias_Mesas'))
	AND I.ID_TRANS = @pId_Trans AND I.Item = @pItem
	

-- HOTEL / HABITACION
SELECT 
	@Habitacion = coalesce(columna,''),
	@Hotel = coalesce(e.Descripcion, '')
	FROM productos p,Empresas_Sedes e
	WHERE p.id_producto =  dbo.CF_AppEve_Habit(@pId_Cliente, @pId_Trans)
	and e.Id_Sede = dbo.CF_AppEve_Hotel(@pId_Cliente, @pId_Trans)


-- UBICACION
SELECT @Mesa = ISNULL(I.Calle,'')
FROM Cbtes_Items I, Cbtes C, Productos P, Cbtes_Tipos T, Clientes E, Clientes K
	WHERE I.Id_Trans = @pId_Trans
	AND I.Id_Cliente = @pId_Cliente
	AND I.Id_Trans = C.Id_Trans
	AND P.Id_Producto = I.Id_Producto
	AND E.Id_cliente = ISNULL(I.Id_cliente,C.Id_cliente)
	AND K.ID_CLIENTE = ISNULL(E.ID_CLIENTE_REF,0)
	AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
	AND T.Compromete_Pedido IN(1,-1)
	AND C.ID_ESTADO_CBTE IN (1,2,4)
	AND (P.Id_Producto IN ('ACOMP') OR P.Id_Familia IN (dbo.CF_xParam('Flias_Mesas')))
	AND C.id_Trans IN (SELECT distinct(i2.id_trans)
					FROM Cbtes_Items I2 ,Productos P2, Prod_Listas_Precios_Items LPI
					WHERE I2.Id_Producto = P2.Id_Producto
					  AND P2.Id_Familia NOT IN (dbo.CF_xParam('Flias_Habitaciones'), dbo.CF_xParam('Flias_Mesas'))
					  AND P2.Vendible = 1
					  AND LPI.Id_Producto = I2.Id_Producto
					  AND I2.Id_Trans = @pId_Trans )
					  

-- DATOS ADICIONALES
select @Datos_Adicionales = dbo.CF_AppEve_DatosAdicionales(@pId_Cliente, @pId_Evento)


-- COLOR - CATEGORIA
select @Color = dbo.SF_AppEve_Cred_Color(@pId_Cliente)

--Datos del acompañante
SET @Acomp = dbo.CF_AppEve_ParticipanteConAcomp(@pId_Trans, @pId_Cliente)

-- RESPUESTA
SELECT 
	@Credencial_Nro as Credencial_Nro, 
	@Fecha_Proceso as Fecha_Proceso, 
	@Fecha_Caducidad as Fecha_Caducidad,
	@Hotel as Hotel,
	@Habitacion as Habitacion,
	@Mesa as Mesa,
	@Datos_Adicionales as Datos_Adicionales,
	@Color as Color,
	@Acomp	AS Acomp




END
GO


CREATE PROCEDURE [dbo].[CP_AppEve_InscExcepProd] (@pId_Evento SMALLINT, @pId_Controlador SMALLINT)
AS
BEGIN

SELECT p.Id_Producto, p.Descripcion_Detallada AS Descripcion 
	FROM Prod_Listas_Precios_Items l
	left join Productos p on l.Id_Producto=p.Id_Producto
	WHERE Id_Lista_Precio=@pId_Evento
	AND p.Id_Familia NOT IN (dbo.CF_xParam('Flias_Habitaciones'), 
	dbo.CF_xParam('Flias_Mesas'),
	dbo.CF_xParam('Flias_Acred_Inst'))

END
GO


CREATE PROCEDURE [dbo].[CP_AppEve_InscInst]  @pDoc_Nro			BIGINT, 
											@pApellido			VARCHAR(100), 
											@pNombre			VARCHAR(100),
											@pFNac				DATE,
											@pSexo				CHAR(1),
											@pEmpresa			VARCHAR(254),
											@pId_Producto		VARCHAR(14)
AS
SET NOCOUNT ON
DECLARE @Id_Cliente		INT
DECLARE @Razon_Social	VARCHAR(100)
DECLARE @Observacion	VARCHAR(MAX)

SET @Id_Cliente = ISNULL((SELECT TOP 1 Id_Cliente FROM Clientes WHERE Id_Tipo_Doc = '1' AND Doc_Nro = @pDoc_Nro ORDER BY Activo DESC), 0)

BEGIN TRY

IF (@Id_Cliente = 0)
BEGIN
	/*No existe el cliente ni Activo ni inactivo*/
    SET @Id_Cliente = (SELECT MAX(ISNULL(Id_Cliente, 0)) + 1 FROM Clientes)
    
    SET @Razon_Social	= LTRIM(RTRIM(@pApellido)) + ' ' + LTRIM(RTRIM(@pNombre))
	SET @Observacion	= 'Dado de alta a traves de: SP_AppEve_InscInst.'
    
	INSERT INTO Clientes 
	(Id_Cliente,		Apellido,		Nombre,
	Razon_Social,		Sexo,			Id_Tipo_Doc,
	Doc_Nro,			Fecha_Nac,		Activo,
	Fecha_alta,			Web,			Tipo_Persona)
	VALUES
	(@Id_Cliente,		@pApellido,		@pNombre,
	@Razon_Social,		@pSexo,			1,
	@pDoc_Nro,			@pFNac,			1,
	GETDATE(),			@pEmpresa,		'F')
END

EXECUTE dbo.SP_InscDirec_Online  @Id_Cliente, @pId_Producto, 2, 'A', 0

END TRY  
BEGIN CATCH  
    -- Execute error retrieval routine.  
    EXECUTE usp_GetErrorInfo;  
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_AppEve_InscMod]
@Doc_Nro BIGINT, 
@Apellido VARCHAR(100), 
@Nombre VARCHAR(100), 
@FNac DATE, 
@Sexo CHAR(1), 
@Empresa VARCHAR(254), 
@Id_Producto CHAR(14),
@Id_Cliente INT,
@Id_Trans INT
AS

BEGIN TRY

IF (@Id_Cliente > 0)
BEGIN

	UPDATE Clientes SET
		Apellido = @Apellido,
		Nombre = @Nombre,
		Razon_Social = LTRIM(RTRIM(@Apellido)) + ' ' + LTRIM(RTRIM(@Nombre)),
		Sexo = @Sexo,
		Id_Tipo_Doc = 1,
		Doc_Nro = @Doc_Nro,
		Fecha_Nac = @FNac,
		Web = @Empresa
	WHERE Id_Cliente = @Id_Cliente

END

IF (@Id_Trans > 0)
BEGIN

	DECLARE @Descripcion_producto VARCHAR(100);
	SET @Descripcion_producto = (SELECT Descripcion_Resumida FROM productos WHERE Id_Producto=@Id_Producto)

	UPDATE Cbtes_Items SET
		Id_Producto =  @Id_Producto,
		Descripcion_producto = @Descripcion_producto
	WHERE Id_Trans = @Id_Trans

END



END TRY  
BEGIN CATCH  
    -- Execute error retrieval routine.  
    EXECUTE usp_GetErrorInfo;  
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_AppEve_Limpiar_Mesa]	 @pId_Evento SMALLINT
AS

UPDATE Cbtes_Items
SET 
Cbtes_Items.Calle	= '', 
Cbtes_Items.Fila	= '', 
Cbtes_Items.Columna	= ''
FROM Productos PR
WHERE 
Cbtes_Items.Id_Producto = PR.Id_Producto
AND ISNULL (Cbtes_Items.Calle, '')    <> ''
AND Cbtes_Items.Id_Trans IN (SELECT DISTINCT(CI2.Id_Trans)

							FROM 

							Cbtes_Items CI2 ,Productos P2, Prod_Listas_Precios_Items LPI

							WHERE 

							CI2.Id_Producto = P2.Id_Producto

							AND LPI.Id_Producto = CI2.Id_Producto

							AND P2.Id_Familia NOT IN (dbo.CF_xParam('Flias_Habitaciones'), dbo.CF_xParam('Flias_Mesas'))

							AND P2.Vendible = 1 							

							AND LPI.Id_Lista_Precio = @pId_Evento)
GO


