CREATE PROCEDURE [dbo].[CP_AppEve_Stat] @Id_evento int
AS
BEGIN
CREATE TABlE #StatTab (Nombre VARCHAR(100), Valor VARCHAR(30), Url VARCHAR(500))

INSERT INTO #StatTab

    SELECT 'Inscriptos' as nombre, 
    (SELECT COUNT(*) FROM Cbtes 
     WHERE (Id_Tipo_Cbte = 'INFO')
       AND (Id_Estado_Cbte IN (1,2)  -- 1 = PENDIENTE, 2 = COMPLETO
       AND (Id_Centro_Costo = '0302170001')) -- PRECOLOQUIO CENTRO 16/08  
    ) 
    AS valor, '' as url
 UNION ALL
 SELECT 'Acreditados' as nombre, 56 as valor, '' as url
 UNION ALL
 SELECT 'Sin Acreditar' as nombre, 23 as valor, '' as url
 UNION ALL
 SELECT '---------------------------------------------','',''
 UNION ALL
 SELECT 'Ubicables' as nombre, 43 as valor, '' as url
 UNION ALL
 SELECT 'Ubicados' as nombre, 43 as valor, '' as url
 UNION ALL
 SELECT 'Sin Ubicar' as nombre, 24 as valor, 'http://www.google.com' as url
 UNION ALL
 SELECT '---------------------------------------------','',''
 UNION ALL
 SELECT 'Presentes' as nombre, 13 as valor, '' as url
 UNION ALL
 SELECT 'Ausentes' as nombre, 13 as valor, '' as url

SELECT * FROM   #StatTab 

DROP TABLE #StatTab
END
GO

CREATE PROCEDURE [dbo].[CP_AppEve_Ubic] (@pId_Evento SMALLINT, @pCredencial_Nro VARCHAR(30))
AS
BEGIN

SELECT I.Id_Cliente, K.Razon_Social, I.Id_Trans,I.Item,I.Calle Mesa, E.Razon_Social empresa, F.Foto
FROM Cbtes_Items I, Cbtes C, Productos P, Clientes E,
Cbtes_Items I3, Cbtes C3, Productos P3,Cbtes_Tipos T3, Prod_Listas_Precios_Items LPI3, Productos P23, Clientes K
LEFT JOIN Clientes_Fotos F on F.Id_Cliente = K.Id_Cliente
WHERE I.Id_Trans = C.Id_Trans
AND P.Id_Producto = I.Id_Producto
AND ISNULL(I.Id_cliente,0) = K.Id_cliente
AND ISNULL(K.ID_CLIENTE_REF,0) = E.ID_CLIENTE
AND ( P.vendible = 1 OR I.Id_Producto IN (dbo.CF_xParam('Acompa_A_Desig')))
AND P.ID_FAMILIA NOT IN (dbo.CF_xParam('Flias_Habitaciones'), dbo.CF_xParam('Flias_Mesas'))
AND C.Id_trans = c3.id_trans
And I3.Id_Trans = C3.Id_Trans AND P3.Id_Producto = I3.Id_Producto AND C3.Id_Tipo_Cbte = T3.Id_Tipo_Cbte
AND P3.ID_FAMILIA NOT IN (dbo.CF_xParam('Flias_Habitaciones'), dbo.CF_xParam('Flias_Mesas'))
AND T3.Compromete_Pedido IN(1,-1) AND C3.ID_ESTADO_CBTE IN (1,2,4)
AND I3.ID_PRODUCTO = LPI3.Id_Producto 
AND P23.Id_Producto = LPI3.Id_Producto
AND P23.Vendible = 1 AND P23.Tipo <> 'L'
AND LPI3.Id_Lista_Precio = @pId_Evento
AND K.Credencial_Nro=@pCredencial_Nro


END
GO


CREATE procedure dbo.CP_Asientos_AjuInflacion @pTipo CHAR(1),@pId_Moneda CHAR(3), @pFDesde datetime,@pFHasta datetime,@pId_Plan_Cta INT,@pAlias INT
/*

@Tipo = 'C'   --Coeficientes
