	Id_Cta_Contable INT,
	Nro_Cta_Contable VARCHAR(20),
	Descripcion VARCHAR(80),
	Alias SMALLINT,
	Id_Centro_Costo CHAR(10),
    Descripcion_CC VARCHAR(200),
	Mes00   DECIMAL(18,5) DEFAULT(0),
	Mes01	DECIMAL(18,5) DEFAULT(0),
	Mes02	DECIMAL(18,5) DEFAULT(0),
	Mes03	DECIMAL(18,5) DEFAULT(0),
	Mes04	DECIMAL(18,5) DEFAULT(0),
	Mes05	DECIMAL(18,5) DEFAULT(0),
	Mes06	DECIMAL(18,5) DEFAULT(0),
	Mes07	DECIMAL(18,5) DEFAULT(0),
	Mes08	DECIMAL(18,5) DEFAULT(0),
	Mes09	DECIMAL(18,5) DEFAULT(0),
	Mes10	DECIMAL(18,5) DEFAULT(0),
	Mes11	DECIMAL(18,5) DEFAULT(0),
	Mes12	DECIMAL(18,5) DEFAULT(0),
	Total	DECIMAL(18,5) DEFAULT(0),
    AliasCtaAju INT
	)


IF UPPER(@pTipo) IN ('C','A','D','F','H') 
BEGIN

	SET @CoefMes00 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,-1,@pFDesde)) ) 
	SET @CoefMes01 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(@pFDesde) ) 
	SET @CoefMes02 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,1,@pFDesde)) ) 
	SET @CoefMes03 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,2,@pFDesde)) ) 
	SET @CoefMes04 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,3,@pFDesde)) ) 
	SET @CoefMes05 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,4,@pFDesde)) ) 
	SET @CoefMes06 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,5,@pFDesde)) ) 
	SET @CoefMes07 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,6,@pFDesde)) ) 
	SET @CoefMes08 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,7,@pFDesde)) ) 
	SET @CoefMes09 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,8,@pFDesde)) ) 
	SET @CoefMes10 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,9,@pFDesde)) ) 
	SET @CoefMes11 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,10,@pFDesde)) ) 
	SET @CoefMes12 = (SELECT TOP 1 Coeficiente FROM Valores_Monedas_Inflacion  WHERE Id_Moneda = @pId_Moneda AND DBO.CF_EOMonth(Fecha) = DBO.CF_EOMonth(DATEADD(MM,11,@pFDesde)) ) 


	SET @CoefActual = @CoefMes01
	IF dbo.CF_FOMONTH(DATEADD(MM, 1,@pFDesde)) <= @pFHasta 
	   SET @CoefActual = @CoefMes02
	IF dbo.CF_FOMONTH(DATEADD(MM, 2,@pFDesde)) <= @pFHasta 
	   SET @CoefActual = @CoefMes03
	IF dbo.CF_FOMONTH(DATEADD(MM, 3,@pFDesde)) <= @pFHasta 
	   SET @CoefActual = @CoefMes04
	IF dbo.CF_FOMONTH(DATEADD(MM, 4,@pFDesde)) <= @pFHasta 
	   SET @CoefActual = @CoefMes05
	IF dbo.CF_FOMONTH(DATEADD(MM, 5,@pFDesde)) <= @pFHasta 
	   SET @CoefActual = @CoefMes06
	IF dbo.CF_FOMONTH(DATEADD(MM, 6,@pFDesde)) <= @pFHasta 
	   SET @CoefActual = @CoefMes07
	IF dbo.CF_FOMONTH(DATEADD(MM, 7,@pFDesde)) <= @pFHasta 
	   SET @CoefActual = @CoefMes08
	IF dbo.CF_FOMONTH(DATEADD(MM, 8,@pFDesde)) <= @pFHasta 
	   SET @CoefActual = @CoefMes09
	IF dbo.CF_FOMONTH(DATEADD(MM, 9,@pFDesde)) <= @pFHasta 
	   SET @CoefActual = @CoefMes10
	IF dbo.CF_FOMONTH(DATEADD(MM, 10,@pFDesde)) <= @pFHasta 
	   SET @CoefActual = @CoefMes11
	IF dbo.CF_FOMONTH(DATEADD(MM, 11,@pFDesde)) <= @pFHasta 
	   SET @CoefActual = @CoefMes12


	SET @CoefAplicMes00 = @CoefActual / @CoefMes00
	SET @CoefAplicMes01 = @CoefActual / @CoefMes01
	SET @CoefAplicMes02 = @CoefActual / @CoefMes02
	SET @CoefAplicMes03 = @CoefActual / @CoefMes03
	SET @CoefAplicMes04 = @CoefActual / @CoefMes04
	SET @CoefAplicMes05 = @CoefActual / @CoefMes05
	SET @CoefAplicMes06 = @CoefActual / @CoefMes06
	SET @CoefAplicMes07 = @CoefActual / @CoefMes07
	SET @CoefAplicMes08 = @CoefActual / @CoefMes08
	SET @CoefAplicMes09 = @CoefActual / @CoefMes09
	SET @CoefAplicMes10 = @CoefActual / @CoefMes10
	SET @CoefAplicMes11 = @CoefActual / @CoefMes11
	SET @CoefAplicMes12 = @CoefActual / @CoefMes12

	IF dbo.CF_FOMONTH(DATEADD(MM, 0,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes01 = 0

	IF dbo.CF_FOMONTH(DATEADD(MM, 1,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes02 = 0

	IF dbo.CF_FOMONTH(DATEADD(MM, 2,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes03 = 0

	IF dbo.CF_FOMONTH(DATEADD(MM, 3,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes04 = 0

	IF dbo.CF_FOMONTH(DATEADD(MM, 4,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes05 = 0

	IF dbo.CF_FOMONTH(DATEADD(MM, 5,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes06 = 0

	IF dbo.CF_FOMONTH(DATEADD(MM, 6,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes07 = 0

	IF dbo.CF_FOMONTH(DATEADD(MM, 7,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes08 = 0

	IF dbo.CF_FOMONTH(DATEADD(MM, 8,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes09 = 0

	IF dbo.CF_FOMONTH(DATEADD(MM, 9,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes10 = 0

	IF dbo.CF_FOMONTH(DATEADD(MM, 10,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes11 = 0

	IF dbo.CF_FOMONTH(DATEADD(MM, 11,@pFDesde)) > @pFHasta 
		SET @CoefAplicMes12 = 0



	INSERT INTO #Resultado 
			SELECT 'C',0,'','Coeficientes',0,'',''
					,@CoefMes00 AS Mes00
					,@CoefMes01 AS Mes01
					,@CoefMes02 AS Mes02
					,@CoefMes03 AS Mes03
					,@CoefMes04 AS Mes04
					,@CoefMes05 AS Mes05
					,@CoefMes06 AS Mes06
					,@CoefMes07 AS Mes07
					,@CoefMes08 AS Mes08
					,@CoefMes09 AS Mes09
					,@CoefMes10 AS Mes10
					,@CoefMes11 AS Mes11
					,@CoefMes12 AS Mes12
					,0
					,0
	IF UPPER(@pTipo) <> 'C'
		INSERT INTO #Resultado 
			SELECT 'A',0,'','Coeficientes a Aplicar',0,'',''
				,@CoefAplicMes00 AS Mes00 
				,@CoefAplicMes01 AS Mes01
				,@CoefAplicMes02 AS Mes02
				,@CoefAplicMes03 AS Mes03
				,@CoefAplicMes04 AS Mes04
				,@CoefAplicMes05 AS Mes05
				,@CoefAplicMes06 AS Mes06
				,@CoefAplicMes07 AS Mes07
				,@CoefAplicMes08 AS Mes08
				,@CoefAplicMes09 AS Mes09
				,@CoefAplicMes10 AS Mes10
				,@CoefAplicMes11 AS Mes11
				,@CoefAplicMes12 AS Mes12
				,0
				,0
END

IF UPPER(@pTipo) IN ('H','A','D')
BEGIN
	DECLARE AjusInfla CURSOR FOR 
		SELECT P.Id_Cta_Contable,P.Nro_Cta_Contable,P.Descripcion,P.Alias,ISNULL(I.Id_Centro_Costo,''),ISNULL(CC.Descripcion,''),Isnull(P.Id_Alias_Cta_Ajust_Inf,0)
			FROM Pla_Ctas_Cuentas_Contables P, Asientos A, Asientos_Items I, Centro_Costos CC
			WHERE P.Id_Plan_Cta = @pId_Plan_Cta 
			AND ISNULL(P.Monetaria,0) = 0 
			AND P.Imputable = 1
			AND I.Id_Cta_Contable = P.Id_Cta_Contable
			AND A.Id_Asiento = I.Id_Asiento
			AND CC.Id_Centro_Costo = I.Id_Centro_Costo
			AND A.Fecha >= @pFDesde
			AND A.Fecha <  @pFHasta
			GROUP BY P.Id_Cta_Contable,P.Nro_Cta_Contable,P.Descripcion,P.Alias,I.Id_Centro_Costo,CC.Descripcion,P.Id_Alias_Cta_Ajust_Inf
			ORDER BY P.Nro_Cta_Contable,I.Id_Centro_Costo

    OPEN AjusInfla
	FETCH NEXT FROM AjusInfla INTO @Id_Cta_Contable, @Nro_Cta_Contable, @Descripcion ,@Alias, @Id_Centro_Costo, @Descripcion_CC,@AliasCtaAju
					

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Mes00 = dbo.CF_Cta_Cont_Saldo_Asi	(@pFDesde  ,              DBO.CF_EOMonth(@pFDesde) , @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',dbo.CF_xParam('Asi_Tipo_Apertura') )
   	    SET @Mes01 = dbo.CF_Cta_Cont_Saldo		(@pFDesde  ,              DBO.CF_EOMonth(@pFDesde) , @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1) 

		SET @Mes01 = @Mes01 - @Mes00

		IF dbo.CF_FOMONTH(DATEADD(MM, 1,@pFDesde)) <= @pFHasta 
			SET @Mes02 = dbo.CF_Cta_Cont_Saldo( dbo.CF_FOMONTH(DATEADD(MM, 1,@pFDesde)),DBO.CF_EOMonth(DATEADD(MM, 1,@pFDesde)), @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1)
		IF dbo.CF_FOMONTH(DATEADD(MM, 2,@pFDesde)) <= @pFHasta 
			SET @Mes03 = dbo.CF_Cta_Cont_Saldo( dbo.CF_FOMONTH(DATEADD(MM, 2,@pFDesde)),DBO.CF_EOMonth(DATEADD(MM, 2,@pFDesde)), @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1)
		IF dbo.CF_FOMONTH(DATEADD(MM, 3,@pFDesde)) <= @pFHasta 
			SET @Mes04 = dbo.CF_Cta_Cont_Saldo( dbo.CF_FOMONTH(DATEADD(MM, 3,@pFDesde)),DBO.CF_EOMonth(DATEADD(MM, 3,@pFDesde)), @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1)
		IF dbo.CF_FOMONTH(DATEADD(MM, 4,@pFDesde)) <= @pFHasta 
			SET @Mes05 = dbo.CF_Cta_Cont_Saldo( dbo.CF_FOMONTH(DATEADD(MM, 4,@pFDesde)),DBO.CF_EOMonth(DATEADD(MM, 4,@pFDesde)), @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1)
		IF dbo.CF_FOMONTH(DATEADD(MM, 5,@pFDesde)) <= @pFHasta 
			SET @Mes06 = dbo.CF_Cta_Cont_Saldo( dbo.CF_FOMONTH(DATEADD(MM, 5,@pFDesde)),DBO.CF_EOMonth(DATEADD(MM, 5,@pFDesde)), @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1)
		IF dbo.CF_FOMONTH(DATEADD(MM, 6,@pFDesde)) <= @pFHasta 
			SET @Mes07 = dbo.CF_Cta_Cont_Saldo( dbo.CF_FOMONTH(DATEADD(MM, 6,@pFDesde)),DBO.CF_EOMonth(DATEADD(MM, 6,@pFDesde)), @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1)
		IF dbo.CF_FOMONTH(DATEADD(MM, 7,@pFDesde)) <= @pFHasta 
			SET @Mes08 = dbo.CF_Cta_Cont_Saldo( dbo.CF_FOMONTH(DATEADD(MM, 7,@pFDesde)),DBO.CF_EOMonth(DATEADD(MM, 7,@pFDesde)), @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1)
		IF dbo.CF_FOMONTH(DATEADD(MM, 8,@pFDesde)) <= @pFHasta 
			SET @Mes09 = dbo.CF_Cta_Cont_Saldo( dbo.CF_FOMONTH(DATEADD(MM, 8,@pFDesde)),DBO.CF_EOMonth(DATEADD(MM, 8,@pFDesde)), @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1)
		IF dbo.CF_FOMONTH(DATEADD(MM, 9,@pFDesde)) <= @pFHasta 
			SET @Mes10 = dbo.CF_Cta_Cont_Saldo( dbo.CF_FOMONTH(DATEADD(MM, 9,@pFDesde)),DBO.CF_EOMonth(DATEADD(MM, 9,@pFDesde)), @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1)
		IF dbo.CF_FOMONTH(DATEADD(MM, 10,@pFDesde)) <= @pFHasta 
			SET @Mes11 = dbo.CF_Cta_Cont_Saldo( dbo.CF_FOMONTH(DATEADD(MM,10,@pFDesde)),DBO.CF_EOMonth(DATEADD(MM,10,@pFDesde)), @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1)
		IF dbo.CF_FOMONTH(DATEADD(MM, 11,@pFDesde)) <= @pFHasta 
			SET @Mes12 = dbo.CF_Cta_Cont_Saldo( dbo.CF_FOMONTH(DATEADD(MM,11,@pFDesde)),DBO.CF_EOMonth(DATEADD(MM,11,@pFDesde)), @Alias, @pId_Plan_Cta,0,1,@Id_Centro_Costo,0,0,'',1)	

	    INSERT INTO #ValorH (Id_Cta_Contable,Nro_Cta_Contable,Descripcion,Alias,Id_Centro_Costo, Descripcion_CC,
						Mes00,Mes01,Mes02,Mes03,Mes04,Mes05,Mes06,Mes07,Mes08,Mes09,Mes10,Mes11,Mes12,AliasCtaAju)
				VALUES (@Id_Cta_Contable, @Nro_Cta_Contable, @Descripcion ,@Alias, @Id_Centro_Costo, @Descripcion_CC
					,@Mes00,@Mes01,@Mes02,@Mes03,@Mes04,@Mes05,@Mes06,@Mes07,@Mes08,@Mes09,@Mes10,@Mes11,@Mes12,@AliasCtaAju)

		FETCH NEXT FROM AjusInfla INTO @Id_Cta_Contable, @Nro_Cta_Contable, @Descripcion ,@Alias, @Id_Centro_Costo, @Descripcion_CC,@AliasCtaAju
	END
	CLOSE AjusInfla
	DEALLOCATE AjusInfla

	INSERT INTO #Resultado 
		SELECT 'H',Id_Cta_Contable,Nro_Cta_Contable,Descripcion,Alias, Id_Centro_Costo, Descripcion_CC,
					Mes00,
					Mes01,
					Mes02,
					Mes03,
					Mes04,
					Mes05,
					Mes06,
					Mes07,
					Mes08,
					Mes09,
					Mes10,
					Mes11,
					Mes12,
					Mes00 + Mes01 + Mes02 + Mes03 + Mes04 + Mes05 + Mes06 + Mes07 + Mes08 + Mes09 + Mes10 + Mes11 + Mes12,
					AliasCtaAju
				FROM #ValorH
END


IF UPPER(@pTipo) IN ('A','D')
BEGIN
	INSERT INTO #Resultado 
	SELECT 	'A',Id_Cta_Contable 
			,Nro_Cta_Contable
			,Descripcion
			,Alias
			,Id_Centro_Costo
			,Descripcion_CC 
			,Mes00 * @CoefAplicMes00 AS Mes00
			,Mes01 * @CoefAplicMes01 AS Mes01
			,Mes02 * @CoefAplicMes02 AS Mes02
			,Mes03 * @CoefAplicMes03 AS Mes03
			,Mes04 * @CoefAplicMes04 AS Mes04
			,Mes05 * @CoefAplicMes05 AS Mes05
			,Mes06 * @CoefAplicMes06 AS Mes06
			,Mes07 * @CoefAplicMes07 AS Mes07
			,Mes08 * @CoefAplicMes08 AS Mes08
			,Mes09 * @CoefAplicMes09 AS Mes09
			,Mes10 * @CoefAplicMes10 AS Mes10
			,Mes11 * @CoefAplicMes11 AS Mes11
			,Mes12 * @CoefAplicMes12 AS Mes12
			,(Mes00 * @CoefAplicMes00) + (Mes01 * @CoefAplicMes01) + (Mes02 * @CoefAplicMes02) + (Mes03 * @CoefAplicMes03) + (Mes04 * @CoefAplicMes04) + (Mes05 * @CoefAplicMes05) + (Mes06 * @CoefAplicMes06) +
			 (Mes07 * @CoefAplicMes07) + (Mes08 * @CoefAplicMes08) + (Mes09 * @CoefAplicMes09) + (Mes10 * @CoefAplicMes10) + (Mes11 * @CoefAplicMes11) + (Mes12 * @CoefAplicMes12)
			,AliasCtaAju
			FROM  #ValorH
END

IF UPPER(@pTipo) IN ('D') 
	INSERT INTO #Resultado 
		SELECT 	'D',Id_Cta_Contable 
			,Nro_Cta_Contable
			,Descripcion
			,Alias 
			,Id_Centro_Costo
			,Descripcion_CC 
			,(Mes00 * @CoefAplicMes00) - Mes00  AS Mes00
			,(Mes01 * @CoefAplicMes01) - Mes01  AS Mes01
			,(Mes02 * @CoefAplicMes02) - Mes02  AS Mes02
			,(Mes03 * @CoefAplicMes03) - Mes03  AS Mes03
			,(Mes04 * @CoefAplicMes04) - Mes04  AS Mes04
			,(Mes05 * @CoefAplicMes05) - Mes05  AS Mes05
			,(Mes06 * @CoefAplicMes06) - Mes06  AS Mes06
			,(Mes07 * @CoefAplicMes07) - Mes07  AS Mes07
			,(Mes08 * @CoefAplicMes08) - Mes08  AS Mes08
			,(Mes09 * @CoefAplicMes09) - Mes09  AS Mes09
			,(Mes10 * @CoefAplicMes10) - Mes10  AS Mes10
			,(Mes11 * @CoefAplicMes11) - Mes11  AS Mes11
			,(Mes12 * @CoefAplicMes12) - Mes12  AS Mes12
			,((Mes00 * @CoefAplicMes00) - Mes00) + ((Mes01 * @CoefAplicMes01) - Mes01) + ((Mes02 * @CoefAplicMes02) - Mes02) + ((Mes03 * @CoefAplicMes03) - Mes03) + ((Mes04 * @CoefAplicMes04) - Mes04) +
			 ((Mes05 * @CoefAplicMes05) - Mes05) + ((Mes06 * @CoefAplicMes06) - Mes06) + ((Mes07 * @CoefAplicMes07) - Mes07) + ((Mes08 * @CoefAplicMes08) - Mes08) +
			 ((Mes09 * @CoefAplicMes09) - Mes09) + ((Mes10 * @CoefAplicMes10) - Mes10) + ((Mes11 * @CoefAplicMes11) - Mes11) + ((Mes12 * @CoefAplicMes12) - Mes12)
			,AliasCtaAju
			FROM  #ValorH


DROP TABLE #ValorH

SELECT * FROM #Resultado

DROP TABLE #Resultado

RETURN


-- EXEC CP_Asientos_AjuInflacion 'C','PES','20170101','20171231',5, 5   --coefcientes
-- EXEC CP_Asientos_AjuInflacion 'F','PES','20170101','20171231',5, 5  --coefcientes a aplicar
-- EXEC CP_Asientos_AjuInflacion 'H','PES','20170101','20171231',5, 5   --Valores Historicos
-- EXEC CP_Asientos_AjuInflacion 'A','PES','20170101','20171231',5, 5   --Valores Actuales
-- EXEC CP_Asientos_AjuInflacion 'D','PES','20170101','20171231',5, 5  --difenrencia
GO


CREATE PROCEDURE [dbo].[CP_Asientos_Control] @fdesde DATETIME, @fhasta DATETIME
AS

DECLARE @Accion VARCHAR(250)  
CREATE TABLE  #Respuesta (Id_Error INT, 
						  Error_Msg VARCHAR(1000),
						  Accion VARCHAR(5000))

-- Control de Alias Duplicados ------------------------------------------------------------------------------- AGREGAR FILTRO FECHA
SET @Accion = 'Debe modificar en el plan de cuentas el alias '
SET @Accion = @Accion + 'indicando el proximo numero disponible de alias'

INSERT INTO #Respuesta
	SELECT 1001 AS Validacion, 
			'Alias Nro.: ' + RTRIM(CONVERT(VARCHAR(15),Alias)) + 
			' de Cuenta Contable Duplicado, Plan de Cuentas: ' + RTRIM(CONVERT(VARCHAR(15),Id_Plan_Cta)) AS Mensaje, 
			@Accion AS Accion
	FROM (SELECT Id_Plan_Cta, Alias, COUNT(*) AS Cantidad FROM Pla_Ctas_Cuentas_Contables 
			GROUP BY Id_Plan_Cta, Alias
			HAVING COUNT(*) > 1) aux1 

-- Control de Alias Diferentes con Plan de Cuentas ----------------------------------------------------------- AGREGAR FILTRO FECHA
INSERT INTO #Respuesta
	SELECT 1002 AS Validacion, 
		   'El Alias Nro.: ' + RTRIM(CONVERT(VARCHAR(15),Id_Alias_Cta_Cont)) + 
		   ' de la cuenta contable: ' + RTRIM(CONVERT(VARCHAR(15),Id_Cta_Contable)) + 
		   ' No equivale a su Alias: ' + RTRIM(CONVERT(VARCHAR(15),p_alias)) AS Mensaje,
		   'Se debe corregir el asiento contable Nro. ' + RTRIM(CONVERT(VARCHAR(15),Id_Asiento)) + ' Item: ' + RTRIM(CONVERT(VARCHAR(15),Item)) AS Accion
	FROM (SELECT I.*, P.Alias AS p_alias
			FROM Asientos_Items I, Pla_Ctas_Cuentas_Contables P
			WHERE I.Id_Cta_Contable = P.Id_Cta_Contable
				AND I.Id_Alias_Cta_Cont <> P.Alias) aux1

-- Control de Cuentas de Otro Ejercicio ------------------------------------------------------------------------ AGREGAR FILTRO FECHA
INSERT INTO #Respuesta
	SELECT 1003 AS Validacion,
		   'La cuenta contable: ' + RTRIM(CONVERT(VARCHAR(15),Id_Cta_Contable)) +
		   ' no pertenece al plan de cuentas, La Cuenta del Periodo es: ' + RTRIM(CONVERT(VARCHAR(15),cuenta_cont_valida)) AS Mensaje,
		   'Se debe corregir el asiento contable Nro. ' + RTRIM(CONVERT(VARCHAR(15),Id_Asiento)) + ' Item: ' + RTRIM(CONVERT(VARCHAR(15),Item)) AS Accion
	FROM  (SELECT I.*, dbo.CF_Cta_Cont(I.Id_Alias_Cta_Cont,a.Fecha) AS cuenta_cont_valida
			 FROM Asientos_Items I, Asientos A, Pla_Ctas_Cuentas_Contables P, Plan_Ctas PC, Plan_Ctas_Ejercicios PE
			 WHERE I.Id_Cta_Contable = P.Id_Cta_Contable
				 AND A.Id_Asiento = I.Id_Asiento
				 AND P.Id_Plan_Cta = PC.Id_Plan_Cta
				 AND PC.Id_Ejercicio = PE.Id_Ejercicio
				 AND (A.Fecha < PE.Fecha_Inicio or A.Fecha >= PE.Fecha_Cierre + 1)) aux1

-- Control de Id_Cta_Contable Unido con Alias ------------------------------------------------------------------ AGREGAR FILTRO FECHA
INSERT INTO #Respuesta
	SELECT 1005 AS Validacion,
		   'La cuenta contable: ' + RTRIM(CONVERT(VARCHAR(15),Id_Cta_Contable)) +
		   ' no se corresponde con su alias en el plan de cuentas, Asiento: ' + RTRIM(CONVERT(VARCHAR(15),Id_Asiento)) +
		   ' Item: ' + RTRIM(CONVERT(VARCHAR(15),Item)) AS Mensaje,
		   'Se debe corregir el asiento contable Nro. ' + RTRIM(CONVERT(VARCHAR(15),Id_Asiento)) + ' Item: '+ RTRIM(CONVERT(VARCHAR(15),Item)) AS Accion
	FROM (SELECT I.*
			FROM Asientos_Items I, Asientos A, Pla_Ctas_Cuentas_Contables P, Plan_Ctas PC, Plan_Ctas_Ejercicios PE
			WHERE A.Id_Asiento = I.Id_Asiento
				 AND P.Id_Plan_Cta = PC.Id_Plan_Cta
				 AND PC.Id_Ejercicio = PE.Id_Ejercicio
				 AND P.Id_Plan_Cta = A.Id_Plan_Cta
				 AND P.Alias = I.Id_Alias_Cta_Cont
				 AND I.Id_Cta_Contable <> P.Id_Cta_Contable) aux1

-- Control de Asientos Resumenes
INSERT INTO #Respuesta
	SELECT 1006 AS Validacion,
		   'El Asiento Nro.' + RTRIM(CONVERT(VARCHAR(15),Id_Asiento)) + ' - ' + RTRIM(CONVERT(varchar(15),Descripcion))+
		   ' de Fecha ' + RTRIM(CONVERT(VARCHAR(15),CONVERT(DATE,Fecha))) +
		   ' Presenta Diferencia de ' + RTRIM(CONVERT(VARCHAR(15),Dif_Debe_Control)) + ' en su asiento resumen ' AS Mensaje,
		   'Se debe Generar el Asiento Resumen ' AS Accion
	FROM (SELECT A.Id_Asiento, A.Fecha, A.Descripcion, A.Importe, O.debe AS Total_Debe_Control, A.Importe - O.debe AS Dif_Debe_Control,
				 O.haber AS Total_Haber_Control, A.Importe - O.Haber AS Dif_Haber_Control  
			FROM Asientos A, (select C.Id_Asiento, SUM(DEBE) AS debe, SUM(HABER) AS haber 
								FROM Cbtes_Ctas_Contables O, cbtes C 
								WHERE C.Id_Trans = O.Id_Trans
									AND C.Id_Estado_Cbte NOT IN (0,3) 
									AND C.Periodo_Iva >= @fdesde
									AND C.Periodo_Iva < @fhasta + 1
								GROUP BY C.Id_Asiento) O
			WHERE O.Id_Asiento = A.Id_Asiento) aux1 
	WHERE Dif_Debe_Control <> 0 OR Dif_Haber_Control <> 0

-- Control de Centro de Costos en NULO
DECLARE @CCNull INT
SET @CCNull = ISNULL((SELECT COUNT(*) FROM  Asientos_Items I, Asientos A 
						WHERE I.id_Asiento = A.id_Asiento 
						AND A.Fecha >= @fdesde 
						AND A.Fecha < @fhasta + 1
						AND I.Id_Centro_Costo IS NULL),0)
IF @CCNull > 0
BEGIN
	UPDATE Asientos_Items SET Id_Centro_Costo = '' FROM Asientos_Items I, Asientos A WHERE I.id_Asiento = A.id_Asiento AND A.Fecha >= @fdesde AND A.Fecha < @fhasta + 1 AND I.Id_Centro_Costo IS NULL
	INSERT INTO #Respuesta VALUES (1007,'Cantidad de Asientos_Items con Id_Centro_Costos en NULO: ' + CAST(@CCNull AS VARCHAR(10)),'Corregido')
END

-- Control de Cuentas Imputables como Cuentas Padres
INSERT INTO #Respuesta
SELECT 1008, 
	   'La cuenta contable: ' + RTRIM(CONVERT(VARCHAR(15),P.Id_Cta_Contable)) + ' ('+ RTRIM(P.Descripcion) +') del ejercicio ' + RTRIM(E.Descripcion) 
	   + ' esta configurada como cuenta imputable y es cuenta padre' AS Mensaje,
	   'Se debe configurar la misma como no imputable y corregir los asientos con esta cuenta' AS Accion
FROM Pla_Ctas_Cuentas_Contables P
	JOIN Plan_Ctas PC ON P.Id_Plan_Cta = PC.Id_Plan_Cta
	JOIN Plan_Ctas_Ejercicios E ON PC.Id_Ejercicio = E.Id_Ejercicio
WHERE P.Imputable = 1
	AND @fdesde BETWEEN E.Fecha_Inicio AND E.Fecha_Cierre
	AND @fhasta BETWEEN E.Fecha_Inicio AND E.Fecha_Cierre
	AND P.Alias IN (SELECT Id_Cuenta_Padre 
						FROM Pla_Ctas_Cuentas_Contables B 
						WHERE B.Id_Plan_Cta = P.Id_Plan_Cta)

-- Control de Cuentas Padres no Imputables con Asientos Imputados
INSERT INTO #Respuesta
SELECT 1009, 
	   'La cuenta contable: ' + RTRIM(CONVERT(VARCHAR(15),P.Id_Cta_Contable)) + ' ('+ RTRIM(P.Descripcion) +') del ejercicio ' + RTRIM(E.Descripcion) 
	   + ' esta configurada como cuenta no imputable y tiene asientos imputados' AS Mensaje,
	   'Se debe corregir el asiento codigo ' + RTRIM(CONVERT(VARCHAR(15),A.Id_Asiento)) + ' ('+ RTRIM(A.Descripcion) +') del ejercicio ' + RTRIM(E.Descripcion) AS Accion
FROM Pla_Ctas_Cuentas_Contables P
	JOIN Plan_Ctas PC ON P.Id_Plan_Cta = PC.Id_Plan_Cta
	JOIN Plan_Ctas_Ejercicios E ON PC.Id_Ejercicio = E.Id_Ejercicio
	JOIN Asientos A ON P.Id_Plan_Cta = PC.Id_Plan_Cta
	JOIN Asientos_Items I ON A.Id_Asiento = I.Id_Asiento AND P.Id_Cta_Contable = I.Id_Cta_Contable
WHERE P.Imputable = 0
	AND @fdesde BETWEEN E.Fecha_Inicio AND E.Fecha_Cierre
	AND @fhasta BETWEEN E.Fecha_Inicio AND E.Fecha_Cierre
	AND P.Alias IN (SELECT Id_Cuenta_Padre 
						FROM Pla_Ctas_Cuentas_Contables B 
						WHERE B.Id_Plan_Cta = P.Id_Plan_Cta)


SELECT * FROM #Respuesta
DROP TABLE #Respuesta
GO


CREATE PROCEDURE dbo.CP_Banco_Roela_RX @Linea CHAR(166)
AS 

/*
LOG VERSIONES:
12/05/2022 09:33Hs (F)	Creado
12/05/2022 11:00Hs (F)	1) Corrección para compatibilidad con BOC. 
				2) Si el 5 digito del codigo de Barra no es un 1 no es un codigo de barra informado por nosotros y no lo procesamos

*/

DECLARE @aFchPago				VARCHAR(8)
DECLARE @aFchAcreditacion			VARCHAR(8)
DECLARE @aFch1Vto				VARCHAR(8)
DECLARE @aImportePagado			VARCHAR(11)
DECLARE @aIdentificador_Usuario		VARCHAR(8)
DECLARE @aIdentificador_Concepto		VARCHAR(1)
DECLARE @aCodigoBarras			VARCHAR(59)
DECLARE @aIdentificador_Comprobante	VARCHAR(20)
DECLARE @aCanal_Cobro			VARCHAR(3)
DECLARE @aCod_Rechazo			VARCHAR(3)
DECLARE @aDescrip_Rechazo			VARCHAR(20)
DECLARE @aFiller				VARCHAR(17)

DECLARE @Fecha_Pago				DATETIME
DECLARE @Fecha_Acreditacion			DATETIME
DECLARE @Fecha_1Vto				DATETIME
DECLARE @Importe_Pagado			DECIMAL(12,2)
DECLARE @Id_Trans				INT
DECLARE @Cod_Rechazo				VARCHAR(3)
DECLARE @Descrip_Rechazo			VARCHAR(20)
DECLARE @Canal_Cobro				VARCHAR(3)
DECLARE @Canal_Cobro_Descrip		VARCHAR(100)
DECLARE @Id_Tar_Lote				INT

DECLARE @Informado_Fecha_1Vto		DATETIME
DECLARE @Informado_Fecha_2Vto		DATETIME
DECLARE @Informado_Fecha_3Vto		DATETIME
DECLARE @Informado_Importe_1Vto		DECIMAL(12,2)
DECLARE @Informado_Importe_2Vto		DECIMAL(12,2)
DECLARE @Informado_Importe_3Vto		DECIMAL(12,2)
DECLARE @Id_Concepto_Cod_Barra		VARCHAR(1)

SET @aFchPago				= SUBSTRING(@Linea, 1, 8)
SET @aFchAcreditacion		= SUBSTRING(@Linea, 9, 8)
SET @aFch1Vto				= SUBSTRING(@Linea, 17, 8)
SET @aImportePagado			= SUBSTRING(@Linea, 25, 11)
SET @aIdentificador_Usuario		= SUBSTRING(@Linea, 36, 8)
SET @aIdentificador_Concepto	= SUBSTRING(@Linea, 44, 1)
SET @aCodigoBarras			= SUBSTRING(@Linea, 45, 59)
SET @aIdentificador_Comprobante	= SUBSTRING(@Linea, 104, 20)
SET @aCanal_Cobro			= SUBSTRING(@Linea, 124, 3)
SET @aCod_Rechazo			= SUBSTRING(@Linea, 127, 3)
SET @aDescrip_Rechazo		= SUBSTRING(@Linea, 130, 20)
SET @aFiller				= SUBSTRING(@Linea, 150, 17)

SET @Fecha_Pago			= CONVERT(DATETIME, @aFchPago)
SET @Fecha_Acreditacion		= CONVERT(DATETIME, @aFchAcreditacion)
SET @Fecha_1Vto			= CONVERT(DATETIME, @aFch1Vto)
SET @Importe_Pagado			= CONVERT(DECIMAL(12,2), (CONVERT(DECIMAL, @aImportePagado) / 100))
SET @Cod_Rechazo			= CONVERT(VARCHAR(3), @aCod_Rechazo)
SET @Descrip_Rechazo			= CONVERT(VARCHAR(20), @aDescrip_Rechazo)
SET @Canal_Cobro			= CONVERT(VARCHAR(3), @aCanal_Cobro)
SET @Id_Concepto_Cod_Barra		= SUBSTRING(@aCodigoBarras, 5, 1)


SET @Canal_Cobro_Descrip =	CASE
					WHEN @aCanal_Cobro = 'RP' 	THEN 'Rapipago'
					WHEN @aCanal_Cobro = 'PF' 	THEN 'Pago Facil'
					WHEN @aCanal_Cobro = 'PP' 	THEN 'Provincia Pagos'
					WHEN @aCanal_Cobro = 'LK' 	THEN 'Link Pagos'
					WHEN @aCanal_Cobro = 'PC' 	THEN 'Pago Mis Cuentas'
					WHEN @aCanal_Cobro = 'DD+' 	THEN 'Cobranza de Debito Directo'
					WHEN @aCanal_Cobro = 'DD-' 	THEN 'Reversion de Debito Directo'
					WHEN @aCanal_Cobro = 'DDR' 	THEN 'Rechazo de Debito Directo'
					WHEN @aCanal_Cobro = 'MC' 	THEN 'Mastercard'
					WHEN @aCanal_Cobro = 'MCR' 	THEN 'Rechazo de Mastercard'
					WHEN @aCanal_Cobro = 'ASJ' 	THEN 'Plus Pagos'
					WHEN @aCanal_Cobro = 'BM' 	THEN 'Banco Municipal'
					WHEN @aCanal_Cobro = 'BR' 	THEN 'Bancor'
					WHEN @aCanal_Cobro = 'RSF' 	THEN 'Rapipago Sin Factura'
					WHEN @aCanal_Cobro = 'PSF' 	THEN 'Provincia Pagos Sin Factura'
					WHEN @aCanal_Cobro = 'VS' 	THEN 'Visa'
					WHEN @aCanal_Cobro = 'VSR' 	THEN 'Rechazo de Visa'
					WHEN @aCanal_Cobro = 'FSF' 	THEN 'Pago Facil Sin Factura'
					WHEN @aCanal_Cobro = 'BOC' 	THEN 'Boton Otros Creditos'
					WHEN @aCanal_Cobro = 'BOD' 	THEN 'Boton Otros Debito'
					WHEN @aCanal_Cobro = 'ASF' 	THEN 'Plus Pagos Sin Factura'
					WHEN @aCanal_Cobro = 'RO' 	THEN 'Banco Roela Caja'
					WHEN @aCanal_Cobro = 'BPD' 	THEN 'Boton Pago Debito'
					WHEN @aCanal_Cobro = 'BPC' 	THEN 'Boton Pago Credito'
					WHEN @aCanal_Cobro = 'BPR' 	THEN 'Rechazo de Boton de Pago'
					WHEN @aCanal_Cobro = 'CE' 	THEN 'Cobro Express'
					WHEN @aCanal_Cobro = 'CEF' 	THEN 'Cobro Express Sin Factura'
					WHEN @aCanal_Cobro = 'PCO' 	THEN 'Pago Mis Cuentas en linea'
					WHEN @aCanal_Cobro = 'LKO' 	THEN 'Link Pagos en linea'
					WHEN @aCanal_Cobro = 'PCV' 	THEN 'PC alta en linea vencida'
					WHEN @aCanal_Cobro = 'LKV' 	THEN 'LK alta en linea vencida'
					WHEN @aCanal_Cobro = 'TI' 	THEN 'Transferencia SNP, Link, Interbanking'
					WHEN @aCanal_Cobro = 'TII' 	THEN 'Transferencia SNP, Link, Interbanking Inmobiliarias'
					ELSE 'Otro Canal no identificado'
				END

SET @Id_Trans		= 0

SET @Id_Trans		=	CASE
					WHEN @aCanal_Cobro = 'RP' AND @Id_Concepto_Cod_Barra = '1' THEN CONVERT(INT, @aIdentificador_Usuario)	/*Si el 5 digito del codigo de Barra no es un 1 no es un codigo de barra informado por nosotros y no lo procesamos*/
					WHEN @aCanal_Cobro = 'PF' AND @Id_Concepto_Cod_Barra = '1' THEN CONVERT(INT, @aIdentificador_Usuario)	/*Si el 5 digito del codigo de Barra no es un 1 no es un codigo de barra informado por nosotros y no lo procesamos*/
					WHEN @aCanal_Cobro = 'PP' 	THEN 'Provincia Pagos'
					WHEN @aCanal_Cobro = 'LK' 	THEN CONVERT(INT, SUBSTRING(@aIdentificador_Comprobante, 1, 15))
					WHEN @aCanal_Cobro = 'PC' 	THEN CONVERT(INT, SUBSTRING(@aIdentificador_Comprobante, 1, 15))
					WHEN @aCanal_Cobro = 'DD+' 	THEN 'Cobranza de Debito Directo'
					WHEN @aCanal_Cobro = 'DD-' 	THEN 'Reversion de Debito Directo'
					WHEN @aCanal_Cobro = 'DDR' 	THEN 'Rechazo de Debito Directo'
					WHEN @aCanal_Cobro = 'MC' 	THEN 'Mastercard'
					WHEN @aCanal_Cobro = 'MCR' 	THEN 'Rechazo de Mastercard'
					WHEN @aCanal_Cobro = 'ASJ' 	THEN 'Plus Pagos'
					WHEN @aCanal_Cobro = 'BM' 	THEN 'Banco Municipal'
					WHEN @aCanal_Cobro = 'BR' 	THEN 'Bancor'
					WHEN @aCanal_Cobro = 'RSF' 	THEN 'Rapipago Sin Factura'
					WHEN @aCanal_Cobro = 'PSF' 	THEN 'Provincia Pagos Sin Factura'
					WHEN @aCanal_Cobro = 'VS' 	THEN 'Visa'
					WHEN @aCanal_Cobro = 'VSR' 	THEN 'Rechazo de Visa'
					WHEN @aCanal_Cobro = 'FSF' 	THEN 'Pago Facil Sin Factura'
					WHEN @aCanal_Cobro = 'BOC' 	THEN 0 /* 'Boton Otros Creditos', es algo pagado directamente por el kiosk por lo tanto ya se proceso*/
					WHEN @aCanal_Cobro = 'BOD' 	THEN 0 /* 'Boton Otros Debito', es algo pagado directamente por el kiosk por lo tanto ya se proceso*/
					WHEN @aCanal_Cobro = 'ASF' 	THEN 'Plus Pagos Sin Factura'
					WHEN @aCanal_Cobro = 'RO' 	THEN 'Banco Roela Caja'
					WHEN @aCanal_Cobro = 'BPD' 	THEN 0 /* 'Boton Pago Debito', es algo pagado directamente por el kiosk por lo tanto ya se proceso*/
					WHEN @aCanal_Cobro = 'BPC' 	THEN 0	/* 'Boton Pago Credito', es algo pagado directamente por el kiosk por lo tanto ya se proceso*/
					WHEN @aCanal_Cobro = 'BPR' 	THEN 0 /* 'Rechazo de Boton de Pago', es algo pagado directamente por el kiosk por lo tanto ya se proceso*/
					WHEN @aCanal_Cobro = 'CE' 	THEN 'Cobro Express'
					WHEN @aCanal_Cobro = 'CEF' 	THEN 'Cobro Express Sin Factura'
					WHEN @aCanal_Cobro = 'PCO' 	THEN 'Pago Mis Cuentas en linea'
					WHEN @aCanal_Cobro = 'LKO' 	THEN 'Link Pagos en linea'
					WHEN @aCanal_Cobro = 'PCV' 	THEN 'PC alta en linea vencida'
					WHEN @aCanal_Cobro = 'LKV' 	THEN 'LK alta en linea vencida'
					WHEN @aCanal_Cobro = 'TI' 	THEN 'Transferencia SNP, Link, Interbanking'
					WHEN @aCanal_Cobro = 'TII' 	THEN 'Transferencia SNP, Link, Interbanking Inmobiliarias'
					ELSE 0
				END

SET @Id_Tar_Lote		= 0

IF(@Id_Trans > 0)
BEGIN
	SET @Id_Tar_Lote	=	CASE
						WHEN @aCanal_Cobro = 'RP' 	THEN ISNULL((SELECT TOP 1 ISNULL(Id_Tar_Lote, 0) FROM Val_Tarjetas_Lotes_Items WHERE Id_Trans = @Id_Trans AND (Importe = @Importe_Pagado OR Importe_2Vto = @Importe_Pagado OR Importe_3Vto = @Importe_Pagado) ORDER BY Id_Tar_Lote DESC), 0) /*No viene detallado el Lote*/
						WHEN @aCanal_Cobro = 'PF' 	THEN ISNULL((SELECT TOP 1 ISNULL(Id_Tar_Lote, 0) FROM Val_Tarjetas_Lotes_Items WHERE Id_Trans = @Id_Trans AND (Importe = @Importe_Pagado OR Importe_2Vto = @Importe_Pagado OR Importe_3Vto = @Importe_Pagado) ORDER BY Id_Tar_Lote DESC), 0) /*No viene detallado el Lote*/
						WHEN @aCanal_Cobro = 'PP' 	THEN 'Provincia Pagos'
						WHEN @aCanal_Cobro = 'LK' 	THEN CONVERT(INT, SUBSTRING(@aIdentificador_Comprobante, 16, 5))
						WHEN @aCanal_Cobro = 'PC' 	THEN CONVERT(INT, SUBSTRING(@aIdentificador_Comprobante, 16, 5))
						WHEN @aCanal_Cobro = 'DD+' 	THEN 'Cobranza de Debito Directo'
						WHEN @aCanal_Cobro = 'DD-' 	THEN 'Reversion de Debito Directo'
						WHEN @aCanal_Cobro = 'DDR' 	THEN 'Rechazo de Debito Directo'
						WHEN @aCanal_Cobro = 'MC' 	THEN 'Mastercard'
						WHEN @aCanal_Cobro = 'MCR' 	THEN 'Rechazo de Mastercard'
						WHEN @aCanal_Cobro = 'ASJ' 	THEN 'Plus Pagos'
						WHEN @aCanal_Cobro = 'BM' 	THEN 'Banco Municipal'
						WHEN @aCanal_Cobro = 'BR' 	THEN 'Bancor'
						WHEN @aCanal_Cobro = 'RSF' 	THEN 'Rapipago Sin Factura'
						WHEN @aCanal_Cobro = 'PSF' 	THEN 'Provincia Pagos Sin Factura'
						WHEN @aCanal_Cobro = 'VS' 	THEN 'Visa'
						WHEN @aCanal_Cobro = 'VSR' 	THEN 'Rechazo de Visa'
						WHEN @aCanal_Cobro = 'FSF' 	THEN 'Pago Facil Sin Factura'
						WHEN @aCanal_Cobro = 'BOC' 	THEN 0 /*'Boton Otros Creditos', es algo pagado directamente por el kiosk por lo tanto ya se proceso*/
						WHEN @aCanal_Cobro = 'BOD' 	THEN 0 /*'Boton Otros Debito', es algo pagado directamente por el kiosk por lo tanto ya se proceso*/
						WHEN @aCanal_Cobro = 'ASF' 	THEN 'Plus Pagos Sin Factura'
						WHEN @aCanal_Cobro = 'RO' 	THEN 'Banco Roela Caja'
						WHEN @aCanal_Cobro = 'BPD' 	THEN 0 /* Boton Pago Debito, es algo pagado directamente por el kiosk por lo tanto ya se proceso*/
						WHEN @aCanal_Cobro = 'BPC' 	THEN 0	/* Boton Pago Credito, es algo pagado directamente por el kiosk por lo tanto ya se proceso*/
						WHEN @aCanal_Cobro = 'BPR' 	THEN 0 /* Rechazo de Boton de Pago, es algo pagado directamente por el kiosk por lo tanto ya se proceso*/
						WHEN @aCanal_Cobro = 'CE' 	THEN 'Cobro Express'
						WHEN @aCanal_Cobro = 'CEF' 	THEN 'Cobro Express Sin Factura'
						WHEN @aCanal_Cobro = 'PCO' 	THEN 'Pago Mis Cuentas en linea'
						WHEN @aCanal_Cobro = 'LKO' 	THEN 'Link Pagos en linea'
						WHEN @aCanal_Cobro = 'PCV' 	THEN 'PC alta en linea vencida'
						WHEN @aCanal_Cobro = 'LKV' 	THEN 'LK alta en linea vencida'
						WHEN @aCanal_Cobro = 'TI' 	THEN 'Transferencia SNP, Link, Interbanking'
						WHEN @aCanal_Cobro = 'TII' 	THEN 'Transferencia SNP, Link, Interbanking Inmobiliarias'
						ELSE 0
					END
END

IF (@Id_Tar_Lote <> 0 AND @Id_Trans <> 0)
BEGIN
	SELECT
	@Informado_Fecha_1Vto		= ISNULL(VTL.Fecha_1_Vto, '19000101'),
	@Informado_Fecha_2Vto		= ISNULL(VTL.Fecha_2_Vto, '19000101'),
	@Informado_Fecha_3Vto		= ISNULL(VTL.Fecha_3_Vto, '19000101'),
	@Informado_Importe_1Vto		= ISNULL(VTLI.Importe, 0),
	@Informado_Importe_2Vto		= ISNULL(VTLI.Importe_2Vto, 0),
	@Informado_Importe_3Vto		= ISNULL(VTLI.Importe_3Vto, 0)
	FROM Val_Tarjetas_Lotes VTL, Val_Tarjetas_Lotes_Items VTLI
	WHERE
	VTL.Id_Tar_Lote = VTLI.Id_Tar_Lote	
	AND VTL.Id_Tar_Lote = @Id_Tar_Lote
	AND VTLI.Id_Trans = @Id_Trans
END


SELECT 
@Id_Trans			AS Id_Trans,
@Id_Tar_Lote			AS Id_Tar_Lote,
@Importe_Pagado		AS Importe_Pagado,
@Fecha_Pago			AS Fecha_Pago,
@Fecha_Acreditacion		AS Fecha_Acreditacion,
@Fecha_1Vto			AS Fecha_1Vto,
@Cod_Rechazo			AS Cod_Rechazo,
@Descrip_Rechazo		AS Descrip_Rechazo,
@Canal_Cobro			AS Id_Canal_Cobro,
@Canal_Cobro_Descrip		AS Canal_Cobro,
@Informado_Fecha_1Vto	AS Informado_Fecha_1Vto,
@Informado_Fecha_2Vto	AS Informado_Fecha_2Vto,
@Informado_Fecha_3Vto	AS Informado_Fecha_3Vto,
@Informado_Importe_1Vto	AS Informado_Importe_1Vto,
@Informado_Importe_2Vto	AS Informado_Importe_2Vto,
@Informado_Importe_3Vto	AS Informado_Importe_3Vto,
@aCodigoBarras		AS Codigo_Barras
--,@aIdentificador_Usuario
--,@aIdentificador_Comprobante

--Pago Mis Cuentas (Envian Id_Trans + Id_Tar_Lote para identificarlo)
