CREATE PROCEDURE [dbo].[CP_Browse_Cbtes_Pedidos]	@pId_Cliente		INT,
												@pId_Estado_Cbte	SMALLINT
AS
BEGIN

DECLARE @sqlStr		NVARCHAR(4000)

CREATE TABLE #BrowsePedidos (Comprobante	VARCHAR(50),
							UN				CHAR(10),
							Fecha			DATE,
							Cliente			INT,
							Razon_Social	VARCHAR(100),
							Suc				SMALLINT, 
							F_Estimada		DATE,
							DP_1			VARCHAR(100),
							DP_2			VARCHAR(100),
							O_Compra		VARCHAR(25),
							Id_Estado_Cbte	SMALLINT,
							Estado			VARCHAR(35),
							Importe			DECIMAL(12,2),
							Trans			INT)

SET @sqlStr =	N'SELECT ' +
				' dbo.CF_Descrip_Cbte(CB.Id_Trans) AS Comprobante, ' +
				' EUN.Id_Unid_Negocio AS UN, ' +
				--' CONVERT(DATE, CB.Fecha) AS Fecha, ' +
				' TR.Fecha_Mov AS Fecha, ' +
				' CL.Id_Cliente AS Cliente, ' +
				' CL.Razon_Social, ' +
				' CB.Id_Sucursal AS Suc, ' +
				' CONVERT(DATE, CB.Fecha_Estimada) AS F_Estimada, ' +
				' CB.Nota_Part1 AS DP_1, ' +
				' CB.Nota_Part2 AS DP_2,' +
				' CB.Cbte_Nro_Externo AS O_Compra, ' +
				' CB.Id_Estado_Cbte AS Id_Estado_Cbte, ' +
				' CE.Descripcion AS Estado, ' +
				' CB.Imp_Total AS Importe, ' +
				' CB.Id_Trans AS Trans ' +
				' FROM Cbtes CB, Cbtes_Tipos CT, Cbtes_Estados CE, Empresas_Unid_Negocios EUN, Clientes CL, Transacciones TR ' +
				' WHERE ' +
				' CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte ' +
				' AND CB.Id_Estado_Cbte = CE.Id_Estado_Cbte ' +
				' AND ISNULL(CT.Id_Unid_Negocio, '''') = EUN.Id_Unid_Negocio ' +
				' AND CB.Id_Cliente = CL.Id_Cliente ' +
				' AND CB.Id_Trans = TR.Id_Trans ' +
				' AND CT.Compromete_Pedido IN (1) ' +
				' AND CB.Id_Cliente = ' + CONVERT(VARCHAR(10), @pId_Cliente)

IF(@pId_Estado_Cbte <> -1)
BEGIN
	SET @sqlStr =	@sqlStr + 
					' AND CB.Id_Estado_Cbte = ' + CONVERT(VARCHAR(10), @pId_Estado_Cbte)
END

INSERT INTO #BrowsePedidos
EXECUTE sp_executesql @sqlStr


SELECT * FROM #BrowsePedidos

DROP TABLE #BrowsePedidos

END
GO


CREATE PROCEDURE [dbo].[CP_Browse_Productos_Precios_Elegir] @pId_Cliente		INT
AS
BEGIN

DECLARE @sqlStr						NVARCHAR(4000)
DECLARE @Id_Lista_Precio			SMALLINT
DECLARE @Id_Lista_Precio_Especial	SMALLINT --Agregada el 06/02/2019 por Pedido de Cirugia

CREATE TABLE #BrowseProductosPreciosElegir (Codigo					VARCHAR(14),
											Descripcion_Producto	VARCHAR(150),
											Precio_Sin_Iva			DECIMAL(13,4),
											Precio_Con_Iva			DECIMAL(13,4),
											Stock_Fisico			DECIMAL(19,4),
											Stock_Pedido			DECIMAL(19,4), 
											Stock_Orden_Compra		DECIMAL(19,4),
											Familia					VARCHAR(35),
											Codigo_Externo			VARCHAR(40),
											Descripcion_Reducida	VARCHAR(100),
											Presentacion_Codigo		VARCHAR(10),
											Presentacion_Descripcion VARCHAR(50),
											Foto_Grande				VARCHAR(255),
											Cantidad				DECIMAL(13,4)
											)

SELECT
@Id_Lista_Precio =  ISNULL(Id_Lista_Precio, 0),
@Id_Lista_Precio_Especial = ISNULL(Id_Precio_Especial, 0)
FROM Clientes
WHERE
Id_Cliente = @pId_Cliente


IF(@Id_Lista_Precio = 0)
BEGIN
	SET @sqlStr =	N'SELECT '+
					'ISNULL(PR.Id_Producto, '''') AS Codigo, '+
					'ISNULL(PR.Descripcion_Detallada, '''') AS Descripcion_Producto, '+
					'ISNULL(PR.Precio_Gravado, 0) AS Precio_Sin_Iva, '+
					'ISNULL(PR.Precio_Final, 0) AS Precio_Con_Iva, '+
					'dbo.CF_Prod_Stock(PR.Id_Producto, GETDATE()) AS Stock_Fisico, '+
					'0 AS Stock_Pedido, '+
					'0 AS Stock_Orden_Compra, '+
					'ISNULL(PF.Descripcion, '''') AS Familia, '+
					'ISNULL(PR.Id_Producto_Externo, '''') AS Codigo_Externo, '+
					'ISNULL(PR.Descripcion_Resumida, '''') AS Descripcion_Reducida, '+
					'ISNULL(PR.Id_Present, '''') AS Presentacion_Codigo, '+
					'ISNULL(PP.Descripcion, '''') AS Presentacion_Descripcion, '+
					'ISNULL(PR.Foto_Grande, '''') AS Foto_Grande, '+
					'ISNULL(PR.Cantidad, 0) AS Cantidad '+
					'FROM Productos PR, Prod_Familias PF, Prod_Present PP '+
					'WHERE '+
					'ISNULL(PR.Id_Familia, 0) = PF.Id_Familia '+
					'AND ISNULL(PR.Id_Present, '''') = PP.Id_Present '+
					'AND ISNULL(PR.Id_Producto, '''') <> '''' '+
					'AND ISNULL(PR.Activo, 0) = 1 '+
					'ORDER BY PR.Descripcion_Detallada'
END
ELSE
BEGIN
	IF(@Id_Lista_Precio_Especial = 0)
	BEGIN
		SET @sqlStr =	N'SELECT '+
						'ISNULL(PR.Id_Producto, '''') AS Codigo, '+
						'ISNULL(PR.Descripcion_Detallada, '''') AS Descripcion_Producto, '+
						'ISNULL(PLPI.Precio, 0) AS Precio_Sin_Iva, '+
						'(ISNULL(PLPI.Precio, 0) * (1 + (ISNULL(PT.Porc1, 0)/100))) AS Precio_Con_Iva, '+
						'dbo.CF_Prod_Stock(PR.Id_Producto, GETDATE()) AS Stock_Fisico, '+
						'0 AS Stock_Pedido, '+
						'0 AS Stock_Orden_Compra, '+
						'ISNULL(PF.Descripcion, '''') AS Familia, '+
						'ISNULL(PR.Id_Producto_Externo, '''') AS Codigo_Externo, '+
						'ISNULL(PR.Descripcion_Resumida, '''') AS Descripcion_Reducida, '+
						'ISNULL(PR.Id_Present, '''') AS Presentacion_Codigo, '+
						'ISNULL(PP.Descripcion, '''') AS Presentacion_Descripcion, '+
						'ISNULL(PR.Foto_Grande, '''') AS Foto_Grande, '+
						'ISNULL(PR.Cantidad, 0) AS Cantidad '+
						'FROM Productos PR, Prod_Familias PF, Prod_Present PP, Prod_Listas_Precios_Items PLPI, Productos_TasaIva PT '+
						'WHERE '+
						'ISNULL(PR.Id_Familia, 0) = PF.Id_Familia '+
						'AND PR.Id_Producto = PLPI.Id_Producto '+
						'AND ISNULL(PR.Id_Iva, '''') = PT.Id_Iva '+
						'AND ISNULL(PR.Id_Present, '''') = PP.Id_Present '+
						'AND ISNULL(PR.Id_Producto, '''') <> '''' '+
						'AND ISNULL(PR.Activo, 0) = 1 '+
						'AND ISNULL(PLPI.Id_Lista_Precio, 0) = '+ CONVERT(VARCHAR(10), @Id_Lista_Precio) + ' ' +
						'ORDER BY PR.Descripcion_Detallada'
	END
	ELSE
	BEGIN
		SET @sqlStr =	N'SELECT '+
						'ISNULL(PR.Id_Producto, '''') AS Codigo, '+
						'ISNULL(PR.Descripcion_Detallada, '''') AS Descripcion_Producto, '+
						'ISNULL(PLPI.Precio, 0) AS Precio_Sin_Iva, '+
						'(ISNULL(PLPI.Precio, 0) * (1 + (ISNULL(PT.Porc1, 0)/100))) AS Precio_Con_Iva, '+
						'dbo.CF_Prod_Stock(PR.Id_Producto, GETDATE()) AS Stock_Fisico, '+
						'0 AS Stock_Pedido, '+
						'0 AS Stock_Orden_Compra, '+
						'ISNULL(PF.Descripcion, '''') AS Familia, '+
						'ISNULL(PR.Id_Producto_Externo, '''') AS Codigo_Externo, '+
						'ISNULL(PR.Descripcion_Resumida, '''') AS Descripcion_Reducida, '+
						'ISNULL(PR.Id_Present, '''') AS Presentacion_Codigo, '+
						'ISNULL(PP.Descripcion, '''') AS Presentacion_Descripcion, '+
						'ISNULL(PR.Foto_Grande, '''') AS Foto_Grande, '+
						'ISNULL(PR.Cantidad, 0) AS Cantidad '+
						'FROM Productos PR, Prod_Familias PF, Prod_Present PP, Prod_Listas_Precios_Items PLPI, Productos_TasaIva PT '+
						'WHERE '+
						'ISNULL(PR.Id_Familia, 0) = PF.Id_Familia '+
						'AND PR.Id_Producto = PLPI.Id_Producto '+
						'AND ISNULL(PR.Id_Iva, '''') = PT.Id_Iva '+
						'AND ISNULL(PR.Id_Present, '''') = PP.Id_Present '+
						'AND ISNULL(PR.Id_Producto, '''') <> '''' '+
						'AND ISNULL(PR.Activo, 0) = 1 '+
						'AND ISNULL(PLPI.Id_Lista_Precio, 0) IN ('+ CONVERT(VARCHAR(10), @Id_Lista_Precio) + ', ' + CONVERT(VARCHAR(10), @Id_Lista_Precio_Especial) + ') ' +
						'ORDER BY PR.Descripcion_Detallada'
	END
END

INSERT INTO #BrowseProductosPreciosElegir
EXECUTE sp_executesql @sqlStr


SELECT * FROM #BrowseProductosPreciosElegir

DROP TABLE #BrowseProductosPreciosElegir

END
GO


CREATE PROCEDURE [dbo].[CP_Browse_SCA_Clientes_Elegir]	@pTipo_Validacion	CHAR(1),		/*'T': Tag | 'D': Documento | 'H': Huella | 'B': Codigo Barras | 'M': Data Matrix | 'R': Razon_Social*/
													@pTag				VARCHAR(30),	/*Credencial MiFare / Wiegand*/
													@pDoc				BIGINT,			/*Documento*/
													@pHue				VARCHAR(5000),	/*Huella Dactilar*/
													@pCba				VARCHAR(20),	/*Codigo de Barra*/
													@pDma				VARCHAR(5000),	/*Data Matrix*/
													@pRazon_Social		VARCHAR(100),	/*Razon_Social*/
													@pId_Cliente_Externo VARCHAR(14)	/*Nro. Socio*/
	
AS
/*Declaracion Variables Locales*/
DECLARE @Mensaje				VARCHAR(100)
DECLARE @Id_Cliente				INT
/*Fin de Declaraciones Variables Locales */

PRINT 'Procedimiento: CP_Browse_SCA_Clientes_Elegir'

CREATE TABlE #Clientes_SCA_Elegir		(Codigo				INT,
										Activo				TINYINT,
										Nro_Socio			VARCHAR(14),
										Apellido_Nombre		VARCHAR(100),
										Apellido			VARCHAR(100),
										Nombre				VARCHAR(100),
										Sexo				CHAR(1),
										Id_Tipo_Cli			SMALLINT,
										Categoria			VARCHAR(50),
										Fecha_Nac			DATETIME,
										Tipo_Doc			CHAR(3),
										Doc_Nro				BIGINT,
										Ult_Cuota_Paga		DATETIME,
										Credencial_Nro		VARCHAR(30),
										Legajo				VARCHAR(30),
										Tipo_Persona		CHAR(1))

BEGIN TRY
	BEGIN TRAN

		IF(@pTipo_Validacion NOT IN ('T', 'D', 'H', 'B', 'M', 'R', 'N'))
		BEGIN
			SET @Mensaje = 'El Tipo de Validaci├│n es inv├ílido'
			
			SELECT	 1000			AS ErrorNumber 
			,0						AS ErrorSeverity  
			,0						AS ErrorState 
			,0						AS ErrorProcedure  
			,0						AS ErrorLine		
			,@Mensaje				AS ErrorMessage
			,0						AS Id_Cliente
		END
		
		IF(@pTipo_Validacion = 'T')
		BEGIN			
			INSERT INTO #Clientes_SCA_Elegir
			SELECT TOP 1
			CL.Id_Cliente AS Codigo,
			CL.Activo,
			CL.Id_Cliente_Externo AS Nro_Socio,
			CL.Razon_Social AS Apellido_Nombre,
			CL.Apellido,
			CL.Nombre,
			CL.Sexo,
			CT.Id_Tipo_Cli,
			CT.Descripcion,
			CL.Fecha_Nac,
			CL.Id_Tipo_Doc AS Tipo_Doc,
			CL.Doc_Nro,
			CL.Ult_Cuota_Paga,
			CL.Credencial_Nro,
			CL.Legajo,
			CL.Tipo_Persona
			FROM Clientes CL, Clientes_Tipos CT
			WHERE
			ISNULL(CL.Id_Tipo_Cli, 0) = CT.Id_Tipo_Cli
			AND CL.Credencial_Nro = @pTag
			ORDER BY CL.Activo DESC, CL.Id_Cliente DESC
		END

		IF(@pTipo_Validacion = 'D')
		BEGIN			
			INSERT INTO #Clientes_SCA_Elegir
			SELECT TOP 1
			CL.Id_Cliente AS Codigo,
			CL.Activo,
			CL.Id_Cliente_Externo AS Nro_Socio,
			CL.Razon_Social AS Apellido_Nombre,
			CL.Apellido,
			CL.Nombre,
			CL.Sexo,
			CT.Id_Tipo_Cli,
			CT.Descripcion,
			CL.Fecha_Nac,
			CL.Id_Tipo_Doc AS Tipo_Doc,
			CL.Doc_Nro,
			CL.Ult_Cuota_Paga,
			CL.Credencial_Nro,
			CL.Legajo,
			CL.Tipo_Persona
			FROM Clientes CL, Clientes_Tipos CT
			WHERE
			ISNULL(CL.Id_Tipo_Cli, 0) = CT.Id_Tipo_Cli
			AND ((CL.Doc_Nro = @pDoc) OR (CL.Id_Cliente_Externo LIKE '%' + CONVERT(VARCHAR(20), @pDoc) + '%'))
			ORDER BY CL.Activo DESC, CL.Id_Cliente DESC
		END

		IF(@pTipo_Validacion = 'H')
		BEGIN
			INSERT INTO #Clientes_SCA_Elegir
			SELECT TOP 1
			CL.Id_Cliente AS Codigo,
			CL.Activo,
			CL.Id_Cliente_Externo AS Nro_Socio,
			CL.Razon_Social AS Apellido_Nombre,
			CL.Apellido,
			CL.Nombre,
			CL.Sexo,
			CT.Id_Tipo_Cli,
			CT.Descripcion,
			CL.Fecha_Nac,
			CL.Id_Tipo_Doc AS Tipo_Doc,
			CL.Doc_Nro,
			CL.Ult_Cuota_Paga,
			CL.Credencial_Nro,
			CL.Legajo,
			CL.Tipo_Persona
			FROM Clientes CL, Clientes_Tipos CT
			WHERE
			ISNULL(CL.Id_Tipo_Cli, 0) = CT.Id_Tipo_Cli
			AND CL.Id_Cliente IN (SELECT Id_Cliente FROM Clientes_HD WHERE Huella = CONVERT(VARBINARY(2000), @pHue))
			ORDER BY CL.Activo DESC, CL.Id_Cliente DESC
		END

		IF(@pTipo_Validacion = 'B')
		BEGIN
			SET @Id_Cliente = 0 /*No implementado*/
		END

		IF(@pTipo_Validacion = 'M')
		BEGIN
			SET @Id_Cliente = 0 /*No implementado*/	
		END
		
		IF(@pTipo_Validacion = 'R')
		BEGIN
			INSERT INTO #Clientes_SCA_Elegir
			SELECT TOP 1
			CL.Id_Cliente AS Codigo,
			CL.Activo,
			CL.Id_Cliente_Externo AS Nro_Socio,
			CL.Razon_Social AS Apellido_Nombre,
			CL.Apellido,
			CL.Nombre,
			CL.Sexo,
			CT.Id_Tipo_Cli,
			CT.Descripcion,
			CL.Fecha_Nac,
			CL.Id_Tipo_Doc AS Tipo_Doc,
			CL.Doc_Nro,
			CL.Ult_Cuota_Paga,
			CL.Credencial_Nro,
			CL.Legajo,
			CL.Tipo_Persona
			FROM Clientes CL, Clientes_Tipos CT
			WHERE
			ISNULL(CL.Id_Tipo_Cli, 0) = CT.Id_Tipo_Cli
			AND ((CL.Razon_Social LIKE '%' + @pRazon_Social + '%') OR (CL.Id_Cliente_Externo LIKE '%' + @pRazon_Social + '%'))
			ORDER BY CL.Activo DESC, CL.Id_Cliente DESC
		END

		IF(@pTipo_Validacion = 'N')
		BEGIN
			INSERT INTO #Clientes_SCA_Elegir
			SELECT TOP 1
			CL.Id_Cliente AS Codigo,
			CL.Activo,
			CL.Id_Cliente_Externo AS Nro_Socio,
			CL.Razon_Social AS Apellido_Nombre,
			CL.Apellido,
			CL.Nombre,
			CL.Sexo,
			CT.Id_Tipo_Cli,
			CT.Descripcion,
			CL.Fecha_Nac,
			CL.Id_Tipo_Doc AS Tipo_Doc,
			CL.Doc_Nro,
			CL.Ult_Cuota_Paga,
			CL.Credencial_Nro,
			CL.Legajo,
			CL.Tipo_Persona
			FROM Clientes CL, Clientes_Tipos CT
			WHERE
			ISNULL(CL.Id_Tipo_Cli, 0) = CT.Id_Tipo_Cli
			AND CL.Id_Cliente_Externo LIKE '%' + @pId_Cliente_Externo + '%'
			ORDER BY CL.Activo DESC, CL.Id_Cliente DESC
		END
		
		SELECT * FROM #Clientes_SCA_Elegir

		DROP TABLE #Clientes_SCA_Elegir

		COMMIT
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH
GO


CREATE PROCEDURE [dbo].CP_CBTE_ANULAR_REVERSION @ID_TRANS INT
AS 
DECLARE @Mensaje			VARCHAR(100)
BEGIN TRY
BEGIN TRAN


IF ((SELECT Id_Estado_cbte FROM CBTES WHERE ID_TRANS = @ID_TRANS) <> 1) 
	BEGIN
	    SET @Mensaje = 'El cbte debe estar en Estado Pendiente'
		ROLLBACK
		SELECT	 1099		    	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,@Mensaje			AS ErrorMessage
		RETURN 1
	END


		DECLARE @trans_nueva INTEGER
		DECLARE @NRO_CBTE INTEGER
	    declare @desc varchar(50)
		declare @fecha_mov datetime
		declare @user smallint
		declare @id_cond_vta  smallint
        declare @id_tipo_cbte varchar(5)
		Declare @Id_Estado_Cbte_Rever smallint

		SET @id_cond_vta = (SELECT id_cond_vta from cbtes where id_trans = @ID_TRANS) 
		SET @trans_nueva = (SELECT max(id_trans) from transacciones ) + 1
		SET @desc = (SELECT descripcion from transacciones where id_trans = @ID_TRANS) 
		SET @fecha_mov = (SELECT fecha_mov from transacciones where id_trans = @ID_TRANS) 
		SET @user = (SELECT id_usuario from transacciones where id_trans = @ID_TRANS) 
		SET @id_tipo_cbte = (SELECT Isnull(Id_tipo_cbte_Rever,'')  From cbtes_Tipos T, Cbtes C where C.Id_Tipo_Cbte = T.Id_Tipo_Cbte And C.id_trans = @ID_TRANS) 

		IF @id_tipo_cbte = ''
			BEGIN
				SET @Mensaje = 'El Cbte de Reversi¾n debe estar definido'
				ROLLBACK
				SELECT	 880		    	AS ErrorNumber 
						,0					AS ErrorSeverity  
						,0					AS ErrorState 
						,0					AS ErrorProcedure  
						,0					AS ErrorLine		
						,@Mensaje			AS ErrorMessage
				RETURN 1
			END		

		SET @Id_Estado_Cbte_Rever = (SELECT Isnull(Id_Estado_cbte,1)  From cbtes_Tipos where Id_Tipo_Cbte = @id_tipo_cbte) 
			    
						
        ----------------------------- Primero los insert ----------------------------------
        INSERT INTO TRANSACCIONES
			(id_trans,descripcion,fecha_mov,id_usuario)
			values (@trans_nueva,@desc,@fecha_mov,@user)

               SELECT * INTO #CBTES_aux_sp FROM CBTES WHERE ID_TRANS = @ID_TRANS

               SELECT * INTO #CBTES_ITEMS_aux_sp FROM CBTES_ITEMS WHERE ID_TRANS = @ID_TRANS

               SELECT * INTO #Clientes_CtaCte_aux_sp FROM Clientes_CtaCte WHERE ID_TRANS = @ID_TRANS

	           SELECT * INTO #Cbtes_Reten_aux_sp FROM Cbtes_Reten WHERE ID_TRANS = @ID_TRANS

	           SELECT * INTO #Cbtes_Ctas_Contables_aux_sp FROM Cbtes_Ctas_Contables WHERE ID_TRANS = @ID_TRANS

               ALTER TABLE #Cbtes_Ctas_Contables_aux_sp ADD IMPORTE DECIMAL(14,2)

               -----------------------------Actualizo id_trans -----------------------------------------------

		update #CBTES_aux_sp set id_trans = @trans_nueva , id_tipo_cbte = @id_tipo_cbte, Id_Estado_Cbte = @Id_Estado_Cbte_Rever
		               ,Fecha = Getdate(), Periodo_Iva = Getdate(), Periodo = Getdate(), Fecha_Venc = Getdate()
					   ,Nro_Auto_Trib = '',Cai_Vence = NULL
                       where id_trans = @ID_TRANS

		update #CBTES_ITEMS_aux_sp set id_trans = @trans_nueva  where id_trans = @ID_TRANS

		update #Clientes_CtaCte_aux_sp set id_trans = @trans_nueva, Importe = Importe * -1
	                 	,Saldo = Saldo*-1, Fecha = Getdate(),Fecha_Vence = Getdate()  
					    where id_trans = @ID_TRANS

		update #Cbtes_Reten_aux_sp set id_trans = @trans_nueva, Importe = Importe * -1
	                 	,Fecha = Getdate()  
					    where id_trans = @ID_TRANS

		update #Cbtes_Ctas_Contables_aux_sp set IMPORTE = HABER
					    where id_trans = @ID_TRANS 

		update #Cbtes_Ctas_Contables_aux_sp set HABER = DEBE 
					    where id_trans = @ID_TRANS
						
		update #Cbtes_Ctas_Contables_aux_sp set Id_trans = @trans_nueva, Fecha =  Getdate(), DEBE = IMPORTE,
		                Id_Cta_Contable = (SELECT dbo.CF_Cta_Cont(Alias,  Getdate()))
					    where id_trans = @ID_TRANS					
						
		ALTER TABLE #Cbtes_Ctas_Contables_aux_sp DROP COLUMN IMPORTE									  
   -----------------------------agrego -----------------------------------------------

               INSERT INTO CBTES
                      SELECT * FROM  #CBTES_aux_sp WHERE ID_TRANS = @trans_nueva    

               INSERT INTO CBTES_ITEMS
                      SELECT * FROM #CBTES_ITEMS_aux_sp WHERE ID_TRANS = @trans_nueva 

               INSERT INTO Clientes_CtaCte
                      SELECT * FROM #Clientes_CtaCte_aux_sp WHERE ID_TRANS = @trans_nueva

               INSERT INTO Cbtes_Reten
                      SELECT * FROM #Cbtes_Reten_aux_sp WHERE ID_TRANS = @trans_nueva

               INSERT INTO Cbtes_Ctas_Contables
                      SELECT * FROM #Cbtes_Ctas_Contables_aux_sp WHERE ID_TRANS = @trans_nueva

               UPDATE Clientes_CtaCte SET Descripcion = dbo.CF_Cbte_Descrip(@trans_nueva) WHERE ID_TRANS = @trans_nueva
   ----------------------------- borro -----------------------------------------------

               DROP TABLE #CBTES_aux_sp 
               DROP TABLE #CBTES_ITEMS_aux_sp 
               DROP TABLE #Clientes_CtaCte_aux_sp 
		       DROP TABLE #Cbtes_Reten_aux_sp 
		       DROP TABLE #Cbtes_Ctas_Contables_aux_sp 


COMMIT
SELECT	 0					AS ErrorNumber 
		,0					AS ErrorSeverity  
		,0					AS ErrorState 
		,0					AS ErrorProcedure  
		,@trans_nueva		AS ErrorLine		
		,@Mensaje			AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;   




-- exec CP_CBTE_ANULAR_REVERSION 37362
GO



CREATE PROCEDURE dbo.CP_CC_Prorrateo_Cta	@Id_Prorrateo	SMALLINT, 
											@Debe			DECIMAL(16,2), 
											@Haber			DECIMAL(16,2),
											@pPeriodo_Iva	DATETIME
AS 
BEGIN
SET NOCOUNT ON

DECLARE @Id_Centro_Costo			CHAR(10)
DECLARE @Porc						DECIMAL(10,5)
DECLARE @Tot_Debe					DECIMAL(16,2)
DECLARE @Tot_Haber					DECIMAL(16,2)
DECLARE @Id_Alias_Cta_Cont			SMALLINT
DECLARE @Id_Cta_Contable			INT
DECLARE @Nro_Cta_Contable			VARCHAR(20)
DECLARE @Cta_Contable_Descripcion	VARCHAR(80)

SELECT 
Id_Centro_Costo,
@Debe						AS Debe, 
@Haber						AS Haber,
@Id_Alias_Cta_Cont			AS Id_Alias_Cta_Cont,
@Id_Cta_Contable			AS Id_Cta_Contable,
@Nro_Cta_Contable			AS Nro_Cta_Contable,
@Cta_Contable_Descripcion	AS Cta_Contable_Descripcion
INTO #TmpProrra
FROM Centro_Costos 
WHERE 
1=0

DECLARE CurTmpProrra CURSOR FOR 
SELECT 
ISNULL(I.Id_Centro_Costo,''), 
ISNULL((I.Porc / 100), 0), 
ISNULL(I.Id_Alias_Cta_Cont, 0)
FROM Centro_Costos_Prorra_Items I
WHERE 
I.Id_Prorrateo = @Id_Prorrateo
					

OPEN CurTmpProrra
FETCH NEXT FROM CurTmpProrra INTO @Id_Centro_Costo, @Porc, @Id_Alias_Cta_Cont
WHILE @@FETCH_STATUS=0
BEGIN
	SET @Id_Cta_Contable			= ISNULL(dbo.CF_Cta_Cont(@Id_Alias_Cta_Cont, @pPeriodo_Iva), 0)
	
	SELECT 
	@Nro_Cta_Contable			= LTRIM(RTRIM(ISNULL(Nro_Cta_Contable, ''))),
	@Cta_Contable_Descripcion	= LTRIM(RTRIM(ISNULL(Descripcion, ''))) 
	FROM Pla_Ctas_Cuentas_Contables 
	WHERE 
	Id_Cta_Contable = @Id_Cta_Contable

	INSERT INTO #TmpProrra 
	(Id_Centro_Costo,		Debe,						Haber, 
	Id_Alias_Cta_Cont,		Id_Cta_Contable,			Cta_Contable_Descripcion,
	Nro_Cta_Contable)
	VALUES 
	(@Id_Centro_Costo,		ISNULL(@Debe * @Porc,0),	ISNULL(@Haber * @Porc,0), 
	@Id_Alias_Cta_Cont,		@Id_Cta_Contable,			@Cta_Contable_Descripcion,
	@Nro_Cta_Contable)

	FETCH NEXT FROM CurTmpProrra INTO @Id_Centro_Costo, @Porc, @Id_Alias_Cta_Cont
END
CLOSE CurTmpProrra
DEALLOCATE CurTmpProrra


SET @Tot_Debe  = ISNULL((SELECT SUM(ISNULL(Debe, 0))  FROM #TmpProrra), 0)
SET @Tot_Haber = ISNULL((SELECT SUM(ISNULL(Haber, 0)) FROM #TmpProrra), 0)


IF (@Tot_Debe <> 0 AND @Tot_Debe <> @Debe)
BEGIN
   UPDATE #TmpProrra 
   SET 
   Debe = Debe + @Tot_Debe - @Debe 
   WHERE 
   Id_Centro_Costo = @Id_Centro_Costo
END


IF (@Tot_Haber <> 0 AND @Tot_Haber <> @Haber)
BEGIN
   UPDATE #TmpProrra 
   SET 
   Haber = Haber + (@Haber - @Tot_Haber) 
   WHERE 
   Id_Centro_Costo = @Id_Centro_Costo
END



SELECT 
T.Id_Centro_Costo, 
C.Descripcion, 
T.Debe, 
T.Haber, 
T.Id_Alias_Cta_Cont,
T.Id_Cta_Contable,
T.Nro_Cta_Contable,
T.Cta_Contable_Descripcion
FROM #TmpProrra T, Centro_Costos C
WHERE 
T.Id_Centro_Costo = C.Id_Centro_Costo

DROP TABLE #TmpProrra
END

