GO


CREATE PROCEDURE [dbo].[CP_CD_Controladores_Novedades_Agregar]	@pJson VARCHAR(8000)
AS

/*Variables recibidas por parámetro a traves del JSON*/
DECLARE @pId_Cliente				INT
DECLARE @pCredencial_Nro_Anterior	VARCHAR(30)

SET @pId_Cliente					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pCredencial_Nro_Anterior		= ISNULL(LTRIM(RTRIM(CONVERT(VARCHAR(30), dbo.CF_JSON_VALUE(@pJson,'Credencial_Nro_Anterior')))), '')
/*FIN Variables recibidas por parámetro a traves del JSON*/

/*Declaracion de Variables*/
DECLARE @Id_Novedad_Max	INT
DECLARE @Id_Controlador	INT
DECLARE @Razon_Social	VARCHAR(100)
DECLARE @Credencial_Nro	VARCHAR(30)
DECLARE @Cant_Huellas	TINYINT
/*FIN Declaracion de Variables*/

/*Si existen novedades pendientes Anteriores las completa para que esta sea la última*/
UPDATE CD_Controladores_Novedades
SET
Estado_Sincr	= 'C',
Id_Usuario		= -1
WHERE
Id_Cliente = @pId_Cliente
AND Estado_Sincr = 'P'
/*FIN Si existen novedades pendientes Anteriores las completa para que esta sea la última*/

SELECT
@Razon_Social	= LTRIM(RTRIM(ISNULL(Razon_Social, ''))),
@Credencial_Nro = LTRIM(RTRIM(ISNULL(Credencial_Nro, '')))
FROM Clientes
WHERE
Id_Cliente = @pId_Cliente

SET @Cant_Huellas = ISNULL((SELECT COUNT(*) FROM Clientes_HD WHERE Id_Cliente = @pId_Cliente),0)

IF(@Credencial_Nro <> '')
BEGIN
	SET @Id_Novedad_Max = ISNULL((SELECT MAX(ISNULL(Id_Novedad, 0)) + 1 FROM CD_Controladores_Novedades), 1)

	DECLARE curControladoresNovedades CURSOR FOR
	SELECT Id_Controlador FROM CD_Controladores
	WHERE
	ISNULL(Tipo_Cont, '') = 'L'
	AND ((SUBSTRING(ISNULL(Nro_Serie, ''), 5, 2) = 'AP') OR (SUBSTRING(ISNULL(Nro_Serie, ''), 5, 2) = 'HP') OR (SUBSTRING(ISNULL(Nro_Serie, ''), 5, 2) = 'SL'))



	OPEN curControladoresNovedades
	FETCH NEXT FROM curControladoresNovedades INTO @Id_Controlador
	WHILE @@FETCH_STATUS = 0
	BEGIN

		INSERT INTO CD_Controladores_Novedades 
		(Id_Controlador,			Id_Novedad,					Fecha_Creacion, 
		Estado_Sincr,				Id_Cliente,					Razon_Social, 
		Credencial_Nro,				Credencial_Nro_Anterior,	Flag_Tiene_Huella)
		VALUES
		(@Id_Controlador,			@Id_Novedad_Max,			GETDATE(), 
		'P',						@pId_Cliente,				@Razon_Social, 
		@Credencial_Nro,			@pCredencial_Nro_Anterior,	@Cant_Huellas)

		FETCH NEXT FROM curControladoresNovedades INTO @Id_Controlador
	END
	CLOSE curControladoresNovedades
	DEALLOCATE curControladoresNovedades
END
GO


CREATE PROCEDURE [dbo].[CP_CD_ES_Rpt_Anual_Ingresos]	@pAnio			SMALLINT,
														@pId_Accesos	VARCHAR(MAX)
AS
BEGIN

DECLARE @Cada_Semana				SMALLINT
DECLARE @Cant_Semanas_Anio			SMALLINT
DECLARE @Inicio_Anio				DATETIME
DECLARE @Inicio_Semana				DATETIME
DECLARE @Fin_Semana					DATETIME
DECLARE @Semana_Nro					VARCHAR(10)
DECLARE @Semana_Periodo				VARCHAR(15)
DECLARE @Cant_Ingresos_Lunes		INT
DECLARE @Cant_Ingresos_Martes		INT
DECLARE @Cant_Ingresos_Miercoles	INT
DECLARE @Cant_Ingresos_Jueves		INT
DECLARE @Cant_Ingresos_Viernes		INT
DECLARE @Cant_Ingresos_Sabados		INT
DECLARE @Cant_Ingresos_Domingos		INT
DECLARE @Cant_Total					INT
DECLARE @CadaAcceso					SMALLINT
DECLARE @SqlStr						NVARCHAR(MAX)
DECLARE @SqlStrCadaDia				NVARCHAR(MAX)
DECLARE @Parametros					NVARCHAR(100)

SET @Parametros = N'@Cant_IngresosOUT INT OUTPUT'; 

CREATE TABLE #CD_Rpt_Anual
(Semanas		VARCHAR(10),
Desde_Hasta		VARCHAR(15),
Lunes			INT,
Martes			INT,
Miercoles		INT,
Jueves			INT,
Viernes			INT,
Sabados			INT,
Domingos		INT,
Total			INT)


SET @Semana_Periodo				= ''
SET @Cada_Semana				= 0
SET @Cant_Semanas_Anio			= 52
SET @Cant_Ingresos_Lunes		= 0
SET @Cant_Ingresos_Martes		= 0
SET @Cant_Ingresos_Miercoles	= 0
SET @Cant_Ingresos_Jueves		= 0
SET @Cant_Ingresos_Viernes		= 0
SET @Cant_Ingresos_Sabados		= 0
SET @Cant_Ingresos_Domingos		= 0
SET @Cant_Total					= 0
SET @Inicio_Anio				= CONVERT(VARCHAR(4), @pAnio) + '0101'

WHILE @Cada_Semana < @Cant_Semanas_Anio
BEGIN   
	SET @Cada_Semana = @Cada_Semana + 1
	
	SET @Semana_Nro = 'Semana ' + RIGHT('00' + CONVERT(VARCHAR(10), @Cada_Semana), 2)
	PRINT @Semana_Nro

	IF(@Cada_Semana = 1)
	BEGIN
		SET @Inicio_Semana	= @Inicio_Anio
		SET @Fin_Semana		= DATEADD(dd, 6, @Inicio_Semana)
	END
	ELSE
	BEGIN
		SET @Inicio_Semana	= DATEADD(dd, 1, @Fin_Semana)
		SET @Fin_Semana		= DATEADD(dd, 6, @Inicio_Semana)
	END

	SET @Semana_Periodo = CONVERT(VARCHAR(5), @Inicio_Semana, 103) + ' al ' + CONVERT(VARCHAR(5), @Fin_Semana, 103)

	IF(ISNULL(@pId_Accesos, '') = '')
	BEGIN
		SET @pId_Accesos = ''

		DECLARE curAccesosSelec CURSOR FOR 
		SELECT Id_Acceso FROM CD_Accesos

		OPEN curAccesosSelec
		FETCH NEXT FROM curAccesosSelec INTO @CadaAcceso
		WHILE @@FETCH_STATUS = 0
		BEGIN
			
			IF(@pId_Accesos = '')
			BEGIN
				SET @pId_Accesos = CONVERT(VARCHAR(10), @CadaAcceso)
			END
			ELSE
			BEGIN
				SET @pId_Accesos = @pId_Accesos + ',' + CONVERT(VARCHAR(10), @CadaAcceso)
			END

		FETCH NEXT FROM curAccesosSelec INTO @CadaAcceso
		END 
		CLOSE curAccesosSelec
		DEALLOCATE curAccesosSelec
		
	END

	DECLARE @Cant_Ingresos INT
	SET @SqlStr = 'SELECT @Cant_IngresosOUT = COUNT(*) FROM CD_ES WHERE Tipo = ''E'' AND Resultado = ''S'' AND Id_Acceso IN (' + @pId_Accesos +')  AND Fecha >= ''' + REPLACE(CONVERT(VARCHAR(10), @Inicio_Semana, 102), '.', '') + ''' AND Fecha < DATEADD(dd, 1, ''' + REPLACE(CONVERT(VARCHAR(10), @Fin_Semana, 102), '.', '') + ''') '

	/*LUNES*/
	SET @SqlStrCadaDia		= @SqlStr + 'AND (DATENAME(dw, Fecha) = ''Lunes'' OR DATENAME(dw, Fecha) = ''Monday'')'
	EXECUTE sp_executesql @SqlStrCadaDia, @Parametros, @Cant_IngresosOUT = @Cant_Ingresos OUTPUT

	SET @Cant_Ingresos_Lunes = @Cant_Ingresos
	PRINT 'Cant Ingresos Lunes: ' + CONVERT(VARCHAR(10), @Cant_Ingresos_Lunes)

	/*MARTES*/
	SET @SqlStrCadaDia		= @SqlStr + 'AND (DATENAME(dw, Fecha) = ''Martes'' OR DATENAME(dw, Fecha) = ''Tuesday'')'
	EXECUTE sp_executesql @SqlStrCadaDia, @Parametros, @Cant_IngresosOUT = @Cant_Ingresos OUTPUT

	SET @Cant_Ingresos_Martes = @Cant_Ingresos
	PRINT 'Cant Ingresos Martes: ' + CONVERT(VARCHAR(10), @Cant_Ingresos_Martes)

	/*MIERCOLES*/
	SET @SqlStrCadaDia		= @SqlStr + 'AND (DATENAME(dw, Fecha) = ''Miércoles'' OR DATENAME(dw, Fecha) = ''Wednesday'')'
	EXECUTE sp_executesql @SqlStrCadaDia, @Parametros, @Cant_IngresosOUT = @Cant_Ingresos OUTPUT

	SET @Cant_Ingresos_Miercoles = @Cant_Ingresos
	PRINT 'Cant Ingresos Miercoles: ' + CONVERT(VARCHAR(10), @Cant_Ingresos_Miercoles)

	/*JUEVES*/
	SET @SqlStrCadaDia		= @SqlStr + 'AND (DATENAME(dw, Fecha) = ''Jueves'' OR DATENAME(dw, Fecha) = ''Thursday'')'
	EXECUTE sp_executesql @SqlStrCadaDia, @Parametros, @Cant_IngresosOUT = @Cant_Ingresos OUTPUT

	SET @Cant_Ingresos_Jueves = @Cant_Ingresos
	PRINT 'Cant Ingresos Jueves: ' + CONVERT(VARCHAR(10), @Cant_Ingresos_Jueves)


	/*VIERNES*/
	SET @SqlStrCadaDia		= @SqlStr + 'AND (DATENAME(dw, Fecha) = ''Viernes'' OR DATENAME(dw, Fecha) = ''Friday'')'
	EXECUTE sp_executesql @SqlStrCadaDia, @Parametros, @Cant_IngresosOUT = @Cant_Ingresos OUTPUT

	SET @Cant_Ingresos_Viernes = @Cant_Ingresos
	PRINT 'Cant Ingresos Viernes: ' + CONVERT(VARCHAR(10), @Cant_Ingresos_Viernes)

	/*SABADO*/
	SET @SqlStrCadaDia		= @SqlStr + 'AND (DATENAME(dw, Fecha) = ''Sábado'' OR DATENAME(dw, Fecha) = ''Saturday'')'
	EXECUTE sp_executesql @SqlStrCadaDia, @Parametros, @Cant_IngresosOUT = @Cant_Ingresos OUTPUT

	SET @Cant_Ingresos_Sabados = @Cant_Ingresos
	PRINT 'Cant Ingresos Sabados: ' + CONVERT(VARCHAR(10), @Cant_Ingresos_Sabados)

	/*DOMIGO*/
	SET @SqlStrCadaDia		= @SqlStr + 'AND (DATENAME(dw, Fecha) = ''Domingo'' OR DATENAME(dw, Fecha) = ''Sunday'')'
	EXECUTE sp_executesql @SqlStrCadaDia, @Parametros, @Cant_IngresosOUT = @Cant_Ingresos OUTPUT

	SET @Cant_Ingresos_Domingos = @Cant_Ingresos
	PRINT 'Cant Ingresos Domingos: ' + CONVERT(VARCHAR(10), @Cant_Ingresos_Domingos)

	/*TOTAL SEMANAL*/
	SET @Cant_Total = @Cant_Ingresos_Lunes + @Cant_Ingresos_Martes + @Cant_Ingresos_Miercoles + @Cant_Ingresos_Jueves + @Cant_Ingresos_Viernes + @Cant_Ingresos_Sabados + @Cant_Ingresos_Domingos
	PRINT 'Cant Total en la semana: ' + CONVERT(VARCHAR(10), @Cant_Total)

	INSERT INTO #CD_Rpt_Anual
	(Semanas,	Desde_Hasta,
	Lunes,		Martes,		Miercoles,
	Jueves,		Viernes,	Sabados,
	Domingos,	Total)
	VALUES
	(@Semana_Nro,			@Semana_Periodo,
	@Cant_Ingresos_Lunes,	@Cant_Ingresos_Martes,		@Cant_Ingresos_Miercoles,
	@Cant_Ingresos_Jueves,	@Cant_Ingresos_Viernes,		@Cant_Ingresos_Sabados,
	@Cant_Ingresos_Domingos,@Cant_Total)
END

SELECT * FROM #CD_Rpt_Anual

DROP TABLE #CD_Rpt_Anual
END
GO


CREATE PROCEDURE [dbo].[CP_CD_ES_Rpt_Global_Ult_Accesos] @pCantUltRegistros INT
AS
BEGIN
    SET NOCOUNT ON

    BEGIN TRY
        
        IF OBJECT_ID('tempdb..#rUlt_Accesos_Global') IS NOT NULL
            DROP TABLE #rUlt_Accesos_Global

        CREATE TABLE #rUlt_Accesos_Global (
            Id_ES           INT,
            Fecha           VARCHAR(10),
            Hora            VARCHAR(10),
            Tipo            VARCHAR(1),
            Id_Tarjeta      VARCHAR(50),
            Id_Cliente      INT,
            Razon_Social    VARCHAR(100),
            Resultado       VARCHAR(1),
            Observacion     VARCHAR(8000),
            Id_Controlador  SMALLINT,
            Controlador     VARCHAR(20),
            Id_Acceso       SMALLINT,
            Acceso          VARCHAR(20)
        )

        INSERT INTO #rUlt_Accesos_Global
        SELECT TOP (@pCantUltRegistros)
            CE.Id_ES,
            CONVERT(VARCHAR(10), CE.Fecha, 102) AS Fecha,
            CONVERT(VARCHAR(10), CE.Fecha, 108) AS Hora,
            CE.Tipo,
            CE.Id_Tarjeta,
            CE.Id_Cliente,
            CL.Razon_Social,
            CE.Resultado,
            CONVERT(VARCHAR(8000), CE.Observacion),
            CE.Id_Controlador,
            LEFT(CC.Descripcion, 20) AS Controlador,
            CE.Id_Acceso,
            CA.Descripcion AS Acceso
        FROM CD_ES CE
        INNER JOIN Clientes CL ON CE.Id_Cliente = CL.Id_Cliente
        INNER JOIN CD_Controladores CC ON CE.Id_Controlador = CC.Id_Controlador
        INNER JOIN CD_Accesos CA ON CE.Id_Acceso = CA.Id_Acceso
        WHERE CONVERT(DATE, CE.Fecha) = CONVERT(DATE, GETDATE())
        ORDER BY CE.Id_ES DESC

        SELECT * FROM #rUlt_Accesos_Global

        DROP TABLE #rUlt_Accesos_Global
    END TRY
    BEGIN CATCH
        -- Captura de error b├ísica
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE()
        RAISERROR('Error en el procedimiento CP_CD_ES_Rpt_Global_Ult_Accesos: %s', 16, 1, @ErrorMessage)
    END CATCH
END
GO


CREATE PROCEDURE [dbo].[CP_CD_Motivos_Habilitacion_Elegir]
AS
/*Declaracion Variables Locales*/
DECLARE @Id_CD_Motivo			INT
DECLARE @Descripcion_Motivo		VARCHAR(5000)
DECLARE @Descripcion_Display	VARCHAR(32)
DECLARE @Descripcion_Pantalla	VARCHAR(100)
DECLARE @Mensaje				VARCHAR(5000)
/*Fin de Declaraciones Variables Locales */

PRINT 'Procedimiento: CP_CD_Motivos_Habilitacion_Elegir'
CREATE TABlE #CD_Motivos_Visibles (Id_CD_Motivo INT, Descripcion VARCHAR(5000))

BEGIN TRY
	BEGIN TRAN


		DECLARE curCDMot CURSOR FOR 
		SELECT
		CM.Id_CD_Motivo,
		ISNULL(CM.Descripcion, ''),
		ISNULL(CM.Descripcion_Display, ''),
		ISNULL(CM.Descripcion_Pantalla, '')
		FROM CD_Motivos CM
		WHERE
		ISNULL(CM.Activo, 0) = 1
		AND ISNULL(CM.Tipo, 'R') = 'H'

		OPEN curCDMot
		FETCH NEXT FROM curCDMot INTO @Id_CD_Motivo, @Descripcion_Motivo, @Descripcion_Display, @Descripcion_Pantalla
		WHILE @@FETCH_STATUS = 0
		BEGIN
			
			PRINT 'Id_CD_Motivo: ' + CONVERT(VARCHAR(10), @Id_CD_Motivo)

			IF(@Descripcion_Pantalla <> '')
			BEGIN
				SET @Mensaje = @Descripcion_Pantalla
			END
			ELSE
			BEGIN
				IF(@Descripcion_Display <> '')
				BEGIN
					SET @Mensaje = @Descripcion_Display
				END
				ELSE
				BEGIN
					SET @Mensaje = @Descripcion_Motivo
				END
			END

			INSERT INTO #CD_Motivos_Visibles
			(Id_CD_Motivo,	Descripcion)
			VALUES
			(@Id_CD_Motivo,	@Mensaje)

			FETCH NEXT FROM curCDMot INTO @Id_CD_Motivo, @Descripcion_Motivo, @Descripcion_Display, @Descripcion_Pantalla
		END 
		CLOSE curCDMot
		DEALLOCATE curCDMot

		SELECT Id_CD_Motivo, Descripcion FROM #CD_Motivos_Visibles ORDER BY Descripcion

		COMMIT
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH
GO


CREATE PROCEDURE [dbo].[CP_Cajas_Movimientos] @Id_Periodo_Caja	VARCHAR(5000) 
												,@Id_Tipo_Valor		CHAR(3)
												,@Id_Moneda			CHAR(3)
												,@Id_Centro_Costo	CHAR(10) 
												,@Filtrar_Fecha		TINYINT 
												,@Fecha_Desde		DATETIME 
												,@Fecha_Hasta		DATETIME

AS 
BEGIN
SET NOCOUNT ON

DECLARE @Sql			VARCHAR(MAX)
DECLARE @SqlSaldo		VARCHAR(MAX)
DECLARE @SqlSelect		VARCHAR(MAX)
DECLARE @SqlFrom		VARCHAR(MAX)
DECLARE @SqlWhere		VARCHAR(MAX)
DECLARE @SqlGroup		VARCHAR(MAX)
DECLARE @TiposValor		VARCHAR(400)

CREATE TABLE #Cajas_Mov  (Fecha DATETIME
						,Concepto VARCHAR(100)
						,Descripcion VARCHAR(300)
						,Cotizacion  DECIMAL(12,5)
						,Tipo VARCHAR(50)
						,Id_Trans INT
						,Renglon_Nro SMALLINT
						,Id_Centro_Costo CHAR(10)
						,Importe DECIMAL(16,2)
						,Imp_Valor DECIMAL(16,2)
						,Ingreso DECIMAL(16,2)
						,Egreso DECIMAL(16,2)
						,Saldo 	DECIMAL(16,2)
						,Id_Moneda char(3)
						,Comprobante_Nro INT
						,Id_Interno INT IDENTITY(1,1))

CREATE TABLE #Renglon_Val_Mov (Id_Trans INT, Renglon_Nro SMALLINT)
CREATE INDEX IX_Val_Mov____ ON  #Renglon_Val_Mov (Id_Trans)
CREATE INDEX IX_Val_Mov2____ ON  #Renglon_Val_Mov (Renglon_Nro)

SET @TiposValor = (SELECT Valor_String From xParametros where IdParametro = 'TVal_Consulta_Caja')

IF @Filtrar_Fecha <> 1
BEGIN
	SET @Filtrar_Fecha = 0
END

-- Calculo de maximo de renglon por transaccion para filtro de consulta principal
SET @SqlSelect = 'SELECT R.Id_Trans, MAX(R.Renglon_Nro) AS Renglon_Nro '

SET @SqlFrom = ' FROM Valores_Mov R
					LEFT JOIN Cbtes C ON R.Id_Trans = C.Id_Trans
					LEFT JOIN Cajas_Mov CM ON R.Id_Trans = CM.Id_Trans
					LEFT JOIN Valores V ON R.Id_Trans = V.Id_Trans '

SET @SqlWhere =	' WHERE R.Id_Estado_Valor NOT IN (7,9)
						AND R.Id_Trans <> 0
						AND C.Id_Estado_Cbte <> 3
						AND CM.Id_Estado_Mov_Caja = 2
						AND R.Id_Periodo_Caja IN ('+ RTRIM(LTRIM(@Id_Periodo_Caja)) +') '

IF ISNULL(@Id_Tipo_Valor,'') <> ''
BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND V.Id_Tipo_Val = '''+  @Id_Tipo_Valor +''''
END
ELSE
BEGIN
    IF ISNULL(@TiposValor,'') <> ''
    BEGIN
	    SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND V.Id_Tipo_Val IN (' + @TiposValor + ')'
    END
END

IF ISNULL(@Id_Moneda,'') <> ''
BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND V.Id_Moneda = ''' + @Id_Moneda + ''''
END

SET @SqlGroup = ' GROUP BY R.Id_Trans'

SET @Sql = @SqlSelect + @SqlFrom + @SqlWhere + @SqlGroup

INSERT INTO #Renglon_Val_Mov
EXEC(@Sql)

SET @Sql = ''
SET @SqlSelect = '' 
SET @SqlFrom = '' 
SET @SqlWhere = '' 
SET @SqlGroup = ''

-- Consulta principal
SET @SqlSelect = 'SELECT CM.FECHA as Fecha
					,ISNULL(CO.Descripcion,CMT.Descripcion)   AS Concepto
					,RTRIM(LTRIM(CM.DESCRIPCION)) + '' '' + RTRIM(LTRIM(ISNULL(C.Destinatario,''''))) as Descripcion
					,ISNULL(CASE ISNULL(T.Compromete_Trans_Fondos,0) 
							WHEN 0 THEN C.Cotizacion
							ELSE V.Cotizacion
						END,1)
						as Cotizacion
					,CMT.DESCRIPCION as Tipo 
					,CM.Id_Trans
					,CM.Renglon_Nro
					,ISNULL(C.Id_Centro_Costo,'''')
					,CM.Importe
					,SUM(V.Importe) as Imp_Valor
					,CASE ISNULL(T.COMPROMETE_BANKING,0) 
							WHEN 0 THEN 
								CASE SIGN(CM.Importe) WHEN 1 THEN SUM(V.Importe) ELSE 0 END 
							WHEN 1 THEN
								SUM(V.Importe)
							WHEN -1 THEN	
								0
							END
							as Ingreso 
					,CASE ISNULL(T.COMPROMETE_BANKING,0) 
							WHEN 0 THEN 
								CASE  SIGN(CM.Importe) WHEN -1 THEN SUM(V.Importe) ELSE 0 END 
							WHEN 1 THEN
								0
							WHEN -1 THEN	
								SUM(V.Importe)
							END
							as Egreso 
					, 0 AS Saldo
     				,V.id_moneda
					,c.Comprobante_Nro'

SET @SqlFrom = 'FROM Valores_mov M LEFT OUTER JOIN CBTES C ON M.Id_Trans = C.Id_Trans 
							LEFT JOIN #Renglon_Val_Mov R ON M.Id_Trans = R.Id_Trans AND M.Renglon_Nro = R.Renglon_Nro
                             LEFT OUTER JOIN CBTES_TIPOS T ON T.ID_TIPO_CBTE = C.ID_TIPO_CBTE
					 LEFT OUTER JOIN Cajas_Mov_Conceptos CMC 
							ON CMC.Id_Trans = M.Id_Trans
						      AND CMC.Item = (SELECT MIN(CMC2.Item) FROM Cajas_Mov_Conceptos CMC2 WHERE CMC2.Id_Trans = M.Id_Trans)   
					 LEFT OUTER JOIN Conceptos CO 
							ON CO.Id_Concepto = CMC.Id_Concepto
					 LEFT OUTER JOIN CAJAS_MOV CM ON CM.Id_Trans = M.Id_Trans
							, Valores V , CAJAS_MOV_TIPOS CMT '

SET @SqlWhere = ' WHERE V.Id_Valor = M.Id_valor
				        AND M.Id_Periodo_Caja IN' + RTRIM(LTRIM(@Id_Periodo_Caja)) + '
						AND CM.Renglon_Nro = ISNULL(M.Renglon_Nro_Caja,0)
						AND CM.Id_Periodo_Caja = M.Id_Periodo_Caja 
						AND CM.Id_Estado_Mov_Caja = 2
						AND CM.Id_Trans = M.Id_Trans
						AND CM.Id_Periodo_Caja = M.Id_Periodo_Caja
						AND CMT.Id_Tipo_Mov_Caja = CM.Id_Tipo_Mov_Caja '
					 
IF ISNULL(@Id_Tipo_Valor,'') <> ''
BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND V.Id_Tipo_Val = '''+  @Id_Tipo_Valor +''''
END
ELSE
BEGIN
    IF ISNULL(@TiposValor,'') <> ''
    BEGIN
	    SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND V.Id_Tipo_Val IN (' + @TiposValor + ')'
    END
END

IF ISNULL(@Id_Moneda,'') <> ''
BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND V.Id_Moneda = ''' + @Id_Moneda + ''''
END

IF ISNULL(@Id_Centro_Costo,'') <> ''
BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND C.Id_Centro_Costo = ''' + @Id_Centro_Costo +''''
END

IF @Filtrar_Fecha = 1
BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND CM.FECHA < '''+ CONVERT(VARCHAR(8),@Fecha_HASTA + 1,112) +''''
END

SET @SqlGroup = ' GROUP BY CM.FECHA
						,CM.DESCRIPCION 
						,C.Destinatario
						,C.Cotizacion
						,V.Cotizacion
						,CMT.DESCRIPCION
						,CM.Id_Trans
						,CM.Renglon_Nro
						,C.Id_Centro_Costo
						,T.Compromete_Trans_Fondos
						,CM.Importe
						,T.COMPROMETE_BANKING
						,CO.Descripcion
						,V.id_moneda
						,c.Comprobante_Nro
				ORDER BY CM.FECHA,CM.ID_TRANS '


SET @Sql = @SqlSelect +' '+ @SqlFrom + ' ' + @SqlWhere + ' ' + @SqlGroup 
PRINT @Sql

CREATE INDEX IX_CajaMov____ ON  #Cajas_Mov (Id_Interno)

INSERT INTO #Cajas_Mov
EXEC(@sql)

DECLARE @Id_Interno INT 
DECLARE @Ing DECIMAL(16,2)
DECLARE @Egr DECIMAL(16,2)
DECLARE @Saldo DECIMAL(16,2)

SET @Saldo = 0
DECLARE Cur_Caja CURSOR FOR
	 SELECT Id_Interno,Ingreso,Egreso FROM #Cajas_Mov order by Id_Interno

OPEN Cur_Caja 
FETCH NEXT FROM Cur_Caja INTO @Id_Interno,@Ing,@Egr
WHILE @@FETCH_STATUS=0
BEGIN

	SET @Saldo = @Saldo + @Ing - @Egr
	UPDATE #Cajas_Mov SET Saldo = @Saldo WHERE Id_Interno = @Id_Interno
	FETCH NEXT FROM Cur_Caja INTO @Id_Interno,@Ing,@Egr

END
CLOSE Cur_Caja
DEALLOCATE Cur_Caja

---------------------------------------------------------------------Creo Tabla Temporal Final en Cero---------------------------------------------------------------------------
SELECT TOP 1 Fecha ,Concepto ,Descripcion ,Cotizacion ,Tipo ,Id_Trans ,Renglon_Nro, Id_Centro_Costo,Importe ,Imp_Valor ,Ingreso ,Egreso ,Saldo, Id_Moneda, Comprobante_Nro
		     INTO #Cajas_Mov2 
			 FROM #Cajas_Mov  WHERE 1=0

IF ISNULL(@Filtrar_Fecha,0) <> 0
BEGIN
		IF ISNULL((SELECT COUNT(*) FROM #Cajas_Mov  WHERE  FECHA < @Fecha_Desde),0) = 0
		BEGIN        /*Cargo Saldo Anterior en cero*/
			INSERT INTO #Cajas_Mov2 ( Fecha           ,Concepto        ,Descripcion     ,Cotizacion      ,Tipo             ,Id_Trans   ,Renglon_Nro   , Id_Centro_Costo ,Importe ,Imp_Valor ,Ingreso ,Egreso ,Saldo,Id_Moneda, Comprobante_Nro)
				VALUES (CAST(@Fecha_Desde - 1 AS DATE),'Saldo Anterior','Saldo Anterior',1               ,'Saldo Anterior' ,0          ,0             ,''               ,0       ,0         ,0       ,0      ,0    ,@Id_Moneda, 0)
        END
		ELSE
		BEGIN        		/*Cargo Saldo Anterior*/
			INSERT INTO #Cajas_Mov2
				SELECT TOP 1 Fecha ,Concepto ,Descripcion ,Cotizacion ,Tipo ,Id_Trans ,Renglon_Nro ,Id_Centro_Costo ,Importe ,Imp_Valor ,Ingreso ,Egreso ,Saldo,Id_Moneda, Comprobante_Nro
                        FROM #Cajas_Mov  WHERE  FECHA < @Fecha_Desde ORDER BY Id_Interno DESC

			UPDATE #Cajas_Mov2 SET Concepto = 'Saldo Anterior', Descripcion = 'Saldo Anterior'
								 , Tipo = 'Saldo Anterior', Importe = 0,	Imp_Valor = 0, Ingreso = 0 
								 , Renglon_Nro = 0 , Id_Trans = 0
								 , Egreso = 0, Fecha = CAST(@Fecha_Desde - 1 AS DATE),Id_Moneda = @id_Moneda, Comprobante_Nro = 0
		END								  
  
		/*Cargo Datos*/
		INSERT INTO #Cajas_Mov2
			 SELECT Fecha ,Concepto ,Descripcion ,Cotizacion ,Tipo ,Id_Trans ,Renglon_Nro , Id_Centro_Costo ,Importe ,Imp_Valor ,Ingreso ,Egreso ,Saldo,Id_Moneda, Comprobante_Nro 
				FROM #Cajas_Mov WHERE  FECHA >= @Fecha_Desde
END
ELSE
BEGIN
	/*Cargo Saldo Anterior en cero*/
	INSERT INTO #Cajas_Mov2 ( Fecha           ,Concepto        ,Descripcion     ,Cotizacion      ,Tipo             ,Id_Trans   ,Renglon_Nro , Id_Centro_Costo ,Importe ,Imp_Valor ,Ingreso ,Egreso ,Saldo,Id_moneda, Comprobante_Nro)
		VALUES (CAST(@Fecha_Desde - 1 AS DATE),'Saldo Anterior','Saldo Anterior',1               ,'Saldo Anterior' ,0          ,0           ,''              ,0       ,0         ,0       ,0      ,0     ,@id_Moneda,0)

	/*Cargo Datos*/		
	INSERT INTO #Cajas_Mov2
			SELECT Fecha ,Concepto ,Descripcion ,Cotizacion ,Tipo ,Id_Trans ,Renglon_Nro , Id_Centro_Costo ,Importe ,Imp_Valor ,Ingreso ,Egreso ,Saldo ,Id_Moneda, Comprobante_Nro
			FROM #Cajas_Mov 

END


SELECT *,
( SELECT TOP 1 U.LastName+' '+ U.FirstName FROM Cajas_Mov_Hist H, SEG_USER U WHERE U.NO = H.ID_USUARIO AND CM.Id_Trans = H.Id_Trans ORDER BY h.Id_Caja_Mov_Hist desc) AS Usuario,
( SELECT TOP 1 H.FECHA FROM Cajas_Mov_Hist H, SEG_USER U WHERE U.NO = H.ID_USUARIO AND CM.Id_Trans = H.Id_Trans ORDER BY h.Id_Caja_Mov_Hist desc) AS Fecha_Mov
     FROM #Cajas_Mov2 CM 
	 ORDER BY Fecha

DROP TABLE #Renglon_Val_Mov
DROP TABLE #Cajas_Mov
DROP TABLE #Cajas_Mov2
END

