CREATE PROCEDURE [dbo].[CP_Cajas_Saldos] @pid_periodo_Caja  Int
 
AS 
BEGIN
SET NOCOUNT ON

declare @Id_Periodo_Caja INT
,@Descripcion char(200)
,@Saldo decimal(14,2)
,@Egresos  decimal(14,2)
,@Id_tipo_Val Char(3) 
  
  
       SELECT P.Id_Periodo_Caja as id_periodo_caja,CA.DESCRIPCION as descripcion,V.id_tipo_val,SUM(V.Importe) AS saldo Into #CAJAS_SALDOS
                 FROM VALORES V,Cajas_Mov C,CBTES CB, CBTES_TIPOS T, Cajas_periodos P, cajas CA
                 WHERE C.Id_Trans = V.Id_Trans 
                 AND CB.ID_TRANS = C.ID_TRANS 
				 AND CA.Id_Caja = P.id_caja and P.Id_Estado_Caja = 1
                 AND CB.ID_TIPO_CBTE = T.ID_TIPO_CBTE 
                 AND T.COMPROMETE_BANKING NOT IN (1,-1) 
                 AND C.Id_Periodo_Caja = V.Id_Periodo_Caja 
                 AND C.Id_Tipo_Mov_Caja IN (1,7,11,10,5)
                 AND C.Id_Estado_Mov_Caja = 2
                 AND C.Id_Periodo_Caja = P.Id_Periodo_Caja
                 AND C.Importe > 0  
                 AND v.id_estado_valor <> 1
                 GROUP BY P.Id_Periodo_Caja,CA.DESCRIPCION,V.Id_Tipo_Val
       

		DECLARE Cur_Caja CURSOR FOR
			 SELECT Id_Periodo_Caja,Descripcion,Id_tipo_Val,Saldo FROM #CAJAS_SALDOS

		OPEN Cur_Caja 
		FETCH NEXT FROM Cur_Caja INTO @Id_Periodo_Caja,@Descripcion,@Id_tipo_Val,@Saldo
		WHILE @@FETCH_STATUS=0
		BEGIN

            set @Egresos = ISNULL(( SELECT SUM(V.Importe)
                 FROM VALORES V,Cajas_Mov C,CBTES CB, CBTES_TIPOS T 
                 WHERE C.Id_Trans = V.Id_Trans 
                 AND CB.ID_TRANS = C.ID_TRANS 
                 AND CB.ID_TIPO_CBTE = T.ID_TIPO_CBTE 
                 AND T.COMPROMETE_BANKING NOT IN (1,-1) 
                 AND C.Id_Periodo_Caja = V.Id_Periodo_Caja 
                 AND C.Id_Tipo_Mov_Caja IN (2,3,6,8,15,4)
                 AND C.Id_Estado_Mov_Caja = 2
                 AND C.Id_Periodo_Caja  = @Id_Periodo_Caja
                 AND C.Importe < 0  
                 AND V.Id_Tipo_Val = @Id_tipo_Val
                 AND v.id_estado_valor <> 1
                 ),0)

			UPDATE #CAJAS_SALDOS SET Saldo = Saldo - @Egresos  WHERE Id_Periodo_Caja = @Id_Periodo_Caja and Id_tipo_Val = @Id_tipo_Val

			FETCH NEXT FROM Cur_Caja INTO @Id_Periodo_Caja,@Descripcion,@Id_tipo_Val,@Saldo
		END
		CLOSE Cur_Caja
		DEALLOCATE Cur_Caja
	

        IF @pid_periodo_Caja = 0
		   BEGIN
		     Select * from #CAJAS_SALDOS  order by Id_Periodo_Caja
		   END
		 ELSE
		   BEGIN
		     Select * from #CAJAS_SALDOS  WHERE Id_Periodo_Caja = @pid_periodo_Caja
		   END

		Drop table #CAJAS_SALDOS

END

-- SP_Cajas_Saldos 176
GO

CREATE PROCEDURE [dbo].[CP_Cbte_Aplica_Generar] 
@pId_Cliente						INT,
@Id_Trans_a_Cancelar				INT,
@Id_trans_NC						INT,
@Imp_Fac							DECIMAL(15,2),
@Imp_NC								DECIMAL(15,2),
@pId_Cobrador						VARCHAR(10)=NULL


AS 
SET NOCOUNT ON

/*Declaracion Variables Locales*/
DECLARE @FlagUsarTrans		TINYINT
DECLARE @Fecha_Actual		DATETIME
DECLARE @Fecha				DATETIME	
DECLARE @Lote				VARCHAR(20)
DECLARE @Id_Cliente			INT
DECLARE @Id_Tipo_Cbte		CHAR(4)
DECLARE @Id_Cond_Pago		INT
DECLARE @Id_Moneda			CHAR(3)
DECLARE @Cotizacion			DECIMAL(12,4)
DECLARE @Id_Trans			INT
DECLARE @Item				TINYINT
DECLARE @Nota				VARCHAR(200)
DECLARE @Cantidad			DECIMAL(15,5)
DECLARE @Id_cobrador		VARCHAR(10)
DECLARE @pimporte			DECIMAL(15,2)
DECLARE @Id_Periodo_Caja	INT
DECLARE @Email				VARCHAR(50)
DECLARE @Id_Usuario			INT
															
/*FIN Declaracion Variables Locales*/

/*Tablas y variables para acumular respuesta de los Stored*/
DECLARE @Respuesta TABLE (	ErrorNumber		INT,
							ErrorSeverity	INT,
							ErrorState		INT,
							ErrorProcedure  VARCHAR(1000),
							ErrorLine		INT,
							ErrorMessage	VARCHAR(1000))
DECLARE @UltError INT
/*FIN Tablas y variables para acumular respuesta de los Stored*/

SET @FlagUsarTrans	= 0
SET @UltError		= 0

BEGIN TRY

	PRINT 'CP_Cbte_Aplica_Generar'
	
	/*Loguea*/
	DECLARE @Nombre_Stored_Procedure	VARCHAR(50)
	DECLARE @Parametros_Recibidos		VARCHAR(8000)

	SET @Nombre_Stored_Procedure = 'CP_Cbte_Aplica_Generar'
	SET @Parametros_Recibidos =  ' @pId_Cliente: ' + CONVERT(VARCHAR(10), ISNULL(@pId_Cliente, 0)) + ' @Id_Trans_a_Cancelar: ' + CONVERT(VARCHAR(10),ISNULL(@Id_Trans_a_Cancelar, 0)) +' @Id_trans_NC: ' + CONVERT(VARCHAR(10),ISNULL(@Id_trans_NC, 0)) + ' @Imp_Fac: ' + CONVERT(VARCHAR(10), ISNULL(@Imp_Fac, 0)) + ' @Imp_NC: ' + CONVERT(VARCHAR(10), ISNULL(@Imp_NC, 0)) + ' @pId_Cobrador: ' + ISNULL(@pId_Cobrador, '')

    IF ISNULL(@FlagUsarTrans, 0) <> 0 
	BEGIN
		BEGIN TRAN
	END

	/*Asignacion de Variables Locales*/
	SET @Id_Usuario			= -1
	SET @Fecha_Actual		= GETDATE()
	SET @Lote				= 'COB_' + SUBSTRING(CONVERT(VARCHAR(10), @Fecha_Actual, 103), 7, 4) + SUBSTRING(CONVERT(VARCHAR(10), @Fecha_Actual, 103), 4, 2) + SUBSTRING(CONVERT(VARCHAR(10), @Fecha_Actual, 103), 1, 2) + '_' + SUBSTRING(CONVERT(VARCHAR(20), @Fecha_Actual, 108), 1, 2) + SUBSTRING(CONVERT(VARCHAR(20), @Fecha_Actual, 108), 4, 2) + SUBSTRING(CONVERT(VARCHAR(20), @Fecha_Actual, 108), 7, 2)
	SET @Id_Cliente			=	@pId_Cliente
	SET @Id_Tipo_Cbte		= 'RECC' /*Recibo*/
	SET @Id_Cond_Pago		= 10 /*Cta. Cte.*/
	SET @Id_Moneda			= 'PES'
	SET @Cotizacion			= 1
	SET @Item				= 1
	SET @Nota				= 'Cbtes. Generado por BD'
	SET @Cantidad			= 1
	SET @Id_Periodo_Caja	= 17035
	SET @pimporte			= 0.00
	SET @Email				=' '
	SET @Fecha				= '20200601'
	
	IF(@pId_Cobrador = 0)
	BEGIN
		SET @pId_Cobrador = ISNULL((SELECT Id_Cobrador FROM Clientes Where Id_cliente = @pId_Cliente),'')
	END
	/*FIN Asignacion de Variables Locales*/

	/*===================================================================*/
	
	DELETE @Respuesta
	
	INSERT INTO @Respuesta			
	EXEC @UltError =	dbo.CP_Cbtes_Rec_Generar
															@Id_Usuario,
															@pId_Cliente,
															@Email,
															@Id_Periodo_Caja,
															@Fecha,
															@pImporte, 
															@Id_Tipo_Cbte,
															@Id_Moneda,
															@Cotizacion,
															@Lote
	
	--SP_Cbte_Aplica_Generar		
	--													@pId_Cliente	,
	--													@Id_Trans_a_Cancelar,
	--													@Id_trans_NC,
	--													@Imp_Fac,
	--													@Imp_NC,
	--													@pTipo_Cbte,	/*RECIBO*/
	--													@pFecha,
	--													@pId_Cobrador
													
	IF @UltError <> 0
	BEGIN
		--IF ISNULL(@FlagUsarTrans, 0) <> 0 
		--BEGIN			
		--	ROLLBACK
		--END

		SELECT * FROM @Respuesta	
		RETURN 4567
	END
	ELSE
	BEGIN
		SELECT TOP 1 @Id_Trans = ErrorLine FROM @Respuesta

		IF @Id_Trans = 0
		BEGIN
			SELECT	 4568			AS ErrorNumber 
					,0				AS ErrorSeverity  
					,0				AS ErrorState 
					,0				AS ErrorProcedure  
					,0				AS ErrorLine		
					,'No se genero el Nro. de Trans. REC'		AS ErrorMessage

			--IF ISNULL(@FlagUsarTrans,0) <> 0 
			--BEGIN
			--	ROLLBACK
			--END

			RETURN 4568
		END
	END
	
	/*===================================================================*/
	DELETE @Respuesta
	
	EXEC dbo.CP_Cbtes_Rec_Generar_Item	@Id_Trans,
											1,
											'',
											1,
											@Id_Trans_a_Cancelar,
											@Imp_Fac
		/*===*/	
	DELETE @Respuesta	
	SET @Imp_NC = @Imp_NC * -1									
	EXEC dbo.CP_Cbtes_Rec_Generar_Item @Id_Trans,
											2,
											'',
											1,
											@Id_trans_NC,
											@Imp_NC 										
																					
	/*===================================================================*/
	DELETE @Respuesta
									
	EXEC dbo.CP_Cbtes_Rec_Fin		@Id_Trans
	
	/*===================================================================*/
	
	
	IF ISNULL(@FlagUsarTrans,0) <> 0 
	BEGIN
		COMMIT
	END

	PRINT 'FIN Procedimiento: CP_Cbte_Aplica_Generar'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,@Id_Trans		AS ErrorLine		
			,0				AS ErrorMessage
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo
	
	IF ISNULL(@FlagUsarTrans,0) <> 0 
	BEGIN
		ROLLBACK
	END
		 	
	RETURN 9999
END CATCH

RETURN 0
GO

CREATE PROCEDURE CP_Cbtes_Alta_Online 
@LOTE		VARCHAR(20), 
@Fecha		CHAR(8),
@Id_Cliente INT,
@Importe	DECIMAL(12,2)
AS 

DECLARE @desc			VARCHAR(50)
DECLARE @Id_Tipo_Cbte	CHAR(4)
DECLARE @Nombre			VARCHAR(100)
DECLARE @NRO_CBTE		INT
DECLARE @trans_nueva	INT
DECLARE @Mensaje		VARCHAR(100)
DECLARE @Id_Moneda		CHAR(3)

BEGIN TRY
	BEGIN TRAN

	SET @Id_Tipo_Cbte = dbo.CF_xParam('Tipo_Cbte_VW_Factura')
	SET @Id_Moneda    = dbo.CF_xParam('Moneda_Cbte_VW')



	SET @desc = 'VW:' + @LOTE
	SET @Nombre = (SELECT rtrim(Razon_Social) FROM Clientes WHERE Id_Cliente = @Id_Cliente)

	SET @trans_nueva = (SELECT max(id_trans) from transacciones ) + 1

	/*===================================================================*/
	INSERT INTO Transacciones	(id_trans,		descripcion,	fecha_mov) 
					VALUES		(@trans_nueva,	@desc,			GETDATE())

	/*===================================================================*/
	SET @NRO_CBTE = (SELECT Prox_Nro from Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte) 

	UPDATE Cbtes_Tipos SET Prox_Nro = Prox_Nro+1 WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte

	/*===================================================================*/
	INSERT INTO Cbtes	(Id_Cond_Vta,		Id_trans,		Id_Sucursal,
						Cbte_Grupo,			Fecha_Venc ,    id_cliente,
						id_estado_Cbte,		id_tipo_cbte,	comprobante_nro,
						fecha,				periodo_iva,	periodo,
						imp_total,			saldo,			imp_gravado,
						destinatario,		lote,			ID_MONEDA,
						Id_Cond_Pago,		Cotizacion)
			   VALUES	('',				@trans_nueva,	1,
						0,					@FECHA,			@id_cliente,
						0,					@Id_Tipo_cbte,	@NRO_CBTE,
						@FECHA,				@FECHA,			@FECHA,
						@Importe,			0,				@Importe,
						@NOMBRE,			'VW:' + @LOTE,	@Id_Moneda,
						10,					1)

	/*===================================================================*/
	INSERT INTO Clientes_CtaCte (Id_Trans,		Nro_Cuota,		Id_Empresa,
								Id_Cliente,		Fecha,			Fecha_Vence,
								Descripcion,	Importe,		Id_Estado_Cbte,
								Observacion,	Id_Trans_Origen,Nro_Cuota_Origen,
								Id_Moneda,		Saldo,			Nro_FacCre)
					VALUES		(@trans_nueva,	1,				NULL,
								@id_cliente,	@Fecha,			@Fecha,
								dbo.CF_Descrip_Cbte(@trans_nueva),@Importe ,1,
								'',				0,				0,
								@Id_Moneda,			0,				0)


	 
	COMMIT

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage
			,@trans_nueva	AS Id_Trans

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO

CREATE PROCEDURE [dbo].[CP_Cbtes_Confirmar_Online] @LOTE VARCHAR(20)
AS 

DECLARE @Mensaje							VARCHAR(100)
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
DECLARE @Result_Stored_Invocado				INT
BEGIN TRY
	DECLARE @trans_rec INTEGER,@trans_ND INT,@LoteND VARCHAR(20),@LoteRec VARCHAR(20),@Saldo DECIMAL(12,2)
	SET @LoteND = 'VW:' + @LOTE
	SET @LoteRec = 'CW:' + @LOTE


	BEGIN TRAN


	SET @trans_ND = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = @LoteND AND Id_Estado_Cbte = 0),0)
	IF (@trans_ND = 0)
	BEGIN
	    SET @Mensaje = 'No hay trans de Factura'
		PRINT @Mensaje
	END
	ELSE
	BEGIN
		PRINT @trans_ND
		UPDATE Cbtes SET Id_Estado_Cbte = 2,Saldo = 0			WHERE Id_Trans = @trans_ND
		UPDATE Cbtes_Items SET Id_Estado_Cbte = 2				WHERE Id_Trans = @trans_ND
		UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 2,Saldo = 0 WHERE Id_Trans = @trans_ND
		
		--/*Se agrega la generación de Asiento para las transacciones WEB*/
		--/*--------------------------------------------------------------*/
		SET @JSON_Parametros_Stored_Invocado =	'{' +
												dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'INT') + ',' +
												dbo.CF_Json_ParsearVariable('Id_Trans', @trans_ND, 'INT') + ',' +
												dbo.CF_Json_ParsearVariable('FlagRegenerar', 1, 'TINYINT') + 
												'}'
							
		EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Ctas_Contables_Generar @JSON_Parametros_Stored_Invocado
		IF ISNULL(@Result_Stored_Invocado,0) <> 0 
		BEGIN
			/*El CPJ_Cbtes_Ctas_Contables_Generar deberÝa devolver el SELECT con el error*/
			RETURN 9999
		END		
		
		/*---------------------------------------------------------------------*/
	END --FIN ELSE

	
	SET @trans_rec = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = @LoteRec AND Id_Estado_Cbte = 0),0)
	IF (@trans_rec = 0)
	BEGIN
	    SET @Mensaje = 'No hay trans de recibo'
		PRINT @Mensaje
	END
	ELSE
	BEGIN
	    DECLARE @Id_Estado_Cbte SMALLINT
		SET @Id_Estado_Cbte = 2
		SET @Saldo			= 0

		PRINT @trans_rec
		IF @trans_ND = 0
		BEGIN
			SET @Id_Estado_Cbte = 1
			SET @Saldo			= (SELECT Imp_Total FROM Cbtes WHERE Id_Trans = @trans_rec)
		END
		

		UPDATE Cbtes			SET Id_Estado_Cbte = @Id_Estado_Cbte,Saldo = @Saldo WHERE Id_Trans = @trans_rec
		UPDATE Cbtes_Items		SET Id_Estado_Cbte = @Id_Estado_Cbte WHERE Id_Trans = @trans_rec
		UPDATE Clientes_CtaCte	SET Id_Estado_Cbte = @Id_Estado_Cbte,Saldo = @Saldo * -1 WHERE Id_Trans = @trans_rec

		UPDATE Cajas_Mov		SET Id_Estado_Mov_Caja = 2 WHERE Id_Trans = @trans_rec  --en siempre va en completo.
	END

	COMMIT

	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage
			,@trans_ND			AS Id_Trans_Fac
			,@trans_rec			AS Id_Trans_Rec

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO

CREATE PROCEDURE [dbo].[CP_Cbtes_Control]    
@FECHA_DESDE	DATETIME,
@FECHA_HASTA	DATETIME,
@PROCESOS		VARCHAR(100)

AS

IF ISNULL(@PROCESOS,'')='' SET @PROCESOS='T'

IF (ISDATE(@FECHA_DESDE)!=1 OR ISDATE(@FECHA_HASTA) != 1 )
	RETURN 


IF @PROCESOS = 'T' OR CHARINDEX('1001',@PROCESOS)>0
		BEGIN 
			SELECT  CA.Id_Trans,CA.Id_Trans_D
			,Ori.Id_Cliente AS CLIENTE_ORI
			,OT.Id_Tipo_Cbte AS TIPO_ORI
			,Dest.Id_Cliente AS CLIENTE_TRANS_D
			,DT.Id_Tipo_Cbte AS TIPO_TRANS_D
			,(case When isnull(Clie_O.Id_Cliente_ref,0)=0 then Clie_O.Id_Cliente else   Clie_O.Id_Cliente_Ref  end) AS CLIENTE_TITULAR
			,(case When isnull(Clie_D.Id_Cliente_ref,0)=0 then Clie_D.Id_Cliente else   Clie_D.Id_Cliente_Ref  end) AS CLIENTE_DESTINO
			

			INTO #TEMPO1

			FROM Cbtes_Aplica CA, cbtes Ori , Cbtes Dest, Cbtes_Tipos OT, Cbtes_Tipos DT, Clientes Clie_O, Clientes Clie_D 
			WHERE CA.ID_TRANS >0 
			AND CA.ID_TRANS_D>0
			AND Ori.Id_Trans = CA.Id_Trans
			AND Dest.Id_Trans = CA.Id_Trans_D
			AND Ori.Id_Tipo_Cbte = OT.Id_Tipo_Cbte
			AND (OT.Compromete_Factura IN (1,-1) OR OT.Compromete_Recibos IN (1,-1))
			AND Dest.Id_Tipo_Cbte = DT.Id_Tipo_Cbte
			AND (DT.Compromete_Factura IN (1,-1) OR DT.Compromete_Recibos IN (1,-1))
			AND Ori.Id_Cliente != Dest.Id_Cliente
			AND Dest.Id_Cliente = Clie_D.Id_Cliente
			AND Ori.Id_Cliente = Clie_O.Id_Cliente
			AND Ori.Fecha BETWEEN @FECHA_DESDE AND @FECHA_HASTA 
			/* ESTE RESULTADO PARA LOS OTROS   */
			SELECT  C.Fecha
			        ,T.TIPO_ORI as Id_Tipo_Cbte 
					,dbo.CF_Cbte_Descrip(T.CLIENTE_ORI) as Cbte_Descrip
					,C.Destinatario
					,C.Imp_Total
					,C.Id_Trans,
			        '1001' as Error,
					'Inconsitencia en Titular de Cbte, cliente '+ CONVERT(VARCHAR(20),T.Id_Trans_D) 
					       + ' aplicado a con transacción = '+ CONVERT(VARCHAR(20),T.Id_Trans_D)+' '+ T.TIPO_TRANS_D + ' Cliente: '+ CONVERT(VARCHAR(20),T.CLIENTE_DESTINO)
					       as Observacion  
				INTO #AUX01
				FROM #TEMPO1 T, Cbtes C
				WHERE CLIENTE_DESTINO != CLIENTE_TITULAR  
					AND C.Id_Trans = T.Id_Trans
					ORDER BY 3,1
					DROP TABLE #TEMPO1
		END 

	IF @PROCESOS = 'T' OR CHARINDEX('1002',@PROCESOS)>0
		BEGIN
		SELECT  C.Fecha
				,C.Id_Tipo_Cbte 
				,dbo.CF_Cbte_Descrip(c.id_Cliente) as Cbte_Descrip
				,C.Destinatario
				,C.Imp_Total
				,C.Id_Trans 
				,'1002' as Error
				,'Documento No debe estar en la Cuenta Corriente del Cliente' AS Observacion
				INTO #AUX02
				FROM CBTES C 
				WHERE C.ID_ESTADO_CBTE <> 3 
				AND C.ID_COND_PAGO = 1 
				AND EXISTS (SELECT * FROM Clientes_CtaCte K WHERE C.ID_TRANS = K.ID_TRANS)
				AND C.Fecha BETWEEN @FECHA_DESDE AND @FECHA_HASTA  ;
		END

	IF OBJECT_ID (N'tempdb..#AUX01', N'U') IS NOT NULL AND
		OBJECT_ID (N'tempdb..#AUX02', N'U') IS NOT NULL 
		SELECT * FROM #AUX02 UNION SELECT * FROM #AUX01 ORDER BY 1,4,2

	IF OBJECT_ID (N'tempdb..#AUX01', N'U') IS NOT NULL AND OBJECT_ID (N'tempdb..#AUX02', N'U') IS NULL 
		SELECT * FROM #AUX01 ORDER BY 1,4,2

	IF OBJECT_ID (N'tempdb..#AUX01', N'U') IS NULL AND OBJECT_ID (N'tempdb..#AUX02', N'U') IS NOT NULL 
		SELECT * FROM #AUX02 ORDER BY 1,4,2

	IF OBJECT_ID (N'tempdb..#AUX01', N'U') IS NOT NULL 
	DROP TABLE #AUX01 
	IF OBJECT_ID (N'tempdb..#AUX02', N'U') IS NOT NULL 
	DROP TABLE #AUX02
GO

CREATE PROCEDURE CP_Cbtes_Copiar @Id_Trans INT,@Id_Usuario SMALLINT,@Id_Estado_Cbte SMALLINT
AS

DECLARE @Mensaje			VARCHAR(100)
		,@Id_Trans_Nueva	INT
		,@Descripcion		VARCHAR(100)
		,@Id_Valor			INT
		,@Comprobante_Nro	INT
BEGIN TRY
	BEGIN TRAN

	IF (NOT EXISTS (SELECT 1 FROM Cbtes WHERE Id_Trans = @Id_Trans))
	BEGIN
		SELECT	 1					AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,'No Existe Cbte de Origen'			AS ErrorMessage
				,@Id_Trans      	AS Id_Trans_Original
				,@Id_Trans_Nueva   	AS Id_Trans_Nueva
		ROLLBACK
		RETURN 1
    END

	/*Agre en transacciones*/
	SET @Id_Trans_Nueva = (SELECT MAX(Id_Trans) FROM Transacciones ) + 1
	INSERT INTO Transacciones	(Id_Trans		,Fecha_mov	,Id_Usuario) 
					VALUES		(@Id_Trans_Nueva ,GETDATE()	,@Id_Usuario)

	/*Agrego en Cbtes*/
	SELECT * INTO #Cbtes FROM Cbtes WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes SET Id_Trans = @Id_Trans_Nueva, Id_Estado_Cbte = @Id_Estado_Cbte, Comprobante_Nro = 0
	INSERT INTO Cbtes SELECT * FROM #Cbtes

	/*Agrego en Cbtes_Bcos_Transf*/
	SELECT * INTO #Cbtes_Bcos_Transf FROM Cbtes_Bcos_Transf WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Bcos_Transf SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Bcos_Transf SELECT * FROM #Cbtes_Bcos_Transf

	/*Agrego en Cbtes_Centro_Costos*/
	SELECT * INTO #Cbtes_Centro_Costos FROM Cbtes_Centro_Costos WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Centro_Costos SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Centro_Costos SELECT * FROM #Cbtes_Centro_Costos


	/*Agrego en Cbtes_Conceptos*/
	SELECT * INTO #Cbtes_Conceptos FROM Cbtes_Conceptos WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Conceptos SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Conceptos SELECT * FROM #Cbtes_Conceptos

	/*Agrego en Cbtes_Ctas_Contables*/
	SELECT * INTO #Cbtes_Ctas_Contables FROM Cbtes_Ctas_Contables WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Ctas_Contables SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Ctas_Contables SELECT * FROM #Cbtes_Ctas_Contables

	/*Agrego en Cbtes_Incluidos*/
	SELECT * INTO #Cbtes_Incluidos FROM Cbtes_Incluidos WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Incluidos SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Incluidos SELECT * FROM #Cbtes_Incluidos

	/*Agrego en Cbtes_Items*/
	SELECT * INTO #Cbtes_Items FROM Cbtes_Items WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Items SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Items SELECT * FROM #Cbtes_Items

	/*Agrego en Cbtes_Items_Cajas*/
	/*             No se hace para no generar un caja nueva
	SELECT * INTO #Cbtes_Items_Cajas FROM Cbtes_Items_Cajas WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Items_Cajas SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Items_Cajas SELECT * FROM #Cbtes_Items_Cajas
	*/
	/*Agrego en Cbtes_Items_Comp*/
	SELECT * INTO #Cbtes_Items_Comp FROM Cbtes_Items_Comp WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Items_Comp SET Id_Trans = @Id_Trans_Nueva 
	INSERT INTO Cbtes_Items_Comp SELECT * FROM #Cbtes_Items_Comp

	/*Agrego en Cbtes_Items_Planif*/
	SELECT * INTO #Cbtes_Items_Planif FROM Cbtes_Items_Planif WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Items_Planif SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Items_Planif SELECT * FROM #Cbtes_Items_Planif
	
	/*Agrego en Cbtes_Iva*/
	SELECT * INTO #Cbtes_Iva FROM Cbtes_Iva WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Iva SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Iva SELECT * FROM #Cbtes_Iva

	/*Agrego en Cbtes_Reten*/
	SELECT * INTO #Cbtes_Reten FROM Cbtes_Reten WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Reten SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Reten SELECT * FROM #Cbtes_Reten

	/*Agrego en Cbtes_Valores_Canje*/
	SELECT * INTO #Cbtes_Valores_Canje FROM Cbtes_Valores_Canje WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Valores_Canje SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Valores_Canje SELECT * FROM #Cbtes_Valores_Canje

	/*Agrego en Cbtes_Vend*/
	SELECT * INTO #Cbtes_Vend FROM Cbtes_Vend WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_Vend SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_Vend SELECT * FROM #Cbtes_Vend

	/*Agrego en Cbtes_xCampos*/
	SELECT * INTO #Cbtes_xCampos FROM Cbtes_xCampos WHERE Id_Trans = @Id_Trans
	UPDATE #Cbtes_xCampos SET Id_Trans = @Id_Trans_Nueva
	INSERT INTO Cbtes_xCampos SELECT * FROM #Cbtes_xCampos

	SET @Descripcion =  dbo.CF_Cbte_Descrip(@Id_Trans_Nueva)
	UPDATE Transacciones		SET Descripcion = @Descripcion WHERE Id_Trans = @Id_Trans_Nueva

	/*============================== cuentas corrientes ========================*/
	
	/*Agrego en Clientes_CtaCte*/
	SELECT * INTO #Clientes_CtaCte FROM Clientes_CtaCte WHERE Id_Trans = @Id_Trans
	UPDATE #Clientes_CtaCte SET Id_Trans = @Id_Trans_Nueva, Descripcion = @Descripcion
	INSERT INTO Clientes_CtaCte SELECT * FROM #Clientes_CtaCte

	/*Agrego en Proveedores_CtaCte*/
	SELECT * INTO #Proveedores_CtaCte FROM Proveedores_CtaCte WHERE Id_Trans = @Id_Trans
	UPDATE #Proveedores_CtaCte SET Id_Trans = @Id_Trans_Nueva, Descripcion = @Descripcion
	INSERT INTO Proveedores_CtaCte SELECT * FROM #Proveedores_CtaCte

	/*============================== Caja ========================*/
	/* 
		Cajas se debe copiar con funci¾n CP_Cajas_Mov_Copiar 
		Valores se debe copiar con funci¾n CP_Valores_Copiar (tener encuanta no duplicar cheques de terceros)
	*/
	
	IF @Id_Estado_Cbte <> 0 
		EXEC CP_Cbtes_Grabar_Numero @Id_Trans_Nueva

	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage
			,@Id_Trans      	AS Id_Trans_Original
			,@Id_Trans_Nueva   	AS Id_Trans_Nueva


END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_Cbtes_Cpra_Generar] 
@Id_Proveedor	INT,
@Destinatario	VARCHAR(100), 
@Importe		DECIMAL(12,2), 
@Id_Sucursal	SMALLINT,
@Fecha			DATETIME, 
@Id_Tipo_Cbte	CHAR(4),
@Lote			CHAR(14),
@Id_Estado_Cbte INT,
@Id_Cond_Pago	SMALLINT,
@Comprobante_Nro INT,
@Id_Trans Int OUTPUT

AS 
/*-----------------------------------------------------
 * OJO!: Buscar la palabra CAMBIAR en estedocumento y 
 *		 adaptar las variables al cliente.
 ------------------------------------------------------*/
SET NOCOUNT ON 
BEGIN TRAN

PRINT 'Genero Comprobante Tipo: '+@Id_Tipo_Cbte+' para el Proveedor: '+CONVERT(VARCHAR(20),@Id_Proveedor)
PRINT 'Fecha del Comprobante: '+CONVERT(VARCHAR(20), @Fecha, 101)+' Estado Comprobante: '+CONVERT(VARCHAR(3),@id_Estado_Cbte)

/*Declaracion Variables Locales*/
DECLARE @Trans_Nueva			INT
DECLARE @User					SMALLINT
DECLARE @Desc					VARCHAR(50)
DECLARE @Nombre					VARCHAR(100)
DECLARE @Descripcion_Producto	VARCHAR(100)
DECLARE @Cantidad				DECIMAL(12,2)
DECLARE @Fecha_Mov				DATETIME
DECLARE @Descrip_Cbte_CtaCte	VARCHAR(100)
DECLARE @Signo					INT
DECLARE @ImporteXCant			DECIMAL(12,2)
DECLARE	@Observacion			VARCHAR(30)
DECLARE @Compromete_Pagos		SMALLINT
DECLARE @Compromete_Compras		SMALLINT
DECLARE @Id_Iva					CHAR(3)
Declare  @Alias_D SmallInt
		,@Alias_H SmallInt
		,@ID_Cta_Debe  Int
		,@ID_Cta_Haber Int
		,@ID_Centro_Costo CHAR(10)

/*FIN Declaracion Variables Locales*/

/*Asignacion Variables*/
SET @Trans_Nueva			= ISNULL((SELECT (MAX(id_trans)+1)	FROM Transacciones),1)
SET @Desc					= @Lote
SET @Observacion			= 'Comprobante Generado desde B.D.'
SET @Compromete_Pagos		= ISNULL((SELECT Compromete_Pagos FROM Cbtes_Tipos WHERE Id_Tipo_Cbte=@Id_Tipo_Cbte), 0)
SET @Compromete_Compras		= ISNULL((SELECT Compromete_Compras FROM Cbtes_Tipos WHERE Id_Tipo_Cbte=@Id_Tipo_Cbte), 0)
SET	@Id_Iva					= ISNULL((SELECT Id_Iva FROM Proveedores WHERE Id_Proveedor = @Id_Proveedor), 'I')
/*FIN Asignacion Variables*/

SET @Signo = 1

IF((@Compromete_Pagos <> 0) OR (@Compromete_Compras = -1))
BEGIN
	SET @Signo = -1
END

/*---------------------------------------------------------------------------------*/

/*Insert: TRANSACCIONES*/
PRINT 'Inserto la Transaccion Nro: ' + CONVERT(VARCHAR(20), @Trans_Nueva)

INSERT INTO Transacciones	(Id_Trans,		Descripcion,	Fecha_Mov) 
VALUES						(@Trans_Nueva,	@Desc,			GETDATE())

IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN
END	 
/*FIN Insert: TRANSACCIONES*/
-- Busco nro de Cbte y actualizo

	SET @Comprobante_Nro    = (SELECT PROX_NRO from CBTES_TIPOS WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte)
	SET @Id_Sucursal = (SELECT Sucursal_Nro from Empresas_Suc E, Cbtes_Tipos T WHERE T.ID_TIPO_CBTE = @Id_Tipo_Cbte And T.Id_Sucursal = E.Id_Sucursal)
	UPDATE Cbtes_Tipos SET PROX_NRO = @Comprobante_Nro+1 WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte

/*---------------------------------------------------------------------------------*/

/*Insert: CBTES*/
SET @ImporteXCant = (@Importe)

PRINT 'Inserto en Cbtes'
INSERT INTO Cbtes			(Id_Trans,			Id_Sucursal,		Id_Tipo_Cbte,
							Cbte_Grupo,			Comprobante_Nro,	Id_Cliente,
							Id_Proveedor,		Signo,				Id_Estado_Cbte,
							Fecha,				Porc_DescEspecial,	Imp_Bonificacion,
							Imp_Gravado,		Imp_Exento,			Imp_IVA,
							Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
							Imp_Total,			Id_Usuario,			Porc_Iva3,
							Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
							Imp_IVA3,			Imp_Percep,			Saldo,
							Periodo_Iva,		Periodo,			Fecha_Venc,
							Observacion,		Id_Cond_Pago,		Cant_Cuotas,
							Cantidad,			Id_Lista,			Id_Moneda,
							Cotizacion,			Destinatario,		Id_Iva,
							Saldo_Iva_Recup,	Lote,				Id_Asiento,
							Id_Valor,			Cai,				Cantidad_Saldo,
							Saldo_Anterior,		Porc_DescFin,		Porc_Bonificacion,
							Porc_Iva,			Porc_Iva2,			Imp_Neto,
							Imp_DescEspecial,	Imp_DescFin)
VALUES						(@Trans_Nueva,		@Id_Sucursal,		@Id_Tipo_cbte,
							0/*Cbte_Grupo*/,	@Comprobante_Nro,	0/*Id_Cliente*/,
							@Id_Proveedor/*Id_Proveedor*/,	0/*Signo*/,	@Id_Estado_Cbte,
							@Fecha,				0/*Porc_DescEspec*/,0/*Imp_Bonificacion*/,
							0/*Imp_Gravado*/,	@ImporteXCant,		0/*Imp_Iva*/,
							0/*Imp_Iva2*/,		0/*Imp_Percepcion_*/,0/*Imp_Percepcion_Iva*/,
							@ImporteXCant,		0/*Id_Usuario*/,	27/*Porc_Iva3*/,
							0/*Imp_Gravado2*/,	0/*Imp_Gravado3*/,	0/*Imp_NoGravado*/,
							0/*Imp_IVA3*/,		0/*Imp_Percep*/,	@ImporteXCant,
							@Fecha,				@Fecha,				@Fecha,
							@Observacion,		@Id_Cond_Pago,		1/*Cant_Cuotas*/,
							0/*Cantidad*/,		0/*Id_Lista*/,		'PES'/*Id_Moneda*/,
							1/*Cotizacion*/,	@Destinatario,		@Id_Iva/*Id_Iva*/,
							0/*Saldo_Iva_Recu*/,@Lote,				0/*Id_Asiento*/,
							0/*Id_Valor*/,		0/*Cai*/,			0/*Cantidad_Saldo*/,
							0/*Saldo_Anterior*/,0/*Porc_DescFin*/,	0/*Porc_Bonificacion*/,
							21/*Porc_Iva*/,		'10.5'/*Porc_Iva2*/,@ImporteXCant,
							0/*Imp_DescEspecial*/,0/*Imp_DescFin*/)
							
IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN
END	 
/*FIN Insert: CBTES*/

/*---------------------------------------------------------------------------------*/
	
	/*Insert: Clientes_CtaCte*/	
	IF @Id_Cond_Pago <> 1
	BEGIN	

	SET @Descrip_Cbte_CtaCte= (SELECT DBO.CF_Cbte_Descrip(@Trans_Nueva))
	PRINT 'Inserto en Proveedores_CtaCte Comprobante: ' + @Descrip_Cbte_CtaCte
								
		INSERT INTO Proveedores_CtaCte	(Id_Trans,			Nro_Cuota,				Id_Empresa,
										Id_Proveedor,		Fecha,				Fecha_Vence,
										Descripcion,		Importe,				Id_Estado_Cbte,
										Observacion,		Id_Trans_Origen,		Nro_Cuota_Origen,
										Id_Moneda,			Saldo)
		VALUES							(@trans_nueva,		1,						NULL,
										@Id_Proveedor,		@Fecha,					@Fecha,
										@Descrip_Cbte_CtaCte,@Importe,	@Id_Estado_Cbte,
										@Observacion,		0,						0,
										'PES',				@Importe)

		IF (@@ERROR <> 0)
		BEGIN
			ROLLBACK
			RETURN
		END	 
	END
	/*FIN Insert: Clientes_CtaCte*/
	-------------------------------------
	 --Insert: CBTES_CONCEPTOS/	
        DECLARE @Id_Concepto INT
		SET @Id_Concepto = (SELECT ISNULL(ID_CONCEPTO,0) FROM PROVEEDORES WHERE ID_PROVEEDOR = @Id_Proveedor)
		IF @Id_Concepto > 0
		   BEGIN
	        	INSERT INTO CBTES_CONCEPTOS (Id_Concepto, Id_Trans, Item, Importe, Observacion)
		        VALUES						(@Id_Concepto,@trans_nueva,	1,@Importe,'')	
           END
		IF (@@ERROR <> 0)
		BEGIN
			ROLLBACK
			RETURN
		END	 

	
	/*---------------------------------------------------------------------------------*/
	--Asiento
	  
	    SET @Alias_D = (SELECT Id_Cta_Contable_D FROM PROVEEDORES WHERE ID_PROVEEDOR = @ID_PROVEEDOR)
		SET @Alias_H = (SELECT Id_Cta_Contable_H FROM PROVEEDORES WHERE ID_PROVEEDOR = @ID_PROVEEDOR)
		SET @ID_Centro_Costo = (SELECT ID_Centro_Costo FROM PROVEEDORES WHERE ID_PROVEEDOR = @ID_PROVEEDOR)

		SET @ID_Cta_Debe  = (SELECT dbo.SF_Cta_Contable(@Alias_D, @Fecha))
		SET @ID_Cta_Haber = (SELECT dbo.SF_Cta_Contable(@Alias_H, @Fecha))
	    
        IF @Importe > 0
		BEGIN					
			INSERT INTO Cbtes_Ctas_Contables (Id_Trans,		  Id_Cta_Contable,	   	Fecha,
												  Debe,             Haber,        Observacion,
												 Alias,            Id_Asiento,    Id_Centro_Costo, Item)

			VALUES					 	   (@trans_nueva,		@ID_Cta_Debe,		@Fecha,
											@Importe,		0,					'',
											@Alias_D,0,	@ID_Centro_Costo,1)


			IF (@@ERROR <> 0)
			BEGIN
				ROLLBACK
				RETURN
			END	 

			INSERT INTO Cbtes_Ctas_Contables (Id_Trans,		  Id_Cta_Contable,	   	Fecha,
												  Debe,             Haber,        Observacion,
												 Alias,            Id_Asiento,    Id_Centro_Costo, Item)

			VALUES					 	   (@trans_nueva,		@ID_Cta_Haber,		@Fecha,
											0,		@Importe,					'',
											@Alias_H,0,	@ID_Centro_Costo,2)


			IF (@@ERROR <> 0)
			BEGIN
				ROLLBACK
				RETURN
			END	
		 END	 
         ELSE
		 BEGIN
		    DECLARE @IMPORTE_NC DECIMAL(12,2)
			SET @IMPORTE_NC = @IMPORTE*-1
			INSERT INTO Cbtes_Ctas_Contables (Id_Trans,		  Id_Cta_Contable,	   	Fecha,
												  Debe,             Haber,        Observacion,
												 Alias,            Id_Asiento,    Id_Centro_Costo, Item)

			VALUES					 	   (@trans_nueva,		@ID_Cta_Haber,		@Fecha,
											@Importe_NC,		0,					'',
											@Alias_H,0,	@ID_Centro_Costo,1)


			IF (@@ERROR <> 0)
			BEGIN
				ROLLBACK
				RETURN
			END	 

			INSERT INTO Cbtes_Ctas_Contables (Id_Trans,		  Id_Cta_Contable,	   	Fecha,
												  Debe,             Haber,        Observacion,
												 Alias,            Id_Asiento,    Id_Centro_Costo, Item)

			VALUES					 	   (@trans_nueva,		@ID_Cta_DEBE,		@Fecha,
											0,		@Importe_NC,					'',
											@Alias_D,0,	@ID_Centro_Costo,2)


			IF (@@ERROR <> 0)
			BEGIN
				ROLLBACK
				RETURN
			END	
	     END
	--Cbtes_Items



set @Id_trans = @trans_nueva
 
IF (@@ERROR = 0)
BEGIN
	COMMIT TRAN
	--SELECT @trans_nueva
END
ELSE
BEGIN
	ROLLBACK
	--SELECT 0
END


/*FIN Actualizo el Proximo Numero de Comprobante*/
GO


CREATE PROCEDURE [dbo].[CP_Cbtes_Cpra_Generar_Asi] 
@Id_Trans Int
AS 

SET NOCOUNT ON 
/*Declaracion Variables Locales*/
DECLARE @Signo	INT
		,@Compromete_Compras SMALLINT
		,@Id_Iva	CHAR(3)
		,@Alias_D SmallInt
		,@Alias_H SmallInt
		,@ID_Cta_Debe Int
		,@ID_Cta_Haber Int
		,@ID_Centro_Costo CHAR(10)
		,@IMP_GRAVADO DECIMAL(12,2)
		,@IMP_IVA DECIMAL(12,2)
		,@Id_Proveedor	INT
		,@Importe	DECIMAL(12,2)
		,@Fecha	DATETIME
		,@Id_Tipo_Cbte	CHAR(4)
		,@ASI_Comp_x_Items INT
		,@Alias_D_IVA INT 
		,@ID_Cta_Debe_IVA INT
		,@IMPORTE_NC DECIMAL(12,2)
        ,@NroItem SMALLINT
		,@Id_Tipo_Reten VARCHAR(10)

/*FIN Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100),@Id_Trans_ND INT

BEGIN TRY
BEGIN TRAN

/*Asignacion Variables*/
SELECT @Fecha = Fecha
        ,@Id_Tipo_Cbte = Id_Tipo_Cbte
		,@Id_Proveedor = Id_Proveedor  
		,@Importe = Imp_TOTAL
		,@IMP_GRAVADO = Imp_Gravado + Imp_Gravado2 + Imp_Gravado3 + Imp_Exento
		,@IMP_IVA = Imp_Iva + Imp_Iva2 + Imp_Iva3
		FROM CBTES WHERE Id_Trans = @Id_Trans

SET @Compromete_Compras	= ISNULL((SELECT Compromete_Compras FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte), 0)
SET	@Id_Iva	= ISNULL((SELECT Id_Iva FROM Proveedores WHERE Id_Proveedor = @Id_Proveedor), 'I')
SET @Signo = @Compromete_Compras
SET @ASI_Comp_x_Items = CAST( dbo.CF_xParam('ASI_Comp_x_Items') AS INT)



SET @Alias_D = (SELECT Id_Cta_Contable_D FROM PROVEEDORES WHERE ID_PROVEEDOR = @ID_PROVEEDOR)
SET @Alias_H = (SELECT Id_Cta_Contable_H FROM PROVEEDORES WHERE ID_PROVEEDOR = @ID_PROVEEDOR)
SET @Alias_D_IVA = (select Valor_INTEGER from xParametros where setDatos= 1 and idParametro ='Cta_Iva_Cre_Loc')

SET @ID_Centro_Costo = (SELECT ID_Centro_Costo FROM PROVEEDORES WHERE ID_PROVEEDOR = @ID_PROVEEDOR)

SET @ID_Cta_Debe = (SELECT dbo.CF_Cta_Cont(@Alias_D, @Fecha))
SET @ID_Cta_Debe_IVA = (SELECT dbo.CF_Cta_Cont(@Alias_D_IVA, @Fecha))
SET @ID_Cta_Haber = (SELECT dbo.CF_Cta_Cont(@Alias_H, @Fecha))
SET @NroItem = 0
/*FIN Asignacion Variables*/

IF @Compromete_Compras = 0
	BEGIN
	    SET @Mensaje = 'No es un cbte de compra.'
		rollback
		SELECT	 1099		    	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,@Mensaje			AS ErrorMessage
		RETURN 1
	END

IF ISNULL(@ASI_Comp_x_Items,0) = 0          --Asiento por cabecerad e cbte.
	BEGIN
		IF @SIGNO > 0
			BEGIN	
			INSERT INTO Cbtes_Ctas_Contables (Id_Trans,	Id_Cta_Contable,	Fecha, Debe, Haber, Observacion, Alias, Id_Asiento, Id_Centro_Costo, Item)
									VALUES	(@Id_Trans,	@ID_Cta_Debe,	@Fecha,@IMP_GRAVADO,	0,	'',@Alias_D,0,	@ID_Centro_Costo,1)
			INSERT INTO Cbtes_Ctas_Contables (Id_Trans,	Id_Cta_Contable,	Fecha,Debe, Haber, Observacion,Alias, Id_Asiento, Id_Centro_Costo, Item)
									VALUES	(@Id_Trans,	@ID_Cta_Debe_IVA,	@Fecha,@IMP_IVA,	0,	'',@Alias_D_IVA,0,	@ID_Centro_Costo,2)
			INSERT INTO Cbtes_Ctas_Contables (Id_Trans,	Id_Cta_Contable,	Fecha,Debe, Haber, Observacion,Alias, Id_Asiento, Id_Centro_Costo, Item)
									VALUES	(@Id_Trans,	@ID_Cta_Haber,	@Fecha,0,	@Importe,	'',@Alias_H,0,	@ID_Centro_Costo,3)
			END	
		ELSE
			BEGIN
			SET @IMPORTE_NC = @IMPORTE*-1
			INSERT INTO Cbtes_Ctas_Contables (Id_Trans,	Id_Cta_Contable,	Fecha,Debe, Haber, Observacion,Alias, Id_Asiento, Id_Centro_Costo, Item)
										VALUES	(@Id_Trans,	@ID_Cta_Haber,	@Fecha,@Importe_NC,	0,	'',@Alias_H,0,	@ID_Centro_Costo,1)
			INSERT INTO Cbtes_Ctas_Contables (Id_Trans,	Id_Cta_Contable,	Fecha,Debe, Haber, Observacion,Alias, Id_Asiento, Id_Centro_Costo, Item)
										VALUES	(@Id_Trans,	@ID_Cta_Debe_IVA,	@Fecha,0,@IMP_IVA,	'',@Alias_D_IVA,0,	@ID_Centro_Costo,2)
			INSERT INTO Cbtes_Ctas_Contables (Id_Trans,	Id_Cta_Contable,	Fecha,Debe, Haber, Observacion,Alias, Id_Asiento, Id_Centro_Costo, Item)
										VALUES	(@Id_Trans,	@ID_Cta_DEBE,	@Fecha,0,	@Importe_NC-@IMP_IVA,	'',@Alias_D,0,	@ID_Centro_Costo,3)
			END
	END
Else
	BEGIN
		--PRINT 'Compromete Factura COMPRA
		/*INICIO Insert: Cuenta Contable: DEBE*/		
		PRINT 'Generacion de Items de Productos'

		DECLARE curGenCtaContDEBE CURSOR FOR 

	    	SELECT P.Id_Alias_Cta_Cont,isnull(P.Id_Centro_Costo,''),isnull(Sum(I.Imp_Gravado*@Signo),0)
	    	FROM Cbtes_Items i, Productos P
		    WHERE 
		    Id_Trans = @Id_Trans
	     	and I.id_Producto = P.Id_Producto
		    group by P.Id_Alias_Cta_Cont,P.Id_Centro_Costo

		    PRINT 'Generacion select del cursor'

		OPEN curGenCtaContDEBE
		FETCH NEXT FROM curGenCtaContDEBE INTO @Alias_D,@Id_Centro_Costo,@IMPORTE
		WHILE @@FETCH_STATUS = 0
		BEGIN
		    SET @ID_Cta_Debe = (SELECT dbo.CF_Cta_Cont(@Alias_D, @Fecha))
			SET @NroItem = @NroItem + 1
		
			PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) +  '. Alias: ' + CONVERT(VARCHAR(10), @Alias_D) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @ID_Cta_Debe) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 


					INSERT INTO Cbtes_Ctas_Contables
					(Id_Trans,		Id_Cta_Contable,	Fecha,
					Debe,			Haber,				Observacion,
					Alias,			Id_Asiento,			Id_Centro_Costo,
					Item)
					VALUES									
					(@Id_Trans,	@ID_Cta_Debe,	@Fecha,
					@Importe/*Debe*/,		0,				''/*Observacion*/,
					@Alias_D,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
					@NroItem)


		FETCH NEXT FROM curGenCtaContDEBE INTO  @Alias_D,@Id_Centro_Costo,@IMPORTE
		END 

		CLOSE curGenCtaContDEBE
		DEALLOCATE curGenCtaContDEBE

		/*FIN Insert: Cuenta Contable: DEBE*/
	
		PRINT 'Generacion de Items de Percepciones'	

		DECLARE curGenCtaCteDEBEPercep CURSOR FOR 
		SELECT DISTINCT Id_Tipo_Reten 
		FROM Cbtes_Reten 
		WHERE 
		Id_Trans = @Id_Trans

		OPEN curGenCtaCteDEBEPercep
		FETCH NEXT FROM curGenCtaCteDEBEPercep INTO @Id_Tipo_Reten
		WHILE @@FETCH_STATUS = 0
		BEGIN
			SET @Alias_D = (SELECT Id_Cta_Contable FROM Cbtes_Reten_Tipos WHERE Id_Tipo_Reten = @Id_Tipo_Reten)
		    SET @ID_Cta_Debe = (SELECT dbo.CF_Cta_Cont(@Alias_D, @Fecha))
			SET @Id_Centro_Costo = ''
			SET @IMPORTE = (SELECT SUM(Importe) FROM Cbtes_Reten WHERE Id_Trans = @Id_Trans AND Id_Tipo_Reten = @Id_Tipo_Reten)
			SET @NroItem = @NroItem + 1
		
			--PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Tipo_Reten: ' + @Id_Tipo_Reten + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@Id_Trans,	@ID_Cta_Debe,	@Fecha,
			@Importe/*Debe*/,		0,				''/*Observacion*/,
			@Alias_D,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)

		FETCH NEXT FROM curGenCtaCteDEBEPercep INTO @Id_Tipo_Reten
		END 
		CLOSE curGenCtaCteDEBEPercep
		DEALLOCATE curGenCtaCteDEBEPercep
	
		--PRINT 'Generacion de Items de Iva'

		SET @Alias_D_IVA = (select Valor_INTEGER from xParametros where setDatos= 1 and idParametro ='Cta_Iva_Cre_Loc')
        SET @ID_Centro_Costo = ''
        SET @ID_Cta_Debe_IVA = (SELECT dbo.CF_Cta_Cont(@Alias_D_IVA, @Fecha))
	
		IF(@IMP_IVA <> 0)
		BEGIN
			SET @NroItem = @NroItem + 1
		
			--PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@Id_Trans,	@ID_Cta_Debe_IVA,	@Fecha,
			@IMP_IVA/*Debe*/,		0,				''/*Observacion*/,
			@Alias_D_IVA,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)		
		END

		/*Insert: Cuenta Contable: HABER */
		--PRINT 'Generacion Cuenta Contable: HABER'

		SELECT @Importe = Imp_TOTAL	FROM CBTES WHERE Id_Trans = @Id_Trans

		SET @Id_Centro_Costo = (SELECT Isnull(Id_Centro_Costo,'') FROM Proveedores WHERE Id_PROVEEDOR = @ID_PROVEEDOR)
		SET @NroItem = @NroItem + 1
		--PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias_H) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @ID_Cta_Haber) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
		INSERT INTO Cbtes_Ctas_Contables
		(Id_Trans,		Id_Cta_Contable,	Fecha,
		Debe,			Haber,				Observacion,
		Alias,			Id_Asiento,			Id_Centro_Costo,
		Item)
		VALUES									
		(@Id_Trans,	@ID_Cta_Haber,	@Fecha,
		0,@Importe ,			''/*Observacion*/,
		@Alias_H,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
		@NroItem)
		/*FIN Insert: Cuenta Contable: DEBE (SI la Cond. Pago NO es Contado)*/
	
	
	/*Insert: Cuenta Contable: HABER*/
	--PRINT 'Generacion Cuenta Contable: HABER'
	
		--PRINT 'FIN Compromete COMPRAS'
	END /*IF(@Flag_Compromete_cOMPRAS = 1)*/


COMMIT
SELECT	 0					AS ErrorNumber 
		,0					AS ErrorSeverity  
		,0					AS ErrorState 
		,0					AS ErrorProcedure  
		,0					AS ErrorLine		
		,@Mensaje			AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO

CREATE PROCEDURE [dbo].[CP_Cbtes_Cpra_Generar_Cabe] 
@Id_Proveedor	INT,
@Destinatario	VARCHAR(100), 
@Importe		DECIMAL(12,2), 
@Id_Sucursal	SMALLINT,
@Fecha			DATETIME, 
@Id_Tipo_Cbte	CHAR(4),
@Lote			CHAR(14),
@Id_Estado_Cbte INT,
@Id_Cond_Pago	SMALLINT,
@Comprobante_Nro INT,
@Id_Trans Int OUTPUT

AS 
/*-----------------------------------------------------
 * OJO!: Buscar la palabra CAMBIAR en estedocumento y 
 *		 adaptar las variables al cliente.
 ------------------------------------------------------*/
SET NOCOUNT ON 
BEGIN TRAN

PRINT 'Genero Comprobante Tipo: '+@Id_Tipo_Cbte+' para el Proveedor: '+CONVERT(VARCHAR(20),@Id_Proveedor)
PRINT 'Fecha del Comprobante: '+CONVERT(VARCHAR(20), @Fecha, 101)+' Estado Comprobante: '+CONVERT(VARCHAR(3),@id_Estado_Cbte)

/*Declaracion Variables Locales*/
DECLARE @Trans_Nueva			INT
DECLARE @User					SMALLINT
DECLARE @Desc					VARCHAR(50)
DECLARE @Nombre					VARCHAR(100)
DECLARE @Descripcion_Producto	VARCHAR(100)
DECLARE @Cantidad				DECIMAL(12,2)
DECLARE @Fecha_Mov				DATETIME
DECLARE @Descrip_Cbte_CtaCte	VARCHAR(100)
DECLARE @Signo					INT
DECLARE @ImporteXCant			DECIMAL(12,2)
DECLARE	@Observacion			VARCHAR(30)
DECLARE @Compromete_Pagos		SMALLINT
DECLARE @Compromete_Compras		SMALLINT
DECLARE @Id_Iva					CHAR(3)
Declare  @Alias_D SmallInt
		,@Alias_H SmallInt
		,@ID_Cta_Debe  Int
		,@ID_Cta_Haber Int
		,@ID_Centro_Costo CHAR(10)

/*FIN Declaracion Variables Locales*/

/*Asignacion Variables*/
SET @Trans_Nueva			= ISNULL((SELECT (MAX(id_trans)+1)	FROM Transacciones),1)
SET @Desc					= @Lote
SET @Observacion			= 'Comprobante Generado desde B.D.'
SET @Compromete_Pagos		= ISNULL((SELECT Compromete_Pagos FROM Cbtes_Tipos WHERE Id_Tipo_Cbte=@Id_Tipo_Cbte), 0)
SET @Compromete_Compras		= ISNULL((SELECT Compromete_Compras FROM Cbtes_Tipos WHERE Id_Tipo_Cbte=@Id_Tipo_Cbte), 0)
SET	@Id_Iva					= ISNULL((SELECT Id_Iva FROM Proveedores WHERE Id_Proveedor = @Id_Proveedor), 'I')
/*FIN Asignacion Variables*/

SET @Signo = 1

IF((@Compromete_Pagos <> 0) OR (@Compromete_Compras = -1))
BEGIN
	SET @Signo = -1
END

/*---------------------------------------------------------------------------------*/

/*Insert: TRANSACCIONES*/
PRINT 'Inserto la Transaccion Nro: ' + CONVERT(VARCHAR(20), @Trans_Nueva)

INSERT INTO Transacciones	(Id_Trans,		Descripcion,	Fecha_Mov) 
VALUES						(@Trans_Nueva,	@Desc,			GETDATE())

IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN
END	 
/*FIN Insert: TRANSACCIONES*/
-- Busco nro de Cbte y actualizo

	SET @Comprobante_Nro    = (SELECT PROX_NRO from CBTES_TIPOS WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte)
	SET @Id_Sucursal = (SELECT Sucursal_Nro from Empresas_Suc E, Cbtes_Tipos T WHERE T.ID_TIPO_CBTE = @Id_Tipo_Cbte And T.Id_Sucursal = E.Id_Sucursal)
	UPDATE Cbtes_Tipos SET PROX_NRO = @Comprobante_Nro+1 WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte

/*---------------------------------------------------------------------------------*/

/*Insert: CBTES*/
SET @ImporteXCant = (@Importe)

PRINT 'Inserto en Cbtes'
INSERT INTO Cbtes			(Id_Trans,			Id_Sucursal,		Id_Tipo_Cbte,
							Cbte_Grupo,			Comprobante_Nro,	Id_Cliente,
							Id_Proveedor,		Signo,				Id_Estado_Cbte,
							Fecha,				Porc_DescEspecial,	Imp_Bonificacion,
							Imp_Gravado,		Imp_Exento,			Imp_IVA,
							Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
							Imp_Total,			Id_Usuario,			Porc_Iva3,
							Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
							Imp_IVA3,			Imp_Percep,			Saldo,
							Periodo_Iva,		Periodo,			Fecha_Venc,
							Observacion,		Id_Cond_Pago,		Cant_Cuotas,
							Cantidad,			Id_Lista,			Id_Moneda,
							Cotizacion,			Destinatario,		Id_Iva,
							Saldo_Iva_Recup,	Lote,				Id_Asiento,
							Id_Valor,			Cai,				Cantidad_Saldo,
							Saldo_Anterior,		Porc_DescFin,		Porc_Bonificacion,
							Porc_Iva,			Porc_Iva2,			Imp_Neto,
							Imp_DescEspecial,	Imp_DescFin)
VALUES						(@Trans_Nueva,		@Id_Sucursal,		@Id_Tipo_cbte,
							0/*Cbte_Grupo*/,	@Comprobante_Nro,	0/*Id_Cliente*/,
							@Id_Proveedor/*Id_Proveedor*/,	0/*Signo*/,	@Id_Estado_Cbte,
							@Fecha,				0/*Porc_DescEspec*/,0/*Imp_Bonificacion*/,
							0/*Imp_Gravado*/,	@ImporteXCant,		0/*Imp_Iva*/,
							0/*Imp_Iva2*/,		0/*Imp_Percepcion_*/,0/*Imp_Percepcion_Iva*/,
							@ImporteXCant,		0/*Id_Usuario*/,	27/*Porc_Iva3*/,
							0/*Imp_Gravado2*/,	0/*Imp_Gravado3*/,	0/*Imp_NoGravado*/,
							0/*Imp_IVA3*/,		0/*Imp_Percep*/,	@ImporteXCant,
							@Fecha,				@Fecha,				@Fecha,
							@Observacion,		@Id_Cond_Pago,		1/*Cant_Cuotas*/,
							0/*Cantidad*/,		0/*Id_Lista*/,		'PES'/*Id_Moneda*/,
							1/*Cotizacion*/,	@Destinatario,		@Id_Iva/*Id_Iva*/,
							0/*Saldo_Iva_Recu*/,@Lote,				0/*Id_Asiento*/,
							0/*Id_Valor*/,		0/*Cai*/,			0/*Cantidad_Saldo*/,
							0/*Saldo_Anterior*/,0/*Porc_DescFin*/,	0/*Porc_Bonificacion*/,
							21/*Porc_Iva*/,		'10.5'/*Porc_Iva2*/,@ImporteXCant,
							0/*Imp_DescEspecial*/,0/*Imp_DescFin*/)
							
IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN
END	 
/*FIN Insert: CBTES*/



set @Id_trans = @trans_nueva
 
IF (@@ERROR = 0)
BEGIN
	COMMIT TRAN
	--SELECT @trans_nueva
END
ELSE
BEGIN
	ROLLBACK
	--SELECT 0
END


/*FIN Actualizo el Proximo Numero de Comprobante*/
GO



CREATE PROCEDURE [dbo].[CP_Cbtes_Cpra_Generar_Fin] 
@Id_Proveedor	INT,
@Destinatario	VARCHAR(100), 
@Importe	DECIMAL(12,2), 
@Id_Sucursal	SMALLINT,
@Fecha	DATETIME, 
@Id_Tipo_Cbte	CHAR(4),
@Lote	CHAR(14),
@Id_Estado_Cbte INT,
@Id_Cond_Pago	SMALLINT,
@Comprobante_Nro INT,
@Id_Trans Int

AS 

SET NOCOUNT ON 

PRINT 'Genero Comprobante Tipo: '+@Id_Tipo_Cbte+' para el Proveedor: '+CONVERT(VARCHAR(20),@Id_Proveedor)
PRINT 'Fecha del Comprobante: '+CONVERT(VARCHAR(20), @Fecha, 101)+' Estado Comprobante: '+CONVERT(VARCHAR(3),@id_Estado_Cbte)

/*Declaracion Variables Locales*/
DECLARE @User	SMALLINT
DECLARE @Desc	VARCHAR(50)
DECLARE @Nombre	VARCHAR(100)
DECLARE @Descripcion_Producto	VARCHAR(100)
DECLARE @Cantidad	DECIMAL(12,2)
DECLARE @Fecha_Mov	DATETIME
DECLARE @Fecha_Vence	DATETIME
DECLARE @Descrip_Cbte_CtaCte	VARCHAR(100)
DECLARE @Signo	INT
DECLARE @ImporteXCant	DECIMAL(12,2)
DECLARE	@Observacion	VARCHAR(30)
DECLARE @Compromete_Compras	SMALLINT
	,@IMP_GRAVADO DECIMAL(12,2)
	,@IMP_IVA DECIMAL(12,2)
	,@IMP_RETENCIONES DECIMAL(12,2)

/*FIN Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100),@Id_Trans_ND INT

BEGIN TRY
BEGIN TRAN


/*Asignacion Variables*/
SET @Desc	= @Lote
SET @Observacion	= 'Comprobante Generado desde B.D.'
SET @Compromete_Compras	= ISNULL((SELECT Compromete_Compras FROM Cbtes_Tipos WHERE Id_Tipo_Cbte=@Id_Tipo_Cbte), 0)
SET @Fecha_Vence = ISNULL((SELECT Fecha_Venc FROM CBTES WHERE Id_Trans = @Id_Trans), @Fecha)
/*FIN Asignacion Variables*/


SET @Signo = @Compromete_Compras

/*---------------------------------------------------------------------------------*/

/*Update: CBTES*/
SET @ImporteXCant = (@Importe)

PRINT 'Modifico Cbtes'

UPDATE Cbtes SET 
Imp_Exento = 0, Imp_Gravado = 0, Imp_Gravado2 = 0, Imp_Gravado3 = 0, Imp_NoGravado = 0, Imp_Percep = 0,
Imp_iva = 0, Imp_iva2 = 0, Imp_iva3 = 0,Imp_neto = 0, Saldo = 0, Imp_Total = 0 
WHERE ID_TRANS = @ID_TRANS 

UPDATE Cbtes SET 
Imp_Gravado = ISNULL((SELECT SUM(Imp_Gravado) FROM Cbtes_Items WHERE ID_TRANS = @ID_TRANS and isnull(Porc_Iva,21) = 21),0) 
WHERE ID_TRANS = @ID_TRANS 
UPDATE Cbtes SET 
Imp_Iva = Imp_Gravado * Porc_Iva/100 
WHERE ID_TRANS = @ID_TRANS 

UPDATE Cbtes SET 
Imp_Gravado2 = ISNULL((SELECT SUM(Imp_Gravado) FROM Cbtes_Items WHERE ID_TRANS = @ID_TRANS and isnull(Porc_Iva,21) = 10.5),0) 
WHERE ID_TRANS = @ID_TRANS 
UPDATE Cbtes SET 
Imp_Iva2 = Imp_Gravado2 * Porc_Iva2/100 
WHERE ID_TRANS = @ID_TRANS 

UPDATE Cbtes SET 
Imp_Gravado3 = ISNULL((SELECT SUM(Imp_Gravado) FROM Cbtes_Items WHERE ID_TRANS = @ID_TRANS and isnull(Porc_Iva,21) = 0),0) 
WHERE ID_TRANS = @ID_TRANS 
UPDATE Cbtes SET 
Imp_Iva3 = Imp_Gravado3 * Porc_Iva3/100 
WHERE ID_TRANS = @ID_TRANS 

SET @IMP_RETENCIONES = ISNULL((SELECT SUM(isnull(IMPORTE,0)) FROM cbtes_reten WHERE ID_TRANS = @ID_TRANS ),0)

UPDATE CBTES SET Imp_Percep = @IMP_RETENCIONES WHERE ID_TRANS = @ID_TRANS


UPDATE Cbtes SET 
Imp_TOTAL = Imp_Gravado + Imp_Gravado2 + Imp_Gravado3 + Imp_Iva + Imp_Iva2 + Imp_Iva3 + Imp_Percep,
Saldo = Imp_Gravado + Imp_Gravado2 + Imp_Gravado3 + Imp_Iva + Imp_Iva2 + Imp_Iva3 + Imp_Percep
WHERE ID_TRANS = @ID_TRANS 

--update cbtes set Cuit = P.CUIT FROM CBTES C, PROVEEDORES P WHERE C.ID_PROVEEDOR = P.ID_PROVEEDOR AND C.ID_TRANS =  @ID_TRANS

--update cbtes set Nro_Auto_Trib = T.NRO_CAI, Cai = T.NRO_CAI,  Cai_Vence = T.FECHA_CAI FROM CBTES C, CBTES_TIPOS T WHERE C.ID_TIPO_CBTE = T.ID_TIPO_CBTE AND C.ID_TRANS = @ID_TRANS

SET @Importe = (SELECT Imp_TOTAL FROM Cbtes WHERE ID_TRANS = @ID_TRANS)
 
SET @Comprobante_Nro = (SELECT Comprobante_Nro FROM Cbtes WHERE ID_TRANS = @ID_TRANS)

/*---------------------------------------------------------------------------------*/
/*Insert: Clientes_CtaCte*/	
IF @Id_Cond_Pago <> 1
	BEGIN	
	SET @Descrip_Cbte_CtaCte = (
	ISNULL((SELECT Descrip_Corta FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte), ' ')+
	' ' +
	ISNULL((SELECT Letra FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte),'A') +
	' ' +
	RIGHT('0000' + LTRIM(RTRIM(@Id_Sucursal)),4) +
	'-' +
	RIGHT('00000000' + LTRIM(RTRIM(@Comprobante_Nro)),8)
	)
	PRINT 'Inserto en Proveedores_CtaCte Comprobante: ' + @Descrip_Cbte_CtaCte

	INSERT INTO Proveedores_CtaCte	(Id_Trans,	Nro_Cuota,	Id_Empresa,
	Id_Proveedor,	Fecha,	Fecha_Vence,
	Descripcion,	Importe,	Id_Estado_Cbte,
	Observacion,	Id_Trans_Origen,	Nro_Cuota_Origen,
	Id_Moneda,	Saldo)
	VALUES	(@Id_Trans,	1,	NULL,
	@Id_Proveedor,	@Fecha,	@Fecha_Vence,
	@Descrip_Cbte_CtaCte,@Importe,	@Id_Estado_Cbte,
	@Observacion,	0,	0,
	'PES',	@Importe)
	END

/*---------------------------------------------------------------------------------*/
--Insert: CBTES_CONCEPTOS/	
DECLARE @Id_Concepto INT
SET @Id_Concepto = (SELECT ISNULL(ID_CONCEPTO,0) FROM PROVEEDORES WHERE ID_PROVEEDOR = @Id_Proveedor)
IF @Id_Concepto > 0
	BEGIN
	INSERT INTO CBTES_CONCEPTOS (Id_Concepto, Id_Trans, Item, Importe, Observacion)
	VALUES	(@Id_Concepto,@Id_Trans,	1,@Importe,'')	
	END	 


/*---------------------------------------------------------------------------------*/
--Asiento

--EXEC CP_Cbtes_Cpra_Generar_Asi @Id_Trans

--UPDATE Cbtes SET Id_Estado_Cbte =  @Id_Estado_Cbte WHERE ID_TRANS = @ID_TRANS 

COMMIT
SELECT	 0					AS ErrorNumber 
		,0					AS ErrorSeverity  
		,0					AS ErrorState 
		,0					AS ErrorProcedure  
		,0					AS ErrorLine		
		,@Mensaje			AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_Cbtes_Ctas_Contables_Generar] 
			@pId_Trans		INT, 
			@pFlagRegenerar TINYINT
AS
SET NOCOUNT ON


IF EXISTS (SELECT 1 FROM sys.objects WHERE name = '[z_CP_Cbtes_Ctas_Contables_Generar_Version2]' AND type = 'P')
BEGIN
		EXEC CP_Cbtes_Ctas_Contables_Generar_ @pId_Trans,@pFlagRegenerar
		RETURN
END

DECLARE @Usar_Trans			TINYINT
--SET @Usar_Trans = ISNULL((SELECT 1 WHERE SERVERPROPERTY('ProductVersion') > '10.50.4000.0'),0)
IF @@TRANCOUNT > 0 SET @Usar_Trans = 0


/*Declaracion de Variables*/
DECLARE @Flag_Compromete_Asientos	SMALLINT
DECLARE @Flag_Compromete_Factura	SMALLINT
DECLARE @Flag_Compromete_Trans_Fondos SMALLINT
DECLARE @Flag_Compromete_Recibos	SMALLINT
DECLARE @Fecha_Cbte					DATETIME
DECLARE @Id_Cliente					INT
DECLARE @Id_Tipo_Cbte				CHAR(4)
DECLARE @Id_Cta_Contable			INT
DECLARE @Alias						INT
DECLARE @Id_Asiento					INT
DECLARE @Id_Centro_Costo			CHAR(10)
DECLARE @Id_Ejercicio_Corresp		INT
DECLARE @Id_Plan_Cta_Corresp		INT
DECLARE @Imp_Total_Cbte				DECIMAL(12,2)
DECLARE @Debe						DECIMAL(12,2)
DECLARE @Haber						DECIMAL(12,2)
DECLARE @Id_Producto				VARCHAR(14)
DECLARE @Id_Tipo_Reten				VARCHAR(10)
DECLARE @NroItem					SMALLINT
DECLARE @CMC_UltItem				SMALLINT
DECLARE @CMC_UltId_Periodo_Caja		INT
DECLARE @CMC_Id_Concepto			INT
DECLARE @VAL_UltId_Valor			INT
DECLARE @VAL_UltId_Periodo_Caja		INT
DECLARE @VAL_Id_Tipo_Val			CHAR(3)
DECLARE @Id_Cond_Pago				SMALLINT
DECLARE @VAL_Id_Periodo_Caja		INT
DECLARE @CP_Id_Caja					INT
DECLARE @ID_TARJETA                 VARCHAR(10)
DECLARE @ID_CTA_BANCO               SMALLINT
DECLARE @ID_TRANS_ORIGEN            INT
DECLARE @Mensaje					VARCHAR(100)
DECLARE @Imp_Original				DECIMAL (12,2) -- Agregado el 20220527
DECLARE @IMPORTE					DECIMAL (12,2) -- Agregado el 20220527
DECLARE @Importe_Fpago				DECIMAL (12,2) -- Agregado el 20220712
DECLARE @Total_Debe					DECIMAL (12,2) -- Agregado el 20220712 
DECLARE @Es_Proforma				VARCHAR (10)   -- Agregado el 20220713 
/*FIN Declaracion de Variables*/

--PRINT 'Procedimiento: CP_Cbtes_Ctas_Contables_Generar Trans: '+ CAST(@pId_Trans AS VARCHAR(10))

IF(@pId_Trans = 0)
BEGIN
	RETURN 999
END

BEGIN TRY
	IF @Usar_Trans = 1 BEGIN TRAN

	IF(@pFlagRegenerar = 1)
	BEGIN
		DELETE FROM Cbtes_Ctas_Contables WHERE Id_Trans = @pId_Trans
	END

	/*************************************************************************************************/

	SET @Id_Tipo_Cbte				= (SELECT Id_Tipo_Cbte FROM Cbtes WHERE Id_Trans = @pId_Trans)

	SELECT  @Flag_Compromete_Asientos		= ISNULL(Compromete_Asientos, 0),
			@Flag_Compromete_Factura		= ISNULL(Compromete_Factura, 0),
			@Flag_Compromete_Trans_Fondos	= ISNULL(Compromete_Trans_Fondos, 0),
			@Flag_Compromete_Recibos		= ISNULL(Compromete_Recibos, 0)
	FROM Cbtes_Tipos
	WHERE 
	Id_Tipo_Cbte = @Id_Tipo_Cbte

	/*************************************************************************************************/

	IF(@Flag_Compromete_Asientos = 0)
	BEGIN
		IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 COMMIT
		SET @Mensaje = 'El Cbte. no Genera Asiento'

		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
			
		RETURN 0
	END

	/*************************************************************************************************/

	SELECT  @Id_Cliente		= ISNULL(Id_Cliente, 0),
			@Fecha_Cbte		= ISNULL(Fecha, '19000101'),
			@Imp_Total_Cbte	= ISNULL(Imp_Total, 0)
	FROM Cbtes
	WHERE 
	Id_Trans = @pId_Trans

	/*************************************************************************************************/

	SET @Id_Ejercicio_Corresp = (SELECT Id_Ejercicio FROM Plan_Ctas_Ejercicios WHERE Fecha_Inicio <= @Fecha_Cbte AND DATEADD(dd, 1, Fecha_Cierre) > @Fecha_Cbte)
	SET @Id_Plan_Cta_Corresp = (SELECT Id_Plan_Cta FROM Plan_Ctas WHERE Id_Ejercicio = @Id_Ejercicio_Corresp)
	----PRINT 'Nro. de Ejercicio: ' + CONVERT(VARCHAR(10), @Id_Ejercicio_Corresp) + '. Nro. Plan de Cuenta: ' + CONVERT(VARCHAR(10), @Id_Plan_Cta_Corresp)

	IF(@Flag_Compromete_Factura = 1)
	BEGIN
		----PRINT 'Compromete Factura'
	
		SET @Id_Cond_Pago = (SELECT Id_Cond_Pago FROM Cbtes WHERE Id_Trans = @pId_Trans)
	
		IF(@Id_Cond_Pago NOT IN (1)) /*Si no es contado*/
		BEGIN
			----PRINT 'Cond. Pago NO ES CONTADO. @Id_Cond_Pago: ' + CONVERT(VARCHAR(10), @Id_Cond_Pago)
		
			/*Insert: Cuenta Contable: DEBE (SI la Cond. Pago NO es Contado)*/
			----PRINT 'Generacion Cuenta Contable: DEBE'
			SET @Alias = (SELECT Id_Alias_Cta_Cont_Venta FROM Clientes WHERE Id_Cliente = @Id_Cliente)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = (SELECT Id_Centro_Costo FROM Clientes WHERE Id_Cliente = @Id_Cliente)
			SET @Debe = @Imp_Total_Cbte
			SET @NroItem = 1
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			@Debe,			0/*Haber*/,			''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)
			/*FIN Insert: Cuenta Contable: DEBE (SI la Cond. Pago NO es Contado)*/
		END
		ELSE
		BEGIN
			----PRINT 'Cond. Pago ES CONTADO'
		
			/*Insert: Cuenta Contable: DEBE (SI la Cond. Pago ES Contado)*/
			----PRINT 'Generacion Cuenta Contable: DEBE'
			SET @VAL_Id_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores_Mov WHERE Id_Trans = @pId_Trans), 0)		
			SET @CP_Id_Caja = ISNULL((SELECT Id_Caja FROM Cajas_Periodos WHERE Id_Periodo_Caja = @VAL_Id_Periodo_Caja), 0)		
			SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Cajas WHERE Id_Caja = @CP_Id_Caja), 0)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Alias = @Alias AND Id_Plan_Cta = @Id_Plan_Cta_Corresp)
			SET @Id_Centro_Costo = ISNULL((SELECT Id_Cta_Contable FROM Cajas WHERE Id_Caja = @CP_Id_Caja), '')
			SET @Debe = @Imp_Total_Cbte
			SET @NroItem = 1
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
		
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			@Debe,			0/*Haber*/,			''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)
			/*FIN Insert: Cuenta Contable: DEBE (SI la Cond. Pago ES Contado)*/
		END
	
		/*Insert: Cuenta Contable: HABER*/
		----PRINT 'Generacion Cuenta Contable: HABER'
	
		--PRINT 'Generacion de Items de Productos'
		DECLARE curGenCtaCteHaber CURSOR FOR 
			SELECT DISTINCT Id_Producto FROM Cbtes_Items WHERE Id_Trans = @pId_Trans

		OPEN curGenCtaCteHaber
		FETCH NEXT FROM curGenCtaCteHaber INTO @Id_Producto
		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @Alias = (SELECT Id_Alias_Cta_Cont FROM Productos WHERE Id_Producto = @Id_Producto)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = (SELECT Id_Centro_Costo FROM Productos WHERE Id_Producto = @Id_Producto)
			SET @Haber = (SELECT SUM(Imp_Gravado) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Id_Producto = @Id_Producto)
			SET @NroItem = @NroItem + 1
		
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Producto: ' + @Id_Producto + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)

		FETCH NEXT FROM curGenCtaCteHaber INTO @Id_Producto
		END 
		CLOSE curGenCtaCteHaber;
		DEALLOCATE curGenCtaCteHaber;
		/*FIN Insert: Cuenta Contable: HABER*/
	
		----PRINT 'Generacion de Items de Percepciones'	
		DECLARE curGenCtaCteHaberPercep CURSOR FOR 
			SELECT DISTINCT Id_Tipo_Reten	FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans

		OPEN curGenCtaCteHaberPercep
		FETCH NEXT FROM curGenCtaCteHaberPercep INTO @Id_Tipo_Reten
		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @Alias = (SELECT Id_Cta_Contable FROM Cbtes_Reten_Tipos WHERE Id_Tipo_Reten = @Id_Tipo_Reten)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = ''
			SET @Haber = (SELECT SUM(Importe) FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans AND Id_Tipo_Reten = @Id_Tipo_Reten)
			SET @NroItem = @NroItem + 1
		
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Tipo_Reten: ' + @Id_Tipo_Reten + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)

		FETCH NEXT FROM curGenCtaCteHaberPercep INTO @Id_Tipo_Reten
		END 
		CLOSE curGenCtaCteHaberPercep;
		DEALLOCATE curGenCtaCteHaberPercep;
	
		----PRINT 'Generacion de Items de Iva'
		SET @Alias = (SELECT ISNULL(Valor_Integer,0) FROM xParametros WHERE IdParametro = 'Iva_Debito_Fiscal')
		SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
		SET @Id_Centro_Costo = ''
		SET @Haber = (SELECT SUM(Imp_Iva) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Id_Producto IN (SELECT Id_Producto FROM Productos WHERE Id_Iva IN (SELECT Id_Iva FROM Productos_TasaIva WHERE (Porc1 <> 0 OR Porc1 IS NOT NULL))))
	
		IF(@Haber <> 0)
		BEGIN
			SET @NroItem = @NroItem + 1
		
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)		
		END
	
		----PRINT 'FIN Compromete Factura'
	END /*IF(@Flag_Compromete_Factura = 1)*/


	IF(@Flag_Compromete_Trans_Fondos = 1)
	BEGIN
		----PRINT 'Compromete Transferencia de Fondos'
	
		/*Insert: Cuenta Contable: DEBE*/
		----PRINT 'Generacion Cuenta Contable: DEBE'
		SET @CMC_UltItem = ISNULL((SELECT MAX(Item) FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Cajas_Mov_Conceptos. Ult. Item Generado: ' + CONVERT(VARCHAR(10), @CMC_UltItem)
	
		IF(@CMC_UltItem <> 0)
		BEGIN
			SET @CMC_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans AND Item = @CMC_UltItem), 0)
		
			----PRINT 'Generacion de Items por cada concepto del Periodo de Caja: ' + CONVERT(VARCHAR(10), @CMC_UltId_Periodo_Caja)
			DECLARE curGenCtaCteDebe_CMC CURSOR FOR 
				SELECT DISTINCT Id_Concepto FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans
								AND Id_Periodo_Caja = @CMC_UltId_Periodo_Caja
		
			SET @NroItem = 0
		
			OPEN curGenCtaCteDebe_CMC
			FETCH NEXT FROM curGenCtaCteDebe_CMC INTO @CMC_Id_Concepto
			WHILE @@FETCH_STATUS = 0
			BEGIN

				SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Conceptos WHERE Id_Concepto = @CMC_Id_Concepto),0)
				SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)	
				SET @Haber = (SELECT ISNULL(SUM(Importe), 0) FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans AND Id_Concepto = @CMC_Id_Concepto AND Id_Periodo_Caja = @CMC_UltId_Periodo_Caja)
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Concepto: ' + CONVERT(VARCHAR(10), @CMC_Id_Concepto) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				@Debe,			0/*Haber*/,			''/*Observacion*/,
				@Alias,			0/*Id_Asiento*/,	''/*Id_Centro_Costo*/,
				@NroItem)

				FETCH NEXT FROM curGenCtaCteDebe_CMC INTO @CMC_Id_Concepto
			END 
			CLOSE curGenCtaCteDebe_CMC;
			DEALLOCATE curGenCtaCteDebe_CMC;
		END /*IF(@CMC_UltItem <> 0)*/
	
		/*Insert: Cuenta Contable: HABER*/
		----PRINT 'Generacion Cuenta Contable: HABER'
		SET @VAL_UltId_Valor = ISNULL((SELECT MAX(Id_Valor) FROM Valores WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
	
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
			SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE Id_Trans = @pId_Trans AND Id_Valor = @VAL_UltId_Valor), 0)
		
			----PRINT 'Generacion de Items por cada Id_Tipo_Val del Periodo de Caja: ' + CONVERT(VARCHAR(10), @VAL_UltId_Periodo_Caja)
			DECLARE curGenCtaCteHaber_Val CURSOR FOR 
				SELECT DISTINCT Id_Tipo_Val 
				FROM Valores 
				WHERE 
				Id_Trans = @pId_Trans
				AND Id_Periodo_Caja = @VAL_UltId_Periodo_Caja
		
			OPEN curGenCtaCteHaber_Val
			FETCH NEXT FROM curGenCtaCteHaber_Val INTO @VAL_Id_Tipo_Val
			WHILE @@FETCH_STATUS = 0
			BEGIN
				SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tipos WHERE Id_Tipo_Val = @VAL_Id_Tipo_Val), 0)
				SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
				SET @Haber = (SELECT SUM(Importe) FROM Valores WHERE Id_Trans = @pId_Trans AND Id_Tipo_Val = @VAL_Id_Tipo_Val AND Id_Periodo_Caja = @VAL_UltId_Periodo_Caja)
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				0/*Debe*/,		@Haber,				''/*Observacion*/,
				@Alias,			0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)

				FETCH NEXT FROM curGenCtaCteHaber_Val INTO @VAL_Id_Tipo_Val
			END 
			CLOSE curGenCtaCteHaber_Val;
			DEALLOCATE curGenCtaCteHaber_Val;		
		END
	
		----PRINT 'FIN Compromete Transferencia de Fondos'
	END /*IF(@Flag_Compromete_Trans_Fondos = 1)*/

	IF(@Flag_Compromete_Recibos = 1)
	BEGIN
	    DECLARE @Tomar_Asiento_Cbte SMALLINT 
		SET @Tomar_Asiento_Cbte = (SELECT ISNULL(Valor_Integer,0) FROM xParametros WHERE IdParametro = 'Tomar_Asiento_Cbte') 

	    SET @NroItem = 1	
		----PRINT 'Compromente Recibos'
		
		----PRINT 'Generacion Cuenta Contable: DEBE'

		SET @VAL_UltId_Valor = ISNULL((SELECT MAX(Id_Valor) FROM Valores_Mov WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
	
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
			SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE  Id_Valor = @VAL_UltId_Valor), 0)
		
			----PRINT 'Generacion de Items por cada Id_Tipo_Val del Periodo de Caja: ' + CONVERT(VARCHAR(10), @VAL_UltId_Periodo_Caja)
			DECLARE curGenCtaDEBE_Val CURSOR FOR 
					SELECT DISTINCT V.Id_Tipo_Val,ISNULL(V.ID_TARJETA,''),ISNULL(V.ID_CTA_BANCO,0)
					FROM Valores_MOV M, VALORES V 
					WHERE 
					M.Id_Trans = @pId_Trans
					AND M.ID_VALOR = V.ID_VALOR
					AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja
		
			OPEN curGenCtaDEBE_Val
			FETCH NEXT FROM curGenCtaDEBE_Val INTO @VAL_Id_Tipo_Val,@ID_TARJETA,@ID_CTA_BANCO
			WHILE @@FETCH_STATUS = 0
			BEGIN
			    SET @Alias = 0 
			    IF @VAL_Id_Tipo_Val = 'TAR'
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tarjetas_Cred WHERE ID_TARJETA = @ID_TARJETA), 0)
                   END
			    IF @VAL_Id_Tipo_Val = 'DB'
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Bancos_Ctas WHERE Id_Cta_Banco = @ID_CTA_BANCO), 0)
                   END	    
				IF @Alias = 0  
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tipos WHERE Id_Tipo_Val = @VAL_Id_Tipo_Val), 0)
                   END


				SET @Id_Cta_Contable = 	  (SELECT dbo.CF_Cta_Cont(@Alias, @Fecha_Cbte))
				SET @NroItem = @NroItem + 1
			    SET @Id_Centro_Costo = ''
			    SET @Debe = (SELECT SUM(V.Importe) FROM Valores V, Valores_Mov M WHERE M.Id_Trans = @pId_Trans AND M.id_valor = V.Id_Valor And V.Id_Tipo_Val = @VAL_Id_Tipo_Val AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja AND ISNULL(V.Id_Tarjeta,'') = @ID_TARJETA AND ISNULL(V.Id_Cta_Banco,0) = @Id_Cta_Banco)
	
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				@Debe,		0,				''/*Observacion*/,
				@Alias,		0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)

				FETCH NEXT FROM curGenCtaDEBE_Val INTO @VAL_Id_Tipo_Val,@ID_TARJETA,@ID_CTA_BANCO
			END 
			CLOSE curGenCtaDEBE_Val;
			DEALLOCATE curGenCtaDEBE_Val;		
		END

		/*Insert: Cuenta Contable: HABER*/
		----PRINT 'Generacion Cuenta Contable: HABER'
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
		
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
		    IF @Tomar_Asiento_Cbte = 0
			BEGIN
				SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE Id_Valor = @VAL_UltId_Valor), 0)
				
				SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont_Venta FROM Clientes WHERE Id_Cliente = @Id_Cliente), 0)
				SET @Id_Cta_Contable = (SELECT dbo.CF_Cta_Cont(@Alias, @Fecha_Cbte))
				SET @Haber = (SELECT SUM(V.Importe) FROM Valores V, Valores_Mov M WHERE M.Id_Trans = @pId_Trans AND M.id_valor = V.Id_Valor  AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja )
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				0/*Debe*/,		@Haber,				''/*Observacion*/,
				@Alias,			0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)
		    END
		   ELSE
			BEGIN
			SELECT * INTO #CTAS_AUX FROM CBTES_CTAS_CONTABLES WHERE ID_TRANS = 1
			DELETE #CTAS_AUX

			
			-- RESPONSABLE AGUSTIN BARRAZA
			-- Tabla temporal que se pasa al cursor // 2022.06.01
			CREATE TABLE #CBTES_APLICA_AUX (
			Id_Trans		BIGINT,
			Id_Trans_D		BIGINT
			)
			
			-- RESPONSABLE AGUSTIN BARRAZA
			-- Validacion para contemplar casos en los cuales NO EXISTE registro en cbtes aplica (pagos a cuenta) // 2022.06.01
			IF EXISTS(SELECT TOP 1 ID_TRANS FROM Cbtes_Aplica WHERE ID_TRANS_D = @pId_Trans)
			BEGIN
				
				INSERT INTO #CBTES_APLICA_AUX
				SELECT Id_Trans, id_Trans_D  FROM Cbtes_Aplica WHERE ID_TRANS_D = @pId_Trans
	
			END
			ELSE
			BEGIN
			
				INSERT INTO #CBTES_APLICA_AUX
				SELECT Id_Trans_D AS Id_Trans , Id_Trans_D  FROM Cbtes_Aplica WHERE id_trans = 1
				UPDATE #CBTES_APLICA_AUX SET Id_Trans_D = @pId_Trans
	
			END
			
			DECLARE curGenCtaDEBE_FAC_APLIC2 CURSOR FOR 
			
			-- Colocamos DISTINCT para casos en los cuales tenemos repetido el Td_trans // 20220713
			SELECT DISTINCT ID_TRANS
			FROM #CBTES_APLICA_AUX WHERE ID_TRANS_D = @pId_Trans

				OPEN curGenCtaDEBE_FAC_APLIC2
				FETCH NEXT FROM curGenCtaDEBE_FAC_APLIC2 INTO @ID_TRANS_ORIGEN
				WHILE @@FETCH_STATUS = 0
				BEGIN
				
			
					-- RESPONSABLE AGUSTIN BARRAZA
					-- Se agrega filtro que contemple pagos a cuenta // 2022-05-27
					IF(@ID_TRANS_ORIGEN = 0)
					
					BEGIN
					
						SET @ID_TRANS_ORIGEN = @pId_Trans
						
						-- RESPONSABLE AGUSTIN BARRAZA
						-- Verificamos si hay registros en Cbtes_Aplica
						IF EXISTS(SELECT ISNULL(IMPORTE,0) FROM Cbtes_Aplica WHERE id_Trans_D = @ID_TRANS_ORIGEN)
						BEGIN
							
							SET @IMPORTE = (SELECT ISNULL(IMPORTE,0) FROM Cbtes_Aplica WHERE id_Trans_D = @ID_TRANS_ORIGEN AND ID_TRANS = 0)
						END
						
						ELSE
						BEGIN
							SET @IMPORTE = (SELECT ISNULL(IMPORTE,0) FROM Valores WHERE id_TRANS = @ID_TRANS_ORIGEN)
						END
						
					END
					
					ELSE
					BEGIN
						-- RESPONSABLE AGUSTIN BARRAZA 
						-- SE AGREGA EL SUM POR CASOS EN LOS CUALES TENEMOS DOS REGISTROS EN CBTES_APLICA PARA LA MISMA Id_Trans // 20220713
						SET @IMPORTE = (SELECT ISNULL(SUM(IMPORTE),0) FROM Cbtes_Aplica WHERE id_Trans = @ID_TRANS_ORIGEN and id_trans_D = @pId_Trans)
					
					END
					
					-- INTERTO EN TABLA AUXILIAR
					INSERT INTO #CTAS_AUX
					SELECT * FROM CBTES_CTAS_CONTABLES WHERE ID_TRANS = @ID_TRANS_ORIGEN AND DEBE <> 0
					
					 /*Agrego linea 2020.09.16*/
					SET @Imp_Original = (SELECT ISNULL(Imp_Total,0) FROM Cbtes WHERE id_Trans = @ID_TRANS_ORIGEN)
					
					-- RESPONSABLE AGUSTIN BARRAZA
					-- CALCULO EN CASO DE QUE SEA UN PAGO PARCIAL, SE AGREGA EL IF // 2022.05.27
					IF(@Imp_Original<>@IMPORTE)
					BEGIN	
							/*Agrego linea 2020.09.16*/
							UPDATE #CTAS_AUX SET DEBE = Debe * @IMPORTE / @Imp_Original WHERE ID_TRANS = @ID_TRANS_ORIGEN AND DEBE <> 0
					
					END
					-- RESPONSABLE AGUSTIN BARRAZA
					-- Modifico el alias en caso de pago a cuenta // 2022.05.27
					IF(@ID_TRANS_ORIGEN = @pId_Trans)
					BEGIN
						UPDATE #CTAS_AUX SET Alias = (SELECT Valor_Integer FROM xParametros WHERE IdParametro = 'Alias_Pago_a_Cta')  WHERE ID_TRANS = @ID_TRANS_ORIGEN AND DEBE <> 0			
					END
				
					FETCH NEXT FROM curGenCtaDEBE_FAC_APLIC2 INTO @ID_TRANS_ORIGEN
					END
				
				
				-- SE AGREGA EL 20220712 --> RESPONSABLE AGUSTIN BARRAZA
				-- SE AGREGA FILRO PARA LOS CASOS EN LOS CUALES LA EL TOTAL DE LA FORMA DE PAGO SUPERA EL MONTO DE LOS CBTES APLICADOS, AHORA SE GENERA A CAJA ESE SALDO A FAVOR 20220712				
				-- CASO DE PRUEBAS: 
				-- TRANS 3526858 -> APLICA : 1844021 // 3549837
				
				
				SET @Importe_Fpago = (SELECT Importe FROM Valores WHERE Id_Trans = @pId_Trans)
				SET @Total_debe = (SELECT SUM(Debe) FROM #CTAS_AUX)
				
				IF(@Importe_Fpago <> @Total_debe)				
				BEGIN					
					SELECT TOP 1  * INTO #CTAS_AUX_F_PAGO FROM #CTAS_AUX 
					
					UPDATE #CTAS_AUX_F_PAGO 
					SET
					Alias = (SELECT Valor_Integer FROM xParametros WHERE IdParametro = 'Alias_Pago_a_Cta'),
					Debe = (@Importe_Fpago - @Total_debe)
				
					INSERT INTO #CTAS_AUX
					SELECT * FROM #CTAS_AUX_F_PAGO	
						
					DROP TABLE #CTAS_AUX_F_PAGO			
				END
				
				
				ALTER TABLE #CTAS_AUX ADD _Item INT IDENTITY(20,1)
		      	UPDATE #CTAS_AUX SET ID_TRANS = @pId_Trans,  Id_Cta_Contable = (SELECT dbo.CF_Cta_Cont(Alias, @Fecha_Cbte))
				UPDATE #CTAS_AUX SET Item = _Item, Id_Asiento = 0, Fecha = @Fecha_Cbte, HABER = DEBE
				UPDATE #CTAS_AUX SET DEBE = 0
				ALTER TABLE #CTAS_AUX DROP COLUMN _Item

				INSERT INTO CBTES_CTAS_CONTABLES 
				       SELECT * FROM #CTAS_AUX
                DROP TABLE #CTAS_AUX

			    CLOSE curGenCtaDEBE_FAC_APLIC2
			    DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 
	    	END
		
		END ----PRINT 'FIN Compromente Recibos'
	END	

	IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 COMMIT

	SET @Mensaje = 'Asiento Generado'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,@pId_Trans				AS ErrorLine		
			,@Mensaje		AS ErrorMessage

END TRY  


BEGIN CATCH  
  --  SELECT  ERROR_NUMBER() AS ErrorNumber  
		--,ERROR_SEVERITY() AS ErrorSeverity  
		--,ERROR_STATE() AS ErrorState  
		--,ERROR_PROCEDURE() AS ErrorProcedure  
		--,ERROR_LINE() AS ErrorLine  
		--,ERROR_MESSAGE() AS ErrorMessage
		--,@pId_Trans		AS Id_Trans 
    EXECUTE usp_GetErrorInfo
	IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 ROLLBACK

	IF (SELECT CURSOR_STATUS('global','curGenCtaDEBE_FAC_APLIC2') ) = -1
	   DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 

	IF (SELECT CURSOR_STATUS('global','curGenCtaDEBE_FAC_APLIC2') ) = 1
	BEGIN
	   CLOSE curGenCtaDEBE_FAC_APLIC2
	   DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 
	END



	RETURN 9999

END CATCH

--PRINT 'Fin de ejecucion: CP_Cbtes_Ctas_Contables_Generar  Trans: '+ CAST(@pId_Trans AS VARCHAR(10))

RETURN 0



-- EXEC dbo.z_CP_Cbtes_Ctas_Contables_Generar_Version2 3534694,1
GO


CREATE PROCEDURE [dbo].[CP_Cbtes_Deposito_Generar] 
@Id_Cta_Banco	INT,
@Destinatario	VARCHAR(100), 
@Importe		DECIMAL(12,2), 
@Id_Sucursal	SMALLINT,
@Fecha			DATETIME, 
@Id_Tipo_Cbte	CHAR(4),
@Lote			CHAR(14),
@Id_Estado_Cbte INT,
@Id_Cond_Pago	SMALLINT,
@Comprobante_Nro INT,
@Id_Periodo_Caja INT,
@Id_Trans Int OUTPUT

AS 
/*-----------------------------------------------------
 * OJO!: Buscar la palabra CAMBIAR en estedocumento y 
 *		 adaptar las variables al cliente.
 ------------------------------------------------------*/
SET NOCOUNT ON 
BEGIN TRAN

PRINT 'Fecha del Comprobante: '+CONVERT(VARCHAR(20), @Fecha, 101)+' Estado Comprobante: '+CONVERT(VARCHAR(3),@id_Estado_Cbte)

/*Declaracion Variables Locales*/
DECLARE @ID_Cliente             INT
DECLARE @ID_Proveedor           INT
DECLARE @Trans_Nueva			INT
DECLARE @User					SMALLINT
DECLARE @Desc					VARCHAR(50)
DECLARE @Nombre					VARCHAR(100)
DECLARE @Descripcion_Producto	VARCHAR(100)
DECLARE @Cantidad				DECIMAL(12,2)
DECLARE @Fecha_Mov				DATETIME
DECLARE @Descrip_Cbte_CtaCte	VARCHAR(100)
