CREATE PROCEDURE [dbo].[CP_Cbtes_Fac_Fin] @Id_Trans VARCHAR(20)
AS 

DECLARE @Mensaje			VARCHAR(100),@trans_ND INT
DECLARE @Id_Cond_Pago		INT

BEGIN TRY
	BEGIN TRAN
	SELECT @trans_ND = Id_trans , @Id_Cond_Pago = Id_Cond_Pago  FROM Cbtes WHERE Id_Estado_Cbte = 0 AND Id_Trans = @Id_Trans

	SET @trans_ND = ISNULL(@trans_ND,0)


	IF (@trans_ND = 0)
	BEGIN
	    SET @Mensaje = 'No hay trans de Factura'
		COMMIT
		SELECT	 1099					AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,@Mensaje			AS ErrorMessage
				,@trans_ND			AS Id_Trans		
		RETURN 1
	END
	ELSE
	BEGIN
		PRINT @trans_ND
		IF @Id_Cond_Pago = 1 -- Contado
			BEGIN
			UPDATE Cbtes SET Id_Estado_Cbte = 2,Saldo = 0			WHERE Id_Trans = @trans_ND
			UPDATE Cbtes_Items SET Id_Estado_Cbte = 2				WHERE Id_Trans = @trans_ND
			UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 2,Saldo = 0 WHERE Id_Trans = @trans_ND
			UPDATE Cajas_Mov		SET Id_Estado_Mov_Caja = 2		WHERE Id_Trans = @trans_ND  --en siempre va en completo
			END
		ELSE
			BEGIN
				UPDATE Cbtes SET Id_Estado_Cbte = 1				WHERE Id_Trans = @trans_ND
				UPDATE Cbtes_Items SET Id_Estado_Cbte = 1		WHERE Id_Trans = @trans_ND
				UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 1	WHERE Id_Trans = @trans_ND
			END
	END

	COMMIT

	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage
			,@trans_ND			AS Id_Trans

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_Cbtes_Fac_Generar] 
@Lote		VARCHAR(20), 
@Fecha		CHAR(8),
@FechaVence		CHAR(8),
@Id_Cliente INT,
@Id_Tipo_Cbte	CHAR(4),
@Id_Cond_Pago	INT,
@Id_Moneda		CHAR(3),
@Cotizacion	 DECIMAL(12,4),
@Importe	DECIMAL(12,2)
AS 

DECLARE @Nombre			VARCHAR(100)
DECLARE @NRO_CBTE		INT
DECLARE @trans_nueva	INT
DECLARE @Mensaje		VARCHAR(100)
DECLARE @Id_Sucursal	INT
DECLARE @Cbte_Grupo		INT


BEGIN TRY
	BEGIN TRAN

	--SET @Id_Tipo_Cbte = dbo.CF_xParam('Tipo_Cbte_VW_Factura')
	--SET @Id_Moneda    = dbo.CF_xParam('Moneda_Cbte_VW')



	--SET @desc = 'VW:' + @LOTE
	SET @Nombre = (SELECT rtrim(Razon_Social) FROM Clientes WHERE Id_Cliente = @Id_Cliente)

	SET @trans_nueva = (SELECT max(id_trans) from transacciones ) + 1

	/*===================================================================*/
	INSERT INTO Transacciones	(id_trans,		descripcion,	fecha_mov) 
					VALUES		(@trans_nueva,	@LOTE,			GETDATE())

	/*===================================================================*/
	SELECT	@NRO_CBTE = Prox_Nro 
			,@Id_Sucursal = Id_Sucursal 
			,@Cbte_Grupo = Cbte_Grupo
			from Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte 

	UPDATE Cbtes_Tipos SET Prox_Nro = Prox_Nro+1 WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte

	/*===================================================================*/
	INSERT INTO Cbtes	(Id_Cond_Vta,		Id_trans,		Id_Sucursal,
						Cbte_Grupo,			Fecha_Venc ,    id_cliente,
						id_estado_Cbte,		id_tipo_cbte,	comprobante_nro,
						fecha,				periodo_iva,	periodo,
						imp_total,			saldo,			imp_gravado,
						destinatario,		lote,			ID_MONEDA,
						Id_Cond_Pago,		Cotizacion)
			   VALUES	('',				@trans_nueva,	@Id_Sucursal,
						@Cbte_Grupo,		@FechaVence,	@id_cliente,
						0,					@Id_Tipo_cbte,	@NRO_CBTE,
						@FECHA,				@FECHA,			@FECHA,
						@Importe,			0,				@Importe,
						@NOMBRE,			@LOTE,			@Id_Moneda,
						@Id_Cond_Pago,		@Cotizacion)

	/*===================================================================*/
	IF @Id_Cond_Pago NOT IN(0,1)
		BEGIN
		INSERT INTO Clientes_CtaCte (Id_Trans,		Nro_Cuota,		Id_Empresa,
									Id_Cliente,		Fecha,			Fecha_Vence,
									Descripcion,	Importe,		Id_Estado_Cbte,
									Observacion,	Id_Trans_Origen,Nro_Cuota_Origen,
									Id_Moneda,		Saldo,			Nro_FacCre)
						VALUES		(@trans_nueva,	1,				NULL,
									@id_cliente,	@Fecha,			@Fecha,
									dbo.CF_Descrip_Cbte(@trans_nueva),@Importe ,1,
									'',				0,				0,
									@Id_Moneda,		@Importe,				0)


		END 
	COMMIT

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,@trans_nueva	AS ErrorLine		
			,@Mensaje		AS ErrorMessage
			,@trans_nueva	AS Id_Trans

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO

CREATE PROCEDURE [dbo].[CP_Cbtes_Fac_Generar_Item] 
	@Id_Trans		VARCHAR(20),
	@Item		INT,
	@Id_Producto CHAR(14),
	@Nota		VARCHAR(200),
	@Importe	DECIMAL(12,2),
	@Desde		DATETIME,
	@Hasta		DATETIME
AS 
--SET NOCOUNT ON 
DECLARE @descripcion_producto	VARCHAR(100)
		,@id_cliente			INT
		,@Mensaje				VARCHAR(100)

BEGIN TRY
	BEGIN TRAN


	SET @descripcion_producto = (SELECT Descripcion_Resumida FROM Productos WHERE Id_Producto  = @Id_Producto)

	SET @id_cliente = (SELECT id_cliente FROM Cbtes WHERE Id_Trans = @Id_Trans)

	INSERT INTO Cbtes_Items		(id_cliente,		descripcion_producto,		Cantidad,
							id_estado_Cbte,		Cantidad_Saldo,				Id_Trans,
							item,				Precio_Grav,				Imp_Gravado,
							Imp_Final,			Precio,						Lote,
							Fecha_QA,			Flag_QA,					Id_Producto,
							Fecha_Venc)
				VALUES		(@id_cliente,		RTRIM(@descripcion_producto),1,
							0,					1,							@Id_Trans,
							@Item,				@Importe,					@Importe,
							@Importe,			@Importe,					'',
							@Desde,				'A',						@Id_Producto,
							@Hasta)


	COMMIT

	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO


CREATE  PROCEDURE dbo.CP_Cbtes_Grabar_Numero @pId_Trans INT
AS
SET NOCOUNT ON
--PRINT 'Procedimiento: CP_Cbtes_Grabar_Numero  Trans: '+ CAST(@pId_Trans AS VARCHAR(10))

DECLARE @Mensaje				VARCHAR(100)
		,@Id_Tipo_Cbte			CHAR(4)
		,@Fecha_Cai				DATETIME
		,@Nro_Cai				VARCHAR(14)
		,@Flag_Val_Correla		TINYINT
		,@Compromete_Factura	SMALLINT
		,@Fecha					DATETIME
		,@Fecha_Cbte			DATETIME
		,@Comprobante_Nro		INT
		,@Id_Estado_Cbte		SMALLINT
		,@Id_Cond_Pago			SMALLINT
		,@Compromete_Recibos	SMALLINT
		,@Compromete_Pagos		SMALLINT
		,@Id_Tipo_Cbte_Dest		CHAR(4)
		,@Fact_Cont_FN			INT
		,@Tipo_Cbte_Dest_Cant	INT
		,@Usar_Trans			TINYINT


--SET @Usar_Trans = ISNULL((SELECT 1 WHERE SERVERPROPERTY('ProductVersion') > '10.50.4000.0'),0)
IF @@TRANCOUNT > 0 SET @Usar_Trans = 0

--Usamos transacciones a partir del SQL 2012 en adelante

/*

8.0 	2000 	SQL Server 20007​ 		Shiloh
8.0 	2003 	SQL Server 2000			64-bit Edition 	Liberty
9.0 	2005 	SQL Server 20058​ 		Yukon
10.0 	2008 	SQL Server 20089​ 		Katmai
10.25 	2010 	SQL Azure DB 			CloudDatabase
10.50 	2010 	SQL Server 2008 R210​ 	Kilimanjaro
11.0 	2012 	SQL Server 201211​ 		Denali
12.0 	2015 	SQL Server 201412​ 		SQL14 (antes Hekaton)
13.0 	2016 	SQL Server 2016 		SQL16
14.0 	2017 	SQL Server 2017 		vNext 2017
15.0 	2019 	SQL Server 2019 		Seattle 


*/



						
BEGIN TRY
	IF @Usar_Trans = 1	BEGIN TRAN

	IF (NOT EXISTS (SELECT 1 FROM Cbtes WHERE Id_Trans = @pId_Trans))
	BEGIN
		SELECT	 1					AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,@pId_Trans					AS ErrorLine		
				,'No Existe Cbte de Origen'			AS ErrorMessage
		IF @Usar_Trans = 1 AND @@TRANCOUNT > 0	ROLLBACK
		RETURN 9999
    END

	SET @Id_Tipo_Cbte_Dest = (SELECT C.Id_Tipo_Cbte FROM Cbtes C WHERE C.Id_Trans = @pId_Trans)
	SET @Id_Tipo_Cbte_Dest =  dbo.CF_Cbte_Traer_Tipo_Dest(@Id_Tipo_Cbte_Dest)
	SET @Tipo_Cbte_Dest_Cant = ISNULL((SELECT COUNT(*) FROM Cbtes_Tipos WHERE Id_Tipo_Cbte_Dest = @Id_Tipo_Cbte_Dest),0)


	SET @Fact_Cont_FN = CAST( dbo.CF_xParam('Fact_Cont_FN') AS INT )


	SELECT @Id_Tipo_Cbte = ISNULL(T.Id_Tipo_Cbte,'')
			, @Fecha_Cai = T.Fecha_Cai
			, @Nro_Cai = T.Nro_Cai
			, @Flag_Val_Correla = ISNULL(T.Flag_Val_Correla,0)
			, @Compromete_Factura = ISNULL(T.Compromete_Factura,0)
			, @Id_Estado_Cbte = ISNULL(T.Id_Estado_Cbte,0)
			, @Id_Cond_Pago = ISNULL(C.Id_Cond_Pago,0)
			, @Compromete_Recibos = ISNULL(Compromete_Recibos,0)
			, @Compromete_Pagos	= ISNULL(Compromete_Pagos,0)
			, @Fecha_Cbte = C.Fecha
			, @Comprobante_Nro = ISNULL(T.Prox_Nro,1)
			FROM Cbtes_Tipos T, Cbtes C
			WHERE T.Id_Tipo_Cbte = @Id_Tipo_Cbte_Dest
			AND C.Id_Trans = @pId_Trans

    IF @Flag_Val_Correla = 1 OR (@Compromete_Factura <> 0 AND @Fact_Cont_FN <> 0 )
	BEGIN
	   IF @Tipo_Cbte_Dest_Cant = 0
		   SELECT @Fecha = MAX(Fecha),@Comprobante_Nro = ISNULL(MAX(Comprobante_Nro),0) + 1 
				FROM Cbtes 
				WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte_Dest AND NOT (Id_Estado_Cbte = 3 AND Comprobante_Nro = 0)

	   ELSE
		   SELECT @Fecha = MAX(Fecha),@Comprobante_Nro = ISNULL(MAX(Comprobante_Nro),0) + 1 
				FROM Cbtes 
				WHERE (Id_Tipo_Cbte = @Id_Tipo_Cbte 
					OR Id_Tipo_Cbte  IN (SELECT Id_Tipo_Cbte FROM Cbtes_Tipos WHERE Id_Tipo_Cbte_Dest = @Id_Tipo_Cbte)) --para destino y todos los cbtes que dependen del destino
					AND NOT (Id_Estado_Cbte = 3 AND Comprobante_Nro = 0)

	   SET @Fecha = ISNULL(@Fecha,GETDATE())
	   SET @Comprobante_Nro = ISNULL(@Comprobante_Nro,1)
	   IF @Fecha > @Fecha_Cbte
			SET @Fecha_Cbte = @Fecha
	END

	IF @Id_Estado_Cbte = 0  --si no tenia valor por defecto
	BEGIN
		SET @Id_Estado_Cbte = 1  --Pendiente
		IF (@Compromete_Factura <> 0 AND @Id_Cond_Pago = 1 ) OR @Compromete_Recibos <> 0 OR @Compromete_Pagos <> 0
			SET @Id_Estado_Cbte = 2	 --Completo
	END


	UPDATE Cbtes SET Comprobante_Nro = @Comprobante_Nro 
						,Fecha = @Fecha_Cbte
						,Id_Estado_Cbte = @Id_Estado_Cbte
						,Cai_Vence  = @Fecha_Cai
						,Cai = @Nro_Cai
						,Nro_Auto_Trib = @Nro_Cai
						 WHERE Id_Trans = @pId_Trans
	UPDATE Cbtes_Tipos SET Fecha_Ult = @Fecha_Cbte, Prox_Nro = @Comprobante_Nro + 1
			WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte 
					OR Id_Tipo_Cbte  IN (SELECT Id_Tipo_Cbte FROM Cbtes_Tipos 
					WHERE Id_Tipo_Cbte_Dest = @Id_Tipo_Cbte) --para destino y todos los cbtes que dependen del destino

	IF @Usar_Trans = 1 AND @@TRANCOUNT > 0	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,@Comprobante_Nro	AS ErrorLine		
			,@Mensaje			AS ErrorMessage


END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo
	IF @Usar_Trans = 1 AND @@TRANCOUNT > 0	ROLLBACK
	RETURN 9999
END CATCH;   

--PRINT 'FIN Procedimiento: CP_Cbtes_Grabar_Numero  Trans: '+ CAST(@pId_Trans AS VARCHAR(10))
RETURN 0
GO

CREATE PROCEDURE [dbo].[CP_Cbtes_Items_Alta_Online] 
	@LOTE		VARCHAR(20),
	@Item		INT,
	@Id_Producto CHAR(14),
	@Nota		VARCHAR(200),
	@Importe	DECIMAL(12,2),
	@Desde		DATETIME,
	@Hasta		DATETIME,
	@pCantidad	DECIMAL(12,4),
	@Id_Cliente	INT
AS 
--SET NOCOUNT ON 
DECLARE @trans_nueva INTEGER,@descripcion_producto VARCHAR(100)
DECLARE @Mensaje			VARCHAR(100)
DECLARE @Flag_Periodo_Tipo		CHAR(1)	
DECLARE @Flag_Periodo			TINYINT	
DECLARE @Flag_Periodo_Cant		INT

BEGIN TRY
	BEGIN TRAN

	SET @trans_nueva = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = 'VW:' + @LOTE AND Id_Estado_Cbte = 0),0)
	IF (@trans_nueva = 0)
	BEGIN
		SET @Mensaje = 'Sin Transación para ese lote'
		PRINT @Mensaje
		SELECT 1,0,0,0,0,@Mensaje
		ROLLBACK
		RETURN 1
	END
	
/*========================================================================*/
SELECT 
			@Flag_Periodo			= ISNULL(Flag_Periodo,0),
			@Flag_Periodo_Tipo		= ISNULL(Flag_Periodo_Tipo,''),
			@Flag_Periodo_Cant		= ISNULL(Flag_Periodo_Cant,0)
	FROM Productos
	WHERE 
	Id_Producto = @Id_Producto	
/*========================================================================*/	

/*Se agrega el calculo de Periodo para agregar a los productos que tienen seteos en sus fichas 20200812*/
	IF(@Flag_Periodo = 1)
	BEGIN
		IF(@Flag_Periodo_Tipo='A') SET @Hasta = CAST(@Desde AS DATETIME) + 360
		IF(@Flag_Periodo_Tipo='M') 
		BEGIN
			IF(@Flag_Periodo_Cant =6)
				SET @Hasta = dbo.CF_EOMONTH(DATEADD(month,6,@Desde)) 
			ELSE IF(@Flag_Periodo_Cant = 3)	
				SET @Hasta = dbo.CF_EOMONTH(DATEADD(month,6,@Desde)) 
			ELSE
				SET @Hasta = dbo.CF_EOMONTH(@Desde) 
		END
		IF (@Flag_Periodo_Tipo='D')
		BEGIN
			IF (@Flag_Periodo_Cant=15)	SET @Hasta = DATEADD(day,15,@Desde)
			IF (@Flag_Periodo_Cant=7)	SET @Hasta = DATEADD(day,7,@Desde)
		END
		ELSE 
			  SET @Hasta = @Desde
	END
	/*Fin Seteos-------------------------*/


	SET @descripcion_producto = (SELECT Descripcion_Resumida FROM Productos WHERE Id_Producto  = @Id_Producto)

	IF(@id_cliente = 0)
		SET @id_cliente = (SELECT id_cliente FROM Cbtes WHERE Id_Trans = @trans_nueva)

	INSERT INTO Cbtes_Items		(id_cliente,		descripcion_producto,		Cantidad,
							id_estado_Cbte,		Cantidad_Saldo,				Id_Trans,
							item,				Precio_Grav,				Imp_Gravado,
							Imp_Final,			Precio,						Lote,
							Fecha_QA,			Flag_QA,					Id_Producto,
							Fecha_Venc)
				VALUES		(@Id_Cliente,		RTRIM(@descripcion_producto),@pCantidad,
							0,					@pCantidad,							@trans_nueva,
							@Item,				@Importe,					@Importe,
							@Importe,			@Importe,					'VW:' + @LOTE,
							@Desde,				'A',						@Id_Producto,
							@Hasta)


	COMMIT

	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO



CREATE PROCEDURE [dbo].[CP_Cbtes_Items_Cpra_Agr]    @Id_Producto varchar(40),
                                            @trans int,
											@cantidad_item decimal(14,4)=NULL,
											@importe_item decimal(12,2)=NULL,
									        @fecha datetime,
											@observacion varchar(200) = '',
											@descripcion_producto varchar(100)
										
AS

declare @Id_trans int
declare @item int
declare @nuevoItem int 
declare @producto varchar(20)
declare @cantidad decimal (14,4)
declare @test varchar(14)
declare @fecha_vto datetime
declare @fecha_caducidad datetime
declare @serie varchar(100)
declare @cantiAJU decimal (14,4)
declare @cantiVMAT decimal (14,4)
declare @estado int

BEGIN TRY
    	SET @Id_trans = @Trans

		set @nuevoItem = (select ISNULL(max(Item),0)+1 from cbtes_items where Id_Trans = @trans)
		SET @serie = ''
		IF ((RTRIM(LTRIM(@descripcion_producto)))<> '')
		Begin
