			VALUES                  (@trans,@nuevoItem,1         ,@cantidad_item, @Id_Producto,@fecha  ,@cantidad_item,@Fecha,@Fecha,@Serie,@descripcion_producto,@Observacion,@Fecha,'A',@importe_item,@importe_item,@importe_item) 
		End

	
	RETURN 0
END TRY

BEGIN CATCH
	RETURN 1
END CATCH
GO

CREATE PROCEDURE CP_Cbtes_Lote_Cambiar_OnLine (
	@Id_Trans					INT,	
	@Lote						VARCHAR(20)
	) 
AS
 
DECLARE @LoteAnt			VARCHAR(20)
DECLARE @Mensaje			VARCHAR(100)

BEGIN TRY
BEGIN TRAN


	SET @LoteAnt =	ISNULL((SELECT Lote FROM Cbtes WHERE Id_Trans = @Id_Trans),'')
	IF (SUBSTRING(@LoteAnt,1,3) NOT IN ('VW:','CW:'))
	BEGIN
		SELECT	 1					AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,'El cbte no es Online'			AS ErrorMessage
		RETURN 1
	END 

    SET @LoteAnt = LTRIM(SUBSTRING(@LoteAnt,4,17) )

	UPDATE Cbtes SET Lote = 'VW:' + RTRIM(LTRIM(@Lote)) WHERE Lote = 'VW:' + RTRIM(LTRIM(@LoteAnt))

	UPDATE Cbtes SET Lote = 'CW:' + RTRIM(LTRIM(@Lote)) WHERE Lote = 'CW:' + RTRIM(LTRIM(@LoteAnt))

	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO



CREATE PROCEDURE dbo.CP_Cbtes_Lotes_Anular 
@pLote			 VARCHAR(20),
@pMotivoAnulacion VARCHAR(1000),
@pId_Usuario	 SMALLINT
AS 
DECLARE @Mensaje				VARCHAR(100)
		,@Usuario				VARCHAR(200)
		,@Flag_Existe_Usuario	SMALLINT



BEGIN TRY
	BEGIN TRAN

	SET @Flag_Existe_Usuario = ISNULL((SELECT 1 FROM Seg_User WHERE No = @pId_Usuario), 0)
	IF (@Flag_Existe_Usuario = 0)
	BEGIN
		SET @Mensaje = 'No existe el usuario '

		SELECT	1001			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,0				AS Id_Trans
		ROLLBACK
		RETURN 1001
	END

	SET @Usuario = ISNULL((SELECT RTRIM(LTRIM(LastName)) +' '+ RTRIM(LTRIM(FirstName))  FROM Seg_User WHERE No = @pId_Usuario),'NO IDENTIFICADO')
	

	SELECT Id_Trans INTO #Trans FROM Cbtes C, Cbtes_Tipos T
		WHERE C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
		AND T.Compromete_Factura IN (1,-1)
		AND C.Lote = @pLote 
		AND C.Id_Estado_Cbte IN (1)
	
	UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 3 
		FROM Clientes_CtaCte C, #Trans T
		WHERE T.Id_Trans  = C.id_Trans


	UPDATE Cbtes_Items SET Id_Estado_Cbte = 3 
		FROM Cbtes_Items C, #Trans T
		WHERE T.Id_Trans  = C.id_Trans


	UPDATE Cbtes SET Id_Estado_Cbte = 3
					,Imp_Neto = 0
					,Imp_DescEspecial  = 0
					,Imp_DescFin  = 0
					,Imp_Bonificacion  = 0
					,Imp_Gravado  = 0
					,Imp_Exento  = 0
					,Imp_IVA  = 0
					,Imp_IVA2  = 0
					,Imp_Percepcion_IB  = 0
					,Imp_Percepcion_Iva  = 0
					,Imp_Total  = 0
					,Imp_Gravado2  = 0
					,Imp_Gravado3  = 0
					,Imp_NoGravado  = 0
					,Imp_IVA3  = 0
					,Imp_Percep  = 0
					,Saldo  = 0
					,Saldo_Iva_Recup  = 0
					,Observacion = LTRIM(RTRIM(@pMotivoAnulacion)) + 
					              CHAR(13) + CHAR(10) +
								  'Anulado por '+  @Usuario +
					              CHAR(13) + CHAR(10) +
								  '---'+ 
								  CHAR(13) + CHAR(10) + 
								  LTRIM(RTRIM(C.Observacion))
		FROM Cbtes C, #Trans T
		WHERE T.Id_Trans  = C.id_Trans

	
	
	COMMIT

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage
			,(SELECT COUNT(*) FROM #Trans) AS Cant_Cbtes
	RETURN 0		

END TRY
  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
	RETURN 999
END CATCH;
GO

CREATE PROCEDURE [dbo].[CP_Cbtes_Lotes_Cobranza]
	@pLote				VARCHAR(29),
	@pFecha				DATETIME,
	@pDescripcion		VARCHAR(50),
	@pId_Lote_Tipo		SMALLINT,
	@pId_Periodo_Caja	INT,
	@pFecha_Rec			DATETIME,
	@pId_Tipo_Cbte		CHAR(4),
	@pId_Moneda			CHAR(3),
	@pCotizacion		DECIMAL(9, 4),
	@pId_Tipo_Val		CHAR(3),
	@pImporte			DECIMAL(16,2),
	@pUsuario			INT,
	@pId_Tarjeta        VARCHAR(10),
	@pId_Cta_banco      INT,
	@pId_Cobrador		VARCHAR(10) /*21/05/2020 Agregado x Ticket 19.849*/
AS
SET NOCOUNT ON

/*Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@Id_Cliente		INT
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Trans_Rec		INT
		,@CursorOpen        INT
		,@Flag_Cbte_Tipo	SMALLINT
		,@Sql               VARCHAR(5000)
		,@Imp_SP            VARCHAR(1000) 


  DECLARE @Respuesta Table (
				ErrorNumber		INT,
				ErrorSeverity	INT,
				ErrorState		INT,
				ErrorProcedure  VARCHAR(1000),
				ErrorLine		INT,
				ErrorMessage	VARCHAR(1000)
				)

BEGIN TRY


	/*Agregar Lote con fecha de inicio y [Flag_enProceso] en 1 */

	INSERT INTO Cbtes_Lotes (Lote,Fecha,Descripcion,Id_Lote_Tipo,Flag_enProceso,Fecha_Inicio)
		VALUES (@pLote,@pFecha,@pDescripcion,@pId_Lote_Tipo,1,GETDATE())



	/*Recorrer los tagueados */

	DECLARE TagCbtesCursor CURSOR FOR
		SELECT T.Ptr AS Id_Trans, C.Id_Cliente,T.Importe , C.Email_Cob
				FROM TagFile_ T , Clientes C
				WHERE Tbl = 300 AND Usr = @pUsuario
				AND C.Id_Cliente = CAST(T.Val AS INT)

	OPEN TagCbtesCursor

	FETCH NEXT FROM TagCbtesCursor INTO @Id_Trans,@Id_Cliente,@Importe,@Email_Cob
	SET @CursorOpen = 0	
	SET @UltError = 0
	WHILE @@FETCH_STATUS=0 AND @UltError  = 0
	BEGIN
	        SET @CursorOpen = 1	

		    SET @Id_Trans_Rec = 0

			DELETE @Respuesta
			INSERT INTO @Respuesta
			EXEC @UltError = CP_Cbtes_Rec_Generar @pUsuario, @Id_Cliente,@Email_Cob,@pId_Periodo_Caja,@pFecha_Rec,@Importe,@pId_Tipo_Cbte,@pId_Moneda,@pCotizacion,@pLote, @pId_Cobrador
			IF @UltError <> 0
				BEGIN
					ROLLBACK
					SELECT * FROM @Respuesta	
					RETURN 4567
				END
			ELSE	
				SELECT TOP 1 @Id_Trans_Rec = ErrorLine FROM @Respuesta

            IF @Id_Trans_Rec = 0
			BEGIN
				ROLLBACK
				SELECT	 4568			AS ErrorNumber 
						,0				AS ErrorSeverity  
						,0				AS ErrorState 
						,0				AS ErrorProcedure  
						,0				AS ErrorLine		
						,'No se genero el numero de trans recibo'		AS ErrorMessage
				RETURN 4568
			END


			DELETE @Respuesta
			INSERT INTO @Respuesta
			EXEC @UltError = CP_Cbtes_Rec_Generar_Item @Id_Trans_Rec,1,'',1,@Id_Trans,@Importe
			IF @UltError <> 0
			BEGIN
				ROLLBACK
				SELECT * FROM @Respuesta	
				RETURN 4569
			END


			DELETE @Respuesta
			INSERT INTO @Respuesta
			EXEC @UltError = CP_Cbtes_Rec_Generar_Pago @Id_Trans_Rec,@pId_Tipo_Val,0,@pFecha_Rec,@pFecha_Rec,@pFecha_Rec,@pFecha_Rec,@Importe,@pId_Tarjeta,'',NULL,'','',0,@pId_Cta_banco
			IF @UltError <> 0
			BEGIN
				ROLLBACK
				SELECT * FROM @Respuesta	
				RETURN 4570
			END

			
			
			DELETE @Respuesta
			INSERT INTO @Respuesta
			EXEC @UltError = CP_Cbtes_Rec_Fin @Id_Trans_Rec
			
			IF @UltError <> 0
			BEGIN
				ROLLBACK
				SELECT * FROM @Respuesta	
				RETURN 4571
			END
			
				
   			FETCH NEXT FROM TagCbtesCursor INTO @Id_Trans,@Id_Cliente,@Importe,@Email_Cob	

	END
	CLOSE TagCbtesCursor
	DEALLOCATE TagCbtesCursor
	SET @CursorOpen = 0	

	/*Actualizar Lote con fecha de fin y [Flag_enProceso] en 0 y totales */
	UPDATE Cbtes_Lotes SET	Cantidad = (SELECT COUNT(*) FROM Cbtes WHERE Lote = @pLote) ,
							Importe =  (SELECT SUM(Imp_Total) FROM Cbtes WHERE Lote = @pLote),
							Fecha_Finalizacion = GETDATE(),
							Flag_enProceso = 0
			WHERE Lote = @pLote
			
	/*CURSOR DE LOS CBTES DEL LOTE */

    SELECT @Imp_SP = ISNULL(Imp_Sp,'') FROM CBTES_TIPOS WHERE ID_TIPO_CBTE = @pId_Tipo_Cbte
	
	IF @Imp_SP <> ''
	BEGIN	

		DECLARE Cursor_Fact_Pro CURSOR FOR
		SELECT c.Id_Trans
		FROM cbtes c
		WHERE c.lote = @pLote
		
		
		OPEN Cursor_Fact_Pro
		FETCH NEXT FROM Cursor_Fact_Pro INTO  @Id_trans
		WHILE @@FETCH_STATUS = 0
		BEGIN	

		    SET @sql = 'EXEC '+ LTRIM(RTRIM(@Imp_SP)) +' '+ CAST(@Id_Trans AS VARCHAR(10))

			EXEC(@sql)
			
		FETCH NEXT FROM Cursor_Fact_Pro INTO @Id_Trans
		END
		CLOSE Cursor_Fact_Pro
		DEALLOCATE Cursor_Fact_Pro
	END
	/*FIN */
		
	/******************************fin del proceso***********************************************/


	/*******************    En caso de error deberia grabar en la tablla cbtes_errores ***********************/

	


	SET @Mensaje = (SELECT DATEDIFF(s,Fecha_Inicio,Fecha_Finalizacion) FROM CBTES_LOTES WHERE LOTE = @pLote)

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage
END TRY  


BEGIN CATCH  
    
    EXECUTE usp_GetErrorInfo
	
	UPDATE Cbtes_Lotes SET	Cantidad = (SELECT COUNT(*) FROM Cbtes WHERE Lote = @pLote) ,
							Importe =  (SELECT SUM(Imp_Total) FROM Cbtes WHERE Lote = @pLote),
							Fecha_Finalizacion = GETDATE(),
							Flag_enProceso = 0
			WHERE Lote = @pLote

      IF @CursorOpen = 1
	     BEGIN 
		 	CLOSE TagCbtesCursor
	        DEALLOCATE TagCbtesCursor
         END
		 	
	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[CP_Cbtes_OP_Varia_Generar] 
@Id_Cta_Banco	INT,
@Destinatario	VARCHAR(100), 
@Importe		DECIMAL(12,2), 
@Id_Sucursal	SMALLINT,
@Fecha			DATETIME, 
@Id_Tipo_Cbte	CHAR(4),
@Lote			CHAR(14),
@Id_Estado_Cbte INT,
@Id_Cond_Pago	SMALLINT,
@Comprobante_Nro INT,
@Id_Periodo_Caja INT,
@Id_Trans Int OUTPUT

AS 
/*-----------------------------------------------------
 * OJO!: Buscar la palabra CAMBIAR en estedocumento y 
 *		 adaptar las variables al cliente.
 ------------------------------------------------------*/
SET NOCOUNT ON 
BEGIN TRAN

PRINT 'Fecha del Comprobante: '+CONVERT(VARCHAR(20), @Fecha, 101)+' Estado Comprobante: '+CONVERT(VARCHAR(3),@id_Estado_Cbte)

/*Declaracion Variables Locales*/
DECLARE @ID_Cliente             INT
DECLARE @ID_Proveedor           INT
DECLARE @Trans_Nueva			INT
DECLARE @User					SMALLINT
DECLARE @Desc					VARCHAR(50)
DECLARE @Nombre					VARCHAR(100)
DECLARE @Descripcion_Producto	VARCHAR(100)
DECLARE @Cantidad				DECIMAL(12,2)
DECLARE @Fecha_Mov				DATETIME
DECLARE @Descrip_Cbte_CtaCte	VARCHAR(100)
DECLARE @Signo					INT
DECLARE @ImporteXCant			DECIMAL(12,2)
DECLARE	@Observacion			VARCHAR(100)
DECLARE @Compromete_Pagos		SMALLINT
DECLARE @Compromete_Compras		SMALLINT
DECLARE @Id_Iva					CHAR(3)
Declare  @Alias_D SmallInt
		,@Alias_H SmallInt
		,@ID_Cta_Debe  Int
		,@ID_Cta_Haber Int
		,@ID_Centro_Costo CHAR(10)
		,@Id_Producto VARCHAR(14)
		,@Id_Valor INT
		,@Id_Tipo_Val VARCHAR(3)
		,@Descrip_Val VARCHAR(50)
		,@Nro_Cuenta VARCHAR(20) 


/*FIN Declaracion Variables Locales*/

/*Asignacion Variables*/
SET @Trans_Nueva			= ISNULL((SELECT (MAX(id_trans)+1)	FROM Transacciones),1)
SET @Desc					= @Lote
SET @Observacion			= 'Comprobante Generado desde liquidacion promociones.'
IF @Id_Cta_Banco > 0
   BEGIN
     SET @Id_Cliente		     = (SELECT Id_cliente FROM Bancos_Ctas WHERE Id_Cta_Banco = @Id_Cta_Banco)
     SET @Destinatario           = 'TRANSFERENCIA ' + (SELECT Razon_Social FROM Clientes WHERE Id_Cliente = @Id_Cliente)
   END
/*FIN Asignacion Variables*/

SET @Signo = 1

/*---------------------------------------------------------------------------------*/

/*Insert: TRANSACCIONES*/
PRINT 'Inserto la Transaccion Nro: ' + CONVERT(VARCHAR(20), @Trans_Nueva)

INSERT INTO Transacciones	(Id_Trans,		Descripcion,	Fecha_Mov) 
VALUES						(@Trans_Nueva,	@Desc,			GETDATE())

IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN
END	 
/*FIN Insert: TRANSACCIONES*/
-- Busco nro de Cbte y actualizo

	SET @Comprobante_Nro    = (SELECT PROX_NRO from CBTES_TIPOS WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte)
	SET @Id_Sucursal = (SELECT Sucursal_Nro from Empresas_Suc E, Cbtes_Tipos T WHERE T.ID_TIPO_CBTE = @Id_Tipo_Cbte And T.Id_Sucursal = E.Id_Sucursal)
	UPDATE Cbtes_Tipos SET PROX_NRO = @Comprobante_Nro+1 WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte
	SET @Id_Estado_Cbte = 2

/*---------------------------------------------------------------------------------*/

/*Insert: CBTES*/
SET @ImporteXCant = (@Importe)

PRINT 'Inserto en Cbtes'
INSERT INTO Cbtes			(Id_Trans,			Id_Sucursal,		Id_Tipo_Cbte,
							Cbte_Grupo,			Comprobante_Nro,	Id_Cliente,
							Id_Proveedor,		Signo,				Id_Estado_Cbte,
							Fecha,				Porc_DescEspecial,	Imp_Bonificacion,
							Imp_Gravado,		Imp_Exento,			Imp_IVA,
							Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
							Imp_Total,			Id_Usuario,			Porc_Iva3,
							Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
							Imp_IVA3,			Imp_Percep,			Saldo,
							Periodo_Iva,		Periodo,			Fecha_Venc,
							Observacion,		Id_Cond_Pago,		Cant_Cuotas,
							Cantidad,			Id_Lista,			Id_Moneda,
							Cotizacion,			Destinatario,		Id_Iva,
							Saldo_Iva_Recup,	Lote,				Id_Asiento,
							Id_Valor,			Cai,				Cantidad_Saldo,
							Saldo_Anterior,		Porc_DescFin,		Porc_Bonificacion,
							Porc_Iva,			Porc_Iva2,			Imp_Neto,
							Imp_DescEspecial,	Imp_DescFin)
VALUES						(@Trans_Nueva,		@Id_Sucursal,		@Id_Tipo_cbte,
							0/*Cbte_Grupo*/,	@Comprobante_Nro,0/*@Id_Cliente*/,
							0/*Id_Proveedor*/,	0/*Signo*/,	@Id_Estado_Cbte,
							@Fecha,				0/*Porc_DescEspec*/,0/*Imp_Bonificacion*/,
							@ImporteXCant/*Imp_Gravado*/,	0/*@ImporteXCant*/,		0/*Imp_Iva*/,
							0/*Imp_Iva2*/,		0/*Imp_Percepcion_*/,0/*Imp_Percepcion_Iva*/,
							@ImporteXCant,	0/*Id_Usuario*/,	0/*Porc_Iva3*/,
							0/*Imp_Gravado2*/,	0/*Imp_Gravado3*/,	0/*Imp_NoGravado*/,
							0/*Imp_IVA3*/,		0/*Imp_Percep*/,	@ImporteXCant,
							@Fecha,				@Fecha,				@Fecha,
							@Observacion,		@Id_Cond_Pago,		1/*Cant_Cuotas*/,
							0/*Cantidad*/,		0/*Id_Lista*/,		'PES'/*Id_Moneda*/,
							1/*Cotizacion*/,	@Destinatario,		@Id_Iva/*Id_Iva*/,
							0/*Saldo_Iva_Recu*/,@Lote,				0/*Id_Asiento*/,
							0/*Id_Valor*/,		0/*Cai*/,			0/*Cantidad_Saldo*/,
							0/*Saldo_Anterior*/,0/*Porc_DescFin*/,	0/*Porc_Bonificacion*/,
							0/*Porc_Iva*/,	0/*Porc_Iva2*/,0/*importe_neto*/,
							0/*Imp_DescEspecial*/,0/*Imp_DescFin*/)
							
IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN
END	 
/*FIN Insert: CBTES*/

/*---------------------------------------------------------------------------------*/
--Genero Item

    SET @Id_Producto =  (select Valor_String from xParametros where setDatos= 1 and idParametro ='C_Prod_Dep_Cta_Prom')
    SET @Descripcion_Producto = (SELECT DESCRIPCION_DETALLADA FROM PRODUCTOS WHERE ID_PRODUCTO = @Id_Producto)
--	EXEC dbo.SP_CbteItem_Agr   @Id_Producto,@Trans_Nueva,1,@ImporteXCant,@fecha,'',@Descripcion_Producto,0,0

/*---------------------------------------------------------------------------------*/
	
	 --Insert: CAJAS_MOV /	

	  	SET @Descrip_Cbte_CtaCte =  (Select Dbo.CF_Descrip_Cbte(@trans_nueva)) 

	   	INSERT INTO CAJAS_MOV (Id_Trans, Renglon_Nro, Id_Estado_Mov_Caja, Importe, Descripcion,        Id_Periodo_Caja,Id_Tipo_Mov_Caja, Fecha)
		         VALUES   	  (@trans_nueva,     1,           2,        @Importe*-1,@Descrip_Cbte_CtaCte,@Id_Periodo_Caja,   6,       @Fecha)	

		IF (@@ERROR <> 0)
		BEGIN
			ROLLBACK
			RETURN
		END	 

	 --Insert: CAJAS_MOV_CONCEPTOS /	
		INSERT INTO Cajas_Mov_Conceptos (Id_Trans, Id_Concepto, Item, Id_Estado_Concepto, Importe, Id_Periodo_Caja)
		       VALUES	(@trans_nueva,80,1,0,@Importe*-1,@Id_Periodo_Caja)	

		IF (@@ERROR <> 0)
		BEGIN
			ROLLBACK
			RETURN
		END	 

  -- insert BANCOS_CTAS_MOV
        DECLARE @ID_MOV_CTA_BANCO INT,
		        @ID_CTA_BANCO_ORIGEN INT

		SET @ID_MOV_CTA_BANCO = (SELECT MAX(ID_MOV_CTA_BANCO) FROM BANCOS_CTAS_MOV)+1
	--	SET @ID_CTA_BANCO_ORIGEN = (SELECT Id_Cta_Banco_Acumuladora FROM BANCOS_CTAS WHERE ID_CTA_BANCO = @ID_CTA_BANCO)
        SET @ID_CTA_BANCO_ORIGEN = (select Valor_Integer from xParametros where setDatos= 1 and idParametro ='Cta_Bco_OP_Prom')
	   	INSERT INTO BANCOS_CTAS_MOV (Id_Mov_Cta_Banco,Id_Trans,Id_Cta_Banco,Id_Tipo_Mov_Cta_Banco, Importe, Id_Est_Mov_Cta_Banco, Comprobante_Nro,Conciliado,Fecha_Acreditacion,Descripcion,Fecha_Mov)
		         VALUES    (@ID_MOV_CTA_BANCO,@trans_nueva, @ID_CTA_BANCO_ORIGEN,1, @Importe,1,0,0,@Fecha,@Descrip_Cbte_CtaCte,@Fecha)	

		IF (@@ERROR <> 0)
		BEGIN
			ROLLBACK
			RETURN
		END	   
	---------------------------------------
	-- agrego valores

	SET @Id_Valor			= (SELECT MAX(id_valor) FROM valores ) + 1
	SET @Id_Tipo_Val  =  (select Valor_String from xParametros where setDatos= 1 and idParametro ='T_Valor_OP_Prom')
	SET @Id_Cta_Banco =  (select Valor_Integer from xParametros where setDatos= 1 and idParametro ='Cta_Bco_OP_Prom')
	Set @Nro_cuenta   = (select Cuenta_Nro from Bancos_Ctas  where Id_cta_Banco = @Id_Cta_Banco)  
    SET @Descrip_Val  = '$ DEP/DEB BANCARIO Cuenta:' + LTRIM(@Nro_cuenta) +' Fecha: ' +  CONVERT(VARCHAR(10), @FECHA, 103)

	PRINT 'Inserto en Valores'
	/*CAMBIAR*/
	INSERT INTO Valores	(Id_Valor,			Id_Valor_Origen,	Id_Trans,
						Id_Estado_Valor,	Id_Tipo_Val,		Valor_Nro,
						Descripcion,		Id_Cliente,			Id_Proveedor,
						Id_Banco,			Id_Cta_Banco,		Id_Mov_Caja,
						Id_Moneda,			Id_Tarjeta,			Tarjeta_Nro,
						Cotizacion,			Id_Periodo_Caja,	Propio,
						Transferible,		Tarjeta_Lote,		Id_Chequera,
						Renglon_Nro_Caja,	Flag_Conciliado,	Tarjeta_Cant_Cuotas,
						Tarjeta_Imp_Cuota,	Tarjeta_Crit_Cuota, Importe,
						Tarjeta_Cod_Autoriz,Fecha_Acreditacion) 
			VALUES		(@Id_Valor/*Id_Valor*/,	0/*Id_Valor_Origen*/,		@trans_nueva/*Id_Trans*/,
						2/*Id_Estado_Valor*/,	@Id_Tipo_Val /*Id_Tipo_Val*/,		0/*Valor_Nro*/,
						@Descrip_Val /*Descripcion*/,0/*Id_Cliente*/,			0/*Id_Proveedor*/,--aca y id_Valor
						0/*Id_Banco*/,	@Id_Cta_Banco,			0/*Id_Mov_Caja*/,
						'PES' /*Id_Moneda*/,		''/*Id_Tarjeta*/,			0/*Tarjeta_Nro*/,
						1/*Cotizacion*/,		@Id_Periodo_Caja/*Id_Periodo_Caja*/,0/*Propio*/,
						0/*Transferible*/,		0/*Tarjeta_Lote*/,			0/*Id_Chequera*/,
						1/*Renglon_Nro_Caja*/,	0/*Flag_Conciliado*/,		0/*Tarjeta_Cant_Cuotas*/,
						00/*Tarjeta_Imp_Cuota*/,0/*Tarjeta_Crit_Cuota*/,	@Importe,
						'',@Fecha)
	

	/*FIN Insert: VALORES*/

	/*---------------------------------------------------------------------------------*/

	/*Insert: VALORES_MOV*/	
	PRINT 'Inserto en Valores_Mov'
	INSERT INTO Valores_Mov	(Id_Valor,			Renglon_Nro,		Id_Trans,
						Id_Motivo_Estado,		Id_Estado_Valor,	Id_Periodo_Caja,
						Descripcion,			Fecha_Acreditacion,	Fecha,
						Renglon_Nro_Caja) 
			VALUES		(@Id_Valor/*Id_Valor*/,	1/*Renglon_Nro*/,	@trans_nueva/*Id_Trans*/,
						0/*Id_Motivo_Estado*/,	3/*Id_Estado_Valor*/,@Id_Periodo_Caja/*Id_Periodo_Caja*/,
						''/*Descripcion*/,		NULL/*Fecha_Acreditacion*/,@Fecha/*Fecha*/,
						1/*Renglon_Nro_Caja*/)

	---------------------------------------
  -- insert BANCOS_CTAS_MOV

	/*---------------------------------------------------------------------------------*/
