CREATE PROCEDURE [dbo].[CP_Cbtes_Pago_Online] 
	@Lote			VARCHAR(20),
	@Item			INT,
	@Id_Tipo_Val	CHAR(3),
	@Id_Tarjeta		VARCHAR(10),
	@TransPago		VARCHAR(15),
	@Nota			VARCHAR(8000),
	@ImportePago	DECIMAL(12,2),
	@id_cliente		INT = NULL,
	@FECHA			DATETIME = NULL,
	@Importe		DECIMAL(12,2) = NULL

AS 
--SET NOCOUNT ON 

DECLARE @Mensaje			VARCHAR(100)
DECLARE @desc			VARCHAR(50)
DECLARE @Id_Tipo_Cbte	CHAR(4)
DECLARE @Nombre			VARCHAR(100)
DECLARE @NRO_CBTE		INT
DECLARE @Nro_Cbte_ND	INT
DECLARE @trans_rec		INT
DECLARE @trans_ND		INT
DECLARE @Observacion	VARCHAR(100)
DECLARE @Descrip_Cbte_CtaCte VARCHAR(50)
DECLARE @Id_Periodo_Caja INT
DECLARE @Id_Valor		INT
DECLARE @Id_Moneda		CHAR(3)
DECLARE @Descrip_Val	VARCHAR(100)

BEGIN TRY
	BEGIN TRAN

	SET @Id_Periodo_Caja	= CAST( dbo.CF_xParam('Periodo_Caja_VW') AS INT)
	SET @Id_Tipo_Cbte		= dbo.CF_xParam('Tipo_Cbte_VW_Recibo')
	SET @Id_Moneda			= dbo.CF_xParam('Moneda_Cbte_VW')
	SET @Descrip_Val		= dbo.CF_Valor_Descrip(0,@Id_Moneda,@Id_Tipo_Val,'',0,0,NULL,@Id_Tarjeta,'',0,'',NULL,0,0)



	SET @trans_rec = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = 'CW:' + @LOTE AND Id_Estado_Cbte = 0),0)

	IF @trans_rec = 0
	BEGIN
		PRINT 'Agregando Recibo'
		SET @trans_ND = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = 'VW:' + @LOTE AND Id_Estado_Cbte = 0),0)

		IF @trans_ND = 0 AND (@id_cliente IS NULL OR @FECHA IS NULL OR @Importe IS NULL)
		BEGIN
			SELECT	 1					AS ErrorNumber 
					,0					AS ErrorSeverity  
					,0					AS ErrorState 
					,0					AS ErrorProcedure  
					,0					AS ErrorLine		
					,'Sin cbte. factura debe especificar id_Cliente,fecha e importe total'			AS ErrorMessage
					,@trans_ND			AS Id_Trans_Fac
					,@trans_rec			AS Id_Trans_Rec
			ROLLBACK
			RETURN 1
		END


		SET @Nro_Cbte_ND =  (SELECT COMPROBANTE_NRO FROM Cbtes WHERE Id_Trans = @trans_ND)

		SET @desc = 'CW:' + @LOTE

		IF @id_cliente IS NULL
			SET @id_cliente = (SELECT id_cliente FROM Cbtes WHERE Id_Trans = @trans_ND)

		IF @FECHA IS NULL
			SET @FECHA = (SELECT Fecha FROM Cbtes WHERE Id_Trans = @trans_ND)

		IF @Importe IS NULL
			SET @Importe = (SELECT Imp_Total FROM Cbtes WHERE Id_Trans = @trans_ND)

		SET @Nombre = (SELECT rtrim(Razon_Social) FROM Clientes WHERE Id_Cliente = @Id_Cliente)

		SET @trans_rec = (SELECT max(id_trans) from transacciones ) + 1
		INSERT INTO TRANSACCIONES (id_trans,descripcion,fecha_mov) values (@trans_rec,@desc,GETDATE())

		SET @NRO_CBTE = (SELECT PROX_NRO from CBTES_TIPOS WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte) 
		UPDATE CBTES_TIPOS SET PROX_NRO = PROX_NRO+1 WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte

		INSERT INTO Cbtes	(Id_Cond_Vta,		Id_trans,		Id_Sucursal,
							Cbte_Grupo,			Fecha_Venc ,    id_cliente,
							id_estado_Cbte,		id_tipo_cbte,	comprobante_nro,
							fecha,				periodo_iva,	periodo,
							imp_total,			saldo,			imp_gravado,
							destinatario,		lote,			ID_MONEDA,
							Id_Cond_Pago,		Cotizacion)
					VALUES ('',					@trans_rec,		1,
							0,					@FECHA,			@id_cliente,
							0,					@Id_Tipo_cbte,	@NRO_CBTE,
							@FECHA,				@FECHA,			@FECHA, 
							@Importe,			0,				@Importe,
							@NOMBRE,			@desc,			@Id_Moneda ,
							10,					1)

		SET @Observacion =  dbo.CF_Descrip_Cbte(@trans_rec)
								
		PRINT 'Recibo: Se inserta Cbtes_Items'
		INSERT INTO Cbtes_Items (id_cliente,	descripcion_producto,	Cantidad,
								id_estado_Cbte,	Cantidad_Saldo,			Id_Trans,
								item,			Precio_Grav,			Imp_Gravado,
								Imp_Final,		Precio,					Lote,
								Fecha_QA,		Flag_QA,				Id_Producto,
								Imp_Exento,		Porc_Iva,				Bonif,
								Id_Usuario,     Observacion,            Precio_Exen,
								Id_Cond_Pago,   Bultos,                 Fecha_Venc,
								Costo,          Imp_Iva,			    calle, 
								columna,		fila, 					id_unidad_medida, 
								id_tarea,		id_pais,				cantidad_equiv, 
								costo_mo,		costo_gf,				flag_noimp_factura)							
						VALUES (@Id_Cliente,	'',						1,
								0				,0						,@Trans_rec,
								1,				0/*Precio_Grav*/,			@Importe,
								0/*Imp_Final*/,	0/*Precio*/,				'',
								NULL/*Fecha_QA*/, ''/*Flag_QA*/,			'', 
								0,				0,							0,
								0,				@Observacion,				0,
								0/*Id_Cond_Pago*/,0,						@Fecha, 
								0,                0,						'',
								'',				  '',						'',
								0,				  '',						0, 
								0,				  0,						0)
						
					

		SET @Descrip_Cbte_CtaCte = dbo.CF_Descrip_Cbte(@trans_rec)

		INSERT INTO CLIENTES_CTACTE  (Id_Trans,Nro_Cuota,Id_Empresa,Id_Cliente,Fecha,Fecha_Vence,Descripcion,Importe,Id_Estado_Cbte,Observacion,Id_Trans_Origen,Nro_Cuota_Origen,Id_Moneda,Saldo,Nro_FacCre)
				VALUES (@trans_rec,1,NULL,@id_cliente,@Fecha,@Fecha,@Descrip_Cbte_CtaCte,@Importe * -1 ,1,'',0,0,dbo.CF_xParam('Moneda_Cbte_VW'),@Importe * -1 ,0)

		/*Insert: CAJAS_MOV*/	
		PRINT 'Inserto en Cajas_Mov'
		INSERT INTO Cajas_Mov	(Id_Trans,			Renglon_Nro	,		Id_Estado_Mov_Caja, 
								Importe,			Descripcion,		Id_Periodo_Caja,
								Id_Tipo_Mov_Caja,	Fecha) 
						VALUES	(@trans_rec,		1,					0, 
								@Importe,			@Descrip_Cbte_CtaCte,@Id_Periodo_Caja,
								7,					@Fecha)
					

		/*FIN Insert: CAJAS_MOV*/

		/*---------------------------------------------------------------------------------*/

		/*Insert: CBTES_APLICA*/	
		PRINT 'Inserto en Cbtes Aplica'
		INSERT INTO Cbtes_Aplica	(Id_Trans,	Item	,	Id_Trans_D, 
									Item_D,		Cantidad,	Importe) 
							VALUES	(@trans_ND,	1,			@trans_rec, 
									1,				0,		@Importe)
						

		/*FIN Insert: CBTES_APLICA*/
	

	END 
	/*Insert: VALORES*/	
	SET @Id_Valor			= (SELECT MAX(id_valor) FROM valores ) + 1
	PRINT 'Inserto en Valores'
	/*CAMBIAR*/
	INSERT INTO Valores	(Id_Valor,			Id_Valor_Origen,	Id_Trans,
						Id_Estado_Valor,	Id_Tipo_Val,		Valor_Nro,
						Descripcion,		Id_Cliente,			Id_Proveedor,
						Id_Banco,			Id_Cta_Banco,		Id_Mov_Caja,
						Id_Moneda,			Id_Tarjeta,			Tarjeta_Nro,
						Cotizacion,			Id_Periodo_Caja,	Propio,
						Transferible,		Tarjeta_Lote,		Id_Chequera,
						Renglon_Nro_Caja,	Flag_Conciliado,	Tarjeta_Cant_Cuotas,
						Tarjeta_Imp_Cuota,	Tarjeta_Crit_Cuota, Importe,
						Tarjeta_Cod_Autoriz) 
			VALUES		(@Id_Valor/*Id_Valor*/,	0/*Id_Valor_Origen*/,		@trans_rec/*Id_Trans*/,
						3/*Id_Estado_Valor*/,	@Id_Tipo_Val /*Id_Tipo_Val*/,		0/*Valor_Nro*/,
						@Descrip_Val /*Descripcion*/,0/*Id_Cliente*/,			0/*Id_Proveedor*/,--aca y id_Valor
						0/*Id_Banco*/,			0/*Id_Cta_Banco*/,			0/*Id_Mov_Caja*/,
						@Id_Moneda /*Id_Moneda*/,@Id_Tarjeta  /*Id_Tarjeta*/,			0/*Tarjeta_Nro*/,
						1/*Cotizacion*/,		@Id_Periodo_Caja/*Id_Periodo_Caja*/,0/*Propio*/,
						0/*Transferible*/,		0/*Tarjeta_Lote*/,			0/*Id_Chequera*/,
						1/*Renglon_Nro_Caja*/,	0/*Flag_Conciliado*/,		0/*Tarjeta_Cant_Cuotas*/,
						00/*Tarjeta_Imp_Cuota*/,0/*Tarjeta_Crit_Cuota*/,	@ImportePago,
						@TransPago)
	
	/*falta funcion que devuelva la descripcion del tipo de valor*/					

	/*FIN Insert: VALORES*/

	/*---------------------------------------------------------------------------------*/

	/*Insert: VALORES_MOV*/	
	PRINT 'Inserto en Valores_Mov'
	INSERT INTO Valores_Mov	(Id_Valor,			Renglon_Nro,		Id_Trans,
						Id_Motivo_Estado,		Id_Estado_Valor,	Id_Periodo_Caja,
						Descripcion,			Fecha_Acreditacion,	Fecha,
						Renglon_Nro_Caja) 
			VALUES		(@Id_Valor/*Id_Valor*/,	1/*Renglon_Nro*/,	@trans_rec/*Id_Trans*/,
						0/*Id_Motivo_Estado*/,	3/*Id_Estado_Valor*/,@Id_Periodo_Caja/*Id_Periodo_Caja*/,
						''/*Descripcion*/,		NULL/*Fecha_Acreditacion*/,@Fecha/*Fecha*/,
						1/*Renglon_Nro_Caja*/)
					

	/*FIN Insert: VALORES_MOV*/
	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage
			,@trans_ND			AS Id_Trans_Fac
			,@trans_rec			AS Id_Trans_Rec

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO




CREATE PROCEDURE [dbo].[CP_Cbtes_Ped_Fin]
@pId_Trans				INT
AS

/*Declaracion Variables Locales*/
DECLARE @Id_Cta_Contable		INT
DECLARE @Fecha					DATETIME
DECLARE @Observacion			VARCHAR(100)
DECLARE @Item					SMALLINT

DECLARE @Descripcion_Cbte		VARCHAR(80)
DECLARE @Imp_Gravado_Sum_It		DECIMAL(12,2)
DECLARE @Porc_Bonificacion_Cb	DECIMAL(5,2)
DECLARE @Imp_Gravado			DECIMAL(12, 2)
DECLARE @Imp_Iva_Sum_It			DECIMAL(12, 2)
DECLARE @Imp_Iva				DECIMAL(12, 2)
DECLARE @Imp_Total				DECIMAL(12, 2)
DECLARE @Saldo					DECIMAL(12, 2)
DECLARE @Imp_Bonificacion		DECIMAL(12, 2)
DECLARE @Cantidad				DECIMAL(12, 4)

DECLARE @Mensaje			VARCHAR(100)
/*Fin de Declaraciones Variables Locales */

PRINT 'Procedimiento: CP_Cbtes_Ped_Fin'



DECLARE @Trans TABLE (ErrorNumber	INT 
					,ErrorSeverity  INT 
					,ErrorState		INT
					,ErrorProcedure	VARCHAR(100)
					,ErrorLine		INT
					,ErrorMessage	VARCHAR(1000)
					,Id_Trans		INT)

DECLARE @Trans2 TABLE (ErrorNumber	INT 
					,ErrorSeverity  INT 
					,ErrorState		INT
					,ErrorProcedure	VARCHAR(100)
					,ErrorLine		INT
					,ErrorMessage	VARCHAR(1000)
					,Id_Trans		INT
					,Id_Tipo_Cbte	CHAR(4)
					,Id_Estado_Cbte SMALLINT
					,Comprobante_Nro INT				
					)


INSERT INTO @Trans2
	EXEC dbo.CP_Cbtes_Grabar_Numero @pId_Trans

IF (SELECT TOP 1 ErrorNumber FROM @Trans) <> 0
BEGIN
	SELECT * FROM @Trans2
	RETURN
END

BEGIN TRY
	BEGIN TRAN
		
	SET @Descripcion_Cbte = (dbo.CF_Cbte_Descrip(@pId_Trans))
	
	UPDATE Transacciones SET Descripcion = SUBSTRING((Descripcion + ' ' + @Descripcion_Cbte), 1, 50) WHERE Id_Trans = @pId_Trans
	UPDATE Cbtes_Items SET Id_Estado_Cbte = 1/*PENDIENTE*/ WHERE Id_Trans = @pId_Trans

	SET @Porc_Bonificacion_Cb	= ISNULL((SELECT ISNULL(Porc_Bonificacion, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans), 0)
	SET @Imp_Gravado_Sum_It		= ISNULL((SELECT SUM((ISNULL(Imp_Gravado, 0) * ISNULL(Cantidad_Saldo, 0))) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)

	IF(@Porc_Bonificacion_Cb = 0)
	BEGIN
		SET @Imp_Gravado = @Imp_Gravado_Sum_It
	END
	ELSE
	BEGIN
		SET @Imp_Gravado = (@Imp_Gravado_Sum_It * ((100 - @Porc_Bonificacion_Cb) / 100))
	END

	SET @Imp_Iva_Sum_It			= ISNULL((SELECT SUM(ISNULL(Imp_Iva, 0)) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)
	SET @Imp_Iva				= @Imp_Iva_Sum_It

	SET @Imp_Total			= @Imp_Gravado + @Imp_Iva
	SET @Saldo				= @Imp_Total

	SET @Imp_Bonificacion	= (@Imp_Gravado_Sum_It - @Imp_Gravado)		

	SET @Cantidad			= ISNULL((SELECT COUNT(*) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)
	
	UPDATE Cbtes 
	SET 
	Id_Estado_Cbte		= 5/*PENDIENTE DE APROBACION*/, 
	Cantidad			= @Cantidad,
	Imp_Gravado			= @Imp_Gravado, 
	Saldo				= @Saldo, 
	Imp_Iva				= @Imp_Iva,
	Imp_Bonificacion	= @Imp_Bonificacion,
	Imp_Total			= @Imp_Total
	WHERE 
	Id_Trans = @pId_Trans	
	
	COMMIT

	SET @Mensaje = @Descripcion_Cbte

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage
			,@pId_Trans		AS Id_Trans

END TRY  


BEGIN CATCH  
    SELECT  
		ERROR_NUMBER() AS ErrorNumber  
		,ERROR_SEVERITY() AS ErrorSeverity  
		,ERROR_STATE() AS ErrorState  
		,ERROR_PROCEDURE() AS ErrorProcedure  
		,ERROR_LINE() AS ErrorLine  
		,ERROR_MESSAGE() AS ErrorMessage
		,@pId_Trans		AS Id_Trans
	    
	ROLLBACK
END CATCH

PRINT 'FIN Procedimiento: CP_Cbtes_Ped_Fin'
GO


CREATE PROCEDURE [dbo].[CP_Cbtes_Ped_Generar]
@pId_Usuario		INT,			/*Seg_User*/
@pId_Tipo_Cbte		CHAR(4),		/*Cbtes_Tipos*/
@pFecha				DATETIME,
@pId_Cliente		INT,			/*Clientes*/
@pFecha_Venc		DATETIME,	
@pFecha_Estimada	DATETIME,
@pId_Vendedor		VARCHAR(10),	/*Vendedores*/
@pCbte_Nro_Externo	VARCHAR(25),
@pId_Cond_Pago		SMALLINT,		/*Cbtes_Cond_Pago*/
@pId_Cond_Vta		CHAR(10),		/*Cbtes_Cond_Vtas*/
@pId_Moneda			CHAR(3),		/*Valores_Monedas*/
@pCotizacion		DECIMAL(9,4),
@pPorc_Bonificacion	DECIMAL(5,2),
@pId_Camp			SMALLINT,		/*CRM_Campanias*/
@pId_Centro_Costo	CHAR(10),		/*Centro_Costos*/
@pId_Lista			SMALLINT,		/*Prod_Listas_Precios*/
@pEmail				VARCHAR(8000),
@pId_Puerto			CHAR(3),		/*Tab_Puertos*/
@pNota_Part1		VARCHAR(100),
@pNota_Part2		VARCHAR(100),
@pObservacion		VARCHAR(8000),
@pNro_Perm_Embarque	VARCHAR(20),
@pPersona_Recibe	VARCHAR(100),
@pLote				VARCHAR(20)
AS

DECLARE @Trans TABLE (ErrorNumber	INT 
					,ErrorSeverity  INT 
					,ErrorState		INT
					,ErrorProcedure	VARCHAR(100)
					,ErrorLine		INT
					,ErrorMessage	VARCHAR(1000)
					,Id_Trans		INT)

INSERT INTO @Trans
	EXEC CP_Transacciones_Generar @pId_Usuario

IF (SELECT TOP 1 ErrorNumber FROM @Trans) <> 0
BEGIN
	SELECT * FROM @Trans
	RETURN
END

/*Declaracion Variables Locales*/
DECLARE @Id_Trans			INT
DECLARE @Id_Empresa			SMALLINT
DECLARE @Id_Sucursal		SMALLINT
DECLARE @Cbte_Grupo			INT
DECLARE @Comprobante_Nro	INT
DECLARE @Id_Taller			VARCHAR(10)
DECLARE @Id_Proceso			VARCHAR(10)
DECLARE @Id_Proveedor		INT
DECLARE @Signo				SMALLINT
DECLARE @Id_Estado_Cbte		SMALLINT
DECLARE @Id_Dep_Fisico		CHAR(3)
DECLARE @Id_Dep_Logico		CHAR(3)
DECLARE @Porc_DescEspecial	DECIMAL(5, 2)
DECLARE @Porc_DescFin		DECIMAL(5, 2)
DECLARE @Porc_Iva			DECIMAL(5, 2)
DECLARE @Porc_Iva2			DECIMAL(5, 2)
DECLARE @Imp_Neto			DECIMAL(12, 2)
DECLARE @Imp_DescEspecial	DECIMAL(12, 2)
DECLARE @Imp_DescFin		DECIMAL(12, 2)
DECLARE @Imp_Bonificacion	DECIMAL(12, 2)
DECLARE @Imp_Gravado		DECIMAL(12, 2)
DECLARE @Imp_Exento			DECIMAL(12, 2)
DECLARE @Imp_IVA			DECIMAL(12, 2)
DECLARE @Imp_IVA2			DECIMAL(12, 2)
DECLARE @Imp_Percepcion_IB	DECIMAL(12, 2)
DECLARE @Imp_Percepcion_Iva DECIMAL(12, 2)
DECLARE @Imp_Total			DECIMAL(12, 2)
DECLARE @Bultos				SMALLINT
