@pFecha				DATETIME,
@pId_Cliente		INT,			/*Clientes*/
@pFecha_Estimada	DATETIME,
@pId_Vendedor		VARCHAR(10),	/*Vendedores*/
@pId_Cond_Pago		SMALLINT,		/*Cbtes_Cond_Pago*/
@pId_Cond_Vta		CHAR(10),		/*Cbtes_Cond_Vtas*/
@pId_Centro_Costo	CHAR(10),		/*Centro_Costos*/
@pId_Lista			SMALLINT,		/*Prod_Listas_Precios*/
@pEmail				VARCHAR(8000),
@pId_Puerto			CHAR(3),		/*Tab_Puertos*/
@pNota_Part1		VARCHAR(100),
@pNota_Part2		VARCHAR(100),
@pObservacion		VARCHAR(8000),
@pNro_Perm_Embarque	VARCHAR(20),
@pPersona_Recibe	VARCHAR(100),
@pLote				VARCHAR(20),
@pPedido_Nro		VARCHAR(25),
@pId_Transportista	INT,
