					,ErrorSeverity  INT 
					,ErrorState		INT
					,ErrorProcedure	VARCHAR(100)
					,ErrorLine		INT
					,ErrorMessage	VARCHAR(1000)
					,Id_Trans		INT)

INSERT INTO @Trans
	EXEC CP_Transacciones_Generar @pId_Usuario

IF (SELECT TOP 1 ErrorNumber FROM @Trans) <> 0
BEGIN
	SELECT * FROM @Trans
	RETURN
END

/*Declaracion Variables Locales*/
DECLARE @Id_Trans			INT
DECLARE @Id_Empresa			SMALLINT
DECLARE @Id_Sucursal		SMALLINT
DECLARE @Cbte_Grupo			INT
DECLARE @Comprobante_Nro	INT
DECLARE @Id_Taller			VARCHAR(10)
DECLARE @Id_Proceso			VARCHAR(10)
DECLARE @Id_Proveedor		INT
DECLARE @Signo				SMALLINT
DECLARE @Id_Estado_Cbte		SMALLINT
DECLARE @Id_Dep_Fisico		CHAR(3)
DECLARE @Id_Dep_Logico		CHAR(3)
DECLARE @Porc_DescEspecial	DECIMAL(5, 2)
DECLARE @Porc_DescFin		DECIMAL(5, 2)
DECLARE @Porc_Iva			DECIMAL(5, 2)
DECLARE @Porc_Iva2			DECIMAL(5, 2)
DECLARE @Imp_Neto			DECIMAL(12, 2)
DECLARE @Imp_DescEspecial	DECIMAL(12, 2)
DECLARE @Imp_DescFin		DECIMAL(12, 2)
DECLARE @Imp_Bonificacion	DECIMAL(12, 2)
DECLARE @Imp_Gravado		DECIMAL(12, 2)
DECLARE @Imp_Exento			DECIMAL(12, 2)
DECLARE @Imp_IVA			DECIMAL(12, 2)
DECLARE @Imp_IVA2			DECIMAL(12, 2)
DECLARE @Imp_Percepcion_IB	DECIMAL(12, 2)
DECLARE @Imp_Percepcion_Iva DECIMAL(12, 2)
DECLARE @Imp_Total			DECIMAL(12, 2)
DECLARE @Bultos				SMALLINT
DECLARE @NroImpresion		INT
DECLARE @Exportado			TINYINT
DECLARE @Id_Pais			CHAR(3)
DECLARE @Id_Provincia		CHAR(3)
DECLARE @Id_Localidad		INT
DECLARE @Porc_Iva3			DECIMAL(5, 2)
DECLARE @Imp_Gravado2		DECIMAL(12, 2)
DECLARE @Imp_Gravado3		DECIMAL(12, 2)
DECLARE @Imp_NoGravado		DECIMAL(12, 2)
DECLARE @Imp_IVA3			DECIMAL(12, 2)
DECLARE @Imp_Percep			DECIMAL(12, 2)
DECLARE @Saldo				DECIMAL(12, 2)
DECLARE @Periodo_Iva		DATETIME
DECLARE @Periodo			DATETIME
DECLARE @Id_Cond_Pago_Item	TINYINT
DECLARE @Id_Tipo_Reten		VARCHAR(10)
DECLARE @Cant_Cuotas		SMALLINT
DECLARE @Id_Producto		VARCHAR(14)
DECLARE @Id_Formula			VARCHAR(15)
DECLARE @Cantidad			DECIMAL(12, 4)
DECLARE @Destinatario		VARCHAR(100)
DECLARE @Cuit				VARCHAR(19)
DECLARE @Id_Iva				CHAR(3)
DECLARE @Cant_Batch			SMALLINT
DECLARE @Fecha_Perm_Embar	DATETIME
DECLARE @Saldo_Iva_Recup	DECIMAL(12, 2)
DECLARE @Suc_Destina		SMALLINT
DECLARE @Id_Asiento			INT
DECLARE @Id_Valor			INT
DECLARE @Cai				DECIMAL(14, 0)
DECLARE @Cai_Vence			DATETIME
DECLARE @Des_Anio			TINYINT
DECLARE @Des_Aduana			CHAR(3)
DECLARE @Des_Destina		CHAR(4)
DECLARE @Des_Nro			INT
DECLARE @Des_Verif			CHAR(1)
DECLARE @Id_Contrato		INT
DECLARE @Id_Cobrador		VARCHAR(10)
DECLARE @Nro_Auto_Trib		VARCHAR(14)
DECLARE @Remito_Nro			VARCHAR(25)
DECLARE @Id_Tarjeta			VARCHAR(11)
DECLARE @Tarjeta_Nro		VARCHAR(25)
DECLARE @Cantidad_Saldo		DECIMAL(12, 4)
DECLARE @Saldo_Anterior		DECIMAL(12, 2)
DECLARE @NRO_DJAI			VARCHAR(30)
DECLARE @Cantidad_Equiv		DECIMAL(12, 4)
DECLARE @Id_Trans_Origen	INT
DECLARE @Id_Sede_Origen		SMALLINT
DECLARE @Email				VARCHAR(8000)
DECLARE @Patente_Transporte VARCHAR(7)
DECLARE @Patente_Transporte_Acoplado VARCHAR(7)
DECLARE @Id_Moneda			CHAR(3)
DECLARE @Id_Camp			SMALLINT
DECLARE @Cotizacion			DECIMAL(9,4)
DECLARE @Porc_Bonificacion	DECIMAL(5,2)
DECLARE @Fecha_Venc			DATETIME
DECLARE @Cbte_Nro_Externo	VARCHAR(25)
DECLARE @Flag_Existe_Cliente		TINYINT
DECLARE @Flag_Existe_Cbte_Tipo		TINYINT
DECLARE @Flag_Existe_Moneda			TINYINT
DECLARE @Flag_Existe_Vendedor		TINYINT
DECLARE @Flag_Existe_Cbte_Cond_Pago	TINYINT
DECLARE @Flag_Existe_Cbte_Cond_Vta  TINYINT
DECLARE @Flag_Existe_CRM_Campania	TINYINT
DECLARE @Flag_Existe_Centro_Costo	TINYINT
DECLARE @Flag_Existe_Prod_Lista_Precio TINYINT
DECLARE @Flag_Existe_Tab_Puerto		TINYINT
DECLARE @Flag_Existe_Id_Transportista TINYINT

DECLARE @Plazo_Venc			SMALLINT

DECLARE @Descripcion		VARCHAR(80)

DECLARE @Mensaje			VARCHAR(100)
/*Fin de Declaraciones Variables Locales */

PRINT 'Procedimiento: CP_Cbtes_Rem_Generar'

SET @Id_Trans = (SELECT Id_Trans FROM @Trans)

BEGIN TRY
	BEGIN TRAN

	SET @Flag_Existe_Cliente = ISNULL((SELECT 1 FROM Clientes WHERE Id_Cliente = @pId_Cliente), 0)
	IF (@Flag_Existe_Cliente = 0)
	BEGIN
		SET @Mensaje = 'No existe el Cliente '

		SELECT	2001			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SET @Flag_Existe_Cliente = ISNULL((SELECT 1 FROM Clientes WHERE Id_Cliente = @pId_Cliente AND ISNULL(Activo, 0) = 1), 0)
	IF (@Flag_Existe_Cliente = 0)
	BEGIN
		SET @Mensaje = 'El Cliente esta Inactivo'

		SELECT	2002			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SET @Flag_Existe_Cbte_Tipo = ISNULL((SELECT 1 FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @pId_Tipo_Cbte AND ISNULL(Activo, 0) = 1), 0)
	IF (@Flag_Existe_Cbte_Tipo = 0)
	BEGIN
		SET @Mensaje = 'No existe el Tipo de Cbte o esta inactivo'

		SELECT	2003			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SET @Id_Moneda = (SELECT ISNULL(Id_Moneda, 'PES') FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @pId_Tipo_Cbte)

	SET @Flag_Existe_Moneda = ISNULL((SELECT 1 FROM Valores_Monedas WHERE Id_Moneda = @Id_Moneda), 0)
	IF (@Flag_Existe_Moneda = 0)
	BEGIN
		SET @Mensaje = 'No existe el Tipo de Moneda'

		SELECT	2004			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SET @Flag_Existe_Vendedor = ISNULL((SELECT 1 FROM Vendedores WHERE Id_Vendedor = @pId_Vendedor), 0)
	IF (@Flag_Existe_Vendedor = 0)
	BEGIN
		SET @Mensaje = 'No existe el Vendedor'

		SELECT	2005			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SET @Flag_Existe_Cbte_Cond_Pago = ISNULL((SELECT 1 FROM Cbtes_Cond_Pago WHERE Id_Cond_Pago = @pId_Cond_Pago), 0)
	IF (@Flag_Existe_Cbte_Cond_Pago = 0)
	BEGIN
		SET @Mensaje = 'No existe la Condicion de Pago'

		SELECT	2006			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SET @Flag_Existe_Cbte_Cond_Vta = ISNULL((SELECT 1 FROM Cbtes_Cond_Vtas WHERE Id_Cond_Vta = @pId_Cond_Vta), 0)
	IF (@Flag_Existe_Cbte_Cond_Vta = 0)
	BEGIN
		SET @Mensaje = 'No existe la Condicion de Venta'

		SELECT	2007			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/
	SET @Id_Camp = 0
	
	SET @Flag_Existe_CRM_Campania = ISNULL((SELECT 1 FROM CRM_Campanias WHERE Id_Camp = @Id_Camp), 0)
	IF (@Flag_Existe_CRM_Campania = 0)
	BEGIN
		SET @Mensaje = 'No existe la CRM Campaña'

		SELECT	2008			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SET @Flag_Existe_Centro_Costo = ISNULL((SELECT 1 FROM Centro_Costos WHERE Id_Centro_Costo = @pId_Centro_Costo), 0)
	IF (@Flag_Existe_Centro_Costo = 0)
	BEGIN
		SET @Mensaje = 'No existe el Centro de Costo'

		SELECT	2009			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SET @Flag_Existe_Prod_Lista_Precio = ISNULL((SELECT 1 FROM Prod_Listas_Precios WHERE Id_Lista_Precio = @pId_Lista), 0)
	IF (@Flag_Existe_Prod_Lista_Precio = 0)
	BEGIN
		SET @Mensaje = 'No existe la Lista de Precios'

		SELECT	2010			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SET @Flag_Existe_Tab_Puerto = ISNULL((SELECT 1 FROM Tab_Puertos WHERE Id_Puerto = @pId_Puerto), 0)
	IF (@Flag_Existe_Tab_Puerto = 0)
	BEGIN
		SET @Mensaje = 'No existe el Puerto'

		SELECT	2011			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/
	
	SET @Flag_Existe_Id_Transportista = ISNULL((SELECT MAX(1) FROM Proveedores WHERE (Id_Proveedor = @pId_Transportista AND Id_Tipo_Pro = (dbo.CF_xParam('Transporte_Id'))) OR @pId_Transportista = 0), 0)
	IF(@Flag_Existe_Id_Transportista = 0)
		BEGIN
		SET @Mensaje = 'No existe el Transportist'

		SELECT	2012			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Id_Trans		AS Id_Trans
		ROLLBACK
		RETURN
	END
	/*************************************************************************************************/
							
	SET @pFecha				= (SELECT CONVERT(DATE, @pFecha))

	SELECT  @Id_Sucursal	= ISNULL(Id_Sucursal, 0),
			@Cbte_Grupo		= ISNULL(Cbte_Grupo, 0),
			@Id_Estado_Cbte	= ISNULL(Id_Estado_Cbte, 0)
	FROM Cbtes_Tipos 
	WHERE 
	Id_Tipo_Cbte = @pId_Tipo_Cbte

	SELECT 	@Destinatario	= ISNULL(Razon_Social, Apellido + ', ' + Nombre),
			@Id_Pais		= ISNULL(Id_Pais_Cob, ''),
			@Id_Provincia	= ISNULL(Id_Provincia_Cob, ''),
			@Id_Localidad	= ISNULL(Id_Localidad_Cob, 0),
			@Cuit			= ISNULL(Cuit, ''),
			@Id_Iva			= ISNULL(Id_Iva, ''),
			@Id_Dep_Fisico	= ISNULL(Id_Dep_Fisico, ''),
			@Id_Dep_Logico	= ISNULL(Id_Dep_Logico, '')
	FROM Clientes
	WHERE
	Id_Cliente = @pId_Cliente

	IF(ISNULL(@pEmail, '') = '')
	BEGIN
		SET @Email				= (SELECT ISNULL(Email, '') FROM Clientes WHERE Id_Cliente = @pId_Cliente)
	END
	ELSE
	BEGIN
		SET @Email				= @pEmail
	END

	SET @Comprobante_Nro	= 0		
	SET @Plazo_Venc			= (SELECT ISNULL(Plazo_Venc, 0) FROM Cbtes_Cond_Pago WHERE Id_Cond_Pago = @pId_Cond_Pago)	
	SET @Periodo_Iva		= @pFecha
	SET @Periodo			= @pFecha
	SET @Imp_Total			= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Saldo				= 0 /*Hay que actualizarlo luego de grabar los items*/
	SET @Imp_Gravado		= 0 /*Hay que actualizarlo luego de grabar los items*/

	/*TO-DO: De aca para abajo por ahora por Default*/
	SET @Id_Taller			= ''
	SET @Id_Proceso			= ''
	SET @Id_Proveedor		= 0
	SET @Signo				= 0
	SET	@Porc_DescFin		= 0
	SET @Porc_DescEspecial	= 0
	SET @Porc_Iva			= dbo.CF_xParam('Tasa_Iva_1')
	SET @Porc_Iva2			= dbo.CF_xParam('Tasa_Iva_2')
	SET @Imp_Neto			= 0
	SET @Imp_DescEspecial	= 0
	SET @Imp_DescFin		= 0
	SET @Imp_Bonificacion	= 0
	SET @Imp_Exento			= 0
	SET @Imp_Iva			= 0
	SET @Imp_Iva2			= 0
	SET @Imp_Percepcion_IB	= 0
	SET @Imp_Percepcion_Iva = 0
	SET @Bultos				= 0
	SET @NroImpresion		= 0
	SET @Exportado			= 0
	SET @Porc_Iva3			= dbo.CF_xParam('Tasa_Iva_3')
	SET @Imp_Gravado2		= 0
	SET @Imp_Gravado3		= 0
	SET @Imp_NoGravado		= 0
	SET @Imp_IVA3			= 0
	SET @Imp_Percep			= 0
	--SET @Id_Cond_Pago_Item	NULL
	SET @Id_Tipo_Reten		= ''
	SET @Cant_Cuotas		= 0
	--SET @Id_Producto		NULL
	--SET @Id_Formula		NULL
	SET @Cantidad = 0
	SET @Cant_Batch = 0
	--SET @Fecha_Perm_Embar
	SET @Saldo_Iva_Recup = 0
	SET @Suc_Destina = 0
	SET @Id_Asiento = 0
	SET @Id_Valor = 0
	SET @Cai = 0
	--SET @Cai_Vence NULL
	SET @Des_Anio = 0
	SET @Des_Aduana = ''
	SET @Des_Destina = ''
	SET @Des_Nro = 0
	SET @Des_Verif = ''
	SET @Id_Contrato = 0
	SET @Id_Cobrador = ''
	SET @Nro_Auto_Trib = ''
	SET @Remito_Nro = ''
	SET @Id_Tarjeta = ''
	SET @Tarjeta_Nro = ''
	SET @Cantidad_Saldo = 0
	SET @Saldo_Anterior	= 0
	SET @NRO_DJAI = ''
	SET @Cantidad_Equiv = 0
	SET @Id_Trans_Origen = 0
	SET @Id_Sede_Origen = 0
	SET @Cotizacion = 1
	SET @Porc_Bonificacion = 0
	SET @Fecha_Venc = DATEADD(dd, 1, @pFecha)
	SET @Cbte_Nro_Externo = '0'
	--SET @Patente_Transporte NULL
	--SET @Patente_Transporte_Acoplado NULL	


	INSERT INTO dbo.Cbtes
	(Id_Trans,			Id_Empresa,			Id_Sucursal,
	Id_Tipo_Cbte,		Cbte_Grupo,			Comprobante_Nro,
	Id_Cliente,			Id_Taller,			Id_Proceso,
	Id_Proveedor,		Signo,				Id_Estado_Cbte,
	Fecha,				Id_Dep_Fisico,		Id_Dep_Logico,
	Porc_DescEspecial,	Porc_DescFin,		Porc_Bonificacion,
	Porc_Iva,			Porc_Iva2,			Imp_Neto,
	Imp_DescEspecial,	Imp_DescFin,		Imp_Bonificacion,
	Imp_Gravado,		Imp_Exento,			Imp_IVA,
	Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
	Imp_Total,			Bultos,				NroImpresion,
	Exportado,			Id_Usuario,			Fecha_Estimada,
	Dir_Entrega,		Id_Pais,			Id_Provincia,
	Id_Localidad,		Persona_Recibe,		Porc_Iva3,
	Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
	Imp_IVA3,			Imp_Percep,			Saldo,
	Periodo_Iva,		Periodo,			Fecha_Venc,
	Observacion,		Id_Cond_Pago_Item,	Id_Cond_Pago,
	Id_Tipo_Reten,		Cant_Cuotas,		Id_Producto,
	Id_Formula,			Cantidad,			Id_Vendedor,
	Id_Transportista,	Id_Lista,			Id_Moneda,
	Cotizacion,			Destinatario,		Cuit,
	Id_Iva,				Cant_Batch,			Nro_Perm_Embarque,
	Fecha_Perm_Embar,	Saldo_Iva_Recup,	Lote,
	Suc_Destina,		Id_Puerto,			Id_Cond_Vta,
	Cbte_Nro_Externo,	Nota_Part1,			Nota_Part2,
	Id_Asiento,			Id_Centro_Costo,	Id_Valor,
	Cai,				Cai_Vence,			Des_Anio,
	Des_Aduana,			Des_Destina,		Des_Nro,
	Des_Verif,			Id_Contrato,		Id_Cobrador,
	Nro_Auto_Trib,		Id_Camp,			Remito_Nro,
	Pedido_Nro,			Id_Tarjeta,			Tarjeta_Nro,
	Cantidad_Saldo,		Saldo_Anterior,		NRO_DJAI,
	Cantidad_Equiv,		Id_Trans_Origen,	Id_Sede_Origen,
	Email,				Patente_Transporte,	Patente_Transporte_Acoplado)
	VALUES
	(@Id_Trans,			@Id_Empresa,		@Id_Sucursal,
	SUBSTRING(@pId_Tipo_Cbte,1,4),	@Cbte_Grupo,		@Comprobante_Nro,
	@pId_Cliente,		@Id_Taller,			@Id_Proceso,
	@Id_Proveedor,		@Signo,				@Id_Estado_Cbte,
	@pFecha,			@Id_Dep_Fisico,		@Id_Dep_Logico,
	@Porc_DescEspecial,	@Porc_DescFin,		@Porc_Bonificacion,
	@Porc_Iva,			@Porc_Iva2,			@Imp_Neto,
	@Imp_DescEspecial,	@Imp_DescFin,		@Imp_Bonificacion,
	@Imp_Gravado,		@Imp_Exento,		@Imp_IVA,
	@Imp_IVA2,			@Imp_Percepcion_IB,	@Imp_Percepcion_Iva,
	@Imp_Total,			@Bultos,			@NroImpresion,
	@Exportado,			@pId_Usuario,		@pFecha_Estimada,
	@pDir_Entrega,		@Id_Pais,			@Id_Provincia,
	@Id_Localidad,		@pPersona_Recibe,	@Porc_Iva3,
	@Imp_Gravado2,		@Imp_Gravado3,		@Imp_NoGravado,
	@Imp_IVA3,			@Imp_Percep,		@Saldo,
	@Periodo_Iva,		@Periodo,			@Fecha_Venc,
	@pObservacion,		@Id_Cond_Pago_Item,	@pId_Cond_Pago,
	@Id_Tipo_Reten,		@Cant_Cuotas,		@Id_Producto,
	@Id_Formula,		@Cantidad,			@pId_Vendedor,
	@pId_Transportista,	@pId_Lista,			@Id_Moneda,
	@Cotizacion,		@Destinatario,		@Cuit,
	@Id_Iva,			@Cant_Batch,		@pNro_Perm_Embarque,
	@Fecha_Perm_Embar,	@Saldo_Iva_Recup,	@pLote,
	@Suc_Destina,		@pId_Puerto,		@pId_Cond_Vta,
	@Cbte_Nro_Externo,	@pNota_Part1,		@pNota_Part2,
	@Id_Asiento,		@pId_Centro_Costo,	@Id_Valor,
	@Cai,				@Cai_Vence,			@Des_Anio,
	@Des_Aduana,		@Des_Destina,		@Des_Nro,
	@Des_Verif,			@Id_Contrato,		@Id_Cobrador,
	@Nro_Auto_Trib,		@Id_Camp,			@Remito_Nro,
	@pPedido_Nro,		@Id_Tarjeta,		@Tarjeta_Nro,
	@Cantidad_Saldo,	@Saldo_Anterior,	@Nro_DJAI,
	@Cantidad_Equiv,	@Id_Trans_Origen,	@Id_Sede_Origen,
	@Email,				@Patente_Transporte,@Patente_Transporte_Acoplado)

	/*****************************************************************************/

	SET @Descripcion = ISNULL((dbo.CF_Cbte_Descrip(@Id_Trans)), '')

	/*****************************************************************************/
	
	UPDATE Transacciones SET Descripcion = Descripcion + ' ' + @Descripcion WHERE Id_Trans = @Id_Trans

	/*****************************************************************************/
	
	COMMIT

	SET @Mensaje = @Descripcion

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage
			,@Id_Trans		AS Id_Trans

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH

PRINT 'FIN Procedimiento: CP_Cbtes_Rem_Generar'
GO


CREATE PROCEDURE [dbo].[CP_Cbtes_Rem_Generar_Item]
@pId_Trans		INT,			/*Cbtes*/
@pId_Producto	VARCHAR(14),	/*Productos*/
@pCantidad		DECIMAL(12,4),
@pObservacion	VARCHAR(8000),
@pFecha_QA		DATETIME,
@pFecha_Venc	DATETIME,
@pPrecio_Grav 	DECIMAL(20, 5), /*Precio Sin IVA*/
@pPorc_Iva 		DECIMAL(5, 2), /*Porcentaje de IVA*/
@pBonif			DECIMAL(5, 2),
@pId_Cliente	INT				/*Clientes*/
AS

DECLARE @Trans TABLE (ErrorNumber	INT 
					,ErrorSeverity  INT 
					,ErrorState		INT
					,ErrorProcedure	VARCHAR(100)
					,ErrorLine		INT
					,ErrorMessage	VARCHAR(1000)
					,Item			SMALLINT)

/*Declaracion Variables Locales*/
DECLARE @Item 					SMALLINT
DECLARE @Id_Estado_Cbte 		SMALLINT
DECLARE @Calle 					CHAR(5)
DECLARE @Columna 				CHAR(5)
DECLARE @Fila 					CHAR(5)
DECLARE @Bultos 				DECIMAL(15, 5)
DECLARE @Despacho 				VARCHAR(100)
DECLARE @Serie 					VARCHAR(100)
DECLARE @Millas 				INT
DECLARE @Cantidad_Saldo 		DECIMAL(15, 5)
DECLARE @Precio_Exen 			DECIMAL(20, 5)
DECLARE @Imp_Gravado 			DECIMAL(20, 2)
DECLARE @Imp_Exento 			DECIMAL(20, 2)
DECLARE @Analisis 				VARCHAR(30)
DECLARE @Lote 					VARCHAR(20)
DECLARE @Flag_QA 				CHAR(1)
DECLARE @Descripcion_producto 	VARCHAR(100)
DECLARE @Id_Unidad_Medida 		CHAR(4)
DECLARE @Imp_Final				DECIMAL(20,5)
DECLARE @Costo 					DECIMAL(20, 5)
DECLARE @Imp_Iva 				DECIMAL(20, 2)
DECLARE @Precio 				DECIMAL(20, 5)
DECLARE @Id_Costo 				INT
DECLARE @Id_Tarea 				SMALLINT
DECLARE @Fecha_Caducidad 		DATETIME
DECLARE @Id_Pais 				CHAR(3)
DECLARE @Id_Usuario 			SMALLINT
DECLARE @Cantidad_Equiv 		DECIMAL(15, 5)
DECLARE @Costo_MO 				DECIMAL(20, 5)
DECLARE @Costo_GF 				DECIMAL(20, 5)
DECLARE @Id_Cond_Pago 			SMALLINT
DECLARE @Fecha_Proceso 			DATETIME
DECLARE @Id_Balanza 			CHAR(10)
DECLARE @Orden 					SMALLINT
DECLARE @Flag_NoImp_Factura 	TINYINT
DECLARE @Nro_Tag 				VARCHAR(30)
DECLARE @Fecha_Elaboracion 		DATETIME
DECLARE @Costo_Comparativo 		DECIMAL(13, 4)
DECLARE @Porc_Imp_Int 			DECIMAL(5, 2)
DECLARE @Id_Cta_Banco 			SMALLINT
DECLARE @Flag_Existe_Trans		TINYINT
DECLARE @Flag_Existe_Cliente	TINYINT
DECLARE @Flag_Existe_Producto	TINYINT

DECLARE @Id_Lista_Precio		SMALLINT
DECLARE @Precio_Gravado_Producto DECIMAL(20, 5)

DECLARE @Mensaje				VARCHAR(100)
/*Fin de Declaraciones Variables Locales */

PRINT 'Procedimiento: CP_Cbtes_Rem_Generar_Item'

BEGIN TRY
	BEGIN TRAN

	SET @Flag_Existe_Trans = ISNULL((SELECT 1 FROM Cbtes WHERE Id_Trans = @pId_Trans), 0)
	IF (@Flag_Existe_Trans = 0)
	BEGIN
		SET @Mensaje = 'No existe la Transaccion'

		SELECT	2001			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Item			AS Item
		ROLLBACK
		RETURN
	END

	SET @Flag_Existe_Cliente = ISNULL((SELECT 1 FROM Clientes WHERE Id_Cliente = @pId_Cliente), 0)
	IF (@Flag_Existe_Cliente = 0)
	BEGIN
		SET @Mensaje = 'No existe el Cliente'

		SELECT	2002			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Item			AS Item
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SET @Flag_Existe_Cliente = ISNULL((SELECT 1 FROM Clientes WHERE Id_Cliente = @pId_Cliente AND ISNULL(Activo, 0) = 1), 0)
	IF (@Flag_Existe_Cliente = 0)
	BEGIN
		SET @Mensaje = 'El Cliente esta Inactivo'

		SELECT	2003			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Item			AS Item
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SET @Flag_Existe_Producto = ISNULL((SELECT 1 FROM Productos WHERE Id_Producto = @pId_Producto), 0)
	IF (@Flag_Existe_Producto = 0)
	BEGIN
		SET @Mensaje = 'No existe el producto'

		SELECT	2004			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,@Item			AS Item
		ROLLBACK
		RETURN
	END

	/*************************************************************************************************/

	SELECT  @Id_Estado_Cbte	= ISNULL(Id_Estado_Cbte, 0),
			@Lote			= ISNULL(Lote, ''),
			@Id_Usuario		= ISNULL(Id_Usuario, '-1')
	FROM Cbtes
	WHERE 
	Id_Trans = @pId_Trans

	/*************************************************************************************************/

	SELECT  @Calle					= ISNULL(Calle, ''),
			@Columna				= ISNULL(Columna, ''),
			@Fila					= ISNULL(Fila, ''),
			@Despacho				= ISNULL(Despacho, ''),
			@Descripcion_producto	= ISNULL(Descripcion_Resumida, ''),
			@Id_Unidad_Medida		= ISNULL(Id_Unidad_Medida, ''),
			@Costo					= ISNULL(Costo, 0),
			@Id_Cond_Pago			= ISNULL(Id_Cond_Pago, 0),
			@Id_Cta_Banco			= ISNULL(Id_Cta_Banco, 0),
			@Precio_Gravado_Producto = ISNULL(Precio_Gravado, 0)
	FROM Productos
	WHERE 
	Id_Producto = @pId_Producto	

	/*************************************************************************************************/	

	/*2018-10-31: Si el precio que se pasa es cero entonces busca en el producto o en la lista de precio del cliente el producto*/
	IF(@pPrecio_Grav = 0)
	BEGIN
		SET @Id_Lista_Precio = ISNULL((SELECT ISNULL(Id_Lista_Precio, 0) FROM Clientes WHERE Id_Cliente = @pId_Cliente), 0)

		IF(@Id_Lista_Precio = 0)
		BEGIN
			SET @pPrecio_Grav = @Precio_Gravado_Producto
		END
		ELSE
		BEGIN
			SET @pPrecio_Grav = ISNULL((SELECT ISNULL(Precio,0) FROM Prod_Listas_Precios_Items WHERE Id_Lista_Precio = @Id_Lista_Precio AND Id_Producto = @pId_Producto), 0)
		END
	END

	/*************************************************************************************************/

	SET @Item 					= (ISNULL((SELECT MAX(ISNULL(Item, 0)) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans), 0)) + 1
	SET @Bultos 				= 0
	SET @Serie 					= ''
	SET @Millas 				= 0
	SET @Cantidad_Saldo 		= @pCantidad
	SET @Precio_Exen 			= 0
	SET @Imp_Gravado 			= @pPrecio_Grav
	SET @Imp_Exento 			= @Precio_Exen
	SET @Analisis 				= ''
	SET @Flag_QA 				= 'A'
	SET @Imp_Iva 				= ((@pPrecio_Grav * @pPorc_Iva) / 100)
	SET @Imp_Final				= (@pPrecio_Grav + @Imp_Iva)
	SET @Precio 				= @pPrecio_Grav
	SET @Id_Costo 				= 0
	SET @Id_Tarea 				= 0
	SET @Fecha_Caducidad 		= NULL
	SET @Id_Pais 				= ''
	SET @Cantidad_Equiv 		= 0
	SET @Costo_MO 				= 0
	SET @Costo_GF 				= 0
	SET @Fecha_Proceso 			= NULL
	SET @Id_Balanza 			= ''
	SET @Orden 					= 0
	SET @Flag_NoImp_Factura 	= 0
	SET @Nro_Tag 				= ''
	SET @Fecha_Elaboracion 		= NULL
	SET @Costo_Comparativo 		= 0
	SET @Porc_Imp_Int 			= 0

	/*************************************************************************************************/

	INSERT INTO Cbtes_Items 
	(Id_Trans,		Item,					Id_Producto, 
	Id_Estado_Cbte, Cantidad,				Calle, 
	Columna,		Fila,					Bultos, 
	Despacho,		Serie,					Fecha_Venc,
	Observacion,	Millas,					Cantidad_Saldo, 
	Precio_Grav,	Precio_Exen,			Imp_Gravado, 
	Imp_Exento,		Analisis,				Lote, 
	Flag_QA,		Fecha_QA,				Porc_Iva, 
	Bonif,			Descripcion_producto,	Id_Unidad_Medida, 
	Imp_Final,		Costo,					Imp_Iva, 
	Precio,			Id_Costo,				Id_Cliente,
	Id_Tarea,		Fecha_Caducidad,		Id_Pais, 
	Id_Usuario,		Cantidad_Equiv,			Costo_MO, 
	Costo_GF,		Id_Cond_Pago,			Fecha_Proceso, 
	Id_Balanza,		Orden,					Flag_NoImp_Factura, 
	Nro_Tag,		Fecha_Elaboracion,		Costo_Comparativo, 
	Porc_Imp_Int,	Id_Cta_Banco)
	VALUES
	(@pId_Trans,		@Item,					@pId_Producto, 
	@Id_Estado_Cbte,	@pCantidad,				@Calle, 
	@Columna,			@Fila,					@Bultos, 
	@Despacho,			@Serie,					@pFecha_Venc,
	@pObservacion,		@Millas,				@Cantidad_Saldo, 
	@pPrecio_Grav,		@Precio_Exen,			@Imp_Gravado, 
	@Imp_Exento,		@Analisis,				@Lote, 
	@Flag_QA,			@pFecha_QA,				@pPorc_Iva, 
	@pBonif,			@Descripcion_producto,	@Id_Unidad_Medida, 
	@Imp_Final,			@Costo,					@Imp_Iva, 
	@Precio,			@Id_Costo,				@pId_Cliente,
	@Id_Tarea,			@Fecha_Caducidad,		@Id_Pais, 
	@Id_Usuario,		@Cantidad_Equiv,		@Costo_MO, 
	@Costo_GF,			@Id_Cond_Pago,			@Fecha_Proceso, 
	@Id_Balanza,		@Orden,					@Flag_NoImp_Factura, 
	@Nro_Tag,			@Fecha_Elaboracion,		@Costo_Comparativo, 
	@Porc_Imp_Int,		@Id_Cta_Banco)

	/*************************************************************************************************/
	
	COMMIT

	SET @Mensaje = @Descripcion_producto

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage
			,@Item			AS Item

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH

PRINT 'FIN Procedimiento: CP_Cbtes_Rem_Generar_Item'
GO


CREATE PROCEDURE [dbo].[CP_Cbtes_Venc_Items_Ctrl]    
	@Id_Trans INT,
	@Fecha DATETIME
AS


DECLARE @Fecha_Tmp DATETIME

SELECT P.Descripcion_Detallada,CVT.Id_Tipo_Venc,CVT.Descripcion,@Fecha_Tmp AS Fecha_Venc,V.Cant_Dias_Gracia
    INTO #Venc_Temp
	FROM Cbtes_Items I, Productos P, Prod_Cli_Venc V, Clientes_Venc_Tipos CVT
	WHERE I.Id_Trans = @Id_Trans
	AND P.Id_Producto = I.Id_Producto
	AND V.Id_Producto = I.Id_Producto
	AND CVT.Id_Tipo_Venc = V.Id_Tipo_Venc
	AND NOT EXISTS (SELECT 1 FROM  Clientes_Venc CV WHERE CV.Id_Cliente = I.Id_Cliente 	AND CV.Id_Tipo_Venc = V.Id_Tipo_Venc)
	
INSERT INTO #Venc_Temp
SELECT P.Descripcion_Detallada,CVT.Id_Tipo_Venc,CVT.Descripcion,CV.Fecha AS Fecha_Venc ,V.Cant_Dias_Gracia
	FROM Cbtes_Items I, Productos P, Prod_Cli_Venc V, Clientes_Venc_Tipos CVT, Clientes_Venc CV
	WHERE I.Id_Trans = @Id_Trans
	AND P.Id_Producto = I.Id_Producto
	AND V.Id_Producto = I.Id_Producto
	AND CVT.Id_Tipo_Venc = V.Id_Tipo_Venc
	AND CV.Id_Cliente = I.Id_Cliente
	AND CV.Id_Tipo_Venc = V.Id_Tipo_Venc
	AND ISNULL(CV.Fecha,'19000101') + V.Cant_Dias_Gracia < @Fecha 

INSERT INTO #Venc_Temp
SELECT P.Descripcion_Detallada,CVT.Id_Tipo_Venc,CVT.Descripcion,@Fecha_Tmp AS Fecha_Venc, 0 AS Cant_Dias_Gracia
	FROM Cbtes_Items I, Productos P, Clientes_Venc_Tipos CVT, Clientes_Venc_Tipos_Flias V
	WHERE I.Id_Trans = @Id_Trans
	AND P.Id_Producto = I.Id_Producto
	AND V.Id_Familia = P.Id_Familia
	AND V.Id_Tipo_Venc = CVT.Id_Tipo_Venc
	AND NOT EXISTS (SELECT 1 FROM  Clientes_Venc CV WHERE CV.Id_Cliente = I.Id_Cliente 	AND CV.Id_Tipo_Venc = V.Id_Tipo_Venc)


INSERT INTO #Venc_Temp
SELECT P.Descripcion_Detallada,CVT.Id_Tipo_Venc,CVT.Descripcion,CV.Fecha AS Fecha_Venc ,0 AS Cant_Dias_Gracia
	FROM Cbtes_Items I, Productos P,  Clientes_Venc_Tipos CVT, Clientes_Venc CV, Clientes_Venc_Tipos_Flias V
	WHERE I.Id_Trans = @Id_Trans
	AND P.Id_Producto = I.Id_Producto
	AND CVT.Id_Tipo_Venc = V.Id_Tipo_Venc
	AND CV.Id_Cliente = I.Id_Cliente
	AND CV.Id_Tipo_Venc = CVT.Id_Tipo_Venc
	AND V.Id_Familia = P.Id_Familia
	AND V.Id_Tipo_Venc = CVT.Id_Tipo_Venc
	AND ISNULL(CV.Fecha,'19000101')   < @Fecha 

SELECT * FROM #Venc_Temp
GO


CREATE PROCEDURE [dbo].[CP_CleverResto_Facturar]	@Id_Mesa_Mov	INT

AS
BEGIN

---------------------------------agrego los productos------------------------------------------
insert into Productos 
(Id_Producto, Descripcion_Detallada, Descripcion_Resumida,Cantidad,Costo,Precio_Final,Observaciones,Vendible
,Activo,Precio_Gravado,Id_Iva)

select 'CR' + CAST(P.Id_Producto as VARCHAR(10))
,LTRIM(RTRIM(Descripcion)) +' - '+ CAST(P.Id_Producto as VARCHAR(10)),Descripcion_Corta,Cantidad,Costo,Precio,Observaciones,Vendible
,Activo, Precio / 1.21,1  
from Pub_Polar.dbo.Productos P
where not exists (select 1 from Productos where Id_Producto = 'CR' + CAST(P.Id_Producto as VARCHAR(10)))


---------------------------------------------------------------------------------------------------------
DECLARE @Lote VARCHAR(20)
		,@Fecha DATETIME
		,@FechaVence DATETIME
		,@Id_Cliente INT
		,@Id_Tipo_Cbte CHAR(4)
		,@Id_Cond_Pago INT
		,@Id_Moneda CHAR(3)
		,@Cotizacion DECIMAL(12,4)
		,@Importe	DECIMAL(12,2)
		,@imp_gravado DECIMAL(12,2)
		,@Nombre	VARCHAR(100)

DECLARE	@Id_Trans		INT,
	@Item		INT,
	@Id_Producto CHAR(14),
	@Cantidad decimal(12,2),
	@Nota		VARCHAR(200),
	@Importe_Item	DECIMAL(12,2),
	@descripcion_producto VARCHAR(100),
	@Suc  INT,
	@Imp_iva DECIMAL(12,2)
	


DECLARE @Id_Iva	CHAR(3)
		,@Cuit		VARCHAR(13)
		,@Doc_Nro   BIGINT


---------------------------------------------------------------------------------------------------------


BEGIN TRY  
BEGIN TRAN


--------------------------- Seteos Generales -----------------------------------------------

SELECT	@Id_Cliente = Id_Cliente ,@Fecha = M.Cierre ,@FechaVence = M.Cierre	,@Importe	= M.Imp_Neto FROM Pub_Polar.dbo.Mesas_Mov M WHERE M.Id_Mesa_Mov = @Id_Mesa_Mov

IF ISNULL(@Id_Cliente,0) = 0     	
	SET @Id_Cliente = dbo.CF_xParam('Id_Cliente_CF')

SELECT	@Id_Iva = Id_Iva, @Cuit = Cuit ,@Doc_Nro = Doc_Nro, @Nombre = Razon_Social FROM Clientes WHERE Id_Cliente = @Id_Cliente
		

SET @Lote = ''
SET @Id_Cond_Pago = 1
SET @Id_Moneda = dbo.CF_xParam('Moneda_Nacional')
SET @Cotizacion = 1
		
IF @Id_Iva = dbo.CF_xParam('Iva_CF') OR @Id_Iva = dbo.CF_xParam('Iva_CF_DNI') 
	SET @Id_Tipo_Cbte = 'FBE'
ELSE
	SET @Id_Tipo_Cbte = 'FAE'

SET @Suc = (SELECT Id_Sucursal FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte)

-------------------------------------Agreggo Transacciones Y Cbtes-----------------------------------------------------

SET @Id_Trans = (SELECT max(id_trans) from transacciones ) + 1
SET @imp_gravado = @Importe / 1.21

INSERT INTO TRANSACCIONES (id_trans,descripcion,fecha_mov) values (@Id_Trans,'Clever_Resto ' + CAST(@Id_Mesa_Mov AS VARCHAR(10)),GETDATE())

SET @Fecha = CAST(@Fecha AS DATE)

INSERT INTO CBTES (	Id_Cond_Vta		,Id_trans			,Id_Sucursal		,Cbte_Grupo,			Fecha_Venc     
					,id_cliente		,id_estado_Cbte		,id_tipo_cbte,		comprobante_nro,		fecha
					,periodo_iva	,periodo			,imp_total			,saldo					,imp_gravado			
					,destinatario	,lote			,ID_MONEDA			,Id_Cond_Pago				,Cotizacion	
					,Cuit
					,Porc_Bonificacion ,Porc_DescEspecial ,Porc_DescFin, Porc_Iva ,Porc_Iva2 ,Porc_Iva3
					,Imp_Neto ,Imp_DescEspecial, Imp_DescFin ,Imp_Gravado2 ,Imp_Gravado3 ,Imp_Exento , Imp_NoGravado
					,Imp_IVA ,Imp_IVA2 ,Imp_IVA3,Imp_Percep,Imp_Percepcion_IB,Imp_Percepcion_Iva
					,Id_Iva , NRO_DJAI
					)
		   values (	''				,@Id_Trans			,@Suc				,0						,@FECHA    
					,@id_cliente	,0					,@Id_Tipo_cbte		,0						,@FECHA
					,@FECHA			,@FECHA				,@Importe			,@Importe				,@imp_gravado			
					,@NOMBRE		,@Lote			,@Id_Moneda			,@Id_Cond_Pago				,@Cotizacion
					,@cuit
					,0 ,0 ,0, 21 ,0 ,0
					,@imp_gravado ,0, 0 ,0 ,0 ,0 ,0
					,@Importe - @imp_gravado ,0 ,0,0,0,0
					,@Id_Iva , @Id_Mesa_Mov
					)


-----------------------Agrego Items --------------------------------------------------------------------------------------

DECLARE CP_CleverResto_Facturar_Cur CURSOR FOR  
		SELECT Item,'CR' + CAST(I.Id_Producto as VARCHAR(10)),I.Cantidad,Imp_Neto ,P.Descripcion_Corta
		FROM Pub_Polar.dbo.Mesas_Mov_Items I , Pub_Polar.dbo.Productos P
		WHERE I.Id_Mesa_Mov = @Id_Mesa_Mov 
		AND P.Id_Producto = I.Id_Producto

OPEN CP_CleverResto_Facturar_Cur

FETCH NEXT FROM CP_CleverResto_Facturar_Cur INTO @Item , @Id_Producto , @Cantidad, @Importe_Item , @descripcion_producto

WHILE @@FETCH_STATUS = 0
BEGIN
		SET @Imp_iva = @Importe_Item - (@Importe_Item / 1.21)
		INSERT INTO Cbtes_Items		(id_cliente,		descripcion_producto,		Cantidad,
							id_estado_Cbte,		Cantidad_Saldo,				Id_Trans,
							item,				Precio_Grav,				Imp_Gravado,
							Imp_Final,			Precio,						Lote,
							Flag_QA,					Id_Producto
							,Precio_Exen ,Porc_Iva ,Bonif , Costo ,Imp_Iva
							)
				VALUES		(@id_cliente,		RTRIM(@descripcion_producto),1,
							0,					1,							@Id_Trans,
							@Item,				@Importe_Item / 1.21 / @Cantidad,					@Importe_Item / 1.21,
							@Importe_Item,		@Importe_Item / 1.21 / @Cantidad,					'',
							'A',				@Id_Producto
							,0 , 21 , 0 , 0 ,@Imp_iva
							)

		FETCH NEXT FROM CP_CleverResto_Facturar_Cur INTO @Item , @Id_Producto , @Cantidad, @Importe_Item , @descripcion_producto
								
END
CLOSE CP_CleverResto_Facturar_Cur
DEALLOCATE CP_CleverResto_Facturar_Cur

UPDATE Cbtes			SET Id_Estado_Cbte = 16,Saldo = 0	WHERE Id_Trans = @Id_Trans
UPDATE Cbtes_Items		SET Id_Estado_Cbte = 16				WHERE Id_Trans = @Id_Trans
UPDATE Clientes_CtaCte	SET Id_Estado_Cbte = 16, Saldo = 0  wHERE Id_Trans = @Id_Trans
UPDATE Cajas_Mov		SET Id_Estado_Mov_Caja = 2			WHERE Id_Trans = @Id_Trans  

COMMIT
END TRY  

BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;   



END
GO


CREATE PROCEDURE [dbo].[CP_Cliente_Ref_Borrar] @Int INT,@Tit INT
AS

DECLARE @MensajeFinEjec		VARCHAR(100)

IF @Int = 0 
BEGIN
	SELECT 1, 0, 0, 0, 'El cliente no puede ser 0 (cero)'
	RETURN
END

IF @Tit = 0
BEGIN
	SELECT 1, 0, 0, 0, 'El cliente de referencia no puede ser 0 (cero)'
	RETURN
END


BEGIN TRY
	BEGIN TRAN

	SET @MensajeFinEjec = 'Proceso Exitoso'

	IF CAST(dbo.CF_xParam('Cli_Ref_CtaCte_Agrup') as INT ) <> 0
	BEGIN
	    UPDATE Cbtes SET Id_Cliente_Ref =  @Tit 
		             WHERE Id_Cliente = @Int 
					 AND ISNULL(Id_Cliente,0) = 0
				     AND Id_estado_Cbte <> 1
	  
	    --actualizo los items que no tienen id_cliente
		UPDATE Cbtes_Items SET Id_Cliente = @Int
				FROM Cbtes C, Cbtes_Items I
				WHERE I.Id_Trans = C.Id_Trans
				AND ISNULL(I.id_Cliente,0) = 0
				AND C.Id_Cliente =  @Int 

		UPDATE Cbtes_Items SET Id_Cliente = @Tit
				FROM Cbtes C, Cbtes_Items I
				WHERE I.Id_Trans = C.Id_Trans
				AND ISNULL(I.id_Cliente,0) = 0
				AND C.Id_Cliente =  @Tit 
		--FIN: actualizo los items que no tienen id_cliente

		--todo lo que no esta pendiente queda en el titular
		UPDATE Cbtes SET Id_Cliente = @Tit
										--se agrega left para editar el error por truncado 
		               , Destinatario = LEFT (LTRIM(RTRIM(Destinatario)) + ' - ' + LTRIM(RTRIM(E.Razon_Social)),100)
					   , Id_Cliente_Ref = @Tit
				FROM Cbtes C,Clientes E
				WHERE E.Id_Cliente =  @Tit
				AND C.Id_Cliente =  @Int 
				AND C.ID_ESTADO_CBTE <> 1


		UPDATE Clientes_CtaCte SET Id_Cliente = C.Id_cliente  from Clientes_CtaCte K, Cbtes C
		WHERE c.id_trans = k.id_trans  and K.id_cliente = @int and C.id_cliente <> K.id_cliente

		UPDATE Clientes_CtaCte SET Id_Cliente = C.Id_cliente  from Clientes_CtaCte K, Cbtes C
		WHERE c.id_trans = k.id_trans  and K.id_cliente = @Tit and C.id_cliente <> K.id_cliente
		      
	END

	UPDATE Clientes SET Id_Cliente_Ref = 0 WHERE Id_Cliente = @Int
	----------------------------------------------------
	COMMIT
	
	SELECT 0, 0, 0, 0, @MensajeFinEjec
END TRY

BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH
GO


CREATE PROCEDURE [dbo].[CP_Clientes_Deuda](
     @pUsuario    INT
   , @pEquate  SMALLINT
   , @pFechaDesde DATETIME
   , @pFechaHasta DATETIME
   , @pFiltroFecha SMALLINT
   , @pIncluirRelaciones SMALLINT
   , @pFiltrarCbtesSinTarjeta SMALLINT
   , @pUnidNegocio VARCHAR(1000)
   )
AS
 
  IF @pEquate = 0
     RETURN

  DECLARE @Id_Producto Varchar(14)
  ,@Id_Proveedor Int
  ,@Razon_Social VarChar(100)
  ,@Cuit Varchar(13)
  ,@Id_Iva Char(3)
  ,@Id_Alias_Cta_Cont Int
  ,@Id_Cta_Contable_H Int
  ,@Porc_Comision_Prov Decimal(7,2) 
  ,@Importe Decimal(12,2) 
  ,@IMPORTE_CREDITO Decimal(12,2) 
  ,@ID_TIPO_CBTE CHAR(4) 
  ,@FECHA DATETIME
  ,@Imp_prod_siva  Decimal(12,2) 
  ,@TRANS INT
  ,@Id_Cliente_Externo VARCHAR(14)
  ,@Id_Cta_Banco INT
  ,@Id_Cliente INT
  ,@EXISTE_TAG INT

  DECLARE @Sql		    VARCHAR(MAX)
  DECLARE @SqlSaldo	    VARCHAR(MAX)
  DECLARE @SqlSelect	VARCHAR(MAX)
  DECLARE @SqlInto	    VARCHAR(MAX)
  DECLARE @SqlFrom	    VARCHAR(MAX)
  DECLARE @SqlWhere  	VARCHAR(MAX)
  DECLARE @SqlGroup	    VARCHAR(MAX)

  SET @FECHA = (SELECT CAST(GETDATE() AS DATE))
  SET @EXISTE_TAG = 0
  SET @EXISTE_TAG = (SELECT COUNT(*) FROM TagFile_ TAG WHERE TAG.TBL = @pEquate AND TAG.USR = @pUsuario)

  SET @SqlSelect = ' SELECT c.id_cliente   
		  ,ISNULL(C.ID_CLIENTE_REF,0) AS ID_CLIENTE_REF
		  ,ISNULL(F.ID_COBRADOR,'''') as Id_Cobrador
		  ,CC.Fecha_Vence
		  ,CC.Descripcion
		  ,F.COMPROBANTE_NRO
		  ,CC.NRO_CUOTA
		  ,F.FECHA
		  ,VM.Signo
		  ,f.Cotizacion
		  ,CC.Importe
		  ,CC.Saldo
		  ,F.Imp_Total
		  ,Isnull(F.Suc_Destina,0) as sucursal
		  ,CC.ID_TRANS
		  ,F.Id_Centro_Costo
		  ,C.RAZON_SOCIAL
		  ,C.ID_PROVINCIA
		  ,C.ID_LOCALIDAD
		  ,C.Direccion
		  ,C.Id_cliente_Externo
		  ,C.Id_Tipo_Cli
		  ,TC.Descripcion as Descripcion_Tipo
		  ,C.Ult_Cuota_Paga
		  ,C.Telefono
		  ,ISNULL(C.Id_Transporte,0) AS Transporte 
		       '

  SET @SqlInto = ' '

  SET @SqlWhere = ' WHERE C.ACTIVO = 1
				AND CC.ID_Trans = F.Id_Trans 
				AND VM.Id_Moneda = F.Id_Moneda
				AND CC.id_estado_cbte in (1,4) 
				AND f.id_tipo_cbte = TF.id_tipo_cbte 
				AND TF.Compromete_Factura in (1,-1)
				AND ISNULL(C.Id_Tipo_Cli,0) = Isnull(TC.Id_Tipo_Cli,0)
				AND TF.Letra <> ''L''
				AND CC.SALDO <> 0 '

  IF @EXISTE_TAG > 0
      BEGIN
        SET @SqlFrom = ' FROM Clientes_Ctacte CC, cbtes f, Cbtes_Tipos TF, Clientes C,TagFile_ TAG, Valores_Monedas VM , Clientes_Tipos TC '

        SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + '	AND (CC.Id_Cliente = TAG.VAL AND TAG.TBL = ' + Cast(@pEquate as varchar(10)) + ' AND TAG.USR = '+  Cast(@pUsuario as varchar(10)) +')'
      END
	ELSE
	  BEGIN
		SET @SqlFrom = ' FROM Clientes_Ctacte CC, cbtes f, Cbtes_Tipos TF, Clientes C, Valores_Monedas VM, Clientes_Tipos TC '

      END

  IF @pFiltroFecha = 0
     BEGIN
         SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + 'AND F.Fecha >= '''+ CONVERT(VARCHAR(8),@pFechaDesde,112) +'''   
			 	                                    AND F.Fecha < ''' + CONVERT(VARCHAR(8),@pFechaHasta+1,112) +'''' 
     END
   ELSE
     BEGIN
         SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + 'AND CC.Fecha_VENCE >= '''+ CONVERT(VARCHAR(8),@pFechaDesde,112) +'''   
			 	                                    AND CC.Fecha_VENCE < ''' + CONVERT(VARCHAR(8),@pFechaHasta+1,112) +'''' 
     END   
	 
   IF RTRIM(LTRIM(@pUnidNegocio)) <> '' 
	  SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND TF.Id_Unid_Negocio in '+ Cast(@pUnidNegocio as varchar(1000))

   IF @pIncluirRelaciones = 0
	  SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND CC.Id_Cliente = C.Id_Cliente '
	Else
	  SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND CC.Id_Cliente = C.Id_Cliente '

   IF @pFiltrarCbtesSinTarjeta = 1

	  SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND dbo.CF_Cbtes_Por_Debito(CC.ID_Trans,1) = 0 '

--	  SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND (CC.Id_Cliente = C.Id_Cliente  Or CC.Id_Cliente = C.Id_Cliente_Ref )'

	  SET @Sql = @SqlSelect + ' ' + @SqlInto +' '+ @SqlFrom + ' ' + @SqlWhere 
	  
	  print @Sql

	  EXEC(@sql)

  
  

--  exec dbo.CP_Clientes_Deuda -1,400,'19631222','20211231',1,1,1,'(1)'

--EXEC CP_Clientes_Deuda -1,400,'19631223','20210621',0,1,1,''
GO


CREATE PROCEDURE [dbo].[CP_Clientes_Deuda_Resumen](
     @pUsuario    INT
   , @pEquate  SMALLINT
   , @pFechaDesde DATETIME
   , @pFechaHasta DATETIME
   , @pFiltroFecha SMALLINT
   , @pIncluirRelaciones SMALLINT
   , @pFiltrarCbtesSinTarjeta SMALLINT
   , @pUnidNegocio VARCHAR(1000)
   )
AS
 
  IF @pEquate = 0
     RETURN

  DECLARE @Id_Producto Varchar(14)
  ,@Id_Proveedor Int
  ,@Razon_Social VarChar(100)
  ,@Cuit Varchar(13)
  ,@Id_Iva Char(3)
  ,@Id_Alias_Cta_Cont Int
  ,@Id_Cta_Contable_H Int
  ,@Porc_Comision_Prov Decimal(7,2) 
  ,@Importe Decimal(12,2) 
  ,@IMPORTE_CREDITO Decimal(12,2) 
  ,@ID_TIPO_CBTE CHAR(4) 
  ,@FECHA DATETIME
  ,@Imp_prod_siva  Decimal(12,2) 
  ,@TRANS INT
  ,@Id_Cliente_Externo VARCHAR(14)
  ,@Id_Cta_Banco INT
  ,@Id_Cliente INT
  ,@EXISTE_TAG INT

  DECLARE @Sql		    VARCHAR(MAX)
  DECLARE @SqlSaldo	    VARCHAR(MAX)
  DECLARE @SqlSelect	VARCHAR(MAX)
  DECLARE @SqlInto	    VARCHAR(MAX)
  DECLARE @SqlFrom	    VARCHAR(MAX)
  DECLARE @SqlWhere  	VARCHAR(MAX)
  DECLARE @SqlGroup	    VARCHAR(MAX)

  SET @FECHA = (SELECT CAST(GETDATE() AS DATE))
  SET @EXISTE_TAG = 0
  SET @EXISTE_TAG = (SELECT COUNT(*) FROM TagFile_ TAG WHERE TAG.TBL = @pEquate AND TAG.USR = @pUsuario)

  SET @SqlSelect = ' SELECT c.Id_Cliente
		  ,C.Razon_Social
		  ,SUM(CC.Saldo*f.Cotizacion) AS Saldo'

  SET @SqlInto = ' '

  SET @SqlWhere = ' WHERE C.ACTIVO = 1
				AND CC.ID_Trans = F.Id_Trans 
				AND VM.Id_Moneda = F.Id_Moneda
				AND CC.id_estado_cbte in (1,4) 
				AND f.id_tipo_cbte = TF.id_tipo_cbte 
				AND (TF.Compromete_Factura in (1,-1) OR TF.Compromete_Recibos IN (1,-1))
				AND ISNULL(F.ID_CLIENTE,0) <> 0
				AND ISNULL(C.Id_Tipo_Cli,0) = Isnull(TC.Id_Tipo_Cli,0)
				AND TF.Letra <> ''L''
				AND CC.SALDO <> 0 '

  IF @EXISTE_TAG > 0
      BEGIN
        SET @SqlFrom = ' FROM Clientes_Ctacte CC, cbtes f, Cbtes_Tipos TF, Clientes C,TagFile_ TAG, Valores_Monedas VM , Clientes_Tipos TC '

        SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + '	AND (CC.Id_Cliente = TAG.VAL AND TAG.TBL = ' + Cast(@pEquate as varchar(10)) + ' AND TAG.USR = '+  Cast(@pUsuario as varchar(10)) +')'
      END
	ELSE
	  BEGIN
		SET @SqlFrom = ' FROM Clientes_Ctacte CC, cbtes f, Cbtes_Tipos TF, Clientes C, Valores_Monedas VM, Clientes_Tipos TC '

      END

  IF @pFiltroFecha = 0
     BEGIN
         SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + 'AND F.Fecha >= '''+ CONVERT(VARCHAR(8),@pFechaDesde,112) +'''   
			 	                                    AND F.Fecha < ''' + CONVERT(VARCHAR(8),@pFechaHasta+1,112) +'''' 
     END
   ELSE
     BEGIN
         SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + 'AND CC.Fecha_VENCE >= '''+ CONVERT(VARCHAR(8),@pFechaDesde,112) +'''   
			 	                                    AND CC.Fecha_VENCE < ''' + CONVERT(VARCHAR(8),@pFechaHasta+1,112) +'''' 
     END   
	 
   IF RTRIM(LTRIM(@pUnidNegocio)) <> '' 
	  SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND TF.Id_Unid_Negocio in '+ Cast(@pUnidNegocio as varchar(1000))

   IF @pIncluirRelaciones = 0
	  SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND CC.Id_Cliente = C.Id_Cliente '
	Else
	  SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND CC.Id_Cliente = C.Id_Cliente '

   IF @pFiltrarCbtesSinTarjeta = 1

	  SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND dbo.CF_Cbtes_Por_Debito(CC.ID_Trans,1) = 0 '

--	  SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND (CC.Id_Cliente = C.Id_Cliente  Or CC.Id_Cliente = C.Id_Cliente_Ref )'

	  SET @Sql = @SqlSelect + ' ' + @SqlInto +' '+ @SqlFrom + ' ' + @SqlWhere + 'GROUP BY  c.id_cliente,C.RAZON_SOCIAL order by C.Razon_Social' 
	  
	  print @Sql

	  EXEC(@sql)

  
  

-- exec dbo.CP_Clientes_Deuda_Resumen -1,400,'19631222','20211231',1,1,1,'(1)'

-- EXEC CP_Clientes_Deuda_Resumen -1,400,'19631223','20211231',1,1,1,''


