CREATE Procedure [dbo].[CP_Clientes_Estadisticas]
As
Declare @Fecha Date
, @socios_activos INT
, @socios_altas INT
, @socios_bajas INT
, @Color char(20)
, @Tendencia Char(2)
, @Valor_1   Decimal(16,4)
, @Valor_2   Decimal(16,4)
, @Valor_3   Decimal(16,4)
, @Valor_4   Decimal(16,4)
, @Valor_5   Decimal(16,4)
, @Valor_6   Decimal(16,4)

SET @Fecha =  convert(Date,(getdate()))


select @socios_activos = Count(*)  from clientes C, Clientes_Tipos T 
where C.Id_Tipo_Cli = T.Id_Tipo_Cli
and Fecha_baja is null
and Activo = 1
And Tipo_Persona = 'F' 
And T.Flag_Tipo <> 'N'


select  @Tendencia = Tendencia 
       , @Valor_1  =  Valor_1
	   , @Valor_2 =  Valor_2
	   , @Valor_3 =  Valor_3
	   , @Valor_4 =  Valor_4
	   , @Valor_5 =  Valor_5
	   , @Valor_6 =  Valor_6 from Indices where Id_Indice = 1001

If @Tendencia = '+'
   BEGIN
      set @COLOR = 'R'
      IF @socios_activos >  @Valor_1
	     set @COLOR = 'O'
      IF @socios_activos >=  @Valor_2
	     set @COLOR = 'Y'
      IF @socios_activos >=  @Valor_3
	     set @COLOR = 'G'
    END

If @Tendencia = '-'
   BEGIN
      set @COLOR = 'G'
      IF @socios_activos >  @Valor_1
	     set @COLOR = 'Y' 
      IF @socios_activos >=  @Valor_2
	     set @COLOR = 'O'
      IF @socios_activos >=  @Valor_3
	     set @COLOR = 'R'
    END

IF EXISTS(SELECT * FROM Indices_Mov WHERE Id_Indice = 1001 AND FECHA = @FECHA)

