	       WHERE Id_Indice = 1001 AND FECHA = @FECHA
   ELSE
	Insert INTO Indices_Mov(Id_Indice,Fecha,Valor,Color) 
		   values (1001,@Fecha,@socios_activos,@Color)

--- no socios

