    UPDATE Indices_Mov SET Valor = @socios_altas ,COLOR = @Color  
	       WHERE Id_Indice = 1002 AND FECHA = @FECHA
   ELSE
	Insert INTO Indices_Mov(Id_Indice,Fecha,Valor,Color) 
		   values (1002,@Fecha,@socios_altas,@Color)

--- bajas

select @socios_bajas = Count(*)  from clientes C, Clientes_Tipos T 
where C.Id_Tipo_Cli = T.Id_Tipo_Cli
and Fecha_baja >=getdate() and Fecha_baja < getdate()+1 
And Tipo_Persona = 'F' 
And T.Flag_Tipo <> 'N'


select  @Tendencia = Tendencia 
       , @Valor_1  =  Valor_1
	   , @Valor_2 =  Valor_2
	   , @Valor_3 =  Valor_3
	   , @Valor_4 =  Valor_4
	   , @Valor_5 =  Valor_5
