	         from #Socios_Cat

  Drop Table #Socios_Cat

-- NO SOCIOS POR CATEGORIA

  SELECT ISNULL(C.ID_TIPO_CLI,0) AS ID_TIPO_CLI,T.DESCRIPCION,COUNT(*) AS CANTIDAD 
      Into #NoSocios_Cat
      FROM Clientes C, Clientes_Tipos T
	  WHERE C.Id_Tipo_Cli = T.Id_Tipo_Cli
