SET @Cantidad_Mes = ISNULL((SELECT SUM(CANTIDAD) FROM #UCP WHERE MESES = -4),0)
INSERT INTO Indices_Mov 
SELECT 1300 AS Id_Indice, @Fecha AS Fecha, @Cantidad_Mes as Valor,'O','Debe 4 mes'
