DECLARE @Id_Transportista		VARCHAR(10)
DECLARE @Bonif					DECIMAL(5, 2)
DECLARE @Id_Cond_Pago			SMALLINT
DECLARE @Cred_CtaCte			DECIMAL(12, 2)
DECLARE @Cred_ChePro			DECIMAL(12, 2)
DECLARE @Cred_CheTer			DECIMAL(12, 2)
DECLARE @Id_Iva					CHAR(3)
DECLARE @CTE					VARCHAR(50)
DECLARE @Id_Concepto			INT
DECLARE @Id_Cta_Banco			SMALLINT
DECLARE @Id_Zona				CHAR(5) 
DECLARE @Observacion			VARCHAR(8000)
DECLARE @Id_Cliente_Externo		VARCHAR(14)
DECLARE @Id_Transporte			INT
DECLARE @Id_Alias_Cta_Cont_Venta SMALLINT
DECLARE @Mercado				CHAR(1)
DECLARE @Observa_Fact			VARCHAR(8000)
DECLARE @Entre_Calle_1			VARCHAR(35) 
DECLARE @Entre_Calle_2			VARCHAR(35) 
DECLARE @Plano_Nro				VARCHAR(10)
DECLARE @Plano_Matriz			VARCHAR(10)
DECLARE @Id_Cobrador			VARCHAR(10)
DECLARE @Id_Motivo_Est			SMALLINT
DECLARE @Id_Dep_Fisico			CHAR(3)
DECLARE @Id_Dep_Logico			CHAR(3)
DECLARE @Id_Tarjeta				VARCHAR(10)
DECLARE @Id_Banco				SMALLINT
DECLARE @Tar_Nro				VARCHAR(25) 
DECLARE @Tar_Fecha_Vence		DATETIME
DECLARE @Tar_Titular			VARCHAR(50)
DECLARE @Direccion_Cob			VARCHAR(100)
DECLARE @Cp_Cob					VARCHAR(10)
DECLARE @Id_Pais_Cob			CHAR(3)
DECLARE @Id_Provincia_Cob		CHAR(3)
DECLARE @Provincia_Descrip_Cob	VARCHAR(200)
DECLARE @Id_Localidad_Cob		INT
DECLARE @Localidad_Descrip_Cob	VARCHAR(200)
DECLARE @Entre_Calle_1_Cob		VARCHAR(35) 
DECLARE @Entre_Calle_2_Cob		VARCHAR(35) 
DECLARE @Plano_Nro_Cob			VARCHAR(10)
DECLARE @Plano_Matriz_Cob		VARCHAR(10)
DECLARE @Fecha_Ven_Trib			DATETIME
DECLARE @Web					VARCHAR(254)
DECLARE @Id_Cliente_Ref			INT
DECLARE @Fecha_Alta				DATETIME
DECLARE @Fecha_Baja				DATETIME
DECLARE @Id_Centro_Costo		CHAR(10)
DECLARE @Id_Promotor			CHAR(10)
DECLARE @Nombre_Fantasia		VARCHAR(100)
DECLARE @Id_Cond_Vta			CHAR(10)
DECLARE @Id_Puerto				CHAR(3)
DECLARE @Id_Calle				INT
DECLARE @Nro					INT
DECLARE @Depto					CHAR(10)	
DECLARE @Fecha_Modif			DATETIME
DECLARE @Foto					VARCHAR(254)
DECLARE @Latitud				DECIMAL(11, 7) 
DECLARE @Longitud				DECIMAL(11, 7) 
DECLARE @Id_Calle_Cob			INT
DECLARE @Nro_Cob				INT
DECLARE @Depto_Cob				VARCHAR(10)
DECLARE @Latitud_Cob			DECIMAL(11, 7) 
DECLARE @Longitud_Cob			DECIMAL(11, 7) 
DECLARE @Id_Precio_Especial		INT
DECLARE @Cod_Autoriz_Trib		VARCHAR(30)
DECLARE @Id_Alias_Cta_Cont_Venta_Dol SMALLINT
DECLARE @Estado_Civil			CHAR(1)
DECLARE @Id_Nacionalidad		CHAR(3)
DECLARE @Id_Cli_Relac			SMALLINT
DECLARE @Tipo_Persona			CHAR(1)
DECLARE @telefono				VARCHAR(900) 
DECLARE @Calle_Descrip			VARCHAR(100)
DECLARE @Calle_Cob_Descrip		VARCHAR(100)
DECLARE @Imp_Aporte				DECIMAL(12, 2)
DECLARE @Fecha_Aporte			DATETIME
DECLARE @Credencial_Banda1		VARCHAR(100)
DECLARE @Credencial_Banda2		VARCHAR(100)
DECLARE @Credencial_Imp			SMALLINT
DECLARE @Ult_Cuota_Paga			DATETIME
DECLARE @Legajo					VARCHAR(30)
DECLARE @Credencial_Entrega		DATETIME
DECLARE @Id_Unid_Negocio		CHAR(10)
DECLARE @Clave_Web				VARCHAR(30)
DECLARE @Flag_Anmat				TINYINT
DECLARE @Nro_Anmat				VARCHAR(26)
DECLARE @Tar_Cuit				VARCHAR(13)
DECLARE @Id_Anmat				CHAR(3)
DECLARE @Coef_Comi_Vta			DECIMAL(8, 4)
DECLARE @Coef_Comi_Cobros		DECIMAL(8, 4)
DECLARE @Email_Cob				VARCHAR(254)
DECLARE @Recorrido_Cob			INT
DECLARE @Tar_Fecha_Alta			DATETIME
DECLARE @Tar_Fecha_Baja			DATETIME
DECLARE @Imp_Fac_Max_Mes		DECIMAL(12, 2)
DECLARE @Email_Web				VARCHAR(300)
DECLARE @Tel_Movil				VARCHAR(20)
DECLARE @Flag_Tel_Movil_Verif	TINYINT
DECLARE @Flag_Comunic_Sms		TINYINT
DECLARE @Flag_Comunic_Email		TINYINT
DECLARE @Carpeta				VARCHAR(256)
DECLARE @Id_Emp_Area			SMALLINT
DECLARE @Id_AR_ARBA_COT_Tipo_Dom_Nro VARCHAR(5)
DECLARE @Dir_Entrega_Numero		SMALLINT
DECLARE @Dir_Entrega_Piso		VARCHAR(3)
DECLARE @Dir_Entrega_Dto		VARCHAR(4)
DECLARE @Dir_Entrega_Barrio		VARCHAR(30)
DECLARE @Dir_Entrega_CP			VARCHAR(8)
DECLARE @Dir_Entrega_Localidad	VARCHAR(50) 
DECLARE @Nombre					VARCHAR(100)
DECLARE @Apellido				VARCHAR(100)
DECLARE @Sexo					CHAR(1)
DECLARE @Fecha_Nac				DATETIME
DECLARE @Doc_Nro				BIGINT
DECLARE @Id_Tipo_Cli			SMALLINT
DECLARE @Credencial_Nro			VARCHAR(30)
DECLARE @Id_Usuario_Alta		SMALLINT
DECLARE @Max_Patente			VARCHAR(14)
DECLARE @Titular_GF				INT
DECLARE @Titular_RSocial_GF		VARCHAR(100) 

DECLARE @CD_ES_Tipo				CHAR(1)
DECLARE @CD_ES_Origen			CHAR(1)
DECLARE @CD_ES_Id_Tarjeta		VARCHAR(50)
DECLARE @CD_ES_Fecha			DATETIME
DECLARE @CD_ES_Resultado		CHAR(1)
DECLARE @CD_ES_Id_Controlador	SMALLINT
DECLARE @CD_ES_Id_Acceso		SMALLINT
DECLARE @CD_ES_tipo_reg			CHAR(5) 
DECLARE @Usuario_Alta			VARCHAR(41)
DECLARE @Id_CD_Motivo			INT
/*Fin de Declaraciones Variables Locales */

PRINT 'Procedimiento: CP_Clientes_Patente'

IF(@pFlag_GrabaRegistro IS NULL)
BEGIN
	SET @pFlag_GrabaRegistro = 1 /*Por defecto graba el registro en CD_ES*/
END


IF EXISTS ( SELECT * 
			FROM sysobjects 
            WHERE
            id = object_id(N'[dbo].[CP_Clientes_Patente_]') 
			AND OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN
	EXEC CP_Clientes_Patente_	@pId_Cliente,
								@pId_Cliente_Ref,
								@pId_Cliente_Externo,
								@pFlag_GrabaRegistro,
								@pId_Controlador
	RETURN
END

BEGIN TRY
	BEGIN TRAN

	SET @Titular_GF = ISNULL((SELECT TOP 1 Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @pId_Cliente_Ref AND Activo = 1), 0)
	IF(@Titular_GF <> 0)
	BEGIN
		SET @pId_Cliente_Ref	= @Titular_GF
		SET @Titular_RSocial_GF = ISNULL((SELECT Razon_Social FROM Clientes WHERE Id_Cliente = @Titular_GF AND Activo = 1), 0) --INTEGRANTE
	END
	ELSE
	BEGIN
		SET @Titular_RSocial_GF = ISNULL((SELECT Razon_Social FROM Clientes WHERE Id_Cliente = @pId_Cliente_Ref AND Activo = 1), 0) --INDIVIDUAL
	END

IF (@pTraerMax_Patente > 0)
BEGIN
	SET @Max_Patente = ISNULL((SELECT TOP 1 Id_Cliente_Externo FROM Clientes WHERE Id_Cliente_Ref = @pId_Cliente_Ref AND Tipo_Persona = 'A' order by Id_Cliente DESC), '')
	BEGIN
		SELECT	 0						AS ErrorNumber 
				,0						AS ErrorSeverity  
				,0						AS ErrorState 
				,0						AS ErrorProcedure  
				,0						AS ErrorLine		
				,@Mensaje				AS ErrorMessage
				,@Max_Patente			AS Id_Cliente
		ROLLBACK
		RETURN 1
	END

END
ELSE
BEGIN
	IF(@pId_Cliente > 0)
	BEGIN
		SET @Flag_Existe_Patente = @pId_Cliente
	END
	ELSE
	BEGIN
		IF(@pId_Cliente_Ref = '' OR @pId_Cliente_Externo = '')
			BEGIN
			SET @Mensaje = 'NO SE RECIBIERON CORRECTAMENTE TODOS LOS PARAMETROS'

			SELECT	 0				AS ErrorNumber 
			,0						AS ErrorSeverity  
			,0						AS ErrorState 
			,0						AS ErrorProcedure  
			,0						AS ErrorLine		
			,@Mensaje				AS ErrorMessage
			,0						AS Id_Cliente
						
			ROLLBACK
			RETURN 1
		END

	SET @Flag_Existe_Patente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Id_Cliente_Externo = @pId_Cliente_Externo), 0)
	END
	
	IF(@Flag_Existe_Patente = 0)
	BEGIN
		/*Asignacion de Variables*/
		SET @Nombre						= CONVERT(VARCHAR,@Titular_RSocial_GF)
		SET @Apellido					= CONVERT(VARCHAR,@pId_Cliente_Externo) + ' - '
		SET @Sexo						= ''
		SET @Fecha_Nac					= '19000101'
		SET @Doc_Nro					= 0
		SET @Id_Tipo_Cli				= dbo.CF_xParam('SCA_Automotor_Categ')
		SET @Credencial_Nro				= 0
		SET @Id_Usuario_Alta			= 0     --pasar por parametro
		SET @Id_Tipo_Doc				= ''	--Documentos_Tipos
		SET @Id_Localidad				= 0		--Tab_Localidades
		SET @Id_Provincia				= ''	--La del registro de Tab_Localidades
		SET @Id_Pais					= ''	--La del registro de Tab_Localidades
		SET @Activo						= 1
		SET @Id_Lista_Precio			= 0		--Prod_Listas_Precios
		SET @Id_Cond_Pago				= dbo.CF_xParam('SCA_Visitor_ConPago')
		SET @Id_Iva						= dbo.CF_xParam('SCA_Visitor_Iva')
		SET @Id_Concepto				= dbo.CF_xParam('SCA_Visitor_Concept')
		SET @Observacion				= 'Ingresado Automaticamente desde Proceso Patente'
		SET @Id_Alias_Cta_Cont_Venta	= dbo.CF_xParam('SCA_Visitor_AliasCV')
		SET @Mercado					= 'I'
		SET @Id_Cliente_Ref				= 0
		SET @Fecha_Alta					= GETDATE()
		SET @Id_Centro_Costo			= ''	--Centro_Costos
		SET @Id_Cond_Vta				= ''	--Cbtes_Cond_Vtas
		SET @Fecha_Modif				= @Fecha_Alta
		SET @Id_Alias_Cta_Cont_Venta_Dol = 0
		SET @Estado_Civil				= ''
		SET @Id_Nacionalidad			= ''	--Tab_Paises
		SET @Id_Cli_Relac				= 0		--Clientes_Relaciones
		SET @Tipo_Persona				= 'A'
		SET @Id_Unid_Negocio			= dbo.CF_xParam('SCA_Visitor_UNegoci')

		SET @CD_ES_Id_Tarjeta			= ''
		/*FIN Asignacion de Variables*/

		CREATE TABLE #RetornoSP
		(ErrorNumber INT,
		ErrorSeverity INT,
		ErrorState INT,
		ErrorProcedure INT,
		ErrorLine INT,
		ErrorMessage VARCHAR(200),
		Id_Cliente INT)

		/*INSERTO Clientes*/
		INSERT INTO #RetornoSP
		EXEC CP_Clientes_Insertar	@Razon_Social,
									@Apellido,
									@Nombre,
									@Sexo,
									@Fecha_Nac,
									@Id_Tipo_Doc,
									@Doc_Nro,
									@Ingresos_Brutos,
									@Direccion,
									@Cp,
									@Id_Pais,
									@Id_Provincia,
									@Provincia_Descrip,
									@Id_Localidad,
									@Localidad_Descrip,
									@Fax,
									@Cuit,
									@Email,
									@Activo,
									@Id_Estado_Cliente,
									@Id_Grupo_Afinidad,
									@Porc_DescEspecial,
									@Id_Lista_Precio,
									@Id_Vendedor,
									@Id_Transportista,
									@Bonif,
									@Id_Cond_Pago,
									@Cred_CtaCte,
									@Cred_ChePro,
									@Cred_CheTer,
									@Id_Iva,
									@CTE,
									@Id_Concepto,
									@Id_Cta_Banco,
									@Id_Zona,
									@Observacion,
									@pId_Cliente_Externo,
									@Id_Transporte,
									@Id_Alias_Cta_Cont_Venta,
									@Mercado,
									@Observa_Fact,
									@Entre_Calle_1 ,
									@Entre_Calle_2 ,
									@Plano_Nro,
									@Plano_Matriz,
									@Id_Cobrador,
									@Id_Motivo_Est,
									@Id_Tipo_Cli,
									@Id_Dep_Fisico,
									@Id_Dep_Logico,
									@Id_Tarjeta,
									@Id_Banco,
									@Tar_Nro ,
									@Tar_Fecha_Vence,
									@Tar_Titular,
									@Direccion_Cob,
									@Cp_Cob,
									@Id_Pais_Cob,
									@Id_Provincia_Cob,
									@Provincia_Descrip_Cob,
									@Id_Localidad_Cob,
									@Localidad_Descrip_Cob,
									@Entre_Calle_1_Cob ,
									@Entre_Calle_2_Cob ,
									@Plano_Nro_Cob,
									@Plano_Matriz_Cob,
									@Fecha_Ven_Trib,
									@Web,
									@pId_Cliente_Ref,
									@Fecha_Alta,
									@Fecha_Baja,
									@Id_Centro_Costo,
									@Id_Promotor,
									@Nombre_Fantasia,
									@Id_Cond_Vta,
									@Id_Puerto,
									@Id_Calle,
									@Nro,
									@Depto,
									@Fecha_Modif,
									@Foto,
									@Latitud ,
									@Longitud ,
									@Id_Calle_Cob,
									@Nro_Cob,
									@Depto_Cob,
									@Latitud_Cob ,
									@Longitud_Cob ,
									@Id_Precio_Especial,
									@Cod_Autoriz_Trib,
									@Id_Alias_Cta_Cont_Venta_Dol,
									@Estado_Civil,
									@Id_Nacionalidad,
									@Id_Cli_Relac,
									@Tipo_Persona,
									@telefono ,
									@Calle_Descrip,
									@Calle_Cob_Descrip,
									@Imp_Aporte,
									@Fecha_Aporte,
									@Credencial_Nro,
									@Credencial_Banda1,
									@Credencial_Banda2,
									@Credencial_Imp,
									@Ult_Cuota_Paga,
									@Legajo,
									@Credencial_Entrega,
									@Id_Unid_Negocio,
									@Clave_Web,
									@Flag_Anmat,
									@Nro_Anmat,
									@Tar_Cuit,
									@Id_Anmat,
									@Coef_Comi_Vta,
									@Coef_Comi_Cobros,
									@Email_Cob,
									@Recorrido_Cob,
									@Tar_Fecha_Alta,
									@Tar_Fecha_Baja,
									@Imp_Fac_Max_Mes,
									@Email_Web,
									@Tel_Movil,
									@Flag_Tel_Movil_Verif,
									@Flag_Comunic_Sms,
									@Flag_Comunic_Email,
									@Carpeta,
									@Id_Emp_Area,
									@Id_AR_ARBA_COT_Tipo_Dom_Nro,
									@Dir_Entrega_Numero,
									@Dir_Entrega_Piso,
									@Dir_Entrega_Dto,
									@Dir_Entrega_Barrio,
									@Dir_Entrega_CP,
									@Dir_Entrega_Localidad,
									@Id_Usuario_Alta									

		SET @Flag_Existe_Patente = (SELECT Id_Cliente FROM #RetornoSP)
	END
	ELSE
	BEGIN
		SET @Mensaje = 'EXISTE'
	END

	IF(@pFlag_GrabaRegistro = 1)
	BEGIN
		SET @CD_ES_Tipo				= 'E' --Entrada
		SET @CD_ES_Origen			= 'M' --Manual
		SET @CD_ES_Id_Tarjeta		= (SELECT ISNULL(Credencial_Nro, '') FROM Clientes WHERE Id_Cliente = @pId_Cliente_Ref)
		SET @CD_ES_Fecha			= GETDATE()
		SET @CD_ES_Resultado		= 'S'

		SET @Id_CD_Motivo			= 0
		SET @Usuario_Alta			= 0
		SET @CD_ES_Id_Controlador	= @pId_Controlador --CD_Controladores

		SET @CD_ES_Id_Acceso		= (SELECT Id_Acceso FROM CD_Controladores WHERE Id_Controlador = @CD_ES_Id_Controlador)
		SET @CD_ES_tipo_reg			= ''

		/*INSERTO CD_ES*/
		INSERT INTO CD_ES
		(Tipo,			Origen,			Id_Tarjeta,
		Id_Cliente,		Fecha,			Resultado,
		Id_Controlador, Id_Acceso,		Observacion,
		tipo_reg,		Id_CD_Motivo,	Flag_Permite_Paso)
		VALUES
		(@CD_ES_Tipo,				@CD_ES_Origen,		@CD_ES_Id_Tarjeta,
		@Flag_Existe_Patente,		@CD_ES_Fecha,		@CD_ES_Resultado,
		@CD_ES_Id_Controlador,		@CD_ES_Id_Acceso,	'INGRESO AUTOMOTOR',
		@CD_ES_tipo_reg,			'205',		0)
	END
	
	COMMIT
	SELECT	 0						AS ErrorNumber 
			,0						AS ErrorSeverity  
			,0						AS ErrorState 
			,0						AS ErrorProcedure  
			,0						AS ErrorLine		
			,@Mensaje				AS ErrorMessage
			,@Flag_Existe_Patente   AS Id_Cliente

END
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH   


/*
EXEC [CP_Clientes_Patente] 0,8783,'ACLQ124',1,22,0
*/
GO


CREATE PROCEDURE [dbo].[CP_Clientes_Temp_Actualizar_Cbte] @LOTE VARCHAR(20) , @Id_Cliente INT
AS

IF EXISTS (SELECT 1 FROM sys.objects WHERE name = 'CP_Clientes_Temp_Actualizar_Cbte_' AND type = 'P')
BEGIN
	EXEC CP_Clientes_Temp_Actualizar_Cbte_ @LOTE, @Id_Cliente 
	RETURN
END

DECLARE @Mensaje			VARCHAR(100)
DECLARE @Titular			INT
DECLARE @GrupoFamiliar		INT

SET @Titular = ISNULL((SELECT Id_Cliente_Temp from clientes_temp where Id_Cliente=@Id_Cliente),0)
SET @GrupoFamiliar = ISNULL((SELECT COUNT(*) from clientes_temp where legajo=CONVERT(VARCHAR(30),@Titular)),0)

IF @Id_Cliente = 0 OR ISNULL(@LOTE,'') = ''
BEGIN
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,'No se especifico cliente o lote'			AS ErrorMessage
	RETURN 
END
BEGIN TRY
	DECLARE @trans_rec INTEGER, @trans_ND INT, @LoteND VARCHAR(20), @LoteRec VARCHAR(20), @Count SMALLINT

	
	SET @LoteND =  @LOTE
	SET @LoteRec = @LOTE

	SET @trans_ND = ISNULL((SELECT MIN(Id_trans) FROM Cbtes WHERE LOTE = @LoteND AND Id_Estado_Cbte in (1,2)),0)
	IF (@trans_ND = 0)
	BEGIN
		PRINT 'No hay trans de Factura'
	END

	SET @trans_rec = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = @LoteRec AND Id_Estado_Cbte in (1,2)),0)
	IF (@trans_rec = 0)
	BEGIN
		PRINT 'No hay trans de recibo'
	END



	BEGIN TRAN

	IF (@trans_ND != 0)
	BEGIN
		UPDATE Clientes_CtaCte	SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_ND 
		UPDATE Cbtes_Items		SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_ND 
		UPDATE Cbtes			SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_ND 
	END

	IF (@trans_rec != 0)
	BEGIN
		UPDATE Clientes_CtaCte	SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_rec 
		UPDATE Cbtes_Items		SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_rec
		UPDATE Cbtes			SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_rec
	END
	
	/*RECORRO MAS DE UNA FACTURA*/
		SET @Count = (SELECT COUNT(Lote) FROM CBTES WHERE LOTE = @LoteND AND Id_Trans <> @trans_rec) 
		IF (@Count > 1)
		BEGIN
			DECLARE @Id_Trans_Count INT

			DECLARE curCount CURSOR FOR
			SELECT Id_Trans FROM CBTES
			WHERE LOTE = @LoteND AND Id_Trans <> @trans_rec

			OPEN curCount
			FETCH NEXT FROM curCount INTO @Id_Trans_Count
			WHILE @@FETCH_STATUS = 0
			BEGIN

				UPDATE Clientes_CtaCte	SET Id_cliente = @Id_Cliente WHERE Id_Trans = @Id_Trans_Count 
				UPDATE Cbtes_Items		SET Id_cliente = @Id_Cliente WHERE Id_Trans = @Id_Trans_Count
				UPDATE Cbtes			SET Id_cliente = @Id_Cliente WHERE Id_Trans = @Id_Trans_Count
		
			FETCH NEXT FROM curCount INTO @Id_Trans_Count
			END
			CLOSE curCount
			DEALLOCATE curCount
			
		END

	/*RECORRO GRUPO FAMILIAR*/
		IF (@GrupoFamiliar>0)
		BEGIN
			DECLARE @Id_Cliente_int		INT
			DECLARE @Id_Cliente_Temp	INT
			DECLARE @Trans_Int			INT
			DECLARE @Item_Int			SMALLINT

			DECLARE curNombre CURSOR FOR
			SELECT C.Id_Trans,T.Id_Cliente, T.Id_Cliente_Temp, I.Item
			FROM Cbtes C
			LEFT JOIN Cbtes_Tipos CT ON C.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
			LEFT JOIN Cbtes_Items I ON C.Id_Trans = I.Id_Trans
			LEFT JOIN Clientes_Temp T ON CONVERT(INT,I.CANTIDAD_EQUIV) = T.Id_Cliente_Temp			
			WHERE CT.Compromete_Factura = 1
			AND C.Lote = @LoteND
			AND Legajo = CONVERT(VARCHAR(30),@Titular)

			OPEN curNombre
			FETCH NEXT FROM curNombre INTO @Trans_Int, @Id_Cliente_int, @Id_Cliente_Temp, @Item_Int
			WHILE @@FETCH_STATUS = 0
			BEGIN

				UPDATE Cbtes_Items SET Id_cliente = @Id_Cliente_int WHERE Id_Trans = @Trans_Int AND CONVERT(INT,Cantidad_Equiv) = @Id_Cliente_Temp AND Item = @Item_Int
				UPDATE Cbtes_Items SET Cantidad_Equiv = 0 WHERE Id_Trans = @Trans_Int
		
			FETCH NEXT FROM curNombre INTO @Trans_Int, @Id_Cliente_int, @Id_Cliente_Temp, @Item_Int
			END
			CLOSE curNombre
			DEALLOCATE curNombre
			
		END
		
		UPDATE Cbtes_Items SET Cantidad_Equiv = 0 WHERE Id_Trans = @trans_ND 
	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage
END TRY  

BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_Clientes_Temp_Actualizar_Cbte_] @LOTE VARCHAR(20) , @Id_Cliente INT
AS

/*

TC. 20260330 - Se crea CP_Clientes_Temp_Actualizar_Cbte_

Log de cambios:
TC. 20260330 - Cambia el producto CS por matricula (1196) cuando se asocia como 'ALUMNO PROFESORADO - MATRÍCULA DE INSCRIPCIÓN'
*/

DECLARE @Mensaje			VARCHAR(100)
DECLARE @Titular			INT
DECLARE @GrupoFamiliar		INT
DECLARE @Id_Tipo_Cli_Temp	SMALLINT

SET @Titular = ISNULL((SELECT Id_Cliente_Temp from clientes_temp where Id_Cliente=@Id_Cliente),0)
SET @GrupoFamiliar = ISNULL((SELECT COUNT(*) from clientes_temp where legajo=CONVERT(VARCHAR(30),@Titular)),0)
SET @Id_Tipo_Cli_Temp = ISNULL((SELECT Id_Tipo_Cli from clientes_temp where Id_Cliente=@Id_Cliente),0)

IF @Id_Cliente = 0 OR ISNULL(@LOTE,'') = ''
BEGIN
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,'No se especifico cliente o lote'			AS ErrorMessage
	RETURN 
END
BEGIN TRY
	DECLARE @trans_rec INTEGER, @trans_ND INT, @LoteND VARCHAR(20), @LoteRec VARCHAR(20), @Count SMALLINT

	
	SET @LoteND =  @LOTE
	SET @LoteRec = @LOTE

	SET @trans_ND = ISNULL((SELECT MIN(Id_trans) FROM Cbtes WHERE LOTE = @LoteND AND Id_Estado_Cbte in (1,2)),0)
	IF (@trans_ND = 0)
	BEGIN
		PRINT 'No hay trans de Factura'
	END

	SET @trans_rec = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = @LoteRec AND Id_Estado_Cbte in (1,2)),0)
	IF (@trans_rec = 0)
	BEGIN
		PRINT 'No hay trans de recibo'
	END



	BEGIN TRAN

	IF (@trans_ND != 0)
	BEGIN
		UPDATE Clientes_CtaCte	SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_ND 
		UPDATE Cbtes_Items		SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_ND 
		UPDATE Cbtes			SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_ND 
		
		-- Actualiza producto a Matricula
		IF(@Id_Tipo_Cli_Temp = 1127)
		BEGIN
			UPDATE Cbtes_Items SET Id_Producto = '1196' WHERE Id_Trans = @trans_ND AND Id_Producto = 'CS'
		END
	END

	IF (@trans_rec != 0)
	BEGIN
		UPDATE Clientes_CtaCte	SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_rec 
		UPDATE Cbtes_Items		SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_rec
		UPDATE Cbtes			SET Id_cliente = @Id_Cliente WHERE Id_Trans = @trans_rec
	END
	
	/*RECORRO MAS DE UNA FACTURA*/
		SET @Count = (SELECT COUNT(Lote) FROM CBTES WHERE LOTE = @LoteND AND Id_Trans <> @trans_rec) 
		IF (@Count > 1)
		BEGIN
			DECLARE @Id_Trans_Count INT

			DECLARE curCount CURSOR FOR
			SELECT Id_Trans FROM CBTES
			WHERE LOTE = @LoteND AND Id_Trans <> @trans_rec

			OPEN curCount
			FETCH NEXT FROM curCount INTO @Id_Trans_Count
			WHILE @@FETCH_STATUS = 0
			BEGIN

				UPDATE Clientes_CtaCte	SET Id_cliente = @Id_Cliente WHERE Id_Trans = @Id_Trans_Count 
				UPDATE Cbtes_Items		SET Id_cliente = @Id_Cliente WHERE Id_Trans = @Id_Trans_Count
				UPDATE Cbtes			SET Id_cliente = @Id_Cliente WHERE Id_Trans = @Id_Trans_Count
				
				-- Actualiza producto a Matricula
				IF(@Id_Tipo_Cli_Temp = 1127)
				BEGIN
					UPDATE Cbtes_Items SET Id_Producto = '1196' WHERE Id_Trans = @Id_Trans_Count AND Id_Producto = 'CS'
				END
		
			FETCH NEXT FROM curCount INTO @Id_Trans_Count
			END
			CLOSE curCount
			DEALLOCATE curCount
			
		END

	/*RECORRO GRUPO FAMILIAR*/
		IF (@GrupoFamiliar>0)
		BEGIN
			DECLARE @Id_Cliente_int		INT
			DECLARE @Id_Cliente_Temp	INT
			DECLARE @Trans_Int			INT
			DECLARE @Item_Int			SMALLINT
			DECLARE @Id_Tipo_Cli_Int	SMALLINT

			DECLARE curNombre CURSOR FOR
			SELECT C.Id_Trans,T.Id_Cliente, T.Id_Cliente_Temp, I.Item, ISNULL(T.Id_Tipo_Cli, 0) AS Id_Tipo_Cli
			FROM Cbtes C
			LEFT JOIN Cbtes_Tipos CT ON C.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
			LEFT JOIN Cbtes_Items I ON C.Id_Trans = I.Id_Trans
			LEFT JOIN Clientes_Temp T ON CONVERT(INT,I.CANTIDAD_EQUIV) = T.Id_Cliente_Temp			
			WHERE CT.Compromete_Factura = 1
			AND C.Lote = @LoteND
			AND Legajo = CONVERT(VARCHAR(30),@Titular)

			OPEN curNombre
			FETCH NEXT FROM curNombre INTO @Trans_Int, @Id_Cliente_int, @Id_Cliente_Temp, @Item_Int, @Id_Tipo_Cli_Int
			WHILE @@FETCH_STATUS = 0
			BEGIN

				UPDATE Cbtes_Items SET Id_cliente = @Id_Cliente_int WHERE Id_Trans = @Trans_Int AND CONVERT(INT,Cantidad_Equiv) = @Id_Cliente_Temp AND Item = @Item_Int
				UPDATE Cbtes_Items SET Cantidad_Equiv = 0 WHERE Id_Trans = @Trans_Int
				
				-- Actualiza producto a Matricula
				IF(@Id_Tipo_Cli_Int = 1127)
				BEGIN
					UPDATE Cbtes_Items SET Id_Producto = '1196' WHERE Id_Trans = @Trans_Int AND Id_Producto = 'CS'
				END
		
			FETCH NEXT FROM curNombre INTO @Trans_Int, @Id_Cliente_int, @Id_Cliente_Temp, @Item_Int, @Id_Tipo_Cli_Int
			END
			CLOSE curNombre
			DEALLOCATE curNombre
			
		END
		
		UPDATE Cbtes_Items SET Cantidad_Equiv = 0 WHERE Id_Trans = @trans_ND 
	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage
END TRY  

BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO

CREATE PROCEDURE [dbo].[CP_Clientes_Temp_Alta] (
	@Id_Cliente					INT,
	@Fecha						DATETIME,	
	@Id_Tipo_Cli				SMALLINT,		
    @Apellido					VARCHAR(100),
	@Nombre						VARCHAR(100), 
	@Sexo						CHAR(1),
	@Estado_Civil				CHAR(1),
	@Fecha_Nac					DATETIME,
	@Id_Tipo_Doc				CHAR(3),
    @Doc_Nro					VARCHAR(20),
    @Direccion 					VARCHAR(100),
    @Cp 						VARCHAR(10),
    @Id_Pais 					CHAR(3),
    @Id_Provincia 				CHAR(3),
    @Provincia_Descrip 			VARCHAR(200),
    @Id_Localidad 				SMALLINT,
    @Localidad_Descrip 			VARCHAR(200),
    @Id_Nacionalidad 			CHAR(3),
	@Email 						VARCHAR(300),
    @telefono					VARCHAR(20),
    @Tel_Movil					VARCHAR(20),		
	@Nro_Trans_Pago				VARCHAR(100),
	@pImporte_CS				DECIMAL(12,2),
	@pImporte_GA				DECIMAL(12,2),
	@pImporte_GE				DECIMAL(12,2),
	@Legajo						VARCHAR(30),
	@Json						TEXT,
	@Hash						VARCHAR(32),
	@Observacion				TEXT = NULL,
	@Id_Cli_Relac				INT = NULL
	) 

AS
 
DECLARE @Razon_Social		VARCHAR(100)
DECLARE	@Id_Cliente_Temp	INT
DECLARE @Mensaje			VARCHAR(100)


BEGIN TRY
BEGIN TRAN

SET @Razon_Social=		@Apellido+ ' '	+	@Nombre 
SET @Id_Cliente_Temp =	(SELECT (ISNULL(MAX(Id_Cliente_Temp),0)+1) FROM Clientes_Temp) 

INSERT INTO Clientes_Temp
					(Id_Cliente, Fecha,			Id_Tipo_Cli,	Razon_Social,		Apellido,		
					Nombre , 			Sexo,	
					Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc,		Doc_Nro,		Direccion,	
					Cp ,				Id_Pais,		Id_Provincia,
					Provincia_Descrip,	Id_Localidad ,  Localidad_Descrip,					Id_Nacionalidad,
					Email,				telefono,		Tel_Movil,			Importe_CS,	
					Nro_Trans_Pago,		Legajo,			Importe_GA,			Importe_GE,		Json,	[Hash],Observacion,
					Id_Cli_Relac)
		VALUES    
				  ( @Id_Cliente, 	@fecha,			@Id_Tipo_Cli,	@Razon_Social,		@Apellido,		
					@Nombre, 			@Sexo,	
					@Estado_Civil,		@Fecha_Nac,		@Id_Tipo_Doc,		@Doc_Nro ,		@Direccion,	
					@Cp ,			@Id_Pais,			@Id_Provincia,
					@Provincia_Descrip, @Id_Localidad,  @Localidad_Descrip ,				@Id_Nacionalidad,
					@Email,				@telefono,		@Tel_Movil,			@pImporte_CS,	
					@Nro_Trans_Pago,	@Legajo,		@pImporte_GA,		@pImporte_GE,	@Json,	@Hash,@Observacion,
					@Id_Cli_Relac)

	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage
			,@Id_Cliente_Temp	AS Id_Cliente_Temp 
			,@Razon_Social		AS Razon_Social

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_Clientes_Temp_Aprobar] @Id_Cliente_Temp INT,  @Id_Tipo_Cli INT 
AS

IF EXISTS (SELECT 1 FROM sys.objects WHERE name = 'CP_Clientes_Temp_Aprobar_' AND type = 'P')
BEGIN
		EXEC CP_Clientes_Temp_Aprobar_ @Id_Cliente_Temp, @Id_Tipo_Cli
		RETURN
END

DECLARE @Id_Unid_Negocio	VARCHAR(10)
DECLARE @Id_Cliente			INT
DECLARE @Categoria			INT
DECLARE @Nota_Part1			VARCHAR(10)
DECLARE @Direccion			VARCHAR(100)
DECLARE @Nro				INT
DECLARE @Piso				VARCHAR(10)
DECLARE	@Depto				VARCHAR(10)
DECLARE @DireccionTotal		VARCHAR(100)
DECLARE @Observacion		VARCHAR(100)
DECLARE @Razon_Social		VARCHAR(100)
DECLARE @Id_Concepto		INT
DECLARE @Id_Alias_Cta_Cont_Venta	SMALLINT
DECLARE @Mensaje			VARCHAR(100)
DECLARE @Lote				VARCHAR(100)
DECLARE @Id_IVA				CHAR(3)
DECLARE @Tipo_Persona		CHAR(1)
DECLARE @Id_Cond_Pago		SMALLINT
DECLARE @Id_Lista_Precio	SMALLINT
DECLARE @Foto				INT
DECLARE @GrupoFamiliar		INT
DECLARE @Id_Nacionalidad	CHAR(3)
DECLARE @Id_Cliente_Titular	INT
BEGIN TRY
	BEGIN TRAN
	SET @GrupoFamiliar = ISNULL((SELECT COUNT(*) from clientes_temp where legajo=@Id_Cliente_Temp),0)
	SET @Id_Alias_Cta_Cont_Venta	= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Alias_Cta_Cont_Venta','A')
	SET @Id_Concepto				= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Concepto','A')
	SET @Id_Unid_Negocio			= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Unid_Negocio','A')
	SET @Id_IVA						= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_IVA','A')
	SET @Tipo_Persona				= 'F'
	SET @Id_Cond_Pago				= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Cond_Pago','A')
	SET @Id_Lista_Precio			= 12
	SET @Id_Nacionalidad			='ARG'

	
	IF(@Id_Tipo_Cli=0)
	BEGIN 
	 SET @Id_Tipo_Cli = (Select Id_Tipo_Cli from Clientes_Temp where Id_Cliente_Temp=@Id_Cliente_Temp)
	END 
	
	
    SET @Id_Cliente = ISNULL((SELECT Id_Cliente FROM Clientes_Temp WHERE Id_Cliente_Temp=@Id_Cliente_Temp),0)
	SET @Nro =			(Select Nro			from Clientes_Temp where Id_Cliente_Temp=@Id_Cliente_Temp)
	SET @Depto =		(Select Depto		from Clientes_Temp where Id_Cliente_Temp=@Id_Cliente_Temp)
	SET @Direccion =	(Select Direccion	from Clientes_Temp where Id_Cliente_Temp=@Id_Cliente_Temp)
	SET @DireccionTotal =	@Direccion+ ' ' + CONVERT(VARCHAR (10),@Nro) + ' Piso '  + ' Depto ' + @Depto

	IF @Id_Cliente = 0
	BEGIN
		SET @Id_Cliente		= ISNULL((SELECT (MAX(ID_CLIENTE)+1) FROM Clientes),2)
		SET @Razon_Social	= (Select Razon_Social	from Clientes_Temp where Id_Cliente_Temp=@Id_Cliente_Temp)
		SET @Observacion	= CONVERT(VARCHAR (10), @Id_Cliente_Temp) + 'Nro De Pago ' +  ISNULL(CONVERT(VARCHAR (10),@Lote),'')
		
	

		INSERT INTO Clientes	(Id_Cliente,	Activo,		Razon_Social,		Apellido,		
								Nombre,			Sexo,		Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc, 
								Doc_Nro,		Direccion, 	Cp,					Id_Pais,		Id_Provincia,
								Provincia_Descrip, Id_Localidad, Localidad_Descrip,	Id_Nacionalidad, Email, 
								telefono,		Tel_Movil,	Id_estado_cliente,	Id_Lista_Precio,Id_Cond_Pago, 
								Id_Iva,			Id_Concepto, Id_Alias_Cta_Cont_Venta,				Mercado,		Id_Tipo_Cli, 
								Id_Pais_Cob,	Fecha_Alta, Tipo_Persona,		Id_Unid_Negocio, Observacion,
								Id_Cli_Relac)
					select		@Id_Cliente,		1,		UPPER(Razon_Social),		UPPER(Apellido),		
								UPPER(Nombre),		Sexo,		Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc, 
								Doc_Nro,		@DireccionTotal, Cp,			Id_Pais,		Id_Provincia,
								Provincia_Descrip, Id_Localidad, Localidad_Descrip, @Id_Nacionalidad, Email, 
								telefono,		Tel_Movil,	0,					@Id_Lista_Precio,		@Id_Cond_Pago,				
								@Id_IVA,		@Id_Concepto,@Id_Alias_Cta_Cont_Venta,				'A',			@Id_Tipo_Cli,	
								Id_Pais,		GETDATE(),	@Tipo_Persona,		@Id_Unid_Negocio, @Observacion,
								Id_Cli_Relac
								from  Clientes_Temp WHERE id_cliente_temp=@Id_Cliente_Temp
	
		UPDATE Clientes_Temp SET Id_Cliente = @Id_Cliente WHERE id_cliente_temp=@Id_Cliente_Temp
		
		SET @Id_Cliente_Titular= @Id_Cliente
		
		DELETE FROM Clientes_Fotos WHERE Id_Cliente=@Id_Cliente
		
		INSERT INTO Clientes_Fotos (Id_Cliente, Nro, Foto,Fecha) 
			SELECT TOP 1 @Id_Cliente, 1, Documento,GETDATE() From Clientes_Temp_Doc 
				WHERE Id_Cliente_Temp=@Id_Cliente_Temp AND Descripcion='FotoP'
				
		/*RECORRO GRUPO FAMILIAR*/
		IF (@GrupoFamiliar>0)
		BEGIN
			DECLARE @Integrante INT

			DECLARE curNombre CURSOR FOR
			SELECT CL.Id_Cliente_Temp FROM Clientes_Temp CL
			WHERE
			Legajo= @Id_Cliente_Temp

			OPEN curNombre
			FETCH NEXT FROM curNombre INTO @Integrante
			WHILE @@FETCH_STATUS = 0
			BEGIN

		SET @Id_Cliente		= ISNULL((SELECT (MAX(ID_CLIENTE)+1) FROM Clientes),2)
		SET @Razon_Social	= (Select Razon_Social	from Clientes_Temp where Id_Cliente_Temp=@Integrante)
		SET @Observacion	= CONVERT(VARCHAR (10), @Id_Cliente_Temp) + 'Nro De Pago ' +  ISNULL(CONVERT(VARCHAR (10),@Lote),'')
		
	

		INSERT INTO Clientes	(Id_Cliente,	Activo,		Razon_Social,		Apellido,		
								Nombre,			Sexo,		Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc, 
								Doc_Nro,		Direccion, 	Cp,					Id_Pais,		Id_Provincia,
								Provincia_Descrip, Id_Localidad, Localidad_Descrip,	Id_Nacionalidad, Email, 
								telefono,		Tel_Movil,	Id_estado_cliente,	Id_Lista_Precio,Id_Cond_Pago, 
								Id_Iva,			Id_Concepto, Id_Alias_Cta_Cont_Venta,				Mercado,		Id_Tipo_Cli, 
								Id_Pais_Cob,	Fecha_Alta, Tipo_Persona,		Id_Unid_Negocio, Observacion,
								Id_Cli_Relac, Id_Cliente_Ref)
					select		@Id_Cliente,		1,		UPPER(Razon_Social),		UPPER(Apellido),		
								UPPER(Nombre),		Sexo,		Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc, 
								Doc_Nro,		@DireccionTotal, Cp,			Id_Pais,		Id_Provincia,
								Provincia_Descrip, Id_Localidad, Localidad_Descrip, Id_Nacionalidad, Email, 
								telefono,		Tel_Movil,	0,					@Id_Lista_Precio,		@Id_Cond_Pago,				
								@Id_IVA,		@Id_Concepto,@Id_Alias_Cta_Cont_Venta,				'A',			@Id_Tipo_Cli,	
								Id_Pais,		GETDATE(),	@Tipo_Persona,		@Id_Unid_Negocio, @Observacion,
								Id_Cli_Relac, @Id_Cliente_Titular
								from  Clientes_Temp WHERE id_cliente_temp=@Integrante
	
		UPDATE Clientes_Temp SET Id_Cliente = @Id_Cliente WHERE id_cliente_temp=@Integrante
		
		DELETE FROM Clientes_Fotos WHERE Id_Cliente=@Id_Cliente
		
		INSERT INTO Clientes_Fotos (Id_Cliente, Nro, Foto,Fecha) 
			SELECT TOP 1 @Id_Cliente, 1, Documento,GETDATE() From Clientes_Temp_Doc 
				WHERE Id_Cliente_Temp=@Integrante AND Descripcion='FotoP'

			FETCH NEXT FROM curNombre INTO @Integrante
			END
			CLOSE curNombre
			DEALLOCATE curNombre
		END 
	END
	ELSE
	BEGIN
		UPDATE Clientes 
				SET Razon_Social		= ct.Razon_Social, 
					Apellido			= ct.Apellido ,
					Nombre				= ct.Nombre ,
					Sexo				= ct.Sexo ,
					Estado_Civil		= ct.Estado_Civil ,
					Fecha_Nac			= ct.Fecha_Nac ,
					Id_Tipo_Doc			= ct.Id_Tipo_Doc, 
					Doc_Nro				= ct.Doc_Nro ,
					Direccion			= ct.Direccion, 
					Cp					= ct.Cp ,
					Id_Pais				= ct.Id_Pais, 
					Id_Provincia		= ct.Id_Provincia, 
					Provincia_Descrip	= ct.Provincia_Descrip, 
					Id_Localidad		= ct.Id_Localidad,
					Localidad_Descrip	= ct.Localidad_Descrip, 
					Id_Nacionalidad		= ct.Id_Nacionalidad, 
					Email_Web			= ct.Email ,
					Email				= ct.Email ,
					telefono			= ct.telefono ,
					Tel_Movil			= ct.Tel_Movil ,
					Id_Cli_Relac		= ct.Id_Cli_Relac,
					Id_Facebook			= ct.Id_Facebook, 
					Id_Instagram		= ct.Id_Instagram, 
					Id_Twitter			= ct.Id_Twitter ,
					Id_Linkedin			= ct.Id_Linkedin ,
					Id_Google			= ct.Id_Google ,
					Id_Microsoft		= ct.Id_Microsoft
				FROM 
					Clientes cl, Clientes_Temp ct
				WHERE 
					cl.Id_Cliente=@Id_Cliente
					and ct.id_cliente_temp=@Id_Cliente_Temp
			
		 SET @Foto =ISNULL((SELECT Id_Cliente_Temp FROM Clientes_Temp_Doc WHERE Id_Cliente_Temp=@Id_Cliente_Temp AND Descripcion='FotoP'),0)

		 IF @Foto<>0
		 BEGIN
		 
			DELETE FROM Clientes_Fotos WHERE Id_Cliente=@Id_Cliente
		
			INSERT INTO Clientes_Fotos (Id_Cliente, Nro, Foto,Fecha) 
				SELECT TOP 1 @Id_Cliente, 1, Documento,GETDATE() From Clientes_Temp_Doc 
					WHERE Id_Cliente_Temp=@Id_Cliente_Temp AND Descripcion='FotoP'
		 END
	END

	UPDATE Clientes_Temp SET Id_Estado_Solicitud = 'A' WHERE id_cliente_temp=@Id_Cliente_Temp
	SET @Lote = (SELECT ISNULL(Nro_Trans_Pago,'') FROM Clientes_Temp WHERE id_cliente_temp=@Id_Cliente_Temp)
	
	COMMIT
	IF @Lote<>''
	BEGIN
	EXEC CP_Clientes_Temp_Actualizar_Cbte @Lote, @Id_Cliente

	IF EXISTS (SELECT 1 FROM sys.objects WHERE name = 'CP_Clientes_Temp_Aprobar_After' AND type = 'P')
		EXEC CP_Clientes_Temp_Aprobar_After @Id_Cliente_Temp

	SELECT	 0			AS ErrorNumber 
			,0			AS ErrorSeverity  
			,0			AS ErrorState 
			,0			AS ErrorProcedure  
			,0			AS ErrorLine		
			,@Mensaje	AS ErrorMessage	
	END 

END TRY  
	

BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_Clientes_Temp_Aprobar_] @Id_Cliente_Temp INT,  @Id_Tipo_Cli INT 
AS


DECLARE @Id_Unid_Negocio			VARCHAR(10)
DECLARE @Id_Cliente					INT
DECLARE @Categoria					INT
DECLARE @Nota_Part1					VARCHAR(10)
DECLARE @Direccion					VARCHAR(100)
DECLARE @Nro						INT
DECLARE @Piso						VARCHAR(10)
DECLARE	@Depto						VARCHAR(10)
DECLARE @DireccionTotal				VARCHAR(100)
DECLARE @Observacion				VARCHAR(100)
DECLARE @Razon_Social				VARCHAR(100)
DECLARE @Id_Concepto				INT
DECLARE @Id_Alias_Cta_Cont_Venta	SMALLINT
DECLARE @Mensaje					VARCHAR(100)
DECLARE @Lote						VARCHAR(100)
DECLARE @Id_IVA						CHAR(3)
DECLARE @Tipo_Persona				CHAR(1)
DECLARE @Id_Cond_Pago				SMALLINT
DECLARE @Id_Lista_Precio			SMALLINT
DECLARE @Foto						INT
DECLARE @GrupoFamiliar				INT
DECLARE @Id_Nacionalidad			CHAR(3)
DECLARE @Id_Cliente_Titular			INT
DECLARE @Id_Tarjeta					VARCHAR(10)
DECLARE @Cantidad_GF				INT
DECLARE @Tar_Nro					VARCHAR(25)
DECLARE @Pago						CHAR(1)
DECLARE @Id_Pais					CHAR(3)
DECLARE @Id_Provincia				CHAR (3)
DECLARE @Id_Localidad				SMALLINT
DECLARE @Localidad_Tmp				VARCHAR(25)
DECLARE @Id_Localidad_Existe		SMALLINT
DECLARE @Id_Provincia_Temp			CHAR (3)
DECLARE @Id_Localidad_Temp			SMALLINT
DECLARE @Id_Pais_Temp				CHAR (3)



BEGIN TRY
	BEGIN TRAN
	SET @GrupoFamiliar = ISNULL((SELECT COUNT(*) from clientes_temp where legajo=CONVERT(VARCHAR(30),@Id_Cliente_Temp)),0)
	SET @Id_Alias_Cta_Cont_Venta	= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Alias_Cta_Cont_Venta','A')
	SET @Id_Concepto				= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Concepto','A')
	SET @Id_Unid_Negocio			= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Unid_Negocio','A')
	SET @Id_IVA						= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_IVA','A')
	SET @Tipo_Persona				= 'F'
	SET @Id_Cond_Pago				= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Cond_Pago','A')
	SET @Id_Lista_Precio			= 222--12
	SET @Id_Nacionalidad			='ARG'
	
	
	
	IF(@Id_Tipo_Cli=0)
	BEGIN 
	 SET @Id_Tipo_Cli = (Select Id_Tipo_Cli from Clientes_Temp where Id_Cliente_Temp=@Id_Cliente_Temp)
	END 
	
	
    SET @Id_Cliente = ISNULL((SELECT Id_Cliente FROM Clientes_Temp WHERE Id_Cliente_Temp=@Id_Cliente_Temp),0)
	SET @Direccion =	(Select Direccion	from Clientes_Temp where Id_Cliente_Temp=@Id_Cliente_Temp)
	SET @DireccionTotal =	@Direccion
	
	
	IF @Id_Cliente = 0
	BEGIN
		SET @Id_Cliente		= ISNULL((SELECT (MAX(ID_CLIENTE)+1) FROM Clientes),2)
		SET @Razon_Social	= (Select Razon_Social	from Clientes_Temp where Id_Cliente_Temp=@Id_Cliente_Temp)
		SET @Observacion	= CONVERT(VARCHAR (10), @Id_Cliente_Temp) + 'Nro De Pago ' +  ISNULL(CONVERT(VARCHAR (10),@Lote),'')
		SET @Pago				= (SELECT ISNULL(Flag_Pago,'') FROM Clientes_Temp WHERE Id_Cliente_Temp=@Id_Cliente_Temp)

	SELECT  @Id_Localidad_Temp =  ISNULL(Id_Localidad,0),
			@Id_Provincia_Temp =  ISNULL(Id_Provincia,''),
			@Id_Pais_Temp	   =  ISNULL(Id_Pais,'')
	FROM  Clientes_Temp 
	WHERE Id_Cliente_Temp = @Id_Cliente_Temp
	
	IF (@Id_Localidad_Temp = 0 AND @Id_Provincia_Temp='')
	BEGIN
		SET @Id_Provincia_Temp = (SELECT ISNULL(MAX(Id_Provincia),'') FROM Tab_Provincias WHERE Id_Pais=@Id_Pais_Temp )
		SET @Id_Localidad_Temp = (SELECT ISNULL(MAX(Id_Localidad),0) FROM Tab_Localidades WHERE Id_Pais=@Id_Pais_Temp AND Id_Provincia=@Id_Provincia_Temp)
	END

	IF (@Id_Localidad_Temp = 0 AND @Id_Provincia_Temp <> '')
	BEGIN
		SET @Id_Localidad_Temp = (SELECT TOP 1 Id_Localidad FROM Tab_Localidades WHERE Id_Pais=@Id_Pais_Temp AND Id_Provincia=@Id_Provincia_Temp)
	END

	PRINT 'Pais ' + @Id_Pais_Temp + '-- Provincia ' + @Id_Provincia_Temp + '-- Localidad ' + CONVERT(VARCHAR (10),@Id_Localidad_Temp)

	SET @Id_Localidad_Existe = ISNULL((select Id_Localidad from Tab_Localidades l, Tab_Provincias pr, Tab_Paises p where
										p.Id_Pais = pr.Id_Pais
										and pr.Id_Provincia = l.Id_Provincia
										and Id_Localidad = @Id_Localidad_Temp and pr.Id_Provincia = @Id_Provincia_Temp 
										and p.Id_Pais = @Id_Pais_Temp),0)
	
	IF (@Pago='P')
	PRINT 'Pais ' + @Id_Pais_Temp + '-- Provincia ' + @Id_Provincia_Temp + '-- Localidad ' + CONVERT(VARCHAR (10),@Id_Localidad_Temp)
	BEGIN
		IF (@Id_Localidad_Existe = 0)
		BEGIN
			DECLARE @Json_Pais VARCHAR(8000)

			SET @Json_Pais='{'
			SET @Json_Pais = @Json_Pais +	dbo.CF_Json_ParsearVariable ('Id_Pais', @Id_Pais_Temp, 'CHAR(3)')
			SET @Json_Pais = @Json_Pais + '}'

				CREATE TABLE #respuesta (Valor VARCHAR(8000))
				INSERT INTO #respuesta	EXEC [CPJ_Clientes_Localidad] @Json_Pais

				SET @Json_Pais = (SELECT Valor FROM #respuesta)

				SET @Id_Localidad			= ISNULL(CONVERT(SMALLINT, dbo.CF_JSON_VALUE(@Json_Pais,'Id_Localidad')), 0)
				SET @Id_Provincia			= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@Json_Pais,'Id_Provincia')), '')
				

				DROP TABLE #respuesta
		END 
		ELSE
			BEGIN
					SET @Id_Provincia			= @Id_Provincia_Temp
					SET @Id_Localidad			= @Id_Localidad_Temp
			END


		SET @Tar_Nro		=(Select debito_automatico	from Clientes_Temp where Id_Cliente_Temp=@Id_Cliente_Temp)
		SET @Id_Tarjeta		=(Select debito_automatico_id_tarjeta	from Clientes_Temp where Id_Cliente_Temp=@Id_Cliente_Temp)


		INSERT INTO Clientes	(Id_Cliente,	Activo,		Razon_Social,		Apellido,		
								Nombre,			Sexo,		Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc, 
								Doc_Nro,		Direccion, 	Cp,					Id_Pais,		Id_Provincia,
								Provincia_Descrip, Id_Localidad, Localidad_Descrip,	Id_Nacionalidad, Email, 
								telefono,		Tel_Movil,	Id_estado_cliente,	Id_Lista_Precio,Id_Cond_Pago, 
								Id_Iva,			Id_Concepto, Id_Alias_Cta_Cont_Venta,				Mercado,		Id_Tipo_Cli, 
								Id_Pais_Cob,	Fecha_Alta, Tipo_Persona,		Id_Unid_Negocio, Observacion,
								Id_Cli_Relac,	Id_Cond_Vta)
					select		@Id_Cliente,		1,		UPPER(Razon_Social),		UPPER(Apellido),		
								UPPER(Nombre),		Sexo,		Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc, 
								Doc_Nro,		@DireccionTotal, Cp,			Id_Pais,		@Id_Provincia,
								Provincia_Descrip, @Id_Localidad, Localidad_Descrip, @Id_Nacionalidad, Email, 
								telefono,		Tel_Movil,	0,					@Id_Lista_Precio,		@Id_Cond_Pago,				
								@Id_IVA,		@Id_Concepto,@Id_Alias_Cta_Cont_Venta,				'A',			@Id_Tipo_Cli,	
								Id_Pais,		GETDATE(),	@Tipo_Persona,		@Id_Unid_Negocio, @Observacion,
								Id_Cli_Relac, 'NO'
								from  Clientes_Temp WHERE id_cliente_temp=@Id_Cliente_Temp
	
		UPDATE Clientes_Temp SET Id_Cliente = @Id_Cliente WHERE id_cliente_temp=@Id_Cliente_Temp
		
		SET @Id_Cliente_Titular = @Id_Cliente
		
		DELETE FROM Clientes_Fotos WHERE Id_Cliente=@Id_Cliente
		
		INSERT INTO Clientes_Fotos (Id_Cliente, Nro, Foto,Fecha) 
			SELECT TOP 1 @Id_Cliente, 1, Documento,GETDATE() From Clientes_Temp_Doc 
				WHERE Id_Cliente_Temp=@Id_Cliente_Temp AND Descripcion='FotoP'
		
		
				
		DELETE FROM Clientes_Doc WHERE Id_Cliente=@Id_Cliente
		
			INSERT INTO Clientes_Doc (Id_Cliente, Item, Descripcion, Fecha, Extension,Documento) 
			SELECT  @Id_Cliente, Item, Descripcion, GETDATE(), Extension,Documento 
					From Clientes_Temp_Doc 
				WHERE Id_Cliente_Temp=@Id_Cliente_Temp 
		
		UPDATE CONTRATOS SET Tar_nro=@Tar_Nro ,id_tarjeta=@Id_Tarjeta WHERE Id_Cliente = @Id_Cliente AND Id_Tipo_Con=1 	
				
		SET @Cantidad_GF	=1	
		/*RECORRO GRUPO FAMILIAR*/
		IF (@GrupoFamiliar>0)
		BEGIN
		SET @Cantidad_GF= @Cantidad_GF + 1
			DECLARE @Integrante INT

			DECLARE curNombre CURSOR FOR
			SELECT CL.Id_Cliente_Temp FROM Clientes_Temp CL
			WHERE
			Legajo= @Id_Cliente_Temp

			OPEN curNombre
			FETCH NEXT FROM curNombre INTO @Integrante
			WHILE @@FETCH_STATUS = 0
			BEGIN

		SET @Id_Cliente		= ISNULL((SELECT (MAX(ID_CLIENTE)+1) FROM Clientes),2)
		SET @Id_Tipo_Cli = (Select Id_Tipo_Cli from Clientes_Temp where Id_Cliente_Temp=@Integrante)
		SET @Razon_Social	= (Select Razon_Social	from Clientes_Temp where Id_Cliente_Temp=@Integrante)
		SET @Observacion	= CONVERT(VARCHAR (10), @Id_Cliente_Temp) + 'Nro De Pago ' +  ISNULL(CONVERT(VARCHAR (10),@Lote),'')
		
	

		INSERT INTO Clientes	(Id_Cliente,	Activo,		Razon_Social,		Apellido,		
								Nombre,			Sexo,		Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc, 
								Doc_Nro,		Direccion, 	Cp,					Id_Pais,		Id_Provincia,
								Provincia_Descrip, Id_Localidad, Localidad_Descrip,	Id_Nacionalidad, Email, 
								telefono,		Tel_Movil,	Id_estado_cliente,	Id_Lista_Precio,Id_Cond_Pago, 
								Id_Iva,			Id_Concepto, Id_Alias_Cta_Cont_Venta,				Mercado,		Id_Tipo_Cli, 
								Id_Pais_Cob,	Fecha_Alta, Tipo_Persona,		Id_Unid_Negocio, Observacion,
								Id_Cli_Relac,	Id_Cliente_Ref, Id_Cond_Vta)
					select		@Id_Cliente,		1,		UPPER(Razon_Social),		UPPER(Apellido),		
								UPPER(Nombre),		Sexo,		Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc, 
								Doc_Nro,		@DireccionTotal, Cp,			Id_Pais,		@Id_Provincia,
								Provincia_Descrip, @Id_Localidad, Localidad_Descrip, Id_Nacionalidad, Email, 
								telefono,		Tel_Movil,	0,					@Id_Lista_Precio,		@Id_Cond_Pago,				
								@Id_IVA,		@Id_Concepto,@Id_Alias_Cta_Cont_Venta,				'A',			@Id_Tipo_Cli,	
								Id_Pais,		GETDATE(),	@Tipo_Persona,		@Id_Unid_Negocio, @Observacion,
								Id_Cli_Relac, @Id_Cliente_Titular, 'NO'
								from  Clientes_Temp WHERE id_cliente_temp=@Integrante
	
		UPDATE Clientes_Temp SET Id_Cliente = @Id_Cliente WHERE id_cliente_temp=@Integrante
		
		DELETE FROM Clientes_Fotos WHERE Id_Cliente=@Id_Cliente
		
		INSERT INTO Clientes_Fotos (Id_Cliente, Nro, Foto,Fecha) 
			SELECT TOP 1 @Id_Cliente, 1, Documento,GETDATE() From Clientes_Temp_Doc 
				WHERE Id_Cliente_Temp=@Integrante AND Descripcion='FotoP_'+CONVERT(varchar(2),@Cantidad_GF)
				
				
			
		DELETE FROM Clientes_Doc WHERE Id_Cliente=@Id_Cliente
		
			INSERT INTO Clientes_Doc (Id_Cliente, Item, Descripcion, Fecha, Extension,Documento) 
			SELECT  @Id_Cliente, Item, Descripcion, GETDATE(), Extension,Documento 
					From Clientes_Temp_Doc 
				WHERE Id_Cliente_Temp=@Integrante 

			FETCH NEXT FROM curNombre INTO @Integrante
			END
			CLOSE curNombre
			DEALLOCATE curNombre
		END
	END 
	END
	ELSE
	BEGIN
		UPDATE Clientes 
				SET Razon_Social		= ct.Razon_Social, 
					Apellido			= ct.Apellido ,
					Nombre				= ct.Nombre ,
					Sexo				= ct.Sexo ,
					Estado_Civil		= ct.Estado_Civil ,
					Fecha_Nac			= ct.Fecha_Nac ,
					Id_Tipo_Doc			= ct.Id_Tipo_Doc, 
					Doc_Nro				= ct.Doc_Nro ,
					Direccion			= ct.Direccion, 
					Cp					= ct.Cp ,
					Id_Pais				= ct.Id_Pais, 
					Id_Provincia		= ct.Id_Provincia, 
					Provincia_Descrip	= ct.Provincia_Descrip, 
					Id_Localidad		= ct.Id_Localidad,
					Localidad_Descrip	= ct.Localidad_Descrip, 
					Id_Nacionalidad		= ct.Id_Nacionalidad, 
					Email_Web			= ct.Email ,
					Email				= ct.Email ,
					telefono			= ct.telefono ,
					Tel_Movil			= ct.Tel_Movil ,
					Id_Cli_Relac		= ct.Id_Cli_Relac,
					Id_Facebook			= ct.Id_Facebook, 
					Id_Instagram		= ct.Id_Instagram, 
					Id_Twitter			= ct.Id_Twitter ,
					Id_Linkedin			= ct.Id_Linkedin ,
					Id_Google			= ct.Id_Google ,
					Id_Microsoft		= ct.Id_Microsoft
				FROM 
					Clientes cl, Clientes_Temp ct
				WHERE 
					cl.Id_Cliente=@Id_Cliente
					and ct.id_cliente_temp=@Id_Cliente_Temp
			
		 SET @Foto =ISNULL((SELECT Id_Cliente_Temp FROM Clientes_Temp_Doc WHERE Id_Cliente_Temp=@Id_Cliente_Temp AND Descripcion='FotoP'),0)

		 IF @Foto<>0
		 BEGIN
		 
			DELETE FROM Clientes_Fotos WHERE Id_Cliente=@Id_Cliente
		
			INSERT INTO Clientes_Fotos (Id_Cliente, Nro, Foto,Fecha) 
				SELECT TOP 1 @Id_Cliente, 1, Documento,GETDATE() From Clientes_Temp_Doc 
					WHERE Id_Cliente_Temp=@Id_Cliente_Temp AND Descripcion='FotoP'
		 END
	END

	UPDATE Clientes_Temp SET Id_Estado_Solicitud = 'A' WHERE id_cliente_temp=@Id_Cliente_Temp
	SET @Lote = (SELECT ISNULL(Nro_Trans_Pago,'') FROM Clientes_Temp WHERE id_cliente_temp=@Id_Cliente_Temp)
	
	COMMIT
	IF @Lote<>''
	BEGIN
	EXEC CP_Clientes_Temp_Actualizar_Cbte @Lote, @Id_Cliente_Titular

	IF EXISTS (SELECT 1 FROM sys.objects WHERE name = 'CP_Clientes_Temp_Aprobar_After' AND type = 'P')
		EXEC CP_Clientes_Temp_Aprobar_After @Id_Cliente_Temp

	SELECT	 0			AS ErrorNumber 
			,0			AS ErrorSeverity  
			,0			AS ErrorState 
			,0			AS ErrorProcedure  
			,0			AS ErrorLine		
			,@Mensaje	AS ErrorMessage	
	END 


END TRY  
	

BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO

CREATE PROCEDURE dbo.CP_Clientes_Temp_Aprobar_After
@Id_Cliente_Temp INT
AS
IF EXISTS (SELECT 1 FROM sys.objects WHERE name = 'CP_Clientes_Temp_Aprobar_After_' AND type = 'P')
BEGIN
	EXEC CP_Clientes_Temp_Aprobar_After_ @Id_Cliente_Temp

	RETURN
END


RETURN
GO


CREATE PROCEDURE [dbo].[CP_Clientes_Temp_Copiar] ( @Id_Cliente INT )

AS
 

DECLARE	@Id_Cliente_Temp	INT
DECLARE @Mensaje			VARCHAR(100)
DECLARE	@Fecha				DATETIME

BEGIN TRY
BEGIN TRAN


SET @Id_Cliente_Temp =	(SELECT (ISNULL(MAX(Id_Cliente_Temp),0)+1) FROM Clientes_Temp)
SET @Fecha = GETDATE();

INSERT INTO Clientes_Temp
					(Id_Cliente,		Id_Cliente_Ref,	Fecha,	Id_Tipo_Cli,	Razon_Social,	Apellido,		
					Nombre , 			Sexo,
					Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc,		Doc_Nro,		Direccion,	
					Cp ,				Id_Pais,		Id_Provincia,
					Provincia_Descrip,	Id_Localidad ,  Localidad_Descrip,	Id_Nacionalidad,
					Email,				telefono,		Tel_Movil,
					Legajo,				Observacion)
SELECT				Id_Cliente,			Id_Cliente_Ref,	@Fecha,	Id_Tipo_Cli,	Razon_Social,	Apellido,		
					Nombre , 			Sexo,
					Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc,		Doc_Nro,		Direccion,	
					Cp ,				Id_Pais,		Id_Provincia,
					Provincia_Descrip,	Id_Localidad ,  Localidad_Descrip,	Id_Nacionalidad,
					Email,				telefono,		Tel_Movil,
					Legajo,				Observacion
FROM Clientes WHERE Id_Cliente=@Id_Cliente

	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage
			,@Id_Cliente_Temp	AS Id_Cliente_Temp 


END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO


CREATE PROCEDURE dbo.CP_Clientes_Tipos_Users_Visualizar
@pId_Usuario		SMALLINT
AS
/*Declaracion Variables Locales*/
DECLARE @Mensaje				VARCHAR(100)
DECLARE @Flag_Existe_Usuario	TINYINT
/*Fin de Declaraciones Variables Locales */

PRINT 'Procedimiento: CP_Clientes_Tipos_Users_Visualizar'
CREATE TABlE #Clientes_Tipos_Visibles (Id_Tipo_Cli SMALLINT, Descripcion VARCHAR(50))

BEGIN TRY
	BEGIN TRAN

		SET @Flag_Existe_Usuario = ISNULL((SELECT 1 FROM Seg_User WHERE No = @pId_Usuario), 0)

		IF(@Flag_Existe_Usuario = 0)
		BEGIN
			SET @Mensaje = 'NO EXISTE EL USUARIO'

			SELECT	 0				AS ErrorNumber 
			,0						AS ErrorSeverity  
			,0						AS ErrorState 
			,0						AS ErrorProcedure  
			,0						AS ErrorLine		
			,@Mensaje				AS ErrorMessage
			,@Flag_Existe_Usuario   AS Id_Usuario
			
			ROLLBACK
			RETURN 1
		END

		INSERT INTO #Clientes_Tipos_Visibles
		SELECT Id_Tipo_Cli, Descripcion FROM Clientes_Tipos
		WHERE
		Id_Tipo_Cli NOT IN (SELECT DISTINCT Id_Tipo_Cli FROM Clientes_Tipos_Users)
		AND Id_Tipo_Cli <> 0

		INSERT INTO #Clientes_Tipos_Visibles
		SELECT CT.Id_Tipo_Cli, CT.Descripcion 
		FROM Clientes_Tipos CT, Clientes_Tipos_Users CTU
		WHERE
		CT.Id_Tipo_Cli = CTU.Id_Tipo_Cli
		AND CTU.Id_Usuario = @pId_Usuario
		AND CT.Id_Tipo_Cli <> 0

		SELECT Id_Tipo_Cli, Descripcion FROM #Clientes_Tipos_Visibles ORDER BY Descripcion

		COMMIT
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH
GO




CREATE PROCEDURE [dbo].[CP_Clientes_Vencimientos]	@pId_Cliente INT , @pId_Tipo_Venc VARCHAR(10)
AS
BEGIN

DECLARE @Existe INT

	IF (@pId_Tipo_Venc <> '')
	BEGIN
			SELECT C.Id_Cliente,CV.Id_Tipo_Venc, CVT.Descripcion, CV.Fecha, ISNULL(CV.Nota,'') as Nota FROM Clientes c
					RIGHT JOIN Clientes_Venc cv			ON cv.Id_Cliente = c.Id_Cliente
					RIGHT JOIN Clientes_Venc_Tipos cvt	ON cv.Id_Tipo_Venc = cvt.Id_Tipo_Venc
					WHERE c.Id_Cliente=@pId_Cliente AND CVT.Id_Tipo_Venc=@pId_Tipo_Venc
	END
	ELSE
	BEGIN
			SET @Existe = ( SELECT COUNT(*) FROM Clientes c
							RIGHT JOIN Clientes_Venc cv			ON cv.Id_Cliente = c.Id_Cliente
							RIGHT JOIN Clientes_Venc_Tipos cvt	ON cv.Id_Tipo_Venc = cvt.Id_Tipo_Venc
							WHERE c.Id_Cliente=@pId_Cliente
							)

			IF(@Existe=0)
			BEGIN
					INSERT INTO Clientes_Venc (Id_Cliente,Id_Tipo_Venc) 
								SELECT @pId_Cliente,Id_Tipo_Venc FROM Clientes_Venc_Tipos A 
								WHERE NOT EXISTS(SELECT 1 FROM Clientes_Venc B WHERE A.Id_Tipo_Venc = B.Id_Tipo_Venc 
													AND Id_Cliente = @pId_Cliente)

			END

	SELECT C.Id_Cliente,CV.Id_Tipo_Venc, CVT.Descripcion, CV.Fecha, ISNULL(CV.Nota,'') as Nota FROM Clientes c
					RIGHT JOIN Clientes_Venc cv			ON cv.Id_Cliente = c.Id_Cliente
					RIGHT JOIN Clientes_Venc_Tipos cvt	ON cv.Id_Tipo_Venc = cvt.Id_Tipo_Venc
					WHERE c.Id_Cliente=@pId_Cliente

	END
END
GO


