DECLARE @Email_Web VARCHAR(300)
DECLARE @Tel_Movil VARCHAR(20)
DECLARE @Flag_Tel_Movil_Verif TINYINT
DECLARE @Flag_Comunic_Sms TINYINT
DECLARE @Flag_Comunic_Email TINYINT
DECLARE @Carpeta VARCHAR(256)
DECLARE @Id_Emp_Area SMALLINT
DECLARE @Id_AR_ARBA_COT_Tipo_Dom_Nro VARCHAR(5)
DECLARE @Dir_Entrega_Numero SMALLINT
DECLARE @Dir_Entrega_Piso VARCHAR(3)
DECLARE @Dir_Entrega_Dto VARCHAR(4)
DECLARE @Dir_Entrega_Barrio VARCHAR(30)
DECLARE @Dir_Entrega_CP VARCHAR(8)
DECLARE @Dir_Entrega_Localidad VARCHAR(50) 

DECLARE @CD_ES_Tipo				CHAR(1)
DECLARE @CD_ES_Origen			CHAR(1)
DECLARE @CD_ES_Id_Tarjeta		VARCHAR(50)
DECLARE @CD_ES_Fecha			DATETIME
DECLARE @CD_ES_Resultado		CHAR(1)
DECLARE @CD_ES_Id_Controlador	SMALLINT
DECLARE @CD_ES_Id_Acceso		SMALLINT
DECLARE @CD_ES_tipo_reg			CHAR(5) 
DECLARE @Usuario_Alta			VARCHAR(41)
DECLARE @Id_CD_Motivo			INT
/*Fin de Declaraciones Variables Locales */

PRINT 'Procedimiento: CP_Clientes_Visitas'

IF(@pFlag_GrabaRegistro IS NULL)
BEGIN
	SET @pFlag_GrabaRegistro = 1 /*Por defecto graba el registro en CD_ES*/
END

IF(@pCredencial_Nro IS NULL)
BEGIN
	SET @pCredencial_Nro = ''
END

IF EXISTS ( SELECT * 
			FROM sysobjects 
            WHERE
            id = object_id(N'[dbo].[CP_Clientes_Visitas_]') 
			AND OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN
	EXEC CP_Clientes_Visitas_	@pApellido,
								@pNombre, 
								@pDoc_Nro,
								@pSexo,
								@pFecha_Nac,
								@pId_Tipo_Cli,
								@pMotivoIngreso,
								@pId_Usuario_Alta,
								@pId_Cliente,
								@pId_Controlador,
								@pFlag_GrabaRegistro,
								@pCredencial_Nro
	RETURN
END

BEGIN TRY
	BEGIN TRAN


	IF(@pId_Cliente > 0)
	BEGIN
		SET @Flag_Existe_Cliente = @pId_Cliente
	END
	ELSE
	BEGIN
		IF(@pApellido = '' OR @pNombre = '' OR @pDoc_Nro = 0 OR @pSexo = '' OR @pId_Tipo_Cli = 0 OR @pMotivoIngreso = '')
			BEGIN
			SET @Mensaje = 'NO SE RECIBIERON CORRECTAMENTE TODOS LOS PARAMETROS'

			SELECT	 0				AS ErrorNumber 
			,0						AS ErrorSeverity  
			,0						AS ErrorState 
			,0						AS ErrorProcedure  
			,0						AS ErrorLine		
			,@Mensaje				AS ErrorMessage
			,0						AS Id_Cliente
						
			ROLLBACK
			RETURN 1
		END
		
		SET @Flag_Existe_Cliente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Doc_Nro = @pDoc_Nro), 0)
	END
	
	IF(@Flag_Existe_Cliente = 0)
	BEGIN
		/*Asignaci┬Ñn de Variables*/
		SET @Id_Tipo_Doc				=  ISNULL((SELECT VALOR_STRING FROM xParametros WHERE IdParametro = 'Cli_Tipo_Doc_SCA'), '')--Documentos_Tipos
		SET @Id_Localidad				= 0		--Tab_Localidades
		SET @Id_Provincia				= ''	--La del registro de Tab_Localidades
		SET @Id_Pais					= ''	--La del registro de Tab_Localidades
		SET @Activo						= 1
		SET @Id_Lista_Precio			= 0		--Prod_Listas_Precios
		SET @Id_Cond_Pago				= dbo.CF_xParam('SCA_Visitor_ConPago')
		SET @Id_Iva						= dbo.CF_xParam('SCA_Visitor_Iva')
		SET @Id_Concepto				= dbo.CF_xParam('SCA_Visitor_Concept')
		SET @Observacion				= 'Ingresado Automaticamente desde Proceso Visitas'
		SET @Id_Alias_Cta_Cont_Venta	= dbo.CF_xParam('SCA_Visitor_AliasCV')
		SET @Mercado					= 'I'
		SET @Id_Cliente_Ref				= 0
		SET @Fecha_Alta					= GETDATE()
		SET @Id_Centro_Costo			= ''	--Centro_Costos
		SET @Id_Cond_Vta				= ''	--Cbtes_Cond_Vtas
		SET @Fecha_Modif				= @Fecha_Alta
		SET @Id_Alias_Cta_Cont_Venta_Dol = 0
		SET @Estado_Civil				= ''
		SET @Id_Nacionalidad			= ''	--Tab_Paises
		SET @Id_Cli_Relac				= 0		--Clientes_Relaciones
		SET @Tipo_Persona				= 'F'
		SET @Id_Unid_Negocio			= dbo.CF_xParam('SCA_Visitor_UNegoci')

		SET @CD_ES_Id_Tarjeta			= ''
		/*FIN Asignaci┬Ñn de Variables*/

		CREATE TABLE #RetornoSP
		(ErrorNumber INT,
		ErrorSeverity INT,
		ErrorState INT,
		ErrorProcedure INT,
		ErrorLine INT,
		ErrorMessage VARCHAR(200),
		Id_Cliente INT)

		/*INSERTO Clientes*/
		INSERT INTO #RetornoSP
		EXEC CP_Clientes_Insertar	@Razon_Social,
									@pApellido,
									@pNombre,
									@pSexo,
									@pFecha_Nac,
									@Id_Tipo_Doc,
									@pDoc_Nro,
									@Ingresos_Brutos,
									@Direccion,
									@Cp,
									@Id_Pais,
									@Id_Provincia,
									@Provincia_Descrip,
									@Id_Localidad,
									@Localidad_Descrip,
									@Fax,
									@Cuit,
									@Email,
									@Activo,
									@Id_Estado_Cliente,
									@Id_Grupo_Afinidad,
									@Porc_DescEspecial,
									@Id_Lista_Precio,
									@Id_Vendedor,
									@Id_Transportista,
									@Bonif,
									@Id_Cond_Pago,
									@Cred_CtaCte,
									@Cred_ChePro,
									@Cred_CheTer,
									@Id_Iva,
									@CTE,
									@Id_Concepto,
									@Id_Cta_Banco,
									@Id_Zona,
									@Observacion,
									@Id_Cliente_Externo,
									@Id_Transporte,
									@Id_Alias_Cta_Cont_Venta,
									@Mercado,
									@Observa_Fact,
									@Entre_Calle_1 ,
									@Entre_Calle_2 ,
									@Plano_Nro,
									@Plano_Matriz,
									@Id_Cobrador,
									@Id_Motivo_Est,
									@pId_Tipo_Cli,
									@Id_Dep_Fisico,
									@Id_Dep_Logico,
									@Id_Tarjeta,
									@Id_Banco,
									@Tar_Nro ,
									@Tar_Fecha_Vence,
									@Tar_Titular,
									@Direccion_Cob,
									@Cp_Cob,
									@Id_Pais_Cob,
									@Id_Provincia_Cob,
									@Provincia_Descrip_Cob,
									@Id_Localidad_Cob,
									@Localidad_Descrip_Cob,
									@Entre_Calle_1_Cob ,
									@Entre_Calle_2_Cob ,
									@Plano_Nro_Cob,
									@Plano_Matriz_Cob,
									@Fecha_Ven_Trib,
									@Web,
									@Id_Cliente_Ref,
									@Fecha_Alta,
									@Fecha_Baja,
									@Id_Centro_Costo,
									@Id_Promotor,
									@Nombre_Fantasia,
									@Id_Cond_Vta,
									@Id_Puerto,
									@Id_Calle,
									@Nro,
									@Depto,
									@Fecha_Modif,
									@Foto,
									@Latitud ,
									@Longitud ,
									@Id_Calle_Cob,
									@Nro_Cob,
									@Depto_Cob,
									@Latitud_Cob ,
									@Longitud_Cob ,
									@Id_Precio_Especial,
									@Cod_Autoriz_Trib,
									@Id_Alias_Cta_Cont_Venta_Dol,
									@Estado_Civil,
									@Id_Nacionalidad,
									@Id_Cli_Relac,
									@Tipo_Persona,
									@telefono ,
									@Calle_Descrip,
									@Calle_Cob_Descrip,
									@Imp_Aporte,
									@Fecha_Aporte,
									@pCredencial_Nro,
									@Credencial_Banda1,
									@Credencial_Banda2,
									@Credencial_Imp,
									@Ult_Cuota_Paga,
									@Legajo,
									@Credencial_Entrega,
									@Id_Unid_Negocio,
									@Clave_Web,
									@Flag_Anmat,
									@Nro_Anmat,
									@Tar_Cuit,
									@Id_Anmat,
									@Coef_Comi_Vta,
									@Coef_Comi_Cobros,
									@Email_Cob,
									@Recorrido_Cob,
									@Tar_Fecha_Alta,
									@Tar_Fecha_Baja,
									@Imp_Fac_Max_Mes,
									@Email_Web,
									@Tel_Movil,
									@Flag_Tel_Movil_Verif,
									@Flag_Comunic_Sms,
									@Flag_Comunic_Email,
									@Carpeta,
									@Id_Emp_Area,
									@Id_AR_ARBA_COT_Tipo_Dom_Nro,
									@Dir_Entrega_Numero,
									@Dir_Entrega_Piso,
									@Dir_Entrega_Dto,
									@Dir_Entrega_Barrio,
									@Dir_Entrega_CP,
									@Dir_Entrega_Localidad,
									@pId_Usuario_Alta									

		SET @Flag_Existe_Cliente = (SELECT Id_Cliente FROM #RetornoSP)
	END
	ELSE
	BEGIN
		IF(@pCredencial_Nro <> '')
		BEGIN
			UPDATE Clientes SET Credencial_Nro = @pCredencial_Nro WHERE Id_Cliente = @Flag_Existe_Cliente
		END
	END

	IF(@pFlag_GrabaRegistro = 1)
	BEGIN
		SET @CD_ES_Tipo				= 'E' --Entrada
		SET @CD_ES_Origen			= 'M' --Manual
		SET @CD_ES_Id_Tarjeta		= (SELECT ISNULL(Credencial_Nro, '') FROM Clientes WHERE Id_Cliente = @Flag_Existe_Cliente)
		SET @CD_ES_Fecha			= GETDATE()
		SET @CD_ES_Resultado		= 'S'

		IF(@pId_CD_Motivo > 0)
		BEGIN
			SET @Id_CD_Motivo		= @pId_CD_Motivo
		END
		ELSE
		BEGIN
			SET @Id_CD_Motivo		= ISNULL((SELECT ISNULL(Id_CD_Motivo, 0) FROM CD_Motivos WHERE UPPER(LTRIM(RTRIM(Descripcion))) = UPPER(LTRIM(RTRIM(@pMotivoIngreso)))), 0)
		END				
		
		SET @Usuario_Alta			= ISNULL((SELECT 'HABILITO: (Id: ' + CONVERT(VARCHAR(10), @pId_Usuario_Alta) + ') ' + LTRIM(RTRIM(ISNULL(FirstName, ''))) + ' ' + LTRIM(RTRIM(ISNULL(LastName, ''))) FROM Seg_User WHERE No = @pId_Usuario_Alta ), '')	
		SET @pMotivoIngreso			= @pMotivoIngreso + '. ' + @Usuario_Alta	
		IF(ISNULL(@pId_Controlador, 0) = 0)
		BEGIN
			SET @CD_ES_Id_Controlador	= dbo.CF_xParam('SCA_Id_Contr_Vis') --CD_Controladores
		END
		ELSE
		BEGIN
			SET @CD_ES_Id_Controlador	= @pId_Controlador --CD_Controladores
		END
		SET @CD_ES_Id_Acceso		= (SELECT Id_Acceso FROM CD_Controladores WHERE Id_Controlador = @CD_ES_Id_Controlador)
		SET @CD_ES_tipo_reg			= ''

		/*INSERTO CD_ES*/
		INSERT INTO CD_ES
		(Tipo,			Origen,			Id_Tarjeta,
		Id_Cliente,		Fecha,			Resultado,
		Id_Controlador, Id_Acceso,		Observacion,
		tipo_reg,		Id_CD_Motivo,	Flag_Permite_Paso)
		VALUES
		(@CD_ES_Tipo,				@CD_ES_Origen,		@CD_ES_Id_Tarjeta,
		@Flag_Existe_Cliente,		@CD_ES_Fecha,		@CD_ES_Resultado,
		@CD_ES_Id_Controlador,		@CD_ES_Id_Acceso,	@pMotivoIngreso,
		@CD_ES_tipo_reg,			@Id_CD_Motivo,		@pFlag_Permite_Paso)
	END
	
	COMMIT
	SELECT	 0						AS ErrorNumber 
			,0						AS ErrorSeverity  
			,0						AS ErrorState 
			,0						AS ErrorProcedure  
			,0						AS ErrorLine		
			,@Mensaje				AS ErrorMessage
			,@Flag_Existe_Cliente   AS Id_Cliente

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH
GO



CREATE PROCEDURE [dbo].[CP_Cobros_Pendientes] 
	 @Filtrar_Fecha		TINYINT 
	,@Fecha_Desde		DateTime 
	,@Fecha_Hasta		DateTime
	,@Id_cliente		INT
	,@Id_Cobrador		Varchar(10)
	,@Det_Producto		INT=0

 
AS 
BEGIN
SET NOCOUNT ON
DECLARE @Sql		VARCHAR(MAX)
DECLARE @SqlSaldo	VARCHAR(MAX)
DECLARE @SqlSelect	VARCHAR(MAX)
DECLARE @SqlFrom	VARCHAR(MAX)
DECLARE @SqlWhere	VARCHAR(MAX)
DECLARE @SqlGroup	VARCHAR(MAX)

CREATE TABLE #Cobros_Pend  (
			 Fecha DATETIME
			,Fecha_Vence DATETIME
			,Descripcion VARCHAR(25)
			,Id_Trans INT
			,Nro_Cuota SMALLINT
			,Id_cliente INT
			,Razon_Social CHAR(100)
			,Importe DECIMAL(16,2)
			,Saldo 	DECIMAL(16,2)
			,Id_Tipo_Cbte Char(4)
			,Comprobante_Nro INT
			,Id_Estado_Cbte SMALLINT
			,Id_Cobrador Varchar(10)
			,Nombre_Cobrador CHAR(100)
			,Id_Interno INT IDENTITY(1,1)
			,Descrip_Producto	VARCHAR(8000)
		)

SET @SqlSelect = 'SELECT k.FECHA as Fecha,
                         k.Fecha_vence as Fecha_Vence,
						 k.Descripcion as Descripcion,
						 k.Id_Trans as Id_Trans,
						 k.Nro_Cuota as Nro_Cuota,
						 k.Id_cliente as Id_Cliente,
						 UPPER(CL.Razon_Social) as Razon_Social,
						 K.Importe as Importe,
						 k.Saldo as Saldo,
						 C.Id_Tipo_Cbte as Id_Tipo_Cbte,
						 C.Comprobante_Nro as Comprobante_Nro,
						 k.Id_Estado_Cbte as Id_Estado_Cbte,
						 UPPER(CL.id_COBRADOR) as Id_Cobrador,
						 ISNULL(V.Descripcion, '''') as Nombre_Cobrador' 

IF (@Det_Producto<>0)
BEGIN
	SET @SqlSelect =@SqlSelect+ ',dbo.CF_Descrip_Cbte_Producto(C.Id_Trans) AS Det_Producto'
END 
ELSE
BEGIN
	SET @SqlSelect =@SqlSelect+ ','''' AS Det_Producto'
END 
SET @SqlFrom = 'FROM  Cbtes C , Clientes_Ctacte K,  Cbtes_Tipos T, Clientes CL LEFT JOIN Vendedores V ON CL.ID_COBRADOR = V.ID_VENDEDOR '
----------------------------------------------------------------------------------------------------------------------
SET @SqlWhere = ' WHERE c.id_trans = k.id_trans 
                        AND K.ID_CLIENTE = CL.ID_CLIENTE
						AND C.ID_TIPO_CBTE = T.ID_TIPO_CBTE
						AND K.ID_ESTADO_CBTE IN (1,4)
						AND T.COMPROMETE_FACTURA IN (1,-1)
						AND K.SALDO <> 0'
						

					 
IF @Id_cliente <> 0
  BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND C.Id_cliente  = ' +  cast(@id_Cliente  as varchar(12))
  END


IF ISNULL(@Id_Cobrador,'') <> ''
	BEGIN
		SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND ISNULL(CL.Id_Cobrador, '''') = ''' + @Id_Cobrador + ''''
	END


IF ISNULL(@Filtrar_Fecha,0) <> 0
BEGIN
	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND k.FECHA_VENCE >= '''+ CONVERT(VARCHAR(8),@Fecha_Desde,112) +''''

	SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND k.FECHA_VENCE < '''+ CONVERT(VARCHAR(8),@Fecha_HASTA+1,112) +''''
END
----------------------------------------------------------------------------------------------------------------------
SET @SqlGroup = ' ORDER BY k.id_cliente,k.FECHA_VENCE '


SET @Sql = @SqlSelect +' '+ @SqlFrom + ' ' + @SqlWhere + ' ' + @SqlGroup 
PRINT @Sql
--EXECUTE (@Sql) 

CREATE INDEX IX_cobros_Pend____ ON  #Cobros_Pend (Id_Interno)

INSERT INTO #Cobros_Pend
EXEC(@sql)

SELECT * FROM #Cobros_Pend


DROP TABLE #Cobros_Pend

END

