-- exec [CP_Cobros_Pendientes] 1,'20201101','20201130',0,''
GO

CREATE PROCEDURE [dbo].[CP_Cobros_Producto](
    @pUsuario    INT
   , @pEquate  SMALLINT
   , @pFechaDesde DATETIME
   , @pFechaHasta DATETIME
   )
AS
 
  IF  @pEquate = 0
     RETURN


  select i.imp_gravado,i.imp_final,f.id_trans, 
                    f.Imp_Gravado + f.Imp_Gravado2 + f.Imp_Gravado3 + f.Imp_Exento, 
                    f.imp_total,r.id_trans,a.importe,i.Fecha_QA,i.Fecha_Venc,i.id_cliente,C.Nombre_Fantasia,C.Id_Cliente_Externo,C.Razon_Social,C.Id_Tipo_Cli 
           
  from cbtes_items i,cbtes f,cbtes_aplica a,cbtes r, cbtes_tipos tr, Cbtes_Tipos TF, Clientes C,TagFilePos_ TAG
  where r.id_tipo_cbte = tr.id_tipo_cbte
                              and tr.compromete_recibos in (1,-1)
                              and r.id_cliente = c.id_Cliente
                              and (i.id_producto = TAG.VAL
         AND TAG.TBL = @pEquate
         AND TAG.USR = @pUsuario)
                              and a.id_trans_d = r.id_trans 
                              and f.id_trans = a.id_trans 
                              and f.id_estado_cbte in (1,2,4) and r.id_estado_cbte in (2,4)
                              and i.id_trans = f.id_trans 
                              And f.id_tipo_cbte = TF.id_tipo_cbte 
                              and r.Fecha >= @pFechaDesde
                              and r.Fecha <  @pFechaHasta+1
                              And TF.Compromete_Factura = 1 



