CREATE PROCEDURE CP_Contratos_Baja_Prog 
AS
BEGIN TRY
	SET NOCOUNT ON
	BEGIN TRAN
	DECLARE @Sql			VARCHAR(MAX)
	DECLARE @Cant			INT
	DECLARE @Cant_CS		INT
	DECLARE @Tipo_Cont_CS	VARCHAR(1000)

	CREATE TABLE #Cont	(Id_Contrato INT,Id_Cliente INT,Id_Motivo_Est INT,Fecha_Baja_Prog DATETIME, Id_User INT)

	SET @Tipo_Cont_CS = RTRIM(LTRIM(ISNULL(dbo.CF_xParam('Tipo_Cont_CS'),'')))
	SET @Cant = 0
	SET @Cant_CS = 0

	IF RTRIM(LTRIM(@Tipo_Cont_CS)) = ''
	BEGIN
		INSERT #Cont 
			SELECT Id_Contrato,Id_Cliente,Id_Motivo_Est,Fecha_Baja_Prog,Id_Usuario_Baja 
				FROM Contratos 
				WHERE Activo = 1 AND Fecha_Baja_Prog IS NOT NULL AND Fecha_Baja_Prog <= GETDATE()
				

		SELECT @Cant = COUNT(*) FROM #Cont

		UPDATE Contratos SET Activo = 0, Fecha_Baja = O.Fecha_Baja_Prog, Fecha_Baja_Prog = NULL FROM Contratos O JOIN #Cont B ON O.Id_Contrato = B.Id_Contrato
	END
	ELSE
	BEGIN
	    ---------------------------------baja contratos CS
		SET @Sql = 'INSERT  #Cont  
							SELECT Id_Contrato,Id_Cliente,Id_Motivo_Est,Fecha_Baja_Prog,Id_Usuario_Baja 
								FROM Contratos 
								WHERE Activo = 1 
									AND Fecha_Baja_Prog IS NOT NULL 
									AND Fecha_Baja_Prog <= GETDATE()
									AND Id_Tipo_Con IN ('+ @Tipo_Cont_CS +')'
		EXEC(@Sql)
		SELECT @Cant_CS = COUNT(*) FROM #Cont
		UPDATE Contratos	SET Activo = 0, Fecha_Baja = B.Fecha_Baja_Prog, Fecha_Baja_Prog = NULL 
								FROM Contratos O JOIN #Cont B ON O.Id_Contrato = B.Id_Contrato
		UPDATE Clientes		SET Activo = 0, Fecha_Baja = B.Fecha_Baja_Prog ,Id_Motivo_Est = B.Id_Motivo_Est,Id_Usuario_Baja = B.Id_User
								FROM Clientes O JOIN #Cont B ON O.Id_Cliente = B.Id_Cliente
		
		
		---------------------------------baja otros contratos
		DELETE #Cont 

		SET @Sql = 'INSERT  #Cont  
							SELECT Id_Contrato,Id_Cliente,Id_Motivo_Est,Fecha_Baja_Prog,Id_Usuario_Baja 
								FROM Contratos 
								WHERE Activo = 1 
									AND Fecha_Baja_Prog IS NOT NULL 
									AND Fecha_Baja_Prog <= GETDATE()
									AND Id_Tipo_Con NOT IN ('+ @Tipo_Cont_CS +')'
		EXEC(@Sql)
		SELECT @Cant = COUNT(*) FROM #Cont
		UPDATE Contratos	SET Activo = 0, Fecha_Baja = B.Fecha_Baja_Prog, Fecha_Baja_Prog = NULL 
								FROM Contratos O JOIN #Cont B ON O.Id_Contrato = B.Id_Contrato

	END





	COMMIT
	SELECT	 0						AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,@Cant + @Cant_CS	AS ErrorLine		
				,'Contratos dados de baja: '+ CONVERT(VARCHAR,@Cant + @Cant_CS)	AS ErrorMessage

	IF OBJECT_ID (N'#Cont', N'U') IS NOT NULL  DROP TABLE #Cont
	
END TRY
BEGIN CATCH

	EXECUTE usp_GetErrorInfo

	ROLLBACK
	IF OBJECT_ID (N'#Cont', N'U') IS NOT NULL  DROP TABLE #Cont

	RETURN 9999

END CATCH



/*


EXEC CP_Contratos_Baja_Prog


*/
GO


CREATE  PROCEDURE dbo.CP_Contratos_Cli_Resumen
		 @Id_Cliente		INT	
		,@Flag_Agrupado		TINYINT    
AS
begin

IF ISNULL(@Id_Cliente,0) = 0
	RETURN
	
		
DECLARE	@Id_Cliente_Ref INT
SET @Id_Cliente_Ref =  @Id_Cliente

IF ISNULL(@Flag_Agrupado,0) <> 0
	SET @Id_Cliente_Ref = (SELECT Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @Id_Cliente)
END

IF ISNULL(@Id_Cliente_Ref,0) = 0
	SET @Id_Cliente_Ref =  @Id_Cliente



 select k.id_cliente as Id_Cliente
			,k.razon_social as Razon_Social
			,k.Id_Cliente_Externo as Id_Cliente_Externo
			,k.id_tipo_cli	as Id_Tipo_Cli
			,kt.Descripcion as Descripcion_Tipo_Cli
			,p.id_producto  as Id_Producto
			,a.descripcion_detallada as Descripcion_Prod
			,c.id_contrato 
			,c.descripcion
			,c.Id_Tipo_Con
			,t.Descripcion	as Descripcion_Cont
			,k.id_cliente_Ref
			,c.id_lista_Precio
 INTO #CP_Contratos_Cli_Resumen
 from contratos_prod p, contratos c, productos a, clientes k , Contratos_Tipos t, clientes_tipos kt
 where c.Id_Contrato = p.Id_Contrato 
 and c.activo = 1 
 and a.id_producto = p.id_producto
 and c.id_cliente = k.id_cliente 
 and t.Id_Tipo_Con = C.Id_Tipo_Con
 and kt.Id_Tipo_Cli = k.Id_Tipo_Cli
 and c.Id_Cliente = @Id_Cliente_ref

 IF ISNULL(@Flag_Agrupado,0) <> 0
	INSERT INTO #CP_Contratos_Cli_Resumen
		 select k.id_cliente as Id_Cliente
				,k.razon_social as Razon_Social
				,k.Id_Cliente_Externo as Id_Cliente_Externo
				,k.id_tipo_cli	as Id_Tipo_Cli
				,kt.Descripcion as Descripcion_Tipo_Cli
				,p.id_producto  as Id_Producto
				,a.descripcion_detallada as Descripcion_Prod
				,c.id_contrato 
				,c.descripcion
				,c.Id_Tipo_Con
				,t.Descripcion	as Descripcion_Cont
			    ,k.id_cliente_Ref
				,c.id_lista_Precio
			 from contratos_prod p, contratos c, productos a, clientes k , Contratos_Tipos t, clientes_tipos kt
			 where c.Id_Contrato = p.Id_Contrato 
			 and c.activo = 1 
			 and a.id_producto = p.id_producto
			 and c.id_cliente = k.id_cliente 
			 and t.Id_Tipo_Con = C.Id_Tipo_Con
			 and kt.Id_Tipo_Cli = k.Id_Tipo_Cli
			 and k.Id_Cliente_Ref = @Id_Cliente_ref

 select * from #CP_Contratos_Cli_Resumen
 DROP TABLE #CP_Contratos_Cli_Resumen
GO



CREATE PROCEDURE [dbo].[CP_Contratos_Prod_PSH_Agregar] @pId_Contrato INT, @pId_Producto VARCHAR(14), @pString VARCHAR(8000)
AS

DECLARE @Cantidad_Productos							INT
DECLARE @Contador_Aux_Productos_Salas				INT
DECLARE @Cada_Producto								VARCHAR(8000)
DECLARE @Cada_Arr_Producto_Horario					VARCHAR(8000)
DECLARE @Cada_Arr_Sala_Horario						VARCHAR(8000)
DECLARE @Cantidad_Salas								INT
DECLARE @Contador_Aux_Salas							INT
DECLARE @Cada_Sala_Horario							VARCHAR(8000)
DECLARE @Cada_Sala									VARCHAR(8000)
DECLARE @Cada_Arr_Horario							VARCHAR(8000)
DECLARE @Cantidad_Horarios							INT
DECLARE @Contador_Aux_Productos_Salas_Horarios		INT
DECLARE @Cada_Horario								VARCHAR(8000)
DECLARE @Items			INT

--SET @pString = '1261_01:4649=3114|2245|3112|,;1002_01:4578=172|,;1261_01:4649=,;'

PRINT '@pString: ' + @pString

SET @Cantidad_Productos = DATALENGTH(@pString)  - DATALENGTH(REPLACE(@pString, ';', ''))

SET @Contador_Aux_Productos_Salas = 1
SET @Items=1

WHILE @Contador_Aux_Productos_Salas <= @Cantidad_Productos
BEGIN
	SET @Cada_Arr_Producto_Horario = dbo.SF_CortarCadena(@pString, ';', @Contador_Aux_Productos_Salas)

	SET @Cada_Producto = dbo.SF_CortarCadena(@Cada_Arr_Producto_Horario, ':', 1)

	SET @Cada_Arr_Sala_Horario = dbo.SF_CortarCadena(@Cada_Arr_Producto_Horario, ':', 2)

	PRINT ''
	PRINT '------------------------------------------------------------------------------------------------'
	PRINT ''
	PRINT 'Producto: ' + @Cada_Producto
	
	IF (@pId_Producto=@Cada_Producto)
	BEGIN
		PRINT ''
		PRINT '--Salas del Producto: '
		SET @Cantidad_Salas = DATALENGTH(@Cada_Arr_Sala_Horario)  - DATALENGTH(REPLACE(@Cada_Arr_Sala_Horario, ',', ''))

		SET @Contador_Aux_Salas = 1

		WHILE @Contador_Aux_Salas <= @Cantidad_Salas
		BEGIN
			SET @Cada_Sala_Horario = dbo.SF_CortarCadena(@Cada_Arr_Sala_Horario, ',', @Contador_Aux_Salas)

			SET @Cada_Sala = dbo.SF_CortarCadena(@Cada_Sala_Horario, '=', 1)

			SET @Cada_Arr_Horario = dbo.SF_CortarCadena(@Cada_Sala_Horario, '=', 2)
		
			PRINT '-------------------------------------------------'
			PRINT 'Sala: ' + @Cada_Sala

		
			INSERT INTO Contratos_Prod 
			(Id_Contrato,		Item,	Id_Producto,	Precio,	Precio_Formula,	Cant_Cuotas,	
			Observa_Fact,	Flag_Facturable,	Cantidad,	Cant_Includ, Flag_No_Bonificable,	Id_Prod_Familia_Sala)
			VALUES
			(@pId_Contrato,	@Items,		@Cada_Producto,	0,		'',				0,				
			'',					1,				1,			0,			0,						@Cada_Sala)

			SET @Items=@Items+1

			PRINT ''
			PRINT '----Horarios de la sala: '
			PRINT ''

			SET @Cantidad_Horarios = DATALENGTH(@Cada_Arr_Horario)  - DATALENGTH(REPLACE(@Cada_Arr_Horario, '|', ''))

			SET @Contador_Aux_Productos_Salas_Horarios = 1

			WHILE @Contador_Aux_Productos_Salas_Horarios <= @Cantidad_Horarios
			BEGIN
				SET @Cada_Horario = dbo.SF_CortarCadena(@Cada_Arr_Horario, '|', @Contador_Aux_Productos_Salas_Horarios)

				PRINT @Cada_Horario

					IF(@Cada_Horario<>'')
					BEGIN
						INSERT INTO Contratos_Prod_Horarios (Id_Contrato, Item, Id_Prod_Familia_Horario)
						VALUES (@pId_Contrato,1,@Cada_Horario)
					END

				SET @Contador_Aux_Productos_Salas_Horarios = @Contador_Aux_Productos_Salas_Horarios + 1
		
			END

			SET @Contador_Aux_Salas = @Contador_Aux_Salas + 1
		END
	END
	SET @Contador_Aux_Productos_Salas = @Contador_Aux_Productos_Salas + 1	
END
GO



CREATE PROCEDURE dbo.CP_Contratos_SP1 
