CREATE PROCEDURE [dbo].[CP_CtrlPresup_Generar] 
@Fecha		CHAR(8),
@Id_Centro_Costo CHAR(10),
@Importe	DECIMAL(16,2)
AS 

DECLARE @Id_Tipo_Cbte	CHAR(4)
DECLARE @Nombre			VARCHAR(100)
DECLARE @NRO_CBTE		INT
DECLARE @trans_nueva	INT
DECLARE @Mensaje		VARCHAR(100)
DECLARE @Id_Moneda		CHAR(3)

BEGIN TRY
	BEGIN TRAN
	SET @Id_Tipo_Cbte = dbo.CF_xParam('Tipo_Cbte_CtrlPresup')
	IF ISNULL(@Id_Tipo_Cbte,'') = ''
	BEGIN
		SELECT	 1001				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,'Parámetro Tipo_Cbte_CtrlPresup sin definir'		AS ErrorMessage
		ROLLBACK
		RETURN
	END


	SET @Id_Moneda    = dbo.CF_xParam('Moneda_Nacional')
	IF ISNULL(@Id_Tipo_Cbte,'') = ''
	BEGIN
		SELECT	 1002				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,'Parámetro Moneda_Nacional sin definir'		AS ErrorMessage
		ROLLBACK
		RETURN
	END


	----------------------------------------Anulo lo anterior
	UPDATE Cbtes SET Id_Estado_Cbte = 3 WHERE Id_Centro_Costo = @Id_Centro_Costo
										AND DATEPART(yyyy,Fecha) =  CAST(SUBSTRING(@Fecha,1,4) AS INT)
										AND DATEPART(mm,Fecha) =  CAST(SUBSTRING(@Fecha,5,2) AS INT)
										AND Id_Tipo_Cbte = @Id_Tipo_Cbte
    ----------------------------------------------------------------------------------


	SET @Nombre = (SELECT rtrim(Descripcion) FROM Centro_Costos WHERE Id_Centro_Costo = @Id_Centro_Costo)

	SET @trans_nueva = (SELECT max(id_trans) from transacciones ) + 1

	/*===================================================================*/
	INSERT INTO Transacciones	(id_trans,		descripcion,	fecha_mov) 
					VALUES		(@trans_nueva,	@Nombre,			GETDATE())

	/*===================================================================*/
	SET @NRO_CBTE = (SELECT Prox_Nro from Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte) 

	UPDATE Cbtes_Tipos SET Prox_Nro = Prox_Nro+1 WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte

	/*===================================================================*/
	INSERT INTO Cbtes	(Id_Cond_Vta,		Id_trans,		Id_Sucursal,
						Cbte_Grupo,			Fecha_Venc ,    id_cliente,
						id_estado_Cbte,		id_tipo_cbte,	comprobante_nro,
						fecha,				periodo_iva,	periodo,
						imp_total,			saldo,			imp_gravado,
						destinatario,		lote,			ID_MONEDA,
						Id_Cond_Pago,		Cotizacion,		Id_Centro_Costo)
			   VALUES	('',				@trans_nueva,	1,
						0,					@FECHA,			0,
						0,					@Id_Tipo_cbte,	@NRO_CBTE,
						@FECHA,				@FECHA,			@FECHA,
						@Importe,			0,				@Importe,
						@NOMBRE,			'',				@Id_Moneda,
						10,					1,				@Id_Centro_Costo)

	/*===================================================================*/
	INSERT INTO Clientes_CtaCte (Id_Trans,		Nro_Cuota,		Id_Empresa,
								Id_Cliente,		Fecha,			Fecha_Vence,
								Descripcion,	Importe,		Id_Estado_Cbte,
								Observacion,	Id_Trans_Origen,Nro_Cuota_Origen,
								Id_Moneda,		Saldo,			Nro_FacCre)
					VALUES		(@trans_nueva,	1,				NULL,
								0,	@Fecha,			@Fecha,
								dbo.CF_Descrip_Cbte(@trans_nueva),@Importe ,1,
								'',				0,				0,
								@Id_Moneda,			0,				0)


	 
	COMMIT

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage
			,@trans_nueva	AS Id_Trans

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO



CREATE PROCEDURE [dbo].[CP_CtrlPresup_Generar_Fin] 
@Id_Trans   INT
AS 

DECLARE @Mensaje			VARCHAR(100)
		,@Importe			DECIMAL(16,2)


BEGIN TRY
	BEGIN TRAN
	SET @Importe = ISNULL((SELECT SUM(Debe) FROM Cbtes_Ctas_Contables WHERE Id_Trans = @Id_Trans),0)

	UPDATE Cbtes SET Id_Estado_Cbte = 2 , Imp_Total = @Importe WHERE Id_Trans = @Id_Trans
	 
	COMMIT

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO



CREATE PROCEDURE [dbo].[CP_CtrlPresup_Generar_Item] 
@Id_Trans   INT,
@Item		SMALLINT,
@Id_Centro_Costo CHAR(10),
@Alias		SMALLINT,
@Debe	DECIMAL(16,2),
@Haber	DECIMAL(16,2)
AS 

DECLARE @Mensaje			VARCHAR(100)
		,@Id_Cta_Contable	INT
		,@Fecha		        DATETIME


BEGIN TRY
	BEGIN TRAN
	SET @Fecha = (SELECT Fecha FROM Cbtes WHERE Id_Trans = @Id_Trans)
	SET @Id_Cta_Contable = dbo.CF_Cta_Cont(@Alias,@Fecha)


	/*===================================================================*/
	INSERT INTO Cbtes_Ctas_Contables	(	Id_Trans		,Item		,Id_Cta_Contable
											,Fecha			,Debe		,Haber
											,Observacion	,Alias		,Id_Asiento
											,Id_Centro_Costo)
			   VALUES					(	@Id_Trans		,@Item		,@Id_Cta_Contable
											,@Fecha			,@Debe		,@Haber
											,''				,@Alias		,0
											,@Id_Centro_Costo)

	 
	COMMIT

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_DB_Check] @Db1 SYSNAME, @Db2 SYSNAME, @Tipo CHAR(2)=NULL

AS
DECLARE @Sql NVARChAR(MAX)

IF @Tipo IS NULL SET @Tipo = '*'

SET @Tipo = UPPER(@Tipo)

IF @Tipo IN ('*','T')
BEGIN
	SELECT 'Tablas Faltantes *********************************************************'
	SET @Sql = ' SELECT * FROM '+ @Db1 +'.[INFORMATION_SCHEMA].TABLES a left join '+ @Db2 +'.[INFORMATION_SCHEMA].TABLES b
					 on   a.TABLE_NAME COLLATE Modern_Spanish_CI_AS = b.TABLE_NAME COLLATE Modern_Spanish_CI_AS 
					 WHERE b.TABLE_NAME IS NULL
					 AND a.TABLE_NAME NOT LIKE ''z%''
					 AND a.TABLE_NAME NOT IN (''userinfo'',''userinfo_attarea'',''GV02ART'',''acc_levelset_emp'')
					 ORDER BY a.TABLE_NAME'

	PRINT @Sql
	EXECUTE sp_executesql  @Sql
END
		
IF @Tipo IN ('*','CF')
BEGIN
	SELECT 'Campos Faltantes *********************************************************'
	SET @Sql = ' SELECT * FROM '+ @Db1 +'.[INFORMATION_SCHEMA].COLUMNS a left join '+ @Db2 +'.[INFORMATION_SCHEMA].COLUMNS b
					 on   a.TABLE_NAME COLLATE Modern_Spanish_CI_AS = b.TABLE_NAME COLLATE Modern_Spanish_CI_AS 
					 and  a.COLUMN_NAME COLLATE Modern_Spanish_CI_AS = b.COLUMN_NAME COLLATE Modern_Spanish_CI_AS
					 WHERE b.COLUMN_NAME IS NULL
					 AND a.TABLE_NAME NOT LIKE ''z%''
					 AND a.TABLE_NAME NOT IN (''userinfo'',''userinfo_attarea'',''GV02ART'',''acc_levelset_emp'')
					 ORDER BY a.TABLE_NAME, a.COLUMN_NAME '

	PRINT @Sql
	EXECUTE sp_executesql  @Sql
END
		
IF @Tipo IN ('*','CD')
BEGIN
	SELECT 'Campos Diferentes *********************************************************'
	SET @Sql = ' SELECT * FROM '+ @Db1 +'.[INFORMATION_SCHEMA].COLUMNS a, '+ @Db2 +'.[INFORMATION_SCHEMA].COLUMNS b
					 WHERE  a.TABLE_NAME COLLATE Modern_Spanish_CI_AS = b.TABLE_NAME COLLATE Modern_Spanish_CI_AS 
					 and  a.COLUMN_NAME COLLATE Modern_Spanish_CI_AS = b.COLUMN_NAME COLLATE Modern_Spanish_CI_AS
					 AND a.TABLE_NAME NOT LIKE ''z%''
					 AND a.TABLE_NAME NOT IN (''userinfo'',''userinfo_attarea'',''GV02ART'',''acc_levelset_emp'')
					 AND (a.DATA_TYPE COLLATE Modern_Spanish_CI_AS <> b.DATA_TYPE COLLATE Modern_Spanish_CI_AS
						OR a.IS_NULLABLE COLLATE Modern_Spanish_CI_AS <> b.IS_NULLABLE COLLATE Modern_Spanish_CI_AS
						OR a.CHARACTER_MAXIMUM_LENGTH <> b.CHARACTER_MAXIMUM_LENGTH
						OR a.NUMERIC_PRECISION <> b.NUMERIC_PRECISION
						OR a.NUMERIC_SCALE <> b.NUMERIC_SCALE
						) 
					 ORDER BY a.TABLE_NAME, a.COLUMN_NAME '

	PRINT @Sql
	EXECUTE sp_executesql  @Sql
END

IF @Tipo IN ('*','KD')
BEGIN
	SELECT 'CONSTRAINTS Faltantes *********************************************************'
	SET @Sql = ' SELECT * FROM '+ @Db1 +'.[INFORMATION_SCHEMA].TABLE_CONSTRAINTS a left join '+ @Db2 +'.[INFORMATION_SCHEMA].TABLE_CONSTRAINTS b
					 on   a.TABLE_NAME COLLATE Modern_Spanish_CI_AS = b.TABLE_NAME COLLATE Modern_Spanish_CI_AS 
					 WHERE b.TABLE_NAME IS NULL
					 AND a.TABLE_NAME NOT LIKE ''z%''
					 AND a.TABLE_NAME NOT IN (''userinfo'',''userinfo_attarea'',''GV02ART'',''acc_levelset_emp'')
					 ORDER BY a.TABLE_NAME'

	PRINT @Sql
	EXECUTE sp_executesql  @Sql
END
		

IF @Tipo IN ('*','KF')
BEGIN
	SELECT 'CONSTRAINTS Diferentes *********************************************************'
	SET @Sql = ' SELECT * FROM '+ @Db1 +'.[INFORMATION_SCHEMA].KEY_COLUMN_USAGE a, '+ @Db2 +'.[INFORMATION_SCHEMA].KEY_COLUMN_USAGE b
					 WHERE  a.TABLE_NAME COLLATE Modern_Spanish_CI_AS = b.TABLE_NAME COLLATE Modern_Spanish_CI_AS 
					 AND  a.COLUMN_NAME COLLATE Modern_Spanish_CI_AS = b.COLUMN_NAME COLLATE Modern_Spanish_CI_AS
					 AND  a.CONSTRAINT_NAME COLLATE Modern_Spanish_CI_AS = b.CONSTRAINT_NAME COLLATE Modern_Spanish_CI_AS
					 AND a.TABLE_NAME NOT LIKE ''z%''
					 AND a.TABLE_NAME NOT IN (''userinfo'',''userinfo_attarea'',''GV02ART'',''acc_levelset_emp'')
					 AND (a.ORDINAL_POSITION  <> b.ORDINAL_POSITION ) 
					 ORDER BY a.TABLE_NAME, a.COLUMN_NAME '

	PRINT @Sql
	EXECUTE sp_executesql  @Sql
END

/*

EXEC CP_DB_Check 'Clever_CDA','Clever_Ferro'
o
EXEC CP_DB_Check 'Clever_CDA','Clever_Ferro','*'   --toda la info

EXEC CP_DB_Check 'Clever_CDA','Clever_Ferro','T'   --tablas faltantes

EXEC CP_DB_Check 'Clever_CDA','Clever_Ferro','CF'   --campos faltantes

EXEC CP_DB_Check 'Clever_CDA','Clever_Ferro','CD'   --campos diferentes

EXEC CP_DB_Check 'Clever_CDA','Clever_Ferro','KD'   --CONSTRAINTS faltantes

EXEC CP_DB_Check 'Clever_CDA','Clever_Ferro','KF'   --CONSTRAINTS diferentes


*/
GO


CREATE PROCEDURE dbo.CP_DB_CloneLogin
  @NewLogin sysname,
  @NewLoginPwd NVARCHAR(MAX),
  @WindowsLogin CHAR(1),
  @LoginToClone sysname
AS BEGIN

SET NOCOUNT ON;

DECLARE @SQL nvarchar(MAX);
DECLARE @Men varchar(MAX);
DECLARE @Return int;
DECLARE @Ver DECIMAL(5,2);

SET @Ver = dbo.CF_DB_Version();

IF EXISTS (SELECT * FROM sys.server_principals WHERE name = @NewLogin AND type_desc = 'SQL_LOGIN')
BEGIN
	RETURN(0);
END

IF NOT EXISTS (SELECT * FROM sys.server_principals WHERE name = @LoginToClone AND type_desc = 'SQL_LOGIN')
BEGIN
	SET @Men = 'Error encountered creating login: ' + @LoginToClone +' doesn´t exist.'
	RAISERROR(@Men, 16, 1);
	RETURN(1);
END

IF (@WindowsLogin = 'T')
	SET @SQL = 'CREATE LOGIN [' + @NewLogin + '] FROM WINDOWS;'
ELSE
	SET @SQL = 'CREATE LOGIN [' + @NewLogin + '] WITH PASSWORD = N''' + @NewLoginPwd + ''';';

IF @Ver >= 12
	BEGIN TRAN;

PRINT @SQL;
EXEC @Return = sp_executesql @SQL;

IF (@Return <> 0)
BEGIN
	IF @Ver >= 12
		ROLLBACK TRAN;
	RAISERROR('Error encountered creating login', 16, 1);
	RETURN(1);
END


-- Query to handle server roles
DECLARE cursRoleMemberSQL CURSOR FAST_FORWARD
FOR
SELECT 'EXEC sp_addsrvrolemember @loginame = ''' + @NewLogin 
			+ ''', @rolename = ''' + R.name + ''';' AS 'SQL'
FROM sys.server_role_members AS RM
	JOIN sys.server_principals AS L
	ON RM.member_principal_id = L.principal_id
	JOIN sys.server_principals AS R
	ON RM.role_principal_id = R.principal_id
WHERE L.name = @LoginToClone;

OPEN cursRoleMemberSQL;

FETCH FROM cursRoleMemberSQL INTO @SQL;

WHILE (@@FETCH_STATUS = 0)
BEGIN
	PRINT @SQL;
	EXECUTE @Return = sp_executesql @SQL;

	IF (@Return <> 0)
	BEGIN
		IF @Ver >= 12
			ROLLBACK TRAN;
		RAISERROR('Error encountered assigning role memberships.', 16, 1);
		CLOSE cursRoleMembersSQL;
		DEALLOCATE cursRoleMembersSQL;
		RETURN(1);
	END

	FETCH NEXT FROM cursRoleMemberSQL INTO @SQL;
END;

CLOSE cursRoleMemberSQL;
DEALLOCATE cursRoleMemberSQL;

DECLARE cursServerPermissionSQL CURSOR FAST_FORWARD
FOR
SELECT CASE P.state WHEN 'W' THEN 
			'USE master; GRANT ' + P.permission_name + ' TO [' + @NewLogin + '] WITH GRANT OPTION;'
		ELSE 
			'USE master;  ' + P.state_desc + ' ' + P.permission_name + ' TO [' + @NewLogin + '];'   
		END AS 'SQL'
FROM sys.server_permissions AS P
	JOIN sys.server_principals AS L
	ON P.grantee_principal_id = L.principal_id
WHERE L.name = @LoginToClone
	AND P.class = 100
	AND P.type <> 'COSQ'
UNION ALL
SELECT CASE P.state WHEN 'W' THEN 
			'USE master; GRANT ' + P.permission_name + ' ON LOGIN::[' + L2.name + 
			'] TO [' + @NewLogin + '] WITH GRANT OPTION;' COLLATE DATABASE_DEFAULT
		ELSE 
			'USE master; ' + P.state_desc + ' ' + P.permission_name + ' ON LOGIN::[' + L2.name 
			+ '] TO [' + @NewLogin + '];' COLLATE DATABASE_DEFAULT
		END AS 'SQL'
FROM sys.server_permissions AS P
	JOIN sys.server_principals AS L
	ON P.grantee_principal_id = L.principal_id
	JOIN sys.server_principals AS L2
	ON P.major_id = L2.principal_id
WHERE L.name = @LoginToClone
	AND P.class = 101
UNION ALL
SELECT CASE P.state WHEN 'W' THEN 
			'USE master; GRANT ' + P.permission_name + ' ON ENDPOINT::[' + E.name + 
			'] TO [' + @NewLogin + '] WITH GRANT OPTION;' COLLATE DATABASE_DEFAULT
		ELSE 
			'USE master; ' + P.state_desc + ' ' + P.permission_name + ' ON ENDPOINT::[' + E.name 
			+ '] TO [' + @NewLogin + '];' COLLATE DATABASE_DEFAULT
		END AS 'SQL'
FROM sys.server_permissions AS P
	JOIN sys.server_principals AS L
	ON P.grantee_principal_id = L.principal_id
	JOIN sys.endpoints AS E
	ON P.major_id = E.endpoint_id
WHERE L.name = @LoginToClone
	AND P.class = 105;

OPEN cursServerPermissionSQL;

FETCH FROM cursServerPermissionSQL INTO @SQL;

WHILE (@@FETCH_STATUS = 0)
BEGIN
	PRINT @SQL;
	EXEC @Return = sp_executesql @SQL;

	IF (@Return <> 0)
	BEGIN
	    IF @Ver >= 12
		   ROLLBACK TRAN;
		RAISERROR('Error encountered adding server level permissions', 16, 1);
		CLOSE cursServerPermissionSQL;
		DEALLOCATE cursServerPermissionSQL;
		RETURN(1);
	END

	FETCH NEXT FROM cursServerPermissionSQL INTO @SQL;
END;

CLOSE cursServerPermissionSQL;
DEALLOCATE cursServerPermissionSQL;

IF @Ver >= 12
	COMMIT TRAN;

PRINT 'Login [' + @NewLogin + '] cloned successfully from [' + @LoginToClone + '].';
END;
GO


CREATE PROCEDURE dbo.CP_DB_CloneLoginAndPerm
  @NewLogin sysname,
  @NewLoginPwd NVARCHAR(MAX),
  @WindowsLogin CHAR(1),
  @LoginToClone sysname,
  @pDBName sysname
AS
BEGIN
SET NOCOUNT ON;

DECLARE @Return int;
DECLARE @SQL nvarchar(MAX);

BEGIN TRAN;

EXEC @Return = dbo.CP_DB_CloneLogin 
@NewLogin = @NewLogin, 
@NewLoginPwd = @NewLoginPwd, 
@WindowsLogin = @WindowsLogin, 
@LoginToClone = @LoginToClone;

IF (@Return <> 0)
BEGIN
	ROLLBACK TRAN;
	RAISERROR('Exiting because login could not be created', 16, 1);
	RETURN(1);
END

SET @SQL= 'ALTER LOGIN ['+ @NewLogin +'] WITH PASSWORD = '''+ @NewLoginPwd +''';'
EXEC @Return = sp_executesql @SQL;
IF (@Return <> 0)
BEGIN
	ROLLBACK TRAN;
	RAISERROR('Error updating login password', 16, 1);
	RETURN(1);
END

EXEC @Return = dbo.CP_DB_CreateUser 
	@NewLogin = @NewLogin, 
	@DBName = @pDBName;

IF (@Return <> 0)
BEGIN
	ROLLBACK TRAN;
	RAISERROR('Exiting because user could not be created.', 16, 1);
	RETURN(1);
END;

EXEC @Return = dbo.CP_DB_GrantUserRoleMember
	@NewLogin = @NewLogin, 
	@LoginToClone = @LoginToClone, 
	@DBName = @pDBName;

IF (@Return <> 0)
BEGIN
	ROLLBACK TRAN;
	RAISERROR('Exiting because role meberships could not be granted.', 16, 1);
	RETURN(1);
END;

EXEC @Return = dbo.CP_DB_ClonePerms
	@NewLogin = @NewLogin, 
	@LoginToClone = @LoginToClone, 
	@DBName = @pDBName;

IF (@Return <> 0)
BEGIN
	ROLLBACK TRAN;
	RAISERROR('Exiting because permisions could not be created.', 16, 1);
	RETURN(1);
END;



COMMIT TRAN;
END;
GO


CREATE PROCEDURE dbo.CP_DB_ClonePerms
  @NewLogin sysname,
  @LoginToClone sysname,
  @DBName sysname
AS
BEGIN
SET NOCOUNT ON;

DECLARE @SQL nvarchar(max);
DECLARE @Return int;
DECLARE @Ver DECIMAL(5,2);

SET @Ver = dbo.CF_DB_Version();

CREATE TABLE #DBPermissionsTSQL (PermsTSQL nvarchar(MAX));


SET @SQL = 'INSERT INTO #DBPermissionsTSQL (PermsTSQL) 
				SELECT CASE [state]
					WHEN ''W'' THEN ''GRANT '' + permission_name + '' ON DATABASE::[' 
						+ @DBName + '] TO [' + @NewLogin + '] WITH GRANT OPTION;'' COLLATE DATABASE_DEFAULT
					ELSE state_desc + '' '' + permission_name + '' ON DATABASE::[' 
						+ @DBNAME + '] TO [' + @NewLogin + '];'' COLLATE DATABASE_DEFAULT
					END AS ''Permission''
				FROM [' + @DBName + '].sys.database_permissions AS P
					JOIN [' + @DBName + '].sys.database_principals AS U
					ON P.grantee_principal_id = U.principal_id
				WHERE class = 0
					AND P.[type] <> ''CO''
					AND U.name = ''' + @LoginToClone + ''';';

EXECUTE @Return = sp_executesql @SQL;

IF (@Return <> 0)
BEGIN
	IF @Ver >= 12
		ROLLBACK TRAN;
	RAISERROR('Error encountered building permissions.', 16, 1);
	RETURN(1);
END

SET @SQL = 'INSERT INTO #DBPermissionsTSQL (PermsTSQL)
				SELECT CASE [state]
					WHEN ''W'' THEN ''GRANT '' + permission_name + '' ON SCHEMA::['' 
						+ S.name + ''] TO [' + @NewLogin + '] WITH GRANT OPTION;'' COLLATE DATABASE_DEFAULT
					ELSE state_desc + '' '' + permission_name + '' ON SCHEMA::['' 
						+ S.name + ''] TO [' + @NewLogin + '];'' COLLATE DATABASE_DEFAULT
					END AS ''Permission''
				FROM [' + @DBName + '].sys.database_permissions AS P
					JOIN [' + @DBName + '].sys.database_principals AS U
					ON P.grantee_principal_id = U.principal_id
					JOIN [' + @DBName + '].sys.schemas AS S
					ON S.schema_id = P.major_id
				WHERE class = 3
					AND U.name = ''' + @LoginToClone + ''';';

EXECUTE @Return = sp_executesql @SQL;

IF (@Return <> 0)
BEGIN
	IF @Ver >= 12
		ROLLBACK TRAN;
	RAISERROR('Error encountered building permissions.', 16, 1);
	RETURN(1);
END

SET @SQL = 'INSERT INTO #DBPermissionsTSQL (PermsTSQL) 
				SELECT CASE [state]
					WHEN ''W'' THEN ''GRANT '' + permission_name + '' ON OBJECT::['' 
						+ O.name + ''] TO [' + @NewLogin + '] WITH GRANT OPTION;'' COLLATE DATABASE_DEFAULT
					ELSE state_desc + '' '' + permission_name + '' ON OBJECT::['' 
						+ O.name + ''] TO [' + @NewLogin + '];'' COLLATE DATABASE_DEFAULT
					END AS ''Permission''
				FROM [' + @DBName + '].sys.database_permissions AS P
					JOIN [' + @DBName + '].sys.database_principals AS U
					ON P.grantee_principal_id = U.principal_id
					JOIN [' + @DBName + '].sys.objects AS O
					ON O.object_id = P.major_id
				WHERE class = 1
					AND U.name = ''' + @LoginToClone + '''
					AND P.major_id > 0
					AND P.minor_id = 0';

EXECUTE @Return = sp_executesql @SQL;

IF (@Return <> 0)
BEGIN
	IF @Ver >= 12
		ROLLBACK TRAN;
	RAISERROR('Error encountered building permissions.', 16, 1);
	RETURN(1);
END

SET @SQL = 'INSERT INTO #DBPermissionsTSQL (PermsTSQL)
				SELECT CASE [state]
					WHEN ''W'' THEN ''GRANT '' + permission_name + '' ON OBJECT::['' 
						+ O.name + ''] ('' + C.name + '') TO [' + @NewLogin + '] WITH GRANT OPTION;'' 
						COLLATE DATABASE_DEFAULT
					ELSE state_desc + '' '' + permission_name + '' ON OBJECT::['' 
						+ O.name + ''] ('' + C.name + '') TO [' + @NewLogin + '];'' 
						COLLATE DATABASE_DEFAULT
					END AS ''Permission''
				FROM [' + @DBName + '].sys.database_permissions AS P
					JOIN [' + @DBName + '].sys.database_principals AS U
					ON P.grantee_principal_id = U.principal_id
					JOIN [' + @DBName + '].sys.objects AS O
					ON O.object_id = P.major_id
					JOIN [' + @DBName + '].sys.columns AS C
					ON C.column_id = P.minor_id AND o.object_id = C.object_id
				WHERE class = 1
					AND U.name = ''' + @LoginToClone + '''
					AND P.major_id > 0
					AND P.minor_id > 0;'
	
EXECUTE @Return = sp_executesql @SQL;

IF (@Return <> 0)
BEGIN
	IF @Ver >= 12
		ROLLBACK TRAN;
	RAISERROR('Error encountered building permissions.', 16, 1);
	RETURN(1);
END

SET @SQL = 'INSERT INTO #DBPermissionsTSQL (PermsTSQL) 
				SELECT CASE [state]
					WHEN ''W'' THEN ''GRANT '' + permission_name + '' ON USER::['' 
						+ U2.name + ''] TO [' + @NewLogin + '] WITH GRANT OPTION;'' COLLATE DATABASE_DEFAULT
					ELSE state_desc + '' '' + permission_name + '' ON USER::['' 
						+ U2.name + ''] TO [' + @NewLogin + '];'' COLLATE DATABASE_DEFAULT
					END AS ''Permission''
				FROM [' + @DBName + '].sys.database_permissions AS P
					JOIN [' + @DBName + '].sys.database_principals AS U
					ON P.grantee_principal_id = U.principal_id
					JOIN [' + @DBName + '].sys.database_principals AS U2
					ON U2.principal_id = P.major_id
				WHERE class = 4
					AND U.name = ''' + @LoginToClone + ''';';

EXECUTE @Return = sp_executesql @SQL;

IF (@Return <> 0)
BEGIN
	IF @Ver >= 12
		ROLLBACK TRAN;
	RAISERROR('Error encountered building permissions.', 16, 1);
	RETURN(1);
END

SET @SQL = 'INSERT INTO #DBPermissionsTSQL (PermsTSQL)
				SELECT CASE [state]
					WHEN ''W'' THEN ''GRANT '' + permission_name + '' ON SYMMETRIC KEY::['' 
						+ K.name + ''] TO [' + @NewLogin + '] WITH GRANT OPTION;'' COLLATE DATABASE_DEFAULT
					ELSE state_desc + '' '' + permission_name + '' ON SYMMETRIC KEY::['' 
						+ K.name + ''] TO [' + @NewLogin + '];'' COLLATE DATABASE_DEFAULT
					END AS ''Permission''
				FROM [' + @DBName + '].sys.database_permissions AS P
					JOIN [' + @DBName + '].sys.database_principals AS U
					ON P.grantee_principal_id = U.principal_id
					JOIN [' + @DBName + '].sys.symmetric_keys AS K
					ON P.major_id = K.symmetric_key_id
				WHERE class = 24
					AND U.name = ''' + @LoginToClone + ''';';

EXECUTE @Return = sp_executesql @SQL;

IF (@Return <> 0)
BEGIN
	IF @Ver >= 12
		ROLLBACK TRAN;
	RAISERROR('Error encountered building permissions.', 16, 1);
	RETURN(1);
END

SET @SQL = 'INSERT INTO #DBPermissionsTSQL (PermsTSQL) 
				SELECT CASE [state]
					WHEN ''W'' THEN ''GRANT '' + permission_name + '' ON ASYMMETRIC KEY::['' 
						+ K.name + ''] TO [' + @NewLogin + '] WITH GRANT OPTION;'' COLLATE DATABASE_DEFAULT
					ELSE state_desc + '' '' + permission_name + '' ON ASYMMETRIC KEY::['' 
						+ K.name + ''] TO [' + @NewLogin + '];'' COLLATE DATABASE_DEFAULT
					END AS ''Permission''
				FROM [' + @DBName + '].sys.database_permissions AS P
					JOIN [' + @DBName + '].sys.database_principals AS U
					ON P.grantee_principal_id = U.principal_id
					JOIN [' + @DBName + '].sys.asymmetric_keys AS K
					ON P.major_id = K.asymmetric_key_id
				WHERE class = 26
					AND U.name = ''' + @LoginToClone + ''';';
	
EXECUTE @Return = sp_executesql @SQL;

IF (@Return <> 0)
BEGIN
	IF @Ver >= 12
		ROLLBACK TRAN;
	RAISERROR('Error encountered building permissions.', 16, 1);
	RETURN(1);
END

SET @SQL = 'INSERT INTO #DBPermissionsTSQL (PermsTSQL) 
				SELECT CASE [state]
					WHEN ''W'' THEN ''GRANT '' + permission_name + '' ON CERTIFICATE::['' 
						+ C.name + ''] TO [' + @NewLogin + '] WITH GRANT OPTION;'' COLLATE DATABASE_DEFAULT
					ELSE state_desc + '' '' + permission_name + '' ON CERTIFICATE::['' 
						+ C.name + ''] TO [' + @NewLogin + '];'' COLLATE DATABASE_DEFAULT
					END AS ''Permission''
				FROM [' + @DBName + '].sys.database_permissions AS P
					JOIN [' + @DBName + '].sys.database_principals AS U
					ON P.grantee_principal_id = U.principal_id
					JOIN [' + @DBName + '].sys.certificates AS C
					ON P.major_id = C.certificate_id
				WHERE class = 25
					AND U.name = ''' + @LoginToClone + ''';';

EXECUTE @Return = sp_executesql @SQL;

IF (@Return <> 0)
BEGIN
	IF @Ver >= 12
		ROLLBACK TRAN;
	RAISERROR('Error encountered building permissions.', 16, 1);
	RETURN(1);
END

DECLARE cursDBPermsSQL CURSOR FAST_FORWARD
FOR
SELECT PermsTSQL FROM #DBPermissionsTSQL

OPEN cursDBPermsSQL;

FETCH FROM cursDBPermsSQL INTO @SQL;

WHILE (@@FETCH_STATUS = 0)
BEGIN
	SET @SQL = 'USE [' + @DBName + ']; ' + @SQL;

	PRINT @SQL;
	EXEC @Return = sp_executesql @SQL;

	IF (@Return <> 0)
	BEGIN
		IF @Ver >= 12
			ROLLBACK TRAN;
		RAISERROR('Error granting permission', 16, 1);
		CLOSE cursDBPermsSQL;
		DEALLOCATE cursDBPermsSQL;
		RETURN(1);
	END;

	FETCH NEXT FROM cursDBPermsSQL INTO @SQL;
END;

CLOSE cursDBPermsSQL;
DEALLOCATE cursDBPermsSQL;
DROP TABLE #DBPermissionsTSQL;
END;
GO


CREATE PROCEDURE dbo.CP_DB_CreateUser
  @NewLogin sysname,
  @DBName sysname
AS
BEGIN
SET NOCOUNT ON;

DECLARE @TSQL nvarchar(MAX);
DECLARE @Return int;
DECLARE @Ver DECIMAL(5,2);

SET @Ver = dbo.CF_DB_Version();

IF NOT EXISTS (SELECT * FROM sys.server_principals WHERE name = @NewLogin AND type_desc = 'SQL_LOGIN')
BEGIN
	RAISERROR('Error creating user not exist LoginToClone', 16, 1);
	RETURN(1);
END

IF @Ver >= 12
	BEGIN TRAN; 

SET @TSQL = 'USE [' + @DBName + ']; IF NOT EXISTS(SELECT name FROM sys.database_principals WHERE name = ''' + @NewLogin + ''') 
                BEGIN
				IF NOT EXISTS(SELECT name FROM sys.database_principals WHERE name = ''' + @NewLogin + ''') 
				    CREATE USER [' + @NewLogin + '] FROM LOGIN [' + @NewLogin + '];
				END;';
EXEC @Return = sp_executesql @TSQL;

IF (@Return <> 0)
BEGIN
	IF @Ver >= 12
		ROLLBACK TRAN;
	RAISERROR('Error creating user', 16, 1);
	RETURN(1);
END;

IF @Ver >= 12
	COMMIT TRAN;
END;
GO


CREATE PROC dbo.CP_DB_GrantUserRoleMember
  @NewLogin sysname,
  @LoginToClone sysname,
  @DBName sysname
AS
BEGIN
SET NOCOUNT ON;

DECLARE @TSQL nvarchar(MAX);
DECLARE @Return int;
DECLARE @Ver DECIMAL(5,2);

SET @Ver = dbo.CF_DB_Version();

IF @Ver >= 12
	BEGIN TRAN; 

CREATE TABLE #RoleMembershipSQL  (RoleMembersTSQL nvarchar(MAX));

SET @TSQL = 'INSERT INTO #RoleMembershipSQL (RoleMembersTSQL) 
				SELECT ''EXEC sp_addrolemember @rolename = '''''' + r.name 
					+ '''''', @membername = ''''' + @NewLogin + ''''';''
				FROM [' + @DBName + '].sys.database_principals AS U
					JOIN [' + @DBName + '].sys.database_role_members AS RM
					ON U.principal_id = RM.member_principal_id
					JOIN [' + @DBName + '].sys.database_principals AS R
					ON RM.role_principal_id = R.principal_id
				WHERE U.name = ''' + @LoginToClone + ''';';

EXEC @Return = sp_executesql @TSQL;

IF (@Return <> 0)
BEGIN
	IF @Ver >= 12
		ROLLBACK TRAN; 
	RAISERROR('Could not retrieve role memberships.', 16, 1);
	RETURN(1)
END;

DECLARE cursDBRoleMembersSQL CURSOR FAST_FORWARD FOR SELECT RoleMembersTSQL FROM #RoleMembershipSQL;
OPEN cursDBRoleMembersSQL;
FETCH FROM cursDBRoleMembersSQL INTO @TSQL;
WHILE (@@FETCH_STATUS = 0)
BEGIN
	SET @TSQL = 'USE [' + @DBName + ']; ' + @TSQL;
    EXECUTE @Return = sp_executesql @TSQL;

    IF (@RETURN <> 0)
    BEGIN
        IF @Ver >= 12
			ROLLBACK TRAN;
	    RAISERROR('Error encountered assigning DB role memberships.', 16, 1);
		CLOSE cursDBRoleMembersSQL;
		DEALLOCATE cursDBRoleMembersSQL;
    END;

    FETCH NEXT FROM cursDBRoleMembersSQL INTO @TSQL;
END;

CLOSE cursDBRoleMembersSQL;
DEALLOCATE cursDBRoleMembersSQL;

DROP TABLE #RoleMembershipSQL;

IF @Ver >= 12
	COMMIT TRAN;
END;
GO


CREATE PROCEDURE CP_DB_Model
AS


SET NOCOUNT ON;

DECLARE @Tag nvarchar(100) = N'SNAPSHOT'; -- pon├® 'MODELO' o 'CLIENTE' para identificar

IF OBJECT_ID('tempdb..#Snapshot') IS NOT NULL DROP TABLE #Snapshot;
CREATE TABLE #Snapshot (
    Tag        nvarchar(100) NOT NULL,
    DbName     sysname NOT NULL,
    ObjType    varchar(20) NOT NULL,   -- INDEX / PK / UQ / FK / CK / DF
    SchemaName sysname NOT NULL,
    TableName  sysname NOT NULL,
    ObjName    sysname NOT NULL,
    Def        nvarchar(max) NOT NULL,
    DefHash    varbinary(32) NOT NULL
);

--------------------------------------------------------------------------------
-- INDEXES
--------------------------------------------------------------------------------
;WITH idx AS (
    SELECT
        s.name AS SchemaName,
        t.name AS TableName,
        i.name AS IndexName,
        i.object_id,
        i.index_id,
        i.type_desc,
        i.is_unique,
        i.is_primary_key,
        i.has_filter,
        i.filter_definition
    FROM sys.indexes i
    JOIN sys.tables t ON t.object_id = i.object_id
    JOIN sys.schemas s ON s.schema_id = t.schema_id
    WHERE i.index_id > 0
      AND t.is_ms_shipped = 0
      AND i.is_hypothetical = 0
      AND i.name IS NOT NULL
),
cols AS (
    SELECT
        ic.object_id,
        ic.index_id,
        ic.is_included_column,
        ic.is_descending_key,
        ic.key_ordinal,
        c.name AS ColumnName
    FROM sys.index_columns ic
    JOIN sys.columns c
      ON c.object_id = ic.object_id
     AND c.column_id = ic.column_id
)
INSERT INTO #Snapshot (Tag, DbName, ObjType, SchemaName, TableName, ObjName, Def, DefHash)
SELECT
    @Tag,
    DB_NAME(),
    'INDEX',
    i.SchemaName,
    i.TableName,
    i.IndexName,
    Def = CONCAT(
        i.type_desc, '|U=', i.is_unique, '|PK=', i.is_primary_key,
        '|KEYS=',
        COALESCE(STUFF((
            SELECT ',' + c.ColumnName + CASE WHEN c.is_descending_key = 1 THEN ' DESC' ELSE ' ASC' END
            FROM cols c
            WHERE c.object_id = i.object_id AND c.index_id = i.index_id
              AND c.is_included_column = 0
            ORDER BY c.key_ordinal
            FOR XML PATH(''), TYPE).value('.','nvarchar(max)'), 1, 1, ''), ''),
        '|INCLUDES=',
        COALESCE(STUFF((
            SELECT ',' + c.ColumnName
            FROM cols c
            WHERE c.object_id = i.object_id AND c.index_id = i.index_id
              AND c.is_included_column = 1
            ORDER BY c.ColumnName
            FOR XML PATH(''), TYPE).value('.','nvarchar(max)'), 1, 1, ''), ''),
        '|FILTER=', COALESCE(i.filter_definition,'')
    ),
    DefHash = HASHBYTES('SHA2_256', CONVERT(nvarchar(max),
        CONCAT(
            i.type_desc, '|U=', i.is_unique, '|PK=', i.is_primary_key,
            '|K=',
            COALESCE(STUFF((
                SELECT ',' + c.ColumnName + CASE WHEN c.is_descending_key = 1 THEN ' DESC' ELSE ' ASC' END
                FROM cols c
                WHERE c.object_id = i.object_id AND c.index_id = i.index_id
                  AND c.is_included_column = 0
                ORDER BY c.key_ordinal
                FOR XML PATH(''), TYPE).value('.','nvarchar(max)'), 1, 1, ''), ''),
            '|I=',
            COALESCE(STUFF((
                SELECT ',' + c.ColumnName
                FROM cols c
                WHERE c.object_id = i.object_id AND c.index_id = i.index_id
                  AND c.is_included_column = 1
                ORDER BY c.ColumnName
                FOR XML PATH(''), TYPE).value('.','nvarchar(max)'), 1, 1, ''), ''),
            '|F=', COALESCE(i.filter_definition,'')
        )
    ))
FROM idx i;

--------------------------------------------------------------------------------
-- PK / UQ
--------------------------------------------------------------------------------
;WITH kc AS (
    SELECT
        CASE WHEN k.type = 'PK' THEN 'PK' ELSE 'UQ' END AS ObjType,
        s.name AS SchemaName,
        t.name AS TableName,
        k.name AS ObjName,
        i.object_id,
        i.index_id
    FROM sys.key_constraints k
    JOIN sys.tables t ON t.object_id = k.parent_object_id
    JOIN sys.schemas s ON s.schema_id = t.schema_id
    JOIN sys.indexes i ON i.object_id = k.parent_object_id AND i.index_id = k.unique_index_id
    WHERE t.is_ms_shipped = 0
),
kcc AS (
    SELECT
        ic.object_id, ic.index_id, ic.key_ordinal, c.name AS ColumnName
    FROM sys.index_columns ic
    JOIN sys.columns c
      ON c.object_id = ic.object_id AND c.column_id = ic.column_id
    WHERE ic.is_included_column = 0
)
INSERT INTO #Snapshot (Tag, DbName, ObjType, SchemaName, TableName, ObjName, Def, DefHash)
SELECT
    @Tag,
    DB_NAME(),
    kc.ObjType,
    kc.SchemaName,
    kc.TableName,
    kc.ObjName,
    Def = CONCAT('COLS=',
        COALESCE(STUFF((
            SELECT ',' + ColumnName
            FROM kcc
            WHERE object_id = kc.object_id AND index_id = kc.index_id
            ORDER BY key_ordinal
            FOR XML PATH(''), TYPE).value('.','nvarchar(max)'), 1, 1, ''), '')
    ),
    DefHash = HASHBYTES('SHA2_256', CONVERT(nvarchar(max),
        COALESCE(STUFF((
            SELECT ',' + ColumnName
            FROM kcc
            WHERE object_id = kc.object_id AND index_id = kc.index_id
            ORDER BY key_ordinal
            FOR XML PATH(''), TYPE).value('.','nvarchar(max)'), 1, 1, ''), '')
    ))
FROM kc;

--------------------------------------------------------------------------------
-- CHECK (CK)
--------------------------------------------------------------------------------
INSERT INTO #Snapshot (Tag, DbName, ObjType, SchemaName, TableName, ObjName, Def, DefHash)
SELECT
    @Tag, DB_NAME(),
    'CK',
    s.name, t.name, cc.name,
    Def = cc.definition,
    DefHash = HASHBYTES('SHA2_256', CONVERT(nvarchar(max), cc.definition))
FROM sys.check_constraints cc
JOIN sys.tables t ON t.object_id = cc.parent_object_id
JOIN sys.schemas s ON s.schema_id = t.schema_id
WHERE t.is_ms_shipped = 0;

--------------------------------------------------------------------------------
-- DEFAULT (DF)
--------------------------------------------------------------------------------
INSERT INTO #Snapshot (Tag, DbName, ObjType, SchemaName, TableName, ObjName, Def, DefHash)
SELECT
    @Tag, DB_NAME(),
    'DF',
    s.name, t.name, dc.name,
    Def = CONCAT(c.name, '=', dc.definition),
    DefHash = HASHBYTES('SHA2_256', CONVERT(nvarchar(max), CONCAT(c.name, '=', dc.definition)))
FROM sys.default_constraints dc
JOIN sys.tables t ON t.object_id = dc.parent_object_id
JOIN sys.schemas s ON s.schema_id = t.schema_id
JOIN sys.columns c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id
WHERE t.is_ms_shipped = 0;

--------------------------------------------------------------------------------
-- FOREIGN KEYS (FK)
--------------------------------------------------------------------------------
;WITH fk AS (
    SELECT
        s.name AS SchemaName,
        t.name AS TableName,
        f.name AS ObjName,
        f.object_id,
        s2.name AS RefSchemaName,
        t2.name AS RefTableName
    FROM sys.foreign_keys f
    JOIN sys.tables t ON t.object_id = f.parent_object_id
    JOIN sys.schemas s ON s.schema_id = t.schema_id
    JOIN sys.tables t2 ON t2.object_id = f.referenced_object_id
    JOIN sys.schemas s2 ON s2.schema_id = t2.schema_id
    WHERE t.is_ms_shipped = 0
),
fkc AS (
    SELECT
        fkc.constraint_object_id,
        fkc.constraint_column_id,
        pc.name AS ParentCol,
        rc.name AS RefCol
    FROM sys.foreign_key_columns fkc
    JOIN sys.columns pc ON pc.object_id = fkc.parent_object_id AND pc.column_id = fkc.parent_column_id
    JOIN sys.columns rc ON rc.object_id = fkc.referenced_object_id AND rc.column_id = fkc.referenced_column_id
)
INSERT INTO #Snapshot (Tag, DbName, ObjType, SchemaName, TableName, ObjName, Def, DefHash)
SELECT
    @Tag, DB_NAME(),
    'FK',
    fk.SchemaName, fk.TableName, fk.ObjName,
    Def = CONCAT(
        'REF=', fk.RefSchemaName, '.', fk.RefTableName,
        '|MAP=',
        COALESCE(STUFF((
            SELECT ',' + ParentCol + '->' + RefCol
            FROM fkc
            WHERE constraint_object_id = fk.object_id
            ORDER BY constraint_column_id
            FOR XML PATH(''), TYPE).value('.','nvarchar(max)'), 1, 1, ''), '')
    ),
    DefHash = HASHBYTES('SHA2_256', CONVERT(nvarchar(max),
        CONCAT(
            fk.RefSchemaName, '.', fk.RefTableName, '|',
            COALESCE(STUFF((
                SELECT ',' + ParentCol + '->' + RefCol
                FROM fkc
                WHERE constraint_object_id = fk.object_id
                ORDER BY constraint_column_id
                FOR XML PATH(''), TYPE).value('.','nvarchar(max)'), 1, 1, ''), '')
        )
    ))
FROM fk;

--------------------------------------------------------------------------------
-- OUTPUT FINAL (ordenado y "diff-friendly")
--------------------------------------------------------------------------------
SELECT
    Tag,
    DbName,
    ObjType,
    SchemaName,
    TableName,
    ObjName,
    DefHash = CONVERT(varchar(64), DefHash, 2),
    Def
FROM #Snapshot
ORDER BY ObjType, SchemaName, TableName, ObjName;



