EXEC CP_DB_Model

*/
GO



CREATE PROCEDURE dbo.CP_DB_Table_BackUp @Tabla VARCHAR(128)
AS 
DECLARE @Nombre			VARCHAR(255)
DECLARE @Sql			VARCHAR(8000)
DECLARE @Mensaje		VARCHAR(100)
DECLARE @ErrorLine		INT
DECLARE @ErrorNumber	INT

BEGIN TRY
	BEGIN TRAN

	SET @Nombre = 'z_'+ @Tabla +'_'+ 
					convert(varchar(19),GETDATE(),12) +'_' + 
					SUBSTRING(convert(varchar(19),GETDATE(),108),1,2) +
					SUBSTRING(convert(varchar(19),GETDATE(),108),4,2) +
					SUBSTRING(convert(varchar(19),GETDATE(),108),7,2) 
	--select * INTO  CAST(@Nombre AS sysname) FROM @Tabla

	SET @Sql = 'SELECT * INTO '+ @Nombre  + ' FROM '+ @Tabla
	EXECUTE (@Sql)

    COMMIT
	SET @ErrorNumber = 0 
	SET @ErrorLine = 0
	SET @Mensaje = 'Table '+ @Nombre + ' created.'

	SELECT	 @ErrorNumber	AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,@ErrorLine		AS ErrorLine		
			,@Mensaje		AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO



CREATE PROCEDURE CP_DB_Tables_Records_View
       AS 
        SELECT 
    X.[name], 
    REPLACE(CONVERT(varchar, CONVERT(money, X.[rows]), 1), '.00', '') 
        AS [rows], 
    REPLACE(CONVERT(varchar, CONVERT(money, X.[reserved]), 1), '.00', '') 
        AS [reserved], 
    REPLACE(CONVERT(varchar, CONVERT(money, X.[data]), 1), '.00', '') 
        AS [data], 
    REPLACE(CONVERT(varchar, CONVERT(money, X.[index_size]), 1), '.00', '') 
        AS [index_size], 
    REPLACE(CONVERT(varchar, CONVERT(money, X.[unused]), 1), '.00', '') 
        AS [unused] 
FROM 
(SELECT 
    CAST(object_name(id) AS varchar(50)) 
        AS [name], 
    SUM(CASE WHEN indid < 2 THEN CONVERT(bigint, [rows]) END) 
        AS [rows],
    SUM(CONVERT(bigint, reserved)) * 8 
        AS reserved, 
    SUM(CONVERT(bigint, dpages)) * 8 
        AS data, 
    SUM(CONVERT(bigint, used) - CONVERT(bigint, dpages)) * 8 
        AS index_size, 
    SUM(CONVERT(bigint, reserved) - CONVERT(bigint, used)) * 8 
        AS unused 
    FROM sysindexes WITH (NOLOCK) 
    WHERE sysindexes.indid IN (0, 1, 255) 
        AND sysindexes.id > 100 
        AND object_name(sysindexes.id) <> 'dtproperties' 
    GROUP BY sysindexes.id WITH ROLLUP
) AS X
WHERE X.[name] is not null
ORDER BY X.[rows] DESC
GO


CREATE PROCEDURE [dbo].[CP_Estructura_Browse]	@pStoredProcedure	VARCHAR(255)

AS
BEGIN

DECLARE @Combos	VARCHAR(8000)

CREATE TABLE #EstructuraBrowse (Id_Dato			VARCHAR(255),	/*Identificador*/
								Tipo_Dato		VARCHAR(50),	/*VARCHAR | INT | DATE ...*/
								Flag_Dato		CHAR(1),		/*P: Parametro de Entrada | C: Campo Respuesta*/
								Posicion_Dato	SMALLINT,		/*Numero de Posicion de llamada de Parámetro o Posición en Query de Respuesta según corresponda con Flag_Dato*/
								Visible			TINYINT,		/*1: Visible | 0: No Visible. Para Flag_Dato = 'P' se ignora*/
								Filtrable		TINYINT,		/*1: Dato Filtrable | 0: Dato no filtrable*/
								Tipo_Filtro		SMALLINT,		/*Ver Anexo. Para Filtrable = 0 lo ignora*/
								Valores_Combo	VARCHAR(8000)	/*Valores posibles para Tipo_Filtro = 50. Formato: Id,Descripcion;Id,Descripcion...*/
								)

/* Anexo Tipos de Filtro:
 *
 * 10: STRING (Exacto)
 * 11: STRING (Empieza Con)
 * 12: STRING (Con %)
 * 20: Numero Entero (Exacto)
 * 21: Numero Entero (Entre Desde y Hasta)
 * 30: Numero Decimal (Exacto, sin tener en cuenta decimales)
 * 31: Numero Decimal (Entre Desde y Hasta, teniendo en cuenta decimales)
 * 40: Fecha (Sin Tiempo y Exacta)
 * 41: Fecha (Sin Tiempo Entre Desde y Hasta)
 * 42: Fecha (Con Tiempo y Exacta)
 * 43: Fecha (Con Tiempo Entre Desde y Hasta)
 * 44: Hora (Exacta)
 * 45: Hora (Desde y Hasta)
 * 50: Combo (Único)
 * 60: Checkbox (1: Verdadero | 0: Falso)
 * 61: Checkbox (Multiple)
 * 70: Browse Externo (Selección Única)
 * 71: Browse Externo (Selección Múltiple)
 */

IF(@pStoredProcedure NOT IN ('CP_Browse_Cbtes_Pedidos', 'CP_Browse_Clientes_CtaCte', 'CP_Browse_Productos_Precios_Elegir', 'CP_Browse_CD_ES_Log', 'CP_CD_ES_Rpt_Anual_Ingresos', 'CP_Browse_SCA_Clientes_Elegir'))
