CREATE PROCEDURE CP_Eventos_Hospedaje (@pId_Lista_Precio smallInt
                        ,@pId_Sede Smallint
						,@pCodigoSector Char(10)
						,@pFamilia_Habitaciones SmallInt
						,@pFamilia_Mesas SmallInt
						)

AS

  DECLARE @Sql		    VARCHAR(MAX)
  DECLARE @SqlSaldo	    VARCHAR(MAX)
  DECLARE @SqlSelect	VARCHAR(MAX)
  DECLARE @SqlInto	    VARCHAR(MAX)
  DECLARE @SqlFrom	    VARCHAR(MAX)
  DECLARE @SqlWhere  	VARCHAR(MAX)
  DECLARE @SqlGroup	    VARCHAR(MAX)

  SET @SqlSelect = ' SELECT I.Id_Producto,C.ID_CLIENTE,CL.RAZON_SOCIAL,C.Fecha,I.Id_Trans,I.Item,I.Cantidad,CL.Id_Cliente_Ref,CR.Razon_Social,ISNULL(I.Fecha_QA,0),ISNULL(I.Fecha_Venc,0),C.Observacion'

  SET @SqlFrom = ' FROM Cbtes_Items I, Cbtes C, Productos P, Clientes CL, Clientes CR '

  SET @SqlWhere = ' WHERE I.Id_Trans = C.Id_Trans 
                       AND P.Id_Producto = I.Id_Producto
                       and C.Id_cliente = CL.ID_CLiente
                       AND P.ID_FAMILIA IN (' + Cast(@pFamilia_Habitaciones AS VARCHAR(10)) + ') 
                       AND ISNULL(CL.ID_CLIENTE_REF,0) = CR.ID_CLIENTE '

  IF @pId_Sede <> 0				   
	 SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND P.CALLE IN (SELECT codigo FROM EMPRESAS_SEDES_SECTORES WHERE ID_SEDE = ' + CAST(@pId_Sede AS VARCHAR(10)) + ') '
					   
	
  IF @pCodigoSector <> ''				                 
      SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND P.CALLE = ''' + Cast(@pCodigoSector AS VARCHAR(10)) + ''''
	   
  SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND C.Id_trans IN (SELECT DISTINCT(c.id_trans) 
                                        FROM Cbtes_Items I, Cbtes C, Productos P,Cbtes_Tipos T, Prod_Listas_Precios_Items LPI3, Productos P23 
                                        WHERE I.Id_Trans = C.Id_Trans  AND P.Id_Producto = I.Id_Producto AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
                                        AND P.ID_FAMILIA NOT IN ( ' + Cast(@pFamilia_Habitaciones AS VARCHAR(10)) + ',' + Cast(@pFamilia_Mesas AS VARCHAR(10))+ ')
                                        AND T.Compromete_Pedido IN (1,-1) AND C.ID_ESTADO_CBTE IN (1,2,4) 
                                        AND I.ID_PRODUCTO = LPI3.Id_Producto  
                                        AND P23.Id_Producto = LPI3.Id_Producto 
                                        AND P23.Vendible = 1 AND P23.Tipo <> ''L''
                                        AND LPI3.Id_Lista_Precio = ' + Cast(@pId_Lista_Precio as varchar(10)) + ') 
										ORDER BY I.ID_PRODUCTO '

	  SET @Sql = @SqlSelect + '  '+ @SqlFrom + ' ' + @SqlWhere 
	  
	  print @Sql

	  EXEC(@sql)


--exec CP_Eventos_Hospedaje 105,10,'VM',97,98
GO



CREATE PROCEDURE [dbo].[CP_Finan_Creditos](
				@pAmort			CHAR(1)
			,	@pCuotas		SMALLINT
			,	@pTEM			DECIMAL(12,4)
			,	@pCapital		DECIMAL(12,4)
			,	@pFechaDesde	DATETIME
			,	@pNroCutoa		SMALLINT
			,   @Id_Cta_Banco    INT
			,   @Pid_Cliente     INT
			)
AS
 
IF  @pAmort NOT IN ('T','F','A','U')
    RETURN

DECLARE @NroCuota SMALLINT
      , @SaldoInicial	DECIMAL(16,2)
	  , @ValorCuota		DECIMAL(16,2)
	  , @Intereses		DECIMAL(16,2)
	  , @Amortizacion	DECIMAL(16,2) 
	  , @AmortACum		DECIMAL(16,2) 
	  , @SaldoFinal		DECIMAL(16,2)
	  , @Fecha			DATETIME
	  , @DifDias	    TINYINT
	  , @Fecha_Pago     DATETIME
	  , @Id_Cliente			INT
	  , @Razon_Social		VARCHAR(100)
	  , @Id_Cliente_Externo	VARCHAR(14)
	  , @Cuenta_Nro			VARCHAR(50)
	  , @Cuenta_Descrip		VARCHAR(100)
	  , @Imp_Seguro         DECIMAL(16,2)
	  , @Imp_Gastos         DECIMAL(16,2)
	  , @Imp_Final_Cuota    DECIMAL(16,2)
	  , @Iva_Intereses      DECIMAL(16,2)
	  , @Id_Producto_Seg    VARCHAR(14)
	  , @Fecha_Ult_Pago     DATETIME
	  


CREATE TABLE #Result (
	    Fecha				DATETIME
      , NroCuota			SMALLINT 
      , SaldoInicial		DECIMAL(16,2)
	  , ValorCuota			DECIMAL(16,2)
	  , Intereses			DECIMAL(16,2)
	  , Amortizacion		DECIMAL(16,2) 
	  , AmortACum			DECIMAL(16,2) 
	  , SaldoFinal			DECIMAL(16,2)
	  , FechaPago			DATETIME
	  , Id_Cliente			INT
	  , Razon_Social		VARCHAR(100)
	  , Id_Cliente_Externo	VARCHAR(14)
	  , Id_Cta_Banco		SMALLINT
	  , Cuenta_Nro			VARCHAR(50)
	  , Cuenta_Descrip		VARCHAR(100)
	  , Imp_Seguro          DECIMAL(16,2)
	  , Imp_Gastos          DECIMAL(16,2)
	  , Imp_Final_Cuota     DECIMAL(16,2)
	  )

SET @NroCuota = 1
SET @SaldoInicial	= @pCapital
SET @AmortACum = 0
SET @Fecha = @pFechaDesde
SET @Fecha_Pago = NULL

SELECT @Id_Cliente = ISNULL(B.Id_Cliente,0)
	, @Razon_Social = C.Razon_Social 
	, @Id_Cliente_Externo = C.Id_Cliente_Externo
	, @Cuenta_Nro = B.Cuenta_Nro
	, @Cuenta_Descrip = B.Descripcion
	, @Fecha_Ult_Pago = B.Fecha_Ult_Pago
	FROM Bancos_Ctas B, Clientes C
	WHERE B.Id_Cliente = C.Id_Cliente
		AND B.Id_Cta_Banco = @Id_Cta_Banco

IF ISNULL(@Id_Cliente,0) = 0 
   BEGIN
     SET @Id_Cliente = @pId_Cliente 
   END


SELECT @IVA_INTERESES = ISNULL(1+(I.PORC1/100),0) FROM PRODUCTOS P, Productos_TasaIva I
    WHERE P.ID_PRODUCTO =  (select Valor_String from xParametros where setDatos= 1 and idParametro ='Prod_Gastos_Prest')
	      AND P.ID_IVA = I.Id_Iva

SELECT @Id_Producto_Seg = (select Valor_String from xParametros where setDatos= 1 and idParametro ='Prod_Seg_Prestamos')

      
/*Cuota Cero*/
SET @DifDias = DATEDIFF(dd,@Fecha,(Select dbo.SF_EOMONTH(@Fecha)))
IF ISNULL(@DifDias,0) != 0
BEGIN
		SET @Intereses		= @pCapital * (@pTEM / 100 / 30) * @DifDias
		SET @Amortizacion	= 0
		SET @ValorCuota		= @Intereses + @Amortizacion
		SET @AmortACum		= 0
		SET @SaldoFinal		= @pCapital 
	    SET @Imp_Seguro      = 0
	    SET @Imp_Gastos      = 0
	    SET @Imp_Final_Cuota = @ValorCuota + @Imp_Seguro + @Imp_Gastos

		INSERT INTO #Result VALUES (@Fecha,0 , @SaldoInicial, @ValorCuota, @Intereses, @Amortizacion, @AmortACum, @SaldoFinal,@Fecha_Pago
		             ,@Id_Cliente,@Razon_Social,@Id_Cliente_Externo,@Id_Cta_Banco,@Cuenta_Nro,@Cuenta_Descrip,@Imp_Seguro,@Imp_Gastos,@Imp_Final_Cuota )
END 

SET @Fecha = (Select dbo.SF_EOMONTH(@Fecha))
SET @Fecha = DATEADD(dd,1,@Fecha) 

WHILE @NroCuota <= @pCuotas
BEGIN
    IF UPPER(@pAmort) = 'T'   -- Tasa directa
	BEGIN
		SET @Intereses		= @pCapital * @pTEM / 100
		SET @Amortizacion	= @pCapital / @pCuotas
		SET @ValorCuota		= @Intereses + @Amortizacion
		SET @AmortACum		= @AmortACum + @Amortizacion
		SET @SaldoFinal		= @pCapital - @AmortACum
    END

    IF UPPER(@pAmort) = 'F'   -- Frances
	BEGIN
		SET @ValorCuota		= @pCapital * ( @pTEM / 100) / (1 -(POWER( (1+( @pTEM / 100)),(@pCuotas * -1) ) ) )   
		SET @Intereses		= @SaldoInicial * @pTEM / 100
		SET @Amortizacion	= @ValorCuota - @Intereses
		SET @AmortACum		= @AmortACum + @Amortizacion
		SET @SaldoFinal		= @pCapital - @AmortACum
    END

    IF UPPER(@pAmort) = 'A'   -- Aleman
	BEGIN
		SET @ValorCuota		= (@pCapital / @pCuotas) + ( @SaldoInicial * ( @pTEM / 100) )
		SET @Intereses		= @SaldoInicial * @pTEM / 100
		SET @Amortizacion	= @pCapital / @pCuotas
		SET @AmortACum		= @AmortACum + @Amortizacion
		SET @SaldoFinal		= @pCapital - @AmortACum
    END

    IF UPPER(@pAmort) = 'U'   -- Americano
	BEGIN
		SET @Intereses		= @pCapital * @pTEM / 100
		IF @NroCuota = @pCuotas
			SET @Amortizacion	= @pCapital  
		ELSE 
			SET @Amortizacion	= 0 
		SET @ValorCuota		= @Intereses + @Amortizacion
		SET @AmortACum		= @AmortACum + @Amortizacion
		SET @SaldoFinal		= @pCapital - @AmortACum

    END
	IF @Id_Cta_Banco > 0
	   BEGIN
		 SET @Fecha_Pago = (Select Max(ISNULL(R.FECHA,'')) From Cbtes_Items i, Cbtes C , CBTES_TIPOS T,CBTES_APLICA A, CBTES R 
						   Where C.Id_Trans = I.Id_Trans 
						   AND A.ID_TRANS = C.ID_TRANS 
						   AND A.ID_TRANS_D = R.ID_TRANS
						   And C.Id_Estado_Cbte = 2 and I.Id_Producto = 'AMORTIZA'
						   AND DATEPART(MM,I.Fecha_QA) = DATEPART(MM,@Fecha) 
						   AND DATEPART(YYYY,I.Fecha_QA) = DATEPART(YYYY,@Fecha) 
						   And C.Id_tipo_Cbte = T.Id_Tipo_cbte And T.Compromete_Factura = 1
						   And I.Id_Cta_Banco =  @Id_Cta_Banco )
						   
	  IF  @Fecha <= @Fecha_Ult_Pago
	     BEGIN
	         SET @Fecha_Pago = isnull(@Fecha_Pago,@Fecha_Ult_Pago)
	     END
						   
       END
         
PRINT @Fecha_Ult_Pago

    SET @Imp_Seguro      = (SELECT DBO.CFU_Finan_Creditos_Seguro(@Id_Producto_Seg,@Id_Cliente,@Fecha,@pCapital))

	SET @Imp_Gastos      = (SELECT DBO.CFU_Finan_Creditos_Gastos(@Amortizacion,@Intereses,@Iva_Intereses))

	SET @Imp_Final_Cuota = @ValorCuota + @Imp_Seguro + @Imp_Gastos
     
    INSERT INTO #Result VALUES (@Fecha,@NroCuota , @SaldoInicial, @ValorCuota, @Intereses, @Amortizacion, @AmortACum, @SaldoFinal,@Fecha_Pago
							,@Id_Cliente,@Razon_Social,@Id_Cliente_Externo,@Id_Cta_Banco,@Cuenta_Nro,@Cuenta_Descrip,@Imp_Seguro,@Imp_Gastos,@Imp_Final_Cuota )

	SET @NroCuota = @NroCuota + 1
	SET @SaldoInicial = @SaldoFinal
	SET @Fecha = DATEADD(mm,1,@Fecha)
END 

IF @SaldoFinal <> 0 
BEGIN
	UPDATE #Result SET Amortizacion = @Amortizacion + @SaldoFinal
	                 , ValorCuota = @ValorCuota + @SaldoFinal 
					 , AmortACum = @AmortACum + @SaldoFinal
					 , SaldoFinal = 0
	WHERE NroCuota = @pCuotas
END
IF ISNULL(@pNroCutoa,0) = 0
   SELECT * FROM #Result
ELSE
   SELECT * FROM #Result WHERE NroCuota = @pNroCutoa



DROP TABLE #Result


--EXEC CP_FINAN_CREDITOS 'T',12,1,15000,'20190618',0,0,4100
GO



CREATE PROCEDURE [dbo].[CP_Finan_Creditos_Saldo]
AS

DECLARE @Tipo_Amortizacion CHAR(1)
       ,@Meses_Cant SMALLINT
	   ,@Tasa_EM DECIMAL(14,9)
	   ,@Imp_Capital DECIMAL(16,2)
	   ,@Fecha_Desde DATETIME
	   ,@Id_Cta_Banco INT
	   ,@Id_Cliente   INT

CREATE TABLE #Result (
	    Fecha			DATETIME
      , NroCuota		SMALLINT 
      , SaldoInicial	DECIMAL(16,2)
	  , ValorCuota		DECIMAL(16,2)
	  , Intereses		DECIMAL(16,2)
	  , Amortizacion	DECIMAL(16,2) 
	  , AmortACum		DECIMAL(16,2) 
	  , SaldoFinal		DECIMAL(16,2)
	  , FechaPago       DATETIME
	  , Id_Cliente			INT
	  , Razon_Social		VARCHAR(100)
	  , Id_Cliente_Externo	VARCHAR(14)
	  , Id_Cta_Banco		SMALLINT
	  , Cuenta_Nro			VARCHAR(50)
	  , Cuenta_Descrip		VARCHAR(100)
	  , Imp_Seguro          DECIMAL(16,2)
	  , Imp_Gastos          DECIMAL(16,2)
	  , Imp_Final_Cuota     DECIMAL(16,2)
	  )
CREATE TABLE #Resultado (
	    Fecha			DATETIME
      , NroCuota		SMALLINT 
      , SaldoInicial	DECIMAL(16,2)
	  , ValorCuota		DECIMAL(16,2)
	  , Intereses		DECIMAL(16,2)
	  , Amortizacion	DECIMAL(16,2) 
	  , AmortACum		DECIMAL(16,2) 
	  , SaldoFinal		DECIMAL(16,2)
	  , FechaPago       DATETIME
	  , Id_Cliente			INT
	  , Razon_Social		VARCHAR(100)
	  , Id_Cliente_Externo	VARCHAR(14)
	  , Id_Cta_Banco		SMALLINT
	  , Cuenta_Nro			VARCHAR(50)
	  , Cuenta_Descrip		VARCHAR(100)
	  , Imp_Seguro          DECIMAL(16,2)
	  , Imp_Gastos          DECIMAL(16,2)
	  , Imp_Final_Cuota     DECIMAL(16,2)	 
	  )


 DECLARE CUR_PRESTAMOS CURSOR FOR
	  SELECT Tipo_Amortizacion,Meses_Cant,Tasa_EM,Imp_Capital,Fecha_Desde,Id_Cta_Banco, id_Cliente FROM Bancos_Ctas WHERE ACTIVO = 1 AND Id_Bco_Cta_Tipo = 6

 OPEN CUR_PRESTAMOS
 FETCH NEXT FROM CUR_PRESTAMOS INTO  @Tipo_Amortizacion,@Meses_Cant,@Tasa_EM,@Imp_Capital,@Fecha_Desde,@Id_Cta_Banco, @Id_Cliente
 WHILE @@FETCH_STATUS = 0
	BEGIN
	
	PRINT 'ID_CLIENTE:' +  CONVERT (VARCHAR(10),@id_cliente)
	
	  INSERT INTO #Result 
         EXEC CP_FINAN_CREDITOS @Tipo_Amortizacion,@Meses_Cant,@Tasa_EM,@Imp_Capital,@Fecha_Desde,0,@Id_Cta_Banco, @Id_Cliente 

      IF isnull((SELECT COUNT(*) FROM #Result WHERE  FechaPago IS NOT NULL ),0) > 0
           INSERT INTO #RESULTADO 
              SELECT TOP 1 * FROM #Result WHERE  FechaPago IS NOT NULL ORDER BY  NroCuota DESC
        ELSE
           INSERT INTO #RESULTADO 
              SELECT TOP 1 * FROM #Result WHERE NroCuota = 0

      DELETE #Result 
		 		  
   FETCH NEXT FROM CUR_PRESTAMOS INTO  @Tipo_Amortizacion,@Meses_Cant,@Tasa_EM,@Imp_Capital,@Fecha_Desde,@Id_Cta_Banco, @Id_Cliente
 END  
 CLOSE CUR_PRESTAMOS
 DEALLOCATE CUR_PRESTAMOS 
 
 SELECT  * FROM #Resultado

 Drop Table #Result 
 
 Drop Table #Resultado 


 -- exec [dbo].[CP_Finan_Creditos_Saldo]
GO

CREATE PROCEDURE [dbo].[CP_Ingresos_por_Tvalor]
	@pFecha_Desde			DATETIME,
	@pFecha_Hasta			DATETIME, 
	@pId_Tipo_cbte          Char(4),
	@pId_Tipo_Val           VARCHAR(3),
	@pTipo                  Char(1),
	@pId_Tarjeta            Char(10),
	@pId_Periodo_Caja       INT

AS

SET NOCOUNT ON
DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@Descripcion	    CHAR(50)
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Tipo_Val   	CHAR(3)
		,@CursorOpen        INT
		,@Tipo	            char(1)
		,@Periodo           DATE 
		,@Id_sucursal	    SMALLINT
		,@Existe      	    SMALLINT
		,@Id_tarjeta        CHAR(10)
		,@Id_Tipo_cbte      CHAR(4)

CREATE TABLE #VTAS_FPAGO (
        Id_Tarjeta CHAR(10),
		Descripcion  Char(50),
        Importe	decimal(16,2)
		)
		
SELECT * INTO #CAJAS FROM Cajas_Periodos
	IF @pId_Periodo_Caja  <> 0
	   DELETE #CAJAS WHERE Id_Periodo_Caja <> @pId_Periodo_Caja    


  IF @pId_Tipo_cbte <> ''
		   BEGIN
	            DECLARE TagCbtesCursor CURSOR FOR 
				select v.id_tipo_val,tc.tipo,TC.Id_Tarjeta,TC.Descripcion ,sum(ISNULL(v.importe,0) * V.COTIZACION) as importe
				from cbtes c, valores v LEFT OUTER JOIN Valores_Tarjetas_Cred tc on v.id_tarjeta = tc.id_tarjeta 
				,valores_mov m, cbtes_tipos t, #CAJAS CA
				where c.id_trans = m.id_trans 
				and m.id_valor = v.id_valor 
				and m.renglon_nro  = 1
				AND V.Id_Periodo_Caja = CA.Id_Periodo_Caja
				and c.id_tipo_cbte = t.id_tipo_cbte
				AND C.FECHA >= @pFecha_Desde 
				AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
				and v.id_tipo_val = @pId_Tipo_Val
				and c.Id_Estado_Cbte not in (0,3)
				and t.id_tipo_cbte = @pid_tipo_cbte
				group by v.id_tipo_val,tc.tipo,TC.Id_Tarjeta,TC.Descripcion HAVING SUM(v.importe  * V.COTIZACION) <> 0
            END
		  ELSE
		    BEGIN
		     	DECLARE TagCbtesCursor CURSOR FOR 
				select v.id_tipo_val,tc.tipo,TC.Id_Tarjeta,TC.Descripcion ,sum(ISNULL(v.importe,0) * V.COTIZACION) as importe
				from cbtes c, valores v LEFT OUTER JOIN Valores_Tarjetas_Cred tc on v.id_tarjeta = tc.id_tarjeta 
				,valores_mov m, cbtes_tipos t, #CAJAS CA 
				where c.id_trans = m.id_trans 
				and m.id_valor = v.id_valor 
				and m.renglon_nro  = 1
				AND V.Id_Periodo_Caja = CA.Id_Periodo_Caja
				and c.id_tipo_cbte = t.id_tipo_cbte
				AND C.FECHA >= @pFecha_Desde 
				AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
				and v.id_tipo_val = @pId_Tipo_Val
				and c.Id_Estado_Cbte not in (0,3)
				and (t.Compromete_Recibos in (1,-1)
				     or (t.Compromete_Factura in (1,-1) and c.Id_Cond_Pago = 1))
				group by v.id_tipo_val,tc.tipo,TC.Id_Tarjeta,TC.Descripcion HAVING SUM(ISNULL(v.importe,0) * V.COTIZACION) <> 0		    
            END

		OPEN TagCbtesCursor

		FETCH NEXT FROM TagCbtesCursor INTO @id_tipo_val,@tipo,@Id_Tarjeta,@Descripcion,@Importe 
		SET @CursorOpen = 0	
		SET @UltError = 0
		WHILE @@FETCH_STATUS=0 AND @UltError  = 0
		BEGIN
            SET @Existe = (Select ISNULL(Count(*),0) from #VTAS_FPAGO where Id_Tarjeta = @Id_Tarjeta)
			
			IF @Existe = 0
			   INSERT INTO #VTAS_FPAGO (
			            Id_Tarjeta,
						Descripcion,
						Importe	
						)
				VALUES (
				@id_Tarjeta,
                @Descripcion,
				0
				)

			IF @id_tipo_val = 'EFE'                     UPDATE #VTAS_FPAGO SET  Importe = Importe + @Importe WHERE  Id_Tarjeta = @Id_Tarjeta
			IF @id_tipo_val = 'TAR' AND @TIPO = @pTipo  UPDATE #VTAS_FPAGO SET  Importe = Importe + @Importe WHERE  Id_Tarjeta = @Id_Tarjeta
			IF @id_tipo_val = 'FIN'                     UPDATE #VTAS_FPAGO SET  Importe = Importe + @Importe WHERE  Id_Tarjeta = @Id_Tarjeta  


   		FETCH NEXT FROM TagCbtesCursor INTO  @id_tipo_val,@tipo,@Id_Tarjeta,@Descripcion,@Importe 

		END
		CLOSE TagCbtesCursor
		DEALLOCATE TagCbtesCursor
   
    SELECT * FROM #VTAS_FPAGO WHERE IMPORTE <> 0 ORDER BY 1

    DROP TABLE #VTAS_FPAGO
    DROP TABLE #CAJAS

  -- CP_INGRESOS_por_Tvalor '20220201','20220201','REC1','TAR','D','0',0
GO


CREATE PROCEDURE [dbo].[CP_Iva_Posicion]  @pFechaDesde DATETIME, @pFechaHasta DATETIME,@pId_Unid_Negocio Char(10)
AS
SET NOCOUNT ON

DECLARE @PERIODOS DATETIME
       ,@ID_UNID_NEGOCIO char(10)

Select Id_Unid_Negocio into #Posicion_Iva from Empresas_Unid_Negocios 

ALTER TABLE #Posicion_Iva ADD 
	 Periodo	        	DATETIME,
	 Deb_Fiscal_iva21       DECIMAL(14,2),
     Deb_Fiscal_iva10       DECIMAL(14,2),
	 Deb_Fiscal_iva27       DECIMAL(14,2),
     Cred_Fiscal_iva21      DECIMAL(14,2),
	 Cred_Fiscal_iva10      DECIMAL(14,2),
	 Cred_Fiscal_iva27      DECIMAL(14,2),
     Perc_iva               DECIMAL(14,2),
	 Reten_iva              DECIMAL(14,2),
	 Saldo_Ant              DECIMAL(14,2),
	 Empresa                VARCHAR(50)
	

	UPDATE #Posicion_Iva SET Periodo = @pFechaDesde,
	 Deb_Fiscal_iva21 = 0,
	 Deb_Fiscal_iva10 = 0,
     Deb_Fiscal_iva27 = 0,
     Cred_Fiscal_iva21 =0,
	 Cred_Fiscal_iva10 = 0,
	 Cred_Fiscal_iva27 = 0,
     Perc_iva = 0,
	 Reten_iva = 0,
	 Saldo_Ant = 0,
	 Empresa = ''

  DECLARE TagCbtesCursor CURSOR FOR  
    Select Id_Unid_Negocio from Empresas_Unid_Negocios 

	OPEN TagCbtesCursor

	FETCH NEXT FROM TagCbtesCursor INTO @ID_UNID_NEGOCIO

	WHILE @@FETCH_STATUS=0 
	BEGIN


	 SET @PERIODOS = DATEADD(MM,1,@pFechaDesde)
	 WHILE  @PERIODOS <= @pFechaHasta
	    BEGIN
		   INSERT #Posicion_Iva VALUES (@ID_UNID_NEGOCIO,@PERIODOS,0,0,0,0,0,0,0,0,0,'')	
		   SET @PERIODOS = DATEADD(MM,1,@PERIODOS)
		END	   
   	 	FETCH NEXT FROM TagCbtesCursor INTO @ID_UNID_NEGOCIO

	END
	CLOSE TagCbtesCursor
	DEALLOCATE TagCbtesCursor

	--select * from #Posicion_Iva

 SELECT substring(convert(nvarchar,c.Periodo_Iva,112),1,6)+'01' as Periodo,isnull(T.Id_Unid_Negocio,'') AS Id_Unid_Negocio
 ,SUM(ISNULL(IMP_IVA,0) * t.Compromete_Factura) as DEB_FISCAL_IVA21
 ,SUM(ISNULL(IMP_IVA2,0) * t.Compromete_Factura) as DEB_FISCAL_IVA10
 ,SUM(ISNULL(IMP_IVA3,0) * t.Compromete_Factura) as DEB_FISCAL_IVA27
  INTO #DEB_IVA
  FROM CBTES C, CBTES_TIPOS T
  WHERE C.Id_Tipo_Cbte =  T.Id_Tipo_Cbte
  AND T.Compromete_Factura in (1,-1) 
  AND T.Compromete_Impuestos IN (1,-1)
  AND C.ID_ESTADO_CBTE NOT IN (0,3)
  AND C.Periodo_Iva >= @pFechaDesde
  AND C.Periodo_Iva < @pFechaHasta
  GROUP BY substring(convert(nvarchar,c.Periodo_Iva,112),1,6)+'01',isnull(T.Id_Unid_Negocio,'')

  UPDATE #Posicion_Iva SET Deb_Fiscal_iva21 = D.Deb_Fiscal_iva21 ,Deb_Fiscal_iva10 = D.Deb_Fiscal_iva10 ,Deb_Fiscal_iva27 = D.Deb_Fiscal_iva27
     FROM #Posicion_Iva P, #DEB_IVA D WHERE P.PERIODO = D.PERIODO  AND P.Id_Unid_Negocio =  D.Id_Unid_Negocio




 SELECT substring(convert(nvarchar,c.Periodo_Iva,112),1,6)+'01' as Periodo,T.Id_Unid_Negocio as Id_Unid_Negocio
 ,SUM(ISNULL(IMP_IVA,0)) as CRED_FISCAL_IVA21
 ,SUM(ISNULL(IMP_IVA2,0)) as CRED_FISCAL_IVA10
 ,SUM(ISNULL(IMP_IVA3,0)) as CRED_FISCAL_IVA27
 INTO #CRED_IVA
  FROM CBTES C, CBTES_TIPOS T
  WHERE C.Id_Tipo_Cbte =  T.Id_Tipo_Cbte
  AND T.Compromete_COMPRAS in (1,-1) 
  AND T.Compromete_Impuestos IN (1,-1)
  AND C.ID_ESTADO_CBTE NOT IN (0,3)
  AND C.Periodo_Iva >= @pFechaDesde
  AND C.Periodo_Iva < @pFechaHasta
  GROUP BY substring(convert(nvarchar,c.Periodo_Iva,112),1,6)+'01',T.Id_Unid_Negocio

  UPDATE #Posicion_Iva SET Cred_Fiscal_iva21 = D.Cred_Fiscal_iva21 ,Cred_Fiscal_iva10 = D.Cred_Fiscal_iva10 ,Cred_Fiscal_iva27 = D.Cred_Fiscal_iva27
  FROM #Posicion_Iva P, #CRED_IVA D WHERE P.PERIODO = D.PERIODO AND P.Id_Unid_Negocio = D.Id_Unid_Negocio
 


 SELECT substring(convert(nvarchar,c.fecha,112),1,6)+'01' as Periodo,T.Id_Unid_Negocio as Id_Unid_Negocio ,SUM(R.IMPORTE) AS RETEN_IVA
  INTO #RETEN_IVA
  FROM CBTES C, CBTES_TIPOS T, CBTES_RETEN R, Cbtes_Reten_Tipos RT
  WHERE C.Id_Tipo_Cbte =  T.Id_Tipo_Cbte
  AND T.Compromete_COMPRAS in (1,-1) 
  AND T.Compromete_Impuestos IN (1,-1)
  AND C.ID_ESTADO_CBTE NOT IN (0,3)
  AND C.Periodo_Iva >= @pFechaDesde
  AND C.Periodo_Iva < @pFechaHasta
  AND C.ID_TRANS = R.ID_TRANS 
  AND R.Id_Tipo_Reten = RT.Id_Tipo_Reten
  AND RT.TIPO = 'R'
  AND RT.TIPO_IMP = 'V'
  GROUP BY substring(convert(nvarchar,c.fecha,112),1,6)+'01',T.Id_Unid_Negocio

  UPDATE #Posicion_Iva SET Reten_iva = D.Reten_iva 
  FROM #Posicion_Iva P, #RETEN_IVA D WHERE P.PERIODO = D.PERIODO AND P.Id_Unid_Negocio = D.Id_Unid_Negocio




  SELECT substring(convert(nvarchar,c.fecha,112),1,6)+'01' as Periodo,T.Id_Unid_Negocio ,sum(R.Importe)  AS PERC_IVA
  INTO #PERCEP_IVA
  FROM CBTES C, CBTES_TIPOS T, CBTES_RETEN R, Cbtes_Reten_Tipos RT
  WHERE C.Id_Tipo_Cbte =  T.Id_Tipo_Cbte
  AND T.Compromete_COMPRAS in (1,-1) 
  AND T.Compromete_Impuestos IN (1,-1)
  AND C.ID_ESTADO_CBTE NOT IN (0,3)
  AND C.Periodo_Iva >= @pFechaDesde
  AND C.Periodo_Iva < @pFechaHasta
  AND C.ID_TRANS = R.ID_TRANS 
  AND R.Id_Tipo_Reten = RT.Id_Tipo_Reten
  AND RT.TIPO = 'P'
  AND RT.TIPO_IMP = 'V'
  GROUP BY substring(convert(nvarchar,c.fecha,112),1,6)+'01',T.Id_Unid_Negocio

  UPDATE #Posicion_Iva SET Perc_iva = D.Perc_iva 
  FROM #Posicion_Iva P, #PERCEP_IVA D WHERE P.PERIODO = D.PERIODO AND P.Id_Unid_Negocio = D.Id_Unid_Negocio

  
  update #Posicion_Iva set Saldo_Ant = D.Saldo
  FROM #Posicion_Iva P, Tab_Iva_Saldos D WHERE P.PERIODO = D.PERIODO AND P.Id_Unid_Negocio = D.Id_Unid_Negocio
 

 UPDATE #Posicion_Iva SET EMPRESA = E.DESCRIPCION FROM #Posicion_Iva P, Empresas_Unid_Negocios E 
        WHERE E.Id_Unid_Negocio = P.Id_Unid_Negocio

 If @pId_Unid_Negocio <> '_'
    BEGIN
	  select * from #Posicion_Iva WHERE (Deb_Fiscal_iva21+
		 Deb_Fiscal_iva10+ 
		 Deb_Fiscal_iva27+
		 Cred_Fiscal_iva21+
		 Cred_Fiscal_iva10+
		 Cred_Fiscal_iva27+
		 Perc_iva+
		 Saldo_Ant+
		 Reten_iva) <> 0 AND Id_Unid_Negocio = @pId_Unid_Negocio
    END
  ELSE
	BEGIN
	  select * from #Posicion_Iva WHERE (Deb_Fiscal_iva21+
		 Deb_Fiscal_iva10+ 
		 Deb_Fiscal_iva27+
		 Cred_Fiscal_iva21+
		 Cred_Fiscal_iva10+
		 Cred_Fiscal_iva27+
		 Perc_iva+
		 Saldo_Ant+
		 Reten_iva) <> 0 
	END



  drop table #Posicion_Iva
  DROP TABLE #RETEN_IVA
  DROP TABLE #PERCEP_IVA
  DROP TABLE #CRED_IVA
  DROP TABLE #DEB_IVA

  /*

  
 EXEC cP_IVA_Posicion '20230101','20230131',''

 */
GO


CREATE PROCEDURE CP_Job_Borrar @pNombre NVARCHAR(max)
AS

DECLARE		@job_id			NVARCHAR(max)
			,@step_id		NVARCHAR(max)
			,@sched_id		INT
			,@Lote			VARCHAR(20)
			,@err			INT
			,@rtaMsjStored VARCHAR(100)


BEGIN TRY
	BEGIN TRAN

	SET @rtaMsjStored = ''


	SELECT	@Lote = CL.Lote, @job_id = [sJOB].[job_id] 
		, @step_id = [sJSTP].[step_id] 
		, @sched_id = [sSCH].schedule_id
	FROM  [msdb].[dbo].[sysjobs] AS [sJOB]
		LEFT JOIN [msdb].[sys].[servers] AS [sSVR]
		ON [sJOB].[originating_server_id] = [sSVR].[server_id]
		LEFT JOIN [msdb].[dbo].[syscategories] AS [sCAT]
		ON [sJOB].[category_id] = [sCAT].[category_id]
		LEFT JOIN [msdb].[dbo].[sysjobsteps] AS [sJSTP]
		ON [sJOB].[job_id] = [sJSTP].[job_id]
		AND [sJOB].[start_step_id] = [sJSTP].[step_id]
		LEFT JOIN [msdb].[sys].[database_principals] AS [sDBP]
		ON [sJOB].[owner_sid] = [sDBP].[sid]
		LEFT JOIN [msdb].[dbo].[sysjobschedules] AS [sJOBSCH]
		ON [sJOB].[job_id] = [sJOBSCH].[job_id]
		LEFT JOIN [msdb].[dbo].[sysschedules] AS [sSCH]
		ON [sJOBSCH].[schedule_id] = [sSCH].[schedule_id]
		LEFT JOIN Cbtes_Lotes_Trabajos AS [CLT]
		ON CLT.job_id = [sJOB].job_id
		LEFT JOIN Cbtes_Lotes AS [CL]
		ON CLT.Lote = CL.Lote
		WHERE [sJOB].[name] = @pNombre


		IF @Lote	IS NOT NULL
			DELETE [dbo].[Cbtes_Lotes_Trabajos] WHERE [Lote] = @Lote

		IF @sched_id IS NOT NULL
		BEGIN
			EXEC @err = msdb.dbo.sp_delete_schedule @schedule_id = @sched_id ,  @force_delete = 1
			IF @err <> 0
				RAISERROR ('An error occurred while trying to delete the job ', 16,  1 ) 
		END


		IF @step_id IS NOT NULL
		BEGIN
			EXEC @err = msdb.dbo.sp_delete_jobsteplog @job_name = @pNombre  
			IF @err <> 0
				RAISERROR ('An error occurred while trying to delete the job step' , 16,  1 ) 

			EXEC @err = msdb.dbo.sp_delete_jobstep @job_name = @pNombre , @step_id = @step_id
			IF @err <> 0
				RAISERROR ('An error occurred while trying to delete the job step' , 16,  1 ) 
		END


		IF @job_id IS NOT NULL
		BEGIN
			EXEC @err = msdb.dbo.sp_delete_job @job_name = @pNombre  , @delete_history = 1 , @delete_unused_schedule = 1
			IF @err <> 0
				RAISERROR ('An error occurred while trying to delete the job ', 16,  1 ) 
		END
	COMMIT
 								
	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage


END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	ROLLBACK

	RETURN 9999
END CATCH

RETURN 0
/*

EXEC CP_Job_Borrar 'CJ_Clever_Macabi_CSA_2022-04__2022-04-18T15:30:00'

*/
GO


CREATE PROCEDURE CP_Job_Cargar @pDB SYSNAME, @pQuery NVARCHAR(4000), @pFecha DATETIME, @pNombre VARCHAR(100)
AS

DECLARE @jn NVARCHAR(200)
		,@descrip			NVARCHAR(100)
		,@fecha				INT
		,@hora				INT
		,@fecha_iso			NVARCHAR(24)
		,@rtaMsjStored		VARCHAR(4000)
		,@productversion	VARCHAR(50)
		,@productlevel		VARCHAR(50)
		,@edition			VARCHAR(50)

SET @fecha_iso = CONVERT(NVARCHAR(100),@pFecha,126) 

SET @jn		=  N'CJ_'+ CAST(@pDB as NVARCHAR(100)) + N'_'+ CAST(@pNombre as NVARCHAR(100)) + N'_'+ @fecha_iso
SET @fecha	= CONVERT(INT, LEFT( CONVERT(NVARCHAR(100),@pFecha,112) ,8) )
SET @hora	= CONVERT(INT, SUBSTRING(@fecha_iso,12,2) +  SUBSTRING(@fecha_iso,15,2) + SUBSTRING(@fecha_iso,18,2) ) 


BEGIN TRY
	BEGIN TRAN

	SELECT	  @productversion = CONVERT(VARCHAR(50),SERVERPROPERTY('productversion'))
			, @productlevel = CONVERT(VARCHAR(50),SERVERPROPERTY ('productlevel'))
			, @edition = CONVERT(VARCHAR(50),SERVERPROPERTY ('edition'))

	IF LEFT(UPPER(@edition),7) = 'EXPRESS'
		RAISERROR ('Jobs cannot be scheduled on EXPRESS database engine versions. Please upgrade DB server.', 16,  1 )
	
	IF EXISTS (SELECT * FROM Cbtes_Lotes_Trabajos WHERE Lote = @pNombre)
	    RAISERROR ('There is already a Job programmed with this ID', 16,  1 ) 

	IF DATEADD(minute,5, GETDATE()) > @pFecha
		 RAISERROR ('The programming date cannot be less than the current day/time plus 5 minutes.', 16,  1 ) 


	IF EXISTS ( SELECT * FROM msdb.dbo.sysjobs WHERE name = @jn)
	BEGIN
		EXEC msdb.dbo.sp_delete_job @job_name = @jn  , @delete_history = 1 , @delete_unused_schedule = 1  
	END
   
	SET @descrip = N'Ejecuta ' + @jn
	EXEC msdb.dbo.sp_add_job  
		@job_name = @jn,
		@description = @descrip;  
  
	EXEC msdb.dbo.sp_add_jobstep  
		@job_name =  @jn,  
		@step_name = @descrip,  
		@subsystem = N'TSQL',  
		@database_name = @pDB,
		@command = @pQuery,   
		@retry_attempts = 1,  
		@retry_interval = 1 ;  


	IF NOT EXISTS ( SELECT * FROM msdb.dbo.sysschedules WHERE name = @jn ) 
	BEGIN
		EXEC msdb.dbo.sp_add_schedule  
			@schedule_name = @jn ,  
			@active_start_date  = @fecha,
			@freq_type = 1,  
			@freq_interval = 1,
			@freq_subday_type  = 0x1,
			@active_start_time = @hora


	END
 

	EXEC msdb.dbo.sp_attach_schedule  
	   @job_name = @jn,   
	   @schedule_name = @jn;  

	EXEC msdb.dbo.sp_add_jobserver  
		@job_name = @jn 


    SELECT TOP 1 @rtaMsjStored = job_id FROM msdb.dbo.sysjobs WHERE name = @jn

    INSERT INTO Cbtes_Lotes_Trabajos (Lote, job_id) VALUES (@pNombre,@rtaMsjStored)		 
	COMMIT
	
								
	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage


END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	ROLLBACK

	RETURN 9999
END CATCH

RETURN 0
/*

EXEC CP_Job_Cargar 'Clever_Macabi'
        , ' EXEC [dbo].[CPJ_Cbtes_Lotes_Facturar] ''{"Lote":"SOP-2021-12/6","Fecha":"20211201","Descripcion":"SOP-2021-12/6","Id_Lote_Tipo":"1","Fecha_Desde":"20211201","Fecha_Hasta":"20211231","Fecha_Rem_Desde":"        ","Fecha_Rem_Hasta":"        ","Id_Tipo_Cont":"1","Id_Usuario":"-1","FiltrarTarjeta":"0","FiltrarCliente":"0","FiltrarCondPago":"0","FiltrarTipoCbte":"0","FiltrarCantCont":"0","Refacturar":"1","Incl_Cbtes_Cero":"0","FlagUsarTrans":"0","ModoDebug":"0","Omitir_Resultado_OK":"0"}'' '
		,'20220419 10:27'
		, 'Prueba5'

select * from cbtes_lotes_trabajos

*/
GO



CREATE PROCEDURE [dbo].[CP_Liquido_Producto](
     @pFechaDesde DATETIME
   , @pFechaHasta DATETIME
   , @pNro_Lote Varchar(20)
   , @pGenerarLiquidacion TINYINT
   , @pId_Proveedor INT
   , @pIncluirPerccep TINYINT
   )
AS

--VERSION 09/03/2022

  CREATE TABLE #Trans (Id_Trans INT)

  DECLARE @Id_Producto Varchar(14)
  ,@Id_Proveedor Int
  ,@Razon_Social VarChar(100)
  ,@Cuit Varchar(13)
  ,@Id_Iva Char(3)
  ,@Id_Alias_Cta_Cont Int
  ,@Id_Cta_Contable_H Int
  ,@Porc_Comision_Prov Decimal(7,2) 
  ,@Importe Decimal(12,2) 
  ,@IMPORTE_CREDITO Decimal(12,2) 
  ,@ID_TIPO_CBTE CHAR(4) 
  ,@FECHA DATETIME
  ,@Imp_prod_siva  Decimal(12,2) 
  ,@TRANS INT
  ,@Id_Cliente_Externo VARCHAR(14)
  ,@Id_Cta_Banco INT
  ,@Id_Cliente INT
  ,@Plazo    INT
  ,@PORCENTAJE DECIMAL(12,2)
  ,@Descripcion_Producto VarChar(200)
  ,@CANTIDAD INT
  ,@Precio DECIMAL(12,2)
  ,@ErrorRetorno Int
  ,@IMP_RETENCIONES DECIMAL(12,2)
  ,@TOTAL_FACTURADO DECIMAL(12,2)
  ,@Fecha_Desde_Retencion DATETIME
  ,@COMPROBANTE_NRO INT
  ,@TRANSACCION INT
  ,@CANT INT
  ,@DETALLE_FACTURAS VarChar(800)
  ,@IMP_RETEN_ACUM DECIMAL(12,2)
  ,@CANT_REGISTROS INT
  ,@CANT_GENERADOS INT

  DECLARE @Respuesta Table (
     ErrorNumber    int,
	  ErrorSeverity  INT,
	  ErrorState     INT,
	  ErrorProcedure INT,
	  ErrorLine      INT, 
      ErrorMessage   VARCHAR(100)
	  )

/*Facturas que componene la NVLP*/
 DECLARE @Trans_FC_NVLP TABLE (Id_Trans_NVLP_Destino INT, Id_Trans_FacVenta_Origen	INT)


  SET @CANT_GENERADOS = 0
  SET @FECHA = @pFechaHasta /*Modificado 27/11/19 antes tomaba la fecha del dia*/

  SET @Fecha_Desde_Retencion = (SELECT DBO.CF_FOMONTH(@pFechaDesde))

  
  IF @pIncluirPerccep = 1
		    BEGIN 
			    SELECT C.ID_TRANS,TR.ID_TIPO_RETEN_DEST,R.IMPORTE INTO #TOTRETENIVA
				FROM cbtes c, cbtes_tipos t, cbtes_reten r,CBTES_RETEN_TIPOS TR
				where c.id_trans = r.id_trans
				AND R.Id_Tipo_Reten = TR.ID_TIPO_RETEN
				AND c.id_tipo_cbte = t.id_tipo_cbte 
				AND t.Compromete_Recibos in (1,-1)
				AND TR.TIPO = 'R'
				AND TR.TIPO_IMP = 'V'
				AND C.ID_ESTADO_CBTE <> 3
				AND c.Fecha >= @Fecha_Desde_Retencion
                AND c.Fecha <  DATEADD (dd, 1, @pFechaHasta) 

              			     
               SELECT DISTINCT C.ID_TRANS ,
               CASE WHEN (select max(V1.Porc_Desc_Liquidacion) 
				FROM cbtes c1, cbtes_tipos t1, cbtes_reten r1 , cbtes f1, cbtes_aplica a1, Cbtes_Cond_Vtas v1,CBTES_RETEN_TIPOS TR1
				where c1.id_trans = r1.id_trans
				AND R1.Id_Tipo_Reten = TR1.ID_TIPO_RETEN
				AND c1.id_trans = a1.id_trans_d
				AND f1.id_trans = a1.id_trans
				AND f1.Id_Cond_Vta = V1.Id_Cond_Vta
				AND c1.id_tipo_cbte = t1.id_tipo_cbte 
				AND t1.Compromete_Recibos in (1,-1)
				AND TR1.TIPO = 'R'
				AND TR1.TIPO_IMP = 'V'
				AND c1.Fecha >= @Fecha_Desde_Retencion
                AND c1.Fecha <  DATEADD (dd, 1, @pFechaHasta) 
				AND C1.ID_ESTADO_CBTE <> 3
				AND C1.iD_TRANS = C.ID_TRANS
				GROUP BY C1.iD_TRANS) = 0 THEN 30 
		      ELSE
		       (select max(V1.Porc_Desc_Liquidacion) 
				FROM cbtes c1, cbtes_tipos t1, cbtes_reten r1 , cbtes f1, cbtes_aplica a1, Cbtes_Cond_Vtas v1,CBTES_RETEN_TIPOS TR1
				where c1.id_trans = r1.id_trans
				AND R1.Id_Tipo_Reten = TR1.ID_TIPO_RETEN
				AND c1.id_trans = a1.id_trans_d
				AND f1.id_trans = a1.id_trans
				AND f1.Id_Cond_Vta = V1.Id_Cond_Vta
				AND c1.id_tipo_cbte = t1.id_tipo_cbte 
				AND t1.Compromete_Recibos in (1,-1)
				AND TR1.TIPO = 'R'
				AND TR1.TIPO_IMP = 'V'
				AND c1.Fecha >= @Fecha_Desde_Retencion
                AND c1.Fecha <  DATEADD (dd, 1, @pFechaHasta) 
				AND C1.ID_ESTADO_CBTE <> 3
				AND C1.iD_TRANS = C.ID_TRANS
				GROUP BY C1.iD_TRANS)
		     END AS PORC
  			 INTO #PORC_DESCUENTO

			 FROM cbtes c, cbtes_tipos t, cbtes_reten r , cbtes f, cbtes_aplica a, Cbtes_Cond_Vtas v,CBTES_RETEN_TIPOS TR
			 where c.id_trans = r.id_trans
			 AND R.Id_Tipo_Reten = TR.ID_TIPO_RETEN
			 AND c.id_trans = a.id_trans_d
			 AND f.id_trans = a.id_trans
			 AND f.Id_Cond_Vta = V.Id_Cond_Vta
			 AND c.id_tipo_cbte = t.id_tipo_cbte 
			 AND t.Compromete_Recibos in (1,-1)
			 AND TR.TIPO = 'R'
			 AND TR.TIPO_IMP = 'V'
			 AND C.ID_ESTADO_CBTE <> 3
		     AND c.Fecha >= @Fecha_Desde_Retencion
             AND c.Fecha <  DATEADD (dd, 1, @pFechaHasta) 
			

			   SET @IMP_RETENCIONES = (SELECT SUM(IMPORTE - (IMPORTE * PORC/100)) FROM #PORC_DESCUENTO V, #TOTRETENIVA T WHERE V.ID_TRANS = T.ID_TRANS) 

               SET @IMP_RETEN_ACUM = 0

			   DECLARE @ID_TIPO_RETEN_DEST VARCHAR(10)
			   SET @ID_TIPO_RETEN_DEST = (SELECT TOP 1 ID_TIPO_RETEN_DEST FROM #TOTRETENIVA)

            END

 -- BEGIN  

   
  SELECT P.Id_PROVEEDOR,isnull(v.Plazo_Venc,0) PLAZO,isnull(v.Porc_Desc_Liquidacion,30) PORCENTAJE,SUM(I.Imp_Gravado*T.COMPROMETE_FACTURA) IMPORTE
	INTO #Res_Cond_Vta FROM cbtes c, Cbtes_Cond_Vtas v, cbtes_tipos t, CBTES_ITEMS I, PRODUCTOS P
	where c.id_tipo_cbte = t.Id_Tipo_Cbte
	AND P.Id_PROVEEDOR = @pId_Proveedor
	AND t.Compromete_Factura in (1,-1)
	AND c.id_cond_vta = v.Id_Cond_Vta 
	AND c.Id_Estado_Cbte <> 3 
	AND c.Fecha >= @pFechaDesde
    AND c.Fecha <  DATEADD (dd, 1, @pFechaHasta) 
	AND V.Porc_Desc_Liquidacion > 0 AND I.ID_TRANS = C.ID_TRANS
	AND I.Id_Producto = P.Id_Producto
	   GROUP BY P.Id_PROVEEDOR,v.Plazo_Venc,v.Porc_Desc_Liquidacion HAVING SUM(I.Imp_Gravado*T.COMPROMETE_FACTURA) <> 0
	   ORDER BY P.Id_PROVEEDOR

 IF @pGenerarLiquidacion <> 1
    SELECT * FROM #Res_Cond_Vta
    
 IF @pGenerarLiquidacion = 1
    BEGIN
       
       SET @TOTAL_FACTURADO = (SELECT SUM(IMPORTE*(1-PORCENTAJE/100)) FROM #Res_Cond_Vta)
       SET @CANT_REGISTROS = (SELECT COUNT(*) FROM #Res_Cond_Vta)  

	   DECLARE CUR_GENERAR CURSOR FOR

	   SELECT * FROM #Res_Cond_Vta

	   OPEN CUR_GENERAR
	   FETCH NEXT FROM CUR_GENERAR INTO  @Id_Proveedor,@Plazo,@PORCENTAJE,@Importe
	   WHILE @@FETCH_STATUS = 0
	   BEGIN
	        DELETE #Trans
			IF @Id_Proveedor > 0
        		BEGIN
				   SET @ID_TIPO_CBTE = (SELECT Valor_String FROM xParametros where SETDatos= 1 AND idParametro ='T_Cbte_NV_Liq_Prod')
			   --    SET @ID_TIPO_CBTE = 'NVLP'

				   SET @Razon_Social = (SELECT Razon_Social FROM Proveedores where Id_Proveedor = @Id_Proveedor)
				   INSERT INTO #Trans
			    		EXEC @ErrorRetorno = dbo.CP_Cbtes_Cpra_Generar_Cabe @Id_Proveedor,@Razon_Social,@Importe,1,@FECHA,@ID_TIPO_CBTE,'',1,@Plazo,100,@trans OUTPUT
						SET @CANT_GENERADOS = @CANT_GENERADOS+1
			       IF @ErrorRetorno <> 0
				      RETURN 1

				END

		  DECLARE CUR_GENERAR_DETALLE CURSOR FOR

		  SELECT I.ID_PRODUCTO,I.Descripcion_producto,Round(I.Precio,02),SUM(I.Cantidad*T.COMPROMETE_FACTURA) CANTIDAD 
		  FROM cbtes c, Cbtes_Cond_Vtas v, cbtes_tipos t, CBTES_ITEMS I, PRODUCTOS P
			where c.id_tipo_cbte = t.Id_Tipo_Cbte AND t.Compromete_Factura in (1,-1) AND c.id_cond_vta = v.Id_Cond_Vta 
			AND c.Id_Estado_Cbte <> 3 
			AND c.Fecha >= @pFechaDesde
			AND c.Fecha <  DATEADD (dd, 1, @pFechaHasta) 
			AND P.Id_PROVEEDOR = @Id_Proveedor
			AND v.Plazo_Venc = @PLAZO
			AND v.Porc_Desc_Liquidacion = @PORCENTAJE
			AND v.Porc_Desc_Liquidacion > 0 
			AND I.Precio <> 0
			AND I.ID_TRANS = C.ID_TRANS
	 		AND I.Id_Producto = P.Id_Producto
			GROUP BY I.ID_PRODUCTO,I.Descripcion_producto,Round(I.Precio,02)

		  OPEN CUR_GENERAR_DETALLE
		  FETCH NEXT FROM CUR_GENERAR_DETALLE INTO  @Id_Producto,@Descripcion_Producto,@Precio,@Cantidad
	  
		  WHILE @@FETCH_STATUS = 0
			  BEGIN
			  
					 IF @trans > 0
						BEGIN
							  SET @Id_Cliente = 0
							  SET @Id_Cta_Banco = 0

							  EXEC @ErrorRetorno = dbo.SP_CbteItem_Agr   @Id_Producto,@trans,@Cantidad,@Precio,@fecha,'',@Descripcion_Producto,@ID_Cliente,@Id_Cta_Banco
							  IF @ErrorRetorno <> 0
				                 RETURN 1
        				END  

			  FETCH NEXT FROM CUR_GENERAR_DETALLE INTO  @Id_Producto,@Descripcion_Producto,@Precio,@Cantidad
		 END  

		 SET @IMPORTE_CREDITO = (SELECT SUM(IMP_GRAVADO) FROM CBTES_ITEMS WHERE ID_TRANS = @TRANS ) * (@PORCENTAJE/100) 
		 SET @Id_Producto  = (SELECT Valor_String FROM xParametros where SETDatos= 1 AND idParametro ='Id_Prod_Desc_NVLP')
		 SET @Descripcion_Producto = (SELECT DESCRIPCION_DETALLADA FROM PRODUCTOS WHERE ID_PRODUCTO = @Id_Producto ) + ' % ' +Cast(@PORCENTAJE AS VARCHAR(10))


		 EXEC @ErrorRetorno = dbo.SP_CbteItem_Agr   @Id_Producto,@trans,-1,@IMPORTE_CREDITO,@fecha,'',@Descripcion_Producto,@ID_Cliente,@Id_Cta_Banco
 	  	 IF @ErrorRetorno <> 0
			 RETURN 1 

 ---------------------------------- GENERAR PERCEPCIONES
 
		 SELECT TR.ID_TIPO_RETEN_DEST,SUM(ISNULL(R.Imp_Base_Imponible,0)) BASE,SUM(ISNULL(R.IMPORTE * T.Compromete_Factura,0)) IMPORTE 
				INTO #CBTES_RETEN 
				FROM CBTES_RETEN R, CBTES C, Cbtes_Cond_Vtas V, cbtes_tipos T,CBTES_RETEN_TIPOS TR
				WHERE c.id_tipo_cbte = t.Id_Tipo_Cbte AND t.Compromete_Factura in (1,-1) 
				AND c.id_cond_vta = v.Id_Cond_Vta 
				AND c.Id_Estado_Cbte <> 3 
				AND c.Fecha >= @pFechaDesde
				AND c.Fecha <  DATEADD (dd, 1, @pFechaHasta)
				AND v.Plazo_Venc = @PLAZO
				AND v.Porc_Desc_Liquidacion = @PORCENTAJE
				AND v.Porc_Desc_Liquidacion > 0 
				AND R.Id_Tipo_Reten = ISNULL(TR.ID_TIPO_RETEN,'')
				AND ISNULL(TR.ID_TIPO_RETEN_DEST,'') <> ''
                AND ISNULL(R.ID_TIPO_RETEN,'') <> ''
				AND TR.TIPO = 'P'
				AND R.ID_TRANS = C.ID_TRANS
				AND EXISTS (SELECT 1 FROM PRODUCTOS P, CBTES_ITEMS I
				               WHERE P.Id_PROVEEDOR = @Id_Proveedor
								   AND I.ID_TRANS = C.ID_TRANS
								   AND I.Id_Producto = P.Id_Producto)
				GROUP BY TR.Id_Tipo_Reten_Dest
				PRINT 'INSERTO 1'
				INSERT INTO CBTES_RETEN (ID_TRANS,ID_TIPO_RETEN,IMPORTE,Observaciones,NRO,Imp_Pago_Acum,Imp_No_Imponible,Imp_Base_Imponible,Porc,Imp_Determinado,Imp_Reten_Ant,Fecha)
				SELECT @trans,R.ID_TIPO_RETEN_DEST,R.IMPORTE,'',0,0,0,R.Base,0,0,0,@fecha FROM #cbtes_reten R WHERE ISNULL(R.ID_TIPO_RETEN_DEST,'''') <> ''

		 DROP TABLE #cbtes_reten

      
----------------------------------- FIN PERCEPCIONES 

 ---------------------------------- GENERAR RETENCIONES

         IF @pIncluirPerccep = 1
		    BEGIN 
			        print 'genero retencion  '

				    DECLARE @TOT_NVLP DECIMAL(14,2)

					SET @TOT_NVLP = (SELECT SUM(IMP_GRAVADO) FROM CBTES_ITEMS WHERE ID_TRANS = @trans)


					print  @IMP_RETENCIONES
					print  @TOT_NVLP
					print  @TOTAL_FACTURADO

			    	INSERT INTO CBTES_RETEN (ID_TRANS,ID_TIPO_RETEN,IMPORTE,Observaciones,NRO,Imp_Pago_Acum,Imp_No_Imponible,Imp_Base_Imponible,Porc,Imp_Determinado,Imp_Reten_Ant,Fecha)
				    VALUES (@trans,@ID_TIPO_RETEN_DEST,(@IMP_RETENCIONES  * (@TOT_NVLP/@TOTAL_FACTURADO)) *-1,'',0,0,0,0,0,0,0,@fecha) 

            END
    
----------------------------------- FIN RETENCIONES


--------------GENERO Observacion con el detalle de las facturas
        SET @DETALLE_FACTURAS = 'Cbtes incluidos: '
        DECLARE CUR_GENERAR_NUMEROS CURSOR FOR

				SELECT C.Comprobante_Nro,C.Id_Trans,Count(*) as Cantidad
				FROM  CBTES C, Cbtes_Cond_Vtas V, cbtes_tipos T, PRODUCTOS P, CBTES_ITEMS I
				WHERE c.id_tipo_cbte = t.Id_Tipo_Cbte AND t.Compromete_Factura in (1,-1) 
				AND c.id_cond_vta = v.Id_Cond_Vta 
				AND c.Id_Estado_Cbte <> 3 
				AND c.Fecha >= @pFechaDesde
				AND c.Fecha <  DATEADD (dd, 1, @pFechaHasta) 
				AND P.Id_PROVEEDOR = @Id_Proveedor
				AND v.Plazo_Venc = @PLAZO
				AND v.Porc_Desc_Liquidacion = @PORCENTAJE
				AND v.Porc_Desc_Liquidacion > 0 
				AND I.Precio <> 0
				AND I.ID_TRANS = C.ID_TRANS
	 			AND I.Id_Producto = P.Id_Producto
				GROUP BY C.Comprobante_Nro,C.Id_Trans

		  OPEN CUR_GENERAR_NUMEROS
		  FETCH NEXT FROM CUR_GENERAR_NUMEROS INTO  @COMPROBANTE_NRO,@TRANSACCION,@CANT
	  
		  WHILE @@FETCH_STATUS = 0
			  BEGIN
			  INSERT INTO Cbtes_Incluidos(Id_Trans,Id_Trans_D,Cantidad,Importe) VALUES (@trans, @TRANSACCION,0,0)
			 
    		  SET @DETALLE_FACTURAS = RTRIM(LTRIM(@DETALLE_FACTURAS))  +' ' + CAST(@COMPROBANTE_NRO AS VARCHAR(10)) 

			  FETCH NEXT FROM CUR_GENERAR_NUMEROS INTO @COMPROBANTE_NRO,@TRANSACCION,@CANT
		  END  
		  CLOSE CUR_GENERAR_NUMEROS
		  DEALLOCATE CUR_GENERAR_NUMEROS

--------------Fin
      
         INSERT INTO @RESPUESTA 
		 EXEC @ErrorRetorno = dbo.CP_Cbtes_Cpra_Generar_Fin @Id_Proveedor,@Razon_Social,@Importe,1,@FECHA,@ID_TIPO_CBTE,'',1,10,100,@trans 
		 IF @ErrorRetorno <> 0
			 RETURN 1

         INSERT INTO @RESPUESTA 
         EXEC @ErrorRetorno = dbo.CP_Cbtes_Cpra_Generar_Asi @Trans
		 IF @ErrorRetorno <> 0
			 RETURN 1

         UPDATE Cbtes SET Id_Estado_Cbte =  1, Lote = @pNro_Lote WHERE ID_TRANS = @TRANS 
		 UPDATE Cbtes SET Observacion =  @DETALLE_FACTURAS WHERE ID_TRANS = @TRANS 

         ---ABRIR ASIENTO


					DECLARE @GEN_REDONDEO  decimal(14,2)
					declare @redondeo decimal(14,2)

					SET @GEN_REDONDEO = 0
					SET @redondeo = 0


					/*ACTUALIZAMOS el monto de la cuenta Alias 59*/

		    		set @redondeo = ISNULL((SELECT sum(Imp_Gravado) * -1 FROM Cbtes_items I WHERE  i.Id_Trans = @Trans  and Id_Producto = 'DESCUENTO'),0)
						print '1 '
						PRINT @redondeo

					UPDATE Cbtes_Ctas_Contables
						SET
						Debe = ISNULL((SELECT SUM(ISNULL(C.Imp_neto*T.Compromete_Factura, 0)) FROM Cbtes C, Cbtes_Tipos T,Cbtes_Incluidos I 
							   WHERE C.Id_Tipo_Cbte = T.Id_tipo_Cbte and c.Id_Trans = I.Id_trans_D and I.Id_trans = @trans) , 0), 
						Observacion = 'Generado Automaticamente x CP_Liquido_Producto'
						WHERE
						Id_Trans = @trans
						AND Alias = 59


						/*BORRAMOS la cuenta de descuento (Alias 787), ya que no se debe realizar en el asiento de NVLP*/
						DELETE Cbtes_Ctas_Contables
						WHERE
						Id_Trans = @trans
						AND Alias = 787

						/*INSERTAMOS las cuentas del HABER por Zona*/
						DECLARE @Id_Alias_Cta_Cont_Haber	SMALLINT
						DECLARE @Id_Cta_Contable_Haber		INT
						DECLARE @Imp_Haber					DECIMAL(12,2)
						DECLARE @Fecha_NVLP					DATETIME
						DECLARE @Porc_Desc_Liquidacion		DECIMAL(7,2)
						DECLARE @Item_Cbtes_Cta_Cont		SMALLINT
				
						SET @Fecha_NVLP				= (SELECT ISNULL(Fecha, '19000101') FROM Cbtes WHERE Id_Trans = @trans)

						SELECT CAST(dbo.SF_Alias_Cta_Contable_X_Zona(CL.Id_Zona) AS INT) AS Id_Alias_Cta_Cont, CCV.Porc_Desc_Liquidacion, SUM(ISNULL(CB.Imp_Neto,0)*T.Compromete_Factura) AS IMP_HABER  
						INTO  #DET_DESCUENTOS
						FROM Cbtes CB, Clientes CL, Cbtes_Cond_Vtas CCV, Cbtes_Tipos T, Cbtes_Incluidos I
						WHERE
						ISNULL(CB.Id_Cliente, 0) = CL.Id_Cliente
						AND CB.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
						AND CB.Id_Cond_Vta = CCV.Id_Cond_Vta
						AND CB.Id_Trans = I.id_trans_d
						and I.id_trans = @trans
						GROUP BY dbo.SF_Alias_Cta_Contable_X_Zona(CL.Id_Zona), CCV.Porc_Desc_Liquidacion


						ALTER TABLE #DET_DESCUENTOS ADD Id_Cta_Contable_Haber INT

						UPDATE #DET_DESCUENTOS SET Id_Cta_Contable_Haber =  (ISNULL(dbo.CF_Cta_Cont (Id_Alias_Cta_Cont, @Fecha_NVLP),0))

						DECLARE curAsixZona CURSOR FOR		
						SELECT Id_Alias_Cta_Cont,Porc_Desc_Liquidacion, IMP_HABER, Id_Cta_Contable_Haber   FROM #DET_DESCUENTOS
						OPEN curAsixZona	
						FETCH NEXT FROM curAsixZona INTO @Id_Alias_Cta_Cont_Haber, @Porc_Desc_Liquidacion, @Imp_Haber, @Id_Cta_Contable_Haber	
						WHILE @@FETCH_STATUS = 0
						BEGIN
		

							SET @Imp_Haber				= (@Imp_Haber * (@Porc_Desc_Liquidacion  / 100))
							SET @Item_Cbtes_Cta_Cont	= ISNULL((SELECT MAX(ISNULL(Item, 0)) + 1 FROM Cbtes_Ctas_Contables WHERE Id_trans = @trans), 1)

							SET @redondeo = @redondeo - @Imp_Haber

							INSERT Cbtes_Ctas_Contables
							(Id_Trans,		Id_Cta_Contable,		Fecha,
							Debe,			Haber,					Observacion,
							Alias,			Id_Asiento,				Id_Centro_Costo,
							Item)
							VALUES
							(@trans,		@Id_Cta_Contable_Haber,	@Fecha_NVLP,
							0,				@Imp_Haber,				'Generado Automaticamente x CP_Liquido_Producto',
							@Id_Alias_Cta_Cont_Haber, 0,			'',
							@Item_Cbtes_Cta_Cont)

							FETCH NEXT FROM curAsixZona INTO @Id_Alias_Cta_Cont_Haber, @Porc_Desc_Liquidacion, @Imp_Haber, @Id_Cta_Contable_Haber	
						END
						CLOSE curAsixZona
						DEALLOCATE curAsixZona

						DROP TABLE #DET_DESCUENTOS

						print '3 '
						print @redondeo

						IF @redondeo <= 0
						   BEGIN
							 UPDATE Cbtes_Ctas_Contables SET Haber = Haber - ABS(@redondeo) where Id_Trans = @trans and Item = @Item_Cbtes_Cta_Cont
						   END
						ELSE
						   BEGIN
							 UPDATE Cbtes_Ctas_Contables SET Haber = Haber + ABS(@redondeo) where Id_Trans = @trans and Item = @Item_Cbtes_Cta_Cont
						   END		

		
		
		      ---fin apertura asiento



		 CLOSE CUR_GENERAR_DETALLE
		 DEALLOCATE CUR_GENERAR_DETALLE

		 FETCH NEXT FROM CUR_GENERAR INTO @Id_Proveedor,@Plazo,@PORCENTAJE,@Importe

	  END
	  CLOSE CUR_GENERAR
	  DEALLOCATE CUR_GENERAR 

 	  SELECT * FROM #Res_Cond_Vta
       
	END
 

--  exec CP_Liquido_Producto '20220201','20220209','pruebAa321',1,123,1
GO



CREATE PROCEDURE CP_Listas_Precios_Job_Cargar @db SYSNAME
AS

DECLARE @jn NVARCHAR(200)
SET @jn =  N'CJ_Listas_Precios_Precio_Nuevo_'+ CAST(@db as NVARCHAR(100))


IF EXISTS ( SELECT * FROM msdb.dbo.sysjobs WHERE name = @jn)
BEGIN
	EXEC msdb.dbo.sp_delete_job @job_name = @jn  , @delete_history = 1 , @delete_unused_schedule = 1  
END
   

EXEC msdb.dbo.sp_add_job  
    @job_name = @jn,
	@description = N'Ejecuta el SP CP_Listas_Precios_Precio_Nuevo_Cargar' ;  
  
EXEC msdb.dbo.sp_add_jobstep  
    @job_name =  @jn,  
    @step_name = N'Actulizacion de Precios',  
    @subsystem = N'TSQL',  
	@database_name = @db,
    @command = N'EXEC CP_Listas_Precios_Precio_Nuevo_Cargar',   
    @retry_attempts = 5,  
    @retry_interval = 5 ;  


IF NOT EXISTS ( SELECT * FROM msdb.dbo.sysschedules WHERE name =  N'CS_DiaNuevo') 
BEGIN
	EXEC msdb.dbo.sp_add_schedule  
		@schedule_name = N'CS_DiaNuevo',  
		@freq_type = 4,  
		@freq_interval = 1,
		@active_start_time = 000000 ;  

END
 

EXEC msdb.dbo.sp_attach_schedule  
   @job_name = @jn,   
   @schedule_name = N'CS_DiaNuevo';  

EXEC msdb.dbo.sp_add_jobserver  
    @job_name = @jn 

--SELECT name FROM msdb.dbo.sysjobs WHERE name =  @jn
GO


CREATE  PROCEDURE [dbo].[CP_Listas_Precios_Precio_Nuevo_Actualizar]  @NroLista int , @HacerBackup tinyint
AS

DECLARE @Mensaje			VARCHAR(100)
		,@Id_Trans_Nueva	INT
		,@Descripcion		VARCHAR(100)
		,@Id_Valor			INT
		,@Comprobante_Nro	INT
		,@ListaBakcup       INT
		,@FECHA             DATETIME
		,@NoActualPrecioCero TINYINT


 DECLARE @Respuesta Table (
      ErrorNumber    int,
	  ErrorSeverity  INT,
	  ErrorState     INT,
	  ErrorProcedure INT,
	  ErrorLine      INT, 
      ErrorMessage   VARCHAR(100)
	  )		

BEGIN TRY
	BEGIN TRAN
	SET @NoActualPrecioCero = dbo.CF_xParam('No_Act_New_pcio_0')


	/*** Si solo aactualiza los precios dif. cero y no tiene nada para actualizar, no hago nada ----7/9/23  ***/
	IF @NoActualPrecioCero = 1 AND (SELECT COUNT(*) FROM Prod_Listas_Precios_Items WHERE Id_Lista_Precio = @NroLista AND Precio_Nuevo <> 0) = 0
	BEGIN
		COMMIT
		SET @Mensaje = 'Nada para actualizar'
		SELECT	 0					AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,@Mensaje			AS ErrorMessage
        RETURN 0
    END 
	/*****************fin de control de si hay algo para actualizar *****************/   
	


	SELECT @ListaBakcup = ISNULL(Id_Lista_Precio_Backup,0)
			FROM  Prod_Listas_Precios
			WHERE Id_Lista_Precio = @NroLista
				     
		    
	IF @HacerBackup = 1
	BEGIN
		SELECT * INTO #COPIA FROM Prod_Listas_Precios_Items WHERE Id_Lista_Precio = @NroLista
		--PRINT(@ListaBakcup)
		IF @ListaBakcup <> 0
			BEGIN
				PRINT 'TIENE LISTA BK'
				DELETE Prod_Listas_Precios_Items WHERE Id_Lista_Precio = @ListaBakcup
				UPDATE #COPIA SET Id_Lista_Precio = @ListaBakcup
			END
		ELSE
			BEGIN
				PRINT 'NO TIENE LISTA BK'
				SET @ListaBakcup = (SELECT MAX(Id_Lista_Precio)+1 FROM Prod_Listas_Precios) 
				PRINT @ListaBakcup

				SELECT * INTO #NUEVA_LISTA FROM Prod_Listas_Precios WHERE Id_Lista_Precio = @NroLista

				UPDATE #NUEVA_LISTA SET Id_Lista_Precio = @ListaBakcup, ACTIVO = 0, DESCRIPCION = 'COPIA BK ' + LTRIM(RTRIM(DESCRIPCION))
				INSERT INTO Prod_Listas_Precios
						SELECT * FROM #NUEVA_LISTA
				UPDATE #COPIA SET Id_Lista_Precio = @ListaBakcup
				DROP TABLE #NUEVA_LISTA
            END				   
			
		INSERT INTO Prod_Listas_Precios_Items
				SELECT * FROM #COPIA

		DROP TABLE #COPIA 
	END		
		 
    IF @NoActualPrecioCero = 1
	BEGIN
			UPDATE Prod_Listas_Precios_Items	SET Fecha_Desde = Getdate(),Precio = Precio_Nuevo  
											WHERE Id_Lista_Precio = @NroLista AND Precio <> Precio_Nuevo AND Precio_Nuevo <> 0
  			UPDATE Prod_Listas_Precios_Items	SET Precio_Nuevo = 0
											WHERE Id_Lista_Precio = @NroLista AND Precio_Nuevo <> 0

			UPDATE Prod_Listas_Precios			SET Fecha_desde = Fecha_Desde_Nueva,Fecha_Hasta = Fecha_Hasta_Nueva 
											WHERE Id_Lista_Precio = @NroLista
			UPDATE Prod_Listas_Precios			SET Fecha_Desde_Nueva = NULL,Fecha_Hasta_Nueva = Null 
											WHERE Id_Lista_Precio = @NroLista
	END	
	ELSE
	BEGIN
			UPDATE Prod_Listas_Precios_Items	SET Fecha_Desde = Getdate(),Precio = Precio_Nuevo  
											WHERE Id_Lista_Precio = @NroLista AND Precio <> Precio_Nuevo
  			UPDATE Prod_Listas_Precios_Items	SET Precio_Nuevo = 0
											WHERE Id_Lista_Precio = @NroLista AND Precio_Nuevo <> 0

			UPDATE Prod_Listas_Precios			SET Fecha_desde = Fecha_Desde_Nueva,Fecha_Hasta = Fecha_Hasta_Nueva		
											WHERE Id_Lista_Precio = @NroLista
			UPDATE Prod_Listas_Precios			SET Fecha_Desde_Nueva = NULL,Fecha_Hasta_Nueva = Null 
											WHERE Id_Lista_Precio = @NroLista
	END	
 


	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage


END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;   

-- EXEC CP_Listas_Precios_Precio_Nuevo_Actualizar 1001,1
GO



CREATE  PROCEDURE [dbo].[CP_Listas_Precios_Precio_Nuevo_Cargar] 
AS

DECLARE @Mensaje			VARCHAR(100)
		,@Id_Trans_Nueva	INT
		,@Descripcion		VARCHAR(100)
		,@Id_Valor			INT
		,@Comprobante_Nro	INT
		,@HacerBackup       TINYINT
		,@ListaBakcup       INT
		,@FECHA             DATETIME
		,@NroLista          INT
		,@ULTIMO_ERROR      INT

 DECLARE @Respuesta Table (
      ErrorNumber    int,
	  ErrorSeverity  INT,
	  ErrorState     INT,
	  ErrorProcedure INT,
	  ErrorLine      INT, 
      ErrorMessage   VARCHAR(100)
	  )		

BEGIN TRY
	

	IF (NOT EXISTS (SELECT 1 FROM Prod_Listas_Precios WHERE ISNULL(Job_Nombre,'') <> ''))
	BEGIN
		SELECT	 1					AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,'No Existen listas con Job de actualizacion asociados'	AS ErrorMessage


		ROLLBACK
		RETURN 1
    END
	

        DECLARE CUR_PROCESAR_LISTAS CURSOR FOR

				SELECT Id_Lista_Precio,Flag_Hacer_Backup,Id_Lista_Precio_Backup,Fecha_Desde_Nueva
				FROM  Prod_Listas_Precios
				WHERE ACTIVO = 1 AND Isnull(Job_Nombre,'') <> ''  
				      AND Fecha_Desde_Nueva >= GETDATE() AND  Fecha_Desde_Nueva < GETDATE()+1

		  OPEN CUR_PROCESAR_LISTAS
		  FETCH NEXT FROM CUR_PROCESAR_LISTAS INTO  @NroLista,@HacerBackup,@ListaBakcup,@FECHA
	  
		  WHILE @@FETCH_STATUS = 0
			  BEGIN

				  EXEC @ULTIMO_ERROR =  CP_Listas_Precios_Precio_Nuevo_Actualizar @NroLista,@HacerBackup
				  IF @ULTIMO_ERROR <> 0
					 BEGIN
						 set @Mensaje = 'Error al ejecutar CP_Listas_Precios_Precio_Nuevo_Actualizar'
			 			 SELECT	 55					AS ErrorNumber 
								,0					AS ErrorSeverity  
								,0					AS ErrorState 
								,0					AS ErrorProcedure  
								,0					AS ErrorLine		
								,@Mensaje			AS ErrorMessage	

						 CLOSE CUR_PROCESAR_LISTAS
						 DEALLOCATE CUR_PROCESAR_LISTAS

						 RETURN 1
					 END				   
			   
  		          FETCH NEXT FROM CUR_PROCESAR_LISTAS INTO  @NroLista,@HacerBackup,@ListaBakcup,@FECHA
             END
		     CLOSE CUR_PROCESAR_LISTAS
		     DEALLOCATE CUR_PROCESAR_LISTAS


	SET @Mensaje = ''
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage


END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_Login_Extranet]	@pEmail_Web VARCHAR(300),
											@pClave_Web VARCHAR(30)
AS
BEGIN


CREATE TABLE #Cliente_Valido	(Id_Cliente			INT,
								Apellido			VARCHAR(100),
								Nombre				VARCHAR(100),
								Razon_Social		VARCHAR(100),
								Email_Web			VARCHAR(300))

INSERT INTO #Cliente_Valido
SELECT TOP 1
Id_Cliente, 
ISNULL(Apellido, '') AS Apellido, 
ISNULL(Nombre, '') AS Nombre, 
ISNULL(Razon_Social, '') AS Razon_Social, 
