CREATE PROCEDURE [dbo].[CP_MOV_STOCK] 
       @FECHA DATETIME,
	   @deposito varchar(10) = ''
AS

CREATE TABLE #MOV_STOCK  (
			 ID_PRODUCTO varchar(14)
			,Descripcion_Producto VARCHAR(300)
			,STK_INICIAL  DECIMAL(16,2)
			,COMPRAS  DECIMAL(16,2)
			,DEVOLUCIONES  DECIMAL(16,2)
			,VENTAS_DIA  DECIMAL(16,2)
			,TOTAL_DIA  DECIMAL(16,2)
			,VENTAS_MES  DECIMAL(16,2)
			,TOTAL_MES  DECIMAL(16,2)
			,VARIOS  DECIMAL(16,2)
			,STK_FINAL  DECIMAL(16,2)
		)

if(@deposito<>'')
begin

INSERT INTO #MOV_STOCK (ID_PRODUCTO, Descripcion_Producto,STK_INICIAL,COMPRAS,DEVOLUCIONES,VENTAS_DIA,TOTAL_DIA,VENTAS_MES,TOTAL_MES,VARIOS,STK_FINAL) 
       SELECT DISTINCT (p.id_producto),Descripcion_detallada,0,0,0,0,0,0,0,0,0 FROM Productos P,Cbtes C, Cbtes_Items ci 
	   WHERE Activo = 1 
	   AND Maneja_Stock = 1 
	   AND ID_FAMILIA  <> 7
	   AND c.Id_Trans = ci.Id_Trans
	   and ci.Id_Producto = p.Id_Producto
	   --and Id_Tipo_Cbte = 'rem'
	   and c.Id_Dep_Fisico = @deposito
	   ORDER BY  p.id_producto
	   

END

IF(@deposito='')
BEGIN

INSERT INTO #MOV_STOCK (ID_PRODUCTO, Descripcion_Producto,STK_INICIAL,COMPRAS,DEVOLUCIONES,VENTAS_DIA,TOTAL_DIA,VENTAS_MES,TOTAL_MES,VARIOS,STK_FINAL) 
       SELECT id_producto,Descripcion_detallada,0,0,0,0,0,0,0,0,0 FROM Productos 
	   WHERE Activo = 1 AND Maneja_Stock = 1 AND ID_FAMILIA  <> 7

END


  DECLARE @id_Producto char(14)
  DECLARE @Stock Decimal(17,4)
  DECLARE @Total Decimal(17,2)
  DECLARE @FECHA_DESDE DATETIME

  SET @FECHA_DESDE = convert(char(6), @FECHA, 112) + '01' 
  PRINT @FECHA_DESDE

--Calculo Stk_Fisico
  DECLARE Cursor_RecStock CURSOR FOR

		SELECT I.ID_PRODUCTO,SUM(I.Cantidad*T.Compromete_Stock) AS Stock 
		 FROM Cbtes_Items I,Cbtes C,Cbtes_Tipos T, PRODUCTOS P
		WHERE I.Id_Trans = C.Id_Trans  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND C.Id_Estado_Cbte <> 3 
		AND I.Id_Estado_Cbte <> 32 
		AND T.Compromete_Stock in (1,-1) 
		AND P.ID_PRODUCTO = I.ID_PRODUCTO
		AND P.ID_FAMILIA  <> 7
		AND isnull(i.id_producto,'') <> ''  
		AND (C.Fecha <= @FECHA  OR  C.Fecha IS NULL ) 
		AND I.Flag_QA = 'A' 
		GROUP BY I.ID_PRODUCTO  HAVING SUM(I.Cantidad*T.Compromete_Stock) <> 0
		ORDER BY I.ID_PRODUCTO
		
	
	OPEN Cursor_RecStock

	FETCH NEXT FROM Cursor_RecStock
	INTO @Id_Producto,@Stock

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update #MOV_STOCK SET STK_INICIAL = @Stock WHERE  Id_producto = @Id_Producto 

	 	FETCH NEXT FROM Cursor_RecStock
		INTO @Id_Producto, @Stock
	END

	CLOSE Cursor_RecStock
	DEALLOCATE Cursor_RecStock


--Calculo comprAS
  DECLARE Cursor_comprAS CURSOR FOR

		SELECT I.ID_PRODUCTO,SUM(I.Cantidad*T.Compromete_STOCK) AS Stock  
		FROM Cbtes_Items I,Cbtes C,Cbtes_Tipos T ,PRODUCTOS P 
		WHERE I.Id_Trans = C.Id_Trans  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND P.ID_PRODUCTO = I.ID_PRODUCTO
		AND P.ID_FAMILIA  <> 7
		AND C.Id_Estado_Cbte <> 3 
		AND I.Id_Estado_Cbte <> 32 
		AND T.Compromete_Stock in (1,-1) 
		AND T.Compromete_comprAS in (1,-1) 
		AND isnull(i.id_producto,'') <> ''  
		AND (C.Fecha >= @FECHA  and C.Fecha < @FECHA+1 ) 
		AND I.Flag_QA = 'A' 
		GROUP BY I.ID_PRODUCTO  HAVING SUM(I.Cantidad*T.Compromete_STOCK) <> 0
		ORDER BY I.ID_PRODUCTO
	
	OPEN Cursor_comprAS

	FETCH NEXT FROM Cursor_comprAS
	INTO @Id_Producto,@Stock

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update #MOV_STOCK SET ComprAS = @Stock WHERE  Id_producto = @Id_Producto 

	 	FETCH NEXT FROM Cursor_comprAS
		INTO @Id_Producto, @Stock
	END

	CLOSE Cursor_comprAS
	DEALLOCATE Cursor_comprAS	


--Calculo DEVOLUCIONES
  DECLARE Cursor_Devo CURSOR FOR

		SELECT I.ID_PRODUCTO,SUM(I.Cantidad*T.Compromete_factura) AS Stock
		  FROM Cbtes_Items I,Cbtes C,Cbtes_Tipos T ,PRODUCTOS P 
		WHERE I.Id_Trans = C.Id_Trans  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
		AND P.ID_PRODUCTO = I.ID_PRODUCTO
		AND P.ID_FAMILIA  <> 7  
		AND C.Id_Estado_Cbte <> 3 
		AND I.Id_Estado_Cbte <> 32 
		AND T.Compromete_Stock in (1,-1) 
		AND T.Compromete_factura in (-1) 
		AND isnull(i.id_producto,'') <> ''  
		AND (C.Fecha >= @FECHA  and C.Fecha < @FECHA+1 ) 
		AND I.Flag_QA = 'A' 
		GROUP BY I.ID_PRODUCTO  HAVING SUM(I.Cantidad*T.Compromete_factura) <> 0
		ORDER BY I.ID_PRODUCTO
	
	OPEN Cursor_Devo

	FETCH NEXT FROM Cursor_Devo
	INTO @Id_Producto,@Stock

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update #MOV_STOCK SET DEVOLUCIONES = @Stock WHERE  Id_producto = @Id_Producto 

	 	FETCH NEXT FROM Cursor_Devo
		INTO @Id_Producto, @Stock
	END

	CLOSE Cursor_Devo
	DEALLOCATE Cursor_Devo	

--Calculo VentAS
  DECLARE Cursor_VENTAS CURSOR FOR

		SELECT I.ID_PRODUCTO,SUM(I.Cantidad*T.Compromete_factura) AS Stock,SUM(I.Imp_Gravado*T.Compromete_factura*C.COTIZACION) AS Total 
		 FROM Cbtes_Items I,Cbtes C,Cbtes_Tipos T,PRODUCTOS P  
		WHERE I.Id_Trans = C.Id_Trans  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND P.ID_PRODUCTO = I.ID_PRODUCTO
		AND P.ID_FAMILIA  <> 7
		AND C.Id_Estado_Cbte <> 3 
		AND I.Id_Estado_Cbte <> 32 
		AND T.Compromete_Stock in (1,-1) 
		AND T.Compromete_factura in (1,-1) 
		AND I.Imp_Gravado <> 0
		AND isnull(i.id_producto,'') <> ''  
		AND (C.Fecha >= @FECHA  and C.Fecha < @FECHA+1 ) 
		AND I.Flag_QA = 'A' 	
		GROUP BY I.ID_PRODUCTO  HAVING SUM(I.Cantidad*T.Compromete_factura) <> 0
		ORDER BY I.ID_PRODUCTO
	
	OPEN Cursor_VENTAS

	FETCH NEXT FROM Cursor_VENTAS
	INTO @Id_Producto,@Stock,@Total

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update #MOV_STOCK SET VENTAS_DIA = @Stock-DEVOLUCIONES, TOTAL_DIA = @Total WHERE  Id_producto = @Id_Producto 

	 	FETCH NEXT FROM Cursor_VENTAS
		INTO @Id_Producto, @Stock,@Total
	END

	CLOSE Cursor_VENTAS
	DEALLOCATE Cursor_VENTAS	


--Calculo VentAS MES

  DECLARE Cursor_VENTAS_MES CURSOR FOR
		SELECT I.ID_PRODUCTO,SUM(I.Cantidad*T.Compromete_factura) AS Stock,SUM(I.Imp_Gravado*T.Compromete_factura*C.COTIZACION) AS Total 
		 FROM Cbtes_Items I,Cbtes C,Cbtes_Tipos T,PRODUCTOS P  
		WHERE I.Id_Trans = C.Id_Trans  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND P.ID_PRODUCTO = I.ID_PRODUCTO
		AND P.ID_FAMILIA  <> 7
		AND C.Id_Estado_Cbte <> 3 
		AND I.Id_Estado_Cbte <> 32 
		and i.Imp_Gravado <> 0 
		AND T.Compromete_Stock in (1,-1) 
		AND T.Compromete_factura in (1,-1) 
		AND isnull(i.id_producto,'') <> ''  
		AND (C.Fecha >= @FECHA_DESDE  and C.Fecha < @FECHA+1 ) 
		AND I.Flag_QA = 'A' 		
		GROUP BY I.ID_PRODUCTO  HAVING SUM(I.Cantidad*T.Compromete_factura) <> 0 
		ORDER BY I.ID_PRODUCTO
	
	OPEN Cursor_VENTAS_MES

	FETCH NEXT FROM Cursor_VENTAS_MES
	INTO @Id_Producto,@Stock,@Total

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update #MOV_STOCK SET VENTAS_MES = @Stock, TOTAL_MES = @Total WHERE  Id_producto = @Id_Producto 

	 	FETCH NEXT FROM Cursor_VENTAS_MES
		INTO @Id_Producto, @Stock,@Total
	END

	CLOSE Cursor_VENTAS_MES
	DEALLOCATE Cursor_VENTAS_MES	

--Calculo OTROS/VARIOS
  DECLARE Cursor_OTROS CURSOR FOR

		SELECT I.ID_PRODUCTO,SUM(I.Cantidad*T.Compromete_STOCK) AS Stock 
		 FROM Cbtes_Items I,Cbtes C,Cbtes_Tipos T,PRODUCTOS P
		WHERE I.Id_Trans = C.Id_Trans  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND P.ID_PRODUCTO = I.ID_PRODUCTO
		AND P.ID_FAMILIA  <> 7
		AND C.Id_Estado_Cbte <> 3 
		AND I.Id_Estado_Cbte <> 32 
	    AND T.Compromete_comprAS NOT IN (1,-1) 
		AND T.Compromete_Stock in (1,-1)
		AND ( T.Compromete_FACTURA NOT IN (1,-1) 
 		OR (T.Compromete_FACTURA IN (1,-1) AND I.Imp_Gravado = 0))
		AND isnull(i.id_producto,'') <> ''  
		AND (C.Fecha >= @FECHA  and C.Fecha < @FECHA+1 ) 
		AND I.Flag_QA = 'A' 	
		GROUP BY I.ID_PRODUCTO  HAVING SUM(I.Cantidad*T.Compromete_STOCK) <> 0
		ORDER BY I.ID_PRODUCTO
	
	OPEN Cursor_OTROS

	FETCH NEXT FROM Cursor_OTROS
	INTO @Id_Producto,@Stock

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update #MOV_STOCK SET VARIOS = @Stock WHERE  Id_producto = @Id_Producto 

	 	FETCH NEXT FROM Cursor_OTROS
		INTO @Id_Producto, @Stock
	END

	CLOSE Cursor_OTROS
	DEALLOCATE Cursor_OTROS	

--Calculo STK_ACTUAL
  DECLARE Cursor_STK_ACTUAL CURSOR FOR

		SELECT I.ID_PRODUCTO,SUM(I.Cantidad*T.Compromete_STOCK) AS Stock 
		 FROM Cbtes_Items I,Cbtes C,Cbtes_Tipos T ,PRODUCTOS P
		WHERE I.Id_Trans = C.Id_Trans  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
		AND P.ID_PRODUCTO = I.ID_PRODUCTO
		AND P.ID_FAMILIA  <> 7 
		AND C.Id_Estado_Cbte <> 3 
		AND I.Id_Estado_Cbte <> 32 
		AND T.Compromete_Stock in (1,-1) 
		AND isnull(i.id_producto,'') <> ''  
		AND (C.Fecha < @FECHA+1  OR  C.Fecha IS NULL ) 
		AND I.Flag_QA = 'A' 	
		GROUP BY I.ID_PRODUCTO  HAVING SUM(I.Cantidad*T.Compromete_STOCK) <> 0
		ORDER BY I.ID_PRODUCTO
	
	OPEN Cursor_STK_ACTUAL

	FETCH NEXT FROM Cursor_STK_ACTUAL
	INTO @Id_Producto,@Stock

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update #MOV_STOCK SET STK_FINAL = @Stock WHERE  Id_producto = @Id_Producto 

	 	FETCH NEXT FROM Cursor_STK_ACTUAL
		INTO @Id_Producto, @Stock
	END

	CLOSE Cursor_STK_ACTUAL
	DEALLOCATE Cursor_STK_ACTUAL	


SELECT * FROM #MOV_STOCK

drop table #MOV_STOCK



-- exec CP_MOV_STOCK '20180612'
GO


CREATE PROCEDURE [dbo].[CP_MatarProcesosBloqueados] @pBaseDatos VARCHAR(255) = NULL
AS 
SET NOCOUNT ON

DECLARE @SqlStr		NVARCHAR(4000)
DECLARE @SpId		INTEGER
DECLARE @SP_Who_Rta TABLE	(SpId		INT,
							Ecid		INT,
							Status		VARCHAR(200),
							LoginName	VARCHAR(255),
							HostName	VARCHAR(255),
							Blk			INT,
							DbName		VARCHAR(255),
							Cmd			VARCHAR(8000),
							Request_Id	INT)

INSERT INTO @SP_Who_Rta
EXEC sp_who

IF(@pBaseDatos IS NULL)
BEGIN
	--Para Todas las Bases de Datos
	DECLARE curCP_MatarProcesosBloqueados CURSOR FOR
	SELECT ISNULL(SpId, 0) 
	FROM @SP_Who_Rta 
	WHERE
	ISNULL(Blk, 0) <> 0 
	AND ISNULL(HostName, '') <> ''

	OPEN curCP_MatarProcesosBloqueados
	FETCH NEXT FROM curCP_MatarProcesosBloqueados INTO @SpId
	WHILE @@FETCH_STATUS = 0
	BEGIN

		SET @SqlStr = 'KILL ' + CAST(@SpId AS VARCHAR(10))
		EXEC (@SqlStr)

		FETCH NEXT FROM curCP_MatarProcesosBloqueados INTO @SpId
	END
	CLOSE curCP_MatarProcesosBloqueados
	DEALLOCATE curCP_MatarProcesosBloqueados
END
ELSE
BEGIN
	--SOLO para la Bases de Datos enviada en el parametro
	DECLARE curCP_MatarProcesosBloqueados CURSOR FOR
	SELECT ISNULL(SpId, 0) 
	FROM @SP_Who_Rta 
	WHERE
	ISNULL(Blk, 0) <> 0 
	AND ISNULL(HostName, '') <> ''
	AND ISNULL(DbName, '') = @pBaseDatos

	OPEN curCP_MatarProcesosBloqueados
	FETCH NEXT FROM curCP_MatarProcesosBloqueados INTO @SpId
	WHILE @@FETCH_STATUS = 0
	BEGIN

		SET @SqlStr = 'KILL ' + CAST(@SpId AS VARCHAR(10))
		EXEC (@SqlStr)

		FETCH NEXT FROM curCP_MatarProcesosBloqueados INTO @SpId
	END
	CLOSE curCP_MatarProcesosBloqueados
	DEALLOCATE curCP_MatarProcesosBloqueados
END

/*
EXEC dbo.CP_MatarProcesosBloqueados
EXEC dbo.CP_MatarProcesosBloqueados   'LHADM_Clever_Admin'
*/
GO


CREATE PROCEDURE [dbo].[CP_Persona_Temp_Aprobar] @Id_Cliente_Temp INT
AS

IF EXISTS (SELECT 1 FROM sys.objects WHERE name = 'CP_Clientes_Temp_Aprobar_' AND type = 'P')
BEGIN
		EXEC CP_Persona_Temp_Aprobar_ @Id_Cliente_Temp
		RETURN
END

DECLARE @Id_Unid_Negocio	VARCHAR(10)
DECLARE @Id_Cliente			INT
DECLARE @Categoria			INT
DECLARE @Nota_Part1			VARCHAR(10)
DECLARE @Direccion			VARCHAR(100)
DECLARE @Nro				INT
DECLARE @Piso				VARCHAR(10)
DECLARE	@Depto				VARCHAR(10)
DECLARE @DireccionTotal		VARCHAR(100)
DECLARE @Observacion		VARCHAR(100)
DECLARE @Razon_Social		VARCHAR(100)
DECLARE @Id_Concepto		INT
DECLARE @Id_Alias_Cta_Cont_Venta	SMALLINT
DECLARE @Mensaje			VARCHAR(100)
DECLARE @Lote				VARCHAR(100)
DECLARE @Id_IVA				CHAR(3)
DECLARE @Tipo_Persona		CHAR(1)
DECLARE @Id_Cond_Pago		SMALLINT
DECLARE @Id_Lista_Precio	SMALLINT

BEGIN TRY
	BEGIN TRAN

	SET @Id_Concepto				= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Concepto','A')
	SET @Id_Unid_Negocio			= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Unid_Negocio','A')
	SET @Id_IVA						= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_IVA','A')
	SET @Id_Cond_Pago				= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Cond_Pago','A')
	SET @Id_Lista_Precio			= dbo.CF_Preset_Valor(0,'Clientes:Ficha','?Cli:Id_Lista_Precio','A')


    SET @Id_Cliente = ISNULL((SELECT Id_Cliente FROM Clientes_Temp WHERE Id_Cliente_Temp=@Id_Cliente_Temp),0)

	IF @Id_Cliente = 0
	BEGIN
		SET @Observacion	= CONVERT(VARCHAR (10), @Id_Cliente_Temp)
		SET @Id_Cliente		= ISNULL((SELECT (MAX(ID_CLIENTE)+1) FROM Clientes),2)
		SET @Razon_Social	= (Select Razon_Social	from Clientes_Temp where Id_Cliente_Temp=@Id_Cliente_Temp)
		SET @Observacion	= CONVERT(VARCHAR (10), @Id_Cliente_Temp)
		
	

		INSERT INTO Clientes	(Id_Cliente,	Activo,		Razon_Social,		Apellido,		
								Nombre,			Sexo,		Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc, 
								Doc_Nro,		Direccion, 	Cp,					Id_Pais,		Id_Provincia,
								Provincia_Descrip, Id_Localidad, Localidad_Descrip,	Id_Nacionalidad, Email,  Email_Web,
								telefono,		Tel_Movil,	Id_estado_cliente,	Id_Lista_Precio,Id_Cond_Pago, 
								Id_Iva,			Id_Concepto, Id_Cond_vta,				Mercado,		Id_Tipo_Cli, 
								Id_Pais_Cob,	Fecha_Alta, Tipo_Persona,		Id_Unid_Negocio, Observacion,
								Id_Cli_Relac)
					select		@Id_Cliente,		1,		UPPER(Razon_Social),		UPPER(Apellido),		
								UPPER(Nombre),		Sexo,		Estado_Civil,		Fecha_Nac,		Id_Tipo_Doc, 
								Doc_Nro,		@DireccionTotal, Cp,			Id_Pais,		Id_Provincia,
								Provincia_Descrip, Id_Localidad, Localidad_Descrip, Id_Nacionalidad, Email,  Email, 
								telefono,		Tel_Movil,	0,					@Id_Lista_Precio,		@Id_Cond_Pago,				
								@Id_IVA,		@Id_Concepto, Id_Cond_vta,				'A',			Id_Tipo_Cli,	
								Id_Pais,		GETDATE(),	'F',		@Id_Unid_Negocio, @Observacion,
								Id_Cli_Relac
								from  Clientes_Temp WHERE id_cliente_temp=@Id_Cliente_Temp
	
		UPDATE Clientes_Temp SET Id_Cliente = @Id_Cliente WHERE id_cliente_temp=@Id_Cliente_Temp
		
		DELETE FROM Clientes_Fotos WHERE Id_Cliente=@Id_Cliente
		
		INSERT INTO Clientes_Fotos (Id_Cliente, Nro, Foto,Fecha) 
			SELECT TOP 1 @Id_Cliente, 1, Documento,GETDATE() From Clientes_Temp_Doc 
				WHERE Id_Cliente_Temp=@Id_Cliente_Temp AND Descripcion='FotoP'
		
		
	END
	ELSE
	BEGIN
		UPDATE Clientes 
				SET Razon_Social		= ct.Razon_Social, 
					Apellido			= ct.Apellido ,
					Nombre				= ct.Nombre ,
					Sexo				= ct.Sexo ,
					Estado_Civil		= ct.Estado_Civil ,
					Fecha_Nac			= ct.Fecha_Nac ,
					Id_Tipo_Doc			= ct.Id_Tipo_Doc, 
					Doc_Nro				= ct.Doc_Nro ,
					Direccion			= ct.Direccion, 
					Cp					= ct.Cp ,
					Id_Pais				= ct.Id_Pais, 
					Id_Provincia		= ct.Id_Provincia, 
					Provincia_Descrip	= ct.Provincia_Descrip, 
					Id_Localidad		= ct.Id_Localidad,
					Localidad_Descrip	= ct.Localidad_Descrip, 
					Id_Nacionalidad		= ct.Id_Nacionalidad, 
					Email				= ct.Email ,
					telefono			= ct.telefono ,
					Tel_Movil			= ct.Tel_Movil ,
					Id_Cli_Relac		= ct.Id_Cli_Relac,
					Id_Facebook			= ct.Id_Facebook, 
					Id_Instagram		= ct.Id_Instagram, 
					Id_Twitter			= ct.Id_Twitter ,
					Id_Linkedin			= ct.Id_Linkedin ,
					Id_Google			= ct.Id_Google ,
					Id_Microsoft		= ct.Id_Microsoft
				FROM 
					Clientes cl, Clientes_Temp ct
				WHERE 
					cl.Id_Cliente=@Id_Cliente
					and ct.id_cliente_temp=@Id_Cliente_Temp
	END

	UPDATE Clientes_Temp SET Id_Estado_Solicitud = 'A' WHERE id_cliente_temp=@Id_Cliente_Temp
	SET @Lote = (SELECT ISNULL(Nro_Trans_Pago,0) FROM Clientes_Temp WHERE id_cliente_temp=@Id_Cliente_Temp)
	
	COMMIT
	IF @Lote<>0
	BEGIN
	EXEC CP_Clientes_Temp_Actualizar_Cbte @Lote, @Id_Cliente

	IF EXISTS (SELECT 1 FROM sys.objects WHERE name = 'CP_Clientes_Temp_Aprobar_After' AND type = 'P')
		EXEC CP_Clientes_Temp_Aprobar_After @Id_Cliente_Temp

	SELECT	 0			AS ErrorNumber 
			,0			AS ErrorSeverity  
			,0			AS ErrorState 
			,0			AS ErrorProcedure  
			,0			AS ErrorLine		
			,@Mensaje	AS ErrorMessage	
	END 

END TRY  
	

BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO



CREATE PROCEDURE [dbo].[CP_Picking_Preparar_Sinc]	@pId_Trans	INT
AS
/*Declaracion Variables*/
DECLARE @strSQL					NVARCHAR(MAX)
DECLARE @Picking_Est_Pend		INT
DECLARE @Picking_Est_Parc		INT
DECLARE @tiposCbtesPicking		VARCHAR(40)
DECLARE @filtro_Flag_QA			VARCHAR(40)
DECLARE @Id_Cliente				INT
/*FINDeclaracion Variables*/

SET @Picking_Est_Pend	= (dbo.CF_xParam('Picking_Est_Pend'))
SET @Picking_Est_Parc	= (dbo.CF_xParam('Picking_Est_Parc'))
SET @tiposCbtesPicking	= (dbo.CF_xParam('Cbtes_Picking'))
SET @filtro_Flag_QA		= (dbo.CF_xParam('Picking_EsQACajDisp'))
SET @Id_Cliente			= (SELECT ISNULL(Id_Cliente, 0) FROM Cbtes WHERE Id_Trans = @pId_Trans)


DELETE  Picking_Cajas_Disp WHERE Id_Producto IN (SELECT I.ID_PRODUCTO FROM Picking_Cbtes_Items I, Picking_Cbtes C
       WHERE I.ID_TRANS = C.ID_TRANS AND C.Id_Estado_Cbte = 3)

DELETE  Picking_Cbtes_Items	FROM Picking_Cbtes_Items I, Picking_Cbtes C WHERE I.ID_TRANS = C.ID_TRANS AND C.Id_Estado_Cbte = 3

DELETE  Picking_Cbtes  WHERE Id_Estado_Cbte = 3

SET @strSQL =	' INSERT INTO Picking_Cbtes ' +
				' ( ' +
				' Id_Trans, Comprobante_Nro, Id_Estado_Cbte, Id_Tipo_Cbte, ' +
				' Id_Dep_Fisico, Id_Dep_Logico, Destinatario, ' +
				' Id_Cliente, NroImpresion' +
				' ) ' +
				' SELECT ' +
				' Id_Trans, Comprobante_Nro, 31 AS Id_Estado_Cbte, Id_Tipo_Cbte, ' +
				' Id_Dep_Fisico, Id_Dep_Logico, Destinatario, '+
				' ISNULL(Id_Cliente, 0) AS Id_Cliente, ' +
				' ISNULL(NroImpresion, 0) AS NroImpresion ' +
				' FROM Cbtes ' +
				' WHERE ' +
				' Id_Estado_Cbte IN (' + CONVERT(VARCHAR(10), @Picking_Est_Pend) +', ' + CONVERT(VARCHAR(10), @Picking_Est_Parc) + ') ' +
				' AND Id_Tipo_Cbte IN ' + @tiposCbtesPicking +
				' AND Id_Trans = ' + CONVERT(VARCHAR(10), @pId_Trans)

EXEC sp_executesql @strSQL
     
SET @strSQL =   ' UPDATE CBTES SET ID_ESTADO_CBTE = 29 WHERE Id_Trans = ' + CONVERT(VARCHAR(10), @pId_Trans)

EXEC sp_executesql @strSQL

SET @strSQL =	' INSERT INTO Picking_Cajas_Disp ' +
				' ( ' +
				' Id_Cliente, Id_Producto, Analisis, ' +
				' Lote, Serie, Stock ' +
				' ) ' +
				' SELECT ISNULL(I.Id_Cliente, 0) AS Id_Cliente, I.Id_Producto, I.Analisis, I.Lote, I.Serie, SUM(I.Cantidad * T.Compromete_Stock) AS Stock ' +
				' FROM Cbtes_Items I, Cbtes C, Cbtes_tipos T ' + 
				' WHERE ' +
				' C.Id_Trans = I.Id_Trans ' +
				' AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte ' +
				' AND T.Compromete_Stock IN (1,-1) ' +
				' AND I.Id_Producto IN (SELECT DISTINCT Id_Producto FROM Cbtes_Items P WHERE P.Id_Estado_Cbte Not in (32,2,3) And Id_Trans = ' + CONVERT(VARCHAR(10), @pId_Trans) + ') ' +
				' AND (ISNULL(I.Id_Cliente,0) = 0 OR I.Id_Cliente = ' + CONVERT(VARCHAR(10), @Id_Cliente) + ') ' +
				' AND I.Id_Estado_Cbte <> ' + CONVERT(VARCHAR(10), @Picking_Est_Parc) +
				' AND ((C.Id_Tipo_Cbte NOT IN (''PICK'',''PIKT'',''PIKB'') AND C.Id_Estado_Cbte NOT IN (3, 31)) OR (C.Id_Tipo_Cbte IN (''PICK'',''PIKT'',''PIKB'') AND I.Id_Estado_Cbte = 2)) ' +
				' AND C.Id_Estado_Cbte <> 3 ' +
				' AND I.Flag_QA IN (' + @filtro_Flag_QA +') ' +
				' GROUP BY ISNULL(I.Id_Cliente, 0), I.Id_Producto, I.Analisis, I.Lote, I.Serie ' +
				' HAVING Sum(I.Cantidad * T.Compromete_Stock) > 0'

EXEC sp_executesql @strSQL

SET @strSQL =	' INSERT INTO Picking_Cbtes_Items ' +				
				' ( ' +
				' Id_Trans, Item, Id_Estado_Cbte, ' +
				' Id_Producto, Cantidad, Analisis, ' +
				' Observacion, Id_Unidad_Medida, Calle, ' +
				' Columna, Fila, Lote, Serie ' +
				' ) ' +
				' SELECT ' +
				' Id_Trans, Item, Id_Estado_Cbte, ' +
				' Id_Producto, Cantidad, LTRIM(RTRIM(Analisis)) AS Analisis, ' +
				' Observacion, Id_Unidad_Medida, Calle, ' +
				' Columna, Fila, Lote, LTRIM(RTRIM(Serie)) AS Serie ' +
				' FROM Cbtes_Items ' +
				' WHERE ' +
				' Id_Estado_Cbte = 1 ' +
				' AND Id_Trans = ' + CONVERT(VARCHAR(10), @pId_Trans)

EXEC sp_executesql @strSQL		


--UPDATE CBTES SET Id_Estado_Cbte = 31 WHERE ID_TRANS = @pId_Trans 


--update PICKING_cbtes set id_estado_cbte = 3 where id_trans = 184684

--exec CP_Picking_Preparar_Sinc 184684

--select * from Picking_Cbtes

--select * from Picking_Cbtes_Items

--select * from Picking_Cajas_Disp

--delete Picking_Cbtes

--delete Picking_Cbtes_Items

--delete Picking_Cajas_Disp
GO


CREATE PROCEDURE [dbo].[CP_Productos_Cobros](
     @pUsuario INT
   , @pEquate  SMALLINT
   , @pFechaDesde DATETIME
   , @pFechaHasta DATETIME
   , @GenerarLiquidacion TINYINT
   , @Id_Periodo_Caja INT
   , @Detallar_FPago SMALLINT
   , @Tipo_Cob CHAR(1)    -- vacio = todos  M = Manual L=Lote
   )
AS

  CREATE TABLE #Trans (Id_Trans INT)

  IF @pEquate = 0
     RETURN

  DECLARE @Id_Producto Varchar(14)
  ,@Id_Proveedor Int
  ,@Razon_Social VarChar(100)
  ,@Cuit Varchar(13)
  ,@Id_Iva Char(3)
  ,@Id_Alias_Cta_Cont Int
  ,@Id_Cta_Contable_H Int
  ,@Porc_Comision_Prov Decimal(7,2) 
  ,@Importe Decimal(12,2) 
  ,@IMPORTE_CREDITO Decimal(12,2) 
  ,@ID_TIPO_CBTE CHAR(4) 
  ,@FECHA DATETIME
  ,@Imp_prod_siva  Decimal(12,2) 
  ,@TRANS INT
  ,@Id_Cliente_Externo VARCHAR(14)
  ,@Id_Cta_Banco INT
  ,@Id_Cliente INT
  ,@EXISTE_TAG INT

  SET @FECHA = (SELECT CAST(GETDATE() AS DATE))

  DECLARE @Sql		    VARCHAR(MAX)
  DECLARE @SqlSaldo	    VARCHAR(MAX)
  DECLARE @SqlSelect	VARCHAR(MAX)
  DECLARE @SqlInto	    VARCHAR(MAX)
  DECLARE @SqlFrom	    VARCHAR(MAX)
  DECLARE @SqlWhere  	VARCHAR(MAX)
  DECLARE @SqlGroup	    VARCHAR(MAX)

  SET @EXISTE_TAG = 0
  SET @EXISTE_TAG = (SELECT COUNT(*) FROM TagFilePos_ TAG WHERE TAG.TBL = @pEquate AND TAG.USR = @pUsuario)

  SELECT (i.Imp_Gravado * F.Cotizacion) as Imp_Gravado_Item													--1
		,(i.Imp_Final * F.Cotizacion) as Imp_Final_Item														--2
		,f.Id_trans as Id_Trans_Fac																			--3
		,(f.Imp_Gravado + f.Imp_Gravado2 + f.Imp_Gravado3 + f.Imp_Exento) * F.Cotizacion as Importe_Fac		--4
		,f.Imp_total * F.Cotizacion as Imp_total_Fac														--5
		,r.Id_trans as Id_Trans_Rec																			--6
		,a.Importe  as Importe_Aplicado																		--7
		,i.Fecha_QA																							--8
		,i.Fecha_Venc																						--9
		,i.Id_cliente																						--10
		,C.Nombre_Fantasia																					--11
		,C.Id_Cliente_Externo																				--12
		,C.Razon_Social																						--13
		,C.Id_Tipo_Cli																						--14
		,dbo.CF_Cbte_Descrip(f.id_trans) as Desc_Factura													--15
		,F.Fecha																							--16
		,dbo.CF_Cbte_Descrip(R.id_trans) as Desc_Recibo														--17
		,R.Fecha as Fecha_Rec																				--18
		,R.Imp_Total as Imp_Total_Rec																		--19
		,R.Id_Estado_Cbte																					--20
		,R.Cotizacion as Cotizacion_Rec																		--21
		,F.Cotizacion as Cotizacion_Fac																		--22
		,F.Porc_Bonificacion																				--23
		,F.Id_Cobrador																						--24
		,I.Id_Producto																						--25
		,P.Descripcion_Detallada																			--26
		,P.Id_Familia																						--27
		,FP.Descripcion as Descripcion_Familia																--28
		,(a.Importe / f.Imp_total) * 100 as porc_aplicado													--29
		,(i.Imp_Final *  F.Cotizacion )  * ( a.Importe / f.Imp_total) * (1 -(F.Porc_Bonificacion / 100)) as imp_prod_civa --30
		,(i.Imp_Gravado * F.Cotizacion ) * ( a.Importe / f.Imp_total) * (1 -(F.Porc_Bonificacion / 100)) as imp_prod_siva --31
		,V.DESCRIPCION AS NOMBRE_COBRADOR																	--32
		,[dbo].[SF_Cli_Categ_Mes](i.Id_cliente, isnull(i.Fecha_QA,F.Fecha)) as Tipo_Cli						--33
		,CT.DESCRIPCION																						--34
		,isnull(c.id_cliente_ref,0) as id_cliente_ref														--35
		,cast(0 as decimal(12,2)) AS EFECTIVO																--36
		,cast(0 as decimal(12,2)) AS TARJETA																--37
		,cast(0 as decimal(12,2)) AS CHEQ_TER																--38
		,cast(0 as decimal(12,2)) AS CHEQ_PROP																--39
		,cast(0 as decimal(12,2)) AS DEBITO																	--40
		,cast(0 as decimal(12,2)) AS FINANC																	--41
		,cast(0 as decimal(12,2)) AS OTROS																	--42
		,cast(0 as decimal(12,2)) AS Total_Pagos															--43
		,cast(0 as decimal(12,2)) AS Dif																	--44
		,i.Item as Item_Fac																					--45
		,cast(0 as decimal(12,5)) AS Coef_Pago																--46 
		,ISNULL(C.Id_Cond_Pago, 0) AS Id_Cond_Pago															--47 14/01/2020 Agregado Ticket 18.924
		,ISNULL(CCP.Descripcion, '') AS Cond_Pago															--48 14/01/2020 Agregado Ticket 18.924
		,f.Imp_Percep AS Imp_Total_Percep_Reten_Fac															--49 14/01/2020 Agregado Ticket 18.924
		,r.Imp_Percep AS Imp_Total_Percep_Reten_Rec															--50 14/01/2020 Agregado Ticket 18.924
		,CLFC.Nombre_Fantasia		AS FC_CL_Nombre_Fantasia												--51 27/01/2021
		,CLFC.Id_Cliente_Externo	AS FC_CL_Id_Cliente_Externo												--52 27/01/2021
		,CLFC.Razon_Social			AS FC_CL_Razon_Social													--53 27/01/2021
		,CLFC.Id_Tipo_Cli			AS FC_CL_Id_Tipo_Cli													--54 27/01/2021
		,C.Id_Cobrador				AS CL_Id_Cobrador														--55 04/02/2021
		,CP.Id_Caja					AS Id_Caja																--56 04/02/2021
		,I.Bonif					AS Porc_Bonif_Item														--57 13/04/2021 Agregado Ticket 22.253
		,((100 * I.Imp_Final) / (100-I.Bonif)) AS Imp_Final_Item_Sin_Desc									--58 13/04/2021 Agregado Ticket 22.253
		,(((100 * I.Imp_Final) / (100-I.Bonif)) * (I.Bonif / 100)) AS Imp_Bonif_Item						--59 13/04/2021 Agregado Ticket 22.253
   INTO #Reporte
   FROM cbtes_items i,cbtes f,cbtes_aplica a,cbtes r, cbtes_tipos tr, Cbtes_Tipos TF, Clientes C,TagFilePos_ TAG, Productos P,Prod_Familias FP, Vendedores V, Clientes_Tipos CT, Cbtes_Cond_Pago CCP, Clientes CLFC, Cajas_Mov CM, Cajas_Periodos CP
   WHERE 1=0

   SET @SqlSelect =  ' SELECT (i.Imp_Gravado * F.Cotizacion) as Imp_Gravado_Item     --1
							  ,(i.Imp_Final * F.Cotizacion) as Imp_Final_Item               --2
							  ,f.Id_trans as Id_Trans_Fac                                   --3
							  ,(f.Imp_Gravado + f.Imp_Gravado2 + f.Imp_Gravado3 + f.Imp_Exento) * F.Cotizacion as Importe_Fac   --4
							  ,f.Imp_total * F.Cotizacion as Imp_total_Fac   --5
							  ,r.Id_trans as Id_Trans_Rec                    --6
							  ,a.Importe  as Importe_Aplicado                --7
							  ,i.Fecha_QA                                    --8
							  ,i.Fecha_Venc                                  --9
							  ,CASE
								WHEN i.Id_Cliente IS NULL THEN F.Id_Cliente  --10
								WHEN i.Id_Cliente = 0 THEN F.Id_Cliente
								ELSE i.Id_Cliente
								END AS Id_Cliente
							  ,C.Nombre_Fantasia                             --11
							  ,C.Id_Cliente_Externo                          --12
							  ,C.Razon_Social                                --13
							  ,C.Id_Tipo_Cli                                 --14
							  ,dbo.CF_Cbte_Descrip(f.id_trans) as Desc_Factura    --15
							  ,F.Fecha                                            --16
							  ,dbo.CF_Cbte_Descrip(R.id_trans) as Desc_Recibo     --17
							  ,R.Fecha as Fecha_Rec								  --18
							  ,R.Imp_Total as Imp_Total_Rec					      --19
							  ,R.Id_Estado_Cbte									  --20
							  ,R.Cotizacion as Cotizacion_Rec                     --21
							  ,F.Cotizacion as Cotizacion_Fac                     --22
							  ,F.Porc_Bonificacion								  --23
							  ,F.Id_Cobrador								      --24
							  ,I.Id_Producto									  --25
							  ,P.Descripcion_Detallada						      --26
							  ,P.Id_Familia										  --27
							  ,FP.Descripcion as Descripcion_Familia              --28
							  ,(R.Imp_Total / (select sum(z.Importe) from cbtes_aplica z where z.id_trans_d = r.id_trans  and z.importe > 1))*100 as porc_aplicado   --29
							  ,(i.Imp_Final *  F.Cotizacion )  * ( a.Importe / f.Imp_total) * (R.Imp_Total / (select sum(z.Importe) from cbtes_aplica z where z.id_trans_d = r.id_trans  and z.importe > 1)) * (1 -(F.Porc_Bonificacion / 100)) as imp_prod_civa --30
							  ,(i.Imp_Gravado * F.Cotizacion ) * ( a.Importe / f.Imp_total) * (R.Imp_Total / (select sum(z.Importe) from cbtes_aplica z where z.id_trans_d = r.id_trans  and z.importe > 1)) * (1 -(F.Porc_Bonificacion / 100)) as imp_prod_siva --31
							  ,V.DESCRIPCION AS NOMBRE_COBRADOR                                               --32
							  ,[dbo].[SF_Cli_Categ_Mes](i.Id_cliente, isnull(i.Fecha_QA,F.Fecha)) as Tipo_Cli --33
							  ,CT.DESCRIPCION                                                                 --34
							  ,isnull(c.id_cliente_ref,0) as id_cliente_ref                                   --35
							  ,cast(0 as decimal(12,2)) AS EFECTIVO                                           --36
							  ,cast(0 as decimal(12,2)) AS TARJETA                                            --37
							  ,cast(0 as decimal(12,2)) AS CHEQ_TER                                           --38
							  ,cast(0 as decimal(12,2)) AS CHEQ_PROP                                          --39
							  ,cast(0 as decimal(12,2)) AS DEBITO                                             --40
							  ,cast(0 as decimal(12,2)) AS FINANC                                             --41
							  ,cast(0 as decimal(12,2)) AS OTROS                                              --42
							  ,cast(0 as decimal(12,2)) AS Total_Pagos                                        --43
							  ,cast(0 as decimal(12,2)) AS Dif                                                --44
							  ,i.Item as Item_Fac															  --45
							  ,cast(0 as decimal(12,5)) AS Coef_Pago										  --46  
							  ,ISNULL(C.Id_Cond_Pago, 0) AS Id_Cond_Pago									--47 14/01/2020 Agregado Ticket 18.924
							  ,ISNULL(CCP.Descripcion, '''') AS Cond_Pago									--48 14/01/2020 Agregado Ticket 18.924
							  ,f.Imp_Percep AS Imp_Total_Percep_Reten_Fac									--49 14/01/2020 Agregado Ticket 18.924
							  ,r.Imp_Percep AS Imp_Total_Percep_Reten_Rec									--50 14/01/2020 Agregado Ticket 18.924
							  ,CLFC.Nombre_Fantasia		AS FC_CL_Nombre_Fantasia							--51 27/01/2021
							  ,CLFC.Id_Cliente_Externo	AS FC_CL_Id_Cliente_Externo							--52 27/01/2021
							  ,CLFC.Razon_Social		AS FC_CL_Razon_Social								--53 27/01/2021
							  ,CLFC.Id_Tipo_Cli			AS FC_CL_Id_Tipo_Cli								--54 27/01/2021
							  ,C.Id_Cobrador			AS CL_Id_Cobrador								    --55 04/02/2021
							  ,CP.Id_Caja				AS Id_Caja											--56 04/02/2021
							  ,I.Bonif					AS Porc_Bonif_Item									--57 13/04/2021 Agregado Ticket 22.253
							  ,CASE ISNULL(I.Imp_Final,0) WHEN 0 THEN 0
							    ELSE  ((I.Imp_Final) / (1-(I.Bonif/100)) ) END AS Imp_Final_Item_Sin_Desc	--58 13/04/2021 Agregado Ticket 22.253
							
							  ,CASE ISNULL(I.Imp_Final,0) WHEN 0 THEN 0
							    ELSE  ((I.Imp_Final) / (1-(I.Bonif/100)) ) - I.Imp_Final END AS Imp_Bonif_Item	--59 13/04/2021 Agregado Ticket 22.253
'
/*
							  ,((100 * I.Imp_Final) / (100-I.Bonif)) AS Imp_Final_Item_Sin_Desc				--58 13/04/2021 Agregado Ticket 22.253
							  ,(((100 * I.Imp_Final) / (100-I.Bonif)) * (I.Bonif / 100)) AS Imp_Bonif_Item	--59 13/04/2021 Agregado Ticket 22.253
							  '
*/
  SET @SqlInto = ' ' 

  SET @SqlWhere = 'WHERE r.id_tipo_cbte = tr.id_tipo_cbte
						    AND tr.compromete_recibos in (1,-1)
							AND r.id_cliente = c.id_Cliente
							AND ISNULL(F.Id_Cliente, 0) = CLFC.Id_Cliente
							AND a.id_trans_d = r.id_trans 
							AND f.id_trans = a.id_trans 
							AND f.id_estado_cbte in (1,2,4) 
							AND r.id_estado_cbte in (2,4)
							AND i.id_trans = f.id_trans 
							AND f.id_tipo_cbte = TF.id_tipo_cbte 
							AND I.Id_Producto = P.Id_Producto
							AND ISNULL(P.Id_Familia,0) = ISNULL(FP.Id_Familia,0)
							AND ISNULL(F.Id_Cond_Pago, 0) = ISNULL(CCP.Id_Cond_Pago, 0)
							AND CM.Id_Trans = R.Id_Trans
							AND CM.Id_Periodo_Caja = CP.Id_Periodo_Caja
							AND r.Fecha >= ''' + CONVERT(VARCHAR(8),@pFechaDesde   ,112) + '''
							AND r.Fecha <  ''' + CONVERT(VARCHAR(8),@pFechaHasta+1 ,112) + '''
							AND F.Imp_total <> 0
							AND R.Imp_Total <> 0
							AND TF.Compromete_Factura = 1 
							AND ISNULL(F.Id_Cobrador,'''') = ISNULL(V.Id_Vendedor,'''')
 							AND ISNULL(CT.ID_TIPO_CLI,0) = ISNULL([dbo].[SF_Cli_Categ_Mes](i.Id_cliente, isnull(i.Fecha_QA,F.Fecha)),0)'

  IF UPPER(@Tipo_Cob) = 'M'
	 SET @SqlWhere = LTRIM(RTRIM(@SqlWhere)) + '	AND ISNULL(R.Lote,'''') = '''''

  IF ISNULL(@Tipo_Cob,'') = 'L'
	 SET @SqlWhere = LTRIM(RTRIM(@SqlWhere)) + '	AND ISNULL(R.Lote,'''') != '''''


  IF @EXISTE_TAG > 0
  BEGIN
	  SET @SqlFrom = 'FROM cbtes_items i,cbtes f,cbtes_aplica a,cbtes r, cbtes_tipos tr, Cbtes_Tipos TF, Clientes C,TagFilePos_ TAG, Productos P,Prod_Familias FP, Vendedores V, Clientes_Tipos CT, Clientes CLFC, Cbtes_Cond_Pago CCP, Cajas_Mov CM, Cajas_Periodos CP'
      SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND (i.id_producto = TAG.POS 
							      AND TAG.TBL = ' + CAST(@pEquate  AS VARCHAR(10))  + '
								  AND TAG.USR = ' + CAST(@pUsuario AS VARCHAR(10)) + '
								 ) ' 
  END
  ELSE
  BEGIN
	  SET @SqlFrom = 'FROM cbtes_items i,cbtes f,cbtes_aplica a,cbtes r, cbtes_tipos tr, Cbtes_Tipos TF, Clientes C, Productos P,Prod_Familias FP, Vendedores V, Clientes_Tipos CT, Clientes CLFC, Cbtes_Cond_Pago CCP, Cajas_Mov CM, Cajas_Periodos CP'
  END
  

  SET @Sql = @SqlSelect + ' ' + @SqlInto +' '+ @SqlFrom + ' ' + @SqlWhere 

 EXEC('INSERT INTO #Reporte ' + @sql)
							 

  IF @Detallar_FPago = 1
      BEGIN 
		  Select Distinct(Id_Trans_Rec) Into #Cbtes_a_Procesar From #Reporte

		  SELECT VM.Id_Trans, MAX(VM.Renglon_Nro) AS Renglon_Nro
		  INTO #Max_Renglon 
		  FROM Valores_Mov VM , #Cbtes_a_Procesar C WHERE VM.Id_Trans = C.Id_Trans_Rec
		  GROUP BY VM.Id_Trans

		  Select VM.Id_Trans as Id_Trans_Rec,V.Id_Tipo_Val,Sum(V.Importe) AS IMPORTE 
		  INTO #SUMA_PAGOS 
		  from #Cbtes_a_Procesar C, Valores_Mov VM, Valores V, #Max_Renglon MR
		  WHERE C.Id_Trans_Rec = VM.Id_Trans AND V.Id_Valor = VM.ID_VALOR AND VM.Id_Trans = MR.Id_Trans AND VM.Renglon_Nro = MR.Renglon_Nro
		  GROUP BY VM.Id_Trans,V.Id_Tipo_Val

		  CREATE INDEX INDEX_SUMA_PAGOS ON #SUMA_PAGOS (Id_Trans_Rec,Id_Tipo_Val)

		  SELECT D.Id_Trans_Rec,R.Id_Trans_Fac,R.Item_Fac,
			 (SELECT ISNULL(SUM(IMPORTE),0) FROM #SUMA_PAGOS WHERE Id_Trans_Rec = D.Id_Trans_Rec AND D.ID_TIPO_VAL = 'EFE') * (Imp_prod_civa/Imp_Total_Rec) AS EFECTIVO,
			 (SELECT ISNULL(SUM(IMPORTE),0) FROM #SUMA_PAGOS WHERE Id_Trans_Rec = D.Id_Trans_Rec AND D.ID_TIPO_VAL = 'TAR') * (Imp_prod_civa/Imp_Total_Rec) AS TARJETA,
			 (SELECT ISNULL(SUM(IMPORTE),0) FROM #SUMA_PAGOS WHERE Id_Trans_Rec = D.Id_Trans_Rec AND D.ID_TIPO_VAL = 'CH3') * (Imp_prod_civa/Imp_Total_Rec) AS CHEQ_TER,
			 (SELECT ISNULL(SUM(IMPORTE),0) FROM #SUMA_PAGOS WHERE Id_Trans_Rec = D.Id_Trans_Rec AND D.ID_TIPO_VAL = 'CHP') * (Imp_prod_civa/Imp_Total_Rec) AS CHEQ_PROP,
			 (SELECT ISNULL(SUM(IMPORTE),0) FROM #SUMA_PAGOS WHERE Id_Trans_Rec = D.Id_Trans_Rec AND D.ID_TIPO_VAL = 'DB') * (Imp_prod_civa/Imp_Total_Rec) AS DEBITO,
			 (SELECT ISNULL(SUM(IMPORTE),0) FROM #SUMA_PAGOS WHERE Id_Trans_Rec = D.Id_Trans_Rec AND D.ID_TIPO_VAL = 'FIN') * (Imp_prod_civa/Imp_Total_Rec) AS FINANC,
			 (SELECT ISNULL(SUM(IMPORTE),0) FROM #SUMA_PAGOS WHERE Id_Trans_Rec = D.Id_Trans_Rec AND D.ID_TIPO_VAL NOT IN ('EFE','TAR','CH3','CHP','DB','FIN') ) * (Imp_prod_civa/Imp_Total_Rec) AS OTROS    
			 ,Imp_prod_civa/Imp_Total_Rec as Coef_Pago
			 INTO #DETALLE_PAGOS
			 FROM #SUMA_PAGOS D, #Reporte R 
			 WHERE D.Id_Trans_Rec = R.Id_Trans_Rec  

		UPDATE  #Reporte SET EFECTIVO = D.EFECTIVO, TARJETA = D.TARJETA, CHEQ_TER = D.CHEQ_TER, CHEQ_PROP = D.CHEQ_PROP, DEBITO = D.DEBITO, OTROS = D.OTROS
		         ,Total_Pagos = D.EFECTIVO + D.TARJETA + D.CHEQ_TER + D.CHEQ_PROP + D.DEBITO + D.OTROS
				 ,Dif = D.EFECTIVO + D.TARJETA + D.CHEQ_TER + D.CHEQ_PROP + D.DEBITO + D.OTROS - imp_prod_civa
				 ,Coef_Pago = D.Coef_Pago
				FROM #DETALLE_PAGOS D, #Reporte R 
				 WHERE D.Id_Trans_Rec = R.Id_Trans_Rec 
				   AND D.Id_Trans_Fac = R.Id_Trans_Fac
				   AND D.Item_Fac = R.Item_Fac
				  
	    DROP TABLE  #DETALLE_PAGOS
		DROP TABLE  #SUMA_PAGOS
		DROP TABLE  #Cbtes_a_Procesar
     END

 -- SELECT * FROM #Reporte
 

  IF @GenerarLiquidacion = 1
	  BEGIN
	  DECLARE CUR_GENERAR CURSOR FOR

	  SELECT R.Id_Producto,P.Id_Proveedor,O.Razon_Social,O.Cuit,O.Id_Iva,P.Id_Alias_Cta_Cont,O.Id_Cta_Contable_H,P.Porc_Comision_Prov,P.Id_Cta_Banco,SUM(R.imp_prod_siva) 
              FROM #Reporte R, Productos P, Proveedores O		
			  Where R.Id_Producto = P.Id_Producto And P.Id_Proveedor = O.Id_Proveedor
			  And (Isnull(P.Id_Proveedor,0) <> 0
			  Or Isnull(P.Id_Cta_Banco,0) <> 0)
			  Group by R.Id_Producto,P.Id_Proveedor,O.Razon_Social,O.Cuit,O.Id_Iva,P.Id_Alias_Cta_Cont,O.Id_Cta_Contable_H,P.Porc_Comision_Prov,P.Id_Cta_Banco

	  OPEN CUR_GENERAR
	  FETCH NEXT FROM CUR_GENERAR INTO  @Id_Producto,@Id_Proveedor,@Razon_Social,@Cuit,@Id_Iva,@Id_Alias_Cta_Cont,@Id_Cta_Contable_H,@Porc_Comision_Prov,@Id_Cta_Banco,@Importe
	  WHILE @@FETCH_STATUS = 0
	      BEGIN
		         DELETE #Trans
                 IF @Id_Proveedor > 0
				    BEGIN
						 SET @ID_TIPO_CBTE =  (select Valor_String from xParametros where setDatos= 1 and idParametro ='T_Cbte_Deb_Liq_Ter')

						 INSERT INTO #Trans
							 EXEC dbo.CP_Cbtes_Cpra_Generar  @Id_Proveedor,@Razon_Social,@Importe,1,@FECHA,@ID_TIPO_CBTE,'',1,10,100,@trans OUTPUT
                    END
				   ELSE
				    BEGIN
						 SET @ID_TIPO_CBTE =  (select Valor_String from xParametros where setDatos= 1 and idParametro ='T_Cbte_Dep_Cta_Prom')

						 INSERT INTO #Trans
							 EXEC dbo.CP_Cbtes_Deposito_Generar  @Id_Cta_Banco,@Razon_Social,@Importe,1,@FECHA,@ID_TIPO_CBTE,'',2,10,100,@Id_Periodo_Caja,@trans OUTPUT

						 SET @ID_TIPO_CBTE =  (select Valor_String from xParametros where setDatos= 1 and idParametro ='T_Cbte_OP_Prom')

						 EXEC dbo.CP_Cbtes_OP_Varia_Generar  @Id_Cta_Banco,@Razon_Social,@Importe,1,@FECHA,@ID_TIPO_CBTE,'',2,10,100,@Id_Periodo_Caja,@trans OUTPUT

						 SET @trans = 0
					END

				 If @trans > 0
				    Begin
						 DECLARE CUR_GENERAR_ITEMS CURSOR FOR

						 SELECT R.Razon_Social,R.Imp_prod_siva,R.Id_Cliente_Externo 
								  FROM #Reporte R	
								  Where R.Id_Producto = @Id_Producto

						 OPEN CUR_GENERAR_ITEMS
						 FETCH NEXT FROM CUR_GENERAR_ITEMS INTO  @Razon_Social,@Imp_prod_siva,@Id_Cliente_Externo
						 WHILE @@FETCH_STATUS = 0
						 BEGIN
				              SET @Razon_Social = LTRIM(RTRIM(@Id_Cliente_Externo)) +' '+ LTRIM(RTRIM(@Razon_Social))
							  SET @Id_Cliente = 0
							  SET @Id_Cta_Banco = 0
							  EXEC dbo.SP_CbteItem_Agr   @Id_Producto,@trans,1,@Imp_prod_siva,@fecha,'',@Razon_Social,@ID_Cliente,@Id_Cta_Banco
                     
							  FETCH NEXT FROM CUR_GENERAR_ITEMS INTO  @Razon_Social,@Imp_prod_siva,@Id_Cliente_Externo 	
						 END  
						 CLOSE CUR_GENERAR_ITEMS
					     DEALLOCATE CUR_GENERAR_ITEMS
                 END
			 	 IF @Porc_Comision_Prov > 0
				    BEGIN
					    SET @Razon_Social = (SELECT RAZON_SOCIAL FROM PROVEEDORES WHERE ID_PROVEEDOR = @Id_Proveedor)
				        SET @ID_TIPO_CBTE =  (select Valor_String from xParametros where setDatos= 1 and idParametro ='T_Cbte_Cred_Liq_Ter')
				        SET @IMPORTE_CREDITO = (@Importe * (@Porc_Comision_Prov/100)) * -1
			        	EXEC dbo.CP_Cbtes_Cpra_Generar @Id_Proveedor,@Razon_Social,@IMPORTE_CREDITO,1,@FECHA,@ID_TIPO_CBTE,'PRUEBA',1,10,100,@Trans OUTPUT
		 		    END

	      FETCH NEXT FROM CUR_GENERAR INTO  @Id_Producto,@Id_Proveedor,@Razon_Social,@Cuit,@Id_Iva,@Id_Alias_Cta_Cont,@Id_Cta_Contable_H,@Porc_Comision_Prov,@Id_Cta_Banco,@Importe
	 END  
	 CLOSE CUR_GENERAR
	 DEALLOCATE CUR_GENERAR 
  
  END

  insert into #Reporte
                        SELECT 0 as Imp_Gravado_Item                         --1
							  ,0 as Imp_Final_Item                           --2
							  ,0 as Id_Trans_Fac                             --3
							  ,0 as Importe_Fac                              --4
							  ,0 as Imp_total_Fac                            --5
							  ,r.Id_trans as Id_Trans_Rec                    --6
							  ,r.imp_total as Importe_Aplicado                  --7
							  ,r.Fecha  as Fecha_QA                          --8
							  ,r.Fecha  as Fecha_Venc                        --9
							  ,c.Id_cliente                                  --10
			  			      ,C.Nombre_Fantasia                             --11
							  ,C.Id_Cliente_Externo                          --12
							  ,C.Razon_Social                                --13
							  ,C.Id_Tipo_Cli                                 --14
							  ,'' as Desc_Factura                            --15
							  ,r.Fecha                                            --16
							  ,dbo.CF_Cbte_Descrip(R.id_trans) as Desc_Recibo     --17
							  ,R.Fecha as Fecha_Rec								  --18
							  ,R.Imp_Total as Imp_Total_Rec					      --19
							  ,R.Id_Estado_Cbte									  --20
							  ,R.Cotizacion as Cotizacion_Rec                     --21
							  ,0 as Cotizacion_Fac                                --22
							  ,0 as Porc_Bonificacion							  --23
							  ,r.Id_Cobrador								      --24
							  ,'' as Id_Producto								  --25
							  ,'PAGO A CUENTA' AS descripcion_Detallada		      --26
							  ,0 as Id_Familia									  --27
							  ,'' as Descripcion_Familia                          --28
							  ,0 as porc_aplicado                                 --29
							  ,r.saldo  as imp_prod_civa                          --30
							  ,r.saldo  as imp_prod_siva                          --31
							  ,V.DESCRIPCION AS NOMBRE_COBRADOR                   --32
							  ,ISNULL([dbo].[SF_Cli_Categ_Mes](r.Id_cliente, r.Fecha),0) as Tipo_Cli --33
							  ,CT.DESCRIPCION                                   --34
							  ,isnull(c.id_cliente_ref,0) as id_cliente_ref                                 --35
							  ,cast(0 as decimal(12,2)) AS EFECTIVO                                         --36
							  ,cast(0 as decimal(12,2)) AS TARJETA                                          --37
							  ,cast(0 as decimal(12,2)) AS CHEQ_TER                                         --38
							  ,cast(0 as decimal(12,2)) AS CHEQ_PROP                                        --39
							  ,cast(0 as decimal(12,2)) AS DEBITO                                           --40
							  ,cast(0 as decimal(12,2)) AS FINANC                                           --41
							  ,cast(0 as decimal(12,2)) AS OTROS                                            --42
							  ,cast(0 as decimal(12,2)) AS Total_Pagos                                      --43
							  ,cast(0 as decimal(12,2)) AS Dif                                              --44
							  ,1 as Item_Fac															    --45
							  ,cast(0 as decimal(12,5)) AS Coef_Pago										--46  
							  ,ISNULL(C.Id_Cond_Pago, 0) AS Id_Cond_Pago									--47 14/01/2020 Agregado Ticket 18.924
							  ,ISNULL(CCP.Descripcion, '''') AS Cond_Pago									--48 14/01/2020 Agregado Ticket 18.924
							  ,0 AS Imp_Total_Percep_Reten_Fac												--49 14/01/2020 Agregado Ticket 18.924
							  ,r.Imp_Percep AS Imp_Total_Percep_Reten_Rec									--50 14/01/2020 Agregado Ticket 18.924
							,''							AS FC_CL_Nombre_Fantasia							--51 27/01/2021
							,''							AS FC_CL_Id_Cliente_Externo							--52 27/01/2021
							,''							AS FC_CL_Razon_Social								--53 27/01/2021
							,0							AS FC_CL_Id_Tipo_Cli								--54 27/01/2021
							,C.Id_Cobrador				AS CL_Id_Cobrador									--55 04/02/2021
							,CP.Id_Caja					AS Id_Caja											--56 04/02/2021
							,0							AS Porc_Bonif_Item									--57 13/04/2021 Agregado Ticket 22.253
							,0							AS Imp_Final_Item_Sin_Desc							--58 13/04/2021 Agregado Ticket 22.253
							,0							AS Imp_Bonif_Item									--59 13/04/2021 Agregado Ticket 22.253
   FROM cbtes r, cbtes_tipos tr,  Clientes C, Vendedores V, Clientes_Tipos CT, Cbtes_Cond_Pago CCP, Cajas_Mov CM, Cajas_Periodos CP
   WHERE r.id_tipo_cbte = tr.id_tipo_cbte 
   and tr.Compromete_Recibos in (1,-1)
   AND C.ID_CLIENTE = R.ID_CLIENTE
   AND R.ID_ESTADO_CBTE IN (1,4,2)
  -- AND R.SALDO <> 0
   AND r.Id_Cobrador = v.id_vendedor
   AND CM.Id_Trans = R.Id_Trans
   AND CM.Id_Periodo_Caja = CP.Id_Periodo_Caja
   AND ISNULL(CT.ID_TIPO_CLI,0) = ISNULL([dbo].[SF_Cli_Categ_Mes](r.Id_cliente, r.Fecha),0)
   AND R.Fecha >= @pFechaDesde
   AND r.Fecha <  @pFechaHasta+1 
   AND ISNULL(C.Id_Cond_Pago, 0) = ISNULL(CCP.Id_Cond_Pago, 0)
   and r.id_Trans not in (select id_Trans from cbtes_items)

-------------------------------------------------------------------------------------------

   SET @SqlSelect =  ' SELECT (i.Imp_Gravado * F.Cotizacion) * (1 -(F.Porc_Bonificacion / 100)) * (TF.Compromete_Factura) as Imp_Gravado_Item            --1
							  ,(i.Imp_Final * F.Cotizacion) * (1 -(F.Porc_Bonificacion / 100))  * (TF.Compromete_Factura) as Imp_Final_Item               --2
							  ,f.Id_trans as Id_Trans_Fac                                   --3
							  ,(f.Imp_Gravado + f.Imp_Gravado2 + f.Imp_Gravado3 + f.Imp_Exento) * F.Cotizacion  * (TF.Compromete_Factura) as Importe_Fac --4
							  ,f.Imp_total * F.Cotizacion  * (TF.Compromete_Factura) as Imp_total_Fac   --5
							  ,0 as Id_Trans_Rec                                 --6
							  ,0  as Importe_Aplicado                            --7
							  ,i.Fecha_QA                                    --8
							  ,i.Fecha_Venc                                  --9
							  ,CASE
								WHEN i.Id_Cliente IS NULL THEN F.Id_Cliente  --10
								WHEN i.Id_Cliente = 0 THEN F.Id_Cliente
								ELSE i.Id_Cliente
								END AS Id_Cliente
							  ,C.Nombre_Fantasia                             --11
							  ,C.Id_Cliente_Externo                          --12
							  ,C.Razon_Social                                --13
							  ,C.Id_Tipo_Cli                                 --14
							  ,dbo.CF_Cbte_Descrip(f.id_trans) as Desc_Factura    --15
							  ,F.Fecha                                            --16
							  ,'''' as Desc_Recibo                                  --17
							  ,NULL  as Fecha_Rec							    	  --18
							  ,0 as Imp_Total_Rec					              --19
							  ,f.Id_Estado_Cbte									  --20
							  ,0 as Cotizacion_Rec                                --21
							  ,F.Cotizacion as Cotizacion_Fac                     --22
							  ,F.Porc_Bonificacion								  --23
							  ,F.Id_Cobrador								      --24
							  ,I.Id_Producto									  --25
							  ,P.Descripcion_Detallada						      --26
							  ,P.Id_Familia										  --27
							  ,FP.Descripcion as Descripcion_Familia              --28
							  ,0 as porc_aplicado                               --29
							  ,0 as imp_prod_civa --30
							  ,0 as imp_prod_siva --31
							  ,V.DESCRIPCION AS NOMBRE_COBRADOR                                               --32
							  ,[dbo].[SF_Cli_Categ_Mes](i.Id_cliente, isnull(i.Fecha_QA,F.Fecha)) as Tipo_Cli --33
							  ,CT.DESCRIPCION                                                                 --34
							  ,isnull(c.id_cliente_ref,0) as id_cliente_ref                                   --35
							  ,cast(0 as decimal(12,2)) AS EFECTIVO                                           --36
							  ,cast(0 as decimal(12,2)) AS TARJETA                                            --37
							  ,cast(0 as decimal(12,2)) AS CHEQ_TER                                           --38
							  ,cast(0 as decimal(12,2)) AS CHEQ_PROP                                          --39
							  ,cast(0 as decimal(12,2)) AS DEBITO                                             --40
							  ,cast(0 as decimal(12,2)) AS FINANC                                             --41
							  ,cast(0 as decimal(12,2)) AS OTROS                                              --42
							  ,cast(0 as decimal(12,2)) AS Total_Pagos                                        --43
							  ,cast(0 as decimal(12,2)) AS Dif                                                --44
							  ,i.Item as Item_Fac															  --45
							  ,cast(0 as decimal(12,5)) AS Coef_Pago										  --46 
							  ,0 AS Id_Cond_Pago										                    --47 14/01/2020 Agregado Ticket 18.924
							  ,ISNULL(CCP.Descripcion, '''') AS Cond_Pago									--48 14/01/2020 Agregado Ticket 18.924
							  ,F.IMP_PERCEP AS Imp_Total_Percep_Reten_Fac		  						    --49 14/01/2020 Agregado Ticket 18.924
							  ,0 AS Imp_Total_Percep_Reten_Rec										        --50 14/01/2020 Agregado Ticket 18.924
							  ,CLFC.Nombre_Fantasia		AS FC_CL_Nombre_Fantasia							--51 27/01/2021
							  ,CLFC.Id_Cliente_Externo	AS FC_CL_Id_Cliente_Externo							--52 27/01/2021
							  ,CLFC.Razon_Social		AS FC_CL_Razon_Social								--53 27/01/2021
							  ,CLFC.Id_Tipo_Cli			AS FC_CL_Id_Tipo_Cli								--54 27/01/2021
							  ,C.Id_Cobrador			AS CL_Id_Cobrador									--55 04/02/2021
							  ,0						AS Id_Caja											--56 04/02/2021
							  ,I.Bonif					AS Porc_Bonif_Item									--57 13/04/2021 Agregado Ticket 22.253
							  ,((100 * I.Imp_Final) / (100-I.Bonif)) AS Imp_Final_Item_Sin_Desc				--58 13/04/2021 Agregado Ticket 22.253
							  ,(((100 * I.Imp_Final) / (100-I.Bonif)) * (I.Bonif / 100)) AS Imp_Bonif_Item	--59 13/04/2021 Agregado Ticket 22.253
							  '
  SET @SqlWhere = 'WHERE  
					f.id_cliente = c.id_Cliente
					AND ISNULL(F.Id_Cliente, 0) = CLFC.Id_Cliente
					AND f.id_estado_cbte in (1,2,4) 
					AND i.id_trans = f.id_trans 
					AND f.id_tipo_cbte = TF.id_tipo_cbte 
					AND I.Id_Producto = P.Id_Producto
					AND ISNULL(P.Id_Familia,0) = ISNULL(FP.Id_Familia,0)
					AND f.Fecha >= ''' + CONVERT(VARCHAR(8),@pFechaDesde   ,112) + '''
					AND f.Fecha <  ''' + CONVERT(VARCHAR(8),@pFechaHasta+1 ,112) + '''
					AND F.Imp_total <> 0
					AND ISNULL(F.Id_Cond_Pago, 0) = ISNULL(CCP.Id_Cond_Pago, 0)
					AND TF.Compromete_Factura in (1,-1)
					AND ISNULL(F.Id_Cobrador,'''') = ISNULL(V.Id_Vendedor,'''')
 					AND ISNULL(CT.ID_TIPO_CLI,0) = ISNULL([dbo].[SF_Cli_Categ_Mes](i.Id_cliente, isnull(i.Fecha_QA,F.Fecha)),0)
					AND i.Imp_Gravado <> 0 '

  
  IF @EXISTE_TAG > 0
  BEGIN
	  SET @SqlFrom = 'FROM cbtes_items i,cbtes f, Cbtes_Tipos TF, Clientes C,TagFilePos_ TAG, Productos P,Prod_Familias FP, Vendedores V, Clientes_Tipos CT, Clientes CLFC, Cbtes_Cond_Pago CCP'
      SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND (i.id_producto = TAG.POS 
							      AND TAG.TBL = ' + CAST(@pEquate  AS VARCHAR(10))  + '
								  AND TAG.USR = ' + CAST(@pUsuario AS VARCHAR(10)) + '
								 ) ' 
  END
  ELSE
  BEGIN
	  SET @SqlFrom = 'FROM cbtes_items i,cbtes f, Cbtes_Tipos TF, Clientes C, Productos P,Prod_Familias FP, Vendedores V, Clientes_Tipos CT, Clientes CLFC, Cbtes_Cond_Pago CCP'
  END


  SET @Sql = @SqlSelect + ' ' + @SqlInto +' '+ @SqlFrom + ' ' + @SqlWhere 
  --print @Sql
  EXEC('INSERT INTO #Reporte ' + @sql)

 ---AGREGO TICKET / VENTAS DE CONTADO
 -------------------------------------------------------------------------------------------

   SET @SqlSelect =  ' SELECT (i.Imp_Gravado * F.Cotizacion) * (1 -(F.Porc_Bonificacion / 100)) * (TF.Compromete_Factura) as Imp_Gravado_Item            --1
							  ,(i.Imp_Final * F.Cotizacion) * (1 -(F.Porc_Bonificacion / 100))  * (TF.Compromete_Factura) as Imp_Final_Item               --2
							  ,f.Id_trans as Id_Trans_Fac                                                    --3
							  ,(f.Imp_Gravado + f.Imp_Gravado2 + f.Imp_Gravado3 + f.Imp_Exento) * F.Cotizacion   * (TF.Compromete_Factura) as Importe_Fac --4
							  ,f.Imp_total * F.Cotizacion  * (TF.Compromete_Factura) as Imp_total_Fac         --5
							  ,f.Id_trans  as Id_Trans_Rec                                                    --6
							  ,f.Imp_total * F.Cotizacion  * (TF.Compromete_Factura)  as Importe_Aplicado     --7
							  ,i.Fecha_QA                                    --8
							  ,i.Fecha_Venc                                  --9
							  ,CASE
								WHEN i.Id_Cliente IS NULL THEN F.Id_Cliente  --10
								WHEN i.Id_Cliente = 0 THEN F.Id_Cliente
								ELSE i.Id_Cliente
								END AS Id_Cliente
							  ,C.Nombre_Fantasia                             --11
							  ,C.Id_Cliente_Externo                          --12
							  ,C.Razon_Social                                --13
							  ,C.Id_Tipo_Cli                                 --14
							  ,dbo.CF_Cbte_Descrip(f.id_trans) as Desc_Factura    --15
							  ,F.Fecha                                            --16
							  ,''TICKET CONTADO'' as Desc_Recibo                  --17
							  ,F.Fecha  as Fecha_Rec						      --18
							  ,f.Imp_total * F.Cotizacion  * (TF.Compromete_Factura) as Imp_Total_Rec	 --19
							  ,f.Id_Estado_Cbte									  --20
							  ,F.Cotizacion as Cotizacion_Rec                     --21
							  ,F.Cotizacion as Cotizacion_Fac                     --22
							  ,F.Porc_Bonificacion								  --23
							  ,F.Id_Cobrador								      --24
							  ,I.Id_Producto									  --25
							  ,P.Descripcion_Detallada						      --26
							  ,P.Id_Familia										  --27
							  ,FP.Descripcion as Descripcion_Familia              --28
							  ,100 as porc_aplicado                               --29
							  ,(i.Imp_Final *  F.Cotizacion )  * (1 -(F.Porc_Bonificacion / 100)) as imp_prod_civa --30
							  ,(i.Imp_Gravado * F.Cotizacion ) * (1 -(F.Porc_Bonificacion / 100)) as imp_prod_siva --31
							  ,V.DESCRIPCION AS NOMBRE_COBRADOR                                               --32
							  ,[dbo].[SF_Cli_Categ_Mes](i.Id_cliente, isnull(i.Fecha_QA,F.Fecha)) as Tipo_Cli --33
							  ,CT.DESCRIPCION                                                                 --34
							  ,isnull(c.id_cliente_ref,0) as id_cliente_ref                                   --35
							  ,cast(0 as decimal(12,2)) AS EFECTIVO                                           --36
							  ,cast(0 as decimal(12,2)) AS TARJETA                                            --37
							  ,cast(0 as decimal(12,2)) AS CHEQ_TER                                           --38
							  ,cast(0 as decimal(12,2)) AS CHEQ_PROP                                          --39
							  ,cast(0 as decimal(12,2)) AS DEBITO                                             --40
							  ,cast(0 as decimal(12,2)) AS FINANC                                             --41
							  ,cast(0 as decimal(12,2)) AS OTROS                                              --42
							  ,cast(0 as decimal(12,2)) AS Total_Pagos                                        --43
							  ,cast(0 as decimal(12,2)) AS Dif                                                --44
							  ,i.Item as Item_Fac															  --45
							  ,cast(0 as decimal(12,5)) AS Coef_Pago										  --46 
							  ,F.Id_Cond_Pago AS Id_Cond_Pago										          --47 14/01/2020 Agregado Ticket 18.924
							  ,ISNULL(CCP.Descripcion, '''') AS Cond_Pago									  --48 14/01/2020 Agregado Ticket 18.924
							  ,F.IMP_PERCEP AS Imp_Total_Percep_Reten_Fac		  						      --49 14/01/2020 Agregado Ticket 18.924
							  ,0 AS Imp_Total_Percep_Reten_Rec										          --50 14/01/2020 Agregado Ticket 18.924
							  ,CLFC.Nombre_Fantasia		AS FC_CL_Nombre_Fantasia							  --51 27/01/2021
							  ,CLFC.Id_Cliente_Externo	AS FC_CL_Id_Cliente_Externo							  --52 27/01/2021
							  ,CLFC.Razon_Social		AS FC_CL_Razon_Social								  --53 27/01/2021
							  ,CLFC.Id_Tipo_Cli			AS FC_CL_Id_Tipo_Cli								  --54 27/01/2021
							  ,C.Id_Cobrador			AS CL_Id_Cobrador								      --55 04/02/2021
							  ,0						AS Id_Caja											  --56 04/02/2021
							  ,I.Bonif					AS Porc_Bonif_Item									  --57 13/04/2021 Agregado Ticket 22.253
							  ,((100 * I.Imp_Final) / (100-I.Bonif)) AS Imp_Final_Item_Sin_Desc				  --58 13/04/2021 Agregado Ticket 22.253
							  ,(((100 * I.Imp_Final) / (100-I.Bonif)) * (I.Bonif / 100)) AS Imp_Bonif_Item	  --59 13/04/2021 Agregado Ticket 22.253
							  '
  SET @SqlWhere = 'WHERE  f.id_cliente = c.id_Cliente
							AND ISNULL(F.Id_Cliente, 0) = CLFC.Id_Cliente
							AND f.id_estado_cbte in (1,2,4) 
							AND i.id_trans = f.id_trans 
							AND f.id_tipo_cbte = TF.id_tipo_cbte 
							AND I.Id_Producto = P.Id_Producto
							AND ISNULL(P.Id_Familia,0) = ISNULL(FP.Id_Familia,0)
							AND f.Fecha >= ''' + CONVERT(VARCHAR(8),@pFechaDesde   ,112) + '''
							AND f.Fecha <  ''' + CONVERT(VARCHAR(8),@pFechaHasta+1 ,112) + '''
							AND F.Imp_total <> 0
							AND ISNULL(F.Id_Cond_Pago, 0) = ISNULL(CCP.Id_Cond_Pago, 0)
							AND TF.Compromete_Factura in (1,-1)
							AND F.ID_COND_PAGO = 1 
							AND ISNULL(F.Id_Cobrador,'''') = ISNULL(V.Id_Vendedor,'''')
 							AND ISNULL(CT.ID_TIPO_CLI,0) = ISNULL([dbo].[SF_Cli_Categ_Mes](i.Id_cliente, isnull(i.Fecha_QA,F.Fecha)),0)
							AND i.Imp_Gravado <> 0 '

  
  IF @EXISTE_TAG > 0
  BEGIN
	  SET @SqlFrom = 'FROM cbtes_items i,cbtes f, Cbtes_Tipos TF, Clientes C,TagFilePos_ TAG, Productos P,Prod_Familias FP, Vendedores V, Clientes_Tipos CT, Clientes CLFC, Cbtes_Cond_Pago CCP'
      SET @SqlWhere = RTRIM(LTRIM(@SqlWhere)) + ' AND (i.id_producto = TAG.POS 
							      AND TAG.TBL = ' + CAST(@pEquate  AS VARCHAR(10))  + '
								  AND TAG.USR = ' + CAST(@pUsuario AS VARCHAR(10)) + '
								 ) ' 
  END
  ELSE
  BEGIN
	  SET @SqlFrom = 'FROM cbtes_items i,cbtes f, Cbtes_Tipos TF, Clientes C, Productos P,Prod_Familias FP, Vendedores V, Clientes_Tipos CT, Clientes CLFC, Cbtes_Cond_Pago CCP'
  END


  SET @Sql = @SqlSelect + ' ' + @SqlInto +' '+ @SqlFrom + ' ' + @SqlWhere 
  --print @Sql
  EXEC('INSERT INTO #Reporte ' + @sql)

