CREATE PROCEDURE [dbo].[CP_Productos_xCampos_Copiar] (@pId_Producto_Origen VARCHAR(14), @pId_Producto_Destino VARCHAR(14))
AS
DECLARE @Mensaje		VARCHAR(100)
DECLARE @Id_Campo		INT
DECLARE @Valor_String	VARCHAR(101)
DECLARE @Valor_Integer	INT
DECLARE @Valor_DT		DATETIME
DECLARE @Valor_Decimal	DECIMAL(20,4)
DECLARE @Valor_Memo		VARCHAR(MAX)

BEGIN TRY
	BEGIN TRAN


	DECLARE curProdXCampCopiar CURSOR FOR 
	SELECT Id_Campo, Valor_String, Valor_Integer, Valor_DT, Valor_Decimal, Valor_Memo 
	FROM Productos_xCampos
	WHERE
	Id_Producto = @pId_Producto_Origen

	OPEN curProdXCampCopiar
	FETCH NEXT FROM curProdXCampCopiar INTO @Id_Campo, @Valor_String, @Valor_Integer, @Valor_DT, @Valor_Decimal, @Valor_Memo
	WHILE @@FETCH_STATUS = 0
	BEGIN

		IF NOT EXISTS(SELECT 1 FROM Productos_xCampos WHERE Id_Producto = @pId_Producto_Destino AND Id_Campo = @Id_Campo)
		BEGIN
			INSERT INTO Productos_xCampos 
			(Id_Producto,			Id_Campo,	Valor_String,
			Valor_Integer,			Valor_DT,	Valor_Decimal,
			Valor_Memo) 
			VALUES 
			(@pId_Producto_Destino,	@Id_Campo,	@Valor_String,
			@Valor_Integer,			@Valor_DT,	@Valor_Decimal,
			@Valor_Memo) 
		END
		ELSE
		BEGIN
			UPDATE Productos_xCampos 
			SET 
			Valor_String	= @Valor_String, 
			Valor_Integer	= @Valor_Integer, 
			Valor_DT		= @Valor_DT, 
			Valor_Decimal	= @Valor_Decimal,
			Valor_Memo		= @Valor_Memo
			WHERE 
			Id_Producto = @pId_Producto_Destino 
			AND Id_Campo = @Id_Campo
		END
		
		FETCH NEXT FROM curProdXCampCopiar INTO @Id_Campo, @Valor_String, @Valor_Integer, @Valor_DT, @Valor_Decimal, @Valor_Memo
	END 
	CLOSE curProdXCampCopiar
	DEALLOCATE curProdXCampCopiar

	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage
			,@pId_Producto_Destino	AS Id_Producto_Destino

	END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO


Create PROCEDURE [dbo].[CP_Recalcular_Stock_Disponible] 

AS
BEGIN
 
        select id_producto,
                          Stk_Fisico,
                          Stk_Disponible,
						  Stk_Pedidos,
						  Stk_Ordenes,
						  Stk_Reserva,
						  Stk_Cuarentena,
						  Stk_Lineas,
						  Stk_Rechazado,
						  STk_Externo
						  into #Stock from productos where id_producto = ''

         delete #Stock
		   
  Declare @id_Producto char(14)
  Declare @Stock Decimal(17,4)
  Declare @existe SmallInt

--Calculo Stk_Fisico
  Declare Cursor_RecStock Cursor for

		SELECT I.ID_PRODUCTO,SUM(isnull(I.Cantidad,0)*T.Compromete_Stock) as Stock  FROM Cbtes_Items I,Cbtes C,Cbtes_Tipos T  
		WHERE I.Id_Trans = C.Id_Trans  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND C.Id_Estado_Cbte <> 3 
		AND I.Id_Estado_Cbte <> 32 
		AND T.Compromete_Stock in (1,-1) 
		AND isnull(i.id_producto,'') <> ''  
		AND (I.Fecha_QA < getdate()+1  OR  I.Fecha_QA IS NULL ) 
		AND I.Flag_QA = 'A' GROUP BY I.ID_PRODUCTO  having SUM(I.Cantidad*T.Compromete_Stock) <> 0
	
	OPEN Cursor_RecStock

	FETCH NEXT FROM Cursor_RecStock
	INTO @Id_Producto,@Stock

	WHILE @@FETCH_STATUS = 0
	BEGIN
	    set @existe = (Select count(*) from #Stock where id_producto = @Id_Producto)

    	if @existe <> 0
	        	begin
				  update #Stock set stk_Fisico = isnull(@Stock,0) where  Id_producto = @Id_Producto 
				end
			  Else
				Begin
				  insert into #stock (Id_Producto,stk_Fisico) values (@id_Producto,isnull(@Stock,0))
                End

	 	FETCH NEXT FROM Cursor_RecStock
		INTO @Id_Producto, @Stock
	END

	CLOSE Cursor_RecStock
	DEALLOCATE Cursor_RecStock



--Calculo Stk_Pendiente
  Declare Cursor_RecStock Cursor for

		SELECT I.ID_PRODUCTO,SUM(isnull(I.Cantidad,0)*T.Compromete_Stock_Res)  as Stock FROM Cbtes_Items I,Cbtes C,Cbtes_Tipos T  
		WHERE I.Id_Trans = C.Id_Trans  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND C.Id_Estado_Cbte <> 3 
		AND I.Id_Estado_Cbte <> 32 
		AND T.Compromete_Stock_Res in (1,-1) 
	    AND isnull(i.id_producto,'') <> ''  
		AND (I.Fecha_QA < getdate()+1  OR  I.Fecha_QA IS NULL ) 
		AND I.Flag_QA = 'A' GROUP BY I.ID_PRODUCTO having SUM(I.Cantidad*T.Compromete_Stock) > 0
	
	OPEN Cursor_RecStock

	FETCH NEXT FROM Cursor_RecStock
	INTO @Id_Producto,@Stock

	WHILE @@FETCH_STATUS = 0
	BEGIN
	    set @existe = (Select count(*) from #Stock where id_producto = @Id_Producto)

    	if @existe <> 0
	        	begin
				  update #Stock set Stk_Pedidos = isnull(@Stock,0) where  Id_producto = @Id_Producto 
				end
			  Else
				Begin
				  insert into #stock (Id_Producto,Stk_Pedidos) values (@id_Producto,isnull(@Stock,0))
                End

	 	FETCH NEXT FROM Cursor_RecStock
		INTO @Id_Producto, @Stock
	END

	CLOSE Cursor_RecStock
	DEALLOCATE Cursor_RecStock




 update productos set Stk_fisico = 0,Stk_Disponible = 0,Stk_Pedidos = 0 

 update productos set Stk_fisico = isnull(S.Stk_fisico,0),Stk_Pedidos = isnull(S.Stk_Pedidos,0), Stk_Disponible = isnull(S.Stk_fisico,0) - isnull(S.Stk_Pedidos,0) 
        from productos p, #stock S where p.id_producto = s.Id_Producto

  drop table #Stock

  END
GO

CREATE PROCEDURE [dbo].[CP_Recibo_Egreso_Banking]   @Id_Cliente INT,
                                                    @Id_Producto CHAR(14) , 
													@Id_Tipo_Cbte Varchar(5),
													@Importe Decimal(12,2),
													@Id_Trans INT,
													@lote Varchar(20),
													@Id_Cta_Banco INT
AS

/*Variables */
DECLARE @Id_Trans_New       INT;
DECLARE @fecha 				DATETIME;
DECLARE @Comprobante_nro 	INT;
DECLARE @id_sucursal 		SMALLINT;
DECLARE @id_iva 			CHAR(3);
DECLARE @cuit 				VARCHAR(19);
DECLARE @id_moneda 			CHAR(3);
DECLARE @Id_Familia         INT;
DECLARE @descripcion		CHAR(100);
DECLARE @id_cond_pago		SMALLINT;		
DECLARE @id_localidad 		SMALLINT;
DECLARE @id_provincia 		CHAR(3);
DECLARE @Destinatario		VARCHAR(100);
DECLARE @imp_neto 			DECIMAL(12,2);
DECLARE @imp_gravado 		DECIMAL(12,2);
DECLARE @imp_exento 		DECIMAL(12,2);
DECLARE @imp_iva 			DECIMAL(12,2);
DECLARE @imp_iva2 			DECIMAL(12,2);
DECLARE @imp_iva3 			DECIMAL(12,2);
DECLARE @imp_percepcion_iva DECIMAL(12,2);
DECLARE @imp_percepcion_IB 	DECIMAL(12,2);
DECLARE @imp_percep 		DECIMAL(12,2);
DECLARE @imp_total  		DECIMAL(12,2);
DECLARE @Id_Cond_Vta	    CHAR(10);	
DECLARE @Obs				VARCHAR(5000);
DECLARE @Descripcion_Producto VARCHAR(100);
DECLARE @cant				INT,@id_lista SMALLINT;
DECLARE @Email				VARCHAR(2000)
DECLARE @Fecha_Venc			DATE , @Fecha_QA DATE;
DECLARE @Id_Cliente_Cbte	INT
DECLARE @Id_Acti_Cbte		CHAR(14)
DECLARE @Mensaje			VARCHAR(100)

/*FIN Variables */


BEGIN TRY
--BEGIN TRAN

BEGIN
  
    Select * into #Nuevo from Cbtes where id_trans = @id_trans

    SET @fecha = (SELECT FECHA FROM CBTES WHERE id_trans = @id_trans)
 


    /*Busco proxima transacci¾n y agrego registro */
	SET @Id_Trans_New = (SELECT (MAX(Id_trans)+1) FROM Transacciones)

	INSERT INTO Transacciones
	(Id_Trans, Descripcion, Fecha_Mov,
	Id_Usuario)
	VALUES
	(@Id_Trans_New, @descripcion, @fecha,
	0/*Usuario*/)
	/*FIN Inserto Tabla: Transacciones*/

	/*Configuro otras Variables*/

	SET @Descripcion_Producto = (SELECT RTRIM(Descripcion_Resumida) FROM Productos WHERE Id_Producto=@Id_Producto)

	SET @Descripcion_Producto =   RTRIM(@Descripcion_Producto) + '  ' + (SELECT RTRIM(ID_TIPO_CBTE)  +' Nro: '+ RTRIM(Comprobante_Nro) FROM CBTES WHERE ID_TRANS = @ID_TRANS)
 
	SET @cuit = (SELECT cuit FROM clientes WHERE id_cliente=@id_cliente);
	SET @imp_total = @Importe;
	SET @Cant = 1;
	SET @imp_gravado = @imp_total;
	SET @imp_exento = 0;
	SET @imp_iva = 0;
	SET @imp_iva2 = 0;
	SET @imp_iva3 = 0;
	SET @imp_percepcion_iva = 0;
	SET @imp_percepcion_IB = 0;
	SET @imp_percep = 0;
	SET @Obs = ''
	SET @lote = ''

	/*FIN Configuro otras Variables*/

	/*MODIFICAR_E COMIENZO INSERTAR*/
	
	/*Inserto Tabla: CBTES*/
	Update #Nuevo set Id_trans        = @Id_Trans_New, 
	                  id_tipo_cbte    = @Id_tipo_Cbte, 
             	      Imp_Gravado     = ABS(@Importe),
					  Imp_Total       = ABS(@Importe),
					  Id_Moneda       = 'PES',
					  Cotizacion      = 1,
					  Saldo           = 0,
					  Porc_Iva        = 0,
					  Porc_Iva2       = 0,
					  Porc_Iva3       = 0,
					  Saldo_Iva_Recup = 0,
					  Id_Estado_Cbte  = 2
         

	INSERT INTO Cbtes
	       SELECT * FROM #Nuevo
    set @imp_total = @imp_total*-1
	INSERT INTO Cbtes_Items	(id_cliente,		descripcion_producto,		Cantidad,
							id_estado_Cbte,		Cantidad_Saldo,				Id_Trans,
							item,				Precio_Grav,				Imp_Gravado,
							Imp_Final,			Precio,						Lote,
							Fecha_QA,			Flag_QA,					Id_Producto,
							Fecha_Venc,         Id_Cta_Banco )
	VALUES					(@id_cliente,		RTRIM(@Descripcion_Producto),@Cant,
							2,	                @Cant,	            		@id_trans_New,
							1,					@imp_total,					@imp_total,
							@imp_total,	    	@imp_total,					@Lote,
							@fecha,				'A',			     		@Id_Producto,
							@fecha,             @Id_Cta_Banco)

    SET @Mensaje = 'Trans. Agregada ' + CAST(@Id_Trans as VARCHAR(14))

    /*Inserto Tabla: CBTES_APLICA */
	    Select * into #Nuevo_APLICA from Cbtes_APLICA where id_trans_D = @id_trans AND ITEM = 1

		UPDATE #Nuevo_APLICA SET Id_trans = @id_trans_New, ITEM = 2

		INSERT INTO CBTES_APLICA 
		       SELECT * FROM #Nuevo_APLICA

        
		DROP TABLE #Nuevo_APLICA
        DROP TABLE #Nuevo
END

--COMMIT

SELECT 0,0,0,0,0,@Mensaje

END TRY  
BEGIN CATCH  
    -- Execute error retrieval routine.  
    EXECUTE usp_GetErrorInfo;  
--	ROLLBACK
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_Reserva_Producto]	@pId_Producto VARCHAR(14)
AS
SET NOCOUNT ON

/*Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100)
DECLARE @Reservado			INT
DECLARE @Fecha_Reserva		DATETIME
DECLARE @cant_min_reserva	INT

--ACTUALIZACIONES
--21/03/2022: Se cambia DATEADD(MINUTE, -1, GETDATE() por DATEADD(MINUTE, (-1) * @cant_min_reserva, GETDATE()


--Se utiliza para cuando una persona hace clic sobre un producto(asiento) se bloquee el producto durante el tiempo que esta definido en el parametro cant_min_reserva

--1: Esta reservado (Nadie mas lo puede reservar)
--0: No estaba reservado y lo reserva

SET @cant_min_reserva = CONVERT(INT, dbo.CF_xParam('cant_min_reserva'))

SET @Fecha_Reserva =  (SELECT ISNULL(Fecha_Reserva,'19900101') FROM Productos WHERE Id_Producto = @pId_Producto)

IF(@Fecha_Reserva >= DATEADD(MINUTE, (-1) * @cant_min_reserva, GETDATE()))
BEGIN 
	SET @Reservado = 1
END 
ELSE
BEGIN
	UPDATE Productos 
	SET Fecha_Reserva = GETDATE()  
	WHERE 
	Id_Producto=@pId_Producto

	SET @Reservado = 0
END

SELECT @Reservado AS 'Reservado'
GO


CREATE PROCEDURE [dbo].[CP_ResumenCta_por_Cliente]
	@pFecha_Desde			DATETIME,
	@pFecha_Hasta			DATETIME,
	@pId_Unid_Negocio       varchar(10)
AS
SET NOCOUNT ON

/*Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@Id_Cliente		INT
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Trans_Rec		INT
		,@CursorOpen        INT
		,@Flag_Cbte_Tipo	SMALLINT
		,@Periodo           DATE 
		,@Id_sucursal	    SMALLINT
		,@Existe      	    SMALLINT
		,@Venta_Total       DECIMAL(16,2)

					
BEGIN 
     

		select c.Id_Cliente, c.Razon_Social, CAST(sum(isnull(f.Imp_Total,0) * f.cotizacion * isnull(T.Compromete_Factura,0)) - sum(isnull(f.Imp_Total,0) * f.cotizacion * isnull(T.Compromete_Recibos,0)) AS DECIMAL(14,2)) AS Saldo
		into #Resumen_Cta
		 from Cbtes_Tipos T, clientes c, cbtes F
		 where c.id_cliente = f.id_cliente
		and f.id_tipo_cbte = t.id_tipo_cbte
		and (f.Id_Cond_Pago <> 1 and t.Compromete_Factura in (1,-1) 
			  or t.Compromete_recibos in (1,-1))
		and f.id_estado_cbte not in (0,3)
		AND F.FECHA < dateadd(dd,1,@pFecha_Hasta)
		group by c.id_cliente, c.razon_social 


		alter table #Resumen_Cta add Sdo_Ant decimal(16,2),Debe decimal(16,2), Haber decimal(16,2)

		update #Resumen_Cta set Debe=0,Haber=0,Sdo_Ant=0

		select c.Id_Cliente, CAST(sum(isnull(f.Imp_Total,0) * f.cotizacion * isnull(T.Compromete_Factura,0)) - sum(isnull(f.Imp_Total,0) * f.cotizacion * isnull(T.Compromete_Recibos,0)) AS DECIMAL(14,2)) AS Sdo_Ant
		into #Resumen_Sdo_Ant
		 from Cbtes_Tipos T, clientes c, cbtes F
		 where c.id_cliente = f.id_cliente
		and f.id_tipo_cbte = t.id_tipo_cbte
		and (f.Id_Cond_Pago <> 1 and t.Compromete_Factura in (1,-1) 
			  or t.Compromete_recibos in (1,-1))
		and f.id_estado_cbte not in (0,3)
		AND F.FECHA < @pFecha_Desde 
		group by c.id_cliente 


		select f.id_cliente,(sum(isnull(f.Imp_Total,0) * f.cotizacion * isnull(T.Compromete_Factura,0))) as debe
		 into #Resumen_Debe
		 from Cbtes_Tipos T, cbtes F, #Resumen_Cta R
		 where r.id_cliente = f.id_cliente
		and f.id_tipo_cbte = t.id_tipo_cbte
		and f.Id_Cond_Pago <> 1 and t.Compromete_Factura in (1) 
		and f.id_estado_cbte not in (0,3)
	    AND F.FECHA >= @pFecha_Desde 
		AND F.FECHA < dateadd(dd,1,@pFecha_Hasta)
		group by f.id_cliente

		select f.id_cliente,(sum(isnull(f.Imp_Total,0) * f.cotizacion * isnull(T.Compromete_Factura,0))) as Haber
		 into #Resumen_Haber
		 from Cbtes_Tipos T, cbtes F, #Resumen_Cta R
		 where r.id_cliente = f.id_cliente
		and f.id_tipo_cbte = t.id_tipo_cbte
		and f.Id_Cond_Pago <> 1 and t.Compromete_Factura in (-1) 
		and f.id_estado_cbte not in (0,3)
		AND F.FECHA >= @pFecha_Desde 
		AND F.FECHA < dateadd(dd,1,@pFecha_Hasta)
		group by f.id_cliente
 
		Select F.Id_Cliente, sum(isnull(f.Imp_Total,0) * f.cotizacion * isnull(T.Compromete_Recibos,0)) as Recibos
		 into #Resumen_Rec
		 from Cbtes_Tipos T, cbtes F, #Resumen_Cta R
		 where r.id_cliente = f.id_cliente
		and f.id_tipo_cbte = t.id_tipo_cbte
		and t.Compromete_Recibos in (1,-1) 
		and f.id_estado_cbte not in (0,3)
		AND F.FECHA >= @pFecha_Desde 
		AND F.FECHA < dateadd(dd,1,@pFecha_Hasta)
		group by f.id_cliente

		update #Resumen_Cta set Debe = D.Debe
		from #Resumen_Cta C,#Resumen_Debe D 
		Where C.Id_Cliente = D.Id_Cliente

		update #Resumen_Cta set  Haber = (H.Haber*-1) 
		from #Resumen_Cta C, #Resumen_Haber H
		Where C.Id_Cliente = H.Id_Cliente

		update #Resumen_Cta set  Haber = Haber + R.Recibos
		from #Resumen_Cta C, #Resumen_Rec R
		Where C.Id_Cliente = R.Id_Cliente

		update #Resumen_Cta set  Sdo_Ant = S.Sdo_Ant
		from #Resumen_Cta C, #Resumen_Sdo_Ant S
		Where C.Id_Cliente = S.Id_Cliente


		select * from #Resumen_Cta

		drop table #Resumen_Cta

		drop table #Resumen_DEBE

        drop table #Resumen_HABER

        drop table #Resumen_REC

END

---[CP_ResumenCta_por_Cliente] '20200801','20210930',''
GO


CREATE PROCEDURE dbo.CP_SCA_Clientes_Huellas @pId_Cliente	INT
