CREATE PROCEDURE [dbo].[CP_SCA_ValidarFoto]	@pId_Cliente		INT, 
											@pId_Acceso			SMALLINT, 
											@pFecha				DATETIME, 
											@pTipoAcceso		CHAR(1), 
											@pFechaEvento		DATETIME,
											@Flag_ValidarFoto_Rta TINYINT OUTPUT
AS
BEGIN
DECLARE @Flag_Foto_Validar	TINYINT
DECLARE @Flag_Guarda_Base	TINYINT
DECLARE @Cli_Foto_Dir		VARCHAR(255)
DECLARE @Ruta_Foto			VARCHAR(255)

SET @Flag_Foto_Validar  = ISNULL((SELECT ISNULL(Flag_Foto_Validar, 0) FROM CD_Accesos WHERE Id_Acceso = @pId_Acceso), 0)
SET @Flag_Guarda_Base	= ISNULL(dbo.CF_xParam('Cli_Fotos_Base'), 0)

IF(@Flag_Foto_Validar = 1)
BEGIN
	IF(@Flag_Guarda_Base = 1)
	BEGIN
		/*Verifica si existe la foto en la base de datos*/
		SET @Flag_ValidarFoto_Rta = ISNULL((SELECT 1 FROM Clientes_Fotos WHERE Id_Cliente = @pId_Cliente), 0)
		
		RETURN ISNULL(@Flag_ValidarFoto_Rta, 0)
	END
	ELSE
	BEGIN
		/*Verificar si existe el archivo*/
		SET @Cli_Foto_Dir		= ISNULL(dbo.CF_xParam('Cli_Fotos_Dir'), '')
		SET @Ruta_Foto			= ISNULL((SELECT ISNULL(Foto, '') FROM Clientes WHERE Id_Cliente = @pId_Cliente), '')
		
		IF(@Ruta_Foto <> '')
		BEGIN
			CREATE TABLE #Archivos_Fotos
			(Nombre_Archivo VARCHAR(255),
			Profundidad SMALLINT,
			Flag_Es_Archivo SMALLINT)
		
			INSERT INTO #Archivos_Fotos
			EXEC xp_dirtree @Cli_Foto_Dir, 1, 1
			
			SET @Flag_ValidarFoto_Rta = ISNULL((SELECT MAX(1) FROM #Archivos_Fotos WHERE (@Cli_Foto_Dir + '\' + Nombre_Archivo) = @Ruta_Foto), 0)
		
			DROP TABLE #Archivos_Fotos
		END
		ELSE
		BEGIN
			SET @Flag_ValidarFoto_Rta = 0
		END
		
		RETURN ISNULL(@Flag_ValidarFoto_Rta, 0)
				
	END		
END

RETURN ISNULL(@Flag_ValidarFoto_Rta, 1)

END
GO


CREATE PROCEDURE [dbo].[CP_SCA_ValidarProducVta] @pId_Cliente		INT, 
												@pId_Acceso			SMALLINT, 
												@pFecha				DATETIME, 
												@pId_Cliente_Ref	INT, 
												@pHorario			TINYINT, 
												@Id_Producto		VARCHAR(14) OUTPUT
AS
BEGIN
DECLARE @Flag_PermiteProdPorPed	INT
DECLARE @Est_Pedido_Habili		VARCHAR(8000)
DECLARE @SqlStr					NVARCHAR(MAX)
DECLARE @SqlStrWhereEsp			NVARCHAR(MAX)
DECLARE @SqlStrSelect			NVARCHAR(MAX)
DECLARE @SqlStrWhere			NVARCHAR(MAX)
DECLARE @Parametros				NVARCHAR(100)
DECLARE @DiaActual				TINYINT

PRINT 'Parametros: '
PRINT '@pId_Cliente: ' + CAST(@pId_Cliente_Ref AS VARCHAR(10))
PRINT '@pId_Acceso: ' + CAST(@pId_Acceso AS VARCHAR(10))
PRINT '@pFecha: ' + CONVERT(VARCHAR(25),CAST(@pFecha AS DATE))
PRINT '@pId_Cliente_Ref: ' + CAST(@pId_Cliente_Ref AS VARCHAR(10))
PRINT '@pHorario: ' + CAST(@pHorario AS VARCHAR(10))
PRINT '@Id_Producto: ' + @Id_Producto


--[CD_ACCESOS_HORARIOS].[Dia] = 0 -> Domingo ,1->Lunes ....
SET @DiaActual = DATEPART(DW,@pFecha)
IF (@@DATEFIRST = 7)
BEGIN
   SET @DiaActual = @DiaActual - 1
END

IF (@DiaActual = 7) 
BEGIN
	SET @DiaActual = 0
END

SET @Parametros = N'@Id_ProductoOUT VARCHAR(14) OUTPUT'; 

SET @Id_Producto	= ''

SET @Flag_PermiteProdPorPed = (dbo.CF_xParam('SCA_Perm_ProdXPed'))
SET @Est_Pedido_Habili		= RTRIM(LTRIM((dbo.CF_xParam('SCA_Est_Ped_Habil'))))

IF (ISNULL(@pId_Cliente_Ref,0) <> 0)
BEGIN
	PRINT 'Valida por TITULAR'
	SET @pId_Cliente = @pId_Cliente_Ref
END

SET @SqlStrSelect = 'SELECT @Id_ProductoOUT = ISNULL(MAX(CI.Id_Producto),'''')'

IF(ISNULL(@pHorario,0) = 0)
BEGIN
   SET @SqlStrSelect = RTRIM(LTRIM(@SqlStrSelect)) + CHAR(13) + 
					   ' FROM Cbtes_Items CI, Cbtes CB, Cbtes_Tipos CT, CD_Accesos_Prod CA, Productos PR'
END
ELSE
BEGIN
   SET @SqlStrSelect =	RTRIM(LTRIM(@SqlStrSelect)) + CHAR(13) + 
						' FROM Cbtes_Items CI, Cbtes CB, Cbtes_Tipos CT, CD_Accesos_Prod CA, CD_Accesos_Horarios CAH, Productos PR'
END

IF(ISNULL(@pHorario,0) = 0)
BEGIN
	SET @SqlStrWhere =	' WHERE' + CHAR(13) + 
						' CI.Id_Trans = CB.Id_Trans ' + CHAR(13) +
						' AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte' + CHAR(13) +
						' AND CA.Id_Acceso = '+ CAST(@pId_Acceso AS VARCHAR(5)) + CHAR(13) +
						' AND CA.Id_Producto = CI.Id_Producto' + CHAR(13) +
						' AND CI.Id_Cliente = '+ CAST(@pId_Cliente AS VARCHAR(10)) + CHAR(13) +
						' AND PR.Id_Producto = CA.Id_Producto '
END
ELSE
BEGIN
	SET @SqlStrWhere =	' WHERE' + CHAR(13) + 
						' CI.Id_Trans = CB.Id_Trans ' + CHAR(13) +
						' AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte' + CHAR(13) +
						' AND CA.Id_Acceso = '+ CAST(@pId_Acceso AS VARCHAR(5)) + CHAR(13) +
						' AND CA.Id_Producto = CI.Id_Producto' + CHAR(13) +
						' AND CI.Id_Cliente = '+ CAST(@pId_Cliente AS VARCHAR(10)) + CHAR(13) +
						' AND PR.Id_Producto = CA.Id_Producto ' + CHAR(13) +
						' AND CA.Id_Producto = CAH.Id_Producto ' + CHAR(13) +
						' AND CA.Id_Acceso = CAH.Id_Acceso '
END

IF @Flag_PermiteProdPorPed = 0                         ----incluismo pedidos o no
BEGIN
   SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
					' AND ((CT.Compromete_Factura = 1 ' + CHAR(13) + 
					' AND CB.Id_Estado_Cbte IN (4, 2))' + CHAR(13) + 
					' OR (CB.Id_Estado_Cbte IN (1) AND CI.Imp_Final = 0))' + CHAR(13) +
					--' AND CB.Id_Trans NOT IN (SELECT Id_Trans_Origen FROM Cbtes WHERE Id_Trans_Origen = CB.Id_Trans)'
					' AND dbo.CF_NC_A_FC(CB.Id_Trans) = 0'
END
ELSE
BEGIN
   SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
					' AND ((CT.Compromete_Factura = 1 AND CB.Id_Estado_Cbte IN (4, 2))' + CHAR(13) +
					' OR (CT.Compromete_Factura = 1 AND CB.Id_Estado_Cbte IN (1) AND CI.Imp_Final = 0)' + CHAR(13) +
					' OR (CT.Compromete_Pedido = 1 AND CB.Id_Estado_Cbte IN (' + @Est_Pedido_Habili + ')))'+ CHAR(13) +
					--' AND CB.Id_Trans NOT IN (SELECT Id_Trans_Origen FROM Cbtes WHERE Id_Trans_Origen = CB.Id_Trans)'
					' AND dbo.CF_NC_A_FC(CB.Id_Trans) = 0'
END

--IF(ISNULL(@pHorario,0) = 0)
--BEGIN
--	IF(ISNULL(@pId_Cliente_Ref,0) = 0)
--		SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
--						' AND ISNULL(CA.Valida_En_Titular,0) = 0'
--	ELSE
--		SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
--						' AND ISNULL(CA.Valida_En_Titular,0) = 1'
--END

IF(ISNULL(@pHorario,0) = 0)
BEGIN
	IF(ISNULL(@pId_Cliente_Ref,0) = 0)
		SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
						' AND ISNULL(CA.Valida_En_Titular,0) IN (1,0)'
	ELSE
		SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
						' AND ISNULL(CA.Valida_En_Titular,0) = 1'
END

IF (ISNULL(@pHorario,0) = 0)
BEGIN
	SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
						' AND ISNULL(CA.Flag_Consumible,0) = 0'
END

SET @SqlStr = RTRIM(LTRIM(@SqlStrSelect)) + CHAR(13) + RTRIM(LTRIM(@SqlStrWhere))

/*-----------------------------------------------------------------------------PRODUCTOS QUE NO VERIFICAN NI MES, NI PERIODO*/
SET @SqlStrWhereEsp =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
						' AND ISNULL(PR.Flag_Mes, 0) = 0 ' + CHAR(13) +  
						' AND ISNULL(PR.Flag_Periodo, 0) = 0'

IF (ISNULL(@pHorario,0)<>0)
	SET @SqlStrWhereEsp = RTRIM(LTRIM(@SqlStrWhereEsp)) + CHAR(13) + 
						 ' AND CAH.Dia = ' + CAST(@DiaActual AS VARCHAR(1)) + CHAR(13) +
						 ' AND ((CAH.Hora_Desde IS NULL AND CAH.Hora_Hasta IS NULL) OR ( '''+ CONVERT(VARCHAR(8),@pFecha,108) +''' BETWEEN CAST(CAH.Hora_Desde AS TIME) AND CAST(CAH.Hora_Hasta AS TIME)))'
                       
PRINT @SqlStrWhereEsp
EXECUTE sp_executesql @SqlStrWhereEsp, @Parametros, @Id_ProductoOUT = @Id_Producto OUTPUT;
IF (@Id_Producto <> '')
   RETURN

/*--------------------------------------------------------------------------------------PRODUCTOS QUE VERIFICAN MES*/
SET @SqlStrWhereEsp =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
						' AND ISNULL(PR.Flag_Mes, 0) = 1'

IF (ISNULL(@pHorario,0)=0)
	SET @SqlStrWhereEsp = RTRIM(LTRIM(@SqlStrWhereEsp)) + CHAR(13) + 
						'AND CONVERT(date, '''+ CONVERT(VARCHAR(10),@pFecha,120) +''') <= DATEADD(DAY, ISNULL(CA.Dias_Gracia,0),DATEADD(DAY, 1, EOMONTH(DATEADD(MONTH, ISNULL(CA.Meses_Gracia,0), CONVERT(date, CI.Fecha_QA)), -1)))'
ELSE
	SET @SqlStrWhereEsp = RTRIM(LTRIM(@SqlStrWhereEsp)) + CHAR(13) +						 
						 'AND CONVERT(date, '''+ CONVERT(VARCHAR(10),@pFecha,120) +''') 
						  <= DATEADD(DAY, ISNULL(CA.Dias_Gracia,0),DATEADD(DAY, 1, EOMONTH(DATEADD(MONTH, ISNULL(CA.Meses_Gracia,0), CONVERT(date, CI.Fecha_QA)), -1)))
						  AND CAH.Dia = ' + CAST(@DiaActual AS VARCHAR(1)) + '
						  AND ((CAH.Hora_Desde IS NULL AND CAH.Hora_Hasta IS NULL) OR ('''+ CONVERT(VARCHAR(8),@pFecha,108) +''' BETWEEN CAST(CAH.Hora_Desde AS TIME) AND CAST(CAH.Hora_Hasta AS TIME)))'


PRINT @SqlStrWhereEsp
EXECUTE sp_executesql @SqlStrWhereEsp, @Parametros, @Id_ProductoOUT = @Id_Producto OUTPUT;
IF @Id_Producto <> ''
   RETURN


/*--------------------------------------------------------------------------------------PRODUCTOS QUE VERIFICAN PERIODO*/
SET @SqlStrWhereEsp =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
						' AND ISNULL(PR.Flag_Periodo, 0) = 1'
						
IF (ISNULL(@pHorario,0)=0)
	SET @SqlStrWhereEsp =	RTRIM(LTRIM(@SqlStrWhereEsp)) + CHAR(13) + 
							' AND CI.Fecha_QA < ('''+ CONVERT(VARCHAR(8),@pFecha + 1,112) +''')' + CHAR(13) + 
							' AND CONVERT(VARCHAR(8),DATEADD(DAY,CA.Dias_Gracia,CI.Fecha_Venc),112) > ('''+ CONVERT(VARCHAR(8),@pFecha - 1,112) +''')'
ELSE
	SET @SqlStrWhereEsp = RTRIM(LTRIM(@SqlStrWhereEsp)) + CHAR(13) +
                         ' AND CI.Fecha_QA < ('''+ CONVERT(VARCHAR(8),@pFecha + 1,112) +''')' + CHAR(13) +
                         ' AND CI.Fecha_Venc > ('''+ CONVERT(VARCHAR(8),@pFecha - 1,112) +''')' + CHAR(13) +
                         ' AND CAH.Dia = ' + CAST(@DiaActual AS VARCHAR(1)) + CHAR(13) +
						 ' AND ((CAH.Hora_Desde IS NULL AND CAH.Hora_Hasta IS NULL) OR ( '''+ CONVERT(VARCHAR(8),@pFecha,108) +''' BETWEEN CAST(CAH.Hora_Desde AS TIME) AND CAST(CAH.Hora_Hasta AS TIME)))'
                         

PRINT @SqlStrWhereEsp
EXECUTE sp_executesql @SqlStrWhereEsp, @Parametros, @Id_ProductoOUT = @Id_Producto OUTPUT;

RETURN
END
GO



CREATE PROCEDURE [dbo].[CP_SCA_ValidarProducVta_Kit] @pId_Cliente		INT, 
													 @pId_Acceso		SMALLINT, 
													 @pFecha			DATETIME, 
													 @pId_Cliente_Ref	INT, 
													 @pHorario			TINYINT,
													 @pFlag_GrabaRegistro TINYINT,  /* [2026-08-05] obligatorio (original); el bug estaba en el LLAMADOR, ya restaurado. Ver nota bajo BEGIN. */
													 @Id_Producto		VARCHAR(14) OUTPUT
AS
BEGIN

/* ============================================================================
   [2026-08-05] REGISTRO DE ERROR / CORRECCION
   Este SP NO tuvo el bug. La causa real fue el LLAMADOR CP_SCA_RegistrarAcceso,
   que al recrearse el 29/07/2026 12:37 dejo de pasar @pFlag_GrabaRegistro en su
   EXEC a este SP -> error 201 'expects parameter ... not supplied' -> fallaban
   los accesos por producto/kit (motivo 207 sin registros 28/07-04/08, ~6 dias).
   El 05/08 hubo un hotfix temporal (default=1 aca) y luego se RESTAURO el
   llamador (vuelve a pasar el arg); este parametro volvio a ser OBLIGATORIO como
   en el original (dump scripts/geba_xsys_2026.sql, 17/07/2026).
   ============================================================================ */

	--======= Variables Locales =======--

DECLARE @Flag_PermiteProdPorPed	INT
DECLARE @Est_Pedido_Habili		VARCHAR(8000)
DECLARE @SqlStr					NVARCHAR(MAX)
DECLARE @SqlStrSelect			NVARCHAR(MAX)
DECLARE @SqlStrWhere			NVARCHAR(MAX)
DECLARE @Parametros				NVARCHAR(100)
DECLARE @DiaActual				TINYINT
DECLARE @ExisteRemito						INT
DECLARE @Cantidad_Saldo						INT
DECLARE @Fecha_QA							DATETIME
DECLARE @Fecha_Venc							DATETIME
DECLARE @Id_Tipo_Cbte						CHAR(4)
DECLARE @json								VARCHAR(8000)
DECLARE @Id_Trans_Rem						INT
DECLARE @Id_Trans_Fac						INT
DECLARE @Item								INT
DECLARE @Result_Stored_Invocado				INT
DECLARE @Result_Tabla_Stored_Invocado		TABLE (ErrorNumber	INT,
											ErrorSeverity	INT,
											ErrorState		INT,
											ErrorProcedure  VARCHAR(1000),
											ErrorLine		INT,
											ErrorMessage	VARCHAR(4000))
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
DECLARE @rta_JSON_Stored_Invocado			VARCHAR(8000)

--======= Fin Variables Locales =======--

	PRINT 'Ingreso a Stored Procedure: CP_SCA_ValidarProducVta_Kit'

SET @Parametros = N'@Id_ProductoOUT VARCHAR(14) OUTPUT'; 

SET @Id_Producto	= ''

SET @Flag_PermiteProdPorPed =  (dbo.CF_xParam('SCA_Perm_ProdXPed'))
SET @Est_Pedido_Habili		= RTRIM(LTRIM((dbo.CF_xParam('SCA_Est_Ped_Habil'))))

IF (ISNULL(@pId_Cliente_Ref,0) <> 0)
BEGIN
   SET @pId_Cliente = @pId_Cliente_Ref
END

--===================================== Verifica si tiene un producto Pack Comprado =====================================--

SET @SqlStrSelect = 'SELECT @Id_ProductoOUT = ISNULL(MAX(CI.Id_Producto),'''') '


IF(ISNULL(@pHorario,0) = 0)
BEGIN
   SET @SqlStrSelect = RTRIM(LTRIM(@SqlStrSelect)) + CHAR(13) + 
					   ' FROM Cbtes_Items CI, Cbtes CB, Cbtes_Tipos CT, CD_Accesos_Prod CA, Productos PR'
END
ELSE
BEGIN
   SET @SqlStrSelect =	RTRIM(LTRIM(@SqlStrSelect)) + CHAR(13) + 
						' FROM Cbtes_Items CI, Cbtes CB, Cbtes_Tipos CT, CD_Accesos_Horarios CA, Productos PR'
END


SET @SqlStrWhere =	' WHERE' + CHAR(13) + 
					' CI.Id_Trans = CB.Id_Trans ' + CHAR(13) +
					' AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte' + CHAR(13) +
					' AND CA.Id_Acceso = '+ CAST(@pId_Acceso AS VARCHAR(5)) + CHAR(13) +
					' AND CA.Id_Producto = CI.Id_Producto' + CHAR(13) +
					' AND CI.Id_Cliente = '+ CAST(@pId_Cliente AS VARCHAR(10)) + CHAR(13) +
					' AND PR.Id_Producto = CA.Id_Producto '

IF @Flag_PermiteProdPorPed = 0 /*Se incluye pedido o no*/
BEGIN
   SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
					' AND ((CT.Compromete_Factura = 1 ' + CHAR(13) + 
					' AND CB.Id_Estado_Cbte IN (4, 2))' + CHAR(13) + 
					' OR (CB.Id_Estado_Cbte IN (1) AND CI.Imp_Final = 0))' + CHAR(13) +
					' AND dbo.CF_NC_A_FC(CB.Id_Trans) = 0'
END
ELSE
BEGIN
   SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
					' AND ((CT.Compromete_Factura = 1 AND CB.Id_Estado_Cbte IN (4, 2))' + CHAR(13) +
					' OR (CT.Compromete_Factura = 1 AND CB.Id_Estado_Cbte IN (1) AND CI.Imp_Final = 0)' + CHAR(13) +
					' OR (CT.Compromete_Pedido = 1 AND CB.Id_Estado_Cbte IN (' + @Est_Pedido_Habili + ')))'+ CHAR(13) +
					' AND ISNULL((SELECT MAX(canr.id_trans)
					  FROM Cbtes_Aplica CAFR, Cbtes_Aplica CANR, Cbtes_Tipos CTF, Cbtes_Tipos CTN, Cbtes CBF, Cbtes CBN
					  WHERE 
					  CAFR.Id_Trans = CB.ID_TRANS
					  AND CAFR.id_trans_d = CANR.id_trans_d
					  AND CAFR.Id_Trans = CBF.Id_Trans
					  AND CTF.Id_Tipo_Cbte = CBF.Id_Tipo_Cbte
					  AND CTF.Compromete_Factura = 1
					  AND CANR.Id_Trans = CBN.Id_Trans
					  AND CTN.Id_Tipo_Cbte = CBN.Id_Tipo_Cbte
					  AND CTN.Compromete_Factura = -1
					  AND CAFR.Importe = CANR.Importe),0) = 0'
END

IF(ISNULL(@pHorario,0) = 0)
BEGIN
	IF(ISNULL(@pId_Cliente_Ref,0) = 0)
	BEGIN
		SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
						' AND ISNULL(CA.Valida_En_Titular,0) = 0'
	END
	ELSE
	BEGIN
		SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
						' AND ISNULL(CA.Valida_En_Titular,0) = 1'
	END
END

IF (ISNULL(@pHorario,0) = 0)
BEGIN
	SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
						' AND CA.Flag_Consumible = 1'
END

SET @SqlStr = RTRIM(LTRIM(@SqlStrSelect)) + CHAR(13) + RTRIM(LTRIM(@SqlStrWhere))
PRINT @SqlStr 

EXECUTE sp_executesql @SqlStr, @Parametros, @Id_ProductoOUT = @Id_Producto OUTPUT;

--===================================== Verifica que exista un remito para ese dÔö£┬ía =====================================--

IF (@Id_Producto <> '')
BEGIN
	SET @ExisteRemito = ISNULL((SELECT COUNT(*) FROM Cbtes C, Cbtes_Tipos T, Cbtes_Items I 
									WHERE C.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
									AND C.Id_Trans=I.Id_Trans
									AND T.Compromete_Remitos IN (1, -1)
									AND C.Id_Estado_Cbte = 2
									AND I.Id_Producto = @Id_Producto
									AND I.Id_Cliente = @pId_Cliente
									AND CONVERT(DATE, C.Fecha) = CONVERT(DATE, @pFecha)),0)
	IF (@ExisteRemito > 0)
	BEGIN
		PRINT 'Existe remito para el dia actual'
		RETURN
	END
	ELSE
	BEGIN
		PRINT 'Ingreso a Generacion de Remito'
		
		SELECT TOP 1 @Cantidad_Saldo = ISNULL(MAX(CI.Cantidad_Saldo),0), 
					 @Id_Trans_Fac = CB.Id_Trans,
					 @Fecha_QA = ISNULL(CI.Fecha_QA,'01011900'),
					 @Fecha_Venc = ISNULL(CI.Fecha_Venc,'01011900'),
					 @Item = CI.Item
				FROM Cbtes_Items CI, Cbtes CB, Cbtes_Tipos CT
				WHERE CI.Id_Trans = CB.Id_Trans 
					AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte
					AND CI.Id_Cliente = @pId_Cliente
					AND CI.Id_Producto = @Id_Producto
					AND ((CT.Compromete_Factura = 1 AND CB.Id_Estado_Cbte IN (4, 2))
					OR (CB.Id_Estado_Cbte IN (1) AND CI.Imp_Final = 0))
					AND CI.Cantidad_Saldo > 0													/*Saldo mayor a cero*/
					AND CONVERT(DATE,CI.Fecha_Venc) >= CONVERT(DATE,@pFecha)					/*Dentro del periodo del item*/
					AND CONVERT(DATE,CI.Fecha_QA) <= CONVERT(DATE,@pFecha)						/*Dentro del periodo del item*/
				GROUP BY CI.Cantidad_Saldo, CB.Id_Trans, CI.Fecha_QA, CI.Fecha_Venc,CI.Item
				ORDER BY CB.Id_Trans ASC

				--====================== Verifica que Cantida Saldo sea mayor a Cero / Genera Recibo ======================--
		IF (@Cantidad_Saldo > 0)
		BEGIN
			IF(@pFlag_GrabaRegistro = 1)
			BEGIN
				SET @Id_Tipo_Cbte	= (SELECT Id_Tipo_Cbte FROM CD_Accesos_Prod WHERE Id_Acceso = @pId_Acceso AND Id_Producto = @Id_Producto)

				SET @json =	'{'
					SET @json =	@json + '"FlagUsarTrans":"1"'
					SET @json =	@json +	',"ModoDebug":"0"'
					SET @json =	@json +	',"RtaMsjStored":"0"'
					SET @json =	@json +	',"Id_Usuario":"-1"'
					SET @json =	@json +	',"Id_Tipo_Cbte":"' + CONVERT(VARCHAR(4), @Id_Tipo_Cbte ) +'"'
					SET @json =	@json +	',"Fecha":"' + CONVERT(VARCHAR(10), @pFecha, 112) +'"'
					SET @json =	@json +	',"Id_Cliente":"' + CONVERT(VARCHAR(10), @pId_Cliente) +'"'
					SET @json =	@json +	',"Fecha_Estimada":"' + CONVERT(VARCHAR(10), @pFecha, 112) +'"'
					SET @json =	@json +	',"Id_Cond_Pago":"10"'
					SET @json =	@json +	',"Lote":"DESCUENTO_PROD_SCA"'
					SET @json =	@json +	'}'

					SET @Id_Trans_Rem = 0
					DELETE @Result_Tabla_Stored_Invocado
		
					INSERT INTO @Result_Tabla_Stored_Invocado  
					EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Rem_Generar @json

					IF ISNULL(@Result_Stored_Invocado, 0) <> 0 
					BEGIN
						RAISERROR ('Error when calling CPJ_Cbtes_Rem_Generar', 16,  1 ) 
					END
					ELSE
					BEGIN
						SELECT TOP 1 @rta_JSON_Stored_Invocado = ErrorMessage FROM @Result_Tabla_Stored_Invocado
						SET @Id_Trans_Rem = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@rta_JSON_Stored_Invocado,'Id_Trans')), 0)
					END

				PRINT '@Id_Trans_Rem: '+ CONVERT (VARCHAR (15), @Id_Trans_Rem)

				IF(@Id_Trans_Rem > 0)
					BEGIN
						SET @json =	'{'
						SET @json =	@json + '"FlagUsarTrans":"1"'
						SET @json =	@json +	',"ModoDebug":"0"'
						SET @json =	@json +	',"RtaMsjStored":"1"'
						SET @json =	@json +	',"Id_Trans":"' + CONVERT(VARCHAR(10), @Id_Trans_Rem) +'"'
						SET @json =	@json +	',"Id_Cliente":"' + CONVERT(VARCHAR(10), @pId_Cliente) +'"'
						SET @json =	@json +	',"Id_Producto":"' + CONVERT(VARCHAR(14), @Id_Producto) +'"'
						SET @json =	@json +	',"Cantidad":"1"'
						SET @json =	@json +	',"Fecha_QA":"' + CONVERT(VARCHAR(10), @pFecha, 112) +'"'
						SET @json =	@json +	',"Fecha_Venc":"' + CONVERT(VARCHAR(10), @pFecha, 112) +'"'
						SET @json =	@json +	',"Refacturar":"1"'
						SET @json =	@json +	'}'

						EXEC dbo.CPJ_Cbtes_Rem_Generar_Item @json

					END

				IF(@Id_Trans_Rem > 0)
					BEGIN
						SET @json =	'{'
						SET @json =	@json + '"FlagUsarTrans":"1"'
						SET @json =	@json +	',"ModoDebug":"0"'
						SET @json =	@json +	',"RtaMsjStored":"1"'
						SET @json =	@json +	',"Id_Trans":"' + CONVERT(VARCHAR(10), @Id_Trans_Rem) +'"'
						SET @json =	@json +	'}'

						EXEC dbo.CPJ_Cbtes_Rem_Fin @json

					END

				UPDATE Cbtes_Items SET Cantidad_Saldo -= 1 WHERE Id_Trans = @Id_Trans_Fac AND Id_Producto = @Id_Producto AND Id_Cliente = @pId_Cliente AND Item = @Item
				UPDATE Cbtes SET Id_Trans_Origen = @Id_Trans_Fac, Id_Estado_Cbte = 2 WHERE Id_Trans = @Id_Trans_Rem AND Id_Cliente = @pId_Cliente

																												

				INSERT INTO Cbtes_Aplica (Id_Trans,			Item,		Id_Trans_D,		Item_D,		
										  Cantidad,			Importe,	Fecha_Aplic)
								   VALUES(@Id_Trans_Rem,	1,			@Id_Trans_Fac,	1,
										  0,				0,			@pFecha)
										  
				PRINT 'Fin Stored Procedure: CP_SCA_ValidarProducVta_Kit (Se Genera Remito Correctamente)'
				RETURN
			END
		END
		ELSE
		BEGIN
			PRINT 'Fin Stored Procedure: CP_SCA_ValidarProducVta_Kit (No se genera remito; No tiene Cantidad Saldo Disponible o No se Encuentra en el Periodo)'
			SET @Id_Producto = ''
			RETURN
		END
	END
END

--============================================================================================================================================================

RETURN
END


/*
EXEC dbo.CP_SCA_ValidarProducVta_Kit 3840537, 
									 6, 
									 '20221128', 
									 0, 
									 0, 
									 ''
*/
GO


CREATE PROCEDURE [dbo].[CP_SCA_ValidarTurno]@pId_Cliente			INT, 
											@pId_Acceso				SMALLINT, 
											@pFecha					DATETIME, 
											@pTipoAcceso			CHAR(1), 
											@pFechaEvento			DATETIME,
											@Flag_ValidarTurno_Rta	TINYINT OUTPUT
AS
BEGIN
DECLARE @Flag_Valida_Turno			TINYINT
DECLARE @Id_Sector					SMALLINT
DECLARE @Minutos_Gracia_Previos		SMALLINT
DECLARE @Minutos_Gracia_Posteriores	SMALLINT
DECLARE @Flag_Tiene_Turno			TINYINT
DECLARE @Turnos						TINYINT
DECLARE @Fecha_Desde				DATETIME
DECLARE @Fecha_Hasta				DATETIME

SET @Flag_Tiene_Turno = 0
SET @Flag_ValidarTurno_Rta = 0

SET @Flag_Valida_Turno = ISNULL((SELECT MAX(1) FROM CD_Accesos_Emp_Sedes_Sec WHERE Id_Acceso = @pId_Acceso), 0)

IF(@Flag_Valida_Turno = 1)
BEGIN	
	DECLARE curCD_Accesos_Emp_Sedes_Sectores CURSOR FOR
	SELECT
	Id_Sector,
	Minutos_Gracia_Prev,
	Minutos_Gracia_Post
	FROM CD_Accesos_Emp_Sedes_Sec
	WHERE
	Id_Acceso = @pId_Acceso

	OPEN curCD_Accesos_Emp_Sedes_Sectores
	FETCH NEXT FROM curCD_Accesos_Emp_Sedes_Sectores INTO @Id_Sector, @Minutos_Gracia_Previos, @Minutos_Gracia_Posteriores
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @Fecha_Desde = DATEADD(MINUTE, @Minutos_Gracia_Previos, @pFecha)
		SET @Fecha_Hasta = DATEADD(MINUTE, (-1) * @Minutos_Gracia_Posteriores, @pFecha)

		/*Busca si tiene un turno como titular CRM_Turnos*/
		SET @Flag_Tiene_Turno = ISNULL(	(SELECT MAX(1)
										FROM CRM_Turnos 
										WHERE
										Id_Cliente = @pId_Cliente
										AND Fecha <= @Fecha_Desde
										AND Fecha >= @Fecha_Hasta
										AND Id_Recurso IN (SELECT Id_Recurso FROM Empresas_Sedes_Sec_Recursos WHERE Id_Sector = @Id_Sector AND ISNULL(Activo, 0) = 1))
										, 0)

		IF(@Flag_Tiene_Turno = 1)
		BEGIN
			/*Tiene al menos 1 turno que cumple la condicion*/
			SET @Flag_ValidarTurno_Rta = 1
		END
		ELSE
		BEGIN
			/*Si no tiene como titular busca si tiene como integrante (CRM_Turnos_Clientes)*/
			SET @Flag_Tiene_Turno = ISNULL(	(SELECT MAX(1)
											FROM CRM_Turnos CT, CRM_Turnos_Clientes CTC
											WHERE
											CT.Id_Turno = CTC.Id_Turno
											AND CTC.Id_Cliente = @pId_Cliente
											AND CT.Fecha <= @Fecha_Desde
											AND CT.Fecha >= @Fecha_Hasta
											AND Id_Recurso IN (SELECT Id_Recurso FROM Empresas_Sedes_Sec_Recursos WHERE Id_Sector = @Id_Sector AND ISNULL(Activo, 0) = 1))
											, 0)
			IF(@Flag_Tiene_Turno = 1)
			BEGIN
				/*Tiene al menos 1 turno como integrante que cumple la condicion*/
				SET @Flag_ValidarTurno_Rta = 1
			END
		END
		
		FETCH NEXT FROM curCD_Accesos_Emp_Sedes_Sectores INTO @Id_Sector, @Minutos_Gracia_Previos, @Minutos_Gracia_Posteriores
	END
	CLOSE curCD_Accesos_Emp_Sedes_Sectores
	DEALLOCATE curCD_Accesos_Emp_Sedes_Sectores
END
ELSE
BEGIN
	/*No valida Turno*/
	SET @Flag_ValidarTurno_Rta = 1
END

RETURN ISNULL(@Flag_ValidarTurno_Rta, 1)
END
GO


CREATE PROCEDURE [dbo].[CP_SCA_ValidoAccesoAcompananteVisita]	@pId_Cliente							INT,
																@pFecha									DATETIME,
																@pId_Controlador						SMALLINT,
																@pId_Acceso								SMALLINT,
																@pFlag_TipoValidacionUCP				TINYINT,
																@Flag_AccesoPermitidoAcompananteVisita	TINYINT OUTPUT
AS
BEGIN
    SET NOCOUNT ON

    DECLARE @Habilitado INT = 0
	DECLARE @Timeout INT = ISNULL(dbo.CF_xParam('SCA_Visit_TmpLimit'), 0)

	SELECT 
		@Flag_AccesoPermitidoAcompananteVisita =
		CASE 
			WHEN EXISTS (
				SELECT 1 
				FROM Clientes_Invitados_Mov CIM
				LEFT JOIN CD_ES CES
					ON CIM.Id_ES = CES.Id_ES
				WHERE
					CONVERT(DATE, CIM.Fecha) <= CONVERT(DATE, @pFecha)
					AND CONVERT(DATE, CIM.Fecha_Hasta) >= CONVERT(DATE, @pFecha)
					AND CIM.Id_Cliente_D = @pId_Cliente
					AND (
						-- Si no tiene Id_ES
						ISNULL(CIM.Id_ES,0)=0
						OR
						-- Si tiene Id_ES, verificar que fue hace menos de 30 segundos
						CES.Fecha >= DATEADD(SECOND, -@Timeout, @pFecha)
					)
			)
			THEN 1
			ELSE 0
		END

   /* IF (@pFlag_TipoValidacionUCP = 1)  -- ACOMPANANTES/VISITAS NO DEBE VALIDAR LA UCP
    BEGIN
		SET @Habilitado = 
			CASE 
				WHEN EXISTS (
					SELECT 1
					FROM Clientes_Invitados_Mov CIM
					INNER JOIN Clientes L 
						ON CIM.Id_Cliente_D = L.Id_Cliente
					LEFT JOIN CD_ES CES
						ON CIM.Id_ES = CES.Id_ES
					WHERE
						CIM.Fecha <= @pFecha
						AND CIM.Fecha_Hasta >= @pFecha
						AND CIM.Id_Cliente_D = @pId_Cliente
						AND dbo.CF_SCA_ValidarUltCuotaPaga(CIM.Id_Cliente_D, @pId_Acceso, @pFecha) = 1
						AND (
							ISNULL(CIM.Id_ES,0)=0
							OR CES.Fecha >= DATEADD(SECOND,-5,@pFecha)
						)
				)
				THEN 1
				ELSE 0
			END


        IF (@Habilitado = 1)
        BEGIN
            SET @Flag_AccesoPermitidoAcompananteVisita = 1
        END
        ELSE
        BEGIN
            SET @Flag_AccesoPermitidoAcompananteVisita = 0
        END
    END*/

    RETURN ISNULL(@Flag_AccesoPermitidoAcompananteVisita, 0)
END
GO


CREATE PROCEDURE [dbo].[CP_SCA_ValidoAccesoPermitidoManualmente]	@pId_Cliente						INT,
																	@pFecha								DATETIME,
																	@pId_Controlador					SMALLINT,
																	@Flag_AccesoPermitidoManualmente	TINYINT OUTPUT
AS
BEGIN
DECLARE @SqlStr					NVARCHAR(1000)
DECLARE @Parametros				NVARCHAR(100)


SET @SqlStr =  N'SELECT @Flag_ExisteOUT = MAX(1) ' +
				'FROM CD_ES ' +
				'WHERE ' +
				'ISNULL(Flag_Permite_Paso, 0) = 1 ' + 
				'AND CONVERT(DATE, Fecha) = CONVERT(DATE, ''' + CONVERT(VARCHAR(10), @pFecha, 112) + ''') ' + --10/02/2020 Agregado (Maximo se puede utilizar el mismo dia)
				'AND Id_Cliente = ' + CONVERT(VARCHAR(10), @pId_Cliente)

SET @Parametros = N'@Flag_ExisteOUT TINYINT OUTPUT';

PRINT 'ACA'
PRINT @SqlStr

EXECUTE sp_executesql @SqlStr, @Parametros, @Flag_ExisteOUT = @Flag_AccesoPermitidoManualmente OUTPUT;

IF(ISNULL(@Flag_AccesoPermitidoManualmente, 0) = 1)
BEGIN
	UPDATE CD_ES
	SET
	Flag_Permite_Paso = 0,
	Fecha_Paso_Permitido = GETDATE(),
	Id_Controlador_Paso_Permitido = @pId_Controlador
	WHERE
	ISNULL(Flag_Permite_Paso, 0) = 1
	AND Id_Cliente = @pId_Cliente
END

RETURN ISNULL(@Flag_AccesoPermitidoManualmente, 0)

END
GO


CREATE PROCEDURE [dbo].[CP_SCA_ValidoCleverQR]			@pDma				VARCHAR(MAX),
														@pId_Acceso			SMALLINT,
														@pFecha				DATETIME, 
														@Flag_QRValido		INT OUTPUT
AS
BEGIN
DECLARE @Flag_Valida_Links		TINYINT
DECLARE @Existe_QR				INT
DECLARE @Flag_QR_Vigente		TINYINT
DECLARE @Flag_QR_YaUtilizado	TINYINT

/*
Valores Posibles de @Flag_QRValido:
1: Es valido o el acceso no controla QR en Clientes_Links o 
0: El QR no existe en Clientes_Links
-1: El QR existe en Clientes_links pero esta vencido
-2: El QR existe en Clientes_links no esta vencido pero ya esta utilizado
*/

SET @Flag_Valida_Links = ISNULL((SELECT ISNULL(Flag_Clientes_Links_Validar, 0) FROM CD_Accesos WHERE Id_Acceso = @pId_Acceso), 0)

IF(@Flag_Valida_Links = 1) 
BEGIN
	SET @Existe_QR = ISNULL(	(SELECT Id_Link
									FROM Clientes_Links
									WHERE
									LOWER(LTRIM(RTRIM(Url))) = LOWER(LTRIM(RTRIM(@pDma))))
								, 0)
	IF(@Existe_QR > 0)
	BEGIN
		SET @Flag_QR_Vigente = ISNULL(	(SELECT 1
										FROM Clientes_Links
										WHERE
										Id_Link = @Existe_QR
										AND Fecha_Desde <= @pFecha
										AND (Fecha_Hasta IS NULL OR Fecha_Hasta >= @pFecha))
									, 0)
									
		IF(@Flag_QR_Vigente = 1)
		BEGIN
			SET @Flag_QR_YaUtilizado = ISNULL(	(SELECT 1
											FROM Clientes_Links
											WHERE
											Id_Link = @Existe_QR
											AND Fecha_Desde <= @pFecha
											AND (Fecha_Hasta IS NULL OR Fecha_Hasta >= @pFecha)
											AND (Cant_Usos_Permitidos - Cant_Usos_Realizados) <= 0)
										, 0)
			IF(@Flag_QR_YaUtilizado = 0)
			BEGIN
				--El QR se puede utilizar
				SET @Flag_QRValido = 1
			END
			ELSE
			BEGIN
				--El QR existe en Clientes_links no esta vencido pero ya esta utilizado
				SET @Flag_QRValido = -2
			END
		END
		ELSE
		BEGIN
			--El QR existe en Clientes_links pero esta vencido
			SET @Flag_QRValido = -1
		END
	END
	ELSE
	BEGIN
		--El QR no existe en Clientes_Links
		SET @Flag_QRValido = 0
	END
END
ELSE
BEGIN
	/*El Acceso no valida QR (Clientes_Links)*/
	SET @Flag_QRValido = 1
END

RETURN ISNULL(@Flag_QRValido, 0)
END
GO


CREATE PROCEDURE [dbo].[CP_SCA_ValidoTagsImportados]	@pTag		VARCHAR(20),
														@pId_Acceso SMALLINT,
														@Flag_TagHabilitado	TINYINT OUTPUT
AS
BEGIN
DECLARE @Puertas				VARCHAR(100)
DECLARE @SqlStr					NVARCHAR(1000)
DECLARE @Parametros				NVARCHAR(100)

SET @Puertas = (SELECT Puerta FROM CD_Tags WHERE Id_Tag = @pTag AND Id_Lista_Precio IN (SELECT Id_Lista_Precio FROM CD_Accesos_Eventos WHERE Id_Acceso = @pId_Acceso))

SET @SqlStr = N'SELECT @Flag_ExisteOUT = 1 ' +
			   'FROM CD_Tags ' +
			   'WHERE ' +
				'Id_Tag = ''' + @pTag + 
				''' AND Id_Lista_Precio IN (SELECT Id_Lista_Precio FROM CD_Accesos_Eventos WHERE Id_Acceso = ' + CONVERT(VARCHAR(10), @pId_Acceso) +')' +
				' AND ' + CONVERT(VARCHAR(10), @pId_Acceso) + ' IN (' + @Puertas + ')' 				

SET @Parametros = N'@Flag_ExisteOUT TINYINT OUTPUT';

EXECUTE sp_executesql @SqlStr, @Parametros, @Flag_ExisteOUT = @Flag_TagHabilitado OUTPUT;

RETURN ISNULL(@Flag_TagHabilitado, 0)

END
GO


CREATE PROCEDURE [dbo].[CP_SCA_ValidoTicketEvento]		@pTag					VARCHAR(MAX),
														@pId_Acceso				SMALLINT,
														@pFecha					DATETIME, 
														@Flag_TicketHabilitado	INT OUTPUT
AS
BEGIN
DECLARE @Flag_Valida_Links		TINYINT
DECLARE @Existe_QR				INT
DECLARE @Flag_QR_Vigente		TINYINT
DECLARE @Flag_QR_YaUtilizado	TINYINT
DECLARE @Evento_QR_Formato		VARCHAR(40)
DECLARE @Id_Lista_Precio		SMALLINT
DECLARE @Id_Acceso				SMALLINT
DECLARE @Ticket_Nro				INT

/*
Valores Posibles de @Flag_TicketHabilitado:

	1: Es valido 
	0: Ticket Invalido
   -1: Ticket ya esta utilizado
   -2: Ticket Puerta Incorrecta
*/


SET @Evento_QR_Formato = dbo.CF_xParam('Evento_QR_Formato')

IF(@Evento_QR_Formato NOT IN ('14'))
BEGIN
	SET @Flag_TicketHabilitado = 0
END

IF(@Evento_QR_Formato IN ('14'))
BEGIN
	IF(LEN(@pTag) = 14)
	BEGIN
		IF(dbo.Is_Numeric(@pTag) = 1)
		BEGIN
			SET @Id_Lista_Precio	= SUBSTRING(@pTag, 1, 4)
			SET @Id_Acceso			= SUBSTRING(@pTag, 5, 3)
			SET @Ticket_Nro			= SUBSTRING(@pTag, 8, 7)

			SET @Flag_TicketHabilitado = 1
		END
		ELSE
		BEGIN
			SET @Flag_TicketHabilitado = 0
		END
	END
	ELSE
	BEGIN
		SET @Flag_TicketHabilitado = 0
	END
END

RETURN ISNULL(@Flag_TicketHabilitado, 0)
END
GO





CREATE PROCEDURE [dbo].[CP_Serial]
AS
BEGIN	


IF (SELECT ISNULL(CHARINDEX('linux', @@VERSION),0)  ) = 0    -- en linux no anda
	BEGIN 

		DECLARE @tbl TABLE(dir_lines VARCHAR(200))
		DECLARE @Cmd VARCHAR(2000)

		SET @cmd = 'dir "' + (SELECT NAME FROM sys.dm_os_loaded_modules WHERE DESCRIPTION like 'SQL Server%' AND NAME LIKE '%sqlservr.exe') + '"'
		INSERT INTO @tbl
		EXEC xp_cmdshell @cmd
		SELECT RIGHT(LTRIM(RTRIM(SUBSTRING(REPLACE(dir_lines,'-',''), CHARINDEX(':',dir_lines)+1,LEN(dir_lines)))),8) AS Serial 
			FROM @tbl WHERE dir_lines like '%volume%serial%' or dir_lines like '%serie%volume%'
	END
ELSE
	BEGIN
		SELECT @@SERVERNAME
	END

END
GO



CREATE PROCEDURE CP_SlowQueries @Start VARCHAR(10)
AS

IF @Start = ''
	SELECT 
		event_xml.value('(event/action[@name="sql_text"]/value)[1]', 'nvarchar(max)') AS sql_text,
		event_xml.value('(event/action[@name="database_name"]/value)[1]', 'nvarchar(max)') AS database_name,
		event_xml.value('(event/action[@name="client_hostname"]/value)[1]', 'nvarchar(max)') AS client_hostname,
		event_xml.value('(event/action[@name="username"]/value)[1]', 'nvarchar(max)') AS username,
		event_xml.value('(event/data[@name="duration"]/value)[1]', 'bigint') / 1000 AS duration_ms,
		DATEADD(HOUR, -3, event_xml.value('(event/@timestamp)[1]', 'datetime2')) AS [timestamp_local]
	FROM sys.fn_xe_file_target_read_file('c:\cleversoft\log\mssql\CE_SlowQueries*.xel', NULL, NULL, NULL) AS xefile
	CROSS APPLY (SELECT CAST(event_data AS XML) AS event_xml) AS x;

IF UPPER(@Start) =  'START'
	ALTER EVENT SESSION CE_SlowQueries ON SERVER STATE = START;

IF UPPER(@Start) =  'STOP'
	ALTER EVENT SESSION [CE_SlowQueries] ON SERVER STATE = STOP;	

RETURN
GO



