exec SP_Stk_Pedidos '40001',1

select * from empresas_suc


update empresas_suc set 

 */
GO


CREATE PROCEDURE [dbo].[CP_Stk_Valorizado] @Id_Fam INT, @Con_Stock TINYINT, @id_Prov INT, @Descrip CHAR(100), @pId_Producto  CHAR(14) = ' '

AS
SET NOCOUNT ON

/*Declaracion Variables Locales*/



DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@ID_PRODUCTO		VARCHAR(14)
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Trans_Rec		INT
		,@CursorOpen        INT
		,@Flag_Cbte_Tipo	SMALLINT
		,@Periodo           DATE 
		,@Id_sucursal	    SMALLINT
		,@Existe      	    SMALLINT
		,@DepFisico         CHAR(3)
		,@DepLogico         CHAR(3)
		,@Cantidad			DECIMAL(16,0)
		,@STK_10            INT
		,@Fecha             DATETIME


  SELECT ID_PRODUCTO INTO #STOCK FROM PRODUCTOS WHERE 1=0
		
  ALTER Table #STOCK  ADD
				DESCRIPCION	   	VARCHAR(150),
				MONEDA          CHAR(3),
				COSTO   	   	DECIMAL(16,2),
				COSTO_PESIF   	DECIMAL(16,2),
				TOTAL    	   	INT,
				FECHA_COSTO     DATETIME,
				STK_VALORIZADO  DECIMAL(16,2)

-------OJO!!!! Siempre que se agrega o elimina una columna aca, hay que modificar la estructura de la tabla "Producteca_Stock" que usa el Stored: SPJ_Producteca_Generar_Arch_Stock								 						
BEGIN 



   SELECT ID_PROVEEDOR INTO #PROVE FROM PROVEEDORES WHERE Activo = 1
   SELECT ID_FAMILIA INTO #FAMILIAS FROM Prod_Familias 

   IF @Id_Fam <> 0
      DELETE #FAMILIAS WHERE ID_FAMILIA <> @Id_Fam

   IF @id_Prov <> 0
      DELETE #PROVE WHERE ID_PROVEEDOR <> @id_Prov


   IF RTRIM(LTRIM(isnull(@descrip,''))) = '' 
	   BEGIN
		set @descrip = '%%'
	   END
	ELSE
	   BEGIN
		set @descrip = '%'+ltrim(rtrim(@Descrip))+'%' 
	   END   
 
 
    INSERT INTO #STOCK
    SELECT P.ID_PRODUCTO AS ID_PRODUCTO ,P.DESCRIPCION_DETALLADA AS DESCRIPCION ,
	        P.ID_MONEDA_C AS MONEDA,
			P.COSTO AS COSTO,
			P.COSTO * M.COTIZACION AS COSTO_PESIF ,
			0 AS	TOTAL, 
			P.Fecha_Costo AS   FECHA_ULT_COSO,
			0 AS STK_VALORIZADO  
			FROM Productos P, #FAMILIAS F,Valores_Monedas M,#PROVE K
	   WHERE P.Activo = 1
	   AND P.Vendible = 1
	   AND P.Maneja_Stock = 1
	   AND P.ID_FAMILIA = F.ID_FAMILIA
	   AND P.Id_Proveedor = K.Id_Proveedor
	   AND ISNULL(P.Id_Moneda_C,'PES')= M.Id_Moneda
	   AND P.Descripcion_Detallada like rtrim(Ltrim(@descrip))





   SELECT  I.ID_PRODUCTO,sum(i.Cantidad*t.compromete_Stock) AS CANTIDAD
           INTO #Inventario
		   from cbtes c, cbtes_tipos t, cbtes_items i, PRODUCTOS S
		   where c.id_tipo_cbte  = t.id_tipo_cbte
		   and I.Id_Trans = c.Id_Trans
		   And c.id_Estado_Cbte <> 3
		   and I.id_Producto = S.Id_Producto 
		   And t.compromete_Stock in (1,-1)
		   AND I.FLAG_QA = 'A'
		   group by I.ID_PRODUCTO


	
         UPDATE #STOCK SET TOTAL = V.Cantidad, STK_VALORIZADO = V.Cantidad * S.COSTO_PESIF	
         FROM #STOCK S, #Inventario V
         WHERE s.ID_PRODUCTO =  v.ID_PRODUCTO 
  


 

--		/*FIN */

END 

IF @pId_Producto <> '_'
   BEGIN
		SELECT * FROM #STOCK WHERE ID_PRODUCTO = @pId_producto  
   END
 ELSE
   BEGIN
		IF ISNULL(@Con_Stock,0) = 0   
			SELECT * FROM #STOCK  ORDER BY DESCRIPCION
		ELSE
			SELECT * FROM #STOCK WHERE TOTAL > 0   ORDER BY DESCRIPCION
   END 
   
 DROP TABLE #STOCK


 /* 

 exec CP_Stk_valorizado 0,0,0,'','_'


 FIN */
GO


CREATE PROCEDURE [dbo].[CP_Stk_Valorizado_Fecha] @Id_Fam INT, @Con_Stock TINYINT, @id_Prov INT, @Descrip CHAR(100), @pId_Producto  CHAR(14) = ' ', @pFecha_Ref DATETIME
AS
SET NOCOUNT ON

/*Declaracion Variables Locales*/



DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@ID_PRODUCTO		VARCHAR(14)
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Trans_Rec		INT
		,@CursorOpen        INT
		,@Flag_Cbte_Tipo	SMALLINT
		,@Periodo           DATE 
		,@Id_sucursal	    SMALLINT
		,@Existe      	    SMALLINT
		,@DepFisico         CHAR(3)
		,@DepLogico         CHAR(3)
		,@Cantidad			DECIMAL(16,0)
		,@STK_10            INT
		,@Fecha             DATETIME


  SELECT ID_PRODUCTO INTO #STOCK FROM PRODUCTOS WHERE 1=0
		
  ALTER Table #STOCK  ADD
				DESCRIPCION	   	VARCHAR(150),
				MONEDA          CHAR(3),
				COSTO   	   	DECIMAL(16,2),
				COTIZACION      DECIMAL(16,4),
				COSTO_PESIF   	DECIMAL(16,2),
				TOTAL    	   	INT,
				FECHA_COSTO     DATETIME,
				STK_VALORIZADO  DECIMAL(16,2)

  BEGIN 

   SELECT ID_PROVEEDOR INTO #PROVE FROM PROVEEDORES WHERE Activo = 1
   SELECT ID_FAMILIA INTO #FAMILIAS FROM Prod_Familias 

   IF @Id_Fam <> 0
      DELETE #FAMILIAS WHERE ID_FAMILIA <> @Id_Fam

   IF @id_Prov <> 0
      DELETE #PROVE WHERE ID_PROVEEDOR <> @id_Prov


   IF RTRIM(LTRIM(isnull(@descrip,''))) = '' 
	   BEGIN
		set @descrip = '%%'
	   END
	ELSE
	   BEGIN
		set @descrip = '%'+ltrim(rtrim(@Descrip))+'%' 
	   END   
 
 

    INSERT INTO #STOCK
    SELECT P.ID_PRODUCTO AS ID_PRODUCTO ,P.DESCRIPCION_DETALLADA AS DESCRIPCION ,
	        P.ID_MONEDA_C AS MONEDA,
			P.COSTO AS COSTO,
			ISNULL(M.Cotizacion_Ref,1) AS COTIZACION,
			P.COSTO * M.Cotizacion_Ref AS COSTO_PESIF ,
			0 AS	TOTAL, 
			P.Fecha_Costo AS   FECHA_ULT_COSO,
			0 AS STK_VALORIZADO  
			FROM Productos P, #FAMILIAS F,Valores_Monedas M,#PROVE K
	   WHERE P.Activo = 1
	   AND P.Vendible = 1
	   AND P.Maneja_Stock = 1
	   AND P.ID_FAMILIA = F.ID_FAMILIA
	   AND P.Id_Proveedor = K.Id_Proveedor
	   AND ISNULL(P.Id_Moneda_C,'PES')= M.Id_Moneda
	   AND P.Descripcion_Detallada like rtrim(Ltrim(@descrip))


   SELECT  I.ID_PRODUCTO,sum(i.Cantidad*t.compromete_Stock) AS CANTIDAD
           INTO #Inventario
		   from cbtes c, cbtes_tipos t, cbtes_items i, #STOCK S
		   where c.id_tipo_cbte  = t.id_tipo_cbte
		   and I.Id_Trans = c.Id_Trans
		   And c.id_Estado_Cbte <> 3
		   and I.id_Producto = S.Id_Producto 
		   And t.compromete_Stock in (1,-1)
		   AND I.FLAG_QA = 'A'
		   AND C.FECHA < dateadd(dd,1,@pFecha_Ref)
		   group by I.ID_PRODUCTO HAVING sum(i.Cantidad*isnull(t.compromete_Stock,1)) > 0
		   
		   
	

		SELECT I.ID_PRODUCTO, I.id_trans into #compra

		FROM CBTES_ITEMS I

		INNER JOIN (

			SELECT i.ID_producto, MAX(fecha_QA) AS fecha_QA

			FROM CBTES_ITEMS i, Cbtes C, Cbtes_Tipos T 

			WHERE i.FECHA_QA <  dateadd(dd,1,@pFecha_Ref)

		      And C.Id_Trans = I.Id_Trans
	          And C.Id_Estado_Cbte <> 3
	          And C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
	          And T.Compromete_Compras IN (1)
	          and i.Id_cliente = 0
			

			GROUP BY i.ID_producto

		) U

		ON I.ID_producto = U.ID_pRODUCTO AND I.fecha_QA = U.fecha_QA
		,CBTES CO, Cbtes_Tipos CT
		WHERE   CO.Id_Trans = I.Id_Trans 
	          And CO.Id_Estado_Cbte <> 3
	          And CO.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
	          And CT.Compromete_Compras IN (1)		
		
        Select Id_Producto,max(id_trans) as id_trans INTO #ULT_COMPRA  FROM #COMPRA GROUP BY Id_Producto 
        

			
        UPDATE #STOCK SET COSTO = I.PRECIO_GRAV
               , Fecha_Costo = I.FECHA_QA 
               , COSTO_PESIF = I.PRECIO_GRAV * S.COTIZACION
              FROM #STOCK S, Cbtes_Items I, #ULT_COMPRA U
              WHERE I.Id_Trans = U.Id_Trans
              AND I.Id_Producto = U.Id_Producto
              AND S.Id_Producto = U.Id_Producto
        
	

        UPDATE #STOCK SET TOTAL = V.Cantidad, STK_VALORIZADO = V.Cantidad * S.COSTO_PESIF	
        FROM #STOCK S, #Inventario V 
        WHERE s.ID_PRODUCTO =  v.ID_PRODUCTO 
  


 

--		/*FIN */

END 

IF @pId_Producto <> '_'
   BEGIN
		SELECT * FROM #STOCK WHERE ID_PRODUCTO = @pId_producto  
   END
 ELSE
   BEGIN
		IF ISNULL(@Con_Stock,0) = 0   
			SELECT * FROM #STOCK  ORDER BY DESCRIPCION
		ELSE
			SELECT * FROM #STOCK WHERE TOTAL > 0   ORDER BY DESCRIPCION
   END 
   
 DROP TABLE #STOCK
 DROP TABLE #Inventario
 DROP TABLE #ULT_COMPRA
 DROP TABLE #COMPRA
 /* 

 exec CP_Stk_valorizado_fecha 0,0,0,'','25082','20221231'
 
 
 select * from cbtes where id_trans = 1414723
 






 FIN */
GO

CREATE PROCEDURE CP_Tab_Reportes_Borrar @Id_Reporte VARCHAR(50)
AS
DECLARE @Mensaje			VARCHAR(100)
BEGIN TRY
	BEGIN TRAN

	DELETE Tab_Reportes_xCampos WHERE Id_Reporte = @Id_Reporte
	DELETE Tab_Reportes_Users WHERE Id_Reporte = @Id_Reporte
	DELETE Tab_Reportes_Col WHERE Id_Reporte = @Id_Reporte
	DELETE Tab_Reportes_Bandas WHERE Id_Reporte = @Id_Reporte
	DELETE Tab_Reportes WHERE Id_Reporte = @Id_Reporte

	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage
			,@Id_Reporte		AS Id_Reporte

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO

CREATE PROCEDURE CP_Tab_Reportes_Copiar @Id_Reporte VARCHAR(50)
AS

DECLARE @Mensaje			VARCHAR(100)
BEGIN TRY
	BEGIN TRAN

	DECLARE @nro SMALLINT
	DECLARE @Id_Reporte_Nuevo VARCHAR(50)
	DECLARE @Descripcion_Nueva VARCHAR(200)
	DECLARE @Id_Banda INT
	DECLARE @Id_Banda_Nueva INT

	IF (NOT EXISTS (SELECT 1 FROM Tab_Reportes WHERE Id_Reporte = @Id_Reporte))
	BEGIN
		SELECT	 1					AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,'No Existe Reporte Origen'			AS ErrorMessage
				,@Id_Reporte	AS Id_Reporte
		ROLLBACK
		RETURN 1
    END



	SET @nro = 1
	SET @Id_Reporte_Nuevo = RTRIM(LTRIM(@Id_Reporte)) +':'+ CAST(@nro AS VARCHAR(50))
	SET @Descripcion_Nueva = RTRIM(LTRIM((SELECT Descripcion FROM Tab_Reportes WHERE Id_Reporte = @Id_Reporte)))  +':'+ CAST(@nro AS VARCHAR(50))

	WHILE (EXISTS (SELECT 1 FROM Tab_Reportes WHERE Id_Reporte = @Id_Reporte_Nuevo))
	BEGIN
		SET @nro = @nro + 1
		IF @nro = 1000 
		BEGIN
			SELECT	 1					AS ErrorNumber 
					,0					AS ErrorSeverity  
					,0					AS ErrorState 
					,0					AS ErrorProcedure  
					,0					AS ErrorLine		
					,'Sueperado Limite de 1000 en nuevo Id'			AS ErrorMessage
					,@Id_Reporte	AS Id_Reporte
			ROLLBACK
			RETURN 1
		END

		SET @Id_Reporte_Nuevo = RTRIM(LTRIM(@Id_Reporte)) +':'+ CAST(@nro AS VARCHAR(50))
		SET @Descripcion_Nueva = RTRIM(LTRIM((SELECT Descripcion FROM Tab_Reportes WHERE Id_Reporte = @Id_Reporte)))  +':'+ CAST(@nro AS VARCHAR(50))
	END 

	/*agregago tab_reportes*/
	SELECT * INTO #TempRpt FROM Tab_Reportes WHERE Id_Reporte = @Id_Reporte
	UPDATE #TempRpt SET Id_Reporte = @Id_Reporte_Nuevo, Descripcion = @Descripcion_Nueva
	INSERT INTO Tab_Reportes SELECT * FROM #TempRpt 
	DROP TABLE #TempRpt

	

	/*agregago tab_reportes_bandas*/
	DECLARE Cursor_Bandas CURSOR FOR SELECT Id_Banda FROM Tab_Reportes_Bandas WHERE Id_Reporte = @Id_Reporte
	OPEN Cursor_Bandas
	FETCH NEXT FROM Cursor_Bandas INTO @Id_Banda
	WHILE (@@FETCH_STATUS=0)
	BEGIN
	    SELECT * INTO #TempRptBandas FROM Tab_Reportes_Bandas WHERE Id_Banda = @Id_Banda
		UPDATE #TempRptBandas SET Id_Reporte = @Id_Reporte_Nuevo
		ALTER TABLE #TempRptBandas DROP COLUMN Id_Banda
		INSERT INTO Tab_Reportes_Bandas	SELECT * FROM #TempRptBandas 
		SET @Id_Banda_Nueva = @@IDENTITY
		DROP TABLE #TempRptBandas

		/*agregago tab_reportes_col*/
		SELECT * INTO #TempRptCol FROM Tab_Reportes_Col WHERE Id_Banda = @Id_Banda
		UPDATE #TempRptCol SET Id_Reporte = @Id_Reporte_Nuevo, Id_Banda = @Id_Banda_Nueva
		ALTER TABLE #TempRptCol DROP COLUMN Id_Rpt_Col
		INSERT INTO Tab_Reportes_Col	SELECT * FROM #TempRptCol 
		DROP TABLE #TempRptCol

		FETCH NEXT FROM Cursor_Bandas INTO @Id_Banda
	END
	CLOSE Cursor_Bandas
	DEALLOCATE Cursor_Bandas

	/*agrego tab_reportes_user*/
	SELECT * INTO #TempRptUsers FROM Tab_Reportes_Users WHERE Id_Reporte = @Id_Reporte
	UPDATE #TempRptUsers SET Id_Reporte = @Id_Reporte_Nuevo
	INSERT INTO Tab_Reportes_Users	SELECT * FROM #TempRptUsers 
	DROP TABLE #TempRptUsers

	/*agrego tab_reportes_xcampos*/
	SELECT * INTO #TempRptxCampos FROM Tab_Reportes_xCampos WHERE Id_Reporte = @Id_Reporte
	UPDATE #TempRptxCampos SET Id_Reporte = @Id_Reporte_Nuevo
	INSERT INTO Tab_Reportes_xCampos SELECT * FROM #TempRptxCampos 
	DROP TABLE #TempRptxCampos


	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage
			,@Id_Reporte_Nuevo	AS Id_Reporte

	


END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO




CREATE PROCEDURE [dbo].[CP_Transacciones_Generar]
@pId_Usuario SMALLINT
AS

/*Declaracion Variables Locales*/
DECLARE @Flag_Existe_Usuario	TINYINT
DECLARE @Id_Trans				INT
DECLARE @Descripcion			VARCHAR(50)
DECLARE @Fecha_Mov				DATETIME
DECLARE @Mensaje				VARCHAR(100)
/*Fin de Declaraciones Variables Locales */

PRINT 'Procedimiento: CP_Transacciones_Generar Id_Usuario: '+ CAST(@pId_Usuario AS VARCHAR(10))

BEGIN TRY
	BEGIN TRAN

	SET @Flag_Existe_Usuario = ISNULL((SELECT 1 FROM Seg_User WHERE No = @pId_Usuario), 0)
	IF (@Flag_Existe_Usuario = 0)
	BEGIN
		SET @Mensaje = 'No existe el usuario '

		SELECT	1001			AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
				,0				AS Id_Trans
		ROLLBACK
		RETURN 1001
	END

	SET @Descripcion	= 'CP_Transacciones_Generar'
	SET @Fecha_Mov		= GETDATE()
	SET @Id_Trans		= ISNULL((SELECT MAX(Id_Trans) + 1 FROM Transacciones), 0)

	INSERT INTO dbo.Transacciones
	(Id_Trans,		Descripcion,	Fecha_Mov,
	Id_Usuario)
	VALUES
	(@Id_Trans,		@Descripcion,	@Fecha_Mov,
	@pId_Usuario)

	COMMIT

	SET @Mensaje = @Descripcion

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage
			,@Id_Trans		AS Id_Trans

END TRY  


BEGIN CATCH  
    SELECT  ERROR_NUMBER() AS ErrorNumber  
		,ERROR_SEVERITY() AS ErrorSeverity  
		,ERROR_STATE() AS ErrorState  
		,ERROR_PROCEDURE() AS ErrorProcedure  
		,ERROR_LINE() AS ErrorLine  
		,ERROR_MESSAGE() AS ErrorMessage
		,@Id_Trans		AS Id_Trans 

	ROLLBACK
	RETURN 9999
END CATCH

PRINT 'FIN Procedimiento: CP_Transacciones_Generar Trans: '+ CAST(@Id_Trans AS VARCHAR(10))
RETURN 0
GO

CREATE PROCEDURE [dbo].[CP_Turno_Cli_Agregar] (
	@Id_Turno					INT,
	@Id_Cliente					INT
	) 

AS
 
DECLARE @Mensaje				VARCHAR(100)
DECLARE @Cupo_Max_Comp_Tipo		CHAR(1)		-- Tipo de reserva
DECLARE @Id_Turno_Acomp			INT			-- 
DECLARE @Id_Recurso_Horario		INT
DECLARE @Fecha					DATETIME

BEGIN TRY
BEGIN TRAN

	SELECT
		@Id_Recurso_Horario= Id_Recurso_Horario, 
		@Fecha= Fecha
		FROM CRM_Turnos
		WHERE Id_Turno=@Id_Turno

	SET  @Cupo_Max_Comp_Tipo = ISNULL((SELECT Cupo_Max_Comp_Tipo FROM Empresas_Sedes_Sec_Recuros_Horarios 
									WHERE Id_Recurso_Horario=@Id_Recurso_Horario),'A')

	IF(@Cupo_Max_Comp_Tipo <>'A')
	BEGIN
		INSERT INTO CRM_Turnos_Clientes(Id_Turno, Id_Cliente) VALUES(@Id_Turno,@Id_Cliente)
	END

	ELSE
	BEGIN

		SET  @Id_Turno_Acomp = ISNULL((SELECT MIN(Id_Turno) FROM CRM_Turnos 
		WHERE Id_Recurso_Horario=@Id_Recurso_Horario and Fecha=@Fecha AND Estado<>'R'),0)

		IF (@Id_Turno_Acomp <>0)
			UPDATE CRM_Turnos SET Id_Cliente=@Id_Cliente, Estado='R', Tipo_Reserva ='A',	Fecha_Asignacion = GETDATE()	
			WHERE Id_Turno=@Id_Turno_Acomp

		INSERT INTO CRM_Turnos_Clientes(Id_Turno, Id_Cliente, Id_Turno_Tomado) 
		VALUES(@Id_Turno,@Id_Cliente,@Id_Turno_Acomp)

	END

	COMMIT
	SELECT	 0					AS ErrorNumber 
			,0					AS ErrorSeverity  
			,0					AS ErrorState 
			,0					AS ErrorProcedure  
			,0					AS ErrorLine		
			,@Mensaje			AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_Turno_DesAsignar] (@Id_Turno INT)
AS

DECLARE @Mensaje VARCHAR(100)
DECLARE @Id_Turno_Padre INT
DECLARE @Id_Turno_Borrar INT
DECLARE @Id_Turno_Cli INT
DECLARE @Id_Turno_Tomado INT



BEGIN TRY
BEGIN TRAN

SELECT @Id_Turno_Padre=ISNULL(Id_Turno_Padre,0) from CRM_Turnos WHERE Id_Turno=@Id_Turno 
IF (@Id_Turno_Padre<>0) SET @Id_Turno = @Id_Turno_Padre



DECLARE Turno_BorrarPadre CURSOR FOR  SELECT Id_Turno FROM CRM_Turnos WHERE Id_Turno = @Id_Turno OR Id_Turno_Padre = @Id_Turno
OPEN Turno_BorrarPadre 
FETCH NEXT FROM Turno_BorrarPadre INTO @Id_Turno_Borrar
WHILE @@FETCH_STATUS = 0                     --recorro el grupo de tunos o el turno solo
BEGIN
--------------Borro los clientes------------------------------------------
	DECLARE TurnoBorrarClientes CURSOR FOR SELECT  Id_Turno_Cli,ISNULL(Id_Turno_Tomado, 0) FROM CRM_Turnos_Clientes 
	                           WHERE Id_Turno = @Id_Turno_Borrar

	OPEN TurnoBorrarClientes 
	FETCH NEXT FROM TurnoBorrarClientes INTO @Id_Turno_Cli,@Id_Turno_Tomado
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF @Id_Turno_Tomado <> 0 UPDATE CRM_Turnos SET Estado = '', Id_Cliente = 0, Fecha_Asignacion = NULL, Tipo_Reserva ='' , Id_Turno_Padre = 0, Nro_Operacion = '' WHERE Id_Turno=@Id_Turno_Tomado  --desagino el turno tomado
        DELETE CRM_Turnos_Clientes WHERE Id_Turno_Cli = @Id_Turno_Cli   -- borro turnos clientes
		FETCH NEXT FROM TurnoBorrarClientes INTO @Id_Turno_Cli,@Id_Turno_Tomado
	END
	CLOSE TurnoBorrarClientes
	DEALLOCATE TurnoBorrarClientes
--------------FIN Borro los clientes------------------------------------------
	UPDATE CRM_Turnos SET Estado = '', Id_Cliente = 0, Fecha_Asignacion = NULL, Tipo_Reserva ='', Id_Turno_Padre = 0, Nro_Operacion = ''
	WHERE Id_Turno=@Id_Turno_Borrar
	FETCH NEXT FROM Turno_BorrarPadre INTO @Id_Turno_Borrar
END
CLOSE Turno_BorrarPadre
DEALLOCATE Turno_BorrarPadre

COMMIT
SELECT  0 AS ErrorNumber
		,0 AS ErrorSeverity
		,0 AS ErrorState
		,0 AS ErrorProcedure
		,0 AS ErrorLine
		,@Mensaje AS ErrorMessage

END TRY


BEGIN CATCH
EXECUTE usp_GetErrorInfo;
ROLLBACK
END CATCH;
GO



CREATE PROCEDURE [dbo].[CP_Turno_Invitados] (
	@Apellido   VARCHAR(100),	
	@Nombre	    VARCHAR(100),
	@Documento  VARCHAR(100),
	@Email		VARCHAR(100),
	@Obs		VARCHAR(2000),
	@Fecha_Nac	DATETIME
	)
AS

------------INICIO DE VARIABLES LOCALES-----------

DECLARE @Existe_Id_Cliente			INT
DECLARE @Existe						INT
DECLARE @Categoia					VARCHAR(40)

------------FIN DE VARIABLES LOCALES--------------

SELECT @Existe				= COUNT(*) FROM Clientes WHERE Doc_Nro = CAST(@Documento AS BIGINT) AND Activo = 1
SELECT @Existe_Id_Cliente	= Id_Cliente FROM Clientes WHERE Doc_Nro = CAST(@Documento AS BIGINT) AND Activo = 1

----------------------------------------------------

SET @Fecha_Nac = REPLACE(@Fecha_Nac,'-','')

SET @Categoia = dbo.CF_xParam('Categ_Invitados')

----------------------------------------------------

IF (ISNULL(@Existe,0 ) <> 0)
BEGIN

SET @Existe  = @Existe

SELECT  0 AS ErrorNumber
			,0 AS ErrorSeverity
			,0 AS ErrorState
			,0 AS ErrorProcedure
			,0 AS ErrorLine
			,401 AS ErrorMessage
END
ELSE
BEGIN TRY
BEGIN TRAN

	SET @Existe  = (SELECT MAX(Id_Cliente) FROM Clientes ) + 1

	INSERT INTO Clientes (Razon_Social,	  Apellido,			Nombre,			Id_Tipo_Doc,	Doc_Nro,
						 Email,			  Email_Cob,		Email_Web,		Activo,			Id_Iva,
						 Id_Tipo_Cli,	  Fecha_Alta,		Tipo_Persona,	Id_Cliente,		ID_NACIONALIDAD,
						 ID_LISTA_PRECIO, Id_Cliente_Ref,	Observacion,	Fecha_Nac)

				VALUES (LTRIM(RTRIM(UPPER(@Apellido))) +' '+ LTRIM(RTRIM(UPPER(@Nombre))),UPPER(@Apellido),UPPER(@Nombre),'DNI',@Documento,
						 @Email,			@Email,			@Email,			1,				'CF',
						@Categoia, 			GETDATE(),		'F',			@Existe,		'ARG',
						0,					0,				@Obs,			@Fecha_Nac)

	
               
	COMMIT
	SELECT  0 AS ErrorNumber
			,0 AS ErrorSeverity
			,0 AS ErrorState
			,0 AS ErrorProcedure
			,0 AS ErrorLine
			,CAST(@Existe AS VARCHAR(4000)) AS ErrorMessage

END TRY

BEGIN CATCH
EXECUTE usp_GetErrorInfo;
ROLLBACK
END CATCH;
GO


CREATE PROCEDURE [dbo].[CP_VTAS_POR_ZONA] 
        @FECHA_DESDE DATETIME
	   ,@FECHA_HASTA DATETIME
	   ,@ID_PROVINCIA CHAR(3)
AS

--30/07/2021 Agregado
IF OBJECT_ID (N'VTAS_ZONA', N'U') IS NOT NULL 
BEGIN
	DROP TABLE VTAS_ZONA
END
--30/07/2021 FIN Agregado

CREATE TABLE VTAS_ZONA  (
			 ID_ZONA varchar(5)
			,Descripcion VARCHAR(300)
			,SDO_INICIAL  DECIMAL(16,2)
			,FACTURAS  DECIMAL(16,2)
			,DEBITOS  DECIMAL(16,2)
			,CREDITOS  DECIMAL(16,2)
			,COBRANZAS  DECIMAL(16,2)
			,DESCUENTOS  DECIMAL(16,2)
			,OTROS  DECIMAL(16,2)
			,RETENCIONES  DECIMAL(16,2)
			,SDO_FINAL  DECIMAL(16,2)
		)

INSERT INTO VTAS_ZONA (ID_ZONA, Descripcion,SDO_INICIAL,FACTURAS,DEBITOS,CREDITOS,COBRANZAS,DESCUENTOS,OTROS,RETENCIONES,SDO_FINAL) 
       select Id_ZONA,Descripcion,0,0,0,0,0,0,0,0,0 from Tab_Zonas  


  Declare @id_ZONA VARchar(5)
  Declare @Stock Decimal(17,4)
  Declare @Total Decimal(17,2)


-- SET @FECHA_DESDE = convert(char(6), @FECHA, 112) + '01' 


--Calculo FACTURAS
  Declare Cursor_FACTURAS Cursor for

		SELECT I.ID_ZONA,SUM(C.IMP_TOTAL*C.COTIZACION*T.Compromete_FACTURA) as TOTAL 
		 FROM CLIENTES I,Cbtes C,Cbtes_Tipos T , VTAS_ZONA M 
		WHERE I.Id_CLIENTE = C.Id_CLIENTE  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND I.ID_ZONA = M.ID_ZONA
		AND C.Id_Estado_Cbte <> 3 
		AND T.Compromete_FACTURA in (1) 
		AND (C.Fecha >= @FECHA_DESDE  and C.Fecha < @FECHA_HASTA +1 ) 
		AND T.Id_tributario in ('01','06','11')
        GROUP BY I.ID_ZONA  having SUM(C.IMP_TOTAL*T.Compromete_FACTURA) <> 0
	
	OPEN Cursor_FACTURAS

	FETCH NEXT FROM Cursor_FACTURAS
	INTO @Id_ZONA,@TOTAL

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update VTAS_ZONA set FACTURAS = @TOTAL where  ID_ZONA = @Id_ZONA

	 	FETCH NEXT FROM Cursor_FACTURAS
		INTO @Id_ZONA,@TOTAL
	END

	CLOSE Cursor_FACTURAS
	DEALLOCATE Cursor_FACTURAS


--Calculo DEBITOS
  Declare Cursor_DEBITOS Cursor for

		SELECT I.ID_ZONA,SUM(C.IMP_TOTAL*C.COTIZACION*T.Compromete_FACTURA) as TOTAL 
		 FROM CLIENTES I,Cbtes C,Cbtes_Tipos T , VTAS_ZONA M 
		WHERE I.Id_CLIENTE = C.Id_CLIENTE  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND I.ID_ZONA = M.ID_ZONA
		AND C.Id_Estado_Cbte <> 3 
		AND T.Compromete_FACTURA in (1) 
		AND (C.Fecha >= @FECHA_DESDE  and C.Fecha < @FECHA_HASTA+1 ) 
		AND T.Id_tributario NOT in ('01','06','11')
        GROUP BY I.ID_ZONA  having SUM(C.IMP_TOTAL*T.Compromete_FACTURA) <> 0
	
	OPEN Cursor_DEBITOS

	FETCH NEXT FROM Cursor_DEBITOS
	INTO @Id_ZONA,@TOTAL

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update VTAS_ZONA set DEBITOS = @TOTAL where  ID_ZONA = @Id_ZONA

	 	FETCH NEXT FROM Cursor_DEBITOS
		INTO @Id_ZONA,@TOTAL
	END

	CLOSE Cursor_DEBITOS
	DEALLOCATE Cursor_DEBITOS


--Calculo CREDITOS
  Declare Cursor_CREDITOS Cursor for

		SELECT I.ID_ZONA,SUM(C.IMP_TOTAL*C.COTIZACION) as TOTAL 
		 FROM CLIENTES I,Cbtes C,Cbtes_Tipos T , VTAS_ZONA M 
		WHERE I.Id_CLIENTE = C.Id_CLIENTE  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND I.ID_ZONA = M.ID_ZONA
		AND C.Id_Estado_Cbte <> 3 
		AND T.Compromete_FACTURA in (-1) 
		AND (C.Fecha >= @FECHA_DESDE  and C.Fecha < @FECHA_HASTA +1 ) 
        GROUP BY I.ID_ZONA  having SUM(C.IMP_TOTAL) <> 0
	
	OPEN Cursor_CREDITOS

	FETCH NEXT FROM Cursor_CREDITOS
	INTO @Id_ZONA,@TOTAL

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update VTAS_ZONA set CREDITOS = @TOTAL where  ID_ZONA = @Id_ZONA

	 	FETCH NEXT FROM Cursor_CREDITOS
		INTO @Id_ZONA,@TOTAL
	END

	CLOSE Cursor_CREDITOS
	DEALLOCATE Cursor_CREDITOS

--Calculo Recibos
  Declare Cursor_Recibos Cursor for

		SELECT I.ID_ZONA,SUM(C.IMP_TOTAL*C.COTIZACION) as TOTAL 
		 FROM CLIENTES I,Cbtes C,Cbtes_Tipos T , VTAS_ZONA M 
		WHERE I.Id_CLIENTE = C.Id_CLIENTE  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND I.ID_ZONA = M.ID_ZONA
		AND C.Id_Estado_Cbte <> 3 
		AND T.Compromete_RECIBOS in (1,-1) 
		AND (C.Fecha >= @FECHA_DESDE  and C.Fecha < @FECHA_HASTA +1 ) 
        GROUP BY I.ID_ZONA  having SUM(C.IMP_TOTAL) <> 0
	
	OPEN Cursor_Recibos

	FETCH NEXT FROM Cursor_Recibos
	INTO @Id_ZONA,@TOTAL

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update VTAS_ZONA set COBRANZAS = @TOTAL where  ID_ZONA = @Id_ZONA

	 	FETCH NEXT FROM Cursor_Recibos
		INTO @Id_ZONA,@TOTAL
	END

	CLOSE Cursor_Recibos
	DEALLOCATE Cursor_Recibos

--Calculo CREDITOS PARA EL SALDO ANTERIOR
  Declare Cursor_Recibos_SI Cursor for

		SELECT I.ID_ZONA,SUM(C.IMP_TOTAL*C.COTIZACION) as TOTAL 
		 FROM CLIENTES I,Cbtes C,Cbtes_Tipos T , VTAS_ZONA M 
		WHERE I.Id_CLIENTE = C.Id_CLIENTE  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND I.ID_ZONA = M.ID_ZONA
		AND C.Id_Estado_Cbte <> 3 
		AND (T.Compromete_RECIBOS in (1,-1) OR T.Compromete_FACTURA IN (-1)) 
		AND C.Fecha <  @FECHA_DESDE
        GROUP BY I.ID_ZONA  having SUM(C.IMP_TOTAL) <> 0
	
	OPEN Cursor_Recibos_SI

	FETCH NEXT FROM Cursor_Recibos_SI
	INTO @Id_ZONA,@TOTAL

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update VTAS_ZONA set SDO_INICIAL = SDO_INICIAL - @TOTAL where  ID_ZONA = @Id_ZONA

	 	FETCH NEXT FROM Cursor_Recibos_SI
		INTO @Id_ZONA,@TOTAL
	END

	CLOSE Cursor_Recibos_SI
	DEALLOCATE Cursor_Recibos_SI

--Calculo DEBITOS PARA EL SALDO ANTERIOR
  Declare Cursor_DEBITOS_SI Cursor for

		SELECT I.ID_ZONA,SUM(C.IMP_TOTAL*C.COTIZACION) as TOTAL 
		 FROM CLIENTES I,Cbtes C,Cbtes_Tipos T , VTAS_ZONA M 
		WHERE I.Id_CLIENTE = C.Id_CLIENTE  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND I.ID_ZONA = M.ID_ZONA
		AND C.Id_Estado_Cbte <> 3 
		AND  T.Compromete_FACTURA IN (1) 
		AND C.Fecha <  @FECHA_DESDE
        GROUP BY I.ID_ZONA  having SUM(C.IMP_TOTAL) <> 0
	
	OPEN Cursor_DEBITOS_SI

	FETCH NEXT FROM Cursor_DEBITOS_SI
	INTO @Id_ZONA,@TOTAL

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update VTAS_ZONA set SDO_INICIAL = SDO_INICIAL + @TOTAL where  ID_ZONA = @Id_ZONA

	 	FETCH NEXT FROM Cursor_DEBITOS_SI
		INTO @Id_ZONA,@TOTAL
	END

	CLOSE Cursor_DEBITOS_SI
	DEALLOCATE Cursor_DEBITOS_SI

--Calculo CREDITOS PARA EL SALDO ANTERIOR
  Declare Cursor_Recibos_SA Cursor for

		SELECT I.ID_ZONA,SUM(C.IMP_TOTAL*C.COTIZACION) as TOTAL 
		 FROM CLIENTES I,Cbtes C,Cbtes_Tipos T , VTAS_ZONA M 
		WHERE I.Id_CLIENTE = C.Id_CLIENTE  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND I.ID_ZONA = M.ID_ZONA
		AND C.Id_Estado_Cbte <> 3 
		AND (T.Compromete_RECIBOS in (1,-1) OR T.Compromete_FACTURA IN (-1)) 
		AND C.Fecha < @FECHA_HASTA+1
        GROUP BY I.ID_ZONA  having SUM(C.IMP_TOTAL) <> 0
	
	OPEN Cursor_Recibos_SA

	FETCH NEXT FROM Cursor_Recibos_SA
	INTO @Id_ZONA,@TOTAL

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update VTAS_ZONA set SDO_FINAL = SDO_FINAL - @TOTAL where  ID_ZONA = @Id_ZONA

	 	FETCH NEXT FROM Cursor_Recibos_SA
		INTO @Id_ZONA,@TOTAL
	END

	CLOSE Cursor_Recibos_SA
	DEALLOCATE Cursor_Recibos_SA

--Calculo DEBITOS PARA EL SALDO ANTERIOR
  Declare Cursor_DEBITOS_SA Cursor for

		SELECT I.ID_ZONA,SUM(C.IMP_TOTAL*C.COTIZACION) as TOTAL 
		 FROM CLIENTES I,Cbtes C,Cbtes_Tipos T , VTAS_ZONA M 
		WHERE I.Id_CLIENTE = C.Id_CLIENTE  AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte  
		AND I.ID_ZONA = M.ID_ZONA
		AND C.Id_Estado_Cbte <> 3 
		AND  T.Compromete_FACTURA IN (1) 
		AND C.Fecha < @FECHA_HASTA+1
        GROUP BY I.ID_ZONA  having SUM(C.IMP_TOTAL) <> 0
	
	OPEN Cursor_DEBITOS_SA

	FETCH NEXT FROM Cursor_DEBITOS_SA
	INTO @Id_ZONA,@TOTAL

	WHILE @@FETCH_STATUS = 0
	BEGIN

		 update VTAS_ZONA set SDO_FINAL = SDO_FINAL + @TOTAL where  ID_ZONA = @Id_ZONA

	 	FETCH NEXT FROM Cursor_DEBITOS_SA
		INTO @Id_ZONA,@TOTAL
	END

	CLOSE Cursor_DEBITOS_SA
	DEALLOCATE Cursor_DEBITOS_SA

select id_zona + ' - ' + descripcion AS 'Zona'  ,Descripcion, SDO_INICIAL,FACTURAS,DEBITOS,CREDITOS,COBRANZAS,DESCUENTOS,OTROS,RETENCIONES,SDO_FINAL from VTAS_ZONA

DROP table VTAS_ZONA



-- exec [CP_VTAS_POR_ZONA] '20170301','20170331','1'

-- SELECT *,SDO_INICIAL+FACTURAS+DEBITOS-CREDITOS-COBRANZAS-SDO_FINAL FROM VTAS_ZONA WHERE SDO_INICIAL+FACTURAS+DEBITOS-CREDITOS-COBRANZAS<>SDO_FINAL
GO


CREATE PROCEDURE [dbo].[CP_VarUserGuardar] @pId_Usuario SMALLINT, @pProcedimiento VARCHAR(100), @pId_Preset SMALLINT, @pVariable VARCHAR(100), @pValor VARCHAR(5000)

AS

/*Declaracion de Variables*/
DECLARE @FlagExisteRegistro	TINYINT
DECLARE @MensajeFinEjec		VARCHAR(100)
/*FIN Declaracion de Variables*/


PRINT '----------------------------------------------------------------'
PRINT 'Inicio de ejecucion: CP_VarUserGuardar'

PRINT 'Id_Usuario: ' + CONVERT(VARCHAR(10), @pId_Usuario) + '. Procedimiento: ' + @pProcedimiento + '. Id_Preset: ' + CONVERT(VARCHAR(10), @pId_Preset) + '. Variable: ' + @pVariable

SET @FlagExisteRegistro = 0

SET @FlagExisteRegistro = (SELECT ISNULL((SELECT 1 FROM Seg_Usuarios_Var WHERE Id_Usuario = @pId_Usuario AND Procedimiento = @pProcedimiento AND Variable = @pVariable AND Id_Preset = @pId_Preset), 0))

BEGIN TRY
	BEGIN TRAN
	
	IF(@FlagExisteRegistro = 1)
	BEGIN		
		SET @MensajeFinEjec = 'Existe un registro previo, se actualiza'
		PRINT @MensajeFinEjec
		UPDATE Seg_Usuarios_Var SET Valor = @pValor WHERE Id_Usuario = @pId_Usuario AND Procedimiento = @pProcedimiento AND Variable = @pVariable AND Id_Preset = @pId_Preset
		
	END
	ELSE
	BEGIN
		SET @MensajeFinEjec = 'No existe registro previo, se inserta uno nuevo'
		PRINT @MensajeFinEjec
		INSERT INTO Seg_Usuarios_Var (Id_Usuario, Procedimiento, Id_Preset, Variable, Valor) VALUES (@pId_Usuario, @pProcedimiento, @pId_Preset, @pVariable, @pValor)
	END
	
	COMMIT
	
	SELECT 0, 0, 0, 0, @MensajeFinEjec
END TRY

BEGIN CATCH  
    -- Ejecuta la rutina de recuperaci¾n de errores
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH

PRINT 'Fin de ejecucion: CP_VarUserGuardar'
PRINT '----------------------------------------------------------------'
GO


CREATE  PROCEDURE [dbo].[CP_Ventas_por_Cli_Producto]
	@pFecha_Desde			DATETIME,
	@pFecha_Hasta			DATETIME,
	@pid_cliente            int,
	@id_Sucursal            INT,
	@pid_familia            int,
	@Venta_Total            DECIMAL(12,2)
AS
SET NOCOUNT ON

/*Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@Id_Cliente		INT
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Trans_Rec		INT
		,@CursorOpen        INT
		,@Flag_Cbte_Tipo	SMALLINT
		,@Periodo           DATE 
		,@Existe      	    SMALLINT


					
BEGIN 

IF @Venta_Total = 0
   BEGIN
   IF @pid_familia = 0
      BEGIN
		IF @id_Sucursal = 0
		   BEGIN
			   set @Venta_Total = 	(select sum((isnull(c.imp_Gravado,0)+isnull(c.imp_Gravado2,0)+isnull(c.imp_Gravado3,0)+isnull(c.imp_NoGravado,0)+isnull(c.imp_Exento,0))*isnull(t.compromete_factura,0))
				   from cbtes c, cbtes_tipos t 
				   where c.id_tipo_cbte  = t.id_tipo_cbte
				   And c.Id_Estado_Cbte <> 3
   				   And T.Compromete_Factura in (1,-1)
				   AND C.ID_CLIENTE = @pid_cliente
				   AND C.FECHA >= @pFecha_Desde 
				   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
				   AND C.ID_TIPO_CBTE NOT IN ('CFIN','DFIN'))
			END
		  ELSE
			BEGIN
			   set @Venta_Total = 	(select sum((isnull(c.imp_Gravado,0)+isnull(c.imp_Gravado2,0)+isnull(c.imp_Gravado3,0)+isnull(c.imp_NoGravado,0)+isnull(c.imp_Exento,0))*isnull(t.compromete_factura,0))
				   from cbtes c, cbtes_tipos t 
				   where c.id_tipo_cbte  = t.id_tipo_cbte
				   And c.Id_Estado_Cbte <> 3
   				   And T.Compromete_Factura in (1,-1)
				   AND C.ID_CLIENTE = @pid_cliente
				   AND C.FECHA >= @pFecha_Desde 
				   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
				   AND T.ID_SUCURSAL = @id_Sucursal
				   AND C.ID_TIPO_CBTE NOT IN ('CFIN','DFIN'))
			END
	  END
	ELSE
	  BEGIN
		IF @id_Sucursal = 0
		   BEGIN
			   set @Venta_Total = (select sum(isnull(i.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0))
				   from cbtes c, cbtes_tipos t, cbtes_items i, productos p
				   where c.id_tipo_cbte  = t.id_tipo_cbte
				   and i.id_trans = c.id_trans
				   and i.id_producto = p.id_producto
				   and p.Id_Familia = @pid_familia
			       AND C.ID_CLIENTE = @pid_cliente
				   And c.Id_Estado_Cbte <> 3
   				   And T.Compromete_Factura in (1,-1)
				   AND C.FECHA >= @pFecha_Desde 
				   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
				   AND C.ID_TIPO_CBTE NOT IN ('CFIN','DFIN'))
			END
		  ELSE
			BEGIN
			   set @Venta_Total = 	(select sum(isnull(i.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0))
				   from cbtes c, cbtes_tipos t, cbtes_items i, productos p
				   where c.id_tipo_cbte  = t.id_tipo_cbte
				   and i.id_trans = c.id_trans
				   and i.id_producto = p.id_producto
				   and p.Id_Familia = @pid_familia
			       AND C.ID_CLIENTE = @pid_cliente
				   And c.Id_Estado_Cbte <> 3
   				   And T.Compromete_Factura in (1,-1)
				   AND C.FECHA >= @pFecha_Desde 
				   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
				   AND T.ID_SUCURSAL = @id_Sucursal
				   AND C.ID_TIPO_CBTE NOT IN ('CFIN','DFIN'))
			END
	  END
  END


   set @Id_Cliente = @pid_cliente
   IF  @pid_familia = 0
      BEGIN
		IF @id_Sucursal = 0
		   BEGIN

					select I.Id_Producto as Producto,P.Descripcion_Detallada as Descripcion ,CAST(Sum(I.Cantidad*T.Compromete_Factura) AS INT) As Cantidad
						,sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) as Importe,
						(sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) / @Venta_Total) * 100 as Porcentaje
						 from cbtes c, cbtes_tipos t, Cbtes_Items I, Productos P
						   where c.id_tipo_cbte  = t.id_tipo_cbte
						   and I.id_Trans = C.Id_Trans
						   And c.Id_Estado_Cbte <> 3
						   AND P.Id_Producto = I.Id_Producto
   						   And T.Compromete_Factura in (1,-1)
						   AND C.FECHA >= @pFecha_Desde 
						   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
						   AND C.ID_CLIENTE = @pid_cliente
						   AND C.ID_TIPO_CBTE NOT IN ('CFIN','DFIN')
						   group by I.Id_Producto,P.Descripcion_Detallada 
						    having sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0))  <> 0
						   order by Porcentaje Desc
			END
		 ELSE
			BEGIN
  

					select I.Id_Producto as Producto,P.Descripcion_Detallada as Descripcion ,CAST(Sum(I.Cantidad*T.Compromete_Factura) AS INT) As Cantidad
						,sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) as Importe,
						(sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) / @Venta_Total) * 100 as Porcentaje
						 from cbtes c, cbtes_tipos t, Cbtes_Items I, Productos P
						   where c.id_tipo_cbte  = t.id_tipo_cbte
						   and I.id_Trans = C.Id_Trans
						   And c.Id_Estado_Cbte <> 3
						   AND P.Id_Producto = I.Id_Producto
   						   And T.Compromete_Factura in (1,-1)
						   AND C.FECHA >= @pFecha_Desde 
						   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
						   AND C.ID_CLIENTE = @pid_cliente
						   AND T.ID_SUCURSAL = @id_Sucursal
						   AND C.ID_TIPO_CBTE NOT IN ('CFIN','DFIN')
						   group by I.Id_Producto,P.Descripcion_Detallada 
						    having sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0))  <> 0
						   order by Porcentaje Desc	END
     END
   ELSE
      BEGIN
		IF @id_Sucursal = 0
		   BEGIN

					select I.Id_Producto as Producto,P.Descripcion_Detallada as Descripcion ,CAST(Sum(I.Cantidad*T.Compromete_Factura) AS INT) As Cantidad
						,sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) as Importe,
						(sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) / @Venta_Total) * 100 as Porcentaje
						 from cbtes c, cbtes_tipos t, Cbtes_Items I, Productos P
						   where c.id_tipo_cbte  = t.id_tipo_cbte
						   and I.id_Trans = C.Id_Trans
						   And c.Id_Estado_Cbte <> 3
						   AND P.Id_Producto = I.Id_Producto
						   AND P.ID_FAMILIA = @pId_Familia
   						   And T.Compromete_Factura in (1,-1)
						   AND C.FECHA >= @pFecha_Desde 
						   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
						   AND C.ID_CLIENTE = @pid_cliente
						   AND C.ID_TIPO_CBTE NOT IN ('CFIN','DFIN')
						   group by I.Id_Producto,P.Descripcion_Detallada
						    having sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0))  <> 0
						   order by Porcentaje Desc
			END
		 ELSE
			BEGIN

					select I.Id_Producto as Producto,P.Descripcion_Detallada as Descripcion ,CAST(Sum(I.Cantidad*T.Compromete_Factura) AS INT) As Cantidad
						,sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) as Importe,
						(sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) / @Venta_Total) * 100 as Porcentaje
						 from cbtes c, cbtes_tipos t, Cbtes_Items I, Productos P
						   where c.id_tipo_cbte  = t.id_tipo_cbte
						   and I.id_Trans = C.Id_Trans
						   And c.Id_Estado_Cbte <> 3
						   AND P.Id_Producto = I.Id_Producto
   						   And T.Compromete_Factura in (1,-1)
						   AND C.FECHA >= @pFecha_Desde 
						   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
						   AND P.ID_FAMILIA = @pId_Familia
						   AND C.ID_CLIENTE = @pid_cliente
