CREATE PROCEDURE [dbo].[CP_Ventas_por_Familia]

    @pFecha_Desde   DATETIME,
    @pFecha_Hasta   DATETIME,
    @pFamilia       INT,
    @pSucursal      INT,
    @pProveedor     INT,
    @pVendedor      VARCHAR(20)

AS

BEGIN

    SET NOCOUNT ON;
    DECLARE @Venta_Total DECIMAL(18,2);
    DECLARE @Fecha_Hasta_Exclusiva DATETIME;
    SET @Fecha_Hasta_Exclusiva = DATEADD(DAY, 1, @pFecha_Hasta);
 
    /*

        Total general para calcular el porcentaje.

        No filtra por familia, igual que el SP original.

        SÝ filtra por fecha, sucursal, proveedor y vendedor.

    */

    SELECT 
        @Venta_Total =
            SUM(
                ISNULL(I.Imp_Gravado, 0)
                * (1 - ISNULL(C.Porc_Bonificacion, 0) / 100.0)
                * ISNULL(T.Compromete_Factura, 0)
            )
    FROM Cbtes C
    INNER JOIN Cbtes_Tipos T 
        ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
    INNER JOIN Cbtes_Items I 
        ON I.Id_Trans = C.Id_Trans
    INNER JOIN Productos P 
        ON P.Id_Producto = I.Id_Producto
    WHERE C.Id_Estado_Cbte <> 3
      AND T.Compromete_Factura IN (1, -1)
      AND C.Fecha >= @pFecha_Desde
      AND C.Fecha < @Fecha_Hasta_Exclusiva
      AND C.Id_Tipo_Cbte NOT IN ('CFIN', 'DFIN')
      AND (@pSucursal = 0 OR T.Id_Sucursal = @pSucursal)
      AND (@pProveedor = 0 OR P.Id_Proveedor = @pProveedor)
      AND (@pVendedor = '' OR C.Id_Vendedor = @pVendedor)

    OPTION (RECOMPILE);
 
 
    SELECT 
        P.Id_Familia AS Familia,
        F.Descripcion AS Descripcion,
        CAST(SUM(I.Cantidad * T.Compromete_Factura) AS INT) AS Cantidad,
         SUM(
            ISNULL(I.Imp_Gravado, 0)
            * (1 - ISNULL(C.Porc_Bonificacion, 0) / 100.0)
            * ISNULL(T.Compromete_Factura, 0)
        ) AS Importe,
         CASE 
            WHEN ISNULL(@Venta_Total, 0) = 0 THEN 0
            ELSE
                (
                    SUM(
                        ISNULL(I.Imp_Gravado, 0)
                        * (1 - ISNULL(C.Porc_Bonificacion, 0) / 100.0)
                        * ISNULL(T.Compromete_Factura, 0)
                    ) / @Venta_Total
                ) * 100
        END AS Porcentaje,
         SUM(
            ISNULL(I.Costo, 0)
            * ISNULL(V.Cotizacion, 1)
            * I.Cantidad
            * ISNULL(T.Compromete_Factura, 0)
        ) AS Costo,
        SUM(
            ISNULL(I.Imp_Gravado, 0)
            * (1 - ISNULL(C.Porc_Bonificacion, 0) / 100.0)
            * ISNULL(T.Compromete_Factura, 0)
        )
        -
        SUM(
            ISNULL(I.Costo, 0)
            * ISNULL(V.Cotizacion, 1)
            * I.Cantidad
            * ISNULL(T.Compromete_Factura, 0)
        ) AS Renta,
         CASE 
            WHEN 
                SUM(
                    CASE 
                        WHEN ISNULL(I.Costo * V.Cotizacion, 0) = 0 
                            THEN 1 
                        ELSE I.Costo * V.Cotizacion 
                    END
                    * I.Cantidad
                    * ISNULL(T.Compromete_Factura, 0)
                ) = 0
            THEN 0
            ELSE
                SUM(
                    ISNULL(I.Imp_Gravado, 0)
                    * (1 - ISNULL(C.Porc_Bonificacion, 0) / 100.0)
                    * ISNULL(T.Compromete_Factura, 0)
                )
                /
                SUM(
                    CASE 
                        WHEN ISNULL(I.Costo * V.Cotizacion, 0) = 0 
                            THEN 1 
                        ELSE I.Costo * V.Cotizacion 
                    END
                    * I.Cantidad
                    * ISNULL(T.Compromete_Factura, 0)
                )
        END AS Markup
    FROM Cbtes C
    INNER JOIN Cbtes_Tipos T 
        ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
    INNER JOIN Cbtes_Items I 
        ON I.Id_Trans = C.Id_Trans
    INNER JOIN Productos P 
        ON P.Id_Producto = I.Id_Producto
    LEFT JOIN Prod_Familias F 
        ON P.Id_Familia = F.Id_Familia
    LEFT JOIN Valores_Monedas V 
        ON P.Id_Moneda_C = V.Id_Moneda
    WHERE C.Id_Estado_Cbte <> 3
      AND T.Compromete_Factura IN (1, -1)
      AND C.Fecha >= @pFecha_Desde
      AND C.Fecha < @Fecha_Hasta_Exclusiva
      AND C.Id_Tipo_Cbte NOT IN ('CFIN', 'DFIN')
      AND (@pSucursal = 0 OR T.Id_Sucursal = @pSucursal)
      AND (@pProveedor = 0 OR P.Id_Proveedor = @pProveedor)
      AND (@pVendedor = '' OR C.Id_Vendedor = @pVendedor)
      AND (@pFamilia = 0 OR P.Id_Familia = @pFamilia)
     GROUP BY 
        P.Id_Familia,
        F.Descripcion
    HAVING 
        SUM(I.Cantidad * T.Compromete_Factura) <> 0
    ORDER BY 
        Porcentaje DESC
    OPTION (RECOMPILE);

END
