CREATE  PROCEDURE [dbo].[CP_Ventas_por_Producto]
	@pFecha_Desde			DATETIME,
	@pFecha_Hasta			DATETIME,
	@pFamilia               Int,
	@pSucursal              Int,
	@pProveedor             Int,
	@pVendedor              VARCHAR(20)
AS
SET NOCOUNT ON

/*Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@Id_Cliente		INT
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Trans_Rec		INT
		,@CursorOpen        INT
		,@Flag_Cbte_Tipo	SMALLINT
		,@Periodo           DATE 
		,@Id_sucursal	    SMALLINT
		,@Existe      	    SMALLINT
		,@Venta_Total       DECIMAL(16,2)

					
BEGIN 

   SELECT * INTO #UN FROM Empresas_Unid_Negocios

   SELECT ID_PROVEEDOR INTO #PROVE FROM PROVEEDORES WHERE Activo = 1
   SELECT ID_FAMILIA INTO #FAMILIAS FROM Prod_Familias WHERE Activo = 1
   SELECT ID_SUCURSAL INTO #SUCURSALES FROM EMPRESAS_SUC WHERE ACTIVO = 1 and Id_Sucursal < 90 and Id_Sucursal > 1
   SELECT ID_VENDEDOR INTO #VENDEDORES FROM VENDEDORES WHERE Activo = 1

   IF @pFamilia <> 0
      DELETE #FAMILIAS WHERE ID_FAMILIA <> @pFamilia

   IF @pSucursal <> 0
      DELETE #SUCURSALES WHERE ID_SUCURSAL <> @pSucursal

   IF @pProveedor <> 0
      DELETE #PROVE WHERE ID_PROVEEDOR <> @pProveedor

   IF @pVendedor <> ''
      DELETE #VENDEDORES WHERE ID_VENDEDOR <> @pVendedor

	set @Venta_Total = 	(select sum(isnull(I.Imp_Final,0)*t.compromete_factura)
					   from cbtes c, cbtes_tipos t , Cbtes_items I, Productos P, #UN U,
					       #FAMILIAS F, #SUCURSALES S, #PROVE PR, #VENDEDORES V
					   where c.id_tipo_cbte  = t.id_tipo_cbte
					   AND T.Id_Unid_Negocio = u.id_Unid_Negocio
					   And I.Id_trans = C.id_trans
					   And I.id_Producto = P.id_Producto
					   And P.id_Familia = F.Id_Familia
					   And P.Id_Proveedor = PR.Id_Proveedor
					   And T.Id_Sucursal = S.Id_Sucursal
					   and C.id_vendedor = V.id_vendedor
					   And c.Id_Estado_Cbte <> 3
   					   And T.Compromete_Factura in (1,-1)
					   AND C.FECHA >= @pFecha_Desde 
					   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
					   AND C.ID_TIPO_CBTE NOT IN ('CFIN','DFIN'))
	
		select I.Id_Producto as Producto,P.Descripcion_Detallada as Descripcion ,CAST(Sum(I.Cantidad*T.Compromete_Factura) AS INT) As Cantidad
						,sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) as Importe
						,(sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) / @Venta_Total) * 100 as Porcentaje
     					,sum(isnull(I.cantidad * (isnull(P.Costo,0) * isnull(M.Cotizacion,0)) * t.compromete_factura,0))  as Costo
						,sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) - sum(isnull(I.cantidad * (isnull(P.Costo,0) * isnull(M.Cotizacion,0)) * t.compromete_factura,0)) as Renta
						,sum(isnull(I.Imp_Gravado,0)*(1-C.Porc_Bonificacion/100)*isnull(t.compromete_factura,0)) / isnull(sum(CASE ISNULL((isnull(P.Costo,0) * isnull(M.Cotizacion,0)),0) when 0 THEN 1 ELSE  (isnull(P.Costo,0) * isnull(M.Cotizacion,0)) END * isnull(I.cantidad,0) * t.compromete_factura),1) as Markup
--             INTO #VENTAS
		     from cbtes c, cbtes_tipos t, Cbtes_Items I, Productos P, #UN U,
			           #FAMILIAS F, #SUCURSALES S, #PROVE PR, #VENDEDORES V,Valores_Monedas M
						   where c.id_tipo_cbte  = t.id_tipo_cbte
						   AND T.Id_Unid_Negocio = u.id_Unid_Negocio
						   and I.id_Trans = C.Id_Trans
						   And c.Id_Estado_Cbte <> 3
						   AND P.Id_Producto = I.Id_Producto
						   and P.Id_Moneda_C = M.Id_Moneda
   						   And T.Compromete_Factura in (1,-1)
						   AND C.FECHA >= @pFecha_Desde 
						   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
					       And P.id_Familia = F.Id_Familia
					       And P.Id_Proveedor = PR.Id_Proveedor
						   and C.id_vendedor = V.id_vendedor
					       And T.Id_Sucursal = S.Id_Sucursal
						   AND C.ID_TIPO_CBTE NOT IN ('CFIN','DFIN')
						   group by I.Id_Producto,P.Descripcion_Detallada having Sum(I.Cantidad*T.Compromete_Factura) <> 0
						   order by Porcentaje Desc



-- SELECT * FROM #VENTAS  

 END

 DROP TABLE #UN 
 DROP TABLE #PROVE  
 DROP TABLE #FAMILIAS  
 DROP TABLE #SUCURSALES
 DROP TABLE #VENDEDORES
-- DROP TABLE #VENTAS

 /* 

