CREATE  PROCEDURE [dbo].[CP_Ventas_por_Producto_CLI]
	@pFecha_Desde			DATETIME,
	@pFecha_Hasta			DATETIME,
	@pid_producto           varchar(14),
	@id_Sucursal            INT,
	@pid_familia            INT,
	@Venta_Total            DECIMAL(20,2),
	@pid_cliente            INT
AS
SET NOCOUNT ON

/*Declaracion Variables Locales*/

DECLARE @Mensaje			VARCHAR(100)
		,@UltError			INT
		,@Id_Trans			INT
		,@Id_Cliente		INT
		,@Importe			DECIMAL(16,2)
		,@Email_Cob			VARCHAR(256)
		,@Id_Trans_Rec		INT
		,@CursorOpen        INT
		,@Flag_Cbte_Tipo	SMALLINT
		,@Periodo           DATE 
		,@Existe      	    SMALLINT


					
BEGIN 

   SELECT ID_UNID_NEGOCIO INTO #UN FROM Empresas_Unid_Negocios 
   SELECT ID_FAMILIA INTO #FAMILIAS FROM Prod_Familias 
   SELECT ID_SUCURSAL INTO #SUCURSALES FROM EMPRESAS_SUC 
   
   
   SELECT * INTO #PRODUCTOS FROM PRODUCTOS WHERE 0=1
   
   IF @pid_producto <> ''
      BEGIN
          INSERT INTO #PRODUCTOS SELECT * FROM PRODUCTOS WHERE Id_Producto = @pid_producto 
      END
     ELSE
       BEGIN
     
          SELECT DISTINCT(I.ID_PRODUCTO) AS ID_PRODUCTO 
                 INTO #PROD_ID 
                 FROM Cbtes_Items I, CBTES C 
                 WHERE C.Id_Trans = I.Id_Trans 
                   AND C.FECHA >= @pFecha_Desde 
                   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
                   AND I.Id_Producto is not null     
     
           INSERT INTO #PRODUCTOS SELECT P.* FROM PRODUCTOS P, #PROD_ID I
                  WHERE I.Id_Producto  = P.ID_PRODUCTO

        END
        
   SELECT * INTO #CLIENTES FROM CLIENTES WHERE 0=1
   
   IF @pid_CLIENTE <> 0
      BEGIN
          INSERT INTO #CLIENTES SELECT * FROM CLIENTES WHERE Id_Cliente = @pid_CLIENTE 
      END
     ELSE
       BEGIN
     
          SELECT DISTINCT(C.ID_CLIENTE) AS ID_CLIENTE
                 INTO #CLI_ID 
                 FROM Cbtes_Items I, CBTES C 
                 WHERE C.Id_Trans = I.Id_Trans 
                   AND C.FECHA >= @pFecha_Desde 
                   AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
                   AND C.Id_CLIENTE is not null     
     
           INSERT INTO #CLIENTES SELECT C.* FROM CLIENTES C, #CLI_ID I
                  WHERE I.Id_CLIENTE  = C.Id_CLIENTE
                
        END       
     
        

   IF @pid_familia <> 0
      DELETE #FAMILIAS WHERE ID_FAMILIA <> @pid_familia

   IF @id_Sucursal <> 0
      DELETE #SUCURSALES WHERE ID_SUCURSAL <> @id_Sucursal
      
      
     set @Venta_Total = (select sum(isnull(I.Imp_gravado,0)*t.compromete_factura)
					   from cbtes c
					    JOIN  cbtes_tipos t ON c.id_tipo_cbte  = t.id_tipo_cbte And T.Compromete_Factura in (1,-1)
			            JOIN  #SUCURSALES S ON T.Id_Sucursal = S.Id_Sucursal
					    JOIN  #UN U ON  T.Id_Unid_Negocio = U.Id_Unid_Negocio  
					    JOIN  Cbtes_items I ON I.Id_trans = C.id_trans
					    JOIN  #PRODUCTOS P ON I.id_Producto = P.id_Producto
					    JOIN  #FAMILIAS F ON P.id_Familia = F.Id_Familia
					    JOIN  #CLIENTES K ON C.Id_Cliente = k.Id_Cliente
					   where  C.Id_Estado_Cbte IN (1,2,4)
						   AND C.FECHA >= @pFecha_Desde 
					       AND C.FECHA < dateadd(dd,1,@pFecha_Hasta))
 
			Select I.Id_Producto as Producto,P.Descripcion_Detallada as Descripcion ,CAST(Sum(ISNULL(I.Cantidad,0)*T.Compromete_Factura) AS INT) As Cantidad
			            ,sum(isnull(i.Imp_Gravado,0)*(1-ISNULL(C.Porc_Bonificacion,0)/100)*t.compromete_factura) as Importe,
						(sum(isnull(i.Imp_Gravado,0)*(1-ISNULL(C.Porc_Bonificacion,0)/100)*t.compromete_factura) / @Venta_Total) * 100 as Porcentaje
				   from cbtes c
					    JOIN  cbtes_tipos t ON c.id_tipo_cbte  = t.id_tipo_cbte And T.Compromete_Factura in (1,-1)
			            JOIN  #SUCURSALES S ON T.Id_Sucursal = S.Id_Sucursal
					    JOIN  #UN U ON  T.Id_Unid_Negocio = U.Id_Unid_Negocio  
					    JOIN  Cbtes_items I ON I.Id_trans = C.id_trans
					    JOIN  #PRODUCTOS P ON I.id_Producto = P.id_Producto
					    JOIN  #FAMILIAS F ON P.id_Familia = F.Id_Familia
					    JOIN  #CLIENTES K ON C.Id_Cliente = k.Id_Cliente
					   where  C.Id_Estado_Cbte IN (1,2,4)
						   AND C.FECHA >= @pFecha_Desde 
					       AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
					   group by I.Id_Producto,P.Descripcion_Detallada having Sum(I.Cantidad*T.Compromete_Factura) <> 0
					   order by Porcentaje Desc



 DROP TABLE #UN
 DROP TABLE #FAMILIAS  
 DROP TABLE #SUCURSALES
 DROP TABLE #PRODUCTOS
 DROP TABLE #PROD_ID 
 DROP TABLE #CLIENTES
 DROP TABLE #CLI_ID 

END	


