CREATE PROCEDURE [dbo].[CP_xCampos_Guardar]  @pTabla			VARCHAR(50), 
											@pId			VARCHAR(100), 
											@pId_Campo		INT,
											@pValor_String	VARCHAR(101),
											@pValor_Integer INT,
											@pValor_DT		DATETIME,
											@pValor_Decimal DECIMAL(20,4),
											@pValor_Memo	TEXT,
											@pValor_Link	TEXT = NULL			/*04/05/2021 Agregado*/

AS

DECLARE @Id_Contrato		INT
DECLARE @Id_Centro_Costo	CHAR(10)
DECLARE @Id_Cliente			INT
DECLARE @Id_Producto		VARCHAR(14)
DECLARE @Id_Trans			INT
DECLARE @Id_Cliente_Temp	INT
DECLARE @MensajeFinEjec		VARCHAR(100)

BEGIN TRY

IF (ISNULL(CONVERT(VARCHAR(8000), @pValor_Link), '') <> '')
BEGIN
	SET @pValor_Memo = @pValor_Link
END

IF RTRIM(LTRIM(UPPER(@pTabla))) = 'CONTRATO' 
BEGIN
	 SET @Id_Contrato = CAST(@pId AS INT)
	 IF NOT EXISTS(SELECT 1 FROM Contratos_xCampos WHERE Id_Contrato = @Id_Contrato AND Id_Campo = @pId_Campo )
	 BEGIN
		INSERT INTO Contratos_xCampos (Id_Contrato,Id_Campo,Valor_String,Valor_Integer,Valor_DT,Valor_Decimal,Valor_Memo) 
		       VALUES (@Id_Contrato,@pId_Campo, @pValor_String,@pValor_Integer,@pValor_DT ,@pValor_Decimal,@pValor_Memo)
     END
	 ELSE
	 BEGIN
		UPDATE Contratos_xCampos 
		       SET Valor_String = @pValor_String, Valor_Integer = @pValor_Integer, 
		                    Valor_DT = @pValor_DT , Valor_Decimal = @pValor_Decimal,Valor_Memo = @pValor_Memo
		       WHERE Id_Contrato = @Id_Contrato AND Id_Campo = @pId_Campo
