		       WHERE Id_Cliente = @Id_Cliente AND Id_Campo = @pId_Campo
	 END
END


IF RTRIM(LTRIM(UPPER(@pTabla))) = 'PRODUCTO' 
BEGIN
	 SET @Id_Producto = CAST(@pId AS VARCHAR(14))
	 IF NOT EXISTS(SELECT 1 FROM Productos_XCampos WHERE Id_Producto = @Id_Producto AND Id_Campo = @pId_Campo )
	 BEGIN
