END



IF RTRIM(LTRIM(UPPER(@pTabla))) = 'CBTE' 
BEGIN
	 SET @Id_Trans = CAST(@pId AS INT)
	 IF NOT EXISTS(SELECT 1 FROM Cbtes_xCampos WHERE Id_Trans = @Id_Trans AND Id_Campo = @pId_Campo )
