		       VALUES (@Id_Trans,@pId_Campo, @pValor_String,@pValor_Integer,@pValor_DT ,@pValor_Decimal,@pValor_Memo)
     END
	 ELSE
	 BEGIN
		UPDATE Cbtes_xCampos 
		       SET Valor_String = @pValor_String, Valor_Integer = @pValor_Integer, 
		                    Valor_DT = @pValor_DT , Valor_Decimal = @pValor_Decimal,Valor_Memo = @pValor_Memo
		       WHERE Id_Trans = @Id_Trans AND Id_Campo = @pId_Campo
	 END
END



IF RTRIM(LTRIM(UPPER(@pTabla))) = 'CLIENTETEMP' 
BEGIN
	 SET @Id_Cliente_Temp = CAST(@pId AS INT)
	 IF NOT EXISTS(SELECT 1 FROM Clientes_Temp_XCampos WHERE Id_Cliente_Temp = @Id_Cliente_Temp AND Id_Campo = @pId_Campo )
	 BEGIN
		INSERT INTO Clientes_Temp_XCampos (Id_Cliente_Temp,Id_Campo,Valor_String,Valor_Integer,Valor_DT,Valor_Decimal,Valor_Memo) 
		       VALUES (@Id_Cliente_Temp,@pId_Campo, @pValor_String,@pValor_Integer,@pValor_DT ,@pValor_Decimal,@pValor_Memo)
     END
	 ELSE
