		                    Valor_DT = @pValor_DT , Valor_Decimal = @pValor_Decimal,Valor_Memo = @pValor_Memo
		       WHERE Id_Cliente_Temp = @Id_Cliente_Temp AND Id_Campo = @pId_Campo
	 END
END

SELECT 0, 0, 0, 0, @MensajeFinEjec
END TRY

BEGIN CATCH  
    -- Ejecuta la rutina de recuperaci¾n de errores
    EXECUTE usp_GetErrorInfo;  
END CATCH
GO


CREATE PROCEDURE [dbo].[CP_xVentanas_Items] @pId_Ventana VARCHAR(50), @pId_Usuario SMALLINT
AS

DECLARE @Mensaje			VARCHAR(100)
DECLARE @Existe				INT
		
CREATE TABLE #Ventana_Item (
      Id_Ventana VARCHAR(50), 	
	  Nombre VARCHAR(200), 	 	
	  Tipo SMALLINT, 	
	  Valor VARCHAR(5000) ,		
	  Ocultar TINYINT,	
	  Requerido TINYINT, 
	  Deshabilitado TINYINT, 
	  Texto VARCHAR(500) ,		
	  Flag_Agregar TINYINT, 	
	  Flag_Cambiar TINYINT,
	  Flag_Borrar TINYINT, 	
	  Flag_Ver TINYINT, 	
	  Flag_Todas TINYINT
		)

INSERT INTO  #Ventana_Item
SELECT Id_Ventana,Nombre, Tipo, Valor, Ocultar, Requerido, ISNULL(Deshabilitado,0),Texto, ISNULL(Flag_Agregar,0), 
		ISNULL(Flag_Cambiar,0), ISNULL(Flag_Borrar,0), ISNULL(Flag_Ver,0),  ISNULL(Flag_Todas,0)
		FROM xVentanas_Items
		WHERE Id_Ventana= @pId_Ventana
		AND Flag_Modif=1


DECLARE 	  @Nombre VARCHAR(200), 
			  @Tipo SMALLINT, 		
			  @Valor VARCHAR(5000) ,		
			  @Ocultar TINYINT,	
			  @Requerido TINYINT, 
			  @Deshabilitado TINYINT, 
			  @Texto VARCHAR(500) ,		
			  @Flag_Agregar TINYINT, 	
			  @Flag_Cambiar TINYINT,
			  @Flag_Borrar TINYINT, 	
			  @Flag_Ver TINYINT, 	
			  @Flag_Todas TINYINT

DECLARE curxVentanas CURSOR FOR
SELECT Nombre,Tipo, Valor, Ocultar, Requerido, Deshabilitado,Texto, Flag_Agregar, 
		Flag_Cambiar, Flag_Borrar, Flag_Ver,  Flag_Todas
		FROM xVentanas_Items_Users
		WHERE Id_Ventana=@pId_Ventana
		AND Flag_Modif=1
		AND Id_Usuario=@pId_Usuario

OPEN curxVentanas
FETCH NEXT FROM curxVentanas INTO @Nombre, @Tipo ,@Valor, @Ocultar, @Requerido, @Deshabilitado, @Texto, @Flag_Agregar, 
									@Flag_Cambiar, @Flag_Borrar, @Flag_Ver,  @Flag_Todas
WHILE @@FETCH_STATUS = 0
BEGIN

SET @Existe= ISNULL((SELECT 1 FROM #Ventana_Item WHERE Nombre=@Nombre AND Id_Ventana=@pId_Ventana),0)

IF (@Existe=1)
BEGIN
	UPDATE #Ventana_Item SET  Valor=@Valor, Tipo=@Tipo, Ocultar=@Ocultar, Requerido=@Requerido, Deshabilitado=@Deshabilitado, 
	Texto=@Texto, Flag_Agregar=@Flag_Agregar, 	Flag_Cambiar=@Flag_Cambiar , Flag_Borrar=@Flag_Borrar , Flag_Ver=@Flag_Ver, 
	Flag_Todas=@Flag_Todas	WHERE Nombre=@Nombre

END

IF (@Existe=0)
BEGIN

	INSERT INTO #Ventana_Item
	SELECT @pId_Ventana, @Nombre,@Tipo,@Valor, @Ocultar,  @Requerido, @Deshabilitado, 
	 @Texto, @Flag_Agregar,  @Flag_Cambiar , @Flag_Borrar ,  @Flag_Ver,  @Flag_Todas

END



FETCH NEXT FROM curxVentanas INTO @Nombre,@Tipo ,@Valor, @Ocultar, @Requerido, @Deshabilitado, @Texto, @Flag_Agregar, 
									@Flag_Cambiar, @Flag_Borrar, @Flag_Ver,  @Flag_Todas
END
CLOSE curxVentanas
DEALLOCATE curxVentanas


SELECT * FROM #Ventana_Item

DELETE FROM #Ventana_Item
GO




CREATE TRIGGER [dbo].[CT_Cajas_Mov_Hist_Upd] ON [dbo].[Cajas_Mov]
AFTER UPDATE
AS 
SET NOCOUNT ON
DECLARE @Id_Trans					INT
DECLARE @Renglon_Nro	    		SMALLINT
DECLARE @Flag_Grabar				INT
DECLARE @Id_Periodo_Caja     		INT
Declare @Descripcion                VARCHAR(80)
DECLARE @Id_Usuario					SMALLINT


	IF ISNUMERIC(SYSTEM_USER) = 1
		SET @Id_Usuario =  SYSTEM_USER 
      ELSE
		SET @Id_Usuario =  0


	DECLARE [Cajas_Mov_Hist_update] CURSOR FOR
	SELECT i.Id_Trans,i.Renglon_Nro,D.Id_Periodo_Caja
			FROM Inserted I, Deleted D
			WHERE I.Id_Trans = D.Id_Trans
			AND (I.Id_Periodo_Caja <> D.Id_Periodo_Caja)
	

	OPEN [Cajas_Mov_Hist_update]
	FETCH NEXT FROM [Cajas_Mov_Hist_update] INTO @Id_Trans, @Renglon_Nro, @Id_periodo_Caja
            
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		INSERT INTO Cajas_Mov_Hist	   (Id_Trans,	     	Renglon_Nro,	Id_periodo_Caja,
										Fecha,              Descripcion,    Id_Usuario)
			VALUES					   (@Id_Trans ,		    @Renglon_Nro,	@Id_periodo_Caja,
										GETDATE(),	     	@Descripcion,	@Id_Usuario)


	
		FETCH NEXT FROM [Cajas_Mov_Hist_update] INTO @Id_Trans, @Renglon_Nro, @Id_periodo_Caja
								 
	END

	CLOSE [Cajas_Mov_Hist_update]
	DEALLOCATE [Cajas_Mov_Hist_update]
GO



CREATE TRIGGER dbo.CT_Cbtes_CD_Clientes_Novedades ON dbo.Cbtes
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF ISNULL(CONVERT(INT, dbo.CF_xParam('CD_Cli_Noved_Ejecut')), 0) = 0
        RETURN;

    IF NOT (UPDATE(Id_Estado_Cbte) OR UPDATE(Saldo) OR UPDATE(Id_Tipo_Cbte))
        RETURN;

    DECLARE @Now datetime = GETDATE();

	DECLARE @TransAfectadas TABLE (
        Id_Trans INT PRIMARY KEY
    );
	
	INSERT INTO @TransAfectadas
    SELECT DISTINCT i.Id_Trans
    FROM inserted i
    JOIN deleted  d ON d.Id_Trans = i.Id_Trans
    JOIN dbo.Cbtes_Tipos ct ON ct.Id_Tipo_Cbte = i.Id_Tipo_Cbte
    WHERE ct.Compromete_Factura IN (1, -1)
      AND (
            ISNULL(i.Id_Estado_Cbte, 0) <> ISNULL(d.Id_Estado_Cbte, 0)
         OR ISNULL(i.Saldo, 0) <> ISNULL(d.Saldo, 0)
      );


    SELECT DISTINCT ci.Id_Cliente
    INTO #CliAfectados
    FROM dbo.Cbtes_Items ci
    JOIN @TransAfectadas t ON t.Id_Trans = ci.Id_Trans
    WHERE ci.Id_Cliente > 1;


    IF NOT EXISTS (SELECT 1 FROM #CliAfectados)
        RETURN;

    CREATE CLUSTERED INDEX IX_CliAfectados ON #CliAfectados(Id_Cliente);

    -- 1) Update si ya hay pendiente
    UPDATE n
       SET n.Fecha = @Now
    FROM dbo.CD_Clientes_Novedades n
    JOIN #CliAfectados c ON c.Id_Cliente = n.Id_Cliente
    WHERE n.Estado = 'P';

    -- 2) Insert si NO hay pendiente
    INSERT INTO dbo.CD_Clientes_Novedades (Id_Cliente, Fecha, Estado)
    SELECT c.Id_Cliente, @Now, 'P'
    FROM #CliAfectados c
    WHERE NOT EXISTS (
        SELECT 1
        FROM dbo.CD_Clientes_Novedades n
        WHERE n.Id_Cliente = c.Id_Cliente
          AND n.Estado = 'P'
    );
END
GO



CREATE TRIGGER dbo.CT_Cbtes_Est_Hist
ON dbo.Cbtes
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    -- 1) Si el UPDATE no toc├│ la columna, salir r├ípido
    IF NOT UPDATE(Id_Estado_Cbte)
        RETURN;

    -- 2) Evaluar par├ímetro una sola vez
    IF dbo.CF_xParam('User_Sql_Hab') <> '1'
        RETURN;

    DECLARE @Now datetime;
    SET @Now = GETDATE();

    INSERT INTO dbo.Cbtes_Estados_Hist (Id_Trans, Fecha, Id_Estado_Cbte, Id_Usuario)
    SELECT
        i.Id_Trans,
        @Now,
        d.Id_Estado_Cbte,
        CASE
            WHEN SYSTEM_USER NOT LIKE '%[^0-9]%' AND SYSTEM_USER <> '' THEN CAST(SYSTEM_USER AS int)
            ELSE 0
        END
    FROM inserted i
    JOIN deleted  d ON d.Id_Trans = i.Id_Trans
    WHERE ISNULL(i.Id_Estado_Cbte, 0) <> ISNULL(d.Id_Estado_Cbte, 0);
END
GO



CREATE TRIGGER [dbo].[CT_Cbtes_Items_CD_Clientes_Novedades] ON [dbo].[Cbtes_Items]
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @xParam INT = ISNULL(CONVERT(INT, dbo.CF_xParam('CD_Cli_Noved_Ejecut')), 0);
    IF (@xParam = 0) RETURN;

    DECLARE @Now DATETIME = GETDATE();

	DECLARE @CliAfectados TABLE (
        Id_Cliente INT PRIMARY KEY
    );



	INSERT INTO @CliAfectados
    SELECT DISTINCT
               Id_Cliente = ISNULL(I.Id_Cliente, 0)
        FROM inserted I
        JOIN dbo.Cbtes CB
          ON CB.Id_Trans = I.Id_Trans
        JOIN dbo.Cbtes_Tipos CT
          ON CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte
        WHERE CT.Compromete_Factura IN (1, -1)
          AND I.Id_Cliente > 1

    IF NOT EXISTS (SELECT 1 FROM @CliAfectados)
        RETURN;   

    -- 1) Update si ya existe pendiente
    UPDATE N
        SET N.Fecha = @Now
		FROM dbo.CD_Clientes_Novedades N
		JOIN @CliAfectados C
		  ON C.Id_Cliente = N.Id_Cliente
		WHERE N.Estado = 'P';

    -- 2) Insert para los que no tienen pendiente
    INSERT INTO dbo.CD_Clientes_Novedades (Id_Cliente, Fecha, Estado)
    SELECT C.Id_Cliente, @Now, 'P'
		FROM @CliAfectados C
		WHERE NOT EXISTS (
			SELECT 1
			FROM dbo.CD_Clientes_Novedades N
			WHERE N.Id_Cliente = C.Id_Cliente
			  AND N.Estado = 'P'
		);
END
GO




CREATE TRIGGER dbo.CT_Clientes_CD_Clientes_Novedades ON dbo.Clientes
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF ISNULL(CONVERT(int, dbo.CF_xParam('CD_Cli_Noved_Ejecut')), 0) = 0
        RETURN;

    DECLARE @Now datetime = GETDATE();
	DECLARE @CliAfectados TABLE (
        Id_Cliente INT PRIMARY KEY
    );


    --------------------------------------------------------------------
    -- INSERT: todos los clientes insertados
    --------------------------------------------------------------------
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        INSERT INTO @CliAfectados (Id_Cliente)
        SELECT DISTINCT I.Id_Cliente
        FROM inserted I;
    END
    ELSE
    BEGIN
        ----------------------------------------------------------------
        -- UPDATE: solo si tocaron columnas relevantes
        ----------------------------------------------------------------
        IF NOT (
            UPDATE(Id_Tipo_Cli) OR
            UPDATE(Activo) OR
            UPDATE(Fecha_Alta) OR
            UPDATE(Fecha_Baja) OR
            UPDATE(Id_Cliente_Ref) OR
            UPDATE(Credencial_Nro)
        )
            RETURN;

        INSERT INTO @CliAfectados (Id_Cliente)
        SELECT DISTINCT I.Id_Cliente
        FROM inserted I
        JOIN deleted  D ON D.Id_Cliente = I.Id_Cliente
        WHERE
            ISNULL(I.Id_Tipo_Cli, 0)        <> ISNULL(D.Id_Tipo_Cli, 0) OR
            ISNULL(I.Activo, 0)             <> ISNULL(D.Activo, 0) OR
            ISNULL(I.Fecha_Alta, '19000101') <> ISNULL(D.Fecha_Alta, '19000101') OR
            ISNULL(I.Fecha_Baja, '19000101') <> ISNULL(D.Fecha_Baja, '19000101') OR
            ISNULL(I.Id_Cliente_Ref, 0)     <> ISNULL(D.Id_Cliente_Ref, 0) OR
            ISNULL(I.Credencial_Nro, '')    <> ISNULL(D.Credencial_Nro, '');
    END

    IF NOT EXISTS (SELECT 1 FROM @CliAfectados)
        RETURN;

    --------------------------------------------------------------------
    -- 1) Update si ya existe pendiente
    --------------------------------------------------------------------
    UPDATE N
       SET N.Fecha = @Now
    FROM dbo.CD_Clientes_Novedades N
    JOIN @CliAfectados C ON C.Id_Cliente = N.Id_Cliente
    WHERE N.Estado = 'P';

    --------------------------------------------------------------------
    -- 2) Insert si no existe pendiente
    --------------------------------------------------------------------
    INSERT INTO dbo.CD_Clientes_Novedades (Id_Cliente, Fecha, Estado)
    SELECT C.Id_Cliente, @Now, 'P'
    FROM @CliAfectados C
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM dbo.CD_Clientes_Novedades N
        WHERE N.Id_Cliente = C.Id_Cliente
          AND N.Estado = 'P'
    );
END
GO


CREATE TRIGGER dbo.CT_Clientes_Fotos_CD_Clientes_Novedades_Ins ON dbo.Clientes_Fotos
AFTER INSERT
AS 
SET NOCOUNT ON
DECLARE @Id_Cliente					INT
DECLARE @Id_Novedad_Pendiente		INT
DECLARE @xParam_CD_Cli_Noved_Ejecut	INT

--INSERT y UPDATE estan separados los Trigger porque en Clarion mantiene todo en Memoria y luego graba todo junto.

SET @xParam_CD_Cli_Noved_Ejecut = ISNULL(CONVERT(INT, dbo.CF_xParam('CD_Cli_Noved_Ejecut')), 0)

IF (@xParam_CD_Cli_Noved_Ejecut <> 0)
BEGIN
	SET NOCOUNT ON
	DECLARE cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Ins cursor for 
	SELECT I.Id_Cliente
	FROM Inserted I

	OPEN cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Ins
	FETCH NEXT FROM cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Ins INTO @Id_Cliente
	WHILE @@FETCH_STATUS = 0
	BEGIN
	
		SET @Id_Novedad_Pendiente = ISNULL(	(SELECT MAX(Id_Novedad)
											FROM CD_Clientes_Novedades
											WHERE
											Estado = 'P'
											AND Id_Cliente = @Id_Cliente)
											, 0)
		IF(@Id_Novedad_Pendiente > 0)
		BEGIN
			UPDATE CD_Clientes_Novedades
			SET
			Fecha = GETDATE()
			WHERE
			Estado = 'P'
			AND Id_Cliente = @Id_Cliente
		END
		ELSE
		BEGIN
			INSERT INTO CD_Clientes_Novedades
			(Id_Cliente,		Fecha,		Estado)
			VALUES
			(@Id_Cliente,		GETDATE(),	'P')
		END

		FETCH NEXT FROM cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Ins INTO @Id_Cliente
	END
	CLOSE cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Ins
	DEALLOCATE cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Ins
END
GO


CREATE TRIGGER dbo.CT_Clientes_Fotos_CD_Clientes_Novedades_Upd ON dbo.Clientes_Fotos
AFTER UPDATE
AS 
SET NOCOUNT ON
DECLARE @Id_Cliente					INT
DECLARE @Id_Novedad_Pendiente		INT
DECLARE @xParam_CD_Cli_Noved_Ejecut	INT

--INSERT y UPDATE estan separados los Trigger porque en Clarion mantiene todo en Memoria y luego graba todo junto.

SET @xParam_CD_Cli_Noved_Ejecut = ISNULL(CONVERT(INT, dbo.CF_xParam('CD_Cli_Noved_Ejecut')), 0)

IF (@xParam_CD_Cli_Noved_Ejecut <> 0)
BEGIN
	SET NOCOUNT ON
	DECLARE cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Upd cursor for 
	SELECT I.Id_Cliente
	FROM Inserted I LEFT OUTER JOIN Deleted D ON I.Id_Cliente = D.Id_Cliente
	WHERE
	(ISNULL(I.Fecha, '19000101') <> ISNULL(D.Fecha, '19000101'))


	OPEN cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Upd
	FETCH NEXT FROM cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Upd INTO @Id_Cliente
	WHILE @@FETCH_STATUS = 0
	BEGIN
	
		SET @Id_Novedad_Pendiente = ISNULL(	(SELECT MAX(Id_Novedad)
											FROM CD_Clientes_Novedades
											WHERE
											Estado = 'P'
											AND Id_Cliente = @Id_Cliente)
											, 0)
		IF(@Id_Novedad_Pendiente > 0)
		BEGIN
			UPDATE CD_Clientes_Novedades
			SET
			Fecha = GETDATE()
			WHERE
			Estado = 'P'
			AND Id_Cliente = @Id_Cliente
		END
		ELSE
		BEGIN
			INSERT INTO CD_Clientes_Novedades
			(Id_Cliente,		Fecha,		Estado)
			VALUES
			(@Id_Cliente,		GETDATE(),	'P')
		END

		FETCH NEXT FROM cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Upd INTO @Id_Cliente
	END
	CLOSE cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Upd
	DEALLOCATE cur_CT_Clientes_Fotos_CD_Clientes_Novedades_Upd
END
GO



CREATE TRIGGER dbo.CT_Clientes_Hist ON dbo.Clientes
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF ISNULL(CONVERT(int, dbo.CF_xParam('Cli_Hist')), 0) = 0
        RETURN;

    DECLARE @Now datetime = GETDATE();
    DECLARE @Id_Usuario int =
        CASE WHEN ISNUMERIC(SYSTEM_USER) = 1 THEN CONVERT(int, SYSTEM_USER) ELSE 0 END;

    DECLARE @HistPendiente TABLE
    (
        Id_Cliente           int          NOT NULL PRIMARY KEY,
        Id_Tipo_Cli          smallint     ,
        Id_Cobrador          varchar(10)  COLLATE DATABASE_DEFAULT ,
        Fecha_Alta           datetime     ,
        Id_Motivo_Est        smallint     ,
        Fecha_Baja           datetime     NULL,
        Id_Cliente_Externo   varchar(14)  COLLATE DATABASE_DEFAULT ,
        Id_Tarjeta           varchar(10)  COLLATE DATABASE_DEFAULT ,
        Tar_Nro              varchar(50)  COLLATE DATABASE_DEFAULT ,
        Tar_Fecha_Alta       datetime     ,
        Tar_Fecha_Baja       datetime     ,
        Id_Cliente_Ref       int          ,
        Id_Cli_Relac         int          ,
        Activo               tinyint            
    );

    --------------------------------------------------------------------
    -- INSERT
    --------------------------------------------------------------------
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        INSERT INTO @HistPendiente
        (
            Id_Cliente, Id_Tipo_Cli, Id_Cobrador, Fecha_Alta, Id_Motivo_Est,
            Fecha_Baja, Id_Cliente_Externo, Id_Tarjeta, Tar_Nro,
            Tar_Fecha_Alta, Tar_Fecha_Baja, Id_Cliente_Ref, Id_Cli_Relac, Activo
        )
        SELECT
            i.Id_Cliente,
            ISNULL(i.Id_Tipo_Cli, 0),
            ISNULL(i.Id_Cobrador, ''),
            i.Fecha_Alta,
            ISNULL(i.Id_Motivo_Est, 0),
            i.Fecha_Baja,
            ISNULL(i.Id_Cliente_Externo, ''),
            ISNULL(i.Id_Tarjeta, ''),
            ISNULL(i.Tar_Nro, ''),
            i.Tar_Fecha_Alta,
            i.Tar_Fecha_Baja,
            ISNULL(i.Id_Cliente_Ref, 0),
            ISNULL(i.Id_Cli_Relac, 0),
            ISNULL(i.Activo, 0)
        FROM inserted i;
    END
    ELSE
    BEGIN
        ----------------------------------------------------------------
        -- UPDATE: cortar r├ípido si no tocaron campos relevantes
        ----------------------------------------------------------------
        IF NOT (
            UPDATE(Id_Tipo_Cli) OR UPDATE(Id_Cobrador) OR UPDATE(Fecha_Alta) OR UPDATE(Id_Motivo_Est) OR
            UPDATE(Fecha_Baja) OR UPDATE(Id_Cliente_Externo) OR UPDATE(Id_Tarjeta) OR UPDATE(Tar_Nro) OR
            UPDATE(Tar_Fecha_Alta) OR UPDATE(Tar_Fecha_Baja) OR UPDATE(Id_Cliente_Ref) OR UPDATE(Activo) OR UPDATE(Id_Cli_Relac)
        )
            RETURN;

        INSERT INTO @HistPendiente
        (
            Id_Cliente, Id_Tipo_Cli, Id_Cobrador, Fecha_Alta, Id_Motivo_Est,
            Fecha_Baja, Id_Cliente_Externo, Id_Tarjeta, Tar_Nro,
            Tar_Fecha_Alta, Tar_Fecha_Baja, Id_Cliente_Ref, Id_Cli_Relac, Activo
        )
        SELECT
            i.Id_Cliente,
            ISNULL(i.Id_Tipo_Cli, 0),
            ISNULL(i.Id_Cobrador, ''),
            i.Fecha_Alta,
            ISNULL(i.Id_Motivo_Est, 0),
            i.Fecha_Baja,
            ISNULL(i.Id_Cliente_Externo, ''),
            ISNULL(i.Id_Tarjeta, ''),
            ISNULL(i.Tar_Nro, ''),
            i.Tar_Fecha_Alta,
            i.Tar_Fecha_Baja,
            ISNULL(i.Id_Cliente_Ref, 0),
            ISNULL(i.Id_Cli_Relac, 0),
            ISNULL(i.Activo, 0)
        FROM inserted i
        JOIN deleted d
          ON d.Id_Cliente = i.Id_Cliente
        WHERE
               ISNULL(i.Id_Tipo_Cli, 0) <> ISNULL(d.Id_Tipo_Cli, 0)
            OR ISNULL(i.Id_Cobrador, '') COLLATE DATABASE_DEFAULT
               <> ISNULL(d.Id_Cobrador, '') COLLATE DATABASE_DEFAULT
            OR ISNULL(i.Id_Motivo_Est, 0) <> ISNULL(d.Id_Motivo_Est, 0)
            OR ISNULL(i.Id_Cliente_Externo, '') COLLATE DATABASE_DEFAULT
               <> ISNULL(d.Id_Cliente_Externo, '') COLLATE DATABASE_DEFAULT
            OR ISNULL(i.Id_Tarjeta, '') COLLATE DATABASE_DEFAULT
               <> ISNULL(d.Id_Tarjeta, '') COLLATE DATABASE_DEFAULT
            OR ISNULL(i.Tar_Nro, '') COLLATE DATABASE_DEFAULT
               <> ISNULL(d.Tar_Nro, '') COLLATE DATABASE_DEFAULT
            OR ISNULL(i.Id_Cliente_Ref, 0) <> ISNULL(d.Id_Cliente_Ref, 0)
            OR ISNULL(i.Id_Cli_Relac, 0) <> ISNULL(d.Id_Cli_Relac, 0)
            OR ISNULL(i.Activo, 0) <> ISNULL(d.Activo, 0)
            OR ISNULL(i.Fecha_Alta, '19000101') <> ISNULL(d.Fecha_Alta, '19000101')
            OR ISNULL(i.Fecha_Baja, '19000101') <> ISNULL(d.Fecha_Baja, '19000101')
            OR ISNULL(i.Tar_Fecha_Alta, '19000101') <> ISNULL(d.Tar_Fecha_Alta, '19000101')
            OR ISNULL(i.Tar_Fecha_Baja, '19000101') <> ISNULL(d.Tar_Fecha_Baja, '19000101');
    END

    IF NOT EXISTS (SELECT 1 FROM @HistPendiente)
        RETURN;

    ;WITH P AS
    (
        SELECT
            h.*,
            RN = ROW_NUMBER() OVER (PARTITION BY h.Id_Cliente ORDER BY h.Id_Cliente)
        FROM @HistPendiente h
    ),
    M AS
    (
        SELECT
            ch.Id_Cliente,
            MaxItem = ISNULL(MAX(ch.Item), 0)
        FROM dbo.Clientes_Hist ch
        JOIN (SELECT DISTINCT Id_Cliente FROM @HistPendiente) x
          ON x.Id_Cliente = ch.Id_Cliente
        GROUP BY ch.Id_Cliente
    )
    INSERT INTO dbo.Clientes_Hist
    (
        Id_Cliente, Item, Fecha,
        Id_Tipo_Cli, Id_Cobrador, Fecha_Alta,
        Id_Motivo_Est, Fecha_Baja, Id_Cliente_Externo,
        Id_Tarjeta, Tar_Nro, Tar_Fecha_Alta,
        Tar_Fecha_Baja, Id_Cliente_Ref, Id_Usuario,
        Id_Cli_Relac, Activo
    )
    SELECT
        P.Id_Cliente,
        ISNULL(M.MaxItem, 0) + P.RN,
        @Now,
        P.Id_Tipo_Cli, P.Id_Cobrador, P.Fecha_Alta,
        P.Id_Motivo_Est, P.Fecha_Baja, P.Id_Cliente_Externo,
        P.Id_Tarjeta, P.Tar_Nro, P.Tar_Fecha_Alta,
        P.Tar_Fecha_Baja, P.Id_Cliente_Ref, @Id_Usuario,
        P.Id_Cli_Relac, P.Activo
    FROM P
    LEFT JOIN M
      ON M.Id_Cliente = P.Id_Cliente;
END
GO



CREATE TRIGGER [dbo].[CT_Clientes_Hist_Ins] 
ON [dbo].[Clientes]
AFTER INSERT
AS 

SET NOCOUNT ON
DECLARE @Id_Cliente		INT
DECLARE @Id_Tipo_Cli	SMALLINT
DECLARE @Id_Cobrador	VARCHAR(10)
DECLARE @Fecha_Alta		DATETIME
DECLARE @Id_Motivo_Est	SMALLINT
DECLARE @Fecha_Baja		DATETIME
DECLARE @Id_Cliente_Externo VARCHAR(14)
DECLARE @Id_Tarjeta		VARCHAR(10)
DECLARE @Tar_Nro		VARCHAR(25)
DECLARE @Tar_Fecha_Alta DATETIME
DECLARE @Tar_Fecha_Baja DATETIME
DECLARE @Id_Cliente_Ref	INT
DECLARE @ProxItem		SMALLINT
DECLARE @Flag_Grabar	INT
DECLARE @Id_Usuario		SMALLINT
DECLARE @Id_Cli_Relac	SMALLINT
DECLARE @Activo			TINYINT

SET @Flag_Grabar =  dbo.CF_xParam('Cli_Hist')

	
IF(ISNULL(@Flag_Grabar,0) <> 0)
BEGIN

	IF ISNUMERIC(SYSTEM_USER) = 1
		SET @Id_Usuario =  SYSTEM_USER 
    ELSE
		SET @Id_Usuario =  0


	DECLARE clientes_hist CURSOR FOR
	SELECT	Id_Cliente,						ISNULL(Id_Tipo_Cli, 0),		ISNULL(Id_Cobrador, ''),
			Fecha_Alta,						ISNULL(Id_Motivo_Est, 0),	Fecha_Baja,
			ISNULL(Id_Cliente_Externo, ''),	ISNULL(Id_Tarjeta, ''),		ISNULL(Tar_Nro, ''),
			Tar_Fecha_Alta,					Tar_Fecha_Baja,				ISNULL(Id_Cliente_Ref, 0),
			ISNULL(Id_Cli_Relac,0),ISNULL(Activo,0)
			FROM Inserted

	OPEN clientes_hist
	FETCH NEXT FROM clientes_hist INTO @Id_Cliente, @Id_Tipo_Cli, @Id_Cobrador, @Fecha_Alta, @Id_Motivo_Est
	        , @Fecha_Baja, @Id_Cliente_Externo, @Id_Tarjeta, @Tar_Nro
			, @Tar_Fecha_Alta, @Tar_Fecha_Baja, @Id_Cliente_Ref,@Id_Cli_Relac,@Activo
	WHILE (@@FETCH_STATUS = 0)
	BEGIN
		SET @ProxItem = (SELECT (ISNULL(MAX(Item), 0) + 1) FROM Clientes_Hist WHERE Id_Cliente = @Id_Cliente)
        
		INSERT INTO Clientes_Hist	(Id_Cliente,		Item,			Fecha,
									Id_Tipo_Cli,		Id_Cobrador,	Fecha_Alta,
									Id_Motivo_Est,		Fecha_Baja,		Id_Cliente_Externo,
									Id_Tarjeta,			Tar_Nro,		Tar_Fecha_Alta,
									Tar_Fecha_Baja,		Id_Cliente_Ref	,Id_Usuario,
									Id_Cli_Relac,		Activo)
		VALUES						(@Id_Cliente,		@ProxItem,		GETDATE(),
									@Id_Tipo_Cli,		@Id_Cobrador,	@Fecha_Alta,
									@Id_Motivo_Est,		@Fecha_Baja,	@Id_Cliente_Externo,
									@Id_Tarjeta,		@Tar_Nro,		@Tar_Fecha_Alta,
									@Tar_Fecha_Baja,	@Id_Cliente_Ref,@Id_Usuario,
									@Id_Cli_Relac,		@Activo)
		

		FETCH NEXT FROM clientes_hist INTO @Id_Cliente, @Id_Tipo_Cli, @Id_Cobrador, @Fecha_Alta, @Id_Motivo_Est
	        , @Fecha_Baja, @Id_Cliente_Externo, @Id_Tarjeta, @Tar_Nro
			, @Tar_Fecha_Alta, @Tar_Fecha_Baja, @Id_Cliente_Ref,@Id_Cli_Relac,@Activo	
	END
	CLOSE clientes_hist
	DEALLOCATE clientes_hist
END
GO




CREATE TRIGGER [dbo].[CT_Clientes_Hist_Upd] ON [dbo].[Clientes]
AFTER UPDATE
AS 
SET NOCOUNT ON
DECLARE @Id_Cliente					INT
DECLARE @Id_Tipo_Cli				SMALLINT
DECLARE @Id_Cobrador				VARCHAR(10)
DECLARE @Fecha_Alta					DATETIME
DECLARE @Id_Motivo_Est				SMALLINT
DECLARE @Fecha_Baja					DATETIME
DECLARE @Id_Cliente_Externo			VARCHAR(14)
DECLARE @Id_Tarjeta					VARCHAR(10)
DECLARE @Tar_Nro					VARCHAR(25)
DECLARE @Tar_Fecha_Alta				DATETIME
DECLARE @Tar_Fecha_Baja				DATETIME
DECLARE @Id_Cliente_Ref				INT
DECLARE @UltimoItem					SMALLINT
DECLARE @Flag_Grabar				INT
DECLARE @Id_Usuario					SMALLINT
DECLARE @Id_Cli_Relac				SMALLINT

SET @Flag_Grabar =  dbo.CF_xParam('Cli_Hist')
IF(ISNULL(@Flag_Grabar,0) <> 0)
BEGIN
	IF ISNUMERIC(SYSTEM_USER) = 1
		SET @Id_Usuario =  SYSTEM_USER 
    ELSE
		SET @Id_Usuario =  0

	DECLARE clientes_hist_update CURSOR FOR
	SELECT	I.Id_Cliente,						ISNULL(I.Id_Tipo_Cli, 0),		ISNULL(I.Id_Cobrador, ''),
			I.Fecha_Alta,						ISNULL(I.Id_Motivo_Est, 0),	I.Fecha_Baja,
			ISNULL(I.Id_Cliente_Externo, ''),	ISNULL(I.Id_Tarjeta, ''),		ISNULL(I.Tar_Nro, ''),
			I.Tar_Fecha_Alta,					I.Tar_Fecha_Baja,				ISNULL(I.Id_Cliente_Ref, 0),
			I.Id_Cli_Relac
			FROM Inserted I, Deleted D
			WHERE I.Id_Cliente = D.Id_Cliente
			AND (
				(I.Id_Tipo_Cli <> D.Id_Tipo_Cli) OR
				(I.Id_Cobrador <> D.Id_Cobrador) OR
				(ISNULL(I.Fecha_Alta, '19000101') <> ISNULL(D.Fecha_Alta, '19000101')) OR 
				(I.Id_Motivo_Est <> D.Id_Motivo_Est) OR
				(ISNULL(I.Fecha_Baja, '19000101') <> ISNULL(D.Fecha_Baja, '19000101')) OR		
				(I.Id_Cliente_Externo <> D.Id_Cliente_Externo) OR				
				(I.Id_Tarjeta  <> D.Id_Tarjeta) OR				
				(I.Tar_Nro <> D.Tar_Nro) OR
				(ISNULL(I.Tar_Fecha_Alta, '19000101') <> ISNULL(D.Tar_Fecha_Alta, '19000101')) OR
				(ISNULL(I.Tar_Fecha_Baja, '19000101') <> ISNULL(D.Tar_Fecha_Baja, '19000101')) OR
				(I.Id_Cliente_Ref <> D.Id_Cliente_Ref) OR
				(I.Activo <> D.Activo) OR
				(I.Id_Cli_Relac <> D.Id_Cli_Relac)
			)


	OPEN clientes_hist_update
	FETCH NEXT FROM clientes_hist_update 
								INTO @Id_Cliente, @Id_Tipo_Cli, @Id_Cobrador, @Fecha_Alta, @Id_Motivo_Est, @Fecha_Baja, 
								@Id_Cliente_Externo, @Id_Tarjeta, @Tar_Nro, @Tar_Fecha_Alta, @Tar_Fecha_Baja, @Id_Cliente_Ref,@Id_Cli_Relac

	WHILE (@@FETCH_STATUS = 0)
	BEGIN

   
		SET @UltimoItem = ISNULL((SELECT ISNULL(MAX(Item), 0) FROM Clientes_Hist WHERE Id_Cliente = @Id_Cliente),0) + 1
	
		INSERT INTO Clientes_Hist	(Id_Cliente,		Item,			Fecha,
										Id_Tipo_Cli,		Id_Cobrador,	Fecha_Alta,
										Id_Motivo_Est,		Fecha_Baja,		Id_Cliente_Externo,
										Id_Tarjeta,			Tar_Nro,		Tar_Fecha_Alta,
										Tar_Fecha_Baja,		Id_Cliente_Ref, Id_Usuario,
										Id_Cli_Relac)
			VALUES						(@Id_Cliente,		@UltimoItem,		GETDATE(),
										@Id_Tipo_Cli,		@Id_Cobrador,	@Fecha_Alta,
										@Id_Motivo_Est,		@Fecha_Baja,	@Id_Cliente_Externo,
										@Id_Tarjeta,		@Tar_Nro,		@Tar_Fecha_Alta,
										@Tar_Fecha_Baja,	@Id_Cliente_Ref,@Id_Usuario,
										@Id_Cli_Relac)
	
		FETCH NEXT FROM clientes_hist_update 
								INTO @Id_Cliente, @Id_Tipo_Cli, @Id_Cobrador, @Fecha_Alta, @Id_Motivo_Est, @Fecha_Baja, 
								@Id_Cliente_Externo, @Id_Tarjeta, @Tar_Nro, @Tar_Fecha_Alta, @Tar_Fecha_Baja, @Id_Cliente_Ref,@Id_Cli_Relac
	END

	CLOSE clientes_hist_update
	DEALLOCATE clientes_hist_update
END
GO



