CREATE TRIGGER dbo.CT_Contratos_CD_Clientes_Novedades
ON dbo.Contratos
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF ISNULL(CONVERT(int, dbo.CF_xParam('CD_Cli_Noved_Ejecut')), 0) = 0
        RETURN;

    DECLARE @Now datetime = GETDATE();
	DECLARE @CliAfectados TABLE (
        Id_Cliente INT PRIMARY KEY
    );



    --------------------------------------------------------------------
    -- INSERT
    --------------------------------------------------------------------
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        INSERT INTO @CliAfectados (Id_Cliente)
        SELECT DISTINCT I.Id_Cliente
        FROM inserted I
        WHERE I.Id_Cliente IS NOT NULL
          AND I.Id_Cliente > 0;
    END
    ELSE
    BEGIN
        ----------------------------------------------------------------
        -- UPDATE: salir rßpido si no tocaron campos relevantes
        ----------------------------------------------------------------
        IF NOT (
            UPDATE(Activo) OR
            UPDATE(Fecha_Alta) OR
            UPDATE(Fecha_Baja) OR
            UPDATE(Fecha_Desde) OR
            UPDATE(Fecha_Hasta)
        )
            RETURN;

        INSERT INTO @CliAfectados (Id_Cliente)
        SELECT DISTINCT I.Id_Cliente
        FROM inserted I
        JOIN deleted  D ON D.Id_Contrato = I.Id_Contrato
        WHERE I.Id_Cliente IS NOT NULL
          AND I.Id_Cliente > 0
          AND (
                ISNULL(I.Activo, 0) <> ISNULL(D.Activo, 0)
             OR ISNULL(I.Fecha_Alta,  '19000101') <> ISNULL(D.Fecha_Alta,  '19000101')
             OR ISNULL(I.Fecha_Baja,  '19000101') <> ISNULL(D.Fecha_Baja,  '19000101')
             OR ISNULL(I.Fecha_Desde, '19000101') <> ISNULL(D.Fecha_Desde, '19000101')
             OR ISNULL(I.Fecha_Hasta, '19000101') <> ISNULL(D.Fecha_Hasta, '19000101')
          );
    END

    IF NOT EXISTS (SELECT 1 FROM @CliAfectados)
        RETURN;

    --------------------------------------------------------------------
    -- 1) Actualizar novedad pendiente existente
    --------------------------------------------------------------------
    UPDATE N
       SET N.Fecha = @Now
    FROM dbo.CD_Clientes_Novedades N
    JOIN @CliAfectados C
      ON C.Id_Cliente = N.Id_Cliente
    WHERE N.Estado = 'P';

    --------------------------------------------------------------------
    -- 2) Insertar novedad pendiente si no existe
    --------------------------------------------------------------------
    INSERT INTO dbo.CD_Clientes_Novedades (Id_Cliente, Fecha, Estado)
    SELECT C.Id_Cliente, @Now, 'P'
    FROM @CliAfectados C
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM dbo.CD_Clientes_Novedades N
        WHERE N.Id_Cliente = C.Id_Cliente
          AND N.Estado = 'P'
    );
END
GO



CREATE TRIGGER [dbo].[CT_Contratos_Hist] ON [dbo].[Contratos]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Now DATETIME = GETDATE();
    DECLARE @Id_Usuario INT = CASE WHEN ISNUMERIC(SYSTEM_USER) = 1 THEN CONVERT(INT, SYSTEM_USER) ELSE 0 END;

    --------------------------------------------------------------------
    -- Pendientes
    --------------------------------------------------------------------
    DECLARE @Pendientes TABLE
    (
        Id_Contrato INT NOT NULL PRIMARY KEY,
        Id_Cliente  INT ,
        Id_Tarjeta  VARCHAR(10) COLLATE DATABASE_DEFAULT,
        Tar_Nro     VARCHAR(50) COLLATE DATABASE_DEFAULT
    );

    --------------------------------------------------------------------
    -- INSERT: todos los contratos insertados
    --------------------------------------------------------------------
    IF NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        INSERT INTO @Pendientes (Id_Contrato, Id_Cliente, Id_Tarjeta, Tar_Nro)
        SELECT
            I.Id_Contrato,
            ISNULL(I.Id_Cliente, 0),
            ISNULL(I.Id_Tarjeta, ''),
            ISNULL(I.Tar_Nro, '')
        FROM inserted I
        WHERE ISNULL(I.Id_Cliente, 0) > 1;
    END
    ELSE
    BEGIN
        ----------------------------------------------------------------
        -- UPDATE: salir r├ípido si no tocaron campos relevantes
        ----------------------------------------------------------------
        IF NOT (
            UPDATE(Id_Cliente) OR
            UPDATE(Id_Tarjeta) OR
            UPDATE(Tar_Nro)
        )
            RETURN;

        INSERT INTO @Pendientes (Id_Contrato, Id_Cliente, Id_Tarjeta, Tar_Nro)
        SELECT
            I.Id_Contrato,
            ISNULL(I.Id_Cliente, 0),
            ISNULL(I.Id_Tarjeta, ''),
            ISNULL(I.Tar_Nro, '')
        FROM inserted I
        INNER JOIN deleted D
            ON D.Id_Contrato = I.Id_Contrato
        WHERE
               ISNULL(I.Id_Cliente, 0) <> ISNULL(D.Id_Cliente, 0)
            OR ISNULL(I.Id_Tarjeta, '') COLLATE DATABASE_DEFAULT
               <> ISNULL(D.Id_Tarjeta, '') COLLATE DATABASE_DEFAULT
            OR ISNULL(I.Tar_Nro, '') COLLATE DATABASE_DEFAULT
               <> ISNULL(D.Tar_Nro, '') COLLATE DATABASE_DEFAULT;

        DELETE FROM @Pendientes
        WHERE Id_Cliente <= 1;
    END

    IF NOT EXISTS (SELECT 1 FROM @Pendientes)
        RETURN;

    --------------------------------------------------------------------
    -- Trabajo
    --------------------------------------------------------------------
    DECLARE @Trabajo TABLE
    (
        Id_Contrato      INT NOT NULL PRIMARY KEY,
        Id_Cliente       INT ,
        Id_Tarjeta       VARCHAR(10) COLLATE DATABASE_DEFAULT ,
        Tar_Nro          VARCHAR(50) COLLATE DATABASE_DEFAULT ,
        Item_Ant         INT ,
        Id_Tarjeta_Ant   VARCHAR(10) COLLATE DATABASE_DEFAULT ,
        Tar_Nro_Ant      VARCHAR(50) COLLATE DATABASE_DEFAULT ,
        MaxItemCliente   INT ,
        DebeInsertar     BIT 
    );

    ;WITH MaxItem AS
    (
        SELECT
            CH.Id_Cliente,
            MaxItemCliente = ISNULL(MAX(CH.Item), 0)
        FROM dbo.Clientes_Hist CH
        INNER JOIN (SELECT DISTINCT Id_Cliente FROM @Pendientes) X
            ON X.Id_Cliente = CH.Id_Cliente
        GROUP BY CH.Id_Cliente
    )
    INSERT INTO @Trabajo
    (
        Id_Contrato, Id_Cliente, Id_Tarjeta, Tar_Nro,
        Item_Ant, Id_Tarjeta_Ant, Tar_Nro_Ant,
        MaxItemCliente, DebeInsertar
    )
    SELECT
        P.Id_Contrato,
        P.Id_Cliente,
        P.Id_Tarjeta,
        P.Tar_Nro,
        Item_Ant       = ISNULL(H.Item, 0),
        Id_Tarjeta_Ant = ISNULL(H.Id_Tarjeta COLLATE DATABASE_DEFAULT, ''),
        Tar_Nro_Ant    = ISNULL(H.Tar_Nro COLLATE DATABASE_DEFAULT, ''),
        MaxItemCliente = ISNULL(M.MaxItemCliente, 0),
        DebeInsertar =
            CASE
                WHEN H.Item IS NULL THEN 1
                WHEN ISNULL(H.Id_Tarjeta COLLATE DATABASE_DEFAULT, '') <> P.Id_Tarjeta
                  OR ISNULL(H.Tar_Nro COLLATE DATABASE_DEFAULT, '')    <> P.Tar_Nro
                THEN 1
                ELSE 0
            END
    FROM @Pendientes P
    OUTER APPLY
    (
        SELECT TOP (1)
            H.Item,
            H.Id_Tarjeta,
            H.Tar_Nro
        FROM dbo.Clientes_Hist H
        WHERE H.Id_Cliente = P.Id_Cliente
          AND H.Id_Contrato = P.Id_Contrato
        ORDER BY H.Item DESC
    ) H
    LEFT JOIN MaxItem M
        ON M.Id_Cliente = P.Id_Cliente;

    --------------------------------------------------------------------
    -- Insertar nuevos registros de historial
    --------------------------------------------------------------------
    ;WITH ParaInsertar AS
    (
        SELECT
            T.*,
            RN = ROW_NUMBER() OVER
                 (
                    PARTITION BY T.Id_Cliente
                    ORDER BY T.Id_Contrato
                 )
        FROM @Trabajo T
        WHERE T.DebeInsertar = 1
    )
    INSERT INTO dbo.Clientes_Hist
    (
        Id_Cliente,         Item,            Fecha,
        Id_Tipo_Cli,        Id_Cobrador,     Fecha_Alta,
        Id_Motivo_Est,      Fecha_Baja,      Id_Usuario,
        Id_Cliente_Externo, Id_Tarjeta,      Tar_Nro,
        Tar_Fecha_Alta,     Tar_Fecha_Baja,  Id_Cliente_Ref,
        Id_Contrato
    )
    SELECT
        C.Id_Cliente,
        Item = P.MaxItemCliente + P.RN,
        @Now,
        C.Id_Tipo_Cli,
        C.Id_Cobrador,
        C.Fecha_Alta,
        C.Id_Motivo_Est,
        C.Fecha_Baja,
        @Id_Usuario,
        C.Id_Cliente_Externo,
        P.Id_Tarjeta,
        P.Tar_Nro,
        @Now,
        NULL,
        C.Id_Cliente_Ref,
        P.Id_Contrato
    FROM ParaInsertar P
    INNER JOIN dbo.Clientes C
        ON C.Id_Cliente = P.Id_Cliente;

    --------------------------------------------------------------------
    -- Cerrar el registro anterior cuando hubo cambio de tarjeta/nro
    --------------------------------------------------------------------
    UPDATE H
       SET H.Tar_Fecha_Baja = @Now
    FROM dbo.Clientes_Hist H
    INNER JOIN @Trabajo T
        ON T.Id_Cliente = H.Id_Cliente
       AND T.Item_Ant   = H.Item
    WHERE T.DebeInsertar = 1
      AND T.Item_Ant > 0
      AND (
             T.Id_Tarjeta_Ant <> T.Id_Tarjeta
          OR T.Tar_Nro_Ant    <> T.Tar_Nro
      );
END
GO



CREATE FUNCTION [dbo].[Contrato_Fraccionar_Precio](@pId_Contrato INT, @pPrecio DECIMAL(16,5), @pFecha DATETIME) 
RETURNS DECIMAL(16,5)
AS 

BEGIN

DECLARE @Retorno			DECIMAL(16,5)
DECLARE @Flag_Fracciona		CHAR(1)
DECLARE @Fecha_Hasta		DATETIME
DECLARE @Fecha_Desde		DATETIME
DECLARE @Fin_Mes			DATETIME
DECLARE @Dia_Fin_Mes		SMALLINT
DECLARE @Semana				SMALLINT
DECLARE @Dia				SMALLINT


SET		@Retorno = @pPrecio


SELECT	@Flag_Fracciona = ISNULL(T.Flag_Fracciona,'')
		,@Fecha_Hasta = C.Fecha_Hasta
		,@Fecha_Desde = C.Fecha_Desde
		FROM Contratos C, Contratos_Tipos T 
		WHERE C.Id_Tipo_Con = T.Id_Tipo_Con AND C.Id_Contrato = @pId_Contrato

IF @Flag_Fracciona =''
BEGIN
	RETURN @retorno
END

IF DATEPART(mm,@pFecha) =  DATEPART(mm,@Fecha_Hasta) AND DATEPART(yy,@pFecha) = DATEPART(yy,@Fecha_Hasta) --fracciono Mismo MES
	BEGIN
		
		IF UPPER(@Flag_Fracciona) = 'S'                   --fracciono por semana
		SET @Dia=(DATEPART(dd,@fecha_hasta) - DATEPART(dd,@Fecha_Desde))
		BEGIN
			IF @Dia <= 7				SET @Semana = 1
			IF @Dia BETWEEN 8 AND 14	SET @Semana = 2
			IF @Dia BETWEEN 15 AND 21	SET @Semana = 3
			IF @Dia >= 22			    SET @Semana = 4
			SET @Retorno	= @Retorno / 4 * @Semana         
		END
	END
	ELSE
	BEGIN 
      IF UPPER(@Flag_Fracciona) IN ('D','S') 
      BEGIN
          SET @Fin_Mes = dbo.CF_EOMONTH(@pFecha)
	      SET @Dia_Fin_Mes = DATEPART(dd,@Fin_Mes)  --28,29,30,31
	
	      IF DATEPART(mm,@pFecha) =  DATEPART(mm,@Fecha_Hasta) AND DATEPART(yy,@pFecha) = DATEPART(yy,@Fecha_Hasta) --fraciono por fin de contrato
	      BEGIN
	      	SET @Dia = DATEPART(dd,@Fecha_Hasta)
		      IF UPPER(@Flag_Fracciona) = 'S'                   --fracciono por semana
		      BEGIN
		      	IF @Dia <= 7				SET @Semana = 1
		      	IF @Dia BETWEEN 8 AND 14	SET @Semana = 2
			    IF @Dia BETWEEN 15 AND 21	SET @Semana = 3
			    IF @Dia >= 22			    SET @Semana = 4
			    SET @Retorno	= @Retorno / 4 * @Semana         
      		END

      		IF UPPER(@Flag_Fracciona) = 'D'                   -- fracciono por dia
		      BEGIN
		      	SET @Retorno	= @Retorno *  @Dia / @Dia_Fin_Mes
	      	END
	      END
	      ELSE    -- Si no entro por finde del contrato verifico el inicio.
	      BEGIN
	      	IF  DATEPART(mm,@pFecha) =  DATEPART(mm,@Fecha_Desde) AND DATEPART(yy,@pFecha) = DATEPART(yy,@Fecha_Desde)
		      BEGIN
		      	SET @Dia = DATEPART(dd,@Fecha_Desde)
		      	IF UPPER(@Flag_Fracciona) = 'S'                       --fracciono por semana
		      	BEGIN
		      		IF @Dia <= 7				SET @Semana = 4
		      		IF @Dia BETWEEN 8 AND 14	SET @Semana = 3
			      	IF @Dia BETWEEN 15 AND 21	SET @Semana = 2
				    IF @Dia >= 22			    SET @Semana = 1
			      	SET @Retorno	= @Retorno / 4 * @Semana         
															 
			      END
			      IF UPPER(@Flag_Fracciona) = 'D'                        -- fracciono por dia
			      BEGIN
			      	SET @Retorno	= @Retorno *  (@Dia_Fin_Mes - @Dia) / @Dia_Fin_Mes
		      	END
		      END
	      END
        END
      END			
RETURN ISNULL(@Retorno,0)
END
GO

CREATE FUNCTION [dbo].[CortarCadena](@cadena nvarchar(4000), @separador char(1))
RETURNS @RtnValue table 
(
	Id int identity(1,1),
	Data nvarchar(100)
) 
AS  
BEGIN 
	Declare @Cnt int
	Set @Cnt = 1

	While (Charindex(@separador,@cadena)>0)
	Begin
		Insert Into @RtnValue (data)
		Select 
			Data = ltrim(rtrim(Substring(@cadena,1,Charindex(@separador,@cadena)-1)))

		Set @cadena = Substring(@cadena,Charindex(@separador,@cadena)+1,len(@cadena))
		Set @Cnt = @Cnt + 1
	End
	
	Insert Into @RtnValue (data)
	Select Data = ltrim(rtrim(@cadena))

	Return
END
GO

create procedure Generar_CbteUCP
as
declare @Id_Cliente		INT, 
@Id_Producto	CHAR(14),
@Importe		DECIMAL(12,2), 
@Fecha			DATETIME, 
@Id_Tipo_Cbte	CHAR(4),
@Lote			CHAR(14),
@Id_Estado_Cbte INT,
@Id_Cond_Vta	CHAR(10),
@Cant			INT,
@Id_Cond_Pago	SMALLINT

declare  cur_ucp cursor for
select c.id_cliente, 'CS',dbo.SF_CS_Precio(c.Id_Cliente,getdate()),
        convert(date,c.Ult_Cuota_Paga),
       'CUPA','A-UCP',2,'',1,1
from clientes c, clientes_tipos t,Clientes_Estados e
where activo = 1
and Ult_Cuota_Paga is not null
and t.Id_Tipo_Cli = c.Id_Tipo_Cli 
and e.Id_Estado_Cliente = c.Id_Estado_Cliente
and c.Id_Cliente_Ref = 0
and dbo.SF_CS_Precio(c.Id_Cliente,getdate()) <> 0

open cur_ucp
fetch next from cur_ucp into 
								@Id_Cliente		, 
								@Id_Producto	,
								@Importe		,
								@Fecha			,
								@Id_Tipo_Cbte	,
								@Lote			,
								@Id_Estado_Cbte ,
								@Id_Cond_Vta	,
								@Cant			,
								@Id_Cond_Pago	


while @@FETCH_STATUS=0
begin
	exec [dbo].[sp_generar_cbte]    @Id_Cliente		, 
									@Id_Producto	,
									@Importe		,
									@Fecha			,
									@Id_Tipo_Cbte	,
									@Lote			,
									@Id_Estado_Cbte ,
									@Id_Cond_Vta	,
									@Cant			,
									@Id_Cond_Pago	


	fetch next from cur_ucp into 
									@Id_Cliente	    , 
									@Id_Producto	,
									@Importe		,
									@Fecha			,
									@Id_Tipo_Cbte	,
									@Lote			,
									@Id_Estado_Cbte ,
									@Id_Cond_Vta	,
									@Cant			,
									@Id_Cond_Pago	

end
close cur_ucp
deallocate cur_ucp
GO


CREATE FUNCTION [dbo].[SF_ActivXCateg_Precio](@Id_Cliente INT, @Fecha DATETIME)
RETURNS DECIMAL(12,2)
AS
BEGIN
DECLARE @Retorno			DECIMAL(12,2)
DECLARE @Prod				CHAR(14)
DECLARE @Actividad			VARCHAR(9)
DECLARE @Id_Tipo_Cli		INT
DECLARE @Id_ContratoActiv	INT
DECLARE @Id_ContratoBeca	INT
DECLARE @Porc_Bonif_Beca	DECIMAL(5,2)

SET @Id_Tipo_Cli = (SELECT dbo.SF_Categ(@Id_Cliente, @Fecha))

/*Busca el mayor contrato de Actividad vigente en la fecha dada*/
SET @Id_ContratoActiv = ISNULL((SELECT MAX(Id_Contrato) FROM Contratos WHERE Id_Cliente = @Id_Cliente AND Id_Tipo_Con = 3 /*Actividades*/ AND (Fecha_Baja IS NULL OR Fecha_Baja>=@Fecha) AND (Fecha_Hasta IS NULL OR Fecha_Hasta>=@Fecha)  AND (Fecha_Desde<=@Fecha)), 0)

/*Si no hay ningun contrato de actividad en la fecha devuelve 0*/
IF(@Id_ContratoActiv = 0)
BEGIN
	SET @Retorno = 0
	RETURN @Retorno /*Se va de la funci{on, no continua*/
END

/*El producto deberia ser alguno de los siguientes: HANCAB - HANDAM - HANDAP - HOCCAB - HOCDAM - GIMCAB - EQUNAT*/
SET @Actividad = ISNULL((SELECT MAX(Id_Producto) FROM Contratos_Prod WHERE Id_Contrato=@Id_ContratoActiv),'')

/*A la descripcion del producto se le concatena la categoria, Ej. HANCAB8*/
SET @Prod = @Actividad + CONVERT(VARCHAR(3), @Id_Tipo_Cli)

SET @Retorno = ISNULL((SELECT Precio_Gravado FROM Productos WHERE Id_Producto = @Prod),0)

/*Busca el mayor contrato de Actividad vigente en la fecha dada*/
SET @Id_ContratoBeca = ISNULL((SELECT MAX(Id_Contrato) FROM Contratos WHERE Id_Cliente = @Id_Cliente AND Id_Tipo_Con = 4 /*Becas*/ AND (Fecha_Baja IS NULL OR Fecha_Baja>=@Fecha) AND (Fecha_Hasta IS NULL OR Fecha_Hasta>=@Fecha) AND (Fecha_Desde<=@Fecha)), 0)

/*Si tiene contrato de beca debe aplicar el descuento al precio*/
IF (@Id_ContratoBeca <> 0)
BEGIN
	SET @Porc_Bonif_Beca = ISNULL((SELECT Porc_Bonif FROM Contratos WHERE Id_Contrato=@Id_ContratoBeca),0)
	SET @Retorno = (@Retorno * (100 - @Porc_Bonif_Beca))/100
END

RETURN @Retorno
END
GO


