CREATE  FUNCTION [dbo].[SF_BancoMacro_TX](@trans INT) 
RETURNS CHAR(220)
AS
BEGIN

DECLARE @Retorno			CHAR(220)
DECLARE @Id_Banco_Macro		VARCHAR(10)
DECLARE @Id_Cliente			INT
DECLARE @CBU				VARCHAR(25)
DECLARE @CBU_PrimerBloque_IdBanco	CHAR(3)
DECLARE @CBU_PrimerBloque_DigVerifA CHAR(1)
DECLARE @CBU_PrimerBloque_IdSuc		CHAR(3)
DECLARE @CBU_PrimerBloque_DigVerifB CHAR(1)
DECLARE @CBU_SegundBloque_Cuenta	CHAR(13)
DECLARE @CBU_SegundBloque_DigVerifC CHAR(1)
DECLARE @FillerInicio		CHAR(1) /*Relleno.  informar '0' cero*/
DECLARE @NroConvenio		CHAR(5) /*Numero de convenio en COBIS. obligatorio*/
DECLARE @NroServicio		CHAR(10)/*Numero de servicio en COBIS. obligatorio. De no existir informar blancos*/
DECLARE @NroEmpresaSueldos	CHAR(5) /*Numero de convenio AS en COBIS. obligatorio. De no existir informar ceros*/
DECLARE @CodBancoAdherente	CHAR(3) /*Codigo de Banco asignado por BCRA. obligatorio*/
DECLARE @CodSucursalCuenta	CHAR(4) /*Codigo de sucursal. Para Banco Macro  informar el numero de sucursal. Para otros bancos, informar las posiciones 4 a 7 del bloque 1 De la CBU*/
DECLARE @TipoCuenta			CHAR(1) /*Tipo de cuenta COBIS. 3 - Cta Cte ,  4 - Caja de Ahorros para cuentas de Banco Macro - Bansud. Para cuentas de otros bancos no informar*/
DECLARE @CtaBancariaAdhere	CHAR(15)/*Cuenta COBIS del adherente. Para Bco Macro informar el numero de cuenta. Para otros bancos, informar el bloque 2 De la CBU y rellenar con un cero a izquierda.*/
DECLARE @IdActualAdhere		CHAR(22)/*Identif. Del cliente con la empresa. obligatorio*/
DECLARE @IdDebito			CHAR(15)/*Numero de factura  / recibo identif. obligatorio Identificacion del Comprobante*/
DECLARE @FuncionUsoMovim	CHAR(2) /*identifica la transaccion a efectuar. informar blancos*/
DECLARE @CodMovimRechazo	CHAR(4) /*obligatorio para rechazos. informar blancos*/
DECLARE @FechaVencimiento	CHAR(8) /*Fecha aplicación / ABM. Obligatoria*/
DECLARE @MonedaDebito		CHAR(3) /*Moneda a debitar / debitada. 002 Dolares 080 Pesos*/
DECLARE @ImporteDebitar		CHAR(13)/*importe de la transaccion. No Informar punto decimal*/
DECLARE @FechaReintentoTope CHAR(8) /*Informar Ceros*/
DECLARE @ImporteDebitado	CHAR(13)/*Informar Ceros*/
DECLARE @NuevaSucBancaria	CHAR(4) /*Codigo de sucursal nueva. Informar Ceros*/
DECLARE @TipoCuentaB		CHAR(1) /*Tipo de cuenta COBIS. Informar Ceros*/
DECLARE @NuevaCuentaBanc	CHAR(15)/*Nueva cuenta COBIS del adherente. Informar Ceros*/
DECLARE @NuevaIdAdherente	CHAR(22)/*Nueva Identificacion Del cliente. Infromar Blancos*/
DECLARE @DatosRetorno		CHAR(40)/*Libre. Información discrecional de la empresa*/
DECLARE @SinUso				CHAR(5) /*Informar Blancos*/
DECLARE @FillerFin			CHAR(1) /*Relleno. Inforar '0' Cero*/

SET @Id_Banco_Macro		= ISNULL((SELECT Valor_String FROM xParametros WHERE IdParametro = 'Id_BancoMacro'),'')
SET @Id_Cliente			= (SELECT Id_Cliente FROM Cbtes WHERE Id_Trans = @trans)
SET @CBU				= (SELECT Tar_Nro FROM Contratos WHERE Id_Cliente = @Id_Cliente AND Id_Tarjeta = @Id_Banco_Macro AND Activo=1)

SET @CBU_PrimerBloque_IdBanco	= (SELECT CAST(SUBSTRING(@CBU,1,3) AS CHAR(3)))
SET @CBU_PrimerBloque_DigVerifA = (SELECT CAST(SUBSTRING(@CBU,4,1) AS CHAR(1)))
SET @CBU_PrimerBloque_IdSuc		= (SELECT CAST(SUBSTRING(@CBU,5,3) AS CHAR(3)))
SET @CBU_PrimerBloque_DigVerifB = (SELECT CAST(SUBSTRING(@CBU,8,1) AS CHAR(1)))
SET @CBU_SegundBloque_Cuenta	= (SELECT CAST(SUBSTRING(@CBU,9,13) AS CHAR(13)))
SET @CBU_SegundBloque_DigVerifC	= (SELECT CAST(SUBSTRING(@CBU,22,1) AS CHAR(1)))

SET @FillerInicio		= '0'
SET @NroConvenio		= (SELECT Comercio_Nro FROM Valores_Tarjetas_Cred WHERE Id_Tarjeta = @Id_Banco_Macro)
SET @NroServicio		= ISNULL((SELECT Valor_String FROM xParametros WHERE IdParametro = 'BcoMacro_Servicio'),'          ')
SET @NroEmpresaSueldos	= ISNULL((SELECT Valor_Integer FROM xParametros WHERE IdParametro = 'BcoMacro_Servicio'),'00000')
SET @CodBancoAdherente	= @CBU_PrimerBloque_IdBanco
SET @CodSucursalCuenta	= @CBU_PrimerBloque_IdSuc
SET @TipoCuenta			= ' ' /*No se informa. Si bien el documento de Macro dice q es numérico, en el ejemplo que envió Club Mendoza es vacio*/
SET @CtaBancariaAdhere	= '0' + @CBU_SegundBloque_Cuenta + @CBU_SegundBloque_DigVerifC
SET @IdActualAdhere		= (SELECT LEFT(CAST(Id_Cliente AS VARCHAR) + '                      ', 22) FROM Cbtes WHERE Id_Trans = @trans)
SET @IdDebito			= (SELECT LEFT(CAST(Id_Trans AS VARCHAR) + '               ', 15) FROM Cbtes WHERE Id_Trans = @trans)
SET @FuncionUsoMovim	= '  '
SET @CodMovimRechazo	= '    '
SET @FechaVencimiento	=	(SELECT CAST(DATEPART(YY,Fecha_Venc) AS CHAR(4)) + 
							RIGHT('00' + CAST(DATEPART(mm,Fecha_Venc) AS VARCHAR),2) + 
							RIGHT('00' + CAST(DATEPART(dd,Fecha_Venc) AS VARCHAR),2) 
							FROM Cbtes WHERE Id_Trans = @trans)
SET @MonedaDebito		= '080' /*Siempre Pesos*/
SET @ImporteDebitar		=	(SELECT RIGHT( '0000000000000' + CAST(CAST((ISNULL(Imp_Total,0) + ISNULL(Saldo_Anterior,0)) * Cotizacion * 100 AS INT) AS VARCHAR), 13) 
							FROM Cbtes WHERE Id_Trans = @trans)
SET @FechaReintentoTope = '00000000'
SET @ImporteDebitado	= '0000000000000'
SET @NuevaSucBancaria	= '0000'
SET @TipoCuentaB		= '0'
SET @NuevaCuentaBanc	= '000000000000000'
SET @NuevaIdAdherente	= '                      '
SET @DatosRetorno		= (SELECT LEFT('Generado_' + CONVERT(VARCHAR(20), GETDATE(),103) + '_' + CONVERT(VARCHAR(20), GETDATE(),108) + '                                        ', 40))
SET @SinUso				= '     '
SET @FillerFin			= '0'

SET @Retorno			=	@FillerInicio		+ @NroConvenio			+ @NroServicio +
							@NroEmpresaSueldos	+ @CodBancoAdherente	+ @CodSucursalCuenta +
							@TipoCuenta			+ @CtaBancariaAdhere	+ @IdActualAdhere +
							@IdDebito			+ @FuncionUsoMovim		+ @CodMovimRechazo +
							@FechaVencimiento	+ @MonedaDebito			+ @ImporteDebitar +
							@FechaReintentoTope + @ImporteDebitado		+ @NuevaSucBancaria +
							@TipoCuentaB		+ @NuevaCuentaBanc		+ @NuevaIdAdherente +
							@DatosRetorno		+ @SinUso				+ @FillerFin

RETURN @retorno
END
GO


CREATE FUNCTION [dbo].[SF_BancoPatagonia_Proveedores_OP_TX](@pId_Trans INT) 
RETURNS CHAR(1132)
AS
BEGIN

/*================================================================================================================================*/

/*Variables del Archivo*/
DECLARE @Retorno						CHAR(1132)

/*--------------------------------------------------------------------------------------------------------------------------------*/

DECLARE @aRegistroId					CHAR(2)		/*Constante 'PO'*/

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Identificacion y referencias de la orden*/
DECLARE @aIRRefOrdenPago				CHAR(25)		/*Este campo traerá referencias unívocas en lo que refiere al pago. 
														Es un número o identificación que asignará internamente el cliente 
														para reconocer está orden. Este valor debe ser único, no pudiendo 
														repetirse en ningún caso para ordenes aceptadas. Este campo permitirá
														unir las ordenes con sus respectivos certificados de retención impositiva.*/

DECLARE @aIRMotivoPago					CHAR(105)	/*Aclaración sobre que se está abonando. Es el texto que iría en los Mails 
													de avisos de pagos a los beneficiarios.Por ejemplo: 'Facturas 0000-1234567890 y 891'*/

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Datos para la ejecucion de la orden*/
DECLARE @aDEFechaEjecucionPago			CHAR(8)		/*Es la fecha en que se deberá ejecutar la orden de pago. No debe ser menor
														a la fecha de procesamiento deseada.Para los casos de pagos con cheques de 
														pago diferido, esta es la fecha que se toma en cuenta para determinar el tiempo
														de validez del pago a favor del beneficiario en la plaza girada (o sea para control
														de vto de validez del pago a los 30 días). La fecha de emisión será igual a esta.
														Para el resto de los medios de ejecución es la fecha en que deberá efectuarse la 
														transferencia electrónica.Normalmente debería ser informarse una fecha hacía adelante,
														para mantener la orden de pago en espera de ejecución hasta la fecha solicitada. 
														Formato AAAAMMDD*/

DECLARE @aDETipoPago					CHAR(3)		/*Opciones:	‘002’= Emisión de cheque pago diferido.
														‘003’=Transferencia interna entre ctas. en el Banco o "book to book"
														‘009’=Transferencia electrónica ‘020’=Transferencia electrónica vía MEP
														‘025’= Orden de pago por caja del Banco*/

DECLARE @aDEImportePagar				CHAR(15)		/* LONG=15.2
														Importe a abonar. Se refiere a la moneda de pago y es el neto a pagar. 
														Son 15 posiciones, de las cuales las últimas 2 corresponden a los decimales - centavos.
														No debe llevar máscara ni punto o coma decimal. Completar con ceros a la izquierda.*/

DECLARE @aDEMonedaPago					CHAR(3)		/*Moneda del pago. 'ARS' – pesos */

DECLARE @aDEFechaVenciCHPD				CHAR(8)		/*Este campo es solo para los cheques de pago diferido y es la fecha de vencimiento del
														cartular.Mandatario para pagos con CHPD*/

DECLARE @aDERequerirReciboPagoCheque	CHAR(1)		/*‘S’ - Si  (para la entrega del cheque se requerirá recibo membretado del Beneficiario
														 – valor por omisión)
														 'N' – No (no se requiere el recibo membreteado)En todos los casos el Banco imprimirá 
														 un recibo en 2 copias que deberán ser firmadas por el Beneficiario.En caso que no se
														 tenga el CUIT o Nro. de documento del beneficiario (por no tener datos en el padrón 
														 correspondiente y no se informe el dato en este archivo de Ordenes), se rechazará la
														 orden por no tenerse el dato necesario para constatar la identidad del Beneficiario
														 a través del recibo o carta de autorización.*/

DECLARE @aDEClausulaNoOrden				CHAR(1)		/*‘S’ – Si (valor por omisión) Incluir leyenda “no a la orden” */

DECLARE @aDEIncluirFirmaChequeCADJ		CHAR(1)		/*‘S’ – Si (valor por omisión) 
														‘N’ – No. Implica imprimir el valor en la modalidad en lote, y enviar al adherente 
														para su firma manuscrita. Esta opción se validará según condiciones del Convenio 
														respectivo.*/

DECLARE @aDEAcompañamiendoComprobante	CHAR(3)		/*‘ICA’ – Imprimir Comprobante Adjunto a esta orden de pago, recibido o a recibir en 
														archivo ad-hoc. ‘RCA’ – Recibir y distribuir Comprobantes Adjuntos a esta orden de pago,
														impresos por el adherente.‘NEC’ – No Existen Comprobantes adjuntos asociados a esta orden.*/

DECLARE @aDETex1ReferenciaAsociadoOrden	CHAR(80)		/*Primer texto libre adicional para indicar aclaraciones sobre el pago.*/

DECLARE @aDETex2ReferenciaAsociadoOrden	CHAR(80)		/*Segundo texto libre adicional para indicar aclaraciones sobre el pago.*/

DECLARE @aDETex3ReferenciaAsociadoOrden	CHAR(80)		/*Tercer texto libre adicional para indicar aclaraciones sobre el pago.*/

DECLARE @aDEInstruccionCustomerService	CHAR(160)	/**/

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Identificacion del proveedor o beneficiario del pago*/
DECLARE @aIPBNroBeneficiario			CHAR(25)		/*Este campo es Mandatario para el caso que se desee, al ejecutar esta orden de pago,
														utilizar uno o todos los datos del Beneficiario que se tengan de antemano en la base
														de Beneficiarios en poder del Banco. Este número debe coincidir con el nro. de 
														beneficiario o proveedor en los sistemas del cliente Adherente.
														NOTA: Prestar especial atención a alinear este campo de la misma forma que en el 
														padrón de beneficiario.
														Este campo deberá venir en blanco, para el caso que se desee pagar a un beneficiario
														no informado en la base de datos de Beneficiarios en poder del Banco. En tal caso, 
														se usarán (y por ende se asume que vendrán informados) los datos del beneficiario 
														que se indican a continuación.*/

DECLARE @aIPBNomBeneficiarioProveedor	CHAR(60)		/*Si se informase algo en este campo, será el que se utilice para ejecutar esta orden
														de pago en forma puntual; sin importar si se ha informado o no Nro. de Beneficiario.
														Si este campo se informa en blanco y se ha informado Nro. de Beneficiario, usará el 
														dato que se encuentre en la base de Beneficiarios en poder del Banco.Si este campo 
														se informa en blanco y no se ha informado Nro. de Beneficiario, o se ha informado y
														no se ha encontrado en la base de datos de Beneficiarios en poder del Banco, dará lugar
														a un error de Validación de la orden.*/
		
DECLARE @aIPBTipoDocumentoBeneficiario	CHAR(3)		/*Contenido único y posible		001 = DNI	002 = LE	003 = LC	004 = CI	
														010 = CUIL (*)	011 = CUIT (*)	014 = CDI (*)	040 = PSPT
														(*) Únicos documentos válidos para transferencias internas y a otros Bancos
														Comentarios: Idem nombre del beneficiario o proveedor*/

DECLARE @aIPBNroCuit_cuilBeneficiario	CHAR(11)		/*Nro. asignado por la AFIP*/

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Domicilio, telefono, fax y mail del beneficiario*/
DECLARE @aDTFMBDomicilioBeneficiario		CHAR(120)	/* Actualmente: No Aplica*/

DECLARE @aDTFMBCodPostalBeneficiario	CHAR(15)		/* Actualmente: No Aplica*/

DECLARE @aDTFMBEmailBeneficiario		CHAR(70)		/*Opcional para el caso de requerirse el envío de avisos y no se cuente con él en el
														padrón de Beneficiarios en poder del Banco. Si no se contara en ningún caso no se 
														enviarán los avisos preestablecidos.
														Otros comentarios: Ídem Nombre del Beneficiario o Proveedor.*/
														
DECLARE @aDTFMBFAXBeneficiario			CHAR(25)		/* Actualmente: No Aplica*/

DECLARE @aDTFMBMedioComunicacionBene	CHAR(3)		/*Es el medio elegido para el envío automático de avisos referidos al pago. 
														Actualmente:‘       ‘ – No se enviarán avisos (valor por omisión).
														‘EML’ – Se enviarán e-mail de avisos a la dirección indicada más arriba */

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Datos para pagos electronicos*/
DECLARE @aDEEspacioCero					CHAR(5)		/*Filler*/

DECLARE @aDEEspacioBlanco1				CHAR(35)		/*Filler*/

DECLARE @aPECBUCuentaBenefiAcreditar	CHAR(22)		/*Mandatario para pagos electrónicos y siempre que el Beneficiario no exista 
														en el padrón en poder del Banco. Si el Beneficiario existiese, y no se informase 
														ninguna cuenta, se usará la cuenta por default declarada en dicho padrón.*/

DECLARE @aDESistemaCtaAcreditar			CHAR(2)		/*Campo mandatario para pagos electrónicos o por transferencias.
														'CC' - cuenta corriente		'CA' - caja de ahorro*/

DECLARE @aDEMonedaCtaAcredidarBanco		CHAR(3)		/*'ARS' - pesos (por default)*/

DECLARE @aDEEspacioBlanco2				CHAR(35)		/*Filler*/	

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Canales de envios de pagos con cheques*/
DECLARE @aCECanalEntregaCheque			CHAR(3)		/*Canal de entrega de los pagos con cheques y sus posibles comprobantes adjuntos.
														Mandatario en caso de no contarse con esta indicación a nivel del Padrón de Beneficiarios.
														Actualmente: 'BCO’ – Se enviará a una sucursal del Banco.
														‘ADH’ – Se entregará el valor al Adherente, quien se encargará de enviárselo a 
														los beneficiarios.	El despacho de los cheques se realizará a la sucursal de un Banco,
														teniendo en cuenta el siguiente orden de prioridades:
														1ro. A la sucursal que se indique en el campo siguiente (si el canal fuese BCO) 
														siempre que esté habilitada en el servicio para el adherente.
														2do. Si se indicara BCO y no se indicare sucursal, a la sucursal que pueda haberse
														indicado en el maestro de Beneficiarios.	Si después de este escalonamiento no se 
														tuviese la forma de entrega, se rechazará la orden.*/

DECLARE @aCESucursalEnviarChequeCbte	CHAR(8)		/*Si el canal de entrega fuese ADH (entrega el propio adherente), este campo será tomado
														de la siguiente forma:
														Si este campo viene informado en blanco, se deberá enviar el cheque a la sucursal 010.
														Si en este campo viene un valor informado distinto de blanco, se deberá enviar el cheque
														a la sucursal especificada en dicho campo.
														Se espera recibir 3 dígitos numéricos ajustados a izquierda. 
														Solo para el caso de pagos con Giro en efectivo, si éste campo viene informado con 999, 
														se asumíra que el mismo puede ser pagado en cualesquiera de las sucursales habilitadas 
														para el servicio. En caso de indicarse 999, se rechazará la OP si la misma tuviera un 
														valor diferente de ‘NEC’, el campo “Acompañamiento de Comprobantes Adjuntos”*/
														
/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Datos de la cuenta del adherente a ser debitada*/
DECLARE @aCADCero						CHAR(5)		/*Filler*/

DECLARE @aCADCbuCtaAdherenteDebitada	CHAR(22)		/*Si no se informasen datos de la cuenta débito, la orden se ejecutará sobre la cuenta de
														pago indicada por omisión al momento del alta del adherente.*/

DECLARE @aCADSistemaCtaDebitar			CHAR(2)		/*'CC' - cuenta corriente	'CA' - caja de ahorro*/

DECLARE @aCADMonedaCtaDebitar			CHAR(3)		/*'ARS' - pesos		'USD' - dólares*/

DECLARE @aCADTipoOperatoria				CHAR(1)		/*‘ ‘ ó ‘1’ - Pago a proveedores*/

DECLARE @aCADChequeCruzado				CHAR(1)		/*‘ ‘ ó ‘S’ - Cruzar el cheque       ‘N’ - NO cruzar el cheque
														Será necesario informar este valor solo si la orden de Pago es con cheque.*/

DECLARE @aCADEspacioBlanco				CHAR(78)		/*Filler*/	

/*FIN Variables del Archivo*/
/*================================================================================================================================*/

/*Variables de Calculo intermedio*/
DECLARE @FechaAcreditacion	DATETIME
DECLARE @Importe			DECIMAL(12,2)
DECLARE @Id_Proveedor		INT
DECLARE @Sucursal_Banco		VARCHAR(3)
DECLARE @Id_Cta_Banco		SMALLINT
/*FIN Variables de Calculo intermedio*/

/*Asignacion de variables*/
SET @FechaAcreditacion	= (SELECT Fecha_Acreditacion FROM Valores WHERE Id_Trans = @pId_Trans)
SET @Importe			= (SELECT Importe FROM Valores WHERE Id_Trans = @pId_Trans)
SET @Id_Proveedor		= (SELECT Id_Proveedor FROM Cbtes WHERE Id_Trans = @pId_Trans)
SET @Id_Cta_Banco		= (SELECT Id_Cta_Banco FROM Valores WHERE Id_Trans = @pId_Trans)
SET @Sucursal_Banco		= (SELECT RIGHT('000' + CAST(Sucursal AS VARCHAR), 3) FROM Bancos_Ctas WHERE Id_Cta_Banco = @Id_Cta_Banco)
/*FIN Asignacion de variables*/

SET @aRegistroId						= 'PO'

/*Identificacion y referencias de la orden*/
SET @aIRRefOrdenPago					= (SELECT LEFT(CAST(@pId_Trans AS VARCHAR) + '                         ', 25))
SET @aIRMotivoPago						= (SELECT LEFT(dbo.CF_Descrip_Cbte(@pId_Trans) + '                                                                                                         ', 105))

/*Datos para la ejecucion de la orden*/
SET @aDEFechaEjecucionPago				= (/*AAAA*/CAST(DATEPART(YY, @FechaAcreditacion) AS CHAR(4)) + /*MM*/RIGHT('00' + CAST(DATEPART(mm, @FechaAcreditacion) AS VARCHAR),2) + /*DD*/RIGHT('00' + CAST(DATEPART(dd, @FechaAcreditacion) AS VARCHAR),2))
SET @aDETipoPago						= '009' /*Transferencia Eléctronica*/
SET @aDEImportePagar					= (SELECT RIGHT( '000000000000000' + CAST(CAST((ISNULL(@Importe,0)) * 100 AS INT) AS VARCHAR), 15))
SET @aDEMonedaPago						= 'ARS'
SET @aDEFechaVenciCHPD					= (/*AAAA*/CAST(DATEPART(YY, @FechaAcreditacion) AS CHAR(4)) + /*MM*/RIGHT('00' + CAST(DATEPART(mm, @FechaAcreditacion) AS VARCHAR),2) + /*DD*/RIGHT('00' + CAST(DATEPART(dd, @FechaAcreditacion) AS VARCHAR),2))
SET @aDERequerirReciboPagoCheque		= 'N' /*No (No se requiere el recibo membretado)*/
SET @aDEClausulaNoOrden					= 'N' /*NO incluye leyenda "No a la orden"*/
SET @aDEIncluirFirmaChequeCADJ			= 'N' /*No (Implica imprimir el valor en la modalidad en lote y enviar al adherente para su firma manuscrita)*/
SET @aDEAcompañamiendoComprobante		= 'NEC' /*No existen comprobantes adjuntos asociados a esta orden*/
SET @aDETex1ReferenciaAsociadoOrden		= '                                                                                '
SET @aDETex2ReferenciaAsociadoOrden		= '                                                                                '
SET @aDETex3ReferenciaAsociadoOrden		= '                                                                                '
SET @aDEInstruccionCustomerService		= '                                                                                                                                                                '

/*Identificacion del proveedor o beneficiario del pago*/
SET @aIPBNroBeneficiario				= (SELECT LEFT(CAST(Id_Proveedor_Externo AS VARCHAR) + '                         ', 25) FROM Proveedores WHERE Id_Proveedor = @Id_Proveedor)
SET @aIPBNomBeneficiarioProveedor		= (SELECT LEFT(CAST(Razon_Social AS VARCHAR) + '                                                            ', 60) FROM Proveedores WHERE Id_Proveedor = @Id_Proveedor)
SET @aIPBTipoDocumentoBeneficiario		= '011' /*TIPO CUIT*/
SET @aIPBNroCuit_cuilBeneficiario		= (SELECT Cuit FROM Proveedores WHERE Id_Proveedor = @Id_Proveedor)

/*Domicilio, telefono, fax y mail del beneficiario*/
SET @aDTFMBDomicilioBeneficiario		= '                                                                                                                        '
SET @aDTFMBCodPostalBeneficiario		= '               '
SET @aDTFMBEmailBeneficiario			= '                                                                      '
SET @aDTFMBFAXBeneficiario				= '                         '
SET @aDTFMBMedioComunicacionBene		= '   '

/*Datos para pagos electronicos*/
SET @aDEEspacioCero						= '00000'
SET @aDEEspacioBlanco1					= '                                   '
SET @aPECBUCuentaBenefiAcreditar		= (SELECT CBU FROM Proveedores WHERE Id_Proveedor = @Id_Proveedor)
SET @aDESistemaCtaAcreditar				= 'CA' /*Caja de Ahorro*/
SET @aDEMonedaCtaAcredidarBanco			= 'ARS' /*Pesos*/
SET @aDEEspacioBlanco2					= '                                   '

/*Canales de envios de pagos con cheques*/
SET @aCECanalEntregaCheque				= 'BCO'
SET @aCESucursalEnviarChequeCbte		= @Sucursal_Banco

/*Datos de la cuenta del adherente a ser debitada*/
SET @aCADCero							= '00000'
SET @aCADCbuCtaAdherenteDebitada		= '0000000000000000000000'
SET @aCADSistemaCtaDebitar				= 'CC' /*Cuenta Corriente*/
SET @aCADMonedaCtaDebitar				= 'ARS' /*Pesos*/
SET @aCADTipoOperatoria					= '1' /*Pago a Proveedores*/
SET @aCADChequeCruzado					= 'N' /*NO cruzar el cheque*/
SET @aCADEspacioBlanco					= '                                                                              '

SET @Retorno	=	@aRegistroId					+ @aIRRefOrdenPago					+ @aIRMotivoPago +
					@aDEFechaEjecucionPago			+ @aDETipoPago						+ @aDEImportePagar +
					@aDEMonedaPago					+ @aDEFechaVenciCHPD				+ @aDERequerirReciboPagoCheque +
					@aDEClausulaNoOrden				+ @aDEIncluirFirmaChequeCADJ		+ @aDEAcompañamiendoComprobante +
					@aDETex1ReferenciaAsociadoOrden + @aDETex2ReferenciaAsociadoOrden	+ @aDETex3ReferenciaAsociadoOrden +
					@aDEInstruccionCustomerService	+ @aIPBNroBeneficiario				+ @aIPBNomBeneficiarioProveedor +
					@aIPBTipoDocumentoBeneficiario	+ @aIPBNroCuit_cuilBeneficiario		+ @aDTFMBDomicilioBeneficiario +
					@aDTFMBCodPostalBeneficiario	+ @aDTFMBEmailBeneficiario			+ @aDTFMBFAXBeneficiario +
					@aDTFMBMedioComunicacionBene	+ @aDEEspacioCero					+ @aDEEspacioBlanco1 +
					@aPECBUCuentaBenefiAcreditar	+ @aDESistemaCtaAcreditar			+ @aDEMonedaCtaAcredidarBanco +
					@aDEEspacioBlanco2				+ @aCECanalEntregaCheque			+ @aCESucursalEnviarChequeCbte +
					@aCADCero						+ @aCADCbuCtaAdherenteDebitada		+ @aCADSistemaCtaDebitar +
					@aCADMonedaCtaDebitar			+ @aCADTipoOperatoria				+ @aCADChequeCruzado +
					@aCADEspacioBlanco
					
RETURN @Retorno
END
GO


CREATE FUNCTION [dbo].[SF_BancoPatagonia_Proveedores_Padron_TX](@pId_Proveedor INT) 
RETURNS CHAR(870)
AS
BEGIN

/*================================================================================================================================*/

/*Variables del Archivo*/
DECLARE @Retorno						CHAR(870)

/*--------------------------------------------------------------------------------------------------------------------------------*/

DECLARE @aRegistroId					CHAR(2)		/*Constante 'PB'*/

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Identificacion del Beneficiario y Tipo de Actualizacion*/
DECLARE @aIBNumeroBen					CHAR(25)		/*Ajustado a izquierda.Es mandatario para todos los casos.*/

DECLARE @aIBTipoActualizacion			CHAR(3)			/*'BAJ' û Se considerarß baja de Beneficiario en el Banco. 
														Cualquier otro valor implica actualizaci¾n o alta de registro, siempre en forma completa;
														por lo tanto, se deberßn informar todos los campos.*/

DECLARE @aIBNombreBen					CHAR(60)		/*Mandatario si no es una baja.*/

DECLARE @aIBTipoDocumentoBene			CHAR(3)			/*Mandatario si no es una baja. Valores ·nicos y posibles	001 = DNI	002 = LE
														003 = LC	004 = CI	010 = CUIL (*)	011 = CUIT (*)	014 = CDI (*)	040 = PSPT
														(*) ┌nicos documentos vßlidos para transferencias internas y a otros Bancos*/

DECLARE @aIBNroCuit_cuilBen				CHAR(11)		/*Mandatario si no es una baja.		Nro. dado por la AFIP*/

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Domicilio, Telefono, Fax y Mail del Beneficiario*/
DECLARE @aDatosDomicilioBen				CHAR(120)		/*Opcional*/

DECLARE @aDatosCodigoPostalBen			CHAR(15)		/*Opcional	Ajustado a izquierda*/

DECLARE @aDatosTelefonoBen				CHAR(25)		/*Ejemplo: 054-0011-4651-4444(333) 
														PaÝs: 3 + Cdad: 4 + Ctral: 4 + Abonado: 4 + Interno: 4*/

DECLARE @aDatosFaxBen					CHAR(25)		/*Idem Telefono*/

DECLARE @aDatosEmailBen					CHAR(70)		/*Mandatario si se solicita aviso de pago por EMAIL. Si se necesita dar aviso a mßs de una
														casilla, se recomendarß al Beneficiario la creaci¾n de un grupo bajo una misma direcci¾n*/

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Datos de Validacion para permitir pagos*/
DECLARE @aDVMarcaBloqueoPago			CHAR(3)			/*æ    æ û No aplica	æBLQÆ û Bloquear	æDESÆ û Desbloquear
														Ordena al Banco, inhibir pr¾ximos pagos a este Beneficiario, o rehabilitarlo en el servicio.*/

DECLARE @aDVMontoMaxPes					CHAR(15)		/*Long=15.2 
														Importe mßximo en pesos, sobre el cual una orden recibida serß rechazada.
														No dejar en ceros, para permitir cualquier monto ingresar 99999999999999*/

DECLARE @aDVMontoMaxDol					CHAR(15)		/*Long=15.2
														Importe mßximo en d¾lares, sobre el cual una orden recibida serß rechazada. 
														No dejar en ceros, para permitir cualquier monto ingresar 99999999999999*/

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Especificaciones de avisos y comunicaciones al beneficiario*/
DECLARE @aECRestriccionAvisosBen		CHAR(3)			/*Dejar en blanco ya que esto se informa en cada pago*/

DECLARE @aECMedioComunicacionBen		CHAR(3)			/*Es el medio elegido para el envÝo automßtico de avisos de pago. Debe ser:
														æEMLÆ û Se enviarßn e-mail de avisos a la direcci¾n indicada mßs arriba . (default)
														æ       æ û No se enviarßn avisos*/

DECLARE @aECNombrePersonaContactoBen	CHAR(60)		/**/

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Datos para la ejecucion de pagos con cheques*/
DECLARE @aEPCInsertClausulaNOEmitirChe	CHAR(1)			/*'S' - Si (es el valor por omisi¾n)	'N' - No se imprime dicha clßusula. OK*/

DECLARE @aEPCNroDoc1erAutorizadoRetirar	CHAR(22)		/*Tipo de documento + n·mero como string.	p.e.: 'D.N.I. 23.789.987'
														Indicar autorizados s¾lo si no requiere recibo oficial del Beneficiario */

DECLARE @aEPCNombre1erAutorizadoRetirar	CHAR(60)		/**/

DECLARE @aEPCTipo1erAutorizado			CHAR(3)			/*Indica si la persona anteriormente informada se encuentra autorizada al retiro de:
														æCHEÆ û Pagos con cheques	æEFEÆ û Pagos en efectivo	
														CYEÆ û Pagos con cheques o efectivo	
														En todos los casos, estß persona se considera autorizada a retirar los comprobantes 
														adjuntos en cualquier tipo de pago.*/

DECLARE @aEPCNroDoc2doAutorizadoRetirar	CHAR(22)		/*Tipo de documento + n·mero como string.	p.e.: 'D.N.I. 23.789.987'*/

DECLARE @aEPCNombre2doAutorizadoRetirar	CHAR(60)		/**/

DECLARE @aEPCTipo2doAutorizado			CHAR(3)			/*═dem autorizado 1.*/

DECLARE @aEPCNroDoc3erAutorizadoRetiro	CHAR(22)		/*Tipo de documento + n·mero como string.	p.e.: 'D.N.I. 23.789.987'*/

DECLARE @aEPCNombre3erAutorizadoRetirar	CHAR(60)		/**/

DECLARE @aEPCTipo3erAutorizado			CHAR(3)			/*═dem autorizado 1.*/

DECLARE @aRequerirReciboBenCheque		CHAR(1)			/*æSÆ- Si(para la entrega del cheque se requerirß recibo membreteado del Beneficiario û
															 valor por omisi¾n)	'N' û No (no se requiere el recibo membreteado)*/

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Canales de envios de pagos con cheque*/
DECLARE @aCEPCTipoRutaElegidaDefault	CHAR(3)			/*Constante:'BCO'  (valor por omisi¾n.) û Se enviarß a la sucursal del Banco, 
														elegida por default en el campo siguiente.*/

DECLARE @aCEPCSucursalBancoEnvioChe		CHAR(5)			/*Sucursal del Banco, por omisi¾n, elegida para girar pagos con cheques.
														Se espera recibir 3 dÝgitos numÚricos ajustados a izquierda.*/

DECLARE @aCEPCEspacioBlanco				CHAR(8)			/*Actualmente:Filler	Ajustado a izquierda.*/

DECLARE @aCEPCCeros						CHAR(5)			/*Actualmente:Filler*/

/*--------------------------------------------------------------------------------------------------------------------------------*/

/*Datos de cuentas creditos para pagos electronicos por default*/
DECLARE @aDCtaECBUBenAcreditarBtoB		CHAR(22)		/*Cuenta a acreditar para pagos electr¾nicos dentro del mismo Banco (Book to Book).*/

DECLARE @aDCtaESistemaAcreditarBtoB		CHAR(2)			/*'CC' - cuenta corriente	'CA' - caja de ahorro*/

DECLARE @aDCtaEMonedaCtaAcreditarBtoB	CHAR(3)			/*'ARS' û pesos */

DECLARE @aDCtaECBUBenAcreditarOtroB		CHAR(22)		/*Cuenta a acreditar para pagos electr¾nicos en otro Banco (MEP,SNP,e- settlement).*/

DECLARE @aDCtaESistemaAcreditarOtroB	CHAR(2)			/*'CC' - cuenta corriente	'CA' - caja de ahorro*/

DECLARE @aDCtaEMonedaCtaAcreditarOtroB	CHAR(3)			/*'ARS' û pesos*/

DECLARE @aDCtaEEspacioBlanco			CHAR(80)		/*Filler*/

/*FIN Variables del Archivo*/

/*Declaracion Variables Locales*/
DECLARE @Id_Cta_Banco		SMALLINT
/*FIN Declaracion Variables Locales*/
/*================================================================================================================================*/

SET @Id_Cta_Banco = (SELECT Id_Cta_Banco FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)

SET @aRegistroId						= 'PB'

/*Identificacion del Beneficiario y Tipo de Actualizacion*/
SET @aIBNumeroBen						= (SELECT LEFT(CAST(Id_Proveedor AS VARCHAR) + '                         ', 25) FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)
SET @aIBTipoActualizacion				= 'ALT'
SET @aIBNombreBen						= (SELECT LEFT(ISNULL(Razon_Social, '') + '                                                            ', 60) FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)
SET @aIBTipoDocumentoBene				= '011' /*CUIT*/
SET @aIBNroCuit_cuilBen					= (SELECT LEFT(CAST(ISNULL(Cuit, '') AS VARCHAR) + '           ', 11) FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)

/*Domicilio, Telefono, Fax y Mail del Beneficiario*/
SET @aDatosDomicilioBen					= (SELECT LEFT(CAST(ISNULL(Direccion, '') AS VARCHAR) + '                                                                                                                        ', 120) FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)
SET @aDatosCodigoPostalBen				= (SELECT LEFT(CAST(ISNULL(Cp, '') AS VARCHAR) + '               ', 15) FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)
SET @aDatosTelefonoBen					= (SELECT LEFT(CAST(ISNULL(Telefono, '') AS VARCHAR) + '                         ', 25) FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)
SET @aDatosFaxBen						= (SELECT LEFT(CAST(ISNULL(Fax, '') AS VARCHAR(25)) + '                         ', 25) FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)
SET @aDatosEmailBen						= (SELECT LEFT(CAST(ISNULL(Email, '') AS VARCHAR(70)) + '                                                                      ', 70) FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)

/*Datos de Validacion para permitir pagos*/
SET @aDVMarcaBloqueoPago				= '   '
SET @aDVMontoMaxPes						= '000000010000000'
SET @aDVMontoMaxDol						= '000000000000000'

/*Especificaciones de avisos y comunicaciones al beneficiario*/
SET @aECRestriccionAvisosBen			= '   '
SET @aECMedioComunicacionBen			= 'EML'
SET @aECNombrePersonaContactoBen		= (SELECT LEFT(ISNULL(Razon_Social, '') + '                                                            ', 60) FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)

/*Datos para la ejecucion de pagos con cheques*/
SET @aEPCInsertClausulaNOEmitirChe		= 'N'
SET @aEPCNroDoc1erAutorizadoRetirar		= '                      '
SET @aEPCNombre1erAutorizadoRetirar		= '                                                            '
SET @aEPCTipo1erAutorizado				= '   '
SET @aEPCNroDoc2doAutorizadoRetirar		= '                      '
SET @aEPCNombre2doAutorizadoRetirar		= '                                                            '
SET @aEPCTipo2doAutorizado				= '   '
SET @aEPCNroDoc3erAutorizadoRetiro		= '                      '
SET @aEPCNombre3erAutorizadoRetirar		= '                                                            '
SET @aEPCTipo3erAutorizado				= '   '
SET @aRequerirReciboBenCheque			= 'N'

/*Canales de envios de pagos con cheque*/
SET @aCEPCTipoRutaElegidaDefault		= 'BCO'
SET @aCEPCSucursalBancoEnvioChe			= (SELECT RIGHT('000' + CAST(Sucursal AS VARCHAR), 3) FROM Bancos_Ctas WHERE Id_Cta_Banco = @Id_Cta_Banco)
SET @aCEPCEspacioBlanco					= '        '
SET @aCEPCCeros							= '00000'

/*Datos de cuentas creditos para pagos electronicos por default*/
SET @aDCtaECBUBenAcreditarBtoB			= (SELECT ISNULL(CBU, '') FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)
SET @aDCtaESistemaAcreditarBtoB			= 'CC'
SET @aDCtaEMonedaCtaAcreditarBtoB		= 'ARS'
SET @aDCtaECBUBenAcreditarOtroB			= (SELECT ISNULL(CBU, '') FROM Proveedores WHERE Id_Proveedor = @pId_Proveedor)
SET @aDCtaESistemaAcreditarOtroB		= 'CC'
SET @aDCtaEMonedaCtaAcreditarOtroB		= 'ARS'
SET @aDCtaEEspacioBlanco				= '                                                                                '



SET @Retorno =	@aRegistroId					+ @aIBNumeroBen						+ @aIBTipoActualizacion +
				@aIBNombreBen					+ @aIBTipoDocumentoBene				+ @aIBNroCuit_cuilBen +
				@aDatosDomicilioBen				+ @aDatosCodigoPostalBen			+ @aDatosTelefonoBen +
				@aDatosFaxBen					+ @aDatosEmailBen					+ @aDVMarcaBloqueoPago +
				@aDVMontoMaxPes					+ @aDVMontoMaxDol					+ @aECRestriccionAvisosBen +
				@aECMedioComunicacionBen		+ @aECNombrePersonaContactoBen		+ @aEPCInsertClausulaNOEmitirChe +
				@aEPCNroDoc1erAutorizadoRetirar + @aEPCNombre1erAutorizadoRetirar	+ @aEPCTipo1erAutorizado +
				@aEPCNroDoc2doAutorizadoRetirar + @aEPCNombre2doAutorizadoRetirar	+ @aEPCTipo2doAutorizado +
				@aEPCNroDoc3erAutorizadoRetiro	+ @aEPCNombre3erAutorizadoRetirar	+ @aEPCTipo3erAutorizado +
				@aRequerirReciboBenCheque		+ @aCEPCTipoRutaElegidaDefault		+ @aCEPCSucursalBancoEnvioChe +
				@aCEPCEspacioBlanco				+ @aCEPCCeros						+ @aDCtaECBUBenAcreditarBtoB +
				@aDCtaESistemaAcreditarBtoB		+ @aDCtaEMonedaCtaAcreditarBtoB		+ @aDCtaECBUBenAcreditarOtroB + 
				@aDCtaESistemaAcreditarOtroB	+ @aDCtaEMonedaCtaAcreditarOtroB	+ @aDCtaEEspacioBlanco
				
RETURN @Retorno
END
GO


CREATE FUNCTION [dbo].[SF_BancoPatagonia_TX](@pId_Trans INT, @pTarNro VARCHAR(22), @pFecha_Venc DATETIME, @pImporte DECIMAL(12,2)) 
RETURNS CHAR(200)
AS
BEGIN

/*Variable de Retorno*/
DECLARE @Retorno			CHAR(200)
/*FIN Variable de Retorno*/

/*Variables del Archivo*/
/*Para todos los tipos de novedad*/
DECLARE @aTipoNovedad				CHAR(1)		/*Tipo de Novedad / D - Debitos*/
DECLARE @aCUIT						CHAR(11)	/*CUIT/L DNI del Cliente*/
/*Bloque 1 de la CBU*/
DECLARE @aEntidad					CHAR(3)		/*Entidad*/
DECLARE @aSucursal					CHAR(4)		/*Sucursal*/
DECLARE @aDigVerifBloq1				CHAR(1)		/*Digito Verificador Bloque 1*/
/*Bloque 2 de la CBU*/
DECLARE @aTipoCuenta				CHAR(2)		/*Tipo de Cuenta*/
DECLARE @aNroCuenta					CHAR(11)	/*Nro. de Cuenta*/
DECLARE @aDigVerifBloq2				CHAR(1)		/*Digito Verificador Bloque 2*/
/*Segun tabla COELSA - ACH*/
DECLARE @aIdentClientePag			CHAR(22)	/*Identificador Cliente Pagador*/
DECLARE @aFechaVenc					CHAR(8)		/*Fecha de Vencimiento*/
DECLARE @aProdPrestacion			CHAR(10)	/*Producto/Prestacion*/
/*Para Adhesiones*/
DECLARE @aADHTipoDoc				CHAR(4)		/*Tipo de Documento*/
DECLARE @aADHNroDoc					CHAR(11)	/*Nro. de Documento*/
/*Para DÚbitos, Reversiones*/
DECLARE @aDEBRefDeb					CHAR(15)	/*Referencia del dÚbito*/
DECLARE @aDEBImporte				CHAR(10)	/*Importe (8 enteros y 2 decimales)*/
DECLARE @aDEBTipoMon				CHAR(1)		/*Tipo de Moneda./ P:Pesos o D:Dolares*/
/*Para notificaciones de Cambio en Empresa Originante*/
DECLARE @aNOTEMPORIIdentCliPag		CHAR(22)	/*Identificador de Cliente Nuevo*/
/*Para Notificaciones de Cambio en Entidad Receptoras*/
/*Bloque 2 de la CBU*/
DECLARE @aNOTENTRECEPTipoCuenta		CHAR(2)		/*Tipo de Cuenta*/
DECLARE @aNOTENTRECEPNroCuenta		CHAR(11)	/*Nro de Cuenta*/
DECLARE @aNOTENTRECEPDigVerifBloq2	CHAR(1)		/*Digito Verificador - Bloque 2*/
/*Para Rechazos en la rendicion, en las presentaciones dajar en blanco*/
DECLARE @aRECHCodRechazo			CHAR(3)		/*Codigo de Rechazo. Ej R02, R03,...*/
DECLARE @aOBLIGReserv				CHAR(35)	/*Reserva. (Blancos)*/
DECLARE @aOBLIGNroCuitEmp			CHAR(11)	/*Nro. Cuit Empresa.*/
/*FIN Variables del Archivo*/

/*Variables Intermedias*/
DECLARE @Importe						VARCHAR(10)
DECLARE @FechaVencimiento				DATETIME
DECLARE @Id_Cliente						INT
DECLARE @CBU							VARCHAR(25)
DECLARE @CBU_PrimerBloque_IdBanco		CHAR(3)
DECLARE @CBU_PrimerBloque_IdSuc			CHAR(4)
DECLARE @CBU_PrimerBloque_DigVerifPriBlo CHAR(1)
DECLARE @CBU_SegundBloque_TipoCuenta	CHAR(2)
DECLARE @CBU_SegundBloque_NroCuenta		CHAR(11)
DECLARE @CBU_SegundBloque_DigVerifC		CHAR(1)
/*FIN Variables Intermedias*/

/*Calculo CBU*/

SET @CBU = (SELECT RTRIM(LTRIM(ISNULL(DBO.SF_COTIZA(@pTarNro), ''))))

SET @CBU_PrimerBloque_IdBanco			= (SELECT CAST(SUBSTRING(@CBU,1,3) AS CHAR(3)))
SET @CBU_PrimerBloque_IdSuc				= (SELECT CAST(SUBSTRING(@CBU,4,4) AS CHAR(4)))
SET @CBU_PrimerBloque_DigVerifPriBlo	= (SELECT CAST(SUBSTRING(@CBU,8,1) AS CHAR(1)))

SET @CBU_SegundBloque_TipoCuenta		= (SELECT CAST(SUBSTRING(@CBU,9,2) AS CHAR(2)))
SET @CBU_SegundBloque_NroCuenta			= (SELECT CAST(SUBSTRING(@CBU,11,11) AS CHAR(11)))
SET @CBU_SegundBloque_DigVerifC			= (SELECT CAST(SUBSTRING(@CBU,22,1) AS CHAR(1)))
/*FIN Calculo CBU*/

SET @Id_Cliente			= (SELECT ISNULL(Id_Cliente,0)			FROM Cbtes WHERE Id_Trans = @pId_Trans)
--5/12/2018 Se toma fecha del Lote en vez del Cbte por Ticket 15.404
SET @FechaVencimiento	= ISNULL(@pFecha_Venc, DATEADD(dd, 10, GETDATE()))
SET @Importe			= (SELECT RIGHT('0000000000' +  CAST(CAST((@pImporte * 100) AS INT) AS VARCHAR), 10))

/*Grabacion de los campos de la fila*/
SET @aTipoNovedad				= 'D'
SET @aCUIT						= '00000000000'
SET @aEntidad					= @CBU_PrimerBloque_IdBanco
SET @aSucursal					= @CBU_PrimerBloque_IdSuc
SET @aDigVerifBloq1				= @CBU_PrimerBloque_DigVerifPriBlo
SET @aTipoCuenta				= @CBU_SegundBloque_TipoCuenta
SET @aNroCuenta					= @CBU_SegundBloque_NroCuenta
SET @aDigVerifBloq2				= @CBU_SegundBloque_DigVerifC
SET @aIdentClientePag			= ISNULL(LEFT(CAST(RIGHT('000000' + CONVERT(VARCHAR(10), @Id_Cliente), 6) AS VARCHAR) + '                      ', 22), '                      ')
SET @aFechaVenc					= /*DD*/RIGHT('00' + CAST(DATEPART(dd, @FechaVencimiento) AS VARCHAR),2) + /*MM*/RIGHT('00' + CAST(DATEPART(mm, @FechaVencimiento) AS VARCHAR),2) + /*AAAA*/CAST(DATEPART(YY, @FechaVencimiento) AS CHAR(4))
SET @aProdPrestacion			= 'CUOTAS    '
SET @aADHTipoDoc				= '    '
SET @aADHNroDoc					= '00000000000'
SET @aDEBRefDeb					= ISNULL(LEFT(CAST(@pId_Trans AS VARCHAR) + '               ', 15), '               ')
SET @aDEBImporte				= @Importe
SET @aDEBTipoMon				= 'P'
SET @aNOTEMPORIIdentCliPag		= '                      '
SET @aNOTENTRECEPTipoCuenta		= '00'
SET @aNOTENTRECEPNroCuenta		= '00000000000'
SET @aNOTENTRECEPDigVerifBloq2	= '0'
SET @aRECHCodRechazo			= '   '
SET @aOBLIGReserv				= '                                   '
SET @aOBLIGNroCuitEmp			= (dbo.CF_XParam('RECE_Cuit'))

/*FIN Grabacion de los campos de la fila*/

/*Grabacio¾n de la Fila Completa*/
SET @Retorno			=	@aTipoNovedad				+ @aCUIT						+ @aEntidad +
							@aSucursal					+ @aDigVerifBloq1				+ @aTipoCuenta +
							@aNroCuenta					+ @aDigVerifBloq2				+ @aIdentClientePag +
							@aFechaVenc					+ @aProdPrestacion				+ @aADHTipoDoc +
							@aADHNroDoc					+ @aDEBRefDeb					+ @aDEBImporte + 
							@aDEBTipoMon				+ @aNOTEMPORIIdentCliPag		+ @aNOTENTRECEPTipoCuenta +
							@aNOTENTRECEPNroCuenta		+ @aNOTENTRECEPDigVerifBloq2	+ @aRECHCodRechazo +
							@aOBLIGReserv				+ @aOBLIGNroCuitEmp
/*FIN Grabacio¾n de la Fila Completa*/

RETURN @retorno
END
GO

CREATE  FUNCTION [dbo].[SF_Banda_Abono](@trans INT, @Item INT) 
RETURNS CHAR(37)
AS
BEGIN
/*
Server: Es un digito y siempre es 0.
Tipo: Todos los abonos tienen un 6 en esa posicion
Seccion: Codigo de 3 digitos que identifica la posicion
Fila: 3 digitos que identifican la fila del asiento
Asiento: 3 digitos que identifican el asiento
Tarifa: Codigo de tarifa, 2 digitos
Club: 4 digitos que representan el club
Vencimiento: Guarda 4 digitos que representa la fecha de vencimiento del abonado
Contador: 1 digito que repreesenta el nro. de versiòn de la credencial de abonado
Nro. de Cliente: Nro. de 8 digitos que representa el cliente, es distinto para cada socio
Abono: Nro. de Abonado, posee 6 digitos
Check Sum: Es el dígito verificador. Se calcula a partir de un algoritmo que se ecncuentra en el sistema.
*/

DECLARE @Server CHAR(1)
DECLARE @Tipo CHAR(1)
DECLARE @Seccion CHAR(3)
DECLARE @Fila CHAR(3)
DECLARE @Asiento CHAR(3)
DECLARE @Tarifa CHAR(2)
DECLARE @Club CHAR(4)
DECLARE @Vencimiento CHAR(4)
DECLARE @Contador CHAR(1)
DECLARE @Cliente CHAR(8)
DECLARE @Abono CHAR(6)
DECLARE @CSum CHAR(1)
DECLARE @retorno CHAR(37)

DECLARE @Venc DATETIME

SET @Venc = ISNULL((SELECT Fecha_Venc FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),'20000101')

SET @Server = '0'
SET @Tipo = '6'


SET @Seccion =  Case (SELECT RTRIM(P.Calle) FROM Productos P , Cbtes_Items  I 
                                WHERE P.Id_Producto = I.Id_Producto 
				AND I.Id_Trans = @trans AND I.Item = @Item)
--CD_SectorBanda    =  7  Palcos                    Sectores Plco 1 Plco 2
					WHEN '1PP' THEN '041'
					WHEN '2PP' THEN '102'
--CD_SectorBanda    =  4  Platea  BAJA SUR          Sectores A,B,C,D,E
					WHEN 'ASBI' THEN '020'
					WHEN 'ASBP' THEN '020'
					WHEN 'BSBI' THEN '021'
					WHEN 'BSBP' THEN '021'
					WHEN 'CSBI' THEN '022'
					WHEN 'CSBP' THEN '022'
					WHEN 'DSBI' THEN '107'
					WHEN 'DSBP' THEN '107'
					WHEN 'ESBI' THEN '108'
					WHEN 'ESBP' THEN '108'
--CD_SectorBanda    =  2  Platea  ALTA SUR          Sectores F,G.H.I,J	
					WHEN 'FSAI' THEN '008'
					WHEN 'FSAP' THEN '007'
					WHEN 'GSAI' THEN '010'
					WHEN 'GSAP' THEN '009'
     				WHEN 'HSAI' THEN '011'
					WHEN 'HSAP' THEN '011'
					WHEN 'ISAI' THEN '012'
					WHEN 'ISAP' THEN '012'
					WHEN 'JSAI' THEN '014'
					WHEN 'JSAP' THEN '013'
--CD_SectorBanda    =  9  Platea  MEDIA NORTE       Sectores F,G.H.I,J					
    				WHEN 'FNBP' THEN '025'
					WHEN 'GNBI' THEN '026'
					WHEN 'GNBP' THEN '026'
					WHEN 'HNBI' THEN '027'
					WHEN 'HNBP' THEN '027'					
					WHEN 'INBI' THEN '028'
					WHEN 'INBP' THEN '028'
					WHEN 'JNBI' THEN '029'
					WHEN 'JNBP' THEN '029'
--CD_SectorBanda    =  1  Platea  ALTA NORTE        Sectores K,L,M,N,O,Q
					WHEN 'KNAI' THEN '006'
					WHEN 'KNAP' THEN '006'
					WHEN 'LNAI' THEN '005'
					WHEN 'LNAP' THEN '005'
					WHEN 'MNAI' THEN '004'
					WHEN 'MNAP' THEN '004'
					WHEN 'NNAI' THEN '003'
					WHEN 'NNAP' THEN '003'
					WHEN 'ONAI' THEN '002'
					WHEN 'ONAP' THEN '002'
					WHEN 'QNAI' THEN '001'
					WHEN 'QNAP' THEN '001'
--CD_SectorBanda    =  3  Platea  BAJA NORTE        Sectores R,S,T,U,V
					WHEN 'RNBI' THEN '015'
					WHEN 'RNBP' THEN '015'
					WHEN 'SNBI' THEN '016'
					WHEN 'SNBP' THEN '016'
					WHEN 'TNBI' THEN '017'
					WHEN 'TNBP' THEN '017'
					WHEN 'UNBI' THEN '018'
					WHEN 'UNBP' THEN '018'
					WHEN 'VNBI' THEN '019'
					WHEN 'VNBP' THEN '019'
					END
-- correcion 01/08
--CD_SectorBanda    =  1  Platea  ALTA NORTE        Sectores K,L,M,N,O,Q
--CD_SectorBanda    =  2  Platea  ALTA SUR          Sectores F,G.H.I,J
--CD_SectorBanda    =  3  Platea  BAJA NORTE        Sectores R,S,T,U,V
--CD_SectorBanda    =  4  Platea  BAJA SUR          Sectores A,B,C,D,E
--CD_SectorBanda    =  7  Palcos                    Sectores Plco 1 Plco 2
--CD_SectorBanda    =  9  Platea  MEDIA NORTE       Sectores F,G.H.I,J					

--detalle inicial 
--0 = (Palcos laterales)  Palco 1 y Palco 2
--1 = (Platea Norte Media Media )  F,G,H,I,J, 
--    (Platea Norte Baja) R,S,T,U,V
--2 = (Platea Norte Alta) K,L,M,N,O,Q
--3 = (Platea Sur Baja) A,B,C,D,E
--4 = (Platea Sur Alta) F,G,H,I,J.

SET @Fila = ISNULL((SELECT RIGHT('000'+RTRIM(P.Fila),3) FROM Productos P , Cbtes_Items  I 
                                WHERE P.Id_Producto = I.Id_Producto 
								AND I.Id_Trans = @trans AND I.Item = @Item),'000') 
SET @Asiento = ISNULL((SELECT RIGHT('000'+RTRIM(P.Columna),3) FROM Productos P , Cbtes_Items  I 
                                WHERE P.Id_Producto = I.Id_Producto  
								AND I.Id_Trans = @trans AND I.Item = @Item),'000') 
								
								
SET @Tarifa = '44'  -- pero hay que hacer un case segun las tarifas que se usen
SET @Club = '2118'
SET @Vencimiento = SUBSTRING(CAST((MONTH(@Venc) + 100 ) AS CHAR(3)),2,2) + SUBSTRING(CAST(YEAR(@Venc) AS CHAR(4)),3,2)
SET @Contador = ISNULL((SELECT CAST(Millas AS CHAR(1)) FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),'0')   
SET @Cliente = ISNULL((SELECT SUBSTRING(CAST((Id_Cliente + 100000000 ) AS CHAR(9)),2,8) FROM Cbtes WHERE Id_Trans = @trans),'00000000')
SET @Abono = ISNULL((SUBSTRING(CAST((@trans + 1000000 ) AS CHAR(7)),2,6) ),'000000')

set @retorno = @Server + @Tipo + @Seccion + @Fila + @Asiento + @Tarifa + @Club +
               @Vencimiento  + @Contador + @Cliente + @Abono 
			   
SET @CSum = (SELECT dbo.SF_Checksum(@retorno))

set @retorno = @Server + @Tipo + @Seccion + @Fila + @Asiento + @Tarifa + @Club +
               @Vencimiento  + @Contador + @Cliente + @Abono + @CSum 
			   

RETURN @Retorno
END
GO

CREATE  FUNCTION [dbo].[SF_Banda_Socio](@Cli INT) 
RETURNS CHAR(37)
AS
BEGIN

DECLARE @Sexo CHAR(1)
DECLARE @Doc_Nro CHAR(12)
DECLARE @Tarifa CHAR(2)
DECLARE @Sala CHAR(1)
DECLARE @Tipo_Persona CHAR(1)
DECLARE @Club CHAR(4)
DECLARE @Contador CHAR(2)
DECLARE @Socio CHAR(8)
DECLARE @Tipo_Cli SMALLINT
DECLARE @Banda VARCHAR(37)

SET @Sexo = (SELECT CASE Sexo WHEN 'F' THEN '1' ELSE '2' END FROM Clientes WHERE Id_Cliente = @Cli)
SET @Doc_Nro = RIGHT ('000000000000' + CAST( ISNULL((SELECT Doc_Nro FROM Clientes WHERE Id_Cliente = @Cli),0) AS VARCHAR(11)),11)
IF @Doc_Nro = '00000000000'
BEGIN
    SET @Doc_Nro = '0' + RIGHT ('000000000000' + CAST( ISNULL((SELECT @Cli ),0) AS VARCHAR(11)),11)
END
ELSE
BEGIN
    SET @Doc_Nro = '1' + @Doc_Nro
END

SET @Club = '2118'        --Velez
SET @Sala = '0'
SET @Tipo_Persona = '2'   --!2=socio 3=empleado   4=empleaod multiple acceso al estadio
SET @Contador = RIGHT('00'+ CAST(ISNULL((SELECT Credencial_Imp  FROM Clientes WHERE Id_Cliente = @Cli),1)  AS VARCHAR(2)),2)
SET @Socio = RIGHT ('000000000000' + CAST( ISNULL((SELECT @Cli ),0) AS VARCHAR(11)),8)

--   !Ejemplo banda velez:  02 00 2118 0000 02 10 60406871 2 00000933561

SET @Tipo_Cli = ISNULL((SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @Cli),0)
IF @Tipo_Cli = 1
	SET @Tarifa = '00'
ELSE
    SET @Tarifa = '01'
                                                                         
SET @Banda = @Sala + 
             @Tipo_Persona +                                      
             '00' +   --Fijo
             @Club +  --
             '000' +  --Fijo
             @Contador +
             @Tarifa +
             '0' +  --fijo
             @Socio +
             @Doc_Nro


DECLARE @CSum CHAR(1)

			   
SET @CSum = (SELECT dbo.SF_Checksum(@Banda))

set @Banda = @Banda + @CSum 
			   

RETURN @Banda
END
GO

