CREATE FUNCTION [dbo].[SF_CAguin_precio](@pId_Cliente INT, @pFecha DATETIME) 
RETURNS DECIMAL(12,2)
AS
BEGIN
/*Declaracion Variables*/
DECLARE @Precio_CAguin		DECIMAL(12,2)
DECLARE @CS_Precio_Persona	DECIMAL(12,2)
DECLARE @Id_Tipo_Cli		SMALLINT
DECLARE @ucp				DATETIME

DECLARE @edad int
DECLARE @fecha_alta datetime
DECLARE @fecha_hasta datetime
DECLARE @Id_Cliente_Temp int

/*FIN Declaracion Variables*/

SET @Id_Tipo_Cli		= (dbo.SF_Categ(@pId_Cliente, @pFecha))

IF (@Id_Tipo_Cli IN (	10, 1004, 1005, 1006, 1007, 1008, 1010, 1011, 1012, 1013, 
						1014, 1015, 1016, 1017, 1018, 1019, 1100, 1101, 1102, 1103,
						1104, 1105, 1106, 1107, 1108, 1109, 1110, 1111, 1112, 1113))
BEGIN
	/* Categorias que directamente pagan $0 por Ticket 12.808:
	* 10	ACCESO MASTER					1004	ACOMPAÑANTE		
	* 1005	CONYUGUE EMPLEADO				1006	EMPLEADO
	* 1007	USUARIO GEBA GYM				1008	USUARIO
	* 1010	VITALICIO + 71					1011	RESOLUCION 95
	* 1012	USUARIO RCA						1013	USUARIO AFIP
	* 1014	USUARIO J.N.					1015	CONCESIONARIO
	* 1016	USUARIO S.M. / JM				1017	USUARIO +75
	* 1018	INVITADOS						1019	COLEGIOS
	* 1019	COLEGIOS						1100	SOCIO HONORARIO
	* 1101	MASTER							1102	CC FAMILY GOLD
	* 1103	NO SOCIO						1104	USUARIO TRIAR
	* 1105	REFERENTE						1106	PRE INFANTIL
	* 1107	USUARIO ASHIWEA					1108	USUARIO ASHIWEA / GIRE
	* 1109	USUARIO ASHIWEA GOLD MAYOR		1110	USUARIO ASHIWEA GOLD MENOR
	* 1111	USUARIO PROMO VERANO MAYOR		1112	USUARIO PROMO VERANO MENOR
	* 1113	VISITA
	*/
	SET @Precio_CAguin = 0
	RETURN @Precio_CAguin
END
ELSE
BEGIN
	/*Se agrega a pedido por ticket 23313*/
	SET @ucp = (dbo.SF_Ult_Cuota_Paga(@pId_Cliente,GETDATE()))
	
	IF(CONVERT(VARCHAR(10),@ucp,112) >= '20210501' AND CONVERT(VARCHAR(10),@ucp,112) < '20211101')
	BEGIN
		
		SET @CS_Precio_Persona	= (dbo.SF_CS_Precio_Persona(@pId_Cliente, @pFecha))
		SET @Precio_CAguin		= ROUND (((@CS_Precio_Persona / 2)* 0.75), 0)
	END
	ELSE IF(CONVERT(VARCHAR(10),@ucp,112) >= '20211101')
	BEGIN
		
		SET @CS_Precio_Persona	= (dbo.SF_CS_Precio_Persona(@pId_Cliente, @pFecha))
		SET @Precio_CAguin		= ROUND (((@CS_Precio_Persona / 2)* 0.50), 0)
	END
	ELSE
	BEGIN
		
		SET @CS_Precio_Persona	= (dbo.SF_CS_Precio_Persona(@pId_Cliente, @pFecha))
		SET @Precio_CAguin		= ROUND ((@CS_Precio_Persona / 2), 0)
	END	
END


SET @Id_Cliente_Temp = ISNULL((SELECT  TOP 1 Id_Cliente FROM Clientes_Temp WHERE Id_Cliente =@pId_Cliente AND (Flag_modificacion is null or flag_modificacion=3)),0)

SELECT 
@fecha_alta= Fecha_Alta ,
@edad =dbo.SF_Edad(GETDATE(),fecha_nac),
@fecha_hasta= DATEADD(year, 1, fecha_alta)
FROM Clientes WHERE Id_Cliente =@pId_Cliente


/*################ TICKET 22085 Bonificacion del 50 %###############*/
/*SE COMENTA ESTA PARTE DEL CODIGO PORQUE QUEDA SIN EFECTO LA PROMOCIÓN*/
--IF(@fecha_alta>='20210219' AND @fecha_alta<='20210503' AND @edad>=18 AND GETDATE()<=@fecha_hasta AND @Id_Cliente_Temp<>0)
--BEGIN 
--	SET @Precio_CAguin=@Precio_CAguin/2
--END 

/*################ TICKET 23260 Bonificacion del 50 %###############*/

--IF(@fecha_alta>='20210507' AND @fecha_alta<='20210520'  AND GETDATE()<=@fecha_hasta AND @Id_Cliente_Temp<>0)
--BEGIN 
--	SET @Precio_CAguin=@Precio_CAguin/2
--END


RETURN ISNULL(@Precio_CAguin, 0)
END
GO

CREATE FUNCTION dbo.SF_CAguin_precio_prueba(@pId_Cliente INT, @pFecha DATETIME) 
RETURNS DECIMAL(12,2)
AS
BEGIN
/*Declaracion Variables*/
DECLARE @Precio_CAguin		DECIMAL(12,2)
DECLARE @CS_Precio_Persona	DECIMAL(12,2)
DECLARE @Id_Tipo_Cli		SMALLINT
DECLARE @ucp				DATETIME
DECLARE @flag_CAGUI_JUN			SMALLINT
DECLARE @flag_CAGUI_DIC				SMALLINT
/*FIN Declaracion Variables*/

SET @Id_Tipo_Cli		= (dbo.SF_Categ(@pId_Cliente, @pFecha))

IF (@Id_Tipo_Cli IN (	10, 1004, 1005, 1006, 1007, 1008, 1010, 1011, 1012, 1013, 
						1014, 1015, 1016, 1017, 1018, 1019, 1100, 1101, 1102, 1103,
						1104, 1105, 1106, 1107, 1108, 1109, 1110, 1111, 1112, 1113))
BEGIN
	/* Categorias que directamente pagan $0 por Ticket 12.808:
	* 10	ACCESO MASTER					1004	ACOMPAÑANTE		
	* 1005	CONYUGUE EMPLEADO				1006	EMPLEADO
	* 1007	USUARIO GEBA GYM				1008	USUARIO
	* 1010	VITALICIO + 71					1011	RESOLUCION 95
	* 1012	USUARIO RCA						1013	USUARIO AFIP
	* 1014	USUARIO J.N.					1015	CONCESIONARIO
	* 1016	USUARIO S.M. / JM				1017	USUARIO +75
	* 1018	INVITADOS						1019	COLEGIOS
	* 1019	COLEGIOS						1100	SOCIO HONORARIO
	* 1101	MASTER							1102	CC FAMILY GOLD
	* 1103	NO SOCIO						1104	USUARIO TRIAR
	* 1105	REFERENTE						1106	PRE INFANTIL
	* 1107	USUARIO ASHIWEA					1108	USUARIO ASHIWEA / GIRE
	* 1109	USUARIO ASHIWEA GOLD MAYOR		1110	USUARIO ASHIWEA GOLD MENOR
	* 1111	USUARIO PROMO VERANO MAYOR		1112	USUARIO PROMO VERANO MENOR
	* 1113	VISITA
	*/
	SET @Precio_CAguin = 0
	RETURN @Precio_CAguin
END
ELSE
BEGIN
	/*Se agrega a pedido por ticket 23313*/
	SET @ucp = (dbo.SF_Ult_Cuota_Paga(@pId_Cliente,GETDATE()))
	SET @flag_CAGUI_JUN = ISNULL((SELECT MIN(1) FROM cbtes_Items WHERE Id_Producto='CAGUIN' AND Fecha_QA='20210601' AND ID_estado_CBTE<>3 AND Id_CLiente=@pId_Cliente),0)
	SET @flag_CAGUI_DIC = ISNULL((SELECT MIN(1) FROM cbtes_Items WHERE Id_Producto='CAGUIN' AND Fecha_QA='20211201' AND ID_estado_CBTE<>3 AND Id_CLiente=@pId_Cliente),0)
	
	
	IF(CONVERT(VARCHAR(10),@ucp,112) >= '20210501' AND @flag_CAGUI_JUN=0)
	BEGIN
	
		SET @CS_Precio_Persona	= (dbo.SF_CS_Precio_Persona(@pId_Cliente, @pFecha))
		SET @Precio_CAguin		= ROUND (((@CS_Precio_Persona / 2)* 0.75), 0)
	END
	ELSE IF(CONVERT(VARCHAR(10),@ucp,112) >= '20211101' AND @flag_CAGUI_DIC=0)
	BEGIN
		
		SET @CS_Precio_Persona	= (dbo.SF_CS_Precio_Persona(@pId_Cliente, @pFecha))
		SET @Precio_CAguin		= ROUND (((@CS_Precio_Persona / 2)* 0.50), 0)
	END
	ELSE
	BEGIN
		
		SET @CS_Precio_Persona	= (dbo.SF_CS_Precio_Persona(@pId_Cliente, @pFecha))
		SET @Precio_CAguin		= ROUND ((@CS_Precio_Persona / 2), 0)
	END
	
END

RETURN ISNULL(@Precio_CAguin, 0)

END
GO


CREATE FUNCTION [dbo].[SF_CD_TagsHabilitados](@Id_Acceso SMALLINT, @Fecha DATETIME)
RETURNS VARCHAR(1350)
AS
BEGIN
DECLARE @Tags			VARCHAR(1349)
DECLARE @Id_Cliente		INT
DECLARE @Tag			VARCHAR(30);
DECLARE @Contador		INT
DECLARE @FlagHabilitado TINYINT

SET @Tags = ''
SET @Contador = 0
SET @FlagHabilitado = 0

DECLARE curTagsHabilitados CURSOR FOR 
SELECT DISTINCT CL.Id_Cliente, CL.Credencial_Nro
FROM Clientes CL
WHERE
CL.Activo = 1
AND CL.Credencial_Nro IS NOT NULL
AND CL.Credencial_Nro <> '00000000'
GROUP BY CL.Id_Cliente, CL.Credencial_Nro

OPEN curTagsHabilitados
FETCH NEXT FROM curTagsHabilitados
INTO @Id_Cliente, @Tag
WHILE @@FETCH_STATUS = 0
BEGIN
	
	SET @FlagHabilitado = 0
	
	IF(dbo.SF_CD_ValidarMaster(@Id_Cliente) = 1)
	BEGIN
		SET @FlagHabilitado = 1
	END
	ELSE
	BEGIN
		IF(dbo.SF_CD_ValidarContratosTipos(@Id_Cliente, @Id_Acceso, @Fecha) = 1)
		BEGIN
			SET @FlagHabilitado = 1
		END
		ELSE
		BEGIN
			IF(dbo.SF_CD_ValidarTipo(@Id_Cliente, @Id_Acceso, @Fecha) = 1)
			BEGIN
				SET @FlagHabilitado = 1
			END
			ELSE
			BEGIN
				IF(dbo.SF_CD_ValidarProducVta(@Id_Cliente, @Id_Acceso, @Fecha) = 1)
				BEGIN
					SET @FlagHabilitado = 1
				END
			END
		END
	END
	
	IF(@FlagHabilitado = 1)
	BEGIN
		IF (@Contador = 0)
			SET @Tags = @Tag	
		ELSE
			SET @Tags = @Tags + ',' + @Tag
		
		SET @Contador = @Contador + 1
	END
		
			
FETCH NEXT FROM curTagsHabilitados
INTO @Id_Cliente, @Tag
END 
CLOSE curTagsHabilitados;
DEALLOCATE curTagsHabilitados;

RETURN ISNULL(@Tags,'')

END
GO


CREATE FUNCTION [dbo].[SF_CD_ValidarContratosTipos](@Id_Cliente INT, @Id_Acceso SMALLINT, @Fecha DATETIME)
RETURNS TINYINT
AS
BEGIN
DECLARE @Habilitado	TINYINT
DECLARE @ContratoHabilitado INT

SET @Habilitado = 0
SET @ContratoHabilitado = 0

SET @ContratoHabilitado = ISNULL((SELECT MAX(CO.Id_Contrato)
							FROM Contratos CO, CD_Accesos_Cont_Tipos CACT
							WHERE 
							CO.Id_Cliente = @Id_Cliente
							AND CO.Id_Tipo_Con = CACT.Id_Tipo_Con
							AND CO.Activo = 1 
							AND CO.Id_Tipo_Con IN (SELECT Id_Tipo_Con FROM CD_Accesos_Cont_Tipos WHERE Id_Acceso = @Id_Acceso)
							AND CACT.Flag_Habilitado = 'H'
							AND CO.Fecha_Desde < @Fecha
							AND (CO.Fecha_Hasta IS NULL OR CO.Fecha_Hasta >= @Fecha)),0)

IF (@ContratoHabilitado <> 0)
BEGIN
	SET @Habilitado = 1
END

RETURN ISNULL(@Habilitado,0)

END
GO


CREATE FUNCTION [dbo].[SF_CD_ValidarMaster](@Id_Cliente INT)
RETURNS TINYINT
AS
BEGIN
DECLARE @Habilitado			TINYINT
DECLARE @Id_Cliente_Master INT

SET @Habilitado = 0
SET @Id_Cliente_Master = 0

SET @Id_Cliente_Master = ISNULL((SELECT Id_Cliente FROM CD_Cli_Master WHERE Id_Cliente = @Id_Cliente),0)

IF (@Id_Cliente_Master <> 0)
BEGIN
	SET @Habilitado = 1
END

RETURN ISNULL(@Habilitado,0)

END
GO


CREATE FUNCTION [dbo].[SF_CD_ValidarProducVta](@Id_Cliente INT, @Id_Acceso SMALLINT, @Fecha DATETIME)
RETURNS TINYINT
AS
BEGIN
DECLARE @Habilitado			TINYINT
DECLARE @Id_Producto_Habil	VARCHAR(14)

SET @Habilitado = 0
SET @Id_Producto_Habil = ''

SET @Id_Producto_Habil = ISNULL((SELECT MAX(CI.Id_Producto)
								FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT
								WHERE 
								CI.Id_Trans = CB.Id_Trans
								AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte
								AND CT.Compromete_Factura = 1
								AND CB.Id_Estado_Cbte IN (4,2)
								AND CI.Id_Cliente = @Id_Cliente
								AND CI.Fecha_QA <= @Fecha
								AND CI.Id_Producto IN (SELECT Id_Producto FROM CD_Accesos_Prod WHERE Id_Acceso = @Id_Acceso)), '')

IF (@Id_Producto_Habil <> '')
BEGIN
	SET @Habilitado = 1
END

RETURN ISNULL(@Habilitado,0)

END
GO


CREATE FUNCTION [dbo].[SF_CD_ValidarTipo](@Id_Cliente INT, @Id_Acceso SMALLINT, @Fecha DATETIME)
RETURNS TINYINT
AS
BEGIN
DECLARE @Habilitado				TINYINT
DECLARE @Id_Tipo_Cli			SMALLINT
DECLARE @Id_Tipo_Cli_Habil	INT

SET @Habilitado = 0
SET @Id_Tipo_Cli_Habil = 0

SET @Id_Tipo_Cli = dbo.SF_Categ(@Id_Cliente, @Fecha)

SET @Id_Tipo_Cli_Habil = ISNULL((SELECT Id_Tipo_Cli
							FROM CD_Accesos_Cli_Tipos CACT
							WHERE 
							CACT.Id_Acceso = @Id_Acceso
							AND CACT.Id_Tipo_Cli = @Id_Tipo_Cli
							AND ISNULL(CACT.Flag_Habilitado, 'H') = 'H'), 0)


IF (@Id_Tipo_Cli_Habil <> 0)
BEGIN
	SET @Habilitado = 1
END

RETURN ISNULL(@Habilitado,0)

END
GO


CREATE FUNCTION [dbo].[SF_CSE_Impaga](@Id_Cliente INT) 
RETURNS DATETIME
AS
BEGIN
DECLARE @Ult_CSE_Impaga		DATETIME
DECLARE @UCSE				DATETIME
DECLARE @Id_Tipo_Cli		SMALLINT

/*Ticket 10.957*/

SET @Id_Tipo_Cli = (SELECT ISNULL(Id_Tipo_Cli, 0) FROM Clientes WHERE Id_Cliente = @Id_Cliente)

IF(@Id_Tipo_Cli IN (1004,1007,1008,1010,1012,1013,1014,1016,1017,1104))
BEGIN
	SET @UCSE = '20501231'
	RETURN @UCSE
END

SET @Ult_CSE_Impaga = (SELECT MIN(CI.Fecha_QA)
						FROM Cbtes_Items CI, Cbtes CB, Productos PR, Cbtes_Tipos CT
						WHERE 
						CB.Id_Trans = CI.Id_Trans 
						AND PR.Id_Producto = CI.Id_Producto
						AND CB.Id_Estado_Cbte IN (1/*Pendiente*/, 4/*Parcial*/)
						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte 
						AND CT.Compromete_Factura IN (1)
						AND PR.Id_Producto = 'CSE'
						AND CI.Id_Cliente = @Id_Cliente)	


SET @UCSE = ISNULL(@Ult_CSE_Impaga,'20501231')

RETURN @UCSE
END
GO


CREATE FUNCTION [dbo].[SF_CS_MesPago](@Cli INT,@Fecha DATETIME) 
RETURNS CHAR(1)
AS
BEGIN
DECLARE @Retorno CHAR(1) = '', @trans INT


SET @trans = (select MAX(c.id_trans) 
from cbtes c, cbtes_tipos t,Cbtes_Items Ci
where c.Id_Tipo_Cbte = t.Id_Tipo_Cbte
and ci.Id_Trans = c.Id_Trans
and c.Id_Estado_Cbte = 2
and Ci.Id_Producto = 'CS'
and t.Compromete_Factura = 1
and c.Id_Cliente = @Cli
and YEAR(Ci.Fecha_QA) = YEAR(@Fecha) 
AND MONTH(Ci.Fecha_QA) = MONTH(@Fecha)
) 
IF ISNULL(@trans,0) > 0
   SET @Retorno = 'P'


RETURN @Retorno
END
GO



CREATE FUNCTION [dbo].[SF_CS_Precio](@Cli INT,@Fecha DATETIME) 
RETURNS DECIMAL(12,2)
AS
BEGIN
DECLARE @Retorno DECIMAL(12,2)
DECLARE @GRUPO DECIMAL(12,2) = 0
DECLARE @Prod CHAR(14)
DECLARE @fecha_nac datetime
DECLARE @edad int
declare @lista int
declare @titular int,@ID_CLI_TEMP INT
declare @cant_grupo int = 0
DECLARE @cond_vta char(10)

DECLARE @fecha_alta datetime
DECLARE @fecha_hasta datetime
DECLARE @fecha_hasta_semestral datetime

DECLARE @Id_Cliente_Temp int

set @titular = isnull((select Id_Cliente_Ref from Clientes where Id_Cliente = @Cli ),0)
SET @GRUPO = 0
if @titular = 0 
   BEGIN
    set @titular = @Cli
    set @cond_vta = isnull((select Id_Cond_Vta from Clientes where Id_Cliente = @Cli ),0)
    IF @cond_vta <> 'GFCP'
    BEGIN
		DECLARE GF_CURSOR_Precio CURSOR FOR
			SELECT ID_CLIENTE FROM CLIENTES WHERE ID_CLIENTE_REF = @titular
			AND FECHA_ALTA <= @Fecha AND ISNULL(FECHA_BAJA,@Fecha + 1) > @Fecha

		OPEN GF_CURSOR_Precio 		
		FETCH NEXT FROM GF_CURSOR_Precio INTO @ID_CLI_TEMP
		WHILE @@FETCH_STATUS = 0
		begin
			set @GRUPO = (@GRUPO + dbo.SF_CS_Precio_Persona(@ID_CLI_TEMP,@Fecha))
			FETCH NEXT FROM GF_CURSOR_Precio INTO @ID_CLI_TEMP
		END
		CLOSE GF_CURSOR_Precio
		DEALLOCATE GF_CURSOR_Precio
	END

   END
   
   
set @lista = (select ISNULL( id_lista_precio,0) from Clientes where Id_Cliente =@Cli )
if @lista = 0
   set @lista = 1

SET @Prod = dbo.SF_Prod(@Cli,@FECHA)
if @Prod = ''
   return 0
  


SET @Id_Cliente_Temp = ISNULL((SELECT  TOP 1 Id_Cliente FROM Clientes_Temp WHERE Id_Cliente =@Cli AND (Flag_modificacion is null or flag_modificacion=3)),0)

SELECT 
@fecha_alta= Fecha_Alta ,
@edad =dbo.SF_Edad(GETDATE(),fecha_nac),
@fecha_hasta= DATEADD(year, 1, fecha_alta),
@fecha_hasta_semestral= DATEADD(MONTH, 6, fecha_alta)
FROM Clientes WHERE Id_Cliente =@Cli

--Se modifica la linea porque estaba sumando lo correspondiente al GF y luego se dividia por dos 13/09/2021
--SET @Retorno = ISNULL(dbo.SF_CS_Precio_Persona(@CLI,@Fecha) ,0)  + @GRUPO

SET @Retorno = ISNULL(dbo.SF_CS_Precio_Persona(@CLI,@Fecha) ,0)


/*################ TICKET 22085 Bonificacion del 50 %###############*/

IF(@fecha_alta>='20210219' AND @fecha_alta<='20210503' AND @edad>=18 AND GETDATE()<=@fecha_hasta AND @Id_Cliente_Temp<>0)
BEGIN 
	SET @Retorno=@Retorno/2  
END 

/*################ TICKET 23260 Bonificacion del 50 %###############*/

IF(@fecha_alta>='20210507' AND @fecha_alta<='20210520'  AND GETDATE()<=@fecha_hasta AND @Id_Cliente_Temp<>0)
BEGIN 
	SET @Retorno=@Retorno/2 
END 

/*################ TICKET 24634 Bonificacion del 50 %###############*/

IF(@fecha_alta>='20210915' AND @fecha_alta<='20210923' AND GETDATE()<=@fecha_hasta_semestral AND @Id_Cliente_Temp<>0)
BEGIN 
	SET @Retorno=@Retorno/2 
END 

/*################ TICKET 25667 Bonificacion del 35 % desde diciembre a febrero ###############*/

IF(@fecha_alta>='20211201' AND @fecha_alta<'20220301'  AND GETDATE()<='20220301' AND @Id_Cliente_Temp<>0)
BEGIN 
	SET @Retorno=(@Retorno- (@Retorno*0.35)) 
END 
-- Aca se suma lo que corresponde al GF 13/09/2021
SET @Retorno = @Retorno + @GRUPO

RETURN isnull(@Retorno,0)
END
GO



CREATE FUNCTION [dbo].[SF_CS_Precio_](@Cli INT,@Fecha DATETIME) 
RETURNS DECIMAL(12,2)
AS
BEGIN
DECLARE @Retorno DECIMAL(12,2)
DECLARE @GRUPO DECIMAL(12,2) = 0
DECLARE @Prod CHAR(14)
DECLARE @fecha_nac datetime
DECLARE @edad int
declare @lista int
declare @titular int,@ID_CLI_TEMP INT
declare @cant_grupo int = 0
DECLARE @cond_vta char(10)

DECLARE @fecha_alta datetime
DECLARE @fecha_hasta datetime

set @titular = isnull((select Id_Cliente_Ref from Clientes where Id_Cliente = @Cli ),0)

if @titular = 0 
   BEGIN
    set @titular = @Cli
    set @cond_vta = isnull((select Id_Cond_Vta from Clientes where Id_Cliente = @Cli ),0)
    IF @cond_vta <> 'GFCP'
    BEGIN
		DECLARE GF_CURSOR_Precio CURSOR FOR
			SELECT ID_CLIENTE FROM CLIENTES WHERE ID_CLIENTE_REF = @titular
			AND FECHA_ALTA <= @Fecha AND ISNULL(FECHA_BAJA,@Fecha + 1) > @Fecha

		OPEN GF_CURSOR_Precio 		
		FETCH NEXT FROM GF_CURSOR_Precio INTO @ID_CLI_TEMP
		WHILE @@FETCH_STATUS = 0
		begin
			set @GRUPO = (@GRUPO + dbo.SF_CS_Precio_Persona(@ID_CLI_TEMP,@Fecha))
			FETCH NEXT FROM GF_CURSOR_Precio INTO @ID_CLI_TEMP
		END
		CLOSE GF_CURSOR_Precio
		DEALLOCATE GF_CURSOR_Precio
	END

   END
   
   
set @lista = (select ISNULL( id_lista_precio,0) from Clientes where Id_Cliente =@Cli )
if @lista = 0
   set @lista = 1

SET @Prod = dbo.SF_Prod(@Cli,@FECHA)
if @Prod = ''
   return 0
  

SET @fecha_alta= (SELECT Fecha_Alta FROM Clientes WHERE Id_Cliente =@Cli)

SET @edad =(SELECT dbo.SF_Edad(GETDATE(),fecha_nac) FROM Clientes WHERE Id_Cliente =@Cli)

SET @fecha_hasta= (SELECT DATEADD(year, 1, fecha_alta) FROM Clientes WHERE Id_Cliente =@Cli)

SET @Retorno = ISNULL(dbo.SF_CS_Precio_Persona(@CLI,@Fecha) ,0) + @GRUPO




RETURN isnull(@Retorno,0)
END
GO

CREATE FUNCTION [dbo].[SF_CS_Precio_Persona](@Cli INT, @Fecha DATETIME) 
RETURNS DECIMAL(12,2)
AS
BEGIN
/*Declaracion de Variables*/
DECLARE @Retorno				DECIMAL(12,2)
DECLARE @Prod					VARCHAR(14)
DECLARE @Fecha_Nac				DATETIME
DECLARE @Edad					INT
DECLARE @Id_Lista_Precio		INT
DECLARE @Titular				INT
DECLARE @Id_Cli_Temp			INT
DECLARE @Cant_Grupo				INT
DECLARE @Id_Contrato_Desc_CS	INT
DECLARE @Porc_Bonif_Cont_DescCS	DECIMAL(5,2)
DECLARE @Imp_Bonif_Cont_DescCS	DECIMAL(12,2)
DECLARE @Id_Contrato_Licencia	INT
DECLARE @Porc_Bonif_Cont_Lic	DECIMAL(5,2)
DECLARE @Id_Contrato_Beca		INT
DECLARE @Porc_Bonif_Cont_Beca	DECIMAL(5,2)
DECLARE @Imp_Bonif_Cont_Beca	DECIMAL(12,2)
-- Se agrega por unica vez 29/04/2020
DECLARE @flag_Existe_contrato_pandemia	TINYINT
DECLARE @Id_Tipo_Cli_Tit		INT
DECLARE @Id_Tipo_Cli_INT		INT
DECLARE @Fecha_Alta				DATETIME
DECLARE @Flag_Existe_Contrato_Recargo DECIMAL(12,2)


SET @Cant_Grupo = 0

/*Busco Titular del Grupo Familiar*/


--SET @Titular = ISNULL((SELECT Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @Cli), 0)
--SET @Id_Tipo_Cli_Tit = ISNULL((SELECT Id_Tipo_Cli FROM Clientes WHERE Id_cliente=@Titular),0)
--SET @Id_Tipo_Cli_INT = ISNULL((SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @Cli), 0)
--SET @Fecha_Alta		 = ISNULL((SELECT Fecha_Alta FROM Clientes WHERE Id_Cliente = @Cli), '19000101')


SELECT
@Titular			=	ISNULL(Id_Cliente_Ref,0)
,@Id_Tipo_Cli_INT	=	ISNULL(Id_Tipo_Cli,0)
,@Fecha_Alta		=	ISNULL(Fecha_Alta,'19000101')
,@Id_Lista_Precio	=	ISNULL(Id_Lista_Precio,1)
,@Edad				=   dbo.CF_Edad_Persona_A_UnaFecha(Fecha_Nac,@Fecha) --- 29/4/22 flor: se modifica para que calcule la edad del mes a fact (ticket 001423)
FROM Clientes 
WHERE Id_Cliente = @Cli

IF @Titular <> 0
BEGIN
	SELECT 
	@Id_Tipo_Cli_Tit	 =	ISNULL(Id_Tipo_Cli,0)
	FROM Clientes 
	WHERE Id_Cliente = @Titular
END

IF @Titular = 0
BEGIN
   SET @Titular = @cli
END

/*Busco Lista Precio del Titular*/
--SET @Id_Lista_Precio = ISNULL((SELECT Id_Lista_Precio from Clientes where Id_Cliente = @Cli), 0)

IF @Id_Lista_Precio = 0
BEGIN
   SET @Id_Lista_Precio = 1
END

/*Busco Producto correspondiente según Categoria*/
SET @Prod = ISNULL(dbo.SF_Prod(@Cli, @Fecha),'')

IF @Prod = ''
BEGIN
   RETURN 0
END

/*Busco si tiene un Contrato Activo de DESCUENTOS EN CUOTA SOCIAL con descuento*/  
--SET @Id_Contrato_Desc_CS		= ISNULL((SELECT MAX(Id_Contrato) FROM Contratos WHERE Id_Cliente = @Cli AND Id_Tipo_Con = 10 AND Fecha_Desde <= @Fecha AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL)),0)

/* Busco si tiene contrato Activo de BECA  */
 /* 4- BECA 
   14- Descuento vitaclicio res 28 
   15- BECA DEPORTISTA 
   16- BECA EXCELENCIA DEPORTIVA)
   17- BECA OLIMPICOS
   34- DESCUENTO POR DISCAPACIDAD*/ -- Se agrega por solicitud en el ticket 18024 para descuento en CS
 
--SET @Id_Contrato_Beca = ISNULL((SELECT MAX(Id_Contrato) FROM Contratos WHERE Id_Cliente = @Cli AND Id_Tipo_Con  in (4, 14, 15, 16, 17, 34)  AND Fecha_Desde <= @Fecha AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL)),0)

/*Busco si tiene un Contrato Activo de LICENCIAS*/  
--SET @Id_Contrato_Licencia = ISNULL((SELECT MAX(Id_Contrato) FROM Contratos WHERE Id_Cliente = @Cli AND Id_Tipo_Con in (11 /*LICENCIA CON ACCESO*/,48/*LICENCIA SIN ACCESO*/) AND Fecha_Desde <= @Fecha AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL)),0)
/**/
SELECT
    @Id_Contrato_Desc_CS = MAX(CASE WHEN Id_Tipo_Con = 10 THEN Id_Contrato END),
    @Porc_Bonif_Cont_DescCS = SUM(CASE WHEN Id_Tipo_Con = 10 THEN Porc_Bonif ELSE 0 END),
    @Imp_Bonif_Cont_DescCS  = SUM(CASE WHEN Id_Tipo_Con = 10 THEN Imp_Bonif ELSE 0 END),
    @Id_Contrato_Beca = MAX(CASE WHEN Id_Tipo_Con IN (4,14,15,16,17,34) THEN Id_Contrato END),
    @Id_Contrato_Licencia = MAX(CASE WHEN Id_Tipo_Con IN (11,48) THEN Id_Contrato END)
FROM Contratos
WHERE Id_Cliente = @Cli
  AND Fecha_Desde <= @Fecha
  AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL)
  AND Activo = 1

/*Cálculo de precio sin descuento*/  
SET @Retorno = ISNULL((	SELECT Precio =
						CASE
							WHEN ISNULL(Precio_Nuevo, 0) <> 0.00 AND p.Fecha_Desde_Nueva <= @Fecha THEN ISNULL(Precio_Nuevo, 0)
							ELSE ISNULL(Precio, 0)
						END
						FROM Prod_Listas_Precios_Items i, Prod_Listas_Precios p
						WHERE i.Id_Lista_Precio=p.Id_Lista_Precio
						AND	i.Id_Producto = @Prod 
						AND i.Id_Lista_Precio = @Id_Lista_Precio)
					,0) 


SET @Retorno = (@Retorno * (1 - (dbo.SF_Desc_GF(@Cli,GETDATE())/100)))

/*Si tiene un contrato de LICENCIA se le modifica el precio*/
IF(@Id_Contrato_Licencia <> 0)
BEGIN
	SET @Porc_Bonif_Cont_Lic = ISNULL((SELECT Porc_Bonif FROM Contratos WHERE Id_Contrato = @Id_Contrato_Licencia),0)
	SET @Retorno = (@Retorno * (100-@Porc_Bonif_Cont_Lic))/100
END

/*Si tiene un contrato de DESCUENTOS EN CUOTA SOCIAL se le modifica el precio*/

IF (@Id_Contrato_Desc_CS <> 0)
BEGIN

	SET @Porc_Bonif_Cont_DescCS = ISNULL((SELECT SUM(Porc_Bonif) FROM Contratos WHERE Id_Cliente = @Cli AND Id_Tipo_Con = 10 AND Fecha_Desde <= @Fecha AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL) AND ACTIVO=1),0)
	SET @Imp_Bonif_Cont_DescCS	= ISNULL((SELECT SUM(Imp_Bonif) FROM Contratos WHERE Id_Cliente = @Cli AND Id_Tipo_Con = 10 AND Fecha_Desde <= @Fecha AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL) AND ACTIVO=1),0)
	
	/*Se modifica esta parte del codigo por pedido en el ticket #20194
	SET @Porc_Bonif_Cont_DescCS = ISNULL((SELECT Porc_Bonif FROM Contratos WHERE Id_Contrato = @Id_Contrato_Desc_CS),0)
	SET @Imp_Bonif_Cont_DescCS	= ISNULL((SELECT Imp_Bonif FROM Contratos WHERE Id_Contrato = @Id_Contrato_Desc_CS),0)
	*/
	
	IF ((@Porc_Bonif_Cont_DescCS <> 0) AND (@Imp_Bonif_Cont_DescCS <> 0))
	BEGIN
		/*Si le pusieron Porcentaje de Descuento e importe de Descuento, prevalece el Porcentaje*/
		SET @Imp_Bonif_Cont_DescCS = 0
	END

	IF @Porc_Bonif_Cont_DescCS <> 0
	BEGIN
		SET @Retorno = (@Retorno * (100-@Porc_Bonif_Cont_DescCS))/100		
	END
	
	IF @Imp_Bonif_Cont_DescCS <> 0
	BEGIN
		IF @Imp_Bonif_Cont_DescCS < @Retorno
		BEGIN
			SET @Retorno = @Retorno - @Imp_Bonif_Cont_DescCS
		END
		ELSE
		BEGIN
			SET @Retorno = 0
		END
	END	
END


/*Si tiene un contrato de DESCUENTOS EN BECA se le modifica el precio*/
IF (@Id_Contrato_Beca <> 0)
BEGIN
	SET @Porc_Bonif_Cont_Beca = ISNULL((SELECT Porc_Bonif FROM Contratos WHERE Id_Contrato = @Id_Contrato_Beca),0)
	SET @Imp_Bonif_Cont_Beca	= ISNULL((SELECT Imp_Bonif FROM Contratos WHERE Id_Contrato = @Id_Contrato_Beca),0)

	IF ((@Porc_Bonif_Cont_Beca <> 0) AND (@Imp_Bonif_Cont_Beca <> 0))
	BEGIN
		/*Si le pusieron Porcentaje de Descuento e importe de Descuento, prevalece el Porcentaje*/
		SET @Imp_Bonif_Cont_Beca = 0
	END

	IF @Porc_Bonif_Cont_Beca <> 0
	BEGIN
		SET @Retorno = (@Retorno * (100-@Porc_Bonif_Cont_Beca))/100		
	END
	
	IF @Imp_Bonif_Cont_Beca <> 0
	BEGIN
		IF @Imp_Bonif_Cont_Beca < @Retorno
		BEGIN
			SET @Retorno = @Retorno - @Imp_Bonif_Cont_Beca
		END
		ELSE
		BEGIN
			SET @Retorno = 0
		END
	END	
END
/*Se agrega esta linea por pedido de contratos de descuentos en ticket 19635*/
SET @flag_Existe_contrato_pandemia = ISNULL((SELECT 1 FROM CONTRATOS WHERE Id_Tipo_CON = 35 /*Contrato Pandemia*/ AND Id_Cliente = @Cli AND Fecha_Desde<= @Fecha AND (Fecha_HASTA >= @Fecha OR FECHA_HASTA IS NULL)),0)
IF(@flag_Existe_contrato_pandemia = 1)
BEGIN
	SET @Retorno = @Retorno * 0.9
END
/*Si la suma de los desc es negativo*/
IF(@Retorno < 0) SET @Retorno = 0 

/************************************************************************************************************************/
/* SI TIENE CONTRATO DE RECUPERO DE GASTOS SE AGREGA EL IMPORTE TOTAL DE ESE CONTRATO AL DE CS - ESTO RIGE A PARTIR DE 2/2022 */

SET @Flag_Existe_Contrato_Recargo = 0

SET @Flag_Existe_Contrato_Recargo = ISNULL((SELECT SUM(C.IMP_BONIF) FROM Contratos C
															 WHERE C.Id_Cliente = @Cli 
															 AND C.Id_Tipo_Con IN (40) 
															 AND C.Fecha_Desde <= @Fecha 
															 AND (C.Fecha_Hasta >= @Fecha OR C.Fecha_Hasta IS NULL)
															 AND C.ACTIVO = 1),0)

IF(@Flag_Existe_Contrato_Recargo > 0)
BEGIN
	SET @Retorno = @Retorno + @Flag_Existe_Contrato_Recargo
END

/****************************************/

-- Se coloca la validacion < 4 a pedido en el ticket Nº #002163 
IF (@Id_Tipo_Cli_INT IN (1000,1106,1115,1122) /*AND @Fecha_Alta > '20220120'*/ AND @Edad < 4) -- 28/4/22 Flor: Se agrega la categoría 1106 por pedido en ticket #001423
BEGIN			--04/07/2022 se agregan categorias 1115, 1122 pedido ticket #000558
	IF @Id_Tipo_Cli_Tit IN (1003,1002,1130,1010,1055,1060,1065,1070,1125,1020) 
	BEGIN
		SET @Retorno = 0
	END	
END   
/****************************************/

RETURN ISNULL(@Retorno,0)
END
GO

CREATE FUNCTION [dbo].[SF_CS_Precio_Persona_SDescFam](@Cli INT, @Fecha DATETIME) 
