   17- BECA OLIMPICOS*/
 
SET @Id_Contrato_Beca = ISNULL((SELECT MAX(Id_Contrato) FROM Contratos WHERE Id_Cliente = @Cli AND Id_Tipo_Con  in (4, 14, 15, 16, 17)  AND Fecha_Desde <= @Fecha AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL)),0)

