CREATE FUNCTION [dbo].[SF_Cantidad_Membresia] (@Id_Cliente INT)
RETURNS INT
AS
BEGIN


DECLARE @Cant_Cbtes_Cliente		INT
DECLARE @Flag_Renovacion		TINYINT
DECLARE @Fecha_Ult_Mem			DATETIME
DECLARE @Id_Trans				INT

SET @Id_Trans = ISNULL((select  MAX(i.id_trans) 
					from cbtes_items i, cbtes c 
					where i.id_trans =c.id_trans
					and i.id_producto='CS' 
					and c.id_estado_cbte <>3
					and i.id_cliente=@Id_Cliente),0)

SET @Fecha_Ult_Mem = ISNULL((select MAX(Fecha_QA) from cbtes_items where id_producto='CS' and Id_trans=@Id_Trans  group by id_trans having count(item)>=12),'19000101')

SET @Cant_Cbtes_Cliente = ISNULL((select count(*)
							from cbtes
							where 
							id_trans in (Select id_trans from cbtes_items where id_producto='CS' and id_cliente=@Id_Cliente  group by id_trans having count(item)>=12)
							and id_Estado_cbte=2
							HAVING COUNT(*) >=1),0)
							
IF 	@Fecha_Ult_Mem	< '20200201'
		RETURN 	ISNULL(@Flag_Renovacion,0)				



IF @Cant_Cbtes_Cliente = 0
	RETURN 	ISNULL(@Flag_Renovacion,0)

IF @Cant_Cbtes_Cliente > 1
	SET @Flag_Renovacion = 2
ELSE IF @Cant_Cbtes_Cliente = 1
	SET @Flag_Renovacion = 1
	
RETURN 	ISNULL(@Flag_Renovacion,0)

END
GO

CREATE FUNCTION [dbo].[SF_Categ](@Cli INT, @Fecha DATETIME)
RETURNS INT
AS
BEGIN
DECLARE @Edad INT
DECLARE @fecha_nac DATETIME
DECLARE @Categ INT
DECLARE @Hasta INT
DECLARE @Categ_Sig INT
DECLARE @Categ_Sig_Fem INT
DECLARE @Retorno INT
DECLARE @Hoy DATETIME
DECLARE @Sexo CHAR(1)

SET @Hoy = LEFT(CONVERT(varchar, GetDate(),112),6) + '01'

IF @Fecha < @Hoy 
BEGIN
 --tomamos del historico Esta consulta estaba comparando mal el id_tipo_cli con el id_cliente pasado por parametro 07/07/2025 Maca
 --SET @Retorno = (SELECT TOP 1 Id_Tipo_cli FROM Clientes_Hist WHERE Id_Tipo_Cli = @Cli AND Fecha <= @Fecha ORDER BY Fecha DESC)
 SET @Retorno = (SELECT TOP 1 Id_Tipo_cli FROM Clientes_Hist WHERE Id_Cliente = @Cli AND Fecha <= @Fecha ORDER BY Fecha DESC)
END

IF @Fecha >= @Hoy OR ISNULL(@Retorno,0) = 0
BEGIN
 SET @fecha_nac = ISNULL((SELECT fecha_nac FROM clientes WHERE id_cliente = @cli), '19000101')
 SET @Edad = (SELECT datediff(yy,@fecha_nac,@fecha))

 --IF DATEPART(mm,@fecha_nac) >= DATEPART(mm,@fecha)
 SET @Edad =[dbo].[SF_Edad_Categ](@fecha, @fecha_nac)                   
         
 SET @Sexo = (SELECT Sexo FROM clientes WHERE id_cliente = @cli)
 SET @Categ = (SELECT id_tipo_cli FROM clientes WHERE id_cliente = @cli)

 SET @Hasta = (SELECT Hasta_Edad FROM clientes_tipos WHERE id_tipo_cli = @Categ)    
 SET @Categ_Sig  = (SELECT Id_Tipo_Cli_Sig FROM clientes_tipos WHERE  id_tipo_cli = @Categ)    
 SET @Categ_Sig_Fem = (SELECT Id_tipo_cli_sig_Fem FROM clientes_tipos WHERE  id_tipo_cli = @Categ)    

 IF (ISNULL(@Categ_Sig,0) = 0) SET @Retorno = @Categ
 ELSE
  IF (ISNULL(@Hasta,0) = 0) SET @Retorno = @Categ
  ELSE
   IF (@Edad >  @Hasta)
      IF @Sexo = 'F' AND (ISNULL(@Categ_Sig_Fem,0) <> 0) 
      SET @Retorno = @Categ_Sig_Fem
      ELSE
      SET @Retorno = @Categ_Sig
   ELSE
    SET @Retorno = @Categ
END
      

RETURN @Retorno
END
GO


CREATE FUNCTION [dbo].[SF_Categ_Precio](@Id_Cliente INT,@Fecha DATETIME,@Lista INT)
RETURNS DECIMAL(12,2)
AS
BEGIN
DECLARE @Retorno			DECIMAL(12,2)
DECLARE @Prod				CHAR(14)
DECLARE @Id_Tipo_Cli		INT
DECLARE @Id_ContratoActiv	INT


SET  @Id_Tipo_Cli = (SELECT dbo.SF_Categ(@Id_Cliente, @Fecha))

/*Si tiene un contrato de actividad a la fecha pasada.
Entonces el precio es $0 porque el precio se calcula en el 
contrato de la actividad*/
SET @Id_ContratoActiv = ISNULL((SELECT MAX(Id_Contrato) FROM Contratos WHERE Id_Cliente = @Id_Cliente AND Id_Tipo_Con = 3 /*Actividades*/ AND (Fecha_Baja IS NULL OR Fecha_Baja>=@Fecha) AND (Fecha_Hasta IS NULL OR Fecha_Hasta>=@Fecha) AND (Fecha_Desde<=@Fecha)), 0)

/*Si no hay ningun contrato de actividad en la fecha devuelve 0*/
IF(@Id_ContratoActiv <> 0)
BEGIN
	SET @Retorno = 0
	RETURN @Retorno /*Se va de la funci{on, no continua*/
END

/*Busca el producto que le corresponde al cliente*/
SET @Prod = dbo.SF_Prod(@Id_Cliente, @Fecha)

/*Segun el producto busca el precio que tiene ese producto*/
SET @Retorno = (SELECT Precio_Gravado FROM Productos WHERE Id_Producto = @Prod)	

RETURN @Retorno
END
GO



CREATE FUNCTION [dbo].[SF_Categ_PrecioActualiza](@Id_Cliente INT,@Fecha DATETIME,@Lista INT)
RETURNS DECIMAL(12,2)
AS
BEGIN
DECLARE @Retorno			DECIMAL(12,2)
DECLARE @Prod				CHAR(14)
DECLARE @Id_Tipo_Cli		INT
DECLARE @Id_ContratoActiv	INT
DECLARE @Id_Familia_CS		INT 
DECLARE @Id_Familia_CS_Para		INT 

SET  @Id_Tipo_Cli = (SELECT dbo.SF_Categ(@Id_Cliente, @Fecha))

/*Si tiene un contrato de actividad a la fecha pasada.
Entonces el precio es $0 porque el precio se calcula en el 
contrato de la actividad*/
SET @Id_ContratoActiv = ISNULL((SELECT MAX(Id_Contrato) FROM Contratos WHERE Id_Cliente = @Id_Cliente AND Id_Tipo_Con = 3 /*Actividades*/ AND (Fecha_Baja IS NULL OR Fecha_Baja>=@Fecha) AND (Fecha_Hasta IS NULL OR Fecha_Hasta>=@Fecha) AND (Fecha_Desde<=@Fecha)), 0)

/*Si no hay ningun contrato de actividad en la fecha devuelve 0*/
IF(@Id_ContratoActiv <> 0)
BEGIN
	SET @Retorno = 0
	RETURN @Retorno /*Se va de la funci{on, no continua*/
END

/*Busca el producto que le corresponde al cliente*/
SET @Prod = dbo.SF_Prod(@Id_Cliente, @Fecha)

/*Segun el producto busca el precio que tiene ese producto*/
--SET @Retorno = (SELECT Precio_Gravado FROM Productos WHERE Id_Producto = @Prod)	
SET @Retorno = (SELECT CASE 
							WHEN Precio_Nuevo <> 0 and Fecha_Desde<=@Fecha THEN ISNULL(Precio_Nuevo, 0)
							ELSE ISNULL(Precio, 0)
						END AS Precio 
						FROM Prod_Listas_Precios_Items WHERE Id_Producto = @Prod and Id_Lista_Precio=@Lista)	

SET @Id_Familia_CS = ISNULL((SELECT Id_Familia FROM Productos WHERE Id_Producto=@Prod),0)
SET @Id_Familia_CS_Para = ISNULL(CONVERT(INT,dbo.CF_xParam('Fam_CuotasSoc')),0)

IF (@Id_Familia_CS = @Id_Familia_CS_Para)
BEGIN
	SET @Retorno = (@Retorno * (1 - (dbo.SF_Desc_GF(@Id_Cliente,@Fecha)/100)))
	RETURN @Retorno
END

RETURN @Retorno
END
GO

CREATE FUNCTION [dbo].[SF_Cbte_Compra_Coef_Saldado](@Id_Trans INT,@Fecha DATETIME) 
RETURNS DECIMAL(9,7)
AS
BEGIN

DECLARE @Imp_Cancelado DECIMAL(16,2),
        @Imp_Total     DECIMAL(16,2),
        @Saldo         DECIMAL(16,2),
        @Id_Cond_Pago  INT,
        @Compromete_Factura  SMALLINT,
        @Coef          DECIMAL(7,5)

SET @Id_Cond_Pago = (SELECT Id_Cond_Pago FROM Cbtes WHERE Id_Trans = @Id_Trans)
IF @Id_Cond_Pago = 1 
BEGIN
   SET @Coef = 1
   RETURN @Coef
END   
   
SET @Imp_Total = (SELECT Imp_Total FROM Cbtes WHERE Id_Trans = @Id_Trans)
IF @Imp_Total = 0 
BEGIN
   SET @Coef = 1
   RETURN @Coef
END   


SET @Compromete_Factura = (SELECT Compromete_Compras FROM Cbtes C, Cbtes_Tipos T
       WHERE C.Id_Trans = @Id_Trans
        AND C.Id_Estado_Cbte NOT IN (0,3)
        AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte)
  
IF ISNULL(@Compromete_Factura,0) = 0
BEGIN
   SET @Coef = 0
   RETURN @Coef
END   

IF @Compromete_Factura = 1               -----------------Facturas
BEGIN
   SET @Imp_Cancelado = ISNULL((SELECT SUM(A.Importe) FROM Cbtes_Aplica A, Cbtes C, Cbtes_Tipos T
    WHERE C.Id_Trans = A.Id_Trans_D
    AND A.Id_Trans = @Id_Trans
    AND C.Id_Estado_Cbte NOT IN (0,3)
    AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
    AND C.Fecha <= @Fecha
    AND (T.Compromete_Compras = -1 OR T.Compromete_Pagos IN (1,-1))),0)
   IF @Imp_Cancelado > @Imp_Total
   BEGIN
      SET @Imp_Cancelado = @Imp_Total
   END   
END  
ELSE                                     --------------notas de credito
BEGIN
   -----------------------------------------------aplicacion directa para las notas de credito
   SET @Imp_Cancelado = ISNULL((SELECT SUM(A.Importe) FROM Cbtes_Aplica A, Cbtes C, Cbtes_Tipos T
    WHERE C.Id_Trans = A.Id_Trans
    AND A.Id_Trans_D = @Id_Trans
    AND A.Id_Trans <> 0
    AND C.Id_Estado_Cbte NOT IN (0,3)
    AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
    AND C.Fecha <= @Fecha
    AND T.Compromete_Factura = 1),0)
    
   -----------------------------------------------aplicacion por recibos para las notas de credito
   SET @Imp_Cancelado = @Imp_Cancelado + 
                           ( ISNULL((SELECT SUM(A.Importe) FROM Cbtes_Aplica A, Cbtes C, Cbtes_Tipos T
    WHERE C.Id_Trans = A.Id_Trans_D
    AND A.Id_Trans = @Id_Trans
    AND C.Id_Estado_Cbte NOT IN (0,3)
    AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
    AND C.Fecha <= @Fecha
    AND (T.Compromete_compras = -1 OR T.Compromete_pagos IN (1,-1))),0)
                         ) * -1
    
    
   IF @Imp_Cancelado > @Imp_Total
   BEGIN
      SET @Imp_Cancelado = @Imp_Total
   END   
END

RETURN @Imp_Cancelado / @Imp_Total
  
  
END
GO

