CREATE FUNCTION [dbo].[SF_Cbte_Saldo](@trans INT,@fecha datetime) 
RETURNS DECIMAL(16,2)
AS
BEGIN
DECLARE @Retorno DECIMAL(17,5)
		,@FechaCbte datetime
		,@Compromete_Factura SMALLINT
		,@Compromete_Recibos SMALLINT


SELECT @fechacbte = C.fecha , @Compromete_Factura = T.Compromete_Factura ,@Compromete_Recibos = T.Compromete_Recibos
					FROM Cbtes C, Cbtes_Tipos T 
					WHERE C.Id_Trans = @trans 
						AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte

if @fecha < @fechacbte 
   RETURN 0

set @Retorno = 0

IF @Compromete_Factura = 1
BEGIN
	SET @Retorno = isnull(
							(
								SELECT SUM(ISNULL(A.importe,0)) 
									FROM Cbtes_Aplica A, Cbtes D , Cbtes_tipos T
									WHERE A.Id_Trans = @trans AND A.id_trans_D = D.Id_trans
										AND d.id_estado_cbte in (1,2,4)
										AND D.Id_Tipo_Cbte = t.Id_Tipo_Cbte
										AND (T.Compromete_Recibos in (1,-1) OR T.compromete_factura = -1)
										AND D.Fecha < @Fecha + 1
							)
					   ,0)
END     
ELSE 
BEGIN
	IF @Compromete_Factura = -1
	BEGIN
		SET @Retorno = isnull(
								(
									SELECT SUM(ISNULL(A.importe,0)) 
										FROM Cbtes_Aplica A, Cbtes O , Cbtes_tipos T
										WHERE A.Id_Trans_D = @trans AND A.id_trans = O.Id_trans
											AND o.id_estado_cbte in (1,2,4)
											AND o.Id_Tipo_Cbte = t.Id_Tipo_Cbte
											AND o.fecha < @fecha + 1
											AND T.Compromete_Factura in (1,-1)
								)
						   ,0)

		SET @Retorno = @Retorno + isnull(
								(
									SELECT SUM(ISNULL(A.importe,0)) 
										FROM Cbtes_Aplica A, Cbtes D , Cbtes_tipos T
										where A.Id_Trans = @trans AND A.id_trans_D = D.Id_trans
											and D.id_estado_cbte in (1,2,4)
											and D.Id_Tipo_Cbte = t.Id_Tipo_Cbte
											and T.Compromete_Recibos in (1,-1) 
											AND D.Fecha < @Fecha + 1
								) * -1
						   ,0)
                  
	END
END

IF @Compromete_Recibos IN (1,-1)
BEGIN
	SET @Retorno = isnull(
							(
									SELECT SUM(ISNULL(A.importe,0)) 
										FROM Cbtes_Aplica A, Cbtes O , Cbtes_tipos T
										WHERE A.Id_Trans_D = @trans AND A.id_trans = O.Id_trans
											AND o.id_estado_cbte in (1,2,4)
											AND o.Id_Tipo_Cbte = t.Id_Tipo_Cbte
											AND o.fecha < @fecha + 1
											AND T.Compromete_Factura in (1,-1)
							)
					   ,0)
END


set @Retorno =  (SELECT Imp_Total FROM Cbtes WHERE Id_Trans = @trans )- @Retorno
     
RETURN @Retorno
END
GO

CREATE  FUNCTION [dbo].[SF_Cbte_SaldoAnterior](@trans INT) 
RETURNS DECIMAL(12,2)
AS
BEGIN

DECLARE @Id_Cliente INT
DECLARE @Fecha_Mov DATETIME
DECLARE @Retorno DECIMAL(12,2)


SET @Retorno = 0

------------------------
IF ISNULL((SELECT Compromete_Factura FROM Cbtes C, Cbtes_Tipos T
           WHERE C.Id_Tipo_cbte = T.Id_Tipo_Cbte AND C.Id_Trans = @trans),0) = 0
   RETURN @Retorno       

SET @Id_Cliente = (SELECT Id_Cliente FROM Cbtes C WHERE C.Id_Trans = @trans)

IF @Id_Cliente IN (0,1) OR @trans = 0
   RETURN @Retorno       

SET @Fecha_Mov = (SELECT Fecha_Mov FROM Transacciones C WHERE C.Id_Trans = @trans)


SET @Retorno = ISNULL((SELECT sum(isnull(C1.imp_total,0) * T1.Compromete_Factura)                     --facturas del titular
                  FROM Cbtes C1,Cbtes_Tipos T1, transacciones l1 
                   WHERE C1.Id_Tipo_Cbte = T1.Id_Tipo_Cbte 
                   and l1.id_trans = c1.id_trans
                   and c1.Id_Cond_Pago <> 1
                   AND T1.Compromete_Factura IN (1,-1)
                   AND C1.Id_Cliente = @Id_Cliente
                   AND l1.Fecha_mov <= @Fecha_Mov
                   AND C1.Id_Estado_Cbte NOT IN( 0, 3)
                   and c1.id_trans <> @Trans),0)
                   
SET @Retorno = @Retorno + ISNULL((SELECT sum(isnull(C1.imp_total,0) * T1.Compromete_Factura)                   --!fact de grupo fam
                  FROM Cbtes C1,Cbtes_Tipos T1, transacciones l1 
                   WHERE C1.Id_Tipo_Cbte = T1.Id_Tipo_Cbte 
                   and l1.id_trans = c1.id_trans
                   and c1.Id_Cond_Pago <> 1
                   AND T1.Compromete_Factura IN (1,-1)
                   AND C1.Id_Cliente IN (SELECT Id_cliente FROM Clientes WHERE Id_cliente_Ref = @Id_Cliente)
                   AND l1.Fecha_mov <=  @Fecha_Mov
                   AND C1.Id_Estado_Cbte NOT IN( 0, 3)
                   and c1.id_trans <> @Trans),0)

SET @Retorno = @Retorno + ISNULL((SELECT sum(f.imp_total * T3.Compromete_Factura) 
                 FROM Cbtes C2,Cbtes_Tipos T2, transacciones l2,Cbtes_Aplica A, Cbtes F,Cbtes_Tipos T3   --fac ex grupo fam
                   WHERE C2.Id_Tipo_Cbte = T2.Id_Tipo_Cbte
                   and l2.id_trans = c2.id_trans
                   and c2.Id_Trans = A.Id_Trans_D 
                   and f.Id_Trans = a.Id_Trans
                   and f.Id_Estado_Cbte not IN( 0 , 3)
                   and f.Id_Tipo_Cbte = t3.Id_Tipo_Cbte 
                   and t3.Compromete_Factura in (1,-1)    
                   and f.Id_Cliente <> c2.Id_Cliente
                   AND  f.Id_Cliente not IN (SELECT Id_cliente FROM Clientes
                                      WHERE Id_cliente_Ref = c2.Id_Cliente)
                   AND T2.Compromete_Recibos IN (1,-1)
                   AND C2.Id_Cliente = @Id_Cliente
                   AND l2.Fecha_mov <= @Fecha_Mov
                   AND C2.Id_Estado_Cbte not IN( 0 , 3)
                   and c2.id_trans <> @Trans),0)


SET @Retorno = @Retorno - ISNULL((SELECT sum(C2.imp_total * T2.Compromete_Recibos) 
                 FROM Cbtes C2,Cbtes_Tipos T2, transacciones l2                   --recibos del tit
                   WHERE C2.Id_Tipo_Cbte = T2.Id_Tipo_Cbte
                   and l2.id_trans = c2.id_trans
                   AND T2.Compromete_Recibos IN (1,-1)
                   AND C2.Id_Cliente = @Id_Cliente
                   AND l2.Fecha_mov <= @Fecha_Mov
                   AND C2.Id_Estado_Cbte not IN( 0 , 3)
                   and c2.id_trans <> @Trans),0)
 
 

SET @Retorno = @Retorno - ISNULL((SELECT sum(C2.imp_total * T2.Compromete_Recibos) 
                  FROM Cbtes C2,Cbtes_Tipos T2, transacciones l2              --rec del grupo
                   WHERE C2.Id_Tipo_Cbte = T2.Id_Tipo_Cbte
                   and l2.id_trans = c2.id_trans
                   AND T2.Compromete_Recibos IN (1,-1)
                   AND C2.Id_Cliente IN (SELECT Id_cliente FROM Clientes WHERE Id_cliente_Ref = @Id_Cliente)
                   AND l2.Fecha_mov <= @Fecha_Mov
                   AND C2.Id_Estado_Cbte not IN( 0 , 3)
                   and c2.id_trans <> @Trans),0)



RETURN @Retorno
END
GO

create FUNCTION [dbo].[SF_Cbte_Vta_Coef_Saldado](@Id_Trans INT,@Fecha DATETIME) 
RETURNS DECIMAL(9,7)
AS
BEGIN

DECLARE @Imp_Cancelado DECIMAL(16,2),
        @Imp_Total     DECIMAL(16,2),
        @Saldo         DECIMAL(16,2),
        @Id_Cond_Pago  INT,
        @Compromete_Factura       SMALLINT,
        @Coef          DECIMAL(7,5)

SET @Id_Cond_Pago = (SELECT Id_Cond_Pago FROM Cbtes WHERE Id_Trans = @Id_Trans)
IF @Id_Cond_Pago = 1 
BEGIN
   SET @Coef = 1
   RETURN @Coef
END   
   
SET @Imp_Total = (SELECT Imp_Total FROM Cbtes WHERE Id_Trans = @Id_Trans)
IF @Imp_Total = 0 
BEGIN
   SET @Coef = 1
   RETURN @Coef
END   


SET @Compromete_Factura = (SELECT Compromete_Factura FROM Cbtes C, Cbtes_Tipos T
       WHERE C.Id_Trans = @Id_Trans
        AND C.Id_Estado_Cbte NOT IN (0,3)
        AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte)
  
IF ISNULL(@Compromete_Factura,0) = 0
BEGIN
   SET @Coef = 0
   RETURN @Coef
END   

IF @Compromete_Factura = 1               -----------------Facturas
BEGIN
   SET @Imp_Cancelado = ISNULL((SELECT SUM(A.Importe) FROM Cbtes_Aplica A, Cbtes C, Cbtes_Tipos T
    WHERE C.Id_Trans = A.Id_Trans_D
    AND A.Id_Trans = @Id_Trans
    AND C.Id_Estado_Cbte NOT IN (0,3)
    AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
    AND C.Fecha <= @Fecha
    AND (T.Compromete_Factura = -1 OR T.Compromete_Recibos IN (1,-1))),0)
   IF @Imp_Cancelado > @Imp_Total
   BEGIN
      SET @Imp_Cancelado = @Imp_Total
   END   
END  
ELSE                                     --------------notas de credito
BEGIN
   -----------------------------------------------aplicacion directa para las notas de credito
   SET @Imp_Cancelado = ISNULL((SELECT SUM(A.Importe) FROM Cbtes_Aplica A, Cbtes C, Cbtes_Tipos T
    WHERE C.Id_Trans = A.Id_Trans
    AND A.Id_Trans_D = @Id_Trans
    AND A.Id_Trans <> 0
    AND C.Id_Estado_Cbte NOT IN (0,3)
    AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
    AND C.Fecha <= @Fecha
    AND T.Compromete_Factura = 1),0)
    
   -----------------------------------------------aplicacion por recibos para las notas de credito
   SET @Imp_Cancelado = @Imp_Cancelado + 
                           ( ISNULL((SELECT SUM(A.Importe) FROM Cbtes_Aplica A, Cbtes C, Cbtes_Tipos T
    WHERE C.Id_Trans = A.Id_Trans_D
    AND A.Id_Trans = @Id_Trans
    AND C.Id_Estado_Cbte NOT IN (0,3)
    AND T.Id_Tipo_Cbte = C.Id_Tipo_Cbte
    AND C.Fecha <= @Fecha
    AND (T.Compromete_Factura = -1 OR T.Compromete_Recibos IN (1,-1))),0)
                         ) * -1
    
    
   IF @Imp_Cancelado > @Imp_Total
   BEGIN
      SET @Imp_Cancelado = @Imp_Total
   END   
END

RETURN @Imp_Cancelado / @Imp_Total
  
  
END
GO


CREATE FUNCTION [dbo].[SF_Cbte_Vta_Coef_Saldado_Rec](@Id_TransFC INT,@Id_TransRC INT) 
RETURNS DECIMAL(9,7)
AS
BEGIN

-- Falta tener en cuenta los recibos y agregar fecha de aplicacion en cbtes_aplica
--SET @Fecha = convert(char(8),GETDATE() + 1,112)

DECLARE @Imp_Fc       DECIMAL(16,2),
        @Imp_Aplicado       DECIMAL(16,2),
        @Coef          DECIMAL(7,6)

SET @Imp_Fc = (SELECT Imp_total FROM Cbtes WHERE Id_Trans = @Id_TransFC)
--Se comente siguiente linea y se agrega nueva con un SUM al importe ya que solo debe devolver un valor la sub consulta
--SET @Imp_Aplicado = (SELECT Importe FROM Cbtes_Aplica WHERE Id_Trans = @Id_TransFC AND Id_Trans_D = @Id_TransRC)
SET @Imp_Aplicado = (SELECT SUM (Importe) FROM Cbtes_Aplica WHERE Id_Trans = @Id_TransFC AND Id_Trans_D = @Id_TransRC)

SET @Coef = @Imp_Aplicado / @Imp_Fc

RETURN @Coef
  
END
GO

CREATE FUNCTION [dbo].[SF_Cbu_Validar](@nro varchar(22) )
RETURNS TINYINT
as
begin
declare @r tinyint

If  ISNULL(@nro,'') = ''
begin
	set @r = 0
	return @r
end

/* primer bloque */
declare @i int
declare @temp int
declare @bco_dv int
declare @suc_dv int
declare @bloque2_dv int
declare @temp_alfa varchar(4)


set @bco_dv = (CAST(SUBSTRING(@nro,4,1) as int)) 
set @suc_dv = (CAST(SUBSTRING(@nro,8,1) as int))
set @bloque2_dv = (CAST(SUBSTRING(@nro,22,1) as int))

set @temp = 0
set @i = 1
while @i <= 7
BEGIN
      set @temp = @temp + (CAST(SUBSTRING(@nro,@i,1) as int)) * (CASE @i
								WHEN 1 THEN 7
								WHEN 2 THEN 1
								WHEN 3 THEN 3
								WHEN 4 THEN 9
								WHEN 5 THEN 7
								WHEN 6 THEN 1
								WHEN 7 THEN 3
								END)
	  set @i = @i + 1
      
END
set @temp_alfa =  RIGHT(CAST(ltrim(RTrim(@temp)) as varchar(4)),1)
set @temp = CAST(@temp_alfa as int)
IF @temp = 0
BEGIN
	set @temp = 10
END

If  @suc_dv <> (10 - @temp)
begin
	set @r = 0
	return @r
end

/* segundo bloque */


set @temp = 0
set @i = 9
while @i <= 21
BEGIN
      set @temp = @temp +(CAST(SUBSTRING(@nro,@i,1) as int)) * (CASE @i
								WHEN 9 THEN 3
								WHEN 10 THEN 9
								WHEN 11 THEN 7
								WHEN 12 THEN 1
								WHEN 13 THEN 3
								WHEN 14 THEN 9
								WHEN 15 THEN 7
								WHEN 16 THEN 1
								WHEN 17 THEN 3
								WHEN 18 THEN 9
								WHEN 19 THEN 7
								WHEN 20 THEN 1
								WHEN 21 THEN 3
								END)
      
	  set @i = @i + 1
END

set @temp_alfa =  CAST(@temp as varchar(4))
set @temp_alfa = RIGHT(ltrim(RTrim(@temp_alfa)),1)
set @temp = CAST(@temp_alfa as int)
IF @temp = 0
BEGIN
	set @temp = 10
END

If  @bloque2_dv <> (10 - @temp)
begin
	set @r = 0
	return @r
end
set @r = 1
return @r
END
GO

CREATE FUNCTION [dbo].[SF_Checksum](@cd_banda varchar(36) )
RETURNS CHAR(1)
as
begin
declare @Tar int
declare @LSUM int
declare @IPOSITION int
declare @ICORRECTION int
declare @i int
declare @J int
declare @nr_rta int

set @Tar = 0
set @LSUM = 0
set @IPOSITION = 0
set @ICORRECTION = 0
set @i = Len(RTrim(@cd_banda))   

while @i > 0
BEGIN
      set @J = Ascii(substring(RTrim(@cd_banda), @i, 1)) - Ascii('0')
      SET @nr_rta = CASE (@IPOSITION - @ICORRECTION) 
						WHEN 0 THEN 1
						WHEN 1 THEN 3
						WHEN 2 THEN 9
						WHEN 3 THEN 27
						WHEN 4 THEN 81
						WHEN 5 THEN 243
						WHEN 6 THEN 729
						WHEN 7 THEN 2187
						WHEN 8 THEN 6561
						WHEN 9 THEN 19683
					END
						
      SET @LSUM = @LSUM + (@nr_rta * @J )
      set @IPOSITION = @IPOSITION + 1

      If @IPOSITION%10 = 0
            begin
        set @ICORRECTION = @ICORRECTION + 10
            end
            SET @i = @i - 1          

END


    SET @i = @LSUM % 11
    If @i = 10
            begin
            set @i = 0
            end

return Char(Ascii('0') + @i)
END
GO

CREATE FUNCTION [dbo].[SF_Cli_Altas_Mes](@Tipo INT, @Mes SMALLINT, @Anio INT)
RETURNS INT
AS
BEGIN

DECLARE @Altas INT
DECLARE @Fecha DATETIME

SET @Fecha = (SELECT
				CAST(
					CAST(@Anio AS VARCHAR(4)) +
					RIGHT('0' + CAST(@Mes AS VARCHAR(2)), 2) +
					RIGHT('0' + CAST(01 AS VARCHAR(2)), 2) 
				AS DATETIME))
				
SET @Fecha = (SELECT dbo.SF_EOMONTH(@Fecha))


SET @Altas =	(SELECT COUNT(DISTINCT(Id_Cliente))
				FROM Clientes_Hist
				WHERE
				dbo.SF_Cli_Categ_Mes(Id_Cliente, @Fecha)=@Tipo
				AND DATEPART(mm, fecha_alta) = @Mes
				AND DATEPART(YY, fecha_alta) = @Anio
				)
       
RETURN @Altas
END
GO

