CREATE  FUNCTION [dbo].[SF_Col](@Linea VARCHAR(1000),@sep_num CHAR(1),@sep_texto CHAR(1),@cero_en_vacio TINYINT, @col SMALLINT) 
RETURNS VARCHAR(250)
AS
BEGIN

DECLARE @Retorno CHAR(250)
DECLARE @Tam SMALLINT, @pos SMALLINT, @actual CHAR(1)
DECLARE @col_acutal SMALLINT,@procesando TINYINT
DECLARE @pos_inicial SMALLINT

IF (ISNULL(@sep_texto,'') <> '') 
BEGIN
   SET @Linea  = REPLACE(@Linea,@sep_texto,'')
END
                 
set @retorno = NULL    
SET @Tam = LEN(@Linea)
SET @pos = 0
SET @col_acutal = 1
IF @col = 1
	BEGIN
	SET @procesando = 1
	SET @pos_inicial = 1
	END
ELSE	
	SET @procesando = 0
      
                 
WHILE (@pos <= @Tam)
BEGIN
    SET @pos = @pos + 1
    IF (@pos > @Tam)
		BEGIN
		IF @procesando = 1
			BEGIN
			SET @Retorno = SUBSTRING(@Linea,@pos_inicial,@pos - @pos_inicial )
			BREAK
			END
		END
	-----------------------------------------------------------	
	SET @actual = SUBSTRING(@Linea,@pos,1)
	
	IF @actual = @sep_num
		BEGIN
		IF @procesando = 1
			BEGIN
			SET @Retorno = SUBSTRING(@Linea,@pos_inicial,@pos - @pos_inicial)
			BREAK
			END
		ELSE
			BEGIN	
			SET @col_acutal = @col_acutal + 1
			IF @col_acutal = @col 
			   BEGIN
			   SET @procesando = 1
			   SET @pos_inicial = @pos + 1
			   END
			CONTINUE	
			END
		END
	ELSE
		CONTINUE
END
IF @Retorno = '' AND @cero_en_vacio = 1
	SET @Retorno = '0'	

RETURN @Retorno
END
GO

CREATE FUNCTION [dbo].[SF_Control_Tiene_Contrato_CS](@pId_Cliente INT, @pFecha DATETIME) 
RETURNS INT
AS
BEGIN
DECLARE @Flag_Tiene_Contrato_CS INT

SET @Flag_Tiene_Contrato_CS =	ISNULL(
										(SELECT MAX(Id_Contrato)
										FROM Contratos
										WHERE
										Id_Tipo_Con IN (1)
										AND CONVERT (DATE, Fecha_Desde) <= CONVERT(DATE, @pFecha) 
										AND (CONVERT (DATE, Fecha_Hasta) > = CONVERT(DATE, @pFecha) OR Fecha_Hasta IS NULL)
										AND Id_Cliente = @pId_Cliente)
										, 0)
								
RETURN ISNULL(@Flag_Tiene_Contrato_CS, 0)
END
GO

