CREATE FUNCTION [dbo].[SF_Cotiza](@pass CHAR(20))
RETURNS VARCHAR (50)
AS
BEGIN


DECLARE @Word CHAR(20)
DECLARE @Mask CHAR(100)
DECLARE @Dest CHAR(20)
DECLARE @Pos  TINYINT
DECLARE @uno CHAR(1)
DECLARE @Long INT

SET @Long = LEN(LTRIM(RTRIM(@pass)))
SET @Word = @pass
SET @Mask = '!@#$%^&*!@#$%^&*!@#$%^&*!@#$%^&*!@#$%^&*!@#$%^&*!@#$%^&*!@#$%^&*'
SET @Pos = 1
SET @Dest = ''
WHILE @Pos <= @Long
BEGIN
    SET @uno  = CHAR(ASCII(SUBSTRING(@Word,@Pos,1)) ^ ASCII(SUBSTRING(@Mask,@Pos,1)))
    SET @Dest = LTRIM(RTRIM(@Dest)) + @uno
    SET @Pos =  @Pos + 1

END
RETURN @Dest
END
GO

CREATE FUNCTION [dbo].[SF_Cta_Cont](@Alias INT,@Fecha DATETIME) 
RETURNS INT
AS
BEGIN

DECLARE @Retorno INT

SET @Retorno = (SELECT MAX(Id_Cta_Contable) 
		FROM Pla_Ctas_Cuentas_Contables C, dbo.Plan_Ctas T, Plan_Ctas_Ejercicios E
		WHERE C.Id_Plan_Cta = T.Id_Plan_Cta
		AND E.Id_Ejercicio = T.Id_Ejercicio
		AND E.Fecha_Inicio < @Fecha + 1
		AND E.Fecha_Cierre >= @Fecha
		AND C.Alias = @Alias
	) 
		

RETURN @Retorno
END
GO

CREATE FUNCTION [dbo].[SF_Cta_Contable](@Alias SMALLINT, @Fecha DATETIME)
RETURNS INT
AS
BEGIN

DECLARE @Id_Ejercicio INT;
DECLARE @Id_Plan_Cta INT;
DECLARE @Id_Cta_Contable INT;

SET @Id_Ejercicio = (SELECT Id_Ejercicio FROM Plan_Ctas_Ejercicios WHERE Fecha_Inicio<=@fecha AND Fecha_Cierre>=@fecha);
SET @Id_Plan_Cta = (SELECT Id_Plan_Cta FROM Plan_Ctas WHERE Id_Ejercicio=@Id_Ejercicio);
SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Alias=@Alias AND Id_Plan_Cta=@Id_Plan_Cta)

RETURN @Id_Cta_Contable

END
GO

CREATe FUNCTION [dbo].[SF_Cta_Contable_DeudaAnterior](@Alias SMALLINT, @Fecha DATETIME)
RETURNS INT
AS
BEGIN

DECLARE @Id_Ejercicio INT;
DECLARE @Id_Plan_Cta INT;
DECLARE @Id_Cta_Contable INT;

SET @Id_Ejercicio = (SELECT Id_Ejercicio FROM Plan_Ctas_Ejercicios WHERE Fecha_Inicio<=GETDATE() AND Fecha_Cierre>=GETDATE());
SET @Id_Plan_Cta = (SELECT Id_Plan_Cta FROM Plan_Ctas WHERE Id_Ejercicio=@Id_Ejercicio);
SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Alias=@Alias AND Id_Plan_Cta=@Id_Plan_Cta)

RETURN @Id_Cta_Contable

END
GO

