CREATE FUNCTION [dbo].[SF_DecAHex](@num varchar(20) )
RETURNS CHAR(8)
AS
BEGIN

DECLARE @card varchar(20)

SET  @card = @num
IF LEN(RTRIM(LTRIM(@num))) > 8
BEGIN
   set @card = substring(convert(char(17),convert(varbinary(10),cast(@num as decimal(12,0) )),2),9,8)
END



RETURN @card
END
GO


CREATE FUNCTION [dbo].[SF_Desc_GF](@Cli INT,@Fecha DATETIME) 
RETURNS DECIMAL(6,2)
AS

BEGIN
DECLARE @titular INT
declare @Id_Cli_Relac int
declare @retorno  DECIMAL(6,2)=0

SET @titular = ISNULL((SELECT Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @Cli),0)

IF @titular = 0
  return 0
-- si es titular sale

DECLARE @relacion INT
SET @relacion = ISNULL((SELECT Id_Cli_Relac FROM Clientes WHERE Id_Cliente = @Cli),0)

-- traigo el conyugue


DECLARE @titular_categ INT, @ID_CLI_TEMP INT,@FNAC DATETIME,@ID_CLI_RELAC_TEMP INT,@ORDEN INT

SET @titular_categ = ISNULL((SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @titular),0)
SET @Id_Cli_Relac = ISNULL((SELECT Id_Cli_Relac FROM Clientes WHERE Id_Cliente = @CLI),0)

IF @titular_categ in (1004 ,1007,1008,1012,1013,1017)   -- es acompñante no va desceunto o usuarios excepto jorge new
   return 0
   
If  isnull((select COUNT(*) from Clientes WHERE 
   ID_CLIENTE_REF = @titular                                                     -- si los integrantes del titular
   AND ID_CLI_RELAC IN (2,3)                                                     -- es conyugue o hijo
   AND FECHA_ALTA <= getdate() 
   AND ISNULL(FECHA_BAJA,getdate() + 1) > getdate() 
   and Id_Tipo_Cli in (1007,1008,1012,1013,1017)),0) > 0                         -- y es categoria usuarios retornar cero en descuento
   return 0

SET @ORDEN = 0


IF @Id_Cli_Relac = 2  /*Conyugue*/
	BEGIN
	   SET @RETORNO =  20    --descuento de conyuge
	   Return @RETORNO
	END

DECLARE GF_CURSOR CURSOR FOR
SELECT Id_Cliente, Fecha_Nac, Id_Cli_Relac
FROM Clientes 
WHERE 
ID_CLIENTE_REF = @titular
AND ID_CLI_RELAC IN (3) --Modifico 2017/11/15: el codigo de tipo de cliente pregunto solo por los hijos
AND FECHA_ALTA <= getdate() AND ISNULL(FECHA_BAJA,getdate() + 1) > getdate()
ORDER BY FECHA_NAC

OPEN GF_CURSOR 		
FETCH NEXT FROM GF_CURSOR INTO @ID_CLI_TEMP,@FNAC,@ID_CLI_RELAC_TEMP
WHILE @@FETCH_STATUS = 0
begin

	SET @ORDEN = @ORDEN + 1

	/*IF @ID_CLI_TEMP = @Cli and @relacion = 2/*Conyugue*/
	BEGIN
	   SET @RETORNO =  15    --descuento de conyuge
	   BREAK
	END*/
	
	IF @ID_CLI_RELAC_TEMP = 3 AND dbo.SF_Edad(@Fecha,@FNAC) < 22
	BEGIN
	   
	   IF @ID_CLI_TEMP = @Cli
	   BEGIN

	      IF @ORDEN = 1 /* 1er hijo en vitalicios +71 va el 15 %*/
	      BEGIN
	        IF @titular_categ = 1010 --VITALICIO +71
		      BEGIN
		         SET @RETORNO =  15 
	             BREAK
	          END
	       ELSE
	          BEGIN
		         SET @RETORNO =  25     ---Se cambia % por Ticket 11998  
	             BREAK
	          END   
		  END

	      IF @ORDEN = 2 /*Segundo Hijo/a*/
	      BEGIN
	         SET @RETORNO =  40    ---Se cambia % por Ticket 11998 30%, Ticket: 16176 se cambia 40% 
             BREAK
		  END
		   	
	      IF @ORDEN = 3 /*Tercer Hijo/a*/
	      BEGIN
	         SET @RETORNO =  65   ---Se cambia % por Ticket 11998 40%; Ticket: 16176 se cambia 65%
             BREAK
		  END
	      
	      IF @ORDEN >= 4 /*Cuarto Hijo/a o mas Hijos/as*/
	      BEGIN
	         SET @RETORNO =  100    ---Se cambia % por Ticket 11998 50%; Ticket: 16176 se cambia 100%
             BREAK
		  END
		  
	      /*IF @ORDEN >= 5 /*Quinto o mas Hijos/as */
	      BEGIN
	         SET @RETORNO =  65    ---Se cambia % por Ticket 11998 50%; Ticket: 16176 se cambia 65%
             BREAK
		  END*/
		  
		  

	   END
	END	 
	FETCH NEXT FROM GF_CURSOR INTO @ID_CLI_TEMP,@FNAC,@ID_CLI_RELAC_TEMP
END 
CLOSE GF_CURSOR
DEALLOCATE GF_CURSOR
RETURN  ISNULL(@RETORNO,0)
END
GO

CREATE FUNCTION [dbo].[SF_DeudaTotal_CS](@pId_Cliente INT) 
RETURNS DECIMAL(16,2)
AS
BEGIN
DECLARE @DeudaTotal_CS DECIMAL(16,2)

SET @DeudaTotal_CS =	(SELECT SUM(CI.Imp_Final) 
						FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT
						WHERE
						CB.Id_Trans = CI.Id_Trans
						AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
						AND CT.Compromete_Factura IN (1)
						AND CB.Id_Estado_Cbte IN (1,4)
						AND CI.Id_Producto = 'CS'
						AND CI.Id_Cliente = @pId_Cliente)
     
RETURN ISNULL(@DeudaTotal_CS, 0)
END
GO

CREATE FUNCTION [dbo].[SF_DivisionCadena](@cadena VARCHAR(2500), @token CHAR(1))
RETURNS @cortes TABLE (
	Id INT IDENTITY(1,1),
	corte VARCHAR(250)
)
AS
BEGIN
	DECLARE @Cnt int
	SET @Cnt = 1

	WHILE (Charindex(@token, @cadena)>0)
	BEGIN
		INSERT INTO @cortes(corte)
		SELECT 
			Data = ltrim(rtrim(Substring(@cadena, 1, Charindex(@token, @cadena)-1)))

		SET @cadena = Substring(@cadena,Charindex(@token, @cadena)+1, len(@cadena))
		SET @Cnt = @Cnt + 1
	END
	
	INSERT INTO @cortes(corte)
	SELECT Data = ltrim(rtrim(@cadena))

	RETURN

END
GO

CREATE FUNCTION [dbo].[SF_EOMONTH](@Fecha DATETIME) 
RETURNS DATETIME
AS
BEGIN
DECLARE @Retorno DATETIME
SET @Retorno = (DATEADD(mm,1,CAST(YEAR(@Fecha) AS VARCHAR(4)) + 
       RIGHT('00'+CAST(MONTH(@Fecha) AS VARCHAR(3)),2) + 
       '01') - 1)
RETURN @Retorno
END
GO

CREATE FUNCTION [dbo].[SF_Edad](@F1 DATETIME,@F2 DATETIME)
RETURNS INT
AS
BEGIN
DECLARE @Edad INT

SET @Edad = (select datediff(yy,@F2,@F1))

IF DATEPART(mm,@F2) >= DATEPART(mm,@F1)              
   SET @Edad = @Edad -1                    
         
RETURN @Edad
END
GO


CREATE FUNCTION [dbo].[SF_Edad_Categ](@F1 DATETIME,@F2 DATETIME)
RETURNS INT
AS
BEGIN
DECLARE @Edad INT
DECLARE @DiaF1 int,@mesF1 int,@anioF1 int
DECLARE @DiaF2 int,@mesF2 int,@anioF2 int

set @DiaF1 = DAY(@F1)
set @DiaF2 = DAY(@F2)
set @mesF1 = MONTH(@F1)
set @mesF2 = MONTH(@F2)
set @anioF1 = YEAR(@F1)
set @anioF2 = YEAR(@F2)
SET @F1 = dbo.SF_DATEFROMPARTS(@anioF1,@mesF1,1)
SET @F2 = dbo.SF_DATEFROMPARTS(@anioF2,@mesF2,1)

SET @Edad = (select datediff(yy,@F2,@F1))
--IF @mesF1 = @mesF2 AND @DiaF2 <= 15  Se comenta por ticket # 18620
IF @mesF1 = @mesF2 --AND @DiaF1 < @DiaF2
BEGIN
   SET @Edad = @Edad  - 1
END 
ELSE
BEGIN 
     IF (@mesF2 > @mesF1 )
	 BEGIN
		SET @Edad = @Edad -1
	 END
     ELSE
	 BEGIN
		SET @Edad = @Edad  
	 END
END
              
         
RETURN @Edad
END
GO

CREATE FUNCTION [dbo].SF_EncriptPassword(@pass CHAR(20))
RETURNS VARCHAR (50)
AS
BEGIN


DECLARE @Word CHAR(20)
DECLARE @Mask CHAR(100)
DECLARE @Dest CHAR(20)
DECLARE @Pos  TINYINT
DECLARE @uno CHAR(1)
DECLARE @Long INT

SET @Long = LEN(LTRIM(RTRIM(@pass)))
SET @Word = @pass
SET @Mask = '!@#$%^&*!@#$%^&*!@#$%^&*!@#$%^&*!@#$%^&*!@#$%^&*!@#$%^&*!@#$%^&*'
SET @Pos = 1
SET @Dest = ''
WHILE @Pos <= @Long
BEGIN
    SET @uno  = CHAR(ASCII(SUBSTRING(@Word,@Pos,1)) ^ ASCII(SUBSTRING(@Mask,@Pos,1)))
    SET @Dest = LTRIM(RTRIM(@Dest)) + @uno
    SET @Pos =  @Pos + 1

END
RETURN @Dest
END
GO

CREATE FUNCTION [dbo].[SF_Estado_Cbte_Fac_A_Una_Fecha](@pId_Trans INT, @pFecha DATETIME) 
RETURNS SMALLINT
AS
BEGIN
DECLARE @Id_Estado_Cbte				SMALLINT
DECLARE @Fecha_Fac					DATETIME
DECLARE @Id_Estado_Cbte_Actual_Fac	SMALLINT
DECLARE @Suma_Aplicaciones_Rec		DECIMAL(14,2)
DECLARE @Imp_Total_Fac				DECIMAL(12,2)
	
SET @Id_Estado_Cbte_Actual_Fac = (SELECT Id_Estado_Cbte FROM Cbtes WHERE Id_Trans = @pId_Trans)

IF(@Id_Estado_Cbte_Actual_Fac = 1/*Pendiente*/)
BEGIN
	SET @Id_Estado_Cbte = 1
	RETURN @Id_Estado_Cbte
END

SET @Fecha_Fac = (SELECT Fecha FROM Cbtes WHERE Id_Trans = @pId_Trans)

IF(CONVERT(DATE, @Fecha_Fac) > CONVERT(DATE, @pFecha))
BEGIN
	SET @Id_Estado_Cbte = 0
	RETURN @Id_Estado_Cbte
END

IF(@Id_Estado_Cbte_Actual_Fac IN (2/*Completo*/, 4/*Parcial*/))
BEGIN
	
	SET @Imp_Total_Fac = (SELECT Imp_Total FROM Cbtes WHERE  Id_Trans = @pId_Trans)
	
	SET @Suma_Aplicaciones_Rec =	(SELECT ISNULL (SUM(CA.Importe),0) FROM Cbtes_Aplica CA
									WHERE 
									CA.Id_Trans = @pId_Trans
									AND CA.Id_Trans_D IN	(SELECT CB.Id_Trans FROM Cbtes CB, Cbtes_Tipos CT
															WHERE 
															CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
															AND ((CT.Compromete_Recibos IN (1, -1)) OR (CT.Compromete_Factura IN (-1)))
															AND CONVERT(DATE, CB.Fecha) <= CONVERT(DATE, @pFecha)))
	IF(@Suma_Aplicaciones_Rec = 0)
	BEGIN
		SET @Id_Estado_Cbte = 1
		RETURN @Id_Estado_Cbte
	END
	
	IF(@Imp_Total_Fac = @Suma_Aplicaciones_Rec)
	BEGIN
		SET @Id_Estado_Cbte = 2
		RETURN @Id_Estado_Cbte
	END
	
	IF(@Imp_Total_Fac > @Suma_Aplicaciones_Rec)
	BEGIN
		SET @Id_Estado_Cbte = 4
		RETURN @Id_Estado_Cbte
	END
END

RETURN ISNULL(@Id_Estado_Cbte, @Id_Estado_Cbte_Actual_Fac)
END
GO

CREATE FUNCTION [dbo].[SF_Estados_Cajas_Mov](@Id_Estado_Cbte SMALLINT)
RETURNS INT
AS
BEGIN
DECLARE @Id_Estado_Mov_Caja INT

/*
ESTADO_____Id_Estado_Mov_Caja_____Id_Estado_Cbte
ANULADO_________1___________________3
COMPLETO_________2__________________(1,2)        
EN CARGA_________0__________________0
*/

IF (@Id_Estado_Cbte = 3 /*Anulado*/)
BEGIN
	SET @Id_Estado_Mov_Caja = 1
END

IF (@Id_Estado_Cbte = 2 /*Completo*/)
BEGIN
	SET @Id_Estado_Mov_Caja = 2
END

IF (@Id_Estado_Cbte = 1 /*Pendiente*/)
BEGIN
	SET @Id_Estado_Mov_Caja = 2
END

IF (@Id_Estado_Cbte = 0 /*En Carga*/)
BEGIN
	SET @Id_Estado_Mov_Caja = 0
END

IF (@Id_Estado_Cbte NOT IN (0,1,2,3))
BEGIN
	SET @Id_Estado_Mov_Caja = 2
END

RETURN ISNULL(@Id_Estado_Mov_Caja,0)
END
GO


