CREATE FUNCTION SF_Facturar_Visita (@Id_Cliente INT, @Fecha DATETIME)
RETURNS DECIMAL(12,2)
AS
BEGIN

DECLARE @Valor		    DECIMAL(12,2)
DECLARE @PrecioGravado  DECIMAL(12,2)
DECLARE @Cantidad	    INT
DECLARE @Producto	    VARCHAR(14)
DECLARE @Precio			DECIMAL(12,2)
DECLARE @Visita			INT

SET @Producto	 = 'VISITA' --Producto a Facturar
SET @Precio	 = 0
SET @Visita	 = (SELECT Cantidad FROM Productos WHERE Id_Producto = @Producto)
SET @Cantidad	 = ISNULL((SELECT COUNT(I.Id_Producto) FROM Cbtes_Items I, Cbtes C, Cbtes_Tipos T 
                    WHERE I.Id_Producto = @Producto 
				AND C.Id_Trans = I.Id_Trans
				AND C.Id_Tipo_Cbte =  T.Id_Tipo_Cbte
				AND (T.Compromete_Remitos = 1 OR T.Compromete_Factura = 1)
				AND C.Id_Estado_Cbte IN (1,2,4)
				AND DATEPART(mm,c.Fecha) = DATEPART(mm,@Fecha)
				AND DATEPART(yy,c.Fecha) = DATEPART(yy,@Fecha)
				AND C.Id_Cliente = @Id_Cliente),0)
SET @PrecioGravado	 = (SELECT Precio_Gravado FROM Productos WHERE Id_Producto = @Producto)
    
IF @Cantidad >= @Visita	   --Apartir de la 3ra Factura del Producto VISITA le Factura con el Precio_Gravado
    BEGIN
	   SET @Valor = @PrecioGravado   
    END
ELSE IF @Cantidad < @Visita   --Hastal 2da Factura del Producto VISITA le Factura con importe 0
    BEGIN
	   SET @Valor =  @Precio
    END    
RETURN @Valor
END;
GO

CREATE FUNCTION [dbo].[SF_FechaJuliana](@Fecha DATETIME)
RETURNS CHAR(6)
AS
BEGIN
DECLARE @FechaJuliana CHAR(6)

DECLARE @Dias VARCHAR(3)
DECLARE @Year VARCHAR(3)

SET @Year = (SELECT RIGHT(CAST(DATEPART(yy, @fecha) AS CHAR(4)),2))

SET @Dias = (SELECT RIGHT('000' + CAST(DATEPART(dy, @fecha) AS VARCHAR(3)),3))

SET @FechaJuliana = @Dias + ' ' + @Year

RETURN @FechaJuliana
END
GO

