	IF (@id_tipo_cbte_orig='NCC3A') SET @id_tipo_cbte = 'VDA3'
	IF (@id_tipo_cbte_orig='FCC4A') SET @id_tipo_cbte = 'FAE4'
	IF (@id_tipo_cbte_orig='NCC4A') SET @id_tipo_cbte = 'CAE4'
	IF (@id_tipo_cbte_orig='FCC1B') SET @id_tipo_cbte = 'FACB'
	IF (@id_tipo_cbte_orig='NCC1B') SET @id_tipo_cbte = 'ND01'
	IF (@id_tipo_cbte_orig='FCC2B') SET @id_tipo_cbte = 'FB02'
	IF (@id_tipo_cbte_orig='NCC2B') SET @id_tipo_cbte = 'ND02'
	IF (@id_tipo_cbte_orig='FCC3B') SET @id_tipo_cbte = 'FB03'
	IF (@id_tipo_cbte_orig='NCC3B') SET @id_tipo_cbte = 'ND03'
