CREATE  FUNCTION [dbo].[SF_Link_TX](@trans INT ) 
RETURNS CHAR(300)
AS
BEGIN

DECLARE @Importe CHAR(11)
DECLARE @Id_Deuda char(5)
DECLARE @Id_Concepto char(3)
DECLARE @Fecha CHAR(8)
declare @Cliente CHAR(19)
DECLARE @Retorno CHAR(300)
DECLARE @Trans_Char CHAR(10)





set @Id_Deuda = (select valor_integer from xparametros
                  where idparametro = 'Id_Link_Id_Deuda'  ) 
                  
set @Id_Concepto = (select valor_integer from xparametros
                    where idparametro = 'Id_Link_Id_Concep')
SET @Cliente = (select CAST(Id_Cliente AS VARCHAR)
                 FROM Cbtes C WHERE Id_Trans = @trans)

             
SET @Trans_Char = (select RIGHT( '000000000000000' + CAST(@trans AS VARCHAR),15))

SET @Importe  = (SELECT RIGHT( '00000000000000' + CAST(cast((ISNULL(Imp_Total,0) + ISNULL(Saldo_Anterior,0)) * Cotizacion * 100 AS INT) AS VARCHAR), 11) 
                 FROM Cbtes WHERE Id_Trans = @trans)
SET @Fecha    = (select cast(DATEPART(YY,Fecha_Venc) as CHAR(4)) + 
                 RIGHT( '00' + CAST(DATEPART(mm,Fecha_Venc) AS VARCHAR),2) + 
                 RIGHT( '00' + CAST(DATEPART(dd,Fecha_Venc) AS VARCHAR),2) 
                 FROM Cbtes WHERE Id_Trans = @trans)
			 
			 
                
set @retorno = @Id_Deuda + @Id_Concepto + @Cliente + @Fecha + @Importe 
             +  '000000' + '000000000000' + '000000' + '000000000000'
             +  @Trans_Char + '                                        '

RETURN @retorno
end
GO

CREATE FUNCTION [dbo].[SF_Moratoria_Cant_Meses](@Cli INT) 
RETURNS INT
AS
BEGIN
DECLARE @Meses_Deuda INT
DECLARE @Retorno INT

SET @Retorno = 0

SET @Meses_Deuda = (select datediff(mm,Ult_Cuota_Paga,getdate()) from clientes where id_cliente = @cli)
IF @Meses_Deuda BETWEEN 4 AND 6
   SET @Retorno = 3

IF @Meses_Deuda BETWEEN 7 AND 12
   SET @Retorno = 5

IF @Meses_Deuda BETWEEN 13 AND 18
   SET @Retorno = 8

IF @Meses_Deuda BETWEEN 19 AND 24
   SET @Retorno = 10

IF @Meses_Deuda > 24
   SET @Retorno = 16
		

RETURN @Retorno
END
GO

CREATE FUNCTION [dbo].[SF_Pago_Actividad](@pId_Cli INT,@pId_Prod VARCHAR(14), @pFecha DATETIME, @pFlag_Dia SMALLINT)
RETURNS SMALLINT
AS
BEGIN

DECLARE @id_trans		INT
DECLARE @pago			SMALLINT
DECLARE @fecha			DATETIME
DECLARE @Id_estado_Cbte	SMALLINT 
DECLARE @Existe			SMALLINT

/*Consulto si requiere consultar por el día de pago*/
/*1= Requiere dia*/
/*0= consulta por el mes*/

--SET @id_trans = (SELECT id_trans from Cbtes_Items WHERE id_cliente = @pId_Cli AND Fecha_QA = @fecha and Id_Producto=@pId_Prod)
SET @fecha = dbo.CF_FirtsDayMonth(@pFecha)
SET @Existe = ISNULL((SELECT 1 from Cbtes_Items WHERE id_cliente = @pId_Cli AND Fecha_QA = @fecha and Id_Producto=@pId_Prod
												AND EXISTS  (SELECT id_trans from Cbtes_Items WHERE id_cliente = @pId_Cli AND Fecha_QA = @fecha 
															and Id_Producto=@pId_Prod)),0)
IF(@Existe= 0)
BEGIN
		SET @pago = 0  /*No se encuentra comprobante para esa fecha retorna Impago*/
		RETURN @pago 
END 
ELSE IF(@Existe= 1)
BEGIN
	IF(@pFlag_Dia = 1)
	BEGIN
	
			SET @fecha = (DAY(@pFecha))
			SET @id_trans = (SELECT id_trans from Cbtes_Items WHERE id_cliente = @pId_Cli AND DAY(Fecha_QA) = @fecha 
															and Id_Producto=@pId_Prod)
			SET @Id_estado_Cbte = ISNULL((SELECT c.Id_estado_Cbte FROM cbtes c WHERE c.id_trans =@id_trans),0)
	END
	ELSE
	BEGIN
			SET @fecha = (dbo.CF_FirtsDayMonth(@pFecha))
			SET @id_trans = (SELECT id_trans from Cbtes_Items WHERE id_cliente = @pId_Cli AND Fecha_QA = @fecha
															and Id_Producto=@pId_Prod)
			SET @Id_estado_Cbte = ISNULL((SELECT c.Id_estado_Cbte FROM cbtes c WHERE c.id_trans =@id_trans),0)	
	END
END

IF(@Id_estado_Cbte = 1)
	SET @pago = 0					/*Impago*/
ELSE IF (@Id_estado_Cbte = 2)	
	RETURN 	@Id_estado_Cbte			/*Completo*/
ELSE IF (@Id_estado_Cbte = 4) 
	RETURN 	@Id_estado_Cbte			/*Pago Parcial*/	
     

RETURN @pago
END
GO

