CREATE FUNCTION [dbo].[SF_RapiPago_TX](@pId_Trans INT, @pImporte DECIMAL(12,2)) 
RETURNS CHAR(90)
AS
BEGIN

DECLARE @Retorno		CHAR(90)
DECLARE @TipoRegistro	CHAR(1)
DECLARE @NroReferencia	CHAR(19)
DECLARE @IdentificFac	CHAR(20)
DECLARE @CodigoMoneda	CHAR(1)
DECLARE @FechaPriVenc	CHAR(8)
DECLARE @ImportePriVenc	CHAR(11)
DECLARE @FechaSegVenc	CHAR(8)
DECLARE @ImporteSegVenc	CHAR(11)
DECLARE @Filler			CHAR(11)
DECLARE @Id_Cliente		INT
DECLARE @Doc_Nro		BIGINT
DECLARE @Fecha_PriVenc	DATETIME
DECLARE @Anio_PriVenc	CHAR(4)
DECLARE @Mes_PriVenc	CHAR(2)
DECLARE @Dia_PriVenc	CHAR(2)
DECLARE @Fecha_SegVenc	DATETIME
DECLARE @Anio_SegVenc	CHAR(4)
DECLARE @Mes_SegVenc	CHAR(2)
DECLARE @Dia_SegVenc	CHAR(2)
DECLARE @MesSeg			DATETIME
DECLARE @UltDiaMesSeg	DATETIME
DECLARE @Id_Cliente_Externo VARCHAR(14)
DECLARE @Id_Cliente_Externo_Int INT

/*=================================================================================*/

SET @TipoRegistro = '5'

/*Nro. de Referencia*/
SET @Id_Cliente		= ISNULL((SELECT Id_Cliente FROM Cbtes WHERE Id_Trans = @pId_Trans),0)
SET @Doc_Nro	= ISNULL((SELECT Doc_Nro FROM Clientes WHERE Id_Cliente = @Id_Cliente), 0)
SET @Id_Cliente_Externo	= ISNULL((SELECT ISNULL(Id_Cliente_Externo, '0') FROM Clientes WHERE Id_Cliente = @Id_Cliente AND ISNUMERIC(Id_Cliente_Externo) = 1), '')
SET @Id_Cliente_Externo_Int = CONVERT(INT, @Id_Cliente_Externo)

--SET @NroReferencia = (SELECT RIGHT('                   ' + CAST(@Doc_Nro AS VARCHAR),19)) Modificado por archivo enviado por Rapipago (sebastian.babandryseca@gire.com) 24/08/2018 14:14Hs via ticket 14323.
SET @NroReferencia = (SELECT RIGHT('0000000000000000000' + CAST(@Id_Cliente_Externo_Int AS VARCHAR),19))
/*FIN Nro. de Referencia*/

/*Identificador de Factura*/
--Modificado por archivo enviado por Rapipago (sebastian.babandryseca@gire.com) 24/08/2018 14:14Hs via ticket 14323.
SET @IdentificFac = (SELECT LEFT(RIGHT('0000000000' + CAST(@pId_Trans AS VARCHAR),10) + '                    ', 20))
/*FIN Identificador de Factura*/

/*Fecha Primer Vencimiento*/
SET @Fecha_PriVenc = (SELECT Fecha_Venc FROM Cbtes WHERE Id_Trans = @pId_Trans)

SET @Anio_PriVenc	= CAST(DATEPART(YY,@Fecha_PriVenc) AS CHAR(4))
SET @Mes_PriVenc	= RIGHT('00' + CAST(MONTH(@Fecha_PriVenc) AS VARCHAR),2)
SET @Dia_PriVenc	= '12'

SET @FechaPriVenc = @Anio_PriVenc + @Mes_PriVenc + @Dia_PriVenc
/*FIN Fecha Primer Vencimiento*/

/*Importe Primer Vencimiento*/
SET @ImportePriVenc	= (SELECT RIGHT('00000000000' +  CAST(CAST((@pImporte * 100) AS INT) AS VARCHAR), 11))
/*FIN Importe Primer Vencimiento*/

/*Fecha Segundo Vencimiento*/
/*Pedido en Ticket: 10.418 el 24/04/2017 a las 11:05 */
SET @MesSeg = DATEADD(mm, 1, GETDATE())
SET @UltDiaMesSeg = dbo.SF_EOMONTH(@MesSeg)
SET @Fecha_SegVenc = (@UltDiaMesSeg)

SET @Anio_SegVenc	= CAST(DATEPART(YY,@Fecha_SegVenc) AS CHAR(4))
SET @Mes_SegVenc	= RIGHT('00' + CAST(MONTH(@Fecha_SegVenc) AS VARCHAR),2)
SET @Dia_SegVenc	= RIGHT('00' + CAST(DAY(@Fecha_SegVenc) AS VARCHAR),2)

SET @FechaSegVenc = @Anio_SegVenc + @Mes_SegVenc + @Dia_SegVenc
/*FIN Fecha Segundo Vencimiento*/

/*Importe Segundo Vencimiento*/
SET @ImporteSegVenc	= (SELECT RIGHT('00000000000' +  CAST(CAST((@pImporte * 100) AS INT) AS VARCHAR), 11))
/*FIN Importe Segundo Vencimiento*/

SET @CodigoMoneda = '0' /*Pesos*/
SET @Filler = '00000000000'

/*=================================================================================*/

SET @retorno =	@TipoRegistro   + /*01 caracter. Tipo de Registro Registro. Fijo: 5*/
				@NroReferencia	+ /*19 caracteres. Identificacion del Cliente en la empresa.*/
				@IdentificFac	+ /*20 caracteres. Identifacacion de la factura*/
				@CodigoMoneda	+ /*01 caracter. 0 = Pesos; 1 = dolares*/					
				@FechaPriVenc	+ /*08 caracteres. Fecha del Primer Vencimiento. 12 del Mes. AAAAMMDD*/
				@ImportePriVenc + /*11 caracteres. Importe del Primer Vencimiento. 9 enteros, 2 decimales*/
				@FechaSegVenc	+ /*08 caracteres. Fecha del Segundo Vencimiento. 27 del Mes. AAAAMMDD*/
				@ImporteSegVenc	+ /*11 caracteres. Importe del Segundo Vencimiento. 9 enteros, 2 decimales*/
				@Filler			  /*11 caracteres. Filler. Todos Ceros*/  

RETURN @retorno
END
GO

create FUNCTION [dbo].[SF_Rec_Coef_Aplic_Pos] (@Id_Trans INT) 
RETURNS DECIMAL(17,5)
AS
BEGIN
DECLARE @Retorno DECIMAL(17,5)

set @Retorno = (select sum(z.importe) from cbtes_aplica z , CBTES a
                   where z.id_trans_d = @Id_Trans 
                   and a.Id_Trans = z.ID_TRANS
                   and a.Id_Estado_Cbte not in (1,3)
                   and z.importe > 0)
                   
set @Retorno = ISNULL(@Retorno,0) 
IF  @Retorno > 0                 
     set @Retorno =  (SELECT Imp_Total FROM Cbtes WHERE Id_Trans = @Id_Trans ) / @Retorno
                        
                   
                   
RETURN ISNULL(@Retorno,0)
END
GO

CREATE FUNCTION [dbo].[SF_Seguro_Precio](@pid_producto VARCHAR(14) ,@pId_Cliente INT, @pFecha DATETIME, @pMontoAsegurado Decimal(12,2)) 
RETURNS DECIMAL(12,2)
AS
BEGIN
/*Declaracion Variables*/
DECLARE @Precio_Seguro			DECIMAL(12,2)
DECLARE @Porc_Aumento_x_Edad	DECIMAL(12,2)
DECLARE @Fecha_Nac				DATETIME
DECLARE @Edad					SMALLINT
/*FIN Declaracion Variables*/

/*Verifica la edad para el calculo de la prima*/
SET @Fecha_Nac = (SELECT ISNULL(Fecha_Nac, '19000101') FROM Clientes WHERE Id_Cliente = @pId_Cliente)

SET @Edad = (SELECT dbo.CF_Edad_Persona_A_UnaFecha(@Fecha_Nac, @pFecha))

IF(@Edad < 50)
BEGIN
	SET @Porc_Aumento_x_Edad = '0.08'
END

IF(@Edad >= 50 AND @Edad < 65)
BEGIN
	SET @Porc_Aumento_x_Edad = '0.24'
END

IF(@Edad >= 65 AND @Edad < 74)
BEGIN
	SET @Porc_Aumento_x_Edad = '0.40'
END

IF(@Edad >= 75)
BEGIN
	SET @Porc_Aumento_x_Edad = '0.60'
END

/*FIN se calcula el valor de la cuota segun la edad */

SET @Precio_Seguro = @pMontoAsegurado * (@Porc_Aumento_x_Edad/100)

 

RETURN ISNULL(@Precio_Seguro, 0)
END
GO

CREATE FUNCTION [dbo].[SF_Seguro_Vida_Precio](@pid_producto VARCHAR(14) ,@pId_Cliente INT, @pFecha DATETIME, @pMontoAsegurado Decimal(12,2)) 
RETURNS DECIMAL(12,2)
AS
BEGIN
/*Declaracion Variables*/
DECLARE @Precio_Seguro			DECIMAL(12,2)
DECLARE @Prima_x_Edad	        DECIMAL(12,2)
DECLARE @Fecha_Nac				DATETIME
DECLARE @Edad					SMALLINT
/*FIN Declaracion Variables*/

/*Verifica la edad para el calculo de la prima*/
SET @Fecha_Nac = (SELECT ISNULL(Fecha_Nac, '19000101') FROM Clientes WHERE Id_Cliente = @pId_Cliente)

SET @Edad = (SELECT dbo.CF_Edad_Persona_A_UnaFecha(@Fecha_Nac, @pFecha))

IF(@Edad <= 40)
BEGIN
	SET @Prima_x_Edad = '0.17'
END

IF(@Edad >= 41 AND @Edad <= 45)
BEGIN
	SET @Prima_x_Edad = '0.51'
END

IF(@Edad >= 46 AND @Edad <= 50)
BEGIN
	SET @Prima_x_Edad = '0.51'
END

IF(@Edad >= 51 AND @Edad <= 55)
BEGIN
	SET @Prima_x_Edad = '1.06'
END

IF(@Edad >= 55 AND @Edad <= 60)
BEGIN
	SET @Prima_x_Edad = '1.06'
END

IF(@Edad >= 61 AND @Edad <= 65)
BEGIN
	SET @Prima_x_Edad = '1.84'
END

IF(@Edad >= 66)
BEGIN
	SET @Prima_x_Edad = '3.97'
END

/*FIN se calcula el valor de la cuota segun la edad */

SET @Precio_Seguro = (@pMontoAsegurado/1000) * @Prima_x_Edad

 

RETURN ISNULL(@Precio_Seguro, 0)
END
GO

CREATE FUNCTION [dbo].[SF_Tar_Validar](@nro varchar(16) )
RETURNS TINYINT
as
begin
/* relleno con ceros */

declare @suma int
declare @i int
declare @temp int
declare @temp_alfa char(2)
declare @r tinyint

set @nro = RIGHT( '0000000000000000' + ltrim(RTrim(@nro)),16)
set @temp = 0
set @suma = 0

set @i = 1
while @i <= 16
BEGIN
      set @temp = (CAST(SUBSTRING(@nro,@i,1) as int)) * 2
      IF @temp > 9
      begin
			set @temp_alfa =  CAST(@temp as char(2))
			set @temp = (CAST(SUBSTRING(@temp_alfa,1,1) as int) + CAST(SUBSTRING(@temp_alfa,2,1) as int))
      end
      set @suma = @suma + @temp 
      set @i = @i + 2
END

set @i = 2
while @i <= 16
BEGIN
      set @temp = (CAST(SUBSTRING(@nro,@i,1) as int))
      set @suma = @suma + @temp 
      set @i = @i + 2
END

If @suma %10 = 0 and @suma <= 150
begin
	set @r = 1
end
else
begin
	set @r = 0
end
return @r
END
GO


CREATE  FUNCTION [dbo].[SF_TarjNevada_TX](@trans INT) 
RETURNS CHAR(69)
AS
BEGIN

DECLARE @Retorno			CHAR(69)
DECLARE @Id_Tarjeta_Nevada	VARCHAR(10)
DECLARE @Tar_Nro			VARCHAR(25)
DECLARE @Fecha_Alta			DATETIME
DECLARE @Id_Cliente			INT
DECLARE @SERPlastico		CHAR(16) /*Nro. de Tarjeta. Aig Por Tarj. Nevada*/
DECLARE @SERMonto			CHAR(12) /*Monto a Debitar. 10 Ent. 2 Dec*/
DECLARE @SERFecAlta			CHAR(6)	 /*Fec. Ingre. al Servicio. AA-MM-DD*/
DECLARE @SERLeyenda			CHAR(35) /*Descripcion Servicio. Alfanumericos*/

SET @Id_Tarjeta_Nevada = ISNULL((SELECT Valor_String FROM xParametros WHERE IdParametro = 'Id_Nevada'),'')

IF (@Id_Tarjeta_Nevada <> '')
BEGIN
	SET @Id_Cliente = (SELECT Id_Cliente FROM Cbtes WHERE Id_Trans = @trans)
	SET @Tar_Nro	= (SELECT DBO.SF_COTIZA(Tar_Nro) FROM Contratos WHERE Id_Cliente = @Id_Cliente AND Id_Tarjeta = @Id_Tarjeta_Nevada AND Activo=1)
	SET @Fecha_Alta = (SELECT Fecha_Alta FROM Contratos WHERE Id_Cliente = @Id_Cliente AND Id_Tarjeta = @Id_Tarjeta_Nevada AND Activo=1)
	
	SET @SERPlastico	=	@Tar_Nro
	SET @SERMonto		=	(SELECT RIGHT( '000000000000' + CAST(CAST((ISNULL(Imp_Total,0) + ISNULL(Saldo_Anterior,0)) * Cotizacion * 100 AS INT) AS VARCHAR), 12) 
							FROM Cbtes WHERE Id_Trans = @trans)
	SET @SERFecAlta		=	(SELECT RIGHT('00' + CAST(DATEPART(YY,@Fecha_Alta) AS VARCHAR),2) + 
							RIGHT('00' + CAST(DATEPART(mm,@Fecha_Alta) AS VARCHAR),2) + 
							RIGHT('00' + CAST(DATEPART(dd,@Fecha_Alta) AS VARCHAR),2))							
	SET @SERLeyenda		= '                                   '

	SET @Retorno		=	@SERPlastico		+ @SERMonto			+ @SERFecAlta +
							@SERLeyenda
END

RETURN ISNULL(@retorno,'')
END
GO


