CREATE FUNCTION [dbo].[SF_UCSAG](@Id_Cliente INT) 
RETURNS DATETIME
AS
BEGIN
DECLARE @Ult_CSAG_Paga		DATETIME
DECLARE @Ult_CSAG_Impaga	DATETIME
DECLARE @UCSAG				DATETIME
DECLARE @Id_Tipo_Cli		SMALLINT

/*Definicion Variables Locales*/

DECLARE @Proximo_Venc_CSAG	DATETIME

/*Fin Definicion Variables Locales*/

/*
	Para el calculo correcto del Vencimiento de la Cuota Aguinaldo deben ser generados los comprobantes con fechas semestral,
	debido que por solicitud del ticket 15193 debe dar prorroga de 2 meses mas para el pago.
*/

SET @Id_Tipo_Cli = ISNULL((SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @Id_Cliente), 0)

IF(@Id_Tipo_Cli IN (1004,/*ACOMPAÑANTE*/	1007,/*USUARIO GEBA GYM*/	
					1008,/*USUARIO*/		1010,/*VITALICIO + 71*/	
					1012,/*USUARIO RCA*/	1013,/*USUARIO AFIP*/
					1014,/*USUARIO J.N.*/	1016,/*USUARIO S.M. / JM*/	
					1017,/*USUARIO +75*/	1104 /*USUARIO TRIAR*/))
BEGIN
	/*Actualiza la fecha de vencimiento de Cuota Aguinaldo Semestral*/
	SET @Proximo_Venc_CSAG = (SELECT DATEADD(MONTH,6/*Cantidad de meses que se actualiza el vencimiento*/,MAX(FECHA_QA)) FROM CBTES_ITEMS WHERE ID_PRODUCTO = 'CAGUIN' AND DATEPART(YY,FECHA_QA) = DATEPART(YY,GETDATE()))
	SET @UCSAG = @Proximo_Venc_CSAG
	RETURN @UCSAG
END

SET @Ult_CSAG_Paga = (	SELECT MAX(CI.Fecha_QA)
						FROM Cbtes_Items CI, Cbtes CB, Productos PR, Cbtes_Tipos CT
						WHERE 
						CB.Id_Trans = CI.Id_Trans 
						AND PR.Id_Producto = CI.Id_Producto 
						AND CB.Id_Estado_Cbte = 2 /*Completo*/
						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte 
						AND CT.Compromete_Factura IN (1)
						AND PR.Id_Producto = 'CAGUIN'
						AND CI.Id_Cliente = @Id_Cliente)

SET @Ult_CSAG_Impaga = (SELECT MIN(CI.Fecha_QA)
						FROM Cbtes_Items CI, Cbtes CB, Productos PR, Cbtes_Tipos CT
						WHERE 
						CB.Id_Trans = CI.Id_Trans 
						AND PR.Id_Producto = CI.Id_Producto
						AND CB.Id_Estado_Cbte IN (1/*Pendiente*/, 4/*Parcial*/)
						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte 
						AND CT.Compromete_Factura IN (1)
						AND PR.Id_Producto = 'CAGUIN'
						AND CI.Id_Cliente = @Id_Cliente)	

IF((@Ult_CSAG_Paga IS NULL) AND (@Ult_CSAG_Impaga IS NOT NULL))
BEGIN
	SET @UCSAG = DATEADD(mm, 3, @Ult_CSAG_Impaga)
	
	RETURN @UCSAG
END

IF((@Ult_CSAG_Paga IS NOT NULL) AND (@Ult_CSAG_Impaga IS NULL))
BEGIN
	SET @Proximo_Venc_CSAG = (SELECT DATEADD(MONTH,6,MAX(FECHA_QA)) FROM CBTES_ITEMS WHERE ID_PRODUCTO = 'CAGUIN' AND Id_Cliente = @Id_Cliente)
	SET @UCSAG = @Proximo_Venc_CSAG	
	RETURN @Proximo_Venc_CSAG
END

IF ((@Ult_CSAG_Paga IS NOT NULL) AND (@Ult_CSAG_Impaga IS NOT NULL))
BEGIN
	IF (@Ult_CSAG_Impaga < @Ult_CSAG_Paga)
	BEGIN
		SET @UCSAG = DATEADD(MONTH,3,@Ult_CSAG_Impaga)
	END
	ELSE
	BEGIN
		SET @UCSAG = @Ult_CSAG_Paga
	END
	
	RETURN @UCSAG
END

IF ((@Ult_CSAG_Paga IS NULL) AND (@Ult_CSAG_Impaga IS NULL))
BEGIN
	SET @Proximo_Venc_CSAG = (SELECT DATEADD(MONTH,6/*Cantidad de meses que se actualiza el vencimiento*/,MAX(FECHA_QA)) FROM CBTES_ITEMS WHERE ID_PRODUCTO = 'CAGUIN' AND DATEPART(YY,FECHA_QA) = DATEPART(YY,GETDATE()))
	SET @UCSAG = @Proximo_Venc_CSAG
	RETURN @UCSAG
END

/*En caso de ser un socio nuevo le actualiza la Cuota Aguinaldo hasta la proxima facturacion de Cuota Aguinaldo.*/

IF(@UCSAG>='20180401')
BEGIN
	--SET @UCSAG = @Proximo_Venc_CSAG
	SET @UCSAG = (SELECT DATEADD(MONTH,6,MAX(FECHA_QA)) FROM CBTES_ITEMS WHERE ID_PRODUCTO = 'CAGUIN' AND DATEPART(YY,FECHA_QA) = DATEPART(YY,GETDATE()))
	
	RETURN @UCSAG
END

RETURN @Proximo_Venc_CSAG
END
GO


CREATE FUNCTION [dbo].[SF_UCSAG](@Id_Cliente INT) 
RETURNS DATETIME
AS
BEGIN
DECLARE @Ult_CSAG_Paga		DATETIME
DECLARE @Ult_CSAG_Impaga	DATETIME
DECLARE @UCSAG				DATETIME
DECLARE @Id_Tipo_Cli		SMALLINT

SET @Id_Tipo_Cli = ISNULL((SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @Id_Cliente), 0)

IF(@Id_Tipo_Cli IN (1004,1007,1008,1010,1012,1013,1014,1016,1017,1104))
BEGIN
	/*Determinado por Ticket*/
	SET @UCSAG = '20190131'
	RETURN @UCSAG
END

SET @Ult_CSAG_Paga = (	SELECT MAX(CI.Fecha_QA)
						FROM Cbtes_Items CI, Cbtes CB, Productos PR, Cbtes_Tipos CT
						WHERE 
						CB.Id_Trans = CI.Id_Trans 
						AND PR.Id_Producto = CI.Id_Producto 
						AND CB.Id_Estado_Cbte = 2 /*Completo*/
						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte 
						AND CT.Compromete_Factura IN (1)
						AND PR.Id_Producto = 'CAGUIN'
						AND CI.Id_Cliente = @Id_Cliente)

SET @Ult_CSAG_Impaga = (SELECT MIN(CI.Fecha_QA)
						FROM Cbtes_Items CI, Cbtes CB, Productos PR, Cbtes_Tipos CT
						WHERE 
						CB.Id_Trans = CI.Id_Trans 
						AND PR.Id_Producto = CI.Id_Producto
						AND CB.Id_Estado_Cbte IN (1/*Pendiente*/, 4/*Parcial*/)
						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte 
						AND CT.Compromete_Factura IN (1)
						AND PR.Id_Producto = 'CAGUIN'
						AND CI.Id_Cliente = @Id_Cliente)	

IF((@Ult_CSAG_Paga IS NULL) AND (@Ult_CSAG_Impaga IS NOT NULL))
BEGIN
	SET @UCSAG = DATEADD(mm, -1, @Ult_CSAG_Impaga)
	
	RETURN @UCSAG
END

IF((@Ult_CSAG_Paga IS NOT NULL) AND (@Ult_CSAG_Impaga IS NULL))
BEGIN
	SET @UCSAG = '20190131'
	
	RETURN @UCSAG
END

IF ((@Ult_CSAG_Paga IS NOT NULL) AND (@Ult_CSAG_Impaga IS NOT NULL))
BEGIN
	IF (@Ult_CSAG_Impaga < @Ult_CSAG_Paga)
	BEGIN
		SET @UCSAG = @Ult_CSAG_Impaga
	END
	ELSE
	BEGIN
		SET @UCSAG = @Ult_CSAG_Paga
	END
	
	RETURN @UCSAG
END

IF(@UCSAG>='20180401')
BEGIN
	SET @UCSAG = '20190131'
	
	RETURN @UCSAG
END

RETURN ISNULL(@UCSAG,'20190131')
END
GO


CREATE FUNCTION [dbo].[SF_UCSE](@Id_Cliente INT) 
RETURNS DATETIME
AS
BEGIN
DECLARE @Ult_CSE_Paga		DATETIME
DECLARE @Ult_CSE_Impaga		DATETIME
DECLARE @UCSE				DATETIME
DECLARE @Id_Tipo_Cli		SMALLINT

SET @Id_Tipo_Cli = ISNULL((SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @Id_Cliente), 0)

IF(@Id_Tipo_Cli IN (1004,1007,1008,1010,1012,1013,1014,1016,1017,1104))
BEGIN
	/*Determinado por Ticket*/
	SET @UCSE = '20501231'
	RETURN @UCSE
END

SET @Ult_CSE_Paga = (	SELECT MAX(CI.Fecha_QA)
						FROM Cbtes_Items CI, Cbtes CB, Productos PR, Cbtes_Tipos CT
						WHERE 
						CB.Id_Trans = CI.Id_Trans 
						AND PR.Id_Producto = CI.Id_Producto 
						AND CB.Id_Estado_Cbte = 2 /*Completo*/
						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte 
						AND CT.Compromete_Factura IN (1)
						AND PR.Id_Producto = 'CSE'
						AND CI.Id_Cliente = @Id_Cliente)

SET @Ult_CSE_Impaga = (SELECT MIN(CI.Fecha_QA)
						FROM Cbtes_Items CI, Cbtes CB, Productos PR, Cbtes_Tipos CT
						WHERE 
						CB.Id_Trans = CI.Id_Trans 
						AND PR.Id_Producto = CI.Id_Producto
						AND CB.Id_Estado_Cbte IN (1/*Pendiente*/, 4/*Parcial*/)
						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte 
						AND CT.Compromete_Factura IN (1)
						AND PR.Id_Producto = 'CSE'
						AND CI.Id_Cliente = @Id_Cliente)	

IF((@Ult_CSE_Paga IS NULL) AND (@Ult_CSE_Impaga IS NOT NULL))
BEGIN
	SET @UCSE = (@Ult_CSE_Impaga)
END

IF((@Ult_CSE_Paga IS NOT NULL) AND (@Ult_CSE_Impaga IS NULL))
BEGIN
	SET @UCSE = '20501231'
END

IF ((@Ult_CSE_Paga IS NOT NULL) AND (@Ult_CSE_Impaga IS NOT NULL))
BEGIN
	IF (@Ult_CSE_Impaga < @Ult_CSE_Paga)
	BEGIN
		SET @UCSE = @Ult_CSE_Impaga
	END
	ELSE
	BEGIN
		SET @UCSE = @Ult_CSE_Paga
	END
END

IF(@UCSE>='20170401')
BEGIN
	SET @UCSE = '20501231'
END

RETURN ISNULL(@UCSE,'20501231')
END
GO


CREATE FUNCTION [dbo].[SF_UltMesGenerado_X_Producto](@Id_Cliente INT, @Id_Producto VARCHAR(14)) 
RETURNS DATETIME
AS
BEGIN
DECLARE @UltMesGen DATETIME

SET @UltMesGen = ISNULL((SELECT MAX(CI.Fecha_QA)
						FROM Cbtes_Items CI, Cbtes CB, Cbtes_Tipos CT
						WHERE 
						CB.Id_Trans = CI.Id_Trans 
						AND CI.Id_Producto = @Id_Producto
						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte 
