CREATE FUNCTION [dbo].[SF_Ult_Cuota_Paga](@pId_Cliente INT, @pFecha DATETIME) 
RETURNS DATETIME
AS
BEGIN
DECLARE @Fecha_UCP					DATETIME
DECLARE @Ult_Cuota_Paga				DATETIME
DECLARE @Ult_Cuota_Paga_Mes			DATETIME
DECLARE @Ult_Cuota_Paga_Periodo		DATETIME
DECLARE @Ult_Cuota_Impaga			DATETIME
DECLARE @Id_Tipo_Cli				SMALLINT
DECLARE @Fecha_Alta					DATETIME
DECLARE @Fam_CuotaSoc				INT
DECLARE @Fecha_Hasta				DATETIME
DECLARE @Id_Tipo_Con				SMALLINT

SET @Id_Tipo_Cli = (SELECT dbo.SF_Categ(@pId_Cliente, @pFecha))
SELECT TOP 1  @Fecha_Hasta = Fecha_Hasta, 
	@Id_Tipo_Con = Id_Tipo_Con
    FROM dbo.Contratos 
    WHERE Id_Cliente=@pId_Cliente 
    AND Id_Tipo_Con IN (39,11) -- Ticket #001854 // 2022.05.30 : Se agrega la validacion del contrato tipo 11 (LICENCIAS)
    AND Activo = 1
    AND Fecha_Desde <= GETDATE()
    AND ISNULL(Fecha_Hasta,GETDATE()-1)>= GETDATE()
    ORDER BY Fecha_Hasta DESC   



IF(@Id_Tipo_Con = 39 )
BEGIN
	/*
	* Si el contrato es Promo Verano
	*/
	SET @Fecha_UCP = @Fecha_Hasta
	RETURN @Fecha_UCP
END


IF(@Id_Tipo_Cli IN (10, 1018, 1103, 1111, 1112, 1113))
BEGIN
	/*
	* Categorias que no pagan:
	*
	* 10	ACCESO MASTER
	* 1018	INVITADOS
	* 1103	NO SOCIO
	* 1111	USUARIO PROMO VERANO MAYOR
	* 1112	USUARIO PROMO VERANO MENOR
	* 1113	VISITA
	*/
	SET @Fecha_UCP = '20500101'
	RETURN @Fecha_UCP
END

------------------------------------------------------------------------------------------------------------------------------------------------

/*IF(@Id_Tipo_Cli IN (NN))
BEGIN
	/*
	 * Categorias que no importa lo que haya pagado, no tiene que entrar
	 * NN XXXXXXXXXX
	 */
	SET @Fecha_UCP = '19000101'
	RETURN @Fecha_UCP
END*/

------------------------------------------------------------------------------------------------------------------------------------------------

SET @Fam_CuotaSoc = CAST( (dbo.CF_xParam('Fam_CuotasSoc')) AS INT)

-------------------------------------------------------------------------

IF(@Id_Tipo_Cli IN (1012,1017))
BEGIN
	/*
	* Categorias que tienen CS Voluntaria: Ticket #22662
	*
	* 1010	VITALICIO + 71 (se modifica en ticket #000250)
	* 1012	USUARIO RCA
	* 1017	USUARIO +75
	*/
	
	
	SET @Ult_Cuota_Paga_Mes =(SELECT MAX(CI.Fecha_QA)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
							AND CI.Id_Producto = PR.Id_Producto
							AND CT.Compromete_Factura IN (1)
							AND (CB.Id_Estado_Cbte IN (2/*Completo*/))
							AND PR.Id_Familia = @Fam_CuotaSoc
							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Mes, 0) = 1)

	SET @Ult_Cuota_Paga_Periodo =(SELECT MAX(CI.Fecha_Venc)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
							AND CI.Id_Producto = PR.Id_Producto
							AND CT.Compromete_Factura IN (1)
							AND (CB.Id_Estado_Cbte IN (2/*Completo*/))
							AND PR.Id_Familia = @Fam_CuotaSoc
							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Periodo, 0) = 1)
END							
-------------------------------------------------------------------------
ELSE
BEGIN					
	SET @Ult_Cuota_Paga_Mes =(SELECT MAX(CI.Fecha_QA)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
							AND CI.Id_Producto = PR.Id_Producto
							AND CT.Compromete_Factura IN (1)
							AND (CB.Id_Estado_Cbte IN (2/*Completo*/) OR (CB.Id_Estado_Cbte IN (1/*PENDIENTE*/) AND CI.Imp_Final = 0))
							AND PR.Id_Familia = @Fam_CuotaSoc
							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Mes, 0) = 1)

	SET @Ult_Cuota_Paga_Periodo =(SELECT MAX(CI.Fecha_Venc)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
							AND CI.Id_Producto = PR.Id_Producto
							AND CT.Compromete_Factura IN (1)
							AND (CB.Id_Estado_Cbte IN (2/*Completo*/) OR (CB.Id_Estado_Cbte IN (1/*PENDIENTE*/) AND CI.Imp_Final = 0))
							AND PR.Id_Familia = @Fam_CuotaSoc
							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Periodo, 0) = 1)
							

END		

-------------------------------------------------------------------------
/*

SE AGREGA NUEVA VALIDACION A PEDIDO EN EL TICKET #000250
Ticket #001854 // 2022.05.30 : Se agrega la validacion del contrato tipo 11 (LICENCIAS)
*/

IF (@Id_Tipo_Cli = 1010) OR (@Id_Tipo_Con = 11)
BEGIN
	SET @Ult_Cuota_Paga_Mes =(SELECT MAX(CI.Fecha_QA)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
							AND CI.Id_Producto = PR.Id_Producto
							AND CT.Compromete_Factura IN (1)
							AND (CB.Id_Estado_Cbte IN (2/*Completo*/))
/*Inclusión ticket #000250*/AND CB.Id_Trans NOT IN(SELECT Id_Trans FROM Cbtes_Items WHERE Id_Producto = 'CS' AND Imp_gravado = 0)
							AND PR.Id_Familia = @Fam_CuotaSoc
							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Mes, 0) = 1)

	SET @Ult_Cuota_Paga_Periodo =(SELECT MAX(CI.Fecha_Venc)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
							AND CI.Id_Producto = PR.Id_Producto
							AND CT.Compromete_Factura IN (1)
							AND (CB.Id_Estado_Cbte IN (2/*Completo*/))
/*Inclusión ticket #000250*/AND CB.Id_Trans NOT IN(SELECT Id_Trans FROM Cbtes_Items WHERE Id_Producto = 'CS' AND Imp_gravado = 0)
							AND PR.Id_Familia = @Fam_CuotaSoc
							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Periodo, 0) = 1)
END	

-------------------------------------------------------------------------
							
IF(@Ult_Cuota_Paga_Periodo IS NOT NULL)
BEGIN
	SET @Ult_Cuota_Paga_Periodo = dbo.CF_FOMONTH(@Ult_Cuota_Paga_Periodo)
	
	IF(@Ult_Cuota_Paga_Mes IS NULL)
	BEGIN
		SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Periodo
	END
	ELSE
	BEGIN
		IF(@Ult_Cuota_Paga_Periodo > @Ult_Cuota_Paga_Mes)
		BEGIN
			SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Periodo
		END
		ELSE
		BEGIN
			SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Mes
		END
	END
END
ELSE
BEGIN
	SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Mes
END

------------------------------------------------------------------------------------------------------------------------------------------------

--SET @Ult_Cuota_Impaga = (SELECT MIN(CI.Fecha_QA)
--						FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
--						WHERE 
--						CB.Id_Trans = CI.Id_Trans 						
--						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte
--						AND CI.Id_Producto = PR.Id_Producto
--						AND CT.Compromete_Factura IN (1)
--						AND CB.Id_Estado_Cbte IN (1/*Pendiente*/, 4/*Parcial*/)
--						AND PR.Id_Familia = @Fam_CuotaSoc
--						AND CI.Id_Cliente = @pId_Cliente)	


IF((@Ult_Cuota_Paga IS NOT NULL) AND (@Ult_Cuota_Impaga IS NOT NULL))
BEGIN
	IF (@Ult_Cuota_Impaga < @Ult_Cuota_Paga)
	BEGIN
		SET @Fecha_UCP = DATEADD(MM, -1, @Ult_Cuota_Impaga)
		RETURN @Fecha_UCP
	END
	ELSE
	BEGIN
		SET @Fecha_UCP = @Ult_Cuota_Paga
		RETURN @Fecha_UCP
	END
END


IF((@Ult_Cuota_Paga IS NULL) AND (@Ult_Cuota_Impaga IS NOT NULL))
BEGIN
	SET @Fecha_UCP = DATEADD(MM, -1, @Ult_Cuota_Impaga)
	RETURN @Fecha_UCP
END

IF((@Ult_Cuota_Paga IS NOT NULL) AND (@Ult_Cuota_Impaga IS NULL))
BEGIN
	SET @Fecha_UCP = @Ult_Cuota_Paga
	RETURN @Fecha_UCP
END

/*
--si las 2 son nulas ***DESCOMENTAR EN CASO DE ERROR***
SET @Fecha_Alta = (SELECT ISNULL(Fecha_Alta, '19000101') FROM Clientes WHERE Id_Cliente = @pId_Cliente)
/*Se hace la siguiente linea porque tienen SQL 2008 o superior*/
SET @Fecha_Alta = CONVERT(DATE,@Fecha_Alta) 

RETURN ISNULL(@Fecha_UCP, DATEADD(MM, -1, @Fecha_Alta))
*/

-- *** VOLVER A COMENTAR EN CASO DE ERROR *** -- 
-- Si las 2 fechas son nulas, se retorna NULL  para que la UCP quede en BLANCO // Ticket #001974 //2022-06-08
RETURN @Fecha_UCP


END
GO

CREATE FUNCTION [dbo].[SF_Ult_Cuota_Paga_a_una_Fecha](@pId_Cliente INT, @pFecha DATETIME) 
RETURNS DATETIME
AS
BEGIN
DECLARE @Fecha_UCP			DATETIME
DECLARE @Ult_Cuota_Paga		DATETIME
DECLARE @Ult_Cuota_Impaga	DATETIME
DECLARE @Fecha_Alta			DATETIME

SET @Fecha_Alta = (SELECT ISNULL(Fecha_Alta, '19000101') FROM Clientes WHERE Id_Cliente = @pId_Cliente)

SET @Fecha_Alta = CONVERT(DATE,@Fecha_Alta) 

SET @Ult_Cuota_Paga =(SELECT MAX(CI.Fecha_QA)
					FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
					WHERE
					CB.Id_Trans = CI.Id_Trans
					AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
					AND CI.Id_Producto = PR.Id_Producto
					AND CT.Compromete_Factura IN (1)
					--AND CB.Id_Estado_Cbte IN (2/*Completo*/)
					AND dbo.SF_Estado_Cbte_Fac_A_Una_Fecha(CB.Id_Trans, @pFecha) IN (2/*Completo*/)
					AND PR.Id_Familia = (dbo.CF_xParam('Fam_CuotasSoc'))
					AND CI.Id_Cliente = @pId_Cliente
					AND CONVERT (DATE, CB.Fecha) <= CONVERT (DATE, @pFecha))


SET @Ult_Cuota_Impaga = (SELECT MIN(CI.Fecha_QA)
						FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
						WHERE 
						CB.Id_Trans = CI.Id_Trans 						
						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte
						AND CI.Id_Producto = PR.Id_Producto
						AND CT.Compromete_Factura IN (1)
						--AND CB.Id_Estado_Cbte IN (1/*Pendiente*/, 4/*Parcial*/)
						AND dbo.SF_Estado_Cbte_Fac_A_Una_Fecha(CB.Id_Trans, @pFecha) IN (1/*Pendiente*/, 4/*Parcial*/)
						AND PR.Id_Familia = (dbo.CF_xParam('Fam_CuotasSoc'))
						AND CI.Id_Cliente = @pId_Cliente
						AND CONVERT (DATE, CB.Fecha) <= CONVERT (DATE, @pFecha))	


IF((@Ult_Cuota_Paga IS NULL) AND (@Ult_Cuota_Impaga IS NOT NULL))
BEGIN
	SET @Fecha_UCP = DATEADD(MM, -1, @Ult_Cuota_Impaga)
	RETURN @Fecha_UCP
END

IF((@Ult_Cuota_Paga IS NOT NULL) AND (@Ult_Cuota_Impaga IS NULL))
BEGIN
	SET @Fecha_UCP = @Ult_Cuota_Paga
	RETURN @Fecha_UCP
END

IF((@Ult_Cuota_Paga IS NOT NULL) AND (@Ult_Cuota_Impaga IS NOT NULL))
BEGIN
	IF (@Ult_Cuota_Impaga < @Ult_Cuota_Paga)
	BEGIN
		SET @Fecha_UCP = DATEADD(MM, -1, @Ult_Cuota_Impaga)
		RETURN @Fecha_UCP
	END
	ELSE
	BEGIN
		SET @Fecha_UCP = @Ult_Cuota_Paga
		RETURN @Fecha_UCP
	END
END

IF((@Ult_Cuota_Paga IS NULL) AND (@Ult_Cuota_Impaga IS NULL))
BEGIN
	/*No existe ningun comprobante de CS*/
	SET @Fecha_UCP = '19000101'
	RETURN @Fecha_UCP
END

RETURN ISNULL(@Fecha_UCP, DATEADD(MM, -1, @Fecha_Alta))
END
GO

CREATE FUNCTION [dbo].[SF_Vendedor_Membresia] (@Id_Cliente INT)
RETURNS VARCHAR(60)
AS
BEGIN


DECLARE @Id_vendedor			INT
DECLARE @Id_Trans				INT
DECLARE @Vendedor				VARCHAR(60)

SET  @Id_Trans = ISNULL((select MAX(id_trans) 
							from cbtes
							where 
							id_trans in (Select id_trans from cbtes_items where id_producto in ('CS') and id_cliente=@Id_Cliente  group by id_trans having count(item)>=12 and MAX(Fecha_QA) > GETDATE() )
							and id_Estado_cbte=2),0)

					

SET @Id_vendedor = ISNULL((SELECT id_vendedor FROM Cbtes WHERE Id_trans=@Id_Trans),0)

SET @Vendedor = ISNULL((SELECT Descripcion FROM Vendedores WHERE Id_vendedor = @Id_vendedor),'')


	
RETURN 	ISNULL(@Vendedor,'')

END
GO

CREATE PROCEDURE [dbo].[SPJ_CD_Clientes_Novedades_Reconocimiento_Facial_Procesar] @pJson VARCHAR(8000)
AS 

/*
 * LOG VERSIONES:
 * 23/08/2022: Se crea el Stored
 * 16/01/2025: Se agrega validacion de Flag_Carga_Exitosa - TC
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug				TINYINT

SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @pJson_A_Enviar						VARCHAR(8000)
DECLARE @Id_Novedad							INT
DECLARE @Id_Cliente							INT
DECLARE @rta_JSON_Stored_Invocado			VARCHAR(8000)
DECLARE @Rta_Estado							INT
DECLARE @Respuesta							VARCHAR(8000)
DECLARE @Respuesta_Status					INT
DECLARE @Flag_Carga_Exitosa					TINYINT
DECLARE @Result_Stored_Invocado				INT
DECLARE @Result_Tabla_Stored_Invocado		TABLE ( 
											Respuesta	VARCHAR(MAX),
											Rta_Estado	INT
											)
/*FIN Variables Locales*/

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a Stored Procedure: SPJ_CD_Clientes_Novedades_Reconocimiento_Facial_Procesar'
	PRINT 'Parametros:'
	PRINT ''
END


DECLARE curSPJ_CD_Clientes_Novedades_Reconocimiento_Facial_Procesar CURSOR FOR
SELECT TOP 100
CCN.Id_Novedad, 
CL.Id_Cliente
FROM CD_Clientes_Novedades CCN, Clientes CL, Clientes_Fotos CF
WHERE
CCN.Id_Cliente = CL.Id_Cliente
AND CL.Id_Cliente = CF.Id_Cliente
AND CCN.Estado = 'P'
AND CCN.Id_Cliente > 0

OPEN curSPJ_CD_Clientes_Novedades_Reconocimiento_Facial_Procesar
FETCH NEXT FROM curSPJ_CD_Clientes_Novedades_Reconocimiento_Facial_Procesar INTO @Id_Novedad, @Id_Cliente
WHILE @@FETCH_STATUS = 0
BEGIN

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Id_Novedad: ' + CONVERT(VARCHAR(10), @Id_Novedad)
		PRINT '@Id_Cliente: ' + CONVERT(VARCHAR(10), @Id_Cliente)
		PRINT ''
	END

	SET @pJson_A_Enviar =	'{' + 
						dbo.CF_Json_ParsearVariable('ModoDebug', '1', 'INTEGER') + ',' + 
						dbo.CF_Json_ParsearVariable('API_Metodo', 'suprema_rf_validate', 'INTEGER') + ',' + 
						'"API_Data":{"id_cliente":"' + CONVERT(VARCHAR(10), @Id_Cliente) + '"}' +
						'}'
	
	/* [BioStar push DESHABILITADO 2026-08-03: comentado para no llamar a CleverSoft/BioStar. Backup: backup_SPJ_Procesar_20260803.sql]
	INSERT INTO @Result_Tabla_Stored_Invocado  
	EXEC @Result_Stored_Invocado = dbo.CPJ_CleverAPI_Ejecutar @pJson_A_Enviar
	*/

	IF ISNULL(@Result_Stored_Invocado, 0) <> 0 
	BEGIN
		RAISERROR ('Error when calling CPJ_CleverAPI_Ejecutar', 16, 1)
	END
	ELSE
	BEGIN
		
		SELECT TOP 1 @rta_JSON_Stored_Invocado = Rta_Estado 
		FROM @Result_Tabla_Stored_Invocado
		
		SET @Rta_Estado = @rta_JSON_Stored_Invocado
		
		SELECT TOP 1 @rta_JSON_Stored_Invocado = Respuesta 
		FROM @Result_Tabla_Stored_Invocado
		
		SET @Respuesta = @rta_JSON_Stored_Invocado
		
		SELECT TOP 1 @Flag_Carga_Exitosa = ISNULL(dbo.CF_JSON_VALUE(@Respuesta,'Flag_Carga_Exitosa'), 0)

		SELECT TOP 1 @Respuesta_Status = ISNULL(dbo.CF_JSON_VALUE(@Respuesta,'status'), 0)
		
	END
	
	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Rta_Estado: ' + CONVERT(VARCHAR(10), @Rta_Estado)
		PRINT '@Respuesta: ' + CONVERT(VARCHAR(8000), @Respuesta)
		PRINT '@Flag_Carga_Exitosa: ' + CONVERT(VARCHAR(50), @Flag_Carga_Exitosa)
		PRINT '@Respuesta_Status: ' + CONVERT(VARCHAR(50), @Respuesta_Status)
		PRINT ''
	END
	
	IF (@Rta_Estado = 200 AND @Flag_Carga_Exitosa = 1)
	BEGIN
		UPDATE CD_Clientes_Novedades
		SET
		Estado = 'S'
		WHERE
		Id_Novedad = @Id_Novedad
	END

	IF (@Respuesta_Status = 407 /*Error documento invalido*/)
	BEGIN
		UPDATE CD_Clientes_Novedades
		SET
		Estado = 'E'
		WHERE
		Id_Novedad = @Id_Novedad
	END
	ELSE IF (@Respuesta_Status = 408 /*No esta habilitado en ningun controlador*/)
	BEGIN
		UPDATE CD_Clientes_Novedades
		SET
		Estado = 'S'
		WHERE
		Id_Novedad = @Id_Novedad
	END

	FETCH NEXT FROM curSPJ_CD_Clientes_Novedades_Reconocimiento_Facial_Procesar INTO @Id_Novedad, @Id_Cliente
END
CLOSE curSPJ_CD_Clientes_Novedades_Reconocimiento_Facial_Procesar
DEALLOCATE curSPJ_CD_Clientes_Novedades_Reconocimiento_Facial_Procesar


--EXEC dbo.SPJ_CD_Clientes_Novedades_Reconocimiento_Facial_Procesar '{"ModoDebug":"1"}'
GO


CREATE PROCEDURE [dbo].[SPJ_Cbtes_Ctas_Contables_Generar] @pJson VARCHAR(8000)
AS 
SET NOCOUNT ON


/*
 * LOG VERSIONES:
 * 05/05/2022: En el Debe cuando habia un producto desplegado en meses ponia el importe de solo un periodo
 * 30/6/2022: En el debe se coloca centro de costo vacio
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE	@pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Trans				INT
DECLARE @pFlagRegenerar			TINYINT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Trans					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pFlagRegenerar				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagRegenerar')), 0)
/*FIN Variables recibidas por par├ƒmetro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Declaracion de Variables*/
DECLARE @Flag_Compromete_Asientos	SMALLINT
DECLARE @Flag_Compromete_Factura	SMALLINT
DECLARE @Flag_Compromete_Trans_Fondos SMALLINT
DECLARE @Flag_Compromete_Recibos	SMALLINT
DECLARE @Fecha_Cbte					DATETIME
DECLARE @Id_Cliente					INT
DECLARE @Id_Tipo_Cbte				CHAR(4)
DECLARE @Id_Cta_Contable			INT
DECLARE @Alias						INT
DECLARE @Id_Asiento					INT
DECLARE @Id_Centro_Costo			CHAR(10)
DECLARE @Id_Ejercicio_Corresp		INT
DECLARE @Id_Plan_Cta_Corresp		INT
DECLARE @Imp_Total_Cbte				DECIMAL(12,2)
DECLARE @Debe						DECIMAL(12,2)
DECLARE @Haber						DECIMAL(12,2)
DECLARE @Id_Producto				VARCHAR(14)
DECLARE @Id_Tipo_Reten				VARCHAR(10)
DECLARE @NroItem					SMALLINT
DECLARE @CMC_UltItem				SMALLINT
DECLARE @CMC_UltId_Periodo_Caja		INT
DECLARE @CMC_Id_Concepto			INT
DECLARE @VAL_UltId_Valor			INT
DECLARE @VAL_UltId_Periodo_Caja		INT
DECLARE @VAL_Id_Tipo_Val			CHAR(3)
DECLARE @Id_Cond_Pago				SMALLINT
DECLARE @VAL_Id_Periodo_Caja		INT
DECLARE @CP_Id_Caja					INT
DECLARE @ID_TARJETA                 VARCHAR(10)
DECLARE @ID_CTA_BANCO               SMALLINT
DECLARE @ID_TRANS_ORIGEN            INT
DECLARE @Parametro_Asiento_Vtas_Ptos INT
DECLARE @Cbtes_Items_Imp_Final		DECIMAL(12,2)
DECLARE @Id_Caja					INT
/*FIN Declaracion de Variables*/


BEGIN TRY

	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Cbtes_Ctas_Contables_Generar'
		PRINT 'Par├ƒmetros:'
		PRINT 'FlagUsarTrans: ' + CONVERT(VARCHAR(10), @pFlagUsarTrans) + ' Id_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans) + ' FlagRegenerar: ' + CONVERT(VARCHAR(10), @pFlagRegenerar)
	END

	/*===================================================================*/

	IF(@pId_Trans = 0)   RAISERROR ('Id_trans can not be zero.', 16,  1 ) 
	
	/*===================================================================*/	

	SET @Parametro_Asiento_Vtas_Ptos = dbo.CF_xParam('Asiento_Vtas_Ptos')

	IF(@pModoDebug = 1)
	BEGIN
		PRINT '@Parametro_Asiento_Vtas_Ptos: ' + CONVERT(VARCHAR(10), @Parametro_Asiento_Vtas_Ptos)
	END

	/*===================================================================*/	

	IF(@pFlagRegenerar = 1)
	BEGIN
		DELETE FROM Cbtes_Ctas_Contables WHERE Id_Trans = @pId_Trans
	END


	/*************************************************************************************************/

	SET @Id_Tipo_Cbte				= (SELECT Id_Tipo_Cbte FROM Cbtes WHERE Id_Trans = @pId_Trans)

	SELECT  @Flag_Compromete_Asientos		= ISNULL(Compromete_Asientos, 0),
			@Flag_Compromete_Factura		= ISNULL(Compromete_Factura, 0),
			@Flag_Compromete_Trans_Fondos	= ISNULL(Compromete_Trans_Fondos, 0),
			@Flag_Compromete_Recibos		= ISNULL(Compromete_Recibos, 0)
	FROM Cbtes_Tipos
	WHERE 
	Id_Tipo_Cbte = @Id_Tipo_Cbte

	/*************************************************************************************************/

	IF(@Flag_Compromete_Asientos = 0)
	BEGIN
		IF @pFlagUsarTrans <> 0 
		BEGIN
			COMMIT
		END
		SET @rtaMsjStored = 'El Cbte. no Genera Asiento'

		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@rtaMsjStored	AS ErrorMessage

			
		RETURN 0
	END

	/*************************************************************************************************/

	SELECT  @Id_Cliente		= ISNULL(Id_Cliente, 0),
			@Fecha_Cbte		= ISNULL(Fecha, '19000101'),
			@Imp_Total_Cbte	= ISNULL(Imp_Total, 0)
			FROM Cbtes
			WHERE 
			Id_Trans = @pId_Trans

	/*************************************************************************************************/

	SET @Id_Ejercicio_Corresp = (SELECT Id_Ejercicio FROM Plan_Ctas_Ejercicios WHERE Fecha_Inicio <= @Fecha_Cbte AND DATEADD(dd, 1, Fecha_Cierre) > @Fecha_Cbte)
	SET @Id_Plan_Cta_Corresp = (SELECT Id_Plan_Cta FROM Plan_Ctas WHERE Id_Ejercicio = @Id_Ejercicio_Corresp)
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Nro. de Ejercicio: ' + CONVERT(VARCHAR(10), @Id_Ejercicio_Corresp) + '. Nro. Plan de Cuenta: ' + CONVERT(VARCHAR(10), @Id_Plan_Cta_Corresp)
	END

	IF(@Flag_Compromete_Factura = 1)
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Compromete Factura'
		END
	
		SET @Id_Cond_Pago = (SELECT Id_Cond_Pago FROM Cbtes WHERE Id_Trans = @pId_Trans)
	
		IF(@Id_Cond_Pago NOT IN (1)) /*Si no es contado*/
		BEGIN
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Cond. Pago NO ES CONTADO. @Id_Cond_Pago: ' + CONVERT(VARCHAR(10), @Id_Cond_Pago)
			END

			/*Insert: Cuenta Contable: DEBE (SI la Cond. Pago NO es Contado)*/
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Generacion Cuenta Contable: DEBE'
			END

			IF(@pModoDebug = 1)
			BEGIN
				PRINT '@Parametro_Asiento_Vtas_Ptos: ' + CONVERT(VARCHAR(10), @Parametro_Asiento_Vtas_Ptos)
			END

			IF(@Parametro_Asiento_Vtas_Ptos = 0)
			BEGIN
				SET @Alias = (SELECT ISNULL(Id_Alias_Cta_Cont_Venta, 0) FROM Clientes WHERE Id_Cliente = @Id_Cliente)
				SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
				SET @Id_Centro_Costo ='' /* 30/6/22 Pongo en CC vacio en el Debe*/ 
				SET @Debe = @Imp_Total_Cbte
				SET @NroItem = 1
				IF(@pModoDebug = 1)
				BEGIN
					PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
				END

				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				@Debe,			0/*Haber*/,			''/*Observacion*/,
				@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
				@NroItem)

			END
			ELSE
			BEGIN
				DECLARE curGenCtaCteDebexProduc CURSOR FOR 							
				SELECT DISTINCT Id_Producto, SUM(Imp_Final) AS Imp_Final FROM Cbtes_Items WHERE Id_Trans = @pId_Trans GROUP BY Id_Producto
				--05/05/2022 Se agrupa para items de meses continuos, antes ponia en el debe solo un item por el monto de un periodo
				--SELECT DISTINCT Id_Producto, Imp_Final FROM Cbtes_Items WHERE Id_Trans = @pId_Trans
				SET @NroItem = 0
				OPEN curGenCtaCteDebexProduc
				FETCH NEXT FROM curGenCtaCteDebexProduc INTO @Id_Producto, @Cbtes_Items_Imp_Final
				WHILE @@FETCH_STATUS = 0
				BEGIN
					IF(@pModoDebug = 1)
					BEGIN
						PRINT 'Id_Producto: ' + @Id_Producto + '. Imp_Final: ' + CONVERT(VARCHAR(20), @Cbtes_Items_Imp_Final)
					END

					SET @Alias = (SELECT ISNULL(Id_Alias_Cta_Deudores, 0) FROM Productos WHERE Id_Producto = @Id_Producto)
					SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
					SET @Id_Centro_Costo =''/* 30/6/22 Pongo en CC vacio en el Debe*/ --- ISNULL((SELECT ISNULL(Id_Centro_Costo, '') FROM Productos WHERE Id_Producto = @Id_Producto),'')
					SET @Debe = @Cbtes_Items_Imp_Final
					SET @NroItem = @NroItem + 1
					IF(@pModoDebug = 1)
					BEGIN
						PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
					END

					INSERT INTO Cbtes_Ctas_Contables
					(Id_Trans,		Id_Cta_Contable,	Fecha,
					Debe,			Haber,				Observacion,
					Alias,			Id_Asiento,			Id_Centro_Costo,
					Item)
					VALUES									
					(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
					@Debe,			0/*Haber*/,			''/*Observacion*/,
					@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
					@NroItem)

					FETCH NEXT FROM curGenCtaCteDebexProduc INTO @Id_Producto, @Cbtes_Items_Imp_Final
				END 
				CLOSE curGenCtaCteDebexProduc;
				DEALLOCATE curGenCtaCteDebexProduc;
			END
			/*FIN Insert: Cuenta Contable: DEBE (SI la Cond. Pago NO es Contado)*/
		END
		ELSE
		BEGIN
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Cond. Pago ES CONTADO'
			END

			/*Insert: Cuenta Contable: DEBE (SI la Cond. Pago ES Contado)*/
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Generacion Cuenta Contable: DEBE'
			END

			SET @VAL_Id_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores_Mov WHERE Id_Trans = @pId_Trans), 0)		
			SET @CP_Id_Caja = ISNULL((SELECT Id_Caja FROM Cajas_Periodos WHERE Id_Periodo_Caja = @VAL_Id_Periodo_Caja), 0)		
			SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Cajas WHERE Id_Caja = @CP_Id_Caja), 0)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Alias = @Alias AND Id_Plan_Cta = @Id_Plan_Cta_Corresp)
			SET @Id_Centro_Costo = ISNULL((SELECT Id_Centro_Costo FROM Cajas WHERE Id_Caja = @CP_Id_Caja), '')
			SET @Debe = @Imp_Total_Cbte
			SET @NroItem = 1
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
			END
		
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			@Debe,			0/*Haber*/,			''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)
			/*FIN Insert: Cuenta Contable: DEBE (SI la Cond. Pago ES Contado)*/
		END
	
		/*Insert: Cuenta Contable: HABER*/
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Generacion Cuenta Contable: HABER'
		END
	
		--PRINT 'Generacion de Items de Productos'
		DECLARE curGenCtaCteHaber CURSOR FOR 
			SELECT DISTINCT Id_Producto FROM Cbtes_Items WHERE Id_Trans = @pId_Trans

		OPEN curGenCtaCteHaber
		FETCH NEXT FROM curGenCtaCteHaber INTO @Id_Producto
		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @Alias = (SELECT Id_Alias_Cta_Cont FROM Productos WHERE Id_Producto = @Id_Producto)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = ISNULL((SELECT Id_Centro_Costo FROM Productos WHERE Id_Producto = @Id_Producto),'')
			SET @Haber = (SELECT SUM(Imp_Gravado) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Id_Producto = @Id_Producto)
			SET @NroItem = @NroItem + 1
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Producto: ' + @Id_Producto + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
			END
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)

		FETCH NEXT FROM curGenCtaCteHaber INTO @Id_Producto
		END 
		CLOSE curGenCtaCteHaber;
		DEALLOCATE curGenCtaCteHaber;
		/*FIN Insert: Cuenta Contable: HABER*/

		IF(@pModoDebug = 1)
		BEGIN
	 		PRINT 'Generacion de Items de Percepciones'	
		END

		DECLARE curGenCtaCteHaberPercep CURSOR FOR 
			SELECT DISTINCT Id_Tipo_Reten	FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans

		OPEN curGenCtaCteHaberPercep
		FETCH NEXT FROM curGenCtaCteHaberPercep INTO @Id_Tipo_Reten
		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @Alias = (SELECT Id_Cta_Contable FROM Cbtes_Reten_Tipos WHERE Id_Tipo_Reten = @Id_Tipo_Reten)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = ''
			SET @Haber = (SELECT SUM(Importe) FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans AND Id_Tipo_Reten = @Id_Tipo_Reten)
			SET @NroItem = @NroItem + 1			
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Tipo_Reten: ' + @Id_Tipo_Reten + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
			END
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)

		FETCH NEXT FROM curGenCtaCteHaberPercep INTO @Id_Tipo_Reten
		END 
		CLOSE curGenCtaCteHaberPercep;
		DEALLOCATE curGenCtaCteHaberPercep;

		IF(@pModoDebug = 1)
		BEGIN	
			PRINT 'Generacion de Items de Iva'
		END
		SET @Alias = (SELECT ISNULL(Valor_Integer,0) FROM xParametros WHERE IdParametro = 'Iva_Debito_Fiscal')
		SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
		SET @Id_Centro_Costo = ''
		SET @Haber = (SELECT SUM(Imp_Iva) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Id_Producto IN (SELECT Id_Producto FROM Productos WHERE Id_Iva IN (SELECT Id_Iva FROM Productos_TasaIva WHERE (Porc1 <> 0 OR Porc1 IS NOT NULL))))
	
		IF(@Haber <> 0)
		BEGIN
			SET @NroItem = @NroItem + 1

			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
			END
			
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)		
		END
	
		----PRINT 'FIN Compromete Factura'
	END /*IF(@Flag_Compromete_Factura = 1)*/

/*************************************************************************************************/

IF(@Flag_Compromete_Factura =-1) /*NC*/
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Compromete Factura -1 ES NC'
		END

		SET @Id_Cond_Pago = (SELECT Id_Cond_Pago FROM Cbtes WHERE Id_Trans = @pId_Trans)
	
		IF(@Id_Cond_Pago NOT IN (1)) /*Si no es contado*/
		BEGIN
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Cond. Pago NO ES CONTADO. @Id_Cond_Pago: ' + CONVERT(VARCHAR(10), @Id_Cond_Pago)
			END
		
			/*Insert: Cuenta Contable: DEBE (SI la Cond. Pago NO es Contado)*/
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Generacion Cuenta Contable: DEBE'
			END
			SET @Alias = (SELECT Id_Alias_Cta_Cont_Venta FROM Clientes WHERE Id_Cliente = @Id_Cliente)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = ISNULL((SELECT Id_Centro_Costo FROM Clientes WHERE Id_Cliente = @Id_Cliente),'')
			SET @Haber = @Imp_Total_Cbte
			SET @NroItem = 1
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
			END
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0,			    @Haber/*Haber*/,			''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)
			/*FIN Insert: Cuenta Contable: HABER (SI la Cond. Pago NO es Contado)*/
		END
		ELSE
		BEGIN
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Cond. Pago ES CONTADO'
			END
		
			/*Insert: Cuenta Contable: HABER (SI la Cond. Pago ES Contado)*/
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Generacion Cuenta Contable: HABER'
			END
			SET @VAL_Id_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE Id_Trans = @pId_Trans), 0)		
			SET @CP_Id_Caja = ISNULL((SELECT Id_Caja FROM Cajas_Periodos WHERE Id_Periodo_Caja = @VAL_Id_Periodo_Caja), 0)		
			SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Cajas WHERE Id_Caja = @CP_Id_Caja), 0)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Alias = @Alias AND Id_Plan_Cta = @Id_Plan_Cta_Corresp)
			SET @Id_Centro_Costo = ISNULL((SELECT  Id_Centro_Costo FROM Cajas WHERE Id_Caja = @CP_Id_Caja), '')
			SET @Haber = @Imp_Total_Cbte
			SET @NroItem = 1
			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
			END
		
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0,			    @Haber/*Haber*/,			''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)
			/*FIN Insert: Cuenta Contable: HABER (SI la Cond. Pago ES Contado)*/
		END
	
		/*Insert: Cuenta Contable: DEBE*/
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Generacion Cuenta Contable: DEBE'
		END
	
		--PRINT 'Generacion de Items de Productos'
		DECLARE curGenCtaCteHaber CURSOR FOR 
			SELECT DISTINCT Id_Producto FROM Cbtes_Items WHERE Id_Trans = @pId_Trans

		OPEN curGenCtaCteHaber
		FETCH NEXT FROM curGenCtaCteHaber INTO @Id_Producto
		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @Alias = (SELECT Id_Alias_Cta_Cont FROM Productos WHERE Id_Producto = @Id_Producto)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = (SELECT Id_Centro_Costo FROM Productos WHERE Id_Producto = @Id_Producto)
			SET @Debe = (SELECT SUM(Imp_Gravado) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Id_Producto = @Id_Producto)
			SET @NroItem = @NroItem + 1

			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Producto: ' + @Id_Producto + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
			END
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			@Debe/*Debe*/,		0,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)

		FETCH NEXT FROM curGenCtaCteHaber INTO @Id_Producto
		END 
		CLOSE curGenCtaCteHaber;
		DEALLOCATE curGenCtaCteHaber;
		/*FIN Insert: Cuenta Contable: DEBE*/

		IF(@pModoDebug = 1)
		BEGIN	
			PRINT 'Generacion de Items de Percepciones'	
		END

		DECLARE curGenCtaCteHaberPercep CURSOR FOR 
			SELECT DISTINCT Id_Tipo_Reten	FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans

		OPEN curGenCtaCteHaberPercep
		FETCH NEXT FROM curGenCtaCteHaberPercep INTO @Id_Tipo_Reten
		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @Alias = (SELECT Id_Cta_Contable FROM Cbtes_Reten_Tipos WHERE Id_Tipo_Reten = @Id_Tipo_Reten)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = ''
			SET @Debe = (SELECT SUM(Importe) FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans AND Id_Tipo_Reten = @Id_Tipo_Reten)
			SET @NroItem = @NroItem + 1

			IF(@pModoDebug = 1)
			BEGIN
				PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Tipo_Reten: ' + @Id_Tipo_Reten + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
			END
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			@Debe/*Debe*/,		0,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)

		FETCH NEXT FROM curGenCtaCteHaberPercep INTO @Id_Tipo_Reten
		END 
		CLOSE curGenCtaCteHaberPercep;
		DEALLOCATE curGenCtaCteHaberPercep;
	
		----PRINT 'Generacion de Items de Iva'
		SET @Alias = (SELECT ISNULL(Valor_Integer,0) FROM xParametros WHERE IdParametro = 'Iva_Debito_Fiscal')
		SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
		SET @Id_Centro_Costo = ''
		SET @Debe = (SELECT SUM(Imp_Iva) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Id_Producto IN (SELECT Id_Producto FROM Productos WHERE Id_Iva IN (SELECT Id_Iva FROM Productos_TasaIva WHERE (Porc1 <> 0 OR Porc1 IS NOT NULL))))
	
		IF(@Debe <> 0)
		BEGIN
			SET @NroItem = @NroItem + 1
		
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			@Debe/*Debe*/,	0,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)		
		END
		IF(@pModoDebug = 1)
		BEGIN	
			PRINT 'FIN Compromete Factura -1 '
		END
	END /*IF(@Flag_Compromete_Factura = -1  NC)*/

/*************************************************************************************************/

	IF(@Flag_Compromete_Trans_Fondos = 1)
	BEGIN
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Compromete Transferencia de Fondos'
		END

		/*Insert: Cuenta Contable: DEBE*/
		----PRINT 'Generacion Cuenta Contable: DEBE'
		SET @CMC_UltItem = ISNULL((SELECT MAX(Item) FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Cajas_Mov_Conceptos. Ult. Item Generado: ' + CONVERT(VARCHAR(10), @CMC_UltItem)
	
		IF(@CMC_UltItem <> 0)
		BEGIN
			SET @CMC_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans AND Item = @CMC_UltItem), 0)
		
			----PRINT 'Generacion de Items por cada concepto del Periodo de Caja: ' + CONVERT(VARCHAR(10), @CMC_UltId_Periodo_Caja)
			DECLARE curGenCtaCteDebe_CMC CURSOR FOR 
				SELECT DISTINCT Id_Concepto FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans
								AND Id_Periodo_Caja = @CMC_UltId_Periodo_Caja
		
			SET @NroItem = 0
		
			OPEN curGenCtaCteDebe_CMC
			FETCH NEXT FROM curGenCtaCteDebe_CMC INTO @CMC_Id_Concepto
			WHILE @@FETCH_STATUS = 0
			BEGIN
			    SET @Haber = 0
				SET @debe = 0
				SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Conceptos WHERE Id_Concepto = @CMC_Id_Concepto),0)
				SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)	
				SET @Debe = (SELECT ISNULL(SUM(Importe), 0) FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans AND Id_Concepto = @CMC_Id_Concepto AND Id_Periodo_Caja = @CMC_UltId_Periodo_Caja)
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Concepto: ' + CONVERT(VARCHAR(10), @CMC_Id_Concepto) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				 Debe,			Haber,				Observacion,
				 Alias,			Id_Asiento,			Id_Centro_Costo,
				 Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				 @Debe,			@Haber,			''/*Observacion*/,
				 @Alias,			0/*Id_Asiento*/,	''/*Id_Centro_Costo*/,
				 @NroItem)

				FETCH NEXT FROM curGenCtaCteDebe_CMC INTO @CMC_Id_Concepto
			END 
			CLOSE curGenCtaCteDebe_CMC;
			DEALLOCATE curGenCtaCteDebe_CMC;
		END /*IF(@CMC_UltItem <> 0)*/
	
		/*Insert: Cuenta Contable: HABER*/
		----PRINT 'Generacion Cuenta Contable: HABER'
		SET @VAL_UltId_Valor = ISNULL((SELECT MAX(Id_Valor) FROM Valores WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
	
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
			SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE Id_Trans = @pId_Trans AND Id_Valor = @VAL_UltId_Valor), 0)
		
			----PRINT 'Generacion de Items por cada Id_Tipo_Val del Periodo de Caja: ' + CONVERT(VARCHAR(10), @VAL_UltId_Periodo_Caja)
			DECLARE curGenCtaCteHaber_Val CURSOR FOR 
				SELECT DISTINCT Id_Tipo_Val 
				FROM Valores 
				WHERE 
				Id_Trans = @pId_Trans
				AND Id_Periodo_Caja = @VAL_UltId_Periodo_Caja
		
			OPEN curGenCtaCteHaber_Val
			FETCH NEXT FROM curGenCtaCteHaber_Val INTO @VAL_Id_Tipo_Val
			WHILE @@FETCH_STATUS = 0
			BEGIN
				SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tipos WHERE Id_Tipo_Val = @VAL_Id_Tipo_Val), 0)
				SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
				SET @Haber = (SELECT SUM(Importe) FROM Valores WHERE Id_Trans = @pId_Trans AND Id_Tipo_Val = @VAL_Id_Tipo_Val AND Id_Periodo_Caja = @VAL_UltId_Periodo_Caja)
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				0/*Debe*/,		@Haber,				''/*Observacion*/,
				@Alias,			0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)

				FETCH NEXT FROM curGenCtaCteHaber_Val INTO @VAL_Id_Tipo_Val
			END 
			CLOSE curGenCtaCteHaber_Val;
			DEALLOCATE curGenCtaCteHaber_Val;		
		END
	
		----PRINT 'FIN Compromete Transferencia de Fondos'
	END /*IF(@Flag_Compromete_Trans_Fondos = 1)*/

	IF(@Flag_Compromete_Recibos = 1)
	BEGIN
	    DECLARE @Tomar_Asiento_Cbte SMALLINT 
		SET @Tomar_Asiento_Cbte = (SELECT ISNULL(Valor_Integer,0) FROM xParametros WHERE IdParametro = 'Tomar_Asiento_Cbte') 

	    SET @NroItem = 1	
		----PRINT 'Compromente Recibos'
		
		----PRINT 'Generacion Cuenta Contable: DEBE'

		SET @VAL_UltId_Valor = ISNULL((SELECT MAX(Id_Valor) FROM Valores_Mov WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
	
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
			SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE  Id_Valor = @VAL_UltId_Valor), 0)
		
			----PRINT 'Generacion de Items por cada Id_Tipo_Val del Periodo de Caja: ' + CONVERT(VARCHAR(10), @VAL_UltId_Periodo_Caja)
			DECLARE curGenCtaDEBE_Val CURSOR FOR 
					SELECT DISTINCT V.Id_Tipo_Val,ISNULL(V.ID_TARJETA,''),ISNULL(V.ID_CTA_BANCO,0)
					FROM Valores_MOV M, VALORES V 
					WHERE 
					M.Id_Trans = @pId_Trans
					AND M.ID_VALOR = V.ID_VALOR
					AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja



		
			OPEN curGenCtaDEBE_Val
			FETCH NEXT FROM curGenCtaDEBE_Val INTO @VAL_Id_Tipo_Val,@ID_TARJETA,@ID_CTA_BANCO
			WHILE @@FETCH_STATUS = 0
			BEGIN
			    SET @Alias = 0 
			    IF @VAL_Id_Tipo_Val = 'TAR'
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tarjetas_Cred WHERE ID_TARJETA = @ID_TARJETA), 0)
                   END

					/********AGREGO 2020-02-08**********************************************/
				   IF @VAL_Id_Tipo_Val = 'EFE'
				   BEGIN
						SET @Id_Caja = ISNULL((SELECT ISNULL(id_Caja,0) FROM Cajas_Periodos WHERE id_periodo_caja= @VAL_UltId_Periodo_Caja), 0)
						SET @Alias = ISNULL((SELECT ISNULL (id_alias_cta_cont,0) FROM Cajas_Ctas_Cont WHERE Id_caja=@Id_Caja AND  id_tipo_val='EFE'), 0)
						IF(@Alias = 0)
						BEGIN
							SET @Alias = ISNULL((SELECT ISNULL(id_cta_contable,0) FROM  cajas  WHERE id_caja= @Id_Caja),0)
						END
                   END
					/***************   FIN   EFE *********************/

			    IF @VAL_Id_Tipo_Val = 'DB'
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Bancos_Ctas WHERE Id_Cta_Banco = @ID_CTA_BANCO), 0)
                   END	    
				IF @Alias = 0  
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tipos WHERE Id_Tipo_Val = @VAL_Id_Tipo_Val), 0)
                   END


				SET @Id_Cta_Contable = 	  (SELECT dbo.CF_Cta_Cont(@Alias, @Fecha_Cbte))
				SET @NroItem = @NroItem + 1
			    SET @Id_Centro_Costo = ''
			    SET @Debe = (SELECT SUM(V.Importe) FROM Valores V, Valores_Mov M WHERE M.Id_Trans = @pId_Trans AND M.id_valor = V.Id_Valor And V.Id_Tipo_Val = @VAL_Id_Tipo_Val AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja AND ISNULL(V.Id_Tarjeta,'') = @ID_TARJETA AND ISNULL(V.Id_Cta_Banco,0) = @Id_Cta_Banco)
	
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				@Debe,		0,				''/*Observacion*/,
				@Alias,		0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)

				FETCH NEXT FROM curGenCtaDEBE_Val INTO @VAL_Id_Tipo_Val,@ID_TARJETA,@ID_CTA_BANCO
			END 
			CLOSE curGenCtaDEBE_Val;
			DEALLOCATE curGenCtaDEBE_Val;		
		END

		/*Insert: Cuenta Contable: HABER*/
		----PRINT 'Generacion Cuenta Contable: HABER'
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
		
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
		    IF @Tomar_Asiento_Cbte = 0
			BEGIN
				SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE Id_Valor = @VAL_UltId_Valor), 0)
				
				SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont_Venta FROM Clientes WHERE Id_Cliente = @Id_Cliente), 0)
				SET @Id_Cta_Contable = (SELECT dbo.CF_Cta_Cont(@Alias, @Fecha_Cbte))
				SET @Haber = (SELECT SUM(V.Importe) FROM Valores V, Valores_Mov M WHERE M.Id_Trans = @pId_Trans AND M.id_valor = V.Id_Valor  AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja )
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				0/*Debe*/,		@Haber,				''/*Observacion*/,
				@Alias,			0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)
		    END
		   ELSE
			BEGIN
			SELECT * INTO #CTAS_AUX FROM CBTES_CTAS_CONTABLES WHERE ID_TRANS = 1
			DELETE #CTAS_AUX

			DECLARE curGenCtaDEBE_FAC_APLIC2 CURSOR FOR 


			SELECT ID_TRANS
				FROM CBTES_APLICA WHERE ID_TRANS_D = @pId_Trans

		
				OPEN curGenCtaDEBE_FAC_APLIC2
				FETCH NEXT FROM curGenCtaDEBE_FAC_APLIC2 INTO @ID_TRANS_ORIGEN
				WHILE @@FETCH_STATUS = 0
				BEGIN
				    INSERT INTO #CTAS_AUX
					    SELECT * FROM CBTES_CTAS_CONTABLES WHERE ID_TRANS = @ID_TRANS_ORIGEN AND DEBE <> 0

				    FETCH NEXT FROM curGenCtaDEBE_FAC_APLIC2 INTO  @ID_TRANS_ORIGEN
		    	END 

				ALTER TABLE #CTAS_AUX ADD _Item INT IDENTITY(20,1)
		      	UPDATE #CTAS_AUX SET ID_TRANS = @pId_Trans,  Id_Cta_Contable = (SELECT dbo.CF_Cta_Cont(Alias, @Fecha_Cbte))
				UPDATE #CTAS_AUX SET Item = _Item, Id_Asiento = 0, Fecha = @Fecha_Cbte, HABER = DEBE
				UPDATE #CTAS_AUX SET DEBE = 0
				ALTER TABLE #CTAS_AUX DROP COLUMN _Item

				INSERT INTO CBTES_CTAS_CONTABLES 
				       SELECT * FROM #CTAS_AUX
                DROP TABLE #CTAS_AUX

			    CLOSE curGenCtaDEBE_FAC_APLIC2
			    DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 
	    	END
		
		END ----PRINT 'FIN Compromente Recibos'
	END	
	/*===================================================================*/	
	
	IF @pFlagUsarTrans <> 0 
	BEGIN
		COMMIT
	END
	
	/*===================================================================*/	

	SET @rtaMsjStored		=	'{' +
								dbo.CF_Json_ParsearVariable('id_trans', @pId_Trans, 'INT') +
								'}'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@rtaMsjStored	AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Cbtes_Ctas_Contables_Generar'
	END

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo
	
	IF ISNULL(@pFlagUsarTrans,0) <> 0 
	BEGIN
		ROLLBACK
	END

	---------------------------------------------------------------------------------------

	IF (SELECT CURSOR_STATUS('global','curGenCtaCteHaber') ) = -1
	   DEALLOCATE curGenCtaCteHaber		 

	IF (SELECT CURSOR_STATUS('global','curGenCtaCteHaber') ) = 1
	BEGIN
	   CLOSE curGenCtaCteHaber 
	   DEALLOCATE curGenCtaCteHaber		 
	END
	---------------------------------------------------------------------------------------

	IF (SELECT CURSOR_STATUS('global','curGenCtaCteHaberPercep') ) = -1
	   DEALLOCATE curGenCtaCteHaberPercep		 

	IF (SELECT CURSOR_STATUS('global','curGenCtaCteHaberPercep') ) = 1
	BEGIN
	   CLOSE curGenCtaCteHaberPercep
	   DEALLOCATE curGenCtaCteHaberPercep		 
	END
	---------------------------------------------------------------------------------------

	IF (SELECT CURSOR_STATUS('global','curGenCtaCteDebe_CMC') ) = -1
	   DEALLOCATE curGenCtaCteDebe_CMC		 

	IF (SELECT CURSOR_STATUS('global','curGenCtaCteDebe_CMC') ) = 1
	BEGIN
	   CLOSE curGenCtaCteDebe_CMC
	   DEALLOCATE curGenCtaCteDebe_CMC 		 
	END
	---------------------------------------------------------------------------------------

	IF (SELECT CURSOR_STATUS('global','curGenCtaCteHaber_Val') ) = -1
	   DEALLOCATE curGenCtaCteHaber_Val		 

	IF (SELECT CURSOR_STATUS('global','curGenCtaCteHaber_Val') ) = 1
	BEGIN
	   CLOSE curGenCtaCteHaber_Val
	   DEALLOCATE curGenCtaCteHaber_Val		 
	END
	---------------------------------------------------------------------------------------

	IF (SELECT CURSOR_STATUS('global','curGenCtaDEBE_Val') ) = -1
	   DEALLOCATE curGenCtaDEBE_Val		 

	IF (SELECT CURSOR_STATUS('global','curGenCtaDEBE_Val') ) = 1
	BEGIN
	   CLOSE curGenCtaDEBE_Val
	   DEALLOCATE curGenCtaDEBE_Val		 
	END
	---------------------------------------------------------------------------------------

	IF (SELECT CURSOR_STATUS('global','curGenCtaDEBE_FAC_APLIC2') ) = -1
	   DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 

	IF (SELECT CURSOR_STATUS('global','curGenCtaDEBE_FAC_APLIC2') ) = 1
	BEGIN
	   CLOSE curGenCtaDEBE_FAC_APLIC2
	   DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 
	END
	---------------------------------------------------------------------------------------


	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[SPJ_Clientes_Deuda_a_Fecha] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON
/*Parametros*/

DECLARE 	@pFechaHasta			DATETIME,
			@pId_Unid_Negocio       VARCHAR(10),
			@pFiltrar_con_saldo     TINYINT,
			@pClientes_activos      TINYINT,
			@pFiltroFecha           TINYINT,
			@pCriterio              VARCHAR(2),
			@pId_Cliente            INT,
			@pInc_UCP_a_Fecha		TINYINT,
			@pLimite				INT
			 
SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())
SET @pFiltrar_con_saldo			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Filtrar_con_saldo')),0)
SET @pClientes_activos			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Clientes_activos')),0)
SET @pFiltroFecha		    	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FiltroFecha')),0)
SET @pCriterio			        = ISNULL(CONVERT(VARCHAR(2), dbo.CF_JSON_VALUE(@pJsonRecibido,'Criterio')),'R')
SET @pId_Cliente  		    	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')),0)
SET @pInc_UCP_a_Fecha  		   	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Inc_UCP_a_Fecha')),0)
SET @pLimite		  		   	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Limite')),0)

 
DECLARE @pFecha DATETIME
SET @pFecha  = @pFechaHasta+1

DECLARE @Agrupar_GF TinyInt
SET @Agrupar_GF =  dbo.CF_xParam('Cli_Ref_CtaCte_Agrup')

SELECT Id_Cliente_Ref
    	INTO #Clientes FROM Clientes WHERE 1=0


		SELECT Id_cliente,Id_Cliente_Ref,Razon_Social
    			INTO #Clientes_Temp FROM Clientes WHERE 1=0
		
		
		IF @pId_Cliente <> 0
			 INSERT INTO #Clientes_Temp SELECT Id_Cliente, CASE ISNULL(Id_Cliente_Ref,0) 
										WHEN 0 THEN Id_Cliente
										ELSE Id_Cliente_Ref
										END AS Id_Cliente_Ref,Razon_Social
										FROM Clientes z
										WHERE Id_Cliente = @pId_Cliente
		  ELSE
		   IF @pClientes_activos = 1
			  INSERT INTO #Clientes_Temp SELECT Id_Cliente, CASE ISNULL(Id_Cliente_Ref,0) 
										WHEN 0 THEN Id_Cliente
										ELSE Id_Cliente_Ref
										END AS Id_Cliente_Ref,Razon_Social
										FROM Clientes WHERE Id_Tipo_Cli NOT IN (10,1005,1011,1015,1018,1019,1101,1102,1103,1105,1113,1114,1127,1128,1129,1132,1133,1134) --Excluidos
										AND Activo = 1 OR (ACTIVO=0 and Fecha_Baja > @pFecha)
									
 
			INSERT INTO #Clientes SELECT DISTINCT(Id_Cliente_Ref) FROM #Clientes_Temp
		

--#Clientes contiene todos los socios sin discriminar titular o integrante
/*---------------------------COMPROBANTES ADEUDADOS A LA FECHA DE CORTE ----------------------------------------------------*/

SELECT Id_unid_Negocio INTO #Unid_Negocios FROM Empresas_Unid_Negocios
If @pId_Unid_Negocio <> ''
   DELETE #Unid_Negocios WHERE Id_unid_Negocio <> @pId_Unid_Negocio

--paso 1 FC


SELECT K.Id_Cliente_Ref AS Id_Cliente
	   ,C.ID_TIPO_CBTE
	   ,C.COMPROBANTE_NRO
	   ,C.FECHA
	   ,(C.Imp_Total * T.Compromete_Factura) AS IMP_TOTAL
	   ,ISNULL((SELECT SUM(ISNULL(A.Importe,0)) 
				FROM Cbtes_Aplica a, cbtes p, Cbtes_Tipos tp 
				WHERE p.Id_Trans = A.ID_TRANS_D  
				AND A.ID_TRANS = C.Id_Trans 
				AND p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte 
				AND  ( tp.Compromete_Recibos in (1,-1) OR tp.Compromete_Factura in (-1))
				AND P.FECHA < @pFecha AND p.id_estado_cbte NOT IN (0,3)),0) AS Imp_Aplicado 
	,CAST(0 AS DECIMAL(12,2)) AS Imp_Aplicado2
	,(C.SALDO * T.Compromete_Factura) AS SALDO
	,C.ID_TRANS,1 AS SIGNO
	INTO #DEUDA
	FROM CBTES C
	 JOIN CBTES_TIPOS T ON  C.Id_Tipo_Cbte = T.ID_TIPO_CBTE AND T.Compromete_Factura IN (1)
	 JOIN #Unid_Negocios U ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
	 JOIN Clientes O ON  C.Id_Cliente = O.ID_Cliente
	 , #Clientes k
	WHERE  CASE ISNULL(O.Id_Cliente_Ref,0) 
								WHEN 0 THEN O.Id_Cliente
								ELSE O.Id_Cliente_Ref
								END = K.Id_Cliente_Ref
		AND C.Id_Estado_Cbte NOT IN (0,3)
		AND C.Id_Cond_Pago <> 1
		AND C.Id_Cliente > 1
		AND C.Fecha >'20190630' /*Fecha de Corte anterior 25/02/2025*/
		AND C.FECHA < @pFecha
		AND C.Imp_Total > 0.01 /*Se agrega para quitar de la deuda lo que ellos brindan como servicio que no se paga*/
		AND ( NOT EXISTS  (SELECT A.ID_TRANS FROM CBTES_APLICA A WHERE C.ID_TRANS = A.ID_TRANS) OR C.SALDO > 0.01
		OR (SELECT MAX(p.fecha)
					 FROM cbtes_aplica a
					 JOIN cbtes p ON p.Id_Trans = A.ID_TRANS_D AND p.id_estado_cbte not in (0,3)
					 JOIN Cbtes_Tipos tp ON p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte AND (tp.Compromete_Recibos in (1,-1) 
						OR ( tp.Compromete_Factura in (-1)   AND P.Id_Cond_Pago <> 1)
						)
					 WHERE  A.ID_TRANS = C.Id_Trans ) >= @pFecha )

-- paso 2 NC

UNION ALL

SELECT	K.Id_Cliente_Ref AS Id_Cliente
		,C.ID_TIPO_CBTE
		,C.COMPROBANTE_NRO
		,C.FECHA
		,(C.IMP_TOTAL* T.Compromete_Factura) AS IMP_TOTAL
		,(SELECT isnull(SUM(A.Importe),0)
					 FROM cbtes_aplica a
					 JOIN cbtes p ON p.Id_Trans = A.ID_TRANS AND P.Id_Cond_Pago <> 1 AND P.FECHA < @pFecha AND p.id_estado_cbte not in (0,3)
					 JOIN Cbtes_Tipos tp ON p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte   AND  ( tp.Compromete_Recibos in (1,-1) OR tp.Compromete_Factura in (1))
					 WHERE A.ID_TRANS_D = C.Id_Trans ) AS Imp_Aplicado 
		,CAST(0 AS DECIMAL(12,2)) AS Imp_Aplicado2
		,(C.SALDO* T.Compromete_Factura) AS SALDO
		,C.ID_TRANS
		,-1 AS SIGNO
	FROM CBTES C
	   JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.ID_TIPO_CBTE AND T.Compromete_Factura IN (-1)
	   JOIN #Unid_Negocios U ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
	   JOIN Clientes O ON C.Id_Cliente = O.ID_Cliente
	   ,#Clientes K 
	WHERE CASE ISNULL(O.Id_Cliente_Ref,0) 
								WHEN 0 THEN O.Id_Cliente
								ELSE O.Id_Cliente_Ref
								END = K.Id_Cliente_Ref
		AND C.Id_Cond_Pago <> 1
		AND C.Id_Estado_Cbte NOT IN (0,3)
		AND C.Id_Cliente > 1
		AND C.Fecha >'20190630' /*Fecha de Corte anterior 25/02/2025*/
		AND C.FECHA < @pFecha
		AND ( NOT EXISTS  (SELECT A.ID_TRANS FROM CBTES_APLICA A WHERE C.ID_TRANS = A.ID_TRANS)
		OR 	(SELECT MAX(p.fecha)
					 FROM cbtes_aplica a
					 JOIN cbtes p ON p.Id_Trans = A.ID_TRANS_D AND p.id_estado_cbte not in (0,3)
					 JOIN Cbtes_Tipos tp ON p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte and (tp.Compromete_Recibos in (1,-1) 
						OR ( tp.Compromete_Factura in (-1)   AND P.Id_Cond_Pago <> 1)
						)
					 WHERE  A.ID_TRANS = C.Id_Trans ) >= @pFecha )
		
		
--paso 3 REC

UNION ALL

SELECT  K.Id_Cliente_Ref AS Id_Cliente
		,C.ID_TIPO_CBTE
		,C.COMPROBANTE_NRO
		,C.FECHA,(C.IMP_TOTAL* -1) as IMP_TOTAL
		,(SELECT ISNULL(SUM(A.IMPORTE),0) FROM CBTES_APLICA A, CBTES K1 WHERE C.ID_TRANS = A.ID_TRANS_D AND K1.FECHA < @pFecha
			  AND A.ID_TRANS = K1.ID_TRANS AND K1.ID_ESTADO_CBTE NOT IN (0,3)  and a.id_trans <> 0
			  AND ISNULL((SELECT COUNT(*) FROM CBTES_APLICA CA WHERE C.ID_TRANS = CA.ID_TRANS_D),0) > = 1 
			  )  as Imp_Aplicado
		,(SELECT ISNULL(SUM(A.IMPORTE),0) FROM CBTES_APLICA A, CBTES K WHERE C.ID_TRANS = A.ID_TRANS AND K.FECHA < @pFecha
			  AND A.ID_TRANS_D = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3) )  as Imp_Aplicado2
		,C.SALDO
		,C.ID_TRANS
		,-1 AS SIGNO
	FROM CBTES C
	 JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.ID_TIPO_CBTE AND T.Compromete_Recibos IN (1,-1)
	 JOIN #Unid_Negocios U ON  U.Id_Unid_Negocio = T.Id_Unid_Negocio
	 JOIN Clientes O ON C.Id_Cliente = O.ID_Cliente
	, #Clientes K  
	WHERE  CASE ISNULL(O.Id_Cliente_Ref,0) 
								WHEN 0 THEN O.Id_Cliente
								ELSE O.Id_Cliente_Ref
								END =K.Id_Cliente_Ref
		AND C.Id_Estado_Cbte NOT IN (0,3)
		AND C.Id_Cliente > 1
		AND C.Fecha >'20190630' /*Fecha de Corte anterior 25/02/2025*/
		AND C.FECHA < @pFecha
		AND (((SELECT ISNULL(MAX(A.ID_TRANS),0) FROM CBTES_APLICA A , CBTES K WHERE C.ID_TRANS = A.Id_Trans_D
			 AND A.ID_TRANS = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3)
			 AND K.FECHA < @pFecha
			 ) = 0)
		   OR (SELECT ISNULL(SUM(A.IMPORTE),0) FROM CBTES_APLICA A, CBTES K WHERE C.ID_TRANS = A.Id_Trans_D
			  AND A.ID_TRANS = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3)	AND A.ID_TRANS <> 0
			  AND K.FECHA < @pFecha
			  ) <> ABS(C.IMP_TOTAL) )
		AND (SELECT ISNULL(ABS(SUM(A.IMPORTE)),0)  FROM CBTES_APLICA A, CBTES K WHERE C.Id_Trans = A.Id_Trans
			  AND A.ID_TRANS_D = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3)
			  AND K.FECHA < @pFecha
			  ) <> ABS(C.IMP_TOTAL) 


UPDATE #DEUDA SET Imp_Aplicado = abs(IMP_TOTAL), Saldo = 0  FROM #DEUDA WHERE  ABS(Imp_Aplicado) > abs(IMP_TOTAL)

/*Se agrega para determinar de quien es la UCP a Fecha 10/10/2024*/
CREATE TABLE #UCP (Id_Cliente INT, UCP_A_Fecha DATE)

--AGREGO Ucp A FECHA DEL SOCIO TITULAR O INDIVIDUAL		
IF @pInc_UCP_a_Fecha = 1
BEGIN
	DECLARE @Fam_CuotasSoc INT
	SET @Fam_CuotasSoc = CONVERT(INT,dbo.CF_xParam('Fam_CuotasSoc'))

	INSERT INTO #UCP
	SELECT I.Id_Cliente,CONVERT(DATE,MAX(I.Fecha_qa) ) AS UCP_A_Fecha
		FROM Cbtes_Items I
		    JOIN  Productos P ON P.Id_Producto = I.Id_Producto AND P.Id_Familia = @Fam_CuotasSoc
			JOIN  Cbtes C ON C.Id_Trans = I.Id_Trans AND C.Id_Estado_Cbte IN (1,2,4)
				LEFT JOIN Cbtes_Aplica A ON A.Id_Trans = C.Id_Trans
					LEFT JOIN Cbtes R ON R.Id_Trans = A.Id_Trans_D AND ( R.Id_Estado_Cbte IN (1,2,4) )
					LEFT JOIN Cbtes_Tipos TR ON TR.Id_Tipo_Cbte = R.Id_Tipo_Cbte AND ( TR.Compromete_Recibos  = 1 OR TR.Compromete_Factura = -1)
			JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte AND T.Compromete_Factura = 1
			, #DEUDA D
		WHERE I.Id_Cliente = D.Id_Cliente
		AND C.Fecha <= @pFechaHasta + 1
		AND R.Fecha < @pFechaHasta + 1
		GROUP BY I.Id_Cliente

END

--SELECT * FROM #DEUDA
--SELECT * FROM #UCP
	  
IF @pCriterio = 'P'
BEGIN
		SELECT	D.Id_Cliente
				,K.Razon_Social
				,K.Id_Cliente_Externo
				,K.Id_Tipo_Cli
				,TC.Descripcion as Categoria
				,CONVERT(DATE,D.Fecha) AS Fecha
				,CONVERT(DATE,C.Fecha_Venc) AS Fecha_Venc
				,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion
				,C.Id_Moneda AS Moneda
				,I.Id_Trans
				,I.Id_Producto
				,I.Descripcion_Producto
				,I.IMP_FINAL*D.SIGNO AS Imp_Prod
				,ISNULL(D.imp_totaL,0)* D.Signo AS Imp_Fac 
				,ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2) ,0) * D.Signo  AS Imp_Apli
				,ABS((ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO )/D.imp_total) AS Coef
				,(I.IMP_FINAL*D.SIGNO) * (ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO )/D.imp_total AS Saldo
				,I.Id_Cliente AS Id_Cliente_Item 
				,H.Razon_Social AS Razon_Social_Item
				,'19000101' as UCP_A_Fecha--,CONVERT(DATE,K.Ult_Cuota_Paga) as Ult_Cuota_Paga
		INTO #DET
		FROM #DEUDA D JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente
					  JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli	
			, CBTES C JOIN  CBTES_ITEMS I ON C.ID_TRANS = I.ID_TRANS
					  LEFT JOIN Clientes H ON I.Id_Cliente = H.Id_Cliente
					  JOIN Cbtes_Tipos T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
		WHERE   D.ID_TRANS = C.ID_TRANS 
				AND ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)* D.SIGNO  <> 0 
				AND T.Compromete_Factura IN (1,-1)
				AND D.imp_total <> 0

	ALTER TABLE #DET ALTER COLUMN Saldo DECIMAL(12,2)

		INSERT INTO #DET
			SELECT D.Id_Cliente
				 ,K.Razon_Social
				 ,K.Id_Cliente_Externo
				 ,K.Id_Tipo_Cli
				 ,TC.Descripcion as Categoria
				 ,CONVERT(DATE,D.Fecha) AS Fecha
				 ,CONVERT(DATE,C.Fecha_Venc) AS Fecha_Venc
				 ,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion
				 ,c.Id_Moneda AS Moneda
				 ,C.Id_Trans
				 , 'ACUENTA' AS ID_PRODUCTO
				 ,'PAGOS A CUENTA' AS Descripcion_Producto
				 , 0 AS IMP_PROD
				 , ISNULL(D.imp_totaL,0)* D.Signo AS IMP_FAC 
				 , ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2) ,0) * D.Signo  AS IMP_APLI
				 , ABS((ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO )/D.imp_total) AS COEF
				 ,0 AS SALDO 
				 ,0 AS Id_Cliente_Item
				 ,'' AS Razon_Social_Item
				 ,'19000101' as UCP_A_Fecha --,CONVERT(DATE,K.Ult_Cuota_Paga) as Ult_Cuota_Paga
				 FROM #DEUDA D JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente
							   JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli	
					, CBTES C JOIN Cbtes_Tipos T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
			   WHERE   D.ID_TRANS = C.ID_TRANS AND ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO  <> 0 
			   AND T.Compromete_Recibos IN (1,-1)
			   AND D.imp_total <> 0

		UPDATE  #DET SET IMP_PROD = (IMP_FAC*COEF)*-1, SALDO  = (IMP_FAC*COEF)*-1 
				 WHERE IMP_PROD = 0    AND IMP_FAC >= ABS(IMP_APLI)  AND ID_PRODUCTO ='ACUENTA'

		UPDATE  #DET SET IMP_PROD = (IMP_FAC*COEF), SALDO  = (IMP_FAC*COEF) 
				 WHERE IMP_PROD = 0  AND IMP_FAC < ABS(IMP_APLI)  AND ID_PRODUCTO ='ACUENTA'
		
		--SELECT * FROM #DET
		
		INSERT INTO #UCP
		SELECT I.Id_Cliente,CONVERT(DATE,MAX(I.Fecha_qa) ) AS UCP_A_Fecha
		FROM Cbtes_Items I
		    JOIN  Productos P ON P.Id_Producto = I.Id_Producto AND P.Id_Familia = @Fam_CuotasSoc
			JOIN  Cbtes C ON C.Id_Trans = I.Id_Trans AND C.Id_Estado_Cbte IN (1,2,4)
				LEFT JOIN Cbtes_Aplica A ON A.Id_Trans = C.Id_Trans
					LEFT JOIN Cbtes R ON R.Id_Trans = A.Id_Trans_D AND ( R.Id_Estado_Cbte IN (1,2,4) )
					LEFT JOIN Cbtes_Tipos TR ON TR.Id_Tipo_Cbte = R.Id_Tipo_Cbte AND ( TR.Compromete_Recibos  = 1 OR TR.Compromete_Factura = -1)
			JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte AND T.Compromete_Factura = 1
			, #DET D
					LEFT JOIN Clientes CL ON CL.Id_Cliente=D.Id_Cliente_Item AND CL.Activo=1 AND CL.Id_Cliente_Ref <> 0
		WHERE I.Id_Cliente = D.Id_Cliente_Item
		AND C.Fecha <= @pFechaHasta + 1
		AND R.Fecha < @pFechaHasta + 1
		GROUP BY I.Id_Cliente
		
       --select * From #UCP	
	
		--SELECT DISTINCT D.Id_Cliente,	
		--		D.Razon_Social,
		--		D.Id_Cliente_Externo,
		--		CL.Id_Tipo_Cli,
		--		CT. Descripcion  as Categoria,
		--		ISNULL(U.UCP_A_Fecha,'19000101')  as UCP_A_Fecha,
		--		D.Fecha,
		--		D.Fecha_Venc,
		--		D.Descripcion,
		--		D.Moneda,
		--		D.Id_Trans,
		--		D.Id_Producto,
		--		D.Descripcion_Producto,
		--		ISNULL(F.Descripcion,'Sin Familia') as Familia,
		--		D.Imp_Prod,
		--		D.Imp_Fac,
		--		D.Imp_Apli,
		--		D.Coef,
		--		D.Saldo,
		--		D.Id_Cliente_Item,
		--		D.Razon_Social_Item,
		--		CLI.Id_Tipo_Cli AS Id_Tipo_Cli_Items,
		--		CTI.Descripcion AS Categoria_Items,				
		--		ISNULL(UI.UCP_A_Fecha,'19000101')  as UCP_A_Fecha_Items,
		--		CAST(@pFechaHasta AS DATE) AS Fecha_Corte
		--		FROM #DET D 
		--					LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente
		--					LEFT JOIN Productos P ON D.Id_Producto = P.Id_Producto
		--					LEFT JOIN Prod_Familias F ON P.Id_Familia = F.Id_Familia
		--					LEFT JOIN Clientes CL ON D.Id_Cliente=CL.Id_Cliente
		--					LEFT JOIN Clientes_Tipos CT ON CL.Id_Tipo_Cli = CT.Id_Tipo_Cli	
		--					LEFT JOIN Clientes CLI ON D.Id_Cliente_Item=CLI.Id_Cliente
		--					LEFT JOIN Clientes_Tipos CTI ON CLI.Id_Tipo_Cli = CTI.Id_Tipo_Cli
		--					LEFT JOIN #UCP UI ON UI.Id_Cliente = D.Id_Cliente_Item		
		--		ORDER BY Razon_Social,Descripcion_Producto ,Fecha
		
		/**/
		;WITH DEUDA_AGRUPADA AS (
			SELECT 
				D.Id_Cliente,
				SUM(D.Saldo) AS Deuda_Total,
				MIN(D.Fecha_Venc) AS Primer_Vencimiento,
				MAX(D.Fecha_Venc) AS Ultimo_Vencimiento,
				COUNT(*) AS Cant_Conceptos
			FROM #DET D
			WHERE D.Saldo <> 0
			GROUP BY D.Id_Cliente
		),
		INTEGRANTE_TOP AS (
			SELECT 
				D.Id_Cliente,
				D.Id_Cliente_Item,
				SUM(D.Saldo) AS Deuda_Integrante,
				ROW_NUMBER() OVER (PARTITION BY D.Id_Cliente ORDER BY SUM(D.Saldo) DESC) AS RN
			FROM #DET D
			WHERE D.Saldo <> 0
			  AND D.Id_Cliente_Item <> 0
			GROUP BY D.Id_Cliente, D.Id_Cliente_Item
		)
		SELECT 
			C.Id_Cliente,
			C.Razon_Social,
			C.Id_Cliente_Externo,
			C.Id_Tipo_Cli,
			CT.Descripcion AS Categoria,

			--  DEUDA
			DA.Deuda_Total,

			-- PERIODO
			DA.Primer_Vencimiento,
			DA.Ultimo_Vencimiento,

			-- UCP TITULAR
			ISNULL(U.UCP_A_Fecha,'19000101') AS UCP_Titular,

			--  INTEGRANTE QUE MÁS DEBE
			IT.Id_Cliente_Item AS Id_Integrante_Deudor,
			CI.Razon_Social AS Nombre_Integrante,

			--  UCP DEL INTEGRANTE DEUDOR
			ISNULL(UI.UCP_A_Fecha,'19000101') AS UCP_Integrante,

			--  INFO EXTRA
			DA.Cant_Conceptos,
			CAST(@pFechaHasta AS DATE) AS Fecha_Corte

		FROM DEUDA_AGRUPADA DA

		JOIN Clientes C ON C.Id_Cliente = DA.Id_Cliente
		LEFT JOIN Clientes_Tipos CT ON C.Id_Tipo_Cli = CT.Id_Tipo_Cli

		--  UCP TITULAR
		LEFT JOIN #UCP U ON U.Id_Cliente = C.Id_Cliente

		--  INTEGRANTE MÁS DEUDOR
		LEFT JOIN INTEGRANTE_TOP IT 
			ON IT.Id_Cliente = DA.Id_Cliente 
		   AND IT.RN = 1

		LEFT JOIN Clientes CI ON CI.Id_Cliente = IT.Id_Cliente_Item

		--  UCP INTEGRANTE
		LEFT JOIN #UCP UI ON UI.Id_Cliente = IT.Id_Cliente_Item

		ORDER BY C.Razon_Social
		
		
			
		 DROP TABLE #DET
	 END

DROP TABLE #UCP
DROP TABLE #DEUDA
DROP TABLE #Clientes
DROP TABLE #Unid_Negocios
 


