CREATE PROCEDURE [dbo].[SPJ_Clientes_Deuda_a_Fecha_OPT]
    @pJsonRecibido VARCHAR(8000)
AS
SET NOCOUNT ON;

DECLARE  
    @pFechaHasta DATETIME = ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE()),
    @pId_Unid_Negocio VARCHAR(10) = ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),''),
    @pId_Cliente INT = ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')),0),
    @pClientes_activos TINYINT = ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Clientes_activos')),0),
    @pFecha DATETIME,
    @Fam_CuotasSoc INT;

SET @pFecha = DATEADD(DAY,1,@pFechaHasta);
SET @Fam_CuotasSoc = CONVERT(INT,dbo.CF_xParam('Fam_CuotasSoc'));

--  CLIENTES
WITH ClientesBase AS (
    SELECT 
        Id_Cliente,
        Id_Cliente_Ref = ISNULL(Id_Cliente_Ref, Id_Cliente),
        Razon_Social,
        Id_Cliente_Externo,
        Id_Tipo_Cli
    FROM Clientes
    WHERE 
        (@pId_Cliente <> 0 AND Id_Cliente = @pId_Cliente)
        OR (
            @pId_Cliente = 0 
            AND (
                @pClientes_activos = 0
                OR (
                    Id_Tipo_Cli NOT IN (10,1005,1011,1015,1018,1019,1101,1102,1103,1105,1113,1114,1127,1128,1129,1132,1133,1134)
                    AND (Activo = 1 OR (Activo = 0 AND Fecha_Baja > @pFecha))
                )
            )
        )
),

Unidades AS (
    SELECT Id_Unid_Negocio
    FROM Empresas_Unid_Negocios
    WHERE (@pId_Unid_Negocio = '' OR Id_Unid_Negocio = @pId_Unid_Negocio)
),

Aplicaciones AS (
    SELECT ID_TRANS, SUM(Importe) AS Imp_Aplicado
    FROM Cbtes_Aplica
    GROUP BY ID_TRANS
),

Aplicaciones_D AS (
    SELECT ID_TRANS_D, SUM(Importe) AS Imp_Aplicado_D
    FROM Cbtes_Aplica
    GROUP BY ID_TRANS_D
),

--  DEUDA BASE
DEUDA AS (
    SELECT 
        C.Id_Trans,
        CB.Id_Cliente_Ref AS Id_Cliente,
        C.Fecha,
        C.Id_Moneda,
        I.Id_Producto,
        I.Descripcion_Producto,
        I.Imp_Final,
        I.Id_Cliente AS Id_Cliente_Item,
        ISNULL(A.Imp_Aplicado,0) AS Imp_Aplicado,
        ISNULL(AD.Imp_Aplicado_D,0) AS Imp_Aplicado2,
        (I.Imp_Final 
            * (C.Imp_Total - (ISNULL(A.Imp_Aplicado,0)+ABS(ISNULL(AD.Imp_Aplicado_D,0))))
            / NULLIF(C.Imp_Total,0)
        ) AS Saldo
    FROM CBTES C
    INNER JOIN Cbtes_Tipos T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
    INNER JOIN Unidades U ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
    INNER JOIN ClientesBase CB ON CB.Id_Cliente = C.Id_Cliente
    INNER JOIN Cbtes_Items I ON I.Id_Trans = C.Id_Trans
    LEFT JOIN Aplicaciones A ON A.ID_TRANS = C.Id_Trans
    LEFT JOIN Aplicaciones_D AD ON AD.ID_TRANS_D = C.Id_Trans
    WHERE 
        C.Id_Estado_Cbte NOT IN (0,3)
        AND C.Id_Cliente > 1
        AND C.Fecha > '20190630'
        AND C.Fecha < @pFecha
        AND C.Id_Cond_Pago <> 1
        AND T.Compromete_Factura IN (1,-1)
),

-- UCP A FECHA (CORRECTA)
UCP AS (
    SELECT 
        I.Id_Cliente,
        MAX(I.Fecha_qa) AS UCP_A_Fecha
    FROM Cbtes_Items I
    INNER JOIN Productos P 
        ON P.Id_Producto = I.Id_Producto
        AND P.Id_Familia = @Fam_CuotasSoc
    INNER JOIN Cbtes C 
        ON C.Id_Trans = I.Id_Trans
        AND C.Id_Estado_Cbte IN (1,2,4)
    INNER JOIN Cbtes_Aplica A 
        ON A.Id_Trans = C.Id_Trans
    INNER JOIN Cbtes R 
        ON R.Id_Trans = A.Id_Trans_D
        AND R.Fecha < @pFecha
        AND R.Id_Estado_Cbte IN (1,2,4)
    INNER JOIN Cbtes_Tipos TR 
        ON TR.Id_Tipo_Cbte = R.Id_Tipo_Cbte
        AND (TR.Compromete_Recibos = 1 OR TR.Compromete_Factura = -1)
    WHERE C.Fecha < @pFecha
    GROUP BY I.Id_Cliente
)

--  RESULTADO FINAL (UNA FILA POR INTEGRANTE)
SELECT  
    D.Id_Cliente,
    C.Razon_Social,
    C.Id_Cliente_Externo,
    C.Id_Tipo_Cli,
    CT.Descripcion AS Categoria,

    ISNULL(U.UCP_A_Fecha,'19000101') AS UCP_A_Fecha,

    -- 👇 INTEGRANTE
    D.Id_Cliente_Item,
    CI.Razon_Social AS Razon_Social_Item,
    CI.Id_Tipo_Cli AS Id_Tipo_Cli_Items,
    CTI.Descripcion AS Categoria_Items,
    ISNULL(UI.UCP_A_Fecha,'19000101') AS UCP_A_Fecha_Items,

    -- CONCEPTOS
    STUFF((
    SELECT DISTINCT ', ' + D2.Descripcion_Producto
    FROM DEUDA D2
    WHERE 
        D2.Id_Cliente = D.Id_Cliente
        AND D2.Id_Cliente_Item = D.Id_Cliente_Item
    FOR XML PATH(''), TYPE
	).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS Deuda_Conceptos,

    -- DEUDA TOTAL
    SUM(D.Saldo) AS Deuda_Total,

    CAST(@pFechaHasta AS DATE) AS Fecha_Corte

FROM DEUDA D
INNER JOIN Clientes C ON C.Id_Cliente = D.Id_Cliente
LEFT JOIN Clientes_Tipos CT ON C.Id_Tipo_Cli = CT.Id_Tipo_Cli

LEFT JOIN Clientes CI ON CI.Id_Cliente = D.Id_Cliente_Item
LEFT JOIN Clientes_Tipos CTI ON CI.Id_Tipo_Cli = CTI.Id_Tipo_Cli

LEFT JOIN UCP U ON U.Id_Cliente = D.Id_Cliente
LEFT JOIN UCP UI ON UI.Id_Cliente = D.Id_Cliente_Item

GROUP BY  
    D.Id_Cliente,
    C.Razon_Social,
    C.Id_Cliente_Externo,
    C.Id_Tipo_Cli,
    CT.Descripcion,
    U.UCP_A_Fecha,

    D.Id_Cliente_Item,
    CI.Razon_Social,
    CI.Id_Tipo_Cli,
    CTI.Descripcion,
    UI.UCP_A_Fecha

HAVING SUM(D.Saldo) <> 0

ORDER BY 
    C.Razon_Social,
    CI.Razon_Social

OPTION (RECOMPILE);
/*
EXEC SPJ_Clientes_Deuda_a_Fecha_OPT '{"FechaHasta":"20251231","Id_Unid_Negocio":"","Clientes_activos":"1","Id_Cliente":""}'
*/
GO

CREATE PROCEDURE [dbo].[SPJ_Colonia] @pJson VARCHAR(8000)
AS
/*Variables recibidas por parßmetro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pTipo_Operacion		CHAR(3)
DECLARE @pRealizado				VARCHAR(10)
DECLARE @pCant_Integantes		INT
DECLARE @pId_Cliente			INT
DECLARE @pId_Contrato           INT

SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pTipo_Operacion		= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Tipo_Operacion')),'')
SET @pRealizado				= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Realizado')),'')
SET @pCant_Integantes		= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Cant_Integrantes')),0)
SET @pId_Contrato			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Contrato')),0)
SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')),0)
/*FIN Variables recibidas por parßmetro a traves del JSON*/


DECLARE @Id_Cliente				INT
DECLARE	@Razon_Social			VARCHAR(100)
DECLARE	@Id_Tipo_Cli			INT
DECLARE	@Categoria				VARCHAR(100)
DECLARE @Json_Rta				NVARCHAR(MAX)
DECLARE @Json					NVARCHAR(MAX)
DECLARE @Contador				INT
DECLARE @Variable_Id_Cliente	VARCHAR(20)
DECLARE @Variable_Id_Tipo_Cli	VARCHAR(20)
DECLARE @Variable_Razon_Social	VARCHAR(30)
DECLARE @Variable_Categoria		VARCHAR(30)
DECLARE @Variable_Fecha_Hasta	VARCHAR(30)
DECLARE @Variable_Cant_Dias		VARCHAR(30)
DECLARE @Variable_Mes			VARCHAR(30)
DECLARE @Fecha_Hasta			DATETIME
DECLARE @Variable_Estado		VARCHAR(20)
DECLARE @Variable_Fecha_Desde	VARCHAR(30)
DECLARE @Fecha_Desde			DATETIME
DECLARE @Estado					INT
DECLARE @Fecha_Nac				DATETIME
DECLARE @Precio					DECIMAL(12,2)
DECLARE @Variable_Precio		VARCHAR(30)
DECLARE @pId_Producto			VARCHAR(14)
DECLARE @Id_Producto			VARCHAR(14)
DECLARE @Variable_Producto		VARCHAR(30)
DECLARE @Variable_Descrip		VARCHAR(30)
DECLARE @Variable_Id_Producto	VARCHAR(30)
DECLARE	@pIds_Clientes			NVARCHAR(MAX)
DECLARE @SqlStr					NVARCHAR(MAX)
DECLARE @Importe_Total			DECIMAL(12,2)
DECLARE @Deuda					INT
DECLARE @Cantidad_PreInfantil	INT
DECLARE @Dias					INT
DECLARE @Mes					VARCHAR(10)

DECLARE @Observacion			VARCHAR(200)


SET @Cantidad_PreInfantil=0
SET @Importe_Total=0
	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Entro Stored Procedure: [SPJ_Colonia]'+' Tipo de operacion'+ @pTipo_Operacion
	END

-- Cargo los clientes 

CREATE TABLE #Clientes_Pasaportes 
			(Id_Cliente		INT,
			Id_Tipo_Cli		INT,
			Razon_Social	VARCHAR(100),
			Categoria		VARCHAR(100),
			Fecha_Nac		DATETIME,
			Precio			DECIMAL(12,2),
			Estado			INT)

	SET @SqlStr =	'INSERT INTO #Clientes_Pasaportes (Id_Cliente, Id_Tipo_Cli, Razon_Social, Categoria, Fecha_Nac)'
	
	SET @SqlStr =	RTRIM(LTRIM(@SqlStr))											+ CHAR(13) + 
					'SELECT c.Id_Cliente,C.Id_Tipo_Cli, LTRIM(RTRIM(ISNULL(Razon_Social, ''''))),ct.Descripcion,Fecha_Nac
					FROM clientes c	, clientes_tipos ct
					WHERE c.Id_Cliente<>0
					and ct.id_tipo_cli=c.id_tipo_cli
					AND c.Activo=1'
	IF (@pTipo_Operacion='EA')
		BEGIN
			SET @SqlStr =RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 'AND (c.id_cliente =  dbo.CF_Cli_Id_Cliente_Ref( ' + CONVERT(VARCHAR(10),@pId_Cliente) + '     )
						OR c.id_cliente IN  (select id_Cliente from Clientes where id_cliente_ref = dbo.CF_Cli_Id_Cliente_Ref( ' + CONVERT(VARCHAR(10),@pId_Cliente) + '  ) ))'
	END
	
	IF (@pTipo_Operacion='PR' OR @pTipo_Operacion='GR')
	BEGIN

		SET @Contador=0
		SET @pIds_Clientes =''
		WHILE (@Contador<=@pCant_Integantes)
		BEGIN
		SET @Contador=@Contador+1
			SET @Variable_Id_Cliente	= 'Id_Cliente_' + CONVERT(VARCHAR(20), @Contador)	
			SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,@Variable_Id_Cliente)),0)
			IF (@pIds_Clientes ='')
			BEGIN
				SET @pIds_Clientes=CONVERT(VARCHAR(10),@pId_Cliente) 
			END
			ELSE 
			BEGIN
				SET @pIds_Clientes=@pIds_Clientes+',' +CONVERT(VARCHAR(10),@pId_Cliente)
			END
		END 
		--print @pIds_Clientes
		SET @SqlStr =RTRIM(LTRIM(@SqlStr)) + ' AND c.id_cliente  in (' + @pIds_Clientes + ')  '
	END

	IF(@pModoDebug = 1)
		BEGIN
			PRINT '@SqlStr: ' + @SqlStr
		END
	--PRINT '@SqlStr: ' + @SqlStr		
	EXECUTE sp_executesql @SqlStr

	--VALIDACIONES

	SET @Json_Rta ='{'

	SET @Contador = 0
	SET @Importe_Total= 0
	DECLARE curPasaporte CURSOR FOR
	
	SELECT ISNULL(Id_Cliente,0), ISNULL(Id_Tipo_Cli,0), ISNULL(Razon_Social,''), ISNULL(Categoria,''), ISNULL(Fecha_Nac,'19900101')
	FROM #Clientes_Pasaportes
	
	OPEN curPasaporte
	FETCH NEXT FROM curPasaporte INTO  @Id_Cliente,@Id_Tipo_Cli, @Razon_Social, @Categoria, @Fecha_Nac
	WHILE @@FETCH_STATUS = 0
	BEGIN
	
		SET @Contador = @Contador + 1
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Contador es:'+ CONVERT(CHAR(2),@Contador)
			PRINT 'La Fecha de finalizacion del contrato es :'+ CONVERT(VARCHAR(20),@Fecha_Hasta)
		END
		
		SET @Variable_Id_Cliente	= 'Id_Cliente_' + CONVERT(VARCHAR(20), @Contador)
		SET @Variable_Id_Tipo_Cli	= 'Id_Tipo_Cli_' + CONVERT(VARCHAR(20), @Contador)
		SET @Variable_Razon_Social	= 'Razon_Social_' + CONVERT(VARCHAR(20), @Contador)
		SET @Variable_Categoria		= 'Categoria_' + CONVERT(VARCHAR(20), @Contador)
		
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'Socio: '+ @Razon_Social
		END
	SET @Json_Rta = @Json_Rta +	dbo.CF_Json_ParsearVariable(@Variable_Id_Cliente, @Id_Cliente, 'INT') + ',' +
									dbo.CF_Json_ParsearVariable(@Variable_Id_Tipo_Cli, @Id_Tipo_Cli, 'INT') + ',' +
									dbo.CF_Json_ParsearVariable(@Variable_Razon_Social, @Razon_Social, 'VARCHAR(100)') + ',' +
									dbo.CF_Json_ParsearVariable(@Variable_Categoria, @Categoria, 'VARCHAR(100)') + ',' 

	IF (@pTipo_Operacion='PR' OR @pTipo_Operacion='GR')
	BEGIN
	
		SET @Variable_Precio		= 'Precio_' + CONVERT(VARCHAR(20), @Contador)
		SET @Variable_Producto		= 'Producto_' + CONVERT(VARCHAR(20), @Contador)
		SET @Variable_Id_Producto	= 'Id_Producto_' + CONVERT(VARCHAR(20), @Contador)	
		SET @Variable_Fecha_Desde	= 'Fecha_Desde_' + CONVERT(VARCHAR(20), @Contador)	
		SET @Variable_Fecha_Hasta	= 'Fecha_Hasta_' + CONVERT(VARCHAR(20), @Contador)	
		SET @Variable_Cant_Dias		= 'Cant_Dias_' + CONVERT(VARCHAR(20), @Contador)	
		SET @Variable_Mes			= 'Mes_' + CONVERT(VARCHAR(20), @Contador)	
		
		SET @pId_Producto			= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,@Variable_Id_Producto)),'')
	
		IF (@pId_Producto <>'')
		BEGIN
		
			SET @Precio =ISNULL((SELECT ISNULL(Precio,0) FROM Prod_Listas_Precios_Items WHERE Id_Producto=@pId_Producto AND Id_Lista_Precio=213),0)	
		END
	
		
		IF (@Id_Tipo_Cli in (1000,1122,1115,1106))
		BEGIN
			SET @Cantidad_PreInfantil=@Cantidad_PreInfantil+1
			
			IF(@Cantidad_PreInfantil>1)
			BEGIN
				SET @Precio=(@Precio*0.85)
			END
			
		END
	

		
	--	SET @Precio=5
		SET @Importe_Total= @Importe_Total + @Precio
		IF(@pModoDebug = 1)
		BEGIN
			PRINT 'El Precio es  : ' + CONVERT(VARCHAR(100),ISNULL(@Precio,0))
		END
		
		SELECT @Variable_Descrip= Descripcion_Detallada,
				@Fecha_Desde= ISNULL(Flag_Periodo_Desde,GETDATE()),
				@Dias= ISNULL(Flag_Periodo_Cant,0),
				@Fecha_Hasta= ISNULL(Flag_Periodo_Hasta,GETDATE())
		FROM Productos WHERE Id_Producto=@pId_Producto
		
		SET @Mes= ISNULL((SELECT Valor_String FROM Productos_Xcampos 
							WHERE Id_Producto=@pId_Producto AND Id_Campo=17),'')
		
		SET @Json_Rta = @Json_Rta +	dbo.CF_Json_ParsearVariable(@Variable_Id_Producto, @pId_Producto, 'VARCHAR(14)') + ',' 
		SET @Json_Rta = @Json_Rta +	dbo.CF_Json_ParsearVariable(@Variable_Producto, @Variable_Descrip, 'VARCHAR') + ','  
		SET @Json_Rta = @Json_Rta +	dbo.CF_Json_ParsearVariable(@Variable_Fecha_Desde, @Fecha_Desde, 'DATETIME') + ','  
		SET @Json_Rta = @Json_Rta +	dbo.CF_Json_ParsearVariable(@Variable_Fecha_Hasta, @Fecha_Hasta, 'DATETIME') + ','  
		SET @Json_Rta = @Json_Rta +	dbo.CF_Json_ParsearVariable(@Variable_Cant_Dias, @Dias, 'INT') + ','  
		SET @Json_Rta = @Json_Rta +	dbo.CF_Json_ParsearVariable(@Variable_Mes, @Mes, 'VARCHAR(10)') + ',' 
		SET @Json_Rta = @Json_Rta +	dbo.CF_Json_ParsearVariable(@Variable_Precio, @Precio, 'DECIMAL(12,2)') + ',' 
		SET @Json_Rta = @Json_Rta +	dbo.CF_Json_ParsearVariable('Precio_Total', @Importe_Total, 'DECIMAL(12,2)') + ',' 
		
	END





		
	FETCH NEXT FROM curPasaporte INTO   @Id_Cliente,@Id_Tipo_Cli, @Razon_Social, @Categoria, @Fecha_Nac
	END
	CLOSE curPasaporte
	DEALLOCATE curPasaporte

	SET @Json_Rta= @Json_Rta +	dbo.CF_Json_ParsearVariable('Contador',@Contador, 'INT') + '}'

	SELECT	 @Json_Rta				AS Datos

	DROP TABLE #Clientes_Pasaportes

/*
