EXEC SPJ_Pasaporte '{"ModoDebug":"1","Tipo_Operacion":"PR","Id_Cliente_1":"66744","Id_Contrato_1":"601194","Id_Cliente_2":"66746","Id_Contrato_2":"601195","Cant_Integrantes":2}'

*/
GO

CREATE PROCEDURE [dbo].[SPJ_Comprobacion_Socios_BioStar] @pJson VARCHAR(8000)
AS 

/*
 * LOG VERSIONES:
 * 16/07/2025: Se crea el Stored
 * 17/07/2025: Se agrega la fecha de proceso de la lista blanca
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Controlador		INT
DECLARE @pGenerar_Novedad		TINYINT

SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Controlador			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Controlador')), 0)
SET @pGenerar_Novedad			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Generar_Novedad')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Id_Controlador_Suprema INT = 2 -- Cuota Social
DECLARE @json					NVARCHAR(MAX)
DECLARE @Id_Cliente				INT
/*FIN Variables Locales*/

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a Stored Procedure: SPJ_Comprobacion_Socios_BioStar'
	PRINT 'Parametros:' + @pJson
END

IF(@pId_Controlador = 0)
BEGIN
	SET @pId_Controlador = 65 -- Control de CS
END

SET @Id_Controlador_Suprema = (SELECT Suprema_Grupo_id FROM CD_Controladores WHERE Id_Controlador = @pId_Controlador)

IF(@pModoDebug = 1)
BEGIN
	PRINT '@Id_Controlador_Suprema: ' + CAST(@Id_Controlador_Suprema AS VARCHAR)
END

-- Compruebo que el id de suprema exista
IF(@Id_Controlador_Suprema IS NULL OR @Id_Controlador_Suprema = 0)
BEGIN
	RETURN
END

-- Creo la tabla temporal con los socios de ese nivel de acceso
SELECT U.USRID AS Id_Cliente
	INTO #Suprema
	FROM [10.0.0.27].[BIOSTAR_AC].dbo.T_USR U
		, [10.0.0.27].[BIOSTAR_AC].dbo.T_ACSGRUSS G
		WHERE U.USRUID NOT IN (0,1,2) 
		AND U.DEL <> 'Y' 
		AND U.USRUID = G.USRUID
		AND G.ACSGRUID = @Id_Controlador_Suprema
		
-- Creo indice para tabla temporal
CREATE INDEX IXXXX_Suprema ON #Suprema (Id_Cliente)

CREATE TABLE #Socios (
	Id_Cliente INT,
	Doc_Nro BIGINT,
	Id_Cliente_Externo VARCHAR(14),
	Razon_Social VARCHAR(100),
	Fecha_Alta DATETIME,
	Ult_Cuota_Paga DATETIME,
	Habilitado_En VARCHAR(10),
	Mensaje VARCHAR(5000),
	Fecha_Lista_Blanca DATETIME,
	Id_Controlador_Suprema INT
)

CREATE TABLE #Socios2 (
	Id_Cliente INT,
	Doc_Nro BIGINT,
	Id_Cliente_Externo VARCHAR(14),
	Razon_Social VARCHAR(100),
	Fecha_Alta DATETIME,
	Ult_Cuota_Paga DATETIME,
	Habilitado_En VARCHAR(10),
	Mensaje VARCHAR(5000),
	Fecha_Lista_Blanca DATETIME,
	Id_Controlador_Suprema INT
)

-- Clientes en lista_blanca y no en #Suprema
INSERT INTO #Socios
SELECT L.Id_Cliente, C.Doc_Nro, C.Id_Cliente_Externo, C.Razon_Social, C.Fecha_Alta, C.Ult_Cuota_Paga, 'GEBA' AS Habilitado_En, L.Mensaje AS Mensaje, L.Fecha_Proceso AS Fecha_Lista_Blanca, Id_Grupo_Suprema
FROM CD_Lista_Blanca_Suprema L, Clientes C
WHERE L.Id_Cliente NOT IN (
    SELECT S.Id_Cliente FROM #Suprema S
) AND L.Id_Cliente = C.Id_Cliente
AND L.Id_Grupo_Suprema = @Id_Controlador_Suprema

UNION ALL

-- Clientes en #Suprema y no en lista_blanca
SELECT S.Id_Cliente, C.Doc_Nro, C.Id_Cliente_Externo, C.Razon_Social, C.Fecha_Alta, C.Ult_Cuota_Paga, 'SUPREMA' AS Habilitado_En, '' AS Mensaje, '' AS Fecha_Lista_Blanca, @Id_Controlador_Suprema AS Id_Grupo_Suprema 
FROM #Suprema S, Clientes C
WHERE S.Id_Cliente NOT IN (
    SELECT L.Id_Cliente FROM CD_Lista_Blanca_Suprema L
) AND S.Id_Cliente = C.Id_Cliente

DELETE S
FROM #Socios S
JOIN Clientes C ON S.Id_Cliente = C.Id_Cliente
WHERE C.doc_nro < 1000000
	OR NOT EXISTS (
		SELECT 1
		FROM Clientes_Fotos F
		WHERE F.Id_Cliente = C.Id_Cliente
		AND F.Nro = 1
	)

IF(@pGenerar_Novedad = 1)
BEGIN

	INSERT INTO CD_Clientes_Novedades (Id_Cliente, Fecha, Estado, Fecha_Simulacion)
	SELECT S.Id_Cliente, GETDATE(), 'P', NULL FROM #Socios S
	WHERE NOT EXISTS(
		SELECT 1 
		FROM CD_Clientes_Novedades N
		WHERE N.Id_Cliente = S.Id_Cliente
		AND N.Estado = 'P'
	)

	SELECT 1 AS Finalizado
END
ELSE
BEGIN

	-- Actualizo la lista blanca
	DECLARE cursor_socios CURSOR FOR
	SELECT Id_Cliente FROM #Socios

	OPEN cursor_socios
	FETCH NEXT FROM cursor_socios INTO @Id_Cliente
	WHILE @@FETCH_STATUS = 0
	BEGIN

		SET @json = '{"ModoDebug":1,"Id_Cliente":"' + CAST(@Id_Cliente AS NVARCHAR) + '","Id_Controlador":"' + CAST(@pId_Controlador AS NVARCHAR) + '"}'
		EXEC dbo.CPJU_Lista_Blanca_Suprema_Socios @json

		PRINT 'ENTRO'
		PRINT 'EXEC dbo.CPJU_Lista_Blanca_Suprema_Socios ''' + @json + ''''  

		FETCH NEXT FROM cursor_socios INTO @Id_Cliente
	END

	CLOSE cursor_socios
	DEALLOCATE cursor_socios

	INSERT INTO #Socios2
	SELECT L.Id_Cliente, C.Doc_Nro, C.Id_Cliente_Externo, C.Razon_Social, C.Fecha_Alta, C.Ult_Cuota_Paga, 'GEBA' AS Habilitado_En, L.Mensaje AS Mensaje, L.Fecha_Proceso AS Fecha_Lista_Blanca, Id_Grupo_Suprema
	FROM CD_Lista_Blanca_Suprema L, Clientes C
	WHERE L.Id_Cliente NOT IN (
		SELECT S.Id_Cliente FROM #Suprema S
	) AND L.Id_Cliente = C.Id_Cliente
	AND L.Id_Grupo_Suprema = @Id_Controlador_Suprema

	UNION ALL

	-- Clientes en #Suprema y no en lista_blanca
	SELECT S.Id_Cliente, C.Doc_Nro, C.Id_Cliente_Externo, C.Razon_Social, C.Fecha_Alta, C.Ult_Cuota_Paga, 'SUPREMA' AS Habilitado_En, '' AS Mensaje, '' AS Fecha_Lista_Blanca, @Id_Controlador_Suprema AS Id_Grupo_Suprema
	FROM #Suprema S, Clientes C
	WHERE S.Id_Cliente NOT IN (
		SELECT L.Id_Cliente FROM CD_Lista_Blanca_Suprema L
	) AND S.Id_Cliente = C.Id_Cliente


	SELECT 
		S.*,
		CASE 
			WHEN N.id_cliente IS NOT NULL THEN 1 
			ELSE 0 
		END AS Pendiente
		FROM #Socios2 S
		LEFT JOIN CD_Clientes_Novedades N ON N.Id_Cliente = S.Id_Cliente AND N.Estado = 'P'
END


DROP TABLE #Suprema
DROP TABLE #Socios
DROP TABLE #Socios2

/*

EXEC dbo.SPJ_Comprobacion_Socios_BioStar_t20250722 '{"ModoDebug":"1"}'

EXEC dbo.SPJ_Comprobacion_Socios_BioStar '{"ModoDebug":"1","Generar_Novedad":"1"}'

EXEC dbo.SPJ_Comprobacion_Socios_BioStar_t20250722 '{"ModoDebug":"1","Id_Controlador":"68"}'
EXEC SPJ_Comprobacion_Socios_BioStar_t20250722 '{"Id_Controlador":"65"}'

*/
