CREATE PROCEDURE SPJ_Deuda_Snapshot_Generar
    @pFechaHasta DATE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @pFecha DATETIME = DATEADD(DAY,1,@pFechaHasta)
    DECLARE @Fam_CuotasSoc INT = CONVERT(INT,dbo.CF_xParam('Fam_CuotasSoc'))

    --  BORRAR SNAPSHOT DEL DÍA (reproceso seguro)
   
		DELETE FROM Deuda_Clientes_Snapshot 
		WHERE Fecha_Corte = @pFechaHasta
	

    --  DEUDA BASE (usar tu CTE optimizado)
   ;WITH DEUDA AS (
    SELECT 
        --  TITULAR SIEMPRE DESDE CBTES
        C.Id_Cliente AS Id_Cliente,

        --  INTEGRANTE (si no hay, usar titular)
        ISNULL(I.Id_Cliente, C.Id_Cliente) AS Id_Cliente_Item,

        --  LIMPIEZA TEXTO
        REPLACE(REPLACE(REPLACE(REPLACE(
            I.Descripcion_Producto,
            CHAR(0), ''
        ), CHAR(31), ''), CHAR(30), ''), CHAR(29), '') 
        AS Descripcion_Producto,

        I.Fecha_qa,
        ISNULL(I.Imp_Final,0) AS Saldo
    FROM Cbtes_Items I
    JOIN Cbtes C ON C.Id_Trans = I.Id_Trans
    WHERE C.Fecha < @pFecha
),

    UCP AS (
        SELECT 
            I.Id_Cliente,
            MAX(I.Fecha_qa) AS UCP_A_Fecha
        FROM Cbtes_Items I
        JOIN Productos P ON P.Id_Producto = I.Id_Producto
        WHERE P.Id_Familia = @Fam_CuotasSoc
          AND I.Fecha_qa < @pFecha
        GROUP BY I.Id_Cliente
    )

    INSERT INTO Deuda_Clientes_Snapshot (
    Id_Cliente,
    Id_Cliente_Item,
    Fecha_Corte,
    Deuda_Total,
    Deuda_Conceptos,
    UCP_A_Fecha,
    UCP_A_Fecha_Item,
    Meses_Atraso,
    Deuda_Vencida
)
SELECT  
    D.Id_Cliente,
    D.Id_Cliente_Item,
    @pFechaHasta,

    SUM(D.Saldo),

    STUFF((
    SELECT DISTINCT ', ' + 
        (
            SELECT D2.Descripcion_Producto
            FOR XML PATH(''), TYPE
        ).value('.', 'NVARCHAR(MAX)')
    FROM DEUDA D2
    WHERE D2.Id_Cliente = D.Id_Cliente
    FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'),1,2,''),

    U.UCP_A_Fecha,
    U.UCP_A_Fecha,

    DATEDIFF(MONTH, U.UCP_A_Fecha, @pFechaHasta),

    SUM(CASE 
        WHEN D.Fecha_qa < DATEADD(MONTH,-1,@pFechaHasta) 
        THEN D.Saldo ELSE 0 
    END)
FROM DEUDA D
LEFT JOIN UCP U ON U.Id_Cliente = D.Id_Cliente
WHERE D.Id_Cliente IS NOT NULL
GROUP BY 
    D.Id_Cliente,
    D.Id_Cliente_Item,
    U.UCP_A_Fecha
END

/*
EXEC SPJ_Deuda_Snapshot_Generar '20251231'
*/
GO

