CREATE PROCEDURE [dbo].[SP_2] as

update Contratos 
set Fecha_Baja = GETDATE(),Id_Motivo_Est = 1,Activo = 0
where Activo = 1
and Fecha_Hasta < GETDATE()


select o.Id_Cliente,MAX(Fecha_Hasta) as hasta
into #tab
from Contratos o, Clientes c
where c.Id_Cliente = o.Id_Cliente
and o.Activo = 0
and not exists (select 1 from Contratos t 
                where t.Id_Cliente = o.Id_Cliente and t.Activo = 1)
                
group by o.Id_Cliente
                

update Clientes set Fecha_Baja = t.hasta, Activo = 0, Id_Motivo_Est = 1
from Clientes c, #tab t
where t.Id_Cliente = c.Id_Cliente

INSERT INTO Clientes_Hist
SELECT C2.Id_Cliente,
(SELECT MAX(ITEM) +1 FROM Clientes_Hist H2 WHERE H2.Id_Cliente = C2.Id_Cliente)
,C2.Fecha_Alta,C2.Id_Tipo_Cli,'',C2.Fecha_Alta,
C2.Id_Motivo_Est,C2.Fecha_Baja,-1,'','','',null,NULL
FROM Clientes C2, #tab t
WHERE T.Id_Cliente = C2.Id_Cliente

-----------------------------------------------

INSERT INTO Clientes_Hist
SELECT C2.Id_Cliente,
(SELECT MAX(ITEM) +1 FROM Clientes_Hist H2 WHERE H2.Id_Cliente = C2.Id_Cliente)
,C2.Fecha_Alta,C2.Id_Tipo_Cli,'',C2.Fecha_Alta,
C2.Id_Motivo_Est,GETDATE(),-1,'','','',null,NULL
FROM Clientes C2
where not exists (select 1 from Contratos o
where C2.Id_Cliente = o.Id_Cliente)
and C2.Id_Cliente not in( 1,3)

update Clientes set Fecha_Baja = GETDATE(), Activo = 0, Id_Motivo_Est = 3
from  Clientes c
where not exists (select 1 from Contratos o
where c.Id_Cliente = o.Id_Cliente)
