CREATE  PROCEDURE [dbo].[SP_AgregarContrato] @cli INT  ,@fecha_qa datetime,@id_Trans int,@item int
AS
begin

DECLARE @Existe INT
declare @id_producto varchar(14)
declare @id_contacto int
declare @fecha_hasta datetime



set @id_contacto = isnull((select max (id_contacto) + 1 from  CRM_Contactos ),0)
SET @Existe = (SELECT MAX(Id_Contrato)+1 FROM Contratos )

set @id_producto= (SELECT ci.id_producto FROM cbtes_items ci inner join cbtes c on ci.id_Trans = c.id_trans
                        inner join cbtes_tipos ct on c.id_tipo_cbte = ct.id_tipo_cbte   
                          WHERE ci.Id_Cliente = @Cli and ct.compromete_factura = 1 and ci.Id_Trans = @id_Trans and ci.Item = @item)
print @Cli                
print '@id_producto'                         
print @id_producto
print @fecha_qa
if  (@id_producto not in ('DIA','MES','SEM','ANUAL','TRI','PRUEBA') )
    return


    set @fecha_hasta =
             case       when @id_producto = 'DIA' THEN  @fecha_qa 
                        when @id_producto = 'PRUEBA' THEN  dateadd(DAY,6,@fecha_qa) 
                        when @id_producto = 'MES' THEN  dateadd(DAY,30,@fecha_qa) 
                        when @id_producto = 'SEM' THEN  dateadd(MONTH,6,@fecha_qa)
                        when @id_producto = 'ANUAL' THEN  dateadd(YEAR,1,@fecha_qa)
                        when @id_producto = 'TRI' THEN  dateadd(MONTH,3,@fecha_qa)
    END

print @fecha_hasta
update Contratos set fecha_hasta = @fecha_hasta where id_contrato = @Existe -- dejo bien la fecha hasta

 IF  @id_producto <>  'DIA'
 BEGIN  
	 IF @id_producto = 'PRUEBA'
		 BEGIN
			INSERT INTO Contratos (Id_Contrato,Id_Cliente,Id_Tipo_Con,Fecha_Alta,Fecha_Desde,fecha_hasta,Activo,Id_Tipo_Cbte,Id_Lista_Precio,Flag_Sistema)
						VALUES(@Existe,@Cli,7,GETDATE(),@fecha_qa,@fecha_hasta,1,'',0,0) 

			INSERT INTO Contratos_Prod (Id_Contrato,Item,Id_Producto)
						VALUES(@Existe,1,@id_producto) 
			
			--bajo los contacto para traerlo a prueba			
			update CRM_Contactos set fecha_reso = GETDATE() 
			       where id_cliente = @cli and Id_Motivo_Contacto = 5 and Id_SubMotivo_Contacto = 1 and Id_Objeto_Contacto = 1
			       --agrego un contacto con fecha del proximo contacto la fecha hasta mas 7 dias
			       
			--agrego el contacto para inscribirlo
			INSERT INTO CRM_Contactos (Id_Contacto,Fecha,Id_Tipo_Contacto,Id_Motivo_Contacto,Id_Cliente
				   ,Fecha_Aviso,Id_SubMotivo_Contacto,Id_Objeto_Contacto,Id_Trans,Id_Usuario)
						VALUES(@id_contacto,GETDATE(),5,5,@Cli,dateadd(day,14,@fecha_qa),2,2,0,0)

		 END               
		 ELSE
		 BEGIN
 			 INSERT INTO Contratos (Id_Contrato,Id_Cliente,Id_Tipo_Con,Fecha_Alta,Fecha_Desde,fecha_hasta,Activo,Id_Tipo_Cbte,Id_Lista_Precio,Flag_Sistema)
						VALUES(@Existe,@Cli,1,GETDATE(),@fecha_qa,@fecha_hasta,1,'',0,0) --dateadd(month,1,@fecha_qa)
			
			 INSERT INTO Contratos_Prod (Id_Contrato,Item,Id_Producto)
						VALUES(@Existe,1,@id_producto) 
			--RESULEVO LA ANTERIOR			
			 update CRM_Contactos set fecha_reso = GETDATE() 
					 where id_cliente = @cli 
					 and ((Id_Motivo_Contacto = 5 and Id_SubMotivo_Contacto = 2 and Id_Objeto_Contacto = 2) 
					       or (Id_Motivo_Contacto = 5 and Id_SubMotivo_Contacto = 1 and Id_Objeto_Contacto = 1)
					       or (Id_Motivo_Contacto = 5 and Id_SubMotivo_Contacto = 4 and Id_Objeto_Contacto = 4)
					       or (Id_Motivo_Contacto = 5 and Id_SubMotivo_Contacto = 3 and Id_Objeto_Contacto = 3
					            and Fecha_Aviso < GETDATE()))
			         
	
			 INSERT INTO CRM_Contactos (Id_Contacto,Fecha,Id_Tipo_Contacto,Id_Motivo_Contacto,Id_Cliente
					   ,Fecha_Aviso,Id_SubMotivo_Contacto,Id_Objeto_Contacto,Id_Trans,Id_Usuario)
							VALUES(@id_contacto,GETDATE(),5,5,@Cli,@fecha_hasta-20,3,3,0,0)
		 END
 END 

                
 UPDATE Cbtes_Items SET Lote = @Existe WHERE Id_Trans = @id_Trans AND Item = @item               

end
GO

CREATE PROCEDURE [dbo].[SP_AnularContrato] @Id_cliente int ,@id_Trans int
AS
begin

DECLARE @Existe INT
declare @id_producto varchar(14)
declare @cbte int
declare @fecha_hasta datetime
declare @lote varchar(14)


set @cbte = (select  id_trans from cbtes c inner join cbtes_tipos ct on c.id_tipo_cbte = ct.id_tipo_cbte 
                  where  c.id_estado_cbte = 3 and  c.comprobante_nro <> 0 and c.id_trans = @id_Trans
             and ct.compromete_factura = 1 ) 
print @cbte
if  (@cbte <> 0)
print 'pasa'
	Declare CursorContratos Cursor for
	select cast (lote as int) from cbtes_items where id_trans = @cbte
	and isnumeric(lote) = 1 and isnull(lote,0)<> 0
    OPEN CursorContratos

	FETCH NEXT FROM CursorContratos
	INTO @lote

	WHILE @@FETCH_STATUS = 0
	BEGIN
	     update contratos set activo = 0 ,fecha_baja = getdate(),id_motivo_est = 6
         where id_contrato = @lote 
		FETCH NEXT FROM CursorContratos
		INTO @lote
	END

	CLOSE CursorContratos
	DEALLOCATE CursorContratos

end
GO


CREATE PROCEDURE [dbo].[SP_Anular_Cbtes_Pendientes_Carnet_Referente]
AS

DECLARE @Id_Trans			INT
DECLARE @Fecha_Actual		DATETIME

SET @Fecha_Actual = CONVERT(DATE, GETDATE())

IF OBJECT_ID('dbo.Cbtes_Pendientes_Carnet_Referente#', 'U') IS NOT NULL
BEGIN
	DROP TABLE dbo.Cbtes_Pendientes_Carnet_Referente#;
END

SELECT Id_Trans 
INTO Cbtes_Pendientes_Carnet_Referente#
FROM Cbtes
WHERE
Id_Estado_Cbte = 1 /*Pendiente*/
AND Id_Contrato IN (SELECT Id_Contrato FROM Contratos WHERE Id_Tipo_Con = 19 AND Fecha_Desde <= @Fecha_Actual AND (Fecha_Hasta >= @Fecha_Actual OR Fecha_Hasta IS NULL))

DECLARE curAnulCbtesPendCarnetRef CURSOR FOR 
SELECT Id_Trans FROM Cbtes_Pendientes_Carnet_Referente#

OPEN curAnulCbtesPendCarnetRef
FETCH NEXT FROM curAnulCbtesPendCarnetRef INTO @Id_Trans
WHILE @@FETCH_STATUS = 0
BEGIN
	
	UPDATE Cbtes SET Id_Estado_Cbte = 3, Observacion = 'Anulado por Proceso Automatico. Fecha Anulacion: ' + CONVERT(VARCHAR(10), @Fecha_Actual, 103) WHERE Id_Trans = @Id_Trans
	UPDATE Cbtes_Items SET Id_Estado_Cbte = 3 WHERE Id_Trans = @Id_Trans
	UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 3 WHERE Id_Trans = @Id_Trans

	FETCH NEXT FROM curAnulCbtesPendCarnetRef INTO @Id_Trans
END 
CLOSE curAnulCbtesPendCarnetRef
DEALLOCATE curAnulCbtesPendCarnetRef
GO


