CREATE PROCEDURE [dbo].[SP_CD_TagsHabilitados] @Id_Acceso SMALLINT, @Fecha DATETIME
AS

BEGIN
DECLARE @Tags			VARCHAR(1349)
DECLARE @Id_Cliente		INT
DECLARE @Tag			VARCHAR(30);
DECLARE @Contador		INT
DECLARE @FlagHabilitado TINYINT

SET @Contador = 0
SET @FlagHabilitado = 0

PRINT 'INCIO del Proceso: SP_CD_TagsHabilitados'

PRINT 'Id_Acceso: ' + CONVERT(VARCHAR(10), @Id_Acceso)
PRINT 'Fecha: ' + CONVERT(VARCHAR(10), @Fecha, 103)

PRINT 'Se eliminan los registros viejos'
DELETE FROM CD_Accesos_Tags WHERE Id_Acceso = @Id_Acceso

DECLARE curTagsHabilitados CURSOR FOR 
SELECT DISTINCT CL.Id_Cliente, CL.Credencial_Nro
FROM Clientes CL
WHERE
CL.Activo = 1
AND CL.Credencial_Nro IS NOT NULL
AND CL.Credencial_Nro <> '00000000'
AND CL.Credencial_Nro <> ''
GROUP BY CL.Id_Cliente, CL.Credencial_Nro

OPEN curTagsHabilitados
FETCH NEXT FROM curTagsHabilitados
INTO @Id_Cliente, @Tag
WHILE @@FETCH_STATUS = 0
BEGIN
	
	SET @FlagHabilitado = 0
	
	IF(dbo.SF_CD_ValidarMaster(@Id_Cliente) = 1)
	BEGIN
		SET @FlagHabilitado = 1
	END
	ELSE
	BEGIN
		IF(dbo.SF_CD_ValidarContratosTipos(@Id_Cliente, @Id_Acceso, @Fecha) = 1)
		BEGIN
			SET @FlagHabilitado = 1
		END
		ELSE
		BEGIN
			IF(dbo.SF_CD_ValidarTipo(@Id_Cliente, @Id_Acceso, @Fecha) = 1)
			BEGIN
				SET @FlagHabilitado = 1
			END
			ELSE
			BEGIN
				IF(dbo.SF_CD_ValidarProducVta(@Id_Cliente, @Id_Acceso, @Fecha) = 1)
				BEGIN
					SET @FlagHabilitado = 1
				END
			END
		END
	END
	
	IF(@FlagHabilitado = 1)
	BEGIN
		PRINT 'Agregando a la Lista Blanca al Id_Cliente: ' + CONVERT(VARCHAR(15), @Id_Cliente) + ' Tag: ' + @Tag
		INSERT INTO CD_Accesos_Tags (Id_Acceso, Id_Tag) VALUES (@Id_Acceso, @Tag)		
		
		SET @Contador = @Contador + 1
	END
		
			
FETCH NEXT FROM curTagsHabilitados
INTO @Id_Cliente, @Tag
END 
CLOSE curTagsHabilitados;
DEALLOCATE curTagsHabilitados;

PRINT 'FIN del Proceso: SP_CD_TagsHabilitados'

END
GO

