CREATE PROCEDURE [dbo].[SP_Cbtes_Items_Cant] @trans INT, @Item SMALLINT, @Prod VARCHAR(14)
AS

-------------------------------------------Verifico que dif cero ----------
DECLARE @Meses INT ,@item_nuevo SMALLINT
SET @Meses = (SELECT c.Cantidad FROM Cbtes_Items C
              WHERE C.Id_Trans = @trans AND Item = @Item)
IF @Meses = 0
	RETURN    

-------------------------------------------Verifico que sea un debito ----------
IF NOT EXISTS(SELECT 1 FROM Cbtes_Tipos T, Cbtes C
              WHERE C.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
              AND C.Id_Trans = @trans AND T.Compromete_Factura in (1,-1))
    RETURN
-------------------------------------------Verifico que tenga flag mes ----------
IF NOT EXISTS(SELECT 1 FROM Productos
              WHERE id_producto = @prod
              AND flag_mes = 1)
    RETURN
-------------------------------------------Cantidad de Meses a Generar --------------    

             
IF @Meses <= 1
	RETURN

SET @Meses = @Meses - 1
-------------------------------------------Cargo el primer mes en el campo fecha -----
DECLARE @Fecha DATETIME
SET @Fecha = (SELECT c.Fecha_QA FROM Cbtes_Items C
              WHERE C.Id_Trans = @trans AND Item = @Item)
SET @Fecha = DATEADD(month, 1, @Fecha)  
  
   
-------------------------------------------Genero cada mes------------------
DECLARE @cant TINYINT
DECLARE @nro_item SMALLINT
DECLARE @descrip VARCHAR(100)

SET @nro_item = 1000 + @Item
SET @descrip = (SELECT Descripcion_producto FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item) 
SET @cant = 1

UPDATE Cbtes_Items 
SET Cantidad = 1 , Imp_Gravado = Precio_Grav , Imp_Final = Precio_Grav + Precio_Exen, Imp_Exento = Precio_Exen
WHERE Id_Trans = @trans AND Item = @Item

WHILE @cant <= @Meses
BEGIN
  	SET @item_nuevo = ISNULL((SELECT MAX(item) FROM Cbtes_Items WITH (NOLOCK) WHERE Id_Trans = @trans),0) +1
	IF @item_nuevo < 100
	   SET @item_nuevo = 100

    SELECT * INTO #ITEMS FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item
    UPDATE #ITEMS SET Item = @item_nuevo, Fecha_QA = @Fecha
    INSERT INTO Cbtes_Items SELECT * FROM #ITEMS
	 
    EXEC SP_Cbtes_Items_Integrantes @trans,@item_nuevo,@prod

    SET @Fecha = DATEADD(month, 1, @Fecha)
    SET @nro_item = @nro_item + 1
	SET @cant = @cant + 1
	DROP TABLE #ITEMS
END
GO

    /********************************************************************
     SP_Cbtes_Items_Integrantes
     Autor: Gemini AI (ajuste técnico) / Reordenado por Maca
     Fecha: 2025-10-22
     Descripción:
       Calcula y distribuye el importe del grupo familiar:
       - El titular nunca queda negativo.
       - Redondeo a 2 decimales.
       - La suma de integrantes + titular = importe total.
       - Evita cursores, utilizando tabla temporal.
    ********************************************************************/

CREATE PROCEDURE [dbo].[SP_Cbtes_Items_Integrantes]
    @trans INT,
    @Item SMALLINT,
    @Prod VARCHAR(14)
AS
BEGIN
    SET NOCOUNT ON;



    DECLARE 
        @Id_Familia INT,
        @Id_Cliente INT,
        @Id_Cliente_Ref INT,
        @Id_Cond_Vta CHAR(10),
        @Imp_Final DECIMAL(15,5),
        @Id_Estado_Cbte SMALLINT,
        @Fecha_Venc DATETIME,
        @Lote VARCHAR(20),
        @Bonif DECIMAL(5,2),
        @Descripcion_Producto VARCHAR(100),
        @Flag_QA CHAR(1),
        @Fecha_QA DATETIME,
        @Cant_Integrantes SMALLINT,
        @Precio_CS_Titular DECIMAL(15,5),
        @item_base		SMALLINT,
		@ModoDebug		SMALLINT,
  		@Cond_Pago		SMALLINT,
		@Id_Usuario		SMALLINT,
		@Porc_Iva		DECIMAL(5,2),	
		@Imp_Iva		DECIMAL(15,2),
		@Cantidad_saldo	DECIMAL(15,5),
		@Cantidad		DECIMAL (15,5)
SET @ModoDebug = 0
	
    IF @ModoDebug = 1
	BEGIN
			PRINT '---------------------------------------------------------------'
			PRINT 'Inicio SP_Cbtes_Items_Integrantes | Trans=' + CONVERT(VARCHAR(10),@trans)
	END
    -- 1. Verifica si el comprobante compromete factura
    IF NOT EXISTS(
        SELECT 1 
        FROM Cbtes_Tipos T 
        JOIN Cbtes C ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
        WHERE C.Id_Trans = @trans 
          AND T.Compromete_Factura IN (1,-1)
    )
    BEGIN
        IF @ModoDebug = 1
		BEGIN	
			PRINT 'Tipo de comprobante NO compromete factura. Sale del SP.'
        END
		RETURN
    END

    -- 2. Obtiene cliente titular del comprobante
    SELECT @Id_Cliente = Id_Cliente
    FROM Cbtes
    WHERE Id_Trans = @trans

    IF @Id_Cliente IS NULL OR @Id_Cliente IN (0,1,1105)
    BEGIN
		IF @ModoDebug = 1
		BEGIN
			PRINT 'Id_Cliente no válido o referente. Sale del SP.'
        END
		RETURN
    END

    -- 3. Valida que sea titular (no integrante)
    SELECT @Id_Cliente_Ref = Id_Cliente_Ref,
           @Id_Cond_Vta = Id_Cond_Vta
    FROM Clientes
    WHERE Id_Cliente = @Id_Cliente

    IF @Id_Cliente_Ref <> 0
    BEGIN
        IF @ModoDebug = 1
		BEGIN	
			PRINT 'Cliente es integrante. Sale del SP.'
        END
		RETURN
    END

    IF (LTRIM(RTRIM(@Id_Cond_Vta)) = 'GFCP')
    BEGIN
        IF @ModoDebug = 1
		BEGIN
			PRINT 'Condición de venta GFCP (cobro separado). Sale del SP.'
        END
		RETURN
    END

    -- 4. Verifica familia del producto
    SET @Id_Familia = (SELECT Id_Familia FROM Productos WHERE Id_Producto = @Prod)
    IF @Id_Familia NOT IN (SELECT dbo.CF_xParam('Fam_CuotasSoc'))
        RETURN

    -- 5. Obtiene info del ítem original
    SELECT 
        @Precio_CS_Titular = dbo.SF_CS_Precio_Persona(Id_Cliente, Fecha_QA),
        @Imp_Final = ISNULL(Imp_Final,0),
        @Id_Estado_Cbte = Id_Estado_Cbte,
        @Fecha_Venc = Fecha_Venc,
        @Lote = ISNULL(Lote,''),
        @Flag_QA = Flag_QA,
        @Bonif = ISNULL(Bonif,0),
        @Descripcion_Producto = Descripcion_Producto,
        @Fecha_QA = Fecha_QA,
		@Cond_Pago = Id_Cond_Pago,
		@Id_Usuario = Id_Usuario,
		@Porc_Iva	=Porc_Iva,		
		@Imp_Iva	=Imp_Iva,
		@Cantidad_Saldo	=Cantidad_Saldo,
		@Cantidad		= Cantidad
		
    FROM Cbtes_Items
    WHERE Id_Trans = @trans AND Item = @Item AND Id_Cliente = @Id_Cliente

	IF @ModoDebug = 1
	BEGIN
		PRINT 'Precio CS Titular: ' + CONVERT(VARCHAR(30),@Precio_CS_Titular)
	END
    -- 6. Contar integrantes
    SELECT @Cant_Integrantes = COUNT(*) 
    FROM Clientes 
    WHERE Id_Cliente_Ref = @Id_Cliente 
      AND Activo = 1 
      AND Tipo_Persona = 'F'

    IF @Cant_Integrantes = 0
    BEGIN
		IF @ModoDebug = 1
		BEGIN
			PRINT 'Sin integrantes. Se actualiza solo el titular.'
        END
		UPDATE Cbtes_Items
        SET Precio_Grav = @Precio_CS_Titular,
            Imp_Gravado = @Precio_CS_Titular,
            Imp_Final = @Precio_CS_Titular,
            Precio = @Precio_CS_Titular
        WHERE Id_Trans = @trans AND Item = @Item
        RETURN
    END
	IF @ModoDebug = 1
	BEGIN
		PRINT 'Integrantes detectados: ' + CONVERT(VARCHAR(10),@Cant_Integrantes)
	END
    -- 7. Tabla temporal con todos los miembros del grupo familiar
    SELECT 
        c.Id_Cliente,
        dbo.SF_CS_Precio_Persona(c.Id_Cliente, @Fecha_QA) AS Precio_CS,
        CASE WHEN c.Id_Cliente_Ref = 0 THEN 1 ELSE 0 END AS EsTitular
    INTO #IntegrantesGF
    FROM Clientes c
    WHERE (c.Id_Cliente_Ref = @Id_Cliente OR c.Id_Cliente = @Id_Cliente)
      AND c.Activo = 1
      AND c.Tipo_Persona = 'F'

    -- 8. Calcula ítem base y genera líneas de ítems para integrantes
    SET @item_base = ISNULL((SELECT MAX(Item) FROM Cbtes_Items WHERE Id_Trans = @trans),0) + 1

    SELECT 
        ROW_NUMBER() OVER (ORDER BY Id_Cliente) + (@item_base - 1) AS ItemNuevo,
        i.Id_Cliente,
        i.Precio_CS
    INTO #ItemsNuevos
    FROM #IntegrantesGF i
    WHERE EsTitular = 0

    --  9. Crea registros para cada integrante
	
    INSERT INTO Cbtes_Items (
					Id_Trans,		Item,			Id_Producto,			Id_Estado_Cbte,
					Cantidad,		Precio_Grav,	Imp_Gravado,			Imp_Final, 
					Precio,			Fecha_Venc,		Lote,					Flag_QA,
					Id_Cliente,		Bonif,			Descripcion_Producto,	Cantidad_Saldo,
					Fecha_QA,		Id_Usuario,		Porc_Iva,				Imp_Iva,
					Id_Cond_Pago
				)
    SELECT 
					@trans,			i.ItemNuevo,	'CS',					@Id_Estado_Cbte,
					@Cantidad,		i.Precio_CS,	i.Precio_CS,			i.Precio_CS, 
					i.Precio_CS,	@Fecha_Venc,	@Lote,					@Flag_QA, 
					i.Id_Cliente,	@Bonif,			@Descripcion_Producto,	@Cantidad_saldo,				
					@Fecha_QA,		@Id_Usuario,	@Porc_Iva,				@Imp_Iva,		
					@Cond_Pago
    FROM #ItemsNuevos i
	IF @ModoDebug = 1
    BEGIN
		PRINT 'Se insertaron ' + CONVERT(VARCHAR(10),@@ROWCOUNT) + ' ítems de integrantes.'
	END
    --  10. Actualiza ítem del titular
    UPDATE Cbtes_Items
    SET Precio_Grav = @Precio_CS_Titular,
        Imp_Gravado = @Precio_CS_Titular,
        Imp_Final = @Precio_CS_Titular,
        Precio = @Precio_CS_Titular
    WHERE Id_Trans = @trans AND Item = @Item

    IF @ModoDebug = 1
	BEGIN
		PRINT 'Actualizado ítem del titular con precio CS.'
	END

    DROP TABLE #IntegrantesGF
    DROP TABLE #ItemsNuevos

	IF @ModoDebug = 1
    BEGIN
		PRINT 'Fin SP_Cbtes_Items_Integrantes'
		PRINT '---------------------------------------------------------------'
	END
END
GO

CREATE PROCEDURE [dbo].[SP_Cbtes_Items_Integrantes_2]
    @trans INT,
    @Item  SMALLINT,
    @Prod  VARCHAR(14)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRAN;

        DECLARE @Id_Familia INT;
        SET @Id_Familia = (SELECT Id_Familia FROM Productos WHERE Id_Producto = @Prod);

        PRINT '-----------------------------------------------------------------------------------'
        PRINT 'Ingreso SP: SP_Cbtes_Items_Integrantes'
        PRINT 'Id_Trans: ' + CONVERT(VARCHAR(10), @trans) + ' Item: ' + CONVERT(VARCHAR(10), @Item) + ' Producto: ' + @Prod

        /* Verifica si el Tipo de Cbte Compromete Factura */
        PRINT 'Verifica si el Tipo de Cbte Compromete Factura'
        IF NOT EXISTS(
            SELECT 1
            FROM Cbtes_Tipos T
            JOIN Cbtes C ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
            WHERE C.Id_Trans = @trans
              AND T.Compromete_Factura IN (1, -1)
        )
        BEGIN
            PRINT 'El Tipo de Cbte NO compromete Factura'
            PRINT 'SALE DEL SP'
            ROLLBACK TRAN;
            RETURN;
        END
        PRINT 'El Tipo de Cbte compromete Factura'

        /* Actualizo Id_Producto_Orig si corresponde */
        UPDATE Cbtes_Items
        SET Id_Producto_Orig = Id_Producto
        WHERE Id_Trans = @Trans AND Item = @Item;

        /* Verifica si el Producto es C.S. (Familia 1) */
        PRINT 'Verifica si el Producto es C.S.'
        IF @Id_Familia NOT IN (1)
        BEGIN
            PRINT 'Producto no pertenece a la familia CS. SALE DEL SP'
            ROLLBACK TRAN;
            RETURN;
        END

        IF @Prod <> 'CS'
        BEGIN
            UPDATE Cbtes_Items
            SET Id_Producto = 'CS'
            WHERE Id_Trans = @Trans AND Item = @Item AND Id_Producto <> 'CS';
        END

        /* Verifico que el Comprobante sea un Titular */
        DECLARE @Id_Cliente INT;
        DECLARE @Id_Cliente_Ref INT;
        DECLARE @item_nuevo SMALLINT;

        SET @Id_Cliente = ISNULL((SELECT Id_Cliente FROM Cbtes WHERE Id_Trans = @trans), 0);
        PRINT 'Id_Cliente del Cbte: ' + CONVERT(VARCHAR(10), @Id_Cliente);

        IF @Id_Cliente IN (0,1,1105)
        BEGIN
            PRINT 'El Id_Cliente es NO DEFINIDO o VARIOS o REFERENTE'
            PRINT 'SALE DEL SP'
            ROLLBACK TRAN;
            RETURN;
        END

        SET @Id_Cliente_Ref = ISNULL((SELECT Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @Id_Cliente), 0);

        IF @Id_Cliente_Ref <> 0
        BEGIN
            PRINT 'El Id_Cliente es INTEGRANTE'
            PRINT 'SALE DEL SP'
            ROLLBACK TRAN;
            RETURN;
        END

        DECLARE @Id_Cond_Vta CHAR(10);
        SET @Id_Cond_Vta = (SELECT Id_Cond_Vta FROM Clientes WHERE Id_Cliente = @Id_Cliente);

        IF (LTRIM(RTRIM(@Id_Cond_Vta)) = 'GFCP')
        BEGIN
            PRINT 'La condicion de Venta es: ESPECIAL-G. Fam Cobro x Separado'
            PRINT 'SALE DEL SP'
            ROLLBACK TRAN;
            RETURN;
        END

        /* Cantidad de Integrantes activos */
        DECLARE @Cant_Integrantes SMALLINT;
        SET @Cant_Integrantes = ISNULL(
            (SELECT COUNT(Id_Cliente) FROM Clientes WHERE Id_Cliente_Ref = @Id_Cliente AND Activo = 1),
            0
        );
        PRINT 'Cant. de Integrantes del Grupo Familiar: ' + CONVERT(VARCHAR(10), @Cant_Integrantes);

        IF @Cant_Integrantes = 0
        BEGIN
            PRINT 'No hay Integrantes en el G.F.'
            PRINT 'SALE DEL SP'
            ROLLBACK TRAN;
            RETURN;
        END

        DECLARE @Imp_Final DECIMAL(18,5);
        DECLARE @Fecha DATETIME;
        DECLARE @Fecha_QA DATETIME;

        SET @Fecha = (SELECT Fecha FROM Cbtes WHERE Id_Trans = @trans);
        SET @Fecha_QA = ISNULL((SELECT Fecha_QA FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item), @Fecha);

        /*
         * 1) Cargar en una tabla temporal los precios por persona (se calcula una sola vez)
         */
        IF OBJECT_ID('tempdb..#Precios_CS') IS NOT NULL DROP TABLE #Precios_CS;

        SELECT
            Id_Cliente,
            dbo.SF_CS_Precio_Persona(Id_Cliente, @Fecha_QA) AS Precio_CS
        INTO #Precios_CS
        FROM Clientes
        WHERE (Id_Cliente_Ref = @Id_Cliente OR Id_Cliente = @Id_Cliente)
          AND Activo = 1
          AND Tipo_Persona = 'F'
          AND Id_Tipo_Cli NOT IN (1105);

        -- Total esperado
        SELECT @Imp_Final = ISNULL(SUM(Precio_CS), 0) FROM #Precios_CS;
        PRINT 'Importe Final del Item $' + CONVERT(VARCHAR(30), @Imp_Final);

        DECLARE @Id_Estado_Cbte SMALLINT;
        SET @Id_Estado_Cbte = ISNULL((SELECT Id_Estado_Cbte FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item), 1);
        PRINT 'Estado del Item: ' + CONVERT(VARCHAR(10), @Id_Estado_Cbte);

        DECLARE @Fecha_Venc DATETIME;
        SET @Fecha_Venc = ISNULL((SELECT Fecha_Venc FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item), GETDATE());
        PRINT 'Fecha Vencimiento del Item: ' + CONVERT(VARCHAR(20), @Fecha_Venc, 103);

        DECLARE @Lote VARCHAR(20);
        SET @Lote = ISNULL((SELECT Lote FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item), '');
        PRINT 'Lote del Item: ' + @Lote;

        DECLARE @Flag_QA CHAR(1);
        SET @Flag_QA = ISNULL((SELECT Flag_QA FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item), 'A');
        PRINT 'Flag QA del Item: ' + @Flag_QA;

        DECLARE @Bonif DECIMAL(5,2);
        SET @Bonif = ISNULL((SELECT Bonif FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item), 0);
        PRINT 'Porc. Bonificacion del Item: ' + CONVERT(VARCHAR(30), @Bonif);

        DECLARE @Descripcion_Producto VARCHAR(100);
        SET @Descripcion_Producto = ISNULL((SELECT Descripcion_Resumida FROM Productos WHERE Id_Producto = @Prod), 'Producto desconocido');
        PRINT 'Descripcion del Producto del Item: ' + @Descripcion_Producto;

        /*
         * 2) Plantilla del ítem original (una sola vez)
         */
        IF OBJECT_ID('tempdb..#ITEMSFAM_BASE') IS NOT NULL DROP TABLE #ITEMSFAM_BASE;
        IF OBJECT_ID('tempdb..#ITEMSFAM') IS NOT NULL DROP TABLE #ITEMSFAM;

        -- Copia del ítem original: contiene la estructura y los valores
        SELECT * INTO #ITEMSFAM_BASE
        FROM Cbtes_Items
        WHERE Id_Trans = @trans AND Item = @Item;

        -- Crea tabla vacía con la misma estructura para reutilizar en cada iteración
        SELECT TOP (0) * INTO #ITEMSFAM FROM #ITEMSFAM_BASE;

        /*
         * 3) Recorremos integrantes usando los precios ya calculados en #Precios_CS
         */
        PRINT 'Se recorren los Integrantes del Grupo';

        DECLARE @id_cliente_Integrante INT;
        DECLARE @Precio_CS_Integrante DECIMAL(18,5);
        DECLARE @Nro_Integrante SMALLINT = 0;
        DECLARE @Resto_Precio_Final DECIMAL(18,5) = @Imp_Final;
        DECLARE @Cantidad_Saldo DECIMAL(18,5);
        DECLARE @TotalIntegrantesEnLista INT;

        SELECT @TotalIntegrantesEnLista = COUNT(*) FROM #Precios_CS WHERE Id_Cliente <> @Id_Cliente; -- excluye titular si listado lo incluye

        -- Cursor local que recorre la lista de integrantes ordenada (excluye titular si es parte de la lista)
        DECLARE curIntegItems CURSOR LOCAL FAST_FORWARD FOR
            SELECT Id_Cliente, Precio_CS
            FROM #Precios_CS
            WHERE Id_Cliente <> @Id_Cliente
            ORDER BY Id_Cliente; -- si necesitás otro orden, cambiar aquí

        OPEN curIntegItems;
        FETCH NEXT FROM curIntegItems INTO @id_cliente_Integrante, @Precio_CS_Integrante;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            SET @Nro_Integrante = @Nro_Integrante + 1;

            -- Si es el último integrante, se le asigna el resto (evita diferencias por redondeo)
            IF @Nro_Integrante = @TotalIntegrantesEnLista
            BEGIN
                SET @Precio_CS_Integrante = ISNULL(@Resto_Precio_Final, 0);
            END

            SET @item_nuevo = ISNULL((SELECT MAX(Item) FROM Cbtes_Items WITH (NOLOCK) WHERE Id_Trans = @trans), 0) + 1;
            IF @item_nuevo < 100 SET @item_nuevo = 100;

            PRINT 'Integrante Nro: ' + CONVERT(VARCHAR(10), @Nro_Integrante)
                  + ' Id_Cliente: ' + CONVERT(VARCHAR(10), @id_cliente_Integrante)
                  + ' Precio CS: $' + CONVERT(VARCHAR(30), @Precio_CS_Integrante);

            IF @Id_Estado_Cbte IN (1, 4)
                SET @Cantidad_Saldo = @Precio_CS_Integrante;
            ELSE
                SET @Cantidad_Saldo = 0;

            PRINT 'Se insertará en Cbtes_Items. Id_Trans: ' + CONVERT(VARCHAR(20), @trans) + ' Item: ' + CONVERT(VARCHAR(20), @item_nuevo);

            -- Reutilizo la tabla #ITEMSFAM: limpiala y copia la base
            DELETE FROM #ITEMSFAM;
            INSERT INTO #ITEMSFAM
            SELECT * FROM #ITEMSFAM_BASE;

            -- Actualizo los campos que deben cambiar
            UPDATE #ITEMSFAM
            SET
                Item = @item_nuevo,
                Precio_Grav = @Precio_CS_Integrante,
                Imp_Gravado = @Precio_CS_Integrante,
                Imp_Final = @Precio_CS_Integrante,
                Precio = @Precio_CS_Integrante,
                Id_Cliente = @id_cliente_Integrante
            -- Si tu tabla tiene columnas adicionales que necesiten cálculo (Saldo, Cantidad, Fecha_Venc, etc.) agrégalas aquí.

            -- Inserto el nuevo item para el integrante
            INSERT INTO Cbtes_Items
            SELECT * FROM #ITEMSFAM;

            -- Resto para asignar al titular / últimas iteraciones
            SET @Resto_Precio_Final = @Resto_Precio_Final - @Precio_CS_Integrante;

            PRINT 'Precio Item Inicial: ' + CONVERT(VARCHAR(30), @Imp_Final);
            PRINT 'Quedan $' + CONVERT(VARCHAR(30), @Resto_Precio_Final) + ' para dividir entre el resto de los integrantes';

            FETCH NEXT FROM curIntegItems INTO @id_cliente_Integrante, @Precio_CS_Integrante;
        END

        CLOSE curIntegItems;
        DEALLOCATE curIntegItems;

        /*
         * 4) Actualizo el Precio del Titular según lo que restaba (o según su precio calculado si lo preferís)
         */
        PRINT 'El Resto de: $' + CONVERT(VARCHAR(30), @Resto_Precio_Final) + ' lo asignará al Titular';

        UPDATE Cbtes_Items
        SET
            Precio_Grav = @Resto_Precio_Final,
            Imp_Gravado = @Resto_Precio_Final,
            Imp_Final = @Resto_Precio_Final,
            Precio = @Resto_Precio_Final
        WHERE Id_Trans = @trans AND Item = @Item;

        COMMIT TRAN;

        PRINT 'FIN SP: SP_Cbtes_Items_Integrantes';
        PRINT '-----------------------------------------------------------------------------------';
    END TRY
    BEGIN CATCH
        DECLARE @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrNum INT = ERROR_NUMBER();
        DECLARE @ErrLine INT = ERROR_LINE();

        IF XACT_STATE() <> 0
            ROLLBACK TRAN;

        PRINT 'ERROR en SP_Cbtes_Items_Integrantes: ' + ISNULL(CONVERT(VARCHAR(10), @ErrNum), '') + ' - ' + @ErrMsg + ' Line: ' + ISNULL(CONVERT(VARCHAR(10), @ErrLine), '');
        THROW; -- re-lanza el error
    END CATCH
END
GO


CREATE PROCEDURE [dbo].[SP_Cbtes_Items_Validar_Fecha_QA] @Fecha_QA DATETIME
AS

/*Declaracion de Variables*/
DECLARE @Modo_Debug					TINYINT
DECLARE @MesesDiferencia			INT
/*FIN Declaracion de Variables*/

SET @Modo_Debug = 0

IF(@Modo_Debug = 1)
BEGIN
	PRINT '----------------------------------------------------------------'
	PRINT 'Inicio de ejecucion: SP_Cbtes_Items_Validar_Fecha_QA'
END

IF(@Modo_Debug = 1)
BEGIN
	PRINT 'Fecha QA Ingresada: ' + CONVERT(VARCHAR(10), @Fecha_QA, 103)
END

SET @MesesDiferencia = ISNULL((SELECT DATEDIFF(mm, GETDATE(), @Fecha_QA)), 0)

IF(@Modo_Debug = 1)
BEGIN
	PRINT 'Cant. Meses de Diferencia: ' + CONVERT(VARCHAR(10), @MesesDiferencia)
END

IF(@MesesDiferencia >= 57)
BEGIN
	/*Devuelve un error. Se dejan espacios para que en el mensaje de error del sistema no aparezca nada mas*/
	RAISERROR (N'OPERACIÓN INVÁLIDA. No puede ingresar una fecha superior o igual a 14 meses.                                                                                                                                                                                 ', 16, 1);
END

IF(@Modo_Debug = 1)
BEGIN
	PRINT 'Fin de ejecucion: SP_Cbtes_Items_Validar_Fecha_QA'
	PRINT '----------------------------------------------------------------'
END
GO

CREATE  PROCEDURE [dbo].[SP_Clientes_Fun1] @Cli INT
AS

DECLARE @Retorno VARCHAR(200)
DECLARE @UCP		DATETIME
DECLARE @UDPActual	DATETIME
DECLARE @pFecha		DATETIME

SET @UCP		= (SELECT ISNULL(dbo.SF_Ult_Cuota_Paga(@Cli,@pFecha), '19000101'))
SET @UDPActual	= (SELECT ISNULL(Ult_Cuota_Paga, '19000101') FROM Clientes WHERE Id_Cliente = @Cli)

IF(@UCP <> @UDPActual)
BEGIN
	UPDATE Clientes SET Ult_Cuota_Paga = @UCP WHERE Id_Cliente = @Cli
	SET @Retorno = 'La Fecha de Última Cuota Paga fué actualizada. Últ. Cuota Paga: ' + CONVERT(VARCHAR(10), @UCP, 103)
END
ELSE
BEGIN
	SET @Retorno = 'La Fecha de Última Cuota Paga no tiene modificaciones. Ult. Cuota Paga: ' + CONVERT(VARCHAR(10), @UCP, 103)
END

SELECT @Retorno
GO

