CREATE PROCEDURE [dbo].[SP_Clientes_Validar] @Id_Cliente INT
AS

/*Declaracion de Variables*/
DECLARE @Id_Tipo_Cli_Actual			SMALLINT
DECLARE @Flag_Categ_Actual_Usuario	TINYINT
DECLARE @Id_Tipo_Cli_Anterior		SMALLINT
DECLARE @Flag_Categ_Anterior_Usuario TINYINT
DECLARE @Clientes_Hist_Item_Anterior SMALLINT
DECLARE @Fecha_Ult_Cuota_Paga		DATETIME
DECLARE @Anio_Pasado				DATETIME
DECLARE @Cant_Meses_Desde_UCP		INT
DECLARE @Modo_Debug					TINYINT
/*FIN Declaracion de Variables*/

SET @Modo_Debug = 1

IF(@Modo_Debug = 1)
BEGIN
	PRINT '----------------------------------------------------------------'
	PRINT 'Inicio de ejecucion: SP_Clientes_Validar'
END

SET @Flag_Categ_Actual_Usuario	= 0 
SET @Flag_Categ_Anterior_Usuario = 0

IF(@Modo_Debug = 1)
BEGIN
	PRINT 'Validacion del Cod. Cliente: ' + CONVERT(VARCHAR(10), @Id_Cliente)
END

/*Cliente no definido o varios*/
IF (@Id_Cliente <= 1)
BEGIN
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Socio NO DEFINIDO o VARIOS. Sale del SP: SP_Clientes_Validar'
	END
END
/*FIN Cliente no definido o varios*/

/*
0		SIN CATEGORIZAR
10		ACCESO MASTER
1000	INFANTIL
1001	CADETE
1002	ACTIVO MENOR
1003	ACTIVO MAYOR
1004	ACOMPAÑANTE
1005	CONYUGUE EMPLEADO
1006	EMPLEADO
1007	USUARIO GEBA GYM
1008	USUARIO
1010	VITALICIO + 71
1011	RESOLUCION 95
1012	USUARIO RCA
1013	USUARIO AFIP
1014	USUARIO J.N.
1015	CONCESIONARIO
1016	USUARIO S.M. / JM
1017	USUARIO +75
1018	INVITADOS
1019	COLEGIOS
1020	VITALICIOS RES.20
1055	VITALICIO 48/55
1060	VITALICIO 56/60
1065	VITALICIO 61/65
1070	VITALICIO 66/70
1100	SOCIO HONORARIO
1101	MASTER
1102	CC FAMILY GOLD
1103	NO SOCIO
1104	USUARIO TRIAR
1135	DOCENTE IGSM
*/

/*===============================================================================*/

SET @Id_Tipo_Cli_Actual = ISNULL((SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @Id_Cliente),0)

IF(@Modo_Debug = 1)
BEGIN
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Cod. Categoria Actual: ' + CONVERT(VARCHAR(10), @Id_Tipo_Cli_Actual)
	END
END

IF (@Id_Tipo_Cli_Actual IN (1007, 1008, 1012, 1013, 1014, 1016, 1017, 1104,1135))
BEGIN
	SET @Flag_Categ_Actual_Usuario = 1
	
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Tipo Categ. Actual: USUARIO'
	END
END
ELSE
BEGIN
	SET @Flag_Categ_Actual_Usuario = 0
	
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Tipo Categ. Actual: NO USUARIO'
	END		
END

/*===============================================================================*/
/*05/04/2017: Victor nos indicó que la categoria anterior se base en la categoria que tenga el día anterior*/
SET @Clientes_Hist_Item_Anterior = ISNULL((SELECT MAX(Item) FROM Clientes_Hist WHERE Id_Cliente = @Id_Cliente AND Fecha<DATEADD(dd,-1,GETDATE())),0)

IF (@Clientes_Hist_Item_Anterior = 0)
BEGIN
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Socio Nuevo. Sale del SP: SP_Clientes_Validar'		
	END
	RETURN	ISNULL(@Clientes_Hist_Item_Anterior,0)	
END


/*===============================================================================*/

SET @Id_Tipo_Cli_Anterior = ISNULL((SELECT Id_Tipo_Cli FROM Clientes_Hist WHERE Id_Cliente = @Id_Cliente AND Item = @Clientes_Hist_Item_Anterior),0)
IF(@Modo_Debug = 1)
BEGIN
	PRINT 'Cod. Categoria Anterior: ' + CONVERT(VARCHAR(10), @Id_Tipo_Cli_Anterior) 
END

IF (@Id_Tipo_Cli_Anterior IN (10/*ACCESO MASTER*/, 1018/*INVITADOS*/, 1103/*NO SOCIO*/, 1004/*ACOMPAÑANTE*/, 1134/*BICICLETA*/))
BEGIN
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Socio Tipo Acompañante. Sale del SP: SP_Clientes_Validar'		
	END
	RETURN	ISNULL(@Id_Tipo_Cli_Anterior,0)	
END


/*===============================================================================*/

IF (@Id_Tipo_Cli_Actual = @Id_Tipo_Cli_Anterior)
BEGIN
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'La Categoria Actual coincide con la anterior. Sale del SP: SP_Clientes_Validar'
	END
	RETURN	ISNULL(@Id_Tipo_Cli_Actual,0)	
END

/*===============================================================================*/

IF (@Id_Tipo_Cli_Anterior IN (1007, 1008, 1012, 1013, 1014, 1016, 1017, 1104))
BEGIN
	SET @Flag_Categ_Anterior_Usuario = 1
	
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Tipo Categ. Anterior: USUARIO'
	END
END
ELSE
BEGIN
	SET @Flag_Categ_Anterior_Usuario = 0
	
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Tipo Categ. Anterior: NO USUARIO'
	END
END

/*===============================================================================*/

IF(@Flag_Categ_Anterior_Usuario = 0 AND @Flag_Categ_Actual_Usuario = 1)
BEGIN
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Condicion: Categoria Anterior Tipo:"Usuario" y Categoria Actual Tipo:"No Usuario" CUMPLIDA'
	END
	
	SET @Fecha_Ult_Cuota_Paga = ISNULL((SELECT Ult_Cuota_Paga FROM Clientes WHERE Id_Cliente = @Id_Cliente),'19000101')
	
	SET @Anio_Pasado = DATEADD(yy, -1, dbo.SF_PrincipioMes(GETDATE()))
	
	SET @Cant_Meses_Desde_UCP = DATEDIFF(mm,@Anio_Pasado, @Fecha_Ult_Cuota_Paga)
	
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Cantidad Meses Transcurridos desde UCP: ' + CONVERT(VARCHAR(10), @Cant_Meses_Desde_UCP)
	END
	
	IF(@Cant_Meses_Desde_UCP <= 12)
	BEGIN
		IF(@Modo_Debug = 1)
		BEGIN
			PRINT 'NO Pasó mas de un año'
		END
		
		UPDATE Clientes SET Id_Tipo_Cli = @Id_Tipo_Cli_Anterior WHERE Id_Cliente = @Id_Cliente
		/*Devuelve un error. Se dejan espacios para que en el mensaje de error del sistema no aparezca nada mas*/
		RAISERROR (N'OPERACIÓN INVÁLIDA. Debe transcurrir más de un año para el cambio de Categoria.                                                                                                                                                                              ', 16, 1);
	END
END
ELSE
BEGIN
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Condicion: Categoria Anterior Tipo:"Usuario" y Categoria Actual Tipo:"No Usuario" NO Cumplida'
		PRINT 'Sale del SP: SP_Clientes_Validar'
	END
END

IF(@Modo_Debug = 1)
BEGIN
	PRINT 'Fin de ejecucion: SP_Clientes_Validar'
	PRINT '----------------------------------------------------------------'
END
GO

CREATE PROCEDURE [dbo].[SP_Contrato_CAguin_Cli] @pId_Cliente INT 
AS

/*Declaracion de Variables*/
DECLARE @Actualizar		TINYINT
DECLARE @Existe			INT
DECLARE @Activo			TINYINT 
DECLARE @Id_Prod		CHAR(14) 
DECLARE @Id_Prod_Ant	CHAR(14) 
DECLARE @Id_Tarjeta		VARCHAR(10)
DECLARE @Id_Banco		SMALLINT
DECLARE @Tar_Nro		VARCHAR(25)
DECLARE @Id_Tipo_Cli	SMALLINT
DECLARE @Id_Lista_Precio INT
/*FIN Declaracion de Variables*/

PRINT '----------------------------------------------------------------'
PRINT 'Inicio de ejecucion: SP_Contrato_CAguin_Cli'

PRINT 'Generacion del Contrato del Socio: ' + CONVERT(VARCHAR(10), @pId_Cliente)

/*Cliente no definido o varios*/
IF (@pId_Cliente <= 1)
BEGIN
	PRINT 'Socio NO DEFINIDO o VARIOS. Sale del SP'
	RETURN
END
/*FIN Cliente no definido o varios*/

/*----------------------------------------------------------------------*/

SET @Id_Tipo_Cli = (dbo.SF_Categ(@pId_Cliente, GETDATE()))
PRINT 'Categoria del Socio: ' + CONVERT(VARCHAR(10), @Id_Tipo_Cli)

/*Categorias exceptuadas de Contratos*/
IF (@Id_Tipo_Cli IN (	10, 1004, 1005, 1006, 1007, 1008, 1010, 1011, 1012, 1013, 
						1014, 1015, 1016, 1017, 1018, 1019, 1100, 1101, 1102, 1103,
						1104, 1105, 1106, 1107, 1108, 1109, 1110, 1111, 1112, 1113,
						1123))
BEGIN
	/* CATEGORIAS EXCEPTUADAS DE CONTRATOS:    
	* 10	ACCESO MASTER					1004	ACOMPAÑANTE		
	* 1005	CONYUGUE EMPLEADO				1006	EMPLEADO
	* 1007	USUARIO GEBA GYM				1008	USUARIO
	* 1010	VITALICIO + 71					1011	RESOLUCION 95
	* 1012	USUARIO RCA						1013	USUARIO AFIP
	* 1014	USUARIO J.N.					1015	CONCESIONARIO
	* 1016	USUARIO S.M. / JM				1017	USUARIO +75
	* 1018	INVITADOS						1019	COLEGIOS
	* 1019	COLEGIOS						1100	SOCIO HONORARIO
	* 1101	MASTER							1102	CC FAMILY GOLD
	* 1103	NO SOCIO						1104	USUARIO TRIAR
	* 1105	REFERENTE						1106	PRE INFANTIL
	* 1107	USUARIO ASHIWEA					1108	USUARIO ASHIWEA / GIRE
	* 1109	USUARIO ASHIWEA GOLD MAYOR		1110	USUARIO ASHIWEA GOLD MENOR
	* 1111	USUARIO PROMO VERANO MAYOR		1112	USUARIO PROMO VERANO MENOR
	* 1113	VISITA
	*/

	SET @Existe = ISNULL((	SELECT MAX(Id_Contrato) 
						FROM Contratos 
						WHERE 
						Id_Cliente = @pId_Cliente 
						AND Activo = 1 
						AND Id_Tipo_Con = 23 /*Contrato Aguinaldo Automatico*/
						AND Fecha_Desde <= GETDATE()
						AND (Fecha_Hasta >= GETDATE() OR Fecha_Hasta IS NULL))
					,0)
					
	IF(@Existe <> 0)
	BEGIN
		PRINT 'Contrato Aguinaldo Automatico Actual. Se debe dar de baja: ' + CONVERT(VARCHAR(10), @Existe)
	
		UPDATE Contratos
		SET
		Activo = 0,
		Fecha_Baja = GETDATE(),
		Fecha_Hasta = GETDATE(),
		Id_Motivo_Est = 1,
		Flag_Sistema = 1
		WHERE 
		Id_Contrato = @Existe
	END
	
	RETURN
END
/*FIN Categorias exceptuadas de Contratos*/

SET @Actualizar = 0

/*Contrato CS Automatico*/
SET @Existe = ISNULL((	SELECT MAX(Id_Contrato) 
						FROM Contratos 
						WHERE 
						Id_Cliente = @pId_Cliente 
						AND Activo = 1 
						AND Id_Tipo_Con = 23 /*Contrato Aguinaldo Automatico*/
						AND Fecha_Desde <= GETDATE()
						AND (Fecha_Hasta >= GETDATE() OR Fecha_Hasta IS NULL))
					,0)
PRINT 'Contrato Aguinaldo Automatico Actual: ' + CONVERT(VARCHAR(10), @Existe)

/*----------------------------------------------------------------------*/

/*Datos del Cliente*/
SET @Activo = (SELECT ISNULL(Activo, 0) FROM Clientes WHERE Id_Cliente = @pId_Cliente)
PRINT 'Socio Activo: ' + CONVERT(VARCHAR(10), @Activo)

SET @Id_Lista_Precio = 0

SET @Id_Lista_Precio = (SELECT ISNULL(Id_Lista_Precio, 0) FROM Clientes WHERE Id_Cliente = @pId_Cliente)
PRINT 'Lista de Precio: ' + CONVERT(VARCHAR(10), @Id_Lista_Precio)

SET @Id_Prod = 'CAGUIN'
PRINT 'Cód. Producto de Aguinaldo Actual: ' + @Id_Prod

/*------------------------------------------------------------------*/

IF (ISNULL(@Existe,0) = 0)
BEGIN
	PRINT 'NO existe contrato Aguinaldo automatico'
	
	IF (@Activo = 1)
	BEGIN
		SET @Actualizar = 1
		PRINT 'Socio Activo, hay que actualizar'
	END
END
ELSE
BEGIN
	PRINT 'Existe un Contrato Aguinaldo Automatico previamente cargado. Cód Contrato: ' + CONVERT(VARCHAR(10), @Existe)
	
    SET @Id_Prod_Ant = ISNULL((SELECT Id_Producto FROM Contratos_Prod WHERE Id_Contrato = @Existe and Item = 1),'')
	PRINT 'Cód. Producto del Contrato Anterior: ' + @Id_Prod_Ant
	
	SET @Id_Tarjeta = (SELECT ISNULL(Id_Tarjeta, '') FROM Contratos WHERE Id_Contrato = @Existe)
	SET @Id_Banco	= (SELECT ISNULL(Id_Banco, 0) FROM Contratos WHERE Id_Contrato = @Existe)
	SET @Tar_Nro	= (SELECT ISNULL(Tar_Nro, '') FROM Contratos WHERE Id_Contrato = @Existe)
	PRINT 'Tipo de Tarjeta de Crédito/Debito Bancario: ' + @Id_Tarjeta + ' Tarjeta Nro.: ' + @Tar_Nro + ' Cód. de Banco: ' + CONVERT(VARCHAR(10), @Id_Banco)
		                  
	IF ((@Activo = 0) OR (@Id_Prod_Ant <> @Id_Prod))
	BEGIN	
		SET @Actualizar = 1

		UPDATE Contratos 
		SET 
			Activo = 0,
			Fecha_Baja = GETDATE(),
			Fecha_Hasta = GETDATE(),
			Id_Motivo_Est = 1,
			Flag_Sistema = 1
		WHERE 
			Id_Contrato = @Existe

		PRINT 'Se pone en Inactivo el Contrato Aguinaldo Automatico. Cód: ' + CONVERT(VARCHAR(10), @Existe)			
	END
	ELSE
	BEGIN
		PRINT 'No hubo cambios, no se actualiza el contrato'
	END
END

/*----------------------------------------------------------------------*/

IF ((@Activo = 1) AND (@Actualizar = 1))
BEGIN  

    SET @Existe = (SELECT ISNULL(MAX(Id_Contrato),0) + 1 FROM Contratos)
    PRINT 'Nro. Contrato a crear: ' + CONVERT(VARCHAR(10), @Existe)

    /*CONTRATO*/
	INSERT INTO Contratos
				(Id_Contrato,	Id_Cliente,			Id_Tipo_Con,
				Fecha_Alta,		Fecha_Desde,		Activo,
				Id_Tipo_Cbte,	Id_Lista_Precio,	Flag_Sistema,
				Id_Tarjeta,		Id_Banco,			Tar_Nro)
	VALUES
				(@Existe,		@pId_Cliente,		23/*Aguinaldo Automatica*/,
				GETDATE(),		GETDATE(),			1/*Activo*/,
				'RCOM',			@Id_Lista_Precio,	1/*Flag_Sistema*/,
				 @Id_Tarjeta,	@Id_Banco,			@Tar_Nro)
	PRINT 'Se creó un nuevo contrato. Nro: ' + CONVERT(VARCHAR(10), @Existe)
    
	 /*CONTRATOS PROD (ITEMS)*/   

	/*Item: Producto especifico de categoria*/       
	INSERT INTO Contratos_Prod 
				(Id_Contrato,	Item,				Id_Producto,
				Precio,			Flag_Facturable,	Cantidad)
	VALUES
				(@Existe,		1,					@Id_Prod,
				0,				1,					1)
	PRINT 'Se creó el Item: ' + @Id_Prod	
END 

PRINT 'Fin de ejecucion: SP_Contrato_CAguin_Cli'
PRINT '----------------------------------------------------------------'
GO



CREATE PROCEDURE [dbo].[SP_Contrato_Cli] @Cli INT 
AS

/*Declaracion de Variables*/
DECLARE @Actualizar		TINYINT
DECLARE @Existe			INT
DECLARE @ExisteManual	INT
DECLARE @Activo			TINYINT 
DECLARE @Id_Prod		VARCHAR(14)
DECLARE @Id_Prod_Ant	VARCHAR(14)
DECLARE @Id_Tipo_Cli	INT 
DECLARE @Cab_Grupo		INT
DECLARE @Flag_Facturable INT,@Flag_Facturable_ant INT
DECLARE @Lista_Precio	INT
DECLARE @Id_Tarjeta		VARCHAR(10)
DECLARE @Id_Banco		SMALLINT
DECLARE @Tar_Nro		VARCHAR(25)	
DECLARE @cond_vta       CHAR(10)
DECLARE @Tiene_Tipo_Con	SMALLINT
DECLARE @Id_Prod_NSC	VARCHAR(14)
DECLARE @Es_Vitalicio	SMALLINT


/*FIN Declaracion de Variables*/
declare @Lista_titular int
/*----------------------------------------------------------------------*/

PRINT '----------------------------------------------------------------'
PRINT 'Inicio de ejecucion: SP_Contrato_Cli'

PRINT 'Generacion del Contrato del Socio: ' + CONVERT(VARCHAR(10), @Cli)

/*Cliente no definido o varios*/
IF (@Cli <= 1)
BEGIN
	PRINT 'Socio NO DEFINIDO o VARIOS. Sale del SP'
	RETURN
END
/*FIN Cliente no definido o varios*/

/*----------------------------------------------------------------------*/

SET @Actualizar = 0

SET @Id_Tipo_Cli = (SELECT MAX(Id_Tipo_Cli) FROM Clientes WHERE Id_Cliente = @Cli)   --Categoria

PRINT 'Categoria del Socio: ' + CONVERT(VARCHAR(10), @Id_Tipo_Cli)

IF ((@Id_Tipo_Cli < 1000)OR (@Id_Tipo_Cli = 1129 /*CAT PRUEBA*/) OR (@Id_Tipo_Cli = 1018 /*invitado*/) OR (@Id_Tipo_Cli = 1103 /*no socio*/) OR (@Id_Tipo_Cli = 1111 /*USUARIO PROMO VERANO MAYOR*/) OR (@Id_Tipo_Cli = 1112 /*USUARIO PROMO VERANO MENOR*/) OR (@Id_Tipo_Cli = 1113 /*Visita*/)OR (@Id_Tipo_Cli = 1114 /*INVITADOS SC*/) OR (@Id_Tipo_Cli = 1134 /*BICICLETA*/))
BEGIN
   RETURN 
END

SET @Cab_Grupo = ISNULL((SELECT Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @Cli), 0)

if @Cab_Grupo  <> 0
   SET @Lista_Precio = ISNULL((SELECT MAX(Id_Lista_Precio) FROM Clientes WHERE Id_Cliente = @Cab_Grupo), 0)
else
   SET @Lista_Precio = ISNULL((SELECT MAX(Id_Lista_Precio) FROM Clientes WHERE Id_Cliente = @Cli), 0)   
   
PRINT 'Lista de Precio del Socio: ' + CONVERT(VARCHAR(10), @Lista_Precio)
/*Contrato CS Automatico*/
SET @Existe = ISNULL((	SELECT MAX(Id_Contrato) 
						FROM Contratos 
						WHERE 
						Id_Cliente = @Cli 
						AND Activo = 1 
						AND Id_Tipo_Con = 1 /*Contrato CS Automatico*/
						AND Fecha_Desde <= GETDATE()
						AND (Fecha_Hasta >= GETDATE() OR Fecha_Hasta IS NULL))
					,0)
PRINT 'Contrato CS Automatico Actual: ' + CONVERT(VARCHAR(10), @Existe)

/*Contrato CS Manual*/
SET @ExisteManual = ISNULL((	SELECT MAX(Id_Contrato) 
								FROM Contratos 
								WHERE
								Id_Cliente = @Cli 
								AND Activo = 1 
								AND Id_Tipo_Con = 2 /*Contrato CS Manual*/
								AND Fecha_Desde <= GETDATE()
								AND (Fecha_Hasta >= GETDATE() OR Fecha_Hasta IS NULL))
							,0)
PRINT 'Contrato CS Manual Actual: ' + CONVERT(VARCHAR(10), @ExisteManual)

/*----------------------------------------------------------------------*/

/*Datos del Cliente*/
SET @Activo = ISNULL((SELECT MAX(Activo) FROM Clientes WHERE Id_Cliente = @Cli), 0)
PRINT 'Socio Activo: ' + CONVERT(VARCHAR(10), @Activo)


IF (@Lista_Precio = 0)
BEGIN
	/*Si no tiene lista de Precio salgo del SP*/
	set @Lista_Precio = 1
	PRINT 'El Socio no tiene lista de precio, se toma la lista de precio 1'
END

SET @Id_Prod = dbo.SF_Prod(@Cli,GETDATE())
PRINT 'Cód. Producto correspondiente a las condiciones del Socio: ' + @Id_Prod

/*----------------------------------------------------------------------*/
/*Si es un referente se le da de baja a los contratos de C.S. existentes, si no existe contrato sale para no generarle contrato*/
IF(@Id_Prod = '1425'/*Referente*/)
BEGIN
	IF (@Existe <> 0)
	BEGIN
		UPDATE Contratos 
		SET 
		Activo = 0, 
		Fecha_Baja = GETDATE(), 
		Fecha_Hasta = GETDATE(), 
		Id_Motivo_Est = 1 
		WHERE
		Id_Contrato = @Existe
	END
	ELSE
	BEGIN
		RETURN
	END
END

/*----------------------------------------------------------------------*/

/*----------------------------------------------------------------------*/
/*Si es un Socio CPCE se le da de baja a los contratos de C.S. existentes, si no existe contrato sale para no generarle contrato ticket#16671*/
IF(@Id_Prod = 'USUCPCE'/*USUARIO CPCE*/)
BEGIN
	IF (@Existe <> 0)
	BEGIN
		UPDATE Contratos 
		SET 
		Activo = 0, 
		Fecha_Baja = GETDATE(), 
		Fecha_Hasta = GETDATE(), 
		Id_Motivo_Est = 1 
		WHERE
		Id_Contrato = @Existe
	END
	ELSE
	BEGIN
		RETURN
	END
END

/*----------------------------------------------------------------------*/
	
/*Cabecera de Grupo*/

IF (@Cab_Grupo = 0)
BEGIN
	PRINT 'El Socio: ' + CONVERT(VARCHAR(10), @Cli) + ' es CABECERA de un Grupo Familiar'
	SET @Cab_Grupo = @Cli
	PRINT 'Es Facturable (Cabecera de Grupo Familiar)'
	SET @Flag_Facturable = 1
END
ELSE
BEGIN
    PRINT 'El Socio: ' + CONVERT(VARCHAR(10), @Cli) + ' es INTEGRANTE de un Grupo Familiar'
    set @cond_vta = isnull((select Id_Cond_Vta from Clientes where Id_Cliente = @Cab_Grupo ),0)
    print @cond_vta
	IF @cond_vta <> 'GFCP'
    BEGIN
     	PRINT 'NO es Facturable (Integrante de Grupo Familiar)'
		SET @Flag_Facturable = 0
	END
	ELSE
	BEGIN
	    PRINT 'ES Facturable  xq la condicion de venta es distinto de GFCP ose se cobra por separado'
		SET @Flag_Facturable = 1 
	END

END

/*----------------------------------------------------------------------*/


IF (ISNULL(@Existe,0) = 0)
BEGIN
	PRINT 'NO existe contrato CS automatico'
 
	IF (@Activo = 1)
	BEGIN
		SET @Actualizar = 1
		PRINT 'Socio Activo, hay que actualizar'
	END 
END
ELSE
BEGIN
	PRINT 'Existe un Contrato Automatico'
	SET @Id_Prod_Ant = ISNULL((SELECT Id_Producto FROM Contratos_Prod WHERE Id_Contrato = @Existe AND Item = 2 ),'')
	PRINT 'Cód. Producto del Contrato Anterior: ' + @Id_Prod_Ant

	SET @Flag_Facturable_ant = ISNULL((SELECT Flag_Facturable FROM Contratos_Prod WHERE Id_Contrato = @Existe AND Item = 1 ),0)
	PRINT 'Facturable anterior:' + CAST(@Flag_Facturable_ant AS VARCHAR(10))
	
	SET @Id_Tarjeta = ISNULL((SELECT Id_Tarjeta FROM Contratos WHERE Id_Contrato = @Existe),'')
	SET @Id_Banco	= ISNULL((SELECT Id_Banco FROM Contratos WHERE Id_Contrato = @Existe),0)
	SET @Tar_Nro	= ISNULL((SELECT Tar_Nro FROM Contratos WHERE Id_Contrato = @Existe),'')
	PRINT 'Tipo de Tarjeta de Crédito/Debito Bancario: ' + @Id_Tarjeta + ' Tarjeta Nro.: ' + @Tar_Nro + ' Cód. de Banco: ' + CONVERT(VARCHAR(10), @Id_Banco)
	
	IF ((@Activo = 0) OR (ISNULL(@ExisteManual,0) <> 0) OR (@Id_Prod_Ant <> @Id_Prod) 
	                  OR (@Flag_Facturable_ant <> @Flag_Facturable))
	BEGIN
		PRINT 'El Socio esta INACTIVO o existe CONTRATO CS MANUAL o CAMBIO PRODUCTO o CAMBIO TARJETA' 
		SET @Actualizar = 1
  
		UPDATE Contratos 
		SET 
			Activo = 0,
			Fecha_Baja = GETDATE(),
			Fecha_Hasta = GETDATE(),
			Id_Motivo_Est =1,
			Flag_Sistema = 1
		WHERE 
			Id_Contrato = @Existe
  
		PRINT 'Se pone en Inactivo el Contrato CS Automatico. Cód: ' + CONVERT(VARCHAR(10), @Existe)
	END
END

/*----------------------------------------------------------------------*/


IF ((@Activo = 1) AND (@Actualizar = 1) AND (@ExisteManual = 0))
BEGIN
	PRINT 'Se crea un nuevo contrato (Socio Activo, hay que actualizar y no existe contrato CS Manual)'
	
    SET @Existe = (SELECT ISNULL(MAX(Id_Contrato),0) + 1  FROM Contratos)
    PRINT 'Nro. Contrato a crear: ' + CONVERT(VARCHAR(10), @Existe)
    
    /*CONTRATO*/
	INSERT INTO Contratos
				(Id_Contrato,	Id_Cliente,		Id_Tipo_Con,
				Fecha_Alta,		Fecha_Desde,	Activo,
				Id_Tipo_Cbte,	Id_Lista_Precio, Flag_Sistema,
				Id_Tarjeta,		Id_Banco,		Tar_Nro,
				Flag_fact_titular)
	VALUES
				(@Existe,		@Cli,			1/*CS Automatica*/,
				GETDATE(),		GETDATE(),		1/*Activo*/,
				'CUP',			@Lista_Precio,	1/*Flag_Sistema*/,
				 @Id_Tarjeta,	@Id_Banco,		@Tar_Nro,
				 1)
	PRINT 'Se creó un nuevo contrato. Nro: ' + CONVERT(VARCHAR(10), @Existe)
 
     
	 /*CONTRATOS PROD (ITEMS)*/
	 /*Item: CS*/      
	INSERT INTO Contratos_Prod 
				(Id_Contrato,	Item,				Id_Producto,
				Precio,			Flag_Facturable,	Cantidad)
	VALUES
				(@Existe,		1,					'CS',
				0,				@Flag_Facturable,	1)
	PRINT 'Se creó el Item: CS'
        
	/*Item: Producto especifico de categoria*/       
	INSERT INTO Contratos_Prod 
				(Id_Contrato,	Item,				Id_Producto,
				Precio,			Flag_Facturable,	Cantidad)
	VALUES
				(@Existe,		2,					@Id_Prod,
				0,				0,					1)
	PRINT 'Se creó el Item: ' + @Id_Prod
END

/*Genera contrato de Aguinaldo*/
-- EXEC dbo.SP_Contrato_CAguin_Cli @Cli

/*----------------------------------------------------------------------------*/
/*Se agrega un contrato 9 a los vitalicios con el producto natación sin Cargo 18/11/2020*/
PRINT 'Inicio de contrato 9 para vitalicio '
SET @Es_Vitalicio = ISNULL((SELECT 1 FROM Clientes WHERE id_Cliente= @Cli AND Id_tipo_Cli IN (1010,1020,1055,1060,1065,1070,1125)),0)	 
IF(@Es_Vitalicio = 1)
BEGIN	
	
	SET @Tiene_Tipo_Con = ISNULL((SELECT 1 FROM Contratos c, Contratos_Prod p 
							WHERE c.Id_contrato = p.Id_contrato 
							AND c.id_Tipo_con=9 
							AND c.activo=1
							AND c.Id_cliente=@Cli 
							AND p.Id_Producto='1485'/*Natación Sin Cargo*/),0)
							
	SET @Id_Prod_NSC = '1485'						
	
	IF(@Tiene_Tipo_Con = 0)
	BEGIN
		PRINT 'Se crea un nuevo contrato (Socio Vitalicio, hay que actualizar y no existe contrato Prod natación)'
	
		SET @Existe = (SELECT ISNULL(MAX(Id_Contrato),0) + 1  FROM Contratos)
		PRINT 'Nro. Contrato a crear: ' + CONVERT(VARCHAR(10), @Existe)
	
		 /*CONTRATO*/
		INSERT INTO Contratos
					(Id_Contrato,	Id_Cliente,		Id_Tipo_Con,
					Fecha_Alta,		Fecha_Desde,	Activo,
					Id_Tipo_Cbte,	Id_Lista_Precio, Flag_Sistema,
					Id_Tarjeta,		Id_Banco,		Tar_Nro,
					Fecha_Hasta)
		VALUES
					(@Existe,		@Cli,			9/*CS Vitalicio*/,
					GETDATE(),		GETDATE(),		1/*Activo*/,
					'ND',			@Lista_Precio,	0/*Flag_Sistema*/,
					 @Id_Tarjeta,	@Id_Banco,		@Tar_Nro,
					 '20501231')
		PRINT 'Se creó un nuevo contrato. Nro: ' + CONVERT(VARCHAR(10), @Existe)
 
     
	 /*CONTRATOS PROD (ITEMS)*/
       
	/*Item: Producto especifico de categoria*/       
	INSERT INTO Contratos_Prod 
				(Id_Contrato,	Item,				Id_Producto,
				Precio,			Flag_Facturable,	Cantidad)
	VALUES
				(@Existe,		1,					@Id_Prod_NSC,
				0,				1,					1)
	PRINT 'Se creó el Item: ' + @Id_Prod_NSC
	END
END
/*----------------------------------------------------------------------------*/


PRINT 'Fin de ejecucion: SP_Contrato_Cli'
PRINT '----------------------------------------------------------------'
GO

CREATE PROCEDURE [dbo].[SP_Contrato_Cli_Conyuge] @Cli INT 
AS

/*Declaracion de Variables*/
DECLARE @Id_Cliente		INT
DECLARE @Existe			INT
DECLARE @ExisteManual	INT
DECLARE @Activo			TINYINT 
DECLARE @Id_Tipo_Cli	INT 
DECLARE @Lista_Precio	INT
DECLARE @Id_Cli_relac	INT
DECLARE @Id_Cliente_Ref	INT
DECLARE @Fecha_Alta		DATETIME
DECLARE @Fecha_Alta_REF DATETIME
DECLARE @Fecha_Hasta	DATETIME
/*FIN Declaracion de Variables*/
/*----------------------------------------------------------------------*/

PRINT '----------------------------------------------------------------'
PRINT 'Inicio de ejecucion: SP_Contrato_Cli_Conyuge'

PRINT 'Generacion del Contrato Descuento Socio Conyuge: ' + CONVERT(VARCHAR(10), @Cli)

/*Cliente no definido o varios*/
IF (@Cli <= 1)
BEGIN
	PRINT 'Socio NO DEFINIDO o VARIOS. Sale del SP'
	RETURN
END
/*FIN Cliente no definido o varios*/

SET @Lista_Precio = ISNULL((SELECT MAX(Id_Lista_Precio) FROM Clientes WHERE Id_Cliente = @Cli), 0) 

/*----------------------------------------------------------------------*/


SET @Id_Tipo_Cli = (SELECT MAX(Id_Tipo_Cli) FROM Clientes WHERE Id_Cliente = @Cli)   --Categoria
SET @Id_Cli_relac = (SELECT ISNULL(Id_Cli_relac,0) FROM Clientes WHERE Id_Cliente = @Cli)   --Relacion
SET @Id_Cliente_Ref = (SELECT ISNULL(Id_Cliente_Ref,0) FROM Clientes WHERE Id_Cliente = @Cli)   --Titular
SET @Fecha_Alta  = (SELECT Fecha_Alta FROM Clientes WHERE Id_Cliente = @Cli) --Fecha alta
SET @Fecha_Alta_REF  = (SELECT Fecha_Alta FROM Clientes WHERE Id_Cliente = @Id_Cliente_Ref) -- 

PRINT 'Relacion del Socio: ' + CONVERT(VARCHAR(10), @Id_Cli_relac)
PRINT 'Fecha Alta del Socio: ' + CONVERT(VARCHAR(10), @Fecha_Alta)
PRINT 'Fecha Alta del Socio REF: ' + CONVERT(VARCHAR(10), @Fecha_Alta_REF)

IF (@Fecha_Alta >= '20220218' AND @Fecha_Alta <= '20220417' AND @Id_Cli_relac = 2 AND @Id_Cliente_Ref > 0 AND CONVERT(VARCHAR(10),@Fecha_Alta_REF,105) = CONVERT(VARCHAR(10),@Fecha_Alta,105))
BEGIN
   SET @Existe = ISNULL((	SELECT MAX(Id_Contrato) 
						FROM Contratos 
						WHERE 
						Id_Cliente = @Cli 
						AND Activo = 1 
						AND Id_Tipo_Con = 10
						AND Fecha_Desde <= GETDATE()
						AND (Fecha_Hasta >= GETDATE() OR Fecha_Hasta IS NULL))
					,0)
PRINT 'Contrato de Descuento de CS Actual: ' + CONVERT(VARCHAR(10), @Existe)
	IF(@Existe > 0)
	BEGIN
	UPDATE Contratos 
		SET 
			Activo = 0,
			Fecha_Baja = GETDATE(),
			Fecha_Hasta = GETDATE(),
			Id_Motivo_Est =1,
			Flag_Sistema = 1
		WHERE 
			Id_Contrato = @Existe
   END

  SET @Lista_Precio = ISNULL((SELECT MAX(Id_Lista_Precio) FROM Clientes WHERE Id_Cliente = @Cli), 0)   
   
PRINT 'Lista de Precio del Socio: ' + CONVERT(VARCHAR(10), @Lista_Precio)
/*Contrato CS Automatico*/
SET @Existe = ISNULL((	SELECT MAX(Id_Contrato) 
						FROM Contratos 
						WHERE 
						Id_Cliente = @Cli 
						AND Activo = 1 
						AND Id_Tipo_Con = 1
						AND Fecha_Desde <= GETDATE()
						AND (Fecha_Hasta >= GETDATE() OR Fecha_Hasta IS NULL))
					,0)
PRINT 'Contrato CS Automatico Actual: ' + CONVERT(VARCHAR(10), @Existe)

	UPDATE CONTRATOS_PROD SET FLAG_FACTURABLE = 0 WHERE ID_CONTRATO = @Existe

/*Contrato CS Manual*/
SET @ExisteManual = ISNULL((	SELECT MAX(Id_Contrato) 
								FROM Contratos 
								WHERE
								Id_Cliente = @Cli 
								AND Activo = 1 
								AND Id_Tipo_Con = 2 /*Contrato CS Manual*/
								AND Fecha_Desde <= GETDATE()
								AND (Fecha_Hasta >= GETDATE() OR Fecha_Hasta IS NULL))
							,0)
PRINT 'Contrato CS Manual Actual: ' + CONVERT(VARCHAR(10), @ExisteManual)


/*----------------------------------------------------------------------*/

/*Datos del Cliente*/
SET @Activo = ISNULL((SELECT MAX(Activo) FROM Clientes WHERE Id_Cliente = @Cli), 0)
PRINT 'Socio Activo: ' + CONVERT(VARCHAR(10), @Activo)

/*Fecha hasta un año desde la alta ticket #780*/
SET @Fecha_Hasta = DATEADD(YEAR,1,GETDATE())

/*----------------------------------------------------------------------*/
	
    SET @Existe = (SELECT ISNULL(MAX(Id_Contrato),0) + 1  FROM Contratos)
    PRINT 'Nro. Contrato a crear: ' + CONVERT(VARCHAR(10), @Existe)
    
    /*CONTRATO*/
	INSERT INTO Contratos
				(Id_Contrato,	Id_Cliente,		Id_Tipo_Con,
				Fecha_Alta,		Fecha_Desde,	Fecha_Hasta,
				Activo,
				Id_Tipo_Cbte,	Id_Lista_Precio, Flag_Sistema,
				Id_Tarjeta,		Id_Banco,		Tar_Nro,
				Porc_Bonif)
	VALUES
				(@Existe,		@Cli,			10/*Descuento CS*/,
				GETDATE(),		GETDATE(),		@Fecha_Hasta,
				1/*Activo*/,
				'ND',			@Lista_Precio,	1/*Flag_Sistema*/,
				 '',			'',				0,
				 100)
	PRINT 'Se creó un nuevo contrato. Nro: ' + CONVERT(VARCHAR(10), @Existe)
 
	 /*CONTRATOS PROD (ITEMS)*/
       
	/*Item: Producto especifico de categoria*/       
/*	INSERT INTO Contratos_Prod 
				(Id_Contrato,	Item,				Id_Producto,
				Precio,			Flag_Facturable,	Cantidad)
	VALUES
				(@Existe,		1,					'',
				0,				1,					1)*/
END



PRINT 'Fin de ejecucion: SP_Contrato_Cli_Conyuge'
PRINT '----------------------------------------------------------------'
GO



CREATE PROCEDURE [dbo].[SP_Contrato_Cli_REF] @Cli INT 
AS

/*Declaracion de Variables*/

DECLARE @Id_Cli	INT 
DECLARE @Cab_Grupo		INT

/*FIN Declaracion de Variables*/

/*----------------------------------------------------------------------*/


SET @Cab_Grupo = ISNULL((SELECT Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @Cli), 0)

if @Cab_Grupo = 0 AND @Cli > 1
begin
	DECLARE GF_CUR CURSOR FOR
		SELECT ID_CLIENTE  FROM CLIENTES WHERE ID_CLIENTE_REF = @Cli
		
	OPEN GF_CUR 		
	FETCH NEXT FROM GF_CUR INTO @Id_Cli
	WHILE @@FETCH_STATUS = 0
	begin
		   EXEC SP_Contrato_Cli @Id_Cli
		   FETCH NEXT FROM GF_CUR INTO @Id_Cli
	END	 
	CLOSE GF_CUR
	DEALLOCATE GF_CUR
end
GO

CREATE PROCEDURE [dbo].[SP_Contrato_Cli_Vitalicio] @Cli INT 
AS

/*Declaracion de Variables*/
DECLARE @Actualizar		TINYINT
DECLARE @Existe			INT
DECLARE @ExisteManual	INT
DECLARE @Activo			TINYINT 
DECLARE @Id_Prod		VARCHAR(14)
DECLARE @Id_Prod_Ant	VARCHAR(14)
DECLARE @Id_Tipo_Cli	INT 
DECLARE @Cab_Grupo		INT
DECLARE @Flag_Facturable INT,@Flag_Facturable_ant INT
DECLARE @Lista_Precio	INT
DECLARE @Id_Tarjeta		VARCHAR(10)
DECLARE @Id_Banco		SMALLINT
DECLARE @Tar_Nro		VARCHAR(25)	
DECLARE @cond_vta       CHAR(10)
/*FIN Declaracion de Variables*/
declare @Lista_titular int
/*----------------------------------------------------------------------*/

PRINT '----------------------------------------------------------------'
PRINT 'Inicio de ejecucion: SP_Contrato_Cli_vitalicio'

PRINT 'Generacion del Contrato del Socio Vitalicio + 71: ' + CONVERT(VARCHAR(10), @Cli)

/*Cliente no definido o varios*/
IF (@Cli <= 1)
BEGIN
	PRINT 'Socio NO DEFINIDO o VARIOS. Sale del SP'
	RETURN
END
/*FIN Cliente no definido o varios*/

SET @Lista_Precio = ISNULL((SELECT MAX(Id_Lista_Precio) FROM Clientes WHERE Id_Cliente = @Cli), 0) 
IF (@Lista_Precio = 6/*GOLD*/)
BEGIN
	PRINT 'Socio GOLD Sale del Sp.'
	RETURN
END
/*----------------------------------------------------------------------*/

SET @Actualizar = 0

SET @Id_Tipo_Cli = (SELECT MAX(Id_Tipo_Cli) FROM Clientes WHERE Id_Cliente = @Cli)   --Categoria

PRINT 'Categoria del Socio: ' + CONVERT(VARCHAR(10), @Id_Tipo_Cli)

IF (@Id_Tipo_Cli NOT IN( 1010 /*VITALICIO + 71*/, 1012 /*Usuario RCA*/, 1017 /*Usuario +75*/))
BEGIN
   SET @Existe = ISNULL((	SELECT MAX(Id_Contrato) 
						FROM Contratos 
						WHERE 
						Id_Cliente = @Cli 
						AND Activo = 1 
						AND Id_Tipo_Con = 37 /*Contrato CS Voluntaria*/
						AND Fecha_Desde <= GETDATE()
						AND (Fecha_Hasta >= GETDATE() OR Fecha_Hasta IS NULL))
					,0)
PRINT 'Contrato CS Automatico Actual: ' + CONVERT(VARCHAR(10), @Existe)
	UPDATE Contratos 
		SET 
			Activo = 0,
			Fecha_Baja = GETDATE(),
			Fecha_Hasta = GETDATE(),
			Id_Motivo_Est =1,
			Flag_Sistema = 1
		WHERE 
			Id_Contrato = @Existe
   RETURN 
END

SET @Cab_Grupo = ISNULL((SELECT Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @Cli), 0)

if @Cab_Grupo  <> 0
  SET @Lista_Precio = ISNULL((SELECT MAX(Id_Lista_Precio) FROM Clientes WHERE Id_Cliente = @Cab_Grupo), 0)
else
  SET @Lista_Precio = ISNULL((SELECT MAX(Id_Lista_Precio) FROM Clientes WHERE Id_Cliente = @Cli), 0)   
   
PRINT 'Lista de Precio del Socio: ' + CONVERT(VARCHAR(10), @Lista_Precio)
/*Contrato CS Automatico*/
SET @Existe = ISNULL((	SELECT MAX(Id_Contrato) 
						FROM Contratos 
						WHERE 
						Id_Cliente = @Cli 
						AND Activo = 1 
						AND Id_Tipo_Con = 37 /*Contrato CS Voluntario*/
						AND Fecha_Desde <= GETDATE()
						AND (Fecha_Hasta >= GETDATE() OR Fecha_Hasta IS NULL))
					,0)
PRINT 'Contrato CS Automatico Actual: ' + CONVERT(VARCHAR(10), @Existe)

/*Contrato CS Manual*/
SET @ExisteManual = ISNULL((	SELECT MAX(Id_Contrato) 
								FROM Contratos 
								WHERE
								Id_Cliente = @Cli 
								AND Activo = 1 
								AND Id_Tipo_Con = 2 /*Contrato CS Manual*/
								AND Fecha_Desde <= GETDATE()
								AND (Fecha_Hasta >= GETDATE() OR Fecha_Hasta IS NULL))
							,0)
PRINT 'Contrato CS Manual Actual: ' + CONVERT(VARCHAR(10), @ExisteManual)


/*----------------------------------------------------------------------*/

/*Datos del Cliente*/
SET @Activo = ISNULL((SELECT MAX(Activo) FROM Clientes WHERE Id_Cliente = @Cli), 0)
PRINT 'Socio Activo: ' + CONVERT(VARCHAR(10), @Activo)


IF (@Lista_Precio = 0)
BEGIN
	/*Si no tiene lista de Precio salgo del SP*/
	set @Lista_Precio = 1
	PRINT 'El Socio no tiene lista de precio, se toma la lista de precio 1'
END

/*Vitalicio + 71*/
IF @Id_Tipo_Cli = 1010 
BEGIN
  SET @Id_Prod = '2010V' /*Vitalicio + 71 voluntaria*/
END

/*Usuario RCA*/
IF @Id_Tipo_Cli = 1012 
BEGIN
  SET @Id_Prod = '2012V' /*Usuario RCA Voluntaria*/
END

/*Usuario +75*/
IF @Id_Tipo_Cli = 1017 
BEGIN
  SET @Id_Prod = '1297V' /*Usuario +75 Voluntaria*/
END


PRINT 'Cód. Producto correspondiente a las condiciones del Socio: ' + @Id_Prod




/*----------------------------------------------------------------------*/
IF (ISNULL(@Existe,0) = 0)
BEGIN
	PRINT 'NO existe contrato CS automatico'
 
	IF (@Activo = 1)
	BEGIN
		SET @Actualizar = 1
		PRINT 'Socio Activo, hay que actualizar'
	END 
END
ELSE
BEGIN
	PRINT 'Existe un Contrato Automatico'
	SET @Id_Prod_Ant = ISNULL((SELECT Id_Producto FROM Contratos_Prod WHERE Id_Contrato = @Existe AND Item = 2 ),'')
	SET @Flag_Facturable_ant = ISNULL((SELECT Flag_Facturable FROM Contratos_Prod WHERE Id_Contrato = @Existe AND Item = 1 ),0)
	print @Flag_Facturable_ant
	PRINT 'Cód. Producto del Contrato Anterior: ' + @Id_Prod_Ant
	
	SET @Id_Tarjeta = ISNULL((SELECT Id_Tarjeta FROM Contratos WHERE Id_Contrato = @Existe),'')
	SET @Id_Banco	= ISNULL((SELECT Id_Banco FROM Contratos WHERE Id_Contrato = @Existe),0)
	SET @Tar_Nro	= ISNULL((SELECT Tar_Nro FROM Contratos WHERE Id_Contrato = @Existe),'')
	PRINT 'Tipo de Tarjeta de Crédito/Debito Bancario: ' + @Id_Tarjeta + ' Tarjeta Nro.: ' + @Tar_Nro + ' Cód. de Banco: ' + CONVERT(VARCHAR(10), @Id_Banco)
	
	IF ((@Activo = 0) OR (ISNULL(@ExisteManual,0) <> 0) OR (@Id_Prod_Ant <> @Id_Prod) 
	                  OR (@Flag_Facturable_ant <> @Flag_Facturable))
	BEGIN
		PRINT 'El Socio esta INACTIVO o existe CONTRATO CS MANUAL o CAMBIO PRODUCTO o CAMBIO TARJETA' 
		SET @Actualizar = 1
  
		UPDATE Contratos 
		SET 
			Activo = 0,
			Fecha_Baja = GETDATE(),
			Fecha_Hasta = GETDATE(),
			Id_Motivo_Est =1,
			Flag_Sistema = 1
		WHERE 
			Id_Contrato = @Existe
  
		PRINT 'Se pone en Inactivo el Contrato CS Automatico. Cód: ' + CONVERT(VARCHAR(10), @Existe)
	END
END

/*----------------------------------------------------------------------*/


IF ((@Activo = 1) AND (@Actualizar = 1) AND (@ExisteManual = 0))
BEGIN
	PRINT 'Se crea un nuevo contrato (Socio Activo, hay que actualizar y no existe contrato CS Manual)'
	
    SET @Existe = (SELECT ISNULL(MAX(Id_Contrato),0) + 1  FROM Contratos)
    PRINT 'Nro. Contrato a crear: ' + CONVERT(VARCHAR(10), @Existe)
    
    /*CONTRATO*/
	INSERT INTO Contratos
				(Id_Contrato,	Id_Cliente,		Id_Tipo_Con,
				Fecha_Alta,		Fecha_Desde,	Activo,
				Id_Tipo_Cbte,	Id_Lista_Precio, Flag_Sistema,
				Id_Tarjeta,		Id_Banco,		Tar_Nro)
	VALUES
				(@Existe,		@Cli,			37/*CS Vitalicio*/,
				GETDATE(),		GETDATE(),		1/*Activo*/,
				'CPRO',			@Lista_Precio,	1/*Flag_Sistema*/,
				 @Id_Tarjeta,	@Id_Banco,		@Tar_Nro)
	PRINT 'Se creó un nuevo contrato. Nro: ' + CONVERT(VARCHAR(10), @Existe)
 
     
	 /*CONTRATOS PROD (ITEMS)*/
       
	/*Item: Producto especifico de categoria*/       
	INSERT INTO Contratos_Prod 
				(Id_Contrato,	Item,				Id_Producto,
				Precio,			Flag_Facturable,	Cantidad)
	VALUES
				(@Existe,		1,					@Id_Prod,
				0,				1,					1)
	PRINT 'Se creó el Item: ' + @Id_Prod
END



PRINT 'Fin de ejecucion: SP_Contrato_Cli_Vitalicio'
PRINT '----------------------------------------------------------------'
GO


CREATE PROCEDURE [dbo].[SP_Contrato_Validar] @Id_Cliente INT
AS

--Ticket 10.792

/*Declaracion de Variables*/
DECLARE @Flag_Tiene_Deuda			TINYINT
DECLARE @Id_Cliente_Titular			INT
DECLARE @Modo_Debug					TINYINT
/*FIN Declaracion de Variables*/

SET @Modo_Debug = 0

IF(@Modo_Debug = 1)
BEGIN
	PRINT '----------------------------------------------------------------'
	PRINT 'Inicio de ejecucion: SP_Contrato_Validar'
END

SET @Flag_Tiene_Deuda	= 0 

IF(@Modo_Debug = 1)
BEGIN
	PRINT 'Validacion del Cod. Cliente: ' + CONVERT(VARCHAR(10), @Id_Cliente)
END

/*Cliente no definido o varios*/
IF (@Id_Cliente <= 1)
BEGIN
	IF(@Modo_Debug = 1)
	BEGIN
		PRINT 'Socio NO DEFINIDO o VARIOS. Sale del SP: SP_Contrato_Validar'
	END
END
/*FIN Cliente no definido o varios*/

SET @Id_Cliente_Titular = ISNULL((SELECT Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @Id_Cliente), 0)

IF(@Id_Cliente_Titular = 0)
BEGIN
	SET @Id_Cliente_Titular = @Id_Cliente
END

IF(@Modo_Debug = 1)
BEGIN
	PRINT 'Cod. Cliente Referente: ' + CONVERT(VARCHAR(10), @Id_Cliente_Titular)
END

SET @Flag_Tiene_Deuda = ISNULL((SELECT 1 FROM Cbtes CB, Cbtes_Tipos CT
								WHERE
								CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte 
								AND CB.Id_Cliente = @Id_Cliente_Titular
								AND CB.Id_Estado_Cbte IN (1/*Pendiente*/, 4/*Parcial*/)
								AND CT.Compromete_Factura IN (1))
								,0)


IF (@Flag_Tiene_Deuda = 1)
BEGIN
	RAISERROR (N'OPERACIÓN INVÁLIDA. El Socio debe cancelar la deuda de la cuenta corriente del Grupo Familiar.                                                                                                                                                                       ', 16, 1);
END

IF(@Modo_Debug = 1)
BEGIN
	PRINT 'Fin de ejecucion: SP_Contrato_Validar'
	PRINT '----------------------------------------------------------------'
END
GO


CREATE procedure [dbo].[SP_Control_Asiento_Contable] @fdesde datetime,@fhasta datetime
 
 as
declare @accion varchar(250)  
--set @fdesde = '20171101'
--set @fhasta = '20171130'

--conrol de alias duplicados
------------------------------------------------------------- ------------------AGREGAR FILTRO FECHA
set @accion = 'Debe modificar en el plan de cuentas el alias '
set @accion = @accion+ 'indicando el proximo numero disponible de alias'
select '1001' as Validacion,'Alias Nro.: '+rtrim(CONVERT(varchar(15),alias)) +
		' de Cuenta Contable Duplicado, Plan de Cuentas: '+rtrim(CONVERT(varchar(15),Id_Plan_Cta))  as Mensaje,
		@accion as Accion
from (select Id_Plan_Cta ,alias,COUNT(*) as cantidad from  
Pla_Ctas_Cuentas_Contables 
group by  Id_Plan_Cta ,alias
having COUNT(*) > 1 ) aux1 

union

--control de alias  diferentes con plan de cuentas --------------------  
------------------------------------------------------------- ------------------AGREGAR FILTRO FECHA

select '1002' as Validacion,'El Alias Nro.: '+rtrim(CONVERT(varchar(15),Id_Alias_Cta_Cont)) +
		' de la cuenta contable: '+rtrim(CONVERT(varchar(15),Id_Cta_Contable)) +
		' No equivale a su Alias: '+rtrim(CONVERT(varchar(15),p_alias))  as Mensaje,
		'Se debe corregir el asiento contable Nro. '+rtrim(CONVERT(varchar(15),id_asiento))+
		' Item: '+rtrim(CONVERT(varchar(15),item))
		 as Accion
		from (
 select i.*,p.Alias as p_alias
 from Asientos_Items i,Pla_Ctas_Cuentas_Contables p
 where i.Id_Cta_Contable = p.Id_Cta_Contable
 and i.Id_Alias_Cta_Cont <> p.Alias) aux1



union

--control de cuentas de otro ejercicio--------------------  
------------------------------------------------------------- ------------------AGREGAR FILTRO FECHA
select '1003' as Validacion,'La cuenta contable: '+rtrim(CONVERT(varchar(15),Id_Cta_Contable)) +
		' no pertenece al plan de cuentas, La Cuenta del Periodo es: '+rtrim(CONVERT(varchar(15),cuenta_cont_valida ))  as Mensaje,
		'Se debe corregir el asiento contable Nro. '+rtrim(CONVERT(varchar(15),id_asiento))+
		' Item: '+rtrim(CONVERT(varchar(15),item))
		 as Accion
 from 
 (select i.* ,dbo.SF_Cta_Contable(i.Id_Alias_Cta_Cont,a.Fecha) as cuenta_cont_valida
 from Asientos_Items i,Asientos a,Pla_Ctas_Cuentas_Contables p,Plan_Ctas pc, Plan_Ctas_Ejercicios PE
 where i.Id_Cta_Contable = p.Id_Cta_Contable
 and a.Id_Asiento = i.Id_Asiento
 and p.Id_Plan_Cta = pc.Id_Plan_Cta
 and pc.Id_Ejercicio = pe.Id_Ejercicio
 and (a.Fecha < pe.Fecha_Inicio or a.Fecha > pe.Fecha_Cierre)) aux1


/*
 union
 --control de alias con funcion-----------
------------------------------------------------------------- ------------------AGREGAR FILTRO FECHA
 select i.*,dbo.SF_Cta_Contable(i.Id_Alias_Cta_Cont,a.Fecha) as dd
 from Asientos_Items i,Asientos a,Pla_Ctas_Cuentas_Contables p,Plan_Ctas pc, Plan_Ctas_Ejercicios PE
 where i.Id_Cta_Contable = p.Id_Cta_Contable
 and a.Id_Asiento = i.Id_Asiento
 and p.Id_Plan_Cta = pc.Id_Plan_Cta
 and pc.Id_Ejercicio = pe.Id_Ejercicio
 and i.Id_Cta_Contable = (dbo.SF_Cta_Contable(i.Id_Alias_Cta_Cont,a.Fecha))
 select * from Asientos 

*/
--------------------------
 --control de id_cta  unido con alias -------------------------------
------------------------------------------------------------- ------------------AGREGAR FILTRO FECHA
union 
select '1005' as Validacion,'La cuenta contable: '+rtrim(CONVERT(varchar(15),Id_Cta_Contable)) +
		' no se corresponde con su alias en el plan de cuentas, Asiento: '+rtrim(CONVERT(varchar(15),id_asiento ))+
		' Item: '+rtrim(CONVERT(varchar(15),item))   as Mensaje,
		'Se debe corregir el asiento contable Nro. '+rtrim(CONVERT(varchar(15),id_asiento))+
		' Item: '+rtrim(CONVERT(varchar(15),item))
		 as Accion
from  
 (select i.*
  from Asientos_Items i,Asientos a,Pla_Ctas_Cuentas_Contables p,Plan_Ctas pc, Plan_Ctas_Ejercicios PE
 where  a.Id_Asiento = i.Id_Asiento
 and p.Id_Plan_Cta = pc.Id_Plan_Cta
 and pc.Id_Ejercicio = pe.Id_Ejercicio
 and p.Id_Plan_Cta = a.Id_Plan_Cta
 and p.Alias = i.Id_Alias_Cta_Cont
 and i.Id_Cta_Contable <> p.Id_Cta_Contable) aux1



-----------------------control de asientos resumenes
union
select  '1006' as Validacion,'El Asiento Nro.'+rtrim(CONVERT(varchar(15),Id_asiento)) +' - '+rtrim(CONVERT(varchar(15),Descripcion))+
		' de Fecha '+rtrim(CONVERT(varchar(15),convert(date, fecha) ))+
		' Presenta Diferencia de '+rtrim(CONVERT(varchar(15),Dif_Debe_Control ))+' en su asiento resumen ' as Mensaje,
		'Se debe Generar el Asiento Resumen '
		 as Accion
from  
(
select A.Id_Asiento,A.Fecha,A.Descripcion,A.Importe,O.debe AS Total_Debe_Control, A.Importe - O.debe AS Dif_Debe_Control,
o.haber AS Total_Haber_Control,A.Importe - O.Haber AS Dif_Haber_Control  
from Asientos a, (select C.id_asiento, SUM(debe) as debe, SUM(haber) as haber 
    from Cbtes_Ctas_Contables o, cbtes c , Cbtes_Tipos ct
  where c.Id_Trans = o.Id_Trans
    and c.Id_Estado_Cbte not in (3) 
    AND C.Periodo_Iva >= @fdesde
    AND C.Periodo_Iva < @fhasta + 1
    and c.Id_Tipo_Cbte = ct.Id_Tipo_Cbte 
    and ct.Compromete_Asientos !=0
  GROUP BY C.Id_Asiento) O
where O.id_asiento=  a.Id_Asiento) aux1 where Dif_Debe_Control <>0 or Dif_Haber_Control <>0
GO

CREATE PROCEDURE [dbo].[SP_Control_EsSocio] @pDocNro BIGINT
AS
DECLARE @Flag_Existen_Registros TINYINT
DECLARE @Flag_Tiene_Contrato_CS INT

SET @Flag_Existen_Registros = ISNULL((SELECT COUNT(Id_Cliente) FROM Clientes WHERE Doc_Nro = @pDocNro), 0)

IF(@Flag_Existen_Registros > 0)
BEGIN
	SELECT 
	CL.Id_Cliente AS Cod_Socio, 
	CL.Id_Cliente_Externo AS Nro_Socio, 
	CL.Doc_Nro,
	CL.Razon_Social AS Ape_Nom, 
	CL.Activo,
	CONVERT(DATE, CL.Fecha_Alta) AS Fecha_Alta, 
	CONVERT(DATE, CL.Fecha_Baja) AS Fecha_Baja, 
	CT.Descripcion AS Categoria, 
	dbo.SF_Control_Tiene_Contrato_CS(CL.Id_Cliente, GETDATE()) AS Contrato_CS,
	dbo.SF_CS_Precio(CL.Id_Cliente, GETDATE()) AS Precio_Actual_CS,
	dbo.SF_DeudaTotal_CS(CL.Id_Cliente) AS Deuda_Total_CS,
	CLT.Id_Cliente AS Cod_Socio_Titular,
	CLT.Id_Cliente_Externo AS Nro_Socio_Titular,
	CLT.Razon_Social AS Ape_Nom_Titular
	FROM Clientes CL, Clientes_Tipos CT, Clientes CLT
	WHERE
	CL.Id_Tipo_Cli = CT.Id_Tipo_Cli
	AND ISNULL(CL.Id_Cliente_Ref, 0) = CLT.Id_Cliente
	AND CL.Doc_Nro = @pDocNro	
	ORDER BY CL.Fecha_Alta
END
/*
Gabriel indicó que no devuelva nada
ELSE
BEGIN
	SELECT 'NO EXISTE SOCIO CON NRO. DOC: ' + CONVERT(VARCHAR(20), @pDocNro) AS Existe_Socio
END*/
GO

CREATE PROCEDURE [dbo].[SP_Desglosar_Pedidos] @ID_TRANS INT
       AS 

        BEGIN
		BEGIN TRY
	    BEGIN TRAN

		DECLARE @trans_nueva INTEGER
		DECLARE @NRO_CBTE INTEGER
	    declare @desc varchar(50)
		declare @fecha_mov datetime
		declare @user smallint
		declare @id_cond_vta  smallint
        declare @id_tipo_cbte varchar(5)
        declare @id_producto varchar(15)
        declare @Cantidad decimal(12,2)
        declare @Cantidad_orig decimal(12,2)
        declare @ITEM INTEGER
		declare @id_Color varchar(10)

        DECLARE @Mensaje	VARCHAR(100) 
		
		SET @Mensaje = ''
		SET @id_cond_vta = (SELECT id_cond_vta from cbtes where id_trans = @ID_TRANS) 
		SET @desc = (SELECT descripcion from transacciones where id_trans = @ID_TRANS) 
		SET @fecha_mov = (SELECT fecha_mov from transacciones where id_trans = @ID_TRANS) 
		SET @user = (SELECT id_usuario from transacciones where id_trans = @ID_TRANS) 
		SET @id_tipo_cbte = (SELECT id_tipo_cbte from cbtes where id_trans = @ID_TRANS) 
						
        select I.Id_Trans,ISNULL(P.Id_Color,'''') AS Id_COLOR ,sum(i.Cantidad) AS CANTIDAD INTO #CBTES_ITEMS_tot_aux
                              from Cbtes_Items I,Productos P
                              where id_trans = @id_trans
                              and I.id_producto = P.Id_producto  group by I.Id_Trans,P.Id_Color

        Set @Cantidad   = (select count(*) from #CBTES_ITEMS_tot_aux )
		IF @Cantidad  < 2 
		   RETURN   

               Declare MIcursor cursor for select id_Color from #CBTES_ITEMS_tot_aux WHERE ID_TRANS = @ID_TRANS

               Open Micursor
                    Fetch next from Micursor into @id_Color
                    While @@fetch_status = 0 
                    begin

               ----------------------------- Primero los insert ----------------------------------
			   	       SET @trans_nueva = (SELECT max(id_trans) from transacciones ) + 1
					   INSERT INTO TRANSACCIONES
					   (id_trans,descripcion,fecha_mov,id_usuario)
					    values (@trans_nueva,@desc,@fecha_mov,@user)

					   SELECT * INTO #CBTES_aux_sp  FROM CBTES 
					              WHERE ID_TRANS = @ID_TRANS

					   SELECT I.* INTO  #CBTES_ITEMS_aux_sp FROM CBTES_ITEMS I, PRODUCTOS P  
							      WHERE I.ID_TRANS = @ID_TRANS AND P.ID_PRODUCTO = I.ID_PRODUCTO AND ISNULL(P.ID_COLOR,'''') = @ID_COLOR


               -----------------------------Actualizo -----------------------------------------------
         
					   UPDATE #CBTES_aux_sp SET 
							  Imp_Gravado = (SELECT SUM(Imp_Gravado) FROM #CBTES_ITEMS_aux_sp  WHERE ID_TRANS = @ID_TRANS) * (1-Porc_Bonificacion/100),
							  Imp_Bonificacion = (SELECT SUM(Imp_Gravado) FROM #CBTES_ITEMS_aux_sp  WHERE ID_TRANS = @ID_TRANS) * (Porc_Bonificacion/100) 
							  WHERE ID_TRANS = @ID_TRANS  

					   UPDATE #CBTES_aux_sp SET 
							  Imp_Iva = Imp_Gravado * Porc_Iva/100 
							  WHERE ID_TRANS = @ID_TRANS  

					   UPDATE #CBTES_aux_sp SET 
							  Imp_Total = Imp_Gravado + Imp_Iva + Imp_Percep
							  WHERE ID_TRANS = @ID_TRANS  
  
  
					   UPDATE #CBTES_aux_sp SET Saldo = Imp_Total WHERE ID_TRANS = @ID_TRANS 
			    
					   SET @NRO_CBTE = (SELECT Prox_nro FROM CBTES_TIPOS WHERE ID_TIPO_CBTE = @id_tipo_cbte)
					   UPDATE CBTES_TIPOS SET Prox_nro = Prox_nro+1 WHERE ID_TIPO_CBTE = @id_tipo_cbte

					   UPDATE #CBTES_AUX_SP SET COMPROBANTE_NRO = @NRO_CBTE  WHERE ID_TRANS = @ID_TRANS

		               update #CBTES_aux_sp set id_trans = @trans_nueva  where id_trans = @ID_TRANS
		               update #CBTES_ITEMS_aux_sp set id_trans = @trans_nueva where id_trans = @ID_TRANS

					   -----------------------------agrego -----------------------------------------------
					   INSERT INTO CBTES
							  SELECT * FROM  #CBTES_aux_sp WHERE ID_TRANS = @trans_nueva    

					   INSERT INTO CBTES_ITEMS
          					 SELECT * FROM #CBTES_ITEMS_aux_sp WHERE ID_TRANS = @trans_nueva 

                        DROP TABLE #CBTES_aux_sp
                        DROP TABLE #CBTES_ITEMS_aux_sp
						
						SET @Mensaje = RTRIM(LTRIM(@Mensaje)) + ' ' + CAST(@trans_nueva AS VARCHAR(10))

                        Fetch next from Micursor into @id_COLOR
                    End       
               Close Micursor
               Deallocate Micursor
               ------- ACTUALIZO ESTADO CBTE ORIGINAL ---------

               UPDATE CBTES SET ID_ESTADO_CBTE = 7, Observacion = 'Transacciones desglosadas: ' + @Mensaje  WHERE ID_TRANS = @ID_TRANS 
			   UPDATE CBTES_ITEMS SET CANTIDAD_SALDO = 0 WHERE ID_TRANS = @ID_TRANS 

               -----------------------------BORRO -----------------------------------------------

			 DROP TABLE #CBTES_ITEMS_tot_aux 

		     COMMIT TRAN
 
			SELECT	 0					AS ErrorNumber 
					,0					AS ErrorSeverity  
					,0					AS ErrorState 
					,0					AS ErrorProcedure  
					,0					AS ErrorLine		
					,@Mensaje			AS ErrorMessage
	END TRY  

	BEGIN CATCH  
		EXECUTE usp_GetErrorInfo 
		ROLLBACK
	END CATCH 

    End

 -- EXEC [dbo].[SP_Desglosar_Pedidos] 161
GO

CREATE  PROCEDURE [dbo].[SP_Fact_Duplicada] @fecha_dede DATE, @fecha_hasta DATE
AS

print @fecha_dede
print @fecha_hasta

select c.id_trans,i.item,c.id_tipo_cbte,c.comprobante_nro,cast(c.fecha as  date) as fecha,c.destinatario
,i.id_producto, p.descripcion_detallada,e.razon_social as persona
,e.id_Cliente_externo as socio,e.id_Cliente as codigo, o.descripcion as categoria
,i.fecha_qa,convert(date,i.fecha_qa,112) as periodo ,i.imp_final as importe
,cast(e.ult_cuota_paga as date) as UCP ,c.Lote, c.Imp_Total, c.id_estado_cbte
INTO #Cbtes_Verificar
from Cbtes_items i , Cbtes c, Productos P, Clientes e, Cbtes_tipos t, clientes_tipos o
where i.id_trans = c.id_trans 
and p.id_producto = i.id_producto
and i.id_cliente = e.id_cliente
and t.id_tipo_Cbte = c.id_tipo_cbte
and o.id_tipo_cli = e.id_tipo_cli
and e.activo = 1
and t.compromete_factura = 1
and c.id_estado_cbte in (1,4) --pendiente/parcial
and c.fecha >=@fecha_dede
and c.fecha <=@fecha_hasta
and p.Flag_mes = 1 --ocultar?
and imp_final > 1


select 
cv.id_trans as id_trans_final,
cv.item as item_final,
cv.id_tipo_cbte as id_tipo_cbte_final,
cv.comprobante_nro as comprobante_nro_final,
cv.fecha as fecha_final,
cv.destinatario as destinatario_final,
cv.id_producto as id_producto_final, 
cv.descripcion_detallada as descripcion_detallada,
cv.persona as persona_final,
cv.socio as socio_final,
cv.codigo as codigo_final, 
cv.categoria as categoria_final,
cv.fecha_qa as fecha_qa_final,
cv.periodo as periodo_final,
CONVERT (DECIMAL(12,2), cv.importe)as importe_final,
cv.UCP as UCP_final,
cv.lote as lote_final,
cv.Imp_Total as imp_total_final , 
cv.id_estado_cbte as id_estado_cbte_final
from #Cbtes_Verificar cv
where exists (select 1 from Cbtes_items i2 , Cbtes c2,  Cbtes_tipos t2
			where i2.id_trans = c2.id_trans 
			and t2.id_tipo_Cbte = c2.id_tipo_cbte
			and t2.compromete_factura = 1
			and c2.id_estado_cbte in (1,2,4)
			and i2.id_cliente = cv.codigo 
			and i2.id_producto = cv.id_producto
			and i2.fecha_qa = cv.fecha_qa
			and c2.id_trans <> cv.id_trans		
			)
			
--select * from #Cbtes_Verificar

			
			--EXEC SP_Fact_Duplicada '20200101','20200101'
GO

CREATE  PROCEDURE [dbo].[SP_Fact_Duplicada_Lote] @fecha_dede DATE, @fecha_hasta DATE
AS

print @fecha_dede
print @fecha_hasta

select c.id_trans,i.item,c.id_tipo_cbte,c.comprobante_nro,cast(c.fecha as  date) as fecha,c.destinatario
,i.id_producto, p.descripcion_detallada,e.razon_social as persona
,e.id_Cliente_externo as socio,e.id_Cliente as codigo, o.descripcion as categoria
,i.fecha_qa,convert(date,i.fecha_qa,112) as periodo ,i.imp_final as importe
,cast(e.ult_cuota_paga as date) as UCP
,c.Lote
INTO #Cbtes_Verificar
from Cbtes_items i , Cbtes c, Productos P, Clientes e, Cbtes_tipos t, clientes_tipos o
where i.id_trans = c.id_trans 
and p.id_producto = i.id_producto
and i.id_cliente = e.id_cliente
and t.id_tipo_Cbte = c.id_tipo_cbte
and o.id_tipo_cli = e.id_tipo_cli
and e.activo = 1
and t.compromete_factura = 1
and c.id_estado_cbte in (1,4)
and c.fecha >=@fecha_dede
and c.fecha <=@fecha_hasta
and p.Flag_mes = 1
--and p.id_familia in (1,7,14,17)
and imp_final > 1

select 
cv.id_trans as id_trans_final,
cv.item as item_final,
cv.id_tipo_cbte as id_tipo_cbte_final,
cv.comprobante_nro as comprobante_nro_final,
cv.fecha as fecha_final,
cv.destinatario as destinatario_final,
cv.id_producto as id_producto_final, 
cv.descripcion_detallada as descripcion_detallada,
cv.persona as persona_final,
cv.socio as socio_final,
cv.codigo as codigo_final, 
cv.categoria as categoria_final,
cv.fecha_qa as fecha_qa_final,
cv.periodo as periodo_final,
CONVERT (DECIMAL(12,2), cv.importe)as importe_final,
cv.UCP as UCP_final,
cv.Lote
from #Cbtes_Verificar cv
where exists (select 1 from Cbtes_items i2 , Cbtes c2,  Cbtes_tipos t2
			where i2.id_trans = c2.id_trans 
			and t2.id_tipo_Cbte = c2.id_tipo_cbte
			and t2.compromete_factura = 1
			and c2.id_estado_cbte in (1,2,4)
			and i2.id_cliente = cv.codigo 
			and i2.id_producto = cv.id_producto
			and i2.fecha_qa = cv.fecha_qa
			and c2.id_trans <> cv.id_trans
			--**se agrego para obtener las trans menores y tengan algun lote**
			and ( 
					( cv.Id_Trans < c2.id_trans and isnull(cv.lote,'') = '' and isnull(c2.lote,'') <> '')
					or
					( c2.Id_Trans < cv.Id_Trans and isnull(c2.Lote,'') = '' and isnull(cv.Lote,'') <> '')
			)
			)
GO


CREATE PROCEDURE [dbo].[SP_Fact_Proforma_Anular]  @pLote VarChar(20)

AS
SET NOCOUNT ON

DECLARE

	@pId_Tipo_Cbte		CHAR(4),
	@pId_Tipo_Cli       Smallint 

	SET @pId_Tipo_Cbte  = 'CPRO'

/*Declaracion Variables Locales*/
  DECLARE  @Mensaje			VARCHAR(100)
	      ,@UltError	    INT
		  ,@Id_Trans		INT
		  ,@Id_Cliente		INT
		  ,@Importe			DECIMAL(16,2)
		  ,@Email_Cob   	VARCHAR(256)
		  ,@Comprobante_Nro   INT
		  ,@CursorOpen        INT
		  ,@Descrip_Cbte      VARCHAR(100)
		  ,@Result_Stored_Invocado  INT
		  ,@JSON_Parametros_Stored_Invocado VARCHAR(8000)

  DECLARE @Respuesta Table (
				ErrorNumber		INT,
				ErrorSeverity	INT,
				ErrorState		INT,
				ErrorProcedure  VARCHAR(1000),
				ErrorLine		INT,
				ErrorMessage	VARCHAR(1000)
				)


  BEGIN TRY

    /*Borrar Cupones */

	UPDATE CBTES SET ID_ESTADO_CBTE = 3 WHERE ID_ESTADO_CBTE = 1 AND ID_TIPO_CBTE = @pId_Tipo_Cbte AND FECHA < Getdate() - 30 AND FECHA >'20210531'
	
	
	/******************************fin del proceso***********************************************/

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo
	
  	
	RETURN 9999
END CATCH

RETURN 0


