CREATE PROCEDURE [dbo].[SP_Fact_Proforma_Reemplazar]  @pId_Trans INT

AS
SET NOCOUNT ON

DECLARE
	@pFecha				DATETIME,
	@pId_Tipo_Cbte		CHAR(4),
	@pId_Tipo_Cli       Smallint 

	SET @pId_Tipo_Cli = (select k.Id_Tipo_Cli from Clientes K,Cbtes C where C.Id_cliente = K.Id_cliente and Id_Trans = @pId_Trans)
	SET @pFecha = (SELECT Fecha from Cbtes where Id_Trans = @pId_Trans)
	SET @pId_Tipo_Cbte  = 'CUP'

	PRINT 'Entro a [SP_Fact_Proforma_Reemplazar] '

/*Declaracion Variables Locales*/
  DECLARE  @Mensaje			VARCHAR(100)
	      ,@UltError	    INT
		  ,@Id_Trans		INT
		  ,@Id_Cliente		INT
		  ,@Importe			DECIMAL(16,2)
		  ,@Email_Cob   	VARCHAR(256)
		  ,@Comprobante_Nro   INT
		  ,@CursorOpen        INT
		  ,@Descrip_Cbte      VARCHAR(100)
		  ,@Result_Stored_Invocado  INT
		  ,@JSON_Parametros_Stored_Invocado VARCHAR(8000)

  DECLARE @Respuesta Table (
				ErrorNumber		INT,
				ErrorSeverity	INT,
				ErrorState		INT,
				ErrorProcedure  VARCHAR(1000),
				ErrorLine		INT,
				ErrorMessage	VARCHAR(1000)
				)
/*Se agrega categoría 1012 y 1017 x Tk 20137 15/8*/
	IF @pId_Tipo_Cli NOT IN ( 1010/*Vitalicio +71*/, 1012 /*Usuario RCA*/, 1017 /*Usiario+ 75*/)
		BEGIN
			SET @Mensaje = 'Debe ser Socio Vicalicio +70, Usuario RCA o Usuario +75' + ' ' + CONVERT(VARCHAR(10),@pId_Tipo_Cli) + '' + CONVERT(VARCHAR(10),@pId_Trans)
			SELECT	 0	    	        AS ErrorNumber 
					,0					AS ErrorSeverity  
					,0					AS ErrorState 
					,0					AS ErrorProcedure  
					,0					AS ErrorLine		
					,@Mensaje			AS ErrorMessage
			RETURN 0
		END

	BEGIN TRY


     /*Recorrer los tagueados */

	DECLARE TagCbtesCursor CURSOR FOR
		SELECT A.ID_TRANS AS Id_Trans 
				FROM Cbtes_Aplica A, CBTES C
				WHERE A.ID_trans_D = @pId_Trans AND A.Id_Trans = C.Id_Trans
				AND C.Id_Tipo_Cbte = 'CPRO'

	OPEN TagCbtesCursor

	FETCH NEXT FROM TagCbtesCursor INTO @Id_Trans
	SET @CursorOpen = 0	
	SET @UltError = 0
	WHILE @@FETCH_STATUS=0 AND @UltError  = 0
	BEGIN
        	PRINT 'Entro al WHILE [SP_Fact_Proforma_Reemplazar] '

            SET @CursorOpen = 1
			Set @Comprobante_Nro = (Select Prox_Nro from Cbtes_Tipos where Id_Tipo_Cbte = @pId_Tipo_Cbte)
			Update Cbtes_Tipos Set Prox_Nro = @Comprobante_Nro+1  where Id_Tipo_Cbte = @pId_Tipo_Cbte

			Update Cbtes Set Id_Tipo_Cbte = @pId_Tipo_Cbte, Comprobante_Nro = @Comprobante_Nro, Fecha = @pFecha,
			                 Fecha_Venc = @pFecha, Periodo_Iva = @pFecha, Periodo = @pFecha where Id_trans = @Id_Trans
			
            SET @Descrip_Cbte = dbo.CF_Descrip_Cbte(@Id_Trans)
            Update Clientes_CtaCte set Fecha = @pFecha, Fecha_Vence = @pFecha, Descripcion = @Descrip_Cbte where Id_trans = @Id_Trans
			--UPDATE Cbtes_Items SET Descripcion_Producto= @Descrip_Cbte where Id_trans = @Id_Trans				 
			
			SET @JSON_Parametros_Stored_Invocado =	'{' +
											dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('Id_Trans', @Id_Trans, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('ModoDebug', 0, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('FlagRegenerar', 1, 'TINYINT') + 
											'}'
	        DELETE @Respuesta
	        INSERT INTO @Respuesta						
        	EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Ctas_Contables_Generar @JSON_Parametros_Stored_Invocado						 

 	    	IF @Result_Stored_Invocado <> 0
			BEGIN
				SELECT * FROM @Respuesta	
				RETURN 4569
			END

  			FETCH NEXT FROM TagCbtesCursor INTO @Id_Trans 

	END
	CLOSE TagCbtesCursor
	DEALLOCATE TagCbtesCursor
	SET @CursorOpen = 0	

    /*SET @JSON_Parametros_Stored_Invocado =	'{' +
											dbo.CF_Json_ParsearVariable('FlagUsarTrans', 0, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('Id_Trans', @pId_Trans, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('ModoDebug', 0, 'INT') + ',' +
											dbo.CF_Json_ParsearVariable('FlagRegenerar', 1, 'TINYINT') + 
											'}'
	        DELETE @Respuesta
	        INSERT INTO @Respuesta						
        	EXEC @Result_Stored_Invocado = dbo.CPJ_Cbtes_Ctas_Contables_Generar @JSON_Parametros_Stored_Invocado						 

 	    	IF @Result_Stored_Invocado <> 0
			BEGIN
				SELECT * FROM @Respuesta	
				RETURN 4569
			END*/   --Comentado  30/12/2024 porque ya lo genera Rec_Fin o Clarion.



	/******************************fin del proceso***********************************************/



	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,0				AS ErrorLine		
			,@Mensaje		AS ErrorMessage
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo
	
      IF @CursorOpen = 1
	     BEGIN 
		 	CLOSE TagCbtesCursor
	        DEALLOCATE TagCbtesCursor
         END
		 	
	RETURN 9999
END CATCH

RETURN 0
GO


CREATE PROCEDURE [dbo].[SP_GENERAR_REMITO] @ID_TRANS INT
AS 
DECLARE @Mensaje			VARCHAR(100)
BEGIN TRY
BEGIN TRAN


IF ((SELECT Id_Estado_cbte FROM CBTES WHERE ID_TRANS = @ID_TRANS) = 3) 
	BEGIN
	    SET @Mensaje = 'El cbte no debe estar en Estado Anulado'
		ROLLBACK
		SELECT	 1099		    	AS ErrorNumber 
				,0					AS ErrorSeverity  
				,0					AS ErrorState 
				,0					AS ErrorProcedure  
				,0					AS ErrorLine		
				,@Mensaje			AS ErrorMessage
		RETURN 1
	END

   UPDATE CBTES SET ID_ESTADO_CBTE = 18 WHERE ID_TRANS =  @ID_TRANS

   PRINT @ID_TRANS

		DECLARE @trans_nueva INTEGER
		DECLARE @NRO_CBTE INTEGER
	    DECLARE @desc varchar(50)
		DECLARE @fecha_mov datetime
		DECLARE @user smallint
		DECLARE @id_cond_vta  VARCHAR(10)
        DECLARE @id_tipo_cbte VARCHAR(4)
		DECLARE @id_Sucursal SMALLINT
		DECLARE @Id_Estado_Cbte_Rever Smallint
		 
		
	
		/*Agrego por tk 18443 - 26/11/19*/
		DECLARE @Fecha       DATETIME
		DECLARE @Periodo_Iva DATETIME
		DECLARE @Periodo     DATETIME
		DECLARE @Fecha_venc  DATETIME

		SET @id_cond_vta = (SELECT id_cond_vta from cbtes where id_trans = @ID_TRANS) 

		PRINT 'Id_cond_vta:' + CONVERT (VARCHAR (5), @id_cond_vta)

		SET @trans_nueva = (SELECT max(id_trans) from transacciones ) + 1
		SET @desc = (SELECT descripcion from transacciones where id_trans = @ID_TRANS) 
		SET @fecha_mov = (SELECT fecha_mov from transacciones where id_trans = @ID_TRANS) 
		SET @user = (SELECT id_usuario from transacciones where id_trans = @ID_TRANS) 
		SET @id_tipo_cbte = 'RM'
		SET @id_Sucursal = (SELECT id_sucursal FROM Cbtes_Tipos WHERE Id_Tipo_Cbte=@id_tipo_cbte)

		SET @Id_Estado_Cbte_Rever = (SELECT Isnull(Id_Estado_cbte,1)  From cbtes_Tipos where Id_Tipo_Cbte = @id_tipo_cbte) 
		SET @NRO_CBTE =  (SELECT Prox_Nro  From cbtes_Tipos where Id_Tipo_Cbte = @id_tipo_cbte) 
		
		
		SET @Fecha       = (SELECT Fecha       FROM Cbtes WHERE id_trans=@ID_TRANS)
		SET @Periodo_Iva = (SELECT Periodo_Iva FROM Cbtes WHERE id_trans=@ID_TRANS)
		SET @Periodo     = (SELECT Periodo     FROM Cbtes WHERE id_trans=@ID_TRANS)
		SET @Fecha_venc  = (SELECT Fecha_venc  FROM Cbtes WHERE id_trans=@ID_TRANS)

	 
		
		Update cbtes_Tipos SET Prox_Nro = @NRO_CBTE + 1 WHERE Id_Tipo_Cbte = @id_tipo_cbte

		PRINT @NRO_CBTE

        ----------------------------- Primero los insert ----------------------------------
        INSERT INTO TRANSACCIONES
			(id_trans,descripcion,fecha_mov,id_usuario)
			values (@trans_nueva,@desc,@fecha_mov,@user)

		
               SELECT * INTO #CBTES_aux_sp FROM CBTES WHERE ID_TRANS = @ID_TRANS

               SELECT * INTO #CBTES_ITEMS_aux_sp FROM CBTES_ITEMS WHERE ID_TRANS = @ID_TRANS


               -----------------------------Actualizo id_trans -----------------------------------------------

		update #CBTES_aux_sp set id_trans = @trans_nueva , id_tipo_cbte = @id_tipo_cbte, Id_Estado_Cbte = @Id_Estado_Cbte_Rever
		               ,Fecha = @Fecha, Periodo_Iva =@Periodo_Iva, Periodo = @Periodo, Fecha_Venc = @Fecha_venc 
					   ,Nro_Auto_Trib = '',Cai_Vence = NULL
					   ,Comprobante_Nro = @NRO_CBTE
					   , Id_Sucursal = @id_Sucursal
                       where id_trans = @ID_TRANS
		IF @id_Sucursal = 4
	    	update #CBTES_aux_sp set Observacion = '' where id_trans = @trans_nueva

		update #CBTES_ITEMS_aux_sp set id_trans = @trans_nueva  where id_trans = @ID_TRANS

							  
   -----------------------------agrego -----------------------------------------------

               INSERT INTO CBTES
                      SELECT * FROM  #CBTES_aux_sp WHERE ID_TRANS = @trans_nueva    

               INSERT INTO CBTES_ITEMS
                      SELECT * FROM #CBTES_ITEMS_aux_sp WHERE ID_TRANS = @trans_nueva 

   ----------------------------- update -----------------------------------------------
   
       UPDATE CBTES SET ID_ESTADO_CBTE = 16,Remito_Nro = @NRO_CBTE, id_trans_origen=@trans_nueva /*Guarda en la factura la tr. del Remito para imp. desde el RECE*/  WHERE ID_TRANS =  @ID_TRANS

   ----------------------------- borro -----------------------------------------------

               DROP TABLE #CBTES_aux_sp 
               DROP TABLE #CBTES_ITEMS_aux_sp 



COMMIT
SELECT	 0					AS ErrorNumber 
		,0					AS ErrorSeverity  
		,0					AS ErrorState 
		,0					AS ErrorProcedure  
		,@trans_nueva		AS ErrorLine		
		,@Mensaje			AS ErrorMessage

END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo;  
	ROLLBACK
END CATCH;   




