CREATE  PROCEDURE [dbo].[SP_Partir_Contrato] @cli INT,@id_contrato int  ,@fecha_desde datetime,@fecha_hasta datetime
AS
begin

declare @contrato_actual int
declare @existe int
declare @fecha_hasta_nueva datetime


set @contrato_actual = isnull((select top 1 id_contrato from Contratos 
                  where id_tipo_con = 1 and activo = 1 and fecha_desde < @fecha_desde
                  and Id_Cliente = @cli 
                  and fecha_hasta > @fecha_hasta order by id_contrato desc ),0)
print 'contrato actual'
print @contrato_actual

if @contrato_actual <> 0
begin

	set @fecha_hasta_nueva = (select fecha_hasta + (@fecha_hasta - @fecha_desde) 
	                            from Contratos where id_contrato =@contrato_actual  )
	print '@fecha_hasta_nueva'
	print @fecha_hasta_nueva
	print '@fecha_desde'
	print @fecha_desde
	update Contratos set fecha_hasta = @fecha_desde - 1
		   where id_contrato = @contrato_actual

	SET @existe = (SELECT MAX(Id_Contrato)+1 FROM Contratos )


	INSERT INTO Contratos (Id_Contrato,Id_Cliente,Id_Tipo_Con,Fecha_Alta,Fecha_Desde,fecha_hasta,Activo,Id_Tipo_Cbte,Id_Lista_Precio,Flag_Sistema)
					VALUES(@Existe,@Cli,1,GETDATE(),@fecha_hasta + 1,@fecha_hasta_nueva,1,'',0,1) 

	SELECT * INTO #cont from Contratos_Prod where Id_Contrato = @contrato_actual
	update #cont set Id_Contrato = @Existe	   
	insert into Contratos_Prod
	    select * from #cont
	drop table #cont    

end
end
GO



CREATE PROCEDURE SP_Pedidos_Entregados 
	@pFecha_Desde			DATETIME,
	@pFecha_Hasta			DATETIME,
	@pId_Sucursal           INT,
	@pPendientes            Int

AS
BEGIN


        SELECT * INTO #SUCURSALES FROM Empresas_Suc WHERE Activo = 1
		If @pId_Sucursal > 0
		   Delete  #SUCURSALES where Id_Sucursal <> @pId_Sucursal

		select OE.ID_TIPO_CBTE ORD_ENTREGA, RE.ID_TIPO_CBTE REMITO, RE.COMPROBANTE_NRO NRO_REMITO,RE.FECHA FECHA_REM, PED.ID_TRANS as ID_TRANS_P
		INTO #ENTREGAS
		from cbtes PED, CBTES OE, CBTES RE, CBTES_TIPOS TOF, CBTES_TIPOS TR, CBTES_TIPOS TP
		WHERE  PED.ID_TIPO_CBTE =  TP.ID_TIPO_CBTE
		AND TP.Compromete_Pedido = 1
		AND PED.ID_ESTADO_CBTE <> 3
		AND OE.ID_TIPO_CBTE = TOF.ID_TIPO_CBTE 
		AND TOF.Compromete_Orden_Facturacion = 1
		AND OE.ID_ESTADO_CBTE <> 3
		AND RE.ID_TIPO_CBTE = TR.ID_TIPO_CBTE 
		AND TR.Compromete_REMITOS = 1
		AND RE.ID_ESTADO_CBTE <> 3
		AND CAST(PED.Comprobante_Nro AS CHAR(10)) = OE.Pedido_Nro  
		and isnumeric(OE.Pedido_Nro) = 1
		and OE.CBTE_NRO_EXTERNO =  RE.CBTE_NRO_EXTERNO
		and OE.CBTE_NRO_EXTERNO <> ''
		and RE.CBTE_NRO_EXTERNO <> ''
		AND RE.ID_SUCURSAL = PED.ID_SUCURSAL
		AND PED.ID_CLIENTE = OE.ID_CLIENTE
		AND PED.ID_TIPO_CBTE <> 'PA25' 


		select C.ID_TIPO_CBTE AS PED_SEG,C.ID_TRANS ,C.FECHA,C.CBTE_NRO_EXTERNO,C.ID_CLIENTE,C.DESTINATARIO ,PS.ID_TIPO_CBTE PEDIDO_SUC,PS.ID_TRANS ID_TRANS_SUC, PS.FECHA FECHA_PED
		INTO #PEDIDOS
		from CBTES C, CBTES PS , CBTES_TIPOS TSEG , #SUCURSALES S
		WHERE C.ID_TIPO_CBTE = 'PA25' 
		AND PS.ID_TRANS_ORIGEN  = C.ID_TRANS 
		AND PS.ID_TIPO_CBTE = TSEG.ID_TIPO_CBTE
		AND TSEG.Compromete_Pedido IN (1,-1)
	    AND C.FECHA >= @pFecha_Desde 
	    AND C.FECHA < dateadd(dd,1,@pFecha_Hasta)
		AND TSEG.Id_Sucursal = S.Id_Sucursal
 
		CREATE NONCLUSTERED INDEX IX_#ENTREGAS_TRANS
		ON [dbo].[#ENTREGAS] ([ID_TRANS_P])
		INCLUDE ([ORD_ENTREGA],[REMITO],[NRO_REMITO],[FECHA_REM])

        If @pPendientes = 0
		   Begin
	        	SELECT * FROM #PEDIDOS P LEFT JOIN #ENTREGAS E ON P.ID_TRANS_SUC = E.ID_TRANS_P ORDER BY P.FECHA
		   End
		 Else
		   Begin
	        	SELECT * FROM #PEDIDOS P LEFT JOIN #ENTREGAS E ON P.ID_TRANS_SUC = E.ID_TRANS_P
				Where isnull(Remito,'') = '' ORDER BY P.FECHA
		   End
END

DROP TABLE #PEDIDOS
DROP TABLE #ENTREGAS


-- EXEC SP_PEDIDOS_ENTREGADOS '','',0
GO

CREATE PROCEDURE [dbo].[SP_Promo2021_Verano] (
	@Ape VARCHAR(100),	
	@Nom VARCHAR(100),	
	@Sex CHAR(1),
	@Doc VARCHAR(100),	
	@Nac VARCHAR(100),	
	@Tel VARCHAR(100),	
	@Mov VARCHAR(100),
	@Email VARCHAR(100),
	@Obs VARCHAR(2000),
	@Id_Invitador INT
	)
AS

--Valido si existe la persna en la base
DECLARE @Existe INT
SELECT @Existe = COUNT(*) FROM Clientes WHERE Doc_Nro = CAST(@Doc AS BIGINT)
IF ISNULL(@Existe,0) <> 0
BEGIN
	SELECT  5001 AS ErrorNumber
			,1 AS ErrorSeverity
			,1 AS ErrorState
			,1 AS ErrorProcedure
			,1 AS ErrorLine
			,'La persona que esta intentando ingresar ya existe en nuestra base de datos. No es posible realizar la invitación.' AS ErrorMessage
	RETURN 9999		
END

SELECT @Existe = z_Id_Invitado_2020__Verano FROM Clientes WHERE Id_Cliente = @Id_Invitador
IF ISNULL(@Existe,0) <> 0
BEGIN
	SELECT  5002 AS ErrorNumber
			,1 AS ErrorSeverity
			,1 AS ErrorState
			,1 AS ErrorProcedure
			,1 AS ErrorLine
			,'Ya invitaste a ' + (SELECT Razon_Social FROM Clientes WHERE Id_Cliente = @Existe) + 
			'. No esta permitido que realices otra invitaciòn.'
			AS ErrorMessage
	RETURN 9999		
END



SET @Nac = REPLACE(@Nac,'-','')

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored						INT
DECLARE @rtaMsjStored						VARCHAR(4000)
DECLARE @Result_Stored_Invocado				INT
DECLARE @Result_Tabla_Stored_Invocado TABLE (ErrorNumber	INT,
											ErrorSeverity	INT,
											ErrorState		INT,
											ErrorProcedure  VARCHAR(1000),
											ErrorLine		INT,
											ErrorMessage	VARCHAR(4000))
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
DECLARE @rta_JSON_Stored_Invocado			VARCHAR(8000)
DECLARE @Id_Trans							INT
DECLARE @Email_Existe						INT
DECLARE @Clave								INT
/*FIN Variable de Retorono del Stored*/


BEGIN TRY
BEGIN TRAN

SET @Existe  = (SELECT MAX(Id_Cliente) FROM Clientes ) + 1
SET @Clave	 = (SELECT FLOOR(RAND()*(99999999-100000)+1))

SET @Email_Existe = ISNULL((SELECT COUNT(*) FROM Clientes WHERE Email_Web=@Email AND Clave_Web=CAST(@Clave AS VARCHAR(30))),0)

IF (@Email_Existe <>0)
BEGIN
	SET @Clave	 = (SELECT FLOOR(RAND()*(99999999-100000)+1))
END 

INSERT INTO Clientes (Razon_Social,Apellido,Nombre,Sexo,Fecha_Nac,Id_Tipo_Doc,Doc_Nro
               ,Email,Email_Cob,Email_Web,Activo,Id_Cond_Pago,Id_Iva,Id_Concepto,Id_Alias_Cta_Cont_Venta,Mercado,
