CREATE PROCEDURE [dbo].[SP_Rev_Med_Grupo_Familiar]  
                   @pid_Cliente INT
				  ,@pid_Cliente_Externo VARCHAR(14)
				  ,@pDoc_Nro BIGINT
AS

SET NOCOUNT ON

/*Declaracion Variables Locales*/
DECLARE @id_Cliente_REF INT

IF @pid_Cliente = 0
   BEGIN
      IF @pid_Cliente_Externo <> '' 
	     BEGIN
	        SELECT @pid_Cliente = Id_Cliente, @id_Cliente_REF = Id_Cliente_Ref From Clientes where id_Cliente_Externo =  @pid_Cliente_Externo 
		    IF @id_Cliente_REF <> 0 
			    BEGIN
			      SET @pid_Cliente = @id_Cliente_REF
		       END
		  END
		 ELSE
		  BEGIN
	        SELECT @pid_Cliente = Id_Cliente, @id_Cliente_REF = Id_Cliente_Ref From Clientes where Doc_Nro =  @pDoc_Nro
		    IF @id_Cliente_REF <> 0 
			    BEGIN
			      SET @pid_Cliente = @id_Cliente_REF
		       END		   
	      END
   END 
  ELSE
 	BEGIN
	  SELECT @pid_Cliente = Id_Cliente, @id_Cliente_REF = Id_Cliente_Ref From Clientes where Id_Cliente =  @pid_Cliente
	  IF @id_Cliente_REF <> 0 
		  BEGIN
		     SET @pid_Cliente = @id_Cliente_REF
		  END		   
	END  


IF @pid_Cliente <> 0
   BEGIN 
	 SELECT C.Id_Cliente,C.Id_Cliente_Externo,C.Doc_Nro,C.Razon_Social, cast(v.FECHA as date) AS Fecha_Vto ,v.ID_TIPO_VENC as Tipo_Vto
	    FROM  clientes c LEFT OUTER JOIN  CLIENTES_VENC  V on C.id_cliente = V.id_cliente and isnull(V.ID_TIPO_VENC,'') in ( 'AF','')
		WHERE ((C.id_cliente = @pid_Cliente and isnull(C.id_cliente_ref ,0) = 0) 
			OR (isnull(C.id_cliente ,0) != 0  AND C.Id_cliente_ref = @pid_Cliente))
	    ORDER BY C.Id_Cliente_Externo
     END


 --  SP_Rev_Med_Grupo_Familiar 0,'017756-002',0

  --  SP_Rev_Med_Grupo_Familiar 0,'',52960931

   --  SP_Rev_Med_Grupo_Familiar 19086,'',0
GO

CREATE PROCEDURE [dbo].[SP_Rev_Med_Resultado]  
                   @pid_Cliente INT
				  ,@pProcesar SMALLINT
AS

SET NOCOUNT ON

/*Declaracion Variables Locales*/
DECLARE @EXISTE INT

SET @EXISTE = ISNULL((SELECT COUNT(*) FROM CLIENTES_VENC WHERE ID_CLIENTE = @pid_Cliente AND ID_TIPO_VENC = 'AF'),0)

IF @pProcesar = 1
   BEGIN
		IF @EXISTE  = 0
		   BEGIN
			 INSERT INTO CLIENTES_VENC (ID_CLIENTE,Id_Tipo_Venc,Fecha) VALUES (@pid_Cliente,'AF',GETDATE() + 30)
		   END
		  ELSE
		   BEGIN
			 UPDATE CLIENTES_VENC SET Fecha = GETDATE() + 30 WHERE ID_CLIENTE = @pid_Cliente AND ID_TIPO_VENC = 'AF'
		   END
   END

IF @pProcesar = 2
   BEGIN
		IF @EXISTE  <> 0
		   UPDATE CLIENTES_VENC SET Fecha = DATEADD(DAY,-30,GETDATE())  WHERE ID_CLIENTE = @pid_Cliente AND ID_TIPO_VENC = 'AF' /*20230403 A. Se saca el Null por - 30 días*/

   END

 --  exec SP_Rev_Med_Grupo_Familiar 831032,'',1
-- EXEC SP_Rev_Med_Resultado '831032',1
