CREATE PROCEDURE [dbo].[SP_Rpt_Ventas_Por_Vend_Tipo] @Fecha_Desde DATETIME,@Fecha_Hasta DATETIME 
AS

DECLARE @ML_Cant					INT
DECLARE @ML_Importe					DECIMAL(14,2)
DECLARE @ML_Cant_Anul				INT
DECLARE @ML_Importe_Anul			DECIMAL(14,2)
DECLARE @ML_Cant_Dev				INT
DECLARE @ML_Importe_Dev				DECIMAL(14,2)
DECLARE @ML_Cant_Hoy				INT
DECLARE @ML_Importe_Hoy				DECIMAL(14,2)
DECLARE @ML_Cant_Mes				INT
DECLARE @ML_Importe_Mes				DECIMAL(14,2)
									
DECLARE @VD_Cant					INT
DECLARE @VD_Importe					DECIMAL(14,2)
DECLARE @VD_Cant_Anul				INT
DECLARE @VD_Importe_Anul			DECIMAL(14,2)
DECLARE @VD_Cant_Dev				INT
DECLARE @VD_Importe_Dev				DECIMAL(14,2)
DECLARE @VD_Cant_Hoy				INT
DECLARE @VD_Importe_Hoy				DECIMAL(14,2)
DECLARE @VD_Cant_Mes				INT
DECLARE @VD_Importe_Mes				DECIMAL(14,2)
									
DECLARE @VS_Cant					INT
DECLARE @VS_Importe					DECIMAL(14,2)
DECLARE @VS_Cant_Anul				INT
DECLARE @VS_Importe_Anul			DECIMAL(14,2)
DECLARE @VS_Cant_Dev				INT
DECLARE @VS_Importe_Dev				DECIMAL(14,2)
DECLARE @VS_Cant_Hoy				INT
DECLARE @VS_Importe_Hoy				DECIMAL(14,2)
DECLARE @VS_Cant_Mes				INT
DECLARE @VS_Importe_Mes				DECIMAL(14,2)
									
DECLARE @VG_Cant					INT
DECLARE @VG_Importe					DECIMAL(14,2)
DECLARE @VG_Cant_Anul				INT
DECLARE @VG_Importe_Anul			DECIMAL(14,2)
DECLARE @VG_Cant_Dev				INT
DECLARE @VG_Importe_Dev				DECIMAL(14,2)
DECLARE @VG_Cant_Hoy				INT
DECLARE @VG_Importe_Hoy				DECIMAL(14,2)
DECLARE @VG_Cant_Mes				INT
DECLARE @VG_Importe_Mes				DECIMAL(14,2)
									
DECLARE @MY_Cant					INT
DECLARE @MY_Importe					DECIMAL(14,2)
DECLARE @MY_Cant_Anul				INT
DECLARE @MY_Importe_Anul			DECIMAL(14,2)
DECLARE @MY_Cant_Dev				INT
DECLARE @MY_Importe_Dev				DECIMAL(14,2)
DECLARE @MY_Cant_Hoy				INT
DECLARE @MY_Importe_Hoy				DECIMAL(14,2)
DECLARE @MY_Cant_Mes				INT
DECLARE @MY_Importe_Mes				DECIMAL(14,2)
									
DECLARE @Total_Cant_Hoy				INT
DECLARE @Total_Importe_Hoy			DECIMAL(14,2)
DECLARE @Total_Cant_Mes				INT
DECLARE @Total_Importe_Mes			DECIMAL(14,2)
DECLARE @Total_Cant					INT
DECLARE @Total_Importe				DECIMAL(14,2)
DECLARE @Total_Cant_Anul			INT
DECLARE @Total_Importe_Anul			DECIMAL(14,2)
DECLARE @Total_Cant_Dev				INT
DECLARE @Total_Importe_Dev			DECIMAL(14,2)

DECLARE @VS_ucp_Importe_Mes DECIMAL(14,2)
,@MY_ucp_Importe_Mes DECIMAL(14,2)
,@VD_ucp_Importe_Mes DECIMAL(14,2)
,@ml_ucp_Importe_Mes DECIMAL(14,2)
,@Total_UCP_Importe_Mes DECIMAL(14,2)

DECLARE @Objetivo					DECIMAL(14,2)
DECLARE @Primer_Dia					DATE
DECLARE @Ultimo_Dia					DATE

DECLARE @FECHA_PROCESO               DATE
SET @FECHA_PROCESO = CONVERT(DATE, GETDATE()) 

--SET @Primer_Dia =(SELECT DATEADD(MONTH, -1, DATEADD(day , 1 , EOMONTH(GETDATE()))))
--SET @Ultimo_Dia =(SELECT EOMONTH(GETDATE()))
--SET @Ultimo_Dia = DATEADD(D,1,@Ultimo_Dia)

SET @Primer_Dia = @Fecha_Desde
SET @Ultimo_Dia = Dateadd(dd,1,@Fecha_Hasta)

CREATE TABLE #RESUMEN (
        Id_Vendedor VARCHAR(10)
		,Descripcion VARCHAR(60)
	    ,ML_Cant_Hoy INT
	    ,ML_Importe_Hoy DECIMAL(14,2)
	    ,ML_Cant_Mes INT 
	    ,ML_Importe_Mes DECIMAL(14,2)
        ,ML_UCR DECIMAL(14,2)
	    ,VD_Cant_Hoy INT
	    ,VD_Importe_Hoy DECIMAL(14,2)
	    ,VD_Cant_Mes INT 
	    ,VD_Importe_Mes DECIMAL(14,2)
	    ,VD_UCR DECIMAL(14,2)
		,VS_Cant_Hoy INT
		,VS_Importe_Hoy DECIMAL(14,2)
		,VS_Cant_Mes INT 
		,VS_Importe_Mes DECIMAL(14,2)
		,VS_UCR DECIMAL(14,2)
		,MY_Cant_Hoy INT
		,MY_Importe_Hoy DECIMAL(14,2)
		,MY_Cant_Mes INT 
		,MY_Importe_Mes DECIMAL(14,2)
	    ,MY_UCR DECIMAL(14,2)
		,Total_Cant_Hoy INT 
		,Total_Importe_Hoy DECIMAL(14,2)
		,Total_Cant_Mes INT 
		,Total_Importe_Mes DECIMAL(14,2)
		,TOTAL_UCR DECIMAL(14,2)
		)

		INSERT INTO #RESUMEN  
		select  Id_Vendedor,Descripcion
		,0 as ML_Cant_Hoy  
	    ,0 as ML_Importe_Hoy 
	    ,0 as ML_Cant_Mes  
	    ,0 as ML_Importe_Mes 
        ,0 as ML_UCR  
	    ,0 as VD_Cant_Hoy  
	    ,0 as VD_Importe_Hoy  
	    ,0 as VD_Cant_Mes  
	    ,0 as VD_Importe_Mes 
	    ,0 as VD_UCR 
		,0 as VS_Cant_Hoy 
		,0 as VS_Importe_Hoy  
		,0 as VS_Cant_Mes 
		,0 as VS_Importe_Mes 
		,0 as VS_UCR  
		,0 as MY_Cant_Hoy  
		,0 as MY_Importe_Hoy 
		,0 as MY_Cant_Mes  
		,0 as MY_Importe_Mes  
	    ,0 as MY_UCR  
		,0 as Total_Cant_Hoy  
		,0 as Total_Importe_Hoy  
		,0 as Total_Cant_Mes  
		,0 as Total_Importe_Mes  
		,0 as TOTAL_UCR  
		from Vendedores where Activo = 1 or isnull(Id_vendedor,'') = ''

		Update #RESUMEN SET DESCRIPCION = 'ML' WHERE Id_vendedor = ''

		

/*#################################### MERCADO LIBRE #################################################*/

/* Cantidad de facturas MERCADO LIBRE HOY */
--SELECT @ML_Cant_Hoy=COUNT(*) , @ML_Importe_Hoy=ISNULL(SUM(ISNULL(CBF.Imp_Total*T.compromete_factura,0)),0)
/*SELECT CBP.Id_Vendedor, COUNT(*) AS  ML_Cant_Hoy, ISNULL(SUM(ISNULL(CBF.Imp_Total*T.compromete_factura,0)),0) AS ML_Importe_Hoy
INTO #DETALLE
FROM Cbtes CBF, Cbtes CBP, CBTES_TIPOS T
WHERE CBF.Id_Tipo_Cbte = T.ID_TIPO_CBTE
AND (T.COMPROMETE_FACTURA IN (1,-1) or CBF.Id_Tipo_Cbte IN ('FP25'))
AND T.ID_SUCURSAL = 25
AND CBP.Id_Tipo_Cbte IN ('PF25', 'PA25', 'PD25', 'PX25')
