SELECT CBP.Id_Vendedor, COUNT(*) AS  ML_Cant_Mes, ISNULL(SUM(ISNULL(CBF.Imp_Total*T.compromete_factura,0)),0) AS ML_Importe_Mes
INTO #DETALLE1
