CREATE PROCEDURE [dbo].[SP_SCA_ListaBlanca_Generar] @Id_Acceso SMALLINT
AS

BEGIN
DECLARE @Tags			VARCHAR(1349)
DECLARE @Id_Cliente		INT
DECLARE @Tag			VARCHAR(30);
DECLARE @Contador		INT
DECLARE @FlagHabilitado TINYINT
DECLARE @Hoy			DATETIME

SET @Hoy = (SELECT GETDATE())

SET @Contador = 0
SET @FlagHabilitado = 0

PRINT 'INCIO del Proceso: SP_SCA_ListaBlanca_Generar'

PRINT 'Id_Acceso: ' + CONVERT(VARCHAR(10), @Id_Acceso)
PRINT 'Fecha: ' + CONVERT(VARCHAR(10), @Hoy, 103)

EXEC dbo.SP_CD_TagsHabilitados @Id_Acceso, @Hoy

UPDATE CD_Accesos SET Fecha_LB = GETDATE() WHERE Id_Acceso = @Id_Acceso

PRINT 'FIN del Proceso: SP_SCA_ListaBlanca_Generar'

SELECT 0,'PROCESO SP_SCA_ListaBlanca_Generar FINALIZADO EXITOSAMENTE';
RETURN(1)

END
