CREATE PROCEDURE [dbo].[SP_UCP_Total] 
AS

DECLARE @Id_Familia		INT

/*Recorro todos los clientes*/

SET @Id_Familia =dbo.CF_xParam('Fam_CuotasSoc')

select MAX(Fecha_QA) as ucp,i.Id_Cliente 
INTO #UCP
from Cbtes_Items I, Cbtes C, Cbtes_Tipos T, Productos p
WHERE I.Id_Trans =C.Id_Trans
And C.Id_Tipo_Cbte=T.Id_Tipo_Cbte
AND T.Compromete_Factura =1
AND C.Id_estado_Cbte IN (2,4)
and i.Id_producto=p.Id_producto
and p.Id_familia=@Id_Familia
AND ISNULL(p.Vendible, 0) = 1
AND (ISNULL(p.Flag_Mes, 0) = 1 OR ISNULL(p.Flag_Periodo, 0) = 1)
GROUP BY i.Id_Cliente 

Create Index ix_#UCP ON #UCP (Id_Cliente)


--SELECT id_tipo_cli,Ult_cuota_Paga,ucp,cl.Id_cliente,getdate() as Fecha_Proc FROM Clientes cl, #UCP z
--WHERE cl.Id_cliente=z.Id_cliente
--AND cl.Ult_cuota_Paga<>z.ucp
--AND activo=1
--AND id_Tipo_Cli in (
--1000,
--1001,
--1002,
--1003,
--1020,
--1055,
--1060,
--1065,
--1070
--)


UPDATE Clientes SET Ult_Cuota_Paga=ucp FROM Clientes c, #UCP z WHERE c.Id_Cliente=z.Id_Cliente
AND c.Ult_cuota_Paga <> z.ucp
AND activo=1
AND id_Tipo_Cli in (
1000,
1001,
1002,
1003,
1020,
1055,
1060,
1065,
1070
)
and Ult_Cuota_Paga < ucp

DROP TABLE #UCP

-- EXEC dbo.SP_UCP_Total
GO

CREATE PROCEDURE [dbo].[SP_Ult_Cuota_Paga] @pId_Trans INT, @pItem INT, @pId_Producto CHAR(14) 
AS
DECLARE @Id_Familia		INT
DECLARE @Id_Estado_Cbte	INT
DECLARE @Ult_Cuota_Paga	DATETIME
DECLARE @UCP			DATETIME
DECLARE @Id_Cliente		INT
DECLARE @UCP_Especial	DATETIME

PRINT 'Ingreso a SP_Ult_Cuota_Paga'

PRINT '@pId_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans) + ' @pItem: ' + CONVERT(VARCHAR(10), @pItem) + ' @pId_Producto: ' + @pId_Producto
  
/*Busco cual es la Familia de Producto*/
SET @Id_Familia = (SELECT Id_Familia FROM Productos where Id_Producto = @pId_Producto)

IF (@Id_Familia = (dbo.CF_xParam('Fam_CuotasSoc')))
BEGIN
	/*Todos los productos de la familia Cuota Social los actualiza al producto CS*/
	IF (@pId_Producto <> 'CS')
	BEGIN
	   UPDATE Cbtes_Items SET Id_Producto = 'CS' WHERE Id_Trans = @pId_Trans AND Item = @pItem AND Id_Producto <> 'CS' 
	END
	/*FIN Todos los productos de la familia Cuota Social los actualiza al producto CS*/
	   
	SET @Id_Estado_Cbte = (SELECT Id_Estado_Cbte FROM Cbtes where Id_Trans = @pId_Trans) 
	PRINT 'Id_Estado_Cbte: ' + CONVERT(VARCHAR(10), @Id_Estado_Cbte)


	IF (@Id_Estado_Cbte IN (2, 1, 3, 0, 4))
	BEGIN	   
		SET @Id_Cliente = (SELECT Id_Cliente FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Item = @pItem)			

		IF(@Id_Cliente NOT IN (0, 1))
		BEGIN
			PRINT 'Id_Cliente: ' + CONVERT(VARCHAR(10), @Id_Cliente)
			SET @Ult_Cuota_Paga = (SELECT ISNULL(Ult_Cuota_Paga, '19000101') FROM Clientes WHERE Id_Cliente = @Id_Cliente)
			
								
			SET @UCP		= 	dbo.SF_Ult_Cuota_Paga(@Id_Cliente, GETDATE())
			
			/*Se agrega un tipo de Cbte capaz de modificar la última cuota paga en caso de encontrase en estado Pendiente*/
			
		 	SET @UCP_Especial = (dbo.CF_Clientes_UCP_xCbteEsp(@Id_Cliente))
			
			IF(@UCP_Especial <> '19000101')
			BEGIN
				SET @UCP = @UCP_Especial
			END
													
			PRINT 'Ultima Cuota Paga Calculada: ' + CONVERT(VARCHAR(10), @UCP, 103)

			IF(@Ult_Cuota_Paga <> @UCP)
			BEGIN
			
				UPDATE Clientes 
				SET Ult_Cuota_Paga = @UCP
				WHERE 
				Id_Cliente = @Id_Cliente 
				
				PRINT 'ACTUALIZO CLIENTES'
				
				/*OR Id_Cliente_Ref = @Id_Cliente*/ /*Se saco la condición por mail enviado por silvia el 28/7*/
			END
		END
	END
END
GO

CREATE procedure [dbo].[SP_VW_Cbtes_Generar] @LOTE VARCHAR(20), @Fecha CHAR(8),@Hora CHAR(6),@Id_Cliente INT, @Importe DECIMAL(12,2)
AS 
--SET NOCOUNT ON 
BEGIN TRAN

declare @desc varchar(50),@Id_Tipo_Cbte CHAR(4),@Nombre VARCHAR(100),@NRO_CBTE INT
DECLARE @trans_nueva INTEGER

SET @Id_Tipo_Cbte = 'ND'
SET @desc = 'VW:' + @LOTE
SET @Nombre = (SELECT rtrim(Razon_Social) FROM Clientes WHERE Id_Cliente = @Id_Cliente)

SET @trans_nueva = (SELECT max(id_trans) from transacciones ) + 1
INSERT INTO TRANSACCIONES (id_trans,descripcion,fecha_mov) values (@trans_nueva,@desc,GETDATE())
IF (@@ERROR <> 0)
BEGIN
    ROLLBACK
	RETURN 1
END

SET @NRO_CBTE = (SELECT PROX_NRO from CBTES_TIPOS WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte) 
UPDATE CBTES_TIPOS SET PROX_NRO = PROX_NRO+1 WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte
IF (@@ERROR <> 0)
BEGIN
    ROLLBACK
	RETURN 1
END

INSERT INTO CBTES (Id_Cond_Vta,Id_trans,Id_Sucursal,Cbte_Grupo, Fecha_Venc ,    id_cliente, id_estado_Cbte  ,id_tipo_cbte, comprobante_nro,fecha,periodo_iva,periodo,imp_total,saldo,imp_gravado,destinatario,lote,ID_MONEDA,Id_Cond_Pago,Cotizacion)
           values ('',@trans_nueva,1   ,0         ,@FECHA    ,@id_cliente,0 ,@Id_Tipo_cbte,@NRO_CBTE,@FECHA,@FECHA,@FECHA, @Importe ,0,@Importe,@NOMBRE,'VW:' + @LOTE,'PES',10,1)

IF (@@ERROR <> 0)
BEGIN
    ROLLBACK
	RETURN 1
END

INSERT INTO CLIENTES_CTACTE  (Id_Trans,Nro_Cuota,Id_Empresa,Id_Cliente,Fecha,Fecha_Vence,Descripcion,Importe,Id_Estado_Cbte,Observacion,Id_Trans_Origen,Nro_Cuota_Origen,Id_Moneda,Saldo,Nro_FacCre)
     VALUES (@trans_nueva,1,NULL,@id_cliente,@Fecha,@Fecha,'ND  C 0001-' + RIGHT('0000000' + LTRIM(CAST(@NRO_CBTE AS CHAR(8))),8),@Importe ,1,'',0,0,'PES',0,0)


