CREATE procedure [dbo].[SP_VW_Confirmar] @LOTE VARCHAR(20)
AS 

--SET NOCOUNT ON 
BEGIN TRAN
DECLARE @trans_rec INTEGER,@trans_ND INT,@LoteND VARCHAR(20),@LoteRec VARCHAR(20)
SET @LoteND = 'VW:' + @LOTE
SET @LoteRec = 'CW:' + @LOTE

SET @trans_ND = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = @LoteND AND Id_Estado_Cbte = 0),0)
IF (@trans_ND = 0)
BEGIN
	ROLLBACK
	PRINT 'No hay trans de Factura'
	RETURN 1
END
PRINT @trans_ND

SET @trans_rec = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = @LoteRec AND Id_Estado_Cbte = 0),0)
IF (@trans_rec = 0)
BEGIN
	ROLLBACK
	PRINT 'No hay trans de recibo'
	RETURN 1
END
PRINT @trans_rec

UPDATE Cbtes SET Id_Estado_Cbte = 2 WHERE Id_Trans = @trans_ND
IF (@@ERROR <> 0)		
BEGIN
	ROLLBACK
	RETURN 1
END
		
UPDATE Cbtes_Items SET Id_Estado_Cbte = 2 WHERE Id_Trans = @trans_ND
IF (@@ERROR <> 0)		
BEGIN
	ROLLBACK
	RETURN 1
END

UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 2 WHERE Id_Trans = @trans_ND
IF (@@ERROR <> 0)		
BEGIN
	ROLLBACK
	RETURN 1
END
		
UPDATE Cbtes SET Id_Estado_Cbte = 2 WHERE Id_Trans = @trans_rec
IF (@@ERROR <> 0)		
BEGIN
	ROLLBACK
	RETURN 1
END
		
UPDATE Cbtes_Items SET Id_Estado_Cbte = 2 WHERE Id_Trans = @trans_rec
IF (@@ERROR <> 0)		
BEGIN
	ROLLBACK
	RETURN 1
END
		
UPDATE Clientes_CtaCte SET Id_Estado_Cbte = 2 WHERE Id_Trans = @trans_rec
IF (@@ERROR = 0)		
    COMMIT TRAN
ELSE
    ROLLBACK
GO

CREATE procedure [dbo].[SP_VW_Items_Generar] @LOTE VARCHAR(20), @Item INT ,@Id_Producto CHAR(14),@Nota VARCHAR(200), @Importe DECIMAL(12,2),@Desde DATETIME,@Hasta DATETIME
AS 
--SET NOCOUNT ON 
BEGIN TRAN

DECLARE @trans_nueva INTEGER,@descripcion_producto VARCHAR(100),@id_cliente INT

SET @trans_nueva = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = 'VW:' + @LOTE AND Id_Estado_Cbte = 0),0)
IF (@trans_nueva = 0)
BEGIN
    ROLLBACK
	RETURN 1
END

SET @descripcion_producto = (SELECT Descripcion_Resumida FROM Productos WHERE Id_Producto  = @Id_Producto)
SET @id_cliente = (SELECT id_cliente FROM Cbtes WHERE Id_Trans = @trans_nueva)

INSERT INTO CBTES_ITEMS  (id_cliente,descripcion_producto,Cantidad,id_estado_Cbte,Cantidad_Saldo,
                Id_Trans    ,item,Precio_Grav,Imp_Gravado,Imp_Final,Precio  ,Lote ,Fecha_Qa,Flag_QA,Id_Producto,Fecha_Venc)
     VALUES (@id_cliente,RTRIM(@descripcion_producto),1,0,1,
                @trans_nueva,@Item   ,@Importe   ,@Importe  ,@Importe ,@Importe,'VW:' + @LOTE,@Desde  ,'A'    ,@Id_Producto,@Hasta)


 IF (@@ERROR = 0)
     COMMIT TRAN
 ELSE
     ROLLBACK
GO

CREATE procedure [dbo].[SP_VW_Pago_Generar] @LOTE VARCHAR(20),@item int, @Id_Tipo_Val CHAR(4),@Id_Tarjeta VARCHAR(10),@TransPago VARCHAR(15),@Nota VARCHAR(100), @ImportePago DECIMAL(12,2)
AS 
--SET NOCOUNT ON 
BEGIN TRAN

declare @desc varchar(50),@Id_Tipo_Cbte CHAR(4),@Nombre VARCHAR(100),@NRO_CBTE INT,@Id_Cliente INT,@Nro_Cbte_ND INT
DECLARE @trans_rec INTEGER,@trans_ND INT,@FECHA DATETIME,@Importe DECIMAL(12,2),@Observacion VARCHAR(100)
DECLARE @Descrip_Cbte_CtaCte VARCHAR(50),@Id_Periodo_Caja INT,@Id_Valor INT

SET @trans_rec = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = 'CW:' + @LOTE AND Id_Estado_Cbte = 0),0)
SET @Id_Periodo_Caja = 14

IF @trans_rec = 0
BEGIN
	PRINT 'Agregando Recibo'
	SET @trans_ND = ISNULL((SELECT MAX(Id_trans) FROM Cbtes WHERE LOTE = 'VW:' + @LOTE AND Id_Estado_Cbte = 0),0)
	SET @Nro_Cbte_ND =  (SELECT COMPROBANTE_NRO FROM Cbtes WHERE Id_Trans = @trans_ND)
	SET @Id_Tipo_Cbte = 'COB'

	SET @desc = 'CW:' + @LOTE
	SET @id_cliente = (SELECT id_cliente FROM Cbtes WHERE Id_Trans = @trans_ND)
	SET @FECHA = (SELECT Fecha FROM Cbtes WHERE Id_Trans = @trans_ND)
	SET @Importe = (SELECT Imp_Total FROM Cbtes WHERE Id_Trans = @trans_ND)
	SET @Nombre = (SELECT rtrim(Razon_Social) FROM Clientes WHERE Id_Cliente = @Id_Cliente)

	SET @trans_rec = (SELECT max(id_trans) from transacciones ) + 1
	INSERT INTO TRANSACCIONES (id_trans,descripcion,fecha_mov) values (@trans_rec,@desc,GETDATE())
	IF (@@ERROR <> 0)
	BEGIN
		ROLLBACK
		RETURN 1
	END

	SET @NRO_CBTE = (SELECT PROX_NRO from CBTES_TIPOS WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte) 
	UPDATE CBTES_TIPOS SET PROX_NRO = PROX_NRO+1 WHERE ID_TIPO_CBTE = @Id_Tipo_Cbte
	IF (@@ERROR <> 0)
	BEGIN
		ROLLBACK
		RETURN 1
	END

	INSERT INTO CBTES (Id_Cond_Vta,Id_trans,Id_Sucursal,Cbte_Grupo, Fecha_Venc ,    id_cliente, id_estado_Cbte  ,id_tipo_cbte, comprobante_nro,fecha,periodo_iva,periodo,imp_total,saldo,imp_gravado,destinatario,lote,ID_MONEDA,Id_Cond_Pago,Cotizacion)
				values ('',@trans_rec,1   ,0         ,@FECHA    ,@id_cliente,0 ,@Id_Tipo_cbte,@NRO_CBTE,@FECHA,@FECHA,@FECHA, @Importe ,0,@Importe,@NOMBRE,@desc,'PES',10,1)
	IF (@@ERROR <> 0)
	BEGIN
		ROLLBACK
		RETURN 1
	END

	SET @Observacion = ('ND  C 0001-' +	RIGHT('00000000' + LTRIM(RTRIM(@Nro_Cbte_ND)),8))
								
	PRINT 'Recibo: Se inserta Cbtes_Items'
	INSERT INTO Cbtes_Items (id_cliente,	descripcion_producto,	Cantidad,
							id_estado_Cbte,	Cantidad_Saldo,			Id_Trans,
							item,			Precio_Grav,			Imp_Gravado,
							Imp_Final,		Precio,					Lote,
							Fecha_QA,		Flag_QA,				Id_Producto,
							Imp_Exento,		Porc_Iva,				Bonif,
							Id_Usuario,     Observacion,            Precio_Exen,
							Id_Cond_Pago,   Bultos,                 Fecha_Venc,
							Costo,          Imp_Iva,			    calle, 
							columna,		fila, 					id_unidad_medida, 
							id_tarea,		id_pais,				cantidad_equiv, 
							costo_mo,		costo_gf,				flag_noimp_factura)							
					VALUES (@Id_Cliente,	'',						1,
							0				,0						,@Trans_rec,
							1,				0/*Precio_Grav*/,			@Importe,
							0/*Imp_Final*/,	0/*Precio*/,				'',
							NULL/*Fecha_QA*/, ''/*Flag_QA*/,			'', 
							0,				0,							0,
							0,				@Observacion,				0,
							0/*Id_Cond_Pago*/,0,						@Fecha, 
							0,                0,						'',
							'',				  '',						'',
							0,				  '',						0, 
							0,				  0,						0)
						
					
	IF (@@ERROR <> 0)
	BEGIN
		ROLLBACK
		RETURN 1
	END	 

	SET @Descrip_Cbte_CtaCte = 'COB C 0001-' + RIGHT('0000000' + LTRIM(CAST(@NRO_CBTE AS CHAR(8))),8)

	INSERT INTO CLIENTES_CTACTE  (Id_Trans,Nro_Cuota,Id_Empresa,Id_Cliente,Fecha,Fecha_Vence,Descripcion,Importe,Id_Estado_Cbte,Observacion,Id_Trans_Origen,Nro_Cuota_Origen,Id_Moneda,Saldo,Nro_FacCre)
			VALUES (@trans_rec,1,NULL,@id_cliente,@Fecha,@Fecha,@Descrip_Cbte_CtaCte,@Importe ,1,'',0,0,'PES',0,0)
	IF (@@ERROR <> 0)
	BEGIN
		ROLLBACK
		RETURN 1
	END         

	/*Insert: CAJAS_MOV*/	
	PRINT 'Inserto en Cajas_Mov'
	INSERT INTO Cajas_Mov	(Id_Trans,			Renglon_Nro	,		Id_Estado_Mov_Caja, 
							Importe,			Descripcion,		Id_Periodo_Caja,
							Id_Tipo_Mov_Caja,	Fecha) 
					VALUES	(@trans_rec,		1,					2, 
							@Importe,			@Descrip_Cbte_CtaCte,@Id_Periodo_Caja,
							7,					@Fecha)
					

	IF (@@ERROR <> 0)
	BEGIN
		ROLLBACK
		RETURN 1
	END	 
	/*FIN Insert: CAJAS_MOV*/
	/*---------------------------------------------------------------------------------*/
	/*Insert: CBTES_APLICA*/	
	PRINT 'Inserto en Cbtes Aplica'
	INSERT INTO Cbtes_Aplica	(Id_Trans,	Item	,	Id_Trans_D, 
								Item_D,		Cantidad,	Importe) 
						VALUES	(@trans_ND,	1,		@trans_rec, 
								1,				0,		@Importe)
						

	IF (@@ERROR <> 0)
	BEGIN
		ROLLBACK
		RETURN
	END	 
	/*FIN Insert: CBTES_APLICA*/
	

END 
/*Insert: VALORES*/	
SET @Id_Valor			= (SELECT MAX(id_valor) FROM valores ) + 1
PRINT 'Inserto en Valores'
INSERT INTO Valores	(Id_Valor,			Id_Valor_Origen,	Id_Trans,
					Id_Estado_Valor,	Id_Tipo_Val,		Valor_Nro,
					Descripcion,		Id_Cliente,			Id_Proveedor,
					Id_Banco,			Id_Cta_Banco,		Id_Mov_Caja,
					Id_Moneda,			Id_Tarjeta,			Tarjeta_Nro,
					Cotizacion,			Id_Periodo_Caja,	Propio,
					Transferible,		Tarjeta_Lote,		Id_Chequera,
					Renglon_Nro_Caja,	Flag_Conciliado,	Tarjeta_Cant_Cuotas,
					Tarjeta_Imp_Cuota,	Tarjeta_Crit_Cuota, Importe,Tarjeta_Cod_Autoriz) 
		VALUES		(@Id_Valor/*Id_Valor*/,	0/*Id_Valor_Origen*/,		@trans_rec/*Id_Trans*/,
					3/*Id_Estado_Valor*/,	'TAR'/*Id_Tipo_Val*/,		0/*Valor_Nro*/,
					'TARJETA'/*Descripcion*/,0/*Id_Cliente*/,	0/*Id_Proveedor*/,--aca y id_Valor
					0/*Id_Banco*/,			0/*Id_Cta_Banco*/,			0/*Id_Mov_Caja*/,
					'PES'/*Id_Moneda*/,		'MP'/*Id_Tarjeta*/,			0/*Tarjeta_Nro*/,
					1/*Cotizacion*/,		@Id_Periodo_Caja/*Id_Periodo_Caja*/,	0/*Propio*/,
					0/*Transferible*/,		0/*Tarjeta_Lote*/,			0/*Id_Chequera*/,
					1/*Renglon_Nro_Caja*/,	0/*Flag_Conciliado*/,		0/*Tarjeta_Cant_Cuotas*/,
					00/*Tarjeta_Imp_Cuota*/,0/*Tarjeta_Crit_Cuota*/,	@ImportePago,@TransPago)
					

IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN 1
END	 
/*FIN Insert: VALORES*/

/*---------------------------------------------------------------------------------*/

/*Insert: VALORES_MOV*/	
PRINT 'Inserto en Valores_Mov'
INSERT INTO Valores_Mov	(Id_Valor,			Renglon_Nro,		Id_Trans,
					Id_Motivo_Estado,		Id_Estado_Valor,	Id_Periodo_Caja,
					Descripcion,			Fecha_Acreditacion,	Fecha,
					Renglon_Nro_Caja) 
		VALUES		(@Id_Valor/*Id_Valor*/,	1/*Renglon_Nro*/,	@trans_rec/*Id_Trans*/,
					0/*Id_Motivo_Estado*/,	3/*Id_Estado_Valor*/,@Id_Periodo_Caja/*Id_Periodo_Caja*/,
					''/*Descripcion*/,		NULL/*Fecha_Acreditacion*/,@Fecha/*Fecha*/,
					1/*Renglon_Nro_Caja*/)
					

IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN 1
END	 
/*FIN Insert: VALORES_MOV*/




IF (@@ERROR = 0)
	COMMIT TRAN
ELSE
	ROLLBACK
GO

