CREATE PROCEDURE [dbo].[SP_Vitalicios_Hist] @pFecha_Desde DATETIME, @pFecha_Hasta DATETIME
AS

IF object_id('tempdb..#Categ_Ant') is null
BEGIN
    SELECT * INTO #Categ_Ant FROM Clientes_Tipos
END

IF object_id('tempdb..#VitaliciosPasajes') is null
BEGIN
    
	SELECT distinct ch.id_cliente,
	cl.Razon_Social,
	CAST(cl.Fecha_Nac as DATE) as Fecha_Nac,
	DATEDIFF(YEAR,cl.Fecha_Nac,GETDATE())as Edad,
	cl.Sexo,
	ch.Id_Tipo_Cli as Id_Categ_Anterior,
	clt2.Descripcion as Categ_Anterior,
	cl.Id_Tipo_Cli as Id_Categ_Actual,
	clt.Descripcion as Categ_Actual,
	MAX(CAST(ch.Fecha as DATE))as Fecha,
	cl.Activo,
	ch.Item
	into #VitaliciosPasajes
	from
	Clientes_Hist ch,
	Clientes cl,
	Clientes_Tipos clt,
	#Categ_Ant clt2

	where
	ch.Id_Cliente=cl.Id_Cliente
	and cl.id_tipo_cli=clt.id_tipo_cli
	and clt2.Id_Tipo_Cli=ch.Id_Tipo_Cli
	and ch.Fecha>=@pFecha_Desde AND ch.Fecha<= @pFecha_Hasta
	--and ch.Fecha>='20160701' AND ch.Fecha<= '20170630'
	and ch.Id_Tipo_Cli<>cl.Id_Tipo_Cli
	and (ch.Id_Tipo_Cli in (select id_tipo_cli from clientes_tipos where Descripcion like '%vital%')
		 or (ch.Id_Tipo_Cli = 1003 and cl.Id_Tipo_Cli = 1055))

	GROUP BY
	ch.id_cliente,
	cl.Razon_Social,
	cl.Fecha_Nac,
	cl.Sexo,
	ch.Id_Tipo_Cli,
	cl.Id_Tipo_Cli,
	clt.Descripcion,
	clt2.Descripcion ,
	ch.Fecha,
	cl.Activo,
	ch.Item

	ORDER BY 9, 2
END

IF object_id('tempdb..#itemMax') is null
BEGIN
	select max(Item) AS Item, v.Id_Cliente 
	into #itemMax
	from #VitaliciosPasajes v 
	group by v.Id_Cliente 
END

	SELECT
	v.id_cliente,
	Razon_Social,
	CAST(Fecha_Nac as DATE) as Fecha_Nac,
	Edad,
	Sexo,
	Id_Categ_Anterior,
	Categ_Anterior,
	Id_Categ_Actual,
	Categ_Actual,
	CAST(Fecha as DATE)as Fecha,
	Activo
	FROM #VitaliciosPasajes v, #itemMax i
	WHERE v.Id_Cliente=i.Id_Cliente
	and v.Item=i.Item
	
DROP Table #VitaliciosPasajes
DROP Table #itemMax
GO

