CREATE PROCEDURE [dbo].[SP_Vitalicios_Hist_V3] @pFecha_Desde DATETIME, @pFecha_Hasta DATETIME
AS

IF object_id('tempdb..#Categ_Ant') is null
BEGIN
    SELECT * INTO #Categ_Ant FROM Clientes_Tipos
END

IF object_id('tempdb..#VitaliciosPasajes') is null
BEGIN
    
	SELECT ant.Id_Tipo_Cli, cl.Id_Cliente,MIN(CAST(ant.Fecha as DATE)) as Fecha
	INTO #FechaCambioCat
	FROM Clientes_Hist ant, Clientes cl
	WHERE ant.Id_Cliente=cl.Id_Cliente
	and cl.Id_Tipo_Cli in (select id_tipo_cli from clientes_tipos where Descripcion like '%vital%')
	and ant.Id_Tipo_Cli=cl.Id_Tipo_Cli
	--AND CL.Id_Cliente in ( 589032,657431,653354,682253)
	and ant.fecha>=@pFecha_Desde AND ant.Fecha<=  @pFecha_Hasta
	and cl.Activo=1
	GROUP BY ant.Id_Tipo_Cli, cl.Id_Cliente

	SELECT ant.Id_Tipo_Cli, cl.Id_Cliente,MAX(Item) as Item
	INTO #Postulados
	FROM Clientes_Hist ant, Clientes cl
	WHERE ant.Id_Cliente=cl.Id_Cliente
	and cl.Id_Tipo_Cli in (SELECT id_tipo_cli FROM clientes_tipos WHERE Descripcion like '%vital%')
	and ant.Id_Tipo_Cli<>cl.Id_Tipo_Cli
	--AND CL.Id_Cliente in ( 589032,657431,653354,682253)
	and cl.Activo=1
	GROUP BY ant.Id_Tipo_Cli, cl.Id_Cliente,cl.Id_Tipo_Cli
	HAVING MAX(Item) + 1 <= (SELECT MAX(Item) FROM Clientes_hist WHERE Id_Cliente=cl.Id_cliente AND fecha>=@pFecha_Desde AND Fecha<=  @pFecha_Hasta AND id_tipo_cli=cl.Id_tipo_cli )

	--select * from #Postulados
	SELECT DISTINCT cl.id_cliente,
	cl.Razon_Social,
	CAST(cl.Fecha_Nac as DATE) as Fecha_Nac,
	DATEDIFF(YEAR,cl.Fecha_Nac,GETDATE())as Edad,
	cl.Sexo,
	z.Id_Tipo_Cli as Id_Categ_Anterior,
	clt2.Descripcion as Categ_Anterior,
	cl.Id_Tipo_Cli as Id_Categ_Actual,
	clt.Descripcion as Categ_Actual,
	CAST(f.Fecha as DATE) as Fecha,
	cl.Activo,
	(z.Item + 1) as item
	INTO #VitaliciosPasajes
	FROM Clientes cl,
		Clientes_Tipos clt,
	    #Categ_Ant clt2,  
		#Postulados z,
		#FechaCambioCat f

	WHERE Cl.Id_Cliente=z.Id_cliente
	AND Cl.Id_Cliente=f.Id_cliente
	AND cl.id_tipo_cli=clt.id_tipo_cli
	and z.Id_Tipo_Cli=clt2.Id_Tipo_Cli 
	and cl.Id_Tipo_Cli in (select id_tipo_cli from clientes_tipos where Descripcion like '%vital%')
	--AND CL.Id_Cliente in (589032,657431,653354,682253)
	and cl.Activo=1
END

--select * from #VitaliciosPasajes
IF object_id('tempdb..#itemMax') is null
BEGIN
	SELECT max(Item) AS Item, v.Id_Cliente 
	INTO #itemMax
	FROM #VitaliciosPasajes v 
	GROUP BY v.Id_Cliente 
END

	SELECT
	v.id_cliente,
	Razon_Social,
	CAST(Fecha_Nac as DATE) as Fecha_Nac,
	Edad,
	Sexo,
	Id_Categ_Anterior,
	Categ_Anterior,
	Id_Categ_Actual,
	Categ_Actual,
	CAST(Fecha as DATE)as Fecha,
	Activo
	FROM #VitaliciosPasajes v, #itemMax i
	WHERE v.Id_Cliente=i.Id_Cliente
	and v.Item=i.Item
	ORDER BY 1,2
	
DROP Table #VitaliciosPasajes
DROP Table #itemMax
DROP Table #Postulados
DROP Table #FechaCambioCat


