CREATE TRIGGER [dbo].[Tri_Clientes_VencCSAG] ON  [dbo].[Clientes]
AFTER INSERT

AS
SET NOCOUNT ON

DECLARE @Id_Cliente INT;
DECLARE @UCSAG		DATETIME;	
DECLARE [cur_TriCliVencCSAG] 
CURSOR FOR 
SELECT Id_Cliente FROM Inserted WHERE Id_Tipo_Cli NOT IN (1113/*Visitas*/,1134/*BICICLETA*/)


OPEN [cur_TriCliVencCSAG]
FETCH NEXT FROM [cur_TriCliVencCSAG] INTO @Id_Cliente
WHILE @@FETCH_STATUS = 0
BEGIN	        
	
	/*Para Clientes Nuevos luego de que se generó el aguinaldo, por eso ya no lo pagan*/
	
	SET @UCSAG = (SELECT DATEADD(MONTH,6/*Cantidad de meses que se actualiza el vencimiento*/,MAX(FECHA_QA)) FROM CBTES_ITEMS WHERE ID_PRODUCTO = 'CAGUIN' AND DATEPART(YY,FECHA_QA) = DATEPART(YY,GETDATE()))
	
	EXEC dbo.SP_Venc_CSAG @Id_Cliente, 0, @UCSAG
		
    FETCH NEXT FROM [cur_TriCliVencCSAG] INTO @Id_Cliente

END
CLOSE [cur_TriCliVencCSAG]
DEALLOCATE [cur_TriCliVencCSAG]
GO


