CREATE TRIGGER [dbo].[Tri_Contratos_Prod_Inscrip] ON [dbo].[Contratos_Prod]
WITH EXECUTE AS CALLER
AFTER INSERT

AS
SET NOCOUNT ON

DECLARE @Id_Contrato	INT
DECLARE @Id_Producto	VARCHAR(14)
DECLARE @Fecha_Hasta	DATETIME
DECLARE @Fecha_Desde	DATETIME

DECLARE ContInsCur 
CURSOR FOR
SELECT  Id_Contrato, Id_Producto FROM Inserted 

OPEN ContInsCur
FETCH NEXT FROM ContInsCur INTO  @Id_Contrato, @Id_Producto
WHILE @@FETCH_STATUS = 0
BEGIN
    
    IF (@Id_Producto IN (select Id_Producto from prod_familias_salas pfs , prod_salas ps 
											where pfs.id_prod_familia_sala=ps.id_prod_familia_sala
											and id_producto not in 
																(select Id_producto 
																 from productos 
																 where Descripcion_Detallada like '%CUOTA%')))
    BEGIN
		UPDATE Contratos SET Fecha_Desde=GETDATE(),ID_TIEMPO='AÑO', Fecha_Cob_Hasta=FECHA_HASTA WHERE Id_Contrato=@Id_Contrato
    END
    ELSE
    BEGIN
		IF @Id_Producto = '2450'
		BEGIN
			SET @Fecha_Hasta = (SELECT DATEADD(month,12,GETDATE()))
			UPDATE Contratos SET Fecha_Hasta=@Fecha_Hasta WHERE Id_Contrato=@Id_Contrato
		END
		IF @Id_Producto = '2449'
		BEGIN
			 --SET @Fecha_Desde = (select LEFT(CONVERT(char(4), getdate(), 112), 6)+ '0801')
			 SET @Fecha_Hasta = '20231231'
			UPDATE Contratos SET  Fecha_Desde=@Fecha_Desde, Fecha_Hasta=@Fecha_Hasta WHERE Id_Contrato=@Id_Contrato
		END
		IF @Id_Producto = '2375'
		BEGIN
			 --SET @Fecha_Desde = (select LEFT(CONVERT(char(4), getdate(), 112), 6)+ '0301')
			 SET @Fecha_Hasta = '20230731'
			UPDATE Contratos SET  Fecha_Desde=@Fecha_Desde, Fecha_Hasta=@Fecha_Hasta WHERE Id_Contrato=@Id_Contrato
		END
    END

   
    FETCH NEXT FROM ContInsCur INTO  @Id_Contrato, @Id_Producto
    
END
CLOSE ContInsCur
DEALLOCATE ContInsCur
GO

