CREATE TRIGGER [dbo].[Tri_Ult_Cuota_Paga]
ON [dbo].[Cbtes]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    ----------------------------------------------------------------
    -- 1. Identificar comprobantes válidos para procesar
    ----------------------------------------------------------------
    ;WITH CbtesValidos AS (
        SELECT DISTINCT
            I.Id_Trans
        FROM Inserted I
        LEFT JOIN Deleted D ON I.Id_Trans = D.Id_Trans
        INNER JOIN Cbtes_Tipos T ON I.Id_Tipo_Cbte = T.Id_Tipo_Cbte AND T.Id_Tipo_Cbte <> 'CPRO'
        WHERE
            (I.Saldo <> ISNULL(D.Saldo,0)
             OR I.Id_Estado_Cbte <> ISNULL(D.Id_Estado_Cbte,0)
             OR I.Id_Cliente <> ISNULL(D.Id_Cliente,0))
          AND (T.Compromete_Factura IN (1, -1)
               OR T.Compromete_Recibos IN (1, -1))
    )
    ----------------------------------------------------------------
    -- 2. Obtener todos los ítems de esos comprobantes
    ----------------------------------------------------------------
    SELECT 
        C.Id_Trans,
        CI.Item,
        CI.Id_Producto
    INTO #ItemsProcesar
    FROM CbtesValidos C
    INNER JOIN Cbtes_Items CI ON C.Id_Trans = CI.Id_Trans;

    ----------------------------------------------------------------
    -- 3. Ejecutar el SP por cada ítem
    -- (Si SP_Ult_Cuota_Paga no acepta modo set-based, se mantiene cursor único)
    ----------------------------------------------------------------
    DECLARE @Id_Trans INT,
            @Item SMALLINT,
            @Id_Producto VARCHAR(14);

    DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT Id_Trans, Item, Id_Producto
        FROM #ItemsProcesar;

    OPEN cur;
    FETCH NEXT FROM cur INTO @Id_Trans, @Item, @Id_Producto;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC dbo.SP_Ult_Cuota_Paga @Id_Trans, @Item, @Id_Producto;
        FETCH NEXT FROM cur INTO @Id_Trans, @Item, @Id_Producto;
    END;

    CLOSE cur;
    DEALLOCATE cur;

    DROP TABLE #ItemsProcesar;

END
GO

