CREATE PROCEDURE [dbo].[cp_grupo_familiar] @Id_Cliente INT
AS 
DECLARE @id_cliente_ref		INT
DECLARE @id_cliente_tit		INT
DECLARE @Total_grupo		INT

	--Busco el id_cliente_ref del socio que nos pasan
	SET @id_cliente_ref = (select id_cliente_ref from clientes where id_cliente = @Id_Cliente)
	
print @id_cliente_ref
	
	--si nos pasan el Id_Cliente del titular
IF (@id_cliente_ref = null or @id_cliente_ref = 0)
	BEGIN
		PRINT 'Nos pasaron un Titular, Id_cliente Obtenido: ' + CONVERT(VARCHAR(10), @Id_Cliente, 103)
		
	SET @Total_grupo = (select count(id_cliente_ref) from clientes where id_cliente_ref = @Id_Cliente)
	
	IF(@Total_grupo = 0)
		BEGIN
		
		PRINT 'No Tiene Grupo Familiar: '+ CONVERT(VARCHAR(10), @Total_grupo, 103)
		
	END
	
	ELSE
		BEGIN	
			select id_cliente,razon_social,id_cliente_ref from clientes
			where id_cliente_ref = @Id_Cliente
			UNION
			select id_cliente,razon_social,id_cliente_ref 
			from clientes 
			where id_cliente = @Id_Cliente
	END
		
			
END
	
	--Si nos pasan el id_cliente del integrante
ELSE	
	BEGIN
		PRINT 'Nos pasaron un Integramte, Id_cliente Obtenido: ' + CONVERT(VARCHAR(10), @id_cliente_ref, 103)
			select id_cliente,razon_social,id_cliente_ref from clientes
			where id_cliente_ref = @id_cliente_ref
			UNION
			select id_cliente,razon_social,id_cliente_ref 
			from clientes 
			where id_cliente = @id_cliente_ref
	
END
			
