create FUNCTION [dbo].[sf_GenerarDescripcionNroCbte](@id_tipo_cbte CHAR(4), @comprobante_nro INT)
RETURNS VARCHAR(50)	
AS

BEGIN
DECLARE @id_sucursal SMALLINT;
DECLARE @Descripcion VARCHAR(50);
DECLARE @sucursal_char VARCHAR(4);
DECLARE @comprobante_nro_char VARCHAR(9);
DECLARE @Letra CHAR(3);
DECLARE @Descrip_Corta CHAR(4);

SET @id_sucursal = (SELECT id_Sucursal FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @id_tipo_cbte);
SET @Letra = (SELECT Letra FROM Cbtes_Tipos WHERE Id_Tipo_Cbte=@id_tipo_cbte);
SET @Descrip_Corta = (SELECT Descrip_Corta FROM Cbtes_Tipos WHERE Id_Tipo_Cbte=@id_tipo_cbte);
SET @sucursal_char = (SELECT RIGHT('0000'+CAST(@id_sucursal AS VARCHAR(4)), 4));
SET @comprobante_nro_char = (SELECT RIGHT('00000000'+CAST(@comprobante_nro AS VARCHAR(9)), 8));

SET @Descripcion = (@Descrip_Corta+' '+@Letra+' '+@sucursal_char+'-'+@comprobante_nro_char);

RETURN @Descripcion;

END
GO



