CREATE FUNCTION [dbo].[sf_nro_socio](@Id_Cliente INT)  
RETURNS VARCHAR(10) AS  
BEGIN 
	DECLARE @Id_Tipo_Cli				SMALLINT
    DECLARE @Id_Cliente_Externo_Prox	VARCHAR(14)
	DECLARE @Id_Cliente_Externo_Prox_Int INT
	
	SET @Id_Tipo_Cli = (SELECT ISNULL(Id_Tipo_Cli, 0) FROM Clientes WHERE Id_Cliente = @Id_Cliente)
	
	IF (@Id_Tipo_Cli = 0)
	BEGIN
		SET @Id_Cliente_Externo_Prox = '0'
		RETURN ISNULL(@Id_Cliente_Externo_Prox, '0')
	END
	
	IF @Id_Tipo_Cli IN (1005,1006) /*Empleados*/
	BEGIN
	
		SET @Id_Cliente_Externo_Prox_Int = (SELECT MAX(CONVERT(INT,ISNULL(Id_Cliente_Externo,'0')))+1 
											FROM Clientes 
											WHERE 
											Id_Tipo_Cli IN (1005,1006))
											
		SET @Id_Cliente_Externo_Prox = CONVERT(VARCHAR(14), @Id_Cliente_Externo_Prox_Int)

		RETURN ISNULL(@Id_Cliente_Externo_Prox, '0')
	END
	
	IF @Id_Tipo_Cli IN (
				1000        ,    --   INFANTIL
				1001        ,    --   CADETE
				1002        ,    --   ACTIVO MENOR
				1003        ,    --   ACTIVO MAYOR
				1004        ,    --   ACOMPAÑANTE
				1007        ,    --   USUARIO GEBA GYM
				1008        ,    --   USUARIO
				1010        ,    --   VITALICIO + 71
				1011        ,    --   RESOLUCION 95
				1012        ,    --   USUARIO RCA
				1013        ,    --   USUARIO AFIP
				1014        ,    --   USUARIO J.N.
				1016        ,    --   USUARIO S.M. / JM
				1017        ,    --   USUARIO +75
				1020        ,    --   VITALICIOS RES.20
				1055        ,    --   VITALICIO 48/55
				1060        ,    --   VITALICIO 56/60
				1065        ,    --   VITALICIO 61/65
				1070        ,    --   VITALICIO 66/70
				1100        ,    --   SOCIO HONORARIO
				1019        ,    --   COLEGIOS
				1102        ,    --   CC FAMILY GOLD
				1111		,	 --	  USUARIO PROMO VERANO MAYOR (* Agregado por solicitud ticket nro 12278)
				1112		,	 --   USUARIO PROMO VERANO MENOR (* Agregado por solicitud ticket nro 12278)		
				1115		,	 --	  INFANTIL + SC
				1116		,	 --	  CADETE + SC
				1117		,	 --	  ACTIVO MENOR + SC
				1118		,	 --	  ACTIVO MAYOR + SC
				1119		,	 --	  ACTIVO MAYOR + PFC
				1120		,	 --	  ACTIVO MENOR + PFC
				1121		,	 --	  CADETE + PFC
				1122		,	 --	  INFANTIL + PFC
				1123		,	 --	  RESIDENTE EXTERIOR
				1130		,	 --	  ACTIVO +71
				1106			 --	  PRE-INFANTIL
--				1005        ,    --   conyugue empledo
--				1006             --   empeado
              )

	BEGIN
	
		SET @Id_Cliente_Externo_Prox_Int = (SELECT MAX(CONVERT(INT,ISNULL(Id_Cliente_Externo,'0')))+1 
											FROM Clientes 
											WHERE 
											Id_Tipo_Cli IN (
											1000        ,    --   INFANTIL
											1001        ,    --   CADETE
											1002        ,    --   ACTIVO MENOR
											1003        ,    --   ACTIVO MAYOR
											1004        ,    --   ACOMPAÑANTE
											1007        ,    --   USUARIO GEBA GYM
											1008        ,    --   USUARIO
											1010        ,    --   VITALICIO + 71
											1011        ,    --   RESOLUCION 95
											1012        ,    --   USUARIO RCA
											1013        ,    --   USUARIO AFIP
											1014        ,    --   USUARIO J.N.
											1016        ,    --   USUARIO S.M. / JM
											1017        ,    --   USUARIO +75
											1020        ,    --   VITALICIOS RES.20
											1055        ,    --   VITALICIO 48/55
											1060        ,    --   VITALICIO 56/60
											1065        ,    --   VITALICIO 61/65
											1070        ,    --   VITALICIO 66/70
											1100        ,    --   SOCIO HONORARIO
											1019        ,    --   COLEGIOS
											1102        ,    --   CC FAMILY GOLD
											1111		,	 --	  USUARIO PROMO VERANO MAYOR (* Agregado por solicitud ticket nro 12278)
											1112		,	 --   USUARIO PROMO VERANO MENOR (* Agregado por solicitud ticket nro 12278)
											1115		,	 --	  INFANTIL + SC
											1116		,	 --	  CADETE + SC
											1117		,	 --	  ACTIVO MENOR + SC
											1118		,	 --	  ACTIVO MAYOR + SC
											1119		,	 --	  ACTIVO MAYOR + PFC
											1120		,	 --	  ACTIVO MENOR + PFC
											1121		,	 --	  CADETE + PFC
											1122		,	 --	  INFANTIL + PFC
											1123		,	 --	  RESIDENTE EXTERIOR
											1130		,	 --	  ACTIVO +71
											1106			 --	  PRE-INFANTIL
							--				1005        ,    --   conyugue empledo
							--				1006             --   empeado 
              							))
              								
		SET @Id_Cliente_Externo_Prox = CONVERT(VARCHAR(14),@Id_Cliente_Externo_Prox_Int)

		RETURN ISNULL(@Id_Cliente_Externo_Prox, '0')
	END
	
    IF @Id_Tipo_Cli IN (1015) /*Concesionario*/
	BEGIN
	
		SET @Id_Cliente_Externo_Prox_Int = (SELECT MAX(CONVERT(INT,ISNULL(Id_Cliente_Externo,'0')))+1 
											FROM Clientes 
											WHERE 
											Id_Tipo_Cli IN (1015))
											
		SET @Id_Cliente_Externo_Prox = CONVERT(VARCHAR(14),@Id_Cliente_Externo_Prox_Int)

		RETURN ISNULL(@Id_Cliente_Externo_Prox, '0')
	END 
	
	IF @Id_Tipo_Cli IN (1018, 1114) /*INVITADOS*/
	BEGIN
	
    	--SET @Id_Cliente_Externo_Prox_Int = (SELECT MAX(CONVERT(INT,ISNULL(Id_Cliente_Externo,'0')))+1 
	    --FROM Clientes WHERE Id_Tipo_Cli IN (1018))
	    --SET @Id_Cliente_Externo_Prox = CONVERT(VARCHAR(14),@Id_Cliente_Externo_Prox_Int)
	
        SET @Id_Cliente_Externo_Prox = (SELECT ISNULL(Doc_Nro, '0') from Clientes where Id_Cliente = @Id_Cliente)
              
		RETURN ISNULL(@Id_Cliente_Externo_Prox, '0')	
	END
	
	IF @Id_Tipo_Cli IN (1104) /*USUARIO TRIAR*/
	BEGIN
	
		SET @Id_Cliente_Externo_Prox_Int = (SELECT CONVERT(INT, SUBSTRING(LTRIM(RTRIM(ISNULL(Id_Cliente_Externo, '000000'))),3,6))+1
											FROM Clientes 
											WHERE 
											Id_Tipo_Cli IN (1104))
											
		SET @Id_Cliente_Externo_Prox = 'TR' + RIGHT('000000' + @Id_Cliente_Externo_Prox_Int, 6)		

		RETURN ISNULL(@Id_Cliente_Externo_Prox, '0')
	END
     
    RETURN ISNULL(@Id_Cliente_Externo_Prox, '0')
END
GO


	CREATE PROCEDURE dbo.sp_alterdiagram
	(
		@diagramname 	sysname,
		@owner_id	int	= null,
		@version 	int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId 			int
		declare @retval 		int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
		declare @ShouldChangeUID	int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid ARG', 16, 1)
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();	 
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		revert;
	
		select @ShouldChangeUID = 0
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		
		if(@DiagId IS NULL or (@IsDbo = 0 and @theId <> @UIDFound))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end
	
		if(@IsDbo <> 0)
		begin
			if(@UIDFound is null or USER_NAME(@UIDFound) is null) -- invalid principal_id
			begin
				select @ShouldChangeUID = 1 ;
			end
		end

		-- update dds data			
		update dbo.sysdiagrams set definition = @definition where diagram_id = @DiagId ;

		-- change owner
		if(@ShouldChangeUID = 1)
			update dbo.sysdiagrams set principal_id = @theId where diagram_id = @DiagId ;

		-- update dds version
		if(@version is not null)
			update dbo.sysdiagrams set version = @version where diagram_id = @DiagId ;

		return 0
	END
GO


	CREATE PROCEDURE dbo.sp_creatediagram
	(
		@diagramname 	sysname,
		@owner_id		int	= null, 	
		@version 		int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId int
		declare @retval int
		declare @IsDbo	int
		declare @userName sysname
		if(@version is null or @diagramname is null)
		begin
			RAISERROR (N'E_INVALIDARG', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID(); 
		select @IsDbo = IS_MEMBER(N'db_owner');
		revert; 
		
		if @owner_id is null
		begin
			select @owner_id = @theId;
		end
		else
		begin
			if @theId <> @owner_id
			begin
				if @IsDbo = 0
				begin
					RAISERROR (N'E_INVALIDARG', 16, 1);
					return -1
				end
				select @theId = @owner_id
			end
		end
		-- next 2 line only for test, will be removed after define name unique
		if EXISTS(select diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @diagramname)
		begin
			RAISERROR ('The name is already used.', 16, 1);
			return -2
		end
	
		insert into dbo.sysdiagrams(name, principal_id , version, definition)
				VALUES(@diagramname, @theId, @version, @definition) ;
		
		select @retval = @@IDENTITY 
		return @retval
	END
GO


	CREATE PROCEDURE dbo.sp_dropdiagram
	(
		@diagramname 	sysname,
		@owner_id	int	= null
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
		declare @theId 			int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid value', 16, 1);
			return -1
		end
	
		EXECUTE AS CALLER;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		REVERT; 
		
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
			return -3
		end
	
		delete from dbo.sysdiagrams where diagram_id = @DiagId;
	
		return 0;
	END
GO

CREATE PROCEDURE [dbo].[sp_generar_asiento_COBRANZAS] @ID_TRANS INT
       AS 

          IF ((SELECT Id_Estado_Cbte FROM CBTES WHERE ID_TRANS = @ID_TRANS) = 3) 
		      RETURN

	      BEGIN TRAN

   	            DECLARE @ID_cliente INTEGER
				DECLARE @ALIAS INTEGER
				Declare @id_producto varchar(15)
				Declare @Importe decimal(14,4)
				Declare @DEBE decimal(12,2)	
				Declare @HABER decimal(12,2)
                declare @id_cta_contable integer
	        	declare @fecha_mov datetime
			  	declare @FECHA_QA datetime
                declare @id_CENTRO_COSTO varchar(5)
                declare @ITEM INTEGER
				declare @RENGLON INTEGER

    	SET @fecha_mov = (SELECT fecha from cbtes where id_trans = @ID_TRANS) 

        ----------------------------- Primero los insert ----------------------------------

        SELECT CC.* INTO #CBTES_CTAS_CONTABLES_aux_sp FROM CBTES_CTAS_CONTABLES CC, CBTES_TIPOS T, CBTES_APLICA A, CBTES C
		WHERE C.ID_TRANS = @ID_TRANS AND C.ID_TIPO_CBTE = T.ID_TIPO_CBTE AND T.Compromete_Recibos = 1 
		      AND C.ID_TRANS = A.ID_TRANS_D AND A.ID_TRANS = CC.ID_TRANS AND CC.HABER = 0

        SET @ITEM = (SELECT COUNT(*) FROM #CBTES_CTAS_CONTABLES_aux_sp)

		IF @ITEM <> 0
		   BEGIN 

		     UPDATE #CBTES_CTAS_CONTABLES_aux_sp SET ID_TRANS =  @ID_TRANS, FECHA =  @fecha_mov, HABER = DEBE
		     UPDATE #CBTES_CTAS_CONTABLES_aux_sp SET DEBE = 0, ITEM = 0


			 INSERT INTO #CBTES_CTAS_CONTABLES_aux_sp 
		         SELECT * FROM CBTES_CTAS_CONTABLES WHERE ID_TRANS =  @ID_TRANS AND HABER = 0

			 DELETE #CBTES_CTAS_CONTABLES_aux_sp WHERE DEBE = 0 AND HABER = 0 

			 SELECT  ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO,SUM(DEBE) DEBE,SUM(HABER) HABER INTO #RESUMEN_ASIENTO
			        FROM #CBTES_CTAS_CONTABLES_aux_sp GROUP BY ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO ORDER BY HABER

			 SET @Importe = ROUND((SELECT SUM(DEBE)/SUM(HABER) FROM  #RESUMEN_ASIENTO),4)
	
		     UPDATE #RESUMEN_ASIENTO SET HABER = HABER * @Importe

             SET @DEBE =  (SELECT SUM(DEBE) FROM  #RESUMEN_ASIENTO)
             SET @HABER = (SELECT SUM(HABER) FROM  #RESUMEN_ASIENTO)
             SET @IMPORTE = @DEBE-@HABER

			 ALTER TABLE #RESUMEN_ASIENTO ADD  ITEM INT IDENTITY (1,1) 

			 ALTER TABLE #RESUMEN_ASIENTO ADD OBSERVACION VARCHAR(100), ID_ASIENTO INT

			 SET @RENGLON = (SELECT MAX(ITEM) FROM #RESUMEN_ASIENTO)

			 UPDATE #RESUMEN_ASIENTO SET HABER = HABER + @IMPORTE WHERE ITEM =  @RENGLON

             DELETE CBTES_CTAS_CONTABLES WHERE ID_TRANS =  @ID_TRANS 

		     INSERT INTO CBTES_CTAS_CONTABLES (ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO,DEBE,HABER,ITEM,OBSERVACION,ID_ASIENTO)
		         SELECT * FROM #RESUMEN_ASIENTO 
           END

           DROP TABLE #CBTES_CTAS_CONTABLES_aux_sp
           DROP TABLE #RESUMEN_ASIENTO 

         IF (@@ERROR = 0)
		     COMMIT TRAN
	     ELSE
		     ROLLBACK

Select 0
GO

CREATE PROCEDURE [dbo].[sp_generar_asiento_Factura] @ID_TRANS INT
       AS 

---          execute SP_generar_stock @ID_TRANS
          IF ((SELECT Id_Estado_Cbte FROM CBTES WHERE ID_TRANS = @ID_TRANS) = 3) 
		      RETURN
          IF ((SELECT Id_Cond_Pago FROM CBTES WHERE ID_TRANS = @ID_TRANS) = 1) 
		      RETURN
	      
		  BEGIN TRAN

   	            DECLARE @ID_cliente INTEGER
				DECLARE @ALIAS INTEGER
				Declare @id_producto varchar(15)
				Declare @Importe decimal(12,2)
				Declare @DEBE decimal(12,2)	
				Declare @HABER decimal(12,2)
                declare @id_cta_contable integer
	        	declare @fecha_mov datetime
			  	declare @FECHA_QA datetime
                declare @id_CENTRO_COSTO varchar(5)
                declare @ITEM INTEGER
				Declare @Imp_Gravado decimal(12,2)
				Declare @Imp_Iva decimal(12,2)

    	
		
		SET @fecha_mov = (SELECT fecha from cbtes where id_trans = @ID_TRANS) 

        ----------------------------- Primero los insert ----------------------------------

        SELECT * INTO #CBTES_CTAS_CONTABLES_aux_sp FROM CBTES_CTAS_CONTABLES WHERE ID_TRANS = @ID_TRANS
		DELETE #CBTES_CTAS_CONTABLES_aux_sp

        DECLARE MicursorAsiento CURSOR FOR 
		SELECT id_producto,ID_CLIENTE,FECHA_QA,Imp_Final,Imp_Gravado,Imp_Iva 
		FROM CBTES_ITEMS 
		WHERE ID_TRANS = @ID_TRANS 
		AND Imp_Final <> 0

               OPEN MicursorAsiento
                    FETCH NEXT FROM MicursorAsiento INTO @id_producto,@Id_Cliente,@FECHA_QA,@Importe,@Imp_Gravado,@Imp_Iva
                    WHILE @@fetch_status = 0 
                    BEGIN
				        -- Genero Asiento en el Debe
						SET @Alias = (SELECT isnull(Id_Alias_Cta_Deudores,0) from Productos where id_producto = @ID_Producto) 
						If @Alias = 0
						   SET @Alias = (SELECT isnull(Id_Alias_Cta_Cont_Venta,0) from Clientes where Id_Cliente = @ID_CLIENTE)

                        set @id_cta_contable =  DBO.SF_Cta_Cont(@Alias,@fecha_mov) 
						    
                        INSERT into #CBTES_CTAS_CONTABLES_aux_sp (
								Id_Trans,
								Item,
								Id_Cta_Contable,
								Fecha,                     
								Debe,
								Haber,
								Alias,
								Id_Centro_Costo)
								VALUES (@ID_TRANS,1,@id_cta_contable,@fecha_mov,@importe,0,@ALIAS,'')						    
                                  
						-- Genero Aiento en el Haber
						IF @ID_PRODUCTO = 'CS'
						   BEGIN
						     SET @Id_producto = DBO.SF_Prod(@id_cliente,@fecha_mov) 
					         IF @FECHA_QA <= @fecha_mov
					              SET @Alias = (SELECT isnull(Id_Alias_Cta_Cont,0) from Productos where Id_producto = @ID_PRODUCTO) 
						      ELSE
					              SET @Alias = (SELECT isnull(Id_Alias_Cta_Vtas_Anticip,0) from Productos where Id_producto = @ID_PRODUCTO) 
                           END
                          ELSE
						   BEGIN 
							  IF @FECHA_QA <= @fecha_mov
							      BEGIN
					    	      SET @Alias = (SELECT isnull(Id_Alias_Cta_Cont,0) from Productos where id_producto = @ID_Producto)
								  PRINT(@Alias)
								  END
								ELSE
								  BEGIN
							        SET @Alias = (SELECT isnull(Id_Alias_Cta_Vtas_Anticip,0) from Productos where id_producto = @ID_Producto)
                                    IF @Alias = 0
							           SET @Alias = (SELECT isnull(Id_Alias_Cta_Cont,0) from Productos where id_producto = @ID_Producto)
                                  END
					       END
                           set @id_cta_contable =  DBO.SF_Cta_Cont(@Alias,@fecha_mov)
          		  	       SET @id_CENTRO_COSTO = (SELECT ID_CENTRO_COSTO from PRODUCTOS where id_producto = @ID_PRODUCTO) 
          		  	        
	                       IF @imp_Gravado <> 0
						      BEGIN					    
								   INSERT into #CBTES_CTAS_CONTABLES_aux_sp (
										Id_Trans,
										Item,
										Id_Cta_Contable,
										Fecha,                     
										Debe,
										Haber,
										Alias,
										Id_Centro_Costo)
										VALUES (@ID_TRANS,1,@id_cta_contable,@fecha_mov,0,@imp_Gravado,@ALIAS,@id_CENTRO_COSTO)
							  END			
                           IF @imp_Iva <> 0
						      BEGIN
							    Set @Alias =  (select Valor_Integer from xParametros where setDatos= 1 and idParametro ='Iva_Debito_Fiscal')
                                set @id_cta_contable =  DBO.SF_Cta_Cont(@Alias,@fecha_mov)
          		  	            SET @id_CENTRO_COSTO = '' 
						    
								   INSERT into #CBTES_CTAS_CONTABLES_aux_sp (
										Id_Trans,
										Item,
										Id_Cta_Contable,
										Fecha,                     
										Debe,
										Haber,
										Alias,
										Id_Centro_Costo)
										VALUES (@ID_TRANS,1,@id_cta_contable,@fecha_mov,0,@imp_Iva,@ALIAS,@id_CENTRO_COSTO)	
						      END
													    
                          Fetch next from MicursorAsiento into @id_producto,@Id_Cliente,@FECHA_QA,@Importe,@Imp_Gravado,@Imp_Iva
                    End       
               Close MicursorAsiento
               Deallocate MicursorAsiento
         
        SELECT ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO,SUM(DEBE) DEBE,SUM(HABER) HABER INTO #CBTES_CTAS_CONTABLES_RESUMEN
                       FROM #CBTES_CTAS_CONTABLES_aux_sp GROUP BY ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO 
        DELETE #CBTES_CTAS_CONTABLES_aux_sp

        SET @ITEM = 0
        Declare MicursorAsientoResumen cursor for 
        select ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO,DEBE,HABER from  #CBTES_CTAS_CONTABLES_RESUMEN WHERE ID_TRANS = @ID_TRANS ORDER BY HABER

               Open MicursorAsientoResumen
                    Fetch next from MicursorAsientoResumen into @ID_TRANS,@ID_CTA_CONTABLE,@fecha_mov,@ALIAS,@ID_CENTRO_COSTO,@DEBE,@HABER
                    While @@fetch_status = 0 
                    begin	
					      SET @ITEM = @ITEM + 1
                          INSERT into #CBTES_CTAS_CONTABLES_aux_sp (
								Id_Trans,
								Item,
								Id_Cta_Contable,
								Fecha,                     
								Debe,
								Haber,
								Alias,
								Id_Centro_Costo)
								VALUES (@ID_TRANS,@ITEM,@id_cta_contable,@fecha_mov,@debe,@haber,@ALIAS,@id_CENTRO_COSTO)						    
                
                         Fetch next from MicursorAsientoResumen into @ID_TRANS,@ID_CTA_CONTABLE,@fecha_mov,@ALIAS,@ID_CENTRO_COSTO,@DEBE,@HABER
                    End       

			   DELETE CBTES_CTAS_CONTABLES WHERE ID_TRANS = @ID_TRANS

			   INSERT INTO CBTES_CTAS_CONTABLES 
			          SELECT * FROM #CBTES_CTAS_CONTABLES_aux_sp

               Close MicursorAsientoResumen
               Deallocate MicursorAsientoResumen

         DROP TABLE #CBTES_CTAS_CONTABLES_aux_sp
		 DROP TABLE #CBTES_CTAS_CONTABLES_RESUMEN

         IF (@@ERROR = 0)
		     COMMIT TRAN
	     ELSE
		     ROLLBACK

 --select 0
 RETURN 0

----exec sp_generar_asiento_Factura 103855



---select * from cbtes_ctas_contables where id_trans = 158723
GO


CREATE PROCEDURE [dbo].[sp_generar_asiento_NCredito] @ID_TRANS INT
       AS 
---          execute SP_generar_stock @ID_TRANS
          IF ((SELECT Id_Estado_Cbte FROM CBTES WHERE ID_TRANS = @ID_TRANS) = 3) 
