							           SET @Alias = (SELECT isnull(Id_Alias_Cta_Cont,0) from Productos where id_producto = @ID_Producto)
							      END
					       END
                           set @id_cta_contable =  DBO.SF_Cta_Cont(@Alias,@fecha_mov)
          		  	       SET @id_CENTRO_COSTO = (SELECT ID_CENTRO_COSTO from PRODUCTOS where id_producto = 'BAJAART21') 
						    
                           INSERT into #CBTES_CTAS_CONTABLES_aux_sp (
								Id_Trans,
								Item,
								Id_Cta_Contable,
								Fecha,                     
								Debe,
								Haber,
								Alias,
								Id_Centro_Costo)
								VALUES (@ID_TRANS,1,@id_cta_contable,@fecha_mov,@importe,0,@ALIAS,@id_CENTRO_COSTO)						    
 
                         Fetch next from MicursorAsiento into @id_producto,@Id_Cliente,@FECHA_QA,@Importe
                    End       
               Close MicursorAsiento
               Deallocate MicursorAsiento
         
        SELECT ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO,SUM(DEBE) DEBE,SUM(HABER) HABER INTO #CBTES_CTAS_CONTABLES_RESUMEN
                       FROM #CBTES_CTAS_CONTABLES_aux_sp GROUP BY ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO
        DELETE #CBTES_CTAS_CONTABLES_aux_sp

        SET @ITEM = 0
        Declare MicursorAsientoResumen cursor for select ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO,DEBE,HABER from  #CBTES_CTAS_CONTABLES_RESUMEN WHERE ID_TRANS = @ID_TRANS

               Open MicursorAsientoResumen
                    Fetch next from MicursorAsientoResumen into @ID_TRANS,@ID_CTA_CONTABLE,@fecha_mov,@ALIAS,@ID_CENTRO_COSTO,@DEBE,@HABER
                    While @@fetch_status = 0 
                    begin	
					      SET @ITEM = @ITEM + 1
                          INSERT into #CBTES_CTAS_CONTABLES_aux_sp (
								Id_Trans,
								Item,
								Id_Cta_Contable,
								Fecha,                     
								Debe,
								Haber,
								Alias,
								Id_Centro_Costo)
								VALUES (@ID_TRANS,@ITEM,@id_cta_contable,@fecha_mov,@debe,@haber,@ALIAS,@id_CENTRO_COSTO)						    
                
                         Fetch next from MicursorAsientoResumen into @ID_TRANS,@ID_CTA_CONTABLE,@fecha_mov,@ALIAS,@ID_CENTRO_COSTO,@DEBE,@HABER
                    End       

			   DELETE CBTES_CTAS_CONTABLES WHERE ID_TRANS = @ID_TRANS

			   INSERT INTO CBTES_CTAS_CONTABLES 
			          SELECT * FROM #CBTES_CTAS_CONTABLES_aux_sp

               Close MicursorAsientoResumen
               Deallocate MicursorAsientoResumen

         --fin 
         DROP TABLE #CBTES_CTAS_CONTABLES_aux_sp
		 DROP TABLE #CBTES_CTAS_CONTABLES_RESUMEN

         IF (@@ERROR = 0)
		     COMMIT TRAN
	     ELSE
		     ROLLBACK

--SELECT 0
RETURN
GO

CREATE  PROCEDURE [dbo].[sp_generar_cbte] 
@Id_Cliente		INT, 
@Id_Producto	CHAR(14),
@Importe		DECIMAL(12,2), 
@Fecha			DATETIME, 
@Id_Tipo_Cbte	CHAR(4),
@Lote			CHAR(14),
@Id_Estado_Cbte INT,
@Id_Cond_Vta	CHAR(10),
@Cant			INT,
@Id_Cond_Pago	SMALLINT

AS 
/*-----------------------------------------------------
 * OJO!: Buscar la palabra CAMBIAR en estedocumento y 
 *		 adaptar las variables al cliente.
 ------------------------------------------------------*/
SET NOCOUNT ON 
BEGIN TRAN

PRINT 'Genero Comprobante Tipo: '+@Id_Tipo_Cbte+' para el Cliente: '+CONVERT(VARCHAR(20),@Id_Cliente)
PRINT 'Fecha del Comprobante: '+CONVERT(VARCHAR(20), @Fecha, 101)+' Estado Comprobante: '+CONVERT(VARCHAR(3),@id_Estado_Cbte)

/*Declaracion Variables Locales*/
DECLARE @Trans_Nueva			INT
DECLARE @Nro_Cbte				INT
DECLARE @Suc					INT
DECLARE @User					SMALLINT
DECLARE @Compromete_Factura		SMALLINT
DECLARE @Compromete_Recibo		SMALLINT
DECLARE @Compromete_Remito		SMALLINT
DECLARE @Desc					VARCHAR(50)
DECLARE @Nombre					VARCHAR(100)
DECLARE @Descripcion_Producto	VARCHAR(100)
DECLARE @Cantidad				DECIMAL(12,2)
DECLARE @Fecha_Mov				DATETIME
DECLARE @Descrip_Cbte_CtaCte	VARCHAR(100)
DECLARE @Signo					INT
DECLARE @ImporteXCant			DECIMAL(12,2)
DECLARE	@Observacion			VARCHAR(30)
/*FIN Declaracion Variables Locales*/

/*Asignacion Variables*/
SET @Descripcion_Producto	= (SELECT Descripcion_Resumida		FROM Productos	 WHERE Id_Producto  = @Id_Producto)
SET @Nombre					= (SELECT RTRIM(Razon_Social)		FROM Clientes	 WHERE Id_Cliente	= @Id_Cliente)
SET @Nro_Cbte				= ISNULL((SELECT Prox_Nro			FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte),1)
SET @Compromete_Factura		= ISNULL((SELECT Compromete_Factura	FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte),0)
SET @Compromete_Recibo		= ISNULL((SELECT Compromete_Recibos FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte),0)
SET @Compromete_Remito		= ISNULL((SELECT Compromete_Remitos	FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte),0)
SET @Suc					= ISNULL((SELECT Id_Sucursal		FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte),0)
SET @Trans_Nueva			= ISNULL((SELECT (MAX(id_trans)+1)	FROM Transacciones),1)
SET @Desc					= @Lote
SET @Observacion			= 'Comprobante Generado desde B.D.'
/*FIN Asignacion Variables*/

SET @Signo = 1

IF((@Compromete_Recibo = 1) OR (@Compromete_Factura = -1))
BEGIN
	SET @Signo = -1
END

/*---------------------------------------------------------------------------------*/

/*Insert: TRANSACCIONES*/
PRINT 'Inserto la Transaccion Nro: ' + CONVERT(VARCHAR(20), @Trans_Nueva)

INSERT INTO Transacciones	(Id_Trans,		Descripcion,	Fecha_Mov) 
VALUES						(@Trans_Nueva,	@Desc,			GETDATE())

IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN
END	 
/*FIN Insert: TRANSACCIONES*/

/*---------------------------------------------------------------------------------*/

/*Insert: CBTES*/
SET @ImporteXCant = (@Importe * @Cant)

PRINT 'Inserto en Cbtes'
INSERT INTO Cbtes			(Id_Trans,			Id_Sucursal,		Id_Tipo_Cbte,
							Cbte_Grupo,			Comprobante_Nro,	Id_Cliente,
							Id_Proveedor,		Signo,				Id_Estado_Cbte,
							Fecha,				Porc_DescEspecial,	Imp_Bonificacion,
							Imp_Gravado,		Imp_Exento,			Imp_IVA,
							Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
							Imp_Total,			Id_Usuario,			Porc_Iva3,
							Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
							Imp_IVA3,			Imp_Percep,			Saldo,
							Periodo_Iva,		Periodo,			Fecha_Venc,
							Observacion,		Id_Cond_Pago,		Cant_Cuotas,
							Cantidad,			Id_Lista,			Id_Moneda,
							Cotizacion,			Destinatario,		Id_Iva,
							Saldo_Iva_Recup,	Lote,				Id_Asiento,
							Id_Valor,			Cai,				Cantidad_Saldo,
							Saldo_Anterior,		Porc_DescFin,		Porc_Bonificacion,
							Porc_Iva,			Porc_Iva2,			Imp_Neto,
							Imp_DescEspecial,	Imp_DescFin)
VALUES						(@Trans_Nueva,		@Suc,				@Id_Tipo_cbte,
							0/*Cbte_Grupo*/,	@Nro_Cbte,			@Id_Cliente,
							0/*Id_Proveedor*/,	0/*Signo*/,			@Id_Estado_Cbte,
							@Fecha,				0/*Porc_DescEspec*/,0/*Imp_Bonificacion*/,
							0/*Imp_Gravado*/,	@ImporteXCant,		0/*Imp_Iva*/,
							0/*Imp_Iva2*/,		0/*Imp_Percepcion_*/,0/*Imp_Percepcion_Iva*/,
							@ImporteXCant,		0/*Id_Usuario*/,	27/*Porc_Iva3*/,
							0/*Imp_Gravado2*/,	0/*Imp_Gravado3*/,	0/*Imp_NoGravado*/,
							0/*Imp_IVA3*/,		0/*Imp_Percep*/,	@ImporteXCant,
							@Fecha,				@Fecha,				@Fecha,
							@Observacion,		@Id_Cond_Pago,		1/*Cant_Cuotas*/,
							0/*Cantidad*/,		0/*Id_Lista*/,		'PES'/*Id_Moneda*/,
							1/*Cotizacion*/,	@Nombre,			'CF'/*Id_Iva*/,
							0/*Saldo_Iva_Recu*/,@Lote,				0/*Id_Asiento*/,
							0/*Id_Valor*/,		0/*Cai*/,			0/*Cantidad_Saldo*/,
							0/*Saldo_Anterior*/,0/*Porc_DescFin*/,	0/*Porc_Bonificacion*/,
							21/*Porc_Iva*/,		'10.5'/*Porc_Iva2*/,@ImporteXCant,
							0/*Imp_DescEspecial*/,0/*Imp_DescFin*/)
							
IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN
END	 
/*FIN Insert: CBTES*/

/*---------------------------------------------------------------------------------*/

/*Insert: CBTES_ITEMS*/
PRINT 'Inserto en Cbtes_Items'
INSERT INTO Cbtes_Items		(Id_Cliente,	Descripcion_producto,	Cantidad,
							Id_Estado_Cbte,	Cantidad_Saldo,			Id_Trans,
							Item,			Precio_Grav,			Imp_Gravado,
							Imp_Final,		Precio,					Lote,
							Fecha_QA,		Flag_QA,				Id_Producto,
							Imp_Exento,		Porc_Iva,				Bonif,
							Id_Usuario)
VALUES						(@Id_Cliente,	RTRIM(@Descripcion_Producto),@Cant,
							@Id_Estado_Cbte,@Cant,					@trans_nueva,
							1,				@Importe,				(@Importe * @Cant),
							(@Importe * @Cant),@Importe,			@Lote,
							@Fecha,			'A',					@Id_Producto,
							0,				0,						0,
							0)
        
IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN
END	 
/*FIN Insert: CBTES_ITEMS*/

/*---------------------------------------------------------------------------------*/

/*Si el comprobante no es Remito, debe llevar Cta Cte y Cta Contable*/
IF (@Compromete_Remito = 0) 
BEGIN
	PRINT 'NO es Remito, Genero CtaCte y CtaContable'
	
	/*Insert: Clientes_CtaCte*/	
	IF @Id_Cond_Pago <> 1
	BEGIN
	
		SET @Descrip_Cbte_CtaCte = (
									ISNULL((SELECT Descrip_Corta FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte), '   ')+
									'  ' +
									ISNULL((SELECT Letra FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte),'A') +
									' ' +
									RIGHT('0000' + LTRIM(RTRIM(@Suc)),4) +
									'-' +
									RIGHT('00000000' + LTRIM(RTRIM(@Nro_Cbte)),8)
									)
		PRINT 'Inserto en Clientes_CtaCte Comprobante: ' + @Descrip_Cbte_CtaCte
								
		INSERT INTO Clientes_CtaCte		(Id_Trans,			Nro_Cuota,				Id_Empresa,
										Id_Cliente,			Fecha,					Fecha_Vence,
										Descripcion,		Importe,				Id_Estado_Cbte,
										Observacion,		Id_Trans_Origen,		Nro_Cuota_Origen,
										Id_Moneda,			Saldo,					Nro_FacCre)
		VALUES							(@trans_nueva,		1,						NULL,
										@id_cliente,		@Fecha,					@Fecha,
										@Descrip_Cbte_CtaCte,((@Importe * @Cant)*@Signo),	@Id_Estado_Cbte,
										@Observacion,		0,						0,
										'PES',				((@Importe * @Cant)*@Signo),	0)

		IF (@@ERROR <> 0)
		BEGIN
			ROLLBACK
			RETURN
		END	 
	END
	/*FIN Insert: Clientes_CtaCte*/
	
	/*---------------------------------------------------------------------------------*/
	DECLARE @generarcta INT
	SET @generarcta = ISNULL((SELECT Compromete_Asientos FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte),0)
	
	IF @generarcta <> 0
	BEGIN
		/*Insert: Cuenta Contable: DEBE*/
		DECLARE @Alias	INT
		DECLARE @Cta	INT
		DECLARE @CC		CHAR(10)

		SET @Alias		= 359	/*CAMBIAR!!!*/
		SET @Cta		= 6411	/*CAMBIAR!!!*/
		SET @CC			= ''	/*CAMBIAR!!!*/
	
		PRINT 'Inserto en Cuenta Cobtable DEBE en Alias: '+CONVERT(VARCHAR(6), @Alias)
			
		INSERT INTO Cbtes_Ctas_Contables	(Id_Trans,		Id_Cta_Contable,	Fecha,
											Debe,			Haber,				Observacion,
											Alias,			Id_Asiento,			Id_Centro_Costo,
											Item)
		VALUES								(@Trans_Nueva,	@Cta,				@Fecha,
											(@Importe * @Cant),0,				@Observacion,
											@Alias,			0,					@CC
											,1)
									
		IF (@@ERROR <> 0)
		BEGIN
			ROLLBACK
			RETURN
		END	 
		/*FIN Insert: Cuenta Contable: DEBE*/
	
		/*---------------------------------------------------------------------------------*/
	
		/*Insert: Cuenta Contable: HABER*/
		SET @Alias	= 28	/*CAMBIAR!!!*/
		SET @Cta	= 6064	/*CAMBIAR!!!*/
		SET @CC		= ''	/*CAMBIAR!!!*/

		PRINT 'Inserto en Cuenta Cobtable HABER en Alias: '+CONVERT(VARCHAR(6), @Alias)
	
		INSERT INTO Cbtes_Ctas_Contables	(Id_Trans,		Id_Cta_Contable,	Fecha,
											Debe,			Haber,				Observacion,
											Alias,			Id_Asiento,			Id_Centro_Costo,
											Item) 
		VALUES								(@Trans_Nueva,	@Cta,				@Fecha,
											0,				(@Importe * @Cant),	@Observacion,
											@Alias,			0,					@CC,
											2)
    END

	IF (@@ERROR <> 0)
	BEGIN
		ROLLBACK
		RETURN
	END
	/*FIN Insert: Cuenta Contable: HABER*/
END
/*FIN Si el comprobante no es Remito, debe llevar Cta Cte y Cta Contable*/

/*Actualizo el Proximo Numero de Comprobante*/
PRINT 'Actualizo el Proximo Nro de Comprobante Tipo: '+@Id_Tipo_Cbte+' a: ' + CONVERT(VARCHAR(20), (@Nro_Cbte + 1))

UPDATE Cbtes_Tipos SET Prox_Nro = (@Nro_Cbte + 1) WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte
 
IF (@@ERROR = 0)
	COMMIT TRAN
ELSE
	ROLLBACK
/*FIN Actualizo el Proximo Numero de Comprobante*/
GO

