		SET @Descrip_Cbte_CtaCte = (
									ISNULL((SELECT Descrip_Corta FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte), '   ')+
									'  ' +
									ISNULL((SELECT Letra FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte),'A') +
									' ' +
									RIGHT('0000' + LTRIM(RTRIM(@Suc)),4) +
									'-' +
									RIGHT('00000000' + LTRIM(RTRIM(@Nro_Cbte)),8)
									)
		PRINT 'Inserto en Clientes_CtaCte Comprobante: ' + @Descrip_Cbte_CtaCte
								
		INSERT INTO Clientes_CtaCte		(Id_Trans,			Nro_Cuota,				Id_Empresa,
										Id_Cliente,			Fecha,					Fecha_Vence,
										Descripcion,		Importe,				Id_Estado_Cbte,
										Observacion,		Id_Trans_Origen,		Nro_Cuota_Origen,
										Id_Moneda,			Saldo,					Nro_FacCre)
		VALUES							(@trans_nueva,		1,						NULL,
										@id_cliente,		@Fecha,					@Fecha,
										@Descrip_Cbte_CtaCte,((@Importe * @Cant)*@Signo),	@Id_Estado_Cbte,
										@Observacion,		0,						0,
										'PES',				((@Importe * @Cant)*@Signo),	0)

		IF (@@ERROR <> 0)
		BEGIN
			ROLLBACK
			RETURN
		END	 
	END

	--genero cuentas contables
	IF @CORTE = 1
	   BEGIN 
	  	select k.* into #cuentas
		from cbtes c, Cbtes_Ctas_Contables k, CLIENTES A 
		where c.id_trans = K.ID_TRANS AND C.ID_CLIENTE = A.ID_CLIENTE 
		      AND (A.ID_CLIENTE = @Id_Cliente OR A.Id_Cliente_Ref = @Id_Cliente) and c.saldo <> 0 AND C.ID_TIPO_CBTE <> 'AR21' AND C.FECHA < @Fecha_CORTE

		alter table #cuentas add importe decimal(12,2)
		alter table #cuentas add renglon int identity(1,1)

		update #cuentas set  observacion = id_trans, item = renglon
		update #cuentas set  id_trans = @trans_nueva, Fecha = @fecha
		update #cuentas set  importe = debe
		update #cuentas set  debe = haber 
		update #cuentas set  haber = importe
		update #cuentas set  Id_Cta_Contable = DBO.SF_Cta_Cont(Alias,@fecha) where debe = 0

		update #cuentas set alias = @ALIAS_CS, Id_Cta_Contable = @ID_CTA_CS where alias in (182,183,184,185,186,187,188,189,190) and haber = 0
		update #cuentas set alias = @ALIAS_varios, Id_Cta_Contable = @ID_CTA_CS where alias not in (182,183,184,185,186,187,188,189,190) and haber = 0

		Alter table #cuentas drop column importe, renglon

		Insert into Cbtes_Ctas_Contables
		       select * from #cuentas

		Drop table #cuentas
	   END

      ELSE

	   BEGIN 

	   	select k.* into #cuentas2
		from cbtes c, Cbtes_Ctas_Contables k, CLIENTES A 
		where c.id_trans = K.ID_TRANS AND C.ID_CLIENTE = A.ID_CLIENTE 
		      AND (A.ID_CLIENTE = @Id_Cliente OR A.Id_Cliente_Ref = @Id_Cliente) and c.saldo <> 0 AND C.ID_TIPO_CBTE <> 'AR21' AND C.FECHA >= @Fecha_CORTE
     

		alter table #cuentas2 add importe decimal(12,2)
		alter table #cuentas2 add renglon int identity(1,1)

		update #cuentas2 set  observacion = id_trans,  item = renglon
		update #cuentas2 set  id_trans = @trans_nueva, Fecha = @fecha
		update #cuentas2 set  importe = debe
		update #cuentas2 set  debe = haber 
		update #cuentas2 set  haber = importe
		update #cuentas2 set  Id_Cta_Contable = DBO.SF_Cta_Cont(Alias,@fecha) where debe = 0

		update #cuentas2 set alias = @ALIAS_CS, Id_Cta_Contable = @ID_CTA_CS where alias in (182,183,184,185,186,187,188,189,190) and haber = 0
		update #cuentas2 set alias = @ALIAS_varios, Id_Cta_Contable = @ID_CTA_CS where alias not in (182,183,184,185,186,187,188,189,190) and haber = 0

		Alter table #cuentas2 drop column importe, renglon

		Insert into Cbtes_Ctas_Contables
		       select * from #cuentas2

		Drop table #cuentas2
     END
---fin asientos

 IF (@@ERROR <> 0)
	BEGIN
		ROLLBACK
		RETURN
	END
	/*FIN Insert: Cuenta Contable: HABER*/
END
/*FIN Si el comprobante no es Remito, debe llevar Cta Cte y Cta Contable*/

/*Actualizo el Proximo Numero de Comprobante*/
PRINT 'Actualizo el Proximo Nro de Comprobante Tipo: '+@Id_Tipo_Cbte+' a: ' + CONVERT(VARCHAR(20), (@Nro_Cbte + 1))

UPDATE Cbtes_Tipos SET Prox_Nro = (@Nro_Cbte + 1) WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte
 
IF (@@ERROR = 0)
	COMMIT TRAN
ELSE
	ROLLBACK
/*FIN Actualizo el Proximo Numero de Comprobante*/
GO

CREATE PROCEDURE [dbo].[sp_generar_cbte_compras] 
@Id_Proveedor	INT,
@Destinatario	VARCHAR(100), 
@Importe		DECIMAL(12,2), 
@Id_Sucursal	SMALLINT,
@Fecha			DATETIME, 
@Id_Tipo_Cbte	CHAR(4),
@Lote			CHAR(14),
@Id_Estado_Cbte INT,
@Id_Cond_Pago	SMALLINT,
@Comprobante_Nro INT

AS 
/*-----------------------------------------------------
 * OJO!: Buscar la palabra CAMBIAR en estedocumento y 
 *		 adaptar las variables al cliente.
 ------------------------------------------------------*/
SET NOCOUNT ON 
BEGIN TRAN

PRINT 'Genero Comprobante Tipo: '+@Id_Tipo_Cbte+' para el Proveedor: '+CONVERT(VARCHAR(20),@Id_Proveedor)
PRINT 'Fecha del Comprobante: '+CONVERT(VARCHAR(20), @Fecha, 101)+' Estado Comprobante: '+CONVERT(VARCHAR(3),@id_Estado_Cbte)

/*Declaracion Variables Locales*/
DECLARE @Trans_Nueva			INT
DECLARE @User					SMALLINT
DECLARE @Desc					VARCHAR(50)
DECLARE @Nombre					VARCHAR(100)
DECLARE @Descripcion_Producto	VARCHAR(100)
DECLARE @Cantidad				DECIMAL(12,2)
DECLARE @Fecha_Mov				DATETIME
DECLARE @Descrip_Cbte_CtaCte	VARCHAR(100)
DECLARE @Signo					INT
DECLARE @ImporteXCant			DECIMAL(12,2)
DECLARE	@Observacion			VARCHAR(30)
DECLARE @Compromete_Pagos		SMALLINT
DECLARE @Compromete_Compras		SMALLINT
DECLARE @Id_Iva					CHAR(3)
/*FIN Declaracion Variables Locales*/

/*Asignacion Variables*/
SET @Trans_Nueva			= ISNULL((SELECT (MAX(id_trans)+1)	FROM Transacciones),1)
SET @Desc					= @Lote
SET @Observacion			= 'Comprobante Generado desde B.D.'
SET @Compromete_Pagos		= ISNULL((SELECT Compromete_Pagos FROM Cbtes_Tipos WHERE Id_Tipo_Cbte=@Id_Tipo_Cbte), 0)
SET @Compromete_Compras		= ISNULL((SELECT Compromete_Compras FROM Cbtes_Tipos WHERE Id_Tipo_Cbte=@Id_Tipo_Cbte), 0)
SET	@Id_Iva					= ISNULL((SELECT Id_Iva FROM Proveedores WHERE Id_Proveedor = @Id_Proveedor), 'I')
/*FIN Asignacion Variables*/

SET @Signo = 1

IF((@Compromete_Pagos <> 0) OR (@Compromete_Compras = -1))
BEGIN
	SET @Signo = -1
END

/*---------------------------------------------------------------------------------*/

/*Insert: TRANSACCIONES*/
PRINT 'Inserto la Transaccion Nro: ' + CONVERT(VARCHAR(20), @Trans_Nueva)

INSERT INTO Transacciones	(Id_Trans,		Descripcion,	Fecha_Mov) 
VALUES						(@Trans_Nueva,	@Desc,			GETDATE())

IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN
END	 
/*FIN Insert: TRANSACCIONES*/

/*---------------------------------------------------------------------------------*/

/*Insert: CBTES*/
SET @ImporteXCant = (@Importe)

PRINT 'Inserto en Cbtes'
INSERT INTO Cbtes			(Id_Trans,			Id_Sucursal,		Id_Tipo_Cbte,
							Cbte_Grupo,			Comprobante_Nro,	Id_Cliente,
							Id_Proveedor,		Signo,				Id_Estado_Cbte,
							Fecha,				Porc_DescEspecial,	Imp_Bonificacion,
							Imp_Gravado,		Imp_Exento,			Imp_IVA,
							Imp_IVA2,			Imp_Percepcion_IB,	Imp_Percepcion_Iva,
							Imp_Total,			Id_Usuario,			Porc_Iva3,
							Imp_Gravado2,		Imp_Gravado3,		Imp_NoGravado,
							Imp_IVA3,			Imp_Percep,			Saldo,
							Periodo_Iva,		Periodo,			Fecha_Venc,
							Observacion,		Id_Cond_Pago,		Cant_Cuotas,
							Cantidad,			Id_Lista,			Id_Moneda,
							Cotizacion,			Destinatario,		Id_Iva,
							Saldo_Iva_Recup,	Lote,				Id_Asiento,
							Id_Valor,			Cai,				Cantidad_Saldo,
							Saldo_Anterior,		Porc_DescFin,		Porc_Bonificacion,
							Porc_Iva,			Porc_Iva2,			Imp_Neto,
							Imp_DescEspecial,	Imp_DescFin)
VALUES						(@Trans_Nueva,		@Id_Sucursal,		@Id_Tipo_cbte,
							0/*Cbte_Grupo*/,	@Comprobante_Nro,	0/*Id_Cliente*/,
							@Id_Proveedor/*Id_Proveedor*/,	0/*Signo*/,	@Id_Estado_Cbte,
							@Fecha,				0/*Porc_DescEspec*/,0/*Imp_Bonificacion*/,
							0/*Imp_Gravado*/,	@ImporteXCant,		0/*Imp_Iva*/,
							0/*Imp_Iva2*/,		0/*Imp_Percepcion_*/,0/*Imp_Percepcion_Iva*/,
							@ImporteXCant,		0/*Id_Usuario*/,	27/*Porc_Iva3*/,
							0/*Imp_Gravado2*/,	0/*Imp_Gravado3*/,	0/*Imp_NoGravado*/,
							0/*Imp_IVA3*/,		0/*Imp_Percep*/,	@ImporteXCant,
							@Fecha,				@Fecha,				@Fecha,
							@Observacion,		@Id_Cond_Pago,		1/*Cant_Cuotas*/,
							0/*Cantidad*/,		0/*Id_Lista*/,		'PES'/*Id_Moneda*/,
							1/*Cotizacion*/,	@Destinatario,		@Id_Iva/*Id_Iva*/,
							0/*Saldo_Iva_Recu*/,@Lote,				0/*Id_Asiento*/,
							0/*Id_Valor*/,		0/*Cai*/,			0/*Cantidad_Saldo*/,
							0/*Saldo_Anterior*/,0/*Porc_DescFin*/,	0/*Porc_Bonificacion*/,
							21/*Porc_Iva*/,		'10.5'/*Porc_Iva2*/,@ImporteXCant,
							0/*Imp_DescEspecial*/,0/*Imp_DescFin*/)
							
IF (@@ERROR <> 0)
BEGIN
	ROLLBACK
	RETURN
END	 
/*FIN Insert: CBTES*/

/*---------------------------------------------------------------------------------*/
	
	/*Insert: Clientes_CtaCte*/	
	IF @Id_Cond_Pago <> 1
	BEGIN	
		SET @Descrip_Cbte_CtaCte = (
									ISNULL((SELECT Descrip_Corta FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte), '   ')+
									'  ' +
									ISNULL((SELECT Letra FROM Cbtes_Tipos WHERE Id_Tipo_Cbte = @Id_Tipo_Cbte),'A') +
									' ' +
									RIGHT('0000' + LTRIM(RTRIM(@Id_Sucursal)),4) +
									'-' +
									RIGHT('00000000' + LTRIM(RTRIM(@Comprobante_Nro)),8)
									)
		PRINT 'Inserto en Proveedores_CtaCte Comprobante: ' + @Descrip_Cbte_CtaCte
								
		INSERT INTO Proveedores_CtaCte	(Id_Trans,			Nro_Cuota,				Id_Empresa,
										Id_Proveedor,		Fecha,				Fecha_Vence,
										Descripcion,		Importe,				Id_Estado_Cbte,
										Observacion,		Id_Trans_Origen,		Nro_Cuota_Origen,
										Id_Moneda,			Saldo)
		VALUES							(@trans_nueva,		1,						NULL,
										@Id_Proveedor,		@Fecha,					@Fecha,
										@Descrip_Cbte_CtaCte,((@Importe)*@Signo),	@Id_Estado_Cbte,
										@Observacion,		0,						0,
										'PES',				((@Importe)*@Signo))

		IF (@@ERROR <> 0)
		BEGIN
			ROLLBACK
			RETURN
		END	 
	END
	/*FIN Insert: Clientes_CtaCte*/
	
	/*---------------------------------------------------------------------------------*/
 
IF (@@ERROR = 0)
	COMMIT TRAN
ELSE
	ROLLBACK
/*FIN Actualizo el Proximo Numero de Comprobante*/
GO


	CREATE PROCEDURE dbo.sp_helpdiagramdefinition
	(
		@diagramname 	sysname,
		@owner_id	int	= null 		
	)
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		set nocount on

		declare @theId 		int
		declare @IsDbo 		int
		declare @DiagId		int
		declare @UIDFound	int
	
		if(@diagramname is null)
		begin
			RAISERROR (N'E_INVALIDARG', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner');
		if(@owner_id is null)
			select @owner_id = @theId;
		revert; 
	
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname;
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId ))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end

		select version, definition FROM dbo.sysdiagrams where diagram_id = @DiagId ; 
		return 0
	END
GO


	CREATE PROCEDURE dbo.sp_helpdiagrams
	(
		@diagramname sysname = NULL,
		@owner_id int = NULL
	)
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		DECLARE @user sysname
		DECLARE @dboLogin bit
		EXECUTE AS CALLER;
			SET @user = USER_NAME();
			SET @dboLogin = CONVERT(bit,IS_MEMBER('db_owner'));
		REVERT;
		SELECT
			[Database] = DB_NAME(),
			[Name] = name,
			[ID] = diagram_id,
			[Owner] = USER_NAME(principal_id),
			[OwnerID] = principal_id
		FROM
			sysdiagrams
		WHERE
			(@dboLogin = 1 OR USER_NAME(principal_id) = @user) AND
			(@diagramname IS NULL OR name = @diagramname) AND
			(@owner_id IS NULL OR principal_id = @owner_id)
		ORDER BY
			4, 5, 1
	END
GO

