		update #CBTES_aux_sp set id_trans = @trans_nueva , id_tipo_cbte = 'HPIC'
                       where id_trans = @ID_TRANS
		update #CBTES_ITEMS_aux_sp set id_trans = @trans_nueva where id_trans = @ID_TRANS

                 -----------------------------agrego -----------------------------------------------

               INSERT INTO CBTES
