CREATE TRIGGER [dbo].[tri_clientes] ON [dbo].[Clientes]
WITH EXECUTE AS CALLER
AFTER INSERT,UPDATE

AS
SET NOCOUNT ON

DECLARE @Cli INT
DECLARE @Alias int
DECLARE @Cli_ref int
DECLARE @Id_Tipo_Cli INT
DECLARE @UNID_NEGOCIO	VARCHAR(14) 
DECLARE @Id_Cliente_Externo VARCHAR(14) -- Ticket #002080

DECLARE clicur 
CURSOR FOR
SELECT I.id_Cliente, I.id_cliente_ref,I.id_tipo_cli,RTRIM(LTRIM(ISNULL(i.Id_Cliente_Externo, ''))) FROM Inserted I left join Deleted D on I.ID_CLIENTE = isnull(D.ID_CLIENTE,0)
WHERE  I.Id_Cliente NOT IN (1113 /*VISITA*/, 1134 /*BICICLETA*/)
       AND (I.ID_TIPO_CLI <> isnull(D.ID_TIPO_CLI,0)
       OR I.ID_CLIENTE_REF <> isnull(D.ID_CLIENTE_REF,0)
       OR I.Activo <> isnull(D.Activo,0)
       OR I.Id_Cli_Relac <> isnull(D.Id_Cli_Relac,0)
       OR I.Fecha_Nac <> isnull(D.Fecha_Nac,'19000101')
       OR I.ID_Unid_Negocio <> ISNULL(D.ID_Unid_Negocio,'')
       OR I.Doc_Nro <> ISNULL(D.Doc_Nro,0)) -- Ticket #002080
       --OR I.Id_Cliente_Externo <> ISNULL(D.Id_Cliente_Externo,''))

OPEN clicur
FETCH NEXT FROM clicur INTO @cli,@Cli_ref,@Id_Tipo_Cli,@Id_Cliente_Externo
WHILE @@FETCH_STATUS = 0
BEGIN
    IF @Id_Tipo_Cli NOT IN (1134/*BICICLETA*/)
    BEGIN
    /*Ejecuta el Stored que verifica las validaciones del Cliente*/

		EXEC SP_Clientes_Validar @cli

		IF @Id_Tipo_Cli NOT IN (1018/*Invitado*/,10/*Acceso Master*/, 1105 /*Referente*/,1127 /*Alumno IGSM*/,1128 /*TESORERIA*/,1134/*BICICLETA*/,1135 /*DOCENTE IGSM*/)
		begin    
			EXEC SP_Contrato_Cli @Cli        --actualizo
			EXEC SP_Contrato_Cli_REF @Cli  
			EXEC SP_Contrato_Cli_Vitalicio @Cli /* Agrego para Cuota Vitalicio + 71 Voluntaria 20200616, Usuarion RCA Voluntaria , Usuario +75 Voluntaria */
   		END
		
		-- Ticket #002080 Numerar socios dentro del tri_clientes (logia del trigger [tri_nro_soc]
		-- Ticket #002080 Se agrega la validacion del Id_Tipo_Cli, para que se renumere el INVITADO cada vez que haya alguna modificacion de DNI.
		IF (@Id_Cliente_Externo = '' OR @Id_Cliente_Externo = 0 OR @Id_Tipo_Cli = 1018)
		BEGIN
			IF(@Id_Tipo_Cli NOT IN (1134/*BICICLETA*/))
			BEGIN
				SET @Id_Cliente_Externo = (dbo.SF_Nro_socio(@cli))
			
				UPDATE Clientes SET Id_Cliente_Externo = @Id_Cliente_Externo WHERE Id_Cliente = @cli
			END
		END		           		
	
	--EXEC SP_Cta_Cont_Cli @Cli,@Id_Tipo_Cli
	 
	 
	/*         SE AGREGA DENTRO DEL [SP_Cta_Cont_Cli]
	    
		 Actualizo el alias de la cuenta contable y unidad de negocios
		
		IF (@Id_Tipo_Cli NOT IN (1015,1006))
		BEGIN
			SET @UNID_NEGOCIO = 'CLUB'
		END
		
		IF @Id_Tipo_Cli = 1015
		BEGIN
		   SET @UNID_NEGOCIO = 'CLI'
		END
	    
		IF @Id_Tipo_Cli = 1006
		BEGIN
		   SET @UNID_NEGOCIO = 'EMPL'
		END
	    
	    
		update Clientes set Id_Alias_Cta_Cont_Venta = dbo.SF_Cli_CtaCont(@Cli,GETDATE()), ID_Unid_Negocio = @UNID_NEGOCIO
		where Id_Cliente = @Cli   
	*/     
	END                    
	FETCH NEXT FROM clicur INTO @cli,@Cli_ref,@Id_Tipo_Cli,@Id_Cliente_Externo
	
END
CLOSE clicur
DEALLOCATE clicur



