CREATE TRIGGER [dbo].[tri_crm_contacto] 
ON [dbo].[CRM_Contactos]
AFTER INSERT
AS 

SET NOCOUNT ON
DECLARE @Id_cliente int
declare @id_contacto int
declare @id_tipo_contacto int
declare @id_motivo_contacto int
declare @id_submotivo_contacto int
declare @id_objeto_contacto int
declare @fecha_aviso datetime

DECLARE [cur_crm] cursor for 
SELECT id_cliente,id_contacto,Id_Motivo_Contacto,Id_SubMotivo_Contacto,Id_Objeto_Contacto FROM Inserted
where Id_Motivo_Contacto = 5 and Id_SubMotivo_Contacto = 4 and Id_Objeto_Contacto = 4


OPEN [cur_crm]
FETCH NEXT FROM [cur_crm] INTO @id_cliente,@id_contacto,@Id_Motivo_Contacto,@Id_SubMotivo_Contacto,@Id_Objeto_Contacto
WHILE @@FETCH_STATUS = 0
BEGIN

    EXEC SP_CRM_ResolverContacto @Id_cliente,@id_contacto
    FETCH NEXT FROM [cur_crm] INTO @id_cliente,@id_contacto,@Id_Motivo_Contacto,@Id_SubMotivo_Contacto,@Id_Objeto_Contacto
END
CLOSE [cur_crm]
DEALLOCATE [cur_crm]
GO

