CREATE FUNCTION [dbo].[zCFU_Clientes_Tipos_Prod_Validar] (@pId_Tipo_Cli INT, @pId_Producto VARCHAR(50))
RETURNS SMALLINT
AS
BEGIN
	DECLARE @Existe_Categoria		SMALLINT
	DECLARE @Permisos_Venta			SMALLINT
	DECLARE @Cantidad				INT
	DECLARE @Flag_Categoria_Product	SMALLINT


	SET @Existe_Categoria = ISNULL((SELECT COUNT(1) FROM Clientes_Tipos WHERE Id_Tipo_Cli = @pId_Tipo_Cli),0)
	IF (@Existe_Categoria = 0) RETURN 0

	-- Si no habilitó para la venta no tiene permisos
	SELECT @Permisos_Venta = ISNULL(Flag_Permitir_Prod, 0) FROM Clientes_Tipos WHERE Id_Tipo_Cli = @pId_Tipo_Cli

	SET @Cantidad = ISNULL((SELECT COUNT(1) FROM Clientes_Tipos_Prod WHERE Id_Tipo_Cli = @pId_Tipo_Cli),0)

	IF(@Cantidad = 0)
	BEGIN	
		SET @Flag_Categoria_Product = 1  
		RETURN @Flag_Categoria_Product 
	END


	SET @Flag_Categoria_Product = ISNULL((SELECT MAX(1) FROM Clientes_Tipos_Prod WHERE Id_Tipo_Cli = @pId_Tipo_Cli AND Id_Producto= @pId_Producto),0) 
	SET @Flag_Categoria_Product = ISNULL(@Flag_Categoria_Product, 0) 

	IF @Permisos_Venta = 1 
		RETURN @Flag_Categoria_Product
		

	IF @Flag_Categoria_Product = 0 
		RETURN 1
	
	RETURN 0

	 END
GO


CREATE FUNCTION [dbo].[zCFU_Prod_Lista_Precio_20251028](@pId_Lista_Precio SMALLINT, @pId_Producto VARCHAR(14), @pId_Cliente INT, @Fecha DATETIME)
RETURNS DECIMAL(12,2)
AS
BEGIN
DECLARE @Precio									DECIMAL(12,2)
DECLARE @Flag_Existe_Lista_Precio				TINYINT
DECLARE @Flag_Existe_Producto					TINYINT
DECLARE @Flag_Existe_Cliente					TINYINT
DECLARE @Flag_Existe_Producto_En_Lista_Precios	TINYINT

DECLARE @Id_Lista_Precio_Nuevo_Socio			SMALLINT

DECLARE @Id_Tipo_Cli							INT
DECLARE @Id_Familia								INT
DECLARE @Fecha_Nac								VARCHAR(4)
DECLARE @Sexo									CHAR(1)
/*=================================================================================*/

SET @Flag_Existe_Lista_Precio = ISNULL((SELECT 1 FROM Prod_Listas_Precios WHERE Id_Lista_Precio = @pId_Lista_Precio), 0)
IF(@pId_Lista_Precio = 0 OR @Flag_Existe_Lista_Precio = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

SET @Flag_Existe_Producto = ISNULL((SELECT 1 FROM Productos WHERE Id_Producto = @pId_Producto), 0)
IF(@pId_Producto = '' OR @Flag_Existe_Producto = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

SET @Flag_Existe_Cliente = ISNULL((SELECT 1 FROM Clientes WHERE Id_Cliente = @pId_Cliente), 0)
IF(@pId_Cliente = 0 OR @Flag_Existe_Cliente = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

SET @Flag_Existe_Producto_En_Lista_Precios = ISNULL((SELECT 1 FROM Prod_Listas_Precios_Items WHERE Id_Lista_Precio = @pId_Lista_Precio AND Id_Producto = @pId_Producto), 0)
IF(@Flag_Existe_Producto_En_Lista_Precios = 0)
BEGIN
	SET @Precio = 0
	RETURN @Precio
END

/*=================================================================================*/
SET @Id_Lista_Precio_Nuevo_Socio = ISNULL((SELECT ID_LISTA_PRECIO FROM CLIENTES WHERE ID_CLIENTE=@pId_Cliente),0)

IF (@Id_Lista_Precio_Nuevo_Socio=222 and @pId_Lista_Precio not in (224,230)) --222 Lista Nuevos socios / 224 Lista para inscripciones
BEGIN
	SELECT
	@Precio = Precio
	FROM Prod_Listas_Precios_Items 
	WHERE 
	Id_Lista_Precio = 223 
	AND Id_Producto = @pId_Producto
	RETURN @Precio
END 

SELECT
@Precio = Precio
FROM Prod_Listas_Precios_Items 
WHERE 
Id_Lista_Precio = @pId_Lista_Precio 
AND Id_Producto = @pId_Producto

/*=================================================================================*/

/*PARA CUALQUIER OTRA PARTICULARIDAD IMPLEMENTAR A PARTIR DE AQUI LA MODIFICACION DE LA VARIABLE @Precio*/

/*=================================================================================*/

-- 20240222 Ticket #7946
IF (@pId_Lista_Precio = 224 /*INSCRIPCIONES WEB*/)
BEGIN
	
	SET @Id_Familia		= ISNULL((SELECT Id_Familia FROM Productos WHERE Id_Producto = @pId_Producto),0)
	
	IF (@Id_Familia = 23 /*FUTBOL*/)
	BEGIN
	
		SELECT	@Id_Tipo_Cli	= Id_Tipo_Cli,
				@Fecha_Nac		= YEAR(Fecha_Nac),
				@Sexo			= Sexo
		FROM Clientes 
		WHERE Id_Cliente = @pId_Cliente 
		AND Activo = 1
		
/*
		1.  Las mujeres pagan el 50% del valor del producto que le corresponde por su categoría de socia
			Si Es mujer y corresponde categoría infantil (6ta y 5ta) el porcentaje de descuento es el que 
			le corresponde por la categoría (30% y 70%).
			A partir de la categoría Cadete si es Mujer le corresponde el 50%
			
		2.  Los infantiles hay categorías 5° y 6° que abonan el 70% y el 30% respectivamente del valor del 
			producto futbol - infantil, las edades para las categoría 5° son nacidos en el 2015 y 2016
			y la categoria 6° nacidos en 2017 y 2018.
			(Validar por categoría de socio da infantil y por fecha de nacimiento el año para encuadrarlo 
			dentro de la 5° o 6° categoría)
*/
		
		IF (@Id_Tipo_Cli = 1000 /*INFANTIL*/) /*sexo indefinido*/
		BEGIN
			/*IF(@Fecha_Nac >= '2015' AND @Fecha_Nac <= '2016') -- 5°
			BEGIN
				SET @Precio = (@Precio-(@Precio * 0.30))
				RETURN ISNULL(@Precio, 0)
			END
			IF(@Fecha_Nac >= '2017' AND @Fecha_Nac <= '2018') -- 6°
			BEGIN
				SET @Precio = (@Precio-(@Precio * 0.70))
				RETURN ISNULL(@Precio, 0)
			END*/
			
			IF(@Fecha_Nac >= '2016' AND @Fecha_Nac <= '2017') -- 5°  //Ticket #011107
			BEGIN
				SET @Precio = (@Precio-(@Precio * 0.30))
				RETURN ISNULL(@Precio, 0)
			END
			IF(@Fecha_Nac >= '2018' AND @Fecha_Nac <= '2019') -- 6°
			BEGIN
				SET @Precio = (@Precio-(@Precio * 0.70))
				RETURN ISNULL(@Precio, 0)
			END
		END

		IF(@Sexo = 'F')
		BEGIN
			SET @Precio = (@Precio-(@Precio * 0.50))
			RETURN ISNULL(@Precio, 0) 
		END

	END
	
END

/*=================================================================================*/

RETURN ISNULL(@Precio, 0)
END
GO

CREATE FUNCTION [dbo].[zCF_SCA_IdentifIdCliente_20220808](@pDato VARCHAR(100))
RETURNS INT
AS
BEGIN
DECLARE @Id_Cliente					INT

IF(ISNULL(@pDato, '') = '')
BEGIN
	SET @Id_Cliente = 0
	RETURN @Id_Cliente
END

IF(LEN(@pDato) > 80)
BEGIN
	/*QR*/
	SET @Id_Cliente = ISNULL((SELECT ISNULL(Id_Cliente, 0) FROM Clientes_Links WHERE LOWER(LTRIM(RTRIM(URL)))= LOWER(LTRIM(RTRIM(@pDato)))), 0)
	RETURN @Id_Cliente
END

IF(dbo.CF_IsNumeric(@pDato) = 0)
BEGIN
	/*Credencial MiFare*/
	SET @Id_Cliente = ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE UPPER(LTRIM(RTRIM(Credencial_Nro))) = UPPER(LTRIM(RTRIM(@pDato)))), 0)
	RETURN @Id_Cliente
END

IF(dbo.CF_IsNumeric(@pDato) = 1)
BEGIN
	/*DNI*/
	IF(CONVERT(BIGINT, @pDato) < 3000000000)
	BEGIN
		SET @Id_Cliente = ISNULL((SELECT TOP 1 Id_Cliente FROM Clientes WHERE Doc_Nro = @pDato ORDER BY Activo DESC, Id_Cliente DESC), 0)	
		RETURN @Id_Cliente
	END
	ELSE
	BEGIN
		/*QR Intelektron Numerico de 10 caracteres que empieza con 9*/
		SET @Id_Cliente = ISNULL((SELECT ISNULL(Id_Cliente, 0) FROM Clientes_Links WHERE LOWER(LTRIM(RTRIM(URL)))= LOWER(LTRIM(RTRIM(@pDato)))), 0)
		RETURN @Id_Cliente
	END
END

RETURN ISNULL(@Id_Cliente, 0)
END

