create FUNCTION [dbo].[zCF_SCA_ValidarUltCuotaPaga_20251009](@pId_Cliente INT, @pId_Acceso SMALLINT, @pFecha DATETIME)
RETURNS TINYINT
AS
BEGIN
DECLARE @Flag_UCP				TINYINT
DECLARE @Ult_Cuota_Paga			DATETIME
DECLARE @Flag_Ult_Cuota_Paga	TINYINT
DECLARE @Dias_Gracia			INT

SET @Flag_UCP				= 0
SET @Flag_Ult_Cuota_Paga	= (SELECT ISNULL(Flag_Ult_Cuota_Paga, 0) FROM CD_Accesos WHERE Id_Acceso = @pId_Acceso)
SET @Dias_Gracia			= (SELECT ISNULL(Dias_Gracia, 0) FROM CD_Accesos WHERE Id_Acceso = @pId_Acceso)

IF(@Flag_Ult_Cuota_Paga <> 0)
BEGIN
	SET @Ult_Cuota_Paga = (SELECT ISNULL(Ult_Cuota_Paga, '19000101') FROM Clientes WHERE Id_Cliente = @pId_Cliente)
	
	IF(YEAR(CONVERT(DATE,(DATEADD(DAY,@Dias_Gracia,@Ult_Cuota_Paga)))) < YEAR(CONVERT(DATE,@pFecha)))
	BEGIN
		SET @Flag_UCP = 0
	END
	ELSE
	BEGIN
		IF(YEAR(CONVERT(DATE,(DATEADD(DAY,@Dias_Gracia,@Ult_Cuota_Paga)))) = YEAR(CONVERT(DATE,@pFecha)))
		BEGIN
			IF(MONTH(CONVERT(DATE,(@Ult_Cuota_Paga + @Dias_Gracia))) < MONTH(CONVERT(DATE,@pFecha)))
			BEGIN
				SET @Flag_UCP = 0
			END
			ELSE
			BEGIN
				SET @Flag_UCP = 1
			END
		END
		ELSE
		BEGIN
			SET @Flag_UCP = 1
		END
	END
	
	RETURN @Flag_UCP
END
ELSE
BEGIN
	SET @Flag_UCP = 0
	RETURN @Flag_UCP
END

RETURN ISNULL(@Flag_UCP, 0)

END
GO

CREATE PROCEDURE [dbo].[zCPJU_Lista_Blanca_Suprema_Socios_20250722] @pJson VARCHAR(8000)
AS 

/*
 * LOG VERSIONES:
 * 16/07/2025: Se crea el Stored
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Controlador		INT
DECLARE @pId_Cliente			INT

SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Controlador			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Controlador')), 0)
SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Id_Controlador_Suprema INT = 2 -- Cuota Social
DECLARE @Id_Cliente				INT
DECLARE @Credencial_Nro			VARCHAR(50)
DECLARE @Doc_Nro				VARCHAR(20)
DECLARE @Mensaje				VARCHAR(5000)
DECLARE @Respuesta				INT
DECLARE @Result_Tabla_Stored_Invocado TABLE (Flag_Habilitado	TINYINT,
						Mensaje				VARCHAR(5000),
						Info				VARCHAR(101),
						Foto				VARCHAR(256),
						Foto_Bin			IMAGE,
						Id_Cliente			INT,
						Id_Cliente_Ref		INT,
						Tiempo_Mensaje		SMALLINT)
--DECLARE @Fecha_Actual			VARCHAR = (SELECT CONVERT(varchar, GETDATE(), 126))
DECLARE @Fecha_Actual DATETIME = GETDATE()
/*FIN Variables Locales*/

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a Stored Procedure: CPJU_Lista_Blanca_Suprema_Socios'
	PRINT 'Parametros:' + @pJson
END

IF(@pId_Controlador = 0)
BEGIN
	SET @pId_Controlador = 65 -- Control de CS
END

SET @Id_Controlador_Suprema = (SELECT Suprema_Grupo_id FROM CD_Controladores WHERE Id_Controlador = @pId_Controlador)

CREATE TABLE #Lista_Blanca (
	Id_Cliente INT,
	Doc_Nro BIGINT, 
	Credencial_Nro VARCHAR(30),
	Mensaje VARCHAR(5000),
	Habilitado TINYINT
)

-- Creo indice para tabla temporal
CREATE INDEX IXXXX_Lista_Blanca ON #Lista_Blanca (Id_Cliente)

IF(@pId_Cliente <> 0)
BEGIN
	DELETE FROM CD_Lista_Blanca_Suprema WHERE Id_Cliente = @pId_Cliente

	INSERT INTO #Lista_Blanca
	SELECT C.Id_Cliente, C.Doc_Nro, C.Credencial_Nro, '' AS Mensaje, 1 AS Habilitado
	FROM Clientes C, Clientes_Fotos F
	WHERE C.Id_Cliente = F.Id_Cliente
	AND F.Foto IS NOT NULL
	AND F.Nro = 1
	AND C.Activo = 1
	AND C.Doc_Nro > 1000000
	AND C.Tipo_Persona = 'F'
	AND C.Id_Cliente = @pId_Cliente
END
ELSE
BEGIN
	DELETE FROM CD_Lista_Blanca_Suprema

	INSERT INTO #Lista_Blanca
	SELECT C.Id_Cliente, C.Doc_Nro, C.Credencial_Nro, '' AS Mensaje, 1 AS Habilitado
	FROM Clientes C, Clientes_Fotos F
	WHERE C.Id_Cliente = F.Id_Cliente
	AND F.Foto IS NOT NULL
	AND F.Nro = 1
	AND C.Activo = 1
	AND C.Doc_Nro > 1000000
	AND C.Tipo_Persona = 'F'
END

DECLARE CPJU_Lista_Blanca_Suprema_Socios CURSOR FOR
SELECT Id_Cliente, Doc_Nro, Credencial_Nro FROM #Lista_Blanca WHERE Habilitado = 1

OPEN CPJU_Lista_Blanca_Suprema_Socios
FETCH NEXT FROM CPJU_Lista_Blanca_Suprema_Socios INTO @Id_Cliente, @Doc_Nro, @Credencial_Nro
WHILE @@FETCH_STATUS = 0
BEGIN

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Id_Cliente AQUI: ' + CAST(@Id_Cliente AS VARCHAR)
	END

	DELETE @Result_Tabla_Stored_Invocado

	IF(ISNULL(@Credencial_Nro, '') = '')
	BEGIN
		SET @Credencial_Nro = CAST(@Doc_Nro AS varchar(30))
	END

	INSERT INTO @Result_Tabla_Stored_Invocado EXEC dbo.CP_SCA_RegistrarAcceso @pId_Controlador,
									'E',
									@Fecha_Actual,
									'19000101',
									@Credencial_Nro,
									0,
									'',
									'',
									'',
									0,
									0,
									0

	SELECT TOP 1 @Respuesta = Flag_Habilitado, @Mensaje = Mensaje 
	FROM @Result_Tabla_Stored_Invocado

	PRINT 'RESPUESTA: ' + CAST(@Respuesta AS VARCHAR)
	PRINT '@Id_Cliente: ' + CAST(@Id_Cliente AS VARCHAR)

	IF @Respuesta = 1
	BEGIN
		UPDATE #Lista_Blanca SET Mensaje = @Mensaje  WHERE Id_Cliente = @Id_Cliente
		PRINT 'INSERTO EN LISTA BLANCA 0'
		IF NOT EXISTS (
			SELECT 1 
			FROM CD_Lista_Blanca_Suprema 
			WHERE Id_Cliente = @Id_Cliente
		)
		BEGIN
			PRINT 'INSERTO EN LISTA BLANCA'
			INSERT INTO CD_Lista_Blanca_Suprema (Id_Grupo_Suprema, Fecha_Proceso, Id_Cliente, Mensaje)
			VALUES (@Id_Controlador_Suprema, GETDATE(), @Id_Cliente, @Mensaje)
		END
		ELSE
		BEGIN
			PRINT 'NO INSERTO EN LISTA BLANCA'
		END
	END
	ELSE
	BEGIN
		PRINT 'UPDATE EN LISTA BLANCA'
		UPDATE #Lista_Blanca SET Habilitado = 0, Mensaje = @Mensaje WHERE Id_Cliente = @Id_Cliente
	END

	FETCH NEXT FROM CPJU_Lista_Blanca_Suprema_Socios INTO @Id_Cliente, @Doc_Nro, @Credencial_Nro
END
CLOSE CPJU_Lista_Blanca_Suprema_Socios
DEALLOCATE CPJU_Lista_Blanca_Suprema_Socios

/*
INSERT INTO CD_Lista_Blanca_Suprema (Id_Grupo_Suprema, Fecha_Proceso, Id_Cliente, Mensaje)
SELECT @Id_Controlador_Suprema, GETDATE(),Id_Cliente, Doc_Nro, Mensaje
	FROM #Lista_Blanca WHERE Habilitado = 1
*/

DROP TABLE #Lista_Blanca

