							ELSE @pFecha_QA
						END as Ult_Fecha_Fact, P.Flag_Mes_Desglo, ISNULL(P.Id_Cond_Pago,@Cond_Pago_Lote)	
						FROM Contratos_Prod C
							JOIN #Total_Contratos Z ON C.Id_Contrato = Z.Id_Contrato
