							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Mes, 0) = 1) 

SET @Ult_Cuota_Paga_Periodo =(SELECT MAX(CI.Fecha_Venc)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
							AND CI.Id_Producto = PR.Id_Producto
							AND CT.Compromete_Factura IN (1)
							AND (CB.Id_Estado_Cbte IN (2/*Completo*/) OR (CB.Id_Estado_Cbte IN (1/*PENDIENTE*/) AND CI.Imp_Final = 0))
							AND PR.Id_Familia = (dbo.CF_xParam('Fam_CuotasSoc'))
							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Periodo, 0) = 1)
							
IF(@Ult_Cuota_Paga_Periodo IS NOT NULL)
BEGIN
	SET @Ult_Cuota_Paga_Periodo = dbo.CF_FOMONTH(@Ult_Cuota_Paga_Periodo)
	
	IF(@Ult_Cuota_Paga_Mes IS NULL)
	BEGIN
		SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Periodo
	END
	ELSE
	BEGIN
		IF(@Ult_Cuota_Paga_Periodo > @Ult_Cuota_Paga_Mes)
		BEGIN
			SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Periodo
		END
		ELSE
		BEGIN
			SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Mes
		END
	END
END
ELSE
BEGIN
	SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Mes
END

------------------------------------------------------------------------------------------------------------------------------------------------

--SET @Ult_Cuota_Impaga = (SELECT MIN(CI.Fecha_QA)
--						FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
--						WHERE 
--						CB.Id_Trans = CI.Id_Trans 						
--						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte
--						AND CI.Id_Producto = PR.Id_Producto
--						AND CT.Compromete_Factura IN (1)
--						AND CB.Id_Estado_Cbte IN (1/*Pendiente*/, 4/*Parcial*/)
--						AND PR.Id_Familia = @Fam_CuotaSoc
--						AND CI.Id_Cliente = @pId_Cliente)	


IF((@Ult_Cuota_Paga IS NOT NULL) AND (@Ult_Cuota_Impaga IS NOT NULL))
BEGIN
	IF (@Ult_Cuota_Impaga < @Ult_Cuota_Paga)
	BEGIN
		SET @Fecha_UCP = DATEADD(MM, -1, @Ult_Cuota_Impaga)
		RETURN @Fecha_UCP
	END
	ELSE
	BEGIN
		SET @Fecha_UCP = @Ult_Cuota_Paga
		RETURN @Fecha_UCP
	END
END


IF((@Ult_Cuota_Paga IS NULL) AND (@Ult_Cuota_Impaga IS NOT NULL))
BEGIN
	SET @Fecha_UCP = DATEADD(MM, -1, @Ult_Cuota_Impaga)
	RETURN @Fecha_UCP
END

IF((@Ult_Cuota_Paga IS NOT NULL) AND (@Ult_Cuota_Impaga IS NULL))
BEGIN
	SET @Fecha_UCP = @Ult_Cuota_Paga
	RETURN @Fecha_UCP
END

--si las 2 son nulas----
SET @Fecha_Alta = (SELECT ISNULL(Fecha_Alta, '19000101') FROM Clientes WHERE Id_Cliente = @pId_Cliente)
/*Se hace la siguiente linea porque tienen SQL 2008 o superior*/
SET @Fecha_Alta = CONVERT(DATE,@Fecha_Alta) 

RETURN ISNULL(@Fecha_UCP, DATEADD(MM, -1, @Fecha_Alta))
END
GO

CREATE PROCEDURE [dbo].[zSPJ_Comprobacion_Socios_BioStar_20250723] @pJson VARCHAR(8000)
AS 

/*
 * LOG VERSIONES:
 * 16/07/2025: Se crea el Stored
 * 17/07/2025: Se agrega la fecha de proceso de la lista blanca
*/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Controlador		INT
DECLARE @pGenerar_Novedad		TINYINT

SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Controlador			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Controlador')), 0)
SET @pGenerar_Novedad			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Generar_Novedad')), 0)
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Id_Controlador_Suprema INT = 2 -- Cuota Social
DECLARE @json					NVARCHAR(MAX)
DECLARE @Id_Cliente				INT
/*FIN Variables Locales*/

IF(@pModoDebug = 1)
BEGIN
	PRINT 'Ingreso a Stored Procedure: SPJ_Comprobacion_Socios_BioStar'
	PRINT 'Parametros:' + @pJson
END

IF(@pId_Controlador = 0)
BEGIN
	SET @pId_Controlador = 65 -- Control de CS
END

SET @Id_Controlador_Suprema = (SELECT Suprema_Grupo_id FROM CD_Controladores WHERE Id_Controlador = @pId_Controlador)

-- Creo la tabla temporal con los socios de ese nivel de acceso
SELECT U.USRID AS Id_Cliente
	INTO #Suprema
	FROM [10.0.0.27].[BIOSTAR_AC].dbo.T_USR U
		, [10.0.0.27].[BIOSTAR_AC].dbo.T_ACSGRUSS G
		WHERE U.USRUID NOT IN (0,1,2) 
		AND U.DEL <> 'Y' 
		AND U.USRUID = G.USRUID
		AND G.ACSGRUID = @Id_Controlador_Suprema
		
-- Creo indice para tabla temporal
CREATE INDEX IXXXX_Suprema ON #Suprema (Id_Cliente)

CREATE TABLE #Socios (
	Id_Cliente INT,
	Doc_Nro BIGINT,
	Id_Cliente_Externo VARCHAR(14),
	Razon_Social VARCHAR(100),
	Fecha_Alta DATETIME,
	Ult_Cuota_Paga DATETIME,
	Habilitado_En VARCHAR(10),
	Mensaje VARCHAR(5000),
	Fecha_Lista_Blanca DATETIME
)

CREATE TABLE #Socios2 (
	Id_Cliente INT,
	Doc_Nro BIGINT,
	Id_Cliente_Externo VARCHAR(14),
	Razon_Social VARCHAR(100),
	Fecha_Alta DATETIME,
	Ult_Cuota_Paga DATETIME,
	Habilitado_En VARCHAR(10),
	Mensaje VARCHAR(5000),
	Fecha_Lista_Blanca DATETIME
)

-- Clientes en lista_blanca y no en #Suprema
INSERT INTO #Socios
SELECT L.Id_Cliente, C.Doc_Nro, C.Id_Cliente_Externo, C.Razon_Social, C.Fecha_Alta, C.Ult_Cuota_Paga, 'GEBA' AS Habilitado_En, L.Mensaje AS Mensaje, L.Fecha_Proceso AS Fecha_Lista_Blanca
FROM CD_Lista_Blanca_Suprema L, Clientes C
WHERE L.Id_Cliente NOT IN (
    SELECT S.Id_Cliente FROM #Suprema S
) AND L.Id_Cliente = C.Id_Cliente

UNION ALL

-- Clientes en #Suprema y no en lista_blanca
SELECT S.Id_Cliente, C.Doc_Nro, C.Id_Cliente_Externo, C.Razon_Social, C.Fecha_Alta, C.Ult_Cuota_Paga, 'SUPREMA' AS Habilitado_En, '' AS Mensaje, '' AS Fecha_Lista_Blanca
FROM #Suprema S, Clientes C
WHERE S.Id_Cliente NOT IN (
    SELECT L.Id_Cliente FROM CD_Lista_Blanca_Suprema L
) AND S.Id_Cliente = C.Id_Cliente

DELETE S
FROM #Socios S
JOIN Clientes C ON S.Id_Cliente = C.Id_Cliente
WHERE C.doc_nro < 1000000
	OR NOT EXISTS (
		SELECT 1
		FROM Clientes_Fotos F
		WHERE F.Id_Cliente = C.Id_Cliente
		AND F.Nro = 1
	)

IF(@pGenerar_Novedad = 1)
BEGIN

	INSERT INTO CD_Clientes_Novedades (Id_Cliente, Fecha, Estado, Fecha_Simulacion)
	SELECT S.Id_Cliente, GETDATE(), 'P', NULL FROM #Socios S
	WHERE NOT EXISTS(
		SELECT 1 
		FROM CD_Clientes_Novedades N
		WHERE N.Id_Cliente = S.Id_Cliente
		AND N.Estado = 'P'
	)

	SELECT 1 AS Finalizado
END
ELSE
BEGIN

	-- Actualizo la lista blanca
	DECLARE cursor_socios CURSOR FOR
	SELECT Id_Cliente FROM #Socios

	OPEN cursor_socios
	FETCH NEXT FROM cursor_socios INTO @Id_Cliente
	WHILE @@FETCH_STATUS = 0
	BEGIN

		SET @json = '{"ModoDebug":1,"Id_Cliente":"' + CAST(@Id_Cliente AS NVARCHAR) + '"}'
		EXEC dbo.CPJU_Lista_Blanca_Suprema_Socios @json

		PRINT 'ENTRO'
		PRINT 'EXEC dbo.CPJU_Lista_Blanca_Suprema_Socios ''' + @json + ''''  

		FETCH NEXT FROM cursor_socios INTO @Id_Cliente
	END

	CLOSE cursor_socios
	DEALLOCATE cursor_socios

	INSERT INTO #Socios2
	SELECT L.Id_Cliente, C.Doc_Nro, C.Id_Cliente_Externo, C.Razon_Social, C.Fecha_Alta, C.Ult_Cuota_Paga, 'GEBA' AS Habilitado_En, L.Mensaje AS Mensaje, L.Fecha_Proceso AS Fecha_Lista_Blanca
	FROM CD_Lista_Blanca_Suprema L, Clientes C
	WHERE L.Id_Cliente NOT IN (
		SELECT S.Id_Cliente FROM #Suprema S
	) AND L.Id_Cliente = C.Id_Cliente

	UNION ALL

	-- Clientes en #Suprema y no en lista_blanca
	SELECT S.Id_Cliente, C.Doc_Nro, C.Id_Cliente_Externo, C.Razon_Social, C.Fecha_Alta, C.Ult_Cuota_Paga, 'SUPREMA' AS Habilitado_En, '' AS Mensaje, '' AS Fecha_Lista_Blanca
	FROM #Suprema S, Clientes C
	WHERE S.Id_Cliente NOT IN (
		SELECT L.Id_Cliente FROM CD_Lista_Blanca_Suprema L
	) AND S.Id_Cliente = C.Id_Cliente


	SELECT 
		S.*,
		CASE 
			WHEN N.id_cliente IS NOT NULL THEN 1 
			ELSE 0 
		END AS Pendiente
		FROM #Socios2 S
		LEFT JOIN CD_Clientes_Novedades N ON N.Id_Cliente = S.Id_Cliente AND N.Estado = 'P'
END


DROP TABLE #Suprema
DROP TABLE #Socios
DROP TABLE #Socios2

--EXEC dbo.SPJ_Comprobacion_Socios_BioStar '{"ModoDebug":"1"}'
--EXEC dbo.SPJ_Comprobacion_Socios_BioStar '{"ModoDebug":"1","Generar_Novedad":"1"}'
GO

CREATE PROCEDURE [dbo].[zSP_Cbtes_Items_Integrantes20251022] @trans INT, @Item SMALLINT, @Prod VARCHAR(14)
AS
DECLARE @Id_Familia INT
SET @Id_Familia = (SELECT Id_Familia FROM Productos where Id_Producto = @Prod)

PRINT '-----------------------------------------------------------------------------------'
PRINT 'Ingreso SP: SP_Cbtes_Items_Integrantes'

PRINT 'Id_Trans: ' + CONVERT(VARCHAR(10), @trans) + ' Item: ' + CONVERT(VARCHAR(10), @Item) + ' Producto: ' + @Prod

/*Verifica si el Tipo de Cbte Compromete Factura*/
PRINT 'Verifica si el Tipo de Cbte Compromete Factura'
IF NOT EXISTS(SELECT 1 FROM Cbtes_Tipos T, Cbtes C
              WHERE 
              C.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
              AND C.Id_Trans = @trans 
              AND T.Compromete_Factura in (1,-1))
BEGIN
	PRINT 'El Tipo de Cbte NO compromete Factura'
	PRINT 'SALE DEL SP'
    RETURN
END
PRINT 'El Tipo de Cbte compromete Factura'
/*FIN Verifica si el Tipo de Cbte Compromete Factura*/
   UPDATE Cbtes_Items SET Id_Producto_Orig = Id_Producto  WHERE Id_Trans = @Trans AND Item = @Item
/*Verifica si el Producto es C.S.*/
PRINT 'Verifica si el Producto es C.S.'
IF @Id_Familia not IN (1) 
   RETURN
   
IF @Prod <> 'CS'
   UPDATE Cbtes_Items SET Id_Producto = 'CS' WHERE Id_Trans = @Trans AND Item = @Item AND Id_Producto <> 'CS' 


--IF @Prod <> 'CS'
--BEGIN
--	PRINT 'El Producto NO es CS. Id_Producto: ' + @Prod
--	PRINT 'SALE DEL SP'
--    RETURN
--END
/*FIN Verifica si el Producto es C.S.*/

/*Verifico que el Comprobante sea un Titular*/
DECLARE @Id_Cliente INT
DECLARE @Id_Cliente_Ref INT, @item_nuevo SMALLINT

SET @Id_Cliente = ISNULL((SELECT Id_Cliente FROM Cbtes WHERE Id_Trans = @trans), 0)
PRINT 'Id_Cliente del Cbte: ' + CONVERT(VARCHAR(10), @Id_Cliente)

IF @Id_Cliente IN (0,1, 1105)
BEGIN
	PRINT 'El Id_Cliente es NO DEFINIDO o VARIOS o REFERENTE'
	PRINT 'SALE DEL SP'
    RETURN	
END

SET @Id_Cliente_Ref = ISNULL((SELECT Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @Id_Cliente),0)

IF @Id_Cliente_Ref <> 0
BEGIN
	PRINT 'El Id_Cliente es INTEGRANTE'
	PRINT 'SALE DEL SP'
    RETURN		
END
/*FIN Verifico que el Comprobante sea un Titular*/

DECLARE @Id_Cond_Vta CHAR(10)
SET @Id_Cond_Vta = (SELECT Id_Cond_Vta FROM Clientes WHERE Id_Cliente = @Id_Cliente)

IF (LTRIM(RTRIM(@Id_Cond_Vta)) = 'GFCP')
BEGIN
	PRINT 'La condicion de Venta es: ESPECIAL-G. Fam Cobro x Separado'
	PRINT 'SALE DEL SP'
    RETURN		
END

/*Cantidad de Integrantes*/
DECLARE @Cant_Integrantes SMALLINT
SET @Cant_Integrantes = ISNULL((SELECT COUNT(Id_Cliente) FROM Clientes WHERE Id_Cliente_Ref = @Id_Cliente AND Activo = 1 AND Tipo_Persona='F'), 0)
PRINT 'Cant. de Integrantes del Grupo Familiar: ' + CONVERT(VARCHAR(10), @Cant_Integrantes)

IF @Cant_Integrantes = 0
BEGIN
	PRINT 'No hay Integrantes en el G.F.'
	PRINT 'SALE DEL SP'
    RETURN	
END

DECLARE @Imp_Final DECIMAL(15,5)

SET @Imp_Final = ISNULL((SELECT Imp_Final FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),0)

PRINT 'Importe Final del Item $' + CONVERT(VARCHAR(30), @Imp_Final)

DECLARE @Id_Estado_Cbte SMALLINT
SET @Id_Estado_Cbte = ISNULL((SELECT Id_Estado_Cbte FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),1)
PRINT 'Estado del Item: ' + CONVERT(VARCHAR(10), @Id_Estado_Cbte)

DECLARE @Fecha_Venc DATETIME
SET @Fecha_Venc = ISNULL((SELECT Fecha_Venc FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),GETDATE())
PRINT 'Fecha Vencimiento del Item: ' + CONVERT(VARCHAR(20), @Fecha_Venc, 103)

DECLARE @Lote VARCHAR(20)
SET @Lote = ISNULL((SELECT Lote FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),'')
PRINT 'Lote del Item: ' + @Lote

DECLARE @Flag_QA CHAR(1)
SET @Flag_QA = ISNULL((SELECT Flag_QA FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),1)
PRINT 'Flag QA del Item: ' + @Flag_QA

DECLARE @Fecha_QA DATETIME
SET @Fecha_QA = ISNULL((SELECT Fecha_QA FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),GETDATE())
PRINT 'Fecha QA del Item: ' + CONVERT(VARCHAR(20), @Fecha_QA, 103)

DECLARE @Bonif DECIMAL(5,2)
SET @Bonif = ISNULL((SELECT Bonif FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),0)
PRINT 'Porc. Bonificacion del Item: ' + CONVERT(VARCHAR(30), @Bonif)

DECLARE @Descripcion_Producto VARCHAR(100)
SET @Descripcion_Producto = ISNULL((SELECT Descripcion_Resumida FROM Productos WHERE Id_Producto = @Prod),'Producto desconocido')
PRINT 'Descripcion del Producto del Item: ' + @Descripcion_Producto


/*Cursor recorriendo Todos los Integrantes del Grupo*/
PRINT 'Se recorren los Integrantes del Grupo'
DECLARE @id_cliente_Integrante	INT;
DECLARE @Precio_CS_Integrante	DECIMAL(15,5);
DECLARE @Nro_Integrante			SMALLINT;
DECLARE @Resto_Precio_Final		DECIMAL(15,5)
DECLARE @Cantidad_Saldo			DECIMAL(15,5)

SET @Nro_Integrante = 0
SET @Resto_Precio_Final = @Imp_Final

DECLARE curIntegItems CURSOR FOR 
		SELECT Id_Cliente FROM Clientes
		WHERE
		Id_Cliente_Ref = @Id_Cliente
		AND Activo = 1
		AND Tipo_Persona='F'
		AND Id_Tipo_Cli  not in (1105) /*Referente*/
		ORDER BY Id_Cli_Relac, Fecha_Nac

OPEN curIntegItems
FETCH NEXT FROM curIntegItems
INTO @id_cliente_Integrante
WHILE @@FETCH_STATUS = 0
BEGIN

	SET @Nro_Integrante = @Nro_Integrante + 1
	SET @Precio_CS_Integrante = dbo.SF_CS_Precio_Persona(@id_cliente_Integrante, @Fecha_QA)
	SET @item_nuevo = ISNULL((SELECT MAX(item) FROM Cbtes_Items WITH (NOLOCK) WHERE Id_Trans = @trans),0) +1
	IF @item_nuevo < 100
	   SET @item_nuevo = 100

	PRINT 'Integrante Nro: ' + CONVERT(VARCHAR(10), @Nro_Integrante) + ' Id_Cliente: ' + CONVERT(VARCHAR(10), @id_cliente_Integrante) + ' Precio CS: $' + CONVERT(VARCHAR(30), @Precio_CS_Integrante)

	
	IF @Id_Estado_Cbte IN (1,4)
	BEGIN
		SET @Cantidad_Saldo = @Precio_CS_Integrante
	END
	ELSE
	BEGIN
		SET @Cantidad_Saldo = 0
	END
	
	PRINT 'Se insertará en Cbtes_Items. Id_Trans: ' + CONVERT(VARCHAR(20), @trans) + ' Item: ' + CONVERT(VARCHAR(20), @item_nuevo)

    SELECT * INTO #ITEMSFAM FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item
    UPDATE #ITEMSFAM SET Item = @item_nuevo ,
						 Precio_Grav = @Precio_CS_Integrante,
						 Imp_Gravado = @Precio_CS_Integrante,
						 Imp_Final = @Precio_CS_Integrante,
						 Precio = @Precio_CS_Integrante,
						 Id_Cliente = @id_cliente_Integrante
							
    INSERT INTO Cbtes_Items SELECT * FROM #ITEMSFAM

	PRINT 'Precio Item Inicial: ' + CONVERT(VARCHAR(30), @Imp_Final) 
	SET @Resto_Precio_Final = @Resto_Precio_Final - @Precio_CS_Integrante
	PRINT 'Quedan $' + CONVERT(VARCHAR(30), @Resto_Precio_Final) + ' para dividir entre el resto de los integrantes'
	DROP TABLE #ITEMSFAM

FETCH NEXT FROM curIntegItems
INTO @id_cliente_Integrante
END 
CLOSE curIntegItems;
DEALLOCATE curIntegItems;
/*Cursor recorriendo Todos los Integrantes del Grupo*/

/*Actualizo el Precio del Titular según lo que restaba*/
PRINT 'El Resto de: $' + CONVERT(VARCHAR(30), @Resto_Precio_Final) + ' lo asignará al Titular'

UPDATE Cbtes_Items
SET
	Precio_Grav = @Resto_Precio_Final,
	Imp_Gravado = @Resto_Precio_Final,
	Imp_Final = @Resto_Precio_Final,
	Precio = @Resto_Precio_Final
WHERE
	Id_Trans = @trans
	AND Item = @Item
/*FIN Actualizo el Precio del Titular según lo que restaba*/

PRINT 'FIN SP: SP_Cbtes_Items_Integrantes'
PRINT '-----------------------------------------------------------------------------------'
GO

