DECLARE @Precio_CS_Integrante	DECIMAL(15,5);
DECLARE @Nro_Integrante			SMALLINT;
DECLARE @Resto_Precio_Final		DECIMAL(15,5)
DECLARE @Cantidad_Saldo			DECIMAL(15,5)

SET @Nro_Integrante = 0
SET @Resto_Precio_Final = @Imp_Final

DECLARE curIntegItems CURSOR FOR 
		SELECT Id_Cliente FROM Clientes
		WHERE
		Id_Cliente_Ref = @Id_Cliente
		AND Activo = 1
		AND Tipo_Persona='F'
		AND Id_Tipo_Cli  not in (1105) /*Referente*/
		ORDER BY Id_Cli_Relac, Fecha_Nac

OPEN curIntegItems
FETCH NEXT FROM curIntegItems
INTO @id_cliente_Integrante
WHILE @@FETCH_STATUS = 0
BEGIN

	SET @Nro_Integrante = @Nro_Integrante + 1
	SET @Precio_CS_Integrante = dbo.SF_CS_Precio_Persona(@id_cliente_Integrante, @Fecha_QA)
	SET @item_nuevo = ISNULL((SELECT MAX(item) FROM Cbtes_Items WITH (NOLOCK) WHERE Id_Trans = @trans),0) +1
	IF @item_nuevo < 100
	   SET @item_nuevo = 100

	PRINT 'Integrante Nro: ' + CONVERT(VARCHAR(10), @Nro_Integrante) + ' Id_Cliente: ' + CONVERT(VARCHAR(10), @id_cliente_Integrante) + ' Precio CS: $' + CONVERT(VARCHAR(30), @Precio_CS_Integrante)

	
	IF @Id_Estado_Cbte IN (1,4)
	BEGIN
		SET @Cantidad_Saldo = @Precio_CS_Integrante
	END
	ELSE
	BEGIN
		SET @Cantidad_Saldo = 0
	END
	
	PRINT 'Se insertará en Cbtes_Items. Id_Trans: ' + CONVERT(VARCHAR(20), @trans) + ' Item: ' + CONVERT(VARCHAR(20), @item_nuevo)

    SELECT * INTO #ITEMSFAM FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item
    UPDATE #ITEMSFAM SET Item = @item_nuevo ,
						 Precio_Grav = @Precio_CS_Integrante,
						 Imp_Gravado = @Precio_CS_Integrante,
						 Imp_Final = @Precio_CS_Integrante,
						 Precio = @Precio_CS_Integrante,
						 Id_Cliente = @id_cliente_Integrante
							
    INSERT INTO Cbtes_Items SELECT * FROM #ITEMSFAM

	PRINT 'Precio Item Inicial: ' + CONVERT(VARCHAR(30), @Imp_Final) 
	SET @Resto_Precio_Final = @Resto_Precio_Final - @Precio_CS_Integrante
	PRINT 'Quedan $' + CONVERT(VARCHAR(30), @Resto_Precio_Final) + ' para dividir entre el resto de los integrantes'
	DROP TABLE #ITEMSFAM

FETCH NEXT FROM curIntegItems
INTO @id_cliente_Integrante
END 
CLOSE curIntegItems;
DEALLOCATE curIntegItems;
/*Cursor recorriendo Todos los Integrantes del Grupo*/

/*Actualizo el Precio del Titular según lo que restaba*/
PRINT 'El Resto de: $' + CONVERT(VARCHAR(30), @Resto_Precio_Final) + ' lo asignará al Titular'

UPDATE Cbtes_Items
SET
	Precio_Grav = @Resto_Precio_Final,
	Imp_Gravado = @Resto_Precio_Final,
	Imp_Final = @Resto_Precio_Final,
	Precio = @Resto_Precio_Final
WHERE
	Id_Trans = @trans
	AND Item = @Item
/*FIN Actualizo el Precio del Titular según lo que restaba*/

PRINT 'FIN SP: SP_Cbtes_Items_Integrantes'
PRINT '-----------------------------------------------------------------------------------'
GO


    /********************************************************************
     SP_Cbtes_Items_Integrantes
     Autor: Gemini AI (ajuste técnico) / Reordenado por Maca
     Fecha: 2025-10-22
     Descripción:
       Calcula y distribuye el importe del grupo familiar:
       - El titular nunca queda negativo.
       - Redondeo a 2 decimales.
       - La suma de integrantes + titular = importe total.
       - Evita cursores, utilizando tabla temporal.
    ********************************************************************/

CREATE PROCEDURE [dbo].[zSP_Cbtes_Items_Integrantes20251103]
    @trans INT,
    @Item SMALLINT,
    @Prod VARCHAR(14)
AS
BEGIN
    SET NOCOUNT ON;



    DECLARE 
        @Id_Familia INT,
        @Id_Cliente INT,
        @Id_Cliente_Ref INT,
        @Id_Cond_Vta CHAR(10),
        @Imp_Final DECIMAL(15,5),
        @Id_Estado_Cbte SMALLINT,
        @Fecha_Venc DATETIME,
        @Lote VARCHAR(20),
        @Bonif DECIMAL(5,2),
        @Descripcion_Producto VARCHAR(100),
        @Flag_QA CHAR(1),
        @Fecha_QA DATETIME,
        @Cant_Integrantes SMALLINT,
        @Precio_CS_Titular DECIMAL(15,5),
        @item_base		SMALLINT,
		@ModoDebug		SMALLINT,
  		@Cond_Pago		SMALLINT,
		@Id_Usuario		SMALLINT,
		@Porc_Iva		DECIMAL(5,2),	
		@Imp_Iva		DECIMAL(15,2),
		@Cantidad_saldo	DECIMAL(15,5),
		@Cantidad		DECIMAL (15,5)
SET @ModoDebug = 0
	
	PRINT '---------------------------------------------------------------'
    PRINT 'Inicio SP_Cbtes_Items_Integrantes | Trans=' + CONVERT(VARCHAR(10),@trans)

    -- 1. Verifica si el comprobante compromete factura
    IF NOT EXISTS(
        SELECT 1 
        FROM Cbtes_Tipos T 
        JOIN Cbtes C ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
        WHERE C.Id_Trans = @trans 
          AND T.Compromete_Factura IN (1,-1)
    )
    BEGIN
        IF @ModoDebug = 1
		BEGIN	
			PRINT 'Tipo de comprobante NO compromete factura. Sale del SP.'
        END
		RETURN
    END

    -- 2. Obtiene cliente titular del comprobante
    SELECT @Id_Cliente = Id_Cliente
    FROM Cbtes
    WHERE Id_Trans = @trans

    IF @Id_Cliente IS NULL OR @Id_Cliente IN (0,1,1105)
    BEGIN
		IF @ModoDebug = 1
		BEGIN
			PRINT 'Id_Cliente no válido o referente. Sale del SP.'
        END
		RETURN
    END

    -- 3. Valida que sea titular (no integrante)
    SELECT @Id_Cliente_Ref = Id_Cliente_Ref,
           @Id_Cond_Vta = Id_Cond_Vta
    FROM Clientes
    WHERE Id_Cliente = @Id_Cliente

    IF @Id_Cliente_Ref <> 0
    BEGIN
        IF @ModoDebug = 1
		BEGIN	
			PRINT 'Cliente es integrante. Sale del SP.'
        END
		RETURN
    END

    IF (LTRIM(RTRIM(@Id_Cond_Vta)) = 'GFCP')
    BEGIN
        IF @ModoDebug = 1
		BEGIN
			PRINT 'Condición de venta GFCP (cobro separado). Sale del SP.'
        END
		RETURN
    END

    -- 4. Verifica familia del producto
    SET @Id_Familia = (SELECT Id_Familia FROM Productos WHERE Id_Producto = @Prod)
    IF @Id_Familia NOT IN (SELECT dbo.CF_xParam('Fam_CuotasSoc'))
        RETURN

    -- 5. Obtiene info del ítem original
    SELECT 
        @Precio_CS_Titular = dbo.SF_CS_Precio_Persona(Id_Cliente, Fecha_QA),
        @Imp_Final = ISNULL(Imp_Final,0),
        @Id_Estado_Cbte = Id_Estado_Cbte,
        @Fecha_Venc = Fecha_Venc,
        @Lote = ISNULL(Lote,''),
        @Flag_QA = Flag_QA,
        @Bonif = ISNULL(Bonif,0),
        @Descripcion_Producto = Descripcion_Producto,
        @Fecha_QA = Fecha_QA,
		@Cond_Pago = Id_Cond_Pago,
		@Id_Usuario = Id_Usuario,
		@Porc_Iva	=Porc_Iva,		
		@Imp_Iva	=Imp_Iva,
		@Cantidad_Saldo	=Cantidad_Saldo,
		@Cantidad		= Cantidad
		
    FROM Cbtes_Items
    WHERE Id_Trans = @trans AND Item = @Item AND Id_Cliente = @Id_Cliente

	IF @ModoDebug = 1
	BEGIN
		PRINT 'Precio CS Titular: ' + CONVERT(VARCHAR(30),@Precio_CS_Titular)
	END
    -- 6. Contar integrantes
    SELECT @Cant_Integrantes = COUNT(*) 
    FROM Clientes 
    WHERE Id_Cliente_Ref = @Id_Cliente 
      AND Activo = 1 
      AND Tipo_Persona = 'F'

    IF @Cant_Integrantes = 0
    BEGIN
		IF @ModoDebug = 1
		BEGIN
			PRINT 'Sin integrantes. Se actualiza solo el titular.'
        END
		UPDATE Cbtes_Items
        SET Precio_Grav = @Precio_CS_Titular,
            Imp_Gravado = @Precio_CS_Titular,
            Imp_Final = @Precio_CS_Titular,
            Precio = @Precio_CS_Titular
        WHERE Id_Trans = @trans AND Item = @Item
        RETURN
    END
	IF @ModoDebug = 1
	BEGIN
		PRINT 'Integrantes detectados: ' + CONVERT(VARCHAR(10),@Cant_Integrantes)
	END
    -- 7. Tabla temporal con todos los miembros del grupo familiar
    SELECT 
        c.Id_Cliente,
        dbo.SF_CS_Precio_Persona(c.Id_Cliente, @Fecha_QA) AS Precio_CS,
        CASE WHEN c.Id_Cliente_Ref = 0 THEN 1 ELSE 0 END AS EsTitular
    INTO #IntegrantesGF
    FROM Clientes c
    WHERE (c.Id_Cliente_Ref = @Id_Cliente OR c.Id_Cliente = @Id_Cliente)
      AND c.Activo = 1
      AND c.Tipo_Persona = 'F'

    -- 8. Calcula ítem base y genera líneas de ítems para integrantes
    SET @item_base = ISNULL((SELECT MAX(Item) FROM Cbtes_Items WHERE Id_Trans = @trans),0) + 1

    SELECT 
        ROW_NUMBER() OVER (ORDER BY Id_Cliente) + (@item_base - 1) AS ItemNuevo,
        i.Id_Cliente,
        i.Precio_CS
    INTO #ItemsNuevos
    FROM #IntegrantesGF i
    WHERE EsTitular = 0

    --  9. Crea registros para cada integrante
	
    INSERT INTO Cbtes_Items (
					Id_Trans,		Item,			Id_Producto,			Id_Estado_Cbte,
					Cantidad,		Precio_Grav,	Imp_Gravado,			Imp_Final, 
					Precio,			Fecha_Venc,		Lote,					Flag_QA,
					Id_Cliente,		Bonif,			Descripcion_Producto,	Cantidad_Saldo,
					Fecha_QA,		Id_Usuario,		Porc_Iva,				Imp_Iva,
					Id_Cond_Pago
				)
    SELECT 
					@trans,			i.ItemNuevo,	'CS',					@Id_Estado_Cbte,
					@Cantidad,		i.Precio_CS,	i.Precio_CS,			i.Precio_CS, 
					i.Precio_CS,	@Fecha_Venc,	@Lote,					@Flag_QA, 
					i.Id_Cliente,	@Bonif,			@Descripcion_Producto,	@Cantidad_saldo,				
					@Fecha_QA,		@Id_Usuario,	@Porc_Iva,				@Imp_Iva,		
					@Cond_Pago
    FROM #ItemsNuevos i
	IF @ModoDebug = 1
    BEGIN
		PRINT 'Se insertaron ' + CONVERT(VARCHAR(10),@@ROWCOUNT) + ' ítems de integrantes.'
	END
    --  10. Actualiza ítem del titular
    UPDATE Cbtes_Items
    SET Precio_Grav = @Precio_CS_Titular,
        Imp_Gravado = @Precio_CS_Titular,
        Imp_Final = @Precio_CS_Titular,
        Precio = @Precio_CS_Titular
    WHERE Id_Trans = @trans AND Item = @Item

    IF @ModoDebug = 1
	BEGIN
		PRINT 'Actualizado ítem del titular con precio CS.'
	END

    DROP TABLE #IntegrantesGF
    DROP TABLE #ItemsNuevos


    PRINT 'Fin SP_Cbtes_Items_Integrantes'
    PRINT '---------------------------------------------------------------'
END
GO

CREATE PROCEDURE [dbo].[zSP_Cbtes_Items_Integrantes_20251015] @trans INT, @Item SMALLINT, @Prod VARCHAR(14)
AS
DECLARE @Id_Familia INT
SET @Id_Familia = (SELECT Id_Familia FROM Productos where Id_Producto = @Prod)

PRINT '-----------------------------------------------------------------------------------'
PRINT 'Ingreso SP: SP_Cbtes_Items_Integrantes'

PRINT 'Id_Trans: ' + CONVERT(VARCHAR(10), @trans) + ' Item: ' + CONVERT(VARCHAR(10), @Item) + ' Producto: ' + @Prod

/*Verifica si el Tipo de Cbte Compromete Factura*/
PRINT 'Verifica si el Tipo de Cbte Compromete Factura'
IF NOT EXISTS(SELECT 1 FROM Cbtes_Tipos T, Cbtes C
              WHERE 
              C.Id_Tipo_Cbte = T.Id_Tipo_Cbte 
              AND C.Id_Trans = @trans 
              AND T.Compromete_Factura in (1,-1))
BEGIN
	PRINT 'El Tipo de Cbte NO compromete Factura'
	PRINT 'SALE DEL SP'
    RETURN
END
PRINT 'El Tipo de Cbte compromete Factura'
/*FIN Verifica si el Tipo de Cbte Compromete Factura*/
   UPDATE Cbtes_Items SET Id_Producto_Orig = Id_Producto  WHERE Id_Trans = @Trans AND Item = @Item
/*Verifica si el Producto es C.S.*/
PRINT 'Verifica si el Producto es C.S.'
IF @Id_Familia not IN (1) 
   RETURN
   
IF @Prod <> 'CS'
   UPDATE Cbtes_Items SET Id_Producto = 'CS' WHERE Id_Trans = @Trans AND Item = @Item AND Id_Producto <> 'CS' 


--IF @Prod <> 'CS'
--BEGIN
--	PRINT 'El Producto NO es CS. Id_Producto: ' + @Prod
--	PRINT 'SALE DEL SP'
--    RETURN
--END
/*FIN Verifica si el Producto es C.S.*/

/*Verifico que el Comprobante sea un Titular*/
DECLARE @Id_Cliente INT
DECLARE @Id_Cliente_Ref INT, @item_nuevo SMALLINT

SET @Id_Cliente = ISNULL((SELECT Id_Cliente FROM Cbtes WHERE Id_Trans = @trans), 0)
PRINT 'Id_Cliente del Cbte: ' + CONVERT(VARCHAR(10), @Id_Cliente)

IF @Id_Cliente IN (0,1, 1105)
BEGIN
	PRINT 'El Id_Cliente es NO DEFINIDO o VARIOS o REFERENTE'
	PRINT 'SALE DEL SP'
    RETURN	
END

SET @Id_Cliente_Ref = ISNULL((SELECT Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @Id_Cliente),0)

IF @Id_Cliente_Ref <> 0
BEGIN
	PRINT 'El Id_Cliente es INTEGRANTE'
	PRINT 'SALE DEL SP'
    RETURN		
END
/*FIN Verifico que el Comprobante sea un Titular*/

DECLARE @Id_Cond_Vta CHAR(10)
SET @Id_Cond_Vta = (SELECT Id_Cond_Vta FROM Clientes WHERE Id_Cliente = @Id_Cliente)

IF (LTRIM(RTRIM(@Id_Cond_Vta)) = 'GFCP')
BEGIN
	PRINT 'La condicion de Venta es: ESPECIAL-G. Fam Cobro x Separado'
	PRINT 'SALE DEL SP'
    RETURN		
END

/*Cantidad de Integrantes*/
DECLARE @Cant_Integrantes SMALLINT
SET @Cant_Integrantes = ISNULL((SELECT COUNT(Id_Cliente) FROM Clientes WHERE Id_Cliente_Ref = @Id_Cliente AND Activo = 1 AND Tipo_Persona='F'), 0)
PRINT 'Cant. de Integrantes del Grupo Familiar: ' + CONVERT(VARCHAR(10), @Cant_Integrantes)

IF @Cant_Integrantes = 0
BEGIN
	PRINT 'No hay Integrantes en el G.F.'
	PRINT 'SALE DEL SP'
    RETURN	
END

DECLARE @Imp_Final DECIMAL(15,5)

SET @Imp_Final = ISNULL((SELECT Imp_Final FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),0)

PRINT 'Importe Final del Item $' + CONVERT(VARCHAR(30), @Imp_Final)

DECLARE @Id_Estado_Cbte SMALLINT
SET @Id_Estado_Cbte = ISNULL((SELECT Id_Estado_Cbte FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),1)
PRINT 'Estado del Item: ' + CONVERT(VARCHAR(10), @Id_Estado_Cbte)

DECLARE @Fecha_Venc DATETIME
SET @Fecha_Venc = ISNULL((SELECT Fecha_Venc FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),GETDATE())
PRINT 'Fecha Vencimiento del Item: ' + CONVERT(VARCHAR(20), @Fecha_Venc, 103)

DECLARE @Lote VARCHAR(20)
SET @Lote = ISNULL((SELECT Lote FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),'')
PRINT 'Lote del Item: ' + @Lote

DECLARE @Flag_QA CHAR(1)
SET @Flag_QA = ISNULL((SELECT Flag_QA FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),1)
PRINT 'Flag QA del Item: ' + @Flag_QA

DECLARE @Fecha_QA DATETIME
SET @Fecha_QA = ISNULL((SELECT Fecha_QA FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),GETDATE())
PRINT 'Fecha QA del Item: ' + CONVERT(VARCHAR(20), @Fecha_QA, 103)

DECLARE @Bonif DECIMAL(5,2)
SET @Bonif = ISNULL((SELECT Bonif FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item),0)
PRINT 'Porc. Bonificacion del Item: ' + CONVERT(VARCHAR(30), @Bonif)

DECLARE @Descripcion_Producto VARCHAR(100)
SET @Descripcion_Producto = ISNULL((SELECT Descripcion_Resumida FROM Productos WHERE Id_Producto = @Prod),'Producto desconocido')
PRINT 'Descripcion del Producto del Item: ' + @Descripcion_Producto


/*Cursor recorriendo Todos los Integrantes del Grupo*/
PRINT 'Se recorren los Integrantes del Grupo'
DECLARE @id_cliente_Integrante	INT;
DECLARE @Precio_CS_Integrante	DECIMAL(15,5);
DECLARE @Nro_Integrante			SMALLINT;
DECLARE @Resto_Precio_Final		DECIMAL(15,5)
DECLARE @Cantidad_Saldo			DECIMAL(15,5)

SET @Nro_Integrante = 0
SET @Resto_Precio_Final = @Imp_Final

DECLARE curIntegItems CURSOR FOR 
		SELECT Id_Cliente FROM Clientes
		WHERE
		Id_Cliente_Ref = @Id_Cliente
		AND Activo = 1
		AND Tipo_Persona='F'
		AND Id_Tipo_Cli  not in (1105) /*Referente*/
		ORDER BY Id_Cli_Relac, Fecha_Nac

OPEN curIntegItems
FETCH NEXT FROM curIntegItems
INTO @id_cliente_Integrante
WHILE @@FETCH_STATUS = 0
BEGIN

	SET @Nro_Integrante = @Nro_Integrante + 1
	SET @Precio_CS_Integrante = dbo.SF_CS_Precio_Persona(@id_cliente_Integrante, @Fecha_QA)
	SET @item_nuevo = ISNULL((SELECT MAX(item) FROM Cbtes_Items WITH (NOLOCK) WHERE Id_Trans = @trans),0) +1
	IF @item_nuevo < 100
	   SET @item_nuevo = 100

	PRINT 'Integrante Nro: ' + CONVERT(VARCHAR(10), @Nro_Integrante) + ' Id_Cliente: ' + CONVERT(VARCHAR(10), @id_cliente_Integrante) + ' Precio CS: $' + CONVERT(VARCHAR(30), @Precio_CS_Integrante)

	
	IF @Id_Estado_Cbte IN (1,4)
	BEGIN
		SET @Cantidad_Saldo = @Precio_CS_Integrante
	END
	ELSE
	BEGIN
		SET @Cantidad_Saldo = 0
	END
	
	PRINT 'Se insertará en Cbtes_Items. Id_Trans: ' + CONVERT(VARCHAR(20), @trans) + ' Item: ' + CONVERT(VARCHAR(20), @item_nuevo)

    SELECT * INTO #ITEMSFAM FROM Cbtes_Items WHERE Id_Trans = @trans AND Item = @Item
    UPDATE #ITEMSFAM SET Item = @item_nuevo ,
						 Precio_Grav = @Precio_CS_Integrante,
						 Imp_Gravado = @Precio_CS_Integrante,
						 Imp_Final = @Precio_CS_Integrante,
						 Precio = @Precio_CS_Integrante,
						 Id_Cliente = @id_cliente_Integrante
							
    INSERT INTO Cbtes_Items SELECT * FROM #ITEMSFAM

	PRINT 'Precio Item Inicial: ' + CONVERT(VARCHAR(30), @Imp_Final) 
	SET @Resto_Precio_Final = @Resto_Precio_Final - @Precio_CS_Integrante
	PRINT 'Quedan $' + CONVERT(VARCHAR(30), @Resto_Precio_Final) + ' para dividir entre el resto de los integrantes'
	DROP TABLE #ITEMSFAM

FETCH NEXT FROM curIntegItems
INTO @id_cliente_Integrante
END 
CLOSE curIntegItems;
DEALLOCATE curIntegItems;
/*Cursor recorriendo Todos los Integrantes del Grupo*/

/*Actualizo el Precio del Titular según lo que restaba*/
PRINT 'El Resto de: $' + CONVERT(VARCHAR(30), @Resto_Precio_Final) + ' lo asignará al Titular'

UPDATE Cbtes_Items
SET
	Precio_Grav = @Resto_Precio_Final,
	Imp_Gravado = @Resto_Precio_Final,
	Imp_Final = @Resto_Precio_Final,
	Precio = @Resto_Precio_Final
WHERE
	Id_Trans = @trans
	AND Item = @Item
/*FIN Actualizo el Precio del Titular según lo que restaba*/

PRINT 'FIN SP: SP_Cbtes_Items_Integrantes'
PRINT '-----------------------------------------------------------------------------------'
GO

CREATE PROCEDURE [dbo].[zSP_Ult_Cuota_Paga] @pId_Trans INT, @pItem INT, @pId_Producto CHAR(14) 
AS
DECLARE @Id_Familia		INT
DECLARE @Id_Estado_Cbte	INT
DECLARE @Ult_Cuota_Paga	DATETIME
DECLARE @UCP			DATETIME
DECLARE @Id_Cliente		INT
DECLARE @UCP_Especial	DATETIME

PRINT 'Ingreso a SP_Ult_Cuota_Paga'

PRINT '@pId_Trans: ' + CONVERT(VARCHAR(10), @pId_Trans) + ' @pItem: ' + CONVERT(VARCHAR(10), @pItem) + ' @pId_Producto: ' + @pId_Producto
  
/*Busco cual es la Familia de Producto*/
SET @Id_Familia = (SELECT Id_Familia FROM Productos where Id_Producto = @pId_Producto)

IF (@Id_Familia = (dbo.CF_xParam('Fam_CuotasSoc')))
BEGIN
	/*Todos los productos de la familia Cuota Social los actualiza al producto CS*/
	--IF (@pId_Producto <> 'CS') 15/12/2020 se modifica para contemplar los productos anuales que nos los cambien (porque controlan por Fecha_QA y Fecha_Venc)
	IF (@pId_Producto <> 'CS' AND @pId_Producto NOT IN ('1487','1488','1489'))
	BEGIN
	   UPDATE Cbtes_Items SET Id_Producto = 'CS' WHERE Id_Trans = @pId_Trans AND Item = @pItem AND Id_Producto <> 'CS' 
	END
	/*FIN Todos los productos de la familia Cuota Social los actualiza al producto CS*/
	   
	SET @Id_Estado_Cbte = (SELECT Id_Estado_Cbte FROM Cbtes where Id_Trans = @pId_Trans) 
	PRINT 'Id_Estado_Cbte: ' + CONVERT(VARCHAR(10), @Id_Estado_Cbte)


	IF (@Id_Estado_Cbte IN (2, 1, 3, 4))
	BEGIN	   
		SET @Id_Cliente = (SELECT Id_Cliente FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Item = @pItem)			

		IF(@Id_Cliente NOT IN (0, 1))
		BEGIN
			PRINT 'Id_Cliente: ' + CONVERT(VARCHAR(10), @Id_Cliente)
			SET @Ult_Cuota_Paga = (SELECT ISNULL(Ult_Cuota_Paga, '19000101') FROM Clientes WHERE Id_Cliente = @Id_Cliente)
			
			--SET @UCP			= (	SELECT MAX(CI.Fecha_QA)
			--						FROM Cbtes_Items CI, Cbtes CB, Productos PR, Cbtes_Tipos CT
			--						WHERE 
			--						CB.Id_Trans = CI.Id_Trans 							
			--						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte 
			--						AND PR.Id_Producto = CI.Id_Producto
			--						AND CT.Compromete_Factura IN (1)
			--						AND CB.Id_Estado_Cbte IN (2/*Completo*/)
			--						AND PR.Id_Familia = (DBO.CF_xParam('Fam_CuotasSoc'))
			--						AND CI.Id_Cliente = @Id_Cliente)
									
			SET @UCP			= 	dbo.SF_Ult_Cuota_Paga(@Id_Cliente, GETDATE())
			--SET @UCP			= GETDATE()
			
			/*Se agrega un tipo de Cbte capaz de modificar la última cuota paga en caso de encontrase en estado Pendiente*/
			SET @UCP_Especial = (dbo.CF_Clientes_UCP_xCbteEsp(@Id_Cliente)) 
			--SET @UCP_Especial	= GETDATE()
			
			IF(@UCP_Especial <> '19000101')
			BEGIN
				SET @UCP = @UCP_Especial
			END
													
			PRINT 'Ultima Cuota Paga Calculada: ' + CONVERT(VARCHAR(10), @UCP, 103)

			IF(@Ult_Cuota_Paga <> @UCP)
			BEGIN
				UPDATE Clientes 
				SET Ult_Cuota_Paga = @UCP
				WHERE 
				Id_Cliente = @Id_Cliente 
				/*OR Id_Cliente_Ref = @Id_Cliente*/ /*Se saco la condición por mail enviado por silvia el 28/7*/
			END
		END
	END
END
GO

CREATE PROCEDURE [dbo].[zSP_Vitalicios_Hist_20241016] @pFecha_Desde DATETIME, @pFecha_Hasta DATETIME
AS

IF object_id('tempdb..#Categ_Ant') is null
BEGIN
    SELECT * INTO #Categ_Ant FROM Clientes_Tipos
END

SELECT distinct ch.id_cliente,
cl.Razon_Social,
CAST(cl.Fecha_Nac as DATE) as Fecha_Nac,
DATEDIFF(YEAR,cl.Fecha_Nac,GETDATE())as Edad,
cl.Sexo,
ch.Id_Tipo_Cli as Id_Categ_Anterior,
clt2.Descripcion as Categ_Anterior,
cl.Id_Tipo_Cli as Id_Categ_Actual,
clt.Descripcion as Categ_Actual,
MAX(CAST(ch.Fecha as DATE))as Fecha,
cl.Activo

from
Clientes_Hist ch,
Clientes cl,
Clientes_Tipos clt,
#Categ_Ant clt2

where
ch.Id_Cliente=cl.Id_Cliente
and cl.id_tipo_cli=clt.id_tipo_cli
and clt2.Id_Tipo_Cli=ch.Id_Tipo_Cli
and ch.Fecha>=@pFecha_Desde AND ch.Fecha<= @pFecha_Hasta
--and ch.Fecha>='20160701' AND ch.Fecha<= '20170630'
and ch.Id_Tipo_Cli<>cl.Id_Tipo_Cli
and (ch.Id_Tipo_Cli in (select id_tipo_cli from clientes_tipos where Descripcion like '%vital%')
     or (ch.Id_Tipo_Cli = 1003 and cl.Id_Tipo_Cli = 1055))

GROUP BY
ch.id_cliente,
cl.Razon_Social,
cl.Fecha_Nac,
cl.Sexo,
ch.Id_Tipo_Cli,
cl.Id_Tipo_Cli,
clt.Descripcion,
clt2.Descripcion ,
ch.Fecha,
cl.Activo

ORDER BY 9, 2
GO


CREATE PROCEDURE [dbo].[z_BU_CP_Cbtes_Ctas_Contables_Generar] 
			@pId_Trans		INT, 
			@pFlagRegenerar TINYINT
AS
SET NOCOUNT ON


IF EXISTS (SELECT 1 FROM sys.objects WHERE name = 'CP_Cbtes_Ctas_Contables_Generar_' AND type = 'P')
BEGIN
		EXEC CP_Cbtes_Ctas_Contables_Generar_ @pId_Trans,@pFlagRegenerar
		RETURN
END

DECLARE @Usar_Trans			TINYINT
--SET @Usar_Trans = ISNULL((SELECT 1 WHERE SERVERPROPERTY('ProductVersion') > '10.50.4000.0'),0)
IF @@TRANCOUNT > 0 SET @Usar_Trans = 0


/*Declaracion de Variables*/
DECLARE @Flag_Compromete_Asientos	SMALLINT
DECLARE @Flag_Compromete_Factura	SMALLINT
DECLARE @Flag_Compromete_Trans_Fondos SMALLINT
DECLARE @Flag_Compromete_Recibos	SMALLINT
DECLARE @Fecha_Cbte					DATETIME
DECLARE @Id_Cliente					INT
DECLARE @Id_Tipo_Cbte				CHAR(4)
DECLARE @Id_Cta_Contable			INT
DECLARE @Alias						INT
DECLARE @Id_Asiento					INT
DECLARE @Id_Centro_Costo			CHAR(10)
DECLARE @Id_Ejercicio_Corresp		INT
DECLARE @Id_Plan_Cta_Corresp		INT
DECLARE @Imp_Total_Cbte				DECIMAL(12,2)
DECLARE @Debe						DECIMAL(12,2)
DECLARE @Haber						DECIMAL(12,2)
DECLARE @Id_Producto				VARCHAR(14)
DECLARE @Id_Tipo_Reten				VARCHAR(10)
DECLARE @NroItem					SMALLINT
DECLARE @CMC_UltItem				SMALLINT
DECLARE @CMC_UltId_Periodo_Caja		INT
DECLARE @CMC_Id_Concepto			INT
DECLARE @VAL_UltId_Valor			INT
DECLARE @VAL_UltId_Periodo_Caja		INT
DECLARE @VAL_Id_Tipo_Val			CHAR(3)
DECLARE @Id_Cond_Pago				SMALLINT
DECLARE @VAL_Id_Periodo_Caja		INT
DECLARE @CP_Id_Caja					INT
DECLARE @ID_TARJETA                 VARCHAR(10)
DECLARE @ID_CTA_BANCO               SMALLINT
DECLARE @ID_TRANS_ORIGEN            INT
DECLARE @Mensaje					VARCHAR(100)
/*FIN Declaracion de Variables*/

--PRINT 'Procedimiento: CP_Cbtes_Ctas_Contables_Generar Trans: '+ CAST(@pId_Trans AS VARCHAR(10))

IF(@pId_Trans = 0)
BEGIN
	RETURN 999
END

BEGIN TRY
	IF @Usar_Trans = 1 BEGIN TRAN

	IF(@pFlagRegenerar = 1)
	BEGIN
		DELETE FROM Cbtes_Ctas_Contables WHERE Id_Trans = @pId_Trans
	END

	/*************************************************************************************************/

	SET @Id_Tipo_Cbte				= (SELECT Id_Tipo_Cbte FROM Cbtes WHERE Id_Trans = @pId_Trans)

	SELECT  @Flag_Compromete_Asientos		= ISNULL(Compromete_Asientos, 0),
			@Flag_Compromete_Factura		= ISNULL(Compromete_Factura, 0),
			@Flag_Compromete_Trans_Fondos	= ISNULL(Compromete_Trans_Fondos, 0),
			@Flag_Compromete_Recibos		= ISNULL(Compromete_Recibos, 0)
	FROM Cbtes_Tipos
	WHERE 
	Id_Tipo_Cbte = @Id_Tipo_Cbte

	/*************************************************************************************************/

	IF(@Flag_Compromete_Asientos = 0)
	BEGIN
		IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 COMMIT
		SET @Mensaje = 'El Cbte. no Genera Asiento'

		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
			
		RETURN 0
	END

	/*************************************************************************************************/

	SELECT  @Id_Cliente		= ISNULL(Id_Cliente, 0),
			@Fecha_Cbte		= ISNULL(Fecha, '19000101'),
			@Imp_Total_Cbte	= ISNULL(Imp_Total, 0)
	FROM Cbtes
	WHERE 
	Id_Trans = @pId_Trans

	/*************************************************************************************************/

	SET @Id_Ejercicio_Corresp = (SELECT Id_Ejercicio FROM Plan_Ctas_Ejercicios WHERE Fecha_Inicio <= @Fecha_Cbte AND DATEADD(dd, 1, Fecha_Cierre) > @Fecha_Cbte)
	SET @Id_Plan_Cta_Corresp = (SELECT Id_Plan_Cta FROM Plan_Ctas WHERE Id_Ejercicio = @Id_Ejercicio_Corresp)
	----PRINT 'Nro. de Ejercicio: ' + CONVERT(VARCHAR(10), @Id_Ejercicio_Corresp) + '. Nro. Plan de Cuenta: ' + CONVERT(VARCHAR(10), @Id_Plan_Cta_Corresp)

	IF(@Flag_Compromete_Factura = 1)
	BEGIN
		----PRINT 'Compromete Factura'
	
		SET @Id_Cond_Pago = (SELECT Id_Cond_Pago FROM Cbtes WHERE Id_Trans = @pId_Trans)
	
		IF(@Id_Cond_Pago NOT IN (1)) /*Si no es contado*/
		BEGIN
			----PRINT 'Cond. Pago NO ES CONTADO. @Id_Cond_Pago: ' + CONVERT(VARCHAR(10), @Id_Cond_Pago)
		
			/*Insert: Cuenta Contable: DEBE (SI la Cond. Pago NO es Contado)*/
			----PRINT 'Generacion Cuenta Contable: DEBE'
			SET @Alias = (SELECT Id_Alias_Cta_Cont_Venta FROM Clientes WHERE Id_Cliente = @Id_Cliente)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = (SELECT Id_Centro_Costo FROM Clientes WHERE Id_Cliente = @Id_Cliente)
			SET @Debe = @Imp_Total_Cbte
			SET @NroItem = 1
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			@Debe,			0/*Haber*/,			''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)
			/*FIN Insert: Cuenta Contable: DEBE (SI la Cond. Pago NO es Contado)*/
		END
		ELSE
		BEGIN
			----PRINT 'Cond. Pago ES CONTADO'
		
			/*Insert: Cuenta Contable: DEBE (SI la Cond. Pago ES Contado)*/
			----PRINT 'Generacion Cuenta Contable: DEBE'
			SET @VAL_Id_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE Id_Trans = @pId_Trans), 0)		
			SET @CP_Id_Caja = ISNULL((SELECT Id_Caja FROM Cajas_Periodos WHERE Id_Periodo_Caja = @VAL_Id_Periodo_Caja), 0)		
			SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Cajas WHERE Id_Caja = @CP_Id_Caja), 0)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Alias = @Alias AND Id_Plan_Cta = @Id_Plan_Cta_Corresp)
			SET @Id_Centro_Costo = ISNULL((SELECT Id_Cta_Contable FROM Cajas WHERE Id_Caja = @CP_Id_Caja), '')
			SET @Debe = @Imp_Total_Cbte
			SET @NroItem = 1
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
		
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			@Debe,			0/*Haber*/,			''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)
			/*FIN Insert: Cuenta Contable: DEBE (SI la Cond. Pago ES Contado)*/
		END
	
		/*Insert: Cuenta Contable: HABER*/
		----PRINT 'Generacion Cuenta Contable: HABER'
	
		--PRINT 'Generacion de Items de Productos'
		DECLARE curGenCtaCteHaber CURSOR FOR 
			SELECT DISTINCT Id_Producto FROM Cbtes_Items WHERE Id_Trans = @pId_Trans

		OPEN curGenCtaCteHaber
		FETCH NEXT FROM curGenCtaCteHaber INTO @Id_Producto
		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @Alias = (SELECT Id_Alias_Cta_Cont FROM Productos WHERE Id_Producto = @Id_Producto)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = (SELECT Id_Centro_Costo FROM Productos WHERE Id_Producto = @Id_Producto)
			SET @Haber = (SELECT SUM(Imp_Gravado) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Id_Producto = @Id_Producto)
			SET @NroItem = @NroItem + 1
		
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Producto: ' + @Id_Producto + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)

		FETCH NEXT FROM curGenCtaCteHaber INTO @Id_Producto
		END 
		CLOSE curGenCtaCteHaber;
		DEALLOCATE curGenCtaCteHaber;
		/*FIN Insert: Cuenta Contable: HABER*/
	
		----PRINT 'Generacion de Items de Percepciones'	
		DECLARE curGenCtaCteHaberPercep CURSOR FOR 
			SELECT DISTINCT Id_Tipo_Reten	FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans

		OPEN curGenCtaCteHaberPercep
		FETCH NEXT FROM curGenCtaCteHaberPercep INTO @Id_Tipo_Reten
		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @Alias = (SELECT Id_Cta_Contable FROM Cbtes_Reten_Tipos WHERE Id_Tipo_Reten = @Id_Tipo_Reten)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = ''
			SET @Haber = (SELECT SUM(Importe) FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans AND Id_Tipo_Reten = @Id_Tipo_Reten)
			SET @NroItem = @NroItem + 1
		
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Tipo_Reten: ' + @Id_Tipo_Reten + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)

		FETCH NEXT FROM curGenCtaCteHaberPercep INTO @Id_Tipo_Reten
		END 
		CLOSE curGenCtaCteHaberPercep;
		DEALLOCATE curGenCtaCteHaberPercep;
	
		----PRINT 'Generacion de Items de Iva'
		SET @Alias = (SELECT ISNULL(Valor_Integer,0) FROM xParametros WHERE IdParametro = 'Iva_Debito_Fiscal')
		SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
		SET @Id_Centro_Costo = ''
		SET @Haber = (SELECT SUM(Imp_Iva) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Id_Producto IN (SELECT Id_Producto FROM Productos WHERE Id_Iva IN (SELECT Id_Iva FROM Productos_TasaIva WHERE (Porc1 <> 0 OR Porc1 IS NOT NULL))))
	
		IF(@Haber <> 0)
		BEGIN
			SET @NroItem = @NroItem + 1
		
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)		
		END
	
		----PRINT 'FIN Compromete Factura'
	END /*IF(@Flag_Compromete_Factura = 1)*/


	IF(@Flag_Compromete_Trans_Fondos = 1)
	BEGIN
		----PRINT 'Compromete Transferencia de Fondos'
	
		/*Insert: Cuenta Contable: DEBE*/
		----PRINT 'Generacion Cuenta Contable: DEBE'
		SET @CMC_UltItem = ISNULL((SELECT MAX(Item) FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Cajas_Mov_Conceptos. Ult. Item Generado: ' + CONVERT(VARCHAR(10), @CMC_UltItem)
	
		IF(@CMC_UltItem <> 0)
		BEGIN
			SET @CMC_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans AND Item = @CMC_UltItem), 0)
		
			----PRINT 'Generacion de Items por cada concepto del Periodo de Caja: ' + CONVERT(VARCHAR(10), @CMC_UltId_Periodo_Caja)
			DECLARE curGenCtaCteDebe_CMC CURSOR FOR 
				SELECT DISTINCT Id_Concepto FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans
								AND Id_Periodo_Caja = @CMC_UltId_Periodo_Caja
		
			SET @NroItem = 0
		
			OPEN curGenCtaCteDebe_CMC
			FETCH NEXT FROM curGenCtaCteDebe_CMC INTO @CMC_Id_Concepto
			WHILE @@FETCH_STATUS = 0
			BEGIN

				SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Conceptos WHERE Id_Concepto = @CMC_Id_Concepto),0)
				SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)	
				SET @Haber = (SELECT ISNULL(SUM(Importe), 0) FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans AND Id_Concepto = @CMC_Id_Concepto AND Id_Periodo_Caja = @CMC_UltId_Periodo_Caja)
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Concepto: ' + CONVERT(VARCHAR(10), @CMC_Id_Concepto) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				@Debe,			0/*Haber*/,			''/*Observacion*/,
				@Alias,			0/*Id_Asiento*/,	''/*Id_Centro_Costo*/,
				@NroItem)

				FETCH NEXT FROM curGenCtaCteDebe_CMC INTO @CMC_Id_Concepto
			END 
			CLOSE curGenCtaCteDebe_CMC;
			DEALLOCATE curGenCtaCteDebe_CMC;
		END /*IF(@CMC_UltItem <> 0)*/
	
		/*Insert: Cuenta Contable: HABER*/
		----PRINT 'Generacion Cuenta Contable: HABER'
		SET @VAL_UltId_Valor = ISNULL((SELECT MAX(Id_Valor) FROM Valores WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
	
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
			SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE Id_Trans = @pId_Trans AND Id_Valor = @VAL_UltId_Valor), 0)
		
			----PRINT 'Generacion de Items por cada Id_Tipo_Val del Periodo de Caja: ' + CONVERT(VARCHAR(10), @VAL_UltId_Periodo_Caja)
			DECLARE curGenCtaCteHaber_Val CURSOR FOR 
				SELECT DISTINCT Id_Tipo_Val 
				FROM Valores 
				WHERE 
				Id_Trans = @pId_Trans
				AND Id_Periodo_Caja = @VAL_UltId_Periodo_Caja
		
			OPEN curGenCtaCteHaber_Val
			FETCH NEXT FROM curGenCtaCteHaber_Val INTO @VAL_Id_Tipo_Val
			WHILE @@FETCH_STATUS = 0
			BEGIN
				SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tipos WHERE Id_Tipo_Val = @VAL_Id_Tipo_Val), 0)
				SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
				SET @Haber = (SELECT SUM(Importe) FROM Valores WHERE Id_Trans = @pId_Trans AND Id_Tipo_Val = @VAL_Id_Tipo_Val AND Id_Periodo_Caja = @VAL_UltId_Periodo_Caja)
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				0/*Debe*/,		@Haber,				''/*Observacion*/,
				@Alias,			0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)

				FETCH NEXT FROM curGenCtaCteHaber_Val INTO @VAL_Id_Tipo_Val
			END 
			CLOSE curGenCtaCteHaber_Val;
			DEALLOCATE curGenCtaCteHaber_Val;		
		END
	
		----PRINT 'FIN Compromete Transferencia de Fondos'
	END /*IF(@Flag_Compromete_Trans_Fondos = 1)*/

	IF(@Flag_Compromete_Recibos = 1)
	BEGIN
	    DECLARE @Tomar_Asiento_Cbte SMALLINT 
		SET @Tomar_Asiento_Cbte = (SELECT ISNULL(Valor_Integer,0) FROM xParametros WHERE IdParametro = 'Tomar_Asiento_Cbte') 

	    SET @NroItem = 1	
		----PRINT 'Compromente Recibos'
		
		----PRINT 'Generacion Cuenta Contable: DEBE'

		SET @VAL_UltId_Valor = ISNULL((SELECT MAX(Id_Valor) FROM Valores_Mov WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
	
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
			SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE  Id_Valor = @VAL_UltId_Valor), 0)
		
			----PRINT 'Generacion de Items por cada Id_Tipo_Val del Periodo de Caja: ' + CONVERT(VARCHAR(10), @VAL_UltId_Periodo_Caja)
			DECLARE curGenCtaDEBE_Val CURSOR FOR 
					SELECT DISTINCT V.Id_Tipo_Val,ISNULL(V.ID_TARJETA,''),ISNULL(V.ID_CTA_BANCO,0)
					FROM Valores_MOV M, VALORES V 
					WHERE 
					M.Id_Trans = @pId_Trans
					AND M.ID_VALOR = V.ID_VALOR
					AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja
		
			OPEN curGenCtaDEBE_Val
			FETCH NEXT FROM curGenCtaDEBE_Val INTO @VAL_Id_Tipo_Val,@ID_TARJETA,@ID_CTA_BANCO
			WHILE @@FETCH_STATUS = 0
			BEGIN
			    SET @Alias = 0 
			    IF @VAL_Id_Tipo_Val = 'TAR'
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tarjetas_Cred WHERE ID_TARJETA = @ID_TARJETA), 0)
                   END
			    IF @VAL_Id_Tipo_Val = 'DB'
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Bancos_Ctas WHERE Id_Cta_Banco = @ID_CTA_BANCO), 0)
                   END	    
				IF @Alias = 0  
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tipos WHERE Id_Tipo_Val = @VAL_Id_Tipo_Val), 0)
                   END


				SET @Id_Cta_Contable = 	  (SELECT dbo.CF_Cta_Cont(@Alias, @Fecha_Cbte))
				SET @NroItem = @NroItem + 1
			    SET @Id_Centro_Costo = ''
			    SET @Debe = (SELECT SUM(V.Importe) FROM Valores V, Valores_Mov M WHERE M.Id_Trans = @pId_Trans AND M.id_valor = V.Id_Valor And V.Id_Tipo_Val = @VAL_Id_Tipo_Val AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja AND ISNULL(V.Id_Tarjeta,'') = @ID_TARJETA AND ISNULL(V.Id_Cta_Banco,0) = @Id_Cta_Banco)
	
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				@Debe,		0,				''/*Observacion*/,
				@Alias,		0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)

				FETCH NEXT FROM curGenCtaDEBE_Val INTO @VAL_Id_Tipo_Val,@ID_TARJETA,@ID_CTA_BANCO
			END 
			CLOSE curGenCtaDEBE_Val;
			DEALLOCATE curGenCtaDEBE_Val;		
		END

		/*Insert: Cuenta Contable: HABER*/
		----PRINT 'Generacion Cuenta Contable: HABER'
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
		
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
		    IF @Tomar_Asiento_Cbte = 0
			BEGIN
				SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE Id_Valor = @VAL_UltId_Valor), 0)
				
				SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont_Venta FROM Clientes WHERE Id_Cliente = @Id_Cliente), 0)
				SET @Id_Cta_Contable = (SELECT dbo.CF_Cta_Cont(@Alias, @Fecha_Cbte))
				SET @Haber = (SELECT SUM(V.Importe) FROM Valores V, Valores_Mov M WHERE M.Id_Trans = @pId_Trans AND M.id_valor = V.Id_Valor  AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja )
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				0/*Debe*/,		@Haber,				''/*Observacion*/,
				@Alias,			0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)
		    END
		   ELSE
			BEGIN
			SELECT * INTO #CTAS_AUX FROM CBTES_CTAS_CONTABLES WHERE ID_TRANS = 1
			DELETE #CTAS_AUX

			DECLARE curGenCtaDEBE_FAC_APLIC2 CURSOR FOR 


			SELECT ID_TRANS
				FROM CBTES_APLICA WHERE ID_TRANS_D = @pId_Trans

		
				OPEN curGenCtaDEBE_FAC_APLIC2
				FETCH NEXT FROM curGenCtaDEBE_FAC_APLIC2 INTO @ID_TRANS_ORIGEN
				WHILE @@FETCH_STATUS = 0
				BEGIN
				    INSERT INTO #CTAS_AUX
					    SELECT * FROM CBTES_CTAS_CONTABLES WHERE ID_TRANS = @ID_TRANS_ORIGEN AND DEBE <> 0

				    FETCH NEXT FROM curGenCtaDEBE_FAC_APLIC2 INTO  @ID_TRANS_ORIGEN
		    	END 

				ALTER TABLE #CTAS_AUX ADD _Item INT IDENTITY(20,1)
		      	UPDATE #CTAS_AUX SET ID_TRANS = @pId_Trans,  Id_Cta_Contable = (SELECT dbo.CF_Cta_Cont(Alias, @Fecha_Cbte))
				UPDATE #CTAS_AUX SET Item = _Item, Id_Asiento = 0, Fecha = @Fecha_Cbte, HABER = DEBE
				UPDATE #CTAS_AUX SET DEBE = 0
				ALTER TABLE #CTAS_AUX DROP COLUMN _Item

				INSERT INTO CBTES_CTAS_CONTABLES 
				       SELECT * FROM #CTAS_AUX
                DROP TABLE #CTAS_AUX

			    CLOSE curGenCtaDEBE_FAC_APLIC2
			    DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 
	    	END
		
		END ----PRINT 'FIN Compromente Recibos'
	END	

	IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 COMMIT

	SET @Mensaje = 'Asiento Generado'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,@pId_Trans				AS ErrorLine		
			,@Mensaje		AS ErrorMessage

END TRY  


BEGIN CATCH  
  --  SELECT  ERROR_NUMBER() AS ErrorNumber  
		--,ERROR_SEVERITY() AS ErrorSeverity  
		--,ERROR_STATE() AS ErrorState  
		--,ERROR_PROCEDURE() AS ErrorProcedure  
		--,ERROR_LINE() AS ErrorLine  
		--,ERROR_MESSAGE() AS ErrorMessage
		--,@pId_Trans		AS Id_Trans 
    EXECUTE usp_GetErrorInfo
	IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 ROLLBACK

	IF (SELECT CURSOR_STATUS('global','curGenCtaDEBE_FAC_APLIC2') ) = -1
	   DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 

	IF (SELECT CURSOR_STATUS('global','curGenCtaDEBE_FAC_APLIC2') ) = 1
	BEGIN
	   CLOSE curGenCtaDEBE_FAC_APLIC2
	   DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 
	END



	RETURN 9999

END CATCH

--PRINT 'Fin de ejecucion: CP_Cbtes_Ctas_Contables_Generar  Trans: '+ CAST(@pId_Trans AS VARCHAR(10))

RETURN 0



-- EXEC CP_Cbtes_Ctas_Contables_Generar 298281,1

-- EXEC CP_Cbtes_Ctas_Contables_Generar 1232043,1
GO


CREATE FUNCTION [dbo].[z_CFUJ_Contrato_Cli_Hab_20260126](@pJson VARCHAR(8000))
RETURNS VARCHAR(8000)
AS
BEGIN

/*Variables recibidas por parametro a traves del JSON*/
DECLARE @pId_Cliente		INT
DECLARE @pId_Familia		INT
DECLARE @pId_Producto		VARCHAR(14)
DECLARE @pObservacion		TINYINT


SET @pId_Cliente			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Cliente')), 0)
SET @pId_Familia			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Familia')), 0)
SET @pId_Producto			= ISNULL(CONVERT(VARCHAR(14), dbo.CF_JSON_VALUE(@pJson,'Id_Producto')), '')
SET @pObservacion			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'Observacion')), 0)

/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variables Locales*/
DECLARE @Respuesta			VARCHAR(8000)
DECLARE @Observacion		VARCHAR(8000) = ''

DECLARE @Inscripto			TINYINT
DECLARE @Existe_Contrato    TINYINT
/*FIN Variables Locales*/


--==========================================================================================
/*IMPLEMENTAR*/
--==========================================================================================

-- Ticket #011090
-- Si el socio esta inscripto en el torneo de futbol (contrato cod. 12), si está inscripto paga el producto 2500, sino paga el 2503
SET @pId_Familia = ISNULL((SELECT TOP 1 Id_Familia FROM Productos WHERE Id_Producto = @pId_Producto),0)

IF (@pId_Familia = 48 /*CFF CENTRO DE FORMACION DE FUTBOL*/)
BEGIN
    SET @Inscripto = ISNULL((SELECT TOP 1 1 
                             FROM Contratos 
                             WHERE Activo = 1 
                               AND Fecha_Hasta >= GETDATE() 
                               AND Id_Tipo_Con = 12 
                               AND Id_Cliente = @pId_Cliente), 0)

    IF (@Inscripto = 0 AND @pId_Producto = '2500')
    BEGIN
        SET @Respuesta = '0'
	END
	
    IF (@Inscripto = 1 AND @pId_Producto = '2503') 
    BEGIN
        SET @Respuesta = '0'
    END
END

---------------------------------------------------------------------------------------
/*INSTITUTO*/
declare @Id_Tipo_Cli int
--SET @pId_Familia = ISNULL((SELECT TOP 1 Id_Familia FROM Productos WHERE Id_Producto = @pId_Producto),0)
SET @Id_Tipo_Cli = ISNULL((SELECT Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @pId_Cliente),0)

IF(@Id_Tipo_Cli = 1127)
BEGIN

		SET @Existe_Contrato = ISNULL((SELECT TOP 1 1 
								 FROM Contratos 
								 WHERE Activo = 1 
								   AND ISNULL(Fecha_Hasta,GETDATE()+1) >= GETDATE() 
								   AND Id_Tipo_Con = 1 
								   AND Id_Cliente = @pId_Cliente), 0)
		IF (@Existe_Contrato = 1)
		BEGIN
			IF(@pId_Familia = 62)
			BEGIN
				SET @Respuesta = 0
				RETURN @Respuesta
			END

		END

		IF(@pId_Familia = 4)
			BEGIN
				SET @Respuesta = 0
				RETURN @Respuesta
			END
END



/*
IF (@pId_Cliente > 0 AND @pId_Producto IN ( '1185'	/*INSTITUTO - CUOTA MENSUAL                             */,
											'1186'	/*INSTITUTO - CUOTA MENSUAL 4 A 8 MATERIAS				*/,
											'1187'	/*INSTITUTO - CUOTA MENSUAL 4 A 8 MATERIAS NO SOCIO		*/,
											'1188'	/*INSTITUTO - CUOTA MENSUAL HASTA 3 MATERIAS			*/,
											'1189'	/*INSTITUTO - CUOTA MENSUAL HASTA 3 MATERIAS NO SOCIO	*/,
											'1190'	/*INSTITUTO - CUOTA MENSUAL NO SOCIO					*/,
											'1191'	/*INSTITUTO - CUOTA MENSUAL UNA MATERIA					*/,
											'1192'	/*INSTITUTO - CUOTA MENSUAL UNA MATERIA NO SOCIO		*/,
											'1193'	/*INSTITUTO - EXAMEN LIBRE								*/,
											'1194'	/*INSTITUTO - EXAMEN LIBRE NO SOCIO						*/,
											'1195'	/*INSTITUTO - MATRICULA ANUAL							*/,
											'1196'	/*INSTITUTO - MATRICULA ANUAL NO SOCIO					*/))
BEGIN
	SET @Respuesta = (SELECT COUNT(*) 
						FROM Cbtes C, Cbtes_items I, Productos P, Cbtes_tipos CT
						WHERE C.id_trans=I.id_trans
						AND I.id_producto=p.id_producto
						AND C.id_tipo_cbte=CT.id_tipo_cbte
						AND P.id_familia=4
						AND C.id_estado_cbte=1
						AND CT.compromete_factura=1
						AND I.id_cliente=@pId_Cliente
						)
	IF @Respuesta <1
	BEGIN
		SET @Respuesta =1
	END
    ELSE
    BEGIN
        SET @Observacion = 'Posee Deuda de Instituto.'
    END
END*/

IF (@pId_Cliente > 0 
    AND @pId_Producto IN (
        '1185','1186','1187','1188','1189','1190','1191','1192',
        '1193','1194','1195','1196'
    ))
BEGIN
    SELECT @Respuesta = COUNT(*)
    FROM Cbtes C
    INNER JOIN Cbtes_items I ON C.id_trans = I.id_trans
    INNER JOIN Productos P ON I.id_producto = P.id_producto
    INNER JOIN Cbtes_tipos CT ON C.id_tipo_cbte = CT.id_tipo_cbte
    WHERE P.id_familia = 4            -- productos del instituto
      AND C.id_estado_cbte = 1        -- impago
      AND CT.compromete_factura = 1   -- genera deuda
      AND I.id_cliente = @pId_Cliente;

    IF @Respuesta >= 1
    BEGIN
		IF(@pObservacion = 1)
		BEGIN
			SET @Observacion = 'Posee Deuda de Instituto'
		END
        SET @Respuesta = 0;
    END
    ELSE
    BEGIN
        SET @Respuesta = 1; -- OK sin deuda
    END
END



IF(@pObservacion = 1)
BEGIN
    RETURN ISNULL(@Observacion, '')
END

-----------------------------------------------------------------------------------------
RETURN ISNULL(@Respuesta,'1')
END

---------------------------------------------------------------------------------------------
GO


CREATE PROCEDURE [dbo].[z_CPJ_Clientes_Deuda_a_Fecha_V4_20241226] @pJsonRecibido VARCHAR(8000)
AS 
SET NOCOUNT ON
/*Parametros*/

DECLARE 	@pFechaHasta			DATETIME,
			@pId_Unid_Negocio       VARCHAR(10),
			@pFiltrar_con_saldo     TINYINT,
			@pClientes_activos      TINYINT,
			@pFiltroFecha           TINYINT,
			@pCriterio              VARCHAR(2),
			@pId_Cliente            INT,
			@pInc_UCP_a_Fecha		TINYINT,
			@pLimite				INT
			 
SET @pId_Unid_Negocio			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Unid_Negocio')),'')
SET @pFechaHasta				= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'FechaHasta')),GETDATE())
SET @pFiltrar_con_saldo			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Filtrar_con_saldo')),0)
SET @pClientes_activos			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Clientes_activos')),0)
SET @pFiltroFecha		    	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FiltroFecha')),0)
SET @pCriterio			        = ISNULL(CONVERT(VARCHAR(2), dbo.CF_JSON_VALUE(@pJsonRecibido,'Criterio')),'R')
SET @pId_Cliente  		    	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Cliente')),0)
SET @pInc_UCP_a_Fecha  		   	= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Inc_UCP_a_Fecha')),0)
SET @pLimite		  		   	= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Limite')),0)

 
DECLARE @pFecha DATETIME
SET @pFecha  = @pFechaHasta+1

DECLARE @Agrupar_GF TinyInt
SET @Agrupar_GF =  dbo.CF_xParam('Cli_Ref_CtaCte_Agrup')

Select Id_Cliente_Ref
    	into #Clientes from Clientes where 1=0

IF @Agrupar_GF <> 1
   BEGIN
		If @pId_Cliente <> 0
           INSERT INTO #Clientes SELECT Id_Cliente as Id_Cliente_Ref 
										from Clientes where Id_Cliente = @pId_Cliente
		  Else
		   If @pClientes_activos = 1
              INSERT INTO #Clientes SELECT Id_Cliente as Id_Cliente_Ref 
										from Clientes where Activo = 1 and Id_cliente > 1
			Else
              INSERT INTO #Clientes SELECT Id_Cliente as Id_Cliente_Ref 
										from Clientes where Activo = 1 and Id_cliente > 1
   END
  ELSE
   BEGIN
		Select Id_cliente,Id_Cliente_Ref,Razon_Social
    			into #Clientes_Temp from Clientes where 1=0

		If @pId_Cliente <> 0
			 Insert Into #Clientes_Temp select Id_cliente, case ISNULL(Id_Cliente_Ref,0) 
										WHEN 0 THEN Id_Cliente
										ELSE Id_Cliente_Ref
										END AS Id_Cliente_Ref,Razon_Social
										from Clientes where Id_Cliente = @pId_Cliente
		  Else
		   If @pClientes_activos = 1
			  Insert Into #Clientes_Temp Select Id_cliente, case ISNULL(Id_Cliente_Ref,0) 
										WHEN 0 THEN Id_Cliente
										ELSE Id_Cliente_Ref
										END AS Id_Cliente_Ref,Razon_Social
										from Clientes where Activo = 1 and Id_cliente > 1
			Else
			  Insert Into #Clientes_Temp select Id_cliente, case ISNULL(Id_Cliente_Ref,0) 
										WHEN 0 THEN Id_Cliente
										ELSE Id_Cliente_Ref
										END AS Id_Cliente_Ref,Razon_Social
										from Clientes where  Id_cliente > 1

 
			 INSERT INTO #Clientes SELECT DISTINCT(Id_Cliente_Ref) FROM #Clientes_Temp
		END




Select Id_unid_Negocio into #Unid_Negocios from Empresas_Unid_Negocios
If @pId_Unid_Negocio <> ''
   Delete #Unid_Negocios where Id_unid_Negocio <> @pId_Unid_Negocio

--paso 1 FC


SELECT K.Id_Cliente_Ref AS Id_Cliente
			,C.ID_TIPO_CBTE,C.COMPROBANTE_NRO,C.FECHA,(C.Imp_Total * T.Compromete_Factura) AS IMP_TOTAL
			,Isnull((SELECT SUM(ISNULL(A.Importe,0)) 
				 FROM cbtes_aplica a, cbtes p, Cbtes_Tipos tp 
				 WHERE p.Id_Trans = A.ID_TRANS_D  AND A.ID_TRANS = C.Id_Trans and p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte 
					   and  ( tp.Compromete_Recibos in (1,-1) OR tp.Compromete_Factura in (-1))
					   AND P.FECHA < @pFecha AND p.id_estado_cbte not in (0,3)),0) AS Imp_Aplicado 
			,CAST(0 AS DECIMAL(12,2)) AS Imp_Aplicado2
			,(C.SALDO * T.Compromete_Factura) AS SALDO,C.ID_TRANS,1 AS SIGNO
	INTO #DEUDA
	FROM CBTES C
	 JOIN CBTES_TIPOS T ON  C.Id_Tipo_Cbte = T.ID_TIPO_CBTE AND T.Compromete_Factura IN (1)
	 JOIN #Unid_Negocios U ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
	 JOIN Clientes O ON  C.Id_Cliente = O.ID_Cliente
	 , #Clientes k
	WHERE  CASE ISNULL(O.Id_Cliente_Ref,0) 
								WHEN 0 THEN O.Id_Cliente
								ELSE O.Id_Cliente_Ref
								END = K.Id_Cliente_Ref
		AND C.Id_Estado_Cbte NOT IN (0,3)
		AND C.Id_Cond_Pago <> 1
		AND C.Id_Cliente > 1
		AND C.FECHA < @pFecha
		AND ( NOT EXISTS  (SELECT A.ID_TRANS FROM CBTES_APLICA A WHERE C.ID_TRANS = A.ID_TRANS) OR C.SALDO <> 0
		OR (SELECT MAX(p.fecha)
					 FROM cbtes_aplica a
					 JOIN cbtes p ON p.Id_Trans = A.ID_TRANS_D AND p.id_estado_cbte not in (0,3)
					 JOIN Cbtes_Tipos tp ON p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte and (tp.Compromete_Recibos in (1,-1) 
						OR ( tp.Compromete_Factura in (-1)   AND P.Id_Cond_Pago <> 1)
						)
					 WHERE  A.ID_TRANS = C.Id_Trans ) >= @pFecha )

-- paso 2 NC

UNION ALL

SELECT K.Id_Cliente_Ref AS Id_Cliente
			,C.ID_TIPO_CBTE,C.COMPROBANTE_NRO,C.FECHA,(C.IMP_TOTAL* T.Compromete_Factura) AS IMP_TOTAL
			,(SELECT isnull(SUM(A.Importe),0)
					 FROM cbtes_aplica a
					 JOIN cbtes p ON p.Id_Trans = A.ID_TRANS AND P.Id_Cond_Pago <> 1 AND P.FECHA < @pFecha AND p.id_estado_cbte not in (0,3)
					 JOIN Cbtes_Tipos tp ON p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte   and  ( tp.Compromete_Recibos in (1,-1) OR tp.Compromete_Factura in (1))
					 WHERE A.ID_TRANS_D = C.Id_Trans ) AS Imp_Aplicado 
			,CAST(0 AS DECIMAL(12,2)) AS Imp_Aplicado2
			,(C.SALDO* T.Compromete_Factura) AS SALDO,C.ID_TRANS,-1 AS SIGNO
	FROM CBTES C
	   JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.ID_TIPO_CBTE AND T.Compromete_Factura IN (-1)
	   JOIN #Unid_Negocios U ON U.Id_Unid_Negocio = T.Id_Unid_Negocio
	   JOIN Clientes O ON C.Id_Cliente = O.ID_Cliente
	   ,#Clientes K 
	WHERE CASE ISNULL(O.Id_Cliente_Ref,0) 
								WHEN 0 THEN O.Id_Cliente
								ELSE O.Id_Cliente_Ref
								END = K.Id_Cliente_Ref
		AND C.Id_Cond_Pago <> 1
		AND C.Id_Estado_Cbte NOT IN (0,3)
		AND C.Id_Cliente > 1
		AND C.FECHA < @pFecha
		AND ( NOT EXISTS  (SELECT A.ID_TRANS FROM CBTES_APLICA A WHERE C.ID_TRANS = A.ID_TRANS)
		OR 	(SELECT MAX(p.fecha)
					 FROM cbtes_aplica a
					 JOIN cbtes p ON p.Id_Trans = A.ID_TRANS_D AND p.id_estado_cbte not in (0,3)
					 JOIN Cbtes_Tipos tp ON p.Id_Tipo_Cbte = tp.Id_Tipo_Cbte and (tp.Compromete_Recibos in (1,-1) 
						OR ( tp.Compromete_Factura in (-1)   AND P.Id_Cond_Pago <> 1)
						)
					 WHERE  A.ID_TRANS = C.Id_Trans ) >= @pFecha )
		
		
--paso 3 OP

UNION ALL

SELECT  K.Id_Cliente_Ref AS Id_Cliente
		,C.ID_TIPO_CBTE,C.COMPROBANTE_NRO,C.FECHA,(C.IMP_TOTAL* -1) as IMP_TOTAL
		,(SELECT ISNULL(SUM(A.IMPORTE),0) FROM CBTES_APLICA A, CBTES K1 WHERE C.ID_TRANS = A.ID_TRANS_D AND K1.FECHA < @pFecha
			  AND A.ID_TRANS = K1.ID_TRANS AND K1.ID_ESTADO_CBTE NOT IN (0,3)  and a.id_trans <> 0
			  AND ISNULL((SELECT COUNT(*) FROM CBTES_APLICA CA WHERE C.ID_TRANS = CA.ID_TRANS_D),0) > = 1 
			  )  as Imp_Aplicado
		,(SELECT ISNULL(SUM(A.IMPORTE),0) FROM CBTES_APLICA A, CBTES K WHERE C.ID_TRANS = A.ID_TRANS AND K.FECHA < @pFecha
			  AND A.ID_TRANS_D = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3) )  as Imp_Aplicado2,
			  C.SALDO,C.ID_TRANS,-1 AS SIGNO
	FROM CBTES C
	 JOIN CBTES_TIPOS T ON C.Id_Tipo_Cbte = T.ID_TIPO_CBTE AND T.Compromete_Recibos IN (1,-1)
	 JOIN #Unid_Negocios U ON  U.Id_Unid_Negocio = T.Id_Unid_Negocio
	 JOIN Clientes O ON C.Id_Cliente = O.ID_Cliente
	, #Clientes K  
	WHERE  CASE ISNULL(O.Id_Cliente_Ref,0) 
								WHEN 0 THEN O.Id_Cliente
								ELSE O.Id_Cliente_Ref
								END = K.Id_Cliente_Ref
		AND C.Id_Estado_Cbte NOT IN (0,3)
		AND C.Id_Cliente > 1
		AND C.FECHA < @pFecha
		AND (((SELECT ISNULL(MAX(A.ID_TRANS),0) FROM CBTES_APLICA A , CBTES K WHERE C.ID_TRANS = A.Id_Trans_D
			 AND A.ID_TRANS = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3)
			 AND K.FECHA < @pFecha
			 ) = 0)
		   OR (SELECT ISNULL(SUM(A.IMPORTE),0) FROM CBTES_APLICA A, CBTES K WHERE C.ID_TRANS = A.Id_Trans_D
			  AND A.ID_TRANS = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3)	AND A.ID_TRANS <> 0
			  AND K.FECHA < @pFecha
			  ) <> ABS(C.IMP_TOTAL) )
		AND (SELECT ISNULL(ABS(SUM(A.IMPORTE)),0)  FROM CBTES_APLICA A, CBTES K WHERE C.Id_Trans = A.Id_Trans
			  AND A.ID_TRANS_D = K.ID_TRANS AND K.ID_ESTADO_CBTE NOT IN (0,3)
			  AND K.FECHA < @pFecha
			  ) <> ABS(C.IMP_TOTAL) 


UPDATE #DEUDA SET Imp_Aplicado = abs(IMP_TOTAL), Saldo = 0  FROM #DEUDA WHERE  ABS(Imp_Aplicado) > abs(IMP_TOTAL)

/*Se agrega para determinar de quien es la UCP a Fecha 10/10/2024*/
CREATE TABLE #UCP (Id_Cliente INT, UCP_A_Fecha DATE)

		
IF @pInc_UCP_a_Fecha = 1
BEGIN
	DECLARE @Fam_CuotasSoc INT
	SET @Fam_CuotasSoc = CONVERT(INT,dbo.CF_xParam('Fam_CuotasSoc'))

	INSERT INTO #UCP
	SELECT I.Id_Cliente,CONVERT(DATE,MAX(I.Fecha_qa) ) AS UCP_A_Fecha
		FROM Cbtes_Items I
		    JOIN  Productos P ON P.Id_Producto = I.Id_Producto AND P.Id_Familia = @Fam_CuotasSoc
			JOIN  Cbtes C ON C.Id_Trans = I.Id_Trans AND C.Id_Estado_Cbte IN (1,2,4)
				LEFT JOIN Cbtes_Aplica A ON A.Id_Trans = C.Id_Trans
					LEFT JOIN Cbtes R ON R.Id_Trans = A.Id_Trans_D AND ( R.Id_Estado_Cbte IN (1,2,4) )
					LEFT JOIN Cbtes_Tipos TR ON TR.Id_Tipo_Cbte = R.Id_Tipo_Cbte AND ( TR.Compromete_Recibos  = 1 OR TR.Compromete_Factura = -1)
			JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte AND T.Compromete_Factura = 1
			, #DEUDA D
		WHERE I.Id_Cliente = D.Id_Cliente
		AND C.Fecha < @pFechaHasta + 1
		AND R.Fecha < @pFechaHasta + 1
		GROUP BY I.Id_Cliente

END

--SELECT * FROM #DEUDA
--SELECT * FROM #UCP
IF @pCriterio = 'D'
BEGIN	
	IF (@pLimite > 0)
	BEGIN
		SELECT TOP (@pLimite) D.Id_Cliente,K.Razon_Social,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,CONVERT(DATE,K.Fecha_Alta) as Fecha_Alta,CONVERT(DATE,K.Fecha_Baja) as Fecha_Baja,CONVERT(DATE,D.Fecha) as Fecha,CONVERT(DATE,C.Fecha_Venc)as Fecha_Venc,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion,c.Id_Moneda AS Moneda, ISNULL(D.imp_total,0) - ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2) ,0) * D.Signo  AS IMP_TOTAL,D.Id_Trans 
		   ,(select sum(isnull(i.imp_final,0)) from cbtes_items i where i.id_trans = d.id_trans)-abs(D.imp_total) as items
		   ,CONVERT(DATE,K.Ult_Cuota_Paga) as Ult_Cuota_Paga
		   ,ISNULL(U.UCP_A_Fecha,'19000101') as UCP_A_Fecha
		   FROM #DEUDA D 
				LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente
				JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente 
				JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
				, CBTES C 
		   WHERE C.Id_trans = D.Id_Trans AND ISNULL(D.imp_total,0)- ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2),0)*D.SIGNO  <> 0
			  ORDER BY K.Razon_Social,D.Fecha
	END
	ELSE
	BEGIN
		SELECT D.Id_Cliente,K.Razon_Social,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,CONVERT(DATE,K.Fecha_Alta) as Fecha_Alta,CONVERT(DATE,K.Fecha_Baja) as Fecha_Baja,CONVERT(DATE,D.Fecha) as Fecha,CONVERT(DATE,C.Fecha_Venc) as Fecha_Venc,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion,c.Id_Moneda AS Moneda, ISNULL(D.imp_total,0) - ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2) ,0) * D.Signo  AS IMP_TOTAL,D.Id_Trans 
		   ,(select sum(isnull(i.imp_final,0)) from cbtes_items i where i.id_trans = d.id_trans)-abs(D.imp_total) as items
		   ,CONVERT(DATE,K.Ult_Cuota_Paga) as Ult_Cuota_Paga
		   ,ISNULL(U.UCP_A_Fecha,'19000101') as UCP_A_Fecha
		   FROM #DEUDA D 
				LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente
				JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente 
				JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
				, CBTES C 
		   WHERE C.Id_trans = D.Id_Trans AND ISNULL(D.imp_total,0)- ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2),0)*D.SIGNO  <> 0
			  ORDER BY K.Razon_Social,D.Fecha
	END
END 
 
IF @pCriterio = 'T'
BEGIN    
    IF @pFiltrar_con_saldo = 1
	BEGIN
		SELECT D.Id_Cliente,K.Razon_Social,SUM(ISNULL(Imp_total,0) - ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2),0) * Signo) as Saldo 
			,CONVERT(DATE,K.Ult_Cuota_Paga) as Ult_Cuota_Paga
			,U.UCP_A_Fecha,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,K.Fecha_Alta,K.Fecha_Baja
		   FROM #DEUDA D 
			LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente		
			JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente
			JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli
		   GROUP BY D.Id_Cliente,Razon_Social,K.Ult_Cuota_Paga,U.UCP_A_Fecha ,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion,K.Telefono,K.Fecha_Alta,K.Fecha_Baja
		   HAVING SUM(ISNULL(Imp_total,0) - ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2),0) * Signo) <> 0
			ORDER BY Razon_Social 
	  END
      ELSE
	  BEGIN	
		SELECT D.Id_Cliente,K.Razon_Social,SUM((ISNULL(imp_total,0)) - Abs(ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2),0))*SIGNO) as Saldo 
			,CONVERT(DATE,K.Ult_Cuota_Paga) as Ult_Cuota_Paga
			,U.UCP_A_Fecha,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion as Descripcion_Tipo,K.Telefono,K.Fecha_Alta,K.Fecha_Baja
				   FROM #DEUDA D 
						LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente			
						JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente
						JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli 
		   GROUP BY D.Id_Cliente,K.Razon_Social ,K.Ult_Cuota_Paga,U.UCP_A_Fecha ,K.Id_Cliente_Externo,K.Id_Tipo_Cli,TC.Descripcion,K.Telefono,K.Fecha_Alta,K.Fecha_Baja
		ORDER BY Razon_Social 
	  END	
END
	  
IF @pCriterio = 'P' OR @pCriterio = 'TP'
BEGIN
		SELECT	D.Id_Cliente
				,K.Razon_Social
				,K.Id_Cliente_Externo
				,CONVERT(DATE,D.Fecha) AS Fecha
				,CONVERT(DATE,C.Fecha_Venc) AS Fecha_Venc
				,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion
				,c.Id_Moneda AS Moneda
				,I.Id_Trans
				,I.Id_Producto
				,I.Descripcion_Producto
				,I.IMP_FINAL*D.SIGNO AS Imp_Prod
				,ISNULL(D.imp_totaL,0)* D.Signo AS Imp_Fac 
				,ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2) ,0) * D.Signo  AS Imp_Apli
				,ABS((ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO )/D.imp_total) AS Coef
				,(I.IMP_FINAL*D.SIGNO) * (ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO )/D.imp_total AS Saldo,I.Id_Cliente AS Id_Cliente_Item ,H.Razon_Social AS Razon_Social_Item
				,K.Id_Tipo_Cli
				,TC.Descripcion as Categoria
				,CONVERT(DATE,K.Ult_Cuota_Paga) as Ult_Cuota_Paga
		INTO #DET
		FROM #DEUDA D JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente
					  JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli	
			, CBTES C JOIN  CBTES_ITEMS I ON C.ID_TRANS = I.ID_TRANS
					  LEFT JOIN Clientes H ON I.Id_Cliente = H.Id_Cliente
				      JOIN Cbtes_Tipos T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
		WHERE   D.ID_TRANS = C.ID_TRANS 
				AND ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)* D.SIGNO  <> 0 
				AND T.Compromete_Factura IN (1,-1)
				AND D.imp_total <> 0

	ALTER TABLE #DET ALTER COLUMN Saldo DECIMAL(12,2)

		INSERT INTO #DET
			SELECT D.Id_Cliente,K.Razon_Social
				 ,K.Id_Cliente_Externo
				 ,CONVERT(DATE,D.Fecha) AS Fecha
				 ,CONVERT(DATE,C.Fecha_Venc) AS Fecha_Venc
				 ,DBO.CF_Cbte_Descrip(D.ID_TRANS) AS Descripcion
				 ,c.Id_Moneda AS Moneda
				 ,C.Id_Trans
				 , 'ACUENTA' AS ID_PRODUCTO
				 ,'PAGOS A CUENTA' AS Descripcion_Producto
				 , 0 AS IMP_PROD
				 , ISNULL(D.imp_totaL,0)* D.Signo AS IMP_FAC 
				 , ISNULL(Imp_Aplicado+ABS(Imp_Aplicado2) ,0) * D.Signo  AS IMP_APLI
				 , ABS((ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO )/D.imp_total) AS COEF
				 ,0 AS SALDO 
				 ,0 AS Id_Cliente_Item 
				 ,'' AS Razon_Social_Item
				 ,K.Id_Tipo_Cli
				 ,TC.Descripcion as Categoria
				 ,CONVERT(DATE,K.Ult_Cuota_Paga) as Ult_Cuota_Paga
				 FROM #DEUDA D JOIN  Clientes K ON K.Id_Cliente = D.Id_Cliente
							   JOIN  Clientes_Tipos TC ON TC.Id_Tipo_Cli = K.Id_Tipo_Cli	
					, CBTES C JOIN Cbtes_Tipos T ON C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
			   WHERE   D.ID_TRANS = C.ID_TRANS AND ISNULL(D.imp_total,0)- ISNULL(D.Imp_Aplicado+ABS(D.Imp_Aplicado2),0)*D.SIGNO  <> 0 
			   AND T.Compromete_Recibos IN (1,-1)
			   AND D.imp_total <> 0

		UPDATE  #DET SET IMP_PROD = (IMP_FAC*COEF)*-1, SALDO  = (IMP_FAC*COEF)*-1 
				 WHERE IMP_PROD = 0    AND IMP_FAC >= ABS(IMP_APLI)  AND ID_PRODUCTO ='ACUENTA'

		UPDATE  #DET SET IMP_PROD = (IMP_FAC*COEF), SALDO  = (IMP_FAC*COEF) 
				 WHERE IMP_PROD = 0  AND IMP_FAC < ABS(IMP_APLI)  AND ID_PRODUCTO ='ACUENTA'
		
		--SELECT * FROM #DET
		
		INSERT INTO #UCP
		SELECT I.Id_Cliente,CONVERT(DATE,MAX(I.Fecha_qa) ) AS UCP_A_Fecha
		FROM Cbtes_Items I
		    JOIN  Productos P ON P.Id_Producto = I.Id_Producto AND P.Id_Familia = @Fam_CuotasSoc
			JOIN  Cbtes C ON C.Id_Trans = I.Id_Trans AND C.Id_Estado_Cbte IN (1,2,4)
				LEFT JOIN Cbtes_Aplica A ON A.Id_Trans = C.Id_Trans
					LEFT JOIN Cbtes R ON R.Id_Trans = A.Id_Trans_D AND ( R.Id_Estado_Cbte IN (1,2,4) )
					LEFT JOIN Cbtes_Tipos TR ON TR.Id_Tipo_Cbte = R.Id_Tipo_Cbte AND ( TR.Compromete_Recibos  = 1 OR TR.Compromete_Factura = -1)
			JOIN Cbtes_Tipos T ON T.Id_Tipo_Cbte = C.Id_Tipo_Cbte AND T.Compromete_Factura = 1
			, #DET D
					LEFT JOIN Clientes CL ON CL.Id_Cliente=D.Id_Cliente_Item AND CL.Activo=1 AND CL.Id_Cliente_Ref <> 0
		WHERE I.Id_Cliente = D.Id_Cliente_Item
		AND C.Fecha < @pFechaHasta + 1
		AND R.Fecha < @pFechaHasta + 1
		GROUP BY I.Id_Cliente
		
       	--select * From #UCP	
	
		
		IF @pCriterio = 'P'
		  --   SELECT D.*, U.UCP_A_Fecha
				--FROM #DET D 
				--			LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente 			
				--ORDER BY Razon_Social ,Razon_Social_Item,Descripcion_Producto ,Fecha

				SELECT 
				DISTINCT D.Id_Cliente,	
				D.Razon_Social,
				D.Id_Cliente_Externo,
				D.Fecha,
				D.Fecha_Venc,
				D.Descripcion,
				D.Moneda,
				D.Id_Trans,
				D.Id_Producto,
				D.Descripcion_Producto,
				D.Imp_Prod,
				D.Imp_Fac,
				D.Imp_Apli,
				D.Coef,
				D.Saldo,
				D.Id_Cliente_Item,
				D.Razon_Social_Item,
				D.Id_Tipo_Cli,
				D.Categoria,
				D.Ult_Cuota_Paga,
				ISNULL(U.UCP_A_Fecha,'19000101') as UCP_A_Fecha
				INTO #REPORTE
				FROM #DET D 
							LEFT JOIN #UCP U ON U.Id_Cliente = D.Id_Cliente_Item 			
				ORDER BY Razon_Social ,Razon_Social_Item,Descripcion_Producto ,Fecha

				ALTER TABLE #REPORTE ADD UCP_A_Fecha_Item DATE

				UPDATE #REPORTE SET UCP_A_Fecha_Item = UCP_A_Fecha,UCP_A_Fecha='19000101' WHERE Id_Cliente_Item IN (SELECT Id_Cliente from Clientes where Id_Cliente_Ref<>0)
				SELECT DISTINCT D.Id_Cliente,	
				D.Razon_Social,
				D.Id_Cliente_Externo,
				D.Fecha,
				D.Fecha_Venc,
				D.Descripcion,
				D.Moneda,
				D.Id_Trans,
				D.Id_Producto,
				D.Descripcion_Producto,
				D.Imp_Prod,
				D.Imp_Fac,
				D.Imp_Apli,
				D.Coef,
				D.Saldo,
				D.Id_Cliente_Item,
				D.Razon_Social_Item,
				D.Id_Tipo_Cli,
				D.Categoria,
				D.Ult_Cuota_Paga,
				ISNULL(D.UCP_A_Fecha,'19000101') as UCP_A_Fecha,
				ISNULL(D.UCP_A_Fecha_Item,'19000101') as UCP_A_Fecha_Item
				FROM #REPORTE D ORDER BY Razon_Social ,Razon_Social_Item,Descripcion_Producto ,Fecha
		--ELSE
		--	 SELECT Id_Producto,Descripcion_Producto,Sum(Saldo) As Saldo 
		--	   	 FROM #DET
		--		 Group by Id_Producto,Descripcion_Producto 
		--		 ORDER BY Descripcion_Producto 

		 DROP TABLE #DET
		 DROP TABLE #REPORTE
	 END

DROP TABLE #UCP
DROP TABLE #DEUDA
DROP TABLE #Clientes
DROP TABLE #Unid_Negocios
 


