CREATE PROCEDURE [dbo].[z_CPJ_Clientes_Visitas_20251127] @pJsonRecibido VARCHAR(MAX)
AS
SET NOCOUNT ON

	IF EXISTS ( SELECT * 
            FROM   sysobjects 
            WHERE  id = object_id(N'dbo.CPJ_Clientes_Visitas_') 
                   and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
	BEGIN 
		EXEC CPJ_Clientes_Visitas_ @pJsonRecibido
		RETURN
	END	

	/***************************************************************************************************

	Procedimiento:      CPJ_Clientes_Visitas
	Fecha de Creacion:  2024-10-22
	Creado por:         Adriana Laverde
	Descripcion:        Stored creado para generar invitaciones al club
	Llamado por:        invitados.php (KIOSK, APP)
	Tablas afectadas:   []
	Usado en:           
	Parametro(s):       FlagUsarTrans, ModoDebug, 
	Forma de uso:       EXEC
	Notas adicionales:  Usar CPJ_Clientes_Visitas_ para validaciones particulares

	****************************************************************************************************

	SUMARIO DE CAMBIOS
	FECHA(yyyy-mm-dd)    Autor              Comentarios
	------------------- ------------------- ------------------------------------------------------------
	2025-09-26 se guarda la fecha_hasta de la invitacion en invitaciones individuales
              
	***************************************************************************************************/

/*Variables recibidas por parametro a traves del JSON*/
DECLARE	@pFlagUsarTrans			TINYINT,
		@pModoDebug				TINYINT,
		@pApellido				VARCHAR(100),
		@pNombre				VARCHAR(100),
		@pDocumento				VARCHAR(100),
		@pFecha_Invitacion		DATETIME,
		@pCantidad				INT,
        @pEmail					VARCHAR(100),
		@pObservacion			VARCHAR(2000),
		@pId_Invitante			INT,
		@pTipo					TINYINT,
		@pId_Link				INT

SET @pFlagUsarTrans				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'FlagUsarTrans')), 0)
SET @pModoDebug					= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'ModoDebug')), 0)
SET @pApellido					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Apellido')), '')
SET @pNombre					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Nombre')), '')
SET @pDocumento					= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Documento')),'')
SET @pFecha_Invitacion			= ISNULL(CONVERT(DATETIME, dbo.CF_JSON_VALUE(@pJsonRecibido,'Fecha_Invitacion')),'')
SET @pCantidad					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Cantidad')),'')
SET @pEmail						= ISNULL(CONVERT(VARCHAR(100), dbo.CF_JSON_VALUE(@pJsonRecibido,'Email')),'')
SET @pObservacion				= ISNULL(CONVERT(VARCHAR(2000), dbo.CF_JSON_VALUE(@pJsonRecibido,'Observacion')),'')
SET @pId_Invitante				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Invitante')),0)
SET @pTipo						= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Tipo')),0)
SET @pId_Link					= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJsonRecibido,'Id_Link')),0) -- Para los registros de invitados por link
/*FIN Variables recibidas por parametro a traves del JSON*/

/*Variable de Retorno del Stored*/
DECLARE @rtaErrorStored			INT
DECLARE @rtaMsjStored			VARCHAR(4000)
/*FIN Variable de Retorono del Stored*/

/*Variables Locales*/
DECLARE @Invitacion_Previa			DATETIME
DECLARE @Existe						INT = 0
DECLARE @Cant_Invitaciones			INT
DECLARE @Categoria					INT
DECLARE @Categoria_Invitado			INT
DECLARE @Cant_Visitas_En_Mes		INT
DECLARE @Primer_Dia_Mes				DATETIME
DECLARE @Primer_Dia_Prox_Mes		DATETIME
DECLARE @Fecha_Libre				DATETIME = 0 --Libre de validaciones 
DECLARE	@URL						VARCHAR(2000)
DECLARE @Token						VARCHAR(250)
DECLARE @Id_Pais					CHAR(3) -- 14/08/2025 Maca Se agrega por las particularidades de los clientes 200, ARG
/*FINVariables Locales*/

BEGIN TRY
	IF (@pFlagUsarTrans <> 0)
	BEGIN
		BEGIN TRAN
	END

	IF (@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Clientes_Visitas'
		PRINT 'Parametros: '+ @pJsonRecibido  
		PRINT ' ---------------------- '
	END

	IF(@pId_Link > 0)
	BEGIN
		SET @pId_Invitante = ISNULL((SELECT Id_Cliente FROM Clientes_Links WHERE Id_Link = @pId_Link),0)
		SET @pFecha_Invitacion = ISNULL((SELECT Fecha_Desde FROM Clientes_Links WHERE Id_Link = @pId_Link),'')
	END
	ELSE
	BEGIN
	 SET @pId_Link = NULL
	END

	IF(@pTipo = 1)
	BEGIN
		-----------------------------------------------------------------------------------------------
		SET	@Existe				= ISNULL((SELECT MAX(Id_Cliente) FROM Clientes WHERE Doc_Nro = CAST(@pDocumento AS BIGINT) AND Activo = 1),0)
		SET	@Categoria			= ISNULL((SELECT TOP 1 Id_Tipo_Cli FROM Clientes WHERE Id_Cliente = @Existe AND Activo = 1),0)

		SET @Categoria_Invitado = dbo.CF_xParam('Categ_Invitados')
		----------------------------------------------------

		SET @Primer_Dia_Mes = (dbo.CF_FOMONTH(@pFecha_Invitacion))
		SET @Primer_Dia_Prox_Mes = DATEADD(MONTH, 1, @Primer_Dia_Mes) 
		SET @Cant_Visitas_En_Mes = ISNULL((SELECT COUNT(*) 
												FROM CD_ES
												WHERE
												Id_Cliente = @Existe
												AND Fecha >= @Primer_Dia_Mes
												AND Fecha < @Primer_Dia_Prox_Mes)
											,0)
		----------------------------------------------------

		SET @Invitacion_Previa = (SELECT ISNULL((SELECT MAX(Fecha)
			FROM Clientes_Invitados_Mov 
			WHERE Id_Cliente_D = @Existe	
			AND FECHA >= DATEADD(yy, DATEDIFF(yy, 0, GETDATE()), 0)
			AND FECHA <=  DATEADD(yy, DATEDIFF(yy, 0, GETDATE()) + 1, -1)),'19000101'))
		----------------------------------------------------

		SELECT @Cant_Invitaciones = COUNT(*)
			FROM Clientes_Invitados_Mov 
			WHERE Id_Cliente_D = @Existe 
			AND FECHA >= DATEADD(yy, DATEDIFF(yy, 0, GETDATE()), 0)
			AND FECHA <=  DATEADD(yy, DATEDIFF(yy, 0, GETDATE()) + 1, -1)
		----------------------------------------------------
	END

	IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES 
			   WHERE TABLE_NAME = 'zInvit_Fechas_Libres' 
			   AND TABLE_SCHEMA = 'dbo')
	BEGIN
		SET @Fecha_Libre = (SELECT ISNULL((SELECT 1
										   FROM zInvit_Fechas_Libres 
										   WHERE Fecha_Desde <= @pFecha_Invitacion
										   AND Fecha_Hasta >= @pFecha_Invitacion), 0))
	END

	----------------------------------------------------

	IF (ISNULL(@Existe,0 ) <> 0)
	BEGIN
	
		IF(@Categoria NOT IN (@Categoria_Invitado))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n a un Socio.' AS ErrorMessage
			RETURN 9999
			END

		IF(@Fecha_Libre = 0) --(0: VALIDA ; 1: NO VALIDA (LIBRE))
		BEGIN

			IF(@Cant_Invitaciones >= dbo.CF_xParam('Invit_Max_Anuales'))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n. La persona posee el m├íximo de invitaciones en el a├▒o.' AS ErrorMessage
			RETURN 9999
			END

			IF(@pFecha_Invitacion < @Invitacion_Previa)
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n. La persona posee una invitaci├│n' AS ErrorMessage
			RETURN 9999
			END

			IF(@Cant_Visitas_En_Mes >= 1  OR (MONTH(@Invitacion_Previa) = MONTH(@pFecha_Invitacion)) AND CONVERT(DATE, @Invitacion_Previa) <> '1900-01-01')
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n. La persona ya fue invitada este mes.' AS ErrorMessage
			RETURN 9999
			END

			IF(@Invitacion_Previa <= @pFecha_Invitacion AND GETDATE() < @Invitacion_Previa AND CONVERT(DATE, @Invitacion_Previa) <> '1900-01-01')
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n. La persona posee una invitaci├│n previa' AS ErrorMessage
			RETURN 9999
			END

			IF(@pFecha_Invitacion < CONVERT(VARCHAR(8),GETDATE(),112))
			BEGIN
				SELECT  5001 AS ErrorNumber
					,1 AS ErrorSeverity
					,1 AS ErrorState
					,1 AS ErrorProcedure
					,1 AS ErrorLine
					,'No es posible realizar la invitaci├│n.' AS ErrorMessage
			RETURN 9999
			END
		END

		IF (@pTipo = 1 /*INVITACION INDIVIDUAL*/)
		BEGIN
			INSERT INTO Clientes_Invitados_Mov (Id_Cliente,	Id_Cliente_D,	Fecha_Mov, Fecha, Id_Link)
			VALUES   (@pId_Invitante, @Existe, GETDATE(), @pFecha_Invitacion, @pId_Link)
		END

		IF (@pTipo = 2 /*GENERAR LINK (INVITACIONES MASIVAS)*/)
		BEGIN
			
			SET @Token = dbo.CF_Clientes_Links_Token('A',32)
			SET @URL = '/' + CONVERT(VARCHAR(20), 'invitados_link.php') + '/' + 'invitados_link.php?id=' + CONVERT(VARCHAR(250), @Token)


			INSERT INTO Clientes_Links (Url, Id_Cliente ,Fecha_Gen, Fecha_Ult_Uso, Cant_Usos_Permitidos,
										Cant_Usos_Realizados, Mail, Token, Nota, Fecha_Desde, Fecha_Hasta)
			VALUES					   (@URL, @pId_Invitante, GETDATE(), GETDATE(), @pCantidad, 
										0, '', @Token, @pObservacion, @pFecha_Invitacion, @pFecha_Invitacion)

			IF(@pId_Link <> 0)
			BEGIN
				UPDATE Clientes_Links SET Cant_Usos_Realizados = Cant_Usos_Realizados + 1 WHERE Id_Link = @pId_Link
			END
		END
	END
	ELSE
	BEGIN
			
		IF (@pTipo = 1 /*INVITACION INDIVIDUAL*/)
		BEGIN
				SET @Existe  = (SELECT MAX(Id_Cliente) FROM Clientes ) + 1
				SET @Id_Pais = dbo.CF_xParam('Web_Id_Pais')

				INSERT INTO Clientes (Razon_Social,	  Apellido,			Nombre,			Id_Tipo_Doc,	Doc_Nro,
										Email,			  Email_Cob,		Email_Web,		Activo,			Id_Iva,
										Id_Tipo_Cli,	  Fecha_Alta,		Tipo_Persona,	Id_Cliente,		ID_NACIONALIDAD,
										ID_LISTA_PRECIO, Id_Cliente_Ref,	Observacion)

				VALUES (LTRIM(RTRIM(UPPER(@pApellido))) +' '+ LTRIM(RTRIM(UPPER(@pNombre))),UPPER(@pApellido),UPPER(@pNombre),'',@pDocumento,
						@pEmail,			@pEmail,			@pEmail,			1,				'CF',
						@Categoria_Invitado,				GETDATE(),			'F',			@Existe,		'ARG',
						0,					0,				@pObservacion )


				INSERT INTO Clientes_Invitados_Mov (Id_Cliente,	Id_Cliente_D,	Fecha_Mov, Fecha, Fecha_Hasta, Id_Link)
				VALUES   (@pId_Invitante, @Existe, GETDATE(), @pFecha_Invitacion, @pFecha_Invitacion,  @pId_Link)

				IF(@pId_Link <> 0)
				BEGIN
					UPDATE Clientes_Links SET Cant_Usos_Realizados = Cant_Usos_Realizados + 1 WHERE Id_Link = @pId_Link
				END

				
			SELECT  0 AS ErrorNumber
					,0 AS ErrorSeverity
					,0 AS ErrorState
					,0 AS ErrorProcedure
					,0 AS ErrorLine
					,CAST(@Existe AS VARCHAR(4000)) AS ErrorMessage
			
		END

		IF (@pTipo = 2 /*GENERAR LINK (INVITACIONES MASIVAS)*/)
		BEGIN

			SET @Token = dbo.CF_Clientes_Links_Token('A',32)
			SET @URL = '/' + CONVERT(VARCHAR(25),'invitados_link.php?id=') + CONVERT(VARCHAR(250),@Token)

			INSERT INTO Clientes_Links (Url, Id_Cliente ,Fecha_Gen, Fecha_Ult_Uso, Cant_Usos_Permitidos,
										Cant_Usos_Realizados, Mail, Token, Nota, Fecha_Desde, Fecha_Hasta)
			VALUES					   (@URL, @pId_Invitante, GETDATE(), GETDATE(), @pCantidad, 
										0, '', @Token, @pObservacion, @pFecha_Invitacion, @pFecha_Invitacion)

			
			SELECT  0 AS ErrorNumber
					,0 AS ErrorSeverity
					,0 AS ErrorState
					,0 AS ErrorProcedure
					,0 AS ErrorLine
					,CAST(@URL AS VARCHAR(4000)) AS ErrorMessage
		END

	END

	/*====================================================================================================================================================*/

	IF @pFlagUsarTrans <> 0 COMMIT
	
	/*====================================================================================================================================================*/

	IF (@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Clientes_Visitas'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  ROLLBACK

	RETURN 9999
END CATCH

RETURN 0
GO



CREATE PROCEDURE [dbo].[z_CPJ_Produc_Cont_Generar_20260313]		@pJson VARCHAR(8000)
AS 
SET NOCOUNT ON 

/*Variables recibidas por par├ƒmetro a traves del JSON*/
DECLARE @pFlagUsarTrans			TINYINT
DECLARE @pModoDebug				TINYINT
DECLARE @pId_Usuario			INT
DECLARE @pId_Contrato			INT
DECLARE @pId_Trans				INT
DECLARE @pTipo					CHAR(3)
DECLARE @pValor					VARCHAR(8000)
DECLARE @pTar_Nro				VARCHAR(50)
DECLARE @pId_Tarjeta			VARCHAR(10)
DECLARE @pObservacion			VARCHAR(200)									

SET @pFlagUsarTrans			= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'FlagUsarTrans')), 0)
SET @pModoDebug				= ISNULL(CONVERT(TINYINT, dbo.CF_JSON_VALUE(@pJson,'ModoDebug')), 0)
SET @pId_Usuario			= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Usuario')), 0)
SET @pId_Trans				= ISNULL(CONVERT(INT, dbo.CF_JSON_VALUE(@pJson,'Id_Trans')), 0)
SET @pTipo					= ISNULL(CONVERT(CHAR(3), dbo.CF_JSON_VALUE(@pJson,'Tipo')), '')
SET @pValor					= ISNULL(CONVERT(VARCHAR(8000), dbo.CF_JSON_VALUE(@pJson,'Valor')), '')
SET @pTar_Nro				= ISNULL(CONVERT(VARCHAR(50), dbo.CF_JSON_VALUE(@pJson,'Tar_Nro')), '')
SET @pId_Tarjeta			= ISNULL(CONVERT(VARCHAR(10), dbo.CF_JSON_VALUE(@pJson,'Id_Tarjeta')), '')
SET @pObservacion			= ISNULL(CONVERT(VARCHAR(200), dbo.CF_JSON_VALUE(@pJson,'Observacion')), '')																								


--'' SOLO PRODUCTO   'PSH' - Producto sala horario 'PH'- Producto Horario
/*FIN Variables recibidas por par├ƒmetro a traves del JSON*/

/*Variables Locales*/
DECLARE @Id_Producto VARCHAR(14),
		@Fecha_QA DATETIME,
		@Fecha_Venc DATETIME,
		@Id_Cliente INT,
		@Existe_Cotrato INT,
		@Id_Tipo_Con_Web_Auto INT,
		@Descripcion_CT VARCHAR(200),
		@Id_Tipo_Cbte_Ri CHAR(4),
		@Id_Tipo_Cbte CHAR(4),
		@Id_Iva CHAR(3),
		@Id_Lista_Precio SMALLINT
						   

/*FIN Variables Locales*/

/*Variable de Retorno del Stored*/
DECLARE @JSON_Parametros_Stored_Invocado	VARCHAR(8000)
DECLARE @Result_Stored_Invocado				INT
/*FIN Variable de Retorono del Stored*/

BEGIN TRY
	IF @pFlagUsarTrans <> 0 
	BEGIN
		BEGIN TRAN
	END

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Ingreso a Stored Procedure: CPJ_Produc_Cont_Generar'
		PRINT 'Par├ƒmetros: '+ @pJson  
	END
	
	/*===================================================================*/	
	
	IF @pId_Trans <> 0
	BEGIN
	--Recorro todos los productos		
	DECLARE cur_Produc_Cont_Generar CURSOR FOR 	
			SELECT ISNULL(I.Id_Cliente,C.Id_Cliente),I.Id_Producto,I.Fecha_QA,I.Fecha_Venc,P.Id_Tipo_Con_Web_Auto,CT.Descripcion,CT.Id_Tipo_Cbte_Ri,CT.Id_Tipo_Cbte,E.Id_Iva,PF.Id_Lista_Precio_Web
		FROM Cbtes_Items I, Cbtes C, Cbtes_Tipos T , Productos P ,Contratos_Tipos CT, Clientes E, Prod_Familias PF
		WHERE I.Id_trans = C.Id_Trans 
		AND C.Id_Trans = @pId_Trans 
		AND C.Id_Tipo_Cbte = T.Id_Tipo_Cbte
		AND P.Id_Producto = I.Id_Producto
		AND P.Id_Familia=PF.Id_Familia						
		AND T.Compromete_Factura = 1
		AND C.Id_Estado_Cbte NOT IN (0,3)
		AND ISNULL(P.Id_Tipo_Con_Web_Auto,0) <> 0
		AND CT.Id_Tipo_Con = Id_Tipo_Con_Web_Auto
		AND E.Id_Cliente = ISNULL(I.Id_Cliente,C.Id_Cliente)

	OPEN cur_Produc_Cont_Generar
	FETCH NEXT FROM cur_Produc_Cont_Generar INTO @Id_Cliente,@Id_Producto,@Fecha_QA,@Fecha_Venc,@Id_Tipo_Con_Web_Auto,@Descripcion_CT,@Id_Tipo_Cbte_Ri,@Id_Tipo_Cbte,@Id_Iva,@Id_Lista_Precio
	WHILE @@FETCH_STATUS = 0
	BEGIN
	    SET @Existe_Cotrato = 0
		IF(@pModoDebug = 1)
		BEGIN
			PRINT '@Id_Producto: ' + CONVERT(VARCHAR(14), @Id_Producto) + ' @Id_Cliente: ' + CONVERT(VARCHAR(14), @Id_Cliente) +
			      '@Fecha_QA: ' + CONVERT(VARCHAR(14), @Fecha_QA,112) + '@Fecha_Venc: ' + CONVERT(VARCHAR(14), @Fecha_Venc,112) 
		END

		

		-----Verifico si existe el contrato --------------------------------------------------------------
		SET @Fecha_QA = ISNULL(@Fecha_QA,GETDATE())		
		SET @Fecha_Venc = ISNULL(@Fecha_Venc,GETDATE())
		
		IF @Fecha_Venc IS NULL
			SELECT TOP 1 @Existe_Cotrato = C.Id_Contrato FROM Contratos C , Contratos_Prod P
				WHERE C.Id_Contrato=P.Id_Contrato
					AND C.Id_Cliente = @Id_Cliente
					AND C.Activo = 1
					AND C.Id_Tipo_Con=30
					AND C.Fecha_Desde <= @Fecha_QA
					AND C.Fecha_Hasta IS NULL
					AND P.Id_Producto=@Id_Producto
        ELSE 
			SELECT TOP 1 @Existe_Cotrato = C.Id_Contrato FROM Contratos C , Contratos_Prod P
				WHERE C.Id_Contrato=P.Id_Contrato
					AND C.Id_Cliente = @Id_Cliente
					AND C.Activo = 1
					AND C.Id_Tipo_Con=30
					AND C.Fecha_Desde <= @Fecha_QA
					AND C.Fecha_Hasta >= @Fecha_Venc
					AND P.Id_Producto=@Id_Producto
        ---------------------------------------------------------------------------------------------------------

		IF ISNULL(@Existe_Cotrato,0) = 0	 						
		BEGIN
		   -------verifico la condici├│n del iva para ver que tipo de cbte tiene que tomar --------------------------
		   IF dbo.CF_xParam('Iva_RI') = @Id_Tipo_Cbte_RI
			  SET @Id_Tipo_Cbte = @Id_Tipo_Cbte_RI
		   ---------------------------------------------------------------------------------------------------------


		   SELECT @Existe_Cotrato = MAX(C.Id_Contrato) FROM Contratos C
		   SET @Existe_Cotrato = ISNULL(@Existe_Cotrato,0) + 1
		   
		   INSERT INTO Contratos 
			   (Id_Contrato,		Id_Cliente,	Id_Tipo_Con,			Fecha_Alta,	Fecha_Desde, Fecha_Hasta,	Activo,	Id_Tipo_Cbte,	Descripcion,
			   Porc_Bonif,	Id_Lista_Precio,Id_Sucursal,Imp_Bonif,	Id_Grupo_Cont,	Id_SubGrupo_Cont, Observacion, Id_Tarjeta, Tar_Nro)
			   VALUES
			   (@Existe_Cotrato,	@Id_Cliente,@Id_Tipo_Con_Web_Auto,	GETDATE(),	@Fecha_QA,	@Fecha_Venc,	1,		@Id_Tipo_Cbte,LTRIM(RTRIM(@Descripcion_CT)) + ' (AUTO. WEB)',		
			   0,			@Id_Lista_Precio,				0,			0,			'',				'', @pObservacion, @pId_Tarjeta, @pTar_Nro)

			   UPDATE CBTES SET Id_Contrato=@Existe_Cotrato WHERE Id_Trans=@pId_Trans

		 IF(@pTipo='PSH')
		 BEGIN

			EXEC @Result_Stored_Invocado = dbo.CP_Contratos_Prod_PSH_Agregar @Existe_Cotrato, @Id_Producto, @pValor
			IF ISNULL(@Result_Stored_Invocado,0) <> 0 
			BEGIN
				/*El CP_Contratos_Prod_PSH_Agregar deberia devolver el SELECT con el error*/
				RETURN 
			END
		 END
		 ELSE
		 BEGIN

			INSERT INTO Contratos_Prod 
			   (Id_Contrato,		Item,	Id_Producto,	Precio,	Precio_Formula,	Cant_Cuotas,	
			   Observa_Fact,	Flag_Facturable,	Cantidad,	Cant_Includ, Flag_No_Bonificable,	Id_Prod_Familia_Sala)
			   VALUES
			   (@Existe_Cotrato,	1,		@Id_Producto,	0,		'',				0,				
			   '',					1,				1,			0,			0,						0)
			END
		END

		FETCH NEXT FROM cur_Produc_Cont_Generar INTO @Id_Cliente,@Id_Producto,@Fecha_QA,@Fecha_Venc,@Id_Tipo_Con_Web_Auto,@Descripcion_CT,@Id_Tipo_Cbte_Ri,@Id_Tipo_Cbte,@Id_Iva,@Id_Lista_Precio
	END
	CLOSE cur_Produc_Cont_Generar
	DEALLOCATE cur_Produc_Cont_Generar
	--FIN Recorro todos los productos



	END --IF @pId_Trans <> 0

	/*===================================================================*/	

	IF @pFlagUsarTrans <> 0 COMMIT

	SELECT	 0							AS ErrorNumber 
			,0							AS ErrorSeverity  
			,0							AS ErrorState 
			,0							AS ErrorProcedure  
			,0							AS ErrorLine		
			,@Existe_Cotrato							AS ErrorMessage

	IF(@pModoDebug = 1)
	BEGIN
		PRINT 'Fin Stored Procedure: CPJ_Produc_Cont_Generar'
	END
	
END TRY  


BEGIN CATCH  
    EXECUTE usp_GetErrorInfo

	IF @pFlagUsarTrans <> 0  
	BEGIN
		ROLLBACK
	END

END CATCH

RETURN 0 

--Ejemplo de uso
--EXEC CPJ_Produc_Cont_Generar '{"FlagUsarTrans":"0", "ModoDebug":"1", "Id_Trans":"2"}'
GO


CREATE PROCEDURE [dbo].[z_CP_Cbtes_Ctas_Contables_Generar_Version2] 
			@pId_Trans		INT, 
			@pFlagRegenerar TINYINT
AS
SET NOCOUNT ON

/*
IF EXISTS (SELECT 1 FROM sys.objects WHERE name = '[z_CP_Cbtes_Ctas_Contables_Generar_Version2]' AND type = 'P')
BEGIN
		EXEC CP_Cbtes_Ctas_Contables_Generar_ @pId_Trans,@pFlagRegenerar
		RETURN
END
*/
DECLARE @Usar_Trans			TINYINT
--SET @Usar_Trans = ISNULL((SELECT 1 WHERE SERVERPROPERTY('ProductVersion') > '10.50.4000.0'),0)
IF @@TRANCOUNT > 0 SET @Usar_Trans = 0


/*Declaracion de Variables*/
DECLARE @Flag_Compromete_Asientos	SMALLINT
DECLARE @Flag_Compromete_Factura	SMALLINT
DECLARE @Flag_Compromete_Trans_Fondos SMALLINT
DECLARE @Flag_Compromete_Recibos	SMALLINT
DECLARE @Fecha_Cbte					DATETIME
DECLARE @Id_Cliente					INT
DECLARE @Id_Tipo_Cbte				CHAR(4)
DECLARE @Id_Cta_Contable			INT
DECLARE @Alias						INT
DECLARE @Id_Asiento					INT
DECLARE @Id_Centro_Costo			CHAR(10)
DECLARE @Id_Ejercicio_Corresp		INT
DECLARE @Id_Plan_Cta_Corresp		INT
DECLARE @Imp_Total_Cbte				DECIMAL(12,2)
DECLARE @Debe						DECIMAL(12,2)
DECLARE @Haber						DECIMAL(12,2)
DECLARE @Id_Producto				VARCHAR(14)
DECLARE @Id_Tipo_Reten				VARCHAR(10)
DECLARE @NroItem					SMALLINT
DECLARE @CMC_UltItem				SMALLINT
DECLARE @CMC_UltId_Periodo_Caja		INT
DECLARE @CMC_Id_Concepto			INT
DECLARE @VAL_UltId_Valor			INT
DECLARE @VAL_UltId_Periodo_Caja		INT
DECLARE @VAL_Id_Tipo_Val			CHAR(3)
DECLARE @Id_Cond_Pago				SMALLINT
DECLARE @VAL_Id_Periodo_Caja		INT
DECLARE @CP_Id_Caja					INT
DECLARE @ID_TARJETA                 VARCHAR(10)
DECLARE @ID_CTA_BANCO               SMALLINT
DECLARE @ID_TRANS_ORIGEN            INT
DECLARE @Mensaje					VARCHAR(100)
DECLARE @Imp_Original				DECIMAL (12,2) -- Agregado el 20220527
DECLARE @IMPORTE					DECIMAL (12,2) -- Agregado el 20220527
DECLARE @Importe_Fpago				DECIMAL (12,2) -- Agregado el 20220712
DECLARE @Total_Debe					DECIMAL (12,2) -- Agregado el 20220712 
/*FIN Declaracion de Variables*/

--PRINT 'Procedimiento: CP_Cbtes_Ctas_Contables_Generar Trans: '+ CAST(@pId_Trans AS VARCHAR(10))

IF(@pId_Trans = 0)
BEGIN
	RETURN 999
END

BEGIN TRY
	IF @Usar_Trans = 1 BEGIN TRAN

	IF(@pFlagRegenerar = 1)
	BEGIN
		DELETE FROM Cbtes_Ctas_Contables WHERE Id_Trans = @pId_Trans
	END

	/*************************************************************************************************/

	SET @Id_Tipo_Cbte				= (SELECT Id_Tipo_Cbte FROM Cbtes WHERE Id_Trans = @pId_Trans)

	SELECT  @Flag_Compromete_Asientos		= ISNULL(Compromete_Asientos, 0),
			@Flag_Compromete_Factura		= ISNULL(Compromete_Factura, 0),
			@Flag_Compromete_Trans_Fondos	= ISNULL(Compromete_Trans_Fondos, 0),
			@Flag_Compromete_Recibos		= ISNULL(Compromete_Recibos, 0)
	FROM Cbtes_Tipos
	WHERE 
	Id_Tipo_Cbte = @Id_Tipo_Cbte

	/*************************************************************************************************/

	IF(@Flag_Compromete_Asientos = 0)
	BEGIN
		IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 COMMIT
		SET @Mensaje = 'El Cbte. no Genera Asiento'

		SELECT	 0				AS ErrorNumber 
				,0				AS ErrorSeverity  
				,0				AS ErrorState 
				,0				AS ErrorProcedure  
				,0				AS ErrorLine		
				,@Mensaje		AS ErrorMessage
			
		RETURN 0
	END

	/*************************************************************************************************/

	SELECT  @Id_Cliente		= ISNULL(Id_Cliente, 0),
			@Fecha_Cbte		= ISNULL(Fecha, '19000101'),
			@Imp_Total_Cbte	= ISNULL(Imp_Total, 0)
	FROM Cbtes
	WHERE 
	Id_Trans = @pId_Trans

	/*************************************************************************************************/

	SET @Id_Ejercicio_Corresp = (SELECT Id_Ejercicio FROM Plan_Ctas_Ejercicios WHERE Fecha_Inicio <= @Fecha_Cbte AND DATEADD(dd, 1, Fecha_Cierre) > @Fecha_Cbte)
	SET @Id_Plan_Cta_Corresp = (SELECT Id_Plan_Cta FROM Plan_Ctas WHERE Id_Ejercicio = @Id_Ejercicio_Corresp)
	----PRINT 'Nro. de Ejercicio: ' + CONVERT(VARCHAR(10), @Id_Ejercicio_Corresp) + '. Nro. Plan de Cuenta: ' + CONVERT(VARCHAR(10), @Id_Plan_Cta_Corresp)

	IF(@Flag_Compromete_Factura = 1)
	BEGIN
		----PRINT 'Compromete Factura'
	
		SET @Id_Cond_Pago = (SELECT Id_Cond_Pago FROM Cbtes WHERE Id_Trans = @pId_Trans)
	
		IF(@Id_Cond_Pago NOT IN (1)) /*Si no es contado*/
		BEGIN
			----PRINT 'Cond. Pago NO ES CONTADO. @Id_Cond_Pago: ' + CONVERT(VARCHAR(10), @Id_Cond_Pago)
		
			/*Insert: Cuenta Contable: DEBE (SI la Cond. Pago NO es Contado)*/
			----PRINT 'Generacion Cuenta Contable: DEBE'
			SET @Alias = (SELECT Id_Alias_Cta_Cont_Venta FROM Clientes WHERE Id_Cliente = @Id_Cliente)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = (SELECT Id_Centro_Costo FROM Clientes WHERE Id_Cliente = @Id_Cliente)
			SET @Debe = @Imp_Total_Cbte
			SET @NroItem = 1
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			@Debe,			0/*Haber*/,			''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)
			/*FIN Insert: Cuenta Contable: DEBE (SI la Cond. Pago NO es Contado)*/
		END
		ELSE
		BEGIN
			----PRINT 'Cond. Pago ES CONTADO'
		
			/*Insert: Cuenta Contable: DEBE (SI la Cond. Pago ES Contado)*/
			----PRINT 'Generacion Cuenta Contable: DEBE'
			SET @VAL_Id_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE Id_Trans = @pId_Trans), 0)		
			SET @CP_Id_Caja = ISNULL((SELECT Id_Caja FROM Cajas_Periodos WHERE Id_Periodo_Caja = @VAL_Id_Periodo_Caja), 0)		
			SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Cajas WHERE Id_Caja = @CP_Id_Caja), 0)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Alias = @Alias AND Id_Plan_Cta = @Id_Plan_Cta_Corresp)
			SET @Id_Centro_Costo = ISNULL((SELECT Id_Cta_Contable FROM Cajas WHERE Id_Caja = @CP_Id_Caja), '')
			SET @Debe = @Imp_Total_Cbte
			SET @NroItem = 1
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
		
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			@Debe,			0/*Haber*/,			''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)
			/*FIN Insert: Cuenta Contable: DEBE (SI la Cond. Pago ES Contado)*/
		END
	
		/*Insert: Cuenta Contable: HABER*/
		----PRINT 'Generacion Cuenta Contable: HABER'
	
		--PRINT 'Generacion de Items de Productos'
		DECLARE curGenCtaCteHaber CURSOR FOR 
			SELECT DISTINCT Id_Producto FROM Cbtes_Items WHERE Id_Trans = @pId_Trans

		OPEN curGenCtaCteHaber
		FETCH NEXT FROM curGenCtaCteHaber INTO @Id_Producto
		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @Alias = (SELECT Id_Alias_Cta_Cont FROM Productos WHERE Id_Producto = @Id_Producto)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = (SELECT Id_Centro_Costo FROM Productos WHERE Id_Producto = @Id_Producto)
			SET @Haber = (SELECT SUM(Imp_Gravado) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Id_Producto = @Id_Producto)
			SET @NroItem = @NroItem + 1
		
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Producto: ' + @Id_Producto + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)

		FETCH NEXT FROM curGenCtaCteHaber INTO @Id_Producto
		END 
		CLOSE curGenCtaCteHaber;
		DEALLOCATE curGenCtaCteHaber;
		/*FIN Insert: Cuenta Contable: HABER*/
	
		----PRINT 'Generacion de Items de Percepciones'	
		DECLARE curGenCtaCteHaberPercep CURSOR FOR 
			SELECT DISTINCT Id_Tipo_Reten	FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans

		OPEN curGenCtaCteHaberPercep
		FETCH NEXT FROM curGenCtaCteHaberPercep INTO @Id_Tipo_Reten
		WHILE @@FETCH_STATUS = 0
		BEGIN

			SET @Alias = (SELECT Id_Cta_Contable FROM Cbtes_Reten_Tipos WHERE Id_Tipo_Reten = @Id_Tipo_Reten)
			SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
			SET @Id_Centro_Costo = ''
			SET @Haber = (SELECT SUM(Importe) FROM Cbtes_Reten WHERE Id_Trans = @pId_Trans AND Id_Tipo_Reten = @Id_Tipo_Reten)
			SET @NroItem = @NroItem + 1
		
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Tipo_Reten: ' + @Id_Tipo_Reten + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)

		FETCH NEXT FROM curGenCtaCteHaberPercep INTO @Id_Tipo_Reten
		END 
		CLOSE curGenCtaCteHaberPercep;
		DEALLOCATE curGenCtaCteHaberPercep;
	
		----PRINT 'Generacion de Items de Iva'
		SET @Alias = (SELECT ISNULL(Valor_Integer,0) FROM xParametros WHERE IdParametro = 'Iva_Debito_Fiscal')
		SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
		SET @Id_Centro_Costo = ''
		SET @Haber = (SELECT SUM(Imp_Iva) FROM Cbtes_Items WHERE Id_Trans = @pId_Trans AND Id_Producto IN (SELECT Id_Producto FROM Productos WHERE Id_Iva IN (SELECT Id_Iva FROM Productos_TasaIva WHERE (Porc1 <> 0 OR Porc1 IS NOT NULL))))
	
		IF(@Haber <> 0)
		BEGIN
			SET @NroItem = @NroItem + 1
		
			----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable) + '. Centro_Costo: ' + CONVERT(VARCHAR(10), @Id_Centro_Costo) 
	
			INSERT INTO Cbtes_Ctas_Contables
			(Id_Trans,		Id_Cta_Contable,	Fecha,
			Debe,			Haber,				Observacion,
			Alias,			Id_Asiento,			Id_Centro_Costo,
			Item)
			VALUES									
			(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
			0/*Debe*/,		@Haber,				''/*Observacion*/,
			@Alias,			0/*El proceso de A.R. lo carga*/,@Id_Centro_Costo,
			@NroItem)		
		END
	
		----PRINT 'FIN Compromete Factura'
	END /*IF(@Flag_Compromete_Factura = 1)*/


	IF(@Flag_Compromete_Trans_Fondos = 1)
	BEGIN
		----PRINT 'Compromete Transferencia de Fondos'
	
		/*Insert: Cuenta Contable: DEBE*/
		----PRINT 'Generacion Cuenta Contable: DEBE'
		SET @CMC_UltItem = ISNULL((SELECT MAX(Item) FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Cajas_Mov_Conceptos. Ult. Item Generado: ' + CONVERT(VARCHAR(10), @CMC_UltItem)
	
		IF(@CMC_UltItem <> 0)
		BEGIN
			SET @CMC_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans AND Item = @CMC_UltItem), 0)
		
			----PRINT 'Generacion de Items por cada concepto del Periodo de Caja: ' + CONVERT(VARCHAR(10), @CMC_UltId_Periodo_Caja)
			DECLARE curGenCtaCteDebe_CMC CURSOR FOR 
				SELECT DISTINCT Id_Concepto FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans
								AND Id_Periodo_Caja = @CMC_UltId_Periodo_Caja
		
			SET @NroItem = 0
		
			OPEN curGenCtaCteDebe_CMC
			FETCH NEXT FROM curGenCtaCteDebe_CMC INTO @CMC_Id_Concepto
			WHILE @@FETCH_STATUS = 0
			BEGIN

				SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Conceptos WHERE Id_Concepto = @CMC_Id_Concepto),0)
				SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)	
				SET @Haber = (SELECT ISNULL(SUM(Importe), 0) FROM Cajas_Mov_Conceptos WHERE Id_Trans = @pId_Trans AND Id_Concepto = @CMC_Id_Concepto AND Id_Periodo_Caja = @CMC_UltId_Periodo_Caja)
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Concepto: ' + CONVERT(VARCHAR(10), @CMC_Id_Concepto) + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				@Debe,			0/*Haber*/,			''/*Observacion*/,
				@Alias,			0/*Id_Asiento*/,	''/*Id_Centro_Costo*/,
				@NroItem)

				FETCH NEXT FROM curGenCtaCteDebe_CMC INTO @CMC_Id_Concepto
			END 
			CLOSE curGenCtaCteDebe_CMC;
			DEALLOCATE curGenCtaCteDebe_CMC;
		END /*IF(@CMC_UltItem <> 0)*/
	
		/*Insert: Cuenta Contable: HABER*/
		----PRINT 'Generacion Cuenta Contable: HABER'
		SET @VAL_UltId_Valor = ISNULL((SELECT MAX(Id_Valor) FROM Valores WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
	
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
			SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE Id_Trans = @pId_Trans AND Id_Valor = @VAL_UltId_Valor), 0)
		
			----PRINT 'Generacion de Items por cada Id_Tipo_Val del Periodo de Caja: ' + CONVERT(VARCHAR(10), @VAL_UltId_Periodo_Caja)
			DECLARE curGenCtaCteHaber_Val CURSOR FOR 
				SELECT DISTINCT Id_Tipo_Val 
				FROM Valores 
				WHERE 
				Id_Trans = @pId_Trans
				AND Id_Periodo_Caja = @VAL_UltId_Periodo_Caja
		
			OPEN curGenCtaCteHaber_Val
			FETCH NEXT FROM curGenCtaCteHaber_Val INTO @VAL_Id_Tipo_Val
			WHILE @@FETCH_STATUS = 0
			BEGIN
				SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tipos WHERE Id_Tipo_Val = @VAL_Id_Tipo_Val), 0)
				SET @Id_Cta_Contable = (SELECT Id_Cta_Contable FROM Pla_Ctas_Cuentas_Contables WHERE Id_Plan_Cta = @Id_Plan_Cta_Corresp AND Alias = @Alias)
				SET @Haber = (SELECT SUM(Importe) FROM Valores WHERE Id_Trans = @pId_Trans AND Id_Tipo_Val = @VAL_Id_Tipo_Val AND Id_Periodo_Caja = @VAL_UltId_Periodo_Caja)
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				0/*Debe*/,		@Haber,				''/*Observacion*/,
				@Alias,			0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)

				FETCH NEXT FROM curGenCtaCteHaber_Val INTO @VAL_Id_Tipo_Val
			END 
			CLOSE curGenCtaCteHaber_Val;
			DEALLOCATE curGenCtaCteHaber_Val;		
		END
	
		----PRINT 'FIN Compromete Transferencia de Fondos'
	END /*IF(@Flag_Compromete_Trans_Fondos = 1)*/

	IF(@Flag_Compromete_Recibos = 1)
	BEGIN
	    DECLARE @Tomar_Asiento_Cbte SMALLINT 
		SET @Tomar_Asiento_Cbte = (SELECT ISNULL(Valor_Integer,0) FROM xParametros WHERE IdParametro = 'Tomar_Asiento_Cbte') 

	    SET @NroItem = 1	
		----PRINT 'Compromente Recibos'
		
		----PRINT 'Generacion Cuenta Contable: DEBE'

		SET @VAL_UltId_Valor = ISNULL((SELECT MAX(Id_Valor) FROM Valores_Mov WHERE Id_Trans = @pId_Trans), 0)
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
	
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
			SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE  Id_Valor = @VAL_UltId_Valor), 0)
		
			----PRINT 'Generacion de Items por cada Id_Tipo_Val del Periodo de Caja: ' + CONVERT(VARCHAR(10), @VAL_UltId_Periodo_Caja)
			DECLARE curGenCtaDEBE_Val CURSOR FOR 
					SELECT DISTINCT V.Id_Tipo_Val,ISNULL(V.ID_TARJETA,''),ISNULL(V.ID_CTA_BANCO,0)
					FROM Valores_MOV M, VALORES V 
					WHERE 
					M.Id_Trans = @pId_Trans
					AND M.ID_VALOR = V.ID_VALOR
					AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja
		
			OPEN curGenCtaDEBE_Val
			FETCH NEXT FROM curGenCtaDEBE_Val INTO @VAL_Id_Tipo_Val,@ID_TARJETA,@ID_CTA_BANCO
			WHILE @@FETCH_STATUS = 0
			BEGIN
			    SET @Alias = 0 
			    IF @VAL_Id_Tipo_Val = 'TAR'
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tarjetas_Cred WHERE ID_TARJETA = @ID_TARJETA), 0)
                   END
			    IF @VAL_Id_Tipo_Val = 'DB'
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Cta_Contable FROM Bancos_Ctas WHERE Id_Cta_Banco = @ID_CTA_BANCO), 0)
                   END	    
				IF @Alias = 0  
				   BEGIN
				      SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont FROM Valores_Tipos WHERE Id_Tipo_Val = @VAL_Id_Tipo_Val), 0)
                   END


				SET @Id_Cta_Contable = 	  (SELECT dbo.CF_Cta_Cont(@Alias, @Fecha_Cbte))
				SET @NroItem = @NroItem + 1
			    SET @Id_Centro_Costo = ''
			    SET @Debe = (SELECT SUM(V.Importe) FROM Valores V, Valores_Mov M WHERE M.Id_Trans = @pId_Trans AND M.id_valor = V.Id_Valor And V.Id_Tipo_Val = @VAL_Id_Tipo_Val AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja AND ISNULL(V.Id_Tarjeta,'') = @ID_TARJETA AND ISNULL(V.Id_Cta_Banco,0) = @Id_Cta_Banco)
	
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				@Debe,		0,				''/*Observacion*/,
				@Alias,		0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)

				FETCH NEXT FROM curGenCtaDEBE_Val INTO @VAL_Id_Tipo_Val,@ID_TARJETA,@ID_CTA_BANCO
			END 
			CLOSE curGenCtaDEBE_Val;
			DEALLOCATE curGenCtaDEBE_Val;		
		END

		/*Insert: Cuenta Contable: HABER*/
		----PRINT 'Generacion Cuenta Contable: HABER'
		----PRINT 'Valores. Ult. Id_Valor Generado: ' + CONVERT(VARCHAR(10), @VAL_UltId_Valor)
		
		IF(@VAL_UltId_Valor <> 0)
		BEGIN
		    IF @Tomar_Asiento_Cbte = 0
			BEGIN
				SET @VAL_UltId_Periodo_Caja = ISNULL((SELECT Id_Periodo_Caja FROM Valores WHERE Id_Valor = @VAL_UltId_Valor), 0)
				
				SET @Alias = ISNULL((SELECT Id_Alias_Cta_Cont_Venta FROM Clientes WHERE Id_Cliente = @Id_Cliente), 0)
				SET @Id_Cta_Contable = (SELECT dbo.CF_Cta_Cont(@Alias, @Fecha_Cbte))
				SET @Haber = (SELECT SUM(V.Importe) FROM Valores V, Valores_Mov M WHERE M.Id_Trans = @pId_Trans AND M.id_valor = V.Id_Valor  AND M.Id_Periodo_Caja = @VAL_UltId_Periodo_Caja )
				SET @NroItem = @NroItem + 1
		
				----PRINT 'Item: ' + CONVERT(VARCHAR(10), @NroItem) + '. Id_Tipo_Val: ' + @VAL_Id_Tipo_Val + '. Alias: ' + CONVERT(VARCHAR(10), @Alias) + '. Id_Cta_Contable: ' + CONVERT(VARCHAR(10), @Id_Cta_Contable)
	
				INSERT INTO Cbtes_Ctas_Contables
				(Id_Trans,		Id_Cta_Contable,	Fecha,
				Debe,			Haber,				Observacion,
				Alias,			Id_Asiento,			Id_Centro_Costo,
				Item)
				VALUES									
				(@pId_Trans,	@Id_Cta_Contable,	@Fecha_Cbte,
				0/*Debe*/,		@Haber,				''/*Observacion*/,
				@Alias,			0/*Id_Asiento*/,	''/*@Id_Centro_Costo*/,
				@NroItem)
		    END
		   ELSE
			BEGIN
			SELECT * INTO #CTAS_AUX FROM CBTES_CTAS_CONTABLES WHERE ID_TRANS = 1
			DELETE #CTAS_AUX

			
			-- RESPONSABLE AGUSTIN BARRAZA
			-- Tabla temporal que se pasa al cursor // 2022.06.01
			CREATE TABLE #CBTES_APLICA_AUX (
			Id_Trans		BIGINT,
			Id_Trans_D		BIGINT
			)
			
			-- RESPONSABLE AGUSTIN BARRAZA
			-- Validacion para contemplar casos en los cuales NO EXISTE registro en cbtes aplica (pagos a cuenta) // 2022.06.01
			IF EXISTS(SELECT TOP 1 ID_TRANS FROM Cbtes_Aplica WHERE ID_TRANS_D = @pId_Trans)
			BEGIN
				
				INSERT INTO #CBTES_APLICA_AUX
				SELECT Id_Trans, id_Trans_D  FROM Cbtes_Aplica WHERE ID_TRANS_D = @pId_Trans
	
			END
			ELSE
			BEGIN
			
				INSERT INTO #CBTES_APLICA_AUX
				SELECT Id_Trans_D AS Id_Trans , Id_Trans_D  FROM Cbtes_Aplica WHERE id_trans = 1
				UPDATE #CBTES_APLICA_AUX SET Id_Trans_D = @pId_Trans
	
			END
			
			DECLARE curGenCtaDEBE_FAC_APLIC2 CURSOR FOR 
			
			SELECT ID_TRANS
			FROM #CBTES_APLICA_AUX WHERE ID_TRANS_D = @pId_Trans

				OPEN curGenCtaDEBE_FAC_APLIC2
				FETCH NEXT FROM curGenCtaDEBE_FAC_APLIC2 INTO @ID_TRANS_ORIGEN
				WHILE @@FETCH_STATUS = 0
				BEGIN
					
					-- RESPONSABLE AGUSTIN BARRAZA
					-- Se agrega filtro que contemple pagos a cuenta // 2022-05-27
					IF(@ID_TRANS_ORIGEN = 0)
					
					BEGIN
					
						SET @ID_TRANS_ORIGEN = @pId_Trans
						
						-- RESPONSABLE AGUSTIN BARRAZA
						-- Verificamos si hay registros en Cbtes_Aplica
						IF EXISTS(SELECT ISNULL(IMPORTE,0) FROM Cbtes_Aplica WHERE id_Trans_D = @ID_TRANS_ORIGEN)
						BEGIN
							SET @IMPORTE = (SELECT ISNULL(IMPORTE,0) FROM Cbtes_Aplica WHERE id_Trans_D = @ID_TRANS_ORIGEN)
						END
						
						ELSE
						BEGIN
							SET @IMPORTE = (SELECT ISNULL(IMPORTE,0) FROM Valores WHERE id_TRANS = @ID_TRANS_ORIGEN)
						END
						
					END
					
					ELSE
					BEGIN
						SET @IMPORTE = (SELECT ISNULL(IMPORTE,0) FROM Cbtes_Aplica WHERE id_Trans = @ID_TRANS_ORIGEN and id_trans_D = @pId_Trans)
					END
					
					-- RESPONSABLE AGUSTIN BARRAZA
					-- INTERTO EN TABLA AUXILIAR
					INSERT INTO #CTAS_AUX
					SELECT * FROM CBTES_CTAS_CONTABLES WHERE ID_TRANS = @ID_TRANS_ORIGEN	 AND DEBE <> 0
					
					 /*Agrego linea 2020.09.16*/
					SET @Imp_Original = (SELECT ISNULL(Imp_Total,0) FROM Cbtes WHERE id_Trans = @ID_TRANS_ORIGEN)
					
					-- RESPONSABLE AGUSTIN BARRAZA
					-- CALCULO EN CASO DE QUE SEA UN PAGO PARCIAL, SE AGREGA EL IF // 2022.05.27
					IF(@Imp_Original<>@IMPORTE)
					BEGIN	
							/*Agrego linea 2020.09.16*/
							UPDATE #CTAS_AUX SET DEBE = Debe * @IMPORTE / @Imp_Original WHERE ID_TRANS = @ID_TRANS_ORIGEN AND DEBE <> 0
					
					END
					-- RESPONSABLE AGUSTIN BARRAZA
					-- Modifico el alias en caso de pago a cuenta // 2022.05.27
					IF(@ID_TRANS_ORIGEN = @pId_Trans)
					BEGIN
						UPDATE #CTAS_AUX SET Alias = (SELECT Valor_Integer FROM xParametros WHERE IdParametro = 'Alias_Pago_a_Cta')  WHERE ID_TRANS = @ID_TRANS_ORIGEN AND DEBE <> 0			
					END
				
					FETCH NEXT FROM curGenCtaDEBE_FAC_APLIC2 INTO @ID_TRANS_ORIGEN
					END
				
				
				SET @Importe_Fpago = (SELECT Importe FROM Valores WHERE Id_Trans = @pId_Trans)
				SET @Total_debe = (SELECT SUM(Debe) FROM #CTAS_AUX)
				
				
				--CASO DE PRUEBAS: 
				--TRANS 3526858 -> APLICA : 1844021 // 3549837
				
				-- SE AGREGA EL 20220712 --> RESPONSABLE AGUSTIN BARRAZA
				-- SE AGREGA FILRO PARA LOS CASOS EN LOS CUALES LA EL TOTAL DE LA FORMA DE PAGO SUPERA EL MONTO DE LOS CBTES APLICADOS, AHORA SE GENERA A CAJA ESE SALDO A FAVOR 20220712
				IF(@Importe_Fpago <> @Total_debe)				
				BEGIN
					
					SELECT TOP 1  * INTO #CTAS_AUX_F_PAGO FROM #CTAS_AUX 
					
					UPDATE #CTAS_AUX_F_PAGO 
					SET
					Alias = (SELECT Valor_Integer FROM xParametros WHERE IdParametro = 'Alias_Pago_a_Cta'),
					Debe = (@Importe_Fpago - @Total_debe)
				
					INSERT INTO #CTAS_AUX
					SELECT * FROM #CTAS_AUX_F_PAGO					
				END
				
				
				ALTER TABLE #CTAS_AUX ADD _Item INT IDENTITY(20,1)
		      	UPDATE #CTAS_AUX SET ID_TRANS = @pId_Trans,  Id_Cta_Contable = (SELECT dbo.CF_Cta_Cont(Alias, @Fecha_Cbte))
				UPDATE #CTAS_AUX SET Item = _Item, Id_Asiento = 0, Fecha = @Fecha_Cbte, HABER = DEBE
				UPDATE #CTAS_AUX SET DEBE = 0
				ALTER TABLE #CTAS_AUX DROP COLUMN _Item

				INSERT INTO CBTES_CTAS_CONTABLES 
				       SELECT * FROM #CTAS_AUX
                DROP TABLE #CTAS_AUX

			    CLOSE curGenCtaDEBE_FAC_APLIC2
			    DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 
	    	END
		
		END ----PRINT 'FIN Compromente Recibos'
	END	

	IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 COMMIT

	SET @Mensaje = 'Asiento Generado'

	SELECT	 0				AS ErrorNumber 
			,0				AS ErrorSeverity  
			,0				AS ErrorState 
			,0				AS ErrorProcedure  
			,@pId_Trans				AS ErrorLine		
			,@Mensaje		AS ErrorMessage

END TRY  


BEGIN CATCH  
  --  SELECT  ERROR_NUMBER() AS ErrorNumber  
		--,ERROR_SEVERITY() AS ErrorSeverity  
		--,ERROR_STATE() AS ErrorState  
		--,ERROR_PROCEDURE() AS ErrorProcedure  
		--,ERROR_LINE() AS ErrorLine  
		--,ERROR_MESSAGE() AS ErrorMessage
		--,@pId_Trans		AS Id_Trans 
    EXECUTE usp_GetErrorInfo
	IF @Usar_Trans = 1 AND @@TRANCOUNT > 0 ROLLBACK

	IF (SELECT CURSOR_STATUS('global','curGenCtaDEBE_FAC_APLIC2') ) = -1
	   DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 

	IF (SELECT CURSOR_STATUS('global','curGenCtaDEBE_FAC_APLIC2') ) = 1
	BEGIN
	   CLOSE curGenCtaDEBE_FAC_APLIC2
	   DEALLOCATE curGenCtaDEBE_FAC_APLIC2		 
	END



	RETURN 9999

END CATCH

--PRINT 'Fin de ejecucion: CP_Cbtes_Ctas_Contables_Generar  Trans: '+ CAST(@pId_Trans AS VARCHAR(10))

RETURN 0



-- EXEC dbo.z_CP_Cbtes_Ctas_Contables_Generar_Version2 3526858,1
GO

CREATE PROCEDURE [dbo].[z_CP_Comodidades_20240807] @id_Criterio char(1), @id_Sede int, @id_sector char(5)
AS


-------------------------------------------------------------------------------------------------------------------------------------------------------
--Se elige Todas Comodidades 
IF (@id_Criterio='T')
BEGIN
      --Se cargan todas las comodidades asignadas 
       Select c.Id_Cliente_Externo, 
			  c.Razon_Social,
			  c.Id_Cliente, 
			  Pr.DESCRIPCION_DETALLADA,  
			  Pr.ID_PRODUCTO,
			  convert(varchar(12), CO.Fecha_Desde,103) as fecha_Desde, 
			  convert(varchar(12),c.Ult_Cuota_Paga,103) as ult_cuota_paga, 
			  C.Activo as Estado
		into #asignadast
		from Clientes C,CONTRATOS CO,Contratos_Prod P,PRODUCTOS Pr
		WHERE P.ID_PRODUCTO in (SELECT P.ID_PRODUCTO 
		                        FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S   
		                        WHERE  ACTIVO = 1 AND TIPO = 'L' AND S.ID_SECTOR = P.CALLE )                  
		AND CO.ID_CONTRATO = P.ID_CONTRATO AND CO.ACTIVO = 1 AND CO.ID_CLIENTE = C.ID_CLIENTE  
		and p.id_producto=pr.id_producto AND ISNULL(CO.FECHA_HASTA,'20500101') >= GETDATE()
		
		--Se carga Fecha ultimo pago comodidad que figura en los correspondientes comprobantes
		SELECT MAX(FECHA_QA) as max_Fecha_qa, 
		      I.ID_PRODUCTO, 
		      C.ID_CLIENTE  
       into #Ult_pago_comodidad
       FROM CBTES_ITEMS I, CBTES C 
       WHERE I.ID_TRANS = C.ID_TRANS 
			 AND C.ID_ESTADO_CBTE = 2 
			 and c.Id_Tipo_Cbte in  ('CUP', 'CADE', 'ND')
			 AND C.Id_Trans IN ( SELECT Id_Trans 
							    FROM Cbtes_Aplica 
								WHERE Id_Trans_D IN (SELECT Id_Trans 
												     FROM CBTES CB, CBTES_TIPOS CT 
													 WHERE CB.ID_tIPO_CBTE=CT.ID_TIPO_CBTE AND CT.COMPROMETE_rECIBOS=1))
			 AND I.ID_PRODUCTO in (SELECT P.ID_PRODUCTO 
								   FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S 
								   WHERE  ACTIVO = 1 AND TIPO = 'L' AND S.ID_SECTOR = P.CALLE) 
	   group by I.ID_PRODUCTO, C.ID_CLIENTE
		
		--Se elige sede
		IF @ID_SEDE IN (1,2,3) 
		BEGIN			
	        --Se elige sector
			IF (@id_sector<>'')
			BEGIN
					SELECT  P.ID_PRODUCTO, 
							P.DESCRIPCION_DETALLADA, 
							ASIG.Id_Cliente_Externo, 
							ASIG.Razon_Social, 
							CASE WHEN  ASIG.ESTADO = 1 THEN 'Activo' ELSE 'Inactivo' END  AS ESTADO,
							ASIG.Id_Cliente,  
							convert(varchar(12),ASIG.Fecha_Desde,103), 
							convert(varchar(12),ASIG.Ult_Cuota_Paga,103),
							convert(varchar(12),up.max_Fecha_qa,103) as Ult_pago_Com
				FROM ((PRODUCTOS P inner join  EMPRESAS_SEDES_SECTORES S on S.ID_SECTOR = P.CALLE  
																		 AND P.Calle =@ID_sECTOR  
																		 AND S.Id_Sede=@id_Sede) 
				left outer join #asignadast ASIG  on asig.Id_Producto=p.id_producto)
				LEFT OUTER JOIN #Ult_pago_comodidad up on UP.Id_Cliente=asig.Id_Cliente 
													   and UP.Id_Producto=P.ID_PRODUCTO
				WHERE  P.ACTIVO = 1 AND TIPO = 'L' 
				ORDER BY 2
			END
			--No se elige sector
			ELSE
			BEGIN
				SELECT  P.ID_PRODUCTO, 
							P.DESCRIPCION_DETALLADA, 
							ASIG.Id_Cliente_Externo, 
							ASIG.Razon_Social, 
							CASE WHEN  ASIG.ESTADO = 1 THEN 'Activo' ELSE 'Inactivo' END  AS ESTADO,
							ASIG.Id_Cliente,  
							convert(varchar(12),ASIG.Fecha_Desde,103), 
							convert(varchar(12),ASIG.Ult_Cuota_Paga,103),
							convert(varchar(12),up.max_Fecha_qa,103) as Ult_pago_Com
				FROM ((PRODUCTOS P 
					  inner join  EMPRESAS_SEDES_SECTORES S on S.ID_SECTOR = P.CALLE  
				                                            AND P.CALLE IN (SELECT ID_SECTOR 
																			FROM EMPRESAS_SEDES_SECTORES 
																			WHERE ID_SEDE =@id_Sede)) 
					left outer join #asignadast asig  on asig.Id_Producto=p.id_producto)
					LEFT OUTER JOIN #Ult_pago_comodidad UP on UP.Id_Cliente=asig.Id_Cliente and UP.Id_Producto=P.ID_PRODUCTO
				WHERE  P.ACTIVO = 1 AND TIPO = 'L' 
				ORDER BY 2
			END
		END	
		--No se elige Sede
		ELSE
		BEGIN
		--Se elige sector
			IF (@id_sector<>'')
			BEGIN
					SELECT  P.ID_PRODUCTO, 
							P.DESCRIPCION_DETALLADA, 
							ASIG.Id_Cliente_Externo, 
							ASIG.Razon_Social, 
							CASE WHEN  ASIG.ESTADO = 1 THEN 'Activo' ELSE 'Inactivo' END  AS ESTADO,
							ASIG.Id_Cliente,  
							convert(varchar(12),ASIG.Fecha_Desde,103), 
							convert(varchar(12),ASIG.Ult_Cuota_Paga,103),
							convert(varchar(12),up.max_Fecha_qa,103) as Ult_pago_Com
				FROM ((PRODUCTOS P inner join  EMPRESAS_SEDES_SECTORES S on S.ID_SECTOR = P.CALLE  
																		 AND P.Calle =@ID_sECTOR  
																		 ) 
				left outer join #asignadast ASIG  on asig.Id_Producto=p.id_producto)
				LEFT OUTER JOIN #Ult_pago_comodidad up on UP.Id_Cliente=asig.Id_Cliente 
													   and UP.Id_Producto=P.ID_PRODUCTO
				
				WHERE  P.ACTIVO = 1 AND TIPO = 'L' 
				ORDER BY 2
			END
			--No se elige Sector
			ELSE
			BEGIN
			 -- Asignadas unido a todas las comodidades     
				SELECT  P.ID_PRODUCTO, 
						P.DESCRIPCION_DETALLADA, 
						ASIG.Id_Cliente_Externo, 
						ASIG.Razon_Social, 
						CASE WHEN  ASIG.ESTADO = 1 THEN 'Activo' ELSE 'Inactivo' END  AS ESTADO,
						ASIG.Id_Cliente,  
						convert(varchar(12),ASIG.Fecha_Desde,103), 
						convert(varchar(12),ASIG.Ult_Cuota_Paga,103),
						convert(varchar(12),up.max_Fecha_qa,103) as Ult_pago_Com
				
				FROM ((PRODUCTOS P 
					   INNER JOIN  EMPRESAS_SEDES_SECTORES S on S.ID_SECTOR = P.CALLE) 
					   LEFT OUTER JOIN #asignadast asig  on asig.Id_Producto=p.id_producto)
					   LEFT OUTER JOIN #Ult_pago_comodidad UP on UP.Id_Cliente=asig.Id_Cliente 
															   and UP.Id_Producto=P.ID_PRODUCTO
				WHERE  P.ACTIVO = 1 AND TIPO = 'L' 
				ORDER BY 2
			END
		END

		DROP table #asignadast
		DROP TABLE #Ult_pago_comodidad
END





-------------------------------------------------------------------------------------------------------------------------------------------------------


--Se elige sólo Asignadas
IF (@id_Criterio='A')
BEGIN
	   --Busca la ultima fecha de pago de comodidad por producto y socio
       SELECT MAX(FECHA_QA) as max_Fecha_qa, 
			  I.ID_PRODUCTO, 
			  C.ID_CLIENTE  
       into #Ult_pago_comodidadA
       FROM CBTES_ITEMS I, CBTES C 
       WHERE I.ID_TRANS = C.ID_TRANS 
			 AND C.ID_ESTADO_CBTE = 2 
			 and c.Id_Tipo_Cbte in  ('CUP', 'CADE', 'ND')
			 AND C.Id_Trans IN ( SELECT Id_Trans 
								 FROM Cbtes_Aplica 
								 WHERE Id_Trans_D IN (SELECT Id_Trans 
													  FROM CBTES CB, CBTES_TIPOS CT 
													  WHERE CB.ID_tIPO_CBTE=CT.ID_TIPO_CBTE 
													  AND CT.COMPROMETE_rECIBOS=1))
			AND I.ID_PRODUCTO in (SELECT P.ID_PRODUCTO 
			                      FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S 
								  WHERE  ACTIVO = 1 
								  AND TIPO = 'L' 
								  AND S.ID_SECTOR = P.CALLE )                     
      group by I.ID_PRODUCTO, C.ID_CLIENTE


    --Se elige sede
	IF @ID_SEDE  IN (1,2,3) --<>0 
	BEGIN 
	    --Se elige sector
		IF (@id_sector<>'')
		BEGIN
			Select Pr.ID_PRODUCTO,
			       Pr.DESCRIPCION_DETALLADA, 
				   c.Id_Cliente_Externo, 
				   c.Razon_Social,
				   CASE WHEN C.Activo = 1 THEN 'Activo' ELSE 'Inactivo' END  AS ESTADO,
				   c.Id_Cliente,  
				   convert(varchar(12), CO.Fecha_Desde,103),
				   convert(varchar(12),c.Ult_Cuota_Paga,103),
				   convert(varchar(12),up.max_Fecha_qa,103) as Ult_pago_Com
			from 
			    ((((Clientes C 
					INNER JOIN CONTRATOS CO ON CO.ID_CLIENTE = C.ID_CLIENTE)
					INNER JOIN  Contratos_Prod P ON CO.ID_CONTRATO = P.ID_CONTRATO )
					INNER JOIN PRODUCTOS PR ON  p.id_producto=pr.id_productO)
					LEFT OUTER JOIN #Ult_pago_comodidadA UP ON UP.Id_Cliente=C.ID_CLIENTE 
															AND UP.Id_Producto=P.Id_Producto)
			WHERE P.ID_PRODUCTO in (SELECT P.ID_PRODUCTO 
									FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S   
									WHERE  ACTIVO = 1 
									AND TIPO = 'L' 
									AND S.ID_SECTOR = P.CALLE  
									AND P.Calle =@ID_sECTOR  
									AND S.Id_Sede=@id_Sede)  
			AND CO.ACTIVO = 1   
			AND ISNULL(CO.FECHA_HASTA,'20500101') >= GETDATE()
			ORDER BY 2
										  
		END
		--No se elige Sector
		ELSE
		BEGIN
			Select Pr.ID_PRODUCTO,
			       Pr.DESCRIPCION_DETALLADA, 
				   c.Id_Cliente_Externo, 
				   c.Razon_Social,
				   CASE WHEN C.Activo = 1 THEN 'Activo' ELSE 'Inactivo' END  AS ESTADO,
				   c.Id_Cliente,  
				   convert(varchar(12), CO.Fecha_Desde,103),
				   convert(varchar(12),c.Ult_Cuota_Paga,103),
				   convert(varchar(12),up.max_Fecha_qa,103) as Ult_pago_Com
			
			FROM  ((((Clientes C 
					INNER JOIN CONTRATOS CO ON CO.ID_CLIENTE = C.ID_CLIENTE)
					INNER JOIN  Contratos_Prod P ON CO.ID_CONTRATO = P.ID_CONTRATO )
					INNER JOIN PRODUCTOS PR ON  p.id_producto=pr.id_productO)
					LEFT OUTER JOIN #Ult_pago_comodidadA UP ON UP.Id_Cliente=C.ID_CLIENTE 
													        AND UP.Id_Producto=P.Id_Producto)
			
			WHERE  P.ID_PRODUCTO in (SELECT P.ID_PRODUCTO 
									 FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S 
			                         WHERE ACTIVO = 1 
			                         AND TIPO = 'L' 
			                         AND S.ID_SECTOR = P.CALLE 
			                         AND P.CALLE IN (SELECT ID_SECTOR 
			                                         FROM EMPRESAS_SEDES_SECTORES 
			                                         WHERE ID_SEDE =@id_Sede)) 
			 AND CO.ACTIVO = 1 
			 AND ISNULL(CO.FECHA_HASTA,'20500101') >= GETDATE()
			 ORDER BY 2
		END  
	END
	
	--No se elige sede
	ELSE
	BEGIN  
	    --Se elige sector
		IF (@id_sector<>'')
		BEGIN
			Select Pr.ID_PRODUCTO,
			       Pr.DESCRIPCION_DETALLADA, 
				   c.Id_Cliente_Externo, 
				   c.Razon_Social,
				   CASE WHEN C.Activo = 1 THEN 'Activo' ELSE 'Inactivo' END  AS ESTADO,
				   c.Id_Cliente,  
				   convert(varchar(12), CO.Fecha_Desde,103),
				   convert(varchar(12),c.Ult_Cuota_Paga,103),
				   convert(varchar(12),up.max_Fecha_qa,103) as Ult_pago_Com
			from 
			    ((((Clientes C 
					INNER JOIN CONTRATOS CO ON CO.ID_CLIENTE = C.ID_CLIENTE)
					INNER JOIN  Contratos_Prod P ON CO.ID_CONTRATO = P.ID_CONTRATO )
					INNER JOIN PRODUCTOS PR ON  p.id_producto=pr.id_productO)
					LEFT OUTER JOIN #Ult_pago_comodidadA UP ON UP.Id_Cliente=C.ID_CLIENTE 
															AND UP.Id_Producto=P.Id_Producto)
			WHERE P.ID_PRODUCTO in (SELECT P.ID_PRODUCTO 
									FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S   
									WHERE  ACTIVO = 1 
									AND TIPO = 'L' 
									AND S.ID_SECTOR = P.CALLE  
									AND P.Calle =@ID_sECTOR)  
			AND CO.ACTIVO = 1   
			AND ISNULL(CO.FECHA_HASTA,'20500101') >= GETDATE()
			ORDER BY 2							  
		END
	    ELSE 
	    BEGIN
			Select Pr.ID_PRODUCTO,
			       Pr.DESCRIPCION_DETALLADA, 
				   c.Id_Cliente_Externo, 
				   c.Razon_Social,
				   CASE WHEN C.Activo = 1 THEN 'Activo' ELSE 'Inactivo' END  AS ESTADO,
				   c.Id_Cliente,  
				   convert(varchar(12), CO.Fecha_Desde,103),
				   convert(varchar(12),c.Ult_Cuota_Paga,103),
				   convert(varchar(12),up.max_Fecha_qa,103) as Ult_pago_Com
				  
		 FROM  ((((Clientes C 
				   INNER JOIN CONTRATOS CO ON CO.ID_CLIENTE = C.ID_CLIENTE)
				   INNER JOIN  Contratos_Prod P ON CO.ID_CONTRATO = P.ID_CONTRATO )
				   INNER JOIN PRODUCTOS PR ON  p.id_producto=pr.id_productO)
				   LEFT OUTER JOIN #Ult_pago_comodidadA UP ON UP.Id_Cliente=C.ID_CLIENTE 
															  AND UP.Id_Producto=P.Id_Producto) 		
		WHERE P.ID_PRODUCTO in (SELECT P.ID_PRODUCTO 
		                        FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S   
		                        WHERE  ACTIVO = 1 
		                        AND TIPO = 'L' 
		                        AND S.ID_SECTOR = P.CALLE )  
		AND CO.ACTIVO = 1 
		AND ISNULL(CO.FECHA_HASTA,'20500101') >= GETDATE() 
		ORDER BY 2
		END
	END   

	DROP TABLE #Ult_pago_comodidadA

END

-------------------------------------------------------------------------------------------------------------------------------------------------------
--Se eligen Libres
IF (@id_Criterio='L')
BEGIN
		--Busca las que ya están ocupadas
		Select c.Id_Cliente_Externo, 
			   c.Razon_Social,
			   c.Id_Cliente, 
			   Pr.DESCRIPCION_DETALLADA,  
			   Pr.ID_PRODUCTO,
			   convert(varchar(12), CO.Fecha_Desde,103) as fecha_Desde, 
			   convert(varchar(12),c.Ult_Cuota_Paga,103) as ult_cuota_paga
		into #asignadasl
		from Clientes C,CONTRATOS CO,Contratos_Prod P,PRODUCTOS Pr
		WHERE P.ID_PRODUCTO in (SELECT P.ID_PRODUCTO 
		                        FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S   
		                        WHERE  ACTIVO = 1 
		                        AND TIPO = 'L' 
		                        AND S.ID_SECTOR = P.CALLE ) 
		AND CO.ID_CONTRATO = P.ID_CONTRATO 
		AND CO.ACTIVO = 1 AND CO.ID_CLIENTE = C.ID_CLIENTE  
		and p.id_producto=pr.id_producto 
		AND ISNULL(CO.FECHA_HASTA,'20500101') >= GETDATE() 

 --Se elige sede
	IF @ID_SEDE IN (1,2,3) --<>0 
	BEGIN 
	    --Se elige sector
		IF (@id_sector<>'')
		BEGIN
			 SELECT  P.ID_PRODUCTO,
			         P.DESCRIPCION_DETALLADA,
			         '--' as Id_Cliente_Externo, 
					 '--' as Razon_Social,
					 '--' as Estado,
					 '--' as Id_Cliente,	
					 '--' as Fecha_Desde,
					 '--' as Ult_Cuota_Paga,
					 '--' as Ult_pago_Com  
			 
			 FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S  
			 WHERE  ACTIVO = 1 
			 AND TIPO = 'L' 
			 AND S.ID_SECTOR = P.CALLE 
			 AND P.Calle =@ID_sECTOR  
			 AND S.Id_Sede=@id_Sede
			 and p.Id_Producto not in (select Id_Producto from #asignadasl)
			 ORDER BY 2 
		END
		--No se elige Sector
		ELSE
		BEGIN
			 SELECT  P.ID_PRODUCTO,
			         P.DESCRIPCION_DETALLADA,
			         '--' as Id_Cliente_Externo, 
					 '--' as Razon_Social,
					 '--' as Estado,
					 '--' as Id_Cliente,	
					 '--' as Fecha_Desde,
					 '--' as Ult_Cuota_Paga,
					 '--' as Ult_pago_Com  
			 
			FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S  
			WHERE  ACTIVO = 1 
			       AND TIPO = 'L' 
			       AND S.ID_SECTOR = P.CALLE  
			       AND P.CALLE IN (SELECT ID_SECTOR 
			                       FROM EMPRESAS_SEDES_SECTORES 
			                       WHERE ID_SEDE =@id_Sede)
			and p.Id_Producto not in (select Id_Producto from #asignadasl)
			ORDER BY 2
		END
	END
	--No se elige Sede
	ELSE
	BEGIN
	 --Se elige sector
		IF (@id_sector<>'')
		BEGIN
			 SELECT  P.ID_PRODUCTO,
			         P.DESCRIPCION_DETALLADA,
			         '--' as Id_Cliente_Externo, 
					 '--' as Razon_Social,
					 '--' as Estado,
					 '--' as Id_Cliente,	
					 '--' as Fecha_Desde,
					 '--' as Ult_Cuota_Paga,
					 '--' as Ult_pago_Com  
			 
			 FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S  
			 WHERE  ACTIVO = 1 
			 AND TIPO = 'L' 
			 AND S.ID_SECTOR = P.CALLE 
			 AND P.Calle =@ID_sECTOR  
			 and p.Id_Producto not in (select Id_Producto from #asignadasl)
			 ORDER BY 2 
		END
		--No se elige Sector
		ELSE
		BEGIN
			SELECT  P.ID_PRODUCTO,
					P.DESCRIPCION_DETALLADA,
					'--' as Id_Cliente_Externo, 
					'--' as Razon_Social,
					'--' as Estado,
					'--' as Id_Cliente,	
					'--' as Fecha_Desde,
					'--' as Ult_Cuota_Paga,
					'--' as Ult_pago_Com  	
			FROM PRODUCTOS P, EMPRESAS_SEDES_SECTORES S  
			WHERE  ACTIVO = 1 
			AND TIPO = 'L' 
			AND S.ID_SECTOR = P.CALLE 
			and p.Id_Producto not in (select Id_Producto from #asignadasl)
			ORDER BY 2
		END
	END
	DROP TABLE #asignadasl
END
GO



create PROCEDURE [dbo].[z_CP_SCA_RegistrarAcceso_20250618]	@pId_Controlador		SMALLINT,
												@pTipoAcceso			CHAR(1),		/*E: Entrada / S:Salida*/
												@pFecha					DATETIME,		/*Fecha a comparar*/
												@pFechaEvento			DATETIME,		/*Fecha del Evento a comparar. Si no es un evento ingresar 19000101*/
												@pTag					VARCHAR(MAX),	/*Credencial MiFare / Wiegand*/
												@pDoc					BIGINT,			/*Documento*/
												@pHue					VARCHAR(5000),	/*Huella Dactilar*/
												@pCba					VARCHAR(20),	/*Codigo de Barra*/
												@pDma					VARCHAR(5000),	/*Data Matrix*/
												@pFlag_GrabaRegistro	TINYINT = NULL, /*23/09/2019. 1(default): Graba Registro. 0: No graba el registro*/
												@pFlag_Permite_Paso		TINYINT = NULL,	/*05/02/2020. 1: Si el resultado es habilitado permite que la persona pase 1 vez mas la proxima vez*/
												@pFlag_Generacion_LB	TINYINT = NULL	/*02/11/2020. 1: Si la llamada la esta haciendo para generar Listas Blancas, en esos casos hay validaciones que no hace como Validacion de Turnos*/
AS

BEGIN

/*Variables Locales*/
DECLARE @Id_Cliente							INT
DECLARE @Id_Cliente_Ref						INT
DECLARE @Huella								VARBINARY
DECLARE @Tipo_Validacion					CHAR(1)
DECLARE @Activo								TINYINT
DECLARE @Foto								VARCHAR(254)
DECLARE @Foto_Bin							VARBINARY(MAX)
DECLARE @Ult_Foto_Bin						TINYINT
DECLARE @ValidarAcceso						TINYINT
DECLARE @ValidarPersona						TINYINT
DECLARE @ValidoTagsImportados				TINYINT
DECLARE @ValidoTicketEvento					TINYINT		/*07/10/2021(2): Validacion Agregada CP_SCA_ValidoTagsImportados*/
DECLARE @ValidarContratosTiposRechazos		INT
DECLARE @Flag_ValidarMaster					TINYINT
DECLARE @ValidarContratosTipos				INT
DECLARE @ContratoRechazo_Descripcion		VARCHAR(500)
DECLARE @ContratoHabilitado_Descripcion		VARCHAR(500)
DECLARE @ValidarTipo						SMALLINT
DECLARE @Clientes_Tipos_Habil_Descripcion	VARCHAR(5000)
DECLARE @ValidarTipoRechazo					SMALLINT
DECLARE @Clientes_Tipos_Rechazo_Descripcion	VARCHAR(500)
DECLARE @ValidarProdVta						VARCHAR(14)
DECLARE @Producto_Descripcion_Resumida		VARCHAR(100)
DECLARE @ValidarEvento						SMALLINT
DECLARE @Clientes_Tipos_Habil_Evento		VARCHAR(5000)
DECLARE @Flag_Antipassback					CHAR(1)
DECLARE @Flag_ValidarUCP					TINYINT
DECLARE @ValidarVencimientosPersona			VARCHAR(10)
DECLARE @VencimientoPersona_Descripcion		VARCHAR(50)
DECLARE @pId_Acceso							SMALLINT
DECLARE @Flag_Foto_Validar					TINYINT		/*14/03/2019 Validacion Agregada*/
DECLARE @Flag_Turno_Validar					TINYINT		/*10/08/2020 Validacion Agregada*/
DECLARE @Id_CD_Motivo						INT
DECLARE @AccesoPermitidoManualmente			TINYINT		/*05/02/2020 Agregado*/
DECLARE @Flag_Clientes_Link_Validar			TINYINT		/*28/09/2020 Validacion agregada por QR impresos*/
DECLARE @ValidoCleverQR						INT			/*21/10/2020 Validacion agregada de rechazo por CleverQR*/
DECLARE @Tipo_Cont							CHAR(1)
DECLARE @Flag_Evento						TINYINT
DECLARE @Evento_QR_Formato					VARCHAR(40)
DECLARE @Flag_Horario						TINYINT
DECLARE @Horario							TINYINT
DECLARE @Flag_TipoValidacionUCP				TINYINT     /*15/11/2022 Agregado para el rechazo y habilitacion por UCP*/
/*FIN Variables Locales*/
						
PRINT 'INCIO del Proceso: CP_SCA_RegistrarAcceso'

/*  Orden de Validaciones 
  - Verificacion de recepcion de datos de consulta
  - Validacion por Acceso existente
  - Validacion por Tags Importados
  - Validacion por Ticket/Entradas Evento
  - Validacion por CleverQR
  - Validacion por Cliente existente
  - Validacion por Acceso Permitido Manualmente
  - SECCION DE RECHAZOS
  - SECCION DE HABILITACIONES
*/


SELECT 
@Tipo_Cont = ISNULL(Tipo_Cont, '')
FROM CD_Controladores
WHERE
Id_Controlador = @pId_Controlador
PRINT '@Tipo_Cont: ' + @Tipo_Cont

SET @pId_Acceso = (dbo.CF_SCA_IdAcceso(@pId_Controlador))

PRINT 'Id_Acceso: ' + CONVERT(VARCHAR(10), @pId_Acceso) + ' Fecha: ' + CONVERT(VARCHAR(10), @pFecha, 103)
PRINT '@pTipoAcceso: ' + CONVERT(VARCHAR(10), @pTipoAcceso)
PRINT '@pTag: ' + @pTag
PRINT '@pDoc: ' + CONVERT(VARCHAR(10), @pDoc)
PRINT '@pHue: ' + @pHue
PRINT '@pCba: ' + @pCba
PRINT '@pDma: ' + @pDma

IF(@pFlag_GrabaRegistro IS NULL)
BEGIN
	SET @pFlag_GrabaRegistro = 1
END
PRINT '@pFlag_GrabaRegistro: ' + CONVERT(VARCHAR(10), @pFlag_GrabaRegistro)

IF(@pFlag_Permite_Paso IS NULL)
BEGIN
	SET @pFlag_Permite_Paso = 0
END
PRINT '@pFlag_Permite_Paso: ' + CONVERT(VARCHAR(10), @pFlag_Permite_Paso)

IF(@pFlag_Generacion_LB IS NULL)
BEGIN
	SET @pFlag_Generacion_LB = 0
END
PRINT '@pFlag_Generacion_LB: ' + CONVERT(VARCHAR(10), @pFlag_Generacion_LB)

SET @Huella	= CONVERT(VARBINARY, @pHue)

SET @Tipo_Validacion = dbo.CF_SCA_TipoValidacion(@pTag, @pDoc, @pHue, @pCba, @pDma)

PRINT 'Tipo de Validacion: ' + @Tipo_Validacion

IF(@Tipo_Validacion = 'N')
BEGIN
	SET @Id_CD_Motivo = 101 /*No se enviaron datos de validacion*/
    EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ERROR', '', 0, 0, 0, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
	RETURN
END

/*A partir de aca existe una variable de validacion*/

/* Valido si existe el Acceso */
SET @ValidarAcceso = (dbo.CF_SCA_ValidoAcceso(@pId_Acceso))
PRINT 'Acceso Valido: ' + CONVERT(VARCHAR(10), @ValidarAcceso)

IF(@ValidarAcceso = 0)
BEGIN
	SET @Id_CD_Motivo = 102 /*El Acceso no existe*/
	EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ERROR', '', 0, 0, 0, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
	RETURN
END
/* FIN Valido si existe el Acceso */


/*06/10/2021 Se agrega para Extraer Dato Flag_Evento y determinar que validaciones se hacen y cuales no dependiendo si es un evento*/
SELECT
@Flag_Evento = ISNULL(Flag_Evento, 0)
FROM CD_Accesos
WHERE
Id_Acceso = @pId_Acceso
/*FIN 06/10/2021*/

/* 14/11/22 Florencia: Se agrega un nuevo tipo de validacion por UCP.
Tipo 0: No se valida por UCP por Acceso
Tipo 1: Con tener la UCP el socio se ve habilitado (se valida en la seccion de habilitaciones)
Tipo 2: El socio debe tener UCP obligatoriamente y ademas un abono de producto que habilite el acceso (se valida en la seccion de rechazos) */

SELECT @Flag_TipoValidacionUCP = ISNULL(Flag_Ult_Cuota_Paga,0)
								 FROM CD_Accesos
								 WHERE Id_Acceso = @pId_Acceso
/* Fin 14/11/2022*/

/* Valido Tags Importados */
IF(@Flag_Evento IN (1))
BEGIN
	EXEC dbo.CP_SCA_ValidoTagsImportados @pTag, @pId_Acceso, @Flag_TagHabilitado = @ValidoTagsImportados OUTPUT

	PRINT 'Valido Tags Importados: ' + CONVERT(VARCHAR(10), ISNULL(@ValidoTagsImportados, 0))

	IF(ISNULL(@ValidoTagsImportados, 0) = 1)
	BEGIN
		SET @Id_CD_Motivo = 201 /*Ingreso por Ticket Import.*/
		EXEC CP_SCA_RegistrarAcceso_Rta 1, '', 'ADVER', '', 0, 0, 0, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Valido Tags Importados */


/* Valido Ticket/Entradas Evento */
/*07/10/2021(2): Agregado*/
SET @Evento_QR_Formato = dbo.CF_xParam('Evento_QR_Formato')

IF(@Flag_Evento IN (1) AND @Evento_QR_Formato <> 'DNI')
BEGIN
	EXEC dbo.CP_SCA_ValidoTicketEvento @pTag, @pId_Acceso, @Flag_TicketHabilitado = @ValidoTicketEvento OUTPUT

	PRINT 'Valido Ticket/Entrada Evento: ' + CONVERT(VARCHAR(10), @ValidoTicketEvento)

	IF(@ValidoTicketEvento = 1)
	BEGIN
		SET @Id_CD_Motivo = 117 /*Ticket Valido*/
		EXEC CP_SCA_RegistrarAcceso_Rta 1, '', 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
	END

	IF(@ValidoTicketEvento = 0)
	BEGIN
		SET @Id_CD_Motivo = 213 /*Ticket Invalido*/
		EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ADVER', '', 0, 0, 0, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
		
	IF(@ValidoTicketEvento = -1)
	BEGIN
		SET @Id_CD_Motivo = 214 /*Ticket ya utilizado*/
		EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ADVER', '', 0, 0, 0, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END

	IF(@ValidoTicketEvento = -2)
	BEGIN
		SET @Id_CD_Motivo = 215 /*Ticket Puerta Incorrecta*/
		EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ADVER', '', 0, 0, 0, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/*FIN 07/10/2021(2): Agregado*/
/* FIN Valido Ticket/Entradas Eventos*/


/* Valido si lo que recibio es un CleverQR */
IF(@Flag_Evento IN (0,1))
BEGIN
	IF(	LEN(@pTag) = 10
	AND dbo.CF_IsNumeric(@pTag) = 1 
	AND SUBSTRING(@pTag,1,1) = '9')
	BEGIN
		SET @pDma = @pTag
	END
	
	IF(@pDma <> '')
	BEGIN
		EXEC dbo.CP_SCA_ValidoCleverQR @pDma, @pId_Acceso, @pFecha, @Flag_QRValido = @ValidoCleverQR OUTPUT
		PRINT 'Valido CleverQR: ' + CONVERT(VARCHAR(10), @ValidoCleverQR)
	
		IF(@ValidoCleverQR = 0)
		BEGIN
			SET @Id_CD_Motivo = 114 /*QR Invalido*/
			EXEC CP_SCA_RegistrarAcceso_Rta 1, '', 'ADVER', '', 0, 0, 0, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
			RETURN
		END
	
		IF(@ValidoCleverQR = -1)
		BEGIN
			SET @Id_CD_Motivo = 115 /*QR Vencido*/
			EXEC CP_SCA_RegistrarAcceso_Rta 1, '', 'ERROR', '', 0, 0, 0, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
			RETURN
		END
	
		IF(@ValidoCleverQR = -2)
		BEGIN
			SET @Id_CD_Motivo = 116 /*QR ya utilizado*/
			EXEC CP_SCA_RegistrarAcceso_Rta 1, '', 'ERROR', '', 0, 0, 0, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
			RETURN
		END
	END
END
/* FIN Valido si lo que recibio es un CleverQR */


/* Valido que el cliente exista */
SET @Id_Cliente = (SELECT dbo.CF_SCA_IdentifIdCliente(@pTag))

PRINT '@Id_Cliente: ' + CONVERT(VARCHAR(10), @Id_Cliente)
/* Fin Valido que el cliente exista */

/* Acceso Permitido Manualmente. Agregado 05/02/2020 */
IF(@Flag_Evento IN (0))
BEGIN
	EXEC dbo.CP_SCA_ValidoAccesoPermitidoManualmente @Id_Cliente, @pFecha, @pId_Controlador, @Flag_AccesoPermitidoManualmente = @AccesoPermitidoManualmente OUTPUT

	PRINT 'Acceso permitido manualmente: ' + CONVERT(VARCHAR(10), ISNULL(@AccesoPermitidoManualmente, 0))

	IF(ISNULL(@AccesoPermitidoManualmente, 0) = 1)
	BEGIN
		SET @Id_CD_Motivo = 211 /*Ingreso por Habilt. Manualmente.*/
		EXEC CP_SCA_RegistrarAcceso_Rta 1, '', 'ADVER', '', 0, 0, 0, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Acceso Permitido Manualmente */


/* Valido Persona */
IF(@Flag_Evento IN (0,1))
BEGIN
	SET @ValidarPersona = (dbo.CF_SCA_ValidarPersona(@Id_Cliente))
	PRINT 'Persona Valida: ' + CONVERT(VARCHAR(10), @ValidarPersona)

	IF(@ValidarPersona = 0)
	BEGIN
		SET @Id_CD_Motivo = 103 /*La Persona es invalida*/
		EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ERROR', '', 0, 0, 0, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Valido Persona */


/* Datos Persona */
SELECT 
@Activo			= ISNULL(Activo, 0),
@Foto			= ISNULL(Foto, ''),
@Id_Cliente_Ref	= ISNULL(Id_Cliente_Ref, 0)
FROM Clientes 
WHERE 
Id_Cliente = @Id_Cliente

PRINT 'Persona Activa: ' + CONVERT(VARCHAR(10), @Activo)
PRINT 'Persona Foto: ' + @Foto
PRINT 'Id_Cliente Titular: ' + CONVERT(VARCHAR(10), @Id_Cliente_Ref)

SET @Ult_Foto_Bin = ISNULL((SELECT MIN(Nro) FROM Clientes_Fotos WHERE Id_Cliente = @Id_Cliente), 0) ---siempre tomamos la 1

IF(@Ult_Foto_Bin <> 0)
BEGIN
	IF(dbo.CF_xParam('SCA_RtaCtrl_Foto') = 1 AND @Tipo_Cont <> 'K'/*Molinete Intelektron*/)
	BEGIN
		SET @Foto_Bin = (SELECT Foto FROM Clientes_Fotos CF WHERE Id_Cliente = @Id_Cliente AND Nro = @Ult_Foto_Bin)		
	END
		
	PRINT 'Persona Foto_Bin: ' + CONVERT(VARCHAR(MAX), @Foto_Bin)
END
/* FIN Datos Persona */

/* Valido si existen Productos con Horarios */
SET @Flag_Horario = ISNULL((SELECT MAX(1) FROM CD_Accesos_Horarios WHERE Id_Horario>0 AND Id_Acceso=@pId_Acceso),0)

	IF (@Flag_Horario=1)
		SET @Horario=0
	ELSE
		SET @Horario=0
/* Fin si existen Productos con Horarios */

/********************************************************************************
*********************************************************************************
**********************************************************************************/

/* COMIENZO SECCION DE RECHAZOS. Orden de rechazos:

1) Rechaza por Persona Inactiva
2) Rechaza por Vencimientos: CF_SCA_ValidarVencimientosPersona
3) Rechaza por Contratos Tipos de Rechazo: CF_SCA_ValidarContratosTiposRechazos
4) Rechaza por Tipo de Categoria de Rechazo: CF_SCA_ValidarTipoRechazos
5) Rechaza por AntiPassBack: CF_SCA_Antipassback
6) Rechaza por Foto Grabada: CP_SCA_ValidarFoto
7) Rechaza por Turno: CP_SCA_ValidarTurno
8) Rechaza por UCP: CF_SCA_ValidarUltCuotaPaga

*/

/* Rechaza por Persona Inactiva */
IF(@Flag_Evento IN (0,1))
BEGIN
	IF(@Activo = 0)
	BEGIN
		SET @Id_CD_Motivo = 104 /*La Persona esta desactivada*/
		EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ADVER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Rechaza por Persona Inactiva */


/* Rechaza por Vencimientos */
IF(@Flag_Evento IN (0))
BEGIN
	SET @ValidarVencimientosPersona = (dbo.CF_SCA_ValidarVencimientosPersona(@Id_Cliente, @pId_Acceso, @pFecha))
	PRINT 'Valida Vencimientos: ' + CONVERT(VARCHAR(10), @ValidarVencimientosPersona)

	IF(@ValidarVencimientosPersona <> '')
	BEGIN
		SET @Id_CD_Motivo = 105 /*Rechazo por Tipo de Venc.*/
		SET @VencimientoPersona_Descripcion = (SELECT SUBSTRING(RTRIM(LTRIM(Descripcion)), 1, 16) FROM Clientes_Venc_Tipos WHERE Id_Tipo_Venc = @ValidarVencimientosPersona) + ' vencido el: ' + (SELECT CONVERT(VARCHAR(10), CV.Fecha, 105) FROM Clientes_Venc CV WHERE CV.Id_Cliente = @Id_Cliente AND CV.Id_Tipo_Venc = @ValidarVencimientosPersona )
		PRINT 'Tipo de Vencimiento de Rechazo: ' + @VencimientoPersona_Descripcion
	
		EXEC CP_SCA_RegistrarAcceso_Rta 0, @VencimientoPersona_Descripcion, 'ADVER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Rechaza por Vencimientos */


/* Rechaza por Contratos Tipos de Rechazo */
IF(@Flag_Evento IN (0,1))
BEGIN
	SET @ValidarContratosTiposRechazos = (dbo.CF_SCA_ValidarContratosTiposRechazos(@Id_Cliente, @pId_Acceso, @pFecha))
	PRINT 'Valida Contratos Tipos Rechazos: ' + CONVERT(VARCHAR(10), @ValidarContratosTiposRechazos)

	IF(@ValidarContratosTiposRechazos <> 0)
	BEGIN
		SET @Id_CD_Motivo = 106 /*Rechazo por Tipo de Contrato*/
		SET @ContratoRechazo_Descripcion = (SELECT RTRIM(LTRIM(CT.Descripcion)) FROM Contratos_Tipos CT, Contratos CO WHERE CT.Id_Tipo_Con = CO.Id_Tipo_Con AND Id_Contrato = @ValidarContratosTiposRechazos)
		PRINT 'Tipo de Contrato de Rechazo: ' + @ContratoRechazo_Descripcion

		EXEC CP_SCA_RegistrarAcceso_Rta 0, @ContratoRechazo_Descripcion, 'ADVER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Rechaza por Contratos Tipos de Rechazo */


/* Rechaza por Tipo de Categoria de Rechazo */
IF(@Flag_Evento IN (0))
BEGIN
	SET @ValidarTipoRechazo = (dbo.CF_SCA_ValidarTipoRechazos(@Id_Cliente, @pId_Acceso, @pFecha))
	PRINT 'Tipo de Cliente de Rechazo: ' + CONVERT(VARCHAR(10), @ValidarTipoRechazo)

	IF(@ValidarTipoRechazo <> 0)
	BEGIN
		SET @Id_CD_Motivo = 107 /*Rechazo por Categoria*/
	
		SET @Clientes_Tipos_Rechazo_Descripcion = (SELECT RTRIM(LTRIM(CT.Descripcion)) FROM Clientes_Tipos CT WHERE Id_Tipo_Cli = @ValidarTipo)
		PRINT 'Tipo de Cliente de Rechazo: ' + @Clientes_Tipos_Rechazo_Descripcion
	
		EXEC CP_SCA_RegistrarAcceso_Rta 0, @Clientes_Tipos_Rechazo_Descripcion, 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Rechaza por Tipo de Categoria de Rechazo */

/* Rechaza por AntiPassBack */
IF(@Flag_Evento IN (0,1))
BEGIN
	SET @Flag_Antipassback = (dbo.CF_SCA_Antipassback(@Id_Cliente, @pId_Acceso, @pFecha, @pTipoAcceso, @pFechaEvento))
	PRINT 'Flag Antipassback: ' + @Flag_Antipassback
	IF(@Flag_Antipassback <> 'O')
	BEGIN
		IF(@Flag_Antipassback = 'Y')
		BEGIN
			SET @Id_CD_Motivo = 108 /*Ya ingresado. Antipassback*/
			EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ADVER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		END
	
		IF(@Flag_Antipassback = 'E')
		BEGIN
			SET @Id_CD_Motivo = 109 /*No Registro Salida. Antipassback*/
			EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ADVER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		END
	
		IF(@Flag_Antipassback = 'S')
		BEGIN
			SET @Id_CD_Motivo = 110 /*No Registro Entrada. Antipassback*/
			EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ADVER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		END
		RETURN
	END
END
/* FIN Rechaza por AntiPassBack */


/* Rechaza por Foto Grabada */
IF(@Flag_Evento IN (0,1))
BEGIN
	EXEC dbo.CP_SCA_ValidarFoto @Id_Cliente, @pId_Acceso, @pFecha, @pTipoAcceso, @pFechaEvento, @Flag_ValidarFoto_Rta = @Flag_Foto_Validar OUTPUT

	PRINT 'Valido Foto Cliente: ' + CONVERT(VARCHAR(10), @Flag_Foto_Validar)

	IF(@Flag_Foto_Validar <> 1)
	BEGIN
		SET @Id_CD_Motivo = 111 /*No posee foto*/
		EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ADVER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Rechaza por Foto Grabada */


/* Rechaza por Turno (10/08/2020) */
IF(@Flag_Evento IN (0))
BEGIN
	IF(@pFlag_Generacion_LB = 0) --02/11/2020 Solo valida turno si no esta generando una lista blanca (Simulacion de entrada)
	BEGIN
		IF(@pTipoAcceso = 'E') /*Solo se valida Turno si es Entrada*/
		BEGIN
			EXEC dbo.CP_SCA_ValidarTurno @Id_Cliente, @pId_Acceso, @pFecha, @pTipoAcceso, @pFechaEvento, @Flag_ValidarTurno_Rta = @Flag_Turno_Validar OUTPUT

			PRINT 'Valido Turno Cliente: ' + CONVERT(VARCHAR(10), @Flag_Turno_Validar)

			IF(@Flag_Turno_Validar <> 1)
			BEGIN
				SET @Id_CD_Motivo = 113 /*No posee un Turno*/
				EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ADVER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
				RETURN
			END
		END
	END
END
/* FIN Rechaza por Turno */

/* Rechaza por UCP */
/* Agregado 15/11/22 */
IF(@Flag_Evento IN (0) AND @Flag_TipoValidacionUCP = 2) /* 15/11/2022: Se agrega validacion por Flag_TipoValidacionUCP */
BEGIN
	SET @Flag_ValidarUCP = (dbo.CF_SCA_ValidarUltCuotaPaga(@Id_Cliente, @pId_Acceso, @pFecha))
	IF(@Flag_ValidarUCP = 0)
	BEGIN
		PRINT 'Valido UCP: ' + 'No posee UCP al dia'
	
		SET @Id_CD_Motivo = 309 /*La Persona no posee UCP al dia*/
	
		EXEC CP_SCA_RegistrarAcceso_Rta 0,  '', 'ADVER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Rechaza por UCP */

/* FIN DE SECCION RECHAZOS */

/********************************************************************************
*********************************************************************************
**********************************************************************************/

/* COMIENZO SECCION DE HABILITACIONES. Orden de habilitaciones:

1) Habilita por Acceso Master: CF_SCA_ValidarMaster
2) Habilita por Clientes Links: CP_SCA_ValidarClientes_Links
3) Habilita por UCP: CF_SCA_ValidarUltCuotaPaga
4) Habilita por Contratos Tipos: CF_SCA_ValidarContratosTipos
5) Habilita por Tipo de Categoria de Cliente: CF_SCA_ValidarTipo
6) Habilita por Kit de Productos Comprado: CP_SCA_ValidarProducVta_Kit
7) Habilita por Producto de Comprado: CP_SCA_ValidarProducVta
8) Habilita por Producto de Comprado por Titular: CP_SCA_ValidarProducVta
9) Habilita por Evento: CF_SCA_ValidarEvento
10) Habilita por Tipo de Cliente y por Horario: CF_SCA_ValidarCategHorario
11) Habilita por Producto Comprado y por Horario: CP_SCA_ValidarProducVta

*/

/* Habilita por Acceso Master */
IF(@Flag_Evento IN (0,1))
BEGIN
	SET @Flag_ValidarMaster = (dbo.CF_SCA_ValidarMaster(@Id_Cliente))
	PRINT 'Valida Persona Master: ' + CONVERT(VARCHAR(10), @Flag_ValidarMaster)

	IF(@Flag_ValidarMaster = 1)
	BEGIN
		SET @Id_CD_Motivo = 202 /*Acceso Master*/
	
		EXEC CP_SCA_RegistrarAcceso_Rta 1, '', 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Habilita por Acceso Master */

/* Habilita por Clientes_Links (28/09/2020)*/
IF(@Flag_Evento IN (0))
BEGIN
	EXEC dbo.CP_SCA_ValidarClientes_Links @Id_Cliente, @pId_Acceso, @pFecha, @pTipoAcceso, @pFechaEvento, @Flag_ValidarClientes_Link_Rta = @Flag_Clientes_Link_Validar OUTPUT

	PRINT 'Valido Clientes_Link: ' + CONVERT(VARCHAR(10), @Flag_Clientes_Link_Validar)

	IF(@Flag_Clientes_Link_Validar = 1)
	BEGIN
		SET @Id_CD_Motivo = 212 /*Habilit. por QR*/
		EXEC CP_SCA_RegistrarAcceso_Rta 1, '', 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Habilita por Clientes_Links */


/* Habilita por UCP */
IF(@Flag_Evento IN (0,1) AND @Flag_TipoValidacionUCP = 1) /* 15/11/2022: Se agrega validacion por Flag_TipoValidacionUCP */
BEGIN
	SET @Flag_ValidarUCP = (dbo.CF_SCA_ValidarUltCuotaPaga(@Id_Cliente, @pId_Acceso, @pFecha))
	IF(@Flag_ValidarUCP = 1)
	BEGIN
		PRINT 'Tipo de Habilitacion: ' + 'Habilitado. La Persona posee UCP al dia'
	
		SET @Id_CD_Motivo = 203 /*La Persona con UCP al dia*/
	
		EXEC CP_SCA_RegistrarAcceso_Rta 1,  '', 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Habilita por UCP */


/* Habilita por Contratos Tipos */
IF(@Flag_Evento IN (0,1))
BEGIN
	SET @ValidarContratosTipos = (dbo.CF_SCA_ValidarContratosTipos(@Id_Cliente, @pId_Acceso, @pFecha))
	PRINT 'Valida Contratos Tipos de Habilitacion: ' + CONVERT(VARCHAR(10), @ValidarContratosTipos)

	IF(@ValidarContratosTipos <> 0)
	BEGIN
		SET @Id_CD_Motivo = 204 /*Habilit. por Tipo de Contrato*/
	
		SET @ContratoHabilitado_Descripcion = (SELECT RTRIM(LTRIM(CT.Descripcion)) FROM Contratos_Tipos CT, Contratos CO WHERE CT.Id_Tipo_Con = CO.Id_Tipo_Con AND Id_Contrato = @ValidarContratosTipos)
		PRINT 'Tipo de Contrato de Habilitacion: ' + @ContratoHabilitado_Descripcion

		EXEC CP_SCA_RegistrarAcceso_Rta 1,  @ContratoHabilitado_Descripcion, 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Habilita por Contratos Tipos */


/* Habilita por Tipo de Categoria de Cliente */
IF(@Flag_Evento IN (0,1))
BEGIN
	SET @ValidarTipo = (dbo.CF_SCA_ValidarTipo(@Id_Cliente, @pId_Acceso, @pFecha))
	PRINT 'Tipo de Cliente de Habilitacion: ' + CONVERT(VARCHAR(10), @ValidarTipo)

	IF(@ValidarTipo <> 0)
	BEGIN
		SET @Id_CD_Motivo = 205 /*Habilit. por Tipo de Cliente*/
	
		SET @Clientes_Tipos_Habil_Descripcion = (SELECT RTRIM(LTRIM(CT.Descripcion)) FROM Clientes_Tipos CT WHERE Id_Tipo_Cli = @ValidarTipo)
		PRINT 'Tipo de Cliente de Habilitacion: ' + @Clientes_Tipos_Habil_Descripcion

		EXEC CP_SCA_RegistrarAcceso_Rta 1, @Clientes_Tipos_Habil_Descripcion, 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Habilita por Tipo de Categoria de Cliente */

/* Habilita por Produc. Pack Comprado */
IF(@Flag_Evento IN (0))
BEGIN
	EXEC dbo.[CP_SCA_ValidarProducVta_Kit] @Id_Cliente, @pId_Acceso, @pFecha,0,@Horario, @pFlag_GrabaRegistro, @Id_Producto = @ValidarProdVta  OUTPUT

	PRINT 'Valida Producto de Venta Kit: ' + @ValidarProdVta

	IF(@ValidarProdVta <> '')
	BEGIN
		SET @Id_CD_Motivo = 301 /*Habilit. por Produc. Pack Comprado*/
	
		SET @Producto_Descripcion_Resumida = (SELECT ISNULL(Descripcion_Resumida, Id_Producto) FROM Productos WHERE Id_Producto = @ValidarProdVta)
		PRINT 'Producto de Venta Kit: ' + @Producto_Descripcion_Resumida
	
		EXEC CP_SCA_RegistrarAcceso_Rta 1, @Producto_Descripcion_Resumida, 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Habilita por Produc. Pack Comprado */

/* Habilita por Producto de Comprado */
IF(@Flag_Evento IN (0))
BEGIN
	EXEC dbo.[CP_SCA_ValidarProducVta] @Id_Cliente, @pId_Acceso, @pFecha,0,@Horario, @Id_Producto = @ValidarProdVta  OUTPUT

	PRINT 'Valida Producto de Venta: ' + @ValidarProdVta

	IF(@ValidarProdVta <> '')
	BEGIN
		SET @Id_CD_Motivo = 206 /*Habilit. por Produc. Comprado*/
	
		SET @Producto_Descripcion_Resumida = (SELECT ISNULL(Descripcion_Resumida, Id_Producto) FROM Productos WHERE Id_Producto = @ValidarProdVta)
		PRINT 'Producto de Venta: ' + @Producto_Descripcion_Resumida
	
		EXEC CP_SCA_RegistrarAcceso_Rta 1, @Producto_Descripcion_Resumida, 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Habilita por Producto de Comprado */


/* Habilita por Producto de Comprado por Titular */
IF(@Flag_Evento IN (0))
BEGIN
	IF (@Id_Cliente_Ref<>0)
	BEGIN
		EXEC dbo.[CP_SCA_ValidarProducVta] @Id_Cliente, @pId_Acceso, @pFecha,@Id_Cliente_Ref,@Horario, @Id_Producto = @ValidarProdVta  OUTPUT

		SET @Id_CD_Motivo = 207 /*Habilit. por Produc. Comprado por Titular*/
	
		PRINT 'Valida Producto de Venta Titular: ' + @ValidarProdVta

		IF(@ValidarProdVta <> '')
		BEGIN
			SET @Producto_Descripcion_Resumida = (SELECT ISNULL(Descripcion_Resumida, Id_Producto) FROM Productos WHERE Id_Producto = @ValidarProdVta)
			PRINT 'Producto de Venta: ' + @Producto_Descripcion_Resumida
	
			EXEC CP_SCA_RegistrarAcceso_Rta 1, @Producto_Descripcion_Resumida, 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
			RETURN
		END
	END
END
/* FIN Habilita por Producto de Comprado por Titular */


/* Habilita por Evento */
IF(@Flag_Evento IN (1))
BEGIN
	--Agregado 29/06/2018
	SET @ValidarEvento = (dbo.CF_SCA_ValidarEvento(@Id_Cliente, @pId_Acceso, @pFecha))
	PRINT 'Tipo de Habilitacion Evento: ' + CONVERT(VARCHAR(10), @ValidarEvento)

	IF(@ValidarEvento <> 0)
	BEGIN
		SET @Id_CD_Motivo = 208 /*Habilit. por Evento*/
	
		SET @Clientes_Tipos_Habil_Evento = (SELECT RTRIM(LTRIM(Descripcion)) FROM Prod_Listas_Precios WHERE Id_Lista_Precio = @ValidarEvento)
		PRINT 'Tipo de Habilitacion Evento: ' + @Clientes_Tipos_Habil_Descripcion

		EXEC CP_SCA_RegistrarAcceso_Rta 1, @Clientes_Tipos_Habil_Evento, 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Habilita por Evento */


/* Habilita por Tipo de Cliente y por Horario */
IF(@Flag_Evento IN (0))
BEGIN
	SET @ValidarTipo = (dbo.CF_SCA_ValidarCategHorario(@Id_Cliente, @pId_Acceso, @pFecha))
	PRINT 'Tipo de Cliente de Habilitacion: ' + CONVERT(VARCHAR(10), @ValidarTipo)

	IF(@ValidarTipo <> 0)
	BEGIN
		SET @Id_CD_Motivo = 209 /*Habilit. por Categoria por horario*/
	
		SET @Clientes_Tipos_Habil_Descripcion = (SELECT RTRIM(LTRIM(CT.Descripcion)) FROM Clientes_Tipos CT WHERE Id_Tipo_Cli = @ValidarTipo)
		PRINT 'Tipo de Cliente de Habilitacion: ' + @Clientes_Tipos_Habil_Descripcion

		EXEC CP_SCA_RegistrarAcceso_Rta 1, @Clientes_Tipos_Habil_Descripcion, 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Habilita por Tipo de Cliente y por Horario */


/* Habilita por Producto Comprado y por Horario */
IF(@Flag_Evento IN (0))
BEGIN
	EXEC dbo.[CP_SCA_ValidarProducVta] @Id_Cliente, @pId_Acceso, @pFecha,0,1, @Id_Producto = @ValidarProdVta  OUTPUT

	PRINT 'Valida Producto de Venta: ' + @ValidarProdVta

	IF(@ValidarProdVta <> '')
	BEGIN
		SET @Id_CD_Motivo = 210 /*Habilit. por Produc. Comprado por horario*/
	
		SET @Producto_Descripcion_Resumida = (SELECT ISNULL(Descripcion_Resumida, Id_Producto) FROM Productos WHERE Id_Producto = @ValidarProdVta)
		PRINT 'Producto de Venta: ' + @Producto_Descripcion_Resumida
	
		EXEC CP_SCA_RegistrarAcceso_Rta 1, @Producto_Descripcion_Resumida, 'OBSER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso
		RETURN
	END
END
/* FIN Habilita por Producto Comprado y por Horario */


/* Rechazo si no cumple con ninguna de las habilitaciones previas */

SET @Id_CD_Motivo = 112 /*No cumple ninguna condicion habilitante*/
EXEC CP_SCA_RegistrarAcceso_Rta 0, '', 'ADVER', @Foto, @Foto_Bin, @Id_Cliente, @Id_Cliente_Ref, @pTipoAcceso, @pTag, @pFecha, @pId_Controlador, @pId_Acceso, @Id_CD_Motivo, @pFlag_GrabaRegistro, @pFlag_Permite_Paso

PRINT 'FIN del Proceso: CP_SCA_RegistrarAcceso'
RETURN

END

/*
EXEC dbo.CP_SCA_RegistrarAcceso	1,							--@pId_Controlador: Id_ Molinete
								'S',						--@pTipoAcceso: E: Entrada / S:Salida
								'2020-08-18T12:16:00',		--@pFecha: Fecha a comparar
								'19000101',					--@pFechaEvento: Fecha del Evento a comparar. Si no es un evento ingresar 19000101
								'0025545736',				--@pTag: Credencial MiFare / Wiegand
								0,							--@pDoc: Documento
								'',							--@pHue: Huella Dactilar
								'',							--@pCba: Codigo de Barra
								'',							--@pDma: Data Matrix
								1,							--@pFlag_GrabaRegistro(NULL): 23/09/2019. 1(default): Graba Registro. 0: No graba el registro
								0,							--@pFlag_Permite_Paso(NULL):  05/02/2020. 1: Si el resultado es habilitado permite que la persona pase 1 vez mas la proxima vez
								0							--@pFlag_Generacion_LB(NULL): 02/11/2020. 1: Si la llamada la esta haciendo para generar Listas Blancas, en esos casos hay validaciones que no hace como Validacion de Turnos

*/
GO

CREATE PROCEDURE [dbo].[z_CP_SCA_ValidarProducVta_20240115] @pId_Cliente		INT, 
												@pId_Acceso			SMALLINT, 
												@pFecha				DATETIME, 
												@pId_Cliente_Ref	INT, 
												@pHorario			TINYINT, 
												@Id_Producto		VARCHAR(14) OUTPUT
AS
BEGIN
DECLARE @Flag_PermiteProdPorPed	INT
DECLARE @Est_Pedido_Habili		VARCHAR(8000)
DECLARE @SqlStr					NVARCHAR(MAX)
DECLARE @SqlStrWhereEsp			NVARCHAR(MAX)
DECLARE @SqlStrSelect			NVARCHAR(MAX)
DECLARE @SqlStrWhere			NVARCHAR(MAX)
DECLARE @Parametros				NVARCHAR(100)
DECLARE @DiaActual				TINYINT

SET @DiaActual = DATEPART(DW,@pFecha)
IF (@@DATEFIRST = 7)
BEGIN
   SET @DiaActual = @DiaActual - 1
END

IF (@DiaActual = 7) 
BEGIN
	SET @DiaActual = 0
END

SET @Parametros = N'@Id_ProductoOUT VARCHAR(14) OUTPUT'; 

SET @Id_Producto	= ''

SET @Flag_PermiteProdPorPed = (dbo.CF_xParam('SCA_Perm_ProdXPed'))
SET @Est_Pedido_Habili		= RTRIM(LTRIM((dbo.CF_xParam('SCA_Est_Ped_Habil'))))

IF(ISNULL(@pId_Cliente_Ref,0) <> 0)
BEGIN
   SET @pId_Cliente = @pId_Cliente_Ref
END

SET @SqlStrSelect = 'SELECT @Id_ProductoOUT = ISNULL(MAX(CI.Id_Producto),'''')'

IF(ISNULL(@pHorario,0) = 0)
BEGIN
   SET @SqlStrSelect = RTRIM(LTRIM(@SqlStrSelect)) + CHAR(13) + 
					   ' FROM Cbtes_Items CI ' + CHAR(13) +
					   ' LEFT JOIN Cbtes CB ON CI.Id_Trans = CB.Id_Trans ' + CHAR(13) +
					   ' LEFT JOIN Cbtes_Tipos CT ON CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte ' + CHAR(13) +
					   ' LEFT JOIN CD_Accesos_Prod CA ON CI.Id_Producto = CA.Id_Producto ' + CHAR(13) +
					   ' LEFT JOIN Productos PR ON CI.Id_Producto = PR.Id_Producto ' 
END
ELSE
BEGIN
   SET @SqlStrSelect = RTRIM(LTRIM(@SqlStrSelect)) + CHAR(13) + 
					   ' FROM Cbtes_Items CI ' + CHAR(13) +
					   ' LEFT JOIN Cbtes CB ON CI.Id_Trans = CB.Id_Trans ' + CHAR(13) +
					   ' LEFT JOIN Cbtes_Tipos CT ON CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte ' + CHAR(13) +
					   ' LEFT JOIN CD_Accesos_Horarios CA ON CI.Id_Producto = CA.Id_Producto ' + CHAR(13) +
					   ' LEFT JOIN Productos PR ON CA.Id_Producto = PR.Id_Producto ' 
END


SET @SqlStrWhere =	' WHERE' + CHAR(13) + 
					' CA.Id_Acceso = '+ CAST(@pId_Acceso AS VARCHAR(5)) + CHAR(13) +
					' AND CI.Id_Cliente = '+ CAST(@pId_Cliente AS VARCHAR(10)) 

IF @Flag_PermiteProdPorPed = 0                              ----incluismo pedidos o no
   SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
					' AND ((CT.Compromete_Factura = 1 AND CB.Id_Estado_Cbte = 4)' + CHAR(13) + 
					' OR (CT.Compromete_Factura = 1 AND CB.Id_Estado_Cbte = 2)' + CHAR(13) + 
					' OR (CB.Id_Estado_Cbte = 1 AND CI.Imp_Final = 0))' --+ CHAR(13) +
					--' AND dbo.CF_NC_A_FC(CB.Id_Trans) = 0'
ELSE
   SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
					' AND ((CT.Compromete_Factura = 1 AND CB.Id_Estado_Cbte = 4)' + CHAR(13) +
					' OR (CT.Compromete_Factura = 1 AND CB.Id_Estado_Cbte = 2)' + CHAR(13) +
					' OR (CT.Compromete_Factura = 1 AND CB.Id_Estado_Cbte = 1 AND CI.Imp_Final = 0)' + CHAR(13) +
					' OR (CT.Compromete_Pedido = 1 AND CB.Id_Estado_Cbte IN (' + @Est_Pedido_Habili + ')))'--+ CHAR(13) +
					--' AND dbo.CF_NC_A_FC(CB.Id_Trans) = 0'

IF(ISNULL(@pHorario,0) = 0)
BEGIN
	IF(ISNULL(@pId_Cliente_Ref,0) = 0)
		SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
						' AND ISNULL(CA.Valida_En_Titular,0) IN (1,0)'
	ELSE
		SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
						' AND CA.Valida_En_Titular = 1'
END

IF (ISNULL(@pHorario,0) = 0)
BEGIN
	SET @SqlStrWhere =	RTRIM(LTRIM(@SqlStrWhere)) + CHAR(13) + 
						' AND ISNULL(CA.Flag_Consumible,0) = 0'
END

SET @SqlStr = RTRIM(LTRIM(@SqlStrSelect)) + CHAR(13) + RTRIM(LTRIM(@SqlStrWhere))

/*-----------------------------------------------------------------------------PRODUCTOS QUE NO VERIFICAN NI MES, NI PERIODO*/
SET @SqlStrWhereEsp =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
						' AND ISNULL(PR.Flag_Mes, 0) = 0 ' + CHAR(13) +  
						' AND ISNULL(PR.Flag_Periodo, 0) = 0 '

IF (ISNULL(@pHorario,0)<>0)
	SET @SqlStrWhereEsp = RTRIM(LTRIM(@SqlStrWhereEsp)) + CHAR(13) + 
						 ' AND CA.Dia = ' + CAST(@DiaActual AS VARCHAR(1)) + CHAR(13) +
						 ' AND ((CA.Hora_Desde IS NULL AND CA.Hora_Hasta IS NULL) OR ( '''+ CONVERT(VARCHAR(8),@pFecha,108) +''' BETWEEN CAST(CA.Hora_Desde AS TIME) AND CAST(CA.Hora_Hasta AS TIME)))'
                       
PRINT @SqlStrWhereEsp
EXECUTE sp_executesql @SqlStrWhereEsp, @Parametros, @Id_ProductoOUT = @Id_Producto OUTPUT;
IF (@Id_Producto <> '')
   RETURN

/*--------------------------------------------------------------------------------------PRODUCTOS QUE VERIFICAN MES*/
SET @SqlStrWhereEsp =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
						' AND PR.Flag_Mes = 1'

IF (ISNULL(@pHorario,0)=0)
	SET @SqlStrWhereEsp = RTRIM(LTRIM(@SqlStrWhereEsp)) + CHAR(13) + 
						' AND dbo.SF_EOMONTH(CI.Fecha_QA) + CA.Dias_Gracia > ('''+ CONVERT(VARCHAR(8),@pFecha - 1,112) +''')'
ELSE
	SET @SqlStrWhereEsp = RTRIM(LTRIM(@SqlStrWhereEsp)) + CHAR(13) +
                         ' AND dbo.SF_EOMONTH(CI.Fecha_QA) > ('''+ CONVERT(VARCHAR(8),@pFecha - 1,112) +''')' + CHAR(13) +
                         ' AND CA.Dia = ' + CAST(@DiaActual AS VARCHAR(1)) + CHAR(13) +
						 ' AND ((CA.Hora_Desde IS NULL AND CA.Hora_Hasta IS NULL) OR ( '''+ CONVERT(VARCHAR(8),@pFecha,108) +''' BETWEEN CAST(CA.Hora_Desde AS TIME) AND CAST(CA.Hora_Hasta AS TIME)))'

PRINT @SqlStrWhereEsp
EXECUTE sp_executesql @SqlStrWhereEsp, @Parametros, @Id_ProductoOUT = @Id_Producto OUTPUT;
IF @Id_Producto <> ''
   RETURN


/*--------------------------------------------------------------------------------------PRODUCTOS QUE VERIFICAN PERIODO*/
SET @SqlStrWhereEsp =	RTRIM(LTRIM(@SqlStr)) + CHAR(13) + 
						' AND PR.Flag_Periodo = 1 '
						
IF (ISNULL(@pHorario,0)=0)
	SET @SqlStrWhereEsp =	RTRIM(LTRIM(@SqlStrWhereEsp)) + CHAR(13) + 
							' AND CI.Fecha_QA < ('''+ CONVERT(VARCHAR(8),@pFecha + 1,112) +''')' + CHAR(13) + 
							' AND CONVERT(VARCHAR(8),DATEADD(DAY,CA.Dias_Gracia,CI.Fecha_Venc),112) > ('''+ CONVERT(VARCHAR(8),@pFecha - 1,112) +''')'
ELSE
	SET @SqlStrWhereEsp = RTRIM(LTRIM(@SqlStrWhereEsp)) + CHAR(13) +
                         ' AND CI.Fecha_QA < ('''+ CONVERT(VARCHAR(8),@pFecha + 1,112) +''')' + CHAR(13) +
                         ' AND CI.Fecha_Venc > ('''+ CONVERT(VARCHAR(8),@pFecha - 1,112) +''')' + CHAR(13) +
                         ' AND CA.Dia = ' + CAST(@DiaActual AS VARCHAR(1)) + CHAR(13) +
						 ' AND ((CA.Hora_Desde IS NULL AND CA.Hora_Hasta IS NULL) OR ( '''+ CONVERT(VARCHAR(8),@pFecha,108) +''' BETWEEN CAST(CA.Hora_Desde AS TIME) AND CAST(CA.Hora_Hasta AS TIME)))'
                         

PRINT @SqlStrWhereEsp
EXECUTE sp_executesql @SqlStrWhereEsp, @Parametros, @Id_ProductoOUT = @Id_Producto OUTPUT;

RETURN
END
GO

CREATE FUNCTION [dbo].[z_Prueba_SF_Ult_Cuota_Paga](@pId_Cliente INT, @pFecha DATETIME) 
RETURNS DATETIME
AS
BEGIN
DECLARE @Fecha_UCP					DATETIME
DECLARE @Ult_Cuota_Paga				DATETIME
DECLARE @Ult_Cuota_Paga_Mes			DATETIME
DECLARE @Ult_Cuota_Paga_Periodo		DATETIME
DECLARE @Ult_Cuota_Impaga			DATETIME
DECLARE @Id_Tipo_Cli				SMALLINT
DECLARE @Fecha_Alta					DATETIME
DECLARE @Fam_CuotaSoc				INT
DECLARE @Fecha_Hasta				DATETIME
DECLARE @Id_Tipo_Con				SMALLINT

SET @Id_Tipo_Cli = (SELECT dbo.SF_Categ(@pId_Cliente, @pFecha))
SELECT TOP 1  @Fecha_Hasta = Fecha_Hasta , @Id_Tipo_Con = Id_Tipo_Con 
    FROM dbo.Contratos 
    WHERE Id_Cliente=@pId_Cliente 
    AND Id_Tipo_Con = 39 
    AND Activo = 1
    AND Fecha_Desde <= GETDATE()
    AND ISNULL(Fecha_Hasta,GETDATE()-1)>= GETDATE()
    ORDER BY Fecha_Hasta DESC   



IF(@Id_Tipo_Con = 39 )
BEGIN
	/*
	* Si el contrato es Promo Verano
	*/
	SET @Fecha_UCP = @Fecha_Hasta
	RETURN @Fecha_UCP
END

IF(@Id_Tipo_Cli IN (10, 1018, 1103, 1111, 1112, 1113))
BEGIN
	/*
	* Categorias que no pagan:
	*
	* 10	ACCESO MASTER
	* 1018	INVITADOS
	* 1103	NO SOCIO
	* 1111	USUARIO PROMO VERANO MAYOR
	* 1112	USUARIO PROMO VERANO MENOR
	* 1113	VISITA
	*/
	SET @Fecha_UCP = '20500101'
	RETURN @Fecha_UCP
END

------------------------------------------------------------------------------------------------------------------------------------------------

/*IF(@Id_Tipo_Cli IN (NN))
BEGIN
	/*
	 * Categorias que no importa lo que haya pagado, no tiene que entrar
	 * NN XXXXXXXXXX
	 */
	SET @Fecha_UCP = '19000101'
	RETURN @Fecha_UCP
END*/

------------------------------------------------------------------------------------------------------------------------------------------------

SET @Fam_CuotaSoc = CAST( (dbo.CF_xParam('Fam_CuotasSoc')) AS INT)

-------------------------------------------------------------------------

IF(@Id_Tipo_Cli IN (1010,1012,1017))
BEGIN
	/*
	* Categorias que tienen CS Voluntaria: Ticket #22662
	*
	* 1010	VITALICIO + 71
	* 1012	USUARIO RCA
	* 1017	USUARIO +75
	*/
	
	
	SET @Ult_Cuota_Paga_Mes = (SELECT MAX(CI.Fecha_QA)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
							AND CI.Id_Producto = PR.Id_Producto
							AND CT.Compromete_Factura IN (1)
							AND (CB.Id_Estado_Cbte IN (2/*Completo*/))
							AND CB.Id_Trans NOT IN( SELECT Id_Trans FROM Cbtes_Items WHERE Id_Producto = 'CS' AND Imp_gravado = 0)
							AND PR.Id_Familia = @Fam_CuotaSoc
							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Mes, 0) = 1)

	SET @Ult_Cuota_Paga_Periodo =(SELECT MAX(CI.Fecha_Venc)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
							AND CI.Id_Producto = PR.Id_Producto
							AND CT.Compromete_Factura IN (1)
							AND (CB.Id_Estado_Cbte IN (2/*Completo*/))
							AND PR.Id_Familia = @Fam_CuotaSoc
							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Periodo, 0) = 1)
							
END
ELSE 
-------------------------------------------------------------------------
BEGIN					
SET @Ult_Cuota_Paga_Mes =	(SELECT MAX(CI.Fecha_QA)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
							AND CI.Id_Producto = PR.Id_Producto
							AND CT.Compromete_Factura IN (1)
							AND (CB.Id_Estado_Cbte IN (2/*Completo*/) OR (CB.Id_Estado_Cbte IN (1/*PENDIENTE*/) AND CI.Imp_Final = 0))
							AND PR.Id_Familia = @Fam_CuotaSoc
							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Mes, 0) = 1) 

SET @Ult_Cuota_Paga_Periodo =(SELECT MAX(CI.Fecha_Venc)
							FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
							WHERE
							CB.Id_Trans = CI.Id_Trans
							AND CB.Id_Tipo_Cbte = CT.Id_Tipo_Cbte
							AND CI.Id_Producto = PR.Id_Producto
							AND CT.Compromete_Factura IN (1)
							AND (CB.Id_Estado_Cbte IN (2/*Completo*/) OR (CB.Id_Estado_Cbte IN (1/*PENDIENTE*/) AND CI.Imp_Final = 0))
							AND PR.Id_Familia = @Fam_CuotaSoc
							AND ISNULL(PR.Vendible, 0) = 1
							AND CI.Id_Cliente = @pId_Cliente
							AND ISNULL(PR.Flag_Periodo, 0) = 1)

END					
							
IF(@Ult_Cuota_Paga_Periodo IS NOT NULL)
BEGIN
	SET @Ult_Cuota_Paga_Periodo = dbo.CF_FOMONTH(@Ult_Cuota_Paga_Periodo)
	
	IF(@Ult_Cuota_Paga_Mes IS NULL)
	BEGIN
		SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Periodo
	END
	ELSE
	BEGIN
		IF(@Ult_Cuota_Paga_Periodo > @Ult_Cuota_Paga_Mes)
		BEGIN
			SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Periodo
		END
		ELSE
		BEGIN
			SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Mes
		END
	END
END
ELSE
BEGIN
	SET @Ult_Cuota_Paga = @Ult_Cuota_Paga_Mes
END

------------------------------------------------------------------------------------------------------------------------------------------------

--SET @Ult_Cuota_Impaga = (SELECT MIN(CI.Fecha_QA)
--						FROM Cbtes CB, Cbtes_Items CI, Cbtes_Tipos CT, Productos PR
--						WHERE 
--						CB.Id_Trans = CI.Id_Trans 						
--						AND CT.Id_Tipo_Cbte = CB.Id_Tipo_Cbte
--						AND CI.Id_Producto = PR.Id_Producto
--						AND CT.Compromete_Factura IN (1)
--						AND CB.Id_Estado_Cbte IN (1/*Pendiente*/, 4/*Parcial*/)
--						AND PR.Id_Familia = @Fam_CuotaSoc
--						AND CI.Id_Cliente = @pId_Cliente)	


IF((@Ult_Cuota_Paga IS NOT NULL) AND (@Ult_Cuota_Impaga IS NOT NULL))
BEGIN
	IF (@Ult_Cuota_Impaga < @Ult_Cuota_Paga)
	BEGIN
		SET @Fecha_UCP = DATEADD(MM, -1, @Ult_Cuota_Impaga)
		RETURN @Fecha_UCP
	END
	ELSE
	BEGIN
		SET @Fecha_UCP = @Ult_Cuota_Paga
		RETURN @Fecha_UCP
	END
END


IF((@Ult_Cuota_Paga IS NULL) AND (@Ult_Cuota_Impaga IS NOT NULL))
BEGIN
	SET @Fecha_UCP = DATEADD(MM, -1, @Ult_Cuota_Impaga)
	RETURN @Fecha_UCP
END

IF((@Ult_Cuota_Paga IS NOT NULL) AND (@Ult_Cuota_Impaga IS NULL))
BEGIN
	SET @Fecha_UCP = @Ult_Cuota_Paga
	RETURN @Fecha_UCP
END

--si las 2 son nulas----
SET @Fecha_Alta = (SELECT ISNULL(Fecha_Alta, '19000101') FROM Clientes WHERE Id_Cliente = @pId_Cliente)
/*Se hace la siguiente linea porque tienen SQL 2008 o superior*/
SET @Fecha_Alta = CONVERT(DATE,@Fecha_Alta) 

RETURN ISNULL(@Fecha_UCP, DATEADD(MM, -1, @Fecha_Alta))
END
GO

CREATE FUNCTION [dbo].[z_SF_APRUEBA_CS_Precio_Persona](@Cli INT, @Fecha DATETIME) 
RETURNS DECIMAL(12,2)
AS
BEGIN
/*Declaracion de Variables*/
DECLARE @Retorno				DECIMAL(12,2)
DECLARE @Prod					VARCHAR(14)
DECLARE @Fecha_Nac				DATETIME
DECLARE @Edad					INT
DECLARE @Id_Lista_Precio		INT
DECLARE @Titular				INT
DECLARE @Id_Cli_Temp			INT
DECLARE @Cant_Grupo				INT
DECLARE @Id_Contrato_Desc_CS	INT
DECLARE @Porc_Bonif_Cont_DescCS	DECIMAL(5,2)
DECLARE @Imp_Bonif_Cont_DescCS	DECIMAL(12,2)
DECLARE @Id_Contrato_Licencia	INT
DECLARE @Porc_Bonif_Cont_Lic	DECIMAL(5,2)
DECLARE @Id_Contrato_Beca		INT
DECLARE @Porc_Bonif_Cont_Beca	DECIMAL(5,2)
DECLARE @Imp_Bonif_Cont_Beca	DECIMAL(12,2)
-- Se agrega por unica vez 29/04/2020
DECLARE @flag_Existe_contrato_pandemia	TINYINT


SET @Cant_Grupo = 0

/*Busco Titular del Grupo Familiar*/
SET @Titular = ISNULL((SELECT Id_Cliente_Ref FROM Clientes WHERE Id_Cliente = @Cli), 0)

IF @Titular = 0
BEGIN
   SET @Titular = @cli
END

/*Busco Lista Precio del Titular*/
SET @Id_Lista_Precio = ISNULL((SELECT Id_Lista_Precio from Clientes where Id_Cliente = @Cli), 0)

IF @Id_Lista_Precio = 0
BEGIN
   SET @Id_Lista_Precio = 1
END


/*Busco Producto correspondiente según Categoria*/
SET @Prod = ISNULL(dbo.SF_Prod(@Cli, @Fecha),'')

IF @Prod = ''
BEGIN
   RETURN 0
END

/*Busco si tiene un Contrato Activo de DESCUENTOS EN CUOTA SOCIAL con descuento*/  
SET @Id_Contrato_Desc_CS		= ISNULL((SELECT MAX(Id_Contrato) FROM Contratos WHERE Id_Cliente = @Cli AND Id_Tipo_Con = 10 AND Fecha_Desde <= @Fecha AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL)),0)

/* Busco si tiene contrato Activo de BECA  */
 /* 4- BECA 
   14- Descuento vitaclicio res 28 
   15- BECA DEPORTISTA 
   16- BECA EXCELENCIA DEPORTIVA)
   17- BECA OLIMPICOS
   34- DESCUENTO POR DISCAPACIDAD*/ -- Se agrega por solicitud en el ticket 18024 para descuento en CS
 
SET @Id_Contrato_Beca = ISNULL((SELECT MAX(Id_Contrato) FROM Contratos WHERE Id_Cliente = @Cli AND Id_Tipo_Con  in (4, 14, 15, 16, 17, 34)  AND Fecha_Desde <= @Fecha AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL)),0)

/*Busco si tiene un Contrato Activo de LICENCIAS*/  
SET @Id_Contrato_Licencia = ISNULL((SELECT MAX(Id_Contrato) FROM Contratos WHERE Id_Cliente = @Cli AND Id_Tipo_Con = 11 AND Fecha_Desde <= @Fecha AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL)),0)

/*Cálculo de precio sin descuento*/  
SET @Retorno = ISNULL((	SELECT Precio FROM Prod_Listas_Precios_Items 
						WHERE 
						Id_Producto = @Prod 
						AND Id_Lista_Precio = @Id_Lista_Precio)
					,0) 


SET @Retorno = (@Retorno * (1 - (dbo.SF_Desc_GF(@Cli,GETDATE())/100)))

/*Si tiene un contrato de LICENCIA se le modifica el precio*/
IF(@Id_Contrato_Licencia <> 0)
BEGIN
	SET @Porc_Bonif_Cont_Lic = ISNULL((SELECT Porc_Bonif FROM Contratos WHERE Id_Contrato = @Id_Contrato_Licencia),0)
	SET @Retorno = (@Retorno * (100-@Porc_Bonif_Cont_Lic))/100
END

/*Si tiene un contrato de DESCUENTOS EN CUOTA SOCIAL se le modifica el precio*/

IF (@Id_Contrato_Desc_CS <> 0)
BEGIN

	SET @Porc_Bonif_Cont_DescCS = ISNULL((SELECT SUM(Porc_Bonif) FROM Contratos WHERE Id_Cliente = @Cli AND Id_Tipo_Con = 10 AND Fecha_Desde <= @Fecha AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL) AND ACTIVO=1),0)
	SET @Imp_Bonif_Cont_DescCS	= ISNULL((SELECT SUM(Imp_Bonif) FROM Contratos WHERE Id_Cliente = @Cli AND Id_Tipo_Con = 10 AND Fecha_Desde <= @Fecha AND (Fecha_Hasta >= @Fecha OR Fecha_Hasta IS NULL) AND ACTIVO=1),0)
	
	/*Se modifica esta parte del codigo por pedido en el ticket #20194
	SET @Porc_Bonif_Cont_DescCS = ISNULL((SELECT Porc_Bonif FROM Contratos WHERE Id_Contrato = @Id_Contrato_Desc_CS),0)
	SET @Imp_Bonif_Cont_DescCS	= ISNULL((SELECT Imp_Bonif FROM Contratos WHERE Id_Contrato = @Id_Contrato_Desc_CS),0)
	*/
	
	IF ((@Porc_Bonif_Cont_DescCS <> 0) AND (@Imp_Bonif_Cont_DescCS <> 0))
	BEGIN
		/*Si le pusieron Porcentaje de Descuento e importe de Descuento, prevalece el Porcentaje*/
		SET @Imp_Bonif_Cont_DescCS = 0
	END

	IF @Porc_Bonif_Cont_DescCS <> 0
	BEGIN
		SET @Retorno = (@Retorno * (100-@Porc_Bonif_Cont_DescCS))/100		
	END
	
	IF @Imp_Bonif_Cont_DescCS <> 0
	BEGIN
		IF @Imp_Bonif_Cont_DescCS < @Retorno
		BEGIN
			SET @Retorno = @Retorno - @Imp_Bonif_Cont_DescCS
		END
		ELSE
		BEGIN
			SET @Retorno = 0
		END
	END	
END


/*Si tiene un contrato de DESCUENTOS EN BECA se le modifica el precio*/
IF (@Id_Contrato_Beca <> 0)
BEGIN
	SET @Porc_Bonif_Cont_Beca = ISNULL((SELECT Porc_Bonif FROM Contratos WHERE Id_Contrato = @Id_Contrato_Beca),0)
	SET @Imp_Bonif_Cont_Beca	= ISNULL((SELECT Imp_Bonif FROM Contratos WHERE Id_Contrato = @Id_Contrato_Beca),0)

	IF ((@Porc_Bonif_Cont_Beca <> 0) AND (@Imp_Bonif_Cont_Beca <> 0))
	BEGIN
		/*Si le pusieron Porcentaje de Descuento e importe de Descuento, prevalece el Porcentaje*/
		SET @Imp_Bonif_Cont_Beca = 0
	END

	IF @Porc_Bonif_Cont_Beca <> 0
	BEGIN
		SET @Retorno = (@Retorno * (100-@Porc_Bonif_Cont_Beca))/100		
	END
	
	IF @Imp_Bonif_Cont_Beca <> 0
	BEGIN
		IF @Imp_Bonif_Cont_Beca < @Retorno
		BEGIN
			SET @Retorno = @Retorno - @Imp_Bonif_Cont_Beca
		END
		ELSE
		BEGIN
			SET @Retorno = 0
		END
	END	
END
/*Se agrega esta linea por pedido de contratos de descuentos en ticket 19635*/
SET @flag_Existe_contrato_pandemia = ISNULL((SELECT 1 FROM CONTRATOS WHERE Id_Tipo_CON = 35 /*Contrato Pandemia*/ AND Id_Cliente = @Cli AND CONVERT(DATE,Fecha_Desde)<= CONVERT(DATE,@Fecha) AND (CONVERT(DATE,Fecha_HASTA)>= CONVERT(DATE,@Fecha) OR FECHA_HASTA IS NULL)),0)
IF(@flag_Existe_contrato_pandemia = 1)
BEGIN
	SET @Retorno = @Retorno * 0.9
END
/*Si la suma de los desc es negativo*/
IF(@Retorno < 0)  SET @Retorno = 0

RETURN ISNULL(@Retorno,3)
END
GO

CREATE PROCEDURE [dbo].[zsp_generar_asiento_FacturaBk20250314] @ID_TRANS INT
       AS 



---          execute SP_generar_stock @ID_TRANS
          IF ((SELECT Id_Estado_Cbte FROM CBTES WHERE ID_TRANS = @ID_TRANS) = 3) 
		      RETURN
          IF ((SELECT Id_Cond_Pago FROM CBTES WHERE ID_TRANS = @ID_TRANS) = 1) 
		      RETURN
	      BEGIN TRAN

   	            DECLARE @ID_cliente INTEGER
				DECLARE @ALIAS INTEGER
				Declare @id_producto varchar(15)
				Declare @Importe decimal(12,2)
				Declare @DEBE decimal(12,2)	
				Declare @HABER decimal(12,2)
                declare @id_cta_contable integer
	        	declare @fecha_mov datetime
			  	declare @FECHA_QA datetime
                declare @id_CENTRO_COSTO varchar(5)
                declare @ITEM INTEGER
				Declare @Imp_Gravado decimal(12,2)
				Declare @Imp_Iva decimal(12,2)

    	SET @fecha_mov = (SELECT fecha from cbtes where id_trans = @ID_TRANS) 

        ----------------------------- Primero los insert ----------------------------------

        SELECT * INTO #CBTES_CTAS_CONTABLES_aux_sp FROM CBTES_CTAS_CONTABLES WHERE ID_TRANS = @ID_TRANS
		DELETE #CBTES_CTAS_CONTABLES_aux_sp

        Declare MicursorAsiento cursor for select id_producto,ID_CLIENTE,FECHA_QA,Imp_Final,Imp_Gravado,Imp_Iva from CBTES_ITEMS WHERE ID_TRANS = @ID_TRANS and Imp_Final <> 0

               Open MicursorAsiento
                    Fetch next from MicursorAsiento into @id_producto,@Id_Cliente,@FECHA_QA,@Importe,@Imp_Gravado,@Imp_Iva
                    While @@fetch_status = 0 
                    begin
				        -- Genero Asiento en el Debe
						SET @Alias = (SELECT isnull(Id_Alias_Cta_Deudores,0) from Productos where id_producto = @ID_Producto) 
						If @Alias = 0
						   SET @Alias = (SELECT isnull(Id_Alias_Cta_Cont_Venta,0) from Clientes where Id_Cliente = @ID_CLIENTE)

                        set @id_cta_contable =  DBO.SF_Cta_Cont(@Alias,@fecha_mov) 
						    
                        INSERT into #CBTES_CTAS_CONTABLES_aux_sp (
								Id_Trans,
								Item,
								Id_Cta_Contable,
								Fecha,                     
								Debe,
								Haber,
								Alias,
								Id_Centro_Costo)
								VALUES (@ID_TRANS,1,@id_cta_contable,@fecha_mov,@importe,0,@ALIAS,'')						    
                                  
						-- Genero Aiento en el Haber
						IF @ID_PRODUCTO = 'CS'
						   BEGIN
						     SET @Id_producto = DBO.SF_Prod(@id_cliente,@fecha_mov) 
					         IF @FECHA_QA <= @fecha_mov
					              SET @Alias = (SELECT isnull(Id_Alias_Cta_Cont,0) from Productos where Id_producto = @ID_PRODUCTO) 
						      ELSE
					              SET @Alias = (SELECT isnull(Id_Alias_Cta_Vtas_Anticip,0) from Productos where Id_producto = @ID_PRODUCTO) 
                           END
                          ELSE
						   BEGIN 
							  IF @FECHA_QA <= @fecha_mov
							      BEGIN
					    	      SET @Alias = (SELECT isnull(Id_Alias_Cta_Cont,0) from Productos where id_producto = @ID_Producto)
								  PRINT(@Alias)
								  END
								ELSE
								  BEGIN
							        SET @Alias = (SELECT isnull(Id_Alias_Cta_Vtas_Anticip,0) from Productos where id_producto = @ID_Producto)
                                    IF @Alias = 0
							           SET @Alias = (SELECT isnull(Id_Alias_Cta_Cont,0) from Productos where id_producto = @ID_Producto)
                                  END
					       END
                           set @id_cta_contable =  DBO.SF_Cta_Cont(@Alias,@fecha_mov)
          		  	       SET @id_CENTRO_COSTO = (SELECT ID_CENTRO_COSTO from PRODUCTOS where id_producto = @ID_PRODUCTO) 
          		  	        
	                       IF @imp_Gravado <> 0
						      BEGIN					    
								   INSERT into #CBTES_CTAS_CONTABLES_aux_sp (
										Id_Trans,
										Item,
										Id_Cta_Contable,
										Fecha,                     
										Debe,
										Haber,
										Alias,
										Id_Centro_Costo)
										VALUES (@ID_TRANS,1,@id_cta_contable,@fecha_mov,0,@imp_Gravado,@ALIAS,@id_CENTRO_COSTO)
							  END			
                           IF @imp_Iva <> 0
						      BEGIN
							    Set @Alias =  (select Valor_Integer from xParametros where setDatos= 1 and idParametro ='Iva_Debito_Fiscal')
                                set @id_cta_contable =  DBO.SF_Cta_Cont(@Alias,@fecha_mov)
          		  	            SET @id_CENTRO_COSTO = '' 
						    
								   INSERT into #CBTES_CTAS_CONTABLES_aux_sp (
										Id_Trans,
										Item,
										Id_Cta_Contable,
										Fecha,                     
										Debe,
										Haber,
										Alias,
										Id_Centro_Costo)
										VALUES (@ID_TRANS,1,@id_cta_contable,@fecha_mov,0,@imp_Iva,@ALIAS,@id_CENTRO_COSTO)	
						      END
													    
                          Fetch next from MicursorAsiento into @id_producto,@Id_Cliente,@FECHA_QA,@Importe,@Imp_Gravado,@Imp_Iva
                    End       
               Close MicursorAsiento
               Deallocate MicursorAsiento
         
        SELECT ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO,SUM(DEBE) DEBE,SUM(HABER) HABER INTO #CBTES_CTAS_CONTABLES_RESUMEN
                       FROM #CBTES_CTAS_CONTABLES_aux_sp GROUP BY ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO 
        DELETE #CBTES_CTAS_CONTABLES_aux_sp

        SET @ITEM = 0
        Declare MicursorAsientoResumen cursor for 
        select ID_TRANS,ID_CTA_CONTABLE,FECHA,ALIAS,ID_CENTRO_COSTO,DEBE,HABER from  #CBTES_CTAS_CONTABLES_RESUMEN WHERE ID_TRANS = @ID_TRANS ORDER BY HABER

               Open MicursorAsientoResumen
                    Fetch next from MicursorAsientoResumen into @ID_TRANS,@ID_CTA_CONTABLE,@fecha_mov,@ALIAS,@ID_CENTRO_COSTO,@DEBE,@HABER
                    While @@fetch_status = 0 
                    begin	
					      SET @ITEM = @ITEM + 1
                          INSERT into #CBTES_CTAS_CONTABLES_aux_sp (
								Id_Trans,
								Item,
								Id_Cta_Contable,
								Fecha,                     
								Debe,
								Haber,
								Alias,
								Id_Centro_Costo)
								VALUES (@ID_TRANS,@ITEM,@id_cta_contable,@fecha_mov,@debe,@haber,@ALIAS,@id_CENTRO_COSTO)						    
                
                         Fetch next from MicursorAsientoResumen into @ID_TRANS,@ID_CTA_CONTABLE,@fecha_mov,@ALIAS,@ID_CENTRO_COSTO,@DEBE,@HABER
                    End       

			   DELETE CBTES_CTAS_CONTABLES WHERE ID_TRANS = @ID_TRANS

			   INSERT INTO CBTES_CTAS_CONTABLES 
			          SELECT * FROM #CBTES_CTAS_CONTABLES_aux_sp

               Close MicursorAsientoResumen
               Deallocate MicursorAsientoResumen

         DROP TABLE #CBTES_CTAS_CONTABLES_aux_sp
		 DROP TABLE #CBTES_CTAS_CONTABLES_RESUMEN

         IF (@@ERROR = 0)
		     COMMIT TRAN
	     ELSE
		     ROLLBACK

 --select 0
 RETURN 0

----exec sp_generar_asiento_Factura 103855



---select * from cbtes_ctas_contables where id_trans = 158723
GO

